INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1, '导引', '和岘', '气和玉烛，睿化著鸿明。\n缇管一阳生。\n郊盛礼燔柴毕，旋轸凤凰城。\n森罗仪卫振华缨。\n载路溢欢声。\n皇图大业超前古，垂象泰阶平。\n岁时丰衍，九土乐升平。\n睹寰海澄清。\n道高尧舜垂衣治，日月并文明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2, '六州', '和岘', '严夜警，铜莲漏迟迟。\n清禁肃，森陛戟，羽卫俨皇闱。\n角声励，钲鼓攸宜。\n金管成雅奏，逐吹逶迤。\n荐苍璧，郊祀神祗。\n属景运纯禧。\n京坻丰衍，群材乐育，诸侯述职，盛德服蛮夷。\n殊祥萃，九苞丹凤来仪。\n膏露降，和气洽，三秀焕灵芝。\n鸿猷播，史册相辉。\n张四维。\n卜世永固丕基。\n敷玄化，荡荡无为。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3, '十二时・忆少年', '和岘', '承宝运，驯致隆平。\n鸿庆被寰瀛。\n时清俗阜，治定功成。\n遐迩咏由庚。\n严郊祀，文物声明。\n会天正、星拱奏严更。\n布羽仪簪缨。\n宸心虔洁，明德播惟馨。\n动苍冥。\n神降享精诚。\n燔柴半，万乘移天仗，肃銮辂旋衡。\n千官云拥，群后葵倾。\n玉帛旅明庭。\n韶荐，金奏谐声。\n集休亨。\n皇泽浃黎庶，普率洽恩荣。\n仰钦元后，睿圣贯三灵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4, '点绛唇', '王禹', '雨恨云愁，江南依旧称佳丽。\n水村渔市。\n一缕孤烟细。\n天际征鸿，遥认行如缀。\n平生事。\n此时凝睇。\n谁会凭阑意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5, '越江吟', '苏易简', '神仙神仙瑶池宴。\n片片。\n碧桃零落春风晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6, '甘草子', '寇准', '春早。\n柳丝无力，低拂清门道。\n暖日笼啼鸟。\n初坼桃花小。\n遥望碧天净如扫。\n曳一缕、轻烟缥缈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7, '踏莎行', '寇准', '春色将阑，莺声渐老。\n红英落尽青梅小。\n画堂人静雨，屏山半掩馀香袅。\n密约沈沈，离情杳杳。\n菱花尘满慵将照。\n倚楼无语欲销魂，长空黯淡连芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8, '阳关引', '寇准', '塞草烟光阔。\n渭水波声咽。\n春朝雨霁轻尘歇。\n征鞍发。\n指青青杨柳，又是轻攀折。\n动黯然、知有後会甚时节。\n更尽一杯酒，歌一阕。\n叹人生，最难欢聚易离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9, '点绛唇', '寇准', '水陌轻寒，社公雨足东风慢。\n定巢新燕。\n湿雨穿花转。\n象尺熏炉，拂晓停针线。\n愁蛾浅。\n飞红零乱。\n侧卧珠帘卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10, '江南春・秋风清', '寇准', '波渺渺，柳依依。\n孤村芳草远，斜日杏花飞。\n江南春尽离肠远，苹满汀洲人未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11, '夜度娘', '寇准', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12, '木兰花・玉楼春', '钱惟演', '城上风光莺语乱。\n城下烟波春拍岸。\n绿杨芳草几时休，泪眼愁肠先已断。\n情怀渐变成衰晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13, '玉楼春', '钱惟演', '锦箨参差朱槛曲。\n露濯文犀和粉绿。\n未容浓翠伴桃红，已许纤枝留凤宿。\n嫩似春荑明似玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14, '踏莎行', '陈尧佐', '二社良辰，千家庭院。\n翩翩又见新来燕。\n凤凰巢稳许为邻，潇湘烟暝来何晚。\n乱入红楼，低飞绿岸。\n画梁时拂歌尘散。\n为谁归去为谁来，主人恩重珠帘卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15, '酒泉子', '潘阆', '长忆钱塘，不是人寰是天上。\n万家掩映翠微间。\n处处水潺潺。\n异花四季当窗放。\n出入分明在屏障。\n别来隋柳几经秋。\n何日得重游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16, '酒泉子', '潘阆', '长忆钱塘，临水傍山三百寺。\n僧房携杖遍曾游。\n闲话觉忘忧。\n檀楼阁云霞畔。\n钟梵清宵彻天汉。\n别来遥礼祗焚香。\n便恐是西方。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17, '酒泉子', '潘阆', '长忆西湖，湖上春来无限景。\n吴姬个个是神仙。\n兢泛木兰船。\n楼台簇簇疑蓬岛。\n野人祗合其中老。\n别来已是二十年。\n东望眼将穿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18, '酒泉子', '潘阆', '长忆西湖，尽日凭阑楼上望。\n三三两两钓鱼舟。\n岛屿正清秋。\n笛声依约芦花里。\n白鸟成行忽惊起。\n别来闲整钓鱼竿。\n思入水云寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19, '酒泉子', '潘阆', '长忆孤山，山在湖心如黛簇。\n僧房四面向湖开。\n轻棹去还来。\n芰荷香喷连云阁。\n阁上清声檐下铎。\n别来尘土污人衣。\n空役梦魂飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20, '酒泉子', '潘阆', '长忆西山，灵隐寺前三竺後。\n冷泉亭上旧曾游。\n三伏似清秋。\n白猿时见攀高树。\n长啸一声何处去。\n别来几向画阑看。\n终是欠峰峦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21, '酒泉子', '潘阆', '长忆高峰，峰上塔高尘世外。\n昔年独上最高层。\n月出见觚。\n举头咫尺疑天汉。\n星斗分明在身畔。\n别来无翼可飞腾。\n何日得重登。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (22, '酒泉子', '潘阆', '长忆吴山，山上森森吴相庙。\n庙前江水怒为涛。\n千古恨犹高。\n寒鸦日暮鸣还聚。\n时有阴云笼殿宇。\n别来有负谒灵祠。\n遥奠酒盈卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (23, '酒泉子', '潘阆', '长忆龙山，日月宫中谁得到。\n宫中旦暮听潮声。\n台殿竹风清。\n门前岁岁生灵草。\n人采食之多不老。\n别来已白数茎头。\n早晚却重游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (24, '酒泉子', '潘阆', '长忆观潮，满郭人争江上望。\n来疑沧海尽成空。\n万面鼓声中。\n弄涛儿向涛头立。\n手把红旗旗不湿。\n别来几向梦中看。\n梦觉尚心寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (25, '扫市舞', '潘阆', '出砒霜，价钱可。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (26, '凤栖梧・蝶恋花', '丁谓', '十二层楼春色早。\n三殿笙歌，九陌风光好。\n堤柳岸花连复道。\n玉梯相对开蓬岛。\n莺啭乔林鱼在藻。\n太液微波，绿斗王孙草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (27, '凤栖梧・蝶恋花', '丁谓', '朱阙玉城通阆苑。\n月桂星榆，春色无深浅。\n潇瑟篌笙仙客宴。\n蟠桃花满蓬莱殿。\n九色明霞裁羽扇。\n云雾为车，鸾鹤骖雕辇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (28, '相思令・相思儿令', '林逋', '吴山青。\n越山青。\n两岸青山相对迎。\n争忍有离情。\n君泪盈。\n妾泪盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (29, '点绛唇', '林逋', '金谷年年，乱生春色谁为主。\n馀花落处。\n满地和烟雨。\n又是离歌，一阕长亭暮。\n王孙去。\n萋萋无数。\n南北东西路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (30, '霜天晓角', '林逋', '冰清霜洁。\n昨夜梅花发。\n甚处玉龙三弄，声摇动、枝头月。\n梦绝。\n金兽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (31, '瑞鹧鸪', '林逋', '众芳摇落独鲜妍。\n占尽风情向小园。\n疏影横斜水清浅，暗香浮动月黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (32, '少年游', '杨亿', '江南节物，水昏云淡，飞雪满前村。\n千寻翠岭，一枝芳艳，迢递寄归人。\n寿阳妆罢，冰姿玉态，的的写天真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (33, '生查子', '陈亚', '朝庭数擢贤，旋占凌霄路。\n自是郁陶人，险难无移处。\n也知没药疗饥寒，食薄何相误。\n大幅纸连粘，甘草归田赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (34, '生查子', '陈亚', '相思意已深，白纸书难足。\n字字苦参商，故要槟郎读。\n分明记得约当归，远至樱桃熟。\n何事菊花时，犹未回乡曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (35, '生查子', '陈亚', '小院雨馀凉，石竹风生砌。\n罢扇尽从容，半下纱厨睡。\n起来闲坐北亭中，滴尽真珠泪。\n为念婿辛勤，去折蟾宫桂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (36, '生查子', '陈亚', '浪荡去未来，踯躅花频换。\n可惜石榴裙，兰麝香销半。\n琵琶闲抱理相思，必拨朱弦断。\n拟续断朱弦，待这冤家看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (37, '喜迁莺', '夏竦', '霞散绮，月沈钩。\n帘卷未央楼。\n夜凉河汉截天流。\n宫阙锁清秋。\n瑶阶曙。\n金盘露。\n凤髓香和烟雾。\n三千珠翠拥宸游。\n水殿按凉州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (38, '鹧鸪天', '夏竦', '镇日无心扫黛眉。\n临行愁见理征衣。\n尊前只恐伤郎意，阁泪汪汪不敢垂。\n停宝马，捧瑶卮。\n相斟相劝忍分离。\n不如饮待奴先醉，图得不知郎去时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (39, '多丽', '聂冠卿', '想人生，美景良辰堪惜。\n问其间、赏心乐事，就中难是并得。\n况东城、凤台沙苑，泛晴波、浅照金碧。\n露洗华桐，烟霏丝柳，绿阴摇曳，荡春一色。\n画堂迥、玉簪琼佩，高会尽词客。\n清欢久、重然绛蜡，别就瑶席。\n有翩若轻鸿体态，暮为行雨标格。\n逞朱唇、缓歌妖丽，似听流莺乱花隔。\n慢舞萦回，娇鬟低，腰肢纤细困无力。\n忍分散、彩云归後，何处更寻觅。\n休辞醉，明月好花，莫谩轻掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (40, '望汉月・忆汉月', '李遵', '黄菊一丛临砌。\n颗颗露珠装缀。\n独教冷落向秋天，恨东君不曾留意。\n雕阑新雨霁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (41, '滴滴金', '李遵', '帝城五夜宴游歇。\n残灯外、看残月。\n都人犹在醉乡中，听更漏初彻。\n行乐已成闲话说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (42, '苏幕遮', '范仲淹', '碧云天，黄叶地。\n秋色连波，波上寒烟翠。\n山映斜阳天接水。\n芳草无情，更在斜阳外。\n黯乡魂，追旅思。\n夜夜除非，好梦留人睡。\n明月楼高休独倚。\n酒入愁肠，化作相思泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (43, '渔家傲', '范仲淹', '塞下秋来风景异。\n衡阳雁去无留意。\n四面边声连角起。\n千嶂里。\n长烟落日孤城闭。\n浊酒一杯家万里。\n燕然未勒归无计。\n羌管悠悠霜满地。\n人不寐。\n将军白发征夫泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (44, '御街行', '范仲淹', '纷纷堕叶飘香砌。\n夜寂静、寒声碎。\n真珠帘卷玉楼空，天淡银河垂地。\n年年今夜，月华如练，长是人千里。\n愁肠已断无由醉。\n酒未到、先成泪。\n残灯明灭枕头欹。\n谙尽孤眠滋味。\n都来此事，眉间心上，无计相回避。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (45, '剔银灯', '范仲淹', '昨夜因看蜀志。\n笑曹操、孙权、刘备。\n用尽机关，徒劳心力，只得三分天地。\n屈指细寻思，争如共、刘伶一醉。\n人世都无百岁。\n少痴呆、老成悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (46, '定风波', '范仲淹', '罗绮满城春欲暮。\n百花洲上寻芳去。\n浦映□花花映浦。\n无尽处。\n恍然身入桃源路。\n莫怪山翁聊逸豫。\n功名得丧归时数。\n莺解新声蝶解舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (47, '剔银灯', '沈邈', '一夜隋河风劲。\n霜湿水天如镜。\n古柳堤长，寒烟不起，波上月无流影。\n那堪频听。\n疏星外、离鸿相应。\n须信道、情多是病。\n酒未到、愁肠还醒。\n数叠兰衾，馀香未减，甚时枕鸳重并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (48, '剔银灯', '沈邈', '江上秋高霜早。\n云静月华如扫。\n候雁初飞，啼正苦，又是黄花衰草。\n等闲临照。\n潘郎鬓、星星易老。\n那堪更、酒醒孤棹。\n望千里、长安西笑。\n臂上妆痕，胸前泪粉，暗惹离愁多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (49, '长相思', '杨适1', '南山明。\n北山明。\n中有长亭号丈亭。\n沙边供送迎。\n东江清。\n西江清。\n海上潮来两岸平。\n行人分棹行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (50, '黄莺儿', '柳永', '园林晴昼春谁主。\n暖律潜催，幽谷暄和，黄鹂翩翩，乍迁芳树。\n观露湿缕金衣，叶映如簧语。\n晓来枝上绵蛮，似把芳心、深意低诉。\n无据。\n乍出暖烟来，又趁游蜂去。\n恣狂踪迹，两两相呼，终朝雾吟风舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (51, '玉女摇仙佩', '柳永', '飞琼伴侣，偶别珠宫，未返神仙行缀。\n取次梳妆，寻常言语，有得几多姝丽。\n拟把名花比。\n恐旁人笑我，谈何容易。\n细思算、奇葩艳卉，惟是深红浅白而已。\n争如这多情，占得人间，千娇百媚。\n须信画堂绣阁，皓月清风，忍把光阴轻弃。\n自古及今、佳人才子，少得当年双美。\n且恁相偎依。\n未消得、怜我多才多艺。\n愿奶奶、兰心蕙性，枕前言下，表余深意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (52, '雪梅香', '柳永', '景萧索，危楼独立面晴空。\n动悲秋情绪，当时宋玉应同。\n渔市孤烟袅寒碧，水村残叶舞愁红。\n楚天阔，浪浸斜阳，千里溶溶。\n临风。\n想佳丽，别後愁颜，镇敛眉峰。\n可惜当年，顿乖雨迹云踪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (53, '尾犯', '柳永', '夜雨滴空阶，孤馆梦回，情绪萧索。\n一片闲愁，想丹青难貌。\n秋渐老、蛩声正苦，夜将阑、灯花旋落。\n最无端处，总把良宵，祗恁孤眠却。\n佳人应怪我，别後寡信轻诺。\n记得当初，翦香云为约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (54, '早梅芳・喜迁莺', '柳永', '海霞红，山烟翠。\n故都风景繁华地。\n谯门画戟，下临万井，金碧楼台相倚。\n芰荷浦溆，杨柳汀洲，映虹桥倒影，兰舟飞棹，游人聚散，一片湖光里。\n汉元侯，自从破虏征蛮，峻陟枢庭贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (55, '斗百花', '柳永', '飒飒霜飘鸳瓦，翠幕轻寒微透，长门深锁悄悄，满庭秋色将晚。\n眼看菊蕊，重阳泪落如珠，长是淹残粉面。\n鸾辂音尘远。\n无险幽恨，寄情空纨扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (56, '斗百花', '柳永', '煦色韶光明媚。\n轻霭低笼芳树。\n池塘浅蘸烟芜，帘幕闲垂风絮。\n春困厌厌，抛掷斗草工夫，冷落踏青心绪。\n终日卮朱户。\n远恨绵绵，淑景迟迟难度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (57, '斗百花', '柳永', '满搦宫腰纤细。\n年纪方当笄岁。\n刚被风流沾惹，与合垂杨双髻。\n初学严妆，如描似削身材，怯雨羞云情意。\n举措多娇媚。\n争奈心性，未会先怜佳婿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (58, '甘草子', '柳永', '秋暮。\n乱洒衰荷，颗颗真珠雨。\n雨过月华生，冷彻鸳鸯浦。\n池长凭阑愁无侣。\n奈此个、单栖情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (59, '甘草子', '柳永', '秋尽。\n叶翦红绡，砌菊遗金粉。\n雁字一行来，还有边庭信。\n飘散露华清风紧。\n动翠幕、晓寒犹嫩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (60, '送征衣', '柳永', '过韶阳。\n璇枢电绕，华渚虹流，运应千载会昌。\n罄寰宇、荐殊祥。\n吾皇。\n诞弥月，瑶图缵庆，玉叶腾芳。\n并景贶、三灵眷，挺英哲、掩前王。\n迂年年、嘉节清和，颁率土称觞。\n无间要荒华夏，尽万里、走梯航。\n彤庭舜张大乐，禹会群方。\n行。\n望上国，山呼鳌，遥炉香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (61, '昼夜乐', '柳永', '洞房记得初相遇。\n便只合、长相聚。\n何期小会幽欢，变作离情别绪。\n况值阑珊春色暮。\n对满目、乱花狂絮。\n直恐好风光，尽随伊归去。\n一场寂寞凭谁诉。\n算前言、总轻负。\n早知恁地难拼，悔不当时留住。\n其奈风流端正外，更别有、系人心处。\n一日不思量，也攒眉千度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (62, '昼夜乐', '柳永', '秀香家住桃花径。\n算神仙、才堪并。\n层波细翦明眸，腻玉圆搓素颈。\n爱把歌喉当筵逞。\n遏天边，乱云愁凝。\n言语似娇莺，一声声堪听。\n洞房饮散帘帏静。\n拥香衾、欢心称。\n金炉麝袅青烟，凤帐烛摇红影。\n无限狂心乘酒兴。\n这欢娱、渐入嘉景。\n犹自怨邻鸡，道秋宵不永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (63, '柳腰轻', '柳永', '英英妙舞腰肢软。\n章台柳、昭阳燕。\n锦衣冠盖，绮堂筵会，是处千金争选。\n顾香砌、丝管初调，倚轻风、佩环微颤。\n乍入霓裳促遍。\n逞盈盈、渐催檀板。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (64, '西江月', '柳永', '凤额绣帘高卷，兽环朱户频摇。\n两竿红日上花梢。\n春睡厌厌难觉。\n好梦狂随飞絮，闲愁浓胜香醪。\n不成雨暮与云朝。\n又是韶光过了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (65, '倾杯乐', '柳永', '禁漏花深，绣工日永，蕙风布暖。\n变韶景、都门十二，元宵三五，银蟾光满。\n连云复道凌飞观。\n耸皇居丽，嘉气瑞烟葱。\n翠华宵幸，是处层城阆苑。\n龙凤烛、交光星汉。\n对咫尺鳌山开羽扇。\n会乐府两籍神仙，梨园四部弦管。\n向晓色、都人未散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (66, '笛家弄・笛家', '柳永', '花发西园，草薰南陌，韶光明媚，乍晴轻暖清明後。\n水嬉舟动，禊饮筵开，银塘似染，金堤如绣。\n是处王孙，几多游妓，往往携纤手。\n遣离人、对嘉景，触目伤怀，尽成感旧。\n别久。\n帝城当日，兰堂夜烛，百万呼卢，画阁春风，十千沽酒。\n未省、宴处能忘管弦，醉里不寻花柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (67, '倾杯乐', '柳永', '皓月初圆，暮云飘散，分明夜色如晴昼。\n渐消尽、醺醺残酒。\n危阁迥、凉生襟袖。\n追旧事、一饷凭阑久。\n如何媚容艳态，抵死孤欢偶。\n朝思暮想，自家空恁添清瘦。\n算到头、谁与伸剖。\n向道我别来，为伊牵系，度岁经年，偷眼觑、也不忍觑花柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (68, '迎新春', '柳永', '管变青律，帝里阳和新布。\n晴景回轻煦。\n庆嘉节、当三五。\n列华灯、千门万户。\n遍九陌、罗绮香风微度。\n十里然绛树。\n鳌山耸、喧天潇鼓。\n渐天如水，素月当午。\n香径里、绝缨掷果无数。\n更阑烛影花阴下，少年人、往往奇遇。\n太平时、朝野多欢民康阜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (69, '曲玉管', '柳永', '陇首云飞，江边日晚，烟波满目凭阑久。\n立望关河萧索，千里清秋。\n忍凝眸。\n杳杳神京，盈盈仙子，别来锦字终难偶。\n断雁无凭，冉冉飞下汀洲。\n思悠悠。\n暗想当初，有多少、幽欢佳会，岂知聚散难期，翻成雨恨云愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (70, '满朝欢', '柳永', '花隔铜壶，露金掌，都门十二清晓。\n帝里风光烂漫，偏爱春杪。\n烟轻昼永，引莺啭上林，鱼游灵沼。\n巷陌乍晴，香尘染惹，垂杨芳草。\n因念秦楼彩凤，楚观朝云，往惜曾迷歌笑。\n别来岁久，偶忆欢盟重到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (71, '梦还京', '柳永', '夜来匆匆饮散，枕背灯睡。\n酒力全轻，醉魂易醒，风揭帘栊，梦断披衣重起。\n悄无寐。\n追悔当初，绣阁话别太容易。\n日许时、犹阻归计。\n甚况味。\n旅馆虚度残岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (72, '凤衔杯', '柳永', '有美瑶卿能染翰。\n千里寄、小诗长简。\n想初襞苔笺，旋挥翠管红窗畔。\n渐玉箸、银钩满。\n锦囊收，犀轴卷。\n常珍重、小斋吟玩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (73, '凤衔杯', '柳永', '追悔当初孤深愿。\n经年价、两成幽怨。\n任越水吴山，似屏如障堪游玩。\n奈独自、慵抬眼。\n赏烟花，听弦管。\n图欢笑、转加肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (74, '鹤冲天', '柳永', '闲窗漏永，月冷霜华堕。\n悄悄下帘幕，残灯火。\n再三追往事，离魂乱、愁肠锁。\n无语沉吟坐。\n好天好景，未省展眉则个。\n从前早是多成破。\n何况经岁月，相抛。\n假使重相见，还得似、旧时麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (75, '受恩深', '柳永', '雅致装庭宇。\n黄花开淡泞。\n细香明艳尽天与。\n助秀色堪餐，向晓自有真珠露。\n刚被金钱妒。\n拟买断秋天，容易独步。\n粉蝶无情蜂已去。\n要上金尊，惟有诗人曾许。\n待宴赏重阳，恁时尽把芳心吐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (76, '看花回', '柳永', '屈指劳生百岁期。\n荣瘁相随。\n利牵名惹逡巡过，奈两轮、玉走金飞。\n红颜成白发，极品何为。\n尘事常多雅会稀。\n忍不开眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (77, '看花回', '柳永', '玉金阶舞舜干。\n朝野多欢。\n九衢三市风光丽，正万家、急管繁弦。\n凤楼临绮陌，嘉气非烟。\n雅俗熙熙物态妍。\n忍负芳年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (78, '柳初新', '柳永', '东郊向晓星杓亚。\n报帝里、春来也。\n柳抬烟眼，花匀露脸，渐觉绿娇红姹。\n妆点层台芳榭。\n运神功、丹青无价。\n别有尧阶试罢。\n新郎君、成行如画。\n杏园风细，桃花浪暖，竞喜羽迁鳞化。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (79, '两同心', '柳永', '嫩脸修蛾，淡匀轻扫。\n最爱学、宫体梳妆，偏能做、文人谈笑。\n绮筵前、舞燕歌云，别有轻妙。\n饮散玉炉烟袅。\n洞房悄悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (80, '两同心', '柳永', '伫立东风，断魂南国。\n花光媚、春醉琼楼，蟾彩迥、夜游香陌。\n忆当时、酒恋花迷，役损词客。\n别有眼长腰搦。\n痛怜深惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (81, '女冠子', '柳永', '断云残雨。\n洒微凉、生轩户。\n动清籁、萧萧庭树。\n银河浓淡，华星明灭，轻云时度。\n莎阶寂静无睹。\n幽蛩切切秋吟苦。\n疏篁一径，流萤几点，飞来又去。\n对月临风，空恁无眠耿耿，暗想旧日牵情处。\n绮罗丛里，有人人、那回饮散，略曾谐鸳侣。\n因循忍便睽阻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (82, '玉楼春', '柳永', '昭华夜醮连清曙。\n金殿霓旌笼瑞雾。\n九枝擎烛灿繁星，百和焚香抽翠缕。\n香罗荐地延真驭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (83, '玉楼春', '柳永', '凤楼郁郁呈嘉瑞。\n降圣覃恩延四裔。\n醮台清夜洞天严，公宴凌晨箫鼓沸。\n保生酒劝椒香腻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (84, '玉楼春', '柳永', '皇都今夕知何夕。\n特地风光盈绮陌。\n金丝玉管咽春空，蜡炬兰灯烧晓色。\n凤楼十二神仙宅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (85, '玉楼春', '柳永', '星闱上笏金章贵。\n重委外台疏近侍。\n百常天阁旧通班，九岁国储新上计。\n太仓日富中邦最。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (86, '玉楼春', '柳永', '阆风歧路连银阙。\n曾许金桃容易窃。\n乌龙未睡定惊猜，鹦鹉能言防漏泄。\n匆匆纵得邻香雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (87, '金蕉叶', '柳永', '厌厌夜饮平阳第。\n添银烛、旋呼佳丽。\n巧笑难禁，艳歌无间声相继。\n准拟幕天席地。\n金蕉叶泛金波齐，未更阑、已尽狂醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (88, '惜春郎', '柳永', '玉肌琼艳新妆饰。\n好壮观歌席。\n潘妃宝钏，阿娇金屋，应也消得。\n属和新词多俊格。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (89, '传花枝', '柳永', '平生自负，风流才调。\n口儿里、道知张陈赵。\n唱新词，改难令，总知颠倒。\n解刷扮，能ㄋ嗽，表里都峭。\n每遇著、饮席歌筵，人人尽道。\n可惜许老了。\n阎罗大伯曾教来，道人生、但不须烦恼。\n遇良辰，当美景，追欢买笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (90, '雨霖铃', '柳永', '寒蝉凄切。\n对长亭晚，骤雨初歇。\n都门帐饮无绪，留恋处、兰舟催发。\n执手相看泪眼，竟无语凝噎。\n念去去、千里烟波，暮霭沈沈楚天阔。\n多情自古伤离别。\n更那堪、冷落清秋节。\n今宵酒醒何处，杨柳岸、晓风残月。\n此去经年，应是良辰、好景虚设。\n便纵有、千种风情，更与何人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (91, '定风波', '柳永', '伫立长堤，淡荡晚风起。\n骤雨歇、极目萧疏，塞柳万株，掩映箭波千里。\n走舟车向此，人人奔名竞利。\n念荡子、终日驱驱，争觉乡关转迢递。\n何意。\n绣阁轻抛，锦字难逢，等闲度岁。\n奈泛泛旅迹，厌厌病绪，迩来谙尽，宦游滋味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (92, '尉迟杯', '柳永', '宠佳丽。\n算九衢红粉皆难比。\n天然嫩脸修蛾，不假施朱描翠。\n盈盈秋水。\n恣雅态、欲语先娇媚。\n每相逢、月夕花朝，自有怜才深意。\n绸缪凤枕鸳被。\n深深处、琼枝玉树相倚。\n困极欢馀，芙蓉帐暖，别是恼人情味。\n风流事、难逢双美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (93, '慢卷绸', '柳永', '闲窗烛暗，孤帏夜永，枕难成寐。\n细屈指寻思，旧事前欢，都来未尽，平生深意。\n到得如今，万般追悔。\n空只添憔悴。\n对好景良辰，皱著眉儿，成甚滋味。\n红茵翠被。\n当时事、一一堪垂泪。\n怎生得依前，似恁偎香倚暖，抱著日高犹睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (94, '征部乐', '柳永', '雅欢幽会，良辰可惜虚抛掷。\n每追念、狂踪旧迹。\n长祗恁、愁闷朝夕。\n凭谁去、花衢觅。\n细说此中端的。\n道向我、转觉厌厌，役梦劳魂苦相忆。\n须知最有，风前月下，心事始终难得。\n但愿我、虫虫心下，把人看待，长是初相识。\n况渐逢春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (95, '佳人醉', '柳永', '暮景萧萧雨霁。\n云淡天高风细。\n正月华如水。\n金波银汉，潋滟无际。\n冷浸书帷梦断，却披衣重起。\n临轩砌。\n素光遥指。\n因念翠蛾，杳隔音尘何处，相望同千里。\n尽凝睇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (96, '迷仙引', '柳永', '才过笄年，初绾云鬟，便学歌舞。\n席上尊前，王孙随分相许。\n算等闲、酬一笑，便千金慵觑。\n常祗恐、容易华偷换，光阴虚度。\n已受君恩顾。\n好与花为主。\n万里丹霄，何妨携手同归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (97, '御街行', '柳永', '燔柴烟断星河曙。\n宝辇回天步。\n端门羽卫簇雕阑，六乐舜韶先举。\n鹤书飞下，鸡竿高耸，恩霈均寰寓。\n赤霜袍烂飘香雾。\n喜色成春煦。\n九仪三事仰天颜，八彩旋生眉宇。\n椿龄无尽，萝图有庆，常作乾坤主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (98, '御街行', '柳永', '前时小饮春庭院。\n悔放笙歌散。\n归来中夜酒醺醺，惹起旧愁无限。\n虽看坠楼换马，争奈不是鸳鸯伴。\n朦胧暗想如花面。\n欲梦还惊断。\n和衣拥被不成眠，一枕万回千转。\n惟有画梁，新来双燕，彻曙闻长叹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (99, '归朝欢', '柳永', '别岸扁舟三两只。\n葭苇萧萧风淅淅。\n沙汀宿雁破烟飞，溪桥残月和霜白。\n渐渐分曙色。\n路遥山远多行役。\n往来人，只轮双桨，尽是利名客。\n一望乡关烟水隔。\n转觉归心生羽翼。\n愁云恨雨两牵萦，新春残腊相催逼。\n岁华都瞬息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (100, '采莲令', '柳永', '月华收，云淡霜天曙。\n西征客、此时情苦。\n翠娥执手送临歧，轧轧开朱户。\n千娇面、盈盈伫立，无言有泪，断肠争忍回顾。\n一叶兰舟，便恁急桨凌波去。\n贪行色、岂知离绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (101, '秋夜月・相见欢', '柳永', '当初聚散。\n便唤作、无由再逢伊面。\n近日来、不期而会重欢宴。\n向尊前、闲暇里，敛著眉儿长叹。\n惹起旧愁无限。\n盈盈泪眼。\n漫向我耳边，作万般幽怨。\n奈你自家心下，有事难见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (102, '巫山一段云', '柳永', '六六真游洞，三三物外天。\n九班麟稳破非烟。\n何处按云轩。\n昨夜麻姑陪宴。\n又话蓬莱清浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (103, '巫山一段云', '柳永', '琪树罗三殿，金龙抱九关。\n上清真籍总群仙。\n朝拜五云间。\n昨夜紫微诏下。\n急唤天书使者。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (104, '巫山一段云', '柳永', '清旦朝金母，斜阳醉玉龟。\n天风摇曳六铢衣。\n鹤背觉孤危。\n贪看海蟾狂戏。\n不道九关齐闭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (105, '巫山一段云', '柳永', '阆苑年华永，嬉游别是情。\n人间三度见河清。\n一番碧桃成。\n金母忍将轻摘。\n留宴鳌峰真客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (106, '巫山一段云', '柳永', '萧氏贤夫妇，茅家好弟兄。\n羽轮飙驾赴层城。\n高会尽仙卿。\n一曲云谣为寿。\n倒尽金壶碧酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (107, '婆罗门令', '柳永', '昨宵里、恁和衣睡。\n今宵里、又恁和衣睡。\n小饮归来，初更过、醺醺醉。\n中夜後、何事还惊起。\n霜天冷，风细细。\n触疏窗、闪闪灯摇曳。\n空床展转重追想，云雨梦、任枕难继。\n寸心万绪，咫尺千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (108, '法曲献仙音', '柳永', '追想秦楼心事，当年便约，于飞比翼。\n每恨临歧处，正携手、翻成云雨离拆。\n念倚玉偎香，前事顿轻掷。\n惯怜惜。\n饶心性，镇厌厌多病，柳腰花态娇无力。\n早是乍清减，别後忍教愁寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (109, '西平乐', '柳永', '尽日凭高目，脉脉春情绪。\n嘉景清明渐近，时节轻寒乍暖，天气才晴又雨。\n烟光淡荡，妆点平芜远树。\n黯凝伫。\n台榭好、莺燕语。\n正是和风丽日，几许繁红嫩绿，雅称嬉游去。\n奈阻隔、寻芳伴侣。\n秦楼凤吹，楚馆云约，空怅望、在何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (110, '凤栖梧・蝶恋花', '柳永', '帘下清歌帘外宴。\n虽爱新声，不见如花面。\n牙板数敲珠一串，梁尘暗落琉璃盏。\n桐树花深孤凤怨。\n渐遏遥天，不放行云散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (111, '凤栖梧・蝶恋花', '柳永', '伫倚危楼风细细。\n望极春愁，黯黯生天际。\n草色烟光残照里。\n无言谁会凭阑意。\n拟把疏狂图一醉。\n对酒当歌，强乐还无味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (112, '凤栖梧・蝶恋花', '柳永', '蜀锦地衣丝步障。\n屈曲回廊，静夜闲寻访。\n玉砌雕阑新月上。\n朱扉半掩人相望。\n旋暖熏炉温斗帐。\n玉树琼枝，迤逦相偎傍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (113, '法曲第二・法曲', '柳永', '青翼传情，香径偷期，自觉当初草草。\n未省同衾枕，便轻许相将，平生欢笑。\n怎生向、人间好事到头少。\n漫悔懊。\n细追思，恨从前容易，致得恩爱成烦恼。\n心下事千种，尽凭音耗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (114, '秋蕊香引', '柳永', '留不得。\n光阴催促，奈芳兰歇，好花谢，惟顷刻。\n彩云易散琉璃脆，验前事端的。\n风月夜，几处前踪旧迹。\n忍思忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (115, '一寸金', '柳永', '井络天开，剑岭云横控西夏。\n地胜异、锦里风流，蚕市繁华，簇簇歌台舞榭。\n雅俗多游赏，轻裘俊、靓妆艳冶。\n当春昼，摸石江边，浣花溪畔景如画。\n梦应三刀，桥名万里，中和政多暇。\n仗汉节、揽辔澄清，高掩武侯勋业，文翁风化。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (116, '永遇乐', '柳永', '薰风解愠，昼景清和，新霁时候。\n火德流光，萝图荐祉，累庆金枝秀。\n璇枢绕电，华渚流虹，是日挺生元后。\n缵唐虞垂拱，千载应期，万灵敷。\n殊方异域，争贡琛，架航波奔凑。\n三殿称觞，九仪就列，韶锵金奏。\n藩侯瞻望彤庭，亲携僚吏，竞歌元首。\n祝尧龄、北极齐尊，南山共久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (117, '永遇乐', '柳永', '天阁英游，内朝密侍，当世荣遇。\n汉守分麾，尧庭请瑞，方面凭心膂。\n风驰千骑，云拥双旌，向晓洞开严署。\n拥朱、喜色欢声，处处竞歌来暮。\n吴王旧国，今古江山秀异，人烟繁富。\n甘雨车行，仁风扇动，雅称安黎庶。\n棠郊成政，槐府登贤，非久定须归去。\n且乘闲、孙阁长开，融尊盛举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (118, '卜算子', '柳永', '江风渐老，汀蕙半凋，满目败红衰翠。\n楚客登临，正是暮秋天气。\n引疏砧、断续残阳里。\n对晚景、伤怀念远，新愁旧恨相继。\n脉脉人千里。\n念两处风情，万重烟水。\n雨歇天高，望断翠峰十二。\n尽无言、谁会凭高意。\n纵写得、离肠万种，奈归云谁寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (119, '鹊桥仙', '柳永', '届征途，携书剑，迢迢匹马东去。\n惨离怀，嗟少年易分难聚。\n佳人方恁缱绻，便忍分鸳侣。\n当媚景，算密意幽欢，尽成轻负。\n此际寸肠万绪。\n惨愁颜、断魂无语。\n和泪眼、片时几番回顾。\n伤心脉脉谁诉。\n但黯然凝伫。\n暮烟寒雨。\n望秦楼何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (120, '浪淘沙', '柳永', '梦觉、透窗风一线，寒灯吹息。\n那堪酒醒，又闻空阶，夜雨频滴。\n嗟因循、久作天涯客。\n负佳人、几许盟言，便忍把、从前欢会，陡顿翻成忧戚。\n愁极。\n再三追思，洞房深处，几度饮散歌阑，香暖鸳鸯被，岂暂时疏散，费伊心力。\n云尤雨，有万般千种，相怜相惜。\n恰到如今，天长漏永，无端自家疏隔。\n知何时、却拥秦云态，愿低帏昵枕，轻轻细说与，江乡夜夜，数寒更思忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (121, '夏云峰', '柳永', '宴堂深。\n轩楹雨，轻压暑气低沈。\n花洞彩舟泛，坐绕清浔。\n楚台风快，湘簟冷、永日披襟。\n坐久觉、疏弦脆管，时换新音。\n越娥兰态蕙心。\n逞妖艳、昵欢邀宠难禁。\n筵上笑歌间发，履交侵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (122, '浪淘沙令', '柳永', '有个人人。\n飞燕精神。\n急锵环佩上华。\n促拍尽随红袖举，风柳腰身。\n簌簌轻裙。\n妙尽尖新。\n曲终独立敛香尘。\n应是西施娇困也，眉黛双颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (123, '荔枝香', '柳永', '甚处寻芳赏翠，归去晚。\n缓步罗袜生尘，来绕琼筵看。\n金缕霞衣轻褪，似觉春游倦。\n遥认，众里盈盈好身段。\n拟回首，又伫立、帘帏畔。\n素脸红眉，时揭盖头微见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (124, '古倾杯・倾杯乐', '柳永', '冻水消痕，晓风生暖，春满东郊道。\n迟迟淑景，烟和露润，偏绕长堤芳草。\n断鸿隐隐归飞，江天杳杳。\n遥山变色，妆眉淡扫。\n目极千里，闲倚危樯迥眺。\n动几许、伤春怀抱。\n念何处、韶阳偏早。\n想帝里看看，名园芳树，烂漫莺花好。\n追思往昔年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (125, '倾杯・倾杯乐', '柳永', '离宴殷勤，兰舟凝滞，看看送行南浦。\n情知道世上，难使皓月长圆，彩云镇聚。\n算人生、悲莫悲於轻别，最苦正欢娱，便分鸳侣。\n泪流琼脸，梨花一枝春带雨。\n惨黛蛾、盈盈无绪。\n共黯然消魂，重携纤手，话别临行，犹自再三、问道君须去。\n频耳畔低语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (126, '破阵乐', '柳永', '露花倒影，烟芜蘸碧，灵沼波暖。\n金柳摇风树树，系彩舫龙舟遥岸。\n千步虹桥，参差雁齿，直趋水殿。\n绕金堤、曼衍鱼龙戏，簇娇春罗绮，喧天丝管。\n霁色荣光，望中似睹，蓬莱清浅。\n时见。\n凤辇宸游，鸾觞禊饮，临翠水、开镐宴。\n两两轻飞画楫，竞夺锦标霞烂。\n罄欢娱，歌鱼藻，徘徊宛转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (127, '双声子', '柳永', '晚天萧索，断蓬踪迹，乘兴兰棹东游。\n三吴风景，姑苏台榭，牢落暮霭初收。\n夫差旧国，香径没、徒有荒丘。\n繁华处，悄无睹，惟闻麋鹿呦呦。\n想当年、空运筹决战，图王取霸无休。\n江山如画，云涛烟浪，翻输范蠡扁舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (128, '阳台路', '柳永', '楚天晚。\n坠冷枫败叶，疏红零乱。\n冒征尘、匹马驱驱，愁见水遥山远。\n追念少年时，正恁凤帏，倚香偎暖。\n嬉游惯。\n又岂知、前欢云雨分散。\n此际空劳回首，望帝里、难收泪眼。\n暮烟衰草，算暗锁、路歧无限。\n今宵又、依前寄宿，甚处苇村山馆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (129, '内家娇', '柳永', '煦景朝升，烟光昼敛，疏雨夜来新霁。\n垂杨艳杏，丝软霞轻，绣出芳郊明媚。\n处处踏青斗草，人人眷红偎翠。\n奈少年、自有新愁旧恨，消遣无计。\n帝里。\n风光当此际。\n正好恁携佳丽。\n阻归程迢递。\n奈好景难留，旧欢顿弃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (130, '二郎神', '柳永', '炎光谢。\n过暮雨、芳尘轻洒。\n乍露冷风清庭户，爽天如水，玉钩遥挂。\n应是星娥嗟久阻，叙旧约、飙轮欲驾。\n极目处、微云暗度，耿耿银河高泻。\n闲雅。\n须知此景，古今无价。\n运巧思、穿针楼上女，抬粉面、云鬟相亚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (131, '醉蓬莱', '柳永', '渐亭皋叶下，陇首云飞，素秋新霁。\n华阙中天，锁葱葱佳气。\n嫩菊黄深，拒霜红浅，近宝阶香砌。\n玉宇无尘，金茎有露，碧天如水。\n正值升平，万几多暇，夜色澄鲜，漏声迢递。\n南极星中，有老人呈瑞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (132, '宣清', '柳永', '残月朦胧，小宴阑珊，归来轻寒凛凛。\n背银、孤馆乍眠，拥重衾、醉魄犹噤。\n永漏频传，前欢已去，离愁一枕。\n暗寻思、旧追游，神京风物如锦。\n念掷果朋侪，绝缨宴会，当时曾痛饮。\n命舞燕翩翻，歌珠贯串，向玳筵前，尽是神仙流品。\n至更阑、疏狂转甚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (133, '锦堂春・锦堂春慢', '柳永', '坠髻慵梳，愁蛾懒画，心绪是事阑珊。\n觉新来憔悴，金缕衣宽。\n认得这疏狂意下，向人诮譬如闲。\n把芳容整顿，恁地轻孤，争忍心安。\n依前过了旧约，甚当初赚我，偷翦云鬟。\n几时得归来，香阁深关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (134, '定风波', '柳永', '自春来、惨绿愁红，芳心是事可可。\n日上花梢，莺穿柳带，犹压香衾卧。\n暖酥消，腻云。\n终日厌厌倦梳裹。\n无那。\n恨薄情一去，音书无个。\n早知恁麽。\n悔当初、不把雕鞍锁。\n向鸡窗、只与蛮笺象管，拘束教吟课。\n镇相随，莫抛躲。\n针线闲拈伴伊坐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (135, '诉衷情近', '柳永', '雨晴气爽，伫立江楼望处。\n澄明远水生光，重叠暮山耸翠。\n遥认断桥幽径，隐隐渔村，向晚孤烟起。\n残阳里。\n脉脉朱阑静倚。\n黯然情绪，未饮先如醉。\n愁无际。\n暮云过了，秋光老尽，故人千里。\n竟日空凝睇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (136, '诉衷情近', '柳永', '景阑昼永，渐入清和气序。\n榆钱飘满闲阶，莲叶嫩生翠沼。\n遥望水边幽径，山崦孤村，是处园林好。\n闲情悄。\n绮陌游人渐少。\n少年风韵，自觉随春老。\n追前好。\n帝城信阻，天涯目断，暮云芳草。\n伫立空残照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (137, '留客住', '柳永', '偶登眺。\n凭小阑、艳阳时节，乍晴天气，是处闲花芳草。\n遥山万叠云散，涨海千里，潮平波浩渺。\n烟村院落，是谁家绿树，数声啼鸟。\n旅情悄。\n远信沈沈，离魂杳杳。\n对景伤怀，度日无言谁表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (138, '迎春乐', '柳永', '近来憔悴人惊怪。\n为别後、相思煞。\n我前生、负你愁烦债。\n便苦恁难开解。\n良夜永、牵情无计奈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (139, '隔帘听', '柳永', '咫尺凤衾鸳帐，欲去无因到。\n虾地重门悄。\n认绣履频移，洞房杳杳。\n强语笑。\n逞如簧、再三轻巧。\n梳妆早。\n琵琶闲抱。\n爱品相思调。\n声声似把芳心告。\n隔帘听，赢得断肠多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (140, '凤归云', '柳永', '恋帝里，金谷园林，平康巷陌，触处繁华，连日疏狂，未尝轻负，寸心双眼。\n况佳人、尽天外行云，掌上飞燕。\n向玳筵、一一皆妙选。\n长是因酒沈迷，被花萦绊。\n更可惜、淑景亭台，暑天枕簟。\n霜月夜凉，雪霰朝飞，一岁风光，尽堪随分，俊游清宴。\n算浮生事，瞬息光阴，锱铢名宦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (141, '抛球乐', '柳永', '晓来天气浓淡，微雨轻洒。\n近清明，风絮巷陌，烟草池塘，尽堪图画。\n艳杏暖、妆脸匀开，弱柳困、宫腰低亚。\n是处丽质盈盈，巧笑嬉嬉，手簇秋千架。\n戏彩球罗绶，金鸡芥羽，少年驰骋，芳郊绿野。\n占断五陵游，奏脆管、繁弦声和雅。\n向名园深处，争泥画轮，竞羁宝马。\n取次罗列杯盘，就芳树、绿阴红影下。\n舞婆娑，歌宛转，仿佛莺娇燕姹。\n寸珠片玉，争似此、浓欢无价。\n任他美酒，十千一斗，饮竭仍解金貂贳。\n恣幕天席地，陶陶尽醉太平，且乐唐虞景化。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (142, '集贤宾・接贤宾', '柳永', '小楼深巷狂游遍，罗绮成丛。\n就中堪人属意，最是虫虫。\n有画难描雅态，无花可比芳容。\n几回饮散良宵永，鸳衾暖、凤枕香浓。\n算得人间天上，惟有两心同。\n近来云雨忽西东。\n诮恼损情。\n纵然偷期暗会，长是匆匆。\n争似和鸣偕老，免教敛翠啼红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (143, '人娇', '柳永', '当日相逢，便有怜才深意。\n歌筵罢、偶同鸳被。\n别来光景，看看经岁。\n昨夜里、方把旧欢重继。\n晓月将沈，征骖已鞴。\n愁肠乱、又还分袂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (144, '思归乐', '柳永', '天幕清和堪宴聚。\n想得尽、高阳俦侣。\n皓齿善歌长袖舞。\n渐引入、醉乡深处。\n晚岁光阴能几许。\n这巧宦、不须多取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (145, '应天长', '柳永', '残蝉渐绝。\n傍碧砌修梧，败叶微脱。\n风露凄清，正是登高时节。\n东篱霜乍结。\n绽金蕊、嫩香堪折。\n聚宴处，落帽风流，未饶前哲。\n把酒与君说。\n恁好景佳辰，怎忍虚设。\n休效牛山，空对江天凝咽。\n尘劳无暂歇。\n遇良会、剩偷欢悦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (146, '合欢带', '柳永', '身材儿、早是妖娆。\n算风措、实难描。\n一个肌肤浑似玉，更都来、占了千娇。\n妍歌艳舞，莺惭巧舌，柳妒纤腰。\n自相逢，便觉韩娥价减，飞燕声消。\n桃花零落，溪水潺，重寻仙径非遥。\n莫道千金酬一笑，便明珠、万斛须邀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (147, '少年游', '柳永', '长安古道马迟迟。\n高柳乱蝉栖。\n夕阳岛外，秋风原上，目断四天垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (148, '少年游', '柳永', '参差烟树灞陵桥。\n风物尽前朝。\n衰杨古柳，几经攀折，憔悴楚宫腰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (149, '少年游', '柳永', '层波潋滟远山横。\n一笑一倾城。\n酒容红嫩，歌喉清丽，百媚坐中生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (150, '少年游', '柳永', '世间尤物意中人。\n轻细好腰身。\n香帏睡起，发妆酒酽，红脸杏花春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (151, '少年游', '柳永', '淡黄衫子郁金裙。\n长忆个人人。\n文谈闲雅，歌喉清丽，举措好精神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (152, '少年游', '柳永', '铃斋无讼宴游频。\n罗绮簇簪绅。\n施朱傅粉，丰肌清骨，容态尽天真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (153, '少年游', '柳永', '帘垂深院冷萧萧。\n花外漏声遥。\n青灯未灭，红窗闲卧，魂梦去迢迢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (154, '少年游', '柳永', '一生赢得是凄凉。\n追前事、暗心伤。\n好天良夜，深屏香被，争忍便相忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (155, '少年游', '柳永', '日高花榭懒梳头。\n无语倚妆楼。\n修眉敛黛，遥山横翠，相对结春愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (156, '少年游', '柳永', '佳人巧笑值千金。\n当日偶情深。\n几回饮散，灯残香暖，好事尽鸳衾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (157, '长相思', '柳永', '画鼓喧街，兰灯满市，皎月初照严城。\n清都绛阙夜景，风传银箭，露金茎。\n巷陌纵横。\n过平康款辔，缓听歌声。\n凤烛荧荧。\n那人家、未掩香屏。\n向罗绮丛中，认得依稀旧日，雅态轻盈。\n娇波艳冶，巧笑依然，有意相迎。\n墙头马上，漫迟留、难写深诚。\n又岂知、名宦拘检，年来减尽风情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (158, '尾犯', '柳永', '晴烟幂幂。\n渐东郊芳草，染成轻碧。\n野塘风暖，游鱼动触，冰嘶微坼。\n几行断雁，旋次第、归霜碛。\n咏新诗，手拈江梅，故人赠我春色。\n似此光阴催逼。\n念浮生、不满百。\n虽照人轩冕，润屋珠金，於身何益。\n一种劳心力。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (159, '木兰花・玉楼春', '柳永', '心娘自小能歌舞。\n举意动容皆济楚。\n解教天上念奴羞，不怕掌中飞燕妒。\n玲珑绣扇花藏语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (160, '木兰花・玉楼春', '柳永', '佳娘捧板花钿簇。\n唱出新声群艳伏。\n金鹅扇掩调累累，文杏梁高尘簌簌。\n鸾吟凤啸清相续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (161, '木兰花・玉楼春', '柳永', '虫娘举措皆温润。\n每到婆娑偏恃俊。\n香檀敲缓玉纤迟，画鼓声催莲步紧。\n贪为顾盼夸风韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (162, '木兰花・玉楼春', '柳永', '酥娘一搦腰肢袅。\n回雪萦尘皆尽妙。\n几多狎客看无厌，一辈舞童功不到。\n星眸顾指精神峭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (163, '驻马听', '柳永', '凤枕鸾帷。\n二三载，如鱼似水相知。\n良天好景，深怜多爱，无非尽意依随。\n奈何伊。\n恣性灵、忒煞些儿。\n无事孜煎，万回千度，怎忍分离。\n而今渐行渐远，渐觉虽悔难追。\n漫寄消寄息，终久奚为。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (164, '诉衷情', '柳永', '一声画角日西曛。\n催促掩朱门。\n不堪更倚危阑，肠断已消魂。\n年渐晚，雁空频。\n问无因。\n思心欲碎，愁泪难收，又是黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (165, '戚氏', '柳永', '晚秋天。\n一霎微雨洒庭轩。\n槛菊萧疏，井梧零乱惹残烟。\n凄然。\n望江关。\n飞云黯淡夕阳间。\n当时宋玉悲感，向此临水与登山。\n远道迢递，行人凄楚，倦听陇水潺。\n正蝉吟败叶，蛩响衰草，相应喧喧。\n孤馆度日如年。\n风露渐变，悄悄至更阑。\n长天净，绛河清浅，皓月婵娟。\n思绵绵。\n夜永对景，那堪屈指，暗想从前。\n未名未禄，绮陌红楼，往往经岁迁延。\n帝里风光好，当年少日，暮宴朝欢。\n况有狂朋怪侣，遇当歌、对酒竞留连。\n别来迅景如梭，旧游似梦，烟水程何限。\n念利名、憔悴长萦绊。\n追往事、空惨愁颜。\n漏箭移、稍觉轻寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (166, '轮台子', '柳永', '一枕清宵好梦，可惜被、邻鸡唤觉。\n匆匆策马登途，满目淡烟衰草。\n前驱风触鸣珂，过霜林、渐觉惊栖鸟。\n冒征尘远况，自古凄凉长安道。\n行行又历孤村，楚天阔、望中未晓。\n念劳生，惜芳年壮岁，离多欢少。\n叹断梗难停，暮云渐杳。\n但黯黯魂消，寸肠凭谁表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (167, '引驾行', '柳永', '虹收残雨。\n蝉嘶败柳长堤暮。\n背都门、动消黯，西风片帆轻举。\n愁睹。\n泛画翩翩，灵龟隐隐下前浦。\n忍回首、佳人渐远，想高城、隔烟树。\n几许。\n秦楼永昼，谢阁连宵奇遇。\n算赠笑千金，酬歌百，尽成轻负。\n南顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (168, '望远行', '柳永', '绣帏睡起。\n残妆浅，无绪匀红补翠。\n藻井凝尘，金梯铺藓，寂寞凤楼十二。\n风絮纷纷，烟芜苒苒，永日画阑，沈吟独倚。\n望远行，南陌春残悄归骑。\n凝睇。\n消遣离愁无计。\n但暗掷、金钗买醉。\n对好景、空饮香醪，争奈转添珠泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (169, '彩云归', '柳永', '蘅皋向晚舣轻航。\n卸云帆、水驿鱼乡。\n当暮天、霁色如晴昼，江练静、皎月飞光。\n那堪听、远村羌管，引离人断肠。\n此际浪萍风梗，度岁茫茫。\n堪伤。\n朝欢暮宴，被多情、赋与凄凉。\n别来最苦，襟袖依约，尚有馀香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (170, '洞仙歌', '柳永', '佳景留心惯。\n况少年彼此，风情非浅。\n有笙歌巷陌，绮罗庭院。\n倾城巧笑如花面。\n恣雅态、明眸回美盼。\n同心绾。\n算国艳仙材，翻恨相逢晚。\n缱绻。\n洞房悄悄，绣被重重，夜永欢馀，共有海约山盟，记得翠云偷翦。\n和鸣彩凤于飞燕。\n间柳径花阴携手遍。\n情眷恋。\n向其间、密约轻怜事何限。\n忍聚散。\n况已结深深愿。\n愿人间天上，暮云朝雨长相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (171, '离别难', '柳永', '花谢水流倏忽，嗟年少光阴。\n有天然、蕙质兰心。\n美韶容、何啻值千金。\n便因甚、翠弱红衰，缠绵香体，都不胜任。\n算神仙、五色灵丹无验，中路委瓶簪。\n人悄悄，夜沈沈。\n闭香闺、永弃鸳衾。\n想娇魂媚魄非远，纵洪都方士也难寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (172, '击梧桐', '柳永', '香靥深深，姿姿媚媚，雅格奇容天与。\n自识伊来，便好看承，会得妖娆心素。\n临歧再约同欢，定是都把、平生相许。\n又恐恩情，易破难成，未免千般思虑。\n近日书来，寒喧而已，苦没忉忉言语。\n便认得、听人教当，拟把前言轻负。\n见说兰台宋玉，多才多艺善词赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (173, '夜半乐', '柳永', '冻云黯淡天气，扁舟一叶，乘兴离江渚。\n渡万壑千岩，越溪深处。\n怒涛渐息，樵风乍起，更闻商旅相呼。\n片帆高举。\n泛画、翩翩过南浦。\n望中酒旆闪闪，一簇烟村，数行霜树。\n残日下，渔人鸣榔归去。\n败荷零落，衰杨掩映，岸边两两三三，浣沙游女。\n避行客、含羞笑相语。\n到此因念，绣阁轻抛，浪萍难驻。\n叹後约丁宁竟何据。\n惨离怀，空恨岁晚归期阻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (174, '祭天神', '柳永', '叹笑筵歌席轻抛。\n背孤城、几舍烟村停画舸。\n更深钓叟归来，数点残灯火。\n被连绵宿酒醺醺，愁无那。\n寂寞拥、重衾卧。\n又闻得、行客扁舟过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (175, '过涧歇近・过涧歇', '柳永', '淮楚。\n旷望极，千里火云烧空，尽日西郊无雨。\n厌行旅。\n数幅轻帆旋落，舣棹蒹葭浦。\n避畏景，两两舟人夜深语。\n此际争可，便恁奔名竞利去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (176, '安公子', '柳永', '长川波潋滟。\n楚乡淮岸迢递，一霎烟汀雨过，芳草青如染。\n驱驱携书剑。\n当此好天好景，自觉多愁多病，行役心情厌。\n望处旷野沈沈，暮云黯黯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (177, '菊花新', '柳永', '欲掩香帏论缱绻。\n先敛双蛾愁夜短。\n催促少年郎，先去睡、鸳衾图暖。\n须臾放了残针线。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (178, '过涧歇近・过涧歇', '柳永', '酒醒。\n梦才觉，小阁香炭成煤，洞户银蟾移影。\n人寂静。\n夜永清寒，翠瓦霜凝。\n疏帘风动，漏声隐隐，飘来转愁听。\n怎向心绪，近日厌厌长似病。\n凤楼咫尺，佳期杳无定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (179, '轮台子', '柳永', '雾敛澄江，烟消蓝光碧。\n彤霞衬遥天，掩映断续，半空残月。\n孤村望处人寂寞，闻钓叟、甚处一声羌笛。\n九疑山畔才雨过，斑竹作、血痕添色。\n感行客。\n翻思故国，恨因循阻隔。\n路久沈消息。\n正老松枯柏情如织。\n闻野猿啼，愁听得。\n见钓舟初出，芙蓉渡头，鸳鸯滩侧。\n干名利禄终无益。\n念岁岁间阻，迢迢紫陌。\n翠蛾娇艳，从别後经今，花开柳拆伤魂魄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (180, '望汉月・忆汉月', '柳永', '明月明月明月。\n争奈乍圆还缺。\n恰如年少洞房人，暂欢会、依前离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (181, '归去来', '柳永', '初过元宵三五。\n慵困春情绪。\n灯月阑珊嬉游处。\n游人尽、厌欢聚。\n凭仗如花女。\n持杯谢、酒朋诗侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (182, '燕归梁', '柳永', '织锦裁编写意深。\n字值千金。\n一回披玩一愁吟。\n肠成结、泪盈襟。\n幽欢已散前期远，无赖、是而今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (183, '八六子', '柳永', '如花貌。\n当来便约，永结同心偕老。\n为妙年、俊格聪明，凌厉多方怜爱，何期养成心性近，元来都不相表。\n渐作分飞计料。\n稍觉因情难供，恁殛恼。\n争克罢同欢笑。\n已是断弦尤续，覆水难收，常向人前诵谈，空遣时传音耗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (184, '长寿乐', '柳永', '尤红翠。\n近日来、陡把狂心牵系。\n罗绮丛中，笙歌筵上，有个人人可意。\n解严妆巧笑，取次言谈成娇媚。\n知几度、密约秦楼尽醉。\n仍携手，眷恋香衾绣被。\n情渐美。\n算好把、夕雨朝云相继。\n便是仙禁春深，御炉香袅，临轩亲试。\n对天颜咫尺，定然魁甲登高第。\n待恁时、等著回来贺喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (185, '望海潮', '柳永', '东南形胜，三吴都会，钱塘自古繁华。\n烟柳画桥，风帘翠幕，参差十万人家。\n云树绕堤沙。\n怒涛卷霜雪，天堑无涯。\n市列珠玑，户盈罗绮竞豪奢。\n重湖叠清嘉。\n有三秋桂子，十里荷花。\n羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。\n千骑拥高牙。\n乘醉听箫鼓，吟赏烟霞。\n异日图将好景，归去凤池夸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (186, '如鱼水', '柳永', '轻霭浮空，乱峰倒影，潋滟十里银塘。\n绕岸垂杨。\n红楼朱阁相望。\n芰荷香。\n双双戏、鸳鸯。\n乍雨过、兰芷汀洲，望中依约似潇湘。\n风淡淡，水茫茫。\n动一片晴光。\n画舫相将。\n盈盈红粉清商。\n紫薇郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (187, '如鱼水', '柳永', '帝里疏散，数载酒萦花系，九陌狂游。\n良景对珍筵恼，佳人自有风流。\n劝琼瓯。\n绛唇启、歌发清幽。\n被举措、艺足才高，在处别得艳姬留。\n浮名利，拟拼休。\n是非莫挂心头。\n富贵岂尤人，时会高志须酬。\n莫闲愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (188, '玉蝴蝶', '柳永', '望处雨收云断，凭阑悄悄，目送秋光。\n晚景萧疏，堪动宋玉悲凉。\n水风轻、苹花渐老，月露冷、梧叶飘黄。\n遣情伤。\n故人何在，烟水茫茫。\n难忘。\n文期酒会，几孤风月，屡变星霜。\n海阔山遥，未知何处是潇湘。\n念双燕、难凭远信，指暮天、空识归航。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (189, '玉蝴蝶', '柳永', '渐觉芳郊明媚，夜来膏雨，一洒尘埃。\n满目浅桃深杏，露染风裁。\n银塘静、鱼鳞簟展，烟岫翠、龟甲屏开。\n殷晴雷。\n云中鼓吹，游遍蓬莱。\n徘徊。\n隼前後，三千珠履，十二金钗。\n雅俗熙熙，下车成宴尽春台。\n好雍容、东山妓女，堪笑傲、北海尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (190, '玉蝴蝶', '柳永', '是处小街斜巷，烂游花馆，连醉瑶卮。\n选得芳容端丽，冠绝吴姬。\n绛唇轻、笑歌尽雅，莲步稳、举措皆奇。\n出屏帏。\n倚风情态，约素腰肢。\n当时。\n绮罗丛里，知名虽久，识面何迟。\n见了千花万柳，比并不如伊。\n未同欢、寸心暗许，欲话别、纤手重携。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (191, '玉蝴蝶', '柳永', '误入平康小巷，画檐深处，珠箔微褰。\n罗绮丛中，偶认旧识婵娟。\n翠眉开、娇横远岫，绿鬓、浓染春烟。\n忆情牵。\n粉墙曾恁，窥宋三年。\n迁延。\n珊瑚筵上，亲持犀管，旋叠香笺。\n要索新词，人含笑立尊前。\n按新声、珠喉渐稳，想旧意、波脸增妍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (192, '玉蝴蝶', '柳永', '淡荡素商行暮，远空雨歇，平野烟收。\n满目江山，堪助楚客冥搜。\n素光动、云涛涨晚，紫翠冷、霜横秋。\n景清幽。\n渚兰香谢，汀树红愁。\n良俦。\n西风吹帽，东篱携酒，共结欢游。\n浅酌低吟，坐中俱是饮家流。\n对残晖、登临休叹，赏令节、酩酊方酬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (193, '满江红', '柳永', '暮雨初收，长川静、征帆夜落。\n临岛屿、蓼烟疏淡，苇风萧索。\n几许渔人飞短艇，尽载灯火归村落。\n遣行客、当此念回程，伤漂泊。\n桐江好，烟漠漠。\n波似染，山如削。\n绕严陵滩畔，鹭飞鱼跃。\n游宦区区成底事，平生况有云泉约。\n归去来、一曲仲宣吟，从军乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (194, '满江红', '柳永', '访雨寻云，无非是、奇容艳色。\n就中有、天真妖丽，自然标格。\n恶发姿颜欢喜面，细追想处皆堪惜。\n自别後、幽怨与闲愁，成堆积。\n鳞鸿阻，无信息。\n梦魂断，难寻觅。\n尽思量，休又怎生休得。\n谁恁多情凭向道，纵来相见且相忆。\n便不成、常遣似如今，轻抛掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (195, '满江红', '柳永', '万恨千愁，将年少、衷肠牵系。\n残梦断、酒醒孤馆，夜长无味。\n可惜许枕前多少意，到如今两总无终始。\n独自个、赢得不成眠，成憔悴。\n添伤感，将何计。\n空只恁，厌厌地。\n无人处思量，几度垂泪。\n不会得都来些子事，甚恁底死难拚弃。\n待到头、终久问伊看，如何是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (196, '满江红', '柳永', '匹马驱驱，摇征辔、溪边谷畔。\n望斜日西照，渐沈山半。\n两两栖禽归去急，对人相并声相唤。\n似笑我、独自向长途，离魂乱。\n中心事，多伤感。\n人是宿，前村馆。\n想鸳衾今夜，共他谁暖。\n惟有枕前相思泪，背灯弹了依前满。\n怎忘得、香阁共伊时，嫌更短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (197, '洞仙歌', '柳永', '乘兴，闲泛兰舟，渺渺烟波东去。\n淑气散幽香，满蕙兰汀渚。\n绿芜平畹，和风轻暖，曲岸垂杨，隐隐隔、桃花圃。\n芳树外，闪闪酒旗遥举。\n羁旅。\n渐入三吴风景，水村渔市。\n闲思更远神京，抛掷幽会小欢何处。\n不堪独倚危樯，凝情西望日边，繁华地、归程阻。\n空自叹当时，言约无据。\n伤心最苦。\n伫立对、碧云将暮。\n关河远，怎奈向、此时情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (198, '引驾行', '柳永', '红尘紫陌，斜阳暮草长安道，是离人、断魂处，迢迢匹马西征。\n新晴。\n韶光明媚，轻烟淡薄和气暖，望花村、路隐映，摇鞭时过长亭。\n愁生。\n伤凤城仙子，别来千里重行行。\n又记得临歧，泪眼湿、莲脸盈盈。\n消凝。\n花朝月夕，最苦冷落银屏。\n想媚容、耿耿无眠，屈指已算回程。\n相萦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (199, '望远行', '柳永', '长空降瑞，寒风翦，淅淅瑶花初下。\n乱飘僧舍，密洒歌楼，迤逦渐迷鸳瓦。\n好是渔人，披得一蓑归去，江上晚来堪画。\n满长安，高却旗亭酒价。\n幽雅。\n乘兴最宜访戴，泛小棹、越溪潇洒。\n皓鹤夺鲜，白鹇失素，千里广铺寒野。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (200, '八声甘州', '柳永', '对潇潇、暮雨洒江天，一番洗清秋。\n渐霜风凄惨，关河冷落，残照当楼。\n是处红衰翠减，苒苒物华休。\n惟有长江水，无语东流。\n不忍登高临远，望故乡渺邈，归思难收。\n叹年来踪迹，何事苦淹留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (201, '临江仙', '柳永', '梦觉小庭院，冷风淅淅，疏雨潇潇。\n绮窗外，秋声败叶狂飘。\n心摇。\n奈寒漏永，孤帏悄，泪烛空烧。\n无端处，是绣衾鸳枕，闲过清宵。\n萧条。\n牵情系恨，争向年少偏饶。\n觉新来、憔悴旧日风标。\n魂消。\n念欢娱事，烟波阻、後约方遥。\n还经岁，问怎生禁得，如许无聊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (202, '竹马子・竹马儿', '柳永', '登孤垒荒凉，危亭旷望，静临烟渚。\n对雌霓挂雨，雄风拂槛，微收烦暑。\n渐觉一叶惊秋，残蝉噪晚，素商时序。\n览景想前欢，指神京，非雾非烟深处。\n向此成追感，新愁易积，故人难聚。\n凭高尽日凝伫。\n赢得消魂无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (203, '小镇西・小镇西犯', '柳永', '意中有个人，芳颜二八。\n天然俏、自来奸黠。\n最奇绝。\n是笑时、媚靥深深，百态千娇，再三偎著，再三香滑。\n久离缺。\n夜来魂梦里，尤花雪。\n分明似旧家时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (204, '小镇西犯', '柳永', '水乡初禁火，青春未老。\n芳菲满、柳汀烟岛。\n波际红帏缥缈。\n尽杯盘小。\n歌祓禊，声声谐楚调。\n路缭绕。\n野桥新市里，花妓好。\n引游人、兢来喧笑。\n酩酊谁家年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (205, '迷神引', '柳永', '一叶扁舟轻帆卷。\n暂泊楚江南岸。\n孤城暮角，引胡茄怨。\n水茫茫，平沙雁、旋惊散。\n烟敛寒林簇，画屏展。\n天际遥山小，黛眉浅。\n旧赏轻抛，到此成游宦。\n觉客程劳，年光晚。\n异乡风物，忍萧索、当愁眼。\n帝城赊，秦楼阻，旅魂乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (206, '促拍满路花', '柳永', '香靥融春雪，翠鬓秋烟。\n楚腰纤细正笄年。\n凤帏夜短，偏爱日高眠。\n起来贪颠耍，只恁残却黛眉，不整花钿。\n有时携手闲坐，偎倚绿窗前。\n温柔情态尽人怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (207, '六么令', '柳永', '淡烟残照，摇曳溪光碧。\n溪边浅桃深杏，迤逦染春色。\n昨夜扁舟泊处，枕底当滩碛。\n波声渔笛。\n惊回好梦，梦里欲归归不得。\n展转翻成无寐，因此伤行役。\n思念多媚多娇，咫尺千山隔。\n都为深情密爱，不忍轻离拆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (208, '剔银灯', '柳永', '何事春工用意。\n绣画出、万红千翠。\n艳杏夭桃，垂杨芳草，各斗雨膏烟腻。\n如斯佳致。\n早晚是、读书天气。\n渐渐园林明媚。\n便好安排欢计。\n论槛买花，盈车载酒，百千金邀妓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (209, '红窗听', '柳永', '如削肌肤红玉莹。\n举措有、许多端正。\n二年三岁同鸳寝。\n表温柔心性。\n别後无非良夜永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (210, '临江仙', '柳永', '鸣珂碎撼都门晓，旌幢拥下天人。\n马摇金辔破香尘。\n壶浆盈路，欢动一城春。\n扬州曾是追游地，酒台花径仍存。\n凤箫依旧月中闻。\n荆王魂梦，应认岭头云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (211, '凤归云', '柳永', '向深秋，雨馀爽气肃西郊。\n陌上夜阑，襟袖起凉飙。\n天末残星，流电未灭，闪闪隔林梢。\n又是晓鸡声断，阳乌光动，渐分山路迢迢。\n驱驱行役，苒苒光阴，绳头利禄，蜗角功名，毕竟成何事，漫相高。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (212, '女冠子', '柳永', '淡烟飘薄。\n莺花谢、清和院落。\n树阴翠、密叶成幄。\n麦秋霁景，夏云忽变奇峰、倚寥廓。\n波暖银塘，涨新萍绿鱼跃。\n想端忧多暇，陈王是日，嫩苔生阁。\n正铄石天高，流金昼永，楚榭光风转蕙，披襟处、波翻翠幕。\n以文会友，沈李浮瓜忍轻诺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (213, '玉山枕', '柳永', '骤雨新霁。\n荡原野、清如洗。\n断霞散彩，残阳倒影，天外云峰，数朵相倚。\n露荷烟芰满池塘，见次第、几番红翠。\n当是时、河朔飞觞，避炎蒸，想风流堪继。\n晚来高树清风起。\n动帘幕、生秋气。\n画楼昼寂，兰堂夜静，舞艳歌姝，渐任罗绮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (214, '减字木兰花', '柳永', '花心柳眼。\n郎似游丝常惹绊。\n慵困谁怜。\n绣线金针不喜穿。\n深房密宴。\n争向好天多聚散。\n绿锁窗前。\n几日春愁废管弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (215, '木兰花令', '柳永', '有个人人真攀羡。\n问著洋洋回却面。\n你若无意向他人，为甚梦中频相见。\n不如闻早还却愿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (216, '甘州令', '柳永', '冻云深，淑气浅，寒欺绿野。\n轻雪伴、早梅飘谢。\n艳阳天，正明媚，却成潇洒。\n玉人歌，画楼酒，对此景、骤增高价。\n卖花巷陌，放灯台榭。\n好时节、怎生轻舍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (217, '西施', '柳永', '苎萝妖艳世难偕。\n善媚悦君怀。\n後庭恃宠，尽使绝嫌猜。\n正恁朝欢暮宴，情未足，早江上兵来。\n捧心调态军前死，罗绮旋变尘埃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (218, '西施', '柳永', '柳街灯市好花多。\n尽让美琼娥。\n万娇千媚，的的在层波。\n取次梳妆，自有天然态，爱浅画双娥。\n断肠最是金闺客，空怜爱、奈伊何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (219, '西施', '柳永', '自从回步百花桥。\n便独处清宵。\n凤衾鸳枕，何事等闲抛。\n纵有馀香，也似郎恩爱，向日夜潜消。\n恐伊不信芳容改，将憔悴、写霜绡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (220, '河传', '柳永', '翠深红浅。\n愁娥黛蹙，娇波刀翦。\n奇容妙妓，争逞舞歌扇。\n妆光生粉面。\n坐中醉客风流惯。\n尊前见。\n特地惊狂眼。\n不似少年时节，千金争选。\n相逢何太晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (221, '河传', '柳永', '淮岸。\n向晚。\n圆荷向背，芙蓉深浅。\n仙娥画舸，露渍红芳交乱。\n难分花与面。\n采多渐觉轻船满。\n呼归伴。\n急桨烟村远。\n隐隐棹歌，渐被蒹葭遮断。\n曲终人不见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (222, '郭郎儿近拍', '柳永', '帝里。\n闲居小曲深坊，庭院沈沈朱户闭。\n新霁。\n畏景天气。\n薰风帘幕无人，永昼厌厌如度岁。\n愁悴。\n枕簟微凉，睡久辗转慵起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (223, '透碧霄', '柳永', '月华边。\n万年芳树起祥烟。\n帝居壮丽，皇家熙盛，宝运当千。\n端门清昼，觚照日，双阙中天。\n太平时、朝野多欢。\n遍锦街香陌，钧天歌吹，阆苑神仙。\n昔观光得意，狂游风景，再睹更精妍。\n傍柳阴，寻花径，空恁辔垂鞭。\n乐游雅戏，平康艳质，应也依然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (224, '木兰花慢', '柳永', '倚危楼伫立，乍萧索、晚晴初。\n渐素景衰残，风砧韵响，双树红疏。\n云衢。\n见新雁过，奈佳人自别阻音书。\n空遣悲秋念远，寸肠万恨萦纡。\n皇都。\n暗想欢游，成往事、动欷。\n念对酒当歌，低帏并枕，翻恁轻孤。\n归途。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (225, '木兰花慢', '柳永', '拆桐花烂漫，乍疏雨、洗清明。\n正艳杏烧林，缃桃绣野，芳景如屏。\n倾城。\n尽寻胜去，骤雕鞍绀出郊。\n风暖繁弦脆管，万家竞奏新声。\n盈盈。\n斗草踏青。\n人艳冶、递逢迎。\n向路傍往往，遗簪坠珥，珠翠纵横。\n欢情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (226, '木兰花慢', '柳永', '古繁华茂苑，是当日、帝王州。\n咏人物鲜明，土风细腻，曾美诗流。\n寻幽。\n近香径处，聚莲娃钓叟簇汀洲。\n晴景吴波练静，万家绿水朱楼。\n凝旒。\n乃眷东南，思共理、命贤侯。\n继梦得文章，乐天惠爱，布政优优。\n鳌头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (227, '临江仙引', '柳永', '渡口、向晚，乘瘦马、陟平冈。\n西郊又送秋光。\n对暮山横翠，衬残叶飘黄。\n凭高念远，素景楚天，无处不凄凉。\n香闺别来无信息，云愁雨恨难忘。\n指帝城归路，但烟水茫茫。\n凝情望断泪眼，尽日独立斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (228, '临江仙引', '柳永', '上国。\n去客。\n停飞盖、促离筵。\n长安古道绵绵。\n见岸花啼露，对堤柳愁烟。\n物情人意，向此触目，无处不凄然。\n醉拥征骖犹伫立，盈盈泪眼相看。\n况绣帏人静，更山馆春寒。\n今宵怎向漏永，顿成两处孤眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (229, '临江仙引', '柳永', '画舸、荡桨，随浪箭、隔岸虹。\n□荷占断秋容。\n疑水仙游泳，向别浦相逢。\n鲛丝雾吐渐收，细腰无力转娇慵。\n罗袜凌波成旧恨，有谁更赋惊鸿。\n想媚魂香信，算密锁瑶宫。\n游人漫劳倦□，奈何不逐东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (230, '瑞鹧鸪', '柳永', '宝髻瑶簪。\n严妆巧，天然绿媚红深。\n绮罗丛里，独逞讴吟。\n一曲阳春定价，何啻值千金。\n倾听处，王孙帝子，鹤盖成阴。\n凝态掩霞襟。\n动象板声声，怨思难任。\n嘹亮处，迥压弦管低沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (231, '瑞鹧鸪', '柳永', '吴会风流。\n人烟好，高下水际山头。\n瑶台绛阙，依约蓬丘。\n万井千闾富庶，雄压十三州。\n触处青娥画舸，红粉朱楼。\n方面委元侯。\n致讼简时丰，继日欢游。\n襦温裤暖，已扇民讴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (232, '忆帝京', '柳永', '薄衾小枕天气。\n乍觉别离滋味。\n展转数寒更，起了还重睡。\n毕竟不成眠，一夜长如岁。\n也拟待、却回征辔。\n又争奈、已成行计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (233, '塞孤', '柳永', '一声鸡，又报残更歇。\n秣马巾车催发。\n草草主人灯下别。\n山路险，新霜滑。\n瑶珂响、起栖乌，金镫冷、敲残月。\n渐西风紧，襟袖凄冽。\n遥指白玉京，望断黄金阙。\n远道何时行彻。\n算得佳人凝恨切。\n应念念，归时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (234, '瑞鹧鸪', '柳永', '天将奇艳与寒梅。\n乍惊繁杏腊前开。\n暗想花神、巧作江南信，鲜染燕脂细翦裁。\n寿阳妆罢无端饮，凌晨酒入香腮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (235, '瑞鹧鸪', '柳永', '全吴嘉会古风流。\n渭南往岁忆来游。\n西子方来、越相功成去，千里沧江一叶舟。\n至今无限盈盈者，尽来拾翠芳洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (236, '洞仙歌', '柳永', '嘉景，向少年彼此，争不雨沾云惹。\n奈傅粉英俊，梦兰品雅。\n金丝帐暖银屏亚。\n并粲枕、轻偎轻倚，绿娇红姹。\n算一笑，百明珠非价。\n闲暇。\n每祗向、洞房深处，痛怜极宠，似觉些子轻孤，早恁背人沾洒。\n从来娇纵多猜讶。\n更对翦香云，须要深心同写。\n爱了双眉，索人重画。\n忍孤艳冶。\n断不等闲轻舍。\n鸳衾下。\n愿常恁、好天良夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (237, '安公子', '柳永', '远岸收残雨。\n雨残稍觉江天暮。\n拾翠汀洲人寂静，立双双鸥鹭。\n望几点、渔灯隐映蒹葭浦。\n停画桡、两两舟人语。\n道去程今夜，遥指前村烟树。\n游宦成羁旅。\n短樯吟倚闲凝伫。\n万水千山迷远近，想乡关何处。\n自别後、风亭月榭孤欢聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (238, '安公子', '柳永', '梦觉清宵半。\n悄然屈指听银箭。\n惟有床前残泪烛，啼红相伴。\n暗惹起、云愁雨恨情何限。\n从卧来、展转千馀遍。\n恁数重鸳被，怎向孤眠不暖。\n堪恨还堪叹。\n当初不合轻分散。\n及至厌厌独自个，却眼穿肠断。\n似恁地、深情密意如何拚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (239, '长寿乐', '柳永', '繁红嫩翠。\n艳阳景，妆点神州明媚。\n是处楼台，朱门院落，弦管新声腾沸。\n恣游人、无限驰骤，娇马车如水。\n竟寻芳选胜，归来向晚，起通衢近远，香尘细细。\n太平世。\n少年时，忍把韶光轻弃。\n况有红妆，楚腰越艳，一笑千金何啻。\n向尊前、舞袖飘雪，歌响行云止。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (240, '倾杯・倾杯乐', '柳永', '水乡天气，洒蒹葭、露结寒生早。\n客馆更堪秋杪。\n空阶下、木叶飘零，飒飒声乾，狂风乱扫。\n当无绪、人静酒初醒，天外征鸿，知送谁家归信，穿云悲叫。\n蛩响幽窗，鼠窥寒砚，一点银闲照。\n梦枕频惊，愁衾半拥，万里归心悄悄。\n往事追思多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (241, '倾杯・倾杯乐', '柳永', '金风淡荡，渐秋光老、清宵永。\n小院新晴天气，轻烟乍敛，皓月当轩练净。\n对千里寒光，念幽期阻、当残景。\n早是多情多病。\n那堪细把，旧约前欢重省。\n最苦碧云信断，仙乡路杳，归鸿难倩。\n每高歌、强遣离怀，惨咽、翻成心耿耿。\n漏残露冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (242, '倾杯・倾杯乐', '柳永', '鹜落霜洲，雁横烟渚，分明画出秋色。\n暮雨乍歇。\n小楫夜泊，宿苇村山驿。\n何人月下临风处，起一声羌笛。\n离愁万绪，闻岸草、切切蛩吟如织。\n为忆。\n芳容别後，水遥山远，何计凭鳞翼。\n想绣阁深沈，争知憔悴损、天涯行客。\n楚峡云归，高阳人散，寂寞狂踪迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (243, '鹤冲天', '柳永', '黄金榜上。\n偶失龙头望。\n明代暂遗贤，如何向。\n未遂风云便，争不恣狂荡。\n何须论得丧。\n才子词人，自是白衣卿相。\n烟花巷陌，依约丹青屏障。\n幸有意中人，堪寻访。\n且恁偎红翠，风流事、平生畅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (244, '木兰花・玉楼春', '柳永', '翦裁用尽春工意。\n浅蘸朝霞千万蕊。\n天然淡泞好精神，洗尽严妆方见媚。\n风亭月榭闲相倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (245, '木兰花・玉楼春', '柳永', '东风催露千娇面。\n欲绽红深开处浅。\n日高梳洗甚时，点滴燕脂匀未遍。\n霏微雨罢残阳院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (246, '木兰花・玉楼春', '柳永', '黄金万缕风牵细。\n寒食初头春有味。\n烟尤雨索春饶，一日三眠夸得意。\n章街隋岸欢游地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (247, '倾杯乐', '柳永', '楼锁轻烟，水横斜照，遥山半隐愁碧。\n片帆岸远，行客路杳，簇一天寒色。\n楚梅映雪数枝艳，报青春消息。\n年华梦促，音信断、声远飞鸿南北。\n算伊别来无绪，翠消红减，双带长抛掷。\n但泪眼沈迷，看朱成碧。\n惹闲愁堆积。\n雨意云情，酒心花态，孤负高阳客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (248, '祭天神', '柳永', '忆绣衾相向轻轻语。\n屏山掩、红蜡长明，金兽盛熏兰炷。\n何期到此，酒态花情顿孤负。\n柔肠断、还是黄昏，那更满庭风雨。\n听空阶和漏，碎声斗滴愁眉聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (249, '鹧鸪天', '柳永', '吹破残烟入夜风。\n一轩明月上帘栊。\n因惊路远人还远，纵得心同寝未同。\n情脉脉，意忡忡。\n碧云归去认无踪。\n只应曾向前生里，爱把鸳鸯两处笼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (250, '归去来', '柳永', '一夜狂风雨。\n花英坠、碎红无数。\n垂杨漫结黄金缕。\n尽春残、萦不住。\n蝶稀蜂散知何处。\n尊酒、转添愁绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (251, '梁州令', '柳永', '梦觉纱窗晓。\n残灯掩然空照。\n因思人事苦萦牵，离愁别恨，无限何时了。\n怜深定是心肠小。\n往往成烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (252, '燕归梁', '柳永', '轻蹑罗鞋掩绛绡。\n传音耗、苦相招。\n语声犹颤不成娇。\n乍得见、两魂消。\n匆匆草草难留恋，还归去又无聊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (253, '夜半乐', '柳永', '艳阳天气，烟雨风暖，芳郊澄朗闲凝伫。\n渐妆点亭台，参差佳树。\n舞腰困力，垂杨绿映，浅桃李夭夭，嫩红无数。\n度绮燕、流莺斗双语。\n翠娥南陌簇簇，蹑影红阴，缓移娇步。\n抬粉面、韶容花光相妒。\n绛绡袖举。\n云鬟风颤，半遮檀口含羞，背人偷顾。\n竞斗草、金钗笑争赌。\n对此嘉景，顿觉消凝，惹成愁绪。\n念解佩、轻盈在何处。\n忍良时、孤负少年等闲度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (254, '清平乐', '柳永', '繁华锦烂。\n已恨归期晚。\n翠减红稀莺似懒。\n特地柔肠欲断。\n不堪尊酒频倾。\n恼人转转愁生。\n□□□□□□，多情争似无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (255, '迷神引', '柳永', '红板桥头秋光暮。\n淡月映烟方煦。\n寒溪蘸碧，绕垂杨路。\n重分飞，携纤手、泪如雨。\n波急隋堤远，片帆举。\n倏忽年华改，向期阻。\n时觉春残，渐渐飘花絮。\n好夕良天长孤负。\n洞房闲掩，小屏空、无心觑。\n指归云，仙乡杳、在何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (256, '失调名', '柳永', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (257, '爪茉莉', '柳永', '每到秋来，转添甚况味。\n金风动、冷清清地。\n残蝉噪晚，甚聒得、人心欲碎，更休道、宋玉多悲，石人、也须下泪。\n衾寒枕冷，夜迢迢、更无寐。\n深院静、月明风细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (258, '女冠子', '柳永', '火云初布。\n迟迟永日炎暑。\n浓阴高树。\n黄鹂叶底，羽毛学整，方调娇语。\n薰风时渐动，峻阁池塘，芰荷争吐。\n画梁紫燕，对对衔泥，飞来又去。\n想佳期、容易成辜负。\n共人人、同上画楼斟香醑。\n恨花无主。\n卧象床犀枕，成何情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (259, '十二时・忆少年', '柳永', '晚晴初，淡烟笼月，风透蟾光如洗。\n觉翠帐、凉生秋思。\n渐入微寒天气。\n败叶敲窗，西风满院，睡不成还起。\n更漏咽、滴破忧心，万感并生，都在离人愁耳。\n天怎知、当时一句，做得十分萦系。\n夜永有时，分明枕上，觑着孜孜地。\n烛暗时酒醒，元来又是梦里。\n睡觉来、披衣独坐，万种无情意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (260, '红窗迥', '柳永', '小园东，花共柳。\n红紫又一齐开了。\n引将蜂蝶燕和莺，成阵价、忙忙走。\n花心偏向蜂儿有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (261, '西江月', '柳永', '师师生得艳冶，香香於我情多。\n安安那更久比和。\n四个打成一个。\n幸自苍皇未款，新词写处多磨。\n几回扯了又重。\n奸字中心著我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (262, '凤凰阁', '柳永', '匆匆相见，懊恼恩情太薄。\n霎时云雨人抛却。\n教我行思坐想，肌肤如削。\n恨只恨、相违旧约。\n相思成病，那更潇潇雨落。\n断肠人在阑干角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (263, '醉垂鞭', '张先', '双蝶绣罗裙。\n东池宴。\n初相见。\n朱粉不深匀。\n闲花淡淡春。\n细看诸处好。\n人人道。\n柳腰身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (264, '醉垂鞭', '张先', '朱粉不须施。\n花枝小。\n春偏好。\n娇妙近胜衣。\n轻罗红雾垂。\n琵琶金画凤。\n双条重。\n倦眉低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (265, '南乡子', '张先', '何处可魂消。\n京口终朝两信潮。\n不管离心千叠恨，滔滔。\n催促行人动去桡。\n记得旧江皋。\n绿杨轻絮几条条。\n春水一篙残照阔，遥遥。\n有个多情立画桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (266, '南乡子', '张先', '潮上水清浑。\n棹影轻於水底云。\n去意徘徊无奈泪，衣巾。\n犹有当时粉黛痕。\n海近古城昏。\n暮角寒沙雁队分。\n今夜相思应看月，无人。\n露冷依前独掩门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (267, '菩萨蛮', '张先', '忆郎还上层楼曲。\n楼前芳草年年绿。\n绿似去时袍。\n回头风袖飘。\n郎袍应已旧。\n颜色非长久。\n惜恐镜中春。\n不如花草新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (268, '菩萨蛮', '张先', '闻人语著仙卿字。\n情恨意还须喜。\n何况草长时。\n酒前频共伊。\n娇香堆宝帐。\n月到梨花上。\n心事两人知。\n掩灯罗幕垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (269, '菩萨蛮', '张先', '夜深不至春蟾见。\n令人更更情飞乱。\n翠幕动风亭。\n时疑响屉声。\n花香闻水榭。\n几误飘衣麝。\n不忍下朱扉。\n绕廊重待伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (270, '菩萨蛮', '张先', '簟纹衫色娇黄浅。\n钗头秋叶玲珑翦。\n轻怯瘦腰身。\n纱窗病起人。\n相思魂欲绝。\n莫话新秋别。\n何处断离肠。\n西风昨夜凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (271, '踏莎行', '张先', '衾凤犹温，笼鹦尚睡。\n宿妆稀淡眉成字。\n映花避月上行廊，珠裙摺摺轻垂地。\n翠幕成波，新荷贴水。\n纷纷烟柳低还起。\n重墙绕院更重门，春风无路通深意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (272, '踏莎行', '张先', '波湛横眸，霞分腻脸。\n盈盈笑动笼香靥。\n有情未结凤楼欢，无爱把歌眉敛。\n密意欲传，娇羞未敢。\n斜偎象板还偷。\n轻轻试问借人麽，佯佯不觑云鬟点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (273, '感皇恩', '张先', '万乘靴袍御紫宸。\n挥豪敷丽藻，尽经纶。\n第名天陛首平津。\n东堂桂，重占一枝春。\n殊观耸簪绅。\n蓬山仙话重，霈恩新。\n暂时趋府冠谈宾。\n十年外，身是凤池人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (274, '西江月', '张先', '体态看来隐约，梳妆好是家常。\n檀槽初抱更安详。\n立向尊前一行。\n小打登钩怕重，尽缠绣带由长。\n娇春莺舌巧如簧。\n飞在四条弦上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (275, '庆金枝', '张先', '青螺添远山。\n两娇靥、笑时圆。\n抱云勾雪近灯看。\n妍处不堪怜。\n今生但愿无离别，花月下、绣屏前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (276, '浣溪沙', '张先', '轻屉来时不破尘。\n石榴花映石榴裙。\n有情应得撞腮春。\n夜短更难留远梦，日高何计学行云。\n树深莺过静无人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (277, '相思儿令', '张先', '春去几时还。\n问桃李无言。\n燕子归栖风紧，梨雪乱西园。\n犹有月婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (278, '师师令', '张先', '香钿宝珥。\n拂菱花如水。\n学妆皆道称时宜，粉色有、天然春意。\n蜀彩衣长胜未起。\n纵乱云垂地。\n都城池苑夸桃李。\n问东风何似。\n不须回扇障清歌，唇一点、小於珠子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (279, '山亭宴慢・山亭宴', '张先', '宴亭永昼喧箫鼓。\n倚青空、画阑红柱。\n玉莹紫微人，蔼和气、春融日煦。\n故宫池馆更楼台，约风月、今宵何处。\n湖水动鲜衣，竞拾翠、湖边路。\n落花荡漾愁空树。\n晓山静、数声杜宇。\n天意送芳菲，正黯淡、疏烟逗雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (280, '谢池春慢', '张先', '缭墙重院，时闻有、啼莺到。\n绣被掩馀寒，画幕明新晓。\n朱槛连空阔，飞絮无多少。\n径莎平，池水渺。\n日长风静，花影闲相照。\n尘香拂马，逢谢女、城南道。\n秀艳过施粉，多眉生轻笑。\n斗色鲜衣薄，碾玉双蝉小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (281, '惜双双・惜分飞', '张先', '城上层楼天边路。\n残照里、平芜绿树。\n伤远更惜春暮。\n有人还在高高处。\n断梦归云经日去。\n无计使、哀弦寄语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (282, '江南柳', '张先', '隋堤远，波急路尘轻。\n今古柳桥多送别，见人分袂亦愁生。\n何况自关情。\n斜照後，新月上西城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (283, '八宝装・八宝妆', '张先', '锦屏罗幌初睡起。\n花阴转、重门闭。\n正不寒不暖，和风细雨，困人天气。\n此时无限伤春意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (284, '一丛花令・一丛花', '张先', '伤高怀远几时穷。\n无物似情浓。\n离愁正引千丝乱，更东陌、飞絮。\n嘶骑渐遥，征尘不断，何处认郎踪。\n双鸳池沼水溶溶。\n南北小桡通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (285, '西江月', '张先', '泛泛春船载乐，溶溶湖水平桥。\n高鬟照影翠烟摇。\n白一声云杪。\n倦醉天然玉软，弄妆人惜花娇。\n风情遗恨几时消。\n不见卢郎年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (286, '感皇恩', '张先', '廊庙当时共代工。\n睢陵千里远，约过从。\n欲知宾主与谁同。\n宗枝内，黄阁旧，有三公。\n广乐起云中。\n湖山看画轴，两仙翁。\n武林嘉语几时穷。\n元丰际，德星聚，照江东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (287, '宴春台慢・宴春台', '张先', '丽日千门，紫烟双阙，琼林又报春回。\n殿阁风微，当时去燕还来。\n五侯池馆频开。\n探芳菲、走马天街。\n重帘人语，辚辚绣轩，远近轻雷。\n雕觞霞滟，翠幕云飞，楚腰舞柳，宫面妆梅。\n金猊夜暖、罗衣暗香煤。\n洞府人归，放笙歌、灯火下楼台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (288, '好事近', '张先', '月色透横枝，短叶小花无力。\n北客一声长笛，怨江南先得。\n谁教强半腊前开，多情为春忆。\n留取大家沈醉，正雨休风息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (289, '好事近', '张先', '灯烛上山堂，香雾暖生寒夕。\n前夜雪清梅瘦，已不禁轻摘。\n双歌声断宝杯空，妆光艳瑶席。\n相趁笑声归去，有随人月色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (290, '清平乐', '张先', '屏山斜展。\n帐卷红绡半。\n泥浅曲池飞海燕。\n风度杨花满院。\n云情雨意空深。\n觉来一枕春阴。\n陇上梅花落尽，江南消息沈沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (291, '清平乐', '张先', '清歌逐酒。\n腻脸生红透。\n樱小杏青寒食後。\n衣换缕金轻绣。\n画堂新月朱扉。\n严城夜鼓声迟。\n细看玉人娇面，春光不在花枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (292, '醉桃源・阮郎归', '张先', '落花浮水树临池。\n年前心眼期。\n见来无事去还思。\n如今花又飞。\n浅螺黛，淡胭脂。\n开花取次宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (293, '恨春迟', '张先', '好梦才成又断。\n日晚起、云梳鬟。\n秀脸拂新红，酒入娇眉眼，薄衣减春寒。\n红柱溪桥波平岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (294, '恨春迟', '张先', '欲借红梅荐饮。\n望陇驿、音信沈沈。\n住在柳州东岸，彼此相思，梦去难寻。\n乳燕来时花期寝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (295, '庆佳节', '张先', '莫风流。\n莫风流。\n风流後、有闲愁。\n花满南园月满楼。\n偏使我、忆欢游。\n我忆欢游无计奈，除却且醉金瓯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (296, '庆佳节', '张先', '芳菲节。\n芳菲节。\n天意应不虚设。\n对酒高歌玉壶阙。\n慎莫负、狂风月。\n人间万事何时歇。\n空赢得、鬓成雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (297, '采桑子', '张先', '水云薄薄天同色，竟日清辉。\n风影轻飞。\n花发瑶林春未知。\n剡溪不辨沙头路，粉水平堤。\n姑射人归。\n记得歌声与舞时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (298, '御街行', '张先', '画船横倚烟溪半。\n春入吴山遍。\n主人凭客且迟留，程入花溪远远。\n数声芦叶，两行霓袖，几处成离宴。\n纷纷归骑亭皋晚。\n风顺樯乌转。\n古今为别最消魂，因别有情须怨。\n更独自、尽上高台望，望尽飞云断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (299, '玉联环・解连环', '张先', '都人未逐风云散。\n愿留离宴。\n不须都爱洛城春，黄花讶、归来晚。\n叶落灞陵如翦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (300, '玉联环・解连环', '张先', '来时露衣香润。\n彩绦垂鬓。\n卷帘还喜月相亲，把酒更、花相近。\n西去阳关休问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (301, '武陵春', '张先', '秋染青溪天外水，风棹采菱还。\n波上逢郎密意传。\n语近隔丛莲。\n相看忘却归来路，遮日小荷圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (302, '定风波', '张先', '素藕抽条未放莲。\n晚蚕将茧不成眠。\n若比相思如乱絮。\n何异。\n两心俱被暗丝牵。\n暂觉欲归还是恨。\n莫问。\n有情谁信道无缘。\n有似中秋云外月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (303, '百媚娘', '张先', '珠阙五云仙子。\n未省有谁能似。\n百媚算应天乞与，净饰艳妆俱美。\n若取次芳华皆可意。\n何处比桃李。\n蜀被锦纹铺水。\n不放彩鸳双戏。\n乐事也知存後会，争奈眼前心里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (304, '梦仙乡', '张先', '江东苏小。\n夭斜窈窕。\n都不胜、彩鸾娇妙。\n春艳上新妆。\n肌肉过人香。\n佳树阴阴池院。\n华灯绣幔。\n花月好、可能长见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (305, '归朝欢', '张先', '声转辘轳闻露井。\n晓引银瓶牵素绠。\n西园人语夜来风，丛英飘坠红成径。\n宝猊烟未冷。\n莲台香蜡残痕凝。\n等身金，谁能得意，买此好光景。\n粉落轻妆红玉莹。\n月枕横钗云坠领。\n有情无物不双栖，文禽只合常交颈。\n昼长欢岂定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (306, '相思令・相思儿令', '张先', '苹满溪。\n柳绕堤。\n相送行人溪水西。\n回时陇月低。\n烟霏霏。\n风凄凄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (307, '少年游', '张先', '红叶黄花秋又老，疏雨更西风。\n山重水远，云闲天淡，游子断肠中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (308, '贺圣朝', '张先', '淡黄衫子浓妆了。\n步缕金鞋小。\n爱来书幌绿窗前，半和娇笑。\n谢家姊妹，诗名空杳。\n何曾机巧。\n争如奴道，春来情思，乱如芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (309, '生查子', '张先', '当初相见时，彼此心萧洒。\n近日见人来，却恁相谩。\n休休休便休，美底教他且。\n匹似没伊时，更不思量也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (310, '夜厌厌・夜行船', '张先', '昨夜小筵欢纵。\n烛房深、舞鸾歌凤。\n酒迷花困共厌厌，倚朱弦、未成归弄。\n峡雨忽收寻断梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (311, '迎春乐', '张先', '城头画角催夕宴。\n忆前时、小楼晚。\n残虹数尺云中断。\n愁送目、天涯远。\n枕清风、停画扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (312, '凤栖梧・蝶恋花', '张先', '密宴厌厌池馆暮。\n天汉沈沈，借得春光住。\n红翠斗为长袖舞。\n香檀拍过惊鸿翥。\n明日不知花在否。\n今夜圆蟾，後夜忧风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (313, '双燕儿', '张先', '榴花帘外飘红。\n藕丝罩、小屏风。\n东山别後，高唐梦短，犹喜相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (314, '卜算子慢', '张先', '溪山别意，烟树去程，日落采苹春晚。\n欲上征鞍，更掩翠帘相眄。\n惜弯弯浅黛长长眼。\n奈画阁欢游，也学狂花乱絮轻散。\n水影横池馆。\n对静夜无人，月高云远。\n一饷凝思，两袖泪痕还满。\n恨私书、又逐东风断。\n纵西北层楼万尺，望重城那见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (315, '更漏子', '张先', '锦筵红，罗幕翠。\n侍宴美人姝丽。\n十五六，解怜才。\n劝人深酒杯。\n黛眉长，檀口小。\n耳畔向人轻道。\n柳阴曲，是儿家。\n门前红杏花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (316, '更漏子', '张先', '相君家，宾宴集。\n秋叶晓霜红湿。\n帘额动，水纹浮。\n缬花相对流。\n薄霞衣，酣酒面。\n重抱琵琶轻按。\n回画拨，抹幺弦。\n一声飞露蝉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (317, '南歌子', '张先', '醉後和衣倒，愁来酒醺。\n困人天气近清明。\n尽日厌厌□脸、浅含颦。\n睡觉□□恨，依然月映门。\n楚天何处觅行云。\n唯有暗灯残漏、伴消魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (318, '南歌子', '张先', '蝉抱高高柳，莲开浅浅波。\n倚风疏叶下庭柯。\n况是不寒不暖、正清和。\n浮世欢会少，劳生怨别多。\n相逢休惜醉颜酡。\n赖有西园明月、照笙歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (319, '南歌子', '张先', '残照催行棹，乘春拂去衣。\n海棠花下醉芳菲。\n无计少留君住、泪双垂。\n烟染春江暮，云藏阁道危。\n行行听取杜鹃啼。\n是妾此时离恨、尽呼伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (320, '蝶恋花', '张先', '临水人家深宅院。\n阶下残花，门外斜阳岸。\n柳舞麴尘千万线。\n青楼百尺临天半。\n楼上东风春不浅。\n十二阑干，尽日珠帘卷。\n有个离人凝泪眼。\n淡烟芳草连云远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (321, '蝶恋花', '张先', '槛菊愁烟兰泣露。\n罗幕轻寒，燕子双来去。\n明月不谙离恨苦。\n斜光到晓穿朱户。\n昨夜西风雕碧树。\n独上高楼，望尽天涯路。\n欲寄彩笺兼尺素。\n山长水阔知何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (322, '蝶恋花', '张先', '绿水波平花烂漫。\n照影红妆，步转垂杨岸。\n别後深情将为断。\n相逢添得人留恋。\n絮软丝轻无系绊。\n烟惹风迎，并入春心乱。\n和泪语娇声又颤。\n行行尽远犹回面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (323, '蝶恋花', '张先', '移得绿杨栽後院。\n学舞宫腰，二月青犹短。\n不比灞陵多送远。\n残丝乱絮东西岸。\n几叶小眉寒不展。\n莫唱阳关，真个肠先断。\n分付与春休细看。\n条条尽是离人怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (324, '诉衷情', '张先', '花前月下暂相逢。\n苦恨阻从容。\n何况酒醒梦断，花谢月朦胧。\n花不尽，月无穷。\n两心同。\n此时愿作，杨柳千丝，绊惹春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (325, '诉衷情', '张先', '数枝金菊对芙蓉。\n零落意忡忡。\n不知多少幽怨，和泪泣东风。\n人散後，月明中。\n夜寒浓。\n谢娘愁卧，潘令闲眠，往事何穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (326, '木兰花・玉楼春', '张先', '青钱贴水萍无数。\n临晓西湖春涨雨。\n泥新轻燕面前飞，风慢落花衣上住。\n红裙空引烟娥聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (327, '木兰花・玉楼春', '张先', '西湖杨柳风流绝。\n满缕青春看赠别。\n墙头簌簌暗飞花，山外阴阴初落月。\n秦姬丽云梳发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (328, '木兰花・玉楼春', '张先', '楼下雪飞楼上宴。\n歌咽笙簧声韵颤。\n尊前有个好人人，十二阑干同倚遍。\n帘重不知金屋晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (329, '减字木兰花', '张先', '垂螺近额。\n走上红初趁拍。\n只恐轻飞。\n拟倩游丝惹住伊。\n文鸳绣履。\n去似杨花尘不起。\n舞彻伊州。\n头上宫花颤未休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (330, '少年游', '张先', '碎霞浮动晓朦胧。\n春意与花浓。\n银瓶素绠，玉泉金，真色浸朝红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (331, '少年游', '张先', '帽檐风细马蹄尘。\n常记探花人。\n露英千样，粉香无尽，蓦地酒初醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (332, '醉落魄・一斛珠', '张先', '云轻柳弱。\n内家髻要新梳掠。\n生香真色人难学。\n横管孤吹，月淡天垂暮。\n朱唇浅破桃花萼。\n倚楼谁在阑干角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (333, '喜朝天・踏莎行', '张先', '晓云开。\n睨仙馆陵虚，步入蓬莱。\n玉宇琼，对青林近，归鸟徘徊。\n风月顿消清暑，野色对、江山助诗才。\n潇鼓宴，璇题宝字，浮动持杯。\n人多送目天际，识渡舟帆小，时见潮回。\n故国千里，共十万室，日日春台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (334, '破阵乐', '张先', '四堂互映，双门并丽，龙阁开府。\n郡美东南第一，望故苑、楼台霏雾。\n垂柳池塘，流泉巷陌，吴歌处处。\n近黄昏，渐更宜良夜，簇簇繁星灯烛，长衢如昼，暝色韶光，几许粉面，飞甍朱户。\n和煦。\n雁齿桥红，裙腰草绿，云际寺、林下路。\n酒熟梨花宾客醉，但觉满山潇鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (335, '菊花新', '张先', '堕髻慵妆来日暮。\n家在画桥堤下住。\n衣缓绛绡垂，琼树袅、一枝红雾。\n院深池静娇相妒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (336, '虞美人', '张先', '苕花飞尽汀风定。\n苕水天摇影。\n画船罗绮满溪春。\n一曲石城清响、入高云。\n壶觞昔岁同歌舞。\n今日无欢侣。\n南园花少故人稀。\n月照玉楼依旧、似当时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (337, '醉红妆', '张先', '琼枝玉树不相饶。\n薄云衣、细柳腰。\n一般妆样百般娇。\n眉眼细、好如描。\n东风摇草百花飘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (338, '天仙子', '张先', '水调数声持酒听。\n午醉醒来愁未醒。\n送春春去几时回，临晚镜。\n伤流景。\n往事後期空记省。\n沙上并禽池上暝。\n云破月来花弄影。\n重重帘幕密遮灯，风不定。\n人初静。\n明日落红应满径。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (339, '天仙子', '张先', '持节来时初有雁。\n十万人家春已满。\n龙标名第凤池身，堂阜远。\n江桥晚。\n一见湖山看未遍。\n障扇欲收歌泪溅。\n亭下花空罗绮散。\n樯竿渐向望中疏，旗影转。\n鼙声断。\n惆怅不如船尾燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (340, '菩萨蛮', '张先', '玉人又是匆匆去。\n马蹄何处垂杨路。\n残日倚楼时。\n断魂郎未知。\n阑干移倚遍。\n薄教人怨。\n明月却多情。\n随人处处行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (341, '怨春风・一斛珠', '张先', '无由且住。\n绵绵恨似春蚕绪。\n见来时饷还须去。\n月浅灯收，多在偷期处。\n今夜掩妆花下语。\n明朝芳草东西路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (342, '于飞乐令・于飞乐', '张先', '宝奁开，菱鉴静，一掏清蟾。\n新妆脸、旋学花添。\n蜀红衫，双绣蝶，裙缕鹣鹣。\n寻思前事，小屏风、巧画江南。\n怎空教、草解宜男。\n柔桑暗、又过春蚕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (343, '临江仙', '张先', '自古伤心惟远别，登山临水迟留。\n暮尘衰草一番秋。\n寻常景物，到此尽成愁。\n况与佳人分凤侣，盈盈粉泪难收。\n高城深处是青楼。\n红尘远道，明日忍回头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (344, '江城子', '张先', '镂牙歌板齿如犀。\n串珠齐。\n画桥西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (345, '转声虞美人・桃源忆故人', '张先', '使君欲醉离亭酒。\n酒醒离愁转有。\n紫禁多时虚右。\n苕霄留难久。\n一声歌掩双罗袖。\n日落乱山春後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (346, '燕归梁', '张先', '去岁中秋玩桂轮。\n河汉净无云。\n今年江上共瑶尊。\n都不是、去年人。\n水精宫殿，琉璃台阁，红翠两行分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (347, '燕归梁', '张先', '夜月啼乌促乱弦。\n江树远无烟。\n缺多圆少奈何天。\n愁只恐、下关山。\n粉香生润，衣珠弄彩，人月两蝉娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (348, '定西番', '张先', '年少登瀛词客，飘逸气，拂晴霓。\n尽带江南春色、过长淮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (349, '河传', '张先', '花暮。\n春去。\n都门东路。\n嘶马将行。\n江南江北，十里五里邮亭。\n几程程。\n高城望远看回睇。\n烟细。\n晚碧空无际。\n今夜何处，冷落衾帏。\n欲眠时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (350, '偷声木兰花', '张先', '雪笼琼苑梅花瘦。\n外院重扉联宝兽。\n海月新生。\n上得高楼无奈情。\n帘波不动凝小。\n今夜夜长争得晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (351, '偷声木兰花', '张先', '画桥浅映横塘路。\n流水滔滔春共去。\n目送残晖。\n燕子双高蝶对飞。\n风花将尽持杯送。\n往事只成清夜梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (352, '醉桃源・阮郎归', '张先', '双花连袂近香猊。\n歌随镂板齐。\n分明珠索漱烟溪。\n凝云定不飞。\n唇破点，齿编犀。\n春莺莫乱啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (353, '千秋岁', '张先', '数声。\n又报芳菲歇。\n惜春更把残红折。\n雨轻风色暴，梅子青时节。\n永丰柳，无人尽日飞花雪。\n莫把幺弦拨。\n怨极弦能说。\n天不老，情难绝。\n心似双丝网，中有千千结。\n夜过也，东窗未白凝残月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (354, '天仙子', '张先', '醉笑相逢能几度。\n为报江头春且住。\n主人今日是行人，红袖舞。\n清歌女。\n凭仗东风教点取。\n三月柳枝柔似缕。\n落絮尽飞还恋树。\n有情宁不忆西园，莺解语。\n花无数。\n应讶使君何处去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (355, '渔家傲', '张先', '巴子城头青草暮。\n巴山重叠相逢处。\n燕子占巢花脱树。\n杯且举。\n瞿塘水阔舟难渡。\n天外吴门清路。\n君家正在吴门住。\n赠我柳枝情几许。\n春满缕。\n为君将入江南去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (356, '天仙子', '张先', '十岁手如芽子笋。\n固爱弄妆偷傅粉。\n金蕉并为舞时空，红脸嫩。\n轻衣褪。\n春重日浓花觉困。\n斜雁轧弦随步趁。\n小凤累珠光绕鬓。\n密教持履恐仙飞，催拍紧。\n惊鸿奔。\n风袂飘摇无定准。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (357, '天仙子', '张先', '坐治吴州成乐土。\n诏卷风飞来圣语。\n亲舆乞得便藩归，瑶席主。\n杯休数。\n清夜为君歌白苎。\n花接旧枝新蕊吐。\n造化不知人有助。\n看花岁岁比甘棠，嘉月暮。\n东门路。\n只恐带将春色去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (358, '南乡子', '张先', '相并细腰身。\n时样宫妆一样新。\n曲项胡琴鱼尾拨，离人。\n入塞弦声水上闻。\n天碧染衣巾。\n血色轻罗碎摺裙。\n百卉已随霜女妒，东君。\n暗折双花借小春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (359, '少年游', '张先', '听歌持酒且休行。\n云树几程程。\n眼看檐牙，手搓花蕊，未必两无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (360, '定风波令・定风波', '张先', '碧玉篦扶坠髻云。\n莺黄衫子退红裙。\n妆样巧将花草竞。\n相并。\n要教人意胜於春。\n酒眼茸茸香拂面。\n□见。\n丹青宁似镜中真。\n自是有情偏小小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (361, '定风波令・定风波', '张先', '浴殿词臣亦议兵。\n禁中颇牧党羌平。\n诏卷促归难自缓。\n溪馆。\n彩花千数酒泉清。\n春草未青秋叶暮。\n□去。\n一家行色万家情。\n可恨黄莺相识晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (362, '定风波令・定风波', '张先', '谈辨才疏堂上兵。\n画船齐岸暗潮平。\n万乘靴袍曾好问。\n须信。\n文章传口齿牙清。\n三百寺应游未遍。\n□算。\n湖山风物岂无情。\n不独渠丘歌叔度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (363, '定风波令・定风波', '张先', '西阁明呈奉诏行。\n南床吏部锦衣荣。\n中有瀛仙宾与主。\n相遇。\n平津选首更神清。\n溪上玉楼同宴喜。\n欢醉。\n对堤杯叶惜秋英。\n尽道贤人聚吴分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (364, '木兰花・玉楼春', '张先', '人意共怜花月满。\n花好月圆人又散。\n欢情去逐远云空，往事过如幽梦断。\n草树争春红影乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (365, '木兰花・玉楼春', '张先', '相离徒有相逢梦。\n门外马蹄尘已动。\n怨歌留待醉时听，远目不堪空际送。\n今宵风月知谁共。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (366, '木兰花・玉楼春', '张先', '檀槽碎响金丝拨。\n露湿浔阳江上月。\n不知商妇为谁愁，一曲行人留晚发。\n画堂花入新声别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (367, '木兰花・玉楼春', '张先', '插花劝酒盐桥馆。\n召节促行龙阙远。\n吴船渐起晚潮生，蛮未空寒日短。\n庆门奕世隆宸眷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (368, '木兰花・玉楼春', '张先', '去年春入芳菲国。\n青蕊如梅终忍摘。\n阑边徒欲说相思，绿蜡密缄朱粉饰。\n归来故苑重寻觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (369, '木兰花・玉楼春', '张先', '龙头舴艋吴儿竞。\n笋柱秋千游女并。\n芳洲拾翠暮忘归，秀野踏青来不定。\n行云去後遥山暝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (370, '木兰花・玉楼春', '张先', '轻牙低掌随声听。\n合调破空云自凝。\n姝娘翠黛有人描，琼女分鬟待谁并。\n弄妆俱学闲心性。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (371, '倾杯・倾杯乐', '张先', '横塘水静，花窥影、孤城转。\n浮玉无尘，五亭争景，画桥对起，垂虹不断。\n爱溪上琼楼，凭雕栏、久□飞云远。\n人在虚空，月生溟海，寒渔夜泛，游鳞可辨。\n正是草长苹老，江南地暖。\n汀洲日晚。\n更茶山、已过清明，风雨暴千岩、啼鸟怨。\n芳菲故苑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (372, '倾杯・倾杯乐', '张先', '飞云过尽，明河浅、天无畔。\n草色栖萤，霜华清暑，轻弄袂，澄澜拍岸。\n宴玉麈谈宾，倚琼枝、秀挹雕觞满。\n午夜中秋，十分圆月，香槽拨凤，朱弦轧雁。\n正是欲醒还醉，临空怅远。\n壶更叠换。\n对东西、数里回塘，恨零落芙蓉、春不管。\n笼灯待散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (373, '离亭宴', '张先', '捧黄封诏卷。\n随处是、离亭别宴。\n红翠成轮歌未遍。\n已恨野桥风便。\n此去济南非久，惟有凤池鸾殿。\n三月花飞几片。\n又减却、芳菲过半。\n千里恩深云海浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (374, '沁园春', '张先', '心膂良臣，帷幄元勋，左右万几。\n暂武林分阃，东南外翰，锦衣乡社，未满瓜时。\n易镇梧台，宣条期岁，又西指夷桥千骑移。\n珠滩上，喜甘棠翠荫，依旧春晖。\n须知。\n系国安危。\n料节召、还趋浴凤池。\n且代工施化，持钧播泽，置盂天下，此外何思。\n素卷书名，赤松游道，飙驭云仙可期。\n湖山美，有啼猿唳鹤，相望东归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (375, '感皇恩', '张先', '延寿芸香七世孙。\n华轩承大对，见经纶。\n溟鱼一息化天津。\n袍如草，三百骑，从清尘。\n玉树莹风神。\n同时棠棣萼，一家春。\n十年身是凤池人。\n蓬莱阁，黄合主，迟谈宾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (376, '忆秦娥', '张先', '参差竹。\n吹断相思曲。\n情不足。\n西北有楼穷远目。\n忆苕溪、寒影透清玉。\n秋雁南飞速。\n菰草绿。\n应下溪头沙上宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (377, '系裙腰', '张先', '惜霜蟾照夜云天。\n朦胧影、画勾阑。\n人情纵是长情月，算一年年。\n又能得、几番圆。\n欲寄西江题叶字，流不到、五亭前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (378, '清平乐', '张先', '青袍如草。\n得意还年少。\n马跃绿螭金络脑。\n寒食乍临新晓。\n曲池斜度鸾桥。\n西园一片笙箫。\n自欲剩留春住，风花无奈飘飘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (379, '偷声木兰花', '张先', '曾居别乘康吴俗。\n民到於今歌不足。\n骊驭征鞭。\n一去东风十二年。\n重来却拥诸侯骑。\n宝带垂鱼金照地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (380, '菩萨蛮', '张先', '佳人学得平阳曲。\n纤纤玉笋横孤竹。\n一弄入云声。\n海门江月清。\n髻摇金钿落。\n惜恐樱唇薄。\n听罢已依依。\n莫吹杨柳枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (381, '菩萨蛮', '张先', '藕丝衫翦猩红窄。\n衫轻不碍琼肤白。\n缦鬓小横波。\n花楼东是家。\n上湖闲荡桨。\n粉艳芙蓉样。\n湖水亦多情。\n照妆天底清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (382, '菩萨蛮', '张先', '牛星织女年年别。\n分明不及人间物。\n匹鸟少孤飞。\n断沙犹并栖。\n洗车昏雨过。\n缺月云中堕。\n斜汉晓依依。\n暗蛩还促机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (383, '菩萨蛮', '张先', '双针竞引双丝缕。\n家家尽道迎牛女。\n不见渡河时。\n空闻乌鹊飞。\n西南低片月。\n应恐云梳发。\n寄语问星津。\n谁为得巧人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (384, '庆春泽', '张先', '飞阁危桥相倚。\n人独立东风，满衣轻絮。\n还记忆江南，如今天气。\n正白苹花，绕堤涨流水。\n寒梅落尽谁寄。\n方春意无穷，青空千里。\n愁草树依依，关城初闭。\n对月黄昏，角声傍烟起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (385, '庆春泽', '张先', '艳色不须妆样。\n风韵好天真，画毫难上。\n花影滟金尊，酒泉生浪。\n镇欲留春，傍花为春唱。\n银塘玉宇空旷。\n冰齿映轻唇，蕊红新放。\n声宛转，疑随烟香悠扬。\n对暮林静，寥寥振清响。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (386, '玉联环・解连环', '张先', '南园已恨归来晚。\n芳菲满眼。\n春工偏上好花多，疑不向、空枝暖。\n惜恐红云易散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (387, '玉树后庭花・后庭花', '张先', '华灯火树红相斗。\n往来如昼。\n桥河水白天青，讶别生星斗。\n落梅李还依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (388, '玉树后庭花・后庭花', '张先', '宝床香重春眠觉。\n窗难晓。\n新声丽色千人，歌後庭清妙。\n青骢一骑来飞鸟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (389, '卜算子', '张先', '梦断寒夜长，坐待清霜晓。\n临镜无人为整妆，但自学、孤鸾照。\n楼台红树杪。\n风月依前好。\n江水东流郎在西，问尺素、何由到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (390, '双韵子', '张先', '鸣鞘电过晓闱静。\n敛龙旗风定。\n凤楼远出霏烟，闻笑语、中天迥。\n清光近。\n欢声竟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (391, '鹊桥仙', '张先', '星桥火树，长安一夜，开遍红莲万蕊。\n绮罗能借月中春，风露细、天清似水。\n重城闭月，青楼夸乐，人在银潢影里。\n画屏期约近收灯，归步急、双鸳欲起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (392, '醉垂鞭', '张先', '酒面滟金鱼。\n吴娃唱。\n吴潮上。\n玉殿白麻书。\n待君归後除。\n勾留风月好。\n平湖晓。\n翠峰孤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (393, '定西番', '张先', '秀眼谩生千媚，钗玉重，髻云低。\n寂寂挹妆羞泪，怨分携。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (394, '定西番', '张先', '焊拨紫槽金衬，双秀萼，两回鸾。\n齐学汉宫妆样，竞蝉娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (395, '望江南・忆江南', '张先', '青楼宴，靓女荐瑶杯。\n一曲白云江月满，际天拖练夜潮来。\n人物误瑶台。\n醺醺酒，拂拂上双腮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (396, '少年游慢', '张先', '春城三二月。\n禁柳飘绵未歇。\n仙生香，轻云凝紫，临层阙。\n歌掌明珠滑。\n酒脸红霞发。\n华省名高，少年得意时节。\n画刻三题彻。\n梯汉同登蟾窟。\n玉殿初宣，银袍齐脱，生仙骨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (397, '翦牡丹', '张先', '野绿连空，天青垂水，素色溶漾都净。\n柔柳摇摇，坠轻絮无影。\n汀洲日落人归，修巾薄袂，撷香拾翠相竞。\n如解凌波，泊烟渚春暝。\n采绦朱索新整。\n宿绣屏、画船风定。\n金凤响双槽，弹出今古幽思谁省。\n玉盘大小乱珠迸。\n酒上妆面，花艳媚相并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (398, '画堂春', '张先', '外潮莲子长参差。\n霁山青处鸥飞。\n水天溶漾画桡迟。\n人影鉴中移。\n桃叶浅声双唱，杏红深色轻衣。\n小荷障面避斜晖。\n分得翠阴归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (399, '芳草渡・系裙腰', '张先', '双门晓锁响朱扉。\n千骑拥、万人随。\n风乌弄影画船移。\n歌时泪，和别怨，作秋悲。\n寒潮小，渡淮迟。\n吴越路、渐天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (400, '芳草渡・系裙腰', '张先', '主人宴客玉楼西。\n风飘雪、忽氛霏。\n唐昌花蕊渐平枝。\n浮光里，寒声聚，队禽栖。\n惊晓日，喜春迟。\n野桥时伴梅飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (401, '御街行', '张先', '夭非花艳轻非雾。\n来夜半、天明去。\n来如春梦不多时，去似朝云何处。\n远鸡栖燕，落星沈月，城头鼓。\n参差渐辨西池树。\n珠阁斜开户。\n绿苔深径少人行，苔上屐痕无数。\n馀香遗粉，剩衾闲枕，天把多情付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (402, '苏幕遮', '张先', '柳飞绵，花实少。\n镂板音清，浅发江南调。\n斜日两竿留碧□。\n马足重重，又近青门道。\n去尘浓，人散了。\n回首旗亭，渐渐红裳小。\n莫讶安仁头白早。\n天若有情，天也终须老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (403, '武陵春', '张先', '每见韶娘梳鬓好，钗燕傍云飞。\n谁掬彤霞露染衣。\n□玉透柔肌。\n梅花瘦雪梨花雨，心眼未芳菲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (404, '醉落魄・一斛珠', '张先', '山围画障。\n风溪弄月清溶漾。\n玉楼苕馆人相望。\n下若醅，竞欲金钗当。\n使君劝醉青娥唱。\n分明仙曲云中响。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (405, '长相思', '张先', '粉艳明。\n秋水盈。\n柳样纤柔花样轻。\n笑前双靥生。\n寒江平。\n江橹鸣。\n谁道潮沟非远行。\n回头千里情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (406, '更漏子', '张先', '杜陵春，秦树晚。\n伤别更堪临远。\n南去信，欲凭谁。\n归鸿多北归。\n小桃枝，红蓓发。\n今夜昔时风月。\n休苦意，说相思。\n少情人不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (407, '浣溪沙', '张先', '楼倚春江百尺高。\n烟中还未见归桡。\n几时期信似江潮。\n花片片飞风弄蝶，柳阴阴下水平桥。\n日长才过又今宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (408, '醉桃源・阮郎归', '张先', '仙郎何日是来期。\n无心云胜伊。\n行云犹解傍山飞。\n郎行去不归。\n强匀画，又芳菲。\n春深轻薄衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (409, '行香子', '张先', '舞雪歌云。\n闲淡妆匀。\n蓝溪水、深染轻裙。\n酒香醺脸，粉色生春。\n更巧谈话，美情性，好精神。\n江空无畔，凌波何处，月桥边、青柳朱门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (410, '熙州慢', '张先', '武林乡，占第一湖山，咏画争巧。\n鹫石飞来，倚翠楼烟霭，清猿啼晓。\n况值禁垣师帅，惠政流入欢谣。\n朝暮万景，寒潮弄月，乱峰回照。\n天使寻春不早。\n并行乐，免有花愁花笑。\n持酒更听，红儿肉声长调。\n潇湘故人未归，但目送游云孤鸟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (411, '虞美人', '张先', '恩如明月家家到。\n无处无清照。\n一帆秋色共云遥。\n眼力不知人远、上江桥。\n愿君书札来双鲤。\n古汴东流水。\n宋王台畔楚宫西。\n正是节趣归路、近沙堤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (412, '泛清苕', '张先', '绿净无痕，过晓霁清苕，镜里游人。\n红柱巧，彩船稳，当筵主、秘馆词臣。\n吴娃劝饮韩娥唱，竞艳容、左右皆春。\n学为行雨，傍画桨，从教水溅罗裙。\n溪烟混月黄昏。\n渐楼台上下，火影星分。\n飞槛倚，斗牛近，响箫鼓、远破重云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (413, '惜琼花', '张先', '汀苹白。\n苕水碧。\n每逢花驻乐，随处欢席。\n别时携手看春色。\n萤火而今，飞破秋夕。\n旱河流，如带窄。\n任身轻似叶，何计归得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (414, '河满子', '张先', '溪女送花随处，沙鸥避乐分行。\n游舸已如图障里，小屏犹画潇湘。\n人面新生酒艳，日痕更欲春长。\n衣上交枝斗色，钗头比翼相双。\n片段落霞明水底，风纹时动妆光。\n宾从夜归无月，千灯万火河塘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (415, '劝金船', '张先', '流泉宛转双开窦。\n带染轻纱皱。\n何人暗得金船酒。\n拥罗绮前後。\n绿定见花影，并照与、艳妆争秀。\n行尽曲名，休更再歌杨柳。\n光生飞动摇琼。\n隔障笙箫奏。\n须知短景欢无足，又还过清昼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (416, '庆同天・河传', '张先', '海宇，称庆。\n复生元圣。\n风入南薰。\n拜恩遥阙，衣上晓色犹春。\n望尧云。\n游钧广乐人疑梦。\n仙声共。\n日转旗光动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (417, '江城子', '张先', '小圆珠串静慵拈。\n夜厌厌。\n下重帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (418, '雨中花令', '张先', '近鬓彩钿云雁细。\n好客艳、花枝争媚。\n学双燕、同栖还并翅。\n我合著、你难分离。\n这佛面、前生应布施。\n你更看、蛾眉下秋水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (419, '汉宫春', '张先', '红粉苔墙。\n透新春消息，梅粉先芳。\n奇葩异卉，汉家宫额涂黄。\n何人斗巧，运紫檀、翦出蜂房。\n应为是、中央正色，东君别与清香。\n仙姿自称霓裳。\n更孤标俊格，非雪凌霜。\n黄昏院落，为谁密解罗囊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (420, '青门引・青门饮', '张先', '乍暖还轻冷。\n风雨晚来方定。\n庭轩寂寞近清明，残花中酒，又是去年病。\n楼头画角风吹醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (421, '满江红', '张先', '飘尽寒梅，笑粉蝶游蜂未觉。\n渐迤逦、水明山秀，暖生帘幕。\n过雨小桃红未透，舞烟新柳青犹弱。\n记画桥深处水边亭，曾偷约。\n多少恨，今犹昨。\n愁和闷，都忘却。\n拼从前烂醉，被花迷著。\n晴鸽试铃风力软，雏莺弄舌春寒薄。\n但只愁、锦绣闹妆时，东风恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (422, '西江月', '张先', '肃肃侯清慎，温温契知诗。\n能推恻隐救民饥。\n况乃义方教子。\n宪府两飞鹗荐，士林竞赋怀辞。\n天门正美可前知。\n入侍钧天从此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (423, '塞垣春', '张先', '野树秋声满。\n对雨壁、风灯乱。\n云低翠帐，烟销素被，签动重幔。\n甚客怀、先自无消遣。\n更篱落、秋虫叹。\n叹樊川、风流减。\n旧欢难得重见。\n停酒说扬州，平山月、应照棋观。\n绿绮为谁弹，空传广陵散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (424, '浪淘沙', '张先', '肠断送韶华。\n为惜杨花。\n雪球摇曳逐风斜。\n容易著人容易去，飞过谁家。\n聚散苦咨嗟。\n无计留他。\n行人洒泪滴流霞。\n今日画堂歌舞地，明日天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (425, '望江南・忆江南', '张先', '香闺内、空自想佳期。\n独步花阴情绪乱，谩将珠泪两行垂。\n胜会在何时。\n厌厌病，此夕最难持。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (426, '碧牡丹', '张先', '步帐摇红绮。\n晓月堕，沈烟砌。\n缓板香檀，唱彻伊家新制。\n怨入眉头，敛黛峰横翠。\n芭蕉寒，雨声碎。\n镜华翳。\n闲照孤鸾戏。\n思量去时容易。\n钿盒瑶钗，至今冷落轻弃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (427, '山亭宴', '张先', '碧波落日寒烟聚，望遥山、迷离红树。\n小艇载人来，约尊酒、商量歧路。\n衰柳断桥西，共携手、攀条无语。\n水际见凫，一对对、眠沙溆。\n西陵松柏青如故。\n翦烟花、幽兰啼露。\n油壁间花骢，那禁得、风吹细雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (428, '谒金门', '晏殊', '秋露坠。\n滴尽楚兰红泪。\n往事旧欢何限意。\n思量如梦寐。\n人貌老于前岁。\n风月宛然无异。\n座有嘉宾尊有桂。\n莫辞终夕醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (429, '破阵子', '晏殊', '海上蟠桃易熟，人间好月长圆。\n惟有掰钗分钿侣，离别常多会面难。\n此情须问天。\n蜡烛到明垂泪，熏炉尽日生烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (430, '破阵子', '晏殊', '燕子欲归时节，高楼昨夜西风。\n求得人间成小会，试把金尊傍菊丛。\n歌长粉面红。\n斜日更穿帘幕，微凉渐入梧桐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (431, '破阵子', '晏殊', '忆得去年今日，黄花已满东篱。\n曾与玉人临小槛，共折香英泛酒卮。\n长条插鬓垂。\n人貌不应迁换，珍丛又睹芳菲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (432, '破阵子', '晏殊', '湖上西风斜日，荷花落尽红英。\n金菊满丛珠颗细，海燕辞巢翅羽轻。\n年年岁岁情。\n美酒一杯新熟，高歌数阕堪听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (433, '浣溪沙', '晏殊', '阆苑瑶台风露秋。\n整鬟凝思捧觥筹。\n欲归临别强迟留。\n月好谩成孤枕梦，酒阑空得两眉愁。\n此时情绪悔风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (434, '浣溪沙', '晏殊', '三月和风满上林。\n牡丹妖艳直千金。\n恼人天气又春阴。\n为我转回红脸面，向谁分付紫檀心。\n有情须酒杯深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (435, '浣溪沙', '晏殊', '青杏园林著酒香。\n佳人初试薄罗裳。\n柳丝无力燕飞忙。\n乍雨乍晴花自落，闲愁闲闷日偏长。\n为谁消瘦减容光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (436, '浣溪沙', '晏殊', '一曲新词酒一杯。\n去年天气旧亭台。\n夕阳西下几时回。\n无可奈何花落去，似曾相识燕归来。\n小园香径独徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (437, '浣溪沙', '晏殊', '红蓼花香夹岸稠。\n绿波春水向东流。\n小船轻舫好追游。\n渔父酒醒重拨棹，鸳鸯飞去却回头。\n一杯销尽两眉愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (438, '浣溪沙', '晏殊', '淡淡梳妆薄薄衣。\n天仙模样好容仪。\n旧欢前事入颦眉。\n闲役梦魂孤烛暗，恨无消息画帘垂。\n且留双泪说相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (439, '浣溪沙', '晏殊', '小阁重帘有燕过。\n晚花红片落庭莎。\n曲阑干影入凉波。\n一霎好风生翠幕，几回疏雨滴圆荷。\n酒醒人散得愁多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (440, '浣溪沙', '晏殊', '宿酒才醒厌玉卮。\n水沈香冷懒熏衣。\n早梅先绽日边枝。\n寒雪寂寥初散後，春风悠扬欲来时。\n小屏闲放画帘垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (441, '浣溪沙', '晏殊', '绿叶红花媚晓烟。\n黄蜂金蕊欲披莲。\n水风深处懒回船。\n可惜异香珠箔外，不辞清唱玉尊前。\n使星归觐九重天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (442, '浣溪沙', '晏殊', '湖上西风急暮蝉。\n夜来清露湿红莲。\n少留归骑促歌筵。\n为别莫辞金盏酒，入朝须近玉炉烟。\n不知重会是何年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (443, '浣溪沙', '晏殊', '杨柳阴中驻彩旌。\n芰荷香里劝金觥。\n小词流入管弦声。\n只有醉饮宽别恨，不须朝暮促归程。\n雨条烟叶系人情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (444, '浣溪沙', '晏殊', '一向年光有限身。\n等闲离别易消魂。\n酒筵歌席莫辞频。\n满目山河空念远，落花风雨更伤春。\n不如怜取眼前人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (445, '浣溪沙', '晏殊', '玉碗冰寒滴露华。\n粉融香雪透轻纱。\n晚来妆面胜荷花。\n鬓欲迎眉际月，酒红初上脸边霞。\n一场春梦日西斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (446, '更漏子', '晏殊', '华浓，山翠浅。\n一寸秋波如剪。\n红日永，绮筵开。\n暗随仙驭来。\n遏云声，回雪袖。\n占断晓莺春柳。\n才送目，又颦眉。\n此情谁得知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (447, '更漏子', '晏殊', '塞鸿高，仙露满。\n秋入银河清浅。\n逢好客，且开眉。\n盛年能几时。\n宝筝调，罗袖软。\n拍碎画堂檀板。\n须尽醉，莫推辞。\n人生多别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (448, '更漏子', '晏殊', '雪藏梅，烟著柳。\n依约上春时候。\n初送雁，欲问莺。\n绿池波浪生。\n探花开，留客醉。\n忆得去年情味。\n金盏酒，玉炉香。\n任他红日长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (449, '更漏子', '晏殊', '菊花残，梨叶堕。\n可惜良辰虚过。\n新酒熟，绮筵开。\n不辞红玉杯。\n蜀弦高，羌管脆。\n慢舞娥香袂。\n君莫笑，醉乡人。\n熙熙长似春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (450, '鹊踏枝・蝶恋花', '晏殊', '槛菊愁烟兰泣露。\n罗幕轻寒，燕子双飞去。\n明月不谙离恨苦。\n斜光到晓穿朱户。\n昨夜西风凋碧树。\n独上高楼，望尽天涯路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (451, '鹊踏枝・蝶恋花', '晏殊', '紫府群仙名籍秘。\n五色斑龙，暂降人间世。\n海变桑田都不记。\n蟠桃一熟三千岁。\n露滴彩旌云绕袂。\n谁信壶中，别有笙歌地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (452, '点绛唇', '晏殊', '露下风高，井梧宫簟生秋意。\n画堂筵启。\n一曲呈珠缀。\n天外行云，欲去凝香袂。\n炉烟起。\n断肠声里。\n敛尽双蛾翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (453, '凤衔杯', '晏殊', '青苹昨夜秋风起。\n无限个、露莲相倚。\n独凭朱阑、愁望晴天际。\n空目断、遥山翠。\n彩笺长，锦书细。\n谁信道、两情难寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (454, '凤衔杯', '晏殊', '留花不住怨花飞。\n向南园、情绪依依。\n可惜倒红斜白、一枝枝。\n经宿雨、又离披。\n凭朱槛，把金卮。\n对芳丛、惆怅多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (455, '凤衔杯', '晏殊', '柳条花恼青春。\n更那堪、飞絮纷纷。\n一曲细丝清脆、倚朱唇。\n斟绿酒、掩红巾。\n追往事，惜芳辰。\n暂时间、留住行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (456, '清平乐', '晏殊', '春花秋草。\n只是催人老。\n总把千山眉黛扫。\n未抵别愁多少。\n劝君绿酒金杯。\n莫嫌丝管声催。\n兔走乌飞不住，人生几度三台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (457, '清平乐', '晏殊', '秋光向晚。\n小阁初开宴。\n林叶殷红犹未遍。\n雨後青苔满院。\n萧娘劝我金卮。\n殷勤更唱新词。\n暮去朝来节老，人生不饮何为。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (458, '清平乐', '晏殊', '春来秋去。\n往事知何处。\n燕子归飞兰泣露。\n光景千留不住。\n酒阑人散忡忡。\n闲阶独倚梧桐。\n记得去年今日，依前黄叶西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (459, '清平乐', '晏殊', '金风细细。\n叶叶梧桐坠。\n绿酒初尝人易醉。\n一枕小窗浓睡。\n紫微朱槿花残。\n斜阳却照阑干。\n双燕欲归时节，银屏昨夜微寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (460, '清平乐', '晏殊', '红笺小字。\n说尽平生意。\n鸿雁在云鱼在水。\n惆怅此情难寄。\n斜阳独倚西楼。\n遥山恰对帘钩。\n人面不知何处，绿波依旧东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (461, '红窗听', '晏殊', '淡薄梳妆轻结束。\n天意与、脸红眉绿。\n断环书素传情久，许双飞同宿。\n一饷无端分比目。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (462, '红窗听', '晏殊', '记得香闺临别语。\n彼此有、万重心诉。\n淡云轻霭知多少，隔桃源无处。\n梦觉相思天欲曙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (463, '采桑子', '晏殊', '春风不负东君信，遍拆群芳。\n燕子双双。\n依旧衔泥入杏梁。\n须知一盏花前酒，占得韶光。\n莫话匆忙。\n梦里浮生足断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (464, '采桑子', '晏殊', '红英一树春来早，独占芳时。\n我有心期。\n把酒攀条惜绛蕤。\n无端一夜狂风雨，暗落繁枝。\n蝶怨莺悲。\n满眼春愁说向谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (465, '采桑子', '晏殊', '阳和二月芳菲遍，暖景溶溶。\n戏蝶游蜂。\n深入千花粉艳中。\n何人解系天边日，占取春风。\n免使繁红。\n一片西飞一片东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (466, '采桑子', '晏殊', '樱桃谢了梨花发，红白相催。\n燕子归来。\n几处风帘绣户开。\n人生乐事知多少，且酌金杯。\n管咽弦哀。\n慢引萧娘舞袖回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (467, '采桑子', '晏殊', '古罗衣上金针样，绣出芳妍。\n玉砌朱阑。\n紫艳红英照日鲜。\n佳人画阁新妆了，对立丛边。\n试摘婵娟。\n贴向眉心学翠钿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (468, '采桑子', '晏殊', '时光只解催人老，不信多情。\n长恨离亭。\n泪滴春衫酒易醒。\n梧桐昨夜西风急，淡月胧明。\n好梦频惊。\n何处高楼雁一声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (469, '采桑子', '晏殊', '林间摘遍双双叶，寄与相思。\n朱槿开时。\n尚有山榴一两枝。\n荷花欲绽金莲子，半落红衣。\n晚雨微微。\n待得空梁宿燕归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (470, '喜迁莺', '晏殊', '风转蕙，露催莲。\n莺语尚绵蛮。\n尧随月欲团圆。\n真驭降荷兰。\n褰油幕。\n调清乐。\n四海一家同乐。\n千官心在玉炉香。\n圣寿祝天长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (471, '喜迁莺', '晏殊', '歌敛黛，舞萦风。\n迟日象筵中。\n分行珠翠簇繁红。\n云髻袅珑璁。\n金炉暖。\n龙香远。\n共祝尧龄万万。\n曲终休解画罗衣。\n留伴彩云飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (472, '喜迁莺', '晏殊', '花不尽，柳无穷。\n应与我情同。\n觥船一棹百分空。\n何处不相逢。\n朱弦悄。\n知音少。\n天若有情应老。\n劝君看取利名场。\n今古梦茫茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (473, '喜迁莺', '晏殊', '烛飘花，香掩烬。\n中夜酒初醒。\n画楼残点两三声。\n窗外月胧明。\n晓帘垂，惊鹊去。\n好梦不知何处。\n南园春色已归来。\n庭树有寒梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (474, '喜迁莺', '晏殊', '曙河低，斜月淡。\n帘外早凉天。\n玉楼清唱倚朱弦。\n馀韵入疏烟。\n脸霞轻，眉翠重。\n欲舞钗钿摇动。\n人人如意祝炉香。\n为寿百千长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (475, '撼庭秋', '晏殊', '别来音信千里。\n怅此情难寄。\n碧纱秋月，梧桐夜雨，几回无寐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (476, '少年游', '晏殊', '重阳过後，西风渐紧，庭树叶纷纷。\n朱阑向晓，芙蓉妖艳，特地斗芳新。\n霜前月下，斜红淡蕊，明媚欲回春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (477, '少年游', '晏殊', '霜华满树，兰凋蕙惨，秋艳入芙蓉。\n胭脂嫩脸，金黄轻蕊，犹自怨西风。\n前欢往事，当歌对酒，无限到心中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (478, '少年游', '晏殊', '芙蓉花发去年枝。\n双燕欲归飞。\n兰堂风软，金炉香暖，新曲动帘帷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (479, '少年游', '晏殊', '谢家庭槛晓无尘。\n芳宴祝良辰。\n风流妙舞，樱桃清唱，依约驻行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (480, '酒泉子', '晏殊', '三月暖风，开却好花无限了，当年丛下落纷纷。\n最愁人。\n长安多少利名身。\n若有一杯香桂酒，莫辞花下醉芳茵。\n且留春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (481, '酒泉子', '晏殊', '春色初来，遍拆红芳千万树，流莺粉蝶斗翻飞。\n恋香枝。\n劝君莫惜缕金衣。\n把酒看花须强饮，明朝後日渐离披。\n惜芳时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (482, '木兰花・玉楼春', '晏殊', '东风昨夜回梁苑。\n日脚依稀添一线。\n旋开杨柳绿蛾眉，暗拆海棠红粉面。\n无情一去云中雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (483, '木兰花・玉楼春', '晏殊', '帘旌浪卷金泥凤。\n宿醉醒来长瞢。\n海棠开後晓寒轻，流絮飞时春睡重。\n美酒一杯谁与共。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (484, '木兰花・玉楼春', '晏殊', '燕鸿过後莺归去。\n细算浮生千万绪。\n长於春梦几多时，散似秋云无觅处。\n闻琴解佩神仙侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (485, '木兰花・玉楼春', '晏殊', '池塘水绿风微暖。\n记得玉真初见面。\n重头歌韵响铮琮，入破舞腰红乱旋。\n玉钩阑下香阶畔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (486, '木兰花・玉楼春', '晏殊', '玉楼朱阁横金锁。\n寒食清明春欲破。\n窗间斜月两眉愁，帘外落花双泪堕。\n朝云聚散真无那。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (487, '木兰花・玉楼春', '晏殊', '朱帘半下香销印。\n二月东风催柳信。\n琵琶旁畔且寻思，鹦鹉前头休借问。\n惊鸿去後生离恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (488, '木兰花・玉楼春', '晏殊', '杏梁归燕双回首。\n黄蜀葵花开应候。\n画堂元是降生辰，玉盏更斟长命酒。\n炉中百和添香兽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (489, '木兰花・玉楼春', '晏殊', '紫薇朱槿繁开後。\n枕簟微凉生玉漏。\n玳筵初启日穿帘，檀板欲开香满袖。\n红衫侍女频倾酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (490, '木兰花・玉楼春', '晏殊', '春葱指甲轻拢拈。\n五彩条垂双袖卷。\n雪香浓透紫檀槽，胡语急随红玉腕。\n当头一曲情无限。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (491, '木兰花・玉楼春', '晏殊', '红条约束琼肌稳。\n拍碎香檀催急衮。\n垅头呜咽水声繁，叶下间关莺语近。\n美人才子传芳信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (492, '迎春乐', '晏殊', '长安紫陌春归早。\n垂杨、染芳草。\n被啼莺语燕催清晓。\n正好梦、频惊觉。\n当此际、青楼临大道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (493, '诉衷情', '晏殊', '青梅煮酒斗时新。\n天气欲残春。\n东城南陌花下，逢著意中人。\n回绣袂，展香茵。\n叙情亲。\n此情拼作，千尺游丝，惹住朝云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (494, '诉衷情', '晏殊', '东风杨柳欲青青。\n烟淡雨初晴。\n恼他香阁浓睡，撩乱有啼莺。\n眉叶细，舞腰轻。\n宿妆成。\n一春芳意，三月和风，牵系人情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (495, '诉衷情', '晏殊', '芙蓉金菊斗馨香。\n天气欲重阳。\n远村秋色如画，红树间疏黄。\n流水淡，碧天长。\n路茫茫。\n凭高目断，鸿雁来时，无限思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (496, '诉衷情', '晏殊', '数枝金菊对芙蓉。\n摇落意重重。\n不知多少幽怨，和露泣西风。\n人散後，月明中。\n夜寒浓。\n谢娘愁卧，潘令闲眠，心事无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (497, '诉衷情', '晏殊', '露莲双脸远山眉。\n偏与淡妆宜。\n小庭帘幕春晚，闲共柳丝垂。\n人别後，月圆时。\n信迟迟。\n心心念念，说尽无凭，只是相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (498, '诉衷情', '晏殊', '秋风吹绽北池莲。\n曙云楼阁鲜。\n画堂今日嘉会，齐拜玉炉烟。\n斟美酒，祝芳筵。\n奉觥船。\n宜春耐夏，多福庄严，富贵长年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (499, '诉衷情', '晏殊', '世间荣贵月中人。\n嘉庆在今辰。\n兰堂帘幕高卷，清唱遏行云。\n持玉盏，敛红巾。\n祝千春。\n榴花寿酒，金鸭炉香，岁岁长新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (500, '诉衷情', '晏殊', '海棠珠缀一重重。\n清晓近帘栊。\n胭脂谁与匀淡，偏向脸边浓。\n看叶嫩，惜花红。\n意无穷。\n如花似叶，岁岁年年，共占春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (501, '胡捣练', '晏殊', '小桃花与早梅花，尽是芳妍品格。\n未上东风先拆。\n分付春消息。\n佳人钗上玉尊前，朵朵香堪惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (502, '人娇', '晏殊', '二月春风，正是杨花满路。\n那堪更、别离情绪。\n罗巾掩泪，任粉痕沾污。\n争奈向、千留万留不住。\n玉酒频倾，宿眉愁聚。\n空肠断、宝筝弦柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (503, '人娇', '晏殊', '玉树微凉，渐觉银河影转。\n林叶静、疏红欲遍。\n朱帘细雨，尚迟留归燕。\n嘉庆日、多少世人良愿。\n楚竹惊鸾，秦筝起雁。\n萦舞袖、急翻罗荐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (504, '人娇', '晏殊', '一叶秋高，向夕红兰露坠。\n风月好、乍凉天气。\n长生此日，见人中嘉瑞。\n斟寿酒、重唱妙声珠缀。\n凤莞移宫，钿衫回袂。\n帘影动、鹊炉香细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (505, '踏莎行', '晏殊', '细草愁烟，幽花怯露。\n凭阑总是销魂处。\n日高深院静无人，时时海燕双飞去。\n带缓罗衣，香残蕙炷。\n天长不禁迢迢路。\n垂杨只解惹春风，何曾系得行人住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (506, '踏莎行', '晏殊', '祖席离歌，长亭别宴。\n香尘已隔犹回面。\n居人匹马映林嘶，行人去棹依波转。\n画阁魂消，高楼目断。\n斜阳只送平波远。\n无穷无尽是离愁，天涯地角寻思遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (507, '踏莎行', '晏殊', '碧海无波，瑶台有路。\n思量便合双飞去。\n当时轻别意中人，山长水远知何处。\n绮席凝尘，香闺掩雾。\n红笺小字凭谁附。\n高楼目尽欲黄昏，梧桐叶上萧萧雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (508, '踏莎行', '晏殊', '绿树归莺，雕梁别燕。\n春光一去如流电。\n当歌对酒莫沈吟，人生有限情无限。\n弱袂萦春，修蛾写怨。\n秦筝宝柱频移雁。\n尊中绿醑意中人，花朝月夜长相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (509, '踏莎行', '晏殊', '小径红稀，芳郊绿遍。\n高台树色阴阴见。\n春风不解禁杨花，乱扑行人面。\n翠叶藏莺，朱帘隔燕。\n炉香静逐游丝转。\n一场愁梦酒醒时，斜阳却照深深院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (510, '渔家傲', '晏殊', '画鼓声中昏又晓。\n时光只解催人老。\n求得浅欢风日好。\n齐揭调。\n神仙一曲渔家傲。\n绿水悠悠天杳杳。\n浮生岂得长年少。\n莫惜醉来开口笑。\n须信道。\n人间万事何时了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (511, '渔家傲', '晏殊', '荷叶荷花相间斗。\n红娇绿嫩新妆就。\n昨日小池疏雨後。\n铺锦绣。\n行人过去频回首。\n倚遍朱阑凝望久。\n鸳鸯浴处波文皱。\n谁唤谢娘斟美酒。\n萦舞袖。\n当筵劝我千长寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (512, '渔家傲', '晏殊', '荷叶初开犹半卷。\n荷花欲拆犹微绽。\n此叶此花真可羡。\n秋水畔。\n青凉伞映红妆面。\n美酒一杯留客宴。\n拈花摘叶情无限。\n争奈世人多聚散。\n频祝愿。\n如花似叶长相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (513, '渔家傲', '晏殊', '杨柳风前香百步。\n盘心碎点真珠露。\n疑是水仙开洞府。\n妆景趣。\n红幢绿盖朝天路。\n小鸭飞来稠闹处。\n三三两两能言语。\n饮散短亭人欲去。\n留不住。\n黄昏更下萧萧雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (514, '渔家傲', '晏殊', '粉笔丹青描未得。\n金针彩线功难敌。\n谁傍暗香轻采摘。\n风淅淅。\n船头触散双。\n夜雨染成天水碧。\n朝阳借出胭脂色。\n欲落又开人共惜。\n秋气逼。\n盘中已见新莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (515, '渔家傲', '晏殊', '叶下眠未稳。\n风翻露香成阵。\n仙女出游知远近。\n羞借问。\n饶将绿扇遮红粉。\n一掬蕊黄沾雨润。\n天人乞与金英嫩。\n试折乱条醒酒困。\n应有恨。\n芳心拗尽丝无尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (516, '渔家傲', '晏殊', '罨画溪边停彩舫。\n仙娥绣被呈新样。\n飒飒风声来一饷。\n愁四望。\n残红片片随波浪。\n琼脸丽人青步障。\n风牵一袖低相向。\n应有锦鳞闲倚傍。\n秋水上。\n时时绿柄轻摇扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (517, '渔家傲', '晏殊', '宿蕊斗攒金粉闹。\n青房暗结蜂儿小。\n敛面似啼开似笑。\n天与貌。\n人间不是铅华少。\n叶软香清无限好。\n风头日脚乾催老。\n待得玉京仙子到。\n凭向道。\n红颜只合长年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (518, '渔家傲', '晏殊', '脸傅朝霞衣剪翠。\n重重占断秋江水。\n一曲采莲风细细。\n人未醉。\n鸳鸯不合惊飞起。\n欲摘嫩条嫌绿刺。\n闲敲画扇偷金蕊。\n半夜月明珠露坠。\n多少意。\n红腮点点相思泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (519, '渔家傲', '晏殊', '越女采莲江北岸。\n轻桡短棹随风便。\n人貌与花相斗艳。\n流水慢。\n时时照影看妆面。\n莲叶层层张绿伞。\n莲房个个垂金盏。\n一把藕丝牵不断。\n红日晚。\n回头欲去心撩乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (520, '渔家傲', '晏殊', '粉面啼红腰束素。\n当年拾翠曾相遇。\n密意深情谁与诉。\n空怨慕。\n西池夜夜风兼露。\n池上夕阳笼碧树。\n池中短棹惊微雨。\n水泛落英何处去。\n人不语。\n东流到了无停住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (521, '渔家傲', '晏殊', '幽鹭慢来窥品格。\n双鱼岂解传消息。\n绿柄嫩香频采摘。\n心似织。\n条条不断谁牵役。\n粉泪暗和清露滴。\n罗衣染尽秋江色。\n对面不言情脉脉。\n烟水隔。\n无人说似长相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (522, '渔家傲', '晏殊', '楚国细腰元自瘦。\n文君腻脸谁描就。\n日夜声声催箭漏。\n昏复昼。\n红颜岂得长如旧。\n醉折嫩房和蕊嗅。\n天丝不断清香透。\n却傍小阑凝坐久。\n风满袖。\n西池月上人归後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (523, '渔家傲', '晏殊', '嫩绿堪裁红欲绽。\n蜻蜓点水鱼游畔。\n一霎雨声香四散。\n风乱。\n高低掩映千千万。\n总是凋零终有恨。\n能无眼下生留恋。\n何似折来妆粉面。\n勤看玩。\n胜如落尽秋江岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (524, '雨中花・夜行船', '晏殊', '剪翠妆红欲就。\n折得清香满袖。\n一对鸳鸯眠未足，叶下长相守。\n莫傍细条寻嫩藕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (525, '瑞鹧鸪', '晏殊', '越娥红泪泣朝云。\n越梅从此学妖。\n腊月初头、庾岭繁开後，特染妍华赠世人。\n前溪昨夜深深雪，朱颜不掩天真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (526, '瑞鹧鸪', '晏殊', '江南残腊欲归时。\n有梅红亚雪中枝。\n一夜前村、间破瑶英拆，端的千花冷未知。\n丹青改样匀朱粉，雕梁欲画犹疑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (527, '望仙门', '晏殊', '紫薇枝上露华浓。\n起秋风。\n管弦声细出帘栊。\n象筵中。\n仙酒斟云液，仙歌转绕梁虹。\n此时佳会庆相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (528, '望仙门', '晏殊', '玉壶清漏起微凉。\n好秋光。\n金杯重叠满琼浆。\n会仙乡。\n新曲调丝管，新声更霓裳。\n博山炉暖泛浓香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (529, '望仙门', '晏殊', '玉池波浪碧如鳞。\n露莲新。\n清歌一曲翠眉。\n舞华茵。\n满酌兰英酒，须知献寿千春。\n太平无事荷君恩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (530, '长生乐', '晏殊', '玉露金风月正圆。\n台榭早凉天。\n画堂嘉会，组绣列芳筵。\n洞府星辰龟鹤，来添福寿。\n欢声喜色，同入金炉泛浓烟。\n清歌妙舞，急管繁弦。\n榴花满酌觥船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (531, '长生乐', '晏殊', '阆苑神仙平地见。\n碧海架蓬瀛。\n洞门相向，倚金铺微明。\n处处天花撩乱，飘散歌声。\n装真筵寿，赐与流霞满瑶觥。\n红鸾翠节，紫凤银笙。\n玉女双来近彩云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (532, '蝶恋花', '晏殊', '一霎秋风惊画扇。\n艳粉娇红，尚拆荷花面。\n草际露垂虫响遍。\n珠帘不下留归燕。\n扫掠亭台开小院。\n四坐清欢，莫放金杯浅。\n龟鹤命长松寿远。\n阳春一曲情千万。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (533, '蝶恋花', '晏殊', '紫菊初生朱槿坠。\n月好风清，渐有中秋意。\n更漏乍长天似水。\n银屏展尽遥山翠。\n绣幕卷波香引穗。\n急管繁弦，共庆人间瑞。\n满酌玉杯萦舞袂。\n南春祝寿千千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (534, '蝶恋花', '晏殊', '帘幕风轻双语燕。\n午醉醒来，柳絮飞撩乱。\n心事一春犹未见。\n馀花落尽青苔院。\n百尺朱楼闲倚遍。\n薄雨浓云，抵死遮人面。\n消息未知归早晚。\n斜阳只送平波远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (535, '蝶恋花', '晏殊', '玉碗冰寒消暑气。\n碧簟纱厨，向午朦胧睡。\n莺舌惺松如会意。\n无端画扇惊飞起。\n雨後初凉生水际。\n人面荷花，的的遥相似。\n眼看红芳犹抱蕊。\n丛中已结新莲子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (536, '蝶恋花', '晏殊', '梨叶疏红蝉韵歇。\n银汉风高，玉管声凄切。\n枕簟乍凉铜漏咽。\n谁教社燕轻离别。\n草际蛩吟珠露结。\n宿酒醒来，不记归时节。\n多少衷肠犹未说。\n朱帘一夜朦胧月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (537, '蝶恋花', '晏殊', '南雁依稀回侧阵。\n雪霁墙阴，偏觉兰芽嫩。\n中夜梦馀消酒困。\n炉香卷穗灯生晕。\n急景流年都一瞬。\n往事前欢，未免萦方寸。\n腊後花期知渐近。\n寒梅已作东风信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (538, '拂霓裳', '晏殊', '庆生辰。\n庆生辰是百千春。\n开雅宴，画堂高会有诸亲。\n钿函封大国，玉色受丝纶。\n感皇恩。\n望九重、天上拜尧云。\n今朝祝寿，祝寿数，比松椿。\n斟美酒，至心如对月中人。\n一声檀板动，一炷蕙香焚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (539, '拂霓裳', '晏殊', '喜秋成。\n见千门万户乐升平。\n金风细，玉池波浪文生。\n宿露沾罗幕，微凉入画屏。\n张绮宴，傍熏炉蕙炷、和新声。\n神仙雅会，会此日，象蓬瀛。\n管弦清，旋翻红袖学飞琼。\n光阴无暂住，欢醉有闲情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (540, '拂霓裳', '晏殊', '乐秋天。\n晚荷花缀露珠圆。\n风日好，数行新雁贴寒烟。\n银簧调脆管，琼柱拨清弦。\n捧觥船。\n一声声、齐唱太平年。\n人生百岁，离别易，会逢难。\n无事日，剩呼宾友启芳筵。\n星霜催绿鬓，风露损朱颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (541, '菩萨蛮', '晏殊', '芳莲九蕊开新艳。\n轻红淡白匀双脸。\n一朵近华堂。\n学人宫样妆。\n看时斟美酒。\n共祝千年寿。\n销得曲中夸。\n世间无此花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (542, '菩萨蛮', '晏殊', '秋花最是黄葵好。\n天然嫩态迎秋早。\n染得道家衣。\n淡妆梳洗时。\n晓来清露滴。\n一一金杯侧。\n插向绿云鬓。\n便随王母仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (543, '菩萨蛮', '晏殊', '人人尽道黄葵淡。\n侬家解说黄葵艳。\n可喜万般宜。\n不劳朱粉施。\n摘承金盏酒。\n劝我千长寿。\n擎作女真冠。\n试伊娇面看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (544, '菩萨蛮', '晏殊', '高梧叶下秋光晚。\n珍丛化出黄金盏。\n还似去年时。\n傍阑三两枝。\n人情须耐久。\n花面长依旧。\n莫学蜜蜂儿。\n等闲悠扬飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (545, '秋蕊香', '晏殊', '梅蕊雪残香瘦。\n罗幕轻寒微透。\n多情只是春杨柳。\n占断可怜时候。\n萧娘劝我杯中酒。\n翻红袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (546, '秋蕊香', '晏殊', '向晓雪花呈瑞。\n飞遍玉城瑶砌。\n何人剪碎天边桂。\n散作瑶田琼蕊。\n萧娘敛尽双蛾翠。\n回香袂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (547, '相思儿令', '晏殊', '昨日探春消息，湖上绿波平。\n无奈绕堤芳草，还向旧痕生。\n有酒且醉瑶觥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (548, '相思儿令', '晏殊', '春色渐芳菲也，迟日满烟波。\n正好艳阳时节，争奈落花何。\n醉来拟恣狂歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (549, '滴滴金', '晏殊', '梅花漏泄春消息。\n柳丝长，草芽碧。\n不觉星霜鬓边白。\n念时光堪惜。\n兰堂把酒留嘉客。\n对离筵，驻行色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (550, '山亭柳', '晏殊', '家住西秦。\n赌博艺随身。\n花柳上、斗尖新。\n偶学念奴声调，有时高遏行云。\n蜀锦缠头无数，不负辛勤。\n数年来往咸京道，残杯冷炙谩消魂。\n衷肠事、托何人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (551, '睿恩新', '晏殊', '芙蓉一朵霜秋色。\n迎晓露、依依先拆。\n似佳人、独立倾城，傍朱槛、暗传消息。\n静对西风脉脉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (552, '睿恩新', '晏殊', '红丝一曲傍阶砌。\n珠露下、独呈纤丽。\n剪鲛绡、碎作香英，分彩线、簇成娇蕊。\n向晚群花欲悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (553, '玉堂春', '晏殊', '帝城春暖。\n御柳暗遮空苑。\n海燕双双，拂扬帘栊。\n女伴相携、共绕林间路，折得樱桃插髻红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (554, '玉堂春', '晏殊', '後园春早。\n残雪尚烟草。\n数树寒梅，欲绽香英。\n小妹无端、折尽钗头朵，满把金尊细细倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (555, '玉堂春', '晏殊', '斗城池馆。\n二月风和烟暖。\n绣户珠帘，日影初长。\n玉辔金鞍、缭绕沙堤路，几处行人映绿杨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (556, '临江仙', '晏殊', '资善堂中三十载，旧人多是凋零。\n与君相见最伤情。\n一尊如旧，聊且话平生。\n此别要知须强饮，雪残风细长亭。\n待君归觐九重城。\n帝宸思旧，朝夕奉皇明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (557, '燕归梁', '晏殊', '双燕归飞绕画堂。\n似留恋虹梁。\n清风明月好时光。\n更何况、绮筵张。\n云衫侍女，频倾寿酒，加意动笙簧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (558, '燕归梁', '晏殊', '金鸭香炉起瑞烟。\n呈妙舞开筵。\n阳春一曲动朱弦。\n斟美酒、泛觥船。\n中秋五日，风清露爽，犹是早凉天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (559, '望汉月・忆汉月', '晏殊', '千缕万条堪结。\n占断好风良月。\n谢娘春晚先多愁，更撩乱、絮飞如雪。\n短亭相送处，长忆得、醉中攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (560, '连理枝', '晏殊', '玉字秋风至。\n帘幕生凉气。\n朱槿犹开，红莲尚拆，芙蓉含蕊。\n送旧巢归燕拂高檐，见梧桐叶坠。\n嘉宴凌晨启。\n金鸭飘香细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (561, '连理枝', '晏殊', '绿树莺声老。\n金井生秋早。\n不寒不暖，裁衣按曲，天时正好。\n况兰堂逢著寿筵开，见炉香缥缈。\n组绣呈纤巧。\n歌舞夸妍妙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (562, '破阵子', '晏殊', '燕子来时新社，梨花落後清明。\n池上碧苔三四点，叶底黄鹂一两声。\n日长飞絮轻。\n巧笑东邻女伴，采桑径里逢迎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (563, '玉楼春', '晏殊', '绿杨芳草长亭路。\n年少抛人容易去。\n楼头残梦五更钟，花底离情三月雨。\n无情不似多情苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (564, '失调名', '晏殊', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (565, '临江仙', '滕宗谅', '湖水连天天连水，秋来分外澄清。\n君山自是小蓬瀛。\n气蒸云梦泽，波撼岳阳城。\n帝子有灵能鼓瑟，凄然依旧伤情。\n微闻兰芝动芳馨。\n曲终人不见，江上数峰青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (566, '满江红', '张', '无利无名，无荣无辱，无烦无恼。\n夜灯前、独歌独酌，独吟独笑。\n况值群山初雪满，又兼明月交光好。\n便假饶百岁拟如何，从他老。\n知富贵，谁能保。\n知功业，何时了。\n算箪瓢金玉，所争多少。\n一瞬光阴何足道，但思行乐常不早。\n待春来携酒东风，眠芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (567, '离亭燕・离亭宴', '张', '一带江山如画。\n风物向秋潇洒。\n水浸碧天何处断，翠色冷光相射。\n蓼岸荻花中，隐映竹篱茅舍。\n天际客帆高挂。\n门外酒旗低迓。\n多少六朝兴废事，尽入渔樵闲话。\n怅望倚危栏，红日无言西下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (568, '诉衷情', '王益', '烧残绛蜡泪成痕。\n街鼓报黄昏。\n碧云又阻来信，廊上月侵门。\n愁永夜，拂香。\n待谁温。\n梦兰憔悴，掷果凄凉，两处销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (569, '鹊桥仙', '石延年', '一分素景，千家新月，凉露楼台遍洗。\n宝奁深夜结蛛丝，五孔、金针不寐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (570, '燕归梁', '石延年', '芳草年年惹恨幽。\n想前事悠悠。\n伤春伤别几时休。\n算从古、为风流。\n春山总把，深匀翠黛，千叠在眉头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (571, '迷仙引', '关咏', '春阴霁。\n岸柳参差，袅袅金丝细。\n画阁昼眠莺唤起。\n烟光媚。\n燕燕双高，引愁人如醉。\n慵缓步，眉敛金铺倚。\n嘉景易失，懊恼韶光改。\n花空委。\n忍厌厌地。\n施朱粉，临鸾鉴，腻香销减摧桃李。\n独自个凝睇。\n暮云暗、遥山翠。\n天色无情，四远低垂淡如水。\n离恨托、征鸿寄。\n旋娇波、暗落相思泪。\n妆如洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (572, '水调歌头', '刘潜', '六郡酒泉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (573, '六州歌头', '刘潜', '秦亡草昧，刘项起吞并。\n驱龙虎。\n鞭寰宇。\n斩长鲸。\n扫枪。\n血染彭门战。\n视馀耳，皆鹰犬。\n平祸乱。\n归炎汉。\n势奔倾。\n兵散月明。\n风急旌旗乱，刁斗三更。\n命虞姬相对，泣听楚歌声。\n玉帐魂惊。\n泪盈盈。\n恨花无主。\n凝愁绪。\n挥雪刃，掩泉扃。\n时不利。\n骓不逝。\n困阴陵。\n叱追兵。\n喑呜摧天地，望归路，忍偷生。\n功盖世。\n成闲纪。\n建遗灵。\n江静水寒烟冷，波纹细、古木凋零。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (574, '水调歌头', '刘潜', '落日塞垣路，风劲戛貂裘。\n翩翩数骑闲猎，深入黑山头。\n极目平沙千里，惟见雕弓白羽，铁面骇骅骝。\n隐隐望青冢，特地起闲愁。\n汉天子，方鼎盛，四百州。\n玉颜皓齿，深锁三十六宫秋。\n堂有经纶贤相，边有纵横谋将，不作翠蛾羞。\n戎虏和乐也，圣主永无忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (575, '蝶恋花', '李冠', '遥夜亭皋闲信步。\n才过清明，渐觉伤春暮。\n数点雨声风约住。\n朦胧淡月云来去。\n桃杏依稀香暗渡。\n谁在秋千，笑里轻轻语。\n一寸相思千万绪。\n人间没个安排处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (576, '六州歌头', '李冠', '凄凉绣岭，宫殿倚山阿。\n明皇帝。\n曾游地。\n锁烟萝。\n郁嵯峨。\n忆惜真妃子。\n艳倾国，方姝丽。\n朝复暮。\n嫔嫱妒。\n宠偏颇。\n三尺玉泉新浴，莲羞吐、红浸秋波。\n听花奴，敲羯鼓，酣奏鸣鼍。\n体不胜罗。\n舞婆娑。\n正霓裳曳。\n惊烽燧。\n千万骑。\n拥雕戈。\n情宛转。\n魂空乱。\n蹙双蛾。\n奈兵何。\n痛惜三春暮，委妖丽，马嵬坡。\n平寇乱。\n回宸辇。\n忍重过。\n香瘗紫囊犹有，鸿都客、钿合应讹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (577, '六州歌头', '李冠', '秦亡草昧，刘项起吞并。\n鞭寰宇。\n驱龙虎。\n扫枪。\n斩长鲸。\n雪染中原战。\n视馀耳，皆鹰犬。\n平祸乱。\n归炎汉。\n势奔倾。\n兵散月明。\n风急旌旗乱，刁斗三更。\n共虞姬相对，泣听楚歌声。\n玉帐魂惊。\n泪盈盈。\n念花无主。\n凝愁苦。\n挥雪刃，掩泉扃。\n时不利。\n骓不逝。\n困阴陵。\n叱追兵。\n呜喑摧天地，望归路，忍偷生。\n功盖世，何处见遗灵。\n江静水寒烟冷，波纹钿、古木凋零。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (578, '蝶恋花', '李冠', '贴鬓香云双绾绿。\n柳弱花娇，一点春心足。\n不肯玉箫闲度曲。\n恼人特把青蛾蹙。\n静夜溪桥霜薄屋。\n独影行歌，惊起双鸾宿。\n愁破酒阑闺梦熟。\n月斜窗外风敲竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (579, '千秋万岁・千秋岁引', '李冠', '杏花好、子细君须辨。\n比早梅深、夭桃浅。\n把鲛绡、淡拂鲜红面。\n蜡融紫萼重重现。\n烟外悄，风中笑，香满院。\n欲绽全开俱可羡。\n粹美妖娆无处选。\n除卿卿似寻常见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (580, '菩萨蛮', '谢绛', '娟娟侵鬓妆痕浅。\n双眸相媚弯如翦。\n一瞬百般宜。\n无论笑与啼。\n酒阑思翠被。\n特故瞢腾地。\n生怕促归轮。\n微波先注人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (581, '夜行船', '谢绛', '昨夜佳期初共。\n鬓云低、翠翘金凤。\n尊前和笑不成歌，意偷转、眼波微送。\n草草不容成楚梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (582, '诉衷情', '谢绛', '银缸夜永影长孤。\n香草续残炉。\n倚屏脉脉无语，粉泪不成珠。\n双粲枕，百娇壶。\n忆当初。\n君恩莫似，秋叶无情，欲向人疏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (583, '失调名', '宋祁', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (584, '浪淘沙近・浪淘沙', '宋祁', '少年不管。\n流光如箭。\n因循不觉韶光换。\n至如今，始惜月满、花满、酒满。\n扁舟欲解垂杨岸。\n尚同欢宴。\n日斜歌阕将分散。\n倚兰桡，望水远、天远、人远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (585, '蝶恋花', '宋祁', '雨过蒲萄新涨绿。\n苍玉盘倾，堕碎珠千斛。\n姬监拥前红簇簇。\n温泉初试真妃浴。\n驿使南来丹荔熟。\n故翦轻绡，一色颁时服。\n娇汗易凝醉玉。\n青凉不用香绵扑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (586, '玉楼春', '宋祁', '东城渐觉风光好。\n皱波纹迎客棹。\n绿杨烟外晓寒轻，红杏枝头春意闹。\n浮生长恨欢娱少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (587, '蝶恋花', '宋祁', '绣幕茫茫罗帐卷。\n春睡腾腾，困入娇波慢。\n隐隐枕痕留玉脸。\n腻云斜溜钗头燕。\n远梦无端欢又散。\n泪落胭脂，界破蜂黄浅。\n整了翠鬟匀了面。\n芳心一寸情何限。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (588, '鹧鸪天', '宋祁', '画毂雕鞍狭路逢。\n一声肠断绣帘中。\n身无彩凤双飞翼，心有灵犀一点通。\n金作屋，玉为笼。\n车如流水马游龙。\n刘郎已恨蓬山远，更隔蓬山几万重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (589, '好事近', '宋祁', '睡起玉屏风，吹去乱红犹落。\n天气骤生轻暖，衬沈香帷箔。\n珠帘约住海棠风，愁拖两眉角。\n昨夜一庭明月，冷秋千红索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (590, '木兰花令', '贾昌朝', '都城水绿嬉游处。\n仙棹往来人笑语。\n红随远浪泛桃花，雪散平堤飞柳絮。\n东君欲共春归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (591, '水调歌头', '尹洙', '万倾太湖上，朝暮浸寒光。\n吴王去後，台榭千古锁悲凉。\n谁信蓬山仙子，天与经纶才器，等闲厌名缰。\n敛翼下霄汉，雅意在沧浪。\n晚秋里，烟寂静，雨微凉。\n危亭好景，佳树修竹绕回塘。\n不用移舟酌酒，自有青山渌水，掩映似潇湘。\n莫问平生意，别有好思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (592, '苏幕遮', '梅尧臣', '露堤平，烟墅杳。\n乱碧萋萋，雨後江天晓。\n独有庾郎年最少。\n地春袍，嫩色宜相照。\n接长亭，迷远道。\n堪怨王孙，不记归期早。\n落尽梨花春又了。\n满地残阳，翠色和烟老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (593, '玉楼春', '梅尧臣', '天然不比花含粉。\n约月眉黄春色嫩。\n小桥低映欲迷人，闲倚东风无奈困。\n烟姿最与章台近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (594, '江南好・忆江南', '叶清臣', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (595, '贺圣朝', '叶清臣', '满斟绿醑留君住。\n莫匆匆归去。\n三分春色二分愁，更一分风雨。\n花开花谢、都来几许。\n且高歌休诉。\n不知来岁牡丹时，再相逢何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (596, '折红梅', '吴感', '喜冰澌初泮，微和渐入、东郊时节。\n春消息，夜来顿觉，红梅数枝争发。\n玉溪仙馆，不是个、寻常标格。\n化工别与、一种风情，似匀点胭脂，染成香雪。\n重吟细阅。\n比繁杏夭桃，品格真别。\n只愁共、彩云易散，冷落谢池风月。\n凭谁向说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (597, '映山红', '文彦博', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (598, '西湖念语', '欧阳修', '昔者王子猷之爱竹，造门不问于主人，陶渊明之卧舆，遇酒便留于道士。\n况西湖之胜概，擅东颍之佳名。\n虽美景良辰，固多于高会。\n而清风明月，幸属于闲人。\n并游或结于良朋，乘兴有时而独往。\n鸣蛙暂听，安问属官而属私。\n曲水临流，自可一觞而一咏。\n至欢然而会意，亦傍若于无人。\n乃知偶来常胜於特来，前言可信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (599, '采桑子', '欧阳修', '轻舟短棹西湖好，绿水逶迤。\n芳草长堤。\n隐隐笙歌处处随。\n无风水面琉璃滑，不觉船移。\n微动涟漪。\n惊起沙禽掠岸飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (600, '采桑子', '欧阳修', '春深雨过西湖好，百卉争妍。\n蝶乱蜂喧。\n晴日催花暖欲然。\n兰桡画舸悠悠去，疑是神仙。\n返照波间。\n水阔风高扬管弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (601, '采桑子', '欧阳修', '画船载酒西湖好，急管繁弦。\n玉盏催传。\n稳泛平波任醉眠。\n行云却在行舟下，空水澄鲜。\n俯仰留连。\n疑是湖中别有天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (602, '采桑子', '欧阳修', '群芳过後西湖好，狼籍残红。\n飞絮。\n垂柳阑干尽日风。\n笙歌散尽游人去，始觉春空。\n垂下帘栊。\n双燕归来细雨中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (603, '采桑子', '欧阳修', '何人解赏西湖好，佳景无时。\n飞盖相追。\n贪向花间醉玉卮。\n谁知闲凭阑干处，芳草斜晖。\n水远烟微。\n一点沧洲白鹭飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (604, '采桑子', '欧阳修', '清明上巳西湖好，满目繁华。\n争道谁家。\n绿柳朱轮走钿车。\n游人日暮相将去，醒醉喧哗。\n路转堤斜。\n直到城头总是花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (605, '采桑子', '欧阳修', '荷花开後西湖好，载酒来时。\n不用旌旗。\n前後红幢绿盖随。\n画船撑入花深处，香泛金卮。\n烟雨微微。\n一片笙歌醉里归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (606, '采桑子', '欧阳修', '天容水色西湖好，云物俱鲜。\n鸥鹭闲眠。\n应惯寻常听管弦。\n风清月白偏宜夜，一片琼田。\n谁羡骖鸾。\n人在舟中便是仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (607, '采桑子', '欧阳修', '残霞夕照西湖好，花坞苹汀。\n十顷波平。\n野岸无人舟自横。\n西南月上浮云散，轩槛凉生。\n莲芰香清。\n水面风来酒面醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (608, '采桑子', '欧阳修', '平生为爱西湖好，来拥朱轮。\n富贵浮云。\n俯仰流年二十春。\n归来恰似辽东鹤，城郭人民。\n触目皆新。\n谁识当年旧主人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (609, '采桑子', '欧阳修', '画楼钟动君休唱，往事无踪。\n聚散匆匆。\n今日欢娱几客同。\n去年绿鬓今年白，不觉衰容。\n明月清风。\n把酒何人忆谢公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (610, '采桑子', '欧阳修', '十年一别流光速，白首相逢。\n莫话衰翁。\n但斗尊前语笑同。\n劝君满酌君须醉，尽日从容。\n画牵风。\n即去朝天沃舜聪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (611, '采桑子', '欧阳修', '十年前是尊前客，月白风清。\n忧患凋零。\n老去光阴速可惊。\n鬓华虽改心无改，试把金觥。\n旧曲重听。\n犹是当年醉里声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (612, '朝中措', '欧阳修', '平山阑槛倚晴空。\n山色有无中。\n手种堂前垂柳，别来几度春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (613, '长相思', '欧阳修', '苹满溪。\n柳绕堤。\n相送行人溪水西。\n回时陇月低。\n烟霏霏。\n风凄凄。\n重倚朱门听马嘶。\n寒鸥相对飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (614, '长相思', '欧阳修', '花似伊。\n柳似伊。\n花柳青春人别离。\n低头双泪垂。\n长江东。\n长江西。\n两岸鸳鸯两处飞。\n相逢知几时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (615, '长相思', '欧阳修', '深花枝。\n浅花枝。\n深浅花枝相并时。\n花枝难似伊。\n玉如肌。\n柳如眉。\n爱著鹅黄金缕衣。\n啼妆更为谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (616, '诉衷情', '欧阳修', '清晨帘幕卷轻霜。\n呵手试梅妆。\n都缘自有离恨，故画作远山长。\n思往事，惜流芳。\n易成伤。\n拟歌先敛，欲笑还颦，最断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (617, '踏莎行', '欧阳修', '候馆梅残，溪桥柳细。\n草熏风暖摇征辔。\n离愁渐远渐无穷，迢迢不断如春水。\n寸寸柔肠，盈盈粉泪。\n楼高莫近危阑倚。\n平芜尽处是春山，行人更在春山外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (618, '踏莎行', '欧阳修', '雨霁风光，春分天气。\n千花百卉争明媚。\n画梁新燕一双双，玉笼鹦鹉愁孤睡。\n薜荔依墙，莓苔满地。\n青楼几处歌声丽。\n蓦然旧事心上来，无言敛皱眉山翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (619, '望江南・忆江南', '欧阳修', '江南蝶，斜日一双双。\n身似何郎全傅粉，心如韩寿爱偷香。\n天赋与轻狂。\n微雨後，薄翅腻烟光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (620, '减字木兰花', '欧阳修', '留春不住。\n燕老莺慵无觅处。\n说似残春。\n一老应无却少人。\n风和月好。\n办得黄金须买笑。\n爱惜芳时。\n莫待无花空折枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (621, '减字木兰花', '欧阳修', '伤怀离抱。\n天若有情天亦老。\n此意如何。\n细似轻丝渺似波。\n扁舟岸侧。\n枫叶荻花秋索索。\n细想前欢。\n须著人间比梦间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (622, '减字木兰花', '欧阳修', '楼台向晓。\n淡月低云天气好。\n翠幕风微。\n宛转梁州入破时。\n香生舞袂。\n楚女腰肢天与细。\n汗粉重匀。\n酒後轻寒不著人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (623, '减字木兰花', '欧阳修', '画堂雅宴。\n一抹朱弦初入遍。\n慢拈轻笼。\n玉指纤纤嫩剥葱。\n拨头利。\n怨月愁花无限意。\n红粉轻盈。\n倚暖香檀曲未成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (624, '减字木兰花', '欧阳修', '歌檀敛袂。\n缭绕雕梁尘暗起。\n柔润清圆。\n百明珠一线穿。\n樱唇玉齿。\n天上仙音心下事。\n留往行云。\n满坐迷魂酒半醺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (625, '生查子', '欧阳修', '去年元夜时，花市灯如昼。\n月到柳梢头，人约黄昏後。\n今年元夜时，月与灯依旧。\n不见去年人，泪满春衫袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (626, '生查子', '欧阳修', '含羞整翠鬟，得意频相顾。\n雁柱十三弦，一一春莺语。\n娇云容易飞，梦断知何处。\n深院锁黄昏，阵阵芭蕉雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (627, '清商怨', '欧阳修', '关河愁思望处满。\n渐素秋向晚。\n雁过南云，行人回泪眼。\n双鸾衾悔展。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (628, '阮郎归', '欧阳修', '刘郎何日是来时。\n无心云胜伊。\n行云犹解傍山飞。\n郎行去不归。\n强匀画，又芳菲。\n春深轻薄衣。\n桃花无语伴相思。\n阴阴月上时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (629, '阮郎归', '欧阳修', '落花浮水树临池。\n年前心眼期。\n见来无事去还思。\n而今花又飞。\n浅螺黛，淡燕脂。\n闲妆取次宜。\n隔帘风雨闭门时。\n此情风月知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (630, '蝶恋花', '欧阳修', '帘幕东风寒料峭。\n雪里香梅，先报春来早。\n红蜡枝头双燕小。\n金刀剪彩呈纤巧。\n旋暖金炉薰蕙藻。\n酒入横波，困不禁烦恼。\n绣被五更春睡好。\n罗帏不觉纱窗晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (631, '蝶恋花', '欧阳修', '南雁依稀回侧阵。\n雪霁墙阴，遍觉兰芽嫩。\n中夜梦馀消酒困。\n炉香卷穗灯生晕。\n急景流年都一瞬。\n往事前欢，未免萦芳寸。\n腊後花期知渐近。\n东风已作寒梅信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (632, '蝶恋花', '欧阳修', '腊雪初销梅蕊绽。\n梅雪相和，喜鹊穿花转。\n睡起夕阳迷醉眼。\n新愁长向东风乱。\n瘦觉玉肌罗带缓。\n红杏梢头，二月春犹浅。\n望极不来芳信断。\n音书纵有争如见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (633, '蝶恋花', '欧阳修', '海燕双来归画栋。\n帘影无风，花影频移动。\n半醉腾腾春睡重。\n绿鬟堆枕香云拥。\n翠被双盘金缕凤。\n忆得前春，有个人人共。\n花里黄莺时一弄。\n日斜惊起相思梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (634, '蝶恋花', '欧阳修', '面旋落花风荡漾。\n柳重烟深，雪絮飞来往。\n雨後轻寒犹未放。\n春愁酒病成惆怅。\n枕畔屏山围碧浪。\n翠被华灯，夜夜空相向。\n寂寞起来褰绣幌。\n月明正在梨花上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (635, '蝶恋花', '欧阳修', '帘幕风轻双语燕。\n午後醒来，柳絮飞撩乱。\n心事一春犹未见。\n红英落尽青苔院。\n百尺朱楼闲倚遍。\n薄雨浓云，抵死遮人面。\n羌管不须吹别怨。\n无肠更为新声断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (636, '蝶恋花', '欧阳修', '永日环堤乘彩舫。\n烟草萧疏，恰似晴江上。\n水浸碧天风皱浪。\n菱花荇蔓随双桨。\n红粉佳人翻丽唱。\n惊起鸳鸯，两两飞相向。\n且把金尊倾美酿。\n休思往事成惆怅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (637, '蝶恋花', '欧阳修', '越女采莲秋水畔。\n窄袖轻罗，暗露双金钏。\n照影摘花花似面。\n芳心只共丝争乱。\n滩头风浪晚。\n雾重烟轻，不见来时伴。\n隐隐歌声归棹远。\n离愁引著江南岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (638, '蝶恋花', '欧阳修', '水浸秋天风皱浪。\n缥缈仙舟，只似秋天上。\n和露采莲愁一饷。\n看花却是啼妆样。\n折得莲茎丝未放。\n莲断丝牵，特地成惆怅。\n归棹莫随花荡漾。\n江头有个人相望。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (639, '蝶恋花', '欧阳修', '梨叶初红婵韵歇。\n银汉风高，玉管声凄切。\n枕簟乍凉铜漏彻。\n谁教社燕轻离别。\n草际虫吟秋露结。\n宿酒醒来，不记归时节。\n多少衷肠犹未说。\n珠帘夜夜朦胧月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (640, '蝶恋花', '欧阳修', '独倚危楼风细细。\n望极离愁，黯黯生天际。\n草色山光残照里。\n无人会得凭阑意。\n也拟疏狂图一醉。\n对酒当歌，强饮还无味。\n衣带渐宽都不悔。\n况伊销得人憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (641, '蝶恋花', '欧阳修', '帘下清歌帘外宴。\n虽爱新声，不见如花面。\n牙板数敲珠一串。\n梁尘暗落琉璃盏。\n桐树花深孤凤怨。\n渐遏遥天，不放行云散。\n坐上少年听未惯。\n玉山将倒肠先断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (642, '蝶恋花', '欧阳修', '翠苑红芳晴满目。\n绮席流莺，上下长相逐。\n紫陌闲随金轹辘。\n马蹄踏遍春郊绿。\n一觉年华春梦促。\n往事悠悠，百种寻思足。\n烟雨满楼山断续。\n人闲倚遍阑干曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (643, '蝶恋花', '欧阳修', '小院深深门掩亚。\n寂寞珠帘，画阁重重下。\n欲近禁烟微雨罢。\n绿杨深处秋千挂。\n傅粉狂游犹未舍。\n不念芳时，眉黛无人画。\n薄幸未归春去也。\n杏花零落香红谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (644, '蝶恋花', '欧阳修', '欲过清明烟雨细。\n小槛临窗，点点残花坠。\n梁燕语多惊晓睡。\n银屏一半堆香被。\n新岁风光如旧岁。\n所恨征轮，渐渐程迢递。\n纵有远情难写寄。\n何妨解有相思泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (645, '蝶恋花', '欧阳修', '画阁归来春又晚。\n燕子双飞，柳软桃花浅。\n细雨满天风满院。\n愁眉敛尽无人见。\n独倚阑干心绪乱。\n芳草芊绵，尚忆江南岸。\n风月无情人暗换。\n旧游如梦空肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (646, '蝶恋花', '欧阳修', '尝爱西湖春色早。\n腊雪方销，已见桃开小。\n顷刻光阴都过了。\n如今绿暗红英少。\n且趁馀花谋一笑。\n况有笙歌，艳态相萦绕。\n老去风情应不到。\n凭君剩把芳尊倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (647, '渔家傲', '欧阳修', '一派潺流碧涨。\n新亭四面山相向。\n翠竹岭头明月上。\n迷俯仰。\n月轮正在泉中漾。\n更待高秋天气爽。\n菊花香里开新酿。\n酒美宾嘉真胜赏。\n红粉唱。\n山深分外歌声响。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (648, '渔家傲', '欧阳修', '十月小春梅蕊绽。\n红炉画阁新妆遍。\n锦帐美人贪睡暖。\n羞起晚。\n玉壶一夜冰澌满。\n楼上四垂帘不卷。\n天寒山色偏宜远。\n风急雁行吹字断。\n红日短。\n江天雪意云撩乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (649, '渔家傲', '欧阳修', '四纪才名天下重。\n三朝构厦为梁栋。\n定册功成身退勇。\n辞荣宠。\n归来白首笙歌拥。\n顾我薄才无可用。\n君恩近许归田垅。\n今日一觞难得共。\n聊对捧。\n官奴为我高歌送。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (650, '渔家傲', '欧阳修', '暖日迟迟花袅袅。\n人将红粉争花好。\n花不能言惟解笑。\n金壶倒。\n花开未老人年少。\n车马九门来扰扰。\n行人莫羡长安道。\n丹禁漏声衢鼓报。\n催昏晓。\n长安城里人先老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (651, '渔家傲', '欧阳修', '红粉墙头花几树。\n落花片片和惊絮。\n墙外有楼花有主。\n寻花去。\n隔墙遥见秋千侣。\n绿索红旗双彩柱。\n行人只得偷回顾。\n肠断楼南金锁户。\n天欲暮。\n流莺飞到秋千处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (652, '渔家傲', '欧阳修', '妾本钱塘苏小妹。\n芙蓉花共门相对。\n昨日为逢青伞盖。\n慵不采。\n今朝斗觉凋零晒。\n愁倚画楼无计奈。\n乱红飘过秋塘外。\n料得明年秋色在。\n香可爱。\n其如镜里花颜改。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (653, '渔家傲', '欧阳修', '花底忽闻敲两桨。\n逡巡女伴来寻访。\n酒盏旋将荷叶当。\n莲舟荡。\n时时盏里生红浪。\n花气酒香清厮酿。\n花腮酒面红相向。\n醉倚绿阴眠一饷。\n惊起望。\n船头阁在沙滩上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (654, '渔家傲', '欧阳修', '叶有清风花有露。\n叶笼花罩鸳鸯侣。\n白锦顶丝红锦羽。\n莲女妒。\n惊飞不许长相聚。\n日脚沈红天色暮。\n青凉伞上微微雨。\n早是水寒无宿处。\n须回步。\n枉教雨里分飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (655, '渔家傲', '欧阳修', '荷叶田田青照水。\n孤舟挽在花阴底。\n昨夜萧萧疏雨坠。\n愁不寐。\n朝来又觉西风起。\n雨摆风摇金蕊碎。\n合欢枝上香房翠。\n莲子与人长厮类。\n无好意。\n年年苦在中心里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (656, '渔家傲', '欧阳修', '叶重如将青玉亚。\n花轻疑是红绡挂。\n颜色清新香脱洒。\n堪长价。\n牡丹怎得称王者。\n雨笔露笺匀彩画。\n日炉风炭薰兰麝。\n天与多情丝一把。\n谁厮惹。\n千条万缕萦心下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (657, '渔家傲', '欧阳修', '粉蕊丹青描不得。\n金针线线功难敌。\n谁傍暗香轻采摘。\n风淅淅。\n船头触散双。\n夜雨染成天水碧。\n朝阳借出胭脂色。\n欲落又开人共惜。\n秋气逼。\n盘中已见新荷的。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (658, '渔家傲', '欧阳修', '幽鹭谩来窥品格。\n双鱼岂解传消息。\n绿柄嫩香频采摘。\n心似织。\n条条不断谁牵役。\n珠泪暗和清露滴。\n罗衣染尽秋江色。\n对面不言情脉脉。\n烟水隔。\n无人说似长相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (659, '渔家傲', '欧阳修', '楚国细腰元自瘦。\n文君腻脸谁描就。\n日夜鼓声催箭漏。\n昏复昼。\n红颜岂得长如旧。\n醉拆嫩房红蕊嗅。\n天丝不断清香透。\n却傍小阑凝望久。\n风满袖。\n西池月上人归後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (660, '渔家傲', '欧阳修', '喜鹊填河仙浪浅。\n云早在星桥畔。\n街鼓黄昏霞尾暗。\n炎光敛。\n金钩侧倒天西面。\n一别经年今始见。\n新欢往恨知何限。\n天上佳期贪眷恋。\n良宵短。\n人间不合催银箭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (661, '渔家傲', '欧阳修', '乞巧楼头云幔卷。\n浮花催洗严妆面。\n花上蛛丝寻得遍。\n颦笑浅。\n双眸望月牵红线。\n奕奕天河光不断。\n有人正在长生殿。\n暗付金钗清夜半。\n千秋愿。\n年年此会长相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (662, '渔家傲', '欧阳修', '别恨长长欢计短。\n疏锺促漏真堪怨。\n此会此情都未半。\n星初转。\n鸾琴凤乐匆匆卷。\n河鼓无言西北盼。\n香蛾有恨东南远。\n脉脉横波珠泪满。\n归心乱。\n离肠便逐星桥断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (663, '渔家傲', '欧阳修', '九日欢游何处好。\n黄花万蕊雕阑绕。\n通体清香无俗调。\n天气好。\n烟滋露结功多少。\n日脚清寒高下照。\n宝钉密缀圆斜小。\n落叶西园风袅袅。\n催秋老。\n丛边莫厌金尊倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (664, '渔家傲', '欧阳修', '青女霜前催得绽。\n金钿乱散枝头遍。\n落帽台高开雅宴。\n芳尊满。\n花吹在流霞面。\n桃李三春虽可羡。\n莺来蝶去芳心乱。\n争似仙潭秋水岸。\n香不断。\n年年自作茱萸伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (665, '渔家傲', '欧阳修', '露娇黄风摆翠。\n人间晚秀非无意。\n仙格淡妆天与丽。\n谁可比。\n女真装束真相似。\n筵上佳人牵翠袂。\n纤纤玉手新蕊。\n美酒一杯花影腻。\n邀客醉。\n红琼共作熏熏媚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (666, '渔家傲', '欧阳修', '对酒当歌劳客劝。\n惜花只惜年华晚。\n寒艳冷香秋不管。\n情眷眷。\n凭栏尽日愁无限。\n思抱芳期随塞雁。\n悔无深意传双燕。\n怅望一枝难寄远。\n人不见。\n楼头望断相思眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (667, '玉楼春', '欧阳修', '风迟日媚烟光好。\n绿树依依芳意早。\n年华容易即凋零，春色只宜长恨少。\n池塘隐隐惊雷晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (668, '玉楼春', '欧阳修', '西亭饮散清歌阕。\n花外迟迟宫漏发。\n涂金烛引紫骝嘶，柳曲西头归路别。\n佳辰只恐幽期阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (669, '玉楼春', '欧阳修', '春山敛黛低歌扇。\n暂解吴钩登祖宴。\n画楼钟动已魂销，何况马嘶芳草岸。\n青门柳色随人远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (670, '玉楼春', '欧阳修', '尊前拟把归期说。\n未语春容先惨咽。\n人生自是有情痴，此恨不关风与月。\n离歌且莫翻新阕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (671, '玉楼春', '欧阳修', '洛阳正值芳菲节。\n艳清香相间发。\n游丝有意苦相萦，垂柳无端争赠别。\n杏花红处青山缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (672, '玉楼春', '欧阳修', '残春一夜狂风雨。\n断送红飞花落树。\n人心花意待留春，春色无情容易去。\n高楼把酒愁独语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (673, '玉楼春', '欧阳修', '常忆洛阳风景媚。\n烟暖风和添酒味。\n莺啼宴席似留人，花出墙头如有意。\n别来已隔千山翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (674, '玉楼春', '欧阳修', '池塘水绿春微暖。\n记得玉真初见面。\n从头歌韵响铮，入破舞腰红乱旋。\n玉钩帘下香阶畔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (675, '玉楼春', '欧阳修', '两翁相遇逢佳节。\n正值柳绵飞似雪。\n便须豪饮敌青春，莫对新花羞白发。\n人生聚散如弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (676, '玉楼春', '欧阳修', '西湖南北烟波阔。\n风里丝簧声韵咽。\n舞馀裙带绿双垂，酒入香腮红一抹。\n杯深不觉琉璃滑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (677, '玉楼春', '欧阳修', '燕鸿过後春归去。\n细算浮生千万绪。\n来如春梦几多时，去似朝云无觅处。\n闻琴解神仙侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (678, '玉楼春', '欧阳修', '蝶飞芳草花飞路。\n把酒已嗟春色暮。\n当时枝上落残花，今日水流何处去。\n楼前独绕鸣蝉树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (679, '玉楼春', '欧阳修', '别後不知君远近。\n触目凄凉多少闷。\n渐行渐远渐无书，水阔鱼沈何处问。\n夜深风竹敲秋韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (680, '玉楼春', '欧阳修', '红条约束琼肌稳。\n拍碎香檀催急衮。\n陇头呜咽水声繁，叶下间关莺语近。\n美人才子传芳信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (681, '玉楼春', '欧阳修', '檀槽碎响金丝拨。\n露湿浔阳江上月。\n不知商妇为谁愁，一曲行人留夜发。\n画堂花月新声别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (682, '玉楼春', '欧阳修', '春葱指甲轻拢拈。\n五彩垂条双袖卷。\n雪香浓透紫檀槽，胡语急随红玉腕。\n当头一曲情何限。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (683, '玉楼春', '欧阳修', '金花盏面红烟透。\n舞急香茵随步皱。\n青春才子有新词，红粉佳人重劝酒。\n也知自为伤春瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (684, '玉楼春', '欧阳修', '雪云乍变春云簇。\n渐觉年华堪送目。\n北枝梅蕊犯寒开，南浦波纹如酒绿。\n芳菲次第还相续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (685, '玉楼春', '欧阳修', '黄金弄色轻於粉。\n濯濯春条如水嫩。\n为缘力薄未禁风，不奈多娇长似困。\n腰柔乍怯人相近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (686, '玉楼春', '欧阳修', '珠帘半下香销印。\n二月东风催柳信。\n琵琶傍畔且寻思，鹦鹉前头休借问。\n惊鸿过後生离恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (687, '玉楼春', '欧阳修', '沈沈庭院莺吟弄。\n日暖烟和春气重。\n绿杨娇眼为谁回，芳草深心空自动。\n倚阑无语伤离凤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (688, '玉楼春', '欧阳修', '去时梅萼初凝粉。\n不觉小桃风力损。\n梨花最晚又凋零，何事归期无定准。\n阑干倚遍重来凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (689, '玉楼春', '欧阳修', '酒美春浓花世界。\n得意人人千万态。\n莫教辜负艳阳天，过了堆金何处买。\n已去少年无计奈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (690, '玉楼春', '欧阳修', '湖边柳外楼高处。\n望断云山多少路。\n阑干倚遍使人愁，又是天涯初日暮。\n轻无管系狂无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (691, '玉楼春', '欧阳修', '南园粉蝶能无数。\n度翠穿红来复去。\n倡条冶叶恣留连，飘荡轻於花上絮。\n朱阑夜夜风兼露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (692, '玉楼春', '欧阳修', '江南三月春光老。\n月落禽啼天未晓。\n露和啼血染花红，恨过千家烟树杪。\n云垂玉枕屏山小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (693, '玉楼春', '欧阳修', '东风本是开花信。\n及至花时风更紧。\n吹开吹谢苦匆匆，春意到头无处问。\n把酒临风千万恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (694, '玉楼春', '欧阳修', '阴阴树色笼晴昼。\n清淡园林春过後。\n杏腮轻粉日催红，池面绿罗风卷皱。\n佳人向晚新妆就。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (695, '玉楼春', '欧阳修', '芙蓉斗晕燕支浅。\n留著晚花开小宴。\n画船红日晚风清，柳色溪光晴照暖。\n美人争劝梨花盏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (696, '渔家傲', '欧阳修', '正月斗杓初转势。\n金刀剪彩功夫异。\n称庆高堂欢幼稚。\n看柳意。\n偏从东面春风至。\n十四新蟾圆尚未。\n楼前乍看红灯试。\n冰散绿池泉细细。\n鱼欲戏。\n园林已是花天气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (697, '渔家傲', '欧阳修', '二月春耕昌杏密。\n百花次第争先出。\n惟有海棠梨第一。\n深浅拂。\n天生红粉真无匹。\n画栋归来巢未失。\n双双款语怜飞乙。\n留客醉花迎晓日。\n金盏溢。\n却忧风雨飘零疾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (698, '渔家傲', '欧阳修', '三月清明天婉娩。\n晴川祓禊归来晚。\n况是踏青来处远。\n犹不倦。\n秋千别闭深庭院。\n更值牡丹开欲遍。\n酴压架清香散。\n花底一尊谁解劝。\n增眷恋。\n东风回晚无情绊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (699, '渔家傲', '欧阳修', '四月园林春去後。\n深深密幄阴初茂。\n折得花枝犹在手。\n香满袖。\n叶间梅子青如豆。\n风雨时时添气候。\n成行新笋霜筠厚。\n题就送春诗几首。\n聊对酒。\n樱桃色照银盘溜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (700, '渔家傲', '欧阳修', '五月榴花妖艳烘。\n绿杨带雨垂垂重。\n五色新丝缠角粽。\n金盘送。\n生绡画扇盘双凤。\n正是浴兰时节动。\n菖蒲酒美清尊共。\n叶里黄骊时一弄。\n犹松。\n等闲惊破纱窗梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (701, '渔家傲', '欧阳修', '六月炎天时霎雨。\n行云涌出奇峰露。\n沼上嫩莲腰束素。\n风兼露。\n梁王宫阕无烦暑。\n畏日亭亭残蕙炷。\n傍帘乳燕双飞去。\n碧碗敲冰倾玉处。\n朝与暮。\n故人风快凉轻度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (702, '渔家傲', '欧阳修', '七月新秋风露早。\n渚莲尚拆庭梧老。\n是处瓜华时节好。\n金尊倒。\n人间采缕争祈巧。\n万叶敲声凉乍到。\n百虫啼晚烟如扫。\n箭漏初长天杳杳。\n人语悄。\n那堪夜雨催清晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (703, '渔家傲', '欧阳修', '八月秋高风历乱。\n衰兰败芷红莲岸。\n皓月十分光正满。\n清光畔。\n年年常愿琼筵看。\n社近愁看归去燕。\n江天空阔云容漫。\n宋玉当时情不浅。\n成幽怨。\n乡关千里危肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (704, '渔家傲', '欧阳修', '九月霜秋秋已尽。\n烘林败叶红相映。\n惟有东篱黄菊盛。\n遗金粉。\n人家帘幕重阳近。\n晓日阴阴晴未定。\n授衣时节轻寒嫩。\n新雁一声风又劲。\n云欲凝。\n雁来应有吾乡信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (705, '渔家傲', '欧阳修', '十月小春梅蕊绽。\n红炉画阁新妆遍。\n鸳帐美人贪睡暖。\n梳洗懒。\n玉壶一夜轻澌满。\n楼上四垂帘不卷。\n天寒山色偏宜远。\n风急雁行吹字断。\n红日晚。\n江天雪意云撩乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (706, '渔家傲', '欧阳修', '十一月新阳排寿宴。\n黄锺应管添宫线。\n猎猎寒威云不卷。\n风头转。\n时看雪霰吹人面。\n南至迎长知漏箭。\n书云纪候冰生妍。\n腊近探春春尚远。\n闲庭院。\n梅花落尽千千片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (707, '渔家傲', '欧阳修', '十二月严凝天地闭。\n莫嫌台榭无花卉。\n惟有酒能欺雪意。\n增豪气。\n直教耳热笙歌沸。\n陇上雕鞍惟数骑。\n猎围半合新霜里。\n霜重鼓声寒不起。\n千人指。\n马前一雁寒空坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (708, '渔家傲', '欧阳修', '正月新阳生翠。\n花苞柳线春犹浅。\n帘幕千重方半卷。\n池冰泮。\n东风吹水琉璃软。\n渐好凭阑醒醉眼。\n陇梅暗落芳英断。\n初日已知长一线。\n清宵短。\n梦魂怎奈珠宫远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (709, '渔家傲', '欧阳修', '二月春期看已半。\n江边春色青犹短。\n天气养花红日暖。\n深深院。\n真珠帘额初飞燕。\n渐觉衔杯心绪懒。\n酒侵花脸娇波慢。\n一捻闲愁无处遣。\n牵不断。\n游丝百尺随风远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (710, '渔家傲', '欧阳修', '三月芳菲看欲暮。\n胭脂泪洒梨花雨。\n宝马绣轩南陌路。\n笙歌举。\n踏青斗草人无数。\n强欲留春春不住。\n东皇肯信韶容故。\n安得此身如柳絮。\n随风去。\n穿帘透幕寻朱户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (711, '渔家傲', '欧阳修', '四月芳林何悄悄。\n绿阴满地青梅小。\n南陌采桑何窈窕。\n争语笑。\n乱丝满腹吴蚕老。\n宿酒半醒新睡觉。\n雏莺相语匆匆晓。\n惹得此情萦寸抱。\n休临眺。\n楼头一望皆芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (712, '渔家傲', '欧阳修', '五月薰风才一信。\n初荷出水清香嫩。\n乳燕学飞帘额峻。\n谁借问。\n东邻期约尝佳酝。\n漏短日长人乍困。\n裙腰减尽柔肌损。\n一撮眉尖千叠恨。\n慵整顿。\n黄梅雨细多闲闷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (713, '渔家傲', '欧阳修', '六月炎蒸何太盛。\n海榴灼灼红相映。\n天外奇峰千掌迥。\n风影定。\n汉宫圆扇初成咏。\n珠箔初褰深院静。\n绛绡衣窄冰肤莹。\n睡起日高堆酒兴。\n厌厌病。\n宿酲和梦何时醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (714, '渔家傲', '欧阳修', '七月芙蓉生翠水。\n明霞拂脸新妆媚。\n疑是楚宫歌舞妓。\n争宠丽。\n临风起舞夸腰细。\n乌鹊桥边新雨霁。\n长河清水冰无地。\n此夕有人千里外。\n经年岁。\n犹嗟不及牵牛会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (715, '渔家傲', '欧阳修', '八月微凉生枕簟。\n金盘露洗秋光淡。\n池上月华开宝鉴。\n波潋滟。\n故人千里应凭槛。\n蝉树无情风苒苒。\n燕归碧海珠帘。\n沈臂冒霜潘鬓减。\n愁黯黯。\n年年此夕多悲感。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (716, '渔家傲', '欧阳修', '九月重阳还又到。\n东篱菊放金钱小。\n月下风前愁不少。\n谁语笑。\n吴娘捣练腰肢袅。\n槁叶半轩慵更扫。\n凭阑岂是闲临眺。\n欲向南云新雁道。\n休草草。\n来时觅取伊消耗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (717, '渔家傲', '欧阳修', '十月轻寒生晚暮。\n霜华暗卷楼南树。\n十二阑干堪倚处。\n聊一顾。\n乱山衰草还家路。\n悔别情怀多感慕。\n胡笳不管离心苦。\n犹喜清宵长数鼓。\n双绣户。\n梦魂尽远还须去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (718, '渔家傲', '欧阳修', '律应黄锺寒气苦。\n冰生玉水云如絮。\n千里乡关空倚慕。\n无尺素。\n双鱼不食南鸿渡。\n把酒遣愁愁已去。\n风吹酒力愁还聚。\n却忆兽炉追旧处。\n头懒举。\n炉灰剔尽痕无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (719, '渔家傲', '欧阳修', '腊月年光如激浪。\n冻云欲折寒根向。\n谢女雪诗真绝唱。\n无比况。\n长堤柳絮飞来往。\n便好开尊夸酒量。\n酒阑莫遣笙歌放。\n此去青春都一饷。\n休怅望。\n瑶林即日堪寻访。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (720, '南歌子', '欧阳修', '凤髻金泥带，龙纹玉掌梳。\n走来窗下笑相扶。\n爱道画眉深浅、入时无。\n弄笔偎人久，描花试手初。\n等闲妨了绣功夫。\n笑问双鸳鸯字、怎生书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (721, '御街行', '欧阳修', '夭非华艳轻非雾。\n来夜半、天明去。\n来如春梦不多时，去似朝云何处。\n乳鸡酒燕，落星沈月，城头鼓。\n参差渐辨西池树。\n朱阁斜欹户。\n绿苔深径少人行，苔上屐痕无数。\n遗香馀粉，剩衾闲枕，天把多情赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (722, '桃源忆故人', '欧阳修', '梅梢弄粉香犹嫩。\n欲寄江南春信。\n别後寸肠萦损。\n说与伊争稳。\n小炉独守寒灰尽。\n忍泪低头画尽。\n眉上万重新恨。\n竟日无人问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (723, '桃源忆故人', '欧阳修', '莺愁燕苦春归去。\n寂寂花飘红雨。\n碧草绿杨歧路。\n况是长亭暮。\n少年行客情难诉。\n泣对东风无语。\n目断两三烟树。\n翠隔江淹浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (724, '临江仙', '欧阳修', '柳外轻雷池上雨，雨声滴碎荷声。\n小楼西角断虹明。\n阑干倚处，待得月华生。\n燕子飞来窥画栋，玉钩垂下帘旌。\n凉波不动簟纹平。\n水精双枕，傍有堕钗横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (725, '临江仙', '欧阳修', '记得金銮同唱第，春风上国繁华。\n如今薄宦老天涯。\n十年歧路，空负曲江花。\n闻说阆山通阆苑，楼高不见君家。\n孤城寒日等闲斜。\n离愁难尽，红树远连霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (726, '圣无忧・乌夜啼', '欧阳修', '世路风波险，十年一别须臾。\n人生聚散长如此，相见且欢娱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (727, '浪淘沙', '欧阳修', '把酒祝东风。\n且共从容。\n垂杨紫陌洛城东。\n总是当时携手处，游遍芳丛。\n聚散苦匆匆。\n此恨无穷。\n今年花胜去年红。\n可惜明年花更好，知与谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (728, '浪淘沙', '欧阳修', '花外倒金翘。\n饮散无。\n柔桑蔽日柳迷条。\n此地年时会一醉，还是春朝。\n今日举轻桡。\n帆影飘飘。\n长亭回首短亭遥。\n过尽长亭人更远，特地魂销。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (729, '浪淘沙', '欧阳修', '五岭麦秋残。\n荔子初丹。\n绛纱囊里水晶丸。\n可惜天教生处远，不近长安。\n往事忆开元。\n妃子偏怜。\n一从魂散马嵬关。\n只有红尘无驿使，满眼骊山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (730, '浪淘沙', '欧阳修', '万恨苦绵绵。\n旧约前欢。\n桃花溪畔柳阴间。\n几度日高春垂重，绣户深关。\n楼外夕阳闲。\n独自凭阑。\n一重水隔一重山。\n水阔山高人不见，有泪无言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (731, '浪淘沙', '欧阳修', '今日北池游。\n漾漾轻舟。\n波光潋滟柳条柔。\n如此春来春又去，白了人头。\n好妓好歌喉。\n不醉难休。\n劝君满满酌金瓯。\n纵使花时常病酒，也是风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (732, '定风波', '欧阳修', '把酒花前欲问他。\n对花何吝醉颜酡。\n春到几人能烂赏。\n何况。\n无情风雨等闲多。\n艳树香丛都几许。\n朝暮。\n惜红愁粉奈情何。\n好是金船浮玉浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (733, '定风波', '欧阳修', '把酒花前欲问伊。\n忍嫌金盏负春时。\n红颜不能旬日看。\n宜算。\n须知开谢只相随。\n蝶去蝶来犹解恋。\n难见。\n回头还是度年期。\n莫候饮阑花已尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (734, '定风波', '欧阳修', '把酒花前欲问公。\n对花何事诉金锺。\n为问去年春甚处。\n虚度。\n莺声撩乱一场空。\n今岁春来须爱惜。\n难得。\n须知花面不长红。\n待得酒醒君不见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (735, '定风波', '欧阳修', '把酒花前欲问君。\n世间何计可留春。\n纵使青春留得住。\n虚语。\n无情花对有情人。\n任是好花须落去。\n自古。\n红颜能得几时新。\n暗想浮生何时好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (736, '定风波', '欧阳修', '过尽韶华不可添。\n小楼红日下层檐。\n春睡觉来情绪恶。\n寂寞。\n杨花缭乱拂珠帘。\n早是闲愁依旧在。\n无奈。\n那堪更被宿酲兼。\n把酒送春惆怅甚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (737, '定风波', '欧阳修', '对酒追欢莫负春。\n春光归去可饶人。\n昨日红芳今绿树。\n已暮。\n残花飞絮两纷纷。\n粉面丽姝歌窈窕。\n清妙。\n尊前信任醉醺醺。\n不是狂心贪燕乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (738, '蓦山溪', '欧阳修', '新正初破，三五银蟾满。\n纤手染香罗，剪红莲、满城开遍。\n楼台上下，歌管咽春风，驾香轮，停宝马，只待金乌晚。\n帝城今夜，罗绮谁为伴。\n应卜紫姑神，问归期、相思望断。\n天涯情绪，对酒且开颜，春宵短。\n春寒浅。\n莫待金杯暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (739, '浣溪沙', '欧阳修', '云曳香绵彩柱高。\n绛旗风出花梢。\n一梭红带往来抛。\n束素美人羞不打，却嫌裙慢褪纤腰。\n日斜深院影空摇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (740, '浣溪沙', '欧阳修', '堤上游人逐画船。\n拍堤春水四垂天。\n绿杨楼外出秋千。\n白发戴花君莫笑，六么催拍盏频传。\n人生何处似尊前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (741, '浣溪沙', '欧阳修', '湖上朱桥响画轮。\n溶溶春水浸春云。\n碧琉璃滑净无尘。\n当路游丝萦醉客，隔花啼鸟唤行人。\n日斜归去奈何春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (742, '浣溪沙', '欧阳修', '叶底青青杏子垂。\n枝头薄薄柳绵飞。\n日高深院晚莺啼。\n堪恨风流成薄幸，断无消息道归期。\n托腮无语翠眉低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (743, '浣溪沙', '欧阳修', '青杏园林著酒香。\n佳人初著薄罗裳。\n柳丝摇曳燕飞忙。\n乍雨乍晴花自落，闲愁闲闷昼偏长。\n为谁消瘦损容光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (744, '浣溪沙', '欧阳修', '红粉佳人白玉杯。\n木兰船稳棹歌催。\n绿荷风里笑声来。\n细雨轻烟笼草树，斜桥曲水绕楼台。\n夕阳高处画屏开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (745, '浣溪沙', '欧阳修', '翠袖娇鬟舞石州。\n两行红粉一时羞。\n新声难逐管弦愁。\n白发主人年未老，清时贤相望偏优。\n一尊风月为公留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (746, '浣溪沙', '欧阳修', '灯尽垂花月似霜。\n薄帘映月两交光。\n酒醺红粉自生香。\n双手舞馀拖翠袖，一声歌已金觞。\n休回娇眼断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (747, '浣溪沙', '欧阳修', '十载相逢酒一卮。\n故人才见便开眉。\n老来游旧更同谁。\n浮世歌欢真易失，宦途离合信难期。\n尊前莫惜醉如泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (748, '御带花', '欧阳修', '青春何处风光好，帝里偏爱元夕。\n万重绘彩，构一屏峰岭，半空金碧。\n宝檠银，耀绛幕、龙虎腾掷。\n沙堤远，雕轮绣毂，争走五王宅。\n雍容熙熙昼，会乐府神姬，海洞仙客。\n拽香摇翠，称执手行歌，锦街天陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (749, '虞美人', '欧阳修', '炉香昼永龙烟白。\n风动金鸾额。\n画屏寒掩小山川。\n睡容初起枕痕圆。\n坠花钿。\n楼高不及烟霄半。\n望尽相思眼。\n艳阳刚爱挫愁人。\n故生芳草碧连云。\n怨王孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (750, '鹤冲天', '欧阳修', '梅谢粉，柳拖金。\n香满旧园林。\n养花天气半晴阴。\n花好却愁深。\n花无数。\n愁无数。\n花好却愁春去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (751, '夜行船', '欧阳修', '忆昔西都欢纵。\n自别後、有谁能共。\n伊川山水洛川花，细寻思、旧游如梦。\n今日相逢情愈重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (752, '夜行船', '欧阳修', '满眼东风飞絮。\n催行色、短亭春暮。\n落花流水草连云，看看是、断肠南浦。\n檀板未终人去去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (753, '洛阳春・一落萦', '欧阳修', '红纱未晓黄鹂语。\n蕙炉销兰炷。\n锦屏罗幕护春寒，昨夜三更雨。\n绣帘闲倚吹轻絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (754, '雨中花・夜行船', '欧阳修', '千古都门行路。\n能使离歌声苦。\n送尽行人，花残春晚，又到君东去。\n醉藉落花吹暖絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (755, '越溪春', '欧阳修', '三月十三寒食日，春色遍天涯。\n越溪阆苑繁华地，傍禁垣、珠翠烟霞。\n红粉墙头，秋千影里，临水人家。\n归来晚驻香车。\n银箭透窗纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (756, '贺圣朝影・添声杨柳枝', '欧阳修', '白雪梨花红粉桃。\n露华高。\n垂杨慢舞绿丝绦。\n草如袍。\n风过小池轻浪起，似江皋。\n千金莫惜买香醪。\n且陶陶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (757, '洞天春', '欧阳修', '莺啼绿树声早。\n槛外残红未扫。\n露点真珠遍芳草。\n正帘帏清晓。\n秋千宅院悄悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (758, '忆汉月', '欧阳修', '红艳几枝轻袅。\n新被东风开了。\n倚烟啼露为谁娇，故惹蝶怜蜂恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (759, '清平乐', '欧阳修', '小庭春老。\n碧砌红萱草。\n长忆小阑闲共绕。\n携手绿丛含笑。\n别来音信全乖。\n旧期前事堪猜。\n门掩日斜人静，落花愁点青苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (760, '凉州令・梁州令', '欧阳修', '翠树芳条。\n的的裙腰初染。\n佳人携手弄芳菲，绿阴红影，共展双纹簟。\n插花照影窥鸾鉴。\n只恐芳容减。\n不堪零落春晚，青苔雨後深红点。\n一去门闲掩。\n重来却寻朱槛。\n离离秋实弄轻霜，娇红脉脉，似见胭脂脸。\n人非事往眉空敛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (761, '南乡子', '欧阳修', '翠密红繁。\n水国凉生未是寒。\n雨打荷花珠不定，轻翻。\n冷泼鸳鸯锦翅斑。\n尽日凭阑。\n弄蕊拈花仔细看。\n偷得袅蹄新铸样，无端。\n藏在红房艳粉间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (762, '南乡子', '欧阳修', '雨後斜阳。\n细细风来细细香。\n风定波平花映水，休藏。\n照出轻盈半面妆。\n路隔秋江。\n莲子深深隐翠房。\n意在莲心无问处，难忘。\n泪红腮不记行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (763, '鹊桥仙', '欧阳修', '月波清霁，烟容明淡，灵汉旧期还至。\n鹊迎桥路接天津，映夹岸、星榆点缀。\n云屏未卷，仙鸡催晓，肠断去年情味。\n多应天意不教长，恁恐把、欢娱容易。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (764, '圣无忧・乌夜啼', '欧阳修', '珠帘卷，暮云愁。\n垂杨暗锁青楼。\n烟雨如画，轻风吹旋收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (765, '摸鱼儿', '欧阳修', '卷绣帘、梧桐秋院落，一霎雨添新绿。\n对小池闲立残妆浅，向晚水纹如。\n凝远目。\n恨人去寂寂，凤枕孤难宿。\n倚阑不足。\n看燕拂风檐，蝶翻露草，两两长相逐。\n双眉促。\n可惜年华婉娩，西风初弄庭菊。\n况伊家年少，多情未已难拘束。\n那堪更趁凉景，追寻甚处垂杨曲。\n佳期过尽，但不说归来，多应忘了，云屏去时祝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (766, '少年游', '欧阳修', '去年秋晚此园中。\n携手玩芳丛。\n拈花嗅蕊，恼烟撩雾，拼醉倚西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (767, '少年游', '欧阳修', '肉红圆样浅心黄。\n枝上巧如装。\n雨轻烟重，无天气，啼破晓来妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (768, '少年游', '欧阳修', '玉壶冰莹兽炉灰。\n人起绣帘开。\n春从一夜，六花开尽，不待剪刀催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (769, '鹧鸪天', '欧阳修', '学画宫眉细细长。\n芙蓉出水斗新妆。\n只知一笑能倾国，不信相看有断肠。\n双黄鹄，两鸳鸯。\n迢迢云水恨难忘。\n早知今日长相忆，不及从初莫作双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (770, '千秋岁', '欧阳修', '罗衫满袖，尽是忆伊泪。\n残妆粉，馀香被。\n手把金尊酒，未饮先如醉。\n但向道，厌厌成病皆因你。\n离思迢迢远，一似长江水。\n去不断，来无际。\n红笺著意写，不尽相思意。\n为个甚，相思只在心儿里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (771, '千秋岁', '欧阳修', '画堂人静，翡翠帘前月。\n鸾帷凤枕虚铺设。\n风流难管束，一去音书歇。\n到而今，高梧冷落西风切。\n未语先垂泪，滴尽相思血。\n魂欲断，情难绝。\n都来些子事，更与何人说。\n为个甚，心头见底多离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (772, '醉蓬莱', '欧阳修', '见羞容敛翠，嫩脸匀红，素腰袅娜。\n红药阑边，恼不教伊过。\n半掩娇羞，语声低颤，问道有人知麽。\n强整罗裙，偷回波眼，佯行佯坐。\n更问假如，事还成後，乱了云鬟，被娘猜破。\n我且归家，你而今休呵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (773, '于飞乐', '欧阳修', '宝奁开，美鉴静，一掬清蟾。\n新妆脸，旋学花添。\n蜀红衫，双绣蝶、裙缕鹣鹣。\n寻思前事，小屏风、仍画江南。\n怎空教、草解宜男。\n柔桑密、又过春蚕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (774, '鼓笛慢・水龙吟', '欧阳修', '缕金裙轻纱，透红莹玉真堪爱。\n多情更把，眼儿斜盼，眉儿敛黛。\n舞态歌阑，困偎香脸，酒红微带。\n便直饶、更有丹青妙手，应难写、天然态。\n长恐有时不见，每饶伊、百般娇呆。\n眼穿肠断，如今千种，思量无奈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (775, '看花回', '欧阳修', '晓色初透东窗，醉魂方觉。\n恋恋绣衾半拥，动万感脉脉，春思无托。\n追想少年，何处青楼贪欢乐。\n当媚景，恨月愁花，算伊全妄凤帏约。\n空泪滴、真珠暗落。\n又被谁、连宵留著。\n不晓高天甚意，既付与风流，却恁情薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (776, '蝶恋花', '欧阳修', '几度兰房听禁漏。\n臂上残妆，印得香盈袖。\n酒力融融香汗透。\n春娇入眼横波溜。\n不见些时眉已皱。\n水阔山遥，乍向分飞後。\n大抵有情须感旧。\n肌肤拼为伊销瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (777, '蝶恋花', '欧阳修', '宝琢珊瑚山样瘦。\n缓髻轻拢，一朵云生袖。\n昨夜佳人初命偶。\n论情旋旋移相就。\n几叠鸳衾红浪皱。\n暗觉金钗，磔磔声相扣。\n一自楚台人梦後。\n凄凉暮雨沾绣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (778, '蝶恋花', '欧阳修', '一掬天和金粉腻。\n莲子心中，自有深深意。\n意密莲深秋正媚。\n将花寄恨无人会。\n桥上少年桥下水。\n小棹归时，不语牵红袂。\n浪溅荷心圆又碎。\n无端欲伴相思泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (779, '蝶恋花', '欧阳修', '百种相思千种恨。\n早是伤春，那更春醪困。\n薄辜人终不愤。\n何时枕畔分明问。\n懊恼风流心一寸。\n强醉偷眠，也即依前闷。\n此意为君君不信。\n泪珠滴尽愁难尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (780, '武陵春', '欧阳修', '宝幄华灯相见夜，妆脸小桃红。\n斗帐香檀翡翠笼。\n携手恨匆匆。\n金泥双结同心带，留与记情浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (781, '梁州令', '欧阳修', '红杏墙头树。\n紫萼香心初吐。\n新年花发旧时枝，徘徊千绕，独共东风语。\n阳台一梦如云雨。\n为问今何处。\n离情别恨多少，条条结向垂杨缕。\n此事难分付。\n初心本谁先许。\n窃香解佩两沈沈，知他而今，记得当初否。\n谁教薄轻相误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (782, '渔家傲', '欧阳修', '为爱莲房都一柄。\n双苞双蕊双红影。\n雨势断来风色定。\n秋水静。\n仙郎彩女临鸾镜。\n妾有容华君不省。\n花无恩爱犹相并。\n花却有情人薄。\n心耿耿。\n因花又染相思病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (783, '渔家傲', '欧阳修', '昨日采花花欲尽。\n隔花闻道潮来近。\n风猎紫荷声又紧。\n低难奔。\n莲茎刺惹香腮损。\n一缕艳痕红隐隐。\n新霞点破秋蟾晕。\n罗袖挹残心不稳。\n羞人问。\n归来剩把胭脂衬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (784, '渔家傲', '欧阳修', '一夜越溪秋水满。\n荷花开过溪南岸。\n贪采嫩香星眼慢。\n疏回眄。\n郎船不觉来身畔。\n罢采金英收玉腕。\n回身急打船头转。\n荷叶又浓波又浅。\n无方便。\n教人只得抬娇面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (785, '渔家傲', '欧阳修', '近日门前溪水涨。\n郎船几度偷相访。\n船小难开红斗帐。\n无计向。\n合欢影里空惆怅。\n愿妾身为红菡萏。\n年年生在秋江上。\n重愿郎为花底浪。\n无隔障。\n随风逐雨长来往。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (786, '渔家傲', '欧阳修', '妾解清歌并巧笑。\n郎多才俊兼年少。\n何事抛儿行远道。\n无音耗。\n江头又绿王孙草。\n昔日采花呈窈窕。\n玉容长笑花枝老。\n今日采花添懊恼。\n伤怀抱。\n玉容不及花枝好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (787, '一斛珠', '欧阳修', '今朝祖宴。\n可怜明夜孤灯馆。\n酒醒明月空床满。\n翠被重重，不似香肌暖。\n愁肠恰似沈香篆。\n千回万转萦还断。\n梦中若得相寻见。\n却愿春宵，一夜如年远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (788, '惜芳时・思归乐', '欧阳修', '因倚兰台翠云。\n睡未足、双眉尚锁。\n潜身走向伊行坐。\n孜孜地、告他梳裹。\n发妆酒冷重温过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (789, '洞仙歌令・洞仙歌', '欧阳修', '楼前乱草，是离人方寸。\n倚遍阑干意无尽。\n罗巾掩，宿粉残眉、香未减，人与天涯共远。\n香闺知人否，长是厌厌，拟写相思寄归信。\n未写了，泪成行、早满香笺。\n相思字、一时滴损。\n便直饶、伊家总无情，也拼了一生，为伊成病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (790, '洞仙歌令・洞仙歌', '欧阳修', '情知须病，奈自家先肯。\n天甚教伊恁端正。\n忆年时、兰棹独倚春风，相怜处、月影花光相映。\n别来凭谁诉，空寄香笺，拟问前欢甚时更。\n後约与新期，易失难寻，空肠断、损风流心性。\n除只把、芳尊强开颜，奈酒到愁肠，醉了还醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (791, '鹊踏枝・蝶恋花', '欧阳修', '一曲尊前开画扇。\n暂近还遥，不语仍低面。\n直至情多缘少见。\n千金不直双回眄。\n苦恨行云容易散。\n过尽佳期，争向年芳晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (792, '品令', '欧阳修', '渐素景。\n金风劲。\n早是凄凉孤冷。\n那堪闻、蛩吟穿金井。\n唤愁绪难整。\n懊恼人人薄。\n负云期雨信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (793, '燕归梁', '欧阳修', '风摆红藤卷绣帘。\n宝鉴慵拈。\n日高梳洗几时。\n金盆水、弄纤纤。\n髻云谩残花淡，和娇媚、瘦岩岩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (794, '燕归梁', '欧阳修', '屏里金炉帐外灯。\n掩春睡腾腾。\n绿云堆枕乱。\n犹依约、那回曾。\n人生少有，相怜到老，宁不被天憎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (795, '圣无忧・乌夜啼', '欧阳修', '相别重相遇。\n恬如一梦须臾。\n尊前今日欢娱事，放盏旋成虚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (796, '锦香囊', '欧阳修', '一寸相思无著处。\n甚夜长难度。\n灯花前、几转寒更，桐叶上、数声秋雨。\n真个此心终难负。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (797, '系裙腰', '欧阳修', '水轩檐幕透薰风。\n银塘外、柳烟浓。\n方床遍展鱼鳞簟，碧纱笼。\n小墀面、对芙蓉。\n玉人共处霜鸳枕，和娇困、睡朦胧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (798, '阮郎归', '欧阳修', '浓香搓粉细腰肢。\n青螺深画眉。\n玉钗撩乱挽人衣。\n娇多长睡迟。\n绣帘角，月痕低。\n仙郎东路归。\n泪红满面湿胭脂。\n兰房怨别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (799, '阮郎归', '欧阳修', '去年今日落花时。\n依前又见伊。\n淡匀双脸浅匀眉。\n青衫透玉肌。\n才会面，便相思。\n相思无尽期。\n这回相见好相知。\n相知已是迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (800, '阮郎归', '欧阳修', '玉肌花脸柳腰肢。\n红妆浅黛眉。\n翠鬟斜语声低。\n娇羞云雨时。\n伊怜我，我怜伊。\n心儿与眼儿。\n绣屏深处说深期。\n幽情谁得知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (801, '怨春郎', '欧阳修', '为伊家，终日闷。\n受尽惶谁问。\n不知不觉上心头，悄一霎身心，顿也没处顿。\n恼愁肠，成寸寸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (802, '滴滴金', '欧阳修', '尊前一把横波溜。\n彼此心儿有。\n曲屏深幌解香罗，花灯微透。\n偎人欲语眉先皱。\n红玉困春酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (803, '卜算子', '欧阳修', '极得醉中眠，迤逦翻成病。\n莫是前生负你来，今世里、教孤冷。\n言约全无定。\n是谁先薄。\n不惯孤眠惯成双，奈奴子、心肠硬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (804, '感庭秋・撼庭秋', '欧阳修', '红笺封了还重拆。\n这添追忆。\n且教伊见我，别来翠减香销端的。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (805, '满路花・促拍满路花', '欧阳修', '铜荷融烛泪，金兽啮扉环。\n兰堂春夜疑，惜更残。\n落花风雨，向晓作轻寒。\n金龟朝早，香衾馀暖，娇由自慵眠。\n小鬟无事须来唤，呵破点唇檀。\n回身还、却背屏山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (806, '好女儿令・好女儿', '欧阳修', '眼细眉长。\n宫样梳妆。\n鞋儿走向花下立著。\n一身绣出，两同心字，浅浅金黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (807, '南乡子', '欧阳修', '浅浅画双眉。\n取次梳妆也便宜。\n洒着胭脂红扑面，须知。\n更有何人得似伊。\n宝帐烛残时。\n好个温柔模样儿。\n月里仙郎清似玉，相期。\n些子精神更与谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (808, '南乡子', '欧阳修', '好个人人，深点唇儿淡抹腮。\n花下相逢、忙走怕人猜。\n遗下弓弓小绣鞋。\n袜重来。\n半乌云金凤钗。\n行笑行行连抱得，相挨。\n一向娇痴不下怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (809, '踏莎行', '欧阳修', '碧藓回廊，绿杨深院。\n偷期夜入帘犹卷。\n照人无奈月华明，潜身却恨花深浅。\n密约如沈，前欢未便。\n看看掷尽金壶箭。\n阑干敲遍不应人，分明帘下闻裁剪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (810, '踏莎行', '欧阳修', '云母屏低，流苏帐小。\n矮床薄被秋将晓。\n乍凉天气未寒时，平明窗外闻啼鸟。\n困榴花，香添蕙草。\n佳期须及朱颜好。\n莫言多病为多情，此身甘向情中老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (811, '诉衷情', '欧阳修', '歌时眉黛舞时腰。\n无处不娇饶。\n初剪菊、欲登高。\n天气怯鲛绡。\n紫丝障，绿杨桥。\n路迢迢。\n酒阑歌罢，一度归时，一度魂消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (812, '诉衷情', '欧阳修', '离怀酒病两忡忡。\n倚枕梦无踪。\n可怜有人今夜，胆小怯房空。\n杨柳绿，杏梢红。\n负春风。\n迢迢别恨，脉脉归心，付与征鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (813, '恨春迟', '欧阳修', '欲借江梅荐饮。\n望陇驿、音息沈沈。\n住在柳州东，彼此相思，梦回云去难寻。\n归燕来时花期浸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (814, '盐角儿', '欧阳修', '增之太长，减之太短，出群风格。\n施朱太赤，施粉太白，倾城颜色。\n慧多多，娇的的。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (815, '盐角儿', '欧阳修', '人生最苦，少年不得，鸳帏相守。\n西风时节，那堪话别，双蛾频皱。\n暗消魂，重回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (816, '忆秦娥', '欧阳修', '十五六，脱罗裳，长恁黛眉蹙。\n红玉暖，入人怀，春困熟。\n展香，帐前明画烛。\n眼波长，斜浸鬓云绿。\n看不足。\n苦残宵、更漏促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (817, '少年游', '欧阳修', '绿云双插金翘。\n年纪正妖饶。\n汉妃束素，小蛮垂柳，都占洛城腰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (818, '踏莎行慢', '欧阳修', '独自上孤舟。\n倚危樯目断。\n难成暮雨，更朝云散。\n凉劲残叶乱。\n新月照、澄波浅。\n今夜里，厌厌离绪难销遣。\n强来就枕，灯残漏永，合相思眼。\n分明梦见如花面。\n依前是、旧庭院。\n新月照，罗幕挂，珠帘卷。\n渐向晓，脉然睡觉如天远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (819, '蕙香囊・鹊桥仙', '欧阳修', '身作琵琶，调全宫羽，佳人自然用意。\n宝檀槽在雪胸前，倚香脐、横枕琼臂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (820, '玉楼春', '欧阳修', '艳冶风情天与措。\n清瘦肌肤冰雪妒。\n百年心事一宵同，愁听鸡声窗外度。\n信阻青禽云雨暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (821, '玉楼春', '欧阳修', '半辐霜绡亲手剪。\n香染青蛾和泪卷。\n画时横接媚霞长，印处双沾愁黛浅。\n当时付我情何限。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (822, '玉楼春', '欧阳修', '红楼昨夜相将饮。\n月近珠帘花近枕。\n银缸照客酒方酣，玉漏催人街已禁。\n晚潮去棹浮清浸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (823, '玉楼春', '欧阳修', '金雀双鬟年纪小。\n学画蛾眉红淡扫。\n尽人言语尽人怜，不解此情惟解笑。\n稳着舞衣行动俏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (824, '玉楼春', '欧阳修', '夜来枕上争闲事。\n推倒屏山褰绣被。\n尽人求守不应人，走向碧纱窗下睡。\n直到起来由自。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (825, '定风波', '欧阳修', '把酒花前欲问伊。\n问伊还记那回时。\n黯淡梨花笼月影。\n人静。\n画堂东畔药阑西。\n及至如今都不认。\n难问。\n有情谁道不相思。\n何事碧窗春睡觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (826, '减字木兰花', '欧阳修', '去年残腊。\n曾折梅花相对插。\n人面而今。\n空有花开无处寻。\n天天不远。\n把酒拈花重发愿。\n愿得和伊。\n偎雪眠香似旧时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (827, '减字木兰花', '欧阳修', '年来方寸。\n十日幽欢千日恨。\n未会此情。\n白尽人头可得平。\n区区堪比。\n水趁浮萍风趁水。\n试望瑶京。\n芳草随人上古城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (828, '迎春乐', '欧阳修', '薄纱衫子裙腰匝。\n步轻轻、小罗。\n人前爱把眼儿札。\n香汗透、胭脂蜡。\n良夜永、幽期欢则洽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (829, '一落索', '欧阳修', '小桃风撼香红碎。\n满帘笼花气。\n看花何事却成愁，悄不会、春风意。\n窗在梧桐叶底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (830, '夜行船', '欧阳修', '闲把鸳衾横枕。\n损眉尖、泪痕红沁。\n花时良夜不归来，忍频听、漏移清禁。\n一饷无言都未寝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (831, '夜行船', '欧阳修', '轻捧香腮低枕。\n眼波媚、向人相浸。\n佯娇佯醉索如今，这风情、怎教人禁。\n却与和衣推未寝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (832, '望江南・忆江南', '欧阳修', '江南柳，花柳两相柔。\n花片落时粘酒盏，柳条低处拂人头。\n各自是风流。\n江南月，如镜复如钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (833, '望江南・忆江南', '欧阳修', '江南柳，叶小未成阴。\n人为丝轻那忍折，莺嫌枝嫩不胜吟。\n留著待春深。\n十四五，闲抱琵琶寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (834, '宴瑶池・越江吟', '欧阳修', '恋眼哝心终未改。\n向意间长在。\n都缘为、颜色殊常，见馀花、尽无心爱。\n都为是风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (835, '解仙佩', '欧阳修', '有个人人牵系。\n泪成痕、滴尽罗衣。\n问海约山盟何时。\n镇教人、目断魂飞。\n梦里似偎人睡。\n肌肤依旧骨香腻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (836, '渔家傲', '欧阳修', '战胜归来飞捷奏。\n倾贺酒。\n玉阶遥献南山寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (837, '少年游', '欧阳修', '阑干十二独凭春。\n晴碧远连云。\n千里万里，二月三月，行色苦愁人。\n谢家池上，江淹浦畔，吟魄与离魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (838, '桃源忆故人', '欧阳修', '碧纱影弄东风晓。\n一夜海棠开了。\n枝上数声啼鸟。\n妆点愁多少。\n妒云恨雨腰支袅。\n眉黛不重扫。\n薄不来春老。\n羞带宜男草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (839, '阮郎归', '欧阳修', '雪霜林际见依稀。\n清香已暗期。\n前村已遍倚南枝。\n群花犹未知。\n情似旧，赏休迟。\n看看陇上吹。\n便从今日赏芳菲。\n韶华取次归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (840, '南乡子', '荣', '江上野梅芳。\n粉色盈盈照路傍。\n闲折一枝和雪嗅，思量。\n似个人人玉体香。\n特地起愁肠。\n此恨谁人与寄将。\n山馆寂寥天欲暮，凄凉。\n人转迢迢路转长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (841, '定风波', '王琪', '把酒花前欲问天。\n春来秋去苦茫然。\n风雨满枝花满地。\n何事。\n却教纤草占流年。\n试把钿筝重促柱。\n无绪。\n酒阑清泪滴朱弦。\n赖有玉人相顾好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (842, '祝英台・祝英台近', '王琪', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (843, '望江南・忆江南', '王琪', '江南柳，烟穗拂人轻。\n愁黛空长描不似，舞腰虽瘦学难成。\n天意与风情。\n攀折处，离恨几时平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (844, '望江南・忆江南', '王琪', '江南酒，何处味偏浓。\n醉卧春风深巷里，晓寻香旆小桥东。\n竹叶满金锺。\n檀板醉，人面粉生红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (845, '望江南・忆江南', '王琪', '江南燕，轻扬绣帘风。\n二月池塘新社过，六朝宫殿旧巢空。\n颉颃恣西东。\n王谢宅，曾入绮堂中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (846, '望江南・忆江南', '王琪', '江南竹，清润绝纤埃。\n深径欲留双凤宿，後庭偏映小桃开。\n风月影徘徊。\n寒玉瘦，霜霰信相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (847, '望江南・忆江南', '王琪', '江南草，如种复如描。\n深映落花莺舌乱，绿迷南浦客魂消。\n日日斗青袍。\n风欲转，柔态不胜娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (848, '望江南・忆江南', '王琪', '江南雨，风送满长川。\n碧瓦烟昏沈柳岸，红绡香润入梅天。\n飘洒正潇然。\n朝与暮，长在楚峰前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (849, '望江南・忆江南', '王琪', '江南水，江路转平沙。\n雨霁高烟收素练，风晴细浪吐寒花。\n迢递送星槎。\n名利客，飘泊未还家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (850, '望江南・忆江南', '王琪', '江南岸，云树半晴阴。\n帆去帆来天亦老，潮生潮落日还沈。\n南北别离心。\n兴废事，千古一沾襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (851, '望江南・忆江南', '王琪', '江南月，清夜满西楼。\n云落开时冰吐鉴，浪花深处玉沈钩。\n圆缺几时休。\n星汉迥，风露入新秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (852, '望江南・忆江南', '王琪', '江南雪，轻素剪云端。\n琼树忽惊春意早，梅花偏觉晓香寒。\n冷影褫清欢。\n蟾玉迥，清夜好重看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (853, '失调名', '王琪', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (854, '一络索・一落萦', '陈凤仪', '蜀江春色浓如雾。\n拥双旌归去。\n海棠也似别君难，一点点、啼红雨。\n此去马蹄何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (855, '水调歌头', '苏舜钦', '潇洒太湖岸，淡伫洞庭山。\n鱼龙隐处，烟雾深锁渺弥间。\n方念陶朱张翰，忽有扁舟急桨，撇浪载鲈还。\n落日暴风雨，归路绕汀湾。\n丈夫志，当景盛，耻疏闲。\n壮年何事憔悴，华发改朱颜。\n拟借寒潭垂钓，又恐鸥鸟相猜，不肯傍青纶。\n刺棹穿芦荻，无语看波澜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (856, '永遇乐', '解', '风暖莺娇，露浓花重，天气和煦。\n院落烟收，垂杨舞困，无奈堆金缕。\n谁家巧纵，青楼弦管，惹起梦云情绪。\n忆当时、纹衾粲枕，未尝暂孤鸳侣。\n芳菲易老，故人难聚。\n到此翻成轻误。\n阆苑仙遥，蛮笺纵写、何计传深诉。\n青山绿水，古今长在，惟有旧欢何处。\n空赢得、斜阳暮草，淡烟细雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (857, '阳台梦', '解', '仙姿本寓。\n十二峰前住。\n千里行云行雨。\n偶因鹤驭过巫阳。\n邂逅他、楚襄王。\n无端宋玉夸才赋。\n诬诞人心素。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (858, '点绛唇', '韩琦', '病起恹恹，画堂花谢添憔悴。\n乱红飘砌。\n滴尽胭脂泪。\n惆怅前春，谁向花前醉。\n愁无际。\n武陵回睇。\n人远波空翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (859, '维扬好', '韩琦', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (860, '安阳好・忆江南', '韩琦', '安阳好，形势魏西州。\n曼衍山川环故国，升平歌吹沸高楼。\n和气镇飞浮。\n笼画陌，乔木几春秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (861, '安阳好・忆江南', '韩琦', '安阳好，戟户使君宫。\n白昼锦衣清宴处，铁楹丹榭画图中。\n壁记旧三公。\n棠讼悄，池馆北园通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (862, '望江南・忆江南', '韩琦', '维杨好，灵宇有琼花。\n千点真珠擎素蕊，一环名玉破香葩。\n芳艳信难加。\n如雪貌，绰约最堪夸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (863, '失调名', '沈唐', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (864, '雨中花・夜行船', '沈唐', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (865, '霜叶飞', '沈唐', '霜林凋晚，危楼迥，登临无限秋思。\n望中闲想，洞庭波面，乱红初坠。\n更萧索、风吹渭水。\n长安飞舞千门里。\n变景摧芳榭，唯有兰衰暮丛，菊残馀蕊。\n回念花满华堂，美人一去，镇掩香闺经岁。\n又观珠露，碎点苍苔，败梧飘砌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (866, '念奴娇', '沈唐', '杏花过雨，渐残红零落，胭脂颜色。\n流水飘香人渐远，难托春心脉脉。\n恨别王孙，墙阴目断，手把青梅摘。\n金鞍何处，绿杨依旧南陌。\n消散云雨须臾，多情因甚，有轻离轻拆。\n燕语千般，争解说、些子伊家消息。\n厚约深盟，除非重见，见了方端的。\n而今无奈，寸肠千恨堆积。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (867, '望海潮', '沈唐', '山光凝翠，川容如画，名都自古并州。\n箫鼓沸天，弓刀似水，连营十万貔貅。\n金骑走长楸。\n少年人一一，锦带吴钩。\n路入榆关，雁飞汾水正宜秋。\n追思昔日风流。\n有儒将醉吟，才子狂游。\n松偃旧亭，城高故国，空馀舞榭歌楼。\n方面倚贤候。\n便恐为霖雨，归去难留。\n好向西溪，恣携弦管宴兰舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (868, '望南云慢', '沈唐', '木叶轻飞，乍雨歇亭皋，帘卷秋光。\n栏隈砌角，绽拒霜几处，蓓深浅红芳。\n应恨开时晚，伴翠菊、风前并香。\n晓来寒露，嫩脸低凝，似带啼妆。\n堪伤。\n记得佳人，当时怨别，盈腮泪粉行行。\n而今最苦，奈千里身心，两处凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (869, '鹤冲天', '杜安世', '清明天气。\n永日愁如醉。\n台榭绿阴浓，薰风细。\n燕子巢方就，盆池小，新荷蔽。\n恰是逍遥际。\n单夹衣裳，半栊软玉肌体。\n石榴美艳，一撮红绡比。\n窗外数修篁，寒相倚。\n有个关心处，难相见、空凝睇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (870, '两同心', '杜安世', '巍巍剑外，寒霜覆林枝。\n望衰柳、尚色依依。\n暮天静、雁阵高飞。\n入碧云际。\n江山秋色，遣客心悲。\n蜀道ε行迟。\n瞻京都迢递。\n听巴峡、数声猿啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (871, '玉阑干', '杜安世', '珠帘怕卷春残景。\n小雨牡丹零欲尽。\n庭轩悄悄燕高空，风飘絮、绿苔侵径。\n欲将幽恨传愁信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (872, '浣溪沙', '杜安世', '模样偏宜掌上怜。\n云如双鬓玉如颜。\n身材轻妙眼儿单。\n幽会未成双怅望，深情欲诉两艰难。\n空教魂梦到巫山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (873, '浣溪沙', '杜安世', '横画功夫想未全。\n双双文彩羽仪鲜。\n和鸣偕老是天然。\n暮雨并深流细草，暖风交颈傍清涟。\n羡他真个好因缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (874, '惜春令', '杜安世', '春梦无凭犹懒起。\n银烛尽、画帘低垂。\n小庭杨柳黄金翠，桃脸两三枝。\n妆阁慵梳洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (875, '惜春令', '杜安世', '今夕重阳秋意深。\n篱边散、嫩菊开金。\n万里霜天林叶坠，萧索动离心。\n臂上茱萸新。\n似旧年、堪赏光阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (876, '踏莎行', '杜安世', '雨霁风光，春分天气。\n千花百草争明媚。\n画梁新燕一双双，玉笼鹦鹉爱孤睡。\n薜荔依墙，莓苔满地。\n青楼几处歌声丽。\n蓦然旧事上心头，无言敛皱眉山翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (877, '踏莎行', '杜安世', '夜雨朝晴，东风微冷。\n雕梁燕子闲相并。\n後园次第数芳菲，千香百艳年年定。\n步险楼高，人赊途迥。\n烟芜冉冉斜阳暝。\n红笺写尽寄无因，想伊不信人成病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (878, '踏莎行', '杜安世', '嫩柳成阴，残花双舞。\n尘消院落新经雨。\n洞房深掩日长天，珠帘时有沈烟度。\n夜梦凄凉，晨妆薄注。\n香肌瘦尽宽金缕。\n到头终是恶因缘，当初只被多情误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (879, '踏莎行', '杜安世', '闲院秋千，又还拆了。\n绿苔遍地青春老。\n画楼日晚燕归巢，红稀翠盛梅初小。\n窈窕身轻，怎禁烦恼。\n罗衣渐减怯风峭。\n韶华好景想多才，厌厌只为书音少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (880, '端正好', '杜安世', '栏菊愁烟沾秋露。\n天微冷、双燕辞去。\n月明空照别离苦。\n透素光、穿朱户。\n夜来西风雕寒树。\n凭阑望、迢遥长路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (881, '端正好', '杜安世', '每逢春来长如病。\n玉容瘦、薄妆相称。\n双欢未经成孤令。\n奈厚约、全无定。\n众禽啾唧声愁听。\n相思事、多少春恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (882, '端正好', '杜安世', '露落风高桐叶坠。\n小庭院、秋凉佳气。\n兰堂聚饮华筵启。\n罢令曲、呈珠缀。\n晚天行云凝香袂。\n新声内、分明心意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (883, '端正好', '杜安世', '野禽林栖啾唧语。\n闲庭院、残阳将暮。\n兰堂静悄珠帘。\n想玉人、归何处。\n喜鹊几回薄无据。\n愁都在、双眉头聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (884, '菩萨蛮', '杜安世', '游丝欲堕还重上。\n春残日永人相望。\n花共燕争飞。\n青梅细雨枝。\n离愁终未解。\n忘了依前在。\n拟待不寻思。\n刚眠梦见伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (885, '菩萨蛮', '杜安世', '锦机织了相思字。\n天涯路远无由寄。\n寒雁只衔芦。\n何曾解寄书。\n缄封和血泪。\n目断西江水。\n拟欲托双鱼。\n问君情有无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (886, '丑奴儿・采桑子', '杜安世', '樱桃谢了梨花发，红白相催。\n燕子归来。\n几处风帘绣户开。\n人生乐事知多少，且酌金杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (887, '凤衔杯', '杜安世', '人生不似月初圆。\n叹分飞、容易经年。\n凄惨断云片雨、□□□。\n□□□、□□□。\n金钵小，玉槽悭。\n想至今、谁为相怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (888, '凤衔杯', '杜安世', '留花不住怨花飞。\n向南园、情绪依依。\n可惜倚红斜白、一枝枝。\n经宿雨、暮江披。\n凭朱槛，把金卮。\n对芳丛、惆怅多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (889, '少年游', '杜安世', '小轩深院是秋时。\n风叶堕高枝。\n疏帘静永，薄帷清夜，暑退觉寒微。\n凄凉天气离愁意，音书杳难期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (890, '玉楼春', '杜安世', '玉烛光明正旦好。\n斗柄东回春太早。\n岭寒犹锁去年梅，江暖新催今岁草。\n蜀国熙熙冬令杪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (891, '玉楼春', '杜安世', '风解池冰蝉翅薄。\n庭树枝枯笼翠萼。\n背寒迎暖起犹慵，闲卷珠帘凭画阁。\n晴景融融烟漠漠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (892, '玉楼春', '杜安世', '晴景融融春色浅。\n落尽梅花千万片。\n小池冰解水纹生，消息未闻梁上燕。\n楼倚轻寒风力软。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (893, '玉楼春', '杜安世', '三月牡丹呈艳态。\n壮观人间春世界。\n鲛绡玉槛作扃栊，淹雅洞中王母队。\n不奈风吹兼日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (894, '玉楼春', '杜安世', '纶命忽从天上至。\n便绾兵权辞漕计。\n汉廷起草旧郎官，蜀部坐筹新将帅。\n红旆碧幢春色里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (895, '玉楼春', '杜安世', '春景抛人无处问。\n多谢石榴花又喷。\n茜罗揉出碎英繁，红蜡缕成香萼润。\n血色新裙羞莫近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (896, '玉楼春', '杜安世', '三月初三春渐老。\n遍地残花风暗扫。\n命俦啸侣拥笙歌，临水泛觞游宴好。\n浮利浮名何足道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (897, '河满子', '杜安世', '细雨开红杏，新妆粉面鲜明。\n东君何事交来早，更无绿叶同荣。\n独倚青楼吟赏，目前无限轻盈。\n命薄不依栏槛，或占郊。\n清香繁艳真堪爱，枉教寂寞凋零。\n相次牡丹芍药，王孙谁道多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (898, '河满子', '杜安世', '柳嫩不禁摇动，梅残尽任飘零。\n雨馀天气来深院，向阳纤草重青。\n寂寞小桃初绽，两三枝上红英。\n又见云中归雁，断续和鸣。\n年年依旧无情绪，镇长冷落银屏。\n不语闲寻往事，微风频动帘旌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (899, '山亭柳', '杜安世', '晓来风雨，万花飘落。\n叹韶光虚过。\n却芳草萋萋，映楼台、淡烟漠漠。\n纷纷絮飞院宇，燕子过朱阁。\n玉容淡妆添寂寞。\n檀郎孤愿太情薄。\n数归期，绝信约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (900, '合欢带', '杜安世', '楼台高下玲珑。\n斗芳草、绿阴浓。\n芍药孤栖香艳晚，见樱桃、万颗初红。\n巢喧乳燕，珠帘镂曳，满户香风。\n罩纱帏、象床屏枕，昼眠才似朦胧。\n起来无语更兼慵。\n念分明、事成空。\n被你厌厌牵系我，怪纤腰、绣带宽松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (901, '更漏子', '杜安世', '雪肌轻，花脸薄。\n愁困不梳掠。\n眉翠袅，眼波长。\n偎人言语香。\n看难厌，怜不足。\n苦恨别离何速。\n珠树远，彩鸾孤。\n今生重见无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (902, '更漏子', '杜安世', '脸如花，花不笑。\n双脸胜花能笑。\n肌似玉，玉非温。\n肌温胜玉温。\n既相逢，情不重。\n何似当初休共。\n情既重，却分飞。\n争如不见伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (903, '更漏子', '杜安世', '镂金环，连玉珥。\n颗颗蚌蛤相缀。\n偎粉面，映莲腮。\n露浓花正开。\n冷光凝，员影重。\n几度偷期摇动。\n山枕上，恐人知。\n摘嫌纤手迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (904, '喜迁莺', '杜安世', '花不尽，柳无穷。\n应与我心同。\n觥船一棹百分空。\n何处不相逢。\n朱弦悄。\n知音少。\n天若有情应老。\n劝君看取利名场。\n今古梦忙忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (905, '杜韦娘', '杜安世', '暮春天气，莺老燕子忙如织。\n间嫩叶题诗哨梅小，乍遍水、新萍圆碧。\n初牡丹谢了，秋千搭起，垂杨暗锁深深陌。\n暖风轻，尽日闲把、榆钱乱掷。\n恨寂寂。\n芳容衰减，顿玳枕困无力。\n为少年、狂荡恩情薄，尚未有、归来消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (906, '胡捣练', '杜安世', '数枝半敛半开时，洞阁晓妆新注。\n宝香格艳姿天赋。\n甘被群芳妒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (907, '少年游', '杜安世', '小楼归燕又黄昏。\n寂寞锁高门。\n轻风细雨，惜花天气，相次过春分。\n画堂无绪，初燃绛蜡，罗帐掩馀薰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (908, '凤栖梧・蝶恋花', '杜安世', '整顿云鬟初睡起。\n庭院无风，尽日帘垂地。\n画阁巢新燕声喜。\n杨花狂散无拘系。\n近来早是添憔悴。\n金缕衣宽，赛过宫腰细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (909, '凤栖梧・蝶恋花', '杜安世', '池上新秋帘幕卷。\n菡萏娇红，鉴里西施面。\n衰柳摇风尚柔软。\n眠沙临清浅。\n新翻归翅云间燕。\n满地槐花，尽日蝉声乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (910, '凤栖梧・蝶恋花', '杜安世', '闲上江楼初雨过。\n满袖清风，微散谁知我。\n莲脸佳人颜未破。\n沙洲两两鸳鸯卧。\n时有渔歌相应和。\n叠秀危横，黛拨山千朵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (911, '凤栖梧・蝶恋花', '杜安世', '惆怅留春留不住。\n欲到清和，背我堂堂去。\n飞絮落花和细雨。\n凄凉庭院流莺度。\n更被闲愁相赚误。\n梦断高唐，回首桃源路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (912, '浪淘沙', '杜安世', '後约无凭。\n往事堪惊。\n秋蛩永夜绕床鸣。\n展转寻思求好梦，还又难成。\n愁思若浮云。\n消尽重生。\n佳人何处独盈盈。\n可惜一天无用月，照空为谁明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (913, '浪淘沙', '杜安世', '又是春暮。\n落花飞絮。\n子规啼尽断肠声，秋千庭院，红旗彩索，淡烟疏雨。\n念念相思苦。\n黛眉长聚。\n碧池惊散睡鸳鸯，当初容易分飞去。\n恨孤儿欢侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (914, '浪淘沙', '杜安世', '帘外微风。\n云雨回踪。\n银烬冷锦帏中。\n枕上深盟，年少心事，陡顿成空。\n岭外白头翁。\n到没由逢。\n一床鸳被叠香红。\n明月满庭花似绣，闷不见虫虫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (915, '更漏子', '杜安世', '庭远途程。\n算万山千水，路入神京。\n暖日春郊，绿柳红杏，香迳舞燕流莺。\n客馆悄悄闲庭，堪惹旧恨深。\n有多少驱驱，蓦岭涉水，枉费身心。\n思想厚利高名。\n谩惹得忧烦，枉度浮生。\n幸有青松，白云深洞，清闲且乐升平。\n长是宦游羁思，别离泪满襟。\n望江乡踪迹，旧游题书，尚自分明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (916, '行香子', '杜安世', '黄金叶细，碧玉枝纤。\n初暖日、当乍晴天。\n向武昌溪畔，於彭泽门前。\n陶潜影，张绪态，两相牵。\n数株堤面，几树桥边。\n嫩垂条、絮荡轻绵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (917, '巫山一段云', '杜安世', '笑拟条风戏，装迟谷雨催。\n彩云飞下柳楼台。\n千朵一时开。\n惜恐尘埃染，惊疑紫府来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (918, '生查子', '杜安世', '关山魂梦长，寒雁音书少。\n两鬓可怜青，只为相思老。\n归傍碧纱窗，说向人人道。\n真个别离难，不似相逢好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (919, '贺圣朝', '杜安世', '东君造物无凝滞。\n芳容相替。\n杏花桃萼一时开，就中明媚。\n绿丛金朵，枝长叶细。\n称花王相待。\n万般堪爱，暂时见了，断肠无计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (920, '贺圣朝', '杜安世', '牡丹盛拆春将暮。\n群芳羞妒。\n几时流落在人间，半间仙露。\n馨香艳冶，吟看醉赏，叹谁能留住。\n莫辞持烛夜深深，怨等闲风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (921, '安公子', '杜安世', '又是春将半。\n杏花零落闲庭院。\n天气有时阴淡淡，绿杨轻软。\n连画阁、绣帘半卷。\n招新燕。\n残黛敛、独倚阑干遍。\n暗思前事，月下风流，狂踪无限。\n惜恐莺花晚。\n更堪容易相抛远。\n离恨结成心上病，几时消散。\n空际有、断云片片。\n遥峰暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (922, '苏幕遮', '杜安世', '尽思量，还叵耐。\n因甚当初，故故相招买。\n早是幽欢多障碍。\n更遣分飞，脉脉如天外。\n有心怜，无计奈。\n两处厌厌，一点虚恩爱。\n独上高楼临暮霭。\n凭暖朱阑，这意无人会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (923, '渔家傲', '杜安世', '微雨初收月映云。\n巢栖燕子欲黄昏。\n花片不飞风力困。\n春色尽。\n蜡梅枝上樱□嫩。\n谁撼金环锁深洞。\n薰馀乍厌锦衾温。\n消灭玉肌谁与问。\n朱明近。\n日长无事添闲闷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (924, '渔家傲', '杜安世', '疏雨才收淡泞天。\n微云绽处月婵娟。\n寒雁一声人正远。\n添幽怨。\n那堪往事思量遍。\n谁道绸缪两意坚。\n水萍风絮不相缘。\n舞鉴鸾肠虚寸断。\n芳容变。\n好将憔悴教伊见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (925, '渔家傲', '杜安世', '每到春来长如病。\n玉容瘦与薄妆称。\n不惯被人抛掷。\n思当本。\n奈向後期全无定。\n早是厌厌愁欲凝。\n花间众禽愁难听。\n天赋多情翻成恨。\n有谁问。\n花屏一点炉烟暝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (926, '剔银灯', '杜安世', '昨夜一场风雨。\n催促牡丹归去。\n孙武宫中，石崇楼下，多情怎生为主。\n真疑洛浦。\n云水算、杳无重数。\n独倚阑干凝伫。\n香片乱沾尘土。\n争似当初，不曾相见，免恁恼人肠肚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (927, '剔银灯', '杜安世', '夜永衾寒梦觉。\n翠屏共、绣帏灯照。\n就枕思量，离多会少。\n孤负小欢轻笑。\n风流争表。\n空惹尽、一生烦恼。\n写遍香笺，分剖鳞翼，路遥难到。\n泪眼愁肠，朝朝暮暮，去便不知音耗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (928, '剔银灯', '杜安世', '好事争如不遇。\n可惜许、多情相误。\n月下风前，偷期窃会，共把衷肠分付。\n尤云雨。\n正缱绻、朝朝暮暮。\n无奈别离情绪。\n和酒病、双眉长聚。\n往事凄凉，佳音迢递，似此因缘谁做。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (929, '临江仙', '杜安世', '太史占天云物好，初阳律合黄锺。\n日缠南极北郊风。\n雪花先柳絮，飞舞透帘栊。\n圣运时和兼岁稔，歌欢处处皆同。\n簪声相庆晓光中。\n金炉红兽炭，一举寿杯空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (930, '临江仙', '杜安世', '遍地残花庭院静，流莺对对相过。\n万条风柳间婆娑。\n樱桃初弄色，萱草自成窠。\n早是芳菲时节晚，追游期会无多。\n眉山敛翠近秋波。\n日长初睡起，愁与病相和。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (931, '采明珠', '杜安世', '雨乍收，小院尘消，云淡天高露冷。\n坐看月华生，射玉楼清莹。\n蟋蟀鸣金井。\n下帘帏、悄悄空阶，败叶坠风，惹动闲愁，千端万绪难整。\n秋夜永。\n凉天迥。\n可不念光景。\n嗟薄命。\n倏忽少年，忍交孤令。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (932, '朝玉阶・朝天子', '杜安世', '春色欺人拂眼清。\n柳条绿丝软，雪花轻。\n黄金才钺掩银屏。\n阴沈深院静，语娇莺。\n美人春困宝钗横。\n惜花芳态，泪盈盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (933, '朝玉阶・朝天子', '杜安世', '帘卷春寒小雨天。\n牡丹花落尽，悄庭轩。\n高空双燕舞翩翩。\n无风轻絮坠，暗苔钱。\n拟将幽怨写香笺。\n中心多少事，语难传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (934, '卜算子', '杜安世', '深院花铺地。\n淡淡阴天气。\n水榭风亭朱明景，又别是、愁情味。\n有情奈无计。\n漫惹成憔悴。\n欲把罗巾暗传寄。\n细认取、斑点泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (935, '卜算子', '杜安世', '尊前一曲歌。\n歌里千重意，才欲歌时泪已流，恨应更、多於泪。\n试问缘何事。\n不语如痴醉。\n我亦情多不忍闻，怕和我、成憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (936, '瑞鹧鸪', '杜安世', '夜来风雨损馀芳。\n数片衰红落槛傍。\n媚景背人容易去，半轩飞絮日空长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (937, '燕归梁', '杜安世', '风摆红绦卷画帘。\n宝鉴慵拈。\n日高梳洗几时。\n金盆水，弄纤纤。\n髻云松衣斜褪，和娇懒、瘦岩岩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (938, '菊花新', '杜安世', '怎奈花残又莺老。\n槛里青梅数枝小。\n新荷长池沼。\n当晴昼、燕子声闹。\n亭栏花绽颜色好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (939, '菊花新', '杜安世', '坐卧双眉镇长敛。\n绣户初开花满院。\n罗帏翠屏空，风微动、玉炉烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (940, '鹊桥仙', '杜安世', '别离情绪，多方开解，却免厌厌似醉。\n楼高终日倚阑干，目断有、千山万水。\n妖娆薄媚，不禁抛摆，渐觉肌肤瘦悴。\n当初相见偶然间，不唤作、如今恁地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (941, '鹊桥仙', '杜安世', '日长天气，深深庭院，又是春愁滋味。\n池边昨夜雨兼风，战红杏、馀香乱坠。\n阴阴亭榭，暖烟轻柳，万缕黄金地。\n一双新燕却重来，但暗把、罗巾掩泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (942, '虞美人', '杜安世', '红颜绿鬓催人老。\n世事何时了。\n君心天意与年光。\n春花未遍已秋霜。\n为谁忙。\n樽前正好闲风月。\n莫话生离别。\n直饶终日踏红尘。\n浮名浮利枉劳神。\n更愁萦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (943, '虞美人', '杜安世', '江亭春晚芳菲尽。\n行色青天近。\n画桥杨柳也多情。\n暗抛飞絮惹前行。\n路尘清。\n彤庭早晚瞻虞舜。\n遥听恩迁峻。\n二年歌宴绮罗人。\n片云疏雨忍漂沦。\n泪沾巾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (944, '虞美人', '杜安世', '炉香昼永龙烟白。\n风动金鸾额。\n画屏细展小山川。\n睡容初起枕痕圆。\n坠花钿。\n楼高不及烟霄半。\n望尽相思眼。\n艳阳刚爱挫愁天。\n故生芳草碧云连。\n怨王孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (945, '凤栖梧・蝶恋花', '杜安世', '秋日楼台在空际。\n画角声沈，历历寒更起。\n深院黄昏人独自。\n想伊遥共伤前事。\n懊恼当初无算计。\n些子欢娱，多少凄凉味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (946, '凤栖梧・蝶恋花', '杜安世', '任在芦花最深处。\n浪静风恬，又泛轻舟去。\n去到滩头遇俦侣。\n散唱狂歌鱼未取。\n不把身心干时务。\n一副轮竿，莫笑闲家具。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (947, '凤栖梧・蝶恋花', '杜安世', '别浦迟留恋清浅。\n菱蔓荷花，尽日妨钩线。\n向晚澄江静如练。\n风送归帆飞似箭。\n鸥鹭相将是家眷。\n坐对云山，一任炎凉变。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (948, '凤栖梧・蝶恋花', '杜安世', '闲把浮生细思算。\n百岁光阴，梦里销除半。\n白首为郎休浩叹。\n偷安自喜身强健。\n多少英贤裨圣旦。\n一个非才，深谢容疏懒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (949, '凤栖梧・蝶恋花', '杜安世', '新月羞光影庭树。\n窗外芭蕉，数点黄昏雨。\n何事秋来无意绪。\n玉容寂寞双眉聚。\n一点银扃绣户。\n莎砌寒蛩，历历啼声苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (950, '忆汉月', '杜安世', '红杏一枝遥见。\n凝露粉愁香怨。\n吹开吹谢任春风，恨流莺、不能拘管。\n曲池连夜雨，绿水上、碎红千片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (951, '诉衷情', '杜安世', '烧残绛蜡泪成痕。\n街鼓报黄昏。\n碧云又阻来信，廊上月侵门。\n愁永夜，拂香。\n待谁温。\n梦兰憔悴，掷果凄凉，两处消魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (952, '朝中措', '杜安世', '养花天气近清明。\n丝雨酿寒轻。\n满眼春工如绣。\n消磨不尽离情。\n行行又宿，小桃旧坞，芳草邮亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (953, '折新荷引・折新荷', '赵', '雨过回廊，圆荷嫩绿新抽。\n越女轻盈，画桡稳泛兰舟。\n芳容艳粉，红香透、脉脉娇羞。\n菱歌隐隐渐遥，依约回眸。\n堤上郎心，波间妆影迟留。\n不觉归时，淡天碧衬蟾钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (954, '梅花曲', '刘几', '汉宫中侍女，娇额半涂黄。\n盈盈粉色凌时，寒玉体、先透薄妆。\n好借月魂来，娉婷画烛旁。\n惟恐随、阳春好梦去，所思飞扬。\n宜向风亭把盏，酬孤艳，醉永夕何妨。\n雪径蕊、真凝密，降回舆、认暗香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (955, '梅花曲', '刘几', '结子非贪，有香不俗，宜当鼎鼐尝。\n偶先红紫，度韶华、玉笛占年芳。\n众花杂色满上林，未能教、腊雪埋藏。\n却怕春风漏泄，一一尽天香。\n不须更御铅黄。\n知国色，禀自天真殊常。\n只裁云缕，奈芳滑、玉体想仙妆。\n少陵为尔东阁。\n美艳激诗肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (956, '梅花曲', '刘几', '浅浅池塘。\n深深庭院，复出短短垣墙。\n年年为尔，若九真巡会、宝惜流芳。\n向人自有，绵渺无言，深意深藏。\n倾国倾城，天教与、抵死芳香。\n袅须金色，轻危欲压，绰约冠中央。\n蒂团红蜡，兰肌粉艳巧能妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (957, '花发状元红慢', '刘几', '三春向暮，万卉成阴、有嘉艳方坼。\n娇姿嫩质。\n冠群品，共赏倾城倾国。\n上苑晴昼暄，千素万红尤奇特。\n绮筵开，会咏歌才子，压倒元白。\n别有芳幽苞小，步障华丝，绮轩油壁。\n与紫鸳鸯、素蛱蝶。\n自清旦、往往连夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (958, '减字木兰花', '元绛', '绿杨阴下。\n短帽轻衫行信马。\n过尽春风。\n踏尽青青打尽红。\n舞鸾歌凤。\n人面湖光红影动。\n醉眼归时。\n人在朱楼曲角西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (959, '映山红慢', '元绛', '谷雨风前，占淑景、名花独秀。\n露国色仙姿，品流第一，春工成就。\n罗帏护日金泥皱。\n映霞腮动檀痕溜。\n长记得天上，瑶池阆苑曾有。\n千匝绕、红玉阑干，愁只恐、朝云难久。\n须款折、绣囊剩戴，细把蜂须频嗅。\n佳人再拜抬娇面，敛红巾、捧金杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (960, '渔家傲', '程师孟', '折柳赠君君且住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (961, '望江南・忆江南', '陈朴', '中黄宝，须向胆中求。\n春帝令行生万物，乾坤膝下与吾俦。\n百脉自流通。\n施造化，左右火双抽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (962, '望江南・忆江南', '陈朴', '玄珠降，丹窟在中宫。\n九候息调重九数，赤波忽迸太阳东。\n心肾始交通。\n逢六变，重六息阴功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (963, '望江南・忆江南', '陈朴', '毛发落，丹左运行阳。\n胎色渐红阴渐小，推移岁运助乾刚。\n育火养中央。\n成物象，五岳辨微茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (964, '望江南・忆江南', '陈朴', '丹往右，四转运行阴。\n逢六闭藏阳户气，玉关泉透合丁壬。\n龟戏任浮沉。\n时出入，无碍贯他心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (965, '望江南・忆江南', '陈朴', '珠自右，飞电入丹城。\n内养婴儿盈尺象，时逢九数采阳精。\n火向水中生。\n烧鬼岳，紫殿势峥嵘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (966, '望江南・忆江南', '陈朴', '日精满，阴魄化无形。\n每遇月圆开北户，神龟时饮碧瑶玲。\n形魄岂能停。\n阳砂赤，阴粉色微青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (967, '望江南・忆江南', '陈朴', '形透日，七转任飞腾。\n幽入深岩图宴坐，息无来去使神凝。\n却粒著奇能。\n生神火，返本气清澄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (968, '望江南・忆江南', '陈朴', '内外遍，八转始还元。\n地带长垂生坎户，周行胎息贯天门。\n太始道方存。\n纯一体，黑赤气常喷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (969, '望江南・忆江南', '陈朴', '丹九转，纯一太初颜。\n内外无为常抱朴，纵横海外与人间。\n功行积丘山。\n青阙诏，玉简赐金环。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (970, '西江月', '张伯端', '内药还同外药，内通外亦须通。\n丹头和合类相同。\n温养两般作用。\n内有天然真火，炉中赫赫长红。\n外炉增减要勤功。\n妙绝无过真种。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (971, '西江月', '张伯端', '此道至神至圣，忧君分薄难消。\n调和铅汞不终朝。\n早睹玄珠形兆。\n志士若能修炼，何妨在市居朝。\n工夫容易药非遥。\n说破人须失笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (972, '西江月', '张伯端', '白虎首经至宝，华池神水真金。\n故知上善利源深。\n不比寻常药品。\n若要修成九转，先须炼己持心。\n依时采取定浮沈。\n进火须防危甚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (973, '西江月', '张伯端', '若要真铅留汞，亲中不离家臣。\n木金间隔会无因。\n须仗媒人勾引。\n本性爱金顺义，金情恋木慈仁。\n相吞相陷却相亲。\n始觉男儿有孕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (974, '西江月', '张伯端', '二八谁家姹女，九三何处郎君。\n自称木液与金精。\n遇土却成三性。\n更假丁公煅炼，夫妻始结欢情。\n河车不敢暂留停。\n运入峰顶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (975, '西江月', '张伯端', '七返朱砂反本，九还金液还真。\n休将寅子数坤申。\n但要五行成准。\n本是水银一味，周流遍历诸辰。\n阴阳数足自通神。\n出入岂离玄牝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (976, '西江月', '张伯端', '雄里内含雌质，负阴抱却阳精。\n两般和合药方成。\n点化魄纤魂胜。\n信道金丹一粒，蛇吞立变龙形。\n鸡餐亦乃化鸾鹏。\n飞入真阳清境。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (977, '西江月', '张伯端', '天地才经否泰，朝昏好识屯蒙。\n辐来辏毂水朝宗。\n妙在抽添运用。\n得一万般皆毕，休分南北西东。\n损之又损慎前功。\n命宝不宜轻弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (978, '西江月', '张伯端', '冬至一阳来服，三旬增一阳爻。\n月中复卦溯晨潮。\n望罢乾终兆。\n日又别为寒暑，阳生复起中宵。\n午时象一阴朝。\n炼药须知昏晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (979, '西江月', '张伯端', '不辨五行四象，那分朱汞铅银。\n修丹火候未曾闻。\n早便称呼居隐。\n不背自思己错，更将错路教人。\n误他永劫在迷津。\n似恁欺心安忍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (980, '西江月', '张伯端', '德行修逾八百，阴功积满三千。\n均齐物我与亲冤。\n始合神仙本愿。\n虎兕刀兵不害，无常火宅难牵。\n宝符降後去朝天。\n稳驾鸾车凤辇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (981, '西江月', '张伯端', '牛女情缘道合，龟蛇类秉天然。\n蟾乌遇朔合婵娟。\n二气相资运转。\n本是乾坤妙用，谁能达此深渊。\n阳阴否隔却成愆。\n怎得天长地远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (982, '西江月', '张伯端', '丹是色身至宝，炼成变化无穷。\n更於性上究真宗。\n决了死生妙用。\n不待他身後世，现前获福神通。\n自从龙虎著斯功。\n尔後谁能继踵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (983, '西江月', '张伯端', '妄想不须强灭，真如何必希求。\n本源自性佛齐修。\n迷悟岂拘先後。\n悟则刹那成佛。\n迷则万劫沦流。\n若能一念契真修。\n灭尽恒沙罪垢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (984, '西江月', '张伯端', '本自无生无灭，强将生灭区分。\n只如罪福亦何根。\n妙体何曾增损。\n我有一轮明镜，从来只为蒙分。\n今朝磨莹照乾坤。\n万象超然难隐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (985, '西江月', '张伯端', '我性入诸佛性，诸方佛性皆然。\n亭亭蟾影照寒泉。\n一月千潭普现。\n小则毫分莫识，大时遍满三千。\n高低不约信方圆。\n说甚短长深浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (986, '西江月', '张伯端', '法法法元无法，空空空亦非空。\n静喧语默本来同。\n梦里何曾说梦。\n有用用中无用，无功功里施功。\n还如果熟自然红。\n莫问如何修种。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (987, '西江月', '张伯端', '善恶一时妄念，荣枯都不关心。\n晦明隐显任浮沈。\n随分肌餐渴饮。\n神静湛然常寂，不妨坐卧歌吟。\n一池秋水碧仍深。\n风动鱼惊尽任。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (988, '西江月', '张伯端', '对镜不须强灭，假名权立菩提。\n色空明暗本来齐。\n真妄体分两种。\n悟则便名静土，更无天竺曹溪。\n谁言极乐在天西。\n了则弥陀出世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (989, '西江月', '张伯端', '人我众生寿者，宁分彼此高低。\n法身通照没吾伊。\n念念体分同异。\n见是何曾是是，闻非未必非非。\n往来诸用不相知。\n生死谁能碍你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (990, '西江月', '张伯端', '住想修行布施，果报不离天人。\n恰如仰箭射浮云。\n坠落祗缘力尽。\n争似无为实相，还须返朴归淳。\n境忘情性任天真。\n以证无生法忍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (991, '西江月', '张伯端', '鱼兔若还入手，自然忘却筌蹄。\n渡河筏子上天梯。\n到彼悉皆遗弃。\n未悟须凭言说，悟来言说皆非。\n虽然四句属无为。\n此等何须脱离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (992, '西江月', '张伯端', '悟了莫求寂灭，随缘只接群迷。\n寻常邪见及提携。\n方便指归实际。\n五眼三身四智，六度万行修齐。\n圆光一颗好摩尼。\n利物兼能自利。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (993, '西江月', '张伯端', '我见时人说性，只夸口急酬机。\n及逢境界转痴迷。\n又与愚人何异。\n说得便须行得，方名言行无亏。\n能将慧剑斩魔魑。\n此号如来正智。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (994, '西江月', '张伯端', '欲了无生妙道，莫如自见真心。\n真心无相亦无音。\n清净法身只恁。\n此道非无外有，非中亦莫求寻。\n二边俱遣弃中心。\n见了名为上品。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (995, '满庭芳', '张伯端', '真铁牛儿，形容丑恶，性刚偏好争驰。\n人人皆有，那角解牵骑。\n种就黄芽满院，更须用、神水浇之。\n宫里，若无此兽，安得似婴儿。\n乾坤真动静，生成家活，总赖於伊。\n饥餐虎髓，渴饮水银池。\n夜半牵车进火，霞光迸、海底腾辉。\n牧童笑，华池宴罢，乘个月明归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (996, '凤栖梧・蝶恋花', '卢氏', '蜀道青天烟霭翳。\n帝里繁华、迢递何时至。\n回望锦川挥粉泪。\n凤钗斜乌云腻。\n钿带双垂金缕细。\n玉玎，露滴寒如水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (997, '家山好', '刘述', '挂冠归去旧烟萝。\n闲身健，养天和。\n功名富贵非由我，莫贪他。\n这歧路、足风波。\n水晶宫里家山好，物外胜游多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (998, '合宫歌', '赵祯', '缵重明。\n端拱保凝命。\n广大孝休德，永锡四海有庆。\n觚坛寓礼正典名。\n幔室雅奏，彩仗崇制定。\n五位仿古甚盛。\n蒿宫光符辰星。\n高秋嘉时款芎灵。\n交累圣。\n上下来顾，寅畏歆纯诚。\n三阶平。\n金气肃，转和景。\n翠葆御双观，巽风兑泽布令。\n脂茶荡墨索清。\n远迩向附，动植咸遂性。\n表里穆悦，庶政醇，熙然胥庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (999, '沁园春', '王拱辰', '华发青云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1000, '好事近', '蔡襄', '瑞雪满京都，宫殿尽成银阙。\n常对素光遥望，是江梅时节。\n如今江上见寒梅，幽香自清绝。\n重看落英残艳，想飘零如雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1001, '踏莎行', '韩绛', '嵩峤云高，洛川波暖。\n举头乔木森无断。\n□□□雨绝风尘，小桥频过春渠满。\n□□离宫，□棱斗焕。\n万家罗绮多游伴。\n□□□□自风□，□□是处喧弦管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1002, '菩萨蛮', '李师中', '子规啼破城楼月。\n画船晓载笙歌发。\n两岸荔枝红。\n万家烟雨中。\n佳人相对泣。\n泪下罗衣湿。\n从此信音稀。\n岭南无雁飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1003, '喜迁莺', '蔡挺', '霜天清晓。\n望紫塞古垒，寒云衰草。\n汗马嘶风，边鸿翻月，垅上铁衣寒早。\n剑歌骑曲悲壮，尽道君恩难报。\n塞垣乐，尽双锦带，山西年少。\n谈笑。\n刁斗静。\n烽火一把，常送平安耗。\n圣主忧边，威灵遐布，骄虏且宽天讨。\n岁华向晚愁思，谁念玉关人老。\n太平也，且欢娱，不惜金尊频倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1004, '喜长新', '王益柔', '秋云朔吹晓徘徊。\n雪照楼台。\n梁王宴召有邹枚。\n相如独逞雄才。\n明烛薰炉香暖，深劝金杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1005, '西江月', '韩维', '早岁相期林下，高年同在尊前。\n风花绣舞乍晴天。\n绿蚁新浮酒面。\n身外虚名电转，人间急景梭传。\n当筵莫惜听朱弦。\n一品归来强健。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1006, '踏莎行', '韩维', '归雁低空，游蜂趁暖。\n凭高目向西云断。\n具茨山外夕阳多，展江亭下春波满。\n双桂情深，千花明焕。\n良辰谁是同游伴。\n辛夷花谢早梅开。\n应须次第调弦管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1007, '减字木兰花', '韩维', '和风动□。\n□□新年□入手。\n世事尘□。\n□□□情近酒□。\n水开湖□。\n□□笙歌波面起。\n相与排□。\n□□□胜特地□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1008, '浪淘沙', '韩维', '饱食日□□。\n□上危亭。\n东风昨夜入□□。\n□□雪晴云□□，□遍银屏。\n回首叹劳生。\n□鼎相承。\n皇恩早晚□□□。\n□□陂边垂钓手，不负幽情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1009, '胡捣练令・胡捣练', '韩维', '夜来风横雨飞狂，满地闲花衰草。\n燕子渐归春悄。\n帘幕垂清晓。\n天将佳景与闲人，美酒宁嫌华皓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1010, '失调名', '韩维', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1011, '失调名', '韩维', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1012, '赏南枝', '曾巩', '暮冬天地闭，正柔木冻折，瑞雪飘飞。\n对景见南山，岭梅露、几点清雅容姿。\n丹染萼、玉缀枝。\n又岂是、一阳有私。\n大抵是、化工独许，使占却先时。\n霜威莫苦凌持。\n此花根性，想群卉争知。\n贵用在和羹，三春里、不管绿是红非。\n攀赏处、宜酒卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1013, '阮郎归', '司马光', '渔舟容易入春山。\n仙家日月闲。\n绮窗纱幌映朱颜。\n相逢醉梦间。\n松露冷，海霞殷。\n匆匆整棹还。\n落花寂寂水潺潺。\n重寻此路难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1014, '西江月', '司马光', '宝髻松松挽就，铅华淡淡妆成。\n青烟翠雾罩轻盈。\n飞絮游丝无定。\n相见争如不见，有情何似无情。\n笙歌散後酒初醒。\n深院月斜人静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1015, '锦堂春・锦堂春慢', '司马光', '红日迟迟，虚廊转影，槐阴迤逦西斜。\n彩笔工夫，难状晚景烟霞。\n蝶尚不知春去，漫绕幽砌寻花。\n奈猛风过後，纵有残红，飞向谁家。\n始知青鬓无价，叹飘零官路，荏苒年华。\n今日笙歌丛里，特地咨嗟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1016, '临江仙', '苏氏', '一夜东风穿绣户，融融暖应佳时。\n春来何处最先知。\n平明堤上柳。\n染遍郁金枝。\n姊妹嬉游时节近，今朝应怨来迟。\n凭谁说与到家期。\n玉钗头上胜，留待远人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1017, '更漏子', '苏氏', '小阑干，深院宇。\n依旧当时别处。\n朱户锁，玉楼空。\n一帘霜日红。\n弄珠江，何处是，望断碧云无际。\n凝泪眼，出重城。\n隔溪羌笛声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1018, '鹊桥仙', '苏氏', '星移斗转，玉蟾西下，渐觉东郊向晓。\n马嘶人语隔霜林，望千里、长安古道。\n珠宫姊妹，相逢方信，别後十分瘦了。\n上林归去正花时，争奈向、花前又老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1019, '踏莎行', '苏氏', '孤馆深沈，晓寒天气。\n解鞍独自阑干倚。\n暗香浮动月黄昏，落梅风送沾衣袂。\n待写红笺，凭谁与寄。\n先教觅取嬉游地。\n到家正是早春时，小桃花下拼沈醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1020, '清平乐', '刘敞', '小山丛桂。\n最有留人意。\n拂叶攀花无限思。\n雨湿浓香满袂。\n别来过了秋光。\n翠帘昨夜新霜。\n多少月宫闲地，娥与借微芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1021, '踏莎行', '刘敞', '蜡炬高高，龙烟细细。\n玉楼十二门初闭。\n疏帘不卷水晶寒，小屏半掩琉璃翠。\n桃叶新声，榴花美味。\n南山宾客东山妓。\n利名不肯放人闲，忙中偷取工夫醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1022, '导引', '王', '忆玉清景，繁盛极当时。\n千古事难追。\n汉家别庙秋风起，空出奉宸衣。\n三山浮海日晖晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1023, '发引', '王', '玉宸朝晚，忽掩赭黄衣。\n愁雾锁金扉。\n蓬莱待得仙丹至，人世已成非。\n龙轩天仗转西畿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1024, '发引', '王', '上林春晚，曾是奉宸游。\n水殿戏龙舟。\n玉箫吹断催仙驭，一去隔千秋。\n游人重到曲江头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1025, '凤箫吟・芳草', '韩缜', '锁离愁，连绵无际，来时陌上初熏。\n绣帏人念远，暗垂珠泪，泣送征轮。\n长亭长在眼，更重重、远水孤云。\n但望极楼高，尽日目断王孙。\n消魂。\n池塘别後，曾行处、绿妒轻裙。\n恁时携素手，乱花飞絮里，缓步香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1026, '蝶恋花', '韩缜姬', '香作风光浓著露。\n正恁双栖，又遣分飞去。\n密诉东君应不许。\n泪波一洒奴衷素。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1027, '浪淘沙', '裴湘', '雁塞说并门。\n郡枕西汾。\n山形高下远相吞。\n古寺楼台依碧嶂，烟景遥分。\n晋庙锁溪云。\n箫鼓仍存。\n牛羊斜日自归村。\n惟有故城禾黍地，前事消魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1028, '浪淘沙', '裴湘', '万国仰神京。\n礼乐纵横。\n葱葱佳气锁龙城。\n日御明堂天子圣，朝会簪缨。\n九陌六街平。\n万国充盈。\n青楼弦管酒如渑。\n别有隋堤烟柳暮，千古含情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1029, '花心动', '阮逸女', '仙苑春浓，小桃开，枝枝已堪攀折。\n乍雨乍晴，轻暖轻寒，渐近赏花时节。\n柳摇台榭东风软，帘栊静、幽禽调舌。\n断魂远、闲寻翠径，顿成愁结。\n此恨无人共说。\n还立尽黄昏，寸心空切。\n强整绣衾，独掩朱扉，簟枕为谁铺设。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1030, '蝶恋花', '滕甫', '叶底无风池面静。\n掬水佳人，拍破青铜镜。\n残月朦胧花弄影。\n新梳斜插乌云鬓。\n拍索闷怀添酒兴。\n旋撷园蔬，随分成盘。\n说与翠微休急性。\n功名富贵皆前定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1031, '蝶恋花', '滕甫', '昼永无人深院静。\n一枕春醒，犹未临镜。\n帘卷新蟾光射影。\n速忙掠起蓬松鬓。\n对景沈吟嗟没兴。\n薄不来，空把杯盘。\n休道妇人多水性。\n今宵独自言无定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1032, '桂枝香', '王安石', '登临送目。\n正故国晚秋，天气初肃。\n千里澄江似练，翠峰如簇。\n归帆去棹残阳里，背西风、酒旗斜矗。\n彩舟云淡，星河鹭起，画图难足。\n念往昔、繁华竞逐。\n叹门外楼头，悲恨相续。\n千古凭高，对此漫嗟荣辱。\n六朝旧事随流水，但寒烟、芳草凝绿。\n至今商女，时时犹唱，後庭遗曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1033, '甘露歌', '王安石', '折得一枝香在手。\n人间应未有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1034, '甘露歌', '王安石', '尽日含毫难比兴。\n都无色可并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1035, '甘露歌', '王安石', '天寒日暮山谷里。\n的砾愁成水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1036, '菩萨蛮', '王安石', '数家茅屋闲临水。\n单衫短帽垂杨里。\n今日是何朝。\n看予度石桥。\n梢梢新月偃。\n午醉醒来晚。\n何物最关情。\n黄鹂三两声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1037, '渔家傲', '王安石', '灯火已收正月半。\n山南山北花撩乱。\n闻说亭新水漫。\n骑款段。\n穿云入坞寻游伴。\n却拂僧床褰素幔。\n千岩万壑春风暖。\n一弄松声悲急管。\n吹梦断。\n西看窗日犹嫌短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1038, '渔家傲', '王安石', '平岸小桥千嶂抱。\n柔蓝一水萦花草。\n茅屋数间窗窈窕。\n尘不到。\n时时自有春风扫。\n午枕觉来闻语鸟。\n眠似听朝鸡早。\n忽忆故人今总老。\n贪梦好。\n茫然忘了邯郸道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1039, '雨霖铃', '王安石', '孜孜。\n向无明里、强作窠窟。\n浮名浮利何济，堪留恋处，轮回仓猝。\n幸有明空妙觉，可弹指超出。\n缘底事、抛了全潮，认一浮沤作瀛渤。\n本源自性天真佛。\n祗些些、妄想中埋没。\n贪他眼花阳艳，谁信道、本来无物。\n一旦茫然，终被阎罗老子相屈。\n便纵有、千种机筹，怎免伊唐突。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1040, '清平乐', '王安石', '云垂平野。\n掩映竹篱茅舍。\n阒寂幽居实潇洒。\n是处绿娇红冶。\n丈夫运用堂堂。\n且莫五角六张。\n若有一卮芳酒，逍遥自在无妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1041, '浣溪沙', '王安石', '百亩中庭半是苔。\n门前白道水萦回。\n爱闲能有几人来。\n小院回廊春寂寂，山桃溪杏两三栽。\n为谁零落为谁开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1042, '诉衷情', '王安石', '常时黄色见眉间。\n松桂我同攀。\n每言天上辛苦，不肯饵金丹。\n怜水静，爱云闲。\n便忘还。\n高歌一曲，岩谷迤逦，宛似商山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1043, '诉衷情', '王安石', '练巾藜杖白云间。\n有兴即跻攀。\n追思往昔如梦，华毂也曾丹。\n尘自扰，性长闲。\n更无还。\n达如周召，穷似丘轲，祗个山山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1044, '诉衷情', '王安石', '茫然不肯住林间。\n有处即追攀。\n将他死语图度，怎得离真丹。\n浆水价，匹如闲。\n也须还。\n何如直截，踢倒军持，赢取沩山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1045, '诉衷情', '王安石', '营巢燕子逞翱翔。\n微志在雕梁。\n碧云举翮千里，其奈有鸾皇。\n临济处，德山行。\n果承当。\n自时降住，一切天魔，扫地焚香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1046, '诉衷情', '王安石', '莫言普化祗颠狂。\n真解作津梁。\n蓦然打个筋斗，直跳过羲皇。\n临济处，德山行。\n果承当。\n将他建立，认作心诚，也是寻香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1047, '南乡子', '王安石', '嗟见世间人。\n但有纤毫即是尘。\n不住旧时无相貌，沈沦。\n祗为从来认识神。\n作麽有疏亲。\n我自降魔转法轮。\n不是摄心除妄想，求真。\n幻化空身即法身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1048, '南乡子', '王安石', '自古帝王州。\n郁郁葱葱佳气浮。\n四百年来成一梦，堪愁。\n晋代衣冠成古丘。\n绕水恣行游。\n上尽层城更上楼。\n往事悠悠君莫问，回头。\n槛外长江空自流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1049, '浪淘沙令', '王安石', '伊吕两衰翁。\n历遍穷通。\n一为钓叟一耕佣。\n若使当时身不遇，老了英雄。\n汤武偶相逢。\n风虎云龙。\n兴王祗在笑谈中。\n直至如今千载後，谁与争功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1050, '望江南・忆江南', '王安石', '归依众，梵行四威仪。\n愿我遍游诸佛土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1051, '望江南・忆江南', '王安石', '归依法，法法不思议。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1052, '望江南・忆江南', '王安石', '归依佛，弹指越三祗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1053, '望江南・忆江南', '王安石', '三界里，有取总灾危。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1054, '西江月', '王安石', '梅好惟嫌淡伫，天教薄与胭脂。\n真妃初出华清池。\n酒入琼姬半醉。\n东阁诗情易动，高楼玉管休吹。\n北人浑作杏花疑。\n惟有青枝不似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1055, '渔家傲', '王安石', '隔岸桃花红未半。\n枝头已有蜂儿乱。\n惆怅武陵人不管。\n清梦断。\n亭亭伫立春宵短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1056, '清平乐', '王安石', '留春不住。\n费尽莺儿语。\n满地残红宫锦污。\n昨夜南园风雨。\n小怜初上琵琶。\n晓来思绕天涯。\n不肯画堂朱户，春风自在杨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1057, '生查子', '王安石', '雨打江南树。\n一夜花开无数。\n绿叶渐成阴，下有游人归路。\n与君相逢处。\n不道春将暮。\n把酒祝东风，且莫恁、匆匆去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1058, '谒金门', '王安石', '春又老。\n南陌酒香梅小。\n遍地落花浑不扫。\n梦回情意悄。\n红笺寄与添烦恼。\n细写相思多少。\n醉後几行书字小。\n泪痕都了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1059, '菩萨蛮', '王安石', '海棠乱发皆临水。\n君知此处花何似。\n凉月白纷纷。\n香风隔岸闻。\n啭枝黄鸟近。\n隔岸声相应。\n随意坐莓苔。\n飘零酒一杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1060, '千秋岁引', '王安石', '别馆寒砧，孤城画角。\n一派秋声入寥廓。\n东归燕从海上去，南来雁向沙头落。\n楚台风，庾楼月，宛如昨。\n无奈被些名利缚。\n无奈被他情担阁。\n可惜风流总闲却。\n当初漫留华表语，而今误我秦楼约。\n梦阑时，酒醒後，思量著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1061, '定风波', '吴氏1', '待得明年重把酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1062, '蜡梅香', '吴师孟', '锦里阳和，看万木凋时，早梅独秀。\n珍馆琼楼畔，正降跗初吐，华将茂。\n国艳天葩，真澹伫、雪肌清瘦。\n似广寒宫，铅华未御，自然妆就。\n凝睇倚朱阑，喷清香暗度，易袭襟袖。\n好与花为主，宜秉烛、频观泛湘酎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1063, '阮郎归', '俞紫芝', '钓鱼船上谢三郎。\n双鬓已苍苍。\n蓑衣未必清贵，不肯换金章。\n汀草畔，浦花旁。\n静鸣榔。\n自来好个，渔父家风，一片潇湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1064, '临江仙', '俞紫芝', '弄水亭前千万景，登临不忍空回。\n水轻墨澹写蓬莱。\n莫教世眼，容易洗尘埃。\n收去雨昏都不见，展时还似云开。\n先生高趣更多才。\n人人尽道，小杜却重来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1065, '苏幕遮', '俞紫芝', '地锺灵，天应瑞。\n簇簇香苞、团作真珠蕊。\n玉宇瑶台分十二。\n要伴娥，月里双双睡。\n月如花，花似月。\n花月生香，添此真奇异。\n不许扬州夸间气。\n昨夜春风，唤醒琼琼醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1066, '失调名', '郑獬', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1067, '好事近', '郑獬', '江上探春回，正值早梅时节。\n两行小槽双凤，按凉州初彻。\n谢娘扶下绣鞍来，红靴踏残雪。\n归去不须银烛，有山头明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1068, '好事近', '郑獬', '把酒对江梅，花小未禁风力。\n何计不教零落，为青春留得。\n故人莫问在天涯，尊前苦相忆。\n好把素香收取，寄江南消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1069, '渔家傲', '强至', '雪月照梅溪畔路。\n幽姿背立无言语。\n冷浸瘦枝清浅处。\n香暗度。\n妆成处士横斜句。\n浑似玉人常淡伫。\n菱花相对盈清楚。\n谁解小图先画取。\n天欲曙。\n恐随月色云间去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1070, '踏莎行', '沈注', '竹阁云深，巢虚人阒。\n几年湖上音尘寂。\n风流今有使君家，月明夜夜闻双笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1071, '望梅花', '蒲宗孟', '一阳初起。\n暖力未胜寒气。\n堪赏素华长独秀，不并开红抽紫。\n青帝只应怜洁白，不使雷同众卉。\n淡然难比。\n粉蝶岂知芳蕊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1072, '减字木兰花', '陈汝羲', '纤纤素手。\n盘里醉花新点就。\n对叶双心。\n别有东风意思深。\n琼沾粉缀。\n消得玉堂留客醉。\n试嗅清芳。\n别有红罗巧袖香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1073, '行香子', '汪辅之', '晚绿寒红。\n芳意匆匆。\n惜年华、今与谁同。\n碧云零落，数字宾鸿。\n看渚莲凋，宫扇旧，怨秋风。\n流波坠叶，佳期何在，想天教、离恨无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1074, '鹧鸪天', '范纯仁', '腊後春前暖律催。\n日和风软欲开梅。\n公方结客寻佳景，我亦忘形趁酒杯。\n添歌管，续尊。\n更阑烛短未能回。\n清欢莫待相期约，乘兴来时便可来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1075, '雨中花・夜行船', '张才翁', '万缕青青，初眠官柳，向人犹未成阴。\n据雕鞍马上，拥鼻微吟。\n远宦情怀谁问，空嗟壮志销沈。\n正好花时节，山城留滞、忍负归心。\n别离万里，飘蓬无定，谁念会合难凭。\n相聚里，休辞金盏，酒浅还深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1076, '渔家傲', '寿涯禅师', '深愿弘慈无缝罅。\n乘时走入众生界。\n窈窕丰姿都没赛。\n提鱼卖。\n堪笑马郎来纳败。\n清冷露湿金坏。\n茜裙不把珠缨盖。\n特地掀来呈捏怪。\n牵人爱。\n还尽许多菩萨债。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1077, '水龙吟', '章', '燕忙莺懒花残，正堤上、柳花飘坠。\n轻飞点画青林，谁道全无才思。\n闲趁游丝，静临深院，日长门闭。\n傍珠帘散漫，垂垂欲下，依前被，风扶起。\n兰帐玉人睡觉，怪春衣、雪粘琼缀。\n绣床旋满，香球无数，才圆却碎。\n时见蜂儿，仰粘轻粉，鱼吹池水。\n望章台路杳，金鞍游荡，有盈盈泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1078, '声声令・胜胜令', '章', '帘移碎影，香褪衣襟。\n旧家庭院嫩苔侵。\n东风过尽，暮云锁，绿窗深。\n怕对人、闲枕剩衾。\n楼底轻阴。\n春信断，怯登临。\n断肠魂梦两沈沈。\n花飞水远，便从今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1079, '渔父乐・渔歌子', '徐积', '水曲山隈四五家。\n夕阳烟火隔芦花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1080, '渔父乐・渔歌子', '徐积', '见说红尘罩九衢。\n贪名逐利各区区。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1081, '渔父乐・渔歌子', '徐积', '讨得渔竿买得船。\n归休何必待高年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1082, '渔父乐・渔歌子', '徐积', '饱则高歌醉即眠。\n只知头白不知年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1083, '渔父乐・渔歌子', '徐积', '管得江湖占得山。\n白云同散学云闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1084, '渔父乐・渔歌子', '徐积', '一酌村醪一曲歌。\n回看尘世足风波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1085, '开元乐・三台', '沈括', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1086, '开元乐・三台', '沈括', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1087, '开元乐・三台', '沈括', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1088, '开元乐・三台', '沈括', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1089, '失调名', '范宽之', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1090, '黄鹤引', '方资', '生逢垂拱。\n不识干戈免田陇。\n士林书圃终年，庸非天宠。\n才初茸。\n老去支离何用。\n浩然归弄。\n似黄鹤、秋风相送。\n尘事塞翁心，浮世庄生梦。\n漾舟遥指烟波，群山森动。\n神闲意耸。\n回首利名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1091, '点绛唇', '王安国', '秋气微凉，梦回明月穿帘幕。\n井梧萧索。\n正绕南枝鹊。\n宝瑟尘生，金雁空零落。\n情无托。\n鬓云慵掠。\n不似君恩薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1092, '清平乐', '王安国', '留春不住。\n费尽莺儿语。\n满地残红宫锦污。\n昨夜南园风雨。\n小怜初上琵琶。\n晓来思绕天涯。\n不肯画堂朱户，春风自在梨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1093, '减字木兰花', '王安国', '画桥流水。\n雨湿落红飞不起。\n月破黄昏。\n帘里馀香马上闻。\n徘徊不语。\n今夜梦魂何处去。\n不似垂杨。\n犹解飞花入洞房。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1094, '菩萨蛮', '孙洙', '楼头上有三冬鼓。\n何须抵死催人去。\n上马苦匆匆。\n琵琶曲未终。\n回头肠断处。\n却更廉纤雨。\n漫道玉为堂。\n玉堂今夜长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1095, '河满子', '孙洙', '怅望浮生急景，凄凉宝瑟馀音。\n楚客多情偏怨别，碧山远水登临。\n目送连天衰草，夜阑几处疏砧。\n黄叶无风自落，秋云不雨长阴。\n天若有情天亦老，摇摇幽恨难禁。\n惆怅旧欢如梦，觉来无处追寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1096, '失调名', '李清臣', '杨花落。\n燕子穿朱阁。\n苦恨春醪如水薄。\n闲愁无处著。\n去年今日王陵舍，鼓角秋风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1097, '减字木兰花', '韦骧', '人生可意。\n祗说功名贪富贵。\n遇景开怀。\n且尽生前有限杯。\n韶华几许。\n鹈声残无觅处。\n莫自因循。\n一片花飞减却春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1098, '减字木兰花', '韦骧', '金貂贳酒。\n乐事可为须趁手。\n且醉青春。\n白发何曾饶贵人。\n凤笙鼍鼓。\n况是桃花落红雨。\n莫诉觥筹。\n炊熟黄粱一梦休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1099, '减字木兰花', '韦骧', '鸾坡凤沼。\n轩冕傥来何足道。\n存养天真。\n安用浮名绊此身。\n劳生逸老。\n摆脱纷华须是早。\n解绶眠云。\n林下何曾见一人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1100, '减字木兰花', '韦骧', '危楼引望。\n天气犹寒花未放。\n远思悠悠。\n芳草何年恨即休。\n仙踪何处。\n此去蓬山多少路。\n春霭腾腾。\n更在瑶台十二层。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1101, '减字木兰花', '韦骧', '帝城春媚。\n绿柳参天花照地。\n共乐升平。\n处处楼台歌板声。\n香轮玉镫。\n驰骤芳郊争选胜。\n妙舞轻讴。\n扰乱春风卒未休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1102, '菩萨蛮', '韦骧', '琼杯且尽清歌送。\n人生离合真如梦。\n瞬息又春归。\n回头光景非。\n香喷金兽暖。\n欢意愁更短。\n白发不须量。\n从教千丈长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1103, '鹊桥仙', '韦骧', '岁华将暮，寒林萧索，极目冻云垂地。\n官梅忽见一枝芳，便顿觉、新春情味。\n小筵开处，歌喉清婉，舞态蹁跹争媚。\n沈腰潘鬓两休论，共举白、何须惜醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1104, '减字木兰花', '韦骧', '雕阑香砌。\n红紫妖韶何足计。\n争似幽芳。\n几朵先春蘸碧塘。\n玉盘金盏。\n谁谓花神情有限。\n绰约仙姿。\n仿佛江皋解佩时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1105, '洛阳春・一落萦', '韦骧', '冷艳幽香奇绝。\n粉金裁雪。\n无端又欲恨春风，恨不解、千千结。\n曲槛小池清切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1106, '醉蓬莱', '韦骧', '漏新春消耗，柳眼微青，素梅犹小。\n帘幕轻寒，引炉烟袅袅。\n凤管雍容，雁筝清切，对绮筵呈妙。\n此际欢虞，门庭自有，辉光荣耀。\n庆事难逢，世间须信，八十遐龄，古来稀少。\n况偶佳辰，是桑弧曾表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1107, '沁园春', '韦骧', '林叶阴浓，海云峰耸，夏景渐分。\n称画堂开宴，雍雍笑语，高年耆德，初弄君恩。\n汉相家声，一经传训，赏典今朝归庆门。\n清和昼，见香飘百和，乐按长春。\n休论。\n万事纷纭。\n算寿考、乡闾能几人。\n况凤书才降，龟龄正永，莫辞金盏，一醉醺醺。\n萱草忘忧，榴花含笑，庭院风光如再新。\n成欢颂，愿齐坚桧柏，频奉丝纶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1108, '渔家傲', '圆禅师', '本是潇湘一钓客。\n自东自西自南北。\n只把孤舟为屋宅。\n无宽窄。\n幕天席地人难测。\n顷闻四海停戈革。\n金门懒去投书册。\n时向滩头歌月白。\n真高格。\n浮名浮利谁拘得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1109, '满庭芳', '则禅师', '咄这牛儿，身强力健，几人能解牵骑。\n为贪原上，嫩草绿离离。\n只管寻芳逐翠，奔驰後、不顾倾危。\n争知道，山遥水远，回首到家迟。\n牧童，今有智，长绳牢把，短杖高提。\n入泥入水，终是不生疲。\n直待心调步稳，青松下、孤笛横吹。\n当归去，人牛不见，正是月明时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1110, '八声甘州', '陈偕', '芰荷风、涤面恰麦秋，应倒著春衣。\n渡晓溪云湿，日流尘脚，露蛛丝。\n调翼受风雏燕，弱不解争泥。\n衬琅锦院，竹外蔷薇。\n立久阑干凭暖，看行鱼吹沫，波晕平池。\n藓痕斑础石，渐雨熟梅时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1111, '满庭芳', '陈偕', '岚影浮春，云容阁雨，澄泓碧展玻璃。\n高低楼观，窗户舞涟漪。\n别有轻盈水面，清讴起、舟叶如飞。\n沙堤上，垂鞭信马，柳重绿交枝。\n渐残红倒影，金波潋滟，弦管催归。\n看飘香陈粉，满路扶携。\n不尽湖边风月，孤山下、猿鸟须知。\n东风里、年年此水，贮尽是和非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1112, '满庭芳', '陈偕', '榆荚抛钱，桃英胎子，杨花已送春归。\n未成萍叶，水面绿纹肥。\n沙暖溪禽行哺，忘机处、雏母相随。\n重帘静，铜壶昼歇，声度竹间棋。\n人生如意少，乐随春减，恨为情离。\n怕牵愁勾怨，渐近金徽。\n浮世更相代谢，江头明月，渡口斜晖。\n关情处，摩挲钓石，莫遣上苔衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1113, '临江仙', '晏几道', '斗草阶前初见，穿针楼上曾逢。\n罗裙香露玉钗风。\n靓妆眉沁绿，羞脸粉生红。\n流水便随春远，行云终与谁同。\n酒醒长恨锦屏空。\n相寻梦里路，飞雨落花中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1114, '临江仙', '晏几道', '身外闲愁空满，眼中欢事常稀。\n明年应赋送君诗。\n细从今夜数，相会几多时。\n浅酒欲邀谁劝，深情惟有君知。\n东溪春近好同归。\n柳垂江上影，梅谢雪中枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1115, '临江仙', '晏几道', '淡水三年欢意，危弦几夜离情。\n晓霜红叶舞归程。\n客情今古道，秋梦短长亭。\n渌酒尊前清泪，阳关叠里离声。\n少陵诗思旧才名。\n云鸿相约处，烟雾九重城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1116, '临江仙', '晏几道', '浅浅馀寒春半，雪消蕙草初长。\n烟迷柳岸旧池塘。\n风吹梅蕊闹，雨细杏花香。\n月堕枝头欢意，从前虚梦高唐，觉来何处放思量。\n如今不是梦，真个到伊行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1117, '临江仙', '晏几道', '长爱碧阑干影，芙蓉秋水开时。\n脸红凝露学娇啼。\n霞觞熏冷艳，云髻袅纤枝。\n烟雨依前时候，霜丛如旧芳菲。\n与谁同醉采香归。\n去年花下客，今似蝶分飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1118, '临江仙', '晏几道', '旖旎仙花解语，轻盈春柳能眠。\n玉楼深处绮窗前。\n梦回芳草夜，歌罢落梅天。\n沈水浓熏绣被，流霞浅酌金船。\n绿娇红小正堪怜。\n莫如云易散，须似月频圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1119, '临江仙', '晏几道', '梦後楼台高锁，酒醒帘幕低垂。\n去年春恨却来时。\n落花人独立，微雨燕双飞。\n记得小苹初见，两重心字罗衣。\n琵琶弦上说相思。\n当时明月在，曾照彩云归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1120, '临江仙', '晏几道', '东野亡来无丽句，于君去後少交亲。\n追思往事好沾巾。\n白头王建在，犹见咏诗人。\n学道深山空自老，留名千载不干身。\n酒筵歌席莫辞频。\n争如南陌上，占取一年春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1121, '蝶恋花', '晏几道', '卷絮风头寒欲尽。\n坠粉飘红，日日香成阵。\n新酒又添残酒困。\n今春不减前春恨。\n蝶去莺飞无处问。\n隔水高楼，望断双鱼信。\n恼乱层波横一寸。\n斜阳只与黄昏近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1122, '蝶恋花', '晏几道', '初拈霜纨生怅望。\n隔叶莺声，似学秦娥唱。\n午睡醒来慵一饷。\n双纹翠簟铺寒浪。\n雨罢苹风吹碧涨。\n脉脉荷花，泪脸红相向。\n斜贴绿云新月上。\n弯环正是愁眉样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1123, '蝶恋花', '晏几道', '庭院碧苔红叶遍。\n金菊开时，已近重阳宴。\n日日露荷凋绿扇。\n粉塘烟水澄如练。\n试倚凉风醒酒面。\n雁字来时，恰向层楼见。\n几点护霜云影转。\n谁家芦管吹秋怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1124, '蝶恋花', '晏几道', '喜鹊桥成催凤驾。\n天为欢迟，乞与初凉夜。\n乞巧双蛾加意画。\n玉钩斜傍西南挂。\n分钿擘钗凉叶下。\n香袖凭肩，谁记当时话。\n路隔银河犹可借。\n世间离恨何年罢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1125, '蝶恋花', '晏几道', '碧草池塘春又晚。\n小叶风娇，尚学娥妆浅。\n双燕来时还念远。\n珠帘绣户杨花满。\n绿柱频移弦易断。\n细看秦筝，正似人情短。\n一曲啼乌心绪乱。\n红颜暗与流年换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1126, '蝶恋花', '晏几道', '碾玉钗头双凤小。\n倒晕工夫，画得宫眉巧。\n嫩曲罗裙胜碧草。\n鸳鸯绣字春衫好。\n三月露桃芳意早。\n细看花枝，人面争多少。\n水调声长歌未了。\n掌中杯尽东池晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1127, '蝶恋花', '晏几道', '醉别西楼醒不记。\n春梦秋云，聚散真容易。\n斜月半窗还少睡。\n画屏闲展吴山翠。\n衣上酒痕诗里字。\n点点行行，总是凄凉意。\n红烛自怜无好计。\n夜寒空替人垂泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1128, '蝶恋花', '晏几道', '欲减罗衣寒未去。\n不卷珠帘，人在深深处。\n残杏枝头花几许。\n啼红正恨清明雨。\n尽日沈香烟一缕。\n宿酒醒迟，恼破春情绪。\n远信还因归燕误。\n小屏风上西江路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1129, '蝶恋花', '晏几道', '千叶早梅夸百媚。\n笑面凌寒，内样妆先试。\n月脸冰肌香细腻。\n风流新称东君意。\n一捻年光春有味。\n江北江南，更有谁相比。\n横玉声中吹满地。\n好枝长恨无人寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1130, '蝶恋花', '晏几道', '金翦刀头芳意动。\n彩蕊开时，不怕朝寒重。\n晴雪半消花。\n晓妆呵尽香酥冻。\n十二楼中双翠凤。\n缥缈歌声，记得江南弄。\n醉舞春风谁可共。\n秦云已有鸳屏梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1131, '蝶恋花', '晏几道', '笑艳秋莲生绿浦。\n红脸青腰，旧识凌波女。\n照影弄妆娇欲语。\n西风岂是繁华主。\n可恨良辰天不与。\n才过斜阳，又是黄昏雨。\n朝落暮开空自许。\n竟无人解知心苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1132, '蝶恋花', '晏几道', '碧落秋风吹玉树。\n翠节红旌，晚过银河路。\n休笑星机停弄杼。\n凤帏已在云深处。\n楼上金针穿绣缕。\n谁管天边，隔岁分飞苦。\n试等夜阑寻别绪。\n泪痕千点罗衣露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1133, '蝶恋花', '晏几道', '碧玉高楼临水住。\n红杏开时，花底曾相遇。\n一曲阳春春已暮。\n晓莺声断朝云去。\n远水来从楼下路。\n过尽流波，未得鱼中素。\n月细风尖垂柳渡。\n梦魂长在分襟处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1134, '蝶恋花', '晏几道', '梦入江南烟水路。\n行尽江南，不与离人遇。\n睡里消魂无说处。\n觉来惆怅消魂误。\n欲尽此情书尺素。\n浮雁沈鱼，终了无凭据。\n却倚缓弦歌别绪。\n断肠移破秦筝柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1135, '蝶恋花', '晏几道', '黄菊开时伤聚散。\n曾记花前，共说深深愿。\n重见金英人未见。\n相思一夜天涯远。\n罗带同心闲结遍。\n带易成双，人恨成双晚。\n欲写彩笺书别怨。\n泪痕早已先书满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1136, '鹧鸪天', '晏几道', '彩袖殷勤捧玉锺。\n当年拼却醉颜红。\n舞低杨柳楼心月，歌尽桃花扇影风。\n从别後，忆相逢。\n几回魂梦与君同。\n今宵剩把银照，犹恐相逢是梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1137, '鹧鸪天', '晏几道', '一醉醒来春又残。\n野棠梨雨泪阑干。\n玉笙声里鸾空怨。\n罗幕香中燕未还。\n终易散，且长闲。\n莫教离恨损朱颜。\n谁堪共展鸳鸯锦，同过西楼此夜寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1138, '鹧鸪天', '晏几道', '梅蕊新妆桂叶眉。\n小莲风韵出瑶池。\n云随绿水歌声转，雪绕红绡舞袖垂。\n伤别易，恨欢迟。\n惜无红锦为裁诗。\n行人莫便消魂去，汉渚星桥尚有期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1139, '鹧鸪天', '晏几道', '守得莲开结伴游。\n约开萍叶上兰舟。\n来时浦口云随棹，采罢江边月满楼。\n花不语，水空流。\n年年拼得为花愁。\n明朝万一西风动，争向朱颜不耐秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1140, '鹧鸪天', '晏几道', '斗鸭池南夜不归。\n酒阑纨扇有新诗。\n云随碧玉歌声转，雪绕红琼舞袖回。\n今感旧，欲沾衣。\n可怜人似水东西。\n回头满眼凄凉事，秋月春风岂得知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1141, '鹧鸪天', '晏几道', '当日佳期鹊误传。\n至今犹作断肠仙。\n桥成汉渚星波外，人在鸾歌凤舞前。\n欢尽夜，别经年。\n别多欢少奈何天。\n情知此会无长计。\n咫尺凉蟾亦未圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1142, '鹧鸪天', '晏几道', '题破香笺小砑红。\n诗篇多寄旧相逢。\n西楼酒面垂垂雪，南苑春衫细细风。\n花不尽，柳无穷。\n别来欢事少人同。\n凭谁问取归云信，今在巫山第几峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1143, '鹧鸪天', '晏几道', '清颍尊前酒满衣。\n十年风月旧相知。\n凭谁细话当时事，肠断山长水远诗。\n金凤阙，玉龙墀。\n看君来换锦袍时。\n娥已有殷勤约，留著蟾宫第一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1144, '鹧鸪天', '晏几道', '醉拍春衫惜旧香。\n天将离恨恼疏狂。\n年年陌上生秋草，日日楼中到夕阳。\n云渺渺，水茫茫。\n征人归路许多长。\n相思本是无凭语，莫向花笺费泪行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1145, '鹧鸪天', '晏几道', '小令尊前见玉箫。\n银灯一曲太妖娆。\n歌中醉倒谁能恨，唱罢归来酒未消。\n春悄悄，夜迢迢。\n碧云天共楚宫遥。\n梦魂惯得无拘检，又踏杨花过谢桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1146, '鹧鸪天', '晏几道', '楚女腰肢越女腮。\n粉圆双蕊髻中开。\n朱弦曲怨愁春尽，渌酒杯寒记夜来。\n新掷果，旧分钗。\n冶游音信隔章台。\n花间锦字空频寄，月底金鞍竟未回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1147, '鹧鸪天', '晏几道', '十里楼台倚翠微。\n百花深处杜娟啼。\n殷勤自与行人语，不似流莺取次飞。\n惊梦觉，弄晴时。\n声声只道不如归。\n天涯岂是无归意，争奈归期未可期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1148, '鹧鸪天', '晏几道', '陌上残絮飞。\n杜娟花里杜娟啼。\n年年底事不归去，怨月愁烟长为谁。\n梅雨细，晓风微。\n倚楼人听欲沾衣。\n故园三度群花谢，曼倩天涯犹未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1149, '鹧鸪天', '晏几道', '晓日迎长岁岁同。\n太平箫鼓间歌钟。\n云高未有前村雪，梅小初开昨夜风。\n罗幕翠，锦筵红。\n钗头罗胜写宜冬。\n从今屈指春期近，莫使金尊对月空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1150, '鹧鸪天', '晏几道', '小玉楼中月上时。\n夜来惟许月华知。\n重帘有意藏私语，双烛无端恼暗期。\n伤别易，恨欢迟。\n归来何处验相思。\n沈郎春雪愁消臂，谢女香膏懒画眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1151, '鹧鸪天', '晏几道', '手拈香笺忆小莲。\n欲将遗恨倩谁传。\n归来独卧逍遥夜，梦里相逢酩酊天。\n花易落，月难圆。\n只应花月似欢缘。\n秦筝算有心情在，试写离声入旧弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1152, '鹧鸪天', '晏几道', '九日悲秋不到心。\n凤城歌管有新音。\n风凋碧柳愁眉淡，露染黄花笑靥深。\n初见雁，已闻砧。\n绮罗丛里胜登临。\n须教月户纤纤玉，细捧霞觞滟滟金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1153, '鹧鸪天', '晏几道', '碧藕花开水殿凉。\n万年枝外转红阳。\n升平歌管随天仗，祥瑞封章满御床。\n金掌露，玉炉香。\n岁华方共圣恩长。\n皇州又奏圜扉静，十样宫眉捧寿觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1154, '鹧鸪天', '晏几道', '绿橘梢头几点春。\n似留香蕊送行人。\n明朝紫凤朝天路，十二重城五碧云。\n歌渐咽，酒初醺。\n尽将红泪湿湘裙。\n赣江西畔从今日，明月清风忆使君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1155, '生查子', '晏几道', '金鞭美少年，去跃青骢马。\n牵系玉楼人，绣被春寒夜。\n消息未归来，寒食梨花谢。\n无处说相思，背面秋千下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1156, '生查子', '晏几道', '轻匀两脸花，淡扫双眉柳。\n会写锦笺时，学弄朱弦後。\n今春玉钏宽，昨夜罗裙皱。\n无计奈情何，且醉金杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1157, '生查子', '晏几道', '关山魂梦长，鱼雁音尘少。\n两鬓可怜青，只为相思老。\n归梦碧纱窗，说与人人道。\n真个别离难，不似相逢好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1158, '生查子', '晏几道', '坠雨已辞云，流水难归浦。\n遗恨几时休，心抵秋莲苦。\n忍泪不能歌，试托哀弦语。\n弦语愿相逢，知有相逢否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1159, '生查子', '晏几道', '一分残酒霞，两点愁蛾晕。\n罗幕夜犹寒，玉枕春先困。\n心情翦彩慵，时节烧灯近。\n见少别离多，还有人堪恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1160, '生查子', '晏几道', '轻轻制舞衣，小小裁歌扇。\n三月柳浓时，又向津亭见。\n垂泪送行人，湿破红妆面。\n玉指袖中弹，一曲清商怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1161, '生查子', '晏几道', '红尘陌上游，碧柳堤边住。\n才趁彩云来，又逐飞花去。\n深深美酒家，曲曲幽香路。\n风月有情时，总是相思处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1162, '生查子', '晏几道', '长恨涉江遥，移近溪头住。\n闲荡木兰舟，误入双鸳浦。\n无端轻薄云，暗作廉纤雨。\n翠袖不胜寒，欲向荷花语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1163, '生查子', '晏几道', '远山眉黛长，细柳腰肢袅。\n妆罢立春风，一笑千金少。\n归去凤城时，说与青楼道。\n遍看颍川花，不似师师好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1164, '生查子', '晏几道', '落梅庭榭香，芳草池塘绿。\n春恨最关情，日过阑干曲。\n几时花里闲，看得花枝足。\n醉後莫思家，借取师师宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1165, '生查子', '晏几道', '狂花顷刻香，晚蝶缠绵意。\n天与短因缘，聚散常容易。\n传唱入离声，恼乱双蛾翠。\n游子不堪闻，正是衷肠事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1166, '生查子', '晏几道', '官身几日闲，世事何时足。\n君貌不长红，我鬓无重绿。\n榴花满盏香，金缕多情曲。\n且尽眼中欢，莫叹时光促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1167, '生查子', '晏几道', '春从何处归，试向溪边问。\n岸柳弄娇黄，陇麦回青润。\n多情美少年，屈指芳菲近。\n谁寄岭头梅，来报江南信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1168, '南乡子', '晏几道', '渌水带青潮。\n水上朱阑小渡桥。\n桥上女儿双笑靥，妖娆。\n倚著阑干弄柳条。\n月夜落花朝。\n减字偷声按玉箫。\n柳外行人回首处，迢迢。\n若比银河路更遥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1169, '南乡子', '晏几道', '小蕊受春风。\n日日宫花花树中。\n恰向柳绵撩乱处，相逢。\n笑靥旁边心字浓。\n归路草茸茸。\n家在秦楼更近东。\n醒去醉来无限事，谁同。\n说著西池满面红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1170, '南乡子', '晏几道', '花落未须悲。\n红蕊明年又满枝。\n惟有花间人别後，无期。\n水阔山长雁字迟。\n今日最相思。\n记得攀条话别离。\n共说春来春去事，多时。\n一点愁心入翠眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1171, '南乡子', '晏几道', '何处别时难。\n玉指偷将粉泪弹。\n记得来时楼上烛，初残。\n待得清霜满画阑。\n不惯独眠寒。\n自解罗衣衬枕檀。\n百媚也应愁不睡，更阑。\n恼乱心情半被闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1172, '南乡子', '晏几道', '画鸭懒熏香。\n绣茵犹展旧鸳鸯。\n不似同衾愁易晓，空床。\n细剔银灯怨漏长。\n几夜月波凉。\n梦魂随月到兰房。\n残睡觉来人又远，难忘。\n便是无情也断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1173, '南乡子', '晏几道', '眼约也应虚。\n昨夜归来凤枕孤。\n且据如今情分里，相於。\n只恐多时不似初。\n深意托双鱼。\n小翦蛮笺细字书。\n更把此情重问得，何如。\n共结因缘久远无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1174, '南乡子', '晏几道', '新月又如眉。\n长笛谁教月下吹。\n楼倚暮云初见雁，南飞。\n漫道行人雁後归。\n意欲梦佳期。\n梦里关山路不知。\n却待短书来破恨，应迟。\n还是凉生玉枕时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1175, '清平乐', '晏几道', '留人不住。\n醉解兰舟去。\n一棹碧涛春水路。\n过尽晓莺啼处。\n渡头杨柳青青。\n枝枝叶叶离情。\n此後锦书休寄，画楼云雨无凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1176, '清平乐', '晏几道', '千花百草。\n送得春归了。\n拾蕊人稀红渐少。\n叶底杏青梅小。\n小琼闲抱琵琶。\n雪香微透轻纱。\n正好一枝娇艳，当筵独占韶华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1177, '清平乐', '晏几道', '烟轻雨小。\n紫陌香尘少。\n谢客池塘生绿草。\n一夜红梅先老。\n旋题罗带新诗。\n重寻杨柳佳期。\n强半春寒去後，几番花信来时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1178, '清平乐', '晏几道', '可怜娇小。\n掌上承恩早。\n把镜不知人易老。\n欲占朱颜长好。\n画堂秋月佳期。\n藏钩赌酒归迟。\n红烛泪前低语，绿笺花里新词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1179, '清平乐', '晏几道', '红英落尽。\n未有相逢信。\n可恨流年凋绿鬓。\n睡得春酲欲醒。\n钿筝曾醉西楼。\n朱弦玉指梁州。\n曲罢翠帘高卷，几回新月如钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1180, '清平乐', '晏几道', '春云绿处。\n又见归鸿去。\n侧帽风前花满路。\n冶叶倡条情绪。\n红楼桂酒新开。\n曾携翠袖同来。\n醉弄影娥池水，短箫吹落残梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1181, '清平乐', '晏几道', '波纹碧皱。\n曲水清明後。\n折得疏梅香满袖。\n暗喜春红依旧。\n归来紫陌东头。\n金钗换酒消愁。\n柳影深深细路，花梢小小层楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1182, '清平乐', '晏几道', '西池烟草。\n恨不寻芳早。\n满路落花红不扫。\n春色渐随人老。\n远山眉黛娇长。\n清歌细逐霞觞。\n正在十洲残梦，水心宫殿斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1183, '清平乐', '晏几道', '蕙心堪怨。\n也逐春风转。\n丹杏墙东当日见。\n幽会绿窗题遍。\n眼中前事分明。\n可怜如梦难凭。\n都把旧时薄，只消今日无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1184, '清平乐', '晏几道', '幺弦写意。\n意密弦声碎。\n书得凤笺无限事。\n犹恨春心难寄。\n卧听疏雨梧桐。\n雨馀淡月朦胧。\n一夜梦魂何处，那回杨叶楼中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1185, '清平乐', '晏几道', '笙歌宛转。\n台上吴王宴。\n宫女如花倚春殿。\n舞绽缕金衣线。\n酒阑画烛低迷。\n彩鸳惊起双栖。\n月底三千绣户，云间十二琼梯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1186, '清平乐', '晏几道', '暂来还去。\n轻似风头絮。\n纵得相逢留不住。\n何况相逢无处。\n去时约略黄昏。\n月华却到朱门。\n别後几番明月，素娥应是消魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1187, '清平乐', '晏几道', '双纹彩袖。\n笑捧金船酒。\n娇妙如花轻似柳。\n劝客千春长寿。\n艳歌更倚疏弦。\n有情须醉尊前。\n恰是可怜时候，玉娇今夜初圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1188, '清平乐', '晏几道', '寒催酒醒。\n晓陌飞霜定。\n背照画帘残烛影。\n斜月光中人静。\n锦衣才子西征。\n万重云水初程。\n翠黛倚门相送，鸾肠断处离声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1189, '清平乐', '晏几道', '莲开欲遍。\n一夜秋声转。\n残绿断红香片片。\n长是西风堪怨。\n莫愁家住溪边。\n采莲心事年年。\n谁管水流花谢，月明昨夜兰船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1190, '清平乐', '晏几道', '沈思暗记。\n几许无凭事。\n菊靥开残秋少味。\n闲却画阑风意。\n梦云归处难寻。\n微凉暗入香襟。\n犹恨那回庭院，依前月浅灯深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1191, '清平乐', '晏几道', '莺来燕去。\n宋玉墙东路。\n草草幽欢能几度。\n便有系人心处。\n碧天秋月无端。\n别来长照关山。\n一点恹恹谁会，依前凭暖阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1192, '清平乐', '晏几道', '心期休问。\n只有尊前分。\n勾引行人添别恨。\n因是语低香近。\n劝人满酌金锺。\n清歌唱彻还重。\n莫道後期无定，梦魂犹有相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1193, '木兰花・玉楼春', '晏几道', '秋千院落重帘暮。\n彩笔闲来题绣户。\n墙头丹杏雨馀花，门外绿杨风後絮。\n朝云信断知何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1194, '木兰花・玉楼春', '晏几道', '小颦若解愁春暮。\n一笑留春春也住。\n晚红初减谢池花，新翠已遮琼苑路。\n湔裙曲水曾相遇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1195, '木兰花・玉楼春', '晏几道', '小莲未解论心素。\n狂似钿筝弦底柱。\n脸边霞散酒初醒，眉上月残人欲去。\n旧时家近章台住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1196, '木兰花・玉楼春', '晏几道', '风帘向晓寒成阵。\n来报东风消息近。\n试从梅蒂紫边寻，更绕柳枝柔处问。\n来迟不是春无信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1197, '木兰花・玉楼春', '晏几道', '念奴初唱离亭宴。\n会作离声勾别怨。\n当时垂泪忆西楼，湿尽罗衣歌未遍。\n难逢最是身强健。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1198, '木兰花・玉楼春', '晏几道', '玉真能唱朱帘静。\n忆在双莲池上听。\n百分蕉叶醉如泥，却向断肠声里醒。\n夜凉水月铺明镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1199, '木兰花・玉楼春', '晏几道', '阿茸十五腰肢好。\n天与怀春风味早。\n画眉匀脸不知愁，酒熏香偏称小。\n东城杨柳西城草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1200, '木兰花・玉楼春', '晏几道', '初心已恨花期晚。\n别後相思长在眼。\n兰衾犹有旧时香，每到梦回珠泪满。\n多应不信人肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1201, '减字木兰花', '晏几道', '长亭晚送。\n都似绿窗前日梦。\n小字还家。\n恰应红灯昨夜花。\n良时易过。\n半镜流年春欲破。\n往事难忘。\n一枕高楼到夕阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1202, '减字木兰花', '晏几道', '留春不住。\n恰似年光无味处。\n满眼飞英。\n弹指东风太浅情。\n筝弦未稳。\n学得新声难破恨。\n转枕花前。\n且占香红一夜眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1203, '减字木兰花', '晏几道', '长杨辇路。\n绿满当年携手处。\n试逐春风。\n重到宫花花树中。\n芳菲绕遍。\n今日不如前日健。\n酒罢凄凉。\n新恨犹添旧恨长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1204, '泛清波摘遍', '晏几道', '催花雨小，著柳风柔，都似去年时候好。\n露红烟绿，尽有狂情斗春早。\n长安道。\n秋千影里，丝管声中，谁放艳阳轻过了。\n倦客登临，暗惜光阴恨多少。\n楚天渺。\n归思正如乱云，短梦未成芳草。\n空把吴霜鬓华，自悲清晓。\n帝城杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1205, '洞仙歌', '晏几道', '春残雨过，绿暗东池道。\n玉艳藏羞媚笑。\n记当时、已恨飞镜欢疏，那至此，仍苦题花信少。\n连环情未己，物是人非，月下疏梅似伊好。\n澹秀色，黯寒香，粲若春容，何心顾、闲花凡草。\n但莫使、情随岁华迁，便杳隔秦源，也须能到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1206, '菩萨蛮', '晏几道', '来时杨柳东桥路。\n曲中暗有相期处。\n明月好因缘。\n欲圆还未圆。\n欲寻芳草去。\n画扇遮微雨。\n飞絮莫无情。\n闲花应笑人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1207, '菩萨蛮', '晏几道', '个人轻似低飞燕。\n春来绮陌时相见。\n堪恨两横波。\n恼人情绪多。\n长留青鬓住。\n莫放红颜去。\n占取艳阳天。\n且教伊少年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1208, '菩萨蛮', '晏几道', '鸾啼似作留春语。\n花飞斗学回风舞。\n红日又平西。\n画帘遮燕泥。\n烟光还自老。\n绿镜人空好。\n香在去年衣。\n鱼笺音信稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1209, '菩萨蛮', '晏几道', '春风未放花心吐。\n尊前不拟分明语。\n酒色上来迟。\n绿须红杏枝。\n今朝眉黛浅。\n暗恨归时远。\n前夜月当楼。\n相逢南陌头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1210, '菩萨蛮', '晏几道', '娇香淡染胭脂雪。\n愁春细画弯弯月。\n花月镜边情。\n浅妆匀未成。\n佳期应有在。\n试倚秋千待。\n满地落英红。\n万条杨柳风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1211, '菩萨蛮', '晏几道', '香莲烛下匀丹雪。\n妆成笑弄金阶月。\n娇面胜芙蓉。\n脸边天与红。\n玳筵双揭鼓。\n唤上华茵舞。\n春浅未禁寒。\n暗嫌罗袖宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1212, '菩萨蛮', '晏几道', '哀筝一弄湘江曲。\n声声写尽湘波绿。\n纤指十三弦。\n细将幽恨传。\n当筵秋水慢。\n玉柱斜飞雁。\n弹到断肠时。\n春山眉黛低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1213, '菩萨蛮', '晏几道', '江南未雪梅花白。\n忆梅人是江南客。\n犹记旧相逢。\n淡烟微月中。\n玉容长有信。\n一笑归来近。\n怀远上楼时。\n晚云和雁低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1214, '菩萨蛮', '晏几道', '相逢欲话相思苦。\n浅情肯信相思否。\n还恐漫相思。\n浅情人不知。\n忆曾携手处。\n月满窗前路。\n长到月来时。\n不眠犹待伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1215, '玉楼春', '晏几道', '雕鞍好为莺花住。\n占取东城南陌路。\n尽教春思乱如云，莫管世情轻似絮。\n古来多被虚名误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1216, '玉楼春', '晏几道', '一尊相遇春风里。\n诗好似君人有几。\n吴姬十五语如弦，能唱当时楼下水。\n良辰易去如弹指。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1217, '玉楼春', '晏几道', '琼酥酒面风吹醒。\n一缕斜红临晚镜。\n小颦微笑尽妖娆，浅注轻匀长淡净。\n手挪梅蕊寻香径。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1218, '玉楼春', '晏几道', '清歌学得秦娥似。\n金屋瑶台知姓字。\n可怜春恨一生心，长带粉痕双袖泪。\n从来懒话低眉事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1219, '玉楼春', '晏几道', '旗亭西畔朝云住。\n沈水香烟长满路。\n柳阴分到画眉边，花片飞来垂手处。\n妆成尽任秋娘妒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1220, '玉楼春', '晏几道', '离鸾照罢尘生镜。\n几点吴霜侵绿鬓。\n琵琶弦上语无凭，豆蔻梢头春有信。\n相思拼损朱颜尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1221, '玉楼春', '晏几道', '东风又作无情计。\n艳粉娇红吹满地。\n碧楼帘影不遮愁，还似去年今日意。\n谁知错管春残事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1222, '玉楼春', '晏几道', '斑骓路与阳台近。\n前度无题初借问。\n暖风鞭袖尽闲垂，微月帘栊曾暗认。\n梅花未足凭芳信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1223, '玉楼春', '晏几道', '红绡学舞腰肢软。\n旋织舞衣宫样染。\n织成云外雁行斜，染作江南春水浅。\n露桃宫里随歌管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1224, '玉楼春', '晏几道', '当年信道情无价。\n桃叶尊前论别夜。\n脸红心绪学梅妆，眉翠工夫如月画。\n来时醉倒旗亭下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1225, '玉楼春', '晏几道', '采莲时候慵歌舞。\n永日闲从花里度。\n暗随苹末晓风来，直待柳梢斜月去。\n停桡共说江头路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1226, '玉楼春', '晏几道', '芳年正是香英嫩。\n天与娇波长入鬓。\n蕊珠宫里旧承恩，夜拂银屏朝把镜。\n云情去住终难信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1227, '玉楼春', '晏几道', '轻风拂柳冰初绽。\n细雨消尘云未散。\n红窗青镜待妆梅，绿陌高楼催送雁。\n华罗歌扇金蕉盏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1228, '阮郎归', '晏几道', '粉痕闲印玉尖纤。\n啼红傍晚奁。\n旧寒新暖尚相兼。\n梅疏待雪添。\n春冉冉，恨恹恹。\n章台对卷帘。\n个人鞭影弄凉蟾。\n楼前侧帽檐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1229, '阮郎归', '晏几道', '来时红日弄窗纱。\n春红入睡霞。\n去时庭树欲栖鸦。\n香屏掩月斜。\n收翠羽，整妆华。\n青骊信又差。\n玉笙犹恋碧桃花。\n今宵未忆家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1230, '阮郎归', '晏几道', '旧香残粉似当初。\n人情恨不如。\n一春犹有数行书。\n秋来书更疏。\n衾凤冷，枕鸳孤。\n愁肠待酒舒。\n梦魂纵有也成虚。\n那堪和梦无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1231, '阮郎归', '晏几道', '天边金掌露成霜。\n云随雁字长。\n绿杯红袖称重阳。\n人情似故乡。\n兰佩紫，菊簪黄。\n殷勤理旧狂。\n欲将沈醉换悲凉。\n清歌莫断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1232, '阮郎归', '晏几道', '晚妆长趁景阳钟。\n双蛾著意浓。\n舞腰浮动绿云浓。\n樱桃半点红。\n怜美景，惜芳容。\n沈思暗记中。\n春寒帘幕几重重。\n杨花尽日风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1233, '归田乐', '晏几道', '试把花期数。\n便早有、感春情绪。\n看即梅花吐。\n愿花更不谢，春且长住。\n只恐花飞又春去。\n花开还不语。\n问此意、年年春还会否。\n绛唇青鬓，渐少花前语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1234, '浣溪沙', '晏几道', '二月春花厌落梅。ピ\n仙源归路碧桃催。ピ\n渭城丝雨劝离杯。ピ\n欢意似云真薄，客鞭摇柳正多才。ピ\n凤楼人待锦书来。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1235, '浣溪沙', '晏几道', '卧鸭池头小苑开。\n暄风吹尽北枝梅。\n柳长莎软路萦回。\n静避绿阴莺有意，漫随游骑絮多才。\n去年今日忆同来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1236, '浣溪沙', '晏几道', '二月和风到碧城。\n万条千缕绿相迎。\n舞烟眠雨过清明。\n妆镜巧眉偷叶样，歌楼妍曲借枝名。\n晚秋霜霰莫无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1237, '浣溪沙', '晏几道', '白春衫杨柳鞭。\n碧蹄骄马杏花鞯。\n落英飞絮冶游天。\n南陌暖风吹舞榭，东城凉月照歌筵。\n赏心多是酒中仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1238, '浣溪沙', '晏几道', '床上银屏几点山。\n鸭炉香过琐窗寒。\n小云双枕恨春闲。\n惜别漫成良夜醉，解愁时有翠笺还。\n那回分袂月初残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1239, '浣溪沙', '晏几道', '绿柳藏乌静掩关。\n鸭炉香细琐窗闲。\n那回分袂月初残。\n惜别漫成良夜醉，解愁时有翠笺还。\n欲寻双叶寄情难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1240, '浣溪沙', '晏几道', '家近旗亭酒易酤。\n花时长得醉工夫。\n伴人歌笑懒妆梳。\n户外绿杨春系马，床前红烛夜呼卢。\n相逢还解有情无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1241, '浣溪沙', '晏几道', '日日双眉斗画长。\n行云飞絮共轻狂。\n不将心嫁冶游郎。\n溅酒滴残歌扇字，弄花熏得舞衣香。\n一春弹泪说凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1242, '浣溪沙', '晏几道', '飞鹊台前晕翠蛾。\n千金新换绛仙螺。\n最难加意为颦多。\n几处睡痕留醉袖，一春愁思近横波。\n远山低尽不成歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1243, '浣溪沙', '晏几道', '午醉西桥夕未醒。\n雨花凄断不堪听。\n归时应减鬓边青。\n衣化客尘今古道，柳含春意短长亭。\n凤楼争见路旁情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1244, '浣溪沙', '晏几道', '一样宫妆簇彩舟。\n碧罗团扇自障羞。\n水仙人在镜中游。\n腰自细来多态度，脸因红处转风流。\n年年相遇绿江头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1245, '浣溪沙', '晏几道', '已拆秋千不奈闲。\n却随胡蝶到花间。\n旋寻双叶插云鬟。\n几摺湘裙烟缕细，一钩罗袜素蟾弯。\n绿窗红豆忆前欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1246, '浣溪沙', '晏几道', '闲弄筝弦懒系裙。\n铅华消尽见天真。\n眼波低处事还新。\n怅恨不逢如意酒，寻思难值有情人。\n可怜虚度琐窗春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1247, '浣溪沙', '晏几道', '团扇初随碧簟收。\n画檐归燕尚迟留。\n靥朱眉翠喜清秋。\n风意未应迷狭路，灯痕犹自记高楼。\n露花烟叶与人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1248, '浣溪沙', '晏几道', '翠阁朱阑倚处危。\n夜凉闲捻彩箫吹。\n曲中双凤已分飞。\n绿酒细倾消别恨，红笺小写问归期。\n月华风意似当时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1249, '浣溪沙', '晏几道', '唱得红梅字字香。\n柳枝桃叶尽深藏。\n遏云声里送雕觞。\n才听便拼衣袖湿，欲歌先倚黛眉长。\n曲终敲损燕钗梁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1250, '浣溪沙', '晏几道', '小杏春声学浪仙。\n疏梅清唱替哀弦。\n似花如雪绕琼筵。\n腮粉月痕妆罢後，脸红莲艳酒醒前。\n今年水调得人怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1251, '浣溪沙', '晏几道', '铜虎分符领外台。\n五云深处彩旌来。\n春随红旆过长淮。\n千里裤襦添旧暖，万家桃李间新栽。\n使星回首是三台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1252, '浣溪沙', '晏几道', '浦口莲香夜不收。\n水边风里欲生秋。\n棹歌声细不惊鸥。\n凉月送归思往事，落英飘去起新愁。\n可堪题叶寄东楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1253, '浣溪沙', '晏几道', '莫问逢春能几回。\n能歌能笑是多才。\n露花犹有好枝开。\n绿鬓旧人皆老大，红梁新燕又归来。\n尽须珍重掌中杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1254, '浣溪沙', '晏几道', '楼上灯深欲闭门。\n梦云归去不留痕。\n几年芳草忆王孙。\n向日阑干依旧绿，试将前事倚黄昏。\n记曾来处易消魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1255, '六么令', '晏几道', '绿阴春尽，飞絮绕香阁。\n晚来翠眉宫样，巧把远山学。\n一寸狂心未说，已向横波觉。\n画帘遮币。\n新翻曲妙，暗许闲人带偷掏。\n前度书多隐语，意浅愁难答。\n昨夜诗有回纹，韵险还慵押。\n都待笙歌散了，记取留时霎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1256, '六么令', '晏几道', '雪残风信，悠扬春消息。\n天涯倚楼新恨，杨柳几丝碧。\n还是南云雁少，锦字无端的。\n宝钗瑶席。\n彩弦声里，拼作尊前未归客。\n遥想疏梅此际，月底香英白。\n别後谁绕前溪，手拣繁枝摘。\n莫道伤高恨远，付与临风笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1257, '六么令', '晏几道', '日高春睡，唤起懒装束。\n年年落花时候，惯得娇眠足。\n学唱宫梅便好，更暖银笙逐。\n黛蛾低绿。\n堪教人恨，却似江南旧时曲。\n常记东楼夜雪，翠幕遮红烛。\n还是芳酒杯中，一醉光阴促。\n曾笑阳台梦短，无计怜香玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1258, '更漏子', '晏几道', '槛花稀，池草遍。\n冷落吹笙庭院。\n人去日，燕西飞。\n燕归人未归。\n数书期，寻梦意。\n弹指一年春事。\n新怅望，旧悲凉。\n不堪红日长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1259, '更漏子', '晏几道', '柳间眠，花里醉。\n不惜绣裙铺地。\n钗燕重，鬓蝉轻。\n一双梅子青。\n粉笺书，罗袖泪。\n还有可怜新意。\n遮闷绿，掩羞红。\n晚来团扇风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1260, '更漏子', '晏几道', '柳丝长，桃叶小。\n深院断无人到。\n红日淡，绿烟晴。\n流莺三两声。\n雪香浓，檀晕少。\n枕上卧枝花好。\n春思重，晓妆迟。\n寻思残梦时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1261, '更漏子', '晏几道', '露华高，风信远。\n宿醉画帘低卷。\n梳洗倦，冶游慵。\n绿窗春睡浓。\n彩条轻，金缕重。\n昨日小桥相送。\n芳草恨，落花愁。\n去年同倚楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1262, '更漏子', '晏几道', '出墙花，当路柳。\n借问芳心谁有。\n红解笑，绿能颦。\n千般恼乱春。\n北来人，南去客。\n朝暮等闲攀折。\n怜晚秀，惜残阳。\n情知枉断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1263, '更漏子', '晏几道', '欲论心，先掩泪。\n零落去年风味。\n闲卧处，不言时。\n愁多只自知。\n到情深，俱是怨。\n惟有梦中相见。\n犹似旧，奈人禁。\n偎人说寸心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1264, '河满子', '晏几道', '对镜偷匀玉箸，背人学写银钩。\n系谁红豆罗带角，心情正著春游。\n那日杨花陌上，多时杏子墙头。\n眼底关山无奈，梦中云雨空休。\n问看几许怜才意，两蛾藏尽离愁。\n难拼此回肠断，终须锁定红楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1265, '河满子', '晏几道', '绿绮琴中心事，齐纨扇上时光。\n五陵年少浑薄，轻如曲水飘香。\n夜夜魂消梦峡，年年泪尽啼湘。\n归雁行边远字，惊鸾舞处离肠。\n蕙楼多少铅华在，从来错倚红妆。\n可羡邻姬十五，金钗早嫁王昌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1266, '于飞乐', '晏几道', '晓日当帘，睡痕犹占香腮。\n轻盈笑倚鸾台。\n晕残红，匀宿翠，满镜花开。\n娇蝉鬓畔，插一枝、淡蕊疏梅。\n每到春深，多愁饶恨，妆成懒下香阶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1267, '愁倚阑令・春光好', '晏几道', '凭江阁，看烟鸿。\n恨春浓。\n还有当年闻笛泪，洒东风。\n时候草绿花红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1268, '愁倚阑令・春光好', '晏几道', '花阴月，柳梢莺。\n近清明。\n长恨去年今夜雨，洒离亭。\n枕上怀远诗成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1269, '愁倚阑令・春光好', '晏几道', '春罗薄，酒醒寒。\n梦初残。\n枕片时云雨事，已关山。\n楼上斜日阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1270, '御街行', '晏几道', '年光正似花梢露。\n弹指春还暮。\n翠眉仙子望归来，倚遍玉城珠树。\n岂知别後，好风良月，往事无寻处。\n狂情错向红尘住。\n忘了瑶台路。\n碧桃花蕊已应开，欲伴彩云飞去。\n回思十载，朱颜青鬓，枉被浮名误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1271, '御街行', '晏几道', '街南绿树春饶絮。\n雪满游春路。\n树头花艳杂娇云，树底人家朱户。\n北楼闲上，疏帘高卷，直见街南树。\n阑干倚尽犹慵去。\n几度黄昏雨。\n晚春盘马踏青苔，曾傍绿阴深驻。\n落花犹在，香屏空掩，人面知何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1272, '浪淘沙', '晏几道', '高阁对横塘。\n新燕年光。\n柳花残梦隔潇湘。\n绿浦归帆看不见，还是斜阳。\n一笑解愁肠。\n人会娥妆。\n藕丝衫袖郁金香。\n曳雪牵云留客醉，且伴春狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1273, '浪淘沙', '晏几道', '小绿间长红。\n露蕊烟丛。\n花开花落昔年同。\n惟恨花前携手处，往事成空。\n山远水重重。\n一笑难逢。\n已拼长在别离中。\n霜鬓知他从此去，几度春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1274, '浪淘沙', '晏几道', '丽曲醉思仙。\n十二哀弦。\n蛾叠柳脸红莲。\n多少雨条烟叶恨，红泪离筵。\n行子惜流年。\n鹈枝边。\n吴堤春水舣兰船。\n南去北来今渐老，难负尊前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1275, '浪淘沙', '晏几道', '翠幕绮筵张。\n淑景难忘。\n阳关声巧绕雕梁。\n美酒十分谁与共，玉指持觞。\n晓枕梦高唐。\n略话衷肠。\n小山池院竹风凉。\n明夜月圆帘四卷，今夜思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1276, '丑奴儿・采桑子', '晏几道', '昭华凤管知名久。\n长闭帘栊。\n日日春慵。\n闲倚庭花晕脸红。\n应说金谷无人後，此会相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1277, '丑奴儿・采桑子', '晏几道', '日高庭院杨花转，闲淡春风。\n莺语惺忪。\n似笑金屏昨夜空。\n娇慵未洗匀妆手，闲印斜红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1278, '诉衷情', '晏几道', '种花人自蕊宫来。\n牵衣问小梅。\n今年芳意何似，应向旧枝开。\n凭寄语，谢瑶台。\n客无才。\n粉香传信，玉盏开筵，莫待春回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1279, '诉衷情', '晏几道', '净揩妆脸浅匀眉。\n衫子素梅儿。\n苦无心绪梳洗，闲淡也相宜。\n云态度，柳腰肢。\n入相思。\n夜来月底，今日尊前，未当佳期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1280, '诉衷情', '晏几道', '渚莲霜晓坠残红。\n依约旧秋同。\n玉人团扇恩浅，一意恨西风。\n云去住，月朦胧。\n夜寒浓。\n此时还是，泪墨书成，未有归鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1281, '诉衷情', '晏几道', '凭觞静忆去年秋，桐落故溪头。\n诗成自写红叶，和恨寄东流。\n人脉脉，水悠悠。\n几多愁。\n雁书不到，蝶梦无凭，漫倚高楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1282, '诉衷情', '晏几道', '小梅风韵最妖娆。\n开处雪初消。\n南枝欲附春信，长恨陇人遥。\n闲记忆，旧江皋。\n路迢迢。\n暗香浮动，疏影横斜，几处溪桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1283, '诉衷情', '晏几道', '长因蕙草记罗裙。\n绿腰沈水熏。\n阑干曲处人静，曾共倚黄昏。\n风有韵，月无痕。\n暗消魂。\n拟将幽恨，试写残花，寄与朝云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1284, '诉衷情', '晏几道', '御纱新制石榴裙。\n沈香慢火熏。\n越罗双带宫样，飞鹭碧波纹。\n随锦字，叠香痕。\n寄文君。\n系来花下，解向尊前，谁伴朝云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1285, '诉衷情', '晏几道', '都人离恨满歌筵。\n清唱倚危弦。\n星屏别後千里，更见是何年。\n骢骑稳，绣衣鲜。\n欲朝天。\n北人欢笑，南国悲凉，迎送金鞭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1286, '破阵子', '晏几道', '柳下笙歌庭院，花间姊妹秋千。\n记得春楼当日事，写向红窗夜月前。\n凭谁寄小莲。\n绛蜡等闲陪泪，吴蚕到了缠绵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1287, '好女儿', '晏几道', '绿遍西池。\n梅子青时。\n尽无端、尽日东风恶，更霏微细雨，恼人离恨，满路春泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1288, '好女儿', '晏几道', '酌酒殷勤。\n尽更留春。\n忍无情、便赋馀花落，待花前细把、一春心事，问个人人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1289, '点绛唇', '晏几道', '花信来时，恨无人似花依旧。\n又成春瘦。\n折断门前柳。\n天与多情，不与长相守。\n分飞後。\n泪痕和酒。\n占了双罗袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1290, '点绛唇', '晏几道', '明日征鞭，又将南陌垂杨折。\n自怜轻别。\n拼得音尘绝。\n杏子枝边，倚处阑干月。\n依前缺。\n去年时节。\n旧事无人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1291, '点绛唇', '晏几道', '碧水东流，漫题凉叶津头寄。\n谢娘春意。\n临水颦双翠。\n日日骊歌，空费行人泪。\n成何计。\n未如浓醉。\n闲掩红楼睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1292, '点绛唇', '晏几道', '妆席相逢，旋匀红泪歌金缕。\n意中曾许。\n欲共吹花去。\n长爱荷香，柳色殷桥路。\n留人住。\n淡烟微雨。\n好个双栖处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1293, '点绛唇', '晏几道', '湖上西风，露花啼处秋香老。\n谢家春草。\n唱得清商好。\n笑倚兰舟，转尽新声了。\n烟波渺。\n暮云稀少。\n一点凉蟾小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1294, '两同心', '晏几道', '楚乡春晚，似入仙源。\n拾翠处、闲随流水，踏青路、暗惹香尘。\n心心在，柳外青帘，花下朱门。\n对景且醉芳尊。\n莫话消魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1295, '少年游', '晏几道', '绿勾阑畔，黄昏淡月，携手对残红。\n纱窗影里，朦腾春睡，繁杏小屏风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1296, '少年游', '晏几道', '西溪丹杏，波前媚脸，珠露与深匀。\n南楼翠柳，烟中愁黛，丝雨恼娇颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1297, '少年游', '晏几道', '离多最是，东西流水，终解两相逢。\n浅情终似，行云无定，犹到梦魂中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1298, '少年游', '晏几道', '西楼别後，风高露冷，无奈月分明。\n飞鸿影里，捣衣砧外，总是玉关情。\n王孙此际，山重水远，何处赋西征。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1299, '少年游', '晏几道', '雕梁燕去，裁诗寄远，庭院旧风流。\n黄花醉了，碧梧题罢，闲卧对高秋。\n繁云破後，分明素月，凉影挂金钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1300, '虞美人', '晏几道', '闲敲玉镫隋堤路。\n一笑开朱户。\n素云凝澹月婵娟。\n门外鸭头春水、木兰船。\n吹花拾蕊嬉游惯。\n天与相逢晚。\n一声长笛倚楼时。\n应恨不题红叶、寄相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1301, '虞美人', '晏几道', '飞花自有牵情处。\n不向枝边坠。\n随风飘荡已堪愁。\n更伴东流流水、过秦楼。\n楼中翠黛含春怨。\n闲倚阑干见。\n远弹双泪惜香红。\n暗恨玉颜光景、与花同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1302, '虞美人', '晏几道', '曲阑干外天如水。\n昨夜还曾倚。\n初将明月比佳期。\n长向月圆时候、望人归。\n罗衣著破前香在。\n旧意谁教改。\n一春离恨懒调弦。\n犹有两行闲泪、宝筝前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1303, '虞美人', '晏几道', '疏梅月下歌金缕。\n忆共文君语。\n更谁情浅似春风。\n一夜满枝新绿、替残红。\n苹香已有莲开信。\n两桨佳期近。\n采莲时节定来无。\n醉後满身花影、倩人扶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1304, '虞美人', '晏几道', '玉箫吹遍烟花路。\n小谢经年去。\n更教谁画远山眉。\n又是陌头风细、恼人时。\n时光不解年年好。\n叶上秋声早。\n可怜蝴蝶易分飞。\n只有杏梁双燕、每来归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1305, '虞美人', '晏几道', '秋风不似春风好。\n一夜金英老。\n更谁来凭曲阑干。\n惟有雁边斜月、照关山。\n双星旧约年年在。\n笑尽人情改。\n有期无定是无期。\n说与小云新恨、也低眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1306, '虞美人', '晏几道', '小梅枝上东君信。\n雪後花期近。\n南枝开尽北枝开。\n长被陇头游子、寄春来。\n年年衣袖年年泪。\n总为今朝意。\n问谁同是忆花人。\n赚得小鸿眉黛、也低颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1307, '虞美人', '晏几道', '湿红笺纸回纹字。\n多少柔肠事。\n去年双燕欲归时。\n还是碧云千里、锦书迟。\n南楼风月长依旧。\n别恨无端有。\n倩谁横笛倚危阑。\n今夜落梅声里、怨关山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1308, '虞美人', '晏几道', '一弦弹尽仙韶乐。\n曾破千金学。\n玉楼银烛夜深深。\n愁见曲中双泪、落香襟。\n从来不奈离声怨。\n几度朱弦断。\n未知谁解赏新音。\n长是好风明月、暗知心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1309, '采桑子', '晏几道', '秋千散後朦胧月，满院人闲。\n几处雕阑。\n一夜风吹杏粉残。\n昭阳殿里春衣就，金缕初乾。\n莫信朝寒。\n明日花前试舞看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1310, '采桑子', '晏几道', '花前独占春风早，长爱江梅。\n秀艳清杯。\n芳意先愁凤管催。\n寻香已落闲人後，此恨难裁。\n更晚须来。\n却恐初开胜未开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1311, '采桑子', '晏几道', '芦鞭坠遍杨花陌，晚见珍珍。\n疑是朝云。\n来作高唐梦里人。\n应怜醉落楼中帽，长带歌尘。\n试拂香茵。\n留解金鞍睡过春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1312, '采桑子', '晏几道', '日高庭院杨花转，闲淡春风。\n昨夜匆匆。\n颦入遥山翠黛中。\n金盆水冷菱花净，满面残红。\n欲洗犹慵。\n弦上啼乌此夜同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1313, '采桑子', '晏几道', '征人去日殷勤嘱，莫负心期。\n寒雁来时。\n第一传书慰别离。\n轻春织就机中素，泪墨题诗。\n欲寄相思。\n日日高楼看雁飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1314, '采桑子', '晏几道', '花时恼得琼枝瘦，半被残香。\n睡损梅妆。\n红泪今春第一行。\n风流笑伴相逢处，白马游缰。\n共折垂杨。\n手拈芳条说夜长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1315, '采桑子', '晏几道', '春风不负年年信，长趁花期。\n小锦堂西。\n红杏初开第一枝。\n碧箫度曲留人醉，昨夜归迟。\n短恨凭谁。\n莺语殷勤月落时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1316, '采桑子', '晏几道', '秋来更觉消魂苦，小字还稀。\n坐想行思。\n怎得相看似旧时。\n南楼把手凭肩处，风月应知。\n别後除非。\n梦里时时得见伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1317, '采桑子', '晏几道', '谁将一点凄凉意，送入低眉。\n画箔闲垂。\n多是今宵得睡迟。\n夜痕记尽窗间月，曾误心期。\n准拟相思。\n还是窗间记月时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1318, '采桑子', '晏几道', '宜春苑外楼堪倚，雪意方浓。\n雁影冥。\n正共银屏小景同。\n可无人解相思处，昨夜东风。\n梅蕊应红。\n知在谁家锦字中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1319, '采桑子', '晏几道', '白莲池上当时月，今夜重圆。\n曲水兰船。\n忆伴飞琼看月眠。\n黄花绿酒分携後，泪湿吟笺。\n旧事年年。\n时节南湖又采莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1320, '采桑子', '晏几道', '高吟烂醉淮西月，诗酒相留。\n明日归舟。\n碧藕花中醉过秋。\n文姬赠别双团扇，自写银钩。\n散尽离愁。\n携得清风出画楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1321, '采桑子', '晏几道', '前欢几处笙歌地，长负登临。\n月幌风襟。\n犹忆西楼著意深。\n莺花见尽当时事，应笑如今。\n一寸愁心。\n日日寒蝉夜夜砧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1322, '采桑子', '晏几道', '无端恼破桃源梦，明日青楼。\n玉腻花柔。\n不学行云易去留。\n应嫌衫袖前香冷，重傍金虬。\n歌扇风流。\n遮尽归时翠黛愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1323, '采桑子', '晏几道', '年年此夕东城见，欢意匆匆。\n明日还重。\n却在楼台缥缈中。\n垂螺拂黛清歌女，曾唱相逢。\n秋月春风。\n醉枕香衾一岁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1324, '采桑子', '晏几道', '双螺未学同心绾，已占歌名。\n月白风清。\n长倚昭华笛里声。\n知音敲尽朱颜改，寂寞时情。\n一曲离亭。\n惜与青楼忍泪听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1325, '采桑子', '晏几道', '西楼月下当时见，泪粉偷匀。\n歌罢还颦。\n恨隔炉烟看未真。\n别来楼外垂杨缕，几换青春。\n倦客红尘。\n长记楼中粉泪人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1326, '采桑子', '晏几道', '非花非雾前时见，满眼娇春。\n浅笑微颦。\n恨隔垂帘看未真。\n殷勤借问家何处，不在红尘。\n若是朝云。\n宜作今宵梦里人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1327, '采桑子', '晏几道', '当时月下分飞处，依旧凄凉。\n也会思量。\n不道孤眠夜更长。\n泪痕遍鸳鸯枕，重绕回廊。\n月上东窗。\n长到如今欲断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1328, '采桑子', '晏几道', '湘妃浦口莲开尽，昨夜红稀。\n懒过前溪。\n闲舣扁舟看雁飞。\n去年谢女池边醉，晚雨霏微。\n记得归时。\n旋折新荷盖舞衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1329, '采桑子', '晏几道', '别来长记西楼事，结遍兰襟。\n遗恨重寻。\n弦断相如绿绮琴。\n何时一枕逍遥夜，细话初心。\n若问如今。\n也似当时著意深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1330, '采桑子', '晏几道', '红窗碧玉新名旧，犹绾双螺。\n一寸秋波。\n千斛明珠觉未多。\n小来竹马同游客，惯听清歌。\n今日蹉跎。\n恼乱工夫晕翠蛾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1331, '采桑子', '晏几道', '昭华凤管知名久，长闭帘栊。\n闻道春慵。\n方倚庭花晕脸红。\n可怜金谷无人後，此会相逢。\n三弄临风。\n送得当筵玉盏空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1332, '采桑子', '晏几道', '金风玉露初凉夜，秋草窗前。\n浅醉闲眠。\n一枕江风梦不圆。\n长情短恨难凭寄，枉费红笺。\n试拂么弦。\n却恐琴心可暗传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1333, '采桑子', '晏几道', '心期昨夜寻思遍，犹负殷勤。\n齐斗堆金。\n难买丹诚一寸真。\n须知枕上尊前意，占得长春。\n寄语东邻。\n似此相看有几人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1334, '踏莎行', '晏几道', '柳上烟归，池南雪尽。\n东风渐有繁华信。\n花开花谢蝶应知，春来春去莺能问。\n梦意犹疑，心期欲近。\n云笺字字萦方寸。\n宿妆曾比杏腮红，忆人细把香英认。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1335, '踏莎行', '晏几道', '宿雨收尘，朝霞破暝。\n风光暗许花期定。\n玉人呵手试妆时，粉香帘幕阴阴静。\n斜雁朱弦，孤鸾绿镜。\n伤春误了寻芳兴。\n去年今日杏墙西，啼莺唤得闲愁醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1336, '踏莎行', '晏几道', '绿径穿花，红楼压水。\n寻芳误到蓬莱地。\n玉颜人是蕊珠仙，相逢展尽双蛾翠。\n梦草闲眠，流觞浅醉。\n一春总见瀛洲事。\n别来双燕又西飞，无端不寄相思字。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1337, '踏莎行', '晏几道', '雪尽寒轻，月斜烟重。\n清欢犹记前时共。\n迎风朱户背灯开，拂檐花影侵帘动。\n绣枕双鸳，香苞翠凤。\n从来往事都如梦。\n伤心最是醉归时，眼前少个人人送。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1338, '满庭芳', '晏几道', '南苑吹花，西楼题叶，故园欢事重重。\n凭阑秋思，闲记旧相逢。\n几处歌云梦雨，可怜便、流水西东。\n别来久，浅情未有，锦字系征鸿。\n年光还少味，开残槛菊，落尽溪桐。\n漫留得，尊前淡月西风。\n此恨谁堪共说，清愁付、绿酒杯中。\n佳期在，归时待把，香袖看啼红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1339, '留春令', '晏几道', '画屏天畔，梦回依约，十洲云水。\n手拈红笺寄人书，写无限、伤春事。\n别浦高楼曾漫倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1340, '留春令', '晏几道', '采莲舟上，夜来陡觉，十分秋意。\n懊恼寒花暂时香，与情浅、人相似。\n玉蕊歌清招晚醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1341, '留春令', '晏几道', '海棠风横，醉中吹落，香红强半。\n小粉多情怨花飞，仔细把、残香看。\n一抹浓檀秋水畔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1342, '风入松', '晏几道', '柳阴庭院杏梢墙。\n依旧巫阳。\n凤箫已远青楼在，水沈谁、复暖前香。\n临镜舞鸾离照，倚筝飞雁辞行。\n坠鞭人意自凄凉。\n泪眼回肠。\n断云残雨当年事，到如今、几处难忘。\n两袖晓风花陌，一帘夜月兰堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1343, '风入松', '晏几道', '心心念念忆相逢。\n别恨谁浓。\n就中懊恼难拼处，是擘钗、分钿匆匆。\n却似桃源路失，落花空记前踪。\n彩笺书尽浣溪红。\n深意难通。\n强欢酒图消遣，到醒来、愁闷还重。\n若是初心未改，多应此意须同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1344, '清商怨', '晏几道', '庭花香信尚浅。\n最玉楼先暖。\n梦觉春衾，江南依旧远。\n回纹锦字暗翦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1345, '秋蕊香', '晏几道', '池苑清阴欲就。\n还傍送春时候。\n眼中人去难欢偶。\n谁共一杯芳酒。\n朱阑碧砌皆如旧。\n记携手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1346, '秋蕊香', '晏几道', '歌彻郎君秋草。\n别恨远山眉小。\n无情莫把多情恼。\n第一归来须早。\n红尘自古长安道。\n故人少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1347, '思远人', '晏几道', '红叶黄花秋意晚，千里念行客。\n飞云过尽，归鸿无信，何处寄书得。\n泪弹不尽临窗滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1348, '碧牡丹', '晏几道', '翠袖疏纨扇。\n凉叶催归燕。\n一夜西风，几处伤高怀远。\n细菊枝头，开嫩香还遍。\n月痕依旧庭院。\n事何限。\n怅望秋意晚。\n离人鬓华将换。\n静忆天涯，路比此情犹短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1349, '长相思', '晏几道', '长相思。\n长相思。\n若问相思甚了期。\n除非相见时。\n长相思。\n长相思。\n欲把相思说似谁。\n浅情人不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1350, '醉落魄・一斛珠', '晏几道', '满街斜月。\n垂鞭自唱阳关彻。\n断尽柔肠思归切。\n都为人人，不许多时别。\n南桥昨夜风吹雪。\n短长亭下征尘歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1351, '醉落魄・一斛珠', '晏几道', '鸾孤月缺。\n两春惆怅音尘绝。\n如今若负当时节。\n信道欢缘，狂向衣襟结。\n若问相思何处歇。\n相逢便是相思彻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1352, '醉落魄・一斛珠', '晏几道', '天教命薄。\n青楼占得声名恶。\n对酒当歌寻思著。\n月户星窗，多少旧期约。\n相逢细语初心错。\n两行红泪尊前落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1353, '醉落魄・一斛珠', '晏几道', '休休莫莫。\n离多还是因缘恶。\n有情无奈思量著。\n月夜佳期，近写青笺约。\n心心口口长恨昨。\n分飞容易当时错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1354, '望仙楼・胡捣练', '晏几道', '小春花信日边来，未上江楼先坼。\n今岁东君消息。\n还自南枝得。\n素衣染尽天香，玉酒添成国色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1355, '凤孤飞', '晏几道', '一曲画楼钟动，宛转歌声缓。\n绮席飞尘满。\n更少待、金蕉暖。\n细雨轻寒今夜短。\n依前是、粉墙别馆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1356, '西江月', '晏几道', '愁黛颦成月浅，啼妆印得花残。\n只消鸳枕夜来闲。\n晓镜心情便懒。\n醉帽檐头风细，征衫袖口香寒。\n绿江春水寄书难。\n携手佳期又晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1357, '西江月', '晏几道', '南苑垂鞭路冷，西楼把袂人稀。\n庭花犹有鬓边枝。\n且插残红自醉。\n画幕凉催燕去，香屏晓放云归。\n依前青枕梦回时。\n试问闲愁有几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1358, '武陵春', '晏几道', '绿蕙红兰芳信歇，金蕊正风流。\n应为诗人多怨秋。\n花意与消愁。\n梁王苑路香英密，长记旧嬉游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1359, '武陵春', '晏几道', '九日黄花如有意，依旧满珍丛。\n谁似龙山秋兴浓。\n吹帽落西风。\n年年岁岁登高节，欢事旋成空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1360, '武陵春', '晏几道', '烟柳长堤知几曲，一曲一魂消。\n秋水无情天共遥。\n愁送木兰桡。\n熏香绣被心情懒，期信转迢迢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1361, '解佩令', '晏几道', '玉阶秋感，年华暗去。\n掩深宫、团扇无绪。\n记得当时，自翦下、机中轻素。\n点丹青、画成秦女。\n凉襟犹在，朱弦未改，忍霜纨、飘零何处。\n自古悲凉，是情事、轻如云雨。\n倚么弦、恨长难诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1362, '行香子', '晏几道', '晚绿寒红。\n芳意匆匆。\n惜年华、今与谁同。\n碧云零落，数字征鸿。\n看渚莲凋，宫扇旧，怨秋风。\n流波坠叶，佳期何在，想天教、离恨无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1363, '庆春时', '晏几道', '倚天楼殿，升平风月，彩仗春移。\n鸾丝凤竹，长生调里，迎得翠舆归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1364, '庆春时', '晏几道', '梅梢已有，春来音信，风意犹寒。\n南楼暮雪，无人共赏，闲却玉阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1365, '喜团圆', '晏几道', '危楼静锁，窗中远岫，门外垂杨。\n珠帘不禁春风度，解偷送馀香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1366, '忆闷令', '晏几道', '取次临鸾匀画浅。\n酒醒迟来晚。\n多情爱惹闲愁，长黛眉低敛。\n月底相逢花下见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1367, '梁州令', '晏几道', '莫唱阳关曲。\n泪湿当年金缕。\n离歌自古最消魂，闻歌更在魂消处。\n南楼杨柳多情绪。\n不系行人住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1368, '燕归梁', '晏几道', '莲叶雨，蓼花风。\n秋恨几枝红。\n远烟收尽水溶溶。\n飞雁碧云中。\n衷肠事。\n鱼笺字。\n情绪年年相似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1369, '胡捣练', '晏几道', '小亭初报一枝梅，惹起江南归兴。\n遥想玉溪风景，水漾横斜影。\n异香直到醉乡中，醉後还因香醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1370, '扑蝴蝶', '晏几道', '风梢雨叶，绿遍江南岸。\n思归倦客，寻芳来最晚。\n酒边红日初长，陌上飞花正满。\n凄凉数声弦管。\n怨春短。\n玉人应在，明月楼中画眉懒。\n鱼笺锦字，多时音信断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1371, '丑奴儿・采桑子', '晏几道', '夜来酒醒清无梦，愁倚阑干。\n露滴轻寒。\n雨打芙蓉泪不乾。\n佳人别後音尘悄，瘦尽难拼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1372, '谒金门', '晏几道', '溪声急。\n无数落花漂出。\n燕子分泥蜂酿蜜。\n迟迟艳风日。\n须信芳菲随失。\n况复佳期难必。\n拟把此情书万一。\n愁多翻阁笔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1373, '忆黄梅', '王观', '枝上叶儿未展。\n已有坠红千片。\n春意怎生防，怎不怨。\n被我安排，矮牙床斗帐，和娇艳。\n移在花丛里面。\n请君看。\n惹清香，偎媚暖。\n爱香爱暖金杯满。\n问春怎管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1374, '浪淘沙', '王观', '素手水晶盘。\n垒起仙丸。\n红绡剪碎却成团。\n逗得安排金粟遍，何似鸡冠。\n味胜玉浆寒。\n只被宜酸。\n莫将荔子一般看。\n色淡香消损，才到长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1375, '天香', '王观', '霜瓦鸳鸯，风帘翡翠，今年早是寒少。\n矮钉明窗，侧开朱户，断莫乱教人到。\n重阴未解，云共雪、商量不了。\n青帐垂毡要密，红炉收围宜小。\n呵梅弄妆试巧。\n绣罗衣、瑞云芝草。\n伴我语时同语，笑时同笑。\n已被金尊劝倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1376, '卜算子', '王观', '水是眼波横，山是眉峰聚。\n欲问行人去那边，眉眼盈盈处。\n才始送春归，又送君归去。\n若到江东赶上春，千万和春住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1377, '清平乐', '王观', '黄金殿里。\n烛影双龙戏。\n劝得官家真个醉。\n进酒犹呼万岁。\n折旋舞彻伊州。\n君恩与整搔头。\n一夜御前宣住，六宫多少人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1378, '雨中花令', '王观', '百尺清泉声陆续。\n映潇洒、碧梧翠竹。\n面千步回廊，重重帘幕，小枕寒玉。\n试展鲛绡看画轴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1379, '庆清朝慢・庆清朝', '王观', '调雨为酥，催冰做水，东君分付春还。\n何人便将轻暖，点破残寒。\n结伴踏青去好，平头鞋子小双鸾。\n烟郊外，望中秀色，如有无间。\n晴则个，阴则个，得天气，有许多般。\n须教镂花拨柳，争要先看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1380, '清平乐', '王观', '宜春小苑。\n处处花开满。\n学得红妆红要浅。\n催上金车要看。\n君王曲宴瑶池。\n小舟掠水如飞。\n夺得锦标归去，匆匆不惜罗衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1381, '木兰花令', '王观', '铜驼陌上新正後。\n第一风流除是柳。\n勾牵春事不如梅，断送离人强似酒。\n东君有意偏就。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1382, '生查子', '王观', '关山魂梦长，塞雁音书少。\n两鬓可怜青，一夜相思老。\n归傍碧纱窗，说与人人道。\n真个别离难，不似相逢好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1383, '菩萨蛮', '王观', '单于吹落山头月。\n漫漫江上沙如雪。\n谁唱缕金衣。\n水寒船舫稀。\n芦花枫叶浦。\n忆抱琵琶语。\n身未发长沙。\n梦魂先到家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1384, '江城梅花引', '王观', '年年江上见寒梅。\n暗香来。\n为谁开。\n疑是月宫、仙子下瑶台。\n冷艳一枝春在手，故人远，相思寄与谁。\n怨极恨极嗅香蕊。\n念此情，家万里。\n暮霞散绮。\n楚天碧、片片轻飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1385, '高阳台', '王观', '红入桃腮，青回柳眼，韶华已破三分。\n人不归来，空教草怨王孙。\n平明几点催花雨，梦半阑、枕初闻。\n问东君，因甚将春，老了闲人。\n东郊十里香尘满，旋安排玉勒，整顿雕轮。\n趁取芳时，共寻岛上红云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1386, '减字木兰花', '王观', '瑞云仙雾。\n拂晓重重遮绣户。\n一炷清香。\n千尺流霞入寿觞。\n家门转好。\n从此应须长不老。\n来岁春风。\n看拜西枢小令公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1387, '红芍药', '王观', '人生百岁，七十稀少。\n更除十年孩童小。\n又十年昏老。\n都来五十载，一半被、睡魔分了。\n那二十五载之中，宁无些个烦恼。\n仔细思量，好追欢及早。\n遇酒追朋笑傲。\n任玉山摧倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1388, '失调名', '王观', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1389, '临江仙', '王观', '别岸相逢何草草，扁舟两岸垂杨。\n绣屏珠箔绮香囊。\n酒深歌拍缓，愁入翠眉长。\n燕子归来人去也，此时无奈昏黄。\n桃花应是我心肠。\n不禁微雨，流泪湿红妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1390, '万年欢', '王安礼', '雅出群芳。\n占春前信息，腊後风光。\n野岸邮亭，繁似万点轻霜。\n清浅溪流倒影，更黯淡、月色笼香。\n浑疑是、姑射冰姿，寿阳粉面初妆。\n多情对景易感，况淮天庾岭，迢递相望。\n愁听龙吟凄绝，画角悲凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1391, '潇湘忆故人慢', '王安礼', '薰风微动，方樱桃弄色，萱草成窠。\n翠帏敞轻罗。\n试冰簟初展，几尺湘波。\n疏帘广厦，寄潇洒、一枕南柯。\n引多少、梦中归绪，洞庭雨棹烟蓑。\n惊回处，闲昼永，但时时，燕雏莺友相过。\n正绿影婆娑。\n况庭有幽花，池有新荷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1392, '点绛唇', '王安礼', '春睡腾腾，觉来鸳被堆香暖。\n起来慵懒。\n触目情何限。\n深院日斜，人静花阴转。\n柔肠断。\n凭高不见。\n芳草连天远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1393, '江神子・江城子', '张舜民', '七朝文物旧江山。\n水如天。\n莫凭栏。\n千古斜阳，无处问长安。\n更隔秦淮闻旧曲，秋已半，夜将阑。\n争教潘鬓不生斑。\n敛芳颜。\n抹么弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1394, '朝中措', '张舜民', '三湘迁客思悠哉。\n尊俎定常开。\n云雨未消歌伴，山川忍对离杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1395, '卖花声', '张舜民', '木叶下君山。\n空水漫漫。\n十分斟酒敛芳颜。\n不是渭城西去客，休唱阳关。\n醉袖抚危栏。\n天淡云闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1396, '卖花声', '张舜民', '楼上久踟躇。\n地远身孤。\n拟将憔悴吊三闾。\n自是长安日下影，流落江湖。\n烂醉且消除。\n不醉何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1397, '江南好・忆江南', '曾布', '江南客，家有宁馨儿。\n三世文章称大手，一门兄弟独良眉。\n藉甚众多推。\n千里足，来自渥洼池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1398, '水调歌头', '曾布', '魏豪有冯燕，年少客幽并。\n击球斗鸡为戏，游侠久知名。\n因避仇、来东郡。\n元戎留属中军。\n直气凌貔虎，须臾叱咤风云。\n凛凛坐中生。\n偶乘佳兴。\n轻裘锦带，东风跃马，往来寻访幽胜。\n游冶出东城。\n堤上莺花撩乱，香车宝马纵横。\n草软平沙稳。\n高楼两岸春风，语笑隔帘声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1399, '水调歌头', '曾布', '袖笼鞭敲镫。\n无语独闲行。\n绿杨下、人初静。\n烟澹夕阳明。\n窈窕佳人，独立瑶阶，掷果潘郎，瞥见红颜横波，不胜娇软倚银屏。\n曳红裳，频推朱户，半开还掩，似欲倚、咿哑声里，细说深情。\n因遣林间青鸟，为言彼此心期，的的深相许，窃香解佩，绸缪相顾不胜情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1400, '水调歌头', '曾布', '说良人滑将张婴。\n从来嗜酒，还家镇长酩酊狂酲。\n屋上鸣鸠空斗，梁间客燕相惊。\n谁与花为主，兰房从此，朝云夕雨两牵萦。\n似游丝飘荡，随风无定。\n奈何岁华荏苒，欢计苦难凭。\n唯见新恩缱绻，连枝并翼，香闺日日为郎，谁知松萝托蔓，一比一毫轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1401, '水调歌头', '曾布', '一夕还家醉，开户起相迎。\n为郎引裾相庇，低首略潜形。\n情深无隐。\n欲郎乘间起佳兵。\n授青萍。\n茫然抚叹，不忍欺心。\n尔能负心於彼，於我必无情。\n熟视花钿不足，刚肠终不能平。\n假手迎天意，一挥霜刃。\n窗间粉颈断瑶琼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1402, '水调歌头', '曾布', '凤凰钗、宝玉凋零。\n惨然怅，娇魂怨，饮泣吞声。\n还被凌波呼唤，相将金谷同游，想见逢迎处，揶揄羞面，妆脸泪盈盈。\n醉眠人、醒来晨起，血凝螓首，但惊喧，白邻里、骇我卒难明。\n思败幽囚推究，覆盆无计哀鸣。\n丹笔终诬服，圜门驱拥，衔冤垂首欲临刑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1403, '水调歌头', '曾布', '向红尘里，有喧呼攘臂，转声辟众，莫遣人冤滥、杀张室，忍偷生。\n僚吏惊呼呵叱，狂辞不变如初，投身属吏，慷慨吐丹诚。\n仿佛缧绁，自疑梦中，闻者皆惊叹，为不平。\n割爱无心，泣对虞姬，手戮倾城宠，翻然起死，不教仇怨负冤声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1404, '水调歌头', '曾布', '义城元靖贤相国，喜慕英雄士，赐金缯。\n闻斯事，频叹赏，封章归印。\n请赎冯燕罪，日边紫泥封诏，阖境赦深刑。\n万古三河风义在，青简上、众知名。\n河东注，任流水滔滔，水涸名难泯。\n至今乐府歌咏。\n流入管弦声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1405, '临江仙', '魏夫人', '庭院深深深几许，云窗雾阁春迟。\n为谁憔悴损芳姿。\n夜来清梦好，应是发南枝。\n玉瘦檀轻无限恨，南楼羌管休吹。\n浓香吹尽有谁知。\n暖风迟日也，别到杏花肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1406, '好事近', '魏夫人', '雨後晓寒轻，花外早莺啼歇。\n愁听隔溪残漏，正一声凄咽。\n不堪西望去程赊，离肠万回结。\n不似海棠阴下，按凉州时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1407, '阮郎归', '魏夫人', '夕阳楼外落花飞。\n晴空碧四垂。\n去帆回首已天涯。\n孤烟卷翠微。\n楼上客，鬓成丝。\n归来未有期。\n断魂不忍下危梯。\n桐阴月影移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1408, '减字木兰花', '魏夫人', '西楼明月。\n掩映梨花千树雪。\n楼上人归。\n愁听孤城一雁飞。\n玉人何处。\n又见江南春色暮。\n芳信难寻。\n去後桃花流水深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1409, '减字木兰花', '魏夫人', '落花飞絮。\n杳杳天涯人甚处。\n欲寄相思。\n春尽衡阳雁渐稀。\n离肠泪眼。\n肠断泪痕流不断。\n明月西楼。\n一曲阑干一倍愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1410, '菩萨蛮', '魏夫人', '溪山掩映斜阳里。\n楼台影动鸳鸯起。\n隔岸两三家。\n出墙红杏花。\n绿杨堤下路。\n早晚溪边去。\n三见柳绵飞。\n离人犹未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1411, '菩萨蛮', '魏夫人', '东风已绿瀛洲草。\n画楼帘卷清霜晓。\n清绝比湖梅。\n花开未满枝。\n长天音信断。\n又见南归雁。\n何处是离愁。\n长安明月楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1412, '菩萨蛮', '魏夫人', '红楼斜倚连溪曲。\n楼前溪水凝寒玉。\n荡漾木兰船。\n船中人少年。\n荷花娇欲语。\n笑入鸳鸯浦。\n波上暝烟低。\n菱歌月下归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1413, '定风波', '魏夫人', '不是无心惜落花。\n落花无意恋春华。\n昨日盈盈枝上笑。\n谁道。\n今朝吹去落谁家。\n把酒临风千种恨。\n难问。\n梦回云散见无涯。\n妙舞清歌谁是主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1414, '点绛唇', '魏夫人', '波上清风，画船明月人归後，渐消残酒。\n独自凭阑久。\n聚散匆匆，此恨年年有，重回首。\n淡烟疏柳。\n隐隐芜城漏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1415, '武陵春', '魏夫人', '小院无人帘半卷，独自倚阑时。\n宽尽春来金缕衣。\n憔悴有谁知。\n玉人近日书来少，应是怨来迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1416, '江城子', '魏夫人', '别郎容易见郎难。\n几何般。\n懒临鸾。\n憔悴容仪，陡觉缕衣宽。\n门外红梅将谢也，谁信道、不曾看。\n晓妆楼上望长安。\n怯轻寒。\n莫凭阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1417, '卷珠帘・蝶恋花', '魏夫人', '记得来时春未暮。\n执手攀花，袖染花梢露。\n暗卜春心共花语。\n争寻双朵争先去。\n多情因甚相辜负。\n轻折轻离，欲向谁分诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1418, '系裙腰', '魏夫人', '灯花耿耿漏迟迟。\n人别後、夜凉时。\n西风潇洒梦初回。\n谁念我，就单枕，皱双眉。\n锦屏绣幌与秋期。\n肠欲断、泪偷垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1419, '清平乐', '王仲甫', '黄金殿里。\n烛影双龙戏。\n劝得官家真个醉，进酒犹呼万岁。\n锦舞彻凉州，君恩与整搔头。\n一夜御前宣唤，六宫多少人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1420, '满朝欢', '王仲甫', '忆得延州，旧曾相见，东城近东下住。\n被若著意引归家，放十分、以上抬举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1421, '丑奴儿・采桑子', '王仲甫', '牡丹不好长春好，有个因依。\n一两枝儿。\n但是风光总属伊。\n当初祗为嫦娥种，月正明时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1422, '永遇乐', '王仲甫', '风折新英，雨肥繁实，又还如豆。\n玉核初成，红腮尚浅，齿软酸透。\n粉墙低亚，佳人惊见，不管露沾襟袖。\n一枝钗子未插，应把手挪频嗅。\n相思病酒，只因思此，免使文君眉皱。\n入鼎调羹，攀林止渴，功业还依旧。\n看看飞燕，衔将春去，又将欲、黄昏时候。\n争如向、金盘满捧，共君王对酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1423, '浪淘沙', '王仲甫', '素手水晶盘。\n垒起仙丸。\n红绡碾碎却成团。\n逗得安排金粟遍，何似鸡冠。\n味胜玉浆寒。\n只被宜酸。\n莫将荔子一般看。\n色淡香消损，才到长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1424, '醉落魄・一斛珠', '王仲甫', '醉醒醒醉。\n凭君会取皆滋味。\n浓斟琥珀香浮蚁。\n一入愁肠，便有阳春意。\n须将席幕为天地。\n歌前起舞花前睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1425, '蓦山溪', '王仲甫', '挂冠神武，来作烟花主。\n千里好江山，都尽是、君恩赐与。\n风勾月引，催上泛宅时，酒倾玉，脍堆雪，总道神仙侣。\n蓑衣箬笠，更著些儿雨。\n横笛两三声，晚云中、惊鸥来去。\n欲烦妙手，写入散人图，蜗角名，蝇头利，著甚来由顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1426, '离亭燕・离亭宴', '孙浩然', '一带江山如画。\n景物向秋潇洒。\n水浸碧天何处断，霁色冷光相射。\n橘树荻花洲，掩映竹篱茅舍。\n天际客帆高挂。\n烟外酒旗低亚。\n多少六朝兴废事，尽入渔樵闲话。\n怅望倚层楼，红日无言西下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1427, '夜行船', '孙浩然', '何处采菱归暮。\n隔宵烟、菱歌轻举。\n白苹风起月华寒，影朦胧、半和梅雨。\n脉脉相逢心似许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1428, '鹧鸪天', '王诜', '才子阴风度远关。\n清愁曾向画图看。\n山衔斗柄三星没，雪共月明千里寒。\n新路陌，旧江干。\n崎岖谁叹客程难。\n临风更听昭华笛，簌簌梅花满地残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1429, '花心动', '王诜', '春欲来时，看雪里、新梅品流珍绝。\n气韵楚江，颜色中央，数朵巧熔香蜡。\n嫩苞珠泪圆金烛，娇腮润、蜂房微缺。\n画栏悄，佳人道妆，醉吟风月。\n淡白轻红谩说。\n算何事、东君用心偏别。\n赋与异姿，添与清香，堪向苦寒时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1430, '落梅花・落梅', '王诜', '寿阳妆晚，慵匀素脸，经宵醉痕堪惜。\n前村雪里，几枝初绽，□冰姿仙格。\n忍被东风，乱飘满地，残英堆积。\n可堪江上起离愁，凭谁说寄，肠断未归客。\n流恨声传羌笛。\n感行人、水亭山驿。\n越溪信阻，仙乡路杳，但风流尘迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1431, '黄莺儿', '王诜', '多情春意忆时节。\n北圃人来，传道江梅，依稀芳姿，数枝新发。\n夸嫩脸著胭脂，腻滑凝香雪。\n问伊还记年时，正好相看，因甚轻别。\n情切。\n往事散浮云，旧恨成华发。\n算知空对，绮槛雕栏，孜孜望人攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1432, '踏青游', '王诜', '金勒狨鞍，西城嫩寒春晓。\n路渐入、垂杨芳草。\n过平堤，穿绿迳，几声啼鸟。\n是处里，谁家杏花临水，依约靓妆窥照。\n极目高原，东风露桃烟岛。\n望十里、红围绿绕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1433, '忆故人・烛影摇红', '王诜', '烛影摇红向夜阑，乍酒醒、心情懒。\n尊前谁为唱阳关，离恨天涯远。\n无奈云沈雨散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1434, '行香子', '王诜', '金井先秋，梧叶飘黄。\n几回惊觉梦初长。\n雨微烟淡。\n疏雨池塘。\n渐蓼花明，菱花冷，藕花凉。\n幽人已惯，枕单衾冷，任商飙、催换年光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1435, '蝶恋花', '王诜', '钟送黄昏鸡报晓。\n昏晓相催，世事何时了。\n万恨千愁人自老。\n春来依旧生芳草。\n忙处人多闲处少。\n闲处光阴，几个人知道。\n独上高楼云渺渺。\n天涯一点青山小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1436, '玉楼春', '王诜', '锦城春色花无数。\n排比笙歌留客住。\n轻寒轻暖夹衣天，乍雨乍晴寒食路。\n花虽不语莺能语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1437, '花发沁园春', '王诜', '帝里春归，早先妆点，皇家池馆园林。\n雏莺未迁，燕子乍归，时节戏弄晴阴。\n琼楼珠阁，恰正在、柳曲花心。\n翠袖艳、衣凭阑干，惯闻弦管新音。\n此际相携宴赏，纵行乐随处，芳树遥岑。\n桃腮杏脸，嫩英万叶，千枝绿浅红深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1438, '人月圆', '王诜', '小桃枝上春来早，初试薄罗衣。\n年年此夜，华灯盛照，人月圆时。\n禁街箫鼓，寒轻夜永，纤手同携。\n更阑人静。\n千门笑语，声在帘帏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1439, '换遍歌头', '王诜', '雪霁轻尘敛，好风初报柳。\n春寒浅、当三五。\n是处鳌山耸，金羁宝乘，游赏遍蓬壶。\n向黄昏时候。\n对双龙阙门前，皓月华灯射，变清昼。\n彩凤低衔天语。\n承宣诏传呼。\n飞上层霄，共陪霞觞频举。\n更渐阑，正回路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1440, '失调名', '王诜', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1441, '失调名', '王诜', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1442, '失调名', '王诜', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1443, '画堂春令・画堂春', '王诜', '画堂霜重晓寒消，南枝红雪妆成。\n卷帘疑是弄妆人。\n粉面带春醒。\n最爱北江临岸，含娇浅淡精神。\n微风不动水纹平。\n倒影斗轻盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1444, '撼庭竹', '王诜', '绰略青梅弄春色。\n真艳态堪惜。\n经年费尽东君力。\n有情先到探春客。\n无语泣寒香，时暗度瑶席。\n月下风前空怅望，思携手同摘。\n画栏倚遍无消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1445, '蝶恋花', '王诜', '小雨初晴回晚照。\n金翠楼台，倒影芙蓉沼。\n杨柳垂垂风袅袅。\n嫩荷无数青钿小。\n似此园林无限好。\n流落归来，到了心情少。\n坐到黄昏人悄悄。\n更应添得朱颜老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1446, '蓦山溪', '陈济翁', '去年今日，从驾游西苑。\n彩仗压金波，看水戏、鱼龙曼衍。\n宝津南殿，宴坐近天颜，金杯酒，君王劝。\n头上宫花颤。\n六军锦绣，万骑穿杨箭。\n日暮翠华归，拥钧天、笙歌一片。\n如今关外，千里未归人，前山雨，西楼晚。\n望断思君眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1447, '蓦山溪', '陈济翁', '薰风时候。\n芍药披晴昼。\n天上玉阑干，展一枰、天家锦绣。\n汉宫唐殿。\n嫔御逞妖娆，飞燕女，太真妃，一样新妆就。\n黄金拈线，色与红芳斗。\n谁把绛绡衣，误将他、胭脂渍透。\n晚风生处，襟袖卷浓香，持玉，秉纱笼，倚醉听更漏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1448, '踏青游', '陈济翁', '濯锦江头，羞杀艳桃李。\n纵赵昌、丹青难比。\n晕轻红，留浅素，千娇百媚。\n照绿水。\n恰如下临鸾镜，妃子弄妆犹醉。\n诗笔因循，不晓少陵深意。\n但满眼、伤春珠泪。\n燕来时，莺啼处，年年憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1449, '水龙吟', '苏轼', '古来云海茫茫，道山绛阙知何处。\n人间自有，赤城居士，龙蟠凤举。\n清净无为，坐忘遗照，八篇奇语。\n向玉霄东望，蓬莱暗霭，有云驾、骖风驭。\n行尽九州四海，笑纷纷、落花飞絮。\n临江一见，谪仙风采，无言心许。\n八表神游，浩然相对，酒酣箕踞。\n待垂天赋就，骑鲸路稳，约相将去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1450, '水龙吟', '苏轼', '楚山修竹如云，异材秀出千林表。\n龙须半翦，凤膺微涨，玉肌匀绕。\n木落淮南，雨晴云梦，月明风袅。\n自中郎不见，桓伊去後，知孤负、秋多少。\n闻道岭南太守，後堂深、绿珠娇小。\n绮窗学弄，梁州初遍，霓裳未了。\n嚼徵含宫，泛商流羽，一声云杪。\n为使君洗尽，蛮风瘴雨，作霜天晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1451, '水龙吟', '苏轼', '似花还似非花，也无人惜从教坠。\n抛家傍路，思量却是，无情有思。\n萦损柔肠，困酣娇眼，欲开还闭。\n梦随风万里，寻郎去处，又还被、莺呼起。\n不恨此花飞尽，恨西园、落红难缀。\n晓来雨过，遗踪何在，一池萍碎。\n春色三分，二分尘土，一分流水。\n细看来，不是杨花点点，是离人泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1452, '水龙吟', '苏轼', '小舟横截春江，卧看翠壁红楼起。\n云间笑语，使君高会，佳人半醉。\n危柱哀弦，艳歌馀响，绕云萦水。\n念故人老大，风流未减，独回首、烟波里。\n推枕惘然不见，但空江、月明千里。\n五湖闻道，扁舟归去，仍携西子。\n云梦南州，武昌南岸，昔游应记。\n料多情梦里，端来见我，也参差是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1453, '满庭芳', '苏轼', '归去来兮，吾归何处，万里家在岷峨。\n百年强半，来日苦无多。\n坐见黄州再闰，儿童尽、楚语吴歌。\n山中友，鸡豚社酒，相劝老东坡。\n云何。\n当此去，人生底事，来往如梭。\n待闲看，秋风洛水清波。\n好在堂前细柳，应念我、莫翦柔柯。\n仍传语，江南父老，时与晒渔蓑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1454, '满庭芳', '苏轼', '香雕盘，寒生冰箸，画堂别是风光。\n主人情重，开宴出红妆。\n腻玉圆搓素颈，藕丝嫩、新织仙裳。\n双歌罢，虚檐转月，馀韵尚悠扬。\n人间，何处有，司空见惯，应谓寻常。\n坐中有狂客，恼乱愁肠。\n报道金钗坠也，十指露、春笋纤长。\n亲曾见，全胜宋玉，想像赋高唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1455, '满庭芳', '苏轼', '蜗角虚名，蝇头微利，算来著甚乾忙。\n事皆前定，谁弱又谁强。\n且趁闲身未老，尽放我、些子疏狂。\n百年里，浑教是醉，三万六千场。\n思量。\n能几许，忧愁风雨，一半相妨。\n又何须，抵死说短论长。\n幸对清风皓月，苔茵展、云幕高张。\n江南好，千锺美酒，一曲满庭芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1456, '满庭芳', '苏轼', '三十三年，今谁存者，算只君与长江。\n凛然苍桧，霜干苦难双。\n闻道司州古县，云溪上、竹坞松窗。\n江南岸，不因送子，宁肯过吾邦。\n。\n疏雨过，风林舞破，烟盖云幢。\n愿持此邀君，一饮空缸。\n居士先生老矣，真梦里、相对残。\n歌舞断，行人未起，船鼓已逄逄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1457, '满庭芳', '苏轼', '三十三年，飘流江海，万里烟浪云帆。\n故人惊怪，憔悴老青衫。\n我自疏狂异趣，君何事、奔走尘凡。\n流年尽，穷途坐守，船尾冻相衔。\n。\n淮浦外，层楼翠壁，古寺空岩。\n步携手林间，笑挽ホホ。\n莫上孤峰尽处，萦望眼、云海相搀。\n家何在，因君问我，归梦绕松杉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1458, '水调歌头', '苏轼', '落日绣帘卷，亭下水连空。\n知君为我，新作窗户湿青红。\n长记平山堂上，枕江南烟雨，渺渺没孤鸿。\n认得醉翁语，山色有无中。\n一千顷，都镜净，倒碧峰。\n忽然浪起，掀舞一叶白头翁。\n堪笑兰台公子，未解庄生天籁，刚道有雌雄。\n一点浩然气，千里快哉风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1459, '水调歌头', '苏轼', '安石在东海，从事鬓惊秋。\n中年亲友难别，丝竹缓离愁。\n一旦功成名遂，准拟东还海道，扶病入西州。\n雅志困轩冕，遗恨寄沧洲。\n岁云暮，须早计，要褐裘。\n故乡归去千里，佳处辄迟留。\n我醉歌时君和，醉倒须君扶我，惟酒可忘忧。\n一任刘玄德，相对卧高楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1460, '水调歌头', '苏轼', '明月几时有，把酒问青天。\n不知天上宫阙，今夕是何年。\n我欲乘风归去，又恐琼楼玉宇，高处不胜寒。\n起舞弄清影，何似在人间。\n转朱阁，低绮户，照无眠。\n不应有恨，何事长向别时圆。\n人有悲欢离合，月有阴晴圆缺，此事古难全。\n但愿人长久，千里共婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1461, '水调歌头', '苏轼', '昵昵儿女语，灯火夜微明。\n恩冤尔汝来去，弹指泪和声。\n忽变轩昂勇士，一鼓填然作气，千里不留行。\n回首暮云远，飞絮搅青冥。\n众禽里，真彩凤，独不鸣。\n跻攀寸步千险，一落百寻轻。\n烦子指间风雨，置我肠中冰炭，起坐不能平。\n推手从归去，无泪与君倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1462, '满江红', '苏轼', '忧喜相寻，风雨过、一江春绿。\n巫峡梦、至今空有，乱山屏簇。\n何似伯鸾携德耀，箪瓢未足清欢足。\n渐粲然、光彩照阶庭，生兰玉。\n幽梦里，传心曲。\n肠断处，凭他续。\n文君婿知否，笑君卑辱。\n君不见周南歌汉广，天教夫子休乔木。\n便相将、左手抱琴书，云间宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1463, '满江红', '苏轼', '江汉西来，高楼下、蒲萄深碧。\n犹自带、岷峨云浪，锦江春色。\n君是南山遗爱守，我为剑外思归客。\n对此间、风物岂无情，殷勤说。\n江表传，君休读。\n狂处士，真堪惜。\n空洲对鹦鹉，苇花萧瑟。\n不独笑书生争底事，曹公黄祖俱飘忽。\n愿使君、还赋谪仙诗，追黄鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1464, '满江红', '苏轼', '东武南城，新堤固、涟漪初溢。\n隐隐遍、长林高阜，卧红堆碧。\n枝上残花吹尽也，与君更向江头觅。\n问向前、犹有几多春，三之一。\n官里事，何时毕。\n风雨外，无多日。\n相将泛曲水，满城争出。\n君不见兰亭修禊事，当时坐上皆豪逸。\n到如今、修竹满山阴，空陈迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1465, '满江红', '苏轼', '清颖东流，愁目断、孤帆明灭。\n宦游处、青山白浪，万重千叠。\n孤负当年林下意，对床夜雨听萧瑟。\n恨此生、长向别离中，添华发。\n一尊酒，黄河侧。\n无限事，从头说。\n相看恍如昨，许多年月。\n衣上旧痕馀苦泪，眉间喜气添黄色。\n便与君、池上觅残春，花如雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1466, '满江红', '苏轼', '天岂无情，天也解、多情留客。\n春向暖、朝来底事，尚飘轻雪。\n君过春来纡组绶，我应归去耽泉石。\n恐异时、杯酒忽相思，云山隔。\n浮世事，俱难必。\n人纵健，头应白。\n何辞更一醉，此欢难觅。\n欲向佳人诉离恨，泪珠先已凝双睫。\n但莫遣、新燕却来时，音书绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1467, '归朝欢', '苏轼', '我梦扁舟浮震泽。\n雪浪摇空千顷白。\n觉来满眼是庐山，倚天无数开青壁。\n此生长接淅。\n与君同是江南客。\n梦中游，觉来清赏，同作飞梭掷。\n明日西风还挂席。\n唱我新词泪沾臆。\n灵均去後楚山空，澧阳兰芷无颜色。\n君才如梦得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1468, '念奴娇', '苏轼', '大江东去，浪淘尽、千古风流人物。\n故垒西边人道是，三国周郎赤壁。\n乱石穿空，惊涛拍岸，卷起千堆雪。\n江山如画，一时多少豪杰。\n遥想公瑾当年，小乔初嫁了，雄姿英发。\n羽扇纶巾谈笑间，强虏灰飞烟灭。\n故国神游，多情应笑，我早生华发。\n人间如梦，一尊还酹江月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1469, '雨中花・夜行船', '苏轼', '今岁花时深院，尽日东风，荡扬茶烟。\n但有绿苔芳草，柳絮榆钱。\n闻道城西，长廊古寺，甲第名园。\n有国艳带酒，天香染袂，为我留连。\n清明过了，残红无处，对此泪洒尊前。\n秋向晚，一枝何事，向我依然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1470, '沁园春', '苏轼', '孤馆灯青，野店鸡号，旅枕梦残。\n渐月华收练，晨霜耿耿，云山锦，朝露清清。\n世路无穷，劳生有限，似此区区长鲜欢。\n微吟罢，凭征鞍无语，往事千端。\n当时共客长安。\n似二陆初来俱少年。\n有笔头千字，胸中万卷，致君尧舜，此事何难。\n用舍由时，行藏在我，袖手何妨闲处看。\n身长健，但优游卒岁，且斗尊前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1471, '劝金船', '苏轼', '无情流水多情客。\n劝我如曾识。\n杯行到手休辞却。\n这公道难得。\n曲水池上，小字更书年月。\n还对茂林修竹，似永和节。\n纤纤素手如霜雪。\n笑把秋花插。\n尊前莫怪歌声咽。\n又还是轻别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1472, '一丛花', '苏轼', '今年春浅腊侵年。\n冰雪破春妍。\n东风有信无人见，露微意、柳际花边。\n寒夜纵长，孤衾易暖，钟鼓渐清圆。\n朝来初日半含山。\n楼阁淡疏烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1473, '木兰花令', '苏轼', '霜馀已失长淮阔。\n空听潺潺清颍咽。\n佳人犹唱醉翁词，四十三年如电抹。\n草头秋露流珠滑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1474, '木兰花令', '苏轼', '知君仙骨无寒暑。\n千载相逢犹旦暮。\n故将别语恼佳人，要看梨花枝上雨。\n落花已逐回风去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1475, '木兰花令', '苏轼', '梧桐叶上三更雨。\n惊破梦魂无觅处。\n夜凉枕簟已知秋，更听寒蛩促机杼。\n梦中历历来时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1476, '西江月', '苏轼', '公子眼花乱发，老夫鼻观先通。\n领巾飘下瑞香风。\n惊起谪仙春梦。\n后土祠中玉蕊，蓬莱殿後红。\n此花清绝更纤。\n把酒何人心动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1477, '西江月', '苏轼', '小院朱阑几曲，重城画鼓三通。\n更看微月转光风。\n归去香云入梦。\n翠袖争浮大白，皂罗半插斜红。\n灯花零落酒花。\n妙语一时飞动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1478, '西江月', '苏轼', '怪此花枝怨泣，托君诗句名通。\n凭将草木记吴风。\n继取相如云梦。\n点笔袖沾醉墨，谤花面有惭红。\n知君却是为情。\n怕见此花撩动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1479, '西江月', '苏轼', '闻道双衔凤带，不妨单著鲛绡。\n夜香知与阿谁烧。\n怅望水沈烟袅。\n云鬓风前绿卷，玉颜醉里红潮。\n莫教空度可怜宵。\n月与佳人共僚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1480, '西江月', '苏轼', '点点楼头细雨。\n重重江外平湖。\n当年戏马会东徐。\n今日凄凉南浦。\n莫恨黄花未吐。\n且教红粉相扶。\n酒阑不必看茱萸。\n俯仰人间今古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1481, '西江月', '苏轼', '龙焙今年绝品，谷帘自古珍泉。\n雪芽双井散神仙。\n苗裔来从北苑。\n汤发云腴酽白，盏浮花乳轻圆。\n人间谁敢更争妍。\n斗取红窗粉面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1482, '西江月', '苏轼', '别梦已随流水，泪巾犹香泉。\n相如依旧是仙。\n人在瑶台阆苑。\n花雾萦风缥缈，歌珠滴水清圆。\n蛾眉新作十分妍。\n走马归来便面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1483, '西江月', '苏轼', '世事一场大梦，人生几度秋凉。\n夜来风叶已鸣廊。\n看取眉头鬓上。\n酒贱常愁客少，月明多被云妨。\n中秋谁与共孤光。\n把盏凄然北望。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1484, '西江月', '苏轼', '莫叹平原落落，且应去鲁迟迟。\n与君各记少年时。\n须信人生如寄。\n白发千茎相送，深杯百罚休辞。\n拍浮何用酒为池。\n我已为君德醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1485, '西江月', '苏轼', '玉骨那愁瘴雾，冰姿自有仙风。\n海仙时遣探芳丛。\n倒挂绿毛么凤。\n素面翻嫌粉，洗妆不褪唇红。\n高情已逐晓云空。\n不与梨花同梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1486, '西江月', '苏轼', '照野弥弥浅浪，横空暧暧微霄。\n障泥未解玉骢骄。\n我欲醉眠芳草。\n可惜一溪明月，莫教踏破琼瑶。\n解鞍枕绿杨桥。\n杜宇一声春晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1487, '西江月', '苏轼', '三过平山堂下，半生弹指声中。\n十年不见老仙翁。\n壁上龙蛇飞动。\n欲吊文章太守，仍歌杨柳春风。\n休言万事转头空。\n未转头时皆梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1488, '西江月', '苏轼', '昨夜扁舟京口，今朝马首长安。\n旧官何物与新官。\n只有湖山公案。\n此景百年几变，个中下语千难。\n使君才气卷波澜。\n与把新诗判断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1489, '临江仙', '苏轼', '细马远驮双侍女，青巾玉带红靴。\n溪山好处便为家。\n谁知巴峡路，却见洛城花。\n面旋落英飞玉蕊，人间春日初斜。\n十年不见紫云车。\n龙丘新洞府，铅鼎养丹砂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1490, '临江仙', '苏轼', '诗句端来磨我钝，钝锥不解生。\n欢颜为我解冰霜。\n酒阑清梦觉，春草满池塘。\n应念雪堂坡下老，昔年共采芸香。\n功成名遂早还乡。\n回车来过我，乔木拥千章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1491, '临江仙', '苏轼', '我劝髯张归去好，从来自己忘情。\n尘心消尽道心平。\n江南与塞北，何处不堪行。\n俎豆庚桑真过矣，凭君说与南荣。\n愿闻吴越报丰登。\n君王如有问，结袜赖王生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1492, '临江仙', '苏轼', '自古相从休务日，何妨低唱微吟。\n天垂云重作春阴。\n坐中人半醉，帘外雪将深。\n闻道分司狂御史，紫云无路追寻。\n凄风寒雨是。\n问囚长损气，见鹤忽惊心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1493, '临江仙', '苏轼', '忘却成都来十载，因君未免思量。\n凭将清泪洒江阳。\n故山知好在，孤客自悲凉。\n坐上别愁君未见，归来欲断无肠。\n殷勤且更尽离觞。\n此身如传舍，何处是吾乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1494, '临江仙', '苏轼', '尊酒何人怀李白，草堂遥指江东。\n珠帘十里卷香风。\n花开又花谢，离恨几千重。\n轻舸渡江连夜到，一时惊笑衰容。\n语音犹自带吴侬。\n夜阑对酒处，依旧梦魂中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1495, '临江仙', '苏轼', '九十日春都过了，贪忙何处追游。\n三分春色一分愁。\n雨翻榆荚阵，风转柳花球。\n阆苑先生须自责，蟠桃动是千秋。\n不知人世苦厌求。\n东皇不拘束，肯为使君留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1496, '临江仙', '苏轼', '四大从来都遍满，此间风水何疑。\n故应为我发新诗。\n幽花香涧谷，寒藻舞沦漪。\n借与玉川生两腋，天仙未必相思。\n还凭流水送人归。\n层巅馀落日，草露已沾衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1497, '临江仙', '苏轼', '一别都门三改火，天涯踏尽红尘。\n依然一笑作春温。\n无波真古井，有节是秋筠。\n惆怅孤帆连夜发，送行淡月微云。\n尊前不用翠眉颦。\n人生如逆旅，我亦是行人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1498, '临江仙', '苏轼', '多病休文都瘦损，不堪金带垂腰。\n望湖楼上暗香飘。\n和风春弄袖，明月夜闻箫。\n酒醒梦回清漏永，隐床无限更潮。\n佳人不见董娇饶。\n徘徊花上月，空度可怜宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1499, '临江仙', '苏轼', '夜饮东坡醒复醉，归来仿佛三更。\n家童鼻息已雷鸣。\n敲门都不应，倚杖听江声。\n长恨此身非我有，何时忘却营营。\n夜阑风静纹平。\n小舟从此逝，江海寄馀生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1500, '临江仙', '苏轼', '冬夜夜寒冰合井，画堂明月侵帏。\n青缸明灭照悲啼。\n青缸挑欲尽，粉泪还垂。\n未尽一尊先掩泪，歌声半带清悲。\n情声两尽莫相违。\n欲知肠断处，梁上暗尘飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1501, '渔家傲', '苏轼', '千古龙蟠并虎踞。\n从公一吊兴亡处。\n渺渺斜风吹细雨。\n芳草渡。\n江南父老留公住。\n公驾飞车凌彩雾。\n红鸾骖乘青鸾驭。\n却讶此洲名白鹭。\n非吾侣。\n翩然欲下还飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1502, '渔家傲', '苏轼', '送客归来灯火尽。\n西楼淡月凉生晕。\n明日潮来无定准。\n潮来稳。\n舟横渡口重城近。\n江水似知孤客恨。\n南风为解佳人愠。\n莫学时流轻久困。\n频寄问。\n钱塘江上须忠信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1503, '渔家傲', '苏轼', '皎皎牵牛河汉女。\n盈盈临水无由语。\n望断碧云空日暮。\n无寻处。\n梦回芳草生春浦。\n鸟散馀花纷似雨。\n汀洲苹老香风度。\n明月多情来照户。\n但揽取。\n清光长送人归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1504, '渔家傲', '苏轼', '一曲阳关情几许。\n知君欲向秦川去。\n白马皂貂留不住。\n回首处。\n孤城不见天霖雾。\n到日长安花似雨。\n故关杨柳初飞絮。\n渐见靴刀迎夹路。\n谁得似。\n风流膝上王文度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1505, '鹧鸪天', '苏轼', '林断山明竹隐墙。\n乱蝉衰草小池塘。\n翻空白鸟时时见，照水红蕖细细香。\n村舍外，古城旁。\n杖藜徐步转斜阳。\n殷勤昨夜三更雨，又得浮生一日凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1506, '鹧鸪天', '苏轼', '笑拈红梅翠翘。\n扬州十里最妖饶。\n夜来绮席亲曾见，撮得精神滴滴娇。\n娇後眼，舞时腰。\n刘郎几度欲魂消。\n明朝酒醒知何处，肠断云间紫玉箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1507, '少年游', '苏轼', '银塘朱槛曲尘波。\n圆绿卷新荷。\n兰条荐浴，菖花酿酒，天气尚清和。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1508, '少年游', '苏轼', '去年相送，馀杭门外，飞雪似杨花。\n今年春尽，杨花似雪，犹不见还家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1509, '定风波', '苏轼', '两两轻红半晕腮。\n依依独为使君回。\n若道使君无此意。\n何为。\n双花不向别人开。\n但看低昂烟雨里。\n不已。\n劝君休诉十分杯。\n更问尊前狂副使。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1510, '定风波', '苏轼', '莫听穿林打叶声。\n何妨吟啸且徐行。\n竹杖芒鞋轻胜马。\n谁怕。\n一蓑烟雨任平生。\n料峭春风吹酒醒。\n微冷。\n山头斜照却相迎。\n回首向来萧瑟处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1511, '定风波', '苏轼', '与客携壶上翠微。\n江涵秋影雁初飞。\n尘世难逢开口笑。\n年少。\n菊花须插满头归。\n酩酊但酬佳节了。\n云峤。\n登临不用怨斜晖。\n古往今来谁不老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1512, '定风波', '苏轼', '莫怪鸳鸯绣带长。\n腰轻不胜舞衣裳。\n薄只贪游冶去。\n何处。\n垂杨系马恣轻狂。\n花谢絮飞春又尽。\n堪恨。\n断弦尘管伴啼妆。\n不信归来但自看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1513, '定风波', '苏轼', '千古风流阮步兵。\n平生游宦爱东平。\n千里远来还不住。\n归去。\n空留风韵照人清。\n红粉尊前深懊恼。\n休道。\n怎生留得许多情。\n记得明年花絮乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1514, '定风波', '苏轼', '雨洗娟娟嫩叶光。\n风吹细细绿筠香。\n秀色乱侵书帙晚。\n帘卷。\n清阴微过酒尊凉。\n人画竹身肥拥肿。\n何用。\n先生落笔胜萧郎。\n记得小轩岑寂夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1515, '定风波', '苏轼', '好睡慵开莫厌迟。\n自怜冰脸不时宜。\n偶作小红桃杏色，闲雅，尚馀孤瘦雪霜姿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1516, '定风波', '苏轼', '月满苕溪照夜堂。\n五星一老斗光芒。\n十五年间真梦里。\n何事。\n长庚对月独凄凉。\n绿鬓苍颜同一醉。\n还是。\n六人吟笑水云乡。\n宾主谈锋谁得似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1517, '定风波', '苏轼', '常羡人间琢玉郎。\n天应乞与点酥娘。\n尽道清歌传皓齿。\n风起。\n雪飞炎海变清凉。\n万里归来颜愈少。\n微笑。\n笑时犹带岭梅香。\n试问岭南应不好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1518, '南乡子', '苏轼', '晚景落琼杯。\n照眼云山翠作堆。\n认得岷峨春雪浪，初来。\n万顷蒲萄涨渌醅。\n暮雨暗阳台。\n乱洒高楼湿粉腮。\n一阵东风来卷地，吹回。\n落照江天一半开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1519, '南乡子', '苏轼', '寒雀满疏篱。\n争抱寒柯看玉蕤。\n忽见客来花下坐，惊飞。\n蹋散芳英落酒卮。\n痛饮又能诗。\n坐客无毡醉不知。\n花尽酒阑春到也，离离。\n一点微酸已著枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1520, '南乡子', '苏轼', '不到谢公台。\n明月清风好在哉。\n旧日髯孙何处去，重来。\n短李风流更上才。\n秋色渐摧颓。\n满院黄英映酒杯。\n看取桃花春二月，争开。\n尽是刘郎去後栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1521, '少年游', '苏轼', '霜降水痕收。\n浅碧鳞鳞露远洲。\n酒力渐消风力软，飕飕。\n破帽多情却恋头。\n佳节若为酬。\n但把清尊断送秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1522, '南乡子', '苏轼', '回首乱山横。\n不见居人只见城。\n谁似临平山上塔，亭亭。\n迎客西来送客行。\n归路晚风清。\n一枕初寒梦不成。\n今夜残灯斜照处，荧荧。\n秋雨晴时泪不晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1523, '南乡子', '苏轼', '冰雪透香肌。\n姑射仙人不似伊。\n濯锦江头新样锦，非宜。\n故著寻常淡薄衣。\n暖日下重帏。\n春睡香凝索起迟。\n曼倩风流缘底事，当时。\n爱被西真唤作儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1524, '南乡子', '苏轼', '东武望馀杭。\n云海天涯两杳茫。\n何日功成名遂了，还乡。\n醉笑陪公三万场。\n不用诉离觞。\n痛饮从来别有肠。\n今夜送归灯火冷，河塘。\n堕泪羊公却姓杨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1525, '南乡子', '苏轼', '凉簟碧纱厨。\n一枕清风昼睡馀。\n睡听晚衙无一事，徐徐。\n读尽床头几卷书。\n搔首赋归欤。\n自觉功名懒更疏。\n若问使君才与术，何如。\n占得人间一味愚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1526, '南乡子', '苏轼', '裙带石榴红。\n却水殷勤解赠侬。\n应许逐鸡鸡莫怕，相逢。\n一点灵犀必暗通。\n何处遇良工。\n琢刻天真半欲空。\n愿作龙香双凤拨，轻拢。\n长在环儿白雪胸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1527, '南乡子', '苏轼', '旌旆满江湖。\n诏发楼船万舳舻。\n投笔将军因笑我，迂儒。\n帕首腰刀是丈夫。\n粉泪怨离居。\n喜子垂窗报捷书。\n试问伏波三万语，何如。\n一斛明珠换绿珠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1528, '南乡子', '苏轼', '天与化工知。\n赐得衣裳总是绯。\n每向华堂深处见，怜伊。\n两个心肠一片儿。\n自小便相随。\n绮席歌筵不暂离。\n苦恨人人分拆破，东西。\n怎得成双似旧时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1529, '南乡子', '苏轼', '寒玉细凝肤。\n清歌一曲倒金壶。\n冶叶倡条遍相识，争如。\n豆蔻花梢二月初。\n年少即须臾。\n芳时偷得醉工夫。\n罗帐细垂银烛背，欢娱。\n豁得平生俊气无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1530, '南乡子', '苏轼', '怅望送春杯。\n渐老逢春能几回。\n花满楚城愁远别，伤怀。\n何况清丝急管催。\n吟断望乡台。\n万里归心独上来。\n景物登临闲始见，徘徊。\n一寸相思一寸灰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1531, '南乡子', '苏轼', '何处倚阑干。\n弦管高楼月正圆。\n胡蝶梦中家万里，依然。\n老去愁来强自宽。\n明镜借红颜。\n须著人间比梦间。\n蜡烛半笼金翡翠，更阑。\n绣被焚香独自眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1532, '南歌子', '苏轼', '山与歌眉敛，波同醉眼流。\n游人都上十三楼。\n不羡竹西歌吹、古扬州。\n菰黍连昌，琼彝倒玉舟。\n谁家水调唱歌头。\n声绕碧山飞去、晚云留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1533, '南歌子', '苏轼', '古岸开青葑，新渠走碧流。\n会看光满万家楼。\n记取他年扶路、入西州。\n佳节连梅雨，馀生寄叶舟。\n只将菱角与鸡头。\n更有月明千顷、一时留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1534, '南乡子', '苏轼', '雨暗初疑夜，风回忽报晴。\n淡云斜照著山明。\n细草软沙溪路、马蹄轻。\n卯酒醒还困，仙材梦不成。\n蓝桥何处觅云英。\n只有多情流水、伴人行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1535, '南歌子', '苏轼', '日出西山雨，无晴又有晴。\n乱山深处过清明。\n不见彩绳花板、细腰轻。\n尽日行桑野，无人与目成。\n且将新句琢琼英。\n我是世间闲客、此闲行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1536, '南歌子', '苏轼', '带酒冲山雨，和衣睡晚晴。\n不知钟鼓报天明。\n梦里栩然蝴蝶、一身轻。\n老去才都尽，归来计未成。\n求田问舍笑豪英。\n自爱湖边沙路、免泥行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1537, '南歌子', '苏轼', '日薄花房绽，风和麦浪轻。\n夜来微雨洗郊。\n正是一年春好、近清明。\n已改煎茶火，犹调入粥饧。\n使君高会有馀清。\n此乐无声无味、最难名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1538, '南歌子', '苏轼', '海上乘槎侣，仙人萼绿华。\n飞升元不用丹砂。\n住在潮头来处、渺天涯。\n雷辊夫差国，云翻海若家。\n坐中安得弄琴牙。\n写取馀声归向、水仙夸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1539, '南歌子', '苏轼', '苒苒中秋过，萧萧两鬓华。\n寓身化世一尘沙。\n笑看潮来潮去、了生涯。\n方士三山路，渔人一叶家。\n早知身世两聱牙。\n好伴骑鲸公子、赋雄夸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1540, '南歌子', '苏轼', '师唱谁家曲，宗风嗣阿谁。\n借君拍板与门槌。\n我也逢场作戏、莫相疑。\n溪女方偷眼，山僧莫眨眉。\n却愁弥勒下生迟。\n不见老婆三五、少年时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1541, '南歌子', '苏轼', '欲执河梁手，还升月旦堂。\n酒阑人散月侵廊。\n北客明朝归去、雁南翔。\n窈窕高明玉，风流郑季庄。\n一时分散水云乡。\n惟有落花芳草、断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1542, '南歌子', '苏轼', '山雨潇潇过，溪桥浏浏清。\n小园幽榭枕苹汀。\n门外月华如水、彩舟横。\n苕岸霜花尽，江湖雪阵平。\n两山遥指海门青。\n回首水云何处、觅孤城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1543, '南歌子', '苏轼', '紫陌寻春去，红尘拂面来。\n无人不道看花回。\n惟见石榴新蕊、一枝开。\n冰簟堆云髻，金尊滟玉醅。\n绿阴青子莫相催。\n留取红巾千点、照池台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1544, '南歌子', '苏轼', '卫霍元勋後，韦平外族贤。\n吹笙只合在缑山。\n闲驾彩峦归去、趁新年。\n烘暖烧香阁，轻寒浴佛天。\n他时一醉画堂前。\n莫忘故人憔悴、老江边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1545, '南歌子', '苏轼', '笑怕蔷薇，行忧宝瑟僵。\n美人依约在西厢。\n祗恐暗中迷路、认馀香。\n午夜风翻幔，三更月到床。\n簟纹如水玉肌凉。\n何物与侬归去、有残妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1546, '南歌子', '苏轼', '寸恨谁云短，绵绵岂易裁。\n半年眉绿未曾开。\n明月好风闲处、是人猜。\n春雨消残冻，温风到冷灰。\n尊前一曲为谁哉。\n留取曲终一拍、待君来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1547, '南歌子', '苏轼', '绀绾双蟠髻，云小偃巾。\n轻盈红脸小腰身。\n叠鼓忽催花拍、斗精神。\n空阔轻红歇，风和约柳春。\n蓬山才调最清新。\n胜似缠头千锦、共藏珍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1548, '南歌子', '苏轼', '琥珀装腰佩，龙香入领巾。\n只应飞燕是前身。\n共看剥葱纤手、舞凝神。\n柳絮风前转，梅花雪里春。\n鸳鸯翡翠两争新。\n但得周郎一顾、胜珠珍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1549, '好事近', '苏轼', '红粉莫悲啼，俯仰半年离别。\n看取雪堂坡下，老农夫凄切。\n明年春水漾桃花，柳岸隘舟楫。\n从此满城歌吹，看黄州阗咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1550, '好事近', '苏轼', '湖上雨晴时，秋水半篙初没。\n朱槛俯窥寒鉴，照衰颜华发。\n醉中吹堕白纶巾，溪风漾流月。\n独棹小舟归去，任烟波飘兀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1551, '鹊桥仙', '苏轼', '缑山仙子，高情云渺，不学痴牛呆女。\n凤箫声断月明中，举手谢、时人欲去。\n客槎曾犯，银河微浪，尚带天风海雨。\n相逢一醉是前缘，风雨散、飘然何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1552, '鹊桥仙', '苏轼', '乘槎归去，成都何在，万里江沱汉漾。\n与君各赋一篇诗，留织女、鸳鸯机上。\n还将旧曲，重赓新韵，须信吾侪天放。\n人生何处不儿嬉，看乞巧、朱楼彩舫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1553, '望江南・忆江南', '苏轼', '春已老，春服几时成。\n曲水浪低蕉叶稳，舞雩风软罗轻。\n酣咏乐升平。\n微雨过，何处不催耕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1554, '望江南・忆江南', '苏轼', '春未老，风细柳斜斜。\n试上超然台上看，半壕春水一城花。\n烟雨暗千家。\n寒食後，酒醒却咨嗟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1555, '卜算子', '苏轼', '蜀客到江南，长忆吴山好。\n吴蜀风流自古同，归去应须早。\n还与去年人，共藉西湖草。\n莫惜尊前仔细看，应是容颜老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1556, '卜算子', '苏轼', '缺月挂疏桐，漏断人初静。\n时见幽人独往来，缥缈孤鸿影。\n惊起却回头，有恨无人省。\n拣尽寒枝不肯栖，枫落吴江冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1557, '瑞鹧鸪', '苏轼', '碧山影里小红旗。\n侬是江南踏浪儿。\n拍手欲嘲山简醉，齐声争唱浪婆词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1558, '十拍子・破阵子', '苏轼', '白酒新开九酝，黄花已过重阳。\n身外傥来都似梦，醉里无何即是乡。\n东坡日月长。\n玉粉旋烹茶乳，金齑新捣橙香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1559, '清平乐', '苏轼', '清淮蜀汴。\n更在江西岸。\n红旆到时黄叶乱。\n霜入梁王故苑。\n秋原何处携壶。\n停骖访古踟蹰。\n双庙遗风尚在，漆园傲吏应无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1560, '昭君怨', '苏轼', '谁作桓伊三弄。\n惊破绿窗幽梦。\n新月与愁烟。\n满江天。\n欲去又还不去。\n明日落花飞絮。\n飞絮送行舟。\n水东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1561, '戚氏', '苏轼', '玉龟山。\n东皇灵媲统群仙。\n绛阙，翠房深迥，倚霏烟。\n幽闲。\n志萧然。\n金城千里锁婵娟。\n当时穆满巡狩。\n翠华曾到海西边。\n风露明霁，鲸波极目，势浮舆盖方圆。\n正迢迢丽日。\n玄圃清寂，琼草芊绵。\n争解绣勒香鞯。\n鸾辂驻跸，八马戏芝田。\n瑶池近、画楼隐隐，翠鸟翩翩。\n肆华筵。\n间作脆管鸣弦。\n宛若帝所钧天。\n稚颜皓齿，绿发方瞳，圆极恬淡高妍。\n尽倒琼壶酒，献金鼎药，固大椿年。\n缥缈飞琼妙舞，命双成、奏曲醉留连。\n云韵响泻寒泉。\n浩歌畅饮，斜月低河汉。\n渐渐绮霞、天际红深浅。\n动归思、回首尘寰。\n烂漫游、玉辇东还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1562, '醉蓬莱', '苏轼', '笑劳生一梦，羁旅三年，又还重九。\n华发萧萧，对荒园搔首。\n赖有多情，好饮无事，似古人贤守。\n岁岁登高，年年落帽，物华依旧。\n此会应须烂醉，仍把紫菊茱萸，细看重嗅。\n摇落霜风，有手栽双柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1563, '贺新郎', '苏轼', '乳燕飞华屋。\n悄无人、桐阴转午，晚凉新浴。\n手弄生绡白团扇，扇手一时似玉。\n渐困倚、孤眠清熟。\n帘外谁来推绣户，枉教人、梦断瑶台曲。\n又却是，风敲竹。\n石榴半吐红巾蹙。\n待浮花、浪蕊都尽，伴君幽独。\n艳一枝细看取，芳心千重似束。\n又恐被、秋风惊绿。\n若待得君来向此，花前对酒不忍触。\n共粉泪，两蔌蔌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1564, '洞仙歌', '苏轼', '江南腊尽，早梅花开後。\n分付新春与垂柳。\n细腰肢、自有入格风流，仍更是、骨体清英雅秀。\n永丰坊那畔，尽日无人，惟见金丝弄晴昼。\n断肠是，飞絮时，绿叶成阴，无个事、一成消瘦。\n又莫是、东风逐君来，便吹散眉间，一点春皱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1565, '洞仙歌', '苏轼', '冰肌玉骨，自清凉无汗。\n水殿风来暗香满。\n绣帘开、一点明月窥人，人未寝、枕钗横鬓乱。\n起来携素手，庭户无声，时见疏星渡河汉。\n试问夜如何，夜已三更，金波淡、玉绳低转。\n但屈指、西风几时来，又不道、流年暗中偷换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1566, '八声甘州', '苏轼', '有情风、万里卷潮来，无情送潮归。\n问钱塘江上，西兴浦口，几度斜晖。\n不用思量今古，俯仰昔人非。\n谁似东坡老，白首忘机。\n记取西湖西畔，正暮山好处，空翠烟霏。\n算诗人相得，如我与君稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1567, '三部乐', '苏轼', '美人如月。\n乍见掩暮云，更增妍绝。\n算应无恨，安用阴晴圆缺。\n娇甚空只成愁，待下床又懒，未语先咽。\n数日不来，落尽一庭红叶。\n今朝置酒强起，问为谁减动，一分香雪。\n何事散花却病，维摩无疾。\n却低眉、惨然不答。\n唱金缕、一声怨切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1568, '阮郎归', '苏轼', '绿槐高柳咽新蝉。\n薰风初入弦。\n碧纱窗下水沈烟。\n棋声惊昼眠。\n微雨过，小荷翻。\n榴花开欲然。\n玉盆纤手弄清泉。\n琼珠碎却圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1569, '阮郎归', '苏轼', '暗香浮动月黄昏。\n堂前一树春。\n东风何事入西邻。\n儿家常闭门。\n雪肌冷，玉容真。\n香腮粉未匀。\n折花欲寄岭头人。\n江南日暮云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1570, '阮郎归', '苏轼', '一年三度过苏台。\n清尊长是开。\n佳人相问苦相猜。\n这回来不来。\n情未尽，老先催。\n人生真可，他年桃李阿谁栽。\n刘郎双鬓衰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1571, '江神子・江城子', '苏轼', '梦中了了醉中醒。\n只渊明。\n是前生。\n走遍人间，依旧却躬耕。\n昨夜东坡春雨足，乌鹊喜，报新晴。\n雪堂西畔暗泉鸣。\n北山倾。\n小溪横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1572, '江神子・江城子', '苏轼', '翠蛾羞黛怯人看。\n掩霜纨。\n泪偷弹。\n且尽一尊，收泪唱阳关。\n漫道帝城天样远，天易见，见君难。\n画堂新拘近孤山。\n曲阑干。\n为谁安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1573, '江神子・江城子', '苏轼', '凤凰山下雨初晴。\n水风清。\n晚霞明。\n一朵芙蕖，开过尚盈盈。\n何处飞来双白鹭，如有意，慕娉婷。\n忽闻江上弄哀筝。\n苦含情，遣谁听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1574, '江神子・江城子', '苏轼', '老夫聊发少年狂。\n左牵黄。\n右擎苍。\n锦帽貂裘，千骑卷平冈。\n为报倾城随太守，亲射虎，看孙郎。\n酒酣胸胆尚开张。\n鬓微霜。\n又何妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1575, '江神子・江城子', '苏轼', '天涯流落思无穷。\n既相逢。\n却匆匆。\n携手佳人，和泪折残红。\n为问东风馀几许，春纵在，与谁同。\n隋堤三月水溶溶。\n背归鸿。\n去吴中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1576, '江神子・江城子', '苏轼', '相逢不觉又初寒。\n对尊前。\n惜流年。\n风紧离亭，冰结泪珠圆。\n雪意留君君不住，从此去，少清欢。\n转头山下转头看。\n路漫漫。\n玉花翻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1577, '江神子・江城子', '苏轼', '黄昏犹是雨纤纤。\n晓开帘。\n欲平檐。\n江阔天低，无处认青帘。\n孤坐冻吟谁伴我，揩病目，拈衰髯。\n使君留客醉厌厌。\n水晶盐。\n为谁甜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1578, '江神子・江城子', '苏轼', '玉人家在凤凰山。\n水云间。\n掩门关。\n门外行人，立马看弓弯。\n十里春风谁指似，斜日映，绣帘斑。\n多情好事与君还。\n闵新鳏。\n拭馀潸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1579, '江神子・江城子', '苏轼', '十年生死两茫茫。\n不思量。\n自难忘。\n千里孤坟，无处话凄凉。\n纵使相逢应不识，尘满面，鬓如霜。\n夜来幽梦忽还乡。\n小轩窗。\n正梳妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1580, '蝶恋花', '苏轼', '花褪残红青杏小。\n燕子飞时，绿水人家绕。\n枝上柳绵吹又少。\n天涯何处无芳草。\n墙里秋千墙外道。\n墙外行人，墙里佳人笑。\n笑渐不闻声渐悄。\n多情却被无情恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1581, '蝶恋花', '苏轼', '一颗樱桃樊素口。\n不爱黄金，只爱人长久。\n学画鸦儿犹未就。\n眉间已作伤春皱。\n扑蝶西园随伴走。\n花落花开，渐解相思瘦。\n破镜重圆人在否。\n章台折尽青青柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1582, '蝶恋花', '苏轼', '雨後春容清更丽。\n只有离人，幽恨终难洗。\n北固山前三面水。\n碧琼梳拥青螺髻。\n一纸乡书来万里。\n问我何年，真个成归计。\n白首送春拼一醉。\n东风吹破千行泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1583, '蝶恋花', '苏轼', '簌簌无风花自。\n寂寞园林，柳老樱桃过。\n落日多情还照坐。\n山青一点横云破。\n路尽河回千转柁。\n系缆渔村，月暗孤灯火。\n凭仗飞魂招楚些。\n我思君处君思我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1584, '蝶恋花', '苏轼', '灯火钱塘三五夜。\n明月如霜，照见人如画。\n帐底吹笙香吐麝。\n此般风味应无价。\n寂寞山城人老也。\n击鼓吹箫，乍入农桑社。\n火冷灯稀霜露下。\n昏昏雪意云垂野。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1585, '蝶恋花', '苏轼', '帘外东风交雨霰。\n帘里佳人，笑语如莺燕。\n深惜今年正月暖。\n灯光酒色摇金盏。\n掺鼓渔阳挝未遍。\n舞褪琼钗，汗湿香罗软。\n今夜何人吟古怨。\n清诗未就冰生砚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1586, '蝶恋花', '苏轼', '自古涟漪佳绝地。\n绕郭荷花，欲把吴兴比。\n倦客尘埃何处洗。\n真君堂下寒泉水。\n左海门前酤酒市。\n夜半潮来，月下孤舟起。\n倾盖相逢拼一醉。\n双凫飞去人千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1587, '蝶恋花', '苏轼', '云水萦回溪上路。\n叠叠青山，环绕溪东注。\n月白沙汀翘宿鹭。\n更无一点尘来处。\n溪叟相看私自语。\n底事区区，苦要为官去。\n尊酒不空田百亩。\n归来分得闲中趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1588, '采桑子', '苏轼', '多情多感仍多病，多景楼中。\n尊酒相逢。\n乐事回头一笑空。\n停杯且听琵琶语，细拈轻拢。\n醉脸春融。\n斜照江天一抹红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1589, '千秋岁', '苏轼', '浅霜侵绿。\n发少仍新沐。\n冠直缝，巾横幅。\n美人怜我老，玉手簪黄菊。\n秋露重，真珠落袖沾馀馥。\n坐上人如玉。\n花映花奴肉。\n蜂蝶乱，飞相逐。\n明年人纵健，此会应难复。\n须细看，晚来月上和银烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1590, '苏幕遮', '苏轼', '暑笼晴，风解愠。\n雨後馀清，暗袭衣裾润。\n一局选仙逃暑困。\n笑指尊前、谁向青霄近。\n整金盆，轮玉笋。\n凤驾鸾车，谁敢争先进。\n重五休言升最紧。\n纵有碧油，到了输堂印。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1591, '永遇乐', '苏轼', '长忆别时，景疏楼上，明月如水。\n美酒清歌，留连不住，月随人千里。\n别来三度，孤光又满，冷落共谁同醉。\n卷珠帘，凄然顾影，共伊到明无寐。\n今朝有客，来从淮上，能道使君深意。\n凭仗清淮，分明到海，中有相思泪。\n而今何在，西垣清禁，夜永露华侵被。\n此时看，回廊晓月，也应暗记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1592, '永遇乐', '苏轼', '明月如霜，好风如水，清景无限。\n曲港跳鱼，圆荷泻露，寂寞无人见。\n如三鼓，铿然一叶，黯黯梦云惊断。\n夜茫茫，重寻无处，觉来小园行遍。\n天涯倦客，山中归路，望断故园心眼。\n燕子楼空，佳人何在，空锁楼中燕。\n古今如梦，何曾梦觉，但有旧欢新怨。\n异时对，黄楼夜景，为余浩叹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1593, '行香子', '苏轼', '绮席才终。\n欢意犹浓。\n酒阑时、高兴无穷。\n共夸君赐，初拆臣封。\n看分香饼，黄金缕，密云龙。\n斗赢一水，功敌千锺。\n觉凉生、两腋清风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1594, '行香子', '苏轼', '三入承明。\n四至九卿。\n问书生、何辱何荣。\n金张七叶，纨绮貂缨。\n无汗马事，不献赋，不明经。\n成都卜肆，寂莫君平。\n郑子真、岩谷躬耕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1595, '行香子', '苏轼', '清夜无尘。\n月色如银。\n酒斟时、须满十分。\n浮名浮利，虚苦劳神。\n叹隙中驹，石中火，梦中身。\n虽抱文章，开口谁亲。\n且陶陶、乐尽天真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1596, '行香子', '苏轼', '昨夜霜风。\n先入梧桐。\n浑无处、回避衰容。\n问公何事，不语书空。\n但一回醉，一回病，一回慵。\n朝来庭下，光阴如箭，似无言、有意伤侬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1597, '行香子', '苏轼', '携手江村。\n梅雪飘裙。\n情何限、处处消魂。\n故人不见，旧曲重闻。\n向望湖楼，孤山寺，涌金门。\n寻常行处，题诗千首，绣罗衫、与拂红尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1598, '行香子', '苏轼', '一叶轻舟。\n双桨鸿惊。\n水天清、影湛波平。\n鱼翻藻鉴，鹭点烟汀。\n过沙溪急，霜溪冷，月溪明。\n重重似画，曲曲如屏。\n算当年、虚老岩陵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1599, '菩萨蛮', '苏轼', '绣帘高卷倾城出。\n灯前潋滟横波溢。\n皓齿发清歌。\n春愁入翠蛾。\n凄音休怨乱。\n我已先肠断。\n遗响下清虚。\n累累一串珠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1600, '菩萨蛮', '苏轼', '碧纱微露纤纤玉。\n朱唇渐暖参差竹。\n越调变新声。\n龙吟彻骨清。\n夜来残酒醒。\n惟觉霜袍冷。\n不见敛眉人。\n胭脂觅旧痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1601, '菩萨蛮', '苏轼', '秋风湖上萧萧雨。\n使君欲去还留住。\n今日漫留君。\n明朝愁杀人。\n佳人千点泪。\n洒向长河水。\n不用敛双蛾。\n路人啼更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1602, '菩萨蛮', '苏轼', '玉童西迓浮丘伯。\n洞天冷落秋萧瑟。\n不用许飞琼。\n瑶台空月明。\n清香凝夜宴。\n借与韦郎看。\n莫便向姑苏。\n扁舟下五湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1603, '菩萨蛮', '苏轼', '天怜豪俊腰金晚。\n故教月向松江满。\n清景为淹留。\n从君都占秋。\n身闲惟有酒。\n拭问清游首。\n帝梦已遥思。\n匆匆归去时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1604, '菩萨蛮', '苏轼', '娟娟缺月西南落。\n相思拨断琵琶索。\n枕泪梦魂中。\n觉来眉晕重。\n华堂堆烛泪。\n长笛吹新水。\n醉客各西东。\n应思陈孟公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1605, '菩萨蛮', '苏轼', '玉笙不受朱唇暖。\n离声凄咽胸填满。\n遗痕几千秋。\n恩留人不留。\n他年京国酒。\n泫泪攀枯柳。\n莫唱短因缘。\n长安远似天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1606, '菩萨蛮', '苏轼', '画檐初挂弯弯月。\n孤光未满先忧缺。\n遥认玉帘钩。\n天孙梳洗楼。\n佳人言语好。\n不顾求新巧。\n此恨固应知。\n愿人无别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1607, '菩萨蛮', '苏轼', '风回仙驭云开扇。\n更阑月堕星河转。\n枕上梦魂惊。\n晓檐疏雨零。\n相逢虽草草。\n长共天难老。\n终不羡人间。\n人间日似年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1608, '菩萨蛮', '苏轼', '城隅静女谁人见。\n先生日夜歌彤管。\n谁识蔡姬贤。\n江南顾彦先。\n先生那久困。\n汤沐须名郡。\n惟有谢夫人。\n从来见拟伦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1609, '菩萨蛮', '苏轼', '买田阳羡吾将老。\n从来只为溪山好。\n来往一虚舟。\n聊随物外游。\n有书仍懒著。\n水调歌归去。\n筋力不辞诗。\n要须风雨时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1610, '菩萨蛮', '苏轼', '落花闲院春衫薄。\n薄衫春院闲花落。\n迟日恨依依。\n依依恨日迟。\n梦回莺舌弄。\n弄舌莺回梦。\n邮便问人羞。\n羞人问便邮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1611, '菩萨蛮', '苏轼', '火云凝汗挥珠颗。\n颗珠挥汗凝云火。\n琼暖碧纱轻。\n轻纱碧暖琼。\n晕腮嫌枕印。\n印枕嫌腮晕。\n闲照晚妆残。\n残妆晚照闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1612, '菩萨蛮', '苏轼', '峤南江浅红梅小。\n小梅红浅江南峤。\n窥我向疏篱。\n篱疏向我窥。\n老人行即到。\n到即行人老。\n离别惜残枝。\n枝残惜别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1613, '菩萨蛮', '苏轼', '翠鬟斜幔云垂耳。\n耳垂云幔斜鬟翠。\n春晚睡昏昏。\n昏昏睡晚春。\n细花梨雪坠。\n坠雪梨花细。\n颦浅念谁人。\n人谁念浅颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1614, '菩萨蛮', '苏轼', '柳庭风静人眠昼。\n昼眠人静风庭柳。\n香汗薄衫凉。\n凉衫薄汗香。\n手红冰碗藕。\n藕碗冰红手。\n郎笑藕丝长。\n长丝藕笑郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1615, '菩萨蛮', '苏轼', '井桐双照新妆冷。\n冷妆新照双桐井。\n羞对井花愁。\n愁花井对羞。\n影孤怜夜永。\n永夜怜孤影。\n楼上不宜秋。\n秋宜不上楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1616, '菩萨蛮', '苏轼', '雪花飞暖融香颊。\n颊香融暖飞花雪。\n欺雪任单衣。\n衣单任雪欺。\n别时梅子结。\n结子梅时别。\n归不恨开迟。\n迟开恨不归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1617, '生查子', '苏轼', '三度别君来，此别真迟暮。\n白尽老髭须，明日淮南去。\n酒罢月随人，泪湿花如雾。\n後月逐君还，梦绕湖边路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1618, '翻香令', '苏轼', '金炉犹暖麝煤残。\n惜香更把宝钗翻。\n重闻处，馀薰在，这一番、气味胜从前。\n背人偷盖小蓬山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1619, '乌夜啼', '苏轼', '莫怪归心甚速，西湖自有蛾眉。\n若见故人须细说，白发倍当时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1620, '虞美人', '苏轼', '定场贺老今何在。\n几度新声改。\n怨声坐使旧声阑。\n俗耳只知繁手、不须弹。\n断弦拭问谁能晓。\n七岁文姬小。\n拭教弹作辊雷声。\n应有开元遗老、泪纵横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1621, '虞美人', '苏轼', '归心正似三春草。\n拭著莱衣小。\n橘怀几日向翁开。\n怀祖已文度、不归来。\n禅心已断人间爱。\n只有平交在。\n笑论瓜葛一枰同。\n看取灵光新赋、有家风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1622, '虞美人', '苏轼', '湖山信是东南美。\n一望弥千里。\n使君能得几回来。\n便使尊前醉倒、且徘徊。\n沙河塘里灯初上。\n水调谁家唱。\n夜阑风静欲归时。\n惟有一江明月、碧琉璃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1623, '虞美人', '苏轼', '波声拍枕长淮晓。\n隙月窥人小。\n无情汴水自东流。\n只载一船离恨、向西州。\n竹溪花浦曾同醉。\n酒味多於泪。\n谁教风鉴在尘埃。\n酝造一场烦恼、送人来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1624, '河满子', '苏轼', '见说岷峨凄怆，旋闻江汉澄清。\n但觉秋来归梦好，西南自有长城。\n东府三人最少，西山八国初平。\n莫负花溪纵赏，何妨药市微行。\n拭问当垆人在否，空教是处闻名。\n唱著子渊新曲，应须分外含情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1625, '哨遍', '苏轼', '为米折腰，因酒弃家，口体交相累。\n归去来，谁不遣君归。\n觉从前皆非今是。\n露未。\n征夫指予归路，门前笑语喧童稚。\n嗟旧菊都荒，新松暗老，吾年今已如此。\n但小窗容膝闭柴扉。\n策杖看孤云暮鸿飞。\n云出无心，鸟倦知还，本非有意。\n噫。\n归去来兮。\n我今忘我兼忘世。\n亲戚无浪语，琴书中有真味。\n步翠麓崎岖，泛溪窈窕，涓涓暗谷流春水。\n观草木欣荣，幽人自感，吾生行且休矣。\n念寓形宇内复几时。\n不自觉皇皇欲何之。\n委吾心、去留谁计。\n神仙知在何处，富贵非吾志。\n但知临水登山啸咏，自引壶觞自醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1626, '哨遍', '苏轼', '睡起画堂，银蒜押帘，珠幕云垂地。\n初雨歇，洗出碧罗天，正溶溶养花天气。\n一霎暖风回芳草，荣光浮动，掩皱银塘水。\n方杏靥匀酥，花吐绣，园林排比红翠。\n见乳燕捎蝶过繁枝。\n忽一线炉香逐游丝。\n昼永人闲，独立斜阳，晚来情味。\n便乘兴携将佳丽。\n深入芳菲里。\n拨胡琴语，轻拢慢捻总伶俐。\n看紧约罗裙，急趣檀板，霓裳入破惊鸿起。\n颦月临眉，醉霞横脸，歌声悠扬云际。\n任满头红雨落花飞。\n渐鹊楼西玉蟾低。\n尚徘徊、未尽欢意。\n君看今古悠悠，浮宦人间世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1627, '点绛唇', '苏轼', '我辈情锺，古来谁似龙山宴。\n而今楚甸。\n戏马馀飞观。\n顾谓佳人，不觉秋强半。\n筝声远。\n鬓云吹乱。\n愁入参差雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1628, '点绛唇', '苏轼', '不用悲秋，今年身健还高宴。\n江村海甸。\n总作空花观。\n尚想横汾，兰菊纷相半。\n楼船远。\n白云飞乱。\n空有年年雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1629, '点绛唇', '苏轼', '莫唱阳关，风流公子方终宴。\n秦山禹甸。\n缥缈真奇观。\n北望平原，落日山衔半。\n孤帆远。\n我歌君乱。\n一送西飞雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1630, '点绛唇', '苏轼', '醉漾轻舟，信流引到花深处。\n尘缘相误。\n无计花间住。\n烟水茫茫，千里斜阳暮。\n山无数。\n乱红如雨。\n不记来时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1631, '点绛唇', '苏轼', '月转乌啼，画堂宫徵生离恨。\n美人愁闷。\n不管罗衣褪。\n清泪斑斑，挥断柔肠寸。\n嗔人问。\n背灯偷。\n拭尽残妆粉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1632, '人娇', '苏轼', '满院桃花，尽是刘郎未见。\n於中更、一枝纤软。\n仙家日月，笑人间春晚。\n浓睡起，惊飞乱红千片。\n密意难传，羞容易变。\n平白地、为伊肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1633, '人娇', '苏轼', '白发苍颜，正是维摩境界。\n空方丈、散花何碍。\n朱唇箸点，更髻鬟生彩。\n这些个，千生万生只在。\n好事心肠，著人情态。\n闲窗下、敛云凝黛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1634, '人娇', '苏轼', '别驾来时，灯火荧煌无数。\n向青琐、隙中偷。\n元来便是，共采鸾仙侣。\n方见了，管须低声说与。\n百子流苏，千枝宝炬。\n人间有、洞房烟雾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1635, '诉衷情', '苏轼', '钱塘风景古来奇。\n太守例能诗。\n先驱负弩何在，心已誓江西。\n花尽後，叶飞时。\n雨凄凄。\n若为情绪，更问新官，向旧官啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1636, '诉衷情', '苏轼', '海棠珠缀一重重。\n清晓近帘栊。\n胭脂谁与匀淡，偏向脸边浓。\n看叶嫩，惜花红。\n意无穷。\n如花似叶，岁岁年年，共占春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1637, '诉衷情', '苏轼', '小莲初上琵琶弦。\n弹破碧云天。\n分明绣阁幽恨，都向曲中传。\n肤莹玉，鬓梳蝉。\n绮窗前。\n素蛾今夜，故故随人，似斗婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1638, '更漏子', '苏轼', '水涵空，山照市。\n西汉二疏乡里。\n新白发，旧黄金。\n故人恩意深。\n海东头，山尽处。\n自古客槎来去。\n槎有信，赴秋期。\n使君行不归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1639, '华清引', '苏轼', '平时十月幸兰汤。\n玉琼梁。\n五家车马如水，珠玑满路旁。\n翠华一去掩方床。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1640, '桃源忆故人', '苏轼', '华胥梦断人何处。\n听得莺啼红树。\n几点蔷薇香雨。\n寂寞闲庭户。\n暖风不解留花住。\n片片著人无数。\n楼上望春归去。\n芳草迷归路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1641, '醉落魄・一斛珠', '苏轼', '醉醒醒醉。\n凭君会取这滋味。\n浓斟琥珀香浮蚁。\n一到愁肠，别有阳春意。\n须将幕席为天地。\n歌前起舞花前睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1642, '醉落魄・一斛珠', '苏轼', '分携如昨。\n人生到处萍飘泊。\n偶然相聚还离索。\n多病多愁，须信从来错。\n尊前一笑休辞却。\n天涯同是伤沦落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1643, '醉落魄・一斛珠', '苏轼', '苍颜华发。\n故山归计何时决。\n旧交新贵音书绝。\n惟有佳人，犹作殷勤别。\n离亭欲去歌声咽。\n潇潇细雨凉吹颊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1644, '醉落魄・一斛珠', '苏轼', '轻云微月。\n二更酒醒船初发。\n孤城回望苍烟合。\n公子佳人，不记归时节。\n巾偏扇坠藤床滑。\n觉来幽梦无人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1645, '谒金门', '苏轼', '秋帷里。\n长漏伴人无寐。\n低玉枕凉轻绣被。\n一番秋气味。\n晓色又侵窗纸。\n窗外鸡声初起。\n声断几声还到耳。\n已明声未已。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1646, '谒金门', '苏轼', '秋池阁。\n风傍晓庭帘幕。\n霜叶未衰吹未落。\n半惊鸦喜鹊。\n自笑浮名情薄。\n似与世人疏略。\n一片懒心双懒脚。\n好教闲处著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1647, '谒金门', '苏轼', '今夜雨。\n断送一年残暑。\n坐听潮声来别浦。\n明朝何处去。\n孤负金尊绿醑。\n来岁今宵圆否。\n酒醒梦回愁几许。\n夜阑还独语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1648, '如梦令', '苏轼', '水垢何曾相受。\n细看两俱无有。\n寄语揩背人，尽日劳君挥肘。\n轻手。\n轻手。\n居士本来无垢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1649, '如梦令', '苏轼', '自净方能净彼。\n我自汗流呀气。\n寄语澡浴人，且共肉身游戏。\n但洗。\n但洗。\n俯为人间一切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1650, '如梦令', '苏轼', '为向东坡传语。\n人在玉堂深处。\n别後有谁来，雪压小桥无路。\n归去。\n归去。\n江上一犁春雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1651, '如梦令', '苏轼', '手种堂前桃李。\n无限绿阴青子。\n帘外百舌儿，惊起五更春睡。\n居士。\n居士。\n莫望小桥流水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1652, '阳关曲', '苏轼', '暮云收尽溢清寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1653, '阳关曲', '苏轼', '受降城下紫髯郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1654, '阳关曲', '苏轼', '济南春好雪初晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1655, '减字木兰花', '苏轼', '郑庄好客。\n容我尊前先堕帻。\n落笔生风。\n籍籍声名不负公。\n高山白早。\n莹骨冰肤那解老。\n从此南徐。\n良夜清风月满湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1656, '减字木兰花', '苏轼', '云鬟倾倒。\n醉倚阑干风月好。\n凭仗相扶。\n误入仙家碧玉壶。\n连天衰草。\n下走湖南西去道。\n一舸姑苏。\n便逐鸱夷去得无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1657, '减字木兰花', '苏轼', '闽溪珍献。\n过海云帆来似箭。\n玉座金盘。\n不贡奇葩四百年。\n轻红酿白。\n雅称佳人纤手擘。\n骨细肌香。\n恰是当年十八娘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1658, '减字木兰花', '苏轼', '贤哉令尹。\n三仕已之无喜愠。\n我独何人。\n犹把虚名玷绅。\n不如归去。\n二顷良田无觅处。\n归去来兮。\n待有良田是几时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1659, '减字木兰花', '苏轼', '玉觞无味。\n中有佳人千点泪。\n学道忘忧。\n一念还成不自由。\n如今未见。\n归去东园花似霰。\n一语相开。\n匹似当初本不来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1660, '减字木兰花', '苏轼', '春光亭下。\n流水如今何在也。\n岁月如梭。\n白首相看拟奈何。\n故人重见。\n世事年来千万变。\n官况阑珊。\n惭愧青松守岁寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1661, '减字木兰花', '苏轼', '惟熊佳梦。\n释氏老君亲抱送。\n壮气横秋。\n未满三朝已食牛。\n犀钱玉果。\n利市平分沾四坐。\n多谢无功。\n此事如何到得侬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1662, '减字木兰花', '苏轼', '晓来风细。\n不会鹊声来报喜。\n却羡寒梅。\n先觉春风一夜来。\n香笺一纸。\n写尽回文机上意。\n欲卷重开。\n读遍千回与万回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1663, '减字木兰花', '苏轼', '天台旧路。\n应恨刘郎来又去。\n别酒频倾。\n忍听阳关第四声。\n刘郎未老。\n怀恋仙乡重得到。\n只恐因循。\n不见如今劝酒人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1664, '减字木兰花', '苏轼', '双龙对起。\n白甲苍髯烟雨里。\n疏影微香。\n下有幽人昼梦长。\n湖风清软。\n双鹊飞来争噪晚。\n翠红轻。\n时下凌宵百尺英。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1665, '减字木兰花', '苏轼', '琵琶绝艺。\n年纪都来十一二。\n拨弄么弦。\n未解将心指下传。\n主人小。\n欲向东风先醉倒。\n已属君家。\n且更从容等待他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1666, '减字木兰花', '苏轼', '春牛春杖。\n无限春风来海上。\n便与春工。\n染得桃红似肉红。\n春幡春胜。\n一阵春风吹酒醒。\n不似天涯。\n卷起杨花似雪花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1667, '减字木兰花', '苏轼', '云容皓白。\n破晓玉英纷似织。\n风力无端。\n欲学杨花更耐寒。\n相如未老。\n梁苑犹能陪俊少。\n莫惹闲愁。\n且折江梅上小楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1668, '减字木兰花', '苏轼', '玉房金蕊。\n宜在玉人纤手里。\n淡月朦胧。\n更有微微弄袖风。\n温香熟美。\n醉慢云鬟垂两耳。\n多谢春工。\n不是花红是玉红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1669, '减字木兰花', '苏轼', '春庭月午。\n摇荡香醪光欲舞。\n步转迥廊。\n半落梅花婉娩香。\n轻云薄雾。\n总是少年行乐处。\n不似秋光。\n只与离人照断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1670, '减字木兰花', '苏轼', '天然宅院。\n赛了千千并万万。\n说与贤知。\n表德元来是胜之。\n今来十四。\n海里猴儿奴子是。\n要赌休痴。\n六双骰儿六点儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1671, '浣溪沙', '苏轼', '风卷珠帘自上钩。\n萧萧乱叶报新秋。\n独携纤手上高楼。\n缺月向人舒窈窕，三星当户照绸缪。\n香生雾见纤柔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1672, '浣溪沙', '苏轼', '山下兰芽短浸溪。\n松间沙路净无泥。\n萧萧暮雨子规啼。\n谁道人生无再少，门前流水尚能西。\n休将白发唱黄鸡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1673, '浣溪沙', '苏轼', '西塞山边白鹭飞。\n散花洲外片帆微。\n桃花流水鳜鱼肥。\n自庇一身青箬笠，相随到处绿蓑衣。\n斜风细雨不须归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1674, '浣溪沙', '苏轼', '覆块青青麦未苏。\n江南云叶暗随车。\n临皋烟景世间无。\n雨脚半收檐断线，雪林初下瓦疏珠。\n归来冰颗乱黏须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1675, '浣溪沙', '苏轼', '醉梦醺醺晓未苏。\n门前辘辘使君车。\n扶头一盏怎生无。\n废圃寒蔬挑翠羽，小槽春酒冻真珠。\n清香细细嚼梅须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1676, '浣溪沙', '苏轼', '雪里餐毡例姓苏。\n使君载酒为回车。\n天寒酒色转头无。\n荐士已闻飞鹗表，报恩应不用蛇珠。\n醉中还许揽桓须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1677, '浣溪沙', '苏轼', '半夜银山上积苏。\n朝来九陌带随车。\n涛江烟渚一时无。\n空腹有诗衣有结，湿薪如桂米如珠。\n冻吟谁伴拈髭须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1678, '浣溪沙', '苏轼', '万顷风涛不记苏。\n雪晴江上麦千车。\n但令人饱我愁无。\n翠袖倚风萦柳絮，绛唇得酒烂樱珠。\n尊前呵手镊霜须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1679, '浣溪沙', '苏轼', '珠桧丝杉冷欲霜。\n山城歌舞助凄凉。\n且餐山色饮湖光。\n共挽朱幡留半日，强揉青蕊作重阳。\n不知明日为谁黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1680, '浣溪沙', '苏轼', '霜鬓真堪插拒霜。\n哀弦危柱作伊凉。\n暂时流转为风光。\n未遣清尊空北海，莫因长笛赋山阳。\n金钗玉腕泻鹅黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1681, '浣溪沙', '苏轼', '傅粉郎君又粉奴。\n莫教施粉与施朱。\n自然冰玉照香酥。\n有客能为神女赋，凭君送与雪儿书。\n梦魂东去觅桑榆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1682, '浣溪沙', '苏轼', '菊暗荷枯一夜霜。\n新苞绿叶照林光。\n竹篱茅舍出青黄。\n香雾人惊半破，清泉流齿怯初尝。\n吴姬三日手犹香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1683, '浣溪沙', '苏轼', '雪颔霜髯不自惊。\n更将翦采发春荣。\n羞颜未醉已先。\n莫唱黄鸡并白发，且呼张丈唤殷兄。\n有人归去欲卿卿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1684, '浣溪沙', '苏轼', '料峭东风翠幕惊。\n云何不饮对公荣。\n水晶盘莹玉鳞。\n花影莫孤三夜月，朱颜未称五年兄。\n翰林子墨主人卿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1685, '浣溪沙', '苏轼', '照日深红暖见鱼。\n连溪绿暗晚藏乌。\n黄童白叟聚睢盱。\n糜鹿逢人虽未惯，猿揉闻鼓不须呼。\n归家说与采桑姑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1686, '浣溪沙', '苏轼', '旋抹红妆看使君。\n三三五五棘篱门。\n相挨踏破罗裙。\n老幼扶携收麦社，乌鸢翔舞赛神村。\n道逢醉叟卧黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1687, '浣溪沙', '苏轼', '麻叶层层苘叶光。\n谁家煮蚕一村香。\n隔篱娇语络丝娘。\n垂白杖藜抬醉眼，捋青捣软饥肠。\n问言豆叶几时黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1688, '浣溪沙', '苏轼', '簌簌衣巾落枣花。\n村南村北响缲车。\n牛衣古柳卖黄瓜。\n酒困路长惟欲睡，日高人渴漫思茶。\n敲门试问野人家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1689, '浣溪沙', '苏轼', '软草平莎过雨新。\n轻沙走马路无尘。\n何时收拾耦耕身。\n日暖桑麻光似泼，风来蒿艾气如薰。\n使君元是此中人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1690, '浣溪沙', '苏轼', '道字娇讹苦未成。\n未应春阁梦多情。\n朝来何事绿鬟倾。\n彩索身轻长趁燕，红窗睡重不闻莺。\n困人天气近清明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1691, '浣溪沙', '苏轼', '缥缈危楼紫翠间。\n良辰乐事古难全。\n感时怀旧独凄然。\n璧月琼枝空夜夜，菊花人貌自年年。\n不知来岁与谁看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1692, '浣溪沙', '苏轼', '桃李溪边驻画轮。\n鹧鸪声里倒清尊。\n夕阳虽好近黄昏。\n香在衣裳妆在臂，水连芳草月连云。\n几时归去不销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1693, '浣溪沙', '苏轼', '四面垂杨十里荷。\n问云何处最花多。\n画楼南畔夕阳和。\n天气乍凉人寂寞，光阴须得酒消磨。\n且来花里听笙歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1694, '浣溪沙', '苏轼', '一别姑苏已四年。\n秋风南浦送归船。\n画帘重见水中仙。\n霜鬓不须催我老，杏花依旧驻君颜。\n夜阑相对梦魂间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1695, '浣溪沙', '苏轼', '惟见眉间一点黄。\n诏书催发羽书忙。\n从教娇泪洗红妆。\n上殿云宵生羽翼，论兵齿颊带风霜。\n归来衫袖有天香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1696, '浣溪沙', '苏轼', '长记鸣琴子贱堂。\n朱颜绿发映垂杨。\n如今秋鬓数茎霜。\n聚散交游如梦寐，升沈闲事莫思量。\n仲卿终不避桐乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1697, '浣溪沙', '苏轼', '风压轻云贴水飞。\n乍晴池馆燕争泥。\n沈郎多病不胜衣。\n沙上不闻鸿雁信，竹间时听鹧鸪啼。\n此情惟有落花知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1698, '浣溪沙', '苏轼', '罗袜空飞洛浦尘。\n锦袍不见谪仙人。\n携壶藉草亦天真。\n玉粉轻黄千岁药，雪花浮动万家春。\n醉归江路野梅新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1699, '浣溪沙', '苏轼', '白雪清词出坐间。\n爱君才器两俱全。\n异乡风景却依然。\n可恨相逢能几日，不知重会是何年。\n茱萸仔细更重看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1700, '浣溪沙', '苏轼', '细雨斜风作晓寒。\n淡烟疏柳媚晴滩。\n入淮清洛渐漫漫。\n雪沫乳花浮午盏，蓼茸蒿笋试春盘。\n人间有味是清欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1701, '浣溪沙', '苏轼', '门外东风雪洒裾。\n山头回首望三吴。\n不应弹铗为无鱼。\n上党从来天下脊，先生元是古之儒。\n时平不用鲁连书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1702, '浣溪沙', '苏轼', '惭愧今年二麦丰。\n千畦细浪舞晴空。\n化工馀力染夭红。\n归去山公应倒载，阑街拍手笑儿童。\n甚时名作锦薰笼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1703, '浣溪沙', '苏轼', '芍药樱桃两斗新。\n名园高会送芳辰。\n洛阳初夏广陵春。\n红玉半开菩萨面，丹砂浓点柳枝唇。\n尊前还有个中人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1704, '浣溪沙', '苏轼', '学画鸦儿正妙年。\n阳城下蔡困嫣然。\n凭君莫唱短因缘。\n雾帐吹笙香袅袅，霜庭按舞月娟娟。\n曲终红袖落双缠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1705, '浣溪沙', '苏轼', '一梦江湖费五年。\n归来风物故依然。\n相逢一醉是前缘。\n迁客不应常，使君为出小婵娟。\n翠鬟聊著小诗缠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1706, '浣溪沙', '苏轼', '轻汗微微透碧纨。\n明朝端午浴芳兰。\n流香涨腻满晴川。\n彩线轻缠红玉臂，小符斜挂绿云鬟。\n佳人相见一千年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1707, '浣溪沙', '苏轼', '徐邈能中酒圣贤。\n刘伶席地幕青天。\n潘郎白璧为谁连。\n无可奈何新白发，不如归去旧青山。\n恨无人借买山钱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1708, '浣溪沙', '苏轼', '倾盖相逢胜白头。\n故山空复梦松楸。\n此心安处是菟裘。\n卖剑买牛吾欲老，乞浆得酒更何求。\n愿为辞社宴春秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1709, '浣溪沙', '苏轼', '炙手无人傍屋头。\n萧萧晚雨脱梧楸。\n谁怜季子敞貂裘。\n顾我已无当世望，似君须向古人求。\n岁寒松柏肯惊秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1710, '浣溪沙', '苏轼', '画隼横江喜再游。\n老鱼跳槛识清讴。\n流年未肯付东流。\n黄菊篱边无怅望，白云乡里有温柔。\n挽回霜鬓莫教休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1711, '双荷叶・忆秦娥', '苏轼', '双溪月。\n清光遍照双荷叶。\n双荷叶。\n红心未偶，绿衣偷结。\n背风迎雨流珠滑。\n轻舟短棹先秋折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1712, '皂罗特髻', '苏轼', '采菱拾翠，算似此佳名，阿谁消得。\n采菱拾翠，称使君知客。\n千金买、采菱拾翠，更罗裙、满把珍珠结。\n采菱拾翠，正髻鬟初合。\n真个、采菱拾翠，但深怜轻拍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1713, '调笑令', '苏轼', '渔父。\n渔父。\n江上微风细雨。\n青蓑黄箬裳衣。\n红酒白鱼暮归。\n归暮。\n归暮。\n长笛一声何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1714, '调笑令', '苏轼', '归雁。\n归雁。\n饮啄江南南岸。\n将飞却下盘桓。\n塞外春来苦寒。\n寒苦。\n寒苦。\n藻荇欲生且住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1715, '荷华媚', '苏轼', '霞苞电荷碧。\n天然地、别是风流标格。\n重重青盖下，千娇照水，好红红白白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1716, '青玉案', '苏轼', '三年枕上吴中路。\n遣黄耳、随君去。\n若到松江呼小渡。\n莫惊鸥鹭，四桥尽是，老子经行处。\n辋川图上看春暮。\n常记高人右丞句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1717, '渔家傲', '苏轼', '些小白须何用染。\n几人得见星星点。\n作郡浮光虽似箭。\n君莫厌。\n也应胜我三年贬。\n我欲自嗟还不敢。\n向来三郡宁非忝。\n婚嫁事稀年冉冉。\n知有渐。\n千钧重担从头减。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1718, '江城子', '苏轼', '前瞻马耳九仙山。\n碧连天。\n晚云闲。\n城上高台，真个是超然。\n莫使匆匆云雨散，今夜里，月婵娟。\n小溪鸥鹭静联拳。\n去翩翩。\n点轻烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1719, '江城子', '苏轼', '墨云拖雨过西楼。\n水东流。\n晚烟收。\n柳外残阳，回照动帘钩。\n今夜巫山真个好，花未落，酒新。\n美人微笑转星眸。\n月华羞。\n捧金瓯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1720, '南乡子', '苏轼', '未倦长卿游。\n漫舞夭歌烂不收。\n不是使君能矫世，谁留。\n教有琼梳脱麝油。\n香粉镂金球。\n花艳红笺笔欲流。\n从此丹唇并皓齿，清柔。\n唱遍山东一百州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1721, '南乡子', '苏轼', '绣鞅玉环游。\n灯晃帘疏笑却收。\n久立香车催欲上，还留。\n更且檀唇点杏油。\n花遍六么球。\n面旋回风带雪流。\n春入腰肢金缕细，轻柔。\n种柳应须柳柳州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1722, '菩萨蛮', '苏轼', '娟娟侵鬓妆痕浅。\n双颦相媚弯如翦。\n一瞬百般宜。\n无论笑与啼。\n酒阑思翠被。\n特故腾腾地。\n生怕促归轮。\n微波先注人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1723, '菩萨蛮', '苏轼', '涂香莫惜莲承步。\n长愁罗袜凌波去。\n只见舞迥风。\n都无行处踪。\n偷穿宫样稳。\n并立双趺困。\n纤妙说应难。\n须从掌上看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1724, '菩萨蛮', '苏轼', '玉环坠耳黄金饰。\n轻衫罩体香罗碧。\n缓步困春醪。\n春融脸上桃。\n花钿从委地。\n谁与郎为意。\n常爱月华清。\n此时憎月明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1725, '蝶恋花', '苏轼', '别酒劝君君一醉。\n清润潘郎，又是何郎婿。\n记取钗头新利市。\n莫将分付东邻子。\n回首长安佳丽地。\n三十年前，我是风流帅。\n为向青楼寻旧事。\n花枝缺处馀名字。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1726, '蝶恋花', '苏轼', '泛泛东风初破五。\n江柳微黄，万万千千缕。\n佳气郁葱来绣户。\n当年江上生奇女。\n一盏寿觞谁与举。\n三个明珠，膝上王文度。\n放尽穷鳞看圉圉。\n天公为下曼陀雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1727, '浣溪沙', '苏轼', '入袂轻风不破尘。\n玉簪犀璧醉佳辰。\n一番红粉为谁新。\n团扇只堪题往事，新丝那解系行人。\n酒阑滋味思残春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1728, '浣溪沙', '苏轼', '几共查梨到雪霜。\n一经题品便生光。\n木奴何处避雌黄。\n北客有来初未识，南金无价喜新尝。\n含滋嚼句齿牙香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1729, '浣溪沙', '苏轼', '山色横侵蘸晕霞。\n湘川风静吐寒花。\n远林屋散尚啼鸦。\n梦到故园多少路，酒醒南望隔天涯。\n月明千里照平沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1730, '减字木兰花', '苏轼', '神闲意定。\n万籁收声天地静。\n玉指冰弦。\n未动宫商意已传。\n悲风流水。\n写处寥寥千古意。\n归去无眠。\n一夜馀音在耳边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1731, '减字木兰花', '苏轼', '银铮旋品。\n不用缠头千尺锦。\n妙思如泉。\n一洗闲愁十五年。\n为公少止。\n起舞属公公莫起。\n风里银山。\n摆撼鱼龙我自闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1732, '减字木兰花', '苏轼', '柔和性气。\n雅称佳名呼懿懿。\n解舞能讴。\n绝妙年中有品流。\n眉长眼细。\n淡淡梳妆新绾髻。\n懊恼风情。\n春著花枝百态生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1733, '减字木兰花', '苏轼', '莺初解语。\n最是一年春好处。\n微雨如酥。\n草色遥看近却无。\n休辞醉倒。\n花不看开人易老。\n莫待春回。\n颠倒红英间绿苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1734, '减字木兰花', '苏轼', '江南游女。\n问我何年归得去。\n雨细风微。\n雨足如霜挽衣。\n江亭夜语。\n喜见京华新样舞。\n莲步轻飞。\n迁客今朝始是归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1735, '减字木兰花', '苏轼', '娇多媚。\n体柳轻盈千万态。\n主尤宾。\n敛黛含喜又嗔。\n徐君乐饮。\n笑谑从伊情意恁。\n脸嫩敷红。\n花倚朱阑裹住风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1736, '减字木兰花', '苏轼', '双鬟绿坠。\n娇眼横波眉黛翠。\n妙舞蹁跹。\n掌上身轻意态妍。\n曲穷力困。\n笑倚人旁香喘喷。\n老大逢欢。\n昏眼犹能仔细看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1737, '减字木兰花', '苏轼', '天真雅丽。\n容态温柔心性慧。\n响亮歌喉。\n遏住行云翠不收。\n妙词佳曲。\n啭出新声能断续。\n重客多情。\n满劝金卮玉手擎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1738, '南歌子', '苏轼', '见说东园好，能消北客愁。\n虽非吾土且登楼。\n行尽江南南岸、此淹留。\n短日明枫缬，清霜暗菊逑。\n流年回首付东流。\n凭仗挽回潘鬓、莫教秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1739, '如梦令', '苏轼', '城上层楼叠。\n城下清淮古汴。\n举手揖吴云，人与暮天俱远。\n魂断。\n魂断。\n後夜松江月满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1740, '瑞鹧鸪', '苏轼', '城头月落尚啼乌。\n朱舰红船早满湖。\n鼓吹未容迎五马，水云先已漾双凫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1741, '临江仙', '苏轼', '谁道东阳都瘦损，凝然点漆精神。\n瑶林终自隔风尘，试看披鹤氅，仍是谪仙人。\n省可清言挥玉麈，真须保器全真。\n风流何似道家纯。\n不应同蜀客，惟爱卓文君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1742, '少年游', '苏轼', '玉肌铅粉傲秋霜。\n准拟凤呼凰。\n伶伦不见，清香未吐，且糠秕吹扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1743, '一斛珠', '苏轼', '洛城春晚。\n垂杨乱掩红楼半。\n小池轻浪纹如篆。\n烛下花前，曾醉离歌宴。\n自惜风流云雨散。\n关山有限情无限。\n待君重见寻芳伴。\n为说相思、目断西楼燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1744, '点绛唇', '苏轼', '闲倚胡床，庾公楼外峰千朵。\n与谁同坐。\n明月清风我。\n别乘一来，有唱应须和。\n还知麽。\n自从添个。\n风月平分破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1745, '点绛唇', '苏轼', '红杏飘香，柳含烟翠拖轻缕。\n水边朱户。\n尽卷黄昏雨。\n烛影摇风，一枕伤春绪。\n归不去。\n凤楼何处。\n芳草迷归路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1746, '虞美人', '苏轼', '持杯遥劝天边月。\n愿月圆无缺。\n持杯复更劝花枝。\n且愿花枝长在、莫离披。\n持杯月下花前醉。\n休问荣枯事。\n此欢能有几人知。\n对酒逢花不饮、待何时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1747, '天仙子', '苏轼', '走马探花花发未。\n人与化工俱不易。\n千回来绕百回看，蜂作婢。\n莺为使。\n谷雨清明空屈指。\n白发卢郎情未已。\n一夜翦刀收玉蕊。\n尊前还对断肠红，人有泪。\n花无意。\n明日酒醒应满地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1748, '满庭芳', '苏轼', '归去来兮，清溪无底，上有千仞嵯峨。\n画楼东畔，天远夕阳多。\n老去君恩未报，空回首、弹铗悲歌。\n船头转，长风万里，归马驻平坡。\n无何。\n何处有，银潢尽处，天女停梭。\n问何事人间，久戏风波。\n顾谓同来稚子，应烂汝、腰下长柯。\n青衫破，群仙笑我，千缕挂烟蓑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1749, '南乡子', '苏轼', '千骑试春游。\n小雨如酥落便收。\n能使江东归老客，迟留。\n白酒无声滑泻油。\n飞火乱星逑。\n浅黛横波翠欲流。\n不似白云乡外冷，温柔。\n此去淮南第一州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1750, '浣溪沙', '苏轼', '缥缈红妆照浅溪。\n薄云疏雨不成泥。\n送君何处古台西。\n废沼夜来秋水满，茂林深处晚莺啼。\n行人肠断草凄迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1751, '浣溪沙', '苏轼', '阳羡姑苏已买田。\n相逢谁信是前缘。\n莫教便唱水如天。\n我作洞霄君作守，白头相对故依然。\n西湖知有几同年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1752, '减字木兰花', '苏轼', '空床响琢。\n花上春禽冰上雹。\n醉梦尊前。\n惊起湖风入坐寒。\n转关镬索。\n春水流弦霜入拨。\n月堕更阑。\n更请宫高奏独弹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1753, '减字木兰花', '苏轼', '回风落景。\n散乱东墙疏竹影。\n满坐清微。\n入袖寒泉不湿衣。\n梦回酒醒。\n百尺飞澜鸣碧井。\n雪洒冰麾。\n散落佳人白玉肌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1754, '减字木兰花', '苏轼', '海南奇宝。\n铸出团团如栲栳。\n曾到。\n乞得山头玉女盆。\n绛州王老。\n百岁痴顽推不倒。\n海口如门。\n一派黄流已电奔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1755, '行香子', '苏轼', '北望平川。\n野水荒湾。\n共寻春、飞步孱颜。\n和风弄袖，香雾萦鬟。\n正酒酣时，人语笑，白云间。\n飞鸿落照，相将归去，澹娟娟、玉宇清闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1756, '画堂春', '苏轼', '柳花飞处麦摇波。\n晚湖净鉴新磨。\n小舟飞棹去如梭。\n齐唱采菱歌。\n平野水云溶漾，小楼风日晴和。\n济南何在暮云多。\n归去奈愁何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1757, '浣溪沙', '苏轼', '花满银塘水漫流。\n犀槌玉板奏凉州。\n顺风环佩过秦楼。\n远汉碧云轻漠漠，今宵人在鹊桥头。\n一声敲彻绛河秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1758, '好事近', '苏轼', '烟外倚危楼，初见远灯明灭。\n却跨玉虹归去，看洞天星月。\n当时张范风流在，况一尊浮雪。\n莫问世间何事，与剑头微。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1759, '占春芳', '苏轼', '红杏了，夭桃尽，独自占春芳。\n不比人间兰麝，自然透骨生香。\n对酒莫相忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1760, '南歌子', '苏轼', '云鬓裁新绿，霞衣曳晓红。\n待歌凝立翠筵中。\n一朵彩云何事、下巫峰。\n趁拍鸾飞镜，回身燕漾空。\n莫翻红袖过帘栊。\n怕被杨花句引、嫁东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1761, '浪淘沙', '苏轼', '昨日出东城。\n拭探春情。\n墙头红杏暗如倾。\n槛内群芳芽未吐，早已回春。\n绮陌敛香尘。\n雪霁前村。\n东君用意不辞辛。\n料想春光先到处，吹绽梅英。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1762, '木兰花令', '苏轼', '元宵似是欢游好。\n何况公庭民讼少。\n万家游赏上春台，十里神仙迷海岛。\n平原不似高阳傲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1763, '木兰花令', '苏轼', '经旬未识东君信。\n一夕薰风来解愠。\n红绡衣薄麦秋寒，绿绮韵低梅雨润。\n瓜头绿染山光嫩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1764, '木兰花令', '苏轼', '高平四面开雄垒。\n三月风光初觉媚。\n园中桃李使君家，城上亭台游客醉。\n歌翻杨柳金尊沸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1765, '虞美人', '苏轼', '冰肌自是生来瘦。\n那更分飞後。\n日长帘暮望黄昏。\n及至黄昏时候、转销魂。\n君还知道相思苦。\n怎忍抛奴去。\n不辞迢递过关山。\n只恐别郎容易、见郎难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1766, '虞美人', '苏轼', '深深庭院清明过。\n桃李初红破。\n柳丝搭在玉阑干。\n帘外潇潇微雨、做轻寒。\n晚晴台榭增明媚。\n已拼花前醉。\n更阑人静月侵廊。\n独自行来行去、好思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1767, '临江仙', '苏轼', '昨夜渡江何处宿，望中疑是秦淮。\n月明谁起笛中哀。\n多情王谢女，相逐过江来。\n云雨未成还又散，思量好事难谐。\n凭陵急桨两相催。\n想伊归去後，应似我情怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1768, '蝶恋花', '苏轼', '春事阑珊芳草歇。\n客里风光，又过清明节。\n小院黄昏人忆别。\n落红处处闻啼。\n咫尺江山分楚越。\n目断魂销，应是音尘绝。\n梦破五更心欲折。\n角声吹落梅花月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1769, '蝶恋花', '苏轼', '记得画屏初会遇。\n好梦惊回，望断高唐路。\n燕子双飞来又去。\n纱窗几度春光暮。\n那日绣帘相见处。\n低眼佯行，笑整香云缕。\n敛尽春山羞不语。\n人前深意难轻诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1770, '蝶恋花', '苏轼', '昨夜秋风来万里。\n月上屏帏，冷透人衣袂。\n有客抱衾愁不寐。\n那堪玉漏长如岁。\n羁舍留连归计未。\n梦断魂销，一枕相思泪。\n衣带渐宽无别意。\n新书报我添憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1771, '蝶恋花', '苏轼', '雨霰疏疏经泼火。\n巷陌秋千。\n犹未清明过。\n杏子梢头香蕾破。\n淡红褪白胭脂。\n苦被多情相折挫。\n病绪厌厌，浑似年时个。\n绕遍回廊还独坐。\n月笼云暗重门锁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1772, '蝶恋花', '苏轼', '蝶懒莺慵春过半。\n花落狂风，小院残红满。\n午醉未醒红日晚。\n黄昏帘暮无人卷。\n云鬓蓬松眉黛浅。\n总是愁媒，欲诉谁消遣。\n未信此情难系绊。\n杨花犹有东风管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1773, '渔家傲', '苏轼', '临水纵横回晚。\n归来转觉情怀动。\n梅笛烟中闻几弄。\n秋阴重。\n西山雪淡云凝冻。\n美酒一杯谁与共。\n尊前舞雪狂歌送。\n腰跨金鱼旌旆拥。\n将何用。\n只堪妆点浮生梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1774, '江城子', '苏轼', '腻红匀脸衬檀唇。\n晚妆新。\n暗伤春。\n手拈花枝，谁会两眉颦。\n连理带头双□□，留待与、个中人。\n淡烟笼月绣帘阴。\n画堂深。\n夜沈沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1775, '祝英台近', '苏轼', '挂轻帆，飞急桨，还过钓台路。\n酒病无聊，枕听鸣橹。\n断肠簇簇云山，重重烟树，回首望、孤城何处。\n闲离阻。\n谁念萦损襄王，何曾梦云雨。\n旧恨前欢，心事两无据。\n要知欲见无由，痴心犹自，倩人道、一声传语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1776, '雨中花慢', '苏轼', '邃院重帘何处，惹得多情，愁对风光。\n睡起酒阑花谢，蝶乱蜂忙。\n今夜何人，吹笙北岭，待月西厢。\n空怅望处，一株红杏，斜倚低墙。\n羞颜易变，傍人先觉，到处被著猜防。\n谁信道，些儿恩爱，无限凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1777, '雨中花慢', '苏轼', '嫩脸羞蛾，因甚化作行云，却返巫阳。\n但有寒灯孤枕，皓月空床。\n长记当初，乍谐云雨，便学鸾凰。\n又岂料、正好三春桃李，一夜风霜。\n丹青□画，无言无笑，看了漫结愁肠。\n襟袖上，犹存残黛，渐减馀香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1778, '念奴娇', '苏轼', '凭高眺远，见长空万里，云无留迹。\n桂魄飞来光射处，冷浸一天秋碧。\n玉宇琼楼，乘鸾来去，人在清凉国。\n江山如画，望中烟树历历。\n我醉拍手狂歌，举杯邀月，对影成三客。\n起舞徘徊风露下，今夕不知何夕。\n便欲乘风，翻然归去，何用骑鹏翼。\n水晶宫里，一声吹断横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1779, '水龙吟', '苏轼', '小沟东接长江，柳堤苇岸连云际。\n烟村潇洒，人闲一哄，渔樵早市。\n永昼端居，寸阴虚度，了成何事。\n但丝莼玉藕，珠粳锦鲤，相留恋，又经岁。\n因念浮丘旧侣，惯瑶池、羽觞沈醉。\n青鸾歌舞，铢衣摇曳，壶中天地。\n飘堕人间，步虚声断，寒露风细。\n抱素琴，独向银蟾影里，此怀难寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1780, '水龙吟', '苏轼', '露寒烟冷蒹葭老，天外征鸿寥唳。\n银河秋晚，长门灯悄，一声初至。\n应念潇湘，岸遥人静，水多菰米。\n□望极平田，徘徊欲下，依前被、风惊起。\n须信衡阳万里。\n有谁家、锦书遥寄。\n万重云外，斜行横阵，才疏又缀。\n仙掌月明，石头城下，影摇寒水。\n念征衣未捣，佳人拂杵，有盈盈泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1781, '渔父・渔歌子', '苏轼', '渔父饮，谁家去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1782, '渔父・渔歌子', '苏轼', '渔父醉，蓑衣舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1783, '渔父・渔歌子', '苏轼', '渔父醒，春江午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1784, '渔父・渔歌子', '苏轼', '渔父笑，轻鸥举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1785, '醉翁操', '苏轼', '琅然。\n清圜。\n谁弹。\n响空山。\n无言。\n惟翁醉中知其天。\n月明风露娟娟。\n人未眠。\n荷蒉过山前。\n曰有心也哉此贤。\n醉翁啸咏，声和流泉。\n醉翁去後，空有朝吟夜怨。\n山有时而童巅。\n水有时而回川。\n思翁无岁年。\n翁今为飞仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1786, '导引', '苏轼', '帝城父老，三岁望尧心。\n天远玉楼深。\n龙颜仿佛笙箫远，肠断属车音。\n离宫春色琐瑶林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1787, '导引', '苏轼', '经文纬武，十有九年中。\n遗烈震羌戎。\n渭桥夹道千君长，犹是建元功。\n西瞻温洛与神崧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1788, '瑶池燕', '苏轼', '飞花成阵。\n春心困。\n寸寸。\n别肠多少愁闷。\n无人问。\n偷啼自。\n残妆粉。\n抱瑶琴、寻出新韵。\n玉纤趁。\n南风来解幽愠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1789, '千秋岁', '苏轼', '岛边天外。\n未老身先退。\n珠泪溅，丹衷碎。\n声摇苍玉佩。\n色重黄金带。\n一万里。\n斜阳正与长安对。\n道远谁云会。\n罪大天能盖。\n君命重，臣节在。\n新恩犹可觊。\n旧学终难改。\n吾已矣。\n乘桴且恁浮於海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1790, '减字木兰花', '苏轼', '凭谁妙笔。\n横扫素缣三百尺。\n天下应无。\n此是钱塘湖上图。\n一般奇绝。\n云淡天高秋夜月。\n费尽丹青。\n只这些儿画不成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1791, '失调名', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1792, '失调名', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1793, '失调名', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1794, '菩萨蛮', '苏轼', '湿云不动溪桥冷。\n嫩寒初透东风影。\n桥下水声长。\n一枝和月香。\n人怜花似旧。\n花比人应瘦。\n莫凭小栏干。\n夜深花正寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1795, '踏青游', '苏轼', '□火初晴，绿遍禁池芳草。\n斗锦绣、火城驰道。\n踏青游，拾翠惜，袜罗弓小。\n莲步袅。\n腰支佩兰轻妙。\n行过上林春好。\n今困天涯，何限旧情相恼。\n念摇落、玉京寒早。\n任刘郎、目断蓬山难到。\n仙梦杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1796, '阮郎归', '苏轼', '歌停檀板舞停鸾。\n高阳饮兴阑。\n兽烟喷尽玉壶乾。\n香分小凤团。\n雪浪浅，露珠圆。\n捧瓯春笋寒。\n绛纱笼下跃金鞍。\n归时人倚栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1797, '西江月', '苏轼', '马趁香微路远，沙笼月淡烟斜。\n渡波清彻映妍华。\n倒绿枝寒凤挂。\n挂凤寒枝绿倒，华妍映彻清波。\n渡斜烟淡月笼沙。\n远路微香趁马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1798, '失调名', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1799, '踏莎行', '苏轼', '山秀芙蓉，溪明罨画。\n真游洞穴沧波下。\n临风慨想斩蛟灵，长桥千载犹横跨。\n解佩投簪，求田问舍。\n黄鸡白酒渔樵社。\n元龙非复少时豪，耳根洗尽功名话。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1800, '踏莎行', '苏轼', '这个秃奴，修行忒煞。\n云山顶上空持戒。\n一从迷恋玉楼人，鹑衣百结浑无奈。\n毒手伤人，花容粉碎。\n空空色色今何在。\n臂间刺道苦相思，这回还了相思债。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1801, '失调名', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1802, '定风波', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1803, '定风波', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1804, '失调名', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1805, '失调名', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1806, '水调歌・水调', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1807, '失调名', '苏轼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1808, '鹧鸪天', '苏轼', '罗带双垂画不成。\n人娇态最轻盈。\n酥胸斜抱天边月，玉手轻弹水面冰。\n无限事，许多情。\n四弦丝竹苦丁宁。\n饶君拨尽相思调，待听梧桐叶落声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1809, '西江月', '苏轼', '碧雾轻笼两凤，寒烟淡拂双鸦。\n为谁流睇不归家。\n错认门前过马。\n有意偷回笑眼，无言强整衣纱。\n刘郎一见武陵花。\n从此春心荡也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1810, '夜行船', '赵', '今夜阴云初霁。\n画帘外、月华如水。\n露霭晴空，风吹高树，满院中秋意。\n皎皎蟾光当此际。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1811, '河传', '郭讵', '大官无闷。\n刚被傍人、竟来相问。\n又难为□□敷臣。\n且只将、甘草论。\n朴消大戟并银粉。\n疏风紧。\n甘草闲相混。\n及至下来，转杀他人。\n尔甘草、有一分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1812, '水龙吟', '李之仪', '晚来轻拂，游云尽卷，霁色寒相射。\n银潢半掩，秋毫欲数，分明不夜。\n玉传声，羽衣催舞，此欢难借。\n凛清辉，但觉圆光照影，冰壶莹、真无价。\n闻道水晶宫殿，蕙炉薰、珠帘高挂。\n琼枝半倚，瑶觞更劝，莺娇燕姹。\n目断魂飞，翠萦红绕，空吟小砑。\n想归来醉里，鸾篦凤朵，倩何人卸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1813, '蓦山溪', '李之仪', '神仙院宇，记得春归後。\n蜂蝶不胜闲，惹残香、萦纡深透。\n玉徽指稳，别是一般情，方永昼。\n因谁瘦。\n都为天然秀。\n桐阴未减，独自携芳酎。\n再弄想前欢，拊金樽、何时似旧。\n凭谁说与，潘鬓转添霜，飞陇首。\n云将皱。\n应念相思久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1814, '蓦山溪', '李之仪', '金柔火老，欲避几无地。\n谁借一檐风，锁幽香、清邃。\n瑶阶珠砌，如膜遇金篦，流水外，落花前，岂是人能致。\n擘鳞泛玉，笑语皆真类。\n惆怅月边人，驾云、何方适意。\n么弦咽处，空感旧时声，兰易歇，恨偏长，魂断成何事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1815, '蓦山溪', '李之仪', '蛾眉亭上，今日交冬至。\n已报一阳生，更佳雪、因时呈瑞。\n匀飞密舞，都是散天花，山不见，水如山，浑在冰壶里。\n平生选胜，到此非容易。\n弄月与燃犀，漫劳神、徒能惊世。\n争如此际，天意巧相符，须痛饮，庆难逢，莫诉厌厌醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1816, '蓦山溪', '李之仪', '晚来寒甚，密雪穿庭户。\n如在广寒宫，惊满目、瑶林琼树。\n佳人乘兴，应是得欢多，泛新声，催金盏，别有留心处。\n争知这里，没个人言语。\n拨尽火边灰，搅愁肠、飞花舞絮。\n凭谁子细，说与此时情，欢暂歇，酒微醺，还解相思否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1817, '满庭芳', '李之仪', '一到江南，三逢此夜，举头羞见婵娟。\n黯然怀抱，特地遣谁宽。\n分外清光泼眼，迷漾、无计拘拦。\n天如洗，星河尽掩，全胜异时看。\n佳人，还忆否，年时此际，相见方难。\n谩红绫偷寄，孤被添寒。\n何事佳期再睹，翻怅望、重叠关山。\n归来呵，休教独自，肠断对团圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1818, '满庭芳', '李之仪', '花陌千条，珠帘十里，梦中还是扬州。\n月斜河汉，曾记醉歌楼。\n谁赋红绫小砑，因飞絮、天与风流。\n春常在，仙源路隔，空自泛渔舟。\n新秋。\n初雨过，龙团细碾，雪乳浮瓯。\n问殷勤何处，特地相留。\n应念长门赋罢，消渴甚、无物堪酬。\n情无尽，金扉玉榜，何日许重游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1819, '玉蝴蝶', '李之仪', '坐久灯花开尽，暗惊风叶，初报霜寒。\n冉冉年华催暮，颜色非丹。\n搅回肠、蛩吟似织，留恨意、月彩如摊。\n惨无欢。\n篆烟萦素，空转雕盘。\n何难。\n别来几日，信沈鱼鸟，情满关山。\n耳边依约，常记巧语绵蛮。\n聚愁窠、蜂房未密，倾泪眼、海水犹悭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1820, '早梅芳・喜迁莺', '李之仪', '雪初销，斗觉寒将变。\n已报梅梢暖。\n日边霜外，迤逦枝条自柔软。\n嫩苞匀点缀，绿萼轻裁剪。\n隐深心，未许清香散。\n渐融和，开欲遍。\n密处疑无间。\n天然标韵，不与群花斗深浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1821, '谢池春', '李之仪', '残寒销尽，疏雨过、清明後。\n花径敛馀红，风沼萦新皱。\n乳燕穿庭户，飞絮沾襟袖。\n正佳时，仍晚昼。\n著人滋味，真个浓如酒。\n频移带眼，空只恁、厌厌瘦。\n不见又思量，见了还依旧。\n为问频相见，何似长相守。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1822, '怨三三', '李之仪', '清溪一派泻揉蓝。\n岸草毵毵。\n记得黄鹂语画檐。\n唤狂里、醉重三。\n春风不动垂帘。\n似三五、初圆素蟾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1823, '春光好', '李之仪', '霜压晓，月收阴。\n斗寒深。\n看尽烛花金鸭冷，卷残衾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1824, '千秋岁', '李之仪', '深帘静昼。\n绰约闺房秀。\n叩衣楚制飞文绣。\n凝脂肤理腻，削玉腰围瘦。\n闲舞袖。\n回身昵语凭肩久。\n眉压横波皱。\n歌断青青柳。\n钗遽擘，壶频叩。\n鬓凄清镜雪，泪涨芳樽酒。\n难再偶。\n沈沈梦峡雪归後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1825, '千秋岁', '李之仪', '柔肠寸折。\n解袂留清血。\n蓝桥动是经年别。\n掩门春絮乱，枕秋蛩咽。\n檀篆灭。\n鸳衾半拥空床月。\n妆镜分来缺。\n尘污菱花洁。\n嘶骑远，鸣机歇。\n密封书锦字，巧绾香囊结。\n芳信绝。\n东风半落梅梢雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1826, '千秋岁', '李之仪', '万红暄昼。\n占尽人间秀。\n怎生图画如何绣。\n宜推萧史伴，消得东阳瘦。\n垂窄袖。\n花前镇忆相携久。\n泪回纹皱。\n好在章台柳。\n洞户隔，凭谁叩。\n寄声虽有雁，会面难同酒。\n无计偶。\n萧萧暮雨黄昏後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1827, '千秋岁', '李之仪', '休嗟磨折。\n看取罗巾血。\n殷勤且话经年别。\n庭花番怅望，檐雨同呜咽。\n明半灭。\n灯光夜夜多如月。\n无复伤离缺。\n共保冰霜洁。\n不断梦，从今歇。\n收回书上絮，解尽眉头结。\n犹未绝。\n金徽泛处应能雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1828, '千秋岁', '李之仪', '中秋才过，又是重阳到。\n露乍冷，寒将报。\n绿香摧渚芰，黄密攒庭草。\n人未老。\n蓝桥漫促霜砧捣。\n照影兰缸晕，破户银蟾小。\n樽在眼，从谁倒。\n强铺同处被，愁却欢时帽。\n须信道。\n狂心未歇情难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1829, '千秋岁', '李之仪', '深秋庭院，残暑全消退。\n天幕迥，云容碎。\n地偏人罕到，风惨寒微带。\n初睡起，翩翩戏蝶飞成对。\n叹息谁能会。\n犹记逢倾盖。\n情暂遣，心常在。\n沈沈音信断，冉冉光阴改。\n红日晚，仙山路隔空云海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1830, '临江仙', '李之仪', '知有阆风花解语，从来只许传闻。\n光明休咏汉宫新。\n拥身疑有月，衬步恨无云。\n莫把金樽容易劝，坐来几度销魂。\n不知仙骨在何人。\n好将千岁日，占断四时春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1831, '临江仙', '李之仪', '九十日春都过了，寻常偶到江皋。\n水容山态两相饶。\n草平天一色，风暖燕双高。\n酒病厌厌何计那，飞红更送无聊。\n莺声又似耳边娇。\n难回巫峡梦，空恨武陵桃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1832, '江神子・江城子', '李之仪', '恼人天气雪消时。\n落梅飞。\n日初迟。\n小阁幽窗，时节听黄鹂。\n新洗头来娇困甚，才试著，夹罗衣。\n木梨花拂淡燕脂。\n翠云。\n敛双眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1833, '江神子・江城子', '李之仪', '今宵莫惜醉颜红。\n十分中。\n且从容。\n须信欢情，回首似旋风。\n流落天涯头白也，难得是，再相逢。\n十年南北感征鸿。\n恨应同。\n苦重重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1834, '江神子・江城子', '李之仪', '阑干掐遍等新红。\n酒频中。\n恨匆匆。\n投得花开，还报夜来风。\n惆怅春光留不住，又何似，莫相逢。\n月窗何处想归鸿。\n与谁同。\n意千重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1835, '清平乐', '李之仪', '西江霜後，万点暄晴昼。\n璀璨寄来光欲溜。\n正值文君病酒。\n画屏斜倚窗纱。\n睡痕犹带朝霞。\n为问清香绝韵，何如解语梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1836, '清平乐', '李之仪', '萧萧风叶。\n似与更声接。\n欲寄明非为怯。\n梦断兰舟桂楫。\n学书只写鸳鸯。\n却应无奈愁肠。\n安得一双飞去，春风芳草池塘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1837, '清平乐', '李之仪', '殷勤仙友。\n劝我千年酒。\n一曲履霜谁与奏。\n邂逅麻姑妙手。\n坐来休叹尘劳。\n相逢难似今朝。\n不待亲移玉指，自然痒处都消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1838, '清平乐', '李之仪', '当时命友。\n曾借邻家酒。\n旧曲不知何处奏。\n梦断空思纤手。\n却应去路非遥。\n今朝还有明朝。\n谩道人能化石，须知石被人消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1839, '清平乐', '李之仪', '仙家庭院。\n红日看看晚。\n一朵梅花挨枕畔。\n玉指几回拈看。\n拥衾不比寻常。\n天涯无限思量。\n看了又还重嗅，分明不为清香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1840, '浪淘沙', '李之仪', '霞卷与云舒。\n月淡星疏。\n摩徽转轸不曾虚。\n弹到当时留意处，谁是相如。\n魂断酒家垆。\n路隔云衢。\n舞鸾镜里早妆初。\n拟学画眉张内史，略借功夫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1841, '卜算子', '李之仪', '我住长江头，君住长江尾。\n日日思君不见君，共饮长江水。\n此水几时休，此恨何时已。\n只愿君心似我心，定不负相思意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1842, '忆秦娥', '李之仪', '清溪咽。\n霜风洗出山头月。\n山头月。\n迎得云归，还送云别。\n不知今是何时节。\n凌望断音尘绝。\n音尘绝。\n帆来帆去，天际双阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1843, '蝶恋花', '李之仪', '天淡云闲晴昼永。\n庭户深沈，满地梧桐影。\n骨冷魂清如梦醒。\n梦回犹是前时景。\n取次杯盘催酩酊。\n醉帽频，又被风吹正。\n踏月归来人已静。\n恍疑身在蓬莱顶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1844, '蝶恋花', '李之仪', '玉骨冰肌天所赋。\n似与神仙，来作烟霞侣。\n枕畔拈来亲手付。\n书窗终日常相顾。\n几度离披留不住。\n依旧清香，只欠能言语。\n再送神仙须爱护。\n他时却待亲来取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1845, '蝶恋花', '李之仪', '万事都归一梦了。\n曾向邯郸，枕上教知道。\n百岁年光谁得到。\n其间忧患知多少。\n无事且频开口笑。\n纵酒狂歌，销遣闲烦恼。\n金谷繁华春正好。\n玉山一任樽前倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1846, '蝶恋花', '李之仪', '为爱梅花如粉面。\n天与功夫，不似人间见。\n几度拈来亲比看。\n功夫却是花枝浅。\n觅得归来临几砚。\n尽日相看，默默情无限。\n更不嗅时须百遍。\n分明销得人肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1847, '浣溪沙', '李之仪', '剪水开头碧玉条。\n能令江汉客魂销。\n只应香信是春潮。\n戴了又羞缘我老，折来同嗅许谁招。\n凭将此意问妖娆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1848, '浣溪沙', '李之仪', '玉室金堂不动尘。\n林梢绿遍已无春。\n清和佳思一番新。\n道骨仙风云外侣，烟鬟雾鬓月边人。\n何妨沈醉到黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1849, '浣溪沙', '李之仪', '依旧琅不染尘。\n霜风吹断笑时春。\n一簪华发为谁新。\n白雪幽兰犹有韵，鹊桥星渚可无人。\n金莲移处任尘昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1850, '浣溪沙', '李之仪', '昨日霜风入绛帷。\n曲房深院绣帘垂。\n屏风几曲画生枝。\n酒韵渐浓欢渐密，罗衣初试漏初迟。\n已凉天气未寒时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1851, '西江月', '李之仪', '昨夜十分霜重，晓来千里书传。\n吴山秀处洞庭边。\n不夜星垂初遍。\n好事寄来禅侣，多情将送琴仙。\n为怜佳果称婵娟。\n一笑聊回媚眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1852, '西江月', '李之仪', '醉透香浓斗帐，灯深月浅回廊。\n当时背面两伥伥。\n何况临风怀想。\n舞柳经春祗瘦，游丝到地能长。\n鸳鸯半调已无肠。\n忍把么弦再上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1853, '西江月', '李之仪', '念念欲归未得，迢迢此去何求。\n都缘一点在心头。\n忘了霜朝雪後。\n要见有时有梦，相思无处无愁。\n小窗若得再绸缪。\n应记如今时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1854, '鹊桥仙', '李之仪', '风清月莹，天然标韵，自是闺房之秀。\n情多无那不能禁，常是为、而今时候。\n绿云低拢，红潮微上，画幕梅寒初透。\n一般偏更恼人深，时更把、眉儿轻皱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1855, '西江月', '李之仪', '宿云收尽，纤尘不警，万里银河低挂。\n清冥风露不胜寒，无计学、双鸾并驾。\n玉徽声断，宝钗香远，空赋红绫小砑。\n庾郎知有几多愁，怎奈向、月明今夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1856, '踏莎行', '李之仪', '绿遍东山，寒归西渡。\n分明认得春来处。\n风轻雨细更愁人，高唐何在空朝暮。\n离恨相寻，酒狂无素。\n柳条又折年时数。\n一番情味有谁知，断魂还送征帆去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1857, '踏莎行', '李之仪', '还是归来，依前问渡。\n好风引到经行处。\n几声啼鸟又催耕，草长柳暗春将暮。\n潦倒无成，疏慵有素。\n且陪野老酬天数。\n多情惟有面前山，不随潮水来还去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1858, '鹧鸪天', '李之仪', '节是重阳却斗寒。\n可堪风雨累寻欢。\n虽辜早菊同高柳，聊楫残蕉共小栏。\n浮蚁嫩，炷烟盘。\n恨无莺唱舞催鸾。\n空惊绝韵天边落，不许韶颜梦里看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1859, '鹧鸪天', '李之仪', '浓丽妖妍不是妆。\n十分风艳夺韶光。\n牡丹开就应难比，繁富犹疑过海棠。\n须仔细，更端相。\n烂霞梳晕带朝阳。\n千金未足酬真赏，一度相看一断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1860, '鹧鸪天', '李之仪', '避暑佳人不著妆。\n水晶冠子薄罗裳。\n摩绵扑粉飞琼屑，滤蜜调冰结绛霜。\n随定我，小兰堂。\n金盆盛水绕牙床。\n时时浸手心头熨，受尽无人知处凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1861, '鹧鸪天', '李之仪', '收尽微风不见江。\n分明天水共澄光。\n由来好处输闲地，堪叹人生有底忙。\n心既远，味偏长。\n须知粗布胜无裳。\n从今认得归田乐，何必桃源是故乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1862, '朝中措', '李之仪', '腊穷天际傍危栏。\n密雪舞初残。\n表里江山如画，分明不似人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1863, '朝中措', '李之仪', '暮山环翠绕层栏。\n时节岁将残。\n远雁不传家信，空能嘹唳人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1864, '朝中措', '李之仪', '翰林豪放绝勾栏。\n风月敢雕残。\n一旦荆溪仙子，笔头唤聚时间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1865, '阮郎归', '李之仪', '朱唇玉羽下蓬莱。\n佳时近早梅。\n惜花情味久安排。\n枝头开未开。\n魂欲断，恨难裁。\n香心休见猜。\n果知何逊是仙才。\n何妨入梦来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1866, '采桑子', '李之仪', '相逢未几还相别，此恨难同。\n细雨。\n一片离愁醉眼中。\n明朝去路云宵外，欲见无从。\n满袂仙风。\n空托双凫作信鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1867, '如梦令', '李之仪', '回首芜城旧苑。\n还是翠深红浅。\n春意已无多，斜日满帘飞燕。\n不见。\n不见。\n门掩落花庭院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1868, '临江仙', '李之仪', '偶向凌台上望，春光已过三分。\n江山重叠倍销魂。\n风花飞有态，烟絮醉无痕。\n已是年来伤感甚，那堪旧恨仍存。\n清愁满眼共谁论。\n却应台下草，不解忆王孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1869, '临江仙', '李之仪', '难得今朝风日好，春光佳思平分。\n虽然公子暗招魂。\n其如抬眼看，都是旧时痕。\n酒到强寻欢日路，坐来谁为温存。\n落花流水不堪论。\n何时弦上意，重为拂桐孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1870, '丑奴儿・采桑子', '李之仪', '春风似有灯前约，先报佳期。\n点缀相宜。\n天气犹寒蝶未知。\n嫩黄染就蜂鬓巧，香压团枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1871, '青玉案', '李之仪', '小篷又泛曾行路。\n这身世、如何去。\n去了还来知几度。\n多情山色，有情江水，笑我归无处。\n夕阳杳杳还催暮。\n练净空吟谢郎句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1872, '更漏子', '李之仪', '暑方烦，人似愠。\n怅望林泉幽峻。\n情会处，景偏长。\n心清闻妙香。\n宝幢低，金锁碎。\n竹影桐印窗外。\n新事旧，旧愁新。\n空嗟不见人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1873, '渔家傲', '李之仪', '洗尽秋容天似莹。\n星稀月淡人初静。\n策杖萦纡寻远径。\n披昏暝。\n堤边犊母闲相并。\n遥想去舟魂欲凝。\n一番佳思从谁咏。\n憔悴归来如独醒。\n知何境。\n沈沈但觉烟村迥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1874, '南乡子', '李之仪', '春後雨馀天。\n娅姹黄鹂胜品弦。\n榴叶千灯初报暑，阶前。\n只有茶瓯味最便。\n身世几蹁跹。\n自觉年来更可怜。\n欲问此情何所似，缘延。\n看取窗间坠柳绵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1875, '南乡子', '李之仪', '绿水满池塘。\n点水蜻蜓避燕忙。\n杏子压枝黄半熟，邻墙。\n风送荷花几阵香。\n角簟衬牙床。\n汗透鲛绡昼影长。\n点滴芭蕉疏雨过，微凉。\n画角悠悠送夕阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1876, '南乡子', '李之仪', '睡起绕回塘。\n不见衔泥燕子忙。\n前日花梢都绿遍，西墙。\n犹有轻风递暗香。\n步懒恰寻床。\n卧看游丝到地长。\n自恨无聊常病酒，凄凉。\n岂有才情似沈阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1877, '南乡子', '李之仪', '小雨湿黄昏。\n重午佳辰独掩门。\n巢燕引雏浑去尽，销魂。\n空向梁间觅宿痕。\n客舍宛如村。\n好事无人载一樽。\n唯有莺声知此恨，殷勤。\n恰似当时枕上闻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1878, '南乡子', '李之仪', '泪眼转天昏。\n去路迢迢隔九门。\n角黍满盘无意举，凝魂。\n不为当时泽畔痕。\n肠断武陵村。\n骨冷难同月下樽。\n强泛菖蒲酬令节，空勤。\n风叶萧萧不忍闻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1879, '蓦山溪', '李之仪', '青楼薄，已分终难偶。\n寻遍绮罗间，悄无个、眼中翘秀。\n江南春晓，花发乱莺飞，情渐透。\n休辞瘦。\n果有人相候。\n醉乡路稳，常是身偏後。\n谁谓正欢时，把相思、番成红豆。\n千言万语，毕竟总成虚，章台柳。\n青青否。\n魂梦空搔首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1880, '减字木兰花', '李之仪', '乱魂无据。\n黯黯只寻来处路。\n灯尽花残。\n不觉长更又向阑。\n几回枕上。\n那件不曾留梦想。\n变尽星星。\n一滴秋霖是一茎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1881, '减字木兰花', '李之仪', '堤长春晚。\n冉冉浑如云外见。\n欲语无门。\n略许莺声隔岸闻。\n锦屏绣幌。\n犹待归来留一饷。\n何事迟迟。\n直恐游丝惹住伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1882, '减字木兰花', '李之仪', '触涂是碍。\n一任浮沈何必改。\n有个人人。\n自说居尘不染尘。\n谩夸千手。\n千物执持都是有。\n气候融怡。\n还取青天白日时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1883, '减字木兰花', '李之仪', '莫非魔境。\n强向中间谈独醒。\n一叶才飞。\n便觉年华太半归。\n醉云可矣。\n认著依前还不是。\n虚过今春。\n有愧斜川得意人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1884, '减字木兰花', '李之仪', '揉花催柳。\n一夜阴风几破牖。\n平晓无云。\n依旧光明一片春。\n掀衣起走。\n欲助喜欢须是酒。\n惆怅空樽。\n拟就王孙借十分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1885, '天门谣', '李之仪', '天堑休论险。\n尽远目、与天俱占。\n山水敛。\n称霜晴披览。\n正风静云闲、平潋滟。\n想见高吟名不滥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1886, '好事近', '李之仪', '相见两无言，愁恨又还千叠。\n别有恼人深处，在懵腾双睫。\n七弦虽妙不须弹，惟愿醉香颊。\n只恐近来情绪，似风前秋叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1887, '减字木兰花', '李之仪', '春到雨初晴，正是小楼时节。\n柳眼向人微笑，傍阑干堪折。\n暮山浓淡锁烟霏，梅杏半明灭。\n玉莫辞沈醉，待归时斜月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1888, '减字木兰花', '李之仪', '上尽玉梯云，还见一番佳节。\n惆怅旧时行处，把青青轻折。\n倚阑人醉欲黄昏，飞鸟望中灭。\n天面碧琉璃上，印弯弯新月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1889, '浣溪沙', '李之仪', '龟坼沟塍草压堤。\n三农终日望云霓。\n一番甘雨报佳时。\n闻道醉乡新占断，更开诗社互排。\n此时空恨隔云泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1890, '浣溪沙', '李之仪', '雨暗轩窗昼易昏。\n强纤手浴金盆。\n却因凉思谢飞蚊。\n酒量羡君如鹄举，寒乡怜我似鸱蹲。\n由来同是一乾坤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1891, '浣溪沙', '李之仪', '声名自昔犹时鸟，日月何尝避覆盆。\n是非都付鬓边蚊。\n邂逅风雷终有用，低回囊槛要深蹲。\n酒中聊复比乾坤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1892, '菩萨蛮', '李之仪', '五云深处蓬山杳。\n寒轻雾重银蟾小。\n枕上挹馀香。\n春风归路长。\n雁来书不到。\n人静重门悄。\n一阵落花风。\n云山千万重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1893, '菩萨蛮', '李之仪', '青梅又是花时节。\n粉墙闲把青梅折。\n玉镫偶逢君。\n春情如乱云。\n藕丝牵不断。\n谁信朱颜换。\n莫厌十分斟。\n酒深情更深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1894, '雨中花令', '李之仪', '休把身心就。\n著便醉人如酒。\n富贵功名虽有味，毕竟因谁守。\n看取刀头切藕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1895, '雨中花令', '李之仪', '点缀叶间如绣。\n开傍小春时候。\n莫把幽兰容易比，都占尽、人间秀。\n信是眼前稀有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1896, '留春令', '李之仪', '梦断难寻，酒醒犹困，那堪春暮。\n香阁深沈，红窗翠暗，莫羡颠狂絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1897, '踏莎行', '李之仪', '紫燕衔泥，黄莺唤友。\n可人春色暄晴昼。\n王孙一去杳无音，断肠最是黄昏後。\n宝髻慵梳，玉钗斜溜。\n凭阑目断空回首。\n薄情何事不归来，谩教折尽庭前柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1898, '踏莎行', '李之仪', '一别芳容，五经寒暑。\n回文欲寄无鳞羽。\n多情犹自梦中来，向人粉泪流如雨。\n梦破南窗，愁肠万缕。\n那听角动城头鼓。\n人生弹指事成空，断魂惆怅无寻处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1899, '南乡子', '李之仪', '夜雨滴空阶。\n想见尊前赋咏才。\n更觉鸣蛙如鼓吹，安排。\n惆怅流光去不回。\n万事已成灰。\n只这些儿尚满怀。\n刚被北风吹晓角，相催。\n不许时间入梦来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1900, '万年欢', '李之仪', '暖律才中，正莺喉竞巧，燕语新成。\n万绿阴浓，全无一点芳尘。\n门巷朝来报喜，庆佳期、此日光荣。\n开华宴、交酌琼酥，共祝鹤算椿龄。\n须知最难得处，双双凤翼，一对和鸣。\n造化无私，谁教特地多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1901, '朝中措', '李之仪', '新开湖水浸遥天。\n风叶响珊珊。\n记得昔游情味，浩歌不怕朝寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1902, '朝中措', '李之仪', '败荷枯苇夕阳天。\n时节渐阑珊。\n独泛扁舟归去，老来不耐霜寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1903, '临江仙', '李之仪', '初破晓寒无限思，融融腊意全迷。\n春工从此被人知。\n不随蜂蝶，长伴玉蟾低。\n缥缈云间应好在，盈盈泪湿征衣。\n背人偷拗向东枝。\n清香满袖，犹记画堂西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1904, '临江仙', '李之仪', '病里不知春早晚，惊心绿暗红稀。\n起来初拭薄罗衣。\n多情海燕，还傍旧梁飞。\n瘦损休文谁记得，空将销臂频围。\n眼前都是去年时。\n不堪追想，魂断画楼西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1905, '蝶恋花', '李之仪', '帘外飞花湖上语。\n不恨花飞，只恨人难住。\n多谢雨来留得住。\n看看却恐晴催去。\n寸寸离肠须会取。\n今日宁宁，明日从谁诉。\n怎得此身如去路。\n迢迢长在君行处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1906, '失调名', '蔡确', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1907, '惜黄花', '许将', '雁声晚断。\n寒宵云卷。\n正一枝开，风前看，月下见。\n花占千花上，香笑千香浅。\n化工与、最先裁翦。\n谁把瑶林，闲抛江岸。\n恁素英浓，芳心细，意何限。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1908, '临江仙', '许将', '圣主临轩亲策试，集英佳气葱葱。\n鸣鞘声震未央宫。\n卷帘龙影动，挥翰御烟浓。\n上第归来何事好，迎人花面争红。\n蓝袍香散六街风。\n一鞭春色里，骄损玉花骢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1909, '临江仙', '郑无党', '不比寻常三五夜，万家齐望清辉。\n烂银盘透碧琉璃。\n莫辞终夕看，动是隔年期。\n试问嫦娥还记否，玉人曾折高枝。\n明年此夜再圆时。\n合开东府宴，身在凤凰池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1910, '无愁可解', '陈', '光景百年，看便一世。\n生来不识愁味。\n问愁何处来，更开解个甚底。\n万事从来风过耳。\n何用不著心里。\n你唤做、展却眉头，便是达者，也则恐未。\n此理。\n本不通言，何曾道、欢游胜如名利。\n道即浑是错，不道如何即是。\n这里元无我与你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1911, '调啸・调笑令', '苏辙', '渔父。\n渔父。\n水上微风细雨。\n青蓑黄箬裳衣。\n红酒白鱼暮归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1912, '调啸・调笑令', '苏辙', '归雁。\n归雁。\n饮啄江南南岸。\n将飞却下盘桓。\n塞北春来苦寒。\n苦寒。\n苦寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1913, '水调歌头', '苏辙', '离别一何久，七度过中秋。\n去年东武今夕，明月不胜愁。\n岂意彭城山下，同泛清河古汴，船上载凉州。\n鼓吹助清赏，鸿雁起汀洲。\n坐中客，翠羽帔，紫绮裘。\n素娥无赖，西去曾不为人留。\n今夜清尊对客，明夜孤帆水驿，依旧照离忧。\n但恐同王粲，相对永登楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1914, '渔家傲', '苏辙', '七十馀年真一梦。\n朝来寿儿孙奉。\n忧患已空无复痛。\n心不动。\n此间自有千钧重。\n早岁文章供世用。\n中年禅味疑天纵。\n石塔成时无一缝。\n谁与共。\n人间天上随他送。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1915, '沁园春', '陈睦', '小雪初晴，画舫明月，强饮未眠。\n念翠鬟双耸，舞衣半卷，琵琶催拍，促管危弦。\n密意虽具，欢期难偶，遣我离情愁绪牵。\n追思处，奈溪桥道窄，无计留连。\n天天。\n莫是前缘。\n自别後、深诚谁为传。\n想玉篦偷付，珠囊暗解，两心长在，须合金钿。\n浅淡精神，温柔情性，记我疏狂应痛怜。\n空肠断，奈衾寒漏永，终夜如年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1916, '清平乐', '陈睦', '鬓云斜坠。\n莲步弯弯细。\n笑脸双蛾生多媚。\n百步兰麝香喷。\n从前万种愁烦。\n枕边未可明言。\n好是蓝桥再渡，玉篦还胜金钿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1917, '玉楼春', '马成', '来时吴会犹残暑。\n去日武林春已暮。\n欲知遗爱感人深，洒泪多於江上雨。\n欢情未举眉先聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1918, '满江红', '李婴', '荆楚风烟，寂寞近、中秋时候。\n露下冷、兰英将谢，苇花初秀。\n归燕殷勤辞巷陌，鸣蛩凄楚来窗牖。\n又谁念、江边有神仙，飘零久。\n横琴膝，携筇手。\n旷望眼，闲吟口。\n任纷纷万事，到头何有。\n君不见、凌烟冠剑客，何人气貌长依旧。\n归去来、一曲为君吟，为君寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1919, '菩萨蛮', '王齐愈', '玉肌香衬冰丝。\n丝冰衬香肌玉。\n纤指拂眉尖。\n尖眉拂指纤。\n巧裁罗袜小。\n小袜罗裁巧。\n移步看尘飞。\n飞尘看步移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1920, '菩萨蛮', '王齐愈', '吼雷催雨飞沙走。\n走沙飞雨催雷吼。\n波涨泻倾河。\n河倾泻涨波。\n幌纱凉气爽。\n爽气凉纱幌。\n幽梦觉仙游。\n游仙觉梦幽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1921, '菩萨蛮', '王齐愈', '兽喷香缕飞长昼。\n昼长飞缕香喷兽。\n迎日喜葵倾。\n倾葵喜日迎。\n卷帘双舞燕。\n燕舞双帘卷。\n清簟枕钗横。\n横钗枕簟清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1922, '菩萨蛮', '王齐愈', '远香风递莲湖满。\n满湖莲递风香远。\n光鉴试新妆。\n妆新试鉴光。\n棹穿花处好。\n好处花穿棹。\n明月咏歌清。\n清歌咏月明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1923, '菩萨蛮', '王齐愈', '酒中愁说人留久。\n久留人说愁中酒。\n归梦要迟迟。\n迟迟要梦归。\n旧衣香染袖。\n袖染香衣旧。\n封短托飞鸿。\n鸿飞托短封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1924, '菩萨蛮', '王齐愈', '老人愁叹惊年早。\n早年惊叹愁人老。\n霜点鬓苍苍。\n苍苍鬓点霜。\n酒杯停欲久。\n久欲停杯酒。\n杯酒唤眉开。\n开眉唤酒杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1925, '菩萨蛮', '王齐愈', '暑烦人困初时午。\n午时初困人烦暑。\n新诗得酒因。\n因酒得诗新。\n缕金歌眉举。\n举眉歌金缕。\n人妒月圆频。\n频圆月妒人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1926, '虞美人', '王齐愈', '黄金柳嫩摇丝软。\n永日堂堂掩。\n卷帘飞燕未归来。\n客去醉眠枕、残杯。\n眉山浅拂青螺黛。\n整整垂双带。\n水沈香熨窄衫轻。\n莹玉碧溪春溜、眼波横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1927, '望江南・忆江南', '王齐叟', '居下位，常恐被人谗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1928, '失调名', '王齐叟', '蹙绣圈金，囊密约，未赴意先警。\n欲罢还休，临行又怯，倚定画栏痴等。\n帘风渐冷。\n先自虑、春宵不永。\n更那堪、斗转星移，尚在有无之境。\n绿云满压蝤蛴领。\n惭愧也、满怀香拥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1929, '点绛唇', '舒氏', '独自临池，闷来强把阑干凭。\n旧愁新恨。\n耗却年时兴。\n鹭散鱼潜，烟敛风初定。\n波心静。\n照人如镜。\n少个年时影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1930, '满庭芳', '琴操', '山抹微云，天连衰草，画角声断斜阳。\n暂停征辔，聊共饮离觞。\n多少蓬莱旧侣，频回首、烟霭茫茫。\n孤村里，寒鸦万点，流水绕红墙。\n魂伤。\n当此际，轻分罗带，暗解香囊。\n谩赢得，青楼薄名狂。\n此去何时见也，襟袖上、空有馀香。\n伤心处，高城望断，灯火已昏黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1931, '卜算子', '琴操', '欲整别离情，怯对尊中酒。\n野梵幽幽石上飘，搴落楼头柳。\n不系黄金绶。\n粉黛愁成垢。\n春风三月有时阑，遮不尽、梨花丑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1932, '临江仙', '舒づ', '折柳门前鹦鹉绿，河梁小驻归船。\n不堪华发对离筵。\n孤村啼日，深院落花天。\n文采弟兄真叠玉，赤宵去路谁先。\n明朝便恐各风烟。\n江山如有恨，桃李自无言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1933, '点绛唇', '舒づ', '紫雾香浓，岁华风转花随辇。\n洞天云暖。\n一片笙歌远。\n水殿龙舟，忆侍瑶池宴。\n闲庭院。\n梦回春半。\n雪鬓无人见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1934, '散天花', '舒づ', '云断长空叶落秋。\n寒江烟浪静，月随舟。\n西风偏解送离愁。\n声声南去雁，下汀洲。\n无奈多情去复留。\n骊歌齐唱罢，泪争流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1935, '醉花阴', '舒づ', '露芽初破云腴细。\n玉纤纤亲试。\n香雪透金瓶，无限仙风，月下人微醉。\n相如消渴无佳思。\n了知君此意。\n不信老卢郎，花底春寒，赢得空无睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1936, '醉花阴', '舒づ', '月幌风帘香一阵。\n正千山雪尽。\n冷对酒尊傍，无语含情，别是江南信。\n寿阳妆罢人微困。\n更玉钗斜衬。\n拟插一枝归，只恐风流，羞上潘郎鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1937, '虞美人', '舒づ', '芙蓉落尽天涵水。\n日暮沧波起。\n背飞双燕帖云寒。\n独向小楼东畔、倚阑看。\n浮生只合尊前老。\n雪满长安道。\n故人早晚上高台。\n赠我江南春色、一枝梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1938, '虞美人', '舒づ', '酒边陡觉罗衣暖。\n独倚黄昏看。\n寒鸦两两下楼东。\n著处暗云垂地、一重重。\n红炉欢坐谁能醉。\n多少看花意。\n谢娘也拟春风。\n便道无端柳絮、逼帘栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1939, '虞美人', '舒づ', '重帘小阁香云暖。\n黛拂梳妆浅。\n玉箫一曲杜韦娘。\n谁是苏州刺史、断人肠。\n醉归旋拨红炉火。\n却倚屏山坐。\n银缸明灭月横斜。\n还是画楼角送、小梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1940, '丑奴儿・采桑子', '舒づ', '一池秋水疏星动，寒影横斜。\n满坐风花。\n红烛纷纷透绛纱。\n江湖散诞扁舟里，到处如家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1941, '一落索', '舒づ', '正是看花天气。\n为春一醉。\n醉来却不带花归，诮不解、看花意。\n试问此花明媚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1942, '一落索', '舒づ', '叶底枝头红小。\n天然窈窕。\n後园桃李谩成蹊，问占得、春多少。\n不管雪消霜晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1943, '满庭芳', '舒づ', '寒日穿帘，澄江凭槛，练光浮动馀霞。\n蓼汀芦岸，黄叶衬孤花。\n天外征帆隐隐，残云共、流水无涯。\n登临处，琼枝潋滟，风帽醉斜。\n丰年，时节好，玉香田舍，酒满渔家。\n算浮世劳生，事事输他。\n便恁从今酩酊，休更问、白雪笼纱。\n还须仗，神仙妙手，传向画图夸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1944, '满庭芳', '舒づ', '红叶飘零，寒烟疏淡，楼台半在云间。\n望中风景，图画也应难。\n又是重阳过了，东篱下、黄菊阑珊。\n陶潜病，风流载酒，秋意与人闲。\n霞冠。\n倒处，瑶台唱罢，如梦中还。\n但醉里赢得，满眼青山。\n华发看看满也，留不住、当日朱颜。\n平生事，从头话了，独自却凭栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1945, '满庭芳', '舒づ', '阊阖天门，芙蓉春殿，几年目断鸡翘。\n短蓬秋鬓，端幸倚琼瑶。\n南圃花边小院，西湖畔、云低双桥。\n归时节，红香露冷，月影上芭蕉。\n明朝。\n那可望，旗亭烟草，柳渡寒潮。\n但万户千门，恨客歌樵。\n戏彩光浮衮绣，听鸣珂、响逼云宵。\n应回首，绮裘醉客，还是独吹箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1946, '卜算子', '舒づ', '池台小雨乾，门巷香轮少。\n谁把青钱衬落红，满地无人扫。\n何时斗草归，几度寻花了。\n留得佳人莲步痕，宫样鞋儿小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1947, '菩萨蛮', '舒づ', '三年江上风吹泪。\n夭桃艳杏无春意。\n今日欲开眉。\n那堪更别离。\n莫折长亭柳。\n折尽愁依旧。\n只有醉如狂。\n人生空断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1948, '菩萨蛮', '舒づ', '柳桥花坞南城陌。\n朱颜绿发长安路。\n雨後小池台。\n寻常载酒来。\n马头今日路。\n却望城西去。\n斜日下汀洲。\n断云和泪流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1949, '菩萨蛮', '舒づ', '画船槌鼓催君去。\n高楼把酒留君住。\n去住若为情。\n西江潮欲平。\n江潮容易得。\n只是人南北。\n今日此尊空。\n知君何日同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1950, '菩萨蛮', '舒づ', '画檐细雨偏红烛。\n疏星冷落排寒玉。\n赌得碧云篇。\n金波更涉船。\n樽前当日客。\n行色垂杨陌。\n天阔水悠悠。\n含情独倚楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1951, '菩萨蛮', '舒づ', '杜鹃啼破江南月。\n香风扑面吹红雪。\n赋就缕金笺。\n黄昏醉上船。\n年华爽短鬓。\n事往情何尽。\n明日各天涯。\n来春空好花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1952, '菩萨蛮', '舒づ', '朱帘乍卷层烟起。\n露华深浅初疑洗。\n困倚玉阑风。\n绮罗知几重。\n向人如有意。\n不醉何时醉。\n便得一枝红。\n犹胜两鬓空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1953, '菩萨蛮', '舒づ', '小池山额垂螺碧。\n绿红香里眠。\n波面翠云开。\n仙槎天上来。\n吹将红日落。\n懊恼严城角。\n风月此时情。\n知君华发生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1954, '菩萨蛮', '舒づ', '一回别後一回老。\n别离易得相逢少。\n莫问故园花。\n长安君是家。\n短亭秋日晚。\n草色随人远。\n欲醉又还醒。\n江楼暮角声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1955, '菩萨蛮', '舒づ', '樽前休话人生事。\n人生只合樽前醉。\n金盏大如船。\n江城风雪天。\n绮窗灯自语。\n一夜芭蕉雨。\n玉漏为谁长。\n枕衾残酒香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1956, '菩萨蛮', '舒づ', '楼前流水西江道。\n江头水落芙蓉老。\n画鼓叠凉波。\n凭栏颦翠娥。\n当年金马客。\n青鬓芦花色。\n把酒感秋蓬。\n骊歌半醉中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1957, '菩萨蛮', '舒づ', '绮栊深闭桃园曲。\n刘郎老向花间宿。\n笑脸抹流霞。\n心知是小琶。\n纤纤垂素玉。\n掠鬓春云绿。\n弹了醉思仙。\n小窗红日偏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1958, '菩萨蛮', '舒づ', '真珠酒滴琵琶送。\n行云旧识巫山梦。\n空得醉中归。\n老来心事非。\n江梅含日暖。\n照水花枝短。\n密叶似商量。\n向人春意长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1959, '菩萨蛮', '舒づ', '小亭露厌风枝动。\n鹊炉火冷金瓶冻。\n悄悄对西窗。\n瘦知罗带长。\n欲眠思酒。\n坐听寒更久。\n无赖是青灯。\n开花故故明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1960, '菩萨蛮', '舒づ', '流年又见风沙送。\n钧天回首清都梦。\n塞雁几时归。\n镜中双鬓非。\n绿袍同冷暖。\n谁道交情短。\n愁斛若为量。\n还随一线长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1961, '菩萨蛮', '舒づ', '白苹洲渚垂杨岸。\n藕花未放青蒲短。\n斜日画船归。\n背人双鹭飞。\n醉眠金马客。\n不道风尘隔。\n红影上窗纱。\n小庭空落花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1962, '菩萨蛮', '舒づ', '金船满引人微醉。\n红绡笼烛崔归骑。\n香泛雪盈杯。\n云龙疑梦回。\n不辞风满腋。\n旧是仙家客。\n坐得夜无眠。\n南窗衾枕寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1963, '菩萨蛮', '舒づ', '江梅未放枝头结。\n江楼已见山头雪。\n待得此花开。\n知君来不来。\n风帆双画。\n小雨随行色。\n空得郁金裙。\n酒痕和泪痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1964, '菩萨蛮', '舒づ', '香波绿暖浮鹦鹉。\n黄金捍拨么弦语。\n小雨落梧桐。\n帘栊残烛红。\n人生闲亦好。\n双鬓催人老。\n莫惜醉中归。\n醒来思醉时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1965, '菩萨蛮', '舒づ', '绿窗酒醒春如梦。\n小池犹见红云动。\n露湿井干桐。\n翠阴生细风。\n雨过芳塘净。\n清昼闲中永。\n门外立双旌。\n隔花闻笑声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1966, '菩萨蛮', '舒づ', '忆曾把酒赏红翠。\n舞腰柳弱歌声细。\n纵马杏园西。\n归来香满衣。\n宝车空犊驻。\n事逐孤鸿去。\n搔首立江干。\n春萝挂暮山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1967, '蝶恋花', '舒づ', '雪後江城红日晚。\n暖入香梢，渐觉玲珑满。\n仿佛临风妆半面。\n冰帘斜卷谁庭院。\n折向樽前君细看。\n便是江南，寄我人还远。\n手把此枝多少怨。\n小楼横笛吹肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1968, '蝶恋花', '舒づ', '深炷熏炉扃小院。\n手拈黄花，尚觉金犹浅。\n回首画堂双语燕。\n无情渐渐看人远。\n相见争如初不见。\n短鬓潘郎，斗觉年华换。\n最是西风吹不断。\n心头往事歌中怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1969, '减字木兰花', '舒づ', '眉山敛额。\n往事追思空手拍。\n雁字频飞。\n生怕人来说著伊。\n闲抛绣履。\n愁香衾浑不起。\n莫似扬州。\n只作寻常薄休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1970, '减字木兰花', '舒づ', '碎红如绣。\n摇曳东风垂彩绶。\n拟倩柔条。\n约住佳人细柳腰。\n蜀江春绿。\n争似枝头能结束。\n纤手攀时。\n欲绾同心寄与谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1971, '木兰花', '舒づ', '十二阑干褰画箔。\n取次穿花成小酌。\n彩鸾舞罢凤孤飞，回首东风空院落。\n杳杳桃源仙路邈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1972, '木兰花', '舒づ', '金丝络马青钱路。\n笑指玉皇香案去。\n点衣柳陌堕残红，拂面风桥吹细雨。\n晓钗压鬓头慵举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1973, '木兰花', '舒づ', '琉璃一片春湖面。\n画舫游人帘外见。\n水边风嫩柳低眠，花底雨乾莺细啭。\n秋千寂寂垂杨岸。\n芳草绿随人渐远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1974, '浣溪沙', '舒づ', '燕外青楼已禁烟。\n小寒犹自薄胜绵。\n画桥红日下秋千。\n惟有樽前芳意在，应须沈醉倒花前。\n绿窗还是五更天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1975, '浣溪沙', '舒づ', '金缕歌残红烛稀。\n梁州舞罢小鬟垂。\n酒醒还是独归时。\n画栋日高来语燕，绮窗风暖度游丝。\n几多落叶上青枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1976, '浣溪沙', '舒づ', '黑白纷纷小战争。\n几人心手斗纵横。\n谁知胜处本无情。\n谢傅老来思别墅，杜郎闲去忆鏖兵。\n何妨谈笑下辽城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1977, '浣溪沙', '舒づ', '雨洗秋空斜日红。\n青葱瑶辔玉玲珑。\n好风吹起□江东。\n且尽红裙歌一曲，莫辞白酒饮千锺。\n人生半在别离中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1978, '浣溪沙', '舒づ', '白鹭飞飞点碧塘。\n雨荷风卷绿罗裳。\n管弦竟奏杂鱼榔。\n游女谩能歌白，使君不学野鸳鸯。\n桃花空解误刘郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1979, '鹊桥仙', '舒づ', '教来歌舞，接成桃李。\n尽是使君指似。\n如今装就满城春，忍便拥、双旌归去。\n莺心巧啭，花心争吐。\n无计可留君住。\n两堤芳草一江云，早晚是、西楼望处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1980, '菩萨蛮', '舒づ', '疏英乍蕾馀寒浅。\n蹋枝小鹊娇犹颤。\n谩炷水沈香。\n帘波不是湘。\n清愁支酒力。\n畏听江城笛。\n恁忍说华年。\n垂垂欲暮天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1981, '好事近', '舒づ', '箫鼓却微寒，犹是芳菲时节。\n分付塞鸿归後，剩一钩寒月。\n双垂锦幄谢残枝，馀香恋衣结。\n又被鸟声呼醒，似征鞍催发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1982, '失调名', '舒づ', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1983, '导引', '范祖禹', '思齐文母，盛烈对皇天。\n演宝祚千年。\n卿云复旦治功全。\n厌人世登仙。\n龙舆忽掩三川。\n彩仗属车旋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1984, '六州', '范祖禹', '太平功。\n拥佑帝尧聪。\n歌九德，偃五戎。\n寰海被祥风。\n车书万里文轨同。\n自南北西东。\n耕田凿井，戏垂髫华发，跻仁寿域变时雍。\n大明方天中。\n弃养东朝苦匆匆。\n玉座如存，永隔慈容。\n恨难穷。\n崇庆空。\n飙轮仙驭无踪。\n超宇宙，驾云龙。\n翟掩轩宫。\n柏城王气长郁葱。\n温洛照寒崧。\n光灵在上，徽音流千古，昭如日月丽层穹。\n太任家邦隆。\n彤史青编永垂鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1985, '十二时・忆少年', '范祖禹', '转招摇。\n厚陵回望，双阙起。\n晓日丽谯。\n金爵上干霄。\n风雨阕，夜宫闭，不重朝。\n奉鸾镳渐遥。\n玉京知何处，飞英衔恤，乱絮缠悲，春路迢迢。\n缥缈哀音，发龙笳凤箫。\n光景同，惨淡度岩邑，指河桥。\n马萧萧。\n络绎星轺。\n拂天容卫，江海上寒潮。\n万国魂销。\n追昔御东朝。\n开钿扇，垂珠箔，侍貂。\n宝香烧。\n散飘。\n开仁寿域，神孙高拱，渤，玉烛方调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1986, '虞神歌', '范祖禹', '驾玉龙。\n设初虞祭终。\n前旌举，天回洛水，路转崧峰。\n瞻寥廓，烟霏冲融。\n无踪。\n震地鼓吹悲雄。\n谁何羽卫重。\n拂云旗帜眩青红。\n来渐东。\n清尘洒道，修职百神恭。\n回首苍茫醅雾雨吹风。\n掩泉宫。\n□□□□□□□□□寰畿入，山川改容。\n鼓钟临近次，千官望拜，涕泪衡从。\n人如堵，晨光葱茏。\n阙穹隆。\n驰道禁水相通。\n当年游幸空。\n皇仪事毕泣重瞳。\n哀未穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1987, '导引', '范祖禹', '延和幄座，临御九年中。\n往事已成空。\n皇基固覆盂四海，本自太任功。\n九虞初毕下西宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1988, '千秋岁', '孔平仲', '春风湖外。\n红杏花初退。\n孤馆静，愁肠碎。\n泪馀痕在枕，别久香销带。\n新睡起。\n小园戏蝶飞成对。\n惆怅人谁会。\n随处聊倾盖。\n情暂遣，心何在。\n锦书消息断，玉漏花阴改。\n迟日暮，仙山杳杳空云海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1989, '满庭芳', '了元', '鳞甲何多，羽毛无数，悟来佛性皆同。\n世人何事，刚爱口头浓。\n痛把群生割剖，刀头转、鲜血飞红。\n□□□，零炮碎炙，不忍见渠侬。\n喉咙。\n才咽罢，龙肝凤髓，毕竟无踪。\n谩赢得、生前夭寿多凶。\n奉劝世人省悟，休恣意、激恼阎翁。\n轮回转，本来面目，改换片时中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1990, '极相思令・极相思', '太尉夫人', '柳烟霁色方春。\n花露逼金茎。\n秋千院落，海棠渐老，才过清明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1991, '醉翁操', '郭祥正', '冷冷潺潺。\n寒泉。\n泻云间。\n如弹。\n醉翁洗心逃区寰。\n自期猿鹤俱闲。\n情未阑。\n日暮造深原。\n异芳谁与搴。\n忘还。\n琼楼玉阙，归去何年。\n遗风馀思，犹有猿吟鹤怨。\n花落溪边。\n萧然。\n莺语林中清圆。\n空山。\n春又残。\n客怀文章仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1992, '望江南・忆江南', '董', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1993, '望江南・忆江南', '董', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1994, '绛都春', '丁仙现', '融和又报。\n乍瑞霭霁色，皇州春早。\n翠竞飞，玉勒争驰都门道。\n鳌山彩结蓬莱岛。\n向晚色、双龙衔照。\n绛绡楼上，彤芝盖底，仰瞻天表。\n缥缈。\n风传帝乐，庆三殿共赏，群仙同到。\n迤逦御香，飘满人间闻嬉笑。\n须臾一点星球小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1995, '减字木兰花', '刘泾', '凭谁妙笔。\n横扫素缣三百尺。\n天下应无。\n此是钱塘湖上图。\n一般奇绝。\n云淡天高秋夜月。\n费尽丹青。\n只这些儿画不成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1996, '夏初临', '刘泾', '泛水新荷，舞风轻燕，园林夏日初长。\n庭树阴浓，雏莺学弄新簧。\n小桥飞如横塘。\n跨青苹、绿藻幽香。\n朱阑斜倚，霜纨未摇，衣袂先凉。\n歌欢稀遇，怨别多同，路遥水远，烟淡梅黄。\n轻衫短帽，相携洞府流觞。\n况有红妆。\n醉归来、宝蜡成行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1997, '桂枝香', '黄裳', '人烟一簇。\n正寄演，客飞升，翠微麓。\n楼阁参差，下瞰水天红绿。\n腰间剑去人安在，记千年、寸阴何速。\n山趋三岸，潭吞二水，岁丰人足。\n是处有、雕阑送目。\n更无限笙歌，芳酝初熟。\n休诧滕王看处，落霞孤鹜。\n雨中尤爱烟波上，见渔舟、来去相逐。\n数声歌向芦花，还疑是湘灵曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1998, '桂枝香', '黄裳', '插云翠壁。\n为送目，入遥空，见山色。\n金鼎丹成去也，晋朝高客。\n百花岩下遗孙在，赋何人、离尘风骨。\n翠微缘近，希夷志远，洞天踪迹。\n近剑有、为龙信息。\n怪潭上灵光，雷电相击。\n尤好风波乍霁，鹭汀斜日。\n倚栏白尽行人鬓，但沈沈、群岫凝碧。\n利名休事蝇头，飞送君南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (1999, '新荷叶', '黄裳', '落日衔山，行云载雨俄鸣。\n一顷新荷，坐间疑是秋声。\n烟波醉客，见快哉、风恼娉婷。\n香和清点，为人吹在衣襟。\n珠佩欢言，放船且向前汀。\n绿伞红幢，自从天汉相迎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2000, '渔家傲', '黄裳', '多幸春来云雨少。\n且教月与花相照。\n清色真香庭院悄。\n前事杳。\n还嗟此景何时了。\n莫道难逢开口笑。\n夜游须趁人年少。\n光泛雕栏寒料峭。\n迂步绕。\n不劳秉烛壶天晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2001, '渔家傲', '黄裳', '汗漫金华寒委地。\n火云散尽奇峰势。\n纨扇团圆休与比。\n犹可喜。\n恩情不怕凉飙至。\n梦冷魂高何处寄。\n琉璃砌上笼人睡。\n逃暑广寒宫似水。\n缘有累。\n乘风却下人间世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2002, '渔家傲', '黄裳', '人在月中宵汉远。\n仙槎乘得秋风便。\n寒信已归砧上练。\n衣未翦。\n疏窗空引相思怨。\n须信婵娟尤有恋。\n轻飞叶上清光转。\n寒菊枝头笼婉娈。\n人初宴。\n新妆更学铅华浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2003, '渔家傲', '黄裳', '三月秋光今夜半。\n一年人爱今回满。\n莫放笙歌容易散。\n须同玩。\n娥解笑人无伴。\n抱尽金精来碧汉。\n醉吟莫作寻常看。\n已过中天欢未断。\n还同叹。\n时情已向明朝换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2004, '蓦山溪', '葛胜仲', '出门西笑。\n千里长安道。\n不用引离声，便登荣、十洲三岛。\n画船珠箔，苹末水风凉，随柳岸，楚台人，景与人俱好。\n应嗟见晚，玉殿生清晓。\n正是妙年时，步承明、谋身须早。\n轺车肤使，新逐凯歌回，恩绋重，彩衣轻，嘉庆知多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2005, '西江月', '葛胜仲', '艳曲醉歌金缕，朱门高耸铜环。\n中天楼观共跻攀。\n飞絮落花春晚。\n低映绿阴朱户，斜拖素练沧湾。\n银钩华榜五云间。\n奕奕蛟龙字绾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2006, '西江月', '葛胜仲', '斜红带柳，琉璃涨绿平桥。\n人在花月见新妖。\n不数江南苏小。\n恨寄飞花蔌蔌，情随流水迢迢。\n鲤鱼风送木兰桡。\n回棹荒鸡报晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2007, '西江月', '葛胜仲', '清樾已生昼寂，孤花尚表春馀。\n象床筠簟燕堂虚。\n初过晚凉微雨。\n圭璧新来北苑，鲈鱼未减东吴。\n捧觞红袖透香肤。\n不翔龙烟缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2008, '西江月', '葛胜仲', '瑞兽香云轻袅，华堂绣幕低垂。\n人生七十尚为稀。\n况是钓璜新岁。\n登俎青梅的，明阑红药芳菲。\n天教眉寿过期颐。\n常对风光沈醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2009, '浣溪沙', '葛胜仲', '楼子包金照眼新。\n香根犹带广陵尘。\n翻阶不羡掖垣春。\n不分与花为近侍，难甘溱洧赠闲人。\n如羞如怨独含颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2010, '虞美人', '葛胜仲', '三年曾不窥园树。\n辛苦萤窗暮。\n怪来文誉满清时。\n柿叶书残犹自、日临池。\n春秋新学卑繁露。\n黄卷聊堪语。\n家人不用寄龟诗。\n行看升平楼外、化龙归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2011, '虞美人', '葛胜仲', '一轮丹桂树。\n光景疑非暮。\n天公著意在兹时。\n扫尽微云点缀、展清池。\n樽前金奏无晨露。\n只有君房语。\n骊驹客莫赋归诗。\n东道留连应赋、不庸归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2012, '瑞鹧鸪', '葛胜仲', '火云欲避金风至。\n秀气充闾初降瑞。\n去家丁令却归来，还燕悬弧当日地。\n金章紫绶身荣贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2013, '鹊桥仙', '葛胜仲', '鹊桥仙偶，天津轻渡，却笑嫦娥孤皎。\n平时五夜似经年，问何事、今宵便晓。\n云车将驾，神夫留恋，更吐心期多少。\n支机休浪与闲人，莫倚赖、芳心素巧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2014, '江城子', '葛胜仲', '浮家重过水晶宫。\n五年中。\n事何穷。\n无恙山溪，鬟影落青铜。\n欲向旧游寻旧事，云散彩，水流东。\n苔花向我似情锺。\n舞霜风。\n雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2015, '江城子', '葛胜仲', '飞身疑到广寒宫。\n玉花中。\n兴何穷。\n酒贵旗亭，谁是惜青铜。\n飘瞥三无真妙绝，银万里，失西东。\n草堂红蜡暖歌锺。\n卷帘风。\n赏空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2016, '蝶恋花', '葛胜仲', '安石榴花浓绿映。\n解愠风轻，乍改朱明令。\n衮绣元臣门户盛。\n童孙此日悬弧庆。\n夜宴华堂添酒兴。\n□□除书，远带天香剩。\n欲苕波供续命。\n不须龙护江心镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2017, '南乡子', '葛胜仲', '晴日乱云收。\n人在苹香柳恽洲。\n溪上清风楼上醉，飕飕。\n共折黄花插满头。\n佳客献还酬。\n不负山城九日秋。\n苕碧下青供酩酊，休休。\n楚客当年浪自愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2018, '南乡子', '葛胜仲', '拂槛晓云鲜。\n销暑楼危竦半天。\n曾是携宾当荐九，开筵。\n度水萦山奏管弦。\n黄菊映华颠。\n千骑重来已六年。\n楼下东流当日水，依然。\n更对周旋旧七贤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2019, '减字木兰花', '葛胜仲', '葛山仙隐。\n尚有馀膏留旧鼎。\n十里梅花。\n夹道争看衮绣华。\n人间妙丽。\n并侍黄扉开国贵。\n僻壤孤芳。\n羞涩尊前不敢香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2020, '临江仙', '葛胜仲', '倦客身同舟不系，轻帆来访儒仙。\n春风元巳艳阳天。\n夭桃芳散锦，高柳欲飞绵。\n千古海昌佳绝地，双凫暂此留连。\n通宵娱客破芳尊。\n兰亭修禊事，梓泽醉名园。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2021, '临江仙', '葛胜仲', '宝观飞雉堞，登临恍欲升仙。\n野桃官柳衬吴天。\n春风寒食夜，遗恨在封绵。\n闻道东溟才二里，银涛直与天连。\n凭谁都卷入芳尊。\n赋归欢靖节，消渴解文园。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2022, '减字木兰花', '葛胜仲', '辛勤场屋。\n未遇知音甘陆陆。\n诏录遗忠。\n一札天书下九重。\n鹅城初命。\n此去青云应渐近。\n解褐恩新。\n今岁吾家第四人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2023, '减字木兰花', '葛胜仲', '杏花零乱。\n拟把百觚来判断。\n病卧漳滨。\n不见枝头闹小春。\n吾衰老矣。\n一醉花前犹不遂。\n情绪厌厌。\n虚度韶光又一年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2024, '虞美人', '葛胜仲', '严陵滩畔香醪好。\n遮莫东方晓。\n春风盎盎如寒肌。\n人道霜浓腊月、我还疑。\n红炉火热香围坐。\n梅蕊迎春破。\n一声清唱解人颐。\n人道牢愁千斛、我谁知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2025, '鹧鸪天', '葛胜仲', '玉还飞换岁灰。\n定山新棹酒船回。\n年时梁燕双双在，肯为人愁便不来。\n衰意绪，病情怀。\n玉山今夜为谁颓。\n年时梅蕊垂垂破，肯为人愁便不开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2026, '西江月', '葛胜仲', '万卷旧推鸿博，一官且慰蹉跎。\n升平楼下赐危科。\n曾对昂黼坐。\n燕颔从来骨贵，鸾栖尚屈才多。\n今宵且共入无何。\n定远功名幺麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2027, '浪淘沙', '葛胜仲', '我爱菊花枝。\n露偏宜。\n旋移佳种一年期。\n照眼黄金三径烂，可但东篱。\n秋老摘花吹。\n敢恨开迟。\n只愁一夜便香衰。\n待插满头年大也，且泛芳卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2028, '鹧鸪天', '葛胜仲', '黄菊鲜鲜带露浓。\n小园开遍度香风。\n自玉酝酬秋色，旋洗霜须对晚丛。\n香在手，莫匆匆。\n寻芳今夜有人同。\n黄金委地新收得，莫道山翁到底穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2029, '鹧鸪天', '葛胜仲', '采采黄花鹄彩浓。\n吹开一夜为霜风。\n已邀骚客陶元亮，不用歌妓盛小丛。\n秋易老，莫匆匆。\n齐山高兴古今同。\n欲知此地花多少，一眼金英望不穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2030, '木兰花・玉楼春', '葛胜仲', '谈围曾蔽青绫帐。\n林下中年敦素尚。\n烟波偶趁一帆风，却锁云扃来就养。\n自从悟得空无相。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2031, '醉花阴', '葛胜仲', '东皇已有来归耗。\n十里青山道。\n冻蘖万株梅，一夜妆成，似趁鸣鸡早。\n年时清赏曾同到。\n先仗游蜂报。\n抖擞旧心情，一笑酬春，不羡和羹诏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2032, '浣溪沙', '葛胜仲', '东阁郎官巧写真。\n西湖处士妙传神。\n嫣然一笑腊前春。\n斗好虽无冰骨女，相宜幸是雪髯人。\n且烦疏影入清尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2033, '浣溪沙', '葛胜仲', '盘里明珠芡实香。\n尊前堆雪脍丝长。\n何妨羌管奏伊凉。\n翠葆重生无复日，白波不有如江。\n壁间醉墨任淋浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2034, '临江仙', '葛胜仲', '二月风光浓似酒，小楼新湿青红。\n碧琉璃色映群峰。\n更携金凿落，来赏锦薰笼。\n调客旧留□月旦，此花清软纤。\n未饶兰蕙转光风。\n赤阑呈雅艳，翠幕护芳丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2035, '临江仙', '葛胜仲', '雪壁歌词题尚湿，春风又见轻红。\n一枝斜插映头峰。\n不辞连夜赏，银烛透纱笼。\n白发欺人今老矣，尊前羞见繁。\n清香尤虎溪风。\n海棠须避席，佳种谩蚕丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2036, '浣溪沙', '葛胜仲', '一夜狂风尽海棠。\n此花天遣殿群芳。\n芝兰百濯见真香。\n劝客淋浪灯底韵，恼人魂梦枕边囊。\n一枝插不□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2037, '鹊桥仙', '葛胜仲', '凉飙破暑，清歌萦坐，缺月稀星庭户。\n瓜华草草具杯盘，喜共、初筵零露。\n天孙东处，牵牛西望，劝汝一杯清醑。\n精灵何必待秋通，为一洗、朦胧今古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2038, '临江仙', '葛胜仲', '槛外奇葩江外种，娇春未减酲红。\n画楼晴日敛云峰。\n佛香来海岸，蜀锦荐灯笼。\n今夜那忧杀风景，酒花来斗妖浓。\n江梅冷淡避春风。\n明朝来纵赏，应醉绮罗丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2039, '蝶恋花', '葛胜仲', '二月春游须烂漫。\n秉烛看花，只为晨曦短。\n高举蜡薪通夕看。\n红光万丈腾天半。\n寄语平时游冶伴。\n不负分阴，胜事输今段。\n灯火休催归小院。\n殷勤更照桃花面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2040, '蝶恋花', '葛胜仲', '只恐深夜花睡去。\n火照红妆，满意留宾住。\n凤烛千枝花四顾。\n消愁更待寻何处。\n汉苑红光非浪语。\n栖静亭前，都是珊瑚树。\n便请催尊鸣鼓。\n明朝风恶飘红雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2041, '蝶恋花', '葛胜仲', '百紫千红今烂熳。\n举烛辉花，莫厌烧令短。\n酒里逢花须细看。\n人生谁似英雄半。\n安得红颜为老伴。\n妙舞花前，杨柳夸身段。\n已倒玉山回竹院。\n清香不断风吹面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2042, '蝶恋花', '葛胜仲', '已过春分春欲去。\n千炬花间，作意留春住。\n一曲清歌无误顾。\n绕梁馀韵归何处。\n尽日劝春春不语。\n红气蒸霞，且看桃千树。\n才子霏谈更五鼓。\n剩看走笔挥风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2043, '浪淘沙', '葛胜仲', '又见菊花新。\n色浅香匀。\n老人衰病卧漳滨。\n虽是无聊仍止酒，幸有嘉宾。\n不用怨萧辰。\n不似芳春。\n请看金蕊照金尊。\n今夜花前须醉倒，直到黎明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2044, '浪淘沙', '葛胜仲', '歌阕斗清新。\n檀板初匀。\n画堂新筑太湖滨。\n好是黄花开应候，聊宴亲宾。\n上客即逢辰。\n况是青春。\n上林开宴锡尧尊。\n今夜素娥真解事，偏向人明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2045, '浪淘沙', '葛胜仲', '娱老小亭新。\n丹垩初匀。\n万枝金菊绕溪滨。\n折向华堂遮醉眼，聊用娱宾。\n红烛夜香辰。\n广坐生春。\n月波新酿入芳尊。\n好向花前拚烂醉，不负承明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2046, '南乡子', '葛胜仲', '秋水莹精神。\n靖节先生太逼真。\n谈麈生风霏玉屑，津津。\n爽气泠然欲侵人。\n一座尽生春。\n满引琼觞已半醺。\n更把黄花寿彭祖，盈盈。\n数阕新声又遏云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2047, '虞美人', '葛胜仲', '灵山法会何曾散。\n此地神光满。\n丁公潭下百雷霆。\n疑是银河挽下、一齐倾。\n高桥飞观连云起。\n槛外惊湍水。\n大矶才过小矶来。\n应有天孙灵驭、月中回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2048, '临江仙', '米友仁', '昨夜扁舟沙外舣，淮山微雨初晴。\n断云飞过月还明。\n一天风露重，人在玉壶清。\n水际不知何许是，遥林□辨微青。\n醉迷归梦强□凌。\n谁言东去雁，解寄此时情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2049, '小重山', '米友仁', '醉倚朱阑一解衣。\n碧云迷望眼，断虹低。\n近来休说带宽围。\n人千里，还是燕双飞。\n深院日初迟。\n绮窗帘幕静，恨生眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2050, '减字木兰花', '米友仁', '柳塘微雨。\n两两飞鸥来复去。\n倚遍重阑。\n人在碧云山外山。\n一春离怨。\n日照绮窗长几线。\n酒病情魔。\n两事春来无奈何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2051, '点绛唇', '米友仁', '浩渺湖天，酒浮黄菊携佳侣。\n澹烟疏雨。\n去鲁方怀土。\n倾盖相逢，引满哦奇语。\n山围处。\n兕觥频举。\n不醉君无去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2052, '渔家傲', '米友仁', '从古荆溪名胜地。\n溪光万顷琉璃翠。\n极望荷花三十里。\n香喷鼻。\n我舟日在花间舣。\n向晚馀霞收散绮。\n遥山抹黛天如水。\n满引一尊明月里。\n微风起。\n萧然真在华胥氏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2053, '阮郎归', '米友仁', '小舟载酒向平湖。\n新凉生晓初。\n乱山烟外有还无。\n王维真画图。\n风遽起，动襟裾。\n雨来荷溅珠。\n一尊相对喜君俱。\n醉归红袖扶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2054, '临江仙', '米友仁', '一曲阳关肠断处，临风惨对离尊。\n红妆揭调十分斟。\n古来多聚散，正似岭头云。\n昨夜晴霄千里月，向人无限多情。\n娟娟今夜满虚庭。\n一帆随浪去，却照画船轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2055, '宴桃源・如梦令', '米友仁', '蝶梦初回栩栩。\n柳岸几声莺语。\n苹末起微风，山外一川烟雨。\n凝顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2056, '南歌子', '米友仁', '遇酒词先举，逢山眼暂明。\n一川风雨纵留人。\n不道此郎归兴、欲兼程。\n客久情深□，寻欢恨不能。\n绳床顿睡梦纵横。\n赖□□□□□、□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2057, '渔家傲', '米友仁', '郊外春和宜散步。\n百花枝上初凝露。\n福地神仙多外府。\n藏奇趣。\n幽寻历遍溪边路。\n薄宦浮家无定处。\n萍飘梗泛前人语。\n与子未须乡国去。\n来同住。\n且看群岫烟中雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2058, '念奴娇', '米友仁', '九秋气爽，正溪山雨过，茅檐清暇。\n篱菊妍英，知是为，佳节重阳开也。\n色妙香殊，匀浮瓯面，俗状卑金。\n歌狂饮俊，满簪还更盈把。\n村外草草杯盘，边尘不动，欲买应无价。\n端使晴霄风露冷，云卷烟收平野。\n向晚婵娟，半轮斜照，想见成清夜。\n玉山颓处，要看猗帽如画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2059, '临江仙', '米友仁', '宝晋轩窗临望处，山围水绕林萦。\n不堪回首到江城。\n墙趺围瓦砾，鸥鹭见人惊。\n日愿太平归旧里，更无馀事关情。\n小营茅舍倚云汀。\n四时风月里，还我醉腾腾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2060, '阮郎归', '米友仁', '碧溪风动满文漪。\n雨馀山更奇。\n淡烟横处柳行低。\n鸳鸯来去飞。\n人似玉，醉如泥。\n一枝随鬓猗。\n夷犹双桨月平西。\n幽寻归路迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2061, '临江仙', '米友仁', '野外不堪无胜侣，笑谈安得君同。\n四时景物一壶中。\n醉馀临望处，远岫数重重。\n溪上新荷初出水，花房半弄微红。\n晓风萧爽韵疏松。\n娟娟明月上，人在广寒宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2062, '念奴娇', '米友仁', '阑干倚处。\n戏裁成、彭泽当年奇语。\n三径荒凉怀旧里，我欲扁舟归去。\n鸟倦知还，寓形宇内，今已年如许。\n小窗容膝，要寻情话亲侣。\n郭外粗有西畴，故园松菊，日涉方成趣。\n流水涓涓千涧上，云绕奇峰无数。\n窈窕经丘，风清月了，时看烟中雨。\n萧然巾岸，引觞寄傲衡宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2063, '醉春风', '米友仁', '一阳来复群阴往。\n吾道从今长。\n万事莫关情，月夕风前，依旧须豪放。\n卿云舒卷浮青嶂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2064, '小重山', '米友仁', '雨过风来午暑清。\n榴花红照眼，向人明。\n一枝低映宝钗横。\n菖蒲酒，玉碗十分斟。\n引满听新声。\n小轩帘半卷，远山青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2065, '诉衷情', '米友仁', '结庐人境羡陶潜。\n车马不来喧。\n胜处自多真趣，飞鸟日相还。\n心既远，地仍偏。\n见南山。\n手持菊颖，山气常佳，欲辨忘言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2066, '白雪', '米友仁', '洞天昼永，正中和时候，凉飙初起。\n羽扇纶巾，云流处，水绕山重云委。\n好雨新晴，绮霞明丽，全是丹青戏。\n豪攘横卷，楚天应解深秘。\n留滞。\n字学书林，折腰缘为米，无机涉世。\n投组归来欣自肆，目仰云霄醒醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2067, '念奴娇', '曾纡', '片帆暮落，正前村梅蕊，愁人如雪。\n东陌西溪长记得，疏影横斜时节。\n六出冰姿，玉人微步，笑里轻轻折。\n兰房沈醉，暗香曾共私窃。\n回头万水千山，一枝重见处，离肠千结。\n料想临鸾消瘦损，时把啼红偷。\n怎得伊来，许多幽恨，共拈青梢说。\n如今千里，断魂空对明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2068, '上林春・一落萦', '曾纡', '东苑梅繁，豪健放乐，醉倒花前狂客。\n靓妆微步，攀条弄粉，凌波遍寻青陌。\n暗香堕靥。\n更飘近、雾鬟蝉额。\n倒金荷、念流光易失，幽姿堪惜。\n惜花心、未甘鬓白。\n南枝上、又见寻芳消息。\n旧游回首，前欢如梦，谁知等闲抛掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2069, '秋霁', '曾纡', '木落山明，暮江碧，楼倚太虚寥廓。\n素手飞觞，钗头笑取，金英满浮桑落。\n鬓云慢约。\n酒红拂破香腮薄。\n细细酌。\n帘外任教、月转画阑角。\n当年快意登临，异乡节物，难禁离索。\n故人远、凌波何在，惟有残英共寂寞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2070, '念奴娇', '曾纡', '江城春晚，正海棠临水，嫣然幽独。\n秀色天姿真富贵，何必金盘华屋。\n月下无人，雨中有泪，绝艳仍清淑。\n丰肌得酒，嫩红微透轻。\n晓日雾霭林深，佳人春睡思，朦胧初足。\n笑出疏篱，端可厌，桃李漫山粗俗。\n衔子飞来，鸿鹄何在，千里移西蜀。\n明朝酒醒，乱红那忍轻触。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2071, '洞仙歌', '曾纡', '相如当日，曾奏凌云赋。\n落笔纵横妙风雨。\n记扬鞭辇路，同醉金明，穷胜赏，不管重城已暮。\n旧游如梦觉，零落朋侪，遗墨淋漓尚如故。\n况神洲北望，今已丘墟，伤白璧、久埋黄土。\n但空似、灵光岿然存，怅朗月清风，更无玄度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2072, '临江仙', '曾纡', '後院短墙临绿水，春风急管繁弦。\n问谁亲按小婵娟。\n玉堂真学士，琳馆地行仙。\n安得此身来此处，依稀一梦梨园。\n江南刺使谩垂涎。\n据鞍肠已断，何况到尊前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2073, '菩萨蛮', '曾纡', '山光冷浸清溪底。\n溪光直到柴门里。\n卧对白苹洲。\n猗眠数钓舟。\n溪山无限好。\n恨不相逢早。\n老病独醒多。\n如此良夜何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2074, '谒金门', '曾纡', '风淅沥。\n窗外雪花初积。\n梦破小窗人寂寂。\n寒威无处敌。\n强起饮君涓滴。\n清泪醉来沾臆。\n歧路即今多拥隔。\n弟兄无信息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2075, '品令', '曾纡', '纹漪涨绿。\n疏霭连孤鹜。\n一年春事，柳飞轻絮，笋添新竹。\n寂寞幽花，独殿小园嫩绿。\n登临未足。\n怅游子、归期促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2076, '失调名', '秦湛', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2077, '卜算子', '秦湛', '春透水波明，寒峭花枝瘦。\n极目烟中百尺楼，人在楼中否。\n四和袅金凫，双陆思纤手。\n拟倩东风浣此情，情更浓於酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2078, '木兰花慢', '范周', '美兰堂昼永，晏清暑、晚迎凉。\n控水槛风帘，千花竞拥，一朵偏双。\n银塘。\n尽倾醉眼，讶湘娥、倦倚两霓裳。\n依约凝情鉴里，并头宫面高妆。\n莲房。\n露脸盈盈，无语处、恨何长。\n有翡翠怜红，鸳鸯妒影，俱断柔肠。\n凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2079, '宝鼎现', '范周', '夕阳西下，暮霭红隘，香风罗绮。\n乘丽景、华灯争放，浓焰烧空连锦砌。\n睹皓月、浸严城如画，花影寒笼绛蕊。\n渐掩映、芙蓉万顷，迤逦齐开秋水。\n太守无限行歌意。\n拥麾幢、光动珠翠。\n倾万井、歌台舞榭，瞻望朱轮骈鼓吹。\n控宝马、耀貔貅千骑。\n银烛交光数里。\n似乱簇、寒星万点，拥入蓬壶影里。\n宴阁多才，环艳粉、瑶簪珠履。\n恐看看、丹诏催奉，宸游燕侍。\n便趁早、占通宵醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2080, '秦楼月・忆秦娥', '吴则礼', '怅离阕。\n淮南三度梅花发。\n梅花发。\n片帆西去，落英如雪。\n新秦古塞人华发。\n一樽别酒君听说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2081, '江楼令', '吴则礼', '凭栏试觅红楼句，听考考、城头暮鼓。\n数骑翩翩度孤戍。\n尽雕弓白羽。\n平生正被儒冠误。\n待闲看、将军射虎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2082, '虞美人', '吴则礼', '真香秀色盈盈女。\n一笑重阳雨。\n不应解怯晚丛寒。\n眼底轻罗小扇、且团团。\n吴云楚燕浑依旧。\n更把金英嗅。\n鲜鲜未恨出闺迟。\n自许平生孤韵、与秋期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2083, '虞美人', '吴则礼', '夜寒闲倚西楼月。\n消尽江南雪。\n东风明日木兰船。\n想见阳关声彻、雁连天。\n斜斜洲渚溶溶水。\n端负青春醉。\n平安小字几时回。\n空有暗香疏影、陇头梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2084, '虞美人', '吴则礼', '从来强作游秦计。\n只有貂裘敝。\n休论范叔十年寒。\n看取星星种种、坐儒冠。\n江湖旧日渔竿手。\n初把黄花酒。\n且凭洛水送归船。\n想见淮南秋尽、水如天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2085, '虞美人', '吴则礼', '乌皮白西窗暖。\n种种霜毛短。\n小春何处有梅花。\n想见水边篱落、数枝斜。\n殊方他日登楼句。\n好在孤吟处。\n五年拚落醉魂中。\n试觅酒垆陈迹、问黄公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2086, '减字木兰花', '吴则礼', '星星素发。\n只有鸣笳楼上发。\n看舞胡姬。\n带得平安探骑归。\n故人渐老。\n只与虎头论墨妙。\n怀抱难开。\n快遣披云一笑来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2087, '减字木兰花', '吴则礼', '梅花未彻。\n付与团团沙塞月。\n端欲捐书。\n去乞君王丈二殳。\n貂裘锦帽。\n盘马不甘青鬓老。\n底事偏奇。\n细草平沙看打围。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2088, '减字木兰花', '吴则礼', '河西春晚。\n独有柳条来入眼。\n塞外斜斜。\n不道欺寒红杏花。\n边笳初发。\n与唤团团沙塞月。\n雁响连天。\n谁倚城头百尺栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2089, '八声甘州', '向子', '扫长空、万里静无云，飞镜上天东。\n欲骑鲸与问，一株丹桂，几度秋风。\n取水珠宫贝阙，聊为洗尘容。\n莫放素娥去，清影方中。\n玄魄犹馀半壁，便笙篁万籁，尊俎千峰。\n况十分端正，更鼓舞衰翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2090, '水调歌头', '向子', '闰馀有何好，一年两中秋。\n补天修月人去，千古想风流。\n少日南昌幕下，更得洪徐苏李，快意作清游。\n送日眺西岭，得月上东楼。\n四十载，两人在，总白头。\n谁知沧海成陆，萍迹落南州。\n忍问神京何在，幸有芗林秋露，芳气袭衣裘。\n断送馀生事，惟酒可忘忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2091, '水调歌头', '向子', '我生六十四，四度闰中秋。\n碧天千里如水，明月更如流。\n照我洛滨诗伯，携手仙卿廛隐，阆苑与同游。\n人醉玉相倚，不肯下琼楼。\n芗林老，章江上，几回头。\n剩欲控鹤瀛海，聊下越王州。\n直入白云深处，细酌仙人九酝，香雾尽侵裘。\n共看一笑粲，以写我心忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2092, '水调歌头', '向子', '飘飘任公子，爽气欲横秋。\n向日携诗过我，知不是凡流。\n筑室清江西畔，巧占一川佳处，胜士日追游。\n邀我出门去，柱月上新楼。\n烂银盘，从树杪，出云头。\n好是风流从事，同醉入青州。\n须信人生如幻，七十古来稀有，销得几狐裘。\n谁似芗林老，无喜亦无忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2093, '洞仙歌', '向子', '碧天如水，一洗秋容净。\n何处飞来大明镜。\n谁道斫却桂，应更光辉，无遗照，泻出山河倒影。\n人犹苦馀热，肺腑生尘，移我超然到三境。\n问娥、缘底事，乃有盈亏，烦玉斧、运风重整。\n教夜夜、人世十分圆，待拚却长年，醉了还醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2094, '满江红', '向子', '雁阵横空，江枫战、几番风雨。\n天有意、作新秋令，欲鏖残暑。\n篱菊岩花俱秀发，清氛不断来窗户。\n共欢然、一醉得黄香，仍叔度。\n尊前事，尘中去。\n拈花问，无人语。\n芗林顾灵照，笑抚庭树。\n试举似虎头城太守，想应会得玄玄处。\n老我来、懒更作渊明，闲情赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2095, '虞美人', '向子', '淮阳堂上曾相对。\n笑把姚黄醉。\n十年离乱有深忧。\n白发萧萧同见、渚江秋。\n履声细听知何处。\n欲上星辰去。\n清寒初溢暮云收。\n更看碧天如水、月如流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2096, '虞美人', '向子', '银山堆里庐山对。\n舟子愁如醉。\n笑看五老了无忧。\n大觉胸中云梦、气横秋。\n若人到得归元处。\n空一齐销去。\n直须闻见泯然收。\n始知大江东注、不曾流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2097, '虞美人', '向子', '澄江霁月清无对。\n鲁酒何须醉。\n人怜贫病不堪忧。\n谁识此心如月、正含秋。\n再三涝漉方知处。\n试向波心去。\n迢迢空劫勿能收。\n谩道从来天地、与同流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2098, '虞美人', '向子', '江头苦被梅花恼。\n一夜霜须老。\n谁将冰玉比精神。\n除是凌风却月、见天真。\n情高意远仍多思。\n只有人相似。\n满城桃李不能春。\n独向雪花深处、露花身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2099, '蝶恋花', '向子', '推上百花如锦绣。\n水满池塘，更作溅溅溜。\n断送风光惟有酒。\n苦吟不怕因诗瘦。\n寻壑经丘长是久。\n晚晚归来，稚子柴门候。\n万事付之醒梦後。\n眉头不为闲愁皱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2100, '蝶恋花', '向子', '岩桂秋风南埭路。\n墙外行人，十里香随步。\n此是芗林游戏处。\n谁知不向根尘住。\n今日对花非浪语。\n忆昨明光，早辱君王顾。\n生怕青蝇轻点污。\n思鲈何似思花去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2101, '鹧鸪天', '向子', '戏彩堂深翠幕张。\n南特地作微凉。\n葵花向日枝枝似，萱草忘忧日日长。\n门有庆，福无疆。\n老人星与酒生光。\n殷勤更假天吴手，倾泻西江入寿觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2102, '鹧鸪天', '向子', '召埭初逢两妙年。\n遥林玉树倚风前。\n疏梅影里春同醉，红芰香中月一船。\n长怅恨，短因缘。\n空馀蝴蝶梦相连。\n谁知瘴雨蛮烟地，重上襄王玳瑁筵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2103, '鹧鸪天', '向子', '两个鸳鸯波上来。\n一ь杨柳掌中回。\n已愁共雪因风去，更着繁弦急管催。\n含浅笑，劝深杯。\n桃花气暖眼边开。\n司空常见风流惯，输与山翁醉玉摧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2104, '鹧鸪天', '向子', '露下风前处处幽。\n官黄如染翠如流。\n谁将天上蟾宫树，散作人间水国秋。\n香郁郁，思悠悠。\n几年梦魂绕江头。\n今朝得到芗林醉，白发相看万事休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2105, '鹧鸪天', '向子', '莫问清江与洛阳。\n山林总是一般香。\n两家地占西南胜，可是前人例姓杨。\n石作枕，醉为乡。\n藕花菱角满池塘。\n虽无中岛霓裳奏，独鹤随人意自长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2106, '鹧鸪天', '向子', '紫禁烟花一万重。\n鳌山宫阙倚晴空。\n玉皇端拱彤云上，人物嬉游陆海中。\n星转斗，驾回龙。\n五侯池馆醉春风。\n而今白发三千丈，愁对寒灯数点红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2107, '鹧鸪天', '向子', '只有梅花似玉容。\n云窗月户几尊同。\n见来怨眼明秋水，欲去愁眉淡远峰。\n山万叠，水千重。\n一双蝴蝶梦能通。\n都将泪作黄梅雨，尽把情为柳絮风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2108, '鹧鸪天', '向子', '玉篆题名在九天。\n而今且作地行仙。\n挂冠神武归休後，同醉芗林是几年。\n龟游泳，鹤蹁迁。\n疏梅修竹两清妍。\n欲知福寿都多少，阁皂清江可比肩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2109, '鹧鸪天', '向子', '江北江南雪未消。\n此花独步百花饶。\n青枝可爱难为杏，绿叶初无不是桃。\n多态度，足风标。\n蕊珠仙子醉红潮。\n绝怜竹外横斜处，似与芗林慰寂寥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2110, '鹧鸪天', '向子', '驾月新成碧玉梁。\n青天万里泻银潢。\n广寒宫里无双树，无热池边不尽香。\n承露液，酿秋光。\n直须一举累千觞。\n不知世路风波恶，何似芗林气味长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2111, '鹧鸪天', '向子', '明月光中与客期。\n一年秋半两圆时。\n娥得意为长计，织女欢盟可恨迟。\n瞻玉兔，倒琼彝。\n追怀往事记新词。\n浩歌直入沧浪去，醉里归来凝不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2112, '鹧鸪天', '向子', '赣上人人说故侯。\n从来文采更风流。\n题诗谩道三千首，别酒须拚一百筹。\n乘画，衣轻裘。\n又将春色过荆州。\n合江绕岸垂杨柳，总学歌眉叶叶愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2113, '减字木兰花', '向子', '青松翠。\n一夜猗倾如醉倒。\n残腊能佳。\n落尽梅花见雪花。\n诗崖酒岛。\n何日登临同笑傲。\n未老还家。\n饱历年华有鬓华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2114, '减字木兰花', '向子', '斜红翠叠。\n何许花神来献瑞。\n粲粲裳衣。\n割得天孙锦一机。\n真香妙质。\n不耐世间风与日。\n着意遮围。\n莫放春光造次归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2115, '阮郎归', '向子', '江南江北雪漫漫。\n遥知易水寒。\n同云深处望三关。\n断肠山又山。\n天可老，海能翻。\n消除此恨难。\n频闻遣使问平安。\n几时鸾辂还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2116, '秦楼月・忆秦娥', '向子', '芳菲歇。\n故园目断伤心切。\n伤心切。\n无边烟水，无穷山色。\n可堪更近乾龙节。\n眼中泪尽空啼血。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2117, '少年游', '向子', '去年同醉，酴花下，健笔赋新词。\n今年君去，酴欲破，谁与醉为期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2118, '西江月', '向子', '风响蕉林似雨，烛生粉艳如花。\n客星乘兴泛仙槎。\n误到支机石下。\n欢喜地中取醉，温柔乡里为家。\n暖红香雾闹春华。\n不道风波可怕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2119, '西江月', '向子', '见处莫教认著，无心慎勿沈空。\n本无背面与初终。\n说了还同说梦。\n欲识芗林居士，真成渔父家风。\n收丝垂钓月明中。\n总是神通妙用。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2120, '西江月', '向子', '得意穿云度水，及时斫玉分金。\n兹游了却未来心。\n怪我归迟一任。\n居士何如学士，翰林休笑芗林。\n个中真味少知音。\n不是清狂太甚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2121, '西江月', '向子', '五柳坊中烟绿，百花洲上云红。\n萧萧白发两衰翁。\n不与时人同梦。\n抛掷麟符虎节，徜徉江月林风。\n世间万事转头空。\n个里如如不动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2122, '西江月', '向子', '红退小园桃杏，绿生芳草池塘。\n谁教芍药殿春光。\n不似酴官样。\n翠盖更蒙珠，薰炉剩熨沈香。\n娟娟风露满衣赏。\n独步瑶台月上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2123, '西江月', '向子', '几见芙蓉并蒂，忽生三秀灵芝。\n千年老树出孙枝。\n岩桂秋来满地。\n白鹤云间翔舞，绿龟叶上游戏。\n齐眉偕老更何疑。\n个里自非尘世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2124, '南乡子', '向子', '梅与雪争姝。\n试问春风管得无。\n除却个人多样态，谁如。\n细把冰姿比玉肤。\n一曲倒金壶。\n既醉仍烦翠袖扶。\n同向凌风台上看，何如。\n且与芗林作画图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2125, '浣溪沙', '向子', '绿玉丛中紫玉条。\n幽花疏淡更香饶。\n不将朱粉污高标。\n空谷佳人宜结伴，贵游公子不能招。\n小窗相对诵离骚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2126, '浣溪沙', '向子', '乐在烟波钓是闲。\n草堂松桂已胜攀。\n梢梢新月几回弯。\n一碧太湖三万顷，屹然相对洞庭山。\n况风浪起且须还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2127, '浣溪沙', '向子', '进步须於百尺竿。\n二边休立莫中安。\n要知玄露没多般。\n花影镜中拈不起，蟾光空里撮应难。\n道人无事更参看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2128, '浣溪沙', '向子', '爆竹声中一岁除。\n东风送暖入屠苏。\n瞳瞳晓色上林庐。\n老去怕看新历日，退归拟学旧桃符。\n青春不染白髭须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2129, '浣溪沙', '向子', '醉里惊从月窟来。\n睡馀如梦蕊宫回。\n碧云时度小崔嵬。\n疑是海山怜我老，不论时节遣花开。\n从今休数返魂梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2130, '浣溪沙', '向子', '星斗昭回自一天。\n疏梅池畔斗清妍。\n蟠桃正熟藕如船。\n叶上灵龟来瑞世，林间白鹤舞胎仙。\n春秋不记几千年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2131, '浣溪沙', '向子', '瑞气氤氲拂水来。\n金幢玉节下瑶台。\n江梅岩桂一时开。\n不尽秋香凝燕寝，无边春色入尊。\n临风嗅蕊共裴回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2132, '浣溪沙', '向子', '绿绕红围宋玉墙。\n幽兰林下正芬芳。\n桃花气暖玉生香。\n谁道广平心似铁，艳妆高韵两难忘。\n苏州老矣不能狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2133, '浣溪沙', '向子', '霭霭停云覆短墙。\n夭夭临水自然芳。\n猗猗无处着清香。\n珍重蓦山溪句好，尊前频举不相忘。\n濠梁梦蝶尽春狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2134, '浣溪沙', '向子', '南国风烟深更深。\n清江相结是庐陵。\n甘棠两地绿成阴。\n九日黄花兄弟会，中秋明月故人心。\n悲欢离合古犹今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2135, '浣溪沙', '向子', '樽俎风流意气倾。\n一杯相属忍催行。\n离歌更作断肠声。\n衮衮大江前後浪，娟娟明月短长亭。\n水程山驿总关情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2136, '生查子', '向子', '我爱木中犀，不是凡花数。\n清似水沈香，色染蔷薇露。\n芗林月冷时，玉笋云深处。\n归梦托秋风，夜夜江头路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2137, '生查子', '向子', '月姊倚秋风，香度青林杪。\n吹堕酒杯中，笑靥撩人小。\n芗林万事休，独此情未了。\n醉里又题诗，不觉花前老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2138, '临江仙', '向子', '新月低垂帘额，小梅半出檐牙。\n高堂开燕静无哗。\n麟孙凤女，学语正咿呀。\n宝鼎剩熏沈水，琼彝烂醉流霞。\n芗林同老此生涯。\n一川风露，总道是仙家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2139, '七娘子', '向子', '山围水绕高唐路。\n恨密云、不下阳台雨。\n雾阁云窗，风亭月户。\n分明携手同行处。\n而今不见生尘步。\n但长江、无语东流去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2140, '减字木兰花', '向子', '维摩住处。\n竟日缤纷花似雨。\n更有难忘。\n十里清芬扑鼻香。\n当年疏傅。\n借问赐金那用许。\n何似归。\n宝墨光芒万丈长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2141, '减字木兰花', '向子', '年年岩桂。\n恰恰中秋供我醉。\n今日重阳。\n百树犹无一树香。\n且倾白酒。\n赖有茱萸枝在手。\n可是清甘。\n绕遍东篱摘未堪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2142, '清平乐', '向子', '幽花无外。\n心与芗林会。\n绿发相看今老矣。\n不作浅俗气味。\n露叶生光。\n风梢泛泛飘香。\n称意中秋开了，馀情犹及重阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2143, '清平乐', '向子', '吴头楚尾。\n踏破芒鞋底。\n万壑千岩秋色里。\n不耐恼人风味。\n而今我老芗林。\n世间百不关心。\n独喜爱香韩寿，能来同醉花阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2144, '清平乐', '向子', '薄情风雨。\n断送花何许。\n一夜清香无觅处。\n却返云窗月户。\n醉乡曲米为春。\n荆州富贵中人。\n肯入芗林净社，玉山屡倒芳茵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2145, '清平乐', '向子', '银钩虿尾。\n一似锺繇字。\n吏部文章麟角起。\n自是惊人瑞世。\n西垣准拟挥毫。\n不须苦续离骚。\n政看翻阶红药，无忘丛桂香醪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2146, '清平乐', '向子', '人间尘外。\n一种寒香蕊。\n疑是月娥天上醉。\n戏把黄云碎。\n使君坐啸清江。\n腾芳飞誉无双。\n兴寄小山丛桂，诗成几明窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2147, '清平乐', '向子', '芗林春色。\n杯面云腴白。\n醉里不知天地窄。\n真是人间欢伯。\n风流玉友争妍。\n酪奴可与忘年。\n空诵少陵佳句，饮中谁与俱仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2148, '更漏子', '向子', '小窗前，疏影下。\n鸾镜弄妆初罢。\n梅似雪，雪如人。\n都无一点尘。\n暮江寒，人响绝。\n更着朦胧微月。\n山似玉，玉如君。\n相看一笑温。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2149, '点绛唇', '向子', '绿水青山，一轮明月林梢过。\n有谁同坐。\n妙德毗卢我。\n石女高歌，古调无人和。\n还知麽。\n更没别个。\n且莫分疏破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2150, '点绛唇', '向子', '此夜中秋，不向光影门前过。\n披衣得坐。\n无佛众生我。\n没鼓打皮，借问今几和。\n还知麽。\n就中两个。\n鼻孔谁穿破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2151, '点绛唇', '向子', '不昧本来，太虚明月流辉过。\n令行独坐。\n高下都由我。\n玉轸无弦，谁对秋风和。\n还知麽。\n老庞一个。\n识得机关破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2152, '点绛唇', '向子', '折脚铛中，二时粥饭随缘过。\n东行西坐。\n不识而今我。\n坏尽田园，终日且婆和。\n还知麽。\n锥也无个。\n肘露衣衫破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2153, '点绛唇', '向子', '不挂一裘，世间万事如风过。\n忘缘兀坐。\n皮袋非真我。\n随色摩尼，朱碧如何和。\n还知麽。\n从来只个。\n千古扑不破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2154, '点绛唇', '向子', '荆棘林中，浪夸好手曾穿过。\n不起於坐。\n塞虚空我。\n问路台山，婆子随声和。\n还知麽。\n石桥老个。\n些子平窥破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2155, '点绛唇', '向子', '春浪桃花，禹门三尺平跳过。\n死生不坐。\n变化须归我。\n山起南云，白雨声相和。\n还知麽。\n点点真个。\n块土何曾破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2156, '点绛唇', '向子', '脱落皮肤，故人南岳峰前过。\n只知闲坐。\n千圣难窥我。\n明月澄潭，谁唱复谁和。\n还知麽。\n锦鳞没个。\n莫触清光破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2157, '点绛唇', '向子', '绿水池塘，笑看野鸭双飞过。\n正当呆坐。\n纫鼻须还我。\n尽日张弓，许久无人和。\n还知麽。\n难得全个。\n不免须明破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2158, '点绛唇', '向子', '冰雪肌肤，靓妆喜作梅花面。\n寄情高远。\n不与凡尘染。\n玉立峰前，闲把经珠转。\n秋风便。\n雾收云卷。\n水月光中见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2159, '点绛唇', '向子', '无热池南，岁寒亭上开新宴。\n青山芳甸。\n尽入真如观。\n举酒高歌，人在秋天半。\n晴空远。\n巷江影乱。\n何处飞来雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2160, '点绛唇', '向子', '病卧秋风，懒寻杯酒追欢宴。\n梦游都甸。\n不改当年观。\n故旧雕零，天下今无半。\n烟尘远。\n泪珠零乱。\n怕问随阳雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2161, '点绛唇', '向子', '今日重阳，强青蕊聊开宴。\n我家几甸。\n试上连辉观。\n忆着池，古塔烟霄半。\n愁心远。\n情随云乱。\n肠断江城雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2162, '点绛唇', '向子', '莫问重阳，黄花满地须游宴。\n休论夷甸。\n且作江山观。\n百岁光阴，屈指今过半。\n霜天晚。\n眼昏花乱。\n不见书空雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2163, '点绛唇', '向子', '春蕙秋兰，断崖空谷终难近。\n何如逸韵。\n十里香成阵。\n倾盖论交，白首情无尽。\n因君问。\n新声玉振。\n更觉花清润。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2164, '点绛唇', '向子', '璧月光辉，万山不隔蟾宫树。\n金风玉露。\n水国秋无数。\n老子情锺，欲向香中住。\n君王许。\n龙鸾飞舞。\n送到归休处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2165, '点绛唇', '向子', '明月山头，古香吹堕青林底。\n世情无味。\n伴我千岩里。\n诗老风流，也向花留意。\n歌新拟。\n调高难比。\n半坐分君醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2166, '采桑子', '向子', '霜须七十期同老，云水之乡。\n总挂冠裳。\n闲里光阴一倍长。\n况逢菊靥篱边笑，风露中香。\n报答秋光。\n自有仙人九酝觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2167, '一落索', '向子', '春风吹断前山雨。\n行云归去。\n暂来须信本无心，回首了无寻处。\n欲问个中玄路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2168, '如梦令', '向子', '欲问芗林秋露。\n来自广寒深处。\n海上说蔷薇，何似桂华风度。\n高古。\n高古。\n不著世间尘污。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2169, '如梦令', '向子', '谁识芗林秋露。\n胜却诸天花雨。\n休更觅曹溪，自有个中玄路。\n参取。\n参取。\n滴滴要知落处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2170, '卜算子', '向子', '临镜笑春风，生怕梅花妒。\n疑是西湖处士家，疏影横斜处。\n江静竹娟娟，绿绕青无数。\n独许幽人子细看，全胜墙东路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2171, '卜算子', '向子', '雨意挟风回，月色兼天静。\n心与秋空一样清，万象森如影。\n何处一声钟，令我发深省。\n独立沧浪忘却归，不觉霜华冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2172, '卜算子', '向子', '时菊碎榛丛，地僻柴门静。\n谁道村中好客稀，明月和清影。\n天地一蘧庐，梦事慵思省。\n若个知余懒是真，心已如灰冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2173, '卜算子', '向子', '胶胶扰扰中，本体元来静。\n一段澄明绝点埃，世事如泡影。\n歇即是菩提，此语须三省。\n古道无人著脚行，禾黍秋风冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2174, '水调歌头', '刘望之', '劝子一杯酒，清泪不须流。\n人间千古，俯仰如梦说扬州。\n何况楚王台畔，为雨为云无限，人事付轻沤。\n聚散随来去，天地有虚舟。\n谪仙人，解金龟，换美酒。\n载与君游，流水曲觞且赓酬。\n麾盖飞迎过霭，江滨响振歌喉，拚醉又何求。\n三万六千日，日日此优游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2175, '渔父词・渔父', '法常', '此事楞严常露布。\n梅华雪月交光处。\n一笑寥寥空万古。\n风瓯语。\n迥然银汉横天宇。\n蝶梦南华方栩栩。\n斑斑谁跨丰干虎。\n而今忘却来时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2176, '念奴娇', '陆淞', '黄橙紫蟹，映金壶潋滟，新醅浮绿。\n共赏西楼今夜月，极目云无一粟。\n挥麈高谈，倚栏长啸，下视鳞鳞屋。\n轰然何处，瑞龙声喷蕲竹。\n何况露白风清，银河澈汉，仿佛如悬瀑。\n此景古今如有价，岂惜明珠千斛。\n灏气盈襟，冷风入袖，只欲骑鸿鹄。\n广寒宫殿，看人颜似冰玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2177, '瑞鹤仙', '陆淞', '脸霞红印枕。\n睡觉来、冠儿还是不整。\n屏间麝煤冷。\n但眉峰压翠，泪珠弹粉。\n堂深昼永。\n燕交飞、风帘露井。\n恨无人，与说相思，近日带围宽尽。\n重省。\n残灯朱幌，淡月纱窗，那时风景。\n阳台路迥。\n云雨梦，便无准。\n待归来，先指花梢教看，却把心期细问。\n问因循、过了青春，怎生意稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2178, '卜算子', '卓世清', '流水一湾西。\n晚坐孤亭静。\n不见高人跨鹤归，风竹摇清影。\n往古与来今，休用重重省。\n十里梅花雪正晴，月挂遥山冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2179, '浣溪沙', '李结', '花圃萦回曲径通。\n小亭风卷绣帘重。\n秋千闲倚画桥东。\n双蝶舞馀红便旋，交莺啼处绿葱珑。\n远山眉黛晚来浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2180, '西江月', '李结', '若将花卉论行藏。\n盍在凌烟阁上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2181, '水调歌头', '向', '短棹舣湍石，华月满汀洲。\n应知孤客无寐，特地照离忧。\n谁念娥单枕，寂寞广寒宫殿，亦自□□□。\n□□□□□，□□□□□。\n□怜我，尘满袖，雪盈头。\n两乡千里萦恨，何事不归休。\n遥想闺中今夜，夜久寒生玉臂，犹自倚高楼。\n别泪入湘水，归梦绕州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2182, '念奴娇', '向', '霜威凄紧，政悲风摇落，千山群木。\n十里清香方盛赏，岩桂娇黄姹绿。\n九畹衰丛，东篱落蕊，到此成粗俗。\n孤标高远，淡然还媚幽独。\n憔悴诗老多情，问佳人底事，幽居空谷。\n日暮天寒垂翠袖，愁倚萧萧修竹。\n林下神情，月边风露，不向雕栏曲。\n殷勤惟有，篆烟留得馀馥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2183, '满庭芳', '向', '玉粉匀梅，曲尘浮柳，画檐迟日融融。\n金猊喷麝，庭户转香风。\n好是闲居戏彩，寿觞举、和满春容。\n须知道，闺门孕秀，佳气在帘栊。\n无穷。\n观盛事，年年此会，拚醉金锺。\n又何须、西池高宴仙宫。\n尽把乔松□寿，兼大国、秦虢重封。\n那堪更，门阑多喜，女婿近乘龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2184, '青玉案', '向', '别时泪花无语。\n但一味、教郎住。\n此日扁舟游远浦。\n雨晴云树。\n月斜烟树。\n目断家何许。\n红笺不寄相思句。\n人在潇湘雁回处。\n屈指归期秋已暮。\n万千里路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2185, '青玉案', '向', '多情赋得相思分。\n便揽断、愁和闷。\n万种千般说不尽。\n吃他圈柜，被他拖逗，便佛也、须教恨。\n传消寄息无凭信。\n水远山遥怎生奔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2186, '小重山', '向', '翡翠林梢青黛山。\n小楼新罨画，卷珠帘。\n碧纱窗外水挪蓝。\n凭栏处，相对玉纤纤。\n人散酒阑珊。\n夜长都睡皱，唾花衫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2187, '踏莎行', '向', '万水千山，两头三绪。\n凭高望断迢迢路。\n钱塘江上客归迟，落花流水青春暮。\n步步金莲，朝朝琼树。\n目前都是伤心处。\n飞鸿过尽没书来，梦魂依旧阳台雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2188, '蝶恋花', '向', '费尽东君无限巧。\n玉减香销，回首令人老。\n梦绕岭头归未到。\n角声吹断江天晓。\n燕子来时春正好。\n寸寸柔肠，休问愁多少。\n从此欢心还草草。\n凭栏一任桃花笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2189, '临江仙', '向', '瘦损东阳缘底事，离愁别恨难禁。\n夜长谁共拥孤衾。\n来时青鬓在，今已二毛侵。\n流水青山依旧是，兰桡往事空寻。\n一番风雨又春深。\n桃花都落尽，赢得是清阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2190, '临江仙', '向', '乱後此身何计是，翠微深处柴扉。\n即今双鬓已如丝。\n虚名将底用，真意在鸱夷。\n治国无谋归去好，衡门犹可栖迟。\n不妨沈醉典春衣。\n人生行乐耳，须富贵何时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2191, '武陵春', '向', '长记酒醒人散後，风月满江楼。\n楼外烟波万顷秋。\n高槛冷飕飕。\n想见云鬟香雾湿，斜坠玉搔头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2192, '阮郎归', '向', '隔篱疏影照横塘。\n东风吹暗香。\n陇头归路指苍茫。\n江南春兴长。\n扃小院，静回廊。\n有人凭短墙。\n角声惊梦月横窗。\n此时能断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2193, '南乡子', '向', '临水窗儿。\n与卷珠帘看画眉。\n雨浴红衣惊起後，争知。\n水远山长各自飞。\n受尽孤凄。\n极目风烟说与谁。\n直是为他憔悴损，寻思。\n怎得心肠一似伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2194, '西江月', '向', '流水断桥衰草，西风落日清笳。\n往来赢得鬓边华。\n此去征鞍休跨。\n烟溆绿深陂筱，霜篱红老江花。\n青山尽处是侬家。\n拟唤渔舟东下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2195, '西江月', '向', '门柳疏疏映日，井桐策策翻秋。\n萧条不似那时游。\n只有山光依旧。\n别久犹牵去梦，怀多还惹新愁。\n吹箫人在雁回州。\n不管沈郎消瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2196, '西江月', '向', '竹寺青灯永夜，江城黄叶高秋。\n当时文物尽交游。\n更为笛声怀旧。\n牢落一生羁思，风流万斛诗愁。\n强邀从事到青州。\n酒病绵绵越瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2197, '西江月', '向', '抵死漫生要见，偷方觅便求欢。\n十分赢得带围宽。\n划地如今难恋。\n枕畔水沈烟尽，床头银蜡烧残。\n鸳衾不觉夜深寒。\n记取有人肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2198, '西江月', '向', '别後千思万想，眼前一日三秋。\n小街栏槛记追游。\n料得新妆依旧。\n自笑非常蒂，为他无限闲愁。\n莫将离恨寄州。\n闻道腰肢愈瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2199, '虞美人', '向', '酒阑枕新凉夜。\n断尽人肠也。\n西风吹起许多愁。\n不道沈腰潘鬓、不禁秋。\n如今病也无人管。\n真个难消遣。\n东邻一笑直千金。\n争奈茂陵情分、在文君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2200, '虞美人', '向', '宝梳半脱文窗里。\n玉软因谁醉。\n锦鸳应是懒熏香。\n□我水村孤酌、减疏狂。\n此时纵有千金笑。\n情味如伊少。\n带围宽尽莫教知。\n嫌怕为侬成病、似前时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2201, '南歌子', '向', '路尽湘江水，人行瘴雾间。\n昏昏西日度严关。\n天外一簪初见、岭南山。\n北雁连书断，新霜点鬓斑。\n此时休问几时还。\n准拟桂林佳处、过春残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2202, '点绛唇', '向', '屈指新冬，肃霜天气重阳後。\n授衣时候。\n兰菊香盈袖。\n此日生申，维岳锺神秀。\n倾名酎。\n篆添金兽。\n共祝如椿寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2203, '减字木兰花', '向', '多情被恼。\n枉了东君无限巧。\n真个愁人。\n一片轻飞减却春。\n阑干凭暖。\n目断彩云肠也断。\n两岸青山。\n隐隐孤舟浪接天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2204, '朝中措', '向', '平生此地几经过。\n家近奈情何。\n长记月斜风劲，小舟犹渡烟波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2205, '忆秦娥', '向', '秋萧索。\n别来先自情怀恶。\n情怀恶。\n日斜庭院，月明帘幕。\n轻离却似於人薄。\n而今休更思量著。\n思量著。\n肝肠空断，水云辽邈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2206, '摊破丑奴儿・采桑子', '向', '自笑好痴迷。\n只为俺、忒雏儿。\n近来都得傍人道，帖儿上面，言儿语子，那底都是虚脾。\n楼上等多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2207, '好事近', '向', '清晓渡横江，江上月寒霜白。\n寂寞断桥南畔，有一枝春色。\n玉肌孤瘦恰如伊，此际转相忆。\n且道这些烦恼，看几时休得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2208, '点绛唇', '向', '蕙怨兰愁，玉台羞对啼妆面。\n懒匀香脸。\n不放眉峰展。\n幽恨谁知，锦字空传远。\n何时见。\n为郎肠断。\n不似郎情浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2209, '阮郎归', '向', '湘南楼上好凭栏。\n西风吹鼻酸。\n宦游何处不惊湍。\n白鸥盟已寒。\n空饮恨，废追欢。\n沈郎衣带宽。\n故人休放酒杯乾。\n而今行路难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2210, '如梦令', '向', '旧恨新愁无际。\n近水远山都是。\n西北有高楼，正为行藏独倚。\n留滞。\n留滞。\n家在吴头楚尾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2211, '如梦令', '向', '梦断绿窗莺语。\n消遣客愁无处。\n小槛俯青郊，恨满楚江南路。\n归去。\n归去。\n花落一川烟雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2212, '如梦令', '向', '直面雨轻风峭。\n极目水空烟渺。\n家在武陵溪，无限壑讥峰诮。\n归好。\n归好。\n睡足一江春晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2213, '如梦令', '向', '楼上千峰翠。\n楼下一湾清浅。\n宝簟酒醒时，枕上月华如练。\n留恋。\n留恋。\n明日水村烟岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2214, '如梦令', '向', '杨柳千丝万缕。\n特地织成愁绪。\n休更唱阳关，便是渭城西路。\n归去。\n归去。\n红杏一腮春雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2215, '如梦令', '向', '野店几杯空酒。\n醉里两眉长皱。\n已自不成眠，那更酒醒时候。\n知否。\n知否。\n直是为他消瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2216, '如梦令', '向', '谁伴明窗独坐。\n和我影儿两个。\n灯烬欲眠时，影也把人抛躲。\n无那。\n无那。\n好个惶的我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2217, '如梦令', '向', '厮守许多时价。\n谁信一筹不画。\n相送到矾园，赢得泪珠如泻。\n挥洒。\n挥洒。\n将底江州司马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2218, '长相思', '向', '桃花堤。\n柳花堤。\n芳草桥边花满溪。\n而今戎马嘶。\n千山西。\n万山西。\n归雁横云落日低。\n登楼望欲迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2219, '长相思', '向', '行相思。\n坐相思。\n两处相思各自知。\n相思更为谁。\n朝相思。\n暮相思。\n一日相思十二时。\n相思无尽期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2220, '菩萨蛮', '向', '小楼不放珠帘卷。\n菱花羞照啼妆面。\n金鸭水沈烟。\n待君来共添。\n鹊声生暗喜。\n翠袖轮纤指。\n细细数归程。\n脸桃春色深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2221, '菩萨蛮', '向', '云屏月帐孤鸾恨。\n香消玉减无人问。\n斜倚碧琅。\n萧萧生暮寒。\n低垂双翠袖。\n袖薄轻寒透。\n庭院欲黄昏。\n凝情空断魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2222, '清平乐', '向', '离愁万斛。\n春思难拘束。\n瘦尽玉肌清彻骨。\n蹙损两眉秀绿。\n画屏罗幌输君。\n文鳞锦翼尤勤。\n长记酒醒香冷，笑将髻子隈人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2223, '卜算子', '向', '休逞一灵心，争甚闲言语。\n十一年间并枕时，没个牵情处。\n四岁学言儿，七岁娇痴女。\n说与傍人也断肠，你自思量取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2224, '念奴娇', '程大昌', '冰容玉格，笑桃杏、非是闺帏装束。\n待要舒华那更管，朔气凝波僵木。\n五鬣山松，万年宫树，仅仅存馀绿。\n一枝寄赠，教渠知道春复。\n宁解车马成蹊，高标宜雪月，仍便溪谷。\n纵有知闻，谁办得、驾野凌寒秉烛。\n尽更荒闲，终难掩抑，风里香千斛。\n林兴尽，此时鼎味翻足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2225, '浣溪沙', '程大昌', '乾处缁尘湿处泥。\n天嫌世路净无时。\n皓然岩谷总凝脂。\n清夜月明人访戴，玉山顶上玉舟移。\n一蓑渔画更能奇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2226, '浣溪沙', '程大昌', '兽炭香红漫应时。\n遮寒姝丽自成围。\n销金暖帐四边垂。\n报道黑风飞柳絮，齐翻白雪侑羔卮。\n那家斟唱□□词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2227, '浣溪沙', '程大昌', '翦水飞花也大奇。\n熬波出素料同机。\n会心一笑撒盐诗。\n谁拥醴酏夸岁瑞，恨无坚白怨朝曦。\n闭门高卧有人饥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2228, '浣溪沙', '程大昌', '始待空冬岁不华。\n还教呈瑞怨贫家。\n若为高下总无嗟。\n日照华檐晴後雨，风吹飞絮腊前花。\n天公何事不由他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2229, '浣溪沙', '程大昌', '水递迢迢到日边。\n清甘夸说与茶便。\n谁知绝品了非泉。\n旋挹天花融液，净无土脉污芳鲜。\n乞君风腋作飞仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2230, '万年欢', '程大昌', '岁岁梅花，向寿尊画阁，长报春起。\n恰似今朝，分外香肥萼。\n杂佩珊珊就列，映蓝袂、宝薰擎跽。\n道这回、屋舍团栾，四时风月桃李。\n回头处、无限思。\n看秋前药裹，而今鼎匕。\n须把康强，收作玳筵欢喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2231, '汉宫春', '程大昌', '万六千年，是仙椿日月，两度阳春。\n根柯不随物化，那有新陈。\n戏夸悠久，借时光、惊觉时人。\n道历管，阶万换，悠然唤做逡巡。\n老我百无贪羡，羡天芳寿种，掩冉三辰。\n谢他流年甲子，已是重轮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2232, '好事近', '程大昌', '日绎五千言，未说年龄可续。\n且得襟期萧散，远氛嚣宠辱。\n鬓须白尽秀眉生，来伴老眸绿。\n人道雪霜林里，有翠松鲜竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2233, '减字木兰花', '程大昌', '距春五日。\n吉语搀先来饮席。\n易卦占新。\n八八周轮又再轮。\n开年定好。\n定把笙歌更药裹。\n旧怕无孙。\n今已蓝袍拥绣荪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2234, '卜算子', '程大昌', '春产不贪春，为厌春花泛。\n睡到深秋梦始回，素影翻春艳。\n意赏逐时新，旧事谁能占。\n解转春光入酒杯，萸菊谁云欠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2235, '感皇恩', '程大昌', '七十在前头，难言未老。\n只是中间有些好。\n云虽瘦，未有一根华皓。\n都缘心地静，无忧恼。\n此际生朝，梅花献笑。\n似向天边得新报。\n孙枝秀雅，已挂恩袍春草。\n定从欢喜处，添年考。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2236, '感皇恩', '程大昌', '池馆足名花，四时蔫馥。\n就里梅春春到速。\n周遭松竹，任是雪霜长绿。\n总堪供寿乐，翻新曲。\n别向心田，有般奇木。\n依约灵椿共标目。\n八千换历，才当一番春复。\n莫乱春起处，醅浮玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2237, '万年欢', '程大昌', '富寿康宁，要三般齐足，方是有福。\n献个新词，不是越夸搀祝。\n七十古稀今独。\n花钗底、髻云堆绿。\n那堪更、眼力过人，彩丝穿透珠曲。\n星辰履阶庭玉。\n对这般景趣，乐胜笙筑。\n更原孙枝衮衮，诜诜续续。\n解把诗书勤读。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2238, '韵令', '程大昌', '是男是女，都有官称。\n孙儿仕也登。\n时新衣著，不待经营。\n寒时火柜，春里花亭。\n星辰上履，我只唤卿卿。\n寿开八秩，两鬓全青。\n颜红步武轻。\n定知前面，大有年龄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2239, '折丹桂', '程大昌', '童年未晓君恩重。\n教得能趋拱。\n重亲带笑酌天杯，听祝语、殷勤捧。\n青衫得挂尤光宠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2240, '水调歌头', '程大昌', '绿净贯，夹岸是楼台。\n楼台分影倒卧，千丈郁崔嵬。\n此是化人奇变，能使山巅水底，对出两蓬莱。\n溪浒有仙观，苕信佳哉。\n水晶宫，谁著语，半嘲诙。\n世间那有，如许磊栋梁材。\n每遇天容全碧，仍更苹风不动，相与夜深来。\n饮子以明月，净洗旧尘埃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2241, '临江仙', '程大昌', '遥认埙篪相应，为传珠贯累累。\n紫荆同本但殊枝。\n直须投老日，常似有亲时。\n子姓亦闻多慧性，贪书不是痴儿。\n朝家世世重诗书。\n一登龙虎榜，许并凤凰池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2242, '临江仙', '程大昌', '抗步碧潭弥弥，五畲青髻累累。\n何年乔木倚筇枝。\n搜寻同队者，追说钓游时。\n今日昂藏称壮子，向来襁褓婴儿。\n年周甲子又重书。\n岂容藏老丑，照白有清池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2243, '临江仙', '程大昌', '夹路传呼杳杳，垂腰印绶累累。\n万般荣贵出丹枝。\n遥知心乐处，椿畔桂当时。\n酒到芳春偏弄色，轻黄泛滟鹅儿。\n大为行乐使堪书。\n醉来花下卧，便是习家池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2244, '好事近', '程大昌', '绿鬓又红颜，谁道年周甲子。\n两婿□□蓝绶，那一儿何虑。\n只今卜筑水晶宫，归安好名义。\n金紫珈笄偕老，备长生福贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2245, '好事近', '程大昌', '白屋到横金，已是蟠桃结子。\n更向仕途贪恋，是痴人呆虑。\n水晶宫里饭莼鲈，中菰第一义。\n留得鬓须迟白，是本来真贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2246, '浣溪沙', '程大昌', '物本无情人有情。\n百般禽百般声。\n有人闻鹊不闻莺。\n我盏通神君信否，酒才著盏月随生。\n大家吸月当箫笙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2247, '万年欢', '程大昌', '秋後花窠，放两枝三朵，来通芳信。\n诗眼惊观，谓是春光倒运。\n便即移尊就赏，更不惜、黄封赤印。\n何期道，青女专时，露华忽变霜阵。\n诗翁笑、但休问。\n那阳和有脚，日进。\n待得灰飞，梅畹果先骋俊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2248, '感皇恩', '程大昌', '身寿又康强，谢天将并。\n耳目聪明行步壮。\n登高挥翰，不用瞠眉扶杖。\n华堂偕老处，儿孙王。\n只恨萍蓬，他乡浮荡。\n回首故山便惆怅。\n今年生日，忽似还家模样。\n当缘风絮韫，来赓唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2249, '感皇恩', '程大昌', '画舸白苹洲，如归故里。\n老幼欢迎僮婢喜。\n较量心事，岁岁春风弧矢。\n今年称寿处，尤欢美。\n嫁得黔娄，苦耽书史。\n文字流传曾贵纸。\n便同黼黻，何似实头龟紫。\n天公闻此语，应怜许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2250, '感皇恩', '程大昌', '变化属朝班，鲲鹏相并。\n健翼垂云风用壮。\n扶摇得势，不藉仙人仙杖。\n旁观生意气，犹神王。\n此去汉庭，春光骀荡。\n亲见子虚不惆怅。\n鸢肩捷上，自有唐家格样。\n三台旬月里，堪歌唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2251, '感皇恩', '程大昌', '中外受郊恩，三封纶告。\n依并小君出称号。\n锦犀光艳，不比香薰脂膏。\n况从鸣瑟里，添花草。\n更愿天公，别施洪造。\n水长船高愈新好。\n恁时舞带，一任巧装百宝。\n曲终珠满地，从人扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2252, '感皇恩', '程大昌', '措大做生朝，无他珍异。\n填个曲儿为鼓吹。\n古来龙马，曾献河图真数。\n羲黄缘得此，齐元气。\n我向如今，职名升赐。\n地在天宫正东序。\n当初真本，到此或容披觑。\n这回错综处，堪详叙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2253, '感皇恩', '程大昌', '七十有三番，挂弧门首。\n此事从来信希有。\n新来仕路，夸说一般高手。\n肯从清要地，抛簪绶。\n何许分花，伊谁送酒。\n得开口时且开口。\n无烦无恼，也没期程奔走。\n但能安此乐，夷然寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2254, '感皇恩', '程大昌', '锦告侈脂封，煌煌家宝。\n偕老之人已华皓。\n绿云拥鬓，更没一根入老。\n但从和看，年堪考。\n叶是松苗，松为叶脑。\n禀得松神大都好。\n人人戴白，独我青青常保。\n只将平易处，为蓬岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2255, '感皇恩', '程大昌', '一岁一生朝，一番老相。\n无欲无营亦无望。\n看经写字，且做闲中气象。\n闭门人阒静，心清旷。\n骨肉团栾，一杯相向。\n野蔌家肴竞来饷。\n真情直话，不用逢迎俯仰。\n从他人笑道，不时样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2256, '好事近', '程大昌', '桃柳旧根株，春到红蔫绿茁。\n一似老年垂白，带少容发。\n浮家泛宅在他乡，难得会瓜葛。\n幸对此番乐饮，任宵分明发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2257, '好事近', '程大昌', '盥水结冰花，老眼於今重见。\n一似琢成水玉，向冻盆游泛。\n天公作事有何难，要花花便现。\n且把重春留住，变苍黎容面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2258, '好事近', '程大昌', '腊月做生朝，只有南枝梅玉。\n此外後生桃李，未舒英吐馥。\n後园别自出神奇，现双松双竹。\n报道前堂琴瑟，俱长生厚福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2259, '水调歌头', '范成大', '元日至人日，未有不阴时。\n新年叶气，无处人物不熙熙。\n万岁声从天下，一札恩随春到，光采动天鸡。\n寿域遍寰海，直过雪山西。\n忆曾预，宣玉册，捧金卮。\n如今万里，魂梦空绕五云飞。\n想见大庭宫馆，重起三山楼观，双指赭黄衣。\n此会古无有，何止古来稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2260, '浣溪沙', '范成大', '十里西畴熟稻香。\n槿花篱落竹丝长。\n垂垂山果挂青黄。\n浓雾知秋晨气润，薄云遮日午阴凉。\n不须飞盖护戎装。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2261, '破阵子', '范成大', '漂泊天隅佳节，追随花下群贤。\n只欠山阴修禊帖，却比兰亭有管弦。\n舞裙香未湔。\n泪竹斑中宿雨，折桐雪里蛮烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2262, '鹧鸪天', '范成大', '楼观青红倚快晴。\n惊看陆地涌蓬瀛。\n南园花影笙歌地，东岭松风鼓角声。\n山绕水，水萦城。\n柳边沙外古今情。\n坐中更有挥豪客，一段风流画不成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2263, '酹江月・念奴娇', '范成大', '浮生有几，叹欢娱常少，忧愁相属。\n富贵功名皆由命，何必区区仆仆。\n燕蝠尘中，鸡虫影里，见了还追逐。\n山间林下，几人真个幽独。\n谁似当年严君，故人龙衮，独抱羊裘宿。\n试把渔竿都掉了，百种千般拘束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2264, '水调歌头', '范成大', '万里筹边处，形胜压坤维。\n恍然旧观重见，鸳瓦拂参旗。\n夜夜东山衔月，日日西山横雪，白羽弄空晖。\n人语半霄碧，惊倒路傍儿。\n分弓了，看剑罢，倚阑时。\n苍茫平楚无际，千古锁烟霏。\n野旷岷江动，天阔崤函云拥，太白暝中低。\n老矣汉都护，却望玉关归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2265, '木兰花慢', '范成大', '古人吾不见，君莫是、郑当时。\n更筑就山房，躬耕谷口，名动京师。\n诸公任他衮衮，与杜陵野老共襟期。\n有客至门先喜，得钱沽酒何疑。\n昔年连辔柳边归。\n陈迹恍难追。\n况种桃道士，看花才子，回首皆非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2266, '贺新郎', '游次公', '暖霭浮晴。\n锁垂杨、龙池罩阁，万丝千缕。\n池上晓光分宿雾，日近群芳易吐。\n寻并蒂、阑干凝伫。\n不信钗头飞凤去，但宝刀、被妾还留住。\n天一笑，万花妒。\n阿娇正好金屋贮。\n甚西风、易得萧疏，扇鸾尘土。\n一自昭阳扃玉户，墙角土花无数。\n况多病、情伤幽素。\n别殿时闻箫鼓奏，望红云、冉冉知何处。\n天尺五，去无路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2267, '卜算子', '游次公', '风雨送人来，风雨留人住。\n草草杯话别离，风雨催人去。\n泪眼不曾晴，眉黛愁还聚。\n明日相思莫上楼，楼上多风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2268, '满江红', '游次公', '云接苍梧，山莽莽、春浮泽国。\n江水涨、洞庭相近，渐近空阔。\n江燕飘飘身似梦，江花草草春如客。\n望渔春、樵市隔平林，寒烟色。\n方寸乱，成丝结。\n离别近，先愁绝。\n便满篷风雨，橹声孤急。\n白发论心湖海暮，清樽照影苍浪窄。\n看明年、天际下归舟，应先识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2269, '贺新郎', '游次公', '斗柄回秋律。\n素蟾飞、冰霜万里，满川金碧。\n得月偏多何处是，惟有桥南第一。\n正野迥、西风寒寂。\n丹桂婆娑疏影在，想微瑕、未累千金璧。\n河汉远，澹无迹。\n知君有句酬佳夕。\n尽高歌、胡床自倚，露珠溢。\n坐到参横星欲暗，隐隐天低似笠。\n但络纬、悲啼催织。\n吟咏凄凉翻有恨，谅知音、人远空追忆。\n谁为置，郑庄驿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2270, '满江红', '游次公', '一舸归来，何太晚、鬓丝如织。\n谩叹息、凄凉往事，尽成陈迹。\n山迫暮烟浮紫翠，溪摇寒浪翻金碧。\n看长虹、渴饮下青冥，危栏湿。\n谁可住，烟萝侧。\n俗士驾，当回勒。\n伴岩扃，须是碧云仙客。\n风月已供无尽藏，溪山更衍清凉国。\n恨谪仙、苏二不曾来，无人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2271, '满江红', '赵老', '见说春时，新波涨、二川溶溢。\n今底事、沙痕犹褪，石渠悭碧。\n人意不须长作解，兴来便向杯中觅。\n纵茂林修竹记山阴，千年一。\n薰吹动，春工毕。\n桥上景，壶中日。\n况梅肥笋嫩，雨微鱼出。\n只恐延英催入觐，不教绿野长均逸。\n任多情、胡蝶满园飞，狂踪迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2272, '满江红', '赵老', '西郭园林，湖光净、暮寒清溢。\n明月上，近环山翠，远摇天碧。\n粉泽兰膏违俗尚，岩花磴蔓从谁觅。\n问近来、铛脚许何人，吾其一。\n欢乐事，休教毕。\n经後夜，思前日。\n想无心不竞，水流云出。\n物外烟霞供啸咏，个中鱼鸟同休逸。\n又何须、浮海访三山，寻仙迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2273, '满江红', '赵老', '潇洒星郎，吹绿鬓、胜游霞举。\n秋又半，月磨云翳，籁传风语。\n太一青黎光对射，中流荡漾莲舟舞。\n戏人间、今夜水精宫，前无古。\n吾家是，蓬山侣。\n歌舞袖，苹花渚。\n拟问津斜汉，乘槎南浦。\n谒帝通明今得便，素娥拍手心先许。\n笑画阑、三十六宫秋，花如土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2274, '念奴娇', '赵老', '冰蟾驾月，荡寒光、不见层波层碧。\n几岁中秋争得似，云卷秋声寂寂。\n多谢星郎，来陪贤令，快赏鳌峰极。\n广寒宫近，素娥不靳馀力。\n夜久露落琼浆，神京归路，有云翘前迹。\n当日仙人曾驭气，只学神交龟息。\n今夜清尊，一齐分付，稳是乘槎客。\n天津重到，霓裳何似闻笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2275, '水调歌头', '赵老', '梅仙了无讼，拄笏看西山。\n山涵秋晓，水光磨荡有无间。\n自是灵襟空洞，更望风云吞吐，浩渺白鸥闲。\n高诵远游赋，独立桂香阑。\n谩常谈，如观水，要观澜。\n物情长在，人生何用苦求难。\n随我一觞一咏，任彼非元彼非白，唯放酒杯宽。\n富贵偿来事，天道管知还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2276, '永遇乐', '赵老', '香雪堆梅，绣丝蹙柳，仙馆春到。\n午夜华灯，烘春艳粉，月借今宵好。\n衮衣摇曳，簪缨闲绕，共祝大椿难老。\n望台躔、明星一点，冰壶表里相照。\n诞弥令节，欣欣物态，共喜重生周召。\n八鼎勋庸，九夷姓字，策杖孤鸿杳。\n鸦啼鹊噪，兰馨松茂，把酒共春一笑。\n管如今、盐梅再梦，夜铃命诏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2277, '醉蓬莱', '赵老', '听都人歌咏，便启金瓯，再登元老。\n山色溪声，与春风齐到。\n补衮工夫，望梅心绪，见丹青重好。\n鹊噪晴空，灯迎诞节，槐堂欢笑。\n正是元宵，满天和气，璧月流光，雪消寒峭。\n今夜今年，表千年同照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2278, '醉蓬莱', '赵老', '记青蛇感异，後日扶颠，太平人瑞。\n壮岁弹冠，有经邦高志。\n晚上文墀，载严霜简，便云龙交际。\n紫极旋枢，金蝉映衮，乾坤开霁。\n底事当时，饮江胡马，一望云旗，倒戈投贽。\n此片丹心，几风声鹤唳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2279, '鹧鸪天', '赵老', '堂上年时见烛花。\n青毡还入旧时家。\n芝函瑞色回春早，绿野东风转岁华。\n催召传，稳铺沙。\n垒尊今日枣如瓜。\n诞辰更接传柑宴，莲炬通宵唤草麻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2280, '鹧鸪天', '赵老', '白日青天一旦明。\n旧时勋业此时情。\n延英再许裴公对，商鼎须调传说羹。\n千万载，辅宗。\n挚天八柱愈峥嵘。\n将军犁却龙庭後，岁傍鳌山奏太平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2281, '生查子', '赵老', '章甫不如人，翠绾垂杨缕。\n纤手送来时，罗帕缄香雾。\n貂婵懒上头，渭水知何处。\n风月共垂竿，脱帽须亲付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2282, '生查子', '赵老', '朝路进贤归，厌听歌金缕。\n不念玉堂花，豹隐南山雾。\n漉酒未巾时，暑槛披风处。\n子夏不兼人，并与诗筒付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2283, '生查子', '赵老', '金门一免时，离绪纷如缕。\n想像切云高，晓日罗昏雾。\n峨冠补衮人，不是无心处。\n欲效贡公弹，衣钵知谁付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2284, '生查子', '赵老', '斜日下平川，楼角销霞缕。\n摆尽浊尘缨，画栋萦非雾。\n平生许子穷，今到知音处。\n约伴玉簪游，好梦从天付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2285, '南柯子・南歌子', '赵老', '世上渊明酒，人间陆羽茶。\n东山无妓有莲花。\n隐隐仙家鸡犬、路非赊。\n积霭犹张幕，轻雷似卷车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2286, '南柯子・南歌子', '赵老', '体质娟娟静，花纹细细装。\n翠筠初得试新忙。\n睡起鬓云撩乱、趣泉汤。\n多病心常捧，新词字带香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2287, '浣溪沙', '赵老', '懒画娥眉倦整冠。\n笋苞来点镜中鬟。\n承恩容易报恩难。\n发未饶青箬笠，素鳞行簇水晶盘。\n流觞元自不相干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2288, '浣溪沙', '赵老', '刘氏风流设此冠。\n今谁将去伴珠鬟。\n君家兄弟二俱难。\n驰去请观流汗马，钓时休等烂银盘。\n明朝吟咏有方干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2289, '瑞鹧鸪', '尤袤', '梁溪西畔小桥东。\n落叶纷纷水映空。\n五夜客愁花片里，一年春事角声中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2290, '瑞鹧鸪', '尤袤', '两行芳蕊傍溪阴。\n一笑嫣然抵万金。\n火齐照林光灼灼，彤霞射水影沈沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2291, '阮郎归', '赵', '留连春意晚花稠。\n云疏雨未收。\n新荷池面叶齐抽。\n凉天醉碧楼。\n能达理，有何愁。\n心宽万事休。\n人生还似水中沤。\n金尊尽更酬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2292, '忆少年', '谢懋', '池塘绿遍，王孙芳草，依依斜日。\n游丝卷晴昼，系东风无力。\n蝶趁幽香蜂酿蜜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2293, '石州引・石州慢', '谢懋', '日脚斜明，秋色半阴，人意凄楚。\n飞雪特地凝愁，做弄晚来微雨。\n谁家别院，舞困几叶霜红，西风送客闻砧杵。\n鞭马出都门，正潮平洲渚。\n无语。\n匆匆短棹，满载离愁，片帆高举。\n京洛红尘，因念几年羁旅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2294, '洞仙歌', '谢懋', '愁边雨细。\n漠漠天如醉。\n摇扬游丝晚风外。\n酿轻寒、和暝色，花柳难胜，春自老，谁管啼红敛翠。\n关情潜入夜，斜湿帘栊，几处挑灯耿无寐。\n念阳台、当日事，好伴云来，因个甚、不入襄王梦里。\n便添起、寒潮卷长江，又恐是离人，断肠清泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2295, '杏花天', '谢懋', '海棠枝上东风软。\n荡霁色、烟光弄暖。\n双双燕子归来晚。\n零落红香过半。\n琵琶泪青衫浅。\n念事与、危肠易断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2296, '画堂春', '谢懋', '西风庭院雨垂垂。\n黄花秋闰迟。\n已凉天气未寒时。\n才褪单衣。\n睡起枕痕犹在，鬓松钗压云低。\n玉奁重拂淡胭脂。\n情入双眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2297, '武陵春', '谢懋', '门掩东风人去後，愁损燕莺心。\n一朵梅花淡有春。\n粉黛不匀。\n我亦青楼成倦客，风月强追寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2298, '霜天晓角', '谢懋', '绿云剪叶。\n低护黄金屑。\n占断花中声誉，香与韵、两清洁。\n胜绝。\n君听说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2299, '风流子', '谢懋', '少年多行乐，方豪健、何处不嬉游。\n记情逐艳波，暖香斜径，醉摇鞭影，扑絮青楼。\n难忘是，笑歌偏婉娩，乡号得温柔。\n娇雨娱云，旋宽衣带，剩风残月，都在眉头。\n一成憔悴损，人惊怪，空自引镜堪羞。\n谁念短封难托，征雁虚浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2300, '念奴娇', '谢懋', '霁天湛碧。\n正新凉风露，冰壶清彻。\n河汉无声光练练，涌处银蟾孤绝。\n岩桂香飘，井梧影转，冷浸官袍洁。\n西厢往事，一帘清梦凄切。\n肠断楚峡云归，尊前无绪，知有愁如发。\n此夕常娥应也恨，冷落琼楼金阕。\n禁漏迢迢，边鸿杳杳，幽意凭谁决。\n阑干星斗，落梅三弄初阕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2301, '鹊桥仙', '谢懋', '钩帘借月，染云为幌，花面玉枝交映。\n凉生河汉一天秋，问此会、今宵孰胜。\n铜壶尚滴，烛龙已驾，泪西风不尽。\n明朝乌鹊到人间，试说向、青楼薄幸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2302, '解连环', '谢懋', '雁空辽邈。\n衬鱼鳞浪浅，护霜云薄。\n念故人、千里音尘，正山月朦胧，水村依约。\n见说瑶姬，拥十二、碧峰如削。\n倚孤芳澹伫，冷笑岁华，可堪寂寞。\n情多为谁瘦弱。\n爱吹芗弄粉，斜搴珠箔。\n自然林壑精神，想回首东风，万花羞落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2303, '蓦山溪', '谢懋', '厌厌睡起，无限春情绪。\n柳色借轻烟，尚瘦怯、东风倦舞。\n海棠红皱，不奈晚来寒，帘半卷，日西沈，寂寞闲庭户。\n飞雪无据。\n化作冥雨。\n愁里见春来，又只恐、愁催春去。\n惜花人老，芳草梦凄迷，题欲遍，琐窗纱，总是伤春句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2304, '风入松', '谢懋', '老年长忆少年狂。\n宿粉栖香。\n自怜独得东君意，有三年、窥宋东墙。\n笑无落花红影，醉眠芳草斜阳。\n事随春梦去悠扬。\n休去思量。\n近来眼底无姚魏，有谁更、管领年芳。\n换得河阳衰鬓，一帘烟雨梅黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2305, '浪淘沙', '谢懋', '黄道雨初乾。\n霁霭空蟠。\n东风杨柳碧毵毵。\n燕子不归花有恨，小院春寒。\n倦客亦何堪。\n尘满征衫。\n明朝野水几重山。\n归梦已随芳草绿，先到江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2306, '相见欢', '王质', '霜花零落全稀。\n不成飞。\n寒水溶溶漾漾、软琉璃。\n红未涌，青已露，白都。\n□□□□沙暖、戏凫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2307, '长相思', '王质', '红疏疏，紫疏疏。\n可惜飘零著地铺。\n春残心转孤。\n莺相呼。\n燕相呼。\n楼下垂杨遮得乌。\n倚阑人已无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2308, '长相思', '王质', '山青青。\n水青青。\n两岸萧萧芦荻林。\n水深村又深。\n风泠泠。\n露泠泠。\n一叶扁舟深处横。\n垂杨鸥不惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2309, '生查子', '王质', '见汝小溪湾，修竹连疏影。\n林杪动风声，惊下毵毵粉。\n见汝大江郊，高浪摇枯本。\n飞雪密封枝，直到斜阳醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2310, '杨柳枝', '王质', '惯得娇云赶不开。\n去还来。\n淡光无可照楼台。\n且停杯。\n薄雨疏疏时几点，洒浮埃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2311, '浣溪沙', '王质', '何药能医肠九回。\n榴莲不似蜀当归。\n却簪征帽解戎衣。\n泪下猿声巴峡里，眼荒鸥碛楚江涯。\n梦魂只傍故人飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2312, '浣溪沙', '王质', '梦到江南梦却回。\n梦归何处得身归。\n故溪渌净看凫衣。\n下到瞿唐春欲杪，桃花香浪渺无涯。\n三台回望五云飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2313, '浣溪沙', '王质', '征雁年来得几回。\n春风无雁带书归。\n故应春瘦减春衣。\n花柳伤心经岁月，江湖无梦失津涯。\n到家无树不红飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2314, '浣溪沙', '王质', '细雨萧萧变作秋。\n晚风杨柳冷飕飕。\n无言有泪洒西楼。\n眼共云山昏惨惨，心随烟水去悠悠。\n一蓑一笠任孤舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2315, '清平乐', '王质', '江沙带湿。\n莎露和烟泣。\n落日欲低红未入。\n悄悄暮峰凝立。\n疏林秀色荒寒。\n频频驻骑回看。\n应是梧桐影下，秋风蹙碎眉山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2316, '清平乐', '王质', '断桥流水。\n香满扶疏里。\n忽见一枝明眼底。\n人在山腰水尾。\n梨花应梦纷纷。\n征鸿叫断行云。\n不见绿毛么凤，一方明月中庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2317, '清平乐', '王质', '从来清瘦。\n更被春。\n瘦得花身无可有。\n莫放隔帘风透。\n一枝相映孤灯。\n灯明不似花明。\n细看横斜影下，如闻溪水泠泠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2318, '眼儿媚', '王质', '雨润梨花雪未乾。\n犹自有春寒。\n不如且住，清明寒食，数日之间。\n想君行尽嘉陵水，我已下江南。\n想看万里，时须片纸，各报平安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2319, '西江月', '王质', '月斧修成腻玉，风斤琢碎轻冰。\n主人无那寿杯深。\n倩取花来唤醒。\n舞罢绣凤蹙，饮阑画阁香凝。\n试将花蕊数层层。\n犹比长年不尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2320, '西江月', '王质', '轻蜡细凝蜂蜜，薄罗深压鹅黄。\n玉容纵不似何郎。\n也在百花头上。\n试看眉间一点，全如瓶里孤芳。\n明年此日趁行。\n记取今朝胜赏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2321, '西江月', '王质', '蹙蹙红中烟润，梢梢翠尾风斜。\n闲轩幽树少啼鸦。\n此处最宜君画。\n望眼不知天阔，归心常恨山遮。\n见君江浦到芦花。\n意在琵琶亭下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2322, '西江月', '王质', '璧水桥边此客，金銮坡上何人。\n沙场老马事无成。\n泪湿青莹夹镜。\n袖手烟霏小景，回头石岭空城。\n乾坤遗恨渺难平。\n目断塞鸿孤影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2323, '滴滴金', '王质', '阴阴湿雾霜无汁。\n江气逼、树声滴。\n荒林只见夕阳入。\n谁唤晚烟集。\n渔翁犹把钓竿执。\n蓑共笠、时时葺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2324, '燕归来・喜迁莺', '王质', '拂拂春风入马啼。\n□驻绿杨堤。\n绿杨堤上乳莺啼。\n声声怨、怨春归。\n而今一似花流水，纵迹任东西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2325, '青门引・青门饮', '王质', '寻遍江南麓。\n只有斑斑野菊。\n梅花不遇我心悲，一枝得见，便是一年足。\n微香来自横冈竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2326, '鹧鸪天', '王质', '空响萧萧似见呼。\n溪昏树暗觉神孤。\n微茫山路才通足，行到山深路亦无。\n寻草浅，拣林疏。\n虽疏无奈野藤粗。\n春衫不管藤碎，可惜教花著地铺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2327, '鹧鸪天', '王质', '一只船儿任意飞。\n眼前不管是和非。\n鱼儿得了浑闲事，未得鱼儿未肯归。\n全似懒，又如痴。\n这些快活有谁知。\n华堂只见灯花好，不见波平月上时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2328, '一斛珠', '王质', '风流太守。\n未春先试回春手。\n天寒修竹斜阳後。\n翠袖中间，忽有人红袖。\n天香国色浓如酒。\n且教青女休。\n梅花元是群花首。\n细细商量，只怕梅花瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2329, '一斛珠', '王质', '寒江凝碧。\n是谁翦作梨花出。\n花心犹带江痕湿。\n轻注香腮，却是桃花色。\n飞来飞去何曾密。\n疏疏全似新相识。\n横吹小弄梅花笛。\n看你飘零，不似江南客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2330, '一斛珠', '王质', '平塘玉立。\n薄罗飞起层层碧。\n人心不似花心密。\n待要相逢，未必相逢得。\n袜尘不动何曾湿。\n芙蓉桥上曾相识。\n橹声摇去江声急。\n西北高楼，回首浮云隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2331, '怨春郎', '王质', '芦花已老。\n蓼花已老。\n江腹冲风，山头残照。\n暮烟不辨栖鸥。\n识归舟。\n归舟照顾新洲阁。\n惊波恶。\n别拣深湾泊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2332, '虞美人', '王质', '绿阴夹岸人家住。\n桥上人来去。\n行舟远远唤相应。\n全似孤烟斜日、出阊门。\n浪花拂拂侵沙觜。\n直到垂杨底。\n吴江虽有晚潮回。\n未比合江亭下、水如飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2333, '虞美人', '王质', '翠阴融尽毵毵雪。\n惨淡花明灭。\n嫩沙拂拂涨痕添。\n想见故溪、绿到草堂前。\n夕阳红透樱桃粒。\n掩映深沈碧。\n成都事事似江南。\n只是香衾、两处受春寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2334, '临江仙', '王质', '缥缈青宵云一握，太清群玉光中。\n钧天声里拂香风。\n紫皇低接手，稳步上层空。\n雀扇徐开鸾影转，日高舞动蛟龙。\n双瞻御座立昭容。\n回班趋复道，环佩响丁东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2335, '临江仙', '王质', '千顷翠围遮绿净，菱花影落波中。\n看看红锦漾清风。\n此时催入觐，烟浪拍云空。\n伫见觚棱栖宝爵，旌旗全仗飞龙。\n赭黄一点现真容。\n御麻宣未毕，云镜上天东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2336, '临江仙', '王质', '曲水流觞修禊事，祓除洗净春愁。\n举尊再拜寿君侯。\n只今虚鼎足，好去作班头。\n自古相门还出相，春旗小驻南州。\n云孙将绍祖风流。\n他时如见忆，江汉一渔舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2337, '临江仙', '王质', '八字山头来较晚，彩云未散南楼。\n夕阳千丈映帘钩。\n君侯如欲老，江水莫教流。\n扇底清歌尘不动，胡床明月清秋。\n天浆为浪玉为舟。\n酒阑君便起。\n归去立班头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2338, '定风波', '王质', '曲曲阑干曲曲池。\n万红缭绕锦相围。\n花到黄昏思欲睡。\n休睡。\n眼前都是好相知。\n银烛转添花转好，人在，花深深处更相宜。\n似此好花须爱惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2339, '定风波', '王质', '问讯山东窦长卿。\n苍苍云外且垂纶。\n流水落花都莫问，等取，榆林沙月静边尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2340, '定风波', '王质', '白璧黄金爵上卿。\n紫宸殿下拜丝纶。\n才出龙门开虎帐，但看，甲光如水夜如尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2341, '苏幕遮', '王质', '水风轻，吹不皱。\n上下浮光，两镜光相就。\n云锦摇香吹散酒。\n细听清谈，玉屑津津嗽。\n明月前，斜阳後。\n竹露秋声，拂拂寒生袖。\n掇取湖山聊入手。\n紫阁黄扉，到了终须有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2342, '苏幕遮', '王质', '驿尘飞，天意紧。\n香雪芝封，犹带吴泥润。\n昨夜宝奁开玉镜。\n一点西风，便觉寒秋近。\n白苹洲，红蓼径。\n风露凄清，快促黄金镫。\n叠叠重重听好信。\n掷了碧油幢，更掷双堂印。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2343, '南歌子', '张孝祥', '人物羲皇上，诗名沈谢间。\n漫郎元自谩为官。\n醉眼瞢腾、只拟看湘山。\n小隐今成趣，邻翁独往还。\n野堂梅柳尚春寒。\n且趁华灯、频泛酒船宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2344, '霜天晓角', '张孝祥', '柳丝无力。\n冉冉萦愁碧。\n系我船儿不住，楚江上、晚风急。\n棹歌休怨抑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2345, '生查子', '张孝祥', '远山眉黛横，媚柳开青眼。\n楼阁断霞明，帘幕春寒浅。\n杯延玉漏迟，烛怕金刀剪。\n明月忽飞来，花影和帘卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2346, '长相思', '张孝祥', '小楼重。\n下帘栊。\n万点芳心绿间红。\n秋千图画中。\n草茸茸。\n柳松松。\n细卷玻璃水面风。\n春寒依旧浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2347, '忆秦娥', '张孝祥', '元宵节。\n凤楼相对鳌山结。\n鳌山结。\n香尘随步，柳梢微月。\n多情又把珠帘揭。\n游人不放笙歌歇。\n笙歌歇。\n晓烟轻散，帝城宫阕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2348, '苍梧谣・归字谣', '张孝祥', '归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2349, '苍梧谣・归字谣', '张孝祥', '归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2350, '苍梧谣・归字谣', '张孝祥', '归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2351, '水调歌头', '张孝祥', '天上掌纶手，阃外折冲才。\n发踪指示，平荡全楚息氛埃。\n缓带轻裘多暇，燕寝森严兵卫，香篆几徘徊。\n襦绔见歌咏，桃李藉栽培。\n紫泥封，天笔润，日边来。\n趣装入觐，行矣归去作盐梅。\n祖帐不须遮道，看取眉间一点，喜气入尊。\n此去沙堤路，平步上三台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2352, '水调歌头', '张孝祥', '客里送行客，常苦不胜情。\n见公秣马东去，底事却欣欣。\n不为青毡俯拾，自是公家旧物，何必更关心。\n且喜谢安石，重起为苍生。\n圣天子，方侧席，选豪英。\n日边仍有知己，应剡荐章间。\n好把文经武略，换取碧幢红旆，谈笑扫胡尘。\n勋业在此举，莫厌短长亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2353, '木兰花・玉楼春', '张孝祥', '拥貔貅万骑，聚千里、铁衣寒。\n正玉帐连云，油幢映日，飞箭天山。\n锦城起方面重，对筹壶、尽日雅歌闲。\n休遣沙场虏骑，尚馀匹马空还。\n那看。\n更值春残。\n斟绿醑、对朱颜。\n正宿雨催红，和风换翠，梅小香悭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2354, '雨中花・夜行船', '张孝祥', '一舸凌风，斗酒酹江，翩然乘兴东游。\n欲吐平生孤愤，壮气横秋。\n浩荡锦囊诗卷，从容玉帐兵筹。\n有当时桥下，取履仙翁，谈笑同舟。\n先贤济世，偶耳功名，事成岂为封留。\n何况我、君恩深重，欲报无由。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2355, '鹧鸪天', '张孝祥', '可意黄花人不知。\n黄花标格世间稀。\n园葵露迎朝日，槛菊迎霜媚夕霏。\n芍药好，是金丝。\n绿藤红刺引蔷薇。\n姚家别有神仙品，似着天香染御衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2356, '眼儿媚', '张孝祥', '晓来江上荻花秋。\n做弄个离愁。\n半竿残日，两行珠泪，一叶扁舟。\n须知此去应难遇，直待醉方休。\n如今眼底，明朝心上，後日眉头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2357, '虞美人', '张孝祥', '清宫初入韶华管。\n宫叶秋声满。\n满庭芳草月婵娟。\n想见明朝喜色、动天颜。\n持杯满劝龙头客。\n荣遇时难得。\n词源三峡泻瞿塘。\n便是醉中空去、也无妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2358, '菩萨蛮', '张孝祥', '史君家枕吴波碧。\n朱门铺手摇双戟。\n也到岭边州。\n真成汗漫游。\n归期应不远。\n趁得东江暖。\n翁媪雪垂肩。\n双双平地仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2359, '临江仙', '张孝祥', '罨画楼前初立马，隔帘笑语相亲。\n铅华洗尽见天真。\n衫儿轻罩雾，髻子直梳云。\n翠叶银丝簪末利，樱桃澹住香唇。\n见人不语解留人。\n数杯愁里酒，两眼醉时春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2360, '浣溪沙', '张孝祥', '我是临川旧史君。\n而今欲作岭南人。\n重来辽鹤事犹新。\n去路政长仍酷暑，主公交契更情亲。\n横秋阁上晚风匀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2361, '浣溪沙', '张孝祥', '康乐亭前种此君。\n重来风月苦留人。\n儿童竹马笑谈新。\n今代孟士仍好客，政成归去眷方新。\n十眉环坐晚妆匀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2362, '西江月', '张孝祥', '十里轻红自笑，两山浓翠相呼。\n意行着脚到精庐。\n借我绳床小住。\n解饮不妨文字，无心更狎鸥鱼。\n一声长啸暮烟孤。\n袖手西湖归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2363, '忆秦娥', '张孝祥', '天一角。\n南枝向我情如昨。\n情如昨。\n水寒烟淡，雾轻云薄。\n吹花嚼蕊愁无托。\n年华冉冉惊离索。\n惊离索。\n倩春留住，莫教摇落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2364, '浣溪沙', '张孝祥', '湓浦从君已十年。\n京江仍许借归船。\n相逢此地有因缘。\n十万貔貅环武帐，三千珠翠入歌筵。\n功成去作地行仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2365, '柳梢青', '张孝祥', '碧云风月无多。\n莫被名缰利锁。\n白玉为车，黄金作印，不恋休呵。\n争如对酒当歌。\n人是人非恁麽。\n年少甘罗，老成吕望，必竟如何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2366, '卜算子', '张孝祥', '万里去担簦，谁识新丰旅。\n好事些儿说与郎，奴是娥侣。\n若到广寒宫，但道奴传语。\n待我仙郎折桂枝，拣个高枝与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2367, '柳梢青', '张孝祥', '草底蛩吟。\n烟横水际，月澹松阴。\n荷动香浓，竹深凉早，销尽烦襟。\n发稀浑不胜簪。\n更客里、吴霜暗侵。\n富贵功名，本来无意，何况如今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2368, '瑞鹧鸪', '张孝祥', '香佩潜分紫绣囊。\n野塘波急折鸳鸯。\n春风灞岸空回首，落日西陵更断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2369, '青玉案', '张孝祥', '相春堂上闻莺语。\n正花柳、芳菲处。\n有底尊前欢且舞。\n满堂宾客，紫泥丹诏，衮衮烟霄路。\n君王天纵资仁武。\n要尺、平骄虏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2370, '念奴娇', '张孝祥', '海云四敛，太清楼、极目一天秋色。\n明月飞来云雾尽，城郭山川历历。\n良夜悠悠，西风袅袅，银汉冰轮侧。\n云霓三弄，广寒宫殿长笛。\n偏照紫府瑶台，香笼玉座，翠霭迷南北。\n天上人间凝望处，应有乘风归客。\n露滴金盘，凉生玉宇，满地新霜白。\n壶中清赏，画檐高挂虚碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2371, '念奴娇', '张孝祥', '风帆更起，望一天秋色，离愁无数。\n明日重阳尊酒里，谁与黄花为主。\n别岸风烟，孤舟灯火，今夕知何处。\n不如江月，照伊清夜同去。\n船过采石江边，望夫山下，酌水应怀古。\n德耀归来虽富贵，忍弃平生荆布。\n默想音容，遥怜儿女，独立衡皋暮。\n桐乡君子，念予憔悴如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2372, '蓦山溪', '张孝祥', '雄风豪雨，时节清明近。\n帘幕起轻寒，暖红炉、笑翻灰烬。\n阴藏迟日，欲验几多长，绣工慵，围棋倦，香篆频销印。\n茂林芳径，绿变红添润。\n桃杏意酣酣，占前头、一番花信。\n华堂尊酒，但作艳阳歌，禽声喜，流云尽，明日春游俊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2373, '拾翠羽', '张孝祥', '春入园林，花信总诸迟速。\n听鸣禽、稍迁乔木。\n夭桃弄色，海棠芬馥。\n风雨霁，芳径草心频绿。\n禊事才过，相次禁烟追逐。\n想千岁、楚人遗俗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2374, '蝶恋花', '张孝祥', '烂烂明霞红日暮。\n艳艳轻云，皓月光初吐。\n倾国倾城恨无语。\n彩鸾祥凤来还去。\n爱花常为花留住。\n今岁风光，又是前春处。\n醉倒扶归也休诉。\n习池人笑山翁语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2375, '渔家傲', '张孝祥', '红白莲房生一处。\n雪肌霞艳难为喻。\n当是神仙来紫府。\n双禀赋。\n人间相见犹相妒。\n清雨轻烟凝态度。\n风标公子来幽鹭。\n欲遣微波传尺素。\n歌曲误。\n醉中自有周郎顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2376, '夜游宫', '张孝祥', '听话危亭句景。\n芳郊迥、草长川永。\n不待崇冈与峻岭。\n倚栏杆，望无穷，心已领。\n万事浮云影。\n最旷阔、鹭闲鸥静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2377, '鹧鸪天', '张孝祥', '桃换肌肤菊换妆。\n只疑春色到重阳。\n偷将天上千年艳，染却人间九日黄。\n新艳冶，旧风光。\n东篱分付武陵香。\n尊前醉眼空相顾，错认陶潜是阮郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2378, '鹧鸪天', '张孝祥', '人物风流册府仙。\n谁教落魄到穷边。\n独班未引甘泉伏，三峡先寻上水船。\n斟楚酒，扣湘弦。\n竹枝歌里意凄然。\n明时合下清猿泪，闲日须题采凤笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2379, '菩萨蛮', '张孝祥', '落霞残照横西阁。\n阁西横照残霞落。\n波浅戏鱼多。\n多鱼戏浅波。\n手携行客酒。\n酒客行携手。\n肠断九歌长。\n长歌九断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2380, '菩萨蛮', '张孝祥', '渚莲红乱风翻雨。\n雨翻风乱红莲渚。\n深处宿幽禽。\n禽幽宿处深。\n澹妆秋水鉴。\n鉴水秋妆澹。\n明月思情人。\n情人思月明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2381, '菩萨蛮', '张孝祥', '晚花残雨风帘卷。\n卷帘风雨残花晚。\n双燕语虚窗。\n窗虚语燕双。\n睡醒风惬意。\n意惬风醒睡。\n谁与话情诗。\n诗情话与谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2382, '菩萨蛮', '张孝祥', '白头人笑花间客。\n客间花笑人头白。\n年去似流川。\n川流似去年。\n老羞何事好。\n好事何羞老。\n红袖舞香风。\n风香舞袖红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2383, '南歌子', '张孝祥', '路尽湘江水，人行瘴雾间。\n昏昏西北度严关。\n天外一簪初见、岭南山。\n北雁连书断，秋霜点鬓斑。\n此行休问几时还。\n唯拟桂林佳处、过春残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2384, '燕归梁', '张孝祥', '风柳摇丝花缠枝。\n满目韶辉。\n离鸿过尽百劳飞。\n都不似、燕来归。\n旧来王谢堂前地，情分独依依。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2385, '卜算子', '张孝祥', '风生杜若洲，日暮垂杨浦。\n行到田田乱叶边，不见凌波女。\n独自倚危栏，欲向荷花语。\n无奈荷花不应人，背立啼红雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2386, '点绛唇', '张孝祥', '秩秩宾筵，玉潭春涨玻璃满。\n旆霞风卷。\n可但长安远。\n夏木成阴，路袅薰风转。\n空留恋。\n细吹银管。\n别意随声缓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2387, '水调歌头', '张孝祥', '湖海倦游客，江汉有归舟。\n西风千里，送我今夜岳阳楼。\n日落君山云气，春到沅湘草木，远思渺难收。\n徙倚栏杆久，缺月挂帘钩。\n雄三楚，吞七泽，隘九州。\n人间好处，何处更似此楼头。\n欲吊沈累无所，但有渔儿樵子，哀此写离忧。\n回首叫虞舜，杜若满芳洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2388, '锦园春', '张孝祥', '醉痕潮玉。\n爱柔英未吐，露花如簇。\n绝艳矜春，分流芳金谷。\n风梳雨沐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2389, '天仙子', '张孝祥', '三月灞桥烟共雨。\n拂拂依依飞到处。\n雪逑轻扬弄精神，扑不住。\n留不住。\n常系柔肠千万缕。\n只恐舞风无定据。\n容易著人容易去。\n肯将心绪向才郎，待拟处。\n终须与。\n作个罗帏收拾取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2390, '鹧鸪天', '张孝祥', '日日青楼醉梦中。\n不知楼外已春浓。\n杏花未遇疏疏雨，杨柳初摇短短风。\n扶画，跃花骢。\n涌金门外小桥东。\n行行又入笙歌里，人在珠帘第几重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2391, '风入松', '张孝祥', '玉妃孤艳照冰霜。\n初试道家妆。\n素衣嫌怕娥妒，染成宫样鹅黄。\n宫额娇涂飞燕，缕金愁立秋娘。\n湘罗百濯蹙香囊。\n蜜露缀琼芳。\n蔷薇水蘸檀心紫，郁金薰染浓香。\n萼绿轻移云袜，华清低舞霓裳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2392, '瑞鹧鸪', '郭世模', '倾城一笑得留人。\n舞罢娇娥敛黛愁。\n明月宝鞲金洛臂，翠琼花珥碧搔头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2393, '瑞鹤仙', '郭世模', '云阶连月地。\n记旧游、身在温柔乡里。\n花阴透窗绮。\n罗衾拥残梦，流莺惊起。\n银瓶水沸。\n待梳妆、屏风共倚。\n看情眉恨眼，宿粉剩香，乱愁无际。\n长记。\n多情消减，宋玉连墙，茂陵同里。\n离怀似水。\n天涯路，叹愁悴。\n想鸳机织锦，鸾台窥镜，秦丝幽怨未已。\n好归去、共把琴书，倚娇扶醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2394, '朝中措', '郭世模', '青灯听雨夜荒凉。\n归梦苦难长。\n坐想玉奁鸳锦，空馀臂粉衣香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2395, '南歌子', '郭世模', '玉盏浮琼蚁，金奁吐翠虬。\n醉乡归路接温柔。\n暗卜幽期低约、笑藏阄。\n索去眉先锁，将言泪已流。\n小窗移火更迟留。\n自剔灯花油、玉搔头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2396, '念奴娇', '郭世模', '光风转蕙，泛崇兰、漠漠满城飞絮。\n金谷楼危山共远，几点亭亭烟树。\n枝上残花，胭脂满地，乱落如红雨。\n青春将暮，玉箫声在何处。\n无端天与娉婷，帘钩鹦鹉，梦断闻残语。\n玉骨瘦来无一把，手挹罗衣看取。\n江北江南，灵均去後，谁采苹花与。\n香销云散，断魂分付潮去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2397, '浣溪沙', '郭世模', '几点胭脂印指红。\n一双蛾绿敛眉浓。\n夜寒绡帐烛花融。\n剩炷龙涎熏骨冷，旋调银液镇心忪。\n整鬟羞顾半娇慵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2398, '木兰花・玉楼春', '黄仁荣', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2399, '失调名', '许左之', '谁知花有主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2400, '失调名', '许左之', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2401, '念奴娇', '黄谈', '午风清暑，过西湖隐约，曾游堤路。\n云径烟扉人境绝，真是珠宫玄圃。\n倦倚阑干，笑呼艇子，同入荷花去。\n一杯相属，恍然身在何许。\n休怪梦入巫云，凌波罗袜，我在迷湘浦。\n缥缈惊鸿飞燕举，却怨严城钟鼓。\n百斛明珠，千金骏马，豪气今犹故。\n归来清晓，幅巾犹带香露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2402, '水调歌头', '张', '雪月两相映，水石互悲鸣。\n不知岩上枯木，今夜若为情。\n应见尘中胶扰，便道山间空旷，与麽了平生。\n与麽平生了，□水不流行。\n起披衣，瞻碧汉，露华清。\n寥寥千载，此事本分明。\n若向乾坤识易，便信行藏无间，处处总圆成。\n记取渊冰语，莫错定盘星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2403, '水龙吟', '阎苍舒', '少年闻说京华，上元景色烘晴昼。\n朱轮画毂，雕鞍玉勒，九衢争骤。\n春满鳌山，夜沈陆海，一天星斗。\n正红球过了，鸣鞘声断，迥鸾驭、钧天奏。\n谁料此生亲到，十五年、都城如旧。\n而今但有，伤心烟雾，萦愁杨柳。\n宝宫前，绛霄楼下，不堪回首。\n愿皇图早复，端门灯火，照人还又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2404, '柳梢青', '崔敦礼', '惊世文章，门户照人，外家衣钵。\n多谢温存，相期宅相，此恩难说。\n今朝祝寿樽前，共拜舞、诸孙下列。\n但愿从今，一年强似，一年时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2405, '西江月', '崔敦礼', '暖日江南梅柳，春风堂上笙歌。\n满斟笑声哗。\n再拜千年寿嘏。\n清健非缘服玉，红颜不是苍霞。\n仙姿福禄自无涯。\n要看沧溟绿野。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2406, '鹧鸪天', '崔敦礼', '本是瑶台月里仙。\n笑麾鸾鹤住人间。\n蟠桃一熟三千岁，剩对春风日月闲。\n缡绶结，彩衣斑。\n孙枝相应傍门阑。\n年年同上长生酒，得见沧溟几度乾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2407, '鹧鸪天', '崔敦礼', '王母瑶池景物鲜。\n蟠桃华宝不知年。\n天教把定春风笑，来作人间长寿仙。\n披蕊芨，诵云篇。\n朝朝香火篆炉烟。\n只将清静为真乐，合住春秋岁八千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2408, '念奴娇', '崔敦礼', '吴松江畔，对烟波浩渺，相忘鸥鸟。\n日日篮舆湖上路，十里珠帘惊笑。\n高下楼台，浅深溪坞，著此香山老。\n辋川图上，好风吹梦曾到。\n不用金谷繁华，碧城修竹，自比封君号。\n万壑千岩天付与，一洗寒酸郊岛。\n霖雨方思，烟尘未扫，合挽三江倒。\n功成名遂，却来依旧华表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2409, '水调歌头', '崔敦礼', '倚棹太湖畔，踏月上垂虹。\n银涛万顷无际，渺渺欲浮空。\n为问瀛洲何在，我欲骑鲸归去，挥手谢尘笼。\n未得世缘了，佳处且从容。\n饮湖光，披晓月，抹春风。\n平生豪气安用，江海兴无穷。\n身在冰壶千里，独倚朱栏一啸，惊起睡中龙。\n此乐岂多得，归去莫匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2410, '江城子', '崔敦礼', '吴王台上雨初晴。\n远烟横。\n柳如云。\n门外西风，催踏马啼尘。\n声断阳关人去□，遮落日，向西秦。\n不教容易纵归程。\n语酸辛。\n黯消魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2411, '诉衷情', '陈造', '今朝人自藕州来。\n花意尚迟迥。\n几时画船同载，云锦照樽。\n铃斋外，已全开。\n是谁催，诗仙住处，和气回春，羯鼓如雷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2412, '蝶恋花', '陈造', '山立翠屏开几面。\n画舸经行，蒲葺□□岸。\n想过溪门帆影转。\n湖光忽作浮天远。\n诗卷来时春晚。\n愁把钓游，佳处寻思遍。\n不许冷官人所贱。\n拘缠自叹冰蚕茧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2413, '洞仙歌', '陈造', '蝶狂风闹，不到凝香地。\n谁见飞琼巧梳洗。\n厌孤标冷艳，不入时宜，银烛底，酒沁冰肌未睡。\n东君怜索寞，分寄寒斋，闹耐残醒嗅芳蕊。\n费西湖东阁，多少诗愁，援采笔、重与江梅品第。\n算肯容、丹杏接仙游，又却要蕊宫，侍香扶醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2414, '水调歌头', '陈造', '胜日探梅去，邂逅得奇观。\n南枝的，陡觉品俗又香悭。\n曾是瑶妃清瘦，帝与金丹换骨，酒韵上韶颜。\n百叠侈罗袂，小立耐春寒。\n凝香地，古仙伯，玉尘间。\n烦公持并三友，秀色更堪。\n定笑芙蓉骚客，认作东风桃杏，醉眼自相谩。\n相见落诗笔，字字漱龙阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2415, '菩萨蛮', '陈造', '冰花的冰蟾下。\n松烟竹雾溪桥夜。\n斜倚小峰峦。\n依依同岁寒。\n生绡明粉墨。\n浅笑犹倾国。\n恰似野桥看。\n飘零只等闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2416, '虞美人', '陈造', '凝香仙伯莺花主。\n雅意怜羁旅。\n略分春色便浓欢。\n街吏何妨日日、报平安。\n诗人一醉龙公妒。\n恰限今朝雨。\n关门独酌强伸眉。\n也胜栖栖腰铺、守风时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2417, '鹧鸪天', '陈造', '闲去街头赏大花。\n翠帷珠护豪华。\n西真宴罢群仙醉，千尺黄云错紫霞。\n团粉黛，闹箫笳。\n使星躔处住灵槎。\n定知今夜游仙梦，不落西京姚魏家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2418, '鹧鸪天', '陈造', '遍赏扬州百种花。\n因循忘却鬓苍华。\n客闲惯刻分题烛，坐久还生醉眼霞。\n催掺鼓，趁鸣笳。\n未应回首问归槎。\n清明寒食风烟地，判到今春不著家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2419, '鹧鸪天', '陈造', '醉阅东风百种花。\n醒来长悔误随车。\n须知绿幕黄帘底，别有春藏姚魏家。\n空想像，胜惊嗟。\n梦云从此漫天涯。\n二年得趁花前约，潘鬓缘愁恐更华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2420, '江神子・江城子', '陈造', '歌筵当日小蓬瀛。\n晚妆明。\n识芳卿。\n挽袖新词，曾博遏云声。\n又侍仙翁灯夕饮，红雾底，沸箫笙。\n催人刻烛待诗成。\n捧雕觥。\n媚盈盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2421, '鹧鸪天', '黄定', '间世文章万选钱。\n清时平步八花砖。\n大开紫府瑶池宴，正是橙黄橘绿天。\n金烛里，玉堂前。\n翰林元是武夷仙。\n雍容草罢明堂诏，留取天香馥寿筵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2422, '念奴娇', '王自中', '扁舟夜泛，向子陵台下，偃帆收橹。\n水阔风摇舟不定。\n依约月华新吐。\n细酌清泉，痛浇尘臆，唤起先生语。\n当年纶钓，为谁高卧烟渚。\n还念古往今来，功名可共，能几人光武。\n一旦星文惊四海，从此故人何许。\n到底轩裳，不如蓑笠，久矣心相与。\n天低云淡，浩然吾欲高举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2423, '水调歌头', '李处全', '金节照南国，画戟壮陪都。\n严谯古角霜晓，雄胜压全吴。\n葱倩采香古径，缥缈折梅新奏，春事早关渠。\n谁识使君意，行乐与民俱。\n披绣幌，薰宝篆，引琼酥。\n黄堂富暇，宾幕谈笑足欢娱。\n看取十行丹诏，遥指五云深处，归路接亨衢。\n玉佩映鸳缀，不老奉轩虞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2424, '水调歌头', '李处全', '上马趣携酒，送客古朱方。\n秋风斜日山际，低草见牛羊。\n酩酊不知更漏，但见横江白露，清映月如霜。\n平睨广寒殿，谁说路歧长。\n醉还醒，时起舞，念吾乡。\n江山尔尔，回首千载几兴亡。\n一笑书生事业，谁信管城居士，不换碧油幢。\n好在中冷水，击楫奏伊凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2425, '鹧鸪天', '韩', '静乐堂中禅悦身。\n相家庆袭两家春。\n瑶池云气冲霄鹤，兰砌风标瑞世麟。\n华屋邃，宝杯新。\n年年秋与月常明。\n笙箫且奏长生曲，宣劝还看送喜频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2426, '忆秦娥', '韩', '香滴滴。\n肌肤冰雪娇无力。\n娇无力。\n秋风凉冷，有谁消得。\n洗妆不奈云鬟侧。\n璧堂珠院空相忆。\n空相忆。\n轻颦浅笑，小梅标格。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2427, '朝中措', '韩', '熏风两节照稽山。\n三百里湖间。\n镜上谁为贺老，棹船能伴官闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2428, '醉落魄・一斛珠', '韩', '风高木落。\n壮心万里空回薄。\n振衣待把尘埃濯。\n声里斜阳，孤起戍楼角。\n人生谁会谁为错。\n年来但觉多离索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2429, '朝中措', '韩', '山林锺鼎似无同。\n舒卷有穷通。\n洗出壶中三峡，帝城赢得从容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2430, '西江月', '韩', '日日山迷水癖，年年书恼诗痴。\n寻思那里要他知。\n试比古人犹未。\n往往眼甜口苦，常常心是身非。\n如何则甚破他疑。\n只学今人足矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2431, '阮郎归', '韩', '小楼秋霁碧阑干。\n中人初薄寒。\n霜风吹我到湖山。\n平林斜照残。\n空阔里，有无间。\n牵萝翠袖闲。\n篮舆兴尽却愁还。\n断肠歌未阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2432, '好事近', '韩', '湖上有孤山，合把探梅词刻。\n清浅黄昏时候，冷疏枝寒色。\n窗前忽到又如何，一夜足相忆。\n信道收香藏白，报春风消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2433, '浣溪沙', '韩', '买得船儿去下湖。\n这些天气近来无。\n清和风里绿阴初。\n酒不为渠闲放荡，诗应嫌我太粗疏。\n酒徒诗社复何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2434, '浣溪沙', '韩', '江上新凉入酒杯。\n瑞芝堂祝寿筵开。\n五楼百雉更崔嵬。\n劳来流离施菽麦，作成丰稔到田莱。\n便朝天去也徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2435, '醉桃源・阮郎归', '韩', '残春风雨绕檐声。\n山空分外鸣。\n闲来落佩倒冠缨。\n尚馀亲旧情。\n人不见，句还成。\n又听求友莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2436, '浣溪沙', '韩', '留得菖蒲酒一杯。\n与公今日寿筵开。\n灵山排闼送青来。\n须信南州高士後，持荷持节照苏台。\n瑞云深处是三台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2437, '醉桃源・阮郎归', '韩', '固穷斋里语吾生。\n言之必可行。\n扶疏夏木既啼莺。\n更逢鱼计成。\n多雅尚，少时情。\n沧浪渔父缨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2438, '减字木兰花', '韩', '从心所欲。\n高蹈祠官惟见独。\n其寿伊何。\n古井章泉水不波。\n腊前梅好。\n玉洁日光香耐老。\n才大三千。\n首首清诗得自编。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2439, '菩萨蛮', '韩', '归来又喜山中约。\n菊枝桂树真宜酌。\n兴尽只观山。\n秋深方闭关。\n会须追雅步。\n策蹇或肩舆。\n少待必能治。\n膏肓泉石医。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2440, '百字令・念奴娇', '韩', '园居好处，是古梅飞动、欺霜凌雪。\n底问纷华桃李态，自倚天姿明洁。\n城外灵山，桥头玉水，多少佳风月。\n岁寒时候，南枝尤与清绝。\n几回唤酒寻诗，诗成小醉，絮帽浑侧。\n领略不辞身跌宕，一洗群儿啁哳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2441, '一翦梅', '韩', '醉倒城中不过溪。\n溪外无尘，惟掩柴扉。\n水浮桥漾翠烟霏。\n一片闲情，能几人知。\n留饮君家絮帽。\n爆竹声中，万事如斯。\n梅催春动已熹微。\n尔既能来，我亦何疑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2442, '贺新郎', '韩', '又见年年雪。\n水浮桥、南岸幽处，周遭森列。\n横碧轩中空旧话，独钓寒江愁绝。\n更一段、冰霜高洁。\n忽得两篇强健曲，倚回风、洒急凭谁说。\n嗟巩雒，乃闽浙。\n何当醉酒扬雄宅。\n问避人避地，其如楚之舆接。\n览德已而歌凤去，千仞辉翔难蹑。\n我和句、却愁狂辄。\n折尽梅花伤岁暮，□撒盐、起絮分才劣。\n鸡犬静，涧篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2443, '点绛唇', '韩', '竹隐高深，夏凉日有清风度。\n苎衣绳屦。\n鹤发空相顾。\n翠扑流烟，又向溪翁去。\n青山路。\n要当同住。\n长占无尘处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2444, '菩萨蛮', '韩', '秋林只共秋风老。\n秋山却笑秋吟少。\n恰恨有秋香。\n青岩秋夜凉。\n清秋须是酒。\n结客秋知否。\n醉笔写成秋。\n一秋无复愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2445, '祝英台近', '韩', '海棠开，春已半，桃李又如许。\n一朵梨花，院落阑干雨。\n不禁中酒情怀，爱闲懊恼，都忘却、旧题诗处。\n燕莺语。\n溪岸点点飞绵，杨柳无重数。\n带得愁来，莫恁空休去。\n断肠芳草天涯，行云荏苒，和好梦、有谁分付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2446, '谒金门', '韩', '人已醉。\n溪北溪南春意。\n击鼓吹箫花落未。\n杏梅桃共李。\n水底鱼龙惊起。\n推枕月明千里。\n伊吕衰翁徒尔耳。\n我怀犹未是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2447, '虞美人', '韩', '晓来一阵催花雨。\n正桃李、横塘处。\n笙歌帘幕燕莺喧。\n春在人间不老、谷城仙。\n潇湘图画迎千骑。\n襦裤欢声起。\n功名风虎庆云龙。\n更看万钉横带、系金狨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2448, '朝中措', '韩', '水南何事兴偏浓。\n花草小园中。\n山气静分馀霭，泉声幽转流淙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2449, '卜算子', '韩', '烟雨海棠花，春夜沈沈酌。\n寒食清明数日间，人也须行乐。\n不怕笛声长，只怕风儿恶。\n烛影红酣宝篆香，楼上黄昏角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2450, '谒金门', '韩', '闲度日。\n愁里费人辞辟。\n榆火新烟还熟食。\n小墙花槛直。\n锦字玉徽清集。\n何用主人留客。\n相赏暂时谁画得。\n庞公非浪出。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2451, '浣溪沙', '韩', '锦瑟瑶琴续断弦。\n璧堂初过牡丹天。\n玉钩斜压小珠帘。\n睡鸭炉温吟散後，双鸳屏掩酒醒前。\n一番春事怨啼鹃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2452, '菩萨蛮', '韩', '丝丝柳色清愁织。\n山城望断花溪碧。\n回首仲宣楼。\n登临无计愁。\n雨声吹海立。\n流转韶光急。\n九万有鹏程。\n沈香天上亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2453, '好事近', '韩', '梅雨快晴风，苔竹定翻新箨。\n相望得寻幽调，把陈言都略。\n大江东去更飞云，心事共回薄。\n彷佛散庵佳处，一声声猿鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2454, '好事近', '韩', '黄发享颐期，兄弟此时宜告。\n见说对床夜雨，世间尘都扫。\n青毡堂外瑞峰高，云气拂晴昊。\n老大中原人物，在江湖乡保。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2455, '好事近', '韩', '三叠古藤阴，自笑无能为役。\n千载和陶新曲，了非仙非释。\n影徒随我月徘徊，风叶露华湿。\n瓮下是成真逸，醉令人思毕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2456, '朝中措', '韩', '霓裳霞佩淡丰容。\n云冷露华浓。\n唤起石丁归去，冥冥仙仗崆峒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2457, '水调歌头', '韩', '新月已如许，我问带湖梅。\n人闲题句，赢得浮潋酒盈杯。\n落拓豪英满坐，烂漫风骚连纸，天外凤凰来。\n只怕轻孤负，莫待巧安排。\n空翠滴，寒爽矣，晚佳哉。\n为君绝倒，折尽千树玉蓓堆。\n渺渺章泉好在，寂寂卢泉仙去，今古付尊。\n拍手见花木，放眼记莓苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2458, '鹧鸪天', '韩', '看了香梅看瑞香。\n月桥花槛更云窗。\n不知是有春多少，玉水灵山醉几场。\n闲蝶梦，褪蜂黄。\n尽温柔处尽端相。\n珠帘十里扬州路，赢得潘郎两鬓霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2459, '菩萨蛮', '韩', '今年是处梅花早。\n分明开到章泉好。\n兄弟寿杯同。\n暗香明月风。\n风流文物旧。\n春意枝枝透。\n儿侄定飞轩。\n衣冠与世传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2460, '菩萨蛮', '韩', '聚星亭下书堂水。\n冬来欲问梅花使。\n圭撮是何官。\n人间有底难。\n章泉词和去。\n交道元如故。\n转眼岁将穷。\n溪头鹤发翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2461, '朝中措', '韩', '年年羞插菊花游。\n华发不禁秋。\n此日遨头寻胜，消除万斛清愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2462, '点绛唇', '韩', '银笔金花，断肠有句闲挥扫。\n又还落了。\n梅片阳春小。\n古往今来，风味须才调。\n山林少。\n这些襟抱。\n输与江东老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2463, '菩萨蛮', '韩', '的南枝横县宇。\n空山无此新花吐。\n手种几多梅。\n迎霜今已开。\n簪屏聊隐几。\n诗与君应喜。\n更报晏斋翁。\n相将索笑同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2464, '鹧鸪天', '韩', '莫笑闲身老态多。\n避人避世欲如何。\n分明画出山阴道。\n太息吟成宁戚歌。\n穿木石，泛烟波。\n从前魑魅喜人过。\n灵山西畔高溪上，一棹归来舞短蓑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2465, '浣溪沙', '韩', '系得船儿柳岸头。\n夹江灯火雨飕飕。\n寻诗家醉更绸缪。\n待腊未教寒事少，小春搀取暗香浮。\n夜长飞梦失清愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2466, '浣溪沙', '韩', '爱日回春一线长。\n氛氲谁忆御炉香。\n孤城岁晚卧沧江。\n花底千官迎淑气，湖阴十里写晴光。\n剩拼华发醉为乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2467, '浣溪沙', '韩', '春入疏弦调外声。\n雪云初霁带湖清。\n屏温香软绮窗深。\n山倚虚窗情淡淡，水流清浅韵泠泠。\n断魂醒处梦难凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2468, '谒金门', '韩', '云外月。ピ\n画出一痕清绝。ピ\n梅已飘零桃未发。ピ\n带湖烟水阔。ピ\n汀渚尚留微雪。ピ\n不恨酒融歌歇。ピ\n老我多情胶漫结。ピ\n半醒空自说。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2469, '临江仙', '韩', '满眼春生梅柳意，山居清听风泉。\n又因初度说今年。\n华颠相望处，新曲忽来前。\n自笑一周闲甲子，何为佞佛贪仙。\n如翁辈行敢随肩。\n徒知言语妙，欢喜向谁传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2470, '谒金门', '韩', '不怕醉。\n记取吟边滋味。\n幽草绿阴花絮里。\n莺啼双燕起。\n老去是何乡里。\n漠漠吴头楚尾。\n一曲荒山清照水。\n渠杯酒旨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2471, '霜天晓角', '韩', '雨收云薄。\n有底情怀恶。\n一段春风花事，吟得就、又忘却。\n海棠红未落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2472, '临江仙', '韩', '寒食清明春事好，公家霁月光风。\n年时犹记雨声中。\n州侯陈乐舞，法从酒杯同。\n坐上王杨虽自散，酴依旧香浓。\n待将诗易寿无穷。\n鸢飞鱼跃矣，风虎更云龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2473, '鹧鸪天', '韩', '莫道庞公不入州。\n为谁歌酒也迟留。\n襟期别乘真难事，领略同游岂易谋。\n他扰扰，自悠悠。\n香浮茉莉笑花头。\n一帘云影催诗雨，唤起佳人无限愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2474, '鹊桥仙', '韩', '诗非漫与，酒非无算，都是悲秋兴在。\n与君觞咏欲如何，画不就、新凉境界。\n微云抹月，斜河回斗，隐隐奇奇怪怪。\n刚风九万舞瑶林，甚些少、人间利害。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2475, '浣溪沙', '韩', '闲里相看两鬓秋。\n酒能沾醉雨能幽。\n吾庐何幸得翁留。\n世路尽教终易与，山林佳话恐难酬。\n人来人去亦知不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2476, '浣溪沙', '韩', '分付心情作上元。\n不知投老在林泉。\n谁将村酒劝觥船。\n月影静摇风柳外，霜华寒浸雪梅边。\n醉乌帽忽醒然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2477, '浣溪沙', '韩', '老觉空生易得年。\n闲居那复问旌旃。\n一丘春静自回旋。\n翁善於人知美矣，我行於世转乖然。\n清词俾寿喜言传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2478, '鹊桥仙', '韩', '红梅已谢，杏花开也，一片海棠犹未。\n春风吹我带湖烟，甚恰限、新晴天气。\n黄昏楼上，烛花影里，拼得那回滋味。\n暗尘弦索拂纤纤，梦留取、巫山十二。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2479, '生查子', '韩', '晴色入青山，更见飞花晚。\n不是不登临，自是心情懒。\n试襞小红笺，与写天涯怨。\n杜宇一声春，楼下沧波远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2480, '一翦梅', '韩', '缥渺神仙云雾窗。\n说与苏州，未断人肠。\n带湖烟月堕苍茫。\n唤醒嫦娥，春笋纤长。\n马上琵琶半额妆。\n拨尽相思，十二巫阳。\n疏□清梦入潇湘。\n佩玉鸣鸾，吹下天香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2481, '眼儿媚', '韩', '西溪回合小青苍。\n梅雨弄残阳。\n意行陇亩，景分庭院，乳燕春长。\n酒深不用人歌啸，锄圃试商量。\n细菜甲，旋寻蔬笋，一梦黄粱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2482, '水调歌头', '韩', '一曲笙歌外，四座笑谈清。\n使君秋霁领客，别乘更宗英。\n想像亲闱称寿，写就通家情分，相与庆恩荣。\n劝动桂花发，香雾扑帘旌。\n功名事，台阁路，好同登。\n只今报政归诏，舆论正蜚声。\n以我文章学术，与国和平安靖，冠剑入明庭。\n应顾棠阴下，野老鬓星星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2483, '鹧鸪天', '韩', '云到春飞若素期。\n柳条吹送落梅枝。\n冰壶表里谁能赋，玉鉴圆明且屈卮。\n村舍北，郡楼西。\n治中风调只心知。\n不堪野老关门醉，想见山翁倒载时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2484, '桃源忆故人', '韩', '杏花雨里东风峭。\n不比寻常开了。\n枝上飞来多少。\n人与春将老。\n山城灯火笙箫杳。\n梦到十洲三岛。\n睡觉绮窗清晓。\n绿遍池塘草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2485, '浣溪沙', '韩', '荆楚谁言镜听词。\n烛花影动画檐低。\n烧灯天气醉为期。\n雨湿杏腮疑淡淡，风迷柳眼半。\n小山西路板桥西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2486, '菩萨蛮', '韩', '春来晴雨常相半。\n水光风力花撩乱。\n山北与山南。\n行歌或再三。\n诵君诗过日。\n才大真盘屈。\n寿我敢言酬。\n相望亦饮不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2487, '浣溪沙', '韩', '百花丛里试新妆。\n不许巫山枉断肠。\n牡丹风扬曲声长。\n寒食清明闲节序，绮窗朱户少年场。\n燕泥香润落空梁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2488, '虞美人', '韩', '西湖十里孤山路。\n犹记荷花处。\n翠茎红蕊最关情。\n不是薰风、吹得晚来晴。\n而今老去丹青底。\n醉腻娇相倚。\n棹歌声缓采香归。\n如梦如酲、新月照涟漪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2489, '虞美人', '韩', '送君报最登朝路。\n初整曹装处。\n又因杯酒见馀情。\n凉雨灵山阁上、月初晴。\n醺然领客襟怀底。\n消得阑干倚。\n风流别乘我依归。\n清誉冰溪棠荫、绿漪漪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2490, '朝中措', '韩', '一番风月已平分。\n留得玉溪云。\n蔼蔼宾僚如故，东楼北海清尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2491, '浣溪沙', '韩', '宋玉悲秋合反骚。\n陶潜把菊任持醪。\n山遥遥外水萧萧。\n梦不到时诗自在，兴难忘处恨全消。\n香沈沈里蕊飘飘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2492, '朝中措', '韩', '君之竹隐是章泉。\n只要世家传。\n莫道闲诗浪句，风花雪月云烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2493, '浣溪沙', '韩', '一抹青山拍岸溪。\n麦云将过笋初齐。\n不知何处水流西。\n小阁路头吾欲醉，短蓬船尾客同携。\n酒边华发更题诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2494, '浣溪沙', '韩', '水绕孤村客路赊。\n一楼风雨角巾斜。\n举觞无复问煎茶。\n夜静曲声初喷竹，酒深烛影细吹花。\n明朝飞鹭起圆沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2495, '浣溪沙', '韩', '忆把兰桡系柳堤。\n斜风细雨一蓑衣。\n夕阳回照断霞飞。\n洛浦佩寒如隔日，高唐梦到又何时。\n背人挑□独心知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2496, '水调歌头', '韩', '玉水灵山地，燕寝亦书功。\n邦人耆老，诞弥佳节以词通。\n尔岂知吾恺悌，我乃因君谈笑，祝寿酒杯同。\n箫鼓少人会，歌舞为谁容。\n观坐客，惊野老，笔如风。\n个般酬唱，诏回应上玉华东。\n多少家传经济，留与孙谋持守，出处信何穷。\n唤起千年调，分付一车公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2497, '菩萨蛮', '韩', '人间多少闲风度。\n薄情失记相逢处。\n绿鬓画鸦儿。\n旧巢双燕栖。\n舞衫回素玉。\n檀板声何蹙。\n一抹晚霞飞。\n泪痕无脸啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2498, '浣溪沙', '韩', '彩笔新题字字香。\n雁来时候燕空梁。\n芙蓉无处著秋光。\n人远山长言外意，曲传书恨醉时妆。\n倩谁闲寄水云乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2499, '菩萨蛮', '韩', '晚云烘日枝南北。\n一杯未尽梅花曲。\n城郭小春回。\n暗香开未开。\n留连吾欲醉。\n醉眼红尘外。\n多少老心情。\n景清人亦清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2500, '少年游', '韩', '闲寻杯酒，清翻曲语，相与送残冬。\n天地推移，古今兴替，斯道岂雷同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2501, '蝶恋花', '韩', '未就丹砂须九转。\n谁把新词，歌绕梁尘遍。\n拍拍韶华春意满。\n揆予初度文何健。\n恰是山花汀草远。\n独乐园林，不梦笙歌殿。\n灵气仙才非小见。\n霞杯漫道蟠桃献。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2502, '蝶恋花', '韩', '千叶香梅春在手。\n日薄帘栊，花影遮前後。\n小立徐行还易久。\n微吟莫厌伤多久。\n拾翠流红弦管透。\n望断青青，休问行人柳。\n往事如云如梦否。\n连天芳草惊依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2503, '点绛唇', '韩', '南陌柔桑，粉墙低见谁家女。\n燕飞莺语。\n依约提篮去。\n老觉多情，梦也无分付。\n君知否。\n楚襄何处。\n一段阳台雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2504, '浣溪沙', '韩', '滴滴琼英发翠绡。\n江梅标韵木香娇。\n乍凉时候漏声遥。\n欲绾鬓丝妆未了，半回身分曲初招。\n霓裳依约梦魂飘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2505, '浣溪沙', '韩', '雨阁云流小院秋。\n半醺凉意不关愁。\n一番相见一番休。\n淡伫乍持杯未浅，懒歌浑罢笑初收。\n主宾无处著绸缪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2506, '摊破浣溪沙・山花子', '韩', '生与真妃姓氏同。\n家随西子苎萝东。\n谁道玉肌寒起粟，酒能红。\n火齐烧空来上苑，冰浆凝露在西宫。\n不似荔枝生处远，恨薰风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2507, '瑞鹧鸪', '李廷忠', '洛浦风光烂漫时。\n千金开宴醉为期。\n花方著雨犹含笑，蝶不禁寒总是痴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2508, '生查子', '李廷忠', '玉女翠帷熏，香粉开妆面。\n不是占春迟，羞被群花见。\n纤手折柔条，绛雪飞千片。\n流入紫金卮，未许停歌扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2509, '水龙吟', '李廷忠', '风流最数宣城，奇山秀水神仙府。\n琴高台畔，花姑坛上，鸾翔凤舞。\n春度玉墀，月升金掌，荣分铜虎。\n想少陵，知有异人间出，三百载、留佳句。\n岁岁椒盘柏，到明朝、又还重举。\n阳和散作，千岩瑞雪，两溪甘雨。\n汲取恩波，酿成禄酒，庆公初度。\n有东风传报，都人已为，筑沙堤路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2510, '沁园春', '李廷忠', '幕府增辉，前度刘郎，又还到来。\n看芙蓉池畔，神凝秋水，绮罗丛里，欢动春雷。\n彩笔新题，金钗半醉，当日英雄安在哉。\n开筵处，是真仙福地，不著纤埃。\n堪怜倦客情怀。\n听吹竹弹丝金奏谐。\n有黄花插鬓，何妨帽，绿橙醒酒，莫惜空。\n坐上疏狂，帘间姝丽，应想横波一笑回。\n停杯久，待娇歌缓劝，归骑休催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2511, '一落索', '方千里', '心抵江莲长苦。\n凌波人去。\n厌厌消瘦不胜衣，恨清泪、多於雨。\n旧曲慵歌琼树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2512, '垂丝钓', '方千里', '锦鳞绣羽。\n难传愁态颦妩。\n岸草际天，云影垂絮。\n人何许。\n谩并栏倚柱。\n烟光暮。\n怅榆钱满路。\n送春酒。\n欢期幽会希遇。\n彩箫凤侣。\n回首分携处。\n双脸吹愁雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2513, '满庭芳', '方千里', '山色澄秋，水光融日，浮萍飘碎还圆。\n数行征雁，分破白鸥烟，高下回塘暗谷，写幽思、终日溅溅。\n闲凝望，残霞暝霭，何处一渔船。\n江南，思旧隐，筠轩野径，茅舍疏椽。\n惯携壶花下，帽风前。\n想像渊明旧节，琴中趣、何必疏弦。\n归欤计，不将五斗，输与北窗眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2514, '隔浦莲・隔浦莲近拍', '方千里', '垂杨烟湿嫩葆。\n别屿环清窈。\n绀影浮新涨，夷犹终日鱼鸟，花妥庭下草。\n鸣蝉闹。\n暗绿藏台沼。\n野轩小。\n眠断梦，闲书风叶颠倒。\n诗怀酒思，悔费十年昏晓。\n投老红尘倦再到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2515, '法曲献仙音', '方千里', '庭叶飘寒，砌蛩催织，夜色迢迢难度。\n细剔灯花，再添香兽，凄凉洞房朱户。\n见凤枕羞孤另，相思洒红雨。\n有谁语。\n道年来，为郎憔悴，音问隔，回首後期尚阻。\n寂寞两愁山，锁闲情、无限颦妩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2516, '过秦楼', '方千里', '柳拂鹅黄，草揉螺黛，院落雨痕才断。\n蜂须雾湿，燕嘴泥融，陌上细风频扇。\n多少艳景关心，长苦春光，疾如飞箭。\n对东风忍负，西园清赏，翠深香远。\n空暗忆、醉走铜驼，闲敲金镫，倦迹素衣尘染。\n因花瘦觉，为酒情锺，绿鬓几番催变。\n何况逢迎向人，眉黛供愁，娇波回倩。\n料相思此际，浓似飞红万点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2517, '侧犯', '方千里', '四山翠合，一溪碧绕秋容靓。\n波定。\n见鹭立鱼跳动平镜。\n修林散步，古木通幽径。\n风静。\n烟雾直、池塘倒晴影。\n流年旧事，老矣尘心莹。\n还暗省。\n点吴霜、憔悴愧潘令。\n梦忆江南，小园路迥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2518, '塞翁吟', '方千里', '暮色催更鼓，庭户月影胧。\n记旧迹、玉楼东。\n看枕上芙蓉。\n云屏几轴江南画，香篆炉暖烟空。\n睡起处，绣衾重。\n尚残酒潮红。\n忡忡。\n从分散，歌稀宴小，怀丽质，浑如梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2519, '苏幕遮', '方千里', '扇留风，冰却暑。\n夏木阴阴，相对黄鹂语。\n薄晚轻阴还阁雨。\n远岸烟深，仿佛菱歌举。\n燕归来，花落去。\n几度逢迎，几度伤羁旅。\n油壁西陵人识否。\n好约追凉，小舣蒹葭浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2520, '浣溪沙', '方千里', '菱藕花开来路香。\n满船丝竹载西凉。\n波摇发彩粉生光。\n翡翠双飞寻密浦，鸳鸯浓睡倚回塘。\n闲情须与酒商量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2521, '浣溪沙', '方千里', '密约深期卒未成。\n藏钩春酒坐频倾。\n向人娇艳夜亭亭。\n相顾无言情易觉，归来单枕梦犹惊。\n眼梢怨泪几时晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2522, '浣溪沙', '方千里', '面面虚堂水照空。\n天然一朵玉芙蓉。\n千娇百媚语惺。\n未散娇云轻鬓，欲融轻雪乍凝胸。\n石榴裙衩为谁红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2523, '浣溪沙', '方千里', '刻样衣裳巧刻绘。\n彩枝环绕万年藤。\n生香吹透蚕冰。\n嫩水带山娇不断，湿云堆岭腻无声。\n香肩婀娜许谁凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2524, '点绛唇', '方千里', '闲荡兰舟，翠娥仙袂风中举。\n鸳鸯深浦。\n绿暗曾来路。\n留恋荷香，薄晚慵归去。\n还相顾。\n练波澄素。\n月上潮生处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2525, '诉衷情', '方千里', '远山重叠乱山盘。\n江上晚风酸。\n秋容更兼残日，枫叶照人丹。\n书未到，梦犹闲。\n鬓先斑。\n凭高无语，征雁知愁，声断云间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2526, '风流子', '方千里', '河梁携手别，临歧语，共约踏青归。\n自双燕再来，断无音信，海棠开了，还又参差。\n料此际，笑随花便面，醉骋锦障泥。\n不忆故园，粉愁香怨，忍教华屋，绿惨红悲。\n旧家歌舞地，生疏久，尘暗凤缕罗衣。\n何限可怜心事，难诉欢期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2527, '华胥引', '方千里', '长亭无数，羁客将归，故园换叶。\n乳鸭随波，轻苹满渚时共唼。\n接眼春色何穷，更橹声伊轧。\n思忆前欢，未言心已愁怯。\n欺鬓吴霜。\n恨星星、又还盈镊。\n锦纹鱼素，那堪重翻再阅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2528, '宴清都', '方千里', '暮色闻津鼓。\n烟波碧、数行征雁时度。\n轻榔聚网，长歌和楫，水村渔户。\n行人又落天涯，但怅望、高阳伴侣。\n记旧日、酒卸宫袍，马酬少妾词赋。\n如今鬓影萧然，相逢似雪，徒话愁苦。\n芳尘暗陌。\n残花遍野，岁华空去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2529, '四园竹', '方千里', '花骢纵策，制泪掩斜扉。\n玉炉细袅，鸳被半闲，萧瑟罗帏。\n银漏声，那更杂、疏疏雨里，此时怀抱谁知。\n恨凄其。\n西窗自剪寒花，沈吟暗数归期。\n最爱深情密意，无限当年，往复诗辞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2530, '齐天乐', '方千里', '碧纱窗外黄鹂语，声声似愁春晚。\n岸柳飘绵，庭花堕雪，惟有平芜如剪。\n重门尚掩。\n看风动疏帘，浪铺湘簟。\n暗想前欢，旧游心事寄诗卷。\n鳞鸿音信未睹，梦魂寻访後，关山又隔无限。\n客馆愁思，天涯倦迹，几许良宵展转。\n闲情意远。\n记密阁深闺，绣衾罗荐。\n睡起无人，料应眉黛敛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2531, '木兰花・玉楼春', '方千里', '溶溶水映娟娟秀。\n浅约宫妆笼翠袖。\n舞馀杨柳乍萦风，睡起海棠犹带酒。\n憔悴萧郎缘底瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2532, '霜叶飞', '方千里', '塞云垂地，堤烟重，燕鸿初度江表。\n露荷风柳向人疏，台榭还清悄。\n恨脉脉、离情怨晓。\n相思魂梦银屏小。\n奈倦客征衣，自遍拂尘埃，玉镜羞照。\n无限静陌幽坊，追欢寻赏，未落人後先到。\n少年心事转头空，况老来怀抱。\n尽绿叶红英过了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2533, '蕙兰芳・蕙兰芳引', '方千里', '庭院雨晴，倚斜照、睡馀双鹜。\n正学染修蛾，官柳细匀黛绿。\n绣帘半卷，透笑语、琐窗华屋。\n带脆声咽韵，远近时闻丝竹。\n乍著单衣，才拈圆扇，气候暄燠。\n趁骄马香车，同按绣坊画曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2534, '塞垣春', '方千里', '四远天垂野。\n向晚景，雕鞍卸。\n吴蓝滴草，塞锦藏柳，风物堪画。\n对雨收雾霁初晴也。\n正陌上、烟光洒。\n听黄鹂、啼红树，短长音□如写。\n怀抱几多愁，年时趁、欢会幽雅。\n尽日足相思，奈春昼难夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2535, '丁香结', '方千里', '烟湿高花，雨藏低叶，为谁翠消红陨。\n叹水流波迅。\n抚艳景、尚有轻阴馀润。\n乳莺啼处路，思归意、泪眼暗忍。\n青青榆荚满地，纵买闲愁难尽。\n勾引。\n正记著年时，乍怯春寒阵阵。\n小阁幽窗，残妆剩粉，黛眉曾晕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2536, '氐州第一', '方千里', '朝日融怡，天气艳冶，桃英杏萼犹小。\n燕垒初营，蜂衙乍散，池面烟光缥缈。\n芳草如薰，更潋滟、波光相照。\n锦绣萦回，丹青映发，未容春老。\n倦客自嗟清兴少。\n念归记、梦魂飞绕。\n浪阔鱼沈，云高雁阻，瞪目添愁抱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2537, '解蹀躞', '方千里', '院宇无人晴昼，静看帘波舞。\n自怜春晚，漂流尚羁旅。\n那况泪湿征衣，恨添客鬓，终日子规声苦。\n动离绪。\n谩徘徊愁步。\n何时再相遇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2538, '少年游', '方千里', '人如李，香翠缕，芳酒嫩於橙。\n宝烛烘香，珠帘闲夜，银字理鸾笙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2539, '庆春宫・高阳台', '方千里', '宿霭笼晴。\n层云遮日，送春望断愁城。\n篱落堆花，帘栊飞絮，更堪远近莺声。\n岁华流转，似行蚁、盘旋万星。\n人生如寄，利锁名缰，何用萦萦。\n皓发相迎。\n斜照难留，朝雾多零。\n宜趁良辰，何妨高会，为酬月皎风清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2540, '醉桃源・阮郎归', '方千里', '良宵相对一灯青。\n相思写砑绫。\n去时情泪滴红冰。\n西风吹涕零。\n愁宛转，意飞腾。\n晴窗穿纸蝇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2541, '醉桃源・阮郎归', '方千里', '鸳鸯浓睡碧溪沙。\n荷花深处家。\n快风收电掣金蛇。\n凉波流素华。\n吴国艳，楚宫娃。\n红潮连翠霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2542, '点绛唇', '方千里', '绿叶阴阴，满城风雨催梅润。\n画楼人近。\n朝雾来芳信。\n从解雕鞍，休数花吹阵。\n无多闷。\n燕催莺趁。\n付与春归恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2543, '夜游宫', '方千里', '一带垂杨蘸水。\n映芳草、萋萋千里。\n跋马回堤少年子。\n拥青娥，向红楼，南酒市。\n拼饮莺花底。\n恣欢笑、粉融香坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2544, '夜游宫', '方千里', '城上昏烟四敛。\n画楼外、陡听更点。\n千里相思梦中见。\n恨年华，逐东流，随急箭。\n帘影参差转。\n夜初过、水沈烟乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2545, '诉衷情', '方千里', '一钩新月淡於霜。\n杨柳渐分行。\n征尘厌堆襟袂，鸡唱促晨装。\n淮水阔，楚山长。\n暗悲伤。\n重阳天气，杯酒黄花，还寄他乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2546, '伤情怨・清商怨', '方千里', '闲愁眉上翠小。\n尽春衫宽了。\n舞槛孤鸾，严妆羞独照。\n王孙音信尚渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2547, '红林擒近', '方千里', '花幕高烧烛，兽炉深炷香。\n寒色上楼阁，春威遍池塘。\n多情天孙罢织，故与玉女穿窗。\n素脸浅约宫装。\n风韵胜笙簧。\n游冶寻旧侣，尊酒老吾乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2548, '红林擒近', '方千里', '晓起山光惨，晚来花意寒。\n映月衣纤缟，因风佩琅。\n三弄江梅听彻，几点岸柳飘残。\n宛然舞曲初翻。\n帘影卷波澜。\n把酒同唤醒，促膝小留欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2549, '满路花・促拍满路花', '方千里', '帘筛月影金，风卷杨花雪。\n天边鸿雁少，音尘绝。\n春光欲暮，客心归心折。\n江湖波浪阔。\n目断家山，料应易过佳节。\n柔情千点，杜宇枝头血。\n危肠馀寸许，谁能接。\n眠思梦忆，不似今番切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2550, '解语花', '方千里', '长空淡碧，素魄凝辉，星斗寒相射。\n凤楼鸳瓦。\n天风动，冉冉佩环高下。\n歌清韵雅。\n对好景、芳樽满把。\n花雾浓，灯火荧煌，笑语烘兰麝。\n千斛明珠照夜。\n况人如图画，明艳容冶。\n绣巾香帕。\n归来路，缓逐杏鞯骄马。\n笙歌散也。\n愁万炬、绛莲分谢。\n更楼残，惊听西楼，吹小梅初罢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2551, '六么令', '方千里', '照人明艳，肌雪消繁燠。\n娇云慢垂柔领，绀发浓於沐。\n微晕红潮一线，拂拂桃腮熟。\n群芳难逐。\n天香国艳，试比春兰共秋菊。\n当时相见恨晚，彼此萦心目。\n别後空忆仙姿，路隔吹箫玉。\n何处栏干十二，缥缈阳台曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2552, '倒犯', '方千里', '尽日、任梧桐自飞，翠阶慵扫。\n闲云散缟。\n秋容莹、暮天清窈。\n斜阳到地，楼阁参差帘栊悄。\n嫩袖舞凉，拂拂生林表。\n荡尘襟，写名。\n携手故国，胜事寻踪，松篁幽径。\n曲沼瞰静绿，荫檐影、龟鱼小。\n信倦迹、归来好。\n倩叮咛、长安游子道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2553, '大', '方千里', '正夕阳闲，秋光淡，鸳瓦参差华屋。\n高低帘幕迥，但风摇环佩，细声频触。\n瘦怯单衣，凉生两袖，零乱庭梧窗竹。\n相思谁能会，是归程客梦，路谙心熟。\n况时节黄昏，闲门人静，凭栏身独。\n欢情何太速。\n岁华似、飞马驰轻毂。\n谩自叹、河阳青鬓，苒苒如霜，把菱花、怅然凝目。\n老去疏狂减，思堕策、小坊幽曲。\n趁游乐、繁华国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2554, '玉烛新', '方千里', '海棠初雨後。\n似露粉妆成，肉红团就。\n太真帐里，春眠醒、缓蹙楼前宫漏。\n潮生酒晕，独自倚、阑干时候。\n吹鬓影、斜立东风，馀寒半侵罗袖。\n骊山宫殿无人，想笑问君王，艳容如否。\n万花竞斗。\n难比并、丽美巧匀丰瘦。\n闺房挺秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2555, '花犯', '方千里', '渚风低，芙蓉万朵，清妍赋情味。\n雾绡红缀。\n看曼立分行，闲淡佳丽。\n靓姿艳冶相扶倚。\n高低纷愠喜。\n正晓色、懒窥妆面，娇眠翠被。\n秋光为花且徘徊，朱颜迎缟露，还应憔悴。\n腰肢小，腮痕嫩、更堪飘坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2556, '丑奴儿・采桑子', '方千里', '凌波台畔花如剪，几点吴霜。\n烟淡云黄。\n东阁何人见晚妆。\n江南春近书千里，谁寄清香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2557, '水龙吟', '方千里', '锦城春色移根，丽姿迥压江南地。\n琼酥拂脸，彩云满袖，群芳羞避。\n双燕来时，暮寒庭院，雨藏烟闭。\n正□□未足，宫妆尚怯，还轻洒胭脂泪。\n长是欢游花底。\n怕东风、陡成怨吹。\n高烧银烛，梁州催按，歌声渐起。\n绿态多慵，红情不语，动摇人意。\n算吴宫独步，昭阳第一，可依稀比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2558, '六丑', '方千里', '看流莺度柳，似急响、金梭飞掷。\n护巢占泥，翩翩飞燕翼。\n昨梦前迹。\n暗数欢娱处，艳花幽草，纵冶游南国。\n芳心荡漾如波泽。\n系马青门，停车紫陌。\n年华转头堪惜。\n奈离襟别袂，容易疏隔。\n人间春寂。\n谩云容暮碧。\n远水沈双鲤、无信息。\n天涯渐老羁客。\n叹良宵漏断，独眠愁极。\n吴霜皎、半侵华帻。\n谁复省十载，匀香晕粉，髻倾鬟侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2559, '虞美人', '方千里', '花台响彻歌声暖。\n白日林中短。\n春心摇荡客魂消。\n搓粉揉香排比、一团娇。\n重来犹自寻芳径。\n吹鬓东风影。\n步金莲处绿苔封。\n不见彩云双袖、舞惊鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2560, '虞美人', '方千里', '高楼远阁花飞遍。\n急雨捎池面。\nけけ杨柳不知门。\n多少乱莺啼处、暮烟昏。\n银钩小字题芳絮。\n宛转回文语。\n可怜单枕梦行云。\n肠断江南千里、未归人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2561, '兰陵王', '方千里', '晚烟直。\n池沼波痕皱碧。\n年芳为、花态柳情，采粉揉蓝酿春色。\n繁华记上国。\n曾识。\n倾城幼客。\n风流是、联句送钩，笺绿绡红递书尺。\n行云去无迹。\n念暖响歌台，香雾瑶席。\n当时谁信盟言食。\n知一岁离聚，几多间阻，人生如梦寄堠驿。\n况分散南北。\n悲恻。\n万愁积。\n奈鸾凤欢疏，鱼雁音寂。\n天涯何处相思极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2562, '蝶恋花', '方千里', '漏泄东君消息後。\n短叶长条，著意遮轩牖。\n嫩比鹅黄初熟酒。\n染匀巧费春风手。\n万缕筛金新月透。\n入夜柔情，还胜朝来秀。\n彩笔雕章知几首。\n可人标韵无新旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2563, '蝶恋花', '方千里', '一搦腰肢初见後。\n恰似娉婷，十五藏朱牖。\n春色恼人浓抵酒。\n风前脉脉如招手。\n黛染修眉蛾绿透。\n态婉仪闲，自是闺房秀。\n堪惜年华同转首。\n女郎台畔春依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2564, '蝶恋花', '方千里', '碎玉飞花寒食後。\n薄影行风，终日穿疏牖。\n有客思归还把酒。\n闲吹倦絮轻黏手。\n雪满愁城寒欲透。\n飘尽残英，翠幄成秀。\n张绪风流今白首。\n少年襟度难如旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2565, '蝶恋花', '方千里', '翠浪蓝光新雨後。\n整整斜斜，高下笼窗牖。\n万斛深倾重碧酒。\n量愁知落何人手。\n栊雾梳烟晴色透。\n照影回风，一段嫣然秀。\n白下门东空引首。\n藏鸦枝叶长怀旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2566, '西河', '方千里', '都会地。\n东南王气须记。\n龙盘凤舞到钱塘，瑞烟回起。\n画图彩笔写西湖，波光溶漾无际。\n翠栏最宜半倚。\n柳阴骏马谁系。\n鳞差观阁接飞，衙庐万垒。\n倒空碧浸软琉璃，云收天净如水。\n夕阳照晚听近市。\n沸笙箫、劝动闾里。\n比屋乐逢尧世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2567, '三部乐', '方千里', '帘卷窗明，听杜宇乍啼，漏声初绝。\n乱云收尽，天际□留残月。\n奈相送、行客将归，怅去程渐促，霁色催发。\n断魂别浦，自上孤舟如叶。\n悠悠音信易隔。\n纵怨怀恨语，到见时难说。\n堪嗟水流急景，霜飞华发。\n想家山、路穷望睫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2568, '菩萨蛮', '方千里', '黄鸡晓唱玲珑曲。\n人生两鬓无重绿。\n官柳系行舟。\n相思独倚楼。\n来时花未发。\n去後纷如雪。\n春色不堪看。\n萧萧风雨寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2569, '品令', '方千里', '露烟静。\n寂寥转、梧桐寒影。\n天际历历征鸿近。\n被风吹散，声断无行阵。\n秋思客怀多少恨。\n谩厌厌谁问。\n晕残兰香消印。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2570, '玉楼春', '方千里', '华堂银烛堆红泪。\n解说离人多少意。\n恨从别後恨无穷，愁到浓时惟一味。\n江南渭北三千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2571, '满路花・促拍满路花', '方千里', '莺飞翠柳摇，鱼跃浮萍破。\n班班红杏子，交榴火。\n池台昼永，缭绕花阴裹。\n山色遥供座。\n枕簟清凉，北窗时唤高卧。\n翻思少年，走马铜驼左。\n归来敲镫月，留关锁。\n年华老矣，事逐浮云过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2572, '沁园春', '吴泳', '鸣兮，卉木萋止，维暮之春。\n笑憨翁渐老，年加三豆，呆郎多事，诗记三星。\n六十有三，高吟勇退，只有尧夫范景仁。\n从今去，且亭前放鹤，溪上垂纶。\n交亲。\n散落如云。\n仅留得尊前康健身。\n有一编书传，一囊诗稿，一枰棋谱，一卷茶经。\n红杏尚书，碧桃学士，看了虚名都赚人。\n成何事，独青山有趣，白发无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2573, '摸鱼儿', '吴泳', '甚一般、化工模子。\n铸成一个拙底。\n生来不向春头上，却跨暮春婪尾。\n蓦省记。\n早冉冉花阴，НН循除水。\n虽然恁地。\n但笑咏春风，闲推鸣瑟，别自有真意。\n从前看，三十七年都未。\n醉生声利场里。\n浮云破处窗涵月，唤得自家醒起。\n别料理。\n那玉燕石麟，不当真符瑞。\n彻头地位。\n也须是长年，闻些好语，作个标月指。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2574, '沁园春', '吴泳', '春事阑斑，桐花烂漫，不堪凤栖。\n叹交枰世道，容容是福，危航宦海，了了成痴。\n邵子豪情，乐天狂态，六十六年才觉非。\n溪山畔，要看承风月，舍我其谁。\n文章高下随时。\n料织锦应须用锦机。\n愧老无健笔，高凌月胁，病无佳句，下解人颐。\n君昔东坡，我今韩愈，造化一炉如小儿。\n都休管，看龟翻荷露，燕落芹泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2575, '满江红', '吴泳', '手摘桐花，怅还是、春风婪尾。\n按锦瑟、一弦一柱，又添一岁。\n紫马西来疑是梦，朱衣双引浑如醉。\n较香山、七十欠三年，吾衰矣。\n红袖却，青尊止。\n檀板住，琼杯废。\n淡香凝一室，自观生意。\n事业不堪霜满镜，文章底用花如绮。\n笑江滨、游女尚高歌，滕王记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2576, '满江红', '吴泳', '梦绕家山，曾访问、鹤林遗迹。\n见老鹤、翩跹飞下，方瞳如漆。\n蕙帐香消形色静，玉笙吹彻丰神逸。\n梦醒来、忽记鹤归时，翁生日。\n南陌杖，东山屐。\n红楼酒，青霄笛。\n料中梁何似，涪江今夕。\n君不见洛阳耆英会，花前雅放诗闲适。\n独北都、留守未归来，七十一。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2577, '水龙吟', '吴泳', '清江社雨初晴，秋香吹彻高堂晓。\n天然带得，酒星风骨，诗囊才调。\n沔水春深，屏山月淡，吟鞭俱到。\n算一生绕遍，瑶阶玉树，如君样、人间少。\n未放鹤归华表。\n伴仙翁、依然天杪。\n知他费几，雁边红粒，马边青草。\n待得清夷，彩衣花绶，哄堂一笑。\n且和平心事，等闲博个，千秋不老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2578, '鹊桥仙', '吴泳', '二童一马，素琴独鹤，长与仙翁为伴。\n自从分付益州来，便蔚有、隆中人望。\n边烽白羽，军符赤籍，弄得不成模样。\n愿公福德厚如山，为扶起、坤陲一半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2579, '清平乐', '吴泳', '梅霖未歇。\n直透菖华节。\n荔子才丹栀子白。\n抬贴诞弥嘉月。\n峨冠蝉尾けけ。\n整衣鹤骨。\n闻道彩云深处，新添弄玉吹箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2580, '贺新凉・贺新郎', '吴泳', '碧嶂青红路。\n近重阳、不寒不暖，不风不雨。\n杜宇花残银杏过，犹有秋英未吐。\n但日对、南山延伫。\n碧落仙人骑赤鲤，渺风烟、不上瞿塘去。\n来伴我，宛陵住。\n西风画角高堂暮。\n炙银灯、疏帘影里，笑呼儿女。\n爷作嘉兴新太守，囝拜鹗书天府。\n况哥共、白头相聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2581, '渔家傲', '吴泳', '翠隐红藏春尚薄。\n百花头上梅先觉。\n清晓寒城闻画角。\n云一握。\n鸦翻诏墨天边落。\n碧眼棱棱言谔谔。\n谏书犹自留黄阁。\n世事翻腾谁认错。\n休话著。\n绿尊且举鸬鹚杓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2582, '八声甘州', '吴泳', '又一番、沪水出。\n江声汹鸣鼍。\n正南人争望，转移虎节，弹压鲸波。\n未见元戎羽葆，民气已冲和。\n不待禁中选，李牧廉颇。\n却顾边陲以北，似乘航共济，亡楫中河。\n纵缆头襦尾，其奈不牢何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2583, '青玉案', '吴泳', '杏花时候匆匆别。\n又欲迫、黄花节。\n过了三年经八月。\n骊驹声里，青鸿头畔，几见刀头折。\n诸生立尽门前雪。\n半偈重翻为渠说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2584, '谒金门', '吴泳', '将进酒。\n吹起黄钟清调。\n手按玉笙寒尚峭。\n陇梅春已透。\n蓝染溪光绿皱。\n花簇马蹄红斗。\n尽使宛陵人说道。\n状元今岁又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2585, '谒金门', '吴泳', '金榜揭。\n都是鹿鸣仙客。\n手按玉笙寒尚怯。\n倚梅歌一阕。\n柳拂御街明月。\n莺扑上林残雪。\n前岁杏花元一色。\n马蹄归路滑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2586, '柳梢青', '吴泳', '元九不回，胡三不问，花说与谁。\n赖得东皇，调停春住，句管花飞。\n庭前密打红围。\n想孙子、兵来出奇。\n似恁丰神，谁人刚道，色比明妃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2587, '摸鱼儿', '吴泳', '倚南墙、几回凝伫。\n绿筠冉冉如故。\n帝城景色缘何事，一半花枝风雨。\n收听取。\n这气象精神，则要人来做。\n当留客处。\n且遇酒高歌，逢场戏剧，莫作皱眉事。\n那个是，紫佩飞霞仙侣。\n云步如许。\n清闲笑我如鸥鹭。\n不肯对松觅句。\n萍散聚。\n又明月、还寻锦里烟霞路。\n浮名自误。\n待好好归来，携筒载酒，同访子云去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2588, '水龙吟', '吴泳', '修篁翠葆人家，分明水槛光中住。\n就中得要，危亭瞰渌，小桥当路。\n一榻桃笙，半窗竹简，清凉如许。\n纵武陵佳丽，若耶深窈，那得似、双溪趣。\n一夜檐花落枕，想鱼天、涨痕新露。\n多君唤我，扫花作晚，解衣逃暑。\n脍切银丝，酒招玉友，曲歌金缕。\n愿张郎，长与莲花相似，朝朝暮暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2589, '鱼游春水', '吴泳', '东里韶光早。\n百舌枝头啼碎了。\n溪梅开尽，池水绿波还皱。\n种柳先生觉意阑，看花君子非年少。\n心似淡云，梦随芳草。\n满地松花不扫。\n镇日春愁萦怀抱。\n谁能击筑长歌，吹笳清啸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2590, '祝英台・祝英台近', '吴泳', '小池塘，闲院落，薄薄见山影。\n杨柳风来，吹彻醉魂醒。\n有时低按秦筝，高歌水调，落花外、纷纷人境。\n猛深省。\n但有竹屋三间，莲田二顷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2591, '千秋岁', '吴泳', '松舟桂楫。\n苕溪头别。\n秋後雨，春前雪。\n书凭湖雁寄，手把江蓠折。\n人未老，相看元似来时节。\n芳草鸣。\n野菜飞黄蝶。\n时易去，愁难说。\n析波浮玉醴，换火银叶。\n拚醉也，马蹄归踏梨花月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2592, '上西平・金人捧露盘', '吴泳', '似斜斜，才整整，又霏霏。\n今夜里、窗户先知。\n嫌春未透，故穿庭树作花飞。\n起来寻访剡溪人，半压桥低。\n兔园册，渔江画，兰房曲，竹丘诗。\n怎模得、似当时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2593, '沁园春', '吴泳', '夸说洪都，西滕王阁，北豫章台。\n对雨帘半卷，江横如旧，沟亭压，梯上无媒。\n但有江山，更无豪杰，拔脚风尘外一杯。\n题千墨，须杜陵老手，太白天才。\n力能笔走风雷。\n人道是闽乡老万回。\n把崇天普地，层胸荡出，横今竖古，信手拈来。\n使翰墨场，著伏波老，上马犹堪矍铄哉。\n今耄矣，独莼鲈在梦，泉石萦怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2594, '满江红', '吴泳', '伶俐聪明，都不似、阿奴碌碌。\n渐欲买、青山路隐，白云同宿。\n半醉尽教乌帻堕，熟眠休管屏风触。\n算人生、能有几时闲，金乌速。\n粗粗饭，天仓粟。\n浊浊酒，天家禄。\n更钓鲜采薇，有何不足。\n君不见当年金谷事，绿珠弄笛椒涂屋。\n到而今、富贵一场空，终非福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2595, '卜算子', '吴泳', '漠漠雨其，湛湛江之永。\n冻压溪桥并见花，安得杯中影。\n明水未登彝，饰玉先浮鼎。\n寄语清居山上翁，驿使催归近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2596, '满江红', '吴泳', '元帅筹边，谁肯办、向前一著。\n大丞相、孙儿挺伟，素闲兵略。\n杨柳依依烟在眼，檀车春浮脚。\n更何妨、二十五长亭，横冰槊。\n登剑栈，怀关洛。\n机易去，愁难割。\n岂而今全是，从前都错。\n鹿走未知真局面，兽穷渐近空篱落。\n早经营、勋业复归来，江头酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2597, '渔家傲', '黄裳', '风入金波凝不住。\n玉楼间倚谁飞举。\n霜艳雪光来竞素。\n分辨处。\n独垂馀意窥庭户。\n强薄罗衣催玉步。\n美人为我当尊舞。\n醉到春来能几度。\n愁今古。\n月华不去年华去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2598, '渔家傲', '黄裳', '方令庚生初皎皎。\n珠帘钩上华堂晓。\n十二栏干多窈窕。\n妆欲妙。\n玉篦偷学娥眉小。\n扰扰时人随兔走。\n十分皆望菱花照。\n瑞荚莫嫌生得少。\n圆未了。\n已圆却恐佳期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2599, '渔家傲', '黄裳', '已送清歌归去後。\n东南楼上人声悄。\n冷落尤临弦上调。\n欢意少。\n空将万感收残照。\n窗外剑光初出鞘。\n斜窥梦断人年少。\n未到盖棺心未了。\n尘虑扰。\n双眸竟入扶桑晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2600, '永遇乐', '黄裳', '朝霭藏晖，客袍惊暖，天巧无意。\n杳杳谁知，包含造化，忽作人间瑞。\n儿童欢笑，忙来花下，便饮九春和气。\n急拿舟，高人乘兴，江天助我幽思。\n缤纷似翦，峥嵘如画，莫道冬容憔悴。\n恍象含空，尘无一点，疑在天宫里。\n酒楼酣宴，茶轩清玩，且待桂花来至。\n有馀光，明年待看，明红暗翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2601, '永遇乐', '黄裳', '天接重云，月临残腊，时有幽意。\n化作瑶池，纷纷戏蝶，一色非人世。\n无情征雁，乘风南向，怅望有情难寄。\n暖惊梅，先传芳信，夜来万宝春至。\n中齐胜境，东藩和气，自有名园佳丽。\n一梦休嗟，三千好客，何处寻珠履。\n小堂人静，尊前清昼，好惜岁华如逝。\n管弦中，金杯更劝，朱颜皓齿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2602, '蓦山溪', '黄裳', '春前信息，到处欢声满。\n旌旆出西郊，拥笙歌、婵娟两畔。\n东巡事往，空有雪中山，仙驭悄，古风间，谩动吟人叹。\n天边身世，况值重华旦。\n击壤访遗民，想如云、望中不断。\n功名休论，齐楚共唐虞，开口笑，插花归，更候清秋晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2603, '喜朝天・踏莎行', '黄裳', '雪云浓。\n送愁思，衾寒更怯霜风。\n惹起离恨，为光阴恼，人意无穷。\n谁省年华屡换，渐作个、浮生玉髯翁。\n休易感，新醅泛蚁，且共时同。\n相逢。\n笑语相契，况驾言游处，山里齐宫。\n寂寞时候，自有皓景，粉泽冬容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2604, '锦堂春・锦堂春慢', '黄裳', '天女多情，梨花碎翦，人间赠与多才。\n渐瑶池潋滟，粉翘徘徊。\n面不禁风力，背人飞去还来。\n最清虚好处，遥度幽香，不掩寒梅。\n岁华多幸呈瑞，泛寒光，一样仙子楼台。\n虽喜朱颜可照，时更相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2605, '霜叶飞', '黄裳', '谁能留得年华住。\n韶华今在何处。\n万林飞尽，但惊天篆，半空无数。\n望消息、霜催雁过，佳人愁起云垂暮。\n就绣幕、红炉去。\n金鸭时飘异香，柳腰人舞。\n休道行且分飞，共乐还一岁，见景长是欢聚。\n大来芳意，既与名园，是花为主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2606, '水龙吟', '黄裳', '五城中锁奇书，世间睡里无人唤。\n家家自有，月中丹桂，朱衣仙子。\n能驻光阴，解留颜鬓，引君霄汉。\n便西归、休梦华胥国□，约无限、烟霞伴。\n谁是采真高士，幻中寻取元非幻。\n时人不为，玉峰三秀，尘缘难断。\n莫说英雄，万端愁绪，夕阳孤馆。\n到流年过尽，韶华去了，起浮生叹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2607, '蝶恋花', '黄裳', '每到花开春已暮。\n况是人生，难得长欢聚。\n一日一游能几度。\n看看背我堂堂去。\n蝶乱蜂忙红粉妒。\n醉眼吟情，且与花为主。\n雪怨云愁无问处。\n芳心待向谁分付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2608, '蝶恋花', '黄裳', '兴到浓时春不住。\n昨夜雕栏，放了花无数。\n谈笑急邀吟醉侣。\n青娥也合随轩去。\n媚恐情生娇恐妒。\n今日开尊，多幸无风雨。\n休唱宴琼林一句。\n来年花共人何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2609, '蝶恋花', '黄裳', '南北两山骄欲斗。\n中有涟漪，莫道壶山小。\n落落情怀临漂渺。\n驾言来处铃斋悄。\n行到桃溪花解笑。\n人面相逢，竞好窥寒照。\n醉步斜西日少。\n欢声犹唱多情调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2610, '蝶恋花', '黄裳', '高下亭台山水境。\n两畔清辉，中有垂杨径。\n鹭点前汀供雪景。\n花乘流水传春信。\n不醉无归先说定。\n醉待言归，又被风吹醒。\n月下壶天游未尽。\n广寒宫是波中影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2611, '蝶恋花', '黄裳', '杳杳晴虚寒漫漫。\n放下尘劳，相共游银汉。\n便入醉乡休浩叹。\n神仙只在云门馆。\n饮兴偏宜流水畔。\n时有红蕖，落在黄金盏。\n鹭未忘机移别岸。\n画船更上前汀看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2612, '蝶恋花', '黄裳', '水鉴中看尤未老。\n乘兴拿舟，更向湘江过。\n俯仰太虚都一个。\n九春风思谁吟到。\n闲上钓台云外坐。\n待得金鳞，始放芳尊倒。\n醉後言归犹更早。\n素纤有数君须道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2613, '喜迁莺', '黄裳', '雕栏闲倚，瑞雪霁、浣出人间金碧。\n下想名园，芳心多少，欲占九州颜色。\n洞开路入丹汉，自是神仙真宅。\n寒吟外，看歌云舞雪，光阴难得。\n谁共怀古意，东海一老，居易头垂白。\n自此英雄，功名相继，空有寂寥遗迹。\n圣贤电拂休笑，离合许多宾客。\n使君乐与人同，且对云门斜日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2614, '宴琼林', '黄裳', '红紫趁春阑，独万簇琼英，尤未开罢。\n问谁共、绿幄宴群真，皓雪肌肤相亚。\n华堂路，小桥边，向晴阴一架。\n为香清、把作寒梅看，喜风来偏惹。\n莫笑因缘，见景跨春空，荣称亭榭。\n助巧笑、晓妆如画，有花钿堪借。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2615, '宴春台', '黄裳', '夏景舒长，麦天清润，高低万木成阴。\n晓意寒轻，一声未放蝉吟。\n但闻莺友同音。\n宴华堂、绿水中心。\n芙蓉都没，红妆信息，终待重寻。\n清冷相照，邂逅俱欢，翠娥拥我，芳酝强斟。\n笙歌引步，登临更向瑶岑。\n卧影沈沈。\n自风来、与客披襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2616, '雨霖铃', '黄裳', '天南游客。\n甚而今、却送君南国。\n薰风万里无限，吟蝉暗续，离情如织。\n秣马脂车，去即去、多少人惜。\n为惠爱、烟惨云山，送两城愁作行色。\n飞帆过、浙西封域。\n到秋深、且舣菏花泽。\n就船买得鲈鳜。\n新谷破、雪堆香粒。\n此兴谁同，须记东秦，有客相忆。\n愿听了、一阕歌声，醉倒拚今日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2617, '桂枝香', '黄裳', '醅初熟。\n竞看九日、西风弄寒菊。\n姝子新妆，向晓淡黄千簇。\n清香闹处君须住，掺盈头、醉乡相逐。\n马台欢笑，龙山纵逸，佳话重绪。\n共尽日、登临未足。\n更休问明年，浮世荣辱。\n难得良辰，鬓发见秋尤绿。\n且邀月照金尊上，近人寒、如对飞瀑。\n宴归还趁人来，茱萸佩垂红玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2618, '喜迁莺', '黄裳', '梅霖初歇。\n乍绛蕊海榴，争开时节。\n角黍包金，香蒲切玉，是处玳筵罗列。\n斗巧尽输少年，玉腕彩丝双结。\n舣彩舫，看龙舟两两，波心齐发。\n奇绝。\n难画处，激起浪花，飞作湖间雪。\n画鼓喧雷，红旗闪电，夺罢锦标方彻。\n望中水天日暮，犹见朱帘高揭。\n归棹晚，载菏花十里，一钩新月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2619, '洞仙歌', '黄裳', '乱蝉何事，冒暑吟如诉。\n断续声中为谁苦。\n阵云行碧落，舒卷光阴，秋意爽，俄作晴空骤雨。\n明珠无限数。\n都在荷花，疑是星河对庭户。\n莫负昼如年，况有清尊，披襟坐、水风来处。\n信美景良辰、自古难并，既不遇多才，岂能欢聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2620, '洞仙歌', '黄裳', '杳无风色，肠断莲花信。\n水鉴云垂数峰影。\n向劳生辛苦，寒暑煎人，争不老，空想秋堂夜静。\n玉姬挥皓月，时送微凉，莫吝金卮为伊尽。\n柳下夕阳收，傍水重游，花茵上、雪回襟冷。\n问避暑天机、自有奇人，但且对湖光，世间谁醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2621, '洞仙歌', '黄裳', '世间言笑，天上谁欢聚。\n河汉涵秋静无暑。\n望丹霄杳杳，云幄俄开，缘会远，空引时情万缕。\n彩楼人送目，今夕无双，巧在灵丝暗相许。\n爽气御西风，众乐难寻，乘槎看、鹊桥初度。\n过几刻良时、早已分飞，向月下何辞，十分芳醑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2622, '八声甘州', '黄裳', '化工多事了，却收天巧，都与西风。\n数峰云如扫，闲垂六幕，初见秋容。\n昨夜烦襟顿释，一雨洗遥空。\n偏有银蟾好，千里人同。\n引起游人多感，为静中景色，悲思无穷。\n傍雕栏怀古，谁问紫元翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2623, '满庭芳', '黄裳', '琼馆烟轻，银河风细，玉桥云锁方开。\n晓虹千丈，宛转下天来。\n人在水精宫里，行乐处、锦绣成堆。\n仍相问，人间天上，何处有蓬莱。\n徘徊。\n追往事，征南巧架，傅野怀才。\n谩石驱东海，沙合龙台。\n好是乐成初宴，红牙碎、声隐晴雷。\n江天晚，游人未散，莫放隼回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2624, '宴琼林', '黄裳', '霜月和银灯，乍送目楼台，星汉高下。\n爱东风、已暖绮罗香，竞走去来车马。\n红莲万斛，开尽处、长安一夜。\n少年郎、两两桃花面，有馀光相借。\n因甚灵山在此，是何人、能运神化。\n对景便作神仙会，恐云且驾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2625, '宴琼林', '黄裳', '遽暖间俄寒，妙用向园林，难问春意。\n万般声与色，自闻雷、便作浮华人世。\n红娇翠软，谁顿悟、天机此理。\n似韶容、可驻无人会，且忘言闲醉。\n当度仙家长日，向人间、闲看佳丽。\n念远处有东风在，梦悠悠往事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2626, '宴琼林', '黄裳', '已览遍韶容，最後有花王，芳信来报。\n魏妃天与色，拥姚黄、去赏十洲仙岛。\n东君到此，缘费尽、天机亦老。\n为娇多、只恐能言笑。\n惹风流烦恼。\n莫道两都迥出，倩多才、吟看谁好。\n为我惨有如花面，说良辰欲过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2627, '满江红', '黄裳', '绿盖纷纷，多少个、云霄仙子。\n应是有，瑶池盛会，靓妆临水。\n无奈轻盈风信急，瑞香乱翠红相倚。\n谁共吟、此景竹林人，桃溪士。\n时雨过，明珠细。\n朝雾染，香腮腻。\n轻舟破幽径，烦襟都洗。\n第一朵须寻华池景，寿觞边偶得龟千岁。\n乘兴泻、云液落新荷，休辞醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2628, '减字木兰花', '黄裳', '红旗高举。\n飞出深深杨柳渚。\n鼓击春雷。\n直破烟波远远回。\n欢声震地。\n惊退万人争战气。\n金碧楼西。\n衔得锦标第一归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2629, '瑶池月・瑶台月', '黄裳', '微尘濯尽，栖真处、群山排在云汉。\n青盘翠跃，掩映平林寒涧。\n流水急、数片桃花逝，自有留春仙馆。\n秦渔问，前朝换。\n卢郎待，今生满。\n谁伴。\n元翁笑语，相从未晚。\n更安得、世味堪玩。\n道未立、身尤是幻。\n浮生一梭过，梦回人散。\n卧松庵、当会灵源，现万象、无中须看。\n乾坤鼎，阴阳炭。\n琼枝秀，金圆烂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2630, '瑶池月・瑶台月', '黄裳', '扁舟寓兴，江湖上、无人知道名姓。\n忘机对景，咫尺群鸥相认。\n烟雨急、一片篷声碎，醉眼看山还醒。\n晴云断，狂风信。\n寒蟾倒，远山影。\n谁听。\n横琴数曲，瑶池夜冷。\n这些子、名利休问。\n况是物、都归幻境。\n须臾百年梦，去来无定。\n向婵娟、留住青春，笑世上、风流多病。\n蒹葭渚，芙蓉径。\n放侯印，趁渔艇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2631, '蝶恋花', '黄裳', '忽破黄昏还太素。\n寒浸楼台，缥缈非烟雾。\n江上分明星汉路。\n金银闪闪神仙府。\n影卧清光随我舞。\n邂逅三人，只愿长相聚。\n今月亭亭曾照古。\n古人问月今何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2632, '蝶恋花', '黄裳', '满到十分人望尽。\n仙桂无根，到处留光景。\n听我尊前欢未竟。\n金卮已弄寒蟾影。\n银色界中风色定。\n散了浮云，宝匣初开镜。\n归去不须红烛影。\n天边自与人相趁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2633, '蝶恋花', '黄裳', '古往今来忙里过。\n今古清光，静照人行道。\n难似素娥长见好。\n见频只是催人老。\n欲驻征轮无计那。\n世上多情，却被无情恼。\n夜夜乌飞谁识破。\n满头空恨霜华早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2634, '蝶恋花', '黄裳', '俄落盏中如有恋。\n盏未乾时，还见霜娥现。\n说向翠鬟斟莫浅。\n殷勤此意应相劝。\n光景尤宜年少面。\n千里同看，不与人同怨。\n席上笑歌身更健。\n良时只愿长相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2635, '蝶恋花', '黄裳', '千二百回圆未半。\n人世悲欢，此景长相伴。\n行到身边琼步款。\n金船载酒银河畔。\n谁为别来音信断。\n那更蟾光，一点窥孤馆。\n静送忘言愁一段。\n会须莫放笙歌散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2636, '蝶恋花', '黄裳', '人逐金乌忙到夜。\n不见金乌，方见人闲暇。\n天汉似来尊畔泻。\n须知闲暇欢无价。\n银色满身谁可画。\n两腋风生，爽气马。\n待入蟾宫偷造化。\n娥已许仙方借。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2637, '蝶恋花', '黄裳', '万籁无声天地静。\n清抱朱弦，不愧丹霄镜。\n照到林梢风有信。\n抬头疑是梅花领。\n万感只应闲对景。\n独倚危栏，扰扰人初定。\n吟不尽中愁不尽。\n溪山千古沈沈影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2638, '蝶恋花', '黄裳', '谁悟月中真火冷。\n能引尘缘，遂出轮迥境。\n争奈多情都未醒。\n九回肠断花间影。\n万古兴亡闲事定。\n物是人非，杳杳无音信。\n问月可知谁可问。\n不如且醉尊前景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2639, '蝶恋花', '黄裳', '忽送林光禽有语。\n飞如遥空，失素归洲鹭。\n照处无私清望富。\n馀辉不惜人人与。\n玉绳欲到中天路。\n且待飞觞，缓缓移琼步。\n花下影圆良夜午。\n东南楼上还相顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2640, '蝶恋花', '黄裳', '一望瑶华初委地。\n更约幽人，共赏岩边翠。\n拭把方诸聊与试。\n无情争得无中泪。\n飞瀑恐从星汉至。\n渐向宾筵，但觉寒如水。\n自爱一轮方得意。\n轻随箕毕还成累。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2641, '青门引・青门饮', '黄裳', '鸿落寒滨，燕辞幽馆，西成万室，颦眉人少。\n自古云，洞门何处，南望数峰秋晓。\n千骑旌麾远，去寻真、忙中心了。\n佩声盘入，烟霞绝顶，谁闻欢笑。\n当候青童相报。\n因待访仙人，长生微妙。\n置俎争来，四乡宴社，且看翠围红绕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2642, '满路花・促拍满路花', '黄裳', '乾坤生古意，草木起秋声。\n移人名利境，梦中惊。\n便寻灵宝，凤髓与龟精。\n密报黄芽就，紫府门开，道情有个莺莺。\n问归含楚山青。\n卧影水天明。\n松庵谁笑话，见还婴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2643, '倦寻芳慢・倦寻芳', '王', '露向晚，帘幕风轻，小院闲昼。\n翠迳莺来，惊下乱红铺绣。\n倚危墙，登高榭，海棠经雨胭脂透。\n算韶华，又因循过了，清明时候。\n倦游燕、风光满目，好景良辰，谁共携手。\n恨被榆钱，买断两眉长斗。\n忆高阳，人散後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2644, '虞美人', '张景修', '春风曾见桃花面。\n重见胜初见。\n两枝独占小春开。\n应怪刘郎迷路、又重来。\n旁人应笑髯公老。\n独爱花枝好。\n世间好景不长圆。\n莫放笙歌归院、且尊前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2645, '选冠子', '张景修', '嫩水蓝，遥堤映翠，半雨半烟桥畔。\n鸣禽弄舌，蔓草萦心，偏称谢家池馆。\n红粉墙头，柳摇金缕，纤柔舞腰低软。\n被和风、搭在阑干，终日绣帘谁卷。\n春易老，细叶舒眉，轻花吐絮，渐觉绿阴垂暖。\n章台系马，灞水维舟，追念凤城人远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2646, '青玉案', '黄大临', '行人欲上来时路。\n破晓雾、轻寒去。\n隔叶子规声暗度。\n十分酒满，舞歌袖，沾夜无寻处。\n故人近送旌旗暮。\n但听阳关第三句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2647, '青玉案', '黄大临', '千锋百嶂宜州路。\n天黯淡、知人去。\n晓别吾家黄叔度。\n弟兄华发，远山修水，异日同归处。\n樽饮散长亭暮。\n别语缠绵不成句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2648, '七娘子', '黄大临', '画堂银烛明如昼。\n见林宗、巾垫羞蓬首。\n针指花枝，线赊罗袖。\n须臾两带还依旧。\n劝君倒戴休令後。\n也不须、更漉渊明酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2649, '念奴娇', '黄庭坚', '断虹霁雨，净秋空，山染修眉新绿。\n桂影扶疏，谁便道，今夕清辉不足。\n万里青天，娥何处，驾此一轮玉。\n寒光零乱，为谁遍照。\n年少从我追游，晚凉幽径，绕张园森木。\n共倒金荷家万里，难得尊前相属。\n老子平生，江南江北，最爱临风曲。\n孙郎微笑，坐来声喷霜竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2650, '水调歌头', '黄庭坚', '瑶草一何碧，春入武陵溪。\n溪上桃花无数，花上有黄鹂。\n我欲穿花寻路，直入白云深处，浩气展红霓。\n只恐花深里，红露湿人衣。\n坐玉石，玉枕，拂金徽。\n谪仙何处，无人伴我白螺杯。\n我为灵芝仙草，不为朱唇丹脸，长啸亦何为。\n醉舞下山去，明月逐人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2651, '水调歌头', '黄庭坚', '落日塞垣路，风劲戛貂裘。\n翩翩数骑闲猎，深入黑山头。\n极目平沙千里，惟见雕弓白羽，铁面骏骅骝。\n隐隐望青冢，特地起闲愁。\n汉天子，方鼎盛，四百州。\n玉颜皓齿，深锁三十六宫秋。\n堂有经纶贤相，边有纵横谋将，不减翠娥羞。\n戎虏和乐也，圣主永无忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2652, '满庭芳', '黄庭坚', '初绾云鬟，才胜罗绮，便嫌柳陌花街。\n占春才子，容易托行媒。\n其奈风情债负，烟花部、不免差排。\n刘郎恨，桃花片片，随水染尘埃。\n风流，贤太守，能笼翠羽，宜醉金钗。\n且留取垂杨，掩映厅阶。\n直待朱去後，从伊便、窄袜弓鞋。\n知恩否，朝云暮雨，还向梦中来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2653, '满庭芳', '黄庭坚', '北苑春风，方圭圆璧，万里名动京关。\n碎身粉骨，功合上凌烟。\n尊俎风流战胜，降春睡、开拓愁边。\n纤纤捧，研膏溅乳，金缕鹧鸪斑。\n相如，虽病渴，一觞一咏，宾有群贤。\n为扶起灯前，醉玉颓山。\n搜搅心中万卷，还倾动、三峡词源。\n归来晚，文君未寝，相对小窗前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2654, '鼓笛慢・水龙吟', '黄庭坚', '早秋明月新圆，汉家戚里生飞将。\n青骢宝勒，绿沈金锁，曾瞻天仗。\n种德江南，宣威西夏，合宫陪享。\n况当年定计，昭陵与子，勋劳在、诸公上。\n千骑风流年少，暂淹留、莫辜清赏。\n平坡驻马，虚弦落雁，思临虏帐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2655, '洞仙歌', '黄庭坚', '月中丹桂，自风霜难老。\n阅尽人间盛衰草。\n望中秋、才有几日，十分圆，霾风雨，云表常如永昼。\n不得文章力，白首防秋，谁念云中上功守。\n正注意，得人雄，静扫河山，应难纵、五湖归棹。\n问持节冯唐几时来，看再策勋名，印窠如斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2656, '雨中花・夜行船', '黄庭坚', '政乐中和，夷夏宴喜，官梅乍传消息。\n待作新年欢计，断送春色。\n桃李成阴，甘棠少讼，又移旌戟。\n念画楼朱阁，风流高会，顿冷谈席。\n西州纵有，舞裙歌板，谁共茗邀棋敌。\n归来未得，先沾离袖，管弦催滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2657, '忆帝京', '黄庭坚', '鸣鸠乳燕春闲暇。\n化作绿阴槐夏。\n寿酒舞红裳，睡鸭飘香麝。\n醉此洛阳人，佐郡深儒雅。\n况坐上、玉麟金马。\n更莫问、莺老花谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2658, '醉蓬莱', '黄庭坚', '对朝云，暮雨霏微，乱峰相倚。\n巫峡高唐，锁楚宫朱翠。\n画戟移春，靓妆迎马，向一川都会。\n万里投荒，一身吊影，成何欢意。\n尽道黔南，去天尺五，望极神州，万里烟水。\n尊酒公堂，有中朝佳士。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2659, '南歌子', '黄庭坚', '诗有渊明语，歌无子夜声。\n论文思见老弥明。\n坐想罗浮山下、羽衣轻。\n何处黔中郡，遥知隔晚晴。\n雨馀风急断虹横。\n应梦池塘春草、若为情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2660, '蓦山溪', '黄庭坚', '鸳鸯翡翠，小小思珍偶。\n眉黛敛秋波，尽湖南、山明水秀。\n娉娉袅袅，恰近十三馀，春未透。\n花枝瘦。\n正是愁时候。\n寻花载酒。\n肯落谁人後。\n只恐远归来，绿成阴、青梅如豆。\n心期得处，每自不由人，长亭柳。\n君知否。\n千里犹回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2661, '转调丑奴儿・采桑子', '黄庭坚', '得意许多时。\n长醉赏、月影花枝。\n暴风狂雨年年有，金笼锁定，莺雏燕友，不被鸡期。\n红旆转逶迤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2662, '品令', '黄庭坚', '败叶霜天晓。\n渐鼓吹、催行棹。\n栽成桃李未开，便解银章归报。\n去取麒麟图画，要及年少。\n劝公醉倒。\n别语怎向醒时道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2663, '踏莎行', '黄庭坚', '画鼓催春，蛮歌走饷。\n雨前一焙谁争长。\n低株摘尽到高株，株株别是闽溪样。\n碾破春风，香凝午帐。\n银瓶雪滚翻成浪。\n今宵无睡酒醒时，摩围影在秋江上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2664, '踏莎行', '黄庭坚', '临水夭桃，倚墙繁李。\n长杨风掉青骢尾。\n尊中有酒且酬春，更寻何处无愁地。\n明日重来，落花如绮。\n芭蕉渐展山公启。\n欲笺心事寄天公，教人长对花前醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2665, '定风波', '黄庭坚', '自断此生休问天。\n白头波上泛孤船。\n老去文章无气味。\n憔悴。\n不堪驱使菊花前。\n闻道使君携将吏。\n高会。\n参军吹帽晚风颠。\n千骑插花秋色暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2666, '定风波', '黄庭坚', '万里黔中一漏天。\n屋居终日似乘船。\n及至重阳天也霁。\n催醉。\n鬼门关外蜀江前。\n莫笑老翁犹气岸。\n君看。\n几人黄菊上华颠。\n戏马台南追两谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2667, '定风波', '黄庭坚', '晚岁监州闻荔枝。\n赤英垂坠压阑枝。\n万里来逢芳意歇。\n愁绝。\n满盘空忆去年时。\n涧草山花光照坐。\n春过。\n等闲桃李又累累。\n辜负寒泉浸红皱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2668, '定风波', '黄庭坚', '准拟阶前摘荔枝。\n今年歇尽去年枝。\n莫是春光厮料理。\n无比。\n譬如疟有休时。\n碧朱阑情不浅。\n何晚。\n来年枝上报累累。\n雨後园林坐清影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2669, '鹊桥仙', '黄庭坚', '八年不见，清都绛阙，望河汉、溶溶漾漾。\n年年牛女恨风波，拼此事、人间天上。\n野麋丰草，江鸥远水，老去惟便疏放。\n百钱端欲问君平，早晚具、归田小舫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2670, '鹊桥仙', '黄庭坚', '朱楼彩舫，浮瓜沈李，报答风光有处。\n一年尊酒暂时同，别泪作、人间晓雨。\n鸳鸯机综，能令侬巧，也待乘槎仙去。\n若逢海上白头翁，共一访、痴牛呆女。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2671, '阮郎归', '黄庭坚', '黔中桃李可寻芳。\n摘茶人自忙。\n月团犀胯斗圆方。\n研膏入焙香。\n青箬裹，绛纱囊。\n品高闻外江。\n酒阑传碗舞红裳。\n都濡春味长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2672, '阮郎归', '黄庭坚', '烹茶留客驻金鞍。\n月斜窗外山。\n别郎容易见郎难。\n有人思远山。\n归去後，忆前欢。\n画屏金博山。\n一杯春露莫留残。\n与郎扶玉山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2673, '更漏子', '黄庭坚', '庵摩勒，西土果。\n霜後明珠颗颗。\n凭玉兔，捣香尘。\n称为席上珍。\n号馀甘，争奈苦。\n临上马时分付。\n管回味，却思量。\n忠言君拭尝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2674, '绣带子・好女儿', '黄庭坚', '小院一枝梅。\n冲破晓寒开。\n晚到芳园游戏，满袖带香回。\n玉酒覆银杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2675, '撼庭竹', '黄庭坚', '呜咽南楼吹落梅。\n闻鸦树惊栖。\n梦中相见不多时。\n隔城今夜也应知。\n坐久水空碧，山月影沈西。\n买个宅儿住著伊。\n刚不肯相随。\n如今果被天嗔作，永落鸡群被鸡欺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2676, '减字木兰花', '黄庭坚', '馀寒争令。\n雪共蜡梅相照影。\n昨夜东风。\n已出耕牛劝岁功。\n阴云幂幂。\n近觉去天无几尺。\n休恨春迟。\n桃李梢头次第知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2677, '减字木兰花', '黄庭坚', '使君那里。\n千骑尘中依约是。\n拂我眉头。\n无处重寻庾信愁。\n山云弥漫。\n夹道旌旗联复断。\n万事茫茫。\n分付澄波与烂肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2678, '减字木兰花', '黄庭坚', '襄王梦里。\n草绿烟深何处是。\n宋玉台头。\n暮雨朝云几许愁。\n飞花漫漫。\n不管羁人肠欲断。\n春水茫茫。\n欲度南陵更断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2679, '减字木兰花', '黄庭坚', '巫山古县。\n老杜淹留情始见。\n拨闷题诗。\n千古神交世不知。\n云阳台下。\n更值清明风雨夜。\n知道愁辛。\n果是当时作赋人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2680, '减字木兰花', '黄庭坚', '诗翁才刃。\n曾陷文场貔虎阵。\n谁敢当哉。\n况是焚舟决胜来。\n三巴春杪。\n客馆梦回风雨晓。\n胸次峥嵘。\n欲共涛头赤甲平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2681, '减字木兰花', '黄庭坚', '苍崖万仞。\n下有奔雷千百阵。\n自古危哉。\n谁遣西园麽来。\n猿啼云杪。\n破梦一声巫峡晓。\n苦唤愁生。\n不是西园作麽平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2682, '减字木兰花', '黄庭坚', '终宵忘寐。\n好事如何犹尚未。\n子细沈吟。\n珠泪盈盈湿袖襟。\n与君别也。\n愿在郎心莫暂舍。\n记取盟言。\n闻早回程却再圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2683, '减字木兰花', '黄庭坚', '中秋多雨。\n常是尊狼藉去。\n今夜云开。\n须道娥得得来。\n不知云外。\n还有清光同此会。\n笛在层楼。\n声彻摩围顶上头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2684, '减字木兰花', '黄庭坚', '中秋无雨。\n醉送月衔西岭去。\n笑口须开。\n几度中秋见月来。\n前年江外。\n儿女传杯兄弟会。\n此夜登楼。\n小谢清吟慰白头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2685, '减字木兰花', '黄庭坚', '浓云骤雨。\n巫峡有情来又去。\n今夜天开。\n不与娥作伴来。\n清光无外。\n白发老人心自会。\n何处歌楼。\n贪看冰轮不转头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2686, '减字木兰花', '黄庭坚', '举头无语。\n家在月明生处住。\n拟上摩围。\n最上峰头试望之。\n偏怜络秀。\n苦淡同甘谁更有。\n想见牵衣。\n月到愁边总不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2687, '减字木兰花', '黄庭坚', '月中笑语。\n万里同依光景住。\n天水相围。\n相见无因梦见之。\n诸儿娟秀。\n儒学传家渠自有。\n自作秋衣。\n渐老先寒人未知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2688, '减字木兰花', '黄庭坚', '当年夜雨。\n头白相依无去住。\n儿女成围。\n欢笑尊前月照之。\n阿连高秀。\n千万里来忠孝有。\n岂谓无衣。\n岁晚先寒要弟知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2689, '木兰花令', '黄庭坚', '风开水面鱼纹皱。\n暖入草心犀点透。\n乍看晴日弄柔条，忆得章台人姓柳。\n心情老大痴成就。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2690, '木兰花令', '黄庭坚', '东君未试雷霆手。\n洒雪开春春锁透。\n帝台应点万年枝，穷巷偏欺三径柳。\n峰排群玉森相就。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2691, '减字木兰花', '黄庭坚', '新年何许春光漏。\n小院闭门风日透。\n酥花入坐颇欺梅，雪絮因风全是柳。\n使君落笔春词就。\n应唤歌檀催舞袖。\n得开眉处且开眉，人世可能金石寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2692, '减字木兰花', '黄庭坚', '黄金捍拨春风手。\n帘幕重重音韵透。\n梅花破萼便回春，似有黄鹂鸣翠柳。\n晓妆未惬梅添就。\n玉笋捧杯离钿袖。\n会拼千日笑尊前，他日相思空损寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2693, '减字木兰花', '黄庭坚', '黔中士女游晴昼。\n花信轻寒罗袖透。\n争寻穿石道宜男，更买江鱼双贯柳。\n竹枝歌好移船就。\n依倚风光垂翠袖。\n满倾芦酒指摩围，相守与郎如许寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2694, '减字木兰花', '黄庭坚', '可怜翡翠随鸡走。\n学绾双鬟年纪小。\n见来行待恶怜伊，心性娇痴空解笑。\n红蕖照映霜林表。\n杨柳舞风腰袅袅。\n衾馀枕剩尽相容，只是老人难再少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2695, '清平乐', '黄庭坚', '春归何处。\n寂寞无行路。\n若有人知春去处。\n唤取归来同住。\n春无踪迹谁知。\n除非问取黄鹂。\n百啭无人能解，因风飞过蔷薇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2696, '清平乐', '黄庭坚', '黄花当户。\n已觉秋容暮。\n云梦南州逢笑语。\n心在歌边舞处。\n使君一笑眉开。\n新晴照酒尊来。\n且乐尊前见在，休思走马章台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2697, '清平乐', '黄庭坚', '休推小户。\n看即风光暮。\n萸粉菊英浮碗醑。\n报答风光有处。\n几回笑口能开。\n少年不肯重来。\n借问牛山戏马，今为谁姓池台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2698, '减字木兰花', '黄庭坚', '舞鬟娟好。\n白发黄花帽。\n醉任旁观嘲潦倒。\n扶老偏宜年小。\n舞回脸玉胸酥。\n缠头一斛明珠。\n日日梁州薄媚，年年金菊茱萸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2699, '减字木兰花', '黄庭坚', '乍晴秋好。\n黄菊乌帽。\n不见清谈人绝倒。\n更忆添丁小小。\n蜀娘漫点花酥。\n酒槽空滴真珠。\n兄弟四人别住，他年同插茱萸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2700, '清平乐', '黄庭坚', '冰堂酒好。\n只恨银杯小。\n新作金荷工献巧。\n图要连台拗倒。\n采莲一曲清歌。\n急檀催卷金河。\n醉里香飘睡鸭，更惊罗袜凌波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2701, '忆帝京', '黄庭坚', '薄妆小靥闲情素。\n抱著琵琶凝伫。\n慢拈复轻拢，切切如私语。\n转拨割朱弦，一段惊沙去。\n万里嫁、乌孙公主。\n对易水、明妃不渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2702, '忆帝京', '黄庭坚', '银烛生花如红豆。\n占好事、而今有。\n人醉曲屏深，借宝瑟、轻招手。\n一阵白苹风，故灭烛、教相就。\n花带雨、冰肌香透。\n恨啼乌、辘轳声晓。\n岸柳微凉吹残酒。\n断肠时、至今依旧。\n镜中消瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2703, '画堂春', '黄庭坚', '东堂西畔有池塘。\n使君几明窗。\n日西人吏散东廊。\n蒲苇送清凉。\n翠管细通岩溜，小峰重叠山光。\n近池催置琵琶床。\n衣带水风香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2704, '画堂春', '黄庭坚', '摩围小隐枕蛮江。\n蛛丝闲锁晴窗。\n水风山影上修廊。\n不到晚来凉。\n相伴蝶穿花径，独飞鸥舞春光。\n不因送客下绳床。\n添火炷炉香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2705, '鹧鸪天', '黄庭坚', '万事令人心骨寒。\n故人坟上土新乾。\n淫坊酒肆狂居士，李下何妨也整冠。\n金作鼎，玉为餐。\n老来亦失少时欢。\n茱萸菊蕊年年事，十日还将九日看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2706, '鹧鸪天', '黄庭坚', '黄菊枝头生晓寒。\n人生莫放酒杯乾。\n风前横笛斜吹雨，醉里簪花倒著冠。\n身健在，且加餐。\n舞裙歌板尽清欢。\n黄花白发相牵挽，付与时人洗眼看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2707, '鹧鸪天', '黄庭坚', '紫菊黄花风露寒。\n平沙戏马雨新乾。\n且看欲尽花经眼，休说弹冠与挂冠。\n甘酒病，废朝餐。\n何人得似醉中欢。\n十年一觉扬州梦，为报时人洗眼看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2708, '鹧鸪天', '黄庭坚', '西塞山边白鹭飞。\n桃花流水鳜鱼肥。\n朝廷尚觅玄真子，何处如今更有诗。\n青箬笠，绿蓑衣。\n斜风细雨不须归。\n人间底是无波处，一日风波十二时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2709, '醉落魄・一斛珠', '黄庭坚', '陶陶兀兀。\n尊前是我华胥国。\n争名争利休休莫。\n雪月风花，不醉怎生得。\n邯郸一枕谁忧乐。\n新诗新事因闲适。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2710, '醉落魄・一斛珠', '黄庭坚', '陶陶兀兀。\n人生无累何由得。\n杯中三万六千日。\n闷损旁观，自我解落魄。\n扶头不起还颓玉。\n日高春睡平生足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2711, '醉落魄・一斛珠', '黄庭坚', '陶陶兀兀。\n人生梦里槐安国。\n教公休醉公但莫。\n盏倒垂莲，一笑是赢得。\n街头酒贱民声乐。\n寻常行处寻欢适。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2712, '醉落魄・一斛珠', '黄庭坚', '陶陶兀兀。\n醉乡路远归不得。\n心情那似当年日。\n割爱金河，一碗淡莫托。\n异乡薪桂炊苍玉。\n摩挲经笥须知足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2713, '南乡子', '黄庭坚', '招唤欲千回。\n暂得尊前笑口开。\n万水千山还麽去，悠哉。\n酒面黄花欲醉谁。\n顾影又徘徊。\n立到斜风细雨吹。\n见我未衰容易去，还来。\n不道年年即渐衰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2714, '南乡子', '黄庭坚', '未报贾船回。\n三径荒锄菊卧开。\n想得邻船霜笛罢，沾衣。\n不为涪翁更为谁。\n风力袅萸枝。\n酒面红鳞惬细吹。\n莫笑插花和事老，摧颓。\n却向人间耐盛衰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2715, '南乡子', '黄庭坚', '黄菊满东篱。\n与客携壶上翠微。\n已是有花兼有酒，良期。\n不用登临恨落晖。\n满酌不须辞。\n莫待无花空折枝。\n寂寞酒醒人散後，堪悲。\n节去蜂愁蝶不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2716, '南乡子', '黄庭坚', '卧稻雨馀收。\n处处游人簇远洲。\n白发又扶红袖醉，戎州。\n乱折黄花插满头。\n青眼想风流。\n画出西楼一帧秋。\n还把去年欢意舞，梁洲。\n塞雁西来特地愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2717, '点绛唇', '黄庭坚', '浊酒黄花，画檐十日无秋燕。\n梦中相见。\n起作南柯观。\n镜里朱颜，又减年时半。\n江山远。\n登高人健。\n应问西来雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2718, '谒金门', '黄庭坚', '山又水。\n行尽吴头楚尾。\n兄弟灯前家万里。\n相看如梦寐。\n君似成蹊桃李。\n入我草堂松桂。\n莫厌岁寒无气味。\n馀生今已矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2719, '采桑子', '黄庭坚', '宗盟有妓能歌舞，宜醉尊。\n待约新醅。\n车上危坡尽要推。\n西邻三弄争秋月，邀勒春回。\n个里声催。\n铁树枝头花也开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2720, '采桑子', '黄庭坚', '荔枝滩上留千骑，桃李阴繁。\n燕寝香残。\n画戟森森镇八蛮。\n永康又得风流守，管领江山。\n少讼多闲。\n烟霭楼台舞翠鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2721, '采桑子', '黄庭坚', '马湖来舞钗初赐，笳鼓声繁。\n贤将开关。\n威竦西山八诏蛮。\n南溪地逐名贤重，深锁群山。\n燕喜公闲。\n一斛明珠两小鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2722, '西江月', '黄庭坚', '龙焙头纲春早，谷帘第一泉香。\n已醺浮蚁嫩鹅黄。\n想见翻成雪浪。\n兔褐金丝宝碗，松风蟹眼新汤。\n无因更发次公狂。\n甘露来从仙掌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2723, '鹧鸪天', '黄庭坚', '汤泛冰瓷一坐春。\n长松林下得灵根。\n吉祥老子亲拈出，个个教成百岁人。\n灯焰焰，酒醺醺。\n壑源曾未醒酲魂。\n与君更把长生碗，聊为清歌驻白云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2724, '渔家傲', '黄庭坚', '万水千山来此土。\n本提心印传梁武。\n对朕者谁浑不顾。\n成死语。\n江头暗折长芦渡。\n面壁九年看二祖。\n一花五叶亲分付。\n只履提归葱岭去。\n君知否。\n分明忘却来时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2725, '渔家傲', '黄庭坚', '三十年来无孔窍。\n几回得眼还迷照。\n一见桃花参学了。\n呈法要。\n无弦琴上单于调。\n摘叶寻枝虚半老。\n拈花特地重年少。\n今後水云人欲晓。\n非玄妙。\n灵云合破桃花笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2726, '渔家傲', '黄庭坚', '忆昔药山生一虎。\n华亭船上寻人渡。\n散却夹山拈坐具。\n呈见处。\n繁驴橛上合头语。\n千户垂丝君看取。\n离钩三寸无生路。\n蓦口一桡亲子父，犹回顾。\n瞎驴丧我儿孙去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2727, '渔家傲', '黄庭坚', '百丈峰头开古镜。\n马驹踏杀重苏醒。\n接得古灵心眼净。\n光炯炯。\n归来藏在袈裟影。\n好个佛堂佛不圣。\n祖师沈醉犹看镜。\n却与斩新提祖令。\n方猛省。\n无声三昧天皇饼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2728, '渔家傲', '黄庭坚', '踏破草鞋参到了。\n等闲拾得衣中宝。\n遇酒逢花须一笑。\n长年少。\n俗人不用嗔贫道。\n何处青旗夸酒好。\n醉乡路上多芳草。\n提著葫芦行未到。\n风落帽。\n葫芦却缠葫芦倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2729, '拨棹子', '黄庭坚', '归去来。\n归去来。\n携手旧山归去来。\n有人共、月对尊。\n横一琴，甚处不逍遥自在。\n闲世界。\n无利害。\n何必向、世间甘幻爱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2730, '诉衷情', '黄庭坚', '一波才动万波随。\n蓑笠一钩丝。\n锦鳞正在深处，千尺也须垂。\n吞又吐，信还疑。\n上钩迟。\n水寒江静，满目青山，载月明归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2731, '浣溪沙', '黄庭坚', '新妇滩头眉黛愁。\n女儿浦口眼波秋。\n惊鱼错认月沈钩。\n青箬笠前无限事，绿蓑衣底一时休。\n斜风吹雨转船头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2732, '菩萨蛮', '黄庭坚', '半烟半雨溪桥畔。\n渔翁醉著无人唤。\n疏懒意何长。\n春风花草香。\n江山如有待。\n此意陶潜解。\n问我去何之。\n君行到自知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2733, '调笑歌・调笑令', '黄庭坚', '无语。\n恨如许。\n方士归时肠断处。\n梨花一枝春带雨。\n半钿分钗亲付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2734, '步蟾宫', '黄庭坚', '虫儿真个忒灵利。\n恼乱得、道人眼起。\n醉归来、恰似出桃源，但目送、落花流水。\n何妨随我归云际。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2735, '南柯子・南歌子', '黄庭坚', '郭泰曾名我，刘翁复见谁。\n入廛还作和罗槌。\n特地干戈相待、使人疑。\n秋浦横波眼，春窗远岫眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2736, '南柯子・南歌子', '黄庭坚', '万里沧江月，波清说向谁。\n顶门须更下金槌。\n只恐风惊草动、又生疑。\n金雁斜妆颊，青螺浅画眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2737, '丑奴儿・采桑子', '黄庭坚', '夜来酒醒清无梦，愁倚阑干。\n露滴轻寒。\n雨打芙蓉泪不乾。\n佳人别後音尘悄，消瘦难拼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2738, '西江月', '黄庭坚', '断送一生惟有，破除万事无过。\n远山横黛蘸秋波。\n不饮旁人笑我。\n花病等闲瘦弱，春愁没处遮拦。\n杯行到手莫留残。\n不道月斜人散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2739, '画堂春', '黄庭坚', '东风吹柳日初长。\n雨馀芳草斜阳。\n杏花零乱燕泥香。\n睡损红妆。\n宝篆烟消龙凤，画屏云锁潇湘。\n夜寒微透薄罗裳。\n无限思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2740, '虞美人', '黄庭坚', '平王本爱江湖住。\n鸥鹭无人处。\n江南江北水云连。\n莫笑醯鸡歌舞、瓮中天。\n当涂舣棹蒹葭外。\n赖有宾朋在。\n此身无路入修门。\n惭愧诗翁清些、与招魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2741, '虞美人', '黄庭坚', '天涯也有江南信。\n梅破知春近。\n夜阑风细得香迟。\n不道晓来开遍、向南枝。\n玉台弄粉花应妒。\n飘到眉心住。\n平生个里愿杯深。\n去国十年老尽、少年心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2742, '两同心', '黄庭坚', '巧笑眉颦。\n行步精神。\n隐隐似、朝云行雨，弓弓样、罗袜生尘。\n尊前见，玉槛雕笼，堪爱难亲。\n自言家住天津。\n生小从人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2743, '两同心', '黄庭坚', '一笑千金。\n越样情深。\n曾共结、合欢罗带，终愿效、比翼纹禽。\n许多时，灵利惺惺，蓦地昏沈。\n自从官不容针。\n直至而今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2744, '两同心', '黄庭坚', '秋水遥岑。\n妆淡情深。\n尽道教、心坚穿石，更说甚、官不容针。\n霎时间，雨散云归，无处追寻。\n小楼朱阁沈沈。\n一笑千金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2745, '满庭芳', '黄庭坚', '北苑龙团，江南鹰爪，万里名动京关。\n碾深罗细，琼蕊暖生烟，一种风流气味，如甘露、不染尘凡。\n纤纤捧，冰瓷莹玉，金缕鹧鸪斑。\n相如，方病酒，银瓶蟹眼，波怒涛翻。\n为扶起，尊前醉玉颓山。\n饮罢风生两腋，醒魂到、明月轮边。\n归来晚，文君未寝，相对小窗前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2746, '满庭芳', '黄庭坚', '明眼空青，忘忧萱草，翠玉闲淡疏妆。\n小来歌舞，长是倚风光。\n我已逍遥物外，人冤道、别有思量。\n难忘处，良辰美景，襟袖有馀香。\n鸳鸯。\n头白早，多情易感，红蓼池塘。\n又须得，尊前席上成双。\n些子风流罪过，都说与、明月空床。\n难拘管，朝云暮雨，分付楚襄王。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2747, '满庭芳', '黄庭坚', '修水浓青，新条淡绿，翠光交映虚亭。\n锦鸳霜鹭，荷径拾幽苹。\n香渡栏干屈曲，红妆映、薄绮疏。\n风清夜，横塘月满，水净见移星。\n堪听。\n微雨过，姗藻荇，琐碎浮萍。\n便移转，胡床湘簟方屏。\n练霭鳞云旋满，声不断、檐响风铃。\n重开宴，瑶池雪沁，山露佛头青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2748, '蓦山溪', '黄庭坚', '山围江暮。\n天镜开晴絮。\n斜影过梨花，照文星、老人星聚。\n清樽一笑，欢甚却成愁，别时襟，馀点点，疑是高唐雨。\n无人知处。\n梦里云归路。\n回雁晓风清，雁不来、啼鸦无数。\n心情老懒，尤物解宜人，春尽也，有南风，好便回帆去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2749, '蓦山溪', '黄庭坚', '稠花乱叶，到处撩人醉。\n林下有孤芳，不匆匆、成蹊桃李。\n今年风雨，莫送断肠红，斜枝倚。\n风尘里。\n不带尘风气。\n微嗔又喜。\n约略知春味。\n江上一帆愁，梦犹寻、歌梁舞地。\n如今对酒，不似那回时，书谩写，梦来空，只有相思是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2750, '蓦山溪', '黄庭坚', '山明水秀，尽属诗人道。\n应是五陵儿，见衰翁、孤吟绝倒。\n一觞一咏，潇洒寄高闲，松月下，竹风间，试想为襟抱。\n玉关遥指，万里天衢杳。\n笔阵扫秋风，泻珠玑、琅琅皎皎。\n卧龙智略，三诏佐升平，烟塞事，玉堂心，频把菱花照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2751, '阮郎归', '黄庭坚', '盈盈娇女似罗敷。\n湘江明月珠。\n起来绾髻又重梳。\n弄妆仍学书。\n歌调态，舞工夫。\n湖南都不如。\n它年未厌白髭。\n同舟归五湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2752, '阮郎归', '黄庭坚', '歌停檀板舞停鸾。\n高阳饮兴阑。\n兽烟喷尽玉壶乾。\n香分小凤团。\n雪浪浅，露花圆。\n捧瓯春笋寒。\n绛纱笼下跃金鞍。\n归时人倚阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2753, '阮郎归', '黄庭坚', '摘山初制小龙团。\n色和香味全。\n碾声初断夜将阑。\n烹时鹤避烟。\n消滞思，解尘烦。\n金瓯雪浪翻。\n只愁啜罢水流天。\n馀清搅夜眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2754, '阮郎归', '黄庭坚', '退红衫子乱蜂儿。\n衣宽只为伊。\n为伊去得忒多时。\n教人直是疑。\n长睡晚，理妆迟。\n愁多懒画眉。\n夜来算得有归期。\n灯花则甚知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2755, '阮郎归', '黄庭坚', '贫家春到也骚骚。\n琼浆注小槽。\n老夫不出长蓬蒿。\n邻墙开碧桃。\n木芍药，品题高。\n一枝烦剪刀。\n传杯犹似少年豪。\n醉红浸雪毛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2756, '定风波', '黄庭坚', '把酒花前欲问溪。\n问溪何事晚声悲。\n名利往来人尽老。\n谁道。\n溪声今古有休时。\n且共玉人斟玉醑。\n休诉。\n笙歌一曲黛眉低。\n情似长溪长不断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2757, '定风波', '黄庭坚', '小院难图云雨期。\n幽欢浑待赏花时。\n到得春来君却去。\n相误。\n不须言语泪双垂。\n密约尊前难嘱付。\n偷顾。\n手搓金橘敛双眉。\n庭榭清风明月媚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2758, '定风波', '黄庭坚', '上客休辞酒浅深。\n素儿歌里细听沈。\n粉面不须歌扇掩，闲静，一声一字总关心。\n花外黄鹂能密语。\n休诉。\n有花能得几时斟。\n画作远山临碧水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2759, '定风波', '黄庭坚', '歌舞阑珊退晚妆。\n主人情重更留汤。\n冠帽斜辞醉去，邀定，玉人纤手自磨香。\n又得尊前聊笑语。\n如许。\n短歌宜舞小红裳。\n宝马促归朱户闭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2760, '浪淘沙', '黄庭坚', '忆昔谪巴蛮。\n荔子亲攀。\n冰肌照映柘枝冠。\n日擘轻红三百颗，一味甘寒。\n重入鬼门关。\n也似人间。\n一双和叶插云鬟。\n赖得清湘燕玉面，同倚阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2761, '看花回', '黄庭坚', '夜永兰堂醺饮，半倚颓玉。\n烂熳坠钿堕履，是醉时风景，花暗烛残，欢意未阑，舞燕歌珠成断续。\n催茗饮、旋煮寒泉，露井瓶窦响飞瀑。\n纤指缓、连环动触。\n渐泛起、满瓯银粟。\n香引春风在手，似粤岭闽溪，初采盈掬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2762, '惜馀欢・惜余欢', '黄庭坚', '四时美景，正年少赏心，频启东阁。\n芳酒载盈车，喜朋侣簪合。\n杯觞交飞劝酬献，正酣饮、醉主公陈榻。\n坐来争奈，玉山未颓，兴寻巫峡。\n歌阑旋烧绛蜡。\n况漏转铜壶，烟断香鸭。\n犹整醉中花，借纤手重插。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2763, '醉落魄・一斛珠', '黄庭坚', '苍颜华发。\n故山归计无因得。\n旧交新贵音书绝。\n惟有家人，犹作殷勤别。\n离亭欲去歌声咽。\n潇潇细雨凉生颊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2764, '西江月', '黄庭坚', '月侧金盆堕水，雁回醉墨书空。\n君诗秀色雨园葱。\n想见衲衣寒拥。\n蚁穴梦魂人世，杨花踪迹风中。\n莫将社燕等秋鸿。\n处处春山翠重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2765, '西江月', '黄庭坚', '宋玉短墙东畔，桃源落日西斜。\n浓妆下著绣帘遮。\n鼓笛相催清夜。\n转眄惊翻长袖，低徊细踏红靴。\n舞馀犹颤满头花。\n娇学男儿拜谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2766, '木兰花令', '黄庭坚', '凌台上青青麦。\n姑熟堂前馀翰墨。\n暂分一印管江山，稍为诸公分皂白。\n江山依旧云空碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2767, '木兰花令', '黄庭坚', '翰林本是神仙谪。\n落帽风流倾座席。\n坐中还有赏音人，能岸乌纱倾大白。\n江山依旧云横碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2768, '木兰花令', '黄庭坚', '青壶乃似壶中谪。\n万象光辉森宴席。\n红尘闹处便休休，不是个中无皂白。\n歌烦舞倦朱成碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2769, '木兰花令', '黄庭坚', '庾郎三九常安乐。\n使有万钱无处著。\n徐熙小鸭水边花，明月清风都占却。\n朱颜老尽心如昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2770, '木兰花令', '黄庭坚', '少年得意从军乐。\n晚岁天教闲处著。\n功名富贵久寒灰，翰墨文章新讳却。\n是非不用分今昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2771, '品令', '黄庭坚', '凤舞团团饼。\n恨分破、教孤令。\n金渠体净，只轮慢碾，玉尘光莹。\n汤响松风，早减了、二分酒病。\n味浓香永。\n醉乡路、成佳镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2772, '醉蓬莱', '黄庭坚', '对朝云，暮雨霏微，翠峰相倚。\n巫峡高唐，锁楚宫佳丽，蘸水朱门，半空霜戟，自一川都会。\n虏酒千杯，夷歌百转，迫人垂泪。\n人道黔南，去天尺五，望极神京，万重烟水。\n悬榻相迎，有风流千骑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2773, '江城子', '黄庭坚', '画堂高会酒阑珊。\n倚栏干。\n霎时间。\n千里关山，常恨见伊难。\n及至而今相见了，依旧似、隔关山。\n倩人传语问平安。\n省愁烦。\n泪休弹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2774, '江城子', '黄庭坚', '新来曾被眼奚搐。\n不甘伏。\n怎拘束。\n似梦还真，烦乱损心曲。\n见面暂时还不见，看不足、惜不足。\n不成欢笑不成哭。\n戏人目。\n远山蹙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2775, '逍遥乐', '黄庭坚', '春意渐归芳草。\n故国佳人，千里信沈音杳。\n雨润烟光，晚景澄明，极目危栏斜照。\n梦当年少。\n对樽前、上客邹枚，小鬟燕赵。\n共舞雪歌尘，醉里谈笑。\n花色枝枝争好。\n鬓丝年年渐老。\n如今遇风景，空瘦损、向谁道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2776, '离亭燕・离亭宴', '黄庭坚', '十载樽前谈笑。\n天禄故人年少。\n可是陆沈英俊地，看即锁窗批诏。\n此处忽相逢，潦倒秃翁同调。\n西顾郎官湖渺。\n事看庾楼人小。\n短艇绝江空怅望，寄得诗来高妙。\n梦去倚君傍，胡蝶归来清晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2777, '归田乐引・归田乐', '黄庭坚', '暮雨阶砌。\n漏渐移、转添寂寞，点点心如碎。\n怨你又恋你。\n恨你惜你。\n毕竟教人怎生是。\n前欢算未已。\n奈向如今愁无计。\n为伊聪俊，销得人憔悴。\n这里诮睡里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2778, '归田乐引・归田乐', '黄庭坚', '对景还销瘦。\n被个人、把人调戏，我也心儿有。\n忆我又唤我，见我嗔我，天生教人怎生受。\n看承幸厮勾。\n又是尊前眉峰皱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2779, '归田乐令・归田乐', '黄庭坚', '引调得、甚今日心肠不恋家。\n宁宁地、思量他，思量他。\n两情各自肯，甚忙咱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2780, '望远行', '黄庭坚', '自见来，虚过却、好时好日。\n这尿粘腻得处煞是律。\n据眼前言定，也有十分七八。\n冤我无心除告佛。\n管人闲底，且放我快活ヵ。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2781, '鼓笛令', '黄庭坚', '酒阑命友闲为戏。\n打揭儿、非常惬意。\n各自输赢只赌是。\n赏罚采、分明须记。\n小五出来无事。\n却跋翻和九底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2782, '鼓笛令', '黄庭坚', '宝犀未解心先透。\n恼杀人、远山微皱。\n意淡言疏情最厚。\n枉教作、著行官柳。\n小雨勒花时候。\n抱琵琶、为谁清瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2783, '鼓笛令', '黄庭坚', '见来两个宁宁地。\n眼厮打、过如拳踢。\n恰得尝些香甜底。\n苦杀人、遭谁调戏。\n腊月望州坡上地。\n冻著你、影村鬼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2784, '鼓笛令', '黄庭坚', '见来便觉情於我。\n厮守著、新来好过。\n人道他家有婆婆。\n与一口、管教磨。\n副靖传语木大。\n鼓儿里、且打一和。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2785, '好女儿', '黄庭坚', '春去几时还。\n问桃李无言。\n燕子归栖风劲，梨雪乱西园。\n唯有月婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2786, '好女儿', '黄庭坚', '粉泪一行行。\n啼破晓来妆。\n懒系酥胸罗带，羞见绣鸳鸯。\n拟待不思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2787, '采桑子', '黄庭坚', '虚堂密候参同火，梨枣枝繁。\n深锁三关。\n不要樊姬与小蛮。\n遥知风雨更阑夜，犹梦巫山。\n浓丽清闲。\n晓镜新梳十二鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2788, '采桑子', '黄庭坚', '投荒万里无归路，雪点鬓繁。\n度鬼门关。\n已拼儿童作楚蛮。\n黄云苦竹啼归去，绕荔枝山。\n蓬户身闲。\n歌板谁家教小鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2789, '采桑子', '黄庭坚', '樱桃著子如红豆，不管春归。\n闻道开时。\n蜂惹香须蝶惹衣。\n楼台灯火明珠翠，酒恋歌迷。\n醉玉东西。\n少个人人暖被携。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2790, '采桑子', '黄庭坚', '城南城北看桃李，依倚年华。\n杨柳藏鸦。\n又是无言落花。\n春风一面长含笑，偷顾羞遮。\n分付谁家。\n把酒花前试问他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2791, '丑奴儿・采桑子', '黄庭坚', '济楚好得些。\n憔悴损、都是因它。\n那回得句闲言语，傍人尽道，你管又还鬼那人。\n得过口儿嘛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2792, '菩萨蛮', '黄庭坚', '细腰宫外清明雨。\n云阳台上烟如缕。\n云雨暗巫山。\n流人殊未还。\n阿谁知此意。\n解遣双壶至。\n不是白头新。\n周郎旧可人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2793, '鹧鸪天', '黄庭坚', '塞雁初来秋影寒。\n霜林风过叶声乾。\n龙山落帽千年事，我对西风犹整冠。\n兰委佩，菊堪餐。\n人情时事半悲欢。\n但将酩酊酬佳节，更把茱萸仔细看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2794, '鹧鸪天', '黄庭坚', '节去蜂愁蝶不知。\n晓庭环绕折残枝。\n自然今日人心别，未必秋香一夜衰。\n无闲事，即芳期。\n菊花须插满头归。\n宜将酩酊酬佳节，不用登临送落晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2795, '鹧鸪天', '黄庭坚', '闻说君家有翠娥。\n施朱施粉总嫌多。\n背人语处藏珠履，得羞时整玉梭。\n拖远岫，压横波。\n何时传酒更传歌。\n为君写就黄庭了，不要山阴道士鹅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2796, '少年心', '黄庭坚', '对景惹起愁闷。\n染相思、病成方寸。\n是阿谁先有意，阿谁薄。\n斗顿恁、少喜多嗔。\n合下休传音问。\n你有我、我无你分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2797, '少年心', '黄庭坚', '心里人人，暂不见、霎时难过。\n天生你要憔悴我。\n把心头从前鬼，著手摩挲。\n抖擞了、百病销磨。\n见说那厮脾鳖热。\n大不成我便与拆破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2798, '点绛唇', '黄庭坚', '几日无书，举头欲问西来燕。\n世情梦幻。\n复作如斯观。\n自叹人生，分合常相半。\n戎虽远。\n念中相见。\n不托鱼和雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2799, '点绛唇', '黄庭坚', '罗带双垂，妙香长恁携纤手。\n半妆红豆。\n各自相思瘦。\n闻道伊家，终日眉儿皱。\n不能勾。\n泪珠轻溜。\n损揉蓝袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2800, '南乡子', '黄庭坚', '诸将说封侯。\n短笛长歌独倚楼。\n万事尽随风雨去，休休。\n戏马台南金络头。\n催酒莫迟留。\n酒味今秋似去秋。\n花向老人头上笑，羞羞。\n白发簪花不解愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2801, '南歌子', '黄庭坚', '槐绿低窗暗，榴红照眼明。\n玉人邀我少留行。\n无奈一帆烟雨、画船轻。\n柳叶随歌皱，梨花与泪倾。\n别时不似见时情。\n今夜月明江上、酒初醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2802, '更漏子', '黄庭坚', '体妖娆，鬟婀娜。\n玉甲银筝照座。\n危柱促，曲声残。\n王孙带笑看。\n休休休，莫莫莫。\n愁拨个丝中索。\n了了了，玄玄玄。\n山僧无碗禅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2803, '好事近', '黄庭坚', '歌罢酒阑时，潇洒座中风色。\n主礼到君须尽，奈宾朋南北。\n暂时分散总寻常，难堪久离拆。\n不似建溪春草，解留连佳客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2804, '好事近', '黄庭坚', '一弄醒心弦，情在两山斜叠。\n弹到古人愁处，有真珠承睫。\n使君来去本无心，休泪界红颊。\n自恨老来憎酒，负十分金叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2805, '好事近', '黄庭坚', '不见片时霎，魂梦镇相随著。\n因甚近新无据，误窃香深约。\n思量模样憎儿，恶又怎生恶。\n终待共伊相见，与佯佯奚落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2806, '喝火令', '黄庭坚', '见晚情如旧，交疏分已深。\n舞时歌处动人心。\n烟水数年魂梦，无处可追寻。\n昨夜灯前见，重题汉上襟。\n便愁云雨又难寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2807, '留春令', '黄庭坚', '江南一雁横秋水。\n叹咫尺、断行千里。\n回纹机上字纵横，欲寄远、凭谁是。\n谢客池塘春都未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2808, '宴桃源・如梦令', '黄庭坚', '天气把人。\n落絮游丝时候。\n茶饭可曾，镜中赢得销瘦。\n生受。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2809, '雪花飞', '黄庭坚', '携手青云路稳，天声迤逦传呼。\n袍笏恩章乍赐，春满皇都。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2810, '下水船', '黄庭坚', '总领神仙侣。\n齐到青云歧路。\n丹禁风微，咫尺谛闻天语。\n尽荣遇。\n看即如龙变化，一掷灵梭风雨。\n真游处。\n上苑寻春去。\n芳草芊芊迎步。\n几曲笙歌，樱桃艳里欢聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2811, '贺圣朝', '黄庭坚', '脱霜披茜初登第。\n名高得意。\n樱桃荣宴玉墀游，领群仙行缀。\n佳人何事轻相戏。\n道得之何济。\n君家声誉古无双，且均平居二。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2812, '青玉案', '黄庭坚', '烟中一线来时路。\n极目送、归鸿去。\n第四阳关云不度。\n山胡新啭，子规言语。\n正在人愁处。\n忧能损性休朝暮。\n忆我当年醉时句。\n渡水穿云心已许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2813, '沁园春', '黄庭坚', '把我身心，为伊烦恼，算天便知。\n恨一回相见，百方作计，未能偎倚，早觅东西。\n镜里拈花，水中捉月，觑著无由得近伊。\n添憔悴，镇花销翠减，玉瘦香肌。\n奴儿。\n又有行期。\n你去即无妨我共谁。\n向眼前常见，心犹未足，怎生禁得，真个分离。\n地角天涯，我随君去。\n掘井为盟无改移。\n君须是，做些儿相度，莫待临时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2814, '千秋岁', '黄庭坚', '苑边花外。\n记得同朝退。\n飞骑轧，鸣珂碎。\n齐歌云绕扇，赵舞风回带。\n岩鼓断，杯盘狼藉犹相对。\n洒泪谁能会。\n醉卧藤阴盖。\n人已去，词空在。\n兔园高宴悄，虎观英游改。\n重感慨，波涛万顷珠沈海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2815, '千秋岁', '黄庭坚', '世间好事。\n恰恁厮当对。\n乍夜永，凉天气。\n雨稀帘外滴，香篆盘中字。\n长入梦，如今见也分明是。\n欢极娇无力，玉软花坠。\n钗袖，云堆臂。\n灯斜明媚眼，汗浃瞢腾醉。\n奴奴睡，奴奴睡也奴奴睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2816, '河传', '黄庭坚', '心情老懒。\n对歌对舞，犹是当时眼。\n巧笑靓妆，近我衰容华鬓。\n似扶著、卖卜算。\n思量好个当年见。\n催酒催更，只怕归期短。\n饮散灯稀，背锁落花深院。\n好杀人、天不管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2817, '望江东', '黄庭坚', '江水西头隔烟树。\n望不见、江东路。\n思量只有梦来去。\n更不怕、江阑住。\n灯前写了书无数。\n算没个、人传与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2818, '桃源忆故人', '黄庭坚', '碧天露洗春容净。\n淡月晓收残晕。\n花上密烟飘尽。\n花底莺声嫩。\n云归楚峡厌厌困。\n两点遥山新恨。\n和泪暗弹红粉。\n生怕人来问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2819, '卜算子', '黄庭坚', '要见不得见，要近不得近。\n试问得君多少怜，管不解、多於恨。\n禁止不得泪，忍管不得闷。\n天上人间有底愁，向个里、都谙尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2820, '蝶恋花', '黄庭坚', '海角芳菲留不住。\n笔下风生，吹入青云去。\n仙籍有名天赐与。\n致君事业安排取。\n要识世间平坦路。\n当使人人，各有安身处。\n黑发便逢尧舜主。\n笑人白首耕南亩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2821, '浣溪沙', '黄庭坚', '飞鹊台前晕翠蛾。\n千金新买帝青螺。\n最难如意为情多。\n几处泪痕留醉袖，一春愁思近横波。\n远山低尽不成歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2822, '浣溪沙', '黄庭坚', '一叶扁舟卷画帘。\n老妻学饮伴清谈。\n人传诗句满江南。\n林下猿垂窥涤砚，岩前鹿卧看收帆。\n杜鹃声乱水如环。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2823, '诉衷情', '黄庭坚', '小桃灼灼柳。\n春色满江南。\n雨晴风暖烟淡，天气正醺酣。\n山泼黛，水蓝。\n翠相搀。\n歌楼酒旆，故故招人，权典青衫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2824, '诉衷情', '黄庭坚', '旋揎玉指著红靴。\n宛宛斗弯讹。\n天然自有殊态，供愁黛、不须多。\n分远岫，压横波。\n妙难过。\n自枕处，独倚阑时，不奈颦何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2825, '诉衷情', '黄庭坚', '珠帘绣幕卷轻霜。\n呵手试梅妆。\n都缘自有离恨，故画作、远山长。\n思往事，惜流光。\n恨难忘。\n未歌先敛，欲笑还颦，最断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2826, '昼夜乐', '黄庭坚', '夜深记得临歧语。\n说花时、归来去。\n教人每日思量，到处与谁分付。\n其奈冤家无定据。\n约云朝、又还雨暮。\n将泪入鸳衾，总不成行步。\n元来也解知思虑。\n一封书、深相许。\n情知玉帐堪欢，为向金门进取。\n直待腰金拖紫後，有夫人、县君相与。\n争奈会分疏，没嫌伊门路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2827, '一落索', '黄庭坚', '谁道秋来烟景素。\n任游人不顾。\n一番时态一番新，到得意、皆欢慕。\n紫萸黄菊繁华处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2828, '满庭芳', '黄庭坚', '风力驱寒，云容呈瑞，晓来到处花飞。\n遍装琼树，春意到南枝。\n便是渔蓑旧画，纶竿重、横玉低垂。\n今宵里，香闺邃馆，幽赏事偏宜。\n风流，金马客，歌鬟醉拥，乌帽斜。\n问人间何处，鹏运天池。\n且共周郎按曲，音微误、首已先回。\n同心事，丹山路稳，长伴彩鸾归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2829, '西江月', '黄庭坚', '细细风清撼竹，迟迟日暖开花。\n香帏深卧醉人家。\n媚语娇声娅姹。\n姹娅声娇语媚，家人醉卧深帏。\n香花开暖日迟迟。\n竹撼清风细细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2830, '失调名', '黄庭坚', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2831, '好事近', '黄庭坚', '潇洒荐冰盘，满座暗惊香集。\n久後一般风味，问几人知得。\n画堂饮散已归来，清润转更惜。\n留取酒醒时候，助茗瓯春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2832, '瑞鹤仙', '黄庭坚', '环滁皆山也。\n望蔚然深秀，琅琊山也。\n山行六七里，有翼然泉上，醉翁亭也。\n翁之乐也。\n得之心、寓之酒也。\n更野芳佳木，风高日出，景无穷也。\n游也。\n山肴野蔌，酒冽泉香，沸筹觥也。\n太守醉也。\n喧哗众宾欢也。\n况宴酣之乐、非丝非竹，太守乐其乐也。\n问当时、太守为谁，醉翁是也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2833, '蓦山溪', '黄庭坚', '朝来风日，陡觉春衫便。\n翠柳艳明眉，戏秋千、谁家倩盼。\n烟匀露洗，草色媚横塘，平沙软。\n雕轮转。\n行乐闻弦管。\n追思年少，走马寻芳伴。\n一醉几缠头，过扬州、珠帘尽卷。\n而今老矣，花似雾中看，欢喜浅。\n天涯远。\n信马归来晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2834, '捣练子', '黄庭坚', '梅凋粉，柳摇金。\n微雨轻风敛陌尘。\n厚约深盟何处诉，除非重见那人人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2835, '减字浣溪沙・浣溪沙', '贺铸', '浮动花钗影鬓烟。\n浅妆浓笑有馀妍。\n酒醺檀点语凭肩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2836, '减字浣溪沙・浣溪沙', '贺铸', '两点春山一寸波。\n当筵娇甚不成歌。\n动人情态可须多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2837, '减字浣溪沙・浣溪沙', '贺铸', '清浅陂塘藕叶乾。\n细风蔬雨鹭鸶寒。\n半垂帘幕倚阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2838, '减字浣溪沙・浣溪沙', '贺铸', '楼角初销一缕霞。\n淡黄杨柳暗栖鸦。\n玉人和月摘梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2839, '相思引', '贺铸', '团扇单衣杨柳陌。\n花似春风□无迹。\n赖白玉香奁供汾泽。\n借秀色。\n添春色。\n借秀色。\n添春色。\n云幕华灯张绮席。\n半醉客。\n留醒客。\n半醉客。\n留醒客。\n渐促膝倾鬟琴差拍。\n问此夕。\n知何夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2840, '天门谣', '贺铸', '牛渚天门险。\n限南北、七雄豪占。\n清雾敛。\n与闲人登览。\n待月上潮平波滟滟。\n塞管轻吹新阿滥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2841, '献金杯・厌金杯', '贺铸', '风软香迟，花深漏短。\n可怜宵、画堂春半。\n碧纱窗影，卷帐蜡灯红，鸳枕畔。\n密写乌丝一段。\n采苹溪晚。\n拾翠沙空，尽愁倚、梦云飞观。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2842, '清平乐', '贺铸', '阴晴未定。\n薄日烘云影。\n临水朱门花一径。\n尽日鸟啼人静。\n厌厌几许春情。\n可怜老去兰成。\n看取镊残双鬓，不随芳草重生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2843, '清平乐', '贺铸', '小桃初谢。\n双燕还来也。\n记得年时寒食下。\n紫陌青门游冶。\n楚城满目春华。\n可堪游子思家。\n惟有夜来归梦，不知身在天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2844, '摊破浣溪沙・山花子', '贺铸', '湖上秋深藕叶黄。\n清霜销瘦损垂杨。\n洲嘴嫩沙斜照暖，睡鸳鸯。\n红粉莲娃何处在，西风不为管馀香。\n今夜月明闻水调，断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2845, '摊破浣溪沙・山花子', '贺铸', '双凤箫声隔彩霞。\n朱门深闭七香车。\n何处探春寻旧约，谢娘家。\n旖旎细风飘水麝，玲珑残雪浸山茶。\n饮罢西厢帘影外，玉蟾斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2846, '惜双双・惜分飞', '贺铸', '皎镜平湖三十里。\n碧玉山围四际。\n莲荡香风里。\n彩鸳鸯觉双飞起。\n明月多情随舵尾。\n偏照空床翠被。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2847, '思越人・朝天子', '贺铸', '紫府东风放夜时。\n步莲李伴人归。\n五更钟动笙歌散，十里月明灯火稀。\n香苒苒，梦依依。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2848, '思越人・朝天子', '贺铸', '怊怅离亭断采襟。\n碧云明月两关心。\n几行书尾情何限，一尺裙腰瘦不禁。\n遥夜半，曲房深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2849, '鹤冲天', '贺铸', '冬冬鼓动，花外沈残漏。\n华月万枝灯，还清昼。\n广陌衣香度，飞盖影、相先後。\n个处频回首。\n锦房西去，期约武陵西口。\n当时早恨欢难偶。\n可堪流浪远，分携久。\n小畹兰英在，轻付与、何人手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2850, '小重山', '贺铸', '飘径梅英雪未融。\n芳菲消息到，杏梢红。\n隔年欢事水西东。\n凝思久，不语坐书空。\n回想夹城中。\n采山箫鼓沸，绮罗丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2851, '六州歌头', '贺铸', '少年侠气，交结五都雄。\n肝胆洞。\n毛发耸。\n立谈中。\n死生同。\n一诺千金重。\n推翘勇。\n衿豪踪。\n轻盖拥。\n聊飞。\n斗城东。\n轰饮酒炉，春色浮寒瓮。\n吸海垂虹。\n闲呼鹰嗾犬，白羽摘雕弓。\n狡穴俄空。\n乐匆匆。\n似黄粱梦。\n辞丹凤。\n明月共。\n漾孤篷。\n官冗从。\n怀倥偬。\n落尘笼。\n薄书从。\n弁如云众。\n共粗用。\n忽奇功。\n笳鼓动。\n渔阳弄。\n思悲翁。\n不请长缨，系取天娇种。\n剑吼西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2852, '浣溪沙', '贺铸', '翠参差拂水风。\n暖云如絮扑低空。\n丽人波脸觉春融。\n缨挂宝钗初促席，檀高微注玉杯红。\n芳醪何似此情浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2853, '浣溪沙', '贺铸', '云母窗前歇绣针。\n低鬟凝思坐调琴。\n玉纤纤按十三金。\n归卧文园犹带酒，柳花飞度画堂阴。\n只凭双燕话春心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2854, '浣溪沙', '贺铸', '叠鼓新歌百样娇。\n铜丸玉腕促云谣。\n揭帘飞瓦雹声焦。\n九渠池边杨柳陌，香轮轧轧马箫箫。\n细风妆面酒痕销。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2855, '江城子', '贺铸', '麝熏微度绣芙蓉。\n翠衾重。\n画堂空。\n前夜偷期，相见却匆匆。\n心事两知何处问，依约是，梦中逢。\n坐疑行听竹窗风。\n出帘栊。\n杳无踪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2856, '浪淘沙', '贺铸', '一叶忽惊秋。\n分付东流。\n殷勤为过白苹洲。\n洲上小楼帘半卷，应认归舟。\n回首恋朋游。\n迹去心留。\n歌尘萧散梦云收。\n惟有尊前曾见月，相伴人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2857, '木兰花・玉楼春', '贺铸', '佩环声认腰肢软。\n风里麝熏知近远。\n此身常羡玉妆台，得见晓来梳画面。\n回廊几步通深院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2858, '木兰花・玉楼春', '贺铸', '银黄雁柱香檀拨。\n镂板三声催细抹。\n舞腰轻怯绛裙长，羞按筑球花十八。\n东城柳岸匆匆发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2859, '蝶恋花', '贺铸', '小院朱扉开一扇。\n内样新妆，镜里分明见。\n眉晕半深唇注浅。\n朵云冠子偏宜面。\n被掩芙蓉熏麝煎。\n帘影沈沈，祗有双飞燕。\n心事向人犹腼腆。\n强来窗下寻针线。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2860, '石州引・石州慢', '贺铸', '薄雨初寒，斜照弄晴，春意空阔。\n长亭柳色缠黄，远客一枝先折。\n烟横水际，映带几点归鸦，东风销尽龙沙雪。\n还记初关来，恰而今时节。\n将发。\n画楼芳酒，红泪清歌，顿成清别。\n已是经年，杳杳音尘多绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2861, '失调名', '贺铸', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2862, '失调名', '贺铸', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2863, '减字木兰花', '贺铸', '簪花照镜。\n客鬓萧萧都不整。\n拟倩东□。\n化作尊前如梦云。\n风香月影。\n信是瑶台清夜永。\n深闭重门。\n牵绊刘郎别後魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2864, '凤栖梧・蝶恋花', '贺铸', '为问宛溪桥畔柳。\n拂水倡条，几赠行人手。\n一样叶眉偏解皱。\n白绵飞尽因谁瘦。\n今日离亭还对酒。\n唱断青青，好去休回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2865, '南柯子・南歌子', '贺铸', '斗酒才供泪，扁舟只载愁。\n画桥青柳小朱楼。\n犹记出城车马、为迟留。\n有恨花空委，无情水自流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2866, '望湘人', '贺铸', '厌莺声到枕，花气动帘，醉魂愁梦相半。\n被惜馀薰，带惊剩眼。\n几许伤春春晚。\n泪竹痕鲜，佩兰香老，湘天浓暖。\n记小江、风月佳时，屡约非烟游伴。\n须信鸾弦易断。\n奈云和再鼓，曲终人远。\n认罗袜无踪，旧处弄波清浅。\n青翰棹舣，白苹洲畔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2867, '谒金门', '贺铸', '杨花落。\n燕子横川朱阁。\n常恨春醪如水薄。\n闲愁无处著。\n绿野带江山络角。\n桃叶参差前约。\n历历短樯沙外泊。\n东风晚来恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2868, '蝶恋花', '贺铸', '几许伤春春复暮。\n杨柳清阴，偏碍游丝度。\n天际小山桃叶步。\n白苹花满湔裙处。\n竟日微吟长短句。\n帘影灯昏，心寄胡琴语。\n数点雨声风约住。\n朦胧淡月云来去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2869, '小梅花・梅花引', '贺铸', '思前别。\n记时节。\n美人颜色如花发。\n美人归。\n天一涯。\n娟娟娥，三五满还亏。\n翠眉蝉鬓生离诀。\n遥望青楼心欲绝。\n梦中寻。\n卧巫云。\n觉来珠泪，滴向湘水深。\n愁无已。\n奏绿绮。\n历历高山与流水。\n妙通神。\n觉知音。\n不知暮雨朝云、何山岑。\n相思无计堪可比。\n珠箔雕阑集千里。\n漏将分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2870, '乌啼月・乌夜啼', '贺铸', '牛女相望处，星桥不碍东西。\n重墙未抵蓬山远，却恨画楼低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2871, '簇水近', '贺铸', '一笛清风弄袖，新月梳云缕。\n澄凉夜色，缠过几点黄昏雨。\n侠少朋游，正喜九陌消尘土。\n鞭穗袅、紫骝花步。\n过朱户。\n认得宫妆，为谁重扫新眉妩。\n徘徊片响难问，桃李都无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2872, '画眉郎・好女儿', '贺铸', '雪絮雕章。\n梅粉华妆。\n小芒台、榧机罗湘素，鼓铜蟾砚滴，金雕琴写，玉燕钗梁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2873, '试周郎・诉衷情', '贺铸', '乔家深闭郁金堂。\n朝镜事梅妆。\n云鬟翠钿浮动，微步拥钗梁。\n情尚秘，色犹庄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2874, '新念别・夜游宫', '贺铸', '湖上兰舟暮发。\n扬州梦断灯明灭。\n想见琼花开似雪。\n帽檐香，玉纤纤，曾为折。\n渔管吹还咽。\n问何意、煎人愁绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2875, '谒金门', '贺铸', '溪声急。\n无数落花漂出。\n燕子分泥蜂酿蜜。\n迟迟艳风日。\n须信芳菲随失。\n况复佳期难必。\n拟把此情书万一。\n愁多翻阁笔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2876, '减字木兰花', '贺铸', '冷香浮动。\n望处欲声胡蝶梦。\n晓日。\n愁见凝酥暖渐融。\n鼓催歌送。\n芳酒一尊谁与共。\n寂寞墙东。\n门掩黄昏满院风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2877, '摊破浣溪沙・山花子', '贺铸', '锦鞯未弦瑟瑟徽。\n玉纤新拟凤双飞。\n缥缈烛烟花暮暗，就更衣。\n约略整环钗影动，迟回顾步佩声微。\n宛是春风胡蝶舞，带香归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2878, '瑶台第一层', '赵仲御', '管声催。\n人报道、嫦娥步月来。\n凤灯鸾矩，寒轻廉箔，光泛楼台。\n万年春未老，更帝乡日月蓬莱。\n从仙仗，看星河银界，锦绣天街。\n欢陪。\n千官万骑，九霄人在五云堆。\n紫袍光里，星球宛转，花影徘徊。\n未央宫漏水，散异香、龙阙崔嵬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2879, '蓦山溪', '仲殊', '清江平淡，疏雨和烟染。\n春在广寒宫，付江梅、先开素艳。\n年年第一，相见越溪东，云体态，雪精神，不把年华占。\n山亭水榭，别恨多销黯。\n又是主人来，更不辜、香心一点。\n题诗才思，清似玉壶冰，轻回顾，落尊前，桃杏声华减。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2880, '鹊踏枝・蝶恋花', '仲殊', '斜日平山寒已薄。\n雪过松梢，犹有残英落。\n晚色际天天似幕。\n一尊先与东风约。\n邀得红梅同宴乐。\n酒面融春，春满纤纤萼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2881, '点绛唇', '仲殊', '春遇瑶池，长空飞下残英片。\n素光围练。\n寒透笙歌院。\n莫把寿阳，妆信传书箭。\n掩香面。\n汉宫寻遍。\n月里还相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2882, '南歌子', '仲殊', '十里青山远，潮平陆带沙。\n数声啼鸟怨年华。\n又是凄凉时候、在天涯。\n白露收残暑，清风衬晚霞。\n绿杨堤畔闹荷花。\n记得年时沽酒、那人家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2883, '减字木兰花', '仲殊', '谁将妙笔。\n写就素缣三百匹。\n天下应无。\n此是钱塘江上图。\n一般奇绝。\n云淡天低秋夜月。\n费尽丹青。\n只这些儿画不成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2884, '减字木兰花', '仲殊', '江南三月。\n犹有枝头千点雪。\n邀上芳尊。\n却占东君一半春。\n尊前眼底。\n南国风光都在此。\n移过江来。\n从此江南不复开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2885, '南歌子', '仲殊', '解舞清平乐，如今说向谁。\n红炉片雪上钳锤。\n打就金毛狮子、也堪疑。\n木女明开眼，泥人暗皱眉。\n蟠桃已是著花迟。\n不向春风一笑、待何时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2886, '踏莎行', '仲殊', '浓润侵衣，暗香飘砌。\n雨中花色添憔悴。\n凤鞋湿透立多时，不言不语厌厌地。\n眉上新愁，手中文字。\n因何不倩鳞鸿寄。\n想伊只诉薄情人，官中谁管闲公事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2887, '金蕉叶', '仲殊', '丛霄逸韵祥烟渺。\n摇金翠、玲珑三岛。\n地控全吴，山横旧楚春来早。\n千里断云芳草。\n六朝遗恨连江表。\n都分付、倚楼吟啸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2888, '定风波', '仲殊', '花戟云幡拥上方。\n画帘风细度春香。\n银色界前多远景。\n人静。\n铁城西面又斜阳。\n山色入江流不尽，古今一梦莫思量。\n故里无家归去懒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2889, '蝶恋花', '仲殊', '北固山前波浪远。\n铁瓮城头，画角残声短。\n促酒溅金催小宴。\n灯摇蜡焰香风软。\n落日烟霞晴满眼。\n欲仗丹青，巧笔彤牙管。\n解写伊川山色浅。\n谁能画得江天晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2890, '南徐好', '仲殊', '南徐好，鼓角乱云中。\n金地浮山星雨点，铁城横锁瓮三重。\n开国旧夸雄。\n春过後，佳气荡晴空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2891, '南徐好', '仲殊', '南徐好，城里小花山。\n淡薄融香松滴露，萧疏笼翠竹生烟。\n风月共闲闲。\n金晕暗，灯火小红莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2892, '南徐好', '仲殊', '南徐好，桥下渌波平。\n画柱千年尝有鹤，垂杨三月未闻莺。\n行乐过清明。\n南北岸，花市管弦声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2893, '南徐好', '仲殊', '南徐好，溪上百花堆。\n宴罢歌声随水去，梦回春色入门来。\n芳草遍池台。\n文彩动，奎璧烂昭回。\n玉殿仪刑推旧德。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2894, '南徐好', '仲殊', '南徐好，春坞锁池亭。\n山送云来长入梦，水浮花去不知名。\n烟草上东城。\n歌榭外，杨柳晚青青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2895, '南徐好', '仲殊', '南徐好，多景在楼前。\n京口万家寒食日，淮南千里夕阳天。\n天际几重山。\n莺啼处，人倚画阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2896, '南徐好', '仲殊', '南徐好，浮玉旧花宫。\n琢破琉璃闲世界，化城楼阁在虚空。\n香雾锁重重。\n天共水，高下混相通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2897, '南徐好', '仲殊', '南徐好，樽酒上西楼。\n调鼎勋庸还世事，镇江旌节从仙游。\n楼下水空流。\n桃李在，花月更悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2898, '南徐好', '仲殊', '南徐好，桥下绿杨村。\n两谢风流称郡守，二苏家世作州民。\n文彩动星辰。\n书万卷，今日富儿孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2899, '南徐好', '仲殊', '南徐好，直下控淮津。\n山放凝云低凤翅，潮生轻浪卷龙鳞。\n清洗古今愁。\n天尽处，风水接西滨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2900, '失调名', '仲殊', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2901, '念奴娇', '仲殊', '水枫叶下，乍湖光清浅。\n凉生商素。\n西帝宸游罗翠盖，拥出三千宫女。\n绛采娇春，铅华掩昼，占断鸳鸯浦。\n歌声摇曳，浣沙人在何处。\n别岸孤袅一枝，广寒宫殿，冷落栖愁苦。\n雪艳冰肌羞淡泊，偷把胭脂匀注。\n媚脸笼霞，芳心泣露，不肯为云雨。\n金波影里，为谁长恁凝伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2902, '蓦山溪', '仲殊', '年芳已远，凉夏疏疏雨。\n菊占此时开，背佳期、清秋何处。\n滴成金豆，弹破栗文圆，临水槛，倚风亭，全胜东篱暮。\n茱萸未结，谁是多情侣。\n菖叶与葵花，也相饶、也□羞妒。\n主人著意，何必念登高，浮酒面，解烦襟，消尽当筵暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2903, '减字木兰花', '仲殊', '青条绿叶。\n结起蓬瀛连万叠。\n风引飘飘。\n下有红波引六鳌。\n五城烟敛。\n剪碎采云红点点。\n帖在山腰。\n旁有斑斑雪未消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2904, '浣溪沙', '仲殊', '楚客才华为发扬。\n深林著意不相忘。\n梦成燕国正芬芳。\n莫把品名闲议拟，且看青凤羽毛长。\n十分领取面前香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2905, '醉花阴', '仲殊', '轻红蔓引丝多少。\n剪青兰叶巧。\n人向月中归，留下星钿，弹破真珠小。\n等闲不管春知道。\n多著绣帘围绕。\n只恐被东风，偷得馀香，分付闲花草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2906, '西江月', '仲殊', '味过华林芳蒂，色兼阳井沈朱。\n轻匀绛蜡裹团酥。\n不比人间甘露。\n神鼎十分火枣，龙盘三寸红珠。\n清含冰蜜洗云腴。\n只恐身轻飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2907, '玉楼春', '仲殊', '飞香漠漠帘帷暖。\n一线水沈烟未断。\n红楼西畔小阑干，尽日倚阑人已远。\n黄梅雨入芭蕉晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2908, '虞美人', '仲殊', '一番雨过年芳浅。\n袅袅心情懒。\n章台人过马嘶声。\n小眉不盏恨盈盈。\n怨清明。\n烟柔露软湖东岸。\n恼乱春风惯。\n一声莺是故园莺。\n及至如今□闻处、又多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2909, '蓦山溪', '仲殊', '黄金线软，玉露声轻润。\n青头破出芽，拂烟痕、一枝犹嫩。\n东风著意，不放舞间□，春渐暖，柔无力，依依怨和□。\n旗亭带晚，又是清明近。\n惹尽别离愁，约啼莺、深深与问。\n灞陵伤感，那更入阳关，扳折处，我无心，行人自多恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2910, '诉衷情', '仲殊', '楚江南岸小青楼。\n楼前人舟。\n别来後庭花晚，花上梦悠悠。\n山不断，水空流，漫凝眸。\n建康宫殿，燕子来时，多少闲愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2911, '诉衷情', '仲殊', '锺山影里看楼台。\n江烟晚翠开。\n六朝旧时明月，清夜满秦淮。\n寂寞处，两潮回。\n黯愁怀。\n汀花雨细，水树风闲，又是秋来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2912, '诉衷情', '仲殊', '清波门外拥轻衣。\n杨花相送飞。\n西湖又还春晚，水树乱莺啼。\n闲院宇，小帘帏。\n晚初归。\n钟声已过，篆香才点，月到门时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2913, '诉衷情', '仲殊', '长桥春水拍堤沙。\n疏雨带残霞。\n几声脆管何处，桥下有人家。\n宫树绿，晚烟斜。\n噪闲鸦。\n山光无尽，水风长在，满面杨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2914, '诉衷情', '仲殊', '涌金门外小瀛洲。\n寒食更风流。\n红船满湖歌吹，花外有高楼。\n晴日暖，淡烟浮。\n恣嬉游。\n三千粉黛，十二阑干，一片云头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2915, '蝶恋花', '仲殊', '开到杏花寒食近。\n人在花前，宿酒和春困。\n酒有尽时情不尽。\n日长只恁厌厌闷。\n经岁别离闲与问。\n花上啼莺，解道深深恨。\n可惜断云无定准。\n不能为寄蓝桥信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2916, '柳梢青', '仲殊', '岸草平沙。\n吴王故苑，柳袅烟斜。\n雨後寒轻，风前香软，春在梨花。\n行人一棹天涯。\n酒醒处，残阳乱鸦。\n门外秋千，墙头红粉，深院谁家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2917, '夏云峰', '仲殊', '天阔云高，溪横水远。\n晚日寒生轻晕。\n闲阶静、杨花渐少，朱门掩、莺声犹嫩。\n悔匆匆、过却清明，旋占得馀芳，已成幽恨。\n都几日阴沈，连宵慵困。\n起来韶华都尽。\n怨入双眉闲斗损。\n乍品得情怀，看承全近。\n深深态、无非自许。\n厌厌意、终羞人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2918, '望江南・忆江南', '仲殊', '成都好，蚕市趁遨游。\n夜放笙歌喧紫陌，春遨灯火上高楼。\n车马溢瀛洲。\n人散後，茧馆喜绸缪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2919, '失调名', '仲殊', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2920, '失调名', '仲殊', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2921, '失调名', '仲殊', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2922, '失调名', '仲殊', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2923, '失调名', '仲殊', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2924, '失调名', '仲殊', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2925, '望江南・忆江南', '仲殊', '成都好，药市晏游闲。\n步出五门鸣剑佩，别登三岛看神仙。\n缥缈结灵烟。\n云影里，歌吹暖霜天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2926, '南柯子・南歌子', '仲殊', '金蟠龙尾，莲开舞凤头。\n凉生宫殿不因秋。\n门外莫寻尘世，卷地江流。\n霁色澄千里，潮声带两洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2927, '减字木兰花', '仲殊', '山阴道士。\n鹤目龟趺多秀气。\n右领将军。\n萧散精神一片云。\n东山太傅。\n落落龙骧兼虎步。\n潦倒支公。\n穷骨零丁少道风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2928, '念奴娇', '仲殊', '故园避暑，爱繁阴翳日，流霞供酌。\n竹影筛金泉漱玉，红映微花帘箔。\n素质生风，香肌无汗，绣扇长闲却。\n双鸾栖处，绿筠时下风箨。\n吹断舞影歌声，阳台人去，有当年池阁。\n佩结兰英凝念久，言语精神依约。\n燕别雕梁，归鸿紫塞，音信凭谁托。\n争知好景，为君长是萧索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2929, '惜双双・惜分飞', '仲殊', '瘐领香前亲写得。\n子细看，粉匀无迹。\n月殿休寻觅。\n姑射人来，知是曾相识。\n不要青春闲用力。\n也曾寄、江南信息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2930, '洞仙歌', '仲殊', '广寒晓驾，姑射寻仙侣。\n偷被霜华送将去。\n过越岭、栖息南枝，匀妆面、凝酥轻聚。\n爱横管、孤度陇头声，尽拼得幽香，为君分付。\n水亭山驿，衰草斜阳，无限行人断肠处。\n尽为我、留得多情，何须待、春风相顾。\n任倒断、深思向梨花，也无奈寒食，几番春雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2931, '楚宫春慢', '仲殊', '轻盈绛雪。\n乍团聚同心，千点珠结。\n画馆绣幄低飞，融融香彻。\n笑里精神放纵，断未许、年华偷歇。\n信任芳春都不管，淅淅南熏，别是一家风月。\n扁舟去後，回望处、娃宫凄凉凝咽。\n身似断云零落，深心难说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2932, '如梦令', '吕本中', '海雁桥边春苦。\n几见落花飞絮。\n重到柳行西，懒问画楼何处。\n凝伫。\n凝伫。\n十顷荷花风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2933, '宣州竹・虞美人', '吕本中', '小溪篷底湖风重。\n吹破凝酥动。\n一枝斜映庾门深。\n冷淡无言香泛、月华清。\n已经轻瘦谁为共。\n魂绕徐熙□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2934, '临江仙', '毕良史', '霜月穿帘乍白，苹风入坐偏凉。\n麾灯促席诧时光。\n桃花歌扇小，杨柳舞衫长。\n别乘平分风月，词人剩引觥觞。\n莫将幽恨搅刚肠。\n尽添金掌露，频注玉猊香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2935, '好事近', '毕良史', '高会罢飞觞。\n方锦再移珍席。\n雷鼎乍烹甘液，试问侯苍璧。\n翠虬宝钏捧殷勤，明灭粲金碧。\n宾主放怀谈笑，满华堂春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2936, '小重山', '沈晦', '湖上秋来莲荡空。\n年华都付与，木芙蓉。\n采菱舟子两相逢。\n双媚靥，一笑与谁浓。\n斜日落溟。\n鸳鸯飞起处，水无踪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2937, '点绛唇', '郭章', '翠柏丹崖，碧云深锁神仙府。\n势盘龙虎。\n楼观雄中土。\n我欲停时，又恐斜阳暮。\n黄尘路。\n客怀良苦。\n满目西山雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2938, '酹江月・念奴娇', '胡世将', '神州沈陆，问谁是、一范一韩人物。\n北望长安应不见，抛却关西半壁。\n塞马晨嘶，胡笳夕引，赢得头如雪。\n三秦往事，只数汉家三杰。\n试看百二山河，奈君门万里，六师不发。\n阃外何人回首处，铁骑千群都灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2939, '蝶恋花', '赵鼎', '一朵江梅春带雪。\n玉软云娇，姑射肌肤洁。\n照影凌波微步怯。\n暗香浮动黄昏月。\n谩道广平心似铁。\n词赋风流，不尽愁千结。\n望断江南音信绝。\n陇头行客空情切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2940, '蝶恋花', '赵鼎', '尽日东风吹绿树。\n向晚轻寒，数点催花雨。\n年少凄凉天付与。\n更堪春思萦离绪。\n临水高楼携酒处。\n曾倚哀弦，歌断黄金缕。\n楼下水流何处去。\n凭栏目送苍烟暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2941, '虞美人', '赵鼎', '魂消目断关山路。\n曾送雕鞍去。\n而今留滞古陪京。\n还是一尊芳酒、送君行。\n吾庐好在条山曲。\n三径应芜没。\n诛茅为我补东篱。\n会待新春残腊、也来归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2942, '怨春风・一斛珠', '赵鼎', '宝鉴菱花莹。\n孤鸾慵照影。\n鱼书蝶梦两浮沉，恨恨恨。\n结尽丁香，瘦如杨柳，雨疏云冷。\n宿醉厌厌病。\n罗巾空泪粉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2943, '点绛唇', '赵鼎', '香冷金炉，梦回鸳帐馀香嫩。\n更无人问。\n一枕江南恨。\n消瘦休文，顿觉春衫褪。\n清明近。\n杏花吹尽。\n薄暮东风紧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2944, '人月圆', '赵鼎', '连环宝瑟深深愿，结尽一生愁。\n人间天上，佳期胜赏，今夜中秋。\n雅歌妍态，嫦娥见了，应羡风流。\n芳尊美酒，年年岁岁，月满高楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2945, '河传', '赵鼎', '年年桃李。\n渺关河一梦，飞花空委。\n鸿去燕来，锦字参差难寄。\n敛双眉、山对起。\n娇波泪落妆如洗。\n独倚高楼，日日春风里。\n江水际。\n天色无情，似送离怀千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2946, '燕归梁', '赵鼎', '绰约彤霞降紫霄。\n是仙子风标。\n湘裙明佩响琼瑶。\n散馥郁、暗香飘。\n小春十月寒犹浅，妆粉弄梅梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2947, '减字木兰花', '赵鼎', '笔端红翠。\n造化工夫春有意。\n云梦涵胸。\n好去蓬山十二重。\n天街追骑。\n催唤谪仙泥样醉。\n电扫云空。\n百斛明珠咳唾中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2948, '好事近', '赵鼎', '兰烛画堂深，歌吹已终瑶席。\n碾破密云金缕，送蓬莱归客。\n看看宣诏未央宫，草诏侍宸极。\n拜赐一杯甘露，泛天边春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2949, '贺圣朝', '赵鼎', '断霞收尽黄昏雨。\n滴梧桐疏树。\n帘栊不卷夜沈沈，锁一庭风露。\n天涯人远，心期梦悄，苦长宵难度。\n知他窗外促织儿，有许多言语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2950, '乌夜啼', '赵鼎', '檐花点滴秋清。\n寸心惊。\n香断一炉沈水、一灯青。\n凉宵永。\n孤衾冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2951, '浣溪沙', '赵鼎', '艳艳春娇入眼波。\n劝人金盏缓声歌。\n不禁粉泪香罗。\n暮雨朝云相见少，落花流水别离多。\n寸肠争奈此情何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2952, '画堂春', '赵鼎', '空笼帘影隔垂杨。\n梦回芳草池塘。\n杏花枝上蝶双双。\n春昼初长。\n强理云鬟临照，暗弹粉泪沾裳。\n自怜容艳惜流光。\n无限思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2953, '浪淘沙', '赵鼎', '归计信悠悠。\n归去谁留。\n梦随江水绕沙洲。\n沙上孤鸿犹笑我，萍梗飘流。\n与世且沈浮。\n要便归休。\n一杯消尽一生愁。\n傥有人来闲论事，我会摇头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2954, '水调歌头', '赵鼎', '屋下疏流水，屋上列青山。\n先生跨鹤何处，窈窕白云间。\n采药当年三径，只有长松绿竹，霜吹晚萧然。\n举酒高台上，彷佛揖群仙。\n转银汉，飞宝鉴，溢清寒。\n金波万顷不动，人在玉壶宽。\n我唱君须起舞，要把嫦娥留住，相送一杯残。\n醉矣拂衣去，一笑渺人寰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2955, '双翠羽', '赵鼎', '小园曲径，度疏林深处，幽兰微馥。\n竹坞无人双翠羽，飞触珊珊寒玉。\n更欲题诗，晚来孤兴，却恐伤幽独。\n不如花下，一尊芳酒相属。\n慨念故国风流，杨花春梦短，黄粱初熟。\n卷白千觞须劝我，洗此胸中荣辱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2956, '河传', '赵鼎', '秋光向晚。\n叹羁游坐见。\n年华将换。\n一纸素书，拟托南来征雁。\n奈雪深、天更远。\n东窗皓月今宵满。\n浅酌芳尊，暂倩嫦娥伴。\n应念夜长，旅枕孤衾不暖。\n便莫教、清影转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2957, '满江红', '赵鼎', '惨结秋阴，西风送、霏霏雨湿。\n凄望眼、征鸿几字，暮投沙碛。\n试问乡关何处是，水云浩荡迷南北。\n但一抹、寒青有无中，遥山色。\n天涯路，江上客。\n肠欲断，头应白。\n空搔首兴欢，暮年离拆。\n须信道消忧除是酒，奈酒行有尽情无极。\n便挽取、长江入尊，浇胸臆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2958, '鹧鸪天', '赵鼎', '客路那知岁序移。\n忽惊春到小桃枝。\n天涯海角悲凉地，记得当年全盛时。\n花弄影，月流辉。\n水精宫殿五云飞。\n分明一觉华胥梦，回首东风泪满衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2959, '浣溪沙', '赵鼎', '惜别怀归老不禁。\n一年春事柳阴阴。\n日下长安何处是，碧云深。\n已恨梅花疏远信，休传桃叶怨遗音。\n一醉东风分首去，两惊心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2960, '如梦令', '赵鼎', '烟雨满江风细。\n江上危楼独倚。\n歌罢楚云空，楼下依前流水。\n迢递。\n迢递。\n目送孤鸿千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2961, '好事近', '赵鼎', '杨柳曲江头，曾记彩舟良夕。\n一枕楚台残梦，似行云无迹。\n青山迢递水悠悠，何处问消息。\n还是一年春暮，倚东风独立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2962, '点绛唇', '赵鼎', '惜别伤离，此生此念无重数。\n故人何处。\n还送春归去。\n美酒一杯，谁解歌金缕。\n无情绪。\n淡烟疏雨。\n花落空庭暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2963, '相思令・相思儿令', '赵鼎', '归去来。\n归去来。\n昨夜东风吹梦回。\n家山安在哉。\n酒一杯。\n复一杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2964, '望海潮', '赵鼎', '双峰遥促，回波奔注，茫茫溅雨飞沙。\n霜凛剑戈，风生阵马，如闻万鼓齐挝。\n儿戏笑夫差。\n漫水犀强弩，一战鱼虾。\n依旧群龙，怒卷银汉下天涯。\n雷驱电炽雄夸。\n似云垂鹏背，雪喷鲸牙。\n须臾变灭，天容水色，琼田万顷无瑕。\n俗眼但惊嗟。\n试望中彷佛，三岛烟霞。\n旧隐依然，几时归去泛灵槎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2965, '花心动', '赵鼎', '江月初升，听悲风、萧瑟满山零叶。\n夜久酒阑，火冷灯青，奈此愁怀千结。\n绿琴三叹朱弦绝，与谁唱、阳春白雪。\n但遐想、穷年坐对，断编遗册。\n西北搀枪未灭。\n千万乡关，梦遥吴越。\n慨念少年，横槊风流，醉瞻海涵天阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2966, '洞仙歌', '赵鼎', '空山雨过，月色浮新酿。\n把盏无人共心赏。\n漫悲吟、独自拈断霜须，还就寝、秋入孤衾渐爽。\n可怜窗外竹，不怕西风，一夜潇潇弄疏响。\n奈此九回肠，万斛清愁，人何处、邈如天样。\n纵陇水、秦云阻归音，便不许时闲，梦中寻访。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2967, '乌夜啼', '赵鼎', '雨馀风露凄然。\n月流天。\n还是年时今夜、照关山。\n收别泪。\n持杯起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2968, '满庭芳', '赵鼎', '靡靡流光，凄凄风露，小园草木初凋。\n杳然尘影，爽气界天高。\n爱此佳名重九，随宜对、秋菊持醪。\n登临处，哀蝉断响，燕雁度云霄。\n闲谣。\n情缅邈，相寻万化，人世徒劳。\n念胸中百虑，何物能消。\n欲致颓龄不老，和金茎、一醉陶陶。\n君休问，千年事往，聊与永今朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2969, '好事近', '赵鼎', '春色遍天涯，寒谷未知消息。\n且共一尊芳酒，看东风飞雪。\n太平遗老洞霄翁，相对两华发。\n一任醉魂飞去，访琼瑶宫阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2970, '好事近', '赵鼎', '羁旅转飞蓬，投老未知休息。\n却念故园春事，舞残红飞雪。\n危楼高处望天涯，云海寄穷发。\n只有旧时凉月，照清伊双阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2971, '好事近', '赵鼎', '一炷鼻端香，方寸浪平风息。\n汲取玉池春水，点红炉微雪。\n年来都以酒相妨，进退只毫发。\n却道醉乡深处，是三山神阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2972, '好事近', '赵鼎', '烟雾锁青冥，直上九关一息。\n姑射有人相挽，莹肌肤冰雪。\n骑鲸却下大荒来，天风乱吹发。\n慨念故人非是，漫尘埃城阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2973, '少年游', '赵鼎', '三月正当三十日，愁杀醉吟翁。\n可奈青春，太无情甚，归去苦匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2974, '贺圣朝', '赵鼎', '花光烛影春容媚。\n香生和气。\n纷纷儿女拜翁前，劝犀尊金醴。\n凌烟图画，王侯富贵，非翁雅意。\n愿翁早早乞身归，对青山沈醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2975, '贺圣朝', '赵鼎', '征鞍南去天涯路。\n青山无数。\n更堪月下子规啼，向深山深处。\n凄然推枕，难寻新梦，忍听伊言语。\n更阑人静一声声，道不如归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2976, '醉蓬莱', '赵鼎', '破新正春到，五叶尧，弄芳初秀。\n翦彩然膏，灿华筵如昼。\n家庆图中，老莱堂上，竟祝翁遐寿。\n喜气欢容，光生玉，香霏金兽。\n谁会高情，淡然声利，一笑尘寰，万缘何有。\n解组归来，访渔樵朋友。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2977, '小重山', '赵鼎', '漠漠晴霓和雨收。\n长波千万里，拍天流。\n云帆烟棹去悠悠。\n西风里，归兴满沧州。\n谩道醉忘忧。\n荡高怀远恨，更悲秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2978, '惜双双・惜分飞', '赵鼎', '度陇信音谁与寄。\n肠断江南千里。\n深雪前村里。\n一枝昨夜传芳意。\n冷蕊暗香空旖旎。\n也应是、春来憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2979, '西江月', '赵鼎', '世态浮云易变，时光飞箭难留。\n五年重见海东头。\n只有交情似旧。\n未尽别来深意，难堪老去离愁。\n青山迢递水悠悠。\n明日扁舟病酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2980, '行香子', '赵鼎', '草色芊绵。\n雨点阑斑。\n糁飞花、还是春残。\n天涯万里，海上三年。\n试倚危楼，将远恨，卷帘看。\n举头见日，不见长安。\n谩凝眸、老泪凄然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2981, '醉桃园・桃源忆故人', '赵鼎', '青春不与花为主。\n花正开时春暮。\n花下醉眠休诉。\n看取春归去。\n莺愁蝶怨春知否。\n欲问春归何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2982, '浪淘沙', '赵鼎', '霜露日凄凉。\n北雁南翔。\n惊风吹起不成行。\n吊影苍波何限恨，日暮天长。\n为尔惜流光。\n还是重阳。\n故人何处舣危墙。\n寄我相思千点泪，直过潇湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2983, '浪淘沙', '赵鼎', '玉宇洗秋晴。\n凉月亭亭。\n梦回孤枕琐窗明。\n何处飞来三弄笛，风露凄清。\n曾看玉纤横。\n苦爱新声。\n由来百虑为愁生。\n此夜曲中闻折柳，都是离情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2984, '青玉案', '蒋璨', '三年枕上吴中路。\n遣黄耳、随君去。\n欲过松江呼小渡。\n莫惊鸥鹭，四桥都是，老子经行处。\n辋川图上看春暮。\n长忆高人右丞句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2985, '汉宫春', '李邴', '潇洒江梅，向竹梢疏处，横两三枝。\n东君也不爱惜，雪压霜欺。\n无情燕子，怕春寒、轻失花期。\n却是有，年年塞雁，归来曾见开时。\n清浅小溪如练，问玉堂何似，茅舍疏篱。\n伤心故人去後，冷落新诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2986, '洞仙歌', '李邴', '一团娇软，是将春揉做，撩乱随风到何处。\n自长亭、人去後，烟草萋迷，归来了、装点离愁无数。\n飘扬无个事，刚被萦牵，长是黄昏怕微雨。\n记那回，深院静，帘幕低垂，花阴下、霎时留住。\n又只恐、伊家太轻狂，蓦地和春，带将归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2987, '玉蝴蝶', '李邴', '壮岁分符方面，惠风草偃，禾稼春融。\n报政朝天，归去稳步鳌宫。\n望尧、九重绛阙，颁汉诏、五色芝封。\n湛恩浓。\n锦衣槐里，重继三公。\n雍容。\n临歧祖帐，绮罗环列，冠盖云丛。\n满城桃李，尽将芳意谢东风。\n柳烟轻、万条离恨，花露重、千点啼红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2988, '念奴娇', '李邴', '素光练净，映秋山、隐隐修眉横绿。\n鹊楼高天似水，碧瓦寒生银粟。\n千丈斜晖，奔云涌雾，飞过卢仝屋。\n更无尘气，满庭风碎梧竹。\n谁念鹤发仙翁，当年曾共赏，紫岩飞瀑。\n对影三人聊痛饮，一洗离愁千斛。\n斗转参横，翩然归去，万里骑黄鹄。\n满川霜晓，叫云吹断横玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2989, '小冲山・小重山', '李邴', '谁劝东风腊里来。\n不知天待雪，恼江梅。\n东郊寒色尚徘徊。\n双彩燕，飞傍鬓云堆。\n玉冷晓妆台。\n宜春金缕字，拂香腮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2990, '木兰花・玉楼春', '李邴', '沈吟不语晴窗畔。\n小字银钩题欲遍。\n云情散乱未成篇，花骨斜终带软。\n重重说尽情和怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2991, '清平乐', '李邴', '露花烟柳。\n春思浓如酒。\n几阵狂风新雨後。\n满地落红铺绣。\n风流何处疏狂。\n厌厌恨结柔肠。\n又是危阑独倚，一川烟草斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2992, '满庭芳', '李邴', '又喜椒觞到手，宝胜里、仍剪金花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2993, '玉楼春', '李邴', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2994, '满庭芳', '李邴', '凉风吹帽，横槊试登高。\n想见征西旧事，龙山会、宾主俱豪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2995, '女冠子', '李邴', '帝城三五。\n灯光花市盈路。\n天街游处。\n此时方信，凤阙都民，奢华豪富。\n纱笼才过处。\n喝道转身，一壁小来且住。\n见许多、才子艳质，携手并肩低语。\n东来西往谁家女。\n买玉梅争戴，缓步香风度。\n北观南顾。\n见画烛影里，神仙无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2996, '调笑令', '李邴', '双绿。\n淡匀拂。\n两脸春融光透玉。\n起来却怕东风触。\n本是一团香玉。\n飞鸾台上看未足。\n贮向阿娇金屋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2997, '满庭芳', '向子', '月窟蟠根，云岩分种，绝知不是尘凡。\n琉璃剪叶金粟缀花繁。\n黄菊周旋避舍，友兰蕙、羞杀山樊。\n清香远，秋风十里，鼻观已先参。\n酒阑。\n听我语，平生半是，江北江南。\n经行处、无穷绿水青山。\n常被此花相恼，思共老、结屋中间。\n不因尔，芗林底事，游戏到人寰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2998, '满庭芳', '向子', '瑟瑟金风，团团玉露，岩花秀发秋光。\n水边一笑，十里得清香。\n疑是蕊宫仙子，新妆就、娇额涂黄。\n霜天晚，妖红丽紫，回首总堪伤。\n中央。\n孕正色，更留明月，偏照何妨。\n便高如兰菊，也让芬芳。\n输与芗林居士，微吟罢、闲据胡床。\n须知道，天教尤物，相伴老江乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (2999, '蓦山溪', '向子', '瑶田银海。\n浩色难为对。\n琪树照人间，晓然是、华岩境界。\n万年松径，一带旧峰峦，深掩覆，密遮藏，三昧兴无碍。\n金毛狮子，打就休惊怪。\n片片上红炉，且不可、将情作解。\n有无不道，泯绝去来今，明即暗，暗还明，只个长不昧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3000, '蓦山溪', '向子', '挂冠神武。\n来作烟波主。\n千里好江山，都尽是、君恩赐与。\n风勾月引，催上泛宅时，酒倾玉，堆雪，总道神仙侣。\n蓑衣箬笠，更着些儿雨。\n横笛两三声，晚云中、惊鸥来去。\n欲烦妙手，写入散人图，蜗角名，蝇头利，着甚来由顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3001, '蓦山溪', '向子', '一阳才动，万物生春意。\n试与问宫梅，到东阁、花枝第几。\n疏疏淡淡，冷艳雪中明，无俗调，有真香，正与人相倚。\n非烟非雾，瑞色门阑喜。\n再拜引杯长，看两颊、红潮欲起。\n天教难老，风鬓绿如云，对玉笥，与芗林，岁岁花前醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3002, '水龙吟', '向子', '华灯明月光中，绮罗弦管春风路。\n龙如骏马，车如流水，软红成雾。\n太一池边，葆真宫里，玉楼珠树。\n见飞琼伴侣，霓裳缥缈，星回眼、莲承步。\n笑入彩云深处。\n更冥冥、一帘花雨。\n金钿半落，宝钗斜坠，乘鸾归去。\n醉失桃源，梦回蓬岛，满身风露。\n到而今江上，愁山万叠，鬓丝千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3003, '水龙吟', '向子', '梦回寒入衾绸，晓惊忽堕瑶林里。\n穿帷透隙，落花飞絮，难穷巧思。\n着帽披裘，挈壶呼友，倚空临水。\n望琼田不尽，银涛无际，浮皓色、来天地。\n遥想吴郎病起。\n政冷窗、微吟拥鼻。\n持笺赠我，新词绝唱，珠零玉碎。\n馀兴追游，清芬坐对，高谈倾耳。\n晚归来，风扫停云，万里月华如洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3004, '八声甘州', '向子', '恨中秋、多雨及晴景，追赏且探先。\n纵玉钩初上，冰轮未正，无奈婵娟。\n饮客不来自酌，对影亦清妍。\n任笑芗林老，雪鬓霜髯。\n好在章江西畔，有凌云玉笥，空翠相连。\n懒崎岖林麓，则窈窕溪边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3005, '卜算子', '向子', '千古一灵根，本妙元明静。\n道个如如已是差，莫认风番影。\n枯木夜堂深，默坐时观省。\n月落乌鸡出户飞，万里关河冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3006, '三字令', '向子', '春尽日，雨馀时。\n红蔌蔌，绿漪漪。\n花满地，水平池。\n烟光里，云影上，画船移。\n纹鸳并，白鸥飞。\n歌韵响，酒行迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3007, '长相思', '向子', '年重月，月重光。\n万瓦千林白似霜。\n扁舟入醉乡。\n山苍苍。\n水茫茫。\n严濑当时不是狂。\n高风引兴长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3008, '南歌子', '向子', '柳眼风前动，梅心雪後寒。\n年光浑似雾中看。\n抱答风光无处、可为欢。\n一曲聊收泪，三杯强自宽。\n新愁不奈上眉端。\n怕见长安归路、懒凭栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3009, '减字木兰花', '向子', '无穷白水。\n无限芰荷红翠里。\n几点青山。\n半在云烟暗霭间。\n移舟横截。\n卧看碧天流素月。\n此意虚徐。\n好把芗林入画图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3010, '南歌子', '向子', '江左称岩桂，吴中说木犀。\n水沈为骨郁金衣。\n却恨疏梅恼我、得香迟。\n叶借山光润，花蒙水色奇。\n年年勾引赋新诗。\n应笑芗林冷淡、独心知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3011, '南歌子', '向子', '病著连三月，谁能慰老夫。\n萧萧短发不胜梳。\n风里支离欲倒、要人扶。\n秋月明如水，岩花忽起予。\n旋白酒入盘盂。\n报答风光不醉、更何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3012, '南歌子', '向子', '我入三摩地，人疑小有天。\n君王送老白云边。\n不用丹青图画、上凌烟。\n喜揽澄清辔，能同载酒船。\n相逢忽谩别经年。\n好是两身强健、在尊前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3013, '桂殿秋', '向子', '秋色里，月明中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3014, '朝中措', '向子', '满城腊雪净无埃。\n触处是花开。\n天上琼林珠树，谁知夜半移来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3015, '菩萨蛮', '向子', '天仙醉把真珠掷。\n荷翻写入玻璃碧。\n雨过酒尊凉。\n红蕖苒苒香。\n飞来双白鹭。\n屡作舞。\n山鸟起清歌。\n晚来情更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3016, '好事近', '向子', '多病卧江干，过尽春花秋叶。\n又见横斜疏影，弄阶前明月。\n呼儿取酒据胡床，尚喜知时节。\n宜与老夫情厚，有鬓边残雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3017, '好事近', '向子', '风劲入平林，扫尽一林黄叶。\n惟有长松千丈，挂娟娟霜月。\n使君和气动江城，疑是芳菲节。\n忽到小园游戏，见南枝如雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3018, '减字木兰花', '向子', '两峰对起。\n象阙端门云雾里。\n千嶂排空。\n虎节龙旗指顾中。\n箫韶妙曲。\n我试与听音韵足。\n借问谁传。\n松上清风石上泉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3019, '减字木兰花', '向子', '翠鬟双小。\n绿绮朱弦心未了。\n画戟森间。\n玉子纹楸手共谈。\n不妨扶老。\n未说他年无限笑。\n且要忘忧。\n莫问今朝胜几筹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3020, '减字木兰花', '向子', '腊前雪里。\n几处梅梢初破蕊。\n年後江边。\n是处花开晚更妍。\n绝知春意。\n不耐愁何心与醉。\n更有难忘。\n宋玉墙头婉婉香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3021, '减字木兰花', '向子', '谁知莹澈。\n惟有碧天云外月。\n一见风流。\n洗尽胸中万斛愁。\n剩烧蜜炬。\n只恐夜深花睡去。\n想得横陈。\n全是巫山一段云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3022, '减字木兰花', '向子', '千山万水。\n望极不知何处是。\n小院回廊。\n梦去相寻未觉长。\n绝怜清瘦。\n雪里梅梢春未透。\n常记分携。\n雨後梨花晓尚啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3023, '减字木兰花', '向子', '去年端午。\n共结彩丝长命缕。\n今日重阳。\n同泛黄花九酝觞。\n经时离缺。\n不为莱菔髭似雪。\n一笑逢迎。\n休觅空青眼自明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3024, '满庭芳', '向子', '天宇长闲，飞仙狂醉，云碎玉沈空。\n谢家庭院，争道絮因风。\n不怕寒生宝粟，深调护、犀幕重重。\n瑶林里，疏梅献笑，小萼露轻红。\n瑞龙。\n香绕处，云间弦管，尘外帘栊。\n须烂醉流霞，莫诉千锺。\n闻道蟠桃正好，蓬瀛路、消息潜通。\n飞琼伴，偷将春色，分付入芳容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3025, '水调歌头', '向子', '天公深藏巧，雪里放春回。\n不到闲花凡草，都付与疏梅。\n独立水边林下，萧萧冰容孤艳，清瘦玉腰支。\n触拨暗香动，风味欲愁谁。\n娥携，青女过，夜阑时。\n瑶冠琼佩，粲然一笑亦何奇。\n剩欲举觞对饮，不怕月明霜重，寒色著人衣。\n只恐邻笛起，化作玉尘飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3026, '梅花引', '向子', '花如颊。\n梅如叶。\n小时笑弄阶前月。\n最盈盈。\n最惺惺。\n闲愁未识、无计定深情。\n十年空省春风面。\n花落花开不相见。\n要相逢。\n得相逢。\n须信灵犀，中自有心通。\n同杯勺。\n同斟酌。\n千愁一醉都推却。\n花阴边。\n柳阴边。\n几回拟待、偷怜不成怜。\n伤春玉瘦慵梳掠。\n抛掷琵琶闲处著。\n莫猜疑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3027, '人娇', '向子', '白似雪花，柔於柳絮。\n胡蝶儿、镇长一处。\n春风骀荡，蓦然吹去。\n得游丝、半空惹住。\n波上精神，掌中态度。\n分明是、彩云团做。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3028, '玉楼春', '向子', '记得江城春意动。\n两行疏梅龙脑冻。\n佳人不用辟寒犀，踏雪穿花云鬓重。\n真珠旋滴留人共。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3029, '玉楼春', '向子', '云窗雾阁春风透。\n蝶绕蜂围花气漏。\n恼人风味恰如梅，倚醉腰肢全是柳。\n细传一曲情偏厚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3030, '鹧鸪天', '向子', '小院深明别有天。\n花能笑语柳能眠。\n雪肌得酒於中暖，莲步凌波分外妍。\n钗燕重，髻荷偏。\n两山斜叠翠连娟。\n朝云无限矜春态，暮雨情知更可怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3031, '鹧鸪天', '向子', '斗帐欢盟不计年。\n谁知蓦地远如天。\n何曾一霎离心上，怎得而今在眼前。\n鱼不断，雁相连。\n可无小字寄芳笺。\n薄情已是抛人去，更与新愁到酒边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3032, '上西平・金人捧露盘', '张元干', '卧扁舟，闻寒雨，数佳期。\n又还是、轻误仙姿。\n小楼梦冷，觉来应恨我归迟。\n鬓云松处，枕檀斜、露泣花枝。\n名利空萦系，添憔悴，谩孤。\n得见了、说与教知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3033, '春光好', '张元干', '花恨雨，柳嫌风。\n客愁浓。\n坐久霜刀飞碎雪，一尊同。\n劳烦玉指春葱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3034, '春光好', '张元干', '寒食近，踏青时。\n画堂西。\n可是春来偏倦绣，乍生儿。\n香绵轻拂胭脂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3035, '清平乐', '张元干', '乱山深处。\n雪拥溪桥路。\n晓日乍明催客去。\n惊起玉鸦翻树。\n翠衾香暖檀灰。\n一枝想见疏梅。\n凭仗东风说与，画眉人共春回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3036, '清平乐', '张元干', '明珠翠羽。\n小绾同心缕。\n好去吴松江上路。\n寄与双鱼尺素。\n兰桡飞取归来。\n愁眉待得伊开。\n相见嫣然一笑，眼波先入郎怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3037, '菩萨蛮', '张元干', '天涯客里秋容晚。\n妖红聊戏思乡眼。\n一朵醉深妆。\n羞渠照鬓霜。\n开时谁断送。\n不待司共花。\n有脚号阳春。\n芳菲属主人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3038, '菩萨蛮', '张元干', '拍堤绿涨桃花水。\n画船稳泛东风里。\n丝雨湿苔钱。\n浅寒生禁烟。\n江山留不住。\n却载笙歌去。\n醉倚玉搔头。\n几曾知旅愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3039, '菩萨蛮', '张元干', '春来春去催人老。\n老夫争肯输年少。\n醉後少年狂。\n白髭殊未妨。\n插花还起舞。\n管领风光处。\n把酒共留春。\n莫教花笑人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3040, '菩萨蛮', '张元干', '雨馀翠袖琼肤润。\n一枝想像伤春困。\n老眼见花时。\n惜花心未衰。\n酿成谁与醉。\n应把流苏缀。\n泪沁枕囊香。\n恼侬归梦长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3041, '菩萨蛮', '张元干', '黄莺啼破纱窗晓。\n兰缸一点窥人小。\n春浅锦屏寒。\n麝煤金博山。\n梦回无处觅。\n细雨梨花湿。\n正是踏青时。\n眼前偏少伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3042, '菩萨蛮', '张元干', '甘林玉蕊生香雾。\n游蜂争采清晨露。\n芳意著人浓。\n微烘曲室中。\n春来瀛海外。\n沈水迎风碎。\n好事富馀熏。\n频分几缕云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3043, '楼上曲', '张元干', '楼外夕阳明远水。\n楼中人倚东风里。\n何事有情怨别离。\n低鬟背立君应知。\n东望云山君去路。\n断肠迢迢尽愁处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3044, '楼上曲', '张元干', '清夜灯前花报喜。\n心随社燕凉风起。\n云路修成宝月时。\n东楼怅望君先归。\n沆瀣秋香生玉井。\n画檐深转梧桐影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3045, '豆叶黄・忆王孙', '张元干', '冰溪疏影竹边春。\n翠袖天寒炯暮云。\n雪里精神澹伫人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3046, '豆叶黄・忆王孙', '张元干', '疏枝冷蕊忽惊春。\n一点芳心入鬓云。\n风韵情知似玉人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3047, '满庭芳', '张元干', '梁苑春归，章街雪霁，柳梢华萼初萌。\n非烟非雾，新岁乐升平。\n京兆雍容报政，金狨过、九陌尘轻。\n朝回处，青霄路稳，黄色起天庭。\n东风，吹绿鬓，薄罗剪彩，小绾流莺。\n比渭滨甲子，尚父难兄。\n满泛椒觞献寿，斑衣侍、云母分屏。\n明年会，双衣对引，谈笑秉钧衡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3048, '满庭芳', '张元干', '韩国殊勋，洛都西内，名园甲第相连。\n当年绿鬓，独占地行仙。\n文彩风流瑞世，延朱履、丝竹喧阗。\n人皆仰，一门相业，心许子孙贤。\n中兴，方庆会，再逢甲子，重数天元。\n问千龄谁比，五福俱全。\n此去沙堤步稳，调金鼎、七叶貂蝉。\n香檀缓，杯传鹦鹉，新月正娟娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3049, '满庭芳', '张元干', '玉叶联芳，天潢分润，寿筵长对熏风。\n间平襟度，濮邸行尊崇。\n忠孝家传大雅，无喜愠、一种宽容。\n芝兰盛，彩衣嬉戏，亲睦冠西宗。\n丝纶，膺重寄，遥防迁美，本镇恩隆。\n应萱堂齐福，诞月仍同。\n花蕊香浓气暖，凝瑞露、满酌金锺。\n龙光近，星飞驿马，宣入嗣王封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3050, '满庭芳', '张元干', '三十年来，云游行化，草鞋踏破尘沙。\n遍参尊宿，曾记到京华。\n衲子如麻似粟，谁会笑、瞿老拈花。\n经离乱，青山尽处，海角又天涯。\n今宵，闲打睡，明朝粥饭，随分僧家。\n把木佛烧却，除是丹霞。\n撞著门徒施主，蓦然个、喜舍由他。\n庐陵米，还知价例，毫发更无差。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3051, '瑞鹤仙', '张元干', '倚格天峻阁。\n舞庭槐阴转，盆榴红烁。\n香风泛帘幕。\n拥霞裾琼佩，真珠璎珞。\n华阳庆渥。\n诞兰房、流芳秀萼。\n有赤绳系足，从来相门，自然媒妁。\n游戏人间荣贵，道要元微，水源清浊。\n长生大药。\n彩鸾韵，凤箫鹤。\n对木公金母，子孙三世，妇姑为寿满酌。\n看千龄，举家飞升，玉京更乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3052, '瑞鹤仙', '张元干', '喜西园放钥。\n对燕寝香润，棠阴寒薄。\n东风夜来恶。\n禁烟时天气，莺啼花落。\n新晴共约。\n怕韶光、容易过却。\n把铜壶、缓浮金杯，禊游行乐。\n弦索。\n笙簧声里，还记兰房，正垂罗幕。\n初眠弱柳。\n梅如豆，玉如琢。\n向凤凰池上，鸳鸯影里，他年何啻紫橐。\n看流芳，继踵韦平，盛传巩洛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3053, '瑶台第一层', '张元干', '宝历祥开飞练上，青冥万里光。\n石城形胜，秦淮风景，威凤来翔。\n腊馀春色早，兆钓璜、贤佐兴王。\n对熙旦，正格天同德，全魏分疆。\n荧煌。\n五云深处，化钧独运斗魁旁。\n绣裳龙尾，千官师表，万事平章。\n景锺文瑞世，醉尚方、难老金浆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3054, '瑶台第一层', '张元干', '江左风流锺间气，洲分二水长。\n凤凰台畔，投怀玉燕，照射神光。\n豆花初秀雨，散暑空、洗出秋凉。\n庆生旦，正圆蟾呈瑞、仙桂飘香。\n肝肠。\n文锦，驾云乘鹤下行。\n紫枢将命，紫微如绋，常近君王。\n旧山同梓里，荷月旦、久已平章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3055, '望海潮', '张元干', '苍山烟澹，寒溪风定，玉簪罗带绸缪。\n轻霭暮飞，青冥远净，珠星璧月光浮。\n城际踊层楼。\n正翠帘高卷，绿琐低钩。\n影落尊，气和歌管共清游。\n史君冠世风流。\n拥香鬟凭槛，雾鬓凝眸。\n银烛暖宵，花光照席，谯门莫报更筹。\n逸兴醉无休。\n赋探梅芳信，翻曲新讴。\n想见疏枝冷蕊，春意到沙洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3056, '望海潮', '张元干', '麒麟图画，貂蝉冠冕，青毡自属元勋。\n绿野旧游，平泉雅咏，霞舒烟卷朝昏。\n风月小阳春。\n照玳筵珠履，公子王孙。\n雪度嵩高，影横伊水庆生申。\n早梅长醉芳尊。\n况中兴盛际，宥密宗臣。\n琳馆奉祠，金瓯覆字，和羹妙手还新。\n光射紫微垣。\n看五云朝斗，千载逢辰。\n开取八荒寿域，一气转洪钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3057, '十月桃', '张元干', '年华催晚，听尊前偏唱，冲暖欺寒。\n乐府谁知，分付点化金丹。\n中原旧游何在，频入梦、老眼空潸。\n撩人冷蕊，浑似当时，无语低鬟。\n有多情多病文园。\n向雪後寻春，醉里凭阑。\n独步群芳，此花风度天然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3058, '十月桃', '张元干', '蟠桃三熟，正清霜吹冷，爱日烘香。\n小试芳菲，时候无限风光。\n洛滨老人星见，□少室、云雾开祥。\n丹青万汇，熊兆台，凤举朝阳。\n向元枢会辅岩廊。\n记名著金瓯，位入中堂。\n梦熟钧天，屡惊颠倒衣裳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3059, '感皇恩', '张元干', '绿发照魁星，平康争看。\n锦绣肝肠五千卷。\n出逢熙运，早侍玉皇香案。\n禁涂扬历遍，纡宸眷。\n安养老成，十年萧散。\n天要中兴相公健。\n生朝开宴，长是通宵弦管。\n藕花香不断，南风远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3060, '感皇恩', '张元干', '年少太平时，名园甲第。\n谈笑雍容万锺贵。\n姚黄重绽，长对小春天气。\n绮罗丛里惯，今朝醉。\n台衮向贤，元枢虚位。\n壮岁青云自曾致。\n流霞麟脯，难老洛滨风味。\n谢公须再为，苍生起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3061, '感皇恩', '张元干', '荔子著花繁，清微庭院。\n贺厦双飞画梁燕。\n绮罗丛里，百和炉烟祝愿。\n愿从今日去，身长健。\n檀板竞催，榕阴初转。\n舞袖风前翠翘颤。\n明年开府，锡宴金锺宣劝。\n寿星朝北斗，君王眷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3062, '感皇恩', '张元干', '豹尾引黄幡，宣麻金殿。\n雨露恩浓自天遣。\n绅交誉，最乐至诚为善。\n信知宗姓喜，君王眷。\n宝炬密香，玉卮波滟。\n醉拥笙歌夜深院。\n西清班近，雅称元戎同燕。\n要看茅土相，貂蝉面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3063, '夏云峰', '张元干', '涌冰轮，飞沆瀣，霄汉万里云开。\n南极瑞占象纬，寿应三台。\n锦肠珠唾，锺间气、卓荦天才。\n正暑，有祥光照社，玉燕投怀。\n新堂深处捧杯，乍香泛水芝，空翠风回。\n凉送燕歌缓舞，醉瑶钗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3064, '千秋岁', '张元干', '相门出相，和气浓春酿。\n传家冠佩云台上。\n庞眉扶寿杖。\n绿发披仙氅。\n星两两。\n泰阶已应升平象。\n玉砌兰芽长。\n定向东风赏。\n添彩袖，褰罗幌。\n丝簧俱妙手，珠翠争宫样。\n江海量。\n年年醉里翻新唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3065, '水龙吟', '张元干', '水晶宫映长城，藕花万顷开浮蕊。\n红妆翠盖，生朝时候，湖山摇曳。\n珠露争圆，香风不断，普熏沈水。\n似瑶池侍女，霞裾缓步，寿烟光里。\n霖雨已沾千里。\n兆丰年、十分和气。\n星郎绿鬓，锦波春酿，碧筒宜醉。\n荷橐还朝，青毡奕世，除书将至。\n看巢龟戏叶，蟠桃著子，祝三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3066, '南乡子', '张元干', '山寺辋川图。\n霜叶云林锦绣居。\n寿浮春珠翠拥，欢娱。\n满院流泉绕绮疏。\n道气自肤腴。\n几席轻尘一点无。\n天要耆英修相业，清都。\n已有泥书降玉除。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3067, '卷珠帘・蝶恋花', '张元干', '祥景飞光盈衮绣。\n流庆昆台，自是神仙胄。\n谁遣阳和放春透。\n化工重入丹青手。\n云锦瑟争为寿。\n玉带金鱼，共愿人长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3068, '醉蓬莱', '张元干', '对小春桃艳，曲室炉红，乍寒天气。\n七叶开，应金章通贵。\n梦草银钩，灿花珠唾，是素来风味。\n满腹经纶，回天议论，昆台仙裔。\n秘殿升华，紫枢勋旧，退步真祠，简心端。\n迎日天元，听正衙宣制。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3069, '陇头泉・多丽', '张元干', '少年时，壮怀谁与重论。\n视文章、真成小技，要知吾道称尊。\n奏公车、治安秘计，乐油幕、谈笑从军。\n百镒黄金，一双白璧，坐看同辈上青云。\n事大谬，转头流落，徒走出修门。\n三十载，黄梁未熟，沧海扬尘。\n念向来、浩歌独往，故园松菊犹存。\n送飞鸿、五弦寓目，望爽气、西山忘言。\n整顿乾坤，廓清宇宙，男儿此志会须伸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3070, '天仙子', '张元干', '楼外轻阴春澹伫。\n数点杏梢寒食雨。\n少年油壁记寻芳，梁苑路。\n今何处。\n千树红云空梦去。\n惊见此花须折取。\n明日满城传侍女。\n情知醉里惜花深，留春住。\n听莺语。\n一段风流天赋与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3071, '鹊桥仙', '张元干', '靓妆艳态，娇波流盼，双靥横涡半笑。\n尊前烛畔粉生光，更低唱、新翻转调。\n花房结子，冰枝清瘦。\n醉依香浓寒峭。\n雏莺新啭上林声，惊梦断、池堂春草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3072, '渔父家风・诉衷情令', '张元干', '八年不见荔枝红。\n肠断故园东。\n风枝露叶新采，怅望冷香浓。\n冰透骨，玉开容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3073, '生查子', '张元干', '天生几种香，风味因花见。\n旖旎透香肌，仿佛飞花片。\n雨润惜馀熏，烟断犹相恋。\n不似薄情人，浓淡分深浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3074, '减字木兰花', '张元干', '客亭小会。\n可惜无欢容易醉。\n归去更阑。\n细雨鸣窗一夜寒。\n昏然独坐。\n举世疏狂谁似我。\n强拨炉烟。\n也道今宵是上元。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3075, '眼儿媚', '张元干', '萧萧疏雨滴梧桐。\n人在绮窗中。\n离愁遍绕，天涯不尽，却在眉峰。\n娇波暗落相思泪，流破脸边红。\n可怜瘦似，一枝春柳，不奈东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3076, '昭君怨', '张元干', '春院深深莺语。\n花怨一帘烟雨。\n禁火已销魂。\n更黄昏。\n衾暖麝灯落。\n雨过重门深夜。\n枕上百般猜。\n未归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3077, '夜游宫', '张元干', '半吐寒梅未拆。\n双鱼洗、冰澌初结。\n户外明帘风任揭。\n拥红炉，洒窗间，闻霰雪。\n比去年时节。\n这心事、有人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3078, '杨柳枝', '张元干', '深院今宵枕簟凉。\n烛花光。\n更筹何事促行觞。\n恼刚肠。\n老去一蓑烟雨里，钓沧浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3079, '彩鸾归令', '张元干', '珠履争围。\n小立春风趁拍低。\n态闲不管乐催伊。\n整铢衣。\n粉融香润随人劝，玉困花娇越样宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3080, '江神子・江城子', '张元干', '梦中北去又南来。\n饱风埃。\n鬓华衰。\n浮木飞蓬，踪迹为谁催。\n自笑自悲还自语，一杯酒，鼻如雷。\n晓舆行处觉春回。\n屑琼瑰。\n糁莓苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3081, '西江月', '张元干', '小阁劣容老子，北窗仍递南风。\n维摩丈室久空空。\n不与散花同梦。\n且作大真游戏，未甘金粟龙锺。\n怜君病後颊颧隆。\n识取小儿戏弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3082, '诉衷情', '张元干', '儿时初未识方红。\n学语问西东。\n对客呼为红蕊，此兴已偏浓。\n嗟白首，抗尘容。\n费牢笼。\n星球何在，鹤顶长丹，谁寄南风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3083, '采桑子', '张元干', '华堂清暑榕阴重，梦里江寒。\n火齐星繁。\n兴在冰壶玉井栏。\n风枝露叶谁新采，欲饱防悭。\n遗恨空盘。\n留取香红满地看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3084, '菩萨蛮', '张元干', '山城何岁无风雨。\n楼台底事随波去。\n归棹望谯门。\n沙痕炯断云。\n诗成空吊古。\n想像经行处。\n陵谷有馀悲。\n举觞浇别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3085, '菩萨蛮', '张元干', '微云红衬馀霞绮。\n明星碧浸银河水。\n猗枕画檐风。\n愁生草际蛩。\n雁行离塞晚。\n不道衡阳远。\n归恨隔重山。\n楼高莫凭栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3086, '浣溪沙', '张元干', '睡起中庭月未蹉。\n繁香随影上轻罗。\n多情肯放一春过。\n比似雪时犹带韵，不如梅处却缘多。\n酒边枕畔奈愁何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3087, '好事近', '张元干', '华烛炯离觞，山吐四更寒月。\n公子唾花枝玉，尽一时豪杰。\n三冬兰若读书灯，想见太清绝。\n纸帐地炉香暖，傲一窗风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3088, '南歌子', '张元干', '玉斧修圆了，冰轮分外清。\n共看星向绣衣明。\n元是生朝为寿、对难兄。\n鸿雁翻秋影，埙篪和笑声。\n他年中令彩衣荣。\n记取今宵丹荔、醉瑶觥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3089, '醉花阴', '张元干', '紫菊红萸开犯早。\n独占秋光老。\n酝造一般清，比著芝兰，犹自争多少。\n霜刀剪叶呈纤巧。\n手拈迎人笑。\n云鬓一枝斜，小阁幽窗，是处都香了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3090, '点绛唇', '张元干', '小雨晴，坐来池上荷珠碎。\n倬眉浓翠。\n怎不交人醉。\n美盼流觞，白鹭窥秋水。\n天然媚。\n大家休睡。\n笑倚西风里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3091, '花心动', '张元干', '水馆风亭，晚香浓、一番芰荷新雨。\n簟枕乍闲，襟裾初试，散尽满天袢暑。\n断云却送轻雷去。\n疏林外、玉钩微吐。\n夜渐永，秋惊败叶，凉生亭户。\n天上佳期久阻。\n银河畔、仙车缥缈云路。\n旧怨未平，幽欢驻，恨入半天风露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3092, '蓦山溪', '张元干', '一番小雨，陡觉添秋色。\n桐叶下银床，又送个、凄凉消息。\n故乡何处，搔首对西风，衣线断，带围宽，衰鬓添新白。\n钱塘江上，冠盖如云积。\n骑马傍朱门，谁肯念、尘埃墨客。\n佳人信杳，日暮碧云深，楼独倚，镜频看，此意无人识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3093, '西楼月・春晓曲', '张元干', '瑶轩倚槛春风度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3094, '瑞鹧鸪', '邓肃', '北书一纸惨天容。\n花柳春风不敢。\n未学宣尼歌凤德，姑从阮籍哭途穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3095, '临江仙', '邓肃', '带雨梨花看上马，问人底事匆匆。\n于飞有愿恨难从。\n大鹏抟九万，鹦鹉锁金笼。\n忽忽便为千里隔，危岑已接高穹。\n回头那忍问前踪。\n家留烟雨外，人在斗牛中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3096, '临江仙', '邓肃', '百尺危楼初过雨，清风凛作轻寒。\n一声渔笛在云端。\n黄昏帘幕卷，新月半阑干。\n青翼不来音信断，云窗杳隔三山。\n何当携手便骖鸾。\n今宵同胜景，玉不留残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3097, '临江仙', '邓肃', '春雪一瓯扶醉玉，翩翩两腋生风。\n柳腰无力云踪。\n陈郎投辖意，分袂忍匆匆。\n白玉琢杯龙麝泛，天酒争浓。\n何妨一饮上青骢。\n晴空行夜月，缓辔水晶宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3098, '临江仙', '邓肃', '剑水泠泠行碧玉，扁舟一叶吹风。\n玉人招手画桥东。\n浩歌随月去，春在小楼中。\n帘幕低垂围笃耨，雕觞笑捧春葱。\n谩将雨意作云浓。\n单于吹未彻，门外响玲珑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3099, '临江仙', '邓肃', '雨过荼縻春欲放，轻寒约住馀芳。\n南园今日被朝阳。\n琼葩开万点，尘世满天香。\n百卉丛中红紫乱，玉肌自笑孤光。\n清风翦翦过纱窗。\n馀酲空一洗，不数寿阳妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3100, '临江仙', '邓肃', '独宿禅房清梦断，鸡声唤起晨钟。\n出门晓月耿寒空。\n小池凝翡翠，竹外跨飞虹。\n梅坞不知何处了，傍篱临水重重。\n啸歌都在冷香中。\n人间那有此，天上广寒宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3101, '临江仙', '邓肃', '夜饮不知更漏永，馀酣困染朝阳。\n庭前莺燕乱丝簧。\n醉眠犹未起，花影满晴窗。\n帘外报言天色好，水沈已染罗裳。\n檀郎欲起趁春狂。\n佳人嗔不语，劈面丁香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3102, '临江仙', '邓肃', '夜静黄云承宝袜，九疑人到羊家。\n蕊宫仙曲送流霞。\n东陵分玉井，远胜隔荷花。\n绰约旗亭沾一笑，众惊食枣如瓜。\n画桥烟柳忽翻鸦。\n醉鬟倾绿醑，参月共横斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3103, '临江仙', '邓肃', '楼北楼南青不断，晴空总是春容。\n先来无处问郎踪。\n那堪风不定，雨尽一窗红。\n初恨水中徒捉月，而今水月俱空。\n谩将雨意伴云浓。\n临风千点泪，不到浙江东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3104, '浣溪沙', '邓肃', '雨入空阶滴夜长。\n月行云外借孤光。\n独将心事步长廊。\n深锁重门飞不去，巫山何日梦襄王。\n一床衾枕冷凄香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3105, '浣溪沙', '邓肃', '傍竹柴门俯碧流。\n见人无语眼横秋。\n鸣机轧轧弄纤柔。\n定有回文传窦子，何时银汉渡牵牛。\n归来风雨夜飕飕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3106, '浣溪沙', '邓肃', '宿雨潜回海宇春。\n晓风徐散日边云。\n熙熙人意一番新。\n破睡海棠能媚客，舞风垂柳似招人。\n春衫归去马蹄轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3107, '浣溪沙', '邓肃', '阑外彤云已满空。\n帘旌不动石榴红。\n谁将秋色到楼中。\n玛瑙一泓浮翠玉，瓠犀终日凛天风。\n炎洲人到广寒宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3108, '浣溪沙', '邓肃', '高会横山酒八仙。\n烟云不减九华妍。\n暖风琼树倚楼前。\n妙唱一声尘暗落，靓妆四座玉相连。\n骖鸾何日共翩翩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3109, '浣溪沙', '邓肃', '二八佳人宴九仙。\n华堂清静斗春妍。\n琼枝相倚妙无前。\n良夜黄云来缥缈，东风碧酒意留连。\n花间蝶梦想翩翩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3110, '浣溪沙', '邓肃', '半醉倚人落珥簪。\n天香不数海南沈。\n时倾秋水话春心。\n已觉吹箫归碧落，从今禊饮笑山阴。\n金杯休惜十分深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3111, '浣溪沙', '邓肃', '海畔山如碧玉簪。\n天涯消息叹鱼沈。\n赖逢倾国洗愁心。\n莫为世情生旅况，且因乐事惜光阴。\n明朝红雨已春深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3112, '菩萨蛮', '邓肃', '隔窗瑟瑟闻飞雪。\n洞房半醉回春色。\n银烛照更长。\n罗屏围夜香。\n玉山幽梦晓。\n明日天涯杳。\n倚户黯芙蓉。\n涓涓秋露浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3113, '菩萨蛮', '邓肃', '萋萋欲遍池塘草。\n轻寒却怕春光老。\n微雨湿昏黄。\n梨花啼晚妆。\n低垂帘四面。\n沈水环深院。\n太白困鸳鸯。\n天风吹梦长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3114, '菩萨蛮', '邓肃', '飞红欲带春风去。\n柳丝却织春风住。\n去住任春风。\n只愁尊俎空。\n今朝鞭马去。\n又得高阳侣。\n半醉踏花归。\n霜蹄骄欲飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3115, '菩萨蛮', '邓肃', '帘旌不动薰馀热。\n高堂谁送能言雪。\n一笑下人间。\n天风袭坐寒。\n歌声云外去。\n句句苏仙语。\n曲罢一尊空。\n飘然欲驭风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3116, '菩萨蛮', '邓肃', '廉纤细雨连天远。\n纱窗不隔斜风冷。\n花柳自生春。\n无聊空闭门。\n双双携手处。\n回首烟汀暮。\n嬉笑在高楼。\n知人牢落否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3117, '菩萨蛮', '邓肃', '垂杨袅袅腰肢软。\n寒溪练练琉璃浅。\n短艇卧吹风。\n生涯一叶中。\n五湖须径去。\n何用若耶女。\n烟雨暝沙汀。\n花香唤酒醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3118, '菩萨蛮', '邓肃', '腰肢欲趁杨花去。\n歌声能遏行云住。\n杯酒醉东风。\n羁愁一洗空。\n谪仙清饮露。\n意在飞琼侣。\n未醉即求归。\n新词句欲飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3119, '菩萨蛮', '邓肃', '归心谩逐飞云去。\n欢情却为芳菲住。\n翠袖拥香风。\n宁辞玉空。\n主人承湛露。\n元是皋夔侣。\n早晚定遄归。\n商霖四海飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3120, '菩萨蛮', '邓肃', '骑鲸好向云端去。\n踏花偶为狂朋住。\n笑语凛生风。\n眼高四海空。\n羊裘冲雨露。\n我是渔樵侣。\n已趁白鸥归。\n长江自在飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3121, '菩萨蛮', '邓肃', '一心唯欲南园去。\n东山著意留难住。\n曾惯识追风。\n马群今已空。\n金盘盛玉露。\n情绝鸳鸯侣。\n破贼凯还归。\n冲天看一飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3122, '南歌子', '邓肃', '竹影窥灯暗，泉声语夜长。\n小窗无梦到高唐。\n独引三杯长啸、步修廊。\n月午衣衫冷，莲开风露香。\n阑干西角下银潢。\n我欲乘槎天上、泛寒光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3123, '南歌子', '邓肃', '皓月明腮雪，冷风乱鬓云。\n高楼帘幕夜生春。\n半醉倚人秋水、欲斜倾。\n晓雨双溪涨，归舟一叶轻。\n杳无青翼寄殷勤。\n目断烟波渔火、又黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3124, '南歌子', '邓肃', '云绕风前鬓，春开槛里妆。\n凤屏清昼蔼龙香。\n浅画娥眉新样、远山长。\n比翼曾同梦，双鱼隔异乡。\n玉楼依旧暗垂杨。\n楼下落花流水、自斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3125, '南歌子', '邓肃', '驿畔争草，车前自喂牛。\n凤城一别几经秋。\n身在天涯海角、忍回头。\n旅梦惊残月，劳生寄小舟。\n都人应也望宸游。\n早晚葱葱佳气、满皇州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3126, '诉衷情', '邓肃', '乘鸾缥缈过三山。\n游戏下人间。\n金尊不辞频倒，春色上朱颜。\n依暖玉，掠风鬟。\n语关关。\n惟愁漏短，雨散云飞，骑月空还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3127, '诉衷情', '邓肃', '龙头一语定闽山。\n黄色上眉间。\n诏书促归金阙，玉带侍天颜。\n拢象板，宫鬟。\n唱阳关。\n从容禁闼，若念林泉，应寄书还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3128, '诉衷情', '邓肃', '从来云雨过巫山。\n只托梦魂间。\n何如醉逢倾国，春到一瓢颜。\n歌窈窕，舞双鬟。\n掩云关。\n重城五鼓，月下西楼，不忍轻还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3129, '长相思令・长相思', '邓肃', '一重山。\n两重山。\n山远天高烟水寒。\n相思枫叶丹。\n菊花开，菊花残。\n雁已西飞人未还。\n一帘风月闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3130, '长相思令・长相思', '邓肃', '一重溪。\n两重溪。\n溪转山回路欲迷。\n朱阑出翠微。\n梅花飞。\n雪花飞。\n醉卧幽亭不掩扉。\n冷香寻梦归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3131, '长相思令・长相思', '邓肃', '红花飞。\n白花飞。\n郎与春风同别离。\n春归郎不归。\n雨霏霏。\n雪霏霏。\n又是黄昏独掩扉。\n孤灯隔翠帷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3132, '西江月', '邓肃', '腊雪犹埋石，春风已入梅梢。\n冷香随马上琼瑶。\n不与时人同到。\n拍手恐惊星斗，高歌已在烟霄。\n醉呼玉女解金貂。\n笑问何如蓬岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3133, '西江月', '邓肃', '风荐荷香翦翦，月行竹影徐徐。\n微闻环佩过庭除。\n恐是阳台行雨。\n玉笋轻笼乐句，流莺夜转诗馀。\n酒酣风劲露凝珠。\n我欲骖鸾归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3134, '水调歌头', '林淳', '湖波涨新绿，环绕越王山。\n棠斋清昼馀暇，赢得静中观。\n四面屏围碧玉，十里障开云锦，冰鉴倒晴澜。\n目送孤鸿远，心与白鸥闲。\n隘游人，喧鼓吹，杂歌欢。\n晓天澄霁，花羞柳妒怯春寒。\n好在风光满眼，只恐阳春有脚，催诏下天关。\n剩写鹅溪幅，归去凤池看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3135, '水调歌头', '林淳', '疏水绕城郭，农利遍三山。\n使君重本，雅志初不在游观。\n化出玉壶境界，挥洒锦囊词翰，笔下涌波澜。\n天巧无馀蕴，意匠自舒闲。\n拥鳌头，民同乐，颂声欢。\n养花天气，云柔烟腻护朝寒。\n桃李满城阴合，杨柳绕堤绿暗，幽鸟语间关。\n似诉风光好，留与後人看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3136, '水调歌头', '林淳', '螺水亘千古，鳌顶冠三山。\n年丰帅阃尘静，栏槛纵遐观。\n四望潮登浦溆，万顷绿浮原野，堤岸溢波澜。\n畎浍皆沾足，日永桔槔闲。\n肆华筵，鱼鸟乐，众宾欢。\n良辰好景，年年莫放此盟寒。\n且念新湖遗爱，莫作故园遐想，到处是乡关。\n勋业知非晚，聊把镜频看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3137, '菩萨蛮', '林淳', '鹅溪净称烟笼月。\n澄心白称光浮雪。\n净白两俱宜。\n天然浓淡枝。\n花光神意远。\n吮墨含毫浅。\n依约有香来。\n春风随手开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3138, '减字木兰花', '林淳', '嫣然笑粲。\n醉靥融滋春意烂。\n侍宴终宵。\n欢动帘帏酒易消。\n尊前狂客。\n惊见蕊仙新谪籍。\n珠阁深关。\n丹就同归海上山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3139, '减字木兰花', '林淳', '烛花呈灿。\n瑞气满筵春欲烂。\n月色中宵。\n疑是阶前雪未消。\n骚人词客。\n魂断蜡梅香已籍。\n谁更情关。\n一点新愁入远山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3140, '浣溪沙', '林淳', '冒雪休寻访戴船。\n红炉剩宝香然。\n阁儿煨暖两三椽。\n更有玉杯传素手，梅花相对两争妍。\n停杯听唱月娟娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3141, '洞仙歌', '廖行之', '虞弦挥按，甫奏熏风曲。\n两两尧长新绿。\n揖鳌峰、连雁峤，圆融，总里许、北郭门围全属。\n年年才见夏，喜溢榆，龙穴霏烟霭晴谷。\n向氤氲和气里，岁奉瑶觞，试屈指、几阅梅林初熟。\n待一品官高见玄孙，算八十彩衣，更饶遐福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3142, '念奴娇', '廖行之', '薰风庭院，报槐阴拥翠，池波凝绿。\n瑞气葱葱浮燕寝，羽仗霓旌相属。\n开祥，长庚入梦，诧列仙图。\n林泉高迈，肯应轩冕尘俗。\n好是妙舞清歌，浮瓜沈李，荐杯中。\n鹊尾炉生香篆细，又作如何祈祝。\n试问蓬莱，丹崖胜处，几摘蟠桃熟。\n东方何在，凛然能继高躅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3143, '贺新郎', '廖行之', '玉宇□蓬户。\n渺凉声、梧井，乱零枫浦。\n得得西山朝来爽，碧瘦千崖万树。\n清兴在、烟霞深处。\n拄笏风流今谁是，但闻鸡、夜半犹狂舞。\n试举看，渠多许。\n青云万里君夷路。\n肯区区、张兔穴，沈迷金坞。\n流水高山真难料，休把朱弦浪抚。\n任展转、翻云覆雨。\n且对佳时随意乐，更从今、莫问惊人句。\n算万事，总天赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3144, '贺新郎', '廖行之', '修月三千户。\n拥冰轮、同游碧落，问津牛浦。\n上界真仙多才思，乞与瑶阶玉树。\n渺万里、人间何处。\n云叶依依分清荫，忆当时、掩映霓裳舞。\n算万木，宁如许。\n年年萧爽幽岩路。\n倚西风、吹香金粟，超然云坞。\n一洗纷纷凡花尽，堪写清商对抚。\n为豁散、蛮烟瘴雨。\n脱俗高标谁能领，向骚人、正欠题新句。\n须大手，与君赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3145, '水调歌头', '廖行之', '林梢挂弦月，江路粲寒梅。\n一年清绝，好是造物巧安排。\n今日不知何日，佳气更随喜气，满室已春回。\n欢事一时足，黄色两眉开。\n紫髯公，平日事，亦高哉。\n都将功业，分付兰玉满庭阶。\n慈爱浑嗤张傅，信义更高吴李，别是一襟怀。\n岁岁长生酒，剩□紫霞杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3146, '水调歌头', '廖行之', '天下伟人物，荆楚号名流。\n幅员千里，英气磅礴岳南州。\n雁峤高参翼轸，石鼓下盘朱府，衮衮应公侯。\n常记生申旦，明日是中秋。\n挈明月，翳翔凤，驷飞虬。\n东南一尉，何事三载漫淹留。\n谈笑洞庭青草，从此阆风阊阖，高处看鳌头。\n更种阶庭玉，慈母念方稠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3147, '水调歌头', '廖行之', '祥起玉龙甲，庆衍紫枢垣。\n奎文得岁，佳气磅礴斗牛间。\n天意方扶兴运，贤业更看奕世，衮衮照英躔。\n四海具瞻久，膏泽满湘川。\n岁六月，苏大旱，作丰年。\n喁喁百万生齿，何处不沾恩。\n此是鸿钧事业，那更青毡步武，早晚即调元。\n混一车书了，还领赤松仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3148, '水调歌头', '廖行之', '黄色起犀表，紫绶照金章。\n两朝耆德，应是南国旧龚黄。\n曾上方壶蓬岛，万里鲸波不作，炎海赖清凉。\n缓造鸿地，高卧水云乡。\n近新来，春色好，遍潇湘。\n不知今日何日，佳气拥高堂。\n竞把芳尊为寿，细祝遐龄难老，福禄未渠央。\n国栋欠元老，仙桂看诸郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3149, '水调歌头', '廖行之', '凉吹起空阔，疏雨敛轻阴。\n潇湘江上秋色，佳处不胜清。\n拄笏西山一望，气与千崖高爽，天意属奇英。\n威凤下瑶阙，丹桂矗云根。\n汉元侯，流德厚，在云孙。\n金昆玉季，曾共接武上青云。\n堂上瑶池仙姥，庭下芝兰玉树，好事萃于门。\n剩讲经纶事，早晚自公卿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3150, '水调歌头', '廖行之', '苍立箨龙秀，青压雨梅肥。\n清和天气，无限佳景属斯时。\n试听虞弦初理，便有熏兮入奏，风物正熙熙。\n此日定何日，香篆袅金猊。\n记当年，两荚，应熊罴。\n男儿壮志，端在伊傅与皋夔。\n况是从容书史，养就经纶功业，早晚帝王师。\n但了公家事，方与赤松期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3151, '水调歌头', '廖行之', '韩国武中令，公望乃云孙。\n平生壮志，凛凛长剑倚天门。\n郁积胸中谋虑，慷慨尊前谈笑，袖手看风云。\n唾手功名事，诗句自朝昏。\n况高怀，吾所敬，果难能。\n千金生产，一笑推尽与诸昆。\n所至才成辄去，不为区区芥蒂，此意有谁论。\n且举杯中酒，今日是生辰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3152, '沁园春', '廖行之', '直下承当，本来能解，莫遣乾休。\n算如今蹉过，峥嵘岁月，分阴可惜，一日三秋。\n闹里偷声，日中逃影，用尽机关无少留。\n争知道，是沤生即水，水外无沤。\n世人等是悠悠。\n谁著个工夫向里求。\n但掩耳窃钟，将泥洗块，觅花空里，舐蜜刀头。\n何以忙中，尻舆浸假，邀取三彭同载游。\n真如界，向毗庐顶上，荐取无忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3153, '千秋岁', '廖行之', '腊馀时候，天意收寒早。\n梅信动，春先到。\n晓来湘水上，有底风光好。\n春有意，惯随仙仗来蓬岛。\n一念到人间，依约瑶池道。\n心好在，慈为宝。\n蟠桃多岁月，不数如瓜枣。\n千岁也，朱颜绿鬓人难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3154, '青玉案', '廖行之', '片帆稳送扁舟去。\n又还踏、江湖路。\n回首京城旧游处。\n断魂南浦，满怀装恨，别後凭谁诉。\n长歌击剑论心素。\n有志功名未应暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3155, '青玉案', '廖行之', '家山此去无多路。\n久没个、音书去。\n一别而今佳节度。\n黄花开未，白衣到否，篱落荒凉处。\n峥嵘岁月远秋暮。\n空腹便便无好句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3156, '满庭芳', '廖行之', '五甲科名，半生蹭蹬，胸中可谓忘奇。\n荣华外物，算岂是人为。\n自有吾身事业，最难得、□养亲时。\n萱堂好，紫鸾重诰，寿与岳山齐。\n世间，欢乐事，争名蜗角，伐性蛾眉。\n谩须臾变化，苍狗云衣。\n那似千秋寿母，功名事、分付吾儿。\n从今去，捧觞戏彩，双绶更相宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3157, '凤栖梧・蝶恋花', '廖行之', '吾母慈祥膺上寿。\n福庇吾家，近世真希有。\n丘嫂今年逾六九。\n康宁可嗣吾慈母。\n我愿慈闱多福厚。\n更祝遐龄，与母齐长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3158, '凤栖梧・蝶恋花', '廖行之', '破腊先春梅有意。\n管领年华，总在清香蕊。\n不逐浮花红与紫。\n岁寒来寿仙翁醉。\n衮衮诸公名又利。\n谁似高标，摆却人间事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3159, '临江仙', '廖行之', '春意茫茫春色里，又还几度花期。\n淡晴时候尽融怡。\n梅腮翻白後，柳眼弄青时。\n正是江城天气好，楼台灯火星移。\n相逢无处不相宜。\n轻狂行乐处，明月夜深归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3160, '西江月', '廖行之', '绀滑一篙春水，云横几里江山。\n一番烟雨洗晴岚。\n向晓碧天如鉴。\n客枕谩劳魂梦，心旌长系乡关。\n封姨悭与送归帆。\n愁对绿波肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3161, '西江月', '廖行之', '试数阶有几，昨朝看到今朝。\n南薰早动舜琴谣。\n端为熊罴梦兆。\n学粹昔人经制，文高古乐箫韶。\n天风从此上扶摇。\n回首不劳耕钓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3162, '鹧鸪天', '廖行之', '飞尽林花绿叶丝。\n十分春色在荼シ。\n多情几日风朝雨，留恋东风未许归。\n天意好，与君期。\n如今且醉□蛾眉。\n明年上国春风里，赏遍名花得意时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3163, '鹧鸪天', '廖行之', '腊月今朝恰一旬。\n梅花开遍陇头春。\n篆烟起处人称寿，从昔家和福自生。\n新喜事，得佳姻。\n贤郎顺妇正充庭。\n从今更祝千千岁，要与邦人作典型。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3164, '鹧鸪天', '廖行之', '细数元正隔两朝。\n眼看杨柳又新条。\n岁寒独有江梅耐，曾伴瑶池下绛霄。\n香篆袅，烛花烧。\n团栾喜气沸欢谣。\n慈祥自是长生乐，不用春醪与椒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3165, '鹧鸪天', '廖行之', '送了春归雨未收。\n雨肥梅子满枝头。\n心知办此和羹品，正为和羹国手谋。\n两荚，岁千秋。\n崧高神气禀公侯。\n好将一卷周公礼，起佐皇家定九州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3166, '鹧鸪天', '廖行之', '曾宴瑶池万玉宫。\n鸾骖此日自从容。\n杓携鹑首坤维外，岁在降娄虎坎中。\n生指李，寿方瞳。\n云仍今有鹊巢风。\n传家自得长年诀，安用人祈鹤与松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3167, '鹧鸪天', '廖行之', '兰谷清香入岭梅。\n多根应尔暖先回。\n腊前似得真消息，争逐尧十叶开。\n春满室，酒盈杯。\n百花宁许到尊。\n仙姿要是仙家伴，长为遐龄岁一来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3168, '鹧鸪天', '廖行之', '畴昔君王庆诞辰。\n欢传金母下瑶城。\n祗应仙子陪仙仗，却向人间作寿星。\n萧史伴，更和鸣。\n殷勤好嗣太夫人。\n直须同饮长生酒，剩看芝兰照谢庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3169, '卜算子', '廖行之', '云破露新晴，月上输清气。\n最是江城有底佳，灯火人烟沸。\n行乐尽欢娱，眼界尤妍媚。\n多少江滨解佩人，邂逅无穷意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3170, '点绛唇', '廖行之', '屈指家山，匆匆又数今朝过。\n客情那可。\n愁似天来大。\n烟雨，细轻尘堕。\n君知麽。\n却成甚个。\n春暮犹江左。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3171, '点绛唇', '廖行之', '秋兴连天，又还不分秋光老。\n莼鲈犹好。\n莫落秋归後。\n有底从人，上马皆东首。\n君知否。\n阳关三奏。\n消黯情多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3172, '点绛唇', '廖行之', '音信西来，匆匆思作东归计。\n别怀萦系。\n为个人留滞。\n尊酒团栾，莫惜通宵醉。\n还来未。\n满期君至。\n只在初三四。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3173, '点绛唇', '廖行之', '年少清新，襟裾那受红尘污。\n还他礼数。\n莫遣衣冠粗。\n拟倩东风，西逐轮蹄去。\n泠然御。\n飘飘仙趣。\n直到骖鸾处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3174, '点绛唇', '廖行之', '此去何之，骈阗车马朝来起。\n扬鞭西指。\n意气眉间是。\n闾里儿童，竞瞩秦萧史。\n归时几。\n快瞻行李。\n还看如云喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3175, '点绛唇', '廖行之', '玳席华筵，嘉宾环集三千履。\n兰膏芬芷。\n一簇红莲里。\n花覆玉郎，苒苒青衫。\n咸倾企。\n小登科第。\n有底新桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3176, '点绛唇', '廖行之', '玉树芝兰，冰清况有闺房秀。\n画堂如昼。\n相对倾醇酎。\n合卺同牢，二姓欢佳耦。\n凭谁手。\n鬓丝同纽。\n共祝齐眉寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3177, '丑奴儿・采桑子', '廖行之', '一春底事多佳气，非雾非云。\n郁郁氲氲。\n端为君家诞阿兴。\n庆源衮衮由高密，福有多根。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3178, '如梦令', '廖行之', '雨歇凉生枕簟。\n不梦大槐宫殿。\n惟对谪仙人，一笑高情眷眷。\n离恨。\n离恨。\n无奈晓窗鸡啭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3179, '如梦令', '廖行之', '应是南枝向暖。\n那更青春未晚。\n竹外见红腮，芳意与香撩乱。\n肠断。\n肠断。\n无奈东风独占。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3180, '鹧鸪天', '廖行之', '九日东篱已泛觞。\n陇头犹待返魂香。\n那知此日花神约，得得同登君子堂。\n迎腊雪，傲晴霜。\n西湖风韵接柴桑。\n寿潭更酌长生水，岁岁和羹入帝乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3181, '减字木兰花', '廖行之', '相从归去。\n行尽江吴到湘楚。\n欲话离怀。\n万事须凭酒一杯。\n临歧握手。\n赠子一言君听否。\n舌在何忧。\n莫作人间儿女愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3182, '醉落魄・一斛珠', '京镗', '芳尘休扑。\n名花唤我相追逐。\n浅妆不比梅竹。\n深注朱颜，娇面称红烛。\n阿娇合贮黄金屋。\n是谁却遣来空谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3183, '好事近', '京镗', '急雨逐骄阳，洗出长空新月。\n更对银河风露，觉今宵都别。\n不须乞巧拜中庭，枉共天孙说。\n且信平生拙极，耐岁寒霜雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3184, '好事近', '京镗', '杰阁耸层霄，几度晓风残月。\n同是行旧侣，慰十年离别。\n一杯相属莫留残，试倚阑干说。\n趁取簪花绿鬓，未如雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3185, '定风波', '京镗', '何必穿针上彩楼。\n剖瓜插竹诉穷愁。\n闻道天孙相会处，银汉无津，不待泛兰舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3186, '定风波', '京镗', '休卧元龙百尺楼。\n眼高照破古今愁。\n若不擎天为八柱，且学鸱夷，归泛五湖舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3187, '水调歌头', '京镗', '杨卢万人杰，见我眼俱青。\n锦官城里胜概，在在款经行。\n笔底烟云飞走，胸次乾坤吐纳，议论总纵横。\n觉我形秽处，相并玉壶清。\n二使者，弦样直，水般平。\n岷峨洗净凄怆，威与惠相并。\n闻道东来有诏，却恐西留无计，顿使雪山轻。\n滚滚蜀江水，不尽是声名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3188, '满江红', '京镗', '乘兴西来，问谁是、平生相识。\n算惟有、瑶台明月，照人如昔。\n万里清凉银世界，放教千丈冰轮出。\n便招邀、我辈上层楼，横孤笛。\n阴晴事，人难必。\n欢乐处，天常惜。\n幸星稀河澹，云收风息。\n更著两贤陪胜赏，此身如与尘寰隔。\n笑谪仙、对影足成三，空孤寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3189, '满江红', '京镗', '喜见中秋，急载酒、登楼邀月。\n谁料得、狂风作祟，浮云为孽。\n孤负阑干凝望眼，不教宝鉴悬银阙。\n但筵前、依旧舞腰斜，歌喉咽。\n阴与霁，圆并缺，难指准，休分别。\n况赏心乐事，从来磨折。\n常把一尊陪笑语，也胜虚度佳时节。\n怪坡仙、底事太愁生，惊华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3190, '满江红', '京镗', '才近重阳，喜风露、酝成爽气。\n应料有、悲秋情绪，澹妆慵试。\n黄菊篱边开遍否，紫鸿塞外归来未。\n但倚阑、高处望长空，无穷意。\n名利鼎，从渠沸。\n穷达路，非人致。\n又何须咄咄，向空书字。\n西风正好狂吹帽，庾尘那解关吾事。\n纵嬉游、也不学山翁，如泥醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3191, '木兰花慢', '京镗', '算秋来景物，皆胜赏、况重阳。\n正露冷欲霜，烟轻不雨，玉宇开张。\n蜀人从来好事，遇良辰、不肯负时光。\n药市家家帘幕，酒楼处处丝簧。\n婆娑老子兴难忘。\n聊复与平章。\n也随分登高，茱萸缀席，菊蕊浮觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3192, '绛都春', '京镗', '升平似旧。\n正锦里元夕，轻寒时候。\n十里轮蹄，万户帘帷香风透。\n火城灯市争辉照。\n谁撒□、满空星斗。\n玉箫声里，金莲影下，月明如画。\n知否。\n良辰美景，□丰岁乐国，从来希有。\n坐上两贤，白玉为山联翩秀。\n笙歌一片围红袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3193, '满江红', '京镗', '锦里先生，草堂筑、浣花溪上。\n料饱看、阶前雀食，篱边渔网。\n跨鹄骑鲸归去後，桥西潭北留佳赏。\n况依然、一曲抱村流，江痕涨。\n鱼龙戏，相浩荡。\n禽鸟乐，增舒畅。\n更绮罗十里，棹歌来往。\n上坐英贤今李郭，邦人应作仙舟想。\n但□呼、落日未西时，船休放。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3194, '念奴娇', '京镗', '扪参历井，恰匆匆三见，西州七夕。\n怪得骄阳回避晚，犹去新秋两日。\n天上良宵，人间佳节，初不分今昔。\n夜来急雨，洗成风露清绝。\n因念万里飘零，君平何在，谁识乘槎客。\n插竹剖瓜休妄想，巧处那容人乞。\n院宇初凉，楼台不夜，漫说经年隔。\n引杯长啸，醉看天地空阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3195, '水调歌头', '京镗', '明月四时好，何事喜中秋。\n瑶台宝鉴，宜挂玉宇最高头。\n放出白毫千丈，散作太虚一色，万象入吾眸。\n星斗避光彩，风露助清幽。\n等闲来，天一角，岁三周。\n东奔西走，在处依旧若从游。\n照我尊前只影，催我镜中华发，蟾兔漫悠悠。\n连璧有佳客，乘兴且登楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3196, '洞仙歌', '京镗', '三年锦里，见重阳药市。\n车马喧阗管弦沸。\n笑篱边孤寂，台上疏狂，争得似，此日西南都会。\n痴儿官事了，乐与民同，况值高秋好天气。\n□不羞华发，不照衰颜，聊满插、黄花一醉。\n道物外、高人有时来，问混杂龙蛇，个中谁是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3197, '水龙吟', '京镗', '夜来井络参躔，使星一点明如昼。\n谁将天上麒麟，锺作人间英秀。\n从橐仪刑，御屏名姓，暂烦衣绣。\n问西川父老，新来喜跃，缘何事、曾知否。\n今代澄清妙手。\n为公家、忧心如疚。\n几年繁赋，一朝输代，恩民特厚。\n初度佳辰，恰逢长至，从来希有。\n但只将一部，欢声百万，与公为寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3198, '汉宫春', '京镗', '看透尘寰。\n更禅心似水，道力如山。\n前身青冥跨鹄，紫府乘鸾。\n世缘一念，便等闲、游戏人间。\n须信道，云霄步武，不应权牧西南。\n此日重临初度，正绣衣辉映，彩服斓斑。\n人生显途易到，容养难攀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3199, '汉宫春', '京镗', '暖律初回。\n又烧灯市井，卖酒楼台。\n谁将星移万点，月满千街。\n轻车细马，隘通衢、蹴起香埃。\n今岁好，土牛作伴，挽留春色同来。\n不是天公省事，要一时壮观，特地安排。\n何妨彩楼鼓吹，绮席尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3200, '洞仙歌', '京镗', '东皇著意，妙出妆春手。\n点缀名花胜於绣。\n向鱼凫国里，琴鹤堂前，仍共赏，蜀锦堆红炫昼。\n娇娆真绝艳，尽是天然，莫恨无香欠檀口。\n幸今年风雨，不苦摧残，还肯为、游人再三留否。\n算魏紫姚黄号花王，若定价收名，未应居右。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3201, '念奴娇', '京镗', '锦城城北，有平湖、仿佛西湖西畔。\n载酒郊修禊事，雅称兰舟同泛。\n麦垅黄轻，桤林绿重，莫厌春光晚。\n棹歌声发，飞来鸥鹭惊散。\n好是水涨弥漫，山围周币，不尽青青岸。\n除却钱塘门外见，只说此间奇观。\n句引游人，追陪佳客，三载成留恋。\n古今陈迹，从教分付弦管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3202, '满江红', '京镗', '雨後晴初，觉春在、桤村柳陌。\n修禊事、郊寻胜，特邀君出。\n缭绕群山疑虎踞，弥漫一水容鲸吸。\n怪西湖、底事却移来，龟城北。\n酬令节，逢佳日。\n风递暖，烟凝碧。\n趁兰舟游玩，尽杯中物。\n十里轮蹄尘不断，几多粉黛花无色。\n笑杜陵、昔赋丽人行，空遗迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3203, '念奴娇', '京镗', '郎闱夙望，问何因袖手，双流溪畔。\n忆昔班行曾接武，今喜一尊同泛。\n骥枥难淹，鹏程方远，大器成须晚。\n等闲访我，又惊云雨分散。\n最是游子悲乡，小人怀土，梦绕江南岸。\n楚尾吴头家住处，满自山川遐观。\n归兴虽浓，俞音尚，此地非贪恋。\n东西惟命，去留迟速休管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3204, '水调歌头', '京镗', '百堞龟城北，江势远连空。\n杠梁济涉，浑似溪涧饮长虹。\n覆以飞华宇，载以鱼浮叠石，守护有神龙。\n好看发源水，滚滚尽流东。\n司马氏，凌云气，盖群公。\n当年题柱，从此奏赋动天容。\n果驾轺车使蜀，能致诸蛮臣汉，邛道仍通。\n寄语登桥者，努力继前功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3205, '念奴娇', '京镗', '绣天锦地，浣花溪风物，尤为奇绝。\n无限兰舟相荡漾，缯彩重重装结。\n冀国遗踪，杜陵陈迹，疑信俱休说。\n笙歌丛里，旌旗光映林樾。\n自笑与蜀缘多，沧浪亭下，饱看烟波阔。\n屡疏求归才请得，知我家山心切。\n已是行人，犹陪佳客，莫放回船发。\n来年今日，相思惟共明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3206, '洞庭春色・沁园春', '京镗', '命驾访嵇，泛舟思戴，此兴甚浓。\n料情侔杨恽，乌乌拊缶，意轻殷浩，咄咄书空。\n莫讶群芳淹速异，到时序推排元自同。\n休怅望，任春来桃李，秋後芙蓉。\n因嗟锦城四载，漫赢得、齿豁头童。\n叹里门密迩，易成间阔，诗筒频寄，难续新工。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3207, '满江红', '京镗', '雨洗新秋，遣凉意、驱除残暑。\n还又是、天孙河鼓，一番相遇。\n银汉桥成乌鹊喜，金奁丝巧蜘蛛吐。\n见几多、结彩拜楼前，穿针女。\n舟楫具，将归去。\n尊俎胜，休匆遽。\n被西川七夕，四回留住。\n此地关心能几辈，他年会面知何处。\n更倚阑、豪饮莫辞频，歌金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3208, '贺新郎', '京镗', '试与娥语。\n问因何、年年此夜，月明如许。\n万顷熔成银世界，是处玉壶风露。\n又岂比、寻常三五。\n变化乾坤同一色，觉星躔、斗柄皆回互。\n须要我，共分付。\n平生脚踏红尘处。\n漫纷纷、鸡虫厚薄，燕鸿来去。\n只有婵娟多情在，依旧当时雅素。\n空自叹、归心难住。\n留取清光岷江畔，照扁舟、送我章江路。\n频引满，莫匆遽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3209, '雨中花・夜行船', '京镗', '玉局祠前，铜壶阁畔，锦城药市争奇。\n正紫萸缀席，黄菊浮卮。\n巷陌联镳并辔，楼台吹竹弹丝。\n登高望远，一年好景，九日佳期。\n自怜行客，犹对佳宾，留连岂是贪痴。\n谁会得、心驰北阙，兴寄东篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3210, '雨中花・夜行船', '京镗', '跨鹤仙姿，掣鲸老手，从来眼赤腰黄。\n更词源峡水，才刃干将。\n处处欢谣载路，时时秀句盈囊。\n牛头山畔，烦公敛惠，许我分光。\n逢迎锦里，话旧从容，谁知各整行装。\n况正好、登高怀古，择胜寻芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3211, '瑞鹤仙', '京镗', '鸳行旧俦侣。\n问底事、迟回西州西处。\n闲居久如许。\n相邻翁对饮，诗人联句。\n夤缘会遇。\n过高轩、相逢喜舞。\n正菊天、景物澄鲜，切莫趣归言去。\n看取。\n星扉月户。\n雾阁云窗，非公孰住。\n从容笑语。\n人生易别难聚。\n恨分违有日，留连无计，满目离愁忍觑。\n若他时、鱼雁南来，把书寄与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3212, '水调歌头', '京镗', '身去日华远，举首望长安。\n四年留蜀，那复有梦到金銮。\n遥想将芜三径，自笑己穷五技，无语倚阑干。\n欲作天涯别，犹对俎尊闲。\n秋意晚，风色厉，叶声乾。\n阳关三叠缓唱，一醉且酡颜。\n聚散燕鸿南北，得失触蛮左右，莫较去仍还。\n後日相思处，烟水与云山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3213, '水龙吟', '京镗', '四年留蜀惭无补，好是求归得去。\n风帆百尺，烟波万里，宁辞掀舞。\n楚尾吴头，我家何在，西山南浦。\n想珠帘画栋，倚阑凝望，依然卷云飞雨。\n最好九霞光处。\n见当时、结知明主。\n冰霜节操，斗星词采，羽仪朝路。\n邂逅开怀，等闲分手，满斟绿醑。\n道日边好语，相将飞下，有人知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3214, '满江红', '京镗', '外省抡才，诏书下、芝泥犹湿。\n应料得、出奇锦绣，争辉金碧。\n三级浪高鱼已化，九霄路远鹏方息。\n有宗工、此地独持衡，将专席。\n岁月晚，霜风急。\n嗟老子，为行客。\n念昔陪班缀，今亲辞色。\n握手方成同社款，消魂又作歧亭别。\n也不须、因赋大刀头，归心折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3215, '念奴娇', '京镗', '文章太守，问何事、犹带天庭黄色。\n上界一时官府足，聊下神仙宫阙。\n剖竹新游，握兰旧梦，此意谁人识。\n千军笔阵，争先曾夺矛槊。\n好是万里相逢，一尊同醉，倾吐平边策。\n聚散人生浑惯见，莫为分襟呜咽。\n借箸机筹，著鞭功业，只合从君说。\n明朝回首，天涯何处风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3216, '水调歌头', '京镗', '衮衮长江水，策策晓霜风。\n求归得请，特地送我布帆东。\n出处何关轻重，去住不拘淹速，社燕与秋鸿。\n父老休相恋，四载愧无功。\n谁知有，楼百尺，卧元龙。\n来从天上，一麾游戏斗牛中。\n闻道君王前席，见说从臣虚位，变化待鲲鸿。\n一笑同锦里，万事付金锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3217, '水龙吟', '京镗', '推移随牒红尘里，试问几时肩息。\n家乡何在，烟迷波渺，云横山屹。\n分阃无功，临民有愧，裤今襦昔。\n想征帆万里，阳关三叠，肠空断、人谁忆。\n多谢殷勤绮席。\n苦留连、不容浮。\n九霞光外，五云深畔，君宜鹄立。\n自笑衰迟，未能轩轾，漫劳嘘吸。\n愿锋车趣召，吴天楚地，相逢他日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3218, '酹江月・念奴娇', '京镗', '蟆颐江畔，问收拾多少，山光水色。\n此是朝宗东去路，准拟鸣鼍浮。\n儒馆英游，侯藩贤望，便合还丹极。\n九重渴想，甘泉闻道虚席。\n因念北阙同朝，西州联事，久矣心相得。\n邂逅天涯拼一笑，洗我尘胸俗臆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3219, '水调歌头', '京镗', '与蜀有缘法，见我眼俱青。\n征车到处，弦管无限作离声。\n自笑四年留滞，漫说三边安静，分阃愧长城。\n一念天地阔，万事羽毛轻。\n欲归去，诗入社，酒寻盟。\n双鬓，老矣祗觉壮心惊。\n虽是东西惟命，已断行藏在己，何必问君平。\n举似铜梁守，怀抱好同倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3220, '水调歌头', '京镗', '雪岭倚空白，霜柏傲寒青。\n千岩万壑奇秀，禽鸟寂无声。\n好是群贤四集，同访宝仙九室，中有玉京城。\n眼底尘嚣远，胸次利名轻。\n云山旁，烟水畔，肯渝盟。\n传呼休要喝道，方外恐猜惊。\n雅羡林泉胜概，倘遂田园归计，志愿足平生。\n此意只自解，聊复为君倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3221, '水调歌头', '京镗', '数月已办去，今日始成行。\n天公怜我，特地趁晓作霜晴。\n万里奔驰为米，四载淹留为豆，自笑太劳生。\n父老漫遮道，抚字愧阳城。\n君有命，难俟驾，合兼程。\n故山心切，猿鹤应是怨仍惊。\n多谢使华追路，不忍客亭分袂，已醉酒犹倾。\n莫久西南往，汉代急公卿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3222, '满江红', '京镗', '道骨仙风，合笞凤、鞭鸾归去。\n底事为、三峨九顶，等闲留住。\n揽辔聊施经济手，凝旒屡出褒嘉语。\n算只今、人物更谁归，心如许。\n嗟我拙，才不武。\n惭我陋，文非古。\n纵策迟鞭钝，也难追步。\n虽喜故人逢异县，却嫌游子贪行路。\n但著公、西掖北门中，相期处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3223, '水调歌头', '京镗', '四载分蜀阃，万里下吴樯。\n老怀易感，厌听催别笛横羌。\n自愧谋非经远，更笑才非任剧，安得召公棠。\n有志但碌碌，无绩可章章。\n汉嘉守，明似月，洁如霜。\n邦人鼓舞，爱戴惟恐趣归忙。\n况是水曹宗派，仍得苏州句法，燕寝昼凝香。\n且趁东风去，步武近明光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3224, '水调歌头', '京镗', '挺挺祖风烈，再岁滞偏州。\n元龙豪气，宜卧百尺最高楼。\n万丈文章光焰，一段襟怀洒落，风露玉壶秋。\n乱石惊涛处，也作等闲游。\n适相逢，君去骑，我归舟。\n清都绛阙密迩，切莫小迟留。\n趁取亲庭强健，好向圣朝倾吐，事业肯悠悠。\n回首藩宣地，恩与大江流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3225, '蝶恋花', '张震', '梅子初青春已暮。\n芳草连云，绿遍西池路。\n小院绣垂帘半举。\n衔泥紫燕双飞去。\n人在赤阑桥畔住。\n不解伤春，还解相思否。\n清梦欲寻犹间阻。\n沙窗一夜萧萧雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3226, '鹧鸪天', '张震', '宽尽香罗金缕衣。\n心情不似旧家时。\n万丝柳暗才飞絮，一点梅酸已着枝。\n金底背，玉东西。\n前欢赢得两相思。\n伤心不及风前燕，犹解穿帘度幕飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3227, '鹧鸪天', '张震', '横素桥边景最佳。\n绿波清浅见琼沙。\n衔泥燕子迎风絮，得食鱼儿趁浪花。\n春已暮，日初斜。\n画船箫鼓是谁家。\n兰桡欲去空留恋，醉倚阑干看晚霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3228, '蓦山溪', '张震', '青梅如豆，断送春归去。\n小绿间长红，看几处、云歌柳舞。\n偎花识面，对月共论心，携素手，采香游，踏遍西池路。\n水边朱户。\n曾记销魂处。\n小立背秋千，空怅望、娉婷韵度。\n杨花扑面，香糁一帘风，情脉脉，酒厌厌，回首斜阳暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3229, '蓦山溪', '张震', '春光如许。\n春到江南路。\n柳眼弄晴晖，笑梅老、落英无数。\n峭寒庭院，罗幕护窗纱，金鸭暖，锦屏深，曾记看承处。\n云边尺素。\n何计传心缕。\n无处说相思，空惆怅、朝云暮雨。\n曲阑干外，小立近黄昏，心下事，眼边愁，借问春知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3230, '水调歌头', '张', '雨後烟景绿，春水涨桃花。\n系舟溪上，笋舆十里达平沙。\n路转峰回胜处，无数青荧玉树，飘缈羽人家。\n楼观倚空碧，水竹湛清华。\n纵幽寻，携蜡屐，上苍霞。\n古仙何在，空馀药灶委岩洼。\n他日倘然归老，乞取一庵云卧，随分了生涯。\n底用更辛苦，九转炼黄芽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3231, '蝶恋花', '王炎2', '纤手行杯红玉润。\n满眼花枝，雨过胭脂嫩。\n新月一眉生浅晕。\n酒阑无奈添春困。\n唤起醉魂君不问。\n憔悴颜容，羞与花相近。\n人自无情花有韵。\n风光易老何须恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3232, '蝶恋花', '王炎2', '柳暗西湖春欲暮。\n无数青丝，不系行人住。\n一点心情千万绪。\n落花寂寂风吹雨。\n唤起声中人独睡。\n千里明驼，不踏山间路。\n谩道遣愁除是醉。\n醉还易醒愁难去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3233, '点绛唇', '王炎2', '雨湿东风，谁家燕子穿庭户。\n孤村薄暮。\n花落春归去。\n浪走天涯，归思萦心绪。\n家何处。\n乱山无数。\n不记来时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3234, '水调歌头', '王炎2', '江月冷如水，江水碧於空。\n晚来一霎过雨，为我洗秋容。\n悄悄四山人静，凛凛三更露下，天阔叫孤鸿。\n唤醒蓬窗梦，身在水晶宫。\n揖湘妃，招月娣，御清风。\n素琴韵远，不觉醉眼杏花红。\n禹穴骑鲸仙去，东海钓鳌人远，此意与谁同。\n倚柁一长啸，出壑舞鱼龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3235, '水调歌头', '王炎2', '千里倦游客，老眼厌尘烟。\n蒸湘平远，他处无此好江山。\n把酒一听乃，过了黄花时节，水国倍生寒。\n输与沧浪叟，长伴白鸥闲。\n傍江亭，穷杳霭，踞岩。\n水深石冷，闻道别有洞中天。\n待倩灵妃调曲，唤起冯夷短舞，从此问群仙。\n云海渺无际，波涌缓移船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3236, '念奴娇', '王炎2', '小妆朱槛，护秋英千点，金钿如簇。\n黄叶白苹朝露冷，只有孤芳幽馥。\n华发苍头，宦情羁思，来伴花幽独。\n巡檐无语，清愁何啻千斛。\n因念爱酒渊明，东篱雅意，千载无人续。\n身在花边须一醉，小覆杯中。\n过了重阳，捻枝嗅蕊，休叹年华速。\n明年春到，陈根更有新绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3237, '鹧鸪天', '王炎2', '淡淡疏疏不惹尘。\n暗香一点静中闻。\n人间怪有晴时雪，天上偷回腊里春。\n疑浅笑，又轻颦。\n虽然无语意相亲。\n老来尚可花边饮，惆怅相携失玉人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3238, '西江月', '辛弃疾', '一柱中擎远碧，两峰旁依高寒。\n横陈削就短长山。\n莫把一分增减。\n我望云烟目断，人言风景天悭。\n被公诗笔尽追还。\n更上层楼一览。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3239, '西江月', '辛弃疾', '堂上谋臣帷幄，边头猛将干戈。\n天时地利与人和。\n燕可伐与曰可。\n此日楼台鼎鼐，他时剑履山河。\n都人齐和大风歌。\n管领群臣来贺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3240, '生查子', '辛弃疾', '青山招不来，偃蹇谁怜汝。\n岁晚太寒生，唤我溪边住。\n山头明月来，本在高高处。\n夜夜入清溪，听读离骚去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3241, '生查子', '辛弃疾', '高人千丈崖，千古储冰雪。\n六月火云时，一见森毛发。\n俗人如盗泉，照眼多昏浊。\n高处挂吾瓢，不饮吾宁渴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3242, '卜算子', '辛弃疾', '盗跖傥名丘，孔子还名跖。\n跖圣丘愚直至今，美恶无真实。\n简册写虚名，蝼蚁侵枯骨。\n千古光阴一霎时，且进杯中物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3243, '卜算子', '辛弃疾', '一个去学仙，一个去学佛。\n仙饮千杯醉似泥，皮骨如金石。\n不饮便康强，佛寿须千百。\n八十馀年入涅，且进杯中物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3244, '卜算子', '辛弃疾', '一饮动连宵，一醉长三日。\n废尽寒暄不写书，富贵何由得。\n请看冢中人，冢似当时笔。\n万札千书只恁休，且进杯中物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3245, '卜算子', '辛弃疾', '刚者不坚牢，柔者难摧挫。\n不信张开口了看，舌在牙先堕。\n已阙两边厢，又豁中间个。\n说与儿曹莫笑翁，狗窦从君过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3246, '卜算子', '辛弃疾', '一以我为牛，一以吾为马。\n人与之名受不辞，善学庄周者。\n江海任虚舟，风雨从飘瓦。\n醉者乘车坠不伤，全得於天也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3247, '卜算子', '辛弃疾', '夜雨醉瓜庐，春水行秧马。\n点检田间快活人，未有如翁者。\n秃尽兔豪锥，磨透铜台瓦。\n谁伴扬雄作解嘲，乌有先生也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3248, '卜算子', '辛弃疾', '珠玉作泥沙，山谷量牛马。\n试上累累丘垅看，谁是强梁者。\n水浸浅深檐，山压高低瓦。\n山水朝来笑问人，翁早归来也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3249, '卜算子', '辛弃疾', '千古李将军，夺得胡儿马。\n李蔡为人在下中，却是封侯者。\n芸草去阵根，笕竹添新瓦。\n万一朝家举力田，舍我其谁也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3250, '哨遍', '辛弃疾', '池上主人，人适忘鱼，鱼适还忘水。\n洋洋乎，翠藻青萍里。\n想鱼兮、无便於此。\n尝试思，庄周正谈两事。\n一明豕虱一羊蚁。\n说蚁慕於膻，於蚁弃知，又说於羊弃意。\n甚虱焚於豕独忘之。\n却骤说於鱼为得计。\n千古遗文，我不知言，以我非子。\n子固非鱼，噫。\n鱼之为计子焉知。\n河水深且广，风涛万倾堪依。\n有网罟如云，鹈鹕成阵，过而留泣计应非。\n其外海茫茫，下有龙伯，饥时一啖千里。\n更任公五十为饵。\n使海上人人厌腥味。\n似鲲鹏、变化能几。\n东游入海，此计直以命为嬉。\n古来谬算狂图，五鼎烹死，指为平地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3251, '兰陵王', '辛弃疾', '恨之极。\n恨极销磨不得。\n苌弘事，人道後来，其血三年化为碧。\n郑人缓也泣。\n吾父攻儒助墨。\n十年梦，沈痛化余，秋柏之间既为实。\n相思重相忆。\n被怨结中肠，潜动精魄。\n望夫江上岩岩立。\n嗟一念中变，後期长绝。\n君看启母愤所激。\n又俄倾为石。\n难敌。\n最多力。\n甚一忿沈渊，精气为物。\n依然困斗牛磨角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3252, '贺新郎', '辛弃疾', '著厌霓裳素。\n染胭脂、苎罗山下，浣沙溪渡。\n谁与流霞千古酝，引得东风相误。\n从臾入、吴宫深处。\n鬓乱钗横浑不醒，转越江、地迷归路。\n烟艇小，五湖去。\n当时倩得春留住。\n就锦屏一曲，种种断肠风度。\n才是清明三月近，须要诗人妙句。\n笑援笔、殷勤为赋。\n十样蛮笺纹错绮，粲珠玑、渊掷惊风雨。\n重唤酒，共花语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3253, '贺新郎', '辛弃疾', '碧海成桑野。\n笑人间，江翻平陆，水云高下。\n自是三山颜色好，更著雨婚烟嫁。\n料未必、龙眠能画。\n拟向诗人求幼妇，倩诸君、妙手皆谈马。\n须进酒，为陶写。\n回头鸥鹭瓢泉社。\n莫吟诗、莫抛尊酒，是吾盟也。\n千骑而今遮白发，忘却沧浪亭榭。\n但记得、灞陵呵夜。\n我辈从来文字饮，怕壮怀、激烈须歌者。\n蝉噪也，绿阴夏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3254, '贺新郎', '辛弃疾', '鸟倦飞还矣。\n笑渊明、瓶中储粟，有无能几。\n莲社高人留翁语，我醉宁论许事。\n试沽酒、重斟翁喜。\n一见箫然音韵古，想东篱、醉卧参差是。\n千载下，竟谁似。\n元龙百尺高楼里。\n把新诗、殷勤问我，停云情味。\n北夏门高从拉，何事须人料理。\n翁曾道、繁华朝起。\n尘土人言宁可用，顾青山、与我何如耳。\n歌且和，楚狂子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3255, '贺新郎', '辛弃疾', '肘後俄生柳。\n叹人生、不如意事，十常八九。\n右手淋浪才有用，闲却持螯左手。\n谩赢得、伤今感旧。\n投阁先生惟寂寞，笑是非、不了身前後。\n持此语，问乌有。\n青山幸自重重秀。\n问新来、萧萧木落，颇堪秋否。\n总被西风都瘦损，依旧千岩万岫。\n把万事、无言搔首。\n翁比渠侬人谁好，是我常、与我周旋久。\n宁作我，一杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3256, '念奴娇', '辛弃疾', '风狂雨横，是邀勒园林，几多桃李。\n待上层楼无气力，尘满栏干谁倚。\n就火添衣，移香傍枕，莫卷朱帘起。\n元宵过也，春寒犹自如此。\n为问几日新晴，鸠鸣屋上，鹊报檐前喜。\n揩试老来诗句眼，要看拍堤春水。\n月下凭肩，花边系马，此兴今休矣。\n溪南酒贱，光阴只在弹指。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3257, '念奴娇', '辛弃疾', '洞庭春晚，旧传恐是，人间尤物。\n收拾瑶池倾国艳，来向朱栏一壁。\n透户龙香，隔帘莺语，料得肌如血。\n月妖真态，是谁教避人杰。\n酒罢归对寒窗，相留昨夜，应是梅花发。\n赋了高唐犹想像，不管孤灯明灭。\n半面难期，多情易感，愁点星星发。\n绕梁声在，为伊忘味三月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3258, '念奴娇', '辛弃疾', '是谁调护，岁寒枝、都把苍苔封了。\n茅舍疏篱江上路，清夜月高山小。\n摸索应知，曹刘沈谢，何况霜天晓。\n芬芳一世，料君长被花恼。\n惆怅立马行人，一枝最爱，竹外横斜好。\n我向东邻曾醉里，唤起诗家二老。\n拄杖而今，婆娑雪里，又识商山皓。\n请君置酒，看渠与我倾倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3259, '沁园春', '辛弃疾', '老子平生，笑尽人间，儿女怨恩。\n况白头能几，定应独往，青云得意，见说长存。\n抖擞衣冠，怜渠无恙，合挂当年神武门。\n都如梦，算能争几许，鸡晓钟昏。\n此心无有新冤。\n况抱瓮年来自灌园。\n但凄凉顾影，频悲往事，殷勤对佛，欲问前因。\n却怕青山，也妨贤路，休斗尊前见在身。\n山中友，试高吟楚些，重与招魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3260, '沁园春', '辛弃疾', '有美人兮，玉佩琼踞，吾梦见之。\n问斜阳犹照，渔樵故里，长桥谁记，今故期思。\n物化苍茫，神游仿佛，春与猿吟秋鹤飞。\n还惊笑，向晴波忽见，千丈虹霓。\n觉来西望崔嵬。\n更上有青枫下有溪。\n待空山自荐，寒泉秋菊，中流却送，桂棹兰旗。\n万事长嗟，百年双鬓，吾非斯人谁与归。\n凭阑久，正清愁未了，醉墨休题。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3261, '沁园春', '辛弃疾', '我试评君，君定何如，玉川似之。\n记李花初发，乘云共语，梅花开後，对月相思。\n白发重来，画桥一望，秋水长天孤鹜飞。\n同吟处，看佩摇明月，衣卷青霓。\n相君高节崔嵬。\n是此处耕岩与钓溪。\n被西风吹尽，村箫社鼓，青山留得，松盖云旗。\n吊古愁浓，怀人日暮，一片心从天外归。\n新词好，似凄凉楚些，字字堪题。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3262, '沁园春', '辛弃疾', '我醉狂吟，君作新声，倚歌和之。\n算芬芳定向，梅间得意，轻清多是，雪里寻思。\n朱雀桥边，何人会道，野草斜阳春燕飞。\n都休问，甚元无霁雨，却有晴霓。\n诗坛千丈崔嵬。\n更有笔如山墨作溪。\n看君才未数，曹刘敌手，风骚合受，屈宋降旗。\n谁识相如，平生自许，慷慨须乘驷马归。\n长安路，问垂虹千柱，何处曾题。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3263, '水调歌头', '辛弃疾', '落日古城角，把酒劝君留。\n长安路远，何事风雪敝貂裘。\n散尽黄金身世，不管秦楼人怨，归计狎沙鸥。\n明夜扁舟去，和月载离愁。\n功名事，身未老，几时休。\n诗书万卷，致身须到古伊周。\n莫学班超投笔，纵得封侯万里，憔悴老边州。\n何处依刘客，寂寞赋登楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3264, '水调歌头', '辛弃疾', '官事未易了，且向酒边来。\n君如无我，问君怀抱向谁开。\n但放平生丘壑，莫管旁人嘲骂，深蛰要惊雷。\n白发还自笑，何地置衰颓。\n五车书，千古饮，百篇才。\n新词未到，琼瑰先梦满吾怀。\n已过西风重九，且要黄花入手，诗兴未关梅。\n君要花满县，桃李趁时栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3265, '水调歌头', '辛弃疾', '千里渥洼种，名动帝王家。\n金銮当日奏草，落笔万龙蛇。\n带得无边春下，等待江山都老，教看鬓方鸦。\n莫管钱流地，且拟醉黄花。\n唤双成，歌弄玉，舞绿华。\n一觞为饮千岁，江海吸流霞。\n闻道清都帝所，要挽银河仙浪，西北洗胡沙。\n回首日边去，云里认飞车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3266, '水调歌头', '辛弃疾', '千古老蟾口，云洞插天开。\n涨痕当日何事，汹涌到崔嵬。\n攫土抟沙儿戏，翠谷苍崖几变，风雨化人来。\n万里须臾耳，野马骤空埃。\n笑年来，蕉鹿梦，画蛇杯。\n黄花憔悴风露，野碧涨荒莱。\n此会明年谁健，後日犹今视昔，歌舞只空台。\n爱酒陶元亮，无酒正徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3267, '水调歌头', '辛弃疾', '文字觑天巧，亭榭定风流。\n平生丘壑，岁晚也作稻粱谋。\n五亩园中秀野，一水田将绿绕，不胜秋。\n饭饱对花竹，可是便忘忧。\n吾老矣，探禹穴，欠东游。\n君家风月几许，白鸟去悠悠。\n插架牙签万轴，射虎南山一骑，容我揽不。\n更欲劝君酒，百尺卧高楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3268, '水调歌头', '辛弃疾', '日月如磨蚁，万事且浮休。\n君看檐外江水，滚滚自东流。\n风雨瓢泉夜半，花草雪楼春到，老子已菟裘。\n岁晚问无恙，归计橘千头。\n梦连环，歌弹铗，赋登楼。\n黄鸡白酒，君去村社一番秋。\n长剑倚天谁问，夷甫诸人堪笑，西北有神州。\n此事君自了，千古一扁舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3269, '水调歌头', '辛弃疾', '说与西湖客，观水更观山。\n淡妆浓抹西子，唤起一时观。\n种柳人今天上，对酒歌翻水调，醉墨卷秋澜。\n老子兴不浅，歌舞莫教闲。\n看尊前，轻聚散，少悲欢。\n城头无限今古，落日晓霜寒。\n谁唱黄鸡白酒，犹记红旗清夜，千骑月临关。\n莫说西州路，且尽一杯看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3270, '水调歌头', '辛弃疾', '万事一杯酒，长叹复长歌。\n杜陵有客，刚赋云外筑婆娑。\n须信功名儿辈，谁识年来心事，古井不生波。\n种种看余发，积雪就中多。\n二三子，问丹桂，倩素娥。\n平生萤雪，男儿无奈五车何。\n看取长安得意，莫恨春风看尽，花柳自蹉砣。\n今夕且欢笑，明月镜新磨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3271, '水调歌头', '辛弃疾', '岁岁有黄菊，千载一东篱。\n悠然政须两字，长笑退之诗。\n自古此山元有，何事当时才见，此意有谁知。\n君起更斟酒，我醉不须辞。\n回首处，云正出，鸟倦飞。\n重来楼上，一句端的与君期。\n都把轩窗写遍，更使儿童诵得，归去来兮辞。\n万卷有时用，植杖且耘耔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3272, '水调歌头', '辛弃疾', '渊明最爱菊，三径也栽松。\n何人收拾，千载风味此山中。\n手把离骚读遍，自扫落英餐罢，杖屦晓霜浓。\n皎皎太独立，更插万芙蓉。\n水潺，云洞，石。\n素琴浊酒唤客，端有古人风。\n却怪青山能巧，政尔横看成岭，转面已成峰。\n诗句得活法，日月有新工。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3273, '满江红', '辛弃疾', '美景良辰，算只是、可人风月。\n况素节扬辉，长是十分清彻。\n著意登楼瞻玉兔，何人张幕遮银阙。\n倩飞帘、得得为吹开，凭谁说。\n弦与望，从园缺。\n今与昨，何区别。\n羡夜来手把，桂花堪折。\n安得便登天柱上，从容陪伴酬佳节。\n更如今，不听麈谈清，愁如发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3274, '满江红', '辛弃疾', '点火樱桃，照一架、荼シ如雪。\n春正好，见龙孙穿破，紫苔苍壁。\n乳燕引雏飞力弱，流莺唤友娇声怯。\n问春归、不肯带愁归，肠千结。\n层楼望，春山叠。\n家何在，烟波隔。\n把古今遗恨，向他谁说。\n蝴碟不传千里梦，子规叫断三更月。\n听声声、枕上劝人归，归难得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3275, '满江红', '辛弃疾', '汉水东流，都洗尽、髭胡膏血。\n人尽说、君家飞将，旧时英烈。\n破敌金城雷过耳，谈兵玉帐冰生颊。\n想王郎、结发赋从戎，传遗业。\n腰间剑，聊弹铗。\n尊中酒，堪为别。\n况故人新拥，汉坛旌节。\n马革裹尸当自誓，蛾眉伐性休重说。\n但从今、记取楚楼风，裴台月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3276, '满江红', '辛弃疾', '风卷庭梧，黄叶坠、新凉如洗。\n一笑折、秋英同赏，弄香蕊。\n天远难穷休久望，楼高欲下还重倚。\n拼一襟、寂寞泪弹秋，无人会。\n今古恨，沈荒垒。\n悲欢事，随流水。\n想登楼青鬓，未堪憔悴。\n极目烟横山数点，孤舟月淡人千里。\n对婵娟、从此话离愁，金尊里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3277, '满江红', '辛弃疾', '紫陌飞尘，望十里、雕鞍绣毂。\n春未老、已惊台榭，瘦红肥绿。\n睡雨海棠犹倚醉，舞风杨柳难成曲。\n问流莺、能说故园无，曾相熟。\n岩泉上，飞凫浴。\n巢林下，栖禽宿。\n恨荼シ开晚，谩翻船玉。\n莲社岂堪谈昨梦，兰亭何处寻遗墨。\n但羁怀、空自倚秋千，无心蹴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3278, '满江红', '辛弃疾', '汉节东南，看驷马、光华周道。\n须信是、七闽还有，福星来到。\n庭草自生心意足，榕阴不动秋光好。\n问不知，何处著君侯，蓬莱岛。\n还自笑，人今老。\n空有恨，萦怀抱。\n记江湖十载，厌持旌纛。\n落我材无所用，易除殆类无根潦。\n但欲搜、好语谢新词，羞琼报。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3279, '满江红', '辛弃疾', '半山佳句，最好是、吹香隔屋。\n又还怪、冰霜侧畔，蜂儿成簇。\n更把香来薰了月，却教影去斜侵竹。\n似神清、骨冷住西湖，何由俗。\n根老大，穿坤轴。\n枝夭袅，蟠龙斛。\n快酒兵长俊，诗坛高筑。\n一再人来风味恶，两三杯後花缘熟。\n记五更、联句失弥明，龙衔烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3280, '满江红', '辛弃疾', '老子平生，原自有、金盘华屋。\n还又要、万间寒士，眼前突兀。\n一舸归来轻似叶，两翁相对清如鹄。\n道如今、吾亦爱吾庐，多松菊。\n人道是，荒年毂。\n还又似，丰年玉。\n甚等闲却为，鲈鱼归速。\n野鹤溪边留杖屦，行人墙外听丝竹。\n问近来、风月几篇诗，三千轴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3281, '满江红', '辛弃疾', '两峡崭岩，问谁占、清风旧筑。\n更满眼、云来鸟去，涧红山绿。\n世上无人供笑傲，门前有客休迎肃。\n怕凄凉、无物伴君时，多栽竹。\n风采妙，凝冰玉。\n诗句好，馀膏馥。\n叹只今人物，一夔应足。\n人似秋鸿无定住，事如飞弹须园熟。\n笑君侯、陪酒又陪歌，阳春曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3282, '永遇乐', '辛弃疾', '千古江山，英雄无觅，孙仲谋处。\n舞榭歌台，风流总被，雨打风吹去。\n斜阳草树，寻常巷陌，人道寄奴曾住。\n想当年，金戈铁马，气吞万里如虎。\n元嘉草草，封狼居胥，赢得仓皇北顾。\n四十三年，望中犹记，烽火扬州路。\n可堪回首，佛狸祠下，一片神鸦社鼓。\n凭谁问，廉颇老矣，尚能饭否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3283, '归朝欢', '辛弃疾', '见说岷峨千古雪。\n都作岷峨山上石。\n君家右史老泉公，千金费尽勤收拾。\n一堂真石室。\n空庭更与添突兀。\n记当时，长编笔砚，日日云烟湿。\n野老时逢山鬼泣。\n谁夜持山去难觅。\n有人依样入明光，玉阶之下岩岩立。\n琅无数碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3284, '瑞鹤仙', '辛弃疾', '雁霜寒透幕。\n正护月云轻，嫩冰犹薄。\n溪奁照梳掠。\n想含香弄粉，艳妆难学。\n玉肌瘦弱。\n更重重、龙绡衬著。\n倚东风，一笑嫣然，转盼万花羞落。\n寂寞。\n家山何在，雪後园林，水边楼阁。\n瑶池旧约。\n鳞鸿更杖谁托。\n粉蝶儿只解，寻桃觅柳，开遍南枝未觉。\n但伤心，冷落黄昏，数声画角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3285, '声声慢', '辛弃疾', '东南形胜，人物风流，白头见君恨晚。\n便觉君家叔度，去人未远。\n长怜士元骥足，道直须、别驾方展。\n问个里，待怎生销杀，胸中万卷。\n况有星辰剑履，是传家合在，玉皇香案。\n零落新诗，我欠可人消遣。\n留君再三不住，便直饶、万家泪眼。\n怎抵得，这眉间、黄色一点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3286, '汉宫春', '辛弃疾', '秦望山头，看乱云急雨，倒立江湖。\n不如云者为雨，雨者云乎。\n长空万里，被西风、变灭须臾。\n回首听，月明天籁，人间万窍号呼。\n谁向若耶溪上，倩美人西去，麋鹿姑苏。\n至今故国人望，一舸归欤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3287, '汉宫春', '辛弃疾', '亭上秋风，记去年袅袅，曾到吾庐。\n山河举目虽异，风景非殊。\n功成者去，觉团扇、便与人疏。\n吹不断，斜阳依旧，茫茫禹迹都无。\n千古茂陵词在，甚风流章句，解拟相如。\n只今木落江冷，眇眇愁余。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3288, '汉宫春', '辛弃疾', '心似孤僧，更茂林修竹，山上精庐。\n维摩定自非病，谁遣文殊。\n白头自昔，叹相逢、语密情疏。\n倾盖处，论心一语，只今还有公无。\n最喜阳春妙句，被西风吹堕，金玉铿如。\n夜来归梦江上，父老欢予。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3289, '汉宫春', '辛弃疾', '达则青云，便玉堂金马，穷则茅庐。\n逍遥小大自适，鹏何殊。\n君如星斗，灿中天、密密疏疏。\n荒草外，自怜萤火，清光暂有还无。\n千古季鹰犹在，向松江道我，问讯何如。\n白头爱山下去，翁定嗔予。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3290, '洞仙歌', '辛弃疾', '冰姿玉骨，自是清凉□。\n此度浓妆为谁改。\n向竹篱茅舍，几误佳期。\n招伊怪，满脸颜红微带。\n寿阳妆鉴里，应是承恩，纤手重匀异香在。\n怕等闲、春未到，雪里先开，风流、说与群芳不解。\n更总做、北人未识伊，据品调，难作杏花看待。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3291, '洞仙歌', '辛弃疾', '贤愚相去，算其间能几。\n差以毫厘缪千里。\n细思量义利，舜跖之分，孳孳者，等是鸡鸣而起。\n味甘终易坏，岁晚还知，君子之交淡如水。\n一饷聚飞蚊，其响如雷，深自觉、昨非今是。\n羡安乐窝中泰和汤，更剧饮，无过半醺而已。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3292, '上西平・金人捧露盘', '辛弃疾', '九衢中，杯逐马，带随车。\n问谁解、爱惜琼华。\n何如竹外，静听蟹行沙。\n自怜是，海山头，种玉人家。\n纷如斗，娇如舞，才整整，又斜斜。\n要图画，还我渔蓑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3293, '上西平・金人捧露盘', '辛弃疾', '恨如新，新恨了，又重新。\n看天上、多少浮云。\n江南好景，落花时节又逢君。\n夜来风雨，春归似欲留人。\n尊如海，人如玉，诗如锦，笔如神。\n能几字、尽殷勤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3294, '婆罗门引', '辛弃疾', '不堪，早教百草放春归。\n江头愁杀吾累。\n却觉君侯雅句，千载共心期。\n便留春甚乐，乐了须悲。\n琼而素而。\n被花恼、只莺知。\n正要千锺角酒，五字栽诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3295, '千年调', '辛弃疾', '卮酒向人时，和气先倾倒。\n最要然然可可，万事称好。\n滑稽坐上，更对鸱夷笑。\n寒与热，总随人，甘国老。\n少年使酒，出口人嫌拗。\n此个和合道理，近日方晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3296, '江神子・江城子', '辛弃疾', '暗香横路雪垂垂。\n晚风吹。\n晓风吹。\n花意争春，先出岁寒枝。\n毕竟一年春事了，缘太早，却成迟。\n未应全是雪霜姿。\n欲开时。\n未开时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3297, '江神子・江城子', '辛弃疾', '五云高处望西清。\n玉阶升。\n棣华荣。\n筑屋溪头，楼观画难成。\n长夜笙歌还起问，谁放月，又西沉。\n家传鸿宝旧知名。\n看长生。\n奉严宸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3298, '一翦梅', '辛弃疾', '忆对中秋丹桂丛。\n花在杯中。\n月在杯中。\n今宵楼上一尊同。\n云湿纱窗。\n雨湿纱窗。\n浑欲乘风问化工。\n路也难通。\n信也难通。\n满堂惟有烛花红。\n杯且从容。\n歌且从容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3299, '踏莎行', '辛弃疾', '夜月楼台，秋香院宇。\n笑吟吟地人来去。\n是谁秋到便凄凉，当年宋玉悲如许。\n随分杯盘，等闲歌舞。\n问他有甚堪悲处。\n思量却也有悲时，重阳节近多风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3300, '踏莎行', '辛弃疾', '弄影阑干，吹香岩谷。\n枝枝点点黄金粟。\n未堪收拾付薰炉，窗前且把离骚读。\n奴仆葵花，儿曹金菊。\n一秋风露清凉足。\n傍边只欠个娥，分明身在蟾宫宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3301, '踏莎行', '辛弃疾', '吾道悠悠，忧心悄悄。\n最无聊处秋光到。\n西风林外有啼鸦，斜阳山下多衰草。\n长忆商山，当年四老。\n尘埃也走咸阳道。\n为谁书到便幡然，至今此意无人晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3302, '定风波', '辛弃疾', '金印累累佩陆离。\n河梁更赋断肠诗。\n莫拥旌旗真个去。\n何处。\n玉堂元自要论思。\n且约风流三学士。\n同醉。\n春风看试几枪旗。\n从此酒酣明月夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3303, '定风波', '辛弃疾', '野草闲花不当春。\n杜鹃却是旧知闻。\n谩道不如归去住。\n梅雨。\n石榴花又是离魂。\n前殿群臣深殿女。\n赭袍一点万红巾。\n莫问兴亡今几主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3304, '破阵子', '辛弃疾', '菩萨丛中惠眼，硕人诗里娥眉。\n天上人间真福相，画就描成好靥儿。\n行时娇更迟。\n劝酒偏他最劣，笑时犹有些痴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3305, '临江仙', '辛弃疾', '小靥人怜都恶瘦，曲眉天与长颦。\n沈思欢事惜腰身。\n枕添离别泪，粉落却深匀。\n翠袖盈盈浑力薄，玉笙袅袅愁新。\n夕阳依旧倚窗尘。\n叶红苔郁碧，深院断无人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3306, '临江仙', '辛弃疾', '逗晓莺啼声昵昵，掩关高树冥冥。\n小渠春浪细无声。\n井床听夜雨，出藓辘轳青。\n碧草旋荒金谷路，乌丝重记兰亭。\n强扶残醉绕云屏。\n一枝风露湿，花重入疏棂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3307, '临江仙', '辛弃疾', '春色饶君白发了，不妨倚绿偎红。\n翠鬟催唤出房栊。\n垂肩金缕窄，蘸甲宝杯浓。\n睡起鸳鸯飞燕子，门前沙暖泥融。\n画楼人把玉西东。\n舞低花外月，唱澈柳边风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3308, '临江仙', '辛弃疾', '金谷无烟宫树绿，嫩寒生怕春风。\n博山微透暖薰笼。\n小楼春色里，幽梦雨声中。\n别浦鲤鱼何日到，锦书封恨重重。\n海棠花下去年逢。\n也应随分瘦，忍泪觅残红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3309, '临江仙', '辛弃疾', '手种门前乌桕树，而今千尺苍苍。\n田园只是旧耕桑。\n杯盘风月夜，箫鼓子孙忙。\n七十五年无事客，不妨两鬓如霜。\n绿窗地调红妆。\n更从今日醉，三万六千场。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3310, '临江仙', '辛弃疾', '手拈黄花无意绪，等闲行尽回廊。\n卷帘芳桂散馀香。\n枯荷难睡鸭，疏雨暗池塘。\n忆得旧时携手处，如今水远山长。\n罗巾泪别残妆。\n旧欢新梦里，闲处却思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3311, '临江仙', '辛弃疾', '冷雁寒云渠有恨，春风自满余怀。\n更教无日不花开。\n未须愁菊尽，相次有梅来。\n多病近来浑止酒，小槽空压新醅。\n青山却自要安排。\n不须连日醉，且进两三杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3312, '临江仙', '辛弃疾', '六十三年无限事，从头悔恨难追。\n已知六十二年非。\n只应今日是，後日又寻思。\n少是多非惟有酒，何须过後方知。\n从今休似去年时。\n病中留客饮，醉里和人诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3313, '临江仙', '辛弃疾', '窄样金杯教换了，房栊试听珊珊。\n莫教秋扇雪团团。\n古今悲笑事，长付後人看。\n记取桔槔春雨後，短畦菊艾相连。\n拙於人处巧于天。\n君看流水地，难得正方园。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3314, '临江仙', '辛弃疾', '醉帽吟鞭花不住，却招花共商量。\n人生何必醉为乡。\n从教斟酒浅，休更和诗忙。\n一斗百篇风月地，饶他老子当行。\n从今三万六千场。\n青青头上发，还作柳丝长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3315, '临江仙', '辛弃疾', '祗恐牡丹留不住，与春约束分明。\n未开微雨半开晴。\n要花开定准，又更与花盟。\n魏紫朝来将进酒，玉盘盂样先呈。\n红似向舞腰横。\n风流人不见，锦绣夜间行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3316, '临江仙', '辛弃疾', '老去浑身无著处，天教只住山林。\n百年光景百年心。\n更欢须叹息，无病也呻吟。\n试向浮瓜沈李处，清风散发披襟。\n莫嫌浅後更频斟。\n要他诗句好，须是酒杯深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3317, '临江仙', '辛弃疾', '偶向停云堂上坐，晓猿夜鹤惊猜。\n主人何事太尘埃。\n低头还说向，被召又重来。\n多谢北山山下老，殷勤一语佳哉。\n借君竹杖与芒鞋。\n径须从此去，深入白云堆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3318, '蝶恋花', '辛弃疾', '泪眼送君倾似雨。\n不折垂杨，只倩愁随去。\n有底风光留不住。\n烟波万顷春江橹。\n老马临流痴不渡。\n应惜障泥，忘了寻春路。\n身在稼轩安稳处。\n书来不用多行数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3319, '蝶恋花', '辛弃疾', '燕语莺啼人乍远。\n却恨西园，依旧莺和燕。\n笑语十分愁一半。\n翠围特地春光暖。\n只道书来无过雁。\n不道柔肠，近日无肠断。\n柄玉莫摇湘泪点。\n怕君唤作秋风扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3320, '蝶恋花', '辛弃疾', '洗尽机心随法喜。\n看取尊前，秋思如春意。\n谁与先生宽发齿。\n醉时惟有歌而已。\n岁月何须溪上记。\n千古黄花，自有渊明比。\n高卧石龙呼不起。\n微风不动天如醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3321, '蝶恋花', '辛弃疾', '何物能令公怒喜。\n山要人来，人要山无意。\n恰似哀筝弦下齿。\n千情万意无时已。\n自要溪堂韩作记。\n今代机云，好语花难比。\n老眼狂花空处起。\n银钩未见心先醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3322, '南乡子', '辛弃疾', '何处望神州。\n满眼风光北固楼。\n千古兴亡多少事，悠悠。\n不尽长江衮衮流。\n年少万兜鍪。\n坐断东南战未休。\n天下英雄谁敌手。\n曹刘。\n生子当如孙仲谋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3323, '鹧鸪天', '辛弃疾', '别恨妆成白发新。\n空教儿女笑阵人。\n醉寻夜雨旗亭酒，梦断东风辇路尘。\n骑，青云。\n看公冠佩玉阶春。\n忠言句句唐虞际，便是人间要路津。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3324, '鹧鸪天', '辛弃疾', '樽俎风流有几人。\n当年未遇已心亲。\n金陵种柳欢娱地，庾岭逢梅寂寞滨。\n樽似海，笔如神。\n故人南北一般春。\n玉人好把新妆样，淡画眉儿浅注唇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3325, '鹧鸪天', '辛弃疾', '指点斋尊特地开。\n风帆莫引酒船回。\n方惊共折津头柳，却喜重寻岭上梅。\n催月上，唤风来。\n莫愁瓶罄耻金。\n只愁画角楼头起，急管哀弦次第催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3326, '鹧鸪天', '辛弃疾', '困不成眠奈夜何。\n情知归未转愁多。\n暗将往事思量遍，谁把多情恼乱他。\n些底事，误人哪。\n不成真个不思家。\n娇痴却妒香香睡，唤起醒松说梦些。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3327, '鹧鸪天', '辛弃疾', '梦断京华故倦游。\n只今芳草替人愁。\n阳关莫作三叠唱，越女应须为我留。\n看逸韵，自名流。\n青衫司马且江州。\n君家兄弟真堪笑，个个能修五凤楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3328, '鹧鸪天', '辛弃疾', '一夜清霜变鬓丝。\n怕愁刚把酒禁持。\n玉人今夜相思不，想见频将翠枕移。\n真个恨，未多时。\n也应香雪减些儿。\n菱花照面须频记，曾道偏宜浅画眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3329, '鹧鸪天', '辛弃疾', '木落山高一夜霜。\n北风驱雁又离行。\n无言每觉情怀好，不饮能令兴味长。\n频聚散，试思量。\n为谁春草梦池塘。\n中年长作东山恨，莫遣离歌苦断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3330, '鹧鸪天', '辛弃疾', '抛却山中诗酒窠。\n却来官府听笙歌。\n闲愁做弄天来大，白发栽埋日许多。\n新剑戟，旧风波。\n天生予懒奈予何。\n此身已觉浑无事，却教儿童莫恁麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3331, '鹧鸪天', '辛弃疾', '桃李漫山过眼空。\n也宜恼损杜陵翁。\n若将玉骨冰姿比，李蔡为人在下中。\n寻驿使，寄芳容。\n垅头休放马蹄松。\n吾家离落黄昏後，剩有西湖处士风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3332, '鹧鸪天', '辛弃疾', '晚岁躬耕不怨贫。\n只鸡斗酒聚比邻。\n都无晋宋之间事，自是羲皇以上人。\n千载後，百篇存。\n更无一字不清真。\n若教王谢诸郎在，未抵柴桑陌上尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3333, '鹧鸪天', '辛弃疾', '发底青青无限春。\n落红飞雪谩纷纷。\n黄花也伴秋光老，何事尊前见在身。\n书万卷，笔如神。\n眼看同辈上青云。\n个中不许儿童会，只恐功名更逼人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3334, '鹧鸪天', '辛弃疾', '老退何曾说著官。\n今朝放罪上恩宽。\n便支香火真侍俸，更缀文书旧殿班。\n扶病脚，洗衰颜。\n快从老病借衣冠。\n此身忘世浑容易，使世相忘却自难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3335, '鹧鸪天', '辛弃疾', '绿鬓都无白发侵。\n醉时拈笔越精神。\n爱将芜语追前事，更把梅花比那人。\n回急雪，遏行云。\n近时歌舞旧时情。\n君侯要识谁轻重，看取金杯几许深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3336, '鹧鸪天', '辛弃疾', '泉上长吟我独清。\n喜君来共雪争明。\n已惊并水鸥无色，更怪行沙蟹有声。\n添爽气，动雄情。\n奇因六出忆陈平。\n却嫌鸟雀投林去，触破当楼云母屏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3337, '鹧鸪天', '辛弃疾', '莫春光花下游。\n便须准备落花愁。\n百年雨打风吹却，万事三平二满休。\n将扰扰，付悠悠。\n此生於世百无忧。\n新愁次第相抛舍，要伴春归天尽头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3338, '瑞鹧鸪', '辛弃疾', '暮年不赋短长词。\n和得渊明数首诗。\n君自不归归甚易，今犹未足足何时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3339, '瑞鹧鸪', '辛弃疾', '声名少日畏人知。\n老去行藏与愿违。\n山草旧曾呼远志，故人今又寄当归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3340, '瑞鹧鸪', '辛弃疾', '胶胶扰扰几时休。\n一出山来不自由。\n秋水观中山月夜，停云堂下菊花秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3341, '摸鱼子', '张炎', '向天涯、水流云散，依依往事非旧。\n西湖见说鸥飞去，知有海翁来否。\n风雨後。\n甚客里逢春，尚记花间酒。\n空嗟皓首。\n对茂苑残红，携歌占地，相趁小垂手。\n归时候。\n花径青红尚有。\n好游何事诗瘦。\n龟蒙未肯寻幽兴，曾恋志和渔叟。\n吟啸久。\n爱如此清奇，岁晚忘年友。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3342, '南乡子', '张炎', '风月似孤山。\n千树斜横水一环。\n天与清香心独领，怡颜。\n冰雪中间屋数间。\n庭户隔尘寰。\n自有云封底用关。\n却笑桃源深处隐，跻攀。\n引得渔翁见不难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3343, '南楼令・唐多令', '张炎', '一见又天涯。\n人生可叹嗟。\n想难忘、江上琵琶。\n诗酒一瓢风雨外，都莫问，是谁家。\n怜我鬓先华。\n何愁归路赊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3344, '醉落魄・一斛珠', '张炎', '镂花镌叶。\n满枝风露和香撷。\n引将芳思归吟箧。\n梦与魂同，闲了弄香蝶。\n小楼帘卷歌声歇。\n幽篁独处泉呜咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3345, '壶中天・念奴娇', '张炎', '西秦倦旅。\n是几年不听，西湖风雨。\n我托长垂短发，心事时看天语。\n吟箧空随，征衣休换，薜荔犹堪补。\n山能招隐，一瓢闲挂烟树。\n方叹旧国人稀，花间忽见，倾盖浑如故。\n客里不须谈世事，野老安知今古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3346, '声声慢', '张炎', '鬟丝湿雾，扇锦翻桃，尊前乍识欧苏。\n赋笔吟笺，光动万颗骊珠。\n英英岁华未老，怨歌长、空击铜壶。\n细看取，有飘然清气，自与尘疏。\n两水犹存三径，叹绿窗窈窕，谩长新浦。\n茂苑扁舟，底事夜雨江湖。\n当年柳枝放却，又不知、樊素何如。\n向醉里，暗传香、还记也无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3347, '清平乐', '张炎', '黑云飞起。\n夜月啼湘鬼。\n魂返灵根无二纸。\n千古不随流水。\n香心淡染清华。\n似花还似非花。\n要与闲梅相处，孤山山下人家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3348, '台城路・齐天乐', '张炎', '几年槐市槐花冷，天风又还吹起。\n故箧重寻，闲书再整，犹记灯窗滋味。\n浑如梦里。\n见说道如今，早催行李。\n快买扁舟，第一桥边趁流水。\n阳关须是醉酒，柳条休要折，争似攀桂。\n旧有家声，荣看世美，方了平生英气。\n琼林宴喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3349, '壶中天・念奴娇', '张炎', '万尘自远，径松存、彷佛斜川深意。\n乌石罔边犹记得，竹里吟安一字。\n暗叶禽幽，虚阑荷近，暑薄迟花气。\n行行且止，枯瓢枝上闲寄。\n不恨老却流光，可怜归未得，翻恨流水。\n落落岭头云尚在，一笑生涯如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3350, '如梦令', '张炎', '隐隐烟痕轻注。\n拂拂脂香微度。\n十二小红楼，人与玉箫何处。\n归去。\n归去。\n醉插一枝风露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3351, '祝英台近', '张炎', '路重寻，门半掩、苔老旧时树。\n采药云深，童子更无语。\n怪他流水迢迢，湖天日暮，想只在、芦花多处。\n谩延伫。\n姓名题上芭蕉，凉夜未风雨。\n赋了秋声，还赋断肠句。\n几回独立长桥，扁舟欲唤，待招取、白鹤归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3352, '如梦令', '张炎', '不是潇湘风雨。\n不是洞庭烟树。\n醉倒古乾坤，人在孤篷来处。\n休去。\n休去。\n见说桃源无路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3353, '桂枝香', '张炎', '琴书半室。\n向桂边偶然，一见秋色。\n老树香迟，清露缀花疑滴。\n山翁翻笑如泥醉，笑生平、无此狂逸。\n晋人游处，幽情付与，酒尊吟笔。\n任萧散、披襟岸帻。\n叹千古犹今，休问何夕。\n发短霜浓，却恐浩歌消得。\n明年野客重来此，探枝头、几分消息。\n望西楼远，西湖更远，也寻梅驿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3354, '瑶台聚八仙・新雁过妆楼', '张炎', '春树江东。\n吟正远、清气竟入崆峒。\n问余栖处，只在缥缈山中。\n此去山中何所有，芰荷制了集芙蓉。\n且扶筇。\n倦游万里，独对青松。\n行藏也须在我，笑晋人为菊，出岫方浓。\n淡然无心，古意且许谁同。\n飞符夜深润物，自呼起苍龙雨太空。\n舒还卷，看满楼依旧，霁日光风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3355, '瑶台聚八仙・新雁过妆楼', '张炎', '近水横斜。\n先得月、玉树宛若笼纱。\n散迹苔，墨晕净洗铅华。\n误入罗浮身外梦，似花又却似非花。\n探寒葩。\n倩人醉里，扶过溪沙。\n竹篱几番倦倚，看乍无乍有，如寄生涯。\n更好一枝，时到素壁檐牙。\n香深与春暗却，且休把江头千树夸。\n东家女，试淡妆颠倒，难胜西家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3356, '瑶台聚八仙・新雁过妆楼', '张炎', '老圃堪嗟。\n深夜雨、紫英犹傲霜华。\n暖宿篱根，飞去想怯寒沙。\n采摘浮杯如戏水，晚香淡似夜来些。\n背风斜。\n翠苔径里，描绣人夸。\n白头共开笑口，看试妆满插，云髻双丫。\n蝶也休愁，不是旧日疏葩。\n连枝愿为比翼，问因甚寒城独自花。\n悠然意，对九江山色，还醉陶家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3357, '西江月', '张炎', '花气烘人尚暖，珠光出海犹寒。\n如今贺老见应难。\n解道江南肠断。\n谩击铜壶浩叹，空存锦瑟谁弹。\n庄生蝴蝶梦春还。\n帘外一声莺唤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3358, '霜叶飞', '张炎', '绣屏开了。\n惊诗梦、娇声啼破春悄。\n隐将谱字转清圆，正杏梁声绕。\n看帖帖、蛾眉淡扫。\n不知能聚愁多少。\n叹客里凄凉，尚记得当年雅音，低唱还好。\n同是流落殊乡，相逢何晚，坐对被真花恼。\n贞元朝士已无多，但暮烟衰草。\n未忘得春风窈窕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3359, '蝶恋花', '张炎', '济楚衣裳眉目秀。\n活脱梨园，子弟家声旧。\n诨砌随机开笑口。\n筵前戏谏从来有。\n戛玉敲金裁锦绣。\n引得传情，恼得娇娥瘦。\n离合悲欢成正偶。\n明珠一颗盘中走。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3360, '甘州・八声甘州', '张炎', '见梅花、斜倚竹篱边。\n休道北枝寒。\n□□□翠袖，情随眼盼，愁接眉弯。\n一串歌珠清润，绾结玉连环。\n苏小无寻处，元在人间。\n何事凄凉蚓窍，向尊前一笑，歌倒狂澜。\n叹从来古雅，欲觅赏音难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3361, '甘州・八声甘州', '张炎', '俯长江、不占洞庭波，山拔地形高。\n对扶疏古木，浮图倒影，势压雄涛。\n门掩翠微僧院，应有月明敲。\n物换堂安在，断碣闲抛。\n不识庐山真面，是谁将此屋，突兀林坳。\n上层台回首，万境入诗豪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3362, '瑶台聚八仙・新雁过妆楼', '张炎', '屋上青山。\n青未了、凌虚试一凭栏。\n乱峰叠嶂，无限古色苍寒。\n正喜云闲云又去，片云未识我心闲。\n对林峦。\n底须谢屐，何用跻攀。\n三十六梯眺远，任半空笑语，飞落人间。\n赋笔吟笺，尘事竟不相关。\n朝来自然气爽，更好是秋屏宜晚看。\n蓬壶里，有天开图画，休唤边鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3363, '壶中天・念奴娇', '张炎', '长流万里。\n与沈沈沧海，平分一水。\n孤白争流蟾不没，影落潜蛟惊起。\n莹玉悬秋，绿房迎晓，楼观光疑洗。\n紫箫声袅，四檐吹下清气。\n遥睇浪擎空明，古愁休问，消长盈虚理。\n风入芦花歌忽断，知有渔舟闲舣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3364, '台城路・齐天乐', '张炎', '翠屏缺处添奇观，修眉远浮孤碧。\n天影微茫，烟痕黯淡，不与千峰同色。\n凭高望极。\n向帘幕中间，冷光流入。\n料得吟僧，数株松下坐苍石。\n泉源犹是故迹。\n煮茶曾味古，还记游历。\n调水符闲，登山屐在，却倚阑干斜日。\n轻阴易□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3365, '江城子', '张炎', '下临无地手扪天。\n上云烟。\n俯山川。\n栖止危巢，不隔道林禅。\n坐处清高风雨隔，全万境，一壶悬。\n我来直欲挟飞仙。\n海为田。\n是何年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3366, '木兰花慢', '张炎', '风雷开万象，散天影、入虚坛。\n看峭壁重云，奇峰献玉，光洗琅。\n青苔古痕暗裂，映参差、石乳倒悬山。\n那得虚无幻境，元来透澈玄关。\n跻攀。\n竟日忘还。\n空翠滴、逼衣寒。\n想邃宇阴阴，炉存太乙，难觅飞丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3367, '台城路・齐天乐', '张炎', '扁舟忽过芦花浦。\n闲情便随鸥去。\n水国吹箫，虹桥问月，西子如今何许。\n危栏谩抚。\n正独立苍茫，半空飞露。\n倒影虚明，洞庭波映广寒府。\n鱼龙吹浪自舞。\n渺然凌万顷，如听风雨。\n夜气浮山，晴晖荡日，一色无寻秋处。\n惊凫自语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3368, '月下笛', '张炎', '千里行秋，支筇背锦，顿怀清友。\n殊乡聚首。\n爱吟犹自诗瘦。\n山人不解思猿鹤，笑问我、韦娘在否。\n记长堤画舫，花柔春闹，几番携手。\n别後都依旧。\n但靖节门前，近来无柳。\n盟鸥尚有。\n可怜西塞渔叟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3369, '台城路・齐天乐', '张炎', '桃花零落玄都观，刘郎此情谁语。\n鬓发萧疏，襟怀淡薄，空赋天涯羁旅。\n离情万缕。\n第一是难招，旧鸥今雨。\n锦瑟年华，梦中犹记艳游处。\n依依心事最苦。\n片帆浑是月，独抱凄楚。\n屋破容秋，床空对雨，迷却青门瓜圃。\n初荷未暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3370, '惜红衣', '张炎', '两翦秋痕，平分水影，炯然冰洁。\n未识新愁，眉心倩人贴。\n无端醉里，通一笑、柔花盈睫。\n痴绝。\n不解送情，倚银屏斜瞥。\n长歌短舞，换羽移宫，飘飘步回雪。\n扶娇倚扇，欲把艳怀说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3371, '满江红', '张炎', '江上相逢，更秉烛、浑疑梦里。\n寂寞久，瑟弦尘断，为君重理。\n紫绶金章都莫问，醉中□送揶揄鬼。\n看满头、白雪欲消难，春风起。\n云一片，身千里。\n漂泊地，东西水。\n叹十年不见，我生能几。\n慷慨悲歌惊泪落，古人未必皆如此。\n想今人、愁似古人多，如何是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3372, '壶中天・念奴娇', '张炎', '奚囊谢屐。\n向芙蓉城下，□□游历。\n江上沙鸥何所似，白发飘飘行客。\n旷海乘风，长波垂钓，欲把珊瑚拂。\n近来杨柳，却怜浑是秋色。\n日暮空想佳人，楚芳难赠，烟水分明隔。\n老病孤舟天地里，惟有歌声消得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3373, '红情・暗香', '张炎', '无边香色。\n记涉江自采，锦机云密。\n翦翦红衣，学舞波心旧曾识。\n一见依然似语，流水远、几回空忆。\n看□□、倒影窥妆，玉润露痕湿。\n闲立。\n翠屏侧。\n爱向人弄芳，背酣斜日。\n料应太液。\n三十六宫土花碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3374, '绿意・疏影', '张炎', '碧圆自洁。\n向浅洲远渚，亭亭清绝。\n犹有遗簪，不展秋心，能卷几多炎热。\n鸳鸯密语同倾盖，且莫与、浣纱人说。\n恐怨歌、忽断花风，碎却翠云千叠。\n回首当年汉舞，怕飞去、谩皱留仙裙摺。\n恋恋青衫，犹染枯香，还叹鬓丝飘雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3375, '虞美人', '张炎', '黄金谁解教歌舞。\n留得当时谱。\n断情残意落人间。\n汉上行云迷却、旧巫山。\n妆楼何处寻樊素。\n空误周郎顾。\n一帘秋雨翦灯看。\n无限羁愁分付、玉箫寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3376, '踏莎行', '张炎', '清气崖深，斜阳木末。\n松风泉水声相答。\n光浮碗面啜先春，何须美酒吴姬压。\n头上乌巾，鬓边白发。\n数间破屋从芜没。\n山中有此玉川人，相思一夜梅花发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3377, '南乡子', '张炎', '晴野事春游。\n老去寻诗苦未休。\n一似浣花溪上路，清幽。\n烟草纤纤水自流。\n何处偶迟留。\n犹未忘情是酒筹。\n童子策驴人已醉，知不。\n醉里眉攒万国愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3378, '临江仙', '张炎', '忆得沈香歌断後，深宫客梦迢遥。\n研池残墨溅花妖。\n青山人独自，早不侣渔樵。\n石壁苍寒巾尚挂，松风顶上飘飘。\n神仙那肯混尘嚣。\n诗魂元在此，空向水中招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3379, '南楼令・唐多令', '张炎', '云冷未全开。\n檐冰雨苔。\n入花根、暧意先回。\n一夜绿房迎晓白，空忆遍、岭头梅。\n如幻旧情怀。\n寻春上吹台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3380, '摸鱼子', '张炎', '步高寒、下观浮远，清晖隔断风雨。\n醉魂误入滁阳路。\n落莫不知何处。\n栏屡拊。\n又却是，秋城自有芙蓉主。\n重游倦旅。\n对万壑千岩，长江巨浪，空翠洒衣履。\n景如许。\n都被楼台占取。\n晴岚暖霭朝暮。\n乾坤静里闲居赋。\n评泊水经茶谱。\n留胜侣。\n更底用，林泉曳杖寻桑苎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3381, '台城路・齐天乐', '张炎', '清时乐事中园赋，怡情楚花湘草。\n秀色通帘，生香聚酒，修景常留池沼。\n闲居自好。\n奈车马喧尘，未教闲了。\n把菊清游，冷红飞下洞庭晓。\n寻泉同步翠杳。\n更将秋共远，书画船小。\n款竹谁家，盟鸥某水，白月光涵圆峤。\n天浮浩渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3382, '华胥引', '张炎', '温泉浴罢，酣酒才苏，洗妆犹湿。\n落暮云深，瑶台月下逢太白。\n素衣初染天香，寻东风倾国。\n惆怅东栏，炯然玉树独立。\n只恐江空，顿忘却、锦袍清逸。\n柳迷归院，欲远花妖未得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3383, '风入松', '张炎', '松风掩昼隐深清。\n流水自泠泠。\n一从柯烂归来後，爱弦声。\n不爱枰声。\n颇笑山中散木，翻怜爨下劳薪。\n透云远响正丁丁。\n孤凤划然鸣。\n疑行岭上千秋雪，语高寒、相应何人。\n回首更无寻处，一江风雨潮生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3384, '浪淘沙', '张炎', '万里一飞篷。\n吟老丹枫。\n潮生潮落海门东。\n三两点鸥沙外月，闲意谁同。\n一色与天通。\n绝去尘红。\n渔歌忽断荻花风。\n烟水自流心不竞，长笛霜空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3385, '夜飞鹊・夜飞鹊慢', '张炎', '林霏散浮暝，河汉空云，都缘水国秋清。\n绿房一夜迎向晓，海影飞落寒冰。\n蓬莱在何处，但危峰缥缈，玉籁无声。\n文箫素约，料相逢、依旧花阴。\n登眺尚馀佳兴，零露下衣襟，欲醉还醒。\n明月明年此夜，颉颃万里，同此阴晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3386, '风入松', '张炎', '晴岚暖翠护烟霞。\n乔木晋人家。\n幽居只恐归图画，唤樵青、多种桑麻。\n门掩推敲古意，泉分冷淡生涯。\n无边风月乐年华。\n留客可茶瓜。\n任他车马虽嫌僻，笑喧喧、流水寒鸦。\n小隐正宜深静，休栽湖上梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3387, '石州慢', '张炎', '野色惊秋，随意散愁，踏碎黄叶。\n谁家篱院闲花，似语试妆娇怯。\n行行步影，未教背写腰肢，一搦犹立门前雪。\n依约镜中春，又无端轻别。\n痴绝。\n汉皋何处，解佩何人，底须情切。\n空引东邻，遗恨丁香空结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3388, '清平乐', '张炎', '百花开後。\n一朵疑堆绣。\n绝色年年常似旧。\n因甚不随春瘦。\n脂痕淡约蜂黄。\n可怜独倚新妆。\n太白醉游何处，定应忘了沈香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3389, '点绛唇', '张炎', '独殿春光，此花开後无花了。\n丹青人巧。\n不许芳心老。\n密影翻阶，曾为寻诗到。\n竹西好。\n采香歌杳。\n十里红楼小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3390, '卜算子', '张炎', '雅淡浅深黄，顾影秋雨。\n碧带犹皴笋指痕，不解擎芳醑。\n休唱古阳关，如把相思铸。\n却忆铜盘露已乾，愁在倾心处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3391, '蝶恋花', '张炎', '花占枝头日焙。\n金汞初抽，火鼎铅华退。\n还似瘢痕涂獭髓。\n胭脂淡抹微酣醉。\n数朵折来春槛外。\n欲染清香，只许梅相对。\n不是临风珠蓓蕾。\n山童隔竹休敲碎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3392, '新雁过妆楼', '张炎', '遍插茱萸。\n人何处、客里顿懒携壶。\n雁影涵秋，绝似暮雨相呼。\n料得曾留堤上月，旧家伴侣有书无。\n谩嗟吁。\n数声怨抑，翻致无书。\n谁识飘零万里，更可怜倦翼，同此江湖。\n饮啄关心，知是近日何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3393, '洞仙歌', '张炎', '中峰壁立，挂飞来孤剑。\n苍雪纷纷堕晴藓。\n自当年诗酒，客里相逢，春尚好，鸥散烟波茂苑。\n只今谁最老，种玉人间，消得梅花共清浅。\n问我入山期，但恐山深，松风把红尘吹断。\n望蓬莱、知隔几重云，料只隔中间，白云一片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3394, '风入松', '张炎', '门前山可久长看。\n留住白云难。\n溪虚却与云相傍，对白云、何必深山。\n爽气潜生树石，晴光竟入栏干。\n旧家三径竹千竿。\n苍雪拂衣寒。\n绿蓑青笠玄真子，钓风波、不是真闲。\n得似壶中日月，依然只在人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3395, '小重山', '张炎', '淡色分山晓气浮。\n疏林犹剩叶，不多秋。\n林深彷佛昔曾游。\n频唤酒，渔屋岸西头。\n不拟此凝眸。\n朦胧清影里，过扁舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3396, '浪淘沙', '张炎', '拂袖入山阿。\n深隐松萝。\n掬流洗耳厌尘多。\n石上一般清意味，不羡渔蓑。\n日月静中过。\n俗□消磨。\n风瓢分付与清波。\n却笑唐求因底事，无奈诗何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3397, '忆王孙', '张炎', '争棋赌墅意欣然。\n心似游丝扬碧天。\n只为当时一著玄。\n笑苻坚。\n百万军声屐齿前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3398, '蝶恋花', '张炎', '秦地瓜分候已故。\n不学渊明，种秫辞归去。\n薄有田园还种取。\n养成碧玉甘如许。\n卜隐青门真得趣。\n蕙帐空闲，鹤怨来何暮。\n莫说蜗名催及戍。\n长安城下锄烟雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3399, '如梦令', '张炎', '苔径独行清昼。\n瑟瑟松风如旧。\n出岫本无心，迟种门前杨柳。\n回首。\n回首。\n篱下白衣来否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3400, '丑奴儿・采桑子', '张炎', '山人去後知何处，风月清虚。\n来往无拘。\n戏引儿孙乐有馀。\n悬崖挂树如相语，常守枯株。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3401, '浣溪沙', '张炎', '空色庄严玉版师。\n老斑遮护锦绷儿。\n只愁一夜被风吹。\n润处似沾谷雨，斫来如带渭川泥。\n从空托出镇帷犀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3402, '清平乐', '张炎', '辔摇衔铁。\n蹴踏平原雪。\n勇趁军声曾汗血。\n闲过升平时节。\n茸茸春草天涯。\n涓涓野水晴沙。\n多少骅骝老去，至今犹困盐车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3403, '木兰花慢', '张炎', '二分春到柳，青未了，欲婆娑。\n甚书剑飘零，身犹是客，岁月频过。\n西湖故园在否，怕东风、今日落梅多。\n抱瑟空行古道，盟鸥顿冷清波。\n知麽。\n老子狂歌。\n心未歇，鬓先斑。\n叹敝却貂裘，驱车万里，风雪关河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3404, '长相思', '张炎', '去来心。\n短长亭。\n只隔中间一片云。\n不知何处寻。\n闷还颦。\n恨还。\n同是天涯流落人。\n此情烟水深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3405, '南楼令・唐多令', '张炎', '湖上景消磨。\n飘零有梦过。\n问堤边、春事如何。\n可是而今张绪老，见说道、柳无多。\n客里醉时歌。\n寻思安乐窝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3406, '清平乐', '张炎', '一犁初卸。\n息影斜阳下。\n角上汉书何不挂。\n老子近来慵跨。\n烟村草树离离。\n卧看流水忘归。\n莫饮山中清味，怕教洗耳人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3407, '满江红', '张炎', '近日衰迟，但随分、蜗涎自足。\n底须共、红尘争道，顿荒松菊。\n壮志已荒圯上履，正音恐是沟中木。\n又安知、幕下有词人，归心速。\n书尚在，怜鱼腹。\n珠何处，惊鱼目。\n且依然诗思，灞桥人独。\n不用回头看堕甑，不愁抱石疑非玉。\n忽一声、长啸出山来，黄粱熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3408, '法曲献仙音', '张炎', '梅失黄昏，雁惊白昼，脉脉斜飞云表。\n絮不生萍，水疑浮玉，此景正宜舒啸。\n记夜悄、曾乘兴，何必见安道。\n系船好。\n想前村、未知甚处。\n吟思苦，谁游灞桥路杳。\n清饮一瓢寒，又何妨、分傍茶灶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3409, '浣溪沙', '张炎', '昨夜蓝田采玉游。\n向阳瑶草带花收。\n如今风雨不须愁。\n零落依稀倾凿落，碎琼重叠缀搔头。\n白云黄鹤思悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3410, '浣溪沙', '张炎', '半面妆凝镜里春。\n同心带舞掌中身。\n因沾弱水褪精神。\n冷艳喜寻梅共笑，枯香羞与佩同纫。\n湘皋犹有未归人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3411, '一枝春', '张炎', '竹外横枝，并栏干、试数风才一信。\n么禽对语，彷佛醉眠初醒。\n遥知是雪，甚都把、暮寒消尽。\n清更润。\n明月飞来，瘦却旧时疏影。\n东阁谩撩诗兴。\n料西湖树老，难认和靖。\n晴窗自好，胜事每来独领。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3412, '水调歌头', '张炎', '白发已如此，岁序更。\n化机消息，壮生天籁雍门琴。\n颇笑论文说剑，休问高车驷马，衮衮□黄金。\n蚁在元无梦，水竞不流心。\n绝交书，招隐操，恶圆箴。\n世尘空扰，脱巾挂壁且松阴。\n谁对紫微阁下，我对白萍洲畔，朝市与山林。\n不用一钱买，风月短长吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3413, '南楼令・唐多令', '张炎', '聚首不多时。\n烟波又别离。\n有黄金、应铸相思。\n折得梅花先寄我，山正在、里湖西。\n风雪脆荷衣。\n休教鸥鹭知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3414, '南乡子', '张炎', '爱此碧相依。\n卜筑西园隐逸时。\n三径成阴门可款，幽栖。\n苍雪纷纷冷不飞。\n青眼旧心知。\n瘦节终看岁晚期。\n人在清风来往处，吟诗。\n更好梅花著一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3415, '朝中措', '张炎', '清明时节雨声哗。\n潮拥渡头沙。\n翻被梨花冷看，人生苦恋天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3416, '采桑子', '张炎', '西园冷秋千索，雨透花颦。\n雨过花皴。\n近觉江南无好春。\n杜郎不恨寻芳晚，梦里行云。\n陌上行尘。\n最是多愁老得人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3417, '阮郎归', '张炎', '钿车骄马锦相连。\n香尘逐管弦。\n瞥然飞过水秋千。\n清明寒食天。\n花贴贴，柳悬悬。\n莺房几醉眠。\n醉中不信有啼鹃。\n江南二十年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3418, '浣溪沙', '张炎', '艾香消火未残。\n便能晴去不多寒。\n冶游天气却身闲。\n带雨移花浑懒看，应时插柳日须攀。\n最堪惆怅是东栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3419, '风入松', '张炎', '向人圆月转分明。\n箫鼓又逢迎。\n风吹不老蛾儿闹，绕玉梅、犹恋香心。\n报道依然放夜，何妨款曲行春。\n锦灯重见丽繁星。\n水影动梨云。\n今朝准拟花朝醉，奈今宵、别是光阴。\n帘底听人笑语，莫教迟了□青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3420, '踏莎行', '张炎', '瑶草收香，琪花采汞。\n冰轮碾处芳尘动。\n竹炉汤暖火初红，玉纤调罢歌声送。\n麾去茶经，袭藏酒颂。\n一杯清味佳宾共。\n从来采药得长生，蓝桥休被琼浆弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3421, '鹧鸪天', '张炎', '楼上谁将玉笛吹。\n山前水阔暝云低。\n劳劳燕子人千里，落落梨花雨一枝。\n修禊近，卖饧时。\n故乡惟有梦相随。\n夜来折得江头柳，不是苏堤也皱眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3422, '摸鱼子', '张炎', '又孤吟、灞桥深雪，千山绝尽飞鸟。\n梅花也著东风笑，一夜瘦添多少。\n春悄悄。\n正断梦愁诗，忘却池塘草。\n前村路杳。\n看野水流冰，舟闲渡口，何必见安道。\n慵登眺。\n脉脉霏霏未了。\n寒威犹自清峭。\n终须几日开晴去，无奈此时怀抱。\n空暗恼。\n料酒兴歌情，未肯随人老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3423, '满江红', '张炎', '老子今年，多准备、吟笺赋笔。\n还自喜、锦囊添富，顿非畴昔。\n书册琴棋清队仗，云山水竹闲踪迹。\n任醉筇、游屐过平生，千年客。\n回首梦，东隅失。\n乘兴去，桑榆得。\n且怡然一笑，探梅消息。\n天下神仙何处有，神仙只向人间觅。\n折梅花、横挂酒壶归，白鸥识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3424, '木兰花慢', '张炎', '锦街穿戏鼓，听铁马、响春冰。\n甚舞绣歌云，欢情未足，早已收灯。\n从今便须胜赏，步青青、野色一枝藤。\n落魄花间酒侣，温存竹里吟朋。\n休憎。\n短发。\n游兴懒、我何曾。\n任蹴踏芳尘，寻蕉覆鹿，自笑无能。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3425, '木兰花慢', '张炎', '江南无贺老，看万壑、出清冰。\n想柳思周情，长歌短咏，密与传灯。\n山川润分秀色，称醉挥、健笔剡溪藤。\n一语不谈俗事，几人来结吟朋。\n堪憎。\n我发。\n频赋曲、旧时曾。\n但春蚓秋蛩，寒篱晚砌，颇叹非能。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3426, '浪淘沙', '张炎', '寒食不多时。\n燕燕才归。\n杏花零落水痕肥。\n浅碧分山初过雨，一霎晴晖。\n闲折小桃枝。\n蝶也相随。\n晚妆不合整蛾眉。\n蓦忽思量张敞画，又被愁知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3427, '临江仙', '张炎', '一点白鸥何处去，半江潮落沙虚。\n淡黄柳上月痕初。\n暇观情悄悄，凝想步徐徐。\n每一相思千里梦，十年有此相疏。\n休休寄雁问何如。\n如何休寄雁，难写绝交书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3428, '壶中天・念奴娇', '张炎', '绕枝倦鹊，鬓萧萧、肯信如今犹客。\n风雪荷衣寒叶补，一点灯花悬壁。\n万里舟车，十年书剑，此意青天识。\n泛然身世，故家休问清白。\n却笑醉倒衰翁，石床飞梦，不入槐安国。\n只恐溪山游未了，莫叹飘零南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3429, '谒金门', '张炎', '晚晴薄。\n一片杏花零落。\n纵是东风浑未恶。\n二分春过却。\n可怪寒生池阁。\n下了重重帘幕。\n忽见旧巢还是错。\n燕归何处著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3430, '清平乐', '张炎', '采芳人杳。\n顿觉游情少。\n客里看春多草草。\n总被诗愁分了。\n去年燕子天涯。\n今年燕子谁家。\n三月休听夜雨，如今不是催花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3431, '渔家傲', '张炎', '门掩新阴孤馆静。\n杨花却解来相趁。\n几日方知因酒病。\n无甚。\n脱巾挂壁将书枕。\n见说红堆满径。\n不知何处游人盛。\n自笑扁舟犹未定。\n清和近。\n寻诗已约兰陵令。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3432, '渔家傲', '张炎', '辛苦移家聊处静。\n扫除花径歌声趁。\n也学维摩闲示病。\n迂疏甚。\n松风两耳和衣枕。\n颇倦扶筇寻捷径。\n东墙蔼蔼红香盛。\n少待摇人波自定。\n蓬壶近。\n且呼白鹤招韩令。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3433, '壶中天・念奴娇', '张炎', '苔根抱古，透阳春、挺挺林间英物。\n隔水笛声那得到，斜日空明绝壁。\n半树篱边，一枝竹外，冷艳凌苍雪。\n淡然相对，万花无此清杰。\n还念庾岭幽情，江南聊折，赠行人应发。\n寂寂西窗闲弄影，深夜寒灯明灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3434, '南楼令・唐多令', '张炎', '曾记宴蓬壶。\n寻思认得无。\n醉归来、事已模糊。\n忽对画图如梦寐，又因甚、下清都。\n拍手笑相呼。\n应书缩地符。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3435, '清平乐', '张炎', '丹丘瑶草。\n不许秋风扫。\n记得对花曾被恼。\n犹似前时春好。\n湘皋闲立双清。\n相看波冷无声。\n独说长生未老，不知老却梅兄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3436, '浪淘沙', '张炎', '回首欲婆娑。\n淡扫修蛾。\n盈盈不语奈情何。\n应恨梅兄矾弟远，云隔山阿。\n弱水夜寒多。\n带月曾过。\n羽衣飞过染馀波。\n白鹤难招归未得，天阔星河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3437, '西江月', '张炎', '缥缈波明洛浦，依稀玉立湘皋。\n独将兰蕙入离骚。\n不识山中瑶草。\n月照英翘楚楚，江空醉魄陶陶。\n犹疑颜色尚清高。\n一笑出门春老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3438, '壶中天・念奴娇', '张炎', '异乡倦旅，问扁舟东下，归期何日。\n琴剑空随身万里，天地谁非行客。\n李杜飘零，羊昙悲感，回首俱陈迹。\n羁怀难写，豆虫吟破孤寂。\n柳外门掩疏阴，佳人何处，溪上苹花白。\n留得一方无用月，隐隐山阳闻笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3439, '甘州・八声甘州', '张炎', '听江湖、夜雨十年灯，孤影尚中州。\n对荒凉茂苑，吟情渺渺，心事悠悠。\n见说寒梅犹在，无处认西楼。\n招取楼边月，同载扁舟。\n明日琴书何处，正风前堕叶，草外闲鸥。\n甚消磨不尽，惟有古今愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3440, '风入松', '张炎', '爱闲能有几人来。\n松下独徘徊。\n清虚冷淡神仙事，笑名场、多少尘埃。\n漱齿石边危坐，洗心易里舒怀。\n划然长啸白云堆。\n更待月明□。\n一瓢春水山中饮，喜无人、踏破苍苔。\n开了桃花半树，此游不是天台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3441, '风入松', '张炎', '一瓢饮水曲肱眠。\n此乐不知年。\n今朝忽上龙峰顶，却原来、有此甘泉。\n洗却平生尘土，慵游万里山川。\n照人如鉴止如渊。\n古窦暗涓涓。\n当时桑苎今何在，想松风、吹断茶烟。\n著我白云堆里，安知不是神仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3442, '浪淘沙', '张炎', '玉立水云乡。\n尔我相忘。\n披离寒羽庇风霜。\n不趁白鸥游海上，静看鱼忙。\n应笑我凄凉。\n客路何长。\n犹将孤影侣斜阳。\n花底行无认处，却对秋塘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3443, '菩萨蛮', '陈义', '天生体态腰肢细。\n新词唱彻歌声利。\n出口便清奇。\n扬尘簌簌飞。\n主人恩义重。\n宴出红妆宠。\n便要赏新荷。\n时光也不多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3444, '菩萨蛮', '陈义', '去年共饮菖蒲酒。\n今年却向僧房守。\n好事更多磨。\n教人没奈何。\n主人恩义重。\n知我心头痛。\n待要赏新荷。\n争知疾愈麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3445, '满庭芳', '梅娇', '一种阳和，玉英初纵，雪天分外精神。\n冰肌肉骨，别是一家春。\n楼上笛声三弄，百花都未知音。\n明窗畔，临风对月，曾结岁寒盟。\n笑杏花何太晚，迟疑不发，等待春深。\n只宜远望，举目似烧林。\n丽质芳姿虽好，一时取媚东君。\n争如我，青青结子，金鼎内调羹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3446, '满庭芳', '杏俏', '景傍清明，日和风暖，数枝浓淡胭脂。\n春来早起，惟我独芳菲。\n门外几番雨过，似佳人、细腻香肌。\n堪赏处，玉楼人醉，斜插满头归。\n梅花何太早，消疏骨肉，叶密花稀。\n不逢媚景，开後甚孤栖。\n恐怕百花笑你，甘心受、雪压霜欺。\n争如我，年年得意，占断踏青时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3447, '飞龙宴', '苏小娘', '炎炎暑气时，流光闪烁，闲扃深院。\n水阁凉亭，半开帘幕遥观。\n灼灼榴花吐艳。\n细雨洒、小荷香浅。\n树影竹影，清凉潇洒，枕簟摇纨扇。\n堪叹浮世忙如箭。\n对良辰欢乐，莫辞频劝。\n遇酒逢歌，恣情遂意迷恋。\n须信人生聚散。\n奈区区、利牵名绊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3448, '踏莎行', '张魁', '凤髻堆鸦，香酥莹腻。\n雨中花占街前地。\n弓鞋湿透立多时，无人为问深深意。\n眉上新愁，手中文字。\n如何不倩鳞鸿去。\n想伊只诉薄情人，官中不管闲公事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3449, '声声慢', '张枢密', '星冠懒带，鹤氅慵披，色心顿起兰房。\n离了三清归去，作个新郎。\n良宵自有佳景，更烧甚、清香德香。\n瑶台上，便玉皇亲诏，也则寻常。\n常观里、孤孤令令，争如赴鸳闱，夜夜成双。\n救苦天尊，你且远离他方。\n更深酒阑歌罢，玉人、云雨交相。\n问则甚，咱门这里拜章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3450, '踏莎行', '申二官人', '葱草身才、灯心脚手。\n闲时与蝶花间走。\n有时跌倒屋檐头，蜘蛛网里翻筋斗。\n水马驰来，藕丝缠就。\n鹅毛般上三杯酒。\n等闲试把秤儿秤，平盘分上何曾有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3451, '失调名', '杨岛仙', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3452, '失调名', '吴德远', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3453, '失调名', '连静女', '朦胧月影，黯淡花阴，独立等多时。\n只恐冤家误约，又怕他、侧近人知。\n千回作念，万般思忆，心下暗猜疑。\n蓦地偷来厮见，抱著郎、语颤声低。\n轻移莲步，暗褪罗裳，携手过廊西。\n已是更阑人静，粉郎恣意怜伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3454, '武陵春', '连静女', '人道有情须有梦，无梦岂无情。\n夜夜相思直到明。\n有梦怎生成。\n伊若忽然来梦里，邻笛又还惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3455, '生查子', '楚娘', '去年梅雪天，千里人归远。\n今岁雪梅天，千里人追怨。\n铁石作心肠，铁石刚犹软。\n江海比君恩，江海深犹浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3456, '南歌子', '谢福娘', '闲傍药栏西。\n正是春光三月时。\n深紫浅红光照眼，依稀。\n有似西施醉枕。\n摘放胆瓶儿。\n冷艳幽光映酒卮。\n曾记古人题品语，祆知。\n今夜花王得艳妻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3457, '南歌子', '张时', '暖日未斜西。\n正是迷花酒时。\n红药雕阑呈冷艳，依稀。\n花重枝柔压半。\n相对耍猴儿。\n一捻幽芳劝酒卮。\n魏紫姚黄来觑着，方知。\n准拟今宵醉伴妻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3458, '人月圆', '双渐', '碧纱低映秦娥面，咫尺暗香浓。\n瑶池春晚，长天共恨，烟锁芙蓉。\n夭桃再赏，流莺声巧，不待春工。\n樽前潜想，樱桃破处，得似香红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3459, '鹧鸪天', '黄夫人', '先自春光似酒浓。\n时听莺语透帘栊。\n小桥杨柳飘香絮，山寺绯桃散落红。\n莺渐老，蝶西东。\n春归难觅恨无穷。\n侵阶草色迷朝雨，满地梨花逐晓风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3460, '醉亭楼', '刘使君', '平生性格，随分好些春色。\n沉醉恋花陌。\n虽然年老心未老，满头花压巾帽侧。\n鬓如霜，须似雪，自嗟恻。\n几个相知劝我染，几个相知劝我摘。\n染摘有何益。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3461, '浣溪沙', '李氏2', '无力蔷薇带雨低。\n多情蝴蝶趁花飞。\n流水飘香乳燕啼。\n南浦魂销春不管，东阳衣减镜仙知。\n小楼今夜月依依。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3462, '失调名', '朱希真', '苦汝临期话别，与君挽手叮咛。\n归期誓约十馀朝，去後又经三四月，鱼沉雁杳，空倚著六曲阑干。\n凤只鸾孤，谩独宿半床衾枕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3463, '采桑子', '朱希真', '王孙去後无芳草，绿遍书阶。\n尘满妆台。\n粉面羞搽泪满腮。\n教我甚情怀。\n去时梅蕊全然少，等到花开花已成梅。\n梅子青青又待黄。\n兀自未归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3464, '一翦梅', '张幼谦', '同年同日又同窗。\n不似鸾凰。\n谁似鸾凰。\n石榴树下事匆忙。\n惊散鸳鸯。\n拆散鸳鸯。\n一年不到读书堂。\n教不思量。\n怎不思量。\n朝朝暮暮只烧香。\n有分成双。\n愿早成双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3465, '长相思', '张幼谦', '天有神。\n地有神。\n海誓山盟字字真。\n如今墨尚新。\n过一春。\n又一春。\n不解金钱变作银。\n如何忘却人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3466, '卜算子', '张幼谦', '去时不由人，归怎由人也。\n罗带同心结到成，底事教┾舍。\n心是十分真，情没些儿假。\n若道归迟打棹篦，甘受三千下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3467, '卜算子', '罗惜惜', '幸得那人归，怎便教来也。\n一日相思十二辰，真是情难舍。\n本是好因缘，又怕因缘假。\n若是教随别个人，相见黄泉下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3468, '应景乐', '萧回', '金陵故国。\n极目长江浩渺，千重隔。\n山无际，临湍怒涛碛。\n俯春城苇寂。\n芳昼迤逦，一簇烟村将晚，严光旧台侧。\n何处倦游客。\n对此景惹起离怀，顿觉旧日意，魂黯愁积。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3469, '阮郎归', '春娘', '胡虏中原乱似麻。\n此景依稀似永嘉。\n丁珠片玉落泥沙。\n何时返翠华。\n呈祥鸾凤失仙槎。\n因循离恨加。\n前生应是负偿他。\n思量无岸涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3470, '西江月', '张生2', '一望朱楼巧小，四边绣幕低垂。\n个人活脱似杨妃。\n倚遍阑干十二。\n最苦两双情眼，难禁四只愁眉。\n无言回首日沉西。\n不道一声安置。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3471, '小重山', '张生2', '杏火无烟烧断肠。\n织成春恨切，柳丝长。\n当时谁是种花郎。\n却不教，柳近杏花傍。\n柳道不须忙。\n春深须是有，絮飞扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3472, '西江月', '郑云娘', '一片冰轮皎洁，十分桂魄婆娑。\n不施方便是何如。\n莫是嫦娥妒我。\n虽则清光可爱，奈缘好事多磨。\n仗谁传与片云呵。\n遮取霎时则个。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3473, '减字木兰花', '吕岩', '暂游大庾。\n白鹤飞来谁共语。\n岭畔人家。\n曾见寒梅几度花。\n春来春去。\n人在落花流水处。\n花满前溪。\n藏尽神仙人不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3474, '渔家傲', '吕岩', '二月江南山水路。\n李花零落春无主。\n一个鱼儿无觅处。\n风和雨。\n玉龙生甲归天去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3475, '望江南・忆江南', '吕岩', '瑶池上，瑞雾霭群仙。\n素练金童锵凤板，青衣玉女啸鸾笙。\n身在大罗天。\n沉醉处，缥缈玉京山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3476, '梧桐影', '吕岩', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3477, '促拍满路花', '吕岩', '秋风吹渭水，落叶满长安。\n黄尘车马道、独清闲。\n自然炉鼎，虎绕与龙盘。\n九转丹砂就，琴心三叠，蕊宫看舞胎仙。\n任万钉、宝带貂蝉。\n富贵欲薰天。\n黄粱炊未熟、梦惊残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3478, '沁园春', '吕岩', '七返还丹，在人先须，炼已待时。\n正一阳初动，中宵漏永，温温铅鼎，光透帘帏。\n造化争驰，虎龙交合，进火工夫犹斗危。\n曲江上，看月华莹静，有个乌飞。\n当时。\n自饮刀圭。\n又谁信无中养就儿。\n辨水源清浊，木金间隔，不因师指，此事难知。\n道要玄微，天机深远，下手速修犹太迟。\n蓬莱路，仗三千行满，动步云归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3479, '浪淘沙', '吕岩', '我有屋三间。\n柱用八山。\n周回四壁海遮拦。\n万象森罗为斗，瓦盖青天。\n无漏得多年。\n结就因缘。\n修成功行满三千。\n降得火龙伏得虎，陆地通仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3480, '失调名', '吕岩', '别无巧妙，与你方儿一个。\n子後午前定息坐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3481, '步蟾宫', '吕岩', '坎离乾兑分子午。\n但认取、自家宗祖。\n炼甲庚、更降龙虎。\n地雷震动山头雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3482, '西江月', '吕岩', '落日数声啼鸟，香风满路吹花。\n道人邀我煮新茶。\n荡涤胸中潇洒。\n世事不堪回首，梦魂犹绕天涯。\n凤停桥畔即吾家，管甚月明今夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3483, '沁园春', '吕岩', '琳馆清标，琼台丽质，何年天上飞来。\n扬州暂倚，后土为深栽。\n独立乾坤一树，春风占、万朵齐开。\n天然巧，蕊珠圆簇，玉瓣轻裁。\n见一花九朵，类玲珑玉，错落琼杯。\n得满盛香露，洗荡尘埃。\n是真元孕育，有仙风道骨，岂是凡胎。\n问真宰，难留下土，携而上蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3484, '失调名', '海哥', '海哥风措。\n被渔人、下网打住。\n将在帝城中，每日教言语。\n甚时节、放我归去。\n龙王传语。\n这里思量你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3485, '八声甘州', '何仙姑', '千门万户，尽七颠八倒，掘地寻天。\n真个玄妙，返作笑胡言。\n无为大道人行少，向捏怪途中有万千。\n伤感。\n蜣转却做灵丹。\n无奈伤嗟最苦，又不知端的，枉弃了家缘。\n时间清净，岂解汞收铅。\n心思意想，何曾遣暂合眼。\n阴魔作睡缠。\n展转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3486, '蝶恋花', '宋媛', '云破蟾光穿晓户。\n枕凄凉，多少伤心处。\n惟有相思情最苦。\n檀郎咫尺千山阻。\n莫学飞花兼落絮。\n摇荡春风，迤逦抛人去。\n结尽寸肠千万缕。\n如今认得先辜负。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3487, '阮郎归', '宋媛', '东风成阵送春归。\n庭花高下飞。\n柔条缭绕入帘帏。\n斑斑装舞衣。\n云鬓乱，坐偷啼。\n郎来何负期。\n人生恰似这芳菲。\n芳菲能几时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3488, '清平乐令・清平乐', '吴城小龙女', '帘卷曲栏独倚。\n江展暮天无际。\n泪眼不曾晴，家在吴头楚尾。\n数点雪花乱委。\n扑漉沙鸥惊起。\n诗句欲成时，没入苍烟丛里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3489, '望江南・忆江南', '蔡真人', '阑干曲，红扬绣帘旌。\n花嫩不禁纤手捻，被风吹去意还惊。\n眉黛蹙山青。\n铿铁板，闲引步虚声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3490, '烛影摇红', '懒堂女子', '绿净湖光，浅寒先到芙蓉岛。\n谢池幽梦属才郎，几度生春草。\n尘世多情易老。\n更那堪、秋风袅袅。\n晓来羞对，香芷汀洲，枯荷池沼。\n恨锁横波，远山浅黛无人扫。\n湘江人去叹无依，此意从谁表。\n喜趁良宵月皎。\n况难逢、人间两好。\n莫辞沉醉，醉入屏山，只愁天晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3491, '惜奴娇', '巫山神女', '瑶阙琼宫，高枕巫山十二。\n睹瞿塘、千载滟滟云涛沸。\n异景无穷好，闲吟满酌金卮。\n忆前时。\n楚襄王，曾来梦中相会。\n吾正鬓乱钗横，敛霞衣云缕。\n向前低揖。\n问我仙职。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3492, '惜奴娇', '巫山神女', '绕绕云梯，上彻青霄霞外。\n与诸仙同饮，镇长春醉。\n虎啸猿吟，碧桃香异风飘细。\n希奇。\n想人间难识，这般滋味。\n娥奏乐箫韶，有仙音异品，自然清脆。\n遏住行云不敢飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3493, '惜奴娇', '巫山神女', '山染青螺缥渺，人间难陟。\n有珍珠光照，昼夜无休息。\n仙景无极。\n欲言时。\n汝等何知。\n且修心，要观游，亦非。\n大段难易。\n下俯浮生，尚自争名逐利。\n岂不省，来岁扰扰兵戈起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3494, '惜奴娇', '巫山神女', '再启诸公，百岁还如电急。\n高名显位瞬息尔。\n泛水轻沤，霎那间、难久立。\n画烛当风里。\n安能久之。\n速往茅峰割爱，休名避世。\n等功成、须有上真相引指。\n放死求生，施良药、功无比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3495, '惜奴娇', '巫山神女', '方结实累累。\n翠枝交映，蟠桃颗颗，仙味真香美。\n遂命双成，持灵刀割来，耳服一粒，令我延年万岁。\n堪笑东方，便启私心盗饵。\n使宫中仙伴，递互相尤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3496, '惜奴娇', '巫山神女', '紫云绛霭，高拥瑶砌。\n晓光中、无限剖列。\n肃整天仙队。\n又有殊音欲举，声还止。\n朝罢时。\n亦有清香飘世。\n玉驾才兴，高上真仙尽退。\n有琼花如雪，散漫飞空里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3497, '惜奴娇', '巫山神女', '光阴奇。\n扶桑宫里。\n日月常昼，风物鲜明可爱。\n无阴晦。\n大帝频銮於瑶池。\n朱阑外，乘凤飞。\n教主开颜命醉。\n宝乐齐吹。\n尽是琼姿天妓。\n每三杯，须用圣母亲来揖。\n异果名花几千般，香盈袂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3498, '惜奴娇', '巫山神女', '显焕明霞，万丈祥云高布，望仙官衣带，曳曳临香砌。\n玉兽齐焚，满高穹、盘龙势。\n大帝起。\n玉女金童遍侍。\n奉敕宣言，甚荷诸仙厚意。\n复回奏，感恩顿首皆躬袂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3499, '惜奴娇', '巫山神女', '吾归矣。\n仙宫久离。\n洞户无人管之。\n专俟吾归。\n欲要开金燧。\n千万频修己。\n言讫无忘之。\n哩哩。\n此去无由再至。\n事冗难言，尔辈须能自会。\n汝之言，还便是如吾意。\n大抵方寸平平，无忧耳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3500, '浪淘沙', '玉英', '塞上早春时。\n暖律犹微。\n柳舒金线拂回堤。\n料得江乡应更好，开尽梅溪。\n昼漏渐迟迟。\n愁损仙机。\n几回无语敛双眉。\n凭遍阑干十二曲，日下楼西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3501, '白苎', '紫姑', '绣帘垂，画堂悄，寒风淅沥。\n遥天万里，黯淡同云幂幂。\n渐纷纷、六花零乱散空碧。\n姑射宴瑶池，把碎玉、零珠抛掷。\n林峦望中，高下琼瑶一白。\n严子陵钓台迷踪迹。\n追惜。\n燕然画角，宝钥珊瑚，是时丞相，虚作银城换得。\n当此际、偏宜访袁安宅。\n醺醺醉了，任他金钗舞困，玉壶频侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3502, '望江南・忆江南', '清源真君', '才举意，玄象照离宫。\n坎女离男金水火，几多铁骑漫英雄。\n最苦是云中。\n辽阳鹤，惊起老苍龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3503, '木兰花・玉楼春', '李季萼', '东风忽起黄昏雨。\n红紫飘残香满路。\n凭阑空有惜春心，浓绿满枝无处诉。\n春光背我堂堂去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3504, '天仙子', '随车娘子', '别酒未斟心先醉。\n忽听阳关辞故里。\n扬鞭勒马到皇都，三题尽，当际会。\n稳跳龙门三级水。\n天意令吾先送喜。\n不审君侯知得未。\n蔡邕博识爨桐声，君背负，只此是。\n酒满金杯来劝你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3505, '瑞鹤仙', '紫姑', '睹娇红细捻。\n是西子、当日留心千叶。\n西都竞栽接。\n赏园林台榭，何妨日涉。\n轻罗慢褶。\n费多少、阳和调燮。\n向晓来、露芳苞，一点醉红潮颊。\n双靥。\n姚黄国艳，魏紫天香，倚风羞怯。\n云鬓试插。\n引动狂蜂浪蝶。\n况东君开宴，赏心乐事，莫惜献酬频叠。\n看相将，红药翻阶，尚馀侍妾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3506, '杨柳枝', '玉真', '已谢芳华更不留。\n几经秋。\n故宫台榭只荒邱。\n忍回头。\n塞外风霜家万里，望中愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3507, '忆少年', '乩仙', '凄凉天气，凄凉院落，凄凉时候。\n孤鸿叫斜月，伴寒灯残漏。\n落尽梧桐秋影瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3508, '鹊桥仙', '乩仙', '鸾舆初驾，牛车齐发，隐隐鹊桥咿轧。\n尤云雨正欢浓，但只怕、来朝初八。\n霞垂彩幔，月明银烛，馥郁香喷金鸭。\n年年此际一相逢，未审是、甚时结煞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3509, '千金意', '琴精', '音音音。\n音音你负心。\n你真负心。\n孤负我到如今。\n记的年时，低低唱、浅浅斟。\n一曲值千金。\n如今寂寞古墙阴。\n秋风荒草白云深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3510, '浣溪沙', '珍娘', '溪雾溪烟溪景新。\n溶溶春水浸春云。\n碧琉璃底静无尘。\n风扬游丝随蝶翅，雨飘飞絮湿鸳唇。\n桃花片片送残春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3511, '青玉案', '刘清之', '江南十月春风早。\n见枝上、梅英小。\n爱日初升清雾晓。\n绣筵中启，星图高挂，膝下斑衣绕。\n今年献寿多欢笑。\n弄玉新将二雏好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3512, '玉交枝・忆秦娥', '刘焘', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3513, '失调名', '田为', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3514, '沁园春', '崔中', '自己阳生，正是中虚，静极动时。\n默地雷微震，冲开玉户，天心朗彻，放下帘帏。\n真火冲融，灵泉复凑，不昧谷神何险危。\n自然妙，若三川龙跃，九万鹏飞。\n中中二土成圭。\n意眷恋浓如母护儿。\n这恍惚真容，不空不色，窈冥妙象，无识无知。\n命住丹圆，全真体道，夺志精修休自迟。\n收功了，把三才全理，一贯全归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3515, '满庭芳', '何锄翁', '二气旋还，三宫升降，往来於是无穷。\n透关神水，铅汞过三峰。\n返复周流八脉，戊己炼、阴虎阳龙。\n凝情处，金光朗朗，身外见形容。\n灵光，真造化，天机深远，推测难通。\n算利名酒色，恰似秋风。\n大道玄炉进火，三田内养出神功。\n功成後，金书来诏，平步赴瑶宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3516, '醉落魄・一斛珠', '无名氏', '红牙板歇。\n韶声断、六么初彻。\n小槽酒滴真珠竭。\n紫玉瓯圆，浅浪泛春雪。\n香芽嫩蕊清心骨。\n醉中襟量与天阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3517, '满江红', '无名氏', '浪蕊浮花，当不住、晚风吹了。\n微雨过，池塘飞絮，一帘晴画。\n寂寂山光春似梦，依依草色熏如酒。\n近新来、怕上小红楼，凭阑眺。\n心事阻，诗情少。\n东皇去，良辰杳。\n想故园闲趣，水村烟柳。\n此日鹃声天不管，当年燕子人何有。\n叹江南、离别酒初醒，频回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3518, '西江月', '无名氏', '三级掀腾波浪，一堂庆会风云。\n快乘霹雳化龙门。\n头角人中有分。\n谁状个中佳致，须还笔扫千军。\n是他画手亦通神。\n同向来春夺迅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3519, '西江月', '无名氏', '身禀五行正气，此心如鉴光明。\n不从龟鹤问年龄。\n万物有衰有盛。\n多谢道人著眼，我於身世常轻。\n任从性巧与心灵，此事从来分定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3520, '谒金门', '无名氏', '真个美。\n水墨观音难比。\n闻道观音谁不害。\n见来须顶礼。\n徐步金莲满地。\n那更兰心聪慧。\n一曲清歌离皓齿。\n梁尘飞不已。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3521, '水龙吟', '无名氏', '邦人前世条缘，福星遇得长庚李。\n光芒初照，一声霹雳，重开天地。\n试问年来，民间安枕，伊谁之赐。\n有青天白日，和风甘雨，公如父、氏如子。\n今度虎牌重到，感皇恩、欢声千里。\n衮归未晚，纱笼人物，御屏名字。\n碧嶂长春，清江不尽，棠阴堪憩。\n愿年年把酒，庆公初度，祝公千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3522, '永遇乐', '无名氏', '个个修行，人人咽纳，谁悟真道。\n曲径多岐，旁门小法，误了人多少。\n容成岂是，神仙究竟，采药谩多炉灶。\n忽一朝，脱却桶底，性根坏倒。\n争如内观，无为清净，学取本来庄老。\n匹配阴阳，抽添铅汞，八卦为端表。\n人生如梦，流年似箭，回首也须闻早。\n贪迷恋，春花秋月，何时是了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3523, '永遇乐', '无名氏', '万法由心，应观法界，一切心造。\n老子瞿昙，同归去揆，不离心是道。\n自从识得，坎离交济，炼药粗知昏晓。\n云腾雨飞，蟾宫兔走，丹阙更无烦恼。\n气中真液，液中真气，和合不多不少。\n种出黄芽，炼成赤水，龙虎交围绕。\n七返九还，工夫到後，还我旧时年少。\n待三千、功圆行满，恁时是了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3524, '永遇乐', '无名氏', '学道修心，存神炼性，直要轻举。\n补脑还精，流水不腐，户枢终不蠹。\n日魂月魄，抟归炉鼎，真气自然流聚。\n把心猿缚住，意马追回，迥无尘虑。\n定中明有，阳龙阴火，水火透时为度。\n八段奇文，千口活法，向上有一路。\n吕公高尚，未离人世，有分也须相遇。\n约十洲三岛，骖鸾跨鹤，大家同去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3525, '永遇乐', '无名氏', '养水养精，养神养血，先须养气。\n日月阴阳，六爻八卦，细看参同契。\n灵躯灵宝，千言万语，不过坎离两字。\n向顶上，返本还元，要明终始。\n一身虽小，如同天地，八万四千馀里。\n玄牝之门，生生万化，都在冲和内。\n此真真外，别无真谛，方信道一而已。\n异时见锺吕，如有未明，请师指示。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3526, '渔家傲', '无名氏', '至道不遥只在迩。\n毫厘差失如千里。\n道是难来元却易。\n如相契。\n一超直入如来地。\n水火交时为既济。\n三尸六贼都回避。\n只此长生仍久视。\n身口意。\n化成一点冲和气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3527, '渔家傲', '无名氏', '神是性兮气是命。\n神不外驰气自定。\n幸有崔公入药镜。\n如究竟。\n全真固蒂归根静。\n主客内明方外应。\n灵台粲发天光莹。\n两个壶中一片景。\n急修省。\n莫待临渴去掘井。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3528, '渔家傲', '无名氏', '精养灵根神守气。\n天然子母何曾离。\n昼夜六时长在意。\n三田内。\n温温天地中和水。\n十二楼前白雪腻。\n九宫台畔黄芽遂。\n日月山头朝上帝。\n神光起。\n腾身直出烟霄外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3529, '渔家傲', '无名氏', '我有光珠无买价。\n光明常照芝田下。\n更没之乎并者也。\n知音寡。\n世间谁是能行者。\n一万精光浑守舍。\n四百四病都齐罢。\n透出火龙归造化。\n回仙驾。\n更无一点尘随马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3530, '促拍满路花', '无名氏', '抱元能守一，四大自轻安。\n心中须返照，几曾闲。\n金乌衔耀，飞入烂银盘。\n心心心是道，只在心心，更於何处求仙。\n又何须衣冕，燕处欲超然。\n荣华能几日，便凋残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3531, '促拍满路花', '无名氏', '人能常清静，天涤悉皆归。\n一真含众妙，入希夷。\n昭文不会，气候有成亏。\n妄心寂灭尽，困睡饥餐，更无作用施为。\n自然，炉鼎就，光彩透帘帏。\n玉池神水涌，上生肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3532, '促拍满路花', '无名氏', '若论修养事，知有几多门。\n谛当归宿处，是灵根。\n至真至道，简易合乾坤。\n坎离并水火，止是筌蹄，粹然一点长存。\n个中如荐得，悟了五千言。\n金晶飞肘後，透。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3533, '沁园春', '衣白山人', '一粒金丹，大如黍米，定中降胎。\n运阴阳根本，东龙西虎，结凝金水，择地深栽。\n九载无亏，三田功满，卦气周圆炉鼎开。\n偷元化，用自然宗祖，全在灵台。\n真才。\n休恋尘埃。\n况颖悟明堂婴未孩。\n幸淮滨相遇，灵丹付了，亲留玄旨，期进仙阶。\n此去何时，水云高会，更上烟霞岐路哉。\n人间世，任王侯贵显，同委蒿莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3534, '失调名', '吕岩', '鼎里坎离，壶中天地，满怀风月，一吸虚空。\n尘寰里，何人识我，开口问鸿。\n云中。\n三弄笛，岳阳楼外，天远霞红。\n笑骑黄鹤，暂过海陵东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3535, '西江月', '吕岩', '葆炼中分相火，行持外借方鞋。\n清虚爽彻御□□。\n□□□□□□。\n□□□□□□，□□灵宝为胎。\n十分无极至真来。\n恍惚芝骈羽盖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3536, '西江月', '吕岩', '一日清欢何往，十年旧事重拈。\n细风斜日到江南。\n春满平湖潋滟。\n黄简手题龙篆，绿舆前控鸾骖。\n玉清真署仙衔。\n列职灵台书监。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3537, '霜天晓角', '吕岩', '乾坤未裂。\n有物如何别。\n解把鸿擘破，说不知、知不说。\n妙诀。\n真难彻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3538, '贺新郎', '熊禾', '旧事凭谁诉。\n记锦宫、初试浓妆，前身天女。\n玉辇行春娇侍夜，浴殿温泉轻注。\n一点点、猩红啼吐。\n绣屋篝香春睡足，细温存，怕遣惊风雨。\n春孟散，暗凝伫。\n韶华寂寞今何许。\n想故宫、柳亦凝愁，倚栏停舞。\n欲趁啼鹃归月下，可奈川回山阻。\n倩万里、鹄来衔子。\n工部无诗虽结恨，道无香、更恨痴人语。\n拌绝艳，付黄土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3539, '临江仙', '李之仪', '清润奇峰名韫玉，温其质并琼瑶。\n中分瀑布写云涛。\n双峦呈翠色，气象两相高。\n珍重幽人诚好事，绿窗聊助风骚。\n寄言俗客莫相嘲。\n物轻人意重，千里赠鹅毛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3540, '点绛唇', '李之仪', '匀妆了。\n背人微笑。\n风入玲珑罩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3541, '水调歌头', '叶梦得', '何处难忘酒，朱夏日偏长。\n湖山地胜潇湘，十里芰荷香。\n柳外新蝉惊晚，楼上疏帘垂翠，簟枕晚生凉。\n纨扇摇霜月，曲水泛流觞。\n流年去，今古梦，几千场。\n虚名浮利，输却几许好时光。\n幸有碧云深处，存取朱颜绿鬓，流落又何妨。\n莫厌人世间，频入醉中乡。\n蔺卿全璧我蹉跎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3542, '失调名', '黄庭坚', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3543, '失调名', '黄庭坚', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3544, '菩萨蛮', '黄庭坚', '轻风袅断沈烟炷。\n霏微尽日寒塘雨。\n残绣没心情。\n鸟啼花外声。\n离愁难自制。\n年少乖盟誓。\n寂寞掩朱门。\n罗衣空泪痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3545, '渔家傲', '黄庭坚', '荡漾生涯身已老。\n短蓑箬笠扁舟小。\n深入水云人不到。\n吟复笑。\n一轮明月长相照。\n谁谓阿师来问道。\n一桡直与传心要。\n船子踏翻才是了。\n波渺渺。\n长鲸万古无人钓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3546, '南乡子', '黄叔达', '落帽晚风回。\n又报黄花一番开。\n扶杖老人心未老，堪。\n漫有才情付与谁。\n芳意正徘徊。\n传与西风且慢吹。\n明日馀尊还共倒，重来。\n未必秋香一夜衰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3547, '惜花容', '盼盼', '少年看花双鬓绿。\n走马章台管弦逐。\n而今老更惜花深，终日看花看不足。\n坐中美女颜如玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3548, '绿头鸭・多丽', '晁端礼', '锦堂深，兽炉轻喷沈烟。\n紫檀槽、金泥花面，美人斜抱当筵。\n挂罗绶、素肌莹玉，近鸾翅、云鬓梳蝉。\n玉笋轻拢，龙香细抹，凤凰飞出四条弦。\n碎牙板、烦襟消尽，秋气满庭轩。\n今宵月，依稀向人，欲斗婵娟。\n变新声、能翻往事，眼前风景依然。\n路漫漫、汉妃出塞，夜悄悄、商妇移船。\n马上愁思，江边怨感，分明都向曲中传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3549, '绿头鸭・多丽', '晁端礼', '晚云收，淡天一片琉璃。\n烂银盘、来从海底，皓色千里澄辉。\n莹无尘、素娥淡伫，静可数、丹桂参差。\n玉露初零，金风未凛，一年无似此佳时。\n露坐久，疏莹时度，乌鹊正南飞。\n瑶台冷，栏干凭暖，玉下迟迟。\n念佳人，音尘别後，对此应解相思。\n最关情、漏声正永，暗断肠、花影偷移。\n料得来宵，清光未减，阴晴天气又争知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3550, '望海潮', '晁端礼', '高阳方面，河间都会，三关地最称雄。\n粉堞万层，金城百雉，楼横一带长虹。\n烟素敛晴空。\n正望迷平野，目断飞鸿。\n易水风烟，范阳山色有无中。\n安边暂倚元戎。\n看纶巾对酒，羽扇摇风。\n金勒少年，吴钩壮士，宁论卫霍前功。\n乃眷在清衷。\n恐凤池虚久，归去匆匆。\n幸有佳人锦瑟，玉笋且轻拢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3551, '水龙吟', '晁端礼', '夜来深雪前村路，应是早梅初绽。\n故人赠我，江头春信，南枝向暖。\n疏影横斜，暗香浮动，月明溪浅。\n向亭边驿畔，行人立马，频回首、空肠断。\n别有玉溪仙馆。\n寿阳人、初匀妆面。\n天教占了，百花头上，和羹未晚。\n最是关情处，高楼上、一声羌管。\n仗谁人向道，何如留取，倚朱栏看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3552, '水龙吟', '晁端礼', '岭梅香雪飘零尽，繁杏枝头犹未。\n小桃一种，妖娆偏占，春工用意。\n微喷丹砂，半含朝露，粉墙低倚。\n似谁家女，娇痴怨别，空凝睇、东风里。\n好是佳人半醉。\n近横波、一枝争媚。\n元都观里，武陵溪上，空随流水。\n惆怅如红雨，风不定、五更天气。\n念当年门里，如今陌上，洒离人泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3553, '水龙吟', '晁端礼', '小桃零落春将半。\n双燕却来池馆。\n名园相倚，初开繁杏，一枝遥见。\n竹外斜穿，柳间深映，粉愁香怨。\n任红宋玉，墙头千里，曾牵惹、人肠断。\n常记山城斜路，喷清香、日迟风暖。\n春阴挫後，马前惆怅，满枝红浅。\n深院帘垂雨，愁人处、碎红千片。\n料明年更发，多应更好，约邻翁看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3554, '水龙吟', '晁端礼', '倦游京洛风尘，夜来病酒无人问。\n九衢雪小，千门月淡，元宵灯近。\n香散眉梢，冻消池面，一番春信。\n记南楼醉里，西城宴阙，都不管、人春困。\n屈指流年未几，早人惊、潘郎双鬓。\n当时体态，如今情绪，多应瘦损。\n马上墙头，纵教瞥见，也难相认。\n凭栏干，但有盈盈泪眼，把罗襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3555, '上林春・一落萦', '晁端礼', '霖雨成功，堂称继美，旧说安阳家世。\n峻岳降神，长庚应梦，佳辰况当秋霁。\n玉函金篆，帝锡与、寿眉齿。\n向清时、便告老，尽取貂蝉轻弃。\n把朝庭旧勋屈指。\n有谁人似此，能全终始。\n谤书顿释，先芬未泯，君王自为知己。\n看花临水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3556, '上林春・一落萦', '晁端礼', '伊洛清波，嵩山秀色，共与皇家为瑞。\n挺生异质，亲逢盛旦，簪缨旧传家世。\n雁炉烟里，罩一段、照人清气。\n灿金章、映紫绶，自是真官标致。\n把朝廷缙绅屈指。\n有谁人似得，多才多艺。\n片言悟主，封侯赐璧，君王自为知己。\n暂来卧治。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3557, '满庭芳', '晁端礼', '天与疏慵，人怜憔悴，分甘抛弃簪缨。\n有时乘兴，波上叶舟轻。\n十里横塘过雨，荷香细、苹末风清。\n真如画，残霞淡日，偏向柳梢明。\n凝情。\n尘网外，鲈鱼旋。\n芳酒深倾。\n又算来、何须身後浮名。\n无限沧浪好景，蓑笠下、且遣馀生。\n长歌去，机心尽矣，鸥鹭莫相惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3558, '满庭芳', '晁端礼', '绿绕群峰，红摇千柄，夜来暑雨初收。\n共君乘兴，轻舸信悠悠。\n且尽一尊别酒，荷香里、满酌轻讴。\n明朝去，征帆夜落，何处好汀洲。\n风流。\n吾小阮，朝辞东观，夕向南州。\n况圣时、争教贾傅淹留。\n若过寻阳亭上，琵琶泪、莫洒清秋。\n堤边柳，从今爱惜，留待系归舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3559, '满庭芳', '晁端礼', '北渚澄兰，南山凝翠，望中浑似仙乡。\n万家烟霭，朱户锁垂杨。\n好是飞泉漱玉，回环遍、小曲深坊。\n西风里，芙蕖带雨，飘散满城香。\n微凉。\n湖上好，桥虹倒影，月练飞光。\n命玳簪促席，云鬓分行。\n谁似风流太守，端解道、春草池塘。\n须留恋，神京纵好，此地也难忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3560, '满庭芳', '晁端礼', '雪满貂裘，风摇金辔，笑看锦带吴钩。\n照人清鬓，年少定封侯。\n此去马啼何处，山万叠、济水南州。\n君知否，卢郎未老，曾是恣狂游。\n风流。\n佳丽地，十年屈指，一梦回头。\n最难忘，西湖北渚澄秋。\n玉砌雕栏好在，桃共李、能忆人不。\n衰翁也，多情为我，将恨寄红楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3561, '满庭芳', '晁端礼', '浅约鸦黄，轻匀螺黛，故教取次梳妆。\n减轻琶面，新样小鸾凰。\n每为花娇玉嫩，容对客、斜倚银床。\n春来病，兰薰半歇，一管舞衣裳。\n悲凉。\n人事改，三春艳，一夜繁霜。\n似人归洛浦，云散高唐。\n痛念你、平生分际，辜负我、临老风光。\n罗裙在，凭谁为我，求取返魂香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3562, '雨中花・夜行船', '晁端礼', '倦贰文昌，乐请左符，双旌去指东藩。\n有腰金新宠，昼锦荣观。\n独步文章，家传素业，世宝青毡。\n动欢声和气，里巷初惊，侍从衣冠。\n朱门映柳，绮窗临水，盛游应记当年。\n端解道、香留罗袜，墨在蛮笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3563, '雨中花・夜行船', '晁端礼', '豆蔻梢头，鸳鸯帐里，扬州一梦初惊。\n忆当时相见，双眼偏明。\n南浦绿波，西城杨柳，痛悔多情。\n望征鞍不见，况是并州，自古高城。\n几多映月凭肩私语，傍花和泪深盟。\n争信道、三年虚负，一事无成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3564, '雨中花・夜行船', '晁端礼', '流水知音，轻裘共敝，相逢才换星霜。\n多少风亭棋酒，画阁丝簧。\n纤指声犹馀响，红粉泪已成行。\n怅绿波浦上，芳草堤边，又整归航。\n新移槛竹，手种庭花，未容烂熳飞觞。\n归去也、重趋丹禁，密侍清光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3565, '玉楼宴', '晁端礼', '记红颜日、向瑶阶，得俊饮、散蓬壶。\n绣鞍纵骄马，故坠鞭柳径，缓辔花衢。\n斗帐兰曲，曾是振、声名上都。\n醉倒旗亭，更深未归，笑倩人扶。\n光阴到今二纪，算难寻前好，懒访仙居。\n近来似闻道，向雾关云洞，自乐清虚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3566, '醉蓬莱', '晁端礼', '正中秋初过，淡碧云容，嫩凉天气。\n紫府真仙，暂谪居尘世。\n慕道高情，照人清骨，是寿星标致。\n德在民心，勋藏帝室，清芬相继。\n庭有芝兰，世调鼎鼐，晋美乌衣，汉称韦氏。\n未必当时，解功成身退。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3567, '醉蓬莱', '晁端礼', '看梅梢初动，池面冰澌，小春时候。\n当日生贤，庆黄家忠厚。\n龙种殊常，照人眉宇，似汝阳端秀。\n世取贤科，胪传圣语，增光华胃。\n天汉灵源，最为亲近，茅土真封，旧相传授。\n开府新恩，拜除书非久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3568, '醉蓬莱', '晁端礼', '乍酒醒孤馆，梦断幽窗，嫩凉天气。\n潇洒情怀，想乡关迢递。\n一枕清风，半帘残月，是闷人滋味。\n南浦离多，东阳带缓，新来憔悴。\n因念当时，乱花深径，画楫环溪，屡陪欢醉。\n踪迹飘流，顿相望千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3569, '金人捧露盘', '晁端礼', '天锡禹圭尧瑞，君王受厘，未央宫殿。\n三五庆元宵，扫春寒、花外蕙风轻扇。\n龙阙前瞻，凤楼背耸，中有鳌峰见。\n渐紫宙、星河晚。\n放桂华浮动，金莲开遍。\n御帘卷。\n须臾万乐喧天，群仙扶辇。\n云间，都人望天表，正仙葩竞插，异香飘散。\n春宵苦长短。\n指花阴，愁听漏传银箭。\n京国繁华，太平盛事，野老何因见。\n但时效华封祝，愿岁岁闻道，金舆游宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3570, '玉女摇仙佩', '晁端礼', '宫梅弄粉，御柳摇金，又喜皇州春早。\n盛世生贤，真仙应运，当日来从三岛。\n车马喧青晓。\n看千锺赐饮，中人传诏。\n最好是、芝兰并砌，鸣佩腰金，彩衣相照。\n炉烟袅。\n高堂半卷珠帘，神仙飘缈。\n须信槐庭荫美，凤沼波澄，屈指十年三到。\n九叙重歌，元圭再锡，已把成功来告。\n四海瞻仪表。\n庆君臣会集，诗符天保。\n况自有、仙风道骨，玉函金篆，阴功须报。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3571, '蓦山溪', '晁端礼', '轻衫短帽，重入长安道。\n屈指十年中，一回来、一回渐老。\n朋游在否，落托更能无，朱弦悄。\n知音少。\n拨断相思调。\n花边柳外，潇洒愁重到。\n深院锁春风，悄无人、桃花自笑。\n金钗一股，拟欲问音尘，天杳杳。\n波渺渺。\n何处寻蓬岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3572, '蓦山溪', '晁端礼', '栏干十二，倚遍还重倚。\n一曲一般愁，对芳草、伤春千里。\n绮窗深处，还解忆人无，碧云辞，红叶字。\n曾仗东风寄。\n缭墙深院，无路通深意。\n纵使得新声，又争知、相如名字。\n从来风韵，潇洒不禁愁，拈梨花，看菊蕊。\n应也成憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3573, '蓦山溪', '晁端礼', '广寒宫殿，千里同云晓。\n飞雪满空来，翦云英、群仙齐到。\n乱飘僧舍，密处洒歌楼，闲日少。\n风光好。\n且共宾朋笑。\n华堂深处，满满觥船掉。\n梅蕊拆来看，已偷得、春风些小。\n绮罗香暖，不怕卷珠帘，沈醉了。\n樽前倒。\n红袖休来叫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3574, '蓦山溪', '晁端礼', '春来心事，分付千锺酒。\n午醉梦还醒，两眉愁、才消又有。\n天涯远梦，归路日中迷，楚云深，孤馆静，潇洒梨花手。\n回文歌罢，幽恨新兼旧。\n帘影卷斜阳，乱红飞、风摇暮柳。\n独携此意，和泪上层楼，尽平芜，穷远目，认断千山首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3575, '喜迁莺', '晁端礼', '嫩柳初摇翠。\n怪朝来早有，飞花零坠。\n洞门斜开，珠帘初卷，惊起谢娘吟缀。\n蕊珠宫殿晓，谁乱把、云英揉碎。\n气候晚，被寒风卷渡，龙沙千里。\n沈醉。\n深院里。\n粉面照人，疑是瑶池会。\n润拂炉烟，寒欺酒力，低压管弦声沸。\n艳阳过半也，应是好、郊原新霁。\n待更与上层楼，遍倚栏干十二。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3576, '喜迁莺', '晁端礼', '伫立蘅皋暮，冻云乍敛，霜飙微列。\n怅饮杯深，阳关声苦，愁见画船催发。\n夜来红泪烛，还解惜、王孙轻别。\n怅望处，乍金丝冷落，兰薰销歇。\n闻说。\n归兴切。\n华鬓未生，得意浓时节。\n画楫门开，斑衣追逐，晓日凤凰双阙。\n帝城春信早，随处有、江梅攀折。\n烂熳赏，也多应忘了，东堂风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3577, '喜迁莺', '晁端礼', '清和时序。\n望桂影渐生，薰风微度。\n挺秀金芝，传芳玉叶，天上瑞麟重睹，竞爽谢庭兰玉，信美西壅鸳鸯。\n庆门里，把丹枝争折，青云平步。\n声誉。\n喧盛世，人咏少年，古锦囊中句。\n艺祖诸孙，宗王贤子，偏爱汝阳眉宇。\n画堂令辰称寿，愿与冈陵同固。\n更看取，继公勋业，东平茅土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3578, '沁园春', '晁端礼', '络纬催凉，断虹收雨，庭梧报秋。\n绕郡城、千顷烟波绿，正鱼肥酒美，名冠东州。\n芰荷风细，蒹葭烟淡，宛在潇湘南岸头。\n凝望处，似桃源洞口，初泛兰舟。\n贤侯。\n酝藉风流。\n向庭讼闲时多宴游。\n有信陵家世，梁园客右，才华高掩，沈谢何刘。\n政声朝奏，除书夕至，即看归趋丹凤楼。\n须眷恋，况新堂莹澈，好共迟留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3579, '水调歌头', '晁端礼', '忆昔红颜日，金玉等泥沙。\n青楼紫陌，惟解惜月与贪花。\n谁信如今憔悴，尘暗金徽玉轸，藓污匣中蛇。\n一事都无就，双鬓只堪嗟。\n恨无情，乌与兔，送年华。\n不如归去，无限云水好生涯。\n未用轻蓑短棹，犹有青鞋黄帽，行处即吾家。\n回首人间世，幽意在青霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3580, '金盏倒垂莲', '晁端礼', '流水漂花，记同寻阆苑，曾宴桃源。\n痛饮狂歌，金盏倒垂莲。\n未省负、佳时良夜，烂游风月三年。\n别後空报瑶琴，谁听朱弦。\n风流少年儒将，有威名震虏，谈笑安边。\n寄我新诗，何事赋归田。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3581, '百宝装・新燕过妆楼', '晁端礼', '枫叶初丹，苹花渐老，蘅皋谁系扁舟。\n故人思我，征棹少淹留。\n一尊潋滟西风里，共醉倒、同销万古愁。\n况今宵自有，明月照人，逼近中秋。\n常爱短李家声，金闺彦士，才高沈谢何刘。\n片帆初卷，歌吹是扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3582, '玉胡蝶・玉蝴蝶', '晁端礼', '淡淡春阳天气，夜来一霎，微雨初晴。\n向暖犹寒，时候又是清明。\n乱沾衣、桃花雨闹，微弄袖、杨柳风轻。\n晓莺声。\n唤回幽梦，犹困春酲。\n牵萦。\n伤春怀抱，东郊烟暖，南浦波平。\n况有良朋，载酒同放彩舟行。\n劝人归、啼禽有意，催棹去、烟水无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3583, '木兰花・玉楼春', '晁端礼', '苦春宵漏短，梦回晚、酒醒迟。\n正小雨初收，馀寒未放，怯试单衣。\n娇痴。\n最尤处，被罗襟、印了宿妆眉。\n潇洒春工斗巧，算来不在花枝。\n芳菲。\n正好踏春，携素手、暂分飞。\n料恨月愁花，多应瘦损，风柳腰肢。\n归期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3584, '金盏子', '晁端礼', '断魂凝睇。\n望故国迢迢，倦摇征辔。\n恨满西风，有千里云山，万重烟水。\n遥夜枕冷衾寒，数更筹无寐。\n想伊家、应也背著孤灯，暗弹珠泪。\n屈指。\n重算归期，知他是何时见去里。\n翻思绣阁旧时，无一事，只管爱争闲气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3585, '洞仙歌', '晁端礼', '年时此际，向扁舟同载。\n风送征帆暮天外。\n对沙汀宿鹭，与波上轻鸥，双双处，相唤相呼自在。\n如今重整棹，烟景依然，谁念轻分绣罗带。\n向蓬窗独坐，不觉徊徨，鸥与鹭、想一齐惊怪。\n怎生得、今宵梦还家，又譬如秉烛，夜阑相对。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3586, '安公子', '晁端礼', '帝里重阳好。\n又对短发来吹帽。\n满目风光还似旧，奈樽前人老。\n暗忆当年，伴侣同倾倒。\n夸俊游、争买千金笑。\n到如今憔悴，恰似华胥一觉。\n此恨何时了。\n旧游屈指愁重到。\n小曲深坊闲信马，掩朱扉悄悄。\n怎得个多情，为我传音耗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3587, '庆寿光', '晁端礼', '丹疏恩，庆闱受命，圣朝广孝非常。\n大邑高封，名兼寿考辉光。\n闾巷相传盛事，焕丝五色成章。\n崇新栋，天语荣夸，共瞻积善华堂。\n灵龟荐祉，紫鸾称寿，千锺泛酒，百和焚香。\n况有新教歌舞，妙选丝篁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3588, '黄鹂绕碧树', '晁端礼', '鸳瓦霜轻，玳帘风细，高门瑞气非烟。\n积厚源深，有长庚应梦，乔岳生贤。\n妙龄秀发，庆谢庭、兰玉争妍。\n名动缙绅，况文章政术，俱是家传。\n别有阴功厚德，向东州、治狱平反。\n玉函高篆，仙风道骨，锡与长年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3589, '永遇乐', '晁端礼', '龙阁先芬，凤毛荣继，当世英妙。\n峻岳储灵，长庚应梦，还庆佳辰到。\n黄花露，碧瓦凝霜，香馥郡齐清晓。\n忆当年、青云平步，共喜骤跻华要。\n阴功厚德，玉符金篆，锡与世间难老。\n注意方浓，分符屡请，雅志人应少。\n棠阴无讼，乐府新教，正醉山频倒。\n有谁莱衣游戏，萱堂寿考。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3590, '满江红', '晁端礼', '五两风轻，移舟向、斜阳岛外。\n最好是、潇湘烟景，自然心会。\n倒影芙蓉明镜底，更折花嗅西风里。\n待问君、明日向何州，东南指。\n人生事，谁如意。\n剩拼取，尊前醉。\n想升沈有命，去来非己。\n菊老松深三径在，田园已有归来计。\n问甚时、重此望归舟，远相对。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3591, '春晴', '晁端礼', '燕子来时，清明过了，桃花乱飘红雨。\n倦客凄凉，千里云山将暮。\n泪眸回望，人在玉楼深处。\n向此多应念远，凭栏无语。\n芳菲可惜轻负。\n空鞭弄游丝，帽冲飞絮。\n恨满东风，谁识此时情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3592, '河满子', '晁端礼', '满浦亭前杨柳，一年两度攀条。\n瞬息光阴都几许，离情常是迢迢。\n须信沈腰易瘦，争教潘鬓相饶。\n不忍重寻香径，还来独立溪桥。\n唯有无情东去水，来时曾傍兰桡。\n今夜欲求好梦，望中莫遣魂销。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3593, '醉桃源・阮郎归', '晁端礼', '又是青春将暮。\n望极桃溪归路。\n洞户悄无人，空锁一庭红雨。\n凝伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3594, '一丛花', '晁端礼', '谪仙海上驾鲸鱼。\n谈笑下蓬壶。\n神寒骨重真男子，是我家、千里龙驹。\n经纶器业，文章光焰，流辈更谁如。\n渊明元与世情疏。\n松菊爱吾庐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3595, '感皇恩', '晁端礼', '蜀锦满林花，三年重到。\n应被花枝笑人老。\n半开微谢，占得几多时好。\n便须拼痛饮、花前倒。\n醉中但记，红围绿绕。\n人面花光斗相照。\n缭墙重院，爱惜遮藏须早。\n免如攀折柳，临官道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3596, '御街行', '晁端礼', '柳条弄色梅飘粉。\n还是元宵近。\n小楼深巷月胧明，记得恁时风景。\n庭花影转，珠帘人静，依旧厌厌闷。\n如今对酒翻成恨。\n春瘦罗衣褪。\n王孙何处草萋萋，辜负小欢幽兴。\n谁知此际，有人灯下，偷把归期问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3597, '踏莎行', '晁端礼', '萱草栏干，榴花庭院。\n悄无人语重帘卷。\n屏山掩梦不多时，斜风雨细江南岸。\n昼漏初传，林莺百啭。\n日长暗记残香篆。\n洞房消息有谁知，几回欲问梁间燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3598, '踏莎行', '晁端礼', '柳暗重门，花深小院。\n盆池昨夜新荷卷。\n银床斜倚小屏风，吴波澄淡春山远。\n纨扇风轻，薰炉烟断。\n日高睡起眉山浅。\n尘侵鸾镜懒匀妆，谁人与整钗头燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3599, '踏莎行', '晁端礼', '衰柳残荷，长山远水。\n扁舟荡漾烟波里。\n离杯莫厌百分斟，船头转便三千里。\n红日初斜，西风渐起。\n琵琶休洒青衫泪。\n区区游宦亦何为，林泉早作归来计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3600, '蝶恋花', '晁端礼', '潋滟长波迎首。\n雨淡烟轻，过了清明候。\n岸草汀花浑似旧。\n行人只是添清瘦。\n沈水香消罗袂透。\n双橹声中，午梦初惊後。\n枕上懵腾犹病酒。\n卷帘数尽长堤柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3601, '蝶恋花', '晁端礼', '骨秀肌香冰雪莹。\n潇洒风标，赋得温柔性。\n髻遗钿慵不整。\n花时长是厌厌病。\n枕上晓来残酒醒。\n一带屏山，千里江南景。\n指点烟村横小艇。\n何时携手重寻胜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3602, '定风波', '晁端礼', '花倚东风柳弄春。\n分明浅笑与轻。\n更忆当时声细细，偎人。\n秦筝轻衬砑罗裙。\n别後此欢谁更共。\n春梦。\n只凭胡蝶伴飞魂。\n独倚高楼还日暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3603, '江城子', '晁端礼', '幽香闲艳露华浓。\n晚妆慵。\n略匀红。\n春困厌厌，常爱鬓云。\n早是自来莲步小，新样子，为谁弓。\n画堂西下小栏东。\n醉醒中。\n苦匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3604, '江城子', '晁端礼', '石榴双叶忆同寻。\n卜郎心。\n向谁深。\n长恁娇痴，尤怎生禁。\n内样双眉新画得，还印了，在罗襟。\n相思幽怨付鸣琴。\n望来音。\n久沈沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3605, '临江仙', '晁端礼', '今夜征帆何处落，烟村几点人家。\n莫惊双泪向风斜。\n渔人西塞曲，商女後庭花。\n从此五湖归去好，一杯酒送生涯。\n多情犹解惜年华。\n春闺重见处，霜鬓不须嗟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3606, '西江月', '晁端礼', '去路湘桃破萼，归时乳燕巢梁。\n不成一事又还乡。\n也是经春游荡。\n香炉重燃，罗衾再拂鸳鸯。\n今宵应解话愁肠。\n指点尘生绣帐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3607, '西江月', '晁端礼', '洛浦神仙流品，姑山冰雪肌肤。\n谁家池馆雨晴初。\n肠断风标白鹭。\n国艳枉教无语，玉颜不待施朱。\n采菱人散夜蟾孤。\n冷落西溪风露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3608, '诉衷情', '晁端礼', '红窗小艇雨馀天。\n李郭未神仙。\n片时篷底幽梦，即是五湖船。\n追往事，惜流年。\n恨风烟。\n向人依旧，两行垂杨，一片新蝉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3609, '诉衷情', '晁端礼', '吴宫绝艳楚宫腰。\n怯挂紫檀槽。\n纤纤玉笋轻拈，莺语弄春娇。\n松钿带，金翘。\n暗香飘。\n红牙拍碎，绛蜡烧残，月淡天高。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3610, '诉衷情', '晁端礼', '金盆水冷又重煨。\n不肯傍妆台。\n从教髻鬟慢，斜卷云钗。\n莲步稳，黛眉开。\n後园回。\n手柳带，鬓插梅梢，探得春来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3611, '清平乐', '晁端礼', '朦胧月午。\n点滴梨花雨。\n青翼欺人多谩语。\n消息知他真否。\n兽炉鸳被重熏。\n故将灯火挑昏。\n最恨西风摇幕，误人几度迎门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3612, '清平乐', '晁端礼', '深沈玉宇。\n枕簟清无暑。\n睡起花阴初转午。\n一霎飞云过雨。\n雨馀隐隐残雷。\n夕阳却照庭槐。\n莫把绣帘垂下，妨它双燕归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3613, '清平乐', '晁端礼', '琐窗朱户。\n曾是娇眠处。\n只有馀香留得住。\n满地花钿翠羽。\n三年宋玉东邻。\n断肠月夕烟春。\n看取画屏深处，题诗欲付何人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3614, '清平乐', '晁端礼', '清樽泛菊。\n共剪西窗烛。\n一抹朱弦新按曲。\n更遣歌喉细逐。\n明朝匹马西风。\n黄云衰草重重。\n试问剑歌悲壮，何如玉指轻拢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3615, '浣溪沙', '晁端礼', '误入仙家小洞来。\n碧桃花落乱浮杯。\n满身罗绮香煤。\n醉倒任眠深迳里，醒时须插满头归。\n更收馀蕊酿新醅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3616, '浣溪沙', '晁端礼', '紫蔓凝阴绿四垂。\n暗香撩乱扑罗衣。\n醉眠惟有落花知。\n玉笋纤纤初嗅罢，乌云娜娜乱簪时。\n此般风韵雅相宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3617, '浣溪沙', '晁端礼', '阆苑瑶台指旧居。\n当年一念别仙都。\n庆门曾梦得明珠。\n赋畀已教尘累浅，修持更与俗缘疏。\n慧心从此悟真如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3618, '浣溪沙', '晁端礼', '似火山榴映翠娥。\n依依香汗轻罗。\n恼人无奈是横波。\n金凿落倾欢事少，玉搔头袅闷时多。\n不留人住意如何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3619, '浣溪沙', '晁端礼', '一见郎来双眼明。\n春风楼上玉箫声。\n谁信同心双结子、苦难成。\n瑶空传张好好，钿筝谁继薛琼琼。\n若是今生无此分、有来生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3620, '浣溪沙', '晁端礼', '清润风光雨後天。\n蔷薇花谢绿窗前。\n碧琉璃瓦欲生烟。\n十里闲情凭蝶梦，一春幽怨付鲲弦。\n小楼今夜月重圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3621, '浣溪沙', '晁端礼', '昼漏迟迟出建章。\n惊回残梦日犹长。\n风微歌吹度昭阳。\n沈水烧残金鸭冷，胭脂匀罢紫绵香。\n一枝花影上东廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3622, '浣溪沙', '晁端礼', '湘簟纱厨午睡醒。\n起来庭院雨初晴。\n夕阳偏向柳梢明。\n懒炷薰炉沈水冷，罢摇纨扇晚凉生。\n莫将闲事恼卿卿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3623, '菩萨蛮', '晁端礼', '薄衾小枕重门闭。\n孤灯照著人无寐。\n风雨夜来多。\n春寒可奈何。\n深闺香暖处。\n还解怜人否。\n只道不来归。\n那知心似飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3624, '菩萨蛮', '晁端礼', '午阴未转晴窗暖。\n无风著地杨花满。\n睡起日犹长。\n卷帘红杏香。\n春心无处定。\n又作花时病。\n芳草伴离愁。\n绵绵早晚休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3625, '菩萨蛮', '晁端礼', '百花未报芳菲信。\n一枝探得春风近。\n只有雪争光。\n更无花似香。\n孤标天赋与。\n冷艳谁能顾。\n庭院好深藏。\n莫教开路傍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3626, '菩萨蛮', '晁端礼', '卷帘风入双双燕。\n燕双双入风帘卷。\n明月晓啼莺。\n莺啼晓月明。\n断肠空望远。\n远望空肠断。\n楼上几多愁。\n愁多几上楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3627, '菩萨蛮', '晁端礼', '远山眉映横波脸。\n脸波横映眉山远。\n云鬓插花新。\n新花插鬓云。\n断魂离思远。\n远思离魂断。\n门掩未黄昏。\n昏黄未掩门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3628, '一落索', '晁端礼', '正向溪堂欢笑。\n忽惊传新诏。\n马啼准拟乐郊行，又却近、长安道。\n鹳鹊楼边初到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3629, '虞美人', '晁端礼', '木兰舟稳桃花浪。\n重到清溪上。\n刘郎惆怅武陵迷。\n无限落英飞絮、水东西。\n玉觞潋滟谁相送。\n一觉扬州梦。\n不知何物最多情。\n惟有南山不改、旧时青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3630, '虞美人', '晁端礼', '短亭过尽长亭到。\n未忍过征棹。\n天涯自是别离身。\n更折一枝杨柳、赠行人。\n淮阴堤上残阳里，暮草连空翠。\n一樽别酒苦匆匆。\n还似陇头流水、各西东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3631, '一斛珠', '晁端礼', '伤春怀抱。\n清明过後莺声老。\n劝君莫向愁人道。\n又被香轮，碾破青青草。\n夜来风雨连清晓。\n秋千院落无人到。\n梦回酒醒愁多少。\n犹赖春寒，未放花开了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3632, '少年游', '晁端礼', '建溪灵草已先尝。\n欢意尚难忘。\n未放笙歌，暂留簪。\n犹有紫芝汤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3633, '鹊桥仙', '晁端礼', '多情应解，留连春意，满地萦花惹絮。\n王孙何在不归来，又遍满、闲门要路。\n咸阳原上，姑苏台下，肠断绿波南浦。\n迢迢归思碧连云，解送我、春山尽处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3634, '点绛唇', '晁端礼', '洞户深沈，起来闲绕回郎转。\n凤箫声远。\n小院杨花满。\n旧曲重寻，移遍秦筝雁。\n芳心乱。\n栏干凭暖。\n目向天涯断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3635, '鹧鸪天', '晁端礼', '并蒂芙蓉本自双。\n晓来波上斗新妆。\n朱匀檀口都无语，酒入圆腮各是香。\n辞汉曲，别高唐。\n芳心应解妒鸳鸯。\n不封虢国并秦国，应嫁刘郎与阮郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3636, '鹧鸪天', '晁端礼', '红紫飘零绿满城。\n春风於此独留情。\n谁将十幅吴绫被，扑向熏笼一夜明。\n风不定，雨初晴。\n晓来苔上拾残英。\n连教贮向鸳鸯枕，犹有馀香入梦清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3637, '武陵春', '晁端礼', '湖上风光寒食近，准拟醉花枝。\n不忍东风烂熳时。\n红泪湿胭脂。\n情知今後游从少，鸾镜懒重窥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3638, '苏幕遮', '晁端礼', '碧桃花，春婉娩。\n未断尘缘，暂别瑶池宴。\n谪限迢迢应未满。\n乘月骖鸾，曾有深深愿。\n帝城赊，凤楼远。\n长寿杯深，此际谁人劝。\n闷倚屏山凝泪眼。\n百和烟中，细想千娇面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3639, '朝中措', '晁端礼', '短亭杨柳接长亭。\n攀折赠君行。\n莫怪尊前无语，大多分外多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3640, '丑奴儿・采桑子', '晁端礼', '小庭数朵寒梅放，雪缀霜。\n装点香英。\n玉软琼娇两未胜。\n佳人皓腕争攀取，插向壶冰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3641, '丑奴儿・采桑子', '晁端礼', '来朝匹马萧萧去，且醉芳卮。\n明夜天涯。\n浅酌低吟欲谁。\n归来应过重阳也，菊有残枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3642, '惜双双・惜分飞', '晁端礼', '天上星杓春又到。\n应律管、微阳已报。\n暖信惊梅早。\n昨夜南枝，先得芳菲耗。\n迟日胧光破晓。\n馥绣幄、麝炉烟袅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3643, '脱银袍', '晁端礼', '纤条绿沁。\n春色为伊难禁。\n传芳意、东君信任。\n燕愁莺懒，怕轻寒犹禁。\n护占得、幽香转甚。\n粉面初匀，冰肌未饮。\n何须爱、妖桃胜锦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3644, '行香子', '晁端礼', '别恨绵绵。\n屈指三年。\n再相逢、情分依然。\n君初霜鬓，我已华颠。\n况其间有，多少恨，不堪言。\n小庭幽槛，菊蕊阑斑。\n近清宵、月已婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3645, '小重山', '晁端礼', '朱户深深小洞房。\n曲屏龟甲样，画潇湘。\n纱轻蓝嫩镂牙床。\n人如玉，一见已心凉。\n午枕梦悠扬。\n流莺声唤觉，日犹长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3646, '雨霖铃', '晁端礼', '槐阴添绿。\n雨馀花落，酒病相续。\n闲寻双杏凝伫，池塘暖、鸳鸯浴。\n却向窗昼卧，正春睡难足。\n叹好梦、一一无凭，帐掩金花座凝目。\n当时共赏移红烛。\n向花间、小饮杯盘促。\n蔷薇花下曾记，双凤带、索题诗曲。\n别後厌厌，应是香肌，瘦减罗幅。\n问燕子、不肯传情，甚入华堂宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3647, '玉叶重黄', '晁端礼', '玉纤初拈梅花蕊。\n早忆著、上元天气。\n重寻旧曲声韵，收拾放灯欢计。\n况人生、百岁能几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3648, '金蕉叶', '晁端礼', '楼头已报咚咚鼓。\n华堂渐、停杯投箸。\n更闻急管频催，凤口香销炷。\n花映玉山倾处。\n主人无计留宾住。\n溪泉泛、越瓯春乳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3649, '南歌子', '晁端礼', '月到中秋夜，还胜别夜圆。\n高河瑟瑟转金盘。\n三十六宫深处、卷帘看。\n香雾云鬟湿，清辉玉臂寒。\n寻常岂是不婵娟。\n吟赏莫辞终夕、动经年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3650, '鹧鸪天', '晁端礼', '霜压天街不动尘。\n千官环贺成。\n三竿阊阖楼边日，五色蓬莱顶上云。\n随步辇，卷香。\n六宫红粉倍添春。\n乐章近与中声合，一片仙韶特地新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3651, '鹧鸪天', '晁端礼', '数骑飞尘入凤城。\n朔方诸部奏河清。\n圜扉木索频年静，大晟箫韶九奏成。\n流协气，溢欢声。\n更将何事卜升平。\n天颜不禁都人看，许近黄金辇路行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3652, '鹧鸪天', '晁端礼', '阆苑瑶台路暗通。\n皇州佳气正葱葱。\n半天楼殿朦胧月，午夜笙歌淡荡风。\n车流水，马游龙。\n万家行乐醉醒中。\n何须更待元宵到，夜夜莲灯十里红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3653, '鹧鸪天', '晁端礼', '洛水西来泛绿波。\n北瞻丹阙正嵯峨。\n先皇秘聿无人解，圣子神孙果众多。\n民物阜，岁时和。\n帝居不用壮山河。\n卜年卜世过周室，亿万斯年入咏歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3654, '鹧鸪天', '晁端礼', '壁水溶溶漾碧漪。\n桥门清晓驻鸾旗。\n三千儒服鸳兼鹭，十万犀兵虎与貔。\n春服就，舞雩归。\n四方争颂育莪诗。\n熙丰教养今成效，已见夔龙集凤池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3655, '鹧鸪天', '晁端礼', '八彩眉开喜色新。\n边陲来奏捷书频。\n百蛮洞穴皆王土，万里戎羌尽汉臣。\n丹转毂，锦拖绅。\n充庭列贡集珠珍。\n宫花御柳年年好，万岁声中过一春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3656, '鹧鸪天', '晁端礼', '圣泽昭天下漏泉。\n君王慈孝自天然。\n四民有养跻仁寿，九族咸亲迈古先。\n歌舜日，咏尧年。\n竞翻玉管播朱弦。\n须知大观崇宁事，不愧生民下武篇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3657, '鹧鸪天', '晁端礼', '日日仙韶度曲新。\n万机多暇宴游频。\n歌馀兰麝生纨扇，舞罢珠玑落绣。\n金屋暖，璧台春。\n意中情态掌中身。\n近来谁解辞同辇，似说昭阳第一人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3658, '鹧鸪天', '晁端礼', '万国梯航贺太平。\n天人协赞甚分明。\n两阶羽舞三苗格，九鼎神金一铸成。\n仙鹤唳，玉芝生。\n包茅三脊已充庭。\n翠华脉脉东封事，日观云深万仞青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3659, '鹧鸪天', '晁端礼', '金碧觚斗极边。\n集英深殿听胪传。\n齐开雉扇双分影，不动金炉一喷烟。\n红锦地，碧罗天。\n升平楼上语喧喧。\n依稀曾听钧天奏，耳冷人间四十年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3660, '并蒂芙蓉', '晁端礼', '太液波澄，向鉴中照影，芙蓉同蒂。\n千柄绿荷深，并丹脸争媚。\n天心眷临圣日，殿宇分明敞嘉瑞。\n弄香嗅蕊。\n愿君王，寿与南山齐比。\n池边屡回翠辇，拥群仙醉赏，凭栏凝思。\n萼绿揽飞琼，共波上游戏。\n西风又看露下，更结双双新莲子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3661, '寿星明・沁园春', '晁端礼', '露湿晴花，散红香清影，建章宫殿。\n玉宇风来，银河云敛，天外老人星现。\n向晓千官入，称庆山呼鳌。\n凤髓香飘，龙墀翡翠，帘栊高卷。\n朝罢仗卫再整，肃鸣鞘，又向瑶池高宴。\n海寓承平，君臣相悦，乐奏徵招初遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3662, '黄河清', '晁端礼', '晴景初升风细细。\n云收天淡如洗。\n望外凤凰双阙，葱葱佳气。\n朝罢香烟满袖，近臣报、天颜有喜。\n夜来连得封章，奏大河、彻底清。\n君王寿与天齐，馨香动上穹，频降嘉瑞。\n大晟奏功，六乐初调清徵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3663, '舜韶新', '晁端礼', '晨光射牖，新燕子、一一穿帘飞去。\n露唏鸳瓦，萧瑟风生琼宇。\n香篆烟消昼永，锁深院、榴花半吐。\n映绛绡、冰雪肌肤，自是清凉无暑。\n浮荣何用萦怀，冷笑看、车马喧喧尘土。\n地偏心远，终日何妨扃户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3664, '上林春・一落萦', '晁端礼', '相识来来，真个为伊，尽把精神役破。\n啼性□，娇痴做处，双眉镇长愁锁。\n为伊恁地，便诸事、自来饶过。\n暂时间未得，又早孜煎无那。\n想从来、性气恁麽。\n那堪更等闲，经时抛。\n料得那里、千万，嗔我也思量我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3665, '雨中花・夜行船', '晁端礼', '小小中庭，深深洞户，谁人笑里相迎。\n有三年窥宋，一顾倾城。\n舞态方浓，箫声未阕，又黯离情。\n怎奈向，赢得多情怀抱，薄声名。\n良宵记得，醉中携手，画楼月皎风清。\n难忘处、凭肩私语，和泪深盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3666, '醉蓬莱', '晁端礼', '向重门深闭，永夜孤眠，梦魂飞过。\n梦里分明，共玉人双卧。\n粉淡香浓，翠深红浅，是那回梳裹。\n楚雨难成，巫云易散，依前惊破。\n无绪无聊，向谁分诉，独语独言，自家摧挫。\n梦也多磨，更那堪真个。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3667, '吴音子', '晁端礼', '细想当初事，又非是、取次相知。\n一年来、著尚迟。\n疑□时、敢共些儿。\n似恁秤停期克了，便一成望不相离。\n却何期、恩情陡变，中路分飞。\n都缘我自心肠软，润就得、转转娇痴。\n如今未中再偎随。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3668, '洞仙歌', '晁端礼', '眼来眼去，未肯分明道。\n有意于人甚不早。\n谩教我、心下终日悬悬，星□事，知他何时是了。\n几回猜伊意，也是难为，拟待偷怜又胆小。\n奈何我已狂迷，怎肯乾休，情深後、不免求告。\n但只教、时时得些儿，便拼了一生，为伊烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3669, '安公子', '晁端礼', '渐渐东风暖。\n杏梢梅萼红深浅。\n正好花前携素手，却云飞雨散。\n是即是、从来好事多磨难。\n就中我与你才相见。\n便世间烦恼，受了千千万万。\n回首空肠断。\n甚时与你同欢宴。\n但得人心长在了，管天须开眼。\n又只恐、日疏日远衷肠变。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3670, '河满子', '晁端礼', '草草时间欢笑，厌厌别後情怀。\n留下一场烦恼去，今回不比前回。\n幸自一成休也，阿谁教你重来。\n眠梦何曾安稳，身心没处安排。\n今世因缘如未断，终期他日重谐。\n但愿人心长在，到头天眼须开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3671, '踏莎行', '晁端礼', '骂女嗔男，呼奴喝爪。\n新来司户多心躁。\n家中幸自好熙熙，眉儿皱著乾烦恼。\n饱喜饥嗔，多愁早老。\n古人言语分明道。\n剩须将息少孜煎，人生万事何时了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3672, '临江仙', '晁端礼', '火冷灯□山驿静，无人与暖香衾。\n阿谁教你惜人深。\n一成迷後，不忘有如今。\n枕畔耳边都悄悄，忆伊模样声音。\n些儿年纪正难禁。\n盟言虽在，只恐我痴心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3673, '清平乐', '晁端礼', '娇羞未惯。\n长是低花面。\n笑里爱将红袖掩。\n遮却双双笑靥。\n早来帘下逢伊。\n怪生频整衫儿。\n元是那回欢会，齿痕犹在凝脂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3674, '一落索', '晁端礼', '道著明朝分袂。\n早眉头攒翠。\n不言不语只偎人，满眼里、汪汪地。\n向道不须如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3675, '一斛珠', '晁端礼', '相思最苦。\n别来有甚好情绪。\n夜间无限凄惶处。\n睡不著时，没个人言语。\n所恨不能飞上路。\n书书直怪迟归去。\n外边闲事无心。\n直自我咱，怕你恶肠肚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3676, '少年游', '晁端礼', '眼来眼去又无言。\n教我怎生团。\n又不分明，许人一句，纵未也心安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3677, '鹊桥仙', '晁端礼', '从来因被，薄情相误，误得人来已怕。\n那回时、有愿不昏沈，甚近日、依前又也。\n你莫就，偎随人便，却骑墙两下。\n自家懑、都望有前程，背地里、莫教人咒骂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3678, '点绛唇', '晁端礼', '我也从来，唤作真个收拾定。\n据伊情性。\n怎到如今恁。\n就百般，终是心肠狠。\n应难更。\n是我薄命。\n不怨奴薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3679, '卜算子', '晁端礼', '恩义重如山，情意深如海。\n假使黄金北斗高，这一分、何由买。\n领家看取彩。\n莫要胡厮赖。\n堂印旁边更碧油，但管取、无人赛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3680, '柳初新', '晁端礼', '些儿柄把天来大。\n闷损也、还知麽。\n共伊合下、深盟厚约，比望收因结果。\n这好事、难成易破。\n到如今、彼此无那。\n终日行行坐坐。\n未曾识、展眉则个。\n若还不是、前生注定，甚得许多摧挫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3681, '步蟾宫', '晁端礼', '昨宵争个甚闲事。\n又不道、被谁调戏。\n任孜孜、求告不回头，诮满眼、汪汪地泪。\n奴哥一向不赌是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3682, '千秋岁', '晁端礼', '飞云骤雨。\n草草成暌阻。\n寸肠结尽千千缕。\n别离谁是没，惟我於中苦。\n最苦是，看奴未足抛奴去。\n一句临歧语。\n忍泪奴听取。\n身可舍，情难负。\n纵非瓶断绠，也是钗分股。\n再见了，知他似得如今否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3683, '人娇', '晁端礼', '旋剔银灯，高褰斗帐。\n孜孜地、看伊模样。\n端相一饷，揉搓一饷。\n不会得、知他甚家娘养。\n不见些儿，行思坐想。\n分飞後、怎生□向。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3684, '遍地花', '晁端礼', '密约幽欢试思忖。\n教人又、怎生安稳。\n算都来、些子精神，诮烦恼、看看瘦损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3685, '梁州令', '晁端礼', '各自寻思取。\n更莫怨他人做。\n如今地怕相逢，愁多正在相逢处。\n人前不敢分明语。\n暗里频回顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3686, '滴滴金', '晁端礼', '庞儿周正心儿得。\n眼儿单、鼻儿直。\n口儿香、发儿黑。\n脚儿一折。\n从来薄命多阻隔。\n未曾有恁相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3687, '失调名', '晁端礼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3688, '蓦山溪', '晁端礼', '风流心胆，直把春偿酒。\n选得一枝花，绮罗中、算来未有。\n名园翠苑，风月最佳时，夜迢迢，车款款，是处曾携手。\n重来一梦，池馆皆依旧。\n幽恨写新诗，托何人、章台问柳。\n渔舟归後，云锁武陵溪，水潺潺，花片片，舣棹空回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3689, '好事近', '曾肇', '岁晚凤山阴，看尽楚天冰雪。\n不待牡丹时候，又使人轻别。\n如今归去老江南，扁舟载风月。\n不似画梁双燕，有重来时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3690, '调笑转踏・调笑令', '郑仅', '归去。\n携笼女。\n南陌柔桑三月暮。\n使君春思如飞絮。\n五马徘徊频驻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3691, '调笑转踏・调笑令', '郑仅', '双桨。\n小舟荡。\n唤取莫愁迎叠浪。\n武陵豪客青楼上。\n不道风高江广。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3692, '调笑转踏・调笑令', '郑仅', '草草。\n最年少。\n袖户银屏人窈窕。\n瑶琴暗写相思调。\n一曲关心多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3693, '调笑转踏・调笑令', '郑仅', '烟暖。\n武陵晚。\n洞里春长花烂熳。\n红英满地溪流浅。\n渐听云中鸡犬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3694, '调笑转踏・调笑令', '郑仅', '春艳。\n桃花脸。\n笑倚银屏施宝靥。\n良人少有平戎胆。\n归路光生弓剑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3695, '调笑转踏・调笑令', '郑仅', '相慕。\n酒家女。\n巧笑明眸年十五。\n当垆春永寻芳去。\n门外落花飞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3696, '调笑转踏・调笑令', '郑仅', '肠断。\n浙江岸。\n楼上青帘新酒软。\n吴姬绰约开金盏。\n的的娇波流盼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3697, '调笑转踏・调笑令', '郑仅', '苏小。\n最娇妙。\n几度尊前曾调笑。\n云情雨态知多少。\n悔恨相逢不早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3698, '调笑转踏・调笑令', '郑仅', '梦悄。\n翠屏晓。\n帐里薰炉残蜡照。\n赏心乐事能多少。\n忍听阳关声调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3699, '调笑转踏・调笑令', '郑仅', '时节。\n白银阙。\n洞里春晴百和。\n兰心底事多悲切。\n消尽一团冰雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3700, '调笑转踏・调笑令', '郑仅', '调笑。\n楚江渺。\n粉面修眉花斗好。\n擎荷折柳争相调。\n惊起鸳鸯多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3701, '调笑转踏・调笑令', '郑仅', '声切。\n恨难说。\n千里潮平春浪阔。\n梅风不解相思结。\n忍送落花飞雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3702, '西江月', '蔡京', '八十一年住世，四千里外无家。ピ\n如今流落向天涯。ピ\n梦到瑶池阙下。ピ\n玉殿五回命相，彤庭几度宣麻。ピ\n止因贪此恋荣华。ピ\n便有如今事也。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3703, '西江月', '苏琼', '韩愈文章盖世，谢安情性风流。\n良辰美景在西楼。\n敢劝一卮芳酒。\n记得南宫高第，弟兄争占鳌头。\n金炉玉殿瑞烟浮。\n高占甲科第九。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3704, '茶瓶儿', '李元膺', '去年相逢深院宇。\n海棠下、曾歌金缕。\n歌罢花如雨。\n翠罗衫上，点点红无数。\n今岁重寻携手处。\n空物事、人非春暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3705, '洞仙歌', '李元膺', '廉纤细雨，东风如困。\n萦断千丝为谁恨。\n向楚宫一梦，千古悲凉，无处问。\n愁到而今未尽。\n分明都是泪，泣柳沾花，常与骚人伴孤闷。\n记当年，得意处，酒力方融，怯轻寒、玉炉香润。\n又岂识、情怀苦难禁，对点滴檐声，夜寒灯晕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3706, '洞仙歌', '李元膺', '雪云散尽，放晓晴池院。\n杨柳于人便青眼。\n更风流多处，一点梅心、相映远。\n约略轻笑浅。\n一年春好处，不在浓芳，小艳疏香最娇软。\n到清明时候，百紫千红花正乱。\n已失春风一半。\n蚤占取韶光，共追游，但莫管春寒，醉红自暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3707, '蓦山溪', '李元膺', '溪堂欢燕。\n惯捧玻璃盏。\n今日祖西城，更忍把、一杯重劝。\n别离情味，自古不堪秋，催泪雨，湿西风，肠共危弦断。\n夕阳去路，五马旌旗乱。\n便是古都春，应醉恋，曲江池馆。\n须知别後，叠翠倚阑情，青嶂晚，碧云深，日近长安远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3708, '鹧鸪天', '李元膺', '寂寞秋千两绣旗。\n日长花影转阶迟。\n燕惊午梦周遮语，蝶困春游落拓飞。\n思往事，入颦眉。\n柳梢阴重又当时。\n薄情风絮难拘束，飞过东墙不肯归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3709, '菩萨蛮', '李元膺', '彩旗画柱清明後。\n花前姊妹争携手。\n先紧绣罗裙。\n轻衫束领巾。\n琐绳金钏响。\n渐出花梢上。\n笑里问高低。\n盘云玉螭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3710, '一落索', '李元膺', '天上粉云如扫。\n放小楼清晓。\n古今何处想风流，最潇洒，龙山帽。\n人似年华易老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3711, '浣溪沙', '李元膺', '乞与安仁掠鬓霜。\n不须红线小机窗。\n剪刀疏下蜀罗长。\n纤手捻残针缕细，金钗翻过齿痕香。\n同心小绾寄思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3712, '浣溪沙', '李元膺', '饮散兰堂月未中。\n骅骝娇簇绛纱笼。\n玳簪促坐客从容。\n已醉人间千日酒，赐来天上密云龙。\n蓬仙清兴欲乘风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3713, '调笑令', '吕南公', '行客。\n行客。\n身世东西南北。\n家林迢递不归。\n岁时悲盛泪垂。\n垂泪。\n垂泪。\n两鬓与霜相似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3714, '调笑令', '吕南公', '华草。\n华草。\n秀发乘春更好。\n深心密竹纷纷。\n妖韶随处动人。\n人动。\n人动。\n王孙公子情重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3715, '瑶台第一层', '赵顼', '西母池边宴罢，赠南枝、步玉霄。\n绪风和扇，冰华发秀，雪质孤高。\n汉陂呈练影，问是谁、独立江皋。\n便凝望、壶中璧，天下琼瑶。\n清标。\n曾陪胜赏，坐望愁、解使尘消。\n况双成与乳丹点染，都付香梢。\n寿妆酥冷，郢韵佩举，麝卷云绡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3716, '临江仙', '吕希纯', '□□□□□□□，□□□□□□。\n莫交闲虑到心头。\n有来忧不得，无後不须忧。\n□□□□□□□，□□□□□□。\n万般希望不如休。\n无来求不得，有後不须求。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3717, '蜡梅香', '喻陟', '晓日初长，正锦里轻阴，小寒天气。\n未报春消息，早瘦梅先发，浅苞纤蕊。\n玉匀香，天赋与，风流标致。\n问陇头人，音容万里。\n待凭谁寄。\n一样晓妆新，倚朱楼凝盼，素英如坠。\n映月临风处，度几声羌管，愁生乡思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3718, '渔家傲', '朱服', '小雨廉纤风细细。\n万家杨柳轻烟里。\n恋树湿花飞不起。\n愁无比。\n和春付与西流水。\n九十光阴能有几。\n金龟解尽留无计。\n寄语东城沽酒市。\n拼一醉。\n而今乐事他年泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3719, '无闷', '丁注', '风急还收，云冻又开，海阔无人翦水。\n算六出工夫，怎教容易。\n刚被郢歌楚舞。\n镇独向，尊前夸轻细。\n想谢庭诗咏，梁园赋赏，未成欢计。\n天意。\n是则是。\n便下得控持，柳梢梅蕊。\n又争奈、看看渐回春意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3720, '宝鼎现', '刘', '浓阴堆积，回野空旷，将回微煦。\n还是觉、早梅依旧，清艳枝枝攒晓树。\n弄霁影、尽脂凝香蒂，琼削纤葩竞吐。\n对几处园林，芳菲消息，都因传去。\n取次台榭，等闲院落，偏宜独擅芳步。\n长恁恐、寿阳妆面，姑射冰肤成暗妒。\n笑杏坞、共桃蹊夸丽，一霎狂风骤雨。\n又争似、年年此际，先得东皇为主。\n好似雪里精神，曾解恼、游人吟顾。\n想当时折赠，端的凭谁付与。\n荡醉目、恨同云阻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3721, '洞仙歌', '刘', '凄凉楚弄，行客肠曾断。\n涛卷秋容暗淮甸。\n去年时、还是今日孤舟，烟浪里，身与江云共远。\n别来丹枕梦，几过沧洲，皓月而今为谁满。\n薄苦无端，误却婵娟，有人在、玉楼天半。\n最不愤、西风破帆来，甚时节，收拾望中心眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3722, '金明春・金明池', '刘', '宝历延洪，昌辰开泰，崧岳储灵特异。\n贤才并、□时间出，尽一一惊人绝艺。\n捧乡书、气格飘飘，似阆苑神仙，参差相继。\n纵子墨文章，相如才调，骤觉雷声平地。\n太守宾兴当此际。\n正瑞霭寒轻，虚堂风细。\n舞腰旋、飞尘仿佛，歌管递、清声嘹唳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3723, '内家娇', '刘', '绰约群芳里，阳和意，偏向一枝浓。\n南国骤惊，动人奇艳，未饶西洛，百本千丛。\n斩新弄，晓来无比格，半坼断肠红。\n三月洞天，又还疑是，赋情楚客，窥见墙东。\n朱阑干、遍倚生愁，怕无计、奈雨禁风。\n别有瑞烟幕幕，时与遮笼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3724, '安平乐慢', '刘', '细想劳生，等闲聚散，冉冉轻似秋烟。\n莲心暗苦，月意难圆。\n神京去路三千。\n当日风流，有妖饶枕上，软媚尊前。\n何计访蓬仙。\n断肠中、一叶晴川。\n到而今、追思往事，奈向梦也难到奴边。\n自恨不如兰灯，通宵尚照伊眠。\n恰道无缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3725, '佳人醉', '刘', '月到楼台第几。\n十里金虫成缀。\n袅琅、争绛球起。\n试新妆、嬉春粉黛，盈盈暗香，接谁家李。\n拥缇骑。\n箫鼓沸三市。\n别指春风画隼，归度鳌山影里。\n闲红翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3726, '惜双双令・惜分飞', '刘', '风外桔花香暗度。\n飞絮绾、残春归去。\n酝造黄梅雨。\n冷烟晓占横塘路。\n翠屏人在天低处。\n惊梦断、行云无据。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3727, '清平乐', '刘', '东风依旧。\n著意随堤柳。\n搓得鹅儿黄欲就。\n天色清明厮句。\n去年紫陌朱门。\n今朝雨魄云魂。\n断送一生憔悴，知他几个黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3728, '青门饮', '时彦', '胡马嘶风，汉旗翻雪，彤云又吐，一竿残照。\n古木连空，乱山无数，行尽暮沙衰草。\n星斗横幽馆，夜无眠、灯花空老。\n雾浓香鸭，冰凝泪烛，霜天难晓。\n长记晓妆才了，一杯未尽，离怀多少。\n醉里秋波，梦中朝雨，都是醒时烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3729, '瑶池宴令・越江吟', '廖正一', '飞花成阵。\n春心困。\n寸寸。\n别肠多少愁闷。\n无人问。\n偷啼自。\n残妆粉。\n抱瑶琴、寻出新韵。\n玉纤趁。\n南风未解幽愠。\n低云鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3730, '失调名', '董武子', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3731, '醉落魄・一斛珠', '哑女', '风波未息。\n虚名浮利终无益。\n不如早去备蓑笠。\n高卧烟霞，千古企难及。\n君今既已装行色。\n定应雁塔题名籍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3732, '望海潮', '秦观', '星分牛斗，疆连淮海，扬州万井提封。\n花发路香，莺啼人起，珠帘十里东风。\n豪俊气如虹。\n曳照春金紫，飞盖相从。\n巷入垂杨，画桥南北翠烟中。\n追思故国繁雄。\n有迷楼挂斗，月观横空。\n纹锦制帆，明珠溅雨，宁论爵马鱼龙。\n往事逐孤鸿。\n但乱云流水，萦带离宫。\n最好挥毫万字，一饮拼千锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3733, '望海潮', '秦观', '秦峰苍翠，耶溪潇洒，千岩万壑争流。\n鸳瓦雉城，谯门画戟，蓬莱燕阁三休。\n天际识归舟。\n泛五湖烟月，西子同游。\n茂草台荒，苎萝村冷起闲愁。\n何人览古凝眸。\n怅朱颜易失，翠被难留。\n梅市旧书，兰亭古墨，依稀风韵生秋。\n狂客鉴湖头。\n有百年台沼，终日夷犹。\n最好金龟换酒，相与醉沧洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3734, '望海潮', '秦观', '梅英疏淡，冰澌溶泄，东风暗换年华。\n金谷俊游，铜驼巷陌，新晴细履平沙。\n长记误随车。\n正絮翻蝶舞，芳思交加。\n柳下桃蹊，乱分春色到人家。\n西园夜饮鸣笳。\n有华灯碍月，飞盖妨花。\n兰苑未空，行人渐老，重来是事堪嗟。\n烟暝酒旗斜。\n但倚楼极目，时见栖鸦。\n无奈归心。\n暗随流水到天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3735, '望海潮', '秦观', '奴如飞絮，郎如流水，相沾便肯相随。\n微月户庭，残灯帘幕，匆匆共惜佳期。\n才话暂分携。\n早抱人娇咽，双泪红垂。\n画舸难停，翠帷轻别两依依。\n别来怎表相思。\n有分香帕子，合数松儿。\n红粉脆痕，青笺嫩约，丁宁莫遣人知。\n成病也因谁。\n更自言秋杪，亲去无疑。\n但恐生时注著，合有分于飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3736, '沁园春', '秦观', '宿霭迷空，腻云笼日，昼景渐长。\n正兰皋泥润，谁家燕喜，蜜脾香少，触处蜂忙。\n尽日无人帘幕挂，更风递游丝时过墙。\n微雨後，有桃愁杏怨，红泪淋浪。\n风流寸心易感，但依依伫立，回尽柔肠。\n念小奁瑶鉴，重匀绛蜡，玉笼金斗，时熨沈香。\n柳下相将游冶处，便回首青楼成异乡。\n相忆事，纵蛮笺万叠，难写微茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3737, '水龙吟', '秦观', '小楼连远横空，下窥绣毂雕鞍骤。\n朱帘半卷，单衣初试，清明时候。\n破暖轻风，弄晴微雨，欲无还有。\n卖花声过尽，斜阳院落，红成阵、飞鸳。\n玉佩丁东别後。\n怅佳期、参差难又。\n名缰利锁，天还知道，和天也瘦。\n花下重门，柳边深巷，不堪回首。\n念多情但有，当时皓月，向人依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3738, '八六子', '秦观', '倚危亭。\n恨如芳草，萋萋尽还生。\n念柳外青骢别後，水边红袂分时，怆然暗惊。\n无端天与娉婷。\n夜月一帘幽梦，春风十里柔情。\n怎奈向、欢娱渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，残雨笼晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3739, '风流子', '秦观', '东风吹碧草，年华换、行客老沧洲。\n见梅吐旧英，柳摇新绿，恼人春色，还上枝头。\n寸心乱，北随云黯黯，东逐水悠悠。\n斜日半山，暝烟两岸，数声横笛，一叶扁舟。\n青门同携手，前欢记、浑似梦里扬州。\n谁念断肠南陌，回首西楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3740, '梦扬州', '秦观', '晚云收。\n正柳塘、烟雨初休。\n燕子未归，恻恻清寒如秋。\n小阑外、东风软，透绣帷、花蜜香稠。\n江南远，人何处，鹧鸪啼破春愁。\n长记曾陪燕游。\n酬妙舞清歌，丽锦缠头。\n酒为花，十载因谁淹留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3741, '雨中花・夜行船', '秦观', '指点虚无征路，醉乘斑虬，远访西极。\n正天风吹落，满空寒白。\n玉女明星迎笑，何苦自淹尘域。\n正火轮飞上，雾卷烟开，洞观金碧。\n重重观阁，横枕鳌峰，水面倒衔苍石。\n随处有、奇香幽火，杳然难测。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3742, '一丛花', '秦观', '年时今夜见师师。\n双颊酒红滋。\n疏帘半卷微灯外，露华上、烟袅凉风。\n簪髻乱抛，偎人不起，弹泪唱新词。\n佳期。\n谁料久参差。\n愁绪暗萦丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3743, '鼓笛慢・水龙吟', '秦观', '乱花丛里曾携手，穷艳景，迷欢赏。\n到如今谁把，雕鞍锁定，阻游人来往。\n好梦随春远，从前事、不堪思想。\n念香闺正杳，佳欢未偶，难留恋、空惆怅。\n永夜婵娟未满，叹玉楼，几时重上。\n那堪万里，却寻归路，指阳关孤唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3744, '促拍满路花', '秦观', '露颗添花色。\n月彩投窗隙。\n春思如中酒，恨无力。\n洞房咫尺，曾寄情鸾翼。\n云散无踪迹。\n罗帐薰残，梦回无处寻觅。\n轻红腻白。\n步步熏兰泽。\n约腕金环重，宜妆饰。\n未知安否，一向无消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3745, '长相思', '秦观', '铁瓮城高，蒜山渡阔，干云十二层楼。\n开尊待月，掩箔披风，依然灯火扬州。\n绮陌南头。\n记歌名宛转，乡号温柔。\n曲槛俯清流。\n想花阴、谁系兰舟。\n念凄绝秦弦，感深荆赋，相望几许凝愁。\n勤勤裁尺素，奈双鱼、难渡瓜洲。\n晓鉴堪羞。\n潘鬓点、吴霜渐稠。\n幸于飞、鸳鸯未老，不应同是悲秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3746, '满庭芳', '秦观', '山抹微云，天连衰草，画角声断谯门。\n暂停征棹，聊共引离尊。\n多少蓬莱旧事，空回首、烟霭纷纷。\n斜阳外，寒鸦万点，流水绕孤村。\n销魂。\n当此际，香囊暗解，罗带轻分。\n谩赢得、青楼薄名存。\n此去何时见也，襟袖上、空惹啼痕。\n伤情处，高城望断，灯火已黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3747, '满庭芳', '秦观', '红蓼花繁，黄芦叶乱，夜深玉露初零。\n霁天空阔，云淡楚江清。\n独棹孤篷小艇，悠悠过、烟渚沙汀。\n金钩细，丝纶慢卷，牵动一潭星。\n时时，横短笛，清风浩月，相与忘形。\n任人笑生涯，泛梗飘萍。\n饮罢不妨醉卧，尘劳事、有耳谁听。\n江风静，日高未起，枕上酒微醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3748, '满庭芳', '秦观', '碧水惊秋，黄云凝暮，败叶零乱空阶。\n洞房人静，斜月照徘徊。\n又是重阳近也，几处处，砧杵声催。\n西窗下，风摇翠竹，疑是故人来。\n伤怀。\n增怅望，新欢易失，往事难猜。\n问篱边黄菊，知为谁开。\n谩道愁须酒，酒未醒、愁已先回。\n凭阑久，金波渐转，白露点苍苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3749, '江城子', '秦观', '西城杨柳弄春柔。\n动离忧。\n泪难收。\n犹记多情，曾为系归舟。\n碧野朱桥当日事，人不见，水空流。\n韶华不为少年留。\n恨悠悠。\n几时休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3750, '江城子', '秦观', '南来飞燕北归鸿。\n偶相逢。\n惨愁容。\n绿鬓朱颜，重见两衰翁。\n别後悠悠君莫问，无限事，不言中。\n小槽春酒滴珠红。\n莫匆匆。\n满金锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3751, '江城子', '秦观', '枣花金钏约柔荑。\n昔曾携。\n事难期。\n咫尺玉颜，和泪锁春闺。\n恰似小园桃与李，虽同处，不同枝。\n玉笙初度颤鸾篦。\n落花飞。\n为谁吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3752, '满园花・促拍满路花', '秦观', '一向沈吟久。\n泪珠盈襟袖。\n我当初不和、苦就。\n惯纵得软顽，见底心先有。\n行待痴心守。\n甚捻著脉子，倒把人来。\n近日来、非常罗皂丑。\n佛也须眉皱。\n怎掩得众人口。\n待收了孛罗，罢了从来斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3753, '迎春乐', '秦观', '菖蒲叶叶知多少。\n惟有个、蜂儿妙。\n雨晴红粉齐开了。\n露一点、娇黄小。\n早是被、晓风力暴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3754, '鹊桥仙', '秦观', '纤云弄巧，飞星传恨，银汉迢迢暗度。\n金风玉露一相逢，便胜却、人间无数。\n柔情似水，佳期如梦，忍顾鹊桥归路。\n两情若是长久时，又岂在、朝朝暮暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3755, '菩萨蛮', '秦观', '虫声泣露惊秋枕。\n罗帏泪湿鸳鸯锦。\n独卧玉肌凉。\n残更与恨长。\n阴风翻翠幔。\n雨涩灯花暗。\n毕竟不成眠。\n鸦啼金井寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3756, '减字木兰花', '秦观', '天涯旧恨。\n独自凄凉人不问。\n欲见回肠。\n断尽金炉小篆香。\n黛峨长敛。\n任是春风吹不展。\n困倚危楼。\n过尽飞鸿字字愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3757, '木兰花・玉楼春', '秦观', '秋容老尽芙蓉院。\n草上霜花匀似翦。\n西楼促坐酒杯深，风压绣帘香不卷。\n玉纤慵整银筝雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3758, '画堂春', '秦观', '落红铺尽水平池。\n弄晴小雨霏霏。\n杏园憔悴杜鹃啼。\n无奈春归。\n柳外画楼独上，凭阑手拈花枝。\n放花无语对斜晖。\n此恨谁知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3759, '千秋岁', '秦观', '水边沙外。\n城郭春寒退。\n花影乱，莺声碎。\n飘零疏酒盏，离别宽衣带。\n人不见，碧云暮合空相对。\n忆昔西池会。\n鹭同飞盖。\n携手处，今谁在。\n日边清梦断，镜里朱颜改。\n春去也，飞红万点愁如海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3760, '踏莎行', '秦观', '雾失楼台，月迷津渡。\n桃源望断无寻处。\n可堪孤馆闭春寒，杜鹃声里斜阳暮。\n驿寄梅花，鱼传尺素。\n砌成此恨无重数。\n郴江幸自绕郴山，为谁流下潇湘去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3761, '蝶恋花', '秦观', '晓日窥轩双燕语。\n似与佳人，共惜春将暮。\n屈指艳阳都几许。\n可无时霎闲风雨。\n流水落花无问处。\n只有飞云，冉冉来还去。\n持酒劝云云且住。\n凭君碍断春归路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3762, '一落索', '秦观', '杨花终日空飞舞。\n奈久长难驻。\n海潮虽是暂时来，却有个、堪凭处。\n紫府碧云为路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3763, '丑奴儿・采桑子', '秦观', '夜来酒醒清无梦，愁倚阑干。\n露滴轻寒。\n雨打芙蓉泪不乾。\n佳人别後音尘悄，瘦尽难拼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3764, '南乡子', '秦观', '妙手写徽真。\n水翦双眸点绛唇。\n疑是昔年窥宋玉，东邻。\n只露墙头一半身。\n往事已酸辛。\n谁记当年翠黛颦。\n尽道有些堪恨处，无情。\n任是无情也动人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3765, '醉桃源・阮郎归', '秦观', '碧天如水月如眉。\n城头银漏迟。\n绿波风动画船移。\n娇羞初见时。\n银烛暗，翠帘垂。\n芳心两自知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3766, '河传', '秦观', '乱花飞絮。\n又望空斗合，离人愁苦。\n那更夜来，一霎薄情风雨。\n暗掩将、春色去。\n篱枯壁尽因谁做。\n若说相思，佛也眉儿聚。\n莫怪为伊，底死萦肠惹肚。\n为没教、人恨处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3767, '河传', '秦观', '恨眉醉眼。\n甚轻轻著，神魂迷乱。\n常记那回，小曲阑干西畔。\n鬓云松、罗袜。\n丁香笑吐娇无限。\n语软声低，道我何曾惯。\n云雨未谐，早被东风吹散。\n闷损人、天不管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3768, '浣溪沙', '秦观', '漠漠轻寒上小楼。\n晓阴无赖似穷秋。\n淡烟流水画屏幽。\n自在飞花轻似梦，无边丝雨细如愁。\n宝帘闲挂小银钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3769, '浣溪沙', '秦观', '香靥凝羞一笑开。\n柳腰如醉暖相挨。\n日长春困下楼台。\n照水有情聊整鬓，倚阑无绪更兜鞋。\n眼边牵系懒归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3770, '浣溪沙', '秦观', '霜缟同心翠黛连。\n红绡四角缀金钱。\n恼人香是龙涎。\n枕上忽收疑是梦，灯前重看不成眠。\n又还一断恶因缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3771, '浣溪沙', '秦观', '脚上鞋儿四寸罗。\n唇边朱粉一樱多。\n见人无语但回波。\n料得有心怜宋玉，只应无奈楚襄何。\n今生有分共伊麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3772, '浣溪沙', '秦观', '锦帐重重卷暮霞。\n屏风曲曲斗红牙。\n恨人何事苦离家。\n枕上梦魂飞不去，觉来红日又西斜。\n满庭芳草衬残花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3773, '如梦令', '秦观', '门外鸦啼杨柳。\n春色著人如酒。\n睡起熨沈香，玉腕不胜金斗。\n消瘦。\n消瘦。\n还是褪花时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3774, '如梦令', '秦观', '遥夜沈沈如水。\n风紧驿亭深闭。\n梦破鼠窥灯，霜送晓寒侵被。\n无寐。\n无寐。\n门外马嘶人起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3775, '如梦令', '秦观', '幽梦匆匆破後。\n妆粉乱痕沾袖。\n遥想酒醒来，无奈玉销花瘦。\n回首。\n回首。\n绕岸夕阳疏柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3776, '如梦令', '秦观', '楼外残阳红满。\n春入柳条将半。\n桃李不禁风，回首落英无限。\n肠断。\n肠断。\n人共楚天俱远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3777, '如梦令', '秦观', '池上春归何处。\n满目落花飞絮。\n孤馆悄无人，梦断月堤归路。\n无绪。\n无绪。\n帘外五更风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3778, '阮郎归', '秦观', '褪花新绿渐团枝。\n扑人风絮飞。\n秋千未拆水平堤。\n落红成地衣。\n游蝶困，乳莺啼。\n怨春春怎知。\n日长早被酒禁持。\n那堪更别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3779, '阮郎归', '秦观', '宫腰袅袅翠鬟松。\n夜堂深处逢。\n无端银烛殒秋风。\n灵犀得暗通。\n身有恨，恨无穷。\n星河沈晓空。\n陇头流水各西东。\n佳期如梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3780, '阮郎归', '秦观', '潇湘门外水平铺。\n月寒征棹孤。\n红妆饮罢少踟蹰。\n有人偷向隅。\n挥玉箸，洒真珠。\n梨花春雨馀。\n人人尽道断肠初。\n那堪肠已无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3781, '阮郎归', '秦观', '湘天风雨破寒初。\n深沈庭院虚。\n丽谯吹罢小单于。\n迢迢清夜徂。\n乡梦断，旅魂孤。\n峥嵘岁又除。\n衡阳犹有雁传书。\n郴阳和雁无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3782, '满庭芳', '秦观', '北苑研膏，方圭圆璧，名动万里京关。\n碎身粉骨，功合上凌烟。\n尊俎风流战胜，降春睡、开拓愁边。\n纤纤捧，香泉溅乳，金缕鹧鸪斑。\n相如，方病酒，一觞一咏，宾有群贤。\n便扶起灯前，醉玉颓山。\n搜揽胸中万卷，还倾动，三峡词源。\n归来晚，文君未寝，相对晓妆残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3783, '满庭芳', '秦观', '晓色云开，春随人意，骤雨才过还晴。\n古台芳榭，飞燕蹴红英。\n舞困榆钱自落，秋千外、绿水桥平。\n东风里，朱门映柳，低底按小秦筝。\n多情。\n行乐处，珠钿翠盖，玉辔红缨。\n渐酒空金，花困蓬瀛。\n豆蔻梢头旧恨，十年梦，屈指堪惊。\n凭阑久，疏烟淡日，寂寞下芜城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3784, '满庭芳', '秦观', '雅燕飞觞，清谈挥座，使君高会群贤。\n密云双凤，初破缕金团。\n窗外炉烟似动，开瓶试、一品香泉。\n轻淘起，香生玉尘，雪溅紫瓯圆。\n娇鬟。\n宜美盼，双擎翠袖，稳步红莲。\n坐中客翻愁，酒醒歌阑。\n点上纱笼画烛，花骢弄、月影当轩。\n频相顾，馀欢未尽，欲去且流连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3785, '桃源忆故人', '秦观', '玉楼深锁薄情种。\n清夜悠悠谁共。\n羞见枕衾鸳凤。\n闷即和衣拥。\n无端画角严城动。\n惊破一番新梦。\n窗外月华霜重。\n听彻梅花弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3786, '调笑令', '秦观', '回顾。\n汉宫路。\n捍拨檀槽鸾对舞。\n玉容寂寞花无主。\n顾影偷弹玉箸。\n未央宫殿知何处。\n目送征鸿南去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3787, '调笑令', '秦观', '辇路。\n江枫古。\n楼上吹箫人在否。\n菱花半璧香尘污。\n往日繁华何处。\n旧欢新爱谁是主。\n啼笑两难分付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3788, '调笑令', '秦观', '翡翠。\n好容止。\n谁使庸奴轻点缀。\n裴郎一见心如醉。\n笑里偷传深意。\n罗衣中夜与门吏。\n暗结城西幽会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3789, '调笑令', '秦观', '相慕。\n无双女。\n当日尚书先曾许。\n王郎明俊神仙侣。\n肠断别离情苦。\n数年睽恨今复遇。\n笑指襄江归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3790, '调笑令', '秦观', '肠断。\n绣帘卷。\n妾愿身为梁上燕。\n朝朝暮暮长相见。\n莫遣恩迁情变。\n红绡粉泪知何限。\n万古空传遗怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3791, '调笑令', '秦观', '恋恋。\n楼中燕。\n燕子楼空春色晚。\n将军一去音容远。\n空锁楼中深怨。\n春风重到人不见。\n十二阑干倚遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3792, '调笑令', '秦观', '春梦。\n神仙洞。\n冉冉拂墙花树动。\n西厢待月知谁共。\n更觉玉人情重。\n红娘深夜行云送。\n困钗横金凤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3793, '调笑令', '秦观', '柳岸。\n水清浅。\n笑折荷花呼女伴。\n盈盈日照新妆面。\n水调空传幽怨。\n扁舟日暮笑声远。\n对此令人肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3794, '调笑令', '秦观', '眷恋。\n西湖岸。\n湖面楼台侵云汉。\n阿溪本是飞琼伴。\n风月朱扉斜掩。\n谢郎巧思诗裁翦。\n能动芳怀幽怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3795, '调笑令', '秦观', '心素。\n与谁语。\n始信别离情最苦。\n兰舟欲解春江暮。\n精爽随君归去。\n异时携手重来处。\n梦觉春风庭户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3796, '虞美人', '秦观', '高城望断尘如雾。\n不见联骖处。\n夕阳村外小湾头。\n只有柳花无数、送归舟。\n琼枝玉树频相见。\n只恨离人远。\n欲将幽事寄青楼。\n争奈无情江水、不西流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3797, '虞美人', '秦观', '碧桃天上栽和露。\n不是凡花数。\n乱山深处水潆回。\n可惜一枝如画、为谁开。\n轻寒细雨情何限。\n不道春难管。\n为君沈醉又何妨。\n祗怕酒醒时候、断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3798, '虞美人', '秦观', '行行信马横塘畔。\n烟水秋平岸。\n绿荷多少夕阳中。\n知为阿谁凝恨、背西风。\n红妆艇子来何处。\n荡桨偷相顾。\n鸳鸯惊起不无愁。\n柳外一双飞去、却回头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3799, '点绛唇', '秦观', '醉漾轻舟，信流引到花深处。\n尘缘相误。\n无计花间住。\n烟水茫茫，千里斜阳暮。\n山无数。\n乱红如雨。\n不记来时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3800, '点绛唇', '秦观', '月转乌啼，画堂宫徵生离恨。\n美人愁闷。\n不管罗衣褪。\n清泪斑斑，挥断柔肠寸。\n嗔人问。\n背灯偷。\n拭尽残妆粉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3801, '品令', '秦观', '幸自得。\n一分索强，教人难吃。\n好好地恶了十来日。\n恰而今、较些不。\n须管啜持教笑，又也何须织。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3802, '品令', '秦观', '掉又惧。\n天然个品格。\n於中压一。\n帘儿下时把鞋儿踢。\n语低低、笑咭咭。\n每每秦楼相见，见了无限怜惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3803, '南歌子', '秦观', '玉漏迢迢尽，银潢淡淡横。\n梦回宿酒未全醒。\n已被邻鸡催起、怕天明。\n臂上妆犹在，襟间泪尚盈。\n水边灯火渐人行。\n天外一钩残月、带三星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3804, '南歌子', '秦观', '愁鬓香云坠，娇眸水玉裁。\n月屏风幌为谁开。\n天外不知音耗、百般猜。\n玉露沾庭砌，金风动灰。\n相看有似梦初回。\n只恐又抛人去、几时来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3805, '南歌子', '秦观', '香墨弯弯画，燕脂淡淡匀。\n揉蓝衫子杏黄裙。\n独倚玉阑无语、点檀唇。\n人去空流水，花飞半掩门。\n乱山何处觅行云。\n又是一钩新月、照黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3806, '临江仙', '秦观', '千里潇湘蓝浦，蓝桡昔日曾经。\n月高风定露华清。\n微波澄不动，冷浸一天星。\n独倚危樯情悄悄，遥闻妃瑟泠泠。\n新声寒尽古今情。\n曲终人不见，江上数峰青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3807, '临江仙', '秦观', '髻子偎人娇不整，眼儿失睡微重。\n寻思模样早心忪。\n断肠携手，何事太匆匆。\n不忍残红犹在臂，翻疑梦里相逢。\n遥怜南埭上孤篷。\n夕阳流水，红满泪痕中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3808, '好事近', '秦观', '春路雨添花，花动一山春色。\n行到小溪深处，有黄鹂千百。\n飞云当面化龙蛇，夭矫转空碧。\n醉卧古藤阴下，了不知南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3809, '失调名', '秦观', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3810, '添春色・醉乡春', '秦观', '唤起一声人悄。\n衾冷梦寒窗晓。\n瘴雨过，海棠晴，春色又添多少。\n社瓮酿成微笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3811, '南柯子・南歌子', '秦观', '霭霭迷春态，溶溶媚晓光。\n不应容易下巫阳。\n祗恐翰林前世、是襄王。\n暂为清歌驻，还因暮雨忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3812, '失调名', '秦观', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3813, '失调名', '秦观', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3814, '画堂春', '秦观', '东风吹柳日初长。\n雨馀芳草斜阳。\n杏花零落燕泥香。\n睡损红妆。\n香篆暗消鸾凤，画屏萦绕潇湘。\n暮寒轻透薄罗裳。\n无限思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3815, '木兰花慢', '秦观', '过秦淮旷望，回萧洒、绝纤尘。\n爱清景风蛩，吟鞭醉帽，时度疏林。\n秋来政情味淡，更一重烟水一重云。\n千古行人旧恨，尽应分付今人。\n渔村。\n望断横门。\n芦荻浦、雁先闻。\n对触目凄凉，红凋岸蓼，翠减汀苹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3816, '御街行', '秦观', '银烛生花如红豆。\n这好事、而今有。\n夜阑人静曲屏深，借宝瑟、轻轻招手。\n一阵白苹风，故灭烛、教相就。\n花带雨、冰肌香透。\n恨啼鸟、辘轳声晓。\n岸柳微风吹残酒。\n断肠时、至今依旧。\n镜中消瘦。\n那人知後，怕你来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3817, '青门饮', '秦观', '风起云间，雁横天末，严城画角，梅花三奏。\n塞草西风，冻云笼月，窗外晓寒轻透。\n人去香犹在，孤衾长闲馀绣。\n恨与宵长，一夜薰炉，添尽香兽。\n前事空劳回首。\n虽梦断春归，相思依旧。\n湘瑟声沈，庾梅信断，谁念画眉人瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3818, '夜游宫', '秦观', '何事东君又去。\n空满院、落花飞絮。\n巧燕昵喃向谁语。\n何曾解、说伊家、些子苦。\n况是伤心绪。\n念个人、又成睽阻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3819, '醉蓬莱', '秦观', '见扬州独有，天下无双，号为琼树。\n占断天风，岁花开两次。\n九朵一苞，攒成环玉，心似珠玑缀。\n瓣瓣玲珑，枝枝洁净，世上无花类。\n冷露朝凝，香风远送，信是琼瑶贵。\n料得天宫有，此地久难留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3820, '满江红', '秦观', '越艳风流，占天上、人间第一。\n须信道、绝尘标致，倾城颜色。\n翠绾垂螺双髻小，柳柔花媚娇无力。\n笑从来、到处只闻名，今相识。\n脸儿美，鞋儿窄。\n玉纤嫩，酥胸白。\n自觉愁肠搅乱，坐中狂客。\n金缕和杯曾有分，宝钗落枕知何日。\n谩从今、一点在心头，空成忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3821, '一斛珠', '秦观', '碧云寥廓。\n倚阑怅望情离索。\n悲秋自怯罗衣薄。\n晓镜空悬，懒把青丝掠。\n江山满眼今非昨。\n纷纷木叶风中落。\n别巢燕子辞帘幕。\n有意东君，故把红丝缚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3822, '西江月', '米芾', '溪面荷香粲粲，林端远岫青青。\n楚天秋色太多情。\n云卷烟收风定。\n夜静冰娥欲上，梦回醉眼初醒。\n玉瓶未耻有新声。\n一曲请君来听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3823, '菩萨蛮', '米芾', '蒹葭风外烟笼柳。\n数叠遥山眉黛秀。\n微雨过江来。\n烦襟为一开。\n沙边临望处。\n紫燕双飞语。\n举酒送飞云。\n夜凉愁梦频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3824, '水调歌头', '米芾', '砧声送风急，蟋蟀思高秋。\n我来对景，不学宋玉解悲愁。\n收拾凄凉兴况，分付尊中，倍觉不胜幽。\n自有多情处，明月挂南楼。\n怅襟怀，横玉笛，韵悠悠。\n清时良夜，借我此地倒金瓯。\n可爱一天风物，遍倚阑干十二，宇宙若萍浮。\n醉困不知醒，枕卧江流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3825, '渔家傲', '米芾', '昔日丹阳行乐里。\n紫金浮玉临无地。\n宝阁化成弥勒世。\n龙宫对。\n时时更有天花坠。\n浩渺一天秋水至。\n鲸鲵鼓鬣连山沸。\n员峤岱舆更。\n无根蒂。\n莫教龙伯邦人戏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3826, '丑奴儿・采桑子', '米芾', '踯蹰山下濡须水，我更委佗。\n物阜时和。\n迨暇相逢笑复歌。\n江湖楼上凭阑久，极目沧波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3827, '减字木兰花', '米芾', '云间皓月。\n光照银淮来万折。\n海岱楼中。\n拂袖雄披楚岸风。\n醉馀清夜。\n羽扇纶巾人入画。\n江远淮长。\n举首宗英醒更狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3828, '减字木兰花', '米芾', '平生真赏。\n纸上龙蛇三五行。\n富贵功名。\n老境谁堪宠辱惊。\n寸心谁语。\n只有当年袁与许。\n归到寥阳。\n玉简霞衣侍帝旁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3829, '点绛唇', '米芾', '莘野寥寥，渭滨漠漠情何限。\n万重堆案。\n懒更重经眼。\n儿辈休惊，头上霜华满。\n功名晚。\n水云萧散。\n漫就驿亭看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3830, '阮郎归', '米芾', '双双鸳鸯戏苹洲。\n几行烟柳柔。\n一声长笛咽清秋。\n碧云生暮愁。\n钩月挂，绮霞收。\n浦南人泛舟。\n娟娟何处烛明眸。\n相望徒倚楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3831, '蝶恋花', '米芾', '千古涟漪清绝地。\n海岱楼高，下瞰秦淮尾。\n水浸碧天天似水。\n广寒宫阙人间世。\n霭霭春和生海市。\n鳌戴三山，顷刻随轮至。\n宝月圆时多异气。\n夜光一颗千金贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3832, '诉衷情', '米芾', '薰风吹动满池莲。\n晓云楼阁鲜。\n绣阁华堂嘉会，齐拜玉炉烟。\n斟美酒，奉觥船。\n祝芳筵。\n宜春耐夏，多福壮严，富贵长年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3833, '诉衷情', '米芾', '劳生奔走困粗官。\n揽镜鬓毛斑。\n物外平生萧散，微宦兴阑珊。\n奇胜处，每平阑。\n定望远。\n好山如画，水绕云萦，无计成闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3834, '鹧鸪天', '米芾', '暖日晴烘候小春。\n际天和气与精神。\n灵台静养千年寿，丹灶全无一点尘。\n寿彭祖，寿广成。\n华阳仙裔是今身。\n夜来银汉清如洗，南极星中见老人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3835, '鹧鸪天', '米芾', '云液无声白似银。\n红霞一抹百花新。\n觞多莫压频频劝，一片花飞减却春。\n蜂翅乱，蝶眉颦。\n花间啼鸟劝游人。\n人生无事须行乐，富贵何时且健身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3836, '浪淘沙', '米芾', '祝寿庆生申。\n德日维新。\n期颐眉寿寿长春。\n五福三灵禄永永，长寿仙人。\n遐算等庄椿。\n□德康宁。\n年年欢会笑欣欣。\n岁岁仰依□寿域，彭祖广成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3837, '浣溪沙', '米芾', '日射平溪玉宇中。\n云横远渚岫重重。\n野花犹向涧边红。\n静看沙头鱼入网，闲支藜杖醉吟风。\n小春天气恼人浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3838, '醉太平', '米芾', '风炉煮茶。\n霜刀剖瓜。\n暗香微透窗纱。\n是池中藕花。\n高梳髻鸦。\n浓妆脸霞。\n玉尖弹动琵琶。\n问香醪饮麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3839, '望云涯引', '李甲', '秋容江上，岸花老，苹洲白。\n露湿蒹葭，浦屿渐增寒色。\n闲渔唱晚，鹜雁惊飞处，映远碛。\n数点轻帆，送天际归客。\n凤台人散，漫回首。\n沈消息。\n素鲤无凭，楼上暮云凝碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3840, '吊严陵', '李甲', '蕙兰香泛，孤屿潮平，惊鸥散雪。\n迤逦点破，澄江秋色。\n暝霭向敛，疏雨乍收，染出蓝峰千尺。\n渔舍孤烟锁寒碛。\n画翠帆旋解，轻舣晴霞岸侧。\n正念往悲酸，怀乡惨切。\n何处引羌笛。\n追惜。\n当时富春佳地，严光钓址空遗迹。\n华星沈後，扁舟泛去，萧洒闲名图籍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3841, '梦玉人引', '李甲', '渐东风暖，陇梅残，霁云碧。\n嫩草柔条，又回江城春色。\n乍促银签，便篆香纹蜡有馀迹。\n愁梦相兼，尽日高无力。\n这些离恨，依然是、酒醒又如织。\n料伊怀情，也应向人端的。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3842, '过秦楼', '李甲', '卖酒炉边，寻芳原上，乱花飞絮悠悠。\n已蝶稀莺散，便拟把长绳、系日无由。\n谩道草忘忧。\n也徒将，酒解闲愁。\n正江南春尽，行人千里，苹满汀洲。\n有翠红径里，盈盈似簇，芳茵禊饮，时笑时讴。\n当暖风迟景，任相将永日，烂熳狂游。\n谁信盛狂中，有离情、忽到心头。\n向尊前拟问，双燕来时，曾过秦楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3843, '帝台春', '李甲', '芳草碧色，萋萋遍南陌。\n暖絮乱红，也知人、春愁无力。\n忆得盈盈拾翠侣，共携赏、凤城寒食。\n到今来，海角逢春，天涯为客。\n愁旋释。\n还似织。\n泪暗拭。\n又偷滴。\n谩伫立、遍倚危阑，尽黄昏，也只是、暮云凝碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3844, '击梧桐', '李甲', '杳杳春江阔。\n收细雨、风蹙波声无歇。\n雁去汀洲暖，岸芜静，翠染遥山一抹。\n群鸥聚散，征航来去，隔水相望楚越。\n对此、凝情久，念往岁上国，嬉游时节。\n斗草园林，卖花巷陌，触处风光奇绝。\n正恁浓欢里，悄不意、顿有天涯离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3845, '幔卷绸・慢卷绸', '李甲', '绝羽沈鳞，埋花葬玉，杳杳悲前事。\n对一盏寒灯，数点流萤，悄悄画屏，巫山十二。\n脸星眸，蕙情兰性，一旦成流水。\n便纵有、甘泉妙手，洪都方士何济。\n香闺宝砌。\n临妆处，迤逦苔痕翠。\n更不忍看伊，绣残鸳侣，而今尚有，啼红粉渍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3846, '望春回', '李甲', '霁霞散晓，射水村渐明，渔火方绝。\n滩露夜潮痕，注冻濑凄咽。\n征鸿来时应负书，见疏柳、更忆伊同折。\n异乡憔悴，那堪更逢，岁穷时节。\n东风暗回暖律。\n算拆遍江梅，消尽岩雪。\n唯有这愁肠，也依旧千结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3847, '少年游', '李甲', '江国陆郎封寄後，独自冠群芳。\n折时雪里，带时灯下，香面讶争光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3848, '蝶恋花', '赵令', '丽质仙娥生月殿。\n谪向人间，未免凡情乱。\n宋玉墙东流美盼。\n乱花深处曾相见。\n密意浓欢方有便。\n不奈浮名，旋遣轻分散。\n最恨多才情太浅。\n等闲不念离人怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3849, '蝶恋花', '赵令', '锦额重帘深几许。\n绣履弯弯，未省离朱户。\n强出娇羞都不语。\n绛绡频掩酥胸素。\n黛浅愁红妆淡伫。\n怨绝情凝，不肯聊回顾。\n媚脸未匀新泪污。\n梅英犹带春朝露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3850, '蝶恋花', '赵令', '懊恼娇痴情未惯。\n不道看看，役得人肠断。\n万语千言都不管。\n兰房跬步如天远。\n废寝忘餐思想遍。\n赖有青鸾，不必凭鱼雁。\n密写香笺论缱绻。\n春词一纸芳心乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3851, '蝶恋花', '赵令', '庭院黄昏春雨霁。\n一缕深心，百种成牵系。\n青翼蓦然来报喜。\n鱼笺微谕相容意。\n待月西厢人不寐。\n帘影摇光，朱户犹慵闭。\n花动拂墙红萼坠。\n分明疑是情人至。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3852, '蝶恋花', '赵令', '屈指幽期惟恐误。\n恰到春宵，明月当三五。\n红影压墙花密处。\n花阴便是桃源路。\n不谓兰诚金石固。\n敛袂怡声，恣把多才数。\n惆怅空回谁共语。\n只应化作朝云去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3853, '蝶恋花', '赵令', '数夕孤眠如度岁。\n将谓今生，会合终无计。\n正是断肠凝望际。\n云心捧得嫦娥至。\n玉困花柔羞泪。\n端丽妖娆，不与前时比。\n人去月斜疑梦寐。\n衣香犹在妆留臂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3854, '蝶恋花', '赵令', '一梦行云还暂阻。\n尽把深诚，缀作新诗句。\n幸有青鸾堪密付。\n良宵从此无虚度。\n两意相欢朝又暮。\n争奈郎鞭，暂指长安路。\n最是动人愁怨处。\n离情盈抱终无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3855, '蝶恋花', '赵令', '碧沼鸳鸯交颈舞。\n正恁双栖，又遣分飞去。\n洒翰赠言终不许。\n援琴请尽奴衷素。\n曲未成声先怨慕。\n忍泪凝情，强作霓裳序。\n弹到离愁凄咽处。\n弦肠俱断梨花雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3856, '蝶恋花', '赵令', '别後相思心目乱。\n不谓芳音，忽寄南来雁。\n却写花笺和泪卷。\n细书方寸教伊看。\n独寐良宵无计遣。\n梦里依稀，暂若寻常见。\n幽会未终魂已断。\n半衾如暖人犹远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3857, '蝶恋花', '赵令', '尺素重重封锦字。\n未尽幽闺，别後心中事。\n佩玉采丝文竹器。\n愿君一见知深意。\n环玉长圆丝万系。\n竹上斓斑，总是相思泪。\n物会见郎人永弃。\n心驰魂去神千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3858, '蝶恋花', '赵令', '梦觉高唐云雨散。\n十二巫峰，隔断相思眼。\n不为旁人移步懒。\n为郎憔悴羞郎见。\n青翼不来孤凤怨。\n露失桃源，再会终无便。\n旧恨新愁无计遣。\n情深何似情俱浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3859, '蝶恋花', '赵令', '镜破人离何处问。\n路隔银河，岁会知犹近。\n只道新来消瘦损。\n玉容不见空传信。\n弃掷前欢俱未忍。\n岂料盟言，陡顿无凭准。\n地久天长终有尽，绵绵不似无穷恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3860, '天仙子', '赵令', '宿雨洗空台榭莹。\n下尽珠帘寒未定。\n花开花落几番晴，春欲竟。\n愁未醒。\n池面杏花红透影。\n一纸短书言不尽。\n明月清风还记省。\n玉楼香断又天香，闲展兴。\n临好景。\n心似乱萍何处整。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3861, '浣溪沙', '赵令', '稳小弓鞋三寸罗。\n歌唇清韵一樱多。\n灯前秀艳总横波。\n指下鸣泉清杳渺，掌中回旋小婆娑。\n明朝归路奈情何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3862, '菩萨蛮', '赵令', '轻鸥欲下春塘浴。\n双双飞破春烟绿。\n两岸野蔷薇。\n翠笼薰绣衣。\n凭船闲弄水。\n中有相思意。\n忆得去年时。\n水边初别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3863, '菩萨蛮', '赵令', '长淮渺渺寒烟白。\n凭阑人是霜台客。\n诗句妙春豪。\n风云不啻高。\n樽前人已老。\n馀恨连芳草。\n一曲酒醒时。\n梧桐月欲低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3864, '菩萨蛮', '赵令', '春风试手先梅蕊。\n姿冷艳明沙水。\n不受众芳知。\n端须月与期。\n清香闲自远。\n先向钗头见。\n雪後燕瑶池。\n人间第一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3865, '好事近', '赵令', '急雨涨溪浑，小树带山秋色。\n轻棹暮天归路，袅芙蓉烟白。\n酒醒香冷梦回时，虫声正凄绝。\n只觉小窗风月，与昨宵都别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3866, '小重山', '赵令', '楼上风和玉漏迟。\n秋千庭院静，百花飞。\n午窗才起暖金卮。\n匀面了，阑畔看春池。\n何事苦颦眉。\n碧云春信断，尽来时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3867, '小重山', '赵令', '雨霁风高天气清。\n玉盘浮出海，转空明。\n小窗帘影冷如冰。\n愁不寐，独自傍阶行。\n情似浪头轻。\n一番销欲尽，一番生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3868, '蝶恋花', '赵令', '欲减罗衣寒未去。\n不卷珠帘，人在深深处。\n红杏枝头花几许。\n啼痕止恨清明雨。\n尽日沈烟香一缕。\n宿酒醒迟，恼破春情绪。\n飞燕又将归信误。\n小屏风上西江路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3869, '蝶恋花', '赵令', '卷絮风头寒欲尽。\n坠粉飘香，日日红成阵。\n新酒又添残酒困。\n今春不减前春恨。\n蝶去莺飞无处问。\n隔水高楼，望断双鱼信。\n恼乱横波秋一寸。\n斜阳只与黄昏近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3870, '西江月', '赵令', '人世一场大梦，我生魔了十年。\n明窗千古探遗编。\n不救饥寒一点。\n更被维摩老子，不教此处容言。\n炉薰清炷坐安禅。\n物物头头显现。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3871, '满庭芳', '赵令', '玉枕生凉，金缸传晓，败叶飞破清秋。\n雨馀翻浪，渺渺阻行舟。\n暂系汀洲侧畔，风夜起、荻叶添愁。\n银屏远，龙香渐尽，还是梦扬州。\n更筹。\n何太永，当年情事，今日堪酬。\n最苦恨红楼，笑我飘浮。\n为寄相思细字，教字字、愁蹙眉头。\n凄凉久，渔人唱晓，随月过横沟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3872, '清平乐', '赵令', '春风依旧。\n著意随堤柳。\n搓得蛾儿黄欲就。\n天气清明时候。\n去年紫陌青门。\n今霄雨魄云魂。\n断送一生憔悴，只销几个黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3873, '思远人', '赵令', '素玉朝来有好怀。\n一枝梅粉照人开。\n晴云欲向杯中起，春色先从脸上来。\n深院落，小楼台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3874, '临江仙', '赵令', '枝上粉香吹欲尽，依前庭院春风。\n更谁同绕摘芳丛。\n漏残金兽冷，信断锦屏空。\n看结灯花愁不睡，酒阑无梦相逢。\n凄凉长判一生中。\n不如云外月，永夜在房栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3875, '虞美人', '赵令', '画船稳泛春波渺。\n夕雨寒声小。\n紫烟深处数峰横。\n惊起一滩鸥鹭、照川明。\n西楼今夜归期误。\n恨入阑干暮。\n可堪春事满春怀。\n不似珠帘新燕、早归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3876, '浣溪沙', '赵令', '风急花飞昼掩门。\n一帘残雨滴黄昏。\n便无离恨也销魂。\n翠被任熏终不暖，玉杯慵举几番温。\n个般情事与谁论。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3877, '浣溪沙', '赵令', '槐柳春馀绿涨天。\n酒旗高插夕阳边。\n谁家墙里笑秋千。\n往事不堪楼上看，新愁多向曲中传。\n此情销得是何年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3878, '浣溪沙', '赵令', '一朵梦云惊晓鸦。\n数枝春雨带梨花。\n坐来残月冷窗纱。\n钗凤谩曾留得半，枕山犹是枕时斜。\n对花今日奈天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3879, '浣溪沙', '赵令', '水满池塘花满枝。\n乱香深里语黄鹂。\n东风轻软弄帘帏。\n日正长时春梦短，燕交飞处柳烟低。\n玉窗红子斗棋时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3880, '浣溪沙', '赵令', '少日怀山老住山。\n一官休务得身闲。\n几年食息白云间。\n似我乐来真是少，见人忙处不相关。\n养真高静出尘寰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3881, '鹧鸪天', '赵令', '可是相逢意便深。\n为郎巧笑不须金。\n门前一尺春风髻，窗内三更夜雨衾。\n情渺渺，信沈沈。\n青莺无路寄芳音。\n山城钟鼓愁难听，不解襄王梦里寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3882, '鹧鸪天', '赵令', '麝发雕炉小袖笼。\n天教我被此时同。\n橼经雪重香方满，菊到秋深色自浓。\n船槛内，月明中。\n插花归去莫匆匆。\n人生更在艰难内，胜事年来不易逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3883, '失调名', '赵令', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3884, '临江仙', '赵令', '翠袖卷纱红映肉，无风玉骨生寒。\n可堪新晓雨初残。\n颦眉谁恼著，粉泪滴阑干。\n闻道谪仙歌妙语，新妆再发愁颜。\n雾帘云幕荐金盘。\n笔间长借句，直莫放春还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3885, '乌夜啼', '赵令', '楼上萦帘弱絮，墙头凝月低花。\n年年春事关心事，肠断欲栖鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3886, '天宁乐・金人捧露盘', '贺铸', '斗储祥，虹流祉，兆黄虞。\n未□□、□圣真符。\n千龄叶应，九河清、神物出龟图。\n□□□□，□盛时、朝野欢娱。\n靡不覆，旋穹□，□□□，□坤舆。\n致万国、一变华胥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3887, '□□□・七娘子', '贺铸', '□波飞□□□向。\n□□□、□□□□样。\n拥鼻微吟，捋须遐想。\n□□□□□□上。\n会须加数□□酿。\n□□□、□□□□涨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3888, '鸳鸯语・七娘子', '贺铸', '京江抵、海边吴楚。\n铁瓮城、行胜无今古。\n北固陵高，西津横渡。\n几人携手分襟处。\n凄凉渌水桥南路。\n奈玉壶、难叩鸳鸯语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3889, '璧月堂・小重山', '贺铸', '梦草池南璧月堂。\n绿阴深蔽日，啭鹂黄。\n淡蛾轻鬓似宜妆。\n歌扇小，烟雨画潇湘。\n薄晚具兰汤。\n雪肌英粉腻，更生香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3890, '群玉轩・小重山', '贺铸', '群玉轩中迹已陈。\n江南重喜见，广陵春。\n纤合度好腰身。\n歌水钓，清啭□□□。\n团扇掩樱唇。\n七双胡蝶子，表□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3891, '□□□・小重山', '贺铸', '隔水桃花□□□。\n□□□□□，□□□。\n□妆飞鹊镜台前。\n□□□，□□□□□。\n□首已依然。\n断云疏雨後，更闻蝉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3892, '辨弦声・迎春乐', '贺铸', '琼琼绝艺真无价。\n指尖纤、态闲暇。\n几多方寸关情话。\n都付与、弦声写。\n三月十三寒食夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3893, '攀鞍态・迎春乐', '贺铸', '逢迎一笑金难买。\n小樱唇、浅蛾黛。\n玉环风调依然在。\n想花下、攀鞍态。\n伫倚碧云如有待。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3894, '辟寒金・迎春乐', '贺铸', '六华应腊妆吴苑。\n小山堂、晚张燕。\n赏心不厌杯行缓。\n待月度、银河半。\n缥缈郢人歌已断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3895, '尔汝歌・清商怨', '贺铸', '劳生羁宦未易处。\n赖醉□□□。\n白眼青天，忘形相尔汝。\n□□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3896, '□□□・清商怨', '贺铸', '扬州商女□□□。\n□□□□□。\n□寄扁舟，江南湖北道。\n津头龙祠屡□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3897, '半死桐・鹧鸪天', '贺铸', '重过阊门万事非。\n同来何事不同归。\n梧桐半死清霜後，头白鸳鸯失伴飞。\n原上草，露初。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3898, '翦朝霞・鹧鸪天', '贺铸', '云弄轻阴谷雨乾。\n半垂油幕护残寒。\n化工著意呈新巧，翦刻朝霞露盘。\n辉锦绣，掩芝兰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3899, '避少年・鹧鸪天', '贺铸', '谁爱松林水似天。\n画船听雨奈无眠。\n清风明月休论价，卖与愁人直几钱。\n挥醉笔，扫吟笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3900, '□□□・鹧鸪天', '贺铸', '留落吴门□□□。\n□□□□□□□。\n扁舟更入毗陵道，却□□□□□□。\n□□念，付清觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3901, '千叶莲・鹧鸪天', '贺铸', '闻你侬嗟我更嗟。\n春霜一夜扫华。\n永无清啭欺头管，赖有浓香著臂纱。\n侵海角，抵天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3902, '第一花・鹧鸪天', '贺铸', '豆蔻梢头莫漫夸。\n春风十里旧繁华。\n金缕玉蕊皆殊艳，别有倾城第一花。\n春雀舫，紫云车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3903, '花想容・武陵春', '贺铸', '南国家人推阿秀，歌醉几相逢。\n云想衣裳花想容。\n春未抵情浓。\n津亭回首青楼远，帘箔更重重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3904, '□□□・捣练子', '贺铸', '楼上鼓，转□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3905, '夜捣衣・捣练子', '贺铸', '收锦字，下鸳机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3906, '杵声齐・捣练子', '贺铸', '砧面莹，杵声齐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3907, '夜如年・捣练子', '贺铸', '斜月下，北风前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3908, '翦征袍・捣练子', '贺铸', '抛练杵，傍窗纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3909, '望书归・捣练子', '贺铸', '边堠远，置邮稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3910, '醉厌厌・南歌子', '贺铸', '紫陌青丝，红尘白衫。\n谁怜绣户闭香奁。\n分付一春心事、两眉尖。\n怯冷重熏被，羞明半卷帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3911, '窗下绣・一落萦', '贺铸', '初见碧纱窗下绣。\n寸波频溜。\n错将黄晕压檀花，翠袖掩、纤纤手。\n金缕一双红豆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3912, '艳声歌・添声杨柳枝', '贺铸', '蜀锦尘香生袜罗。\n小婆娑。\n个侬无赖动人多。\n是横波。\n楼角云开风卷幕，月侵河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3913, '唤春愁・添声杨柳枝', '贺铸', '天与多情不自由。\n占风流。\n云闲草远絮悠悠。\n唤春愁。\n试作小妆窥晚镜，淡蛾羞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3914, '花幕暗・添声杨柳枝', '贺铸', '绿绮新声隔坐闻。\n认殷勤。\n尊前为舞郁金裙。\n酒微醺。\n月转参横花幕暗，夜初分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3915, '晚云高・添声杨柳枝', '贺铸', '秋尽江南叶未凋。\n晚云高。\n情山隐隐水迢迢。\n接亭皋。\n二十四桥明月夜，弭兰桡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3916, '钓船归・添声杨柳枝', '贺铸', '绿净春深好染衣。\n际柴扉。\n溶溶漾漾白鸥飞。\n两忘机。\n南去北来徒自老，故人稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3917, '爱孤云・添声杨柳枝', '贺铸', '闲爱孤云静爱僧。\n得良朋。\n清时有味是无能。\n矫聋丞。\n况复早年豪纵过，病婴仍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3918, '替人愁・添声杨柳枝', '贺铸', '风紧云轻欲变秋。\n雨初收。\n江城水路漫悠悠。\n带汀洲。\n正是客心孤回处，转归舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3919, '梦江南・忆江南', '贺铸', '九曲池头三月三。\n柳毵毵。\n香尘扑马喷金衔。\n春衫。\n苦笋鲥鱼乡味美，梦江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3920, '愁风月・生查子', '贺铸', '风清月正圆，信是佳时节。\n不会长年来，处处愁风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3921, '绿罗裙・生查子', '贺铸', '东风柳陌长，闭月花房小。\n应念画眉人，拂镜啼新晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3922, '陌上郎・生查子', '贺铸', '西津海鹘舟，径渡沧江雨。\n双橹本无情，鸦轧如人语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3923, '卷春空・定风波', '贺铸', '墙上夭桃簌簌红。\n巧随轻絮入帘栊。\n自是芳心贪结子。\n翻使。\n惜花人恨五更风。\n露萼鲜浓妆脸靓。\n相映。\n隔年情事此门中。\n粉面不知何处在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3924, '桃源行・蝶恋花', '贺铸', '流水长烟何缥缈。\n诘□□□，□逗渔舟小。\n夹岸桃花烂□□。\n□□□□□□□。\n萧闲村落田畴好。\n避地移家，□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3925, '西笑吟・蝶恋花', '贺铸', '桃叶园林风日好。\n曲径珍丛，处处闻啼鸟。\n翠珥金丸委芳草。\n袜罗尘动香裙扫。\n片帆乘兴东流早。\n每话长安，引领犹西笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3926, '望长安・蝶恋花', '贺铸', '排办张灯春事早。\n十二都门，物色宜新晓。\n金犊车轻玉骢小。\n拂头杨柳穿驰道。\n莼羹鲈非吾好。\n去国讴吟，半落江南调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3927, '呈纤手・玉楼春', '贺铸', '秦弦络络呈纤手。\n宝雁斜飞三十九。\n徵韶新谱日边来，倾耳吴娃惊未有。\n文园老令难堪酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3928, '归风便・玉楼春', '贺铸', '津亭薄晚张离燕。\n红粉□歌持酒劝。\n歌声煎泪欲沾襟，酒色□□□□□。\n□□会有归风便。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3929, '续渔歌・玉楼春', '贺铸', '中年多办收身具。\n投老归来无著处。\n四肢安稳一渔舟，祗许樵青相伴去。\n沧洲大胜黄尘路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3930, '惜馀春・踏莎行', '贺铸', '急雨收春，斜风约水。\n浮红涨绿鱼文起。\n年年有子惜馀春，春归不解招游子。\n留恨城隅，关情纸尾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3931, '题醉袖・踏莎行', '贺铸', '浅黛宜颦，明波欲溜。\n逢迎宛似平生旧。\n低鬟促坐认弦声，霞觞艳艳持为寿。\n浓染吟毫，偷题醉袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3932, '阳羡歌・踏莎行', '贺铸', '山秀芙蓉，溪明罨画。\n真游洞穴沧波下。\n临风慨想斩蛟灵，长桥千载犹横跨。\n解组投簪，求田问舍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3933, '芳心苦・踏莎行', '贺铸', '杨柳回塘，鸳鸯别浦。\n绿萍涨断莲舟路。\n断无蜂蝶慕幽香，红衣脱尽芳心苦。\n返照迎潮，行云带雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3934, '平阳兴・踏莎行', '贺铸', '凉叶辞风，流云卷雨。\n寥寥夜色沈钟鼓。\n谁调清管度新声，有人高卧平阳坞。\n草暖沧洲，潮平别浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3935, '晕眉山・踏莎行', '贺铸', '镜晕眉山，囊熏水麝。\n凝然风度长闲暇。\n归来定解裘，唤时应倍骅骝价。\n酒伤春，添香惜夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3936, '思牛女・踏莎行', '贺铸', '楼角参横，庭心月午。\n侵阶夜色凉经雨。\n轻罗小扇扑流萤，微云渡汉思牛女。\n拥髻柔情，扶肩昵语。\n可怜分破□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3937, '负心期・浣溪沙', '贺铸', '节物侵寻迫暮迟。\n可胜摇落长年悲。\n回首五湖乘兴地，负心期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3938, '醉中真・浣溪沙', '贺铸', '不信芳春厌老人。\n老人几度送春归。\n惜春行乐莫辞频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3939, '频载酒・浣溪沙', '贺铸', '金斗城南载酒频。\n东西飞观跨通津。\n漾舟聊送雨馀春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3940, '掩萧斋・浣溪沙', '贺铸', '落日逢迎朱雀街。\n共乘青舫度秦淮。\n笑拈飞絮金钗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3941, '杨柳陌・浣溪沙', '贺铸', '兴庆宫池整月开。\n□□□□缕金鞋。\n後庭芳草绿缘阶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3942, '换追风・浣溪沙', '贺铸', '掌上香罗六寸弓。\n雍容胡旋一盘中。\n目成心许两匆匆。\n别夜可怜长共月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3943, '最多宜・浣溪沙', '贺铸', '半解香绡扑粉肌。\n避风长下绛纱帷。\n碧琉璃水浸琼枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3944, '锦缠头・浣溪沙', '贺铸', '旧说山阴禊事休。\n漫书茧纸叙清游。\n吴门千载更风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3945, '将进酒・梅花引', '贺铸', '城下路。\n凄风露。\n今人犁田古人墓。\n岸头沙。\n带蒹葭。\n漫漫惜时，流水今人家。\n黄埃赤日长安道。\n倦客无浆马无草。\n开函关。\n掩函关。\n千古如何，不见一人闲。\n六国扰。\n三秦扫。\n初谓商山遗四老。\n驰单车。\n致缄书。\n裂荷焚芰，接武曳长裙。\n高流端得酒中趣。\n深入醉乡安稳处。\n生忘行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3946, '行路难・梅花引', '贺铸', '缚虎手。\n悬河口。\n车如鸡栖马如狗。\n白纶巾。\n扑黄尘。\n不知我辈，可是蓬蒿人。\n衰兰送客咸阳道。\n天若有情天亦老。\n作雷颠。\n不论钱。\n谁问旗亭，美酒斗十千。\n酌大斗。\n更为寿。\n青鬓常青古无有。\n笑嫣然。\n舞翩然。\n当垆秦女，十五语如弦。\n遗音能记秋风曲。\n事去千年犹恨促。\n揽流光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3947, '东邻妙・玉楼春', '贺铸', '张灯结绮笼驰道。\n六六洞天连夜到。\n韶华吹断紫云回，怊怅人间新梦觉。\n倾城犹记东邻妙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3948, '问歌颦・雨中花令', '贺铸', '清滑京江人物秀。\n富美发、丰肌素手。\n宝子馀妍，阿娇馀韵，独步秋娘後。\n奈倦客襟怀先怯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3949, '画楼空・诉衷情', '贺铸', '吴门春水雪初融。\n触处小桡通。\n满城弄黄杨柳，著意恼春风。\n弦管闹，绮罗丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3950, '偶相逢・诉衷情', '贺铸', '采山涌起翠楼空。\n箫鼓沸春风。\n桂娥唤回清昼，夹路宝芙蓉。\n长步障，小纱笼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3951, '步花间・诉衷情', '贺铸', '凭陵残醉步花间。\n风棹佩珊珊。\n踏青解红人散，不耐日长闲。\n纤手指，小金环。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3952, '醉梦迷・采桑子', '贺铸', '深坊别馆兰闺小，障掩金泥，灯映玻璃。\n一枕浓香醉梦迷。\n醒来拟作清晨散，草草分携。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3953, '忍泪吟・采桑子', '贺铸', '十年一觉扬州梦，雨散云沈。\n隔水登临。\n扬子湾西夕照深。\n当时玉管朱弦句，忍泪重吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3954, '凌・金人捧露盘', '贺铸', '控沧江。\n排青嶂，燕台凉。\n驻采仗、乐未渠央。\n岩花磴蔓，妒千门、珠翠倚新妆。\n舞闲歌悄，恨风流、不管馀香。\n繁华梦，惊俄顷，佳丽地，指沧茫。\n寄一笑、何与兴亡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3955, '秋风叹・燕瑶池', '贺铸', '琼钩褰幔。\n秋风观。\n漫漫。\n白云聊度河汉。\n长宵半。\n参旗烂烂。\n何时旦。\n命闺人、金徽重按。\n商歌弹。\n依稀广陵清散。\n低眉叹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3956, '断湘弦・万年欢', '贺铸', '淑质柔情，靓妆艳笑，未容桃李争妍。\n红粉墙东，曾记窥宋三年。\n不间云朝雨暮，向西楼、南馆留连。\n何尝信，美景良辰，赏心乐事难全。\n青门解袂，画桥回首，初沈汉佩，永断湘弦。\n漫写浓愁幽恨，封寄鱼笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3957, '子夜歌', '贺铸', '三更月。\n中庭恰照梨花雪。\n梨花雪。\n不胜凄断，杜鹃啼血。\n王孙何许音尘绝。\n柔桑陌上吞声别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3958, '独倚楼・更漏子', '贺铸', '上东门，门外柳。\n赠别每烦纤手。\n一叶落，几番秋。\n江南独倚楼。\n曲阑干，凝伫久。\n薄暮更堪搔首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3959, '翻翠袖・更漏子', '贺铸', '绣罗垂，花蜡换。\n问夜何其将半。\n侵履，促杯盘。\n留欢不作难。\n令随阄，歌应弹。\n舞按霓裳前段。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3960, '付金钗・更漏子', '贺铸', '付金钗，平斗酒。\n未许解携纤手。\n吟警句，写清愁。\n浮骖为少留。\n旧游赊，新梦後。\n月映隔窗疏柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3961, '伴登临・采桑子', '贺铸', '中吴茂苑繁华地。\n冠盖如林。\n桃李成阴。\n若个芳心、真个会琴心。\n高秋霁色清於水。\n月榭风襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3962, '苗而秀・采桑子', '贺铸', '吴都佳丽苗而秀。\n燕样腰身。\n按舞华茵。\n促遍凉州、罗袜未生尘。\n□□□□□□透。\n歌怨眉颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3963, '东吴乐・尉迟杯', '贺铸', '胜游地。\n信东吴绝景饶佳丽。\n平湖底，见层岚，凉月下，闻清吹。\n人如李。\n泛金袂、香润苹风起。\n喜凌波、素袜逢迎，领略当歌深意。\n鄂君被。\n双鸳绮。\n垂杨阴，夷犹画相舣。\n宝瑟弦调，明珠佩委。\n回首碧云千里。\n归鸿後、芳音难寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3964, '台城游・水调歌头', '贺铸', '南国本潇洒。\n六代浸豪奢。\n台城游冶。\n襞笺能赋属宫娃。\n云观登临清夏。\n璧月留连长夜。\n吟醉送年华。\n回首飞鸳瓦。\n却羡井中蛙。\n访乌衣，成白社。\n不容车。\n旧时王谢。\n堂前双燕过谁家。\n楼外河横斗挂。\n淮上潮平霜下。\n墙影落寒沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3965, '潇湘雨・满庭芳', '贺铸', '一阕离歌，满尊红泪，解携十里长亭。\n木兰归棹，犹倚采苹汀。\n鸦噪黄陵庙掩，因想像、鼓瑟湘灵。\n渔村远，烟昏雨淡，灯火两三星。\n愁听。\n墙影外，繁声骤点，□□□□。\n□□□□□，浓睡香屏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3966, '念离群・沁园春', '贺铸', '宫烛分烟，禁池开钥，凤城暮春。\n向落花香里，澄波影外，笙歌迟日，罗绮芳尘。\n载酒追游，联镳归晚，灯火平康寻梦云。\n逢迎处，最多才自负，巧笑相亲。\n离群。\n客浣漳滨。\n但惊见、来鸿归燕频。\n念日边消耗，天涯怅望，楼台清晓，帘暮黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3967, '宛溪柳・六么令', '贺铸', '梦云萧散，帘卷画堂晓。\n残薰尽烛隐映，绮席金壶倒。\n尘送行鞭袅袅。\n醉指长安道。\n波平天渺。\n兰舟欲上，回首离愁满芳草。\n已恨归期不早。\n枉负狂年少。\n无奈风月多情，此去应相笑。\n心记新声缥缈。\n翻是相思调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3968, '伤春曲・满江红', '贺铸', '火禁初开，深深院、尽重帘箔。\n人自起、翠衾寒梦，夜来风恶。\n肠断残红和泪落。\n半随经雨飘池角。\n记采兰、携手曲江游，年时约。\n芳物大，都如昨。\n自怨别，疏行乐。\n被无情双燕，短封难托。\n谁念东阳销瘦骨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3969, '横塘路・青玉案', '贺铸', '凌波不过横塘路。\n但目送、芳尘去。\n锦瑟华年谁与度。\n月桥花院，琐窗朱户。\n只有春知处。\n飞云冉冉蘅皋暮。\n彩笔新题断肠句。\n若问闲情都几许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3970, '人南渡・感皇恩', '贺铸', '兰芷满芳洲，游思横路。\n罗袜尘生步。\n迎顾。\n整鬟颦黛，脉脉两情难语。\n细风吹柳絮。\n人南渡。\n回首旧游，山无重数。\n花底深朱户。\n何处。\n半黄梅子，向晚一帘疏雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3971, '薄幸', '贺铸', '艳真多态。\n更的的，频回眄睐。\n便认得、琴心相许，与写宜男双带。\n记画堂、斜月朦胧，轻颦微笑娇无奈。\n便翡翠屏开，芙蓉帐掩，与把香罗偷解。\n自过了收灯後，都不见、踏青挑菜。\n几回凭双燕，丁宁深意，往来翻恨重帘碍。\n约何时再。\n正春浓酒暖，人闲昼永无聊赖。\n厌厌睡起，犹有花梢日在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3972, '伴云来・天香', '贺铸', '烟络横林，山沈远照，逦迤黄昏钟鼓。\n烛映帘栊，蛩催机杼，共苦清秋风露。\n不眠思妇，齐应和、几声砧杵。\n惊动天涯倦宦，岁华行暮。\n当年酒狂自负。\n谓东君、已春相付。\n流浪征骖北道，客墙南浦。\n幽恨无人晤语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3973, '念良游・满江红', '贺铸', '山缭平湖，寒飙扬、六英粉泊。\n清镜晓、倚岩琪树，挠云朱阁。\n窈窕缯窗褰翠募，尊前浩齿歌梅落。\n信醉乡、绝境待名流，供行乐。\n时易失，今犹昨。\n欢莫再，情何薄。\n扁舟幸不系，会寻佳约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3974, '寒松叹・声声慢', '贺铸', '鹊惊桥断，凤怨箫闲，彩云薄晚苍凉。\n难致祖州灵草，方士神香。\n寒松半涧底，恨女萝、先委冰霜。\n宝琴尘网，□□□□，□□□□。\n依□履綦行处，酸心□，□□□□□□。\n□□帘垂地，簟竟空床。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3975, '凤求凰・声声慢', '贺铸', '园林幕翠，燕寝凝香。\n华池缭绕飞廊。\n坐按吴娃清丽，楚调圆长。\n歌阑横流美眄，乍疑生、绮席辉光。\n文园属意，玉觞交劝，宝色高张。\n南薰难销幽恨，金徽上，殷勤彩凤求凰。\n便许卷收行雨，不恋高唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3976, '国门东・好女儿', '贺铸', '车马匆匆。\n会国门东。\n信人间、自古销魂处，指红尘北道，碧波南浦，黄叶西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3977, '九回肠・好女儿', '贺铸', '削玉销香。\n不喜浓妆。\n倚高楼、望断章台路，但垂杨永巷，落花微雨，芳草斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3978, '月先圆・好女儿', '贺铸', '才色相怜。\n难偶当年。\n屡逢迎、几许缠绵意，记秋千架底，蒲局上，祓禊池边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3979, '绮筵张・好女儿', '贺铸', '绮绣张筵。\n粉黛争妍。\n记六朝、旧数闺房秀，有长圆璧月，永新琼树，随步金莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3980, '舞迎春・迎春乐', '贺铸', '云鲜日嫩东风软。\n雪初融、水清浅。\n粉□舞按迎春遍。\n似飞动、钗头燕。\n深折梅花曾寄远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3981, '城里钟・菩萨蛮', '贺铸', '厌厌别酒商歌送。\n萧萧凉叶秋声动。\n小泊画桥东。\n孤舟月满篷。\n高城遮短梦。\n衾藉馀香拥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3982, '望西飞・清商怨', '贺铸', '十分持酒每□□。\n□□□□□。\n□计留春，春随人去远。\n东流□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3983, '东阳叹・清商怨', '贺铸', '流连狂乐恨景短。\n奈夕阳送晚。\n醉未成欢，醒来愁满眼。\n东阳消瘦带展。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3984, '要销凝・清商怨', '贺铸', '雕梁寻巢旧燕侣。\n似向人欲语。\n试问来时，逢郎郎健否。\n春风深闭绣户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3985, '想车音・兀令', '贺铸', '盘马楼前风日好。\n雪销尘扫。\n楼上宫妆早。\n认帘箔微开，一面嫣妍笑。\n携手别院重廊，窈窕花房小。\n任碧罗窗晓。\n间阔时多书问少。\n镜鸾空老。\n身寄吴云杳。\n想辘车音，几度青门道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3986, '荆溪咏・渔家傲', '贺铸', '南岳去天才尺五。\n荆溪笠泽相吞吐。\n十日一风仍再雨。\n宜禾黍。\n秋成处处宜禾黍。\n坊市万家连岛屿。\n长杨□□□□□。\n□□□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3987, '吹柳絮・瑞鹧鸪', '贺铸', '月痕依约到西厢。\n曾羡花枝拂短墙。\n初未识愁那得泪，每浑疑梦奈馀香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3988, '江如练・蝶恋花', '贺铸', '睡鸭鲈寒熏麝煎。\n寂寂歌梁，无计留归燕。\n十二曲阑闲倚遍。\n一杯长待何人劝。\n不识当年桃叶面。\n吟咏佳词，想像犹曾见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3989, '宴齐云・南歌子', '贺铸', '境跨三千里，楼侵尺五天。\n碧鸳鸯瓦昼生烟。\n未信西山台观、压当年。\n野色分禾黍，秋声入管弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3990, '醉琼枝・定风波', '贺铸', '槛外雨波新涨，门前烟柳浑青。\n寂寞文园淹卧久，推枕援琴涕自零。\n无人著意听。\n绪绪风披芸幌，锓锓月到萱庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3991, '□□□・更漏子', '贺铸', '酒三行，琴再弄。\n宛是和鸣双凤。\n罗斗帐，绣屏风。\n浓香夜夜同。\n去年欢，今夕梦。\n怊怅晓钟初动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3992, '弄珠英・蓦山溪', '贺铸', '楚乡新岁。\n不放残寒退。\n月晓桂娥闲，弄珠英、因风委坠。\n清淮铺练，十二玉峰前，上帘栊，招佳丽。\n置酒成高会。\n江南芳信，目断何人寄。\n应占镜边春，想晨妆、膏浓压翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3993, '梦相亲・玉楼春', '贺铸', '清琴再鼓求凰弄。\n紫陌屡盘骄马。\n远山眉样认心期，流水车音牵目送。\n归来翠被和衣拥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3994, '罗敷歌・采桑子', '贺铸', '高楼帘卷秋风里，目送斜阳。\n衾枕遗香。\n今夜还如昨夜长。\n玉人望月销凝处，应在西厢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3995, '罗敷歌・采桑子', '贺铸', '河阳官罢文园病，触绪萧然。\n犀麈流连。\n喜见清蟾似旧圆。\n人生聚散浮云似，回首明年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3996, '罗敷歌・采桑子', '贺铸', '东南自古繁华地，歌吹扬州。\n十二青楼。\n最数秦娘第一流。\n季鹰久负鲈鱼兴，不住今秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3997, '罗敷歌・采桑子', '贺铸', '自怜楚客悲秋思，难写丝桐。\n目断书鸿。\n平淡江山落照中。\n谁家水调声声怨，黄叶西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3998, '罗敷歌・采桑子', '贺铸', '东亭南馆逢迎地，几醉红裙。\n凄怨临分。\n四叠阳关忍泪闻。\n谁怜今夜篷窗雨，何处渔村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (3999, '小重山', '贺铸', '玉指金徽一再弹。\n新声传访戴，雪溪寒。\n两行墨妙破冰纨。\n牵情处，幽恨寄毫端。\n昵语强羞难。\n相逢真许似，镜中鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4000, '小重山', '贺铸', '帘影新妆一破颜。\n玳筵回雪舞，小云鬟。\n琼枝擢秀望难攀。\n凝情处，千里望蓬山。\n歌断酒阑珊。\n画船箫鼓转，绿杨湾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4001, '小重山', '贺铸', '枕上阊门五报更。\n蜡灯香冷，恨天明。\n青苹风转彩帆轻。\n樯头燕，多谢伴人行。\n临镜想倾城。\n两尖愁黛浅，泪波横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4002, '小重山', '贺铸', '月月相逢只旧圆。\n迢迢三十夜，夜如年。\n伤心不照绮罗筵。\n孤舟里，单枕若为眠。\n茂苑想依然。\n花楼连苑起，压漪涟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4003, '河传', '贺铸', '华堂张燕。\n向尊前妙选，舞裙歌扇。\n彼美个人，的的风流心眼。\n恨寻芳来晚。\n曲街灯火香尘散。\n犹约晨妆，一觇春风面。\n惆怅善和坊里，平桥南畔。\n小青楼、帘不卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4004, '河传', '贺铸', '华堂重厦，向尊前更听，碧云新怨。\n玉指钿徽，总是挑人心眼。\n恨随红蜡短。\n彩旗影动船头转。\n双桨凌波，惟念人留恋。\n江上暮潮，隐隐山横南岸。\n奈离愁、分不断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4005, '侍香金童', '贺铸', '楚梦方回，翠被寒如水。\n尚想见、扬州桃李。\n姿秀韵闲何物比。\n玉管秋风，漫声流美。\n燕堂开，双按秦弦呈素指。\n宝雁参差飞不起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4006, '凤栖梧・蝶恋花', '贺铸', '独立江东人婉娈。\n粉本花真，千里依稀见。\n闲弄彩毫濡玉砚。\n缠绵春思□歌扇。\n爱我竹窗新句练。\n小砑凌笺、偷寄西风燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4007, '更漏子', '贺铸', '芳草斜曛。\n映画桥□□，翠阁临津。\n数阕清歌，两行红粉，厌厌别酒初曛。\n芳意赠我殷勤。\n罗巾双黛痕。\n便兰舟独上，洞府人闲，素手轻分。\n十里绮陌香尘。\n望紫云车远，已掩青门。\n迤逦黄昏，景阳钟动，临风隐隐犹闻。\n明朝水馆渔村。\n凭谁招断魂。\n恨不如今夜，明月多情，应待归云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4008, '玉京秋', '贺铸', '陇首霜晴，泗滨云晚，乍摇落。\n废榭苍苔，破台荒草，西楚霸图冥漠。\n记登临事，九日胜游，千载如昨。\n更想像，晋客□归，谢生能赋继高作。\n飘泊。\n尘埃倦客，风月羁心，潘鬓晓来清镜觉。\n蜡屐纶巾，羽觞象管，且追随、隼行乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4009, '蕙清风', '贺铸', '何许最悲秋，凄风残照。\n临水复登山，莞然西笑。\n车马几番尘，自古长安道。\n问谁是、後来年少。\n飞集两悠悠，江滨海岛。\n乘雁与双凫，强分多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4010, '虞美人', '贺铸', '粉娥齐敛千金笑。\n愁结眉峰小。\n渭城才唱轻尘。\n无奈两行红泪、湿香巾。\n伤心风月南城道。\n几纵朱到。\n明年载酒洛阳春。\n还念淮山楼上、倚阑人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4011, '下水船', '贺铸', '芳草青门路。\n还拂京尘东去。\n回想当年离绪。\n送君南浦。\n愁几许。\n尊酒流连薄暮。\n帘卷津楼风雨。\n凭阑语。\n草草蘅皋赋。\n分首惊鸿不驻。\n灯火虹桥，难寻弄波微步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4012, '点绛唇', '贺铸', '见面无多，坐来百媚生馀态。\n後庭春在。\n折取残红戴。\n小小兰舟，荡桨东风快。\n何愁载。\n缠绵难解。\n不似罗裙带。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4013, '渔家傲', '贺铸', '莫厌香醪斟绣履。\n吐茵也是风流事。\n今夜夜寒愁不睡。\n披衣起。\n挑灯开卷花生纸。\n倩问尊前桃与李。\n重来若个犹相记。\n前度刘郎应老矣。\n行乐地。\n兔葵燕麦春风里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4014, '感皇恩', '贺铸', '歌笑见馀妍，情生眄睐。\n拥髻扬蛾黛。\n多态。\n小花深院，漏促离襟将解。\n恼人红蜡泪。\n啼相对。\n芳草唤愁，愁来难奈。\n兰叶犹堪向谁采。\n小楼妆晚，应念斑骓何在。\n碧云长有待。\n斜阳外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4015, '菩萨蛮', '贺铸', '彩舟载得离愁动。\n无端更借樵风送。\n波渺夕阳迟。\n销魂不自持。\n良宵谁与共。\n赖有窗间梦。\n可奈梦回时。\n一番新别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4016, '菩萨蛮', '贺铸', '章台游冶金龟婿。\n归来犹带醺醺醉。\n花漏怯春宵。\n云屏无限娇。\n绛纱灯影背。\n玉枕钗声碎。\n不待宿酲销。\n马嘶催早朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4017, '菩萨蛮', '贺铸', '曲门南与鸣珂接。\n小园绿径飞胡蝶。\n下马访婵娟。\n笑迎妆阁前。\n鹧鸪声几叠。\n艳艳金蕉叶。\n未许被香鞯。\n月生楼外天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4018, '菩萨蛮', '贺铸', '绿窗残梦闻。\n曲屏映枕春山叠。\n梳□发如蝉。\n镜生波上莲。\n绛裙金缕褶。\n学舞腰肢怯。\n帘下小凭肩。\n与人双翠钿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4019, '菩萨蛮', '贺铸', '绿杨眠後拖烟穗。\n日长扫尽青苔地。\n香断入帘风。\n炉心檀烬红。\n兰溪修祓禊。\n上巳明朝是。\n不许放春慵。\n景阳临晓钟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4020, '菩萨蛮', '贺铸', '粉香映叶花羞日。\n窗间宛转蜂寻蜜。\n欢罢卷帘时。\n玉纤匀面脂。\n舞裙金斗熨。\n绛鸳鸯密。\n翠带一双垂。\n索人题艳诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4021, '菩萨蛮', '贺铸', '子规啼梦罗窗晓。\n开奁拂镜严妆早。\n彩碧画丁香。\n背垂裙带长。\n钿筝寻旧曲。\n愁结眉心绿。\n犹恨夜来时。\n酒狂归太迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4022, '菩萨蛮', '贺铸', '虚堂向壁青灯灭。\n觉来惊见横窗月。\n起看月平西。\n城头乌夜啼。\n兰衾羞更入。\n枕偷声泣。\n肠断数残更。\n望明天未明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4023, '菩萨蛮', '贺铸', '芭蕉衬雨秋声动。\n罗窗恼破鸳鸯梦。\n愁倚□帘栊。\n灯花落地红。\n枕横衾浪拥。\n好夜无人共。\n莫道粉墙东。\n蓬山千万重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4024, '菩萨蛮', '贺铸', '朱甍碧树莺声晓。\n残醺残梦犹相恼。\n薄雨隔轻帘。\n寒侵白衫。\n锦屏人起早。\n惟见馀妆好。\n眉样学新蟾。\n春愁入翠尖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4025, '菩萨蛮', '贺铸', '炉烟微度流苏帐。\n孤衾冷叠芙蓉浪。\n蟋蟀不离床。\n伴人愁夜长。\n玉人飞阁上。\n见月还相望。\n相望莫相忘。\n应无未断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4026, '于飞乐', '贺铸', '日薄云融。\n满城罗绮芳丛。\n一枝粉淡香浓。\n几销魂，偏健羡、紫蝶黄蜂。\n繁华梦断，酒醒来、扫地春空。\n武陵原、回头何处，情随流水无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4027, '浣溪沙', '贺铸', '双鹤横桥阿那边。\n静坊深院闭婵娟。\n五度花开三处见，两依然。\n水眄难禁频领□，歌云犹许小流连。\n破得尊前何限恨，不论钱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4028, '品令', '贺铸', '怀彼美。\n愁与泪。\n分占眉丛眼尾。\n求好梦、闲拥鸳鸯绮。\n恨啼鸟、唤人起。\n目断清淮楼上，心寄长洲坊里。\n迢迢地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4029, '海月谣', '贺铸', '楼平叠。\n瞰瀛海、波三面。\n碧云扫尽，桂轮玉，鲸波张练。\n化出无边宝界，是名壮观。\n追游汗漫。\n愿少借、长风便。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4030, '风流子', '贺铸', '何处最难忘。\n方豪健，放乐五云乡。\n彩笔赋诗，禁池芳草，香鞯调马，辇路垂杨。\n绮筵上，扇偎歌黛浅，汗舞罗香。\n兰烛伴归，绣轮同载，闭花别馆，隔水深坊。\n零落少年场。\n琴心漫流怨，带眼偷长。\n无奈占床燕月，侵鬓吴霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4031, '鹧鸪天', '贺铸', '轰醉王孙玳瑁筵。\n渴虹垂地吸长川。\n侧商调里清歌送，破尽穷愁直几钱。\n孤棹舣，小江边。\n爱而不见酒中仙。\n伤心两岸官杨柳，已带斜阳又带蝉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4032, '忆仙姿・如梦令', '贺铸', '白春衫新制。\n准拟采兰修禊。\n遮日走京尘，何啻分阴如岁。\n留滞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4033, '忆仙姿・如梦令', '贺铸', '日日春风楼上。\n不见石城双桨。\n鸳枕梦回时，烛泪屏山相向。\n流荡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4034, '忆仙姿・如梦令', '贺铸', '相见时难别易。\n何限玉琴心意。\n眉黛只供愁，羞见双鸳鸯字。\n憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4035, '忆仙姿・如梦令', '贺铸', '罗绮丛中初见。\n理鬓横波流转。\n半醉不胜情，帘影犹招歌扇。\n留恋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4036, '忆仙姿・如梦令', '贺铸', '雨後一分春减。\n深院落红如糁。\n柳外出秋千，度日彩旗风。\n销黯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4037, '忆仙姿・如梦令', '贺铸', '柳下玉骢双。\n蝉鬓宝钿浮动。\n半醉倚迷楼，聊送斜阳三弄。\n豪纵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4038, '忆仙姿・如梦令', '贺铸', '何处偷谐心赏。\n促坐绮罗筵上。\n不记下楼时，醉□月侵书幌。\n怀想。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4039, '忆仙姿・如梦令', '贺铸', '江上潮回风细。\n红袖倚楼凝睇。\n天际认归舟，但见平林如荠。\n迢递。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4040, '忆仙姿・如梦令', '贺铸', '梦想山阴游冶。\n深径碧桃花谢。\n曲水稳流觞，暖絮芳兰堪藉。\n萧洒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4041, '凤栖梧・蝶恋花', '贺铸', '挑菜踏青都过却。\n杨柳风轻，摆动秋千索。\n啼鸟自惊花自落。\n有人同在真珠箔。\n淡净衣裳妆□薄。\n闲凭银筝，睡鬓慵梳掠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4042, '相思引', '贺铸', '终日怀归翻送客。\n春风祖席。\n南成陌。\n便莫惜。\n离觞频卷白。\n动管色。\n催行色。\n动管色。\n催行色。\n何处投鞍风雨夕。\n临水驿。\n空山驿。\n临水驿。\n空山驿。\n纵明月相思千里隔。\n梦咫尺。\n勤书尺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4043, '芳草渡・系裙腰', '贺铸', '留征辔，送离杯。\n羞泪下，拈青梅。\n低声问道几时回。\n秦筝雁促，此夜为谁排。\n君去也，远蓬莱。\n千里地，信音乖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4044, '雨中花・夜行船', '贺铸', '回首扬州，猖狂十载，依然一梦归来。\n但觉安仁愁鬓，几点尘埃。\n醉墨碧纱犹锁，春衫白新裁。\n认鸣珂曲里，旧日朱扉，闲闭青苔。\n人非物是，半晌鸾肠易断，宝勒空回。\n徒怅望、碧云销散，明月徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4045, '花心动', '贺铸', '西郭园林，远尘烦，门临绿杨堤路。\n画□簟长，水馆帘空，竟日素襟销暑。\n小湾红芰清香里，深隐映、风标鸳鹭。\n指□□，相将故故，背人飞去。\n翻念多情自苦。\n当置酒徵歌，梦云难驻。\n醉眼渐迷，花拂墙低，误认宋邻偷顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4046, '浪淘沙', '贺铸', '把酒欲歌骊。\n浓醉何辞。\n玉京烟柳欲黄时。\n明日景阳门外路，相背春归。\n敛泪复牵衣。\n私语迟迟。\n可怜谁会两心期。\n惟有画帘斜月见，应共人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4047, '浪淘沙', '贺铸', '一十二都门。\n梦想能频。\n无言桃李几经春。\n艳粉鲜香开自落，还为何人。\n白别时新。\n苒苒征尘。\n镜中消瘦老於真。\n赖有天涯风月在，依旧相亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4048, '浪淘沙', '贺铸', '潮涨湛芳桥。\n难渡兰桡。\n卷帘红袖莫相招。\n十二阑干今夜月，谁伴吹箫。\n烟草接亭皋。\n归思迢迢。\n兰成老去转无。\n偏恨秋风添鬓雪，不共魂销。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4049, '浪淘沙', '贺铸', '雨过碧云秋。\n烟草汀洲。\n远山相对一眉愁。\n可惜芳年桥畔柳，不系兰舟。\n为问木兰舟。\n何处淹留。\n相思今夜忍登楼。\n楼下谁家歌水调，明月扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4050, '夜游宫', '贺铸', '江面波纹皱。\n江南岸、草和烟绿。\n初过寒食一百六。\n采苹游，□香裙，鸣佩玉。\n心事偷相属。\n赋春恨、彩笺双幅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4051, '忆仙姿・如梦令', '贺铸', '莲叶初生南浦。\n两岸绿杨飞絮。\n向晚鲤鱼风，断送彩帆何处。\n凝伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4052, '忆仙姿・如梦令', '贺铸', '彩舫解维官柳。\n楼上谁家红袖。\n团扇弄微风，如为行人招手。\n回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4053, '菱花怨', '贺铸', '叠鼓嘲喧，彩旗挥霍，苹汀薄晚，兰舟催解。\n别浦潮平，小山云断，十幅饱帆风快。\n回想牵衣，愁掩啼妆，一襟香在。\n纨扇惊秋，菱花怨晚，谁共蛾黛。\n何处玉尊空，对松陵正美，鲈鱼菜。\n露洗凉蟾，潦吞平野，三万顷非尘界。\n览胜情无奈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4054, '望扬州・长相思慢', '贺铸', '铁瓮城高，蒜山渡阔，干云十二层楼。\n开尊待月，卷箔披风，依然灯火扬州。\n绣陌南头。\n记歌名宛转，乡号温柔。\n曲槛俯清流。\n想花阴、谁系兰舟。\n念凄绝秦弦，感深荆赋，相望几许凝愁。\n殷勤裁尺素，奈双鱼、难渡瓜洲。\n晓鉴堪羞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4055, '定情曲', '贺铸', '沈水浓熏，眉粉淡妆，露华鲜映春晓。\n浅颦轻笑。\n真物外，一种闲花风调。\n可待合欢翠被，不见忘忧芳草。\n拥膝浑忘羞，回身就郎抱。\n两点灵犀心颠倒。\n念乐事稀逢，归期须早。\n五云闻道。\n星桥畔、油壁车迎苏小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4056, '拥鼻吟・吴音子', '贺铸', '别酒初销，怃然弭棹蒹葭浦。\n回首不见高城，青楼更何许。\n大轲峨，越商巴贾。\n万恨龙锺，篷下对语。\n指征路。\n山缺处，孤烟起，历历闻津鼓。\n江豚吹浪，晚来风转夜深雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4057, '思越人・朝天子', '贺铸', '京口瓜洲记梦间。\n朱扉犹想映花关。\n东风太是无情思，不许扁舟兴尽还。\n春水漫，夕阳闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4058, '清平乐', '贺铸', '吴波不动。\n四际晴山拥。\n载酒一尊谁与共。\n回首江湖旧梦。\n长艚珠箔青篷。\n橹声鸦轧征鸿。\n泪□镂檀香枕，醉眠摇□春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4059, '清平乐', '贺铸', '宋邻东畔。\n明月关深院。\n玉指金徽调旧怨。\n楚客归心欲断。\n城隅芳草初春。\n佳期重约临分。\n丽句漫题双带，也愁系住行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4060, '清平乐', '贺铸', '厌厌别酒。\n更执纤纤手。\n指似归期庭下柳。\n一叶西风前後。\n无端不系孤舟。\n载将多少离愁。\n又是十分明月，照人两处登楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4061, '木兰花・玉楼春', '贺铸', '嫣然何啻千金价。\n意远态闲难入画。\n更无方便只尊前，说尽牵情多少话。\n别来乐事经春罢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4062, '木兰花・玉楼春', '贺铸', '朝来著眼沙头认。\n五两竿摇风色顺。\n佳期学取弄潮儿，人纵无情潮有信。\n纷纷花雨红成阵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4063, '减字木兰花', '贺铸', '春容秀润。\n二十四番花有信。\n鸾镜佳人。\n得得浓妆样样新。\n情无远近。\n水阔山长分不尽。\n一断音尘。\n泪眼花前只见春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4064, '减字木兰花', '贺铸', '闲情减旧。\n无奈伤春能作瘦。\n桂楫兰舟。\n几送人归我滞留。\n西门官柳。\n满把青青临别手。\n谁共登楼。\n分取烟波一段愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4065, '减字木兰花', '贺铸', '南园清夜。\n临水朱阑垂柳下。\n从坐莲花。\n潋滟觥船泛露华。\n酒阑歌罢。\n双□前愁东去也。\n回想人家。\n芳草平桥一径斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4066, '减字木兰花', '贺铸', '多情多病。\n万斛闲愁量有剩。\n一顾倾城。\n惟觉尊前笑不成。\n探香幽径。\n好住东风谁主领。\n多谢流莺。\n欲别频啼四五声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4067, '摊破木兰花・木兰花', '贺铸', '南浦东风落暮潮。\n祓禊人归，相并兰桡。\n回身昵语不胜娇。\n犹碍华灯，扇影频摇。\n重泛青翰顿寂寥。\n魂断高城手漫招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4068, '摊破木兰花・木兰花', '贺铸', '芳草裙腰一尺围。\n粉郎香润，清洒蔷薇。\n为嫌风日下楼稀。\n杨柳青阴，深闭朱扉。\n枉是尊前调玉徽。\n彩鸾何事逐鸡飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4069, '南乡子', '贺铸', '秋半雨凉天。\n望後清蟾未破圆。\n二十四桥游冶处，留连。\n携手娇饶步步莲。\n眉宇有馀妍。\n初破瓜时正妙年。\n玉局弹棋无限意，缠绵。\n肠断吴蚕两处眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4070, '南乡子', '贺铸', '柳岸舣兰舟。\n更结东山谢氏游。\n红泪清歌催落景，回头。\n□出尊前一段愁。\n东水漫西流。\n谁道行云肯驻留。\n无限鲜飙吹芷若，汀洲。\n生羡鸳鸯得自由。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4071, '临江仙', '贺铸', '暂假临淮东道主，每逃歌舞华筵。\n经年未办买山钱。\n筋骸难强，久坐沐猴禅。\n行拥一舟称浪士，五湖春水如天。\n越人相顾足嫣然。\n何须绣被，来伴拥蓑眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4072, '罗敷歌・采桑子', '贺铸', '东山未办终焉计，聊尔西来。\n花苑平台。\n倦客登临第几回。\n连延复道通驰道，十二门开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4073, '点绛唇', '贺铸', '一幅霜绡，麝煤熏腻纹丝缕。\n掩妆无语。\n的是销凝处。\n薄暮兰桡，漾下苹花渚。\n风留住。\n绿杨归路。\n燕子西飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4074, '南歌子', '贺铸', '绣幕深朱户，熏炉小象床。\n扶肩醉被冒明。\n绣履可怜分破、两鸳鸯。\n梦枕初回雨，啼钿半□妆。\n一钩新月渡横塘。\n谁认凌波微步、袜尘香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4075, '南歌子', '贺铸', '心蹙黄金缕，梢垂白玉团。\n孤芳不怕雪霜寒。\n先向百花头上、探春□。\n傍水添新韵，横墙露粉颜。\n夜来和月起凭阑。\n认得暗香微度、有无间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4076, '小重山', '贺铸', '一叶西风生嫩凉。\n彩舟旗影动，背斜阳。\n溪流几曲似回肠。\n高城远，今夜为谁长。\n正节号清狂。\n苎萝标韵美，倚新妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4077, '清平乐', '贺铸', '林皋叶脱。\n楼下清江阔。\n船里琵琶金捍拨。\n弹断么弦再抹。\n夜潮州渚生寒。\n城头星斗阑干。\n忍话旧游新梦，三千里外长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4078, '清平乐', '贺铸', '沈侯销瘦。\n八咏新题就。\n惆怅酒醒兼梦後。\n带眼如何复旧。\n几时一叶兰舟。\n画桡鸦轧东流。\n新市小桥西畔，有人长倚妆楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4079, '木兰花・玉楼春', '贺铸', '罗巾粉汗和香。\n纤指留痕红一捻。\n离亭再卜和欢期，寻见石榴双翠叶。\n危楼欲上危肠怯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4080, '玉连环・一落索', '贺铸', '别酒更添红粉泪。\n促成愁醉。\n相逢浅笑合微吟，撩惹到、缠绵地。\n花下解携重附耳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4081, '惜奴娇', '贺铸', '玉立佳人，韵不减、吴苏小。\n赋深情、华年韶妙。\n叠鼓新歌，最能作、江南调。\n缥缈。\n似阳台、娇云弄晓。\n有客临风，梦後拟、池塘草。\n竟装怀、□愁多少。\n绿绮芳尊，映花月、东山道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4082, '蓦山溪', '贺铸', '画桥流水，宛是南州路。\n转柁绿杨湾，恍然间、青楼旧处。\n回肠断尽，犹剩尔多愁，记新声，怀昵语。\n依约对眉宇。\n袜罗香在，祗欠莲随步。\n无物比朝云，恨难续、高唐後赋。\n迢遥此夜，泪枕不成眠，月侵窗，灯映户。\n应见可怜许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4083, '西江月', '贺铸', '携手看花深径，扶肩待月斜廊。\n临分少伫已伥伥。\n此段不堪回想。\n欲寄书如天远，难销夜似年长。\n小窗风雨碎人肠。\n更在孤舟枕上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4084, '摊破木兰花・木兰花', '贺铸', '桂叶眉丛恨自成。\n锦瑟弦调，双凤和鸣。\n钗梁玉胜挂兰缨。\n帘影沈沈，月堕参横。\n屏护文茵翠织成。\n摘佩牵裾，燕样腰轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4085, '点绛唇', '贺铸', '十二层楼，梦回缥缈非烟里。\n此情何寄。\n赖尔荆江水。\n莫谓东君，触处逢桃李。\n留深意。\n温柔乡里。\n自有终焉计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4086, '诉衷情', '贺铸', '不堪回首卧云乡。\n羁宦负清狂。\n年来镜湖风月，鱼鸟两相忘。\n秦塞险，楚山苍。\n更斜阳。\n画桥流水，曾见扁舟，几度刘郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4087, '诉衷情', '贺铸', '半销檀粉睡痕新。\n背镜照樱唇。\n临风再歌团扇，深意属何人。\n轻调笑，浅凝颦。\n认情亲。\n最难堪酒，似不胜情，依样伤春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4088, '怨三三', '贺铸', '玉津春水如蓝。\n宫柳毵毵。\n桥上东风侧帽檐。\n记佳节、约是重三。\n飞楼十二珠帘。\n恨不贮、当年彩蟾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4089, '醉春风', '贺铸', '楼外屏山秀。\n凭阑新梦後。\n归云何许误心期，候候候。\n到陇梅花，渡江桃叶，断魂招手。\n楚制汗衫旧。\n啼妆曾枕袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4090, '忆秦娥', '贺铸', '晓朦胧。\n前溪百鸟啼匆匆。\n啼匆匆。\n凌波人去，拜月楼空。\n去年今日东门东。\n鲜妆辉映桃花红。\n桃花红。\n吹开吹落，一任东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4091, '忆秦娥', '贺铸', '风惊幕。\n灯前细雨檐花落。\n檐花落。\n玉台清镜，泪淹妆薄。\n良时不再须行乐。\n王孙莫负东城约。\n东城约。\n一分春色，为君留著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4092, '忆秦娥', '贺铸', '著春衫。\n玉鞭鞭马南城南。\n南城南。\n柔条芳草，留驻金衔。\n粉娥采叶供新蚕。\n蚕饥略许携纤纤。\n携纤纤。\n湔裙淇上，更待初三。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4093, '河满子', '贺铸', '每恨相逢薄处，可怜欲去迟回。\n犹记新声团扇□，殷勤再引馀杯。\n为问依依杨柳，秋风好住章台。\n疏雨忽随云断，斜阳却送潮回。\n桃叶青山长在眼，几时双楫迎来。\n如待碧阑红药，一年两度花开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4094, '御街行', '贺铸', '松门石路秋风扫。\n似不许、飞尘到。\n双携纤手别烟萝，红粉清泉相照。\n几声歌管，正须陶写，翻作伤心调。\n岩阴暝色归云悄。\n恨易失、千金笑。\n更逢何物可忘忧，为谢江南芳草。\n断桥孤驿，冷云黄叶，相见长安道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4095, '连理枝', '贺铸', '绣幌闲眠晓。\n处处闻啼鸟。\n枕上无情，斜风横雨，落花多少。\n想灞桥、春色老於人，恁江南梦杳。\n往事今何道。\n聊咏池塘草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4096, '金凤钩', '贺铸', '江南又叹流寓。\n指芳物、伴人迟暮。\n搅晴风絮。\n弄寒烟雨。\n春去更无寻处。\n石城楼观青霞举。\n想艇子、寄谁容与。\n断云荆渚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4097, '芳洲泊・踏莎行', '贺铸', '露叶栖萤，风枝袅鹊。\n水堂离燕褰珠箔。\n一声横玉吹流云，厌厌凉月西南落。\n江际吴边，山侵楚角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4098, '水调歌头', '贺铸', '彼美吴姝唱，繁会阖闾邦。\n千坊万井，斜桥曲水小轩窗。\n缥缈关山台观。\n罗绮云烟相半。\n金石压撞。\n痴信东归虏，黑自死心降。\n范夫子，高标韵，秀眉庞。\n功成长往，有人同载世无双。\n物外聊从吾好。\n赖尔工颦妍笑。\n伴醉玉连缸。\n尽任扁舟路，风雨卷秋江。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4099, '摊破浣溪沙・山花子', '贺铸', '曲磴斜阑出翠微。\n西州回首思依依。\n风物宛然长在眼，只人非。\n绿树隔巢黄鸟并，沧洲带雨白鸥飞。\n多谢子规啼劝我，不如归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4100, '江南曲・踏莎行', '贺铸', '蝉韵清弦，溪横翠。\n翩翩彩帆开幅。\n黄帘绛幕掩香风，当筵灿灿人如玉。\n浅黛凝愁，明波转瞩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4101, '江南曲・踏莎行', '贺铸', '鸦轧齐桡，□冬叠鼓。\n浮骖晚下金牛渚。\n莫愁应自有愁时，篷窗今夜潇潇雨。\n杜若芳洲。\n芙蓉别浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4102, '江南曲・踏莎行', '贺铸', '小苑浴兰，微波寄叶。\n石城回首山重沓。\n绮窗烟雨梦佳期，飞霞艇子雕檀楫。\n楼回披襟，廊长响。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4103, '楼下柳・天香', '贺铸', '满马京□，装怀春思，翩然笑度江南。\n白鹭芳洲，青蟾雕舰，胜游三月初三。\n舞裙溅水，浴兰佩、绿染纤纤。\n归路要同步障，迎风会卷珠帘。\n离觞未容半酣。\n恨乌樯、已张轻帆。\n秋鬓重来淮上，几换新蟾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4104, '吴门柳・渔家傲', '贺铸', '窈窕盘门西转路。\n残阳映带青山暮。\n最是长杨攀折苦。\n堪怜许。\n清霜翦断和烟缕。\n春水归期端不负。\n依依照影临南浦。\n留取木兰舟少住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4105, '吴门柳・渔家傲', '贺铸', '啸度万松千步岭。\n钱湖门外非尘境。\n见底碧漪如眼净。\n岚光映。\n镜屏百曲新磨莹。\n好月为人重破瞑。\n云头艳艳开金饼。\n传语桂娥应奈静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4106, '雁後归・临江仙', '贺铸', '巧翦合欢罗胜子，钗头春意翩翩。\n艳歌浅拜笑嫣然。\n愿郎宜此酒，行乐驻华年。\n未是文园多病客，幽襟凄断堪怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4107, '雁後归・临江仙', '贺铸', '鸦背夕阳山映断，绿杨风扫津亭。\n月生河影带疏星。\n青松巢白鸟，深竹逗流萤。\n隔水彩舟然绛蜡，碧窗想见娉婷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4108, '雁後归・临江仙', '贺铸', '翡翠楼高帘幕薄，温家小玉妆台。\n画眉难称怯人催。\n羞从面色起，娇逐语声来。\n门外木兰花艇子，垂杨风扫纤埃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4109, '鸳鸯梦・临江仙', '贺铸', '午醉厌厌醒自晚，鸳鸯春梦初惊。\n闲花深院听啼莺。\n斜阳如有意，偏傍小窗明。\n莫倚雕阑怀往事，吴山楚水纵横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4110, '念彩云・夜游宫', '贺铸', '流水苍山带郭。\n寻尘迹、宛然如昨。\n犹记黄花携手约。\n误重来，小庭花，空自落。\n不怨兰情薄。\n可怜许、彩云漂泊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4111, '烛影摇红', '贺铸', '波影翻帘，泪痕凝蜡青山馆。\n故人千里念佳期，襟佩如相款。\n惆怅更长梦短。\n但衾枕、馀芬剩暖。\n半窗斜月，照人肠断，啼鸟不管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4112, '小重山', '贺铸', '花院深疑无路通。\n碧纱窗影下，玉芙蓉。\n当时偏恨五更钟。\n分携处，斜月小帘栊。\n楚梦冷沈踪。\n一双金缕枕，半床空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4113, '绿头鸭・多丽', '贺铸', '玉人家，画楼珠箔临津。\n托微风、彩箫流怨，断肠马上曾闻。\n燕堂开、艳妆丛里，调琴思、认歌颦。\n麝蜡烟浓，玉莲漏短，更衣不待酒初醺。\n绣屏掩、枕鸳相就，香气渐暾暾。\n回廊影，疏钟淡月，几许销魂。\n翠钗分、银笺封泪，舞鞋从此生尘。\n住兰舟、载将离恨，转南浦、背西曛。\n记取明年，蔷薇谢後，佳期应未误行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4114, '减字浣溪沙・浣溪沙', '贺铸', '秋水斜阳演漾金。\n远山隐隐隔平林。\n几家村落几声砧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4115, '减字浣溪沙・浣溪沙', '贺铸', '三扇屏山匝象床。\n背灯偷解素罗裳。\n粉肌和汗自生香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4116, '减字浣溪沙・浣溪沙', '贺铸', '鼓动城头啼暮鸦。\n过云时送雨些些。\n嫩凉如水透窗纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4117, '减字浣溪沙・浣溪沙', '贺铸', '烟柳春梢蘸晕黄。\n井阑风绰小桃香。\n觉时帘幕又斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4118, '减字浣溪沙・浣溪沙', '贺铸', '梦想西池辇路边。\n玉鞍娇马小辎。\n春风十里斗婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4119, '减字浣溪沙・浣溪沙', '贺铸', '莲烛啼痕怨漏长。\n吟蛩随月到回廊。\n一屏烟景画潇湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4120, '减字浣溪沙・浣溪沙', '贺铸', '闲把琵琶旧谱寻。\n四弦声怨却沈吟。\n燕飞人静画堂深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4121, '减字浣溪沙・浣溪沙', '贺铸', '鹦鹉无言理翠襟。\n杏花零落昼阴阴。\n画桥流水半篙深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4122, '减字浣溪沙・浣溪沙', '贺铸', '鹦鹉惊人促下帘。\n碧纱如雾隔香奁。\n雪儿窥镜晚蛾纤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4123, '减字浣溪沙・浣溪沙', '贺铸', '宫锦袍熏水麝香。\n越纱裙染郁金黄。\n薄罗依约见明妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4124, '减字浣溪沙・浣溪沙', '贺铸', '青翰舟中祓禊筵。\n粉娥窥影两神仙。\n酒阑飞去作非烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4125, '水龙吟', '晁补之', '水晶宫绕千家，卞山倒影双溪里。\n白苹洲渚，诗成春晚，当年此地。\n行遍瑶台，弄英携手，月婵娟际。\n算多情小杜，风流未睹，空肠断、枝间子。\n一似君恩赐与，贺家湖、千峰凝翠。\n黄粱未熟，红旌已远，南柯旧事。\n常恐重来，夜阑相对，也疑非是。\n向松陵回首，平芜尽处，在青山外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4126, '八声甘州', '晁补之', '谓东坡、未老赋归来，天未遣公归。\n向西湖两处秋波一种，飞蔼澄辉。\n又拥竹西歌吹，僧老木兰非。\n一笑千秋事，浮世危机。\n应倚平山栏槛，是醉翁饮处，江雨霏霏。\n送孤鸿相接，今古眼中稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4127, '八声甘州', '晁补之', '谓东风、定是海冬来，海上最春先。\n乍微阳破腊，梅心已省，柳意都远。\n雪後南山耸翠，平野欲生烟。\n记得相逢日，如上林边。\n莫叹春光易老，算今年春老，还有明年。\n叹人生难得，常好是朱颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4128, '满庭芳', '晁补之', '鸥起苹中，鱼惊荷底，画船天上来时。\n翠湾红渚，宛似武陵迷。\n更晚青山更好，孤云带、远雨丝垂。\n清歌里，金尊未掩，谁使动分携。\n竹林、高晋软，阿咸潇散，犹愧风期。\n便弃官终隐，钓叟苔矶。\n纵是鸣鸿云外，应念我、垂翼低飞。\n新词好，他年认取，天际片帆归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4129, '凤凰台上忆吹箫', '晁补之', '千里相思，况无百里，何妨暮往朝还。\n又正是、梅初淡伫，禽未绵蛮。\n陌上相逢缓辔，风细细、云日斑斑。\n新晴好，得意未妨，行尽青山。\n应携後房小妓，来为我，盈盈对舞花间。\n便拼了、松醪翠满，蜜炬红残。\n谁信轻鞍射虎，清世里、曾有人闲。\n都休说，帘外夜久春寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4130, '凤凰台上忆吹箫', '晁补之', '才短宫慵，命奇人弃，年年故里来远。\n记往岁、莲塘送我，远赴荆蛮。\n莫道风情似旧，青镜里、绿鬓新斑。\n佳人怪，把盏为我，微敛眉山。\n从来嗣宗高韵，独见赏，青云忧绝尘间。\n谩回首、平生醉语，一梦惊残。\n莫笑移花种柳，应备办、投老同闲。\n纵枯槁，松桧奈得霜寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4131, '摸鱼儿', '晁补之', '买陂塘、旋栽杨柳，依稀淮岸江浦。\n东皋嘉雨新痕涨，沙觜鸥来鹭聚。\n堪爱处。\n最好是、一川夜月光流渚。\n无人独舞。\n任翠幄张天，柔茵藉地，酒尽未能去。\n青绫被，莫忆金闺故步。\n儒冠曾把身误。\n弓刀千骑成何事，荒了邵平瓜圃。\n君试。\n满青镜、星星鬓影今如许。\n功名浪语。\n便似得班超，封侯万里，归计恐迟春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4132, '永遇乐', '晁补之', '松菊堂深，芰荷池小，长夏清暑。\n燕引雏还，鸠呼妇往，人静郊原趣。\n麦天已过，薄衣轻扇，试起绕园徐步。\n听衡宇、欣欣童稚，共说夜来初雨。\n苍菅径里，紫葳枝上，数点幽花垂露。\n东里催锄，西邻助晌，相戒清晨去。\n斜川归兴，け然满目，回首帝乡何处。\n只愁恐、轻鞭犯夜，灞陵旧路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4133, '过涧歇', '晁补之', '归去。\n奈故人、尚作青眼相期，未许明时归去。\n放怀处。\n买得东皋数亩，静爱园林趣。\n任过客、剥啄相呼昼扃户。\n堪笑儿童事业，华颠向谁语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4134, '黄莺儿', '晁补之', '南园佳枝偏宜暑。\n两两三三修篁，新篁新出初齐，猗猗过檐侵户。\n听乱芰荷风，细洒梧桐雨。\n午馀帘影参差，远林蝉声，幽梦残处。\n凝伫。\n既往尽成空，暂遇何曾住。\n算人间事、岂足追思，依依梦中情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4135, '消息・永遇乐', '晁补之', '红日葵开，映墙遮牖，小斋端午。\n杯展荷金，簪抽笋玉，幽事还数。\n绿窗纤手，朱奁轻缕。\n争斗彩丝艾虎。\n想沈江怨魄归来，空惆怅、对菰黍。\n朱颜老去，清风好在，未减佳辰欢聚。\n趣蜡酒深斟，菖细糁，围坐从儿女。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4136, '梁州令叠韵・梁州令', '晁补之', '田野闲来惯。\n睡起初惊晓燕。\n樵青走挂小帘钩，南园昨夜，细雨红芳遍。\n平芜一带烟光浅。\n过尽南归雁。\n俱远。\n凭阑送目空肠断。\n好景难常占。\n过眼韶华如箭。\n莫教送韶华，多情杨柳，为把长条绊。\n清尊满酌谁为伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4137, '酒泉子', '晁补之', '萱草戎葵，松菊堂深犹畏暑，晚云催雨霭帘栊。\n满楼风。\n池莲翻倒小莲红。\n看扫鉴、天清似水，一轮明月却当空。\n画栏中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4138, '归田乐', '晁补之', '春又去，似别佳人幽恨积。\n闲庭院，翠阴满，添昼寂。\n一枝梅最好，至今忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4139, '诉衷情', '晁补之', '东城南陌路歧斜。\n芳草遍藏遮。\n黄鹂自是来晚，莫恨海棠花。\n惊雪絮，满天涯。\n送春赊。\n问春莫是，忆著东君，自去还家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4140, '金凤钩', '晁补之', '春辞我向何处。\n怪草草、夜来风雨。\n一簪华发，少欢饶恨，无计春且住。\n春回常恨寻无路。\n试向我、小园徐步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4141, '金凤钩', '晁补之', '雪消闲步花畔。\n试屈指、早春将半。\n樱桃枝上最先到，却恨小梅芳浅。\n忽惊拂水双来燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4142, '生查子', '晁补之', '永日向人妍，百合忘忧草。\n午枕梦初回，远柳蝉声杳。\n藓井出冰泉，洗瀹烦襟了。\n却挂小帘钩，一缕炉烟袅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4143, '行香子', '晁补之', '前岁栽桃，今岁成蹊。\n更黄鹂、久住相知。\n微行清露，细履斜晖。\n对林中侣，闲中我，醉中谁。\n何妨到老，常闲常醉，任功名、生事俱非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4144, '诉衷情', '晁补之', '小园过午，便觉凉生翠柏。\n戎葵闲出墙红，萱草静依径绿。\n还是去年，浮瓜沈李，追凉故绕池边竹。\n小筵促。\n忽忆杨梅正熟。\n下山南畔，画舸笙歌逐。\n愁凝目。\n使君彩笔，佳人锦字，断弦怎续。\n尽日栏干曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4145, '木兰花・玉楼春', '晁补之', '小楼新创堪临远。\n一带寒山都入眼。\n人间应未觉春归，楼上已先变柳眼。\n风威自与微阳战。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4146, '行香子', '晁补之', '归鸟翩翩，楼上黄昏。\n黯天气、残照馀痕。\n曲阑干里，有个愁人。\n向不言中，千载事，一年春。\n春来似客，春归如云。\n付楼前、行路双轮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4147, '阮郎归', '晁补之', '小楼独上暮锺时。\n红霞楼外飞。\n烟中远鸟一双归。\n城门灯火微。\n横短吹，傍危梯。\n冰轮涌海迟。\n天涯幽恨有谁知。\n凉风时动衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4148, '引驾行', '晁补之', '梅梢琼绽，东君次第开桃李。\n痛年年、好风景，无事对花垂泪。\n园里。\n旧赏处、幽葩柔条，一一动芳意。\n恨心事。\n春来间阻，忆年时、把罗袂。\n雅戏。\n樱桃红颗，为插边明丽。\n又渐是。\n樱桃尝新，忍把旧游重记。\n何意。\n便云收雨歇，瓶沈簪折两无计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4149, '碧牡丹', '晁补之', '渐老闲情减。\n春山事、撩心眼。\n似血桃花，似雪梨花相间。\n望极雅川，阳焰迷归雁。\n征鞍方长坂。\n正魂乱。\n旧事如云散。\n良游盛年俱换。\n罢说功名，但觉青山归晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4150, '江神子・江城子', '晁补之', '双鸳池沼水融融。\n桂堂东。\n又春风。\n今日看花，花胜去年红。\n把酒问花花不语，携手处，遍芳丛。\n留春且住莫匆匆。\n秉金笼。\n夜寒浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4151, '好事近', '晁补之', '风雨过中秋，愁对画帘银烛。\n那更气迟节晚，负重阳金菊。\n月期花信尚参差。\n功名更难卜。\n何事四时俱好，□一杯一曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4152, '洞仙歌', '晁补之', '花恨月恼。\n更夏有凉风，冬轩雪皎。\n闲事不关心，算四时皆好。\n从来又说，春台登览，人意多同，常是惜、春过了。\n须痛饮，莫放欢情草草。\n年少。\n尚忆瑶阶，得隽寻芳，骖东城，适见垂鞭，南陌，又逢低帽。\n莺花荡眼，功名满意，无限嬉游，荣华事、如梦杳。\n伤富贵浮云，曾萦怀抱。\n为春醉倒。\n愿花更好。\n春休老。\n开口笑。\n占醉乡、莫教人到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4153, '洞仙歌', '晁补之', '当时我醉，美人颜色，如花堪悦。\n今日美人去，恨天涯离别。\n青楼朱箔，婵娟蟾桂，三五初圆，伤二八、还又缺。\n空伫立，一望一见心绝。\n心绝。\n顿成凄凉，千里音尘，一梦欢娱，推枕惊巫山远，洒泪对湘江阔。\n美人不见，愁人看花，心乱含愁，奏绿绮、弦清切。\n何处有知音，此恨难说。\n怨歌未阕。\n恐暮雨收、行云歇。\n窗梅发。\n乍似睹、芳容冰洁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4154, '水龙吟', '晁补之', '问春何苦匆匆，带风伴雨如驰骤。\n幽葩细萼，小园低槛，壅培未就。\n吹尽繁红，占春长久，不如垂柳。\n算春常不老，人愁春老，愁只是、人间有。\n春恨十常八九。\n忍轻辜、芳醪经口。\n那知自是，桃花结子，不因春瘦。\n世上功名，老来风味，春归时候。\n纵樽前痛饮，狂歌似旧，情难依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4155, '洞仙歌', '晁补之', '裙芳老尽，海棠花时候。\n雨过寒轻好清昼。\n最妖饶一段，全是初开，云鬟小，涂粉施朱未就。\n全开还自好，骀荡春馀，百样宫罗斗繁绣。\n纵无语也，心应恨我来迟，恰柳絮、将春归後。\n醉犹倚柔柯，怯黄昏，这一点愁，须共花同瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4156, '洞仙歌', '晁补之', '年年青眼。\n为江梅肠断。\n一句新诗思无限。\n向碧琼枝上，白玉葩中、春犹浅。\n一点龙香清远。\n谁抛倾国艳。\n昨夜前村，都恐东皇未曾见。\n正倚墙红杏，芳意浓时，惊千片。\n何许飘零仙馆。\n待冰雪丛中看奇姿，乍一笑能回，上林冬暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4157, '行香子', '晁补之', '雪里清香，月下疏枝。\n更无花、比并琼姿。\n一年一见，千绕千回。\n向未开时，愁花放，恐花飞。\n芳樽移就，幽葩折取，似玉人，携手同归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4158, '盐角儿', '晁补之', '开时似雪。\n谢时似雪。\n花中奇绝。\n香非在蕊，香非在萼，骨中香彻。\n占溪风，留溪月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4159, '清平乐', '晁补之', '黄花过也。\n月酒何曾把。\n寒蝶多情爱潇洒。\n晴日双双飞下。\n沈吟独倚朱阑。\n采芳贻向□边。\n枕上醉排金靥，幽香付与谁怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4160, '江神子・江城子', '晁补之', '去年初见早梅芳。\n一春忙。\n短红墙。\n马上不禁、花恼只颠狂。\n苏晋长斋犹好事，时唤我，举离觞。\n今年春事更茫茫。\n浅宫妆。\n断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4161, '望海潮', '晁补之', '人间花老，天涯春去，扬州别是风光。\n红药万株，佳名千种，天然浩态狂香。\n尊贵御衣黄。\n未便教西洛，独占花王。\n困倚东风，汉宫谁敢斗新妆。\n年年高会维阳。\n看家夸绝艳，人诧奇芳。\n结蕊当屏，联葩就幄，红遮绿绕华堂。\n花面映交相。\n更秉菅观洧，幽意难忘。\n罢酒风亭，梦魂惊恐在仙乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4162, '夜合花', '晁补之', '百紫千红，占春多少，共推绝世花王。\n西都万家俱好，不为姚黄。\n谩肠断巫阳。\n对沈香、亭北新妆。\n记清平调，词成进了，一梦仙乡。\n天葩秀出无双。\n倚朝晖，半如酣酒成狂。\n无言自有，檀心一点偷芳。\n念往事情伤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4163, '下水船', '晁补之', '百紫千红翠。\n唯有琼花特异。\n便是当年，唐昌观中玉蕊。\n尚记得、月里仙人来赏，明日喧传都市。\n甚时又，分与扬州本，一朵冰姿难比。\n曾向无双亭边，半酣独倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4164, '浣溪沙', '晁补之', '雨过园亭绿暗时。\n樱桃红颗压枝低。\n绿兼红好眼中迷。\n荔子天教生处远，风流一种阿谁知。\n最红深处有黄鹂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4165, '万年欢', '晁补之', '心忆春归，似佳人未来，香径无迹。\n雪里江梅，因甚早知消息。\n百卉芳心正寂。\n夜不寐、幽姿脉脉。\n图清晓、先作宫妆，似防人见偷得。\n真香媚情动魄。\n算当时寿阳，无此标格。\n应寄扬州，何郎旧曾相识。\n花似何郎鬓白。\n恐花笑、逢花羞摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4166, '感皇恩', '晁补之', '常岁海棠时，偷闲须到。\n多病寻芳懒春老。\n偶来恰值，半谢妖绕犹好。\n便呼诗酒伴，同倾倒。\n繁枝高荫，疏枝低绕。\n花底杯盘花影照。\n多情一片，恨我归来不早。\n断肠铺碎锦，门前道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4167, '洞仙歌', '晁补之', '今春闰好。\n怪重阳菊早。\n满槛煌煌看霜晓。\n唤金钱翠雨，不称标容，潇洒意、陶潜诗中能道。\n不应夸绝艳，曾妒春华，因甚东君意不到。\n又似锁，三千汉女，偏教明妃、怨西风边草。\n也何必、牛山苦沾衣，算只好龙山，醉狂吹帽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4168, '喜朝天・踏莎行', '晁补之', '众芳残。\n海棠正轻盈，绿鬓朱颜。\n碎锦繁绣，更柔柯映碧，纤匀殷。\n谁与将红间白，采熏笼、仙衣覆斑斓。\n如有意、浓妆淡抹，斜倚阑干。\n夭饶向晚春後，惯困欹晴景，愁怕朝寒。\n纵有狂雨，便离披损，不奈幽闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4169, '生查子', '晁补之', '青帝晓来风，偏傍梅梢紧。\n未放玉肌开，已觉龙香喷。\n此意比佳人，争奈非朱粉。\n惟有许飞琼，风味依稀近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4170, '少年游', '晁补之', '庐山瑶草四时春。\n烟锁上宫门。\n记得南游，偶寻飞涧，一洗庾公尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4171, '少年游', '晁补之', '如今田野谩抛春。\n红雨掩衡门。\n懒读诗书，欠伸扶杖，几案任生尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4172, '满江红', '晁补之', '华鬓春风，长歌罢、伤今感昨。\n春正好、瑶墀已叹，侍臣冥寞。\n牙帐尘昏馀剑戟，翠帷月冷虚弦索。\n记往岁、龙坂误曾登，今飘泊。\n贤人命，从来薄。\n流水意，知谁托。\n绕南枝身似，未眠飞鹊。\n射虎山边寻旧迹，骑鲸海上追前约。\n便江湖、与世永相忘，还堪乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4173, '离亭宴', '晁补之', '丹府黄香堪笑。\n章台坠鞭年少。\n细雨春风花落处，醉里中人传诏。\n却上五湖船，悲歌楚狂同调。\n青草荆江波渺。\n香炉紫霄簪小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4174, '千秋岁', '晁补之', '江头苑外。\n常记同朝退。\n飞骑轧，鸣珂碎。\n齐呕云绕扇，赵舞风回带。\n严鼓断，杯盘藉草犹相对。\n洒涕谁能会。\n醉卧藤阴盖。\n人已去，词空在。\n兔园高宴悄，虎观英游改。\n重感慨，惊涛自卷珠沈海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4175, '迷神引', '晁补之', '黯黯青山红日暮。\n浩浩大江东注。\n馀霞散绮，向烟波路。\n使人愁，长安远，在何处。\n几点渔灯小，迷近坞。\n一片客帆低，傍前浦。\n暗想平生，自悔儒冠误。\n觉阮途穷，归心阻。\n断魂素月，一千里、伤平楚。\n怪竹枝歌，声声怨，为谁苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4176, '满江红', '晁补之', '莫话南征，船头转、三千馀里。\n未叹此、浮生飘荡，但伤佳会。\n满眼青山芳草外，半篙碧水斜阳里。\n问此中、何处芰荷深，渔人指。\n清时事，羁游意。\n尽付与，狂歌醉。\n有多才南阮，自为知己。\n不似朱公江海去，未成陶令田园计。\n便楚乡、风景胜吾乡，何人对。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4177, '古阳关・阳关引', '晁补之', '暮草蛩吟噎。\n暗柳萤飞灭。\n空庭雨过，西风紧，飘黄叶。\n卷书帷寂静，对此伤离别。\n重感叹、中秋数日又圆月。\n沙觜樯杆上，淮水阔。\n有飞凫客，词珠玉，气冰雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4178, '玉蝴蝶', '晁补之', '暗忆少年豪气，烂南国、蓬岛风光。\n醉倚吴王宫殿，不解悲凉。\n舞犹慵、小腰似柳，歌尚怯、娇语如簧。\n好林塘。\n玳筵留住，彩舫携将。\n清狂。\n扬州一梦，中山千日，名利都忘。\n细数从前，眼中欢事尽成伤。\n去船迷，乱花流水，遗佩悄、寒草空江。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4179, '安公子', '晁补之', '柳老荷花尽。\n夜来霜落平湖净。\n征雁横天鸥舞乱，鱼游清镜。\n又还是、当年我向江南兴。\n移画船、深渚蒹葭映。\n对半篙碧水，满眼青山魂凝。\n一番伤华鬓。\n放歌狂饮犹堪逞。\n水驿孤帆明夜事，此欢重省。\n梦回处、诗塘春草愁难整。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4180, '惜分飞', '晁补之', '山水光中清无暑。\n是我消魂别处。\n只有多情雨。\n会人深意留人住。\n不见梅花来已暮。\n未见荷花又去。\n图画他年。\n断肠千古苕溪路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4181, '惜分飞', '晁补之', '消暑楼前双溪市。\n尽住水晶宫里。\n人共荷花丽。\n更无一点尘埃气。\n不会史君匆匆至。\n又作匆匆去计。\n谁解连红袂。\n大家都把兰舟系。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4182, '离亭宴', '晁补之', '忆向吴兴假守。\n双溪四垂高柳。\n仪凤桥边兰舟过，映水雕甍华牖。\n烛下小红妆，争看史君归後。\n携手松亭难又。\n题诗水轩依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4183, '满庭芳', '晁补之', '欲买庐山，山前三亩，小桥横过松间。\n变名吴市，谁认旧容颜。\n最好栖贤峡外，应自此、都隔尘寰。\n人稀到，壶中化国，光景更堪闲。\n无心，求至道，柴门闭了，饱睡甘。\n幸儿成孙长，为扫家山。\n若问它年归去，蓦地也、双桨来还。\n愁难舍，清风万壑，高处正跻攀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4184, '满庭芳', '晁补之', '闲说秋来，乘槎心懒，梦回三岛波间。\n便思黄帽，同我老山颜。\n上界仙人官府，何似我、萧散尘寰。\n云无止，流泉自急，此意本来闲。\n寂寥，松桂圃，陪君好语，亦可望。\n况琼枝玉蕊，秀满春山。\n若问幽栖何意，莫道是、飞鸟知还。\n无言处，孙登半岭，高韵更难攀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4185, '满庭芳', '晁补之', '归去来兮，名山何处，梦中庐阜嵯峨。\n二林深处，幽士往来多。\n自画远公莲社，教儿诵、李白长歌。\n如重到，丹崖翠户，琼草秀金坡。\n生绡，双幅上，诸贤中屦，文彩天梭。\n社中客，禅心古井无波。\n我似渊明逃社，怡颜盼、百尺庭柯。\n牛闲放，溪童任懒，吾已废鞭蓑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4186, '尾犯', '晁补之', '庐山小隐。\n渐年来疏懒，浸浓归兴。\n彩桥飞过，深溪地底，奔雷馀韵。\n香炉照日，望处与、青霄近。\n想群仙，呼我应远，怪来须丝垂镜。\n海上云车回轫。\n少姑传、金母信。\n森翠裾琼佩，落日初霞，纷纭相映。\n谁见壶中景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4187, '尉迟杯', '晁补之', '去年时。\n正愁绝，过却红杏飞。\n沈吟杏子青时。\n追悔负好花枝。\n今年又春到，傍小阑、日日数花期。\n花有信，人却无凭，故教芳意迟迟。\n及至待得融怡。\n未攀条拈蕊，已叹春归。\n怎得春如天不老，更教花与月相随。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4188, '八六子', '晁补之', '喜秋晴。\n淡云萦缕，天高群雁南征。\n正露冷初减兰红，风紧潜雕柳翠，愁人漏长梦惊。\n重阳景物凄清。\n渐老何时无事，当歌好在多情。\n暗自想、朱颜并游同醉，官名缰锁，世路蓬萍。\n难相见，赖有黄花满把，从教渌酒深倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4189, '临江仙', '晁补之', '尽说彭门新半，昆吾玉如泥。\n功名馀事不须为。\n才情诗里见，风味酒边知。\n好在阿咸同老也，青云往岁心期。\n千锺百首兴来时。\n伯伦从妇劝，元亮信儿痴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4190, '临江仙', '晁补之', '十岁儿曹同砚席，华裾织翠如葱。\n一生心事醉吟中。\n相逢俱白首，无语对西风。\n莫道尊前情调减，衰颜得酒能红。\n可怜此会意无穷。\n夜阑人总睡，独绕菊花丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4191, '蓦山溪', '晁补之', '谯园幽古，烟锁前朝桧。\n摇落枣红时，满园空、几株苍翠。\n史君才誉，金殿握兰人。\n将风调，改荒凉，便是嬉游地。\n刘郎莫问，去後桃花事。\n司马更堪怜，掩金觞、琵琶催泪。\n愁来不醉。\n不醉奈愁何，汝南周，东阳沈，劝我如何醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4192, '蓦山溪', '晁补之', '金樽玉酒，佳味名仙桧。\n恐是九龙泉，堪一饮、霜毛却翠。\n何须说此，只但饮陶陶，灯光底，百花春，自是仙家地。\n星郎早贵，惯见风流事。\n留我不须归，倒尊空、烛堆红泪。\n飞凫令尹，才调更翩翩，休吊古，枉伤神，有兴来同醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4193, '蓦山溪', '晁补之', '兰台仙史，好在多情否。\n不寄一行书，过西风、飞鸿去後。\n功名心事，千载与君同，只狂饮，只狂吟，绿鬓殊非旧。\n山歌村馆，愁醉浔阳叟。\n且借两州春，看一曲、樽前舞袖。\n古来毕竟，何处是功名，不同饮，不同吟，也劝时开口。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4194, '蓦山溪', '晁补之', '扬州全盛，往事今何处。\n帆锦两明珠，蔷薇、月中嬉语。\n朱衣白面，公子似神仙，登云屿。\n临烟渚。\n狂醉成怀古。\n兰舟归後，谁与春为主。\n吟笑我重来，倚琼花、东风日暮。\n吴霜点鬓，流落共天涯，竹西路。\n高阳侣。\n魂梦应相遇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4195, '忆秦娥', '晁补之', '牵人意。\n高堂照碧临烟水。\n清秋至。\n东山时伴，谢公携妓。\n黄菊虽残堪泛蚁。\n乍寒犹有重阳味。\n应相记。\n坐中少个，孟嘉狂醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4196, '好事近', '晁补之', '丝管闹南湖，湖上醉游时晚。\n独看小桥官柳，泪无言偷满。\n坐中谁唱解愁辞，红妆劝金盏。\n物是奈人非是，负东风心眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4197, '阮郎归', '晁补之', '西城北渚旧追随。\n荒台今是非。\n白苹无主绿蒲迷。\n停舟忆旧时。\n双鸭戏，乱鸥飞。\n人家烟雨西。\n不成携手折芳菲。\n兰绕惆怅归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4198, '阮郎归', '晁补之', '一濠秋水净涟漪。\n红妆照水嬉。\n攀条寻藕怯船移。\n浮萍湿绣衣。\n临好景，惜轻归。\n夕阳州渚迷。\n城门灯火簇轮蹄。\n沙鸥飞去时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4199, '阮郎归', '晁补之', '儿童嬉戏杏花堤。\n春归不解悲。\n重来草露湿人衣。\n无花空绕枝。\n曾学道，久望机。\n一尊甘若饴。\n平生鱼鸟与同归。\n临风心自知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4200, '宴桃源・如梦令', '晁补之', '往岁真源谪去。\n红泪扬州留住。\n饮罢一帆东，去入楚江寒雨。\n无绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4201, '一丛花', '晁补之', '王孙眉宇凤凰雏。\n天与世情疏。\n扬州坐上琼花底，佩锦囊、曾忆奚奴。\n金盏醉挥，满身花影，红袖竞来扶。\n十年一梦访林居。\n离缺重踯躇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4202, '一丛花', '晁补之', '碧山无意解银鱼。\n花底且携壶。\n华颠又喜熊罴且，笑骐骥，老反为驹。\n文史渐抛，功名更懒，随处见真如。\n高情敢并汉庭疏。\n长揖去田庐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4203, '一丛花', '晁补之', '飞凫仙令气如虹。\n脱屐向尘笼。\n凌烟画像云台议，似眼前、百草春风。\n盏里圣贤，壶中天地，高兴更谁同。\n应怀得隽大明宫。\n无事老冯公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4204, '临江仙', '晁补之', '曾唱牡丹留客饮，明年何处相逢。\n忽惊鹊起落梧桐。\n绿荷多少恨，回首背西风。\n莫叹今宵身是客，一尊未晓犹同。\n此身应似去来鸿。\n江湖春水阔，归梦故园中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4205, '临江仙', '晁补之', '常记河阳花县里，恰如饭颗山逢。\n春城何处满丝桐。\n纶巾并羽扇，君有古人风。\n重向梁王台畔见，黄花绿酒谁同。\n新诗别後寄南鸿。\n回头思照碧，人在白云中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4206, '浣溪沙', '晁补之', '帐饮都门春浪惊。\n东飞身与白鸥轻。\n淮山一点眼初明。\n谁使梦回兰芷国，却将春去凤凰城。\n樯乌风转不胜情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4207, '忆少年', '晁补之', '无穷官柳，无情画舸，无根行客。\n南山尚相送，只高城人隔。\n罨画园林溪绀碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4208, '江神子・江城子', '晁补之', '旧山铅椠倦栖迟。\n叩宸闱。\n向淮圻。\n五马行春，初喜後车随。\n太守风流容客醉，花压帽，酒淋衣。\n隋宫烟外草萋萋。\n菊花时。\n动旌旗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4209, '虞美人', '晁补之', '江南载酒平生事。\n游宦如萍寄。\n蓬山归路傍银台。\n还是扬州一梦、却惊回。\n年年后土春来早。\n不负金尊倒。\n明年珠履赏春时。\n应寄琼花一朵、慰相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4210, '金盏倒垂莲', '晁补之', '诸阮英游，尽千锺饮量，百丈词源。\n对舞春风，螺髻小双莲。\n念两处、登高临远，又伤芳物新年。\n此泪不待，桓伊危柱哀弦。\n身闲未应无事，趁栽梅径里，插柳池边。\n野鹤飘，幽兴在青田。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4211, '金盏倒垂莲', '晁补之', '休说将军，解弯弓掠地，岭河源。\n彩笔题诗，绿水映红莲。\n算总是、风流馀事，会须行乐□年。\n况有一部，随轩脆管繁弦。\n多情旧游尚忆，寄秋风万里，鸿雁天边。\n未学元龙，豪气笑求田。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4212, '西平乐', '晁补之', '凤诏传来绛阕，当宁思贤辅。\n淮海甘棠惠化，霖雨商岩吉梦，熊虎周郊旧卜。\n千秋盛际，催促朝天归去。\n动离绪。\n空眷恋，难暂驻。\n新植双亭临水，风月佳名未睹。\n准拟金尊时举。\n况乐府、风流一部。\n妍歌妙舞，萦云回雪，亲教与，恨难诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4213, '御街行', '晁补之', '年年不放春闲了。\n今岁衔杯少。\n来时柳上浅金黄，归路玉眠吹帽。\n惜春长似，五陵狂俊，不道朱颜老。\n斜烟薄雨青林杳。\n犹有莺声到。\n西园红艳绿盘龙，辜负一年春好。\n锦城乐事，不关愁眼，何似还家早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4214, '生查子', '晁补之', '宫里妒娥眉，十载辞君去。\n翠袖怯天寒，修竹无人处。\n今日近君家，望极香车骛。\n一水是红墙，有恨无由语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4215, '青玉案', '晁补之', '十年不向都门道。\n信匹马、羞重道。\n玉府骖鸾犹年少。\n宫花头上，御炉烟底，常日朝回早。\n霞觞翻手群仙笑。\n恨尘土人间易春老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4216, '水龙吟', '晁补之', '去年暑雨钩盘，夜阑睡起同征辔。\n今年芳草，齐河古岸，扁舟同舣。\n萍梗孤踪，梦魂浮世。\n别离常是。\n念当时绿鬓，狂歌痛饮，今憔悴、东风里。\n此去济南为说。\n道愁肠、不醒犹醉。\n多情北渚，两行烟柳，一湖春水。\n还唱新声，後人重到，应悲桃李。\n待归时，揽取庭前皓月，也应堪寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4217, '南歌子', '晁补之', '霜细犹欺柳，风柔已弄梅。\n东园捶鼓赏新醅。\n唤取舞周歌沈、探春回。\n妙舞堪千盏，长歌可百杯。\n笑人将恨上春台。\n劝我十分一举、两眉开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4218, '醉落魄・一斛珠', '晁补之', '高鸿远骛。\n溪山一带人烟簇。\n知君船近渔矶宿。\n轻素横溪，天淡挂寒玉。\n谁家红袖阑干曲。\n南陵风软波平绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4219, '万年欢', '晁补之', '忆惜论心，尽青云少年，燕赵豪俊。\n二十南游，曾上会稽千仞。\n捐袂江中往岁，有骚人、兰荪遗韵。\n嗟管鲍、当日贫交，半成翻手难信。\n君知未遇元礼，肯抽身盛时，寻我幽隐。\n此事谈何容易，骥才方骋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4220, '临江仙', '晁补之', '谪宦江城无屋买，残僧野寺相依。\n松间药臼竹间衣。\n水穷行到处，云起坐看时。\n一个幽禽缘底事，苦来醉耳边啼。\n月斜西院愈声悲。\n青山无限好，犹道不如归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4221, '虞美人', '晁补之', '原桑飞尽霜空杳。\n霜夜愁难晓。\n油灯野店怯黄昏。\n穷途不减酒杯深。\n故人心。\n羊山古道行人少。\n也送行人老。\n一般别语重千金。\n明年过我小园林。\n话如今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4222, '安公子', '晁补之', '少日狂游好。\n阆苑花间同低帽。\n不恨千金轻散尽，恨花残莺老。\n命小辔、翩翩随处金尊倒。\n从市人、拍手拦街笑。\n镇琼楼归卧，丽日三竿未觉。\n迷路桃源了。\n乱山沈水何由到。\n拨断朱弦成底事，痛知音人悄。\n似近日、曾教青鸟传佳耗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4223, '绿头鸭・多丽', '晁补之', '新秋近，晋公别馆开筵。\n喜清时、衔杯乐圣，未饶绿野堂边。\n绣屏深、丽人乍出，坐中雷雨起弦。\n花暖间关，冰凝幽咽，宝钗摇动坠金钿。\n未弹了、昭君遗怨，四坐已凄然。\n西风里、香街驻马，嬉笑微传。\n算从来、司空惯，断肠初对云鬟。\n夜将阑、井梧下叶，砌蛩收响悄林蝉。\n赖得多愁，浔阳司马，当时不在绮筵前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4224, '水龙吟', '晁补之', '满湖高柳摇风，坐看骤雨来湖面。\n跳珠溅玉，圆荷翻倒，轻鸥惊散。\n堂上凉生，槛前暑退，罗裾凌乱。\n想东山谢守，纶巾羽扇，高歌下、青天半。\n应记狂饮司马，去年时、黄花高宴。\n竹枝苦怨，琵琶多泪，新年鬓换。\n常恐归时，眼中物是，日边人远。\n望隋河一带，伤心雾霭，遣离魂断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4225, '惜奴娇', '晁补之', '歌阕琼筵，暗失金貂侣。\n说衷肠、丁宁嘱付。\n棹举帆开，黯行色、秋将暮。\n欲去。\n待却回、高城已暮。\n渔火烟村，但触目伤离绪。\n此情向、阿谁分诉。\n那里思量，争知我，思量苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4226, '临江仙', '晁补之', '身外闲愁空满眼，就中欢事常稀。\n明年应赋送君诗。\n试从今夜数，相会几多时。\n浅酒欲邀谁共劝，深情唯有君知。\n东溪春近好同归。\n柳垂江上影，梅谢雪中枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4227, '临江仙', '晁补之', '自古齐山重九胜，登临梦想依依。\n偶来恰值菊花时。\n难逢开口笑，须插满头归。\n昨夜一江风色好，平明秋浦帆飞。\n可怜如赴史君期。\n且当酬令节，不用叹斜晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4228, '满庭芳', '晁补之', '乡物牵情，家山回首，浩然归兴难收。\n报恩心事，投老拼悠悠。\n却笑当年牛下，轻自许、激烈寒讴。\n成何事，夷犹桂楫，兰芷咏芳洲。\n人生，萍梗迹，谁非乐土，何处吾州。\n算不须，临歧惝恍迟留。\n要看香炉瀑布，丹枫乱、江色凝秋。\n真堪与，潇湘暮雨，图上画扁舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4229, '定风波', '晁补之', '跨鹤扬州一梦回。\n东风佛面上平台。\n阆苑花前狂覆酒。\n拍手。\n东风骑凤却教来。\n谪好伯阳丹井畔。\n官满。\n平台还见片帆开。\n上界虽然官府好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4230, '千秋岁', '晁补之', '玉京仙侣，同受琅函结。\n风雨隔，尘埃绝。\n霞觞翻手破，阆苑花前别。\n鹏翼敛，人间泛梗无由歇。\n岂忆山中酒，还共溪边月。\n愁闷火，时间灭。\n何妨心似水，莫遣头如雪。\n春近也，江南雁识归时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4231, '千秋岁', '晁补之', '叶舟容易。\n行尽江南地。\n南雁断，无书至。\n怜君羁旅处。\n见我飘蓬际。\n如梦寐。\n当年阆苑曾相对。\n休说深心事。\n但付狂歌醉。\n那更话，孤帆起。\n水精溪绕户。\n云母山相砌。\n君莫去。\n只堪伴我溪山里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4232, '鹧鸪天', '晁补之', '欲上南湖采舫嬉。\n还思北渚与岚漪。\n圆荷盖水垂杨暗，鸳鸯总下时。\n持此意，遣谁知。\n清波还照鬓间丝。\n西楼重唱池塘好，应有红妆敛翠眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4233, '清平乐', '晁补之', '炎天畏景。\n午漏那堪永。\n何苦相仍愁簿领。\n短壑清溪牵兴。\n瑶台月下曾逢。\n何由却睹冰容。\n一笑为驱烦暑，故人元是清风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4234, '虞美人', '晁补之', '荒城又见重阳到。\n狂醉还吹帽。\n人生开口笑难逢。\n何况良辰一半，别离中。\n平台朱履登高处。\n犹自怀人否。\n且簪黄菊满头归。\n惟有此花风韵、似年时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4235, '浣溪沙', '晁补之', '江上秋高风怒号。\n江声不断雁嗷嗷。\n别魂调递为君销。\n一夜不眠孤客耳，耳边愁听雨萧萧。\n碧纱窗外有芭蕉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4236, '万年欢', '晁补之', '十里环溪，记当年并游，依旧风景。\n采舫红妆，重泛九秋清镜。\n莫叹歌台蔓草，喜相逢、欢情犹胜。\n苹洲畔、横玉惊鸾，半天云正愁凝。\n中秋醉魂未醒。\n又佳辰授衣，良会堪更。\n早岁功名，豪气尚凌汝颍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4237, '一丛花', '晁补之', '东君密意在花心。\n飞雪戏妆林。\n多情定怪春来晚，故穿花、千点深深。\n烟柳上轻，风丝漫袅，楼阁晚还阴。\n雕梁双燕悄来音。\n帘幕镇沈沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4238, '减字木兰花', '晁补之', '萍蓬行路。\n来不多时还遣去。\n会有重来。\n还把清尊此地开。\n隋河杨柳。\n见我五年三执手。\n红泪多情。\n待得重来走马迎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4239, '菩萨蛮', '晁补之', '玉京不许尘容到。\n疏慵只合疏慵老。\n鸥鸟共烟波。\n田夫与醉歌。\n忘怀无物我。\n莫似陈惊坐。\n勋业付长闲。\n西山爽气间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4240, '鹧鸪天', '晁补之', '吉梦灵蛇朱夏宜。\n佳辰阿母会瑶池。\n竹风荷雨来消暑，玉李冰瓜可疗肌。\n心悟了，道成时。\n不劳龙女骋威仪。\n僧祗世界共游戏，贤懿光阴比寿期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4241, '凤箫吟・芳草', '晁补之', '晓。\n雨和雨细，南园次第春融。\n岭梅犹妒雪，露桃云杏，已绽碧呈红。\n一年春正好，助人狂、飞燕游蜂。\n更吉梦良辰，对花忍负金锺。\n香浓。\n博山沈水，小楼清旦，佳气葱葱。\n旧游应未改，武陵花似锦，笑语相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4242, '梁州令', '晁补之', '二月春犹浅。\n去年樱桃开遍。\n今年春色怪迟迟，红梅常早，未露胭脂脸。\n东君故遣春来缓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4243, '引驾行', '晁补之', '春云轻锁，春风乍扇园林晓。\n扫华堂，正桃李芳时，诞辰还到。\n年少。\n记绛蜡光摇，金猊香郁宝妆了。\n骤骏马、天街向晚，喜同车、咏窈窕。\n多少。\n卢家壶范，杜曲家声荣耀。\n庆孟光齐眉，冯唐白首，镇同欢笑。\n缥缈。\n待琅函深讨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4244, '菩萨蛮', '晁补之', '百花含蓓东风里。\n南园小雨朱扉启。\n春色一年年。\n年年花共妍。\n清谈招隐去。\n莫认如宾处。\n华发好风光。\n林间此味长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4245, '点绛唇', '晁补之', '回雁风微，养花浓淡天容好。\n似春知道。\n吉梦佳辰到。\n共乐春台，携手蓬莱小。\n同倾祷。\n愿春不老。\n岁岁寻芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4246, '上林春・一落萦', '晁补之', '天惜中秋，三夜淡云，占得今宵明月。\n陬岁好，金风气爽，清时挺生贤哲。\n相门出相，算锺庆、自应累叶。\n乍归来，暂燕处，共仰赤松高辙。\n想人生、会须自悦。\n浮云事，笑里尊前休说。\n旧有衮衣，公归未晚，千岁盛明时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4247, '杨柳枝', '晁补之', '素色清薰出俗华。\n腊前花。\n轩前爱日扫云遮。\n几枝斜。\n月淡纱窗香暗透，白於纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4248, '蓦山溪', '晁补之', '凤凰山下，东畔青苔院。\n记得当初个，与玉人、幽欢小宴。\n黄昏风雨，人散不归家，帘旌卷。\n灯火颤。\n惊拥娇羞面。\n别来憔悴，偏我愁无限。\n歌酒情都减，也不独、朱颜改变。\n如今桃李，湖上泛舟时，青天晚。\n青山远。\n愿见无由见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4249, '蓦山溪', '晁补之', '自来相识，比你情都可。\n咫尺千里算，惟孤枕、单衾知我。\n终朝尽日，无绪亦无言，我心里，忡忡也，一点全无那。\n香笺小字，写了千千个。\n我恨无羽翼，空寂寞、青苔院锁。\n昨朝冤我，却道不如休，天天天，不曾麽，因甚须冤我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4250, '生查子', '晁补之', '夜引别佳人，梅小犹飘雪。\n忍泪一春愁，过却花时节。\n相见话相思，重与临风月。\n休似那回时，无事还轻别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4251, '少年游', '晁补之', '当年携手，是处成双，无人不羡。\n自间阻、五年也，一梦拥、娇娇粉面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4252, '青玉案', '晁补之', '三年宋玉墙东畔。\n怪相见、常低面。\n一曲文君芳心乱。\n匆匆依旧，吹散，月淡梨花馆。\n秋娘苦妒浮金盏。\n漏些子堪猜是娇盼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4253, '江城子', '晁补之', '娉娉闻道似轻盈。\n好佳名。\n也堪称。\n楚观云归，重见小樊惊。\n豆蔻梢头春尚浅，娇未顾，已倾城。\n章台休咏旧青青。\n惹离情。\n恨难平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4254, '青玉案', '晁补之', '彩云易散琉璃脆。\n念往事、心将碎。\n只合人间十三岁。\n百花开尽，丁香独自，结恨春风里。\n小圆幽槛经行地。\n恨春草佳名谩抛弃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4255, '胜胜慢・声声慢', '晁补之', '朱门深掩，摆荡春风，无情镇欲轻飞。\n断肠如雪，撩乱去点人衣。\n朝来半和细雨，向谁家、东馆西池。\n算未肯、似桃含红蕊，留待郎归。\n还记章台往事，别後纵青青，依旧时垂。\n灞岸行人多少，竟折柔枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4256, '点绛唇', '晁补之', '檀口星眸，艳如桃李情柔惠。\n据我心里。\n不肯相抛弃。\n哭怕人猜，笑又无滋味。\n忡忡地。\n系人心里。\n一句临歧誓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4257, '永遇乐', '晁补之', '银烛将残，玳筵初散，依旧愁绪。\n醉里凝眸，娇来纵体，此意难分付。\n怜伊只似，风前轻燕，好语暂来还去。\n重楼静，珠帘休下，待扫画梁留住。\n青娥浩齿，云鬓花面，见了绮罗无数。\n只你厌厌，教人竟日，一点无由诉。\n如今拼了，萦眠惹梦，没个顿身心处。\n深诚事，骖鸾解佩，是许未许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4258, '虞美人', '晁补之', '梅花时候君轻去。\n曾寄红笺句。\n胡麻好种少人知。\n正是归时何处、误芳期。\n谁教又作狂游远。\n归路杨花满。\n当年不负琐窗春。\n老向长楸走马、更愁人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4259, '行香子', '晁补之', '柳态纤柔，雪艳疏明。\n问人来、人道轻盈。\n张琵莲脸，一寸横波。\n比潇洒处，犹难称，此嘉名。\n花前烛下，微频浅笑，要题诗、盏畔低声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4260, '感皇恩', '晁补之', '终岁忆春回，西园行尽。\n欢喜梅梢上春信。\n去年携手，暗约芳时还近。\n燕来莺又到，人无准。\n凭谁向道，流光一瞬。\n佳景闲无事衣褪。\n春归何处，又对飞花难问。\n旧欢都未遇，成新恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4261, '临江仙', '晁补之', '马上匆匆听鹊喜，朦胧月淡黄昏。\n碧罗双扇拥朝云。\n粉光先辨脸，朱色怎分唇。\n暂别宝奁蛛网遍，春风泪污榴裙。\n香笺小字寄行云。\n纤腰非学楚，宽带为思君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4262, '碧牡丹', '晁补之', '院宇帘垂地。\n银筝雁、低春水。\n送出灯前，婀娜腰枝柳细。\n步蹙香，红浪随鸳履。\n梁州紧凤翘坠。\n悚轻体。\n绣带因风起。\n霓裳恐非人世。\n调促香檀，困入流波生媚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4263, '少年游', '晁补之', '前时相见，楼头窗畔，尊酒望银蟾。\n如今间阻，银蟾又满，小阁下朱帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4264, '西江月', '晁补之', '似有如无好事，多离少会幽怀。\n流莺过了又蝉催。\n肠断碧云天外。\n不寄书还可恨，全无梦也堪猜。\n秋风吹泪上楼台。\n只恐朱颜便改。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4265, '鹧鸪天', '晁补之', '绣幕低低拂地垂。\n春风何事入罗帏。\n胡麻好种无人种，正是归时君未归。\n临晚景，忆当时。\n愁心一动乱如丝。\n夕阳芳草本无恨，才子佳人空自悲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4266, '满江红', '晁补之', '月上西窗，书帏静、灯明又减。\n水漏涩、铜壶香炉，夜霜如雪。\n睡眼不曾通夕闭，梦魂争得连宵接。\n念碧云、川路古来长，无由越。\n鸾钗重，青丝滑。\n罗带缓，小腰怯。\n伊多感那更，恨离伤别。\n正是少年佳意气，渐当故里春时节。\n归去来、莫教子规啼，芳菲歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4267, '菩萨蛮', '晁补之', '丝篁斗好莺羞巧。\n红檀微映燕脂小。\n当□敛双蛾。\n曲中幽恨多。\n知君怜舞袖。\n舞要歌成就。\n独舞不成妍。\n因歌舞可怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4268, '临江仙', '晁补之', '离别寻常今白首，更须竹雨萧萧。\n不应都占世间豪。\n清风居士手，杨柳洛城腰。\n文字功名真自误，从今好月良宵。\n只消怜取董娇饶。\n修门君自到，不用我词招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4269, '临江仙', '晁补之', '君似苍崖千仞竹，一枝孤映蒿萧。\n箪瓢不减万锺豪。\n闲情搔短发，佳句咏纤腰。\n罢酒兰舟回楚，相思何处今宵。\n淮南幽桂水云饶。\n他年春草恨，应有小山招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4270, '紫玉箫', '晁补之', '罗绮丛中，笙歌丛里，眼狂初认轻盈。\n无花解比，似一钩新月，云际初生。\n算不虚得，都占与、第一佳名。\n轻归去，那知有人，别後牵情。\n襄王自是春梦，休谩说东墙，事更难凭。\n谁教慕宋，要题诗曾倚，宝柱低声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4271, '斗百草', '晁补之', '别日常多，会时常少天难晓。\n正喜花开，又愁花谢，春也似人易老。\n惨无言、念旧日朱颜，清欢莫笑。\n便苒苒如云，霏霏似雨，去无音耗。\n追想墙头梅下，门里桃边，名利为伊都忘了。\n血写香笺，泪封罗帕，记三日、离肠恨搅。\n如今事，十二楼空凭谁到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4272, '斗百草', '晁补之', '往事临邛，旧游雅态羞重忆。\n解赋才高，好音情慧，琴里句中暗识。\n正当年、似阆苑琼枝，朝朝相倚。\n便涤器何妨，当炉正好，镇同比翼。\n谁使褰裳佩失，推枕云归，惆怅至今遗恨积。\n双鲤书来，大刀诗意，纵章台、青青似昔。\n重寻事，前度刘郎转愁寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4273, '斗百花', '晁补之', '小小盈盈珠翠。\n忆得眉长眼细。\n曾共映花低语，已解伤春情意。\n重向溪堂，临风看舞梁州，依旧照人秋水。\n转更添姿媚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4274, '斗百花', '晁补之', '脸色朝霞红腻。\n眼色秋波明媚。\n云度小钗浓鬓，雪透轻绮香臂。\n不语凝情，教人唤得回头，斜盼未知何意。\n百态生珠翠。\n低问石上，凿井何由及底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4275, '斗百花', '晁补之', '斜日东风深院。\n绣幕低迷归燕。\n潇洒小屏娇面，仿佛灯前初见。\n与选筵中，银盆半拆姚黄，插向凤凰钗畔。\n微笑遮纨扇。\n教展香，看舞霓裳促遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4276, '御街行', '晁补之', '天街欲照珠帘粉。\n辔曾相近。\n繁花乐事老来慵，对酒尚怜佳景。\n王孙年少，风流应更，无奈春愁闷。\n幽期莫误香闺恨。\n罗带今朝褪。\n月圆花好一般春，触处总堪乘兴。\n有人惆怅，何如归好，相见凭君问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4277, '南歌子', '晁补之', '睡起临窗坐，妆成傍砌闲。\n春来莫卷绣帘看。\n嫌怕东风吹恨、在眉间。\n鹦鹉花前弄，琵琶月下弹。\n蓦然收袖倚栏干。\n一向思量何事、点云鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4278, '清平乐', '晁补之', '寒风雁度。\n声向千门去。\n也到文闱校文处。\n也到文君绣户。\n背灯解带惊魂。\n长安此夜秋声。\n早是夜寒不寐，五更风雨无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4279, '好事近', '晁补之', '归路苦无多，正值早秋时节。\n应是画帘灵鹊，把归期先说。\n就中风送马蹄轻，人意渐欢悦。\n此夜醉眠无梦，任西楼斜月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4280, '调笑・调笑令', '晁补之', '肠断。\n越江岸。\n越女江头纱自浣。\n天然玉貌铅红浅。\n自弄芙蓉日晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4281, '调笑・调笑令', '晁补之', '将暮。\n乱心素。\n上客风流名重楚。\n临街下马当窗户。\n饭煮凋胡留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4282, '调笑・调笑令', '晁补之', '波恶。\n倚江阁。\n大轲峨帆夜落。\n横堂朱户多行乐。\n大堤花容绰约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4283, '调笑・调笑令', '晁补之', '相误。\n空凝伫。\n郑子江头逢二女。\n霞衣曳玉非尘土。\n笑解明轻付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4284, '调笑・调笑令', '晁补之', '寸结。\n肝肠切。\n织锦机边音韵咽。\n玉琴尘暗薰炉歇。\n望尽床头秋月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4285, '调笑・调笑令', '晁补之', '心记。\n好心事。\n玉刻容颜眉刷翠。\n杜郎生得真男子。\n况是东家妖丽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4286, '调笑・调笑令', '晁补之', '相忆。\n顿轻掷。\n春草佳名渐赠璧。\n长洲茂苑吴王国。\n自有芊绵碧色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4287, '洞仙歌', '晁补之', '青烟幂处，碧海飞金镜。\n永夜闲阶卧桂影。\n露凉时、零乱多少寒，神京远，惟有蓝桥路近。\n水晶帘不下，云母屏开，冷浸佳人淡脂粉。\n待都将许多明，付与金尊，投晓共、流霞倾尽。\n更携取、胡床上南楼，看玉做人间，素秋千倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4288, '下水船', '晁补之', '上客骊驹系。\n惊唤银屏睡起。\n困倚妆台，盈盈正解罗髻。\n凤钗垂，缭绕金盘玉指。\n巫山一段云委。\n半窥镜、向我横秋水。\n斜颔花枝交镜里。\n淡拂铅华，匆匆自整罗绮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4289, '失调名', '晁补之', '残腊初雪霁。\n梅白飘香蕊。\n依前又还是，迎春时候，大家都备。\n灶马门神，酒酌酴酥，桃符尽书吉利。\n五更催驱傩，爆竹起。\n虚耗都教退。\n交年换新岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4290, '洞仙歌', '晁补之', '江陵种橘，尚比封侯贵。\n何况江涛转千里。\n带天香，含洞乳，宜入春盘，红荔子，驰驿风流仅比。\n齿疏潘令老，怯咀冰霜，十颗金苞谩分遗。\n记觞前、须细认，别有馀甘，从此去，枉却栽桃种李。\n想相如酒渴对文君，迥不是人间，等闲风味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4291, '洞仙歌', '晁补之', '温江异果，惟有泥山贵。\n驿送江南数千里。\n半含霜，轻雾，曾怯吴姬，亲赠我，绿桔黄柑怎比。\n双亲云水外，游子空怀，惆怅无人可归遗。\n报周郎、须念我，物少情多，春酒醉，独胜甜桃醋李。\n况灯火楼台近元宵，似不减年时，袖中香味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4292, '菩萨蛮', '陈师道', '行云过尽星河烂。\n炉烟未断蛛丝满。\n想得两眉颦。\n停针忆远人。\n河桥知有路。\n不解留郎住。\n天上隔年期。\n人间长别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4293, '菩萨蛮', '陈师道', '东风乌鹊西飞燕。\n盈盈一水经年见。\n急雨洗香车。\n天回河汉斜。\n离愁千载上。\n相远长相望。\n终不似人间。\n回头万里山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4294, '菩萨蛮', '陈师道', '绮楼小小穿针女。\n秋光点点蛛丝雨。\n今夕是何宵。\n龙车乌鹊桥。\n经年谋一笑。\n岂解令人巧。\n不用问如何。\n人间巧更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4295, '菩萨蛮', '陈师道', '银潢清浅填乌鹊。\n画檐急雨长河落。\n初月未成圆。\n明星惜此筵。\n愁来无断绝。\n岁岁年年别。\n不用泪红滋。\n年年岁岁期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4296, '木兰花・玉楼春', '陈师道', '阴阴云日江城晚。\n小院回廊春已满。\n谁教言语似鹂黄，深闭玉笼千万怨。\n蓬莱易到人难见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4297, '南柯子・南歌子', '陈师道', '故国山河在，新堂冰雪生。\n万家和气贺初成。\n人在笙歌声里、暗生春。\n今代无双士，当年第一人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4298, '西江月', '陈师道', '楼上风生白羽，尊前笑出青春。\n破红展翠恰如今。\n把酒如何不饮。\n绣幕灯深绿暗，画帘人语黄昏。\n晚云将雨不成阴。\n竹月风窗弄影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4299, '菩萨蛮', '陈师道', '喧喧车马西郊道。\n临行更觉人情好。\n住有一年情。\n去留千载名。\n离歌声欲尽。\n只作常时听。\n天上玉堂东。\n阳春是梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4300, '虞美人', '陈师道', '城南观阁连云起。\n形像丹青里。\n使君笳鼓渡江来。\n尽带江南春色、放春回。\n青春欲住风催去。\n流水花无数。\n尊前触目一番新。\n只有玉楼明月、记游人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4301, '木兰花・玉楼春', '陈师道', '湖平木落摇空阔。\n叶底流泉鸣复咽，酒边清漏往时同，花里朱弦纤手抹。\n风光过手春冰滑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4302, '南乡子', '陈师道', '晴野下田收。\n照影寒江落雁洲。\n禅榻茶炉深闭阁，飕飕。\n横雨旁风不到头。\n登览却轻酬。\n剩作新诗报答秋。\n人意自阑花自好，休休。\n今日看时蝶也愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4303, '南乡子', '陈师道', '潮落去帆收。\n沙涨江回旋作洲。\n侧帽独行斜照里，飕飕。\n卷地风前更掉头。\n语妙後难酬。\n回雁峰南未得秋。\n唤取佳人听旧曲，休休。\n瘴雨无花孰与愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4304, '西江月', '陈师道', '点点轻黄减白，垂垂重露生鲜。\n肌香骨秀月中仙。\n雪满瑶台曳练。\n绰约却宜长见，清真不假馀妍。\n殷勤与插小婵娟。\n要试尊前玉面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4305, '西江月', '陈师道', '叶叶枝枝绿暗，重重密密红滋。\n芳心应恨赏春迟。\n不会春工著意。\n晚照酒生娇面，新妆睡污胭脂。\n凭将双叶寄相思。\n与看钗头何似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4306, '菩萨蛮', '陈师道', '髻钗初上朝云卷。\n眼波翻动眉山远。\n一曲杜韦娘。\n当年枉断肠。\n佳期如好月。\n拟满还须缺。\n别易见应难。\n长须仔细看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4307, '减字木兰花', '陈师道', '清尊白发。\n曾是登临年少客。\n不似当年。\n人与黄花两并妍。\n来愁去恨。\n十载相看情不尽。\n莫更思量。\n梦破春回枉断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4308, '满庭芳', '陈师道', '闽岭先春，琅函联璧，帝所分落人间。\n绮窗纤手，一缕破双团。\n云里游龙舞凤，香雾起、飞月轮边。\n华堂静，松风竹雪，金鼎沸潺。\n门阑。\n车马动，扶黄籍白，小袖高鬟。\n渐胸里轮，肺腑生寒。\n唤起谪仙醉倒，翻湖海、倾泻涛澜。\n笙歌散，风帘月幕，禅榻鬓丝斑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4309, '南乡子', '陈师道', '急雨打寒窗。\n雨气侵灯暗壁缸。\n窗下有人挑锦字，行行。\n泪湿红绡减旧香。\n往事最难忘。\n更著秋声说断肠。\n曲渚圆沙风叶底，藏藏。\n谁使鸳鸯故作双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4310, '清平乐', '陈师道', '休休莫莫。\n更莫思量著。\n记著不如浑忘著。\n百种寻思枉却。\n绣囊锦帐吹香。\n雄蜂雌蝶难双。\n眉上放开春色，眼前怜取新郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4311, '清平乐', '陈师道', '藏藏摸摸。\n好事争如莫。\n背後寻思浑是错。\n猛与将来放著。\n吹花卷絮无踪。\n晚妆知为谁红。\n梦断阳台云雨，世间不要春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4312, '南乡子', '陈师道', '阴重雨垂垂。\n并马西郊试薄衣。\n红蕊未开花已过，迟迟。\n不见东风著意时。\n酒到更须辞。\n报答春光旧有期。\n勤苦著书妨作乐，痴痴。\n莫学衰翁万事非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4313, '罗敷媚・采桑子', '陈师道', '春风吹尽秋光照，瘦减初黄。\n改样新妆。\n特地相逢只认香。\n南台九日登临处，不共飞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4314, '罗敷媚・采桑子', '陈师道', '芙蓉不借韶华助，故著缃黄。\n宿面留妆。\n不出寒花只暂香。\n伤春不尽悲秋苦，落蕊浮觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4315, '木兰花・玉楼春', '陈师道', '荣光休气天为瑞。\n道祖当天传宝裔。\n千年昌运此时逢，四海欢声今日沸。\n香雾沾衣腻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4316, '木兰花减字・减字木兰花', '陈师道', '娉婷娜袅。\n红落东风青子小。\n妙舞逶迤。\n拍误周郎却未知。\n花前月底。\n谁唤分司狂御史。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4317, '木兰花减字・减字木兰花', '陈师道', '娉娉袅袅。\n芍药枝头红玉小。\n舞袖迟迟。\n心到郎边客已知。\n当筵举酒。\n劝我尊前松柏寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4318, '临江仙', '陈师道', '离别寻常今白首，更须竹雨萧萧。\n不应都占世间豪。\n清风居士手，杨柳洛城腰。\n文字功名真自误，从今好月良宵。\n只消怜取董娇饶。\n修门君自到，不用我词招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4319, '南柯子・南歌子', '陈师道', '天上云为瑞，人间睡作魔，疏帘清簟汗成河。\n酒醒梦回眵眼、费摩娑。\n但有寒喧问，初无凤鸟过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4320, '木兰花减字・减字木兰花', '陈师道', '匀红点翠。\n取次梳妆谁得似。\n风柳腰肢。\n尽日纤柔属阿谁。\n娇娇小小。\n却是寻春人较老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4321, '清平乐', '陈师道', '秋声隐地。\n叶叶无留意。\n冰簟流光团扇坠。\n惊起双栖燕子。\n夜堂帘合回廊。\n风帏吹乱凝香。\n卧看一庭名月，晓衾不耐初凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4322, '清平乐', '陈师道', '秋光烛地。\n帘幕生秋意。\n露叶翻风惊鹊坠。\n暗落青林红子。\n微行声断长廊。\n熏炉衾换生香。\n灭烛却延明月，揽衣先怯微凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4323, '卜算子', '陈师道', '纤软小腰身，明秀天真面。\n淡画修眉小作春，中有相思怨。\n背立向人羞，颜破因谁倩。\n不比阳台梦里逢，亲向尊前见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4324, '洛阳春・一落萦', '陈师道', '酒到横波娇满。\n和香喷面。\n攀花落雨祝东风，诮不借、周郎便。\n背立腰肢挪拈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4325, '浣溪沙', '陈师道', '暮叶朝花种种陈。\n三秋作意向诗人。\n安排云雨要新清。\n随意且须追去马，轻衫从使著行尘。\n晚窗谁念一愁新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4326, '临江仙', '陈师道', '官样初黄过闰九。\n鲜妍时更宜寒。\n挽回人意不成阑。\n香罗堆叶密，芳意著心单。\n过与後房歌舞手，轻盈喜色生颜。\n堕钗拥髻与垂鬟。\n欲知谁称面，遍插一枝看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4327, '清平乐', '陈师道', '重重叠叠。\n娜娜裙千。\n时样官黄香百叶。\n一岁相逢两节。\n曲阑绕遍芳丛。\n一枝作意妍。\n折得有谁相忆，却须还与秋风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4328, '南乡子', '陈师道', '风絮落东邻。\n点缀繁枝旋化尘。\n关锁玉楼巢燕子，冥冥。\n桃李摧残不见春。\n流转到如今。\n翡翠生儿翠作衿。\n花样腰身官样立，婷婷。\n困倚阑干一欠伸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4329, '南乡子', '陈师道', '乱蕊压枝繁。\n堆积金钱闹作团。\n晚起涂黄仍带酒，看看。\n衣剩腰肢故著单。\n薄瘦却禁寒。\n牵引人心不放阑。\n拟折一枝遮老眼，难难。\n蝶横蜂争只倚阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4330, '临江仙', '陈师道', '曲巷斜街信马，小桥流水谁家。\n浅衫深袖倚门斜。\n只缘些子意，消得百般夸。\n粉面初生明月，酒容欲退朝霞。\n春风还解染霜华。\n肯持鸳绮被，来伴杜家花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4331, '蝶恋花', '陈师道', '九里山前千里路。\n流水无情，只送行人去。\n路转河回寒日暮。\n连峰不许重回顾。\n水解随人花却住。\n衾冷香销，但有残妆污。\n泪入长江空几许。\n双洪一抹无寻处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4332, '西江月', '陈师道', '浅色千重柔叶，深心一点娇黄。\n只消可意更须香。\n好个风流模样。\n玉蕊今谁攀折，诗人此日凄凉。\n正须蛮素作伊凉。\n与插钗傍鬓上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4333, '洛阳春・一落萦', '陈师道', '素手拈花纤软。\n生香相乱。\n却须诗力与丹青，恐俗手、难成染。\n一顾教人微倩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4334, '菩萨蛮', '陈师道', '清词丽句前朝曲。\n使君借与灯前读。\n读罢已三更。\n寒窗雨打声。\n应怜诗客老。\n要使情怀好。\n犹有解歌人。\n尊前未得听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4335, '木兰花减字・减字木兰花', '陈师道', '清愁叠积。\n更莫迟留春酒逼。\n吹面和风。\n梅信新来一线通。\n危楼晓望。\n雪满群山开画障。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4336, '卜算子', '陈师道', '梅岭数枝春，疏影斜临水。\n不借芳华只自香，娇面长如洗。\n还把最繁枝，过与偏怜底。\n拭傍鸾台仔细看，何似丹青里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4337, '渔家傲', '陈师道', '一舸姑苏风雨疾。\n吴笺满载红犹湿。\n色润朝花光触日。\n人未识。\n街南小阮应先得。\n青入柳条初著色。\n溪梅已露春消息。\n拟作新词酬帝力。\n轻落笔。\n黄秦去後无强敌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4338, '少年游', '陈师道', '御园果子压枝繁。\n看看分摘无缘。\n团沙弄雪，劳心费手，不肯暂时圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4339, '南乡子', '陈师道', '袅娜破瓜馀。\n豆蔻梢头二月初。\n众里腰肢遥可识，应殊。\n暗里犹能摸得渠。\n醉侧不须扶。\n唤作周家行画图。\n背立欠伸花絮底，知无。\n未信丹青画得如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4340, '木兰花减字・减字木兰花', '陈师道', '今年百五。\n风日清明尘不举。\n紫袖红陈。\n三节烟花次第春。\n来舆去马。\n千念一空春事谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4341, '踏莎行', '陈师道', '红上花梢，风传梅信。\n青春欲动群芳竞。\n林声鸟语带馀寒，江光野色开游径。\n乍雨还晴，喧寒不定。\n重门深院帘帷静。\n又还日日唤愁生，到谁准拟风流病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4342, '菩萨蛮', '陈师道', '晓来误入桃源洞。\n恰见佳人春睡重。\n玉腕枕香腮。\n荷花藕上开。\n一扇俄惊起。\n敛黛凝秋水。\n笑倩整金衣。\n问郎来几时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4343, '卜算子', '陈师道', '摇风影似凝，带雪香如抱。\n开尽南枝到北枝，不道春将老。\n飘姑射仙，谁识冰肌好。\n会有青绫梦觉人，可爱池塘草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4344, '卜算子', '陈师道', '绣幕罩梅花，莫放清香透。\n鉴里朱颜岁岁移，只道花依旧。\n把酒问梅花，知我离情否。\n若使梅花知我时，料得花须瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4345, '卜算子', '陈师道', '雪暗岭头云，竹冷溪边树。\n还似潇湘缥缈人，玉骨笼香雾。\n月下幽香度。\n梦里香魂驻。\n回首南枝酒半醺，寂寞无寻处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4346, '减字木兰花', '青幕子妇', '清词丽句。\n永叔子瞻曾独步。\n似恁文章。\n写得出来当甚强。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4347, '减字木兰花', '张耒', '个人风味。\n只有江梅些子似。\n每到开时。\n满眼清愁只自知。\n霞裾仙。\n姑射神人风露态。\n蜂蝶休忙。\n不与春风一点香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4348, '鹧鸪天', '张耒', '倾盖相逢汝水滨。\n须知见面过闻名。\n马头虽去无千里，酒盏才倾且百分。\n嗟得失，一微尘。\n莫教冰炭损精神。\n北扉西禁须公等，金榜当年第一人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4349, '满庭芳', '张耒', '裂楮裁筠，虚明潇洒，制成方丈屠苏。\n草团蒲坐，中置一山炉。\n拙似春林鸠宿，易于□、秋野鹑居。\n谁相对，时烦孟妇，石鼎煮寒蔬。\n嗟吁。\n人生随分足，风云际会，漫付伸舒。\n且偷取闲时，向此踌躇。\n谩取黄金建厦，繁华梦、毕竟空虚。\n争如且、寒村厨火，汤饼一斋盂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4350, '风流子', '张耒', '木叶亭皋下，重阳近，又是捣衣秋。\n奈愁入庾肠，老侵潘鬓，谩簪黄菊，花也应羞。\n楚天晚，白苹烟尽处，红蓼水边头。\n芳草有情，夕阳无语，雁横南浦，人倚西楼。\n玉容，知安否，香笺共锦字，两处悠悠。\n空恨碧云离合，青鸟沈浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4351, '秋蕊香', '张耒', '帘幕疏疏风透。\n一线香飘金兽。\n朱阑倚遍黄昏後。\n廊上月华如昼。\n别离滋味浓於酒。\n著人瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4352, '少年游', '张耒', '含羞倚醉不成歌。\n纤手掩香罗。\n偎花映烛，偷传深意，酒思入横波。\n看朱成碧心迷乱，翻脉脉、敛双蛾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4353, '失调名', '张耒', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4354, '失调名', '张耒', '菖蒲酒满劝人人，愿年年欢醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4355, '失调名', '张耒', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4356, '临江仙', '侯蒙', '未遇行藏谁肯信，如今方表名踪。\n无端良匠画形容。\n当风轻借力，一举入高空。\n才得吹嘘身渐稳，只疑远赴蟾宫。\n雨馀时候夕阳红。\n几人平地上，看我碧霄中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4357, '瑞龙吟', '周邦彦', '章台路。\n还见褪粉梅梢，试花桃树。\n坊陌人家，定巢燕子，归来旧处。\n暗凝伫。\n因念个人痴小，乍窥门户。\n侵晨浅约宫黄，障风映袖，盈盈笑语。\n前度刘郎重到，访邻寻里，同时歌舞。\n唯有旧家秋娘，声价如故。\n吟笺赋笔，犹记燕台句。\n知谁伴，名园露饮，东城闲步。\n事与孤鸿去。\n探春尽是，伤离意绪。\n官柳低金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4358, '锁窗寒・琐寒窗', '周邦彦', '暗柳啼鸦，单衣伫立，小帘朱户。\n桐花半亩，静锁一庭愁雨。\n洒空阶，夜阑未休，故人剪烛西窗语。\n似楚江暝宿，风灯零乱，少年羁旅。\n迟暮。\n嬉游处。\n正店舍无烟，禁城百五。\n旗亭唤酒，付与高阳俦侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4359, '风流子', '周邦彦', '新绿小池塘。\n风帘动，碎影舞斜阳。\n羡金屋去来，旧时巢燕，土花缭绕，前度莓墙。\n绣阁凤帏深几许，曾听得理丝簧。\n欲说又休，虑乖芳信，未歌先咽，愁近清觞。\n遥知新妆了，开朱户，应自待月西厢。\n最苦梦魂，今宵不到伊行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4360, '渡江云', '周邦彦', '晴岚低楚甸，暖回雁翼，阵势起平沙。\n骤惊春在眼，借问何时，委曲到山家。\n涂香晕色，盛粉饰、争作妍华。\n千万丝、陌头杨柳，渐渐可藏鸦。\n堪嗟。\n清江东注，画舸西流，指长安日下。\n愁宴阑，风翻旗尾，潮溅乌纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4361, '应天长', '周邦彦', '条风布暖，霏雾弄晴，池塘遍满春色。\n正是夜堂无月，沈沈暗寒食。\n梁间燕，前社客。\n似笑我、闭门愁寂。\n乱花过，隔院芸香，满地狼藉。\n长记那回时，邂逅相逢，郊外驻油壁。\n又见汉宫传烛，飞烟五候宅。\n青青草，迷路陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4362, '荔枝香近・荔枝香', '周邦彦', '照水残红零乱，风唤去。\n尽日测测轻寒，帘底吹香雾。\n黄昏客枕无，细响当窗雨。\n看两两相依燕新乳。\n楼下水，渐绿遍、行舟浦。\n暮往朝来，心逐片帆轻举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4363, '荔枝香近・荔枝香', '周邦彦', '夜来寒侵酒席，露微泫。\n履初会，香泽方熏，无端暗雨催人，但怪灯偏帘卷。\n回顾，始觉惊鸿去云远。\n大都世间，最苦唯聚散。\n到得春残，看即是、开离宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4364, '还京乐', '周邦彦', '禁烟近，触处、浮香秀色相料理。\n正泥花时候，奈何客里，光阴虚费。\n望箭波无际。\n迎风漾日黄云委。\n任去远，中有万点，相思清泪。\n到长淮底。\n过当时楼下，殷勤为说，春来羁旅况味。\n堪嗟误约乖期，向天涯、自看桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4365, '扫地花・扫地游', '周邦彦', '晓阴翳日，正雾霭烟横，远迷平楚。\n暗黄万缕。\n听鸣禽按曲，小腰欲舞。\n细绕回堤，驻马河桥避雨。\n信流去。\n想一叶怨题，今在何处。\n春事能几许。\n任占地持杯，扫花寻路。\n泪珠溅俎。\n叹将愁度日，病伤幽素。\n恨入金徽，见说文君更苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4366, '解连环', '周邦彦', '怨怀无托。\n嗟情人断绝，信音辽邈。\n信妙手、能解连环，似风散雨收，雾轻云薄。\n燕子楼空，暗尘锁、一床弦索。\n想移根换叶。\n尽是旧时，手种红药。\n汀洲渐生杜若。\n料舟依岸曲，人在天角。\n谩记得、当日音书，把闲语闲言，待总烧却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4367, '玲珑四犯', '周邦彦', '李夭桃，是旧日潘郎，亲试春艳。\n自别河阳，长负露房烟脸。\n憔悴鬓点吴霜，念想梦魂飞乱。\n叹画阑玉砌都换。\n才始有缘重见。\n夜深偷展香罗荐。\n暗窗前、醉眠葱茜。\n浮花浪蕊都相识，谁更曾抬眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4368, '丹凤吟', '周邦彦', '迤逦春光无赖，翠藻翻池，黄蜂游阁。\n朝来风暴，飞絮乱投帘幕。\n生憎暮景，倚墙临岸，杏靥夭斜，榆钱轻薄。\n昼永惟思傍枕，睡起无，残照犹在亭角。\n况是别离气味，坐来但觉心绪恶。\n痛引浇愁酒，奈愁浓如酒，无计消铄。\n那堪昏暝，簌簌半檐花落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4369, '满江红', '周邦彦', '昼日移阴，揽衣起、春帷睡足。\n临宝鉴，绿云撩乱，未妆束。\n蝶粉蜂黄都褪了，枕痕一线红生肉。\n背画栏、脉脉悄无言，寻棋局。\n重会面，犹未卜。\n无限事，萦心曲。\n想秦筝依旧，尚鸣金屋。\n芳草连天迷远望，宝香熏被成孤宿。\n最苦是、蝴蝶满园飞，无人扑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4370, '瑞鹤仙', '周邦彦', '悄郊原带郭。\n行路永，客去车尘漠漠。\n斜阳映山落。\n敛馀红、犹恋孤城栏角。\n凌波步弱。\n过短亭、何用素约。\n有流莺劝我，重解绣鞍，缓引春酌。\n不记归时早暮，上马谁扶，醒眠朱阁。\n惊飙动幕。\n扶残醉，绕红药。\n叹西园、已是花深无地，东风何事又恶。\n任流光过却。\n犹喜洞天自乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4371, '西平乐', '周邦彦', '稚柳苏晴，故溪歇雨，川迥未觉春赊。\n驼褐寒侵，正怜初日，轻阴抵死须遮。\n叹事逐孤鸿尽去，身与塘蒲共晚，争知向此，征途迢递，伫立尘沙。\n追念朱颜翠发，曾到处、故地使人嗟。\n道连三楚，天低四野，乔木依前，临路斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4372, '浪涛沙・浪淘沙', '周邦彦', '昼阴重，霜凋岸草，雾隐城堞。\n南陌脂车待发。\n东门帐饮乍阕。\n正拂面垂杨堪缆结。\n掩红泪、玉手亲折。\n念汉浦离鸿去何许，经时信音绝。\n情切。\n望中地远天阔。\n向露冷风清，无人处、耿耿寒漏咽。\n嗟万事难忘，唯是轻别。\n翠尊未竭。\n凭断云留取，西楼残月。\n罗带光销纹衾叠。\n连环解、旧香顿歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4373, '忆旧游', '周邦彦', '记愁横浅黛，泪洗红铅，门掩秋宵。\n坠叶惊离思，听寒蜇夜泣，乱雨潇潇。\n凤钗半脱云鬓，窗影烛光摇。\n渐暗竹敲凉，疏荧照晚，两地魂销。\n迢迢。\n问音信，道径底花阴，时认鸣镳。\n也拟临朱户，叹因郎憔悴，羞见郎招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4374, '蓦山溪', '周邦彦', '湖平春水，菱荇萦船尾。\n空翠入衣襟，拊轻、游鱼惊避。\n晚来潮上，迤逦没沙痕，山四倚。\n云渐起。\n鸟度屏风里。\n周郎逸兴，黄帽侵云水。\n落日媚沧洲，泛一棹、夷犹未已。\n玉箫金管，不共美人游，因个甚，烟雾底。\n独爱莼羹美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4375, '少年游', '周邦彦', '南都石黛扫晴山。\n衣薄耐朝寒。\n一夕东风，海棠花谢，楼上卷帘看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4376, '少年游', '周邦彦', '朝云漠漠散轻丝。\n楼阁淡春姿。\n柳泣花啼，九街泥重，门外燕飞迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4377, '秋蕊香', '周邦彦', '乳鸭池塘水暖。\n风紧柳花迎面。\n午妆粉指印窗眼。\n曲里长眉翠浅。\n问知社日停针线。\n探新燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4378, '渔家傲', '周邦彦', '灰暖香融销永昼。\n蒲萄架上春藤秀。\n曲角栏干群雀斗。\n清明後。\n风梳万缕亭前柳。\n日照钗梁光欲溜。\n循阶竹粉沾衣袖。\n拂拂面红如著酒。\n沈吟久。\n昨宵正是来时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4379, '渔家傲', '周邦彦', '几日轻阴寒测测。\n东风急处花成积。\n醉踏阳春怀故国。\n归未得。\n黄鹂久住如相识。\n赖有蛾眉能暖客。\n长歌屡劝金杯侧。\n歌罢月痕来照席。\n贪欢适。\n帘前重露成涓滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4380, '南乡子', '周邦彦', '晨色动妆楼。\n短烛荧荧悄未收。\n自在开帘风不定，飕飕。\n池面冰澌趁水流。\n早起怯梳头。\n欲绾云鬟又却休。\n不会沈吟思底事，凝眸。\n两点春山满镜愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4381, '望江南・忆江南', '周邦彦', '游妓散，独自绕回堤。\n芳草怀烟迷水曲，密云衔雨暗城西。\n九陌未沾泥。\n桃李下，春晚未成蹊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4382, '浣溪沙', '周邦彦', '争挽桐花两鬓垂。\n小妆弄影照清池。\n出帘踏袜趁蜂儿。\n跳脱添金双腕重，琵琶拨尽四弦悲。\n夜寒谁肯剪春衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4383, '浣溪沙', '周邦彦', '雨过残红湿未飞。\n珠帘一行透斜晖。\n游蜂酿蜜窃香归。\n金屋无人风竹乱，衣篝尽日水沈微。\n一春须有忆人时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4384, '浣溪沙', '周邦彦', '楼上晴天碧四垂。\n楼前芳草接天涯。\n劝君莫上最高梯。\n新笋已成堂下竹，落花都上燕巢泥。\n忍听林表杜鹃啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4385, '迎春乐', '周邦彦', '清池小圃开云屋。\n结春伴、往来熟。\n忆年时，纵酒杯行速。\n看月上、归禽宿。\n墙里修篁森似束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4386, '迎春乐', '周邦彦', '桃蹊柳曲闲踪迹。\n俱曾是、大堤客。\n解春衣、贳酒城南陌。\n频醉卧、胡姬侧。\n鬓点吴霜嗟早白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4387, '点绛唇', '周邦彦', '台上披襟，快风一瞬收残雨。\n柳丝轻举。\n蛛网粘飞絮。\n极目平芜，应是春归处。\n愁凝伫。\n楚歌声苦。\n村落黄昏鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4388, '一落索', '周邦彦', '眉共春山争秀。\n可怜长皱。\n莫将清泪湿花枝，恐花也、如人瘦。\n清润玉箫闲久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4389, '一落索', '周邦彦', '杜宇思归声苦。\n和春催去。\n倚阑一霎酒旗风，任扑面、桃花雨。\n目断陇云江树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4390, '垂丝钓', '周邦彦', '缕金翠羽。\n妆成才见眉妩。\n倦倚绣帘，看舞风絮。\n愁几许。\n寄凤丝雁柱。\n春将暮。\n向层城苑路。\n钿车似水，时时花径相遇。\n旧游伴侣。\n还到曾来处。\n门掩风和雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4391, '满庭芳', '周邦彦', '风老莺雏，雨肥梅子，午阴嘉树清圆。\n地卑山近，衣润费垆烟。\n人静乌鸢自乐，小桥外、新绿溅溅。\n凭栏久，黄芦苦竹，拟泛九江船。\n年年。\n如社燕，飘流瀚海，来寄修椽。\n且莫思身外，长近尊前。\n憔悴江南倦客，不堪听、急管繁弦。\n歌筵畔，先安簟枕，容我醉时眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4392, '隔浦莲・隔浦莲近拍', '周邦彦', '新篁摇动翠葆。\n曲径通深窈。\n夏果收新脆，金丸落、惊飞鸟。\n浓霭迷岸草。\n蛙声闹。\n骤雨鸣池沼。\n水亭小。\n浮萍破处，帘花檐影颠倒。\n纶巾羽扇，困卧北窗清晓。\n屏里吴山梦自到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4393, '法曲献仙音', '周邦彦', '蝉咽凉柯，燕飞尘幕，漏阁签声时度。\n倦脱纶巾，困便湘竹，桐阴半侵朱户。\n向抱影凝情处。\n时闻打窗雨。\n耿无语。\n叹文圆、近来多病，情绪懒，尊酒易成间阻。\n缥缈玉京人，想依然、京兆眉妩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4394, '过秦楼', '周邦彦', '水浴清蟾，叶喧凉吹，巷陌马声初断。\n闲依露井，笑扑流萤，惹破画罗轻扇。\n人静夜久凭阑，愁不归眠，立残更箭。\n叹年华一瞬，人今千里，梦沈书远。\n空见说、鬓怯琼梳，容销金镜，渐懒趁时匀染。\n梅风地溽，虹雨苔滋，一架舞红都变。\n谁信无，为伊才减江淹，情伤荀倩。\n但明河影下，还看稀星数点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4395, '侧犯', '周邦彦', '暮霞霁雨，小莲出水红妆靓。\n风定。\n看步袜江妃照明镜。\n飞萤度暗草，秉烛游花径。\n人静。\n携艳质、追凉就槐影。\n金环皓腕，雪藕清泉莹。\n谁念省。\n满身香、犹是旧荀令。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4396, '塞翁吟', '周邦彦', '暗叶啼风雨，窗外晓色珑。\n散水麝，小池东。\n乱一岸芙蓉。\n蕲州簟展双纹浪，轻帐翠缕如空。\n梦念远别、泪痕重。\n淡铅脸斜红。\n忡忡。\n嗟憔悴、新宽带结，羞艳冶、都销镜中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4397, '苏幕遮', '周邦彦', '燎沈香，消溽暑。\n鸟雀呼晴，侵晓窥檐语。\n叶上初阳乾宿雨，水面清圆，一一风荷举。\n故乡遥，何日去。\n家住吴门，久作长安旅。\n五月渔郎相忆否。\n小楫轻舟，梦入芙蓉浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4398, '浣溪沙', '周邦彦', '日射红蜡蒂香。\n风乾微汗粉襟凉。\n碧纱对掩簟纹光。\n自剪柳枝明画阁，戏抛莲种横塘。\n长亭无事好思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4399, '浣溪沙', '周邦彦', '翠葆参差竹径成。\n新荷跳雨泪珠倾。\n曲阑斜转小池亭。\n风约帘衣归燕急，水摇扇影戏鱼惊。\n柳梢残日弄微晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4400, '浣溪沙', '周邦彦', '薄薄纱橱望似空。\n簟纹如水浸芙蓉。\n起来娇眼未惺惚。\n强整罗衣抬皓腕，更将纨扇掩酥胸。\n羞郎何事面微红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4401, '浣溪沙', '周邦彦', '宝扇轻圆浅画缯。\n象床平稳细穿藤。\n飞蝇不到避壶冰。\n翠枕面凉频忆睡，玉箫手汗错成声。\n日长无力要人凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4402, '点绛唇', '周邦彦', '征骑初停，酒行莫放离歌举。\n柳汀莲浦。\n看尽江南路。\n苦恨斜阳，冉冉催人去。\n空回顾。\n淡烟横素。\n不见扬鞭处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4403, '诉衷情', '周邦彦', '出林杏子落金盘。\n齿软怕尝酸。\n可惜半残青紫，犹有小唇丹。\n南陌上，落花闲。\n雨斑斑。\n不言不语，一段伤春，都在眉间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4404, '风流子', '周邦彦', '枫林凋晚叶，关河迥，楚客惨将归。\n望一川暝霭，雁声哀怨，半规凉月，人影参差。\n酒醒後，泪花销凤蜡，风幕卷金泥。\n砧杵韵高，唤回残梦，绮罗香减，牵起馀悲。\n亭皋分襟地，难拚处、偏是掩面牵衣。\n何况怨怀长结，重见无期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4405, '华胥引', '周邦彦', '川原澄映，烟月冥，去舟如叶。\n岸足沙平，蒲根水冷留雁唼。\n别有孤角吟秋，对晓风呜轧。\n红日三竿，醉头扶起还怯。\n离思相萦，渐看看、鬓丝堪镊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4406, '宴清都', '周邦彦', '地僻无锺鼓。\n残灯灭，夜长人倦难度。\n寒吹断梗，风翻暗雪，洒窗填户。\n宾鸿谩说传书，算过尽、千俦万侣。\n始信得、庾信愁多，江淹恨极须赋。\n凄凉病损文园，徽弦乍拂，音韵先苦。\n淮山夜月，金城暮草，梦魂飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4407, '四园竹', '周邦彦', '浮云护月，未放满朱扉。\n鼠摇暗壁，萤度破窗，偷入书帏。\n秋意浓，闲伫立、庭柯影里。\n好风襟袖先知。\n夜何其。\n江南路绕重山，心知谩与前期。\n奈向灯前堕泪，肠断萧娘，旧日书辞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4408, '齐天乐', '周邦彦', '绿芜凋尽台城路，殊乡又逢秋晚。\n暮雨生寒，鸣蛩劝织，深阁时闻裁剪。\n云窗静掩。\n叹重拂罗，顿疏花簟。\n尚有囊，露萤清夜照书卷。\n荆江留滞最久，故人相望处，离思何限。\n渭水西风，长安乱叶，空忆诗情宛转。\n凭高眺远。\n正玉液新，蟹螯初荐。\n醉倒山翁，但愁斜照敛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4409, '木兰花・玉楼春', '周邦彦', '郊原雨过金英秀。\n风扫霜威寒入袖。\n感君一曲断肠歌，劝我十分和泪酒。\n古道尘清榆柳瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4410, '霜叶飞', '周邦彦', '露迷衰草。\n疏星挂，凉蟾低下林表。\n素娥青女斗婵娟，正倍添凄悄。\n渐飒飒、丹枫撼晓。\n横天云浪鱼鳞小。\n似故人相看，又透入、清辉半饷，特地留照。\n迢递望极关山，波穿千里，度日如岁难到。\n凤楼今夜听秋风，奈五更愁抱。\n想玉匣、哀弦闭了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4411, '蕙兰芳引', '周邦彦', '寒莹晚空，点清镜、断霞孤鹜。\n对客馆深扃，霜草未衰更绿。\n倦游厌旅，但梦绕、阿娇金屋。\n想故人别後，尽日空疑风竹。\n塞北氍毹，江南图障，是处温燠。\n更花管云笺，犹写寄情旧曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4412, '塞垣春', '周邦彦', '暮色分平野。\n傍苇岸、征帆卸。\n烟村极浦，树藏孤馆，秋景如画。\n渐别离气味难禁也。\n更物象、供潇洒。\n念多材浑衰减，一怀幽恨难写。\n追念绮窗人，天然自、风韵娴雅。\n竟夕起相思，谩嗟怨遥夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4413, '丁香结', '周邦彦', '苍藓沿阶，冷萤粘屋，庭树望秋先陨。\n渐雨凄风迅。\n澹暮色，倍觉园林清润。\n汉姬纨扇在，重吟玩、弃掷未忍。\n登山临水，此恨自古，销磨不尽。\n牵引。\n记试酒归时，映月同看雁阵。\n宝幄香缨，熏炉象尺，夜寒灯晕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4414, '氐州第一', '周邦彦', '波落寒汀，村渡向晚，遥看数点帆小。\n乱叶翻鸦，惊风破雁，天角孤云缥缈。\n官柳萧疏，甚尚挂、微微残照。\n景物关情，川途换目，顿来催老。\n渐解狂朋欢意少。\n奈犹被、思牵情绕。\n座上琴心，机中锦字，觉最萦怀抱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4415, '解蹀躞', '周邦彦', '候馆丹枫吹尽，面旋随风舞。\n夜寒霜月，飞来伴孤旅。\n还是独拥秋衾，梦馀酒困都醒，满怀离苦。\n甚情绪。\n深念凌波微步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4416, '少年游', '周邦彦', '并刀如水，吴盐胜雪，纤手破新橙。\n锦幄初温，兽烟不断，相对坐调笙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4417, '庆春宫・高阳台', '周邦彦', '云接平冈，山围寒野，路回渐转孤城。\n衰柳啼鸦，惊风驱雁，动人一片秋声。\n倦途休驾，澹烟里、微茫见星。\n尘埃憔悴，生怕黄昏，离思牵萦。\n华堂旧日逢迎。\n花艳参差，香雾飘零。\n弦管当头，偏怜娇凤，夜深簧暖笙清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4418, '醉桃源・阮郎归', '周邦彦', '冬衣初染远山青。\n双丝云雁绫。\n夜寒袖湿欲成冰。\n都缘珠泪零。\n情黯黯，闷腾腾。\n身如秋後蝇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4419, '醉桃源・阮郎归', '周邦彦', '菖蒲叶老水平沙。\n临流苏小家。\n画阑曲径宛秋蛇。\n金英垂露华。\n烧蜜炬，引莲娃。\n酒香薰脸霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4420, '点绛唇', '周邦彦', '孤馆迢迢，暮天草露沾衣润。\n夜来秋近。\n月晕通风信。\n今日原头，黄叶飞成阵。\n知人闷。\n故来相趁。\n共结临岐恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4421, '夜游宫', '周邦彦', '叶下斜阳照水。\n卷轻浪、沈沈千里。\n桥上酸风射眸子。\n立多时，看黄昏，灯火市。\n古屋寒窗底。\n听几片、井桐飞坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4422, '夜游宫', '周邦彦', '客去车尘未敛。\n古帘暗、雨苔千点。\n月皎风清在处见。\n奈今宵，照初弦，吹一箭。\n池曲河声转。\n念归计，眼迷魂乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4423, '诉衷情', '周邦彦', '堤前亭午未融霜。\n风紧雁无行。\n重寻旧日岐路，茸帽北游装。\n期信杳，别离长。\n远情伤。\n风翻酒幔，寒凝茶烟，又是何乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4424, '伤情怨・清商怨', '周邦彦', '枝头风势渐小。\n看暮鸦飞了。\n又是黄昏，闭门收返照。\n江南人去路缈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4425, '红林擒近', '周邦彦', '高柳春才软，冻梅寒更香。\n暮雪助清峭，玉尘散林塘。\n那堪飘风递冷，故遣度幕穿窗。\n似欲料理新妆。\n呵手弄丝簧。\n冷落词赋客，萧索水云乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4426, '红林擒近', '周邦彦', '风雪惊初霁，水乡增暮寒。\n树杪坠飞羽，檐牙挂琅。\n才喜门堆巷积，可惜迤逦销残。\n渐看低竹翩翻。\n清池涨微澜。\n步屐晴正好，宴席晚方欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4427, '满路花・促拍满路花', '周邦彦', '金花落烬灯，银砾鸣窗雪。\n夜深微漏断，行人绝。\n风扉不定，竹圃琅折。\n玉人新间阔。\n著甚情，更当恁地时节。\n无言枕，帐底流清血。\n愁如春後絮，来相接。\n知他那里，争信人心切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4428, '解语花', '周邦彦', '风销焰蜡，露烘炉。\n花市光相射。\n桂华流瓦。\n纤云散，耿耿素娥欲下。\n衣裳淡雅。\n看楚女、纤腰一把。\n箫鼓喧，人影参差，满路飘香麝。\n因念都城放夜。\n望千门如昼，嬉笑游冶。\n钿车罗帕。\n相逢处，自有暗尘随马。\n年光是也。\n唯只见、旧情衰谢。\n清漏移，飞盖归来，从舞休歌罢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4429, '六么令', '周邦彦', '快风收雨，亭馆清残燠。\n池光静横秋影，岸柳如新沐。\n闻道宜城酒美，昨日新醅熟。\n轻镳相逐。\n冲泥策马，来折东篱半开菊。\n华堂花艳对列，一一惊郎目。\n歌韵巧共泉声，间杂琮玉。\n惆怅周郎已老，莫唱当时曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4430, '倒犯', '周邦彦', '霁景、对霜蟾乍升，素烟如扫。\n千林夜缟。\n徘徊处、渐移深窈。\n何人正弄，孤影蹁跹，西窗悄。\n冒霜冷貂裘，玉邀云表。\n共寒光、饮清。\n淮左旧游，记送行人，归来山路。\n驻马望素魄，印遥碧、金枢小。\n爱秀色、初娟好。\n念漂浮、绵绵思远道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4431, '大', '周邦彦', '对宿烟收，春禽静，飞雨时鸣高屋。\n墙头青玉旆，洗铅霜都尽，嫩梢相触。\n润逼琴丝，寒侵枕障，虫网吹沾帘竹。\n邮亭无人处，听檐声不断，困眠初熟。\n奈愁极顿惊，梦轻难记，自怜幽独。\n行人归意速。\n最先念、流潦妨车毂。\n怎奈向、兰成憔悴，卫清羸，等闲时、易伤心目。\n未怪平阳客，双泪落、笛中哀曲。\n况萧索、青芜国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4432, '玉烛新', '周邦彦', '溪源新腊後。\n见数朵江梅，剪裁初就。\n晕酥砌玉芳英嫩，故把春心轻漏。\n前村昨夜，想弄月、黄昏时候。\n孤岸峭，疏影横斜，浓香暗沾襟袖。\n尊前赋与多材，问岭外风光，故人知否。\n寿阳谩斗。\n终不似，照水一枝清瘦。\n风娇雨秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4433, '花犯', '周邦彦', '粉墙低，梅花照眼，依然旧风味。\n露痕轻缀。\n疑净洗铅华，无限佳丽。\n去年胜赏曾孤倚。\n冰盘同宴喜。\n更可惜，雪中高树，香篝熏素被。\n今年对花最匆匆，相逢似有恨，依依愁悴。\n吟望久，青苔上、旋看飞坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4434, '丑奴儿・采桑子', '周邦彦', '肌肤绰约真仙子，来伴冰霜。\n洗尽铅黄。\n素面初无一点妆。\n寻花不用持银烛，暗里闻香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4435, '水龙吟', '周邦彦', '素肌应怯馀寒，艳阳占立青芜地。\n樊川照日，灵关遮路，残红敛避。\n传火楼台，妒花风雨，长门深闭。\n亚帘栊半湿，一枝在手，偏勾引、黄昏泪。\n别有风前月底。\n布繁英、满圆歌吹。\n朱铅退尽，潘妃却酒，昭君乍起。\n雪浪翻空，粉裳缟夜，不成春意。\n恨玉容不见，琼英谩好，与何人比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4436, '六丑', '周邦彦', '正单衣试酒，恨客里、光阴虚掷。\n愿春暂留，春归如过翼。\n一去无迹。\n为问花何在，夜来风雨，葬楚宫倾国。\n钗钿堕处遗香泽。\n乱点桃蹊，轻翻柳陌。\n多情为谁追惜。\n但蜂媒蝶使，时叩窗隔。\n东园岑寂。\n渐蒙笼暗碧。\n静绕珍丛底，成叹息。\n长条故惹行客。\n似牵衣待话，别情无极。\n残英小、强簪巾帻。\n终不似一朵，钗头颤袅，向人侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4437, '虞美人', '周邦彦', '金闺平帖春云暖。\n昼漏花前短。\n玉颜酒解艳红消。\n一面捧心啼困、不成娇。\n别来新翠迷行径。\n窗锁玲珑影。\n砑绫小字夜来封。\n斜倚曲栏凝睇、数归鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4438, '虞美人', '周邦彦', '廉纤小雨池塘遍。\n细点看萍面。\n一双燕子守朱门。\n比似寻常时候、易黄昏。\n宜城酒泛浮香絮。\n细作更阑语。\n相将羁思乱如云。\n又是一窗灯影、两愁人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4439, '兰陵王', '周邦彦', '柳阴直。\n烟里丝丝弄碧。\n隋堤上、曾见几番，拂水飘绵送行色。\n登临望故国。\n谁识。\n京华倦客。\n长亭路，年去岁来，应折柔条过千尺。\n闲寻旧踪迹。\n又酒趁哀弦，灯照离席。\n梨花榆火催寒食。\n愁一箭风快，半篙波暖，回头迢递便数驿。\n望人在天北。\n凄恻。\n恨堆积。\n渐别浦萦回，津堠岑寂。\n斜阳冉冉春无极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4440, '蝶恋花', '周邦彦', '爱日轻明新雪後。\n柳眼星星，渐欲穿窗牖。\n不待长亭倾别酒。\n一枝已入骚人手。\n浅浅蓝轻蜡透。\n过尽冰霜，便与春争秀。\n强对青铜簪白首。\n老来风味难依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4441, '蝶恋花', '周邦彦', '桃萼新香梅落後。\n暗叶藏鸦，苒苒垂亭牖。\n舞困低迷如著酒。\n乱丝偏近游人手。\n雨过朦胧斜日透。\n客舍青青，特地添明秀。\n莫话扬鞭回别首。\n渭城荒远无交旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4442, '蝶恋花', '周邦彦', '蠢蠢黄金初脱後。\n暖日飞绵，取次粘窗牖。\n不见长条低拂酒。\n赠行应已输先手。\n莺掷金梭飞不透。\n小榭危楼，处处添奇秀。\n何日隋堤萦马首。\n路长人倦空思旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4443, '蝶恋花', '周邦彦', '小阁阴阴人寂後。\n翠幕褰风，烛影摇疏牖。\n夜半霜寒初索酒。\n金刀正在柔荑手。\n彩薄粉轻光欲透。\n小叶尖新，未放双眉秀。\n记得长条垂首。\n别离情味还依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4444, '西河', '周邦彦', '佳丽地。\n南朝盛事谁记。\n山围故国绕清江，髻鬟对起。\n怒涛寂寞打孤城，风樯遥度天际。\n断崖树，犹倒倚。\n莫愁艇子曾系。\n空馀旧迹郁苍苍，雾沈半垒。\n夜深月过女墙来，赏心东望淮水。\n酒旗戏鼓甚处市。\n想依稀、王谢邻里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4445, '归去难・促拍满路花', '周邦彦', '佳约人未知，背地伊先变。\n恶会称停事，看深浅。\n如今信我，委的论长远。\n好来无可怨。\n洎合教伊，因些事後分散。\n密意都休，待说先肠断。\n此恨除非是，天相念。\n坚心更守，未死终相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4446, '三部乐', '周邦彦', '浮玉飞琼，向邃馆静轩，倍增清绝。\n夜窗垂练，何用交光明月。\n近闻道、官阁多梅，趁暗香未远，冻蕊初发。\n倩谁摘取，寄赠情人桃叶。\n回文近传锦字，道为君瘦损，是人都说。\n祆知染红著手，胶梳粘发。\n转思量、镇长堕睫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4447, '菩萨蛮', '周邦彦', '银河宛转三千曲。\n浴凫飞鹭澄波绿。\n何处是归舟。\n夕阳江上楼。\n天憎梅浪发。\n故下封枝雪。\n深院卷帘看。\n应怜江上寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4448, '品令', '周邦彦', '夜阑人静。\n月痕寄、梅梢疏影。\n帘外曲角栏干近。\n旧携手处，花发雾寒成阵。\n应是不禁愁与恨。\n纵相逢难问。\n黛眉曾把春衫印。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4449, '玉楼春', '周邦彦', '玉琴虚下伤心泪。\n只有文君知曲意。\n帘烘楼迥月宜人，酒暖香融春有味。\n萋萋芳草迷千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4450, '黄鹂绕碧树', '周邦彦', '双阙笼嘉气，寒威日晚，岁华将暮。\n小院闲庭，对寒梅照雪，淡烟凝素。\n忍当迅景，动无限、伤春情绪。\n犹赖是、上苑风光渐好，芳容将煦。\n草荚兰芽渐吐。\n且寻芳、更休思虑。\n这浮世、甚驱驰利禄，奔竞尘土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4451, '满路花・促拍满路花', '周邦彦', '帘烘泪雨乾，酒压愁城破。\n冰壶防饮渴，培残火。\n朱消粉退，绝胜新梳裹。\n不是寒宵短，日上三竿，人犹要同卧。\n如今多病，寂寞章台左。\n黄昏风弄雪，门深锁。\n兰房密爱，万种思量过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4452, '绮寮怨', '周邦彦', '上马人扶残醉，晓风吹未醒。\n映水曲、翠瓦朱檐，垂杨里、乍见津亭。\n当时曾题败壁，蛛丝罩、淡墨苔晕青。\n念去来、岁月如流，徘徊久、叹息愁思盈。\n去去倦寻路程。\n江陵旧事，何曾再问杨琼。\n旧曲凄清。\n敛愁黛、与谁听。\n尊前故人如在，想念我、最关情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4453, '拜星月・拜星月慢', '周邦彦', '夜色催更，清尘收露，小曲幽坊月暗。\n竹槛灯窗，识秋娘庭院。\n笑相遇，似觉琼枝玉树，暖日明霞光烂。\n水眄兰情，总平生稀见。\n画图中、旧识春风面。\n谁知道、自到瑶台畔。\n眷恋雨润云温，苦惊风吹散。\n念荒寒、寄宿无人馆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4454, '尉迟杯', '周邦彦', '隋堤路。\n渐日晚、密霭生深树。\n阴阴淡月笼沙，还宿河桥深处。\n无情画舸，都不管、烟波隔南浦。\n等行人、醉拥重衾，载将离恨归去。\n因念旧客京华，长偎傍、疏林小槛欢聚。\n冶叶倡条俱相识，仍惯见、珠歌翠舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4455, '绕佛阁', '周邦彦', '暗尘四敛。\n楼观迥出，高映孤馆。\n清漏将短。\n厌闻夜久，签声动书幔。\n桂华又满。\n闲步露草，偏爱幽远。\n花气清婉，望中迤逦，城阴度河岸。\n倦客最萧索，醉倚斜桥穿柳线。\n还似汴堤，虹梁横水面。\n看浪春灯，舟下如箭。\n此行重见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4456, '一寸金', '周邦彦', '州夹苍崖，下枕江山是城郭。\n望海霞接日，红翻水面，晴风吹草，青摇山脚。\n波暖凫作。\n沙痕退、夜潮正落。\n疏林外、一点炊烟，渡口参差正寥廓。\n自叹劳生，经年何事，京华信漂泊。\n念渚蒲汀柳，空归闲梦，风轮雨楫，终辜前约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4457, '蝶恋花', '周邦彦', '月皎惊乌栖不定。\n更漏将残，辘，牵金井。\n唤起两眸清炯炯。\n泪花落枕红棉泠。\n执手霜风吹鬓影。\n去意徊徨，别语愁难听。\n楼上阑干横斗柄。\n露寒人远鸡相应。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4458, '如梦令', '周邦彦', '尘满一文绣。\n泪湿领巾红皱。\n初暖绮罗轻，腰胜武昌官柳。\n长昼。\n长昼。\n困卧午窗中酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4459, '如梦令', '周邦彦', '门外迢迢行路。\n谁送郎边尺素。\n巷陌雨馀风，当面湿花飞去。\n无绪。\n无绪。\n闲处偷垂玉箸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4460, '月中行・月宫春', '周邦彦', '蜀丝趁日染乾红。\n微暖面脂融。\n博山细篆霭房栊。\n静看打窗虫。\n愁多胆怯疑虚幕，声不断、暮景疏钟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4461, '浣沙溪・浣溪沙', '周邦彦', '日薄尘飞官路平。\n眼前喜见汴河倾。\n地遥人倦莫兼程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4462, '浣沙溪・浣溪沙', '周邦彦', '贪向津亭拥去车。\n不辞泥雨溅罗襦。\n泪多脂粉了无馀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4463, '浣沙溪・浣溪沙', '周邦彦', '不为萧娘旧约寒。\n何因容易别长安。\n预愁衣上粉痕乾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4464, '点绛唇', '周邦彦', '辽鹤归来，故乡多少伤心地。\n寸书不寄。\n鱼浪空千里。\n凭仗桃根，说与凄凉意。\n愁无际。\n旧时衣袂。\n犹有东门泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4465, '少年游', '周邦彦', '檐牙缥缈小倡楼。\n凉月挂银钩。\n聒席笙歌，透帘灯火，风景似扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4466, '望江南・忆江南', '周邦彦', '歌席上，无赖是横波。\n宝髻玲珑玉燕，绣巾柔腻掩香罗。\n人好自宜多。\n无个事，因甚敛双蛾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4467, '意难忘', '周邦彦', '衣染莺黄。\n爱停歌驻拍，劝酒持觞。\n低鬟蝉影动，私语口脂香。\n檐露滴，竹风凉。\n拚剧饮淋浪。\n夜渐深，笼灯就月，子细端相。\n知音见说无双。\n解移宫换羽，未怕周郎。\n长颦知有恨，贪耍不成妆。\n些个事，恼人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4468, '迎春乐', '周邦彦', '人人花艳明春柳。\n忆筵上、偷携手。\n趁歌停舞罢来相就。\n醒醒个、无些酒。\n比目香囊新刺绣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4469, '定风波', '周邦彦', '莫倚能歌敛黛眉。\n此歌能有几人知。\n他日相逢花月底。\n重理。\n好声须记得来时。\n苦恨城头更漏永，无情岂解惜分飞。\n休诉金尊推玉臂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4470, '红罗袄', '周邦彦', '画烛寻欢去，羸马载愁归。\n念取酒东垆，尊虽近，采花南浦，蜂蝶须知。\n自分袂、天阔鸿稀。\n空怀梦约心期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4471, '玉楼春', '周邦彦', '当时携手城东道。\n月堕檐牙人睡了。\n酒边难使客愁惊，帐底不教春梦到。\n别来人事如秋草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4472, '玉楼春', '周邦彦', '大堤花艳惊郎目。\n秀色华看不足。\n休将宝瑟写幽怀，座上有人能顾曲。\n平波落照涵玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4473, '玉楼春', '周邦彦', '玉奁收起新妆了。\n鬓畔斜枝红袅袅。\n浅颦轻笑百般宜，试著春衫犹更好。\n裁金簇翠天机巧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4474, '玉楼春', '周邦彦', '桃溪不作从容住。\n秋藕绝来无续处。\n当时相候赤栏桥，今日独寻黄叶路。\n烟中列岫青无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4475, '夜飞鹊・夜飞鹊慢', '周邦彦', '河桥送人处，凉夜何其。\n斜月远堕馀辉。\n铜盘烛泪已流尽，霏霏凉露沾衣。\n相将散离会，探风前津鼓，树杪参旗。\n华骢会意，纵扬鞭、亦自行迟。\n迢递路回清野，人语渐无闻，空带愁归。\n何意重红满地，遗钿不见，斜径都迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4476, '早梅芳・喜迁莺', '周邦彦', '花竹深，房栊好。\n夜阒无人到。\n隔窗寒雨，向壁孤灯弄馀照。\n泪多罗袖重，意密莺声小。\n正魂惊梦怯，门外已知晓。\n去难留，话未了。\n早促登长道。\n风披宿雾，露洗初阳射林表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4477, '早梅芳・喜迁莺', '周邦彦', '缭墙深，丛竹绕。\n宴席临清沼。\n微呈纤履，故隐烘帘自嬉笑。\n粉香妆晕薄，带紧腰围小。\n看鸿惊凤翥，满座叹轻妙。\n酒醒时，会散了。\n回首城南道。\n河阴高转，露脚斜飞夜将晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4478, '凤来朝', '周邦彦', '逗晓看娇面。\n小窗深、弄明未遍。\n爱残朱宿粉云鬟乱。\n最好是、帐中见。\n说梦双蛾微敛。\n锦衾温、酒香未断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4479, '芳草渡・系裙腰', '周邦彦', '昨夜里，又再宿桃源，醉邀仙侣。\n听碧窗风快，珠帘半卷疏雨。\n多少离恨苦。\n方留连啼诉。\n凤帐晓，又是匆匆，独自归去。\n愁睹。\n满怀泪粉，瘦马冲泥寻去路。\n谩回首、烟迷望眼，依稀见朱户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4480, '感皇恩', '周邦彦', '露柳好风标，娇莺能语。\n独占春光最多处。\n浅颦轻笑，未肯等闲分付。\n为谁心子里，长长苦。\n洞房见说，云深无路。\n凭仗青鸾道情素。\n酒空歌断，又被涛江催去。\n怎奈向、言不尽，愁无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4481, '虞美人', '周邦彦', '灯前欲去仍留恋。\n肠断朱扉远。\n未须红雨洗香腮。\n待得蔷薇花谢、便归来。\n舞腰歌版闲时按。\n一任傍人看。\n金炉应见旧残煤。\n莫使恩情容易、似寒灰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4482, '虞美人', '周邦彦', '疏篱曲径田家小。\n云树开清晓。\n天寒山色有无中。\n野外一声钟起、送孤蓬。\n添衣策马寻亭堠。\n愁抱惟宜酒。\n菰蒲睡鸭占陂塘。\n纵被行人惊散、又成双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4483, '虞美人', '周邦彦', '玉觞才掩朱弦悄。\n弹指壶天晓。\n回头犹认倚墙花。\n只向小桥南畔、便天涯。\n银蟾依旧当窗满。\n顾影魂先断。\n凄风休半残灯。\n拟倩今宵归梦、到云屏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4484, '玉团儿', '周邦彦', '铅华淡伫新妆束。\n好风韵、天然异俗。\n彼此知名，虽然初见，情分先熟。\n垆烟淡淡云屏曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4485, '玉团儿', '周邦彦', '妍姿艳态腰如束。\n笑无限、桃粗杏俗。\n玉体横陈，云鬟斜坠，春睡还熟。\n夕阳斗转阑干曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4486, '粉蝶儿慢', '周邦彦', '宿雾藏春，馀寒带雨，占得群芳开晚。\n艳初弄秀，倚东风娇懒。\n隔叶黄鹂传好音，唤入深丛中探。\n数枝新，比昨朝、又早红稀香浅。\n眷恋。\n重来倚槛。\n当韶华、未可轻辜双眼。\n赏心随分乐，有清尊檀板。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4487, '红窗迥', '周邦彦', '几日来、真个醉。\n不知道、窗外乱红，已深半指。\n花影被风摇碎。\n拥春酲乍起。\n有个人人，生得济楚，来向耳畔，问道今朝醒未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4488, '念奴娇', '周邦彦', '醉魂乍醒，听一声啼鸟，幽斋岑寂。\n淡日朦胧初破晓，满眼娇晴天色。\n最惜香梅，凌寒偷绽，漏泄春消息。\n池塘芳草，又还淑景催逼。\n因念旧日芳菲，桃花永巷，恰似初相识。\n荏苒时光，因惯却、觅雨寻云踪迹。\n奈有离拆，瑶台月下，回首频思忆。\n重愁叠恨，万般都在胸臆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4489, '燕归梁', '周邦彦', '帘底新霜一夜浓。\n短烛散飞虫。\n曾经洛浦见惊鸿。\n关山隔、梦魂通。\n明星晃晃，回津路转，榆影步花骢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4490, '南浦', '周邦彦', '浅带一帆风，向晚来、扁舟稳下南浦。\n迢递阻潇湘，衡皋迥，斜舣蕙兰汀渚。\n危樯影里，断云点点遥天暮。\n菡萏里风，偷送清香，时时微度。\n吾家旧有簪缨，甚顿作天涯，经岁羁旅。\n羌管怎知情，烟波上，黄昏万斛愁绪。\n无言对月，皓彩千里人何处。\n恨无凤翼身，只待而今，飞将归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4491, '醉落魄・一斛珠', '周邦彦', '葺金细弱。\n秋风嫩、桂花初著。\n蕊珠宫里人难学。\n花染娇荑，羞映翠云幄。\n清香不与兰荪弱。\n一枝云鬓巧梳掠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4492, '留客住', '周邦彦', '嗟乌兔。\n正茫茫、相催无定，只恁东生西没，半均寒暑。\n昨见花红柳绿，处处林茂。\n又睹霜前篱畔，菊散馀香，看看又还秋暮。\n忍思虑。\n念古往贤愚，终归何处。\n争似高堂，日夜笙歌齐举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4493, '长相思', '周邦彦', '夜色澄明。\n天街如水，风力微冷帘旌。\n幽期再偶，坐久相看才喜，欲叹还惊。\n醉眼重醒。\n映雕阑修竹，共数流萤。\n细语轻盈。\n尽银台、挂蜡潜听。\n自初识伊来，便惜妖娆艳质，美眄柔情。\n桃溪换世，鸾驭凌空，有愿须成。\n游丝荡絮，任轻狂、相逐牵萦。\n但连环不解，流水长东，难负深盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4494, '看花回', '周邦彦', '秀色芳容明眸，就中奇绝。\n细看艳波欲溜，最可惜微重，红绡轻帖。\n匀朱傅粉，几为严妆时睫。\n因个甚、底死嗔人，半饷斜眄费贴燮。\n斗帐里、浓欢意惬。\n带困眼、似开微合。\n曾倚高楼望远，似指笑频，知他谁说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4495, '看花回', '周邦彦', '蕙风初散轻暖，霁景微澄洁。\n秀蕊乍开乍敛，带雨态烟痕，春思纡结。\n危弦弄响，来去惊人莺语滑。\n无赖处，丽日楼台，乱纷歧路思奇绝。\n何计解，黏花系月。\n叹冷落、顿辜佳节。\n犹有当时气味，挂一缕相思，不断如发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4496, '月下笛', '周邦彦', '小雨收尘，凉蟾莹彻，水光浮璧。\n谁知怨抑。\n静倚官桥吹笛。\n映宫墙、风叶乱飞，品高调侧人未识。\n想开元旧谱，柯亭遗韵，尽传胸臆。\n阑干四绕，听折柳徘徊，数声终拍。\n寒灯陋馆，最感平阳孤客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4497, '无闷', '周邦彦', '云作轻阴，风逗细寒，小溪冰冻初结。\n更听得、悲鸣雁度空阔。\n暮雀喧喧聚竹，听竹上清响风敲雪。\n洞户悄，时见香消翠楼，兽煤红。\n凄切。\n念旧欢聚，旧约至此，方惜轻别。\n又还是、离亭楚梅堪折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4498, '相思引', '周邦彦', '生碧香罗粉兰香。\n冷绡缄泪倩谁将。\n故人何在，烟水隔潇湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4499, '青房并蒂莲', '周邦彦', '醉凝眸。\n正楚天秋晚，远岸云收。\n草绿莲红，□映小汀洲。\n芰荷香里鸳鸯浦，恨菱歌、惊起眠鸥。\n望去帆、一派湖光，棹声咿哑橹声柔。\n愁窥汴堤细柳，曾舞送莺时，锦缆龙舟。\n拥倾国纤腰皓齿，笑倚楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4500, '满庭芳', '周邦彦', '山崦笼春，江城吹雨，暮天烟淡云昏。\n酒旗渔市，冷落杏花村。\n苏小当年秀骨，萦蔓草、空想罗裙。\n潮声起，高楼喷笛，五两了无闻。\n凄凉，怀故国，朝钟暮鼓，十载红尘。\n似梦魂迢递，长到吴门。\n闻道花开陌上，歌旧曲、愁杀王孙。\n何时见、□□唤酒，同倒瓮头春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4501, '满庭芳', '周邦彦', '花扑鞭梢，风吹衫袖，马啼初趁轻装。\n都城渐远，芳树隐斜阳。\n未惯羁游况味，征鞍上、满目凄凉。\n今宵里，三更皓月，愁断九回肠。\n佳人，何处去，别时无计，同引离觞。\n但唯有相思，两处难忘。\n去即十分去也，如何向、千种思量。\n凝眸处，黄昏画角，天远路岐长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4502, '满庭芳', '周邦彦', '白玉楼高，广寒宫阙，暮云如幛褰开。\n银河一派，流出碧天来。\n无数星躔玉李，冰轮动、光满楼台。\n登临处，全胜瀛海，弱水浸蓬莱。\n云鬟，香雾湿，月娥韵压，云冻江梅。\n况餐花饮露，莫惜裴徊。\n坐看人间如掌，山河影、倒入琼杯。\n归来晚，笛声吹彻，九万里尘埃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4503, '青玉案', '周邦彦', '良夜灯光簇如豆。\n占好事、今宵有。\n酒罢歌阑人散後。\n琵琶轻放，语声低颤，灭烛来相就。\n玉体偎人情何厚。\n轻惜轻怜转唧。\n雨散云收眉儿皱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4504, '一剪梅・一翦梅', '周邦彦', '一剪梅花万样娇。\n斜插梅枝，略点眉梢。\n轻盈微笑舞低回，何事尊前拍误招。\n夜渐寒深酒渐消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4505, '鹊桥仙令・鹊桥仙', '周邦彦', '浮花浪蕊，人间无数，开遍朱朱白白。\n瑶池一朵玉芙蓉，秋露洗、丹砂真色。\n晚凉拜月，六铢衣动，应被娥认得。\n翩然欲上广寒宫，横玉度、一声天碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4506, '花心动', '周邦彦', '帘卷青楼，东风暖，杨花乱飘晴昼。\n兰袂褪香，罗帐褰红，绣枕旋移相就。\n海棠花谢春融暖，偎人恁、娇波频溜。\n象床稳，鸳衾谩展，浪翻红绉。\n一夜情浓似酒。\n香汗渍鲛绡，几番微透。\n鸾困凤慵，娅姹双眉，画也画应难就。\n问伊可煞□人厚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4507, '双头莲', '周邦彦', '一抹残霞，几行新雁，天染云断，红迷阵影，隐约望中，点破晚空澄碧。\n助秋色。\n门掩西风，桥横斜照，青翼未来，浓尘自起，咫尺凤帏，合有人相识。\n叹乖隔。\n知甚时恣与，同携欢适。\n度曲传觞，并鞯飞辔，绮陌画堂连夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4508, '大有', '周邦彦', '仙骨清羸，沈腰憔悴，见傍人、惊怪消瘦。\n柳无言，双眉尽日齐斗。\n都缘薄幸赋情浅，许多时、不成欢偶。\n幸自也，总由他，何须负这心口。\n令人恨，行坐儿断了更思量，没心求守。\n前日相逢，又早见伊仍旧。\n却更被温存後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4509, '丑奴儿・采桑子', '周邦彦', '南枝度腊开全少，疏影当轩。\n一种宜寒。\n自共清蟾别有缘。\n江南风味依然在，玉貌韶颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4510, '丑奴儿・采桑子', '周邦彦', '香梅开後风传信，绣户先知。\n雾湿罗衣。\n冷艳须攀最远枝。\n高歌羌管吹遥夜，看即分披。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4511, '蝶恋花', '周邦彦', '鱼尾霞生明远树。\n翠壁黏天，玉叶迎风举。\n一笑相逢蓬海路。\n人间风月如尘土。\n剪水双眸云鬓吐。\n醉倒天瓢，笑语生青雾。\n此会未阑须记取。\n桃花几度吹红雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4512, '蝶恋花', '周邦彦', '美盼低迷情宛转。\n爱雨怜云，渐觉宽金钏。\n桃李香苞秋不展。\n深心黯黯谁能见。\n宋玉墙高才一觇。\n絮乱丝繁，苦隔春风面。\n歌板未终风色便。\n梦为蝴蝶留芳甸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4513, '蝶恋花', '周邦彦', '晚步芳塘新霁後。\n春意潜来，迤逦通窗牖。\n午睡渐多浓似酒。\n韶华已入东君手。\n嫩绿轻黄成染透。\n烛下工夫，泄漏章台秀。\n拟插芳条须满首。\n管交风味还胜旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4514, '蝶恋花', '周邦彦', '叶底寻花春欲暮。\n折遍柔枝，满手真珠露。\n不见旧人空旧处。\n对花惹起愁无数。\n却倚阑干吹柳絮。\n粉蝶多情，飞上钗头住。\n若遣郎身如蝶羽。\n芳时争肯抛人去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4515, '蝶恋花', '周邦彦', '酒熟微红生眼尾。\n半额龙香，冉冉飘衣袂。\n云压宝钗撩不起。\n黄金心字双垂耳。\n愁入眉痕添秀美。\n无限柔情，分付西流水。\n忽被惊风吹别泪。\n只应天也知人意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4516, '减字木兰花', '周邦彦', '风鬟雾鬓。\n便觉蓬莱三岛近。\n水秀山明。\n缥缈仙姿画不成。\n广寒丹桂。\n岂是夭桃尘俗世。\n只恐乘风。\n飞上琼楼玉宇中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4517, '木兰花令', '周邦彦', '歌时宛转饶风措。\n莺语清圆啼玉树。\n断肠归去月三更，薄酒醒来愁万绪。\n孤灯翳翳昏如雾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4518, '蓦山溪', '周邦彦', '楼前疏柳，柳外无穷路。\n翠色四天垂，数峰青、高城阔处。\n江湖病眼，偏向此山明，愁无语。\n空凝伫。\n两两昏鸦去。\n平康巷陌，往事如花雨。\n十载却归来，倦追寻、酒旗戏鼓。\n今宵幸有，人似月婵娟，霞袖举。\n杯深注。\n一曲黄金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4519, '蓦山溪', '周邦彦', '江天雪意，夜色寒成阵。\n翠袖捧金蕉，酒红潮、香凝沁粉。\n帘波不动，新月淡笼明，香破豆，烛频花，减字歌声稳。\n恨眉羞敛，往事休重问。\n人去小庭空，有梅梢、一枝春信。\n檀心未展，谁为探芳丛，消瘦尽，洗妆匀，应更添风韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4520, '南柯子・南歌子', '周邦彦', '宝合分时果，金盘弄赐冰。\n晓来阶下按新声。\n恰有一方明月、可中庭。\n露下天如水，风来夜气清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4521, '南柯子・南歌子', '周邦彦', '腻颈凝酥白，轻衫淡粉红。\n碧油凉气透帘栊。\n指点庭花低映，云母屏风。\n恨逐瑶琴写，书劳玉指封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4522, '关河令・清商怨', '周邦彦', '秋阴时晴向暝，变一庭凄冷。\n伫听寒声，云深无雁影。\n更深人去寂静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4523, '长相思', '周邦彦', '举离觞。\n掩洞房。\n箭水泠泠刻漏长。\n愁中看晓光。\n整罗裳。\n脂粉香。\n见扫门前车上霜。\n相持泣路傍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4524, '长相思', '周邦彦', '马如飞。\n归未归。\n谁在河桥见别离。\n修杨委地垂。\n掩面啼。\n人怎知。\n桃李成阴莺哺儿。\n闲行春尽时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4525, '长相思', '周邦彦', '好风浮。\n晚雨收。\n林叶阴阴映舟。\n斜阳明倚楼。\n黯凝眸。\n忆旧游。\n艇子扁舟来莫愁。\n石城风浪秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4526, '长相思', '周邦彦', '沙棠舟。\n小棹游。\n池水澄澄人影浮。\n锦鳞迟上钩。\n烟云愁。\n箫鼓休。\n再得来时已变秋。\n欲归须少留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4527, '万里春', '周邦彦', '千红万翠。\n簇定清明天气。\n为怜他、种种清香，好难为不醉。\n我爱深如你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4528, '鹤冲天', '周邦彦', '梅雨霁，暑风和。\n高柳乱蝉多。\n小园台榭远池波。\n鱼戏动新荷。\n薄纱厨，轻羽扇。\n枕冷簟凉深院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4529, '鹤冲天', '周邦彦', '白角簟，碧纱厨。\n梅雨乍晴初。\n谢家池畔正清虚。\n香散嫩芙蕖。\n日流金，风解愠。\n一弄素琴歌舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4530, '西河', '周邦彦', '长安道，潇洒西风时起。\n尘埃车马晚游行，霸陵烟水。\n乱鸦栖鸟夕阳中，参差霜树相倚。\n到此际。\n愁如苇。\n冷落关河千里。\n追思唐汉昔繁华，断碑残记。\n未央宫阙已成灰，终南依旧浓翠。\n对此景、无限愁思。\n绕天涯、秋蟾如水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4531, '瑞鹤仙', '周邦彦', '暖烟笼细柳。\n弄万缕千丝，年年春色。\n晴风荡无际，浓於酒、偏醉情人调客。\n阑干倚处，度花香、微散酒力。\n对重门半掩，黄昏淡月，院宇深寂。\n愁极。\n因思前事，洞房佳宴，正值寒食。\n寻芳遍赏，金谷里，铜驼陌。\n到而今、鱼雁沈沈无信，天涯常是泪滴。\n早归来，云馆深处，那人正忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4532, '浪淘沙', '周邦彦', '万叶战，秋声露结，雁度砂碛。\n细草和烟尚绿，遥山向晚更碧。\n见隐隐、云边新月白。\n映落照、帘幕千家，听数声何处倚楼笛。\n装点尽秋色。\n脉脉。\n旅情暗自消释。\n念珠玉、临水犹悲感，何况天涯客。\n忆少年歌酒，当时踪迹。\n岁华易老，衣带宽、懊恼心肠终窄。\n飞散後、风流人阻，蓝桥约、怅恨路隔。\n马蹄过、犹嘶旧巷陌。\n叹往事、一一堪伤，旷望极。\n凝思又把阑干拍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4533, '南乡子', '周邦彦', '秋气绕城。\n暮角寒鸦未掩门。\n记得佳人冲雨别，吟分。\n别绪多於雨後云。\n小棹碧溪津。\n恰似江南第一春。\n应是采莲闲伴侣，相寻。\n收取莲心与旧人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4534, '南乡子', '周邦彦', '寒夜梦初醒。\n行尽江南万里程。\n早是愁来无会处，时听。\n败叶相传细雨声。\n书信也无凭。\n万事由他别後情。\n谁信归来须及早，长亭。\n短帽轻衫走马迎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4535, '南乡子', '周邦彦', '户外井桐飘。\n淡月疏影共寂寥。\n恐怕霜寒初索被，中宵。\n已觉秋声引雁高。\n罗带束纤腰。\n自剪灯花试彩毫。\n收起一封江北信，明朝。\n为问江头早晚潮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4536, '南乡子', '周邦彦', '轻软舞时腰。\n初学吹笙苦未调。\n谁遣有情知事早，相撩。\n暗举罗巾远见招。\n痴呆一团娇。\n自折长条拨燕巢。\n不道有人潜看著，从教。\n掉下鬟心与凤翘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4537, '浣溪沙慢', '周邦彦', '水竹旧院落，樱笋新蔬果。\n嫩英翠幄，红杏交榴火。\n心事暗卜，叶底寻双朵。\n深夜归青琐。\n灯尽酒醒时，晓窗明、钗横鬓。\n怎生那。\n被间阻时多。\n奈愁肠数叠，幽恨万端，好梦还惊破。\n可怪近来，传语也无个。\n莫是人呵。\n真个若人，却因何、逢人问我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4538, '夜游宫', '周邦彦', '一阵斜风横雨。\n薄衣润、新添金缕。\n不谢铅华更清素。\n倚筠窗，弄么弦，娇欲语。\n小阁横香雾。\n正年少、小娥愁绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4539, '诉衷情', '周邦彦', '当时选舞万人长。\n玉带小排方。\n喧传京国声价，年少最无量。\n花阁迥，酒筵香。\n想难忘。\n而今何事，佯向人前，不认周郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4540, '虞美人', '周邦彦', '淡云笼月松溪路。\n长记分携处。\n梦魂连夜绕松溪。\n此夜相逢恰似、梦中时。\n海山陡觉风光好。\n莫惜金尊倒。\n柳花吹雪燕飞忙。\n生怕扁舟归去、断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4541, '烛影摇红', '周邦彦', '芳脸匀红，黛眉巧画宫妆浅。\n风流天付与精神，全在娇波眼。\n早是萦心可惯。\n向尊前、频频顾眄。\n几回相见，见了还休，争如不见。\n烛影摇红，夜阑饮散春宵短。\n当时谁会唱阳关，离恨天涯远。\n争奈云收雨散。\n凭阑干、东风泪满。\n海棠开後，燕子来时，黄昏深院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4542, '失调名', '周邦彦', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4543, '减字木兰花', '陈', '世间拘碍。\n人不堪时渠不改。\n古有斯人。\n千载谁能继後尘。\n春风入手。\n乐事自应随处有。\n与众熙怡。\n何似幽居独乐时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4544, '减字木兰花', '陈', '结庐人境。\n万事醉来都不醒。\n鸟倦云飞。\n两得无心总是归。\n古人逝矣。\n旧日南窗何处是。\n莫负青春。\n即是升平寄傲人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4545, '满庭芳', '陈', '槁木形骸，浮云身世，一年两到京华。\n又还乘兴，闲看洛阳花。\n闻道红最好，春归後、终委泥沙。\n忘言处，花开花谢，不似我生涯。\n年华。\n留不住，饥困寝，触处为家。\n这一轮明月，本自无瑕。\n随分冬裘夏葛，都不会、赤水黄芽。\n谁知我，春风一拐，谈笑有丹砂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4546, '卜算子', '陈', '身如一叶舟，万事潮头起。\n水长船高一任伊，来往洪涛里。\n潮落又潮生，今古长如此。\n後夜开尊独酌时，月满人千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4547, '一落索', '陈', '体上衣裳云作缕。\n不论寒暑。\n世间多少老婆禅，犹苦问、台山路。\n堪笑庞翁无趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4548, '减字木兰花', '陈', '大江北去。\n未到沧溟终不住。\n淮水东流。\n日夜朝宗亦未休。\n香炉烟袅。\n浓淡卷舒终不老。\n寸碧千锺。\n人醉华胥月色中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4549, '减字木兰花', '陈', '华胥月色。\n万水千山同一白。\n南北相望。\n独醉香山旧草堂。\n淮岑妙境。\n十载醺酣犹未醒。\n一腹便便。\n也读春秋也爱眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4550, '卜算子', '陈', '只解劝人归，都不留人住。\n南北东西总是家，劝我归何处。\n去住总由天，天意人难阻。\n若得归时我自归，何必闲言语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4551, '卜算子', '陈', '黄了旧皮肤，最是风流处。\n多少纷纷陌上人，不听春鹃语。\n触目是家山，到了须拈取。\n云散长空月满天，好个还乡路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4552, '卜算子', '陈', '梦里不知眠，觉後眠何在。\n试问眠身与梦身，那个能祗对。\n醉後有人醒，醒了无人醉。\n要识三千与大千，不在微尘外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4553, '青玉案', '陈', '碧空暗淡同云绕。\n渐枕上、风声峭。\n明透纱窗天欲晓。\n珠帘才卷，美人惊报，一夜青山老。\n使君留客金尊倒。\n正千里琼瑶未经扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4554, '蓦山溪', '陈', '扁舟东去，极目沧波渺。\n千古送残红，到如今、东流未了。\n午潮方去，江月照还生，千帆起，玉绳低，枕上莺声晓。\n锦囊佳句，韵压池塘草。\n声遏去年云，恼离怀、馀音缭绕。\n倚楼看镜，此意与谁论，一重水，一重山，目断令人老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4555, '减字木兰花', '陈', '世间药院。\n只爱大黄甘草贱。\n急急加工。\n更靠硫黄与鹿茸。\n鹿茸吃了。\n却恨世间凉药少。\n冷热平均。\n须是松根白茯苓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4556, '满庭芳', '陈', '扰扰匆匆，红尘满袖，自然心在溪山。\n寻思百计，真个不如闲。\n浮世纷华梦影，嚣尘路、来往循环。\n江湖手，长安障日，何似把鱼竿。\n盘旋。\n那忍去，他邦纵好，终异乡关。\n向七峰回首，清泪班班。\n西望烟波万里，扁舟去、何日东还。\n分携处，相期痛饮，莫放酒杯悭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4557, '满庭芳', '陈', '淮叶缤纷，江烟浓淡，别尊同倒寒晖。\n未逢春信，霜露惹征衣。\n往事元无是处，无须待、回首知非。\n春鹃语，从来劝我，常道不如归。\n家山，何处近，江楼帘栋，夕卷朝飞。\n问西江笋蕨，何似鲈肥。\n且置华胥旧梦，忘言处、千古同时。\n君知我，平生心事，相契古来稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4558, '醉蓬莱', '陈', '问东州何处，境胜人幽，两俱难得。\n狼山相望，有高堂千尺。\n妙曲轰空，彩云翻袖，乐奏壶天长日。\n笑我飘然，蓬窗竹户，只延山色。\n拟棹觥船，径冲花浪，直造雕筵，共醺仙液。\n仍乞蟠桃，向庐山亲植。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4559, '临江仙', '陈', '闻道洛阳花正好，家家庭户春风。\n道人饮去百壶空。\n年年花下醉，看谢几番红。\n此别又从何处去，风萍一任西东。\n语声虽异笑声同。\n一轮深夜月，何处不相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4560, '蝶恋花', '陈', '海角芳菲留不住。\n笔下风生，飞入青云去。\n仙有名天赐与。\n致君事业安排取。\n要识世间平坦路。\n当使人人，各有安心处。\n黑发便逢尧舜主。\n笑人白首归南亩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4561, '卜算子', '陈', '咄咄汝何人，眼在眉毛下。\n明月相随万里来，何处分真假。\n问著总无言，有口番成哑。\n荆棘林中自在身，即是知音者。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4562, '蝶恋花', '陈', '有个胡儿模样别。\n满颔髭须，生得浑如漆。\n见说近来头也白。\n髭须那得长长黑。\n□□□□□□□。\n子镊来，须有千堆雪。\n莫向细君容易说。\n恐他嫌你将伊摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4563, '减字木兰花', '陈', '一尊薄酒。\n满酌劝君君举手。\n不是亲朋。\n谁肯相从寂寞滨。\n人生如梦。\n梦里惺惺何处用。\n盏到休辞。\n醉後全胜未醉时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4564, '阮郎归', '陈', '从来多唱杜鹃辞。\n如今真个归。\n健帆笑里落湖西。\n回看江浪飞。\n说情话，复何疑。\n临流应赋诗。\n引觞自酌更何之。\n心闲光景迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4565, '失调名', '陈', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4566, '失调名', '陈', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4567, '满庭芳', '刘山老', '跛子年来，形容何似，俨然一部髭须。\n世间许大，拐上做工夫。\n选甚南州北县，逢著处、酒满葫芦。\n醺醺醉，不知明日，何处度朝晡。\n洛阳，花看了，归来帝里，一事全无。\n又还与瓠羹，再作门徒。\n蓦地思量下水，浪网上、芦席横铺。\n呵呵笑，睢阳门外，有个大南湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4568, '望江南・忆江南', '邵伯温', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4569, '调笑・调笑令', '邵伯温', '翻翻绣袖上红茵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4570, '渔家傲', '净端', '斗转星移天渐晓。\n蓦然听得鹈鹕叫。\n山寺钟声人浩浩。\n木鱼噪。\n渡船过岸行官道。\n轻舟再奈长江讨。\n重添香饵为钩钓。\n钓得锦鳞船里跳。\n呵呵笑。\n思量天下渔家好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4571, '渔家傲', '净端', '浪静西溪澄似练。\n片帆高挂乘风便。\n始向波心通一线。\n群鱼见。\n当头谁敢先吞咽。\n闪烁锦鳞如闪电。\n灵光今古应无变。\n爱是憎非都已遣。\n回头转。\n一轮明月升苍弁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4572, '渔家傲', '净端', '七宝池中堪下钓。\n八功德水烟波渺。\n池底金沙齐布了。\n羡鱼鸟。\n周回旋绕为阶道。\n白鹤孔雀鹦鹉噪。\n弥陀接引毫光照。\n不是修行何得到。\n一般好。\n西方净土无烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4573, '渔家傲', '净端', '一只孤舟巡海岸。\n盘陀石上垂钩线。\n钓得锦鳞鲜又健。\n堪爱羡。\n龙王见了将珠换。\n钓罢归来莲苑看。\n满堂尽是真罗汉。\n便名香三五片。\n梵□献。\n原来佛不夺众生愿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4574, '菩萨蛮', '李', '城阴犹有松间雪。\n松间暗淡城头月。\n月下几枝梅。\n为谁今夜开。\n尊前簪素发。\n自拥繁枝折。\n疑是在瑶台。\n宝灯携手来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4575, '虞美人令・虞美人', '李', '玉阑干外清江浦。\n渺渺天涯雨。\n好风如扇雨如帘。\n时见岸花汀草、涨痕添。\n青林枕上关山路。\n卧想乘鸾处。\n碧芜千里信悠悠。\n惟有霎时凉梦、到南州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4576, '品令', '李', '唱歌须是，玉人檀口，皓齿冰肤。\n意传心事，语娇声颤，字如贯珠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4577, '清平乐', '李', '落梅呜咽。\n暗淡城头月。\n吹满江山惊梦蝶。\n唤起画楼伤别。\n帘风轻触银钩。\n梧桐玉露新秋。\n底事琐窗深夜，素娥常伴人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4578, '水龙吟', '孔夷', '岁穷风雪瓢零，望迷万里云垂冻。\n红绡碎翦，凝酥繁缀，烟深霜重。\n疏影沈波，暗香和月，横斜浮动。\n怅别来，欲把芳菲寄远，还羌管、吹三弄。\n寂寞玉人睡起，污残妆、不胜姣凤。\n盈盈山馆，纷纷客路，相思谁共。\n才与风流，赋称清艳，多情唯宋。\n算襄王，枉被梨花瘦损，又成春梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4579, '南浦', '孔夷', '风悲画角，听单于、三弄落谯门。\n投宿征骑，飞雪满孤村。\n酒市渐闲灯火，正敲窗、乱叶舞纷纷。\n送数声惊雁，下离烟水，嘹唳度寒云。\n好在半胧溪月，到如今、无处不销魂。\n故国梅花归梦，愁损绿罗裙。\n为问暗香闲艳，也相思、万点付啼痕。\n算翠屏应是，两眉馀恨倚黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4580, '惜馀春慢・选冠子', '孔夷', '弄月馀花，团风轻絮，露湿池堂春草。\n莺莺恋友，燕燕将雏，惆怅睡残清晓。\n还似初相见时，携手旗亭，酒香梅小。\n向登临长是，伤春滋味，泪弹多少。\n因甚却、轻许风流，终非长久，又说分飞烦恼。\n罗衣瘦损，绣被香消，那更乱红如扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4581, '鼓笛慢・水龙吟', '孔矩', '数枝凌雪乘冰，嫩英半吐琼酥点。\n南州故苑，何郎遗咏，风台月观。\n疏影横斜，暗香浮动，水寒云晚。\n笑浮花浪蕊，娇春万里，空零落、愁莺燕。\n游子寂寥暮景，向天边、几回相见。\n玉人纤手，殷勤攀赠，欲行微盼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4582, '鹧鸪天', '孔矩', '却月凌风度雪清。\n何郎高咏照花明。\n一枝弄碧传幽信，半额涂黄拾晚荣。\n春思淡，暗香轻。\n江南雨冷若为情。\n犹胜远隔潇湘水，忽到窗前梦不成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4583, '渔家傲', '邹浩', '慧眼舒光无不见。\n尘中一一藏经卷。\n闻说大千摊已遍。\n门方便。\n法轮尽向毫端转。\n月挂烛笼知再见。\n西方可履休回盼。\n要与老岑同掣电。\n酬所愿。\n欣逢十二观音面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4584, '临江仙', '邹浩', '有个头陀修苦行，头上头发毵毵。\n身披一副裙衫。\n紧缠双脚，苦苦要游南。\n闻说度牒朝夕到，并除颔下髭髯。\n钵中无粥住无庵。\n摩登伽处，只恐却重参。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4585, '失调名', '曾诞', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4586, '风流子', '李坦然', '东君虽不语，年华事、今岁恰如期。\n向寒雨望中，晓霜清处，领些春意，开两三枝。\n又不是、山桃红锦烂，溪柳绿摇丝。\n别是一般，孤高风韵，绛裁纤萼，冰剪芳蕤。\n清香还有意，轻飘度勾引，几句新诗。\n须是放怀追赏，莫恁轻离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4587, '感皇恩', '阮阅', '芝检下中天，春寒犹浅。\n馀闰银蟾许重看。\n满城灯火，又遍高楼深院。\n宝鞍催绣毂，香风软。\n憔悴慢翁，萧条古县。\n随分良辰试开宴。\n且倾芳酒，共听新声弦管。\n夜阑人未散，更筹转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4588, '踏莎行', '阮阅', '驿使初回，新阳才报。\n时和倍觉青春早。\n华灯和月拥朱，花间万点寒星小。\n团扇歌清，重舞妙。\n游人只恐归来悄。\n明年亲侍辇舆行，未应肯记濡须好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4589, '减字木兰花', '阮阅', '晓云舒瑞。\n寒影初回长日至。\n罗袜新成。\n更有何人继後尘。\n绮窗寒浅。\n尽道朝来添一线。\n秉烛须游。\n已减铜壶昨夜筹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4590, '锦堂春・锦堂春慢', '阮阅', '江入重关，山围翠，湖边自古巢阳。\n正梅残林坞，冰泮池塘。\n闻道当年父老，记梅福、曾隐南昌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4591, '洞仙歌', '阮阅', '赵家姊妹，合在昭阳殿。\n因甚人间有飞燕。\n见伊底，尽道独步江南，便江北、也何曾惯见。\n惜伊情性好，不解嗔人，长带桃花笑时脸。\n向尊前酒底，得见些时，似恁地、能得几回细看。\n待不眨眼儿、觑著伊，将眨眼底工夫，剩看几遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4592, '眼儿媚', '阮阅', '楼上黄昏杏花寒。\n斜月小栏干。\n一双燕子，两行征雁，画角声残。\n绮窗人在东风里，洒泪对春闲。\n也应似旧，盈盈秋水，淡淡春山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4593, '失调名', '赵企', '闻道南丹风土美。\n流出溅溅五溪水。\n威仪尽识汉君臣，衣冠已变□番子。\n凯歌还、欢声载路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4594, '感皇恩', '赵企', '骑马踏红尘，长安重到。\n人面依前似花好。\n旧欢才展，又被新愁分了。\n未成云雨梦，巫山晓。\n千里断肠，关山古道。\n回首高城似天杳。\n满怀离恨，付与落花啼鸟。\n故人何处也，青春老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4595, '步蟾宫', '汪存', '玉京此去春犹浅。\n正雪絮、马头零乱。\n娥剪就绿云裳，待来步蟾宫与换。\n明年二月桃花岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4596, '蝶恋花', '谢逸', '豆蔻梢头春色浅。\n新试纱衣，拂袖东风软。\n红日三竿帘幕卷。\n画楼影里双飞燕。\n拢鬓步摇青玉碾。\n缺样花枝，叶叶蜂儿颤。\n独倚阑干凝望远。\n一川烟草平如剪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4597, '踏莎行', '谢逸', '柳絮风轻，梨花雨细。\n春阴院落帘垂地。\n碧溪影里小桥横，青帘市上孤烟起。\n镜约关情，琴心破睡。\n轻寒漠漠侵鸳被。\n酒醒霞散脸边红，梦回山蹙眉间翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4598, '菩萨蛮', '谢逸', '暄风迟日春光闹。\n蒲萄水绿摇轻棹。\n两岸草烟低。\n青山啼子规。\n归来愁未寝。\n黛浅眉痕沁。\n花影转廊腰。\n红添酒面潮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4599, '菩萨蛮', '谢逸', '纹波面浮。\n蒲芽出水参差碧。\n满院落梅香。\n柳梢初弄黄。\n衣轻红袖皱。\n春困花枝瘦。\n睡起玉钗横。\n隔帘闻晓莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4600, '采桑子', '谢逸', '楚山削玉云中碧，影落沙汀。\n秋水澄凝。\n一抹江天雁字横。\n金钱满地西风急，红蓼烟轻。\n帘外砧声。\n惊起青楼梦不成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4601, '采桑子', '谢逸', '冰霜林里争先发，独压群花。\n风送清笳。\n更引轻烟淡淡遮。\n抱墙溪水弯环碧，月色清华。\n疏影横斜。\n恰似林逋处士家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4602, '采桑子', '谢逸', '冷猿寒雁淮山远，风袅青帘。\n飞雪廉纤。\n莫道空中是撒盐。\n到时乳鹊喧梧影，晓卷疏帘。\n彩服巡檐。\n索共梅花笑语添。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4603, '西江月', '谢逸', '落寞寒香满院，扶疏清影侵门。\n雪消平野晚烟昏。\n睡起懒匀檀粉。\n皎皎风前玉树，盈盈月下冰魂。\n南枝春信夜来温。\n便觉肌肤瘦损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4604, '西江月', '谢逸', '花额上堆翠葆，远山横处星眸。\n绛宫深锁暮云浮。\n月破黄昏时候。\n谁谓霞衣玉简，便孤彩凤秦楼。\n桃源不禁昔人游。\n曾是刘郎邂逅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4605, '西江月', '谢逸', '窄袖浅笼温玉，修眉淡扫遥岑。\n行时云雾绕衣襟。\n步步莲生宫锦。\n菊与秋烟共晚，酒随人意俱深。\n尊前有客动琴心。\n醉後清狂不禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4606, '西江月', '谢逸', '宝柱横云雁影，朱弦隔叶莺声。\n风生玉脂晚寒清。\n官样轻黄袖冷。\n饮罢尚留馀意，曲终自有深情。\n归来江上数峰青。\n梅水横斜夜永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4607, '西江月', '谢逸', '滴滴金盘露冷，萧萧玉宇风清。\n长庚入梦晓窗明。\n淡月微云耿耿。\n松竹五峰秋色，笙歌三市欢声。\n华堂开宴拥娉婷。\n天上人间共庆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4608, '西江月', '谢逸', '青锦缠条配剑，紫丝络辔飞骢。\n入关意气喜生风。\n年少胸吞云梦。\n金阙日高露泣，东华尘软香红。\n争看荀氏第三龙。\n春暖桃花浪涌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4609, '西江月', '谢逸', '晓艳最便清露，晚红偏怯斜阳。\n移根栽近菊花傍。\n蜀锦翻成新样。\n坐客联挥玉麈，歌词细琢琼章。\n从今故事记溪堂。\n岁岁携壶共赏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4610, '西江月', '谢逸', '木末谁攀新萼，雪消自种前庭。\n莫嫌开过尚盈盈。\n似待诗人醉咏。\n霜後最添妍丽，风中更觉娉婷。\n影摇溪水一湾清。\n妆罢晓临鸾境。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4611, '西江月', '谢逸', '密雪未知肤白，夜寒已觉香清。\n振芳堂下月盈庭。\n踏碎横斜疏影。\n且醉杯中绿蚁，休辞笛里清声。\n东君催促子青青。\n滋味要调金鼎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4612, '南歌子', '谢逸', '雨洗溪光净，风掀柳带斜。\n画楼朱户玉人家。\n帘外一眉新月、浸梨花。\n金鸭香凝袖，铜荷烛映纱。\n凤盘宫锦小屏遮。\n夜静寒生春笋、理琵琶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4613, '虞美人', '谢逸', '碧梧翠竹交加影。\n角簟纱厨冷。\n疏云淡月媚横塘。\n一阵荷花风起、隔帘香。\n雁横天末无消息。\n水阔吴山碧。\n刺桐花上蝶翩翩。\n唯有夜深清梦、到郎边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4614, '虞美人', '谢逸', '角声吹散梅梢雪。\n疏影黄昏月。\n落英点点拂阑干。\n风送清香满院、作轻寒。\n花瓷羯鼓催行酒。\n红袖掺掺手。\n曲声未彻宝杯空。\n饮罢香薰翠被、锦屏中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4615, '虞美人', '谢逸', '风前玉树金韵。\n碧落佳期近。\n疏云影里鹊桥低。\n檐外一弯新月、印修眉。\n星河渐晓铜壶噎。\n又是经年别。\n此情莫与玉人知。\n引起旧家离恨、泪珠垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4616, '谒金门', '谢逸', '帘外雨。\n洗尽楚乡残暑。\n白露影边霞一缕。\n绀碧江天暮。\n沈水烟横香雾。\n茗碗浅浮琼乳。\n卧听鹧鸪啼竹坞。\n竹风清院宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4617, '如梦令', '谢逸', '花落莺啼春暮。\n陌上绿杨飞絮。\n金鸭晚香寒，人在洞房深处。\n无语。\n无语。\n叶上数声疏雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4618, '如梦令', '谢逸', '门外落花流水。\n日暖杜鹃声碎。\n蕃马小屏风，一枕画堂春睡。\n如醉。\n如醉。\n正是困人天气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4619, '青玉案', '谢逸', '芦花飘雪迷洲渚。\n送秋水、连天去。\n一叶小舟横别浦。\n数声鸿雁，两行鸥鹭。\n天淡潇湘暮。\n蓬窗醉梦惊箫鼓。\n回首青楼在何处。\n柳岸风轻吹残暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4620, '好事近', '谢逸', '疏雨洗烟波，雨过满江秋色。\n风起白鸥零乱，破岚光深碧。\n荻花枫叶只供愁，清吟写岑寂。\n吟罢倚阑无语，听一声羌笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4621, '临江仙', '谢逸', '木落江寒秋色晚，飕飕吹帽风轻。\n丹枫楼外捣衣声。\n登高怀远，山影雁边横。\n露染宫黄庭菊浅，茱萸烟拂红轻。\n尊前谁整醉冠倾。\n酒香薰脸，落日断霞明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4622, '临江仙', '谢逸', '玉树临风宾欲散，黄昏约马嘶庭。\n幽欢未尽有馀清。\n琼糜方一啜，银烛已双擎。\n坐久香津生齿颊，何须五斗消酲。\n艳歌声里醉魂醒。\n明年思此会，旌旆想登瀛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4623, '减字木兰花', '谢逸', '荷花风细。\n乞巧楼中凉似水。\n天幕低垂。\n新月弯环浅晕眉。\n桥横乌鹊。\n不负年年云外约。\n残漏疏钟。\n肠断朝霞一缕红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4624, '减字木兰花', '谢逸', '疏疏密密。\n卜林中飞玉出。\n妒舞欺梅。\n悠扬随风去却回。\n遥岑玉刻。\n不见云中浮寸碧。\n夜色清妍。\n庭下交光月午天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4625, '渔家傲', '谢逸', '秋水无痕清见底。\n蓼花汀上西风起。\n一叶小舟烟雾里。\n兰棹舣。\n柳条带雨穿双鲤。\n自叹直钩无处使。\n笛声吹彻云山翠。\n脍落霜刀红缕细。\n新酒美。\n醉来独枕莎衣睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4626, '清平乐', '谢逸', '晓风残角。\n月里梅花落。\n宿酒醒时滋味恶。\n翠被轻寒漠漠。\n梦回一点相思。\n远山暗蹙双眉。\n不觉肌肤瘦玉，但知带减腰围。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4627, '清平乐', '谢逸', '花边柳际。\n已渐知春意。\n归信不知何日是。\n旧恨欲拚无计。\n故人零落西东。\n题诗待倩归鸿。\n惟有多情芳草，年年处处相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4628, '蓦山溪', '谢逸', '霜清木落，深院帘栊静。\n池面卷烟波，莹香水、一奁明镜。\n修筠拂槛，疏翠挽婵娟，山雾敛，水云收，野阔江天迥。\n红消醉玉，酒面风前醒。\n罗幕护轻寒，锦屏空、金炉烬冷。\n星横参昴，梅径月黄昏，清梦觉，浅眉颦，窗外横斜影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4629, '玉楼春', '谢逸', '弄晴数点梨梢雨。\n门外画桥寒食路。\n杜鹃飞破草间烟，蛱蝶惹残花底露。\n东君著意怜樊素。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4630, '玉楼春', '谢逸', '横塘晕浅琉璃莹。\n绿叶阴浓庭院静。\n樱桃熟後麦秋凉，芍药开时槐夏永。\n蓬莱阁下红尘境。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4631, '玉楼春', '谢逸', '个中怀抱谁排遣。\n恻恻轻寒风剪剪。\n细丝梅蕊晚香浓，争似柳梢春色浅。\n娇叱道字歌声软。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4632, '玉楼春', '谢逸', '青钱点水圆荷绿。\n解箨新篁森嫩玉。\n轻风冉冉楝花香，小雨丝丝梅子熟。\n华堂烛烬零金粟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4633, '武陵春', '谢逸', '画烛笼纱红影乱，门外紫骝嘶。\n分破云团月影亏。\n雪浪皱清漪。\n捧碗纤纤春笋瘦，乳雾泛冰瓷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4634, '武陵春', '谢逸', '拍岸蒲萄江水碧，柳带挽归。\n破闷琴风绕袖凉。\n蔌蔌楝花香。\n淡烟疏雨随宜好，何处不潇湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4635, '浪淘沙', '谢逸', '料峭小桃风。\n凝淡春容。\n宝灯山列半天中。\n丽服靓妆携手处，笑语匆匆。\n酒滴小槽红。\n一饮千锺。\n铜荷擎烛绛纱笼。\n归去笙歌暄院落，月照帘栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4636, '鹧鸪天', '谢逸', '桐叶成阴拂画檐。\n清风凉处卷疏帘。\n红绡舞袖萦腰柳，碧玉眉心媚脸莲。\n愁满眼，水连天。\n香笺小字倩谁传。\n梅黄楚岸垂垂雨，草碧吴江淡淡烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4637, '鹧鸪天', '谢逸', '金节平分院落凉。\n黄昏帘幕卷西厢。\n冰轮碾碎粼粼碧，玉斧修成练练光。\n低照户，巧侵床。\n锦袍起舞谪仙狂。\n鹊飞影里觥筹乱，桂子风前笑语香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4638, '鹧鸪天', '谢逸', '红晕香腮粉末匀。\n梳妆闲淡稳精神。\n谁知碧嶂清溪畔，也有姚家一朵春。\n眉黛浅，谁为颦。\n莫将心事付朝云。\n坐中有客肠应断，忘了酴架下人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4639, '鹧鸪天', '谢逸', '水阔天低雁字横。\n小春时节晚寒清。\n梅梢月上纷纷白，竹坞风来冉冉轻。\n人似玉，酒如渑。\n入关意气喜风生。\n坐中有客联镳去，谁唱阳关第四声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4640, '浣溪沙', '谢逸', '楼阁帘垂乳燕飞。\n圆荷细细点清溪。\n薰风破闷晚凉时。\n玉轸琴边兰思远，霜纨扇里翠眉低。\n揉蓝衫子闹蜂儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4641, '燕归梁', '谢逸', '六曲阑干翠幕垂。\n香烬冷金猊。\n日高花外啭黄鹂。\n春睡觉、酒醒时。\n草青南浦，云横西塞，锦字杳无期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4642, '千秋岁', '谢逸', '楝花飘砌。\n蔌蔌清香细。\n梅雨过，苹风起。\n情随湘水远，梦绕吴峰翠。\n琴书倦，鹧鸪唤起南窗睡。\n密意无人寄。\n幽恨凭谁洗。\n修竹畔，疏帘里。\n歌馀尘拂扇，舞罢风掀袂。\n人散後，一钩淡月天如水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4643, '南乡子', '谢逸', '浅色染春衣。\n衣上双双小雁飞。\n袖卷藕丝寒玉瘦，弹棋。\n赢得尊前酒一卮。\n冰雪拂胭脂。\n绛蜡香融落日西。\n唱彻阳关人欲去，依依。\n醉眼横波翠黛低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4644, '醉落魄・一斛珠', '谢逸', '霜砧声急。\n潇潇疏雨梧桐湿。\n无言独倚阑干立。\n帘卷黄昏，一阵西风入。\n年时画阁佳宾集。\n玉人檀板当筵执。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4645, '鹊桥仙', '谢逸', '蝶飞烟草，莺啼云树，满院垂杨阴绿。\n轻风飘散杏梢红，更吹皱、池波如。\n珠帘日晚，银屏人散，楼上醉横霜竹。\n一春若道不相思，缘底事、红绡褪玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4646, '江神子・江城子', '谢逸', '一江秋水碧湾湾。\n绕青山。\n玉连环。\n帘幕低垂，人在画图间。\n闲抱琵琶寻旧曲，弹未了，意阑珊。\n飞鸿数点拂云端。\n倚阑看。\n楚天寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4647, '江神子・江城子', '谢逸', '杏花村馆酒旗风。\n水溶溶。\n扬残红。\n野渡舟横，杨柳绿阴浓。\n望断江南山色远。\n人不见，草连空。\n夕阳楼外晚烟笼。\n粉香融。\n淡眉峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4648, '点绛唇', '谢逸', '九日登高，倚楼人在秋空半。\n汝江如练。\n碧影涵云。\n醉看茱萸，定是明年健。\n清尊满。\n菊花黄浅。\n偏入陶潜眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4649, '点绛唇', '谢逸', '金气秋分，风清露冷秋期半。\n凉蟾光满。\n桂子飘香远。\n素练宽衣，仙仗明飞观。\n霓裳乱。\n银桥人散。\n吹彻昭华管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4650, '七娘子', '谢逸', '风剪冰花飞零乱。\n映梅梢、素影摇清浅。\n绣幄寒轻，兰薰烟暖。\n艳歌催得金荷卷。\n游梁已觉相如倦。\n忆去年、舟渡淮南岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4651, '卜算子', '谢逸', '烟雨幂横塘，绀色涵清浅。\n谁把并州快剪刀，剪取吴江半。\n隐几岸乌巾，细葛含风软。\n不见柴桑避俗翁，心共孤云远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4652, '醉桃源・阮郎归', '谢逸', '花枝破蕾柳梢青。\n春寒拂面轻。\n一眉新月影三星。\n铜荷烛烬零。\n低凤扇，袅霓旌。\n珊珊环佩声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4653, '醉桃源・阮郎归', '谢逸', '风飘万点落花飞。\n残红枝上稀。\n平芜叶上淡烟迷。\n那堪春鸟啼。\n风细细，日迟迟。\n轻纱叠雪衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4654, '醉桃源・阮郎归', '谢逸', '晨光晓色扫檐晶。\n寒斋蝶梦惊。\n乱飘鸳瓦细无声。\n游扬柳丝轻。\n书幌冷，竹窗明。\n柴门只独扃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4655, '望江南・忆江南', '谢逸', '临川好，柳岸转平沙。\n门外澄江丞相宅，坛前乔木列仙家。\n春到满城花。\n行乐处，舞袖卷轻纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4656, '望江南・忆江南', '谢逸', '临川好，山影碧波摇。\n鱼跃冰池飞玉尺，云横石廪拂鲛绡。\n高树竹萧萧。\n寒食近，湖水绿平桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4657, '柳梢青', '谢逸', '香肩轻拍。\n尊前忍听，一声将息。\n昨夜浓欢，今朝别酒，明日行客。\n後回来则须来，便去也、如何去得。\n无限离情，无穷江水，无边山色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4658, '减字木兰花', '夏倪', '江涵晓日。\n荡漾波光摇桨入。\n笑指浯溪。\n漫叟雄文锁翠微。\n休嗟不偶。\n归到中州何处有。\n独立风烟。\n湘水浯台总接天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4659, '汉宫春', '晁冲之', '黯黯离怀，向东门系马，南浦移舟。\n薰风乱飞燕子，时下轻鸥。\n无情渭水，问谁教、日日东流。\n常是送、行人去後，烟波一向离愁。\n回首旧游如梦，记踏青饮，拾翠狂游。\n无端彩云易散，覆水难收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4660, '玉蝴蝶', '晁冲之', '目断江南千里，灞桥一望，烟水微茫。\n尽锁重门，人去暗度流光。\n雨轻轻，梨花院落，风淡淡、杨柳池塘。\n恨偏长。\n佩沈湘浦，云散高唐。\n清狂。\n重来一梦，手搓梅子，煮酒初尝。\n寂寞经春，小桥依旧燕飞忙。\n玉钩栏、凭多渐暖，金缕枕、别久犹香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4661, '感皇恩', '晁冲之', '小阁倚晴空，数声钟定。\n斗柄寒垂暮天净。\n向来残酒，尽被晓风吹醒。\n眼前还认得，当时景。\n旧恨与新愁，不堪重省。\n自叹多情更多病。\n绮窗犹在，敲遍阑干谁应。\n断肠明月下，梅摇影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4662, '感皇恩', '晁冲之', '蝴蝶满西园，啼莺无数。\n水阁桥南路。\n凝伫。\n两行烟柳，吹落一池飞絮。\n秋千斜挂起，人何处。\n把酒劝君，闲愁莫诉。\n留取笙歌住。\n休去。\n几多春色，禁得许多风雨。\n海棠花谢也，君知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4663, '感皇恩', '晁冲之', '寒食不多时，牡丹初卖。\n小院重帘燕飞碍。\n昨宵风雨，只有一分春在，今朝犹自得，阴晴快。\n熟睡起来，宿酲微带。\n不惜罗襟眉黛，日高梳洗，看著花阴移改。\n笑摘双杏子，连枝戴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4664, '临江仙', '晁冲之', '双舸亭亭横晚渚，城中飞观嵯峨。\n画桥灯火照清波。\n玉钩平浸水，金锁半沈河。\n试问无情堤上柳，也应厌听离歌。\n人生无奈别离何。\n夜长嫌梦短，泪少怕愁多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4665, '临江仙', '晁冲之', '忆昔西池池上饮，年年多少欢娱。\n别来不寄一行书。\n寻常相见了，犹道不如初。\n安稳锦屏今夜梦，月明好度江湖。\n相思休问定何如。\n情知春去後，管得落花无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4666, '临江仙', '晁冲之', '谩道追欢惟九日，年年此恨偏浓。\n今朝吹帽与谁同。\n黄花都未拆，和泪泣西风。\n应恐登临肠更断，故交烟雨迷空。\n为君一曲送飞鸿。\n谁能推毂我，深入醉乡中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4667, '渔家傲', '晁冲之', '浦口潮来沙尾涨。\n危樯半落帆游漾，水调不知何处唱。\n风淡荡。\n鳜鱼吹起桃花浪。\n雪尽小桥梅总放。\n层楼一任愁人上。\n万里长安回首望。\n山四向。\n澄江日色如春酿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4668, '传言玉女', '晁冲之', '一夜东风，吹散柳梢残雪。\n御楼烟暖，正鳌山对结。\n箫鼓向晚，凤辇初归宫阙。\n千门灯火，九街风月。\n绣阁人人，乍喜游、困又歇。\n笑匀妆面，把朱帘半揭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4669, '如梦令', '晁冲之', '帘外新来双燕。\n珠阁琼楼穿遍。\n香径得泥归，飞蹙池塘波面。\n谁见。\n谁见。\n春晚昭阳宫殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4670, '如梦令', '晁冲之', '墙外辘轳金并。\n惊梦瞢腾初省。\n深院闭斜阳，燕入阴阴帘影。\n人静。\n人静。\n花落鸟啼风定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4671, '如梦令', '晁冲之', '门在垂杨阴里。\n楼枕曲江春水。\n一阵牡丹风，香压满园花气。\n沈醉。\n沈醉。\n不记绿窗先睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4672, '上林春慢', '晁冲之', '帽落宫花，衣惹御香，凤辇晚来初过。\n鹤降诏飞，龙擎烛戏，端门万枝灯火。\n满城车马，对明月、有谁闲坐。\n任狂游，更许傍禁街，不局金锁。\n玉楼人、暗中掷果。\n珍帘下、笑著春衫袅娜。\n素蛾绕钗，轻蝉扑鬓，垂垂柳丝梅朵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4673, '汉宫春', '晁冲之', '潇洒江梅，向竹梢稀处，横两三枝。\n东君也不爱惜，雪压风欺。\n无情燕子，怕春寒、轻失佳期。\n惟是有、南来归雁，年年长见开时。\n清浅小溪如练，问玉堂何似，茅舍疏篱。\n伤心故人去後，冷落新诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4674, '小重山', '晁冲之', '碧水浮瓜纹簟前。\n只知闲枕手，不成眠。\n晚云如火雨晴天。\n轻云远，亭外一声蝉。\n池馆几年年。\n倚阑催小艇，采新莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4675, '临江仙', '苏庠', '本是白苹洲畔客，虎符卧镇江城。\n归来犹得趁鸥盟。\n柳丝摇晓市，杜若遍芳汀。\n莫惜飞觞仍堕帻，柳边依约莺声。\n水秋鲈熟正关情。\n只愁宣室召，未许钓船轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4676, '临江仙', '苏庠', '猎猎风蒲初暑过，萧然庭户秋清。\n野航渡口带烟横。\n晚山千万叠，别鹤两三声。\n秋水芙蓉聊荡桨，一樽同破愁城。\n蓼花滩上白鸥明。\n暮云连极浦，急雨暗长汀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4677, '如梦令', '苏庠', '叠嶂晓埋烟雨。\n忽作飞花无数。\n整整复斜斜，来伴南枝清苦。\n日暮。\n日暮。\n何许云林烟树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4678, '虞美人', '苏庠', '军书未息梅仍破。\n穿市溪流过。\n病来无处不关情。\n一夜鸣榔急雨、杂滩声。\n飘零无复还山梦。\n云屋春寒重。\n山连积水水连空。\n溪上青蒲短短、柳重重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4679, '浣溪沙', '苏庠', '水榭风微玉枕凉。\n牙床角簟藕花香。\n野塘烟雨罩鸳鸯。\n红蓼渡头青嶂远，绿苹波上白鸥双。\n淋浪淡墨水云乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4680, '谒金门', '苏庠', '何处所。\n门外冷云堆浦。\n竹里江梅寒未吐。\n茅屋疏疏雨。\n谁遣愁来如许。\n小立野塘官渡。\n手种凌霄今在否。\n柳浪迷烟渚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4681, '谒金门', '苏庠', '杨柳渡。\n醉著青鞋归去。\n点点沙鸥何处所。\n十里菰蒲雨。\n抖擞向来尘土。\n卧看碧山云度。\n寄语故时猿鹤侣。\n未见心先许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4682, '鹧鸪天', '苏庠', '枫落河梁野水秋。\n澹烟衰草接郊丘。\n醉眠小坞黄茅店，梦倚高城赤叶楼。\n天杳杳，路悠悠。\n钿筝歌扇等闲休。\n灞桥杨柳年年恨，鸳浦芙蓉叶叶愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4683, '鹧鸪天', '苏庠', '梅妒晨妆雪妒轻。\n远山依约学眉青。\n樽前无复歌金缕，梦觉空馀月满林。\n鱼与雁，两浮沈。\n浅颦微笑总关心。\n相思恰似江南柳，一夜春风一夜深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4684, '鹧鸪天', '苏庠', '秋入蒹葭小雁行。\n参差飞堕水云乡。\n直须银甲供春笋，且滴糟床覆羽觞。\n风压幕，月侵廊。\n江南江北夜茫茫。\n悬知上马啼鹃梦，一夜惊飞宝鸭香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4685, '诉衷情', '苏庠', '杖头挑得布囊行。\n活计有谁争。\n不肯侯家五鼎，碧涧一杯羹。\n溪上月，岭头云。\n不劳耕。\n瓮中春色，枕上华胥，便是长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4686, '诉衷情', '苏庠', '倦投林樾当诛茅。\n鸿雁响寒郊。\n溪上晚来杨柳，月露洗烟梢。\n霜後渚，水分槽。\n尚平桥。\n客床归梦，何必江南，门接云涛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4687, '阮郎归', '苏庠', '西园风暖落花时。\n绿阴莺乱啼。\n倚阑无语惜芳菲。\n絮飞蝴蝶飞。\n缘底事，减腰围。\n遣愁愁著眉。\n波连春渚暮天垂。\n燕归人未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4688, '点绛唇', '苏庠', '冰勒轻，绿痕初涨回塘水。\n柳洲烟际。\n白鹭翘沙嘴。\n箬笠青蓑，未减貂蝉贵。\n云涛里。\n醉眠篷底。\n不属人间世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4689, '菩萨蛮', '苏庠', '北风振野云平屋。\n寒溪淅淅流冰谷。\n落日送归鸿。\n夕岚千万重。\n荒坡垂斗柄。\n直北乡山近。\n何必苦言归。\n石亭春满枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4690, '菩萨蛮', '苏庠', '园林寂寂春归去。\n柳下飞香絮。\n野水接云横。\n绿烟啼晓莺。\n江南梦。\n山色朝来重。\n小艇小湾头。\n苹花苹叶洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4691, '菩萨蛮', '苏庠', '短船谁泊蒹葭渚。\n夜深远火明渔浦。\n却忆槿花篱。\n春声穿竹溪。\n云山如昨好。\n人自垂垂老。\n心事有谁知。\n月明霜满枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4692, '菩萨蛮', '苏庠', '眼中叠叠烟中树。\n晚云点点翻荷雨。\n鸥泛渚边烟。\n绿蒲秋满川。\n未成江海去。\n聊作林塘主。\n客恨阔无津。\n风斜白巾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4693, '菩萨蛮', '苏庠', '年时忆著花前醉。\n而今花落人憔悴。\n麦浪卷晴川。\n杜鹃声可怜。\n有书无雁寄。\n初夏槐风细。\n家在落霞边。\n愁逢江月圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4694, '菩萨蛮', '苏庠', '照溪梅雪和烟堕。\n寒林漠漠愁烟锁。\n客恨渺无涯。\n雁来人忆家。\n远山疑带雨。\n一线云间语。\n霜月又婵娟。\n江南若个边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4695, '菩萨蛮', '苏庠', '春波滟滟浮春渚。\n绿阴一径风兼雨。\n又作去年时。\n绿深垂蔓篱。\n故山归兴动。\n江北江南梦。\n白发故相欺。\n星星如有期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4696, '木兰花・玉楼春', '苏庠', '江云叠叠遮鸳浦。\n江水无情留薄暮。\n归帆初张苇边风，客梦不禁篷背雨。\n渚花不解留人住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4697, '清平乐', '苏庠', '断崖流水。\n香度青林底。\n元配骚人兰与芷。\n不数春风桃李。\n淮南丛桂小山。\n诗翁合得攀翻。\n身到十洲三岛，心游万壑千岩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4698, '小重山', '祖可', '谁向江头遣恨浓。\n碧波流不断，楚山重。\n柳烟和雨隔疏钟。\n黄昏後，罗幕更朦胧。\n桃李小园空。\n阿谁犹笑语，拾残红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4699, '菩萨蛮', '祖可', '西风簌簌低红叶。\n梧桐影里银河匝。\n梦破画帘垂。\n月明乌鹊飞。\n新愁知几许。\n欲似丝千缕。\n雁已不堪闻。\n砧声何处村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4700, '菩萨蛮', '祖可', '谁能画取沙边雨。\n和烟澹扫蒹葭渚。\n别岸却斜晖。\n采莲人未归。\n鸳鸯如解语。\n对浴红衣去。\n去了更回头。\n教侬特地愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4701, '失调名', '蔡', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4702, '声声慢', '张阁', '长天霞散，远浦潮平，危阑注目江皋。\n长记年年荣遇，同是今朝。\n金銮两回命相，对清光、频许挥毫。\n雍容久，正茶杯初赐，香袖时飘。\n归去玉堂深夜，泥封罢，金莲一寸才烧。\n帝语丁宁，曾被华衮亲褒。\n如今谩劳梦想，叹尘踪、杳隔仙鳌。\n无聊意，强当歌对酒怎消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4703, '水调歌头', '毛滂', '九金增宋重，八玉变秦馀。\n千年清浸，洗净河洛出图书。\n一段升平光景，不但五星循轨，万点共连珠。\n垂衣本神圣，补衮妙工夫。\n朝元去，锵环佩，冷云衢。\n芝房雅奏，仪凤矫首听笙竽。\n天近黄麾仗晓，春早红鸾扇暖，迟日上金铺。\n万岁南山色，不老对唐虞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4704, '绛都春', '毛滂', '馀寒尚峭。\n早凤沼冻开，芝田春到。\n茂对诞期，天与公春向廊庙。\n元工开物争春妙。\n付与华多少。\n召还和气，拂开霁色，未妨谈笑。\n缥缈。\n五云乱处，种雕菰向熟，碧桃犹小。\n雨露在门，光采充闾乌亦好。\n宝熏郁雾城南道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4705, '清平乐', '毛滂', '九重寒少。\n烟暖丰瑶草。\n金井碧梧雏凤矫。\n南极人来最老。\n衣冠远换裘毡。\n德随和气蝉连。\n万里同开寿域，一年三秀芝田。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4706, '清平乐', '毛滂', '重芳叠秀。\n风约仙云皱。\n椿不争年松与寿。\n共出皇家忠孝。\n仁深枯冷皆蒙。\n托根不倚东风。\n日照恩光万里，暖生塞草丛中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4707, '清平乐', '毛滂', '镂烟翦雾。\n无层数。\n苜蓿青深烦雪兔。\n引到祥华开处。\n仙人手翳朝阳。\n清都绛阙相将。\n来覆东封翠辇，好遮化日舒长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4708, '清平乐', '毛滂', '九茎为寿。\n千叶前无有。\n叶叶年年看不朽。\n天与君主意厚。\n君恩雨露无边。\n玉筵暖接非烟。\n马向华山烽冷，人安草亦千年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4709, '清平乐', '毛滂', '绛河千岁。\n一照升平事。\n万里青铜开碧霁。\n俯见南山晚翠。\n绀寒不翅湘酃。\n清於练静江澄。\n流向万年觞里，玉波可但如渑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4710, '清平乐', '毛滂', '银河秋浪。\n遥出上。\n忽变澄澜添碧涨。\n可道升平无象。\n黄云浊雾初开。\n荣光休气徘徊。\n试觅当时五老，金泥玉检将来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4711, '清平乐', '毛滂', '天连翠潋。\n九折玻璃软。\n回抱金堤清宛转。\n疑共蓬莱清浅。\n吾君欲济如何。\n唐虞风顺无多。\n自有松舟桧楫，一帆三代同波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4712, '清平乐', '毛滂', '娟娟月满。\n冉冉梅花暖。\n春意初长寒力浅。\n渐拟芳菲满眼。\n当时吉梦重重。\n间生天子三公。\n付与人间桃李，年年管领春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4713, '清平乐', '毛滂', '瀛洲春酒。\n满酌公眉寿。\n日照沙堤春傍柳。\n恩暖朝天衮绣。\n东君著意丁宁。\n芳酸先许梅英。\n要就生平滋味，待公来进君羹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4714, '清平乐', '毛滂', '雪馀寒退。\n唯有青松在。\n春不加荣寒不悴。\n用舍如公都耐。\n流肪磊硌龟蛇。\n会留红日西斜。\n欲助我公寿骨，蟠桃等见开花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4715, '清平乐', '毛滂', '流光电急。\n又过书云日。\n旧是天津花下客。\n老对山青水碧。\n而今转惜年华。\n迟阳为缓西斜。\n试问东君音信，晓寒犹压梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4716, '清平乐', '毛滂', '云峰秀叠。\n露冷琉璃叶。\n北畔娑罗花弄雪。\n香度小桥淡月。\n与君踏月寻花。\n玉人双捧流霞。\n吸尽杯中花月，仙风相送还家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4717, '清平乐', '毛滂', '东风桂影。\n低拂娥镜。\n镜里妆寒酥粉莹。\n越恁十分端正。\n素光行处随人。\n柳边照见青春。\n一片笙箫何处，花阴定有遗簪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4718, '清平乐', '毛滂', '曲房青琐。\n浅笑樱桃破。\n睡起三竿红日过。\n冷了沈香残火。\n东风偏管伊家。\n剩教那与华。\n谁送一怀春思，玉台燕拂菱花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4719, '清平乐', '毛滂', '杏花时候。\n庭下双梅瘦。\n天上流霞凝碧袖。\n起舞与君为寿。\n两桥风月同来。\n东堂且没尘埃。\n烟艇何时重理，更凭风月相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4720, '清平乐', '毛滂', '兰堂灯。\n春入流苏夜。\n衣褪轻红闻水麝。\n云重宝钗未卸。\n知君不奈情何。\n时时慢转横波。\n一饷花柔柳困，枕前特地春多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4721, '清平乐', '毛滂', '风摇烬。\n吹下桃花影。\n醉倒碧铺眠碎锦。\n谁伴香迷酒凝。\n少年不解孤春。\n年来减尽春心。\n犹下绣帘遮定，不教风雨侵凌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4722, '清平乐', '毛滂', '桃夭杏好。\n似个人人好。\n淡抹胭脂眉不扫。\n笑里知春占了。\n此情没个人知。\n灯前仔细看伊。\n恰似云屏半醉，不言不语多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4723, '清平乐', '毛滂', '杯深莫厌。\n强看桃花面。\n记约阳和初一线。\n便恁芳菲满眼。\n明年春色重来。\n东堂花为谁开。\n我在芦花深处，钓矶雨绿莓苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4724, '清平乐', '毛滂', '锦屏夜夜。\n绣被熏兰麝。\n帐卷芙蓉长不下。\n垂尽银台蜡。\n脸痕微著流霞。\n瞢腾越恁华。\n破睡半残妆粉，月随雪到梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4725, '浣溪沙', '毛滂', '碧雾朦胧郁宝熏。\n和风容曳舞帘旌。\n花间千骑两朱轮。\n金马天材文作锦，玉堂仙骨气如冰。\n湖山何似使君清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4726, '浣溪沙', '毛滂', '曾向瑶台月下逢。\n为谁回首矮墙东。\n春风吹酒退腮红。\n庾岭殷勤通远信，梅家潇洒有仙风。\n晚香都在玉杯中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4727, '浣溪沙', '毛滂', '谢女清吟压郢楼。\n楼前风转柳花球。\n学成舞态却多羞。\n半落琼瑶天又惜，稍侵桃李蝶应愁。\n酒家先当翠云裘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4728, '浣溪沙', '毛滂', '小圃韶光不待邀。\n早通消耗与含桃。\n晚来芳意半寒梢。\n含笑不言春淡淡，试妆未遍雨萧萧。\n东家小女可怜娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4729, '浣溪沙', '毛滂', '日照遮檐绣凤凰。\n博山金暖一帘香。\n尊前光景为君长。\n不信腊寒雕鬓影，渐匀春意上妆光。\n梅花长共占年芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4730, '浣溪沙', '毛滂', '花市东风卷笑声。\n柳溪人影乱於云。\n梅花何处暗香闻。\n露湿翠云裘上月，烛摇红锦帐前春。\n瑶台有路渐无尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4731, '浣溪沙', '毛滂', '月样婵娟雪样清。\n索强先占百花春。\n於中烛底好精神。\n多恨肌肤元自瘦，半残妆粉不匀。\n十分全似那人人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4732, '浣溪沙', '毛滂', '水北烟寒雪似梅。\n水南梅闹雪千堆。\n月明南北两瑶台。\n云近恰如天上坐，魂清疑向斗边来。\n梅花多处载春回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4733, '浣溪沙', '毛滂', '小雨初收蝶做团。\n和风轻拂燕泥乾。\n秋千院落落花寒。\n莫对清尊追往事，更催新火续馀欢。\n一春心绪倚阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4734, '浣溪沙', '毛滂', '魏紫姚黄欲占春。\n不教桃杏见清明。\n残红吹尽恰才晴。\n芳草池塘新涨绿，官桥杨柳半拖青。\n秋千院落管弦声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4735, '浣溪沙', '毛滂', '晚色寒清如四檐。\n梧桐冷碧到疏帘。\n小花未了烛花偏。\n瑶瓮孛堆春这里，锦屏屈曲梦谁边。\n熏笼香暖索衣添。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4736, '浣溪沙', '毛滂', '碧浸澄沙上下天。\n曲堤疏柳短长烟。\n月明不待十分圆。\n凿落未空牙板闹，阑干久凭夹衣寒。\n婵娟薄幸冷相看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4737, '浣溪沙', '毛滂', '碧户珠窗小洞房。\n玉醅新压嫩鹅黄。\n半青橙子可怜香。\n风露满帘清似水，笙箫一片醉为乡。\n芙蓉绣冷夜初长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4738, '浣溪沙', '毛滂', '松菊秋来好在无。\n寄声猿鹤莫情疏。\n渊明不老久踟蹰。\n打鼓枫林谁作社，枕溪茅屋忆吾庐。\n去年醉倒倩人扶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4739, '浣溪沙', '毛滂', '本是青门学灌园。\n生涯浑在乱山前。\n一犁春雨种瓜田。\n别後倩云遮鹤帐，来时和月寄渔船。\n旁人莫做长官看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4740, '浣溪沙', '毛滂', '晚色轻凉入画船。\n云峰飞尽玉为天。\n疏飙自为月褰帘。\n细酌流霞君且住，更深风月更清妍。\n为谁凄断小桥边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4741, '浣溪沙', '毛滂', '锦里无端无素书。\n长安秋晚忆家无。\n故人来此尚踟蹰。\n旧事殷勤休忘了，老来凄断恶消除。\n小楼雪夜记当初。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4742, '浣溪沙', '毛滂', '记得山翁往少年。\n青楼一笑万金钱。\n宝鞍逐月玉鞭寒。\n老对冻醪留客话，醉爬短发枕书眠。\n伴人松雨隔疏帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4743, '浣溪沙', '毛滂', '烟柳风蒲冉冉斜。\n小窗不用著帘遮。\n载将山影转湾沙。\n略断时分岸色，蜻蜓立处过汀花。\n此情此水共天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4744, '浣溪沙', '毛滂', '蕙炷犹熏百和。\n兰膏正烂五枝红。\n风流云散太匆匆。\n仙草已添君胜爽，醉乡肯为我从容。\n剩风残月小庭空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4745, '浣溪沙', '毛滂', '银字笙箫小小童。\n梁洲吹过柳桥风。\n阿谁劝我玉杯空。\n小醉径须眠锦瑟，夜归不用照纱笼。\n画船帘卷月明中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4746, '浣溪沙', '毛滂', '滟滟金波暖做春。\n疏疏烟柳瘦於人。\n柳边半醉不胜情。\n未解画船留待月，缓歌金缕细留云。\n将云带月入东门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4747, '浣溪沙', '毛滂', '蜡烛花中月满窗。\n楚梅初试寿阳妆。\n麒麟为脯玉为浆。\n花影烛光相动荡，抱持春色入金觞。\n鸭炉从冷醉魂香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4748, '天香', '毛滂', '进止详华，文章尔雅，金銮恩异群彦。\n尘断银台，天低鳌禁，最是玉皇香案。\n燕公视草，星斗动、昭回云汉。\n对罢宵分，又是金莲，烛引归院。\n年来偃藩江畔。\n赖湖山、慰公心眼。\n碧瓦千家，少借裤襦馀暖。\n黄气珠庭渐满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4749, '小重山', '毛滂', '碧瓦朱甍紫翠深。\n玻璃屏障里，锦为城。\n子胥英爽海涛横。\n玉堂人，於此劝春耕。\n五月政当成。\n岩廊将去路，肯留行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4750, '小重山', '毛滂', '谁劝东风腊里来。\n不知天待雪，恼江梅。\n东郊寒色尚徘徊。\n双彩燕，飞傍鬓云堆。\n玉冷晓妆台。\n宜春金缕字，拂香腮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4751, '小重山', '毛滂', '门外东风糁玉尘。\n曲房花气蔼，博山春。\n小槽珠滴桂椒芬。\n梅蕊绽，谁共醉中闻。\n睡起静无人。\n曲屏横远翠，锦为邻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4752, '小重山', '毛滂', '鹤舞青青雪里松。\n冰开龟在藻，绿蒙茸。\n一成不记蕊珠宫。\n蟠桃熟，应待几东风。\n玉酒紫金锺。\n非烟罗幕暖，宝熏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4753, '满庭芳', '毛滂', '烁石炎曦，过云急雨，院落槐午阴清。\n藕花开遍，绿细一池萍。\n槽下真珠溜溜，龙团破、河朔馀酲。\n阑干外，梧桐叶底，金井辘轳声。\n盈盈。\n开雾帐，珊瑚连枕，云母围屏。\n对肌肤冰雪，自有凉生。\n翠袖风回画扇，拂香篆、虬尾斜横。\n北窗晚，娟娟静色，竹影上帘旌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4754, '满庭芳', '毛滂', '马络青丝，障开红锦，小晴初断香尘。\n芳醪满载，持烛有佳人。\n飞盖西园午夜，花梢冷、云月胧明。\n折还惜，留花伴月，占定可怜春。\n佳人。\n争插帽，已残芳树，犹缀馀英。\n任红辞香散，蝶恨蜂嗔。\n醉也和春戴去，深院落、初馥炉熏。\n玉台畔，未教卸了，留映晚妆新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4755, '摊声浣溪沙・浣溪沙', '毛滂', '日照门前千万峰。\n晴飙先扫冻云空。\n谁作素涛翻玉手，小团龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4756, '摊声浣溪沙・浣溪沙', '毛滂', '日转堂阴一线添。\n使君和气作春妍。\n祗有北山轻带雪，见丰年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4757, '摊声浣溪沙・浣溪沙', '毛滂', '雨色流香绕坐中。\n映阶疏竹一丛丛。\n不奈晚来萧瑟意，子猷风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4758, '踏莎行', '毛滂', '天质婵娟，妆光荡漾。\n御酥做出花模样。\n夭桃繁杏本妖妍，文鸳彩凤能偎傍。\n艾绿浓香，鹅黄新酿。\n缘云清切歌声上。\n夜寒不近绣芙蓉，醉中祗觉春相向。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4759, '踏莎行', '毛滂', '映竹幽妍，临池娟靓。\n芳苞先暖香初娠。\n南枝微弄雪精神，东君早寄春音信。\n奔月仙标，乘烟远韵。\n玉台粉点和酥凝。\n从来清瘦可禁寒，为谁早把霞衣褪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4760, '踏莎行', '毛滂', '粟玉玲珑，雍酥浮动。\n芳跗染得胭脂重。\n风前兰麝作香寒，枝头烟雪和春冻。\n蜂翅初开，蜜房香弄。\n佳人寒睡愁和梦。\n鹅黄衫子茜罗裙，风流不与江梅共。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4761, '踏莎行', '毛滂', '景泮冰檐，情回瑶草。\n副能守得春来到。\n管曾独自索春怜，而今觑著东风笑。\n粉凝酥寒，云房睡觉。\n胭脂也不添些小。\n天真要与此花争，是伊占得春多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4762, '踏莎行', '毛滂', '拨雪寻春，烧灯续昼。\n暗香院落梅开後。\n无端夜色欲遮春，天教月上官桥柳。\n花市无尘，朱门如绣。\n娇云瑞雾笼星斗。\n沈香火冷小妆残，半衾轻梦浓如酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4763, '踏莎行', '毛滂', '阶影红迟，柳苞黄遍。\n纤云弄日阴晴半。\n重帘不卷篆香横，小花初破春丛浅。\n凤绣犹重，鸭炉长暖。\n屏山翠入江南远。\n醉轻梦短枕闲，绿窗窈窕风光转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4764, '踏莎行', '毛滂', '芳气霏微，薄衣料峭。\n何人正倚桃花笑。\n流红不出武陵溪，这回空与春风到。\n尊俎全稀，风情终较。\n安仁老也谁知道。\n碧云无信失秦楼，旧时明月犹相照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4765, '踏莎行', '毛滂', '碧树阴圆，绿阶露满。\n金波潋滟堆瑶盏。\n行云会事不飞来，长空一片琉璃浅。\n玉燕钗寒，藕丝袖冷。\n只应未倚阑干遍。\n随人全不似婵娟，桂花影里年年见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4766, '玉楼春', '毛滂', '西风吹冷沈香篆。\n门掩小晴红叶院。\n卧看黄菊送重阳，露重烟寒花未遍。\n衰翁病怯琉璃簟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4767, '玉楼春', '毛滂', '泥银四壁盘蜗篆。\n明月一庭秋满院。\n不知陶菊总开无，但见杜苔新雨遍。\n去年醉倒云为簟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4768, '玉楼春', '毛滂', '三衢太守文章伯。\n七月政成如戏剧。\n坐中咳唾落珠玑，笔下神明飞霹雳。\n才高莫恨溪山窄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4769, '玉楼春', '毛滂', '一年滴尽莲花漏。\n碧井酴酥沈冻酒。\n晓寒料峭尚欺人，春态苗条先到柳。\n佳人重劝千长寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4770, '玉楼春', '毛滂', '蕊珠宫里三千女。\n滴粉为春尘不住。\n月华冷处欲迎人，七里香风生满路。\n一枝谁寄长安去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4771, '玉楼春', '毛滂', '小园半夜东风转。\n吹皱冰池云母面。\n晓披阊阖见朝阳，知向碧阶添几线。\n小烟弄柳晴先暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4772, '玉楼春', '毛滂', '长安回首空云雾。\n春梦觉来无觅处。\n冷烟寒雨又黄昏，数尽一堤杨柳树。\n楚山照眼青无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4773, '玉楼春', '毛滂', '一春花事今宵了。\n点检落红都已少。\n阿谁追路问东君，祗有青青河畔草。\n尊前不信韶华老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4774, '南歌子', '毛滂', '暮霰寒依树，娇云冷傍人。\n江南谁寄一枝春。\n何似珑璁十里、更无尘。\n雨萼胭脂淡，香须蝶子轻。\n碧山归路小桥横。\n谁见暗香今夜、月胧明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4775, '南歌子', '毛滂', '庭下新生月，凭君把酒看。\n不须直待素团团。\n恰似那人眉样、秀弯环。\n冷射鸳鸯瓦，清欺翡翠帘。\n数枝烟竹小桥寒。\n渐见风吹疏影、过阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4776, '南歌子', '毛滂', '绿暗藏城市，清香扑酒尊。\n淡烟疏雨冷黄昏。\n零落酴花片、损春痕。\n润入笙箫腻，春馀笑语温。\n更深不锁醉乡门。\n先遣歌声留住、欲归云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4777, '八节长欢', '毛滂', '名满人间。\n记黄金殿，旧赐清闲。\n才高鹦鹉赋，风懔惠文冠。\n涛波何处试蛟鳄，到白头、犹守溪山。\n且做龚黄样度，留与人看。\n桃溪柳曲阴圆。\n离唱断、旌旗却卷春还。\n襦裤寄馀温，双石畔、唯闻吏胆长寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4778, '八节长欢', '毛滂', '泽国秋深。\n绣楹天近，坐久魂清。\n溪山绕尊酒，云雾衣襟。\n馀霞孤雁送愁眼，寄寒闺、一点离心。\n杜老两峰秀处，短发疏巾。\n佳人为折寒英。\n罗袖湿、真珠露冷钿金。\n幽艳为谁妍，东篱下、却教醉倒渊明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4779, '蓦山溪', '毛滂', '雪空毡径，扑扑怜飞絮。\n柔弱不胜春，任东风、吹来吹去。\n墙阴苑外，一片落谁家，叶依依，烟郁郁，依旧如张绪。\n那人拈得，吹向钗头住。\n不定却飞扬，满眼前、搅人情愫。\n蜂儿蝶子，教得越轻狂，隔斜阳，点芳草，断送青春暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4780, '蓦山溪', '毛滂', '东堂先晓，帘挂扶桑暖。\n画舫寄江湖，倚小楼、心随望远。\n水边竹畔，石瘦藓花寒，秀阴遮，潜玉梦，鹤下渔矶晚。\n藏花小坞，蝶径深深见。\n彩笔赋阳春，看藻思、飘飘云半。\n烟拖山翠，和月冷西窗，玻璃盏，蒲萄酒，旋落酴片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4781, '蓦山溪', '毛滂', '婵娟不老，依旧东风面。\n华烛下珠，盛寒里、春光一片。\n不教暮景，也似每常来，水精宫，银色界，今夜分明见。\n碧街如水，人影花凌乱。\n谁在柳阴中，小妆寒、落梅数点。\n诗翁独倚，十二玉阑干，露，云冉冉，千嶂琉璃浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4782, '蓦山溪', '毛滂', '梅花初谢，雪後寒微峭。\n谁送一城春，绮罗香、风光窈窕。\n插花走马，天近宝鞭寒，金波上，玉轮边，不是红尘道。\n玻璃山畔，夜色无由到。\n深下水晶帘，拥严妆、铅华相照。\n珠楼缈缈，人月两婵娟，尊前月，月中人，相见年年好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4783, '临江仙', '毛滂', '古寺长廊清夜美，风松烟桧萧然。\n石阑干外上疏帘。\n过云闲窈窕，斜月静婵娟。\n独自徘徊无个事，瑶琴试奏流泉。\n曲终谁见枕琴眠。\n香残虬尾细，灯暗玉虫偏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4784, '临江仙', '毛滂', '莫恨那回容易别，不妨久远情肠。\n为人留下旧风光。\n花枝长好在，馥馥十年香。\n便是旧时帘外月，却来小槛低窗。\n朦胧影里淡梳妆。\n相看如梦寐，回首乍思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4785, '剔银灯', '毛滂', '帘下风光自足。\n春到席间屏曲。\n瑶瓮酥融，羽觞蚁闹，花映酃湖寒绿。\n汨罗愁独。\n又何似、红围翠簇。\n聚散悲欢箭速。\n不易一杯相属。\n频剔银灯，别听牙板，尚有龙膏堪续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4786, '水调歌头', '毛滂', '金马空故事，方朔漫多端。\n三千牍在，玉殿何日赐清闲。\n难恋长安锺漏，谁借青云咳唾，拂袖且东还。\n笑杀长缨使，复转出秦关。\n吾道在，虽不遇，面何惭。\n雒阳年少，高轮难与绛侯谈。\n富贵暂饶先手，尽草头秋露，掩鼻出东山。\n且饱鲸鱼脍，风月过江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4787, '水调歌头', '毛滂', '谢安涵雅量，叔夜赋刚肠。\n清宵假寐，应笑长孺卧淮阳。\n尽彻东平屏障，不废南楼谈咏，宴寝自凝香。\n庭下一杯土，须避赤帷裳。\n双石健，含古色，照新堂。\n百年乔木阴下，僵立两蛟苍。\n目送千山爽气，帘卷一城风月，杖屦合彷徉。\n他日峨眉秀，相望隔明光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4788, '浣溪沙', '毛滂', '竹送秋声入小窗。\n香迷夜色暗牙床。\n小屏风掩烛花长。\n雁过故人无信息，酒醒残梦寄凄凉。\n画桥露月冷鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4789, '武陵春', '毛滂', '维岳分公英特气，万丈拂长虹。\n丙魏萧曹总下风。\n千载友夔龙。\n宝熏袅翠昏帘绣，嘉颂佩绅同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4790, '武陵春', '毛滂', '迎得春来闻好语，贺燕立帘钩。\n转蕙风光柳弄柔。\n喜气与春游。\n万钱珍鼎期公饭，天自寿留侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4791, '武陵春', '毛滂', '银浦流云初度月，空碧挂团团。\n照夜珠胎贝阙寒。\n光彩满长安。\n春风为拂新沙路，珂马款天关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4792, '玉楼春', '毛滂', '今朝何以为公寿。\n极贵长年公素有。\n庭阶不乏长芝兰，少翁又是廷臣右。\n三能粲粲依魁秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4793, '玉楼春', '毛滂', '我公两器兼文武。\n谈笑岩廊无治古。\n红颜绿发已官高，赤舄绣裳今仲父。\n我欲形容无妙语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4794, '玉楼春', '毛滂', '压玉为浆麟作。\n珠树琼葩长不谢。\n翠帘绣暖燕归来，宝鸭花香蜂上下。\n沙堤佩马催公驾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4795, '秦楼月・忆秦娥', '毛滂', '蔷薇折。\n一怀秀影花和月。\n花和月。\n著人浓似，粉香酥色。\n绿阴垂幕帘波叠。\n微风过竹凉吹发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4796, '遍地花', '毛滂', '白玉阑边自凝伫。\n满枝头、彩云雕雾。\n甚芳菲、绣得成团，砌合出、韶华好处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4797, '夜游宫', '毛滂', '长记劳君送远。\n柳烟重、桃花波暖。\n花外溪城望不见。\n古槐边，故人稀，秋鬓晚。\n我有凌霄伴。\n在何处、山寒云乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4798, '诉衷情', '毛滂', '花阴柳影映帘栊。\n罗幕绣重重。\n行云自随语燕，回雪趁惊鸿。\n银字歇，玉杯空。\n蕙烟中。\n桃花髻暖，杏叶眉弯，一片春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4799, '诉衷情', '毛滂', '短疏萦缘象床低。\n玉鸭度香迟。\n微云淡著河汉，凉过碧梧枝。\n秋韵起，月阴移。\n下帘时。\n人间天上，一样风光，我与君知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4800, '醉花阴', '毛滂', '檀板一声莺起速。\n山影穿疏木。\n人在翠阴中，欲觅残春，春在屏风曲。\n劝君对客杯须覆。\n灯照瀛洲绿。\n西去玉堂深，魄冷魂清，独引金莲烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4801, '醉花阴', '毛滂', '金叶犹温香未歇。\n尘定歌初彻。\n暖透薄罗衣，一霎清风，人映团团月。\n持杯试听留春阕。\n此个情肠别。\n分付与莺莺，劝取东君，停待芳菲节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4802, '减字木兰花', '毛滂', '暖风吹雪。\n洗尽碧阶今夜月。\n试觅云英。\n更就蓝桥借月明。\n从教不借。\n自有使君家不夜。\n谁道由天。\n光景随人特地妍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4803, '减字木兰花', '毛滂', '曾教风月。\n催促花边烟棹发。\n不管花开。\n月白风清始肯来。\n既来且住。\n风月闲寻秋好处。\n收取凄清。\n暖日阑干助梦吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4804, '减字木兰花', '毛滂', '小桥秀绝。\n露湿芙蕖花上月。\n月下人人。\n花样精神月样清。\n谁言见惯。\n到了司空情不慢。\n丞相无。\n若不时醉倩扶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4805, '上林春令・一落索', '毛滂', '蝴蝶初翻帘绣。\n万玉女、齐回舞袖。\n落花飞絮，长忆著、灞桥别後。\n浓香斗帐自永漏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4806, '人娇', '毛滂', '雪做屏风，花为行帐。\n屏帐里、见春模样。\n小晴未了，轻阴一饷。\n酒到处、恰如把春拈上。\n官柳黄轻，河堤绿涨。\n花多处、少停兰桨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4807, '人娇', '毛滂', '短棹犹停，寸心先往。\n说归期、唤做的当。\n夕阳下地，重城远样。\n风露冷、高楼误伊等望。\n今夜孤村，月明怎向。\n依还是、梦回绣幌。\n远山想像。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4808, '惜分飞', '毛滂', '山转沙回江声小。\n望尽冷烟衰草。\n梦断瑶台晓。\n楚云何处英英好。\n古寺黄昏人悄悄。\n帘卷寒堂月到。\n不会思量了。\n素光看尽桐阴少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4809, '惜分飞', '毛滂', '泪湿阑干花著露。\n愁到眉峰碧聚。\n此恨平分取。\n更无言语。\n空相觑。\n短雨残云无意绪。\n寂寞朝朝暮暮。\n今夜山深处。\n断魂分付。\n潮回去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4810, '惜分飞', '毛滂', '花影低徊帘幕卷。\n惯了双来燕燕。\n惊散雕阑晚。\n雨昏烟重垂杨院。\n云断月斜红烛短。\n望断真个望断。\n情寄梅花点。\n趁风飞过楼南畔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4811, '惜分飞', '毛滂', '恰则心头托托地。\n放下了日多萦系。\n别恨还容易。\n袖痕犹有年时泪。\n满满频斟乞求醉。\n且要时闲忘记。\n明日刘郎起。\n马蹄去便三千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4812, '蝶恋花', '毛滂', '闻说君家传窈窕。\n秀色天真，更夺丹青妙。\n细意端相都总好。\n春愁春媚生颦笑。\n琼玉胸前金凤小。\n那得殷勤，细托琵琶道。\n十二峰云遮醉倒。\n华灯翠帐花相照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4813, '蝶恋花', '毛滂', '江接寒溪家已近。\n想见秋来，松菊荒三径。\n目送吴山秋色尽。\n星星却入双蓬鬓。\n凫短鹤长真个定。\n勋业来迟，不用频看镜。\n懒出问人人不问。\n绿尊倒尽横书枕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4814, '蝶恋花', '毛滂', '相见江南情不少。\n尔许多时，怪得无消耗。\n淡日暖云句引到。\n阑干寂寞怜春小。\n宫面可匀画了。\n粉瘦酥寒，一段天真好。\n唤起玉儿娇睡觉。\n半山残月南枝晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4815, '蝶恋花', '毛滂', '红杏梢头寒食雨。\n燕子泥新，不住飞来去。\n行傍柳阴闻好语。\n莺儿穿过黄金缕。\n桑落酒寒杯懒举。\n总被多情，做得无情绪。\n春过二分能几许。\n银台新火重帘暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4816, '蝶恋花', '毛滂', '三叠阑干铺碧。\n小雨新晴，才过清明後。\n初见花王披衮绣。\n娇云瑞日明春昼。\n彩女朝真天质秀。\n宝髻微偏，风卷霞衣皱。\n莫道东君情最厚。\n韶光半在东堂手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4817, '蝶恋花', '毛滂', '红影斑斑吹锦片。\n露叶烟梢，寒月娟娟满。\n更起绕庭行百遍。\n无人祗有栖莺见。\n觅个薄情心对换。\n愁绪偏长，不信春宵短。\n正是碧云音信断。\n半衾犹赖香熏暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4818, '蝶恋花', '毛滂', '城上春云低阁雨。\n渐觉春随，一片花飞去。\n素颈圆吭莺燕语。\n不妨缓缓歌金缕。\n堕纪颓纲公已举。\n但见清风，萧瑟随谈绪。\n借寇假饶天不许。\n未须忙遣韶华暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4819, '蝶恋花', '毛滂', '花里传觞飞羽过。\n渐觉金槽，月缺圆龙破。\n素手转罗酥作颗。\n鹅溪雪绢云腴堕。\n七盏能醒千日卧。\n扶起瑶山，嫌怕香尘。\n醉色轻松留不可。\n清风停待些时过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4820, '蝶恋花', '毛滂', '不雨不晴秋气味。\n酒病秋怀，不做醒松地。\n初换夹衣围翠被。\n蔷薇水润衙香腻。\n旋折秋英餐露蕊。\n金缕虬团，更试康王水。\n幽梦不来寻小睡。\n无言划尽屏山翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4821, '更漏子', '毛滂', '玉狻猊，金叶暖。\n馥馥香云不断。\n长下著，绣帘重。\n怕随花信风。\n傍蔷薇，摇露点。\n衣润得香长远。\n双枕凤，一衾鸾。\n柳烟花雾间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4822, '更漏子', '毛滂', '绿窗寒，清漏短。\n帐底沈香火暖。\n残烛暗，小屏弯。\n云峰遮梦还。\n那些愁，推不去。\n分付一檐寒雨。\n檐外竹，试秋声。\n空庭鹤唤人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4823, '更漏子', '毛滂', '柳藏烟，云漏日。\n寒满雕盘玉食。\n风卷旆，水摇天。\n鱼龙挟彩船。\n水边人，波面乐。\n太守与民同乐。\n春好处，总随轩。\n花中谁状元。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4824, '西江月', '毛滂', '花下春藏五马，松间风落双凫。\n兵厨玉帐卷酃湖。\n人醉碧云欲暮。\n归去聊登文石，翱翔便是天衢。\n雅歌谁解继投壶。\n桃李无言满路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4825, '西江月', '毛滂', '烟雨半藏杨柳，风光初到桃花。\n玉人细细酌流霞。\n醉里将春留下。\n柳畔鸳鸯作伴，花边蝴蝶为家。\n醉翁醉里也随他。\n月在柳桥花榭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4826, '西江月', '毛滂', '雨後夹衣初冷，霜前细菊浑斑。\n觚棱清月绣团环。\n万里长安秋晚。\n槽下内家玉滴，盘中江国金丸。\n春容著面作微殷。\n烛影红摇醉眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4827, '西江月', '毛滂', '席上芙蓉待暖，花间袅还嘶。\n劝君不醉且无归。\n归去因谁惜醉。\n汤点瓶心未老，乳堆盏面初肥。\n留连能得几多时。\n两腋清风唤起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4828, '青玉案', '毛滂', '芙蕖花上雨。\n又冷落、池塘暮。\n何处风来摇碧户。\n卷帘凝望，淡烟疏柳，翡翠穿花去。\n玉京人去无由驻。\n恁独坐、凭阑处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4829, '青玉案', '毛滂', '玉婴初有排云分。\n向晚色、娟娟静。\n秋入风枝清不尽。\n月和粉露，徘徊孤映，独夜扶疏影。\n子猷风调全相称。\n是彼此、无凡韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4830, '青玉案', '毛滂', '玉人为我殷勤醉。\n向醉里、添姿媚。\n偏著冠儿钗欲坠。\n桃花气暖，露浓烟重，不自禁春意。\n绿榆阴下东行水。\n渐渐近、凄凉地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4831, '青玉案', '毛滂', '今宵月好来同看。\n月未落、人还散。\n把手留连帘儿畔。\n含羞和恨转娇盼。\n恁花映春风面。\n相思不用宽金钏。\n也不用、多情似玉燕。\n问取婵娟学长远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4832, '河满子', '毛滂', '急雨初收珠点。\n云峰绝天半。\n辘轳金井卷甘冽，帘外翠阴遮遍。\n波翻水精重帘，秋在琉璃双簟。\n漏永流花缓缓。\n未放崦嵫晚。\n红荷绿芰暮天好，小宴水亭风馆。\n云乱香喷宝鸭，月冷钗横玉燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4833, '谒金门', '毛滂', '灯雾里。\n老去昔游不记。\n月似旧时人不似。\n小楼何处是。\n归卧晚香翠被。\n玉酒著人小醉。\n欲睡先来都不睡。\n此情那恁地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4834, '七娘子', '毛滂', '山屏雾帐玲珑碧。\n更绮窗、临水新凉入。\n雨短烟长，柳桥萧瑟。\n这番一日凉一日。\n离多绿鬓多时白。\n这离情、不似而今惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4835, '七娘子', '毛滂', '月光波影寒相向。\n借团团、与做长壕样。\n此老南楼，风流可想。\n殷勤冰彩随人上。\n欲同次道倾家酿。\n有兵厨、玉盎金波涨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4836, '雨中花・夜行船', '毛滂', '寒浸东倾不定。\n更奈橹声催紧。\n堤树胧明孤月上，暗淡移船影。\n旧事十年愁未醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4837, '雨中花・夜行船', '毛滂', '池上山寒欲雾。\n竹暗小窗低户。\n数点秋声侵短梦，檐下芭蕉雨。\n白酒浮蛆鸡啄黍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4838, '夜行船', '毛滂', '寒满一衾谁共。\n夜沈沈、醉魂朦。\n雨呼烟唤付凄凉，又不成、那些好梦。\n明日烟江□暝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4839, '夜行船', '毛滂', '弄水馀英溪畔。\n绮罗香、日迟风慢。\n桃花春浸一篙深，画桥东、柳低烟远。\n涨绿流红空满眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4840, '鹊桥仙', '毛滂', '红摧绿锉，莺愁蝶怨，满院落花风紧。\n醉乡好梦恰瞢腾，又冷落、一成吹醒。\n柔红不耐，暗香犹好，觑著翻成不忍。\n春心减尽眼长闲，更肯被、游丝牵引。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4841, '鹊桥仙', '毛滂', '水精帘外，沈香阑畔，新下红油画幕。\n百花何处避芳尘，便独自、将春占却。\n月华淡淡，夜寒森森，犹把红灯照著。\n醉时从醉不归家，贤守定、不教冷落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4842, '烛影摇红', '毛滂', '一亩清阴，半天潇洒松窗午。\n床头秋色小屏山，碧帐垂烟缕。\n枕畔风摇绿户。\n唤人醒、不教梦去。\n可怜恰到，瘦石寒泉，冷云幽处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4843, '烛影摇红', '毛滂', '老景萧条，送君归去添凄断。\n赠君明月满前溪，直到西湖畔。\n门掩绿苔应遍。\n为黄花、频开醉眼。\n橘奴无恙，蝶子相迎，寒窗日短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4844, '烛影摇红', '毛滂', '鬓绿飘萧，漫郎已是青云晚。\n古槐阴外小阑干，不负看山眼。\n此意悠悠无限。\n有云山、知人醉懒。\n他年寻我，水边月底，一蓑烟短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4845, '忆秦娥', '毛滂', '醉醉。\n醉击珊瑚碎。\n花花。\n先借春光与酒家。\n夜寒我醉谁扶我。\n应抱瑶琴卧。\n清清。\n揽月吟风不用人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4846, '忆秦娥', '毛滂', '夜夜。\n夜了花朝也。\n连忙。\n指点银瓶索酒尝。\n明朝花落知多少。\n莫把残红扫。\n愁人。\n一片花飞减却春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4847, '武陵春', '毛滂', '城上落梅风料峭，寒馥逼清尊。\n爽兴天教属使君。\n雪意压歌云。\n插帽殷罗金缕细，燕燕早随人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4848, '武陵春', '毛滂', '风过冰檐环佩响，宿雾在华茵。\n剩落瑶花衬月明。\n嫌怕有纤尘。\n凤口衔灯金炫转，人醉觉寒轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4849, '武陵春', '毛滂', '春在前村梅雪里，一夜到千门。\n玉佩琼琚下冷云。\n银界见东君。\n桃花髻暖双飞燕，金字巧宜春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4850, '点绛唇', '毛滂', '高柳横斜，冷光凌乱摇疏翠。\n露荷珠缀。\n但见鸳鸯睡。\n□□□□，□□□□□。\n□□□。\n□□□□。\n□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4851, '点绛唇', '毛滂', '柏叶春醅，为君亲酌玻璃盏。\n玉箫牙管。\n人意如春暖。\n鬓绿长留，不使韶华晚。\n春无限。\n碧桃花畔。\n笑看蓬莱浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4852, '点绛唇', '毛滂', '手抚归鸿，坐临烟雨帘旌润。\n气清天近。\n云日温阑。\n压玉浮金，一醉留青鬓。\n风光胜。\n淡妆人靓。\n眉黛生秋晕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4853, '点绛唇', '毛滂', '何处君家，蟠桃花下瑶池畔。\n日迟烟暖。\n占得春长远。\n几见花开，一任年光换。\n今年见。\n明年重见。\n春色如人面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4854, '点绛唇', '毛滂', '秀岭寒青，冷泉凌乱催秋意。\n佩环声里。\n无限真珠碎。\n叹我平生，识尽闲滋味。\n来闲地。\n为君一醉。\n万事浮云外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4855, '点绛唇', '毛滂', '小院重帘，那回来处花相向。\n迟迟一饷。\n记得春模样。\n昨夜月明，应照芙蓉帐。\n空凝望。\n蜂劳蝶攘。\n谁在花枝上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4856, '点绛唇', '毛滂', '绣岭横秋，玉螭吹暑迎凉气。\n碧崖流水。\n流入春葱指。\n半倚朱弦，微连环珥。\n通深意。\n月明风细。\n分付知音耳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4857, '如梦令', '毛滂', '深苑重调弦管。\n不觉银台烛短。\n相对有金波，天畔杯中都满。\n人远。\n人远。\n醉倚阑干玉冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4858, '玉楼春', '毛滂', '当日岭头相见处。\n玉骨冰肌元淡伫。\n近来因甚要浓妆，不管满城桃杏妒。\n酒晕脸霞春暗度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4859, '生查子', '毛滂', '鲈蟹正肥时，烟雨新凉日。\n露蕊郁金黄，云液蒲萄碧。\n此日古为佳，此醉君宁惜。\n高挂水精帘，尽放秋光入。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4860, '生查子', '毛滂', '日照小窗纱，风动重帘绣。\n宝炷暮云迷，曲沼晴漪皱。\n烟暖柳醒松，雪尽梅清瘦。\n恰是可怜时，好似花後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4861, '生查子', '毛滂', '钗上燕犹寒，胜里红偏小。\n恰有尔多春，不许群花笑。\n酒面粉酥融，香袖金泥罩。\n芳意已潜通，残雪犹相照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4862, '生查子', '毛滂', '春晚出山城，落日行江岸。\n人不共潮来，香亦临风散。\n花谢小妆残，莺困清歌断。\n行雨梦魂消，飞絮心情乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4863, '生查子', '毛滂', '花地锦斑残，月箔波凌乱。\n斗鸭玉阑旁，扑兽金炉畔。\n小醉奈春何，轻梦催云散。\n却步蕙兰中，应被鸳鸯见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4864, '浪淘沙', '毛滂', '深院绣帘垂。\n前日春归。\n画桥杨柳弄烟霏。\n池面东风先解冻，龟上涟漪。\n酒潋玉东西。\n香暖狻猊。\n远山郁秀入双眉。\n待看碧桃花烂漫，春日迟迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4865, '菩萨蛮', '毛滂', '玉卮细酌流霞湿。\n金钗翠袖勤留客。\n行色小梅残。\n官桥杨柳寒。\n赐环宣室夜。\n看落金莲。\n人记海听康。\n流风秀水旁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4866, '菩萨蛮', '毛滂', '端端正正人如月。\n孜孜媚媚花如颊。\n花月不如人。\n眉眉眼眼春。\n沈香添小炷。\n共挹熏炉语。\n香解著人衣。\n君心蝴蝶飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4867, '菩萨蛮', '毛滂', '含章檐下眉如月。\n融酥和粉描疏雪。\n桃杏莫争春。\n凌风台畔人。\n如今千万树。\n零乱孤村雨。\n和雨滴瑶觞。\n归来肌骨香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4868, '菩萨蛮', '毛滂', '淡烟疏雨东篱晓。\n菊团凄露真珠小。\n青蕊抱寒枝。\n因谁特故迟。\n曾是骚人盼。\n羞做茱萸伴。\n揉破郁金黄。\n与君些子香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4869, '菩萨蛮', '毛滂', '溪山不尽知多少。\n遥峰秀叠寒波渺。\n携酒上高台。\n与君开壮怀。\n枉做悲秋赋。\n醉後悲何处。\n白发几黄花。\n官裘付酒家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4870, '菩萨蛮', '毛滂', '春潮曾送离魂去。\n春山曾见伤离处。\n老去不堪愁。\n凭阑看水流。\n东风留不住。\n一夜檐前雨。\n明日觅春痕。\n红疏桃杏村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4871, '菩萨蛮', '毛滂', '云山沁绿残眉浅。\n垂杨睡起腰肢软。\n不见玉妆台。\n飞花将梦来。\n行云何事恶。\n雨透罗衣薄。\n不忍湿残春。\n黄莺啼向人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4872, '菩萨蛮', '毛滂', '当时学舞钧天部。\n惊鸿吹下江湖去。\n家住百花桥。\n何郎偏与娇。\n杏梁尘拂面。\n牙板闻莺燕。\n劝客玉梨花。\n月侵钗燕斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4873, '渔家傲', '毛滂', '年少莫寻潜玉老。\n无才无艺烦君笑。\n暖过茅檐霜日晓。\n休起早。\n竹间尽日无人到。\n别径小峰孤碧峭。\n曲沟浅浸寒清绕。\n此老相看情不少。\n浑忘了。\n浑教忘了长安道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4874, '渔家傲', '毛滂', '恰则小庵贪睡著。\n不知风撼梅花落。\n一点儿春吹去却。\n香约略。\n黄蜂犹抱红酥萼。\n绕遍寒枝添索寞。\n却穿竹径随孤鹤。\n守定微官真个错。\n从今莫。\n从今莫负云山约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4875, '渔家傲', '毛滂', '鬓底青春留不住。\n功名薄似风前絮。\n何似瓮头春没数。\n都占取。\n只消一纸长门赋。\n寒日半窗桑柘暮。\n倚阑目送繁云去。\n却欲载书寻旧路。\n烟深处。\n杏花菖叶耕春雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4876, '于飞乐', '毛滂', '水边山，云畔水，新出烟林。\n送秋来、双桧寒阴。\n桧堂寒，香雾碧，帘箔清深。\n放衙隐几，谁知共、云水无心。\n望西园，飞盖夜，月到清尊。\n为诗翁、露冷风清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4877, '于飞乐', '毛滂', '记瞢腾，浓睡里，一片行云。\n未多时、梦破云惊。\n听辘轳，声断也，井底银瓶。\n不知罗带，等闲便、结得同心。\n系画船，杨柳岸，晓月亭亭。\n记阳关、断韵残声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4878, '于飞乐', '毛滂', '并梅兄，双蝶子，烟缕衫轻。\n凤凰钗、缭绕香云。\n淡梳妆，□得恁，雪腻酥匀。\n揉春捻就，更是他、花与精神。\n黛尖低、桃萼破，微笑轻颦。\n早做成、役梦劳魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4879, '阮郎归', '毛滂', '映阶芳草净无尘。\n新晴隔柳阴。\n绿丝步障碧茸茵。\n遮藏欲尽春。\n寒未了，酒须深。\n残花无处寻。\n年来陪尽惜春心。\n闲愁渐不禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4880, '阮郎归', '毛滂', '雨馀烟草弄春柔。\n芳郊翠欲流。\n暖风时转柳花球。\n晴光烂不收。\n红尽处，绿新稠。\n华只暂留。\n却应留下等闲愁。\n令人双鬓秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4881, '虞美人', '毛滂', '游人莫笑东园小。\n莫问花多少。\n一枝半朵恼人肠。\n无限姿姿媚媚、倚斜阳。\n二分春去知何处。\n赖是无风雨。\n更将绣幕密遮花。\n任是东风急性、不由他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4882, '虞美人', '毛滂', '百花赶定东君去。\n知与花何处。\n阳春但更买花栽。\n留住蜂儿蝶子、等君来。\n翠轻绿嫩庭阴好。\n醉便眠芳草。\n春波如酒不曾空。\n谁见东堂日日、自春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4883, '虞美人', '毛滂', '柳枝却学腰肢袅。\n好似江东小。\n春风吹绿上眉峰。\n秀色欲流不断、眼波融。\n檐前月上灯花堕。\n风递馀香过。\n小欢云散已难收。\n到处冷烟寒雨、为君愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4884, '一落索', '毛滂', '月下风前花畔。\n此情不浅。\n欲留风月守花枝，却不道、而今远。\n樯外鹭飞沙晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4885, '散馀霞', '毛滂', '墙头花□寒犹噤。\n放绣帘昼静。\n帘外时有蜂儿，趁杨花不定。\n阑干又还独凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4886, '最高楼', '毛滂', '微雨过，深院芰荷中。\n香冉冉，绣重重。\n玉人共倚阑干角，月华犹在小池东。\n入人怀，吹鬓影，可怜风。\n分散去、轻如云与梦，剩下了、许多风与月，侵枕簟，冷帘栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4887, '最高楼', '毛滂', '新睡起，熏过绣罗衣。\n梳洗了，百般宜。\n东风淡荡垂杨院，一春心事有谁知。\n苦留人，娇不尽，曲眉低。\n漫良夜、月圆空好意，恐落花、流水终寄恨，悲欢往往相随。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4888, '少年游', '毛滂', '遥山雪气入疏帘。\n罗幕晓寒添。\n爱日腾波，朝霞入户，一线过冰檐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4889, '粉蝶儿', '毛滂', '雪遍梅花，素光都共奇绝。\n到窗前、认君时节。\n下重帏，香篆冷，兰膏明灭。\n梦悠扬，空绕断云残月。\n沈郎带宽，同心放开重结。\n褪罗衣、楚腰一捻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4890, '调笑・调笑令', '毛滂', '城月。\n冷罗袜。\n郎睡不知鸾帐揭。\n香凄翠被灯明灭。\n花困钗横时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4891, '调笑・调笑令', '毛滂', '香歇。\n袂红。\n记立河桥花自折。\n隼绀城西阙。\n教妾惊鸿回雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4892, '调笑・调笑令', '毛滂', '无力。\n倚瑶瑟。\n罢舞霓裳今几日。\n楼空雨小春寒逼。\n钿晕罗衫烟色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4893, '调笑・调笑令', '毛滂', '钗冷。\n鬓云晚。\n罗袖拂人花气暖。\n风流公子来应远。\n半倚瑶琴羞懒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4894, '调笑・调笑令', '毛滂', '憔悴。\n何郎地。\n密寄软绡三尺泪。\n传心语眼郎应记。\n翠袖犹芬仙桂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4895, '调笑・调笑令', '毛滂', '何处。\n长安路。\n不记墙东花拂树。\n瑶琴理罢霓裳谱。\n依旧月窗风户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4896, '调笑・调笑令', '毛滂', '芳草。\n恨春老。\n自是寻春来不早。\n落花风起红多少。\n记得一枝春小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4897, '调笑・调笑令', '毛滂', '相望。\n楚江上。\n萦水缭云闻妙唱。\n龙沙醉眼看花浪。\n正要风将月傍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4898, '调笑・调笑令', '毛滂', '酒美。\n从酒贵。\n濯锦江边花满地。\n换得文君醉。\n暖和一团春意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4899, '调笑・调笑令', '毛滂', '花好。\n怕花老。\n暖日和风将养到。\n东君须愿长年少。\n图不看花草草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4900, '感皇恩', '毛滂', '两岁抚邦人，曾无恩意。\n别後何人更相记。\n题舆玉树，愧与蒹葭相倚。\n殷勤犹念我，同吟醉。\n画舸相追，孤城已闭。\n不道扁舟□云外。\n夜分月冷，一段波平风细。\n忆君清兴满，无由寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4901, '感皇恩', '毛滂', '绿水小河亭，朱阑碧。\n江月娟娟上高柳。\n画楼缥缈，尽挂窗纱帘绣。\n月明知我意，来相就。\n银字吹笙，金貂取酒。\n小小微风弄襟袖。\n宝熏浓炷，人共博山烟瘦。\n露凉钗燕冷，更深後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4902, '感皇恩', '毛滂', '多病酒尊疏，饮少辄醉。\n年少衔杯可追记。\n无多酌我，醉倒阿谁扶起。\n满怀明月冷，炉烟细。\n云汉虽高，风波无际。\n何似归来醉乡里。\n玻璃江上，满载春光花气。\n蒲萄仙浪软，迷红翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4903, '临江仙', '毛滂', '闻道长安灯夜好，雕轮宝马如云。\n蓬莱清浅对觚棱。\n玉皇开碧落，银界失黄昏。\n谁见江南憔悴客，端忧懒步芳尘。\n小屏风畔冷香凝。\n酒浓春入梦，窗破月寻人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4904, '相见欢', '毛滂', '十年湖海扁舟。\n几多愁。\n白发青灯今夜、不宜秋。\n中庭树。\n空阶雨。\n思悠悠。\n寂寞一生心事、五更头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4905, '花心动', '刘焘', '偏忆江南，有尘表丰神，世外标格。\n低傍小桥，斜山疏篱，似向陇头曾识。\n暗香孤韵冰雪里，初不怕、春寒要勒。\n问桃杏贤瞒，怎生向前争得。\n省共萧娘笑摘。\n玉纤映琼枝，照人一色。\n澹粉晕酥，多少工夫，到得寿阳宫额。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4906, '八宝妆', '刘焘', '门掩黄昏，画堂人寂，暮雨乍收残暑。\n帘卷疏星门户悄，隐隐严城钟鼓。\n空街烟暝半开，斜日朦胧，银河澄淡风凄楚。\n还是凤楼人远，桃源无路。\n惆怅夜久星繁，碧空望断，玉箫声在何处。\n念谁伴、茜裙翠袖，共携手、瑶台归去。\n对修竹、森森院宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4907, '转调满庭芳・满庭芳', '刘焘', '风急霜浓，天低云淡，过来孤雁声切。\n雁儿且住，略听自家说。\n你是离群到此，我共那人才相别。\n松江岸，黄芦影里，天更待飞雪。\n声声肠欲断，和我也、泪珠点点成血。\n一江流水，流也呜咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4908, '菩萨蛮', '刘焘', '小红桃脸花中笑。\n笑中花脸桃红小。\n垂柳拂帘低。\n低帘拂柳垂。\n袅花风鬓绕。\n绕鬓风花袅。\n归路月沈西。\n西沈月路归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4909, '菩萨蛮', '刘焘', '簟纹双映冰肌艳。\n艳肌冰映双纹簟。\n窗外竹生风。\n风生竹外窗。\n点红潮醉脸。\n脸醉潮红点。\n廊上月昏黄。\n黄昏月上廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4910, '菩萨蛮', '刘焘', '露盘金冷初阑暑。\n暑阑初冷金盘露。\n风细引鸣蛩。\n蛩鸣引细风。\n雨零愁远路。\n路远愁零雨。\n空醉一尊同。\n同尊一醉空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4911, '菩萨蛮', '刘焘', '屑琼霏玉堆檐雪。\n雪檐堆玉霏琼屑。\n山远对眉攒。\n攒眉对远山。\n拆梅寒映月。\n月映寒梅拆。\n阑倚暂愁宽。\n宽愁暂倚阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4912, '菩萨蛮', '刘焘', '湿花春雨如珠泣。\n泣珠如雨春花湿。\n花枕并斜。\n斜并枕花。\n织文回字密。\n密字回文织。\n嗟更数年华。\n华年数更嗟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4913, '菩萨蛮', '刘焘', '润肌饶汗香红沁。\n沁红香汗饶肌润。\n低槛小山围。\n围山小槛低。\n枕横钗坠鬓。\n鬓坠钗横枕。\n归梦与郎期。\n期郎与梦归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4914, '菩萨蛮', '刘焘', '绿窗斜动摇风竹。\n竹风摇动斜窗绿。\n虚恍夕凉初。\n初凉夕恍虚。\n曲眉愁翠蹙。\n蹙翠愁眉曲。\n无雁寄书来。\n来书寄雁无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4915, '菩萨蛮', '刘焘', '雪窗寒听孤灯灭。\n灭灯孤听寒窗雪。\n残漏惜衾闲。\n闲衾惜漏残。\n说时常恨别。\n别恨常时说。\n还不奈宵寒。\n寒宵奈不还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4916, '于飞乐', '宇文元质', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4917, '满庭芳慢・满庭芳', '范致虚', '紫禁寒轻，瑶津冰泮，丽月光射千门。\n万年枝上，甘露惹祥氛。\n北阙华灯预赏，嬉游盛、丝管纷纷。\n东风峭，雪残梅瘦，烟锁凤城春。\n风光何处好，彩山万仞，宝炬凌云。\n尽欢陪舜乐，喜赞尧仁。\n天子千秋万岁，徵招宴、宰府师臣。\n君恩重，年年此夜，长祝本嘉辰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4918, '鹧鸪天', '郑少微', '谁折南枝傍小丛。\n佳人丰色与梅同。\n有花无叶真潇洒，不问胭脂借淡红。\n应未许，嫁春风。\n天教雪月伴玲珑。\n池塘疏影伤幽独，何似横斜酒盏中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4919, '思越人・朝天子', '郑少微', '欲把长绳系日难。\n纷纷从此见花残。\n休将世事兼身事，须看人间比梦间。\n红烛继，艳歌阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4920, '临江仙', '李新', '杨柳梢头春色重，紫骝嘶入残花。\n香风满面日西斜。\n只知闲信马，不觉误随车。\n已许洞天归路晚，空劳眼惜眉怜。\n几回偷为掷花钿。\n今生应已过，重结後来缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4921, '浣溪沙', '李新', '千古人生乐事稀。\n露浓烟事薄寒时。\n菊花须插两三枝。\n未老功名辜两鬓，悲秋情绪入双眉。\n茂陵多病有谁知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4922, '浣溪沙', '李新', '雨霁笼山碧破赊。\n小园围屋粉墙斜。\n朱门闲掩那人家。\n素腕拨香临宝砌，层波窥客擘轻纱。\n隔窗隐隐见簪花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4923, '摊破浣溪沙・山花子', '李新', '几度珠帘卷上钩。\n折花走马向扬州。\n老去不堪寻往事，上心头。\n陶令无聊惟喜醉，茂陵多病不胜愁。\n脉脉春情长不断，水东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4924, '临江仙', '欧阳辟', '涧碧山红粉烂漫，烟萝远映霜枫。\n倚阑人在暮云东。\n遥天垂众壑，平地起孤峰。\n大好家山重九日，尊前切莫匆匆。\n黄花消息雁声中。\n寻芳须未晚，与客且携筇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4925, '黄金缕・蝶恋花', '司马', '家在钱塘江上住。\n花落花开，不管年华度。\n燕子又将春色去。\n纱窗一阵黄昏雨。\n斜插犀梳云半吐。\n檀板清歌，唱彻黄金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4926, '河传', '司马', '银河漾漾。\n正桐飞露井，寒生斗帐。\n芳草梦惊，人忆高唐惆怅。\n感离愁，甚情况。\n春风二月桃花浪。\n扁舟征棹，又过吴江上。\n人去雁回，千里风云相望。\n倚江楼，倍凄怆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4927, '蝶恋花', '王重', '去岁花前曾记有。\n坐醉嬉游，花下携纤手。\n粉面与花相间斗。\n星眸一转晴波溜。\n一见新花还感旧。\n泪眼逢春，忍更看花柳。\n春恨厌厌如永昼。\n□□寂寞黄昏後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4928, '烛影摇红', '王重', '烟雨江城，望中绿暗花枝少。\n惜春长待醉东风，却恨春归早。\n纵有幽情欢会，奈如今、风情渐老。\n凤楼何处，画阑愁倚，天涯芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4929, '失调名', '某两地', '为爱金陵佳丽。\n乃分符来此。\n拥麾忽又向淮东，便咫尺、人千里。\n画鼓一声催起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4930, '浣溪沙', '王采', '雪里东风未过江。\n陇头先折一枝芳。\n如今疏影照溪塘。\n北客乍惊无绿叶，东君应笑不红妆。\n玉真爱著淡衣裳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4931, '渔家傲', '王采', '日月无根天不老。\n浮生总被消磨了。\n陌上红尘常扰扰。\n昏复晓。\n一场大梦谁先觉。\n雒水东流山四绕。\n路傍几个新华表。\n见说在时官职好。\n争信道。\n冷烟寒雨埋荒草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4932, '浣溪沙', '王采', '扇影轻摇一线香。\n斜红匀过晚来妆。\n娇多无事做凄凉。\n借问谁教春易老，几时能勾夜何长。\n旧欢新恨总思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4933, '浣溪沙', '王采', '珠箔随檐一桁垂。\n绣屏遮枕四边移。\n春归人懒日迟迟。\n旧事只将云入梦，新欢重借月为期。\n晚来花动隔墙枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4934, '玉楼春', '王采', '秋闺思入江南远。\n帘幕低垂闲不卷。\n玉珂声断晓屏空，好梦惊回还起懒。\n风轻只觉香烟短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4935, '玉楼春', '王采', '绣屏晓梦鸳鸯侣。\n可惜夜来欢聚取。\n几声低语记曾闻，一段新愁看乍觑。\n繁红洗尽胭脂雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4936, '蝶恋花', '王采', '燕子来时春未老。ピ\n红蜡团枝，费尽东君巧。ピ\n烟雨弄晴芳意恼。ピ\n雨馀特地残妆好。ピ\n斜倚青楼临远道。ピ\n不管傍人，密共东君笑。ピ\n都见娇多情不少。ピ\n丹青传得倾城貌。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4937, '蝶恋花', '王采', '濯锦江头春欲暮。\n枝上繁红，着意留春住。\n只恐东君嫌面素。\n新妆剩把胭脂傅。\n晓梦惊寒初过雨。\n寂寞珠帘，问有馀花否。\n怅望草堂无一语。\n丹青传得凝情处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4938, '蝶恋花', '王采', '艳娇春春婉娩。\n雨惜风饶，学得宫妆浅。\n爱把绿眉都不展。\n无言脉脉情何限。\n花下当时红粉面。\n准拟新年，都向花前见。\n争奈武陵人易散。\n丹青传得闺中怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4939, '蝶恋花', '王采', '镂雪成花檀作蕊。\n爱伴秋千，摇曳东风里。\n翠袖年年寒食泪。\n为伊牵惹愁无际。\n幽艳偏宜春雨细。\n红粉阑干，有个人相似。\n钿合金钗谁与寄。\n丹青传得凄凉意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4940, '蝶恋花', '王采', '晕绿抽芽新叶斗。\n掩映娇红，脉脉群芳後。\n京兆画眉樊素口。\n风姿别是闺房秀。\n新篆题诗霜实就。\n换得琼琚，心事偏长久。\n应是春来初觉有。\n丹青传得厌厌瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4941, '蝶恋花', '王采', '花为年年春易改。\n待放柔条，系取长春在。\n宫样妆成还可爱。\n鬓边斜作拖枝戴。\n每到无情风雨大。\n检点群芳，却是深丛耐。\n摇曳绿萝金缕带。\n丹青传得妖娆态。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4942, '蓦山溪', '周纯', '江南春信，望断人千里。\n魂梦入花枝，染相思、同心并蒂。\n鸳鸯名字，赢得一双双，无限意。\n凝烟水。\n念远教谁寄。\n毫端写兴，莫把丹青拟。\n墨客要卿卿，想临池、等闲梳洗。\n香衣黯淡，元不缁尘，怜缟袂。\n东风里。\n只恐于飞起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4943, '满庭霜・满庭芳', '周纯', '脂泽休施，铅华不御，自然林下真风。\n欲窥馀韵，何处问仙踪。\n路厌横桥夜雪，看暗淡、残月朦胧。\n无言处，丹青莫拟，谁寄染毫工。\n遥通。\n尘外信，寒生墨晕，依约形容。\n似疏疏斜影，蘸水摇空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4944, '菩萨蛮', '周纯', '梅花韵似才人面。\n为伊写在春风扇。\n人面似花妍。\n花应不解言。\n在手微风动。\n勾引相思梦。\n莫用插酴。\n酴羞见伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4945, '瑞鹧鸪', '周纯', '一痕月色挂帘栊。\n梅影斜斜小院中。\n狂醉有心窥粉面，梦魂无处避香风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4946, '西江月', '曹希蕴', '零落不因春雨，吹嘘何假东风。\n纱窗一点自然红。\n费尽工夫怎种。\n有艳难寻腻粉，无香不惹游蜂。\n更阑人静画堂中。\n相伴玉人春梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4947, '踏莎行', '曹希蕴', '解遣愁人，能添喜气。\n些儿好事先施力。\n画堂深处伴妖娆，绛纱笼里丹砂赤。\n有艳难留，无根怎觅。\n几回不忍轻轻别。\n玉人曾向耳边言，花有信、人无的。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4948, '望江南・忆江南', '廖刚', '无诸好，方面镇全闽。\n千骑泛云归洞府，三山明玉外风尘。\n依约是蓬瀛。\n贤刺史，龙虎檀香名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4949, '望江南・忆江南', '廖刚', '无诸好，金地遍重城。\n乌石亭危千嶂合，荔枝楼暖百花明。\n十里暮潮平。\n贤刺史，来暮相欢迎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4950, '满路花・促拍满路花', '廖刚', '雨霁烟波阔，雁度陇云愁。\n西风庭院不胜秋。\n桂华光满，偏照最高楼。\n东山携妓约，故人千里，夜来为舣仙舟。\n明眸皓齿，歌舞总名流。\n恼人情态物中忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4951, '望江南・忆江南', '廖刚', '柯山瑞，云路玉桥横。\n六月天香琼蕊秀，千年人瑞昂星明。\n风露湿麒麟。\n廊庙器，冰雪照精神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4952, '望江南・忆江南', '廖刚', '蓬山晓，龟鹤倚芝庭。\n云覆宝熏迷舞凤，玉扶琼液荐文星。\n棠荫署风清。\n人尽道，天遣瑞升平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4953, '阮郎归', '廖刚', '月桥风槛水边居。\n画楼三鼓初。\n草堂收拾读闲书。\n起看清夜徂。\n闲想像，尽踌躇。\n玉牌金字铺。\n梦昏纵有也成虚。\n那堪和梦无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4954, '蓦山溪', '廖刚', '论长校短，总是非闲誉。\n光景百年中，似难留、长江东去。\n随缘游戏，触□寄高情，西楼月，北窗风，鹆尊前舞。\n故人襟韵，千里心相许。\n飞骑趁花时，正名园、揉风洗雨。\n玻璃潋滟，聊共醉红裙，阳春曲，碧云词，慷慨怀千古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4955, '念奴娇', '赵鼎臣', '旧游何处，记金汤形胜，蓬瀛佳丽。\n渌水芙蓉，元帅与宾僚，风流济济。\n万柳庭边，雅歌堂上，醉倒春风里。\n十年一梦，觉来烟水千里。\n惆怅送子重游，南楼依旧不，朱阑谁倚。\n要识当时，惟是有明月，曾陪珠履。\n量减杯中，雪添头上，甚矣吾衰矣。\n酒徒相问，为言憔悴如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4956, '玉漏迟', '韩嘉彦', '杏香消散尽，须知自昔，都门春早。\n燕子来时，绣陌乱铺芳草。\n蕙圃妖桃过雨，弄笑脸、红筛碧沼。\n深院悄。\n绿杨巷陌，莺声争巧。\n早是赋得多情，更遇酒临花，镇辜欢笑。\n数曲阑干，故国谩劳凝眺。\n汉外微云尽处，乱峰锁、一杆修竹。\n间琅，东风泪零多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4957, '鹊桥仙', '谢', '月胧星淡，南飞乌鹊，暗数秋期天上。\n锦楼不到野人家，但门外、清流叠嶂。\n一杯相属，佳人何在，不见绕粱清唱。\n人间平地亦崎岖，叹银汉、何曾风浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4958, '菩萨蛮', '谢', '雪消新洗寒林碧。\n华堂向晚开瑶席。\n一曲杜韦娘。\n有人空断肠。\n谪仙同夜宴。\n晓即归程远。\n莫放酒尊空。\n主人陈孟公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4959, '菩萨蛮', '谢', '相思一夜庭花发。\n窗前忽认生尘袜。\n晓起艳寒妆。\n雪肌生暗香。\n佳人纤手摘。\n手与花同色。\n插鬓有谁宜。\n惟应潘玉儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4960, '生查子', '谢', '情亲难语离，且尽玻璃盏。\n双鲤有来时，莫使音书缓。\n征骖去若飞，不道家山远。\n相见小冯君，笑语迎归雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4961, '如梦令', '谢', '人似已圆孤月。\n心似丁香百结。\n不见谪仙人，孤负梅花时节。\n愁绝。\n愁绝。\n江上落英如雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4962, '浣溪沙', '谢', '柳絮随风散漫飞。\n檐冰成柱粟生肌。\n力排寒气赖金卮。\n赋丽谁为梁苑客，调高难和郢中词。\n且烦呵笔写乌丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4963, '偷声木兰花', '谢', '景阳楼上钟声晓。\n半面啼妆匀未了。\n斜月纷纷。\n斜影幽香暗断魂。\n玉颜应在昭阳殿。\n却向前村深夜见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4964, '醉蓬莱', '谢', '望晴峰染黛，暮霭澄空，碧天银汉。\n圆镜高飞，又一年秋半。\n皓色谁同，归心暗折，听唳云孤雁。\n问月停杯，锦袍何处，一尊无伴。\n好在南邻，诗盟酒社，刻烛争成，引觞愁缓。\n今夕楼中，继阿连清玩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4965, '减字木兰花', '谢', '江边一树。\n愁绝黄昏谁与度。\n琪树琼枝。\n不受雄蜂取次欺。\n风前望处。\n直恐乘风吹得去。\n能动诗情。\n故与诗人独目成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4966, '减字木兰花', '谢', '寻常三五。\n坐待丹山飞玉兔。\n试问常娥。\n底事清光此夜多。\n尊空客满。\n纵有无处换。\n不倒金荷。\n可奈金波潋滟何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4967, '减字木兰花', '谢', '风篁度曲。\n倦倚银屏初睡足。\n清簟疏帘。\n金鸭香销懒更添。\n纤纤露玉。\n风雹纵横飞钿局。\n颦敛双蛾。\n凝伫无言密意多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4968, '虞美人', '谢', '金钗尽醉何须伴。\n萸糁浮杯乱。\n黄花香返岭梅魂。\n好把一枝斜插、向乌云。\n坡词欲唱无人会。\n桃叶知何在。\n与君同咏一联诗。\n但道老来能趁、菊花时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4969, '虞美人', '谢', '人间离合常相半。\n璧月宁长满。\n九秋风露又方阑。\n何日小窗相对、话悲欢。\n月华临夜宜人醉。\n老去嗟颜悴。\n君如玉树照清空。\n况有凝之道蕴、一尊同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4970, '蝶恋花', '谢', '一水盈盈牛与女。\n目送经年，脉脉无由语。\n後夜鹊桥知暗度。\n持杯乞与开愁绪。\n君似庾郎愁几许。\n万斛愁生，更作征人去。\n留定征鞍君且住。\n人间岂有无愁处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4971, '定风波', '谢', '牛女心期与目成。\n弥弥脉脉得盈盈。\n今夕银河凭鹊度。\n相遇。\n玉钩新吐照云屏。\n行旆雍容留宴语。\n将暮。\n方携珠袖到山亭。\n寂寞江天正云雾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4972, '江神子・江城子', '谢', '破瓜年纪柳腰身。\n懒精神。\n带羞。\n手把江梅，冰雪斗清新。\n不向鸦儿飞处著。\n留乞与，眼中人。\n水精船里酒粼粼。\n皱香茵。\n驻行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4973, '念奴娇', '谢', '绿云影里，把明霞、织就千重文绣。\n紫腻红骄扶不起，好是未开时候。\n半怯新寒，半宜晴色，养得胭脂透。\n小亭人静。\n嫩莺啼破清昼。\n犹记携手芳阴，一枝斜带艳，娇波双秀。\n小语轻怜花总见，争得似花长久。\n醉浅休归，夜深同睡，明月还相守。\n免叫春去，断肠空叹诗瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4974, '满庭芳', '沈蔚', '柳与堤回，桥随波转，望中如在蓬莱。\n水禽高下，烟雾敛还开。\n认是仙翁住处，都不见、一点尘埃。\n壶天晚，清寒带雪，光景自徘徊。\n高才。\n廊庙手，当年平步，直到尧阶。\n况今朝调鼎，尤待盐梅。\n只恐身闲不久，难留恋、花月楼台。\n看新岁，春风且送，五马过江来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4975, '满庭芳', '沈蔚', '雪底寻梅，冰痕观水，晚来天气尤寒。\n渐闻歌笑，轻暖发春妍。\n赏尽十洲新景，依稀见、三岛风烟。\n判深夜，一年月色，只是这般圆。\n熙然。\n千里地，何妨载酒，频上湖船。\n况坐中高客，不日朝天。\n须信人间好处，没个事、胜得尊前。\n东风近，侵寻桃李，别做醉夤缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4976, '满庭芳', '沈蔚', '疏木藏钟，轻烟笼角，几家帘幕灯光。\n暮砧声断，空壁锁寒蜇。\n入袂西风阵阵，彻醉骨、都不胜凉。\n栏干外，依稀嫩竹，月色冷如霜。\n仙乡。\n何处是，云深路杳，不念刘郎。\n但画桥流水，依旧垂杨。\n要见时时便是，一向价、只作寻常。\n争知道，愁肠泪眼，独自个重阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4977, '临江仙', '沈蔚', '过尽清明三月雨，东风才到溪滨。\n画工传得已非真。\n青君著意处，桃李未为伦。\n倚槛盈盈如欲语，就中拈足花神。\n自然亭馆一番新。\n从今观绝品，不独洛阳人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4978, '梦玉人引', '沈蔚', '旧追游处，思前事、俨如昔。\n过尽莺花，横雨暴风初息。\n杏子枝头，又自然、别是般天色。\n好傍垂杨，系画船桥侧。\n小欢幽会，一霎时、光景也堪惜。\n对酒当歌，故人情分难觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4979, '蓦山溪', '沈蔚', '想伊不住。\n船在蓝桥路。\n别语未甘听，更拟问、而今是去。\n门前杨柳，几日转西风，将行色，欲留心，忽忽城头鼓。\n一番幽会，只觉添愁绪。\n邂逅却相逢。\n又还有、此时欢否。\n临岐把酒，莫惜十分斟，尊前月，月中人，明夜知何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4980, '汉宫春', '沈蔚', '别酒初醒。\n似一番梦觉，屈指堪惊。\n犹疑送消寄息，遇著人听。\n当初唤作，据眼前、略略看承。\n及去了，从头想伊，心下始觉宁宁。\n黄昏画角重城。\n更伤高念远，怀抱何胜。\n良时好景，算来半为愁生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4981, '寻梅', '沈蔚', '今年早觉花信蹉。\n想芳心、未应误我。\n一月小径几回过。\n始朝来寻见，雪痕微破。\n眼前大抵情无那。\n好景色、只消些个。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4982, '不见・如梦令', '沈蔚', '日过重帘未卷。\n袅袅欲残香线。\n午醉却醒来，柳外一声莺啭。\n不见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4983, '不见・如梦令', '沈蔚', '回首芜城旧苑。\n还是绿深红浅。\n春意已无多，斜日满帘飞燕。\n不见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4984, '诉衷情', '沈蔚', '深深院宇小池塘。\n一径碧梧长。\n青春又归何处，新笋绿成行。\n多少事，恼人肠。\n懒思量。\n香消一炷，睡起霎时，日过东窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4985, '菩萨・菩萨蛮', '沈蔚', '相逢无处无尊酒。\n尊前未必皆朋旧。\n酒到任教倾。\n莫思今夜醒。\n明朝相别後。\n江上空回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4986, '菩萨・菩萨蛮', '沈蔚', '春城迤逦层阴绕。\n青梅竞弄枝头小。\n江色雨和烟。\n行人江那边。\n好花都过了。\n满地空芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4987, '小重山', '沈蔚', '花过园林清荫浓。\n琅新脱笋，绿丛丛。\n雨声只在小池东。\n闲枕，直面芰荷风。\n长日敞帘栊。\n轻尘飞不到，画堂空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4988, '转调蝶恋花・蝶恋花', '沈蔚', '溪上清明初过雨。\n春色无多，叶底花如许。\n轻暖时闻燕双语。\n等闲飞入谁家去。\n短墙东畔新朱户。\n前日花前，把酒人何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4989, '转调蝶恋花・蝶恋花', '沈蔚', '渐近朱门香夹道。\n一片笙歌，依约楼台杪。\n野色和烟满芳草。\n溪光曲曲山回抱。\n物华不逐人间老。\n日日春风，在处花枝好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4990, '天仙子', '沈蔚', '景物因人成胜概。\n满目更无尘可碍。\n等闲帘幕小栏干，衣未解。\n心先快。\n明月清风如有待。\n谁信门前车马隘。\n别是人间闲世界。\n坐中无物不清凉，山一带。\n水一派。\n流水白云长自在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4991, '倾杯・倾杯乐', '沈蔚', '梅英弄粉。\n尚浅寒、腊雪消未尽。\n布彩箔、层楼高下，灯火万点，金莲相照映。\n香径纵横，听画鼓、声声随步紧。\n渐霄汉无云，月华如水，夜久露清风迅。\n轻车趁马，微尘杂雾，带晓色、绮罗生润。\n花阴下、瞥见仍回，但时闻、笑音中香阵阵。\n奈酒阑人困。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4992, '清商怨', '沈蔚', '城上鸦啼斗转。\n渐渐玉壶冰满。\n月淡寒梅，清香来小院。\n谁遣鸾笺写怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4993, '醉花阴', '沈蔚', '微含清露真珠滴。\n怯晓寒脉脉。\n秉烛倚雕栏，今日尊前，尽是多情客。\n从来应与春相得。\n有动人标格。\n半笑倚春风，醉脸生红，不是胭脂色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4994, '柳摇金・思归乐', '沈蔚', '相将初下蕊珠殿。\n似醉粉、生香未遍。\n爱惜娇心春不管。\n被东风、赚开一半。\n中黄宫里赐仙衣，斗浅深、妆成笑面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4995, '柳初新', '沈蔚', '楚天来驾春相送。\n半醉侧、花冠重。\n瑶台清宴，群仙戏手，剪出彩衣犹动。\n谁拂瑶琴巧弄。\n舞丹山、三千雏凤。\n艳冶轻盈放纵。\n倚东风、从来遍宠。\n桃花溪上，相思未断，愁掩五云真洞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4996, '诉衷情', '唐庚', '平生不会敛眉头。\n诸事等闲休。\n元来却到愁处，须著与他愁。\n残照外，大江流。\n去悠悠。\n风悲兰杜，烟淡沧浪，何处扁舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4997, '浣溪沙', '惠洪', '南涧茶香笑语新。\n西州春涨小舟横。\n困顿人归烂熳晴。\n天迥游丝长百尺，日高飞絮满重城。\n一番花信近清明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4998, '浣溪沙', '惠洪', '日暮江空船自流。\n谁家院落近沧洲。\n一枝闲暇出墙头。\n数朵幽香和月暗，十分归意为春留。\n风撩片片是闲愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (4999, '渔父词・渔父', '惠洪', '玉带云袍童顶露。\n一生笑傲知何故。\n万里归来方旦暮。\n休疑虑。\n大千捏在豪端聚。\n不解犁田分亩步。\n却能对客鸣花鼓。\n忽共老安相耳语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5000, '渔父词・渔父', '惠洪', '不怕石头行路滑。\n归来那爱驹儿踏。\n言下百骸俱拨撒。\n无剩法。\n灵然昼夜光通达。\n古寺天寒还恶发。\n夜将木佛齐烧杀。\n炙背横眠真快活。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5001, '渔父词・渔父', '惠洪', '来往独龙冈畔路。\n杖头落索闲家具。\n後事前观如目睹。\n非谶语。\n须知一念无今古。\n长笑老萧多病苦。\n笑中与药皆狼虎。\n蜡炬一枝非嘱付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5002, '渔父词・渔父', '惠洪', '画饼充饥人笑汝。\n一庵归扫南阳坞。\n击竹作声方省悟。\n徐回顾。\n本来面目无藏处。\n却望沩山敷坐具。\n老师头角浑呈露。\n珍重此恩逾父母。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5003, '渔父词・渔父', '惠洪', '野鹤精神云格调。\n逼人气韵霜天晓。\n松下残经看未了。\n当斜照。\n苍烟风撼流泉绕。\n闺阁珍奇徒照耀。\n光无渗漏方灵妙。\n活计现成谁管绍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5004, '渔父词・渔父', '惠洪', '讲虎天华随玉麈。\n波心月在那能取。\n旁舍老僧偷指注。\n回头觑。\n虚空特地能言语。\n归对学徒重自诉。\n从前见解都欺汝。\n隔岸有山横暮雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5005, '渔父词・渔父', '惠洪', '急雨颠风花信早。\n枝枝叶叶春俱到。\n何待小桃方悟道。\n休迷倒。\n出门无限青青草。\n根不覆藏尘亦扫。\n见精明树唯心造。\n试借疑情看白皂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5006, '渔父词・渔父', '惠洪', '万叠空青春杳杳。\n一蓑烟雨吴江晓。\n醉眼忽醒惊白鸟。\n拍手笑。\n清波不犯鱼吞钓。\n津渡有僧求法要。\n一桡为汝除玄妙。\n已去回头知不峭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5007, '凤栖梧・蝶恋花', '惠洪', '碧瓦笼晴烟雾绕。\n水殿西偏，小立闻啼鸟。\n风度女墙吹语笑。\n南枝破腊应开了。\n道骨不凡江瘴晓。\n春色通灵，医得花重少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5008, '千秋岁', '惠洪', '半身屏外。\n睡觉唇红退。\n春思乱，芳心碎。\n空馀簪髻玉，不见流苏带。\n试与问，今人秀整谁宜对。\n湘浦曾同会。\n手搴轻罗盖。\n疑是梦，今犹在。\n十分春易尽，一点情难改。\n多少事，却随恨远连云海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5009, '青玉案', '惠洪', '绿槐烟柳长亭路。\n恨取次、分离去。\n日永如年愁难度。\n高城回首，暮云遮尽，目断人何处。\n解鞍旅舍天将暮。\n暗忆丁宁千万句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5010, '西江月', '惠洪', '十指嫩抽春笋，纤纤玉软红柔。\n人前欲展强娇羞。\n微露云衣霓袖。\n最好洞天春晚，黄庭卷罢清幽。\n凡心无计奈闲愁。\n试拈花枝频嗅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5011, '西江月', '惠洪', '大厦吞风吐月，小舟坐水眠空。\n雾窗春晓翠如葱。\n睡起云涛正涌。\n往事回头笑处，此生弹指声中。\n玉笺佳句敏惊鸿。\n闻道衡阳价重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5012, '鹧鸪天', '惠洪', '蜜烛花光清夜阑。\n粉衣香翅绕团团。\n人犹认假为真实，蛾岂将灯作火看。\n方叹息，为遮拦。\n也知爱处实难拚。\n忽然性命随烟焰，始觉从前被眼瞒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5013, '清商怨', '惠洪', '一段文章种性。\n更谪仙风韵。\n画戟丛中，清香凝宴寝。\n落日清寒勒花信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5014, '青玉案', '惠洪', '凝祥宴罢闻歌吹。\n画毂走，香尘起。\n冠压花枝驰万骑。\n马行灯闹，凤楼帘卷，陆海龙鳌山对。\n当年曾看天颜醉。\n御杯举，欢声沸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5015, '西江月', '惠洪', '入骨风流国色，透尘种性真香。\n为谁风鬓新妆。\n半树入村春暗。\n雪压枝低篱落，月高影动池塘。\n高情数笔寄微茫。\n小寝初开雾帐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5016, '浪淘沙', '惠洪', '城里久偷闲。\n尘浣云衫。\n此身已是再眠蚕。\n隔岸有山归去好，万壑千岩。\n霜晓更凭阑。\n减尽晴岚。\n微云生处是茅庵。\n试问此生谁作伴，弥勒同龛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5017, '浪淘沙', '惠洪', '山径晚樵远。\n深壑孱颜。\n孙山背後泊船看。\n手把遗编披白帔，剩却清闲。\n篱落竹丛寒。\n渔业凋残。\n水痕无底照秋宽。\n好在夕阳凝睇处，数笔秋山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5018, '水调歌头', '吕颐浩', '一片苍崖璞，孕秀自天锺。\n浑如暖烟堆里，乍放力犹慵。\n疑是犀眠海畔，贪玩烂银光彩，精魄入蟾宫。\n泼墨阴云妒，蟾影淡朦胧。\n沩山颂，戴生笔，写难穷。\n些儿造化，凭谁细与问元工。\n那用牧童鞭索，不入千群万队，扣角起雷同。\n莫怪作诗手，偷入锦囊中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5019, '点绛唇', '苏过', '新月娟娟，夜寒江静山衔斗。\n起来搔首。\n梅影横窗瘦。\n好个霜天，闲却传杯手。\n君知否。\n乱鸦啼後。\n归兴浓如酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5020, '感皇恩', '陆蕴', '残角两三声，催登古道。\n远水长山又重到。\n水声山色，看尽轮蹄昏晓。\n风头日脚下，人空老。\n匹马旧时，西征谈笑。\n绿鬓朱颜正年少。\n旗亭斗酒，任是十千倾倒。\n面今酒兴减，诗情少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5021, '忆君王・忆王孙', '谢克家', '依依宫柳拂宫墙。\n楼殿无人春昼长。\n燕子归来依旧忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5022, '江神子・江城子', '葛胜仲', '昏昏雪意惨云容。\n猎霜风。\n岁将穷。\n流落天涯，憔悴一衰翁。\n清夜小窗围兽火，倾酒绿，借颜红。\n官梅疏艳小壶中。\n暗香浓。\n玉玲珑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5023, '蝶恋花', '葛胜仲', '雨後春光浓似醉。\n著柳催花，节物侵龙忌。\n绣褓香阁当日佩。\n紫兰宫堕人间世。\n歌管停云香吐穗。\n碧酒红裳，共祝鱼轩贵。\n天上阿环金秘。\n龟龄鹤寿三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5024, '蝶恋花', '葛胜仲', '共乐堂深帘不卷。\n恻恻寒轻，二月春犹浅。\n续寿竞来歌舞院。\n龙涎香衬鲛绡段。\n画栋朝飞双语燕。\n端似知人，著意窥金盏。\n柳外花前同祝愿。\n朱颜长在年龄远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5025, '临江仙', '葛胜仲', '郊外黄垓端可厌，归来移病香闺。\n象床珍簟共委蛇。\n耆婆寻草尽，天女散花迟。\n小雨作寒秋意晚。\n檐声与梦相宜。\n冷侵罗幌酒烟微。\n试评书五朵，何似画双眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5026, '渔家傲', '葛胜仲', '岩壑萦回云水窟。\n林深路断迷烟客。\n茅屋数椽携杖舄。\n人寂寂。\n侵檐万个琅碧。\n倦客羁怀清似涤。\n更无一点飞埃迹。\n溪涨慢流过几席。\n寒。\n凫点破琉璃色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5027, '渔家傲', '葛胜仲', '叠叠云山供四顾。\n簿书忙里偷闲去。\n心远地偏陶令趣。\n登览处。\n清幽疑是斜川路。\n野蔌溪毛供饮具。\n此身甘被烟霞痼。\n兴尽碧云催日暮。\n招晚渡。\n遥遥一叶随鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5028, '鹧鸪天', '葛胜仲', '小榭幽园翠箔垂。\n云轻日薄淡秋晖。\n菊英露渊明径，藕叶风吹叔宝池。\n酬素景，泥芳卮。\n老人痴钝强伸眉。\n欢华莫遣笙歌散，归路从教灯影稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5029, '鹧鸪天', '葛胜仲', '婆律香深气味佳。\n玻璃仙碗进流霞。\n凝膏清涤高阳醉，灵液甘和正焙芽。\n香染指，浪浮花。\n加笾礼尽客还家。\n贯珠声断红裳散，踏影人归素月斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5030, '点绛唇', '葛胜仲', '秋晚寒斋，藜床香篆横轻雾。\n闲愁几许。\n梦逐芭蕉雨。\n云外哀鸿，似替幽人语。\n归不去。\n乱山无数。\n斜日荒城鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5031, '行香子', '葛胜仲', '风物飕飕。\n木落沧洲。\n渐老人、不奈悲秋。\n羁怀都在，鬓上眉头。\n似休文瘦，文通恨，子山愁。\n庭梧影薄，篱菊香浮。\n强招寻、聊命朋俦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5032, '诉衷情', '葛胜仲', '清明寒食景暄妍。\n花映碧罗天。\n参差捍拨齐奏，丰颊拥芳筵。\n逢诞日，揖真仙。\n托炉烟。\n朱颜长似，头上花枝，岁岁年年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5033, '水调歌头', '葛胜仲', '夜泛南溪月，光影冷涵空。\n棹飞穿碎金电，翻动水精宫。\n横管何妨三弄，重醑仍须一斗，知费几青铜。\n坐久桂花落，襟袖觉香浓。\n庾公阁，子猷舫，兴应同。\n从来好景良夜，我辈敢情锺。\n但恐仙娥川後，嫌我尘容俗状，清境不相容。\n击汰同情赏，赖有紫溪翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5034, '水调歌头', '葛胜仲', '下濑惊船驶，挥麈恐尊空。\n谁吹尺八寥亮，嚼徵更含宫。\n坐爱金波潋滟，影落蒲萄涨绿，夜漏尽移铜。\n回棹携红袖，一水带香浓。\n坐中客，驰隽辩，语无同。\n青鞋黄帽，此乐谁肯换千锺。\n岩壑从来无主，风月故应长在，赏不待先容。\n羽化寻烟客，家有左仙翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5035, '水调歌头', '葛胜仲', '胜友欣倾盖，羁宦懒书空。\n爱君笔力清壮，名已在蟾宫。\n萧散英姿直上，自有练裙葛帔，岂待半通铜。\n长短作新语，墨纸似鸦浓。\n山吐月，溪泛艇，率君同。\n吾侪轰饮文字，乐不在歌锺。\n今夜长风万里，且倩泓澄浩荡，一为洗尘容。\n世上闲荣辱，都付寒边翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5036, '木兰花・玉楼春', '葛胜仲', '木阑干外池光阔。\n午夜乔林迷岸樾。\n掠船凉吹起青苹，萦水歌声欺白雪。\n檀郎响趁红牙节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5037, '满庭霜・满庭芳', '葛胜仲', '百不为多，一不为少，阿谁昔仕吾邦。\n共推任笔，洪鼎力能扛。\n不为桃花禄米，雠书倦、一苇横江。\n招寻处，徒行曳杖，曾不拥麾幢。\n山川，真大好，鱼矶无恙，密岭难双。\n听讼诉多就，樵坞僧窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5038, '醉蓬莱', '葛胜仲', '望葱葱佳气，虹渚祥开，斗枢光绕。\n析木天津，正灵晖腾照。\n鹭缀分班，象胥交贡，奉御觞清晓。\n玉殿寒轻，金徒漏永，瑞炉烟袅。\n万宇均欢，示慈颁燕，寿祝南山，庆均凫藻。\n缥缈红云，望九重天表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5039, '西江月', '葛胜仲', '羁宦新来作恶，穷途谁肯相从。\n追攀十日水云中。\n情谊知君独重。\n寂寂回廊小院，冥冥细雨尖风。\n凤山香雪定应空。\n昨夜疏枝入梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5040, '西江月', '葛胜仲', '山镇红桃阡陌，烟迷绿水人家。\n尘容误到只惊嗟。\n骨冷玉堂今夜。\n莫对佳人锦瑟，休辞洞府流霞。\n峰回路转乱云遮。\n归去空传图画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5041, '南乡子', '葛胜仲', '柳岸正飞绵。\n选胜斋轻漾碧涟。\n笑语忘怀机事尽，鸥边。\n万顷溪光上下天。\n菰苇久延缘。\n不觉遥峰霭暮烟。\n对酒莫嫌红粉陋，婵娟。\n自有孤高月妇仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5042, '浣溪沙', '葛胜仲', '可惜随风面旋飘。\n直须烧烛看娇娆。\n人间花月更无妖。\n浓丽独将春色殿，繁华端合众芳朝。\n南床应为醉陶陶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5043, '浣溪沙', '葛胜仲', '通白轻红溢万枝。\n浓香百和透丰肌。\n丹山威凤势将飞。\n玉镜台前呈国艳，沈香亭北映朝曦。\n如花惟有上皇妃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5044, '浣溪沙', '葛胜仲', '斗鸭栏边晓路沾。\n华堂醉赏轴珠帘。\n插花人好手纤纤。\n遮护轻寒施翠幄，标题仙品露牙签。\n词人遗恨独江淹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5045, '西江月', '葛胜仲', '山外半规残日，云边一缕馀霞。\n满城飞雪散苕花。\n万顷溪连罨画。\n柳恽风流旧国，鹤龄潇洒人家。\n肯嗟流落在天涯。\n云水从今起价。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5046, '西江月', '葛胜仲', '晚路交游绿酒，平生志趣青霞。\n霜风时节近黄花。\n泛宅舟将画。\n不分两溪明月，夜深只属渔家。\n今朝清赏寄情涯。\n肯向萦涂索价。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5047, '蝶恋花', '葛胜仲', '风过涟漪纹细。\n十指香檀，惊破交禽睡。\n野蔌溪毛真易致。\n风流未减兰亭会。\n击汰千艘供洛禊。\n映水垂杨，万缕拖浓翠。\n小海一声波上戏。\n殷勤留客千金意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5048, '临江仙', '葛胜仲', '自古吴兴称冷僻，菰城水浸粼粼。\n回星难望使车尘。\n如何三日饮，并有五行人。\n文似枚皋加敏速，记书易若张巡。\n幕中无用郄嘉宾。\n他年浮枣会，莫忘两溪春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5049, '临江仙', '葛胜仲', '千古乌程新酿美，玉觞风过粼粼。\n歌声未办起梁尘。\n九天持斧客，来作绣衣人。\n夙有辞华惊乙览，传闻献颂东巡。\n未应握节久宾宾。\n一封驰诏旨，却醉上林春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5050, '临江仙', '葛胜仲', '小样洪河分九曲，飞泉环绕粼粼。\n青莲往事已成尘。\n羽觞浮玉，宝剑捧金人。\n绿绮且依流水调，蓬蓬鼓催巡。\n玉堂词客是佳宾。\n茂林修竹地，大胜永和春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5051, '定风波', '葛胜仲', '千叠云山万里流。\n坐中碧落与鳌头。\n真意见嬉吾已领。\n烟景。\n不辞捧诏久汀洲。\n老去一官真是漫。\n溪岸。\n独馀此兴未能收。\n留与吴儿传胜事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5052, '定风波', '葛胜仲', '共喜新凉大火流。\n一声水调听歌头。\n况有修蛾兼粉领。\n佳景。\n谢公无不碍沦洲。\n平昔短檠真大漫。\n气岸。\n老来都向酒杯收。\n云水光中修禊事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5053, '浣溪沙', '葛胜仲', '今夜风光恋渚苹。\n欲教四角出车轮。\n金钗离立座生春。\n神女恍惊巫峡梦，飞琼原是阆风人。\n诏封後院宠儒臣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5054, '浣溪沙', '葛胜仲', '溪岸沈深属泛苹。\n倾城容貌此推轮。\n可怜虚度二年春。\n暮暮来时骚客赋，朝朝新处後庭人。\n天留花月伴羁臣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5055, '浣溪沙', '葛胜仲', '东道殷勤玉飞。\n华灯倾国拥珠玑。\n玉奴嫌瘦玉环肥。\n缥缈幸闻缑岭曲。\n参差犹隔夏侯衣。\n放开云月出清辉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5056, '瑞鹧鸪', '葛胜仲', '两年人住岂无情。\n别乘辞华四水清。\n何事千锺勤饮饯，故知一别未能轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5057, '浪淘沙', '葛胜仲', '步对东风。\n细探春工。\n百花堂下牡丹丛。\n莫恨使君来便去，不见红。\n雾眼一衰翁。\n无意芳。\n年来结习已成空。\n寄语国香雕槛里，好为人容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5058, '蓦山溪', '葛胜仲', '望云门外。\n油壁如流水。\n空巷逐朱幡，步春风、香河七里。\n冶容炫服，摸石道宜男，穿翠霭，度飞桥，影在清漪里。\n秦头楚尾。\n千古风流地。\n试问汉江边，有解佩、行云旧事。\n主人是客，一笑强颁春，烧灯後，赏花前，遥忆年年醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5059, '蓦山溪', '葛胜仲', '春风野外。\n卵色天如水。\n鱼戏舞绡纹，似出听、新声北里。\n追风骏足，千骑卷高冈，一箭过，万人呼，雁落寒空里。\n天穿过了，此日名穿地。\n横石俯清波。\n竞追随、新年乐事。\n谁怜老子，使得暂遨游，争捧手，乍凭肩，夹道游人醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5060, '减字木兰花', '吴则礼', '团团璧月。\n今夜广寒真秀发。\n何处吹笙。\n催得清霜满凤城。\n淮南好梦。\n镜里星星还种种。\n犹记银床。\n曾为凉洲唤玉觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5061, '减字木兰花', '吴则礼', '淮天不断。\n点缀南云秋几雁。\n白露沾衣。\n始是银屏梦觉时。\n别离怀抱。\n消得镜中青鬓老。\n小字无能。\n烦寄平安一纸书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5062, '减字木兰花', '吴则礼', '斑斑小雨。\n初入高梧黄叶暮。\n又是重阳。\n昨夜西风作许凉。\n鲜鲜丛菊。\n只解凋人双鬓绿。\n试傍清尊。\n分付幽香与断魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5063, '减字木兰花', '吴则礼', '九年离别。\n梦里相逢端怕说。\n携手河梁。\n雁淮天如许长。\n鲈鱼正美。\n白发季鹰聊启齿。\n後夜江干。\n与把梅花子细看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5064, '减字木兰花', '吴则礼', '淮山清夜。\n镜面平铺纤月挂。\n端是生还。\n同倚西风十二栏。\n休论往事。\n投老相逢真梦寐。\n两鬓疏疏。\n好在松江一尺鲈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5065, '满庭芳', '吴则礼', '声促铜壶，灰飞玉，梦惊偷换年华。\n江南芳信，疏影月横斜。\n又喜椒觞到手，宝胜里、仍翦金花。\n钗头燕，妆台弄粉，梅额故相夸。\n隼，人未老，东风袅袅，已傍高牙。\n渐园林月永，叠鼓凝笳。\n小字新传秀句，歌扇底、深把流霞。\n聊行乐，他时画省，归近紫皇家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5066, '满庭芳', '吴则礼', '玉垒尊，清秋关塞，正宜催唤香醪。\n凉风吹帽，横槊试登高。\n相见征西旧事，龙山会、宾主俱豪。\n来群雁，凉生画角，红叶聚亭皋。\n南洲、应好在，长关梦眼，天际云涛。\n有一簪黄菊，两鬓霜毛。\n快把金荷共倒，凝望久、只遣魂消。\n君须听，新翻燕乐，馀韵响檀槽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5067, '木兰花慢', '吴则礼', '尽晴春自老，乍翠、出清流。\n望杳杳飞旌，翩翩戍骑，初过边头。\n幽花尚猗短岸，渐鸣禽、唤友绕行。\n端有雕戈锦领，竟驰袅骅骝。\n凝眸。\n雁入长天，羌管罢、陇云愁。\n共解鞍临水，雷惊电散，雪溅霜浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5068, '醉落魄・一斛珠', '吴则礼', '梅花褪雪。\n赏心莫使慵欢悦。\n大家且恁同攀折。\n馀蕊残英，偏称淡笼月。\n当初相见花初发。\n如今花谢人离缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5069, '踏莎行', '吴则礼', '一片花飞，青春已减。\n可堪南陌红千点。\n生憎杨柳要藏鸦，东风只遣横笳怨。\n看定新巢，初怜语燕。\n游丝正把残英。\n酒尊也会不相违，风光本自同流转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5070, '鹧鸪天', '吴则礼', '永遇英雄际会时。\n垂天鹏翼逐云飞。\n退朝日上青花道，催直霜零赤雁池。\n鸣汉履，侍唐眉。\n渭川莘野晚追随。\n归来仍对金銮老，三峡词源气未衰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5071, '鹧鸪天', '吴则礼', '作赋丁年厌兔园。\n紫微深锁九重关。\n花墩屡赐清闲燕，文石难忘咫尺颜。\n烟外屐，水边山。\n纶巾羽扇五湖间。\n自怜季子貂裘敝，来与机云相对闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5072, '鹧鸪天', '吴则礼', '衮绣三朝社稷臣。\n旧调元鼎斡洪钧。\n垂绅屡转龙墀日，接膝潜回黼座春。\n金凿落，玉麒麟。\n凤鸣良月庆佳辰。\n巨鳌行听扃华禁，又起商周梦卜人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5073, '红楼慢', '吴则礼', '声慑燕然，势压横山，镇西名重榆塞。\n干霄百雉朱阑下，极目长河如带。\n玉垒凉生过雨，帘卷晴岚凝黛。\n有城头、钟鼓连云，殷春雷天外。\n长啸，畴昔驰边骑。\n听陇底鸣笳，风搴双旆。\n霜髯飞将曾百战，欲掳名王朝帝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5074, '声声慢', '吴则礼', '林塘朱夏，雨过斑斑，绿苔绕地初遍。\n叶底雏莺，犹记日斜春晚。\n芙蕖靓妆红粉，傍高荷、闲倚歌扇。\n轻风起，纹滟滟，翠生波面。\n可是追凉月下，清坐久，微云屡遮星汉。\n露湿纶巾，遥望玉清台殿。\n白头共论胜事，须偿五湖深愿。\n南枝好，有南飞乌鹊，绕枝低转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5075, '水龙吟', '吴则礼', '秋生泽国，无边落木，又作萧萧下。\n澄江过雨，凉飙吹面，黄花初把。\n苍鬓羁孤，粗营鸡黍，浊醪催贳。\n对斜斜露脚，寒香正好，幽人去、空惊咤。\n头上纶巾醉堕，要猗眠、水云萦舍。\n牵衣儿女，归来欢笑，仍邀同社。\n月底蓬门，一株江树，悲虫鸣夜。\n把茱萸细看，牛山底事，强成沾洒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5076, '眼儿媚', '李德载', '雪儿魂在水云乡。\n犹忆学梅妆。\n玻璃枝上，体薰山麝，色带飞霜。\n水边竹外愁多少，不断俗人肠。\n如何伴我，黄昏携手，步月斜廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5077, '早梅芳近・早梅芳', '李德载', '深院静，小阑傍。\n标致不寻常。\n尽他桃杏占风光。\n谁敢斗新妆。\n玉堂中，梁苑里。\n休把雪来轻比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5078, '早梅芳近・早梅芳', '李德载', '残腊里，早梅芳。\n春信报新阳。\n晓来枝上斗寒光。\n轻点寿阳妆。\n雪难欺，霜莫妒。\n别是一般风措。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5079, '鹧鸪天', '赵子发', '约略应飞白玉盘。\n明楼渐放满轮寒。\n天垂万丈清光外，人在三秋爽气间。\n闻叶吹，想风鬟。\n浮空仿佛女乘鸾。\n此时不合人间有，尽入嵩山静夜看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5080, '洞仙歌', '赵子发', '荒山明月，下有云来去。\n深夜纤毫静可数。\n问古今底事，留此空光，修月户、犹是当年玉斧。\n思君持羽扇，来伴微吟，水佩风环饮松露。\n待勾漏丹成，约与轻飞，人间世、不知归处。\n更长啸、馀声振林溪，见乱红惊飞，半岩花雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5081, '桃源忆故人', '赵子发', '芳菲已有东风露。\n寒著轻罗未去。\n午夜鸾车鹤驭。\n散入千莲步。\n粉香度曲嬉游女。\n草草相逢无据。\n肠断泪零无数。\n洒作花梢雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5082, '浣溪沙', '赵子发', '疏荫摇摇趁岸移。\n惊鸥点点过帆飞。\n船分水打嫩沙回。\n断梦不知人去处，卷帘还有燕来时。\n日斜风紧转湾西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5083, '南歌子', '赵子发', '天末疑无路，波翻欲御风。\n此身忽在玉壶中。\n醉倒不知、南北与西东。\n猎猎遥鸣草，飕飕静打篷。\n与君回棹碧云浓。\n不是思归、只为酒船空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5084, '南歌子', '赵子发', '人有纫兰佩，云无出岫心。\n扁舟来入碧涛深。\n坐见楚咻、儿女变齐音。\n但醉双瓶玉，从渠六印金。\n此时何处可幽寻。\n风定津头、白日照平林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5085, '点绛唇', '赵子发', '野岸孤舟，断桥明月穿流水。\n雁声嘹呖。\n双落行人泪。\n去岁吾家，曾插黄花醉。\n今那是。\n杖藜西指。\n看即成千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5086, '虞美人', '赵子发', '飞云流水来无信。\n花发年年恨。\n小桃如脸柳如眉。\n记得那人模样、旧家时。\n楼高映步拖金缕。\n香湿黄昏雨。\n如今不见欲凭书。\n门外水平波暖、一双鱼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5087, '惜分飞', '赵子发', '数点雨声惊残暑。\n帘外秋光容与。\n重换熏炉炷。\n渐低罗幕香成雾。\n今夜夜凉情几许。\n莫向屏山取取。\n却笑阳台女。\n楚人空□高唐赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5088, '阮郎归', '赵子发', '马蹄踏月响空山。\n梅生烟壑寒。\n水妃去後泪痕乾。\n天风吹佩兰。\n纫香久，怕花残。\n与君聊据鞍。\n一枝欲寄北人看。\n如今行路难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5089, '忆王孙', '赵子发', '日长高柳一蝉声。\n翡翠帘深宝簟清。\n梦远春云不散情。\n晓风轻。\n玉楝花飞宿雨晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5090, '杨柳枝', '赵子发', '淅淅西风生暮寒。\n绣衣单。\n碧梧叶落藕花残。\n恨前欢。\n月镂虚棂烟逗竹，梦千山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5091, '望江南・忆江南', '赵子发', '新梦断，久立暗伤春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5092, '菩萨蛮', '赵子发', '闲庭草色侵阶绿。\n琐窗午梦人如玉。\n抛枕出罗帏。\n风吹金缕衣。\n怨春风雨恶。\n二月桃花落。\n雨後纵多晴。\n花休春不成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5093, '少年游', '赵子发', '晓山日薄半春阴。\n烟暖柳拖金。\n满眼新晴，歌声妆影，悠荡碧云心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5094, '采桑子', '赵子发', '春蚕昨夜眠方起，闲了罗机。\n共采柔枝。\n桑柘阴阴三月时。\n背人佯笑移金钏，惆怅花期。\n故故留迟。\n独自归来雨满衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5095, '浪淘沙', '赵子发', '约素小腰身。\n不奈伤春。\n疏梅影下晚妆新。\n袅袅娉娉何样似，一缕轻云。\n歌巧动朱唇。\n字字娇嗔。\n桃花深处一通津。\n怅望瑶台清夜月，还送归轮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5096, '念奴娇', '徐俯', '素光练静，照青山隐隐，修眉横绿。\n鹊楼高天似水，碧瓦寒生银粟。\n万丈辉光，奔云涌雾，飞过卢鸿屋。\n更无尘翳，皓然冷浸梧竹。\n因念鹤发仙翁，当时曾共赏，紫岩飞瀑。\n对影三人聊痛饮，一洗闲愁千斛。\n斗转参移，翻然归去，万里骑黄鹄。\n一川霜晓，叫云吹断横玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5097, '浣溪沙', '徐俯', '章水何如颍水清。\n江山明秀发诗情。\n七言还我是长城。\n小小钿花开宝靥，纤纤玉笋见云英。\n十千名酒十分倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5098, '虞美人', '徐俯', '梅花元自江南得。\n还醉江南客。\n雪中雨里为谁香。\n闻道数枝清笑、出东墙。\n多情宋玉还知否。\n梁苑无寻处。\n胭脂为萼玉为肌。\n却恨恼人桃杏、不同时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5099, '卜算子', '徐俯', '心空道亦空，风静林还静。\n卷尽浮云月自明，中有山河影。\n供养及修行。\n旧话成重省。\n豆爆生莲火里时，痛拨寒灰冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5100, '卜算子', '徐俯', '天生百种愁，挂在斜阳树。\n绿叶阴阴占得春，草满莺啼处。\n不见生尘步。\n空忆如簧语。\n柳外重重叠叠山，遮不断、愁来路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5101, '卜算子', '徐俯', '清池过雨凉，暗有清香度。\n缥缈娉婷绝代歌，翠袖风中举。\n忽敛双眉去。\n总是关情处。\n一段江山一片云，又下阳台雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5102, '鹧鸪天', '徐俯', '绿水名园不是村。\n淡妆浓笑两生春。\n笛中已自多愁怨，雨里因谁有泪痕。\n香旖旎，酒氤氲。\n多情生怕落纷纷。\n旧来好事浑如梦，年少风流付与君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5103, '鹧鸪天', '徐俯', '满眼纷纷恰似花。\n飘飘泊泊自天涯。\n雨中添得无穷湿，风里吹成一道斜。\n银作屋，玉为车。\n娥青女过人家。\n应嫌素面微微露，故着轻云薄薄遮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5104, '踏莎行', '徐俯', '素景将阑，黄花初笑。\n登高一望秋天杳。\n邀宾携妓数能来，醉中赢得闲多少。\n佳气氤氲，飞云缥缈。\n竹林更着清江绕。\n高歌屡舞莫催人，华筵直待华灯照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5105, '踏莎行', '徐俯', '画栋风生，绣筵花绕。\n层台胜日频高眺。\n清辉爽气自娱人，何妨称意开颜笑。\n水碧无穷，山青未了。\n斜阳浦口归帆少。\n云鬟烟鬓只供愁，琵琶更作相思调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5106, '踏莎行', '徐俯', '玉露团花，金风破雾。\n高台与上晴空去。\n举杯相属看前山，烟中乱叠青无数。\n皓齿明眸，肌香体素。\n恼人正在秋波注。\n因何欲雨又还晴，歌声遏得行云住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5107, '南歌子', '徐俯', '细蕊黄金嫩，繁花白雪香。\n共谁连璧向河阳。\n自是不须汤饼、试何郎。\n婀娜松髻，轻盈淡薄妆。\n莫令韩寿在伊傍。\n便逐游蜂惊蝶、过东墙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5108, '鹧鸪天', '徐俯', '宜笑宜颦掌上身。\n能歌能舞恶精神。\n脸边红入桃花嫩，眉上青归柳叶新。\n娇不语，易生嗔。\n尊前还是一番春。\n深杯百罚重拚却，只为妖饶醉得人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5109, '浣溪沙', '徐俯', '西塞山前白鹭飞。\n桃花流水鳜鱼肥。\n一波才动万波随。\n黄帽岂如青箬笠，羊裘何似绿蓑衣。\n斜风细雨不须归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5110, '浣溪沙', '徐俯', '新妇矶边秋月明。\n女儿浦口晚潮平。\n沙头鹭宿戏鱼惊。\n青箬笠前明此事，绿蓑衣底度平生。\n斜风细雨小舟轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5111, '鹧鸪天', '徐俯', '西塞山前白鹭飞。\n桃花柳水鳜鱼肥。\n朝廷若觅元真子，晴在长江理钓丝。\n青箬笠，绿蓑衣。\n斜风细雨不须归。\n浮云万里烟波客，惟有沧浪孺子知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5112, '鹧鸪天', '徐俯', '七泽三湘碧草连。\n洞庭江汉水如天。\n朝廷若觅元真子，不在云边则酒边。\n明月棹，夕阳船。\n鲈鱼恰似镜中悬。\n丝纶钓饵都收却，八字山前听雨眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5113, '虞美人', '王安中', '千山青比妆眉浅。\n却奈眉峰远。\n玉人元自不禁秋。\n更算恼伊深处、月当楼。\n分携不见凭阑际。\n只料无红泪。\n万千应在锦回纹。\n嘱付断鸿西去、问行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5114, '浣溪沙', '王安中', '慵整金钗缩指尖。\n晓犹自入疏帘。\n绿窗清冷脸红添。\n妒粉尽饶花六六，回风从斗玉纤纤。\n不成香暖也相兼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5115, '玉楼春', '王安中', '秋鸿只向秦筝住。\n终寄青楼书不去。\n手因春梦有携时，眼到花开无著处。\n泥金小字蛮笺句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5116, '绿头鸭・多丽', '王安中', '魏都雄，凤皇飞观云间。\n佩麟符、荀池元老，暂辞西省仙班。\n憩甘棠、地澄远籁，咏华黍、河卷惊澜。\n碧草萋迷，丹毫冷落，圜扉铃索镇长闲。\n绣筵展、三台星近，锵玉韵珊珊。\n金尊滟、新醅方荐，薄暑初残。\n政成时、欢馀客散，後园朱户休关。\n度秋风、画阑枕水，挂夜月、雕栏骑山。\n锦帐笼香，鸾钗按曲，琵琶双转语绵蛮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5117, '北山移文哨遍・哨遍', '王安中', '世有达人，潇洒出尘，招隐青霄际。\n终始追。\n游览老山栖。\n藐千金、轻脱如屣。\n彼假容江皋，滥巾云岳，缨情好爵欺松桂。\n观向释谈空，寻真讲道，巢由何足相拟。\n待诏书来起便驺驰。\n席次早焚烈芰荷衣。\n敲朴喧喧，牒诉匆匆，抗颜自喜。\n嗟明月高霞，石径幽绝谁回睇。\n空怅猿惊处，凄凉孤鹤嘹唳。\n任列壑争讥。\n众蜂竦诮，林惭涧愧移星岁。\n方浪神京，腾装魏阙，徘徊经过留憩。\n致草堂灵怒蒋侯麾。\n扃岫幌、驱烟勒新移。\n忍丹崖碧岭重滓。\n鸣湍声断深谷，逋客归何计。\n信知一逐浮荣，便丧素守，身成俗士。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5118, '菩萨蛮', '王安中', '中军玉帐旌旗绕。\n吴钩锦带明霜晓。\n铁马去追风。\n弓声惊塞鸿。\n分兵闲细柳。\n金字回飞奏。\n犒饮上恩浓。\n燕然思勒功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5119, '御街行', '王安中', '清霜飞入蓬莱殿。\n别进云裘软。\n却回宸虑念多寒，诏语日边亲遣。\n冰蚕绵厚，金雕锦好，永夜缝宫线。\n红旌绛旆迎星传。\n喜气欢声远。\n庙堂勋旧使台贤，领袖坐中争绚。\n天香馥郁，君恩岁岁，一醉春生面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5120, '鹧鸪天', '王安中', '茜雾红云捧建章。\n鸣珂星使渡银潢。\n亲将圣主如丝语，传与陪都振鹭行。\n香袅袅，佩锵锵。\n升平歌管趁飞觞。\n明时玉帐恩相续，清夜钧天梦更长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5121, '蝶恋花', '王安中', '曲径深丛枝袅袅。\n晕粉揉绵，破蕊烘清晓。\n十二番开寒最好。\n此花不惜春归早。\n青女飞来红翠少。\n特地芳菲，绝艳惊衰草。\n只东风终甚了。\n久长欲伴娥老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5122, '蝶恋花', '王安中', '巧剪明霞成片片。\n欲笑还颦，金蕊依稀见。\n拾翠人寒妆易浅。\n浓香别注唇膏点。\n竹雀喧喧烟岫远。\n晚色溟，六出花飞遍。\n此际一枝红绿眩。\n画工谁写银屏面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5123, '蝶恋花', '王安中', '剪腊成梅天著意。\n黄色浓浓，对萼匀装缀。\n百和薰肌香旖旎。\n仙裳应渍蔷薇水。\n雪径相逢人半醉。\n手折低枝，拥髻云争翠。\n嗅蕊拈枝无限思。\n玉真未洒梨花泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5124, '蝶恋花', '王安中', '青玉一枝红类吐。\n粉颊愁寒，浓与胭脂传。\n辨杏猜桃君莫误。\n天姿不到风尘处。\n云破月来花下住。\n要伴佳人，弄影参差舞。\n只有暗香穿绣户。\n昭华一曲惊吹去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5125, '蝶恋花', '王安中', '雪霁花梢春欲到。\n饯腊迎春，一夜花开早。\n青帝回舆云缥缈。\n鲜鲜金雀来飞绕。\n绣阁纱窗人窈窕。\n翠缕红丝，斗剪幡儿小。\n戴在花枝争笑道。\n愿人常共春难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5126, '蝶恋花', '王安中', '艳夭桃春信漏。\n弄粉飘香，枫叶飞丹後。\n酒入冰肌红欲透。\n无言不许群芳斗。\n楼外何人揎翠袖。\n剪落金刀，插处浓云覆。\n肯与刘郎仙去否。\n武陵回路相思瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5127, '蝶恋花', '王安中', '翠袖盘花金拈线。\n晓炙银簧，劝饮随深浅。\n复幕重帘谁得见。\n馀醺微觉红浮面。\n别唤清商开绮宴。\n玉管双横，抹起梁州遍。\n白苎歌前寒莫怨。\n湘梅萼里春那远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5128, '蝶恋花', '王安中', '千古铜台今莫问。\n流水浮云，歌舞西陵近。\n烟柳有情开不尽。\n东风约定年年信。\n天与麟符行乐分。\n带缓球纹，雅宴催云鬓。\n翠雾萦纡销篆印。\n筝声恰度秋鸿阵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5129, '蝶恋花', '王安中', '未帖宜春双彩胜。\n手点酥山，玉筋人争莹。\n节过日长心自准。\n迟留碧瓦看红影。\n楼外尖风吹鬓冷。\n一望平林，花相映。\n落粉筛云晴未定。\n朝酲只凭阑干醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5130, '一落索', '王安中', '梦破池塘杳杳。\n情随春草。\n尊前风味不胜清，赋白雪、幽兰调。\n秀句银钩争妙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5131, '一落索', '王安中', '欲访瑶台蓬岛。\n烟云缥缈。\n清游却到凤皇池，听檀板、新声妙。\n天上除书催早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5132, '木兰花・玉楼春', '王安中', '尧天雨露承新诏。\n珂马风生趋急召。\n玉符曾将虎牙军，金殿还升龙尾道。\n征西镇北功成早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5133, '玉蝴蝶', '王安中', '御水毂纹风皱，画桥横处，沙路晴时。\n曲坞藏春，朱户翠竹参差。\n过墙花、娇无限思，笼槛柳、低不胜垂。\n海棠枝。\n为东君爱，未敢离披。\n迟迟。\n日华融丽，悠扬丝管，掩冉旌旗。\n喜入繁红，坐来开尽不须吹。\n听莺迁、还思上苑，约凤浴、应展新池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5134, '水龙吟', '王安中', '魏台长乐坊西，画桥倒影烟堤远。\n东风与染，揉蓝春水，湾环清浅。\n浴鹭翘莎，戏鱼吹絮，落红漂卷。\n为游人盛踪，兰舟彩舫，飞轻棹、凌波面。\n乐事年来乍见。\n趁旌旗、谷莺娇啭。\n追随况有，疏帘珠袖，浓香绀。\n萧寺高亭，茂林斜照，且留芳宴。\n看韶华烂向，尊前放手，作梨花晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5135, '临江仙', '王安中', '六六云从龙戏月，天颜带笑尝新。\n年年回首建溪春。\n香甘先玉食，珍宠在枫宸。\n赐品暂醒歌里醉，延和行对台臣。\n宫瓯浮雪乳花匀。\n九重清昼永，宣坐议东巡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5136, '小重山', '王安中', '重举金猊多炷香。\n仙方调绛雪，坐初尝。\n醉鬟娇捧不成行。\n颜如玉，玉碗共争光。\n飞盖莫催忙。\n歌檀临阅处，缓何妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5137, '小重山', '王安中', '椽烛乘珠清漏长。\n醉痕衫袖湿，有馀香。\n红牙双捧旋排行。\n将歌处，相向更催妆。\n明月映东墙。\n海棠花径密，迸流光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5138, '江神子・江城子', '王安中', '荷花遮水水漫溪。\n柳底垂。\n乱蝉嘶。\n舍辔何妨，临水照征衣。\n一扇香风摇不尽，人念远，意凄迷。\n骑鲸仙子已相知。\n数归期。\n赋新诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5139, '徵招调中腔・徵招', '王安中', '红云茜雾笼金阙。\n圣运叶、星虹佳节。\n紫禁晓风馥天香，奏九韶、帝心悦。\n瑶阶万岁蟠桃结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5140, '清平乐', '王安中', '花时微雨。\n未减春分数。\n占取帘疏花密处。\n把酒听歌金缕。\n斜风轻度浓香。\n闲情正与春长。\n向晚红灯入坐，尝新青杏催觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5141, '清平乐', '王安中', '花枝晚。\n过雨红珠转。\n欲共东君论缱绻。\n繁艳休将风卷。\n归来凝思闲窗。\n寒花莫□微觞。\n解慢不成幽梦，燕泥惊落雕梁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5142, '安阳好・忆江南', '王安中', '安阳好，形胜魏西州。\n曼衍山河环故国，升平歌鼓沸高楼。\n和气镇飞浮。\n笼画陌，乔木几春秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5143, '安阳好・忆江南', '王安中', '安阳好，戟户府居雄。\n白昼锦衣清宴处，铁梁丹榭画图中。\n壁记旧三公。\n棠讼悄，池馆北园通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5144, '安阳好・忆江南', '王安中', '安阳好，物外占天平。\n叠叠蓝烟岫色，淙淙鸣玉晚溪声。\n仙路驭风行。\n松路转，丹碧照飞甍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5145, '安阳好・忆江南', '王安中', '安阳好，泮水盛儒宫。\n金字照碑光射斗，芸香书阁势凌空。\n肃肃采芹风。\n来劝学，乡衮首文翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5146, '安阳好・忆江南', '王安中', '安阳好，耆旧迹依然。\n醉白垂杨低掠水，延松高桧老参天。\n曾映两貂蝉。\n王谢族，兰玉秀当年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5147, '安阳好・忆江南', '王安中', '安阳好，负郭相君园。\n绿野移春花自老，平泉醒酒石空存。\n月馆对风轩。\n人选胜，幽径破苔痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5148, '安阳好・忆江南', '王安中', '安阳好，曲水似山阴。\n咽咽清泉岩溜细，弯弯碧篆痕深。\n永昼坐披襟。\n红袖小，歌扇画泥金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5149, '安阳好・忆江南', '王安中', '安阳好，□□又飞。\n拨垅旋栽花密密，著行重接柳依依。\n鸳瓦荡晴辉。\n池面渺，相望是荣归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5150, '安阳好・忆江南', '王安中', '安阳好，千古邺台都。\n穗帐歌人春不见，金楼梦凤夜相呼。\n辇路旧萦纡。\n闲引望，漳水绕城隅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5151, '破子清平乐・清平乐', '王安中', '烟云千里。\n一抹西山翠。\n碧瓦红楼山对起。\n楼下飞花流水。\n锦堂风月依然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5152, '小重山', '王安中', '碧藕花风入袖香。\n涓涓清露，玉肌凉。\n折花无语傍横塘。\n随折处，一寸万丝长。\n还更擘莲房。\n莲心真个苦，似离肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5153, '虞美人', '王安中', '星郎才思生雕管。\n四海声名满。\n尊前新唱更新妍。\n况有玉人相劝、拚酡颜。\n芙蓉幕下同时客。\n年少那重得。\n且寻幽梦赋高唐。\n莫为浮名容易、却相妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5154, '虞美人', '王安中', '清商初入昭华。\n宫叶秋声满。\n草麻初罢月蝉娟。\n想见明朝喜色、动天颜。\n持杯满劝龙头客。\n荣遇时方得。\n词源三峡泻瞿塘。\n便是醉中宣去、也无妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5155, '虞美人', '王安中', '文昌郎自文无比。\n风露行千里。\n试寻天上使星看。\n却见锦衣白昼、过乡关。\n边城落照孤鸿外。\n联璧人相对。\n应吟红叶送清秋。\n向我旧题诗处、更重游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5156, '卜算子', '王安中', '客舍两三花，并脸开清晓。\n一朵涓涓韵已高，一朵纤纤袅。\n谁与插斜红，拥髻争春好。\n此意遥知梦已传，月落前村悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5157, '一落索', '王安中', '塞柳未传春信。\n霜花侵鬓。\n送君西去指秦关，看日近、长安近。\n玉帐同时英俊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5158, '临江仙', '王安中', '凤拨弦鸣夜永，直疑人在浔阳。\n轻云薄雾隔新妆。\n但闻儿女语，倏忽变轩昂。\n且看金泥花那面，指痕微印红桑。\n几多馀暖与真香。\n移船犹自可，卷箔又何妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5159, '浣溪沙', '王安中', '宫缬悭裁翡翠轻。\n文犀松串水晶明。\n风新样称娉婷。\n带笑缓摇春笋细，障羞斜映远山横。\n玉肌无汗暗香清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5160, '卜算子', '王安中', '燕尾道冠儿，蝉翼生衫子。\n枕看书卧北窗，簟展潇湘水。\n团扇弄薰风，皓质添凉意。\n谁与文君作粉真，只此莲花是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5161, '洞仙歌', '王安中', '深庭夜寂，但凉蟾如昼。\n鹊起高槐露华透。\n听曲楼玉管，吹彻伊州，金钏响，轧轧朱扉暗扣。\n迎人巧笑道，好个今宵，怎不相寻暂携手。\n见淡净晚妆残，对月偏宜，多情更、越饶纤瘦。\n早促分飞霎时休，便恰似阳台，梦云归後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5162, '失调名', '王安中', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5163, '点绛唇', '王安中', '岘首亭空，劝君休堕羊碑泪。\n宦游如寄。\n且伴山翁醉。\n说与鲛人，莫解江皋佩。\n将归思。\n晕红萦翠。\n细织回文字。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5164, '菩萨蛮', '王安中', '雨零花昼春杯举。\n举杯春昼花零雨。\n诗令酒行迟。\n迟行酒令诗。\n满斟犹换盏。\n盏换犹斟满。\n天转月光圆。\n圆光月转天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5165, '菩萨蛮', '王安中', '绿笺长写新成曲。\n曲成新写长笺绿。\n豪句逞才高。\n高才逞句豪。\n美容歌皓齿。\n齿皓歌容美。\n香篆小花团。\n团花小篆香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5166, '菩萨蛮', '王安中', '玉纤传酒浮香菊。\n菊香浮酒传纤玉。\n弦管沸欢筵。\n筵欢沸管弦。\n出帘珠袖蔌。\n蔌袖珠帘出。\n眉晕浅山低。\n低山浅晕眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5167, '菩萨蛮', '王安中', '浦烟迷处回莲步。\n步莲回处迷烟浦。\n罗绮媚横波。\n波横媚绮罗。\n细眉双拂翠。\n翠拂双眉细。\n歌意任情多。\n多情任意歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5168, '点绛唇', '张继先', '小小葫芦，生来不大身材矮。\n子儿在内。\n无口如何怪。\n藏得乾坤，此理谁人会。\n腰间带。\n臣今偏爱。\n胜挂金鱼袋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5169, '忆桃源', '张继先', '长生之话口相传。\n求丹金液全。\n混成一物作神仙。\n丁宁说与贤。\n休咽气，莫胡言。\n岂知造化玄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5170, '忆桃源', '张继先', '白云堆里采芙蓉。\n枝枝香艳浓。\n灵龟畔岸起祥风。\n楼高十二重。\n黄金殿，碧云笼。\n丹砂透顶红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5171, '临江仙', '张继先', '莫怪精神都素淡，全谙千载松头。\n羽人幽意苦相投。\n殷勤争点写，展转动吟酬。\n况有咸阳兄弟事，教人闻见忘忧。\n我生曾是眷仙标。\n一从挥洒後，相继未能休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5172, '临江仙', '张继先', '自古清真灵妙降，安妃来就杨君。\n因缘冥会异常伦。\n仙风聊设相，真道本无亲。\n惟有元规能访问，深将此意相闻。\n大家宜赏缀新文。\n免教尘世士，诮笑上天人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5173, '临江仙', '张继先', '蠢动含灵天赋与，逍遥性分元均。\n莫生异见乱吾真。\n只今中有主，浑与化为人。\n那更徽词清彻底，轻埃欲染无因。\n惟应得此便凝神。\n百魔咸息战，六道永停轮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5174, '沁园春', '张继先', '劫运将新，天书降恩，圣师命魔。\n正阴阳错忤，鬼神淆混，依凭城市，绵亘山河。\n杀气闭空，阴容夺昼，万姓罹殃日已多。\n青城上，见琉璃高座，忽起巍峨。\n群妖忿怒扬戈。\n竞奔走、攻山若舞梭。\n感神光一瞬，龙催虎陷，威音一动，电掣霆呵。\n立活化民，摄邪归正，生息熙熙享太和。\n风云静，见天连碧汉，月浸澄波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5175, '沁园春', '张继先', '真一长存，太虚同体，妙门自开。\n既混元初判，两仪布景，复还根本，全籍灵台。\n浩气冲开，谷神滋化，渐觉神光空际来。\n幽绝处，听龙吟虎啸，蓦地风雷。\n奇哉。\n妙道难猜。\n鲜点化、愚迷成大材。\n试与君说破，分明状似，蚌含渊月，秋兔怀胎。\n壮志男儿，当年高士，莫把身心惹世埃。\n功成後，任身居紫府，名列仙阶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5176, '沁园春', '张继先', '急急修行，细算人生，能有几时。\n任万般千种风流好，柰一朝身死，不免抛离。\n蓦地思量，死生事大，使我心如刀剑挥。\n难留住，那金乌箭疾，玉兔梭飞。\n早觉悟、莫教迟。\n我清净、谁能婚少妻。\n便假饶月里，娥见在，从他越国，有貌西施。\n此个风流，更无心恋，且放宽怀免是非。\n蓬莱路，仗三千行满，独跨鸾归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5177, '沁园春', '张继先', '况有夷途，正透元关，众所共传。\n愿万魔披散，诸尘荡尽，琴心和雅，天性清圆。\n未信凡流，可回高步，留恋形声情更延。\n真消息，定如何唤醒，聊证言诠。\n虽由宿命因缘。\n达士何曾无慨然。\n算尽专为妙，闲多乐少，一成潇洒，永绝忧煎。\n影照澄潭，声流虚谷，业火消亡睹瑞莲。\n安平泰，看坚完如地，长久如天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5178, '满庭芳', '张继先', '闲里工夫，无中妙用，切休拟议参详。\n龙降虎伏，真土自中黄。\n行动起居寝食，随缘度、莫动真阳。\n归根处，神凝脉住，玉界发天光。\n风高，鹏翼远，水深舟运，物理昭彰。\n但明心是道，专役天罡。\n信口呼神招鬼，和谷、不是颠狂。\n痴迷者，风霆在手，应用反乖张。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5179, '满庭芳', '张继先', '心境双清，古今同乐，胜缘休道无媒。\n天门高妙，应仗至人开。\n岂比寻常意绪，方寸地、不贮纤埃。\n仍须信，金坚石确，一志断无回。\n真元，真可爱，真师真友，且喜无猜。\n就中更脱洒，不顾形骸。\n可是正容而悟，凭真趣、改易凡胎。\n神明会，尘缨世网，莫共话由来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5180, '满庭芳', '张继先', '调理三关，安和四体，静无忧扰相煎。\n太微冥契，元始语诸仙。\n玉宇重修妙典，西台□、南岳题篇。\n崇□好，身田在世，心向太清天。\n云边。\n曾降圣，金坛夜拜，高驾留连。\n论琼华灵液，形与神全。\n形体须凭妙气，神来舍、黄阙丹田。\n真精旨，明光辅相，天地保长年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5181, '洞仙歌', '张继先', '孤峰绝顶，更无人能到。\n万里虚空没边徼。\n正秋高景静，雾扫云收，风露里，惟有月华高照。\n浮生纷过客，好天良夜，醉舞狂歌错昏晓。\n有谁知、一性圆满恒河，亘万古、光明不老。\n竞对月、论利与谈名，全不想驹阴，暗催年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5182, '渔家傲', '张继先', '草草开尊资一笑。\n微生病苦随缘了。\n友义交情如地厚。\n心相照。\n今人莫遣前人诮。\n灯火荧荧山悄悄。\n芝兰佳气松筠茂。\n得便盘桓尘世表。\n香初透。\n邻鸡且莫催清晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5183, '更漏子', '张继先', '固元精，收听视。\n物外身无此地。\n接子谬，季真非。\n无为翻有为。\n但心虚，教腹实。\n密与寥天为一。\n华阳洞，广寒宫。\n人人方寸中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5184, '更漏子', '张继先', '是和非，双打过。\n免共相魔生火。\n谈有相，损顽空。\n斋居看望中。\n圣贤风，行处在。\n巧智争如休卖。\n诗与酒，且乘闲。\n随缘发笑颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5185, '更漏子', '张继先', '诵真经，期万过。\n未灭无明心火。\n宜回首，探真空。\n融怡淡漠中。\n自古人，何处在。\n谩记声名沽卖。\n抛尘累，养清闲。\n琼浆自驻颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5186, '瑶台月', '张继先', '天开景运。\n记建武中兴，炎刘重盛。\n明良际会，八表风调雨顺。\n任一时、岳降生申，正千载、河清诞圣。\n祥云拥，流霞映。\n飞仙拱，魁星炯。\n佳应是、师真毓瑞，人天交庆。\n蘅薇香满元宵景。\n耀天目、神光如镜。\n见龙章凤质，降伏群魔归正。\n禀玄元、立教开先，悟至道、心空神领。\n昌元嗣，明真镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5187, '喜迁莺', '张继先', '深源密坞，问牧竖樵童，俱迷方所。\n蓬纵横，龙蛇出没，玉峡搀空无路。\n不恋雁塔荣名，解守鱼渊寒素。\n这勤苦。\n但坚心自有，神灵呵护。\n猛悟。\n无回顾。\n一点虚明，万劫无今古。\n胎息根深，灵泉穴秘，静里运调阳火。\n莫问地久天长，管取收因结果。\n休轻负。\n把天谷真机，与君说破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5188, '喜迁莺', '张继先', '情缠识缚，欢时人不悟，酒中真乐。\n纵欲招愆，迷心失行，却道为他狂药。\n须信醉舞狂歌，也有良知真觉。\n无倚泊。\n任暖气同流，三关三络。\n落魄。\n清闲客。\n醉乡深处，风月长酬酢。\n空花消亡，光明显露，人我自皆忘却。\n不问市酝村醪，尽可浅斟低酌。\n从鄙薄。\n竞口口谈醒，言言成错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5189, '雪夜渔舟', '张继先', '晚风歇。\n谩自棹扁舟，顺流观雪。\n山耸瑶峰，林森玉树，高下尽无分别。\n性情澄彻。\n更没个、故人堪说。\n恍然身世，如居天上，水晶宫阙。\n万尘声影绝。\n透尘空无外，水天相接。\n浩气冲盈，真宫深厚，永夜不愁寒冽。\n愧怜鄙劣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5190, '春从天上来', '张继先', '王土平平。\n正海息波澜，岳敛云烟。\n三景虚明，八表澄清，一月普照诸天。\n有流霞洞焕，映黍珠、徐下空玄。\n绝形言。\n见千真拱极，万气朝元。\n当时鹤鸣夜半，感真符宝篆，特地清传。\n碧湛龙文，红凝龟篆，绛衣舞鬣蹁跹。\n计功成果就，无真教、郭景飞仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5191, '风入松', '张继先', '深耕易耨寸田中。\n看真个英雄。\n夜来犹上星台望，全不厌、水绿云红。\n便是清交素友，频相视、笑晴空。\n玉阶瑶翠重重。\n带萱草葱葱。\n流霞尽饮何辞醉，更休数、尘里千锺。\n晓夜朝元去也，怎忍舍、大夫松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5192, '摸鱼儿', '张继先', '甚山灵、斗奇夸巧，悬峰遥献形似。\n仓船炉灶无封闭，零落车罗机履。\n山临水。\n任瓮杵、辘轳厩架俱闲毁。\n床棺尘委。\n更乐隐棋休，料闲真隐，三教忘宾主。\n人都语，二十四岩佳致。\n来往溯流观指。\n目前景相纷虚幻，神仙家在何许。\n君莫取。\n这身世、山林朝市随缘遇。\n休论诡异。\n但总绝情缘，一空妍丑，觌面先寻你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5193, '惜时芳・思归乐', '张继先', '虚心劲节争萧散。\n无冬夏、钩阑侧畔。\n霜风雪色沈沈晚。\n残不了、细枝纤干。\n情中意里尘沙恨。\n试与聆、弦歌急慢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5194, '清平乐', '张继先', '天先天後。\n真土藏灵秀。\n妙用自然循火候。\n节节薰教透。\n不分龙麝檀沈。\n都能入鼻通心。\n待得烟消息住，浑身变见真金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5195, '苏幕遮', '张继先', '先天生，後天久。\n道有真诠，谛听当时受。\n恰是迷天迷望斗。\n只恐微躯，薄幸随枯朽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5196, '苏幕遮', '张继先', '抱孤琴，弹小操。\n独坐幽轩，尽日无人到。\n惟乐烟霞长啸傲。\n明月清风，今古长为道。\n识乾坤，知牝牡。\n懒共尘劳，汨汨争奔走。\n爱杀高眠消白昼。\n一任他家，玉兔金乌走。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5197, '西江月', '张继先', '蓬户横开岑寂，寒窗侧映清晖。\n竹风偷入五香帏。\n还有好音相惠。\n须信毫芒可入，明珠胎里忘机。\n宵征夜宴是和非。\n月府仙人无愧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5198, '南乡子', '张继先', '无奈这群迷。\n味色声中若系羁。\n尽任改头兼换面，何悲。\n不染伊时不管伊。\n春去又秋兮。\n莫遣空逾十二时。\n好把自然真妙旨，修为。\n尘事萦仍道甚希。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5199, '南乡子', '张继先', '久不上春台。\n直待将身跨九垓。\n懒向人间深有谓，氛埃。\n难趁邪风伤圣胎。\n水栏映山斋。\n赏遍从容首自回。\n长谢故人书曲意，徽哉。\n赢得腰琴拂袂来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5200, '望江南・忆江南', '张继先', '楸枰静，黑白两奁均。\n山水最宜情共乐，琴书赢得道相亲。\n一局一番新。\n松影里，轻度几回春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5201, '望江南・忆江南', '张继先', '西源好，仙构占仙峰。\n一鹤性灵清我宇，万龙风雨乱霜空。\n高静太疏慵。\n天地乐，山水静流通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5202, '望江南・忆江南', '张继先', '西源好，龙首虎头高。\n风雨每掀清宇宙，林峦长似涌波涛。\n吟咏有诗豪。\n成大乐，美称适相遭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5203, '望江南・忆江南', '张继先', '西源好，岩馆凿松。\n五斗洞前斟玉，半酣窗外抚金杯。\n无累自悠哉。\n青翠色，玉竹自新栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5204, '望江南・忆江南', '张继先', '西源好，春日日初长。\n不看人间三月景，常思天上万花香。\n幽赏一时狂。\n歌笑也，空洞大歌章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5205, '望江南・忆江南', '张继先', '西源好，迎夏洒炎风。\n红锦石边怜一派，老张岩上恋群峰。\n时得化龙筇。\n琴振玉，晓色倚梧桐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5206, '望江南・忆江南', '张继先', '西源好，秋景道人怜。\n时至自然天气肃，夜凉犹喜月华圆。\n长啸碧崖颠。\n须信酒，难别咏歌边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5207, '望江南・忆江南', '张继先', '西源好，冬日雪中松。\n携手石坛承爱景，静观天地入清宫。\n恰似大茅峰。\n襟袂冷，琴里意浓浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5208, '望江南・忆江南', '张继先', '西源好，幽径不成斜。\n山谷隐连无改色，池塘空静默无瑕。\n人钓水之涯。\n仙舫小，人欲盼君家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5209, '望江南・忆江南', '张继先', '西源好，神洞自相求。\n傍水垦田流涧急，砍山开径小花浮。\n踪迹旧人留。\n忘万物，爽气白云收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5210, '望江南・忆江南', '张继先', '西源好，人在水晶宫。\n长愿玉津名濯鼎，恰如龙井到天峰。\n的的好遗风。\n清彻底，岂忤李唐隆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5211, '望江南・忆江南', '张继先', '西源好，雨霁敛红纱。\n碧水静摇招钓叟，绿苔寒迫起渔家。\n携驾会春茶。\n风浩浩，锦荫石屏华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5212, '望江南・忆江南', '张继先', '西源好，还向观庭西。\n拚晚菊明方丈外，傍寒梅放六花飞。\n三鹤会同时。\n清净宇，处一贯无为。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5213, '减字木兰花', '张继先', '严寒冬月。\n前日阳生几降雪。\n松柏凌霄。\n森耸庭中叹後凋。\n昔人犹豫。\n身入山林深静处。\n今古同符。\n好趁笙歌且自娱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5214, '江神子・江城子', '张继先', '彩云楼阁瑞烟平。\n雨初晴。\n月胧明。\n夜静天风，吹下步虚声。\n何处朝元归去晚，双凤小，五云轻。\n落花流水两关情。\n恨无凭。\n梦难成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5215, '鹊桥仙', '张继先', '神清心妙，山长水远，有分何年瞻望。\n晴空一月彩云飞，又起我、无穷想像。\n一阳门径，九华恩露，惟愿分明指向。\n竹风频起紫微烟，似有意、许归吾党。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5216, '水调歌头', '张继先', '高真留妙诀，达士济群迷。\n心清行洁，天人凡圣尽皈依。\n不在搬精运气，不在飞罡蹑斗，心乱转狐疑。\n但要除邪妄，心地合神祗。\n悟真空，离世网，绝关机。\n养吾浩气，驱雷役电震天威。\n混合百神归一，一念通天彻地，方始了无为。\n叱咤生风雨，玩世挟明时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5217, '度清霄', '张继先', '一更一点一更初。\n城门半掩行人疏。\n茅庵潇洒一事无。\n孤灯相对光清虚。\n蒲团安稳身不拘。\n跏趺大坐心如如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5218, '度清霄', '张继先', '二更二点二更深。\n宫锺声绝夜沈沈。\n明月满天如写金。\n同光共影无昏沈。\n起来闲操无弦琴。\n声高调古惊人心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5219, '度清霄', '张继先', '三更三点三更中。\n烟开雾敛静无风。\n月华迸入水晶宫。\n四方上下同一空。\n光明遍转华胥同。\n千古万古无初终。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5220, '度清霄', '张继先', '四更四点四更长。\n迎午迸鼠心不忙。\n丹炉伏火生新香。\n群阴剥尽回真阳。\n金娥木父欢相当。\n醍醐次进无停觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5221, '度清霄', '张继先', '五更五点五更残。\n青冥风露逼人寒。\n扶桑推出红银盘。\n城门依旧声尘喧。\n明暗二景交相转。\n生来死去纷易换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5222, '度清霄', '张继先', '独自行兮独自坐。\n独自歌兮独自和。\n日日街头走一过。\n我不识吾谁识我。\n人间旦暮自四时。\n玄中消息不推移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5223, '望江南・忆江南', '张继先', '秋夜事，月里竹亭亭。\n清籁与谁喧池水，微风遣我下檐楹。\n圆缺若为情。\n终南道，累寄笑歌声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5224, '贺新郎', '叶梦得', '睡起啼莺语。\n掩青苔、房栊向晚，乱红无数。\n吹尽残花无人见，惟有垂杨自舞。\n渐暖霭、初回轻暑。\n宝扇重寻明月影，暗尘侵、尚有乘鸾女。\n惊旧恨，遽如许。\n江南梦断横江渚。\n浪黏天、葡萄涨绿，半空烟雨。\n无限楼前沧波意，谁采苹花寄取。\n但怅望、兰舟容与。\n万里云帆何时到，送孤鸿、目断千山阻。\n谁为我，唱金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5225, '水调歌头', '叶梦得', '渺渺楚天阔，秋水去无穷。\n两淮不辨牛马，轻浪舞回风。\n独倚高台一笑，圉圉游鱼来往，还戏此波中。\n危栏对千里，落日照澄空。\n子非我，安知我，意真同。\n鹏飞鲲化何有，沧海漫冲融。\n堪笑溪遣老，白首直钩溪畔，岁晚忽衰翁。\n功业竟安在，徒自兆非熊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5226, '水调歌头', '叶梦得', '霜降碧天静，秋事促西风。\n寒声隐地，初听中夜入梧桐。\n起瞰高城回望，寥落关河千里，一醉与君同。\n叠鼓闹清晓，飞骑引雕弓。\n岁将晚，客争笑，问衰翁。\n平生豪气安在，沈领为谁雄。\n何似当筵虎士，挥手弦声响处，双雁落遥空。\n老矣真堪愧，回首望云中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5227, '水调歌头', '叶梦得', '江海渺千里，飘荡叹流年。\n等闲匹马相过，乘兴却け然。\n十载悲欢如梦，抚掌惊呼相语，往事尽飞烟。\n此会真难偶，此醉且留连。\n酒方半，谁轻使，动离弦。\n我歌未阕公去，明日复山川。\n空有高城危槛，缥缈当筵清唱，馀响落尊前。\n细雨黄花後，飞雁点遥天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5228, '水调歌头', '叶梦得', '修眉扫遥碧，清镜走回流。\n堤外柳烟深浅，碧瓦起朱楼。\n分付平云千里，包卷骚人遗思，春色入帘钩。\n桃李尽无语，波影动兰舟。\n念谢公，平生志，在沧洲。\n登临漫怀风景，佳处每难酬。\n却叹从来贤士，如我与公多矣，名迹竟谁留。\n惟有尊前醉，何必问消忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5229, '水调歌头', '叶梦得', '今古几流转，身世两奔忙。\n那知一丘一壑，何处不堪藏。\n须信超然物外，容易扁舟相踵，分占水云乡。\n雅志真无负，来日故应长。\n问骐骥，空矫首，为谁昂。\n冥鸿天际，尘事分付一轻芒。\n认取骚人生此，但有轻蓬短楫，多制芰荷裳。\n一笑陶彭泽，千载贺知章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5230, '水调歌头', '叶梦得', '河汉下平野，香雾卷西风。\n倚空千嶂横起，银阙正当中。\n常恨年年此夜，醉倒歌呼谁和，何事偶君同。\n莫恨岁华晚，容易感梧桐。\n揽清影，君试与，问天公。\n遥知玉斧初斫，重到广寒宫。\n付与孤光千里，不遣微云点缀，为我洗长空。\n老去狂犹在，应未笑衰翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5231, '水调歌头', '叶梦得', '秋色渐将晚，霜信报黄花。\n小窗低户深映，微路绕斜。\n为问山翁何事，坐看流年轻度，拚却鬓双华。\n徙倚望沧海，天净水明霞。\n念平昔，空飘荡，遍天涯。\n归来三径重扫，松竹本吾家。\n却恨悲风时起，冉冉云间新雁，边马怨胡笳。\n谁似东山老，谈笑静胡沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5232, '八声甘州', '叶梦得', '故都迷岸草，望长淮、依然绕孤城。\n想乌衣年少，芝兰秀发，戈戟云横。\n坐看骄兵南渡，沸浪骇奔鲸。\n转盼东流水，一顾功成。\n千载八公山下，尚断崖草木，遥拥峥嵘。\n漫云涛吞吐，无处问豪英。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5233, '八声甘州', '叶梦得', '又新正过了，问东风、消息几时来。\n笑春工多思，留连底事，犹未轻回。\n应为瑶刀裁翦，容易惜花开。\n试向湖边望，几处寒梅。\n好是绿莎新径，剩安排芳意，特地重栽。\n便从今追赏，莫遣暂停杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5234, '八声甘州', '叶梦得', '问浮家泛宅，自玄真、去後有谁来。\n漫烟波千顷，云峰倒影，空翠成堆。\n可是溪山无主，佳处却徘徊。\n暮雨卷晴野，落照天开。\n老去馀生江海，伴远公香火，犹有宗雷。\n便何妨元亮，携酒间相陪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5235, '八声甘州', '叶梦得', '寄知还倦鸟，对飞云、无心两难齐。\n漫飘然欲去，悠然且止，依旧山西。\n十亩荒园未遍，趁雨却锄犁。\n敢忘邻翁约，有酒同携。\n况是岩前新创，带小轩横绝，松桂成蹊。\n试凭高东望，云海与天低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5236, '念奴娇', '叶梦得', '故山渐近，念渊明归意，け然论谁。\n归去来兮秋已老，松菊三径犹存。\n稚子欢迎，飘飘风袂，依约旧衡门。\n琴书萧散，更欣有酒盈尊。\n惆怅萍梗无根，天涯行已遍，空负田园。\n去矣何之窗户小，容膝聊倚南轩。\n倦鸟知还，晚云遥映，山气欲黄昏。\n此还真意，故应欲辨忘言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5237, '念奴娇', '叶梦得', '洞庭波冷，望冰轮初转，沧海沈沈。\n万顷孤光云阵卷，长笛吹破层阴。\n汹涌三江，银涛无际，遥带五湖深。\n酒阑歌罢，至今鼍怒龙吟。\n回首江海平生，漂流容易散，佳期难寻。\n缥缈高城风露爽，独倚危栏重临。\n醉倒清尊，娥应笑，犹有向来心。\n广寒宫殿，为予聊借琼林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5238, '念奴娇', '叶梦得', '云峰横起，障吴关三面，真成尤物。\n倒卷回潮目尽处，秋水黏天无壁。\n绿鬓人归，如今虽在，空有千茎雪。\n追寻如梦，满馀诗句犹杰。\n闻道尊酒登临，孙郎终古恨，长歌时发。\n万里云屯瓜步晚，落日旌旗明灭。\n鼓吹风高，画船遥想，一笑吞穷发。\n当时曾照，更谁重问山月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5239, '满庭芳', '叶梦得', '麦陇如云，清风吹破，夜来疏雨才晴。\n满川烟草，残照落微明。\n缥渺危栏曲槛，遥天尽、日脚初平。\n青林外，参差暝霭，萦带远山横。\n孤城。\n春雨过，绿阴是处，时有莺声。\n问落絮游丝，毕竟何成。\n信步苍苔绕遍，真堪付、闲客闲行。\n微吟罢，重回皓首，江海渺遗情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5240, '满庭芳', '叶梦得', '枫落吴江，扁舟摇荡，暮山斜照催晴。\n此心长在，秋水共澄明。\n底事经年易判，惊遗恨、悄悄难平。\n临风处，佳人万里，霜笛与谁横。\n长城。\n谁敢犯，知君五字，元有诗声。\n笑茅舍何时，归计真成。\n绿鬓朱颜老尽，柴车在、行即终行。\n聊相待，狂歌醉舞，虽老未忘情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5241, '满庭芳', '叶梦得', '一曲离歌，烟村人去，马头微雪新晴。\n隔年光景，回首近清明。\n断送残花又老，春波净、湖水初平。\n谁重到，雕阑尽日，遥想画桥横。\n高城。\n凝望久，何人为我，重唱馀声。\n问桃李如今，几处阴成。\n老去从游似梦，尊前事、空有经行。\n犹能记，殷勤寄语，多谢故人情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5242, '满江红', '叶梦得', '一朵黄花，先催报、秋归消息。\n满芳枝凝露，为谁装饰。\n便向尊前拚醉倒，古今同是东篱侧。\n问何须、特地赋归来，抛彭泽。\n回首去，年时节。\n开口笑，真难得。\n史君今郡更，自成行客。\n霜鬓不辞重插满，他年此会何人忆。\n记多情、曾伴小阑干，亲攀摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5243, '满江红', '叶梦得', '雪後郊原，烟林静、梅花初坼。\n春欲半，犹自探春消息。\n一眼平芜看不尽，夜来小雨催新碧。\n笑去年、携酒折花人，花应识。\n兰舟漾，城南陌。\n云影淡，天容窄。\n绕风漪十顷，暖浮晴色。\n恰似槎头收钓处，坐中仍有江南客。\n问何如、雨桨下苕溪，吞云泽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5244, '应天长', '叶梦得', '松陵秋已老，正柳岸田家，酒醅初熟。\n鲈脍莼羹，万里水天相续。\n扁舟凌浩渺，寄一叶、暮涛吞沃。\n青箬笠，西塞山前，自翻新曲。\n来往未应足。\n便细雨斜风，有谁拘束。\n陶写中年，何待更须丝竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5245, '定风波', '叶梦得', '破萼初惊一点红。\n又看青子映帘栊。\n冰雪肌肤谁复见。\n清浅。\n尚馀疏影照晴空。\n惆怅年年桃李伴。\n肠断。\n只应芳信负东风。\n待得微黄春亦暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5246, '定风波', '叶梦得', '渺渺空波下夕阳。\n睡痕初破水风凉。\n过雨归云留不住。\n何处。\n远村烟树半微茫。\n莫笑经年人老矣。\n归计。\n得迟留处也何妨。\n老子兴来殊不浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5247, '定风波', '叶梦得', '千步长虹跨碧流。\n两山浮影转螭头。\n付与诗人都总领。\n风景。\n更逢仙客下瀛洲。\n袅袅凉风吹汗漫。\n平岸。\n遥空新卷绛河收。\n却怪娥真好事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5248, '定风波', '叶梦得', '斜汉初看素月流。\n坐惊金饼出云头。\n华发萧然吹素领。\n光景。\n何妨分付属沧洲。\n莫待霜花飘烂漫。\n苹岸。\n更凭佳句尽拘收。\n解与破除消万事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5249, '江城子', '叶梦得', '碧潭浮影蘸红旗。\n日初迟。\n漾晴漪。\n我欲寻芳，先遣报春知。\n尽放百花连夜发，休更待，晓风吹。\n满携尊酒弄繁枝。\n与佳期。\n伴群嬉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5250, '江城子', '叶梦得', '翩迁飞舞半空来。\n晓风催。\n巧萦回。\n野旷天遥，回望兴悠哉。\n欲问玉京知远近，试携手，上高台。\n云涛无际卷崔嵬。\n敛浮埃。\n照琼瑰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5251, '江城子', '叶梦得', '芙蓉开过雨初晴。\n曲池平。\n画桥横。\n耿耿银河，遥下蘸空明。\n一舸吴松归未得，聊共住，小蓬瀛。\n问君何事引前旌。\n趣归程。\n背高城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5252, '江城子', '叶梦得', '生涯何有但青山。\n小溪湾。\n转潺。\n投老归来，终寄此山间。\n茅舍半风雨横，荒径晚，乱榛菅。\n强扶衰病上巅。\n水云闲。\n伴跻攀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5253, '江城子', '叶梦得', '甘泉祠殿汉离宫。\n五云中。\n渺难穷。\n永漏通宵，壶矢转金铜。\n曾从钧天知帝所，孤鹤老，寄辽东。\n强扶衰病步龙锺。\n雪花。\n打窗风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5254, '江城子', '叶梦得', '银涛无际卷蓬瀛。\n落霞明。\n暮云平。\n曾见青鸾、紫凤下层城。\n二十五弦弹不尽，空感慨，惜馀情。\n苍梧烟水断归程。\n卷霓旌。\n为谁迎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5255, '竹马儿', '叶梦得', '与君记，平山堂前细柳，几回同挽。\n又征帆夜落，危槛依旧，遥临云。\n自笑来往匆匆，朱颜渐改，故人俱远。\n横笛想遗声，但寒松千丈，倾崖苍藓。\n世事终何已，田阴纵在，岁阴仍晚。\n稽康老来尤懒。\n只要莼羹菰饭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5256, '浣溪沙', '叶梦得', '小雨初回昨夜凉。\n绕篱新菊已催黄。\n碧空无际卷苍茫。\n千里断鸿供远目，十年芳草挂愁肠。\n缓歌聊与送瑶觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5257, '浣溪沙', '叶梦得', '睡粉轻消露脸新。\n醉红初破玉肌匀。\n尊前留得两州春。\n剩挽雕盘醉帽，重催飞骑走红尘。\n十年兰笑骚人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5258, '浣溪沙', '叶梦得', '荷叶荷花水底天。\n玉壶冰酒酿新泉。\n一欢聊复记他年。\n我亦故山归去客，与君分手暂流连。\n佳人休唱好因缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5259, '浣溪沙', '叶梦得', '休笑山翁不住山。\n二年偷向此中闲。\n归来赢得鬓毛斑。\n瓮底新醅供酩酊，城头曲槛俯淙潺。\n山翁老去此山间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5260, '浣溪沙', '叶梦得', '绛蜡烧残夜未分。\n宝筝声缓拍初匀。\n斗枢光照坐生春。\n便恐赐环归衮绣，莫辞挥翰落烟云。\n凤城西去断离魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5261, '浣溪沙', '叶梦得', '绿野歌欢喜见分。\n骤惊和气晓来匀。\n妙歌谁敢和阳春。\n梅蕊旧年迎腊雪，月华今夜破寒云。\n独醒争笑楚人魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5262, '浣溪沙', '叶梦得', '物外光阴不属春。\n且留风景伴佳辰。\n醉归谁管断肠人。\n柳絮尚飘庭下雪，梨花空作梦中云。\n竹间篱落水边门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5263, '浣溪沙', '叶梦得', '千古风流咏白苹。\n二年歌笑拥朱轮。\n翩翩却忆上林春。\n剑履便应陪北阙，裤襦那更假西人。\n玉堂金殿要词臣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5264, '永遇乐', '叶梦得', '苹芷芳州，故人回首，云海何处。\n五亩荒田，殷勤问我，归计真成否。\n洞庭波冷，秋风袅袅，木叶乱随风舞。\n记扁舟、横斜载月，目极暮涛烟渚。\n传声试问，垂虹千顷，兰棹有谁重驻。\n雪溅雷翻，潮头过後，帆影前浦。\n此中高兴，何人解道，天也未应轻付。\n且留取、千锺痛饮，与君共赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5265, '永遇乐', '叶梦得', '天末山横，半空箫鼓，楼观高起。\n指点栽成，东风满院，总是新桃李。\n纶巾羽扇，一尊饮罢，目送断鸿千里。\n揽清歌、馀音不断，缥缈尚萦流水。\n年来自笑无情，何事犹有，多情遗思。\n绿鬓朱颜，匆匆拚了，却记花前醉。\n明年春到，重寻幽梦，应在乱莺声里。\n拍阑干、斜阳转处，有谁共倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5266, '临江仙', '叶梦得', '闻道今年春信早，梅花不怕馀寒。\n凭君先向近南看。\n香苞开遍未。\n莫待北枝残。\n肠断陇头他日恨，江南几驿征鞍。\n一杯聊与尽馀欢。\n风情何似我，老去未应阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5267, '临江仙', '叶梦得', '梦里江南浑不记，祗君幽户难忘。\n夜来急雪绕东堂。\n竹窗松径里，何处问归航。\n瓮底新醅应已熟，一尊知与谁尝。\n会须雄笔卷苍茫。\n雪涛声隐户，琼玉照颓墙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5268, '临江仙', '叶梦得', '不见跳鱼翻曲港，湖边特地经过。\n萧萧疏雨乱风荷。\n微云吹散，凉月坠平波。\n白酒一杯还径醉，归来散发婆娑。\n无人能唱采莲歌。\n小轩枕，檐影挂星河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5269, '临江仙', '叶梦得', '碧瓦新霜侵晓梦，黄花已过清秋。\n风帆何处挂扁舟。\n故人归欲尽，残日更回头。\n乐圃桥边烦借问，有人高卧江楼。\n寄声聊为诉离忧。\n桂丛应已老，何事久淹留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5270, '临江仙', '叶梦得', '闻道安车来过我，百花未敢飘零。\n疾催弦管送杯行。\n五朝瞻旧老，挥麈听风生。\n凤诏远从天上落，高堂燕喜初醒。\n莫言白发减风情。\n此时谁得似，饮罢却精明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5271, '临江仙', '叶梦得', '三月莺花都过了，晓来雪片犹零。\n嵩阳居士记行行。\n西湖初水满，遥想纹生。\n欲为海棠传信息，如今底事长醒。\n不应高卧顿忘情。\n留春春不住，老眼若为明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5272, '临江仙', '叶梦得', '唱彻阳关分别袂，佳人粉泪空零。\n请君重作醉歌行。\n一欢须痛饮，回首念平生。\n却怪老来风味减，半酣易逐愁醒。\n因花那更赋闲情。\n鬓毛今尔耳，空笑老渊明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5273, '临江仙', '叶梦得', '潋滟湖光供一笑，未须醉日论千。\n将军曾记旧临边。\n野塘新水漫，烟岸藕如船。\n却怪情多春又老，回肠易逐愁煎。\n何如旌旆郁相连。\n凯歌归玉帐，锦帽碧油前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5274, '临江仙', '叶梦得', '学士园林人不到，传声欲问江梅。\n曲阑清浅小池台。\n已知春意近，为我著诗催。\n急管行觞围舞袖，故人坐上三台。\n此欢此宴固难陪。\n不辞同二老，倒载习池回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5275, '临江仙', '叶梦得', '不与群芳争绝艳，化工自许寒梅。\n一枝临晚照歌台。\n眼明浑未见，弦管莫惊催。\n记取刘郎归去路，千里应话天台。\n酒阑不惜更重陪。\n夜寒衣袂薄，犹有暗香回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5276, '临江仙', '叶梦得', '三日疾风吹浩荡，绿芜未遍平沙。\n约回残影射明霞。\n水光遥泛坐，烟柳卧斜。\n霜鬓不堪春点检，留连又见芳华。\n一枝重插去年花。\n此身江海梦，何处定吾家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5277, '临江仙', '叶梦得', '自笑天涯无定准，飘然到处迟留。\n兴阑却上五湖舟。\n鲈莼新有味，碧树已惊秋。\n台上微凉初过雨，一尊聊记同游。\n寄声时为到沧洲。\n遥知枕处，万壑看交流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5278, '临江仙', '叶梦得', '山半飞泉鸣玉佩，回波倒卷粼粼。\n解巾聊濯十年尘。\n青山应却怪，此段久无人。\n行乐应须贤太守，风光过眼逡巡。\n不辞常作坐中宾。\n只愁花解笑，衰鬓不宜春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5279, '临江仙', '叶梦得', '手种千株桃李树，参差半已成阴。\n主人何事马。\n二年江海路，空负种花心。\n试问中间安小槛，此还长要追寻。\n却惊摇落动悲吟。\n春归知早晚，为我变层林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5280, '临江仙', '叶梦得', '绝顶参差千嶂列，不知空水相浮。\n下临湖海见三州。\n落霞横暮景，为客小迟留。\n卷尽微云天更阔，此行不负清秋。\n忽惊河汉近人流。\n青霄元有路，一笑倚琼楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5281, '临江仙', '叶梦得', '一醉三年那易得，应须大白同浮。\n已知绝景是吾州。\n娥仍有意，更肯为人留。\n万籁无声遥夜永，人间未识高秋。\n从来我客尽风流。\n故知怜老子，尤胜在南楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5282, '临江仙', '叶梦得', '卷地惊风吹雨去，却看香雾轻浮。\n遥知清影遍南州。\n万峰横玉立，谁为此山留。\n邂逅一欢须共惜，年年长记今秋。\n平生江海恨飘流。\n元龙真老懒，无意卧高楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5283, '临江仙', '叶梦得', '一醉年年今夜月，酒船聊更同浮。\n恨无羯鼓打梁州。\n遗声犹好在，风景一时留。\n老去狂歌君勿笑，已拚双鬓成秋。\n会须击节溯中流。\n一声云外笛，惊看水明楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5284, '临江仙', '叶梦得', '草草一年真过梦，此生不恨萍浮。\n且令从事到青州。\n已能从辟谷，那更话封留。\n好月尚寻当日约，故人何啻三秋。\n援琴欲写竹间流。\n此声谁解听，空上仲宣楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5285, '虞美人', '叶梦得', '落花已作风前舞。\n又送黄昏雨。\n晓来庭院半残红。\n惟有游丝千丈、晴空。\n殷勤花下同携手。\n更尽杯中酒。\n美人不用敛蛾眉。\n我亦多情、无奈酒阑时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5286, '虞美人', '叶梦得', '翻翻翠叶梧桐老。\n雨後凉生早。\n葛巾藜杖正关情。\n莫遣繁蝉、容易作秋声。\n遥空不尽青天去。\n一抹残霞暮。\n病馀无力厌跻攀。\n为寄曲阑幽意、到西山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5287, '虞美人', '叶梦得', '一声催春晚。\n芳草连空远。\n年年馀恨怨残红。\n可是无情、容易爱随风。\n茂林修竹山阴道。\n千载谁重到。\n半湖流水夕阳前。\n犹有一觞一咏、似当年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5288, '虞美人', '叶梦得', '东风一夜催春到。\n杨柳朝来好。\n莫辞尊酒重携持。\n老去情怀、能有几人知。\n凤台园里新诗伴。\n不用相追唤。\n一声清唱落琼卮。\n千顷西风烟浪、晚云迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5289, '虞美人', '叶梦得', '数声微雨风惊晓。\n烛影猗残照。\n客愁不奈五更寒。\n明日梨花开尽、有谁看。\n追寻犹记清明近。\n为向花前问。\n东风正使解欺侬。\n不道花应有恨、也匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5290, '虞美人', '叶梦得', '平波涨绿春堤满。\n渡口人归晚。\n短篷轻楫费追寻。\n始信十年归梦、是如今。\n故人回望高阳里。\n遥想车连骑。\n尊前点检旧年春。\n应有海棠、犹记插花人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5291, '虞美人', '叶梦得', '绿阴初过黄梅雨。\n隔叶闻莺语。\n睡馀谁遣夕阳斜。\n时有微凉风动、入窗纱。\n天涯走遍终何有。\n白发空搔首。\n未须锦瑟怨年华。\n为寄一声长笛、怨梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5292, '虞美人', '叶梦得', '梅花落尽桃花小。\n春事馀多少。\n新亭风景尚依然。\n白发故人相遇、且留连。\n家山应在层林外。\n怅望花前醉。\n半天烟雾尚连空。\n换取扁舟归去、与君同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5293, '减字木兰花', '叶梦得', '黄花渐老。\n秋色欲归还草草。\n花下前期。\n花老空歌鹊踏枝。\n狂酲易醒。\n不似旧时长酩酊。\n玉簟新凉。\n数尽更筹夜更长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5294, '减字木兰花', '叶梦得', '前村夜半。\n每为江梅肠欲断。\n浅紫深红。\n谁信漫天雪里逢。\n醉头扶起。\n宿酒阑干犹困倚。\n便莫催残。\n明日东风为扫看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5295, '减字木兰花', '叶梦得', '粉消妆半。\n一曲阳春歌始断。\n便觉香红。\n十倍光华昔未逢。\n杨花吹起。\n犹自风前相枕倚。\n莫恨春残。\n留取新诗子细看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5296, '木兰花・玉楼春', '叶梦得', '花残却是春留恋。\n几日馀香吹酒面。\n湿烟不隔柳条青，小雨池塘初有燕。\n波光纵使明如练。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5297, '点绛唇', '叶梦得', '高柳萧萧，睡馀已觉西风劲。\n小窗人静。\n淅沥生秋听。\n底事多情，欲与流年竞。\n残云瞑。\n坠巾慵整。\n独立芝兰径。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5298, '点绛唇', '叶梦得', '缥缈危亭，笑谈独在千峰上。\n与谁同赏。\n万里横烟浪。\n老去情怀，犹作天涯想。\n空惆怅。\n少年豪放。\n莫学衰翁样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5299, '点绛唇', '叶梦得', '山上飞泉，漫流山下知何处。\n乱云无数。\n留得幽人住。\n深闭柴门，听尽空檐雨。\n秋还暮。\n小窗低户。\n惟有寒蛩语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5300, '鹧鸪天', '叶梦得', '不怕微霜点玉肌。\n恨无流水照冰姿。\n与君著意从头看，初见今年第一枝。\n人醉後，雪消时。\n江南春色寄来迟。\n使君本是花前客，莫怪殷勤为赋诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5301, '鹧鸪天', '叶梦得', '夹路行歌尽落梅。\n篆烟香细袅寒灰。\n云移碧海三山近，月破中天九陌开。\n追乐事，惜多才。\n车声遥听走晴雷。\n十年梦断钧天奏，犹记流霞醉後杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5302, '鹧鸪天', '叶梦得', '小雨初收报夕阳。\n归云欲渡转横塘。\n空回雨盖翻新影，不见琼肌洗暗香。\n追落景，弄微凉。\n尚馀残泪空床。\n只应自有东风恨，长遣啼痕破晚妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5303, '鹧鸪天', '叶梦得', '晓日初开露未。\n夕烟轻散雨还微。\n暗摇绿雾游戏，斜映红云属玉飞。\n情脉脉，恨依依。\n沙边空见棹船归。\n何人解舞新声曲，一试纤腰六尺围。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5304, '鹧鸪天', '叶梦得', '兰空悲楚客秋。\n旌旗谁见使君游。\n凌云不隔三山路，破浪聊凭万里舟。\n公欲去，尚能留。\n杯行到手未宜休。\n新诗无物堪伦比，愿探珊瑚出宝钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5305, '鹧鸪天', '叶梦得', '天末残霞卷暮红。\n波间时见没凫翁。\n斜风细雨家何在，老矣生涯尽个中。\n惟此意，与公同。\n未须持酒祝牛宫。\n旁人不解轻蓑意，犹说黄金宝带重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5306, '鹧鸪天', '叶梦得', '一曲青山映小池。\n绿荷阴尽雨离披。\n何人解识秋堪美，莫为悲秋浪赋诗。\n携浊酒，绕东篱。\n菊残犹有傲霜枝。\n一年好景君须记，正是橙黄橘绿时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5307, '水龙吟', '叶梦得', '对花常欲留春，恨春故遣花飞早。\n晓来雨过，绿阴新处，几番芳草。\n一片飘时，已知消减，满庭谁扫。\n料多情也似，愁人易感，先催趁、朱颜老。\n犹有清明未过，但狂风、匆匆难保。\n酒醒梦断，年年此恨，不禁相恼。\n只恐春应，暗留芳信，与花争好。\n有姚黄一朵，殷勤付与，送金杯倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5308, '水龙吟', '叶梦得', '舵楼横笛孤吹，暮云散尽天如水。\n人间底事，忽惊飞堕，冰壶千里。\n玉树风清，漫披遥卷，与空无际。\n料嫦娥此夜，殷勤偏照，知人在、千山里。\n常恨孤光易转，仗多情、使君料理。\n一杯起舞，曲终须寄，狂歌重倚。\n为问飘流，几逢清影，有谁同记。\n但尊中有酒，长追旧事，拚年年醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5309, '千秋岁', '叶梦得', '晓烟溪畔。\n曾记东风面。\n化工更与重裁翦。\n额黄明艳粉，不共妖红软。\n凝露脸。\n多情正似当时见。\n谁相沧波岸。\n特地移闲馆。\n情一缕，愁千点。\n烦君搜妙语，为我催清宴。\n须细看。\n粉粉乱蕊空凡艳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5310, '千秋岁', '叶梦得', '雨声萧瑟，初到梧桐响。\n人不寐，秋声爽。\n低檐灯暗淡，画幕风来往。\n谁共赏。\n依稀记得船篷上。\n拍岸浮轻浪。\n水阔菰蒲长。\n相别浦，收横纲。\n绿蓑冲瞑□，艇子摇双桨。\n君莫忘。\n此情犹是当时唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5311, '蓦山溪', '叶梦得', '一年春事，常恨风和雨。\n趁取未残时，醉花前、春应相许。\n山公倒载，日暮习池回，问东风，春知否，莫道空归去。\n满城歌吹，也似春和豫。\n争笑使君狂，占风光、不教飞絮。\n明朝酒醒，满地落残红，唱新词，追好景，犹有君收聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5312, '清平乐', '叶梦得', '水空相映。\n淡碧涵千顷。\n素练不收寒玉镜。\n□落阶无影。\n纤纤与捧金杯。\n暗香逐舞徘徊。\n雪尽玉容开遍，东风不管寒梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5313, '雨中花慢', '叶梦得', '痛饮狂歌，百计强留，风光无奈春归。\n春去也，应知相赏，未忍相违。\n卷地风惊，争催春暮雨，顿回寒威。\n对黄昏萧瑟，冰肤洗尽，犹覆霞衣。\n多情断了，为花狂恼，故飘万点霏微。\n低粉面、妆台酒散，泪颗频挥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5314, '南乡子', '叶梦得', '浅碧蘸鳞鳞。\n照眼全无一点尘。\n百草千花都过了，初新。\n翠竹高槐不占春。\n歌啸堕纶巾。\n午醉醒来尚欠伸。\n待得月明归去也，青苹。\n更有凉风解送人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5315, '南乡子', '叶梦得', '小院雨新晴。\n初听黄鹂第一声。\n满地绿阴人不到，盈盈。\n一点孤花尚有情。\n却傍水边行。\n叶底跳鱼浪自惊。\n日暮小舟何处去，斜横。\n冲破波痕久未平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5316, '南乡子', '叶梦得', '山畔小池台。\n曾记幽人著意栽。\n乱石参差春至晚，徘徊。\n素景冲寒却自开。\n绝绝照琼瑰。\n孤负芳心巧翦裁。\n应恐练裙惊缟夜，残杯。\n且放疏枝待我来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5317, '卜算子', '叶梦得', '新月挂林梢，暗水鸣枯沼。\n时见疏星落画檐，几点流萤小。\n归意已无多，故作连环绕。\n欲寄新声问采菱，水阔烟波渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5318, '卜算子', '叶梦得', '晓雨洗新妆，艳艳惊衰眼。\n不趁东风取次开，待得清霜晚。\n曲港照回流，影乱微波浅。\n作态低昂好自持，水阔烟波远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5319, '菩萨蛮', '叶梦得', '平波不尽蒹葭远。\n清霜半落沙痕浅。\n烟树晚微茫。\n孤鸿下夕阳。\n梅花消息近。\n试向南枝问。\n记得水边春。\n江南别後人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5320, '蝶恋花', '叶梦得', '薄雪消时春已半。\n踏遍苍苔，手挽花枝看。\n一缕游丝牵不断。\n多情更觉蜂儿乱。\n尽日平波回远岸。\n倒影浮光，却记冰初泮。\n酒力无多吹易散。\n馀寒向晚风惊幔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5321, '醉蓬莱', '叶梦得', '问东风何事，断送残红，便拚归去。\n牢落征途，笑行人羁旅。\n一曲阳关，断云残霭，做渭城朝雨。\n欲寄离愁，绿阴千啭，黄鹂空语。\n遥想湖边，浪摇空翠，弦管风高，乱花飞絮。\n曲水流觞，有山公行处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5322, '南歌子', '叶梦得', '雨惜山容敛，云矜棹影开。\n忽看霁色射林隈。\n为问湖亭清影、为谁来。\n尽洗归时路，重倾醉後杯。\n未应霜雪遽相催。\n留得佳期犹在、共徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5323, '采桑子', '叶梦得', '山蹊小路归来晚，暮雪缤纷。\n尊酒殷勤。\n邂逅相从只有君。\n全家住处无人到，元在重云。\n此景谁分。\n万玉参差更作群。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5324, '南歌子', '叶梦得', '麦陇深初转，桃溪曲渐成。\n绿槐重叠午阴清。\n更有榴花一朵、照人明。\n画栋清微暑，疏帘入晚晴。\n请君坐待纹平。\n看取红幢翠盖、引前旌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5325, '菩萨蛮', '叶梦得', '经年不踏斜桥路。\n青山试问谁为主。\n密叶转回风。\n寒泉落半空。\n此间无限兴。\n可便荒三径。\n明日下扁舟。\n沧波莫浪游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5326, '好事近', '赵士', '雪里晓寒浓，已见蜡梅初折。\n应是月娥仙挂，与娇魂香魄。\n玉人挨鬓一枝斜，不忍更多摘。\n酒面暗沈疏影，照鹅儿颜色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5327, '好事近', '赵士', '萧洒点疏从，浑似蜜房雕刻。\n不爱艳妆浓粉，借娇黄一拂。\n有情常恁早相逢，须信做尤物。\n已是恼人风韵，更芝兰香骨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5328, '好事近', '赵士', '造化有深功，缀就梢头黄蜡。\n剪刻翻成新样，与江梅殊别。\n半开微露紫檀心，萧洒对风月。\n素手偏宜折取，向乌云斜插。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5329, '好事近', '赵士', '剪蜡缀寒条，标韵自然奇绝。\n不待陇头春信，喜一枝先折。\n寿阳妆鉴晓初开，残若飞雪。\n何似嫩黄新蕊，映眉心娇月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5330, '锦缠绊・锦缠道', '江衍', '屈曲新堤，占断满村佳气。\n画檐两行连云际。\n乱山叠翠水回还，岸边楼阁，金碧遥相倚。\n柳阴低，艳映花光美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5331, '蓦山溪', '周铢', '松陵江上，极目烟波缈。\n天际接沧溟，到如今、东流未了。\n吴樯越橹，都是利名人，空扰扰，知多少，只见朱颜老。\n故园应是，绿遍池塘草。\n家住十洲西，算随分、生涯自好。\n渔蓑清贵，休羡谢三郎，红蕖月，白苹风，何似长安道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5332, '眼儿媚', '王赏', '凌寒低亚出墙枝。\n孤瘦雪霜姿。\n岁华已晚，暗香幽艳，自与时违。\n化工放出江头路，沙水冷相宜。\n东风自此，别开红紫，是处芳菲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5333, '水调歌头', '李光', '元亮赋归去，富贵比浮云。\n常於闹里，端的认得主和宾。\n肯羡当年轩冕，时引壶觞独酌，一笑落冠巾。\n园圃日成趣，桃李几番春。\n挹清风，追往躅，事如新。\n遗编讽咏，敛衽千载友斯人。\n君爱谪仙风调，我恨楼船迫胁，终污永王。\n何似北窗下，寂寞可栖神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5334, '水调歌头', '李光', '兵器暗吴楚，江汉久凄凉。\n当年俊杰安在，酌酒酹严光。\n南顾豺狼吞噬，北望中原板荡，矫首讯穹苍。\n归去谢宾友，客路饱风霜。\n闭柴扉，窥千载，考三皇。\n兰亭胜处，依旧流水绕修篁。\n傍有湖光千顷，时泛扁舟一叶，啸傲水云乡。\n寄语骑鲸客，何事返南荒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5335, '水调歌头', '李光', '自笑客行久，新火起新烟。\n园林春半风暖，花落柳飞绵。\n坐想稽山佳处，贺老门前湖水，侧钓鱼船。\n何事成淹泊，流转海南边。\n水中影，镜中像，慢流连。\n此心未住，赢得忧患苦相缠。\n行尽荒烟蛮瘴，深入维那境界，参透祖师禅。\n宴坐超三际，萧洒任吾年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5336, '水调歌头', '李光', '独步长桥上，今夕是中秋。\n群黎怪我何事，流转古儋州。\n风定潮平如练，云散月明如昼，孤兴在扁舟。\n笑尽一杯酒，水调杂蛮讴。\n少年场，金兰契，尽白头。\n相望万里，悲我已是十年流。\n晚遇玉霄仙子，授我王屋奇书，归路指蓬邱。\n不用乘风御，八极可神游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5337, '南歌子', '李光', '佳节多离恨，难逢笑口开。\n使君携客上层台。\n不用篱边凝望、白衣来。\n且看花经眼，休辞酒满杯。\n玉人低唱管弦催。\n归去琐窗无梦、月徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5338, '南歌子', '李光', '南圃秋香过，东篱菊未英。\n蓼花无数满寒汀。\n中有一枝纤软、吐微馨。\n被冷沈烟细，灯青梦水成。\n皎如月明入窗棂。\n天女维摩相对、两忘情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5339, '临江仙', '李光', '画栋朱楼凌缥缈，全家住在层城。\n中秋风露助凄清。\n香凝燕寝，遮莫下帘旌。\n佳节喜逢今夕月，後房重按新声。\n娥端解妒娉婷。\n微云点缀，不放十分明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5340, '减字木兰花', '李光', '芳心一点。\n瘴雾难侵尘不染。\n冷澹谁看。\n月转霜林怯夜寒。\n一枝孤静。\n梦破小窗曾记省。\n烛影参差。\n脉脉还如背立时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5341, '念奴娇', '李光', '榕林叶暗，见一枝独放，霜华争白。\n写我精神惟赖有，萧洒西湖词客。\n玉骨清羸，冰容冷落，似恨关山隔。\n蛮烟侵妒，未应减动肌雪。\n幽梦时绕芳枝，夜寒谁见我，身为蝴蝶。\n抱蕊窥丛惊睡觉，窗影横斜和月。\n谢馆池边，松风亭下，忍使香消歇。\n多情饶恨，算应天解磨折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5342, '汉宫春', '李光', '危阁临流，渺沧波万顷，涌出冰轮。\n星河澹澹，天衢迥绝纤尘。\n琼楼玉馆，遍人间、水月精神。\n□□□，清江瘴海，乘流处处分身。\n邦侯盛集佳宾。\n有香风缥缈，和气氤氲。\n华灯耀添绮席，笑语烘春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5343, '鹧鸪天', '李光', '踏舞贪看赤脚娘。\n送春春去莫悲伤。\n飞花逐水归何处，落絮沾泥不解狂。\n都是醉，任飞扬。\n百年三万六千场。\n使君亲按新歌舞，魂梦相逢笑楚襄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5344, '武陵春', '李光', '漠漠春阴人似雾，那用绣帘垂。\n不道持杯是阿谁。\n须拚倒金。\n人世浑知天上月，离合比盈亏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5345, '渔家傲', '李光', '海外无寒花发早。\n一枝不忍簪风帽。\n归插净瓶花转好。\n维摩老。\n年来却被花枝恼。\n忽忆故乡花满道。\n狂歌痛饮俱年少。\n桃坞花开如野烧，都醉倒。\n花深往往眠芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5346, '水调歌头', '李光', '晚渡呼舟急，寒日正苍茫。\n西兴浦口云树，真个是吾乡。\n闻□蜗庐好在，小圃犹存松菊，三径未全荒。\n收拾桑榆景，蓑笠换金章。\n珥金貂，拥珠履，在岩廊。\n回头万事何有，一枕梦黄粮。\n十载人间忧患，赢得萧萧华发，清镜照星霜。\n醉倒休扶我，身世永相忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5347, '雨中花慢', '张生1', '事往人离，还似暮峡归云，陇上流泉。\n奈强分圆镜，枉断哀弦。\n常记酒阑歌畔，难忘月底花前。\n旧携手处，层楼朱户，触目依然。\n从来惯向，绣帏罗帐，镇效比翼纹鸳。\n谁念我、而今清夜，常是孤眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5348, '向湖边', '江纬', '退处相关，幽栖林薮，舍宇第须茅盖。\n翠清泉，启轩窗遥对。\n遇等闲、邻里过从，亲朋临顾，草草便成幽会。\n策杖携壶，向湖边柳外。\n旋买溪鱼，便斫银丝脍。\n谁复欲痛饮，如长鲸吞海。\n共惜醺酣，恐欢娱难再。\n矧清风明月非钱买。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5349, '卜算子', '美奴', '送我出东门，乍别长安道。\n两岸垂杨锁暮烟，正是秋光老。\n一曲古阳关，莫惜金尊倒。\n君向潇湘我向秦，鱼雁何时到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5350, '如梦令', '美奴', '日暮马嘶人去。\n船逐清波东注。\n後夜最高楼，还肯思量人否。\n无绪。\n无绪。\n生怕黄昏疏雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5351, '人娇', '张扩', '深院海棠，谁倩春工染就。\n映窗户、烂如锦绣。\n东君何意，便风狂雨骤。\n堪恨处，一枝未曾到手。\n今日乍晴，匆匆命酒。\n犹及见、胭脂半透。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5352, '人娇', '张扩', '多少胭脂，匀成点就。\n千枝乱、攒红堆绣。\n花无长好，更光阴去骤。\n对景忆良朋，故应招手。\n曾记年时，花间把酒。\n枉淋浪、春衫湿透。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5353, '菩萨蛮', '赵子崧', '锦如花色春残饮。\n饮残春色花如锦。\n楼上正人愁。\n愁人正上楼。\n晏天横阵雁。\n雁阵横天晏。\n思远寄情词。\n词情寄远思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5354, '菩萨蛮', '赵子崧', '雨荷惊起双飞鹭。\n鹭飞双起惊荷雨。\n浓醉一轩风。\n风轩一醉浓。\n午阴清散暑。\n暑散清阴午。\n斜日转窗纱。\n纱窗转日斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5355, '菩萨蛮', '赵子崧', '断鸿归处飞云乱。\n乱云飞处归鸿断。\n风弄叶翻红。\n红翻叶弄风。\n柳残凋院後。\n後院凋残柳。\n楼外水云秋。\n秋云水外楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5356, '菩萨蛮', '赵子崧', '月天遥照寒窗雪。\n雪窗寒照遥天月。\n门掩欲黄昏。\n昏黄欲掩门。\n锦双并枕。\n枕并双锦。\n云鬓整纤琼。\n琼纤整鬓云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5357, '菩萨蛮', '鉴堂', '落花丛外风惊鹊。\n鹊惊风外丛花落。\n乡梦困时长。\n长时困梦乡。\n暮天江口渡。\n渡口江天暮。\n林远度栖禽。\n禽栖度远林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5358, '菩萨蛮', '鉴堂', '竹枝高映荷池绿。\n绿池荷映高枝竹。\n流水碧浮鸥。\n鸥浮碧水流。\n酒尊陪旧友。\n友旧陪尊酒。\n吟客坐时斟。\n斟时坐客吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5359, '菩萨蛮', '鉴堂', '砌风鸣叶繁霜坠。\n坠霜繁叶鸣风砌。\n山外水潺潺。\n潺潺水外山。\n冷衾愁夜永。\n永夜愁衾冷。\n砧响更蛩吟。\n吟蛩更响砧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5360, '菩萨蛮', '鉴堂', '浦南回桨归庭户。\n户庭归桨回南浦。\n帘卷欲晴天。\n天晴欲卷帘。\n月光交映雪。\n雪映交光月。\n残漏怯宵寒。\n寒宵怯漏残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5361, '菩萨蛮', '梅窗', '碧窗纱透春寒极。\n极寒春透纱窗碧。\n谁送缕金衣。\n衣金缕送谁。\n玉肌生嫩粟。\n粟嫩生肌玉。\n温处坐香茵。\n茵香坐处温。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5362, '菩萨蛮', '梅窗', '折来初步东溪月。\n月溪东步初来折。\n香处是瑶芳。\n芳瑶是处香。\n藓花浮晕浅。\n浅晕浮花藓。\n清对一枝瓶。\n瓶枝一对清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5363, '菩萨蛮', '梅窗', '浅红绡透春裁剪。\n剪裁春透绡红浅。\n机锦织情丝。\n丝情织锦机。\n意深凭远寄。\n寄远凭深意。\n波渺胜愁多。\n多愁胜渺波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5364, '菩萨蛮', '梅窗', '点点花飞春恨浅。\n浅恨春飞花点点。\n莺语似多情。\n情多似语莺。\n恋春增酒劝。\n劝酒增春恋。\n颦损翠蛾新。\n新蛾翠损颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5365, '菩萨蛮', '梅窗', '曲屏春展山浮玉。\n玉浮山展春屏曲。\n香鸭瑞云翔。\n翔云瑞鸭香。\n醉深留客意。\n意客留深醉。\n凉枕怯宵长。\n长宵怯枕凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5366, '菩萨蛮', '梅窗', '玉钗松鬓凝云绿。\n绿云凝鬓松钗玉。\n双翠碍枝长。\n长枝碍翠双。\n色丝添意密。\n密意添丝色。\n红映袖纱笼。\n笼纱袖映红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5367, '西江月', '梅窗', '雨过轻风弄柳，湖东映日春烟。\n晴芜平水远连天。\n隐隐飞翻舞燕。\n燕舞翻飞隐隐。\n天连远水平芜。\n晴烟春日映东湖。\n柳弄风轻过雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5368, '阮郎归', '梅窗', '皇州新景媚晴春。\n春晴媚景新。\n万家明月醉风清。\n清风醉月明。\n人游乐，乐游人。\n游人乐太平。\n御楼神圣喜都民。\n民都喜圣神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5369, '踏莎行', '欧阳', '雁字成行，角声悲送。\n无端又作长安梦。\n青衫小帽这回来，安仁两鬓秋霜重。\n孤馆残灯，小楼钟动。\n马踢踏破前村冻。\n平生牵系为浮名，名垂万古知何用。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5370, '洞仙歌', '刘一止', '细风轻雾，锁山城清晓。\n冷蕊疏枝为谁好。\n对斜桥孤驿，流水溅溅，无限意，清影徘徊自照。\n何郎空立马，恼乱馀香，绮思凭花更娟妙。\n肠断处，天涯路远音稀，行人怨、角声吹老。\n叹客里经春又三年，向月地云阶，负伊多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5371, '夜行船', '刘一止', '十顷疏梅开半就。\n折芳条、嫩香沾袖。\n今度何郎，尊前疑怪，花共那人俱瘦。\n恻恻轻寒吹散酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5372, '念奴娇', '刘一止', '江边故国，望南云缥缈，连山修木。\n远意渊明束带见，乡里儿曹何辱。\n世味熏人，折腰从事，俯仰何时足。\n可怜菊下，醉吟谁共徵逐。\n我爱九日佳名，飘然归思，想当年丘谷。\n梦绕篱边犹眷恋，满把清尊馀馥。\n援笔洪都，如君英妙，满座方倾属。\n月台挥袖，叫云声横断玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5373, '念奴娇', '刘一止', '故山秋晚，叹萧萧华发，霜林同色。\n崖谷题诗追旧赏，往往苍苔绿壁。\n二士权奇，一翁衰病，努力攀筇屐。\n佛香吹过，了知境是空寂。\n别後风月佳时，拄颐何事，想东林遥碧。\n小砑蛮笺惊秀句，天巧何会雕刻。\n倚马雄才，凌云逸气，路觉丹霄直。\n三千牍就，看君归奏文石。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5374, '念奴娇', '刘一止', '燕台暮集，对秋容凄紧，松阴幂幂。\n徙倚阑边临翠壑，千顷风烟横出。\n坐待冰轮，天空云散，一色如苍璧。\n娥有意，为谁来赴今夕。\n身世如许飘流，佳时轻过了，他年空忆。\n我辈情锺端未愧，昔日兰亭陈迹。\n坐上何人，骊歌凄断，语别还应惜。\n有心红烛，替人珠泪频滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5375, '念奴娇', '刘一止', '水烟收尽，望汀苹千顷，银光如幂。\n霜镜无痕清夜久，惟有惊鱼跳出。\n月在杯中，我疑天赐，欢饮仍如璧。\n娥应为，後期偿赛今夕。\n遥想当日同盟，山斋孤讽，有新诗相忆。\n聚散难常空怅望，萍梗飘流踪迹。\n明月明年，此身此夜，知与谁同惜。\n参横河侧，短篷清露时滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5376, '踏莎行', '刘一止', '两水中分，三山半落。\n风云气象通廖廓。\n少年怀古有新诗，清愁不是伤春作。\n六代豪华，一时燕乐。\n从教雨打风吹却。\n与君携酒近阑干，月明满地天无幕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5377, '虞美人', '刘一止', '浪花云叶交加舞。\n身近轻冥路。\n天知此客解骑鲸。\n今夜一江明月、送行行。\n从今直上鳌峰去。\n应记经行处。\n莫将险语乱江声。\n却怕月中高卧、彩虹惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5378, '江城子', '刘一止', '秋香岩下著尊。\n小徘徊。\n莫停杯。\n来岁花时，相望两悠哉。\n看取修眉萦度曲，真个泪，界香腮。\n船头击鼓片帆开。\n晓风吹。\n首应回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5379, '临江仙', '刘一止', '柳外双旌斜照日，匆匆去意难留。\n大江旁畔老诸侯。\n举觞仍气概，觅句更风流。\n迟暮不堪容易别，溪声为写离愁。\n自从今日转船头。\n他时扶杖叟，独立向沧洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5380, '临江仙', '刘一止', '落日西风原上好，笛声谁奏伊凉。\n缓寻山径掇幽芳。\n平生真自许，江海老潜郎。\n最爱杯中浮蚁闹，鹅儿破壳娇黄。\n使君醉里是家乡。\n更追修禊帖，一咏一传觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5381, '雪月交光・醉蓬莱', '刘一止', '正五云飞杖，缟素褰裳，乱空交舞。\n拂石归来，向玉阶微步。\n欲唤冰娥，暂凭风使，为扫氛驱雾。\n渐见停轮，人间未识，高空真侣。\n千里无尘，地连天迥，倦客古来，路迷江树。\n故国烟深，想溪树何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5382, '望海潮', '刘一止', '垂杨深院，啼莺清昼，东风细绕檐牙。\n野色乱春，娇云捧日，燕翻蝶舞交加。\n温诏下天涯。\n早画船飞楫，叠鼓鸣挝。\n共挽旌幢，缓留丝竹醉韶华。\n江都自古豪夸。\n正迷楼坠絮，月观吹花。\n玉眷深，金瓯望重，何人暗草黄麻。\n归路接堤沙。\n宴上林风月，紫阙烟霞。\n凤检飞来，便将春色到朝家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5383, '醉蓬莱', '刘一止', '正官桥柳润，候馆梅开，暮云凄冽。\n泽国春归，是烧灯时节。\n吹绽红蕖，挽低星斗，共水光澄澈。\n霜瓦楼台，参差似与，蓬壶相接。\n千骑遨游，万家嬉笑，帘卷东风，弄妆成列。\n慢舞尊前，看轻盈回雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5384, '望明河', '刘一止', '华旌耀日，报天上使星，初辞金阙。\n许国精忠，试此日传岩，济川舟楫。\n向来鸡林外，况传咏、篇章雄绝。\n问人地、真是唐朝第一，未论勋业。\n鲸波霁云千叠。\n望仙驭缥缈，神山明灭。\n万里勤劳，也等是壮年，绣衣持节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5385, '蓦山溪', '刘一止', '卿云衍苒，翠壁天开就。\n移下小方壶，照初日、嘉林濯秀。\n君恩暂许，丘壑憩夔龙，开径竹，续岩花，小试丹青手。\n声名德业，汉代谁居右。\n红旆碧油幢，想今古、山中未有。\n霜松手种，应待茯芩生，斋酿熟，玉泉香，还上萱堂寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5386, '生查子', '刘一止', '城头长短更，水调高低唱。\n别洒不盈斟，泪洒风烟上。\n明年二月时，更向城阴望。\n只有旧歌辞，传作风流样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5387, '清平乐', '刘一止', '相望吴楚。\n远信无凭据。\n欲倩春风吹泪去。\n化作愁云恨雨。\n春应已到三吴。\n楚江日夜东徂。\n惟有溯流鱼上，不知尺素来无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5388, '青玉案', '刘一止', '小山遮断蓝桥路。\n恨短梦、难飞去。\n长记修眉萦曲度。\n约花开槛，映风招袖，总是怜渠处。\n追欢我已伤迟暮。\n犹有多情旧时句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5389, '梦横塘', '刘一止', '浪痕经雨，鬓影吹寒，晓来无限萧瑟。\n野色分桥，翦不断、溪山风物。\n船系朱藤，路迷烟寺，远鸥浮没。\n听疏钟断鼓，似近远遥，惊心事、伤羁客。\n新醅旋压鹅黄，拚清愁在眼，酒病萦骨。\n绣阁娇慵，争解说、短封传忆。\n念谁伴、涂妆绾结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5390, '西河', '刘一止', '山驿晚，行人昨停征辔。\n白沙翠竹锁柴门，乱峰相倚。\n一番急雨洗天回，扫云风定还起。\n念凄断，谁与寄。\n双鱼尽素难委。\n遥知洞户隔烟窗，簟横秋水。\n淡花明玉不胜寒，绿尊初试冰蚁。\n小欢细酌任醉。\n扑流萤、应卜心事。\n谁记天涯憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5391, '眼儿媚', '刘一止', '度岁经年两看承。\n谁信有轻分。\n从前稳过，如今方悔，不会温存。\n眼前无限经行地，何处不销魂。\n多应为你，不看风月，睡过黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5392, '水调歌头', '刘一止', '千古严陵濑，清夜月荒凉。\n水明沙净，波面一叶弄孤光。\n北望旄头天际，杀气遥昏楚甸，云树失青苍。\n愁绝未归客，衰鬓点吴霜。\n听江边，鸣宝瑟，想英皇。\n骑鲸仙裔，高韵清绝胜风篁。\n醉入无何境界，却笑昔人底事，远慕白云乡。\n不见咸阳道，烟草茂陵荒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5393, '水调歌头', '刘一止', '缥缈青溪畔，山翠欲粘天。\n纵云台上，揽风招月自何年。\n新旧今逢二妙，人地一时清绝，高并两峰寒。\n歌发烟霏外，人在去留间。\n著方床，容老子，醉时眠。\n一尊相属，高会何意此时圆。\n况是古今难遇，人月竹花俱妙，曾见句中传。\n不向今宵醉，忍负四婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5394, '鹧鸪天', '刘一止', '岩下清阴引兴长。\n坐中初识令君香。\n揽将风月归诗薮，乞得溪山作醉乡。\n怜我老，与传觞。\n吴霜点鬓又何妨。\n只应银烛交红夜，羞对双歌发彩光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5395, '木兰花・玉楼春', '刘一止', '桂香台上秋风袅。\n鸭绿溪前离思渺。\n一卮芳醑细深倾，听尽阳关须醉倒。\n政成早晚传温诏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5396, '浣溪沙', '刘一止', '午夜明蟾冷浸溪。\n娥应有辟寒犀。\n桂岩仍在曲阑西。\n撷蕊攀条情未已，经丘寻壑想招携。\n不应痴马惜障泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5397, '点绛唇', '刘一止', '洞户香凝，宴开特地风烟好。\n靓妆娟妙。\n玉雪光相照。\n认是桃源，绿水红云绕。\n真曾到。\n漾舟人老。\n应被桃花笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5398, '点绛唇', '刘一止', '云鬓分行，照人明艳新妆就。\n御香窗牖。\n细酌鹅儿酒。\n铁拨弦，一试春风手。\n龙仙奏。\n绛霄声透。\n不许人间有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5399, '临江仙', '刘一止', '台上风光浓欲滴，傍阑芳桂阴成。\n乱山相对长官青。\n琢诗能句好，举酒见心倾。\n团扇不应秋後弃，几年仁惠风行。\n渭城柳色若为情。\n一尊松竹底，三唱和秋声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5400, '蓦山溪', '刘一止', '王家人地，奕奕争高秀。\n金紫照青春，想当日、乌衣巷口。\n声名气概，今见两朱，诗似锦，酒如渑，属意风光厚。\n酿泉石壁，未减南阳寿。\n清兴与谁同，探梅萼、溪桥驿堠。\n东风御柳，应访此韩，归步稳，赤墀边，肯记幽栖否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5401, '念奴娇', '刘一止', '小舟漂兀，犯溪烟深入，无穷寒碧。\n路绕莲塘浑乱眼，千顷朱朱白白。\n闻说高情，寻盟鸥鹭，爱此风标客。\n掀髯一笑，顿忘身世形迹。\n我爱古邑风流，碧峰争秀峙，相持如掖。\n制锦才雄应未怕，百里文书堆积。\n吏散庭空，举觞遨月，饮兴何妨剧。\n却怜宣子，杖头才挂钱百。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5402, '柳梢青', '刘一止', '柳汀烟暮。\n常记岸帻，风流张绪。\n酒兴诗情，而今移向，那边佳处。\n使君自乐萧闲，未肯副、岩廊虚伫。\n不念寒窗，老人幽梦，追寻无据。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5403, '鹊桥仙', '刘一止', '春风真个，取将花去，酬我清阴满院。\n名园清昼漏签迟，未肯负、酒朋歌伴。\n使君情在，暮云合处，卧看碧峰峨弁。\n向来魂梦几曾真，休怨断、楼高不见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5404, '浣溪沙', '刘一止', '曾向蓬莱得姓名。\n坐中省识是飞琼。\n琵琶翻作步虚声。\n一自当时收拨後，世间弦索不堪听。\n梦回凄断月胧明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5405, '点绛唇', '刘一止', '岁月飘流，故人相望如箕斗。\n畔愁千首。\n诗骨能清瘦。\n白日弦，同看春风手。\n君知否。\n袖痕别後。\n犹有临歧酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5406, '点绛唇', '刘一止', '山邑新凉，夜堂爽气侵南斗。\n为谁骧首。\n月冷冰蛾瘦。\n八万二千，雕琢琼瑶手。\n君知否。\n待君归後。\n双照杯中酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5407, '望海潮', '刘一止', '东郊人报，春风消息，先归御柳宫梅。\n残雪恋枝，轻阴阁雨，郁葱瑞气佳哉。\n清晓九门开。\n听舜韶声举，迤逦天街。\n双阙连云，六鳌横海驾峰来。\n华灯竟簇楼台。\n正丰年共乐，欢意徘徊。\n帘卷弄妆，尘香趁马，轻寒细入人怀。\n争待凤舆回。\n看一天星斗，移下蓬莱。\n是处歌谣，太平声入万年杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5408, '青玉案', '刘一止', '马头双鹊飞来喜。\n惜凝望、音书至。\n一掬离怀千万事。\n绿窗深夜，短笺封就，应也寻人寄。\n春风鬓畔疏梅蕊。\n映妆艳、清如洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5409, '喜迁莺', '刘一止', '晓光催角。\n听宿鸟未惊，邻鸡先觉。\n迤逦烟村，马嘶人起，残月尚穿林薄。\n泪痕带霜微凝，酒力冲寒犹弱。\n叹倦客、悄不禁，重染风尘京洛。\n追念，人别後，心事万重，难觅孤鸿托。\n翠幌娇深，曲屏香暖，争念岁寒飘泊。\n怨月恨花烦恼，不是不曾经著。\n这情味，望一成消减，新来还恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5410, '踏莎行', '刘一止', '淡月精神，疏梅风韵。\n粉香融脸胭脂润。\n袖痕犹带玉虬烟，六朝窄样裁宫锦。\n眉黛分愁，眼波传信。\n酒阑画烛交红影。\n有期无定却人，索强我早谙伊性。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5411, '浣溪沙', '刘一止', '莫问新欢与旧愁。\n浅颦微笑总风流。\n眼波横注楚江秋。\n十字街头家住处，心肠四散几时休。\n揽风招月是朱楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5412, '点绛唇', '汪藻', '新月娟娟，夜寒江静山衔斗。\n起来搔首。\n梅影横窗瘦。\n好个霜天，闲却传杯手。\n君知否。\n乱鸦啼後。\n归兴浓於酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5413, '点绛唇', '汪藻', '高柳蝉嘶，采菱歌断秋风起。\n晚云如髻。\n湖上山横翠。\n帘卷西楼，过雨凉生袂。\n天如水。\n画楼十二。\n有个人同倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5414, '小重山', '汪藻', '月下潮生红蓼汀。\n浅霞都敛尽，四山青。\n柳梢风急坠流萤。\n随波处，点点乱寒星。\n别语寄丁宁。\n如今能间隔，几长亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5415, '醉落魄・一斛珠', '汪藻', '小舟帘隙。\n佳人半露梅妆额。\n绿云低映花如刻。\n恰似秋宵，一半银蟾白。\n结儿梢朵香红。\n钿蝉隐隐摇金碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5416, '蓦山溪', '曹组', '洗妆真态，不作铅华御。\n竹外一枝斜，想佳人、天寒日暮。\n黄昏小院，无处著清香，风细细，雪垂垂，何况江头路。\n月边疏影，梦到消魂处。\n结子欲黄时，又须著、廉纤细雨。\n孤芳一世，供断有情愁，销瘦却，东阳也，试问花知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5417, '点绛唇', '曹组', '秋劲风高，暗知斗力添弓面。\n靶分筠斡。\n月到天心满。\n白羽流星，飞上黄金碗。\n胡沙雁。\n云边惊散。\n压尽天山箭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5418, '点绛唇', '曹组', '疏柳残蝉，助人离思斜阳外。\n淡烟疏霭。\n节物随时改。\n水已无情，风更无情。\n兰舟解。\n水流风快。\n回首人何在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5419, '点绛唇', '曹组', '密炬高烧，宝刀时翦金花碎。\n照人欢醉。\n也照人无睡。\n待得灰心，陪尽千行泪。\n笼纱里。\n夜凉如水。\n犹喜长成对。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5420, '如梦令', '曹组', '门外绿阴千顷。\n两两黄鹂相应。\n睡起不胜情，行到碧梧金井。\n人静。\n人静。\n风动一枝花影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5421, '扑蝴蝶', '曹组', '人生一世。\n思量争甚底。\n花开十日，已随尘共水。\n且看欲尽花枝，未厌伤多酒盏，何须细推物理。\n幸容易。\n有人争奈，只知名与利。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5422, '忆少年', '曹组', '年时酒伴，年时去处，年时春色。\n清明又近也，却天涯为客。\n念过眼、光阴难再得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5423, '蓦山溪', '曹组', '草熏风暖，楼阁笼轻雾。\n墙短出花梢，映谁家、绿杨朱户。\n寻芳拾翠，绮陌自青春，江南远，踏青时，谁念方羁旅。\n昔游如梦，空忆横塘路。\n罗袖舞台风，想桃花、依然旧树。\n一怀离恨，满眼欲归心，山连水，水连云，怅望人何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5424, '相思会・千年调', '曹组', '人无百年人，刚作千年调。\n待把门关铁铸，鬼见失笑。\n多愁早老。\n惹尽闲烦恼。\n我醒也，枉劳心，谩计较。\n粗衣淡饭，赢取暖和饱。\n住个宅儿，只要不大不小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5425, '品令', '曹组', '乍寂寞。\n帘栊静，夜久寒生罗幕。\n窗儿外、有个梧桐树，早一叶、两叶落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5426, '小重山', '曹组', '帘卷东风日射窗。\n小山庭院静，接回廊。\n疏疏晴雨弄斜阳。\n凭栏久，墙外杏花香。\n时节好寻芳。\n多情怀酒伴，忆欢狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5427, '小重山', '曹组', '陌上花繁莺乱啼。\n骅骝金络脑，锦障泥。\n寻芳行乐忆当时。\n联镖处，飞绿杨堤。\n春物又芳菲。\n情如风外柳，只依依。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5428, '青玉案', '曹组', '碧山锦树明秋霁。\n路转陡、疑无地。\n忽有人家临曲水。\n竹篱茅舍，酒旗沙岸，一簇成村市。\n凄凉只恐乡心起。\n凤楼远、回头谩凝睇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5429, '鹧鸪天', '曹组', '辇路薰风起绿槐。\n都人凝望满天街。\n云韶杳杳鸣鞘肃，芝盖亭亭障扇开。\n微雨过，绝纤埃。\n内家车子走轻雷。\n千门不敢垂帘看，总上银钩等驾来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5430, '渔家傲', '曹组', '水上落红时片片。\n江头雪絮飞缭乱。\n渺渺碧波天漾远。\n平沙暖。\n花风一阵苹香满。\n晚来醉著无人唤。\n残阳已在青山半。\n睡觉只疑花改岸。\n抬头看。\n元来弱缆风吹断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5431, '阮郎归', '曹组', '檐头风佩响丁东。\n帘疏烛影红。\n秋千人散月溶溶。\n楼台花气中。\n春酒醒，夜寒浓。\n绣衾谁与同。\n只愁梦短不相逢。\n觉来罗帐空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5432, '临江仙', '曹组', '青琐窗深红兽暖，灯前共倒金尊。\n数枝梅浸玉壶春。\n雪明浑似晓，香重欲成云。\n户外马嘶催客起，席间欢意留人。\n从他微霰落粉粉。\n不妨吹酒面，归去醒馀醺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5433, '鹧鸪天', '曹组', '浅笑轻颦不在多。\n远山微黛接横波。\n情吞千锺酒，心醉飞琼一曲歌。\n人欲散，奈愁何。\n更看朱袖拂云和。\n夜深醉墨淋浪处，书遍香红拥项罗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5434, '青门饮', '曹组', '山静烟沈，岸空潮落。\n晴天万里，飞鸿南渡。\n冉冉黄花，翠翅金钿，还是倚风凝露。\n岁岁青门饮，尽龙山、高阳俦侣。\n旧赏成空，回首旧游，人在何处。\n此际谁怜萍泛，空自感光阴，暗伤羁旅。\n醉里悲歌，夜深惊梦，无奈觉来情绪。\n孤馆昏还晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5435, '青玉案', '曹组', '田园有计归须早。\n在家纵贫亦好。\n南来北去何日了。\n光阴送尽，可怜青鬓，暗逐流年老。\n寂寥孤馆残灯照。\n乡思惊时梦初觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5436, '好事近', '曹组', '茅舍竹篱边，雀噪晚枝时节。\n一阵暗香飘处，已难禁愁绝。\n江南得地故先开，不待有飞雪。\n肠断几回山路，恨无人攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5437, '醉花阴', '曹组', '九陌寒轻春尚早。\n灯火都门道。\n月下步莲人，薄薄香罗，峭窄春衫小。\n梅妆浅淡风蛾袅。\n随路听嬉笑。\n无限面皮儿，虽则不同，各是一般好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5438, '点绛唇', '曹组', '小小朱桥，柳边人过横塘路。\n细风时度。\n□浪痕痕去。\n草软沙平，稳衬寻幽步。\n□□处。\n乱红飞舞。\n回首春城暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5439, '点绛唇', '曹组', '云透斜阳，半楼红影明窗户。\n暮山无数。\n归雁愁远去。\n十里平芜，花远重重树。\n空凝伫。\n故人何处。\n可惜春将暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5440, '点绛唇', '曹组', '沈醉归来，洞房灯火闲相照。\n夜寒犹峭。\n信意和衣倒。\n春梦虽多，好梦长长少。\n纱窗晓。\n凤帏人悄。\n花外空啼鸟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5441, '水龙吟', '曹组', '晓天谷雨晴时，翠罗护日轻烟里。\n酴径暖，柳花风淡，千葩浓丽。\n三月春光，上林池馆，西都花市。\n看轻盈隐约，何须解语，凝情处、无穷意。\n金殿筠笼岁贡，最姚黄、一枝娇贵。\n东风既与花王，芍药须为近侍。\n歌舞筵中，满装归帽，斜簪云髻。\n有高情未已，齐烧绛蜡，向阑边醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5442, '声声慢', '曹组', '重檐飞峻，丽彩横空，繁华壮观都城。\n云母屏开八面，人在青冥。\n凭栏瑞烟深处，望皇居、遥识蓬瀛。\n回环阁道，五花相斗，压尽旗亭。\n歌酒长春不夜，金翠照罗绮，笑语盈盈。\n陆海人山辐辏，万国欢声。\n登临四时总好，况花朝、月白风清。\n丰年乐，岁熙熙、且醉太平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5443, '蝶恋花', '曹组', '帘卷真珠深院静。\n满地槐阴，镂日如云影。\n午枕花前情思凝。\n象床冰簟光相映。\n过面风情如酒醒。\n沈水瓶寒，带绠来金井。\n涤尽烦襟无睡兴。\n阑干六曲还重凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5444, '浣溪沙', '曹组', '柳絮池台淡淡风。\n碧波花岫小桥通。\n云连丽宇倚晴空。\n芳草绿杨人去住，短墙幽径燕西东。\n攀条弄蕊得从容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5445, '点绛唇', '曹组', '霜落吴江，万畦香稻来场圃。\n夜村舂黍。\n草屋寒灯雨。\n玉粒长腰，沈水温温注。\n相留住。\n共抄云子。\n更听歌声度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5446, '点绛唇', '曹组', '一片南云，定知来做巫山雨。\n歌声才度。\n只向风中住。\n恼乱襄王，无限牵情处。\n长天暮。\n又还飞去。\n目断阳台路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5447, '婆罗门引', '曹组', '涨云暮卷，漏声不到小帘栊。\n银河淡扫澄空。\n皓月当轩高挂，秋入广寒宫。\n正金波不动，桂影朦胧。\n佳人未逢。\n叹此夕、与谁同。\n望远伤怀对景，霜满愁红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5448, '失调名', '曹组', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5449, '卜算子', '曹组', '松竹翠萝寒，迟日江山暮。\n幽径无人独自芳，此恨凭谁诉。\n似共梅花语。\n尚有寻芳侣。\n著意闻时不肯香，香在无心处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5450, '小重山', '曹组', '深拥熏篝倏已冥。\n寂寥山枕畔，梦难成。\n谁堪三两夜乌声。\n银缸，花影上围屏。\n犹记旧时情。\n帘边人似月，月如冰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5451, '脱银袍', '曹组', '济楚风光，升平时世。\n端门支散，碗遂逐旋温来，吃得过、那堪更使金器。\n分明是。\n与穷汉、消灾灭罪。\n又没支分，犹然递滞。\n打笃磨槎来根底。\n换头巾，便上弄交番斯替。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5452, '忆瑶姬', '曹组', '雨细云轻，花娇玉软，於中好个情性。\n争奈无缘相见，有分孤零。\n香笺细写频相问。\n我一句句儿都听。\n到如今，不得同欢，伏惟与他耐静。\n此事凭谁执证。\n有楼前明月，窗外花影。\n拚了一生烦恼，为伊成病。\n只恐更把风流逞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5453, '蓦山溪', '万俟咏', '芳菲叶底。\n谁会秋江意。\n深绿护轻黄，怕青女、霜侵憔悴。\n开分早晚，都占九秋天，花四出，香七里。\n独步珠宫里。\n佳名岩桂。\n却是因遗子。\n不自月中来，又那得、萧萧风味。\n霓裳旧曲，休问广寒人，飞太白，酬仙蕊。\n香外无香比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5454, '临江仙', '万俟咏', '寒甚正前三五日。\n风将腊雪侵寅。\n彩鸡缕燕已惊春。\n玉梅飞上苑，金柳动天津。\n□□□□□□□，□□□□□□。\n□□□□□□□。\n春盘共，绕坐庆时新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5455, '雪明鹊夜慢・雪明鹊夜', '万俟咏', '望五云多处春深，开阆苑、别就蓬岛。\n正梅雪韵清，桂月光皎。\n凤帐龙帘萦嫩风，御座深、翠金间绕。\n半天中、香泛千花，灯挂百宝。\n圣时观风重腊，有箫鼓沸空，锦绣匝道。\n竞呼卢、气贯调欢笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5456, '凤皇枝令・凤凰枝令', '万俟咏', '人间天上。\n端楼龙凤灯先赏。\n倾城粉黛月明中，春思荡。\n醉金瓯仙酿。\n一从鸾辂北向。\n旧时宝座应蛛网。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5457, '南歌子', '万俟咏', '梅夏暗丝雨，麦秋扇浪风。\n香芦结黍趁天中。\n五日凄凉今古、与谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5458, '明月照高楼慢・明月照高楼', '万俟咏', '平分素商。\n四垂翠幕，斜界银潢。\n颢气通建章。\n正烟澄练色，露洗水光。\n明映波融太液，影随帘挂披香。\n楼观壮丽，附霁云、耀绀碧相望。\n宫妆。\n三千从赭黄。\n万年世代，一部笙簧。\n夜宴花漏长。\n乍莺歌断续，燕舞回翔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5459, '失调名', '万俟咏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5460, '尉迟杯慢・尉迟杯', '万俟咏', '碎云薄。\n向碧玉枝缀万萼。\n如将汞粉匀开，疑使柏麝熏却。\n雪魄未应若。\n况天赋、标艳仍绰约。\n当暄风暖日佳处，戏蝶游蜂看著。\n重重绣帘珠箔。\n障艳霏霏，异香漠漠。\n见说徐妃，当年嫁了，信任玉钿零落。\n无言自啼露萧索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5461, '钿带长中腔', '万俟咏', '簇真香。\n似风前拆麝囊。\n嫩紫轻红，间斗异芳。\n风流富贵，自觉兰蕙荒。\n独占蕊珠春光。\n绣结流苏密织，魂梦悠扬。\n气融液散满洞房。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5462, '春草碧・番枪子', '万俟咏', '又随芳绪生，看翠霁连空，愁遍征路。\n东风里，谁望断西塞，恨迷南浦。\n天涯地角，意不尽、消沈万古。\n曾是送别长亭下，细绿暗烟雨。\n何处。\n乱红铺绣茵，有醉眠荡子，拾翠游女。\n王孙远，柳外共残照，断云无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5463, '三台', '万俟咏', '见梨花初带夜月，海棠半含朝雨。\n内苑春、不禁过青门，御沟涨、潜通南浦。\n东风静、细柳垂金缕。\n望凤阙、非烟非雾。\n好时代、朝野多欢，遍九陌、太平箫鼓。\n乍莺儿百啭断续，燕子飞来飞去。\n近绿水、台榭映秋千，斗草聚、双双游女。\n饧香更、酒冷踏青路。\n会暗识、夭桃朱户。\n向晚骤、宝马雕鞍，醉襟惹、乱花飞絮。\n正轻寒轻暖漏永，半阴半晴云暮。\n禁火天、已是试新妆，岁华到、三分佳处。\n清明看、汉宫传蜡炬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5464, '恋芳春慢', '万俟咏', '蜂蕊分香，燕泥破润，暂寒天气清新。\n帝里繁华，昨夜细雨初匀。\n万品花藏四苑，望一带、柳接重津。\n寒食近，蹴秋千，又是无限游人。\n红妆趁戏，绮罗夹道，青帘卖酒，台榭侵云。\n处处笙歌，不负治世良辰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5465, '安平乐慢', '万俟咏', '瑞日初迟，绪风乍暖，千花百草争香。\n瑶池路稳，阆苑春深，云树水殿相望。\n柳曲沙平，看尘随青盖，絮惹红妆。\n卖酒绿阴傍。\n无人不醉春光。\n有十里笙歌，万家罗绮，身世疑在仙乡。\n行乐知无禁，五侯半隐少年场。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5466, '卓牌儿・卓牌子', '万俟咏', '东风绿杨天，如画出、清明院宇。\n玉艳淡泊，梨花带月，胭脂零落，海棠经雨。\n单衣怯黄昏，人正在、珠帘笑语。\n相并戏蹴秋千，共携手、同倚栏干，暗香时度。\n翠窗绣户。\n路缭绕、潜通幽处。\n断魂凝伫。\n嗟不似飞絮。\n闲闷闲愁，难消遣、此日年年意绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5467, '昭君怨', '万俟咏', '春到南楼雪尽。\n惊动灯期花信。\n小雨一番寒。\n倚阑干。\n莫把阑干倚。\n一望几重烟水。\n何处是京华。\n暮云遮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5468, '昭君怨', '万俟咏', '一望西山烟雨。\n目断心飞何处。\n天外白云城。\n几多程。\n谩记阳关句。\n衣上粉啼痕污。\n陇水一分流。\n此生休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5469, '诉衷情', '万俟咏', '一鞭清晓喜还家。\n宿醉困流霞。\n夜来小雨新霁，双燕舞风斜。\n山不尽，水无涯。\n望中赊。\n送春滋味，念远情怀，分付杨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5470, '梅花引', '万俟咏', '晓风酸。\n晓霜乾。\n一雁南飞人度关。\n客衣单。\n客衣单。\n千里断魂，空歌行路难。\n寒梅惊破前村雪。\n寒鸡啼破西楼月。\n酒肠宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5471, '忆秦娥', '万俟咏', '千里草。\n萋萋尽处遥山小。\n遥山小。\n行有远似，此山多少。\n天若有情天亦老。\n此情说便说不了。\n说不了。\n一声唤起，又惊春晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5472, '忆少年', '万俟咏', '陇云溶泄，陇山峻秀，陇泉呜咽。\n行人暂驻马，已不胜愁绝。\n上陇首、凝眸天四阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5473, '长相思', '万俟咏', '一声声。\n一更更。\n窗外芭蕉窗里灯。\n此时无限情。\n梦难成。\n恨难平。\n不道愁人不喜听。\n空阶滴到明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5474, '长相思', '万俟咏', '短长亭。\n古今情。\n楼外凉蟾一晕生。\n雨馀秋更清。\n暮云平。\n暮山横。\n几叶秋声和雁声。\n行人不要听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5475, '木兰花慢', '万俟咏', '恨莺花渐老，但芳草、绿汀洲。\n纵岫壁千寻，榆钱万叠，难买春留。\n梅花向来始别，又匆匆，结子满枝头。\n门外垂杨岸侧，画桥谁系兰舟。\n悠悠。\n岁月如流。\n叹水覆、杳难收。\n凭画阑，往往抬头举眼，都是春愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5476, '武陵春', '万俟咏', '燕子飞来花在否，微雨退、掩重门。\n正满院梨花雪照人。\n独自个、怯黄昏。\n轻风淡月总消魂。\n罗衣暗惹啼痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5477, '快活年近拍', '万俟咏', '千秋万岁君，五帝三王世。\n观风重令节，与民乐盛际。\n蕊宫长春，洞天不老，花艳蝉辉，十里照春珠翠。\n闹罗绮。\n遥望太极，一簇通明里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5478, '醉蓬莱', '万俟咏', '正波泛银汉，漏滴铜壶，上元佳致。\n绛烛银灯，若繁星连缀。\n明月逐人，暗尘随马，尽五陵豪贵。\n鬓惹乌云，裙拖湘水，谁家姝丽。\n金阙南边，彩山北面，接地罗绮，沸天歌吹。\n六曲屏开，拥三千珠翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5479, '芰荷香', '万俟咏', '小潇湘。\n正天影倒碧，波面容光。\n水仙朝罢，间列绿盖红幢。\n吹风细雨，荡十顷、清香。\n人在水精中央。\n霜绡雾，襟袂收凉。\n款放轻舟闹红里，有晴蜓点水，交颈鸳鸯。\n翠阴密处，曾觅相并青房。\n晚霞散绮，泛远净、一叶鸣榔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5480, '别瑶姬慢・忆瑶姬', '万俟咏', '可惜香红。\n又一番骤雨，几阵狂风。\n霎时留不往，便夜来和月，飞过帘栊。\n离愁未了，酒病相仍，便堪此恨中。\n片片随、流水斜阳去，各自西东。\n又还是、九十春光，误双飞蝶，并采游峰。\n人生能几许，细算来何物，得似情浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5481, '忆秦娥', '万俟咏', '天如洗。\n金波冷浸冰壶里。\n冰壶里。\n一年得似，此宵能几。\n等闲莫把栏干倚。\n马蹄去便三千里。\n三千里。\n几重云岫，几重烟水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5482, '南柯子・南歌子', '田为', '梦怕愁时断，春从醉里回。\n凄凉怀抱向谁开。\n些子清明时候、被莺催。\n柳外都成絮，栏边半是苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5483, '南柯子・南歌子', '田为', '团玉梅梢重，香罗芰扇低。\n帘风不动蝶交飞。\n一样绿阴庭院、锁斜晖。\n对月怀歌扇，因风念舞衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5484, '念奴娇', '田为', '嫩冰未白，被霜风换却，满院秋色。\n小阁深沈围坐促，初拥红炉宜窄。\n帘密收香，窗明迟夜，砚冷凝新滴。\n无人知道，个中多少岑寂。\n翻念一枕高唐，当年仙梦觉，难寻消息。\n睡起微醒衣袖重，不管腰支犹索。\n旋暖银簧，时添酥字，笋玉寒无力。\n如今肠断，暮云依旧凝碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5485, '探春・探春慢', '田为', '小雨分山，断云镂日，丹青难状清晓。\n柳眼窥晴，梅妆迎暖，林外幽禽啼早。\n烟径润如酥，正浓淡遥看堤草。\n望中新景无穷，最是一年春好。\n骄马黄金络脑。\n争探得东君，何处先到。\n万盏飞觞，千金倚玉，不肯轻辜年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5486, '惜黄花慢', '田为', '雁空浮碧，印晓月，露洗重阳天气。\n望极楼外，淡烟半隔疏林，掩映断桥流水。\n黄金篱畔白衣人，更谁会、渊明深意。\n晚风底。\n落日乱鸿，飞起无际。\n情多对景凄凉，念旧赏，步屐登高迢递。\n兴满东山，共携素手持杯，劝泛玉浆云蕊。\n此时霜鬓欲归心，谩老尽、悲秋情味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5487, '江神子慢・江城子慢', '田为', '玉台挂秋月。\n铅素浅，梅花傅香雪。\n冰姿洁。\n金莲衬、小小凌波罗袜。\n雨初歇。\n楼外孤鸿声渐远，远山外、行人音信绝。\n此恨对语犹难，那堪更寄书说。\n教人红销翠减，觉衣宽金缕，都为轻别。\n太情切。\n消魂处、画角黄昏时节。\n声呜咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5488, '转调二郎神・二郎神', '徐伸', '闷来弹雀，又搅破、一帘花影。\n谩试著春衫，还思纤手，熏彻金炉烬冷。\n动是愁多如何向，但怪得、新来多病。\n想旧日沈腰，而今潘鬓，不堪临镜。\n重省。\n别时泪滴，罗衣犹凝。\n料为我厌厌，日高慵起，长托春酲未醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5489, '喜迁莺', '江汉', '升平无际。\n庆八载相业，君臣鱼水。\n镇抚风，调燮精神，合是圣朝房魏。\n凤山政好，还被画毂朱轮催起。\n按锦辔。\n映玉带金鱼，都人争指。\n丹陛。\n常注意。\n追念裕陵，元佐今无几。\n绣衮香浓，鼎槐风细。\n荣耀满门朱紫。\n四方具瞻师表，尽道一夔足矣。\n运花笔，又管领年年，烘春桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5490, '失调名', '田中行', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5491, '风入松', '田中行', '一宵风雨送春归。\n绿暗红稀。\n画楼尽日凭阑意，与谁同拈花枝。\n门外蔷薇开也，枝头梅子酸时。\n玉人应是数归期。\n翠敛愁眉。\n塞鸿不到双鱼远，恨楼前、流水难西。\n新恨欲题红叶，东风满院花飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5492, '喜迁莺', '赵温之', '琼姿冰体。\n料莹光乍傅，广寒宫里。\n北陆寒深，南园春先，此後万花方起。\n翦霞斗萼，栽芯砌□，天与高致。\n大潇洒，最宜雪宜月，宜亭宜水。\n好是。\n天涯庾岭上，万珠浮动香千里。\n写横斜，鬟插垂袅，占尽秀骨清意。\n醉魂易醒，吟兴信来，佳思无际。\n为传语，向东风，甘使无言桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5493, '踏青游', '赵温之', '竹外溪边，一枝破寒冲腊。\n莹素肌、玉雕冰刻。\n赋闲标，足馀韵，岂同常格。\n最风流，生来处处尽好，别得造化工力。\n疏影幽香，意思迥然殊绝。\n算不枉、诗人分别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5494, '踏莎行', '赵温之', '妖艳相偎，清香交喷。\n花王尤喜来亲迎。\n有如二女事唐虞，群芳休更夸相并。\n小雨资娇，轻风借润。\n天应知我怜孤韵。\n莫惊岁岁有双葩，仪真自古风流郡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5495, '谒金门', '王庭', '溪风紧。\n溪上官梅整整。\n万木寒痴吹不醒。\n一枝先破冷。\n梦断香云耿耿。\n月淡梨花清影。\n长笛倚楼谁共听。\n调高成绝品。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5496, '凤栖梧・蝶恋花', '王庭', '琼海无边银浪卷。\n画戟朱楼，缥缈云间见。\n当日使君曾拥传。\n海霞光里时开宴。\n翠红鳞吹酒面。\n莫谓今朝，人在天涯远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5497, '醉桃源・阮郎归', '王庭', '朱门映柳画帘垂。\n门前闻马嘶。\n主人新著绿袍归。\n天恩下玉墀。\n凭翠袖，拈花枝。\n劝教人醉时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5498, '临江仙', '王庭', '家住天门阊阖外，别来几度花开。\n近传消息到江淮。\n玉京知好在，金阙尚崔嵬。\n流落江南山尽处，雨馀苍翠成堆。\n暂同溪馆醉尊。\n恐随丹诏动，且任玉山颓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5499, '临江仙', '王庭', '问道春来相识否，岭头昨夜开花。\n水村烟坞寄生涯。\n月寒疏影淡，整整复斜斜。\n素面玉妃嫌粉污，晨妆洗尽铅华。\n香肌应只饭胡麻。\n年年如许瘦，知是阿谁家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5500, '临江仙', '王庭', '寂寞久无红袖饮，忽逢浩齿轻讴。\n坐令孤客洗穷愁。\n谁知沅水上，却似洛城游。\n闻道辰溪贤令长，深房别锁明眸。\n多年铅鼎养青虬。\n不应携妓女，骑鹤上扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5501, '临江仙', '王庭', '帘外东风吹断梦，卷帘人探春还。\n一枝疏影动檐间。\n鸳鸯□瓦冷，霜月堕栏干。\n闻道寿阳如许好，晨妆洗尽微殷。\n可怜玉骨瘦孱孱。\n谁家长笛□，吹彻玉楼寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5502, '人娇', '王庭', '小院桃花，烟锁几重珠箔。\n更深後、海棠睡著。\n东风吹去，落谁家墙角。\n平白地教人，为他情恶。\n花若有情，情应不薄。\n也须悔从前事错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5503, '忆秦娥', '王庭', '梅花发。\n夜寒吹笛千山月。\n千山月。\n此时愁听，龙吟幽噎。\n数枝飞尽南枝雪。\n风光又作年时别。\n年时别。\n江头心绪，乱丝千结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5504, '念奴娇', '王庭', '少年时节，见皇州灯火，衣冠朝市。\n天汉桥边瞻凤辇，帘幕千家垂地。\n人似神仙，身游佛国，谪堕红尘里。\n如今憔悴，渐无往岁欢味。\n此夜帝里喧传，太平祥瑞，有街头人醉。\n更值端门新又起，楼阙千兵严卫。\n朝野多欢，边庭初静，歌舞方腾沸。\n良宵好景，异时多少遗事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5505, '点绛唇', '王庭', '花外红楼，当时青鬓颜如玉。\n淡烟残烛。\n醉入花间宿。\n白发相逢，犹唱当时曲。\n当时曲。\n断弦难续。\n且尽杯中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5506, '点绛唇', '王庭', '玉漏春迟，铁关金锁星桥夜。\n暗尘随马。\n明月应无价。\n天半朱楼，银汉星光射。\n更深也。\n翠娥如画。\n犹在凉蟾下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5507, '点绛唇', '王庭', '春入西园，数重花外红楼起。\n倚阑金翠。\n人在非烟里。\n风月佳时，蓬岛开平地。\n笙歌沸。\n画桥灯市。\n一夜惊桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5508, '西江月', '王庭', '一拂退黄衫子，几团嗅芯蜂儿。\n西风吹下月中枝。\n种在寒岩影里。\n人道蜡梅相似，又传菊满东篱。\n饶伊颜色入时宜。\n安得香传九里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5509, '江城子', '王庭', '锦袍绣帽跃金鞍。\n卷旗幡。\n整师还。\n轻骑穷追，湘尾鼓声寒。\n千里尘清高会处，张翠幕，万人看。\n藕丝衫袖捧雕盘。\n玉颓山。\n夜将阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5510, '江城子', '王庭', '渡头犹唱棹歌声。\n雨初晴。\n月初生。\n忽见飞虹，夭矫挂寒汀。\n两岸小儿齐拍手，今夜里，放人行。\n朱栏画照江亭。\n客来登。\n眼初明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5511, '江城子', '王庭', '夜郎江上看元宵。\n斗回杓。\n雪初消。\n灯火银花，何处是星桥。\n哄得满城春不夜，三妓女，五溪徭。\n此时回首忆行朝。\n太平楼。\n倚层宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5512, '江城子', '王庭', '天回北斗欲中宵。\n屡移杓。\n客魂消。\n记得皇州，灯火虹成桥。\n异俗西南开万里，冠带尽，百蛮徭。\n卢溪太守未还朝。\n起朱楼。\n接丛宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5513, '江城子', '王庭', '楼头钟鼓变新声。\n晚霞晴。\n水云生。\n何处归帆，争泊蓼花汀。\n遥望虹桥如画里，鳌背上，著人行。\n夜阑风定见危亭。\n却重登。\n景方明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5514, '蝶恋花', '王庭', '月落灯残人散後。\n忽到尊前，但觉眉儿皱。\n数日不来如许瘦。\n裙腰减尽君知否。\n公子风流应自有。\n占断春光，肯落谁人手。\n已是许多时做就。\n重教舞彻双罗袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5515, '蝶恋花', '王庭', '罨画楼中人已醉。\n别院微闻，笑语帘垂地。\n催唤倾城香雾起。\n翠帷双卷春风里。\n妆样尖新歌妙丽。\n满酌金尊，不信人憔悴。\n饥客眼寒谁管你。\n主人见惯浑闲事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5516, '蝶恋花', '王庭', '桂树新生都几许。\n兄弟骑龙，双入蟾宫去。\n一日两枝同折处。\n娥拍手都分与。\n杨柳江头春色暮。\n白马青衫，两郡文章主。\n只恐远方难久住。\n高宗梦觉思霖雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5517, '满庭芳', '王庭', '颓玉成山，倾江作酒，醉来莫问升沈。\n少年狂怪，应笑老婆心。\n也会东涂西抹，行穿过、柳陌花阴。\n诚何用，腰龟左顾，犹待铸黄金。\n如今。\n回首处，青楼缥缈，朱箔重深。\n叹江海飘零，离恨难禁。\n好在铜梁玉垒，将军骑、他日重临。\n归来看，文君未老，相对抚鸣琴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5518, '满庭芳', '王庭', '宿雨初收，晚风微度，万家帘卷青烟。\n暗尘随马，人物似神仙。\n试问天公借月，天须放、明月教圆。\n应移下，广寒宫殿，灯火接星躔。\n卢川。\n元古郡，当时太守，宾从俱贤。\n到如今井邑，歌吹喧阗。\n花下红妆卖酒，时相遇、曲水桥边。\n谁知道，山城父老，重见中兴年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5519, '满庭芳', '王庭', '东阁官梅，玉栏朱槛，未如山馆疏篱。\n水边竹外，斜出两三枝。\n最好西湖月下，林处士、著意吟时。\n何须说，扬州旧日，何逊更能诗。\n谁知。\n深雪里，玉妃粲粲，初下瑶池。\n笑人间春色，只在桃蹊。\n紫燕黄鹂解语，来时但、青实离离。\n争知道，调羹附鼎，终得近丹墀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5520, '柳梢青', '王庭', '兰亭丝竹。\n高会群贤，其人如玉。\n曲水流觞，灯前细雨，檐花蔌蔌。\n舞雩初试春衣，听咏歌、童子五六。\n泽畔行吟，沙汀拾翠，满江新绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5521, '菩萨蛮', '王庭', '武陵西上沅陵渡。\n扁舟忘了来时路。\n花外有人烟。\n相逢疑是仙。\n清尊留夜语。\n醉倒知何处。\n归去客心惊。\n金鸡嘲哳鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5522, '浣溪沙', '王庭', '薄薄春衫簇绮霞。\n画檐晨起见栖鸦。\n宿妆仍拾落梅花。\n回首高楼闻笑语，倚栏红袖卷轻纱。\n玉肌微减旧时些。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5523, '浣溪沙', '王庭', '九里香风动地来。\n寻香空绕百千回。\n错惊秋色上崔嵬。\n谁识芗林三昧手，能令花落又花开。\n返魂元学岭头梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5524, '虞美人', '王庭', '城东楼阁连云起。\n冠绝辰州市。\n莲灯初发万枝红。\n也似江南风景、半天中。\n花衢柳陌年时静。\n划地今年盛。\n棚前箫鼓闹如雷。\n添个辰溪女子、舞三台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5525, '桃源忆故人', '王庭', '催花一霎清明雨。\n留得东风且住。\n两岸柳汀烟坞。\n未放行人去。\n人如双鹄云间举。\n明夜扁舟何处。\n只向武陵南渡。\n便是长安路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5526, '醉花阴', '王庭', '红尘紫阳春来早。\n晚市烟光好。\n灯发万枝莲，华月光中，天净开蓬岛。\n老人旧日曾年少。\n年少还须老。\n今夕在天涯，烛影星桥，也似长安道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5527, '醉花阴', '王庭', '玉妃谪堕烟村远。\n犹似瑶池见。\n缺月挂寒梢，时有幽香，飞到朱帘畔。\n春风岭上淮南岸。\n曾为谁魂断。\n依旧瘦，天若有情，天也应须管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5528, '醉花阴', '王庭', '月娥昨夜江头过。\n把素衫揉破。\n冷逐晓云归，留与东风，吹作千千朵。\n云残香瘦春犹可。\n玉笛愁无那。\n倚著画楼人，且莫教他，吹动些儿个。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5529, '雨霖铃', '王庭', '琼楼玉宇。\n满人寰似、海边洲渚。\n蓬莱又还水浅，鲸涛静见，银宫如许。\n紫极鸣筲声断，望霓舟何处。\n待夜深、重倚层霄，认得瑶池广寒路。\n郢中旧曲谁能度。\n恨歌声、响入青云去。\n西湖近时绝唱，总不道、月梅盐絮。\n暗想当年宾从，毫端有惊人句。\n谩说枚叟邹生，共作梁园赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5530, '鹊桥仙', '王庭', '云静天高，山明水阔。\n一年待个中秋月。\n十分魄少一分圆，今宵已觉蟾光别。\n且尽金尊，遥瞻玉阙。\n更深江水沙如雪。\n来宵风雨不相关，重须买酒追佳节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5531, '感皇恩', '王庭', '飞雪满貂裘，马蹄轻骤。\n笔下文章焕星斗。\n凌云才调，尽是夺标高手。\n况闻场屋里，知名久。\n金榜篆云，银鞍披绣。\n归去天香满衣袖。\n莫辞今夕，且尽一尊芳酒。\n为君歌一曲，为君寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5532, '感皇恩', '王庭', '羸马怯征鞍，欲骤。\n昨夜文星动南斗。\n广寒宫近，欲上烟霄携手。\n素娥不奈冷，凄凉久。\n知是谪仙，肝肠锦绣。\n天半清风动襟袖。\n而今西笑，且饮新丰美酒。\n悠然还独酌，谁为寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5533, '感皇恩', '王庭', '一叶下西风，寒生南浦。\n椎鼓鸣桡送君去。\n长亭把酒，却倩阿谁留住。\n尊前人似玉，能留否。\n醉中暂听，离歌几许。\n听不能终泪如雨。\n无情江水，断送扁舟何处。\n归时烟浪卷，朱帘暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5534, '寰海清', '王庭', '画鼓轰天。\n暗尘随宝马，人似神仙。\n天恁不教昼短，明月长圆。\n天应未知道，天天。\n须肯放、三夜如年。\n流酥拥上香。\n为个甚、晚妆特地鲜妍。\n花下清阴乍合，曲水桥边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5535, '浪淘沙', '王庭', '翠袖卷轻纱。\n玉腕慵遮。\n蕊珠宫殿倚彤霞。\n不愤江南梅信早，争下香车。\n月露洗凝华。\n艳压群葩。\n暗传春信到天涯。\n试问东风谁第一，先到人家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5536, '好事近', '王庭', '宴罢莫匆匆，聊驻玉鞍金勒。\n闻道建溪新焙，尽龙蟠苍璧。\n黄金碾入碧花瓯，瓯翻素涛色。\n今夜酒醒归去，觉风生两腋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5537, '解佩令', '王庭', '湘江停瑟。\n洛川回雪。\n是耶非、相逢飘瞥。\n云鬓风裳，照心事、娟娟山月。\n翦烟花、带萝同结。\n留环盟切。\n贻珠情彻。\n解携时、玉声愁绝。\n罗袜尘生，早波面、春痕欲灭。\n送人行、水声凄咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5538, '西江月', '薛式', '一是金丹总数，河图象出真机。\n谁知罔象尽玄微。\n大道从兹孕起。\n斗柄璇玑正位，阴中却抱阳辉。\n子母著绯衣。\n此是乾坤真理。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5539, '西江月', '薛式', '偃月炉中金鼎，三台两曜行神。\n尊卑简易汞中真。\n握固休推心肾。\n白虎长存坎户，青龙却与南邻。\n阴魂阳魄似窗尘。\n大意不离玄牝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5540, '西江月', '薛式', '天上三清真境，三皇五帝规模。\n瞿昙老氏仲尼徒。\n经史深藏妙素。\n间有真人出世，来明赤子玄珠。\n蟾光终日耀昏衢。\n满目黄芽显露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5541, '西江月', '薛式', '内有五行相制，包含一粒红铅。\n相生相杀自天然。\n此药殊无贵贱。\n会向我家园里，栽培一亩天田。\n中男小女共相连。\n种得黄芽满院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5542, '西江月', '薛式', '凿破玄元三五，拨开造化圭璋。\n希夷妙旨在中央。\n咫尺无名罔象。\n片饷工夫便得，教君地久天长。\n蓬莱仙岛是吾乡。\n怎不留心信向。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5543, '西江月', '薛式', '竹破须还竹补，人衰须假铅全。\n思量只是眼睛前。\n自是时人不见。\n日月相交离坎，龙蛇产在先天。\n长生妙药在家园。\n一饷工夫便现。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5544, '西江月', '薛式', '此道至灵至圣，无令泄漏轻为。\n全凭德行两相宜。\n言语须防避忌。\n要籍五行生旺，须明阳盛阴衰。\n三人同志谨防危。\n进火工夫仔细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5545, '西江月', '薛式', '炼就光明莹玉，回来却入黄泉。\n升腾须假至三年。\n携养殷勤眷恋。\n九九才终变化，神功岂假言宣。\n分明顷刻做神仙。\n永驾鸾车凤辇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5546, '西江月', '薛式', '一气初回遇朔，鼎中神水温温。\n刚柔相会气均匀。\n妙在无过浑沌。\n八卦循回循绕，推排九窍追奔。\n东西沈静合朝昏。\n莫与常人议论。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5547, '临江仙', '陈克', '枕帐依依残梦，斋房忽忽馀酲。\n薄衣团扇绕阶行。\n曲阑幽树，看得绿成阴。\n檐雨为谁凝咽，林花似我飘零。\n微吟休作断肠声。\n流莺百啭，解道此时情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5548, '临江仙', '陈克', '四海十年兵不解，胡尘直到江城。\n岁华销尽客心惊。\n疏髯浑似雪，衰涕欲生冰。\n送老齑盐何处是，我缘应在吴兴。\n故人相望若为情。\n别愁深夜雨，孤影小窗灯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5549, '渔家傲', '陈克', '宝瑟尘生郎去後。\n绿窗闲却春风手。\n浅色宫罗新染就。\n晴时後。\n裁缝细意花枝斗。\n象尺熏炉移永昼。\n粉涩蔷薇透。\n晚景看来浑似旧。\n沈吟久。\n个侬争得知人瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5550, '浣溪沙', '陈克', '浅画香膏拂紫绵。\n牡丹花重翠云偏。\n手梅子并郎肩。\n病起心情终是怯，困来模样不禁怜。\n旋移针线小窗前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5551, '浣溪沙', '陈克', '香雾空堕彩蟾。\n倾城催映出重帘。\n□□银烛夜厌厌。\n何物与侬供醉眼，半黄梅子带红盐。\n粉融香润玉纤纤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5552, '浣溪沙', '陈克', '淡墨花枝掩薄罗。\n嫩蓝裙子湘波。\n水晶新样碾风荷。\n问著似羞还似恶，恼来成笑不成歌。\n芙蓉帐里奈君何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5553, '浣溪沙', '陈克', '短烛荧荧照碧窗。\n重重帘幕护梨霜。\n幽欢不怕夜偏长。\n罗袜钿钗红粉醉，曲屏深幔绿橙香。\n征鸿离远断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5554, '浣溪沙', '陈克', '小院春来百草青。\n拂墙桃李已飘零。\n绝知春意总无凭。\n卢女嫁时终薄命，徐娘身老谩多情。\n洗香吹粉转娉婷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5555, '浣溪沙', '陈克', '窗纸幽幽不肯明。\n寒更忍作断肠声。\n背人残烛却多情。\n合下心期唯有梦，如今魂梦也无凭。\n几行闲泪莫纵横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5556, '摊破浣溪沙・山花子', '陈克', '慢梳头浅画眉。\n乱莺残梦起多时。\n不道小庭花露湿，翦酴。\n帘额好风低燕子，窗油晴日打蜂儿。\n翠袖粉笺闲弄笔，写新诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5557, '谒金门', '陈克', '花满院。\n飞去飞来双燕。\n红雨入帘寒不卷。\n晓屏山六扇。\n翠袖玉笙凄断。\n脉脉两娥愁浅。\n消息不知郎近远。\n一春长梦见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5558, '谒金门', '陈克', '柳丝碧。\n柳下人家寒食。\n莺语匆匆花寂寂。\n玉阶春藓湿。\n闲凭薰笼无力。\n心事有谁知得。\n檀炷绕窗灯背壁。\n画檐残雨滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5559, '谒金门', '陈克', '深院静。\n尘暗曲房凄冷。\n黄叶满阶风不定。\n无端吹酒醒。\n露湿小园幽径。\n悄悄啼姑相应。\n半被馀熏残烛影。\n夜长人独冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5560, '谒金门', '陈克', '春漏促。\n谁见两人心曲。\n罨画屏风银蜡烛。\n泪珠红蔌蔌。\n懊恼欢娱不足。\n只许梦中相逐。\n今夜月明何处宿。\n画桥春水绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5561, '谒金门', '陈克', '春草碧。\n忆著去年寒食。\n白红裙香□□，折花闹调客。\n好在江南江北。\n燕子不传消息。\n醉眼腾腾羞面赤。\n断肠侬记得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5562, '谒金门', '陈克', '罗帐薄。\n缥缈绮疏飞阁。\n红地团花金解络。\n香囊垂四角。\n尽日春风帘幕。\n谁见绿屏纤弱。\n云压枕函钗自落。\n无端春梦恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5563, '谒金门', '陈克', '愁脉脉。\n目断江南江北。\n烟树重重芳信隔。\n小楼山几尺。\n细草孤云斜日。\n一向弄晴天色。\n帘外落花飞不得。\n东风无气力。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5564, '谒金门', '陈克', '春寂寂。\n绿暗溪南溪北。\n溪水沈沈天一色。\n鸟飞春树黑。\n肠断小楼吹笛，醉里看朱成碧。\n愁满眼前遮不得。\n可怜双鬓白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5565, '虞美人', '陈克', '踏车不用青裙女。\n日夜歌声苦。\n风流墨绶强跻攀。\n唤起潜蛟飞舞、破天悭。\n公庭休更重门掩。\n细听催诗点。\n一尊已咏北窗风。\n卧看雪儿纤手、剥莲蓬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5566, '虞美人', '陈克', '小山戢戢盆池浅。\n芳树阴阴转。\n红阑干上刺蔷薇。\n蝴蝶飞来飞去、两三枝。\n绣裙斜立腰肢困。\n翠黛萦新恨。\n风流踪迹使人猜。\n过了斗鸡时节、合归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5567, '虞美人', '陈克', '绿阴满院帘垂地。\n落絮萦香砌。\n池光不定药栏低。\n闲并一双、没人时。\n旧欢黯黯成幽梦。\n帐卷金泥重。\n日虹斜处暗尘飞。\n脉脉小窗孤枕、镜花移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5568, '菩萨蛮', '陈克', '柳条闲庭院。\n锦波绣浪春风转。\n红日上阑干。\n晚来花更寒。\n绿檀金隐起。\n翠被香烟里。\n幽恨有谁知。\n空梁落燕泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5569, '菩萨蛮', '陈克', '赤阑桥尽香街直。\n笼街细柳娇无力。\n金碧上青空。\n花晴帘影红。\n黄衫飞白马。\n日日青楼下。\n醉眼不逢人。\n午香吹暗尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5570, '菩萨蛮', '陈克', '池塘淡淡浮。\n杏花吹尽垂杨碧。\n天气度清明。\n小园新雨晴。\n绿窗描绣罢。\n笑语酴下。\n围坐赌青梅。\n困从双脸来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5571, '菩萨蛮', '陈克', '绿芜墙绕青苔院。\n中庭日淡芭蕉卷。\n蝴蝶上阶飞。\n烘帘自在垂。\n玉钩双语燕。\n宝杨花转。\n几处簸钱声。\n绿窗春睡轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5572, '菩萨蛮', '陈克', '柳条到地莺声滑。\n鸳鸯睡稳清沟阔。\n九曲转朱阑。\n花深人对闲。\n日长刀尺罢。\n试屐樱桃下。\n髻玉钗风。\n云轻线脚红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5573, '菩萨蛮', '陈克', '绿阴寂寂樱桃下。\n盆池劣照蔷薇架。\n帘影假山前。\n映阶红叶翻。\n芭蕉笼碧砌。\n子中庭睡。\n香径没人来。\n拂墙花又开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5574, '点绛唇', '陈克', '曲陌春风，谁家姊妹同墙看。\n映花烘暖。\n困入茸茸眼。\n细马轻衫，倚醉偷回面。\n垂杨转。\n坠鞭挥扇。\n白地肝肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5575, '好事近', '陈克', '寻遍石亭春，黯黯暮山明灭。\n竹外小溪深处，倚一枝寒月。\n淡云疏雨苦无情，得折便须折。\n醉帽凤鬟归去，有馀香愁绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5576, '千秋岁', '陈克', '柏舟高躅。\n晚岁宜遐福。\n门户壮，疏汤沐。\n青袍围白发。\n端锦缥犀轴。\n仙桂长，交柯却映蟠桃熟。\n缥缈长江曲。\n入破□箫逐。\n香雾满，飞华屋。\n玉钩凉月挂，冰麝芙蓉馥。\n千万寿，酒中倒卧南山绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5577, '鹧鸪天', '陈克', '禁馀寒酒半醒。\n蒲萄力软被愁侵。\n鲤鱼不寄江南信，绿尽菖蒲春水深。\n疑梦断，怆离襟。\n重帘复幕静。\n赤阑干外梨花雨，还是去年寒食心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5578, '鹧鸪天', '陈克', '芳树阴阴脱晚红。\n馀香不断玉钗风。\n簿情夫婿花相似，一片西飞一片东。\n金翡翠，绣芙蓉。\n从教纤媚笑床空。\n揉蓝衫子休无赖，只与离人结短封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5579, '鹧鸪天', '陈克', '小市桥弯更向东。\n便门长记旧相逢。\n踏青会散秋千下，鬓影衣香怯晚风。\n悲往事，向孤鸿。\n断肠肠断旧情浓。\n梨花院落黄茅店，绣被春寒此夜同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5580, '豆叶黄・忆王孙', '陈克', '粉墙丹柱柳丝中。\n帘箔轻明花影重。\n午醉醒来一面风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5581, '豆叶黄・忆王孙', '陈克', '树头初日鹁鸠鸣。\n野店山桥新雨晴。\n短褐无泥竹杖轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5582, '豆叶黄・忆王孙', '陈克', '秋千人散小庭空。\n麝冷灯昏愁杀侬。\n独有闲阶两袖风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5583, '鹧鸪天', '陈克', '柳外东风不满旗。\n青裾白面出疏篱。\n来打鼓侬吹笛，催送儿郎踏浪飞。\n倾两耳，斗双螭。\n家家春酒泻尖泥。\n侬今已是沧浪客，莫向尊前唱教池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5584, '浣溪沙', '陈克', '罨画溪头春水生。\n铜官山外夕阳明。\n暖风无力小舟横。\n万事悠悠生处熟，三杯兀兀醉时醒。\n杏花杨柳更多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5585, '浣溪沙', '陈克', '桥北桥南新雨晴。\n柳边花底暮寒轻。\n万家灯火照溪明。\n凫舄差池官事了，木山彩错市人惊。\n街头酒贱唱歌声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5586, '减字木兰花', '陈克', '阆风玄圃。\n阳羡溪头山好处。\n郁郁葱葱。\n胜日尊笑语中。\n十分芳酒。\n鹤发初生千万寿。\n乐事年年。\n弟劝兄酬阿母前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5587, '临江仙', '陈克', '老屋风悲脱叶，枯城月破浮烟。\n谁人惨惨把忧端。\n蛮歌犯星起，重觉在天边。\n秋色巧摧愁鬓，夜寒偏著诗肩。\n不知桂影为谁圆。\n何须照床里，终是一人眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5588, '清平乐', '陈克', '枕边清血。\n梦好离肠切。\n笑倚柳条同挽结。\n满眼河桥烟月。\n莺啼新晓珑。\n罗窗寂寞春空。\n只许梦魂相近，此生枉是相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5589, '鹧鸪天', '陈克', '白苎吴侬红颊儿。\n行歌半是使君诗。\n山茶处处春犹浅，灯市人人夜不归。\n拚剧饮，莫相违。\n皇恩往往下丹墀。\n挥毫却对莲花炬，忆著苹洲秉烛时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5590, '南歌子', '陈克', '午夜添红蜡，分曹立翠娥。\n觥筹寂寂断经过。\n谁料绮丛香里、是银河。\n老去空髯戟，愁来奈脸波。\n一杯如此断肠何。\n枉杀两人心事、只闻歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5591, '南歌子', '陈克', '献鲤荣今日，凭熊瑞此邦。\n年年寿酒乐城隍。\n共道使君椿树、似甘棠。\n歌舞重城晓，从容燕席凉。\n不须苏合与都梁。\n风外荷花无数、是炉香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5592, '南歌子', '陈克', '北固烟中寺，西津雨後山。\n看公英气两眉间。\n如在林霏、江月袭人寒。\n展翼声名久，占熊福艾全。\n风流不是地行仙。\n好去鞭笞鸾凤、紫微天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5593, '南歌子', '陈克', '云里千山暖，溪头八月凉。\n华簪霭霭待萱堂。\n羡子怀中双橘、半青黄。\n老去齐眉案，闲来坦腹床。\n相如何日从长杨。\n惭愧年年高会、索槟榔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5594, '南歌子', '陈克', '胜日萱庭小，西风橘柚长。\n天怜扇枕彩衣郎。\n乞与淡云纤月、十分凉。\n潋滟三危雾，氤氲百濯香。\n年来椿树更苍苍。\n不用蓝桥辛苦、捣玄霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5595, '南歌子', '陈克', '画幛经梅润，罗衣尚麦寒。\n古苔苍石绿句栏。\n帘外映花新竹、两三竿。\n蠢蠢吴蚕卧，娉娉楚女闲。\n红阴角子共尝酸。\n肠断个侬憨态、小眉弯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5596, '南歌子', '陈克', '看月凭肩枨，娇春枕臂眠。\n不尽花絮夜来寒。\n帐底浓香残梦、更缠绵。\n起晚笼莺怪，妆迟绣伴牵。\n声声催唤药栏边。\n整髻收裙无力、上秋千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5597, '虞美人', '陈克', '越罗巧画春山叠。\n个里融香雪。\n满身空翠不胜寒。\n恰似那回偷印、小眉山。\n青骢油壁西陵下。\n仿佛当时话。\n而今眼底是高唐。\n拂拂淡云疏雨、断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5598, '双燕儿', '朱敦复', '尚志服事跛神仙。\n辛勤了、万千般。\n一朝身死入黄泉。\n至诚地、哭皇天。\n旁人苦苦叩玄言。\n不免得、告诸贤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5599, '聒龙谣', '朱敦儒', '肩拍洪崖，手携子晋，梦里暂辞尘宇。\n高步层霄，俯人间如许。\n算蜗战、多少功名，问蚁聚、几回今古。\n度银潢、展尽参旗，桂花澹，月飞去。\n天风紧，玉楼斜，舞万女霓袖，光摇金缕。\n明廷宴阕，倚青冥回顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5600, '聒龙谣', '朱敦儒', '凭月携箫，溯空秉羽，梦踏绛霄仙去。\n花冷街榆，悄中天风露。\n并真官、蕊佩芬芳，望帝所、紫云容与。\n享钧天、九奏传觞，听龙啸，看莺舞。\n惊尘世，悔平生，叹万感千恨，谁怜深素。\n群仙念我，好人间难住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5601, '雨中花・夜行船', '朱敦儒', '故国当年得意，射麋上苑，走马长楸。\n对匆匆佳气，赤县神州。\n好景何曾虚过，胜友是处相留。\n向伊川雪夜，洛浦花朝，占断狂游。\n胡尘卷地，南走炎荒，曳裾强学应刘。\n空漫说、螭蟠龙卧，谁取封侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5602, '水调歌头', '朱敦儒', '当年五陵下，结客占春游。\n红缨翠带，谈笑跋马水西头。\n落日经过桃叶，不管插花归去，小袖挽人留。\n换酒春壶碧，脱帽醉青楼。\n楚云惊，陇水散，两漂流。\n如今憔悴，天涯何处可消忧。\n长揖飞鸿旧月。\n不知今夕烟水，都照几人愁。\n有泪看芳草，无路认西州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5603, '水调歌头', '朱敦儒', '白日去如箭，达者惜分阴。\n问君何苦，长抱冰炭利名心。\n冀望封侯一品，侥升仙三岛，不死解烧金。\n听取百年曲，三叹有遗音。\n会良朋，逢美景，井频斟。\n昔人已矣，松下泉底不如今。\n幸遇重阳佳节，高处红萸黄菊，好把醉乡寻。\n澹澹飞鸿没，千古共销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5604, '水调歌头', '朱敦儒', '偏赏中秋月，从古到如今。\n金风玉露相间，别做一般清。\n是处帘栊争卷，谁家管弦不动，乐世足欢情。\n莫指关山路，空使翠蛾颦。\n水精盘，鲈鱼脍，点新橙。\n鹅黄酒暖，纤手传杯任频斟。\n须惜晓参横後，直到来年今夕，十二数亏盈。\n未必来年看，得似此回明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5605, '水调歌头', '朱敦儒', '平生看明月，西北有高楼。\n如今羁旅，常叹茅屋暗悲秋。\n闻说吴淞江上，有个垂虹亭好，结友漾轻舟。\n记得蓬莱路，端是旧曾游。\n趁黄鹄，湖影乱，海光浮。\n绝尘胜处，合是不数白苹洲。\n何物陶朱张翰，劝汝橙齑鲈脍，交错献还酬。\n寄语梅仙道，来岁肯同不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5606, '水调歌头', '朱敦儒', '天宇著垂象，日月共回旋。\n因何明月，偏被指点古来传。\n浪语修成七宝，漫说霓裳九奏，阿姊最婵娟。\n愤激书青奏，伏愿听臣言。\n诏六丁，驱狡兔，屏痴蟾。\n移根老桂，种在历历白榆边。\n深锁广寒宫殿，不许娥歌舞，按次守星躔。\n永使无亏缺，长对日团圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5607, '水调歌头', '朱敦儒', '中秋一轮月，只和旧青冥。\n都缘人意，须道今夕别般明。\n是处登临开宴，争看吴歌楚舞，沈醉倒金尊。\n各自心中事，悲乐几般情。\n烛摧花，鹤警露，忽三更。\n舞茵未卷，玉绳低转便西倾。\n认取眼前流景，试看月归何处，因甚有亏盈。\n我自阖门睡，高枕笑浮生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5608, '桂枝香', '朱敦儒', '春寒未定。\n是欲近清明，雨斜风横。\n深闭朱门，尽日柳摇金井。\n年光自趁飞花紧。\n奈幽人、雪添双鬓。\n谢山携妓，黄垆贳酒，旧愁慵整。\n念壮节、漂零未稳。\n负九江风笛，五湖烟艇。\n起舞悲歌，泪眼自看清影。\n新莺又向愁时听。\n把人间、如梦深省。\n旧溪鹤在，寻云弄水，是事休问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5609, '水龙吟', '朱敦儒', '放船千里凌波去。\n略为吴山留顾。\n云屯水府，涛随神女，九江东注。\n北客翩然，壮心偏感，年华将暮。\n念伊嵩旧隐，巢由故友，南柯梦、遽如许。\n回首妖氛未扫，问人间、英雄何处。\n奇谋报国，可怜无用，尘昏白羽。\n铁锁横江，锦帆冲浪，孙郎良苦。\n但求敲桂棹，悲吟梁父，泪流如雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5610, '水龙吟', '朱敦儒', '晓来极目同云，暧空降雪花零乱。\n平生尘想，老来俗状，都齐惊散。\n玉凤凌霄，素虬横海，一杯相劝。\n任霓裳学舞，梅妆作面，终不似、天裁翦。\n正是年华美满。\n斗迎春、巧飞钗燕。\n冲寒醉眼，倚空长揖，群仙笑粲。\n说道瑶池，有人来报，西真开宴。\n便争回蕊佩，高驰羽驾，卷东风转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5611, '念奴娇', '朱敦儒', '见梅惊笑，问经年何处，收香藏白。\n似语如愁，却问我、何苦红尘久客。\n观里栽桃，仙家种杏，到处成疏隔。\n千林无伴，澹然独傲霜雪。\n且与管领春回，孤标争肯接、雄蜂雌蝶。\n岂是无情，知受了、多少凄凉风月。\n寄驿人遥，和羹心在，忍使芳尘歇。\n东风寂寞，可怜谁为攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5612, '念奴娇', '朱敦儒', '插天翠柳，被何人，推上一轮明月。\n照我藤床凉似水，飞入瑶台琼阙。\n雾冷笙箫，风轻环佩，玉锁无人掣。\n闲云收尽，海光天影相接。\n谁信有药长生，素娥新炼就、飞霜凝雪。\n打碎珊瑚，争似看、仙桂扶疏横绝。\n洗尽凡心，满身清露，冷浸萧萧发。\n明朝尘世，记取休向人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5613, '念奴娇', '朱敦儒', '晚凉可爱，是黄昏人静，风生苹叶。\n谁作秋声穿细柳，初听寒蝉凄切。\n旋采芙蓉，重熏沈水，暗里香交彻。\n拂开冰簟，小床独卧明月。\n老来应免多情，还因风景好，愁肠重结。\n可惜良宵人不见，角枕兰衾虚设。\n宛转无眠，起来闲步，露草时明灭。\n银河西去，画楼残角呜咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5614, '念奴娇', '朱敦儒', '老来可喜，是历遍人间，谙知物外。\n看透虚空，将恨海愁山，一时碎。\n免被花迷，不为酒困，到处惺惺地。\n饱来觅睡，睡起逢场作戏。\n休说古往今来，乃翁心里，没许多般事。\n也不蕲仙不佞佛，不学栖栖孔子。\n懒共贤争，从教他笑，如此只如此。\n杂剧打了，戏衫脱与呆底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5615, '念奴娇', '朱敦儒', '素秋天气，是登山临水，昔人悲处。\n我遇清时无个事，好约莺迁鸿翥。\n旋整兰舟，多携芳酝，笑里轻帆举。\n松江缆月，望云飞棹延伫。\n别乘文雅风流，新词光万丈，珠连锦聚。\n恨不同游，指浩渺、玉宇琼楼相付。\n桂子收香，蟾辉采露，暂辍尊前舞。\n丝囊封寄，倩他双翠衔去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5616, '念奴娇', '朱敦儒', '腊回春近，正日添宫线，香传梅驿。\n玉律冰壶此际显，天与奇才英识。\n贯日孤忠，凌云独志，曾展回天力。\n功名由命，等闲却铩鸾翮。\n谁信夫子如今，眠云情意稳，风尘机息。\n邂逅初心得计处，伊水鸥闲波碧。\n但恐天教，经纶缘在，未遂紫烟客。\n君王图旧，看公归觐京国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5617, '念奴娇', '朱敦儒', '放船纵棹，趁吴江风露，平分秋色。\n帆卷垂虹波面冷，初落萧萧枫叶。\n万顷琉璃，一轮金鉴，与我成三客。\n碧空寥阔，瑞星银汉争白。\n深夜悄悄鱼龙，灵旗收暮霭，天光相接。\n莹澈乾坤，全放出、叠玉层冰宫阙。\n洗尽凡心，相忘尘世，梦想都销歇。\n胸中云海，浩然犹浸明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5618, '苏武慢', '朱敦儒', '枕海山横，陵江潮去，雉堞秋风残照。\n闲寻桂子，试听菱歌，湖上晚来凉好。\n几处兰舟，采莲游女，归去隔花相恼。\n奈长安不见，刘郎已老，暗伤怀抱。\n谁信得、旧日风流，如今憔悴，换却五陵年少。\n逢花倒，遇酒坚辞，常是懒歌慵笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5619, '木兰花慢', '朱敦儒', '折芙蓉弄水，动玉佩、起秋风。\n正柳外闲云，溪头澹月，映带疏钟。\n人间厌谪堕久，恨霓旌未返碧楼空。\n且与时人度日，自怜怀抱谁同。\n当时种玉五云东。\n露冷夜耕龙。\n念瑞草成畦，琼疏未采，尘染衰容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5620, '木兰花慢', '朱敦儒', '指荣河峻岳，锁胡尘、几经秋。\n叹故苑花空，春游梦冷，万斛堆愁。\n簪缨散、关塞阻，恨难寻杏馆觅瓜畴。\n凄惨年来岁往，断鸿去燕悠悠。\n拘幽。\n化碧海西头。\n剑履问谁收。\n但易水歌传，子山赋在，青史名留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5621, '洞仙歌', '朱敦儒', '今年生日，庆一百省岁。\n喜趁烧灯作欢会。\n问先生有甚，阴德神丹，霜雪里、鹤在青松相似。\n总无奇异处，只是天然，冷澹寻常旧家计。\n探袖弄明珠，满眼儿孙，一壶酒、□向花间长醉。\n且落魄、装个老人星，共野叟行歌，太平时世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5622, '洞仙歌', '朱敦儒', '风流老峭，负不群奇表。\n弹指超凡怎由教。\n把俗儒故纸，推向一边，三界外、寻得一场好笑。\n尘缘无处，应见宰官，苦行公心众难到。\n这功名富贵，有也寻常，管做得、越古超今神妙。\n待接得、众生总成佛，向酒肆淫房，再逞年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5623, '洞仙歌', '朱敦儒', '何人不爱，是江梅红绽。\n雪野寒空冻云晚。\n照清溪绰约，粉艳先春，包绛萼、姑射冰肌自暖。\n上林花万品，都借风流，国色天香任欣羡。\n共素娥青女，一笑相逢，人不见、悄悄霜宫月殿。\n想乘云、是在玉皇前，粲蕊佩明，侍清都燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5624, '满庭芳', '朱敦儒', '鹏海风波，鹤巢云水，梦残身寄尘寰。\n老来穷健，无闷也无欢。\n随分饥餐困睡，浑忘了、秋热春寒。\n清平世，闲人自在，乘兴访溪山。\n渔竿。\n要老伴，浮江载酒，舣棹观澜。\n倩轻鸥假道，白鹭随轩。\n直到垂虹亭上，惊怪我、却做仙官。\n中秋月，披襟四顾，不似在人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5625, '满庭芳', '朱敦儒', '花满金盆，香凝碧帐，小楼晓日飞光。\n有人相伴，开镜点新妆。\n脸嫩琼肌著粉，眉峰秀、波眼宜长。\n云鬟就，玉纤溅水，轻笑换明。\n檀郎。\n犹恣意，高凤枕，慵下银床。\n问今日何处，斗草寻芳。\n不管馀酲未解，扶头酒、亲捧瑶觞。\n催人起，雕鞍翠，乘露看姚黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5626, '满江红', '朱敦儒', '竹翠阴森，寒泉浸、几峰奇石。\n销畏日、溪蒲呈秀，水蕉供碧。\n筠簟平铺光欲动，纱高挂空无色。\n似月明、苹叶起秋风，潇湘白。\n不敢笑，红尘客。\n争肯羡，神仙宅。\n且披襟脱帽，自适其适。\n靖节窗风犹有待，本初朔饮非长策。\n怎似我、心闲便清凉，无南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5627, '风流子', '朱敦儒', '吴越东风起，江南路，芳草绿争春。\n倚危楼纵目，绣帘初卷，扇边寒减，竹外花明。\n看西湖、画船轻泛水，茵幄稳临津。\n嬉游伴侣，两两携手，醉回别浦，歌遏南云。\n有客愁如海，江山异，举目暗觉伤神。\n空想故园池阁，卷地烟尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5628, '望海潮', '朱敦儒', '嵩高维岳，图书之渊，西都二室三川。\n神鼎定金，麟符刻玉，英灵未称河山。\n谁再整乾坤。\n是挺生真主，浴日开天。\n御归梁苑，驾回汾水凤楼闲。\n升平运属当千。\n眷凝旒暇日，西顾依然。\n银汉诏虹，瑶台赐碧，一新瑞气祥烟。\n重到帝居前。\n怪鹊桥龙阙，飞下人间。\n父老欢呼，翠华来也太平年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5629, '胜胜慢・声声慢', '朱敦儒', '红炉围锦，翠幄盘雕，楼前万里同云。\n青雀窥窗，来报瑞雪纷纷。\n开帘放教飘洒，度华筵、飞入金尊。\n斗迎面，看美人呵手，旋罗巾。\n莫说梁园往事，休更羡、越溪访戴幽人。\n此日西湖真境，圣治中兴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5630, '芰荷香', '朱敦儒', '远寻花。\n正风亭霁雨，烟浦移沙。\n缓提金勒，路拥桃叶香车。\n凭高帐饮，照羽觞、晚日横斜。\n六朝浪语繁华。\n山围故国，绮散馀霞。\n无奈尊前万里客，叹人今何在，身老天涯。\n壮心零落，怕听叠鼓掺挝。\n江浮醉眼，望浩渺、空想灵槎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5631, '沁园春', '朱敦儒', '七十衰翁，告老归来，放怀纵心。\n念聚星高宴，围红盛集，如何著得，华发陈人。\n勉意追随，强颜陪奉，费力劳神恐未真。\n君休怪，近频辞雅会，不是无情。\n岩扃。\n旧菊犹存。\n更松偃、梅疏新种成。\n爱静窗明几，焚香宴坐，闲调绿绮，默诵黄庭。\n莲社轻舆，雪溪小棹，有兴何妨寻弟兄。\n如今且，花迷酒困，心迹双清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5632, '卜算子慢', '朱敦儒', '凭高望远，云断路迷，山簇暮寒凄紧。\n兰菊如斯，燕子怎知秋尽。\n想闺中、锦换新翻晕。\n自解佩匆匆散後，鸳鸯到今难问。\n只得愁成病。\n是悔上瑶台，误留金枕。\n不忍相忘，万里再寻音信。\n奈飘风、不许蓬莱近。\n又一番、冻雨凄凉，送归鸿成阵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5633, '醉春风', '朱敦儒', '夜饮西真洞。\n群仙惊戏弄。\n素娥传酒袖凌风，送送送。\n吸尽金波，醉朝天阙，斗班星拱。\n碧简承新宠。\n紫微恩露重。\n忽然推枕草堂空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5634, '踏歌', '朱敦儒', '宴阕。\n散津亭鼓吹扁舟发。\n离魂黯、隐隐阳关彻。\n更风愁雨细添凄切。\n恨结。\n叹良朋雅会轻离诀。\n一年价、把酒风花月。\n便山遥水远分吴越。\n书倩雁，梦借蝶。\n重相见、且把归期说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5635, '鹊桥仙', '朱敦儒', '溪清水浅，月胧烟澹，玉破梅梢未遍。\n横枝依约影如无，但风里、空香数点。\n乘风欲去，凌波难住，谁见红愁粉怨。\n夜深青女湿微霜，暗香散、广寒宫殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5636, '鹊桥仙', '朱敦儒', '今年冬後，黄花初绽。\n莫怪时光较晚。\n晓来玉露芳丛，莹秀色、无尘到眼。\n支筇驻屐，徘徊篱畔。\n弄酌金杯自泛。\n须添罗幕护风霜，要留与、疏梅相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5637, '鹊桥仙', '朱敦儒', '娥怕闹，银蟾传令，且与遮鸾翳凤。\n直须人睡俗尘清，放云汉、冰轮徐动。\n山翁散发，披衣松下，琴奏瑶池三弄。\n曲终鹤警露华寒，笑浊世、饶伊做梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5638, '鹊桥仙', '朱敦儒', '携琴寄鹤，辞山别水，乘兴随云做客。\n囊中欲试紫金丹，待点化、鸾红凤碧。\n谁知到此，玉梯无路，天上难通消息。\n不如却趁白云归，免误使、山英扫迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5639, '鹊桥仙', '朱敦儒', '竹西散策，花阴围坐，可恨来迟几日。\n披香不觉玉壶空，破酒面、飞红半湿。\n悲歌醉舞，九人而已，总是天涯倦客。\n东风吹泪故园春，问我辈、何时去得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5640, '鹊桥仙', '朱敦儒', '白鸥欲下，金鱼不去，圆叶低开蕙帐。\n轻风冷露夜深时，独自个、凌波直上。\n幽阑共晚，明难寄，尘世教谁将傍。\n会寻织女趁灵槎，泛旧路、银河万丈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5641, '临江仙', '朱敦儒', '西子溪头春到也，大家追趁芳菲。\n盘雕翦锦换障泥。\n花添金凿落，风展玉东西。\n先探谁家梅最早，雪儿桂子同携。\n别翻舞袖按新词。\n从今排日醉，醉过牡丹时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5642, '临江仙', '朱敦儒', '堪笑一场颠倒梦，元来恰似浮云。\n尘劳何事最相亲。\n今朝忙到夜，过腊又逢春。\n流水滔滔无住处，飞光忽忽西沈。\n世间谁是百年人。\n个中须著眼，认取自家身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5643, '临江仙', '朱敦儒', '直自凤凰城破後，掰钗破镜分飞。\n天涯海角信音稀。\n梦回辽海北，魂断玉关西。\n月解重圆星解聚，如何不见人归。\n今春还听杜鹃蹄。\n年年看塞雁，一十四番回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5644, '临江仙', '朱敦儒', '最好中秋秋夜月，常时易雨多阴。\n难逢此夜更无云。\n玉轮飞碧落，银幕换层城。\n桂子香浓凝瑞露，中兴气象分明。\n酒楼灯市管弦声。\n今宵谁肯睡，醉看晓参横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5645, '临江仙', '朱敦儒', '生长西都逢化日，行歌不记流年。\n花间相过酒家眠。\n乘风游二室，弄雪过三川。\n莫笑衰容双鬓改，自家风味依然。\n碧潭明月水中天。\n谁闲如老子，不肯作神仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5646, '临江仙', '朱敦儒', '纱帽篮舆青织盖，儿孙从我嬉游。\n绿池红径雨初收。\n桃偏会笑，细柳几曾愁。\n随分盘筵供笑语，花间社酒新。\n踏歌起舞醉方休。\n陶潜能啸傲，贺老最风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5647, '临江仙', '朱敦儒', '几日春愁无意绪，拈金翦彩慵拈。\n小楼终日怕凭阑。\n一双新泪眼，千里旧关山。\n苦恨碧云音信断，只教征雁空还。\n早知盟约是虚言。\n枉裁诗字锦，悔寄泪痕笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5648, '临江仙', '朱敦儒', '信取虚空无一物，个中著甚商量。\n风头紧後白云忙。\n风元无去住，云自没行藏。\n莫听古人闲语话，终归失马亡羊。\n自家肠肚自端详。\n一齐都打碎，放出大圆光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5649, '鹧鸪天', '朱敦儒', '草草园林作洛川。\n碧宫红塔借风烟。\n虽无金谷花能笑，也有铜驼柳解眠。\n春似旧，酒依前。\n何妨倚杖雪垂肩。\n五陵侠少今谁健，似我亲逢建武年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5650, '鹧鸪天', '朱敦儒', '检尽历头冬又残。\n爱他风雪忍他寒。\n拖条竹杖家家酒，上个篮舆处处山。\n添老大，转痴顽。\n谢天教我老来闲。\n道人还了鸳鸯债，纸帐梅花醉梦间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5651, '鹧鸪天', '朱敦儒', '我是清都山水郎，天教懒慢带疏狂。\n曾批给露支风敕，累奏留云借月章。\n诗万首，酒千觞，几曾着眼看侯王？玉楼金阙慵归去，且插梅花醉洛阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5652, '鹧鸪天', '朱敦儒', '唱得梨园绝代声。\n前朝惟数李夫人。\n自从惊破霓裳後，楚奏吴歌扇里新。\n秦嶂雁，越溪砧。\n西风北客两飘零。\n尊前忽听当时曲，侧帽停杯泪满巾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5653, '鹧鸪天', '朱敦儒', '曾为梅花醉不归。\n佳人挽袖乞新词。\n轻红遍写鸳鸯带，浓碧争斟翡翠卮。\n人已老，事皆非。\n花前不饮泪沾衣。\n如今但欲关门睡，一任梅花作雪飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5654, '鹧鸪天', '朱敦儒', '画舫东时洛水清。\n别离心绪若为情。\n西风挹泪分携後，十年长亭九梦君。\n云背水，雁回汀。\n只应芳草见离魂。\n前回共采芙蓉处，风自凄凄月自明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5655, '鹧鸪天', '朱敦儒', '竹粉吹香杏子丹。\n试新纱帽衣宽。\n日长几案琴书静，地僻池塘鸥鹭闲。\n寻汗漫，听潺。\n澹然心寄水云间。\n无人共酌松黄酒，时有飞仙暗往还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5656, '鹧鸪天', '朱敦儒', '至节先庚欲雪天。\n玳筵围锦帐青毡。\n嫖姚副帅招佳客，太守高明别乘贤。\n歌宛转，舞蹁迁。\n金钗十二拥婵娟。\n老人南极星边住，也趁梅花听管弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5657, '鹧鸪天', '朱敦儒', '凤烛星球初试灯。\n冰轮辗破碧棱层。\n来宵虽道十分满，未必胜如此夜明。\n留上客，换瑶觥。\n任教楼外晓参横。\n春风从旧偏怜我，那更娥是故人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5658, '鹧鸪天', '朱敦儒', '通处灵犀一点真。\n随紫橐步红茵，个中自是神仙住，花作帘栊玉作人。\n偏澹静，最尖新。\n等闲舞雪振歌尘。\n若教宋玉尊前见，应笑襄王梦里寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5659, '鹧鸪天', '朱敦儒', '天上人间酒最尊。\n非甘非苦味通神。\n一杯能变愁山色，三盏全迥冷谷春。\n欢後笑，怒时。\n醒来不记有何因。\n古时有个陶元亮，解道君当恕醉人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5660, '鹧鸪天', '朱敦儒', '有个仙人捧玉卮。\n满斟坚劝不须辞。\n瑞龙透顶香难比，甘露浇心味更奇。\n开道域，洗尘机。\n融融天乐醉瑶池。\n霓裳拽住君休去，待我醒时更一。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5661, '鹧鸪天', '朱敦儒', '不系虚舟取性颠。\n浮河泛海不知年。\n乘风安用青帆引，逆浪何须锦缆牵。\n云荐枕，月铺毡。\n无朝无夜任横眠。\n太虚空里知谁管，有个明官唤做天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5662, '鹧鸪天', '朱敦儒', '极目江湖水浸云。\n不堪回首洛阳春。\n天津帐饮凌云客，花市行歌绝代人。\n穿绣陌，踏香尘。\n满城沈醉管弦声。\n如今远客休惆怅，饱向皇都见太平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5663, '木兰花・玉楼春', '朱敦儒', '老後人间无去处。\n多谢碧桃留我住。\n红尘回步旧烟霞，清境开扉新院宇。\n隐几日长香一缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5664, '木兰花・玉楼春', '朱敦儒', '前日寻梅椒样缀。\n今日寻梅蜂已至。\n乍开绛萼欲生香，略绽粉苞先有意。\n古人今日升沈异。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5665, '蓦山溪', '朱敦儒', '邻家相唤，酒熟闲相过。\n竹径引篮舆，会乡老、吾曹几个。\n沈家姊妹，也是可怜人，回巧笑，发清歌，相间花间坐。\n高谈阔论，无可无不可。\n幸遇太平年，好时节、清明初破。\n浮生春梦，难得是欢娱，休要劝，不须辞，醉便花间卧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5666, '蓦山溪', '朱敦儒', '琼蔬玉蕊。\n久寄清虚里。\n春到碧溪东，下白云、寻桃问李。\n弹簧吹叶，懒傍少年场，遗楚佩，觅秦箫，踏破青鞋底。\n河桥酒熟，谁解留侬醉。\n两袖拂飞花，空一春、凄凉憔悴。\n东风误我，满帽洛阳尘，唤飞鸿，遮落日，归去烟霞外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5667, '蓦山溪', '朱敦儒', '西真姊妹。\n只这梅花是。\n乘醉下瑶池，粉燕支、何曾梳洗。\n冰姿素艳，无意压群芳，独自笑，有时愁，一点心难寄。\n雪添蕊佩。\n霜护盈盈泪。\n尘世悔重来，梦凄凉，玉楼十二。\n教些香去，说与惜花人，云黯澹，月朦胧，今夜谁同睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5668, '蓦山溪', '朱敦儒', '夜来雨过，桃李将开遍。\n策杖引儿童，也学人、随莺趁燕。\n青天许大，多少好风光，一岁去，一春来，只恁空扰乱。\n西池琼苑。\n游赏人何限。\n玉勒拥朱轮，各骋些、新欢旧怨。\n都齐醉也，说甚是和非，我笑他，他不觉，花落春风晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5669, '蓦山溪', '朱敦儒', '元来尘世。\n放著希奇事。\n行到路穷时，果别有、真山真水。\n登临任意，随步白云生，三秀草，九花藤，满袖琼瑶蕊。\n何须麴老，浩荡心常醉。\n唱个快活歌，更说甚、黄梁梦里。\n苍颜华发，只是旧时人，不动步，却还家，处处新桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5670, '蓦山溪', '朱敦儒', '东风不住。\n几阵黄梅雨。\n风外晓莺声，怨飘零、花残春暮。\n鸳鸯散後，供了十年愁，怀旧事，想前欢，忍记丁宁语。\n尘昏青镜，休照孤鸾舞。\n烟锁凤楼空，问吹箫、人今何处。\n小窗惊梦，携手似平生，阳台路。\n行云去。\n目断山无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5671, '蓦山溪', '朱敦儒', '西江东去，总是伤时泪。\n北陆日初长，对芳尊、多悲少喜。\n美人去後，花落几春风，杯漫洗。\n人难醉。\n愁见飞灰细。\n梅边雪外。\n风味犹相似。\n迤逦暖乾坤，仗君主、雄风英气。\n吾曹老矣，端是有心人、追剑履。\n辞黄绮。\n珍重萧生意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5672, '朝中措', '朱敦儒', '先生馋病老难医。\n赤米厌晨炊。\n自种畦中白菜，腌成瓮里黄齑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5673, '朝中措', '朱敦儒', '先生筇杖是生涯。\n挑月更担花。\n把住都无憎爱，放行总是烟霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5674, '朝中措', '朱敦儒', '当年弹铗五陵间。\n行处万人看。\n雪猎星飞羽箭，春游花簇雕鞍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5675, '朝中措', '朱敦儒', '东方千骑拟三河。\n灯夕试春罗。\n想是蟾宫高会，暂留暮雨娥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5676, '朝中措', '朱敦儒', '闲愁无奈指频弹。\n芳景为谁残。\n可惜良宵虚过，且容草草谋欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5677, '朝中措', '朱敦儒', '元宵初过少吹弹。\n楼角彩灯残。\n踏雪闲寻深院，携壶试觅幽欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5678, '朝中措', '朱敦儒', '夜来听雪晓来看。\n惊失却尘寰。\n摇撼琼林玉树，心疑身是仙官。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5679, '朝中措', '朱敦儒', '新来省悟一生痴。\n寻觅上天梯。\n抛失眼前活计，踏翻暗里危机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5680, '朝中措', '朱敦儒', '登临何处自销忧。\n直北看扬州。\n朱雀桥边晚市，石头城下新秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5681, '朝中措', '朱敦儒', '胸中尘土久无奇。\n今夕借清辉。\n歌纵群英诸彦，舞狂蕙带荷衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5682, '朝中措', '朱敦儒', '红稀绿暗掩重门。\n芳径罢追寻。\n已是老於前岁，那堪穷似他人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5683, '促拍丑奴儿', '朱敦儒', '清露湿幽香。\n想瑶台、无语凄凉。\n飘然欲去，依然如梦，云度银潢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5684, '醉落魄・一斛珠', '朱敦儒', '海山叠翠。\n夕阳殷雨云堆雪。\n鹧鸪声里蛮花发。\n我共扁舟，江上两萍叶。\n东风落酒愁难说。\n谁教春梦分胡越。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5685, '醉思仙', '朱敦儒', '倚晴空。\n正三洲下叶，七泽收虹。\n叹年光催老，身世飘蓬。\n南歌客，新丰酒，但万里、云水俱东。\n谢故人，解系船访我，脱帽相从。\n人世欢易失，尊俎且更从容。\n任酒倾波碧，烛翦花红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5686, '感皇恩', '朱敦儒', '曾醉武陵溪，竹深花好。\n玉佩云鬟共春笑。\n主人好事，坐客雨巾风帽。\n日斜青凤舞，金尊倒。\n歌断渭城，月沈星晓。\n海上归来故人少。\n旧游重到。\n但有夕阳衰草。\n恍然真一梦，人空老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5687, '感皇恩', '朱敦儒', '早起未梳头，小园行遍。\n拄杖穿花露犹泫。\n菊篱瓜畹。\n最喜引枝添蔓。\n先生独自笑，流莺见。\n著意访寻，幽香国艳。\n千里移根未为远。\n浅深相间。\n最要四时长看。\n群芳休怪我，归来晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5688, '感皇恩', '朱敦儒', '一个小园儿，两三亩地。\n花竹随宜旋装缀。\n槿篱茅舍，便有山家风味。\n等闲池上饮，林间醉。\n都为自家，胸中无事。\n风景争来趁游戏。\n称心如意。\n剩活人间几岁。\n洞天谁道在，尘寰外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5689, '杏花天', '朱敦儒', '挂帘等月阑干曲。\n厌永昼、劳烟倦局。\n单衣汗透鲛绡缩。\n脱帽梳犀枕玉。\n移床就、碧梧翠竹。\n寄语倩、娥伴宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5690, '杏花天', '朱敦儒', '听蝉翦叶迎秋燕。\n画戟散、金铺开遍。\n清风占住秦筝怨。\n楼上衙牌易晚。\n飞雨过、绣幕尽卷。\n借水沈、龙涎旋碾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5691, '杏花天', '朱敦儒', '残春庭院东风晓。\n细雨打、鸳鸯寒峭。\n花尖望见秋千了。\n无路踏青斗草。\n人别後、碧云信杳。\n对好景、愁多欢少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5692, '恋绣衾', '朱敦儒', '木落江南感未平。\n雨萧萧、衰鬓到今。\n甚处是长安路，水连空、山锁暮云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5693, '青玉案', '朱敦儒', '芝房并蒂空称瑞。\n几曾见、香旎旎。\n也不论兰休比蕙。\n王孙高韵，说得的当，不减唐诸李。\n今朝影落琼杯里。\n共才子佳人斗高致。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5694, '南歌子', '朱敦儒', '住近沈香浦，门前蕙草春。\n鸳鸯飞下柘枝新。\n见弄青梅初著、翠罗裙。\n怕唤拈歌扇，嫌催上舞茵。\n几时微步不生尘。\n来作维摩方丈、散花人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5695, '苏幕遮', '朱敦儒', '瘦仙人，穷活计。\n不养丹砂，不肯参同契。\n两顿家餐三觉睡。\n闭著门儿，不管人闲事。\n又经年，知几岁。\n老屋穿空，幸有天遮蔽。\n不饮香醪常似醉。\n白鹤飞来，笑我颠颠地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5696, '苏幕遮', '朱敦儒', '酒壶空，歌扇去。\n独倚危楼，无限伤心处。\n芳草连天云薄暮。\n故国山河，一阵黄梅雨。\n有奇才，无用处。\n壮节飘零，受尽人间苦。\n欲指虚无问征路。\n回首风云，未忍辞明主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5697, '浪淘沙', '朱敦儒', '圆月又中秋。\n南海西头。\n蛮云瘴雨晚难收。\n北客相逢弹泪坐，合恨分愁。\n无酒可销忧。\n但说皇州。\n天家宫阙酒家楼。\n今夜只应清汴水，呜咽东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5698, '浪淘沙', '朱敦儒', '风约雨横江。\n秋满篷窗。\n个中物色尽凄凉。\n更是行人行未得，独系归。\n拥被换残香。\n黄卷堆床。\n开愁展恨翦思量。\n伊是浮云侬是梦，休问家乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5699, '浪淘沙', '朱敦儒', '白菊好开迟。\n冷蝶空迷。\n沾风惹露也随时。\n何事深藏偏在後，天性难移。\n陶令最怜伊。\n同病相医。\n寒枝瘦叶更栽培。\n直待群芳零落後，独殿东篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5700, '千秋岁', '朱敦儒', '占秋呈瑞。\n四海杨公子。\n蹋拖尚带蓬壶体。\n清新春草句，潇洒兰亭字。\n宦情少，眠云弄月知心事。\n此去应无滞。\n稳步烟宵地。\n鹏万里，鹤千岁。\n他年黄阁老，访我清溪醉。\n青凤舞，贻君万斛瑶花蕊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5701, '定风波', '朱敦儒', '红药花前欲送春。\n金鞭柘弹趁芳尘。\n故傍绣帘柳线。\n恰见。\n澹梳妆映瘦腰身。\n闲倚金铺书闷字。\n尤。\n为谁憔悴减心情。\n放下彩毫匀粉泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5702, '踏莎行', '朱敦儒', '梅倚江娥，日舒宫线。\n老人星唤群仙宴。\n泛杯玉友暖飞浮，堆盘金橘光零乱。\n听命宽心，随缘适愿。\n痴狂赢取身长健。\n醉中等看碧桃春，尊前莫问蓬莱浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5703, '踏莎行', '朱敦儒', '花涨藤江，草熏鸭步。\n锦帆兰棹分春去。\n二翁元是一溪云，暂为山北山南雨。\n绿酒多斟，白须休觑。\n飞丹约定烟霞侣。\n与君先占赤城春，回桡早趁桃源路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5704, '梦玉人引', '朱敦儒', '浪萍风梗，寄人间，倦为客。\n梦里瀛洲，姓名误题仙籍。\n敛翅归来，爱小园、蜕箨碧。\n新种幽花，戒儿童休摘。\n放怀随分，各逍遥，飞等鹏翼。\n舍此萧闲，问君携杖安适。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5705, '一落索', '朱敦儒', '一夜雨声连晓。\n青灯相照。\n旧时情绪此时心，花不见、人空老。\n可惜春光闲了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5706, '一落索', '朱敦儒', '惯被好花留住。\n蝶飞莺语。\n少年场上醉乡中，容易放、春归去。\n今日江南春暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5707, '渔家傲', '朱敦儒', '谁转琵琶弹侧调。\n征尘万里伤怀抱。\n客散黄昏庭院悄。\n灯相照。\n春寒燕子归来早。\n可惜韶光虚过了。\n多情人已非年少。\n只恐莺啼春又老。\n知音少。\n人间何处寻芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5708, '渔家傲', '朱敦儒', '鉴水稽山尘不染。\n归来贺老身强健。\n有客跨鲸游汗漫。\n留羽扇。\n玉船取酒青鸾劝。\n莫恨飞花容易散。\n仙家风味何曾减。\n春色一壶丹九转。\n堪为伴。\n雕粱幸有轻盈燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5709, '渔家傲', '朱敦儒', '畏暑闲寻湖上径。\n雨丝断送凉成阵。\n风里芙蓉斜不整。\n沈红影。\n约回萍叶波心静。\n催唤吴姬迎小艇。\n妆花烛焰明相映。\n饮到夜阑人却醒。\n风雨定。\n欲归更把阑干凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5710, '望江南・忆江南', '朱敦儒', '炎昼永，初夜月侵床。\n露卧一丛莲叶畔，芙蓉香细水风凉。\n枕上是仙乡。\n浮世事，能有几多长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5711, '十二时・忆少年', '朱敦儒', '连云衰草，连天晚照，连山红叶。\n西风正摇落，更前溪呜咽。\n燕去鸿归音信绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5712, '南乡子', '朱敦儒', '宫样细腰身。\n玉带罗衫稳试新。\n小底走来宣对御，催频。\n曲殿西厢小苑门。\n歌舞斗轻盈。\n不许杨花上锦茵。\n劝得君王真个醉，承恩。\n金凤红袍印粉痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5713, '南乡子', '朱敦儒', '风雪打黄昏。\n别殿无人早闭门。\n拜了天香罗袖冷，低颦。\n催灭银灯解绣裙。\n金鸭卧残薰。\n看破屏风数泪痕。\n回首昭阳天样远，销魂。\n又过梅花一番春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5714, '行香子', '朱敦儒', '宝篆香沈。\n锦瑟尘侵。\n日长时、懒把金针。\n裙腰暗减，眉黛长颦。\n看梅花过，梨花谢，柳花新。\n春寒院落，灯火黄昏。\n悄无言、独自销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5715, '忆帝京', '朱敦儒', '元来老子曾垂教。\n挫锐和光为妙。\n因甚不听他，强要争工巧。\n只为忒惺惺，惹尽闲烦恼。\n你但莫、多愁早老。\n你但且、不分不晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5716, '桃源忆故人', '朱敦儒', '飘萧我是孤飞雁。\n不共红尘结怨。\n几度蓬莱清浅。\n侧翅曾傍看。\n有时飞入西真院。\n许趁风光流转。\n玉芯绿花开遍。\n可惜无人见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5717, '桃源忆故人', '朱敦儒', '小园雨霁秋光转。\n天气微寒犹暖。\n黄菊红蕉庭院。\n翠径苔痕软。\n眼前明快眉间展。\n细酌霞觞不浅。\n一曲广陵弹遍。\n目送飞鸿远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5718, '桃源忆故人', '朱敦儒', '雨斜风横香成阵。\n春去空留春恨。\n欢少愁多因甚。\n燕子浑难问。\n碧尖蹙损眉慵晕。\n泪湿燕支红沁。\n可惜海棠吹尽。\n又是黄昏近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5719, '桃源忆故人', '朱敦儒', '西楼几日无人到。\n依旧红围绿绕。\n楼下落花谁扫。\n不见长安道。\n碧云望断无音耗。\n倚遍阑干残照。\n试问泪弹多少。\n湿遍楼前草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5720, '桃源忆故人', '朱敦儒', '谁能留得朱颜住。\n枉了百般辛苦。\n争似萧然无虑。\n任运随缘去。\n人人放著逍遥路。\n只怕君心不悟。\n弹指百年今古。\n有甚成亏处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5721, '桃源忆故人', '朱敦儒', '玉笙吹彻清商後。\n寂寞弓弯舞袖。\n巧画远山不就。\n只为眉长皱。\n灵犀望断星难透。\n立到凄凉时候。\n今夜月明如昼。\n人共梅花瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5722, '好事近', '朱敦儒', '春雨细如尘，楼外柳丝黄湿。\n风约绣帘斜去，透窗纱寒碧。\n美人慵翦上元灯，弹泪倚瑶瑟。\n却上紫姑香火，问辽东消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5723, '好事近', '朱敦儒', '春雨挠元宵，花绽柳眠无力。\n风峭画堂帘幕，卷金泥红湿。\n王孙开宴聚娇饶，越山洗愁碧。\n休说凤凰城里，少年时踪迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5724, '好事近', '朱敦儒', '惊见老仙来，触目琳琅奇绝。\n打酒道人林下，奏醉翁三叠。\n接倾倒海云飞，物色又催别。\n回棹晚江春雨，胜剡溪风雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5725, '好事近', '朱敦儒', '春去尚堪寻，莫恨老来难却。\n且趁禁烟百七，醉残英馀萼。\n坐间玉润赋妍辞，情语见真乐。\n引满瘿杯竹盏，胜黄金凿落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5726, '好事近', '朱敦儒', '摇首出红尘，醒醉更无时节。\n活计绿蓑青笠，惯披霜冲雪。\n晚来风定钓丝闲，上下是新月。\n千里水天一色，看孤鸿明灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5727, '好事近', '朱敦儒', '眼里数闲人，只有钓翁潇洒。\n已佩水仙宫印，恶风波不怕。\n此心那许世人知，名姓是虚假。\n一棹五湖三岛，任船儿尖耍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5728, '好事近', '朱敦儒', '渔父长身来，只共钓竿相识。\n随意转船回棹，似飞空无迹。\n芦花开落任浮生，长醉是良策。\n昨夜一江风雨，都不曾听得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5729, '好事近', '朱敦儒', '拨转钓鱼船，江海尽为吾宅。\n恰向洞庭沽酒，却钱塘横笛。\n醉颜禁冷更添红，潮落下前碛。\n经过子陵滩畔，得梅花消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5730, '好事近', '朱敦儒', '短棹钓船轻，江上晚烟笼碧。\n塞雁海鸥分路，占江天秋色。\n锦鳞拨刺满蓝鱼，取酒价相敌。\n风顺片帆归去，有何人留得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5731, '好事近', '朱敦儒', '猛向这边来，得个信音端的。\n天与一轮钓线，领烟波千亿。\n红尘今古转船头，鸥鹭已陈迹。\n不受世间拘束，任东西南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5732, '好事近', '朱敦儒', '绿泛一瓯云，留住欲飞胡蝶。\n相对夜深花下，洗萧萧风月。\n从容言笑醉还醒，争忍便轻别。\n只愿主人留客，更重斟金叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5733, '好事近', '朱敦儒', '失却故山云，索手指空为客。\n莼菜鲈鱼留我，住鸳鸯湖侧。\n偶然添酒旧壶卢，小醉度朝夕。\n吹笛月波楼下，有何人相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5734, '好事近', '朱敦儒', '深住小溪春，好在柳枝桃叶。\n风澹水轩人静，数双飞胡蝶。\n日长时有一莺啼，兰佩为谁结。\n销散旧愁新恨，泛琴心三叠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5735, '好事近', '朱敦儒', '我不是神仙，不会炼丹烧药。\n只是爱闲耽酒，畏浮名拘缚。\n种成桃李一园花，真处怕人觉。\n受用现前活计，且行歌行乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5736, '长相思', '朱敦儒', '昨日晴。\n今日阴。\n楼下飞花楼上云。\n阑干双泪痕。\n江南人。\n江北人。\n一样春风两样情。\n晚寒潮未平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5737, '长相思', '朱敦儒', '海云黄。\n橘洲霜。\n如箭滩流石似羊。\n溪船十丈长。\n人难量。\n水难量。\n过险方知著甚忙。\n归休老醉乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5738, '乌夜啼', '朱敦儒', '翦胜迎春後，和风入律频催。\n前回下叶飞霜处，红绽一枝梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5739, '沙塞子', '朱敦儒', '万里飘零南越，山引泪、酒添愁。\n不见凤楼龙阙、又惊秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5740, '沙塞子', '朱敦儒', '蛮径寻春春早，千点雪，已飞梅。\n席地插花传酒、日西催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5741, '西江月', '朱敦儒', '澹澹薰风庭院，青青过雨园林。\n铜驼陌上旧莺声。\n今日江边重听。\n落帽酒中有趣，题桥琴里无心。\n香残沈水缕烟轻。\n花影阑干人静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5742, '西江月', '朱敦儒', '琴上金星正照，砚中眼相青。\n闲来自觉有精神。\n心海风恬浪静。\n且喜面前花好，更听林外莺新。\n瓮头清辣洞庭春。\n醉里徐行路稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5743, '西江月', '朱敦儒', '元是西都散汉，江南今日衰翁。\n从来颠怪更心风。\n做尽百般无用。\n屈指八旬将到，回头万事皆空。\n云间鸿雁草间虫。\n共我一般做梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5744, '西江月', '朱敦儒', '穷後常如囚系，老来半似心风。\n饥蚊饿蚤不相容。\n一夜何曾做梦。\n被我不扇不捉，廓然总是虚空。\n寺钟官角任西东。\n别弄些儿骨董。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5745, '西江月', '朱敦儒', '世事短如春梦，人情薄似秋云。\n不须计较苦劳心。\n万事原来有命。\n幸遇三杯酒好，况逢一朵花新。\n片时欢笑且相亲。\n明日阴晴未定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5746, '西江月', '朱敦儒', '日日深杯酒满，朝朝小圃花开。\n自歌自舞自开怀。\n且喜无拘无碍。\n青史几番春梦，黄泉多少奇才。\n不须计较与安排。\n领取而今现在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5747, '西江月', '朱敦儒', '正月天饶阴雨，江南寒在晨朝。\n娇莺声袅杏花梢。\n暗澹绿窗春晓。\n好梦空留被在，新愁不共香销。\n小楼帘卷路迢迢。\n望断天涯芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5748, '西江月', '朱敦儒', '织素休寻往恨，攀条幸有前缘。\n隔河彼此事经年。\n且说蓬莱清浅。\n障面重新团扇，倾鬟再整花钿。\n歌云舞雪画堂前。\n长共阿郎相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5749, '减字木兰花', '朱敦儒', '花弄扇。\n碧斗遥山眉黛晚。\n白玉阑干。\n倚遍春风翠袖寒。\n难寻可见。\n何似一双青翅燕。\n人瘦春残。\n芳草连云日下山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5750, '减字木兰花', '朱敦儒', '寻花携李。\n红漾轻舟汀柳外。\n小簇春山。\n溪雨岩云不饱帆。\n相逢心醉。\n容易堆盘银烛泪。\n痛饮何言。\n犀箸敲残玉酒船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5751, '减字木兰花', '朱敦儒', '东风桃李。\n春水绿波花影外。\n载酒胥山。\n祓禊相期落锦帆。\n吾曹一醉。\n却笑新亭人有泪。\n相对清言。\n不觉黄昏雨打船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5752, '减字木兰花', '朱敦儒', '闲人行李。\n羽扇芒鞋尘世外。\n一叠溪山。\n也解分风送客帆。\n时平易醉。\n无复惊心并溅泪。\n长揖忘言。\n回棹桃花插满船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5753, '减字木兰花', '朱敦儒', '刘郎已老。\n不管桃花依旧笑。\n要听琵琶。\n重院莺啼觅谢家。\n曲终人醉。\n多似浔阳江上泪。\n万里东风。\n国破山河落照红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5754, '减字木兰花', '朱敦儒', '慵歌怕酒。\n今日春衫惊著瘦。\n双燕帘栊。\n金鸭香沈客泪中。\n琵琶重听。\n谁信人间多少恨。\n落日东风。\n吹得桃花满院红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5755, '减字木兰花', '朱敦儒', '古人误我。\n独舞西风双泪堕。\n鹤去无踪。\n木落西陵返照红。\n人间难住。\n掷下酒杯何处去。\n楼锁钟残。\n山北山南两点烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5756, '减字木兰花', '朱敦儒', '无知老子。\n元住渔舟樵舍里。\n暂借权监。\n持节纡朱我甚惭。\n不能者止。\n免苦龟肠忧虎尾。\n身退心闲。\n剩向人间活几年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5757, '减字木兰花', '朱敦儒', '斫鱼作。\n酒面打开香可。\n相唤同来。\n草草杯盘饮几杯。\n人生虚假。\n昨日梅花今日谢。\n不醉何为。\n从古英雄总是痴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5758, '减字木兰花', '朱敦儒', '今年梅晚。\n懒趁寿阳钗上燕。\n月唤霜催。\n不肯人间取次开。\n低鬟掩袂。\n愁寄玉阑金井外。\n粉瘦香寒。\n独抱深心一点酸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5759, '减字木兰花', '朱敦儒', '无人惜我。\n我自殷勤怜这个。\n恧峭惺惺。\n不肯随人独自行。\n乾坤许大。\n只在棘针尖上坐。\n依旧多情。\n搂著虚空睡到明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5760, '减字木兰花', '朱敦儒', '年衰人老。\n矍铄支离君莫笑。\n白日青天。\n我自心情胜少年。\n超凡入妙。\n游戏神通随意到。\n酒圣诗仙。\n舞棹虚空驾铁船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5761, '减字木兰花', '朱敦儒', '虚空无碍。\n你自痴迷不自在。\n撒手游行。\n到处笙歌拥路迎。\n天然美满。\n不用些儿心计算。\n莫听先生。\n引入深山百丈坑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5762, '减字木兰花', '朱敦儒', '无人请我。\n我自铺毡松下坐。\n酌酒栽诗。\n调弄梅花作侍儿。\n心欢易醉。\n明月飞来花下睡。\n醉舞谁知。\n花满纱巾月满怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5763, '减字木兰花', '朱敦儒', '花随人去。\n今夜钱塘江上雨。\n宿酒残更。\n潮过西窗不肯明。\n小罗金缕。\n结尽同心留不住。\n何处长亭。\n绣被春寒掩翠屏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5764, '减字木兰花', '朱敦儒', '有何不可。\n依旧一枚闲底我。\n饭饱茶香。\n瞌睡之时便上床。\n百般经过。\n且喜青鞋踏不破。\n小院低窗。\n桃李花开春昼长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5765, '减字木兰花', '朱敦儒', '江南春水。\n罗幕黄昏寒未退。\n好个相知。\n唱到娥敛黛眉。\n夜阑人醉。\n风露无情花有泪。\n画角残时。\n一片参旗红杏西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5766, '点绛唇', '朱敦儒', '淮海秋风，冶城飞下扬州叶。\n画船催发。\n倾酒留君别。\n卧倒金壶，相对天涯客。\n阳关彻。\n大江横绝。\n泪湿杯中月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5767, '点绛唇', '朱敦儒', '客梦初回，卧听吴语开帆索。\n护霜云薄。\n澹澹芙蓉落。\n画舫无情，人去天涯角。\n思量著。\n翠蝉金雀。\n别後新梳掠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5768, '点绛唇', '朱敦儒', '至日春云，万般祥瑞朝来奏。\n太平时候。\n乐事家家有。\n玉指呵寒，酥点梅花瘦。\n金杯酒。\n与君为寿。\n只愿人长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5769, '点绛唇', '朱敦儒', '春雨春风，问谁染就江南草。\n燕娇莺巧。\n只是参军老。\n今古红尘，愁了人多少。\n尊前好。\n缓歌低笑。\n醉向花间倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5770, '点绛唇', '朱敦儒', '缘径朱阑，暖烟晴日春来早。\n自家亭沼。\n不问人寻讨。\n携酒提篮，儿女相随到。\n风光好。\n醉纱帽。\n索共梅花笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5771, '柳梢青', '朱敦儒', '狂踪怪迹。\n谁料年老，天涯为客。\n帆展霜风，船随江月，山寒波碧。\n如今著处添愁，怎忍看、参西雁北。\n洛浦莺花，伊川云水，何时归得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5772, '柳梢青', '朱敦儒', '松江胜集。\n中秋载酒，幽人闲客。\n云将迟疑，桂娥羞涩，一欢难得。\n天怜我辈凄凉，借万里、晴空湛碧。\n浩浩烟波，堂堂风月，今夕何夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5773, '柳梢青', '朱敦儒', '红分翠别。\n宿酒半醒，征鞍将发。\n楼外残钟，帐前残烛，窗边残月。\n想伊绣枕无眠，记行客、如今去也。\n心下难拚，眼前难觅，口头难说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5774, '柳梢青', '朱敦儒', '梅蒸乍热。\n无处散策，芳菲初歇。\n席展凉莞，帐垂黄草，天然奇绝。\n披襟永昼清风，更荐枕、良宵皓月。\n一梦游仙，软云推倒，广寒宫阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5775, '柳梢青', '朱敦儒', '秋光正洁。\n仙家瑞草，黄花初发。\n物外高情，天然雅致，清标偏别。\n仙翁笑酌金杯，庆儿女、团圆喜悦。\n嫁与萧郎，凤凰台上，长生风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5776, '柳梢青', '朱敦儒', '水云晚照。\n浮生了了，霜风衰草。\n日月金梭，江山春梦，天多人少。\n赤松认得虚空，便一向、飞腾缥缈。\n直上蓬瀛，回看沧海，凄然长啸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5777, '采桑子', '朱敦儒', '扁舟去作江南客，旅雁孤云。\n万里烟尘。\n回首中原泪满巾。\n碧山对晚汀洲冷，枫叶芦根。\n日落波平。\n愁损辞乡去国人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5778, '采桑子', '朱敦儒', '天高风劲尘寰静，佳节重阳。\n叶下潇湘。\n碧海晴空一陈霜。\n安排弦管倾芳酝，报答秋光。\n昼短歌长。\n红烛黄花夜未央。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5779, '采桑子', '朱敦儒', '一番海角凄凉梦，却到长安。\n翠帐犀帘。\n依旧屏斜十二山。\n玉人为我调琴瑟，颦黛低鬟。\n云散香残。\n风雨蛮溪半夜寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5780, '忆秦娥', '朱敦儒', '西江碧。\n江亭夜燕天涯客。\n天涯客。\n一杯相属，此夕何夕。\n烛残花冷歌声急。\n秦关汉苑无消息。\n无消息。\n戍楼吹角，故人难得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5781, '忆秦娥', '朱敦儒', '霜风急。\n江南路上梅花白。\n梅花白。\n寒溪残月，冷村深雪。\n洛阳醉里曾同摘。\n水西竹外常相忆。\n常相忆。\n宝钗双凤，鬓边春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5782, '忆秦娥', '朱敦儒', '吴船窄。\n吴江岸下长安客。\n长安客。\n惊尘心绪，转蓬踪迹。\n征鸿也是关河隔。\n孤飞万里谁相识。\n谁相识。\n三更月落，斗横西北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5783, '忆秦娥', '朱敦儒', '歌锺列。\n公堂盛会酬佳节。\n酬佳节。\n皇恩宣布，早梅争发。\n舞场椎鼓催回雪。\n金壶镟酒琼酥热。\n琼酥热。\n今朝不饮，几时欢悦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5784, '卜算子', '朱敦儒', '江上见新年，年夜听春雨。\n有个人人领略春，粉澹红轻注。\n深劝玉东西，低唱黄金缕。\n拈底梅花总是愁，酒尽人归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5785, '卜算子', '朱敦儒', '陌上雪销初，才得江梅信。\n翦彩盘金院落香，便觉烧灯近。\n乐事眼前多，春酒今年胜。\n好趁迎梅接柳时，满引金杯饮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5786, '卜算子', '朱敦儒', '碧瓦小红楼，芳草江南岸。\n雨後纱窗几阵寒，零落梨花晚。\n看到水如云，送尽鸦成点。\n南北东西处处愁，独倚阑干遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5787, '卜算子', '朱敦儒', '古涧一枝梅，免被园林锁。\n路远山深不怕寒，似共春相。\n幽思有谁知，托契都难可。\n独自风流独自香，明月来寻我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5788, '卜算子', '朱敦儒', '灼灼一枝桃，粉艳天然好。\n只被春风摆撼多，颜色凋零早。\n结子未为迟，悔恨随芳草。\n不下山来不出溪，待守刘郎老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5789, '卜算子', '朱敦儒', '旅雁向南飞，风雨群初失。\n饥渴辛勤两翅垂，独下寒汀立。\n鸥鹭苦难亲，缴忧相逼。\n云海茫茫无处归，谁听哀鸣急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5790, '卜算子', '朱敦儒', '山晓鹧鸪啼，云暗泷州路。\n榕叶阴浓荔子青，百尺桄榔树。\n尽日不逢人，猛地风吹雨。\n惨黯蛮溪鬼峒寒，隐隐闻铜鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5791, '清平乐', '朱敦儒', '乱红深翠。\n楼阁春风外。\n胡蝶成团飞照水。\n睡鸭无人惊起。\n身闲更觉身轻。\n酒壶歌扇随行。\n芳草绿杨堤畔，一声初听啼莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5792, '清平乐', '朱敦儒', '人间花少。\n菊小芙蓉老。\n冷澹仙人偏得道。\n买定西风一笑。\n前身原是疏梅。\n黄姑点碎冰肌。\n惟有暗香长在，饱参清露霏微。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5793, '清平乐', '朱敦儒', '相留不住。\n又趁东风去。\n楼外夕阳芳草路。\n今夜短亭何处。\n杏花斜压阑干。\n朱帘不卷春寒。\n惆怅黄昏前後，离愁酒病厌厌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5794, '清平乐', '朱敦儒', '多寒易雨。\n春事都相误。\n愁过黄昏无著处。\n宝篆烧残香缕。\n低鬟暗摘明。\n罗巾挹损残妆。\n檐外几声风玉，丁东敲断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5795, '清平乐', '朱敦儒', '春寒雨妥。\n花萼红难破。\n绣线金针慵不作。\n要见秋千无那。\n西邻姊妹丁宁。\n寻芳更约清明。\n画个丙丁帖子，前阶後院求晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5796, '清平乐', '朱敦儒', '当初相见。\n君恨相逢晚。\n一曲秦筝弹未遍。\n无奈昭阳人怨。\n便教恩浅情疏。\n隔花空望金舆。\n春晚不拈红粉，碧窗自录仙书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5797, '昭君怨', '朱敦儒', '胧月黄昏亭榭。\n池上秋千初架。\n燕子说春寒。\n杏花残。\n泪断愁肠难断。\n往事总成幽怨。\n幽怨几时休。\n泪还流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5798, '浣溪沙', '朱敦儒', '折桂归来懒觅官。\n十年风月醉家山。\n有人挟瑟伴清闲。\n楚畹飞香兰结佩，蓝田生暖玉连环。\n拥书万卷看双鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5799, '浣溪沙', '朱敦儒', '西塞山边白鹭飞。\n吴兴江上绿杨低。\n桃花流水鳜鱼肥。\n青箬笠将风里戴，短蓑衣向雨中披。\n斜风细雨不须归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5800, '浣溪沙', '朱敦儒', '银海清泉洗玉杯。\n恰白酒冷偏宜。\n水林檎嫩折青枝。\n争看使君长寿曲，旋教法部太平词。\n快风凉雨火云摧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5801, '浣溪沙', '朱敦儒', '碧玉栏干白玉人。\n倚花吹叶忍黄昏。\n萧郎一去又经春。\n眉澹翠峰愁易聚，脸残红雨泪难匀。\n纤腰减半绿罗裙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5802, '浣溪沙', '朱敦儒', '雨湿清明香火残。\n碧溪桥外燕泥寒。\n日长独自倚阑干。\n脱箨修篁初散绿，褪花新杏未成酸。\n江南春好与谁看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5803, '浣溪沙', '朱敦儒', '风落芙蓉画扇闲。\n凉随春色到人间。\n乍垂罗幕乍飞鸾。\n好把深杯添绿酒，休拈明镜照苍颜。\n浮生难得是清欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5804, '浣溪沙', '朱敦儒', '才子佳人相见难。\n舞收歌罢又更阑。\n密将春恨系幽欢。\n结子同心香佩带，帕儿双字玉连环。\n酒醒灯暗忍重看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5805, '浣溪沙', '朱敦儒', '晚菊花前敛翠蛾。\n采花传酒缓声歌。\n柳枝团扇别离多。\n拥髻凄凉论旧事，曾随织女度银梭。\n当年今夕奈愁何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5806, '阮郎归', '朱敦儒', '柳花陌上拈明。\n娇红新样妆。\n匆匆曾贮一襟香。\n月痕金缕凉。\n分泪扇，掩离觞。\n春残人断肠。\n锦书难寄雁飞忙。\n池塘芳草长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5807, '生查子', '朱敦儒', '卧病独眠人，无月中秋节。\n澹照碧纱灯，冷看银屏雪。\n风露转萧寒，砧杵添凄切。\n伏枕漫书空，到晓愁难说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5808, '眼儿媚', '朱敦儒', '青锦成帏瑞香浓。\n雅称小帘栊。\n主人好事，金杯留客，共倚春风。\n不知因甚来尘世，香似旧曾逢。\n江梅退步，幽兰偷眼，回避芳丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5809, '眼儿媚', '朱敦儒', '叠翠阑红斗纤浓。\n云雨绮为栊。\n只忧谢了，偏须著意，障雨遮风。\n瑞云香雾虽难觅，蓦地有时逢。\n不妨守定，从他人笑，老入花丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5810, '眼儿媚', '朱敦儒', '紫帔红襟艳争浓。\n光彩烁疏栊。\n香为小字，瑞为高姓，道骨仙风。\n此花合向瑶池种，可惜未遭逢。\n阿环见了，羞回眼尾，愁聚眉丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5811, '诉衷情', '朱敦儒', '青垂柳线水平池。\n芳径燕初飞。\n日长事少人静，山茧换单衣。\n箫鼓远，篆香迟。\n卷帘低。\n半床花影，一枕松风，午醉醒时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5812, '诉衷情', '朱敦儒', '老人无复少年欢。\n嫌酒倦吹弹。\n黄昏又是风雨，楼外角声残。\n悲故国，念尘寰。\n事难言。\n下了纸帐，曳上青毡，一任霜寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5813, '诉衷情', '朱敦儒', '青旗彩胜又迎春。\n暖律应祥云。\n金盘内家生菜，宫院遍承恩。\n时节好，管弦新。\n度升平。\n惠风迟日，柳眼梅心，任醉芳尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5814, '诉衷情', '朱敦儒', '月中玉兔日中鸦。\n随我度年华。\n不管寒暄风雨，饱饭热煎茶。\n居士竹，故侯瓜。\n老生涯。\n自然天地，本分云山，到处为家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5815, '菩萨蛮', '朱敦儒', '老人谙尽人间苦。\n近来恰似心头悟。\n九九是重阳。\n重阳菊散芳。\n出门何处去。\n对面谁相语。\n枕臂卧南窗。\n铜炉柏子香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5816, '菩萨蛮', '朱敦儒', '芭蕉叶上秋风碧。\n晚来小雨流苏湿。\n新窨木樨沈。\n香迟斗帐深。\n无人同向夕。\n还是愁成忆。\n忆昔结同心。\n鸳鸯何处寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5817, '菩萨蛮', '朱敦儒', '风流才子倾城色。\n红缨翠长安陌。\n夜饮小平康。\n暖生银字簧。\n持杯留上客。\n私语眉峰侧。\n半冷水沈香。\n罗帷宫漏长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5818, '菩萨蛮', '朱敦儒', '乡关散尽当年客。\n春风寂寞花无色。\n长日掩重门。\n江山眼外昏。\n画图高挂壁。\n嵩少参差碧。\n想见卧云人。\n松黄落洞门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5819, '菩萨蛮', '朱敦儒', '芙蓉红落秋风急。\n夜寒纸帐霜华湿。\n枕畔木瓜香。\n晓来清兴长。\n轻舟青箬笠。\n短棹溪光碧。\n去觅谢三郎。\n芦花何处藏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5820, '双', '朱敦儒', '拂破秋江烟碧。\n一对双飞。\n应是远来无力。\n捎下相偎沙碛。\n小艇谁吹横笛。\n惊起不知消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5821, '鼓笛令', '朱敦儒', '纸帐绸衾忒暖。\n尽自由、横翻倒转。\n睡觉西窗灯一盏。\n恰听打、三更三点。\n残梦不须深念。\n这些个、光阴煞短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5822, '西湖曲・玉楼春', '朱敦儒', '今冬寒早风光好。\n休怪搀先絮帽。\n蟹肥一个可称斤，酒美三杯真合道。\n年年闲梦垂垂了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5823, '风蝶令・南歌子', '朱敦儒', '试看何时有，元来总是空。\n丹砂只在酒杯中。\n看取乃公双颊、照人红。\n花外庄周蝶，松间御寇风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5824, '谒金门', '朱敦儒', '春怎恋。\n楼外绿催红殿。\n短袖迎风愁半卷。\n手寒无处暖。\n目断蓬莱宫殿。\n引去谁怜谁怨。\n相见不如青翅燕。\n举头长安远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5825, '洛妃怨・昭君怨', '朱敦儒', '拾翠当年延伫。\n解佩感君诚素。\n微步过南冈。\n献明。\n襟上泪难再会。\n惆怅幽兰心事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5826, '燕归梁', '朱敦儒', '帐掩秋风一半开。\n闲将玉笛吹。\n过云微雨散轻雷。\n夜参差、认楼台。\n暗香移枕新凉住，竹外漏声催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5827, '相见欢', '朱敦儒', '泷州几番清秋。\n许多愁。\n叹我等闲白了、少年头。\n人间事。\n如何是。\n去来休。\n自是不归归去、有谁留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5828, '相见欢', '朱敦儒', '东风吹尽江梅。\n橘花开。\n旧日吴王宫殿、长青苔。\n今古事。\n英雄泪。\n老相催。\n长恨夕阳西去、晚潮回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5829, '相见欢', '朱敦儒', '金陵城上西楼。\n倚清秋。\n万里夕阳垂地、大江流。\n中原乱。\n簪缨散。\n几时收。\n试倩悲风吹泪、过扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5830, '相见欢', '朱敦儒', '秋风又到人间。\n叶珊珊。\n四望烟波无尽、欠青山。\n浮生事。\n长江水。\n几时闲。\n幸是古来如此、且开颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5831, '相见欢', '朱敦儒', '吟蛩作尽秋声。\n月西沈。\n凄断馀香残梦、下层城。\n人不见。\n屏空掩。\n数残更。\n还自搴帷独坐、看青灯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5832, '相见欢', '朱敦儒', '当年两上蓬瀛。\n燕殊庭。\n曾共群仙携手、斗吹笙。\n云涛晚。\n霓旌散。\n海鸥轻。\n却钓松江烟月、醉还醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5833, '相见欢', '朱敦儒', '深秋庭院初凉。\n近重阳。\n篱畔一枝金菊、露微黄。\n鲈脍韵。\n橙齑品。\n酒新香。\n我是升平闲客、醉何妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5834, '如梦令', '朱敦儒', '一夜新秋风雨。\n客恨客愁无数。\n我是卧云人，悔到红尘深处。\n难住。\n难住。\n拂袖青山归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5835, '如梦令', '朱敦儒', '好个中秋时节。\n莫恨今宵无月。\n岩壑一灯青，寒浸水香留客。\n留客。\n留客。\n相对无言无说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5836, '如梦令', '朱敦儒', '盏底一盘金凤。\n满泛酒光浮动。\n引我上烟霞，智力一时无用。\n无用。\n无用。\n蹋破十洲三洞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5837, '如梦令', '朱敦儒', '真个先生爱睡。\n睡里百般滋味。\n转面又翻身，随意十方游戏。\n游戏。\n游戏。\n到了元无一事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5838, '如梦令', '朱敦儒', '莫恨中秋无月。\n月又不甜不辣。\n幸有瓮头春，闲坐暖云香雪。\n香雪。\n香雪。\n满引水晶蕉叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5839, '如梦令', '朱敦儒', '莫恨中秋无月。\n多点金缸红蜡。\n取酒拥丝簧，迎取轻盈桃叶。\n桃叶。\n桃叶。\n唱我新歌白雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5840, '如梦令', '朱敦儒', '一夜蟠桃吹坼。\n刚道有人偷折。\n幸自没踪由，无奈蝶蜂胡说。\n胡说。\n胡说。\n方朔不须耳热。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5841, '如梦令', '朱敦儒', '好笑山翁年纪。\n不觉七十有四。\n生日近元宵，占早烧灯欢会。\n欢会。\n欢会。\n坐上人人千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5842, '春晓曲', '朱敦儒', '西楼落月鸡声急。\n夜浸疏香寒淅沥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5843, '柳枝・杨柳枝', '朱敦儒', '江南岸。\n江北岸。\n折送行人无尽时。\n恨分离。\n酒一杯。\n泪双垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5844, '念奴娇', '朱敦儒', '别离情绪，奈一番好景，一番悲戚。\n燕语莺啼人乍远，还是他乡寒食。\n桃李无言，不堪攀折，总是风流客。\n东君也自，怪人冷淡踪迹。\n花艳草草春工，酒随花意薄，疏狂何益。\n除却清风并皓月，脉脉此情谁识。\n料得文君，重帘不卷，且等闲消息。\n不如归去，受他真个怜惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5845, '浣溪沙', '孙觌', '弱骨轻肌不耐春。\n一枝江路玉梅新。\n巡檐索笑为何人。\n素影徘徊波上月，醉香摇荡竹间云。\n酒醒人散梦仙村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5846, '浣溪沙', '慕容卿妻', '满目江山忆旧游。\n汀洲花草弄春柔。\n长亭舣住木兰舟。\n好梦易随流水去，芳心空逐晓云愁。\n行人莫上望京楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5847, '水龙吟', '周紫芝', '黄金双阙横空，望中隐约三山眇。\n春皇欲降，渚烟收尽，青虹正绕。\n日到层宵，九枝光满，普天俱照。\n看海中桃熟，云幡绛节，冉冉度、沧波渺。\n遥想建章宫阙，□熏风、月寒清晓。\n红鸾影上，云韶声里，蒙天一笑。\n万国朝元，百蛮款塞，太平多少。\n听尧云深处，人人尽祝，似天难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5848, '水龙吟', '周紫芝', '楚山千叠浮空，楚云只在巫山往。\n鸾飞凤舞，当时空记，梦中奇语。\n晓日瞳，夕阳零乱，袅红萦素。\n问如今依旧，霏霏冉冉，知他为、谁朝暮。\n玉佩烟鬟飞动，炯星眸、人间相遇。\n嫣然一笑，阳城下蔡，尽成惊顾。\n蕙帐春浓，兰衾日暖，未成行雨。\n但丁宁莫似，阳台梦断，又随风去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5849, '水龙吟', '周紫芝', '楚山木落风高，暮云黯黯孤容瘦。\n天晴似洗，明霞消尽，玉峦排秀。\n九凤飞来，五云深处，一时轻矫。\n恨三山不见，六鳌去後，天空远，人将老。\n堪笑此生如寄，信扁舟、来江表。\n望中愁眼，依稀犹认，数峰林杪。\n万里东南，跨江云梦，此情多少。\n问何时还我，千岩万壑，卧霜天晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5850, '浣溪沙', '周紫芝', '近腊风光一半休。\n南枝未动北枝愁。\n嫦娥莫是见人羞。\n么凤不传蓬岛信，杜鹃空办鹤林秋。\n便须千杖打梁州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5851, '浣溪沙', '周紫芝', '欲醉江梅兴未休。\n待春瓮洗春愁。\n不成欢绪却成羞。\n天意若教花似雪，客情宁恨鬓如秋。\n趁他何逊在扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5852, '浣溪沙', '周紫芝', '无限春情不肯休。\n江梅未动使人愁。\n东昏觑得玉奴羞。\n对酒情怀疑是梦，忆花天气黯如秋。\n唤春云梦泽南州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5853, '浣溪沙', '周紫芝', '水上鸣榔不系船。\n醉来深闭短篷眠。\n潮生潮落自年年。\n一尺鲈鱼新活计，半蓑烟雨旧衣冠。\n庙堂空有画图看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5854, '浣溪沙', '周紫芝', '多病嫌秋怕上楼。\n苦无情绪懒抬头。\n雁来不寄小银钩。\n一点离情深似海，万重凄恨黯如秋。\n怎生禁得许多愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5855, '浣溪沙', '周紫芝', '新翻碧玉壶。\n水精钗袅绛纱符。\n吴姬亲手碎菖蒲。\n彩索系时新睡起，榴花剪处要人扶。\n心情还似去年无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5856, '浣溪沙', '周紫芝', '学画双蛾苦未成。\n鬓云新结翠鬟轻。\n伴人歌笑已多情。\n飞絮乱花闲院宇，舞鸾歌凤小娉婷。\n阳关休唱断肠声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5857, '卜算子', '周紫芝', '江北上归舟，再见江南岸。\n江北江南几度秋，梦里朱颜换。\n人是岭头云，聚散天谁管。\n君似孤云何处归，我似离群雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5858, '卜算子', '周紫芝', '霜叶下孤篷，船在垂杨岸。\n早是凄凉惜别时，更惜年华换。\n别酒解留人，拚醉君休管。\n醉里朱弦莫谩弹，愁入参差雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5859, '卜算子', '周紫芝', '絮尽柳成空，春去花如扫。\n窗外枝枝海石榴，特为幽人好。\n密叶过疏篱，薄艳明芳草。\n剪得花时却倚阑，楼上人垂手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5860, '木兰花・玉楼春', '周紫芝', '嫦娥天上人谁识。\n家在蓬山烟水隔。\n不应著意眼前人，便是登瀛当日客。\n双眸炯炯秋波滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5861, '木兰花・玉楼春', '周紫芝', '江头雨後山如髻。\n催送新凉风有意。\n月来杨柳绿阴中，秋在梧桐疏影外。\n小窗纹簟凉如水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5862, '减字木兰花', '周紫芝', '春闲昼永。\n城下江深山倒影。\n净扫风埃。\n收拾烟光入句来。\n短窗闲倚。\n身似浮云门似水。\n谁伴馀年。\n结得青山一个缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5863, '减字木兰花', '周紫芝', '蓬莱三岛。\n上有青青千岁草。\n玉佩烟鬟。\n来作人间一笑欢。\n麻姑行酒。\n萼绿华歌清韵袅。\n玉秀兰芳。\n醉舞东风彩袖长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5864, '减字木兰花', '周紫芝', '西山岩桂。\n常恨香闻烟雨外。\n何似君家。\n戏彩堂前早试花。\n黄金千粟。\n风撼芳条香馥馥。\n一剪无多。\n桃李漫山奈俗何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5865, '减字木兰花', '周紫芝', '当年文伯。\n曾是东坡门下客。\n文采风流。\n奕叶传芳总未休。\n为公持酒。\n愿祝彩衣无限寿。\n归觐枫宸。\n剩醉长安几度春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5866, '摊破浣溪沙・山花子', '周紫芝', '苍璧新敲小凤团。\n赤泥开印煮清泉。\n醉捧纤纤双玉笋，鹧鸪斑。\n雪浪溅翻金缕袖，松风吹醒玉酡颜。\n更待微甘回齿颊，且留连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5867, '减字木兰花', '周紫芝', '门外青骢月下嘶。\n映阶笼烛画帘垂。\n一曲阳关声欲尽，不多时。\n凤饼未残云脚乳，水沈催注玉花瓷。\n忍看捧瓯春笋露，翠鬟低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5868, '水调歌头', '周紫芝', '白发三千丈，双鬓不胜垂。\n人间忧喜如梦，老矣更何之。\n蘧玉行年过了，未必如今俱是，五十九年非。\n拟把彭殇梦，分付与痴儿。\n君莫羡，客起舞，寿琼卮。\n此生但愿，长遣猿鹤共追随。\n金印借令如斗，富贵那能长久，不饮竟何为。\n莫问蓬莱路，从古少人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5869, '水调歌头', '周紫芝', '濯锦桥边月，几度照中秋。\n年年此夜清景，伴我与君游。\n万里相随何处，看尽吴波越嶂，更向古徐州。\n应为霜髯老，西望倚黄楼。\n天如水，云似扫，素魂流。\n不知今夕何夕，相对语羁愁。\n故国归来何事，记易南枝惊鹊，还对玉蟾羞。\n踏尽疏桐影，更复为君留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5870, '水调歌头', '周紫芝', '岁晚念行役，江阔渺风烟。\n六朝文物何在，回首更凄然。\n倚尽危楼杰观，暗想琼枝璧月，罗袜步承莲。\n桃叶山前鹭，无语下寒滩。\n潮寂寞，浸孤垒，涨平川。\n莫愁艇子何处，烟树杳无边。\n王谢堂前双燕，空绕乌衣门巷，斜日草连天。\n只有台城月，千古照婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5871, '水调歌头', '周紫芝', '落日在烟树，云水两空。\n澹霞消尽，何事依约有微红。\n湖上晚来风细，吹尽一天残雨，苍翠湿千峰。\n谁遣长空月，冷浸玉壶中。\n问明月，应解笑，白头翁。\n不堪老去，依旧临水照衰容。\n良夜几横烟棹，独倚危墙西望，目断远山重。\n但恨故人远，此乐与谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5872, '沙塞子', '周紫芝', '秋云微淡月微羞。\n云黯黯、月彩难留。\n只应是、嫦娥心里，也似人愁。\n几时回步玉移钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5873, '沙塞子', '周紫芝', '玉溪秋月浸寒波。\n忍持酒、重听骊歌。\n不堪对、绿阴飞阁，月下羞蛾。\n夜深惊鹊转南柯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5874, '鹧鸪天', '周紫芝', '荷气吹凉到枕边。\n薄纱如雾亦如烟。\n清泉浴後花垂雨，白酒倾时玉满船。\n钗欲溜，髻微偏。\n却寻霜粉扑香绵。\n冰肌近著浑无暑，小扇频摇最可怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5875, '鹧鸪天', '周紫芝', '乌鹊桥边河汉流。\n洗车微雨湿清秋。\n相逢不似长相忆，一度相逢一度愁。\n云却静，月垂钩。\n金针穿得喜回头。\n只应人倚阑干处，便似天孙梳洗楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5876, '鹧鸪天', '周紫芝', '尊酒年年乐事多。\n古铜犹得几摩挲。\n他时人物君须记，玉笋班中李泰和。\n烦翠袖，把金荷。\n功名馀事且高歌。\n新来学得长生诀，写就黄庭不换鹅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5877, '鹧鸪天', '周紫芝', '名在休文季孟间。\n一时风味更萧然。\n琼林不逐春风老，安用丹砂巧驻颜。\n春入户，酒吹澜。\n小桃枝上锦阑斑。\n明年欲与君为寿，无路相从入道山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5878, '鹧鸪天', '周紫芝', '袅袅云梳晓髻堆。\n涓涓秋净眼波回。\n旧家十二峰前住，偶为襄王下楚台。\n闲院静，小桃开。\n刘郎前度几回来。\n东风易行云散，花里传觞莫谩催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5879, '鹧鸪天', '周紫芝', '晴日烘帘暖似春。\n菊回霜晕浅仍深。\n谁知此地栽花手，便是当时嗅蕊人。\n秋渺渺，夜沈沈。\n一声清唱袅残音。\n娇痴应挽香罗比，六幅双裙染郁金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5880, '鹧鸪天', '周紫芝', '一点残红欲尽时。\n乍凉秋气满屏帏。\n梧桐叶上三更雨，叶叶声声是别离。\n调宝瑟，拨金猊。\n那时同唱鹧鸪词。\n如今风雨西楼夜，不听清歌也泪垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5881, '鹧鸪天', '周紫芝', '年少登高意气多。\n黄花压帽醉嵯峨。\n如今满眼看华发，强拈茱萸奈老何。\n千垒岫，万重波。\n一时分付与秦娥。\n明年身健君休问，且对秋风卷翠螺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5882, '鹧鸪天', '周紫芝', '终日看山不厌山。\n寻思百计不如闲。\n何时得到重阳日，醉把茱萸仔细看。\n醉帽，倚雕阑。\n偶然携酒却成欢。\n篱边黄菊关心事，触误愁人到酒边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5883, '鹧鸪天', '周紫芝', '读尽牙签玉轴书。\n不知门外有园蔬。\n借令未解銮坡去，也合雠书在石渠。\n微雨後，小寒初。\n满斟长寿碧琳腴。\n不须更问荆州路，便上追锋御府车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5884, '鹧鸪天', '周紫芝', '楼上缃桃一萼红。\n别来开谢几东风。\n武陵春尽无人处，犹有刘郎去後踪。\n香阁小，翠帘重。\n今宵何事偶相逢。\n行云又被风吹散，见了依前是梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5885, '鹧鸪天', '周紫芝', '彩双飞雪浪翻。\n楚歌声转绿杨湾。\n一川红旆初衔日，两岸朱楼不下帘。\n阑倚处，玉垂纤。\n白团扇底藕丝衫。\n未成密约回秋水，看得羞时隔画檐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5886, '鹧鸪天', '周紫芝', '花褪残红绿满枝。\n嫩寒犹透薄罗衣。\n池塘雨细双鸳睡，杨柳风轻小燕飞。\n人别後，酒醒时。\n午窗残梦子规啼。\n尊前心事人谁问，花底闲愁春又归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5887, '采桑子', '周紫芝', '跳珠雨罢风初静，阑槛凭虚。\n绛阙清都。\n只在仙人碧玉壶。\n九原唤起王摩诘，画作新图。\n十城芙蕖。\n乞与知章老鉴湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5888, '西江月', '周紫芝', '画幕灯前细雨，垂莲盏里清歌。\n玉纤持板隔香罗。\n不放行云飞过。\n今夜尘生洛浦，明朝雨在巫山。\n羞蛾且莫斗弯环。\n不似司空见惯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5889, '西江月', '周紫芝', '池面风翻弱絮，树头雨退嫣红。\n扑花蝴蝶杳无踪。\n又做一场春梦。\n便是一成去了，不成没个来时。\n眼前无处说相思。\n要说除非梦里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5890, '西江月', '周紫芝', '罗袖云轻雾薄，醉肌玉软花柔。\n相逢不道有春愁。\n只道春来微瘦。\n一点人间深意，数声柳下轻讴。\n带将离恨上归舟。\n肠断月斜时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5891, '西江月', '周紫芝', '发白犹旅枕，溪深未挂烟莎。\n往来苕意如何。\n应有轻鸥笑我。\n细算年来活计，只消一个渔舟。\n金鱼无分不须求。\n只乞鲈鱼换酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5892, '西江月', '周紫芝', '连理枝头并蒂，同心带上双垂。\n背灯偷赠语低低。\n一点浓情先寄。\n翡翠钗头摘处，鸳鸯枕上醒时。\n酸甜红颗阿谁知。\n别是人间滋味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5893, '西江月', '周紫芝', '天意未教秋老，花容地宜霜。\n酒肌红软玉肌香。\n不与梨花同样。\n来伴孙郎小宴，临风为舞霓裳。\n更深绿水照红妆。\n便是采莲船上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5894, '西江月', '周紫芝', '谁把蓝揉翡翠，天将蜡做梅花。\n晚来秋水映残霞。\n水墨新描图画。\n纸上写将心去，眼边送却愁来。\n今回相见比前回。\n心下忡忡越。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5895, '小重山', '周紫芝', '溪上晴山簇翠螺。\n晓来霜叶醉，小池荷。\n琐窗秋意苦无多。\n帘绣卷，黄菊两三窠。\n小睡拥香罗。\n起来匀醉粉，玉垂梭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5896, '小重山', '周紫芝', '碧玉山围十里湖。\n水云天共远，戏双凫。\n河阳花县锦屏铺。\n人不老，长日在蓬壶。\n一笑且踟蹰。\n会骑箕尾去，上云衢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5897, '汉宫春', '周紫芝', '秋意还深，渐银床露冷，梧叶风高。\n婵娟也应为我，羞照霜毛。\n流年老尽，漫银蟾、冷浸香醪。\n除尽把，平生怨感，一时分付离骚。\n伤心故人千里，问阴晴何处，还记今宵。\n楼高共谁同看，玉桂烟梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5898, '汉宫春', '周紫芝', '香满箱奁，看沈犀弄水，浓麝含薰。\n荀郎一时旧事，尽属王孙。\n残膏剩馥，须倾囊、乞与兰荪。\n金兽暖，云窗雾阁，为人洗尽馀醺。\n依稀雪梅风味，似孤山尽处，马上烟村。\n从来甲煎浅俗，那忍重闻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5899, '醉落魄・一斛珠', '周紫芝', '江天云薄。\n江头雪似杨花落。\n寒灯不管人离索。\n照得人来，真个睡不著。\n归期已负梅花约。\n又还春动空飘泊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5900, '醉落魄・一斛珠', '周紫芝', '柳边池阁。\n晚来卷地东风恶。\n人生不解频行乐。\n昨日花开，今日风吹落。\n杨花却似人飘泊。\n春云更似人情薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5901, '醉落魄・一斛珠', '周紫芝', '薰风池阁。\n小红桥下荷花薄。\n沙平水浅山如削。\n水上鸳鸯，何处风吹落。\n今朝端午新梳掠。\n锦丝围腕花柔弱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5902, '醉落魄・一斛珠', '周紫芝', '云深海阔。\n天风吹上黄金阙。\n酒醒不记归时节。\n三十年来，往事无人说。\n浮生正似风中雪。\n丹砂岂是神仙诀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5903, '阮郎归', '周紫芝', '酴花谢日迟迟。\n杨花无数飞。\n章台侧畔尽风吹。\n飘零无定期。\n烟漠漠，草萋萋。\n江南春尽时。\n可怜踪迹尚东西。\n故园何日归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5904, '阮郎归', '周紫芝', '月棂疏影照婵娟。\n闲临小玉盘。\n枣花金钏出纤纤。\n棋声敲夜寒。\n飞雹冷，水精圆。\n夜深人未眠。\n笑催炉兽暖衾鸳。\n莫教银漏残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5905, '阮郎归', '周紫芝', '西湖山下水潺潺。\n满山风雨寒。\n枝头红日晓斓斑。\n越梅催晓丹。\n连翠叶，拥金盘。\n玉池生乳泉。\n此生三度试甘酸。\n欲归归尚难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5906, '青玉案', '周紫芝', '青鞋忍踏江沙路。\n恨人已、骑鲸去。\n笔底骅骝谁与度。\n西州重到，可怜不见，华屋生存处。\n秋江渺渺高台暮。\n满壁栖鸦醉时句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5907, '青玉案', '周紫芝', '梅花落尽人谁管。\n暗凄断、伤春眼。\n雪後平芜春尚浅。\n一簪华发，满襟离恨，羞作东风伴。\n斗花小斛兰芽短。\n犹是当时旧庭院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5908, '菩萨蛮', '周紫芝', '翠蛾懒画妆痕浅。\n香肌得酒花柔软。\n粉汗湿吴绫。\n玉钗敲枕。\n鬓丝云卸腻。\n罗带还重系。\n含笑出房栊。\n羞随脸上红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5909, '菩萨蛮', '周紫芝', '风头不定云来去。\n天教月到湖心住。\n遥夜一襟愁。\n水风浑似秋。\n藕花迎露笑。\n暗水飞萤照。\n渔笛莫频吹。\n客愁人不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5910, '菩萨蛮', '周紫芝', '宝薰拂拂浓如雾。\n暗惊梅蕊风前度。\n依约似江村。\n馀香马上闻。\n画桥风雨暮。\n零落知无数。\n收拾小窗春。\n金炉檀炷深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5911, '西地锦', '周紫芝', '雨细欲收还滴。\n满一庭秋色。\n阑干独倚，无人共说，这些愁寂。\n手把玉郎书迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5912, '谒金门', '周紫芝', '春雨细。\n开尽一番桃李。\n柳暗曲阑花满地。\n日高人睡起。\n绿浸小池春水。\n沙暖鸳鸯双戏。\n薄幸更无书一纸。\n画楼愁独倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5913, '生查子', '周紫芝', '春寒入翠帷，月淡云来去。\n院落半晴天，风撼梨花树。\n人醉掩金铺，闲倚秋千柱。\n满眼是相思，无说相思处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5914, '生查子', '周紫芝', '青丝结晓鬟，临镜心情懒。\n知为晓愁浓，画得双蛾浅。\n柳困玉楼空，花落红窗暖。\n相对语春愁，只有春闺燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5915, '生查子', '周紫芝', '新欢君未成，往事无人记。\n行雨共行云，如梦还如醉。\n相见又难言，欲住浑无计。\n眉翠莫频低，我已无多泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5916, '生查子', '周紫芝', '清歌忆去年，共唱秦楼曲。\n门外月横波，帐里人如玉。\n秋风吹彩云，梦断惊难续。\n别调不堪闻，红泪销残烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5917, '生查子', '周紫芝', '金鞍欲别时，芳草溪边渡。\n不忍上西楼，怕看来时路。\n帘幕卷东风，燕子双双语。\n薄幸不归来，冷落春情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5918, '生查子', '周紫芝', '轻云浅护霜，晓日红生砌。\n烟共宝薰浓，人与山长翠。\n银浪酒杯浓，锦幄双鸾戏。\n庭下彩衣郎，共祝千千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5919, '昭君怨', '周紫芝', '满院融融花气。\n红绣一帘垂地。\n往事忆年时。\n只春知。\n风又暖。\n花渐满。\n人似行云不见。\n无计奈离情。\n恶销凝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5920, '秦楼月・忆秦娥', '周紫芝', '东风歇。\n香尘满院花如雪。\n花如雪。\n看看又是，黄昏时节。\n无言独自添香鸭。\n相思情绪无人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5921, '天仙子', '周紫芝', '雪似杨花飞不定。\n枝上冻禽昏欲暝。\n寒窗相对话分飞，箫鼓静。\n灯炯炯。\n一曲阳关和泪听。\n酒入离肠愁欲凝。\n往事不堪重记省。\n劝君莫上玉楼梯，风力劲。\n山色暝。\n忍看去时楼下径。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5922, '渔家傲', '周紫芝', '遇坎乘流随分了。\n鸡虫得失能多少。\n儿辈雌黄堪一笑。\n堪一笑。\n鹤长凫短从他道。\n几度秋风吹梦到。\n花姑溪上人空老。\n唤取扁舟归去好。\n归去好。\n孤篷一枕秋江晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5923, '渔家傲', '周紫芝', '月黑波翻江浩渺。\n扁舟系缆垂杨杪。\n渔网横江灯火闹。\n红影照。\n分明赤壁回惊棹。\n风静云收天似扫。\n梦疑身在三山岛。\n浮世功名何日了。\n从醉倒。\n柁楼红日千岩晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5924, '渔家傲', '周紫芝', '休惜骑鲸人已远。\n风流都被仍云占。\n腰下锦绦缠宝剑。\n光闪焰。\n人间莫作牛刀看。\n见说河阳花满县。\n相邀更约疏狂伴。\n幸有小蛮开小燕。\n须少款。\n玉堂此去知非晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5925, '渔家傲', '周紫芝', '路入云岩山窈窕。\n岩花滴露花头小。\n香共西风吹得到。\n秋欲杪。\n天还未放秋容老。\n谁道水南花不好。\n犹胜金蕊浑如扫。\n留取光阴重一笑。\n须是早。\n黄花更惜重阳帽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5926, '渔家傲', '周紫芝', '月黑天寒花欲睡。\n移灯影落清尊里。\n唤醒妖红明晚翠。\n如有意。\n嫣然一笑知谁会。\n露湿柔柯红压地。\n羞容似替人垂泪。\n著意西风吹不起。\n空绕砌。\n明年花共谁同醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5927, '南柯子・南歌子', '周紫芝', '蝉薄轻梳鬓，螺香浅画眉。\n西湖人道似西施。\n人似西施浓淡、更相宜。\n画烛催歌板，飞花上舞衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5928, '南柯子・南歌子', '周紫芝', '雾帐兰衾暖，薰炉宝篆浓。\n眼波犹带睡朦胧。\n卧听晓来双燕、语春风。\n螺浅欢馀黛，霞销枕处红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5929, '南柯子・南歌子', '周紫芝', '白羽传觞急，金鞍跃马迟。\n云间彩凤看双飞。\n飞上碧梧枝上、稳双栖。\n林下风流女，堂东坦腹儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5930, '朝中措', '周紫芝', '西湖烟尽水溶溶。\n一笑与谁同。\n多谢湖边霜菊，伴人三见秋风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5931, '朝中措', '周紫芝', '大江流处是庐峰。\n苍玉照晴空。\n何事浅鬟浓黛，却成烟雨溟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5932, '朝中措', '周紫芝', '雨馀庭院冷萧萧。\n帘幕度微飙。\n鸟语唤回残梦，春寒勒住花梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5933, '朝中措', '周紫芝', '小桃花动著枝浓。\n移得伴衰翁。\n多谢天公怜我，一时染就轻红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5934, '朝中措', '周紫芝', '黄昏楼阁乱栖鸦。\n天末淡微霞。\n风里一池杨柳，月边满树梨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5935, '虞美人', '周紫芝', '短墙梅粉香初透。\n削约寒枝瘦。\n恼人知为阿谁开。\n还伴冷烟疏雨、做愁媒。\n飘零苦恨春情薄。\n不管花开落。\n小池疏影弄寒沙。\n何似玉台鸾镜、对横斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5936, '虞美人', '周紫芝', '西园摘处香和露。\n洗尽南轩暑。\n莫嫌坐上适来蝇。\n只恐怕寒、难近玉壶冰。\n井花浮翠金盆小。\n午梦初回後。\n诗翁自是不归来。\n不是青门、无地可移栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5937, '虞美人', '周紫芝', '痴云压地风尘卷。\n雪共春寒浅。\n山城寒夜不烧灯。\n时见竹篱茅舍、两三星。\n九衢风里香尘拥。\n十载鳌山梦。\n如今独自倚冰檐。\n落尽短檠红、不成眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5938, '江城子', '周紫芝', '夕阳低尽柳如烟。\n淡平川。\n断肠天。\n今夜十分，霜月更娟娟。\n怎得人如天上月，虽暂缺，有时圆。\n断云飞雨又经年。\n思凄然。\n泪涓涓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5939, '江城子', '周紫芝', '碧梧和露滴清秋。\n小庭幽。\n翠烟流。\n羞带一襟，明月上危楼。\n苦恨秋江风与月，偏管断，这些愁。\n此情空道两绸缪。\n信悠悠。\n几时休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5940, '潇湘夜雨・满庭芳', '周紫芝', '楼上寒深，江边雪满，楚台烟霭空。\n一天飞絮，零乱点孤篷。\n似我华颠雪领，浑无定、漂泊孤踪。\n空凄黯，江天又晚，风袖倚蒙茸。\n吾庐，犹记得，波横素练，玉做寒峰。\n更短坡烟竹，声碎玲珑。\n拟问山阴旧路，家何在、水远山重。\n渔蓑冷，扁舟梦断，灯暗小窗中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5941, '潇湘夜雨・满庭芳', '周紫芝', '晓色凝暾，霜痕犹浅，九天春意将回。\n隔年花信，先已到江梅。\n沈水烟浓如雾，金波满、红袖双垂。\n仙翁醉，问春何处，春在玉东西。\n瑶台。\n人不老，还从东壁，来步天墀。\n且细看八砖，花影迟迟。\n会见朱颜绿鬓，家长近、咫尺天威。\n君知否，天教雨露，常满岁寒枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5942, '潇湘夜雨・满庭芳', '周紫芝', '江绕淮城，云昏楚观，一枝烟笛谁横。\n晓风吹帽，霜日照人明。\n暗恼潘郎旧恨，应追念、菊老残英。\n秋空晚，茱萸细拈，为谁倾。\n人间，真梦境，新愁未了，绿鬓星星。\n问明年此会，谁寄幽情。\n倚尽一楼残照，何妨更、月到帘旌。\n凭阑久，歌君妙曲，谁是米嘉荣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5943, '潇湘夜雨・满庭芳', '周紫芝', '楚尾江横，斗南山秀，辋川谁画新图。\n几时天际，平地出方壶。\n应念江南倦客，家何在、飘泊江湖。\n天教共，银涛翠壁，相伴老人娱。\n长淮，看不尽，风帆落处，天在平芜。\n算人间此地，岂是穷途。\n好与婆娑尽日，应须待、月到金枢。\n山中饮，从教笑我，白首醉模糊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5944, '宴桃源・如梦令', '周紫芝', '帘幕疏疏风透。\n庭下月寒花瘦。\n宽尽沈郎衣，方寸不禁。\n难受。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5945, '宴桃源・如梦令', '周紫芝', '林外野塘烟腻。\n衣上落梅香细。\n瘦马步凌兢，人在乱山丛里。\n憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5946, '宴桃源・如梦令', '周紫芝', '绿尽小池芳草。\n门外柳垂春昼。\n花上雨廉纤，帘幕燕来时候。\n消瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5947, '宴桃源・如梦令', '周紫芝', '旧日荼シ时候。\n酒粉香襟袖。\n老去惜春心，试问孙郎知否。\n花瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5948, '满江红', '周紫芝', '寂寂江天，雪又满、晚来风急。\n空懊恨、散盐飞絮，未成轻集。\n万里长空飞不到，珠帘卷尽还羞入。\n问向晚、谁欲画渔莎，寒江立。\n天黯淡，催残日。\n波浩渺，添寒力。\n又何如聊遣，舞衣红湿。\n好与月娥临晚砌，莫教先放梅花拆。\n便准拟、一醉广寒宫，千山白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5949, '定风波令・定风波', '周紫芝', '梅粉梢头雨未乾。\n淡烟疏日带春寒。\n暝鸦啼处，人在小楼边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5950, '蝶恋花', '周紫芝', '天意才晴风又雨。\n催得风前，日日吹轻絮。\n燕子不飞莺不语。\n满庭芳草空无数。\n春去可堪人去也。\n枝上残红，不忍抬头觑。\n假使留春春肯住。\n唤谁相伴春同处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5951, '永遇乐', '周紫芝', '槐幄如云，燕泥犹湿，雨馀清暑。\n细草摇风，小荷擎雨，时节还端午。\n碧罗窗底，依稀记得，闲系翠丝烟缕。\n到如今、前欢如梦，还对彩绦无语。\n榴花半吐，金刀犹在，往事更堪重数。\n艾虎钗头，菖蒲酒里，旧约浑无据。\n轻衫如雾，玉肌似削，人在画楼深处。\n想灵符、无人共带，翠眉暗聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5952, '蓦山溪', '周紫芝', '月眉星眼，阆苑真仙侣。\n娇小正笄年，每当筵、愁歌怕舞。\n水亭烟树，春去已无踪，桃源路。\n知何处。\n往事如风絮。\n如今闻道，误剪香云缕，闲系小乌纱，更无心、浅匀深注。\n三山路杳，终不是人间，知谁与。\n吹箫女。\n共驾青鸾去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5953, '品令', '周紫芝', '西风持酒。\n诮不做、愁时候。\n机云兄弟，坐中玉树，琼枝高秀。\n且莫劝人归去，坐来未久。\n甘泉书奏。\n报幽障、沈烽後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5954, '品令', '周紫芝', '霜蓬零乱。\n笑绿鬓、光阴晚。\n紫茱时节，小楼长醉，一川平远。\n休说龙山佳会，此情不浅。\n黄花香满。\n记白苎、吴歌软。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5955, '清平乐', '周紫芝', '芦州晚净。\n雨罢江如镜。\n属玉双飞栖不定。\n数点晚来烟艇。\n梦回满眼凄凉。\n一成无奈思量。\n舟在绿杨堤下，蝉嘶欲尽斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5956, '清平乐', '周紫芝', '烟鬟敛翠。\n柳下门初闭。\n门外一川风细细。\n沙上暝禽飞起。\n今宵水畔楼边。\n风光宛似当年。\n月到旧时明处，共谁同倚阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5957, '清平乐', '周紫芝', '青春欲暮。\n柳下将飞絮。\n月到阶前梅子树。\n啼得杜鹃飞去。\n人归不掩朱门。\n一成过了黄昏。\n只有琐窗红蜡，照人犹自销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5958, '清平乐', '周紫芝', '团栾小树。\n天与香无数。\n薄艳不尽风日苦。\n剩著红油遮护。\n移栽未到江南。\n香山鼻观先参。\n勾引老情偏醉，锦薰笼暖春酣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5959, '清平乐', '周紫芝', '浅妆匀靓。\n一点闲心性。\n脸上羞红凝不定。\n恼乱酒愁花病。\n晚来泪残霞。\n坠鬟小玉钗斜。\n细雨一帘春恨，东风满地桃花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5960, '清平乐', '周紫芝', '东风庭户。\n红满桃花树。\n准拟踏青南陌路。\n双凤绣鞋新做。\n秋千月挂黄昏。\n画堂深掩朱门。\n立尽花阴归去，此时别是销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5961, '浪淘沙', '周紫芝', '江上送年归。\n还似年时。\n屠苏休恨到君迟。\n觅得醉乡无事处，莫放愁知。\n红一灯垂。\n应笑人衰。\n鹤长凫短怨他谁。\n明日江楼春到也，且醉南枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5962, '浪淘沙', '周紫芝', '落日在阑干。\n风满晴川。\n坐来高浪拥银山。\n白鹭欲栖飞不下，却入苍烟。\n千里水云寒。\n正绕烟鬟。\n拍浮须要酒杯宽。\n天与吾曹供一醉，不是人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5963, '踏莎行', '周紫芝', '风翠轻翻，雾红深注。\n鸳鸯池畔双鱼树。\n合欢凤子也多情，飞来连理枝头住。\n欲付浓愁，深凭尺素。\n戏鱼波上无寻处。\n教谁试与问花看，如何寄得香笺去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5964, '踏莎行', '周紫芝', '燕子归来，梅花又落。\n缃桃雨後燕支薄。\n眼前先自许多愁，斜阳更在春池阁。\n梦里新欢，年时旧约。\n日长院静空帘幕。\n几回猛待不思量，抬头又是思量著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5965, '踏莎行', '周紫芝', '鹊报寒枝，鱼传尺素。\n晴香暗与风微度。\n故人还寄陇头梅，凭谁为作梅花赋。\n柳外朱桥，竹边深坞。\n何时却向君家去。\n便须倩月与徘徊，无人留得花常住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5966, '踏莎行', '周紫芝', '情似游丝，人如飞絮。\n泪珠阁定空相觑。\n一溪烟柳万丝垂，无因系得兰舟住。\n雁过斜阳，草迷烟渚。\n如今已是愁无数。\n明朝且做莫思量，如何过得今宵去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5967, '雨中花令', '周紫芝', '山雨细、泉生幽谷，水满平田。\n雪茧红蚕熟後，黄云陇麦秋间。\n武陵烟暖，数声鸡犬，别是山川。\n嗟老去、倦游踪迹，长恨华颠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5968, '点绛唇', '周紫芝', '燕子风高，小桃枝上花无数。\n乱溪深处。\n满地飞红雨。\n唤得春来，又送春归去。\n浑无绪。\n刘郎前度。\n空记来时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5969, '点绛唇', '周紫芝', '人道长生，算来世上何曾有。\n玉尊长倒。\n早是人间少。\n四十年来，历尽闲烦恼。\n如今老。\n大家开口。\n赢得花前笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5970, '临江仙', '周紫芝', '水远山长何处去，欲行人似孤云。\n十分瘦损沈休文。\n忍将秋水镜，容易与君分。\n试问梨花枝上雨，为谁弹满清尊。\n一江风月黯离魂。\n平波催短棹，小立送黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5971, '临江仙', '周紫芝', '记得武陵相见日，六年往事堪惊。\n回头双鬓已星星。\n谁知江上酒，还与故人倾。\n铁马红旗寒日暮，使君犹寄边城。\n只愁飞诏下青冥。\n不应霜塞晚，横槊看诗成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5972, '好事近', '周紫芝', '江路绕青山，山翠扑衣轻湿。\n谁酿晚来云意，做一天愁色。\n竹溪斜度尽篮舆，疏梅暗香入。\n何处最关心事，恨落梅风急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5973, '好事近', '周紫芝', '香蜡染宫黄，不属世间风月。\n分我照寒金蕊，伴小窗愁绝。\n高标独步本无双，一枝为谁折。\n压尽半春桃李，任满山如雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5974, '好事近', '周紫芝', '帘外一声歌，倾尽满城风月。\n看到酒阑羞处，想多情难说。\n周郎元是个中人，如今鬓如雪。\n自恨老来肠肚，诮不堪摧折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5975, '好事近', '周紫芝', '雨後欲斜阳，红满井梧风叶。\n还是夜来时候，共小轩明月。\n不关纤手与调冰，消除这些热。\n自是月娥肌骨，似玉壶香雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5976, '好事近', '周紫芝', '春似酒杯浓，醉得海棠无力。\n谁染玉肌丰脸，做燕支颜色。\n送春风雨最无情，吹残也堪惜。\n何似且留花住，唤小鬟催拍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5977, '好事近', '周紫芝', '秋意总关愁，那更与君轻别。\n从此共谁同醉，恨老来风月。\n遥知手板笑看云，江边醉时节，应为老人回首，记白头如雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5978, '酹江月・念奴娇', '周紫芝', '冰轮飞上，正金波翻动，玉壶新绿。\n风帽还猗清露滴，凛凛微生寒粟。\n白玉楼高，水精帘卷，十里堆琼屋。\n千山人静，怒龙声喷蕲竹。\n夜久斗落天高，银河还对泻，冷悬双瀑。\n此地人间何处有，难买明珠千斛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5979, '酹江月・念奴娇', '周紫芝', '楚山无尽，看西来新拥，石城双旆。\n立马花边金镫暖，遥想元戎小队。\n白雪歌成，莫愁去後，往事空千载。\n一时吟啸，风流不减前辈。\n闻道梦泽南州，日高初睡足，雅宜高会。\n老去愁多谁念我，空对云山苍翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5980, '感皇恩', '周紫芝', '残月挂征鞍，路长山绕。\n独拥寒貂犯霜晓。\n水边林下，孤负此生多少。\n星星空满鬓，因谁有。\n不如办个，短蓑长钓。\n唤取轻鸥伴人老。\n思量也胜，看人眉头眼脑。\n世间浑是梦，何时了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5981, '感皇恩', '周紫芝', '玉箸点椒花，年华又杪。\n绛蜡烧残暗催晓。\n小窗醒处，梦断月斜江悄。\n故山春欲动，归程杳。\n天意不放，人生长少。\n富贵应须致身早。\n此宵长愿，赢取一尊娱老。\n假饶真百岁，能多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5982, '感皇恩', '周紫芝', '无事小神仙，世人谁会。\n著甚来由自萦系。\n人生须是，做些闲中活计。\n百年能几许，无多子。\n近日谢天，与片闲田地。\n作个茅堂待打睡。\n酒儿熟也，赢取山中一醉。\n人间如意事，只此是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5983, '感皇恩', '周紫芝', '江上一山横，偶来同住。\n山北山南共来去。\n今朝何事，目送征鸿轻举。\n可堪吹不断，梨花雨。\n千里莫厌，重霄云路。\n飞下彤庭伴鹭。\n紫骝乌帽，看尽章台风絮。\n故人应问我，今何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5984, '感皇恩', '周紫芝', '何处是云庵，本来无住。\n云共谁来共谁去。\n菊篱杯酒，聊为渊明频举。\n幅巾应屡湿，斜川雨。\n此去常恨，相从无路。\n记取孤飞水边鹭。\n重来一笑，又是柳飞残絮。\n梦魂飞不到，君闲处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5985, '洞仙歌', '周紫芝', '江梅吹尽，更幽兰香度。\n可惜浓春为谁住。\n最嫌他、无数轻薄桃花，推不去，偏守定、东风一处。\n病来应怕酒，□眼常醒，老去羞春似无语。\n准拟强追随，管领风光，人生只、欢期难预。\n纵留得、梨花做寒食，怎吃他朝来，这般风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5986, '贺新郎', '周紫芝', '白首归何晚。\n笑一椽、天教负与，楚江南岸。\n门外春山晚无数，只有匡庐似染。\n但想像、红妆不见。\n谁念香山当日事，漫青衫、泪湿人谁管。\n歌旧曲，空凄怨。\n将军未老身归汉。\n算功名、过了唯有，古词尘满。\n谁似渊明拚得老，饱看云山万点。\n况此老、斜川不远。\n终待我他年自，剪黄花、一酹重阳盏。\n君为我，休辞劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5987, '苏幕遮', '周紫芝', '水傍边，山尽处。\n唤取云来，共我山头住。\n分得一江风共雨。\n满院芙蓉，更听红妆舞。\n趁霜晴，闲独步。\n那里烟村，有个梅花树。\n小径斜穿来又去。\n醉後知他，有甚青云路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5988, '苏幕遮', '周紫芝', '老相邀，山作伴。\n千里西来，始识庐山面。\n爱酒扬雄浑不管。\n天与邻翁，来慰穷愁眼。\n似惊鸿，吹又散。\n画柯横江，望断江南岸。\n地角天涯无尽远。\n一阕清歌，且放梨花满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5989, '一剪梅・一翦梅', '周紫芝', '无限江山无限愁。\n两岸斜阳，人上扁舟。\n阑干吹浪不多时，酒在离尊，情满沧洲。\n早是霜华两鬓秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5990, '千秋岁', '周紫芝', '小春时候。\n晴日吴山秀。\n霜尚浅，梅先透。\n波翻盏，雾暖芙蓉绣。\n持寿酒。\n仙娥特地回双袖。\n试问春多少。\n恩入芝兰厚。\n松不老，山长久。\n星占南极远，家是椒房旧。\n君一笑。\n金鸾看取人归後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5991, '千秋岁', '周紫芝', '当年文焰。\n蜀锦词华烂。\n年正少，声初远。\n手攀天上桂，书奏蓬莱殿。\n人尽道，洛阳盛事今重见。\n千尺青苍干。\n直节凌霄汉。\n天未识，应嗟晚。\n饮残长寿盏，归奉春皇燕。\n金叶满。\n擗麟且受麻姑劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5992, '千秋岁', '周紫芝', '送春归去。\n说与愁无数。\n君去後，归何处。\n人应空懊恼，春亦无言语。\n寒日暮，腾腾醉梦随风絮。\n尽日间庭雨。\n红湿秋千柱。\n人恨切，莺声苦。\n拟倾浇闷酒，留取残红树。\n春去也，不成不为愁人住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5993, '风入松', '周紫芝', '禁烟过後落花天。\n无奈轻寒。\n东风不管春归去，共残红、飞上秋千。\n看尽天涯芳草，春愁堆在阑干。\n楚江横断夕阳边。\n无限青烟。\n旧时云去今何处，山无数、柳涨平川。\n与问风前回雁，甚时吹过江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5994, '忆王孙', '周紫芝', '梅子生时春渐老。\n红满地、落花谁扫。\n旧年池馆不归来，又绿尽、今年草。\n思量千里乡关道。\n山共水、几时得到。\n杜鹃只解怨残春，也不管、人烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5995, '减字木兰花', '周紫芝', '快风消暑。\n门近雨边梅子树。\n昼梦腾腾。\n急雨声中唤不醒。\n轻衫短。\n林下日长聊散发。\n无计医贫。\n长作云山高卧人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5996, '采桑子', '周紫芝', '云踪老去浑无定，飘泊寒空。\n又被东风。\n吹过江南第几峰。\n长安市上看花眼，不到衰翁。\n好趁归鸿。\n家在西岩碧桂丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5997, '渔父词・渔父', '周紫芝', '好个神仙张志和。\n平生只是一渔蓑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5998, '渔父词・渔父', '周紫芝', '禁中图画访玄真。\n晚得歌词献紫宸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (5999, '渔父词・渔父', '周紫芝', '解印归来暂结庐。\n有时同钓水西鱼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6000, '渔父词・渔父', '周紫芝', '趁梅寻得水边枝。\n独棹渔船却过溪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6001, '渔父词・渔父', '周紫芝', '人间何物是穷通。\n终向烟波作钓翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6002, '花心动', '李弥逊', '水馆风亭，晚香浓、一番荷芰经雨。\n簟枕乍闲，襟裾初试，散尽满轩袢暑。\n断云却送轻雷去，疏林外、玉钩微吐。\n夜未阑，秋生败叶，暗催庭树。\n天上佳期久阻。\n星河畔，仙车缥缈云路。\n旧恨未平，幽欢难驻，洒落半天风露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6003, '一寸金', '李弥逊', '仙李盘根，自有云仍霭芳裔。\n更留雨霜皮，临风玉树，紫髯丹颊，长生久视。\n鹤帐琅书至。\n长庚梦、当年暗记。\n佳辰近，回首西风，渐喜秋英弄霜蕊。\n暂卷双旌，鸣金吹竹，萱堂伴新戏。\n对璧月流光，屏山供翠，碧云乍合，飞觞如缀。\n早晚岩廊侍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6004, '蝶恋花', '李弥逊', '百尺游丝当秀户。\n不系春晖，只系闲愁住。\n拾翠归来芳草路。\n避人蝴蝶双飞去。\n困脸羞眉无意绪。\n陌上行人，记得清明否。\n消息未来池阁暮。\n一饷梨花雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6005, '蝶恋花', '李弥逊', '足力穷时山已晦。\n却上轻舟，急棹穿沙背。\n云影渐随风力退。\n一川月白寒光碎。\n唤客主人陶谢辈。\n拂石移尊，不管游人醉。\n罗绮丛中无此会。\n只疑身在烟霞外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6006, '蝶恋花', '李弥逊', '清晓天容争显晦。\n溪上群山，戢戢分驼背。\n谁似浮云知进退。\n疏林嫩日黄金碎。\n夜枕不眠憎鼠辈。\n困眼贪晴，拚被风烟醉。\n天意有情人不会。\n分明置我风波外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6007, '蝶恋花', '李弥逊', '百叠青山江一缕。\n十里人家，路绕南台去。\n榕叶满川飞白鹭。\n疏帘半卷黄昏雨。\n楼阁峥嵘天尺五。\n荷芰风清，习习消袢暑。\n老子人间无著处。\n一尊来作横山主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6008, '蝶恋花', '李弥逊', '小小芙蕖红半展。\n占早争先，不奈腰肢软。\n罗袜凌波娇欲颤。\n向人如诉闺中怨。\n把酒与君成眷恋。\n约束新荷，四面低歌扇。\n不放游人偷眼盼。\n鸳鸯叶底潜窥见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6009, '虞美人', '李弥逊', '上阳迟日千门锁。\n花外流莺过。\n一番春去又经秋。\n惟有深宫明月、照人愁。\n暗中白发随芳草。\n却恨容颜好。\n更无魂梦到昭阳。\n肠断一双飞燕、在雕粱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6010, '虞美人', '李弥逊', '海棠开後春谁主。\n日日催花雨。\n可怜新绿遍残枝。\n不见香腮和粉、晕燕脂。\n去年携手听金缕。\n正是花飞处。\n老来先自不禁愁。\n这样愁来欺老、几时休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6011, '虞美人', '李弥逊', '金泥捍拨春声碎。\n恨入相思泪。\n醉欺秋水绿云斜。\n浑似梦中重到、阿环家。\n主人著意留春住。\n不醉无归去。\n只愁银烛晓生寒。\n明日落花飞絮、满长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6012, '虞美人', '李弥逊', '年年江上清秋节。\n盏面分霜月。\n不堪对月已伤离。\n那更梅花开後、海棠时。\n剑溪难驻仙游路。\n直上云霄去。\n藕花恰莫碍行舟。\n要趁潮头八月、到扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6013, '虞美人', '李弥逊', '方壶小有人谁到。\n底事春知早。\n使君和气粲如花。\n更筑百花深处、驻春华。\n云关远枕苕溪浅。\n未放归怀展。\n看残红紫绿阴斜。\n鸾凤干霄却上、玉皇家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6014, '青玉案', '李弥逊', '杨花尽做难拘管。\n也解趁、飞红伴。\n骢马无情人渐远。\n沙平浅渡，雨湿孤村，何处长亭晚。\n欲凭桃叶传春怨。\n算不似、斜风倩双燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6015, '菩萨蛮', '李弥逊', '小山娇翠低歌扇。\n雏莺学语春犹浅。\n无力响方檀。\n声随玉笋翻。\n垂鬟云乍染。\n媚靥香微点。\n未解作轻颦。\n凝情已动人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6016, '菩萨蛮', '李弥逊', '凉飙轻散馀霞绮。\n疏星冷浸明河水。\n枕画檐风。\n秋生草际蛩。\n雁门离塞晚。\n不道衡阳远。\n归恨隔重山。\n楼高莫凭栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6017, '菩萨蛮', '李弥逊', '风庭瑟瑟灯明灭。\n碧梧枝上蝉声歇。\n枕冷梦魂惊。\n一阶寒水明。\n鸟飞人未起。\n月露清如洗。\n无语听残更。\n愁从两鬓生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6018, '菩萨蛮', '李弥逊', '馀霞收尽寒烟绿。\n江山一片团明玉。\n枕画楼风。\n愁生草际蛩。\n金茎秋未老。\n两鬓吴霜早。\n忍负广寒期。\n清尊对语谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6019, '浣溪沙', '李弥逊', '小小茅茨隐翠微。\n桥平双手弄涟漪。\n好风还动去年枝。\n得雨疏梅肥欲展，人家次第有芳菲。\n惜花恰莫探春迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6020, '浣溪沙', '李弥逊', '箫鼓哀吟乐楚臣。\n牙樯锦缆簇江。\n调高彩笔逞尖新。\n海角逢时伤老大，莫辞卮酒话情亲。\n与君同是异乡人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6021, '浣溪沙', '李弥逊', '向日南枝不奈晴。\n无风绛雪自飘零。\n画楼更作断肠声。\n小侧金荷迎落蕊，高烧银烛照残英。\n生愁斜月酒初醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6022, '临江仙', '李弥逊', '枝上子规催去旆，柳条偏系离情。\n片云留雨锁愁城。\n不堪明月夜，寂寞照南荣。\n莫作东山今日计，风雷已促鹏程。\n功成来伴赤松行。\n却寻鸿雁侣，尊酒会如星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6023, '临江仙', '李弥逊', '燕去莺来昏又晓，劳生莫负心期。\n菊花何必待开时。\n十分浮玉蚁，一拍贯珠词。\n少借笔端烟雨力，不须露染风披。\n芳心微露定因谁。\n风流今太傅，萧洒古东篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6024, '临江仙', '李弥逊', '多病渊明刚止酒，不禁秋蕊浮香。\n饮船歌板已兼忘。\n吴霜羞鬓改，无语对红妆。\n小拈青枝撩鼻观，绝胜娇额涂黄。\n独醒滋味怕新凉。\n归来烛影乱，枕听更长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6025, '临江仙', '李弥逊', '一片花飞春已减，那堪万点愁人。\n可能春便负闲身。\n细思愁不饮，却是自辜春。\n且共一尊追落蕊，犹胜陌上成尘。\n杯行到手莫辞频。\n杏花须记取，曾与此翁邻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6026, '临江仙', '李弥逊', '试问花枝馀几许，卷帘细雨随人。\n风光犹恋苦吟身。\n海棠浑怯冷，为我强留春。\n细听惜花歌白雪，不知盏面生尘。\n吹开吹谢漫惊频。\n少陵真有味，爱酒觅南邻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6027, '醉花阴', '李弥逊', '翠箔阴阴笼画阁。\n昨夜东风恶。\n香迳慢春泥，南陌东郊，惆怅妨行乐。\n伤春比似年时觉。\n潘鬓新来薄。\n何处不禁愁，雨滴花腮，和泪胭脂落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6028, '醉花阴', '李弥逊', '紫菊红萸开犯早。\n独占秋光老。\n酝造一般清，比著芝兰，犹自争多少。\n霜刀翦叶呈纤巧。\n手拈迎人笑。\n云鬓一枝斜，小阁幽窗，是处都香了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6029, '清平乐', '李弥逊', '烛花催晓。\n醉玉颓春酒。\n一骑东风消息到。\n占得鳖头龙首。\n长安去路。\n明朝跃马芳阴。\n应是花繁莺巧，东君著意琼林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6030, '清平乐', '李弥逊', '一帘红雨。\n飘荡谁家去。\n门外垂杨千万缕。\n不把东风留住。\n旧巢燕子来迟。\n故园绿暗残枝。\n肠断画桥烟水，此情不许春知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6031, '浪淘沙', '李弥逊', '把酒挽芳时。\n醉袖淋漓。\n多情楚客为秋悲。\n未抵香飘红褪也，独绕空枝。\n天女宝刀迟。\n露染风披。\n翠云叠叠拥铢衣。\n知道筠溪春寂寞，来慰相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6032, '浪淘沙', '李弥逊', '乐事信难逢。\n莫放匆匆。\n飞红撩乱减春容。\n临水不禁频送客，风袖龙锺。\n小阁画堂东。\n绮绣相重。\n尊前谁唱夏云峰。\n醒後欲寻溪上路，烟水无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6033, '谒金门', '李弥逊', '春又老。\n愁似落花难扫。\n一醉一回才忘了。\n醒来还满抱。\n此恨欲凭谁道。\n柳外数声啼鸟。\n只恐春风吹不到。\n断云连碧草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6034, '滴滴金', '李弥逊', '广平未拚心如铁。\n恨梅花、隔年别。\n化工翦水斗春风，似南枝和月。\n长鲸一饮宁论石。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6035, '诉衷情', '李弥逊', '小桃初破两三花。\n深浅散馀霞。\n东君也解人意，次第到山家。\n临水岸，一枝斜。\n照笼纱。\n可怜何事，苦爱施朱，减尽容华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6036, '好事近', '李弥逊', '春苑杂花芳，诗老剩夸梅格。\n谁道武陵深处，便不如姑射。\n莫分红浅与红深，点点是春色。\n生怕一番风雨，半飘零江国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6037, '鹤冲天', '李弥逊', '玉液，酿花光。\n来趁北窗凉。\n为君小摘蜀葵黄。\n一似嗅枝香。\n饮中仙，山中相。\n也道十分宫样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6038, '天仙子', '李弥逊', '飞盖追春春约伫。\n繁杏枝头红未雨。\n小楼翠幕不禁风，芳草路。\n无尘处。\n明月满庭人欲去。\n一醉邻翁须记取。\n见说新妆桃叶女。\n明年却对此花时，留不住。\n花前语。\n总向似花人付与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6039, '清平乐', '李弥逊', '断桥缺月。\n点点枝头雪。\n画角吹残声未歇。\n早是一年春别。\n寿阳弄粉成妆。\n柔肠结结丁香。\n可怕真梅轻妒，游蜂说与何妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6040, '清平乐', '李弥逊', '推愁何计。\n车下忘乘坠。\n日上南枝春有意。\n已讶红酥如缀。\n儿童缓整馀杯。\n芒鞋午夜重来。\n素面应憎月冷，真香不逐风回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6041, '清平乐', '李弥逊', '长红小白。\n何处寻梅格。\n日日南山云满额。\n暗老一分春色。\n广平赋罢瑶香。\n细□花蕊商量。\n留得笔端雨露，後来收拾群芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6042, '点绛唇', '李弥逊', '翦翦疏花，托根宛在长松底。\n蔓柯相倚。\n便有凌霄志。\n丹凤忽来，小队迎秋起。\n留无计。\n待公归侍。\n重与分红翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6043, '虞美人', '李弥逊', '梨花院落溶溶雨。\n弱柳低金缕。\n画檐风露为谁明。\n青翼来时试问、董双成。\n去年春酒为眉寿。\n花影浮金斗。\n不须更觅老人星。\n但愿一年一上、一千龄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6044, '醉花阴', '李弥逊', '池面芙蕖红散绮。\n鹊噪朱门喜。\n环佩响天风，香霭杯盘，更约麻姑侍。\n尘寰不隔蓬莱水。\n束带岩廊戏。\n瘦鹤与长松，且伴仙，久住人间世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6045, '醉花阴', '李弥逊', '帘卷西风轻雨外。\n揖数峰横翠。\n楼上地行仙，压玉为醪，旋摘黄金蕊。\n一觞一阕千秋岁。\n不愿封侯贵。\n长伴紫髯翁，踏月吹箫，笑咏云山里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6046, '感皇恩', '李弥逊', '花院小回廊，庭萱成行。\n水面红妆翠绡帐。\n蓬莱云近，风露一番清旷。\n星郎来碧落，长庚象。\n素志未酬，丹心益壮。\n且醉真珠小槽酿。\n不须皓齿，拍手狂歌清唱。\n一尊为寿庆，羲皇上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6047, '感皇恩', '李弥逊', '密竹翦轻绡，华堂初建。\n卷上虾须待开宴。\n寿期春聚，芍药一番开遍。\n砌成锦步帐，笼弦管。\n绛节近颁，丹雏重见。\n花里双双乍归燕。\n重重乐事，凭仗东风拘管。\n一时分付与，金荷劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6048, '小重山', '李弥逊', '鞭凤骖鸾自斗杓。\n老君亲抱送，下层霄。\n人间仙李占春饶。\n千秋里，松月伴吹箫。\n故国水云遥。\n谪仙丹荔熟，剥红绡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6049, '小重山', '李弥逊', '星斗心胸锦绣肠。\n厌随尘土客，逐炎凉。\n江山风月伴行藏。\n无人识，高卧水云乡。\n肘後有仙方。\n假饶丹未就，寿须长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6050, '花心动', '李弥逊', '红日当楼，绣屏开、风舞花随步。\n绛拂佩兰，香染妆梅，彷佛紫烟真侣。\n雪消池馆年年会，玻璃泛、小槽新注。\n弄箫语。\n云未彻，暖回芳树。\n瑶检曾寿缕。\n好系日萦春，驭鸾深驻。\n桂殿影寒，蓬山波阔，未似彩衣庭户。\n坐看鹤鬓云来戏，重重拜、天阶雨露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6051, '渔家傲', '李弥逊', '海角秋高风力骤。\n楼台四面山容瘦。\n季子貂裘寒欲透。\n悬弧昼。\n高歌棣萼聊卮酒。\n且共追欢宽白首。\n清闲赢得身长久。\n世上功名翻覆手。\n为君寿。\n腰间要看悬金斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6052, '阮郎归', '李弥逊', '黄花犹未拆霜枝。\n今年秋较迟。\n六么催泛玉东西。\n登高庆诞时。\n神仙事，古来稀。\n且为千岁期。\n戏莱堂上两庞眉。\n何妨举案齐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6053, '醉落托', '李弥逊', '霜林变绿。\n画帘桂子排香粟。\n一声檀板惊飞鹜。\n弦管楼高，谁在阑干曲。\n人生一笑难相属。\n满堂何必堆金玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6054, '柳梢青', '李弥逊', '寿烟笼席。\n采莲新按，舞腰无力。\n占尽风光，人间天上，今夕何夕。\n蓝袍换了莱衣，庆岁岁、君恩屡锡。\n连夜欢声，满城佳气，和春留得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6055, '点绛唇', '李弥逊', '花信争先，暗将春意传桃李。\n寿卿同醉。\n绿野连珠履。\n麟阁丹青，眷注耆英裔。\n眉间喜。\n日边飞骑。\n来促东山起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6056, '十样花', '李弥逊', '陌上风光浓处。\n第一寒梅先吐。\n待得春来也，香销减，态凝伫。\n百花休谩妒。\n陌上风光浓处。\n繁杏枝头春聚。\n艳态最娇娆，堪比并，东邻女。\n红梅何足数。\n陌上风光浓处。\n日暖山樱红露。\n结子点朱唇，花谢後，君看取。\n流莺偏嘱付。\n陌上风光浓处。\n忘却桃园归路。\n洞口水流迟，香风动，红无数。\n吹愁何处去。\n陌上风光浓处。\n最是海棠风措。\n翠袖衬轻红，盈盈泪，怨春去。\n黄昏微带雨。\n陌上风光浓处。\n自有花王为主。\n富艳压群芳，蜂蝶戏，燕莺语。\n东君都付与。\n陌上风光浓处。\n红药一番经雨。\n把酒绕芳丛，花解语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6057, '菩萨蛮', '李弥逊', '江城烽火连三月。\n不堪对酒长亭别。\n休作断肠声。\n老来无泪倾。\n风高帆影疾。\n目送舟痕碧。\n锦字几时来。\n薰风无雁回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6058, '水调歌头', '王以宁', '岁晚橘洲上，老叶舞愁红。\n西山光翠，依旧影落酒杯中。\n人在子亭高处，下望长沙城郭，猎猎酒帘风。\n远水湛寒碧，独钓绿蓑翁。\n怀往事，追昨梦，转头空。\n孙郎前日，豪健颐指五都雄。\n起拥奇才剑客，十万银戈赤帻，歌鼓壮军容。\n何似裴相国，谈道老圭峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6059, '水调歌头', '王以宁', '大别我知友，突兀起西州。\n十年重见，依旧秀色照清眸。\n常记鲒狂客，邀我登楼雪霁，杖策拥羊裘。\n山吐月千仞，残夜水明楼。\n黄粱梦，未觉枕，几经秋。\n与君邂逅，相逐飞步碧山头。\n举酒一觞今古，叹息英雄骨冷，清泪不能收。\n鹦鹉更谁赋，遗恨满芳洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6060, '满庭芳', '王以宁', '山耸方壶，潮通碧海，江东自昔名家。\n玉真仙子，佩粲朝霞。\n一种天香胜味，笑杨梅、不数枇杷。\n难模写，牟尼妙质，光透紫丹砂。\n咨嗟。\n如此辈，不知何为，留滞天涯。\n料甘心远引，无意纷华。\n一任姚黄魏紫，供吟赏、银烛笼纱。\n南游士，日餐千颗，不愿九霞车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6061, '满庭芳', '王以宁', '千古南阳，刘郎乡国，依约楚俗秦风。\n英姿豪气，耆旧笑谈中。\n佩来从帝所，许洲花、潭菊从容。\n霜秋晓，凉生日观，极目送飞鸿。\n主公。\n天下士，挥豪万字，一饮千锺。\n醉高歌起舞，唤醒人龙。\n我自人间漫浪，平生事、南北西东。\n辞公去，寒眸激电，曾识小安丰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6062, '满庭芳', '王以宁', '五十七年，侵寻老矣，小庵初筑林。\n故人相过，喜雪舞祥。\n遍野跳珠浅玉，纵儿童、收满金瓶。\n明年待，洗光银海，袖手看升平。\n先生。\n齐物久，蚁丘罢战，蜗角休征。\n趁尊前身健，有酒须倾。\n随分村歌社舞，何须问、武宿文星。\n忘怀矣，未能忘酒，相与醉忘形。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6063, '满庭芳', '王以宁', '千古黄州，雪堂奇胜，名与赤壁齐高。\n竹楼千字，笔势压江涛。\n笑问江头皓月，应曾照、今古英豪。\n菖蒲酒，尊无恙，聊共访临皋。\n陶陶。\n谁晤对，粲花吐论，宫锦纫袍。\n借银涛雪浪，一洗尘劳。\n好在江山如画，人易老、双鬓难。\n升平代，凭高望远，当赋反离骚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6064, '蓦山溪', '王以宁', '平山堂上，侧盏歌南浦。\n醉望五州山，渺千里、银涛东注。\n钱郎英远，满腹贮精神，窥素壁，墨栖鸦，历历题诗处。\n风裘雪帽，踏遍荆湘路。\n回首古扬州，沁天外、残霞一缕。\n德星光次，何日照长沙，渔夫曲，竹枝词，万古歌来暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6065, '蓦山溪', '王以宁', '雕弓绣帽。\n戏马秦淮道。\n风入马啼轻，曾踏遍、淮堤芳草。\n飞英点点，春事已阑珊，风雨横，别离多，断送英雄老。\n功名终在，休惜芳尊倒。\n谈笑下燕云，看千里、风驱电扫。\n男儿此事，莫待鬓丝棼，汉都护，万年觞，玉殿春风早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6066, '念奴娇', '王以宁', '天工何意，碎琼玉佩，书空千尺。\n箬笠蓑衫扁舟下，淮口烟林如织。\n飞观嶙峋，子亭突兀，影浸澄淮碧。\n纶巾鹤氅，是谁独笑携策。\n遥想易水燕山，有人方醉赏，六花如席。\n云重天低酣歌罢，胆壮乾坤犹窄。\n射雉归来，铁鳞十万，踏碎千山白。\n紫箫声断，唤回春满南陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6067, '念奴娇', '王以宁', '云收天碧。\n渐风高露冷，群喧初寂。\n远浦归舟荒渡口，搴篷横棹堤侧。\n一带澄江，十分蟾影，千里寒光白。\n襟怀迎爽，有人独步携策。\n遥想帘卷琼楼，凭阑凝望，此意知何极。\n声断琴箫双凤驾，凌厉飞仙同籍。\n问汉乘槎，采珠临海，往事空踪迹。\n莫辞吟赏，终宵清景难得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6068, '念奴娇', '王以宁', '晚烟凝碧。\n渐渔村山市，人归寂寂。\n有客飞舟还顾访，应讶纶巾侧。\n得意忘年，推诚投分，高论追元白。\n英标逸气，笑予穷抱真策。\n兴尽又复言归，秋风分袂，浩荡思无极。\n咫尺昭山明翠壁，那知中隐咸籍。\n说梦难听，闭门寻梦，肯念栖萍迹。\n浪吟狂醉，几时还共重得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6069, '鹧鸪天', '王以宁', '昔有书生荐寿杯。\n清词妙绝贺方回。\n黄花也欲为君寿，先向重阳六日开。\n跻楚俗，上春台。\n政成归去位三台。\n明年寿酒君王劝，知有传宣敕使来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6070, '鹧鸪天', '王以宁', '帝乙何年骑玉龙。\n武夷仙伯笑相从。\n长庚瑞应游仙梦，碧藕花开解愠风。\n歌既醉，乐元丰。\n明良相悦寿无穷。\n野人更有深深祝，笑指三台十八公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6071, '鹧鸪天', '王以宁', '桃李纷纷春事催。\n桐花风定牡丹开。\n天麟下作人间瑞，玉燕清宵入梦来。\n红玉酎，紫霞杯。\n五云深处望三台。\n君家况有庭前柏，好个擎天八柱材。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6072, '临江仙', '王以宁', '眼看西园红与紫，年来几度芳菲。\n吾生四十渐知非。\n祗思青箬笠，江上雨霏霏。\n饮酒但知寻夏季，不须远慕安期。\n丹成仙去是何时。\n龟藏何必学，春日正迟迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6073, '临江仙', '王以宁', '此理循环如引锯，春来百草菲菲。\n道人一笑悟前非。\n功名真长物，夕霭与朝霏。\n梦褥清孙今绿隐，漫郎自许风期。\n江楼景物得旬时。\n平芜三百里，天阔夕阳迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6074, '临江仙', '王以宁', '闻道洛阳花正好，家家遮户春风。\n道人饮处百壶空。\n年年花下醉，看尽几番红。\n此拐又从何处去，飘蓬一任西东。\n语声虽异笑声同。\n一轮清夜月，何处不相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6075, '浣溪沙', '王以宁', '起看船头蜀锦张。\n沙汀红叶舞斜阳。\n杖拿惊起睡鸳鸯。\n木落群山雕玉□，霜和冷月浸澄江。\n疏篷今夜梦潇湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6076, '西江月慢', '吕渭老', '春风淡淡，清昼永、落英千尺。\n桃杏散平郊，晴蜂来往，妙香飘掷。\n傍画桥、煮酒青帘，绿杨风外，数声长笛。\n记去年、紫陌朱门，花下旧相识。\n向宝帕、裁书凭燕翼。\n望翠阁、烟林似织。\n闻道春衣犹未整，过禁烟寒食。\n但记取、角枕情题，东窗休误，这些端的。\n更莫待、青子绿阴春事寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6077, '思佳客', '吕渭老', '曾醉扬州十里楼。\n竹西歌吹至今愁。\n燕衔柳絮春心远，鱼入晴江水自流。\n情渺渺，梦悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6078, '思佳客', '吕渭老', '薄薄山云欲湿花。\n双双燕子入帘斜。\n西楼尚记垂垂雪，酌酒犹残片片霞。\n人已远，发成华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6079, '夜游宫', '吕渭老', '帘外繁霜未扫。\n楼角动、玉绳横晓。\n百和交焚瑞烟绕。\n霁霞明，画屏深，天渺渺。\n喜色连池沼。\n荐眉寿、玉儿娇小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6080, '浣溪沙', '吕渭老', '风扫长林雪压枝。\n纷纷冻鹊傍帘飞。\n一尊聊作破寒威。\n春意正愁梅漏泄，客情尤怕病禁持。\n曲阑干外日初迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6081, '南歌子', '吕渭老', '片片云藏雨，重重雾隐山。\n可怜新月似眉弯。\n今夜断肠凝望、小楼寒。\n梦断云房远，书长蜡炬残。\n夜妆应罢短屏间。\n都把一春心事、付梅酸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6082, '如梦令', '吕渭老', '珠阁雨帘高卷。\n望断碧梧墙院。\n短梦有幽寻，晓枕一峰云乱。\n谁见。\n谁见。\n风散菊英千片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6083, '浣溪沙', '吕渭老', '微绽樱桃一颗红。\n断肠声里唱玲珑。\n轻罗小扇掩酥胸。\n惹鬓蛛丝新有喜，窥窗月彩旧相从。\n清宵一醉许谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6084, '浪淘沙', '吕渭老', '凉露洗秋空。\n菊径鸣蛩。\n水晶帘外月玲珑。\n烛蕊双悬人似玉，簌簌啼红。\n宋玉在墙东。\n醉袖摇风。\n心随月影入帘栊。\n戏著锦茵天样远，一段愁浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6085, '醉桃源・阮郎归', '吕渭老', '棂香新染砑红绫。\n腰肢瘦不胜。\n合欢小幌掩馀酲。\n芙蓉入梦频。\n山不尽，水无情。\n锦河隔锦茵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6086, '思佳客', '吕渭老', '梦里相逢不记时。\n断肠多在杏花西。\n微开笑语兜鞋急，远有灯光掠鬓迟。\n辞永夜，失深期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6087, '小重山', '吕渭老', '雨洗檐花湿画帘。\n知他因甚地，瘦厌厌。\n玉人风味似冰蟾。\n愁不见，烟雾晓来添。\n烦恼旧时谙。\n新来一段事，未心甘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6088, '柳梢青', '吕渭老', '远帘笼月。\n谁见南陌，子规啼血。\n萸糁菊英，整冠落帽，一时虚说。\n五湖自有深期，曾指定、灯花细说。\n燕子巢空，秋鸿程远，音书中绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6089, '卜算子', '吕渭老', '云破月高悬，照我双双泪。\n人在朱桥转曲西，翠幕重重闭。\n要见索商量，见了还无计。\n心似长檠一点灯，到晓清清地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6090, '卜算子', '吕渭老', '眉为占愁多，镇日长长敛。\n试问心中有底愁，泪早千千点。\n莫唱短因缘，缘短犹伤感。\n谁信萧郎是路人，常有深深念。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6091, '卜算子', '吕渭老', '一日抵三秋，半月如千岁。\n自夏经秋到雪飞，一向都无计。\n续续说相思，不尽无穷意。\n若写幽怀一段愁，应用天为纸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6092, '卜算子', '吕渭老', '得酒解愁烦，多病还疏酒。\n本是多情失意人，此味如何受。\n沈醉且高歌，不饮心常有。\n守著残灯斗著眉，怎不腰肢瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6093, '如梦令', '吕渭老', '多谢西池桃李。\n伴我一春沈醉。\n能有几多香，陪了一江来泪。\n憔悴。\n憔悴。\n又是落花铺地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6094, '木兰花慢', '吕渭老', '石榴花谢了，正荷叶、盖平池。\n试玛瑙杯深，琅簟冷，临水帘帷。\n知他故人甚处，晚霞明、断浦柳枝垂。\n唯有松风水月，向人长似当时。\n依依。\n望断水穷，云起处、是天涯。\n奈燕子楼高，江南梦断，虚费相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6095, '木兰花慢', '吕渭老', '对修篁万个，更疏雨、洗琅。\n望燕外晴丝，鸥边水叶，胡蝶成团。\n榴红劝人把酒，泛菖蒲、对客不成欢。\n金缕新番彩索，始知今岁衣宽。\n年年。\n此日青楼，花缺处、倚阑干。\n记小扇清歌，蛮笺妙墨，不觉更残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6096, '木兰花慢', '吕渭老', '桂乡云万缕，更飞雨、洗香车。\n念密会经年，银潢浪阻，玉露期赊。\n灵星瑞桥对展，散匆匆、喜色满天涯。\n回首丁宁晓角，未宜吹动梅花。\n家家。\n竟赏彩茸，穿桂影、醉流霞。\n渐舞袖翻鸾，歌声缀凤，钗影交加。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6097, '恋香衾', '吕渭老', '记得花阴同携手，指定日、许我同欢。\n唤做真成，耳热心安。\n打叠从来不成器，待做个、平地神仙。\n又却不成些事，蓦地心残。\n据我如今没投奔，见著你、泪早偷弹。\n对月临风，一味埋冤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6098, '豆叶黄・忆王孙', '吕渭老', '芰荷香外一声蝉。\n风撼琅惊昼眠。\n刻烛题诗花满笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6099, '豆叶黄・忆王孙', '吕渭老', '晚妆新试碧衫凉。\n金鸭犹残昨夜香。\n柳际风来月满廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6100, '豆叶黄・忆王孙', '吕渭老', '轻罗团扇掩微羞。\n酒满玻璃花满头。\n小板齐声唱石州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6101, '豆叶黄・忆王孙', '吕渭老', '林花著雨褪胭脂。\n叶底双桃结子迟。\n对镜凭郎略皱眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6102, '豆叶黄・忆王孙', '吕渭老', '玉萧风外一声清。\n粉面婵娟月对明。\n紫府楼台夜不扃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6103, '千秋岁', '吕渭老', '宝蟾悬镜。\n露颗倾荷柄。\n飞萤点点明花径。\n凝愁情不展，宿酒风还醒。\n天似晓，银河半落星相趁。\n心事都无定。\n才致元相称。\n春过了，秋将近。\n小窗通竹圃，野色连金井。\n得仗个，多情燕子分明问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6104, '好事近', '吕渭老', '心事已成空，春尽百花零落。\n谁见黄鹂百啭，索东君评泊。\n晓来枝上语绵蛮，应悔向来错。\n看则绿阴青子，却惶无托。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6105, '南乡子', '吕渭老', '小雨阻行舟。\n人在烟林古渡头。\n欲挈一尊相就醉，无由。\n谁见横波入鬓流。\n百计不迟留。\n明月他时独上楼。\n水尽又山山又水，温柔。\n占断江南万斛愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6106, '南乡子', '吕渭老', '樊子唤春归。\n梦逐杨花满院飞。\n吹过西家人不见，依依。\n萍点荷钱又满池。\n屈指数佳期。\n何日凭肩对展眉。\n倾尽十分应不醉，迟迟。\n何惜樱桃杏子时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6107, '浪淘沙', '吕渭老', '纤指捧玻璃。\n莫惜重持。\n自离阆苑失回期。\n门掩东风桃著子，帘影迟迟。\n楼上正横篦。\n荷气沾衣。\n谁将名玉碾花枝。\n不比寻常红与紫，取次芳菲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6108, '卜算子', '吕渭老', '渡口看潮生，水满蒹葭浦。\n长记扁舟载月明，深入红云去。\n荷尽覆平池，忘了归来路。\n谁信南楼百尺高，不见如莲步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6109, '小重山', '吕渭老', '云护柔条雪压枝。\n斜风吹绛蜡，点胭脂。\n蔷薇柔水麝分脐。\n园林晚，脉脉带斜晖。\n深阁绣帘低。\n宝奁匀泪粉，晚妆迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6110, '惜分钗・撷芳词', '吕渭老', '春将半。\n莺声乱。\n柳丝拂马花迎面。\n小堂风。\n暮楼锺。\n草色连云，暝色连空。\n重重。\n秋千畔。\n何人见。\n宝钗斜照春妆浅。\n酒霞红。\n与谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6111, '惜分钗・撷芳词', '吕渭老', '重帘挂。\n微灯下。\n背兰同说春风话。\n月盈楼。\n泪盈眸。\n觑著红，无计迟留。\n休休。\n莺花谢。\n春残也。\n等闲泣损香罗帕。\n见无由。\n恨难收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6112, '如梦令', '吕渭老', '花趁清明争展。\n白白红红满院。\n莫怪泪痕多，爱底不能得见。\n凝恋。\n凝恋。\n门外雨飞帘卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6113, '水龙吟', '吕渭老', '年年九月西湖，绣船继日笙箫拥。\n五云深处，红帘一桁，语莺歌凤。\n群玉峰头，影娥池畔，烟霞飞动。\n认蓬瀛仙子，云程路远，贪人世、瑶池梦。\n要看黄尘清海，戏真珠、麻姑清纵。\n曲门自有，菊金芳砌，月篦浮栋。\n子著宫桃，舞翻官柳，霞杯纤捧。\n待明年更把，西风妙曲，按成新弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6114, '鹊桥仙', '吕渭老', '西风不落，薄衾孤枕，记起花时些个。\n宿愁新恨两关心，说道理、分疏不可。\n别愁如絮，佳期何在，古屋萧萧灯火。\n打窗风雨又何消，梦未就、依前惊破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6115, '点绛唇', '吕渭老', '扇列红鸾，赭黄日色明金殿。\n御香葱茜。\n宝仗香风暖。\n咫尺天颜，九奏朝阳管。\n群臣宴。\n醉霞凝面。\n午漏传宫箭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6116, '点绛唇', '吕渭老', '俊眼犀心，尊前如有乘鸾便。\n过愁传怨。\n只许灯光见。\n见了重休，河汉明遮断。\n深深院。\n乱风飘霰。\n揉了双罗燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6117, '水调歌头', '吕渭老', '解衣同一笑，聊复起厨烟。\n醉乡何处，与君舒啸入壶天。\n长怪时情狭隘，杯酒岂容我辈，不上谪仙船。\n雅志念湖海，小艇一丝竿。\n夜迢迢，灯烛下，几心闲。\n平生得处，不在内外及中间。\n点检春风欢计，惟有诗情宛转，馀事尽疏残。\n彩笔题桐叶，佳句问平安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6118, '好事近', '吕渭老', '世事莫牵萦，乐取这闲时节。\n且恁醉来醒去，免光阴虚设。\n有则有个泼心儿，不敢被利名啜。\n却待两手分付，与风花雪月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6119, '好事近', '吕渭老', '长记十年前，彼此玉颜云发。\n尊酒几番相对，乐春花秋月。\n而今各自困飘零，憔悴几年别。\n说著大家烦恼，且大家休说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6120, '青玉案', '吕渭老', '一尊聊对西风醉。\n况九日、明朝是。\n曾与茱萸论子细。\n江天虚旷，暮林横远，人隔银河水。\n碧云渐展天无际。\n吹不断、黄昏泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6121, '倾杯乐', '林季仲', '璧月初圆，彩云轻护，散雪叠冰凉馆。\n张眉竞巧，赵瑟新成，整顿戏衫歌扇。\n寿酒殷勤，娇语温柔，只愁杯浅。\n正连山玉枕，回波瑶席，漏长更款。\n良会久、细拥香肩，瑶庭闲步，共指渡河星点。\n今朝此日，同祝卿卿，福寿禄星齐转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6122, '庆清朝', '王之道', '晓日彤墀，春风黄伞，天颜咫尺清光。\n恩袍初赐，一时玉质金相。\n济济满廷鹭，月卿映、日尹星郎。\n鸣鞘绕，锦鞯归路，醉舞醒狂。\n追随宝津琼苑，看穿花帽侧，拂柳鞭长。\n临流夹径，参差绿荫红芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6123, '谒金门', '王之道', '春睡起。\n金鸭暖消沈水。\n笑比梅花鸾鉴里。\n嗅香还嚼蕊。\n琼户倚来重倚。\n又见夕阳西坠。\n门外马嘶郎且至。\n失惊心暗喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6124, '蝶恋花', '王之道', '春入花梢红欲半。\n水外绿杨，掩映笙歌院。\n霁日迟迟风扇暖。\n天光上下青浮岸。\n归去画楼烟暝晚。\n步拾梅英，点缀宫妆面。\n美目碧长眉翠浅。\n消魂正值回头看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6125, '蝶恋花', '王之道', '檐溜潺潺朝复暮。\n燕子衔泥，穿幕来还去。\n素锦青袍知有处。\n花光草色迷汀渚。\n春不负人人自负。\n君看流觞，只恁良宵度。\n厌小桃如泣诉。\n东风莫漫飘红雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6126, '蝶恋花', '王之道', '城上春旗催日暮。\n柳絮沾泥，花蕊随流去。\n记得前时行乐处。\n小桥水渌初平渚。\n玉子纹楸谁胜负。\n不道光阴，暗向闲中度。\n天若有情容我诉。\n春来底事多阴雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6127, '蝶恋花', '王之道', '庭院雨馀秋意晚。\n一阵风来，到处清香遍。\n把酒对花情不浅。\n花前敢避金杯满。\n卜酴虽惯见。\n常恨搀先，不是君徒伴。\n莫把龙涎轻斗远。\n流芳肯逐炉烟断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6128, '蝶恋花', '王之道', '碧雾暗消香篆半。\n花影穿帘，厌苍苔院。\n一双塘水暖。\n浮沈时近垂杨岸。\n雨过不知春事晚。\n但怪朱唇，得酒红潮面。\n野蔌山肴三四盏。\n携尊更向花前看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6129, '蝶恋花', '王之道', '玉子纹楸频较路。\n胜负等闲，休冶黄金注。\n黑白斑斑乌间鹭。\n明窗净几谁知处。\n逼剥声中人不语。\n见可知难，步武来还去。\n何日挂冠宫一亩。\n相从识取棋中趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6130, '蝶恋花', '王之道', '曾向水边云外见。\n争似霜蕤，照映苍苔院。\n檀口半开金袅线。\n端相消得纶巾岸。\n点缀南枝红旋旋。\n准拟杯盘，日向花前宴。\n飞雪飘飘云不卷。\n何人览镜凭阑看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6131, '蝶恋花', '王之道', '杏靥桃腮俱有。\n常避孤芳，独斗红深浅。\n犯雪凌霜芳意展。\n玉容似带春寒怨。\n分得数枝来小院。\n依倚铜瓶，标致能清远。\n淡月帘栊疏影转。\n骚人为尔柔肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6132, '蝶恋花', '王之道', '寒雨霏霏江上路。\n不见书邮，病目空凝注。\n沙觜尽头飞白鹭。\n篙师指似人来处。\n自笑自怜还自语。\n钝滞如君，只合归田去。\n竹屋数间环亩。\n个中自有无穷趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6133, '宴山亭・燕山亭', '王之道', '微雨斑斑，晕湿海棠，渐觉燕脂红褪。\n迟日短垣，娇怯和风，摇曳一成春困。\n玉软酴酥，扶不起、晚妆慵整。\n愁恨。\n对佳时媚景，可堪重省。\n曾约小桃新燕，有蜂媒蝶使，为传芳信。\n西蜀杜郎，东坡苏老，道也道应难尽。\n一朵风流，雅称且、凤翘云鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6134, '风流子', '王之道', '扁舟南浦岸，分携处、鸣佩忆珊珊。\n见十里长堤，数声啼，至今清泪，襟袖斓斑。\n谁信道，沈腰成瘦减，潘鬓就衰残。\n漫把酒临风，看花对月，不言拄笏，无绪凭阑。\n相逢复相感，但凝情秋水，送恨春山。\n应念马催行色，泥溅征衫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6135, '玉连环・解连环', '王之道', '流水细通何处。\n柳溪新雨。\n清风十里送篮舆，行不尽、山无数。\n一簇楼台堵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6136, '江城子', '王之道', '新篁初上箨龙陂。\n绿阴稀。\n绿阴稀。\n墙外石榴，花放两三枝。\n裙褶绛纱还半皱，追往事，惜佳期。\n流莺娇婉燕双飞。\n雨晴时。\n雨晴时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6137, '江城子', '王之道', '寒光凌乱六花纤。\n巧穿帘。\n不鸣檐。\n十里黄垆，遥望辨青帘。\n玉树参差何处觅，吟雪曲，拈霜髯。\n坐来令我看无厌。\n拟名盐。\n试尝甜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6138, '水调歌头', '王之道', '颢气遍寰宇，风露逼衣裘。\n中秋昨夜，明月千里满西楼。\n人道当年今日，海上骑鲸仙客，乘兴下瀛州。\n雅志在扶世，来佐紫宸游。\n庙堂上，须早计，要嘉谋。\n牙床锦帐，三岁江北叹淹留。\n好在蟹螯如臂，判取兵厨百斛，与客醉瑶舟。\n待得蟠桃熟，相约访浮丘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6139, '水调歌头', '王之道', '湖上有佳色，黄菊傲霜秋。\n一尊相属，谈咏彼此得无愁。\n何处鲈鱼初荐，错俎金齑点脍，令我忆东州。\n双鹭带斜日，飞下白苹洲。\n晚风劲，吹残酒，袭破裘。\n故人俱在，江左底事独淹留。\n归去草堂侵夜，一点青荧灯火，得句可忘忧。\n欲识无穷意，终日倚城楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6140, '水调歌头', '王之道', '斜阳明薄暮，暗雨霁凉秋。\n弱云狼藉，晚来风起，席卷更无留。\n天外老蟾高挂，皎皎寒光照水，金璧共沈浮。\n宾主一时杰，倾动庾公楼。\n渡银汉，玉露，势欲流。\n不妨吟赏，坐拥红袖舞还讴。\n暗祝今宵素魄，助我清才逸气，稳步上瀛洲。\n欲识瀛洲路，雄据六鳌头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6141, '水调歌头', '王之道', '琼树挂初日，珠箔卷清霜。\n夜来溪上微雨，佳节过重阳。\n共庆当年此际，曾见天麟协梦，华阀挂蓬桑。\n人作鲁侯祝，俾尔寿而臧。\n保疲瘵，旌德善，致吉祥。\n会看报政，朝夕芝检趣徵黄。\n不藉灵丹九转，不用蟠桃三窃，源远自流长。\n愿借沧溟富，斟酌荐瑶觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6142, '水调歌头', '王之道', '败屋拥破衲，惊飙漫飕。\n不离当处人见，操慧上蓝游。\n弹指九州四海，浪说其来云聚，其去等风休。\n莫作袈裟看，吾道惯聃丘。\n齐死生，同宠辱，泯春秋。\n高名厚利，眇若天地一蜉蝣。\n闲举前人公案，试问把锄空手，何似步骑牛。\n会得个中语，净土在阎浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6143, '水调歌头', '王之道', '暑雨湿修竹，凉吹入高檐。\n鹭洲锺阜如画，霁色为纤。\n槛外藕花无数，妆点休祥嘉应，不觉有秋炎。\n谪仙堕人世，香雾郁重帘。\n富才艺，强记览，三万签。\n须信公侯有种，道义自相渐。\n此去腰金佩玉，回视依莲泛水，岁月亦何淹。\n称觞还戏彩，无惜醉厌厌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6144, '青玉案', '王之道', '金尊照坐红裙绕。\n怪一饷、歌声悄。\n乱扑珠帘风絮晓。\n香薰笑语，酒烘颜色，莫逐流年老。\n诗涛入笔悬河倒。\n快万里云天为君扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6145, '青玉案', '王之道', '逢人借问钱塘路。\n我亦欲、西湖去。\n目送兰桡知几度。\n鳌峰浮玉，鲸波飞雪，正是潮来处。\n海棠花下春将暮。\n缓唱新词味佳句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6146, '青玉案', '王之道', '半年不踏轩车路。\n仿佛过、长桥去。\n贴水行云风送度。\n两行高柳，一坡修竹，是我尝游处。\n黄鹂休叹青春暮。\n出谷迁乔旧家句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6147, '凤箫吟・芳草', '王之道', '雨溟。\n年年今日，农夫共卜新丰。\n登高随处好，银瓶突兀，南峙对三公。\n真珠露菊，更芙蓉、照水匀红。\n但华发衰颜，不堪频鉴青铜。\n相逢。\n行藏休借问，且徘徊、目送飞鸿。\n十年湖海，千里云山，几番残照凄风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6148, '谒金门', '曹勋', '春待去。\n帘外连天飞絮。\n老大心情慵纵步。\n草迷池上路。\n春去不知何处。\n欲问谁能分付。\n但有清阴遮院宇。\n晚莺和暮雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6149, '玉楼春', '曹勋', '昔年曾到神清洞。\n笑领希夷非夙梦。\n看时须到月边乌，养处且论铅与汞。\n土膏仍有黄芽动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6150, '饮马歌', '曹勋', '边头春未到。\n雪满交河道。\n暮沙明残照。\n塞烽云间小。\n断鸿悲。\n陇月低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6151, '长寿仙促拍', '曹勋', '舜德日辉光，正初冬盛期。\n东朝喜、诞生时。\n向彤闱、清净均化有，自然和气。\n长生久视，金殿熙熙。\n宴瑶池。\n衣俱侍、玳筵启。\n花如锦、耀朝晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6152, '长寿仙促拍', '曹勋', '绛阙，正春光到时。\n当人日、诞芳仪。\n向宫壶、雅著徽誉美，懿德无亏。\n深被恩荣，金殿宴嬉。\n气融怡。\n贤均木，宜颂二南诗。\n天心喜、锦筵启。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6153, '浣溪沙', '曹勋', '西苑烟光倚槛新。\n桃花艳艳静无尘。\n照溪红映一天云。\n肯放落红流出水，且寻歌舞赏明春。\n持杯知是洞中人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6154, '浣溪沙', '曹勋', '日上龙城散晓阴。\n琼芳堂下玉成林。\n江梅开未十分深。\n随处锦亭穹帐暖，冷香邀住入衣襟。\n酒肠判断付频斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6155, '酒泉子', '曹勋', '连面霜风。\n野馆山村逢至日，开怀欲酒杯空。\n与谁同。\n一缄来信托飞鸿。\n信里催归无限意，黄昏应是出房栊。\n夜香浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6156, '诉衷情', '曹勋', '人情世态饱经过。\n眼也见来多。\n忙中掉得便去，不是有人唆。\n云似舞，水如歌。\n笑呵呵。\n这回还我，半世偎绥，一味磨跎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6157, '诉衷情', '曹勋', '得抽头处好抽头。\n等待几时休。\n贤且广张四至，我早已优游。\n黄道服，布钱绉。\n煞风流。\n往来熟後，也没惊怕，也没忧愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6158, '朝中措', '曹勋', '酴芳架引繁英。\n香远透帘清。\n更与洛阳花市，一齐移在宫庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6159, '朝中措', '曹勋', '斜斜整整暗江湾。\n蓑笠有无间。\n应与君家却暑，冷看白满群山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6160, '谒金门', '曹勋', '香乍起。\n满院垂垂岩桂。\n未卷珠帘香已至。\n酒杯言笑里。\n叶下茸金繁蕊。\n别是清妍风致。\n更远随人闻细细。\n月华天似水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6161, '谒金门', '曹勋', '春渐至。\n雪染梅梢轻细。\n试路新芜殊可喜。\n冷云闲照水。\n白苎今年不寄。\n最好且寻幽会。\n不怕清寒侵紫绮。\n看灯同晚醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6162, '玉蹀躞・解蹀躞', '曹勋', '雨过池台秋静，桂影凉清昼。\n槁叶喧空，疏黄满堤柳。\n风外残菊枯荷，凭阑一饷，犹喜冷香襟袖。\n少欢偶。\n人道消愁须酒。\n酒又怕醒後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6163, '水调歌头', '曹勋', '江影浮空阔，江水拍天流。\n山藏地秘，伟观须是伟人收。\n闻道烟斜雨暗，还留月底风边，墨客一凝眸。\n阑槛随指顾，江海还生秋。\n绣帘卷，开绮宴，翠香浮。\n邹枚宾从俱咏，韵闲出嘉谋。\n点点群山吴楚，历历三州灯火，潮落没沙鸥。\n老子会心处，应已付南楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6164, '醉思仙', '曹勋', '记华堂。\n对宝台绛蜡，红艳成行。\n乌云髻映，浅浅宫妆。\n江梅媚，生嫩脸，莹素质，自有清香。\n歌喉稳，按镂版缓拍，娇倚银床。\n天外行云驻，轻尘暗落雕梁。\n似晓莺历历，琼韵锵锵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6165, '江神子・江城子', '曹勋', '南丰诗将驻灵江。\n下明光。\n惹天香。\n十雨五风，连岁致丰穰。\n初夏清和才四日，开寿席、宴华堂。\n严宸已奏二南章。\n眷循良。\n比龚黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6166, '满庭芳', '曹勋', '老不求名，心惟耽静，旧缘历过艰难。\n杜门无事，一味放痴顽。\n只藉炉香上彻，与天地、平直交关。\n真人喜，扶晨遣客，时暂下仙班。\n矜怜。\n身已病，九疑夙驾，来顾台山。\n看神超清境，玉炼朱颜。\n为向芝田桂圃，收妙有、与作真丹。\n他年报，冲融朝礼，香火紫云间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6167, '满庭芳', '曹勋', '秋色澄晖，蟾波增莹，桂华宫殿香凝。\n夜凉天半，横管度新声。\n应是齐吹万指，岩谷震、石裂霜清。\n天如水，飞云散尽，江月照还明。\n人间，何处有，祥风缓引，飘下层城。\n想广寒光冷，妙舞轻盈。\n愿上君王万寿，空伫忆、酒海吞鲸。\n归来也，惊涛隐隐，馀韵入青冥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6168, '武陵春', '曹勋', '今岁重阳经闰早，金蕊粲繁枝。\n玉殿珠楼步辇随。\n高兴在东篱。\n且泛金英同潋滟，休与傲霜期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6169, '武陵春', '曹勋', '玉露金风寻胜去，一月看三州。\n红叶黄花满意秋。\n真是巧装愁。\n我在天台山下住，松菊占深幽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6170, '武陵春', '曹勋', '惨惨江云浑不动，玉雪耿孤芳。ピ\n萼绿仙人带暗香。ピ\n风韵冷尤长。ピ\n陇信不来寒日晚，疏影照澄江。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6171, '武陵春', '曹勋', '春到小园春草绿，烟雨湿云山。\n池上梅花已半残。\n无奈晚来寒。\n不怕醉多只怕醒，花影上阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6172, '玉楼春', '曹勋', '九重盛旦薰风候。\n佳气氛氲横永昼。\n眉心烟彩拥群仙，华宴重开同圣后。\n箫韶宫殿锵金奏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6173, '玉楼春', '曹勋', '佳时莫放游鞍倦。\n梅润清薰随处宴。\n不妨一半雨兼风，况对有情莺与燕。\n琼艘百柁花千点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6174, '浪淘沙', '曹勋', '归意逐飞鸿。\n点点书空。\n爱渠南去晓烟中。\n不似老人尘土里，一似痴聋。\n庭院晚来风。\n还过秋客。\n旧时与客绕珍丛。\n有酒不曾无客醉，欢与秋浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6175, '浪淘沙', '曹勋', '秋杪喜新凉。\n烟淡池塘。\n团团岩桂作风光。\n多少水云萧散意，都付芬芳。\n雨逐漏声长。\n小院回廊。\n枕边清梦几悠扬。\n只恐四檐声未断，洗褪幽香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6176, '鹧鸪天', '曹勋', '枫落吴江肃晓霜。\n洞庭波静耿云光。\n芳苞照眼黄金嫩，纤指开新白玉香。\n盐胜雪，喜初尝。\n微酸历齿助新妆。\n直须满劝三山酒，更喜持杯云水乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6177, '鹧鸪天', '曹勋', '准拟中秋快客情。\n新亭雨後喜登临。\n彩蟾特地中宵出，吹散层云十日阴。\n松露重，月烟深。\n祥云捧玉到天心。\n金波动是经年别，为酌金荷醉碧琳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6178, '鹧鸪天', '曹勋', '曾到东风最上头。\n低云阁雨接溪流。\n只应缟袂闺房秀，尚带天香汗漫游。\n当日暇，从贤侯。\n冲寒迎翠小迟留。\n归骖白凤来何处，更指玉霄城畔楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6179, '鹧鸪天', '曹勋', '雪後疏香一两枝。\n高轩乘兴访春时。\n金蕉酌酒应须醉，玉指传觞岂易辞。\n嗟老大，喜追随。\n南楼宵漏任迟迟。\n已闻水部神仙语，更诵骑鲸短李诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6180, '好事近', '曹勋', '花动两山春，绿绕翠围时节。\n雨涨晓来湖面，际天光清彻。\n移尊兰棹压深波，歌吹与尘绝。\n应向断云浓淡，见湖山真色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6181, '好事近', '曹勋', '密密偃蜂房，香远未应时霎。\n薇露紫烟尽，任风欺雪压。\n老人曾饮百川空，相对肯微呷。\n揽取占先风度，醉高烧红蜡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6182, '好事近', '曹勋', '潮尽海波平，赏尽绿烟凉月。\n罗袂乍迎风快，悄喜欢不彻。\n一年好处记如今，朝暮更无热。\n庭院晚来些雨，是开尊时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6183, '胜胜慢・声声慢', '曹勋', '素商吹景，西真赋巧，桂子秋借蟾光。\n层层翠葆，深隐幽艳清香。\n占得秀岩分种，天教薇露染娇黄。\n珍庭晓，透肌破鼻，细细芬芳。\n应是月中倒影，喜馀叶婆娑，灏色迎凉。\n移根上苑，雅称曲槛回廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6184, '一剪梅・一翦梅', '曹勋', '不占前村占宝阶。\n芳影横斜积渐开。\n水边竹外冷摇春，一带冲寒，香满襟怀。\n管领东风要有才。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6185, '御街行', '曹勋', '凌寒架雪知春近。\n闲探处、如相问。\n溪流清浅暮云低，玉蓓横斜风定。\n晚枝雀，幽姿方展，还映疏篁冷。\n镜鸾妆罢明梢嫩。\n犹记宜相并。\n如今却月别传香，知引何人幽兴。\n不堪楼上，昭华吹断，声与愁肠尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6186, '行香子', '曹勋', '也爱休官。\n也爱清闲。\n谢神天、教我愚顽。\n眼前万事，都不相干。\n访好林峦。\n好洞府，好溪山。\n日月如盘。\n缺又还圆。\n自然他、虎踞龙蟠。\n河东上下，一撞三关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6187, '蓦山溪', '曹勋', '乌龙云洞，神护红尘外。\n金鼎养丹砂，有仙卿、清修名世。\n三千功行，活字少人知，松露，紫烟深，知是聃翁裔。\n吹箫後约，岂慕穿青紫。\n八十在人间，比当日、何须指李。\n相逢一笑，酒量海同宽，拔宅隐，玉霄寒，升举应新岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6188, '千秋岁', '曹勋', '洞房秀韵，结绮临春後。\n都压尽，名花柳。\n锦堂笼翡翠，璨枕同清昼。\n谁似得，佳时占断长欢偶。\n我昔闻名久。\n欲见成消瘦。\n寻不遇，空回首。\n征途难驻马，坐想冰姿秀。\n凭寄语，南归更趁酴酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6189, '水龙吟', '曹勋', '冻云阁雨，长风送雪，万里无凝滞。\n斜斜整整，纯白入素，应同太始。\n袁巷萧条，冷光寒透，有人曾至。\n但圆虚上下，澄明莹洁，如□□、混元气。\n时听松篁泻坠。\n任山川、珠联玉缀。\n一尘不染，一毫不现，真空妙治。\n祥应三白，润归多稼，已成丰岁。\n待收拾大翁，茶盐贺喜，兴村东醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6190, '念奴娇', '曹勋', '烘帘昼暖，正飞花堆锦，风迟烟暮。\n绿叶成阴春又老，甲子谁能重数。\n梅已青圆，雪深犹记，曾拈疏枝否。\n须知物外，这些光景常驻。\n闻道江水东头，同门相过，不作儿女语。\n醉墨凌波歌数阕，心迹都忘逆旅。\n胸次扶摇，壶中光景，肯与人同趣。\n栖尘功就，浩然俱待飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6191, '念奴娇', '曹勋', '半阴未雨，洞房深、门掩清润芳晨。\n古鼎金炉，烟细细、飞起一缕轻云。\n罗绮娇春。\n争拢翠袖，笑语惹兰芬。\n歌筵初罢，最宜斗帐黄昏。\n楼上念远佳人。\n心随沈水，学兰俱焚。\n事与人非，争似此、些子香气常存。\n记得临分。\n罗巾馀赠，尽日把浓熏。\n一回开看，一回肠断重闻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6192, '沁园春', '曹勋', '浓绿交阴，脆圆经雨，夏景正新。\n遽紫泥封检，红幢建钺，飘然吹起，一片闲云。\n禁殿趋班，玉音亲诏，并遣皇华通宝邻。\n凌去，任重霄温暑，万里风薰。\n炎曦正斡天钧。\n更午气均齐天地根。\n运至精感化，千和万合，涤堤旁说，必自成真。\n已约归期，秋风前後，梨枣黄花满地匀。\n阊阖晚，待朝元紫府，上达明君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6193, '菩萨蛮', '曹勋', '稽山鉴水无寒暑。\n荷香莲露相倾注。\n堂拟揖樵风。\n山围晚照红。\n桃根随秀叶。\n玉麈频招客。\n客况不言蓬。\n回船逸兴同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6194, '菩萨蛮', '曹勋', '萧萧还是秋容暮。\n炉薰已冷氲香注。\n犹记踏香尘。\n东风满院春。\n冷烟迷望处。\n声断阑干雨。\n无计问行云。\n黄昏空掩门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6195, '菩萨蛮', '曹勋', '花飞零乱随风舞。\n花梢犹带虚檐雨。\n帘幕映黄昏。\n江天日暮云。\n有人楼上望。\n生怕褰虚幌。\n冷落对炉薰。\n一春常怨春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6196, '菩萨蛮', '曹勋', '等闲将度三春景。\n景春三度将闲等。\n愁怕更高楼。\n楼高更怕愁。\n弄花梅已动。\n动已梅花弄。\n梅看几年催。\n催年几看梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6197, '菩萨蛮', '曹勋', '雨昏连夜催炎暑。\n暑炎催夜连昏雨。\n长簟水波凉。\n凉波水簟长。\n翠鬟双倚醉。\n醉倚双鬟翠。\n香枕印红妆。\n妆红印枕香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6198, '菩萨蛮', '曹勋', '玉摇素腰如束。\n束如腰素摇玉。\n宜更醉春期。\n期春醉更宜。\n绣鸳闲永昼。\n昼永闲鸳绣。\n归念不曾稀。\n稀曾不念归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6199, '清平乐', '曹勋', '秋凉破暑。\n暑气迟迟去。\n最喜连日风和雨。\n断送凉生庭户。\n晚来灯火回廊。\n有人新酒初尝。\n且喜薄衾围暖，却愁秋月如霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6200, '清平乐', '曹勋', '一春老病。\n空过春光永。\n药鼎煎炉朝暮景。\n只是医方药性。\n经旬日色云遮。\n山高寒透窗纱。\n常恨檐头倾雨，犹能枕上看花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6201, '清平乐', '曹勋', '赵家燕燕。\n宜在昭阳殿。\n春入馆娃深宫宴。\n秀色从来未见。\n浅颦轻笑都宜。\n临风好是腰肢。\n今夜松江归路，月明愁满清辉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6202, '点绛唇', '曹勋', '怯雨羞云，翠鬟初按檀槽就。\n赏心时候。\n常劝花间酒。\n慢拈轻拢，怨感随纤手。\n胡沙奏。\n几行红袖。\n都道谁家有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6203, '点绛唇', '曹勋', '不厌频来，探梅选胜湖山里。\n瑶林琼蕊。\n真是游方外。\n玉殿珠楼，不并人间世。\n何妨醉。\n都无寒意。\n满坐惟和气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6204, '点绛唇', '曹勋', '有个庵儿，做来不大元非小。\n阳光常照。\n坐卧谁知道。\n炼得丹砂，不是人间灶。\n冲和妙。\n鹤鸣猿啸。\n一任西风老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6205, '点绛唇', '曹勋', '一气冲融，浩然识取生缘处。\n敛归灵府。\n便作真铅柱。\n九任玄归，行处龙先虎。\n山头雨。\n散成清露。\n玛瑙生玄圃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6206, '点绛唇', '曹勋', '石洞清寒，柳烟吹散松风静。\n日华光映。\n翠水环云径。\n道境多闲，不是人间景。\n谈清净。\n道师歌咏。\n花转云房影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6207, '失调名', '曹勋', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6208, '水调歌头', '胡寅', '不见严夫子，寂寞富春山。\n空留千丈危石，高出暮云端。\n想象羊裘披了，一笑两望身世，来插钓鱼竿。\n肯似林间翮，飞倦始知还。\n中兴主，功业就，鬓毛斑。\n驱驰一世人物，相与济时艰。\n独委狂奴心事，未羡痴儿鼎足，放去任疏顽。\n爽气动星斗，终古照林峦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6209, '蓦山溪', '吴舜选', '园林何有，修竹摇苍翠。\n春到小桃蹊，看绿满、一池春水。\n花开日暖，儿侄竞追随，挑野蔌，网溪鱼，有酒多且旨。\n去来聚散，无必亦无意。\n说地或谈天，更休问、语言粗细。\n谁强谁弱，谁是又谁非，过去事，未来事，一枕腾腾睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6210, '西江月', '赵桓', '历代恢文偃武，四方晏粲无虞。\n奸臣招致北匈奴。\n边境年年侵侮。\n一旦金汤失守，万邦不救銮舆。\n我今父子在穹庐。\n壮士忠臣何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6211, '西江月', '赵桓', '塞雁南去，高飞难寄音书。\n只应宗社已丘墟。\n愿有真人为主。\n岭外云藏晓日，眼前路忆平芜。\n寒沙风紧泪盈裾。\n难望燕山归路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6212, '眼儿媚', '赵桓', '宸传三百旧京华。\n仁孝自名家。\n一旦奸邪，倾天拆地，忍听琵琶。\n如今在外多萧索，迤逦近胡沙。\n家邦万里，伶仃父子，向晓霜花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6213, '蓦溪山・蓦山溪', '刘子', '浮烟冷雨，今日还重九。\n秋去又秋来，但黄花、年年如旧。\n平台戏马，无处问英雄，茅舍底，竹篱东，伫立时搔首。\n客来何有。\n草草三杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6214, '满庭芳', '刘子', '秋入微阴，凉生平远，小山愁绝天南。\n似闻还断，飞策遍千岩。\n叶底轻黄纂纂，恼人是、微裂芳缄。\nけ然胜，清真冷淡，无艳寄尘凡。\n澄潭。\n两岸，波光摇动，碧影相参。\n任西风十里，吹度松杉。\n我自寒灰槁木，□神处、不觉醺酣。\n归来晚，飞花无迹，明月满空函。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6215, '南歌子', '刘子', '卜夜容三献，微欢极一时。\n风流太守未庞眉。\n放出笔头光焰、压金闺。\n藻丽花骈蕊，清高雪亚枝。\n曼声恰与贯珠宜。\n听此直教拚得、醉翻卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6216, '南歌子', '刘子', '伎俩无多子，逍遥自许时。\n闲愁且莫著双眉。\n恰有梅香一点、到幽闺。\n宠辱棋翻局，光阴鸟度枝。\n颓然径醉是便宜。\n拟倩潭风吹绿、涨瑶卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6217, '小重山', '何大圭', '绿树莺啼春正浓。\n钗头青杏小，绿成丛。\n玉船风动酒鳞红。\n歌声咽，相见几时重。\n车马去匆匆。\n路随芳草远，恨无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6218, '水调歌头', '何大圭', '今夕出佳月，银汉泻高寒。\n风缠云卷，转觉天陛玉楼宽。\n疑是金华仙子，又喜经年药就，倾出玉团团。\n收拾江河影，都向镜中蟠。\n横霜笛，吹明影，到中天。\n要令四海瞻望，千古此轮安。\n何岁何年无月，唯有谪仙著语，高绝不能攀。\n我欲唤空起，云海路漫漫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6219, '蝶恋花', '何大圭', '鱼尾霞收明远树。\n翠色黏天，一叶迎风举。\n一笑相逢蓬海路。\n人间风月如尘土。\n翦水双眸云鬓吐。\n醉倒天瓢，笑语生香雾。\n此会未阑须记取。\n蟠桃几度吹红雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6220, '浣溪沙', '胡铨', '忽忽春归没计遮。\n百年都似散馀霞。\n持杯聊听浣溪沙。\n但觉暗添双鬓雪，不知落尽一番花。\n东风寒似夜来些。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6221, '转调定风波・定风波', '胡铨', '从古将军自有真。\n引杯看剑坐生春。\n扰扰介鳞何足扫。\n谈笑。\n纶巾羽扇典刑新。\n试问天山何日定。\n伫听。\n雅歌长啸静烟尘。\n解道汾阳是人杰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6222, '转调二郎神・二郎神', '张孝祥', '闷来无那，暗数尽、残更不寐。\n念楚馆香车，吴溪兰棹，多少愁云恨水。\n阵阵回风吹雪霰，更旅雁、一声沙际。\n想静拥孤衾，频挑寒，数行珠泪。\n凝睇。\n傍人笑我，终朝如醉。\n便锦织回鸾，素传双鲤，难写衷肠密意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6223, '满江红', '张孝祥', '秋满蘅皋，烟芜外、吴山历历。\n风乍起，兰舟不住，浪花摇碧。\n离岸橹声惊渐远，盈襟泪颗凄犹滴。\n问此情、能有几人知，新相识。\n追往事，欢连夕。\n经旧馆，人非昔。\n把轻颦浅笑，细思重忆。\n红叶题诗谁与寄，青楼薄幸空遗迹。\n但长洲、茂苑草萋萋，愁如织。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6224, '满江红', '张孝祥', '千古凄凉，兴亡事、但悲陈迹。\n凝望眼、吴波不动，楚山丛碧。\n巴滇绿骏追风远，武昌云旆连江赤。\n笑老奸、遗臭到如今，留空壁。\n边书静，烽烟息。\n通轺传，销锋镝。\n仰太平天子，坐收长策。\n蹙踏扬州开帝里，渡江天马龙为匹。\n看东南、佳气郁葱葱，传千亿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6225, '满江红', '张孝祥', '秋满漓源，瘴云净、晓山如簇。\n动远思、空江小艇，高丘乔木。\n策策西风双鬓底，晖晖斜日朱栏曲。\n试侧身、回首望京华，迷南北。\n思归梦，天边鹄。\n游宦事，蕉中鹿。\n想一年好处，砌红堆绿。\n罗帕分柑霜落齿，冰磐剥芡珠盈掬。\n倩春纤、缕捣香齑，新熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6226, '青玉案', '张孝祥', '红尘冉冉长安路。\n看风度、凝然去。\n唱彻阳关留不住。\n甘棠庭院，芰荷香渚。\n尽是相思处。\n龟鱼从此谁为主。\n好记江湖断肠句。\n万斛离愁休更诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6227, '蓦山溪', '张孝祥', '清都绛阕，我自经行惯。\n璧月带珠星，引钧天、笙箫不断。\n宝簪瑶佩，玉立拱清班。\n天一笑，物皆春，结得清虚伴。\n还丹九转。\n凡骨亲曾换。\n携剑到人间，偶相逢、依然青眼。\n狂歌醉舞，心事有谁知，明月下，好风前，相对纶巾岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6228, '蝶恋花', '张孝祥', '漠漠飞来双属玉。\n一片秋光，染就潇湘绿。\n雪转寒芦花蔌蔌。\n晚风细起波纹。\n落日闲云归意促。\n小倚蓬窗，写作思家曲。\n过尽碧湾三十六。\n扁舟只在滩头宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6229, '蝶恋花', '张孝祥', '恰则杏花红一树，拈指来时，结子青无数。\n漠漠春阴缠柳絮。\n一天风雨将春去。\n春到家山须小住。\n芍药樱桃，更是寻芳处。\n绕院碧莲三百亩。\n留春伴我春应许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6230, '蝶恋花', '张孝祥', '画戟闲刀入鞘。\n安石榴花，影落红栏小。\n似劝先生须饮。\n枕中鸿宝微传妙。\n衮衮锋车还急诏。\n满眼潇湘，总是恩波渺。\n归去槐庭思楚峤。\n觚月晓期分照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6231, '蝶恋花', '张孝祥', '君泛仙槎银海去。\n後日相思，地角天涯路。\n草草杯磐深夜语。\n冥冥四月黄梅雨。\n莫拾明珠并翠羽。\n但使邦人，爱我如慈母。\n待得政成民按堵。\n朝天衣袂翩翩举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6232, '鹧鸪天', '张孝祥', '咏彻琼章夜向阑。\n天移星斗下人间。\n九光倒影腾青简，一气回春绕绛坛。\n瞻北阕，祝南山。\n遥知仙仗簇清班。\n何人曾侍传柑宴，翡翠帘开识圣颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6233, '鹧鸪天', '张孝祥', '子夜封章扣紫清。\n五霞光里佩环声。\n驿传风火龙鸾舞，步入烟宵孔翠迎。\n瑶简重，羽衣轻。\n金童双引到通明。\n三湘五管同民乐，万岁千秋与帝龄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6234, '鹧鸪天', '张孝祥', '忆昔追游翰墨场。\n武夷仙伯较文章。\n琅函奏号银台省，毡笔书名御苑墙。\n经十载，过三湘。\n横楣丽锦照传觞。\n醉馀吐出胸中墨，只欠彭宣到後堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6235, '鹧鸪天', '张孝祥', '月地云阶欢意阑。\n仙姿不合住人间。\n骖鸾已恨车尘远，泣凤空馀烛影残。\n情脉脉，泪珊珊。\n梅花音信隔关山。\n只应楚雨清留梦，不那吴霜绿易斑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6236, '鹧鸪天', '张孝祥', '去日清霜菊满丛。\n归来高柳絮缠空。\n长驱万里山收瘴，径度层波海不风。\n阴得遍，岭西东。\n天教慈母寿无穷。\n遥知今夕称觞处，衣彩还将衣绣同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6237, '鹧鸪天', '张孝祥', '阿母蟠桃不记春。\n长沙星里寿星明。\n金花罗纸新裁诏，贝叶旁行别授经。\n同犬子，祝龟龄。\n天教二老鬓长青。\n明年今日称觞处，更有孙枝满谢庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6238, '鹧鸪天', '张孝祥', '舞凤飞龙五百年。\n尽将锦绣裹山川。\n王家券册诸孙嗣，主第笙歌故国传。\n居玉铉，拥金蝉。\n祗今门户庆蝉联。\n君侯合侍明光殿，且作横槎海上仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6239, '鹧鸪天', '张孝祥', '浴殿西头白玉堂。\n湘江东畔碧玉幢。\n北辰躔次瞻星象，南国山川解印章。\n随步武，谢恩光。\n送公归趣舍人装。\n它年若肯传衣钵，今日应须传寿觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6240, '鹧鸪天', '张孝祥', '昼得游嬉夜得眠。\n农桑欲遍楚山川。\n问看百姓知公否，馀子纷纷定不然。\n思主眷，酌民言。\n与民称寿拜公前。\n只将心与天通处，合住人间五百年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6241, '鹧鸪天', '张孝祥', '割镫难留乘马东。\n花枝争看袅长红。\n衮衣空使斯民恋，绿竹谁歌入相同。\n回武事，致年丰。\n几多遗爱在湘中。\n须知楚水枫林下，不似初闻长乐钟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6242, '鹧鸪天', '张孝祥', '楚楚吾家千里驹。\n老人心事正关渠。\n风流合是阶除玉，爱惜真成掌上珠。\n纡彩绶，荐芳壶。\n老人还醉弟兄扶。\n问将何物为儿寿，付与家传万卷书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6243, '鹧鸪天', '张孝祥', '又向荆州住半年。\n西风催放五湖船。\n来时露菊团金颗，去日池荷叠绿钱。\n斟别酒，扣离弦。\n一时宾从最多贤。\n今宵拼醉花迷坐，後夜相思月满川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6244, '鹧鸪天', '张孝祥', '忆昔彤庭望日华。\n匆匆枯笔梦生花。\n郁轮袍曲惭新奏，风送银湾犯斗槎。\n追往事，甫新瓜。\n飞蓬何事及兰麻。\n一江湘水流馀润，十里河堤筑浅沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6245, '鹧鸪天', '张孝祥', '瞻跸门前识个人。\n柳眉桃脸不胜春。\n短襟衫子新来棹，四直冠儿内样新。\n秋色净，晓妆匀。\n不知何事在风尘。\n主翁若也怜幽独，带取妖饶上玉宸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6246, '虞美人', '张孝祥', '庐敖夫妇骖鸾侣。\n相敬如宾主。\n森然兰玉满尊前。\n举案齐眉乐事、看年年。\n我家白发双垂雪。\n已是经年别。\n今宵归梦楚江滨。\n也学君家儿子、寿吾亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6247, '虞美人', '张孝祥', '雪花一尺江南北。\n薪尽炊无粟。\n老仙活国拭刀圭。\n十万人家生意、与春回。\n天公一笑酬阴德。\n赐与长生籍。\n今朝雪霁寿尊前。\n看我双亲都是、地行仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6248, '虞美人', '张孝祥', '雪消烟涨清江浦。\n碧草春无数。\n江南几树夕阳红。\n点点归帆吹尽、晚来风。\n楼头自昭华管。\n我已无肠断。\n断行双雁向人飞。\n织锦回文空住、寄它谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6249, '虞美人', '张孝祥', '溪西竹榭溪东路。\n溪上山无数。\n小舟却在晚烟中。\n更看萧萧微雨、打疏篷。\n无聊情绪如中酒。\n此意君知否。\n年时曾向此中行。\n有个人人相对、坐调筝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6250, '虞美人', '张孝祥', '柳梢梅萼春全未。\n谁曾伤春意。\n一年好处是新春。\n柳底梅边只欠、那人人。\n凭春约住梅和柳。\n略待些时候。\n锦帆风送彩舟来。\n却遗香包娇叶、一齐开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6251, '虞美人', '张孝祥', '罗衣怯雨轻寒透。\n陡做伤春瘦。\n个人无奈语佳期。\n徙倚黄昏池阁、等多时。\n当初不似休来好。\n来後空烦恼。\n倩人传语更商量。\n只得千金一笑、也甘当。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6252, '鹊桥仙', '张孝祥', '北窗凉透，南窗月上，浴罢满怀风露。\n不知何处有花来，但怪底、清香无数。\n炎州珍产，吴儿未识，天与幽芳独步。\n冰肌玉骨岁寒时，倩间止、堂中留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6253, '鹊桥仙', '张孝祥', '吹香成阵，飞花如雪，不那朝来风雨。\n可怜无处避春寒，但玉立、仙衣数缕。\n清愁万斛，柔肠千结，醉里一时分付。\n与君不用叹飘零，待结子、成阴归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6254, '鹊桥仙', '张孝祥', '横波滴素，遥山蹙翠，江北江南肠断。\n不知何处驭风来。\n云雾里、钗横鬓乱。\n香罗叠恨，蛮笺写意，付与瑶台女伴。\n醉时言语醒时羞，道醒了、休教再看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6255, '鹊桥仙', '张孝祥', '湘江东畔，去年今日，堂上簪缨罗绮。\n弟兄同拜寿尊前，共一笑、欢欢喜喜。\n渚宫风月，边城鼓角，更好亲庭一醉。\n醉时同唱去年词，愿来岁、强如今岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6256, '鹊桥仙', '张孝祥', '南州名酒，北园珍果，都与黄香为寿。\n风流文物是家传，睨血指、旁观袖手。\n东风消息，西山爽气，总聚君家户牖。\n旧时曾识玉堂仙，在帝所、频开荐口。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6257, '鹊桥仙', '张孝祥', '明珠盈斗，黄金作屋，占了湘中秋色。\n金风玉露不胜情，看天上、人间今夕。\n枝头一点，琴心三叠，算有诗名消得。\n野堂从此不萧疏，问何日、尊前唤客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6258, '鹊桥仙', '张孝祥', '黄陵庙下，送君归去，上水船儿一只。\n离歌声断酒杯空，容易里、东西南北。\n重湖风月，九秋天气，冉冉清愁如织。\n我家住在楚江滨，为频寄、双鱼素尺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6259, '鹊桥仙', '张孝祥', '东明大士，吾家老子，是一元知非二。\n共携甘雨趁生朝，做万里、丰年欢喜。\n司空山上，长沙星里，乞与无边祥瑞。\n仙家日月镇常春，笑人说、长生久视。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6260, '南乡子', '张孝祥', '江上送归船。\n风雨排空浪拍天。\n赖有清尊浇别恨，凄然。\n宝蜡烧花看吸川。\n楚舞对湘弦。\n暖响围春锦帐毡。\n坐上定知无俗客，俱贤。\n便是朱张与少连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6261, '画堂春', '张孝祥', '蟠桃一熟九千年。\n仙家春色无边。\n书堂日暖卷非烟。\n昼永风妍。\n看取蔬封汤沐，何妨频棹觥船。\n方瞳绿发对儒仙。\n岁岁尊前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6262, '柳梢青', '张孝祥', '重阳时节。\n满城风雨，更催行色。\n陇树寒轻，海山秋老，清愁如织。\n一杯莫惜留连，我亦是、天涯倦客。\n後夜相思，水长山远，东西南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6263, '柳梢青', '张孝祥', '今年元夕。\n探尽江梅，都无消息。\n草市梢头，柳庄深处，雪花如席。\n一尊邻里相过，也随分、移时换节。\n玉辇端门，红旗夜市、凭君休说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6264, '柳梢青', '张孝祥', '溪南溪北。\n玉香消尽，翠娇无力。\n月淡黄昏，烟横清晓，都无消息。\n无聊更绕空枝，断魂远、重招怎得。\n驿使归来，戍楼吹断，空成凄恻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6265, '踏莎行', '张孝祥', '杨柳东风，海棠春雨。\n清愁冉冉无来处。\n曲径惊飞蛱蝶丛，回塘冻湿鸳鸯侣。\n舞彻霓裳，歌残金缕。\n蘼芜白芷愁烟渚。\n不识阳台梦里云，试听华表归来语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6266, '踏莎行', '张孝祥', '洛下根株，江南栽种。\n天香国色千金重。\n花边三阁建康春，风前十里扬州梦。\n油壁轻车，青丝短。\n看花日日催宾从。\n而今何许定王城，一枝且为邻翁送。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6267, '踏莎行', '张孝祥', '旋葺荒园，初开小径。\n物华还与东风竞。\n曲槛晖晖落照明，高城冉冉孤烟暝。\n柳色金寒，梅花雪静。\n道人随处成幽兴。\n一杯不惜小淹留，归期已理沧浪艇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6268, '踏莎行', '张孝祥', '万里扁舟，五年三至。\n故人相见犹堪喜。\n山阴乘兴不须回，毗耶问疾难为对。\n不药身轻，高谈心会。\n匆匆我又成归计。\n它时江海肯相寻，绿蓑青弱看清贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6269, '踏莎行', '张孝祥', '藕叶池塘，榕阴庭院。\n年时好月今宵见。\n云鬓玉臂共清寒，冰绡雾谁裁剪。\n扑粉口绵，侵尘宝扇。\n遥知掩抑成凄怨。\n去程何许是归程，离觞为我深深劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6270, '踏莎行', '张孝祥', '古屋丛祠，孤舟野渡。\n长年与客分携处。\n漠漠愁阴岭上云，萧萧别意溪边树。\n我已北归，君方南去。\n天涯客里多歧路。\n须君早出瘴烟来，江南山色青无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6271, '踏莎行', '张孝祥', '时雨初晴，诏书随至。\n邦人父老为君喜。\n十年江海始归来，祥曦殿里搀班对。\n日月开明，风云感会。\n切须稳上平戎计。\n天教慈母寿无穷，看君黄发腰金贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6272, '踏莎行', '张孝祥', '桂岭南边，湘江东畔。\n三年两见生申旦。\n知君心地与天通，天教仙骨年年换。\n趁此仙风，乘槎宵汉。\n看看黄纸书来唤。\n但令丹鼎汞频添，莫辞酒盏春无算。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6273, '丑奴儿・采桑子', '张孝祥', '年年有个人生日，谁似君家。\n谁似君家。\n八十慈亲发未华。\n棠阴阁上棠阴满，满劝流霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6274, '丑奴儿・采桑子', '张孝祥', '伯鸾德耀贤夫妇，见说宜家。\n见说宜家。\n庭砌森森长玉华。\n天公遣注长生籍，服日餐霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6275, '丑奴儿・采桑子', '张孝祥', '十年闻说查山好，何日追游。\n木落霜秋。\n梦想云溪不那愁。\n主人好事长留客，尊酒夷犹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6276, '丑奴儿・采桑子', '张孝祥', '十分济楚邦之媛，此日追游。\n雨霁云收。\n梦入潇湘不那愁。\n主人白玉堂中老，曾侍凝旒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6277, '丑奴儿・采桑子', '张孝祥', '珠灯璧月年时节，织手同携。\n今夕谁知，自拈梅花劝一卮。\n逢人问道归来也，日日佳期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6278, '丑奴儿・采桑子', '张孝祥', '无双谁似黄郎子，自郐无讥。\n月满星稀。\n想见歌场夜打围。\n画眉京兆风流甚，应赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6279, '浣溪沙', '张孝祥', '卷旗直入蔡州城。\n只倚精忠不要兵。\n贼营半夜落妖星。\n万旅云屯看整暇，十眉环坐却娉婷。\n白麻早晚下天庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6280, '浣溪沙', '张孝祥', '玉节珠幢出翰林。\n诗书谋帅眷方深。\n威声虎啸复龙吟。\n我是先生门下士，相逢有酒且教斟。\n高山流水遇知音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6281, '浣溪沙', '张孝祥', '绝代佳人淑且真。\n雪为肌骨月为神。\n烛前花底不胜春。\n倚竹袖长寒卷翠，凌波袜小暗生尘。\n十分京落旧家人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6282, '浣溪沙', '张孝祥', '妙手何人为写真。\n只难传处是精神。\n一枝占断洛城春。\n暮雨不堪巫峡梦，西风莫障瘐公尘。\n扁舟湖海要诗人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6283, '浣溪沙', '张孝祥', '腊後春前别一般。\n梅花枯淡水仙寒。\n翠云裘著紫霞冠。\n仙品只今推第一，清香元不是人间。\n为君更拭小龙团。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6284, '浣溪沙', '张孝祥', '宝蜡烧春夜影红。\n梅花枝傍锦薰笼。\n曲琼低卷瑞香风。\n万里江山供燕几，一时宾主看谈锋。\n问君归计莫匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6285, '浣溪沙', '张孝祥', '六客西来共一舟。\n吴儿踏浪剪轻鸥。\n水光山色翠相浮。\n我欲吹箫明月下，略须停棹晚风头。\n从前五度到蕲州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6286, '浣溪沙', '张孝祥', '已是人间不系舟。\n此心元自不惊鸥。\n卧看骇浪与天浮。\n对月只应频举酒，临风何必更搔头。\n暝烟多处是神州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6287, '浣溪沙', '张孝祥', '冉冉幽香解钿囊。\n兰桡烟雨暗春江。\n十分清瘦为箫郎。\n遥忆牙樯收楚缆，应将玉箸点吴妆。\n有人萦断九回肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6288, '浣溪沙', '张孝祥', '楼下西流水拍堤。\n楼头日日望春归。\n雪晴风静燕来迟。\n留得梅花供半额，要将杨叶画新眉。\n莫教辜负早春时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6289, '浣溪沙', '张孝祥', '方舡载酒下江东。\n箫鼓喧天浪拍空。\n万山紫翠映云重。\n拟看岳阳楼上月，不禁石首岸头风。\n作笺我欲问龙公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6290, '浣溪沙', '张孝祥', '罗袜生尘洛浦东。\n美人春梦琐窗空。\n眉山蹙恨几千重。\n海上蟠桃留结子，渥洼天马去追风。\n不须多怨主人公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6291, '浣溪沙', '张孝祥', '一片西飞一片东。\n高情已逐落花空。\n旧欢休问几时重。\n结习正如刀舔蜜，扫除须著絮因风。\n请君持此问龙公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6292, '浣溪沙', '张孝祥', '鹊楼高晚雪融。\n鸳鸯池暖暗潮通。\n郁金黄染柳丝风。\n油壁不来春草绿，栏干倚遍夕阳红。\n江南山色有无中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6293, '浣溪沙', '张孝祥', '妒妇滩头十八姨。\n颠狂无赖占佳期。\n唤它滕六把春欺。\n莺莺并燕燕，凄惶柳柳与梅梅。\n东君独自落便宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6294, '浣溪沙', '张孝祥', '行尽潇湘到洞庭。\n楚天阔处数峰青。\n旗梢不动晚波平。\n红蓼一湾纹缬乱，白鱼双尾玉刀明。\n夜凉船影浸疏星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6295, '浪淘沙', '宋先生', '师指炼金丹。\n牢锁金关。\n工夫进火莫交闲。\n向己澄心观内景，闪电眉间。\n妙用在泥丸。\n神思难看。\n愚迷不悟隔千山。\n悟即如同观返掌，出世何难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6296, '浪淘沙', '宋先生', '铅汞要加添。\n火候频煎。\n体中气足返阳全。\n养就婴儿并姹女，同坐同眠。\n髓实自身坚。\n运满三田。\n刀圭服了得神仙。\n只候功成并行满，独步朝元。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6297, '糖多令・唐多令', '宋先生', '搬载渡黄河。\n金关牢闭锁。\n运九还、须是功多。\n光透帘帏红似火。\n见金钱、万千朵。\n过水涌银波。\n充开牛斗过。\n进工夫、□□蹉跎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6298, '桃源忆故人', '宋先生', '自从师指天机道。\n万卷仙经都晓。\n若会连精归脑。\n颜貌长不老。\n真铅真汞人知少。\n乌兔烹煎成宝。\n身外有身方了。\n玉帝金书召。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6299, '惜黄花', '宋先生', '天机大道。\n达者稀少。\n运戊己、龙蟠更虎绕。\n这一颗丹砂，凡世人难晓。\n间木金、坎离颠倒。\n阳全阴尽，形容不老。\n将水火烹煎，自然炉灶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6300, '阮郎归', '宋先生', '一轮明月照三峰。\n彩霞飞满空。\n分明见我主人公。\n明珠透上宫。\n丹药炼，鼎中红。\n频频要用功。\n功成定是出樊笼。\n闲游仙洞中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6301, '武陵春', '宋先生', '七返阳全阴去尽，精髓满三田。\n修道无为必自然。\n论甚後和先。\n认取五行真水火，须要识根源。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6302, '西江月', '叶适', '识贯事中枢纽，笔开象外精神。\n传观弓力异常钧。\n衣我六铢羞问。\n周后数茎命粒，鲁儒一点芳心。\n啄残栖老付谁论。\n谩要睡馀支枕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6303, '望江南・忆江南', '王', '三杰後，福寿两无涯。\n食乳相君功未既，妩眉京兆眷方兹。\n富贵莫推辞。\n门两戟，却棹一纶丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6304, '水龙吟', '刘褒', '东风初池波，轻阴未放游丝堕。\n新春歌管，丰年笑语，六街灯火。\n绣毂雕鞍，飞尘卷雾，水流云过。\n恍扬州十里，三生梦觉，卷珠箔、映青琐。\n金猊戏掣星桥锁。\n博山香、烟浓百和。\n使君行乐，绛纱万炬，雪梅千朵。\n羯鼓轰空，弦沸晓，樱梢微破。\n想明年更好，传柑侍宴，醉扶狨座。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6305, '雨中花慢', '刘褒', '缥蒂缃枝，玉叶翡英，百梢争赴春忙。\n正雨後、蜂黏落絮，燕扑晴香。\n遗策谁家荡子，唾花何处新妆。\n想流红有恨，拾翠无心，往事凄凉。\n春愁如海，客思翻空，带围只看东阳。\n更那堪、玉笙度曲，翠羽传觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6306, '满庭芳', '刘褒', '柳袅金丝，梨铺香雪，一年春事方中。\n烛前一见，花艳觉羞红。\n枕臂香痕未落，舟横岸、作计匆匆。\n明朝去，暮天平水，双桨碧云东。\n隔离歌一阕，琵琶声断，燕子楼空。\n叹阳台梦杳，行雨无踪。\n後会芙蕖未老，从今去、日望归鸿。\n愁如织，断肠啼，饶舌诉东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6307, '六州歌头', '刘褒', '凭深负阻，蜂舞肆奔腾。\n龙江上，妖氛涨，鲸海外，白波惊。\n羽檄交飞急，玉帐静，金韬，恢远驭，振长樱。\n密分兵。\n细草黄沙渺渺，西关路、风袅高旌。\n听飞霜令肃，坚壁夜无声。\n鼓角何神。\n地中鸣。\n看追风骑，攒云槊，雷野毂，激天钲。\n飞箭集，旄头坠，长围掩，郭东倾。\n振旅观旋凯，笳鼓竞，绣旗明。\n刀换犊，戈藏革，士休营。\n黄色赤云交映，论功何止蔡州平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6308, '水调歌头', '刘褒', '天淡四垂幕，云细不成衣。\n西风扫尽绣翳，凉我鬓边丝。\n破匣菱花飞动，跨海清光无际，草露滴明玑。\n杯到莫停手，何用问来期。\n坐虚堂，揩病眼，溯流辉。\n云山应有幽恨，瑶瑟掩金徽。\n河汉无声自转，玉兔有情亦老，世事巧相违。\n一写谪仙怨，双泪满君颐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6309, '小重山', '章良能', '柳暗花明春事深。\n小阑红芍药，已抽簪。\n雨馀风软碎鸣禽。\n迟迟日，犹带一分阴。\n往事莫沈吟。\n身闲时序好，且登临。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6310, '水调歌头', '熊以宁', '天地有英气，锺秀在人间。\n流虹甫近华旦，维岳预生贤。\n千载明良会遇，三世勋庸忠烈，谁得似家传。\n高论排风俗，抗志遏狂澜。\n记年时，胡尘外，拥朱幡。\n洪枢紫府功业，指日复青毡。\n拭目泥封飞下，趁取梅花消息，去去朝班。\n骨相元不老，何必颂南山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6311, '醉蓬莱', '熊以宁', '渐荷收绿盖，桂吐金英，嫩凉天气。\n香案仙官，向人间游戏。\n道貌孤高，灵扃恬淡，有寿星标致。\n梦得文章，水心谈论，家声相继。\n芙蓉上幕，龙藩胜地。\n剡荐交飞，宸衷简记。\n行趣朝班，便鸾坡螭陛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6312, '鹊桥仙', '熊以宁', '隐君仙裔，帅垣佳配。\n谁似硕人清贵。\n几番鸾诰自天来，森绿绶、彩衣当砌。\n莲开十丈，留十荚，迟十日、瑶池秋至。\n殷勤祝寿指蟠桃，更重数、三千馀岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6313, '失调名', '詹克爱', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6314, '失调名', '詹克爱', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6315, '失调名', '詹克爱', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6316, '齐天乐', '李寅仲', '摩挲阅古堂前柳，尽是世臣乔木。\n故国风流，中兴事业，都写南山修竹。\n商颜自绿。\n甚当日君王，浩歌鸿鹄。\n谁识宫中，有人先定大横卜。\n簪貂更鸣佩玉。\n退朝归较晚，留传黄屋。\n雨露无边，风云在手，宜享长生福。\n神京未复。\n看先取鸿沟，次封函谷。\n岁岁初寒，小桃花下跨青鹿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6317, '长相思', '张', '晴时看。\n雨时看。\n红绿云中驾彩鸾。\n阳台梦未阑。\n咏伊难。\n画伊难。\n服透东皇九转丹。\n光生玉炼颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6318, '梦游仙・戚氏', '张', '骖鸾侣，娇小怯云期。\n柳戏花游能几日，顿抛尘幻学希夷。\n清梦到瑶池。\n霞袂稳，那顾缕金衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6319, '梦游仙・戚氏', '张', '晴昼永，闲步小园中。\n羽帔云轻苍佩响，宝冠星莹绀纱笼。\n波秀浅蛾峰。\n琳洞窈，人静理丝桐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6320, '梦游仙・戚氏', '张', '飞梦去，闲到玉京游。\n尘隔天高那得暑，月明云薄淡於秋。\n宫殿锁金虬。\n冰佩冷，风扬紫绡裘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6321, '梦游仙・戚氏', '张', '归兴动，骑鹤下青冥。\n几点山河浮色界，一簪风露拂寒星。\n银汉悄无声。\n鸾啸舞，仙乐送霓旌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6322, '昭君怨', '张', '拂晓拿舟东去。\n细看荷花垂露。\n红绿总吹香。\n一般凉。\n会享人天清福。\n休把两眉轻蹙。\n谁道做神仙。\n戴貂蝉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6323, '昭君怨', '张', '船过柳湾亭曲。\n万叶圆荷浮绿。\n月照水珠明。\n一池星。\n光透玻璃香蒂。\n梦入藕丝中戏。\n却上小金台。\n罢归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6324, '昭君怨', '张', '月在碧虚中住。\n人向乱荷中去。\n花气杂风凉。\n满船香。\n云被歌声摇动。\n酒被诗情掇送。\n醉里卧花心。\n拥红衾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6325, '霜天晓角', '张', '荷花闲拨。\n撑破玻璃滑。\n拂拂香风微度，吹雪乱、数根发。\n弄泉罗盖匝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6326, '如梦令', '张', '人在骖鸾深院。\n误认落梅疏片。\n零乱舞东风，云淡水平天远。\n帘卷。\n帘卷。\n飞上绣不见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6327, '南乡子', '张', '翠袖怯春寒。\n对雪偏宜傍彩阑。\n弱骨丰肌无限韵，凭肩。\n共看南窗玉数竿。\n羔酒莫留残。\n更觉娇随饮量宽。\n小立妖娇何所似，风前。\n柳絮飞时见牡丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6328, '乌夜啼', '张', '月儿犹未全明。\n乞怜生。\n几片彩云来去、更风轻。\n应见我。\n行又坐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6329, '菩萨蛮', '张', '风流不把花为主。\n多情管定烟和雨。\n潇洒绿衣长。\n满身无限凉。\n文笺舒卷处。\n似索题诗句。\n莫凭小阑干。\n月明生夜寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6330, '菩萨蛮', '张', '前生曾是风流侣。\n返魂却向南枝住。\n疏影卧晴溪。\n恰如沙暖时。\n绿窗娇插鬓。\n依约犹交颈。\n微笑语还羞。\n愿郎同白头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6331, '菩萨蛮', '张', '藤床巧织波文小。\n翻书欲睡莺惊觉。\n绕舍灿明霞。\n短长旌节花。\n此身无系著。\n南北东西乐。\n碧宇朗吟归。\n天风香染衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6332, '折丹桂', '张', '玉为楼观银为地。\n秋到中分际。\n淡金光衬水晶球，上碧虚、千万里。\n香风浩荡吹蟾桂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6333, '清平乐', '张', '苍涯叠嶂。\n有路梯云上。\n忽见地平方数丈。\n坐石风林相向。\n凤膺时作龙声。\n夜深惊动寒星。\n几点光芒欲下，傍人头上来听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6334, '清平乐', '张', '猬房秋熟。\n紫实包黄玉。\n吹叶风高销旧绿。\n疏影半遮茅屋。\n山居未觉全贫。\n园收今岁盈。\n自拨砖炉松火，细煨分饷幽人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6335, '谒金门', '张', '秋淡淡。\n弥望暮天云暗。\n窗小新糊便老眼。\n不应疏酒盏。\n菊净橙香霜晚。\n何处数声来雁。\n飞下湖边红蓼岸。\n有诗方许看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6336, '谒金门', '张', '何许住。\n不属西湖烟雨。\n雪後偏怜香猛处。\n全胜开半树。\n试倩暖云收贮。\n桃杏尽教羞妒。\n只把新词林下去。\n一春休著雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6337, '柳梢青', '张', '一望清溪。\n两堤翠阴，半纸新诗。\n凉满衣裳，香生笔砚，风动窗扉。\n月明撑过船儿。\n载龙玉、双娥对吹。\n竹外山亭，花边水槛，不醉休归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6338, '柳梢青', '张', '烟淡波平。\n蓬松岸蓼，红浅红深。\n满院西风，连宵良月，几处清砧。\n区区宦海浮沈。\n幸隐去、将愁素心。\n两鬓吴霜，一屏秦梦，谁是知音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6339, '柳梢青', '张', '雨後天涯。\n微云送晚，过尽归鸦。\n何处开尊，海棠亭小，飞燕风斜。\n有人粲玉娇花。\n更翳凤、曾游帝家。\n长远身心，温柔情态，不枉多他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6340, '好事近', '张', '手种满阑花，瑞露一枝先坼。\n拄个杖儿来看，两三人门客。\n今朝欢笑且衔杯，休更问明日。\n此意悠然谁会，有湖边风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6341, '诉衷情', '张', '筠笼白雁得时双。\n一自戏回塘。\n冰魂问归何处，明月影中藏。\n苹蓼岸，镇相将。\n忍思量。\n晓昏应是，梦绕江湖，怕见鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6342, '浣溪沙', '张', '无计长留月里花。\n收英巧付火前茶。\n绿尘飞处粉芳华。\n午夜露浓天竺径，一秋香满玉川家。\n扫除残梦入云涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6343, '虞美人', '张', '妆浓未试芙蓉脸。\n却扇凉犹浅。\n粉轻红袅一生娇。\n风外细香时伴、湿云飘。\n双飞属玉来还去。\n谁识幽闲趣。\n莫教疏雨暗黄昏。\n已是不禁秋色、怕销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6344, '玉团儿', '张', '晓来一阵金风劣。\n把阆海、檀霞细屑。\n依就花儿，深藏叶底，不教人折。\n初开数朵谁知得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6345, '眼儿媚', '张', '凄风吹露湿银床。\n凉月到西厢。\n蛩声未苦，桐阴先瘦，愁与更长。\n起来没个人采，枕上越思量。\n眼儿业重，假饶略睡，又且何妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6346, '眼儿媚', '张', '山矾风味木樨魂。\n高树绿堆云。\n水光殿侧，月华楼畔，晴雪纷纷。\n何如且向南湖住，深映竹边门。\n月儿照著，风儿吹动，香了黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6347, '眼儿媚', '张', '玄霜凉夜铸瑶丹。\n飘落翠藤间。\n西风万颗，明珠巧缀，零露初。\n诗人那识风流品，马乳漫堆盘。\n玉纤旋摘，银罂分酿，莫负清欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6348, '南歌子', '张', '种玉能延命，居山易学仙。\n青青一亩自锄烟。\n雾孕云蒸、肌骨更凝坚。\n熟染蜂房蜜，清添石鼎泉。\n雪香酥腻老来便。\n煨芋炉深、却笑祖师禅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6349, '鹧鸪天', '张', '阴阴一架绀云凉。\n袅袅千丝翠蔓长。\n紫玉乳圆秋结穗，水晶珠莹露凝浆。\n相并熟，试新尝。\n累累轻翦粉痕香。\n小槽压就西凉酒，风月无边是醉乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6350, '江城子', '张', '试霜池面浅粼粼。\n鹊飞晴。\n远峰明。\n蓬岛群仙，来过瑞云清。\n龙榜当年人第一，黄叔度，是前生。\n玉堂行见演丝纶。\n彩毫轻。\n思难停。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6351, '江城子', '张', '春风旗鼓石头城。\n急麾兵。\n斩长鲸。\n缓带轻裘，乘胜讨蛮荆。\n蚁聚蜂屯三十万，军面缚，赴行营。\n舳舻千里大江横。\n凯歌声。\n犬羊惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6352, '卜算子', '张', '常记十年前，共醉梅边路。\n别後频收尺素书，依旧情相与。\n早愿却来看，玉照花深处。\n风暖还听柳际莺，休唱闲居赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6353, '杨柳枝', '张', '绿蜡芽疏雪一包。\n绽云梢。\n清香却暑置堂坳。\n晚风飘。\n冰雹无声栖碧叶，笑仍娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6354, '感皇恩', '张', '诗眼看青天，几多虚旷。\n雨过凉生气萧爽。\n白云无定，吹散作、鳞鳞琼浪。\n尚馀星数点，浮空上。\n明月飞来，寒光磨荡。\n仿佛轮间桂枝长。\n倚风归去，纵长啸、一声悠扬。\n乡摇山岳影，秋悲壮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6355, '夜游宫', '张', '鹊相庞儿谁有。\n兀底便、笔描不就。\n小邈如何敢出手。\n细端相，甚精神、甚洗漱。\n到老长厮守。\n不吃饭、也须唧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6356, '醉高楼', '张', '浮云散，天似碧琉璃。\n月正是、上弦时。\n娥蟾兔俱何在，广寒宫殿不应亏。\n这神功，千万世，有谁知。\n甚知解、催人须鬓老。\n更不算、将人情绪恼。\n撺掇酒，撼摇诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6357, '蝶恋花', '张', '杨柳秋千旗斗舞。\n漠漠轻烟，罩定黄鹂语。\n红滴海棠娇半吐。\n燕脂水似朝来雨。\n行过池边携手路。\n都把多情，变作无情绪。\n惟有东风知住处。\n凭君送取温存去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6358, '蝶恋花', '张', '门外沧洲山色近。\n鸥鹭双双，恼乱行云影。\n翠拥高筠阴满径。\n帘垂尽日林堂静。\n明月飞来烟欲暝。\n水面天心，两个黄金镜。\n慢轻摇风不定。\n渔歌乃谁同听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6359, '蝶恋花', '张', '洒面松风凉似水。\n下看冰泉，喷薄溪桥底。\n叠叠层峰相对起。\n家居却在深山里。\n枝上凌霄红绕翠。\n飘下红英，翠影争摇曳。\n今夜岩扉休早闭。\n月明定有飞仙至。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6360, '鹊桥仙', '张', '暑云犹在，澄空欲变，入夜俳徊庭际。\n新秋知是昨宵来，爱残月、纤纤西坠。\n芭蕉老大，流萤衰倦，静里细观天意。\n轻风未有半分凉，奈人道、今宵好睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6361, '鹊桥仙', '张', '连汀接渚，萦蒲带藻，万镜香浮光满。\n湿烟吹霁木栏轻，照波底、红娇翠腕。\n玉纤采处，银笼携去，一曲山长水远。\n采鸳双惯贴人飞，恨南浦、离多梦短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6362, '鹧鸪天', '张', '闲立飞虹远兴长。\n一方云锦荐疏凉。\n翻风翠盖无尘土，出水红妆有艳香。\n携靓侣，泛轻航。\n棹歌惊起野鸳鸯。\n同过清夏看新月，茉莉花园小象床。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6363, '鹧鸪天', '张', '不似琵琶不似琴。\n四弦陶写晋人心。\n指尖历历泉鸣涧，腹上锵锵玉振金。\n天外曲，月边音。\n为君转轴拟秋砧。\n又成雅集相依坐，清致高标记竹林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6364, '临江仙', '张', '七个圈儿为岁数，年年用墨糊涂。\n一圈又剩半圈馀。\n看看云蔽月，三际等空虚。\n纵使古稀真个得，後来争免呜呼。\n肯闲何必更悬车。\n非关轻利禄，自是没工夫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6365, '御街行', '张', '良宵无意贪游玩。\n奈怜友、闲呼唤。\n六街非是少人行，不似旧时风范。\n笙歌零落，绮罗销减，枉了心情看。\n思量往事堪肠断。\n怕频到、帘儿畔。\n朦胧月下却归来，指望阿谁收管。\n低头注定，两汪儿泪，百计难销遣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6366, '满庭芳', '张', '月洗高梧，露幽草，宝钗楼外秋深。\n土花沿翠，萤火坠墙阴。\n静听寒声断续，微韵转、凄咽悲沈。\n争求侣，殷勤劝织，促破晓机心。\n儿时，曾记得，呼灯灌穴，敛步随音。\n任满身花影，犹自追寻。\n携向花堂戏斗，亭台小、笼巧妆金。\n今休说，从渠床下，凉夜伴孤吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6367, '风入松', '张', '小樊标韵称香山。\n压尽花间。\n便须著个楼儿住，彩鸾看、飞舞妖闲。\n珠佩时因醉解，云扉常为春关。\n耳边属付话儿奸。\n休放蛮檀。\n绿窗惟怕今宵梦，莺声巧、春满阑干。\n待把衷肠教与，却愁长远都难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6368, '浣溪沙', '高观国', '魂是湘云骨是兰。\n春风冰玉注芳颜。\n谁招仙子在人间。\n溅水裙儿香雾皱，唾花衫子碧云寒。\n洞箫声绝却骖鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6369, '浣溪沙', '高观国', '偷得韩香惜未烧。\n吹箫人在月明桥。\n草芳似待玉骢骄。\n吹絮绣帘春澹澹，隔香罗帐夜迢迢。\n楚魂须著楚词招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6370, '浣溪沙', '高观国', '云外峰峦翠欲埋。\n雨沾黄叶湿青鞋。\n小惊春色入寒。\n风月愁新空雁字，神仙梦冷忆鸾钗。\n凄凉不是好情怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6371, '浣溪沙', '高观国', '一色烟云澹不消。\n两峰眉黛为谁娇。\n春寒犹占木兰桡。\n燕子似甘愁寂寞，海棠未肯醉妖娆。\n小园嫩约尚萧条。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6372, '兰陵王', '高观国', '凤箫咽。\n花底寒轻夜月。\n兰堂静，香雾翠深，曾与瑶姬恨轻别。\n罗巾泪暗叠。\n情人歌声怨切。\n殷勤意，欲去又留，柳色和愁为重折。\n十年迥凄绝。\n念髻怯瑶簪，衣褪香雪。\n双鳞不渡烟江阔。\n自春来人见，水边花外，羞倚东风翠袖怯。\n正愁恨时节。\n南陌。\n阻金勒。\n甚望断青禽，难倩红叶。\n春愁欲解丁香结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6373, '兰陵王', '高观国', '洒虚阁。\n幂幂天垂似幕。\n春寒峭，吹断万丝，湿影和烟暗帘箔。\n清愁晚来觉。\n佳景过却。\n芳郊外，莺恨燕愁，不管秋千冷红索。\n行云楚台约。\n念今古凝情，朝暮如昨。\n啼红湿翠春情薄。\n谩一犁江上，半篙堤外，勾引轻阴趁暮角。\n正孤绪寂寞。\n斑驳。\n止还作。\n听点点檐声，沈沈春酌。\n只愁入夜东风恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6374, '水龙吟', '高观国', '旧家心绪如云，乍舒乍卷初无定。\n西郊载雨，东城隔雾，还开晴景。\n爱恼花阴，喜移月地，朦胧清影。\n任无心有意，溶溶曳曳，萧散处、有谁问。\n朝暮如今难准。\n枉教他、惜春人恨。\n远峰依旧，前踪何在，有时愁凝。\n此兴飘然，不妨吹断，一川轻暝。\n待良宵，再入高唐梦里，觅巫阳信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6375, '水龙吟', '高观国', '道山玉府真仙，去年再履论思地。\n西清禁域，眷深名重，年高身退。\n玉振金声，水增川涌，德兼才贵。\n爱知章引去，安车稳驾，轩冕付、谈笑外。\n兰玉孙枝竞秀，奉亲欢、莱衣同戏。\n蓬莱东接，苎萝西顾，三山耸翠。\n赐杖清朝，命堂绿野，放怀高致。\n似太公出将，卫公入相，为苍生起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6376, '水龙吟', '高观国', '夜来曾跨青虬，海风袅袅吹襟袖。\n蓬莱误入，群仙争问，刘郎安否。\n玉尘冰壶，日庭星角，孕成奇秀。\n看丹分宝鼎，传秘箧，闻重寄、长生酒。\n归梦惊回晓漏。\n正长庚、辉躔南斗。\n祥开华旦，菊香秋杪，枨黄霜後。\n笔扫龙蛇，句裁螭锦，俊才谁右。\n看功勋绣衮，家声再振，数千龄寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6377, '声声慢', '高观国', '壶天不夜，宝炷生香，光风荡摇金碧。\n月滟冰痕，花外峭寒无力。\n歌传翠帘尽卷，误惊回、瑶台仙迹。\n禁漏促，拼千金一刻，未酬佳夕。\n卷地香尘不断，最得意、输他五陵狂客。\n楚柳吴梅，无限眼边春色。\n鲛绡暗中寄与，待重寻、行云消息。\n乍醉醒，怕南楼、吹断晓笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6378, '隔浦莲・隔浦莲近拍', '高观国', '银湾初霁暮雨。\n鹊赴秋期去。\n浅月窥清夜，凉生一天风露。\n纤巧云暗度。\n河桥路。\n缥缈乘鸾女。\n正容与。\n西厢旧约，玉娇谁见私语。\n柔情不尽，好似冰绡云缕。\n回首天涯又怨阻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6379, '思佳客', '高观国', '入手西风意已羞。\n不须玉斧为重修。\n扑萤凉夜沈沈月，障面清歌澹澹秋。\n休弃置，且迟留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6380, '思佳客', '高观国', '写出梨花雨後晴。\n凝脂洗尽见天真。\n春从翠髻堆边见，娇自红绡脱处生。\n天宝梦，马嵬尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6381, '思佳客', '高观国', '有约湖山却解襟。\n昼眠占得一庭深。\n树边风色寒滋味，愁里年华雁信音。\n惊楚梦，听瑶琴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6382, '思佳客', '高观国', '翦翠衫儿稳四停。\n最怜一曲凤箫吟。\n同心罗帕轻藏素，合字香囊半影金。\n春思悄，昼窗深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6383, '思佳客', '高观国', '不肯楼边著画船。\n载将诗酒入风烟。\n浪花溅白疑飞鹭，荷芰藏红似小莲。\n醒醉梦，唤吟仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6384, '思佳客', '高观国', '白玉楼台知几重。\n夜来望断广寒宫。\n一分乍阙婵娟影，二八尤宜冰雪容。\n云鬓露，玉钗风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6385, '永遇乐', '高观国', '浅晕修娥，脆痕红粉，犹记窥户。\n香断帘空，尘生砌冷，谁唤青鸾舞。\n春风花信，秋宵月约，历历此心曾许。\n衔芳恨、千年怨结，玉骨未应成土。\n木兰艇子，莫愁何在，谩系寒江烟树。\n事逐云沈，情随佩冷，短梦分今古。\n一杯遥夜，孤光难晓，多少碎人肠处。\n空凄黯、西风细雨，尽吹泪去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6386, '玲珑四犯', '高观国', '水外轻阴，做弄得飞云，吹断晴絮。\n驻马桥西，还系旧时芳树。\n不见翠陌寻春，每问著、小桃无语。\n恨燕莺、不识闲情，却隔乱红飞去。\n少年曾识春风意，到如今、怨怀难诉。\n魂惊冉冉江南远，烟草愁如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6387, '御街行', '高观国', '香波半深深院。\n正日上、花阴浅。\n青丝不动玉钩闲，看翠额、轻笼葱茜。\n莺声似隔，篆醒微度，爱横影、参差满。\n那回低挂朱阑畔。\n念闲损、无人卷。\n窥春偷倚不胜情，彷佛见、如花娇面。\n纤柔缓揭，瞥然飞去，不似春风燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6388, '御街行', '高观国', '藤筠巧织花纹细。\n称稳步、如流水。\n踏青陌上雨初晴，嫌怕湿、文鸳双履。\n要人送上，逢花须住，才过处、香风起。\n裙儿挂在帘儿底。\n更不把、窗儿闭。\n红红白白簇花枝，恰称得、寻春芳意。\n归来时晚，纱笼引道，扶下人微醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6389, '霜天晓角', '高观国', '春云粉色。\n春水和云湿。\n试问西湖杨柳，东风外、几丝碧。\n望极。\n连翠陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6390, '霜天晓角', '高观国', '炉烟。\n花露蒸沈液。\n不用宝钗翻炷，闲窗下、袅轻碧。\n醉拍。\n罗袖惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6391, '霜天晓角', '高观国', '霜清水碧。\n冷浸红云湿。\n休说季伦锦帐，山南岸、更花密。\n露滴。\n空翠幂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6392, '眼儿媚', '高观国', '轻云终被断云留。\n不肯放春愁。\n翠楼旧倚，粉墙重见，歌酒风流。\n今朝毕竟吟情澹，芳意未全酬。\n东风向晚，莺花有意，吹转船头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6393, '卜算子', '高观国', '屈指数春来，弹指惊春去。\n檐外蛛丝网落花，也要留春住。\n几日喜春晴，几夜愁春雨。\n十二雕窗六曲屏，题遍伤春句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6394, '西江月', '高观国', '小舫半帘山色，断桥两岸秋阴。\n芙蓉消息已愁深。\n红染云机翠锦。\n几度烟波共酌，半生风月关心。\n飞来鸥鹭是知音。\n一笑歌边醉醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6395, '点绛唇', '高观国', '天外青鸾，几时常向人间住。\n断歌零舞。\n月上桐阴暮。\n憔悴潘郎，不解为花主。\n知何处。\n梦云愁雨。\n怕向西楼去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6396, '点绛唇', '高观国', '钓月蓬闲，载诗却向旗亭醉。\n翠蒲阴外。\n莫放双鸥起。\n水佩仙裳，酒落烟云意。\n来相试。\n玉绡新制。\n要写蓬壶记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6397, '踏莎行', '高观国', '水减堤痕，秋生屐齿。\n瘦筇唤起登高意。\n翠烟微冷梦凄凉，黄花香晚人憔悴。\n怀古风流，悲秋情味。\n紫萸劝入旗亭醉。\n玉人相见说新愁，可怜又湿西风泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6398, '踏莎行', '高观国', '花染烟香，柳摇风翠。\n春工写出清明意。\n翠湾还趁画船开，粉墙到处骄骢系。\n歌唤红裙，酒招青旆。\n吟情又许春风醉。\n何妨日日烂芳游，今宵先向西城睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6399, '恋绣衾', '高观国', '碧梧偷恋小窗阴。\n恨芭蕉、不展寸心。\n暗语近、阳台远，奈秋宵、砧断漏沈。\n月明欲教吹箫去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6400, '风入松', '高观国', '卷帘日日恨春阴。\n寒食新晴。\n马蹄只向南山去，长桥爱、花柳多情。\n红外风娇日暖，翠边水秀山明。\n杜郎歌酒过平生。\n到处蓬瀛。\n醉魂不入重城晚，浓欢寄、桃叶桃根。\n绣被嫩寒清晓，莺声唤醒春酲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6401, '风入松', '高观国', '粉娇曾隔翠帘看。\n横玉声寒。\n夜深不管柔荑冷，樱朱度、香喷云鬟。\n霜月摇摇吹落，梅花簌簌惊残。\n萧郎且放凤箫闲。\n何处骖鸾。\n静听三弄霓裳罢，魂飞断、愁里关山。\n三十六宫天近，念奴却在人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6402, '南乡子', '高观国', '直柱倚冰弦。\n曾见胡儿马上弹。\n却笑琵琶风韵古，溅溅。\n想像湘妃水一帘。\n塞恨曲中传。\n两摺琴丝费玉纤。\n不似江南风月好，厌厌。\n拍手齐看舞袖边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6403, '洞仙歌', '高观国', '轻痕浅晕。\n偷染春风面。\n恰似西施影儿现。\n拟新妆、临槛一段天真，闲态度，长恁香娇玉软。\n从今怀袖里，不暂相离，似笑如颦任舒卷。\n顾芳容不老，只似如今，娇不语、无奈情深意远。\n便雨隔云疏暂分携，也时展丹青，见伊一见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6404, '柳梢青', '高观国', '翠拂晴波，烟垂古岸，灞桥春色。\n斜带鸦啼，乱萦莺梦，愁丝如织。\n为怜张绪风流，正瘦损、宫腰褪碧。\n绽绾同心，留连不住，天涯行客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6405, '少年游', '高观国', '春风吹碧，春云映绿，晓梦入芳。\n软衬飞花，远连流水，一望隔香尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6406, '诉衷情', '高观国', '西楼杨柳未胜烟。\n寒峭落梅天。\n东风渡头波晚，一棹木兰船。\n花态度，酒因缘。\n只春怜。\n屏开山翠，雨怯云娇，尽付愁边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6407, '夜行船', '高观国', '翦水天风吹醉醒。\n高楼外、冻云愁凝。\n袖口香寒，歌喉春暖，不管雁边寒紧。\n琼屑瑶花飞碎影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6408, '满江红', '高观国', '击碎空明，沧浪晚、棹歌飞入。\n西山外、紫霞吹断，赤尘无迹。\n飞上冰轮凉世界，唤回天籁清肌骨。\n看骊珠、影堕冷光斜，蛟龙窟。\n长啸外，纶巾侧。\n轻露下，纤湿。\n听洞箫声在，卧虹阴北。\n十万江妃留醉梦，二三沙鸟惊吟魄。\n任天河、落尽玉杯空，东方白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6409, '酹江月・念奴娇', '高观国', '万岩灵秀，拱崇台飞观，凭陵千尺。\n清磬一声帘幕冷，无复宫娃消息。\n响屉廊空，采香径古，尘土成遗迹。\n石闲松老，断云空锁愁寂。\n专宠谁比轻颦，楚腰吴艳，一笑无颜色。\n风月荒凉罗绮梦，输与扁舟归客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6410, '谒金门', '高观国', '烟墅暝。\n隔断仙源芳径。\n雨歇花梢魂未醒。\n湿红如有恨。\n别後香车谁整。\n怪得画桥春静。\n碧涨平湖三十顷。\n归云何处问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6411, '留春令', '高观国', '断霞低映，小桥流水，一川平远。\n柳影人家起炊烟，彷佛似、江南岸。\n马上东风吹醉面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6412, '留春令', '高观国', '粉绡轻试，绿裙微褪，吴姬娇小。\n一点清香著芳魂，便添起、春怀抱。\n玉脸窥人舒浅笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6413, '留春令', '高观国', '玉清冰瘦，洗妆初见，春风头面。\n等得黄昏月溪寒，爱顾影、临清浅。\n历尽冰霜空羞怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6414, '留春令', '高观国', '玉妃春醉，夜寒吹堕，江南风月。\n一自情留馆娃宫，在竹外、尤清绝。\n贪睡开迟风韵别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6415, '太常引', '高观国', '玉肌轻衬碧霞衣。\n似争驾、翠鸾飞。\n羞问武陵溪，笑女伴、东风醉时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6416, '浪淘沙', '高观国', '啼魄一天涯。\n怨入芳华。\n可怜零血染烟霞。\n记得西风秋露冷，曾浼司花。\n明月满窗纱。\n倦客思家。\n故宫春事与愁赊。\n冉冉断魂招不得，翠冷红斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6417, '意难忘', '高观国', '仙子奇容。\n是名花第一，美占春风。\n烟香笼浅翠，露靓芳红。\n怜舞燕，惜惊鸿。\n想独步吴宫。\n料认得、娇云媚雨，来自巫峰。\n风流正与欢浓。\n羡高楼并倚，曲影阑东。\n烛摇留醉枕，尘坠恋歌钟。\n三弄笛，五花骢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6418, '雨中花・夜行船', '高观国', '旆拂西风，客应星汉，行参玉节征鞍。\n缓带轻裘，争看盛世衣冠。\n吟倦西湖风月，去看北塞关山，过离宫禾黍，故垒烟尘，有泪应弹。\n文章俊伟，颖露囊锥，名动万里呼韩。\n知素有、平戎手段，小试何难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6419, '八归', '高观国', '楚峰翠冷，吴波烟远，吹袂万里西风。\n关河迥隔新愁外，遥怜倦客音尘，未见征鸿。\n雨帽风巾归梦杳，想吟思、吹入飞蓬。\n料恨满、幽苑离宫。\n正愁黯文通。\n秋浓。\n新霜初试，重阳催近，醉红偷染江枫。\n瘦筇相伴，旧游回首，吹帽知与谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6420, '瑞鹤仙', '高观国', '一枝苍玉冷。\n爱露节霜根，从来孤劲。\n提携远尘境。\n自清骨力，岁寒心性。\n登临助兴。\n甚偏与，芒鞋相称。\n笑葛洪、陂外腾飞，渺渺水闲烟迥。\n寻胜。\n拨开林影，斫破苔痕，缓支幽径。\n分云度岭。\n待随处、问梅信。\n任香挑村醑，寒拖夜月，识尽江山好景。\n扣禅关拗折，归来万缘自静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6421, '蝶恋花', '魏了翁', '又见王正班玉瑞。\n霁月光风，恰与元宵际。\n横玉一声天似水。\n阳春到处皆生意。\n十载奔驰今我里。\n昔□元非，未信今皆是。\n风月惺惺人自醉。\n却将醉眼看荣悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6422, '水调歌头', '魏了翁', '江水自石纽，灌口怒腾辉。\n便如黑水北出，迤逦到三危。\n百尺长虹夭矫，两岸苍龙偃蹇，翠碧互因依。\n古树百夫长，修竹万竿旗。\n画堂开，风与月，巧相随。\n史君领客行乐，旌纛立披披。\n慨想二江遗迹，更起三闾忠愤，此日最为宜。\n推本美功意，禹甸六章诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6423, '水调歌头', '魏了翁', '轻露沦残暑，蟾影插高寒。\n团团只似前夕，持向老莱看。\n九帙元开父算，六甲更逢儿换，梧竹拥檀栾。\n都把方寸地，散作万云烟。\n锦边城，云间戌，雪中山。\n风流老监在此，忧顾赖渠宽。\n天上玉颜合笑，堂上酡颜如酒，家国两平安。\n又恐玉川子，茗碗送飞翰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6424, '水调歌头', '魏了翁', '风露浸秋色，烟雨媚湖弦。\n旌旗十里小队，拟约醮坛仙。\n身在黄旗朱邸，名在玉皇香案，底事个人传。\n正恐未免耳，惊搅日高眠。\n虎分符，龙握节，鹿御。\n於君本亦馀事，所乐不存焉。\n一点春风和气，无限蓝田种子，渺渺玉生烟。\n富贵谁不肯，借问此何缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6425, '水调歌头', '魏了翁', '万里蜀山险，难似上青天。\n谁知间有，人心之险甚山川。\n赖得皇华星使，满载春风和气，来自鉴湖边。\n要识方寸地，四十万云烟。\n佩珑璁，冠昱炝，组蝉联。\n眼前富贵馀事，所乐不存焉。\n闻道汉家子政，博考兰台载籍，胸次著千年。\n会有太一老，同结海山缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6426, '念奴娇', '魏了翁', '万人遮道，拨不断、争挽房湖逐客。\n臣罪既盈应九死，全荷君王矜恻。\n况是当年，曾将愚技，十字街头立。\n恩波浩荡，孤忠未报涓滴。\n世事应若穿杨，一弦不到，前发皆虚的。\n自判此生元有分，不管筮违龟食。\n靴帽丛中，渔樵席上，无入非吾得。\n倚湖一笑，夜深群动皆息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6427, '临江仙', '魏了翁', '九十秋光三十八，新居初度称觞。\n青衫彩服列郎娘。\n孙枝无处著，犹欠两东床。\n尽是当年亲手种，如今满院芬芳。\n只凭方寸答苍苍。\n个中无尽藏，谁弱又谁强。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6428, '临江仙', '魏了翁', '细雨斜风驱晓瘴，绰开坦坦长途。\n膏车秣马问程初。\n梅梢迎候骑，雁影度平芜。\n行己不论官小大，穷探不间精粗。\n只从厚处作规模。\n简编迂事业，屋漏拙功夫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6429, '感皇恩', '魏了翁', '三峡打头风，吹回荆步。\n坎止流行谩随遇。\n须臾风静，重踏西来旧武。\n世间忧喜地，分明觑。\n喜事虽新，忧端依旧，徒为岷峨且欢舞。\n阴云掩映，天末扣阍无路。\n一鞭归去也，鸥为侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6430, '水龙吟', '魏了翁', '阑风长雨连霄，昨朝晴色随轩骤。\n松声花气，江烟浦树，如相迎候。\n山送青来，僧随麦去，山为吾有。\n更筇直上，薜萝深处，云垂幄、藓成。\n未至相如独後。\n对山尊、劝酬多又。\n记曾犯雪，重来已是，绿肥红瘦。\n好语时闻，忧端未歇，倚风搔首。\n谩持觞自慰，冰山安在，此山如旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6431, '满江红', '魏了翁', '玉质金相，长自守、间庭暗室。\n对黄昏月冷，朦胧雾。\n知我者希常我贵，於人不即而人即。\n彼云云、谩自怨灵均，伤兰植。\n乱，春芳寂。\n络纬叫，池英摘。\n惟国香耐久，素秋同德。\n既向静中观性分，偏於发处知生色。\n待到头、声臭两无时，真闻识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6432, '水调歌头', '魏了翁', '世界要扶助，人物载耆英。\n茫茫四海，谁识今代有宠臣。\n万顷青湖佳气，一片紫岩心事，天付与斯人。\n耸耸铁冠吏，表表白云卿。\n海沮漳，城汉郢，宅峨岷。\n规摹妙处，胸次纳纳几沧瀛。\n未说令公二纪，先看武公百岁，年与学俱新。\n星弁百僚准，天宇四时春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6433, '南乡子', '魏了翁', '万里载浮名。\n忆昔从容下帝京。\n冉冉七年如昨梦，分明。\n赢得存存夜气清。\n谁使滥专城。\n有罪当诛尚薄刑。\n细数当时同省士，皆卿。\n落落韶阳独九龄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6434, '水调歌头', '魏了翁', '冬至子之半，玉管罅微阳。\n壶中别有天地，转觉日增长。\n一样金章紫服，一样朱颜绿发，翁季俨相望。\n翁是修何行，未已且方将。\n玉生烟，兰竞秀，彩成行。\n翁无他智，只把一念答苍苍。\n今日列城桃李，他日八荒雨露，都是乃翁庄。\n要数义方训，不说窦家郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6435, '临江仙', '魏了翁', '尚忆去年称寿日，彩衣犹带天香。\n今年还见雁成行。\n两头娘子拜，笑领伯仁觞。\n知是几年培植底，如今满院芬芳。\n只凭方寸答苍苍。\n春风来不断，点缀艳阳妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6436, '水调歌头', '魏了翁', '曾向君王说，臣愿守嘉州。\n风流别乘初届，元在越王楼。\n湖上龟鱼何事，桥上雁犀谁使，争挽海山舟。\n便遣旧姻娅，解后作斯游。\n晚风清，初暑涨，暮云收。\n公堂高会，恍疑仙女下罗浮。\n好是中郎有女，况是史君有妇，同对藕花洲。\n拟把鹤山月，换却鉴湖秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6437, '临江仙', '魏了翁', '腰著万钉犀玉夸，肘垂斗大金章。\n非关性分总寻常。\n要知真乐处，彩服鬓毛苍。\n浩荡春风生玉树，蒸成满院芬芳。\n斗城无处著韶光。\n会归天上去，长捧伯仁觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6438, '水调歌头', '魏了翁', '有匪碧岩使，满腹鉴湖秋。\n不居上界官府，来作散仙游。\n长佩高冠人伟，组练锦袍官贵，清献旧风流。\n杓柄长多少，洗尽蜀民愁。\n冠，貂尾案，鹭鸶。\n时来正恐不免，留滞剑南州。\n帘卷西州风雨，庭伫百城歌鼓，桃李翠云绸。\n谁谓蜀山远，只在殿山头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6439, '贺新郎', '魏了翁', '家住峨山趾。\n暑风轻、双泉漱玉，五坡攒翠。\n坡上主人归无计。\n梦泛沧波清。\n曾拜奏、前旒十二。\n愿上皇华将亲去，及翁儿、未老相扶曳。\n乘款段，过闾里。\n玺书未报人相谓。\n倚西风、胡尘涨野，隐忧如猬。\n就似东门贤父子，祗恐荣亲犹未。\n待洗尽、岷峨憔悴。\n便把手中长杓柄，为八荒，更作无边施。\n却上表，乞归侍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6440, '鹧鸪天', '魏了翁', '十载交盟可重寻。\n剩於棠茇细论心。\n云障晚日供秋思，风递荷书作晚阴。\n纡胜引，豁尘襟。\n未须紫马去。\n玻璃无计留君住，但乞天公三日霖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6441, '倒犯', '吴文英', '茂苑、共莺花醉吟，岁华如许。\n江湖夜雨。\n传书问、雁多幽阻。\n清溪上，惯来往扁舟、轻如羽。\n到兴懒归来，玉冷耕云圃。\n按琼箫，赋金缕。\n回首词场，动地声名，春雷初启户。\n枕水卧漱石，数间屋，梅一坞。\n待共结、良朋侣。\n载清尊、随花追野步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6442, '花犯', '吴文英', '翦横枝，清溪分影，修然空镜晓。\n小窗春到。\n怜夜冷孀娥，相伴孤照。\n古苔泪锁霜千点，苍华人共老。\n料浅雪、黄昏驿路，飞香遗冻草。\n行云梦中认琼娘，冰肌瘦，窈窕风前纤缟。\n残醉醒，屏山外、翠禽声小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6443, '花犯', '吴文英', '小娉婷，清铅素靥，蜂黄暗偷晕。\n翠翘鬓。\n昨夜冷中庭，月下相认。\n睡浓更苦凄风紧。\n惊回心未稳。\n送晓色、一壶葱，才知花梦准。\n湘娥化作此幽芳，凌波路，古岸云沙遗恨。\n临砌影，寒香乱、冻梅藏韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6444, '蝶恋花', '吴文英', '北斗秋横云髻影。\n莺羽衣轻，腰减青丝剩。\n一曲游仙闻玉磬。\n月华深院人初定。\n十二阑干和笑凭。\n风露生寒，人在莲花顶。\n睡重不知残酒醒。\n红帘几度啼鸦暝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6445, '蝶恋花', '吴文英', '明月枝头香满路。\n几日西风，落尽花如雨。\n倒照秦眉天镜古。\n秋明白鹭双飞处。\n自摘霜葱宜荐俎。\n可惜重阳，不把黄花与。\n帽堕笑凭纤手取。\n清歌莫送秋声去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6446, '浣溪沙', '吴文英', '新梦游仙驾紫鸿。\n数家灯火灞桥东。\n吹箫楼外冻云重。\n石瘦溪根船宿处，月斜梅影晓寒中。\n玉人无力倚东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6447, '浣溪沙', '吴文英', '冰骨清寒瘦一枝。\n玉人初上木兰时。\n懒妆斜立澹春姿。\n月落溪穷清影在，日长春去画帘垂。\n五湖水色掩西施。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6448, '浣溪沙', '吴文英', '千盖笼花斗胜春。\n东风无力扫香尘。\n尽沿高阁步红云。\n闲里暗牵经岁恨，街头多认旧年人。\n晚钟催散又黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6449, '浣溪沙', '吴文英', '蝶粉蜂黄大小乔。\n中庭寒尽雪微销。\n一般清瘦各无聊。\n窗下和香封远讯，墙头飞玉怨邻箫。\n夜来风雨洗春娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6450, '浣溪沙', '吴文英', '门隔花深梦旧游。\n夕阳无语燕归愁。\n玉纤香动小帘钩。\n落絮无声春堕泪，行云有影月含羞。\n东风临夜冷於秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6451, '浣溪沙', '吴文英', '波面铜花冷不收。\n玉人垂钓理纤钩。\n月明池阁夜来秋。\n江燕话归成晓别，水花红减似春休。\n西风梧井叶先愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6452, '浣溪沙', '吴文英', '门巷深深小画楼。\n阑干曾识凭春愁。\n新蓬遮却绣鸳游。\n桃观日斜香掩户，苹溪风起水东流。\n紫萸玉腕又逢秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6453, '浣溪沙', '吴文英', '曲角深帘隐洞房。\n正嫌玉骨易愁黄。\n好花偏占一秋香。\n夜气清时初傍枕，晓光分处未开窗。\n可怜人似月中孀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6454, '玉楼春', '吴文英', '茸茸狸帽遮梅额。\n金蝉罗翦胡衫窄。\n乘肩争看小腰身，倦态强随闲鼓笛。\n问称家住城东陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6455, '玉楼春', '吴文英', '华堂夜宴连清晓。\n醉里笙歌云窈袅。\n酿来千日酒初尝，过却重阳秋更好。\n阿儿早晚成名了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6456, '点绛唇', '吴文英', '推枕南窗，拣花寒入单纱浅。\n雨帘不卷。\n空碍调雏燕。\n一握柔葱，香染榴巾汗。\n音尘断。\n画罗闲扇。\n山色天涯远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6457, '点绛唇', '吴文英', '时霎清明，载花不过西园路。\n嫩阴绿树。\n正是春留处。\n燕子重来，往事东流去。\n征衫贮。\n旧寒一缕。\n泪湿风帘絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6458, '点绛唇', '吴文英', '卷尽愁云，素娥临夜新梳洗。\n暗尘不起。\n酥润凌波地。\n辇路重来，仿佛灯前事。\n情如水。\n小楼熏被。\n春梦笙歌里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6459, '秋蕊香', '吴文英', '宝月惊尘堕晓。\n愁锁空枝斜照。\n古苔几点露萤小。\n销减秋光旋少。\n佩丸尚忆春酥袅。\n故人老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6460, '秋蕊香', '吴文英', '懒浴新凉睡早。\n雪靥酒红微笑。\n倚楼起把绣针小。\n月冷波光梦觉。\n怕闻井叶西风到。\n恨多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6461, '诉衷情', '吴文英', '阴阴绿润暗啼鸦。\n陌上断香车。\n红云深处春在，飞出建章花。\n春此去，那天涯。\n几烟沙。\n忍教芳草，狼藉斜阳，人未归家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6462, '诉衷情', '吴文英', '柳腰空舞翠裙烟。\n尽日不成眠。\n花尘浪卷清昼，渐变晚阴天。\n吴社水，系游船。\n又经年。\n东风不管，燕子初来，一夜春寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6463, '诉衷情', '吴文英', '片云载雨过江鸥。\n水色澹汀洲。\n小莲玉惨红怨，翠被又经秋。\n凉意思，到南楼。\n小帘钩。\n半窗灯晕，几叶芭蕉，客梦床头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6464, '诉衷情', '吴文英', '西风吹鹤到人间。\n凉月满缑山。\n银河万里秋浪，重载客槎还。\n河汉女，巧云鬟。\n夜阑干。\n钗头新约，针眼娇颦，楼上秋寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6465, '夜游宫', '吴文英', '窗外捎溪雨响。\n映窗里、嚼花灯冷。\n浑似潇湘系孤艇。\n见幽仙，步凌波，月边影。\n香苦欺寒劲。\n牵梦绕、沧涛千顷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6466, '夜游宫', '吴文英', '春语莺迷翠柳，烟隔断、晴波远岫。\n寒压重帘幔拖绣。\n袖炉香，倩东风，与吹透。\n花讯催时候。\n旧相思、偏供闲昼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6467, '醉桃源・阮郎归', '吴文英', '金丸一树带霜华。\n银台摇艳霞。\n烛阴树影两交加。\n秋纱机上花。\n飞醉笔，驻吟车。\n香深小隐家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6468, '醉桃源・阮郎归', '吴文英', '沙河塘上旧游嬉。\n卢郎年少时。\n一声长笛月中吹。\n和云和雁飞。\n惊物换，叹星移。\n相看两鬓丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6469, '醉桃源・阮郎归', '吴文英', '青春花姊不同时。\n凄凉生较迟。\n艳妆临水最相宜。\n风来吹秀漪。\n惊旧事，问长眉。\n月明仙梦回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6470, '醉桃源・阮郎归', '吴文英', '翠阴浓合晓莺堤。\n春如日坠西。\n画图新展远山齐。\n花深十二梯。\n风絮晚，醉魂迷。\n隔城闻马嘶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6471, '如梦令', '吴文英', '春在绿窗杨柳。\n人与流莺俱瘦。\n眉底暮寒生，帘额时翻波皱。\n风骤。\n风骤。\n花径啼红满袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6472, '如梦令', '吴文英', '秋千争闹粉墙。\n闲看燕紫莺黄。\n啼到绿阴处，唤回浪子闲忙。\n春光。\n春光。\n正是拾翠寻芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6473, '望江南・忆江南', '吴文英', '衣白苎，雪面堕愁鬟。\n不识朝云行雨处，空随春梦到人间。\n留向画图看。\n慵临镜，流水洗花颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6474, '望江南・忆江南', '吴文英', '松风远，莺燕静幽坊。\n妆褪宫梅人倦绣，梦回春草日初长。\n瓷碗试新汤。\n笙歌断，情与絮悠扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6475, '定风波', '吴文英', '密约偷香□蹋青。\n小车随马过南屏。\n回首东风销鬓影。\n重省。\n十年心事夜船灯。\n离骨渐尘桥下水，到头难灭景中情。\n两岸落花残酒醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6476, '月中行・月宫春', '吴文英', '疏桐翠井早惊秋。\n叶叶雨声愁。\n灯前倦客老貂裘。\n燕去柳边楼。\n吴宫寂寞空烟水，浑不认、旧采菱洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6477, '虞美人', '吴文英', '背庭缘恐花羞坠。\n心事遥山里。\n小帘愁卷月笼明。\n一寸秋怀、禁得几蛩声。\n井梧不放西风起。\n供与离人睡。\n梦和新月未圆时。\n起看檐蛛结网、又寻思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6478, '菩萨蛮', '吴文英', '落花夜雨辞寒食。\n尘香明日城南陌。\n玉靥湿斜红。\n泪痕千万重。\n伤春头竟白。\n来去春如客。\n人瘦绿阴浓。\n日长帘影中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6479, '菩萨蛮', '吴文英', '绿波碧草长堤色。\n东风不管春狼藉。\n鱼沫细痕圆。\n燕泥花唾乾。\n无情牵怨抑。\n画舸红楼侧。\n斜日起凭阑。\n垂杨舞晓寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6480, '贺新郎', '吴文英', '湖上芙蓉早。\n向北山、山深雾冷，更看花好。\n流水茫茫城下梦，空指游仙路杳。\n笑萝障、云屏亲到。\n雪玉肌肤春温夜，饮湖光、山渌成花貌。\n临涧水，弄清照。\n著愁不尽宫眉小。\n听一声、相思曲里，赋情多少。\n红日阑干鸳鸯枕，那枉裙腰褪了。\n算谁识、垂杨秋袅。\n不是秦楼无缘分，点吴霜、羞带簪花帽。\n但酒，任天晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6481, '贺新郎', '吴文英', '浪影龟纹皱。\n蘸平烟、青红半湿，枕溪窗牖。\n千尺晴霞慵卧水，万叠罗屏拥绣。\n漫几度、吴船回首。\n归雁五湖应不到，问苍茫、钓雪人知否。\n樵唱杳，度深秀。\n重来趁得花时候。\n记留连、空山夜雨，短亭春酒。\n桃李新栽成蹊处，尽是行人去後。\n但东阁、官梅清瘦。\n乃一声山水绿，燕无言、风定垂帘昼。\n寒正悄，吟袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6482, '江城梅花引', '吴文英', '江头何处带春归。\n玉川迷。\n路东西。\n一雁不飞、雪压冻云低。\n十里黄昏成晓色，竹根篱。\n分流水、过翠微。\n带书傍月自锄畦。\n苦吟诗。\n生鬓丝。\n半黄烟雨，翠禽语、似说相思。\n惆怅孤山、花尽草离离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6483, '婆罗门引', '吴文英', '香霏泛酒，瘴花初洗玉壶冰。\n西风乍入吴城。\n吹彻玉笙何处，曾说董双成。\n奈司空经惯，未畅高情。\n瑶台几层。\n但梦绕、曲阑行。\n空忆双蝉□翠，寂寂秋声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6484, '婆罗门引', '吴文英', '风涟乱翠，酒霏飘汗洗新妆。\n幽情暗寄莲房。\n弄雪调冰重会，临水暮追凉。\n正碧云不破，素月微行。\n双成夜笙，断旧曲、解明。\n别有红娇粉润，初试霓裳。\n分莲调郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6485, '祝英台近', '吴文英', '黯春阴，收灯後，寂寞几帘户。\n一片花飞，人驾彩云去。\n应是蛛网金徽，拍天寒水，恨声断、孤鸿洛浦。\n对君诉。\n团扇轻委桃花，流红为谁赋。\n□□□□，从今醉何处。\n可怜憔悴文园，曲屏春到，断肠句、落梅愁雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6486, '祝英台近', '吴文英', '问流花，寻梦草，云暖翠微路。\n锦雁峰前，浅约昼行处。\n不教嘶马飞春，一奁越境，那销尽、红吟绿赋。\n送人去。\n长丝初染柔黄，晴和晓烟舞。\n心事偷占，莺漏汉宫语。\n趁得罗盖天香，归来时候，共留取、玉阑春住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6487, '祝英台近', '吴文英', '采幽香，巡古苑，竹冷翠微路。\n斗草溪根，沙印小莲步。\n自怜两鬓清霜，一年寒食，又身在、云山深处。\n昼闲度。\n因甚天也悭春，轻阴便成雨。\n绿暗长亭，归梦趁风絮。\n有情花影阑干，莺声门径，解留我、霎时凝伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6488, '祝英台近', '吴文英', '晚云开，朝雪霁，时节又灯市。\n夜约遗香，南陌少年事。\n笙箫一片红云，飞来海上，绣帘卷、缃桃春起。\n旧游地。\n素蛾城阙年年，新妆趁罗绮。\n玉练冰轮，无尘浣流水。\n晓霞红处啼鸦，良宵一梦，画堂正、日长人睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6489, '祝英台近', '吴文英', '翦红情，裁绿意，花信上钗股。\n残日东风，不放岁华去。\n有人添烛西窗，不眠侵晓，笑声转、新年莺语。\n旧尊俎。\n玉纤曾擘黄柑，柔香系幽素。\n归梦湖边，还迷镜中路。\n可怜千点吴霜，寒销不尽，又相对、落梅如雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6490, '西子妆慢・西子妆', '吴文英', '流水曲尘，艳阳醅酒，画舸游情如雾。\n笑拈芳草不知名，乍凌波、断桥西堍。\n垂杨漫舞。\n总不解、将春系住。\n燕归来，问彩绳纤手，如今何许。\n欢盟误。\n一箭流光，又趁寒食去。\n不堪衰鬓著飞花，傍绿阴、冷烟深树。\n玄都秀句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6491, '江南春・秋风清', '吴文英', '风响牙签，云寒古砚，芳铭犹在棠笏。\n秋床听雨，妙谢庭、春早吟笔。\n城市喧鸣辙。\n清溪上、小山秀洁。\n便向此。\n搜松访石，葺屋营花，红尘远避风月。\n瞿塘路，随汉节。\n记羽扇纶巾，气凌诸葛。\n青天万里，料漫忆、莼丝鲈雪。\n车马从休歇。\n荣华事、醉歌耳熟。\n天与此翁，芳芷嘉名，纫兰佩兮琼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6492, '梦芙蓉', '吴文英', '西风摇步绮。\n记长堤骤过，紫骝十里。\n断桥南岸，人在晚霞外。\n锦温花共醉。\n当时曾共秋被。\n自别霓裳，应红销翠冷，霜枕正慵起。\n惨澹西湖柳底。\n摇荡秋魂，夜月归环佩。\n画图重展，惊忍旧梳洗。\n去来双翡翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6493, '高山流水', '吴文英', '素弦一一起秋风。\n写柔情、都在春葱。\n徽外断肠声，霜霄暗落惊鸿。\n低颦处、翦绿裁红。\n仙郎伴、新制还赓旧曲，映月帘栊。\n似名花并蒂，日日醉春浓。\n吴中。\n空传有西子，应不解、换徵移宫。\n兰蕙满襟怀，唾碧总喷花茸。\n後堂深、想费春工。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6494, '霜花腴', '吴文英', '翠微路窄，醉晚风、凭谁为整冠。\n霜饱花腴，烛消人瘦，秋光作也都难。\n病怀强宽。\n恨雁声、偏落歌前。\n记年时、旧宿凄凉，暮烟秋雨野桥寒。\n妆靥鬓英争艳，度清商一曲，暗坠金蝉。\n芳节多阴，兰情稀会，晴晖称拂吟笺。\n更移画船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6495, '澡兰香', '吴文英', '盘丝系腕，巧篆垂簪，玉隐绀纱睡觉。\n银瓶露井，彩云窗，往事少年依约。\n为当时、曾写榴裙，伤心红绡褪萼。\n黍梦光阴渐老，汀洲烟箬。\n莫唱江南古调，怨抑难招，楚江沈魄。\n薰风燕乳，暗雨梅黄，午镜澡兰帘幕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6496, '玉京谣', '吴文英', '蝶梦迷清晓，万里无家，岁晚貂裘敝。\n载取琴书，长安闲看桃李。\n烂绣锦、人海花场，任客燕、飘零谁记。\n春风里。\n香泥九陌，文梁孤垒。\n微吟怕有诗声翳。\n镜慵看、但小楼独依。\n金屋千娇，从他鸳暖秋被。\n蕙帐移、烟雨孤山，待对影、落梅清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6497, '探芳新', '吴文英', '九街头，正软尘润酥，雪销残溜。\n禊赏祗园，花艳云阴笼昼。\n层梯峭空麝散，拥凌波、萦翠袖。\n叹年端、连环转，烂漫游人如绣。\n肠断回廊伫久。\n便写意溅波，传愁蹙岫。\n渐没飘鸿，空惹闲情春瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6498, '凤池吟', '吴文英', '万丈巍台，碧罘外，衮衮野马游尘。\n旧文书几阁，昏朝醉暮，覆雨翻云。\n忽变清明，紫垣敕使下星辰。\n经年事静，公门如水，帝甸阳春。\n长安父老相语，几百年见此，独驾冰轮。\n又凤鸣黄幕，玉霄平溯，鹊锦新恩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6499, '暗香', '吴文英', '县花谁葺。\n记满庭燕麦，朱扉斜阖。\n妙手作新，公馆青红晓云湿。\n天际疏星趁马，帘昼隙、冰弦三叠。\n尽换却、吴水吴烟，桃李靓春靥。\n风急。\n送帆叶。\n正雁水夜清，卧虹平帖。\n软红路接。\n涂粉闱深早催入。\n怀暖天香宴果，花队簇、轻轩银蜡。\n更问讯、湖上柳，两堤翠匝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6500, '暗香疏影', '吴文英', '占春压一。\n卷峭寒万里，平沙飞雪。\n数点酥钿，凌晓东风□吹裂。\n独曳横梢瘦影，入广平、裁冰词笔。\n记五湖、清夜推篷，临水一痕月。\n何逊扬州旧事，五更梦半醒，胡调吹彻。\n若把南枝，图入凌烟，香满玉楼琼阙。\n相将初试红盐味，到烟雨、青黄时节。\n想雁空、北落冬深，澹墨晚天云阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6501, '念奴娇', '吴文英', '思生晚眺，岸乌纱平步，春云层绿。\n罨画屏风开四面，各样莺花结束。\n寒欲残时，香无著处，千树风前玉。\n游蜂飞过，隔墙疑是金谷。\n偏称晚色横烟，愁凝峨髻，澹生绡裙幅。\n缥缈孤山南畔路，相对花房竹屋。\n溪足沙明，岩阴石秀，梦冷吟亭宿。\n松风古涧，高调月夜清曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6502, '惜红衣', '吴文英', '鹭老秋丝，苹愁暮雪，鬓那不白。\n倒柳移栽，如今暗溪碧。\n乌衣细语，伤绊惹、茸红曾约。\n南陌。\n前度刘郎，寻流花踪迹。\n朱楼水侧。\n雪面波光，汀莲沁颜色。\n当时醉近绣箔，夜吟寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6503, '江南好・忆江南', '吴文英', '行锦归来，画眉添妩，暗尘重拂雕栊。\n稳瓶泉暖，花隘斗春容。\n围密笼香暗霭，烦纤手、亲点团龙。\n温柔处，垂杨髻，□暗豆花红。\n行藏，多是客，莺边话别，桔下相逢。\n算江湖幽梦，频绕残钟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6504, '双双燕', '吴文英', '小桃谢後，双双燕，飞来几家庭户。\n轻烟晓暝，湘水暮云遥度。\n帘外馀寒未卷，共斜入、红楼深处。\n相将占得雕梁，似约韶光留住。\n堪举。\n翩翩翠羽。\n杨柳岸，泥香半和梅雨。\n落花风软，戏促乱红飞舞。\n多少呢喃意绪。\n尽日向、流莺分诉。\n还过短墙，谁会万千言语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6505, '无闷', '吴文英', '霓节飞琼，鸾驾弄玉，杳隔平云弱水。\n倩皓鹤传书，卫姨呼起。\n莫待粉河凝晓，趁夜月、瑶笙飞环佩。\n正蹇驴吟影，茶烟灶冷，酒亭门闭。\n歌丽。\n泛碧蚁。\n放绣帘半钩，宝台临砌。\n要须借东君，灞陵春意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6506, '水调歌头', '吴文英', '屋下半流水，屋上几青山。\n当心千顷明镜，入座玉光寒。\n云起南峰未雨，云敛北峰初霁，健笔写青天。\n俯瞰古城堞，不碍小阑干。\n绣鞍马，软红路，乍回班。\n层梯影转亭午，信手展缃编。\n残照游船收尽，新月画帘才卷，人在翠壶间。\n天际笛声起，尘世夜漫漫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6507, '洞仙歌', '吴文英', '芳辰良宴，人日春朝并。\n细缕青丝裹银饼。\n更玉犀金彩，沾座分簪，歌围暖，梅靥桃唇斗胜。\n露房花曲折，莺入新年，添个宜男小山枕。\n待枝上，饱东风，结子成阴，蓝桥去、还觅琼浆一饮。\n料别馆、西湖最情浓，烂画舫月明，醉宫袍锦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6508, '秋思', '吴文英', '堆枕香鬟侧。\n骤夜声、偏称画屏秋色。\n风碎串珠，润侵歌板，愁压眉窄。\n动罗清商，寸心低诉叙怨抑。\n映梦窗，零乱碧。\n待涨绿春深，落花香泛，料有断红流处，暗题相忆。\n欢酌。\n檐花细滴。\n送故人、粉黛重饰。\n漏侵琼瑟。\n丁东敲断，弄晴月白。\n怕一曲、霓裳未终，催去骖凤翼。\n叹谢客、犹未识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6509, '江神子・江城子', '吴文英', '长安门外小林丘。\n碧壶秋。\n浴轻鸥。\n不放啼红，流水通宫沟。\n时有晴空云过影，华镜里，翳鱼游。\n绮罗尘满九衢头。\n晚香楼。\n夕阳收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6510, '江神子・江城子', '吴文英', '一声玉磬下星坛。\n步虚阑。\n露华寒。\n平晓阿香，油壁碾青鸾。\n应是老鳞眠不得，云炮落，雨瓢翻。\n身闲犹耿寸心丹。\n炷炉烟。\n暗祈年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6511, '江神子・江城子', '吴文英', '翠纱笼袖映红霏。\n冷香飞。\n洗凝脂。\n睡足娇多，还是夜深宜。\n翻怕回廊花有影，移烛暗，放帘垂。\n尊前不按驻云词。\n料花枝。\n妒蛾眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6512, '渔父词・渔父', '周紫芝', '花姑溪上鹭鸶滩。\n辜负渔竿二十年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6513, '木兰花・玉楼春', '莫将', '一枝和露珍珠贯。\n月下回来寻几遍。\n今朝忽见数枝开，未有十分如待伴。\n新妆不比徐妃面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6514, '木兰花・玉楼春', '莫将', '梅边晓景清无比。\n林下诗人呵冻指。\n玉龙留住麝脐烟，银漏滴残龙脑水。\n晨光渐渐收寒气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6515, '木兰花・玉楼春', '莫将', '清姿自是生寒瘦。\n更在春前并腊後。\n谁教六出巧遮藏，争似一番先透漏。\n谢娘莫把翻衣袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6516, '木兰花・玉楼春', '莫将', '寒梢雨里愁无那。\n林下开时宜数过。\n夕阳恰似过清溪，一树横斜疏影卧。\n朱唇莫比桃花破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6517, '木兰花・玉楼春', '莫将', '寻梅莫背东风路。\n路在花前知去处。\n真香破鼻蓦然闻，试问幽丛知几步。\n多情更被无寒助。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6518, '木兰花・玉楼春', '莫将', '暗香浮动黄昏後。\n更是月明如白昼。\n看来都坐玉壶冰，折赠徐妃丹桂手。\n赏酬风景无过酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6519, '木兰花・玉楼春', '莫将', '花时人道多风雨。\n梅蕊都来无几许。\n何须飘洒湿芳心，粉面琳琅如泪注。\n家童莫扫花阴土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6520, '木兰花・玉楼春', '莫将', '眼前欲尽情何限。\n风外南枝无一半。\n东君何事莫教开，及至如今都不管。\n高楼三弄休吹趱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6521, '木兰花・玉楼春', '莫将', '前村雪里虽然早。\n争似横斜开处好。\n直饶隔水是江南，也恐一枝春未到。\n延宾莫恨花阴小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6522, '木兰花・玉楼春', '莫将', '少陵长被花为恼。\n况是梅花非草草。\n临歧争奈不吟诗，此度诗人宜可老。\n诗成莫惜尊倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6523, '独脚令・忆王孙', '莫将', '绛唇初点粉红新。\n凤镜临妆已逼真。\n苒苒钗头香趁人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6524, '浣溪沙', '莫将', '宝钏香裙上玉梯。\n云重应恨翠楼低。\n愁同芳草两萋萋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6525, '浣溪沙', '莫将', '归梦悠扬见未真。\n绣衾恰有暗香薰。\n五更分得楚台春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6526, '念奴娇', '邵博', '天然潇洒，尽人间、无物堪齐标格。\n只与娥为伴侣，方显一家颜色。\n好是多情，一年一度，首作东君客。\n竹篱茅舍，典刑别是清白。\n惆怅玉杵无凭，蓝桥人去，空锁神仙宅。\n今日天涯凭马上，忽见轻盈冰魄。\n恰似当年，温柔乡里，晓看新妆额。\n临风三嗅，挽条不忍空摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6527, '声声慢', '赵佶', '宫梅粉淡，岸柳金匀，皇州乍庆春回。\n凤阙端门，棚山彩建蓬莱。\n沈沈洞天向晚，宝舆还、花满钧台。\n轻烟里，算谁将金莲，陆地齐开。\n触处声歌鼎沸，香鞯趁，雕轮隐隐轻雷。\n万家帘幕，千步锦绣相挨。\n银蟾皓月如昼，共乘欢、争忍归来。\n疏钟断，听行歌、犹在禁街。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6528, '声声慢', '赵佶', '欺寒冲暖，占早争春，江梅已破南枝。\n向晚阴凝，偏宜映月临池。\n天然莹肌秀骨，笑等闲、桃李芳菲。\n劳梦想，似玉人羞懒，弄粉妆迟。\n长记行歌声断，犹堪恨，无情塞管频吹。\n寄远丁宁，折赠陇首相思。\n前村夜来雪里，东君、须索饶伊。\n烂漫也，算百花、犹自未知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6529, '念奴娇', '赵佶', '雅怀素态，向闲中、天与风流标格。\n绿锁窗前湘簟展，终日风清人寂。\n玉子声乾，纹楸色净，星点连还直。\n跳丸日月，算应局上销得。\n全似落浦斜晖，寒鸦游鹭，乱点沙汀碛。\n妙算神机，须信道，国手都无敌。\n玳席欢馀，芸堂香暖，赢取专良夕。\n桃园归路，烂柯应笑凡客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6530, '醉落魄・一斛珠', '赵佶', '无言哽噎。\n看灯记得年时节。\n行行指月行行说。\n愿月常圆，休要暂时缺。\n今年华市灯罗列。\n好灯争柰人心别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6531, '探春令', '赵佶', '帘旌微动，峭寒天气，龙池冰泮。\n杏花笑吐香犹浅。\n又还是、春将半。\n清歌妙舞从头按。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6532, '聒龙谣', '赵佶', '紫阙苕，绀宇邃深，望极绛河清浅。\n霜月流天，锁穹隆光满。\n水精宫、金锁龙盘，玳瑁帘、玉钩云卷。\n动深思，秋籁萧萧，比人世、倍清燕。\n瑶阶回。\n玉签鸣，渐秘省引水，辘轳声转。\n鸡人唱晓，促铜壶银箭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6533, '临江仙', '赵佶', '过水穿山前去也，吟诗约句千馀。\n淮波寒重雨疏疏。\n烟笼滩上鹭，人买就船鱼。\n古寺幽房权且住，夜深宿在僧居。\n梦魂惊起转嗟吁。\n愁牵心上虑，和泪写回书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6534, '月上海棠', '赵佶', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6535, '满庭芳', '赵佶', '寰宇清夷，元宵游豫，为开临御端门。\n暖风摇曳，香气霭轻氛。\n十万钩陈灿锦，钧台外、罗绮缤纷。\n欢声里，烛龙衔耀，黼藻太平春。\n灵鳌，擎采岫，冰轮远驾，初上祥云。\n照万宇嬉游，一视同仁。\n更起维垣大第，通宵宴、调燮良臣。\n从兹庆，都俞庚载，千岁乐昌辰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6536, '眼儿媚', '赵佶', '玉京曾忆惜繁华。\n万里帝王家。\n琼林玉殿，朝喧弦管，暮列笙琶。\n花城人去今萧索，春梦绕胡沙。\n家山何处，忍听羌笛，吹彻梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6537, '燕山亭', '赵佶', '裁翦冰绡，打叠数重，冷淡燕脂匀注。\n新样靓妆，艳溢香融，羞杀蕊珠宫女。\n易得凋零，更多少、无情风雨。\n愁苦。\n闲院落凄凉，几番春暮。\n凭寄离恨重重，这双燕，何曾会人言语。\n天遥地远，万水千山，知他故宫何处。\n怎不思量，除梦里、有时会去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6538, '失调名', '赵佶', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6539, '金莲绕凤楼', '赵佶', '绛烛朱笼相随映。\n驰绣毂、尘清香衬。\n万金光射龙轩莹。\n绕端门、瑞雷轻振。\n元宵为开圣景。\n严敷坐、观灯锡庆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6540, '小重山', '赵佶', '罗绮生香娇上春。\n金莲开陆海，艳都城。\n宝舆回望翠峰青。\n东风鼓，吹下半天星。\n万井贺升平。\n行歌花满路，月随人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6541, '踏莎行', '侯彭老', '十二封章，三千里路。\n当年走遍东西府。\n时人莫讶出都忙，官家送我归乡去。\n三诏出山，一言悟主。\n古人料得皆虚语。\n太平朝野总多欢，江湖幸有宽闲处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6542, '水龙吟', '李纲', '笑不知天命，明珠玉斗，漫撞令碎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6543, '水龙吟', '李纲', '汉家炎运中微，坐令闰位馀分据。\n南阳自有，真人膺历，龙翔虎步。\n初起昆城，旋驱乌合，块然当路。\n想莽军百万，旌旗千里，应道是、探囊取。\n豁达刘郎大度。\n对敌、安恬无惧。\n提兵夹击，声喧天壤，雷风借助。\n虎豹哀嗥，戈委地，一时休去。\n早复收旧物，扫清氛，作中兴主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6544, '念奴娇', '李纲', '茂陵仙客，算真是、天与雄才宏略。\n猎取天骄驰卫霍，如使鹰驱雀。\n鏖战皋兰，犁庭龙碛，饮至行勋爵。\n中华疆盛，坐令夷狄衰弱。\n追想当日巡行，勒兵十万骑，横临边朔。\n亲总貔貅谈笑看，黠虏心惊胆落。\n寄语单于，两君相见，何苦逃沙漠。\n英风如在，卓然千古高著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6545, '喜迁莺', '李纲', '长江千里。\n限南北、雪浪云涛无际。\n天险难逾，人谋克壮，索虏岂能吞噬。\n阿坚百万南牧，倏忽长驱吾地。\n破强敌，在谢公处画，从容颐指。\n奇伟。\n淝水上，八千戈甲，结阵当蛇豕。\n鞭弭周旋，旌旗麾动，坐却北军风靡。\n夜闻数声鸣鹤，尽道王师将至。\n延晋祚，庇民，周雅何曾专美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6546, '水龙吟', '李纲', '古来夷狄难驯，射飞择肉天骄子。\n唐家建国，北边雄盛，无如颉利。\n万马崩腾，皂旗毡帐，远临清渭。\n向郊原驰突，凭陵仓卒，知战守、难为计。\n须信君王神武。\n觇虏营、只从七骑。\n长弓大箭，据鞍诘问，单于非义。\n戈甲鲜明，旌麾光彩，六军随至。\n怅敌情震骇，鱼循鼠伏，请坚盟誓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6547, '念奴娇', '李纲', '晚唐姑息，有多少方镇，飞扬跋扈。\n淮蔡雄藩联四郡，千里公然旅拒。\n同恶相资，潜伤宰辅，谁敢分明语。\n婀群议，共云旄节应付。\n於穆天子英明，不疑不贰处，登庸裴度。\n往督全师威令使，擒贼功名归诉。\n半夜衔枚，满城深雪，忽已亡悬瓠。\n明堂坐治，中兴高映千古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6548, '雨霖铃', '李纲', '蛾眉修绿。\n正君王恩宠，曼舞丝竹。\n华清赐浴瑶，五家会处，花盈山谷。\n百里遗簪堕珥，尽宝钿珠玉。\n听突骑、鼙鼓声喧，寂寞霓裳羽衣曲。\n金舆还幸匆匆速。\n奈六军不发人争目。\n明眸皓齿难恋，肠断处、绣囊犹馥。\n剑阁峥嵘，何况铃声，带雨相续。\n谩留与、千古伤神，尽入生绡幅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6549, '喜迁莺', '李纲', '边城寒早。\n恣骄虏、远牧甘泉丰草。\n铁马嘶风，毡裘凌雪，坐使一方云扰。\n庙堂折冲无策，欲幸坤维江表。\n叱群议，赖寇公力挽，亲行天讨。\n缥缈。\n銮辂动，霓旌龙旆，遥指澶渊道。\n日照金戈，云随黄伞，径渡大河清晓。\n六军万姓呼舞，箭发敌酋难保。\n虏情慑，誓书来，从此年年修好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6550, '减字木兰花', '李纲', '茫茫云海。\n方丈蓬壶何处在。\n拟泛轻舟。\n一到金鳌背上游。\n琼楼珠室。\n千岁蟠桃初结实。\n月冷风清。\n试倩双成吸玉笙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6551, '减字木兰花', '李纲', '龟台金母。\n绀发芳容超古。\n绛节霓旌。\n青鸟传言若可凭。\n瑶池龙宴。\n零落碧桃香片片。\n八骏西巡。\n更有何人继後尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6552, '永遇乐', '李纲', '秋色方浓，好天凉夜，风雨初霁。\n缺月如钩，微云半掩，的灿星河碎。\n爽来轩户，凉生枕簟，夜永悄然无寐。\n起徘徊，凭栏凝伫，片时万情千意。\n江湖倦客，年来衰病，坐叹岁华空逝。\n往事成尘，新愁似锁，谁是知心底。\n五陵萧瑟，中原杳杳，但有满襟清泪。\n烛兰缸，呼童取酒，且图径醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6553, '望江南・忆江南', '李纲', '归去客，迂骑过江乡。\n茅店鸡声寒逗月，板桥人迹晓凝霜。\n一望楚天长。\n春信早，山路野梅香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6554, '水调歌头', '李纲', '律吕自相召，韶不难谐。\n致君泽物，古来何世不须才。\n幸可山林高卧，袖手何妨闲处，醇酒醉朋侪。\n千里故人驾，不怕物情猜。\n秋夜永，更秉烛，且衔杯。\n五年离索，谁谓谈笑豁幽怀。\n况我早衰多病，屏迹云山深处，俗客不曾来。\n此日扫花径，蓬户为君开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6555, '水调歌头', '李纲', '如意始身退，此事古难谐。\n中年醉饮，多病闲去正当才。\n长爱兰亭公子，弋钓溪山娱适，甘旨及朋侪。\n衰疾卧江海，鸥鸟莫惊猜。\n酒初熟，招我友，共一杯。\n碧天云卷，高挂明月照人怀。\n我醉欲眠君去，醉醒君如有意，依旧抱琴来。\n尚有一壶酒，当复为君开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6556, '水调歌头', '李纲', '物我本虚幻，世事若俳谐。\n功名富贵，当得须是个般才。\n幸有山林云水，造物端如有意，分付与吾侪。\n寄语旧猿鹤，不用苦相猜。\n醉中适，一杯尽，复一杯。\n坐间有客，超诣言笑可忘怀。\n况是清风明月，如会幽人高意，千里自飞来。\n共笑陶彭泽，空对菊花开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6557, '念奴娇', '李纲', '暮云四卷，淡星河、天影茫茫垂碧。\n皓月浮空，人尽道，端的清圆如璧。\n丹桂扶疏，银蟾依约，千古佳今夕。\n寒光委照，有人独坐秋色。\n怅念老子平生，粗令婚嫁了，超然闲适。\n误缚簪缨遭世故，空有当时胸臆。\n苒苒流年，春鸿秋燕，来往终何益。\n云山深处，这回真是休息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6558, '感皇恩', '李纲', '九日菊花迟，茱萸却早。\n嫩蕊浓香自妍好。\n一簪华发，只恐西风吹帽。\n细看还遍插，人忘老。\n千古此时，清欢多少。\n铁马台空但荒草。\n旅愁如海，须把金尊销了。\n暮天秋影碧，云如扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6559, '渔家傲', '李纲', '木落霜清秋色霁。\n菊苞渐吐金英碎。\n佳节不随东去水。\n谁得会。\n黄花开日重阳至。\n三径旧栽烟水外。\n故园凝望空流泪。\n香色向人如有意。\n落蕊。\n金尊满满从教醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6560, '水调歌头', '李纲', '秋杪暑方退，清若玉壶冰。\n高楼对月，天上宫殿不曾扃。\n散下凄然风露，影照江山如昼，浑觉俗缘轻。\n弋者欲何慕，鸿羽正冥冥。\n世间法，唯此事，最堪凭。\n太虚心量，聊假梨枣制颓龄。\n但使心安身健，静看草根泉际，吟蚓与飞萤。\n一坐小千劫，无念契无生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6561, '江城子', '李纲', '老饕嗜酒若鸱夷。\n拣珠玑。\n自蒸炊。\n尽云腴，浮蚁在瑶卮。\n有客相过同一醉，无客至，独中之。\n麴生风味有谁知。\n豁心脾。\n展愁眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6562, '江城子', '李纲', '客中重九共登高。\n逼烟霄。\n见秋毫。\n云涌群山，山外海翻涛。\n回首中原何处是，天似幕，碧周遭。\n茱萸蕊绽菊方苞。\n左倾醪。\n右持螯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6563, '感皇恩', '李纲', '西阁夜初寒，炉烟轻袅。\n竹枕绸衾素屏小。\n片时清梦，又被木鱼惊觉。\n半窗残月影，天将晓。\n幻境去来，胶胶扰扰。\n追想平生发孤笑。\n壮怀消散，尽付败荷衰草。\n个中还得趣，从他老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6564, '望江南・忆江南', '李纲', '新阁就，向日借清光。\n广厦生风非我志，小窗容膝正相当。\n聊此傲羲皇。\n狨尾拂，高挂木绳床。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6565, '望江南・忆江南', '李纲', '新酒熟，云液满香。\n溜溜清声归小瓮，温温玉色照瓷瓯。\n饮兴浩难收。\n嘉客至，一酌散千忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6566, '望江南・忆江南', '李纲', '新雨足，一夜满南塘。\n粳稻向成初吐秀，芰荷虽败尚馀香。\n爽气入轩窗。\n澄霁後，远岫更青苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6567, '望江南・忆江南', '李纲', '新月出，清影尚苍茫。\n学扇欲生青海上，如钩先挂碧霄傍。\n星斗焕文章。\n林下客，把酒挹孤光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6568, '江城子', '李纲', '琉璃滑处玉花飞。\n溅珠玑。\n喷霏微。\n谁遣银河，一派九天垂。\n昨夜白虹来涧饮，留不去，许多时。\n幽人独坐石ㄛ。\n赏清奇。\n濯涟漪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6569, '减字木兰花', '李纲', '华清赐浴。\n宝瓮温泉浇腻玉。\n笑靥开时。\n一骑红尘献荔枝。\n明珠乍剖。\n自擘轻红香满手。\n锦袜罗囊。\n犹瘗当年驿路旁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6570, '减字木兰花', '李纲', '仙姝丽绝。\n被服红绡肤玉雪。\n火齐堆盘。\n常得杨妃带笑看。\n劳生重马。\n远贡长为千古话。\n林下甘芳。\n却准幽人餍饫尝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6571, '丑奴儿・采桑子', '李纲', '幽芳不为春光发，直待秋风。\n直待秋风。\n香比馀花分外浓。\n步摇金翠人如玉，吹动珑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6572, '丑奴儿・采桑子', '李纲', '枝头万点妆金蕊，十里清香。\n十里清香。\n解引幽人雅思长。\n玉壶贮水花难老，净几明窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6573, '江城子', '李纲', '去年九日在衡阳。\n满林霜。\n俯潇湘。\n回雁峰头，依约雁南翔。\n遥想茱萸方遍插，唯少我，一枝香。\n今年佳节幸相将。\n陟层冈。\n举华觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6574, '水调歌头', '李纲', '太白乃吾祖，逸气薄青云。\n开元有道，聊复乘兴一来宾。\n天子呼来方醉，洒面清泉微醒，馀吐试龙巾。\n词翰不加点，歌阕满宫春。\n笔风雨，心锦绣，极清新。\n大儿中令，神契兼有坐忘人。\n不识将军高贵，醉里指污吾足，乃敢尚衣嗔。\n千载已仙去，图象耸风神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6575, '水龙吟', '李纲', '际天云海无涯，径从一叶舟中渡。\n天容海色，浪平风稳，何尝有飓。\n鳞甲千山，笙镛群籁，了无遮护。\n笑读君佳阕，追寻往事，须信道、忘来去。\n闻说钓鲸公子，为才名、鹗书交举。\n高怀澹泊，柏台兰省，留连莫住。\n万里闽山，不从海道，寄声何处。\n怅七年契阔，无因握手，与开怀语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6576, '水龙吟', '李纲', '莫春清淑之初，赏心最乐惟修禊。\n兰亭序饮，泛觞流咏，萧然适意。\n旧弼宗英，文章贤牧，肯临外。\n向碧山深处，寻花问柳，有佳气、随旌旆。\n寥落幽人寓止。\n惜僧园、缭云萦水。\n栽花种竹，凿池开径，渊明岂愧。\n美景良辰，玉颜方老，欲留何计。\n对残红嫩绿，开怀笑时，且须同醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6577, '水调歌头', '李纲', '花径不曾扫，蓬户为君开。\n元戎小队，清晓佳客与同来。\n我为衰迟多病，且恁浇花艺药，随分葺池台。\n多谢故人意，迂访白云隈。\n暮春月，修禊事，会兰斋。\n一觞一咏，何愧当日畅幽怀。\n况是茂林修竹，映带清流湍激，山色碧崔嵬。\n勿复叹陈迹，且为醉金杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6578, '江城子', '李纲', '武夷山里一溪横。\n晚风清。\n断霞明。\n行至真、馆下月华生。\n仙迹灵踪知几许，云缥缈，石峥嵘。\n羽人同载小舟轻。\n玉壶倾。\n荐芳馨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6579, '江城子', '李纲', '春来江上打头风。\n吼层空。\n卷飞蓬。\n多少云涛，雪浪暮江中。\n早是客情多感慨，烟漠漠，雨。\n梁溪只在太湖东。\n长儿童。\n学庞翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6580, '江城子', '李纲', '晓来江口转南风。\n静烟空。\n整云蓬。\n满眼高帆，隐映画图中。\n呕轧数声离岸橹，云暗淡，雪溟。\n扁舟归去五湖东。\n狎樵童。\n侣渔翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6581, '望江南・忆江南', '李纲', '征骑远，千里别沙阳。\n泛碧斋傍凝翠阁，凄云寺里印心堂。\n回首意茫茫。\n分水岭，烟雨正凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6582, '望江南・忆江南', '李纲', '云岭水，南北自分流。\n触目澜翻飞雪浪，赴溪盘屈转琼钩。\n呜咽不胜愁。\n归去客，征骑远闽州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6583, '望江南・忆江南', '李纲', '云棹远，南浦绿波春。\n日暖风和初解冻，饵香竿袅好垂纶。\n一钓得金鳞。\n风乍起，吹皱碧渊沦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6584, '望江南・忆江南', '李纲', '清昼永，幽致夏来多。\n远岸参差风扬柳，平湖清浅露翻荷。\n移棹钓烟波。\n凉一霎，飞雨洒轻蓑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6585, '望江南・忆江南', '李纲', '烟艇稳，浦溆正清秋。\n风细波平宜进楫，月明江静好沈钩。\n横笛起汀洲。\n鲈鳜美，新酿蚁醅浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6586, '望江南・忆江南', '李纲', '江上雪，独立钓渔翁。\n箬笠但闻冰散响，蓑衣时振玉花空。\n图画若为工。\n云水暮，归去远烟中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6587, '六么令', '李纲', '长江千里，烟澹水云阔。\n歌沈玉树，古寺空有疏钟发。\n六代兴亡如梦，苒苒惊时月。\n兵戈凌灭。\n豪华销尽，几见银蟾自圆缺。\n潮落潮生波渺，江树森如发。\n谁念迁客归来，老大伤名节。\n纵使岁寒途远，此志应难夺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6588, '喜迁莺', '李纲', '江天霜晓。\n对万顷雪浪，云涛弥渺。\n远岫参差，烟树微茫，阅尽往来人老。\n浅沙别浦极望，满目馀霞残照。\n暮云敛，放一轮明月，窥人怀抱。\n杳杳。\n千里恨，玉人一别，梦断无音耗。\n手拈江梅，枝头春信，欲寄算应难到。\n画船片帆浮碧，更值风高波浩。\n几时得向尊前，销却许多烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6589, '喜迁莺', '李纲', '边城寒早。\n对漠漠暮秋，霜风烟草。\n战□长闲，刁斗无声，空使荷戈人老。\n陇头立马极目，万里长城古道。\n感怀处，问仲宣云乐，从军多少。\n缥缈。\n云岭外，夕烽一点，塞上传光小。\n玉帐尊，青油谈笑，肯把壮怀销了。\n画楼数声残角，吹彻梅花霜晓。\n愿岁岁静烟尘，羌虏常修邻好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6590, '一翦梅', '李纲', '数点梅花玉雪娇。\n烟水篱边，半袅青梢。\n横斜疏影月黄昏，谁使天香，暗淡飘飘。\n半醉佳人酒未消。\n宝髻偏时，插更斜袅。\n尊前还唱早梅词，琼醑何如，□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6591, '玉蝴蝶', '李纲', '万古秣陵江国，舣舟烟岸，千里云林。\n故垒高楼，凝望远水遥岑。\n景阳钟、那闻旧响，玉树唱、空有馀音。\n感春心。\n六朝遗事，萧索难寻。\n甘泉法从弟兄芝玉，顾我情深。\n契阔相思，岂知今日共登临。\n对尊俎、休辞痛饮，伤志节、须且高吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6592, '水龙吟', '李纲', '晚春天气融和，乍惊密雪烟空坠。\n因风飘荡，千门万户，牵情惹思。\n青眼初开，翠眉才展，小园长闭。\n又谁知化作，琼花玉屑，共榆荚、漫天起。\n深院美人慵困，乱云鬟、尽从妆缀。\n小廊回处，氍毹重叠，轻拈却碎。\n飞入楼台，舞穿帘幕，总归流水。\n怅青春又过，年年此恨，满东风泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6593, '满庭芳', '李纲', '何时得，恩来日下，蓑笠老江湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6594, '西江月', '李纲', '意态何如涎涎，轻盈只恐飞飞。\n华堂偏傍主人栖。\n好与安巢稳戏。\n揽断楼中风月，且看掌上腰支。\n谪仙词赋少陵诗。\n万语千言总记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6595, '苏武令', '李纲', '塞上风高，渔阳秋早。\n惆怅翠华音杳。\n驿使空驰，征鸿归尽，不寄双龙消耗。\n念白衣、金殿除恩，归黄阁、未成图报。\n谁信我、致主丹衷，伤时多故，未作救民方召。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6596, '感皇恩', '胡舜陟', '乞得梦中身，归栖云水。\n始觉精神自家底。\n峭帆轻棹，时与白鸥游戏。\n畏途都不管，风波起。\n光景如梭，人生浮脆。\n百岁何妨尽沈醉。\n卧龙多事，谩说三分奇计。\n算来争似我，长昏睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6597, '渔家傲', '胡舜陟', '几日北风江海立。\n千车万马鏖声急。\n短棹峭寒欺酒力。\n飞雨息。\n琼花细细穿窗隙。\n我本绿蓑青箬笠。\n浮家泛宅烟波逸。\n渚鹭沙鸥多旧识。\n行未得。\n高歌与尔相寻觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6598, '减字木兰花', '李祁', '梨花院宇。\n澹月倾云初过雨。\n一枝轻寒。\n梦入西瑶小道山。\n花深人静。\n帘锁御香清昼永。\n红药阑干。\n玉案春风窈窕间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6599, '点绛唇', '李祁', '楼下清歌，水流歌断春风暮。\n梦云烟树。\n依约江南路。\n碧水黄沙，梦到寻梅处。\n花无数。\n问花无语。\n明月随人去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6600, '青玉案', '李祁', '绿琐窗纱明月透。\n正清梦、莺啼柳。\n碧井银瓶鸣玉。\n翔鸾妆样，粲花衫绣。\n分付春风手。\n喜入秋波娇欲溜。\n脉脉青山两眉秀。\n玉枕春寒郎知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6601, '鹊桥仙', '李祁', '春阴淡淡，春波渺渺，帘卷花稍香雾。\n小舟谁在落梅村，正梦绕、清溪烟雨。\n碧山学士，云房娇小，须要五湖同去。\n桃花流水鳜鱼肥，恰趁得、江天佳处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6602, '阮郎归', '李祁', '校书学士小蓬山。\n新参玉笋班。\n买花归去五湖间。\n浣花龙尾湾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6603, '南歌子', '李祁', '袅袅秋风起，萧萧败叶声。\n岳阳楼上听哀筝。\n楼下凄凉江月、为谁明。\n雾雨沈云梦，烟波渺洞庭。\n可怜无处问湘灵。\n只有无情江水、绕孤城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6604, '醉桃源・阮郎归', '李祁', '春风碧水满郎湖。\n水清梅影疏。\n渡江桃叶酒家垆。\n髻鬟云样梳。\n吹玉蕊，饮琼腴。\n不须红袖扶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6605, '朝中措', '李祁', '郎官湖上探春回。\n初见照江梅。\n过尽竹溪流水，无人知道花开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6606, '西江月', '李祁', '拾翠亭前水满，郎官湖上春回。\n仪龙新碾试琼杯。\n更见春江有味。\n拄杖行穿翠，吹花醉绕江梅。\n故园心事老相催。\n此意陶潜能会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6607, '西江月', '李祁', '云观三山清露，长生万鬣青松。\n琼珠珥下秋空。\n一笑满天鸾凤。\n雾鬓新梳绀绿，霞衣旧佩柔红。\n更邀豪俊驭南风。\n此意平生飞动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6608, '如梦令', '李祁', '春水湖塘深处。\n竹暗沙洲无路。\n闲伴落花来，却信东风归去。\n且住。\n且住。\n细看两山烟雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6609, '如梦令', '李祁', '不见玉人清晓。\n长啸一声云杪。\n碧水满阑塘，竹外一枝风袅。\n奇妙。\n奇妙。\n半夜山空月皎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6610, '水龙吟', '李祁', '碧山横绕清湖，茂林秀麓波光里。\n南宫老大，西洲漂荡，危亭重倚。\n雨步云行，饵风饮雾，平生游戏。\n笑此中空洞，都无一物，有神妙、浩然气。\n扫尽云南梦北，看三江五湖秋水。\n狂歌两解，清尊一举，超然千里。\n江汉苍茫，故人何处，山川良是。\n待白苹露下，青天月上，约骑鲸起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6611, '浪淘沙', '李祁', '拍手趁西风。\n惊起乖龙。\n青山绿水古今同。\n唯有一轮山上月，长照江中。\n一点落金钟。\n浑似虚空。\n道人不住有云峰。\n但是人家清酒瓮，行处相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6612, '如梦令', '叶祖义', '如梦。\n如梦。\n和尚出门相送。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6613, '失调名', '左誉', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6614, '失调名', '左誉', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6615, '失调名', '左誉', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6616, '洞仙歌', '吕直夫', '征鞍带月，浓露沾襟袖。\n马上轻衫峭寒透。\n望翠峰深浅，忆着眉儿，腰枝袅，忍看风前细柳。\n别时频嘱付，早寄书来，能趁清明到家否。\n这言语，便梦里、也在心头，重相见、不知伊瘦我瘦。\n纵百卉千花已离披，也趁锝、酴牡丹时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6617, '婆罗门引', '杨景', '帐云暮卷，漏声不到小帘栊。\n银汉夜洗晴空。\n皓月堂轩高挂，秋入广寒宫。\n正金波不动，桂影玲珑。\n佳人未逢。\n怅此夕、与谁同。\n对酒当歌，追念霜满愁红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6618, '西江月', '范智闻', '紫素全如玉琢，清音不假金妆。\n海沈时许试芬芳。\n仿佛云飞仙掌。\n烟缕不愁凄断，宝钗还与商量。\n佳人特特为翻香。\n图得氤氲重上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6619, '好事近', '蒋元龙', '叶暗乳鸦啼，风定老红犹落。\n蝴蝶不随春去，入薰风池阁。\n休歌金缕劝金卮，酒病煞如昨。\n帘卷日长人静，任杨花飘泊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6620, '阮郎归', '蒋元龙', '小池芳草绿初匀。\n柳寒眉尚颦。\n东风吹雨细於尘。\n一庭花脸皴。\n莺共蝶，怨还嗔。\n眼前无好春。\n这般天气煞愁人。\n人愁旋旋新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6621, '乌夜啼', '蒋元龙', '小桃落尽残红。\n夜来风。\n又是一番春事、不从容。\n翠屏掩。\n芳信断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6622, '绿头鸭・多丽', '周格非', '陇头泉，未到陇下轻分。\n一声声、凄凉呜咽，岂堪侧耳重闻。\n细思量、那时携手，画楼高、帘幕黄昏。\n月不长圆，云多轻散，天应偏妒有情人。\n自别後、小窗幽院，无处不消魂。\n罗衣上，残妆未减，犹带啼痕。\n自一从、瓶沈簪折，杳知欲见无因。\n也浑疑、事如春梦，又只愁、人是朝云。\n破境分来，朱弦断後，不堪独自对芳樽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6623, '西江月', '程邻', '阶下宝鞍罗帕，门前绛蜡纱笼。\n留连佳客怅匆匆。\n赖有新团小凤。\n琼碎黄金碾里，乳浮紫玉瓯中。\n归来袭袭袖生风。\n齿颊馀甘入梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6624, '宴清都', '何籀', '细草沿阶软。\n迟日薄，蕙风轻蔼微暖。\n春工靳惜，桃红尚小，柳芽犹短。\n罗帏绣幕高卷。\n又早是、歌慵笑懒。\n凭画楼，那更天远，山远，水远，人远。\n堪叹。\n傅粉疏狂，窃香俊雅，无计拘管。\n青丝绊马，红巾寄泪，甚处迷恋。\n无言泪珠零乱。\n翠袖滴、重重渍遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6625, '烛影摇红', '廖世美', '霭霭春空，画楼森耸凌云渚。\n紫薇登览最关情，绝妙夸能赋。\n惆怅相思迟暮。\n记当日、朱阑共语。\n塞鸿难问，岸柳何穷，别愁纷絮。\n催促年光，旧来流水知何处。\n断肠何必更残阳，极目伤平楚。\n晚霁波声带雨。\n悄无人、舟横野渡。\n数峰江上，芳草天涯，参差烟树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6626, '好事近', '廖世美', '落日水熔金，天淡暮烟凝碧。\n楼上谁家红袖，靠阑干无力。\n鸳鸯相对浴红衣，短棹弄长笛。\n惊起一双飞去，听波声拍拍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6627, '菩萨蛮', '李元卓', '一枝绛蜡香梅软。\n宜春小胜玲珑剪。\n拂晓上瑶钗。\n春从鬓底来。\n菱花频自照。\n粉面惊春早。\n淡拂晓山眉。\n为谁今日宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6628, '人娇', '张方仲', '多少胭脂，匀成点就。\n千枝乱、攒红堆绣。\n花无长好，更光阴去骤。\n对景忆良朋，故应招手。\n曾说年时，花间把酒。\n任淋浪、春衫湿透。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6629, '透碧霄', '查', '舣兰舟。\n十分端是载离愁。\n练波送远，屏山遮断，此去难留。\n相从争奈，心期久要，屡更霜秋。\n叹人生、杳似萍浮。\n又翻成轻别，都将深恨，付与东流。\n想斜阳影里，寒烟明处，双桨去悠悠。\n爱渚梅、幽香动，须采掇、倩纤柔。\n艳歌粲发，谁传馀韵，来说仙游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6630, '卜算子', '李敦诗', '南北利名人，常恨家居少。\n每到春时听子规，无不伤怀抱。\n好去向长安，细与公卿道。\n待得功成名遂时，不似归来早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6631, '忆真妃・相见欢', '康仲伯', '匆匆一望关河。\n听离歌。\n艇子急催双桨、下清波。\n淋浪醉。\n阑干泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6632, '昭君怨', '程过', '试问愁来何处。\n门外山无重数。\n芳草不知人。\n翠连云。\n欲看不忍重看。\n心事只堪肠断。\n肠断宿孤村。\n雨昏昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6633, '满江红', '程过', '春欲来时，长是与、江梅花约。\n又还向、竹林疏处，一枝开却。\n对酒渐惊身老大，看花应念人离索。\n但十分、沈醉祝东君，长如昨。\n芳草渡，孤舟泊。\n山敛黛，天垂幕。\n黯销魂、无奈暮云残角。\n便好折来和雪戴，莫教酒醒随风落。\n待殷勤、留此记相思，谁堪托。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6634, '浣溪沙', '曾', '别样清芬扑鼻来。\n秋香过後却追回。\n博山轻雾锁崔嵬。\n珍重芗林三昧手，不教一日不花开。\n暗中错认是江梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6635, '调笑令', '曾', '佳友。\n金英辏。\n陶令篱边常宿留。\n秋风一夜摧枯朽。\n独艳重阳时候。\n剩收芳蕊浮卮酒。\n荐酒先生眉寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6636, '调笑・调笑令', '曾', '清友。\n群芳右。\n万缟纷披兹独秀。\n天寒月薄黄昏後。\n缟袂亭亭招手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6637, '调笑・调笑令', '曾', '净友。\n如妆就。\n折得清香来满手。\n一溪湛湛无尘垢。\n白羽轻摇晴昼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6638, '调笑・调笑令', '曾', '玉友。\n平生旧。\n相与忘形偏耐久。\n醉乡径到无何有。\n莫问区区升斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6639, '调笑・调笑令', '曾', '花好。\n被花恼。\n庭下嫣然如巧笑。\n曾教健步移根到。\n各是一般奇妙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6640, '调笑・调笑令', '曾', '酒美。\n直无比。\n小瓮新醅浮玉蚁。\n空传乌氏并程氏。\n不数云安曲米。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6641, '临江仙', '曾', '子後寅前东向坐，冥心琢齿鸣鼍。\n托天回顾眼光摩。\n张弓仍踏弩，升降辘轳多。\n三度朝元九度转，背摩双摆扳弩。\n虎龙交际咽元和。\n浴身挑甲罢，便可蹑烟萝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6642, '念奴娇', '张纲', '论思厌久，动莼鲈清兴，轻辞丹极。\n佩玉腰金归故里，光照湖山秋色。\n八座仪刑，九重尊宠，才大今词伯。\n汉家豪俊，一时谁是敌。\n三径旧日家声，华堂深稳处，频开瑶席。\n春在壶中真自有，一境珠宫仙掖。\n谭程挥风，罚筹如猬，数因尊前客。\n故应元放，举杯狂醉轻掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6643, '念奴娇', '张纲', '多情宋玉，值西风摇落，悲秋时节。\n赖有幽芳深解意，的枝头争发。\n欲语含羞，敛容微笑，心事如何说。\n暗香时度，卷帘留伴霜月。\n谁为赋写仙姿，挥毫落纸，有尊前词客。\n独倚阑干须信道，消得孤吟愁绝。\n补阙骚经，拾遗香传，顿许居前列。\n品题多谢，一枝当为君折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6644, '青门饮', '张纲', '疏柳飘零，暮鸦寒集，都门送客，斜阳影里。\n野色沈沈，翠微隐隐，遥指故乡云外。\n聚久交情厚，对西风、争忍分袂。\n饮散宾朋，画船去也，平芜千里。\n因记。\n小轩无寐。\n观夜月凭阑，共论深契。\n绛帐清闲，杏坛优暇，当念宴游同醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6645, '蓦山溪', '张纲', '小窗开宴，草草杯盘具。\n欢喜走儿童，庆生朝、一年一度。\n风光好处，恰是小春时，香泛泛，酒醺醺，一曲歌金缕。\n吾今已醉，解作醒时语。\n千里念重亲，望家山、云天尽处。\n深深发愿，只愿早休官，居颜巷，戏莱衣，岁岁长欢聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6646, '临江仙', '张纲', '绿蚁浮觞香泛泛，黄花共荐芳辰。\n清霜天宇净无尘。\n登高宜有赋，拈笔戏成文。\n可奈园林摇落尽，悲秋意与谁论。\n眼中相识几番新。\n龙山高会处，落帽定何人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6647, '临江仙', '张纲', '追想京都全盛日，蓬弧初记生时。\n朝来朱绂照庭闱。\n谁知衰谢老，还有宁馨儿。\n休记蓝田生美玉，举杯听取歌词。\n年方强仕未应迟。\n高风轻借便，一鹗看横飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6648, '满庭芳', '张纲', '十月风光，小春时候，宴堂初启朱筵。\n博山云润，风细袅晴烟。\n坐有文章公子，争吟唱、诗满花笺。\n帘帷里，时闻笑语，今日间生贤。\n郎潜。\n虽未贵，虚名自有，清议推先。\n更那堪、高堂重庆兼全。\n占取人间乐事，何必羡、玉带貂蝉。\n飞觞处，深深更祝，龟鹤永齐年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6649, '满庭芳', '张纲', '风轧云低，寒催腊近，画堂和气先春。\n玳筵处启，佳会庆生辰。\n漏转高张宝炬，重帘邃、深炷炉薰。\n欢声里，清歌闲发，一曲绕梁尘。\n慈闱，春不老，山河象服，恩被丝纶。\n占人间荣贵，兰玉诜诜。\n便好金尊尽醉，殷勤劝、须满十分。\n深深愿，斑衣拜舞，千岁奉灵椿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6650, '万年欢', '张纲', '岁晚寒凝，正冥舒四叶，梅吐孤芳。\n庆诞佳辰，开筵盛集萱堂。\n合坐春回锦绣，卷帘处、花簇笙簧。\n除乐禁、初许闻韶，应时欢宴何妨。\n人言富贵最好，算有谁能兼，福寿康强。\n自是仙姿，天教占取恩光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6651, '浣溪沙', '张纲', '罗绮争春拥画堂。\n翠帷深处按笙簧。\n宝奁频炷郁沈香。\n海上蟠桃元未老，月中仙桂看馀芳。\n何须龟鹤颂年长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6652, '浣溪沙', '张纲', '腊日银罂翠管新。\n潘舆迎腊庆生辰。\n卷帘花簇锦堂春。\n百和宝薰笼瑞雾，一声珠唱驻行云。\n流霞深劝莫辞频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6653, '浣溪沙', '张纲', '象服华年两鬓青。\n喜逢生日是嘉平。\n何妨开宴雪初晴。\n酒劝十分金凿落，舞催三叠玉娉婷。\n满堂欢笑祝椿龄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6654, '浣溪沙', '张纲', '过隙光阴还自催。\n生朝又送一年来。\n宴堂深处强追陪。\n眼眩岂堪花里笑，眉攒聊向酒边开。\n与君同醉莫辞杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6655, '点绛唇', '张纲', '飞雪初晴，晓来佳气生庭户。\n宝薰笼雾。\n帘幕香风度。\n鹤发龟龄，堂上潘舆驻。\n花深处。\n缓歌金缕。\n莫借杯频举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6656, '点绛唇', '张纲', '罗幕重重，画堂迎腊和风转。\n玳筵高展。\n知是群仙宴。\n银鸭香浮，红袖翻歌扇。\n金杯劝。\n深深祝愿。\n争把蟠桃献。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6657, '江城子', '张纲', '宝津楼下柳阴重。\n画桥东。\n戏鱼龙。\n闻喜当时，开宴盛仪容。\n遥想新年寻故事，扶醉帽，夕阳中。\n可怜衰鬓飒霜丛。\n借酡红。\n遣愁浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6658, '绿头鸭・多丽', '张纲', '敛晴烟。\n桂花如水轻寒。\n宴中秋、朋簪来会，满筵绿鬓朱颜。\n罄尊、兴吞海量，妙歌吹、声彻云端。\n独念衰残，强陪欢笑，恍然感旧觉悲酸。\n功名志，黄梁晓梦，老去奈何天。\n休追悔，天应教人，赢取身闲。\n想娥、情郎如旧，也须知我贪欢。\n奈潘鬓、霜蓬渐满，况沈腰、革带频宽。\n月有重圆，人谁长健，一回相见一回难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6659, '绿头鸭・多丽', '张纲', '爱家山。\n坐来心与云闲。\n念平生、功名有志，暮年多病知难。\n眷簪缨、未容引去，奈猿鹤、久已催还。\n松菊关情，莼鲈引兴，昔人高韵照尘寰。\n细追想，山林锺鼎，从古罕兼全。\n归来好，皇恩赐可，拂袖欣然。\n望西清、犹叨法从，梦魂宁隔台躔。\n莳七松、便为小隐，开三径、且乐馀年。\n宾友相过，鸡豚为具，从容聊作饮中仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6660, '感皇恩', '张纲', '解组盛明时，角巾东路。\n家在深村更深处。\n扫开三径，坐看一川烟雨。\n故山休笑我，来何暮。\n苦贪富贵，多忧多虑。\n百岁光阴能几许。\n醉乡日月，莫问人间寒暑。\n兴来随短棹，过南浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6661, '朝中措', '张纲', '年时生日宴高堂。\n欢笑拥炉香。\n今日山前停棹，也须随分飞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6662, '朝中措', '张纲', '前年初对大明宫。\n寒律转春风。\n几度相关归梦，催成两鬓霜蓬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6663, '朝中措', '张纲', '休惊初腊冻全消。\n旬日是春朝。\n梅吐芳心半笑，柳含青眼相撩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6664, '凤栖梧・蝶恋花', '张纲', '五日小春休屈指。\n花发西轩，早已传春意。\n应为高堂催燕喜。\n一枝得得来呈瑞。\n绮席初开云幕邃。\n兰蕙腾芳，人在蓬壶里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6665, '凤栖梧・蝶恋花', '张纲', '雨洗轩庭迎晚照。\n黄菊才芳，未觉秋光老。\n怪底烘堂添语笑。\n娥此夜来蓬岛。\n献寿新词谁解道。\n满眼儿孙，著语皆争巧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6666, '凤栖梧・蝶恋花', '张纲', '风动飞迎晓霁。\n银海光浮，宴启群仙会。\n骑省流芳谁可继。\n尊前看取连枝贵。\n华发衰翁羞晚岁。\n未报皇恩，尚忝专城寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6667, '凤栖梧・蝶恋花', '张纲', '老去光阴惊掣电。\n生长元丰，试数今谁健。\n多谢天公怜岁晚。\n清时乞得身闲散。\n忆昔生朝叨睿眷。\n台馈颁恩，内酒当筵劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6668, '凤栖梧・蝶恋花', '张纲', '缓带垂红双侍女。\n彩凤衔来，秀色生庭户。\n转蕙光风香暗度。\n回眸绰约神仙侣。\n寡和清歌声激楚。\n夜饮厌厌，劝我杯频举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6669, '好事近', '张纲', '梅柳约东风，迎腊暗传消息。\n粉面翠眉偷笑，似欣逢佳客。\n晚来歌管破馀寒，沈烟袅轻碧。\n老去不禁卮酒，奈尊前春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6670, '菩萨蛮', '张纲', '重帘卷尽楼台日。\n华灯万点欢声入。\n老病莫凭阑。\n一城星斗寒。\n艳妆翻舞雪。\n目眩红生缬。\n不是故无情。\n羞君双鬓青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6671, '菩萨蛮', '张纲', '南山只与溪桥隔。\n年来厌著寻山屐。\n卧对曲屏风。\n淡烟疏雨中。\n功成投老去。\n拚作林塘主。\n万事不关心。\n酒杯红浪生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6672, '清平乐', '张纲', '红莲照晚。\n花底明人眼。\n无限游人谁惜倦。\n只有衰翁心懒。\n笙歌缓引更筹。\n更阑客散添愁。\n香雾半窗幽梦，烟波千里归舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6673, '人月圆', '张纲', '封人祝望尧云了，归路蔼欢声。\n何妨明日，开筵笑语，聊庆初生。\n官闲岁晚身犹健，兰玉更盈庭。\n持杯为寿，从教夜醉，谁怕参横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6674, '西江月', '张纲', '易老方惊岁晚，难禁又报生朝。\n从他华发转萧萧。\n且共尊前一笑。\n为具随宜，烘堂不用笙箫。\n只烦欢伯散无。\n醉里追回年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6675, '惜分飞', '张纲', '年少春心花里转。\n只恐飞花片片。\n沈醉归深院。\n妓衣何用令高卷。\n要看梁州初入遍。\n放出楼中舞燕。\n有眼何曾见。\n看来未足重开宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6676, '减字木兰花', '张纲', '思堂醇酎。\n满酌金杯争献寿。\n记取年时。\n头白成双唱旧词。\n莫言秋晚。\n五日小春黄菊绽。\n折一枝来。\n纶诰金花要并开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6677, '孤雁儿・御街行', '李清照', '藤床纸帐朝眠起。\n说不尽、无佳思。\n沈香断续玉炉寒，伴我情怀如水。\n笛里三弄，梅心惊破，多少春情意。\n小风疏雨萧萧地。\n又催下、千行泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6678, '满庭霜・满庭芳', '李清照', '小阁藏春，闲窗锁昼，画堂无限深幽。\n篆香烧尽，日影下帘钩。\n手种江梅更好，又何必、临水登楼。\n无人到，寂寥浑似，何逊在扬州。\n从来，知韵胜，难堪雨籍，不耐风柔。\n更谁家横笛，吹动浓愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6679, '玉楼春', '李清照', '红酥肯放琼苞碎。\n探著南枝开遍未。\n不知酝藉几多香，但见包藏无限意。\n道人憔悴春窗底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6680, '渔家傲', '李清照', '雪里已知春信至。\n寒梅点缀琼枝腻。\n香脸半开娇旖旎。\n当庭际。\n玉人浴出新妆洗。\n造化可能偏有意。\n故教明月玲珑地。\n共赏金尊沈绿蚁。\n莫辞醉。\n此花不与群花比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6681, '清平乐', '李清照', '年年雪里。\n常插梅花醉。\n尽梅花无好意。\n赢得满衣清泪。\n今年海角天涯。\n萧萧两鬓生华。\n看取晚来风势，故应难看梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6682, '南歌子', '李清照', '天上星河转，人间帘幕垂。\n凉生枕簟泪痕滋。\n起解罗衣、聊问夜何其。\n翠贴莲蓬小，金销藕叶稀。\n旧时天气旧时衣。\n只有情怀、不似旧家时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6683, '转调满庭芳・满庭芳', '李清照', '芳草池塘，绿阴庭院，晚晴寒透窗纱。\n□□金锁，管是客来。\n寂寞尊前席上，惟□、海角天涯。\n能留否，酴落尽，犹赖有□□。\n当年，曾胜赏，生香薰袖，活火分茶。\n□□□龙骄马，流水轻车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6684, '渔家傲', '李清照', '天接云涛连晓雾。\n星河欲转千帆舞。\n彷佛梦魂归帝所。\n闻天语。\n殷勤问我归何处。\n我报路长嗟日暮。\n学诗谩有惊人句。\n九万里风鹏正举。\n风休住。\n蓬舟吹取三山去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6685, '如梦令', '李清照', '常记溪亭日暮。\n沈醉不知归路。\n兴尽晚回舟，误入藕花深处。\n争渡。\n争渡。\n惊起一滩鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6686, '如梦令', '李清照', '昨夜雨疏风骤。\n浓睡不消残酒。\n试问卷帘人，却道海棠依旧。\n知否。\n知否。\n应是绿肥红瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6687, '多丽', '李清照', '小楼寒，夜长帘幕低垂。\n恨萧萧、无情风雨，夜来揉损琼肌。\n也不似、贵妃醉脸，也不似、孙寿愁眉。\n韩令偷香，徐娘傅粉，莫将比拟未新奇。\n细看取、屈平陶令，风韵正相宜。\n微风起，清芬酝籍，不减酴。\n渐秋阑、雪清玉瘦，向人无限依依。\n似愁凝、汉皋解佩，似泪洒、纨扇题诗。\n朗月清风，浓烟暗雨，天教憔悴度芳姿。\n纵爱惜、不知从此，留得几多时。\n人情好，何须更忆，泽畔东篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6688, '菩萨蛮', '李清照', '风柔日薄春犹早。\n夹衫乍著心情好。\n睡起觉微寒。\n梅花鬓上残。\n故乡何处是。\n忘了除非醉。\n沈水卧时烧。\n香消酒未消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6689, '菩萨蛮', '李清照', '归鸿声断残云碧。\n背窗雪落炉烟直。\n烛底凤钗明。\n钗头人胜轻。\n角声催晓漏。\n曙色回牛斗。\n春意看花难。\n西风留旧寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6690, '浣溪沙', '李清照', '莫许杯深琥珀浓。\n未成沈醉意先融。\n□□已应晚来风。\n瑞脑香消魂梦断，辟寒金小髻鬟松。\n醒时空对烛花红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6691, '浣溪沙', '李清照', '小院闲窗春色深。\n重帘未卷影沈沈。\n倚楼无语理瑶琴。\n远岫出山催薄暮，细风吹雨弄轻阴。\n梨花欲谢恐难禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6692, '浣溪沙', '李清照', '淡荡春光寒食天。\n玉炉沈水袅残烟。\n梦回山枕隐花钿。\n海燕未来人斗草，江海已过柳生绵。\n黄昏疏雨湿秋千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6693, '凤凰台上忆吹箫', '李清照', '香冷金猊，被翻红浪，起来人未梳头。\n任宝奁闲掩，日上帘钩。\n生怕闲愁暗恨，多少事、欲说还休。\n今年瘦，非干病酒，不是悲秋。\n明朝，这回去也，千万遍阳关，也即难留。\n念武陵春晚，云锁重楼。\n记取楼前绿水，应念我、终日凝眸。\n凝眸处，从今更数，几段新愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6694, '一剪梅・一翦梅', '李清照', '红藕香残玉簟秋。\n轻解罗裳，独上兰舟。\n雪中谁寄锦书来，雁字回时，月满西楼。\n花自飘零水自流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6695, '蝶恋花', '李清照', '泪湿罗衣脂粉满。\n四叠阳关，唱到千千遍。\n人道山长山又断。\n萧萧微雨闻孤馆。\n惜别伤离方寸乱。\n忘了临行，酒盏深和浅。\n好把音书凭过雁。\n东来不似蓬莱远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6696, '蝶恋花', '李清照', '暖日晴风初破冻。\n柳眼眉腮，已觉春心动。\n酒意诗情谁与共。\n泪融残粉花钿重。\n乍试夹衫金缕缝。\n山枕斜，枕损钗头凤。\n独抱浓愁无好梦。\n夜阑犹剪灯花弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6697, '鹧鸪天', '李清照', '寒日萧萧上锁窗。\n梧桐应恨夜来霜。\n酒阑更喜团茶苦，梦断偏宜瑞脑香。\n秋已尽，日犹长。\n仲宣怀远更凄凉。\n不如随分尊前醉，莫负东篱菊蕊黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6698, '小重山', '李清照', '春到长门春草青。\n江梅些子破，未开匀。\n碧云笼碾玉成尘。\n留晓梦，惊破一瓯春。\n花影压重门。\n疏帘铺淡月，好黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6699, '怨王孙・忆王孙', '李清照', '湖上风来波浩渺。\n秋已暮、红稀香少。\n水光山色与人亲，说不尽、无穷好。\n莲子已成荷叶老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6700, '临江仙', '李清照', '庭院深深深几许，云窗雾阁常扃。\n柳梢梅萼渐分明。\n春归秣陵树，人客远安城。\n感月吟风多少事，如今老去无成。\n谁怜憔悴更凋零。\n试灯无意思，踏雪没心情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6701, '醉花阴', '李清照', '薄雾浓云愁永昼。\n瑞脑消金兽。\n佳节又重阳，玉枕纱厨，半夜凉初透。\n东篱把洒黄昏後，有暗香盈袖。\n莫道不消魂，帘卷西风，人似黄花瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6702, '好事近', '李清照', '风定落花深，帘外拥红堆雪。\n长记海棠开後，正是伤春时节。\n酒阑歌罢玉尊空，青缸暗明灭。\n魂梦不堪幽怨，更一声啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6703, '诉衷情', '李清照', '夜来沈醉卸妆迟。\n梅萼插残枝。\n酒醒熏破春睡，梦远不成归。\n人悄悄，月依依。\n翠帘垂。\n更残芯，更拈馀香，更得些时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6704, '行香子', '李清照', '草际鸣蛩。\n惊落梧桐。\n正人间、天上愁浓。\n云阶月地，关锁千重。\n纵浮槎来，浮槎去，不相逢。\n星桥鹊驾，经年才见，想离情、别恨难穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6705, '失调名', '李清照', '犹将歌扇向人遮。\n水晶山枕象牙床。\n彩云易散月长亏。\n几多深恨断人肠。\n罗衣消尽恁时香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6706, '鹧鸪天', '李清照', '暗淡轻黄体性柔。\n情疏迹远只香留。\n何须浅碧深红色，自是花中第一流。\n梅定妒，菊应羞。\n画阑开处冠中秋。\n骚人可煞无情思，何事当年不见收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6707, '添字丑奴儿・采桑子', '李清照', '窗前谁种芭蕉树，阴满中庭。\n阴满中庭。\n叶叶心心，舒卷有馀情。\n伤心枕上三更雨，点滴霖霪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6708, '忆秦娥', '李清照', '临高阁。\n乱山平野烟光薄。\n烟光薄。\n栖鸦归後，暮天闻角。\n断香残酒情怀恶。\n西风催衬梧桐落。\n梧桐落。\n又还秋色，又还寂寞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6709, '失调名', '李清照', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6710, '失调名', '李清照', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6711, '念奴娇', '李清照', '萧条庭院，有斜风细雨，重门须闭。\n宠柳娇花寒食近，种种恼人天气。\n险韵诗成，扶头酒醒，别是闲滋味。\n征鸿过尽，万千心事难寄。\n楼上几日春寒，帘垂四面，玉阑干慵倚。\n被冷香消新梦觉，不许愁人不起。\n清露晨流，新桐初引，多少游春意。\n日高烟敛，更看今日晴未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6712, '永遇乐', '李清照', '落日熔金，暮云合璧，人在何处。\n染柳烟浓，吹梅笛怨，春意知几许。\n元宵佳节，融和天气，次第岂无风雨。\n来相召、香车宝马，谢他酒朋诗侣。\n中州盛日，闺门多暇，记得偏重三五。\n铺翠冠儿，拈金雪柳，簇带争济楚。\n如今憔悴，风鬟霜鬓，怕见夜间出去。\n不如向、帘儿底下，听人笑语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6713, '武陵春', '李清照', '风住尘香花已尽，日晚倦梳头。\n物是人非事事休。\n欲语泪先流。\n闻说双溪春尚好，也拟泛轻舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6714, '怨王孙・忆王孙', '李清照', '帝里春晚。\n重门深院。\n草绿阶前，暮天雁断。\n楼上远信谁传。\n恨绵绵。\n多情自是多沾惹。\n难拚舍。\n又是寒食也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6715, '长寿乐', '李清照', '微寒应候。\n望日边六叶，阶初秀。\n爱景欲挂扶桑，漏残银箭，杓回摇斗。\n庆高闳此际，掌上一颗明珠剖。\n有令容淑质，归逢佳偶。\n到如今，昼锦满堂贵胄。\n荣耀，文步紫禁，一一金章绿绶。\n更值棠棣连阴，虎符熊轼，夹河分守。\n况青云咫尺，朝暮重入承明後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6716, '蝶恋花', '李清照', '永夜恹恹欢意少。\n空梦长安，认取长安道。\n为报今年春色好。\n花光月影宜相照。\n随意杯盘虽草草。\n酒美梅酸，恰称人怀抱。\n醉莫插花花莫笑。\n可怜春似人将老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6717, '声声慢', '李清照', '寻寻觅觅，冷冷清清，凄凄惨惨戚戚。\n乍暖还寒时候，最难将息。\n三杯两盏淡酒，怎敌他、晚来风急。\n雁过也，正伤心，却是旧时相识。\n满地黄花堆积。\n憔悴损，如今有谁摘。\n守著窗儿，独自怎生得黑。\n梧桐更兼细雨，到黄昏、点点滴滴。\n这次第，怎一个、愁字了得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6718, '点绛唇', '李清照', '寂寞深闺，柔肠一寸愁千缕。\n惜春春去。\n几点催花雨。\n倚遍阑干，只是无情绪。\n人何处。\n连天衰草，望断归来路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6719, '减字木兰花', '李清照', '卖花担上。\n买得一枝春欲放。\n泪染轻匀。\n犹带彤霞晓露痕。\n怕郎猜道。\n奴面不如花面好。\n云鬓斜簪。\n徒要教郎比并看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6720, '失调名', '李清照', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6721, '摊破浣溪沙・山花子', '李清照', '揉破黄金万点轻。\n剪成碧玉叶层层。\n风度精神如彦辅，大鲜明。\n梅蕊重重何俗甚，丁香千结苦粗生。\n熏透愁人千里梦，却无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6722, '摊破浣溪沙・山花子', '李清照', '病起萧萧两鬓华。\n卧看残月上窗纱。\n豆蔻连梢煎熟水，莫分茶。\n枕上诗书闲处好，门前风景雨来佳。\n终日向人多酝藉，木犀花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6723, '瑞鹧鸪', '李清照', '风韵雍容未甚都。\n尊前甘橘可为奴。\n谁怜流落江湖上，玉骨冰肌未肯枯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6724, '临江仙', '李清照', '庭院深深深几许，云窗雾阁春迟。\n为谁憔悴损芳姿。\n夜来清梦好，应是发南枝。\n玉瘦檀轻无限恨，南楼羌管休吹。\n浓香吹尽有谁知。\n暖风迟日也，别到杏花肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6725, '庆清朝', '李清照', '禁幄低张，彤阑巧护，就中独占残春。\n容华淡伫，绰约俱见天真。\n待得群花过後，一番风露晓妆新。\n妖娆艳态，妒风笑月，长东君。\n东城边，南陌上，正日烘池馆，竟走香轮。\n绮筵散日，谁人可继芳尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6726, '浣溪沙', '李清照', '髻子伤春慵更梳。\n晚风庭院落梅初。\n淡云来往月疏疏。\n玉鸭熏炉闲瑞脑，朱樱斗帐掩流苏。\n通犀还解辟寒无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6727, '浣溪沙', '李清照', '绣面芙蓉一笑开。\n斜飞宝鸭衬香腮。\n眼波才动被人猜。\n一面风情深有韵，半笺娇恨寄幽怀。\n月移花影约重来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6728, '采桑子', '吕本中', '恨君不似江楼月，南北东西。\n只有相随无别离。\n恨君却似江楼月，暂满还亏。\n暂满还亏。\n待得团团是几时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6729, '采桑子', '吕本中', '乱红夭绿风吹尽，小市疏楼。\n细雨轻鸥。\n总向离人恨里收。\n年年春好年年病，妾自西游。\n水自东流。\n不似残花一样愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6730, '西江月', '吕本中', '渺渺风吹月上，雾挟霜回。\n百年心事老相催。\n人在夕阳落外。\n有梦常嫌去远，无书可恨来迟。\n一杯浊酒两篇诗。\n小槛黄花共醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6731, '西江月', '吕本中', '酒罢悠扬醉兴。\n茶烹唤起醒魂。\n却嫌仙剂点甘辛。\n冲破龙团气韵。\n金鼎清泉乍泻，香沈微惜芳熏。\n玉人歌断恨轻分。\n欢意厌厌未尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6732, '朝中措', '吕本中', '病香无力傍栏干。\n风雨送春还。\n一枕晓来清梦，无人说似西山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6733, '南歌子', '吕本中', '驿路侵斜月，溪桥度晓霜。\n短篱残菊一枝黄。\n正是乱山深处、过重阳。\n旅枕元无梦，寒更每自长。\n只言江左好风光。\n不道中原归思、转凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6734, '虞美人', '吕本中', '梅花自是于春懒。\n不是春来晚。\n看伊开在众花前。\n便道与春无分、结因缘。\n风前月下频相就。\n笑我如伊瘦。\n几回冲雨过疏篱。\n已见一番青子、缀残枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6735, '虞美人', '吕本中', '平生臭味如君少。\n自是君难老。\n似侬憔悴更谁知。\n只道心情、不似少年时。\n春风也到江南路。\n小槛花深处。\n对人不是忆姚黄。\n实是旧时风味、老难忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6736, '浣溪沙', '吕本中', '暖日温风破浅寒。\n短青无数簇幽栏。\n三年春在病中看。\n中酒心情浑似梦，探花时候不曾闲。\n几年芳信隔秦关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6737, '浣溪沙', '吕本中', '共饮昏昏到暮鸦。\n不须春日念京华。\n迩来沈醉是生涯。\n不是对君犹惜醉，只嫌春病却怜他。\n愿为蜂采落残花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6738, '长相思', '吕本中', '要相忘。\n不相忘。\n玉树郎君月艳娘。\n几回曾断肠。\n欲下床。\n却上床。\n上得床来思旧乡。\n北风吹梦长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6739, '减字木兰花', '吕本中', '去年今夜。\n同醉月明花树下。\n此夜江边。\n月暗长堤柳暗船。\n故人何处。\n带我离愁江外去。\n来岁花前。\n又是今年忆去年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6740, '菩萨蛮', '吕本中', '客愁不到西池路。\n残春又逐花飞去。\n今日傍池行。\n新荷昨夜生。\n故人千虑绕。\n不道书来少。\n去住隔关河。\n长亭风雨多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6741, '菩萨蛮', '吕本中', '高楼只在斜阳里。\n春风淡荡人声喜。\n携客不嫌频。\n使君如酒醇。\n花光人不会。\n月色须君醉。\n月色与花光。\n共成今夜长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6742, '菩萨蛮', '吕本中', '登楼一望南山雪。\n使君风味如新月。\n月向雪前明。\n主人今夜情。\n平生相与意。\n老病犹堪记。\n对酒为君欢。\n酒杯嫌未宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6743, '踏莎行', '吕本中', '雪似梅花，梅花似雪。\n似和不似都奇绝。\n恼人风味阿谁知，请君问取南楼月。\n记得旧时，探梅时节。\n老来旧事无人说。\n为谁醉倒为谁醒，到今犹恨轻离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6744, '清平乐', '吕本中', '故人何处。\n同在江南路。\n百种旧愁分不去。\n枉被落花留住。\n旧愁百种谁知。\n除非是见伊时。\n最是一春多病，等闲过了酴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6745, '渔家傲', '吕本中', '小院悠悠春未远。\n牡丹昨夜开犹浅。\n珍重使君帘尽卷。\n风欲转。\n绿阴掩映栏干晚。\n记得旧时清夜短。\n洛阳芳讯时相伴。\n一朵姚黄髻满。\n情未展。\n新来衰病无人管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6746, '生查子', '吕本中', '残春雾雨馀，小院黄昏後。\n说道觅新词，把酒来相就。\n酴插髻云，岁岁长如旧。\n不是做词迟，却怕添伊瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6747, '满江红', '吕本中', '东里先生，家何在、山阴溪曲。\n对一川平野，数间茅屋。\n昨夜冈头新雨过，门前流水清如玉。\n抱小桥、回合柳参天，摇新绿。\n疏篱下，丛丛菊。\n虚檐外，萧萧竹。\n叹古今得失，是非荣辱。\n须信人生归去好，世间万事何时足。\n问此春、春酝酒何如，今朝熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6748, '浪淘沙', '吕本中', '柳色过疏篱。\n花又离披。\n旧时心绪没人知。\n记得一年寒食下，独自归时。\n归後却寻伊。\n月上嫌迟。\n十分斟酒不推辞。\n将为老来浑忘却，因甚沾衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6749, '浪淘沙', '吕本中', '柳塘新涨。\n艇子操双浆。\n闲倚曲楼成怅望。\n是处春愁一样。\n傍人几点飞花。\n夕阳又送栖鸦。\n试问画楼西畔，暮云恐近天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6750, '生查子', '吕本中', '双双小凤斜，淡淡鸦儿稳。\n一曲渭城歌，柳色饶春恨。\n离觞洗别愁，酒尽愁难尽。\n宝瑟雁纵横，谁寄天涯信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6751, '生查子', '吕本中', '人分南浦春，酒把阳关盏。\n衣带自无情，顿为离人缓。\n愁随苦海深，恨逐前峰远。\n更听断肠猿，一似闻弦雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6752, '蝶恋花', '吕本中', '巧语娇莺春未暮。\n杨柳风流，恰过池塘雨。\n芳草满庭花满树。\n无情胡蝶飞来去。\n睡起小奁香一缕。\n玉篆回纹，等个人分付。\n桃叶不言人不语。\n眉尖一点君知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6753, '鹧鸪天', '向子', '说著分飞百种猜。\n泥人细数几时回。\n风流可惯曾孤冷，怀抱如何得好开。\n垂玉箸，下香阶。\n凭肩小语更兜鞋。\n再三莫遣归期误，第一频教入梦来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6754, '鹧鸪天', '向子', '浅浅妆成淡淡梅。\n见梅忆着傍妆台。\n书无鸿雁如何寄，肠断催归作麽回。\n千种恨，百般猜。\n为伊怀抱几时开。\n可堪江上风头恶，不放朝云入梦来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6755, '鹧鸪天', '向子', '几处秋千懒未收。\n花梢柳外出纤柔。\n霞衣轻举疑奔月，宝髻倾若坠楼。\n争缥缈，斗风流。\n蜂儿蛱蝶共嬉游。\n朝朝暮暮春风里，落尽梨花未肯休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6756, '踏莎行', '向子', '霭霭朝云，矜春态度。\n楚宫梦断寻无路。\n欲将尊酒遣新愁，谁知引到愁深处。\n不尽长江，无边细雨。\n只疑都把愁来做。\n西山总不解遮栏，随春直过东湖去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6757, '鹊桥仙', '向子', '合风流，擘钗情态，压倒痴牛呆女。\n今年云外果深期，想却笑、人间离苦。\n萦愁叠恨，青山绿水，杳杳重重无数。\n寻常犹有梦能来，到此夜、无寻梦处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6758, '虞美人', '向子', '烟树无重数。\n不碍相思路。\n晚云分外欲增愁。\n更那堪疏雨、送归舟。\n雨来还被风吹去。\n陨泪多如雨。\n拟题双叶问离忧。\n怎得水随人意、肯西流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6759, '虞美人', '向子', '去年不到琼花底。\n蝶梦空相倚。\n今年特地趁花来。\n却甚不教同醉、过花开。\n花知此恨年年有。\n也伴人春瘦。\n一枝和泪寄春风。\n应把旧愁新怨、入眉峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6760, '虞美人', '向子', '去年雪满长安树。\n望断扬州路。\n今年看雪在扬州。\n人在蓬莱深处、若为愁。\n而今不恨伊相误。\n自恨来何暮。\n平山堂下旧嬉游。\n只有舞春杨柳、似风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6761, '虞美人', '向子', '倚窗人似莺藏柳。\n巧语春心透。\n声声清切入人深。\n一夜不知两鬓、雪霜侵。\n何时月下歌金缕。\n醉看行云住。\n懒将幽恨寄瑶琴。\n却倩金笼鹦鹉、递芳音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6762, '更漏子', '向子', '竹孤青，梅酽白。\n更着使君清绝。\n梅似竹，竹如君。\n须知德有邻。\n月同高，风同调。\n月底风前一笑。\n翻碎影，度微香。\n与人风味长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6763, '更漏子', '向子', '鹊桥边，牛渚上。\n翠节红旌相向。\n承玉露，御金风。\n年年岁岁同。\n懒飞梭，停弄杼。\n遥想彩云深处。\n人咫尺，事关山。\n无聊独倚栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6764, '鹊桥仙', '向子', '澄江如练，远山横翠，一段风烟如画。\n层楼杰阁倚晴空，疑便是、支矶石下。\n宝奁琼鉴，淡匀轻扫，纤手弄妆初罢。\n拟将心事问天公，与牛女、平分今夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6765, '南歌子', '向子', '碧落飞明镜，晴烟幂远山。\n扁舟夜下广陵滩。\n照我白苹红蓼、一杯残。\n初望同盘饮，如何两处看。\n遥知香雾湿云鬟。\n凭暖琼楼十二、玉栏干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6766, '鹊桥仙', '向子', '飞云多态，凉飕微度，都到酒边歌处。\n冰肌玉骨照人寒，更做弄、一帘风雨。\n同盘风味，合欢情思，不管星娥猜妒。\n桃花溪水接银河，与占断、鹊桥归路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6767, '南歌子', '向子', '缥缈云间质，轻盈波上身。\n瑶林玉树出风尘。\n不是野花凡草、等闲春。\n翠羽双垂珥，乌纱巧制巾。\n经珠不动两眉颦。\n须信铅华销尽、见天真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6768, '南歌子', '向子', '梁苑千花乱，隋堤一水长。\n眼前风物总悲凉。\n何况眉头心上、不相忘。\n因梦聊携手，凭书续断肠。\n已惊蝴蝶过东墙。\n更被风吹鸿雁、不成行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6769, '卜算子', '向子', '竹里一枝梅，雨洗娟娟静。\n疑是佳人日暮来，绰约风前影。\n新恨有谁知，往事何堪省。\n梦绕阳台寂寞回，沾袖馀香冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6770, '菩萨蛮', '向子', '鸳鸯翡翠同心侣。\n惊风不得双飞去。\n春水绿西池。\n重期相见时。\n长怜心共语。\n梦里池边路。\n相见不如新。\n花应解笑人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6771, '菩萨蛮', '向子', '娟娟明月如霜白。\n鳌山可是蓬山隔。\n恨不及春风。\n行云处处同。\n暖香红雾里。\n一笑谁新喜。\n知得远愁无。\n春衫有泪珠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6772, '菩萨蛮', '向子', '袜儿窄剪鞋儿小。\n纹鸳并影双双好。\n微步巧藏人。\n轻飞洛浦尘。\n前回深处见。\n欲近还相远。\n心事不能知。\n教人直是疑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6773, '南歌子', '向子', '雨过林峦静，风回池阁凉。\n窥人双燕语雕梁。\n笑看小荷翻处、戏鸳鸯。\n共饮菖蒲细，同分彩线长。\n今朝真不负风光。\n绝胜几年飞梦、绕高唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6774, '减字木兰花', '向子', '几年不见。\n胡蝶枕中魂梦远。\n一日相逢。\n鹦鹉杯深笑靥浓。\n欢心未已。\n流水落花愁又起。\n离恨如何。\n细雨斜风晚更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6775, '秦楼月・忆秦娥', '向子', '虫声切。\n柔肠欲断伤离别。\n伤离别。\n几行清泪，界残红颊。\n玉阶白露侵罗袜。\n下帘却望玲珑月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6776, '生查子', '向子', '月在两山间，人在空明里。\n山色碧於天，月色光於水。\n心闲物物幽，心动尘尘起。\n莫向动中来，长愿闲如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6777, '生查子', '向子', '春心如杜鹃，日夜思归切。\n啼尽一川花，愁落千山月。\n遥怜白玉人，翠被馀香歇。\n可惯独眠寒，减动丰肌雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6778, '生查子', '向子', '近似月当怀，远似花藏雾。\n好是月明时，同醉花深处。\n看花不自持，对月空相顾。\n愿学月频圆，莫作花飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6779, '生查子', '向子', '春山和恨长，秋水无言度。\n脉脉复盈盈，几点梨花雨。\n深深一段愁，寂寂无行路。\n推去又还来，没个遮栏处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6780, '生查子', '向子', '娟娟月入眉，整整云归鬓。\n镜里弄妆迟，帘外花移影。\n斜窥秋水长，软语春莺近。\n无计奈情何，只有相思分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6781, '生查子', '向子', '相思懒下床，春梦迷蝴蝶。\n入柳又穿花，去去轻如叶。\n可堪歧路长，不道关山隔。\n无赖是黄鹂，唤起空愁绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6782, '望江南・忆江南', '向子', '微雨过，庭院净无尘。\n天上秋期明日是，人间月影十分清，真不负佳辰。\n称寿处，香雾绕花身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6783, '浣溪沙', '向子', '冰雪肌肤不受尘。\n脸桃眉柳暖生春。\n手搓梅子笑迎人。\n欲语又休无限思，暂来还去不胜颦。\n梦随蝴蝶过东邻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6784, '西江月', '向子', '微步凌波尘起，弄妆满镜花开。\n春心掷处眼频来。\n秀色著人无耐。\n旧事如风无迹，新愁似水难裁。\n相思日夜梦阳台。\n减尽沈郎衣带。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6785, '点绛唇', '向子', '丹凤飞来，细传日下丝纶语。\n使君归去。\n已近沙堤路。\n风叶露花，秋意浓如许。\n江天暮。\n离歌轻举。\n愁满西山雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6786, '丑奴儿・采桑子', '向子', '无双亭下琼花树，玉骨云腴。\n倾国称姝。\n除却扬州是无处。\n天教红药来参乘，桃李先驱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6787, '如梦令', '向子', '午夜凉生翠幔。\n帘外行云撩乱。\n可恨白苹风，欲雨又还吹散。\n肠断。\n肠断。\n楚梦惊残一半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6788, '好事近', '向子', '小雨度微云，快染一天新碧。\n恰到中秋佳处，是芳年华日。\n冰轮莫做九分看，天意在今夕。\n先占广寒风露，怕娥偏得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6789, '好事近', '向子', '初上舞茵时，争看袜罗弓窄。\n恰似晚霞零乱，衬一钩新月。\n折旋多态小腰身，分明是回雪。\n生怕因风飞去，放真珠帘隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6790, '采桑子', '向子', '人如濯濯春杨柳，彻骨风流。\n脱体温柔。\n牵系多情尽未休。\n最怜恰恰新眠起，云雨初收。\n斜倚琼楼。\n叶叶眉心一样愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6791, '清平乐', '向子', '云无天净。\n明月端如镜。\n乌鹊绕枝栖未稳。\n零露垂垂珠陨。\n扁舟共绝潮河。\n秋风别去如梭。\n今夜凄然对影，与谁斟酌娥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6792, '浣溪沙', '向子', '花想仪容柳想腰。\n融融曳曳一团娇。\n绮罗丛里最妖娆。\n歌罢碧天零影乱，舞时红袖雪花飘。\n几回相见为魂销。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6793, '浣溪沙', '向子', '艳赵倾燕花里仙。\n乌丝阑写永和年。\n有时闲弄醒心弦。\n茗碗分云微醉後，纹楸斜倚髻鬟偏。\n风流模样总堪怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6794, '浣溪沙', '向子', '曾是襄王梦里仙。\n娇痴恰恰破瓜年。\n芳心已解品朱弦。\n浅浅笑时双靥媚，盈盈立处绿云偏。\n称人心是尽人怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6795, '浣溪沙', '向子', '一夜凉动碧厨。\n晓庭飞雨溅真珠。\n玉人睡起倚金铺。\n云髻作堆初未整，柳腰如醉不胜扶。\n天仙风调世间无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6796, '浣溪沙', '向子', '璧月光中玉漏清。\n小梅疏影水边明。\n似梅人醉月西倾。\n梅欲黄时朝暮雨，月重圆处短长亭。\n旧愁新恨若为情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6797, '浣溪沙', '向子', '人意天公则甚知。\n故教小雨作深悲。\n桃花浑似泪胭脂。\n理棹又从今日去，断肠还似去年时。\n经行处处是相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6798, '浣溪沙', '向子', '花样风流柳样娇。\n雪中微步过溪桥。\n心期春色到梅梢。\n折得一枝归绿鬓，冰容玉艳不相饶。\n索人同去醉金蕉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6799, '浣溪沙', '向子', '守得梅开著意看。\n春风几醉玉栏干。\n去时犹自惜馀欢。\n雨後重来花扫地，叶间青子已团团。\n凭谁寄与蹙眉山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6800, '浣溪沙', '向子', '翡翠衣裳白玉人。\n不将朱粉污天真。\n清风为伴月为邻。\n枕上解随良夜梦，壶中别是一家春。\n同心小绾更尖新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6801, '浣溪沙', '向子', '雨点春山入翠眉。\n一ь杨柳作腰肢。\n语音娇软带儿痴。\n犹省当来求识面，隔帘清唱倒琼彝。\n真成相见说当时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6802, '浣溪沙', '向子', '姑射肌肤雪一团。\n掺掺玉手弄冰纨。\n著人情思几多般。\n水上月如天样远，眼前花似镜中看。\n见时容易近时难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6803, '浣溪沙', '向子', '云外遥山是翠眉。\n风前杨柳入腰肢。\n凌波微步袜尘飞。\n倚醉传歌留客处，佯嗔不语人时。\n风流态度百般宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6804, '浣溪沙', '向子', '百斛明珠得翠娥。\n风流彻骨更能歌。\n碧云留住劝金荷。\n取醉归来因一笑，恼人深处是横波。\n酒醒情味却知麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6805, '相见欢', '向子', '亭亭秋水芙蓉。\n翠围中。\n又是一年风露、笑相逢。\n天机畔。\n云锦乱。\n思无穷。\n路隔银河犹解、嫁西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6806, '相见欢', '向子', '桃源深闭春风。\n信难通。\n流水落花馀恨、几时穷。\n水无定。\n花有尽。\n会相逢。\n可是人生长在、别离中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6807, '相见欢', '向子', '腰肢一缕纤长。\n是垂杨。\n泥泥风中衣袖、冷沈香。\n花如颊。\n眉如叶。\n语如簧。\n微笑微颦相恼、过回廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6808, '最高楼', '向子', '无双亭下，琼树正花敷。\n玉骨莹云腴。\n已知倾国无能比，除非天上有仙姝。\n到扬州才见，是处俱无。\n比碧桃、也无二朵，算丹桂、止是一株。\n千万卉，尽花奴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6809, '醉蓬莱', '吴穆仲', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6810, '南柯子・南歌子', '杨适2', '怨草迷南浦，愁花傍短亭。\n有情歌酒莫催行。\n看取无情花草、也关情。\n旧日临岐曲，而今忍泪听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6811, '江城子', '莫蒙', '长庚入梦夜何其。\n月波迟。\n露华滋。\n珠褓犀帷，生此宁馨儿。\n天上麒麟人不识，森，骏权奇。\n文章锦绣识新机。\n国风诗。\n楚人词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6812, '满庭霜・满庭芳', '李', '白玉肌肤，清冰神彩，仙妃何事烟村。\n自然标韵，羞入百花群。\n不易盈盈瘦质，犯寒腊、独作春温。\n溪桥外，斜枝半吐，行客一销魂。\n清香无处著，雪中暗认，月下空闻。\n算谁许幽人，相伴芳尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6813, '念奴娇', '韩驹', '海天向晚，渐霞收馀绮，波澄微绿。\n木落山高真个是，一雨秋容新沐。\n唤起嫦娥，撩云拨雾，驾此一轮玉。\n桂华疏淡，广寒谁伴幽独。\n不见弄玉吹箫，尊前空对此，清光堪掬。\n雾鬓风鬟何处问，云雨巫山六六。\n珠斗斓，银河清浅，影转西楼曲。\n此情谁会，倚风三弄横竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6814, '失调名', '韩驹', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6815, '西江月', '颜博文', '草草书传锦字，厌厌梦绕梅花。\n海山无计驻星槎。\n肠断芭蕉影下。\n缺月旧时庭院，飞云到处人家。\n而今赢得鬓先华。\n说著多情已怕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6816, '品令', '颜博文', '夜萧索。\n侧耳听、清海楼头吹角。\n停归棹、不觉重门闭，恨只恨、暮潮落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6817, '浣溪沙', '沈与求', '云幕垂垂不掩关，落鸿孤没有无间。\n雪花欺鬓一年残。\n欲把小梅还斗雪，冷香嫌怕乱沈檀。\n恼人归梦绕江干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6818, '浣溪沙', '沈与求', '花信催春入帝关。\n玉争腊去留间。\n不禁风力又吹残。\n客舍不眠清夜冷，萦愁一缕袅旃檀。\n空庭月落斗栏干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6819, '江城子', '沈与求', '华灯高宴水精宫。\n浪花中。\n意无穷。\n十载江湖，重绾汉符铜。\n应有青藜存往事，人缥缈，佩丁东。\n卧听萧寺响疏钟。\n渡溪风。\n转空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6820, '江城子', '沈与求', '鱼龙戏舞近幽宫。\n乱山中。\n似途穷。\n绿野堂深，门敞兽铺铜。\n无限青瑶攒峭壁，花木老，映西东。\n消磨万事酒千锺。\n一襟风。\n鬓霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6821, '秦刷子', '陈东', '谁斫碧琅，影撼半庭风月。\n尚有岁寒心在，留得数根华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6822, '西江月', '陈东', '风动一轩花竹，琅青锦薰笼。\n怜才自是宋墙东。\n更识琴心挑弄。\n暮雨乍收寒浅，朝云又起春浓。\n冰肌玉骨信俱融。\n不比巫山闲梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6823, '蓦山溪', '陈东', '半生羁旅，几度经元夜。\n长是竞虚名，把良宵、等闲弃舍。\n去年元夜，道得□身闲，依旧是，客长安，寂寞孤眠者。\n今年元夜。\n也则非乡社。\n却有人□约，携手□、灯前月下。\n那知风雨，此事又参差，成怨恨，独凄惶，清泪淆然洒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6824, '西江月', '陈东', '我笑牛郎织女，一年一度相逢。\n欢情尽逐晓云空。\n愁损舞莺歌凤。\n牛女而今笑我，七年独卧西风。\n西风还解过江东。\n为报佳期入梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6825, '念奴娇', '姚孝宁', '素娥睡起，驾冰轮碾破，一天秋绿。\n醉倚高楼风露下，凛凛寒生肌粟。\n横管孤吹，龙吟风劲，雪浪翻银屋。\n壮游回首，会稽何限修竹。\n今夜对月依然，尊前须快泻，山头鸣瀑。\n吸此清光倾肺腑，洗我明珠千斛。\n只恐蝉娟，明年依旧，衰鬓先成鹄。\n举杯相劝，为予且挂团玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6826, '石州词・石州慢', '胡松年', '月上疏帘，风射小窗，孤馆岑寂。\n一杯强洗愁怀，万里堪嗟行客。\n乱山无数，晚秋云物苍然，何如轻抹淮山碧。\n喜气拂征衣，作眉间黄色。\n役役。\n马头尘暗斜阳，陇首路回飞翼。\n梦里姑苏城外，钱塘江北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6827, '石州词・石州慢', '胡松年', '歌阕阳关，肠断短亭，惟有离别。\n画船送我薰风，瘦马迎人飞雪。\n平生幽梦，岂知塞北江南，而今真叹河山阔。\n屈指数分携，早许多时节。\n愁绝。\n雁行点点云垂，木叶霏霏霜滑。\n正是荒城落日，空山残月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6828, '明月逐人来', '李持正', '星河明淡。\n春来深浅。\n红莲正、满城开遍。\n禁街行乐，暗尘香拂面。\n皓月随人近远。\n天半鳌山，光动凤楼两观。\n东风静、珠帘不卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6829, '人月圆令・人月园', '李持正', '小桃枝上春风早，初试薄罗衣。\n年年乐事，华灯竞处，人月圆时。\n禁街箫鼓，寒轻夜永，纤手重携。\n更阑人散，千门笑语，声在帘帏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6830, '桃源忆故人', '王道亨', '刘郎自是桃花主。\n不许春风闲度。\n春色易随风去。\n片片伤春暮。\n返魂不用清香炷。\n却有梅花淡伫。\n从此镇长相顾。\n不怨飘残雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6831, '五福降中天', '江致和', '喜元宵三五，纵马御柳沟东。\n斜日映珠帘，瞥见芳容。\n秋水娇横俊眼，腻雪轻铺素胸。\n爱把菱花，笑匀粉面露春葱。\n徘徊步懒，奈一点、灵犀未通。\n怅望七香车去，慢辗春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6832, '清平乐', '韩璜', '秋光如水。\n酿作鹅黄蚁。\n散入千岩佳树里。\n惟许修门人醉。\n轻钿重上风鬟。\n不禁月冷霜寒。\n步障深沈归去，依然愁满江山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6833, '菩萨蛮', '李邦献', '薰沈刻蜡工夫巧。\n蜜脾锁碎金锺小。\n别是一般香。\n解教人断肠。\n冰霜相与瘦。\n清在江梅右。\n念我忍寒来。\n怜君特地开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6834, '眼儿媚', '宋齐愈', '霏霏疏影转征鸿。\n人语暗香中。\n小桥斜渡，西亭深院，水月朦胧。\n人间不是藏春处，玉笛晓霜空。\n江南树树，黄垂密雨，绿涨薰风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6835, '念奴娇', '宋江', '天南地北。\n问乾坤何处，可容狂客。\n借得山东烟水寨，来买凤城春色。\n翠袖围香，鲛绡笼玉，一笑千金值。\n神仙体态，薄幸如何销得。\n回想芦叶滩头，蓼花汀畔，皓月空凝碧。\n六六雁行连八九，只待金鸡消息。\n义胆包天，忠肝盖地，四海无人识。\n闲愁万种，醉乡一夜头白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6836, '撒金钱', '袁', '频瞻礼。\n喜升平、又逢元宵佳致。\n鳌山高耸翠。\n对端门、珠玑交制。\n似嫦娥降仙宫，乍临凡世。\n恩露匀施，凭御栏、圣颜垂视。\n撒金钱，乱抛坠。\n万姓推抢没理会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6837, '传言玉女', '袁', '眉黛轻分，惯学玉真梳掠。\n艳容可画，那精神怎貌。\n鲛绡映玉，钿带双穿缨络。\n歌音清丽，舞腰柔弱。\n宴罢瑶池，御风跨皓鹤。\n凤凰台上，有萧郎共约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6838, '念奴娇', '连仲宣', '暗黄著柳，渐寒威收敛，日和风细。\n□□端门初锡宴，郁郁葱葱佳气。\n太一行春，青藜照夜，夜色明如水。\n鳌山彩结，恍然移在平地。\n曲盖初展湘罗，玉皇香案，近雕阑十二。\n夹道红帘齐卷上，两行绝新珠翠。\n清跸声乾，传柑宴罢，闪闪星球坠。\n下楼归去，觚月衔龙尾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6839, '临江仙', '邢俊臣', '巍峨万丈与天高。\n物轻人意重，千里送鹅毛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6840, '临江仙', '邢俊臣', '远来犹自忆梁陈。\n江南无好物，聊赠一枝春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6841, '临江仙', '邢俊臣', '用心勤苦是新诗。\n吟安一个字，拈断数茎髭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6842, '临江仙', '邢俊臣', '扪窗摸户入房来。\n笙歌归院落，灯火下楼台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6843, '临江仙', '邢俊臣', '酥胸露出白皑皑。\n遥知不是雪，为有暗香来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6844, '临江仙', '邢俊臣', '只愁歌舞罢，化作彩云飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6845, '浪淘沙', '幼卿', '目送楚云空。\n前事无踪。\n谩留遗恨锁眉峰。\n自是荷花开较晚，孤负东风。\n客馆叹飘蓬。\n聚散匆匆。\n扬鞭那忍骤花骢。\n望断斜阳人不见，满袖啼红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6846, '减字木兰花', '蒋氏女', '朝云横渡。\n辘辘车声如水去。\n白草黄沙。\n月照孤村三两家。\n飞鸿过也。\n万结愁肠无昼夜。\n渐近燕山。\n回首乡关归路难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6847, '鹧鸪天', '蔡楠', '病酒厌厌与睡宜。\n珠帘罗幕卷银泥。\n风来绿树花含笑，恨入西楼月敛眉。\n惊瘦尽，怨归迟。\n休将桐叶更题诗。\n不知桥下无情水，流到天涯是几时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6848, '念奴娇', '蔡楠', '碧梧转影，正露冷天高，凉生襟袖。\n此夕清辉，谁信道、夜色居然如昼。\n玉斧重修，宝奁初启，万里寒光透。\n将军高会，翠鬟争劝尊酒。\n遥想地近仙丘，碧山高处，引手攀星斗。\n醉嘱娥，惟但愿、月与佳人长久。\n罗覆银鞍，雨抛金甲，赢得诗千首。\n掀髯一笑，此怀人解知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6849, '满庭芳', '蔡楠', '手染橙芗，杯摇烛影，夜阑人意醺酣。\n故人惜别，却酒更清谈。\n只合相从老矣，知何事、还著征衫。\n流年晚，长途匹马，奔走亦何堪。\n江潭。\n摇落後，云嘘绝壁，雪舞空岩。\n念行人归鬓，今已毵毵。\n往事真成梦里，十年恨、江北江南。\n休凝伫，霜风卷地，寒日又西衔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6850, '摊破诉衷情・诉衷情', '蔡楠', '夕阳低户水当楼。\n风烟惨淡秋。\n乱云飞尽碧山留。\n寒沙卧海鸥。\n浑似画，只供愁。\n相看空泪流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6851, '摊破诉衷情・诉衷情', '蔡楠', '栏干十二绕层楼。\n珠帘卷素秋。\n当年尊酒屡迟留。\n识公惟白鸥。\n才得趣，又成愁。\n情锺我辈流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6852, '凤栖梧・蝶恋花', '蔡楠', '狂滥生涯今几许。\n敕赐湖天，万顷烟波主。\n约我小舟同老去。\n要前一叶风掀舞。\n邂逅同寻溪上路。\n淡墨题诗，正在云深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6853, '念奴娇', '李久善', '东君试手，向南枝著意，争先时节。\n纵有丹青谁便忍，轻点肌肤冰雪。\n色借琼瑰，香分兰麝，元自标孤洁。\n冲寒独秀，误他多少蜂蝶。\n缟练不染缁尘，算来□合是，广寒宫阙。\n未问阳和先占取，前村一溪风月。\n留取清芬，主张真态，驿使休轻折。\n梢头青子，异时风味甚别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6854, '蝶恋花', '李久善', '莺掷垂杨，一点黄金溜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6855, '蓦山溪', '宝月', '清江平淡，疏雨和烟染。\n春在广寒宫，付江梅、先开素艳。\n年年第一，相见越溪东，云体态，雪精神，不把年华占。\n山亭水榭，别恨多销黯。\n又是主人来，更不辜、香心一点。\n题诗才思，清似玉壶冰，轻回顾，落尊前，桃杏声华减。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6856, '鹊踏枝・蝶恋花', '宝月', '斜日平山寒已薄。\n雪过松梢，犹有残英落。\n晚色际天天似幕。\n一尊先与东风约。\n邀得红梅同宴乐。\n酒面融春，春满纤纤萼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6857, '点绛唇', '宝月', '春遇瑶池，长空飞下残英片。\n素光围练。\n寒透笙歌院。\n莫把寿阳，妆信传书箭。\n掩香面。\n汉宫寻遍。\n月里还相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6858, '失调名', '宝月', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6859, '柳梢青', '宝月', '脉脉春心，情人渐远，难托离愁。\n雨後寒轻，风前香软，春在梨花。\n行人倚棹天涯。\n酒醒处、残阳乱鸦。\n门外秋千，墙头红粉，深院谁家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6860, '惜双双・惜分飞', '宝月', '庚岭香前亲写得。\n子细看、粉匀无迹。\n月殿休寻觅。\n姑射人来，知是曾相识。\n不要青春闲用力。\n也会寄、江南信息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6861, '洞仙歌', '宝月', '广寒晓驾，姑射寻仙侣。\n偷被霜华送将去。\n过越岭、栖息南枝，匀妆面、凝酥轻聚。\n爱横管孤度陇头声，尽拚得幽香，为君分付。\n水亭山驿，衰草斜阳，无限行人断肠处。\n尽为我、留得多情，何须待、春风相顾。\n任倒断深思向梨花，也无奈，寒食几番春雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6862, '念奴娇', '苏仲及', '问梅何事，对岩东微笑，暗中轻馥。\n韵绝姿高直下视，红紫端如童仆。\n绕树千回，临风三嗅，待与论心曲。\n何人还解，为伊特地青目。\n潇洒些个精神，谁怜孤瘦，正无语幽独。\n不许春知应自负，一生风月心足。\n傲雪难陪，欺霜无伴，耿耿横修竹。\n纷纷桃李，□□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6863, '远朝归', '赵耆孙', '金谷先春，见乍开江梅，晶明玉腻。\n珠帘院落，人静雨疏烟细。\n横斜带月，又别是、一般风味。\n金尊里。\n任遗英乱点，残粉低坠。\n惆怅杜陇当年，念水远天长，故人难寄。\n山城倦眼，无绪更看桃李。\n当时醉魄，算依旧、裴回花底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6864, '蓦山溪', '费时举', '黄苞初绽，谁向江头寄。\n天赋与清香，笑红颜、呈妖逞媚。\n低垂花面，不与众争妍，春尚未。\n先群卉。\n独禀中央气。\n何须施巧，点缀芳丛里。\n只恐暗寻香，误蜂儿、归来故垒。\n玉纤攀处，金钏色相宜，朔风寒，空雪坠。\n痛赏休辞醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6865, '梅花引', '刘均国', '千里月，千山雪。\n梅花正落寒时节。\n一枝昂。\n一枝藏。\n清香冷艳、天赋与孤光。\n孤光似被珠帘隔。\n风度烟遮好颜色。\n粉垂垂。\n玉累累。\n先春挺秀，不管百花知。\n似霜结。\n与霜别。\n莫使幽人容易折。\n短墙边。\n矮窗前。\n横斜峭影，重叠斗婵娟。\n黄昏惯听楼头角。\n只恐听时零乱落。\n醉来看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6866, '凤凰台忆吹箫・凤凰台上忆吹箫', '权无染', '水国云乡，冰魂雪魄，朝来新领春还。\n便未怕、天暄蜂蝶，笛转羌蛮。\n一树垂云似画，香暗暗、白浅红班。\n东风外，清新雪月，潇洒溪山。\n应是飞琼弄玉，天不管、年年谪向人间。\n占芳事，铅华一洗，红叶俱残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6867, '乌夜啼', '权无染', '洗尽铅华污，玉颜自发轻红。\n无言雪月黄昏後，别是个丰容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6868, '南歌子', '权无染', '照水金莲小，披风宝麝浮。\n雪中开占百花头。\n一味潇潇洒洒、自风流。\n病态含春瘦，芳魂傍月愁。\n轻烟微雨更清幽。\n遮莫姚黄相并、也应羞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6869, '南歌子', '权无染', '一点檀心紫，千重粉翅光。\n蔷薇水浸淡鹅黄。\n别是一般风韵、断人肠。\n有艳难欺雪，无花可此香。\n寻思无计与幽芳。\n除是玉人清瘦、道家妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6870, '孤馆深沈', '权无染', '琼英雪艳岭梅芳。\n天付与清香。\n向腊後春前，解压万花，先占东阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6871, '永遇乐', '南山居士', '满眼寒姿，桂蟾匀素，霜女同莹。\n野屋喷香，池波弄影，仿佛鸾窥镜。\n一枝堪寄，天涯远信，惆怅塞鸿难倩。\n这情怀、厌厌怎向，无人伴我孤另。\n风凄露冷。\n仙郎此夜，若许枕衾相并。\n解吐芳心，绸缪共约，学取双交颈。\n好天难遇，从今一去，荏苒後期无定。\n把柔肠、千萦万断，为伊薄幸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6872, '永遇乐', '南山居士', '玉骨冰肌，野墙山径，烟雨萧索。\n公子豪华，贪红恋紫，谁分怜孤萼。\n想应窥见，潘毛相似，故把素怀相托。\n岂知人、年来闷损，被名利拘缚。\n当歌对酒，如痴如梦，欲笑啼痕先落。\n二十年前，欢娱一醉，不忍思量著。\n衾寒枕冷，不教孤另，不是自家情薄。\n枉将心、千尤万，算应著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6873, '江神子・江城子', '郭仲宣', '腊寒犹重见年芳。\n为花忙。\n倚雕墙。\n准拟巡檐，一笑但清狂。\n冷蕊疏枝浑不奈，凭折取，泛清觞。\n扬州春梦两微茫。\n记娥妆。\n耿冰肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6874, '连理枝', '邵叔齐', '淡泊疏篱隔。\n寂寞官桥侧。\n绿萼青枝风尘外，别是一般姿质。\n念天涯、憔悴各飘零，记初曾相识。\n雪里清寒逼。\n月下幽香袭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6875, '扑蝴蝶', '邵叔齐', '兰摧蕙折，霜重晓风恶。\n长安何处，孤根谩自托。\n水寒断续溪桥，月破黄昏院落。\n相逢俨然瘦削。\n最萧索。\n星星蓬鬓，杳杳家山路正貌。\n攀枝嗅蕊，露陪清泪阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6876, '鹧鸪天', '邵叔齐', '不比江梅粉作华。\n天香肯作俗香夸。\n高悬蜡蓓蜂房密，遍挂金锺雁字斜。\n侵月影，上窗纱。\n中央颜色自仙家。\n玉人插向乌云畔，浑似灵犀正透芽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6877, '减兰十梅・减字木兰花', '李子正', '梅萼香嫩。\n雪里开时春粉润。\n雨蕊风枝。\n暗与黄昏取次宜。\n日边月下。\n休问初开兼欲谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6878, '减兰十梅・减字木兰花', '李子正', '东风吹暖。\n轻动枝头娇艳颤。\n成片惊飞。\n不是城南画角吹。\n香英飘处。\n定向寿阳妆阁去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6879, '减兰十梅・减字木兰花', '李子正', '潇潇细雨。\n雨歇芳菲犹淡伫。\n密洒轻笼。\n湿遍柔枝香更浓。\n琼腮微腻。\n疑是凝酥初点缀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6880, '减兰十梅・减字木兰花', '李子正', '六花飞素。\n飘入枝头无觅处。\n密缀轻堆。\n只似香苞次第开。\n栏边欲坠。\n姑射山头人半醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6881, '减兰十梅・减字木兰花', '李子正', '寒蟾初满。\n正是枝头开烂熳。\n素质笼明。\n多少风姿无限情。\n暗香疏影。\n冰麝萧萧山驿静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6882, '减兰十梅・减字木兰花', '李子正', '腾腾初照。\n半拆琼苞还似笑。\n莫近柔条。\n只恐凝酥暖欲消。\n三竿已上。\n点缀胭脂红荡漾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6883, '减兰十梅・减字木兰花', '李子正', '急催银漏。\n渐渐纱窗明欲透。\n点检花枝。\n晓笛吹时几片飞。\n淡烟初破。\n仿佛夜来飞几朵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6884, '减兰十梅・减字木兰花', '李子正', '天寒欲暮。\n别有一般姿媚处。\n半载斜阳。\n宝鉴微开试晚妆。\n淡烟轻处。\n渐近黄昏香暗渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6885, '减兰十梅・减字木兰花', '李子正', '阳和初布。\n入萼春红才半露。\n暖律潜催。\n与占百花头上开。\n香英微吐。\n折赠一枝人已去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6886, '减兰十梅・减字木兰花', '李子正', '香苞渐少。\n满地残英寒不扫。\n传语东君。\n分付南枝桃李春。\n东风吹暖。\n南北枝头开烂熳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6887, '忆秦娥', '房舜卿', '与君别。\n相思一夜梅花发。\n梅花发。\n凄凉南浦，断桥斜月。\n盈盈微步凌波袜。\n东风笑倚天涯阔。\n天涯阔。\n一声羌管，暮云愁绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6888, '玉交枝・忆秦娥', '房舜卿', '蕙死兰枯待返魂。\n暗香梅上又重闻。\n粉妆额子，多少画难真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6889, '鹧鸪天', '石耆翁', '借问枝头昨夜春。\n已传消息到柴门。\n频看秀色无多艳，拖得清香不见痕。\n山矗矗，水粼粼。\n村南村北冷销魂。\n人间不识春风面，羞见瑶台破月明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6890, '蝶恋花', '石耆翁', '半夜六龙飞海峤。\n漾鳌波，露出珊瑚小。\n玉粉枝头春意早。\n东风未绿瀛洲草。\n姑射仙人真窃窕。\n净练明妆，如伴商岩老。\n梦入水云闲缥缈。\n一楼明月千山晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6891, '西江月', '杜安道', '晓镜初妆玉粉，轻风暗递幽香。\n闲随月影到寒塘。\n忘却人间天上。\n雪意空惊春意，孤芳已断年芳。\n从教驿使为伊忙。\n乞个寿阳宫样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6892, '独脚令・忆王孙', '史远道', '墙头梅蕊一枝新。\n宋玉东邻算未真。\n折与冰姿绰约人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6893, '玉楼春', '郭仲循', '靓妆才学春无价。\n腮粉额黄宫样画。\n妖娆闲倚曲阑边，孤净不胜微月下。\n牵情群蕊临风亚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6894, '临江仙', '范梦龙', '试问前村深雪里，小梅未放云英。\n阳和先到锦官城。\n南枝初破粉，东阁有馀清。\n人在高楼横怨管，寄将陇客新声。\n西园下晚看飞琼。\n春风催结子，金鼎待调羹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6895, '渔家傲', '薛几圣', '雪月照梅溪畔路。\n幽姿背立无言语。\n冷浸瘦枝清浅处。\n香暗度。\n妆成处士横斜句。\n浑似玉人常淡伫。\n菱花相对成清楚。\n谁解小图先画取。\n天欲曙。\n恐随月色云间去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6896, '遂宁好', '马咸', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6897, '点绛唇', '洪皓', '不假施朱，鹤翎初试轻红亚。\n为栽堂下。\n更咏樵人画。\n绿叶青枝，辨认诗亏价。\n休催也。\n忍寒郊野。\n留待东坡马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6898, '点绛唇', '洪皓', '耐久芳馨，拟将蜂蜡龙涎亚。\n化工裁下。\n风韵胜如画。\n鼻观先通，顿减沈檀价。\n思量也。\n梦游吴野。\n凭仗神为马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6899, '减字木兰花', '洪皓', '蜂房馀液。\n写就南枝凌正色。\n折干垂芳。\n点缀如生秘暗香。\n寿阳妆样。\n纤手拈来簪髻上。\n恍若还家。\n暂睹真花压百花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6900, '蓦山溪', '洪皓', '鳌山凤阙，多少飞琼侣。\n俟翠华临，庆新春、金波盈五。\n莲灯开遍，侍从尽登楼，簪花赴。\n传柑处。\n咫尺聆天语。\n厌厌欲罢，宣劝犹旁午。\n扶上玉花骢，更踟蹰、梨园四部。\n追思往事，一夕九回肠，皇恩溥。\n归期阻。\n引领江南路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6901, '木兰花慢', '洪皓', '属三秋正半，暮云敛、月舒圆。\n误惊鹤鸣皋，栖乌绕树，魑魅惊旋。\n寻常对三五夜，纵清光、皎洁未精妍。\n须是风高气爽，一轮绝後光前。\n无偏。\n故国迢迢，千万里、共婵娟。\n但陟屺瞻驰，高楼念远，宁不凄然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6902, '木兰花慢', '洪皓', '对金商暮节，此时客、意难忘。\n正卉木凋零，蛩韵切，宾雁南翔。\n东篱有黄蕊绽，是幽人、最爱折浮觞。\n须信凌霜可赏，任他落帽清狂。\n茫茫。\n去国三年，行万里、过重阳。\n奈眷恋庭闱，矜怜幼稚，坠泪回肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6903, '浣溪沙', '洪皓', '丧乱佳辰不易攀。\n四逢寒食尽投闲。\n踏青无处想家山。\n麟殿阻趋陪内宴，萱堂遥忆侍慈颜。\n感时双泪滴潺潺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6904, '浣溪沙', '洪皓', '南北渝盟久未和。\n斯民涂炭死亡多。\n不知何日戢干戈。\n赖有兴王如世祖，况闻谋帅得廉颇。\n蔺卿全璧我蹉跎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6905, '临江仙', '洪皓', '冷落天涯今一纪，谁怜万里无家。\n三闾憔悴赋怀沙。\n思新增怅望，吊影觉斜。\n兀坐书堂真可怪，销忧酒难赊。\n因人成事耻矜夸。\n何时还使节，踏雪看梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6906, '江梅引・江城梅花引', '洪皓', '天涯除馆忆江梅。\n几枝开。\n使南来。\n还带馀杭、春信到燕台。\n准拟寒英聊慰远，隔山水，应销落，赴诉谁。\n空恁遐想笑摘蕊。\n断回肠，思故里。\n漫弹绿绮。\n引三弄、不觉魂飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6907, '江梅引・江城梅花引', '洪皓', '春还消息访寒梅。\n赏初开。\n梦吟来。\n映雪衔霜、清绝绕风台。\n可怕长洲桃李妒，度香远，惊愁眼，欲媚谁。\n曾动诗兴笑冷蕊。\n效少陵，惭下里。\n万株连绮。\n叹金谷、人坠莺飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6908, '江梅引・江城梅花引', '洪皓', '重闺佳丽最怜梅。\n牖春开。\n学妆来。\n争粉翻光、何遽落梳台。\n笑坐雕鞍歌古曲，催玉柱，金卮满，劝阿谁。\n贪为结子藏暗蕊。\n敛蛾眉，隔千里。\n旧时罗绮。\n已零散、沈谢双飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6909, '江梅引・江城梅花引', '洪皓', '去年湖上雪欺梅。\n片云开。\n月飞来。\n雪月光中、无处认楼台。\n今岁梅开依旧雪，人如月，对花笑，还有谁。\n一枝两枝三四蕊。\n想西湖，今帝里。\n彩笺烂绮。\n孤山外、目断云飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6910, '渔家傲', '洪皓', '臂上萸囊悬已满。\n杯中菊蕊浮无限。\n纵使登高宁忍看。\n昏复旦。\n心肠似铁还须断。\n岁月川流难把玩。\n平生万事思量遍。\n但对割愁山似剑。\n聊自劝。\n东坡海岛犹三见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6911, '渔家傲', '洪皓', '圃蕙庭桐凋大半。\n西风不借行人便。\n不用留题明月观。\n西园宴。\n颜酡浪说觞无算。\n万斛羁愁推不远。\n千杯鲁酒何曾见。\n却羡南宾凫与雁。\n行不乱。\n哀鸣直到翻江岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6912, '渔家傲', '洪皓', '□□□□□□□。\n□□□□□□□。\n□□□□□□□。\n□□□。\n□□□□□□□。\n正念当筵人已换。\n疏砧又捣谁家练。\n独坐愁吟搔首乱。\n肠欲断。\n凭高不见吴宫殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6913, '渔家傲', '洪皓', '侍宴乐游游赏惯。\n今兹吊影难呼伴。\n欲上望乡台复倦。\n愁满眼。\n琵琶莫写昭君怨。\n满目平芜无足玩。\n南冠未税徒增欢。\n万里庭闱安否断。\n形魂散。\n此身何暇穷游观。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6914, '忆仙姿・如梦令', '洪皓', '试问春归何处。\n蜂懒蝶忙来去。\n婉娩倦寻芳，偶遂涉园成趣。\n莺语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6915, '忆仙姿・如梦令', '洪皓', '乍到园亭清处。\n面面此君忘去。\n把酒挹幽人，仰止七贤高趣。\n吴语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6916, '忆仙姿・如梦令', '洪皓', '小憩书斋胡处。\n闲取响泉调去。\n是事不关心，自得曲中深趣。\n无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6917, '忆仙姿・如梦令', '洪皓', '燕敞画堂深处。\n夜艾不知归去。\n忍醉作歌词，要引遏云奇趣。\n娇语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6918, '水调歌头', '蔡伸', '醉击玉壶缺，恨写绿琴哀。\n悠悠往事谁问，离思渺难裁。\n绿野堂前桃李，燕子楼中歌吹，那忍首重回。\n唯有旧时月，远远逐人来。\n小庭空，清夜永，独徘徊。\n伴人幽怨，一枝潇洒陇头梅。\n肠断云帆西去，目送烟波东注，千里接长淮。\n为我将双泪，好过楚王台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6919, '水调歌头', '蔡伸', '亭皋木叶下，原隰菊花黄。\n凭高满眼秋意，时节近重阳。\n追想彭门往岁，千骑云屯平野，高宴古球场。\n吊古论兴废，看剑引杯长。\n感流年，思往事，重凄凉。\n当时坐间英俊，强半已凋亡。\n慨念平生豪放，自笑如今霜鬓，漂泊水云乡。\n已矣功名志，此意付清觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6920, '水调歌头', '蔡伸', '相逢非草草，分袂太匆匆。\n征裘泪痕遍，眸子怯酸风。\n天际孤帆难驻，柳外香望断，云雨各西东。\n回首重城远，楼观暮烟中。\n黯销魂，思陈事，已成空。\n东郊胜赏，归路骑马踏残红。\n月下一樽芳酒，凭阑几曲清歌，别後少人同。\n为问桃花脸，一笑为谁容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6921, '满庭芳', '蔡伸', '烟锁长堤，云横孤屿，断桥流水溶溶。\n凭阑凝望，远目送征鸿。\n桃叶溪边旧事，如春梦、回首无踪。\n难忘处，紫薇花下，清夜一尊同。\n东城，携手地，寻芳选胜，赏遍珍丛。\n念紫箫声阕，燕子楼空。\n好是卢郎未老，佳期在、端有相逢。\n重重恨，聊凭红叶，和泪寄西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6922, '满庭芳', '蔡伸', '风卷龙沙，云垂平野，晚来密雪交飞。\n坐看阑槛，琼蕊遍寒枝。\n妆点兰房景致，金铺掩、帘幕低垂。\n红炉畔，浅斟低唱，天色正相宜。\n更阑，人半醉，香肌玉暖，宝髻云。\n又何须高会，梁苑瑶池。\n堪笑子猷访戴，清兴尽、忍冻空回。\n仍休羡，渔人江上，披得一蓑归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6923, '满庭芳', '蔡伸', '鹦鹉洲边，芙蓉城下，迥然水秀山明。\n小舟双桨，特地访云英。\n惊破兰衾好梦，开朱户、一笑相迎。\n良宵永，南窗皓月，依旧照娉婷。\n别来，无限恨，持杯欲语，恍若魂惊。\n念霎时相见，又惨离情。\n还是匆匆去也，重携手、密语叮咛。\n佳期在，宝钗鸾镜，端不负平生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6924, '满庭芳', '蔡伸', '秦洞花迷，巫阳梦断，夜来曾到蓝桥。\n洞房深处，重许见云翘。\n惠帐残灯耿耿，纱窗外、疏雨萧萧。\n双心字，重衾小枕，玉困不胜娇。\n寻常，愁夜永，今宵更漏，弹指明朝。\n叙深情幽怨，泪香绡。\n记取于飞厚约，丹山愿、别选安巢。\n骖鸾去，青霄路稳，明月共吹箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6925, '满庭芳', '蔡伸', '玉鼎翻香，红炉叠胜，绮窗疏雨潇潇。\n故人相过，情话款良宵。\n酒晕微红衬脸，横波浸、满眼春娇。\n云屏掩，鸳鸯被暖，枕听寒潮。\n如今，成别恨，临风对月，总是无聊。\n念伤心南陌，执手河桥。\n还似一声春梦，离魂断、楚些难招。\n佳期在，踏青时候，花底听鸣镳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6926, '苏武慢', '蔡伸', '雁落平沙，烟笼寒水，古垒鸣笳声断。\n青山隐隐，败叶萧萧，天际暝鸦零乱。\n楼上黄昏，片帆千里归程，年华将晚。\n望碧云空暮，佳人何处，梦魂俱远。\n忆旧游、邃馆朱扉，小园香径，尚想桃花人面。\n书盈锦轴，恨满金徽，难写寸心幽怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6927, '飞雪满群山', '蔡伸', '冰结金壶，寒生罗幕，夜阑霜月侵门。\n翠筠敲竹，疏梅弄影，数声雁过南云。\n酒醒粲枕，怆犹有、残妆泪痕。\n绣衾孤拥，馀香未减，犹是那时熏。\n长记得、扁舟寻旧约，听小窗风雨，灯火昏昏。\n锦才展，琼签报曙，宝钗又是轻分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6928, '飞雪满群山', '蔡伸', '绝代佳人，幽居空谷，绮窗森玉猗猗。\n小舟双桨，重寻旧约，洞房宛是当时。\n夜阑红烛暗，黯相对、浑如梦里。\n旋烘鸳锦，尘生绣帐，香减缕金衣。\n须信有、盟言同皎日，□利牵名役，事与君违。\n□君已许，今生来世，两情到此奚疑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6929, '水龙吟', '蔡伸', '画桥流水桃溪路，别是壶中佳致。\n南楼夜月，东窗疏雨，金莲共醉。\n人静回廊，并肩携手，玉芝香里。\n念紫箫声断，巫阳梦觉，人何在、花空委。\n寂寞危栏独倚。\n望仙乡、水云无际。\n芸房花院，重来空锁，苍苔满地。\n物是人非，小池依旧，彩鸳双戏。\n念当时风月，如今怀抱有盈襟泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6930, '蓦山溪', '蔡伸', '孤城暮角，落日边声静。\n醉袖拂危阑，对天末、孤云愁凝。\n吴津楚望，表里抱江山，山隐隐，水迢迢，满目江南景。\n羁怀易感，往事伤重省。\n罗袂残香，鬓星星、忍窥清镜。\n琼英好在，应念玉关遥，凝泪眼，下层楼，回首平林暝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6931, '蓦山溪', '蔡伸', '疏梅雪里，已报东君信。\n冷艳与清香，似一个、人人标韵。\n晚来特地，酌酒慰幽芳，携素手，摘纤枝，插向乌云鬓。\n老来世事，百种皆消尽。\n荣利等浮云，谩汲汲、徒劳方寸。\n花前眼底，幸有赏心人，歌金缕，醉瑶卮，此外君休问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6932, '蓦山溪', '蔡伸', '书云今旦，雪霁严凝候。\n玉辇想回銮，正花覆、千官锦绣。\n周南留滞，清梦绕觚，心耿耿，路迢迢，此际空回首。\n华堂荐寿。\n玉笋持椒酒。\n一曲啭春莺，更祝我、膺时纳佑。\n功名富贵，老去已灰心，唯只愿，捧觞人，岁岁长依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6933, '蓦山溪', '蔡伸', '金风玉露，时节清秋候。\n散发步闲亭，对荧荧、一天星斗。\n悲歌慷慨，念远复伤时，心耿耿，发星星，倚杖空搔首。\n区区恋豆。\n岂是甘牛後。\n时命未来间，且只得、低眉袖手。\n男儿此志，肯向死前休，无限事，几多愁，总付杯中酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6934, '念奴娇', '蔡伸', '凌空宝观，乍登临、多少伤离情味。\n淼淼烟波吴会远，极目江淮无际。\n槛外长江，楼中红袖，淡荡秋光里。\n一声横吹，半滩鸥鹭起。\n因念邃馆香闺，玉肌花貌，有盈盈仙子。\n弄水题红传密意，宝墨银钩曾寄。\n泪粉香销，碧云□杳，脉脉人千里。\n一弯新月，断肠危栏独倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6935, '念奴娇', '蔡伸', '岁华晚，念羁怀多感，佳会难卜。\n草草杯盘聊话旧，同剪西窗寒烛。\n翠袖笼香，双蛾敛恨，低按新翻曲。\n无情风雨，断肠更漏催促。\n匆匆归骑难留，鸾屏鸳被，忍良宵孤宿。\n回首幽欢成梦境，唯觉衣襟芬馥。\n海约山盟，云情雨意，何日教心足。\n不如不见，为君一味愁蹙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6936, '念奴娇', '蔡伸', '画堂宴阕，望重帘不卷，轻哑朱户。\n悄悄回廊，惊渐闻、蟋蟀凌波微步。\n酒力融春，香风暗度，携手偎金缕。\n低低笑问，睡得真个稳否。\n因念隔阔经年，除非魂梦里，有时相遇。\n天意怜人心在了，岂信关山遐阻。\n晓色朦胧，柔情倦恋，後约叮咛语。\n休教肠断，楚台朝暮云雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6937, '念奴娇', '蔡伸', '当年豪放，况朋侪俱是，一时英杰。\n逸气凌云，佳丽地、独占春花秋月。\n冶叶倡条，寻芳选胜，是处曾攀折。\n昔游如梦，镜中空叹华发。\n邂逅萍梗相逢，十年往事，忍尊前重说。\n茂绿成阴春又晚，谁解丁香千结。\n宝瑟弹愁，玉壶敲怨，触目堪愁绝。\n酒阑人静，为君肠断时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6938, '念奴娇', '蔡伸', '轻雷骤雨，洗千岩浓翠，层峦森列。\n衣袂凉生，丛竹外、时有飞萤明灭。\n云浪鳞鳞，兰舟泛泛，共载一轮月。\n五湖当日，未应此段奇绝。\n归路横玉惊鸾，叫云清似水，悠扬天末。\n玉宇琼林凝望处，依约广寒宫阙。\n老去情锺，此心仍在，未肯甘华发。\n清欢留作，异时嘉话重说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6939, '雨中花慢', '蔡伸', '寓目伤怀，逢欢感旧，年来事事疏慵。\n叹身心业重，赋得情浓。\n况是离多会少，难忘雨迹云踪。\n断无锦字，双鳞杳杳，新雁雍雍。\n良宵孤枕，人远天涯，除非梦里相逢。\n相逢处，愁红敛黛，还又匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6940, '喜迁莺', '蔡伸', '青娥呈瑞。\n正惨惨暮寒，同云千里。\n剪水飞花，渐渐瑶英，密洒翠筠声细。\n邃馆静深，金铺半掩，重帘垂地。\n明窗外。\n伴疏梅潇洒，玉肌香腻。\n幽人当此际。\n醒魂照影，永漏愁无寐。\n强拊清尊，慵添宝鸭，谁会黯然情味。\n幸有赏心人，奈咫尺、重门深闭。\n今夜里。\n算忍教孤负，浓香鸳被。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6941, '忆瑶姬', '蔡伸', '微雨初晴。\n洗瑶空万里，月挂冰轮。\n广寒宫阙近，望素娥缥缈，丹桂亭亭。\n金盘露冷，玉树风轻。\n倍觉秋思清。\n念去年曾共吹箫侣，同赏蓬瀛。\n奈此夜、旅泊江城。\n谩花光眩目，绿酒如渑。\n幽怀终有恨，恨绮窗清影，虚照娉婷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6942, '丑奴儿慢・采桑子慢', '蔡伸', '明眸秀色，别是天真潇洒。\n更鬓发堆云，玉脸淡拂轻霞。\n醉里精神，众中标格谁能画。\n当时携手，花笼淡月，重门深亚。\n巫峡梦回，已成陈事，岂堪重话。\n谩赢得、罗襟清泪，鬓边霜华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6943, '满江红', '蔡伸', '人倚金铺，颦翠黛、盈盈堕睫。\n话别处、留连无计，语娇声咽。\n十幅云帆风力满，一川烟暝波光阔。\n但回首、极目望高城，弹清血。\n并兰舟，停画楫。\n曾共醉，津亭月。\n销魂处，今夜月圆人缺。\n楚岫云归空怅望，汉皋佩解成轻别。\n最苦是、拍塞满怀愁，无人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6944, '婆罗门引', '蔡伸', '素秋向晚，岁华分付木芙蓉。\n萧萧红蓼西风。\n记得当时撷翠，拥手绕芳丛。\n念吹箫人去，明月楼空。\n遥山万重。\n望寸碧、想眉峰。\n翠钿琼谩好，谁适为容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6945, '青玉案', '蔡伸', '参差弱柳长堤路。\n柳外征帆去。\n皓齿明眸娇态度。\n回头一梦，断肠千里，不到相逢地。\n来时约略春将暮。\n幽恨空馀锦中句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6946, '青玉案', '蔡伸', '鸾凰本是和鸣友。\n奈无计、长相守。\n云雨匆匆分袂後。\n彩舟东去，橹声呕轧，目断长堤柳。\n涓涓清泪轻绡透。\n残粉馀香尚依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6947, '浣溪沙', '蔡伸', '双佩雷文拂手香。\n青纱衫子淡梳妆。\n冰姿绰约自生凉。\n虚掉玉钗惊翡翠，缓移兰棹趁鸳鸯。\n鬓鬟风乱绿云长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6948, '浣溪沙', '蔡伸', '玉趾弯弯一折弓。\n秋波剪碧滟双瞳。\n浅颦轻笑意无穷。\n夜静拥炉熏督耨，月明飞棹采芙蓉。\n别来欢事少人同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6949, '浣溪沙', '蔡伸', '苹末风轻入夜凉。\n飞桥画阁跨方塘。\n月移花影上回廊。\n粲枕随钗云鬓乱，红绵扑粉玉肌香。\n起来携手看鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6950, '浣溪沙', '蔡伸', '窗外疏篁对节金。\n画桥新绿一篙深。\n沈沈清夜对横参。\n酒晕半消红玉脸，云鬟轻制小犀簪。\n梦回陈迹杳难寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6951, '浣溪沙', '蔡伸', '沙上寒鸥接翼飞。\n潮生潮落水东西。\n征船鸣橹趁潮归。\n望断碧云无锦字，谩题红叶有新诗。\n黄昏微雨倚阑时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6952, '浣溪沙', '蔡伸', '漠漠新田绿未齐。\n柳阴阴下水平堤。\n竹间时有乳鸦啼。\n云敛屏山横枕畔，夜阑璧月转林西。\n玉芝香里彩鸳栖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6953, '浣溪沙', '蔡伸', '紫燕双双掠水飞。\n廉纤小雨未成泥。\n篱边开尽野蔷薇。\n会少离多终有恨，暂来还去益堪悲。\n後期重约采莲时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6954, '浣溪沙', '蔡伸', '窄窄霜绡稳称身。\n强临歌酒惨离魂。\n故人相遇益伤神。\n断雨残云千里隔，琼枝璧月四时新。\n为君留取镜中春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6955, '浣溪沙', '蔡伸', '且斗尊前见在身。\n昔游如梦可销魂。\n玉容依约旧精神。\n千里重来人事改，一杯相属意还新。\n韶华不减洞中春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6956, '浣溪沙', '蔡伸', '木似文犀感月华。\n寸根移种自仙家。\n春兰秋菊浪矜夸。\n玉露初零秋夜永，幽香直入小窗纱。\n此时风月独输他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6957, '浣溪沙', '蔡伸', '叶剪玻璃芯糁金。\n清香端不数琼沈。\n独将高韵冠芗林。\n千里江山新梦後，一天风露小庭深。\n主人归兴已。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6958, '浣溪沙', '蔡伸', '浅褐衫儿寿带藤。\n碾花如意枕冠轻。\n凤鞋弓小称娉婷。\n约略梳妆随事好，出尘标韵出尘清。\n一枝梅映玉壶冰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6959, '浣溪沙', '蔡伸', '窗外桃花烂熳开。\n年时曾伴玉人来。\n一枝斜插凤皇钗。\n今日重来人事改，花前无语独徘徊。\n凄凉怀抱可怜哉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6960, '虞美人', '蔡伸', '瑶琴一弄清商怨。\n楼外桐阴转。\n月华澄淡露华浓。\n寂寞小池烟水、冷芙蓉。\n攀花撷翠当时事。\n绿叶同心字。\n有情还解忆人无。\n过尽寒沙新雁、甚无书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6961, '虞美人', '蔡伸', '飞梁石径关山路。\n惨淡秋容暮。\n一行新雁破寒空。\n肠断碧云千里、水溶溶。\n鸾衾欲展谁堪共。\n帘幕霜华重。\n鸭炉香尽锦屏中。\n幽梦今宵何许、与君同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6962, '虞美人', '蔡伸', '红尘匹马长安道。\n人与花俱老。\n缓垂鞭袖过平康。\n散尽高阳、零落少年场。\n朱弦重理相思调。\n无奈知音少。\n十年如梦尽堪伤。\n乐事如今、回首做凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6963, '虞美人', '蔡伸', '彩旗摇曳樯乌转。\n首征帆展。\n高城楼观暮云平。\n叠鼓凝笳都在、断肠声。\n绿窗朱户空回首。\n明月还依旧。\n乱山无数水茫茫。\n谁念塞垣风物、惶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6964, '虞美人', '蔡伸', '堆琼滴露冰壶莹。\n楼外天如镜。\n水晶双枕衬云鬟。\n卧看千山明月、听潺。\n渡江桃叶分飞後。\n马上犹回首。\n邮亭今夜月空圆。\n不似当时携手、对婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6965, '虞美人', '蔡伸', '碧溪曾寄流红字。\n忍话当时事。\n重来种种尽堪悲。\n有酒盈杯、聊为故人持。\n夜闲剪烛西窗语。\n怀抱今如许。\n尊前莫讶两依依。\n绿鬓朱颜、不似少年时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6966, '虞美人', '蔡伸', '鸾屏绣被香云拥。\n平帖幽闺梦。\n觉来重试古龙涎。\n深炷玉炉、烧气不烧烟。\n匆匆人去三更也。\n月到回廊下。\n出门无语送郎时。\n泪共一天风露、湿罗衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6967, '生查子', '蔡伸', '画堂初见伊，明月当满窗。\n今夜月如眉，话别河桥畔。\n重见约中秋，莫负于飞愿。\n免使月圆时，两处空肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6968, '生查子', '蔡伸', '霜寒月满窗，夜永人无寐。\n绛腊有馀情，偏照鸳鸯被。\n看尽旧时书，洒尽今生泪。\n衙鼓已三更，还是和衣睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6969, '生查子', '蔡伸', '金壶插玉芝，人面交相照。\n花影满方床，翠叠屏山杳。\n风月亦多情，特地今宵好。\n尽道夜初长，弹指东窗晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6970, '生查子', '蔡伸', '几番花信风，数点笼丝雨。\n并辔踏香尘，选胜东郊路。\n韶华转首空，谁解留春住。\n幸到绿尊前，且作莺花主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6971, '生查子', '蔡伸', '银缸委坠红，碧锁朦胧晓。\n别泪洒金徽，一曲情多少。\n邮亭今夜长，明月香帏悄。\n纵使梦相逢，何处寻蓬岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6972, '南歌子', '蔡伸', '萧寺疏锺断，虚堂夜气清。\n凉蟾偏向小明窗。\n露井碧梧寒叶、颤秋声。\n幽恨人谁问，孤衾泪独横。\n此时风月此时情。\n拟倩蓝桥归梦、见云英。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6973, '南歌子', '蔡伸', '远水澄明绿，孤云暗淡愁。\n白苹红蓼满汀洲。\n肠断圆蟾空照、木兰舟。\n节物伤羁旅，归程叹滞留。\n佳期已误小红楼。\n赖得今年犹有、闰中秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6974, '南歌子', '蔡伸', '恨入眉峰翠，寒生酒晕红。\n临期凝泪洒西风。\n须信世间无物、似情浓。\n玉蹬敲霜月，金钲伴晓锺。\n凄凉古驿乱山重。\n今夜拥衾无寐、与君同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6975, '南乡子', '蔡伸', '天外雨初收。\n风紧云轻已变秋。\n邂逅故人同一笑，迟留。\n聚散人生宜自谋。\n去路指南州。\n万顷云涛一叶舟。\n莫话太湖波浪险，归休。\n人在溪边正倚楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6976, '南乡子', '蔡伸', '木落雁南翔。\n锦鲤殷勤为渡江。\n泪墨银钩相忆字，成行。\n滴损云笺小凤皇。\n陈事费思量。\n回首烟波卷夕阳。\n尽道凭书聊破恨，难忘。\n及至书来更断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6977, '菩萨蛮', '蔡伸', '鸳鸯枕上云堆绿。\n兰膏微润知新沐。\n开帐对华灯。\n见郎双眼明。\n锦衾香馥郁。\n槛竹敲寒玉。\n何物最无情。\n晓鸡咿喔声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6978, '菩萨蛮', '蔡伸', '杏花零落清明雨。\n卷帘双燕来还去。\n枕上玉芙蓉。\n暖香堆锦红。\n翠翘金钿雀。\n蝉鬓慵疏掠。\n心事一春闲。\n黛眉颦远山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6979, '菩萨蛮', '蔡伸', '飞英不向枝头住。\n等闲又送春归去。\n云幄翠阴浮。\n长随日脚流。\n玉箫吹凤怨。\n惊起楼中燕。\n飞去自双双。\n恼人空断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6980, '菩萨蛮', '蔡伸', '水光山影浮空碧。\n柳丝摇曳春无力。\n柳岸系行舟。\n吹箫忆旧游。\n旧游堪更忆。\n望断迷南北。\n千古恨悠悠。\n长江空自流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6981, '菩萨蛮', '蔡伸', '当时携手今千里。\n可堪重到相逢地。\n触目尽关心。\n流莺尚好音。\n无人知我意。\n只有涓涓泪。\n寂寞到斜阳。\n罗衣旧香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6982, '菩萨蛮', '蔡伸', '鸣茄叠鼓催双桨。\n扁舟稳泛桃花浪。\n别泪洒东风。\n前欢如梦中。\n梦魂无定据。\n不到相逢处。\n纵使梦相逢。\n香闺岂解同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6983, '菩萨蛮', '蔡伸', '金铺半掩银瞻满。\n个人应恨归来晚。\n轧轧橹声迟。\n那知心已飞。\n迎门一笑粲。\n娇困横波慢。\n偎倚绿窗前。\n今宵人月圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6984, '菩萨蛮', '蔡伸', '双双紫燕来华屋。\n雨馀芳草池塘绿。\n一夜摆花风。\n莺花满树红。\n杯深君莫诉。\n醉袖歌金缕。\n无奈惜花心。\n老来情转深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6985, '菩萨蛮', '蔡伸', '朝来一陈狂风雨。\n春光已作堂堂去。\n茂绿满繁枝。\n青梅结子时。\n攀枝惊晚。\n乐事孤心眼。\n正是惜春归。\n那堪怨别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6986, '菩萨蛮', '蔡伸', '凝羞隔水抛红豆。\n嫩桃如脸腰如柳。\n心事暗明期。\n阳台云雨迷。\n玉楼花似雪。\n花上朦胧月。\n挥泪执柔荑。\n匆匆话别时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6987, '菩萨蛮', '蔡伸', '花冠鼓翼东方动。\n兰闺惊破辽阳梦。\n翠被小屏山。\n晓窗灯影残。\n并头双燕语。\n似诉横塘雨。\n风雨晓寒多。\n征人可奈何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6988, '忆秦娥', '蔡伸', '湖光碧。\n春花秋月无今昔。\n无今昔。\n十年往事，尽成陈迹。\n玉箫声断云屏隔。\n山遥水远长相忆。\n长相忆。\n一生怀抱，为君牵役。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6989, '忆秦娥', '蔡伸', '花阴月。\n兰堂夜宴神仙客。\n神仙客。\n江梅标韵，海棠颜色。\n良辰佳会诚难得。\n花前一醉君休惜。\n君休惜。\n楚台云雨，今夕何夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6990, '清平乐', '蔡伸', '彩舟双橹。\n六月临平路。\n小雨轻风消晚暑。\n绕岸荷花无数。\n玉人璨枕方床。\n遥知待月西厢。\n昨夜有情风月，今宵特地凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6991, '清平乐', '蔡伸', '南窗月满。\n绣被堆香暖。\n苦恨春宵更漏短。\n应讶郎归又晚。\n征帆初落桥边。\n迎门一笑嫣然。\n今夜流霞共酌，何妨金盏垂莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6992, '清平乐', '蔡伸', '明眸秀色。\n肌理凝香雪。\n罗绮丛中标韵别。\n捧酒歌声清越。\n不辞醉脸潮红。\n却愁归骑匆匆。\n回首绿窗朱户，断肠明月清风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6993, '谒金门', '蔡伸', '溪声咽。\n溪上有人离别。\n别语叮咛和泪说。\n罗巾沾泪血。\n尽做刚肠如铁。\n到此也应愁绝。\n回首断山帆影灭。\n画船空载月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6994, '谒金门', '蔡伸', '相思切。\n触目只供愁绝。\n好梦惊回清漏咽。\n烛残香穗结。\n长恨南楼明月。\n只解照人离缺。\n同倚朱栏飞大白。\n今宵风月别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6995, '忆王孙', '蔡伸', '凉生冰簟怯衣单。\n明月楼高空画栏。\n满院啼人未眠。\n掩重关。\n乌鹊南飞风露寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6996, '阮郎归', '蔡伸', '烟笼寒水暝禽栖。\n满庭红叶飞。\n兰堂寂寂画帘垂。\n霜浓更漏迟。\n鸳被冷，麝香微。\n强单枕时。\n西窗看尽月痕移。\n此情君怎知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6997, '柳梢青', '蔡伸', '数声。\n可怜又是，春归时节。\n满院东风，海棠铺绣，梨花飘雪。\n丁香露泣残枝，算未比、愁肠寸结。\n自是休文，多情多感，不干风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6998, '柳梢青', '蔡伸', '子规啼月。\n幽衾梦断，销魂时节。\n枕上斑斑，枝头点点，染成清血。\n凄凉断雨残云，算此恨、文君更切。\n老去情怀，春来况味，那禁离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (6999, '柳梢青', '蔡伸', '联璧寻春，踏青尚意，年时携手。\n此际重来，可怜还是，年时时候。\n阴阴柳下人家，人面桃花似旧。\n但原年年，春风有信，人心长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7000, '好事近', '蔡伸', '花露滴香红，花低漏声初歇。\n人似一枝梅瘦，照冰壶清彻。\n翠娥云鬓为谁容，虫丝宝奁结。\n可惜一春憔悴，负满怀风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7001, '好事近', '蔡伸', '十幅健帆风，天意巧催行客。\n极目五湖云浪，泛满空秋色。\n玉人应怪误佳期，凝恨正脉脉。\n锦鳞为传尺素，报兰舟消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7002, '卜算子', '蔡伸', '风雨送春归，寂寞花空委。\n枝上红稀地上多，万点随流水。\n翠黛敛春愁，照影临清。\n应念韶华惜颜，洒遍胭脂泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7003, '卜算子', '蔡伸', '小阁枕清流，一霎莲塘雨。\n风递幽香入槛来，枕簟全无暑。\n遐想似花人，阅岁音尘阻。\n物是人非空断肠，梦入芳洲路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7004, '卜算子', '蔡伸', '玉斧斫冰轮，中有乘鸾女。\n鬓乱钗横襟袖凉，只恐轻飞举。\n青冥缥缈间，自有吹箫侣。\n不向巫山十二峰，朝暮为云雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7005, '卜算子', '蔡伸', '前度月圆时，月下相携手。\n今夜天边月又圆，夜色如清昼。\n风月浑依旧。\n水馆空回首。\n明夜归来试问伊，曾解思量否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7006, '卜算子', '蔡伸', '重重雪外山，渺渺烟中路。\n路转山横无尽愁，正是分携处。\n望极锦中书，肠断鱼中素。\n锦素沈沈两未期，鱼雁空相误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7007, '卜算子', '蔡伸', '春事付莺花，曾是莺花主。\n醉拍春衫金缕衣，只向花间住。\n密意君听取。\n莫逐风来去。\n若是真心待于飞，云里千条路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7008, '小重山', '蔡伸', '楼外江山展翠屏。\n沈沈虹影畔，彩舟横。\n一尊别酒为君倾。\n留不住，风色太无情。\n斜日半山明。\n画栏重倚处，独销凝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7009, '小重山', '蔡伸', '澹澹秋容烟水寒。\n楼高清夜永，倚阑干。\n玉人不见坐长叹。\n箫声远，明月满空山。\n遐想绿云鬟。\n青冥风露冷，独乘鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7010, '小重山', '蔡伸', '流水桃花小洞天。\n壶中春不老，胜尘寰。\n霞衣鹤氅并桃冠。\n新装好，风韵愈飘然。\n功行满三千。\n婴儿并姹女，炼成丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7011, '小重山', '蔡伸', '楼上风高翠袖寒。\n碧云笼淡日，照阑干。\n绿杨芳草恨绵绵。\n长亭路，何处认征鞍。\n晓镜懒重看。\n鬓云堆凤髻，任阑珊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7012, '踏莎行', '蔡伸', '佩解江皋，魂消南浦。\n人生惟有别离苦。\n别时容易见时难，算来却是无情语。\n百计留君，留君不住。\n留君不住君须去。\n望君频问梦中来，免教肠断巫山雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7013, '踏莎行', '蔡伸', '如是我闻，金仙出世。\n一超直入如来地。\n慈悲方便济群生，端严妙相谁能比。\n四众归依，悉皆欢喜。\n有情同赴龙华会。\n无忧帐里结良缘，麽诃修哩修修哩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7014, '踏莎行', '蔡伸', '客里光阴，伤离情味。\n玉觞未举心先醉。\n临岐莫怪苦留连，樯乌转处人千里。\n恨写新声，云笺密寄。\n短封难尽心中事。\n凭君看取纸痕斑，分明总是离人泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7015, '踏莎行', '蔡伸', '落日归云，寒空断雁。\n吴波浅淡山平远。\n丹青写出在霜缣，佳人特地栽团扇。\n渔艇孤烟，酒旗幽院。\n些儿景趣君休羡。\n五湖归去共扁舟，何如早早酬深愿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7016, '踏莎行', '蔡伸', '水满青钱，烟滋翠葆。\n残英满地无人扫。\n先来羁思乱如云，无端更被春酲恼。\n叠叠遥山，绵绵远道。\n凭阑满目唯芳草。\n莫惊青鬓点秋霜，卢郎已分愁中老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7017, '踏莎行', '蔡伸', '玉质孤高，天姿明慧。\n了无一点尘凡气。\n白莲空殿锁幽芳，亭亭独占秋光里。\n一切见闻，不可思议。\n我今有分亲瞻礼。\n愿垂方便济众生，他时同赴龙华会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7018, '定风波', '蔡伸', '一曲骊歌酒一锺。\n可怜分袂太匆匆。\n百计留君留不住。\n□去。\n满川烟暝满帆风。\n目断魂销人不见。\n但见。\n青山隐隐水浮空。\n拟把一襟相忆泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7019, '定风波', '蔡伸', '老去情锺不自持。\n花酌酒送春归。\n玉貌冰姿人窈窕。\n一笑。\n清狂岂减少年时。\n欲上香车俱脉脉，半帘花影月平西。\n待得酒醒人已去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7020, '点绛唇', '蔡伸', '水绕孤城，乱山深锁横江路。\n帆归别浦。\n苒苒兰皋暮。\n人在天涯，雁背南云去。\n空凝伫。\n凤楼何处。\n烟霭迷津渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7021, '点绛唇', '蔡伸', '香雪飘零，暖风著柳笼丝雨。\n恼人情绪。\n春事还如许。\n宝勒朱轮，共结寻芳侣。\n东郊路。\n乱红深处。\n醉拍黄金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7022, '点绛唇', '蔡伸', '背壁灯残，卧听檐雨难成寐。\n井梧飘坠。\n历历蛩声细。\n数尽更筹。\n滴尽罗巾泪。\n如何睡。\n甫能得睡。\n梦到相思地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7023, '点绛唇', '蔡伸', '月缺花残，世间乐事难双美。\n夜来相对。\n把酒弹轻泪。\n一点情锺，销尽英雄气。\n樊笼外。\n五湖烟水。\n好作扁舟计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7024, '点绛唇', '蔡伸', '玉笋持杯，敛红颦翠歌金缕。\n彩鸳戢羽。\n未免群鸡妒。\n我为情多，愁听多情语。\n君休诉。\n两心坚固。\n云里千条路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7025, '点绛唇', '蔡伸', '人面桃花，去年今日津亭见。\n瑶琴锦荐。\n一弄清商怨。\n金日重来，不见如花面。\n空肠断。\n乱红千片。\n流水天涯远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7026, '点绛唇', '蔡伸', '梅雨初晴，画栏开遍忘忧草。\n兰堂清窈。\n高柳新蝉噪。\n枕上芙蓉，如梦还惊觉。\n匀妆了。\n背人微笑。\n风入玲珑罩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7027, '点绛唇', '蔡伸', '帐外华灯，翠屏花影参差满。\n锦衣香暖。\n苦恨春宵短。\n画角声中，云雨还轻散。\n河桥畔。\n月华如练。\n回首成肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7028, '点绛唇', '蔡伸', '绿萼冰花，数枝清影横疏牖。\n玉肌清瘦。\n夜久轻寒透。\n忍使孤芳，攀折他人手。\n人归後。\n断肠回首。\n只有香盈袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7029, '点绛唇', '蔡伸', '解绂朝天，满城桃李繁阴市。\n彩舟难驻。\n忍听骊歌举。\n协赞中兴，圣意方倾注。\n从今去。\n五云深处。\n稳步沙堤路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7030, '点绛唇', '蔡伸', '云雨匆匆，洞房当日曾相遇。\n暂来还去。\n无计留春住。\n宝瑟重调，静听莺弦语。\n休轻负。\n绮窗朱户。\n好做风光主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7031, '昭君怨', '蔡伸', '一曲云和松响。\n多少离愁心上。\n寂寞掩屏帷。\n泪沾衣。\n最是销魂处。\n夜夜绮窗风雨。\n风雨伴愁眠。\n夜如年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7032, '醉落魄・一斛珠', '蔡伸', '波纹如。\n池塘雨後添新绿。\n海棠初绽红生肉。\n双燕归来，还认旧巢宿。\n凝情凭暖阑干曲。\n新愁无限伤心目。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7033, '醉落魄・一斛珠', '蔡伸', '霜华摇落。\n亭亭皓月侵朱箔。\n梦回枕听残角。\n一片寒声，风送入寥廓。\n眼前风月都如昨。\n独眠无奈情怀恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7034, '醉落魄・一斛珠', '蔡伸', '明眸秀色。\n双蛾巧画春山碧。\n盈盈标韵倾瑶席。\n一见尊前，宛是旧相识。\n深期密语虽端的。\n良宵无奈成轻掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7035, '醉落魄・一斛珠', '蔡伸', '阳关声咽。\n清歌响断云屏隔。\n溪山依旧连空碧。\n昨日主人，今日是行客。\n绿窗朱户应如昔。\n回头往事成陈迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7036, '极相思', '蔡伸', '碧檐鸣玉玎。\n金锁小兰房。\n楼高夜永，飞霜满院，璧月沈缸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7037, '极相思', '蔡伸', '相思情味堪伤。\n谁与话衷肠。\n明朝见也，桃花人面，碧藓回廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7038, '玉楼春', '蔡伸', '碧桃溪上蓝桥路。\n寂寞朱门闲院宇。\n粉墙疏竹弄清蟾，玉砌红蕉宜夜雨。\n个中人是吹箫侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7039, '玉楼春', '蔡伸', '星河风露经年别。\n月照离亭花似雪。\n宝钗鸾镜会重逢，花里同眠今夜月。\n月华依旧当时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7040, '长相思', '蔡伸', '我心坚。\n你心坚。\n各自心坚石也穿。\n谁言相见难。\n小窗前。\n月婵娟。\n玉困花柔并枕眠。\n今宵人月圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7041, '长相思', '蔡伸', '锦衾香。\n玉枕双。\n昨夜深深小洞房。\n回头已断肠。\n背兰缸。\n梦仙乡。\n风撼梧桐雨洒窗。\n今宵好夜长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7042, '长相思', '蔡伸', '村姑儿。\n红袖衣。\n初发黄梅插稻时。\n双双女伴随。\n长歌诗。\n短歌诗。\n歌里真情恨别离。\n休言伊不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7043, '西地锦', '蔡伸', '寂寞悲秋怀抱。\n掩重门悄悄。\n清风皓月，朱阑画阁，双鸳池沼。\n不忍今宵重到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7044, '归田乐', '蔡伸', '风生苹末莲香细。\n新浴晚凉天气。\n犹自倚朱阑，波面双双彩鸳戏。\n鸾钗委坠云堆髻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7045, '七娘子', '蔡伸', '天涯触目伤离绪。\n登临况值秋光暮。\n手拈黄花，凭谁分付。\n雍雍雁落蒹葭浦。\n凭高目断桃溪路。\n屏山楼外青无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7046, '感皇恩', '蔡伸', '酒晕衬横波，玉肌香透。\n轻袅腰肢妒垂柳。\n臂宽金钏，且是不干春瘦。\n拈金双合字，无心绣。\n云半堕，金钗欲溜。\n罗袂残香忍重嗅。\n渡江桃叶，肠断为谁招手。\n倚阑凝望久，眉空斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7047, '感皇恩', '蔡伸', '膏雨晓来晴，海棠红透。\n碧草池塘袅金柳。\n王孙何在，不念玉容消瘦。\n日长深院静，帘垂绣。\n璨枕堕钗，粉痕轻溜。\n玉鼎龙涎记同嗅。\n钿筝重理，心事谩凭纤手。\n素弦弹不尽，眉峰斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7048, '减字木兰花', '蔡伸', '彤庭龙尾。\n礼备天颜知有喜。\n九奏初传。\n耳冷人间十七年。\n盈成持守。\n仁德如春渐九有。\n三辅名州。\n好整笙歌结胜游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7049, '减字木兰花', '蔡伸', '船回沙尾。\n几误红窗听鹊喜。\n尺素空传。\n转首相逢又隔年。\n寒灯独守。\n玉笋持杯宁复有。\n秀水南州。\n徒使幽人作梦游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7050, '减字木兰花', '蔡伸', '多情多病。\n玉貌疲来愁览镜。\n门掩东风。\n零落桃花满地红。\n重帘不卷。\n愁睹杏梁双语燕。\n强拂瑶琴。\n一曲幽兰泪满襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7051, '减字木兰花', '蔡伸', '金风玉露。\n喜鹊桥成牛女渡。\n天宇沈沈。\n一夕佳期两意深。\n琼签报曙。\n忍使飙轮容易去。\n明日如今。\n想见君心似我心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7052, '减字木兰花', '蔡伸', '锦屏人醉。\n玉暖香融春有味。\n今日兰舟。\n魂梦还随绿水流。\n高城望断。\n无奈城中人不见。\n斜倚妆楼。\n恨入眉峰两点愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7053, '渔家傲', '蔡伸', '烟锁池塘秋欲暮。\n细细前香，直到双栖处。\n并枕东窗听夜雨。\n偎金缕。\n云深不见来时路。\n晓色朦胧人去住。\n香覆重帘，密密闻私语。\n日断征帆归别浦。\n空凝伫。\n苔痕绿印金莲步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7054, '西楼子・相见欢', '蔡伸', '楼前流水悠悠。\n驻行舟。\n满目寒云衰草、使人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7055, '西楼子・相见欢', '蔡伸', '红靴玉带葳蕤。\n翠绡衣。\n并辔垂鞭妆影、照清溪。\n长亭路。\n停骑处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7056, '御街行', '蔡伸', '东君不锁寻芳路。\n曾是莺花主。\n有情风月可怜宵，犹记绿窗朱户。\n十年空想，春风面杳，无计凭鳞羽。\n凄凉怀抱今如许。\n天与重相遇。\n不应还向楚峰前，朝暮为云为雨。\n算来各把，平生分付，也不是、恶著处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7057, '上阳春・蓦山溪', '蔡伸', '好在章台杨柳。\n不禁春瘦。\n淡烟微雨曲尘丝，锁一点、眉头皱。\n忆自灞陵别後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7058, '临江仙', '蔡伸', '繁杏枝头蜂蝶乱，香风阖坐微闻。\n靓妆浓艳任东君。\n无情风雨，春事已平分。\n珍重主人留客意，夜阑秉烛开尊。\n何须歌韵遏行云。\n羽觞交劝，挥麈细论文。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7059, '临江仙', '蔡伸', '昨夜中秋今夕望，十分桂影团圆。\n玉人相对绿尊前。\n素娥有恨，应是妒蝉娟。\n人静小庭风露冷，歌声特地清圆。\n醉红醺脸髻鬟偏。\n翠裙轻皱，端的为留仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7060, '临江仙', '蔡伸', '帘幕深深清昼永，玉人不耐春寒。\n镂牙棋子缕金圆。\n象盘雅戏，相对小窗前。\n隔打直行尖曲路，教人费尽机关。\n局中胜负定谁偏。\n饶伊使幸，毕竟我赢先。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7061, '临江仙', '蔡伸', '仙品不同桃李艳，移来月窟云乡。\n幽姿绰约道家妆。\n绿云堆髻，娇额半涂黄。\n可但乍凉风月下，饶伊独占秋光。\n雨中别有恼人香。\n错教萧史，肠断忆巫阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7062, '临江仙', '蔡伸', '琪树鸾栖花露重，依稀兰洞风光。\n玉人相对自生凉。\n翠鬟琼佩，绰约蕊珠妆。\n宝瑟声沈清梦觉，夜阑明月幽窗。\n可堪襟袂惹馀香。\n断云残雨，何处认高唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7063, '临江仙', '蔡伸', '记得南楼三五夜，曾听凤管昭华。\n曾前此际重兴嗟。\n素娥端有恨，烟霭等闲遮。\n珍重主人留客意，厌厌缓引流霞。\n夜间银汉淡天涯。\n亭亭丹桂现，耿耿玉绳斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7064, '临江仙', '蔡伸', '青润奇峰名韫玉，温其质并琼瑶。\n中分瀑布泻云涛。\n双峦呈翠色，气象两相高。\n珍重幽人诚好事，绿窗聊助风骚。\n寄言俗客莫相嘲。\n物轻人意重，千里赠鹅毛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7065, '鹧鸪天', '蔡伸', '脉脉柔情不自持。\n浅颦轻笑百般宜。\n尊前唱歇黄金缕，一点春愁入翠眉。\n流蕙盼，捧瑶卮。\n借君歌扇写新诗。\n浮花谩说惊郎目，不似东风第一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7066, '惜奴娇', '蔡伸', '隔阔多时，算彼此、难存济。\n咫尺地、千山万水。\n眼眼相看，要说话、都无计。\n只是。\n唱曲儿、词中认意。\n雪意垂垂，更刮地、寒风起。\n怎禁这几夜意。\n未散痴心，便指望、长偎倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7067, '行香子', '蔡伸', '珠露初零。\n天宇澄明。\n正闲阶、皎月亭亭。\n更阑人静，烟敛风清。\n更井边桐，一叶叶，做秋声。\n斗帐鸾屏。\n翠被华茵。\n梦回时、酒力初醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7068, '一翦梅', '蔡伸', '堆枕乌云堕翠翘。\n午梦惊回，满眼春娇。\n一袅楚宫腰。\n那更春来，玉减香消。\n柳下朱门傍小桥。\n几度红窗，误认鸣镳。\n断肠风月可怜宵。\n忍使恹恹，两处无聊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7069, '一翦梅', '蔡伸', '高宴华堂夜向阑。\n急管飞霜，羯鼓声乾。\n仙人掌上水晶盘。\n回按凌波，舞袖弓弯。\n曲罢凝娇整翠鬟。\n玉笋持杯，巧笑嫣然。\n为君一醉倒金船。\n只恐醒来，人隔云山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7070, '一翦梅', '蔡伸', '夜永虚堂烛影寒。\n斗转春来，又是明年。\n异乡怀抱只凄然。\n尊酒相逢且自宽。\n天际孤云云外山。\n梦绕觚，日下长安。\n功名已觉负初心，羞对菱花，绿鬓成斑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7071, '六么令', '蔡伸', '梅英飘雪，弱柳弄新绿。\n泠泠画桥流水，风静波如。\n长记扁舟共载，偶近旗亭宿。\n渺云横玉。\n鸳鸯枕上，听彻新翻数般曲。\n此际魂清梦冷，绣被香芬馥。\n因念多感情怀，触处伤心目。\n自是今宵独寐，怎不添愁蹙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7072, '镇西・小镇西犯', '蔡伸', '秋风吹暗雨，重衾寒透。\n伤心听、晓钟残漏。\n凝情久。\n记红窗夜雪，促膝围炉，交杯劝酒。\n如今顿孤欢偶。\n念别後。\n菱花清镜里。\n眉峰暗斗。\n想标容、怎禁销瘦。\n忍回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7073, '看花回', '蔡伸', '夜久凉生，庭院漏声频促。\n念昔胜游旧地，对画阁层峦，雨馀烟簇。\n新诗暗藏小字，霜刀刊翠竹。\n携素手、细绕回塘，芰荷香里彩鸳宿。\n别後想、香销腻玉。\n带围减、钏宽金粟。\n虽有鳞鸿锦素，柰事与心违，佳期难卜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7074, '诉衷情', '蔡伸', '亭亭秋水玉芙蓉。\n天际水浮空。\n碧云望中空暮，人在广寒宫。\n双缕枕，曲屏风。\n小房栊。\n可怜今夜，明月清风，无计君同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7075, '浪淘沙', '蔡伸', '楼下水潺。\n楼外屏山。\n淡烟笼月晚凉天。\n曾共玉人携素手，同倚阑干。\n云散梦难圆。\n幽恨绵绵。\n旧游重到忍重看。\n负你一生多少泪，月下花前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7076, '如梦令', '蔡伸', '人静重门深亚。\n朱阁画帘高挂。\n人与月俱圆，月色波光相射。\n潇洒。\n潇洒。\n人月长长今夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7077, '如梦令', '蔡伸', '今夜行云何处。\n还是月华当午。\n倚遍曲阑桥，望断锦屏归路。\n空去。\n空去。\n梦到绿窗朱户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7078, '愁倚阑・春光好', '蔡伸', '伤春晚，送春归。\n步云溪。\n绿叶同心双小字，记曾题。\n楼外红日平西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7079, '愁倚阑・春光好', '蔡伸', '天如水，月如钩。\n正新秋。\n月影参差人窈窕，小红楼。\n如今往事悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7080, '愁倚阑・春光好', '蔡伸', '一番雨，一番凉。\n夜初长。\n满院蛩吟人不寝，月侵廊。\n木犀微绽幽芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7081, '望江南・忆江南', '蔡伸', '花落尽，寂寞委残红。\n蝶帐梦回空晓月，凤楼人去谩东风。\n春事已成空。\n闲伫立，□□水溶溶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7082, '春光好', '蔡伸', '鸾屏掩，翠衾香。\n小兰房。\n回首当时云雨梦，两难忘。\n如今水远山长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7083, '风流子', '蔡伸', '韶华惊晚，青春老、倦客惜年芳。\n庭樾荫浓，半藏莺语，畹兰花减，时有蜂忙。\n粉墙低，嫩岚滋翠葆，零露湿残妆。\n风暖昼长，柳绵吹尽，澹烟微雨，梅子初黄。\n洛浦音容远，书空漫惆怅，往事悲凉。\n无奈锦鳞杳杳，不渡横塘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7084, '朝中措', '蔡伸', '章台杨柳月依依。\n飞絮送春归。\n院宇日长人静，园林绿暗红稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7085, '朝中措', '蔡伸', '雨馀清镜湛秋容。\n屏展九华峰。\n万里闲云散尽，半规凉月当空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7086, '侍香金童', '蔡伸', '宝马行春，缓辔随油壁。\n念一瞬、韶光堪重惜。\n还是去年同醉日。\n客里情怀，倍添凄恻。\n记南城、锦径名园曾遍历。\n更柳下、人家似织。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7087, '江城子', '蔡伸', '碧厨文簟小窗前。\n乍更阑。\n□□□。\n乌鹊南飞，秋意渐凄然。\n满院蛩吟风露下，人窈窕，月蝉娟。\n双星旧约又经年。\n信谁传。\n恨绵绵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7088, '西江月', '蔡伸', '翡翠蒙金衫子，缕尘如意冠儿。\n持杯轻按遏云词。\n别是出尘风味。\n莫羡双星旧约，愿谐明月佳期。\n凭肩密语两心知。\n一棹五湖烟水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7089, '苍梧谣・归字谣', '蔡伸', '天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7090, '采桑子', '蔡伸', '奇花不比寻常艳，独步南州。\n往事悠悠。\n辽鹤重来忆梦游。\n仙翁不改青青眼，一醉迟留。\n妙墨银钩。\n题作人间第一流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7091, '洞仙歌', '蔡伸', '莺莺燕燕。\n本是于飞伴。\n风月佳时阻幽愿。\n但人心坚固後，天也怜人，相逢处、依旧桃花人面。\n绿窗携手，帘幕重重，烛影摇红夜将半。\n对尊前如梦，欲语魂惊，语未竟、已觉衣襟泪满。\n我只为、相思特特来，这度更休推，後回相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7092, '瑞鹤仙', '蔡伸', '玉猊香谩。\n叹瓶沈簪断，紫箫声绝。\n丹青挂寒壁。\n细端详，宛是旧时标格。\n音容望极。\n奈弱水、蓬山路隔。\n似瑶林琼树，韶华正好，一枝先折。\n凄切。\n相思情味，镜中绿鬓，看成华发。\n临风对月。\n空罗袂，清血。\n待随群逐队，开眉一笑，除你心肠是铁。\n看今生，为伊烦恼，甚时是彻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7093, '采桑子', '何', '百花丛里花君子，取信东君。\n取信东君。\n名策花中第一勋。\n结成宝鼎和羹味，多谢东君。\n多谢东君。\n香遍还应号令春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7094, '虞美人', '何', '分香帕子揉蓝腻。\n欲去殷勤惠。\n重来直待牡丹时。\n只恐花知、知後故开迟。\n别来看尽闲桃李。\n日日阑干倚。\n催花无计问东风。\n梦作一双蝴蝶、绕芳丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7095, '失调名', '何', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7096, '失调名', '何', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7097, '一剪梅・一翦梅', '郑刚中', '汉粉重番内样妆。\n新染冰肌，浅浅莺黄。\n广寒宫迥阻归期，襟袖空馀暗淡香。\n江路迢迢楚塞长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7098, '临江仙', '韩世忠', '冬看山林萧疏净，春来地润花浓。\n少年衰老与山同。\n世间争名利，富贵与贫穷。\n荣贵非干长生药，清闲是不死门风。\n劝君识取主人公。\n单方只一味，尽在不言中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7099, '南乡子', '韩世忠', '人有几何般。\n富贵荣华总是闲。\n自古英雄都如梦，为官。\n宝玉妻男宿业缠。\n年迈衰残。\n鬓发苍浪骨髓乾。\n不道山林有好处，贪欢。\n只恐痴迷误了贤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7100, '更漏子', '黄大舆', '怜宋玉、许王昌。\n东西邻短墙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7101, '虞美人', '黄大舆', '世间离恨何时了。\n不为英雄少。\n楚歌声起霸图休。\n玉帐佳人血泪、满东流。\n葛荒葵老芜城暮。\n玉貌知何处。\n至今芳草解婆娑。\n只有当时魂魄、未消磨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7102, '水调歌头', '王灼', '长江飞鸟外，明月众星中。\n今来古往如此，人事几秋风。\n又对团团红树，独跨蹇驴归去，山水澹丰容。\n远色动愁思，不见两诗翁。\n酒如渑，谈如绮，气如虹。\n当时痛饮狂醉，只许赏心同。\n响绝光沈休问，俯仰之间陈迹，我亦老飘蓬。\n望久碧云晚，一雁度寒空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7103, '渔家傲', '王灼', '漠漠郊原荒宿草。\n黄花趁得秋风早。\n万里岷峨归梦到。\n东篱好。\n未应花似行人老。\n古往今来成一笑。\n为君醉里销沈了。\n不用登临短帽。\n愁绝□。\n吴霜点鬓教谁扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7104, '醉花阴', '王灼', '平生五色江淹笔。\n合占金闺籍。\n桃李满城春，恨□屏□，只作三年客。\n画船暂系河桥侧。\n一醉分南北。\n惆怅酒醒时，雨笠风蓑，似旧无人识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7105, '清平乐', '王灼', '东风归早。\n已绿瀛洲草。\n紫殿红楼春正好。\n杨柳半和烟袅。\n玉舆遍绕花行。\n初闻百啭新莺。\n历历因风传去，千门万户春声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7106, '清平乐', '王灼', '坠红飘絮。\n收拾春归去。\n长恨春归无觅处。\n心事顾谁分付。\n卢家小苑回塘。\n于飞多少鸳鸯。\n纵使东墙隔断，莫愁应念王昌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7107, '点绛唇', '王灼', '休惜馀春，试来把酒留春住。\n问春无语。\n帘卷西山雨。\n一掬愁心，强欲登高赋。\n山无数。\n烟波无数。\n不放春归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7108, '浣溪沙', '王灼', '一样婵娟别样清。\n眼明初识董双成。\n香风随步过帘旌。\n笑捧玉觞频劝客，浣溪沙里转新声。\n花间侧听有流莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7109, '虞美人', '王灼', '别来杨柳团轻絮。\n摆撼春风去。\n小园桃李却依依。\n犹自留花不发、待郎归。\n枝头便觉层层好。\n信是花相恼。\n觥船一棹百分空。\n拚了如今醉倒、闹香中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7110, '虞美人', '王灼', '姚黄真是花中主。\n个个寻芳去。\n春光能有几多时。\n莫遣无花空折、断肠枝。\n蜂媒蝶使争撩乱。\n应妒传觞缓。\n问花端的为谁开。\n拟作移春小槛、载归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7111, '菩萨蛮', '王灼', '风柔日薄江村路。\n一鞭又逐春光去。\n胡蝶作团飞。\n竹间桃李枝。\n醉魂招不得。\n一半随春色。\n桃李□无多。\n其如风日何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7112, '好事近', '王灼', '小砑碧霞笺，不见近来消息。\n玉骨瘦无一把，又不成空忆。\n炉熏歇尽烛花残，佳梦了难得。\n二十五声秋点，最知人端的。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7113, '长相思', '王灼', '来匆匆。\n去匆匆。\n短梦无凭春又空。\n难随郎马踪。\n山重重。\n水重重。\n飞絮流云西复东。\n音书何处通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7114, '酒泉子', '王灼', '锦水花林，前度刘郎行乐处，当时桃李卧莓苔。\n又重来。\n今年菊蕊为君开。\n赖有诗情浑似旧，西风斜日上高台。\n醉千回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7115, '恨来迟', '王灼', '柳暗汀洲，最春深处，小宴初开。\n似泛宅浮家，水平风软，咫尺蓬莱。\n更劝君、吸尽紫霞杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7116, '春光好', '王灼', '和醉梦，上峥嵘。\n忆娉婷。\n回首锦江烟一色，不分明。\n翻为离别牵情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7117, '南歌子', '王灼', '命啸无人啸，含娇何处娇。\n江南烟水太迢迢。\n璧月琼枝空想、夜和朝。\n目断肠随断，魂销骨更销。\n琐窗风雨不相饶。\n犹似西湖一枕、听寒潮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7118, '画堂春', '王灼', '暖风和雨暗楼台。\n馀寒巧作愁媒。\n半春怀抱向谁开。\n忍泪千回。\n断梦已随烟篆，醉魂空琼杯。\n小窗瞥见一枝梅。\n疑误君来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7119, '七娘子', '王灼', '花明雾暗非花雾。\n似春屏、短梦无凭据。\n夜月将来，晓灯催去。\n半衾馀暖空留住。\n情柔意密愁千缕。\n想一声、鸡唱东城路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7120, '减字木兰花', '王灼', '飞霞半缕。\n收尽一天风和雨。\n可惜黄昏。\n残角疏钟要断魂。\n双鱼传信。\n只道横塘消息近。\n心事悠悠。\n同向春风各自愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7121, '一落索', '王灼', '昨夜封枝寒雪。\n暗堆残叶。\n佳人醉里插钗梁，更不问、眠时节。\n绣被重重夜彻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7122, '丑奴儿・采桑子', '王灼', '东风已有归来信，先返梅魂。\n雪斗纷纷。\n更引蟾光过璧门。\n绿衣小凤枝头语，我有嘉宾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7123, '减字木兰花', '陈袭善', '江南二月。\n犹有枝头千点雪。\n邀上芳尊。\n却占东君一半春。\n尊前眼底。\n南国风光都在此。\n移过江来。\n从此江南不复开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7124, '渔家傲', '陈袭善', '鹫岭峰前阑独倚。\n愁眉蹙损愁肠碎。\n红粉佳人伤别袂。\n情何已。\n登山临水年年是。\n常记同来今独至。\n孤舟晚扬湖光里。\n衰草斜阳无限意。\n谁与寄。\n西湖水是相思泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7125, '丑奴儿・采桑子', '曾乾曜', '蓦地厮看时。\n赤怕那、迪功郎儿。\n气岸昂昂因权县，厅子叫道，宣教请後，有无限威仪。\n先自不相知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7126, '点绛唇', '孙', '烟洗风梳，司花先放江梅吐。\n竹村沙路。\n脉脉摇寒雨。\n醉魄吟魂，无著清香处。\n愁如缕。\n系春不住。\n又折冰枝去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7127, '卜算子', '如晦', '有意送春归，无计留春住。\n毕竟年年用著来，何似休归去。\n目断楚天遥，不见春归路。\n风急桃花也似愁，点点飞红雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7128, '菩萨蛮', '孙舣', '一声羌管吹呜咽。\n玉溪夜半梅翻雪。\n江月正茫茫。\n断桥流水香。\n含章春欲暮。\n落日千山雨。\n一点著枝酸。\n吴姬先齿寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7129, '倦寻芳', '潘汾', '兽环半掩，鸳无尘，庭院潇洒。\n树色沈沈，春尽燕娇莺姹。\n梦草池塘清渐满，海棠轩槛红相亚。\n听箫声，记秦楼夜约，彩鸾齐跨。\n渐迤逦、更催银箭，何处贪欢，犹系骄马。\n旋剪灯花，两点翠眉谁画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7130, '贺新郎', '潘汾', '篆缕销香鼎。\n翠沈沈、庭阴转午，画堂人静。\n芳草王孙知何处，惟有杨花糁径。\n正玉枕、瞢腾初醒。\n门外残红春已去，镇无聊、酒厌厌病。\n云髻，未整。\n江南旧事休重省。\n但天涯、寻消问息，断鸿难倩。\n月满西楼凭阑久，依旧归期未定。\n便只恐、瓶沈金井。\n嘶骑不来银烛暗，枉教人、立尽梧桐影。\n谁伴我，对鸾镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7131, '孟家蝉', '潘汾', '向卖花担上，落絮桥边，春思难禁。\n正暖日温风里，斗采遍香心。\n夜夜稳栖芳草，还处处、先春禽。\n满园林。\n梦觉南华，直到如今。\n情深。\n记那人小扇、扑得归来，绣在罗襟。\n芳意赠谁，应费万线千针。\n谩道滕王画得，枉谢客、多少清吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7132, '花心动', '潘汾', '啼鸟惊心，怨年华，羞看杏梢桃萼。\n映柳小桥，芳草闲庭，处处旧游如昨。\n断肠人在东风里，遮不尽、几重帘幕。\n旧巢稳，呢喃燕子，笑人漂泊。\n应是素肌瘦削。\n空望断天涯，信音难托。\n半污泪痕，重整馀香，夜夜翠衾寒薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7133, '玉蝴蝶', '潘汾', '睡起日高莺啭，画帘低卷，花影重重。\n醉眼羞抬，娇困犹自未惺忪。\n绣床近、强来描翠，妆镜掩、不肯匀红。\n锦屏空。\n对花无语，独怨春风。\n匆匆。\n庾郎去後，香销玉减，是事疏慵。\n纵蛮笺封了，何处问鳞鸿。\n眼中泪、万行难尽，眉上恨、一点偏浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7134, '丑奴儿慢・采桑子慢', '潘汾', '愁春未醒，还是清和天气。\n对浓绿阴中庭院，燕语莺啼。\n数点新荷翠钿，轻泛水平池。\n一帘风絮，才晴又雨，梅子黄时。\n忍记那回，玉人娇困，初试单衣。\n共携手、红窗描绣，画扇题诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7135, '忆王孙', '李重元', '萋萋芳草忆王孙。\n柳外楼高空断魂。\n杜宇声声不忍闻。\n欲黄昏。\n雨打梨花深闭门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7136, '忆王孙', '李重元', '风蒲猎猎小池塘。\n过雨荷花满院香。\n沈李浮瓜冰雪凉。\n竹方床。\n针线慵拈午梦长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7137, '忆王孙', '李重元', '飕飕风冷荻花秋。\n明月斜侵独倚楼。\n十二珠帘不上钩。\n黯凝眸。\n一点渔灯古渡头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7138, '忆王孙', '李重元', '彤云风扫雪初晴。\n天外孤鸿三两声。\n独拥寒衾不忍听。\n月笼明。\n窗外梅花瘦影横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7139, '贺新郎', '李玉', '篆缕销金鼎。\n醉沈沈、庭阴转午，画堂人静。\n芳草王孙知何处，惟有杨花糁径。\n渐玉枕、腾腾春醒。\n帘外残红春已透，镇无聊、酒厌厌病。\n云鬓乱，未整。\n江南旧事休重省。\n遍天涯、寻消问息，断鸿难倩。\n月满西楼凭栏久，依旧归期未定。\n又只恐、瓶沈金井。\n嘶骑不来银烛暗，枉教人、立尽梧桐影。\n谁伴我，对鸾镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7140, '小重山', '吴淑姬1', '谢了荼シ春事休。\n无多花片子，缀枝头。\n庭槐影碎被风揉。\n莺虽老，声尚带娇羞。\n独自倚妆楼。\n一川烟草浪，衬云浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7141, '惜分飞', '吴淑姬1', '岸柳依依拖金缕。\n是我朝来别处。\n惟有多情絮。\n故来衣上留人住。\n两眼啼红空弹与。\n未见桃花又去。\n一片征帆举。\n断肠遥指苕溪路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7142, '祝英台近', '吴淑姬1', '粉痕销，芳信断，好梦又无据。\n病酒无聊，枕听春雨。\n断肠曲曲屏山，温温沈水，都是旧、看承人处。\n久离阻。\n应念一点芳心，闲愁知几许。\n偷照菱花，清瘦自羞觑。\n可堪梅子酸时，杨花飞絮，乱莺闹、催将春去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7143, '失调名', '吴淑姬1', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7144, '最高楼', '柳富', '人间最苦，最苦是分离。\n伊爱我，我怜伊。\n青草岸头人独立，画船东去橹声迟。\n楚天低，回望处，两依依。\n後会也知俱有愿，未知何日是佳期。\n心下事、乱如丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7145, '失调名', '王幼玉', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7146, '渔家傲', '李生', '庭院黄昏人悄悄。\n两情暗约谁知道。\n咫尺蓬山难一到。\n明月照。\n潜身只得听言笑。\n特地嗟吁传密耗。\n芳衷要使郎心表。\n此际归来愁不少。\n萦怀抱。\n卿卿销得人烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7147, '极相思令・极相思', '谭意哥', '湘东最是得春先。\n和气暖如绵。\n清明过了，残花巷陌，犹见秋千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7148, '长相思令・长相思', '谭意哥', '旧燕初归，梨花满院，迤逦天气融和。\n新晴巷陌，是处轻车骏马，禊饮笙歌。\n旧赏人非，对佳时、一向乐少愁多。\n远意沈沈，幽闺独自颦蛾。\n正消黯、无言自感，凭高远意，空寄烟波。\n从来美事，因甚天教，两处多磨。\n开怀强笑，向新来、宽却衣罗。\n似恁他、人怪憔悴，甘心总为伊呵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7149, '极相思', '李氏1', '日红疏翠密晴暄。\n初夏困人天。\n风流滋味，伤怀尽在，花下风前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7150, '南乡子', '花仲胤', '顿首起情人。\n即日恭维问好音。\n接得彩笺词一首，堪惊。\n题起词名恨转生。\n展转意多情。\n寄与音书不志诚。\n不写伊川题尹字，无心。\n料想伊家不要人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7151, '伊川令・伊州令', '花仲胤妻', '西风昨夜穿帘幕。\n闺院添消索。\n最是梧桐零落。\n迤逦秋光过却。\n人情音信难托。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7152, '失调名', '花仲胤妻', '奴启情人勿见罪。\n闲将小书作尹字。\n情人不解其中意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7153, '期夜月', '刘浚', '金钩花绶系双月。\n腰肢软低折。\n揎皓腕，萦绣结。\n轻盈宛转，妙若凤鸾飞越。\n无别。\n香檀急扣转清切。\n翻纤手飘瞥。\n催画鼓，追管，锵洋雅奏，尚与众音为节。\n当时妙选舞袖，慧性雅资，名为殊绝。\n满座倾心注目，不甚窥回雪。\n纤怯。\n逡巡一曲霓裳彻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7154, '卜算子', '施酒监', '相逢情便深，恨不相逢早。\n识尽千千万万人，终不似、伊家好。\n别你登长道。\n转更添烦恼。\n楼外朱楼独倚阑，满目围芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7155, '卜算子', '乐婉', '相思似海深，旧事如天远。\n泪滴千千万万行，更使人愁断肠。\n要见无因见，了拚终难拚。\n若是前生未有缘，待重结、来生愿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7156, '江神子・江城子', '虞某', '相逢只怕有分离。\n许多时。\n暗为期。\n常是眉来眼去、惹猜疑。\n何似总休拈弄上，轻咳嗽、有人知。\n终须买个小船儿。\n任风吹。\n尽东西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7157, '失调名', '巴谈', '正月月尽夕。\n芭蕉船一只。\n灯盏两只明辉辉，内里更有筵席。\n奉劝郎君小娘子。\n饱吃莫形迹。\n每年只有今日日。\n愿我做来称意。\n奉劝郎君小娘子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7158, '清平乐', '杨师纯', '羞娥浅浅。\n秋水如刀剪。\n窗下无人自针线。\n不觉郎来身畔。\n相将携手鸳帏。\n匆匆不许多时。\n耳畔告郎低语，共郎莫使人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7159, '清平乐', '杨师纯', '小庭春院。\n睡起花阴转。\n往事旧欢离思远。\n柳絮随风难管。\n等闲屈指当时。\n阑干几曲谁知。\n为问春风桃李，而今子满芳枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7160, '渔家傲', '杨端臣', '有个人人情不久。\n而今已落他人手。\n见说近来伊也瘦。\n好教受。\n看谁似我能就。\n莲脸能匀眉黛皱。\n相思泪滴残妆透。\n总是自家为事谬。\n从今後。\n这回断了心先有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7161, '渔家傲', '杨端臣', '楼鼓数声人迹散。\n马蹄不响街尘软。\n门户深深扃小院。\n帘不卷。\n背灯尽烛红条短。\n归路恍如春梦断。\n千愁万恨知河限。\n昨夜月华明似练。\n花影畔。\n算来惟有嫦娥见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7162, '阮郎归', '杨端臣', '□□今日那人家。\n琐窗红影斜。\n髻云散乱不胜花。\n偷匀残脸霞。\n梁燕老，石榴花。\n佳期今已差。\n凭阑思想入天涯。\n暮云重叠遮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7163, '失调名', '聂胜琼', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7164, '鹧鸪天', '聂胜琼', '玉惨花愁出凤城。\n莲花楼下柳青青。\n尊前一唱阳关後，别个人人第五程。\n寻好梦，梦难成。\n况谁知我此时情。\n枕前泪共帘前雨，隔个窗儿滴到明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7165, '燕归梁', '赵才卿', '细柳营中有亚夫。\n华宴簇名姝。\n雅歌长许佐投壶。\n无一日、不欢娱。\n汉王拓境思名将，捧飞诏欲登途。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7166, '雨中花慢', '任', '事往人离，还似暮峡归云，陇上流泉。\n奈向分罗带，已断么弦。\n长记歌时酒畔，难忘月夕花前。\n相携手处，琼楼珠户，触目依然。\n从来惯共，锦衾屏枕，长效比翼文鸳。\n谁念我、而今清夜，常是孤眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7167, '朝中措', '都下妓', '屏山栏槛倚晴空。\n山色有无中。\n手种庭前桃李，别来几度春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7168, '沁园春', '李弥逊', '枕深轩，散帙虚堂，畏景屡移。\n渐披襟临水，床就月，莲香拂面，竹色侵衣。\n压玉为醪，折荷当盏，卧看银潢星四垂。\n人归後，伴饥蝉自语，宿鸟相依。\n痴儿。\n莫蹈危机。\n悟四十九年都尽非。\n任纡朱拖紫，围金佩玉，青钱流地，白璧如坻。\n富贵浮云，身名零露，事事无心归便归。\n秋风动，正吴淞月冷，莼长鲈肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7169, '永遇乐', '李弥逊', '曲径通幽，小亭依翠，春事才过。\n看笋成竿，等花著果，永昼供闲坐。\n苍苍晚色，临渊小立，引首暮鸥飞堕。\n悄无人，一溪山影，可惜被渠分破。\n百年似梦，一身如寄，南北去留皆可。\n我自知鱼，け然濠上，不问鱼非我。\n隔篱呼取，举杯对影，有唱更凭谁和。\n知渊明，清流临赋，得似恁麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7170, '永遇乐', '李弥逊', '五十劳生，紫髯霜换，白日驹过。\n闭户推愁，缘崖避俗，壁角团蒲坐。\n提壶人至，竹根同卧，醉帽尽从堕。\n梦惊回，满身疏影，露滴月斜云破。\n无人自酌，有邀皆去，我笑两翁多可。\n忍冻吟诗，典衣沽酒，二子应嗤我。\n两忘一笑，调同今古，谁道郢歌无和。\n後之人，犹今视昔，有能继麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7171, '念奴娇', '李弥逊', '瑶池倒影，露华浓、群玉峰峦如洗。\n明镜平铺秋水净，寒锁一天空翠。\n荷芰风摇，苹蘩波动，惊起鱼龙戏。\n扶疏桂影，十分光照人世。\n谁似。\n老子痴顽，胡床危坐，自引壶觞醉。\n斗转参横歌未彻，屋角乌飞星坠。\n对影三人，停杯一问，谁会骑鲸意。\n金牛何处，玉楼高耸十二。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7172, '念奴娇', '李弥逊', '风帘弄影，正闲堂永昼，香销人寂。\n轧轧邻机芳思乱，愁入回文新织。\n燕蹴巢泥，莺喧庭柳，好梦无踪迹。\n那堪春事，背人何计留得。\n谁似爱酒南邻，岸巾坦腹，醉踏西山碧。\n彩笔阳春传雁足，催我飞觞浮白。\n老去情怀，凭君试看，鬓上秋霜色。\n故园千里，月华空照相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7173, '念奴娇', '李弥逊', '楚天木落，际平芜千里，寒霜凝碧。\n鄂渚波横何处是，当日孙郎赤壁。\n黄耳音稀，白云望远，又见春消息。\n嘉辰长记，谢池梅蕊初摘。\n遥想黄鹤楼高，兰阶丝管沸，传觞如织。\n倦客心驰归路绕，不及南飞双翼。\n固著斑衣，重翻锦字，寄远供新拍。\n明年欢侍，寿期应献千百。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7174, '三段子・宝鼎现', '李弥逊', '层林烟霁，巨壁天半，鸿飞无路。\n云断处、两山之间，十万琅环翠羽。\n转秀谷、枕苹花汀溆。\n短柳疏篱向暮。\n看卧垄牛归，横舟人去，平芜鸥鹭。\n并游不见鞭鸾侣。\n只僧前、松子随步。\n回径险、凌风遐想，小憩清泉茂树。\n正笋蕨、过如苏新雨。\n矶下游鱼可数。\n纵窈窕、云关长启，寂寂谁争子所。\n世上丹毂朱缨，春梦觉、南柯何许。\n况荣枯无定，中有欢离愁聚。\n尽笑我、诧盘中趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7175, '水调歌头', '李弥逊', '清夜月当午，轩户踏层冰。\n楼高百尺，缥缈天阙敞云扃。\n万里风摇玉树，吹我衣裾零乱，寒入骨毛轻。\n径欲乘之去，高兴送青冥。\n神仙说，功名事，两难成。\n苇汀筠岫深处，端可寄馀龄。\n身外营营姑置，对景掀髯一笑，引手接飞萤。\n且尽杯中物，日出事还生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7176, '水调歌头', '李弥逊', '安石寓丝竹，方朔杂诙谐。\n昂霄气概，古来无地可容才。\n不见骑鲸仙伯，唾手功名事了，猿鹤与同侪。\n有意谢轩冕，无计避嫌猜。\n静中乐，山照座，月浮杯。\n忘形湛辈，一笑丘壑写高怀。\n只恐天催玉斧，为破烟尘昏翳，人自日边来。\n东阁动诗兴，莫待北枝开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7177, '水调歌头', '李弥逊', '松柏渐成趣，红紫勿齐开。\n花神靳惜芳事，日日待公来。\n遥想金葵侧处，素月华灯相照，妆影满歌台。\n馀韵写宫徵，飞落远山隈。\n逃禅客，尊中尽，厌长斋。\n且愁风絮，断送春色揽离怀。\n命驾何妨千里，只恐行云碍辙，直磴插崔嵬。\n手拍阳春唱，隔岸借残杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7178, '水调歌头', '李弥逊', '不见隐君子，一月比三秋。\n惊涛如许，梦魂无路绝横流。\n安得如云长翮，命驾不须千里，上下逐君游。\n此计杳难就，注目倚江楼。\n西风里，多少恨，寄歌头。\n飞奴接翼，为我三度下南州。\n正是天寒日暮，独钓一江残雪，风猎碧莎裘。\n和子浩然句，一酌散千忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7179, '水调歌头', '李弥逊', '不上长安道，霜鬓几惊秋。\n故人何在，时序欺我去如流。\n赏对洛滨仙伯，共说芗林佳致，魂梦与追游。\n更唱中秋句，得月上东楼。\n云岩底，秋香下，楚江头。\n十年笑傲，真是骑鹤上扬州。\n却忆金门联辔，晓殿催班同到，高拱翠云裘。\n明月今千里，何计缓离忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7180, '水调歌头', '李弥逊', '白发闽江上，几度过中秋。\n阴晴相半，曾见玉塔卧寒流。\n不似今年三五，皎皎冰轮初上，天阙恍神游。\n下视人间世，万户水明楼。\n贤公子，追乐事，占鳌头。\n酒酣喝月，腰鼓百面打凉州。\n沈醉尽扶红袖，不管风摇仙掌，零露湿轻裘。\n但恐尊中尽，身外复何忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7181, '蓦山溪', '李弥逊', '冲寒山意，未放江头树。\n老去恨春迟，数花期、朝朝暮暮。\n疏英冷蕊，也为有情忙，深夜月，小庭中，绝胜西城路。\n调元妙手，便是春来处。\n酝造十分香，更暖借、毫端烟雨。\n狂歌醉客，小摘问东风，花谢後，子成时，趁得和羹否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7182, '蓦山溪', '李弥逊', '竹边柳外，两两寒梅树。\n疏影上帘栊，似却□、一枝横暮。\n玉肌瘦损，有恨不禁春，萦冰佩，整风裳，怅望瑶台路。\n我来胜赏，持酒花深处。\n天晓酿幽香，正一霎、如酥小雨。\n江山得助，臭味许谁同，长安远，故人疏，梦到江南否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7183, '昆明池・金明池', '李弥逊', '帐锦笼庭，囊香飘榭，过了芳时强半。\n觅残红、蜂须趁日，占新绿、莺喉咤暖。\n数花期、望得春来，春去也、把酒南山谁伴。\n更帘幕垂垂，恼人飞絮，乱落一轩风晚。\n手拍狂歌挥醉碗。\n笑浪走江头，几逢归燕。\n忆黄华、曾吹纱帽，讶彩楼、催纨扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7184, '十月桃', '李弥逊', '浮云无定，任春风万点，吹上寒枝。\n砌外珑璁，暗香夜透帘帏。\n闲情最宜酒伴，胜黄昏、冷月清溪。\n风流谢傅，梦到华胥，长是相随。\n似凝愁、不语谁知。\n芳思乱微酸，已带离离。\n传语花神，任教横竹三吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7185, '十月桃', '李弥逊', '一枝三四，弄疏英秀色，特地生寒。\n刻楮三年，谩夸煮石成丹。\n梨花带雨难并，似玉妃、寂寞微潸。\n瑶台空阔，露下星坠，零乱风鬟。\n记前回、拥盖西园。\n花信被山烟，著意邀阑。\n盏面横斜，大家月底颓然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7186, '声声慢', '李弥逊', '龙涎染就，沈水薰成，分明乱屑琼瑰。\n一朵才开，人家千里须知。\n花儿大则不大，有许多、潇洒清奇。\n较量尽，诮胜如末利，赛过酴。\n更被秋光断送，微放些月照，著阵风吹。\n恼杀多情，猛拚沈醉酬伊。\n朝朝暮暮守定，尽忙时、也不分离。\n睡梦里，胆瓶儿、枕畔数枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7187, '永遇乐', '李弥逊', '一水如绳，两山如翼，绿野如绣。\n松院干霄，筠庄枕浪，揽尽溪山秀。\n水南水北，竹舆兰棹，来往月宵花昼。\n问人间、天上何处，更寻大围小有。\n人言拒梗，功成仙去，丹鼎夜寒光透。\n唤取云英，炼成石髓，日月齐长久。\n烦君挟我，朝元真阙，两翼羽轻风骤。\n此时看，小茅峰顶，有云贯斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7188, '满庭芳', '李弥逊', '荷背翻黄，蕉心滴翠，雨洗庭院无尘。\n断云缺处，矫首望冰轮。\n迤逦天垂四幕，星杓淡、河汉横银。\n笙歌散，风帘自上，寒水满楼明。\n刘郎方得计，钗摇绣户，枕并华。\n笑狂客无眠，坐听锺鲸。\n明月中秋一梦，临鸳、三绕殷勤。\n清光里，持杯对影，风月两兼并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7189, '水龙吟', '李弥逊', '化工收拾芳菲，晕酥翦彩迎春禊。\n江山影里，泰阶星聚，重寻古意。\n曲水流觞，晚林张宴，竹边花外。\n倩飞英衬地，繁枝障日，游丝驻，羲和旆。\n雪避清歌自止。\n放一钩、玉沈寒水。\n西园飞盖，东山携妓，古今无愧。\n闻道东君，商量花蕊，作明年计。\n待公归，独运丹青妙手，忆山阴醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7190, '洞仙歌', '李弥逊', '断桥斜路，又是春来也。\n仙掌云半开谢。\n尽凝酥砌粉，不似真香，分明对、冰雪肌肤姑射。\n天涯伤老大，万斛新愁，一笑端须问花借。\n纵广平冷淡，铁石心肠，未拚得、花里风前月下。\n为传语、游蜂缓经营，且留与山翁，醉吟清夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7191, '洞仙歌', '李弥逊', '残烟薄雾，杖东风排遣。\n收拾轻寒做轻暖。\n问墙偶屋角，多少青红，春不语，行处随人近远。\n穿帘花影乱，金鸭香温，幽梦醒时午禽啭。\n任抛书推枕，嚼蕊攀条，暗消了、清愁一半。\n且莫放、浮云蔽晴晖，怕惹起羁人，望中凝恋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7192, '江神子・江城子', '李弥逊', '梦中北去又南来。\n饱风埃。\n鬓华衰。\n浮木飞蓬，踪迹为谁催。\n自笑自悲还自误，一杯酒，鼻如雷。\n晓舆行处觉春回。\n屑琼瑰。\n糁□苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7193, '感皇恩', '李弥逊', '入夜月华清，中天方好。\n更著山光两相照。\n星稀云净，玉树惊乌三绕。\n广寒风陆近，秋光老。\n老山高胜，飞尘不到。\n亭上仙翁自昏晓。\n短封新唱，字字令人绝倒。\n待凭书寄恨，归鸿少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7194, '浣溪沙', '王以宁', '艾胜迎薰寿缕长。\n碧酒泛绿蒲香。\n万家喜气在都粱。\n小阁幽轩新料理，舞衫歌扇且传觞。\n看君飞步上明光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7195, '浣溪沙', '王以宁', '招福宫中第几真。\n餐花辟谷小夫人。\n天翁新与玉麒麟。\n我识外家西府相，玉壶冰雪照青春。\n小郎风骨已凌云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7196, '踏莎行', '王以宁', '梦褥光宗，河东右族。\n向来到耳声华熟。\n游从两世纪金兰，风流二阮居南北。\n今夕何辰，相亲灯烛。\n一廛我愿依韦曲。\n长君未可赋骊驹，山人莫为蒲轮促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7197, '踏莎行', '王以宁', '我自山中，渔樵冷族。\n一丘一壑平生熟。\n来江海寄馀生，心兵语阱频奔北。\n九里灵河，十分光烛。\n分辉借润须邻曲。\n柳家兄弟莫人，狂奴小户元低促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7198, '踏莎行', '王以宁', '位正三槐，光生九族。\n人间一梦黄粱熟。\n迩来荆楚地行仙，卜居深在延原北。\n笑问从前，谁调玉烛。\n当筵鲍老那能曲。\n山中饮酒是生涯，欲归未果成烦促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7199, '感皇恩', '王以宁', '千古洞庭湖，百川争注。\n雪浪银涛正如许。\n骑鲸诗客，浩气决云飞雾。\n背人歌乃，凌空去。\n我欲从公，翩然鹄举。\n未愿人间相君雨。\n箸短棹，是我平身真语。\n个中烟景好，烦公句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7200, '庆双椿・浣溪沙', '王以宁', '问政山头景气嘉。\n仙家绿酒荐菖芽。\n仙郎玉女共乘槎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7201, '渔家傲', '王以宁', '往事闲思人共怕。\n十年塞上烟尘亚。\n百万铁衣驰铁马。\n都弄罢。\n八风断送归莲社。\n卖药得钱休教化。\n归来醉卧蜗牛舍。\n一颗明珠元不夜。\n非待借。\n神光穿透诸天下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7202, '好事近', '王以宁', '诗客少微家，世有斗南人杰。\n一段素襟清韵，似玉壶冰雪。\n怀中卿相饱经纶，况是好时节。\n我有太平歌颂，待形容贤业。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7203, '好事近', '王以宁', '白石读书房，世有斗南人杰。\n一段素襟清韵，似玉壶冰雪。\n仙家赤酒荐交梨，道眼况超越。\n来往十州三岛，跨一轮新月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7204, '虞美人', '王以宁', '归来峰下霜如水。\n明月三千里。\n幽人独立瞰长淮。\n谁棹扁舟一叶、趁潮来。\n洞庭湖上银涛观。\n忆我烟蓑伴。\n此身天地一浮萍。\n去国十年华发、欲星星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7205, '浣溪沙', '王以宁', '快雨疏风六月凉。\n貂蝉人著彩衣裳。\n肃然心拜玉炉香。\n相国趣还调鼎鼐，潘舆指日下潇湘。\n秋来江上接归航。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7206, '南歌子', '王以宁', '未折江南柳，先开陇上梅。\n绿情红意到根。\n昨夜春随和气、已归来。\n忠力扶昌运，冲和保圣胎。\n阳功阴德好栽培。\n他日骑鲸仙路、指蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7207, '鹧鸪天', '王以宁', '瑞雪当空舞素英。\n玳筵收得满金瓶。\n洗教双眼明如镜，看取黄河几度清。\n龟畀寿，鹤为形。\n年年长愿见仪刑。\n他年林下逢彭祖，唤作谁家小後生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7208, '法驾导引', '陈与义', '朝元路，朝元路，同驾玉华君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7209, '法驾导引', '陈与义', '东风起，东风起，海上百花摇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7210, '法驾导引', '陈与义', '帘漠漠，帘漠漠，天澹一帘秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7211, '虞美人', '陈与义', '十年花底承潮露。\n看到江南树。\n洛阳城里又东风。\n未必桃花得似、旧时红。\n胭脂睡起春才好。\n应恨人空老。\n心情虽在只吟诗。\n白发刘郎孤负、可怜枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7212, '忆秦娥', '陈与义', '鱼龙舞。\n湘君欲下潇湘浦。\n潇湘浦。\n兴亡离合，乱波平楚。\n独无尊酒酬端午。\n移舟来听明山雨。\n明山雨。\n白头孤客，洞庭怀古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7213, '临江仙', '陈与义', '高咏楚词酬午日，天涯节序匆匆。\n榴花不似舞裙红。\n无人知此意，歌罢满帘风。\n万事一身伤老矣，戌葵凝笑墙东。\n酒杯深浅去年同。\n试浇桥下水，今夕到湘中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7214, '虞美人', '陈与义', '张帆欲去仍搔首。\n更醉君家酒。\n吟诗日日待春风。\n及至桃花开後、却匆匆。\n歌声频为行人咽。\n记著尊前雪。\n明朝酒醒大江流。\n满载一船离恨、向衡州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7215, '点绛唇', '陈与义', '寒食今年，紫阳山下蛮江左。\n竹篱烟锁。\n何处求新火。\n不解乡音，只怕人嫌我。\n愁无那。\n短歌谁和。\n风动梨花朵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7216, '虞美人', '陈与义', '超然堂上闲宾主。\n不受人间暑。\n冰盘围坐此州无。\n却有一瓶和露、玉芙蕖。\n亭亭风骨凉生牖。\n消尽尊中酒。\n酒阑明月转城西。\n照见纱巾藜杖、带香归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7217, '渔家傲', '陈与义', '今日山头云欲举。\n青蛟素凤移时舞。\n行到石桥闻细雨。\n听还住。\n风吹却过溪西去。\n我欲寻诗宽久旅。\n桃花落尽春无所。\n渺渺篮舆穿翠楚。\n悠然处。\n高林忽送黄鹂语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7218, '虞美人', '陈与义', '扁舟三日秋塘路。\n平度荷花去。\n病夫因病得来游。\n更值满川微雨、洗新秋。\n去年长恨拿舟晚。\n空见残荷满。\n今年何以报君恩。\n一路繁花相送、过青墩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7219, '浣溪沙', '陈与义', '送了栖鸦复暮钟。\n栏干生影曲屏东。\n卧看孤鹤驾天风。\n起舞一尊明月下，秋空如水酒如空。\n谪仙已去与谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7220, '玉楼春', '陈与义', '山人本合居岩岭。\n聊问支郎分半境。\n残年藜杖与纶巾，八尺庭中时弄影。\n呼儿汲水添茶鼎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7221, '清平乐', '陈与义', '黄衫相倚。\n翠葆层层底。\n八月江南风日美。\n弄影山腰水尾。\n楚人未识孤妍。\n离骚遗恨千年。\n无住庵中新事，一枝唤起幽禅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7222, '定风波', '陈与义', '九日登临有故常。\n随晴随雨一传觞。\n多病题诗无好句。\n孤负。\n黄花今日十分黄。\n记得眉山文翰老。\n曾道。\n四时佳节是重阳。\n江海满前怀古意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7223, '菩萨蛮', '陈与义', '南轩面对芙蓉浦。\n宜风宜月还宜雨。\n红少绿多时。\n帘前光景奇。\n绳床乌木几。\n尽日繁香里。\n睡起一篇新。\n与花为主人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7224, '南柯子・南歌子', '陈与义', '矫矫千年鹤，茫茫万里风。\n阑干三面看秋空。\n背插浮屠千尺、冷烟中。\n林坞村村暗，溪流处处通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7225, '临江仙', '陈与义', '忆昔午桥桥上饮，坐中多是豪英。\n长沟流月去无声。\n杏花疏影里，吹笛到天明。\n二十馀年如一梦，此身虽在堪惊。\n闲登小阁看新晴。\n古今多少事，渔唱起三更。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7226, '临江仙', '杜大中妾', '彩凤随鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7227, '临江仙', '刘彤', '千里长安名利客，轻离轻散寻常。\n难禁三月好风光。\n满阶芳草绿，一片杏花香。\n记得年时临上马，看人眼泪汪汪。\n如今不忍更思量。\n恨无千日酒，空断九回肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7228, '满庭芳', '僧儿', '团菊苞金，丛兰减翠，画成秋暮风烟。\n使君归去，千里倍潸然。\n两度朱幡雁水，全胜得、陶侃当年。\n如何见，一时盛事，都在送行篇。\n愁烦。\n梳洗懒，寻思陪宴，把月湖边。\n有多少、风流往事萦牵。\n闻道霓旌羽驾，看看是、玉局神仙。\n应相许，冲云破雾，一到洞中天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7229, '满江红', '胡仔', '泛宅浮家，何处好、苕溪清境。\n占云山万叠，烟波千顷。\n茶灶笔床浑不用，雪蓑月笛偏相称。\n争不教、二纪赋归来，甘幽屏。\n红尘事，谁能省。\n青霞志，方高引。\n任家风舴艋，生涯箸。\n三尺鲈鱼真好脍，一瓢春酒宜闲饮。\n问此时、怀抱向谁论，惟箕颍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7230, '水龙吟', '胡仔', '梦寒绡帐春风晓，檀枕半堆香髻。\n辘轳初转，阑干鸣玉，咿哑惊起。\n眠鸭凝烟，舞鸾翻镜，影开秋水。\n解低鬟试整，牙床对立，香丝乱、云撒地。\n纤手犀梳落处，腻无声、重盘鸦翠。\n兰膏匀渍，冷光欲溜，鸾钗易坠。\n年少偏娇，髻多无力，恼人风味。\n理云裾下阶，含情不语，笑折花枝戏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7231, '好事近', '王昂', '喜气拥朱门，光动绮罗香陌。\n行到紫微花下，悟身非凡客。\n不须脂粉天真，嫌怕太红白。\n留取黛眉浅处，画章台春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7232, '贺新郎', '张元干', '曳杖危楼去。\n斗垂天、沧波万顷，月流烟渚。\n扫尽浮云风不定，未放扁舟夜渡。\n宿燕落、寒芦深处。\n怅望关河空吊影，正人间、鼻息鸣鼍鼓。\n谁伴我，醉中舞。\n十年一梦扬州路。\n倚高寒、愁生故国，气吞骄虏。\n要斩楼兰三尺剑，遗恨琵琶旧语。\n谩暗涩、铜华尘土。\n唤取谪仙平章看，过苕溪、尚许垂纶否。\n风浩荡，欲飞举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7233, '贺新郎', '张元干', '梦绕神州路。\n怅秋风、连营画角，故宫离黍。\n底事倾砥柱。\n九地黄流乱注。\n聚万落、千村狐兔。\n天意从来高难问，况人情、老易悲如许。\n更南浦，送君去。\n凉生岸柳催残暑。\n耿斜河、疏星淡月，断云微度。\n万里江山知何处。\n回首对床夜语。\n雁不到、书成谁与。\n目尽青天怀今古，肯儿曹、恩怨相尔汝。\n举大白，听金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7234, '满江红', '张元干', '春水迷天，桃花浪、几番风恶。\n云乍起、远山遮尽，晚风还作。\n绿卷芳洲生杜若。\n数帆带雨烟中落。\n傍向来、沙觜共停桡，伤飘泊。\n寒犹在，衾偏薄。\n肠欲断，愁难著。\n倚篷窗无寐，引杯孤酌。\n寒食清明都过却。\n最怜轻负年时约。\n想小楼、终日望归舟，人如削。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7235, '兰陵王', '张元干', '卷朱箔。\n朝雨轻阴乍阁。\n阑干外，烟柳弄晴，芳草侵阶映红药。\n东风妒花恶。\n吹落。\n梢头嫩萼。\n屏山掩，沈水倦熏，中酒心情怕杯勺。\n寻思旧京洛。\n正年少疏狂，歌笑迷著。\n障泥油壁催梳掠。\n曾驰道同载，上林携手，灯夜初过早共约。\n又争信漂泊。\n寂寞。\n念行乐。\n甚粉淡衣襟，音断弦索。\n琼枝璧月春如昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7236, '兰陵王', '张元干', '绮霞散。\n空碧留晴向晚。\n东风里，天气困人，时节秋千闭深院。\n帘旌翠波。\n窗影残红一线。\n春光巧，花脸柳腰，勾引芳菲闹莺燕。\n闲愁费消遣。\n想娥绿轻晕，鸾鉴新怨。\n单衣欲试寒犹浅。\n羞衾凤空展，塞鸿难托，谁问潜宽旧带眼。\n念人似天远。\n迷恋。\n画堂宴。\n看最乐王孙，浓艳争劝。\n兰膏宝篆春宵短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7237, '念奴娇', '张元干', '江天雨霁，正露荷擎翠，风槐摇绿。\n试问秦楼今夜里，愁到阑干几曲。\n笑拈黄花，重题红叶，无奈归期促。\n暮云千里，桂花初绽寒玉。\n有谁伴我凄凉，除非分付与，杯中。\n水本无情山又远，回首烟波云木。\n梦绕西园，魂飞南浦，自古情难足。\n旧游何处，落霞空映孤鹜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7238, '念奴娇', '张元干', '蕊香深处，逢上巳、生怕花飞红雨。\n万点胭脂遮翠袖，谁识黄昏凝伫。\n烧烛呈妆，传杯绕槛，莫放春归去。\n垂丝无语，见人浑似羞妒。\n修禊当日兰亭，群贤弦管里，英姿如许。\n宝靥罗衣，应未有、许多阳台神女。\n气涌三山，醉听五鼓，休更分今古。\n壶中天地，大家著意留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7239, '念奴娇', '张元干', '吴松初冷，记垂虹南望，残日西沈。\n秋入青冥三万顷，蟾影吞尽湖阴。\n玉斧为谁，冰轮如许，宫阙想寒深。\n人间奇观，古今豪士悲吟。\n苍弁丹颊仙翁，淮山风露底，曾赋幽寻。\n老去专城仍好客，时拥歌吹登临。\n坐揖龙江，举杯相属，桂子落波心。\n一声猿啸，醉来虚籁千林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7240, '念奴娇', '张元干', '秋风万里，湛银潢清影，冰轮寒色。\n八月灵槎乘兴去，织女机边为客。\n山拥鸡林，江澄鸭绿，四顾沧溟窄。\n醉来横吹，数声悲愤谁测。\n飘荡贝阙珠宫，群龙惊睡起，冯夷波激。\n云气苍茫吟啸处，龟吼鲸奔天黑。\n回首当时，蓬莱方丈，好个归消息。\n而今图画，谩教千古传得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7241, '念奴娇', '张元干', '寒绡素壁，露华浓、群玉峰峦如洗。\n明镜池开秋水净，冷浸一天空翠。\n荷芰波生，菰蒲风动，惊起鱼龙戏。\n山河影里，十分光照人世。\n谁似老子痴顽，胡床坐，自引壶觞醉。\n醉里悲歌歌未彻，屋角乌飞星坠。\n对影三人，停杯一问，谁解骑鲸意。\n玉京何处，翠楼空锁十二。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7242, '念奴娇', '张元干', '垂虹望极，扫太虚纤翳，明河翻雪。\n一碧天光波万顷，涌出广寒宫阙。\n好事浮家，不辞百里，俱载如花颊。\n琴高双鲤，鼎来同醉孤绝。\n浩荡今夕风烟，人间天上，别似寻常月。\n陶冶三高千古恨，赏我中秋清节。\n八十仙翁，雅宜图画，写取横江楫。\n平生奇观，梦回犹竦毛发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7243, '石州慢', '张元干', '寒水依痕，春意渐回，沙际烟阔。\n溪梅晴照生香，冷芯数枝争发。\n天涯旧恨，试看几许消魂，长亭门外山重叠。\n不尽眼中青，是愁来时节。\n情切。\n画楼深闭，想见东风，暗销肌雪。\n辜负枕前云雨，尊前花月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7244, '石州慢', '张元干', '雨急云飞，惊散暮鸦，微弄凉月。\n谁家疏柳低迷，几点流萤明灭。\n夜帆风使，满湖烟水苍茫，菰蒲零乱秋声咽。\n梦断酒醒时，倚危樯清绝。\n心折。\n长庚光怒，群盗纵横，逆胡猖獗。\n欲挽天河，一洗中原膏血。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7245, '永遇乐', '张元干', '月仄金盆，江萦罗带，凉飙天际。\n摩诘丹青，营丘平远，一望穷千里。\n白鸥盟在，黄粱梦破，投老此心如水。\n耿无眠、披衣顾影，乍闻绕阶络纬。\n百年倦客，三生习气，今古到头谁是。\n夜色苍茫，浮云灭没，举世方熟寐。\n谁人著眼，放神八极，逸想寄尘寰外。\n独凭栏、鸡鸣日上，海山雾起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7246, '永遇乐', '张元干', '飞观横空，众山绕甸，江面相照。\n曲槛披风，虚檐挂月，据尽登临要。\n有时巾屦，访公良夜，坐我半天林杪。\n揽浮丘、飘飘衣袂，相与似游蓬岛。\n主人胜度，文章英妙，合住北扉西沼。\n何事十年，风洒露沐，不厌江山好。\n曲屏端有，吹箫人在，同倚暮云清晓。\n乘除了、人间宠辱，付之一笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7247, '八声甘州', '张元干', '倚凌空飞观，展营丘卧轴恍移时。\n渐微云点缀，参横斗转，野阔天垂。\n草树萦回岛屿，杳霭数峰低。\n共此一尊月，顾影为谁。\n俯仰乾坤今古，正嫩凉生处，浓露初扉。\n据胡床残夜，唯我与公知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7248, '八声甘州', '张元干', '记当年共饮，醉画船、摇碧花钗。\n问苍颜华发，烟蓑雨笠，何事重来。\n看尽人情物态，冷眼只堪。\n赖有西湖在，洗我尘埃。\n夜久波光山色，间澹妆浓抹，冰鉴云开。\n更潮头千丈，江海两崔嵬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7249, '水调歌头', '张元干', '落景下青嶂，高浪卷沧洲。\n平生颇惯，江海掀舞木兰舟。\n百二山河空壮。\n底事中原尘涨。\n丧乱几时休。\n泽畔行吟处，天地一沙鸥。\n想元龙，犹高卧，百尺楼。\n林风酹酒，堪笑淡话觅封侯。\n老去英雄不见。\n惟与渔樵为伴。\n回首得无忧。\n莫道三伏热，便是五湖秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7250, '水调歌头', '张元干', '闰馀有何好，一岁两中秋。\n滕王高阁曾醉，月涌大江流。\n今夜钓龙台上，还似当时逢闰，佳句记英游。\n看山兼看月，登阁复登楼。\n别离久，今古恨，大刀头。\n老来长是清梦，宛在旧神州。\n遐想芗林风味，瓮里自倾春色，不用贳貂裘。\n笑我成何事，搔首谩私忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7251, '水调歌头', '张元干', '缥缈九仙阁，壮观在人间。\n凉飙乍起，四围晴黛入阑干。\n已过中秋时候。\n便是菊花重九。\n为寿一尊欢。\n今古登高意，玉帐正清闲。\n引三巴，连五岭，控百蛮。\n元戎小队，旧游曾记并龙山。\n闽峤尤宽南顾。\n闻道天边玉露。\n持橐诏新颁。\n且拥笙歌醉，廊庙更徐还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7252, '水调歌头', '张元干', '平日几经过，重到更留连。\n黄尘乌帽，觉来眼界忽醒然。\n坐见如云秋稼，莫问鸡虫得失，鸿鹄下翩翩。\n四海九洲大，何地著飞仙。\n吸湖光，吞蟾影，倚天圆。\n胸中万顷空旷，清夜炯无眠。\n要识世间闲处，自有尊前深趣，且唱钓鱼船。\n调鼎他年事，妙手看烹鲜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7253, '水调歌头', '张元干', '雨断翻惊浪，山瞑拥归云。\n麦秋天气，聊泛征棹泊江村。\n不羡腰间金印，却爱吾庐高枕，无事闭柴门。\n搔首烟波上，老去任乾坤。\n白纶巾，玉麈尾，一杯春。\n性灵陶冶，我辈犹要个中人。\n莫变姓名吴市，且向渔樵争席，与世共浮沈。\n目送飞鸿去，何用画麒麟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7254, '水调歌头', '张元干', '露下菱歌远，萤傍藕花流。\n临溪堂上，望中依旧柳边洲。\n晚暑冰肌沾汗，新浴香绵扑粉，湘簟月华浮。\n长记开朱户，不寐待归舟。\n恍重来，思往事，搅离愁。\n天涯何处，未应容易此身休。\n莫问吴霜点鬓，细与蛮笺封恨，相见转绸缪。\n云雨阳台梦，河汉鹊桥秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7255, '水调歌头', '张元干', '万里冰轮满，千丈玉盘浮。\n广寒宫殿，西望湖海冷光流。\n扫尽长空纤翳，散乱疏林清影，风露迫人愁。\n徐步行歌去，危坐莫眠休。\n问孤蓬，缘底事，苦淹留。\n倦游回首，向来云卧两星周。\n此夜此生长好，明月明年何处，归兴在南州。\n老境一伧父，异县四中秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7256, '水调歌头', '张元干', '袖手看飞雪，高卧过残冬。\n飘然底事春到，先我逐孤鸿。\n挟取笔端风雨，快写胸中丘壑，不肯下樊笼。\n大笑了今古，乘兴便西东。\n一尊酒，知何处，又相逢。\n奴星结柳，与君同送五家穷。\n好是橘封千户，正恐楼高百尺，湖海有元龙。\n目光在牛背，马耳射东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7257, '水调歌头', '张元干', '放浪形骸外，憔悴山泽癯。\n倒冠落佩，此心不待白髭须。\n聊复脱身鹭，未暇先寻水竹，矫首汉庭疏。\n长夏啖丹荔，两纪傲闲居。\n忽风飘，连雨打，向西湖。\n藕花深处，尚能同载曲生无。\n听子谈天舌本，浇我书空胸次，醉卧踏冰壶。\n毕竟凌烟像，何似辋川图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7258, '水调歌头', '张元干', '柱策松江上，举酒酹三高。\n此生飘荡，往来身世两徒劳。\n长羡五湖烟艇，好是秋风鲈脍，笠泽久蓬蒿。\n想像英灵在，千古傲云涛。\n俯沧浪，舌空旷，恍神交。\n解衣盘礴，政须一笑属吾曹。\n洗尽人间尘土，扫去胸中冰炭，痛饮读离骚。\n纵有垂天翼，何用钓连鳌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7259, '水调歌头', '张元干', '今夕定何夕，秋垂满东瓯。\n悲凉怀抱，何事还倍去年愁。\n万里碧空如洗，寒浸十分明月，帘卷玉波流。\n非是经年别，一岁两中秋。\n坐中庭，风露下，冷飕飕。\n素娥无语相对，尊酒且迟留。\n琴罢不堪幽怨，遥想三山影外，人倚夜深楼。\n矫首望霄汉，云海路悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7260, '水调歌头', '张元干', '最乐贤王子，今岁好中秋。\n夜深珠履，举杯相属尽名流。\n宿雨乍开银汉，洗出玉蟾秋色，人在广寒游。\n浩荡山河影，偏照岳阳楼。\n露华浓，君恩重，判扶头。\n霓旌星节，已随丝管下皇州。\n满座烛光花礼，笑乌巾同醉，谁问负薪裘。\n月转檐牙晓，高枕更无忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7261, '水调歌头', '张元干', '举手钓鳌客，削迹种瓜侯。\n重来吴会三伏，行见五湖秋。\n耳畔风波摇荡，身外功名飘忽，何路射旄头。\n孤负男儿志，怅望故园愁。\n梦中原，挥老泪，遍南州。\n元龙湖海豪气，百尺卧高楼。\n短发霜黏两鬓，清夜盆倾一雨，喜听瓦鸣沟。\n犹有壮心在，付与百川流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7262, '水调歌头', '张元干', '戎虏乱中夏，星历一周天。\n干戈未定，悲咤河洛尚腥膻。\n万里两宫无路。\n政仰君王神武。\n愿数中兴年。\n吾道尊洙泗，何暇议伊川。\n吕公子，三世相，在凌烟。\n诗名独步，焉用儿辈更毛笺。\n好去承明谠论。\n照映金狨带稳。\n恩与荔枝偏。\n回首东山路，池阁醉双莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7263, '风流子', '张元干', '飞观插雕粱。\n凭虚起、缥缈五云乡。\n对山滴翠岚，两眉浓黛，水分双派，满眼波光。\n曲栏干外，汀烟轻冉冉，莎草细茫茫。\n无数钓舟，最宜烟雨，有如图画，浑似潇湘。\n使君行乐处，秦筝弄哀怨，云鬓分行。\n心醉一缸春色，满座疑香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7264, '鱼游春水', '张元干', '芳洲生苹芷。\n宿雨收晴浮暖翠。\n烟光如洗，几片花飞点泪。\n清镜空馀白发添，新恨谁传红绫寄。\n溪涨岸痕，浪吞沙尾。\n老去情怀易醉。\n十二栏干慵遍倚。\n双凫人惯风流，功名万里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7265, '宝鼎现', '张元干', '山庄图画，锦囊吟咏，胸中丘壑。\n年少日、如虹豪气，吐凤词华浑忘却。\n便袖手、向岩前溪畔，种满烟梢雾箨。\n想别墅平泉，当时草木，风流如昨。\n瘦藤闲倚看锄药。\n双芒鞋、雨後常著。\n目送处、飞鸿灭没，谁问蓬蒿争燕雀。\n乍霁月、望松云南渡，短艇沙夜泊。\n正万里清冥，千林虚籁，从渠缯缴。\n携幼尚有筠丁，谁会得、人生行乐。\n岸帻纶巾归去，深户相迷翠幕。\n恐未免、上凌烟阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7266, '祝英台近', '张元干', '枕霞红，钗燕坠。\n花露云髻。\n粉淡香残，犹带宿酲睡。\n画檐红日三竿，慵窥鸾鉴，长是倚、春风无力。\n又经岁。\n玉腕条脱轻松，羞郎见憔悴。\n何事秋来，容易又分袂。\n可堪疏雨梧桐，空阶络纬，背人处、偷弹珠泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7267, '朝中措', '张元干', '花阴如坐木兰船。\n风露正娟娟。\n翠盖匝庭芳影，青蛟平地飞涎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7268, '蝶恋花', '张元干', '窗暗窗明昏又晓。\n百岁光阴，老去难重少。\n四十归来犹赖早。\n浮名浮利都经了。\n时把青铜闲自照。\n华发苍颜，一任傍人笑。\n不会参禅并学道。\n但知心下无烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7269, '蝶恋花', '张元干', '燕去莺来春又到。\n花落花开，几度池塘草。\n歌舞筵中人易老。\n闭门打坐安闲好。\n败意常多如意少。\n著甚来由，入闹寻烦恼。\n千古是非浑忘了。\n有时独自掀髯笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7270, '沁园春', '张元干', '神水华池，汞铅凝结，虎龙往来。\n问子前午後，阳销阴长，自然炉鼎，何用安排。\n灵宝玄门，烟萝真境，三日庚生兑户开。\n泥丸透，尽周天火候，平步仙阶。\n蓬莱。\n直上瑶台。\n看海变桑田飞暮埃。\n念尘劳良苦，流光易度，明珠难得，白骨成堆。\n位极人臣，功高今古，总蹈危机吞祸胎。\n争知我，办青鞋布袜，雁荡天台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7271, '沁园春', '张元干', '枕深轩，散帙虚堂，畏景屡移。\n渐披襟临水，床就月，莲香拂面，竹色侵衣。\n压玉为醪，折荷当盏，卧看银潢星四垂。\n人归後，任肌蝉自啸，宿鸟相依。\n痴儿。\n莫道危机。\n悟三十九年都尽非。\n任纡朱拖紫，围金佩玉，青钱流地，白璧如坻。\n富贵浮云，身名零露，事事无心归便归。\n秋风动，正吴松月冷，莼长鲈肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7272, '临江仙', '张元干', '玉立清标消晚暑，胸中一段冰壶。\n画船归去醉歌珠。\n微云收未尽，残月炯如初。\n鸳鹭行间催阔步，秋来乘兴凫趋。\n烦君为我问西湖。\n不知疏影畔，许我结茅无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7273, '临江仙', '张元干', '莺唤屏山惊睡起，娇多须要郎扶。\n荼シ斗帐罢熏炉。\n翠穿珠落索，香泛玉流苏。\n长记枕痕销醉色，日高犹倦妆梳。\n一枝春瘦想如初。\n梦迷芳草路，望断素鳞书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7274, '临江仙', '张元干', '十日篱边犹袖手，天教冷地藏香。\n王孙风味最难忘。\n逃禅留坐客，度曲出宫妆。\n判却为花今夜醉，大家且泛鹅黄。\n人心休更问炎凉。\n从渠簪发短，还我引杯长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7275, '临江仙', '张元干', '露坐榕阴须痛饮，从渠叠鼓频催。\n暮山新月两徘徊。\n离愁秋水远，醉眼晓帆开。\n泛宅浮家游戏去，流行坎止忘怀。\n江边鸥鹭莫相猜。\n上林消息好，鸿雁已归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7276, '醉落魄・一斛珠', '张元干', '浮家泛宅。\n旧游记溪踪迹。\n此生已是天涯隔。\n投老谁知，还作三吴客。\n故人怪我疏髯黑。\n醉来犹似丁年日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7277, '醉落魄・一斛珠', '张元干', '绿枝红萼。\n江南芳信年年约。\n竹舆路转溪桥角。\n晴日烘香，的疏篱落。\n玉台粉面铅华薄。\n画堂长记深罗幕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7278, '醉落魄・一斛珠', '张元干', '一枝冰萼。\n鬓云低度横波约。\n醉扶曾乌巾角。\n长是春来，肠断宝钗落。\n罗衣乍怯香风薄。\n夜深花困遮垂幕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7279, '醉落魄・一斛珠', '张元干', '云鸿影落。\n风吹小艇沙泊。\n津亭古木浓阴合。\n一枕滩声，客睡何曾著。\n天涯万里情怀恶。\n年华垂暮犹离索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7280, '南歌子', '张元干', '凉月今宵满，晴空万里宽。\n素娥应念老夫闲。\n特地中秋著意、照人间。\n香雾云鬟湿，清辉玉臂寒。\n休教凝伫向更阑。\n飘下桂华闻早、大家看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7281, '南歌子', '张元干', '远树留残雪，寒江照晚晴。\n分明江上数峰青。\n倚槛旧愁新恨、一时生。\n春意来无际，归舟去有程。\n道人元自没心情。\n楚梦只因沈醉、等闲成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7282, '南歌子', '张元干', '玉露团寒菊，秋风入败荷。\n缭墙南畔曲池涡。\n天迥遥岑倒影、落层波。\n月转檐牙短，更传漏箭多。\n醉来归去意如何。\n只为地偏心远、惯弦歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7283, '南歌子', '张元干', '桂魄分馀晕，檀香破紫心。\n高鬟松绾鬓云侵。\n又被兰膏香染、色沈沈。\n指印纤纤粉，钗横隐隐金。\n更阑云雨凤帷深。\n长是枕前不见、人寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7284, '卜算子', '张元干', '的数枝斜，冰雪萦馀态。\n烛外尊前满眼春，风味年年在。\n老去惜花深，醉里愁多。\n冷蕊孤芳底处愁，少个人人戴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7285, '卜算子', '张元干', '凉气入熏笼，暗影花砌。\n紫玉谁人三弄寒，细吹断、江梅意。\n花底湿春衣，隔坐风轻递。\n却笑笙箫缑岭人，明日偷垂泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7286, '卜算子', '张元干', '风露湿行云，沙水迷归艇。\n卧看明河月满空，斗挂苍山顶。\n万古只青天，多事悲人境。\n起舞闻鸡酒未醒，潮落秋江冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7287, '卜算子', '张元干', '芳信着寒梢，影入花光画。\n玉立风前万里春，雪艳江天夜。\n谁折暗香来，故把新泻。\n记得偎人并照时，鬓乱斜枝惹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7288, '浣溪沙', '张元干', '曲室明窗烛吐光。\n瓦炉灰暖炷瓢香。\n夜阑茗碗间飞觞。\n坐稳蒲团凭几，熏馀纸帐掩梨床。\n个中风味更难忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7289, '浣溪沙', '张元干', '一枕秋风两处凉。\n雨声初歇漏声长。\n池塘零落藕花香。\n归梦等闲归燕去，断肠分付断云行。\n画屏今夜更思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7290, '浣溪沙', '张元干', '翡翠钗头缀玉虫。\n秋蟾飘下广寒宫。\n数枝金粟露华浓。\n花底清歌生皓齿，烛边疏影映酥胸。\n恼人风味冷香中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7291, '浣溪沙', '张元干', '燕掠风樯款款飞。\n艳桃李闹长堤。\n骑鲸人去晓莺啼。\n可意湖山留我住，断肠烟水送君归。\n三春不是别离时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7292, '浣溪沙', '张元干', '云气吞江卷夕阳。\n白头波上电飞忙。\n奔雷惊雨溅胡床。\n玉节故人同壮观，锦囊公子更平章。\n榕阴归梦十分凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7293, '浣溪沙', '张元干', '山绕平湖波撼城。\n湖光倒影浸山青。\n水晶楼下欲三更。\n雾柳暗时云度月，露荷翻处水流萤。\n萧萧散发到天明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7294, '浣溪沙', '张元干', '目送归州铁瓮城。\n隔江想见蜀山青。\n风前团扇仆频更。\n梦里有时身化鹤，人间无数草为萤。\n此时山月下楼明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7295, '浣溪沙', '张元干', '月转花枝清影疏。\n露华浓处滴真珠。\n天香遗恨花须。\n沐出乌云多态度，晕成娥绿费功夫。\n归时分付与妆梳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7296, '浣溪沙', '张元干', '花气天然百和芬。\n仙风吹过海中春。\n龙涎沈水总销魂。\n清润巧萦金缕细，氤氲偏傍玉脂温。\n别来长是惜馀熏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7297, '浣溪沙', '张元干', '萼绿华家萼绿春。\n山瓶何处下青云。\n浓香气味已醺人。\n竹叶传杯惊老眼，松醪题赋倒纶巾。\n须防银字暖朱唇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7298, '浣溪沙', '张元干', '花气蒸浓古鼎烟。\n水沈春透露华鲜。\n心清无暇数龙涎。\n乞与病夫僧帐座，不妨公子醉茵眠。\n普熏三界扫腥膻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7299, '浣溪沙', '张元干', '花气薰人百和香。\n少陵佳句是仙方。\n空教蜂蝶为花忙。\n和露摘来轻换骨，傍怀闻处恼回肠。\n去年时候入思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7300, '浣溪沙', '张元干', '残腊晴寒出众芳。\n风流勾引破春光。\n年年长为此花忙。\n夜久莫教银烛，酒边何似玉台妆。\n冰肌温处觅馀香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7301, '浣溪沙', '张元干', '几明窗乐未央。\n熏炉茗碗是家常。\n客来长揖对胡床。\n蟹眼汤深轻泛乳，龙涎灰暖细烘香。\n为君行草写秋阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7302, '浣溪沙', '张元干', '榕叶桄榔驿枕溪。\n海风吹断瘴云低。\n薄寒初觉到征衣。\n岁晚可堪归梦远，愁深偏恨得书稀。\n荒庭日脚又垂西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7303, '柳梢青', '张元干', '清山浮碧。\n细风丝雨，新愁如织。\n慵试春衫，不禁宿酒，天涯寒食。\n归期莫数芳辰，误几度、回廊夜色。\n入户飞花，隔帘双燕，有谁知得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7304, '柳梢青', '张元干', '小楼南陌。\n翠金勒，谁家春色。\n冷雨吹花，禁烟怯柳，伤心行客。\n少年百万呼卢，拥越女、吴姬共掷。\n被底香浓，尊前烛灭，如今消得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7305, '醉花阴', '张元干', '紫枢泽笏趋龙尾。\n平入钧衡位。\n春殿听宣麻，争喜登庸，何似今番喜。\n台宜有神仙裔。\n奕世貂蝉贵。\n玉砌长兰芽，好拥笙歌，长向花前醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7306, '醉花阴', '张元干', '翠箔阴阴笼画阁。\n昨夜东风恶。\n芳径满香泥，南陌东郊，惆怅妨行乐。\n伤春比似年时恶。\n潘鬓新来薄。\n何处不禁愁，雨滴花腮，和泪胭脂落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7307, '长相思令・长相思', '张元干', '香暖帏。\n玉暖肌。\n娇卧嗔人来睡迟。\n印残双黛眉。\n虫声低。\n漏声稀。\n惊枕初醒灯暗时。\n梦人归未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7308, '长相思令・长相思', '张元干', '花下愁。\n月下愁。\n花落月明人在楼。\n断肠春复秋。\n从他休。\n任他休。\n如今青鸾不自由。\n看看天尽头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7309, '如梦令', '张元干', '雨洗青冥风露。\n云外双星初度。\n乞巧夜楼空，月妒回廊私语。\n凝伫。\n凝伫。\n不似去年情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7310, '如梦令', '张元干', '潮退江南晚渡。\n山暗水西烟雨。\n天气十分凉，断送一年残暑。\n归去。\n归去。\n香雾曲屏深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7311, '如梦令', '张元干', '卧看西湖烟渚。\n绿盖红妆无数。\n帘卷曲栏风，拂面荷香吹雨。\n归去。\n归去。\n笑损花边鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7312, '春光好', '张元干', '疏雨洗，细风吹。\n淡黄时。\n不分小亭芳草绿，映檐低。\n楼下十二层梯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7313, '春光好', '张元干', '吴绫窄，藕丝重。\n一钩红。\n翠被眠时常要人暖，著怀中。\n六幅裙轻风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7314, '虞美人', '张元干', '开残桃李春方到。\n谁送东风早。\n杖藜幽径踏馀花。\n却对绿阴青子、问年华。\n迢迢云水横清浅。\n不遣愁眉展。\n数竿修竹自横斜。\n犹有小窗朱户、似侬家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7315, '青玉案', '张元干', '华裾玉辔青丝。\n记年少、金吾从。\n花底朝回珠翠拥。\n晓钟初断，宿酲犹带，绿锁窗中梦。\n天涯相遇鞭鸾凤。\n老去堂成更情重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7316, '青玉案', '张元干', '王孙陌上春风。\n蕊珠宴、云从。\n归去笙歌常醉拥。\n蜡残花炬，月侵冰簟，惯作凉堂梦。\n玉人劝客钗斜凤。\n条脱擎杯腕嫌重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7317, '青玉案', '张元干', '花王独占春风远。\n看百卉、芳菲遍。\n五福长随今日宴。\n粉光生艳，宝香飘雾，方响流苏颤。\n寿祺堂上修篁畔。\n乳燕双双贺新院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7318, '青玉案', '张元干', '水芝香远摇红影。\n泛瑞霭、横山顶。\n缥缈笙歌云不定。\n玉钩斜挂，素蟾初满，醉惬浮瓜冷。\n庭兰戏彩传金鼎。\n小袖青衫更辉映。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7319, '青玉案', '张元干', '银潢露洗冰轮皎。\n谪仙下、蓬莱岛。\n帘卷横山珠翠绕。\n生朝香雾，玳筵丝管，长醉壶天晓。\n金銮夜锁麻新草。\n入辅明光拜元老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7320, '青玉案', '张元干', '月华冷沁花梢露。\n芳意恋、香肌住。\n心字龙涎饶济楚。\n素馨风味，碎琼流品，别有天然处。\n围炉屈曲宜深炷。\n留取春光向朱户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7321, '青玉案', '张元干', '平生百绕垂虹路。\n看万顷、翻云去。\n山澹夕晖帆影度。\n菱歌风断，袜罗尘散，总是关情处。\n少年陈迹今迟暮。\n走笔犹能醉时句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7322, '点绛唇', '张元干', '山暗秋云，暝鸦接翅啼榕树。\n故人何处。\n一夜溪亭雨。\n梦入新凉，只道消残暑。\n还知否。\n燕将雏去。\n又是流年度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7323, '点绛唇', '张元干', '水驿凝霜，夜帆风驶潮生晓。\n酒醒寒悄。\n枕底波声小。\n好去归舟，有个人风调。\n君行了。\n此欢应少。\n索共梅花笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7324, '点绛唇', '张元干', '春晓轻雷，采苹洲上清明雨。\n乱云遮树。\n暗澹江村路。\n今夜归舟，绿润红香处。\n遥山暮。\n画楼何许。\n唤取潮回去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7325, '点绛唇', '张元干', '画阁深围，暖红光里芳林影。\n暗香成阵。\n上下花相映。\n倒挂疏枝，月落参横冷。\n休装景。\n要人酒醒。\n除是花枝并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7326, '点绛唇', '张元干', '嵩洛云烟，间生真相耆英裔。\n要知鲐背。\n难老中和气。\n报道玉堂，已草调元制。\n华夷喜。\n绣裳貂珥。\n便向东山起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7327, '点绛唇', '张元干', '清夜沈沈，暗蛩啼处檐花落。\n乍凉帘幕。\n香绕屏山角。\n堪恨归鸿，情似秋云薄。\n书难托。\n尽交寂寞。\n忘了前时约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7328, '点绛唇', '张元干', '醉泛吴松，小舟谁怕东风大。\n旧时经过。\n曾向垂虹卧。\n月淡霜天，今夜空清坐。\n还知麽。\n满斟高和。\n只有君知我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7329, '点绛唇', '张元干', '减塑冠儿，宝钗金缕双结。\n怎教宁帖。\n眼恼儿里劣。\n韵底人人，天与多磨折。\n休分说。\n放灯时节。\n闲了花和月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7330, '点绛唇', '张元干', '水风帆，两眉只解相思皱。\n悄然难受。\n教我怎唧。\n待得书来，不管归时瘦。\n娇痴後。\n是事就。\n只这难依口。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7331, '虞美人', '张元干', '广寒蟾影开云路。\n目断愁来处。\n菊花轻泛玉杯空。\n醉後不知星斗、乱西东。\n今宵入梦阳台雨。\n谁忍先归去。\n酒醒长是五更钟。\n休念旧游吹帽、几秋风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7332, '虞美人', '张元干', '西郊追赏寻芳处。\n闻道冲寒去。\n雨肥红绽向南枝。\n岁晚才开应是、恨春迟。\n天涯乐事王孙贵。\n花底还君醉。\n有人风味胜疏梅。\n醉里折花归去、更传杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7333, '虞美人', '张元干', '菊坡九日登高路。\n往事知何处。\n陵迁谷变总成空。\n回首十年秋思、吹台东。\n西窗一夜萧萧雨。\n梦绕中原去。\n觉来依旧画楼锺。\n不道木犀香撼、海山风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7334, '渔家傲', '张元干', '钓笠披云青障绕。\n橛头细雨春江渺。\n白鸟飞来风满棹。\n收纶了。\n渔童拍手樵青笑。\n明月太虚同一照。\n浮家泛宅忘昏晓。\n醉眼冷看城市闹。\n烟波老。\n谁能惹得闲烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7335, '渔家傲', '张元干', '楼外天寒山欲暮。\n溪过雪後藏云树。\n小艇风斜沙觜露。\n流年度。\n春光已向梅梢住。\n短梦今宵还到否。\n苇村四望知何处。\n客里从来无意绪。\n催归去。\n故园正要莺花主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7336, '渔家傲', '张元干', '寒日西郊湖畔路。\n天低野阔山无数。\n路转斜冈花满树。\n丝吹雨。\n南枝占得春光住。\n藉草携壶花底去。\n花飞酒面香浮处。\n老手调羹当独步。\n须记取。\n坐中都是芳菲侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7337, '谒金门', '张元干', '鸳鸯渚。\n春涨一江花雨。\n别岸数声初过橹。\n晚风生碧树。\n艇子相呼相语。\n载取暮愁归去。\n寒食烟村芳草路。\n愁来无着处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7338, '谒金门', '张元干', '风露底。\n石上岸巾愁起。\n月到房心天似水。\n乱峰清影里。\n此去登瀛须记。\n今夕道山同醉。\n春殿明年人共指。\n玉皇香案吏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7339, '谒金门', '张元干', '清光溢。\n影转画檐凉入。\n风露一天星斗湿。\n无云天更碧。\n满引送君何惜。\n记取吾曹今夕。\n目断秋江君到日。\n潮来风正急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7340, '瑞鹧鸪', '张元干', '雏莺初转斗尖新。\n双蕊花娇掌上身。\n总解满斟偏劝客，多生俱是绮罗人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7341, '瑞鹧鸪', '张元干', '白衣苍狗变浮云。\n千古功名一聚尘。\n好是悲歌将进酒，不妨同赋惜馀春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7342, '好事近', '张元干', '老去更思归，芳草正薰南陌。\n上巳又逢寒食，叹三年为客。\n吹花小雨湿秋千，闲却好春色。\n天甚不怜人老，早教人归得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7343, '好事近', '张元干', '梅润乍晴天，帘卷画堂风月。\n珠翠共迷香雾，是长年时节。\n瑶池清夜宴群仙，鸾笙未吹彻。\n西母醉中微笑，看蟠桃初结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7344, '好事近', '张元干', '春色到花房，芳信一枝偏好。\n勾引万红千翠，为化工呈巧。\n花姑玉貌笑东风，今朝放春早。\n看取鬓边幡胜，永宜春难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7345, '好事近', '张元干', '斗帐炷炉熏，花露成芗泽。\n萦透雪儿金缕，醉玉壶春色。\n非烟非雾锁窗中，王孙倦留客。\n不道粉墙南畔，也有人闻得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7346, '怨王孙・忆王孙', '张元干', '小院春昼。\n晴窗霞透。\n把雨燕脂，倚风翠袖。\n芳意恼乱人多。\n暖金荷。\n多情不分群葩後。\n伤春瘦。\n浅黛眉尖秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7347, '怨王孙・忆王孙', '张元干', '霁雨天迥。\n平林烟暝。\n灯闪沙汀，水生钓艇。\n楼外柳暗谁家。\n乱昏鸦。\n相思怪得今番甚。\n寒食近。\n小砑鱼笺信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7348, '喜迁莺令・喜迁莺', '张元干', '文倚马，笔如椽。\n桂殿早登仙。\n旧游册府记当年。\n衮绣合貂蝉。\n庆天申，瞻玉座，鹭正陪班。\n看君稳步过花砖。\n归院引金莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7349, '喜迁莺令・喜迁莺', '张元干', '云叶乱，月华光。\n罗幕卷新凉。\n玉醅初泛嫩鹅黄。\n花露滴秋香。\n地行仙，天上相。\n风度世间人样。\n悬知洗盏径开尝。\n谁醉伴禅床。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7350, '喜迁莺慢・喜迁莺', '张元干', '雁塔题名，宝津宴，盛事簪绅常说。\n文物昭融，圣代搜罗，千里争趋丹阙。\n元侯劝驾，乡老献书，发轫龟前列。\n山川秀，圜冠众多，无如闽越豪杰。\n姓标红纸，帖报泥金，喜信归来俱捷。\n骄马芦鞭醉垂，蓝绶吹雪。\n芳月素娥情厚，桂华一任郎君折。\n须满引，南台又是，合沙时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7351, '鹧鸪天', '张元干', '不怕微霜点玉肌。\n恨无流水照冰姿。\n与君著意从头看，初见东南第一枝。\n人散後，雪晴时。\n陇头春色寄来迟。\n使君本是花前客，莫怪殷勤为赋诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7352, '忆秦娥', '张元干', '桃花萼。\n雨肥红绽东风恶。\n东风恶。\n长亭无寐，短书难托。\n征衫辜负深闺约。\n禁烟时候春罗薄。\n春罗薄。\n多应消瘦，可梳掠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7353, '明月逐人来', '张元干', '花迷珠翠。\n香飘罗绮。\n帘旌外、月华如水。\n暖红影里，谁会王孙意。\n最乐升平景致。\n长记宫中五夜，春风鼓吹。\n游仙梦、轻寒半醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7354, '小重山', '张元干', '谁向晴窗伴素馨。\n兰芽初秀发，紫檀心。\n国香幽艳最情深。\n歌白雪，祗少一张琴。\n新月冷光侵。\n醉时花近眼，莫频斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7355, '生查子', '邓肃', '执手两潸然，情极都无语。\n去马更匆匆，一息迷回顾。\n孤馆得村醪，一醉空离绪。\n酒醒却无人，帘外三更雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7356, '感皇恩', '邓肃', '翠竹谩连云，天风不到。\n帘幕重重自热恼。\n冷香忽至，爱惜当同芝草。\n井花浮碧玉，炎威扫。\n酒渴想东邻，忧心如捣。\n纳履生疑谩悔懊。\n未容沈李，相对尊前倾倒。\n报君惟短句，琼琚好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7357, '一剪梅・一翦梅', '邓肃', '雨过春山翠欲浮。\n影落寒溪碧玉流。\n片帆乘兴挂东风，夹岸花香拥去舟。\n尊酒时追李郭游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7358, '蝶恋花', '邓肃', '执手长亭无一语。\n泪眼汪汪，滴下阳关句。\n牵马欲行还复住。\n春风吹断梨花雨。\n海角三千千叠路。\n归侍玉皇，那复回头顾。\n旌旆已因风月驻。\n何妨醉过清明去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7359, '江城子', '邓肃', '酒阑携手过回廊。\n夜初凉。\n月如霜。\n笑问木樨，何日吐天香。\n待插一枝归斗帐，和云雨，襄王。\n如今满目雨新黄。\n绕高堂。\n自芬芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7360, '菩萨蛮', '谢明远', '春风春雨花经眼。\n石泉槐火春容晚。\n流水自无情。\n回波聚落英。\n问春何处去。\n春向天边住。\n举酒欲销愁。\n酒阑愁更愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7361, '踏莎行', '谢明远', '楚树芊绵，江云芜漫。\n晓风吹堕梅千片。\n惊禽飞去响春空，平沙月落光零乱。\n人意伤离，物华惊换。\n武夷此去如天远。\n临分为我少留连，柳条独在江南岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7362, '踏莎行', '张焘', '阳复寒根，气回枯杆。\n前村昨夜梅初绽。\n谁言造化没偏颇，半开何独南枝暖。\n素艳幽轻，清香远散。\n雪中岂恨和羹晚。\n不知何处误东君，至今不使春拘管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7363, '恨欢迟・恨来迟', '张焘', '淡薄情怀。\n浅缀胭脂。\n独占江梅。\n最好是、严凝苦寒天气，却是开时。\n也不许、桃杏斗妍媸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7364, '青玉案', '姚述尧1', '三年枕上吴中路。\n遣黄耳、随君去。\n君到松江呼小渡。\n莫惊鸥鹭，四桥尽是，老子经行处。\n辋川图上看春暮。\n长记高人右丞句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7365, '薄幸', '吕渭老', '青楼春晚。\n昼寂寂、梳匀又懒。\n乍听得、鸦啼莺弄，惹起新愁无限。\n记年时、偷掷春心，花间隔雾遥相见。\n便角枕题诗，宝钗贳酒，共醉青苔深院。\n怎忘得、回廊下，携手处、花明月满。\n如今但暮雨，蜂愁蝶恨，小窗闲对芭蕉展。\n却谁拘管。\n尽无言、闲品秦筝，泪满参差雁。\n腰支渐小，心与杨花共远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7366, '望海潮', '吕渭老', '侧寒斜雨，微灯薄雾，匆匆过了元宵。\n帘影护风，盆池见日，青青柳叶柔条。\n碧草皱裙腰。\n正昼长烟暖，蜂困莺娇。\n望处凄迷，半篙绿水浸斜桥。\n孙郎病酒无聊。\n记乌丝醉语，碧玉风标。\n新燕又双，兰心渐吐，嘉期趁取花朝。\n心事转迢迢。\n但梦随人远，心与山遥。\n误了芳音，小窗斜日对芭蕉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7367, '选冠子', '吕渭老', '雨湿花房，风斜燕子，池阁昼长春晚。\n檀盘战象，宝局铺棋，筹画未分还懒。\n谁念少年，齿怯梅酸，病疏霞盏。\n正青钱遮路，绿丝明水，倦寻歌扇。\n空记得、小阁题名，红笺青制，灯火夜深裁剪。\n明眸似水，妙语如弦，不觉晓霜鸡唤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7368, '选冠子', '吕渭老', '风约晴云，花乾宿露，帘幕万家清晓。\n青帘赛酒，小坞藏春，冶叶艳枝相照。\n羊驾小车，笑逐游人，远迷芳草。\n更红英飞舞，绣茵连接，雾台烟沼。\n年少日、细马戎鞯，红靴玉带，同指软尘西笑。\n珍珠戏掷，彩笔搜奇，不觉暮春莺老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7369, '念奴娇', '吕渭老', '暮云收尽，霁霞明、高拥一轮寒玉。\n帘影横斜房户静，小立啼红蔌蔌。\n素鲤频传，蕉心微展，双蕊明红烛。\n开门疑是，故人敲撼窗竹。\n长记那里西楼，小寒窗静，尽掩风筝鸣屋。\n泪眼灯光情未尽，尽觉语长更促。\n短短霞杯，温温罗，妙语书裙幅。\n五湖何日，小舟同泛春绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7370, '情久长', '吕渭老', '锁窗夜永，无聊尽作伤心句。\n甚近日、带红移眼，梨脸择雨。\n春心偿未足，怎忍听、啼血催归杜宇。\n暮帆挂、沈沈暝色，衮衮长江，流不尽、来无据。\n点检风光，岁月今如许。\n趁此际、浦花汀草，一棹东去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7371, '情久长', '吕渭老', '冰梁跨水，沈沈霁色遮千里。\n怎向我、小舟孤楫，天外飘逐。\n夜寒侵短发，睡不稳、窗外寒风渐起。\n岁华暮、蟾光射雪，碧瓦飘霜，尘不动、寒无际。\n鸡咽荒郊，梦也无归计。\n拥绣枕、断魂残魄，清吟无味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7372, '满江红', '吕渭老', '晚浴新凉，风蒲乱、松梢见月。\n庭阴尽、暮蝉啼歇。\n萤绕井阑帘入燕，荷香兰气供摇。\n赖晚来、一雨洗游尘，无些热。\n心下事，峰重叠。\n人甚处，星明灭。\n想行云应在，凤凰城阙。\n曾约佳期同菊蕊，当时共指灯花说。\n据眼前、何日是西风，凉吹叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7373, '满江红', '吕渭老', '笑语移时，风影乱、半帘寒日。\n鲜明是、晚来妆饰。\n共说西园携手处，小桥深竹连苔色。\n到如今、梧叶染清霜，封行迹。\n春未透，梅先拆。\n人纵健，时难得。\n想明年虚过，上元寒食。\n数著佳期愁入眼，雨珠零乱梨花湿。\n任翠鬟、猗侧背斜阳，鸣瑶瑟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7374, '满江红', '吕渭老', '燕拂危樯，斜日外、数峰凝碧。\n正暗潮生渚，暮风飘席。\n初过南村沽酒市，连空十顷菱花白。\n想故人、轻障游丝，闻遥笛。\n鱼与雁，通消息。\n心与梦，空牵役。\n到如今相见，怎生休得。\n斜抱琵琶传密意，一襟新月横空碧。\n问甚时、同作醉中仙，烟霞客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7375, '满江红', '吕渭老', '山绕吴城，修竹外、满林围碧。\n任孤樯百丈，远牵江色。\n政简民闲无一事，同游仍是鸳鸾客。\n到晚年、遗爱续新题，都堪说。\n修门赋，今谁续。\n痛饮士，天应惜。\n正彩霞垂帔，暮风飘瑟。\n笑疾禅痴今在否，风灯石火同飘忽。\n去醉乡、深处著身心，休铭栉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7376, '醉蓬莱', '吕渭老', '任落梅铺缀，雁齿斜桥，裙腰芳草。\n闲伴游丝，过晓园庭沼。\n厮近清明，雨晴风软，称少年寻讨。\n碧缕墙头，红云水面，柳堤花岛。\n谁信而今，怕愁憎酒，对著花枝，自疏歌笑。\n莺语丁宁，问甚时重到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7377, '齐天乐', '吕渭老', '香红飘没明春水，寒食万家游舫。\n整整斜斜，疏疏密密，帘缬旗红相望。\n江波荡漾。\n称彩舰龙舟，绣衣霞桨。\n舞楫争先，歌笑箫鼓乱清唱。\n重来刘郎又老，对故园桃红春晚，尽成惆怅。\n泪雨难晴，愁眉又结，翻覆十年手掌。\n如今怎向。\n念舞板歌尘，远如天上。\n斜日回舟，醉魂空舞扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7378, '沁园春', '吕渭老', '复把元宵，等闲过了，算来告谁。\n整二年三岁，尊前笑处，知他陪了，多少歌诗。\n岂信如今，不成些事，还是无聊空皱眉。\n争知道，冤家误我，日许多时。\n心儿。\n转更痴迷。\n又疑道、清明得共伊。\n但自家晚夜，多方遣免，不须烦恼，雨月为期。\n用破身心，博些欢爱，有后不成人便知。\n从来是，这风流伴侣，有分双飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7379, '满路花・促拍满路花', '吕渭老', '西风秋日短，小雨菊花寒。\n断云低古木，暗江天。\n星娥尺五，佳约误当年。\n小语凭肩处，犹记西园。\n画桥斜月阑干。\n鸟啼花落，春信遣谁传。\n尚容清夜梦、小留连。\n青楼何处，宝镜注婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7380, '蓦山溪', '吕渭老', '韵高格妙。\n不数闲花草。\n向晚小梳妆，换一套、新衣始了。\n横钗整鬓，倚醉唱清词，房户静，酒杯深。\n帘幕明残照。\n扬州一梦，未尽还惊觉。\n自恁在心头，拈不出、倚时是了。\n吴霜点鬓，春色老刘郎，云路远，晚溪横，谁见桃花笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7381, '蓦山溪', '吕渭老', '元宵灯火。\n月淡游人可。\n携手步长廊，又说道、倾心向我。\n归来一梦，整整十年馀，人似旧，去无因，牵惹情怀破。\n章台杨柳，闻道无关锁。\n行客挽长条，悄不似、当初些个。\n而今休也，摇落任东风，但恣意，尽留情，我也知无那。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7382, '千秋岁', '吕渭老', '宝香盈袖。\n约腕金条瘦。\n裙儿细裥如肩皱。\n笑多簪髻侧，语小丝簧奏。\n洞房晚，千金未直横波溜。\n缘短欢难又。\n人去春如旧。\n枝上月，谁携手。\n宿云迷远梦，泪枕中残酒。\n怎奈向，繁阴乱叶梅如豆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7383, '早梅芳近・早梅芳', '吕渭老', '画帘深，妆阁小。\n曲径明花草。\n风声约雨，暝色啼鸦暮天杳。\n染眉山对碧，匀脸霞相照。\n渐更衣对客，微坐自轻笑。\n醉红明，金叶倒。\n恣看还新好。\n莹汪粉泪，滴烁波光射庭沼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7384, '醉落魄・一斛珠', '吕渭老', '明窗读易。\n时才人地俱超轶。\n偶然一坠槐安国。\n说利谈功，这事怎休得。\n何时置酒图书室。\n挥弦目送西飞翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7385, '醉落魄・一斛珠', '吕渭老', '纤鞋窄袜。\n红茵自称琵琶拍。\n明衣妆脸春梳掠。\n好好亭亭，那得恁标格。\n匆匆一醉霜华白。\n归来偏记蓝桥宅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7386, '惜分飞', '吕渭老', '白玉花骢金络脑。\n十里华灯相照。\n帘映春窈窕。\n雾香残腻桃花笑。\n一串歌珠云外袅。\n饮罢玉楼寒悄。\n归去城南道。\n柳梢猎猎东风晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7387, '浣溪沙', '吕渭老', '烟柳鹊做巢。\n青青弱草带斜桥。\n莺声多在杏花梢。\n逐伴不知春路远，见人时著小词招。\n阿谁有分伴吹箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7388, '浣溪沙', '吕渭老', '彩选骰儿隔袖拈。\n整钗微见玉纤纤。\n夜寒窗外更垂帘。\n好事灯花双作蕊，照人月影入斜檐。\n新愁日日座中添。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7389, '浣溪沙', '吕渭老', '做得因缘不久长。\n惊风枝上偶成双。\n归来魂梦带幽香。\n灯下揉花春去早，竹间影月索归忙。\n十年前事费思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7390, '渔家傲', '吕渭老', '闻道庐山横广泽。\n晴空万顷波涛白。\n上有至人营窟宅。\n经游客。\n古今多是烟霞谪。\n一钵上人轻六翮。\n选场要射如来策。\n点化黄金非妙药。\n难堪酌。\n三生一口都吞却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7391, '渔家傲', '吕渭老', '昨夜山空流石乳。\n道人妙手亲拈取。\n未欲凌云归洞府。\n清风举。\n大千一叶同掀舞。\n笑把须弥挝破鼓。\n东山云作西山雨。\n我欲住庵无拄斧。\n君相许。\n三更明月湖心午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7392, '渔家傲', '吕渭老', '潦倒瞿昙饶口悄。\n拈花冤道头陀笑。\n鸡足山中眠未觉。\n谁知道。\n至今功业犹分剖。\n唇口周遮何日了。\n禅床四面藤萝绕。\n有个路头君试讨。\n梅花老。\n南园蝴蝶飞芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7393, '渔家傲', '吕渭老', '高绊袈裟挑纸帔。\n一杯茶罢成行计。\n路入庐山风细细。\n轻弹指。\n百千三昧俱游戏。\n法椅何曾烧两臂。\n谁知纸上无穷意。\n欲识普贤真实际。\n地。\n小炉雪夜和衣睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7394, '渔家傲', '吕渭老', '顶上铁轮飞火焰。\n防身细按威神剑。\n体用双行谁敢觇。\n光闪闪。\n何须更把茶林撼。\n衲子家风存古俭。\n一条榔栗如天堑。\n粥鼓未鸣灯火暗。\n无恩念。\n断崖古木横藤簟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7395, '渔家傲', '吕渭老', '落月杜鹃啼未了。\n粥鱼忽报千山晓。\n笠子盖头衣钵少。\n穿林表。\n回头高刹空中小。\n官路旧多林木绕。\n露浓花蕊皆颠倒。\n渡水登山排草草。\n卢山好。\n香炉峰下湖波渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7396, '思佳客', '吕渭老', '江上何人一笛横。\n倚楼吹得月华生。\n寒风堕指倾三弄，小市收灯欲二更。\n持蟹股，破霜橙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7397, '思佳客', '吕渭老', '微点胭脂晕泪痕。\n更衣整鬓立黄昏。\n春风搅树花如雨，夕霭迷空燕趁门。\n题往事，锦回纹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7398, '好事近', '吕渭老', '别酒带愁酸，千里失群黄鹄。\n行到小桥梯下，便飞云南北。\n不妨垂手小徘徊，日影转阑曲。\n从此贺囊佳制，有新奇题目。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7399, '好事近', '吕渭老', '飞雪过江来，船在赤栏桥侧。\n惹报布帆无恙，著两行亲札。\n从今日日在南楼，鬓自此时白。\n一咏一觞谁共，负平生书册。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7400, '好事近', '吕渭老', '年少万函书，朱紫只应低拾。\n更赖主人明眼，作青云梯级。\n归来应是印累累，笳鼓闹乡邑。\n若访老人生计，贩谢郎蓑笠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7401, '好事近', '吕渭老', '云影护梅枝，短短未禁飞雪。\n彩幅自题新句，作催妆佳阕。\n西楼昨夜五更寒，恐一枝先发。\n元是素娥无寐，驾半轮明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7402, '好事近', '吕渭老', '小饮破清寒，坐久困花颓玉。\n两行艳衣明粉，听阿谁拘束。\n丽华百媚坐来生，仙韵动群目。\n一曲凤箫同去，倦人间丝竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7403, '天仙子', '吕渭老', '楼下辘轳横露井。\n楼上婵娟开晓镜。\n下楼难忘上楼时，风未定。\n帆不正。\n簌簌珍珠挥麈柄。\n眉上新愁吹不醒。\n别酒未斟歌未忍。\n雪中梅下定重来，烟暝暝。\n肠寸寸。\n莫放笛声吹落尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7404, '燕归梁', '吕渭老', '楼外东风杜宇声。ピ\n双枕细眉颦。ピ\n女郎番马小山屏。ピ\n金笼冷、梦魂惊。ピ\n起来重绾双罗髻，无个事、泪盈盈。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7405, '小重山', '吕渭老', '半夜灯残鼠上檠。\n上窗风动竹，月微明。\n梦魂偏记水西亭。\n琅碧，花影弄晴蜓。\n千里暮云平。\n南楼催上烛，晚来晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7406, '河传', '吕渭老', '斜红照水。\n似晴空万里。\n明霞相倚。\n逐伴笑歌，小立绿槐阴里。\n诮没些，春气味。\n纷纷觑著闲桃李。\n浅浅深深，不满游人意。\n幽艳一枝，向晚重帘深闭。\n是青君、爱惜底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7407, '清平乐', '吕渭老', '水瓶石砚。\n败壁蜗书篆。\n窗下日舒缝衲线。\n屋角晚风飞霰。\n上元灯火佳时。\n长廊语笑追随。\n高卧一番纸帔，觉来月贯南枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7408, '握金钗', '吕渭老', '风日困花枝，晴蜂自相趁。\n晚来红浅香尽。\n整顿腰肢晕残粉。\n弦上语，梦中人，天外信。\n青杏已成双，新尊荐樱笋。\n为谁一和销损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7409, '握金钗', '吕渭老', '向晚小妆匀，明窗倦裁剪。\n见花清泪遮眼。\n开尽繁桃又春晚。\n心下事，比年时，都较懒。\n胡蝶入帘飞，郎声似莺啭。\n见来无计拘管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7410, '南歌子', '吕渭老', '策杖穿荒圃，登临笑晚风。\n无穷秋色蔽晴空。\n遥见夕阳江上、卷飞蓬。\n雁过菰蒲远，山遥梦寐通。\n一林枫叶堕愁红。\n归去暮烟深处、听疏锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7411, '南歌子', '吕渭老', '远色连朱阁，寒鸦噪夕阳。\n小炉温手酌鹅黄。\n掩乱一枝清影、在寒窗。\n念远歌声小，嗔归泪眼长。\n纤腰今属冶游郎。\n朝暮楚宫云雨、恨茫茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7412, '蝶恋花', '吕渭老', '风洗游丝花皱影。\n碧草初齐，舞鹤闲相趁。\n短梦乍回慵理鬓。\n惊心忽数清明近。\n逐伴强除眉上恨。\n趁蝶西园，不觉鞋儿褪。\n醉笑眼波横一寸。\n微微酒色生红晕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7413, '蝶恋花', '吕渭老', '花色撩人红入眼。\n可是东君，要得人肠断。\n欲诉深情春不管。\n风枝雨叶空撩乱。\n谩插一枝飞一盏。\n小赏幽期，破我平生愿。\n珍约未成春又短。\n但凭蝴蝶传深怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7414, '品令', '吕渭老', '绣衣未整。\n傍窗格、临清镜。\n新霜薄雾，这下几日，阴晴不定。\n欲插黄花，心事又还记省。\n去年香径。\n共粉蝶、闲相趁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7415, '祝英台・祝英台近', '吕渭老', '宝蟾明，朱阁静，新燕近帘语。\n还记元宵，灯火小桥路。\n逢迎春笋柔微，凌波纤稳，诮不顾、斗斜三鼓。\n甚无据。\n谁信一霎是春，惊声留不住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7416, '水调歌头', '吕渭老', '扁舟思独往，樯影划晴烟。\n要伴人随明月，踏破水中天。\n谁信骑鲸高逝，空对笔端风雨，如泛楚江船。\n老子穷无赖，端欲把降竿。\n白苹汀，归老计，似高闲。\n平生爱我，一言相置二刘间。\n准拟何山松桂，折足铛能安稳，芋火对阑残。\n何必少林语，立雪问心安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7417, '水调歌头', '吕渭老', '江湖堪极目，非雾亦非烟。\n故人相见，纵横高义薄云天。\n已具萸尊茗话，怅望云中江树，不见子猷船。\n日色隐林表，十里认帆竿。\n百年间，无个事，且安闲。\n功名两字，茫然都坠有无间。\n且尽身前一醉，休问古来今往，及取菊花残。\n仙事占无据，竹帛笑刘安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7418, '水调歌头', '吕渭老', '秋斋多梦谒，舌本欲生烟。\n独步一庭明月，雁字已横天。\n作个生涯不遂，松竹雨荒三径，却忆五湖船。\n小阮贫尤甚，犊鼻挂长竿。\n白鸥汀，风共水，一生闲。\n横琴唳鹤，要携妻子老云间。\n灯火荧荧深夜，高卧南窗折几，杯到不留残。\n莫遣江湖手，遮日向长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7419, '水调歌头', '吕渭老', '心肝皆锦绣，落笔尽云烟。\n诗狂酒兴，要骑赤鲤上青天。\n织女回车相劳，指点虚无征路，翻动月明船。\n举手谢同辈，岂复念渔竿。\n我平生，心正似，白云闲。\n衣冠污我，偶逢游戏到人间。\n常念孤云高妙，若作辘轳俯仰，谁复食君残。\n拜尘金谷辈，都是卧崇安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7420, '水调歌头', '吕渭老', '诗人翻水尽，寂寞五侯烟。\n醉魂何在，应骑箕尾列青天。\n记得平生谈笑，夹岸手栽杨柳，同泛夜深船。\n溪水还依旧，深浅半青竿。\n小神仙，殷七七，许闲闲。\n黄粱未熟，经游都在梦魂间。\n我厌嚣寺浊味，几欲凌云羽化，鸡犬不留残。\n俗事丹砂冷，且抱一枝安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7421, '水调歌头', '吕渭老', '暮云遮远眼，叠叠入青烟。\n十年不见，醯鸡同舞瓮中天。\n闻道山阴回棹，相去都无百里，李郭可同船。\n行止皆天意，端欲自操竿。\n功名事，须早计，真安闲。\n高才妙手，不当留意市廛间。\n俄已山林长往，尘面时时拂镜，齿发甚衰残。\n廊庙非吾事，茅屋且安安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7422, '水调歌头', '吕渭老', '抚床多感慨，白发困风烟。\n出门有碍，更堪寒暮雪飞天。\n君弃一盂一衲，奔走五湖清海，杯度不乘船。\n来访山中友，□□□□竿。\n看人间，谁得似，谪仙闲。\n生涯不问，留情多在酒杯间。\n剪烛西风谈笑，零落一尊相对，不觉已更残。\n回首功名事，笺记谢任安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7423, '水调歌头', '吕渭老', '十年禅榻畔，风雨扬茶烟。\n跳丸日月，未甘白发困尧天。\n江左风流才子，要伴江湖张翰，同泛洛阳船。\n酌酒情无尽，海燕绕船竿。\n逼人来，功业事，不教闲。\n男儿三十，定当谈笑在堂间。\n老子婆娑贫态，闭户长须赤脚，他日要分残。\n禹浪桃花影，归棹正轻安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7424, '江城子', '吕渭老', '晓参垂户宿酲醒。\n坐南亭。\n对疏星。\n点点萤光，偏向竹梢明。\n望断长空何处是，云叶乱，彩霞横。\n西楼依旧抱重城。\n小银屏。\n此时情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7425, '江城子', '吕渭老', '闻君见影已堪怜。\n短因缘。\n偶同筵。\n相见无言，分散倍依然。\n做梦杨花随去也，妆阁畔，绣床前。\n觉来离绪意绵绵。\n写蛮笺。\n倩谁传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7426, '水龙吟', '吕渭老', '五湖春水茫茫，梦魂夜逐杨花去。\n汀花岸草，佳人微笑，眼波横注。\n借问刘郎，心期则甚，一成无据。\n自春来泪满，蓝袖口，没整顿，心情处。\n闻道相如病渴，念文君、白头新句。\n相思两地，无穷烟水，一庭花雾。\n锦字藏头，织成机上，一时分付。\n问他年，更有微云淡月，重来兮否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7427, '减字木兰花', '吕渭老', '雨帘高卷。\n芳树阴阴连别馆。\n凉气侵楼。\n蕉叶荷枝各自秋。\n前溪夜舞。\n化作惊鸿留不住。\n愁损腰肢。\n一桁香销旧舞衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7428, '减字木兰花', '吕渭老', '明眸巧笑。\n坐久更宜灯烛照。\n小醉辞归。\n怀抱明明只自知。\n琐窗重见。\n桃李春风三月面。\n怎不思量。\n折柳孤吟断杀肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7429, '江城子慢', '吕渭老', '新枝媚斜日。\n花径霁、晚碧泛红滴。\n近寒食。\n蜂蝶乱、点检一城春色。\n倦游客。\n门外昏鸦啼梦破，春心似、游丝飞远碧。\n燕子又语斜檐，行云自没消息。\n当时乌丝夜语，约桃花时候，同醉瑶瑟。\n甚端的。\n看看是、榆角杨花飞掷。\n怎忘得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7430, '如梦令', '吕渭老', '百和宝钗香佩。\n短短同心霞带。\n清镜照新妆，巧画一双眉黛。\n多态。\n多态。\n偷观榴花窗外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7431, '极相思', '吕渭老', '拂墙花影飘红。\n微月辨帘栊。\n香风满袖，金莲印步，狭径迎逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7432, '极相思', '吕渭老', '西园斗草归迟。\n隔叶啭黄鹂。\n阑干醉倚，秋千背立，数遍佳期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7433, '贺新郎', '吕渭老', '斜日封残雪。\n记别时、檀槽按舞，霓裳初彻。\n唱煞阳关留不住，桃花面皮似热。\n渐点点、珍珠承睫。\n门外潮平风席正，指佳期、共约花同折。\n情未忍，带双结。\n钗金未断肠先结。\n下扁舟、更有暮山千叠。\n别後武陵无好梦，春山子规更切。\n但孤坐、一帘明月。\n蚕共茧、花同蒂，甚人生要见，底多离别。\n谁念我，泪如血。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7434, '浪淘沙', '吕渭老', '倚枕数更筹。\n清夜悠悠。\n竹风荷露小窗秋。\n往事迷人浑不省，总是离愁。\n无赖是横眸。\n济楚风流。\n一时搂揽著心头。\n调数梦魂将我去，明月重楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7435, '思佳客', '吕渭老', '深夜槐风析酲惺。\n露荷凉气满西庭。\n凭栏小语花梢月，缓步偷拈石上萤。\n秋意早，暑衣轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7436, '二郎神', '吕渭老', '西池旧约。\n燕语柳梢桃萼。\n向紫陌、秋千影下，同绾双双凤索。\n过了莺花休则问，风共月、一时闲却。\n知谁去、唤得秋阴，满眼败垣红叶。\n飘泊。\n江湖载酒，十年行乐。\n甚近日、伤高念远，不觉风前泪落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7437, '百宜娇・眉妩', '吕渭老', '隙月垂篦，乱蛩催织，秋晚嫩凉房户。\n燕拂帘旌，鼠窥窗网，寂寂飞萤来去。\n金铺镇掩，谩记得、花时南浦。\n约重阳、萸糁菊英，小楼遥夜歌舞。\n银烛暗、佳期细数。\n帘幕渐西风，午窗秋雨。\n叶底翻红，水面皱碧，灯火裁缝砧杵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7438, '醉思仙', '吕渭老', '断人肠。\n正西楼独上，愁倚斜阳。\n称鸳鸯，两两池塘。\n春又老，人何处，怎惯不思量。\n到如今，瘦损我，又还无计禁当。\n小院呼卢夜，当时醉倒残缸。\n被天风吹散，凤翼难双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7439, '眼儿媚', '吕渭老', '晓钗催鬓语南风。\n碧涧小桥通。\n榆阴短短，露光炯炯，满地花红。\n天涯不见归帆影，蜂蝶尽西东。\n宿酲渐解，残妆犹在，晓日帘栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7440, '眼儿媚', '吕渭老', '循槛琅粉沾衣。\n一片子规啼。\n蓬壶梦短，蜀衾香远，愁损腰肢。\n石城堂上双双燕，应傍莫愁飞。\n春江艇子，雪中梅下，知与谁期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7441, '梦玉人引', '吕渭老', '上危梯尽，尽画阁迥，昼帘垂。\n曲水飘香，小园莺唤春归。\n舞袖弓弯，正满城、烟草凄迷。\n结伴踏青，趁蝴蝶双飞。\n赏心欢计，从别後、无意到西池。\n自检罗囊，要寻红叶留诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7442, '倾杯令・杯倾乐', '吕渭老', '枫叶飘红，莲房肥露，枕席嫩凉先到。\n帘外蟾华如扫。\n枝上啼鸦催晓。\n秋风又送潘郎老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7443, '倾杯令・倾杯乐', '吕渭老', '隔座藏钩，分曹射覆，烛艳渐催三鼓。\n筝按教坊新谱。\n楼外月生春浦。\n徘徊争忍忙归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7444, '生查子', '吕渭老', '摊钱临小窗，扑蝶穿斜径。\n醉戏晚风前，吹乱连枝影。\n别来秋夜长，梦到金屏近。\n肠断一声鸡，残月悬朝镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7445, '生查子', '吕渭老', '裙长步渐迟，扇薄羞难掩。\n鞋褪倚郎肩，问路眉先敛。\n踏青南陌回，倚醉开娇靥。\n今夜更同行，忍笑匀妆脸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7446, '生查子', '吕渭老', '双鬟绿发齐，多笑蔫红落。\n穿竹过西斋，问字时偷学。\n娇慵不惯羞，同倚阑干角。\n屈指数元宵，灯火堪行乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7447, '扑蝴蝶近・扑蝴蝶', '吕渭老', '分钗绾髻，洞府难分手。\n离觞短阕，啼痕冰舞袖。\n马嘶霜滑，桥横路转，人依古柳。\n晓色渐分星斗。\n怎分剖。\n心儿一似，倾入离愁万千斗。\n垂鞭伫立，伤心还病酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7448, '扑蝴蝶近・扑蝴蝶', '吕渭老', '风荷露竹，秋意侵疏鬓。\n微灯曲几。\n有帘通桂影。\n乍凉衣著，轻明微醉，歌声听稳。\n新愁人方寸。\n怎不闷。\n当初欲凭，燕翼西飞寄归信。\n小窗睡起，梁间都去尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7449, '一落索', '吕渭老', '蝉带残声移别树。\n晚凉房户。\n秋风有意染黄花，下几点、凄凉雨。\n渺渺双鸿飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7450, '一落索', '吕渭老', '宫锦裁书寄远。\n意长辞短。\n香兰泣露雨催莲，暑气昏池馆。\n向晚小园行遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7451, '一落索', '吕渭老', '鸟散馀花飞舞。\n满地风雨。\n长江滚滚接天流，夜送征帆去。\n今夜行云何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7452, '谒金门', '吕渭老', '人已老。\n春亦不留些少。\n花尽叶长蚕又抱。\n子规啼未了。\n往事不论多少。\n且向尊前一笑。\n白发满头愁已到。\n路长波渺渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7453, '鼓笛慢・水龙吟', '吕渭老', '拍肩笑别洪崖，共看紫海还清浅。\n蓬壶旧约，人间舒笑，桃红千遍。\n去岁争春，今年逼腊，满空飘霰。\n渐横枝照水，清绿弄日，都点缀、江南岸。\n须吸百川为寿，卷恩波、已倾银汉。\n戎袍拥戟，万钉围带，天孙新眷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7454, '卜算子', '王之道', '拄颊看西湖，屡对纶巾岸。\n江上相从醉万山，六见年华换。\n君唱我当酬，我醉君休管。\n明日醒时小艇东，莫负传书雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7455, '卜算子', '王之道', '堂下水浮天，人指山为岸。\n水落寒沙只见山，暗被天偷换。\n堂上老诗翁，客至劳相管。\n风喘西头客自东，目送云中雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7456, '卜算子', '王之道', '今日富川滨，後夜湓江岸。\n千里西湖指顾间，未怕新年换。\n再见复何时，此意凭吟管。\n应有新诗当尺书，日望南来雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7457, '丑奴儿・采桑子', '王之道', '青腰似诧天公富，奔走风云。\n银界无痕。\n委巷穷山草木春。\n玉楼不怕歌茵湿，笑语纷纷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7458, '桃源忆故人', '王之道', '逢人借问春归处。\n遥指芜城烟树。\n收尽柳梢残雨。\n月闯西南户。\n游丝不解留伊住。\n漫惹闲愁无数。\n燕子为谁来去。\n似说江头路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7459, '桃源忆故人', '王之道', '不知春色归何处。\n但见茂林芳树。\n庭巷落花如雨。\n斗乱穿窗户。\n晚行溪上东风住。\n荷点青钱无数。\n蛱蝶飞来还去。\n错认花间路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7460, '桃源忆故人', '王之道', '南园最是花多处。\n门掩绿杨千树。\n别後几番风雨。\n碧藓侵苔户。\n侬家旧在郊西住。\n门外远山无数。\n谁道不如归去。\n咫尺长安路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7461, '桃源忆故人', '王之道', '依依杨柳青青草。\n梦断画桥春晓。\n风里落花如扫。\n莫厌寻芳早。\n酴芍药看来好。\n恰似江湖遗老。\n锦段荷□传到。\n愧乏琼瑶报。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7462, '桃源忆故人', '王之道', '望中风絮迷烟草。\n愁结几番昏晓。\n花径有时亲扫。\n载酒应须早。\n人情曷似春山好。\n山色不随春老。\n旧隐何当重到。\n迎得平安报。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7463, '沁园春', '王之道', '城郭萧条，风雨霏微，酝造春愁。\n况鸷群雕鹗，未谐荐祢，棘栖鸾凤，犹叹栖仇。\n世路如棋，人情似纸，厚薄高低何日休。\n逢殷浩，会披云对月，同赋南楼。\n堪嗟日月如流。\n甚首夏来今半秋。\n纵荻花枫叶，强撩归思，有莼羹菰饭，归更何忧。\n三板松舟，一篙秋水，百里淮山无暂留。\n何须问，蘧蘧栩栩，孰是庄周。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7464, '惜奴娇', '王之道', '不厮知名，怎奈向、前缘注定。\n一封书、便成媒娉。\n千里相从，恰似寻盟合姓。\n泥泞。\n尚隔个、轿儿难近。\n薄薄纱厨，小驿夜凉人静。\n红一点、暗通犀晕。\n花月多情，摇碎半窗清影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7465, '惜奴娇', '王之道', '甚麽因缘，恰得一年相聚。\n和闰月、更无剩数。\n说著分飞，背面偷弹玉箸。\n好去。\n记取许时言语。\n旧爱新人，後夜一时分付。\n从前事、不堪回顾。\n怎奈冤家，抵死牵肠惹肚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7466, '南乡子', '王之道', '遗爱满南州。\n千骑曾为万里游。\n琳馆归来，无责更无忧。\n坐听笙歌醉玉舟。\n香雾郁金虬。\n春入梅花助献酬。\n请祝遐年，长笑挹浮丘。\n何止莘君一百筹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7467, '南乡子', '王之道', '天际彩虹垂。\n风起痴云快一吹。\n原隰，春水更弥弥。\n布谷期从野鸟知。\n初霁卷帘时。\n巷陌泥融燕子飞。\n午醉醒来，红日欲平西。\n一碗新茶乳面肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7468, '南乡子', '王之道', '出户绣帘垂。\n拂面从他细细吹。\n乘兴有谁招访戴，难为。\n暖帐薰炉醉不知。\n闲看逐风时。\n欲著梅花又却飞。\n雅兴佳人回舞袂，相宜。\n试比冰肌可煞肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7469, '南乡子', '王之道', '春霁柳花垂。\n娇软轻狂不待吹。\n圆欲成球还复碎，谁为。\n习习和风即旧知。\n深院日长时。\n乱扑珠帘入坐飞。\n试问荻芽生也未，偏宜。\n出网河豚美更肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7470, '南乡子', '王之道', '风急断虹收。\n孤鹜摇摇下荻洲。\n醉帽尽从吹落去，飕飕。\n幸有黄花插满头。\n君唱我当酬。\n千里湖山照眼秋。\n不见故人思故国，休休。\n一阕清歌听解愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7471, '南乡子', '王之道', '翠袖熨沈香。\n黛拂修蛾淡淡妆。\n消得多情锺傅粉，何郎。\n风动珠帘月半床。\n素手捧瑶觞。\n谁念苏州已断肠。\n夜雨不随歌扇歇，浪浪。\n归去无心赋海棠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7472, '减字木兰花', '王之道', '彩幡金胜。\n一笑酬春聊适性。\n呆女痴儿。\n半挽梅花半柳枝。\n追欢何计。\n幸对绿尊环皂髻。\n欲舞还羞。\n美盼娇回碧水秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7473, '减字木兰花', '王之道', '诗成呵手。\n欲写已输君赋就。\n寒粟生肤。\n一盏浇肠可得无。\n回风弄巧。\n比似婆娑尤敏妙。\n似个人人。\n嗅认梅花孰是真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7474, '减字木兰花', '王之道', '尊前放手。\n铜钵声穷诗已就。\n姑射肌肤。\n舞罢缠头怎得无。\n青腰更巧。\n搓粉团酥来斗妙。\n不敢方人。\n容色依稀似太真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7475, '减字木兰花', '王之道', '玉奴招手。\n来看前山琼琢就。\n透骨侵肤。\n似恁清寒更有无。\n春工纵巧。\n只许梅花称独妙。\n花底逢人。\n逐马银杯误认真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7476, '减字木兰花', '王之道', '鳖头龟手。\n孤坐书生能意就。\n暖体温肤。\n绣被春寒想见无。\n雪词工巧。\n高压君房天下妙。\n白发欺人。\n甚矣吾衰懒是真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7477, '减字木兰花', '王之道', '修眉山远。\n娇抹乌云秋水畔。\n酒里花前。\n坐拥斯人怎得寒。\n浮满。\n须索空缸仍覆盏。\n正恐相妨。\n归去如闻笑语香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7478, '减字木兰花', '王之道', '江梅清远。\n潇洒一枝尊俎畔。\n雪里风前。\n照水窥檐巧耐寒。\n多情美满。\n共饮自应渠盏。\n醉赏何妨。\n倾国天教抵死香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7479, '减字木兰花', '王之道', '笑中声远。\n走向曲房花树畔。\n拥在尊前。\n顿觉春温却夜寒。\n愿酬心满。\n只得教伊频劝盏。\n缓唱何妨。\n贴体衫儿扑扑香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7480, '减字木兰花', '王之道', '仙姿凝远。\n半出新妆琼户畔。\n缓步来前。\n正值东风料峭寒。\n钗头花满。\n舞罢梅英飞入盏。\n一何妨。\n花与佳人巧斗香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7481, '减字木兰花', '王之道', '离筵暂住。\n君在龙舒曾是主。\n今作行人。\n卧辙何妨借寇恂。\n清歌妙舞。\n断送吟鞭乘醉去。\n一休辞。\n捧爵佳人玉箸垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7482, '减字木兰花', '王之道', '金尊频倒。\n照坐梅花清更好。\n春到长杨。\n宠拜三公入郑庄。\n月城两载。\n千里生灵蒙惠爱。\n舞彻歌词。\n并立新妆绿带垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7483, '减字木兰花', '王之道', '蛾眉螓首。\n舞雪娇回开冻候。\n尽道今年。\n千里风光萃绮筵。\n坐来新月。\n照我苍颜并白发。\n酒到休辞。\n自有黄芽介寿祺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7484, '阮郎归', '王之道', '玉绳低转斗阑干。\n欠温春酒寒。\n夜长风劲怯衣单。\n有人哦二山。\n蟾欲满，雁初还。\n桃花微破颜。\n枕痕犹带断红残。\n无言心自闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7485, '阮郎归', '王之道', '长杨风软弄腰肢。\n日长胡蝶飞。\n雨馀新绿细通池。\n玉钩悬妓衣。\n鸿雁远，子规啼。\n此情谁得知。\n一尊聊与故人持。\n醉来悲别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7486, '长相思', '王之道', '雨。\n日。\n洗出远山三四重。\n分明眉黛浓。\n野桥西，官路东。\n小驿夜凉风入松。\n梦魂谁与同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7487, '长相思', '王之道', '花一枝。\n酒一卮。\n举酒对花君莫辞。\n人生多别离。\n行相随。\n坐相随。\n更有何人得似伊。\n春融胡蝶飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7488, '长相思', '王之道', '天四垂。\n山四围。\n山色天容入坐帷。\n清风吹我衣。\n湖水东，江水西。\n东去西来无尽期。\n不如君共伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7489, '长相思', '王之道', '吴江枫。\n吴江风。\n索索秋声飞乱红。\n晚来归兴浓。\n淮山西，淮山东。\n明月今宵何处同。\n相寻魂梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7490, '长相思', '王之道', '风凄凄。\n雨霏霏。\n风雨夜寒人别离。\n梦回还自疑。\n蛩声悲。\n漏声迟。\n一点青灯明更微。\n照人双泪垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7491, '长相思', '王之道', '桃花春。\n杏花春。\n桃杏妖娆如个人。\n歌声清遏云。\n酒醺醺。\n烛荧荧。\n眼尾微红无限情。\n相逢堪断魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7492, '满庭芳', '王之道', '紫角初繁，青裳正好，充闾清露飘香。\n悬弧何早，乌辔上扶桑。\n试问椿龄几许，逾万计、才满三章。\n佳辰乐，林塘增气，菡萏拥红妆。\n称觞。\n人共庆，盘中白李，来自华阳。\n倩壶中日月，特地舒长。\n定见霜毫换绿，天荐祉、家庆延昌。\n情千万，辞悭思窘，聊献满庭芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7493, '满庭芳', '王之道', '蔡水西来，于门南峙，天波拥入华楹。\n芝兰争秀，难弟遇难兄。\n欲说随龙雨露，庆千载、河海初清。\n良辰好，榴花照眼，绿柳隐啼莺。\n君恩，隆横赐，冰桃火枣，来自蓬瀛。\n正雾横玉篆，泉泻金鲸。\n四座香和酒泛，对妙舞、弦索铿。\n椿难老，年年今日，论报祝长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7494, '满庭芳', '王之道', '翠盖千重，青钱万叠，雨馀绿涨银塘。\n藕花无数，高下斗芬芳。\n浑似华清赐浴，温泉滑、洗出真香。\n何妨更，合欢连理，高压万芝祥。\n风流，贤太守，当年奏瑞，盛事名堂。\n好是琉璃池上，一片宫妆。\n况有薰风解愠，流霞泛、丝竹成行。\n依莲暇，联珠唱玉，应不愧金相。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7495, '满庭芳', '王之道', '天驷呈祥，土牛颁政，欢呼万井春来。\n雕轮丹毂，杂沓展轻雷。\n风动珠帘不卷，香散处、半露梅腮。\n东郊好，波澜浸绿，萌蘖上条枚。\n徘徊。\n应共怪，十年豹隐，一旦鸾台。\n问康时术业，混俗情怀。\n过雪湖山清丽，笙歌沸、舞袖萦回。\n兵厨富，酒肠似海，莫惜醉金杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7496, '满庭芳', '王之道', '雪霁风温，霜消日暖，一时笑语烘春。\n草堂何幸，四座德星邻。\n聊借红妆侑爵，兰膏腻、高髻盘云。\n清歌妙，贯珠馀韵，犹振画梁尘。\n熙朝，卿相种，扁舟东去，入侍严宸。\n忆当年擢桂，连见三秦。\n休说参军俊逸，应难过、开府清新。\n从今去，八州都督，端不困无津。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7497, '满庭芳', '王之道', '露溢金茎，风翔玉宇，嫩凉初霁秋容。\n山肴野蔌，聊快一尊同。\n正值大田多稼，临邛隘、酒客憧憧。\n追随处，杯盘狼藉，野草荫长松。\n新词，何所似，金声应铎，玉气腾虹。\n时来终宦达，休怨苍穹。\n顾我蹉跎老矣，飘素发、衰态龙锺。\n心犹壮，会看文度，独步大江东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7498, '满庭芳', '王之道', '麦野青深，桃溪红暗，浪游何处芳园。\n清明初过，门巷霭晴烟。\n柳外池塘绿遍，溪流细、终日溅溅。\n东风软，谁家儿女，墙里送秋千。\n花前。\n从醉倒，吾当尽量，君盍忘年。\n纵杯盘草草，随分开筵。\n自有高谈雄辩，何须问、急管繁弦。\n身长健，少陵如在，应赋饮中仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7499, '满庭芳', '王之道', '歌彻骊驹，酒斟，帆樯高映城楼。\n绣衣携具，开宴话离愁。\n两岸橙黄橘绿，一行雁、几点沙鸥。\n情千万，相看无语，送我上孤舟。\n悠悠。\n冬向晚，梅花潜暖，随处香浮。\n奈长亭饮散，无计淹留。\n归路淮山百舍，空梦想、连岁清游。\n烦双鲤，频将尺素，来往寄江流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7500, '醉蓬莱', '王之道', '对黄芦卧雨，苍雁横秋，江天重九。\n千载渊明，信风流称首。\n吟绕东篱，白衣何处，谁复当年偶。\n蓝水清游，龙山胜集，恍然依旧。\n萸实嫩红，菊团馀馥，付与佳人，比妍争嗅。\n一曲婆娑，看舞腰萦柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7501, '醉蓬莱', '王之道', '正薰风解愠，萱草忘忧，黄梅新霁。\n缥缈歌台，半金衣公子。\n丹桂香中，碧梧枝上，两两飞还止。\n似说当年，而今时候，长庚诞贵。\n恩厚随龙，官崇御带，二十横金，玉阶寸地。\n须信骅骝，一日能千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7502, '浣溪沙', '王之道', '一样檀心半卷舒。\n淡黄衫子衬冰肤。\n细看全似那人姝。\n枕里芳蕤薰绣被，酒中馀馥溢金壶。\n不须频嗅惹罗裾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7503, '浣溪沙', '王之道', '晓日晖晖玉露光。\n枝头一样斗宫妆。\n可怜娇额半涂黄。\n衣与酴新借色，肌同卜更薰香。\n风流荀令雅相当。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7504, '浣溪沙', '王之道', '过雨花容杂笑啼。\n淡妆深注半开时。\n娇娆情态自天姿。\n新浴太真增艳丽，微风新燕斗清奇。\n绿窗朱户雅相宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7505, '浣溪沙', '王之道', '阳气初升土脉苏。\n东郊人散欲回车。\n一时春雪十年无。\n鱼枕蕉深浮酒蚁，鹿胎冠子粲歌珠。\n题诗不觉烛然须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7506, '浣溪沙', '王之道', '体粟须烦鼎力苏。\n流涎正值麴盈车。\n坐来兽炭拨还无。\n一阕可能酬一绝，双银端不换双珠。\n松毛粉白老翁须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7507, '浣溪沙', '王之道', '春到衡门病滞苏。\n力强犹可驾柴车。\n少年狂望一时无。\n清坐不堪肌起粟，高谈还喜唾成珠。\n红裙痴笑雪如须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7508, '浣溪沙', '王之道', '冻卧袁安已复苏。\n闭门那患出无车。\n似渠人物到今无。\n可笑山夸片玉，须怜沧海叹遗珠。\n时来应许捋君须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7509, '浣溪沙', '王之道', '残雪笼晴作寒。\n北风吹浪过前滩。\n远山云气尚漫漫。\n睡起阳乌窥破牖，坐怜香雾蔼雕盘。\n一尊聊佐旅中欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7510, '浣溪沙', '王之道', '玉骨冰肌软更香。\n一枝丹棘映青裳。\n相逢归去未须忙。\n曲里春山情不浅，尊前秋水意何长。\n酒醺颜色粉生光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7511, '浣溪沙', '王之道', '寒透珠帘怯晓霜。\n灰飞缇室验回阳。\n坐看红日上修廊。\n泉泻龙头深泛酒，烟凝象口暖吹香。\n及时歌舞意何长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7512, '浣溪沙', '王之道', '水外山光淡欲无。\n堤边草色翠如铺。\n绿杨风软鸟相呼。\n牛蒡叶齐罗翠扇，鹿黎花小隘真珠。\n一声何处叫提壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7513, '东风第一枝', '王之道', '玉骨冰肌，绛趺檀口，玲珑亚竹当户。\n嫣然照雪精神，消得东君眷与。\n群芳退舍，顾凡下、非伊朋侣。\n却自有、卜酴，次第效颦追步。\n寓心赏、还须吟醉，赴目成、便依歌舞。\n情锺束素无华，意在含情不语。\n纷纷桃李，亦何用、轻猜轻妒。\n觅一枝、欲寄相思，伴取个人书去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7514, '西江月', '王之道', '黄菊正怀彭泽，白衣俄致江州。\n登高馀醉快扶头。\n此贶义兼情厚。\n痛饮还须酒对，清吟况值诗流。\n轻投无惜万金酬。\n木李旧先琼玖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7515, '西江月', '王之道', '北陆藏冰欲竟，东风解冻非遥。\n一时芳意巧相撩。\n入眼绿娇红小。\n柳色轻摇弱线，梅英纷缀枯梢。\n觥筹醉里赖君饶。\n归去斜阳尚早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7516, '西江月', '王之道', '磨急锯霏琼屑，汤鸣车转羊肠。\n一杯聊解水仙浆。\n七日狂酲顿爽。\n指点红裙劝坐，招呼岩桂分香。\n看花不觉酒浮觞。\n醉倒宁辞鼠量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7517, '西江月', '王之道', '雪後千林尚冻，城边一径微通。\n柳梢摇曳转东风。\n来看梅花应梦。\n酒面初潮蚁绿，歌唇半启樱红。\n冰肌绰约月朦胧。\n仿佛暗香浮动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7518, '西江月', '王之道', '春色荒荒别浦，春潮滟滟长堤。\n绿杨风喘客帆迟。\n肠断江南双鲤。\n短梦当年楚雨，扁舟後夜秦溪。\n一声啼鸟怨春归。\n人在酴花底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7519, '西江月', '王之道', '一霎轻云过雨，半篙新绿横舟。\n梅花池馆暗香浮。\n酒入朱唇红透。\n有恨尤怜别恨，多愁不惯春愁。\n舞馀何惜更迟留。\n肠断断肠更後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7520, '西江月', '王之道', '一别清风北牖，几番明月西楼。\n断肠千里致书邮。\n借问近来安否。\n归路淮山过雨，归舟江水澄秋。\n佳人应已数程头。\n准拟到家时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7521, '归朝欢', '王之道', '透隙敲窗风。\n坐见广庭飞缟白。\n长安道上正骑驴，蔡州城里谁坚壁。\n表表风尘物。\n瑶林琼宇三豪客。\n对分毫、连珠唱玉，竟把诗笺掷。\n草草杯盘还促席。\n痛饮狂歌话胸臆。\n前村昨夜访梅花，东邻休更夸容色。\n清欢那易得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7522, '宴春台', '王之道', '翠竹扶疏，丹葵隐映，绿窗朱户萦回。\n帘卷虾须，清风时自南来。\n题舆好客筵开。\n俨新妆、深出云街。\n歌珠累贯，一时倾坐，全胜腰雷。\n金猊袅碧，玉兕浮红，令传三杏，情寄双梅。\n楼头漏促，笼纱暗落花煤。\n锦里遗音，忆当年、曾赋春台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7523, '朝中措', '王之道', '江城春霁雪初融。\n楼观瑞烟中。\n向晚金莲无数，一时开遍东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7524, '朝中措', '王之道', '从来寒食半阴晴。\n花底听歌声。\n昨夜满城风雨，惜花还系心情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7525, '朝中措', '王之道', '朝阳淡淡宿云轻。\n风入管弦声。\n十里碧芜幽步，一枝丹杏柔情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7526, '朝中措', '王之道', '老穷无赖事成丛。\n短发自松。\n坐想帝城当日，万花绣出天宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7527, '朝中措', '王之道', '暖风迟日透香肌。\n春到柳边枝。\n曾见酒红潮颊，玉人初出罗帏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7528, '朝中措', '王之道', '天庭丹熟在何时。\n铅汞适投机。\n四海方思霖雨，未容驾鹤先飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7529, '朝中措', '王之道', '州闾庠序少追随。\n俯仰鬓成丝。\n仕宦孰逾君达，恩施遍及庭芝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7530, '朝中措', '王之道', '满庭岩桂蔼香风。\n人在画堂中。\n欲验鲁侯难老，欢声千里攸同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7531, '朝中措', '王之道', '君心节直更心虚。\n移植并庭除。\n好在红蕖相映，卷帘如见吴姝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7532, '朝中措', '王之道', '晴烟漠漠日晖晖。\n天际远山低。\n槛外碧芜千里，坐来目送鸥飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7533, '玉楼春', '王之道', '年来六十增三岁。\n却忆去年趋盛会。\n风流人物胜斜川，灼灼有同前日事。\n不知弦管催新水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7534, '玉楼春', '王之道', '少年心性消磨尽。\n三斗烂肠浑是闷。\n看书聊复强寻行，属句不妨闲趁韵。\n此生自断天休问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7535, '石州慢', '王之道', '磔攘送寒，燔烈兴岁，又颁尧历。\n青霭烧痕，绿浮风皱，暖回春色。\n地天交泰，时当倾否，五鬼休相厄。\n何妨笑倚东风，一饮杯三百。\n长忆。\n苻坚入寇，功高晋室，无如安石。\n义概雄心，辄莫等闲抛掷。\n盖壤声名，鼎彝勋业。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7536, '鹊桥仙', '王之道', '霜风擢霁，云涛涨晚，更觉我心弥壮。\n一尊谁与醉西风，辄莫负、高吟胜赏。\n致君才术，康时事业，到底不容闲放。\n十年湖海哄樵歌，何幸出、阳春绝唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7537, '鹊桥仙', '王之道', '断虹霁雨，馀霞送日，帘卷西楼月上。\n银河风静夜无波，天亦为、云相访。\n蛛丝有恨，鹊桥何处，回首又成惆怅。\n长江滚滚向东流，写不尽、别离情状。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7538, '菩萨蛮', '王之道', '香鬟倭堕兰膏腻。\n睡起搔头红玉坠。\n秋水不胜情。\n盈盈横沁人。\n朱阑频徙倚。\n笑与花争媚。\n眉黛索重添。\n春酲意未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7539, '菩萨蛮', '王之道', '绿杨低映深深院。\n春风不动珠帘卷。\n乳燕引雏飞。\n流苏尽日垂。\n绮窗开小宴。\n娅姹莺声啭。\n一饷不闻声。\n罗衣香汗轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7540, '菩萨蛮', '王之道', '小庭过雨莓苔滑。\n碧波滟滟池也阔。\n睡起□雕阑。\n不言神思闲。\n晚来调瑟罢。\n笑语秋千下。\n高枕绿杨风。\n隔帘花映红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7541, '菩萨蛮', '王之道', '晴窗睡起炉烟直。\n香云堕髻娇无力。\n溪水碧涵空。\n拒霜深浅红。\n坠鞭还驻马。\n缥缈珠帘下。\n自是意中人。\n临风休障尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7542, '千秋岁', '王之道', '薰风散雾。\n帘幕清无暑。\n萱草径，荷花坞。\n幽香浮几席，秀色侵庭庑。\n微雨过，绿杨枝上珠成缕。\n双燕飞还语。\n似庆良辰遇。\n酾美酒，烹肥。\n何妨饮且醉，共作斑衣舞。\n人竟报，蟠桃已实君知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7543, '千秋岁', '王之道', '斜风横雨。\n咫尺高城路。\n红蓼岸，苍葭浦。\n滞留春色晚，栖泊邮亭暮。\n信杳杳，鹊声近有无凭据。\n肠断家何处。\n又见重阳度。\n多少恨，从谁诉。\n黄鸡斟白酒，自促供搜句。\n归去好，人生莫被浮名误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7544, '千秋岁', '王之道', '金风玉宇。\n庭院新经雨。\n香有露，清无暑。\n溪光摇几席，岚翠横尊俎。\n烘笑语，佳时聊复乡人聚。\n门外荷花浦。\n秋到化无数。\n红脍鲤。\n青浮醑。\n何妨文字饮，更得江山助。\n从此去。\n蒲轮入佐中兴主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7545, '千秋岁', '王之道', '山前湖外。\n初日浮云退。\n荷气馥，槐阴碎。\n葵花红障锦，萱草青垂带。\n谁得似，黄鹂求友新成对。\n忆昔东门会。\n千古同侵盖。\n人已远，歌如在。\n银钩虽可漫，琬琰终难改。\n愁浩荡，临风令我思淮海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7546, '千秋岁', '王之道', '晓霜初肃。\n秋色团芳菊。\n榴转紫，柑犹绿。\n昨朝吹帽会，未快登临目。\n须信道，兵厨准拟三千斛。\n采采香云掬。\n泛泛纷浮玉。\n红袖捧，清歌逐。\n何妨倾坐客，共献长生祝。\n归去好，北门夜饮金莲烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7547, '千秋岁', '王之道', '熙熙台上。\n秋色增清壮。\n和气溢，祥烟扬。\n淮山供杂俎，湖水浮新酿。\n人共仰，貔貅坐拥诗书将。\n箫鼓声嘹亮。\n珠翠环相向。\n回妙舞，迟妍唱。\n竟斟长命，同试沧溟量。\n锋车往，东归遂继华原相。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7548, '胜胜慢・声声慢', '王之道', '鲁云书瑞，周日迎长，晓占缇室飞灰。\n玉勒朝天，千门禁钥齐开。\n帘卷扇分雉尾，香风远、人到蓬莱。\n霞觞满，□万年献祝，宫殿昭回。\n况有金瓯名姓，一任名园萧散，元自徘徊。\n门外锋车，又连凤沼相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7549, '胜胜慢・声声慢', '王之道', '凌云气节，贯日精忠，艰难未许心灰。\n芳酒一尊，对君聊为君开。\n要识治安非晚，乐得贤、新赋台莱。\n愁似雪，喜青天万里，晓霁春回。\n须信赤绳系足，朱衣点额终在，休叹淹徊。\n梅实槐花，看看便是相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7550, '胜胜慢・声声慢', '王之道', '菊团封绿，莲萼凋红，萧然独见芳姿。\n短墙高榭，疏筠怪石偏宜。\n香遍秋风到处，微雨过、清露零时。\n花阴下，称笺毫唱和，杖履追随。\n曷似江头竹外，凌霜犯雪，岁晚争奇。\n夕赏朝吟，劝秋莫放离披。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7551, '宴桃源・如梦令', '王之道', '飞雪舞稀还骤。\n高阁下临群岫。\n独立遂移时，归去黄昏前後。\n知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7552, '宴桃源・如梦令', '王之道', '风急柳花飞骤。\n白尽千林万岫。\n樵担晚来归，正在栖鸦啼後。\n知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7553, '宴桃源・如梦令', '王之道', '黄叶声迟风歇。\n龛火夜寒明灭。\n残月却多情，来照先生归辙。\n清绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7554, '宴桃源・如梦令', '王之道', '遥指汤泉西路。\n隐约碧云天暮。\n宿鸟择深枝，两两相呼如语。\n凝伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7555, '宴桃源・如梦令', '王之道', '水外漫山桃李。\n那得个中风味。\n一种最怜渠，酒著佳人半醉。\n还似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7556, '折丹桂', '王之道', '照人何处双瞳碧。\n欲去江城北。\n过江风顺莫迟留，快雁序、飞联翼。\n西湖花柳传消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7557, '折丹桂', '王之道', '风漪欲皱春江碧。\n予寄江城北。\n子今东去赴春官，挽不住、抟风翼。\n修程应过天池息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7558, '折丹桂', '王之道', '雪晴山色分遥碧。\n辉映江南北。\n子今东去步蟾宫，看少展、垂天翼。\n晚来江上西风息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7559, '八声甘州', '王之道', '叹关河在眼、孰雌雄，兴废古犹今。\n问中原何处，黄尘千里，远水平林。\n闻说讴谣思汉，人有望霓心。\n想垂髫戴白，泣涕盈襟。\n流水高山还会，意不烦挥按，如见虞琴。\n□逶迟周道，四牡骤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7560, '渔家傲', '王之道', '风揭珠帘寒乍透。\n青娥不住添香兽。\n火暖画檐鸣线溜。\n人醉後。\n锦堂丝竹烘残昼。\n势合湖山增地厚。\n孤高但觉修篁瘦。\n回策如萦今在手。\n骄马骤。\n吾家金埒新编就。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7561, '渔家傲', '王之道', '岩电晶荧君未老。\n看看门外锋车到。\n一点眉间黄色好。\n人尽道。\n从今次第登三少。\n左右青娥来巧笑。\n注唇涂额新妆了。\n斜插梅花仍斗妙。\n歌窈窕。\n醉来容我相嘲傲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7562, '渔家傲', '王之道', '岁月漂流人易老。\n东郊又报春来到。\n梅靥柳眉还斗好。\n君信道。\n衰颜得酒重年少。\n对酒邀宾同燕笑。\n莫教虚过芳菲了。\n咳唾珠玑夸笔妙。\n人窈窕。\n新声倾坐渔家傲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7563, '渔家傲', '王之道', '灯火熙熙来稚老。\n喜逢灯夕都齐到。\n花市绮楼随处好。\n人竟道。\n今年天气常年少。\n五马行游还坐笑。\n公堂帘卷东风了。\n箫鼓喧阗歌舞妙。\n人窈窕。\n也应引动南窗傲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7564, '渔家傲', '王之道', '系国安危还故老。\n鹤书赴陇行当到。\n多谢不遗敦雅好。\n应信道。\n年高德劭如公少。\n尊酒论文聊一笑。\n肯将苦语夸危了。\n落笔君房天下妙。\n环窈窕。\n清歌一曲渔家傲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7565, '渔家傲', '王之道', '海岱惟青遗一老。\n禁垣清切亲曾到。\n独直固劳非所好。\n谁信道。\n才如权相从来少。\n把酒自歌还自笑。\n醉中万事都齐了。\n绝唱清歌仍敏妙。\n声窈窕。\n行云初遏渔家傲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7566, '渔家傲', '王之道', '爵齿俱尊惟此老。\n诗词笔力谁能到。\n奇字古文仍笃好。\n须信道。\n如公宁复忧才少。\n剩费黄金应买笑。\n穷通得丧都忘了。\n坐对瑶觞看舞妙。\n携窈窕。\n南窗聊得渊明傲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7567, '渔家傲', '王之道', '老老恩波今及老。\n诏书前日新颁到。\n视膳慈宁先嗜好。\n隆孝道。\n慕逾五十前王少。\n想见天颜温色笑。\n东朝上寿称觞了。\n易俗功深神且妙。\n来窈窕。\n德齐任姒消骄傲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7568, '浪淘沙', '王之道', '高髻堕香鬟。\n遗恨眉山。\n老年花似梦中看。\n厌一枝晓露，珠泪阑干。\n卮酒发酡颜。\n休更留残。\n满城风雨麦秋寒。\n馀馥尚能消酒恶，谁敢包弹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7569, '忆东坡', '王之道', '雪霁柳舒容，日薄梅摇影。\n新岁换符来，天上初见颁桃梗。\n试问我酬君唱，何如博塞欢娱，百万呼卢胜。\n投珠报玉，须放骚人遣春兴。\n诗成谈笑，写出无穷景。\n不妨时作颠草，驰骋张芝圣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7570, '忆东坡', '王之道', '虚堂响应声，皎月形和影。\n春到也须还，长红多紫啼条梗。\n况有光风丽日，能消积雪繁霜，青女休言胜。\n扶摇借便，请看天池发鹏兴。\n人言强汉，治道夸文景。\n谁能尧舜其君，远继阿衡圣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7571, '六州歌头', '王之道', '燧勋业，何敢望西平。\n观当日，清大憝，震天声。\n绩其凝。\n追配汾阳郭，临淮李，扫妖孽，植颠仆，复疆宇，洗膻腥。\n堪叹中原久矣，长淮隔、胡骑纵横。\n问何时，风驱电扫，重见文明。\n宾雁宵鸣。\n梦初惊。\n念吾君复古，修攘两尽，早晚功成。\n岁云暮，冰腹壮，雪华零。\n怅神京。\n谁信汉家陵阙，呵护有神兵。\n罄寰海，重回首，镇关情。\n想见皇华咨度，望淮北、心曲摇旌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7572, '好事近', '王之道', '春色到梅梢，人在东风清嚏。\n曾见少微初降，蔼龙泉佳气。\n功名富贵属多才，如子已无几。\n造物恰同予意，放骅骝千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7573, '好事近', '王之道', '霞影入瑶觞，酒与馀霞同色。\n人共昌朝方永，过觥筹三百。\n一枝红皱石榴裙，帘卷篆烟碧。\n约我他年湖上，看九华终日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7574, '好事近', '王之道', '秋色到东篱，金散菊团香馥。\n预借浮觞高会，为作长年祝。\n蟹螯如臂酒如渑，橙橘半黄绿。\n唱我新词一，听尊前丝竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7575, '好事近', '王之道', '花影到酴，风过玉卮摇碧。\n坐上酒豪诗敌，尽骑鲸仙客。\n主人名姓在金瓯，归去定前席。\n要见碧桃千岁，看壶中春日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7576, '好事近', '王之道', '春色到酴，人在酴花底。\n花扑尊香透，远胜烧沈水。\n一杯聊复对东风，为祝千千岁。\n作楫和羹事了，归去骑箕尾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7577, '木兰花慢', '王之道', '对春光淡沲，烟冉冉、日迟迟。\n渐红入桃溪，青回柳陌，莺刷金衣。\n差池。\n竞求友去，恼佳人、幽恨上蛾眉。\n应念年时追逐，妆馀为带交枝。\n芳菲。\n谁共赏游嬉。\n何处马如飞。\n□不道新来，牵肠惹肚，暗减腰肢。\n须知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7578, '感皇恩', '王之道', '宿雾霁晨霜，江山明秀。\n照眼黄花乱晴昼。\n当年今日，正是悬弧时候。\n一杯聊献祝，同亲旧。\n莫问穷通，休论贫富。\n且趁良辰醉醇酎。\n扬珠捣玉，况值西成多收。\n饱餐歌至治，天垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7579, '石州慢', '王之道', '天迥楼高，日长院静，琴声幽咽。\n昵昵恩情，切切言语，似伤离别。\n子期何处，漫高山流水，又逐新声彻。\n仿佛江上移舟，听琵琶凄切。\n休说。\n春寒料峭，夜来花柳，弄风摇雪。\n大错因谁，算不翅六州铁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7580, '一翦梅', '王之道', '风揭珠帘夜气清。\n香扑尊，初见云英。\n蓝桥何处旧知名。\n今夕相逢，此恨消停。\n劝酒嫣然一笑倾。\n细意端相，无限娉婷。\n曲终犹带绕梁声。\n莫辞沈醉，为覆金觥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7581, '汉宫春', '王之道', '欢动江城，快风声震地，云势颓山。\n半年不雨，玉来溉冬乾。\n飘飘弱絮，杂檐花、飞上宾筵。\n疏林表，数行征雁，翱翔欲下清湾。\n何处梅梢点白，弄横斜疏影，竹外溪边。\n天寒日暮，含香脉脉无言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7582, '点绛唇', '王之道', '一撮檀心，春来还对东君吐。\n莫随春去。\n我欲花间住。\n燕子衔泥，似向吾人诉。\n烦相语。\n九龄风度。\n流落今何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7583, '点绛唇', '王之道', '珠霜蕤，晚来芬馥清香吐。\n流莺飞去。\n应上花梢住。\n一曲阳春，聊对东风诉。\n无多语。\n韶光暗度。\n恨到分携处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7584, '点绛唇', '王之道', '宿雨朝寒，芳时又过酴了。\n舞环歌绕。\n应恨金杯小。\n零乱霜蕤，点缀青青草。\n花间道。\n曾遭花恼。\n把酒呼晴昊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7585, '点绛唇', '王之道', '短棹西来，追随不及桃花宴。\n薰风庭院。\n明月裁纨扇。\n睡起娇慵，想见云鬟乱。\n双鱼远。\n欲凭春唤。\n一觇韦娘面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7586, '点绛唇', '王之道', '透幕穿帘，回风舞态能轻妙。\n不须相恼。\n江上春来了。\n一阕清歌，唱彻琼楼晓。\n春工巧。\n柳颦梅笑。\n点缀芳菲早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7587, '点绛唇', '王之道', '竹外梅花，檀心玉颊春初透。\n一池风皱。\n妙语天生就。\n有个人人，袅娜灵和柳。\n君知否。\n目成心授。\n何日同携手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7588, '点绛唇', '王之道', '春意催花，片云又作朝来雨。\n淡匀深注。\n红紫纷无数。\n社日人家，准拟行春去。\n痴儿女。\n倚门凝伫。\n借问东郊路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7589, '点绛唇', '王之道', '古屋衰杨，淡烟疏雨江南岸。\n几家村疃。\n酒旆还相唤。\n短棹扁舟，风横河频转。\n柔肠断。\n寒鸦噪晚。\n天共蒹葭远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7590, '虞美人', '王之道', '酪浆冷浸金盘粉。\n玉友浮新酝。\n如君真是酒中仙。\n一斗百篇、吟到小池莲。\n清风拂拂来纨素。\n独擅江南步。\n红裙无用妒芳姿。\n且把绿罗、争学画长眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7591, '虞美人', '王之道', '郑侯美政推仁厚。\n何独高淮右。\n分携令我预颦眉。\n只恐桐庐民望、怪来迟。\n一尊聊罄金蕉叶。\n更语半时霎。\n青娥罗列竞消凝。\n阁定眼边珠泪、做红冰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7592, '小重山', '王之道', '要识长生辈赤松。\n朱颜和绿发，正丰茸。\n当年今日堕仙宫。\n佳气郁，香霭菊花风。\n一醉拚千锺。\n小槽新酿美，玉泉浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7593, '小重山', '王之道', '花艳嫣然照坐红。\n池光高下见，木芙蓉。\n相从款款莫匆匆。\n新酿熟，浮瓮碧香浓。\n倚槛送飞鸿。\n登高时节近，菊披风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7594, '秦楼月・忆秦娥', '王之道', '云不卷。\n浇愁莫放金杯浅。\n金杯浅。\n新词丽句，要人裁翦。\n酒酣思致天同远。\n临风捉笔纶巾岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7595, '满江红', '王之道', '竹马来迎，留不住、寸心如结。\n□历湖、须坞相望，近同吴越。\n阙里风流今未减，此行报政看期月。\n已验康沂富国，千古曾无别。\n多谢润沾枯辙。\n令我神思清发。\n□新命欢浃，两邦情惬。\n明日西风帆卷席。\n高樯到处旌麾列。\n忽相思，吾当往，谁谓三墩隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7596, '望海潮', '王之道', '宝山烟霁，金湖波渺，珠帘高卷清霜。\n枫叶露痕，荻花风色，人言今日重阳。\n芳菊袅秋香。\n更榴房斗紫，柑实传黄。\n观阁凌空，杯盘照坐独醒狂。\n良辰乐事难忘。\n正少年游冶，人在任庄。\n铜钵探题，金钗当酒，一时绿鬓红妆。\n故国黯凄凉。\n漫情随水远，兴与云长。\n要是致君尧舜，千古继垂裳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7597, '如梦令', '王之道', '绰约一枝红怨。\n疏雨淡烟池馆。\n梅子欲黄时，日倚朱阑几遍。\n争看。\n争看。\n人在沈香亭畔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7598, '如梦令', '王之道', '叶底芳蕤如缀。\n坐对广庭忘味。\n娇呆最怜伊，乱糁舞馀风袂。\n贪喜。\n贪喜。\n不觉宝钗斜坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7599, '如梦令', '王之道', '一饷凝情无语。\n手拈梅花何处。\n倚竹不胜愁，暗想江头归路。\n东去。\n东去。\n短艇淡烟疏雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7600, '临江仙', '王之道', '红楼缥缈光风里，熙熙和气欢声。\n遏云馀韵最关情。\n春山闲淡淡，秋水醉盈盈。\n老去自怜心尚在，相逢殊慰劳生。\n纹楸聊复戏同枰。\n试烦歌一曲，须借酒三行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7601, '临江仙', '王之道', '鼓棹正逢江雪霁，是行应快吴吟。\n透云寒日半晴阴。\n烟岚凝翠重，霜树溅红深。\n案上文书闲展读，圣贤踪迹重寻。\n不堪华发故。\n三旌还有分，万事付无心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7602, '临江仙', '王之道', '怪得举头闻鹊喜，果然都骑相过。\n柳阴乘月倒金荷。\n疏星明耿耿，银汉静无波。\n总角追随今老矣，相逢无惜婆娑。\n夜阑馀兴到狂歌。\n长鲸方正渴，应不厌倾河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7603, '南歌子', '王之道', '朱实盈盈露，黄花细细风。\n龙山胜集古今同。\n断送一年秋色、酒杯中。\n鸭脚供柔白，鸡头荐嫩红。\n量吞云梦正能容。\n试问具区何处、浙江东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7604, '南歌子', '王之道', '老懒诗才退，春融醉眼昏。\n青山终日对柴门。\n柳外断桥流水、几家村。\n桃李添新意，池塘失旧痕。\n一尊聊复为君温。\n倾倒年来酬唱、细论文。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7605, '南歌子', '王之道', '扇里薰风细，壶中化日长。\n榴花高下照红妆。\n花外云飞馥郁、水沈香。\n新竹轻储粉，流莺巧弄簧。\n不知何处是华阳。\n应有千年白李、荐霞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7606, '南歌子', '王之道', '玉露澄天宇，金风净月华。\n满庭秋色木犀花。\n记得谪仙初下、五云车。\n才业追前辈，人门属当家。\n寿觞无惜醉流霞。\n闻说姓名潜护、有笼纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7607, '南歌子', '王之道', '角簟横龟枕，兰房挂艾人。\n一尊菖泛清醇。\n好在佳人如玉、映长春。\n冰彻杯盘莹，香和笑语薰。\n莲花衫子入时新。\n挂起南窗一榻、晚风清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7608, '南歌子', '王之道', '玉浮菖虎，金盘馈鱼。\n研丹聊作厌兵符。\n何必城头一女、当千夫。\n雨过山如洗，风来草似梳。\n佳人不惯手谈输。\n却道如今重赌、选官图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7609, '南歌子', '王之道', '露竹舒新绿，风荷递暗香。\n谁家池馆睡鸳鸯。\n还有玉人相对、坐传觞。\n角簟清冰滑，纱厨薄雾凉。\n晚来行雨过巫阳。\n强整罗衣临镜、学宫妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7610, '念奴娇', '王之道', '碧天无际，乍雨清烟霭，风开云月。\n人在南楼，剧谈胜咏，拥碧油旌节。\n银阙腾辉，冰轮驾彩，颢气资高洁。\n大星不见，更容萤火明灭。\n须烦翠杓琼杯，华笺象管，与我酬清绝。\n谁使琵琶声到耳，轻赋荻花枫叶。\n露脚斜飞，河阴低转，香篆环三杰。\n莫辞终日，舞腰重看回雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7611, '念奴娇', '王之道', '黄花照眼，对西风庭槛，为渠凝伫。\n准拟登高酬一醉，底事晚来微雨。\n蟋蟀声中，芭蕉叶上，怎得争如许。\n龙山何处，无言暗想烟树。\n须知天意随人，重阳晴未晚，不须频诉。\n幸有兵厨三万斛，足助赏心欢趣。\n千里江山，两行珠翠，端为骚人付。\n层楼飞观，应容老子追步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7612, '贺新郎', '王之道', '又是春残去，倚东风、寒云淡日，堕红飘絮。\n燕社鸿秋人不问，尽管吴声越鼓。\n但短发、星星无数。\n万事惟消彭泽醉，也何妨、袖卷长沙舞。\n身与世，只如许。\n阑干拍手闲情绪。\n便明朝、苍烟白鹭，北山南浦。\n笑指午桥桥畔路，帘幕深深院宇。\n尚趁得、柳烟花雾。\n我亦故山猿鹤怨，问何时、归棹双溪渚。\n歌一曲，恨千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7613, '菩萨蛮', '王之道', '藕丝衫剪轻红窄。\n衫轻不碍琼肤白。\n缦鬓小横波。\n花楼东是家。\n上湖闲荡桨。\n粉艳芙蓉榜。\n湖水亦多情。\n照妆天底清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7614, '薄媚', '董颖', '怒潮卷雪，魏岫布云，越襟吴带如斯。\n有客经游，月伴风随。\n值盛世。\n观此江山美。\n合放怀、何事却兴悲。\n不为回头，旧谷天涯。\n为想前君事。\n越王嫁祸献西施。\n吴即中深机。\n阖庐死。\n有遗誓。\n句践必诛夷。\n吴未干戈出境，仓卒越兵，投怒夫差。\n鼎沸鲸鲵。\n越遭劲敌，可怜无计脱重围。\n归路茫然，城郭丘墟，飘泊稽山里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7615, '薄媚', '董颖', '自笑平生，英气凌云，凛然万里宣威。\n那知此际。\n熊虎涂穷，来伴麋鹿卑栖。\n既甘臣妾，犹不许，何为计。\n争若都燔宝器。\n尽诛吾妻子。\n径将死战决雄雌。\n天意恐怜之。\n偶闻太宰，正擅权，贪赂市恩私。\n因将宝玩献诚，虽脱霜戈，石室囚系。\n忧嗟又经时。\n恨不如巢燕自由归。\n残月朦胧，寒雨萧萧，有血都成泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7616, '薄媚', '董颖', '种陈谋，谓吴兵正炽。\n越勇难施。\n破吴策，唯妖姬。\n有倾城妙丽。\n名称西子。\n岁方笄。\n算夫差惑此。\n须致颠危。\n范蠡微行，珠贝为香饵。\n苎萝不钓钓深闺。\n吞饵果殊姿。\n素肌纤弱，不胜罗绮。\n鸾镜畔、粉面淡匀，梨花一朵琼壶里。\n嫣然意态娇春，寸眸剪水。\n斜鬟松翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7617, '薄媚', '董颖', '湘裙，摇汉佩。\n步步香风起。\n敛双蛾，论时事。\n兰心巧会君意。\n殊珍异宝，犹自朝臣未与。\n妾何人，被此隆恩，虽令效死。\n奉严旨。\n隐约龙姿忻悦。\n重把甘言说。\n辞俊雅，质娉婷，天教汝、众美兼备。\n闻吴重色，凭汝和亲，应为靖边陲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7618, '薄媚', '董颖', '飞云驶。\n香车故国难回睇。\n芳心渐摇，迤逦吴都繁丽。\n忠臣子胥，预知道为邦崇。\n谏言先启。\n愿勿容其至。\n周亡褒姒。\n商倾妲己。\n吴王却嫌胥逆耳。\n才经眼、便深恩爱。\n东风暗绽娇蕊。\n彩鸾翻妒伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7619, '薄媚', '董颖', '华宴夕，灯摇醉。\n粉菡萏，笼蟾桂。\n扬翠袖，含风舞，轻妙处，惊鸿态。\n分明是。\n瑶台琼榭，阆苑蓬壶，景尽移此地。\n花绕仙步，莺随管吹。\n宝帐暖留春，百和馥郁融鸳被。\n银漏永，楚云浓，三竿日、犹褪霞衣。\n宿酲轻腕，嗅宫花，双带系。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7620, '薄媚', '董颖', '耳盈丝竹，眼摇珠翠。\n迷乐事。\n宫闱门。\n争知。\n渐国势凌夷。\n奸臣献佞，转恣奢淫，天谴岁屡饥。\n从此万姓离心解体。\n越遣使。\n阴窥虚实，蚤夜营边备。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7621, '薄媚', '董颖', '机有神，征鼙一鼓，万马襟喉地。\n庭喋血，诛留守，怜屈服，敛兵还，危如此。\n当除祸本，重结人心，争奈竟荒迷。\n战骨方埋，灵旗又指。\n势连败。\n柔荑携泣。\n不忍相抛弃。\n身在兮，心先死。\n宵奔兮，兵已前围。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7622, '薄媚', '董颖', '哀诚屡吐，甬东分赐。\n垂暮日，置荒隅，心知愧。\n宝锷红委。\n鸾存凤去，辜负恩怜，情不似虞姬。\n尚望论功，荣还故里。\n降令曰，吴亡赦汝，越与吴何异。\n吴正怨，越方疑。\n从公论、合去妖类。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7623, '薄媚', '董颖', '王公子。\n青春更才美。\n风流慕连理。\n耶溪一日，悠悠回首凝思。\n云鬟烟鬓，玉佩霞裾，依约露妍姿。\n送目惊喜。\n俄迂玉趾。\n同仙骑。\n洞府归去，帘栊窈窕戏鱼水。\n正一点犀通，遽别恨何已。\n媚魄千载，教人属意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7624, '卜算子', '董颖', '春浅借和风，吹绿庭皋树。\n依约屏间出紫云，入阁风流处。\n便做铁心肠，也为梅花语。\n欲去东君更挽留，巧栈烟霞路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7625, '满庭芳', '董颖', '红斗风桃，绿肥烟草，杨柳春暗重门。\n五陵佳兴，酿酝付芳尊。\n窈窕笙箫丛里，金猊篆、雾绕云纷。\n勾情也，歌眉低翠，依约鹧鸪村。\n人生须快意，十分春事，才破三分。\n况点检年时，胜客都存。\n更把馀欢卜夜，纵彻晓、蜡泪流痕。\n花阴昼，朱帘未卷，犹自醉昏昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7626, '满庭芳', '潘良贵', '夹水松篁，一天风露，觉来身在扁舟。\n桂花当午，云卷素光流。\n起傍篷窗危坐，飘然竟、欲到瀛洲。\n人世乐，那知此夜，空际列琼楼。\n休休。\n闲最好，十年归梦，两眼乡愁。\n谩赢得、萧萧华发盈头。\n往事不须追谏，从今去、拂袖何求。\n一尊酒，持杯顾影，起舞自相酬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7627, '柳梢青', '董德元', '满腹文章，满头霜雪，满面埃尘。\n直至如今，别无收拾，只有清贫。\n功名已是因循。\n最懊恨、张巡李巡。\n几个明年，几番好运，只是瞒人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7628, '青玉案', '冯时行', '年时江上垂杨路。\n信柱杖、穿云去。\n碧涧步虚声里度。\n疏林小寺，远山孤渚，独倚阑干处。\n别来无几春还暮。\n空记当时锦囊句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7629, '虞美人', '冯时行', '东君已了韶华媚。\n未快芳菲意。\n临居倾倒向荼シ。\n十万宝珠璎珞、带风垂。\n合欢翠玉新呈瑞。\n十日傍边醉。\n今年花好为谁开。\n欲寄一枝无处、觅阳台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7630, '虞美人', '冯时行', '芳菲不是浑无据。\n只是春收取。\n都将酝造晚风光。\n百尺瑶台、吹下半天香。\n多愁多病疏慵意。\n也被香扶起。\n微吟小酌送花飞。\n更拚小屏幽梦、到开时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7631, '虞美人', '冯时行', '去年同醉黄花下。\n采采香盈把。\n今年仍复对黄花。\n醉里不羞斑鬓、落乌纱。\n劝君莫似阳关柳。\n飞伴离亭酒。\n愿君只似月常圆。\n还使人人一月、一回看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7632, '渔家傲', '冯时行', '云复衡茅霜雪後。\n风吹江面青罗皱。\n镜里功名愁里瘦。\n闲袖手。\n去年长至今年又。\n梅逼玉肌春欲透。\n小槽新压冰澌溜。\n好把升沈分付酒。\n光阴骤。\n须臾又绿章台柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7633, '天仙子', '冯时行', '风幸多情开得好。\n忍却吹教零落了。\n弄花衣上有馀香，春已老。\n枝头少。\n况又酒醒晓。\n一片初飞情已悄。\n可更如今纷不扫。\n年随流水去无踪，恨不了。\n愁不了。\n楼外远山眉样小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7634, '点绛唇', '冯时行', '十日春风，吹开一岁闲桃李。\n南柯惊起。\n归踏春风尾。\n世事无凭，偶耳成忧喜。\n歌声里。\n落花流水。\n明日人千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7635, '玉楼春', '冯时行', '杏花微露春犹浅。\n春浅愁浓愁送远。\n山拖馀翠断行踪，细雨疏烟迷望眼。\n暮云浓处轻吹散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7636, '点绛唇', '冯时行', '江上新晴，闲撑小艇寻梅去。\n自知梅处。\n香满鱼家路。\n路尽疏篱，一树开如许。\n留人住。\n留人不住。\n黯淡黄昏雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7637, '点绛唇', '冯时行', '眉黛低颦，一声春满留苏帐。\n却从檀响。\n渐到梅花上。\n归卧孤舟，梅影舟前扬。\n劳心想。\n岸横千嶂。\n霜月铺寒浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7638, '梦兰堂', '冯时行', '小雨清尘淡烟晚。\n官柳花待暖。\n君愁入伤阙眼。\n芳草绿、断云归雁。\n酒重斟，须再劝。\n今夕近、明朝乍远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7639, '蓦山溪', '冯时行', '艰难时世。\n万事休夸会。\n官宦误人多，道是也、终须不是。\n功名事业，已是负初心，人老也，发白也，随分谋生计。\n如今晓得，更莫争闲气。\n高下与人和，且觅个、置锥之地。\n江村僻处，作个老渔樵，一壶酒，一声歌，一觉醺醺睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7640, '醉落魄・一斛珠', '冯时行', '点酥点蜡。\n凭君尽做风流骨。\n汉家旧样宫妆额。\n流落人间，真个没人识。\n佳人误拨龙香觅。\n一枝初向烟林得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7641, '蝶恋花', '朱松', '清晓方塘开一镜。\n落絮飞花，肯向春风定。\n点破翠奁人未醒。\n馀寒犹倚芭蕉劲。\n拟托行云医酒病。\n帘卷闲愁，空占红香迳。\n青鸟呼君君莫听。\n日边幽梦从来正。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7642, '点绛唇', '朱翌', '流水泠泠，断桥横路梅枝亚。\n雪花飞下。\n浑似江南画。\n白璧青钱，欲买春无价。\n归来也。\n西风平野。\n一点香随马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7643, '朝中措', '朱翌', '玉台金盏对炎光。\n全似去年香。\n有意庄严端午，不应忘却重阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7644, '生查子', '朱翌', '宫纱蜂趁梅，宝扇鸾开翅。\n数折聚清风，一捻生秋意。\n摇摇云母轻，袅袅琼枝细。\n莫解玉连环，怕作飞花坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7645, '阮郎归', '陈康伯', '闲来溪上有云飞。\n溪光接翠微。\n江南三月落花时。\n春波去棹迟。\n寻竹路，破林扉。\n苍台旧钓矶。\n欲归回首未成归。\n黄尘满素衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7646, '浪淘沙', '陈康伯', '台上凭阑干。\n犹怯春寒。\n被谁偷了最高山。\n将谓六丁移取去，不在人间。\n却是晓寒闲。\n特地遮栏。\n与天一样自漫漫。\n喜得东风收卷尽，依就追还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7647, '踏莎行', '欧阳澈', '雁字书空，橘星垂槛。\n江天水墨秋光晚。\n香丝袅袅祝尧年，公庭锡宴挥金碗。\n醉索蛮笺，狂吟象管。\n珠玑灿灿惊人眼。\n遏云更倩雪儿歌，从教拍碎红牙板。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7648, '蝶恋花', '欧阳澈', '红叶飘风秋欲暮。\n送目层楼，帘卷西山雨。\n解榻聚宾挥玉尘。\n风流只欠王夷甫。\n质剑为公沽绿醑。\n涤濯吟魂，拟摘黄花句。\n醉眼瞢腾携手处。\n谢池风月谁分付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7649, '玉楼春', '欧阳澈', '个人风韵天然俏。\n入鬓秋波常似笑。\n一弯月样黛眉低，四寸鞋儿莲步小。\n绝缨尝宴琼楼杪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7650, '玉楼春', '欧阳澈', '年时醉倚温温玉。\n妒月精神疑可掬。\n香丝篆袅一帘秋，潋滟十分浮蚁绿。\n兴来笑把朱弦促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7651, '踏莎行', '欧阳澈', '罗幕风轻，水沈烟细。\n杯行笑拥东山妓。\n酬歌何惜锦缠头，清音暗绕粱尘起。\n银甲弹筝，碧桃荐味。\n举觞飞白拚沈醉。\n花窗弄月晚归来，门迎蜡炬笙箫沸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7652, '小重山', '欧阳澈', '红叶伤心月午楼。\n袭人风细细，远烟浮。\n瞢腾醉眼不禁秋。\n追旧事，拍塞一怀秋。\n心绪两悠悠。\n东阳消瘦损，甚风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7653, '虞美人', '欧阳澈', '玉楼缥缈孤烟际。\n徙倚愁如醉。\n雁来人远暗消魂。\n帘卷一钩新月、怯黄昏。\n那人音信全无个。\n幽恨谁凭破。\n扑花蝴蝶若知人。\n为我一场清梦、去相亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7654, '朝中措', '曾', '幽芳独秀在山林。\n不怕晓寒侵。\n应笑钱塘苏小，语娇终带吴音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7655, '朝中措', '曾', '绿华居处渺云深。\n不受一尘侵。\n细看宜州新句，平生才是知音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7656, '念奴娇', '曾', '绣衣直指，问凌风一笑，翩然何许。\n诏出层霄持汉节，千里秋风淮浦。\n鉴远江山，竹西歌吹，曾被腥膻污。\n须君椽笔，为渠一洗尘土。\n休厌共倒金荷，翠眉重为唱，渭城朝雨。\n看即扬鞭归骑稳，还指郁葱深处。\n宝带兼金，华鞯新绣，直上云霄去。\n回头莫忘，玉霄今夜风露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7657, '诉衷情', '曾', '鄞江云气近蓬莱。\n花柳满城隈。\n风流谢守相遇，应覆故人杯。\n烟浪暖，锦帆回。\n莫徘徊。\n玉霄亭下，芍药荼シ，都望归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7658, '浣溪沙', '曾', '无数春山展画屏。\n无穷烟柳照溪明。\n花枝缺处小舟横。\n紫禁正须红药句，清江莫与白鸥盟。\n主人元自是仙卿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7659, '点绛唇', '曾', '九月传杯，要携佳客栖霞去。\n满城风雨。\n记得潘郎句。\n紫菊红萸，何意留侬住。\n愁如许。\n暮烟一缕。\n正在归时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7660, '菩萨蛮', '张表臣', '垂虹亭下扁舟住。\n松江烟雨长桥暮。\n白听吴歌。\n佳人泪脸波。\n劝倾金凿落。\n莫作思家恶。\n绿鸭与鲈鱼。\n如何可寄书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7661, '蓦山溪', '张表臣', '楼横北固，尽日厌厌雨。\n乃数声歌，但渺漠、江山烟树。\n寂寥风物，三五过元宵，寻柳眼，觅花英，春色知何处。\n落梅呜咽，吹彻江城暮。\n脉脉数飞鸿，杳归期、东风凝伫。\n长安不见，烽起夕阳间，魂欲断、酒初醒，独下危梯去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7662, '南乡子', '吴亿', '江上雪初消。\n暖日晴烟弄柳条。\n认得裙腰芳草路，魂消。\n曾折梅花过断桥。\n潘鬓为谁凋。\n长恨金闺闭阿娇。\n遥想晚妆呵手罢，夭饶。\n更傍珠唇暖玉箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7663, '烛影摇红', '吴亿', '楼雪初消，丽谯吹罢单于晚。\n使君千炬起班春，歌吹香风暖。\n十里珠帘尽卷。\n正人在、蓬壶阆苑。\n卖薪买酒，立马传觞，升平重见。\n谁识鳌头，去年曾侍传柑宴。\n至今衣袖带天香，行处氤氲满。\n已是春宵苦短。\n且莫遣、欢游意懒。\n细听归路，璧月光中，玉箫声远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7664, '临江仙', '刘袤', '樱桃结子春归尽，蝶翻金粉双飞。\n子规啼月小楼西。\n玉钩罗幕，惆怅卷金泥。\n门巷寂寥人去後，望残烟草低迷。\n何时重听玉骢嘶。\n扑帘飞絮，依约梦回时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7665, '清平乐', '李鼐', '乱云将雨。\n飞过鸳鸯浦。\n人在小楼空翠处。\n分得一襟离绪。\n片帆隐隐归舟。\n天边雪卷云浮。\n今夜梦魂何处，青山不隔人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7666, '水龙吟', '杨无咎', '当年谁种官梅，自开自落清无比。\n一朝惊见，危亭岑立，繁华丛里。\n知是贤侯，有难兄弟，素书时寄。\n纵舞携如意，吟搔短发，无从诉、心中喜。\n却对斜枝冷蕊。\n似於人、不胜风味。\n冰姿斜映，朱唇浅破，欣然会意。\n青子垂垂，翠阴密密，尤堪频憩。\n待促归禁近，邦人指点，作甘棠比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7667, '水龙吟', '杨无咎', '晓来雨歇风生，素商乍入鸳鸯浦。\n红蕖翠盖，不知西帝，神游何处。\n罗绮丛中，是谁相慕，凭肩私语。\n似汉皋佩解，桃源人去，成思忆、空凝伫。\n肯为风流令尹，把芳心、双双分付。\n碧纱对引，朱衣前导，应须此去。\n好揖清香，盛邀嘉客，杯行无数。\n唤瑶姬并立，如花并蒂，唱黄金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7668, '水龙吟', '杨无咎', '西湖天下应如是。\n谁唤作、真西子。\n云凝山秀，日增波媚，宜晴宜雨。\n况是深秋，更当遥夜，月华如水。\n记词人解道，丹青妙手，应难写、真奇语。\n往事输他范蠡。\n泛扁舟、仍携佳丽。\n毫端幻出，淡妆浓抹，可人风味。\n和靖幽居，老坡遗迹，也应堪记。\n更凭君画我，追随二老，游千家寺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7669, '水龙吟', '杨无咎', '小轩潇洒清宵午，风正紧、门深闭。\n藜床危坐，竹窗频听，春虫扑纸。\n灯烬垂红，篆烟消碧，衣轻如水。\n料飞花未止，堆檐已满，时催折、琅尾。\n骨冷魂清无寐。\n这身在、广寒宫里。\n暗怀千古，浑疑一夜，冰生肠胃。\n岁事峥嵘，故园睽阻，归期犹未。\n向寒乡、不念丰年，只忆青天万里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7670, '水龙吟', '杨无咎', '夜来六出飞花，又催寂寞袁门闭。\n幽斋无寐，寒欺衾布，明吞窗纸。\n起步闲庭，月华交映，长空如水。\n便乘风欲去，凌云直上，青冥际、骑箕尾。\n谁信团成和气。\n在贤侯、笑谈声里。\n咸惊句琢琼瑰，端是锦缠肠胃。\n宿麦连云，遗蝗入地，田家知未。\n更明年看取，东阡北陌，黄云万里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7671, '水龙吟', '杨无咎', '智琼娇额涂黄，为谁种作秋风蕊。\n寒香半露，绿帏深护，犹闻十里。\n山麝生脐，水沈削蜡，一时羞避。\n向钱塘江上，中秋月下，有人暗寻遗子。\n不奈书生习气。\n对群花、领略风味。\n骚人已去，欲纫幽佩，重为湘酹。\n天赋风流，友梅兄蕙，舆桃奴李。\n向明窗几，纤枝未老，眼明如水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7672, '念奴娇', '杨无咎', '单于吹罢，望西山乞得，斜阳收脚。\n素魄旋升，听桂子、风里时时飘落。\n莹彻杯盘，冷侵毛发，浑不胜衣著。\n天公有意，为人掀尽云幕。\n童稚犹也多情，广庭扫净草，不容纤恶。\n步绕周遭，疑便是、踏雪当年东郭。\n慢引歌声，响穿云际，直使娥觉。\n一尊重酹，为言千载同约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7673, '扫花游・扫地游', '杨无咎', '乳莺啭午。\n□好梦初醒，小轩清楚。\n水沈细缕。\n趁游丝落絮，缓随风舞。\n起春心，又是愁云怨雨。\n玉人去。\n遍徙倚旧时，曾并肩处。\n相望知几许。\n纵远隔云山，不遮愁路。\n捧杯荐俎。\n记低歌丽曲，共论心素。\n薄恨斜阳，不道离情最苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7674, '隔浦莲・隔浦莲近拍', '杨无咎', '墙头低荫翠幄。\n格磔鸣乌鹊。\n好梦惊回处，馀酲推枕犹觉。\n新晴人意乐。\n云容薄。\n丽日明池阁。\n卷帘幕。\n披衣散策，闲庭吟绕红药。\n残英几许，尚可一供春酌。\n天气今宵怕又恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7675, '品令', '杨无咎', '水寒江静。\n浸一抹、青山影。\n楼外指点渔村近。\n笛声谁喷。\n惊起宾鸿阵。\n往事总归眉际恨。\n这相思、□□谁问。\n泪痕空把罗襟印。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7676, '阳春', '杨无咎', '蕙风轻，莺语巧，应喜乍离幽谷。\n飞过北窗前，递晴晓，丽日明透翠帏。\n篆台芬馥。\n初睡起、横斜簪玉。\n因甚自觉腰肢瘦，新来又宽裙幅。\n对清镜、无心梳裹，谁问著、馀酲带宿。\n寻思前欢往事，似惊回、好梦难续。\n花亭遍倚槛曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7677, '白雪', '杨无咎', '檐收雨脚，云乍敛、依然又满长空。\n纹蜡焰低，熏炉烬冷，寒衾拥尽重重。\n隔帘栊。\n听撩乱、扑漉春虫。\n晓来见、玉楼珠殿，恍若在蟾宫。\n长爱越水泛舟，蓝关立马，画图中。\n怅望几多诗□，无句可形容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7678, '垂丝钓', '杨无咎', '燕将旧侣。\n呢喃终日相语。\n似惜别离情，知几许。\n谁与度。\n为向人代诉。\n空朝暮。\n谩千言百句。\n怎生会得，争如作个青羽。\n又闻院宇。\n不在当时住。\n飞去无寻处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7679, '垂丝钓', '杨无咎', '玉纤半露。\n香檀低应鼍鼓。\n逸调响穿空，云不度。\n情几许。\n看两眉碧聚。\n为谁诉。\n听敲冰戛玉。\n恨云怨雨。\n声声总在愁处。\n放杯未举。\n倾坐惊相顾。\n应也肠千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7680, '解蹀躞', '杨无咎', '金谷楼中人在，两点眉颦绿。\n叫云穿月，横吹楚山竹。\n怨断忧忆因谁，坐中有客，犹记住、平阳宿。\n泪盈目。\n百转千声相续。\n停杯听难足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7681, '醉落魄・一斛珠', '杨无咎', '双心小萼。\n瑞炉慢炷轻烟初著。\n清香已透红绡幄。\n底事多情，玉笋更轻掠。\n鬓云侧畔□眉角。\n妆成曾印铅华薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7682, '青玉案', '杨无咎', '芝兰桃李环围著。\n拥和气、浮帘幕。\n寿交飞争满酌。\n一声珠，数敲牙板，应有梁尘落。\n腰金虽重何曾觉。\n更看悬鱼上麟阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7683, '青玉案', '杨无咎', '南州独数多名士。\n谁富贵、归桑梓。\n昼锦如公难比似。\n傍湖开径，雨帘云栋，平地居仙子。\n行须勋业超青史。\n再侍宸帏任非次。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7684, '青玉案', '杨无咎', '奇葩珍树丛丛绕。\n望仙隐、蓬莱小。\n前枕湖光秋色晓。\n荷花今岁，也如人意，不逐西风老。\n霞觞献寿频频倒。\n瑞蔼浮空凝不扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7685, '青玉案', '杨无咎', '五云楼阁蓬瀛路。\n空相望、无由去。\n弱水渺茫谁可渡。\n君家徐福，荡舟寻访，却是曾知处。\n群仙应问来何暮。\n说与荣归锦封句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7686, '望江南・忆江南', '杨无咎', '锺陵好，佳节庆元正。\n瑞色潜将春共到，台星遥映月初升。\n贤帅为时生。\n人意乐，天宇亦清明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7687, '望江南・忆江南', '杨无咎', '锺陵好，和气满江城。\n忆昨旌麾初至止，到今政令只宽平。\n仍岁兆丰登。\n称庆旦，遐迩一般情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7688, '望江南・忆江南', '杨无咎', '锺陵好，襦裤听欢声。\n薰入管弦增亮响，唤教罗绮亦光荣。\n引满劝金觥。\n谁信是，元自悟长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7689, '望江南・忆江南', '杨无咎', '锺陵好，家世仰仙卿。\n衣带不须藏贝叶，集贤何用化金瓶。\n且欲佐中兴。\n期早晚，丹诏天下庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7690, '选冠子', '杨无咎', '海上楼台，壶中日月，乍觉挈来平地。\n熙熙鸡犬，簇簇僮奴，亦自有登天志。\n知是仙宫，出应亨期，因识前修风味。\n看纵横才美，雍容谈笑，一团和气。\n锺秀处、雪洁霜□，梅清竹瘦，占尽小春佳致。\n笙歌韵溢，锦绣香浓，饮少未妨欢醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7691, '满庭芳', '杨无咎', '节物争妍，江山改观，已闻春到萧滩。\n瑞烟和气，葱茜接螺川。\n元是使君诞日，半千运、来踵三贤。\n争相竞，谁知胜地，拜相有前山。\n芳筵。\n开富寿，罗绮间，簪组骈阗。\n正雪梅迎腊，霜月将圆。\n看取霜髯秀颊，人人道、平世神仙。\n调元手，阴功在继，八百定长年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7692, '二郎神', '杨无咎', '炎光欲谢，更几日、薰风吹雨。\n共说是天公，亦嘉神贶，特作澄清海宇。\n灌口擒龙，离堆平水，休问功超前古。\n当中兴、护我边陲，重使四方安堵。\n新府。\n祠庭占得，山川佳处。\n看晓汲双泉，晚除百病，奔走千门万户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7693, '水调歌头', '杨无咎', '闰馀有何好，一岁两中秋。\n霁云卷尽，依旧银汉截天流。\n长记芗林堂上，静对小山丛桂，尊俎许从游。\n遥想此时兴，不减上南楼。\n引玉觞，看金饼，水云头。\n醉听哦响，宁羡王粲赋荆州。\n此夕翻成愁绝，未斫广寒丹桂，犹衣敝貂裘。\n万事付谈笑，斗酒且宽忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7694, '水调歌头', '杨无咎', '芗林有何好，花蕊不惊秋。\n千章云木，长见密叶翠光流。\n中有三朝勋旧，早岁辞荣轩冕，归伴赤松游。\n不羡鸳鸯侣，锺听景阳楼。\n问向来。\n麟阁上，凤池头。\n有谁能继，向来解印似苏州。\n自是英姿绝俗，非我与时违异，何用衣羊裘。\n况得长生趣，千岁有怀忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7695, '水调歌头', '杨无咎', '寥亮度弦管，笑语集簪缨。\n又逢华旦争庆，豪杰为时生。\n犹对中秋月影，渐放重阳菊蕊，万宝正西成。\n爽气知多少，天赋满襟灵。\n擅词华，追鲍谢，踵斯冰。\n入趋禁近，出镇藩辅早辞荣。\n休恋平湖佳致，好为苍生重起，归去侍宸庭。\n一德及元□，千载致升平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7696, '水调歌头', '杨无咎', '帝里记当日，赐第富相联。\n惟君家最称著，桐木老参天。\n三相勋庸才业，一代风流人物，继世赖君贤。\n自合跻清要，小屈佐平川。\n下车初，逢庆旦，听欢传。\n冰清玉润，仁爱终始被江。\n满泛黄花称寿，细看红萸枝健，和气霭芳筵。\n隔日醉重九，千岁似今年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7697, '传言玉女', '杨无咎', '小院春长，整整绣帘低轴。\n异葩幽艳，满千瓶百斛。\n珠钿翠佩，尘袜锦笼环簇。\n日烘风和，奈何芬馥。\n凤髓龙津，觉从前、气味俗。\n夜阑人醉，引春葱兢□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7698, '传言玉女', '杨无咎', '料峭寒生，知是那番花信。\n算来都为，惜花人做恨。\n看犹未足，早觉枝头吹尽。\n曲栏幽榭，乱红成阵。\n酾酒花前，试停杯、与细问。\n褪香销粉，问东君怎忍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7699, '於中好', '杨无咎', '墙头艳杏花初试。\n绕珍丛、细红蕊。\n欲知占尽春明媚。\n诮无意、看桃李。\n持杯准拟花前醉。\n早一叶、两叶飞坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7700, '於中好', '杨无咎', '溅溅不住溪流素。\n忆曾记、碧桃红露。\n别来寂寞朝朝暮。\n恨遮乱、当时路。\n仙家岂解空相误。\n嗟尘世、自难知处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7701, '於中好', '杨无咎', '梅花摘索穿疏竹。\n荫纹禽、喜欢相逐。\n坐中已自清堪掬。\n更潇洒、人如玉。\n新声爱度周郎曲。\n捧霞杯、再三相嘱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7702, '瑞云浓', '杨无咎', '睽离谩久，年华谁信曾换。\n依旧当时似花面。\n幽欢小会，记永夜、杯行无算。\n醉里屡忘归，任虚檐月转。\n能变新声，随语意、悲欢感怨。\n可更馀音寄羌管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7703, '一丛花', '杨无咎', '娟娟□月可庭方。\n窗户进新凉。\n美人为我歌新曲，翻身调、韵超出宫商。\n犀箸细敲，花瓷清响，馀韵绕红梁。\n风流难似我清狂。\n随处占烟光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7704, '好事近', '杨无咎', '花里爱姚黄，琼苑旧曾相识。\n不道风流种在，又一枝倾国。\n拟图遮断倚阑人，休教妄攀摘。\n其奈老来情减，负十分春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7705, '人娇', '杨无咎', '恼乱东君，满目千花百卉。\n偏怜处、爱他李。\n莹然风骨，占十分春意。\n休漫说、唐昌观中玉蕊。\n妒雪凝霜，凌红掩翠。\n看不足、可人情味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7706, '人娇', '杨无咎', '露下天高，最是中秋景胜。\n喜银蟾、十分增晕。\n嫦娥飞下，见雾鬟风鬓。\n念八景园中，画谁能尽。\n慢奏云韶，美斟仙酝。\n清不寐、桂香成阵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7707, '蝶恋花', '杨无咎', '端正纤柔如玉削。\n窄袜宫鞋，暖衬吴绫薄。\n掌上细看才半搦。\n巧偷强夺尝春酌。\n稳称身材轻绰约。\n微步盈盈，未怕香尘觉。\n试问更谁如样脚。\n除非借与嫦娥著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7708, '蝶恋花', '杨无咎', '春睡腾腾长过午。\n楚梦云收，雨歇香风度。\n起傍妆台低笑语。\n画檐双鹊尤偷顾。\n笑指遥山微敛处。\n问我清癯，莫是因诗苦。\n不道别来愁几许。\n相逢更忍从头诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7709, '蝶恋花', '杨无咎', '昔在仁皇当极治。\n南极星宫，曾降为嘉瑞。\n犹有画图传好事。\n身材只恐君今是。\n对酒不妨同看戏。\n他日功名，晏子堪为比。\n更愿远孙逢九世。\n安排君在鸡窠里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7710, '蝶恋花', '杨无咎', '万里无云秋色静。\n上下天光，共水交辉映。\n坐对冰轮心目莹。\n此身不在尘寰境。\n扑漉文禽飞不定。\n勾引离人，分外添归兴。\n来往悠悠重记省。\n夜阑人散花移影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7711, '锯解令', '杨无咎', '送人归後酒醒时，睡不稳、衾翻翠缕。\n应将别泪洒西风，尽化作、断肠夜雨。\n卸帆浦溆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7712, '忆秦娥', '杨无咎', '情难足。\n不堪黄帽催行速。\n催行速。\n扁舟一叶，别愁千斛。\n津亭送客惊相嘱。\n举杯欲唱眉先蹙。\n眉先蹙。\n背人掩面，不能终曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7713, '倾杯・倾杯乐', '杨无咎', '瑞日凝晖，东风解冻，峭寒犹浅。\n正池馆、梅英粉淡，柳梢金软，兰芽香暖。\n滕城谁种芙蕖满。\n浸银蟾影，一夜万花开遍。\n翠楼朱户，是处重帘竞卷。\n罗绮簇、欢声一片。\n看五马行春旌旆远。\n拥襦裤、千里歌谣，都入太平弦管。\n且莫厌、瑶觞屡劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7714, '望海潮', '杨无咎', '菊暗荷枯，橙黄桔绿，嘉时记得今朝。\n欢蔼十州，香飘万井，春容小试梅梢。\n星昂耀层霄。\n庆诞生元德，出佐明朝。\n雅奏声中，彩旗光里仰英标。\n遐年已卜民谣。\n最招徕瘵俗，洗尽奸骄。\n东府政声，北门治绩，流芳况自迢遥。\n莫惜拚今宵。\n听缓敲牙板，引满金蕉。\n看即泥封峻召，无计驻华镳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7715, '齐天乐', '杨无咎', '後堂芳树阴阴见。\n疏蝉又还催晚。\n燕守朱门，萤粘翠幕，纹蜡啼红慵剪。\n纱帏半卷。\n记云瑶山，粉融珍簟。\n睡起援毫，戏题新句谩盈卷。\n睽离鳞雁顿阻，似闻频念我，愁绪无限。\n瑞鸭香销，铜壶漏永，谁惜无眠展转。\n蓬山恨远。\n想月好风清，酒登琴荐。\n一曲高歌，为谁眉黛敛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7716, '齐天乐', '杨无咎', '疏疏数点黄梅雨。\n殊方又逢重五。\n角黍包金，草蒲泛玉，风物依然荆楚。\n衫裁艾虎。\n更钗凫朱符，臂缠红缕。\n扑粉香绵，唤风绫扇小窗午。\n沈湘人去已远，劝君休对酒，感时怀古。\n慢啭莺喉，轻敲象板，胜读离骚章句。\n荷香暗度。\n渐引入陶陶，醉乡深处。\n卧听江头，画船喧叠鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7717, '蓦山溪', '杨无咎', '去年今日，踪迹留金水。\n乘兴挈朋侪，游赏遍、南峰佳致。\n崇仙岸左，争看竞龙舟，人汹汹，鼓冬冬，不觉金鸟坠。\n而今寂寞，独处山林里。\n欲去恨无因，奈阻隔、川途百里。\n香蒲角黍，对暑悄无言，梅雨细，麦风轻，怅望宽垂泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7718, '蓦山溪', '杨无咎', '天姿雅素，不管群芳妒。\n微笑倚春风，似窥宋、墙头凝伫。\n一春花草，陡觉更无香，悬绣帐，结罗巾，谁更熏沈炷。\n可堪开晚，未放韶光去。\n生怕糁庭阶，直不忍、苍苔散步。\n会须开宴，满摘蘸瑶觞，何况有，绮窗人，娇鬓相宜处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7719, '蓦山溪', '杨无咎', '玉英檀蕊，细意凭君看。\n青帝忒多情，费几许、春风暗剪。\n晓来枕，不觉嫩香飘，披宿雾，启幽窗，不道开初遍。\n无穷风味，乍可蜂莺占。\n莫遣俗人知，怕毒眼、急须遮断。\n倚墙压架，娇困卧枝头，心绪里，阿谁知，似个人撩乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7720, '蓦山溪', '杨无咎', '蟾宫仙种，几日飘鸳。\n密叶绣围栾，似翦出、佳人翠袖。\n叶间金粟，蔌蔌糁枝头，黄菊嫩，碧莲披，独对秋容瘦。\n浓香馥郁，庭户宜熏透。\n十里远随风，又何必、凭阑细嗅。\n明犀一点，暗里为谁通，秋夜永，月华寒，无寐听残漏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7721, '醉蓬莱', '杨无咎', '见恩荣故里。\n□著贤关，特然超诣。\n满腹诗书，洗膏粱馀味。\n羞挽乌号，换将蓝绶，向广庭亲试。\n磊落胸襟，雍容人物，于今谁比。\n争许才猷，合跻严禁，行看横飞，少将清议。\n喜对生朝，且陶陶欢醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7722, '醉蓬莱', '杨无咎', '正才过七夕，又近中元，素秋时候。\n月皎风高，渐凉生襟袖。\n灏气澄凝，是谁清白，应此□□秀。\n味洗膏粱，才侔沈谢，三朝勋旧。\n好是新来，日临连帅，化格黔黎，政归仁厚。\n早祷群祠，有雨随车骤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7723, '醉蓬莱', '杨无咎', '见禾山凝秀，禾水澄清，地灵境胜。\n天与珍奇，产凌霄峰顶。\n嫩叶森枪，轻尘飞雪，冠中州双井。\n绝品家藏，武陵有客，清奇相称。\n坐列群贤，手呈三味，云逐瓯圆，乳随汤迸。\n珍重殷勤，念文园多病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7724, '朝中措', '杨无咎', '杯盘狼藉烛参差。\n欲去未容辞。\n春雪看飞金碾，香云旋涌花瓷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7725, '朝中措', '杨无咎', '打窗急听□然汤。\n沈水剩熏香。\n冷暖旋投冰碗，荤膻一洗诗肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7726, '点绛唇', '杨无咎', '宝勒嘶归，未教佳客轻辞去。\n姊夫屡鼠。\n笑听殊方语。\n清入回肠，端助诗情苦。\n春风路。\n梦寻何处。\n门掩桃花雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7727, '点绛唇', '杨无咎', '瓦枕藤床，道人劝饮鸡苏水。\n清虽无比。\n何似今宵意。\n红袖传持，别是般情味。\n歌筵起。\n绛纱影里。\n应有吟鞭坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7728, '点绛唇', '杨无咎', '借问嫦娥，当初谁种婆娑树。\n空中呈露。\n不坠凡花数。\n却爱芗林，便似蟾宫住。\n清如许。\n醉看歌舞。\n同在高寒处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7729, '点绛唇', '杨无咎', '散策芗林，几回来绕团团树。\n月明风露。\n平地神仙数。\n准拟归来，移近东家住。\n应相许。\n为君起舞。\n直到高寒处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7730, '卜算子', '杨无咎', '婆娑月里枝，隐约空中露。\n拟访嫦娥高处看，一夜心生羽。\n仙种落人间，群艳难俦侣。\n恼乱骚人有底香，欲赋无奇语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7731, '卜算子', '杨无咎', '平分月殿香，碎点金盘露。\n占断秋光独自芳，端称觞飞羽。\n谢了却重开，若个花同侣。\n谁识灵心一点通，手拈空无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7732, '卜算子', '杨无咎', '昨夜月初圆，今日春才半。\n自是元君并旦生，岂在称遐算。\n花诰看加封，玉休辞满。\n绮席来年谁与同，笑揖麻姑伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7733, '滴滴金', '杨无咎', '当初本合蟾宫里。\n谩容易、到尘世。\n表里冰清谁与比。\n占无双两地。\n诜诜已是多孙子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7734, '滴滴金', '杨无咎', '相逢未尽论心素。\n早容易、背人去。\n忆得歌翻断肠句。\n更惺惺言语。\n萋萋芳草迷南浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7735, '上林春令・一落索', '杨无咎', '李夭桃堆绣。\n正暖日、如熏芳袖。\n流莺恰恰娇啼。\n似为劝、百觞进酒。\n少年未用称遐寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7736, '瑞鹤仙', '杨无咎', '看灯花尽落。\n更欲换，门外初听剥啄。\n一尊赴谁约。\n甚不知早暮，忒贪欢乐。\n嗔人调谑。\n饮芳容、索强倒恶。\n渐娇慵不语，迷奚带笑，柳柔花弱。\n难藐。\n扶归鸳帐，不褪罗裳，要人求托。\n偷偷弄搦。\n红玉软，暖香薄。\n待酒醒枕臂，同歌新唱，怕晓愁闻画角。\n问昨宵、可归迟，更休道著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7737, '瑞鹤仙', '杨无咎', '听梅花再弄。\n残酒醒，无寐寒衾愁拥。\n凄凉谁与共。\n谩赢得，别恨离怀千种。\n拂墙树动。\n更晓来、云阴雨重。\n对伤心好景，回首旧游，恍然如梦。\n欢纵。\n西湖曾是，画舫争驰，绣鞍双控。\n归来夜中。\n要银烛，卸金凤。\n到而今，谁拈花枝同载，谁酌酒杯笑捧。\n但逢花对酒，空祗自歌自送。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7738, '瑞鹤仙', '杨无咎', '见兰枯菊悴。\n□寂寞，天与春风来至。\n梅梢弄晴蕊。\n似於人，装点十分和气。\n吴头楚尾。\n听民谣、欢声鼎沸。\n总扶携□手，嬉游鼓腹，顿忘愁悴。\n谁比。\n承流宣化，问俗观风，一时双美。\n笙歌宴启。\n交酬献，尽沈醉。\n□□□，行看宸庭同拜，归向天街并辔。\n对西湖把酒，应须共谈旧治。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7739, '瑞鹤仙', '杨无咎', '数文章翰墨。\n前辈远，稍□风流岑寂。\n公才万夫敌。\n嗣家声，不坠江西人物。\n凝脂点漆。\n向鸳行、神峰秀出。\n况襟怀倜傥，词华洒落，未容俦匹。\n均逸。\n妙龄识退，故国怀归，问安亲戚。\n屏风坐隔。\n看除召，在晨夕。\n对生朝，且趁清明时节，痛饮无妨堕帻。\n著莱衣戏舞，千春永如是日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7740, '雨中花・夜行船', '杨无咎', '海宇澄明，天气宴温，人情物态昭苏。\n喜分付揽辔，来与春俱。\n潇洒兰亭醉墨，丁宁黄石传书。\n到如今几载，不坠风流，世有名儒。\n山川瑞色，樵牧欢声，尽随弦管虚徐。\n判醉笑、频挥玉麈，共□金壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7741, '雨中花・夜行船', '杨无咎', '漠漠云轻，涓涓露重，西风特地飕飕。\n觉良宵初永，袢暑微收。\n乘鹤缑山，浮槎银汉，尚想风流。\n笑人间儿戏，瓜果堆盘，缯彩为楼。\n广庭净扫，露坐披衣，细看新月如钩。\n谁道是、嫦娥不嫁，独守清秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7742, '雨中花・夜行船', '杨无咎', '雨霁云收，风高露冷，银河万里波澄。\n正冰轮初见，玉斧修成。\n还是一年，凭栏望处，对景愁生。\n想娥应念，待久西厢，为可中庭。\n翻思皓彩，未如微暗，向人多少深情。\n长记得、墙阴密语，花底潜行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7743, '鹊桥仙', '杨无咎', '云容掩帐，星辉排烛，待得鹊成桥後。\n匆匆相见夜将阑，更应副、家家乞巧。\n经年怨别，霎时欢会，心事如何可了。\n朝朝暮暮是佳期，乍可在、人间先老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7744, '洞仙歌', '杨无咎', '痴牛呆女，谩恩深情远。\n一岁惟能一相见。\n纵金风玉露，胜却人间，争奈向、雪月花时阻间。\n幽欢犹未足，催度桥归，乌鹊无端便惊散。\n别後欲重来，杳杳银河，空怅望、不胜凄断。\n最可惜、当初泛槎人，甚不问、天边这些磨难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7745, '多丽', '杨无咎', '晚风清，淡云卷尽轻罗。\n看银蟾、初离海上，万里碧汉澄波。\n碾云衢、玉轮缓驾，照山影、宝镜新磨。\n光彻庭除，寒生绮席，无聊清兴助吟哦。\n共宴赏、明宵天气，晴晦又知他。\n无眠处，衣濡湛露，目断明河。\n念年来、青云失志，举头羞见嫦娥。\n且高歌、细敲檀板，拚痛饮、频倒金荷。\n断约他年，重挥大手，桂枝须斫最高柯。\n恁时节、清光比似，今夕更应多。\n功名事，到头须在，休用忙呵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7746, '卓牌子慢・卓牌子', '杨无咎', '西楼天将晚。\n流素月、寒光正满。\n楼上笑揖娥，似看罗袜尘生，鬓云风乱。\n珠帘终夕卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7747, '倒垂柳', '杨无咎', '晓来烟露重，为重阳、增胜致。\n记一年好处，无似此天气。\n东篱白衣至，南陌芳筵启。\n风流曾未远，登临都在眼底。\n人生如寄。\n谩把茱萸看子细。\n击节听高歌，痛饮莫辞醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7748, '惜黄花慢', '杨无咎', '霁空如水。\n衬落木坠红，遥山堆翠。\n独立闲阶，数声□度风前，几点雁横云际。\n已凉天气未寒时，问好处、一年谁记。\n笑声里。\n摘得半钗，金蕊来至。\n横斜为插乌纱，更碎揉、泛入金尊琼蚁。\n满酌霞觞，愿人寿百千，可奈此时情味。\n牛山何必独沾衣，对佳节、惟应欢醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7749, '醉花阴', '杨无咎', '满城风雨无端恶。\n孤负登高约。\n佳节若为酬，盛与歌呼，胜却秋萧索。\n菊花旋摘揉青萼。\n满满浮杯杓。\n老鬓未侵霜，醉里乌纱，不怕风吹落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7750, '醉花阴', '杨无咎', '捧杯不管馀酲恶。\n玉腕宽金约。\n宛转一声清，戛玉敲冰，浑胜鸣弦索。\n朱唇浅破桃花萼。\n重注鸬鹚杓。\n夜永醉归来，细想罗襟，犹有梁尘落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7751, '醉花阴', '杨无咎', '楚乡易得天时恶。\n风雨长如约。\n不道有幽人，衣带秋深，犹自悬鹑索。\n招呼朋侣如花萼。\n有酒须同酌。\n世态任凋疏，却爱黄花，不似群花落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7752, '醉花阴', '杨无咎', '金铃玉屑嫌非巧。\n生作文鸳小。\n西帝也多情，偷取佳名，分付闲花草。\n渊明手把谁携酒。\n羞把簪乌帽。\n寄与绮窗人，百种妖娆，不似酴好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7753, '醉花阴', '杨无咎', '淋漓尽日黄梅雨。\n断送春光暮。\n目断向高楼，持酒停歌，无计留春住。\n扑人飞絮浑无数。\n总是添愁绪。\n回首问春风，争得春愁，也解随春去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7754, '解蹀躞', '杨无咎', '迤逦韶华将半。\n桃杏匀於染。\n又还撩拨、春心倍凄黯。\n准拟□□狂吟，可怜无复当年，酒肠文瞻。\n倦游览。\n憔悴羞窥鸾鉴。\n眉端为谁敛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7755, '琐窗寒', '杨无咎', '柳暗藏鸦，花深见蝶，物华如绣。\n情多思远，又是一番清瘦。\n忆前回、庭榭来春，个人预约同携手。\n恨迟留，载酒期程，孤负踏青时候。\n搔首。\n双眉暗斗。\n况无似今年，一春晴昼。\n风雨。\n直得□时迤逗。\n想闲窗、针线倦拈，寂寞细拈酴嗅。\n待还家、定自冤人，泪粉盈襟袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7756, '玉楼春', '杨无咎', '朱帘碧瓦干云际。\n占尽潇滩形势地。\n傍墙人唤状元家，想见华堂融瑞气。\n寿杯莫惜团栾醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7757, '玉楼春', '杨无咎', '娉婷标格神仙样。\n几日佩环离海上。\n小春只隔一旬期，菊蕊包香犹未放。\n霞觞满酌摇红浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7758, '玉楼春', '杨无咎', '酒阑未放宾朋散。\n自拈冰芽教旋碾。\n调膏初喜玉成泥，溅沫共惊银作线。\n已知於我情非浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7759, '清平乐', '杨无咎', '开心暖胃。\n最爱门冬水。\n欲识味中犹有味。\n记取东坡诗意。\n笑看玉笋双传。\n还思此老亲煎。\n归去北窗高卧，清风不用论钱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7760, '清平乐', '杨无咎', '花阴转午。\n小院清无暑。\n雪碗冰瓯凝灏露。\n自涤紫毫鸡距。\n麝煤落纸生春。\n只应李卫夫人。\n我亦前身逸少，莫嗔太逼君真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7761, '渔家傲', '杨无咎', '昨日小春才得信。\n明宵新月初生晕。\n又对寿觞斟九酝。\n香成阵。\n欢声点破梅梢粉。\n琪树长青资玉润。\n鸳鸯不老眠沙稳。\n此去期程知远近。\n君休问。\n山河有尽情无尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7762, '渔家傲', '杨无咎', '菊暗枯秋已满。\n枨黄橘绿冬初暖。\n草草杯盘成小宴。\n殷勤劝。\n尊前莫遣霞觞浅。\n两鬓从教霜点半。\n人生最要长为伴。\n举洒岂徒称寿算。\n深深愿。\n来年更看门风换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7763, '渔家傲', '杨无咎', '梅晕渐开红蜡垒。\n菊篱尚耀黄金蕊。\n正是小春风物美。\n宜家喜。\n生朝颜巷犹和气。\n古鼎氤氲云缕细。\n霞觞潋滟红鳞起。\n听取殷勤歌里意。\n千秋气。\n北堂同我供甘旨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7764, '渔家傲', '杨无咎', '事事无心闲散惯。\n有时独坐溪桥畔。\n雨密波平鱼曼衍。\n鱼曼衍。\n轮轻钓细随风卷。\n忆昔故人为侣伴。\n而今怎奈成疏间。\n水远山长无计见。\n无计见。\n投竿顿觉肠千断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7765, '双雁儿', '杨无咎', '穷阴急景暗推迁。\n减绿鬓，捐朱颜。\n利名牵役几时闲。\n又还惊，一岁圆。\n劝君今夕不须眠。\n且满满，泛觥船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7766, '双雁儿', '杨无咎', '休惊明日岁华新。\n且喜得，又逢春。\n北堂歌舞奉慈亲。\n愿遐龄，等大椿。\n□□□□□□□。\n□□□，□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7767, '迎春乐', '杨无咎', '新来特特更门地。\n都收拾、山和水。\n看明年、事事都如意。\n迎福禄、俱来至。\n莫管明朝添一岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7768, '永遇乐', '杨无咎', '鸳瓦霜明，绣帘烟暖，和气容与。\n云想衣裳，风清环佩，拥翠娥扶步。\n蓬山远别，仙班知是，有客旧同俦侣。\n来到、人间又也，爱他相门荣遇。\n清秋菊在，小春梅绽，正是年华好处。\n酒满瑶觞，歌翻金缕，莫放行云去。\n已随夫贵，仍因儿显，两国看齐楚。\n此时对、生朝听我，却称寿语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7769, '永遇乐', '杨无咎', '黄叶缤纷，碧江清浅，锦水秋暮。\n画鼓冬冬，高牙，离棹无由驻。\n波声笳韵，芦花蓼穗，翻作别离情绪。\n须知道、风流太守，未尝恝情来去。\n那堪对此，来时单骑，去也文鸳得侣。\n绣被熏香，蓬窗听雨，还解知人否。\n一川风月，满堤杨柳，今夜酒醒何处。\n调疏呵，双栖正稳，慢摇去橹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7770, '永遇乐', '杨无咎', '风褪柔英，雨肥繁实，又还如豆。\n玉核初成，红腮尚浅，齿软酸微透。\n粉墙低亚，佳人惊见，不管露沾襟袖。\n折一枝、钗头未插，应把手频嗅。\n相如病酒，只因思此，免使文君眉皱。\n入鼎调羹，攀林止渴，功业还依旧。\n看看飞燕，衔将春去，又是欲黄时候。\n争如向、金盘满捧，共君对酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7771, '玉烛新', '杨无咎', '荒山藏古寺。\n见傍水梅开，一枝三四。\n兰枯蕙死。\n登临处、慰我魂消惟此。\n可堪红紫。\n曾不解、和羹结子。\n高压尽、百卉千葩，因君合修花史。\n韶华且莫吹残，待浅松煤，写教形似。\n此时胸次。\n凝冰雪、洗尽从前尘滓。\n吟安个字。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7772, '御街行', '杨无咎', '平生厌见花时节。\n惟只爱、梅花发。\n破寒迎腊吐幽姿，占断一番清绝。\n照溪印月，带烟和雨，傍竹仍藏雪。\n松煤淡出宜孤洁。\n最嫌把、铅华说。\n暗香销尽欲飘零，须得笛声呜咽。\n这些风味，自家领略，莫与傍人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7773, '柳梢青', '杨无咎', '傲雪凌霜。\n平欺寒力，搀借春光。\n步绕西湖，兴馀东阁，可奈诗肠。\n娟娟月转回廊。\n悄无处、安排暗香。\n一夜相思，几枝疏影，落在寒窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7774, '柳梢青', '杨无咎', '雪艳烟痕。\n又要春色来到芳尊。\n却忆年时，月移清影，人立黄昏。\n一番幽思谁论。\n但永夜、空迷梦魂。\n绕遍江南，缭墙深苑，水郭山村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7775, '柳梢青', '杨无咎', '茅舍疏篱。\n半飘残雪，斜卧低枝。\n可更相宜，烟笼修竹，月在寒溪。\n亭亭伫立移时。\n判瘦损、无妨为伊。\n谁赋才情，画成幽思，写入新诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7776, '柳梢青', '杨无咎', '月堕霜飞。\n隔窗疏瘦，微见横枝。\n不道寒香，解随羌管，吹到屏帷。\n个中风味谁知。\n睡乍起、乌云任。\n嚼蕊英，浅颦轻笑，酒半醒时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7777, '柳梢青', '杨无咎', '日转墙东。\n几枝寒影，一点香风。\n清不成眠，醉凭诗兴，起绕珍丛。\n平生只个情锺。\n渐老矣、无愁可供。\n最是难忘，倚楼人在，横笛声中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7778, '柳梢青', '杨无咎', '玉骨冰肌。\n为谁偏好，特地相宜。\n一段风流，广平休赋，和靖无诗。\n绮窗睡起春迟。\n困无力、菱花笑窥。\n嚼蕊吹香，眉心贴处，鬓畔簪时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7779, '柳梢青', '杨无咎', '为爱冰姿，画看不足，吟看不足。\n已恨春催，可堪风里，飞英相逐。\n只应自惜高标，似羞伴、妖红媚绿。\n藏白收香，放他桃李，漫山粗俗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7780, '柳梢青', '杨无咎', '水曲山傍。\n寒梢冷蕊，隐映修篁。\n细细吹香，疏疏沈影，恼断回肠。\n为伊驻马横塘。\n漫立尽、烟村夕阳。\n空袅吟鞭，几多诗句，不入思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7781, '柳梢青', '杨无咎', '天付风流。\n相时宜称，著处清幽。\n雪月光中，烟溪影里，松竹梢头。\n却憎吹笛高楼。\n一夜里、教人鬓秋。\n不道明朝，半随风远，半逐波浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7782, '柳梢青', '杨无咎', '屋角墙隅。\n占宽闲处，种两三株。\n月夕烟朝，影侵窗牖，香彻肌肤。\n群芳欲比何如。\n癯儒岂、膏梁共途。\n因事顺心，为花修史，从记中书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7783, '柳梢青', '杨无咎', '瑞鸭烟浓。\n晓来弦管，声在霜空。\n却退寒威，借回春色，满苑香风。\n几时人下瑶宫。\n记千载、今朝庆逢。\n满捧瑶觞，芝兰丛里，锦绣光中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7784, '柳梢青', '杨无咎', '江月轩中。\n拍堤新涨，绕院熏风。\n深注瑶觞，低歌金缕，声在晴空。\n新词尽索无穷。\n断酩酊、衰颜为红。\n愿得年年，繁枝子满，绿叶阴浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7785, '柳梢青', '杨无咎', '槐夏风清。\n霁天欲晓，武曲增明。\n元是今朝，曾生名将，力佐中兴。\n朝家息马休兵。\n享逸乐、嬉游太平。\n忧国胸襟，平戎材略，分付瑶觥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7786, '柳梢青', '杨无咎', '灼灼红榴，垂垂绿柳，庭户清和。\n罗绮香中，十分春酒，几叠高歌。\n遐龄欲问如何。\n记平日、阴功数多。\n千载今朝，笑看池面，龟戏青荷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7787, '柳梢青', '杨无咎', '小阁深沈，酒醺香暖，容易眠熟。\n梦入仙源，桃红似火，李莹如玉。\n觉来几许悲凉，记永夜、传杯换烛。\n绣被熏香，宝钗落枕，同论心曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7788, '柳梢青', '杨无咎', '送雁迎鸿，未寒时节，已凉天气。\n针线倦拈，帘帏低卷，别般风味。\n眠梦到山中，共老幼、扶携笑喜。\n桑柘影深，鸡豚香美，家家人醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7789, '柳梢青', '杨无咎', '暴雨生凉。\n做成好梦，飞到伊行。\n几叶芭蕉，数竿修竹，人在南窗。\n傍人笑我惶。\n算除是、铁心石肠。\n一自别来，百般宜处，都入思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7790, '解连环', '杨无咎', '素书谁托。\n嗟鳞沈雁断，水遥山邈。\n问别来、几许离愁，但只觉衣宽，不禁消薄。\n岁岁年年，又岂是、春光萧索。\n自无心、强陪醉笑，负他满庭花药。\n援琴试弹贺若。\n尽清于别鹤，悲甚霜角。\n怎似得、斜拥檀槽，看小品吟商，玉纤推却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7791, '踏莎行', '杨无咎', '灯月交光，笙簧递响。\n繁华依旧升平样。\n心期休卜紫姑神，文章曾照青藜杖。\n歌落梁尘，酒摇鳞浪。\n暂还南国同邀赏。\n明年侍辇向端门，却瞻日表青霄上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7792, '探春令', '杨无咎', '梅英粉淡，柳梢金软，兰芽依旧。\n见万家、灯火明如昼。\n正人月、圆时候。\n挨香傍玉偷携手。\n尽轻衫寒透。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7793, '探春令', '杨无咎', '雪梅风柳，弄金匀粉，峭寒犹浅。\n又还近、三五银蟾满。\n渐玉漏、声初短。\n尊前重约年时伴。\n拈灯词先按。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7794, '探春令', '杨无咎', '搦儿身分，测儿鞋子、捻儿年纪。\n著一套、时样不肯红，甚打扮、诸馀济。\n回头一笑千娇媚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7795, '探春令', '杨无咎', '东风初到，小梅枝上，又惊春近。\n料天台不比，人间日月，桃萼红英晕。\n刘郎浪迹凭谁问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7796, '人月圆', '杨无咎', '风和日薄馀烟嫩，测测透鲛绡。\n相逢且喜，人圆玳席，月满丹霄。\n烂游胜赏，高低灯火，鼎沸笙箫。\n一年三百六十日，愿长似今宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7797, '人月圆', '杨无咎', '月华灯影光相射。\n还是元宵也。\n绮罗如画，笙歌递响，无限风雅。\n闹蛾斜插，轻衫乍试，闲趁尖耍。\n百年三万六千夜，愿长如今夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7798, '眼儿媚', '杨无咎', '柳腰花貌天然好，聪慧更温柔。\n千娇百媚，一时半霎，不离心头。\n是人总道新来瘦，也著甚来由。\n假饶薄命，因何瘦了，地风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7799, '倒垂柳', '杨无咎', '南州初会遇。\n记惺惺、说底语。\n而今精神□，倾下越风措。\n雍门人独夜，客舍停杯处。\n馀香应未泯，凭君重唱金缕。\n移宫易羽。\n纵有离愁休怨诉。\n客里□凄凉，怕听断肠句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7800, '南歌子', '杨无咎', '露宠妆成态，风扶醉里身。\n谩劳驿使走征尘。\n岭外陇头处、不知春。\n诗思如清水，毫端妙入神。\n可怜徒效越娘颦。\n为问吟哦摹写、几曾真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7801, '南歌子', '杨无咎', '小雨疏疏过，长江滚滚流。\n落霞残照晚明楼。\n又是一番重午，身寄南州。\n罗绮纷香陌，鱼龙漾彩舟。\n不堪回首凤池头。\n谁道於今霜鬓，犹自淹留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7802, '南歌子', '杨无咎', '波静明如染，山光翠欲流。\n晚来乘兴上章楼。\n楼外谁歌新唱，知有黄州。\n拟泛银可浪，聊乘藕叶舟。\n蓬山应自隐鳌头。\n借问谪仙何在，今为谁留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7803, '南歌子', '杨无咎', '笛喷风前曲，歌翻意外声。\n年来老子厌风情。\n可是於君一见、眼双明。\n枕臂听残漏，停杯对短檠。\n直教笔底有文星。\n欲状此时情味、若为成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7804, '南歌子', '杨无咎', '巾染乌烟碧，衣拖晓露鲜。\n盈盈风骨小神仙。\n特地勾牵处士、梦巫山。\n星宿罗胸次，牙签弄指端。\n凭君为算小行年。\n试问与伊结得、几生缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7805, '南歌子', '杨无咎', '彩缕牵肠断，明珠暗滴圆。\n从头颗颗手亲穿。\n寄与仙乡同结、此生缘。\n和串拢瑜臂，连云坠雪肩。\n循环密数对沈烟。\n似我真情不断、永相联。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7806, '西江月', '杨无咎', '沙上鸥群□戏，云端雁阵斜铺。\n殷勤特为故人书。\n写尽衷肠情素。\n名字纵非俦匹，夤缘自合欢娱。\n尽教涂抹费工夫。\n到底翻成吃醋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7807, '西江月', '杨无咎', '态度雪香花瘦，情怀雨润云温。\n故将淡墨写精神。\n记得洗妆馀晕。\n只恐妖娆未似，谁云彼此难分。\n别来憔悴不堪论。\n相对无言有恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7808, '生查子', '杨无咎', '秋深郎未归，月上人初静。\n无语意迟迟，步转梧桐影。\n罗衣宽莫裁，云鬓松还整。\n谁与问相思，立尽清宵永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7809, '生查子', '杨无咎', '秋来愁更深，黛拂双蛾浅。\n翠袖怯春寒，修竹萧萧晚。\n此意有谁知，恨与孤鸿远。\n小立背西风，又是重门掩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7810, '生查子', '杨无咎', '妖娆百种宜，总在春风面。\n含笑又和嗔，莫作丹青现。\n问著却无言，觑了还回盼。\n底处奈思量，卷了还重展。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7811, '甘草子', '杨无咎', '秋暮。\n永夜西楼，冷月明窗户。\n梦破橹声中，忆在松江路。\n枕试寻曾游处。\n记历历、风光堪数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7812, '鹧鸪天', '杨无咎', '湖上风光直万金。\n芙蓉并蒂照清深。\n须知花意如人意，好在双心同一心。\n词共唱，酒俱斟。\n夜阑扶醉小亭阴。\n当时比翼连枝愿，未必风流得似今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7813, '鹧鸪天', '杨无咎', '休倩傍人为正冠。\n披襟散发最宜闲。\n水云况得平生趣，富贵何曾著眼看。\n低拍棹，称鸣銮。\n一尊长向枕边安。\n夜深贪钓波间月，睡起知他日几竿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7814, '鹧鸪天', '杨无咎', '不学真空不学仙。\n不居尘市不居山。\n时沽鲁酒供诗兴，莫管吴霜点鬓斑。\n只麽去，几时还。\n岂知魂梦□□间。\n凭君休作千年调，到处惟□一味闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7815, '鹧鸪天', '杨无咎', '蕙性柔情忒可怜。\n盈盈真是女中仙。\n披图一见春风面，携手疑同玳瑁筵。\n挥象管，擘蛮笺。\n等闲写就碧云篇。\n风流意态犹难画，潇洒襟怀怎许传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7816, '天下乐', '杨无咎', '雪後雨儿雨後雪。\n镇日价、长不歇。\n今番为寒忒太切。\n和天地、也来厮鳖。\n睡不著、身心自暗。\n这况味、凭谁说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7817, '玉抱肚', '杨无咎', '同行同坐。\n同携同卧。\n正朝朝暮暮同欢，怎知终有抛。\n记江皋惜别，那堪被、流水无情送轻舸。\n有愁万种，恨未说破。\n知重见、甚时可。\n见也浑闲，堪嗟处、山遥水远，音书也无个。\n这眉头、强展依前锁。\n这泪珠、强依前堕。\n我平生、不识相思，为伊烦恼忒大。\n你还知麽。\n你知後、我也甘心受催挫。\n又只恐你，背盟誓、似风过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7818, '雨中花令', '杨无咎', '惆怅红尘千里。\n恨死拨、浮名浮利。\n欠我温存，少伊就，两处悬悬地。\n拟待归来伏不是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7819, '雨中花令', '杨无咎', '已是花魁柳冠。\n更绝唱、不容同伴。\n画鼓低敲，红牙随应，著个人勾唤。\n慢引莺喉千样转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7820, '雨中花令', '杨无咎', '自是云温雨润。\n诮不解、佯嗔偷闷。\n倾坐精神，人情性，眉际生春晕。\n语带京华清更韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7821, '夜行船', '杨无咎', '不假铅华嫌太白。\n玉搓成、体柔腰搦。\n明月堂深，莲花杯软，情重自斟琼液。\n寄语休并色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7822, '夜行船', '杨无咎', '醉袖轻拢檀板转。\n听声声、晓莺初啭。\n花落江南，柳青客舍，多少旧愁新怨。\n我也寻常听见惯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7823, '夜行船', '杨无咎', '宝髻双垂烟一缕。\n年纪小、未周三五。\n压一精神，出群标格，偏向众中翘楚。\n记得谯门初见处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7824, '夜行船', '杨无咎', '怪被东风相误。\n落轻帆、暂停烟渚。\n桐树阴森，茅檐潇洒，元是那回来处。\n相与狂朋沽绿醑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7825, '夜行船', '杨无咎', '夹岸绮罗欢聚。\n看喧喧、彩舟来去。\n晴放湖光，雨添山色，谁识总相宜处。\n输与骚人知胜趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7826, '两同心', '杨无咎', '行看不足。\n坐看不足。\n柳条短、斜倚春风，海棠睡、醉红玉。\n清堪掬。\n桃李漫山，真成粗俗。\n遥夜几番相属。\n暗魂飞逐。\n深酌酒、低唱新声，密传意、解回娇目。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7827, '两同心', '杨无咎', '秋水明眸、翠螺堆发。\n却扇坐、羞落庭花，凌波步、尘生罗袜。\n芳心发。\n分付春风，恰当时节。\n渐解愁花怨月。\n忒贪娇劣。\n宁宁地、情态于人，惺惺处、语言低说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7828, '两同心', '杨无咎', '月可中庭，夜凉初燕。\n见个人人、越格风流，饶济济、入时打扮。\n小从容，不似前回，匆匆得见。\n坐上不禁肠断。\n捧杯深劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7829, '两同心', '杨无咎', '枕簟凉生秋早。\n梦魂忒好。\n见玉人、且喜且悲，挨琼脸、厮偎厮抱。\n信言多磨，刚被山禽，一声催晓。\n觉来满船清悄。\n愁恨多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7830, '乌夜啼', '杨无咎', '不禁枕簟新凉。\n夜初长。\n又是惊回好梦、叶敲窗。\n江南望。\n江北望。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7831, '朝天子', '杨无咎', '小阁宽如掌。\n占螺浦、山川夷旷。\n千奇万状。\n见云烟收放。\n更永夜、风生明月上。\n用取真成无尽藏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7832, '步蟾宫', '杨无咎', '桂花馥郁清无寐。\n觉身在、广寒宫里。\n忆吾家、妃子旧游，瑞龙脑、暗藏叶底。\n不堪午夜西风起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7833, '步蟾宫', '杨无咎', '一斑两点从初起。\n这手脚、渐不灵利。\n背人只待暗搔爬，腥臭气、薰天炙地。\n下梢管取好脓水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7834, '长相思', '杨无咎', '急雨回风，淡云障日，乘闲携客登楼。\n金桃带叶，玉李含朱，一尊同醉青州。\n福善桥头。\n记檀槽凄绝，春笋纤柔。\n窗外月西流。\n似浔阳、商妇邻舟。\n况得意情怀，倦妆模样，寻思可奈离愁。\n何妨乘逸兴，甚征帆、只抵芦洲。\n月却花羞。\n重见想、欢情更稠。\n问何时，佳期卜夜，如今双鬓惊秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7835, '曲江秋', '杨无咎', '前山雨歇。\n爱竹树低阴，轩窗无热。\n珠箔半垂，清风细绕，萧萧吹华发。\n珍簟粲枕设。\n珊瑚瘦，琉璃滑。\n永日枕，知谁是伴，旧书重揭。\n清绝。\n轻云淡月。\n梦同泛、沧波万叠。\n杯盘狼籍处，相扶就枕，欢笑歌翻雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7836, '曲江秋', '杨无咎', '香消烬歇。\n换沈水重燃，薰炉犹热。\n银汉坠怀，冰轮转影，冷光侵毛发。\n随分且宴设。\n小槽酒，真珠滑。\n渐觉夜阑，乌纱露濡，画帘风揭。\n清绝。\n轻纨弄月。\n缓歌处、眉山怨叠。\n持杯须我醉，香红映脸，双腕凝霜雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7837, '曲江秋', '杨无咎', '鸣鸠怨歇。\n对急雨过云，暗风吹热。\n漠漠稻田，差差柳岸，新沐青丝发。\n楼上素琴设。\n爱流水，随弦滑。\n深炷龙津，浓熏绛帏，博山频揭。\n超绝。\n遥岑吐月。\n照苍茜、重重叠叠。\n恍然身在处，浑疑同泛，花舫波喷雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7838, '点绛唇', '杨无咎', '小阁清幽，胆瓶高插梅千朵。\n主宾欢坐。\n不速还容我。\n换羽移宫，绝唱谁能和。\n伊知麽。\n暂听些个。\n已觉丝成裹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7839, '柳梢青', '杨无咎', '渐近青春，试寻红，经年疏隔。\n小立风前，恍然初见，情如相识。\n为伊只欲颠狂，犹自把、芳心爱惜。\n传与东君，乞怜愁寂，不须要勒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7840, '柳梢青', '杨无咎', '嫩蕊商量。\n无穷幽思，如对新妆。\n粉面微红，檀唇羞启，忍笑含香。\n休将春色包藏。\n抵死地、教人断肠。\n莫待开残，却随明月，走上回廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7841, '柳梢青', '杨无咎', '粉墙斜搭。\n被伊勾引，不忘时霎。\n一夜幽香，恼人无寐，可堪开币。\n晓来起看芳丛，只怕里、危梢欲压。\n折向胆瓶，移归芸阁，休薰金鸭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7842, '柳梢青', '杨无咎', '目断南枝。\n几回吟绕，长怨开迟。\n雨风欺，雪侵霜妒，却恨离披。\n欲调商鼎如期。\n可奈向、骚人自悲。\n赖有毫端，幻成冰彩，长似芳时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7843, '法曲散序・法曲', '曹勋', '飞金走玉常奔驰。\n日上还西。\n自古待著长绳系。\n算尘心、谩劳役堪悲。\n盘古到此际。\n桑田变海，海复成陆高低。\n噫嘻。\n下土是凡质容仪。\n寿考能消，几日支持。\n念一世。\n真若朝荣暮落难期。\n幸有志、日传得神仙希夷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7844, '法曲歌头・法曲', '曹勋', '柱史乘车，青牛驾轭，紫云覆顶，函关令已前知。\n西升稍驻，尹喜虔恭誓。\n求老子。\n亲谈道德微旨。\n五千馀言，俱救末俗，度脱令咸归生理。\n体元机。\n人间方解道术，兼明治身，与国阶梯。\n更有黄庭，专分二境，内外皆举璇题。\n羽客见者，倾诚恳诵合彝仪。\n万神潜礼。\n密奉二经，炷香静默，心无竞，靡端倪。\n得失扫去，意海澄流要体。\n内景防愆失。\n外景忘疲。\n阆风蓬岛岂能移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7845, '法曲遍第一・法曲', '曹勋', '丽景早春时。\n正花漏初迟。\n东君出震，太和应物，恍惚中立丹基。\n天风卦成随象，记合成□□□□□□□必相契。\n三千六百火候，密运精微。\n蒸入肌肤，嫩红潮颊，自然旧容生辉。\n情志。\n鄙凡尘，瑶圃满眼，都看桃李。\n晴云万叠开异色。\n灵光湛湛增秀逸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7846, '法曲遍第二・法曲', '曹勋', '向虚靖晨起。\n朝元意达，冲漠怡怡。\n三天澄映，九光霁碧，如有鹤舞鸾飞。\n泛空际。\n瑶室明辉。\n动与真期。\n至理常寂，户庭无远，欣欣端比。\n侍宴日在瑶池。\n师友多闲，抱琴沽酒度曲，笑采华芝。\n九节倚筇时。\n何须钓月眠石，寻觅占渊静逸。\n乐修持。\n澹然灵府泳真谛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7847, '法曲遍第三・法曲', '曹勋', '珠星璧月，昼景夜色相催。\n正阳炎序火府，龙珠蕴照，冰海融澌。\n洞天春常好，日日琪花，琼蕊芳菲。\n绛景无别，惟似琉璃。\n平地环绕清。\n火中生莲，会成真物，更取海底龟儿。\n胜热涤暑风，全形莹若冰肌。\n常存道意。\n铄石流金无畏。\n共协混元一气。\n入冲极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7848, '法曲第四・法曲', '曹勋', '南薰殿阁，卷窗户新翠。\n池沼十顷净，俯桥影横霓。\n龟鱼自乐，潺潺螭口，流水照碧，芰荷绿满长堤。\n柳烟水色，一派涟漪。\n松竹阴中，细风缓引凉吹。\n琴韵响，玉德凤轸，声传瑶徽。\n疏襟曳履。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7849, '法曲入破第一・法曲', '曹勋', '秋容应节，渐肃景入窗扉。\n碧洞连翠微。\n商律回岩桂。\n金精壮盛时。\n拥蟾轮、生素辉。\n启口天为侣，是列仙行缀。\n心均太上，欲度世缘无亏。\n用定力坚持。\n奉真常，惟凝寂。\n忱诚贯斗极。\n赐长生，仍久视。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7850, '法曲入破第二・法曲', '曹勋', '清昼静居香冷，风动万年枝。\n凉应兑卦体。\n秋色鸣轻。\n冥心运正一。\n御铁牛、耕寸地。\n都种金钱花，秀色照戊己。\n新霜万物凋谢，我常无为。\n冲起浩然气。\n抱冲和，人间世。\n登高共赏宴，泛东篱。\n菊尽醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7851, '法曲入破第三・法曲', '曹勋', '光铺晓曦。\n云影拂霜低。\n空阔飞鸿过，两三行、向天际。\n晴景乍升，晃疏棂，蜂翅迷。\n密障红炉暖，香缕飘烟细。\n超然坐久，幽径试寻寒梅。\n酥点竹间稀。\n正疏蓓吐南枝。\n微阳动细蕊。\n任斜日、沈澹晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7852, '法曲入破第四・法曲', '曹勋', '黄锺正严凛，飞舞屑琼瑰。\n清赏丰年瑞。\n云液喜传杯。\n阴爻会见复，动一阳、生浩气。\n谁问添宫线，炼功在金液。\n晴檐试暖，表里莹如无疵。\n庭柳漏春信，更萱色、侵苔砌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7853, '法曲第五煞・法曲', '曹勋', '多景推移。\n便似风灯里。\n将尘寰喻，尘里白驹过隙。\n今世过却，来生何处觅。\n失时节。\n生死到来嗟何及。\n勤而行之。\n竞力待与、锺吕相期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7854, '大椿', '曹勋', '梅拥繁枝，香飘翠帘，钧奏严陈华宴。\n诚孝感南极，老人星垂眷。\n东朝功崇庆远，享五福、长乐金殿。\n兹时寿协七旬，庆古今来稀见。\n慈颜绿发看更新，玉色粹温，体力加健。\n导引冲和气，觉春生酒面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7855, '花心动', '曹勋', '椒柏称觞，抚寰瀛佳辰，正临端月。\n瑞应屡臻，宫多祥，气候暖回微冽。\n圣母七旬寿，无前、天心昭格。\n溥庆处，坤珍效祉，宴开清切。\n金殿箫韶备设。\n锵钧奏留云，舞容回雪。\n赭袍绣拥，翟同诚，递捧玉杯欢悦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7856, '保寿乐', '曹勋', '和气暖回元日，四海充庭琛贡至。\n仗卫俨东朝，郁郁葱葱，响传环佩。\n凤历无穷，庆慈闱上寿，皇情与天俱喜。\n念永锡难老，在昔难比。\n六宫嫔嫱罗绮。\n奉圣德、坤宁俱备。\n箫韶动钧奏，花似锦，广筵启。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7857, '宴清都', '曹勋', '画幕明新晓。\n晴日薄，小春微动花柳。\n宸闱荐祉，东朝诞育，载光坤厚。\n朱颜内鼎丹就。\n喜自得、长生妙有。\n奉冕旒、衣彩坤珍，同耀帕罗珠袖。\n钧奏。\n翠羽帘垂，三千粉色，花明如绣。\n歌声缓引，梁尘暗落，五云凝昼。\n龙香绕斟芳酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7858, '宴清都', '曹勋', '凤苑东风软。\n春容早，岁端新律初转。\n宫云丽晓，人日应锺，庆符闺范。\n元妃懿德尊显。\n位四圣、晋芳避辇。\n佐圣主、美化重宣，光被海宇弥远。\n香满。\n帝渥恩隆，歌珠舞雪，俱陈丝管。\n彤闱共悦，天颜有喜，看寿觞亲劝。\n今年外家华焕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7859, '一寸金', '曹勋', '霜落鸳鸯，绣隐芙蓉小春节。\n应运看，月魄分辉，坤顺同符，文母徽音芳烈。\n诞育乾坤主，均慈爱、练裙岂别。\n经沙塞、涉履烟尘，瑞色怡然更英发。\n上圣中兴，严恭问寝，宫庭正和悦。\n看寿筵高启，龙香低转，声入霓裳，檀槽新拨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7860, '国香', '曹勋', '十月新阳。\n喜桃杏秀发，宫殿春香。\n宝历开图，文母协应时康。\n诞庆欣逢令旦，向花闱、罄列嫔嫱。\n欢荣是九五，侍膳芳筵，翠龙章。\n天心人共喜，拱三钗瑞彩，同捧瑶觞。\n禁中和气，都入法部丝簧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7861, '国香', '曹勋', '红染芙蓉。\n似晓霞丽日，秋满珠宫。\n瑞彩朝来，都做和气葱葱。\n共庆龟台降祉，化均凤历同风。\n升平助阴化，奉养馀闲，翰墨鸾龙。\n群仙移彩仗，尽红妆玉带，乐震霜空。\n响入千岩，芳桂香散房栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7862, '齐天乐', '曹勋', '芙蓉凝露青霞护，朝日绮疏风细。\n正是中秋，时候喜逢，中宫葱葱佳气。\n云龙庆会。\n赞真主当阳，辅成天地。\n暇日琴书，暂闲蚕馆见贤志。\n嫔嫱衣罗乍试。\n尽趋椒殿，喜芳绣筵初启。\n酒面腾红，香烟罩碧，恩满六宫金翠。\n何妨绛烛。\n任花玉侧，劝教沈醉。\n凤阙龙楼，夜色凉如水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7863, '透碧霄', '曹勋', '阆苑喜新晴。\n正桂华、飘下太清。\n宝凉秋，梦祥明月，天开辅盈成。\n宫闱女职遵慈训，见海宇仪型。\n奉东朝、晨夕趋承。\n化内外、咸知柔顺，已看彤管赋和平。\n宴坤宁。\n香腾金猊，烟暖秘殿彩衣轻。\n六乐丝竹，绕云萦水，总按新声。\n天临帝幄，亲颁寿酒，恩意兼勤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7864, '芰荷香', '曹勋', '彩云闲。\n正西瑶阿母，初驻非烟。\n晓空吹静，暑气清度薰弦。\n母仪万国，配帝德、直切天垣。\n阴化从此俱宣。\n六宫内壶，欣拜新班。\n况是关雎咏懿美，奉东朝晨夕，甘旨芳鲜。\n上膺慈训，下齐海宇均欢。\n坤宁暇日，庆盛旦、且款芳筵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7865, '玉连环・解连环', '曹勋', '庆云开霁，清华明昼，殿阁风度薰弦。\n电虹敷瑞，应炎运当千。\n端景命、符圣德，三阶正、万国归化，远胜文思睿藻，问鲭寝格中天。\n深严。\n邃启芳筵。\n正花拥绛，瑶殿神仙。\n缓闻钧韶奏下，歌舞云边。\n宫闱罄和气，浃南山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7866, '夏云峰', '曹勋', '绍洪基，抚万宇，中兴宝运符千。\n枢电瑞绕，景命燕及云天。\n挺生真主，平四海、复禹山川。\n班列立、瞻云就日，职贡衣冠。\n欢均鳌禁鸾。\n望花城粉黛，金兽祥烟。\n笙箫缓奏，化国日永留连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7867, '凤凰台上忆吹箫', '曹勋', '碧玉烟塘，绛罗艳卉，朱清炎驭升。\n正应运、真人诞节，宝绪灵光。\n海宇均颁湛露，环佩拱、北极称觞。\n欢声浃，三十六宫，齐奉披香。\n芬芳。\n宝薰如霭，仙仗捧椒扉，秀绕嫔嫱。\n上万寿、双鬟妙舞，一部丝簧。\n花满蓬莱殿里，光照坐、尊俎生凉。\n南山祝，常对化日舒长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7868, '安平乐・安平乐慢', '曹勋', '圣德如尧，圣心如舜，欣逢出震昌期。\n中兴继体，抚有寰瀛，三阳方是炎曦。\n万国朝元，奉崇严宸，咫尺天威。\n瑞色满三墀。\n渐嵩呼、均庆彤闱。\n正金屋妆成，翠围红绕，香霭高散狻猊。\n东朝移雕辇，与坤仪、同奉瑶卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7869, '夜合花', '曹勋', '星拱尧眉，日临云幄，晓天初静炎曦。\n香凝翠，花笼禁殿风迟。\n彩山高与云齐。\n奉明主、玉交挥。\n庆天申旦，九州四海，同咏昌时。\n今年麦有双歧。\n别有琅并节，深秀联枝。\n丰世瑞物，嘉祥效祉熙熙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7870, '绿头鸭・多丽', '曹勋', '喜雨薰泛景，翠云低柳。\n正凉生殿阁，梅润晓天，暑风时候。\n应乘乾、彩虹流渚，惊电绕、璇霄枢斗。\n大业辉光，益建火德，梯航四海尽奔走。\n六府焕修，多方平定，寰宇歌元首。\n凝九有。\n三辰拱北，万邦孚佑。\n对祥烟、霁色清和，凤韶九成仪昼。\n听山声、响传呼舞，腾紫府、香浓金兽。\n禁升平，慈闱燕适，衣共上玉觞酒。\n齐奉舜图，南山同永，合殿备金奏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7871, '赏松菊', '曹勋', '凉飙应律惊潮韵，晓对彩蟾如水。\n庆霄占梦月，已祥开天地。\n圣主中兴大业，二南化、恭勤辅翊。\n抚宫闱，看仪型，海宇尽成和气。\n禁掖西瑶宴席。\n泛天风、响钧韶空外。\n贵是至尊母，极人间崇贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7872, '瑞鹤仙', '曹勋', '小梅凝秀色，泛霁霭晴和，春容初透。\n璇霄降仙格，觉葱葱佳气，先惊花柳。\n芝兰户牖。\n庆禀质、天长地久。\n有当熊避辇，嘉声懿德，六宫居右。\n清昼。\n文箫仪凤，妙舞低云，缓锵钧奏。\n香传绣幄，腾飞雾，上金兽。\n愿千龄遐算，三宫慈爱，长亭兹辰劝酒。\n向瑶台阆苑，芳音永嫔万寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7873, '水龙吟', '曹勋', '翠帘迟晚，龙楼丽日，海宇明新霁。\n枢旋大电，虹流华渚，阳春天气。\n出震乘乾，保民立政，垂衣裳治。\n诞恩均九有，功兼七制，恢图抚、四荒外。\n威动殊邻万里。\n拥衣冠、称觞玉陛。\n虞韶缓度，龙香飞下，晴云如水。\n行见冰天，版图来上，诸侯盟会。\n奉怡颜宴罢，归移宝辇，向瑶池醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7874, '水龙吟', '曹勋', '嫩凉微袅，秋容乍肃，迥觉凉如水。\n重阳已近，岩华增秀，一钩天际。\n香动前星，气横文圃，荣光呈瑞。\n仰宸心密眷，行都正牧，兵民奉、神明治。\n金殿朝回燕适。\n肆武功、文德咸备。\n萧闲翰墨，惟亲书史，不寻罗绮。\n欢动宸严，宴开鹤禁，生朝和气。\n愿青宫布政，龙楼问寝，同千万岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7875, '水龙吟', '曹勋', '傍阶红药，新梢翠竹，榭阁薰风静。\n维神降岳，维熊占梦，姿仪玉聘。\n金殿趋庭，禁严衣彩，寝门温清。\n是宗藩帝子，天潢宝牒，当神武、侍明廷。\n为善先知最乐，咏诗书、存存成性。\n亲师讲道，华挥藻，水云高兴。\n一代荣观，觊尧显舜，古今难并。\n看青华蕊简，松乔比寿，佐南风政。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7876, '月上海棠慢・月上海棠', '曹勋', '东风扬暖，渐是春半，海棠丽烟径。\n似蜀锦晴展，翠红交映。\n嫩梢万点胭脂，移西溪、浣花真景。\n雨，黄鹂飞上，数声宜听。\n风定。\n朱阑夜悄，蟾华如水，初照清影。\n喜浓芳满地，暗香难并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7877, '松梢月', '曹勋', '院静无声。\n天边正、皓月初上重城。\n群木摇落，松路径暖风轻。\n喜揖蟾华当松顶，照榭阁、细影纵横。\n杖策徐步空明里，但襟袖皆清。\n恍若如临异境，漾凤沼岸阔，波净鱼惊。\n气入层汉，疑有素鹤飞鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7878, '隔帘花', '曹勋', '宿雨初晴，花艳迎阳，槛前如绣如绮。\n向晓峭寒轻，真珠十二。\n正朝曦、桃杏暖，透影帘栊烘春霁。\n似暂隔、祥烟香雾，朝仙侣庭际。\n更值迟迟丽日。\n且休约寻芳，与开瑶席。\n未拟上金钩，尽围红遮翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7879, '东风第一枝', '曹勋', '宝苑明春，青霞射晚，六幕云闲风静。\n茂林修竹昂霄，素月照人澄莹。\n梅花十顷，递暗香、琼瑶真景。\n散万斛金莲，崇山秀岭，尽开花径。\n真个好、月灯相映。\n真个乐、圣驾游幸。\n四部箫韶，群仙奏乐，万光耀境。\n玉华不夜，向洞天、暖烟回冷。\n好大家、酒色醺醺，任教漏移花影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7880, '水龙吟', '曹勋', '鉴天云敛壶中，昼暖乍喜薰风永。\n轻纱渐试，香罗初褪，梅阴又□。\n广殿窗虚，翠帘卷起，一番清影。\n正新篁绿嫩，池光涨雨，鱼吹浪、燕飞径。\n好是九重邃密，有岚光、烟溪深静。\n升平暇日，长廊别院，笙歌缓整。\n宝辇迟留，玉觞时举，何妨乘兴。\n况一年好处，犹寒未暖，是清和景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7881, '夏云峰', '曹勋', '五云开，过夜来、初收几阵梅雨。\n画罗携芳扇，正喜逢重午。\n角黍星团，巧萦臂、龙纹轻缕。\n细祝降福天中，列箫韶歌舞。\n薰风凉殿开处。\n称绡裙雾，莲步俦侣。\n翠铺交枝艾，便手香微度。\n菖丝浮玉，向台榭、留连欢聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7882, '忆吹箫・凤凰台上忆吹箫', '曹勋', '烦暑衣襟，乍凉院宇，梧桐吹下新秋。\n望鹊羽、桥成上汉，绿雾初收。\n喜见西南月吐，帘尽卷、玉宇珠楼。\n银潢晚，应是绛河，已度牵牛。\n何妨翠烟深处，佳丽拥缯筵，斗巧嬉游。\n是向夕、穿针竞立，香霭飞浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7883, '尾犯', '曹勋', '秋空过雨静，晚景澄明，天淡如水。\n渐看蟾彩，东山旋升，金饼上云际。\n轻烟散尽，莹皓色、消尘翳。\n倚琼楼，皎若瑶台阆风，翠阑十二。\n正好登临无外。\n满斟与、清光对。\n虽桂华飘下，玉轮移影，归兴犹未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7884, '秋蕊香', '曹勋', '秋色宫庭，黄花禁，西风乍透罗衣。\n龙山意渐爽，瑶砌叶初飞。\n喜天宇、明洁晓晴时。\n翠楼都卷帘帷。\n奉宴赏，菊英环坐，金玉成围。\n凭阑海山万里，登望处，休论戏马台池。\n揽幽芳、泛酒面香凝，携手与、仙姿共游嬉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7885, '十六贤', '曹勋', '拱皇图，御宝历，上圣垂衣。\n旰食亲万机。\n海宇熙熙。\n登寿域，瑞霞彩云常捧日。\n花阴麦垅四民齐。\n宫卫仗肃，阆苑瑶池。\n台殿倚晴晖。\n当盛际。\n风俗美。\n寻胜事。\n人物总游嬉。\n太平何处，知不摇征旗摇酒旗。\n四方感格臻上瑞。\n官家闲暇宴芳菲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7886, '金盏倒垂莲', '曹勋', '谷雨初晴，对晓霞乍敛，暖风凝露。\n翠云低映，捧花王留住。\n满阑嫩红贵紫，道尽得、韶光分付。\n禁浩荡，天香巧随天步。\n群仙倚春似语。\n遮丽日、更著轻罗深护。\n半开微吐，隐非烟非雾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7887, '庆清朝', '曹勋', '绛罗萦色，茸金丽蕊，秀格压尽群芳。\n人间第一娇妩，深紫轻黄。\n乍过夜来谷雨，盈盈明艳惹天香。\n春风暖，宝幄竞倚，名称花王。\n朝槛五云拥秀，护晓日、偏宜翠幕高张。\n姿露叶，临赏须趁韶光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7888, '花心动', '曹勋', '密幄阴阴，正嘉花嘉木，尽成新翠。\n蕙圃过雨，牡丹初歇，怎见浅深相倚。\n好称花王侍。\n秀层台、重楼明丽。\n九重晓，狂香浩态，暖风轻细。\n堪想诗人赠意。\n喜芳艳卿云，嫩苞金蕊。\n要看秀色，收拾韶华，自做殿春天气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7889, '花心动', '曹勋', '玉井生寒，正枫落吴江，冷侵罗幕。\n翠云翦叶，紫锦攒花，暗香遍熏珠阁。\n瑞非兰麝比，氤氲清彻寥廓。\n向燕寝，团团秀色，巧宜围却。\n宝槛浓开对列，蜂共蝶多情，未知花萼。\n爱玩置向窗几，时时更碾，建春浇著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7890, '杏花天慢', '曹勋', '桃蕊初谢，双燕来後，枝上嫩苞时节。\n绛萼滋浩露，照晓景、裁翦冰绡标格。\n烟传靓质。\n似淡拂、妆成香颊。\n看暖日、催吐繁英，占断上林风月。\n坛边曾见数枝，算应是真仙，故留春色。\n顿觉偏造化，且任他、桃李成蹊谁说。\n晴霁易雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7891, '念奴娇', '曹勋', '禁烟过也，正东风浓拂，来禽奇绝。\n翠叶修条千万点，轻染微红香雪。\n霁景烘云，暖梢吹绽，浩荡春容阔。\n棠阴已静，此花标韵终别。\n犹记宝帖开缄，如何春李，与佳名齐列。\n秀实甘芳莫待看，叶底匀圆堪折。\n且赏琼苞，繁英插鬓，淡伫留风月。\n宜将图画，有时凝想重阅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7892, '风流子', '曹勋', '中春膏雨歇，雕阑晓，最好海棠时。\n正新梢吐绿，万苞凝露，暖铺云锦，香点胭脂。\n向枝上，绪风开秀色，桃李尽成蹊。\n朱唇晕酒，脸红微透，翠纱轻卷，红映丰肌。\n严宸风光主，临赏处，玉殿丽日迟迟。\n天与造化西蜀，浓艳芳菲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7893, '蜀溪春', '曹勋', '蜀景风迟，浣花溪边，谁种芬芳。\n天与蔷薇，露华匀脸，繁蕊竞拂娇黄。\n枝上标韵别，浑不染、铅粉红妆。\n念杜陵、曾见时，也为赋篇章。\n如今盛开禁掖，千万朵莺羽，先借朝阳。\n待得君王，看花明艳，都道赭袍同光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7894, '倚阑人', '曹勋', '清明池馆，芳菲渐晚，晴香满架笼永昼。\n翠拥柔条，玉铺繁蕊，袅袅舞低襟袖。\n秀蓓凝浩露，疑挂六铢衣绉。\n檀点芳心，体薰清馥，粉容宜拈春风手。\n肯与芝兰共嗅。\n向夜阑凝月，洞户花、别是素芳依旧。\n翦取长梢，青蛟喷雪，挽住晓云争秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7895, '夹竹桃花', '曹勋', '绛彩娇春，苍筠静锁，掩映夭姿凝露。\n花腮藏翠，高节穿花遮护。\n重重蕊叶相怜，似青帔艳妆神仙侣。\n正武陵溪暗，淇园晓色，宜望中烟雨。\n向暖景、谁见斜枝处。\n喜上苑韶华渐布。\n又似瑞霞低拥，却恐随风飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7896, '峭寒轻', '曹勋', '照溪流清浅，正万梅都开，峭寒天气。\n才过了元宵，渐昼长禁宇，迤逦佳时。\n断肠枝上雪，残英已、片影初飞。\n苒苒随风，送春到、便烂漫香迟。\n凝睇。\n迎芳菲至。\n觉欣欣桃李，嫩色依微。\n应是有新酸，向嫩梢定须，一点藏枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7897, '竹马子・竹马儿', '曹勋', '喜韶景才回，章台向晓，官柳舒香缕。\n正和烟带雨，遮桃映杏，东君先与。\n乍引柔条萦路。\n娇黄照水，经渭城朝雨。\n翠惹丝垂，玉阑干风静，轻轻搭住。\n到此曾追想，陶潜旧隐，忆隋堤津渡。\n三眠昼永凝露。\n更许黄鹂娇语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7898, '二色莲', '曹勋', '凤沼湛碧，莲影明洁，清泛波面。\n素肌鉴玉，烟脸晕红深浅。\n占得薰风弄色，照醉眼、梅妆相间。\n堤上柳垂轻帐，飞尘尽教遮断。\n重重翠荷净，列向横塘暖。\n争映芳草岸。\n画船未桨，清晓最宜遥看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7899, '八音谐', '曹勋', '芳景到横塘，官柳阴低覆，新过疏雨。\n望处藕花密，映烟汀沙渚。\n波静翠展琉璃，似伫立、飘飘川上女。\n弄晓色，正鲜妆照影，幽香潜度。\n水阁薰风对万姝，共泛泛红绿，闹花深处。\n移棹采初开，嗅金缨留取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7900, '清风满桂楼', '曹勋', '凉飙霁雨。\n万叶吟秋，团团翠深红聚。\n芳桂月中来，应是染、仙禽顶砂匀注。\n晴光助绛色，更都润、丹霄风露。\n连朝看、枝间粟粟，巧裁霞缕。\n烟姿照琼宇。\n上苑移时，根连海山佳处。\n回看碧岩边，薇露过，残黄韵低尘污。\n诗人谩自许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7901, '雁侵云慢', '曹勋', '晓云低。\n是残暑渐消，凉意初至。\n翠帘燕去，觉商飙天气。\n凝华吹、动绣额，乍殿阁、金茎风细。\n夜雨笼微阴，满绮窗、疏影响清吹。\n轻嫩细透衣。\n想宵长漏迟，香动罗袂。\n戏曾计日，忆宾鸿来期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7902, '锦标归', '曹勋', '风搅长空，冷入寒云，正是严凝初至。\n围炉坐久，珠帘卷起，准拟六花飞砌。\n渐苒苒晴烟，更暗觉、远天开霁。\n阻琼瑶、不舞蓝田，但有蟾华铺地。\n想像如今剡溪，应误幽人访客，轻舟闲舣。\n翠幕登临处，散无限清兴，顿孤沈醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7903, '索酒', '曹勋', '乍喜惠风初到，上林翠红，竞开时候。\n四吹花香扑鼻，露裁烟染，天地如绣。\n渐觉南薰，总冰绡纱扇避烦昼。\n共游凉亭消暑，细酌轻讴须酒。\n江枫装锦雁横秋，正皓月莹空，翠阑侵斗。\n况素商霜晓，对径菊、金玉芙蓉争秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7904, '凤箫吟・芳草', '曹勋', '列旗常。\n中宵天净，郊丘展采圆苍。\n肇三岁礼，圣天子为民，致福穰穰。\n凝旒亲奠玉，粲珠联、星斗垂芒。\n渐月转燔柴，露重烟断坛旁。\n欢康。\n青霞催晓，六乐均调，响逐新阳。\n辇回天仗肃，庆千官舞，绣锦成行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7905, '六花飞', '曹勋', '寅杓乍正，瑞云开晓，罩紫府宫殿。\n圣孝虔恭，率宸庭冠剑。\n上徽称、天明地察，奉玉检、璇耀金辉，仰吾君，亲被衮龙，当槛俯旒冕。\n中兴明天子，舜心温，示未尝闲燕。\n礼无前比，出渊衷深念。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7906, '浣溪沙', '曹勋', '禁芙蓉秋气凉。\n新枨启待满林霜。\n旨甘初荐摘青黄。\n乍剖金肤藏嫩玉，吴盐兼味发清香。\n圣心此意与天长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7907, '浣溪沙', '曹勋', '春到皇居景晏温。\n冰轮驾玉上祥云。\n烛龙衔耀九重门。\n宫掖两仪临舜殿，金莲万斛奉尧尊。\n官家慈孝格乾坤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7908, '浣溪沙', '曹勋', '初过西风烟雨微。\n霓光留景正团枝。\n月中新彩与增辉。\n霞影分丹乘浩露，珊瑚秀色满彤墀。\n凉飙吹上赭红衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7909, '浣溪沙', '曹勋', '春晓于飞彩仗明。\n西园嘉瑞格和鸣。\n花王特地献双英。\n并蒂轻黄宜淡淡，联芳竞秀巧盈盈。\n飞琼萼绿两倾城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7910, '临江仙', '曹勋', '连夜阴云开晓景，中秋胜事偏饶。\n十分晴莹碧天高。\n台升吴岫顶，乐振海门潮。\n桂影一庭香渐远，四并都向今朝。\n宸欢得句付风骚。\n围棋消白日，赏月度清宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7911, '临江仙', '曹勋', '嫩绿阴阴台榭映，南风初送清微。\n扬州花市进芳菲。\n丝头开万朵，玉叶衬繁枝。\n自是诗人佳赠意，花王香借馀姿。\n翠红深展奉瑶卮。\n何妨沈醉赏，天与绊春晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7912, '西江月', '曹勋', '霞绮浓披翡翠，晨光巧上珊蝴。\n丹林偏许下清都。\n香占深岩烟雨。\n秋到九华宫殿，赭袍红借繁珠。\n广寒桂与世花殊。\n不带人间风露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7913, '西江月', '曹勋', '连夜六花飞舞，清晨玉境瑶阶。\n湖山寒雾隐楼台。\n难画西园真态。\n月殿九华同到，雕舆乘兴俱来。\n浮春帘密锦筵开。\n不是山阴访戴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7914, '诉衷情', '曹勋', '西都花市锦云同。\n谷雨贡黄封。\n天心故偏雨露，名品满深宫。\n开国艳，正春融。\n露香中。\n绮罗金殿，醉赏浓春，贵紫娇红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7915, '武陵春', '曹勋', '元夕晴和中禁好，梅影玉阑干。\n峭窄春衫试嫩寒。\n金翠会群仙。\n移下一天星斗璨，喜色动宸颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7916, '四槛花', '曹勋', '鸳瓦霜浓，兽炉烟冷，琐窗渐明。\n芙蓉红晕减，疏篁晓风清。\n睡觉犹眠，怯新寒，仍宿酒，尚有馀酲。\n拥闲衾。\n先记早梅糁糁，流水泠泠。\n须记岁月堪惊。\n最难管、苍华满镜生。\n心地常自乐，谁能问枯荣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7917, '花心动', '曹勋', '绿结阴浓，渐南风初到、旧家庭院。\n细麦落花，圆荷浮叶，翠径受风新燕。\n乍晴还雨香罗怯，惜柳絮、已将春远。\n最好处，清和气暖，喜拈轻扇。\n好对层轩邃馆。\n供极目晴云，晓江横练。\n煮酒试尝，梅子团青，草草也休辞劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7918, '胜胜令', '曹勋', '梅风吹粉，柳影摇金。\n渐看春意入芳林。\n波明草嫩，据征鞍，晚烟沈。\n向野馆、愁绪怎禁。\n过了烧灯，醉别院，阻同寻。\n琐窗还是冷瑶琴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7919, '玉蹀躞・解蹀躞', '曹勋', '红绿烟村惨淡，市井初经虏。\n舍馆人家，凄凄但尘土。\n依旧春色撩人，柳花飞处，犹听几声莺语。\n黯无绪。\n匹马三游四楚。\n行路漫怀古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7920, '水龙吟', '曹勋', '海榴红暖。\n圆荷翠小，榭阁薰风浅。\n真人抚运，云龙相际，真贤载诞。\n鲁国元勋，相门接踵，传家非远。\n辅中兴大业，折冲邻壤，扶红日、上霄汉。\n端是清明重见。\n范陶熔、咸收群彦。\n垂绅正笏，炉烟不动，宸廷闲燕。\n天地平成，父尧子舜，永膺宸眷。\n赐我公岁岁，恩荣锡命，向黄金殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7921, '水龙吟', '曹勋', '晓云阁雨。\n疏梅缀玉，麈尾闻谈吐。\n精忠许国，才华锦，尘劳释去。\n六印雄图，百川明辩，苏张谁数。\n有奇谋欲下，阴山族帐，惟英卫、可接武。\n想见临戎丰度。\n慨然定、中原疆土。\n果惊一坐，折冲遐裔，嘉言循古。\n安抚疲民，静摧骄虏，无烦旗鼓。\n看功成、入辅中兴，永佐乾坤主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7922, '宴清都', '曹勋', '野水澄空，远山随眼，笋舆乘兴庐阜。\n天池最极，云溪最隐，翠迷归路。\n三峡两龙翔翥。\n尽半月、犹贪杖屦。\n闲引杯，相赏好处奇处，险处清处。\n凝伫。\n道友重陪，西山胜迹，玉隆风御。\n滕阁下临，晴峰万里，水云千古。\n飞觞且同豪举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7923, '江神子・江城子', '曹勋', '帝俞赓载下方壶。\n雨随车。\n旷时无。\n尽道南丰，仙骨秀而都。\n光照丹丘人快睹，金袅，玉蟾蜍。\n自怜老景病仍癯。\n芘微躯。\n驻安舆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7924, '满庭芳', '曹勋', '白行缠，青巾包结，几年且混常流。\n寰中谁见，心地自清幽。\n雨散顶上，香润遍、琼圃无忧。\n灵芽长，如今寒暑，饥渴总何愁。\n诸公，须著力，尘缘扫尽，师旨坚求。\n看天边、飞金走玉难留。\n住个庵儿不大，争恋得、月馆青楼。\n台山里，从人一任，说个好苏州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7925, '满庭芳', '曹勋', '玉景明心，木鸡修性，要须和会三家。\n未知头面，何处认摩耶。\n自有身中异境，藏巨浪、一点笼纱。\n升沈际，难将赋得，有限逐无涯。\n时时，须点检，随缘遣性，何更兴嗟。\n那浩然独得，迥绝痕瑕。\n妙占熙风惠日，乘正气、三缕明霞。\n真机运，连环放下，无处不光华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7926, '满庭芳', '曹勋', '风搅长空，霜飞平野，冷云常带遥山。\n乱鸦声断，烟霭有无间。\n气与寒威共凛，深绣户、帘幕重关。\n梅枝亚，纤纤秀色，疏影小阑干。\n相携，同好景，窥檐望雪，呵手低鬟。\n笑语里、都言雪意非悭。\n有个红炉暖处，围兽炭、不管宵残。\n从教醉，添香倚玉，门外任清寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7927, '选冠子', '曹勋', '细柳排空，高榆拥岸，乍觉楚天秋意。\n凉随夜雨，望极长淮，孤馆漫成留滞。\n天净无云，浪痕清影，窗户闲临烟水。\n叹驱驰尘事，殊喜萧散，暂来闲适。\n常思念、圣主垂衣，临朝北顾，泛遣聊宽忧寄。\n轩载揽，虎节严持，谈笑挂帆千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7928, '选冠子', '曹勋', '秀木撑空，凝云藏岫，处处群山横翠。\n霜风冽面，酒力潜消，征辔暂指天际。\n红叶黄花，水光山色，常爱晓云晴霁。\n念尘埃眯眼，年华易老，觉远行非易。\n常自感、羽客难寻，蓬莱难到，强作林泉活计。\n鱼依密藻，雁过烟空，家信渐遥千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7929, '定风波', '曹勋', '雪後篱边冷未晴。\n江天浓淡暗还明。\n断续流香传玉蓓。\n心醉。\n临风嗅蕊不胜清。\n映竹幽姿深有思。\n何似。\n照溪真色更多情。\n待得微酸藏傅粉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7930, '祝英台・祝英台近', '曹勋', '晚寒浓，残雪重，春意在何许。\n萼绿仙姿，海上未飞去。\n粲粲玉立丰标，天寒日暮，笑东风、不曾轻付。\n几凝伫。\n闲为写出横斜，无声断肠句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7931, '二郎神', '曹勋', '半阴未雨。\n霁晓寒、轻烟薄暮。\n乍过了挑青，名园深院，把酒偏宜细步。\n满槛梅花，绕堤溪柳，径暖迁莺相语。\n春澹澹，渐觉清明，相傍小桃才吐。\n凝伫。\n山村水馆，难堪羁旅。\n甚觑著花开，频惊屈指，谩写奚奴丽句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7932, '满路花・促拍满路花', '曹勋', '清都山水客，何事入临安。\n珍祠天赐与，半生闲。\n曲池人静，水击赤乌蟠。\n飞上烟岚顶，三缕明霞照晚，时对胎仙。\n圃中有个小庭轩。\n才到便绦然。\n坐来闲看了，篆香残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7933, '木兰花慢', '曹勋', '断虹收霁雨，卷帘幕、与风期。\n正燕子将雏，莺儿弄巧，日影迟迟。\n荼シ。\n牡丹过也，但游丝、上下网晴晖。\n三月韶华，转头易失，密阴匀齐。\n常思。\n入夏景偏奇。\n是梅雨霏微。\n更乍著轻纱，凉摇素羽，翠点清池。\n还思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7934, '念奴娇', '曹勋', '公家世德，建凌烟勋业，中兴长策。\n三十年来，皆帝殊选，金瓯名迹。\n眷倚江南，澄清一道，遴柬惟公得。\n西清严秘，龙头高动奎壁。\n深殿衣惹天香，皇华原野，接萧萧秋色。\n六管均输行奏课，唐室家声皆识。\n老我相逢，萍蓬飘转，晚景俱头白。\n西山南浦，溯风衰泪横臆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7935, '念奴娇', '曹勋', '冰铸雪，赋神情天壤，无伦香泽。\n月女霜娥，直是有如许，清明姿色。\n细玉钗梁，温琼环佩，语好新音发。\n相逢一笑，桂宫连夜寒彻。\n应是第一瑶台，水晶宫殿里，飞升仙列。\n小谪尘寰缘契合，同饮银浆凝结。\n醉里归来，魂清骨醒，乍向层城别。\n晓风吹袂，冷香犹带残月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7936, '念奴娇', '曹勋', '五门照日，是真人膺，炎图家国。\n二百年来，抚四海安乐，六服承德。\n虎旅横江，胡尘眯眼，恨有中原隔。\n宫城缺处，望来消尽金碧。\n征辔暂款神州，期宽北顾，且驰驱朝夕。\n皓彩流天宁忍见，双阙笼秋月色。\n欲饮无，还成长叹，清泪空横臆。\n请缨无路，异时林下犹忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7937, '沁园春', '曹勋', '春点烟红，露新绿，土膏渐香。\n散懒慵情性，寻幽选静，一筇烟雨，几处松篁。\n恨我求闲，已成迟暮，石浅泉甘难屡尝。\n犹堪去，向清风皓月，南涧东冈。\n如今雁断三湘。\n念酒伴、不来梅自芳。\n幸隐居药馆，孙登啸咏，从容云水，无负年光。\n且共山间，琴书朋旧，时饮无何游醉乡。\n归常是，趁前村桑柘，犹挂残阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7938, '沁园春', '曹勋', '五老横峰，二林云衲，自古洞天。\n喷玉龙飞，下三峡水，望香炉暗霭，如起非烟。\n有个真人，拨云峰下，宴坐修真不记年。\n明亭诏，看龙翔凤翥，宸制奎篇。\n君臣际会诚难。\n耸翠阁、频颁宝墨鲜。\n众妙门皆向，微言显启，两朝天德，甘涌神泉。\n道化承平，应稽升举，且向人间寻有缘。\n掀髯笑，做庐山隐逸，大宋神仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7939, '青玉案', '曹勋', '东风冉冉迟芳昼。\n渐黄缀、疏疏柳。\n为惜春来通安否。\n可能相就，径须图醉，莫问伤春瘦。\n陶然共酌新醅酒。\n咏好句、须还凤楼手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7940, '青玉案', '曹勋', '尘埃踏遍长安道。\n念云水、归来好。\n趁得梅花先春到。\n冷云疏雨，暗香寒艳，万玉明清晓。\n青鞋黄帽从渠笑。\n粲十里、冰姿步时绕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7941, '虞美人', '曹勋', '风流贺监栽培好。\n梅最妍姿巧。\n娟娟占得入时妆。\n秀影横斜香并、彩鸳鸯。\n汉皋解佩当时遇。\n绿满经行处。\n如今清梦已惊残。\n赖向君家窗户、得重看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7942, '虞美人', '曹勋', '芙蓉露下闲庭晚。\n犹觉秋容浅。\n惊心莫道岁华赊。\n已有官梅轻放、小春花。\n西风河汉溪流月。\n月下疏疏雪。\n新妆喜是寿阳人。\n鸾鉴不劳呵手、对寒云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7943, '阮郎归', '曹勋', '谁将春信到长安。\n江南腊向残。\n玉妃何事在人间。\n冰肌莹素颜。\n新月上，怯轻寒。\n香心破紫檀。\n数枝斜傍小亭闲。\n黄昏人倚阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7944, '阮郎归', '曹勋', '玉宸赐得水云身。\n初欣不佩绅。\n烟霞一任著衣巾。\n朝中散袒人。\n湖水静，了无尘。\n语兼天上春。\n道人相见肯情亲。\n银钩墨尚新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7945, '菩萨蛮', '曹勋', '乱山影直危楼起。\n天涯目断雕阑倚。\n寂寞过东风。\n行宫烟雨中。\n长安何处日。\n城郭今寒食。\n谁待翠华归。\n片云天际飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7946, '菩萨蛮', '曹勋', '天台不是登长道。\n浑如弱水烟波渺。\n楼上指归程。\n春风无限情。\n石桥书不到。\n雁阵横空杳。\n愁绪比遥峰。\n依依千万重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7947, '菩萨蛮', '曹勋', '琴堂窗户清无暑。\n宫妆争捧黄金注。\n劝我醉秋风。\n难辞两脸红。\n别来三堕叶。\n同是修门客。\n十载叹萍蓬。\n方欣一笑同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7948, '清平乐', '曹勋', '去年春破。\n强半途中过。\n日日篷窗眠了坐。\n饱听吴音楚些。\n今年犹在天涯。\n客情触处思家。\n柳密何人深院，竹疏特地桃花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7949, '清平乐', '曹勋', '风休雨罢。\n三五春寒夜。\n翠额重帘何妨下。\n一炷非兰非麝。\n红莲开遍吴宫。\n华灯小试房栊。\n客里愁须强遣，从来我辈情锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7950, '清平乐', '曹勋', '春前别後。\n常是双眉皱。\n生怕莺声催残漏。\n梦破闲衾堆绣。\n又还玉露金风。\n秋声先到房栊。\n川上不传尺素，云间犹望飞鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7951, '点绛唇', '曹勋', '秋雨弥空，冷侵窗户琴书润。\n四檐成韵。\n孤坐无人问。\n壮志消沈，喜入清闲运。\n常安分。\n炷烟飘尽。\n更拨馀香烬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7952, '点绛唇', '曹勋', '惨惨春阴，画桡寒漾梅风去。\n冷风吹度。\n愁入淮山路。\n歌扇归期，只恐春城暮。\n人何处。\n柳汀烟渚。\n听尽篷窗雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7953, '点绛唇', '曹勋', '晓日浓阴，冷云遮断山无数。\n雁飞筝柱。\n都向愁边去。\n帘影沈沈，一缕芳香度。\n深庭户。\n且寻欢聚。\n雪意还成雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7954, '点绛唇', '曹勋', '昏旦交时，个中已有甘香味。\n咽同真液。\n便觉温温地。\n八一高蟠，光动重楼外。\n但留意。\n自然和气。\n香满水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7955, '浣溪沙', '曹勋', '翠袖携持婉有情。\n湘筠犀轴巧装成。\n声随一苇更分明。\n倚竹双丝明玉细，低眉数曲语莺轻。\n转移新韵几多声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7956, '浣溪沙', '曹勋', '玉柱檀槽立锦筵。\n低眉信手曲初传。\n凤凰飞上四条弦。\n杨柳已吹三叠韵，何须人在九江船。\n夜凉人与月婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7957, '酒泉子', '曹勋', '霜护云低，竹外斜枝初璀璨，仙风吹堕玉钿新。\n度清芬。\n叹寒冰艳了无尘。\n不占纷纷桃李径，一庭疏影冷摇春。\n月黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7958, '酒泉子', '曹勋', '爱景催暄。\n初向晴梢舒玉点，修筠霭霭隔婵娟。\n更清妍。\n东风欲到冷霜天。\n常记孤山残雪路，一枝流水小桥边。\n卧疏烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7959, '酒泉子', '曹勋', '惨惨西风。\n人与两州俱不见，一江残照落霞红。\n橹声中。\n汀花苹草六朝空。\n人向赏心增远恨，闲云犹绕建康宫。\n古今同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7960, '酒泉子', '曹勋', '帘幕闲垂。\n密密围毡红兽暖，有人陌上冷征衣。\n未成归。\n檐间鹊语卜归期。\n应是疑人犹驻马，琐窗日影又还西。\n翠眉低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7961, '朝中措', '曹勋', '一封清诏下金鸾。\n临遣讲邻欢。\n谁问火云挥汗，要看易水摇寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7962, '朝中措', '曹勋', '宝筝偏劝酒杯深。\n歌舞乍沈沈。\n秀指十三弦上，挑吟击玉锵金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7963, '朝中措', '曹勋', '鸣珂揽辔玉霄东。\n持节散陈红。\n子舍已先多士，一鞭同袅春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7964, '西江月', '曹勋', '弦泛龙香细拨，声回花底莺雏。\n低眉信手巧工夫。\n犹带巫烟楚雨。\n人占东风秀色，花笼宝髻真珠。\n锦绦金凤要人扶。\n只恐乘鸾飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7965, '西江月', '曹勋', '春绣东风疑早，映檐翠箔低笼。\n氤氲不是梦云空。\n叶密香翻侵冻。\n折桂广寒手段，移来点检珍丛。\n醉归满载紫云浓。\n抱膝庵中仙种。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7966, '菩萨蛮', '胡铨', '银河牛女年年渡。\n相逢未款还忧去。\n珠斗欲阑干。\n盈盈一水间。\n玉人偷拜月。\n苦恨匆匆别。\n此意愿天怜。\n今宵长似年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7967, '减字木兰花', '胡铨', '渭阳佳梦。\n瓦变成璋真妙弄。\n不是勾回。\n汤饼冤家唤得来。\n不分利市。\n要我开尊真倒置。\n试问坡翁。\n此事如何著得侬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7968, '醉落魄・一斛珠', '胡铨', '百年强半。\n高秋犹在天南畔。\n幽怀已被黄花乱。\n更恨银蟾，故向愁人满。\n招呼诗酒颠狂伴。\n羽觞到手判无算。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7969, '醉落魄・一斛珠', '胡铨', '千岩竞秀。\n西湖好是春时候。\n谁知梅雪飘零久。\n藏白收香，空袖和羹手。\n天涯万里情难逗。\n眉峰岂为伤春皱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7970, '鹧鸪天', '胡铨', '梦绕松江属玉飞。\n秋风莼美更鲈肥。\n不因入海求诗句，万里投荒亦岂宜。\n青箬笠，绿荷衣。\n斜风细雨也须归。\n崖州险似风波海，海里风波有定时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7971, '鹧鸪天', '胡铨', '一忆西湖太瘦生。\n十年不到梦曾行。\n空山色烟霏晚，淡沲湖光雾轻。\n芳草远，暮云平。\n雨馀空翠入帘明。\n梦回一饷难存济，这错都因自打成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7972, '朝中措', '胡铨', '崖州何有水连空。\n人在浪花中。\n月屿一声横竹，云帆万里雄风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7973, '采桑子', '胡铨', '山浮海上青螺远，决眦归鸿。\n闲倚东风。\n叠叠层云欲荡胸。\n弄琴细写清江引，一洗愁容。\n木杪黄封。\n贤圣都堪日日中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7974, '临江仙', '胡铨', '我与梅花真莫逆，别来长恐因循。\n几年不见岭头春。\n栩然蝴蝶梦，魂梦竟非真。\n浪蕊浮花空满眼，愁眉不展长颦。\n此君还似不羁人。\n月边风畔，千里淡相亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7975, '如梦令', '胡铨', '谁念新州人老。\n几度斜阳芳草。\n眼雨欲晴时，梅雨故来相恼。\n休恼。\n休恼。\n今岁荔枝能好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7976, '玉楼春', '胡铨', '十年目断鲸波阔。\n万里相逢歌怨咽。\n髻鬟春雾翠微重，眉黛秋山烟雨抹。\n小槽旋滴真珠滑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7977, '清平乐', '胡铨', '深深花院。\n雨虐风饕遍。\n只欠画屏并羽扇。\n谁领略春风面。\n愁须诗酒相禁。\n少陵底事慵吟。\n不是为梅牵兴，怕渠恼乱春心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7978, '青玉案', '胡铨', '宜霜开尽秋光老。\n感节物、愁多少。\n尘事难逢开口笑。\n满林风雨，一江烟水，飒爽惊吹帽。\n玉堂金马何须道。\n且斗取、尊前玉山倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7979, '好事近', '胡铨', '富贵本无心，何事故乡轻别。\n空使猿惊鹤怨，误薜萝风月。\n囊锥刚要出头来，不道甚时节。\n欲驾巾车归去，有豺狼当辙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7980, '“僮至”念奴娇', '俞处', '残蝉断雁，政西风萧索，夕阳流水。\n落木无边幽眺处，云拥登山屐齿。\n岁月如驰，古今同梦，惟有悲欢异。\n绿尊空对，故人相望千里。\n追念淮海当年，五云行殿，咫尺天颜喜。\n清晓胪传仙仗里，衣染玉龙香细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7981, '小重山', '岳飞', '昨夜寒蛩不住鸣。\n惊回千里梦，已三更。\n起来独自绕阶行。\n人悄悄，帘外月胧明。\n白首为功名。\n旧山松竹老，阻归程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7982, '满江红', '岳飞', '怒发冲冠，凭阑处、潇潇雨歇。\n抬望眼、仰天长啸，壮怀激烈。\n三十功名尘与土，八千里路云和月。\n莫等闲、白了少年头，空悲切。\n靖康耻，犹未雪。\n臣子恨，何时灭。\n驾长车踏破，贺兰山缺。\n壮志饥餐胡虏肉，笑谈渴饮匈奴血。\n待从头、收拾旧山河，朝天阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7983, '满江红', '岳飞', '遥望中原，荒烟外、许多城郭。\n想当年、花遮柳护，凤楼龙阁。\n万岁山前珠翠绕，蓬壶殿里笙歌作。\n到而今、铁骑满郊畿，风尘恶。\n兵安在，膏锋锷。\n民安在，填沟壑。\n叹江山如故，千村寥落。\n何日请缨提锐旅，一鞭直渡清河洛。\n却归来、再续汉阳游，骑黄鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7984, '满庭芳', '邵缉', '落日旌旗，清霜剑戟，塞角声唤严更。\n论兵慷慨，齿颊带风生。\n坐拥貔貅十万，衔枚勇、云槊交横。\n笑谈顷，匈奴授首，千里静枪。\n荆襄，人按堵，提壶劝酒，布谷催耕。\n芝夫荛子，歌舞威名。\n好是轻裘缓带，驱营阵、绝漠横行。\n功谁纪，风神宛转，麟阁画丹青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7985, '水调歌头', '吴芾', '九月二十六，公相纪生辰。\n橙黄橘绿时候，天气暖於春。\n奎画有堂辉焕，中著台星一点，长伴寿星明。\n衮衮有家庆，未羡古徐卿。\n谢元枢，营绿野，避洪名。\n六年裁国事，曾费几精神。\n歇了傅岩霖雨，闲了孤舟野渡，旒冕合知心。\n吾道苟尊尚，元不在蒲轮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7986, '滴滴金', '孙道绚', '月光飞入林前屋。\n风策策，度庭竹。\n夜半江城击柝声，动寒梢栖宿。\n等闲老去年华促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7987, '醉蓬莱', '孙道绚', '看鸥翻波溅，苹末风轻，水轩消暑。\n云叠奇峰，破桐阴亭午。\n列岫连环，溜泉鸣玉，对幅巾芒履。\n况有清时，风流故人，剧谈挥麈。\n才冠一时，论高两汉，书扇豪踪，吐凤辞语。\n昼锦归来，庆长年老母。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7988, '菩萨蛮', '孙道绚', '栏干六曲天围碧。\n松风亭下梅初白。\n腊尽见春回。\n寒梢花又开。\n曲琼闲不卷。\n沈燎看星转。\n凝伫小徘徊。\n云间征雁来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7989, '少年游', '孙道绚', '雨晴云敛，烟花澹荡，遥山凝碧。\n驱车问征路，赏春风南陌。\n正雨後、梨花幽艳白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7990, '忆秦娥', '孙道绚', '秋寂寞。\n秋风夜雨伤离索。\n伤离索。\n老怀无奈，泪珠零落。\n故人一去无期约。\n迟书忽寄西飞鹤。\n西飞鹤。\n故人何在，水村山郭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7991, '醉思仙', '孙道绚', '晚霞红。\n看山迷暮霭，烟暗孤松。\n动翩翩风袂，轻若惊鸿。\n心似鉴，鬓如云，弄清影，月明中。\n谩悲凉，岁冉冉，华潜改衰容。\n前事销凝久，十年光景匆匆。\n念云轩一梦，回首春空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7992, '如梦令', '孙道绚', '翠柏红蕉影乱。\n月上朱栏一半。\n风自碧空来，吹落歌珠一串。\n不见。\n不见。\n人被绣帘遮断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7993, '清平乐', '孙道绚', '悠悠扬扬。\n做尽轻模样。\n半夜萧萧窗外响。\n多在梅边竹上。\n朱楼向晓帘开。\n六花片片飞来。\n无奈熏炉烟雾，腾腾扶上金钗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7994, '临江仙', '何蓑衣道人', '在世为仙须有分，不须素食持斋。\n寸丝不著挂形骸。\n蓑衣为伴侣，箬笠作家怀。\n行满三千上界，奉敕宣至金台。\n传言问汝有何哉。\n人生长富贵，阴骘种将来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7995, '夜游宫', '陆凝之', '东风捏就腰儿细。\n系滴粉裙儿不起。\n从来只惯掌中看，怎忍在、烛花影里。\n酒红应是铅华褪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7996, '念奴娇', '陆凝之', '远山一带，溯晴空、极目天涯浮白。\n枫落鸦翻谈笑处，不觉云涛横席。\n酒病方苏，睡魔犹，一扫无留迹。\n吴帆越棹，恍然飞上空碧。\n长记草赋梁园，凌云笔势，倒三江秋色。\n对此惊心空怅望，老作红尘闲客。\n别浦烟平，小楼人散，回首千波寂。\n西风归路，为君重喷霜笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7997, '采莲延遍・采莲令', '史浩', '霞霄上，有寿乡广袤无际。\n东极沧海，缥缈虚无，蓬莱弱水。\n风生屋浪，鼓楫扬，不许凡人得至。\n甚幽邃。\n试右望金枢外。\n西母楼阁，玉阙瑶池。\n万顷琉璃。\n双成倩巧，方朔诙谐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7998, '采莲　遍・采莲令', '史浩', '南邻幄丹宫，赤伏显符记。\n朱陵曜绮绣，箕翼炯、瑞光腾起。\n每岁秋分老人见，表皇家、袭庆迎祺。\n天子当膺，无疆万岁。\n北窥玄冥，魁杓拥佳气。\n长拱极、终古无移。\n论南北东西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (7999, '采莲入破・采莲令', '史浩', '璇穹层云上覆，光景如梭逝。\n惟此过隙缓征辔。\n垂象森列昭回。\n碧落卓然躔度，炳曜更腾辉。\n永永清光晔炜。\n绵四野、金璧为地。\n蕊珠馆，琼玖室，俱高峙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8000, '采莲衮遍・采莲令', '史浩', '遍此境，人乐康，挟难老术，悟长生理。\n尽阿僧祗劫，赤松王令安期。\n彭盛矣。\n尚为婴稚。\n鹤算龟龄，绛老休夸甲子。\n鲐背耸、黄发垂髻。\n更童颜，长鼓腹、同游戏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8001, '采莲实催・采莲令', '史浩', '露华霞液，云桨椒醑，姿玉金。\n交酬成雅会。\n拚沈醉。\n中山千日，未为长久，今此陶陶一饮，动经万祀。\n陈果，皆是奇异。\n似瓜如斗尽备。\n三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8002, '采莲衮　・采莲令', '史浩', '有珍馔，时时馈。\n滑甘丰腻。\n紫芝荧煌，嫩菊秀媚。\n贮玛瑙琥珀精器。\n延年益寿莫拟。\n人间烹饪徒费。\n休说龙肝凤髓。\n动妙乐、仙音鼎沸。\n玉箫清，瑶瑟美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8003, '采莲歇拍・采莲令', '史浩', '其间有洞天侣，思游尘世。\n珠葆摇曳。\n华表真人，清江使者，相从密议。\n此老遨嬉。\n我辈应须随侍。\n正举步、忽思同类。\n十八公、方耸壑，宜邀致。\n夙驾星言，人争图绘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8004, '采莲煞衮・采莲令', '史浩', '吾皇喜。\n光宠无贰。\n玉带金鱼荣贵。\n或者疑之。\n岂识圣明，曾主斯乡，尝相与尽缱绻，胶漆何可相离。\n今日风云合契。\n此实天意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8005, '采莲舞', '史浩', '练光浮，烟敛澄波渺。\n燕脂湿、靓妆初了。\n绿云伞上露滚滚，的真珠小。\n笼娇媚、轻盈伫眺。\n无言不见仙娥，凝望蓬岛。\n玉阙葱葱，镇锁佳丽春难老。\n银潢急、星槎飞到。\n暂离金砌，为爱此、极目香红绕。\n倚兰棹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8006, '采莲舞', '史浩', '蕊沼清冷涓滴水。\n迢迢烟浪三千里。\n微孕青房包绣绮。\n薰风里。\n幽芳洗尽闲桃李。\n羽氅飘萧尘外侣。\n相呼短棹轻偎倚。\n一片清歌天际起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8007, '采莲舞', '史浩', '翠盖参差森玉柄。\n迎风露香无定。\n不著尘沙真体净。\n芦花径。\n酒侵酥脸霞相映。\n棹拨木兰烟水暝。\n月华如练秋空静。\n一曲悠扬沙鹭听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8008, '采莲舞', '史浩', '草软沙平风掠岸。\n青蓑一钓烟江畔。\n荷叶为花作幔。\n知谁伴。\n醇醪只把鲈鱼换。\n盘缕银丝杯自暖。\n篷窗醉著无人唤。\n逗得醒来横脆管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8009, '采莲舞', '史浩', '太华峰头冰玉沼。\n开花十丈干云杪。\n风散天香闻四表。\n知多少。\n亭亭碧叶何曾老。\n试问霏烟登鸟道。\n丹崖步步祥光绕。\n折得一枝归月峤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8010, '采莲舞', '史浩', '珠露清玉宇。\n霞标绰约消烦暑。\n时驭清风之帝所。\n寻旧侣。\n三千仙仗临烟渚。\n舴艋飘摇来复去。\n渔翁问我居何处。\n笑把红蕖呼鹤驭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8011, '采莲舞', '史浩', '彤霞出水弄幽姿。\n娉婷玉面相宜。\n棹歌先得一枝枝。\n波上画鲸飞。\n向此画堂高会，幽馥散、堪引瑶卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8012, '采莲舞', '史浩', '蕊宫阆苑。\n听钧天帝乐，知他几遍。\n争似人间，一曲采莲新传。\n柳腰轻，莺舌啭。\n逍遥烟浪谁羁绊。\n无奈天阶，早已催班转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8013, '太清舞', '史浩', '武陵自古神仙府。\n有渔人迷路。\n洞户迸寒泉，泛桃花容与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8014, '太清舞', '史浩', '须臾却有人相顾。\n把肴桨来聚。\n礼数既雍容，更衣冠淳古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8015, '太清舞', '史浩', '当时脱得长城苦。\n但熙熙朝暮。\n上帝锡长生，任跳丸乌兔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8016, '太清舞', '史浩', '渔舟之子来何所。\n尽相猜相语。\n夜宿玉堂空，见火轮飞舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8017, '太清舞', '史浩', '我今来访烟霞侣。\n沸华堂箫鼓。\n疑是奏钧天，宴瑶池金母。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8018, '太清舞', '史浩', '云羽仙风举。\n指丹霄烟雾。\n行作玉京朝，趁两班鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8019, '太清舞', '史浩', '游尘世、到仙乡。\n喜君王。\n跻治虞唐。\n文德格遐荒。\n四裔尽来王。\n干戈偃息岁丰穰。\n三万里农桑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8020, '柘枝舞', '史浩', '□人奉圣□□朝□□□□主□□□□□留伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8021, '柘枝舞', '史浩', '我是柘枝娇女。\n□□多风措。\n□□□、□住深□，妙学得柘枝舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8022, '柘枝舞', '史浩', '回头却望尘寰去。\n喧画堂箫鼓。\n整云鬟、摇曳青绡，爱一曲柘枝舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8023, '花舞', '史浩', '贵客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8024, '花舞', '史浩', '嘉客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8025, '花舞', '史浩', '素客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8026, '花舞', '史浩', '幽客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8027, '花舞', '史浩', '野客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8028, '花舞', '史浩', '雅客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8029, '花舞', '史浩', '净客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8030, '花舞', '史浩', '仙客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8031, '花舞', '史浩', '寿客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8032, '花舞', '史浩', '清客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8033, '花舞', '史浩', '近客之名从此有。\n多谢风流，飞驭陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8034, '花舞', '史浩', '算仙家，真巧数，能使众芳长绣组。\n羽芝葆，曾到世间，谁共凡花为伍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8035, '花舞', '史浩', '对芳辰，成良聚，珠服龙妆环宴俎。\n我御清风，来此纵观，还须折枝归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8036, '花舞', '史浩', '叹尘寰，乌兔走，花谢花开能几许。\n十分春色，一半遣愁，那堪飘零风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8037, '花舞', '史浩', '是非场，名利海，得丧炎凉徒自苦。\n至乐陶陶，唯有醉乡，谁向此间知趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8038, '剑舞', '史浩', '荧荧巨阙。\n左右凝霜雪。\n且向玉阶掀舞，终当有、用时节。\n唱彻。\n人尽说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8039, '渔夫舞', '史浩', '细雨斜风都不管。\n柔蓝软绿烟堤畔。\n鸥鹭忘机为主伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8040, '渔夫舞', '史浩', '好景侬家披得去。\n前村雪屋云深处。\n一棹清歌归晚浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8041, '渔夫舞', '史浩', '济涉还渠渔父子。\n生涯只在烟波里。\n练静忽然风又起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8042, '渔夫舞', '史浩', '万斛黄金迷俯仰。\n轻不碍飞双桨。\n光透碧霄千万丈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8043, '渔夫舞', '史浩', '已见白鱼翻翠荇。\n任公一掷波千顷。\n不是六鳌休便领。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8044, '渔夫舞', '史浩', '一引修鳞吾事了。\n棹船归去歌声杳。\n门俯清湾山更好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8045, '渔夫舞', '史浩', '试倩霜刀登玉缕。\n银鳞不忍供盘俎。\n掷向清波方圉圉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8046, '渔夫舞', '史浩', '莫惜清尊长在手。\n圣朝化洽民康阜。\n说与渔家知得否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8047, '望海潮', '史浩', '烟笼香径，霞舒花砌，东君绣出芳辰。\n蝶羽弄轻，鸾声啭巧，嬉嬉舞态歌唇。\n纶制出严宸。\n曳耀春品服，荣锡绯银。\n向此华涂要路，颜色倍精神。\n珠帘碧方新。\n有兰堂快目，水榭通津。\n玉蘸清，金虬蔼翠，轮蹄尽集簪绅。\n偕老指双椿。\n望武林咫尺，同上青云。\n异日重为此会，应羡凤池人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8048, '望海潮', '史浩', '烟浓柳径，霞蒸花砌，春深特地芳辰。\n蝶侣斗狂，莺雏弄巧，嬉嬉舞态歌唇。\n西铺集簪绅。\n正桂薰兰玉，天寿松椿。\n竞捧瑶觥潋滟，来祝纵怀人。\n当年辍侍严宸。\n有星轺问俗，熊轼临民。\n康阜政成，蕃宣治美，归休燕处申申。\n行庆紫泥新。\n起钓璜国老，东海之滨。\n屈指重开此宴，应已拜平津。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8049, '望海潮', '史浩', '熊罴嘉梦，风云享会，溪应卜之年。\n黄菊萃英，红萸酿馥，安排预赏芳筵。\n环佩拥神仙。\n向粉额两字，金缕红鲜。\n最好花展处，双凤舞翩翩。\n人人竞擘香笺。\n璨珠玑溢目，祝颂无边。\n彭祖一分，庄椿十倍，千秋未足多言。\n日驭且停鞭。\n把燕闲欢乐，分付壶天。\n笑享亲朋岁岁，春酒庆团圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8050, '感皇恩', '史浩', '健卒走红尘，芝封飞到。\n金缕斜斜印三道。\n舞鸾翔凤，犹带御炉烟袅。\n茜衣新象笏，银章好。\n对此况当，莺花缭绕。\n画栋映蓬岛。\n绣帘初卷，共指松椿偕老。\n浩歌拚烂醉，金尊倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8051, '感皇恩', '史浩', '风雨揽元宵，收灯方了。\n深院红莲尚围绕。\n德星同聚，更有祥光临照。\n始知真洞府，春长好。\n应是化工，偏怜衰老。\n剩把青藜作荣耀。\n正须沈醉，拚却玉山频倒。\n寄声更漏子，休催晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8052, '满庭芳', '史浩', '烘锦花堤，铺绵柳巷，晓来膏雨初晴。\n画堂初建，碧沼映朱楹。\n最好芙蓉绣褥，交辉敞、孔雀金屏。\n那堪更，华裾满坐，和气动欢声。\n冰清。\n真美行，棠阴善政，槐市高名。\n今朝消受得，茜服光荣。\n况是齐眉并寿，谁云道、乐事难并。\n相将见，飞凫过阙，除目下彤庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8053, '满庭芳', '史浩', '爱日轻融，阴云初敛，一番雪意阑珊。\n柳摇金缕，梅绽五腮寒。\n知是东皇翠葆，飞星汉、来止人间。\n开新宴，笙歌逗晓，和气满城寰。\n风光，偏舜水，贤侯政美，棠荫多欢。\n更圜扉草鞠，木索长闲。\n休向今朝惜醉，红妆映、群玉颓山。\n相将见，宜春帖子，清夜写金銮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8054, '满庭芳', '史浩', '微霰疏飘，骄云轻簇，短檠暗淡笼纱。\n冷禁兰帐，清晓忽飞花。\n已是平芜步阔，那堪更、折竹如蓑。\n凭栏处，关心一叶，归兴渺无涯。\n为瑞，已多少，适从狼子，来自龙沙。\n赖吾皇神武，薄海为家。\n尽扫腥风杀气，依然放、红日光华。\n回头看，山蹊水坞，缟带不随车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8055, '满庭芳', '史浩', '鲸海波澄，棠阴日永，正宜坐啸雍容。\n岁丰民乐，无讼到庭中。\n试数循良自古，龚黄外、谁可追踪。\n那堪更，恩均髦寿，良会此宵同。\n璇穹。\n占瑞处，荧煌五马，璀璨群公。\n盛笙歌落绮，共引髯翁。\n祗恐芝泥趣召，双旌展、猎猎飞红。\n须知道，君王渴见，名久在屏风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8056, '满庭芳', '史浩', '十载江湖，一朝簪组，宠荣曷称衰容。\n圣恩不许，归卧旧庐中。\n慨念东山伴侣，烟霞外、久阔仙踪。\n今何幸，相逢故里，谈笑一尊同。\n吾州，真幸会，湖边贺监，海上黄公。\n胜渭川遗老，绛县仙翁。\n纵饮何辞烂醉，脸霞转、一笑生红。\n从今後，婆娑化国，千岁乐皇风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8057, '满庭芳', '史浩', '油幕初开，旄前导，暂归梓里舂容。\n致身槐揆，功在鼎彝中。\n自是襟怀绝俗，今犹记、笔砚陈踪。\n张高会，君恩厚赐，乐与故人同。\n把麾，鄞水上，相看青眼，谁复如公。\n况亲陪尊俎，笑接群翁。\n坐上笙歌屡合，须拚到、晓日酣红。\n公今去，恩波四海，桃李尽东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8058, '满庭芳', '史浩', '玉阙朝回，沙堤烟晓，碧幢光动军容。\n虎符熊轼，行指七闽中。\n假道吾乡我里，挥金事、思蹑前踪。\n倾怀处，萤窗雪案，犹说昔年同。\n相看，俱老大，襟期道义，不为王公。\n念儿时聚戏，今已成翁。\n敢借玉壶美酒，还为寿、金盏翻红。\n仍频祝，中书二纪，寰海振淳风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8059, '满庭芳', '史浩', '复拥旌麾，重歌褥裤，满城长自春容。\n绅耆旧，欢溢笑谈中。\n尽道邦君恺悌，逍遥遂、湖海遐踪。\n今朝会，公真乐善，屈意与人同。\n恩勤，东道主，挥金汉傅，怀绶朱公。\n引群仙环拱，欲寿吾翁。\n春瓮初澄盎绿，春衫更、轻染香红。\n持杯愿，归登绛阙，花萼醉春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8060, '满庭芳', '史浩', '鹤冷风亭，鸿迷烟渚，晓来雪意填空。\n酿成佳瑞，端为兆年丰。\n况有神娲妙手，调和得、云彩皆同。\n楼台上，铺琼缀玉，随步广寒宫。\n天公。\n开地轴，八混一，莫辨堤封。\n又须教、归禽狡兽沈踪。\n坐见花敷万木，谁知道、春已输工。\n三杯酒，西湖父老，相与话时雍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8061, '庆清朝', '史浩', '翠竹茎疏，碧溪流浅，绮窗为尔时开。\n依稀远岸，才见一点寒梅。\n冷定半疑是雪，因风还度暗香来。\n醉清兴，瘦策过桥，黄帽青鞋。\n繁枝正微雨後，似怨人知晚，泪冰腮。\n殷勤百绕，留连踏遍莓苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8062, '蓦山溪', '史浩', '清淡无限，林下逢人少。\n骑马踏红尘，恁区区、何时是了。\n名场利海，毕竟白头翁，山簇翠，水拖蓝，只个生涯好。\n君侯洒落，卜筑开冰沼。\n三径直危楼，遍岩隈、幽花香草。\n风勾月引，馀事作诗人，词歌雪，气凌云，寒瘦伦郊岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8063, '青玉案', '史浩', '玉姬曾向瑶池舞。\n轻掷霓裳忤王母。\n从此烟消飞鹤驭。\n一来人世，有缘相遇，得得为鸳侣。\n年年此际霞觞举。\n彩笔香笺染新句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8064, '青玉案', '史浩', '涌金斜转青云路。\n溯衮衮、红尘去。\n春色勾牵知几度。\n月帘风幌，有人应在，唾线馀香处。\n年来不梦巫山暮。\n但苦忆、江南断肠句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8065, '青玉案', '史浩', '年来减却风情大。\n百样收心待不作。\n恰恨仙翁停画舸。\n雪中把酒，美人频为，浅破樱桃颗。\n清歌谁许阳春和。\n悄不放、遥空片云过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8066, '西江月', '史浩', '红蓼千堤挺蕊，苍梧一叶辞柯。\n夜阑清露泻银河。\n洗出芙蓉半朵。\n解带初开粉面，绕梁还听珠歌。\n心期端的在秋波。\n想得今宵只我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8067, '喜迁莺', '史浩', '凤阙朱旗展，弄罢五弦，南薰敲竹。\n雨糁桃蹊，钱浮荷沼，一瞬染成新绿。\n玉皇香案吏，曾是时、鹤飞江国。\n对此际，每丹霄效瑞，非烟郁郁。\n卜筑。\n陶山曲，风榭月台，图画应难足。\n绿绮春浓，青蛇星烂，肯便稳栖烟麓。\n玳筵称寿，清皓齿、霏霏珠玉。\n竞屈指，看芝封紫检，鸣驺入谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8068, '喜迁莺', '史浩', '征鸿回北。\n正雪洗烧痕，千岩匀绿。\n鱼纵新漪，梅繁断岸，春到鉴湖一曲。\n满城绣帘珠幌，暖响聒天丝竹。\n渐向晚，放芙蕖千顷，交辉华烛。\n贤牧。\n棠阴静，康阜政成，褒诏来黄屋。\n玉笋光寒，紫荷香润，人道此装须趣。\n且出催花银漏，恣饮宝觥。\n向明岁，看传柑归去，腰横金粟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8069, '喜迁莺', '史浩', '才过元夕。\n送宴赏未阑，欢娱无极。\n且莫收灯，仍休止酒，留取凤笙龙笛。\n金马玉堂学士，当此同开华席。\n最堪爱，是兰膏光在，金连壁。\n难觅。\n交欢处，杯吸百川，雅量皆敌。\n老子衰迟，居然怀感，厚意怎生酬得。\n况已倦游客路，一志归安泉石。\n但屈指，愿诸贤衮绣，联飞鹏翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8070, '喜迁莺', '史浩', '谯门残月。\n正画角晓寒，梅花吹彻。\n瑞日烘云，和风解冻，青帝乍临东阙。\n暖响土牛箫鼓，夹路珠帘高揭。\n最好是，看彩幡金胜，钗头双结。\n奇绝。\n开宴处，珠履玳簪，俎豆争罗列。\n舞袖翩翻，歌声缥缈，压倒柳腰莺舌。\n劝我应时纳祜，还把金炉香。\n愿岁岁，这一卮春酒，长陪佳节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8071, '喜迁莺', '史浩', '雪消春浅。\n听爆竹送穷，椒花待旦，系马合簪，鸣鸦列炬，几处玳筵开宴。\n介我百千眉寿，齐捧玉壶金盏。\n最奇绝，是小桃新坼，争妍粉面。\n女伴。\n频告语，守岁通宵，莫放笙歌散。\n酒晕朝霞，寒欺重翠，却忆凤屏香暖。\n笑拂满身花影，遥指珠帘深院。\n待到了，道一声稳睡，明年相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8072, '喜迁莺', '史浩', '凭高寓目。\n爱屹起四窗，云南云北。\n缥缈烟霞，萧森松竹，多少洞天岩谷。\n著向十洲三岛，入海何妨登陆。\n要知处，在皇家新赐，西湖一曲。\n林麓。\n真胜概，樊榭鹿亭，百卉生幽馥。\n绿绮春浓，青蛇星烂，隔断世间尘俗。\n笑呼羡门俦侣，时引宝觞。\n醉和醒，但南山之寿，难忘勤祝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8073, '点绛唇', '史浩', '我为劳生，自怜浪迹天涯遍。\n如今春换。\n又是孤萍断。\n谁信年时，老子情非浅。\n思量见。\n画楼天远。\n花倚夕阳院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8074, '点绛唇', '史浩', '千里欢谣，使君美政高三辅。\n沸天箫鼓。\n笑拥锋车去。\n卧辙攀辕，漫拟双旌住。\n还知否。\n禁林深处。\n已辟金闺路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8075, '点绛唇', '史浩', '翠幄园林，火云方绽南薰起。\n玉轮天外。\n夜色凉如水。\n况有清歌，劝我尊浮蚁。\n拚沈醉。\n万花丛里。\n一枕朦胧睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8076, '点绛唇', '史浩', '曾到蟾宫，玉轮乞得长随手。\n数声轻叩。\n已有锵琼玖。\n最好长清，浑不惊秋候。\n歌阑後。\n那回辞酒。\n笑把遮檀口。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8077, '木兰花慢', '史浩', '喜阳和应律，启佳气、满寰瀛。\n正雪洗疏梅，云浮淡月，昨夜生明。\n熊罴信占梦好，当年相阀再蟠英。\n收拾仙风道韵，萃兹一点台星。\n功名。\n壮岁逢真。\n主紫橐、耀西清。\n向玉笋光中，瑶林宴里，来拥双旌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8078, '临江仙', '史浩', '衮绣蝉联三重客，朝回晓日。\n绿杨门巷拥花骢。\n喜承天上语，来作主人公。\n况值瑶林风露爽，冰轮碾上晴空。\n桂香和影堕金锺。\n莫辞通夕醉，明日是秋中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8079, '临江仙', '史浩', '槛竹敲风初破睡，楚台梦雨精神。\n背屏斜映小腰身。\n山明双翦水，香满一钗云。\n炉袅金丝帘地，绮窗秋静无尘。\n半钩春笋带湘筠。\n兰亭初写就，愁杀卫夫人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8080, '临江仙', '史浩', '绣幕罗裙风冉冉，象床毡幄低垂。\n兽炉香袅锦屏围。\n不贪钿枕，偏爱倚花枝。\n软玉红绡轻暖透，温温翠袖扶持。\n正安稳坐移时。\n雨云忘峡梦，身境是瑶池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8081, '鹧鸪天', '史浩', '画角梅花曲未终。\n霜严飞落五更风。\n谁知林外鸡三唱，推出红轮海上峰。\n官一品，禄千锺。\n此时分付荷重瞳。\n更教赐子云南境，绝胜湖边九里松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8082, '鹧鸪天', '史浩', '我本飘然出岫云。\n挂冠归去岸纶巾。\n但教名利休缰锁，心地何时不是春。\n竹叶美，菊花新。\n百杯且听绕梁尘。\n故乡父老应相贺，林下方今见一人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8083, '鹧鸪天', '史浩', '孔雀双飞敞画屏。\n锦花茵上舞娉婷。\n红绡袖暖琉璃滑，金鸭炉香椒桂馨。\n丹脸渥，秀眉青。\n平生阴德在遐龄。\n如今便好添龟鹤，元是南箕一寿星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8084, '鹧鸪天', '史浩', '晓日花露稀。\n明光已报敞金扉。\n三千彩仗翔鸾舞，数百银袍振鹭飞。\n开雉扇，正垂衣。\n奏篇初得上彤墀。\n胪传绕殿天颜喜，先折东风第一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8085, '蝶恋花', '史浩', '桂影团团光正满。\n更似菱花，齐把匀娇面。\n非镜非蟾君细看。\n元来却是吴姬扇。\n一曲阳春犹未遍。\n惊落梁尘，不数莺喉啭。\n好著红绡笼玉腕。\n轻敲引入笙歌院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8086, '宝鼎现', '史浩', '霞霄丹阙，瑞霭佳气，青葱如绮。\n才半月、东君雨露，无限韶华生宝砌。\n渐向晚、放烛龙掀舞，周币红蕖绀蕊。\n况对峙、鳌峰，不隔蓬莱弱水。\n圣主有乐升平意。\n引芝华、双辇凝翠。\n纷万俗、歌谣弦管，声混莺吟喧凤吹。\n更漏永、正冰轮掩映，光接康衢万里。\n似移下、一天星斗，妆点都城表里。\n清警跸、忽登楼，簇彩仗、锦襦丝履。\n看柑传万颗，恩浃王公近侍。\n散异卉覆千官醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8087, '最高楼', '史浩', '当年尚父，一个便兴周。\n今十倍，更何忧。\n冲融道貌丹为脸，扶疏漆发黑盈头。\n世方知，非熊老，聚吾州。\n有智略、可从兹日用，有志愿、可从兹日酬。\n天付我，怎教休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8088, '明月逐人来', '史浩', '莫嫌春浅。\n寒威俱敛。\n阳和至此时方见。\n木君敷令，把雪霜扫断。\n要集德星胜伴。\n为有仙翁，正尔名喧蕃汉。\n眉寿比、聃彭更远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8089, '踏莎行', '史浩', '歌舌莺娇，舞腰蜂细。\n华堂是处皆颐指。\n四弦独擅席中春，移船出塞声能继。\n慢拈幽情，轻拢柔思。\n其中有口传心事。\n主人灯火下楼时，偏渠领略深深意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8090, '生查子', '史浩', '双蛟画鼓催，一水银蟾满。\n见夺锦标回，却倚花枝看。\n已擘冷金笺，更酹玻璃碗。\n归去诧乡关，不负平生眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8091, '江城子', '史浩', '片帆初落甬勾东。\n碧湖空。\n满汀风。\n回首一川，银浪孤篷。\n且驾两椽烟雨里，凭曲槛，空。\n闲移拄杖上晴峰。\n莫匆匆。\n伴冥鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8092, '浪淘沙令', '史浩', '祝寿祝寿。\n筵开锦绣。\n拈起香来玉也似手。\n拈起盏来金也似酒。\n祝寿祝寿。\n命比乾坤久。\n长寿长寿。\n松椿自此碧森森底茂。\n乌兔从他汨轳轳底走。\n长寿长寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8093, '瑞鹤仙', '史浩', '霁光春未晓。\n拥绛蜡攒星，霜蹄轻袅。\n皇居耸云杪。\n霭祥烟瑞气，青葱缭绕。\n金门羽葆。\n听胪唱、千官并到。\n庆三朝、雉扇开时，拜舞仰瞻天表。\n荣耀。\n万方图籍，四裔明王，赆珍宝。\n椒盘颂好。\n称寿，祝难老。\n更传宣锡坐，钧天妙乐，声遏行运缥缈。\n逗归来、酒晕生霞，此恩怎报。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8094, '水龙吟', '史浩', '翠空缥缈虚无，算唯海上蓬瀛好。\n琼瑶宫阙，蕊珠台榭，玲珑缭绕。\n弱水沈冥，瑞云遮隔，几人曾到。\n四明中，自有神仙洞府，烟霞里、知多少。\n堪笑当年狂客，爱休官、何须入道。\n婆娑绿发垂肩，著甚黄冠乌帽。\n花底金船，月边玉局，尽能迟老。\n待丹成九转，飘然驾鹤，却游三岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8095, '水龙吟', '史浩', '平湖渺渺烟波，是中只许神仙住。\n人间空爱，夭桃繁李，雪飞红雨。\n谁信壶天，靓妆玉貌，春光容与。\n似佳人才子，青冥步稳，同携手、成欢聚。\n老子时来宴赏，拥笙歌、留连尊俎。\n乌纱压倒，香云簪遍，知他几度。\n多谢东君，肯教满架，长情相处。\n更须拚痛饮，年年此际，作芳菲主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8096, '永遇乐', '史浩', '鄞有壶天，景传图画，声著海县。\n四面攒峰，皆七十二，各在窗中见。\n祥云拥蔽，飞泉缭绕，咫尺似天涯远。\n如今向、仙家觅得，挈来十洲东畔。\n虚无缥缈，蓬莱方丈，所喜只居隔岸。\n羽垂珠，琼车织翠，长是陪嘉宴。\n豺狼远迹，风波不作，日月御轮须缓。\n且衔杯、称贤乐圣，度兹岁晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8097, '迎仙客', '史浩', '瑞云绕。\n四窗好。\n何须隔水寻蓬岛。\n日常晓。\n春不老。\n玉蕊楼台，果是无尘到。\n没智巧。\n没华妙。\n个中只喜风波少。\n清尊倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8098, '南浦', '史浩', '一箭舜弦风，向晓来、轻寒初报麦秀。\n蝶股歇花须，韶光老，莺声倦闻呼友。\n池塘绿暗，数竿粉节天然瘦。\n对兹美景，爱清歌妙曲，千锺芳酒。\n谁知别是壶中，缭画阁朱栏，烟谷云岫。\n三岛十洲东，青霄上，神工幻成岩窦。\n瑶台阆苑，翠旌羽葆频相就。\n世凡洗断，教乌兔从今，迟迟飞走。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8099, '夜合花', '史浩', '三岛烟霞，十洲风月，四明古号仙乡。\n萦纡雉堞，中涵一片湖光。\n绕岸异卉奇芳。\n跨虹桥、隐映垂杨。\n玉楼珠阁，冰帘卷起，无限红妆。\n龙舟两两飞扬。\n见飘翻绣旗，歌杂笙簧。\n清尊满泛，休辞饮到斜阳。\n直须画蜡荧煌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8100, '人月圆', '史浩', '夕阳影里东风软，骄马趁香车。\n看花妆镜，藏春绣幕，百万人家。\n夜阑归去，星繁绛蜡，珠翠鲜华。\n笙歌不散，疏锺隐隐，月在梅丫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8101, '人月圆', '史浩', '骄云不向天边聚，密雪自飞空。\n佳人纤手，霎时造化，珠走盘中。\n六街灯市，争圆斗小，玉碗频供。\n香浮兰麝，寒消齿颊，粉脸生红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8102, '粉蝶儿', '史浩', '一箭和风，熏许多春意。\n闹蛾儿、满城都是。\n向深闺，争翦碎、吴绫蜀绮。\n点妆成，分明是、粉须香翅。\n玉容似花，全胜故园桃李。\n最相宜、鬓云秋水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8103, '粉蝶儿', '史浩', '玉屑轻盈，鲛绡霎时铺遍。\n看仙娥、骋些神变。\n咄嗟间，如撒下、真珠一串。\n火方然，汤初滚、尽浮锅面。\n歌楼酒垆，今宵任伊索唤。\n那佳人、怎生得见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8104, '教池回', '史浩', '云淡天低，疏雨乍霁，桃溪嫩绿蒙茸。\n珠帘映画毂，金勒耀花骢。\n绕湖上、罗衣隘香风。\n擘波双引蛟龙。\n寻奇处，高标锦段，各骋英雄。\n缥缈初登彩舫，箫鼓沸，群仙玉佩丁东。\n夕阳中、拚一饮千锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8105, '如梦令', '史浩', '小院春风不老。\n鹊碧霓裳缥缈。\n雪脸间朱颜，各自一般轻妙。\n忒掉。\n忒掉。\n真个一双两好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8106, '洞仙歌', '史浩', '琼肌太白，浅著鹅黄罩。\n金缕檀心更天巧。\n算同时、虽有似火红榴，争比得、淡妆伊家轻妙。\n兴来清赏处，无限真香，可惜生教生闽峤。\n这消息、纵使移向蒸沈，终不似凭栏，披襟一笑。\n若归去长安诧标容，单道胜、酴水仙风貌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8107, '醉蓬莱', '史浩', '纪今辰高会，屈指三朝，更逢重九。\n珠履瑶簪，聚一天星斗。\n菊蕊含芳，桂花笼艳，有美容争秀。\n衮绣堂中，蓬壶影里，异香喷兽。\n况是清朝，太平真主，治享雍熙，眷深耆旧。\n恩锡兼金，遣星轺东走。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8108, '声声慢', '史浩', '风收淅沥，雾隐森罗。\n群山万玉嵯峨。\n禁街车马，银杯缟带相过。\n胥涛晚来息怒，练光浮、都不扬波。\n最好处，是渔翁归去，鼓棹披蓑。\n况是东堂锡宴，龙墀骤，貂宣劝金荷。\n庆此嘉瑞，明岁黍应多。\n天家预知混一，把琼瑶、铺遍山河。\n这宴饮，罄华戎、同醉泰和。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8109, '秋蕊香', '史浩', '玉露，秋色似画，东堂宴席初开。\n红萸泛寿，紫菊上妆台。\n倚栏见、新雁已南来。\n落霞孤鹜徘徊。\n最奇处，重阳将近，凉满襟怀。\n萧洒秀眉，华发丹脸，映双瞳、的如孩。\n擘香笺、听丽句新裁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8110, '渔家傲', '史浩', '春恨不禁听杜宇。\n买舟忽觅东鄞路。\n一笑轻帆同野渡。\n频回顾。\n吴山夜岫俱眉妩。\n何事匆匆分袂去。\n夫君小隐临烟渚。\n明夜月华来竹坞。\n相思处。\n还应梦属清江橹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8111, '花心动', '史浩', '迟日轻阴，雨初收，花枝湿红犹滴。\n玉镫绣鞯，才得新晴，柳岸往来如织。\n画楼几处珠帘卷，风光遍、神仙瑶席。\n萃佳景，分明管领，一陂澄碧。\n忽见波涛激。\n苍烟际、双龙起为敌。\n桂楫拨云，鼍鼓轰雷，竞夺锦标千尺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8112, '水龙吟', '史浩', '雪中蓓蕾嫣然，美人莫恨春容少。\n化工消息，只须些子，阳和便了。\n文杏徒繁，牡丹虽贵，敢夸妍妙。\n看冰肌玉骨，诗家漫道，银蟾莹、白驹皎。\n楼上角声催晓。\n是东皇、丝纶新草。\n青旗苍辂，欲临东阙，遣伊先到。\n排斥风霜，扫除氛雾，直教闻早。\n算功高调鼎，不如竹外，一枝斜好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8113, '瑞鹤仙', '史浩', '是花堪爱惜。\n谢天教、花信添花颜色。\n花红衬花碧。\n灿朝阳花露，鲛珠频滴。\n花光的。\n映花下、□茵百尺。\n趁花时，手拈花枝，饱嗅此花消息。\n常恐，一番花褪，失了花容，怎生寻觅。\n花神效力。\n将花貌，尽留得。\n更移花并植，仙家玉圃，不许花阴过隙。\n向花前，长把蕉花，为花主席。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8114, '喜迁莺', '史浩', '三春正美。\n是霁景融和，韶华如绮。\n夹岸香红，登墙粉白，开遍故园桃李。\n画舸绣帘高卷，锦毂朱轩低倚。\n对此际，向池台好处，争倾绿蚁。\n醉里。\n须醒悟，些子芳菲，造物都谩你。\n一瞬光阴，霎时蜂蝶，还付落花流水。\n我有大丹九转，真个长春不死。\n待得了，把高歌清赏，随缘而已。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8115, '菩萨蛮', '史浩', '提壶漫欲寻芳去。\n桃红柳绿年年事。\n唯有列仙翁。\n清明本在躬。\n何须从外讨。\n皮里阳秋好。\n堪羡个中人。\n无时不是春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8116, '南浦', '史浩', '天气正清和，庆西乾、释迦如来出世。\n毓质向金盆，祥云布、层霄九龙喷水。\n东传震旦，正令此日人人记。\n露盘百卉拥金容，香汤争来拂洗。\n谁知这个因缘，化众生令求，尘埃脱离。\n一点本昭昭，当须向、兹时便知瞥地。\n何烦费手，自然作个惺惺底。\n若犹未晤，且管令师僧，八丈十二。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8117, '青玉案', '史浩', '银涛渐溢江南路。\n泛短棹、轻帆去。\n破块跳珠知几度。\n竹窗新粉，藕池香碧，应在云深处。\n萧萧鹤发虽云暮。\n曾得神仙悟真句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8118, '花心动', '史浩', '槐夏阴浓，笋成竿、红榴正堪攀折。\n菖碎琼，角黍堆金，又赏一年佳节。\n宝觥交劝殷勤愿，把玉腕、彩丝双结。\n最好是，龙舟竞夺，锦标方彻。\n此意凭谁向说。\n纷两岸，游人强生区别。\n胜负既分，些个悲欢，过眼尽归休歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8119, '卜算子', '史浩', '符玉搔头，艾虎青丝鬓。\n一曲清歌倒酒莲，尚有香蒲晕。\n角簟碧纱厨，挥扇消烦闷。\n唯有先生心地凉，不怕炎曦近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8120, '永遇乐', '史浩', '日永绣工，减却一线，节临短至。\n幸有杯盘，随分快乐，□得醺醺醉。\n寻思尘世，寒来暑往，冻极又还热炽。\n恰如个、脾家疟疾，比著略长些子。\n人生百岁，一年一发，且是不通医治。\n两鬓青丝，皆伊染就，今已星星地。\n除非炉内，龙盘虎绕，养得大丹神水。\n却从他、阴阳自变，卦分泰否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8121, '鹊桥仙', '史浩', '金乌玉兔，时当几望，只是光明相与。\n天孙河鼓事应同，又启比、人间男女。\n精神契合，风云交际，不在一宵欢聚。\n乘槎曾得问星津，为我说、因缘如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8122, '瑞鹤仙', '史浩', '霁天风露好。\n乍暑退西郊，凉生秋早。\n银潢炯云杪。\n拥香车鹊翅，凌波初到。\n清歌缥缈。\n凭危阁、新蟾吐曜。\n有盈尊美酒，蛛丝钿合，拜舞竞分天巧。\n堪笑。\n世间痴绝，不识人中，拙是珍宝。\n多愁易老。\n都缘是，不闻道。\n骋些儿机智，遭他驱使，毕竟辛勤到了。\n又何如，百事无能，是非较少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8123, '念奴娇', '史浩', '碧天似水，看常娥摩出，一轮寒璧。\n桂魄扶疏光照耀，尘界都成银色。\n万象森罗，羞明卷彩，黯淡唯今夕。\n风高露重，井梧湿翠时滴。\n谁信鹤发婆娑，峰真隐，对影为三益。\n虎绕龙盘丹就後，一颗清辉的国。\n不养银蟾，不关玉兔，到处无亏蚀。\n三千行满，也能飞上璇极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8124, '芰荷香', '史浩', '过横塘。\n见红妆翠盖，柄柄擎香。\n月娥有意，暮霭收尽银潢。\n一轮高挂，且放同、千里清光。\n秋中气爽天凉。\n露凝玉臂，风拂云裳。\n老子通宵不忍睡，把青尊小酌，仍更思量。\n自家活计，幸有无限珍藏。\n大千世界，静极後、普现十方。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8125, '清平乐', '史浩', '池台非雾。\n缥缈双溪路。\n家在江南佳丽处。\n看取谢公风度。\n蟠桃酒酝千秋。\n金焦欲上迟留。\n笑待锦花上，双鸾舞彻梁州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8126, '清平乐', '史浩', '翠蛾雪柳。\n鬓影春风透。\n灯火千门辉绮绣。\n移下一天星斗。\n剩拚连夜欢游。\n金波欲上迟留。\n且看香梅影底，双鸾舞彻梁州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8127, '清平乐', '史浩', '石头虎踞。\n骄虏何能渡。\n曾是六朝雄胜处。\n瑞绕碧江云路。\n当时霸国多贤。\n风流只解遗鞭。\n便好扬北伐，举头即见长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8128, '清平乐', '史浩', '万花如绣。\n淑景熏晴昼。\n一曲齐称千岁寿。\n欢拥两行红袖。\n当年西府横翔。\n急流稳上仙乡。\n笑阅溪日月，行看尚父鹰扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8129, '清平乐', '史浩', '槐庭元老。\n四海真师表。\n曲为故人敦久要。\n隔巷不嫌时到。\n虚堂已入凉。\n一觥为寿何辞。\n看即关河恢复，千秋永辅淳熙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8130, '清平乐', '史浩', '当年桂籍。\n同展摩云翼。\n位冠洪枢情似昔。\n肯共一尊瑶席。\n经纶素韫胸中。\n筹帷小试成功。\n已殄黄池小丑，行收沙漠肤功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8131, '清平乐', '史浩', '吾皇睿哲。\n廷有真三杰。\n同向清时扬茂烈。\n掩迹皋陶夔契。\n联镳忽访山樊。\n凉生花底清尊。\n太史明朝日奏，台星皆聚柴门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8132, '清平乐', '史浩', '南阳宾友。\n道旧须尊酒。\n一曲为公千岁寿。\n弦索春风纤手。\n忠谋黼黻明昌。\n英词锦绣甘肠。\n帝所盛推颇牧，人间尤重班扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8133, '朝中措', '史浩', '冻云著地静无风。\n簌蔌坠遥空。\n无限人间险秽，一时为尔包容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8134, '七娘子', '史浩', '东篱寿菊金犹浅。\n对南山、把酒开新宴。\n绛阙丛霄，玉书丹篆。\n坐间俱是神仙伴。\n童颜绿发何曾变。\n喜婴儿姹女交相恋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8135, '惜黄花', '史浩', '秋光将老。\n黄花开早。\n露清晓，金钱万叠犹小。\n簪遍碧云鬟，压倒乌纱帽。\n更把来、玉觞同。\n过□添炉鼎，朱颜愈少。\n壮道骨，长仙风，养成灵宝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8136, '浣溪沙', '史浩', '翠馆银罂下紫清。\n内家闻说庆嘉平。\n柳条萱草眼偏明。\n小阁数杯成酩酊，醒来不爱佩环声。\n为通幽梦到蓬瀛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8137, '临江仙', '史浩', '腊月正当三十夜，几人到此惺惺。\n一轮明月本圆明。\n朗然无挂碍，何用问前程。\n况有长生真秘□，岁华虽换休惊。\n但将歌酒乐升平。\n尘缘如未了，明日贺新正。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8138, '感皇恩', '史浩', '结柳送穷文，驱傩吓鬼。\n爆火熏天漫儿戏。\n自家炉鼎，有却冷清清地。\n腊月三十日，如何避。\n且与做些，神仙活计。\n铅汞收添结灵水。\n跳丸日月，一任东生西委。\n玉颜长向此，迎新岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8139, '满庭芳', '史浩', '梅萼冰融，柳丝金浅，绪风还报初春。\n木君青旆，猎猎下苍。\n亲捧虚皇妙旨，将枯朽、咸与维新。\n须臾见，芳郊乐圃，生气遍无垠。\n青丝，行白玉，一杯介寿，红浪粼粼。\n便安排歌舞，蝶翅莺唇。\n别有神仙窟宅，乾坤内、充满氤氲。\n功成处，花开不老，酒熟镇甘醇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8140, '扑胡蝶・扑蝴蝶', '史浩', '光阴转指。\n百岁知能几。\n儿时童稚，老来将耄矣。\n就中些子强壮，又被浮名牵系。\n良辰尽成轻弃。\n此何理。\n若有惺惺活底，必解自为计。\n清尊在手，且须拚烂醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8141, '蝶恋花', '史浩', '玉瓮新醅翻绿蚁。\n滴滴真珠，便有香浮鼻。\n欲把盈尊成雅会。\n更须寻个无愁地。\n况是赏心多乐事。\n美景良辰，又复来相值。\n料得天家深有意。\n教人长寿花前醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8142, '临江仙', '史浩', '自古圣贤皆寂寞，祗教饮者留名。\n万花丛里酒如渑。\n池台仍旧贯，歌管有新声。\n欲识醉乡真乐地，全胜方丈蓬瀛。\n是非荣辱不关情。\n百杯须痛饮，一枕拚春酲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8143, '粉蝶儿', '史浩', '一盏阳和，分明至珍无价。\n解教人、哩哩。\n把胸中，些磊块，一时熔化。\n悟从前，恁区区，总成虚假。\n何妨竟夕，交酬玉觞金。\n更休辞、醉眠花下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8144, '瑞鹤仙', '史浩', '瑞烟笼绣幕。\n正玳席欢燕，觥筹交错。\n高情动寥廓。\n恣清谈雄辩，珠玑频落。\n锵锵妙乐。\n且赢取、升平快乐。\n又何辞、醉玉颓山，是处有人扶著。\n追念抟风微利，画饼浮名，久成离索。\n输忠素约。\n没材具，漫担阁。\n怅良辰美景，花前月下，空把欢游蹉却。\n到如今、对酒当歌，怎休领略。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8145, '永遇乐', '史浩', '桃李繁华，芰荷清净，景物相继。\n霜後橙黄，雪中梅绽，迤逦春还至。\n寻思天气，寒暄凉燠，各有一时乐地。\n如何被、浮名牵役，此欢逐成抛弃。\n如今醒也，扁舟短棹，更有篮舆胡倚。\n到处为家，山肴社酒，野老为宾侣。\n三杯之後，吴歌楚舞，忘却曳金穿履。\n虽逢个、清朝贵客，也须共来一醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8146, '青玉案', '史浩', '闲忙两字无多子。\n叹举世、皆由此。\n逐利争名忙者事。\n廛中得丧，仕中宠辱，无限非和是。\n谁人解识闲中味。\n雪月烟云自能致。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8147, '满庭芳', '史浩', '和靖重湖，知章一曲，浙江左右为邻。\n绣鞯彩舰，只许日寻春。\n正好厌厌夜饮，都寂静、没个游人。\n夫何故，欢阑兴阻，只为隔城。\n堪嘉，唯甬水，回环雉堞，中峙三神。\n更楼台缭岸，花柳迷津。\n不惜频添画烛，更深看、舞上华。\n拚沈醉，从他咿喔，金距报凌晨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8148, '满庭芳', '史浩', '柴作疏篱，茅编小屋，绕堤苦竹黄芦。\n老翁蜗处，却自乐清虚。\n理钓何妨钩直，据琴又、不管弦无。\n逍遥处，都捐世虑，忘我亦忘渠。\n雨馀。\n添美景，眉横山妩，脸媚花腴。\n笑凡间粉黛，浓抹轻涂。\n客至三杯薄酒，欲眠後、一枕蘧蘧。\n起来见，龟翻鹤舞，却是寿星图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8149, '临江仙', '史浩', '曾向泗滨浮玉质，也居十二峰前。\n飞来藓发尚如拳，郁纷因出岫，巧镂是谁镌。\n挈凭栏成胜赏，老夫亦自颓然。\n坐疑霭霭上瑶天。\n已为苏旱雨，却放老龙眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8150, '好事近', '史浩', '枕不成眠，得句十分清绝。\n一夜酸风阁花，酝江天飞雪。\n晓来的看枝头，老蚌剖明月。\n帝所待调金鼎，莫教人轻折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8151, '好事近', '史浩', '对竹擘吟笺，正是赏梅时节。\n便把这些清致，作东湖三绝。\n帝家金鼎待调羹，何似且休折。\n却爱玉楼清弄，褪霏霏香雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8152, '念奴娇', '史浩', '银潢耿耿，正露零仙掌，尘空天幕。\n碧玉扶疏□万朵，偏称水村山郭。\n巧酝檀英，密包金粟，只待清秋著。\n三春桃李，自应束在高阁。\n好是月窟奇标，东堂幽韵，不管西风恶。\n独立盈盈回首笑，白苇丹枫索索。\n折向冰壶，莫教纱帽，醉里轻簪却。\n浓芳长在，□疑身在云壑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8153, '念奴娇', '史浩', '枝头蓓蕾，褪红绡微露，江南春色。\n多谢东风吹半朵，来入骚人瑶席。\n粉脸轻红，芳心羞吐，别有真消息。\n妆台帘卷，寿阳著意留得。\n好是雪满群山，玉纤频拈，泛清波文。\n深院相逢人尽道，标格都从天锡。\n梦蝶徒劳，霜禽休妒，争奈伊怜惜。\n高楼谁倚，寄言休为横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8154, '念奴娇', '史浩', '银塘江上，展鲛绡初见，长天一色。\n风拭菱花光照眼，谁许红尘轻积。\n转盼冯夷，奔云起电，两岸惊涛拍。\n振空破地，水龙争喷吟笛。\n客有步江干，胸吞奇观，寄英词元白。\n素壁淋浪翻醉墨，飘洒神仙踪迹。\n好待波匀，横飞小艇，快引香筒碧。\n烟消月出，不眠拚了通夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8155, '白苎', '史浩', '腊天寒，晓风劲，幽香频吐。\n精神绰约，谁羡姑射居处。\n江南探春独步。\n恨无侣。\n微语。\n又谁管、雪势霜威埋妒。\n且图少陵东阁作诗苦。\n拟烦玉纤轻拗、宁相许。\n惜取。\n栏干遍倚，月淡黄昏，水边清浅，不放红尘染污。\n似名画手丹青，罢施缃素。\n不随艳卉，强媚韶光一瞬，飘荡无据。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8156, '浣溪沙', '史浩', '一握钩儿能几何。\n弓弓珠蹙杏红罗。\n即时分惠谢奴哥。\n香压幽兰兰尚浅，样窥初月月仍多。\n只堪掌上恹琼波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8157, '浣溪沙', '史浩', '珠履三千巧斗妍。\n就中弓窄只迁迁。\n恼伊袜转堪怜。\n舞罢有香留绣褥，步馀无迹在金莲。\n好随云雨楚峰前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8158, '浣溪沙', '史浩', '湿翠湖山收晚烟。\n月华如练水如天。\n兴来催上钓鱼船。\n青箬一尊汀草畔，霜筠数曲渚花边。\n更於何处觅神仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8159, '浣溪沙', '史浩', '梁武憨痴达摩呆。\n个中消息岂容猜。\n九年面壁口慵开。\n双履却寻归路止，一花原不是君栽。\n这回枉了一遭来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8160, '浣溪沙', '史浩', '索得玄珠也是呆。\n人人有分莫胡猜。\n顶门一眼镇长开。\n路断玉关无辙迹，雪埋葱岭没根栽。\n始称达摩不曾来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8161, '浣溪沙', '史浩', '胜概朱楹俯碧湖。\n萧萧风月一尘无。\n只堪绿蚁满尊浮。\n况是小春天正爽，杖藜相与探梅初。\n半皴枝上未成珠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8162, '浣溪沙', '史浩', '远岫数堆苍玉髻。\n平湖千顷碧琉璃。\n笙歌催我上船时。\n载月有如浮玉鉴，采莲还复拥燕脂。\n更於何处觅瑶池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8163, '武陵春', '史浩', '报道东皇初弭节，芳思满凌晨。\n争看钗头彩胜新。\n金字写宜春。\n四坐行盘堆白玉，纤手自和匀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8164, '千秋岁', '史浩', '吾乡我里。\n偕老真无比。\n宴席展，欢声起。\n蕊宫仙子绕，玉砌莱衣戏。\n称贺处，眉心竞指朱书字。\n忆昔西周吕。\n年纪虽相似。\n独自个，谁为侣。\n如今双凤老，堪引同螺醉。\n彭祖寿，十分方一从头纪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8165, '新荷叶', '史浩', '真隐先生，家居近在东湖。\n茅屋三椽，自有一种清虚。\n秫来酿酒，便无後、也解赊沽。\n只愁客至，不能拚此芳壶。\n且乐天真，醉乡里、无限欢娱。\n时倚花枝，困来著枕蘧蘧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8166, '醉蓬莱', '史浩', '喜泉通碧。\n秫刈黄云，酿成芳酎。\n瑞霭凝香，更阳和锺秀。\n晓瓮寒光，夜槽清响，听颔珠频溜。\n昼锦堂深，聚星筵启，一觥为寿。\n况此神仙，蕊宫俦侣，玉殿英游，尽皆亲旧。\n赢得开怀，对良辰握手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8167, '瑶台第一层', '史浩', '寥廓澄清。\n人正在、瑶台第一层。\n瑞霭深处，蕊宫掩映，金碧觚棱。\n异花非世种，蔼剩馥、紫雾飞腾。\n有仙驾，过吾庐环堵，少驻云。\n俄惊。\n重壶叠，顿然潇洒俗尘清。\n佩环声里，宝觥潋滟，舞态娉婷。\n祝言千岁寿，仍更予、五福川增。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8168, '如梦令', '史浩', '摘索衣裳宫样。\n生得脸儿福相。\n容止忒精神，一似观音形像。\n归向。\n归向。\n见者擎拳合掌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8169, '如梦令', '史浩', '粉脸霞生一缕。\n掩映绿云秋水。\n言语更雍容，具足十分娇美。\n无比。\n无比。\n要比除非镜里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8170, '如梦令', '史浩', '红杏白梨肌理。\n时样新妆淡伫。\n真个是观音，少个杨枝净水。\n欢喜。\n欢喜。\n尽此一锺醇美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8171, '如梦令', '史浩', '罗袜半钩新月。\n更把凤鞋珠结。\n步步著金莲，行得轻轻瞥瞥。\n难说。\n难说。\n真是世间奇绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8172, '如梦令', '史浩', '试把珠帘低卷。\n宛见梅妆粉面。\n绿绕更红围，齐捧瑶卮来劝。\n堪羡。\n堪羡。\n此是神仙阆苑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8173, '如梦令', '史浩', '一笑尊前相语。\n莫遣良辰虚度。\n饮兴正浓时，兔碗聊分春露。\n留住。\n留住。\n催办後筵歌舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8174, '南歌子', '史浩', '藻涧蟾光动，松风蟹眼鸣。\n浓熏沈麝入金瓶。\n泻出温温一盏、涤烦膺。\n爽继云龙饼，香无芝术名。\n主人襟韵有馀清。\n不向今宵忘了、淡交情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8175, '画堂春', '史浩', '小槽春酿香红。\n良辰飞盖相从。\n主人着意在金钟。\n茗碗作先容。\n欲到醉乡深处，应须仗、两腋香风。\n献酬高兴渺无穷。\n归骑莫匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8176, '杏花天', '史浩', '梦魂飞过屏山曲。\n见依旧、如花似玉。\n天寒翠袖依修竹。\n两点春山斗绿。\n披衣起、闲愁万斛。\n正月澹、梅花照屋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8177, '临江仙', '史浩', '忆昔来时双髻小，如今云鬓堆鸦。\n绿窗冉冉度年华。\n秋波娇酒，春笋惯分茶。\n居士近来心绪懒，不堪老眼看花。\n画堂明月隔天涯。\n春风吹柳絮，知是落谁家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8178, '临江仙', '史浩', '试凭阑干春欲暮，桃花点点胭脂。\n故山凝望水云迷。\n数堆苍玉髻，千顷碧琉璃。\n我本清都闲散客，蓬莱未是幽奇。\n明朝归去鹤齐飞。\n三山乘缥缈，海运到天池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8179, '忆王孙', '仲并', '庭梧叶密未惊秋。\n风雨潇潇特地愁。\n愁绪如丝无尽头。\n思悠悠。\n怅望王孙空倚楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8180, '点绛唇', '仲并', '秀出群儿，柳眉濯濯春庭院。\n不亲歌扇。\n弄笔勤书篆。\n翁已无能，老退惭面。\n欣同宴。\n坐来喜见。\n痛饮惊无算。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8181, '浣溪沙', '仲并', '举案家风未肯低。\n清心端自秀深闺。\n芝兰玉树宁馨儿。\n早岁安禅灵照女，静中经卷手常携。\n声名要与断机齐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8182, '浣溪沙', '仲并', '雅称诗人美孟都。\n清新幽韵比来无。\n新来学得绣工夫。\n经卷但知从阿母，醉来翁已要人扶。\n尚能把盏劝屠苏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8183, '浣溪沙', '仲并', '说似当年老季伦。\n君家虽富客常贫。\n何曾一笑任吾真。\n酒满罢留天下士，词新空赋坐中春。\n谁能绝笔更书麟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8184, '菩萨蛮', '仲并', '宛如姑射人冰雪。\n知公不负佳风月。\n莫放漏声残。\n清风生坐间。\n赏春心未足。\n翦尽尊前烛。\n此乐自难忘。\n一觞还一觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8185, '好事近', '仲并', '二陆起云间，千载风流人物。\n未似一门三凤，向层霄联翼。\n贞元朝士苦无多，公今未华发。\n重向紫宸朝路，立鸾前列。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8186, '好事近', '仲并', '今古满胸中，韬略一时人杰。\n高卧溪山好处，迟十年斋钺。\n朱休傍武陵溪，梅花记曾别。\n早晚殿前归侍，总周庐千列。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8187, '好事近', '仲并', '淮上五分符，名在图书东壁。\n坐对书成多暇，写青箱千帙。\n一杯先为祝东风，丹诏来朝夕。\n何处称公挥翰，定北扉西掖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8188, '好事近', '仲并', '阀阅盛中州，冠冕共推华族。\n耐久松筠交契，更襟怀金玉。\n诸儒皆自愧卢前，小试暂符竹。\n行看世官入践，继西枢前躅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8189, '好事近', '仲并', '分手又三秋，犹记花时歌别。\n每念征帆归晚，误五湖风月。\n清江休望使君来，指日趋天阙。\n婿玉翁冰相映，看紫薇花发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8190, '好事近', '仲并', '襟韵绝纤尘，炯炯夜光明月。\n合是紫荷持橐，侍丹墀清切。\n暗香疏影想公家，人与梅超绝。\n酒罢帝城早去，占百花先发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8191, '好事近', '仲并', '今雨几人来，冰霰更凝寒色。\n门外车多长者，顿光生蓬荜。\n缤纷飞雪更初梅，特特为留客。\n惟恨坐无华馔，只平时真率。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8192, '忆秦娥', '仲并', '隈岩侧。\n怪生小院香来别。\n香来别。\n嫩黄细细，商量齐发。\n佳人敛笑贪先折。\n重新为翦斜斜叶。\n斜斜叶。\n钗头常带，一秋风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8193, '画堂春', '仲并', '春波浅碧涨方池。\n池台深锁烟霏。\n缓歌争胜早莺啼。\n客忍轻归。\n合坐香凝宿雾，垫巾梅插寒枝。\n渐西蟾影漾馀辉。\n醉倒谁知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8194, '大圣乐令・玉团儿', '仲并', '豆蔻梢头春正早。\n敛修眉、未经重扫。\n湖山清远，几年牢落，风韵初好。\n慢绾垂螺最娇小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8195, '浪淘沙', '仲并', '趁拍舞初筵。\n柳袅春烟。\n街头桃李莫争妍。\n家本凤楼高处住，锦瑟华年。\n不用抹繁弦。\n歌韵天然。\n天教独立百花前。\n但愿人如天上月，三五团圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8196, '浪淘沙', '仲并', '倾国与倾城。\n袅袅盈盈。\n歌喉巧作断肠声。\n看尽风光花不语，却是多情。\n家近董双成。\n三妙齐名。\n谁教蜂蝶漫经营。\n留取无双风味在，真是琼英。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8197, '浪淘沙', '仲并', '草圣与诗馀。\n清韵谁如。\n生绡团扇倩谁书。\n月湛素华天似水，深院凉初。\n人散晚钟疏。\n後约还虚。\n良宵忍放枕鸾孤。\n要得相逢除是梦，有梦来无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8198, '鹧鸪天', '仲并', '小泊横塘日欲斜。\n一枝犹有未残花。\n几年燕子无消息，今日飞来王谢家。\n歌水调，韵琵琶。\n声声都是怨年华。\n钗头杏子今如许，翦烛裁诗莫问他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8199, '鹧鸪天', '仲并', '间世麒麟降自天。\n光辉列宿灿初躔。\n他年身致夔龙列，少日心存翰墨边。\n簪彩笔，照金莲。\n词华当使思如泉。\n未论耸壑昂霄事，且与衰翁慰暮年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8200, '蓦山溪', '仲并', '冰清玉映，自是闺房秀。\n十里卷朱帘，好紫陌、家家未有。\n天然情素，高压一城春，花艳丽，月精神，梅韵腰枝瘦。\n曲屏虚幌，枉著鸳鸯绣。\n不是不相逢，泪空滴、年年别袖。\n从他兰菊，秋露与春风，终不似，玉人人，一片心长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8201, '水调歌头', '仲并', '华栋一何丽，移下小壶天。\n几多曲房新户，缥缈似当年。\n曾是使君风度，元有胸中丘壑，六月竹风寒。\n一洗筝笛耳，歌舞粲筵间。\n坐中客，醒复醉，听无眠。\n已回归梦，犹复袅袅记清圆。\n尚想饮中仙子，来处馀香飘坐，胜韵此双全。\n为寄月华语，难与并蝉娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8202, '芰荷香', '仲并', '醉凝眸。\n正行云遮断，澄练江头。\n皓月今宵何处，不管中秋。\n朱阑倚遍，又微雨、催下危楼。\n秋风空响更筹。\n不将好梦，吹过南州。\n浮远轩窗异日到，山空云净，江远天浮。\n别去客怀，无赖准拟开愁。\n冰轮好在，解随我、天际归舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8203, '八声甘州', '仲并', '正西山、雨过弄晴景，竹屋贯斜晖。\n问谁将千斛，霏瑛落屑，吹上花枝。\n风外青鞋未熟，鼻观已先知。\n扰损江南客，诗面难肥。\n两句林边倾盖，笑化工开落，尤甚儿嬉。\n叹额黄人去，还是隔年期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8204, '念奴娇', '仲并', '灰飞竹。\n庆群阴消尽，新阳来复。\n云物呈祥连瑞霭，烟气纷纷馥馥。\n紫陌香衢，朱檐影里，罗绮花成簇。\n岭梅惊暖，数枝争绽寒玉。\n有人袅袅盈盈，今朝特地，为我新妆束。\n娇倚银床添绣线，长喜修眉舒绿。\n不道多情，锦屏罗幌，难得欢生足。\n谁知今夜，玉壶银漏催促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8205, '念奴娇', '仲并', '江南春早，尚馀寒门巷，杨花飘逐。\n一色初梅开尽也，不数芳园红绿。\n珍重骚人，幽怀分寄，高韵歌黄竹。\n六花羞避，满笺凌乱琼玉。\n应念有客长安，履穿东郭，无与怜穷独。\n鼓棹前溪非兴尽，寒怯水栖岩宿。\n咫尺君家，瑶田无径，冰柱排银屋。\n瓮头春到，唤回晚梦清熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8206, '念奴娇', '仲并', '金滕事业。\n庆丹青千载，勋在王室。\n圣主英明平万国，天产非常人物。\n岳渎分灵，熊罴符梦，五百年方出。\n致君尧舜，要须纯用经术。\n须信凤阁仙人，风流文采，蔼家声如昔。\n献纳司存持禁橐，合历三台清秩。\n倦宿承明，乞麾临郡，暂辍金闺直。\n五云深处，一星今在南极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8207, '瑞鹤仙', '仲并', '试六花院落。\n正柳绵飘坠，因风无著。\n吴王旧城郭。\n记乌衣门巷，小桥帘幕。\n他州寥索。\n漫等闲、桃英杏萼。\n认幽香来处，群芳尽掩，蕙心先觉。\n行乐。\n燕雏莺友，浪语狂歌，休休莫莫。\n兰房绣幄。\n添新恨，念前约。\n十分芳景，十分春意，休惜十分共酌。\n任十分、吹老寒梅，戌楼画角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8208, '水调歌头', '仲并', '静练平千顷，华栋俯中流。\n凌晨画戟，来看宿雨断虹收。\n八九胸中云梦，三千笔端风月，无处快凝眸。\n笑咏一堂上，挥麈气横秋。\n俯危阑，红日下，暮云稠。\n无穷伟观，祗应天意为君谋。\n容我时醒时醉，独泛微烟微雨，浩荡逐轻鸥。\n不羡岳阳胜，丹碧耸层楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8209, '念奴娇', '仲并', '练江风静，卧冰奁百尺，朱阑飞入。\n江远浮天天在水，水满半天云湿。\n白鸟明边，青山断处，眼冷江头立。\n月明潮上，苇间渔唱声急。\n几度吹老苹花，野香无数，欲寄应难及。\n天借诗人供醉眼，尊俎一时收拾。\n竹里行厨，花间步障，风雨生呼吸。\n酒阑歌罢，钓船先具蓑笠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8210, '画堂春', '仲并', '溪边风物已春分。\n画堂烟雨黄昏。\n水沈一缕袅炉薰。\n尽醉芳尊。\n舞袖飘摇回雪，歌喉宛转留云。\n人间能得几回闻。\n丞相休嗔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8211, '浣溪沙', '仲并', '清远湖山佳丽人。\n柳边花下复清晨。\n向前犹有几多春。\n祓禊秋千时节近，管弦歌舞一回新。\n未嗔狂客污车茵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8212, '眼儿媚', '仲并', '铃阁寻盟未肯寒。\n首驻江干。\n云烟翰墨，风流尊俎，不放更残。\n金声掷地西清老，天未许终闲。\n知音素赏，当筵一曲，流水高山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8213, '武陵春', '仲并', '门巷乌衣应好在，风韵尚依然。\n知是蓬瀛第几仙。\n秀色粲当筵。\n索句濡毫云阁里，清坐袅炉烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8214, '渔父词・渔父', '赵构', '一湖春水夜来生。\n几叠春山远更横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8215, '渔父词・渔父', '赵构', '薄晚烟林澹翠微。\n江边秋月已明晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8216, '渔父词・渔父', '赵构', '云洒清江江上船。\n一钱何得买江天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8217, '渔父词・渔父', '赵构', '青草开时已过船。\n锦鳞跃处浪痕圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8218, '渔父词・渔父', '赵构', '扁舟小缆荻花风。\n四合青山暮霭中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8219, '渔父词・渔父', '赵构', '侬家活计岂能明。\n万顷波心月影清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8220, '渔父词・渔父', '赵构', '骇浪吞舟脱巨鳞。\n结绳为网也难任。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8221, '渔父词・渔父', '赵构', '鱼信还催花信开。\n花风得得为谁来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8222, '渔父词・渔父', '赵构', '暮暮朝朝冬复春。\n高车驷马趁朝身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8223, '渔父词・渔父', '赵构', '远水无涯山有邻。\n相看岁晚更情亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8224, '渔父词・渔父', '赵构', '谁云渔父是愚翁。\n一叶浮家万虑空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8225, '渔父词・渔父', '赵构', '水涵微雨湛虚明。\n小笠轻蓑未要晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8226, '渔父词・渔父', '赵构', '无数菰蒲间藕花。\n棹歌轻举酌流霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8227, '渔父词・渔父', '赵构', '春入渭阳花气多。\n春归时节自清和。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8228, '渔父词・渔父', '赵构', '清湾幽岛任盘纡。\n一舸横斜得自如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8229, '失调名', '崔若砺', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8230, '多丽', '高登', '人间世，偶然攘臂来游。\n何须恁、乾坤角抵，又成冷笑俳优。\n且宽心、待他天命，谩鼓舌、夸吾人谋。\n李广不侯，刘未第，千年公论合谁羞。\n往矣瓦飘无意，甑堕懒回头。\n真堪笑，直钩论议，圆枘机筹。\n幸斯道、元无得丧，壮心岂有沈浮。\n好温存、困中节概，莫冷落、穷里风流。\n酒滴珍珠，饭钞云子，醉饱卧信缘休。\n归去也，幅巾谈笑，卒岁且优游。\n循环事，亡羊须在，失马何忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8231, '阮郎归', '高登', '武仙花县谒凫仙。\n急招横渡船。\n重门昼掩讼庭闲。\n虚檐群雀喧。\n金屋畔，玉阑边。\n新春桃李妍。\n主人情重客无缘。\n销魂空黯然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8232, '蓦山溪', '高登', '黄茅时节，病恼南来客。\n瘦得不胜衣，试腰围、都无一搦。\n东篱兴在，手种菊方黄，摘晚艳，泛新，谁道乾坤窄。\n百年役役，乐事真难得。\n短发已无多，更何劳、霜风染白。\n儿曹齐健，扶□一翁孱，龙山帽，习池巾，归路从侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8233, '行香子', '高登', '瘴气如云。\n暑气如焚。\n病轻时、也是十分。\n沈疴恼客，罪罟萦人。\n叹槛中猿，笼中鸟，辙中鳞。\n休负文章，休说经纶。\n得生还、已早因循。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8234, '渔家傲', '高登', '名利场中空扰扰。\n十年南北东西道。\n依旧缘山尘扑帽。\n空懊恼。\n羡他陶令归来早。\n归去来兮秋已杪。\n菊花又绕东篱好。\n有酒一尊开口笑。\n虽然老。\n玉山犹解花前倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8235, '好事近', '高登', '潇洒带霜枝，独向岁寒时节。\n触目千林憔悴，更幽姿清绝。\n多才应赋得天真，落笔惊风叶。\n从此绿窗深处，有一梢秋月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8236, '好事近', '高登', '送客过江村，况值重阳佳节。\n向晚西风萧瑟，正离人愁绝。\n尊前相顾惜参商，引十分蕉叶。\n回首高阳人散，负西楼风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8237, '好事近', '高登', '饮兴正阑珊，正是挥毫时节。\n霜乾银钩锦句，看壁间三绝。\n西风特地飒秋声，楼外触残叶。\n匹马翩然归去，向征鞍敲月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8238, '浪淘沙', '高登', '璧月挂秋宵。\n丹桂香飘。\n广寒宫殿路迢迢。\n试问嫦娥缘底事，欲下层霄。\n兰玉自垂髫。\n拜命当朝。\n神仙会里且逍遥。\n分取壶中闲日月，来伴王乔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8239, '西江月', '高登', '渺渺西江流水，翩翩北客征帆。\n清秋月影浸人寒。\n云净碧天澄淡。\n飘泊道途零落，疏慵鬓发。\n从来涉世戒三缄。\n只好随时饮啖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8240, '南歌子', '高登', '菊拈黄金嫩，杯倾琥珀浓。\n良辰何处寄萍踪。\n短艇飘摇一叶、浪花中。\n凤阙游娃馆，幽坡赏梵宫。\n当年乐事总成空。\n目断天边想像、意何穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8241, '好事近', '高登', '富贵本无心，何事故乡轻别。\n空惹猿惊鹤怨，误松萝风月。\n囊锥刚强出头来，不道甚时节。\n欲命巾车归去，恐豺狼当辙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8242, '菩萨蛮', '闻人武子', '晴风吹暖枝头雪。\n露华香沁庭中月。\n屏上小江南。\n雨昏天际帆。\n翠钗香雾湿。\n侧鬓云松立。\n灯背欲眠时。\n晓莺还又啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8243, '桂华明・四犯令', '关注', '缥缈神京开洞府。\n遇广寒宫女。\n问我双鬟梁溪舞。\n还记得、当时否。\n碧玉词章教仙侣。\n为按歌宫羽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8244, '水调歌头', '关注', '凤舞龙蟠处，玉室与金堂。\n平生想望真境，依约在何方。\n谁信许君丹灶，便与吴君遗剑，只在洞天傍。\n若要安心地，便是远名场。\n几年来，开林麓，建山房。\n安眠饱馆清坐，无事可思量。\n洗尽人间忧患，看尽仙家风月，和气满清扬。\n一笑尘埃外，云水远相忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8245, '剔银灯', '关注', '小院烟凉雨细。\n正好恹恹春睡。\n蓦被金枝，连推绣枕，报道皇都书至。\n良人得意。\n集英殿、首攀仙桂。\n斗帐重襟惊起。\n斜倚屏山偷喜。\n宝髻慵梳，香笺折破，果见中、高高名第。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8246, '如梦令', '李石', '桥上水光浮雪。\n桥下柳阴遮月。\n梦里去寻香，露冷五更时节。\n胡蝶。\n胡蝶。\n飞过闲红千叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8247, '如梦令', '李石', '忆被金尊劝倒。\n灯下红香围绕。\n别後有谁怜，一任春残莺老。\n烦恼。\n烦恼。\n肠断绿杨芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8248, '生查子', '李石', '小桃小杏红，和雨和烟瘦。\n不是点燕脂，素面偏宜酒。\n也是惯伤春，可惜闲时候。\n正要画眉人，与作双蛾斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8249, '生查子', '李石', '新花上苑枝，枝上娇莺语。\n日日抱花心，啄破燕脂雨。\n莺飞莺去时，谁与花为主。\n守等却飞来，再见花开处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8250, '生查子', '李石', '今年花发时，燕子双双语。\n谁与卷珠帘，人在花间住。\n明年花发时，燕语人何处。\n且与寄书来，人往江南去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8251, '生查子', '李石', '荷花人面红，月影波心见。\n扇子倒拈来，敲落红香片。\n窗下翦灯花，今日眉深浅。\n留得镜中看，蹙破春山远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8252, '捣练子', '李石', '斟别酒，问东君。\n一年一度一回新。\n看百花，飘舞茵。\n斟别酒，问行人。\n莫将别泪罗巾。\n早归来，依旧春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8253, '捣练子', '李石', '腰束素，鬓垂鸦。\n无情笑面醉犹遮。\n扇儿扇，瞥见些。\n双凤小，玉钗斜。\n芙蓉衫子藕花纱。\n戴一枝，卜花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8254, '长相思', '李石', '花飞飞。\n絮飞飞。\n三月江南烟雨时。\n楼台春树迷。\n双莺儿。\n双燕儿。\n桥北桥南相对啼。\n行人犹未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8255, '长相思', '李石', '红藕丝。\n白藕丝。\n艾虎衫裁金缕衣。\n钗头双荔枝。\n鬓符儿。\n背符儿。\n鬼在心头符怎知。\n相思十二时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8256, '长相思', '李石', '花深红。\n花浅红。\n桃杏浅深花不同。\n年年吹暖风。\n莺语中。\n燕语中。\n唤起碧窗春睡浓。\n日高花影重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8257, '乌夜啼', '李石', '红软榴花脸晕，绿愁杨柳眉疏。\n日长院宇闲消遣，荔子赌樗蒲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8258, '乌夜啼', '李石', '鸾镜愁添眉黛，罗裙瘦减腰肢。\n一回见了一回病，弹指误佳期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8259, '乌夜啼', '李石', '绣阁和烟飞絮，粉墙映日吹红。\n花花柳柳成阴处，休恨五更风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8260, '朝中措', '李石', '飘飘仙袂缕黄金。\n相对弄清音。\n几度教人误听，当窗绿暗红深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8261, '朝中措', '李石', '绿杨庭院觉深沈。\n曾听一莺吟。\n今夜却成容易，双莲步步摇金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8262, '朝中措', '李石', '凌波庭院藕香残。\n银烛夜生寒。\n两点眉尖新恨，别来谁画遥山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8263, '一翦梅', '李石', '红映阑干绿映阶。\n闲闷闲愁，独自徘徊。\n天涯消息几时归，别後无书有梦来。\n後院棠梨昨夜开。\n雨急风忙次第催。\n罗衣消瘦却春寒，莫管红英，一任苍苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8264, '一翦梅', '李石', '百濯香残恨未消。\n万绪千丝，莲藕芭蕉。\n临岐犹自说前时，轻翦乌云解翠翘。\n雨意重来风已飘。\n南陌行人折柳条。\n此间无计可留连，枕上今宵。\n马上明朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8265, '醉落魄・一斛珠', '李石', '天低日暮。\n清商一曲行人住。\n著人意态如飞絮。\n才泊春衫，却被风吹去。\n朝期暮约浑无据。\n同心结尽千千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8266, '临江仙', '李石', '烟柳疏疏人悄悄，画楼风外吹笙。\n倚阑闻唤小红声。\n熏香临欲睡，玉漏已三更。\n坐待不来来又去，一方明月中庭。\n粉墙东畔小桥横。\n起来花影下，扇子扑飞萤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8267, '临江仙', '李石', '八曲阑干垂手处，烛光花影疏疏。\n一尊共饮记当初。\n彩毫浓点，双带要人书。\n日暮不来朱户隔，碧云高挂蟾蜍。\n琴心密约总成虚。\n醉中言语，醒後忆人无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8268, '临江仙', '李石', '有宅一区家四壁，年年花柳深村。\n父兄随处宴鸡豚。\n折腰归去，何苦傍侯门。\n拟射九乌留白日，假饶立到黄昏。\n卧龙老矣及三分。\n不如把手，堂上宴芳尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8269, '临江仙', '李石', '九九之年逢降庆，生年生日同时。\n金花紫诰鬓银丝。\n乞身香火地，日戏老莱衣。\n浑舍集成千岁会，子孙三世庭闱。\n共将春酒祝金卮。\n蟠桃三月暮，莫怪看花迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8270, '满庭芳', '李石', '江草抽心，江云弄碧，江波依旧东流。\n别筵初散，行客上兰舟。\n休唱阳关旧曲，青青柳、无限轻柔。\n应争记，三年乐事，珠翠拥鳌头。\n离愁。\n知几许，花梢著雨，红泪难收。\n看烟火吴天，万里悠悠。\n一望珠宫绛阙，蓬莱路、应在皇州。\n仍回首，蜀山万点，明月满南楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8271, '木兰花・玉楼春', '李石', '辘轳轭轭门前井。\n不道隔窗人睡醒。\n柔弦无力玉琴寒，残麝彻心金鸭冷。\n一莺啼破帘栊静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8272, '木兰花・玉楼春', '李石', '一春闲却花时候。\n小阁幽窗长独守。\n晴云南浦梦还空，初月西楼眉也皱。\n马嘶何日门前柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8273, '南乡子', '李石', '十月小春天。\n红叶红花半雨烟。\n点滴红酥真耐冷，争先。\n夺取梅魂斗雪妍。\n坐待晓莺迁。\n织女机头蜀锦川。\n枝上绿毛幺凤子，飞仙。\n乞与双双作被眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8274, '南乡子', '李石', '裹帽拈吟须。\n我是蓬莱旧酒徒。\n除了茅君谁是伴，麻姑。\n洞里仙浆不用沽。\n弱水渺江湖。\n醉里笙歌醉里扶。\n纵饮菊潭餐菊蕊，茱萸。\n医得人间瘦也无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8275, '西江月', '李石', '一脉分溪浅绿，数枝约岸猗红。\n小船横系碧芦丛。\n似我江湖春梦。\n晒网渔归别浦，举头雁度晴空。\n短蓑独宿月明中。\n醉笛一声风弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8276, '八声甘州', '李石', '向吴天万里、一叶归舟。\n岁月尽悠悠。\n有清歌一曲，醉中自笑，酒醒还愁。\n几度春莺啭午，塞雁横秋。\n渔笛蓑衣底，依旧勾收。\n多谢飞来双鹤，□水边林下，伴我遨游。\n笑老莱晨昏，色笑为亲留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8277, '雨中花慢', '李石', '潋滟云霞，空雾雨，长堤柳色如茵。\n问西湖何似，粉面初匀。\n尽道软红香土，东华风月俱新。\n旧游如梦，尘缘未断，几度逢春。\n蓬莱阁上，风流二老，相携把酒论文。\n最好是、四娘桃李，约近东邻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8278, '醉蓬莱', '李石', '望长江东去，逐客西来，几逢秋杪。\n江草江花，约鬓丝俱老。\n朝士红萸，佳人雪藕，别後忍孤欢笑。\n楚水楼台，巫山宫殿，五湖烟渺。\n又是征帆，万里行去，旧恨鲈鱼，昔日鸥鸟。\n九日江南，上蓬莱仙岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8279, '渔家傲', '李石', '西去征鸿东去水。\n几重别恨千山里。\n梦绕绿窗书半纸。\n何处是。\n桃花溪畔人千里。\n瘦玉倚香愁黛翠。\n劝人须要人先醉。\n问道明朝行也未。\n犹自记。\n灯前背立偷弹泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8280, '卜算子', '李石', '密叶蜡蜂房，花下频来往。\n不知辛苦为谁甜，山月梅花上。\n玉质紫金衣，香雪随风荡。\n人间唤作返魂梅，仍是蜂儿样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8281, '捣练子', '李石', '心自小，玉钗头。\n月娥飞下白苹洲。\n水中仙，月下游。\n江汉佩，洞庭舟。\n香名薄幸寄青楼。\n问何如，打泊浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8282, '捣练子', '李石', '红粉里，绛金裳。\n一卮仙酒艳晨妆。\n醉温柔，别有乡。\n清暑殿，藕风凉。\n鸡头擘破误君王。\n泣梨花，春梦长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8283, '谢池春', '李石', '烟雨池塘，绿野乍添春涨。\n凤楼高、珠帘卷上。\n金柔玉困，舞腰肢相向。\n似玉人、瘦时模样。\n离亭别後，试问阳关谁唱。\n对青春、翻成怅望。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8284, '出塞・谒金门', '李石', '花树树。\n吹碎胭脂红雨。\n将谓郎来推绣户。\n暖风摇竹坞。\n睡起栏干凝伫。\n漠漠红楼飞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8285, '望江南・忆江南', '康与之', '重阳日，四面雨垂垂。\n戏马台前泥拍肚，龙山路上水平脐。\n淹浸倒东篱。\n茱萸胖，黄菊湿齑齑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8286, '满江红', '康与之', '叹诗书万卷、致君人，番沈陆。\n……且置请缨封万户，径须卖剑酬黄犊。\n恸当年、寂寞贾长沙，伤时哭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8287, '鹧鸪天', '康与之', '解将天上千年艳，换得人间九日黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8288, '忆秦娥', '康与之', '春寂寞。\n长安古道东风恶。\n东风恶。\n胭脂满地，杏花零落。\n臂销不奈黄金约。\n天寒犹怯春衫薄。\n春衫薄。\n不禁珠泪，为君弹却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8289, '洞仙歌令・洞仙歌', '康与之', '若耶溪路。\n别岸花无数。\n欲敛娇红向人语。\n与绿荷、相倚恨，回首西风，波淼淼、三十六陂烟雨。\n新妆明照水，汀渚生香，不嫁东风被谁误。\n遣踟蹰、骚客意，千里绵绵，仙浪远、何处凌波微步。\n想南浦、潮生画桡归，正月晓风清，断肠凝伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8290, '西江月', '康与之', '名与牡丹联谱，南珍独比江瑶。\n闽山入贡冠前朝。\n露叶风枝袅袅。\n香玉满苞仙液，绉红圆戚鲛绡。\n华清宫殿蜀山遥。\n一骑红尘失笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8291, '曲游春', '康与之', '脸薄难藏泪，恨柳风，不与吹断行色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8292, '舞杨花', '康与之', '牡丹半坼初经雨，雕槛翠幕朝阳。\n娇困倚动风，羞谢了群芳。\n洗烟凝露向清晓，步瑶台、月底霓裳。\n轻笑淡拂宫黄。\n浅拟飞燕新妆。\n杨柳啼鸦昼永，正秋千庭馆，风絮池塘。\n三十六宫，簪艳粉浓香。\n慈宁玉殿庆清赏，占东君、谁比花王。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8293, '瑞鹤仙', '康与之', '瑞烟浮禁苑。\n正绛阙春回，新正方半。\n冰轮桂华满。\n溢花衢歌市，芙蓉开遍。\n龙楼两观。\n见银烛、星球有烂。\n卷珠帘、尽日笙歌，盛集宝钗金钏。\n堪羡。\n绮罗丛里，兰麝香中，正宜游玩。\n风柔夜暖。\n花影乱，笑声喧。\n闹蛾儿满路，成团打块，簇著冠儿斗转。\n喜皇都、旧日风光，太平再见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8294, '瑞鹤仙', '康与之', '薄寒罗袖怯。\n教小玉添香，被翻宫。\n兰缸半明灭。\n听几声归雁，一帘微月。\n情波恨叶。\n索新词、犹自怨别。\n梦回时、雪暖酥凝，掠鬓宝鸳钗折。\n凄切。\n纹窗描绣，旧谱寻棋，变成虚设。\n同心对结。\n重来是，甚时节。\n怅姑苏台上，征帆何许，隐隐遥山万叠。\n袖红绡、独立无言，偷弹泪血。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8295, '汉宫春', '康与之', '云海沈沈，峭寒收建章。\n雪残鹊。\n华灯照夜，万井禁城行乐。\n春随鬓影，映参差、柳丝梅萼。\n丹禁杳，鳌峰对耸，三山上通寥廓。\n春衫绣罗香薄。\n步金莲影下，三千绰约。\n冰轮桂满，皓色冷浸楼阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8296, '喜迁莺', '康与之', '腊残春早。\n正帘幕护寒，楼台清晓。\n宝运当千，佳辰馀五，嵩岳诞生元老。\n帝遣阜安宗社，人仰雍容廊庙。\n尽总道，是文章孔孟，勋庸周召。\n师表。\n方眷遇，鱼水君臣，须信从来少。\n玉带金鱼，朱颜绿鬓，占断世间荣耀。\n篆刻鼎彝将遍，整顿乾坤都了。\n愿岁岁，见柳梢青浅，梅英红小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8297, '喜迁莺', '康与之', '秋寒初劲。\n看云路雁来，碧天如镜。\n湘浦烟深，衡阳沙远，风外几行斜阵。\n回首塞门何处，故国关河重省。\n汉使老，认上林欲下，徘徊清影。\n江南烟水暝。\n声过小楼，烛暗金猊冷。\n送目鸣琴，裁诗挑锦，此恨此情无尽。\n梦想洞庭飞下，散入云涛千顷。\n过尽也，奈社陵人远，玉关无信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8298, '丑奴儿令・采桑子', '康与之', '冯夷剪碎澄溪练，飞下同云。\n著地无痕。\n柳絮梅花处处春。\n山阴此夜明如昼，月满前村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8299, '丑奴儿令・采桑子', '康与之', '红楼紫陌青春路，柳色皇州。\n月淡烟柔。\n袅袅亭亭不自由。\n旧时扶上雕鞍处，此地重游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8300, '诉衷情令', '康与之', '郁孤台上立多时。\n烟晚暮云低。\n山川城郭良是，回首昔人非。\n今古事，只堪悲。\n此心知。\n一尊芳酒，慷慨悲歌，月堕人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8301, '诉衷情令', '康与之', '阿房废址汉荒丘。\n狐兔又群游。\n豪华尽成春梦，留下古今愁。\n君莫上，古原头。\n泪难收。\n夕阳西下，塞雁南飞，渭水东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8302, '菩萨蛮令・菩萨蛮', '康与之', '秦时宫殿咸阳里。\n千门万户连云起。\n复道互西东。\n不禁三月风。\n汉唐乘王气。\n万岁千秋计。\n毕竟是荒丘。\n荆榛满地愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8303, '菩萨蛮令・菩萨蛮', '康与之', '龙蟠虎踞金陵郡。\n古来六代豪华盛。\n缥凤不来游。\n台空江自流。\n下临全楚地。\n包举中原势。\n可惜草连天。\n晴郊狐兔眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8304, '感皇恩', '康与之', '一雨一番凉，江南秋兴。\n门掩苍苔锁寒径。\n红尘不到，尽日鸟啼人静。\n绿荷风已过，摇香柄。\n澹阴未解，园林清润。\n一片花飞堕红影。\n残书读尽，袖手高吟清咏。\n任从车马客，劳方寸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8305, '卖花声', '康与之', '蹙损远山眉。\n幽怨谁知。\n罗衾滴尽泪胭脂。\n夜过春寒愁未起，门外鸦啼。\n惆怅阻佳期。\n人在天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8306, '卖花声', '康与之', '愁拈断钗金。\n远信沈沈。\n秦筝调怨不成音。\n郎马不知何处也，楼外春深。\n好梦已难寻。\n夜夜馀衾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8307, '江城子', '康与之', '南溪二月雨初晴。\n四郊明。\n暖风轻。\n一雨一风，铺地落红英。\n枝上流莺啼劝我，春欲去，且留春。\n登临行乐慰闲情。\n过长亭。\n暮潮平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8308, '风入松', '康与之', '一宵风雨送春归。\n绿暗红稀。\n画楼整日无人到，与谁同拈花枝。\n门外蔷薇开也，枝头梅子酸时。\n玉人应是数归期。\n翠敛愁眉。\n塞鸿不到双鱼远，叹楼前、流水难西。\n新恨欲题红叶，东风满院花飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8309, '风入松', '康与之', '碧苔满地衬残红。\n绿树阴浓。\n晓莺啼破眉心事，旧愁新恨重重。\n翠黛不重扫，佳时每恨难同。\n花开花谢任东风。\n此恨无穷。\n梦魂拟逐杨花去，人休下帘栊。\n要见只凭清梦，几时真个相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8310, '谒金门', '康与之', '春又晚。\n风劲落红如剪。\n睡起绣床飞絮满。\n日长门半掩。\n不管离肠欲断。\n听尽梁间双燕。\n试上小楼还不见。\n楼前芳草远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8311, '长相思', '康与之', '南高峰。\n北高峰。\n一片湖光烟霭中。\n春来愁杀侬。\n郎意浓。\n妾意浓。\n油壁车轻郎马骢。\n相逢九里松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8312, '应天长', '康与之', '管弦绣陌，灯火画桥，尘香旧时归路。\n肠断萧娘，旧日风帘映朱户。\n莺能舞，花解语。\n念後约、顿成轻负。\n缓雕佩、独自归来，凭栏情绪。\n楚岫在何处。\n香梦悠悠，花月更谁主。\n惆怅後期，空有鳞鸿寄纨素。\n枕前泪，窗外雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8313, '玉楼春令・玉楼春', '康与之', '青笺後约无凭据。\n误我碧桃花下语。\n谁将消息问刘郎，怅望玉溪溪上路。\n春来无限伤情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8314, '风入松', '康与之', '画桥流水欲平阑。\n雨後青山。\n去年芳草今年恨，恨香车、不逐雕鞍。\n红杏墙头院落，绿杨楼外秋千。\n谢娘别後忆前欢。\n泪滴春衫。\n柔荑共折香红处，劝东风、且与流连。\n早是相思瘦损，梅花谢了春寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8315, '忆少年令・忆少年', '康与之', '双龙烛影，千门夜色，三五宴瑶台。\n舞蝶随香，飞蝉扑鬓，人自蕊宫来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8316, '风流子', '康与之', '结客少年场。\n繁华梦，当日赏风光。\n红灯九街，买移花市，画楼十里，特地梅妆。\n醉魂荡，龙跳万字，鲸饮吸三江。\n娇随钿车，玉骢南陌，喜摇双桨，红袖横塘。\n天涯归期阻，衡阳雁不到，路隔三湘。\n难见谢娘诗好，苏小歌长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8317, '瑞鹤仙令・临江仙', '康与之', '樱桃落尽春归去，蝶翻金粉双飞。\n子规啼恨小楼西。\n曲屏珠箔晚，惆怅卷金泥。\n门巷寂寥人去後，望残烟草低迷。\n闲寻旧曲玉笙悲。\n关山千里恨，云汉月重规。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8318, '杏花天', '康与之', '帝城柳色藏春絮。\n嫩绿满、游人归路。\n残红剩蕊留春住。\n无奈霏微细雨。\n南陌上、玉佩钿车，怅紫陌、青门日暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8319, '卜算子', '康与之', '潮生浦口云，潮落津头树。\n潮本无心落又生，人自来还去。\n今古短长亭，送往迎来处。\n老尽东西南北人，亭下潮如故。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8320, '金菊对芙蓉', '康与之', '梧叶飘黄，万山空翠，断霞流水争辉。\n正金风西起，海燕东归。\n凭栏不见南来雁，望故人、消息迟迟。\n木樨开後，不应误我，好景良时。\n只念独守孤帏。\n把枕前嘱付，一旦分飞。\n上秦楼游赏，酒花迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8321, '满江红', '康与之', '恼杀行人，东风里、为谁啼血。\n正青春未老，流莺方歇。\n蝴蝶枕前颠倒梦，杏花枝上朦胧月。\n问天涯、何事苦关情，思离别。\n声一唤，肠千结。\n闽岭外，江南陌。\n正是堤杨柳，翠条堪折。\n镇日叮咛千百遍，只将一句频频说。\n道不如归去不如归，伤情切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8322, '失调名', '康与之', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8323, '满庭芳', '康与之', '霜幕风帘，闲斋小户，素蟾初上雕笼。\n玉杯，还与可人同。\n古鼎沈烟篆细，玉笋破、橙橘香浓。\n梳妆懒，脂轻粉薄，约略淡眉峰。\n清新，歌几许，低随慢唱，语笑相供。\n道文书针线，今夜休攻。\n莫厌兰膏更继，明朝又、粉冗匆匆。\n酩酊也，冠儿未卸，先把被儿烘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8324, '减字木兰花', '康与之', '杨花飘尽。\n云压绿阴风乍定。\n帘幕闲垂。\n弄语千般燕子飞。\n小楼深静。\n睡起残妆犹未整。\n梦不成归。\n泪滴斑斑金缕衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8325, '采桑子', '康与之', '晚来一霎风兼雨，洗尽炎光。\n理罢笙篁。\n却对菱花淡淡妆。\n绛绡缕薄冰肌莹，雪腻酥香。\n笑语檀郎。\n今夜纱厨枕簟凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8326, '荷叶铺水面', '康与之', '春光艳冶，游人踏绿苔。\n千红万紫竞香开。\n暖风拂鼻籁，蓦地暗香透满怀。\n荼縻似锦裁。\n娇红间绿白，只怕迅速春回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8327, '菩萨蛮', '康与之', '弱柳小腰身。\n双双蛾翠颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8328, '水龙吟', '曾觌', '楚天千里无云，露华洗出秋容净。\n银蟾台榭，玉壶天地，参差桂影。\n鸳瓦寒生，画檐光射，碧梧金井。\n听韶华半夜，江梅三弄，风袅袅、良宵永。\n携手西园宴罢，下瑶台、醉魂初醒。\n吹箫仙子，骖鸾归路，一襟清兴。\n鹊楼高，建章门迥，星河耿耿。\n看沧江潮上，丹枫落叶，浸关山冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8329, '念奴娇', '曾觌', '霁天湛碧，正新凉风露，冰壶清彻。\n河汉无声□□□，涌出银蟾孤绝。\n岩桂香飘，井梧影转，冷浸宫袍洁。\n西厢往事，一帘幽梦凄切。\n肠断楚峡云归，尊前无绪，只有愁如发。\n此夕娥应也恨，冷落琼楼金阙。\n禁漏迢迢，边鸿杳杳，密意凭谁说。\n阑干星汉，落梅三弄初阕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8330, '念奴娇', '曾觌', '群花渐老，向晓来微雨，芳心初拆。\n拂掠娇红香旖旎，浑欲不胜春色。\n淡月梨花，新晴繁杏，装点成标格。\n风光都在，半开深院人寂。\n刚要买断东风，袅栾枝低映，舞茵歌席。\n记得当时曾共赏，玉人纤手轻摘。\n醉里妖饶，醒时风韵，比并堪端的。\n谁知憔悴，对花空恁思忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8331, '念奴娇', '曾觌', '人生行乐，算一春欢赏，都来几日。\n绿暗红稀春已去，赢得星星头白。\n醉里狂歌，花前起舞，拚罚金杯百。\n淋漓宫锦，忍辜妖艳姿色。\n须信殿得韶光，只愁花谢，又作经年别。\n嫩紫娇红还解语，应为主人留客。\n月落乌啼，酒阑烛暗，离绪伤吴越。\n竹西歌吹，不堪老去重忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8332, '念奴娇', '曾觌', '媚容素态，比群花、赢了风流颜色。\n昵枕低帏销受得，□□轻怜深惜。\n怎望如今，瓶沈簪折，蓦地成疏隔。\n□□夕雨，甚时重见踪迹。\n门外暂泊兰舟，一行霜树，□一重山碧。\n泪眼相看争忍望，天际孤村寒驿。\n卞水无情，催人东去，去也添愁寂。\n鳞鸿方便，为人传个消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8333, '瑞鹤仙', '曾觌', '陡寒生翠幕。\n冻云垂，缤纷飞雪初落。\n萦风度池阁。\n袅馀妍，时趁舞腰纤弱。\n江天漠漠。\n认残梅、吹散画角。\n正貂裘乍怯，黄昏院宇，入檐飘泊。\n依约。\n银河迢递，种玉群仙，共骖鸾鹤。\n东君未觉。\n先春绽，万花萼。\n向尊前、已喜丰年呈瑞，人间何事最乐。\n拥笙歌、绣阁低帷，纵欢细酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8334, '倾杯乐', '曾觌', '锦帐寒添，画檐雀噪，冻云布野。\n望空际、瑶峰微吐，琼花初绽，江山如画。\n裁冰剪水装鸳瓦。\n杳旗亭路，依稀管弦台榭。\n倚小楼佳兴，一行珠帘不下。\n随缕板、歌声闲暇。\n傍翠袖云鬟、怜艳冶。\n似佯醉、不奈娇羞，浓欢旋学风雅。\n相暝色、双鸾舞罢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8335, '木兰花慢', '曾觌', '正枝头荔子，晚红皱、袅熏风。\n对碧瓦迷云，青山似浪，返照浮空。\n高台称吟眺处，□繁华、清胜两无穷。\n帘卷榕阴暮合，万家香霭溟。\n年光冉冉逐飞鸿。\n叹雨迹云踪。\n渐暑退兰房，凉生象簟，知与谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8336, '水调歌头', '曾觌', '溪山多胜事，诗酒辨清游。\n主人为我，增茸台榭足凝眸。\n仿佛玉壶天地，隐见瀛洲风月，千首傲王侯。\n谁与共登眺，公子气横秋。\n记当年，曾共醉，庾公楼。\n一杯此际，重话前事逐东流。\n多谢兼金清唱，更拟重阳佳节，菊任扶头。\n但愿身长健，浮世拚悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8337, '水调歌头', '曾觌', '图画上鳞阁，莫使鬓先秋。\n壮年豪气，无奈黯黯阵云浮。\n常记青油幕下，一矢聊城飞去，谈笑静边头。\n勋业出无意，非为快恩雠。\n卷龙韬，随凤诏，与时谋。\n朱幡皂盖南下，聊试海山州。\n邂逅故人相见，俯仰浮生今古，蝼蚁共王侯。\n万事偶然耳，风月恣嬉游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8338, '水调歌头', '曾觌', '长乐富山水，杖屡足追游。\n故人千里，西望双剑黯回眸。\n多谢扁舟乘兴，慰我天涯羁思，何必羡封侯。\n暮雨疏帘卷，爽气飒如秋。\n送征鸿，浮大白，倚危楼。\n参横月落，耿耿河汉近人流。\n堪叹人生离合，後日征鞍西去，别语却从头。\n老矣江边路，清兴漫悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8339, '醉蓬莱', '曾觌', '向逍遥物外，造化工夫，做成幽致。\n杳霭壶天，映满空苍翠。\n耸秀峰峦，媚春花木，对玉阶金砌。\n方丈瀛洲，非烟非雾，恍移平地。\n况值良辰，宴游时候，日永风和，暮春天气。\n金母龟台，傍碧桃阴里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8340, '满庭芳', '曾觌', '冶态轻盈，香风摇荡，画栏淑景初长。\n彩霞深处，明艳夺昭阳。\n试问沈香旧事，应劝我、莫负韶光。\n多情是，低徊顾影，云幕淡微凉。\n人间，春更好，一枝斜插，犹记疏狂。\n到如今潘鬓，暗点吴霜。\n乐事直须年少，何妨拚、一饮千觞。\n醺醺醉，壶天向晚，春思正悠扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8341, '燕山亭', '曾觌', '河汉风情，庭户夜凉，皓月澄秋时候。\n冰鉴乍开，跨海飞来，光掩满天星斗。\n四卷珠帘，渐移影、宝阶鸳。\n还又。\n看岁岁婵娟，向人依旧。\n朱邸高宴簪缨，正歌吹瑶台，舞翻宫袖。\n银管竞酬，棣萼相辉，风流古来谁有。\n玉笛横空，更听彻、裳霓三奏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8342, '燕山亭', '曾觌', '玉立明光，才业冠伦，汉历方承休运。\n江左奏功，塞垒宣威，紫绶几垂金印。\n岁晚归来，望丹极、新清氛。\n忠愤。\n著挠节朋俦，便成嘉遁。\n千载云海茫茫，记举目新亭，壮怀难尽。\n蝴蝶梦惊，化鹤飞还，荣华等闲一瞬。\n七十尊前，算畴昔、都无可恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8343, '沁园春', '曾觌', '更漏迢迢，乍寒天气，画烛对床。\n正井梧飘砌，边鸿度月，故人何处，水远山长。\n老去功名，年来情绪，宽尽寒衣销旧香。\n除非是，仗蛮笺象管，时伴吟窗。\n词章。\n莫话行藏。\n且喜见捷书来帝乡。\n看锐师云合，妖氛电扫，随堤宫柳，依旧成行。\n梦绕他年，青门紫陌，对酒花前歌正当。\n空成恨，奈潘郎两鬓，新点吴霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8344, '喜迁莺', '曾觌', '七闽形胜。\n镇南纪会府，山川交映。\n箫鼓喧天，绮罗盈市，不负四时风景。\n共喜太平无事，岂料潢池不逞。\n殄群丑，看一鼓雷奔，沧溟波静。\n指纵诗书帅，曾到凤池，密勿陪几政。\n暂掩筹帏，催分战舰，总出智谋先定。\n想见捷书初上，尽道臣贤主圣。\n正图旧，听重宣丹诏，归调金鼎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8345, '金人捧露盘', '曾觌', '记神京、繁华地，旧游踪。\n正御沟、春水溶溶。\n平康巷陌，绣鞍金勒跃青骢。\n解衣沽酒醉弦管，柳绿花红。\n到如今、馀霜鬓，嗟前事、梦魂中。\n但寒烟、满目飞蓬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8346, '传言玉女', '曾觌', '凤阙龙楼，清夜月华初照。\n万点星球，护花梢寒峭。\n华胥梦里，老去欢情终少。\n花愁醉闷，总消除了。\n紫陌嬉游，不似少年怀抱。\n珠帘十里，听笙箫声香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8347, '好事近', '曾觌', '摇扬杏花风，迟日淡阴双阙。\n丝管缓随檀板，看舞腰回雪。\n龙舟闲舣画桥边，须趁好花折。\n频劝御杯宜满，正清歌初阕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8348, '好事近', '曾觌', '一梦别长安，山路雨斜风细。\n行到子陵滩畔，谢主人深意。\n多情低唱下梁尘，拚十分沈醉。\n去也为伊消瘦，悄不禁思忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8349, '好事近', '曾觌', '霁雪好风光，恰是相逢时节。\n酒量不禁频劝，便醉倒人侧。\n严城更漏夜厌厌，应有断肠客。\n莫问落梅三弄，喜一枝曾折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8350, '柳梢青', '曾觌', '梅粉轻匀。\n和风布暖，香径无尘。\n凤阁凌虚，龙池澄碧，芳意鳞鳞。\n清时酒圣花神。\n对内苑、风光又新。\n一部仙韶，九重鸾仗，天上长春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8351, '柳梢青', '曾觌', '花柳争春。\n湖山竟秀，恰近清明。\n绮席从容，兰舟摇曳，稳泛波平。\n君恩许宴簪缨。\n密座促、仍多故情。\n一部清音，两行红粉，醉入严城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8352, '柳梢青', '曾觌', '品雅风流，端端正正，堪人怜惜。\n因甚新来，眉儿不展，愁情如织。\n倡条冶叶无情，犹为他、千思万忆。\n据恁当初，真心实意，如何亏得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8353, '春光好', '曾觌', '胭脂腻，粉光轻。\n正新晴。\n枝上闹红无处著，近清明。\n仙娥进酒多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8354, '春光好', '曾觌', '心下事，不思量。\n自难忘。\n花底梦回春漠漠，恨偏长。\n闲日多少韶光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8355, '春光好', '曾觌', '槐阴密，蔗浆寒。\n荔枝丹。\n珍重主人怜客意，荐雕盘。\n多情翠袖凭栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8356, '减字木兰花', '曾觌', '一声杜宇。\n满地落红愁不语。\n国色春娇。\n不逐风前柳絮飘。\n珠帘休卷。\n爱惜龙香藏粉艳。\n胜友俱来。\n同醉君恩倒玉杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8357, '点绛唇', '曾觌', '璧月香风，万家帘幕烟如昼。\n闹蛾雪柳。\n人似梅花瘦。\n行乐清时，莫惜笙歌奏。\n更阑後。\n满斟金斗。\n且醉厌厌酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8358, '点绛唇', '曾觌', '细雨斜风，上元灯火还空过。\n下帘孤坐。\n老去知因果。\n风月词情，冷落教谁和。\n今忘我。\n静中看破。\n万事空花堕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8359, '浣溪沙', '曾觌', '艳杏红芳透粉肌。\n沈香亭宴太真妃。\n新晴庭馆燕来迟。\n试抹么弦妆半掩，满斟绿醑袖交飞。\n九重天上捧金卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8360, '浣溪沙', '曾觌', '元是昭阳宫里人。\n惊鸿宛转掌中身。\n只疑飞过洞庭云。\n按彻凉州莲步紧，好花风袅一枝新。\n画堂香暖不胜春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8361, '浣溪沙', '曾觌', '绮陌寻芳惜少年。\n长楸走马著金鞭。\n玉楼春醉杏花前。\n憔悴如今谁作伴，别离还近养花天。\n碧云凝处忆婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8362, '浣溪沙', '曾觌', '一扇熏风入座凉。\n轻云微雨弄晴光。\n绿团梅子未成黄。\n渐近日长愁闷处，更堪羁旅送归。\n乱山重叠水茫茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8363, '钗头凤・撷坊词', '曾觌', '华灯闹。\n银蟾照。\n万家罗幕香风透。\n金尊侧。\n花颜色。\n醉里人人，向人情极。\n惜惜惜。\n春寒峭。\n腰肢小。\n鬓云斜蛾儿袅。\n清宵寂。\n香闺隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8364, '诉衷情', '曾觌', '建章宫殿晚生寒。\n飞雪点朱阑。\n舞腰缓随檀板，轻絮春闲。\n愁思乱，酒肠悭。\n漏将残。\n玉人今夜，滴粉搓酥，应敛眉山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8365, '诉衷情', '曾觌', '半钩珠箔小扬州。\n春色在重楼。\n曾醉玳筵歌舞，楚梦苦难留。\n情脉脉，恨悠悠。\n几时休。\n大都人世，会少离多，总是闲愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8366, '诉衷情', '曾觌', '晚妆初试蕊珠宫。\n随步异香浓。\n檀槽缓垂鸾带，纤指拈春葱。\n莺语巧，上林中。\n正娇慵。\n暂教花下，帘影微开，多谢东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8367, '诉衷情', '曾觌', '兰亭曲水擅风流。\n移宴向清秋。\n黄花未应憔悴，盏面尚堪浮。\n围艳质，发歌喉。\n细相酬。\n明年此会，主人还是，在凤池头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8368, '踏莎行', '曾觌', '翠幄成阴，谁家帘幕。\n绮罗香拥处、觥筹错。\n清和将近，□春寒更薄。\n高歌看簌簌、梁尘落。\n好景良辰，人生行乐。\n金杯无奈是、苦相虐。\n残红飞尽，袅垂杨轻弱。\n来岁断不负、莺花约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8369, '眼儿媚', '曾觌', '花近清明晚风寒。\n锦幄兽香残。\n醺醺醉里，匆匆相见，重听哀弹。\n春情入指莺声碎，危柱不胜弦。\n十分得意，一场轻梦，淡月阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8370, '眼儿媚', '曾觌', '重劝离觞泪相看。\n寂寞上征鞍。\n临行欲话，风流心事，万绪千端。\n春光漫漫人千里，归梦绕长安。\n不堪向晚，孤城吹角，回首关山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8371, '蝶恋花', '曾觌', '翠箔垂云香喷雾。\n年少疏狂，载酒寻芳路。\n多少惜花春意绪。\n劝人金盏歌金缕。\n桃李飘零风景暮。\n只有闲愁，不逐流年去。\n旧事而今谁共语。\n画楼空指行云处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8372, '蝶恋花', '曾觌', '御柳风柔春正暖。\n紫殿朱楼，赫奕祥光远。\n十二玉龙迎凤辇。\n香腾锦绣闻弦管。\n扇却双鸾开宝宴。\n绿绕红围，宣劝金卮满。\n万岁千秋流宠眷。\n此身欲备昭阳燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8373, '隔浦莲・隔浦莲近拍', '曾觌', '凉秋湖上过雨。\n作意回商素。\n暗绿翻轻盖，萧然姑射俦侣。\n妆脸宜淡伫。\n红衣妒。\n步袜凌波去。\n异香度。\n天教占断，风汀月浦烟渚。\n纤尘不到，梦绕玉壶清处。\n多少芳心待怨诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8374, '浪淘沙', '曾觌', '一线海门来。\n雪喷云开。\n山移玉下瑶台。\n卷地西风吹不断，直到蓬莱。\n羯鼓噪春雷。\n鼍舞蛟回。\n歌楼鼓吹夕阳催。\n今古清愁流不尽，都一樽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8375, '蓦山溪', '曾觌', '催花小雨，轻把香尘洒。\n帘卷水亭风，梅影转、夕阳初下。\n靓妆窥鉴，鸳湛清漪，浮暗麝，剪芳琼，消得连城价。\n玉楼十二，寒怯铢衣挂。\n曾是绿华仙，眷馀情、新词如画。\n花随人圣，须信世无双，腾凤吹，驻銮舆，堪与瑶池亚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8376, '蓦山溪', '曾觌', '凋红减翠，正是清秋杪。\n深院袅香风，看梨花、一枝开早。\n珑璁映面，依约认娇颦，天淡淡，月溶溶，春意知多少。\n清明池馆，芳信年年好。\n更向五侯家，把江梅、风光占了。\n休教寂寞，辜负向人心，檀板响，宝杯倾，潘鬓从他老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8377, '感皇恩', '曾觌', '依旧惜春心，花枝常好。\n只恐尊前被花笑。\n少年青鬓，耐得几番重到。\n旧欢重记省，如天杳。\n绮陌青门，斜阳芳草。\n今古销沈送人老。\n帝城春事，又是等闲来了。\n乱红随过雨，莺声悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8378, '阮郎归', '曾觌', '柳阴庭馆占风光。\n呢喃清昼长。\n碧波新涨小池塘。\n双双蹴水忙。\n萍散漫，絮飘扬。\n轻盈体态狂。\n为怜流去落红香。\n衔将归画梁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8379, '鹧鸪天', '曾觌', '龙驭亲迎玉辇来。\n江梅枝上雪培堆。\n东风上苑春光到，更放金莲匝地开。\n腾凤吹，进瑶杯。\n两宫交劝正欢谐。\n父慈子孝从今数，准拟开筵一万回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8380, '鹧鸪天', '曾觌', '桃李飘零春已深。\n可怜轻负惜花心。\n尊前赖有红千叠，窗外休惊绿满林。\n灯灼灼，醉沈沈。\n笙歌丛里酒频斟。\n留欢且莫匆匆去，怅望春归何处寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8381, '鹧鸪天', '曾觌', '每上春泥向晓乾。\n花间幽鸟舞姗姗。\n年华不管人将老，门外东风依旧寒。\n投簪易，息机难。\n鹿门归路不曾关。\n羡君早觉无生法，识破南柯一梦间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8382, '鹧鸪天', '曾觌', '故乡寒食醉酡颜。\n秋千彩索眩斓斑。\n如今头上灰三斗，赢得疏慵到处闲。\n锺已动，漏将残。\n浮生犹恨别离难。\n镬汤转作清凉地，只在人心那样看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8383, '定风波', '曾觌', '捍拨金泥雅制新。\n紫檀槽映小腰身。\n娅姹雏莺相对语。\n欣睹。\n上林花底暖生春。\n飒飒胡沙飞指下。\n休讶。\n一般奇绝称精神。\n向道曲终多少意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8384, '定风波', '曾觌', '上苑芳初雨晴。\n香风袅袅泛轩楹。\n犹记洛阳开小宴。\n娇面。\n粉光依约认倾城。\n流落江南重此会。\n相对。\n金蕉蘸甲十分倾。\n怕见人间春更好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8385, '定风波', '曾觌', '极目秋光夕照开。\n潮头初自海门来。\n杳杳江天横一线。\n如练。\n疾驱千骑鼓声催。\n杰槛翠飞争徙倚。\n一行新雁去仍回。\n翠袖半空歌笑迥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8386, '定风波', '曾觌', '天语丁宁对未央。\n少摅素志向荆襄。\n赫家声今不坠。\n英伟。\n风姿飒爽紫髯郎。\n别酒一杯君莫阻。\n烛前粉艳俨成行。\n领略大堤花好处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8387, '南乡子', '曾觌', '霜月晚云收。\n萧瑟西风满院秋。\n雅会难期嗟易散，迟留。\n把酒听歌且劝酬。\n万事拚悠悠。\n只有情亲意未休。\n後夜扁舟烟浪里，回头。\n叶叶丹枫总是愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8388, '忆秦娥', '曾觌', '晴空碧。\n吴山染就丹青色。\n丹青色。\n西风摇落，可堪凄恻。\n世情冷暖君应识。\n鬓边各自侵寻白。\n侵寻白。\n江南江北，几时归得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8389, '忆秦娥', '曾觌', '西风节。\n碧云卷尽秋宵月。\n秋宵月。\n关河千里，照人离别。\n尊前俱是天涯客。\n那堪三载遥相忆。\n遥相忆。\n年光依旧，渐成华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8390, '忆秦娥', '曾觌', '暮云蹙。\n小亭带雪斟。\n斟。\n一声羌管，落梅蔌蔌。\n舞衣旋趁霓裳曲。\n倚阑相对人如玉。\n人如玉。\n锦屏罗幌，看成不足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8391, '忆秦娥', '曾觌', '正飞雪。\n园林一样梨花白。\n梨花白。\n画堂帘卷，暖生春色。\n嵇康转轴声幽噎。\n新来多病娇无力。\n娇无力。\n浅红转黛，自然标格。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8392, '忆秦娥', '曾觌', '风萧瑟。\n邯郸古道伤行客。\n伤行客。\n繁华一瞬，不堪思忆。\n丛台歌舞无消息。\n金尊玉管空尘迹。\n空尘迹。\n连天草树，暮云凝碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8393, '鹊桥仙', '曾觌', '菊花小摘，西风斜照，帘影轻笼暝色。\n玉尊侧倒莫辞空，□满座、宾朋弁侧。\n乡邦万里，北来年少，几个如今在得。\n扶头一任且留连，叹人世、光阴半百。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8394, '清平乐', '曾觌', '松姿不老。\n独立蓬莱杪。\n风卷流苏香雾晓。\n又是江梅开了。\n丹青早画麒麟。\n貂蝉自属王门。\n闻道碧桃花绽，一枝枝祝千春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8395, '长相思', '曾觌', '清夜长。\n泛玉觞。\n照座江梅花正芳。\n风传细细香。\n围艳妆。\n留醉乡。\n一曲清歌声绕梁。\n尊前人断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8396, '虞美人', '曾觌', '芙蓉池畔都开遍。\n又是西风晚。\n霁天碧净暝云收。\n渐看一轮冰魄、冷悬秋。\n闽山层叠迷归路。\n把酒宽愁绪。\n旧欢新恨几凄凉。\n暗想瀛洲何处、梦悠扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8397, '采桑子', '曾觌', '清明池馆晴还雨，绿涨溶溶。\n花里游蜂。\n宿粉栖香锦绣中。\n玉箫声断人何处，依旧春风。\n万点愁红。\n乱逐烟波总向东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8398, '朝中措', '曾觌', '画堂帘卷兽香浓。\n花上雪玲珑。\n平地十州三岛，蟠桃已试春红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8399, '朝中措', '曾觌', '画堂栏槛占韶光。\n端不负年芳。\n依倚东风向晓，数行浓淡仙妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8400, '朝中措', '曾觌', '金沙架上日璁珑。\n浓绿衬轻红。\n花下两行红袖，直疑春在壶中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8401, '朝中措', '曾觌', '休论社燕与秋鸿。\n时节太匆匆。\n海上一番微雨，朱门浓绿阴中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8402, '朝中措', '曾觌', '西湖南北旧游空。\n谁料一尊同。\n回首四年间事，浑如飞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8403, '朝中措', '曾觌', '双溪楼上凭栏时。\n潋滟泛金卮。\n醉到闹花深处，歌声遏住云飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8404, '朝中措', '曾觌', '雕车南陌碾香尘。\n一梦尚如新。\n回首旧游何在，柳烟花雾迷春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8405, '朝中措', '曾觌', '功名虽未压英游。\n一种旧风流。\n人世百年须到，如今七十春秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8406, '南柯子・南歌子', '曾觌', '璧月窥红粉，金莲映彩山。\n东风丝管满长安。\n移下十洲三岛、在人间。\n两两人初散，厌厌夜向阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8407, '南柯子・南歌子', '曾觌', '粉黛娉婷艳，芝兰笑语香。\n延平春色斗芬芳。\n不管清宵更漏、听霓裳。\n烛暗人方醉，杯传意更长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8408, '南柯子・南歌子', '曾觌', '绿阴侵檐净，红榴照眼明。\n主人开宴出倾城。\n正是雨馀天气、暑风清。\n别酒殷勤竟，危弦要妙声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8409, '南柯子・南歌子', '曾觌', '共禀阴阳数，谁知造化工。\n安闲百计总输公。\n掩映芙蓉花径、郡城东。\n风月三秋兴，尊一笑同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8410, '玉楼春', '曾觌', '江天暝色伤心目。\n冻鹊争投林下竹。\n四垂云幕一襟寒，片片飞花轻镂玉。\n美人试按新翻曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8411, '江神子・江城子', '曾觌', '故人情分转绸缪。\n小窗幽。\n话离愁。\n海阔天遥，鸿雁两悠悠。\n今日相逢谁较健，应怪我、鬓先秋。\n功名淅米在刀头。\n壮心休。\n弊貂裘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8412, '踏莎行', '曾觌', '凤翼双双，金泥细细。\n四弦斜抱拢纤指。\n紫檀香暖转春雷，嘈嘈切切声相继。\n弱柳腰肢，轻云情思。\n曲中多少风流事。\n红牙拍碎少年心，可怜辜负尊前意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8413, '生查子', '曾觌', '温柔乡内人，翠微阁中女。\n颜笑洛阳花，肌莹荆山玉。\n东君深有情，解与花为主。\n移傍楚峰居，容易为云雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8414, '青玉案', '曾觌', '蒲葵佳节初经雨。\n正栏槛、薰风度。\n满泛香蒲斟醑。\n故人情厚，艳歌娇舞。\n总是留宾处。\n榴花照眼江天暮。\n醉里春情荡轻絮。\n岂止卷帘通一顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8415, '青玉案', '曾觌', '乘鸾影里冰轮度。\n秋空净、南楼暮。\n袅袅天风吹玉兔。\n今宵只在，旧时圆处。\n往事难重数。\n天涯几见新霜露。\n怎得朱颜旧如故。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8416, '菩萨蛮', '曾觌', '杏花寒食佳期近。\n一帘烟雨琴书润。\n砌下水潺潺。\n玉笙吹暮寒。\n阳台云易散。\n往事寻思懒。\n花底醉相扶。\n当时人在无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8417, '菩萨蛮', '曾觌', '云烟漠漠秋容老。\n茅檐映水人家好。\n林叶未凋疏。\n远山横有无。\n平生耕钓事。\n若个安身事。\n劝君早归来。\n碧香新瓮开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8418, '西江月', '曾觌', '焕烂莲灯高下，参差梅影横斜。\n凭栏一目尽天涯。\n雪月交辉清夜。\n莫惜柔荑劝酒，从教醉脸红霞。\n烂银宫阙对仙家。\n一段风光如画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8419, '西江月', '曾觌', '桂苑旋生凉思，银河左界秋高。\n纤尘不动湛清霄。\n皓月照人偏好。\n诗为情多却减，酒因愁里难销。\n一声羌管梦魂劳。\n可惜风光虚老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8420, '西江月', '曾觌', '醉伴三千珠履，如登十二琼楼。\n壶天澄爽露华秋。\n滟滟金波酾酒。\n罗扇不随恩在，佳时须要人酬。\n麒麟阁画为谁留。\n只见浮生白首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8421, '绣带儿・好女儿', '曾觌', '潇洒陇头春。\n取次一枝新。\n还是东风来也，犹作未归人。\n微月淡烟村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8422, '卜算子', '曾觌', '数尽万般花，不比梅花韵。\n雪压风欺恁地寒，划地清喷香。\n半醉折归来，插向乌云鬓。\n不是愁人闷带花，花带愁人闷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8423, '柳梢青', '曾觌', '雨过风微。\n温泉浴倦，妃子妆迟。\n翠袖牵云，朱唇得酒，脸晕胭脂。\n年年海燕新归。\n怎奈向、黄昏恁时。\n倚遍琼干，烧残银烛，花又争知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8424, '柳梢青', '曾觌', '□杏堂前，清深窗外，宛似蓬瀛。\n珠翠分行，笙歌争奏，音韵清新。\n玉皇金母情亲。\n劝醑、更酬嗣君。\n地久天长，花朝月夕，天上长春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8425, '柳梢青', '曾觌', '小宴清秋。\n霎时见了，雨散云收。\n柳絮轻柔，梅花闲澹，宫院风流。\n空教梦绕青楼。\n待说个、相思又休。\n无奈情何，不来眼底，常在心头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8426, '醉落魄・一斛珠', '曾觌', '情深恨切。\n忆伊诮没些休歇。\n百般做处百厮惬。\n管是前生，曾负你冤业。\n临岐不忍匆匆别。\n两行珠泪流红颊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8427, '鹊桥仙', '曾觌', '娇波媚靥，尊前席上，只是寻常梳裹。\n温柔伶俐总天然，没半掏、教人看破。\n从来可恁，痴迷著相，百计消除不过。\n烟花不是不曾经，放不下、唯他一个。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8428, '清平乐', '曾觌', '艳苞初拆。\n偏借东君力。\n上苑梨花风露湿。\n新染胭脂颜色。\n玉人小立帘栊。\n轻匀媚脸妆红。\n斜插一枝云鬓，看谁剩□春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8429, '诉衷情', '曾觌', '闲窗静院漏声长。\n金鸭冷残香。\n几番梦回枕上，飞絮恨悠扬。\n身在此，意伊行。\n思量。\n不言不语，几许闲情，月上回廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8430, '浣溪沙', '曾觌', '谷雨郊园喜弄晴。\n满林璀璨缀繁星。\n筠篮新采绛珠倾。\n樊素扇边歌未发，葛洪炉内药初成。\n金盘乳酪齿流冰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8431, '壶中天慢・念奴娇', '曾觌', '素飙漾碧，看天衢稳送、一轮明月。\n翠水瀛壶人不到，比似世间秋别。\n玉手瑶笙，一时同色，小按霓裳叠。\n天津桥上，有人偷记新阙。\n当日谁幻银桥，阿瞒儿戏，一笑成痴绝。\n肯信群仙高宴处，移下水晶宫阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8432, '点绛唇', '黄公度', '嫩绿娇红，砌成别恨千千斗。\n短亭回首。\n不是缘春瘦。\n一曲阳关，杯送纤纤手。\n还知否。\n凤池归後。\n无路陪尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8433, '千秋岁', '黄公度', '郁葱佳气。\n天降麒麟瑞。\n回首处，江城外。\n一麾遗爱在，万口欢声沸。\n人乍远，危楼目断天无际。\n五马徘徊地。\n春色随归旆。\n寿水绿，壶山翠。\n风轻香篆直，日暖歌喉脆。\n椒觞举，人人尽祝千秋岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8434, '菩萨蛮', '黄公度', '高楼目断南来翼。\n玉人依旧无消息。\n愁绪促眉端。\n不随衣带宽。\n萋萋天外草。\n何处春归早。\n无语凭栏杆。\n竹声生暮寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8435, '青玉案', '黄公度', '邻鸡不管离怀苦。\n又还是、催人去。\n回首高城音信阻。\n霜桥月馆，水村烟市，总是思君处。\n残别袖燕支雨。\n谩留得、愁千缕。\n欲倩归鸿分付与。\n鸿飞不住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8436, '卜算子', '黄公度', '寒透小窗纱，漏断人初醒。\n翡翠屏间拾落钗，背立残影。\n欲去更踟蹰，离恨终难整。\n陇首流泉不忍闻，月落双溪冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8437, '好事近', '黄公度', '湖上送残春，已负别时归约。\n好在故园桃李，为谁开谁落。\n还家应是荔支天，浮蚁要人酌。\n莫把舞裙歌扇，便等闲抛却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8438, '菩萨蛮', '黄公度', '眉尖早识愁滋味。\n娇羞未解论心事。\n试问忆人不。\n无言但点头。\n嗔人归不早。\n故把金杯恼。\n醉看舞时腰。\n还如旧日娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8439, '卜算子', '黄公度', '薄宦各东西，往事随风雨。\n先自离歌不忍闻，又何况、春将暮。\n愁共落花多，人逐征鸿去。\n君向潇湘我向秦，後会知何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8440, '眼儿媚', '黄公度', '一枝雪里冷光浮。\n空自许清流。\n如今憔悴，蛮烟瘴雨，谁肯寻搜。\n昔年曾共孤芳醉，争插玉钗头。\n天涯幸有，惜花人在，杯酒相酬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8441, '朝中措', '黄公度', '幽香冷艳缀疏枝。\n横影卧霜溪。\n清楚浑如南郭，孤高胜似东篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8442, '朝中措', '黄公度', '屑瑶飘絮满层空。\n人在广寒宫。\n已觉楼台改观，渐看桃李春融。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8443, '一翦梅', '黄公度', '冷艳幽香冰玉姿。\n占断孤高，压尽芳菲。\n东君先暖向南枝。\n要使天涯，管领春归。\n不受人间莺蝶知。\n长是年年，雪约霜期。\n嫣然一笑百花迟。\n调鼎行看，结子黄时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8444, '满庭芳', '黄公度', '一径叉分，三亭鼎峙，小园别是清幽。\n曲阑低槛，春色四时留。\n怪石参差卧虎，长松偃蹇拿虬。\n携筇晚，风来万里，冷撼一天秋。\n优游。\n销永昼，琴尊左右，宾主风流。\n且偷闲，不妨身在南州。\n故国归帆隐隐，西往事悠悠。\n都休问，金钗十二，满酌听轻讴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8445, '浣溪沙', '黄公度', '风送清香过短墙。\n烟笼晚色近修篁。\n夕阳楼外角声长。\n欲去还留无限思，轻匀淡抹不成妆。\n一尊相对月生凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8446, '满庭芳', '黄公度', '枫岭摇丹，梧阶飘冷，一天风露惊秋。\n数丛篱下，滴滴晓香浮。\n不趁桃红李白，堪匹配、梅淡兰幽。\n孤芳晚，狂蜂戏蝶，长负岁寒愁。\n年年，重九日，龙山高会，彭泽清流。\n向尊前一笑，未觉淹留。\n况有甘滋玉铉，佳名算、合在金瓯。\n功成後，夕英饱饵，相伴赤松游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8447, '卜算子', '黄童', '不忍更回头，别泪多於雨。\n肺腑相看四十秋，奚止朝朝暮暮。\n何事值花时，又是匆匆去。\n过了阳关更向西，总是思兄处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8448, '临江仙', '倪', '结束征鞍临驿路，长林积雪消初。\n天回春色到平芜。\n不禁杯酒罢，便与故人疏。\n一曲阳关歌未彻，仆夫催驾修途。\n非君思我更谁欤。\n西风吹过雁，应有寄来书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8449, '临江仙', '倪', '万里凉风收积雨，一天晴碧新开。\n暮云归尽绝纤埃。\n金波明静夜，玉露湿苍苔。\n坐有霜髯诗酒客，平生见月衔杯。\n传闻丹诏日边来。\n莫辞通夕醉，对景且徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8450, '临江仙', '倪', '竹里轩窗真可爱，况当暑退新凉。\n檐前岩桂向人芳。\n清阴团翠盖，金粟淡微黄。\n坐到夜深明月出，好风时度幽香。\n莫辞沈醉倒霞觞。\n一枝聊赠子，早冠绿衣郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8451, '临江仙', '倪', '木落西风秋已半，正当璧月圆时。\n为登绝岭赋新诗。\n酒摇金凿落，波净碧琉璃。\n细看冰轮还有意，要君把盏休辞。\n看看两鬓欲成丝。\n明年当此夜，千里共相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8452, '临江仙', '倪', '茅屋三间临木杪，门前流水潺潺。\n林泉得趣喜身闲。\n开窗延翠竹，翦树纳青山。\n行乐政须筋力健，莫令白发衰颜。\n与君藜杖极跻攀。\n岭头舒望眼，天末数烟鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8453, '临江仙', '倪', '湖上青山千万叠，倏如阵马交驰。\n平湖百顷却逶迟。\n晴光相荡激，倒影落沦漪。\n何日漾舟深碧处，细听羌笛高吹。\n多君起我以新诗。\n未能同寓目，聊复一伸眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8454, '临江仙', '倪', '鸟语朝来新雨霁，杖藜呼我闲行。\n天晴腰脚上山轻。\n清风收积润，斜日弄新晴。\n最爱飞泉鸣野涧，清如万壑松声。\n回风溅沫湿冠缨。\n归来魂梦冷，幽响杂瑶琼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8455, '南歌子', '倪', '佳月当今夕，清尊尽客欢。\n参横斗转夜将阑。\n试泛小溪深处、与重看。\n野水从磨激，群山势郁盘。\n殷勤照我一杯残。\n更有谪仙奇句、斗清寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8456, '南歌子', '倪', '置酒临清夜，狂歌尽一欢。\n主人幽兴未渠阑。\n不负一天明月、卷帘看。\n影动黄金阙，光摇承露盘。\n君今双鬓未凋残。\n明岁玉堂兹夕、赏高寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8457, '南歌子', '倪', '对月中秋夜，传觞一笑欢。\n飘然逸兴未应阑。\n步向望湖桥上、倚阑看。\n松径风萧瑟，山腰路屈盘。\n南飞惊鹊五更残。\n小立水云光里、葛衣寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8458, '南歌子', '倪', '露下衣微湿，杯深意甚欢。\n西风吹暑十分阑。\n月满中秋、仍共故人看。\n酒好鹅黄嫩，茶珍小凤盘。\n醉吟不觉曙锺残。\n犹记归来扑面、井花寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8459, '南歌子', '倪', '嫩竹呈新绿，幽花露浅红。\n一檐苍翠落杯中。\n更有飞泉鸣佩、响丁东。\n乐事知难并，良辰得暂逢。\n晚风林下一尊同。\n便觉飘然身在、广寒宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8460, '南歌子', '倪', '积水凝深碧，斜阳散满红。\n扁舟轻漾白苹风。\n曲港孤村萦绕、路相通。\n野色浮尊净，荷香入座浓。\n胜游聊复五人同。\n恰似辋川当日、画图中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8461, '水调歌头', '倪', '昨夜狂雷怒，鞭起卞山龙。\n怪见朝来急雨，万木偃颠风。\n试看潭头落涧，一片练波飞出，河汉与天通。\n向晚馀霏落，巾已垫林宗。\n向高岩，凭曲槛，抚孤松。\n为雕好句，快倾桑落玉壶空。\n借问庐山三峡，与此飞流溅沫，今日定谁雄。\n乞与丹青手，写入紫微宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8462, '水调歌头', '倪', '风卷暮云尽，镜净一天秋。\n试把鹅黄新酒，细酌散闲愁。\n西望群山千叠，眇眇飞鸿没处，爽气与俱浮。\n且尽尊中绿，不用叹淹留。\n对西风，歌妙曲，意绸缪。\n万顷烟云奇变，所得过封侯。\n何事苦萦名利，便合绿蓑青笠，投绂早归休。\n他日君寻我，小艇钓寒流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8463, '念奴娇', '倪', '素秋向晚，正洞庭木落，疏林凋绿。\n惟有岩前双桂树，翠叶香浮金粟。\n皓月飞来，徘徊树杪，光射林间屋。\n夜深人静，好风忽起庭竹。\n俄顷万籁号鸣，清寒疑乍，听高岩悬瀑。\n起看碧天澄似洗，应费明河千斛。\n细酌鹅黄，宴搜奇句，逸气凌鸿鹄。\n浩歌归去，却愁踏碎琼玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8464, '减字木兰花', '倪', '凭高一览。\n紫翠相围光照眼。\n下瞰平湖。\n鹭立鸥飞意自如。\n天清境胜。\n云澹烟横鱼动镜。\n不是公诗。\n谁写新亭一段奇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8465, '减字木兰花', '倪', '超然远览。\n是我辈人方俱眼。\n默想江湖。\n何处山川略得如。\n凉秋最胜。\n万顷芙蕖盖明镜。\n更乞清诗。\n要见胸中一吐奇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8466, '减字木兰花', '倪', '新晴眺览。\n空翠相磨明老眼。\n水满溪湖。\n来往风帆得自如。\n天公济胜。\n明月当空开宝镜。\n咏谪仙诗。\n醉里骑鲸也大奇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8467, '减字木兰花', '倪', '岭头独览。\n诗料森然纷满眼。\n倒影摇湖。\n西子新妆定不如。\n溪南更胜。\n一片寒光明泻镜。\n赖有新诗。\n不负西山万叠奇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8468, '减字木兰花', '倪', '新诗细览。\n满纸骊珠光眩眼。\n高论倾湖。\n倒峡词源世不如。\n园池日胜。\n只恨孤鸾犹舞镜。\n陶写须诗。\n怪得连篇字字奇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8469, '减字木兰花', '倪', '雨馀还览。\n隐隐遥岑花病眼。\n嫩绿浮湖。\n百顷蒲萄染不如。\n晨光绝胜。\n不许纤尘微点镜。\n满目皆诗。\n莫怪骚人语益奇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8470, '蝶恋花', '倪', '长羡东林山下路。\n万叠云山，流水从倾注。\n两两三三飞白鹭。\n不须更觅神仙处。\n夜久望湖桥上语。\n乃渔歌，深入荷花去。\n修竹满山梅十亩。\n烦君为我成幽趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8471, '蝶恋花', '倪', '紫翠空庵畔路。\n满室松声，错认潺注。\n潇洒苹汀清立鹭。\n溪山真我归休处。\n老子平生无妄语。\n梅竹阴成，肯舍斯亭去。\n种秫会须盈百亩。\n非君谁识渊明趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8472, '蝶恋花', '倪', '我爱西湖湖上路。\n万顷沧波，河汉连天注。\n一片寒光明白鹭。\n依稀似我登临处。\n报答溪山须好语。\n痛饮高歌，何必骑鲸去。\n环舍清阴消几亩。\n无人肯办归来趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8473, '蝶恋花', '倪', '绿叶阴阴亭下路。\n修竹乔松，中有飞泉注。\n水满寒溪清照鹭。\n个中不住归何处。\n枝上幽禽相对语。\n细听声声，道不如归去。\n只待小园成数亩。\n归来占尽山中趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8474, '蝶恋花', '倪', '茅屋三间林临水路。\n几明窗，待把虫鱼注。\n我已忘机狎鸥鹭。\n溪山买得幽深处。\n小雨招君连夜语。\n野服纶巾，胜日寻君去。\n借问良田千万亩。\n何如乐取林泉趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8475, '朝中措', '倪', '森然修竹满晴窗。\n山色净明妆。\n无限凄凉古意，白苹红蓼斜阳。\n松风一枕借僧床。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8476, '西江月', '倪', '四面烟鬟绕翠，一川鸭绿摇光。\n危亭缥缈短松冈。\n把酒与君西望。\n万事尽皆前定，人生底用乾忙。\n只应醉里是家乡。\n且尽玉壶新酿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8477, '鹧鸪天', '倪', '萧瑟西风万里秋。\n暮云收尽月华流。\n偶然北海清尊满，况是西山爽气浮。\n登翠岭，更溪游。\n素光何处不清幽。\n悬知明岁君思我，今夕欢娱可罢休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8478, '鹧鸪天', '倪', '拟看今宵璧月秋。\n浮云却妒素光流。\n天公肯放冰轮出，我辈宁辞大白浮。\n穿翠密，极遨游。\n人间那得此深幽。\n金波若到清尊里，下笔联篇未肯休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8479, '鹧鸪天', '倪', '野旷无尘夕霭收。\n人间八月桂花秋。\n三更爽气山围座，万里凉风月满楼。\n登绝岭，小迟留。\n人言惟酒可忘忧。\n一杯径入无何有，未愧当年赤壁游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8480, '鹧鸪天', '倪', '去岁登高感叹长。\n今年九日倍幽凉。\n怀人独下西州泪，对菊谁空北海觞。\n夸酒量，斗新狂。\n尚馀醉墨在巾箱。\n眼前风物都非旧，祗有青山带夕阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8481, '菩萨蛮', '王之望', '华灯的明金碧。\n玳筵剧饮杯馀湿。\n珠翠隔房栊。\n微闻笑语通。\n蓬瀛知已近。\n青鸟仍传信。\n应为整云鬟。\n教侬倒玉山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8482, '好事近', '王之望', '五载复相逢，俱被一官驱役。\n惊我雪髯霜鬓，只声香相识。\n翠帷珍重出笙歌，醉迟迟春日。\n亲到鹊桥津畔，见天机停织。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8483, '好事近', '王之望', '彩舰载娉婷，宛在玉楼琼宇。\n人欲御风仙去，觉衣裳飘举。\n玉京咫尺是蓝桥，一见已心许。\n梦解汉皋珠佩，但茫茫烟浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8484, '好事近', '王之望', '缓带抚雄边，一面灭烽休役。\n歌舞後堂高宴，喜倾城初识。\n红绫小砑写新词，佳句丽星日。\n从此锦城机杼，把回文休织。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8485, '好事近', '王之望', '清唱动梁尘，窈窕夜深庭宇。\n一笑满斟芳酒，看霞觞争举。\n弓靴三寸坐中倾，惊叹小如许。\n子建向来能赋，过凌波仙浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8486, '好事近', '王之望', '萧寺两珠红，欲共晓霞争色。\n独占岁寒天气，正群芳休息。\n坐中清唱并阳春，写物妙诗格。\n霜鬓自羞簪帽，叹如何抛得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8487, '减字木兰花', '王之望', '珠帘乍见。\n云雨无踪空有怨。\n锦字新词。\n青鸟衔来恼暗期。\n桃溪得路。\n直到仙家留客处。\n今日东邻。\n远忆当年窥宋人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8488, '减字木兰花', '王之望', '糟糠相乐。\n早共梁鸿同隐约。\n著籍天门。\n隔品新封感帝恩。\n满堂儿女。\n妇捧金杯孙屡舞。\n白发卿卿。\n与尔尊前作寿星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8489, '丑奴儿・采桑子', '王之望', '蒙泉秋色登临处，愁送将归。\n一梦经时。\n肠断佳人、犹唱渭城词。\n春来重醉分携地，人在天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8490, '丑奴儿・采桑子', '王之望', '去年池馆同君醉，正是花时。\n隔院韶辉。\n桃李欣欣、如与故人期。\n相望两地今千里，还对芳菲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8491, '惜分飞', '王之望', '要眇新声生宝柱。\n弹到离肠断处。\n细落檐花雨。\n夜阑清唱行云住。\n洞府春长还易暮。\n凡客暂来终去。\n不忍回头觑。\n乱山流水桃溪路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8492, '醉花阴', '王之望', '弧门此日犹能记。\n叹居诸难系。\n弹指片声中，不觉流年，五十还加二。\n儿童寿酒邀翁醉。\n笑欣欣相戏。\n休画老人星，白发苍髯，怎解如翁似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8493, '鹧鸪天', '王之望', '撩乱江云雪欲飞。\n小轩幽会酒行时。\n佳人喜得鸳鸯侣，豪客争题鹦鹉词。\n歌舞地，喜追随。\n歙州端恨外迁迟。\n谪仙狂监从来识，七步初看子建诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8494, '虞美人', '王之望', '鸳鸯碧瓦寒留雪。\n玉树先春发。\n小楼歌舞夜流连。\n月落参横、一梦绕梅边。\n尊前酒量谁能惜。\n都是高阳客。\n十分莫厌羽觞传。\n半醉娉婷、云鬓金钿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8495, '小重山', '王之望', '幂幂轻云护晓霜。\n银花千万朵，烂韶光。\n宝山金字屡更张。\n笙箫远，帘幕重廊。\n车马暗尘香。\n一邦如蜡日，尽豪狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8496, '临江仙', '王之望', '十二峰前朝复暮，忽愁望断行云。\n梦回江浦晓风清。\n远山思翠黛，蔓草记罗裙。\n锦字织成千万恨，翻成第入新声。\n幽期谁为反离魂。\n主人无浪语，狂客最锺情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8497, '临江仙', '王之望', '霓作衣裳冰作面，铅华不天真。\n临风几待逐行云。\n自从留得住，不肯系仙裙。\n对客挥毫惊满座，银钩虿尾争新。\n数行草圣妙如神。\n从今王逸少，不学卫夫人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8498, '临江仙', '王之望', '家在蓬莱山下住，乘风时到尘寰。\n双凫偶堕网罗间。\n惊容凝粉泪，愁鬓乱云鬟。\n人世风波难久驻，云霞终反仙关。\n虚无仙路拥归鸾。\n却随烟雾去，长向洞天闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8499, '洞仙歌', '王之望', '玉楼玄圃，旧是神仙伴。\n鸣佩时朝紫皇殿。\n种蟠桃成树，碧柰开花，著子满，金母盘中屡献。\n飘然乘彩凤，东望蓬莱，曾共扁舟五湖泛。\n正珈笄未老，兰玉盈前，春欲转、喜对芳辰开宴。\n愿绿发朱颜镇长新，教岁岁年年，寿觞深劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8500, '满庭芳', '王之望', '海国寒轻，江南春早，小梅已漏芳妍。\n岁前冬後，和气欲回旋。\n此际瑶台阆苑，仙人下、白玉云。\n人间世，风帆月棹，同泛五湖船。\n当年。\n参谒地，鱼轩象服，锵佩朝天。\n向闽邦开国，福地真传。\n今日华筵寿，儿孙拥、兰玉相鲜。\n休辞□，蓬莱清浅，看取变桑田。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8501, '满庭芳', '王之望', '犀隐雕龙，蟾将威凤，建溪初贡新芽。\n九天春色，先到列仙家。\n今日磨圭碎璧，天香动、风入窗纱。\n清泉嫩，江南锡乳，一脉贯天涯。\n芳华。\n瑶圃宴，群真飞佩，同引流霞。\n醉琼筵红绿，眼乱繁花。\n一碗分云饮露，尘凡尽、斗牛何赊。\n归途稳，清飙两腋，不用泛灵槎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8502, '念奴娇', '王之望', '堂堂七尺，懔一时人物，孤映三蜀。\n闲雅风流豪醉後，犹有临邛遗俗。\n十载虞庠，一官楚塞，雅操凌寒玉。\n江山千里，惠然来慰幽独。\n落笔妙语如神，两章入手，不觉珠盈掬。\n从此西归荣耀处，宁假华旌高纛。\n乐府新声，郢都馀唱，应纪阳春曲。\n老夫一醉，故人高义堪服。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8503, '念奴娇', '王之望', '蒙泉岁晚，偶扁舟、同泛一池寒渌。\n四者难并谁信道，草草幽欢能足。\n美景良辰，赏心乐事，更有人如玉。\n今宵此会，陋邦惊破衰俗。\n豪俊傅粉诸孙，几年分袂，一笑还相逐。\n痛饮厌厌清夜永，那管更深催促。\n宋玉词章，陶潜风概，况继前贤躅。\n故人未至，坐中仍对梅福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8504, '念奴娇', '王之望', '柳花飞絮，又还是、清明寂寞时节。\n洞府人间嗟素手，今日匆匆分拆。\n巧笑难成，含情谁解，顾影无颜色。\n风流满面，却成春恨凄恻。\n云鬓从金蝉，纷纷红泪，千点胭脂湿。\n聚调轻盈离调惨，声入低空愁碧。\n祖帐将收，骊驹欲驾，去也劳相忆。\n伤心南浦，断肠芳草如积。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8505, '永遇乐', '王之望', '元夜风光，上都灯火，辉映春色。\n鳌冠仙山，龙衔瑞烛，银阙凌空碧。\n紫烟深拥，黄云孤起，人喜乍瞻天日。\n□云里，□□□□，侍臣□□鹄立。\n雾收霞卷，珠帘开遍，翠幕娉婷争出。\n倾国丛中，钧天合处，忽听鸣清跸。\n貂裘小帽，随车信马，犹忆少年豪逸。\n如今对，山城皓月，但馀叹息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8506, '风流子', '王之望', '江国东风早，芳菲又、迤逦报寒梅。\n正元气孕和，小春归候，数丁千载，喜动三台。\n向此际，上天开景运，王国产英材。\n想崇岳洞天，暗书苔藓，海山烟雨，空锁楼台。\n煌煌天人表，琼林与瑶树，照映庭槐。\n中有丽天星斗，惊世风雷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8507, '满庭芳', '葛立方', '霜叶停飞，冰鱼初跃，梅花犹芳丛。\n剪酥装玉，应为费天工。\n争奈江南驿使，征鞍待、一朵香浓。\n凭谁报，冰肌仙子，闻早驾飞龙。\n溶溶。\n春意动，寒姿未展，终愧群红。\n与斩新来上，开伴长松。\n要看黄昏庭院，横斜映、霜月朦胧。\n兰堂畔，巡檐索笑，谁羡杜陵翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8508, '满庭芳', '葛立方', '未许蜂知，难交雀，芳丛犹是寒丛。\n东方解冻，春仗做春工。\n何事仙葩未放，寒苞秘、冰麝香浓。\n应须是、惊闻羯鼓，谁敢喷髯龙。\n梅花，君自看，丁香已白，桃脸将红。\n结岁寒三友，久迟筠松。\n要看含章檐下，闲妆靓、春睡朦胧。\n知音是，冻云影底，铁面葛仙翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8509, '满庭芳', '葛立方', '狂吹鸣篱，祥剪水，分明欺压寒梅。\n冰威初敛，曦影上池台。\n应有一番和气，南枝上、恐有春来。\n须勤探，呼吾筇杖，屐齿上苍苔。\n春风，浑未到，徘徊香径，巡绕千回。\n见琼英一点，小占条枚。\n且看先锋素艳，看看便、繁蕾齐开。\n香浮动，微薰诗梦，须更著诗催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8510, '满庭芳', '葛立方', '腊雪方凝，春曦俄漏，画堂小秩芳筵。\n玉台仙蕊，帘外幂瑶烟。\n莫话青山万树，聊须对、一段孤妍。\n杯行处，香参鼻观，百濯未为贤。\n吾庐，何处好，绣香竹畔，偶桂溪边。\n且为渠珍重，满泛金船。\n已拚春酲一枕，如今且、醉倒花前。\n花飞後，欢呼一笑，又是说明年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8511, '满庭芳', '葛立方', '庾信何愁，休文何瘦，范叔一见何寒。\n梅花酷似，索笑画檐看。\n便肯嫣然一笑，疏篱上、玉脸冰颜。\n须勤赏，莫教青子，半著树头酸。\n朱阑。\n聊掩映，顶上，琪树团栾。\n命儿曹班坐，草草杯盘。\n旋折溪边□朵，琼蕤泛、蕉叶杯宽。\n从教□，尊前有客，拍手笑颓山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8512, '满庭芳', '葛立方', '弄月黄昏，封霜清晓，数枝影堕溪滨。\n化工先手，幻出一番新。\n片片雕酥碾玉，寒苞似、已泄香尘。\n聊相对，畸人投分，尊酒认荀陈。\n吾年，今老矣，佳人薄相，笑插林巾。\n愧苍颜白发，回授乌云。\n玉镜台边试看，相宜是、浅笑轻颦。\n君知否，寿阳额上，不似鬓边春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8513, '满庭芳', '葛立方', '一阵轻香，不知来处，元来梅已舒英。\n出篱含笑，芳意为人倾。\n细看高标孤韵，谁家有、别得花人。\n应须是，魏徵妩媚，夷甫太鲜明。\n北枝，方半吐，水边疏影，绰约娉婷。\n问横空皎月，匝地寒。\n何似此花清绝，凭君为、子细推评。\n幽奇处，素娥青女，著意为横陈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8514, '锦堂春・锦堂春慢', '葛立方', '气应三阳，氛澄六幕，翔乌初上云端。\n问朝来何事，喜动门阑。\n田父占来好岁，星翁说道宜官。\n拟更凭高望远，春在烟波，春在晴峦。\n歌管雕堂宴喜，任重帘不卷，交护春寒。\n况金钗整整，玉树团团。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8515, '水龙吟', '葛立方', '九州雄杰溪山，遂安自古称佳处。\n云迷半岭，风号浅濑，轻舟斜渡。\n朱阁横飞，渔矶无恙，鸟啼林坞。\n吊高人陈迹，空瞻遗像，知英烈、垂千古。\n忆昔龙飞光武。\n怅当年、故人何许。\n羊裘自贵，龙章难换，不如归去。\n七里溪边，鸬鸶源畔，一蓑烟雨。\n叹如今宕子，翻将钓手遮日，向西秦路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8516, '菩萨蛮', '葛立方', '井梧叶叶秋风晚。\n东篱点点金钱满。\n开急为重阳。\n日烘深院香。\n幽姿无众草。\n莫恨生非早。\n嚼蕊傍池台。\n寿公桑落杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8517, '风流子', '葛立方', '夜半春阳启，东风峭、犹带去年寒。\n叹榆塞战尘，玉关烟燧，壮心耿耿，青鬓斑斑。\n又还是，一年头上到，日月信跳丸。\n看门贴绘鸡，历颁金凤，酒浮柏叶，人颂椒盘。\n幽园。\n春信近，帘栊静，小宴取次追欢。\n聊□水沈烟袅，清唱声闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8518, '多丽', '葛立方', '冷云收，小园一段瑶芳。\n乍春来、未回穷腊，几枝开犯严霜。\n傍黄昏、暗香浮动，照清浅、疏影低昂。\n却月幽姿，含章媚态，娥姑射下仙乡。\n倚阑看、殷勤持酒，索笑也何妨。\n堪怜处，东君不管，独自凄凉。\n算何人、为伊销断，古今才子篇章。\n有西湖、赋诗处士，□东阁、年少台郎。\n驿使来时，吴王醉处，几番牵动广平肠。\n剩宴赏、微酸如豆，又是隔年长。\n高楼外，莫教羌管，吹堕寒香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8519, '沙塞子', '葛立方', '天生玉骨冰肌。\n瘦损也、知他为谁。\n□寒底、傲霜凌雪，不教春知。\n高楼横笛试轻吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8520, '多丽', '葛立方', '破波光如镜，三翼轻舟。\n对雨馀、重岩叠嶂，何妨影堕清流。\n望芙蕖、渺然如海，张云锦、掩映汀洲。\n出水奇姿，凌波艳态，眼看□叶弄新秋。\n恍疑是、金沙池内，玉井认峰头。\n花深处，田田叶底，鱼戏龟游。\n正微凉、西风初度，一弯斜月如钩。\n想天津、鹊桥将驾，看宝奁、蛛网初抽。\n晒腹何勘，穿针无绪，不如溪上少淹留。\n竞笑语、追寻惟有，沈醉可忘忧。\n凭清唱，一声檀板，惊起沙鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8521, '满庭芳', '葛立方', '扉映琉璃，窗摇云母，水堂新云湾。\n际天波面，玉镜宝奁宽。\n栏外青山几叠，瑶烟敛、影落千鬟。\n寒汀晚，芦花飞雪，风定白鸥闲。\n尘寰。\n何处有，方壶圆峤，弱水波翻。\n问何如藜杖，此地跻攀。\n种竹今逾万个，风枝静、日报平安。\n他年事、苍云屯处，千亩看栖鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8522, '春光好', '葛立方', '去年曾寿生朝。\n正菊黄、初舒翠翘。\n今岁雕堂重预宴，梨雪香飘。\n明年应傍丹霄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8523, '西江月', '葛立方', '风送丹枫卷地，霜乾枯苇鸣溪。\n兽炉重展向深闺。\n红入麒麟方炽。\n翠箔底垂银蒜，罗帏小钉金泥。\n笙歌送我玉东西。\n谁管摇花舞砌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8524, '蝶恋花', '葛立方', '缇室群阴清晓散。\n灰动葭莩，渐觉微阳扇。\n日永绣工才一线。\n挈壶已报添银箭。\n六幕无尘开碧汉。\n非雾非烟，彷佛登台见。\n梅萼飘香萦小宴。\n霞浆莫放琉璃浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8525, '清平乐', '葛立方', '文章惊世。\n半挹南宫第。\n蟾窟澄辉天似洗。\n折得丹桂。\n当年蓬矢生贤。\n流霞满祝长年。\n更愿巨鳌连钓，枫宸第一胪传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8526, '减字木兰花', '葛立方', '摇毫铸藻。\n纵有微之应压倒。\n万里鹏程。\n南省今书淡墨名。\n胪传丹陛。\n月里桂花先著袂。\n雁塔高题。\n玉季巍科尚觉低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8527, '满庭芳', '葛立方', '栗里田园，乌衣门巷，别来几换星霜。\n华阳仙窟，翠桁彩衣香。\n梦堕当涂风月，披绛帐、欲指堂。\n浮鸥外，来宁老子，特泛溪航。\n相逢，春正好，梅舒香白，柳曳宫黄。\n且相将一笑，乐未渠央。\n须念离多会少，难轻负、百霞浆。\n深深观，舞回飞雪，乐奏小宫商。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8528, '水调歌头', '葛立方', '睡鸭凝香缕，白酒泻无声。\n郊墟不办羊酪，照箸紫丝莼。\n此去青山深处，邀得白云为伴，绝意请长缨。\n一舸背君去，几幅布帆轻。\n帝恩重，容绿隐，吏祠庭。\n膝间文度安亲，得计是扬名。\n珍重金兰交契，共惜匆匆别去，送我几烟林。\n异日怀君处，凝睇乱层岑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8529, '风流子', '葛立方', '细草芳南苑，东风里、赢得一身闲。\n见花朵绣田，柳丝络岸，沼冰方泮，山雪初残。\n又还是，陇头春信动，梅蕊入征鞍。\n月里暗香，水边疏影，淡妆宜瘦，玉骨禁寒。\n泛金溪上好，开幽户、聊面翠麓云湾。\n知道醉吟堪老，名利难关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8530, '满庭芳', '葛立方', '江国麾幢，边城鼓角，湓川几报严更。\n笑谈油幕，英杰为时生。\n腹贮六韬三略，新诗就、矛槊频横。\n功名事，他年未晚，一落枪。\n归来，何早计，白苹洲畔，危获深耕。\n又何如，竹帛彝鼎垂名。\n犀节徵还伊迩，春风外、文催行。\n岩廊上，谈兵齿颊，谠论佐休明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8531, '玉漏迟', '葛立方', '窗户明环堵。\n山容黛染，水光绡舞。\n荷盖擎烟，花映步波神女。\n嫩脸铅华掩素，无语向、薰风凝伫。\n晴又雨。\n征隐隐，云洲沙渚。\n须臾风卷还晴，看香泄丹囊，乍飘沈炷。\n鱼荷衣，珠颗乱倾无数。\n休话金沙玉井，争似我、神龟□处。\n觞为举。\n何人解歌金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8532, '行香子', '葛立方', '风透纱窗。\n叶落银床。\n夹缬林、吹下严霜。\n新浮蚁，班坐飞觞。\n有岩中秀，篱中艳，洛中香。\n金钿放蕊，玉粒争芳。\n惯年年、来趁清商。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8533, '玉楼春', '葛立方', '青女飞花浓剪水。\n寒气霏微度窗纸。\n人间那得骨为帘，有麒麟尊有蚁。\n笙簧冻涩闲纤指。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8534, '瑞鹧鸪', '葛立方', '榴花庭院戏氍毹。\n水剪双眸画不如。\n莫恨未能通瑟，只今先已辩之无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8535, '浪淘沙', '葛立方', '休看辋川图。\n未是幽居。\n何如云水绕储胥。\n新湿青红开栋宇，雾拱风疏。\n小圃秀郊墟。\n花破平芜。\n五峰列影水平铺。\n只欠五城楼十二，便是蓬壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8536, '卜算子', '葛立方', '明镜盖红蕖，轩户临烟渚。\n珠帘淡淡风，香里开尊俎。\n莫把碧筒弯，恐带荷心苦。\n唤我溪边太乙舟，潋滟盛芳醑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8537, '卜算子', '葛立方', '袅袅水芝红，脉脉蒹葭浦。\n淅淅西风淡淡烟，几点疏疏雨。\n草草展杯觞，对此盈盈女。\n叶叶红衣当酒船，细细流霞举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8538, '减字木兰花', '葛立方', '张南周北。\n谩说清漳摇绀碧。\n何似幽栖。\n甥舅相望共一溪。\n璇题沙版。\n不用买邻糜百万。\n余户增辉。\n庭列芝兰户戟枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8539, '夜行船', '葛立方', '百尺雕堂悬蜀绣。\n珠帘外、玉阑琼。\n调鼎名家，吹箫贤胄，新卜凤皇佳繇。\n银叶添香香满袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8540, '雨中花・夜行船', '葛立方', '壮岁嬉游，乐事几经，青门紫陌芳春。\n未见廉纤，膏雨花尘。\n濯锦宝丝增艳，洗妆玉颊尤新。\n向韶光浓处，点染芳菲，总是东君。\n苏州老子，经雨南园，为谁一扫花林。\n谁信道、佳声著处，肌润香匀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8541, '雨中花・夜行船', '葛立方', '寄径濉阳，陌上忽看，夭桃李争春。\n又见楚宫，行雨洗芳尘。\n红艳霞光夕照，素华琼树朝新。\n为奇姿芳润，拟倩游丝，留住东君。\n拾遗杜老，犹爱南塘，寄情萝薜山林。\n争似此、花如姝丽，獭髓轻匀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8542, '好事近', '葛立方', '几骑汉旌回，喜动满川花木。\n遥睇清淮古岸，散离愁千斛。\n烟笼沙嘴定连艘，鹊脚蘸波绿。\n归话隔年心事，秉夜阑银烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8543, '好事近', '葛立方', '归日指清明，肯把话言轻食。\n已是飞花时候，赖东风无力。\n青帘沽酒送春归，莫惜万金掷。\n屈指明年春事，有红梅消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8544, '朝中措', '葛立方', '暂时莫荡出燕然。\n冰柱冻层檐。\n时节马蹄归路，杨花乱扑征鞯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8545, '春光好', '葛立方', '禁烟却酿新愁。\n正系马、清淮渡头。\n後日清明催叠鼓，应在扬州。\n归时元已临流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8546, '虞美人', '魏杞', '冰肤玉面孤山裔。\n肯到人间世。\n天然不与百花同。\n却恨无情轻付、与东风。\n丽谯三弄江梅晓。\n立马溪桥小。\n只应明月最相思。\n曾见幽香一点、未开时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8547, '卜算子', '魏杞', '一叶鉴中来，两岸青山起。\n送我红蕖万柄香，疑在蓬壶里。\n天地莹无尘，巾袂凉如水。\n白浪无声月自高，不是人间世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8548, '人月圆', '陈知柔', '鬓缘心事随时改，依旧在天涯。\n多情惟有，篱边黄菊，到处能华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8549, '水调歌头', '王识', '一雨洗空阁，象纬迫人清。\n披襟台上，坐看北斗正旋衡。\n知是南宫列宿，初出极星未远，龙角正分明。\n河汉馀千里，风露已三更。\n坐未久，书帙散，酒壶倾。\n凉生殿阁，冷然邀我御风行。\n拟欲乘槎一问，但得天孙领略，安用访君平。\n莫笑儒生事，造化掌中生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8550, '临江仙', '许庭', '不见昭阳宫内柳，黄金齐拈轻柔。\n东君昨夜到皇州。\n玉阶金井，无处不风流。\n怅望翠华春欲暮，六宫都锁春愁。\n暖风吹动绣帘钩。\n飞花委地，时转玉香球。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8551, '临江仙', '许庭', '不见隋河堤上柳，绿阴流水依依。\n龙舟东下疾於飞。\n千条万叶，浓翠染旌旗。\n记得当年春去也，锦帆不见西归。\n故抛轻絮点人衣。\n如将亡国恨，说与路人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8552, '临江仙', '许庭', '不见陶家门外柳，柴扉一径遥通。\n闭门终日掩清风。\n感君高节，绿荫向人浓。\n篱落萧疏鸡犬静，日长飞絮。\n先生一醉万缘空。\n经时高卧，不到翠阴中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8553, '临江仙', '许庭', '不见都门亭畔柳，春来绿尽长条。\n柳边行色马萧萧。\n一枝折赠，相见又何朝。\n酒尽曲终人去也，风前亦自无聊。\n祗应於我恨偏饶。\n东君特地，付与沈郎腰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8554, '临江仙', '许庭', '不见灞陵原上柳，往来过尽蹄轮。\n朝离南楚暮西秦。\n不成名利，赢得鬓毛新。\n莫怪枝条憔悴损，一生唯苦征尘。\n两三烟树倚孤村。\n夕阳影里，愁杀宦游人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8555, '清平乐', '邵某', '阿郎去日。\n不道长为客。\n底事桐庐无处觅。\n却得广州消息。\n江头一支兰船。\n风雨湘妃庙前。\n死恨无情江水，送郎一去三年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8556, '如梦令', '陈祖安', '月直金波潋滟。\n此去水仙不远。\n霜重夜风清，骨冷□□□□。\n谁见。\n谁见。\n醉眼参横斗转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8557, '二郎神', '王十朋', '深深院。\n夜雨过，帘栊高卷。\n正满槛、海棠开欲半。\n仍朵朵、红深红浅。\n遥认三千宫女面。\n匀点点、胭脂未遍。\n更微带、春醪宿醉，袅娜香肌娇艳。\n日暖。\n芳心暗吐，含羞轻颤。\n笑繁杏夭桃争烂漫。\n爱容易、出墙临岸。\n子美当年游蜀苑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8558, '点绛唇', '王十朋', '野态芳姿，枝头占得春长久。\n怕钩衣袖。\n不放攀花手。\n试问东山，花似当时否。\n还依旧。\n谪仙去後。\n风月今谁有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8559, '点绛唇', '王十朋', '庭院深深，异香一片来天上。\n傲春迟放。\n百卉皆推让。\n忆昔西都，姚魏声名旺。\n堪惆怅。\n醉翁何往。\n谁与花标榜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8560, '点绛唇', '王十朋', '近侍盈盈，向人自笑还无语。\n牡丹飘雨。\n开作群芳主。\n柔美温香，剪染劳天女。\n青春去。\n花间歌舞。\n学个狂韩愈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8561, '点绛唇', '王十朋', '芳友依依，结根遥向深林外。\n国香风递。\n始见殊萧艾。\n雅操幽姿，不怕无人采。\n堪纫佩。\n灵均千载。\n九畹遗芳在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8562, '点绛唇', '王十朋', '仙友苍苍，西风吹散天香好。\n暗飘龙脑。\n金栗枝头小。\n谁种丹霄，造化玄功妙。\n真堪笑。\n学仙疏谬。\n有似西河老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8563, '点绛唇', '王十朋', '雪径深深，北枝贪睡南枝醒。\n暗香疏影。\n孤压群芳顶。\n玉艳冰姿，妆点园林景。\n凭阑咏。\n月明溪静。\n忆昔林和靖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8564, '点绛唇', '王十朋', '霜蕊鲜鲜，野人开径新栽植。\n冷香佳色。\n趁得重阳摘。\n预约比邻，有酒须相觅。\n东篱侧。\n为花辞职。\n古有陶彭泽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8565, '点绛唇', '王十朋', '羽盖垂垂，玉英乱簇春光满。\n韵香清远。\n暖日烘庭院。\n露褒琼枝，脸透何郎晕。\n凝余恨。\n古人不见。\n谁与花公论。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8566, '点绛唇', '王十朋', '毗舍遥遥，异香一炷驰名久。\n妙香稀有。\n鼻观深参透。\n问讯东来，知□谁先後。\n称仙友。\n十花为偶。\n近有江西守。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8567, '点绛唇', '王十朋', '春色融融，东风吹散花千树。\n雪香飘处。\n寒食江村暮。\n左掖看花，多少词人赋。\n花无语。\n一枝春雨。\n惟有香山句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8568, '点绛唇', '王十朋', '秀色娟娟，最宜雨沐风梳际。\n径幽香细。\n草滴青襟袂。\n一日才无，便觉生尘态。\n轩窗外。\n数竿相对。\n不减王猷爱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8569, '点绛唇', '王十朋', '丝蕊垂垂，嫣然一笑新妆就。\n锦亭前後。\n燕子来时候。\n谁恨无香，试把花枝嗅。\n风微透。\n细熏锦袖。\n不止嘉州有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8570, '点绛唇', '王十朋', '十里西湖，淡妆浓抹如西子。\n藕花簪水。\n清净香无比。\n记得曾游，短棹红云里。\n聊相拟。\n一盆池水。\n十里西湖似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8571, '点绛唇', '王十朋', '畏日炎炎，梵香一炷熏亭院。\n鼻根充满。\n好利心殊浅。\n贝叶书名，名义谁能辨。\n西风远。\n胜鬟不见。\n喜见琼花面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8572, '点绛唇', '王十朋', '南国名花，向人无语长含笑。\n缘香囊小。\n不肯全开了。\n花笑何人，鹤相诗词好。\n须知道。\n一经品藻。\n又压前诗倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8573, '点绛唇', '王十朋', '蜡换梅姿，天然香韵初非俗。\n蝶驰蜂逐。\n蜜在花梢熟。\n岩壑深藏，几载甘幽独。\n因坡谷。\n一标题目。\n高价掀兰菊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8574, '点绛唇', '王十朋', '清夜沈沈，携来深院柔枝小。\n俪兰开巧。\n雪里乘风袅。\n温室寒祛，旖旎仙姿早。\n看成好。\n花仙欢笑。\n不管年华老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8575, '点绛唇', '王十朋', '落木萧萧，琉璃叶下琼葩吐。\n素香柔树。\n雅称幽人趣。\n无意争先，梅蕊休相妒。\n含春雨。\n结愁千绪。\n似忆江南主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8576, '点绛唇', '王十朋', '阑槛阴沈，紫云呈瑞馀寒凛。\n卷帘猗枕。\n香逼幽人寝。\n入梦何年，庐阜闻名稔。\n风流甚。\n阿谁题品。\n唤作熏笼锦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8577, '失调名', '刘大辨', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8578, '长相思令・长相思', '吴淑姬2', '烟霏霏。\n雪霏霏。\n雪向梅花枝上堆。\n春从何处回。\n醉眼开。\n睡眼开。\n疏影横斜安在哉。\n从教塞管催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8579, '锁窗寒・琐寒窗', '程先', '雨洗红尘，云迷翠麓，小车难去。\n凄凉感慨，未有今年春暮。\n想曲江水边丽人，影沈香歇谁为主。\n但兔葵燕麦，风前摇荡，径花成土。\n空被多情苦。\n庆会难逢，少年几许。\n纷纷沸鼎，负了青阳百五。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8580, '瑞鹤仙', '朱耆寿', '樱桃抄乳酪。\n正雨厌肥梅，风吹箨。\n咸瞻格天阁。\n见十眉环侍，争鸣弦索。\n茶瓯试瀹。\n更良夜、沈沈细酌。\n问间生、此日为谁，曾向玉皇、案前持橐。\n龟鹤。\n从他祝寿，未比当年，阴功堪托。\n天应不错。\n教公议，细评泊。\n自和戎以来，谋国多少，萧曹卫霍。\n奈胡儿自若，惟守绍兴旧约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8581, '西江月', '石安民', '飞阁下临无地，层峦上出重霄。\n重阳未到客登高。\n信是今年秋早。\n随意烟霞笑傲，多情猿鹤招邀。\n山翁笑我太丰标。\n竹杖棕鞋桐帽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8582, '贺新郎', '刘镇1', '翠葆摇新竹。\n正榴花、枝头叶底，斗红争绿。\n谁在纱窗停针线，闲理竹西旧曲。\n又还是、兰汤新浴。\n手弄合欢双彩索，笑偎人、福寿低相祝。\n金凤，艾花矗。\n龙舟水飞相逐。\n记当年、怀沙旧恨，至今遗俗。\n雨过平芜浮天阔，画凌波尽簇。\n沸十里、笙歌声续。\n好是蟾钩随归棹，任欢呼、船重成颓玉。\n犹未忍，罩银烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8583, '天香', '刘镇1', '漠漠江皋，迢迢驿路，天教为春传信。\n万木丛边，百花头上，不管雪飞风紧。\n寻交访旧，惟翠竹、寒松相认。\n不意牵丝动兴，何心衬妆添晕。\n孤标最甘冷落，不许蝶亲蜂近。\n直自从来洁白，个中清韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8584, '失调名', '魏之', '挂天师，撑著眼，直下觑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8585, '点绛唇', '曾协', '小驻征骖，一尊古寺留君住。\n六花无数。\n飞舞朝天路。\n上苑繁华，却似词章富。\n春将暮。\n玉鞭凝伫。\n总是经行处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8586, '点绛唇', '曾协', '乱叠香罗，玉纤微把燕支污。\n靓妆无数。\n十里扬州路。\n怨绿啼红，总道春归去。\n君知否。\n画阑幽处。\n留得韶光住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8587, '浣溪沙', '曾协', '昼漏新来一倍长。\n众宾沾醉尚传觞。\n浓云遮日惜红妆。\n应是主人归凤沼，为传芳讯到黄堂。\n腰围恰恰束金黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8588, '秦楼月・忆秦娥', '曾协', '清秋月。\n长空万里烟华白。\n烟华白。\n江云收尽，楚天一色。\n莼丝惹起思归客。\n清光正好伤离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8589, '桃源忆故人', '曾协', '野亭问柳今朝试。\n更访小园开未。\n月下山横空际。\n两两修眉对。\n骚人对此增高致。\n意入笔端清邃。\n投分周郎心醉。\n真解消人意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8590, '踏莎行', '曾协', '柳眼传情，花心蹙恨。\n春风处处关方寸。\n朱帘卷尽画屏间，云鬟半罗衣褪。\n燕语莺啼，日长人困。\n鱼沈雁断无音信。\n琵琶声乱篆烟斜，寸肠欲断无人问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8591, '凤栖梧・蝶恋花', '曾协', '柳弄轻黄花泣露。\n万叠春山，不记尘寰路。\n日射霜林烟罩素。\n长空不著纤云污。\n历历远村明可数。\n绿涨前溪，渺渺迷津渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8592, '祝英台・祝英台近', '曾协', '放花开，催花谢，谁解东君意。\n要遣花王，独占花蹊邃。\n且看玉镜台前，霞觞新举，红玉软、晓妆慵试。\n好风味。\n须信金屋中人，谁堪并娇媚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8593, '水调歌头', '曾协', '今日复何日，欢动楚江滨。\n紫泥来自天上，优诏起元臣。\n想见傅岩梦断，记得金瓯名在，却念佩兰人。\n永昼通明殿，曾听话经纶。\n促归装，趋北阙，觐严宸。\n玉阶陈迹如故，天笑一番新。\n好借食间前箸，尽吐胸中奇计，指顾静烟尘。\n九万云霄路，飞走趁新春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8594, '水调歌头', '曾协', '日永向槐夏，绕屋树扶疏。\n麦秋天气清润，设记生初。\n新拜小君佳号，更过诸郎官舍，仍玩掌中珠。\n乐事似今少，一笑倒双壶。\n列山肴，烹野蔌，且欢娱。\n鹿门远引，平生此志与君俱。\n终向苕溪烟水，携手云庄风月，不践利名区。\n功业看儿辈，相对老江湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8595, '酹江月・念奴娇', '曾协', '一年好处，是霜轻尘敛，山川如洗。\n晚菊留花供燕赏，金缕宝衣销地。\n旧观初还，层楼相望，重见升平际。\n小春时节，绮罗丛里人醉。\n此日武帐贤侯，六年仁政，浃长淮千里。\n欲入行仍缓带，聊抚竹西歌吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8596, '酹江月・念奴娇', '曾协', '苕溪古岸，有朱门初建，落成华屋。\n对启园林随杖履，迤逦柳蹊相属。\n好是危亭，片峰迎面，独立清溪曲。\n芜城低远，一尘不碍游目。\n公子豪饮方酣，夜堂深静，隐隐鸣丝竹。\n却尽春寒宾满座，深酌葡萄新绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8597, '酹江月・念奴娇', '曾协', '一年好处，是满城红药，留连□□。\n十里扬州应费了，多少春工妆饰。\n弱质风，芳心带露，酒困娇无力。\n园林绿暗，粉光低占丛碧。\n谁与千载声名，翻阶高咏，出文章仙伯。\n阅尽繁华芳意歇，初识倾城风格。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8598, '水龙吟', '曾协', '楚乡菰黍初尝，马蹄偶踏扬州路。\n莼丝向老，江鲈堪脍，催人归去。\n秋气萧骚，月华如洗，一天风露。\n望重重烟水，吴淞万顷，曾约旧时鸥鹭。\n惆怅别离无奈，整孤帆、依然回顾。\n玉龙节底，故人情重，欲行犹驻。\n敛散功多，澄清志遂，好回高步。\n看归鞍稳上，文鸳班里，五云深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8599, '水调歌头', '郑庶', '千古钓台下，老尽去来人。\n倚空绝壁，朝暮秀色只如春。\n高挂瀑泉千尺，洗到云根山骨，无处著风尘。\n秋尽玉壶冷，别是一乾坤。\n问当日，中兴将，汉功臣。\n云台何在，寂寞谁复记丹青。\n争似先生标致，长共清风明月，不减旧精神。\n无限兴亡意，舒卷在丝纶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8600, '好事近', '曾逮', '满树叶繁枝重，缀青黄千百。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8601, '菩萨蛮', '王炎1', '远风江急潮来晚。\n晚来潮急江风远。\n横岸断山青。\n青山断岸横。\n寄书无雁系。\n系雁无书寄。\n归梦只江西。\n西江只梦归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8602, '梅花引', '王炎1', '裁征衣。\n寄征衣。\n万里征人音信稀。\n朝相思。\n暮相思。\n滴尽真珠，如今无泪垂。\n闺中幼妇红颜少。\n应是玉关人更老。\n几时归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8603, '水调歌头', '毛并', '襟带大江左，平望见三州。\n凿空遗迹，千古奇胜米公楼。\n太守中朝耆旧，别乘当今豪逸，人物眇应刘。\n此地一尊酒，歌吹拥貔貅。\n楚山晓，淮月夜，海门秋。\n登临无尽，须信诗眼不供愁。\n恨我相望千里，空想一时高唱，零落几人收。\n妙赏频回首，谁复继风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8604, '水调歌头', '毛并', '春意满南国，花动雪明楼。\n千坊万井，此时灯火隘追游。\n十里寒星相照，一轮明月斜挂，缥缈映红球。\n共嬉不禁夜，光彩遍飞浮。\n艳神仙，轰鼓吹，引遨头。\n文章太守，此时宾从敌应刘。\n回首生平旧事，未减当年风月，一醉为君酬。\n明日朝天去，空复想风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8605, '水调歌头', '毛并', '小筑百年计，雅志几人成。\n乱山深处，烟雨面面对萦青。\n巾屦方安吾土，花木仍供真赏，邻有阮嵇生。\n岁月抛身外，尘事更无营。\n鸟知归，云出岫，两忘情。\n从渠华屋，回首烟草吊颓倾。\n何似生涯才足，枕南窗北牖，醉梦落樵声。\n更喜濯缨处，门外一江清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8606, '水调歌头', '毛并', '汉代李元礼，江左管夷吾。\n英姿雅望，凛凛玉立冠中都。\n胸中千丈，不肯低回青禁，引去卧江湖。\n更学鸱夷子，一舸下东吴。\n送公别，杯酒尽，少踌躇。\n旧棠阴下，几人临路拥行车。\n归近云天尺五，梦想经纶贤业，谈笑取单于。\n为问苕溪水，留得此翁无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8607, '水调歌头', '毛并', '十载刘夫子，名过庾兰成。\n人人争看，角犀今喜试丰盈。\n倾耳新诗千首，妙处端须击节，金石破虫声。\n此士难复得，黄口闹如羹。\n忆年少，游侠窟，戏荆卿。\n结交投分，驰心千里剧摇旌。\n我老公方豪健，傥许相从晚岁，慷慨激中情。\n洗眼功名会，一箭取辽城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8608, '秋蕊香', '毛并', '荡暖花风满路。\n织翠柳阴和雾。\n曲池斗草旧游处。\n忆试春衫白苎。\n暗惊节意朱弦柱。\n送春去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8609, '满庭芳', '毛并', '世事难穷，人生无定，偶然蓬转萍浮。\n为谁教我，从宦到东州。\n还似翩翩海燕，乘春至、归及凉秋。\n回头笑，浑家数口，又泛五湖舟。\n悠悠。\n当此去，黄童白叟，莫漫相留。\n但溪山好处，深负重游。\n珍重诸公送我，临岐泪、欲语先流。\n应须记，从今风月，相忆在南楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8610, '满庭芳', '毛并', '五十年来，追思畴曩，佳时去若云浮。\n依然重见，感涕话西州。\n幸喜灵光不改，空自笑、蒲柳先秋。\n成何事，风波末路，险畏有沈舟。\n别愁。\n都几许，相从未，我去公留。\n况狂直平生，谁念遨游。\n月夕风天正好，还惊怅、失此诗流。\n江南岸，明朝更远，回首仲宣楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8611, '满庭芳', '毛并', '落难容，崎岖堪笑，一年陆走川浮。\n又携妻子，两度过神州。\n紫蟹鲈鱼正美，凉天气、恰傍中秋。\n今宵意，无人伴我，快泻玉双舟。\n功名，聊尔耳，千金聘楚，万户封留。\n又争如物外，闲旷优游。\n好在东阡北陌，相从有、诸老风流。\n家山近，归休去也，不上望京楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8612, '渔家傲', '毛并', '极目丹枫迎霁晓。\n山明水净新霜早。\n燕去鸿归无事了。\n天渺渺。\n风吹平野低寒草。\n渐过初冬时节好。\n寻梅踏雪城南道。\n追忆旧游人已老。\n欢更少。\n孤怀拟共谁倾倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8613, '好事近', '毛并', '飞盖满南园，想见八仙遥集。\n几树海棠开遍，正新晴天色。\n休辞一醉任扶还，衣上酒痕湿。\n便恐岁华催去，听秋虫相泣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8614, '贺新郎', '毛并', '风雨连朝夕。\n最惊心、春光晚，又过寒食。\n落尽一番新桃李，芳草南园似积。\n但燕子、归来幽寂。\n况是单栖饶惆怅，尽无聊、有梦寒犹力。\n春意远，恨虚掷。\n东君自是人间客。\n暂时来、匆匆却去，为谁留得。\n走马插花当年事，池畹空馀旧迹。\n奈老去、流光堪惜。\n杳隔天涯人千里，念无凭、寄此长相忆。\n回首处，暮云碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8615, '念奴娇', '毛并', '层栏飞栋，压孤城临瞰，并吞空阔。\n千古吴京佳丽地，一览江山奇绝。\n天际归舟，云中行树，鹭点汀洲雪。\n三山无际，眇然相望溟渤。\n凤么遗响悲凉，故台今不见，苍烟芜没。\n千骑重来初起废，缅想六朝人物。\n岘首他年，羊公终在，笑几人磨灭。\n一时尊俎，且须同赋风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8616, '念奴娇', '毛并', '少年奇志，笑功名画虎，文章刻鹄。\n永夜漫漫悲昼短，难挽苍龙衔烛。\n飞藿飘零，浮云迁变，过眼邮传速。\n昔人真意，眇然千载谁属。\n犹喜二子当年，诸公籍甚，赏云和孤竹。\n翰墨流传知几许，遗响宫商相续。\n梦里京华，不须惊叹，春草年年绿。\n赤霄归去，更看奔电喷玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8617, '念奴娇', '毛并', '十年湖海，叹潘郎憔悴，无心云阁。\n强起登临惊暮序，目极清霜摇落。\n散发层阿，振衣千仞，浩荡穷林壑。\n寥无际，镜天收尽云脚。\n长啸声落悲风，想沧州万里，当年归约。\n回首区中无限事，此意谁同商略。\n欲驾飞鸿，翩然独往，汗漫期相诺。\n滞留何事，坐令双鬓如鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8618, '念奴娇', '毛并', '丽谯春晚，望东南千里，湖山佳色。\n画戟门前清似水，时节初过灯夕。\n封井年登，京华日近，每报平安驿。\n满城花柳，正须千骑寻觅。\n忆我年少追游，叨兔园客右，多惭英识。\n今日怀人无限意，老泪尊前重滴。\n赋咏空传，雄豪谁在，鬓点吴霜白。\n招呼一醉，幸公时慰愁寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8619, '念奴娇', '毛并', '倚风含露，似轻颦微笑，盈盈脉脉。\n染素匀红，知费尽，多少东君心力。\n国艳酣晴，天香融暖，画手争传得。\n绿窗朱户，晓妆谁见凝寂。\n独占三月芳菲，千花百卉，算难争春色。\n欲寄朝云无限意，回首京尘犹隔。\n舞破霓裳，一枝浑似，醉倚香亭北。\n旧欢如梦，老怀那更追惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8620, '念奴娇', '毛并', '王孙老去，算无地倾倒，胸中豪逸。\n小筑三间便席卷，多少江山风月。\n万壑回流，千峰输秀，人境成三绝。\n登临佳处，鸟飞不尽空阔。\n追念辋水斜川，有风流千载，渊明摩诘。\n何必斯人聊一笑，俯仰今犹前日。\n只恐东州，催成棠阴，又作三年别。\n赏心难继，莫教辜负华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8621, '念奴娇', '毛并', '阿环家住阆风顶，绛阙瑶台相接。\n翳凤乘鸾人不见，隐隐霓裳云。\n秀骨贞风，长眉翠浅，映白喉红颊。\n非烟深处，渺然云浪千叠。\n一笑徐福扁舟，春风空老尽，当时童妾。\n骨冷魂清惊梦到，同看碧桃千叶。\n寄语青童，何时丹就，为我留穷笈。\n天鸡催晓，却愁吹堕尘劫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8622, '念奴娇', '毛并', '素秋新霁，风露洗寥廓，珠宫琼阙。\n帘幕生寒人未定，鹊羽惊飞林樾。\n河汉无声，微云收尽，相映寒光发。\n三千银界，一时无此奇绝。\n正是老子南楼，多情孤负了，十分佳节。\n起舞徘徊谁为我，倾倒杯中明月。\n欲揽娥，扁舟沧海，戏濯凌波袜。\n漏残钟断，坐愁人世超忽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8623, '满江红', '毛并', '东马严徐，名籍甚、西京人物。\n谁不羡、伏蒲忠鲠，演纶词笔。\n雅意中朝今小试，二年东郡弦风迹。\n数中兴、循吏两三人，公居一。\n温诏趣，还丹阙。\n倾睿相，方前席。\n看云台登践，论思密勿。\n超览堂中遗爱在，几人同恋津亭别。\n顾倦游、云路仆登仙，心如失。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8624, '满江红', '毛并', '回首吾庐，思归去、石溪樵谷。\n临玩有、门前流水，乱松疏竹。\n幽草春馀荒井迳，鸣禽日在窥墙屋。\n但等闲、凭几看南山，云相逐。\n家酿美，招邻曲。\n朝饭饱，随耕牧。\n况东皋二顷，岁时都足。\n鳞阁功名身外事，墙阴不驻流光促。\n更休论、一枕梦中惊，黄粱熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8625, '水龙吟', '毛并', '渺然震泽东来，太湖望极平无际。\n三吴风月，一江烟浪，古今绝致。\n羽化蓬莱，胸吞云梦，不妨如此。\n看垂虹千丈，斜阳万顷，尽倒影、青奁里。\n追想扁舟去後，对汀洲、白苹风起。\n只今谁会，水光山色，依然西子。\n安得超然，相从物外，此生终矣。\n念素心空在，徂年易失，泪如铅水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8626, '渔家傲', '毛并', '杨子津头风色暮。\n孤舟渺渺江南去。\n忆得佳人临别处。\n愁返顾。\n青山几点斜阳树。\n可忍归期无定据。\n天涯已听边鸿度。\n昨夜乡心留不住。\n无驿数。\n梦中行了来时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8627, '江城子', '毛并', '神仙楼观梵王宫。\n月当中。\n望难穷。\n坐听三通，谯鼓报笼铜。\n还忆当年京辇旧，车马会，五门东。\n华堂歌舞间笙钟。\n夕香。\n度花风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8628, '江城子', '毛并', '倚墙高树落惊禽。\n小窗深。\n夜沈沈。\n酒醒灯昏，人静更愁霖。\n惆怅行云留不住，携手处，却分襟。\n悠悠风月两关心。\n拥孤衾。\n恨难禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8629, '画堂春', '毛并', '华灯收尽雪初残。\n踏青还尔游盘。\n落梅强半已飞翻。\n划地春寒。\n多病故人日远，几时双燕来还。\n可怜楼上一凭栏。\n不见长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8630, '风流子', '毛并', '新禽初弄舌，东郊外、催尔踏青期。\n渐晴滟翠漪，惠风骀荡，暖蒸红雾，淑景辉迟。\n粉墙外，杏花无限笑，杨柳不胜垂。\n闲里岁华，但惊萧索，老来心赏，尤惜芳菲。\n平生歌酒地，空回首，惆怅触绪沾衣。\n谁见素琴翻恨，青镜留悲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8631, '浪淘沙', '毛并', '帘幕燕双飞。\n春共人归。\n东风恻恻雨霏霏。\n水满西池花满地，追惜芳菲。\n回首昔游非。\n别梦依稀。\n一成春瘦不胜衣。\n无限楼前伤远意，芳草斜晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8632, '醉落魄・一斛珠', '毛并', '暮寒凄冽。\n春风探绕南枝发。\n更无人处增清绝。\n冷蕊孤香，竹外朦胧月。\n西洲昨梦凭谁说。\n攀翻剩忆经年别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8633, '眼儿媚', '毛并', '小溪微月淡无痕。\n残雪拥孤村。\n攀条弄蕊，春愁相值，寂默无言。\n忍寒宜主何人见，应怯过黄昏。\n朝阳梦断，熏残沈水，谁为招魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8634, '谒金门', '毛并', '春已半。\n芳草池塘绿遍。\n山北山南花烂熳。\n日长蜂蝶乱。\n闲掩屏山六扇。\n梦好强教惊断。\n愁对画梁双语燕。\n故心人不见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8635, '谒金门', '毛并', '伤离索。\n犹记并肩池阁。\n病起绿窗闲倚薄。\n一秋天气恶。\n玉臂都宽金约。\n歌舞新来忘却。\n回首故人天一角。\n半江枫又落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8636, '玉楼春', '毛并', '日长澹澹光风转。\n小尾黄蜂随早燕。\n行寻香迳不逢人，惟有落红千万片。\n酒成憔悴花成怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8637, '玉楼春', '毛并', '曲房小院匆匆过。\n急鼓疏钟催又去。\n来如春梦几多时，去似朝云无觅处。\n金瓶落井翻相误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8638, '蝶恋花', '毛并', '罗袜匆匆曾一遇。ピ\n乌鹊归来，怨感流年度。ピ\n别袖空看啼粉污。ピ\n相思待倩谁分付。ピ\n残雪江村回马路。ピ\n袅袅春寒，帘晚空凝伫。ピ\n人在梅花深处住。ピ\n梅花落尽愁无数。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8639, '薄幸', '毛并', '柳桥南畔。\n驻骢马、寻春几遍。\n自见了、生尘罗袜，尔许娇波流盼。\n为感郎、松柏深心，西陵已约平生愿。\n记别袖频招，斜门相送，小立钗横鬓乱。\n恨暗写、如蚕纸，空目断、高城人远。\n奈当时消息，黄姑织女，又成王谢堂前燕。\n托琴心怨。\n怕娇云弱雨，东风蓦地轻吹散。\n伤春病也，狼藉飞花满院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8640, '应天长令・应天长', '毛并', '曲栏十二闲亭沼。\n履迹双沈人悄悄。\n被池寒，香炉小。\n梦短女墙莺唤晓。\n柳风轻袅袅。\n门外落花多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8641, '点绛唇', '毛并', '夜色侵霜，萧萧络纬啼金井。\n梦寒初惊。\n一倍铜壶永。\n无限思量，展转愁重省。\n熏炉冷。\n起来人静。\n窗外梧桐影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8642, '瑞鹤仙', '毛并', '柳风清昼溽。\n山樱晚，一树高红争熟。\n轻纱睡初足。\n悄无人、猗枕虚檐鸣玉。\n南园秉烛。\n叹流光、容易过目。\n送春归去，有无数弄禽，满径新竹。\n闲记追欢寻胜，杏栋西厢，粉墙南曲。\n别长会促。\n成何计，奈幽独。\n纵湘弦难寄，韩香终在，屏山蝶梦断续。\n对沿阶、细草萋萋，为谁自绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8643, '满江红', '毛并', '泼水初收，秋千外、轻烟漠漠。\n春渐远、绿杨芳草，燕飞池阁。\n已著单衣寒食後，夜来还是东风恶。\n对空山、寂寂杜鹃啼，梨花落。\n伤别恨，闲情作。\n十载事，惊如昨。\n向花前月下，共谁行乐。\n飞盖低迷南苑路，湔裙怅望东城约。\n但老来、憔悴惜春心，年年觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8644, '燕山亭', '毛并', '暖霭辉迟，雨过夜来，帘外春风徐转。\n霞散锦舒，密映窥，亭亭万枝开遍。\n一笑嫣然，犹记有、画图曾见。\n无伴。\n初睡起，昭阳弄妆日晚。\n长是相趁佳期，有寻旧流莺，贪新双燕。\n惆怅共谁，细绕花阴，空怀紫箫凄怨。\n银烛光中，且更待、夜深重看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8645, '调笑・调笑令', '洪适', '南土。\n贤铜虎。\n黄木湾头腾好语。\n骑羊执穗神仙五。\n拭目摩肩争睹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8646, '调笑・调笑令', '洪适', '寒食。\n人如织。\n藉草临流罗饮席。\n阳春有脚森双戟。\n和气欢声洋溢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8647, '调笑・调笑令', '洪适', '奇货。\n归帆过。\n击鼓吹箫相应和。\n楼前高浪风掀簸。\n渔唱一声山左。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8648, '调笑・调笑令', '洪适', '名世。\n花无二。\n高压提倾末利。\n素丝缕缕联芳蕊。\n一片云生宝髻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8649, '调笑・调笑令', '洪适', '音乐。\n传佳作。\n盖海旌幢开观阁。\n绮霞飞渡青油幕。\n好是登临行乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8650, '调笑・调笑令', '洪适', '弱水。\n天无际。\n相去扶胥知几里。\n高亭东望阳乌起。\n杲杲晨光初洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8651, '调笑・调笑令', '洪适', '佳节。\n初春月。\n飞盖倾城尊俎列。\n安期驾鹤朝金阙。\n丹灶分留岩穴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8652, '调笑・调笑令', '洪适', '饮器。\n贪泉水。\n山乳涓涓甘似醴。\n怀金嗜宝随人意。\n枉受恶名难洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8653, '调笑・调笑令', '洪适', '深浦。\n停舟处。\n只恐越装相染污。\n奇香一见如泥土。\n投著水中归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8654, '调笑・调笑令', '洪适', '明月。\n舟初歇。\n三峡重过惊久别。\n玉环留与人间说。\n诗罢离肠千结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8655, '调笑・调笑令', '洪适', '南海。\n繁华最。\n城郭山川雄岭外。\n遗踪嘉话垂千载。\n竹帛班班俱在。\n元戎好古新声改。\n调笑花前分队。\n高会。\n尊对。\n笑眼茸茸回盼睐。\n蹋筵低唱眉弯黛。\n翔凤惊鸾多态。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8656, '渔家傲引・渔家傲', '洪适', '正月东风初解冻。\n渔人撒网波纹动。\n不识雕梁并绮栋。\n扁舟重。\n眠鸥浴雁相迎送。\n溪北画桥弯。\n溪南古岸添青葑。\n长把鱼钱寻酒瓮。\n春一梦。\n起来拈笛成三弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8657, '渔家傲引・渔家傲', '洪适', '二月垂杨花糁地。\n荻芽迸绿春无际。\n细雨斜风浑不避。\n青笠底。\n三三两两鸣起。\n新妇矶边云接袂。\n女儿浦口山堆髻。\n一拥河豚千百尾。\n摇食指。\n城中虚却鱼虾市。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8658, '渔家傲引・渔家傲', '洪适', '三月愁霖多急雨。\n桃江绿浪迷洲渚。\n西塞山边飞白鹭。\n烟横素。\n一声乃山深处。\n红雨缤纷因水去。\n行行寻得神仙侣。\n楼阁五云心不住。\n分凤侣。\n重来翻恨花相误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8659, '渔家傲引・渔家傲', '洪适', '四月圆荷钱学铸。\n鳞鳞波暖鸳鸯语。\n无数燕雏来又去。\n鱼未取。\n钓丝直上蜻蜓聚。\n风弄碧漪摇岛屿。\n奇云蘸影千峰舞。\n骑马官人江上驻。\n天且暮。\n借舟送过沧波渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8660, '渔家傲引・渔家傲', '洪适', '五月河中菱荇遍。\n丝纶欲下相萦绊。\n却掉船来芳草岸。\n呼侣伴。\n蓑衣不把金章换。\n碧落云高星烂烂。\n波心举网星光乱。\n跃出鲤鱼长尺半。\n回首看。\n孤灯一点风吹散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8661, '渔家傲引・渔家傲', '洪适', '六月长江无暑气。\n怒涛漱壑侵沙觜。\n轻舟随浪起。\n何不畏。\n从来惯作风波计。\n别溆藕花舒锦绮。\n采莲三五谁家子。\n问我买鱼相调戏。\n飘芰制。\n笑声咭咭花香里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8662, '渔家傲引・渔家傲', '洪适', '七月凛秋飞叶响。\n长吟杳杳澄江上。\n秃尾槎头添一网。\n丝自纺。\n新炊菰饭更相饷。\n渡口青烟藏叠嶂。\n岸旁红蓼翻轻浪。\n沈浮双漾漾。\n闻鸣桨。\n高飞拍拍穿林莽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8663, '渔家傲引・渔家傲', '洪适', '八月紫莼浮绿水。\n细鳞巨口鲈鱼美。\n画舫问渔篙暂舣。\n欣然喜。\n金齑顷刻尝珍味。\n涌雾驱云天似洗。\n静看星斗迎蟾桂。\n枕棹眠蓑清不睡。\n无名利。\n谁人分得逍遥意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8664, '渔家傲引・渔家傲', '洪适', '九月芦香霜旦旦。\n丹枫落尽吴江岸。\n长濑黄昏张蟹断。\n灯火乱。\n圆沙惊起行行雁。\n半夜系船桥北岸。\n三杯睡著无人唤。\n睡觉只疑桥不见。\n风已变。\n缆绳吹断船头转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8665, '渔家傲引・渔家傲', '洪适', '十月橘洲长鼓。\n潇湘一片尘缨洗。\n斩得钓竿斑染泪。\n中夜里。\n时闻鼓瑟湘妃至。\n白发垂纶孙又子。\n得钱沽酒长长醉。\n小艇短篷真活计。\n家云水。\n更无王役并田税。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8666, '渔家傲引・渔家傲', '洪适', '子月水寒风又烈。\n巨鱼漏网成虚设。\n圉圉从它归丙穴。\n谋自拙。\n空归不管旁人说。\n昨夜醉眠西浦月。\n今宵独钓南溪雪。\n妻子一船衣百结。\n长欢悦。\n不知人世多离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8667, '渔家傲引・渔家傲', '洪适', '腊月行舟冰凿罅。\n潜鳞透暖偏堪射。\n岁岁年年篷作舍。\n三冬夜。\n牛衣自暖何须借。\n滕六晚来方命驾。\n千山绝影飞禽怕。\n江上雪如花片下。\n宜入画。\n一蓑披著归来也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8668, '调笑・调笑令', '洪适', '渔父饮时花作荫。\n羹鱼煮蟹无它品。\n世代太平除酒禁。\n渔父饮。\n绿蓑藉地胜如锦。\n渔父醉时收钓饵。\n鱼梁晒翅闲乌鬼。\n白浪撼船眠不起。\n渔父醉。\n滩声无尽清双耳。\n渔父醒时清夜永。\n澄澜过尽征鸿影。\n略略风来舴艋。\n渔父醒。\n月高露下衣裳冷。\n渔父笑时莺未老。\n提鱼入市归来早。\n一叶浮家生计了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8669, '鹧鸪天', '洪适', '报答风光思更新。\n安排好语续阳春。\n罗胸玉藻英华别，信手银钩点画匀。\n歌妙曲，想光尘。\n相望尺五叹参辰。\n曲终强对红颜笑，欠我高谈惊座人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8670, '生查子', '洪适', '廉纤小雨来，噤轻寒乍。\n丝竹送迎时，灯火阑珊夜。\n铜壶漏故迟，银烛花频。\n怀我独醒人，健笔方飞洒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8671, '蝶恋花', '洪适', '漠漠水田飞白鹭。\n夏木阴阴，巧啭黄鹂语。\n金匮诗人新得句。\n江山应道来何暮。\n好向金门联步武。\n何事双旌，却为丹丘驻。\n琼十分须一举。\n看看紫诏催归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8672, '减字木兰花', '洪适', '藩车容裔。\n挺挺风流追两地。\n粲斗分星。\n诗句当年汗简青。\n疏帘披绣。\n共看横云晴出岫。\n新月如钩。\n来照琼彝醉小楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8673, '好事近', '洪适', '风细晚轩凉，妙句初挥新墨。\n绿水池中宾佐，对嫩荷擎绿。\n坐看微月上云头，清臂映寒玉。\n只恐朝来酒醒，有文书羁束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8674, '虞美人', '洪适', '芭蕉滴滴窗前雨。\n望断江南路。\n乱云重叠几多山。\n不似倦飞鸥鹭、便知还。\n角声更听谯门弄。\n夜夜思归梦。\n鄱江楼下水含漪。\n孤负钓滩烟艇、绿蓑衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8675, '卜算子', '洪适', '修竹拂疏棂，淡月侵凉榭。\n四畔青山进好风，金鸭香煤。\n宝唾粲珠玑，长袖飘兰麝。\n莫问更楼夜若何，且结高阳社。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8676, '江城子', '洪适', '冥冥云屿两经秋。\n落霞收。\n断烟留。\n小阁凉生，清馥凝金虬。\n乘兴开颜那草草，烦玉腕，举琼舟。\n明年此日楚江头。\n极层楼。\n望丹丘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8677, '减字木兰花', '洪适', '使君情素。\n念我明朝行县去。\n一醉相留。\n和气欢声到小楼。\n暂时南北。\n莫唱渭城朝雨曲。\n此去农郊。\n收拾童儿五裤谣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8678, '浣溪沙', '洪适', '邦伯今推第一流。\n几因歌席负诗筹。\n一时文采说台州。\n雨脚渐收风入牖，云心初破月窥楼。\n翠眉相映晚山秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8679, '望海潮', '洪适', '重溟倒影，五芝含笑，神仙今古台州。\n山拥黄堂，烟披画戟，双岩瑞气长浮。\n前事记鳌头。\n有百年台榭，千室嬉游。\n墨宝凄凉，风凌雨蠹尽悠悠。\n规恢共仰贤侯。\n当政成五月，景对三秋。\n飞栋干云，虚檐受露，放怀不减南楼。\n宾燕奉觥筹。\n妙绮笺琼藻，声度歌喉。\n只恐棠阴成後，趣去侍凝旒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8680, '好事近', '洪适', '小阁过重阳，愁对轻篁团色。\n喜得蛮笺新唱，似夜光明月。\n萸房菊蕊定相怜，酩酊误蕉叶。\n犹记去年今夜，听歌声清切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8681, '清平乐', '洪适', '风鬟飞乱。\n寒入秦筝雁。\n情似云阴浑未展。\n雨脚更飘银线。\n横枝有意先开。\n玉尘欲伴金。\n何日舞歌扇，後堂重到惟梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8682, '选冠子', '洪适', '雨脚报晴，云容成瑞，夜雪萦盈连昼。\n千岩曳缟，万瓦堆琼，稍稍冷侵怀袖。\n鹤氅神仙，兔园宾客，高会坐移清漏。\n想灞陵桥畔，苦吟缓辔，耸肩寒瘦。\n向此际、色映堂阴，香传梅影，寒力更欺尊酒。\n左符词伯，蛮笺巧思，不道起风飞柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8683, '好事近', '洪适', '缥酒颂青春，不减宜城桑落。\n楼下玉人凝笑，散万英千萼。\n绣衣当日帝王州，横飞看雕鹗。\n闻道赐环书下，向金门持橐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8684, '鹧鸪天', '洪适', '领客携尊花底开。\n薄寒初送雨声来。\n一声未弄林间笛，几片低飞阁下梅。\n酬的，少迟回。\n不妨春雪撒银杯。\n玉肌莫放清香散，更待晴时赏一回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8685, '浣溪沙', '洪适', '整顿春衫欲跨鞍。\n一杯相属少开颜。\n愁眉不似旧时弯。\n未见两星添柳宿，忍教三叠唱阳关。\n相思空望会稽山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8686, '浣溪沙', '洪适', '报道倾城出洞房。\n水边疏影弄清香。\n风流更有小鸳鸯。\n蝉鬓半含花下笑，蛾眉相映醉时妆。\n梦魂不到白云乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8687, '浣溪沙', '洪适', '玉颊微醺怯晚寒。\n可怜凝笑整双翰。\n枝头一点为谁酸。\n只恐轻飞烟树里，好教斜插鬓云边。\n淡妆仍向醉中看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8688, '浣溪沙', '洪适', '忆得熙春晓立班。\n使星曾入紫微垣。\n归来小饮友芝兰。\n投辖风流今复见，开尊礼数自来宽。\n更看宝唾写乌阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8689, '清平乐', '洪适', '轻红淡白。\n蓬阆神仙谪。\n魏紫姚黄夸异色。\n到得海边初识。\n玉阑不语如颦。\n虚教春尽三分。\n却问檀心谁向，多情更属东君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8690, '生查子', '洪适', '桃疏蝶惜香，柳困莺惊絮。\n日影过帘旌，多少愁情绪。\n红惨武陵溪，绿暗章台路。\n春色似行人，无意花间住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8691, '思佳客', '洪适', '花信今无一半风。\n芙蓉出水几时红。\n看成弱柳阴阴绿，自在迁莺巧语中。\n风傍户，月留空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8692, '朝中措', '洪适', '当年召父治南阳。\n千室颂慈祥。\n今代天台太守，声名已达岩廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8693, '朝中措', '洪适', '江西文派有新图。\n诗律嗣东湖。\n十首齐安书事，君王曾问相如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8694, '朝中措', '洪适', '青云垂下不争程。\n绣斧记澄清。\n黄木湾头人闹，耳边都是欢声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8695, '朝中措', '洪适', '斗南楼阁舞祥云。\n为寿几多人。\n有酒恰如东海，年年为满金尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8696, '朝中措', '洪适', '西当日下云骈。\n采藻奉苏仙。\n玉节荣看棠棣，斑衣笑俯芝兰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8697, '朝中措', '洪适', '嘉禾一别十经春。\n清泖记垂纶。\n今日天涯沦落，跫然一见佳人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8698, '浣溪沙', '洪适', '占得登高一日先。\n跨云来作地行仙。\n天将黄菊助长年。\n健笔已凌枚叟赋，高怀欲著祖生鞭。\n组向甘泉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8699, '临江仙', '洪适', '向日行瞻凤彩，共期直上金銮。\n却来持节海云边。\n身兼三使者，名是一仙官。\n汉室中兴高密冠，千年苗裔蝉联。\n左弧嘉庆舞祥烟。\n橘中招四老，同醉酒如泉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8700, '临江仙', '洪适', '北斗南头云送喜，人间快睹魁星。\n向来平步到蓬瀛。\n如何天上客，来佐海边城。\n方伯娱宾香作穗，风随歌扇凉生。\n且须滟滟引瑶觥。\n十年迟凤诏，万里寄鹏程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8701, '临江仙', '洪适', '钓濑怀珠山韫玉，谪仙至自蓬莱。\n它年勋业上云台。\n棣华开幕府，莲沼屈英才。\n南极逢秋光烂烂，门阑香雾萦回。\n须将寿卉荐琼杯。\n篱东明日菊，借取一枝来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8702, '临江仙', '洪适', '烟凑横岚霞抱日，望中衰草稠稠。\n西风吹恨著扁舟。\n马卿多病後，方寸不禁秋。\n颇念银壶行绿醑，共听渔子清讴。\n梦魂飞过海山楼。\n人随秋易老，情寄水东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8703, '临江仙', '洪适', '干吕青云垂宝露，结邻恰挂初弦。\n瑞光腾踊杂非烟。\n骑箕瞻鼻祖，孕昴控胎仙。\n勋业子卿全汉节，壮怀久寄林泉。\n举觞低唱脸舒莲。\n寿高人七十，果熟岁三千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8704, '临江仙', '洪适', '瓜瓞绵绵储庆远，闲平代有名人。\n一襦五裤说朱轮。\n云逵鸳缀近，雷社虎符新。\n正是泗滨浮磬日，潘舆一粲欣欣。\n鸾歌飞起杏梁尘。\n巢莲龟问岁，介寿酒融春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8705, '临江仙', '洪适', '远驾星屏临百粤，康沂户户歌功。\n使君五马去乘骢。\n卖刀无旷土，赠扇有仁风。\n莫唱渭城朝雨曲，片帆时暂西东。\n促归行拜紫泥封。\n九霄先步武，三接未央宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8706, '江城子', '洪适', '当年提笔上词坛。\n琢琅。\n涌波澜。\n晁董声名，一日满人间。\n底事远烦骐骥足，梅岭外，砚台边。\n元戎倾盖有馀欢。\n酒杯宽。\n语离难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8707, '江城子', '洪适', '江如罗带抱山青。\n好风轻。\n五云横。\n北斗南边，烨烨使华星。\n两路平反多少事，培吉德，赍长生。\n当年乌府振冠缨。\n稔英声。\n起鹏程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8708, '醉蓬莱', '洪适', '正中秋初过，重阳相近，金茎多露。\n玉燕开祥，喜气浮庭户。\n览凤千峰，骖鸾八桂，未展青云步。\n碧玉边，红莲池上，羽仙旁午。\n少日声名，珠玑黼黻，晔煜分符，喧轰持斧。\n带缓裘轻，足远人襦裤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8709, '满庭芳', '洪适', '昴宿光芒，德星家世，当时飞舞华旗。\n风清玉宇，珠露缀瑶枝。\n八桂苍苍耸壑，问椿木、同数秋期。\n黄堂上，油幢转影，美酒注金卮。\n英躔，名誉早，青箱传学，黄绢辞。\n说江东治行，召杜肩齐。\n畏爱双行五管，收绣斧、却把旌麾。\n欢声沸，明年此日，公在凤凰池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8710, '千秋岁', '洪适', '颜朱鬓绿。\n天与穰穰福。\n旄钺贵，崇汤沐。\n华轩鱼映锦，紫诰鸾回幅。\n为寿处，玻璃凿落斟。\n瑞雾蟠华屋。\n露秋兰馥。\n香篆起，歌裾簇。\n衣斑丹穴凤，色润东床玉。\n鸾共鹤，年年来听神仙曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8711, '眼儿媚', '洪适', '黄堂风转碧幢开。\n笙鹤九天来。\n三冬爱日，一方惠露，人在春台。\n持杯多赞松乔喜，低唱列金钗。\n明年此日，紫微垣里，光应中台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8712, '鹧鸪天', '洪适', '月上初弦映左弧。\n葭吹六转璇枢。\n日边远近瞻新渥，天下中庸系两都。\n犀献角，蚌回珠。\n皇皇星节烛扶胥。\n满斟北海尊中酒，请寿安期涧底蒲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8713, '长相思', '洪适', '朝思归。\n暮思归。\n塞雁三年不见飞。\n断肠天一涯。\n千思归。\n万思归。\n梦到窗前拂淡眉。\n觉来双泪垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8714, '长相思', '洪适', '柳青青。\n酒清清。\n雨脚涔涔忆渭城。\n一尊和泪倾。\n山青青。\n水清清。\n水阔山重不计程。\n愁堆长短亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8715, '好事近', '洪适', '柳岸碧漪深，底事催人行色。\n无计曲留情话，只别愁如织。\n小蛮樊素两倾城，几度醉狂客。\n明日扁舟西去，听歌声不得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8716, '点绛唇', '洪适', '天末相逢，醉中不讶车茵污。\n一声鸣橹。\n惊散眠沙鹭。\n我是行人，却送行人去。\n听金缕。\n莫辞甘醑。\n别泪飞寒雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8717, '南歌子', '洪适', '云拂山腰过，风吹雨点来。\n田园好处有池台。\n记著相逢时节、海棠开。\n蝴蝶那无梦，鸳鸯亦有媒。\n藏钩解佩两三杯。\n明日水边沙际、首空回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8718, '好事近', '洪适', '烂漫海棠花，多谢东君留得。\n眉寿堂边风景，与蓬瀛咫尺。\n桃红李白竞争妍，绿野尽春色。\n只欠樱唇清唱，怕行云南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8719, '生查子', '洪适', '带郭得盘洲，胜处双溪水。\n月榭间风亭，叠嶂横空翠。\n团栾情话时，三径参差是。\n听我一年词，对景休辞醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8720, '生查子', '洪适', '正月到盘洲，解冻东风至。\n便有浴鸥飞，时见潜鳞起。\n高柳送青来，春在长林里。\n绿萼一枝梅，端是花中瑞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8721, '生查子', '洪适', '二月到盘洲，繁缬盈千萼。\n恰恰早莺啼，一羽黄金落。\n花边自在行，临水还寻壑。\n步步肯相随，独有苍梧鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8722, '生查子', '洪适', '三月到盘洲，九曲清波聚。\n修竹荫流觞，秀叶题佳句。\n红紫渐阑珊，恋恋莺花主。\n芍药拥芳蹊，未放春归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8723, '生查子', '洪适', '四月到盘洲，长是黄梅雨。\n屐齿满莓苔，避湿开新路。\n极望绿阴成，不见乌飞处。\n云采列奇峰，绝胜看庐阜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8724, '生查子', '洪适', '五月到盘洲，照眼红巾蹙。\n句引石榴裙，一唱仙翁曲。\n藕步进新船，斗楫飞云速。\n此际独醒难，一一金锺覆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8725, '生查子', '洪适', '六月到盘洲，水阁盟鸥鹭。\n面面纳清风，不受人间暑。\n彩舫下垂杨，深入荷花去。\n浅笑擘莲蓬，去却中心苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8726, '生查子', '洪适', '七月到盘洲，枕簟新凉早。\n岸曲侧黄葵，沙际排红蓼。\n团团歌扇疏，整整炉烟袅。\n环坐待横参，要乞珠丝巧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8727, '生查子', '洪适', '八月到盘洲，柳外寒蝉懒。\n一掬木犀花，泛泛玻璃盏。\n蟾桂十分明，远近秋毫见。\n举酒劝嫦娥，长使清光满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8728, '生查子', '洪适', '九月到盘洲，华发惊霜叶。\n缓步绕东篱，香蕊金重叠。\n橘绿又橙黄，四老相迎接。\n好处不宜休，莫放清尊歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8729, '生查子', '洪适', '十月到盘洲，小小阳春节。\n晚菊自争妍，谁管人心别。\n木末簇芙蓉，禁得霜如雪。\n心赏四时同，不与痴人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8730, '生查子', '洪适', '子月到盘洲，日影长添线。\n水退露溪痕，风急寒芦战。\n终日倚枯藤，细看浮云变。\n洲畔有圆沙，招尽云边雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8731, '生查子', '洪适', '腊月到盘洲，寒重层冰结。\n试去探梅花，休把南枝折。\n顷刻暗同云，不觉红炉热。\n隐隐绿蓑翁，独钓寒江雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8732, '生查子', '洪适', '一岁会盘洲，月月生查子。\n弟劝复兄酬，举案灯花喜。\n曲终人半酣，添酒留罗绮。\n车马不须喧，且听三更未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8733, '阮郎归', '洪适', '澄清阁下藕如船。\n扁舟曾采莲。\n向来辛苦叠青钱。\n而今知几年。\n人去也，客凄然。\n酒泉添泪泉。\n一杯今夜且留连。\n断肠芳草边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8734, '浣溪沙', '洪适', '丹桂飘香已四番。\n杖藜携手自今难。\n黯淡离恨满江干。\n壁上两冠元是谶，花前双韵几时弹。\n中秋後夜与谁看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8735, '满江红', '洪适', '暮雨萧萧，飞败叶、增添秋色。\n登高会、痴风吹散，山居佳客。\n人世难逢开口笑，老来便觉流年迫。\n到如今、黄菊满园开，无人摘。\n珠履凑，铢衣窄。\n萦翠袖，催牙拍。\n索松儿添半，战酣相吓。\n橘绿橙黄时节好，舞停歌罢门墙隔。\n酒醒时、枕上一声鸡，东方白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8736, '满江红', '洪适', '累月愁霖，知今夕、是何天色。\n秋老矣、芙蓉遮道，黄花留客。\n长有霜螯来左右，谁言枥马能煎迫。\n眄高穹、重叠起顽云，星难摘。\n罗绮盛，轩窗窄。\n心已醉，肩须拍。\n更十分行酒，再三相吓。\n凤诏十行归路近，桂华千里明年隔。\n趁闲时、楼上共凝眸，芦花白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8737, '临江仙', '洪适', '两载绣衣频驻节，金莲曾印青苔。\n匆匆归去寿琼杯。\n曲终挥别泪，江上片帆开。\n记得秋宵山吐月，酒酣同上层台。\n杖藜何日解重来。\n相思凭过雁，飞送一枝梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8738, '浣溪沙', '洪适', '举目霜林叶叶黄。\n使星归骑未须忙。\n烟鬟千叠弄残妆。\n内殿恩光承雨露，外台风力挟冰霜。\n应怀三径杂花香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8739, '浣溪沙', '洪适', '不见丹丘三十年。\n青山碧水想依然。\n自惊绿鬓已苍颜。\n月在柳梢曾径醉，雨荒院菊有谁怜。\n绣衣归与古人言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8740, '生查子', '洪适', '碧涧有神龟，千岁游莲叶。\n七十古来稀，寿母杯频接。\n绣衣牵彩衣，喜庆相重叠。\n龟紫看孙曾，鹤发何须镊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8741, '生查子', '洪适', '贪看端木花，难办销金帐。\n庭下舞琼瑶，飞到须眉上。\n衰病不禁寒，对景频惆怅。\n梦寐到凌风，倚著青藜杖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8742, '鹧鸪天', '洪适', '莫问甘醪浊与清。\n试将一酌破愁城。\n海棠过後荼蘼发，堪叹人间不再生。\n心已老，眼重明。\n嫣然国色带朝酲。\n耳边听得兰亭曲，一咏流觞已有名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8743, '鹧鸪天', '洪适', '两塾弦歌日日春。\n不容坐席更凝尘。\n常思芳桂攀燕窦，未见童乌继子云。\n流庆泽，仰家尊。\n救荒阴德过于门。\n从师已是平原客，毛遂怀绷作弄孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8744, '好事近', '洪适', '春意渐盈盈，窗外小桃堪折。\n若问得人怜处，是轻颦时节。\n主人特地出红妆，不要云心月。\n三径虽然冷淡，有采莲舟楫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8745, '满江红', '洪适', '春色匆匆，三分过、二分光景。\n吾老矣，坡轮西下，可堪弄影。\n曲水流觞时节好，茂林修竹池台永。\n望前村、绿柳荫茅檐，云封岭。\n蜂蝶闹，烟花整。\n百年梦，如俄顷。\n这回头陈迹，漫劳深省。\n吹竹弹丝谁不爱，焚琴煮鹤人何肯。\n尽三觥、歌罢酒来时，风吹醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8746, '满江红', '洪适', '雨过春深，溪水涨、绿波溶溢。\n年年是、杨花吹絮，草茵凝碧。\n驹隙光阴身易老，槐安梦幻醒难觅。\n算六分、春色五分休，才留一。\n雁鹜静，文书毕。\n尘外趣，壶中日。\n喜兰亭修禊，郊出。\n合璧连珠同啸咏，怒猊渴骥尤清逸。\n酒酣时、梁上暗尘飞，无痕迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8747, '满江红', '洪适', '衰老贪春，春又老、尊交溢。\n凝目处、清漪拍岸，四山堆碧。\n白也论文情最厚，维摩示病心难觅。\n到盘洲、车骑太匆匆，觞浮一。\n春再见，官期毕。\n归路近，长安日。\n奉清时明诏，迭回更出。\n上殿风霜生颊齿，元龟献替图无逸。\n记而今、杖策过溪桥，留行迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8748, '满江红', '洪适', '燕寝香凝，官事了、诗情充溢。\n归後院、花容争媚，柳眉添碧。\n老子胡床常自叹，轻裾长袖从何觅。\n探城楼、此际夜如何，更筹一。\n人已老，春将毕。\n临曲水，才旬日。\n快朝来雨过，鱼儿争出。\n淡酒一杯空酩酊，黄堂千骑真安逸。\n问朱、何日到丘园，联綦迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8749, '满江红', '洪适', '百计留春，春不住、愁怀填溢。\n争如对、宝梳压鬓，翠环铺碧。\n紫绶金章都是梦，云庐花坞如何觅。\n劝金杯、浅笑傍宾筵，须均一。\n前夜月，新离毕。\n收雨，呈红日。\n荷主人情厚，五云齐出。\n一颗樱桃天付与，数声水调人飘逸。\n叹荒园、三月百花残，无踪迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8750, '南歌子', '洪适', '闰岁饶光景，中旬始打春。\n拥炉看雪酒催人。\n梁上不曾飞落、去年尘。\n未暇巾车出，何妨举盏频。\n斜川日月已成陈。\n想得前村仙子、晚妆匀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8751, '南歌子', '洪适', '多病都缘老，寒阴可惜春。\n栽桃种竹怕因循。\n移转蓝舆藤杖、未开门。\n真率须如约，安排欲效颦。\n莫将筝笛损精神。\n自有啼莺舞鹤、解随人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8752, '南歌子', '洪适', '顽健输村老，嬉游付後生。\n七旬才有五清明。\n须趁良辰美景、绕园行。\n云意将飞雪，天心未肯晴。\n难将性命作人情。\n只合拥炉清坐、阅医经。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8753, '南歌子', '洪适', '住得如筛雪，方欣有脚春。\n谁云三尺不须循。\n若是诗僧月下、许敲门。\n钜竹多中断，残梅竞小颦。\n畦丁说与主林神。\n扫洒板桥前径、待吾人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8754, '南歌子', '洪适', '强作千年调，难逾五度春。\n脊令继踵漫相循。\n休要关心药裹、也扃门。\n蕙帐银杯化，纱窗翠黛颦。\n烧香试问紫姑神。\n一岁四并三乐、几多人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8755, '南歌子', '洪适', '南浦山罗列，东湖水渺弥。\n主人好客过当时。\n斗转参横时候、醉如泥。\n莫管莺声老，从它柳絮飞。\n野园春色别无奇。\n船上有花多酒、未须归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8756, '好事近', '洪适', '睡足淡梳妆，喜见诗人元白。\n不学艳红妖紫，环花仙标格。\n须知玉骨本天然，不是借人力。\n准拟小春重看，望秋灰无射。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8757, '卜算子', '洪适', '五凤望中仙，五马人间贵。\n舞态歌声尽出群，乌鹊巡檐喜。\n昨夜值狂风，痛饮全无味。\n说与谯门漫打更，却怕催归骑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8758, '满庭芳', '洪适', '华发苍头，年年更变，白雪轻犯双眉。\n六旬过四，七十古来稀。\n问柳寻花兴懒，拈筇杖、闲绕园池。\n尊中有，青州从事，无意唤琼彝。\n人生，何处乐，楼台院落，吹竹弹丝。\n奈壮怀销铄，病费医治。\n漫道琴弦绿绮，游鱼听、山水谁知。\n盘洲怨，盟鸥闲阔，痍鹤立新碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8759, '满庭芳', '洪适', '风搅花间，雨悭柳下，人人懒拂愁眉。\n年荒省事，投辖井中稀。\n架上舞衣尘积，弦索断、筝雁差池。\n南柯梦，转头陈迹，饥鼠穴空彝。\n新年，官事少，秋蛇春蚓，重叠乌丝。\n更出奇花判，百病都治。\n报道行厨办也，乌鹊喜、龟鹤前知。\n更书近，行浸远，长对去思碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8760, '满庭芳', '洪适', '酒销愁，逢场作戏，何曾择地伸眉。\n诗筒来往，如我与君稀。\n喜得青春有闰，添日月、款曲临池。\n洲盘有，山肴野蔌，安用设鸡彝。\n老来，空自笑，一头梳雪，两鬓吹丝。\n便常逢社饮，聋不堪治。\n曾就新年真率，花神报、蜂蝶皆知。\n东风恶，江梅欲尽，荐福莫轰碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8761, '满庭芳', '洪适', '柳径花台，熙熙春动，游人珥堕簪遗。\n枯藤到处，绿刺惹冠衣。\n雪後园林更好，琼作佩、香满横枝。\n巡檐久，留连一笑，不管午阴移。\n盘洲，今雅集，皇华飞盖，挥麈迟迟。\n觉龟鱼增价，草木生辉。\n梁上不教尘落，谈文字、酒散星稀。\n明年好，玉津随驾，回首记襟期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8762, '满庭芳', '洪适', '同病相怜，冻吟谁伴，漫怀举案齐眉。\n槐安梦境，一笑自来稀。\n未到斜川见雪，春欲半、尚压铜池。\n今思古，拊盆击筑，虿鼎闲夔彝。\n何时。\n天意解，并游花坞，旋扫蛛丝。\n对壶中闲日，冗牍休治。\n四坐同盟情话，飞玉麈、万事多知。\n杯盘省，浅斟随意，真率视前碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8763, '满庭芳', '洪适', '蝴蝶梦魂，芭蕉身世，几人得到庞眉。\n十分如意，天赋古今稀。\n昼日猥叨三接，摩鹏翼、曾化鲲池。\n槐阴下，深惭房魏，那敢作封彝。\n雁行，争接翅，北门矩烛，西掖纶丝。\n幸归来半世，园路先治。\n渔唱樵歌不到，莺燕语、何畏人知。\n编花史，修篁千亩，封植具穹碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8764, '满庭芳', '洪适', '春入花畦，雪迷筠坞，柳梢未肯低眉。\n泥深路滑，车马往来稀。\n平地琼琚盈尺，冰冻解、檐水如池。\n皇华喜，增添泉货，不铸尚方彝。\n光阴，驹过隙，髭髯如戟，容易成丝。\n把诗盟长讲，酒病休治。\n两两垂螺舞彻，藏羌管、人已潜知。\n樯乌转，钱流地上，褒诏便刊碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8765, '满庭芳', '洪适', '当国无功，归田有分，四山浓抹烟眉。\n春云多变，清昼惠风稀。\n欲踵兰亭故事，溪水涨、簪盍鹅池。\n临修竹，一觞一咏，考古到辛彝。\n当时。\n龙衮侧，亲闻胪句，天语如丝。\n谩三年博士，局冗争治。\n底事绣衣留滞，青天瑞、奴隶皆知。\n迎归诏，鸾台凤阁，名记壁间碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8766, '满庭芳', '洪适', '草阁烟横，花蹊雨润，伤春谁画鸦眉。\n药囊未减，尊酒自然稀。\n堪叹云和挂壁，弦半绝、鼠啮龙池。\n投壶罢，凭阑玩古，罗列父丁彝。\n龟巢，添绿皱，残梅片片，新柳丝丝。\n恨风狂折竹，鹤病谁治。\n自信年衰景短，甘冷淡、应也天知。\n埙篪奏，清歌醉墨，一一上圭碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8767, '满庭芳', '洪适', '雨洗花林，春回柳岸，窗间列岫横眉。\n老来光景，生怕聚谈稀。\n何事扁舟西去，收杖屦、契阔鱼池。\n流觞近，诗筒暂歇，焉用虎文彝。\n良辰，怀旧事，海棠花下，笑摘垂丝。\n叹五年一别，万病难治。\n几处绣衣尘迹，歌舞地、乌鹊曾知。\n君今去，珠帘暮卷，山雨拂崇碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8768, '满庭芳', '洪适', '旧日盘洲，藏钩卜夜，松儿笑拣双眉。\n老人好静，此乐数年稀。\n尚记乘舟西溯，楼卷雪、曾到雷池。\n今非惜，畏寒闭户，弃掷夏商彝。\n入春，逾两月，轻烟非雾，细雨如丝。\n任风颓花架，不惮装治。\n想得醉吟滕阁，家园事、争解详知。\n归来好，猿惊鹤怨，孤负辋川碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8769, '望江南・忆江南', '洪适', '嗟故岁，夏旱复秋阳。\n十雨五风皆定数，千方百计为灾伤。\n小郡怎禁当。\n劳拊字，惠露洽丁黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8770, '望江南・忆江南', '洪适', '倾盖侣，古语诵邹阳。\n曲水一觞今意懒，阳关三叠重情伤。\n离恨落花当。\n人截镫，归骑莫仓黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8771, '西江月', '洪适', '小室坐毡重叠，红炉兽炭交加。\n一卮村酒吸流霞。\n窗外寒威可怕。\n心在盘洲种柳，眼看密雪飞花。\n银杯缟带不随车。\n江上渔蓑难画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8772, '西江月', '洪适', '席上酒杯难减，鼎中药味频加。\n老人争得脸如霞。\n镜里衰容人怕。\n檐溜尽成冰柱，前村变却梅花。\n琼瑶破碎为行车。\n冻雀盈枝堪画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8773, '眼儿媚', '洪适', '瀛仙好客过当时。\n锦幌出蛾眉。\n体轻飞燕，歌欺樊素，压尽芳菲。\n花前一盼嫣然媚，滟滟举金卮。\n断肠狂客，只愁径醉，银漏催归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8774, '六州歌头', '洪适', '严更永，今夕是何年。\n玉衡正，钩陈灿，天字起祥烟。\n协风应、江海安澜。\n重规仍叠矩，圣主乘乾。\n尧授舜、盛事光前。\n称寿玉卮边。\n三年亲祀，一阳回律，八乡承宇，觚陛紫为坛。\n仰天颜。\n斋居寂，诚心肃，礼容专。\n存锺石，约舆卫，五辂不求全。\n听金钥、虎旅无眠。\n俨千官。\n须期显。\n相嘉笾。\n一人俭德动天渊。\n费减大农钱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8775, '十二时・忆少年', '洪适', '庭有燎，叠鼓鸣鼍。\n更问夜如何。\n信星彪列，天象森罗。\n虞旦宫毕，觞清庙，浆柘尊牺继猗那。\n嘉颂可同科。\n卮圣万肩摩。\n饬躬三宿，泰缛仪多。\n丘泽合，岳渎从曦娥。\n神光烛、云车风马，芝作盖，玉为珂。\n奉成礼，燔柴竣事，休嘉砰，隐丹阙，湛恩波。\n共愿乾坤祉，边鄙投戈。\n覆盂连瀚海，洗甲挽天河。\n欣欣喜色，长遇六龙过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8776, '奉礼歌', '洪适', '吹葭缇龠气潜分。\n云采宜书壤效珍。\n长日至，一阳新。\n四时玉烛和匀。\n物欣欣。\n造化转洪钧。\n郊之祭，孤竹管，六变舞云门。\n自古严。\n牺牲具，粢盛洁，豆笾陈。\n衮龙陟降，币玉纷纶。\n彻高阍。\n灵之，神哉沛，排历昆仑。\n九歌毕，盈郊瞻燎，斗转参横将旦，天开地辟如春。\n清跸移轮。\n阗然鼓吹相闻。\n祥云。\n欢胪八陛，厘逆三神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8777, '降仙台', '洪适', '漏残柝静鸡声远，到高燎。\n入层霄。\n云裘蟠瑞霭，天步下嘉坛，旗旆飘摇。\n黄麾列仗貔貅整，气压江潮。\n导前从後盛官僚。\n玉佩间金貂。\n望扶桑，日渐高。\n阴霾霜雪，底处不潜消。\n辇路祥飙。\n披拂绛纱袍。\n云间瑞阙仰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8778, '导引', '洪适', '重华天子，长至奉神虞。\n九奏会轩朱。\n星晖云润东方晓，拜贶竹宫初。\n归来千乘护皇舆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8779, '点绛唇', '韩元吉', '木落霜浓，探春只道梅花未。\n嫩红相倚。\n灼灼新妆腻。\n莫问仙源，且问花前事。\n休辞醉。\n想君园□。\n总是生春地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8780, '浣溪沙', '韩元吉', '莫惜清尊领客同。\n已无花伴舞衣红。\n强歌归去莫匆匆。\n细雨弄烟烟弄日，断云黏水水黏空。\n酴飞下晚来风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8781, '霜天晓角', '韩元吉', '倚天绝壁。\n直下江千尺。\n天际两蛾凝黛，愁与恨、几时极。\n怒潮风正急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8782, '霜天晓角', '韩元吉', '几声残角。\n月照梅花薄。\n花下有人同醉，风满槛、波明阁。\n夜寂香透幕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8783, '菩萨蛮', '韩元吉', '春残日日风和雨。\n烟江目断春无处。\n山路有黄鹂。\n背人相唤飞。\n解鞍宿酒醒。\n枕残香冷。\n梦想小亭东。\n蔷薇何似红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8784, '菩萨蛮', '韩元吉', '江南雪里花如玉。\n风流越样新装束。\n恰恰缕金裳。\n浓熏百和香。\n分明篱菊艳。\n却作妆梅面。\n无处奈君何。\n一枝春更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8785, '菩萨蛮', '韩元吉', '薄云卷雨凉成阵。\n雨晴陡觉荷香润。\n波影澹寒星。\n水边镫火明。\n白苹洲上路。\n几度来还去。\n枕恨茫茫。\n笛声依夜长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8786, '菩萨蛮', '韩元吉', '诏书昨夜先春到。\n留公一共梅花笑。\n青琐凤凰池。\n十年归已迟。\n灵溪霜後水。\n的的清无比。\n比似使君清。\n要知清更明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8787, '菩萨蛮', '韩元吉', '墙根新笋看成竹。\n青梅老尽樱桃熟。\n幽墙几多花。\n落红成暮霞。\n闭门风又雨。\n只道春归去。\n媚脸笑持杯。\n却惊春思回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8788, '菩萨蛮', '韩元吉', '梧桐叶上秋萧瑟。\n画阑桂树攒金碧。\n花底最风流。\n相逢不上楼。\n数枝添宝髻。\n滴滴香沾袂。\n杯到莫留残。\n雾窗疑广寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8789, '减字木兰花', '韩元吉', '壶中春早。\n翦刻工夫天自巧。\n雨转风斜。\n吹作千林到处花。\n瑶池清浅。\n璧月琼枝朝暮见。\n莫上扁舟。\n且醉仙家白玉楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8790, '减字木兰花', '韩元吉', '风梳雨洗。\n玉阙琼楼何处是。\n万里秋容。\n唤起嫦娥酒未中。\n相逢且醉。\n忙里偷闲知有几。\n况自丰年。\n须信金华别是天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8791, '诉衷情', '韩元吉', '疏疏密密未开时。\n装点最繁枝。\n分明占断秋思，一任晓风吹。\n金屡细，翠绡垂。\n画阑西。\n嫦娥也道，一种幽香，几处相宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8792, '谒金门', '韩元吉', '春尚浅。\n谁把玉英裁翦。\n尽道梅梢开未遍。\n卷帘花满院。\n楼上酒融歌暖。\n楼下水平烟远。\n却似涌金门外见。\n絮飞波影乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8793, '谒金门', '韩元吉', '幽槛暑。\n又是一年重午。\n猎猎风蒲吹翠羽。\n楚天梅熟雨。\n往事潇湘南浦。\n魂断画船箫鼓。\n双叶石榴红半吐。\n倩君聊寄与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8794, '好事近', '韩元吉', '华屋翠云深，云外晚山千叠。\n眼底无穷春事，对杨枝桃叶。\n老来沈醉为花狂，霜鬓未须镊。\n几许夜阑清梦，任翻成胡蝶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8795, '好事近', '韩元吉', '秋意满芙蓉，红映小园丛竹。\n风里凤箫声扬，有新妆明玉。\n诗翁相对两悠然，一醉绕黄菊。\n目尽晚山横处，共修眉争绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8796, '秦楼月・忆秦娥', '韩元吉', '莺声寂。\n春风欲去难踪迹。\n难踪迹。\n几枝红叶，万金消得。\n青铜镜里朱阑侧。\n照人也似倾城色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8797, '朝中措', '韩元吉', '危亭崛起卧苍龙。\n绝景画图中。\n便作龙山高会，千年乐事能同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8798, '贺圣朝', '韩元吉', '斜阳只向花梢驻。\n似愁君西去。\n清歌也便做阳关，更朝来风雨。\n佳人莫道，一杯须近，总眉峰偷聚。\n明年归诏上鸾台，记别离难处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8799, '西江月', '韩元吉', '一度难逢佳节，今年两度重阳。\n菊花犹折御衣黄。\n莫惜危亭更上。\n况有飞觞滟玉，从教醉帽吹香。\n兴来相与共清狂。\n频把新词细唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8800, '西江月', '韩元吉', '山路冥冥雨暗，溪桥阵阵花飞。\n一年寂寂又春归。\n白发自惊尘世。\n不惜障泥渡水，且寻团扇题诗。\n杜鹃休绕暮烟啼。\n我欲风前重醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8801, '燕归梁', '韩元吉', '凉月圆时翠帐深。\n锁非雾沈沈。\n广寒宫里未归人。\n共结屋、住黄金。\n繁枝未老秋光澹，好风露、总关心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8802, '南柯子・南歌子', '韩元吉', '急雨朝来过，浓云晚半收。\n荷香便傍酒尊浮。\n极目澹烟斜照、满芳洲。\n消尽人间暑，翻成一段秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8803, '南柯子・南歌子', '韩元吉', '野杏抟枝熟，戎葵抱叶开。\n村村箫鼓画船回。\n客里不知时节、又相催。\n角黍堆冰碗，兵符点翠钗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8804, '浪淘沙', '韩元吉', '席地赏残红。\n少驻孤蓬。\n一春不奈风和雨。\n雨自无情风有恨，花片西东。\n云澹远峰浓。\n绿遍高桐。\n神仙知在此山中。\n万古消凝多少事，目尽晴空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8805, '浪淘沙', '韩元吉', '倦客怕离歌。\n春已无多。\n闲愁须倩酒消磨。\n风雨才晴今夜月，不醉如何。\n玉笋滟金荷。\n情在双蛾。\n二年能得几经过。\n花满碧蹊归棹远，回首烟波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8806, '浪淘沙', '韩元吉', '怨花残。\n谁道春阑。\n多情红药待君看。\n浓澹晓妆新意态，独占西园。\n风叶万枝繁。\n犹记平山。\n五云楼映玉成盘。\n二十四桥明月下，谁凭朱阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8807, '鹧鸪天', '韩元吉', '山绕江城腊又残。\n朔风垂地雪成团。\n莫将带雨梨花认，且作临风柳絮看。\n烟杳渺，路弥漫。\n千林犹待月争寒。\n凭君细酌羔儿酒，倚遍琼楼十二阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8808, '鹧鸪天', '韩元吉', '不惜黄花插满头。\n花应却为老人羞。\n年年九日常拚醉，处处登高莫浪愁。\n酬美景，驻清秋。\n绿橙香嫩酒初浮。\n多情雨後双溪水，红满斜阳自在流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8809, '鹧鸪天', '韩元吉', '老去休惊节物催。\n菊花端的为君开。\n携壶幸有齐山客，怀古还如单父台。\n松掩映，水萦回。\n使君强健得重来。\n不须细把茱萸看，且尽丰年酒一杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8810, '虞美人', '韩元吉', '西风斜日兰皋路。\n碧嶂连红树。\n天公也有惜君行。\n小雨霏霏特地、不成晴。\n满城桃李春来处。\n我老君宜住。\n莫惊华发笑相扶。\n记取他年同姓、两尚书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8811, '虞美人', '韩元吉', '登临自古骚人事。\n惨栗天涯意。\n金华峰顶做重阳。\n月地千寻风里、万枝香。\n相君携客相应记。\n几处容狂醉。\n双溪明月乱山青。\n飞梦时时犹在、最高亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8812, '虞美人', '韩元吉', '烟霄脉脉停机杼。\n双鹊飞来语。\n踏歌声转玉钩斜。\n好是满天风露、一池花。\n离多会少从来有。\n不似人间久。\n欢情谁道隔年迟。\n须信仙家日月、未多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8813, '虞美人', '韩元吉', '诏书昨夜催春到。\n绿野花争早。\n几枝先见海棠开。\n全胜陇头冲雪、寄江梅。\n破寒滴滴娇如醉。\n不比春饶睡。\n万红千紫莫嫌迟。\n看取满城花送、衮衣归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8814, '夜行船', '韩元吉', '极目高亭横远岫。\n拂新晴、黛蛾依旧。\n策马重来，秋光如画，霜满翠梧高柳。\n菊美橙香还封酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8815, '南乡子', '韩元吉', '江路木犀天。\n梨枣吹风树树悬。\n只道荔枝无驿使，依然。\n赢得骊珠万颗传。\n香露滴芳鲜。\n并蒂连枝照绮筵。\n惊走梧桐双睡鹊，应怜。\n腰底黄金作弹圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8816, '南乡子', '韩元吉', '细雨弄中秋。\n雨歇烟霄玉镜流。\n唤起佳人横玉笛，凝眸。\n收拾风光上小楼。\n烂醉拚扶头。\n明日阴晴且漫愁。\n二十四桥何处是，悠悠。\n忍对嫦娥说旧游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8817, '醉落魄・一斛珠', '韩元吉', '楼头晚鼓。\n佳人莫唱黄金缕。\n良宵镫火还三五。\n肠断扁舟，明日江南去。\n离觞欲醉谁能许。\n风前蝶闹蜂儿舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8818, '醉落魄・一斛珠', '韩元吉', '菊花又折。\n今年真是龙山客。\n杯行潋滟新醅白。\n一醉相欢，莫便话离恻。\n从教破帽频侧。\n楼头霜树明秋色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8819, '一翦梅', '韩元吉', '竹里疏枝总是梅。\n月白霜清，犹未全开。\n相逢聊与著诗催。\n要趁金波，满泛金杯。\n多病渐非作赋才。\n醉到花前，探得春回。\n明年公已在鸾台。\n看取春风，丹诏重来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8820, '临江仙', '韩元吉', '记得年时离别夜，都门强半清秋。\n今年想望只邻州。\n星连南极动，月满大江流。\n芸阁老仙多妙语，云阶清梦曾游。\n屐声还认庾公楼。\n金波摇酒面，河影堕帘钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8821, '临江仙', '韩元吉', '自古文章贤太守，江南只数苏州。\n而今太守更风流。\n熏香开画阁，迎月上西楼。\n见说宫妆高髻拥，司空却是遨头。\n五湖莫便具扁舟。\n玉堂红蕊在，还胜百花洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8822, '江神子・江城子', '韩元吉', '十年此地看花时。\n醉题诗。\n夜弹棋。\n湖海相逢，曾共惜芳菲。\n前度刘郎今度客，嗟老矣，鬓成丝。\n江梅吹尽柳桥西。\n雪纷飞。\n画船移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8823, '江神子・江城子', '韩元吉', '金银楼阁认蓬莱。\n晓烟开。\n上崔嵬。\n风引孤帆，谁道却船回。\n鹏翼倚天鳌背稳，惊浪起，雪成堆。\n翩翩黄鹤为谁来。\n醉持杯。\n共徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8824, '满江红', '韩元吉', '梅欲开时，君欲去、花谁同折。\n应怅望、江津千树，晚烟明雪。\n花似故人相见好，人如塞雁多离别。\n待留君、重看水边花，花边月。\n台城路，山如阙。\n追往事，伤时节。\n但春风春雨，古人愁绝。\n多少扬州诗兴在，直须清梦翻胡蝶。\n问他年、谁记饮中仙，花应说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8825, '满江红', '韩元吉', '寂寞山城，春已半、好花都折。\n无奈向、阴晴不定，冷烟寒食。\n莫问花残风又雨，且须烂醉酬春色。\n叹使君、华发又重来，人应识。\n丹井畔，山桥侧。\n空翠里，烟如织。\n便直教马上，醉巾沾湿。\n丞相车茵端未惜，孟公好客聊无客。\n算明年、溪路海棠开，还应忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8826, '满江红', '韩元吉', '江绕层城，重楼迥、依然山色。\n□□有、佳人犹记，旧家离别。\n把酒只如当日醉，挥毫剩欠尊前客。\n算平林、有恨寄伤心，烟如织。\n湖平树，花连陌。\n风景是，光阴易。\n叹新声浑在，断云难觅。\n暮雨不成巫峡梦，数峰还认湘波瑟。\n但与君、同看小槽红，真珠滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8827, '水调歌头', '韩元吉', '世事不须问，我老但宜仙。\n南溪一曲，独对苍翠与孱颜。\n月白风清长夏。\n醉里相逢林下。\n欲辩已忘言。\n无客问生死，有竹报平安。\n少年期，功名事，觅燕然。\n如今憔悴，萧萧华发抱尘编。\n万里蓬莱归路。\n一醉瑶台风露。\n因酒得天全。\n笑指云阶梦，今夕是何年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8828, '水调歌头', '韩元吉', '江路晓来雨，残暑夜全消。\n人言天上今夕，飞鹊渐成桥。\n杳杳云车何处。\n脉脉红蕖香度。\n瓜果趁良宵。\n推枕断虹卷，抚槛白鱼跳。\n无湖客，临风露，倚兰苕。\n云涛四起，极目人世有烟霄。\n我送君舟西渡。\n君望我帆南浦。\n明日恨迢迢。\n且醉吴淞月，重听浙江潮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8829, '水调歌头', '韩元吉', '明月照多景，一话九经年。\n故人何在，依约蜀道倚青天。\n豪气如今谁在。\n剩对岷峨山水。\n落纸起云烟。\n应有阳台女，来寿隐中仙。\n相如赋，王褒颂，子云玄。\n兰台麟阁，早晚飞诏下甘泉。\n梦绕神州归路。\n却趁鸡鸣起舞。\n馀事勒燕然。\n白首待君老，同泛五湖船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8830, '水调歌头', '韩元吉', '潋潋桂华满，摇落楚江秋。\n去年今夜，相望千里一扁舟。\n满目都门风露。\n离别凄凉几度。\n霜雪渐盈头。\n山水最佳处，常恨不同游。\n少年约，谈笑事，取封侯。\n田园归晚，休问适不用吾谋。\n身外功名何处。\n屈指如今老去。\n无梦到金瓯。\n剩买五湖月，吹笛下沧洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8831, '水调歌头', '韩元吉', '今日俄重九，莫负菊花开。\n试寻高处，携手蹑屐上崔嵬。\n放目苍岩千仞。\n云护晓霜成阵。\n知我与君来。\n古寺倚修竹，飞槛绝纤埃。\n笑谈间，风满座，酒盈杯。\n仙人跨海，休问随处是蓬莱。\n落日平原西望。\n鼓角秋深悲壮。\n戏马但荒台。\n细把茱萸看，一醉且徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8832, '水调歌头', '韩元吉', '泽国又秋晚，天际有飞鸿。\n中原何在，极目千里暮云重。\n今古长干桥下，遗恨都随流水，西去几时东。\n斜日动歌管，萸菊舞西风。\n江南岸，淮南渡，草连空。\n石城潮落，寂寞烟树锁离宫。\n且斗尊前酒美，莫问楼头佳丽，往事有无中。\n却笑东山老，拥鼻与谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8833, '水调歌头', '韩元吉', '落日澹芳草，烟际一鸥浮。\n西湖好处，君去千里为谁留。\n坐想敬亭山下，竹映一溪寒水，飞盖共追游。\n况有尊前客，相对两诗流。\n笑谈间，风满座，气横秋。\n平生壮志，长啸起舞看吴钩。\n红白山花开谢，半醉半醒时节，春去子规愁。\n梦绕水西寺，回首谢公楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8834, '醉蓬莱', '韩元吉', '听清歌初转，翠岭云横，乍飞还驻。\n水落秋明，正千岩呈露。\n况有宾朋，飘然才调，尽凌空鹭。\n步绕西畴，同寻南涧，郊原新雨。\n好客声名，郑庄风韵，松菊栽成，故侯瓜圃。\n燕去鸿来，笑人生离聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8835, '念奴娇', '韩元吉', '去年秋半，正都门结束，相将离别。\n潋潋双溪新雁过，重见当时明月。\n步转高楼，凄凉看镜，绿鬓纷成雪。\n晚晴烟树，傍人飞下洪叶。\n还记江浦潮生，云涛天际，涌金波一色。\n千里相望浑似梦，极目空山围碧。\n醉拍朱阑，满簪丹桂，细与娥说。\n倚风孤啸，恍然身在瑶阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8836, '念奴娇', '韩元吉', '定交最早，叹西津几度，匆匆论别。\n世事浮云山万变，只有沧江横月。\n长忆追随，湖山好处，醉帽风雪。\n竹阴花径，兴来题尽桐叶。\n谁忆此地相逢，鬓毛君未白，眉添黄色。\n屈指烟霄归诏近，路入龙楼金碧。\n千载功名，一尊欢笑，会作他年说。\n倚天长剑，夜寒光透银阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8837, '念奴娇', '韩元吉', '湖山泥影，弄晴丝、目送天涯鸿鹄。\n春水移船花似雾，醉里题诗刻烛。\n离别经年，相逢犹健，底恨光阴速。\n壮怀浑在，浩然起舞相属。\n长记入洛声名，风流觞咏，有兰亭修竹。\n绝唱人间知不知，零落金貂谁续。\n北固烟锺，西州雪岸，且共杯中绿。\n紫台青琐，看君归上群玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8838, '念奴娇', '韩元吉', '春来离思，正楼台灯火、香凝金戟。\n扬子江头嘶骑拥，杨柳花飞留客。\n枚乘声名，谪仙风韵，更赋长相忆。\n酒阑相顾，起看月堕寒壁。\n尊前谁唱新词，平林真有恨、寒烟如织。\n燕雁横空梅蕊乱，醉里隔江闻笛。\n白发逢春，湖山好在，一笑千金直。\n待君归诏，买船重话畴昔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8839, '水龙吟', '韩元吉', '乱山深处逢春，断魂更入桃源路。\n双双翠羽，溅溅流水，香雾。\n花里莺啼，水边人去，落红无数。\n恨刘郎鬓点，星星华发，空回首、伤春暮。\n寂寞云间洞户。\n问当年、佳期何处。\n虹桥望断，琼楼深锁，如今谁住。\n绿满千岩，浣衣石上，倚风凝伫。\n料多情好在，也应笑我，却匆匆去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8840, '水龙吟', '韩元吉', '五溪深锁烟霞，定知不是人间世。\n轩然九老，排云一笑，苍颜相对。\n星斗垂空，月华随步，酒醒无寐。\n□广寒已近，嫦娥起舞，天风动、摇丹桂。\n极目层霄如洗。\n正千岩、棱棱霜气。\n飞泉半落，苍崖百仞，珠翻玉碎。\n金衲松成，葛洪丹就，如今千载。\n叹谪仙诗在，骑驴未远，且留君醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8841, '瑞鹤仙', '韩元吉', '西风吹暮雨。\n正碧树凉生，送君南浦。\n蝉声带残暑。\n满高林斜照，暝烟横渚。\n故乡路阻。\n更秋入、江城雁渡。\n怅天涯、几许闲愁，对酒共成羁旅。\n休问功名何在，绿鬓吴霜，素衣尘土。\n离觞缓举。\n收玉箸，听金缕。\n叹凌云才调，乌丝阑上，省把清诗漫与。\n见洛阳、年少交游，倩君寄语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8842, '薄幸', '韩元吉', '送君南浦。\n对烟柳、青青万缕。\n更满眼、残红吹尽，叶底黄鹂自语。\n甚动人、多少离情，楼头水阔山无数。\n记竹里题诗，花边载酒，魂断江干春暮。\n都莫问、功名事，白发渐、星星如许。\n任鸡鸣起舞，乡关何在，凭高目尽孤鸿去。\n漫留君住。\n趁酴香暖，持杯且醉瑶台露。\n相思记取，愁绝西窗夜雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8843, '临江仙', '韩元吉', '不恨绿阴桃李过，酴正向人开。\n一尊清夜月徘徊。\n花如人意好，月为此花来。\n未信人间香有许，却疑同住瑶台。\n纷纷残雪堕深杯。\n直教攀折尽，犹胜酒醒回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8844, '南柯子・南歌子', '韩元吉', '五月炎州路，千重扑地开。\n只疑标韵是江梅。\n不道薰风庭院、雪成堆。\n宝髻琼瑶缀，仙衣翡翠裁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8845, '醉落魄・一斛珠', '韩元吉', '霓裳弄月。\n冰肌不受人间热。\n分明密露枝枝结。\n碧树珊瑚，容易与君折。\n玉环旧事谁能说。\n迢迢驿路香风彻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8846, '水龙吟', '韩元吉', '雨馀叠浮空，望中秀色仙都是。\n洞天未锁，人间春老，玉妃曾坠。\n锦瑟繁弦，凤箫清响，九霄歌吹。\n问分香旧事，刘郎去後，知谁伴、风前醉。\n回首暝烟千里。\n但纷纷、落红如泪。\n多情易老，青鸾何许，诗成谁寄。\n斗转参横，半帘花影，一溪寒水。\n怅飞凫路杳，行云梦断，有三峰翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8847, '好事近', '韩元吉', '凝碧旧池头，一听管弦凄切。\n多少梨园声在，总不堪华发。\n杏花无处避春愁，也傍野烟发。\n惟有御沟声断，似知人呜咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8848, '永遇乐', '韩元吉', '池馆春归，帘栊昼静，清漏移箭。\n山下孤城，水边翠竹，声千转。\n记得年时，绮窗人去，尚有唾茸遗线。\n照珠筵、歌檀舞扇，寂寞旧家排遍。\n青云赋客，多情多病，西掖桐阴满院。\n飞絮随风，马头月在，翡翠帷空卷。\n平湖烟远，斜桥雨暗，欲寄短书双燕。\n算犹忆、兰房画烛，醉时共翦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8849, '六州歌头', '韩元吉', '东风著意。\n先上小桃枝。\n红粉腻。\n娇如醉。\n倚朱扉。\n记年时。\n隐映新妆，面临水岸。\n春将半。\n云日暖。\n斜桥转。\n夹城西。\n草软莎平跋马，垂杨渡、玉勒争嘶。\n认蛾眉凝笑，脸薄拂燕支。\n绣户曾窥。\n恨依依。\n共携手处。\n香如雾。\n红随步。\n怨春迟。\n消瘦损。\n凭谁问。\n只花知。\n泪空垂。\n旧日堂前燕，和烟雨，又双飞。\n人自老。\n春长好。\n梦佳期。\n前度刘郎，几许风流地，花也应悲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8850, '水龙吟', '韩元吉', '南风五月江波，使君莫袖平戎手。\n燕然未勒，渡沪声在，宸衷怀旧。\n卧占湖山，楼横百尺，诗成千首。\n正菖蒲叶老，芙蕖香嫩，高门瑞、人知否。\n凉夜光躔牛斗。\n梦初回、长庚如昼。\n明年看取，锋旗南下，六骡西走。\n功画凌烟，万钉宝带，百壶清酒。\n便留公剩馥，蟠桃分我，作归来寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8851, '蓦山溪', '韩元吉', '双龙古洞，领略千岩秀。\n福地有真仙，来一试、调元□手。\n青春绿野，月转最高峰，星斗润，柳海新，五夜收灯後。\n诏飞天上，人倚经纶旧。\n重入辅升平，更赢得、千龄眉寿。\n功成未晚，归伴赤松游，金印重，羽衣轻，会见丹砂就。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8852, '鹊桥仙', '韩元吉', '菊花黄後。\n山茶红透。\n南国小春时候。\n蓬山高处绿云间，有一个、仙宫诞秀。\n精神龟媚，骨毛鹤瘦。\n落落人中星斗。\n殷勤自折早梅芳，调一鼎、和羹为寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8853, '朝中措', '韩元吉', '清霜著柳夜来寒。\n新月印湖山。\n共喜今年称寿，一尊还在长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8854, '南乡子', '韩元吉', '新笋旋成林。\n梅子枝头雨更深。\n织就彩丝犹十日，登临。\n人似江心百炼金。\n功业会相寻。\n好挹薰风和舜琴。\n鹤住千年丹九转，如今。\n门外梧桐长翠阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8855, '鹧鸪天', '韩元吉', '甲子今年甫一周。\n人间聊住八千秋。\n依依梅蕊看如雪，恰恰蟾华未上钩。\n分玉节，共南州。\n台城辇路记重游。\n相期一品归来健，兄弟华颠自献酬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8856, '瑞鹤仙', '韩元吉', '好山横翠幕。\n更一水流烟，嫩阴成幄。\n薰风转林薄。\n笑劳生底事，漫嗟离索。\n霞觞细酌。\n尽流年、青镜易觉。\n算芙蓉、玉井香翻，不减旧阶红药。\n寂寞。\n早玄空老，问字人稀，也胜投阁。\n骑鲸後约。\n追汗漫，记寥廓。\n便风帆高挂，云涛千里，谁道蓬壶水弱。\n任蟠桃、满路千花，自开自落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8857, '醉落魄・一斛珠', '韩元吉', '红蕖漾月。\n薰风特地生梧叶。\n一年风月今宵别。\n隐隐笙鸾，何处有炎热。\n凤凰山下榴花发。\n一杯香露融春雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8858, '醉落魄・一斛珠', '韩元吉', '相看半百。\n劳生等是乾坤客。\n功成一笑惊头白。\n惟有榴花，相对似颜色。\n蓬莱水浅何曾隔。\n也应待得蟠桃摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8859, '酹江月・念奴娇', '黄宰', '三光五岳，孕乾坤英彩，非金非玉。\n赫赫岩岩真相种，来驾横空仙鹄。\n十万儿童，和丰堂下，齐指梅山祝。\n黑头难老，岁寒苍桧修竹。\n须信自家有传，中庸一卷，是长生真。\n借问洛阳归去後，几度桃开桃熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8860, '忆秦娥', '朱淑真', '弯弯曲。\n新年新月钩寒玉。\n钩寒玉。\n凤鞋儿小，翠眉儿蹙。\n闹蛾雪柳添妆束。\n烛龙火树争驰逐。\n争驰逐。\n元宵三五，不如初六。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8861, '浣溪纱・浣溪沙', '朱淑真', '春巷夭桃吐绛英。\n春衣初试薄罗轻。\n风和烟暖燕巢成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8862, '生查子', '朱淑真', '寒食不多时，几日东风恶。\n无绪倦寻芳，闲却秋千索。\n玉减翠裙交，病怯罗衣薄。\n不忍卷帘看，寂寞梨花落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8863, '生查子', '朱淑真', '年年玉镜台，梅蕊宫妆困。\n今岁未还家，怕见江南信。\n酒从别後疏，泪向愁中尽。\n遥想楚云深，人远天涯近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8864, '谒金门', '朱淑真', '春已半。\n触目此情无限。\n十二阑干闲倚遍。\n愁来天不管。\n好是风和日暖。\n输与莺莺燕燕。\n满院落花帘不卷。\n断肠芳草远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8865, '江城子', '朱淑真', '斜风细雨作春寒。\n对尊前。\n忆前欢。\n曾把梨花，寂寞泪阑干。\n芳草断烟南浦路，和别泪，看青山。\n昨宵结得梦夤缘。\n水云间。\n悄无言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8866, '减字木兰花', '朱淑真', '独行独坐。\n独倡独酬还独卧。\n伫立伤神。\n无奈轻寒著摸人。\n此情谁见。\n泪洗残妆无一半。\n愁病相仍。\n剔尽寒灯梦不成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8867, '眼儿媚', '朱淑真', '迟迟春日弄轻柔。\n花径暗香流。\n清明过了，不堪回首，云锁朱楼。\n午窗睡起莺声巧，何处唤春愁。\n绿杨影里，海棠亭畔，红杏梢头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8868, '鹧鸪天', '朱淑真', '独倚阑干昼日长。\n纷纷蜂蝶斗轻狂。\n一天飞絮东风恶，满路桃花春水香。\n当此际，意偏长。\n萋萋芳草傍池塘。\n千锺尚欲偕春醉，幸有荼蘼与海棠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8869, '清平乐', '朱淑真', '风光紧急。\n三月俄三十。\n拟欲留连计无及。\n绿野烟愁露泣。\n倩谁寄语春宵。\n城头画鼓轻敲。\n缱绻临歧嘱付，来年早到梅梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8870, '点绛唇', '朱淑真', '黄鸟嘤嘤，晓来却听丁丁木。\n芳心已逐。\n泪眼倾珠斛。\n见自无心，更调离情曲。\n鸳帏独。\n望休穷目。\n回首溪山绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8871, '蝶恋花', '朱淑真', '楼外垂杨千万缕。\n欲系青春，少住春还去。\n独自风前飘柳絮。\n随春且看归何处。\n绿满山川闻杜宇。\n便做无情，莫也愁人苦。\n把酒送春春不语。\n黄昏却下潇潇雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8872, '清平乐', '朱淑真', '恼烟撩露。\n留我须臾住。\n携手藕花湖上路。\n一霎黄梅细雨。\n娇痴不怕人猜。\n随群暂遣愁怀。\n最是分携时候，归来懒傍妆台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8873, '菩萨蛮', '朱淑真', '秋声乍起梧桐落。\n蛩吟唧唧添萧索。\n枕背灯眠。\n月和残梦圆。\n起来钩翠箔。\n何处寒砧作。\n独倚小阑干。\n逼人风露寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8874, '菩萨蛮', '朱淑真', '山亭水榭秋方半。\n凤帏寂寞无人伴。\n愁闷一番新。\n双蛾只旧颦。\n起来临绣户。\n时有疏萤度。\n多谢月相怜。\n今宵不忍圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8875, '鹊桥仙', '朱淑真', '巧云妆晚，西风罢暑，小雨翻空月坠。\n牵牛织女几经秋，尚多少、离肠恨泪。\n微凉入袂，幽欢生座，天上人间满意。\n如何暮暮与朝朝，更改却、年年岁岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8876, '菩萨蛮', '朱淑真', '也无梅柳新标格。\n也无桃李妖娆色。\n一味恼人香。\n群花争敢当。\n情知天上种。\n飘落深岩洞。\n不管月宫寒。\n将枝比并看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8877, '点绛唇', '朱淑真', '风劲云浓，暮寒无奈侵罗幕。\n髻鬟斜掠。\n呵手梅妆薄。\n少饮清欢，银烛花频落。\n恁萧索。\n青工已觉。\n点破香梅萼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8878, '念奴娇', '朱淑真', '冬晴无雪。\n是天心未肯，化工非拙。\n不放玉花飞堕地，留在广寒宫阙。\n云欲同时，霰将集处，红日三竿揭。\n六花翦就，不知何处施设。\n应念陇首寒梅，花开无伴，对景真愁绝。\n待出和羹金鼎手，为把玉盐飘撒。\n沟壑皆平，乾坤如画，更吐冰轮洁。\n梁园燕客，夜明不怕灯灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8879, '念奴娇', '朱淑真', '鹅毛细翦，是琼珠密洒，一时堆积。\n斜倚东风浑漫漫，顷刻也须盈尺。\n玉作楼台，铅熔天地，不见遥岑碧。\n佳人作戏，碎揉些子抛掷。\n争奈好景难留，风雨，打碎光凝色。\n总有十分轻妙态，谁似旧时怜惜。\n担阁梁吟，寂寥楚舞，笑捏狮儿只。\n梅花依旧，岁寒松竹三益。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8880, '卜算子', '朱淑真', '竹里一枝斜，映带林逾静。\n雨後清奇画不成，浅水横疏影。\n吹彻小单于，心事思重省。\n拂拂风前度暗香，月色侵花冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8881, '菩萨蛮', '朱淑真', '湿云不渡溪桥冷。\n娥寒初破东风影。\n溪下水声长。\n一枝和月香。\n人怜花似旧，花不知人瘦。\n独自倚阑干，夜深花正寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8882, '失调名', '朱淑真', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8883, '西江月', '朱淑真', '办取舞裙歌扇，赏春只怕春寒。\n卷帘无语对南山。\n已觉绿肥红浅。\n去去惜花心懒，踏青闲步江干。\n恰如飞鸟倦知还。\n澹荡梨花深院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8884, '月华清', '朱淑真', '雪压庭春，香浮花月，揽衣还怯单薄。\n枕裴回，又听一声乾鹊。\n粉泪共、宿雨阑干，清梦与、寒云寂寞。\n除却。\n是江梅曾许，诗人吟作。\n长恨晓风漂泊。\n且莫遣香肌，瘦减如削。\n深杏夭桃，端的为谁零落。\n况天气、妆点清明，对美景、不妨行乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8885, '柳梢青', '张抡', '柳色初匀。\n轻寒似水，纤雨如尘。\n一阵东风，绞微皱，碧沼鳞鳞。\n仙娥花月精神。\n奏凤管、鸾丝斗新。\n万岁声中，九霞杯里，长醉芳春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8886, '蝶恋花', '张抡', '前日海棠犹未破。\n点点胭脂，染就真珠颗。\n今日重来花下坐。\n乱铺宫锦春无那。\n剩摘繁枝簪几朵。\n痛惜深怜，只恐芳菲过。\n醉倒何妨花底卧。\n不须红袖来扶我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8887, '临江仙', '张抡', '玉宇凉生清禁晓，丹葩色照晴空。\n珊瑚敲碎小玲珑。\n人间无此种，来自广寒宫。\n雕玉阑干深院静，嫣然凝笑西风。\n曲屏须占一枝红。\n且图醉枕，香到梦魂中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8888, '临江仙', '张抡', '闻道彤庭森宝仗，霜风逐雨驱云。\n六龙扶辇下青冥。\n香随鸾扇远，日射赭袍明。\n帘卷天街人隘路，满城喜望清尘。\n欢声催起岭梅春。\n欲知天意好，昨夜月华新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8889, '西江月', '张抡', '翦就碧云闹叶，刻成紫玉芳心。\n浅春不怕峭寒侵。\n暧彻薰笼瑞锦。\n花里清芬独步，尊前胜韵难禁。\n飞香直到玉杯深。\n消得厌厌痛饮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8890, '朝中措', '张抡', '灯花挑尽夜将阑。\n斜掩小屏山。\n一点凉蟾窥慢，钏敲玉臂生寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8891, '烛影摇红', '张抡', '双阙中天，凤楼十二春寒浅。\n去年元夜奉宸游，曾侍瑶池宴。\n玉殿珠帘尽卷。\n拥群仙、蓬壶阆苑。\n五云深处，万烛光中，揭天丝管。\n驰隙流年，恍如一瞬星霜换。\n今宵谁念泣孤臣，回首长安远。\n可是尘缘未断。\n谩惆怅、华胥梦短。\n满怀幽恨，数点寒灯，几声归雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8892, '浣溪沙', '张抡', '筑室峥嵘占宝峰。\n退朝燕坐万缘空，出尘高志抗冥鸿。\n何日嘉招陪一笑，看君豪饮千锺。\n试凭鄙句作先容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8893, '霜天晓角', '张抡', '晓风摇幕。\n枕闻残角。\n霜月可窗寒影，金猊冷、翠衾薄。\n旧恨无处著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8894, '点绛唇', '张抡', '何处春来，惠风初自东郊至。\n柳条花蕊。\n迤逦争明媚。\n造化难穷，谁晓幽微理。\n都来是。\n自然天地。\n一点冲和气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8895, '点绛唇', '张抡', '昨夜东风，又还吹遍闲花草。\n翠轻红小。\n触处惊春早。\n草舍茅□，□□□□□。\n谁□□。\n□□丹灶。\n别有阳和□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8896, '点绛唇', '张抡', '阳气初生，万花潜动根暖。\n暗藏芳艳。\n未许东君见。\n恰似温温，铅鼎丹初转。\n功犹浅。\n九回烹炼。\n日月光华满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8897, '点绛唇', '张抡', '暖日迟迟，乱莺声在垂杨里。\n昼眠惊起。\n花影间铺地。\n试问荣名，何似花前醉。\n陶陶地。\n任他门外。\n车驾喧朝市。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8898, '点绛唇', '张抡', '花满名园，万红千翠交相映。\n画阑幽径。\n行乐迷芳景。\n惟有幽人，不与浮华竞。\n便幽静。\n兴来独饮。\n花下风吹醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8899, '点绛唇', '张抡', '春入山家，杖藜独步登严岫。\n野花争秀。\n弄蕊香盈袖。\n对景开怀，莫遣双眉皱。\n春难久。\n乱红飞後。\n留得韶光否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8900, '点绛唇', '张抡', '气体冲融，四时长在阳春里。\n玉田琼蕊。\n养就灵苗异。\n堪笑□□，□□□□□。\n□□□。\n□□流水。\n半落苍□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8901, '点绛唇', '张抡', '乐事难并，少年常恨春宵短。\n万花丛畔。\n只恐金杯浅。\n方喜春来，又叹韶华晚。\n频相劝。\n且闻强健。\n莫厌花经眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8902, '点绛唇', '张抡', '一瞬光阴，世人常被芳菲恼。\n玉壶频倒。\n惟恨春归早。\n何似逍遥，物外寻三岛。\n春长好。\n瑞芝瑶草。\n春又何曾老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8903, '点绛唇', '张抡', '浮世如何，问花何事花无语。\n夜来风雨。\n已送韶华暮。\n念此堪惊，得失休思虑。\n从今去。\n醉乡深处。\n莫管流年度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8904, '阮郎归', '张抡', '亭亭槐柳午阴圆。\n薰风拂舜弦。\n一轮红日贴中天。\n乾坤如火然。\n观上象，想丹田。\n阳精色正鲜。\n□从炼得体纯全。\n朱颜无岁年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8905, '阮郎归', '张抡', '欲如臭腐化神奇。\n当观蝉蜕时。\n脱然飞上绿槐枝。\n炎炎昼景□。\n□□□，□如斯。\n□□□□迷。\n灵躯一旦脱□□。\n□□□□归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8906, '阮郎归', '张抡', '深亭邃馆锁清风。\n榴花芳艳浓。\n阳光染就欲烧空。\n谁能窥化工。\n观物外，喻身中。\n灵砂别有功。\n若将一粒比花容。\n金丹色又红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8907, '阮郎归', '张抡', '炎天何处可登临。\n须於物外寻。\n松风涧水杂清音。\n空山如弄琴。\n宜散发，称披襟。\n都无烦暑侵。\n莫将城市比山林。\n山林兴味深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8908, '阮郎归', '张抡', '豪家大厦敞千楹。\n风摇玉柄轻。\n金盆弄水复敲冰。\n热从何处生。\n低草舍，小茅亭。\n如何安此身。\n元来一念静无尘。\n萧然心自清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8909, '阮郎归', '张抡', '金乌玉兔最无情。\n驱驰不暂停。\n春光才去又朱明。\n年华只暗惊。\n须省悟，莫劳神。\n朱颜不再新。\n灭除妄想养天真。\n管无寒暑侵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8910, '阮郎归', '张抡', '动时思静暑思寒。\n尘劳扰扰间。\n翻云复雨百千般。\n几时心地闲。\n□□□，□□难。\n将□□□然。\n自然寒暑不相□。\n□□□地仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8911, '阮郎归', '张抡', '谁言无处避炎光。\n山中有草堂。\n安然一枕即仙乡。\n竹风穿户凉。\n名不恋，利都忘。\n心闲日自长。\n不须辛苦觅琼浆。\n华池神水香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8912, '阮郎归', '张抡', '炎炎日正当中。\n澄潭忽此逢。\n金丹乍浴表深功。\n通明照水红。\n丹浴罢，乐无穷。\n怡然百体融。\n人间何处不清风。\n此怀谁与同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8913, '阮郎归', '张抡', '寒来暑往几时休。\n光阴逐水流。\n浮云身世两悠悠。\n何劳身外求。\n天上月，水边楼。\n须将一醉酬。\n陶然无喜亦无忧。\n人生且自由。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8914, '醉落魄・一斛珠', '张抡', '流光转毂。\n乌飞兔走争相逐。\n火云方见奇峰簇。\n飒飒西风，惊堕井梧绿。\n隙驹莫叹年华速。\n新凉且喜消炎酷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8915, '醉落魄・一斛珠', '张抡', '红芳紫陌。\n韶华□□□□□。\n□花弄□□□色。\n不比西风，吹落□□□。\n乾坤造化□□□。\n都缘一气潜相易。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8916, '醉落魄・一斛珠', '张抡', '清秋夜寂。\n圆蟾素影流空碧。\n都无一点浮云隔。\n河汉光微，星斗淡无色。\n日精欲炼须阴魄。\n更深犹望清宵立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8917, '醉落魄・一斛珠', '张抡', '秋高气肃。\n西风又拂盈盈菊。\n金弄玉香芬馥。\n桃李虽繁，其奈太粗俗。\n渊明雅兴谁能续。\n东篱千古遗高躅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8918, '醉落魄・一斛珠', '张抡', '流年迅速。\n君看败叶初辞木。\n若非寿有金丹续。\n石火光中，难保鬓长绿。\n区区何用争荣辱。\n百年一梦黄梁熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8919, '醉落魄・一斛珠', '张抡', '秋光莹彻。\n园林□□□□□。\n如何宋玉□□切。\n作赋悲凉，草木□□□。\n□人自与□□□。\n长歌清啸无时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8920, '醉落魄・一斛珠', '张抡', '虚窗透月。\n寒莎败壁蛩吟切。\n沈沈永漏灯明灭。\n只为愁人，不为道人设。\n愁人对此成愁绝。\n道人终是心如铁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8921, '醉落魄・一斛珠', '张抡', '光辉皎洁。\n古今但赏中秋月。\n寻思岂是月华别。\n都为人间，天上气清彻。\n广寒想望峨琼阙。\n玉杵声奇绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8922, '醉落魄・一斛珠', '张抡', '湖光湛碧。\n亭亭照水芙蕖拆。\n绿罗盖底争红白。\n恍若凌波，仙子步罗袜。\n如今霜落枯荷折。\n清香无处重寻觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8923, '醉落魄・一斛珠', '张抡', '秋宵露结。\n清晨□□□□□。\n□□润□□□冽。\n名体才分，功用□□□。\n□儿本是□□□。\n养成方见仙凡隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8924, '西江月', '张抡', '有限光阴过隙，无情日月飞梭。\n春花秋月暗消磨。\n一岁相看又过。\n逢酒须成痛饮，临风莫厌高歌。\n虚名微利两如何。\n识破方知恁麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8925, '西江月', '张抡', '雪似琼花铺地，月如宝鉴当空。\n光辉上下两相通。\n千古谁窥妙用。\n若悟珠生蚌腹，方知非异非同。\n阴阳相感有无中。\n恍惚已萌真种。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8926, '西江月', '张抡', '卷地朔风凛凛，漫天瑞雪霏霏。\n园林万木变枯枝。\n因甚松篁独翠。\n只为春花竞发，却教秋叶争飞。\n若无荣盛便无衰。\n悟此方名达理。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8927, '西江月', '张抡', '密布同云万里，六飞玉糁琼铺。\n清歌妙舞拥红炉。\n犹恨寒侵尊俎。\n谁念山林路险，独行跣足樵夫。\n莫惊苦乐□殊途。\n阳□皆由阴注。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8928, '西江月', '张抡', '雅士常多雅□，□□□□□怀。\n雪溪□□□舟来。\n兴尽何须见戴。\n恰似□云出岫，岂拘宇内形骸。\n超然物外远尘埃。\n到此方为自在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8929, '西江月', '张抡', '冬至一阳初动，鼎炉光满帘帏。\n五行造化太幽微。\n颠倒难穷妙理。\n遇此急须进火，速修犹恐迟迟。\n茫茫何处问天机。\n要悟须凭师指。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8930, '西江月', '张抡', '一梦浮生未觉，三冬短晷堪惊。\n天高谁解挽长绳。\n系住流年光景。\n须信阴阳有定，非关岁月无情。\n若教心地湛然清。\n日在壶中自永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8931, '西江月', '张抡', '四序常如转毂，百年须待春风。\n江梅何事向严冬。\n早有清香浮动。\n只为六阴极处，一阳已肇黄宫。\n阴阳迭用事何穷。\n此是乾坤妙用。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8932, '西江月', '张抡', '独坐闲观瑞雪，方知造化无偏。\n不论林木与山川。\n白玉一时装遍。\n梁苑休寻赋客，山阴莫上溪船。\n三杯醉□意陶然。\n梦後瑶台阆苑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8933, '西江月', '张抡', '仙道於人不□，□□□□□□。\n坎离□□□无穷。\n不信浮生若梦。\n君看□□窨雪，寻常见消熔。\n能令新旧再相逢。\n此是如何作用。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8934, '踏莎行', '张抡', '朝锁烟霏，暮凝空翠。\n千峰迥立层霄外。\n阴睛变化百千般，丹青难写天然态。\n人住山中，年华频改。\n山花落尽山长在。\n浮生一梦几多时，有谁得似青山耐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8935, '踏莎行', '张抡', '一道飞泉，来从何许。\n空山积翠无人处。\n潺时和七弦琴，溟忽散千岩雨。\n不问春秋，何拘今古。\n清音一听忘千虑。\n缨尘濯尽百神间，飘然襟袖思轻举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8936, '踏莎行', '张抡', '一片闲云，山头初起。\n飘然直上虚空里。\n残虹收雨耸奇峰，春晴鹤舞丹霄外。\n出岫无心，为霖何意。\n都缘行止难拘系。\n幽人心已与云闲，逍遥自在谁能累。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8937, '踏莎行', '张抡', '人远山深，草□□□。\n□□□□天真性。\n□□□长在山中，肯□□□□□□。\n□似幽□，□□心尽。\n超然心□□□隐。\n□□□水作生涯，百年甘守空山静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8938, '踏莎行', '张抡', '堪笑山中，春来风景。\n一声啼鸟烟林静。\n山泉风暖奏笙簧。\n山花雨过开云锦。\n短棹桃溪，瘦藤兰径。\n独来独往乘幽兴。\n韶光回首即成空，及时乐取逍遥性。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8939, '踏莎行', '张抡', '人问山中，因何无暑。\n山堂恰在山深处。\n藤阴满地走龙蛇，泉声万壑鸣风雨。\n且弄青松，休挥白羽。\n相逢况有烟霞侣。\n长天一任火云飞，夜凉踏月相将去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8940, '踏莎行', '张抡', '秋入云山，物情潇洒。\n百般景物堪图画。\n丹枫万叶碧云边，黄花千点幽岩下。\n已喜佳辰，更怜清夜。\n一轮明月林梢挂。\n松醪常与野人期，忘形共说清闲话。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8941, '踏莎行', '张抡', '雪拥群峰，静□□□。\n□□□□□居□。\n□□破壳栗黄香，柴□□□□□□。\n□□□□，□和衣倒。\n寂寥气□□君好。\n□□□贵足人争，山中恬淡能长保。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8942, '踏莎行', '张抡', '割断凡缘，心安神定。\n山中采药修身命。\n青松林下茯苓多，白云深处黄精盛。\n百味甘香，一身清净。\n吾生可保长无病。\n八珍五鼎不须贪，荤膻浊乱人情性。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8943, '踏莎行', '张抡', '身世浮沤，利名缰锁。\n省来万事都齐可。\n寻花时傍碧溪行，看云独倚青松坐。\n云片飞飞，花枝朵朵。\n光阴且向闲中过。\n世间萧散更何人，除非明月清风我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8944, '朝中措', '张抡', '吴松江影漾清辉。\n山远翠光微。\n杨柳风轻日永，桃花浪暖鱼肥。\n东来西往。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8945, '朝中措', '张抡', '湖光染翠□□□。\n□□□□□。\n□爱江湖光景，不曾别做□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8946, '朝中措', '张抡', '碧波深处锦鳞游。\n波面小渔舟。\n不为来贪香饵，如何赚得吞钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8947, '朝中措', '张抡', '沙明波净小汀洲。\n枫落洞庭秋。\n红蓼白苹深处，晚风吹转船头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8948, '朝中措', '张抡', '松江西畔水连空。\n霜叶舞丹枫。\n谩道金章清贵，何如蓑笠从容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8949, '朝中措', '张抡', '鸣榔惊起鹭鸶飞。\n山远水弥弥。\n米贱茅柴酒美，霜清螃蟹螯肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8950, '朝中措', '张抡', '午阴多处□□□。\n杨柳□□□。\n翠羽无情飞去，红蕖有意□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8951, '朝中措', '张抡', '红尘光景事如何。\n扰扰利名多。\n若问侬家活计，扁舟小笠轻蓑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8952, '朝中措', '张抡', '萧萧芦叶暮寒生。\n雪厌冻云平。\n密洒一篷烟火，惊鸿飞起沙汀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8953, '朝中措', '张抡', '慕名人似蚁贪膻。\n扰扰几时闲。\n输我吴松江上，一帆点破晴烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8954, '菩萨蛮', '张抡', '人间何处难忘酒。\n迟迟暖日群花秀。\n红紫斗芳菲。\n满园张锦机。\n春光能几许。\n多少闲风雨。\n一盏此时疏。\n非痴即是愚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8955, '菩萨蛮', '张抡', '人间何处难忘酒。\n小舟□□□杨柳。\n柳影蘸湖光。\n薰风拂□□。\n□□□□□。\n□□□□□。\n一盏此时倾。\n□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8956, '菩萨蛮', '张抡', '人间何处难忘酒。\n中秋皓月明如昼。\n银汉洗晴空。\n清辉万古同。\n凉风生玉宇。\n只怕云来去。\n一盏此时迟。\n阴晴未可知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8957, '菩萨蛮', '张抡', '人间何处难忘酒。\n素秋令节逢重九。\n步绕东篱。\n金英烂漫时。\n折来惊岁晚。\n心与南山远。\n一盏此时休。\n高怀何以酬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8958, '菩萨蛮', '张抡', '人间何处难忘酒。\n六花投隙琼瑶透。\n火满地炉红。\n萧萧屋角风。\n飘摇飞絮乱。\n浩荡银涛卷。\n一盏此时乾。\n清吟可那寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8959, '菩萨蛮', '张抡', '人间何处难忘酒。\n闭门永日无交友。\n何以乐天真。\n云山发兴新。\n听风松下坐。\n趁蝶花边过。\n一盏此时空。\n幽怀谁与同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8960, '菩萨蛮', '张抡', '人间何处难忘酒。\n□□□□□□斗。\n不是慕荣华。\n惟愁月□□。\n□□□□□。\n□□□□□。\n一盏此时悭。\n□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8961, '菩萨蛮', '张抡', '人间何处难忘酒。\n山村野店清明後。\n满路野花红。\n一帘杨柳风。\n田家春最好。\n箫鼓村村闹。\n一盏此时辞。\n将何乐圣时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8962, '菩萨蛮', '张抡', '人间何处难忘酒。\n兴来独步登岩岫。\n倚杖看云生。\n时闻流水声。\n山花明照眼。\n更有提壶劝。\n一盏此时斟。\n都忘名利心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8963, '菩萨蛮', '张抡', '人间何处难忘酒。\n水边石上逢山友。\n相约老山林。\n幽居不怕深。\n浮名心已尽。\n倾倒都无隐。\n一盏此时无。\n交情何以舒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8964, '诉衷情', '张抡', '闲中一卷圣贤书。\n耽玩意□□。\n潜心要游阃奥，须是下功夫。\n今何异，古何殊。\n本同途。\n若明性理，一点灵台，万事都无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8965, '诉衷情', '张抡', '闲中一片□□□。\n□□□□□。\n□□□澄秋水，明月夜□□。\n□□□，□□□。\n□□□。\n鹤长凫短，前定难□，□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8966, '诉衷情', '张抡', '闲中一亩小□□。\n临水对遥岑。\n茅茨□□低小，竹径要幽深。\n逢酒醉，遇花吟。\n日登临。\n四时无限，好景良辰，莫负光阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8967, '诉衷情', '张抡', '闲中一篆百花香。\n袅袅翠□□。\n低回宛转何似，行路绕羊肠。\n深竹户，小山房。\n雅相当。\n清心默坐，燕寝无风，永日芬芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8968, '诉衷情', '张抡', '闲中一戋瓮头春。\n养气又颐神。\n莫教大段沈醉，只好带微醺。\n心自适，体还淳。\n乐吾真。\n此怀何似，兀兀陶陶，太古天民。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8969, '诉衷情', '张抡', '闲中一盏建溪茶。\n香嫩雨前芽。\n砖炉最宜石铫，装点野人家。\n三昧手，不须夸。\n满瓯花。\n睡魔何处，两腋清风，兴满烟霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8970, '诉衷情', '张抡', '闲中一弄七弦琴。\n此曲少知音。\n多因淡然无味，不比郑声淫。\n松院静，竹林深。\n夜沈沈。\n清风拂轸，明月当轩，谁会幽心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8971, '诉衷情', '张抡', '闲中一叶小渔舟。\n无线也无钩。\n□□□云深处，适性自遨游。\n波渺渺，兴悠悠。\n意休休。\n一船明月，一棹清风，换了封侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8972, '诉衷情', '张抡', '闲中一觉日高眠。\n都没利□□。\n黑甜自来无比，百计总输先。\n花转影，篆凝烟。\n意悠然。\n华胥何处，蝶化逍遥，此意谁传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8973, '诉衷情', '张抡', '闲中一首醉时歌。\n此乐信无过。\n阳春自来寡和，谁与乐和。\n言不尽，意何多。\n且蹉跎。\n功名莫问，富贵休言，到底如何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8974, '减字木兰花', '张抡', '五行颠倒。\n火里栽莲君莫□。\n□要东牵。\n引取青龙来西边。\n一阳时候。\n□□温温光已透。\n消尽群阴。\n赫赤金丹色渐深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8975, '减字木兰花', '张抡', '阴阳均配。\n□□□□□□□。\n□□□□。\n争得灵苗不解□。\n□□□□。\n□□□□□□□。\n□是真铅。\n只□□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8976, '减字木兰花', '张抡', '至言妙道。\n□□□□□□□。\n□□□□。\n□是蓬莱顶上仙。\n归根□□。\n□□□□方复命。\n复命常存。\n此事幽微好细论。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8977, '减字木兰花', '张抡', '神仙何处。\n若有宿缘须□□。\n□□□□。\n不在山林及市朝。\n丹炉休守。\n须信人人皆自有。\n此外非真。\n莫认凡砂与水银。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8978, '减字木兰花', '张抡', '天机深远。\n不遇真仙争得见。\n欲下工夫。\n须是先寻偃月炉。\n抽添运用。\n火候不明□妄动。\n毫发才差。\n只恐灵根□□芽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8979, '减字木兰花', '张抡', '咽津纳气。\n鼎内须□□□□。\n□□□□。\n□□空铛枉误人。\n有真不□。\n□□□□□□□。\n□□修持。\n超出□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8980, '减字木兰花', '张抡', '冥冥窈窕。\n□□□□□□□。\n□□□□。\n□□□□□□□。\n□□□□。\n□□□□□□□。\n□□□□。\n□□□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8981, '减字木兰花', '张抡', '澄神静虑。\n□□□□□□□。\n□□□□。\n□□□水满池。\n无中养□。\n□□□□□□□。\n□□凡胎。\n五彩云生鹤驾来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8982, '减字木兰花', '张抡', '乾坤入手。\n谈笑三关云□□。\n□□□□。\n鬼骇神惊一黍光。\n逍遥宇内。\n□□□□□数外。\n功满三千。\n独跨斑麟入紫烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8983, '减字木兰花', '张抡', '还元返本。\n作用难明须细论。\n神气□□。\n窈窕之中复混成。\n勤修不倦。\n直到无为功始见。\n此是天机。\n不遇真仙莫强知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8984, '蝶恋花', '张抡', '碧海沈沈西极远。\n间访□□，□□□□□。\n恰值群仙来阆苑。\n相将□□□□□。\n□□□□谁得见。\n五彩□□，□□□□□。\n□□□□□□□。\n人间几度□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8985, '蝶恋花', '张抡', '□□□□□□□。\n□□□□，□□□□□。\n□影□□□□□。\n□□□□□□□。\n□□□□长不老。\n天□□□，□□□□□。\n□□□□□物表。\n广寒宫殿□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8986, '蝶恋花', '张抡', '碧落浮黎光景异。\n琼□□□，□□□□□。\n□有宝珠如黍米。\n天真□□□□□。\n□□□□凭玉几。\n花雨霏霏，散入诸天□。\n□□□□傅妙旨。\n至今流演无终纪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8987, '蝶恋花', '张抡', '弱水茫茫三万里。\n遥望蓬莱，浮动烟霄外。\n若问蓬莱何处是。\n珠楼玉殿金鳌背。\n惟是飞仙能驭气。\n霞袖飘摇，来往如平地。\n除□飞仙谁得至。\n只缘山在波涛底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8988, '蝶恋花', '张抡', '绝想凝真天地表。\n九□□□，□□□□□。\n行处旌幢参羽葆。\n五云随□□□□。\n□□神仙春不老。\n烟□□□，□□□□□。\n□□□□多与少。\n下窥海□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8989, '蝶恋花', '张抡', '□□□□□□□。\n□□□□，□□□□□。\n□□□□□□□。\n□□□□□□□。\n□□□□□露采。\n□□□□，□□□□□。\n□□□□□□□。\n飘然直□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8990, '蝶恋花', '张抡', '碧海灵桃花朵朵。\n阿母□□，□□□□□。\n作夜海风吹玉颗。\n分明□□□□□。\n□□□□苞已破。\n散液流□，馥郁□□□。\n□□三偷谁可那。\n如今先手还输我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8991, '蝶恋花', '张抡', '莫笑一瓢门户隘。\n任意游行，出入俱无碍。\n玉殿珠宫都不爱。\n别藏大地非尘界。\n东海扬尘瓢不坏。\n寒暑□移，瑞日何曾改。\n一住如今知几载。\n主人不老长春在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8992, '蝶恋花', '张抡', '清夜凝然□□□。\n□□□□，□□□□□。\n□界森罗星□□。\n□□□□□□□。\n□□□□萦碧雾。\n上□□□，□□□□□。\n□□□□□紫府。\n归来□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8993, '蝶恋花', '张抡', '不假□□□□□。\n□□□□，□□□□□。\n□□□□□□□。\n□□□□□□□。\n□□□□□□□。\n□□□□，□□□□□。\n□□□□□□□。\n□□□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8994, '鹊桥仙', '张抡', '远公连社，流传图画，千古声名独在。\n後人多少继遗踪，到我便、失惊打怪。\n西方未到，官方先到，冤我白衣吃菜。\n龙华三会愿相逢，怎敢学、他家二会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8995, '春光好', '张抡', '烟澹澹，雨。\n水溶溶。\n帖水落花飞不起，小桥东。\n翩翩怨蝶愁蜂。\n绕芳丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8996, '壶中天慢・念奴娇', '张抡', '洞天深处赏娇红，轻玉高张云幕。\n国艳天香相竞秀，琼苑风光如昨。\n露洗妖妍，风传馥郁，云雨巫山约。\n春浓如酒，五云台榭楼阁。\n圣代道洽功成，一尘不动，四境无鸣柝。\n屡有丰年天助顺，基业增隆山岳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8997, '水调歌头', '侯置', '晓雾散晴渚，秋色满湘山。\n青鞋黄帽，与名士共跻攀。\n窈窕深林幽谷，诘曲危亭飞观，俯首视尘寰。\n长啸望天末，馀响下云端。\n白鹤去，荒井在，汲清寒。\n醒然毛骨，浮丘招我御风还。\n拂拭苍崖苔鲜，一写胸中豪气，渺渺洞庭宽。\n山鬼善呵护，千载照层峦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8998, '水调歌头', '侯置', '凉吹送溪雨，落日散汀鸥。\n暮天空阔无际，层绿蛾浮。\n上印初辞藩寄，拂袖欣还故里，归骑及中秋。\n倚杖饱山阁，回首翠微楼。\n一区宅，千里客，旧从游。\n甘棠空有馀荫，谁解挽公留。\n翰墨文章独步，富贵功名馀事，当代仰风流。\n暂蜡登山屐，终作济川舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (8999, '水调歌头', '侯置', '湘水照秋碧，衡岳际天高。\n绣衣玉节，清晓欢颂拥旌旄。\n本是紫庭梁栋，暂借云台耳目，驿传小游遨。\n五管与三楚，爱胜春醪。\n扫材枪，苏耄倪，载弓。\n远民流恋，须信寰海待甄陶。\n坐享龟龄鹤算，稳佩金鱼玉带，常近赭黄袍。\n岁岁秋月底，沈醉紫檀槽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9000, '水调歌头', '侯置', '天地孕冲气，霜雪实嘉平。\n粹然经世材具，应为圣时生。\n妙处为仁受用。\n颠倒纵横无壅。\n一笑泮春冰。\n袖手无一语，四海已倾情。\n紫岩老，游戏事，悟诚明。\n当年夷夏高仰，玉振更金声。\n家有渊骞高第。\n可但闻诗闻礼。\n衣钵要相承。\n周绚馀彩，商鼎味新羹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9001, '瑞鹤仙', '侯置', '楚山无际碧。\n湛一溪晴绿，四郊寒色。\n霜华弄初日。\n看玉明遥草，金铺平碛。\n天涯倦翼。\n更何堪、临岐送客。\n念飞蓬、断梗无踪，把酒後期难觅。\n愁寂。\n梅花憔悴，茅舍萧疏，倍添凄恻。\n维舟岸侧。\n留君饮，醉休惜。\n想柯山春晚，还家应对，菊老松坚旧宅。\n叹宦游、索寞情怀，甚时去得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9002, '瑞鹤仙', '侯置', '溥天氛廓。\n看庆绵鸿祚，勋昭麟阁。\n蕃宣换符钥。\n占西南襟带，遍□油幕。\n湘流绕郭。\n蔼一城、和气雾薄。\n听嘈嘈、比屋欢声，共说吏闲民乐。\n遥想芗霏凫暖，翠拥屏深，晓风传乐。\n琼腴缓酌。\n花阴淡，柳丝弱。\n任松凋鹤瘦，莲龟老，丹颊常如旧渥。\n趁天申、去押西班，奉觞御幄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9003, '瑞鹤仙', '侯置', '春风无检束。\n放倡条冶叶，恣情丹绿。\n□莺喧燕宿。\n似东邻北里，都无贞淑。\n高情恨蹙。\n欢何时、重见桂菊。\n又谁知、天上黄姑，扫尽晚春馀俗。\n幽独。\n铅华不御，翡翠帷深，郁金裙蔌。\n长眉了目。\n嫣然态，倚修竹。\n纵青门瓜美，江陵橘老，怎比无穷剩馥。\n最难禁、扇底横枝，恼人睡足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9004, '满江红', '侯置', '天阔江南，秋未老、空江澄碧。\n江外月、飞来千丈，水天同色。\n万屋覆银清不寐，一城踏雪寒无迹。\n况楚风、连陌竞张灯，如元夕。\n山獠静，棠阴寂。\n秋稼盛，香醪直。\n听子城吹角，青楼横笛。\n君不见、苏仙翻醉墨，一篇水调锵金石。\n念良辰美景赏心时，诚难得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9005, '满江红', '侯置', '困顿春眠，无情思、梦魂飘泊。\n檐外雨、霏霏冉冉，乍睛还落。\n山黛四围频入眼，柳丝一缕低萦阁。\n念沈郎、多感更伤春，腰如削。\n风入户，香穿箔。\n花似旧，人非昨。\n任游蜂双燕，经营拂掠。\n海阔锦鱼传不到，洞深紫凤期难约。\n谩彩笺、牙管倚西窗，题红叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9006, '满江红', '侯置', '重到西湖，春拆信、露花酥滴。\n倚危栏、湖山佳处，短屏著色。\n拟泛一舟苍莽岸，恐伤万里羁游客。\n赖款门、修竹有高人，留狂迹。\n倾盖意，真相得。\n诗句里，曾相识。\n看戛然飞动，笔端金石。\n照眼光浮琼液满，断肠翠拥宫靴窄。\n问多情、还肯借青鸾，通消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9007, '满江红', '侯置', '老矣何堪，随处是、春衫酒滴。\n醉狂时、一挥千字，贝光玉色。\n失意险为湘岸鬼，浩歌又作长安客。\n且乘流、除却五侯门，无车迹。\n惊人句，天外得。\n医国手，尘中识。\n问鼎槐何似，卧云石。\n梦里略无轩冕念，眼前岂是江湖窄。\n拚蝇头、蜗角去来休，休姑息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9008, '满江红', '侯置', '甚矣吾衰，徒是苦、饥肠为孽。\n嗟寸禄、区区留恋，形疲心竭。\n江海一生真可羡，尘埃永昼何堪说。\n似钝刀、终岁斫空山，宁无缺。\n拚放浪，休豪杰。\n秋水涨，归期决。\n尽凫长鹤短，任渠分别。\n芒夜寻溪上酒，葛巾晓挂松间月。\n向丹霄、传语旧交游，慵非拙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9009, '水龙吟', '侯置', '夜来霜拂帘旌，淡云丽日开清晓。\n香猊金暖，冰壶玉嫩，佳辰寒早。\n橘绿橙黄，袖红裙翠，一堂欢笑。\n正梅妃月姊，雪肌粉面，争妆点、潇湘好。\n莫惜芳尊屡倒。\n拥群仙、醉游蓬岛。\n东床俊选，南溟归信，一时俱到。\n鬓影摇春，命书纡锦，子孙环绕。\n看他时归去，飞觞石涧，侍甘泉老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9010, '多丽', '侯置', '帝城春，玉堂深处飞烟。\n想圣人、恩隆内职，左押赐传宣。\n彩衣明、瑶觞膝下，花昼永、锦瑟尊前。\n富贵从来，功名馀事，鼎彝勒遍笔如椽。\n向中禁、琐窗偷觑，王母语当年。\n清平世，衣冠是谁，三世甘泉。\n记年时、翘才献寿，小诗曾苔笺。\n望三槐、云霞交映，照五彩、衮绣相鲜。\n当日非谀，如今方信，门人称颂是师言。\n况自有、两宫眷，卜梦亦徒然。\n看指日，鼎新化炉，一气陶甄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9011, '念奴娇', '侯置', '沧浪万顷，厌尘缨、手掬清流频洗。\n落日孤云烟渚净，鸥没澄波心里。\n一舸横秋，两桡开浪，霜竹醒烦耳。\n萧萧风露，梦回月照船尾。\n须信闲少忙多，壶觞并赋咏，莫辜云水。\n乘兴前溪溪转□，隐约归帆天际。\n红蓼丹枫，黄芦白竹，总胜春桃李。\n浮丘何在，与君共跨琴鲤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9012, '念奴娇', '侯置', '竞春台榭，媚东风、迤逦繁红成簇。\n方霁溪南帘绣卷，和气充盈华屋。\n金暖香彝，玉鸣舞佩，春笋调丝竹。\n乌衣宴会，远追王谢高躅。\n籍甚四海声名，林泉活计，未许翁知足。\n日日江边沙露静，人东来雕毂。\n八锦行持，五禽游戏，已受长生。\n衮衣蝉冕，最宜双鬓凝绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9013, '念奴娇', '侯置', '衰翁憨甚，向尊前、手拈一枝寒玉。\n想见梅台花更好，一片琼田栖绿。\n短辔轻舆，大家同去，取酒偿馥。\n元来春晚，万包空间黄竹。\n休恨雪小云娇，出群风韵，已觉桃花俗。\n羯鼓声高回笑脸，怎得天公来促。\n江上风平，岭南人远，谁度单于曲。\n明朝酒醒，但馀诗兴天北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9014, '风入松', '侯置', '少年心醉杜韦娘。\n曾格外疏狂。\n锦笺预约西湖上，共幽深、竹院松窗。\n愁夜黛眉颦翠，惜归罗帕分香。\n重来一梦觉黄梁。\n空烟水微茫。\n如今眼底无姚魏，记旧游、凝伫凄凉。\n入扇柳风残酒，点衣花雨斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9015, '风入松', '侯置', '东楼烟重暗山光。\n春意堕微茫。\n小红嫩绿匀如剪，黯无言、云渡澄江。\n没处与人消遣，倚阑情寄斜阳。\n共君今夜举清觞。\n投老各殊方。\n痴儿官事何时了，恨花时、潘鬓先霜。\n唤取客帆聊住，将予同下潇湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9016, '风入松', '侯置', '霏霏小雨恼春光。\n烟水更弥茫。\n昨宵把酒高歌处，任一声、鸡唱清江。\n憔悴杏花如许，情怀应似东阳。\n宿酲犹在莫传觞。\n消闷苦无方。\n几时玉杵蓝桥路，约云英、同捣玄霜。\n冷落黄昏庭院，梦回家在三湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9017, '遥天奉翠华引', '侯置', '雪消楼外山。\n正秦淮、翠溢回澜。\n香梢豆蔻，红轻犹怕春寒。\n晓光浮画戟，卷绣帘、风暖玉钩间。\n紫府仙人，花园羽帔星冠。\n蓬莱阆苑，意倦游、常戏世间。\n佩麟旧都，江左襦裤歌欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9018, '蓦山溪', '侯置', '玉麟春晚，绿遍甘棠荫。\n可是惜花深，旋移得、翻阶红影。\n朱帘卷处，如在古扬州，宝璎珞，玉盘盂，娇艳交相映。\n蓬莱殿里，几样春风鬓。\n生怕逐朝云，更罗幕、重重遮定。\n多情绛蜡，常见醉时容，萦舞袖，蔌歌尘，莫负良宵永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9019, '凤皇台上忆吹箫・凤凰台上忆吹箫', '侯置', '玉管灰飞，云台珥笔，东君飚驭将还。\n又正是、霜花□剪，梅粉初乾。\n窈窕红窗髻影，添一线、组绣工间。\n潇湘好，雪意尚遥，绿占群山。\n应思少年壮气，贪游乐、追随玉勒雕鞍。\n更化日舒长，赢得觅醉谋欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9020, '凤皇台上忆吹箫・凤凰台上忆吹箫', '侯置', '尘暗双凫，菊明山径，何妨倦羽知还。\n最好是，诗翁醉後，瓶罄乾。\n一笑东风打耳，心无竞、远与春间。\n时时地，觅伴访梅，寻胜登山。\n清时俊材定用，看捧诏春郊，月露濡鞍。\n况表识、买臣贵骨，琴瑟逾欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9021, '凤皇台上忆吹箫・凤凰台上忆吹箫', '侯置', '浴雪精神，倚风情态，百端邀勒春还。\n记旧隐、溪桥日暮，驿路泥乾。\n曾伴先生蕙帐，香细细、粉瘦琼间。\n伤牢落，一夜梦回，肠断家山。\n空教映溪带月，供游客无情，折满雕鞍。\n便忘了、明窗静几，笔研同欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9022, '凤皇台上忆吹箫・凤凰台上忆吹箫', '侯置', '浅染霓裳，轻匀汉额，巫山行雨方还。\n最好是、肌香蜡莹，萼嫩红乾。\n曾见金钟在列，钧天罢、笋都间。\n妖饶似，晓镜乍开，绿沁眉山。\n休夸瘦枝疏影，湘裙窄、一钩龙麝随鞍。\n便更做、山人倦赏，畏冷无欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9023, '蝶恋花', '侯置', '雪压小桥溪路断。\n独立无言，雾鬓风鬟乱。\n拂拭冰霜君试看。\n一枝堪寄天涯远。\n拟向南邻寻酒伴。\n折得花归，醉著歌声缓。\n姑射梦回星斗转。\n依然月下重相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9024, '清平乐', '侯置', '缕金剪彩。\n茸绾同心带。\n整整云鬟宜簇戴。\n雪柳闹蛾难赛。\n休夸结实炎州。\n且看指面纤柔。\n试问苦人滋味，何如插鬓风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9025, '清平乐', '侯置', '忍寒情味。\n枝染蔷薇水。\n搅照清溪花影碎。\n笑杀小桃李。\n一生占断春妍。\n偏宜月露娟娟。\n欲寄江南春去，乱鸦点破云笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9026, '玉楼春', '侯置', '市桥灯火春星碎。\n街鼓催归人未醉。\n半嗔还笑眼回波，欲去更留眉敛翠。\n归来短烛馀红泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9027, '玉楼春', '侯置', '今秋中月逢馀闰。\n月姊重来风露静。\n未劳玉斧整蟾宫，又见冰轮浮桂影。\n寻常经岁睽佳景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9028, '秦楼月・忆秦娥', '侯置', '天一色。\n玉盘冷浸潇湘碧。\n潇湘碧。\n短亭系缆，隔江闻笛。\n胡床对坐凉生腋。\n通宵说尽狂踪迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9029, '新荷叶', '侯置', '柳幄飞绵，风池暖泛新萍。\n燕垒泥香，玉麟堂外春深。\n晴云丽日，花浓处、蜂蝶纷纷。\n偿春一醉，管弦声里欢声。\n况是清时，锦衣重到台城。\n故国江山，向人依旧多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9030, '菩萨蛮', '侯置', '楼前曲浪归桡急。\n楼中细雨春风湿。\n终日倚危阑。\n故人湖上山。\n高情浑似旧。\n只枉东阳瘦。\n薄晚去来休。\n装成一段愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9031, '菩萨蛮', '侯置', '东风吹梦春酲恶。\n琐窗淡淡花阴薄。\n一夜曲池平。\n小窗云样明。\n绿轻眉懒晕。\n香浅罗衣润。\n未见海棠开。\n卷帘双燕来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9032, '菩萨蛮', '侯置', '江风漠漠寒山碧。\n孤鸿声里霜花白。\n画舸且停桡。\n有人魂欲销。\n相从能几日。\n总是天涯客。\n尺素好频裁。\n休言无雁来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9033, '菩萨蛮', '侯置', '东君管尽闲花草。\n红红白白知多少。\n末後一奁香。\n绿庭春昼长。\n道人心似海。\n梦冷屏山里。\n莫剪最长条。\n从教玉步摇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9034, '菩萨蛮', '侯置', '东风卷尽欺花雨。\n月明皎纸庭前路。\n月底且论诗。\n从教露湿衣。\n明朝愁入绪。\n各自东归去。\n後夜月明中。\n绿尊谁与同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9035, '菩萨蛮', '侯置', '绿帷剪剪黄金碎。\n西风庭院清如水。\n月姊更多情。\n与人无际明。\n浓阴遮玉砌。\n桂影冰壶里。\n灭烛且徜徉。\n夜深应更香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9036, '菩萨蛮', '侯置', '靓妆金翠盈盈晚。\n凝情有恨无人管。\n何处一帘风。\n故人天际逢。\n从教香扑鬓。\n只怕繁华尽。\n牢落正悲秋。\n非□谁解愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9037, '菩萨蛮', '侯置', '江梅占尽江头雪。\n忍寒玉骨夸清绝。\n不似杜秋娘。\n婆娑秋水傍。\n波光涵晚日。\n照影从教密。\n隐隐认遥黄。\n隔溪十里香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9038, '菩萨蛮', '侯置', '黄昏曾见凌波步。\n无端暝色催人去。\n一夜露华浓。\n香销兰菊丛。\n缕金衣易湿。\n莫对西风泣。\n洗尽夜来妆。\n温泉初赐汤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9039, '菩萨蛮', '侯置', '休文多病疏杯酌。\n被花恼得心情恶。\n碧树又惊秋。\n追欢怀旧游。\n与君聊一醉。\n醉倒花阴里。\n斜日下阑干。\n满身金屑寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9040, '菩萨蛮', '侯置', '交刀剪碎琉璃碧。\n深黄一穗珑松色。\n玉蕊纵妖娆。\n恐无能样娇。\n绿窗初睡起。\n堕马慵梳髻。\n斜插紫鸾钗。\n香从鬓底来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9041, '菩萨蛮', '侯置', '黄姑青女交相忌。\n眼看尘土占芳蕊。\n急埽满阑金。\n小奁熏水沈。\n博山银叶透。\n浓馥穿罗袖。\n犹欲问鸿都。\n太真安稳无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9042, '菩萨蛮', '侯置', '午庭栩栩花间蝶。\n翅添金粉穿琼叶。\n曾见羽衣黄。\n瑶台淡薄妆。\n醒来魂欲断。\n掺掺芳英满。\n梦里尚偷香。\n何堪秋夜长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9043, '菩萨蛮', '侯置', '霓裳舞罢难留住。\n湘裙缓若轻烟去。\n动是隔年期。\n生绡傅艳姿。\n精神浑似旧。\n碧暗黄金瘦。\n永夜对西窗。\n何缘襟袖香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9044, '菩萨蛮', '侯置', '揉香嗅蕊朝还暮。\n无端却被西风误。\n底死欲留伊。\n金尘蔌蔌飞。\n茂陵头已白。\n新聘谁相得。\n耐久莫相思。\n年年秋与期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9045, '西江月', '侯置', '金鼎香销沈麝，碧梧影转阑干。\n可庭明月绮窗闲。\n帘幕低垂不卷。\n一自高唐人去，秋风几许摧残。\n拂檐修竹韵珊珊。\n梦断山长水远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9046, '西江月', '侯置', '豆蔻梢头年纪，芙蓉水上精神。\n幼云娇玉两眉春。\n京洛当时风韵。\n金缕深深劝客，雕梁蔌蔌飞尘。\n主人从得董双成。\n应忘瑶池宴饮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9047, '青玉案', '侯置', '东风一夜吹晴雨。\n小园里、春如许。\n桃李无言情难诉。\n阳关车马，灞桥风月，移入江天暮。\n双旌明日留难住。\n今夕清觞且频举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9048, '青玉案', '侯置', '年年寓屋称觞处。\n陪彩绶、尊前舞。\n牢落潇湘归去未。\n蜡梅开遍，冰蟾圆後，梦断灵溪路。\n长年厚福天分付。\n算四海、今独步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9049, '青玉案', '侯置', '三年牢落荒江路。\n忍明日、轻帆去。\n冉冉年光真暗度。\n江山无助，风波有险，不是留君处。\n梅花万里伤迟暮。\n驿使来时望佳句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9050, '昭君怨', '侯置', '晴日烘香花睡。\n花艳浮杯人醉。\n杨柳绿丝风。\n水溶溶。\n留恋芳丛深处。\n懒上锦鞯归去。\n待得牡丹开。\n更同来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9051, '四犯令', '侯置', '月破轻云淡注。\n夜悄花无语。\n莫听阳关牵离绪。\n拚酩酊、花深处。\n明日江郊芳草路。\n春逐行人去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9052, '鹧鸪天', '侯置', '万点胭脂落日烘。\n坐间酒面散微红。\n谁教艳质撩潘鬓，生怕朝云逐楚风。\n寻画烛，照芳容。\n夜深两行锦灯笼。\n朱唇翠袖休凝伫，几许春情睡思中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9053, '鹧鸪天', '侯置', '蜀锦吴绫剪染成。\n东皇花令一番新。\n风帘不碍寻巢燕，雨叶偏禁斗草人。\n非病酒，不关春。\n恨如芳草思连云。\n西楼角畔双桃树，几许浓苞等露匀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9054, '鹧鸪天', '侯置', '梦想当年姚魏家。\n尊前重见旧时花。\n双檠分焰交红影，四座春回粲晚霞。\n杯潋滟，帽斜。\n夜深绝艳愈清佳。\n天明恐逐行云去，更著重重翠幕遮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9055, '鹧鸪天', '侯置', '只有梅花是故人。\n岁寒情分更相亲。\n红鸾跨碧江头路，紫府分香月下身。\n君既去，我离群。\n天涯白发怕逢春。\n西湖苍莽烟波里，来岁梅时痛忆君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9056, '朝中措', '侯置', '翻阶红药竞芬芳。\n著意巧成双。\n须信扬州国艳，旧时曾在昭阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9057, '朝中措', '侯置', '漏云初见六花开。\n惊巧妒江梅。\n飘洒元戎小队，玉妆旌旆归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9058, '朝中措', '侯置', '露英云萼一般清。\n揉雪更雕琼。\n预喜重阳登览，大家插帽浮觥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9059, '朝中措', '侯置', '依微春绿遍江干。\n烟水小屏寒。\n惆怅雁行南北，新词不忍拈看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9060, '朝中措', '侯置', '风帘交翠篆香飘。\n却暑卷轻绡。\n最好佳辰相近，寿觞对饮连宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9061, '朝中措', '侯置', '年来玉帐罢兵筹。\n灯市小迟留。\n花外香随金勒，酒边人倚红楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9062, '朝中措', '侯置', '年年重午近佳辰。\n符艾一番新。\n满酌九霞奇酝，寿君两鬓长春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9063, '点绛唇', '侯置', '春日迟迟，柳丝金淡东风软。\n绿娇红浅。\n帘幕飞新燕。\n玉帐优游，赢得花间宴。\n香尘远。\n暂停歌扇。\n□醉深深院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9064, '点绛唇', '侯置', '约莫香来，倚阑低瞰花如雪。\n怨深愁绝。\n瘦似年时节。\n岁一相逢，常是匆匆别。\n歌壶缺。\n又还吹彻。\n笛里关山月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9065, '苏武慢', '侯置', '暗雨收梅，晴波摇柳，万顷水精宫冷。\n桥森画栋，岸列红楼，两岸翠帘交映。\n天上行舟，鉴中开户，人在蕊珠仙境。\n况吟烟啸月，弹丝吹竹，太平歌咏。\n人尽说、铜虎分贤，银潢储秀，巩固行都藩屏。\n棠阴散暑，鼎篆凝香，永日一庭虚静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9066, '阮郎归', '侯置', '莫欺骑省鬓边华。\n曾眠苏小家。\n彩丝萦腕剪轻霞。\n菖蒲酒更嘉。\n人别後，叹飞花。\n云山和梦遮。\n吴笺小字写流沙。\n几行秋雁斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9067, '阮郎归', '侯置', '美人小字称春娇。\n云鬟玉步摇。\n淡妆浓态楚宫腰。\n梅枝雪未消。\n拚恼乱，尽妖娆。\n微窝生脸潮。\n算来虚度怜宵。\n醉魂谁与招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9068, '阮郎归', '侯置', '薰风吹尽不多云。\n晓天如水清。\n哦松庭院忽闻笙。\n帘疏香篆明。\n兰玉盛，凤和鸣。\n家声留汉庭。\n狨鞍长傍九重城。\n年年双鬓青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9069, '浪淘沙', '侯置', '晓日掠轻云。\n霜瓦鳞鳞。\n六朝山色俨如新。\n家在洞庭南畔住，身在江滨。\n华发照乌巾。\n无意寻春。\n空将两袖拂飞尘。\n可惜梅花开近路，恼尽行人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9070, '踏莎行', '侯置', '元夕风光，中兴时候。\n东风著意催梅柳。\n谁家银字小笙簧，倚阑度曲黄昏後。\n拨雪张灯，解衣贳酒。\n觚金碧闻依旧。\n明年何处看升平，景龙门下灯如昼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9071, '踏莎行', '侯置', '雪意初浓，云情已厚。\n黄昏散尽扶头酒。\n不知墙外夜来梅，忍寒添得疏花否。\n休更熏香，且同携手。\n从教策策轻寒透。\n亭儿直下玉生烟，暗香归去沾襟袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9072, '浣溪沙', '侯置', '客里忽忽梦帝州。\n故人相遇一杯休。\n疏梅些子最清幽。\n双绾香螺春意浅，缓歌金缕楚云留。\n不知妆镜若为俦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9073, '浣溪沙', '侯置', '倚醉怀春翠黛长。\n肉红衫子半窥墙。\n兰汤浴困嫩匀妆。\n应为长年餐绛雪，故教丹颊耐清霜。\n弄晴飞馥笑冯唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9074, '浣溪沙', '侯置', '春梦惊回谢氏塘。\n箧中消尽旧家香。\n休文多病怯秋光。\n空对金盘承瑞露，竟无玉杵碎玄霜。\n醉魂飞度月宫凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9075, '眼儿媚', '侯置', '花信风高雨又收。\n风雨互迟留。\n无端燕子，怯寒归晚，闲损帘钩。\n弹棋打马心都懒，撺掇上春愁。\n推书就枕，凫烟淡淡，蝶梦悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9076, '渔家傲', '侯置', '过尽百花芳草满。\n柳丝舞困阑干暖。\n柳外秋千裙影乱。\n人逐伴。\n旧家心性如今懒。\n斗帐宝香凝不散。\n黄昏院落莺声晚。\n红叶不来音信断。\n疏酒盏。\n东阳瘦损无人管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9077, '渔家傲', '侯置', '本是潇湘渔艇客。\n钱塘江上铺帆席。\n两处烟波天一色。\n云幂幂。\n吴山不似湘山碧。\n休费精神劳梦役。\n鸥凫难上铜驼陌。\n扰扰红尘人似织。\n山头石。\n潮生月落今如昔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9078, '临江仙', '侯置', '一抹烟林屏样展，轻花岸柳无边。\n连朝春雨涨平川。\n冬冬迎社鼓，渺渺下陂船。\n同事多才饶我懒，乘闲纵饮郊园。\n髻花侧醉巾偏。\n时丰容卒岁，游乐更明年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9079, '临江仙', '侯置', '失脚青云何所往，故山松竹应秋。\n痴儿官事几时休。\n可怜双白鬓，斗栗尚迟留。\n尊酒偷闲聊放旷，夜凉河汉西流。\n从教孤笛喷高楼。\n与君同一醉，明日旋分愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9080, '柳梢青', '侯置', '小院轻寒，酒浓香软，深沈帘幕。\n我辈相逢，欢然一笑，春在杯酌。\n家山辜负猿鹤。\n轩冕意、秋云似薄。\n我自西风，扁舟归去，看君寥廓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9081, '柳梢青', '侯置', '楚天清绝。\n苇岸兰汀，素秋时节。\n帘卷湘鬟，香飞云篆，叵看轻别。\n明朝底处关山，算总是、愁花恨月。\n白马江寒，黄牛峡静，小梅初彻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9082, '杏花天', '侯置', '宝钗整鬓双鸾斗。\n睡未醒、熏风襟袖。\n彩丝皓腕宜清昼。\n更艾虎、衫儿新就。\n玉杯共饮菖蒲酒。\n愿耐夏、宜春厮守。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9083, '江城子', '侯置', '萍蓬踪迹几时休。\n尽飘浮。\n为君留。\n共话当年，年少气横秋。\n莫叹两翁俱白发，今古事，尽悠悠。\n西风吹梦入江楼。\n故山幽。\n谩回头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9084, '南歌子', '侯置', '菊润初经雨，橙香独占秋。\n碧琳仙酿试新。\n内集熙熙休试、蚁浮瓯。\n家世传黄阁，功名起黑头。\n双凫聊傍故人舟。\n咫尺青云岐路、看英游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9085, '瑞鹧鸪', '侯置', '遥天拍水共空明。\n玉镜开奁特地晴。\n极目秋容无限好，举头醉眼暂须醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9086, '天仙子', '侯置', '暖日丽晴春正好。\n杨柳池塘风弄晓。\n露桃云杏一番新，花窈窕。\n香飘缈。\n玉帐靓深闻语笑。\n新赐绣鞯花映照。\n须信浓恩春共到。\n汉家飞将久宣劳，迎禁诏。\n瞻天表。\n入卫帝庭常不老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9087, '醉落魄・一斛珠', '侯置', '铜壶漏歇。\n纱窗倒挂梅梢月。\n玉人酒晕消香雪。\n促轸调弦，弹个古离别。\n雏莺小凤交飞说。\n嘈嘈软语丁宁切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9088, '醉落魄・一斛珠', '侯置', '梅花似雪。\n雪花却似梅清绝。\n小窗低映梅梢月。\n常记良宵，吹酒共攀折。\n如今客里都休说。\n潇潇洒洒情怀别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9089, '醉落魄・一斛珠', '侯置', '玉钩珠箔。\n夜凉庭院天垂幕。\n好风吹动纶巾角。\n羽扇休挥，已怯衣薄。\n扁舟明日清溪泊。\n归来依旧情怀恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9090, '减字木兰花', '侯置', '春酲拚却。\n一声花雨落。\n密炬红残。\n人在青罗步障间。\n天公薄相。\n惯得柳绵高百丈。\n彩笔题诗。\n休诵骚人九辨词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9091, '鹊桥仙', '侯置', '鹤发萧森，玉颜腴润，养就黄芽金鼎。\n一区松菊老湘滨，但心远、何妨人境。\n衮衣家世，鸣鸾歌舞，到了春冰消尽。\n不须惆怅梦中身，这彩选、输赢谁省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9092, '醉蓬莱', '赵彦端', '向蓬莱云渺。\n姑射山深，有春长好。\n香满枝南，笑人间惊早。\n试问寒柯，镂冰裁玉，费化工多少。\n东阁诗成，西湖梦觉，几番清晓。\n好是罗帏，麝温屏暖，却恨烟村，雨愁风恼。\n一一清芬，为东君倾倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9093, '满江红', '赵彦端', '千种繁春，春已去、翩然无迹。\n谁信道、荼シ枝上，静中留得。\n晓镜洗妆非粉白，晚衣弄舞馀衫碧。\n粲宝钿、珠珥不胜持，浓阴夕。\n金翦度，还堪惜。\n霜蝶睡，无从觅。\n知多少、好词清梦，酿成冰骨。\n天女散花无酒圣，仙人种玉惭香德。\n怅攀条、记得鬓丝青，东风客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9094, '满江红', '赵彦端', '津鼓冬冬，三老醉、知谁留得。\n都不记、琵琵洲畔，草青江碧。\n桃李春风吹不断，烟霞秋兴清无极。\n怅樽前、桂子有馀香，曾相识。\n残雨昼，初凉夕。\n高烛烂，新醅白。\n长歌断，欢意不如愁色。\n父老能寻循吏传，关河暂枉诸侯客。\n待日边、一纸诏黄飞，胜相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9095, '满江红', '赵彦端', '赐被薰炉，曾同见、官槐重绿。\n时归看、绮疏叠嶂，楚腰翻曲。\n君过蓬山轻岁月，我怀庐阜分符竹。\n道别离、待得再归来，人应俗。\n春欲动，醅初熟。\n追一笑，森三玉。\n且相对青眼，共裁红烛。\n小语人家闲意态，浅寒都下新装束。\n念平生、和雨醉东风，从今足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9096, '水调歌头', '赵彦端', '秋色忽如许，风露皎如空。\n平生青鬓馀地，老与故人同。\n忆得鲈鱼来後，杂以洞庭新橘，月堕酒杯中。\n宾客可人意，歌舞转春风。\n坐间玉，花底扇，又从容。\n从容更好，无奈多病已衰翁。\n赖有主人风味，识我少年狂态，乞与酒颜红。\n一醉晓鸦起，流水任西东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9097, '水调歌头', '赵彦端', '淦水定何许，楼外满晴岚。\n落霞蜚鸟无际，新酒为谁甘。\n闻道居邻玉笥，下有芝田琳苑，光景照江南。\n已转丹砂九，应降素云三。\n忆畴昔，翻舞袖，纵剧谈。\n玉壶倾倒，香务黄菊酿红柑。\n好在当时明月，只有炉薰一缕，缄寄可同参。\n剩肯南游不，蓬海试穷探。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9098, '瑞鹤仙', '赵彦端', '记河梁折柳。\n问画堂乐事，燕鸿难偶。\n十年谩回首。\n但亭亭紫盖，差差南斗。\n传闻小有。\n种桃花、亲烦素手。\n怪归来、道骨仙风缥缈，迥然非旧。\n清昼。\n江南如画，紫菊冬前，翠橙霜後。\n扁舟渡口。\n佳客至，奉名酒。\n唤青鸾起舞，云窗月槛，一曲山明水秀。\n笑相看、玉海别来，浅如故否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9099, '瑞鹤仙', '赵彦端', '揽垂杨细折。\n有别情遗爱，与君都说。\n文茵带雕轭。\n是行春来处，去年阡陌。\n柔桑半叶。\n转光风、轻扬秀麦。\n正人家共约，耕相借牛，社相留客。\n清绝。\n溪山犹记，脱帽吟风，倚楼招月。\n东君何事，将春至，放春歇。\n道从今江上，一花一柳，皆想油幢瑞节。\n纵离愁、瘦减腰围，带金正晔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9100, '朝中措', '赵彦端', '山矾风味更梨花。\n清白竞春华。\n试问西园清夜，何如山崦人家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9101, '朝中措', '赵彦端', '烧灯已过禁烟前。\n春信递相传。\n柳暗乍迷津路，花暄欲照江天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9102, '朝中措', '赵彦端', '长松擎月与天通。\n霜叶乱惊鸿。\n露炯乍疑杯滟，云生似觉衣重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9103, '朝中措', '赵彦端', '几枝筇竹半烟云。\n钟鼓醉中闻。\n千点好山馀思，一湾流水能分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9104, '朝中措', '赵彦端', '新凉溪阁暮山重。\n水月共空。\n九转不须尘外，三峰只在壶中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9105, '朝中措', '赵彦端', '西城烟雾一重重。\n潇洒便秋风。\n巧妒玉人装髻，无如禁钥难通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9106, '新荷叶', '赵彦端', '欲暑还凉，如春有意重归。\n春若归来，任他莺老花飞。\n轻雷澹雨，似晚风、欺得单衣。\n檐声惊醉，起来新缘成围。\n回首分携。\n光风冉冉菲菲。\n曾几何时，故山疑梦还非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9107, '新荷叶', '赵彦端', '雨细梅黄，去年双燕还归。\n多少繁红，尽随蝶舞蜂飞。\n阴浓绿暗，正麦秋、犹衣罗衣。\n香凝沈水，雅宜帘幕重围。\n绣扇仍携。\n花枝尘染芳菲。\n遥想当时，故交往往人非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9108, '新荷叶', '赵彦端', '玉井冰壶，人间有此清秋。\n笑语雍雍，从今庭户初修。\n迎风待月，香凝处、四卷帘钩。\n月波奇观，未饶当日南楼。\n闻说三吴，江湖胜、从古风流。\n况有双，旧谙黄阁青油。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9109, '看花回', '赵彦端', '注目。\n正江湖浩荡，烟云离属。\n美人衣兰佩玉。\n澹秋水凝神，阳春翻曲。\n烹鲜坐啸，清净五千言自足。\n横剑气、南斗光中，浩然一醉引双鹿。\n回雁到、归书未续。\n梦草处、旧芳重绿。\n谁忆潇湘岁晚，为唤起长风，吹飞黄鹄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9110, '看花回', '赵彦端', '爱日。\n报疏梅动意，春前呼得。\n画栋晓开寿城。\n度百和温馨，霜华无力。\n斑衣翠袖，人面年年照酒色。\n环四座、璧月琼枝，恍然江县拟乡国。\n闻道抚、东岩旧迹。\n又殊胜、谢家清逸。\n知与桃花笑了，定何似青鸟，层城消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9111, '芰荷香', '赵彦端', '燕初归。\n正春阴暗淡，客意凄迷。\n玉觞无味，晚花雨退凝脂。\n多情细柳，对沈腰、浑不胜垂。\n别袖忍见离披。\n江南陌上，强半红飞。\n乐事从今一梦散，纵锦囊空在，金碗谁挥。\n舞裙歌扇，故应间琐幽闺。\n练江诗就，算舟、宁不相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9112, '垂丝钓', '赵彦端', '短篷醉舣。\n江南秋意如水。\n露草星明，风柳丝委。\n危槛倚。\n为故人宴喜。\n欢无几。\n念青鞋紫绮。\n论诗载酒，犹胜心寄双鲤。\n倦游晚矣。\n云路非吾事。\n湖海从君意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9113, '垂丝钓', '赵彦端', '莫愁有信。\n全胜春梦无准。\n篆缕欲销，衣粉堪认。\n残梦醒。\n枕夜凉满鬓。\n想香迳。\n正垂垂美荫。\n晚花在否，朱阑谁与同凭。\n断云怨冷。\n青鸟无凭问。\n红叶翻成恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9114, '谒金门', '赵彦端', '朱槛曲。\n妆浅鬓云吹绿。\n半尺鹅溪凉意足。\n手香沾柄玉。\n午梦已惊难续。\n说与翠梧修竹。\n蓬海路遥天六六。\n乘鸾何处逐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9115, '谒金门', '赵彦端', '劳顾曲。\n燕贡雅羞衣绿。\n鲁酒不能春味足。\n小杯空荐玉。\n只愿此欢常续。\n莫序水边丝竹。\n明日朝参同趁六。\n犹期归骑逐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9116, '谒金门', '赵彦端', '休相忆。\n明夜远如今日。\n楼外绿烟村幂幂。\n花飞如许急。\n柳岸晚来船集。\n波底斜阳红湿。\n送尽去云成独立。\n酒醒愁又入。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9117, '谒金门', '赵彦端', '春已半。\n绣绿新红如换。\n燕子还来帘幕畔。\n闲愁天不管。\n翠被曲屏香满。\n花叶彩笺人远。\n鹊喜蛛丝都未判。\n连环空约腕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9118, '谒金门', '赵彦端', '春不尽。\n处处与情相趁。\n谁道刘郎家恁近。\n一年花不问。\n双剪画罗春胜。\n今夜月圆如镜。\n怎得酒阑心易定。\n试将金液镇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9119, '谒金门', '赵彦端', '春似绣。\n不是别离时候。\n滴尽黄昏残刻漏。\n月高花影昼。\n好在画屏金兽。\n深琐粉窗兰牖。\n溪水南来堪问否。\n几时离渡口。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9120, '谒金门', '赵彦端', '朱户密。\n镇锁一庭春日。\n画幕黄帘芳草碧。\n游蜂初未识。\n脆管么弦无力。\n青子绿阴如织。\n花满深宫无路入。\n旧游浑记得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9121, '谒金门', '赵彦端', '春意密。\n不受人间风日。\n一曲清歌云暮碧。\n尊前今夜识。\n醉客倦吟无力。\n滞梦停愁相织。\n只道桃源难再入。\n有人还问得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9122, '柳梢青', '赵彦端', '衰翁自谪。\n堪笑忘了，山林闲适。\n一岁花黄，一秋酒绿，一番头白。\n浮生似醉如客。\n问底事、归来未得。\n但愿长年，故人相与，春朝秋夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9123, '柳梢青', '赵彦端', '卮言日出。\n天上漫试，人间无术。\n一笑归来，身如蝉蜕，首如龟缩。\n年年白酒黄花，共愿我、光风霁月。\n不道道人，老去，如何消得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9124, '柳梢青', '赵彦端', '酴过也，酴过後，无花堪折。\n只有垂杨，垂杨却作，絮惊行色。\n海棠半在如无，又争倩、蔷薇恋得。\n除是东风，随君归问，玉堂消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9125, '好事近', '赵彦端', '君莫厌江乡，也有茂林修竹。\n竹外有些亭榭，置酒尊棋局。\n棋神酒圣各成欢，欢长更烧烛。\n寄语故人鹏，任倾金围玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9126, '好事近', '赵彦端', '君到共黄花，君去早梅将发。\n君不待梅归去，问与谁同折。\n白头潘令一年秋，有酒恨无客。\n莫忘道山堂上，话清音风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9127, '好事近', '赵彦端', '草草复匆匆，相见也还相忆。\n记取梦魂诗思，似水光山色。\n清音堂下一扁舟，谁主又谁客。\n休厌一杯相劝，看梅梢将白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9128, '好事近', '赵彦端', '寻得一枝春，惊动小园花月。\n把酒放歌添烛，看连林争发。\n从今日日有花开，野水酿春碧。\n旧日爱闲陶令，作江南狂客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9129, '好事近', '赵彦端', '风露入新亭，看尽楚天秋色。\n行到暮霞明处，有金华仙刻。\n孤城乔木堕荒凉，白云带溪碧。\n唤取小舟同醉，话江湖归日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9130, '好事近', '赵彦端', '一种岁前春，谁辨额黄腮白。\n风意只吟群木，与此花修别。\n此花佳处似佳人，高情带诗格。\n君与岁寒相许，有芳心难结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9131, '好事近', '赵彦端', '朱户闭东风，春在小红纤雪。\n门外未寒犹暖，怪有花堪折。\n梨花菊蕊不相饶，娇黄带轻白。\n莫厌醉歌相恼，是中原乡客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9132, '好事近', '赵彦端', '日日念江东，何有旧人重说。\n二妙一时相遇，怪尊前头白。\n山城无物为君欢，薄酒待寒月。\n草草数歌休笑，似主人衰拙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9133, '点绛唇', '赵彦端', '山水乡中，岂知还有中原笑。\n醉歌倾倒。\n记得升平调。\n旧日年光，试把华灯照。\n心情好。\n有些怀抱。\n拟向梅花道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9134, '点绛唇', '赵彦端', '一点青阳，早梅初识春风面。\n暖回琼管。\n斗自东方转。\n白马青袍，莫作铜驼恋。\n看宫线。\n但长相见。\n爱日如人愿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9135, '点绛唇', '赵彦端', '护雨烘晴，紫云缥缈来深院。\n晚寒谁见。\n红杏梢头怨。\n绝代佳人。\n万里沈香殿。\n光风转。\n梦馀千片。\n犹恨相逢浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9136, '点绛唇', '赵彦端', '秋入阑干，亭亭波面虹千丈。\n一声鱼唱。\n画个三高样。\n江上风波，更泛吴松浪。\n寒潮涨。\n石鱼酒舫。\n漫叟知何向。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9137, '点绛唇', '赵彦端', '好在苍苔，摩挲遗恨风还雨。\n一凉相与。\n片月生新浦。\n天外离居，为我荪桡举。\n山如许。\n故人来否。\n岁晚鲈堪煮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9138, '秦楼月・忆秦娥', '赵彦端', '香蔌蔌。\n小山丛桂烘温玉。\n烘温玉。\n酒愁花暗，沈腰如束。\n烦君剩与阳春曲。\n为君细拂衾罗馥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9139, '秦楼月・忆秦娥', '赵彦端', '梅缀雪。\n雪缀梅花肌肤惬。\n肌肤惬。\n丰姿浓态，莹如玉色。\n岁寒期约无相缺。\n祥花不减晴空月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9140, '阮郎归', '赵彦端', '岁寒堂下两株梅。\n商量先後开。\n春前日绕一千回。\n花来春未来。\n冰可断，玉堪裁。\n寒空无暖埃。\n为君翻动腊前醅。\n酒醒香满怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9141, '阮郎归', '赵彦端', '一春种得牡丹成。\n那知君遽行。\n东君也自没心情。\n夜来风雨声。\n追间阔，数清明。\n不应歌渭城。\n只愁河畔草青青。\n却须离绪生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9142, '阮郎归', '赵彦端', '三年何许竞芳辰。\n君家千树春。\n如今欲去复逡巡。\n好花留住人。\n红蕊乱，绿阴匀。\n彩云新又新。\n只应小阕记情亲。\n动君梁上尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9143, '减字木兰花', '赵彦端', '四弦续续。\n山水依然关塞足。\n天上新声。\n谪堕人间得自名。\n清歌宛转。\n弹向指间依旧见。\n满眼春风。\n不觉黄梅细雨中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9144, '减字木兰花', '赵彦端', '绿阴红雨。\n黯淡衣裳花下舞。\n花月佳时。\n舞破东风第几枝。\n一杯相属。\n从尊前三四烛。\n酒尽花阑。\n京洛风流仔细看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9145, '减字木兰花', '赵彦端', '一年歌舞。\n还是花黄尊绿处。\n雨横风多。\n比似年时恨若何。\n帘深酒暖。\n细雨斜风浑不管。\n只有黄花。\n欲近佳人鬓畔鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9146, '减字木兰花', '赵彦端', '送人南浦。\n日日客亭风又雨。\n相见如何。\n梅子枝头春已多。\n真成别去。\n酒病明朝知几许。\n淋损宫袍。\n都是人人醉後娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9147, '减字木兰花', '赵彦端', '屈亭湘浦。\n怨尽朝云还暮雨。\n知是谁何。\n赋得清愁尔许多。\n爱来慵去。\n此意平生成浪许。\n著尽茸袍。\n想像江梅雪後娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9148, '减字木兰花', '赵彦端', '乱云萦浦。\n做雪不成还是雨。\n知我为何。\n一笑仍添一恨多。\n不须归去。\n琥珀杯深能几许。\n草色如袍。\n记取从今舞处娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9149, '鹊桥仙', '赵彦端', '来时夹道，红罗步障，已换青丝翠羽。\n春愁元自逐春来，却不肯、随春归去。\n千觞美酒，十分幽事，归到只愁风雨。\n凭谁传语牡丹花，为做取、东君些主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9150, '鹊桥仙', '赵彦端', '江梅仙去，蜡梅蜂化，只有缃梅呈秀。\n不知春在阿谁边，试与问、青青杨柳。\n小园幽事，中都风味，斗草分香依旧。\n东风莫谩送扁舟，为管取、轻寒罗袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9151, '鹊桥仙', '赵彦端', '留花翠幕，添香红袖，常恨情长春浅。\n南风吹酒玉虹翻，便忍听、离弦声断。\n乘鸾宝扇，凌波微步，好在清池凉馆。\n直饶书与荔枝来，问纤手、谁传冰碗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9152, '鹊桥仙', '赵彦端', '藕花亭上，无尘无暑，滟滟一池秋韵。\n绿罗宝盖碧琼竿，翠浪里、亭亭月影。\n一家姊妹，两般梳洗，浓淡施朱傅粉。\n夜深风露逼人怀，问谁在、牙床酒醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9153, '菩萨蛮', '赵彦端', '雪中梅艳风前竹。\n诗缘渐与情缘熟。\n醉眼眩成花。\n恼人生脸霞。\n巫云将楚雨。\n只恐翩然去。\n我有合欢杯。\n为君聊挽回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9154, '菩萨蛮', '赵彦端', '雨声不断垂檐竹。\n清歌唤起清眠熟。\n洞户有馀花。\n同倾细细霞。\n酒行如过雨。\n雨尽风吹去。\n吹去复盈杯。\n一春能几回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9155, '菩萨蛮', '赵彦端', '绣罗裙上双鸳带。\n年年长系春心在。\n梅子别时青。\n如今浑已成。\n美人书幅幅。\n中有连环玉。\n不是只催归。\n要情无断时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9156, '菩萨蛮', '赵彦端', '倚阑闲拈生绡扇。\n新凉庭户微风转。\n疏雨断檐声。\n淡云开晚晴。\n蔗浆寒浸齿。\n枕簟清如水。\n相忆不胜愁。\n月来帘上钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9157, '菩萨蛮', '赵彦端', '青春背我堂堂去。\n桃花乱落如红雨。\n是妾断肠时。\n芳心空自持。\n相思君助取。\n脉脉如牛女。\n天远暮江迟。\n今宵归不归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9158, '蝶恋花', '赵彦端', '堂外溪桥杨柳畔。\n满树东风，更著流莺唤。\n时节清明寒暖半。\n秦筝欲妒歌珠贯。\n一寸离肠无可断。\n旧管新收，尽记双帷卷。\n赖得今年春较晚。\n送人犹有馀红乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9159, '蝶恋花', '赵彦端', '雪里珠衣寒未动。\n雪後清寒，惊损幽帷梦。\n风撼海牛帘幕重。\n画檐冰箸如流汞。\n一穗香云佳客共。\n溜溜金槽，政尔新词送。\n酒戏诗阄忘百中。\n烛间有个人非众。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9160, '相思引・琴调', '赵彦端', '拂拂轻阴雨麴尘。\n小庭深幕堕娇云。\n好花无几，犹是洛阳春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9161, '相思引・琴调', '赵彦端', '曾蹑姑苏城上台。\n好山知有好人来。\n几回徙倚，月里暮云开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9162, '杏花天', '赵彦端', '风韶雨润催花候。\n欢春恨、年年常有。\n桃蹊杏陌相期久。\n一为东君试手。\n匆匆去、那人信否。\n襟泪渍、粉香依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9163, '杏花天', '赵彦端', '当时众里闻新曲。\n拚一醉、移舟换烛。\n清波快送仙帆幅。\n十里披烟泛玉。\n谁知度、春寒夜独。\n常记恨、花阑漏促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9164, '浣溪沙', '赵彦端', '冰练新裁月见羞。\n墨花飞作淡云浮。\n宜歌宜笑不妨秋。\n约腕半笼衫草碧，洗妆初失黛蛾愁。\n嫩凉轻暑奈风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9165, '浣溪沙', '赵彦端', '过雨园林绿渐浓。\n晚霞明处暮云重。\n小桥东畔再相逢。\n睡起未添双鬓绿，汗融微退小妆红。\n几多心事不言中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9166, '浣溪沙', '赵彦端', '菊已开时梅未通。\n似寒如暖意融融。\n情亲语妙一杯中。\n歌舞欲来须更理，林泉有乐政须同。\n好诗多味酒无功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9167, '浣溪沙', '赵彦端', '渺渺东风泛酒船。\n月华为地玉为川。\n春于红药更留连。\n云路功名方步步，草庐松竹自年年。\n他时人说二疏贤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9168, '浣溪沙', '赵彦端', '花下凭肩月下迎。\n避人私语脸霞生。\n画堂红烛意盈盈。\n病酒一春愁与睡，倚阑终日雨还晴。\n强移心绪作清明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9169, '浣溪沙', '赵彦端', '人意歌声欲度春。\n春容温暖胜於人。\n劝君一醉酒如渑。\n梅子枝头应有恨，柳花风底不堪。\n盖公堂下净无尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9170, '虞美人', '赵彦端', '烟空磴尽长松语。\n佳处遗基古。\n道人乘月又乘风。\n未用秋衣沈水、换薰笼。\n两峰千涧依稀是。\n想像诗翁醉。\n莫惊青蕊後时开。\n笑倒江南陶令、未归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9171, '虞美人', '赵彦端', '凌虚风马来无迹。\n水净山光出。\n松间孤鹤睡残更。\n唤起缑箫飞去、与云平。\n新亭聊共丰年悦。\n一醉中秋月。\n江山拟作画图临。\n乐府翻成终胜、写无声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9172, '虞美人', '赵彦端', '兰畦梅迳香云绕。\n长恨相从少。\n相从虽少却情亲。\n不道相从频後、是行人。\n行人未去犹清瘦。\n想见相分後。\n书来梅子定尝新。\n记取江东日暮、雨还云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9173, '南乡子', '赵彦端', '风露晚珊珊。\n洛下湘中接佩环。\n急把一杯相劳苦，云端。\n只恐冰肌亦自寒。\n二客共阑干。\n潋潋鲸波吸未乾。\n待得月华移十丈，乘欢。\n更上层楼极处看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9174, '南乡子', '赵彦端', '浓绿暗芳洲。\n春事都随芍药休。\n风雨只贪梅子熟，飕飕。\n却送行人一夜秋。\n新月幸如钩。\n三五还催玉鉴浮。\n一段离愁溪样远，悠悠。\n只是溪流浅似愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9175, '南乡子', '赵彦端', '窗户映朝光。\n花气浑如百和香。\n即遣花飞深造次，茫茫。\n曲渚飘成锦一张。\n相忆莫相忘。\n并蒂芙蓉本自双。\n草色连云人去住，堪伤。\n海上尖峰似剑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9176, '画堂春', '赵彦端', '倡条繁蒂绿层层。\n解衫扶醉同登。\n暝云无树亦。\n红袖深凭。\n病思去春饶睡，醉魂因酒思冰。\n夜凉星斗挂修甍。\n歌尽香凝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9177, '画堂春', '赵彦端', '满城风雨近重阳。\n夹衫清润生香。\n好辞赓尽楚天长。\n唤得花黄。\n客胜不知门陋，酒新如趁春狂。\n故人相见等相忘。\n一语千觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9178, '滴滴金', '赵彦端', '澄溪暝度轻澌白。\n对平湖、澹烟隔。\n我与征鸿共行人，更张灯留客。\n东园半是馀花迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9179, '青玉案', '赵彦端', '当年万里龙沙路。\n载多少、离愁去。\n冷压层帘云不度。\n芙蓉双带，垂杨娇髻，弦索初调处。\n花凝玉立东风暮。\n曾记江边丽人句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9180, '沙塞子', '赵彦端', '春水绿波南浦。\n渐理棹、行人欲去。\n黯消魂、柳上轻烟，花梢微雨。\n长亭放无计住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9181, '临江仙', '赵彦端', '忆著旧山归去乐，松筠岁晚参天。\n老来慵似柳三眠。\n从教官府冷，甘作地行仙。\n青琐紫微追昨梦，扁舟已具犹怜。\n有情如酒月如川。\n为君忘饮病，更拟索茶煎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9182, '临江仙', '赵彦端', '潦水似讥酒浅，秋云如妒蟾明。\n幽人闻雁若闻莺。\n更长端有意，菊晚近无情。\n诗学笑中偷换，烛花醉里频倾。\n罗衣迥立可怜生。\n五湖虽好在，客意欲登瀛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9183, '鹧鸪天', '赵彦端', '天外秋云四散飞。\n波间风艇一时归。\n他年淮水东边月，犹为登临替落晖。\n夸客胜，数星稀。\n晚寒拂拂动秋衣。\n酒行不尽清光意，输与渔舟睡钓矶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9184, '鹧鸪天', '赵彦端', '渺渺东风拂画船。\n不堪临雨落花前。\n清歌只拟留春住，好语频闻有诏传。\n秦望月，镜湖天。\n养成英气自当年。\n两山总是经行处，献纳雍容定几篇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9185, '鹧鸪天', '赵彦端', '忆醉君家倚翠屏。\n年年相喜鬓毛青。\n谁知缓步从天下，犹许清弹此地听。\n挥羽扇，写鹅经。\n使星何似老人星。\n几时一试薰风手，今日桐阴又满庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9186, '鹧鸪天', '赵彦端', '拂拂深帏起暗尘。\n清歌缓响自回春。\n月知灯市云间堕，人对梅花雪後新。\n杯掌露，舞衣云。\n酒慵微觉翠鬟倾。\n洞房不压阳台雨，乞与游人弄晚晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9187, '清平乐', '赵彦端', '新寒一段。\n变尽人间暖。\n说与群花花不管。\n只有江梅情乱。\n江梅也似山人。\n山人到老梅亲。\n斗薮衣冠气象，百般归去精神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9188, '清平乐', '赵彦端', '桃根桃叶。\n一树芳相接。\n春到江南三二月。\n迷损东家蝴蝶。\n殷勤踏取青阳。\n风前花正低昂。\n与我同心栀子，报君百结丁香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9189, '眼儿媚', '赵彦端', '侬家风物似山家。\n梅老鬓丝华。\n几回记得，攀翻琪树，醉帽斜。\n冷香不断春千里，归路本非赊。\n有人却道，使君犹健，看遍馀花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9190, '永遇乐', '赵彦端', '杜曲桑麻，灞桥风雪，归梦无路。\n马健凌秋，人间玩日，聊用宽迟暮。\n摇摇羽扇，翩翩凫，胜处恍疑仙去。\n笑相看，风林露草，古来有谁知趣。\n黄公垆下，山阴亭畔，岁月著鞭如骛。\n出塞功名，入关游说，纸上俱难据。\n论诗说剑，尊前风味，天巧却容人觑。\n问少陵，酣歌拓戟，为谁献赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9191, '诉衷情', '赵彦端', '洗妆舞傍清尊。\n霏雨澹黄昏。\n殷勤与花为地，烧烛助微温。\n松半岭，竹当门。\n意如村。\n明朝酒醒，桃李漫山，心事谁论。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9192, '诉衷情', '赵彦端', '江梅初试两三花。\n人意竞年华。\n春工未敢轻放，深院拥吴娃。\n翻酒戏，醉人家。\n旧生涯。\n而今且趁，便面斜阳，莫照红纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9193, '千秋岁', '赵彦端', '杏花风下。\n独立春寒夜。\n微雨度，疏星挂。\n晖晖浓艳出，袅袅繁枝亚。\n朱槛倚，轻罗醉里添还卸。\n寂寞情犹乍。\n怅望骖鸾驾。\n衣褪玉，香欺麝。\n一花拚一醉，杯重凭谁把。\n春去也，重帘翠幕人如画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9194, '风入松', '赵彦端', '传闻天上有星榆。\n历历谁居。\n淡烟暮拥红云暖，春寒乍有还无。\n作态似深又浅，多情要密还疏。\n移尊环坐足相娱。\n醉影凭扶。\n江南归到虽怜晚，犹胜不见踟躇。\n尽拚绿阴青子，凭肩携手如初。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9195, '茶瓶儿', '赵彦端', '澹月华灯春夜。\n送东风、柳烟梅麝。\n宝钗宫髻连娇马。\n似记得、帝乡游冶。\n悦亲戚之情话。\n况溪山、坐中如画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9196, '祝英台・祝英台近', '赵彦端', '兽金寒，帘玉润，梅雪印苔絮。\n春意如人，易散苦难聚。\n几多丝竹深情，池塘幽梦，犹倚赖、与君同住。\n旧游处。\n谁唤别浦仙帆，风前问征路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9197, '五彩结同心', '赵彦端', '人间尘断，雨处风回，凉波自泛仙槎。\n非郭还非野，闲莺燕、时傍笑语清佳。\n铜壶花漏长如线，金铺碎、香暖檐牙。\n谁知道、东园五亩，种成国艳天葩。\n主人汉家龙种，正翩翩迥立，雪乌纱。\n歌舞承平旧，围红袖、诗兴自写春华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9198, '瑞鹧鸪', '赵彦端', '芙蓉池馆一重重。\n留得黄花寿中。\n春到小春如有信，月临良月正相同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9199, '月中桂', '赵彦端', '露醑无情，送长歌未终，已醉离别。\n何如暮雨，酿一襟凉润，来留佳客。\n好山侵座碧。\n胜作夜、疏星淡月。\n君欲翩然去，人间底许，员峤问帆席。\n诗情酒病非畴昔。\n赖亲朋对影，且慰良夕。\n风流雨散，定几回肠断，能禁头白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9200, '满庭芳', '赵彦端', '云暖萍漪，雨香兰迳，西湖二月初时。\n两山十里，锦绣照金羁。\n柳外阑干相望，弄东风、倚遍斜晖。\n朋游好，乱红堆里，一饮百篇诗。\n三年，江上梦，青衫风日，白尘泥。\n听几声黄鸟，粤树闽溪。\n长是春朝多病，今年更、添得相思。\n须归去，倦游滋味，犹有个人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9201, '水龙吟', '赵彦端', '春溪漠漠如空，望中只与新愁去。\n何知尚有，烟间馀怨，洛津闲赋。\n已瘦难丰，久离重见，好春如许。\n念海棠未老，荼シ欲吐。\n且莫恨、风兼雨。\n休问无情水驿，载幽怀、小桡轻橹。\n君看睡起，平阶柳絮，入门花雾。\n才尽无奇，客残如扫，一尊谁举。\n怅行云断後，祗应梦里，有澄江句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9202, '如梦令', '赵彦端', '鸳瓦初凝霜粟。\n冰笋旋裁春玉。\n巧思化东风，唤省蕊红枝绿。\n清淑。\n清淑。\n会有蜂栖蝶宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9203, '如梦令', '赵彦端', '嫩柳眉梢轻蹙。\n细草烟凝堪掬。\n争似小桃，酒入香肌红玉。\n清馥。\n清馥。\n不觉花阑漏促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9204, '蕊珠闲', '赵彦端', '浦云融，梅风断，碧水无情轻度。\n有娇黄上林梢，向春欲舞。\n绿烟迷昼，浅寒欺暮。\n不胜小楼凝伫。\n倦游处。\n故人相见易阻。\n花事从今堪数。\n片帆无恙，好在一篙新雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9205, '念奴娇', '赵彦端', '雨斜风横，正诗人闲倦，淮山清绝。\n弹压秋光江万顷，只欠凌波罗袜。\n好事幽人，怜予止酒，著意温琼雪。\n翠帷低卷，怪来飞堕初月。\n凉夜华字无尘，舞裙香渐暖，锦茵声阕。\n不分金莲随步步，谁遣芙蓉争发。\n赖得高情，湘歌洛赋，称作西风客。\n为君留住，不然飘去云阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9206, '忆少年', '赵彦端', '逢春如酒，逢花如露，逢人如玉。\n东风送寒去，蔚温温香。\n海上三山元似粟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9207, '思佳客令・思佳客', '赵彦端', '天似水。\n秋到芙蓉如乱绮。\n芙蓉意与黄花倚。\n历历黄花矜酒美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9208, '惜分飞', '赵彦端', '相与十年亲且旧。\n一笑天涯携手。\n霜际寒云逗。\n去年情味君思否。\n远水无情冰不就。\n好在尊前眉岫。\n肠断东南秀。\n淡烟疏月梅时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9209, '绛都春', '赵彦端', '平生相遇。\n算未有、笑语闽山佳处。\n旧日文章，如今风味浑如许。\n眼前都是蓬莱路。\n但莫道、有人曾住。\n异时天上，种种风流，待君如故。\n此自君家旧物，看九万清风，为君掀举。\n举上青云，却忆梅花如旧否。\n故人衰病今无绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9210, '小重山', '赵彦端', '春日归来如许长。\n不知偿此意，几何觞。\n老人临酒兴犹狂。\n溪山主，终不道山王。\n一雨罢耕桑。\n平生欢喜处，是吾乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9211, '隔浦莲・隔浦莲近拍', '赵彦端', '西风吹断梦草。\n来度芙蓉老。\n座上人谁在，晨参疏影相照。\n幽馆寒意早。\n檐声小。\n醉语秋屏晓。\n记年少。\n相携胜处，黄花香满乌帽。\n如今将见，璧月琼枝空好。\n准拟新歌待见了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9212, '贺圣朝', '赵彦端', '一江风月同君住。\n了不知秋去。\n赏心亭下，过帆如马，堕枫如雨。\n相将莫问，兴亡旧事，举离觞谁诉。\n垂杨指点，但归来、有温柔佳处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9213, '念奴娇', '赵彦端', '棠阴绿遍，正金菊芙蓉，争放时节。\n满路歌谣民五裤，底事逢车催发。\n结彩成门，攀辕卧辙，何计留连得。\n故园花柳，尽成憔悴难说。\n今夜祖席邮亭，主人来日，已是朝天客。\n旌旆匆匆从此去，□赏□湖风月。\n眷恋无因，笑啼不敢，那忍伤轻别。\n清□难驻，一杯聊送行色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9214, '点绛唇', '赵彦端', '憔悴天涯，故人相遇情如故。\n别离何遽。\n忍唱阳关句。\n我是行人，更送行人去。\n愁无据。\n寒蝉鸣处。\n回首斜阳暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9215, '转调踏莎行・踏莎行', '赵彦端', '宿雨才收，馀寒尚力。\n牡丹将绽也、近寒食。\n人间好景，算仙家也惜。\n因循尽扫断、蓬莱迹。\n旧日天涯，如今咫尺。\n一月五番价、共欢集。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9216, '瑞鹤仙', '赵彦端', '气佳哉寿域。\n正晓松呈翠，早梅施白。\n良辰值良月。\n看景星朝睹，洗空霜洁。\n珍图瑞牒。\n仰天心、锺在俊杰。\n向人间，化作如膏甘雨，莫放春歇。\n堪忆。\n三吴乐事，画戟凝香，舞衣回雪。\n风流胜绝。\n尊中酒，坐中客。\n问今年何事，骑鲸南去，久矣湘枫下叶。\n早归来，应取千龄，凤池旧列。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9217, '看花回', '赵彦端', '端有恨，留春无计，花飞何速。\n槛外青青翠竹。\n镇高节凌云，清阴常足。\n春寒风袂，带雨穿窗如利镞。\n催处处、燕巧莺慵，几声钩叫云木。\n看波面、垂杨蘸绿。\n最好是、风梳烟沐。\n阴重熏帘未卷，正泛乳新芽，香飘清馥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9218, '好事近', '赵彦端', '一沮寄江干，十载山青水碧。\n山水大无馀意，有故情难识。\n故情难识有谁知，衣残更头白。\n别後是人安稳，只楚吴行客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9219, '贺圣朝', '赵彦端', '河阳桃李开无数。\n待成春归去。\n小园几月忽惊飞，恨主人难驻。\n雏莺乳燕愁悲语。\n道留君不住。\n愿君随处作东风，与群花为主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9220, '浣沙溪・浣溪沙', '赵彦端', '花县双凫缥缈仙。\n家庭椿树正苍然。\n斑衣举酒大人前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9221, '浣沙溪・浣溪沙', '赵彦端', '水到桐江镜样清。\n有人还似水清明。\n尊前无语更盈盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9222, '菩萨蛮', '赵彦端', '佩环解处妆初了。\n翠娥玉面金钿小。\n萼绿本仙家。\n天香谁似他。\n芳心真耐久。\n度月长相守。\n岁晚未能忘。\n相期云水乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9223, '眼儿媚', '赵彦端', '黄昏小宴史君家。\n梅粉试春华。\n暗香素蕊，横枝疏影，月淡风斜。\n更饶红烛枝头挂，粉蜡斗香奢。\n元宵近也，小园先试，火树银花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9224, '江城子', '赵彦端', '春风旗鼓石头城。\n急麾兵。\n斩长鲸。\n缓带轻裘，乘胜讨蛮荆。\n蚁聚蜂屯三十万，争面缚，向行营。\n舳舻千里大江横。\n凯歌声。\n犬羊惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9225, '西江月', '赵彦端', '捣玉扬珠万户，眉高髻千峰。\n佳辰请寿黑头公。\n老稚扶携欢动。\n借问优游黄绮，何如强健夔龙。\n觥船一棹百分空。\n浇泼胸中云梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9226, '千秋岁', '赵彦端', '柏舟高躅。\n晚岁宜遐福。\n门户壮，疏汤沐。\n青袍围白发，瑞锦缠犀轴。\n仙桂长，交柯却映蟠桃熟。\n缥缈长生曲。\n入破笙箫逐。\n香雾薄，菲华屋。\n玉钩凉月挂，水麝秋蕖馥。\n千万寿，酒中倒卧南山绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9227, '虞美人', '赵彦端', '断蝉高柳斜阳处。\n池阁丝丝雨。\n绿檀珍簟卷猩红。\n屈曲杏花蝴蝶、小屏风。\n春山叠叠秋波慢。\n收拾残针线。\n又成娇困倚檀郎。\n无事更抛莲子、打鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9228, '虞美人', '赵彦端', '疏梅淡月年年好。\n春意今年早。\n迎长时节近佳辰。\n看取衮衣黄发、画麒麟。\n酒中倒卧南山绿。\n起舞人如玉。\n风流椿树可怜生。\n长与柳枝桃叶、共青青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9229, '瑞鹧鸪', '赵彦端', '榴花五月眼边明。\n角簟流冰午梦清。\n江上扁舟停画桨，云间一笑濯尘缨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9230, '豆叶黄・忆王孙', '赵彦端', '粉墙丹柱柳丝中。\n帘箔轻明花影重。\n午醉醒来一面风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9231, '念奴娇', '赵彦端', '娥万古，算清光常共、水清山绿。\n我欲蓬莱风露顶，眇视寰瀛一粟。\n携手群仙，广寒游戏，玉砌琉璃屋。\n归来一笑，葛陂还访骑竹。\n此夕纵饮清欢，吸寒辉万丈、快如飞瀑。\n倾倒银河斟斗杓，莫问人间荣辱。\n独倚阑干，浩歌长啸，惊堕云飞鹄。\n乱呼蟾兔，捣霜为驻颜玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9232, '水调歌头', '赵彦端', '山色望中好，□□□□清。\n连峰叠极目，高下与云平。\n玉洞沈沈何处。\n隐映一溪烟树。\n倒影碧波□。\n唤起骖鸾客，丹灶夜光横。\n□霞卷，风露滴，月华明。\n佳人为我，垂手凄怨理秦筝。\n千载虹桥新路。\n依约幔亭歌舞。\n一醉话浮生。\n但得尊盈酒，莫问世间名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9233, '清平乐', '赵彦端', '悠悠漾漾。\n做尽轻模样。\n昨夜潇潇窗外响。\n多在梅梢柳上。\n画楼拂晓帘开。\n六花一片飞来。\n却被金炉香雾，腾腾扶上琼钗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9234, '临江仙', '赵彦端', '十载长安桃李梦，年来镜净尘空。\n忽传彩笔小笺红。\n满怀秋思，倾倒为芙蓉。\n莫恨霜浓开较晚，尊前元有春风。\n酣娇肯为别人容。\n试携银烛，斜照绿波中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9235, '鹧鸪天', '赵彦端', '一□青春正及笄。\n蕊珠仙子下瑶池。\n箫吹弄玉登楼月，弦拨昭君未嫁时。\n云体态，柳腰肢。\n绮罗活计强相随。\n天教谪入群花苑，占得东风第一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9236, '鹧鸪天', '赵彦端', '花动仪容玉润颜。\n温柔袅娜趁清闲。\n盈盈醉眼横秋水，淡淡蛾眉抹远山。\n膏雨霁，晓风寒。\n一枝红杏拆朱阑。\n天台迥失刘郎路，因忆前缘到世间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9237, '鹧鸪天', '赵彦端', '月□金□□□□。\n素娥何事下天衢。\n翩翩舞袖穿花蝶，宛转歌喉贯索珠。\n帘翡翠，枕珊瑚。\n锦衾冰簟象床铺。\n春光九十羊城景，百紫千红总不如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9238, '鹧鸪天', '赵彦端', '云暗青丝玉莹冠。\n笑生百媚入眉端。\n春深芍药和烟拆，秋晓芙蓉破露看。\n星眼俊，月眉弯。\n舞狂花影上栏干。\n醉来直驾仙鸾去，不到银河到广寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9239, '鹧鸪天', '赵彦端', '醉拈花枝舞翠翘。\n十分春色赋妖娆。\n千金笑里争檀板，一搦纤围间舞腰。\n行也媚，坐也娇。\n乍离银阙下青霄。\n檀郎若问芳笄记，二月和风弄柳条。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9240, '鹧鸪天', '赵彦端', '梅粉新妆间玉容。\n寿阳人在水晶宫。\n浴残雨洗梨花白，舞转风摇菡萏红。\n云枕席，月帘栊。\n金炉香喷凤帏中。\n凡材纵有凌云格，肯学文君一旦从。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9241, '鹧鸪天', '赵彦端', '绰约娇波二八春。\n几时飘谪下红尘。\n桃源寂寂啼春鸟，蓬岛沈沈销暮云。\n丹脸嫩，黛眉新。\n肯将朱粉污天真。\n杨妃不似才卿貌，也得君王宠爱勤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9242, '鹧鸪天', '赵彦端', '未有年光好破瓜。\n绿珠娇小翠鬟丫。\n清肌莹骨能香玉，艳质英姿解语花。\n钗插凤，鬓堆鸦。\n舞腰春柳受风斜。\n有时马上人争看，擘破红窗新绛纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9243, '鹧鸪天', '赵彦端', '两两青螺绾额傍。\n彩云齐会下巫阳。\n俱飞蛱蝶尤相逐，并蒂芙蓉本自双。\n翻彩袖，舞霓裳。\n点风飞絮恣轻狂。\n花神只恐留难住，早晚承恩入未央。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9244, '鹧鸪天', '赵彦端', '一簇神仙会见奇。\n誓夸苏小与西施。\n怜轻镂月为歌扇，喜薄裁云作舞衣。\n牙板脆，玉音齐。\n落霞天外雁行低。\n看看各得风流侣，回首乘鸾旧路归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9245, '桃源忆故人', '赵彦端', '修檐堕玉欺窗竹。\n独坐冷云堆屋。\n此味与谁同宿。\n几寸东斋烛。\n烟鬟雾鬓春山曲。\n好梦浅愁相续。\n那慰沈腰如束。\n歌意灯前足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9246, '生查子', '赵彦端', '翻翻别袖风，醉眼迷残日。\n春色荡人魂，杨柳浑无力。\n不知长短亭，何处逢寒食。\n多少向来情，门掩梨花夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9247, '卜算子', '赵彦端', '脉脉万重心，相望何时见。\n强半春寒去却来，野水差新燕。\n远负白头吟，坐惜红颜变。\n欲问平安无使来，日落庭花转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9248, '生查子', '赵彦端', '新月曲如眉，未有团圆意。\n红豆不堪看，满眼相思泪。\n终日擘桃穰，人在心儿里。\n两朵隔墙花，早晚成连理。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9249, '贺新郎', '王千秋', '吊古城头去。\n正高秋、霜晴木落，路通洲渚。\n欲问紫髯分鼎事，只有荒祠烟树。\n巫觋去、久无箫鼓。\n霸业荒凉遗堞坠，但苍崖、日阅征帆渡。\n兴与废，几今古。\n夕阳细草空凝伫。\n试追思、当时子敬，用心良误。\n要约刘郎铜雀醉，底事遽争荆楚。\n遂但见、吴蜀烽举。\n致使五官伸脚睡，唤诸儿、昼取长陵土。\n遗此恨，欲谁语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9250, '沁园春', '王千秋', '豆蔻娇春，烟花羞暖，物华渐嘉。\n也不须莺怨，桃封绛萼，也不须蜂恨，兰郁金芽。\n料是东君，都将和气，分付清丰诗礼家。\n充闾庆，有青毡事业，丹凤才华。\n乘槎。\n早上云霞。\n侍祠甘泉瞻羽车。\n试笑凭熊轼，嘉禾合穗，进思鱼钥，菡萏骈花。\n萧寇勋名，龚黄模样，入拜行趋堤上沙。\n今宵里，且觥船满棹，醉帽斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9251, '风流子', '王千秋', '夜久烛花暗，仙翁醉、丰颊缕红霞。\n正三行钿袖，一声金缕，卷茵停舞，侧火分茶。\n笑盈盈，溅汤温翠碗，折印启缃纱。\n玉笋缓摇，云头初起，竹龙停战，雨脚微斜。\n清风生两腋，尘埃尽，留白雪、长黄芽。\n解使芝眉长秀，潘鬓休华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9252, '醉蓬莱', '王千秋', '正歌尘惊夜，斗乳回甘，暂醒还醉。\n再煮银瓶，试长松风味。\n玉手磨香，镂金檀舞，在寿星光里。\n翠袖微揎，冰瓷对捧，神仙标致。\n记得拈时，吉祥曾许，一饮须教，百年千岁。\n况有阴功在，遍江东桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9253, '西江月', '王千秋', '心事几多白发，客情无数青山。\n廉纤细雨褪馀寒。\n正是花期酒限。\n一自瓶簪信杳，空留钿带香残。\n我今多病寄江干。\n瘦似东阳也惯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9254, '西江月', '王千秋', '老去频惊节物，乱来依旧江山。\n清明雨过杏花寒。\n红紫芳菲何限。\n春病无人消遣，芳心有酒摧残。\n此情拍手问阑干。\n为甚多愁我惯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9255, '南歌子', '王千秋', '鹊起惊红雨，潮生涨碧澜。\n水晶城馆月方圆。\n谁唤骑鲸仙伯、下三山。\n笔势翔鸾媚，词锋射斗寒。\n向来文价重贤关。\n便合批风支月、紫薇间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9256, '虞美人', '王千秋', '流苏斗帐泥金额。\n我亦花前客。\n谪仙标韵胜琼枝。\n一咏一觞、常是得追随。\n自从风借云帆便。\n冷落青楼宴。\n石桥风月也应猜。\n过尽中秋、不见晚归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9257, '念奴娇', '王千秋', '扁舟东下，正岁华将晚，江湖清绝。\n万点寒鸦高下舞，凝住一天云叶。\n映筱渔村，衡茅酒舍，淅沥鸣飞雪。\n壮怀兴感，悔将钗凤轻别。\n遥望杰阁层楼，明眸艳，许把同心结。\n东畎西倾浑未定，终恐前盟虚设。\n兽炉温，分霞酒满，此夕欢应狎。\n多情言语，又还知共谁说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9258, '青玉案', '王千秋', '雪堂不远临皋路。\n怅仙伯、骑鲸去。\n燕麦桃花更几度。\n横桥虽在，种松无有，谁是关心处。\n解鞍君到冬虽暮。\n传语无忘晒蓑句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9259, '水调歌头', '王千秋', '迟日江山好，老去倦遨游。\n好天良夜，自恨无地可销忧。\n岂意绮窗朱户，深锁双双玉树，桃扇避风流。\n未暇泛沧海，直欲老温柔。\n解檀槽，敲玉钏，泛清讴。\n画楼十二，梁尘惊坠彩云留。\n座上骑鲸仙友，笑我胸中磊，取酒为浇愁。\n一举千觞尽，来日判扶头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9260, '减字木兰花', '王千秋', '阴檐雪在。\n小雨廉纤寒又。\n莫上危楼。\n楼迥空低雁更愁。\n一杯浊酒。\n万事世间无不有。\n待早归田。\n欲买田无使鬼钱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9261, '风流子', '王千秋', '同云垂六幕，啼乌静、风御玉妃寒。\n渐声入钓蓑，色侵书幌，似花如絮，结阵成团。\n倦游客，一番诗思苦，无算酒肠宽。\n黄竹调悲，绮衾人马，岂堪梅蕊，索笑巡檐。\n一杯知谁劝，空搔首、远是忆旧青毡。\n问素娥早晚，光射江干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9262, '忆秦娥', '王千秋', '云破碧。\n作霜天气西风急。\n西风急。\n一行征雁，数声横笛。\n挑灯试问今何夕。\n柔肠底事愁如织。\n愁如织。\n紫苔庭院，悄无人迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9263, '忆秦娥', '王千秋', '云叶舞。\n寒林浅淡围烟雨。\n围烟雨。\n三三两两，雁投沙渚。\n征帆暂落知何所。\n短篷静听舟人语。\n舟人语。\n夜寒如许，客能眠否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9264, '清平乐', '王千秋', '吹花何处。\n桃叶江头路。\n碧锦障泥冲暮雨。\n一霎峭寒如许。\n归来索酒浇春。\n潮红秋水增明。\n却自不禁春恼，偎人低度歌声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9265, '贺新郎', '王千秋', '短艇横烟渚。\n梦惊回、凄凉尚记，缘蓑鸣雨。\n拍塞愁怀人不解，只有黄鹂能语。\n复拟待、乘槎重去。\n无奈东君刚留客，张碧油、缓按香红舞。\n生怕我，顿遐举。\n故溪冉冉春光度。\n想晚来、杨花云际，白苹无数。\n竹里樵青应是怪，目断鸣榔去路。\n料为我、羞烦鳞羽。\n好趁小蛮针线在，按纶巾、归唤松江渡。\n重系缆，醉眠处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9266, '好事近', '王千秋', '六幕冻云凝，谁翦玉花为雪。\n寒入竹窗茅舍，听琴弦声绝。\n从他拂面去寻梅，香吐是时节。\n归晚楚天不夜，抹墙腰横日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9267, '好事近', '王千秋', '明日发骊驹，共起为传杯绿。\n十岁女儿娇小，倚琵琵翻曲。\n绝怜啄木欲飞时，弦响颤鸣玉。\n虽是未知离恨，亦晴峰微蹙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9268, '虞美人', '王千秋', '琵琵弦畔春风面。\n曾向尊前见。\n彩云初散燕空楼。\n萧寺相逢各认、两眉愁。\n旧时曲谱曾翻否。\n好在曹纲手。\n老来心绪怯么弦。\n出塞移船莫遣、到愁边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9269, '水调歌头', '王千秋', '壮日遇重九，跃马□欢游。\n如今何事多感，双鬓不禁秋。\n目断五陵台路，无复临高千骑，鼓吹簇轻裘。\n霜露下南国，淮汉绕神州。\n钓松鲈，斟郢酒，听吴讴。\n壮心铄尽，今夕重见紫茱羞。\n月落笳鸣沙碛，烽静人耕榆塞，此志恐悠悠。\n拟欲堕清泪，生怕菊花愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9270, '菩萨蛮', '王千秋', '流莺不许青春住。\n催得春归花亦去。\n何物慰侬怀。\n荼シ最後开。\n青衫冰雪面。\n细雨斜桥见。\n莫浪送香来。\n等闲蜂蝶猜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9271, '蓦山溪', '王千秋', '清明池馆。\n侧卧帘初卷。\n还是海棠开，睡未足、馀酲满面。\n低头不语，浑似怨东风，心始吐，又惊飞，交现垂杨眼。\n少陵情浅。\n花草题评遍。\n赋得恶因缘，没一字、聊通缱绻。\n黄昏时候，凝伫怯春寒，笼翠袖，减丰肌，脉脉情何限。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9272, '渔家傲', '王千秋', '黄栗留鸣春已暮。\n西园无著清阴处。\n昨日骤寒风又雨。\n花良苦。\n信缘吹落谁家去。\n病起日长无意绪。\n等闲还与春相负。\n魏紫姚黄无恙否。\n栽培取。\n开时我欲听金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9273, '念奴娇', '王千秋', '开花借水，信天姿高胜，都无俗格。\n玉陇娟娟黄点小，依约西湖清魄。\n绿带垂腰，碧簪髻，索句撩元白。\n西清微笑，为渠模写香色。\n常记月底风前，水沈肌骨，瘦不禁怜惜。\n生怕因循纷委地，仙去难寻踪迹。\n缥槛深栽，彤帏密护，不肯轻抛释。\n等差休问，未容梅品悬隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9274, '生查子', '王千秋', '枝垂云碧长，心展鹅黄嫩。\n无力倚阑时，扫尽漫山杏。\n玲珑影结阴，蕴藉香成阵。\n谁为祝东风，更莫催花信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9275, '生查子', '王千秋', '花飞锦绣香，茗碾枪旗嫩。\n是处绿连云，又摘斑斑杏。\n愁来苦酒肠，老去闲花阵。\n燕子不知人，尚说行云信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9276, '生查子', '王千秋', '莺声恰恰娇，草色纤纤嫩。\n诗鬓已惊霜，镜叶慵拈杏。\n因何积恨山，著底攻愁阵。\n春事到荼シ，还是无音信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9277, '生查子', '王千秋', '睡起髻云松，枕印香腮嫩。\n愁思到眉尖，齿软尝新杏。\n都无鱼雁书，又过莺花阵。\n宽尽缕金衣，说与伊争信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9278, '生查子', '王千秋', '春江波面浑，春岸芦芽嫩。\n不见木兰舟，羞带骈枝杏。\n轻绡泪痕，急雨冲花阵。\n暗祷紫姑神，觅个巴陵信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9279, '生查子', '王千秋', '雄姿画麒麟，朽骨分蝼蚁。\n争似及生前，常为莺花醉。\n云山静有情，天地宽无际。\n且放两眉开，万事非人意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9280, '生查子', '王千秋', '功名竹上鱼，富贵槐根蚁。\n三万六千场，排日扶头醉。\n高怀隘世间，壮气横天际。\n常是惜春残，不会东君意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9281, '解佩令', '王千秋', '花儿不大，叶儿不美。\n只一段、风流标致。\n淡淡梳妆，已赛过、骚人兰芷。\n古龙涎、怎敢□气。\n开时无奈，风斜雨细。\n坏得来、零零碎碎。\n著意收拾，安顿在、胆瓶儿里。\n且图教梦魂旖旎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9282, '清平乐', '王千秋', '唤云且住。\n莫作龙池舞。\n五月人间须好雨。\n为扫无边烦暑。\n畦秧针绿重生。\n壶天表里俱清。\n林外桔槔闲挂，省渠多少心情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9283, '忆秦娥', '王千秋', '阑干侧。\n当时我亦凝香客。\n凝香客。\n而今老大，鬓苍头白。\n扬州梦觉浑无迹。\n旧游英俊今南北。\n今南北。\n断鸿沈鲤，更无消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9284, '西江月', '王千秋', '梦幻影泡有限，风花雪月无涯。\n莫分粗俗与精华。\n日醉石间松下。\n菜尽邻家解与，杯空稚子能赊。\n通幽即步尽横斜。\n不问墩犹姓谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9285, '临江仙', '王千秋', '者也之乎真太错，甘心吞棘吞蓬。\n有无俱尽见真空。\n炉锥难自荐，关捩只心通。\n野鹤孤云元自在。\n刚论隐豹冥鸿。\n此身今在幻人宫。\n要将驴佛我，分付马牛风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9286, '浣溪沙', '王千秋', '玉偎香倚翠屏。\n当年常唤在凝春。\n岂知云雨散逡巡。\n不止恨伊唯准拟，也先伤我太因循。\n而今头过总休论。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9287, '浣溪沙', '王千秋', '亲染柔毛擘彩笺。\n自怜探得恶因缘。\n一尊重许笑凭肩。\n往事已同花屡褪，新欢闻似月常圆。\n休休休更苦萦牵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9288, '瑞鹤仙', '王千秋', '征鸿翻塞影。\n怅悲秋人老，浑无佳兴。\n鸣蛩问酒病。\n更堆积愁肠，摧残诗鬓。\n起寻芳径。\n菊羞人、依丛半隐。\n又岂知、虚度重阳，浪阔渺无归恨。\n无定。\n登高人远、戏马台闲，怨歌谁听。\n香肩醉凭。\n镇常是、笑得醒。\n到如今何在，西风凝伫，冠也无人为正。\n看他门、对插茱萸，恨长怨永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9289, '瑞鹤仙', '王千秋', '红消梅雨润。\n正榴花照眼，荷香成阵。\n炉薰炷芳烬。\n记于门今日，长庚占庆。\n文艳锦。\n笑班扬、用字未稳。\n果青云、快上黄扉，地□誉高英俊。\n名盛。\n都期持橐，却借乘轺，布宣宽政。\n除书已进。\n归宠异，侍严近。\n且金船满酌，云翘低祝，□此椿龄更永。\n任月斜、未放笙歌，翠桐转影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9290, '满江红', '王千秋', '楼压层城，斜阳敛、帆收南浦。\n最好是、长江澄练，远山新雨。\n□□留连邀皓月，一堂高敞祛隆暑。\n问从来、佳赏有谁同，应难数。\n舟横渡，车阗路。\n催酒进，麾灯去。\n放娥照座，不烦帘阻。\n已见天清无屏翳，更须潮上喧阗鼓。\n看波光、撩乱上樯竿，龙蛇舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9291, '感皇恩', '王千秋', '天气过烧灯，初闲人倦。\n晓色绣帘卷。\n聚星歌扇，一簇雪香琼软。\n寿杯争要把，从他满。\n低低笑祝，年龄遐远。\n息驾无由遂公愿。\n东风吹喜，又做眉黄一点。\n便参鹭入，常朝殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9292, '青玉案', '王千秋', '鸣鼍欲引鱼龙戏。\n先自作、长江擂。\n头管一声天外起。\n群仙俱上，有人殊丽。\n认得分明是。\n欲相问劳来无计。\n但隔炉烟屡凝睇。\n掷我胸前方寸纸。\n拥翘欲去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9293, '醉落魄・一斛珠', '王千秋', '惊鸥扑蔌。\n萧萧卧听鸣幽屋。\n窗明怪得鸡啼速。\n墙角烂斑，一半露松绿。\n歌楼管竹谁翻曲。\n丹唇冰面喷馀馥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9294, '桃源忆故人', '王千秋', '移灯背月穿金缕。\n合色鞋儿初做。\n却被阿谁将去。\n鹦鹉能言语。\n朝来半作凌波步。\n可惜孤鸾□侣。\n若念玉纤辛苦。\n早与成双取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9295, '水调歌头', '王千秋', '披锦泛江客，横槊赋诗人。\n气吞宇宙，当拥千骑静胡尘。\n何事折腰执版，久在泛莲幕府，深觉负平生。\n踉众人底，欲语复吞声。\n庆垂弧，期赐杖，酒深倾。\n愿君大耐，碧眸丹颊百千龄。\n用即经纶天下，不用归谋三径，一笑友渊明。\n出处两俱得，亦鹏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9296, '鹧鸪天', '王千秋', '翠勺银锅飨夜游。\n万灯初上月当楼。\n溶溶琥珀流匙滑，璨璨珠著面浮。\n香入手，暖生瓯。\n依然京国旧风流。\n翠娥且放杯行缓，甘味虽浓欲少留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9297, '鹧鸪天', '王千秋', '比屋烧灯作好春。\n先须歌舞赛蚕神。\n便将簇上如霜样，来饷尊前似玉人。\n丝馅细，粉肌匀。\n从它犀箸破花纹。\n殷勤又作梅羹送，酒力消除笑语新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9298, '浣溪沙', '王千秋', '买市宣和预赏时。\n流苏垂盖宝灯围。\n小铛烹玉鼓声随。\n金弹玲珑今夕是，鳌山缥缈昔游非。\n马行遗老想沾衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9299, '浣溪沙', '王千秋', '灯火阑珊欲晓时。\n夜游人倦总思归。\n更须冰蛹替丝。\n玉篆古文光灿烂，花垂零露影参差。\n月寒烟淡最相宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9300, '好事近', '王千秋', '人物又无双，馀事锦机闲织。\n□就两都新赋，笑一生联缉。\n来年秋色起鹏程，一举上晴碧。\n须洗玉荷为寿，助穿杨飞的。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9301, '喜迁莺', '王千秋', '春前腊尾。\n问谁会开解，幽人心里。\n映竹精神，凌风标致，姑射昔闻今是。\n试妆竞看吹面，寄驿胜传缄纸。\n迥潇洒，更香来林表，枝横溪底。\n谁为。\n停征骑。\n评蕙品兰，俱恐非同里。\n天意深怜，花神偏巧，持为翦冰裁水。\n拟唤绿衣来舞，只许苍官相倚。\n醉眠稳，尽参横月落，留连行李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9302, '喜迁莺', '王千秋', '玉龙垂尾。\n望阙角，如侵云里。\n明璧榱题，白银阶陛，平日世间无是。\n静久声鸣槛竹，夜半色侵窗纸。\n最奇处，尽巧妆枝上，低飞檐底。\n当为。\n呼游骑。\n嗾犬擎苍，腰箭随邻里。\n藉草烹鲜，枯枝煎茗，点化玉花为水。\n未挹瑶台风露，且借琼林栖倚。\n眩银海，待斜披鹤氅，骑鲸寻李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9303, '满庭芳', '王千秋', '蕊小雕琼，花明熔蜡，天交一旦俱芳。\n丰虽异，皆熨水沈香。\n应笑纷红堕紫，初未识、调粉涂黄。\n凭肩处，金细玉珥，不数寿阳妆。\n思量。\n谁比似，酥裁笋指，密翦蜂房。\n又何须酣酒，重暖瑶觞。\n且放侧堆金缕，骊山冷、来浴温汤。\n谁题品，青枝绿萼，俱未许升堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9304, '诉衷情', '王千秋', '二分浓绿一分红。\n春事若为穷。\n醉袖香沾粉，公挽我、我扶公。\n短帽，吐长虹。\n拟凌风。\n布金堆里，叠翠屏中，云月轻笼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9305, '临江仙', '王千秋', '柳巷莺啼春未晓，画堂环佩珊珊。\n薰炉烘暖鹧鸪斑。\n寿杯须斗酌，舞袖正弓弯。\n未说珥貂横玉事，勋名且勒燕然。\n归来方卜五湖闲。\n年年花月夜，沈醉绮罗间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9306, '浣溪沙', '王千秋', '叠雪裁霜越匀。\n美人亲翦称腰身。\n暑天宁数越罗春。\n两臂轻笼燕玉腻，一胸斜露塞酥温。\n不教香汗湿歌尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9307, '西江月', '王千秋', '四俊乡书荐鹗，一夔漕府登贤。\n明年春晚柳如烟。\n看取胪传金殿。\n册府牙签昼阅，词垣紫诰宵传。\n青楼买酒定无缘。\n且放金杯潋滟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9308, '醉落魄・一斛珠', '王千秋', '能歌善谑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9309, '虞美人', '王千秋', '风花南北知何据。\n常是将春负。\n海棠开尽野棠开。\n匹马崎岖、还入乱山来。\n尊前人物胜前度。\n谁记桃花句。\n老来情事不禁浓。\n玉佩行云、切莫易丁东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9310, '虞美人', '王千秋', '要津去去无由据。\n已分平生负。\n拟将怀抱向谁开。\n万水千山、聊为借书来。\n玄都昼永闲难度。\n欲正书中句。\n黄琮丹璧已磨浓。\n发箧烦君、早送过桥东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9311, '谒金门', '王千秋', '春漠漠。\n闲尽绮窗云幕。\n悔不车轮生四角。\n却成缘分薄。\n想画鸦儿方学。\n小蹙恨人无托。\n不道月明谁共酌。\n这般情味恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9312, '谒金门', '王千秋', '春漠漠。\n何处养花张幕。\n佩冷香残天一角。\n忍看罗袖薄。\n两两鸳鸯难学。\n六六锦鳞空托。\n趁有馀妍须细酌。\n东风情性恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9313, '点绛唇', '王千秋', '玉立霞升，纵谈刘尹高支许。\n待为霖雨。\n小驻红莲府。\n鹤健松坚，鸿宝初非误。\n玄都路。\n桃花栽取。\n来看千千度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9314, '点绛唇', '王千秋', '何处春来，试烦君向垂杨看。\n万条轻线。\n已借鹅黄染。\n弄日摇风，按舞知谁见。\n阳关远。\n一杯休劝。\n且放修眉展。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9315, '点绛唇', '王千秋', '何处春来，试烦君向梅梢看。\n寿阳妆面。\n漏泄春何限。\n冷蕊疏枝，似恨春犹浅。\n收羌管。\n莫惊香散。\n留副□和愿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9316, '点绛唇', '王千秋', '何处春来，试烦君向钗头看。\n舞翻飞燕。\n已拂春风面。\n白玉圆钿，酌酒殷勤劝。\n深深愿。\n愿长□健。\n岁与春相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9317, '点绛唇', '王千秋', '何处春来，试烦君向盘中看。\n韭黄犹短。\n玉指呵寒翦。\n犀箸调匀，更为双双卷。\n情何限。\n怕寒须暖。\n先酌黄金盏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9318, '水调歌头', '王千秋', '笔力卷鲸海，人物冠麟台。\n向来朱邸千字，不省有惊雷。\n人似曲江风韵，刚要重来持节，不道玉堂开。\n草诏坐扛鼎，琐屑扫尊。\n金错落，貂掩映，玉崔嵬。\n看公谈笑，长河千里静氛埃。\n散马昼闲榆塞，辫发春趋瑶陛，都出济川才。\n老子尚顽健，东阁亦时来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9319, '瑞鹤仙', '王千秋', '夷吾在江左。\n罄毡裘俱，笑清边琐。\n遗民冀巾裹。\n个规模欲继，外人谁可。\n一花两果。\n晚占熊、材能更夥。\n试颁春、便有欢谣，声接月鞍烟。\n娑。\n已传丹诏，催上文石，□论炙。\n橐弓□。\n□九域，措安妥。\n待缁衣重咏，履封光继，绿野从教昼锁。\n问黑头、当日三公，可能似我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9320, '满江红', '王千秋', '水满方塘，三日雨、晓来方足。\n阑干外、锦初脱，新篁森玉。\n沃叶未乾鸠妇去，馀花时坠蜂儿逐。\n认去年、乳燕又双双，飞华屋。\n红豆恨，归谁促。\n青鸾梦，惊难续。\n想多情犹记，碧笺新曲。\n白发欺人虽已老，短襟黛存馀馥。\n且如今、一笑总休论，杯行速。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9321, '西江月', '王千秋', '璀璨雕笼洒笔，联翩荐鹗飞书。\n翻阶红药试妆梳。\n管取不言温树。\n容我一杯为寿，看君九万鹏图。\n髻鬟人小串珠玑。\n岁岁绿窗朱户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9322, '一落索', '李吕', '琢成玉树。\n谁解著、云斤月斧。\n短羸骖，朴一怀尘土。\n叹雄图、伤别绪。\n主人不语花能语。\n苦欲留君、不是留君处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9323, '满庭芳', '李吕', '光拂星榆，轮高金掌，暮烟飘尽澄空。\n素娥幽恨，霜艳洗铅红。\n醉把摩云妙手，教纤翳、不点青铜。\n知多少，天高露冷，争占九秋风。\n歌钟。\n邀胜侣，园攀琼树，帘卷珠宫。\n算庾楼吟赏，今古应同。\n多谢秦娥绝唱，声声为、飘入云中。\n留仙住，莫教清影，容易转梧桐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9324, '醉落魄・一斛珠', '李吕', '休休莫莫。\n当年不负西湖约。\n一技初见横篱落。\n嚼蕊闻香，长是醉乡落魄。\n而今对酒空斟酌。\n老来多病情非昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9325, '朝中措', '李吕', '展屏山色翠连空。\n潇洒冠闽中。\n背郭元无尘事，披襟时有清风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9326, '朝中措', '李吕', '堂成开宴日无空。\n景占四时中。\n画栋飞星汉，雕阑锁断花风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9327, '鹧鸪天', '李吕', '脸上残霞酒半消。\n晚妆匀罢却无聊。\n金泥帐小教谁共，银字笙寒懒更调。\n人悄悄，漏迢迢。\n琐窗虚度可怜宵。\n一从恨满丁香结，几度春深豆蔻梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9328, '鹧鸪天', '李吕', '甲帐春风肯见分。\n夜陪清梦当炉熏。\n寻香若傍阑干晓，定见堆红越鄂君。\n雕玉佩，郁金裙。\n凭谁书叶寄朝云。\n兰芽九畹虽清绝，也要芳心伴小醺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9329, '沁园春', '李吕', '射虎南山，断蛟北海，恍如梦中。\n念少年豪气，霜寒一剑，清时功业，月满雕弓。\n年去年来成底事，已一半消磨成老翁。\n那堪更，病为城绕，愁作兵攻。\n无。\n慵语西风。\n正独倚危阑送塞鸿。\n道酒能消遣，酒因病减，歌能消遣，歌为愁浓。\n大造不将炉冶去，□万卷诗书宁愤穷。\n都休问，且试弹绿绮，闲和秋虫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9330, '水调歌头', '李吕', '山雨喜开霁，爽气涤烦襟。\n晚秋丹叶飘坠，篱菊散黄金。\n徙倚关河凝望，回首光阴轻驶，倏忽二毛侵。\n须信人间世，莫放酒杯深。\n一星子，名与利，漫浮沈。\n塞翁祸福无定，此理古犹今。\n妙处只应亲到，外物从渠舒卷，出处我无心。\n袖手无新语，洗耳听清音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9331, '凤栖梧・蝶恋花', '李吕', '一岁光阴寒共暑。\n一日光阴，只个朝还暮。\n有物分明能唤寤。\n晚钟晨角君听取。\n扰扰胶胶劳百虑。\n究竟思量，没个相干处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9332, '点绛唇', '李吕', '去岁天涯，一灯闲作幽窗伴。\n酒来须满。\n不待旁人劝。\n今岁天涯，又是年华晚。\n凄凉惯。\n问天不管。\n只我何曾管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9333, '调笑令', '李吕', '眼尾。\n寄深意。\n一点兰膏红破蕊。\n钿窝浅浅双痕媚。\n背面银床斜倚。\n烛花先报今宵喜。\n管定知人心里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9334, '调笑令', '李吕', '归晚。\n思何限。\n玉坠金偏云鬓乱。\n伤春谁作嬉游伴。\n只有飞来花片。\n几回愁映眉山远。\n总被东风惊散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9335, '调笑令', '李吕', '春尽。\n敛新闷。\n暗傍银屏撩绿鬓。\n攒眉不许旁人问。\n帘外冷红成阵。\n银挑尽睡未肯。\n肠断秦郎归信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9336, '调笑令', '李吕', '花底。\n锦铺地。\n绣浪琼枝光似洗。\n一心长在金盆里。\n翠袖懒遮纤指。\n珠玑满斗犹慵起。\n过尽红楼春睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9337, '调笑令', '李吕', '含怨。\n两颦浅。\n羽髻云鬟低玉燕。\n绿沈香底金鹅扇。\n隐隐花枝轻颤。\n当筵不放红云转。\n正是玉壶春满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9338, '临江仙', '李吕', '家在宋墙东畔住，流莺时送芳音。\n窃香解佩两沈沈。\n都缘些子事，过却许多春。\n日上花梢初睡起，绣衣闲纵金针。\n错将黄晕压檀心。\n见人羞不语，偷把泪珠匀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9339, '青玉案', '李吕', '参横月落闻街鼓。\n指杨柳、天边路。\n冷澹梨花啼玉箸。\n五云芝检，八花砖影，稳上鳌头去。\n吹箫台冷秦云暮。\n玉勒嘶风弄娇步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9340, '蝶恋花', '陈从古', '日借轻黄珠缀露。\n困倚东风，无限娇春处。\n看尽夭红浑谩语。\n淡妆偏称泥金缕。\n不共铅华争胜负。\n殿後开时，故欲寻春去。\n去似朝霞无定所。\n那堪更著催花雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9341, '菩萨蛮', '姚宽', '斜阳山下明金碧。\n画楼返照融春色。\n睡起揭帘旌。\n玉人蝉鬓轻。\n无言空伫立。\n花落东风急。\n燕子引愁来。\n眉心那得开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9342, '菩萨蛮', '姚宽', '梦中不记江南路。\n玉钗翠鬓惊春去。\n午醉晚来醒。\n暝烟花上轻。\n红绡空泪。\n锦字凭谁寄。\n衫薄暧香销。\n相思云水遥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9343, '怨王孙・忆王孙', '姚宽', '毵毵杨柳绿初低。\n澹澹梨花开未齐。\n楼上情人听马嘶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9344, '生查子', '姚宽', '郎如陌上尘，妾似堤边絮。\n相见两悠扬，踪迹无寻处。\n酒面扑春风，泪眼零秋雨。\n过了别离时，还解相思否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9345, '踏莎行', '姚宽', '苹页烟深，荷花露湿。\n碧芦红蓼秋风急。\n采菱渡口日将沈，飞鸿楼上人空立。\n彩凤难双，红绡暗泣。\n回纹未剪吴刀涩。\n梦云归处不留踪，厌厌一夜凉蟾入。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9346, '满江红', '刘珙', '南郭新居，忆乡社、久成疏隔。\n乘暇日、风吹衣袂，花迎村陌。\n果核难豚张燕豆，儿童父老聊宾席。\n想笋舆、到处水增光，山添色。\n应情念，天涯侄。\n随官牒，飘萍迹。\n叹离多聚少，感今思昔。\n鬓影羞临湘水绿，梦魂常对屏山碧。\n凭画栏、搔首望归云，情无极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9347, '水调歌头', '黄格', '富贵不难致，名节几人全。\n渡江龙化，於今，五十有三年。\n历数朝堂诸老，谁似武夷仙伯，操行老弥坚。\n吾道适中否，一柱独擎天。\n湖南北，江左右，屡藩宣。\n韩公城下，烽火静、米斗三钱。\n人愿公归台鼎，我愿公归中隐，九老要齐肩。\n岁岁祝公寿，风月伴梅仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9348, '菩萨蛮', '汤思退', '画船横绝湖波练。\n更上雕鞍穷翠。\n霜橘半垂黄。\n征衣尽日香。\n钟声云外听。\n金界青松映。\n何处是华山。\n峰峦杳霭间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9349, '如梦令', '张仲宇', '送过雕梁旧燕。\n听到妆楼新雁。\n菊讯一何迟，倒尽清樽谁伴。\n魂断。\n魂断。\n人与暮云俱远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9350, '踏莎行', '李流谦', '菊露晴黄，枫霜晚翠。\n重阳气候偏如此。\n异乡牢落怕登临，吾家落照飞云是。\n举扇尘低，脱巾风细。\n灵苗医得人憔悴。\n灯前点检欠谁人，惟有断鸿知此意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9351, '如梦令', '李流谦', '老插黄花不称。\n节物撩人且任。\n破帽略遮阑，嫌见星星越甚。\n不饮。\n不饮。\n和取蜂愁蝶恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9352, '醉蓬莱', '李流谦', '正红疏绿密，浪软波肥，放舟时节。\n载地擎天，识堂堂人杰。\n万里长江，百年骄虏，只笑谈烟灭。\n葭苇霜秋，楼船月晓，渔樵能说。\n分陕功成，沙堤归去，衮绣光浮，两眉黄彻。\n了却中兴，看这回勋业。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9353, '小重山', '李流谦', '轻暑单衣四月天。\n重来间屈指，惜流年。\n人间何处有神仙。\n安排我，花底与尊前。\n争道使君贤。\n笔端驱万马，驻平川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9354, '青玉案', '李流谦', '相知元早来何暮。\n社燕送、秋鸿去。\n春草春波愁目注。\n酒香花韵，绮谭妍唱，怎不思量住。\n虚无指点骑鲸路。\n个是骚人不凡处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9355, '虞美人', '李流谦', '一春不识春风面。\n都为慵开眼。\n荼シ雪白牡丹红。\n犹及尊前一醉、赏芳。\n东君又是匆匆去。\n我亦无多住。\n四年薄宦老天涯。\n闲了故园多少、好花枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9356, '点绛唇', '李流谦', '一翦秋光，阿谁洗得无纤滓。\n冰盘彻底。\n人也清如此。\n万里归来，著个斑衣戏。\n慈颜喜。\n问君不醉。\n更遣何人醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9357, '感皇恩', '李流谦', '万绿压庭柯，雨晴烟润。\n三尺金猊麝微喷。\n百花香暖，酿作九霞仙酝。\n祝君如此酒，年年饮。\n插额汉貂，垂腰苏印。\n趁取如今未华鬓。\n三茅兄弟，总有丹台名姓。\n蟠桃熟也未，教人问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9358, '武陵春', '李流谦', '晓日帘栊初破睡，宝鸭宿薰浓。\n笑指图中鹤发翁。\n仙骨宛然同。\n万里郎官遥上寿，五马茜衫红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9359, '谒金门', '李流谦', '行不记。\n贪看远峰颦翠。\n风约柳花吹又起。\n故黏行客袂。\n老大浑无欢意。\n不为伤春憔悴。\n茅屋数间修竹里。\n日长春睡美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9360, '谒金门', '李流谦', '空伫立。\n又是冷烟寒食。\n开尽荼シ都一色。\n东风吹更白。\n我是纶竿倦客。\n道上行人不识。\n著取蓑衣拈短笛。\n沙鸥应认得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9361, '谒金门', '李流谦', '春又晚。\n杨柳晓莺啼断。\n落尽残红馀片片。\n风狂都不管。\n作客惟嫌酒浅。\n未敌闲愁一半。\n人与青山谁近远。\n可怜春梦短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9362, '谒金门', '李流谦', '山数尺。\n江草江波同碧。\n晚雨吹风才数滴。\n行人心更急。\n漠漠疏烟如织。\n遮断客愁不得。\n肠断故园无信息。\n灯花闲手剔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9363, '玉漏迟', '李流谦', '东南应眷倚。\n当年丽绝，今其馀几。\n云锦飘香，好在藕花十里。\n六月长安徂暑，只一雨、滂沱都洗。\n君好为。\n携将苏醒，三吴生齿。\n总道秦蜀讴吟，但消得雍容，笑谈而致。\n稍待秋风，也拟买舟东逝。\n收拾尘编蠹简，更饱看、江山奇伟。\n歌盛美。\n远送往趋天陛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9364, '满庭芳', '李流谦', '归去来兮，吾归何处，旧山闲却岷峨。\n雪堂重到，但觉客愁多。\n来往真成底事，人应笑、我亦狂歌。\n凭阑久，云东不至，举盏酹东坡。\n少年，浑妄意，斗冲剑气，雷化龙梭。\n到如今，翻羡白鸟沧波。\n松柏皆吾手种，依然□、烟蕊霜柯。\n君知否，人间尘事，元不到渔蓑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9365, '人娇', '李流谦', '痴本无绦，闷宁有火。\n都是你，自缠自锁。\n高来也可。\n低来也可。\n这宇宙，何曾碍你一个。\n休说荣枯，强分物我。\n惺惺地，要须识破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9366, '洞仙歌', '李流谦', '云窗雾阁，尘满题诗处。\n枝上流莺解人语。\n道别来，知否瘦尽花枝，春不管，更遣何人管取。\n平生鸥鹭性，细雨疏烟，惯了江头自来去。\n不见鹊桥旁，只为隔年，翻赢得、年年风露。\n便学得、无情海中潮，纵一日两回，如何凭据。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9367, '卜算子', '李流谦', '生别有相逢，死别无消息。\n说著从前总是愁，只是不相忆。\n月堕半窗寒，梦里分明识。\n却似人不忆他，花露盈盈湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9368, '水调歌头', '李流谦', '江涨解网雨，衣润熟梅天。\n高人何事，乘兴来寄五湖船。\n才听咚咚叠奏，呕轧撸声声齐发，几别故州山。\n转盼青楼杪，已在碧云端。\n渡头月，临晚霁，泊清湾。\n水空天静，高下相应总团。\n遥想吾家更好，尽唤儿曹泛扫，欣赏共婵娟。\n应念思归客，对此不成眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9369, '于飞乐', '李流谦', '薄日烘晴，轻烟笼晓，春风绣出林塘。\n笑溪桃，并坞杏，忒煞寻常。\n东君处，没他後、成甚风光。\n翠深深，谁教入骨，夜来过雨淋浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9370, '西江月', '李流谦', '色似腊梅浑浅，香如卜微清。\n更张绿幄蔽轻盈。\n巧著工夫斗钉。\n露页涓涓月晓，风英点点秋晴。\n江南江北可经行。\n梦到吴王香径。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9371, '眼儿媚', '李流谦', '素娥作意失幽期。\n我自不凭伊。\n举杯重叹，帖云微笑，应道人痴。\n如今老去无情绪，只有睡相宜。\n建溪一啜，木樨数翦，酒醒归时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9372, '朝中措', '李流谦', '相思两地费三年。\n明月几回圆。\n鸥鸟不知许事，清江仍绕青山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9373, '千秋岁', '李流谦', '玉林照坐。\n簌簌花微堕。\n春院静，烟扉锁。\n黛轻妆未试，红淡唇微破。\n清瘦也，算应都是风流过。\n把盏对横枝，尚忆年时个。\n人不见，愁无那。\n绕林霜掠袂，嚼蕊香黏唾。\n清梦断，更随月色禁持我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9374, '虞美人', '李流谦', '吴波亭畔千行柳。\n直恁留人久。\n晚来船槛再三凭。\n又是一钩新月、照江心。\n故人有约何时到。\n白地令人老。\n只愁酒尽更谁赊。\n一段闲愁无计、奈何他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9375, '满江红', '洪迈', '雨涩风悭，双溪、几曾洋溢。\n长长是、非霞散绮，岫云凝碧。\n修禊欢游今不讲，流觞故事何从觅。\n待它时、水到却寻盟，筹输一。\n燕舞倦，莺吟毕。\n春肯住，才明日。\n池塘波绿皱，小荷争出。\n童子舞雩浑怅望，吾人提笔谁飘逸。\n记去年，修竹暮天寒，无踪迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9376, '临江仙', '洪迈', '绮席流欢欢正洽，高楼佳气重重。\n钗头小篆烛花红。\n直须将喜事，来报主人公。\n桂月十分春正半，广寒宫殿葱葱。\n娥相对曲阑东。\n云梯知不远，平步蹑东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9377, '导引', '洪迈', '寒日短，草露朝。\n仙鹤下，梦云归。\n大椿亭畔苍苍柳，怅无由、挽住天衣。\n昭阳深，暝鸦飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9378, '六州', '洪迈', '尧传舜，盛事千古难并。\n回龙驭，辞凤掖，北内别有蓬瀛。\n为天子父，册鸿名。\n万年千岁福康宁。\n春秋不说楚冥灵。\n莱衣彩戏，汉殿玉卮轻。\n宸游今不见，烟外落霞明。\n前回丁未，雾塞神京。\n正同符、光武中兴。\n擎天独力扶倾。\n定宗庙，保河山，乾坤整顿庚庚。\n功成了，脱屣遗荣。\n访崆峒、空与丹庭。\n笑挹尘寰、不留行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9379, '十二时・忆少年', '洪迈', '璧门双阙转苍龙。\n德寿俨祗宫。\n轩屏正坐，天子亲拜天公。\n仪绅笏，罗鹭，粲庭中。\n仙家欢不尽，人世寿无穷。\n谁知云路，玉京成就，催返璇穹。\n转手万缘空。\n见说烟霄好处，不与下方同。\n尘合雾迷。\n笙箫寥寂，楼阁玲珑。\n中兴大业，巍巍稽古成功。\n事去孤鸿。\n忍听宵柝晨锺。\n灵举驾，素帏低，杳庞茸。\n渐江潮，万神护，川後滋恭。\n因山祗事，崔嵬禹穴，此日重逢。\n柏城封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9380, '踏莎行', '洪迈', '院落深沈，池塘寂静。\n帘钩卷上梨花影。\n宝筝拈得雁难寻，篆香消尽山空冷。\n钗凤斜，鬓蝉不整。\n残红立褪慵看镜。\n杜鹃啼月一声声，等闲又是三春尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9381, '浪淘沙', '赵缩手', '损屋一间儿。\n好与支持。\n休教风雨等闲欺。\n觅个带修安稳路，休遣人知。\n须是着便宜。\n运转临时。\n祆知险里却防危。\n透得玄关归去路，方步云梯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9382, '满庭芳', '张风子', '咄哉牛儿，心壮力壮，几人能可牵系。\n为爱原上，娇嫩草萋萋。\n只管侵青逐翠，奔走後、岂顾群迷。\n争知道，山遥水远，回首到家迟。\n牧童，能有智，长绳牢把，短梢高携。\n任从它，入泥入水无为。\n我自心调步稳，青松下、横笛长吹。\n当归处，人牛不见，正是月明时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9383, '失调名', '张珍奴', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9384, '减字木兰花', '洪惠英', '梅花似雪。\n刚被雪来相挫折。\n雪里梅花。\n无限精神总属他。\n梅花无语。\n只有东君来作主。\n传语东君。\n且与梅花作主人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9385, '浣溪沙', '何作善', '草草杯盘访玉人。\n灯花呈喜座添春。\n邀郎觅句要奇新。\n黛浅波娇情脉脉，云轻柳弱意真真。\n从今风月属闲人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9386, '水调歌头', '刘之翰', '凉露洗金井，一叶下梧桐。\n谪仙浪游，何事华发作诗翁。\n乌帽萧萧一幅，坐对清泉白石，矫首抚长松。\n独鹤归来晚，声在碧霄中。\n神仙宅，留玉节，驻金狨。\n黔南一道，十万貔虎控雕弓。\n笑折碧荷倒影，自唱采莲新曲，词句满秋风。\n剑佩八千岁，长入大明宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9387, '失调名', '周某', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9388, '南乡子', '太学诸生', '洪迈被拘留。\n稽首垂哀告彼酋。\n七日忍饥犹不耐，堪羞。\n苏武争禁十九秋。\n厥父既无谋。\n厥子安能解国忧。\n万里归来夸舌辨，村牛。\n好摆头时便摆头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9389, '失调名', '仪珏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9390, '水调歌头', '袁去华', '云冻鸟飞灭，春意著林峦。\n娥何事，醉撼瑞叶落人间。\n斜入酒楼歌处，微褪茅檐烟际，窗户漾光寒。\n西帝游何许，翳凤更骖鸾。\n玉楼耸，银海眩，倚阑干。\n渔蓑江上归去，浑胜画图看。\n三嗅疏枝冷蕊，索共梅花一笑，相对两无言。\n月影黄昏里，清兴绕吴山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9391, '水调歌头', '袁去华', '吴门古都会，畴昔记曾游。\n轻帆卸处，西风吹老白苹洲。\n试觅姑苏台榭，尚想吴王宫阙，陆海跨鳌头。\n西子竟何许，水殿漫凉秋。\n画图中，烟际寺，水边楼。\n叫云横玉，须臾三弄不胜愁。\n兴废都归闲梦，俯仰已成陈迹，家在泽南州。\n有恨向谁说，月涌大江流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9392, '水调歌头', '袁去华', '天下最奇处，绿水照朱楼。\n三高仙去，白头千古想风流。\n跨海晴虹垂饮，极目沧波无际，落日去渔舟。\n苹末西风起，橘柚洞庭秋。\n记当年，携长剑，觅封侯。\n而今憔悴长安，客里叹淹留。\n回首洪崖西畔，随分生涯可老，卒岁不知愁。\n做个终焉计，谁羡五湖游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9393, '水调歌头', '袁去华', '一叶堕金井，秋色满蟾宫。\n婵娟影里，玉箫吹断碧芙蓉。\n缭绕宫墙千雉，森耸觚双阙，缥缈五云中。\n郁郁葱葱处，佳气夜如虹。\n日华边，江海客，每从容。\n青钱万选，北门东观会留侬。\n堪叹搏沙一散，今夜扁舟何许，红蓼碧芦丛。\n无地寄愁绝，把酒酹西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9394, '水调歌头', '袁去华', '笔阵万人敌，风韵玉壶冰。\n文章万丈光焰，论价抵连城。\n小试冯川三异，无数成阴桃李，寒谷自春生。\n奏牍三千字，晁董已销声。\n玺书下，天尺五，运千龄。\n长安知在何处，指点日边明。\n看取纶巾羽扇，静扫神州赤县，功业小良平。\n翻笑凌烟阁，双鬓半星星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9395, '水调歌头', '袁去华', '雄跨洞庭野，楚望古湘州。\n何王台殿，危基百尺自西刘。\n尚想霓旌千骑，依约入云歌吹，屈指几经秋。\n叹息繁华地，兴废两悠悠。\n登临处，乔木老，大江流。\n书生报国无地，空白九分头。\n一夜寒生关塞，万里云埋陵阙，耿耿恨难休。\n徙倚霜风里，落日伴人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9396, '水调歌头', '袁去华', '鸟影度疏木，天势入平湖。\n沧波万顷，轻风落日片帆孤。\n渡口千章云木，苒苒炊烟一缕，人在翠微居。\n客里更愁绝，回首忆吾庐。\n功名事，今老矣，待何如。\n拂衣归去，谁道张翰为莼鲈。\n且就竹深荷静，坐看山高月小，剧饮与谁俱。\n长啸动林木，意气欲凌虚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9397, '念奴娇', '袁去华', '蕊珠宫女弄幽妍，初著春心娇小。\n自白真香，浑胜似、姑射冰肌窈窕。\n带雪茅檐，临溪篱落，占却春多少。\n天寒日暮，有人愁绝行绕。\n长记流水桥边，雨晴烟淡，袅一枝清晓。\n梦想经年开病眼，把酒风前一笑。\n花骨娇多，不禁人觑，只怕轻飞了。\n无端羌管，夜阑声入云杪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9398, '念奴娇', '袁去华', '水边篱落独横枝，苒苒风烟岑寂。\n踏雪寻芳村路永，竹屋西头遥识。\n蕙草香销，小桃红未，醉眼惊春色。\n罗浮何处，断肠无限陈迹。\n憔悴素脸朱唇，天寒日暮，倚琅无力。\n岁晚天涯驿使远，难寄江南消息。\n自笑平生，怜清惜淡，故国曾亲植。\n百花虽好，问还有恁标格。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9399, '念奴娇', '袁去华', '竹阴窗户荐微凉，积雨郊墟新霁。\n万里飞云都过尽，天阙星河如洗。\n檐隙风来，流萤飘堕，苒苒还飞起。\n魂清骨冷，坐来衣润空翠。\n勘笑丘壑闲身，儒冠相误，著青衫朝市。\n功业君看清镜里，两鬓于今如此。\n身外纷纷，倘来适去，到了成何事。\n人生一世，种瓜何处无地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9400, '念奴娇', '袁去华', '满城风雨近重阳，云卷天空垂幕。\n林表初阳光似洗，屋角呼晴双鹊。\n香泽方熏，烘帘初下，森森霜华薄。\n发妆酒暖，人须要同酌。\n老手为拂春山，休夸京兆扫，宫眉难学。\n客里清欢随分有，争似还家时乐。\n料得厌厌，云窗深锁，宽尽黄金约。\n不堪重省，泪和灯烬偷落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9401, '念奴娇', '袁去华', '一番雨过一番凉，秋入苍崖青壁。\n昼日多阴，还又是、重九飘零江国。\n瘦水鳞鳞，长烟袅袅，枫叶千林赤。\n南山入望，为谁依旧佳色。\n随分绿酒黄花，联镳飞盖，总龙山豪客。\n人世高歌狂笑外，扰扰於身何得。\n短发萧萧，风吹乌帽，醉里从侧。\n明年虽健，未知何处相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9402, '水龙吟', '袁去华', '晚来侧侧清寒，冻云万里回飞鸟。\n故园梦断，单于吹罢，房栊易晓。\n西帝神游，万妃缟袂，相看一笑。\n泛扁舟乘兴，蹇驴觅句，山阴曲、霸陵道。\n舞态随风窈窕。\n任穿帘，儿童休扫。\n洛阳高卧，萧条门巷，悄无人到。\n供断诗愁，夜窗还共，陈编相照。\n念寒梅映水，匀妆弄粉，与谁争好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9403, '水龙吟', '袁去华', '汉家经略中原，上游眷此喉衿地。\n风行雷动，无前伟绩，伊谁扬厉。\n玉帐筹边，绣衣给，江上增气。\n自武侯蜕迹，羊公缓带，功名事、更谁继。\n方□长驱万里。\n笑谈间、生擒元济。\n非熊未兆，封留终在，同功异世。\n刻就丰碑，万山直下，不须沈水。\n要追攀二雅，流传千古，属骚人记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9404, '水龙吟', '袁去华', '汉江流入苍烟，戍楼吊古临无地。\n清霜初肃，鹰扬隼击，青霄凌厉。\n新雁声中，夕阳影里，千崖秋气。\n念东篱采菊，龙山落帽，风流在、尚堪继。\n引满松醪径醉。\n诵坡仙、临漳宵济。\n茱萸细看，明年谁健，空悲身世。\n儿辈何知，更休说似，登山临水。\n那纷纷毁誉，耳边风过，我何曾记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9405, '满庭芳', '袁去华', '雨送凉来，风将云去，晚天千顷玻璃。\n婵娟依旧，出海较些迟。\n玉兔秋毫可数，疏星外、乌鹊南飞。\n今何夕，空浮大白，一笑共谁持。\n团栾，成露坐，云鬟香雾，玉臂清辉。\n任短髭争挽，问我归期。\n三弄楼头长笛，愁人处、休苦高吹。\n沈吟久，颐细数，四十九年非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9406, '满庭芳', '袁去华', '麦陇黄轻，桑畴绿暗，野桥新碧泱泱。\n怕春归去，莺语燕飞忙。\n风定闲花自落，穿幽径、拾蕊寻香。\n曾来处，孤云翠壁，依旧挂斜阳。\n客愁，知几许，唯思径醉，谁与持觞。\n料文君衣带，为我偷长。\n苦忆新晴昼永，闲相伴、刺绣明窗。\n何时得，西风夜雨，枕簟共新凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9407, '满庭芳', '袁去华', '马上催归，枕边唤起，谢他闲管闲愁。\n正难行处，云木叫钩。\n似笑天涯倦客，区区地、著甚来由。\n真怜我，提壶劝饮，一醉散千忧。\n人生，谁满百，闲中最乐，饱外何求。\n算苦无官况，莫要来休。\n住个溪山好处，随缘老、蜡屐渔舟。\n虽难比，东山绿野，得似个优游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9408, '满江红', '袁去华', '香雾空，檐牙外、流萤自照。\n夜向久、明河东畔，电飞云绕。\n错落疏星垂屋角，须臾万弩鸣林杪。\n渐翠竹、苍梧嫩凉生，惊秋早。\n人语静，签声杳。\n珍簟冷，纱厨小。\n想云窗依旧，梦寻难到。\n雁足空来书断绝，眉头顿著愁多少。\n纵细写、琴心有谁知，朱弦悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9409, '满江红', '袁去华', '画栋珠帘，临无地、沧波万顷。\n云尽敛、西山横翠，半江沈影。\n斜日明边回白鸟，晚烟深处迷渔艇。\n听棹歌、游女采莲归，声相应。\n愁似织，人谁省。\n情纵在，欢难更。\n满身香犹是，旧时笋令。\n宦海归来尘扑帽，酒徒散尽霜侵鬓。\n最愁处、独立咏苍茫，西风劲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9410, '满江红', '袁去华', '社雨初晴，烟光暖、吴山滴翠。\n望绛阙、祥云亏蔽，粉垣千雉。\n万柳低垂春似酒，微风不动天如醉。\n遍万井、嬉嬉画图中，欢声里。\n嗟倦客，道傍李。\n看人事，槐根蚁。\n立苍茫俯仰，漫悲身世。\n靖节依然求县令，元龙老去空豪气。\n便乘兴、一叶泛沧浪，吾归矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9411, '兰陵王', '袁去华', '晓阴薄。\n隔屋呼晴噪鹊。\n长烟袅、轻素望中，林表初阳照城郭。\n秋容自寂寞。\n清浅溪痕旋落。\n桥虹外，明嶂万重，云木千章映楼阁。\n天涯信飘泊。\n漫水绕郴山，尺素难托。\n文园多病宽衣索。\n最长笛声断，画阑凭暖，黄昏前後况味恶。\n甚良宵闲却。\n辽邈。\n误行乐。\n料恨寄徽弦，心倦梳掠。\n西风满院垂帘幕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9412, '兰陵王', '袁去华', '小桥直。\n林表遥岑寸碧。\n斜阳外、霞绚晚空，一目千里总佳色。\n初寒遍泽国。\n投老依然是客。\n功名事，云散鸟飞，匣里青萍漫三尺。\n重来怆陈迹。\n又水褪沙痕，风满帆席。\n鲈肥莼美曾同食。\n听虚阁松韵，古墙竹影，参差犹记过此驿。\n傍溪南山北。\n悲恻。\n暗愁积。\n拥绣被焚香，谁伴孤寂。\n追寻恩怨无穷极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9413, '六州歌头', '袁去华', '柴桑高隐，邱壑岁寒姿。\n北窗下，羲黄上，古人期。\n俗人疑。\n束带真难事，赋归去，吾庐好，斜川路，携筇杖，看云飞。\n六翮冥冥高举，青霄外、缴何施。\n且流行坎止，人世任相违。\n采菊东篱。\n正悠然、见南山处，无穷景，与心会，有谁知。\n琴中趣，杯中物，醉中诗。\n可忘机。\n一笑骑鲸去，向千载，赏音稀。\n嗟倦翼，瞻遗像，是吾师。\n门外空馀衰柳，摇疏翠、斜日辉辉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9414, '瑞鹤仙', '袁去华', '郊原初过雨。\n见败叶零乱，风定犹舞。\n斜阳挂深树。\n映浓愁浅黛，遥山眉妩。\n来时旧路。\n尚岩花、娇黄半吐。\n到而今，唯有溪边流水，见人如故。\n无语。\n邮亭深静，下马还寻，旧曾题处。\n无聊倦旅。\n伤离恨，最愁苦。\n纵收香藏镜，他年重到，人面桃花在否。\n念沈沈、小阁幽窗，有时梦去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9415, '荔枝香近・荔枝香', '袁去华', '晓来丹枫过雨，净如扫。\n霜空横雁，寒日翻鸦，惊嗟岁月如流，更被酒迷花恼。\n转眼吴霜，点鬓催老。\n细思欢游旧事，还自笑。\n断雨残云，都总似、梦初觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9416, '卓牌子近', '袁去华', '曲沼朱阑，缭墙翠竹晴昼。\n金万缕、摇摇风柳。\n还是燕子归时，花信来後。\n看淡净洗妆态，梅样瘦。\n春初透。\n尽日明窗相守。\n闲共我焚香，伴伊刺绣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9417, '剑器近', '袁去华', '夜来雨。\n赖倩得、东风吹住。\n海棠正妖饶处。\n且留取。\n悄庭户。\n试细听、莺啼燕语。\n分明共人愁绪。\n怕春去。\n佳树。\n翠阴初转午。\n重帘未卷，乍睡起、寂寞看风絮。\n偷弹清泪寄烟波，见江头故人，为言憔悴如许。\n彩笺无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9418, '木兰花慢', '袁去华', '□中原望眼，正汉水、接天流。\n渐霁雨虹消，清风面旋，借我凉秋。\n草庐旧三顾处，但孤云、翠壁晚悠悠。\n唯有兰皋解佩，至今犹话离愁。\n迟留。\n叹息此生浮。\n去去老沧洲。\n念岁月侵寻，闲中最乐，饱外何求。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9419, '八声甘州', '袁去华', '正阴阴、夏木听黄鹂，百啭语惺松。\n乍钩窗意适，临池倒影，竹树青葱。\n翠盖红妆窈窕，香引一帘风。\n向晚追凉处，月挂梧桐。\n何处楼头吹笛，渐玉绳低侧，河汉横空。\n想调冰雪藕，清夜与谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9420, '宴清都', '袁去华', '暮雨消烦暑。\n房栊□、顿觉秋意如许。\n天高云杳，山横绀碧，桂华初吐。\n空庭静掩桐阴，更苒苒、流萤暗度。\n记那时、朱户迎风，西厢待月私语。\n佳期易失难重，馀香破镜，虽在何据。\n如今要见，除非是梦，几时曾做。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9421, '倾杯近', '袁去华', '邃馆金铺半掩，帘幕参差影。\n睡起槐阴转午，鸟啼人寂静。\n残妆褪粉，松髻云慵不整。\n尽无言，手裙带绕花径。\n酒醒时，梦回处，旧事何堪省。\n共载寻春，并坐调筝何时更。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9422, '长相思', '袁去华', '叶舞殷红，水摇瘦碧，隐约天际帆归。\n寒鸦影里，断雁声中，依然残照辉辉。\n立马看梅。\n试寻香嚼蕊，醉折繁枝。\n山翠扫修眉。\n记人人、蹙黛愁时。\n叹客里、光阴易失，霜侵短鬓，尘染征衣。\n阳台云归後，到如今、重见无期。\n流怨清商，空细写、琴心向谁。\n更难将、愁随梦去，相思惟有天知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9423, '风流子', '袁去华', '吴山新摇落，湖光净、鸥鹭点涟漪。\n望一簇画楼，记沽酒处，几多鸣橹，争趁潮归。\n瑞烟外，缭墙迷远近，飞观耸参差。\n残日衬霞，散成锦绮，怒涛推月，辗上玻璃。\n西风吹残酒，重门闭，深院露下星稀。\n肠断凭肩私语，织锦新诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9424, '侧犯', '袁去华', '篆销馀馥，烛堆残蜡房栊晓。\n寒峭。\n看杏脸羞红、尚娇小。\n游蜂静院落，绿水摇池沼。\n闲绕。\n翠树底、颐听啼鸟。\n愁风怕雨，弹指春光了。\n音信杳。\n最堪恨、归雁过多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9425, '贺新郎', '袁去华', '晓色明窗绮。\n耿残灯、寒生翠幕，鸟啼人起。\n一夜西园新雨过，细草闲花似洗。\n漾澜影、柳塘春水。\n闲昼双飞归来燕，正东风、漫漫吹桃李。\n还是个，闷天气。\n回廊小院帘垂地。\n想连天、芳草萋迷，短长亭外。\n愁到春来依然在，旧事浑如梦里。\n又生怕、人惊憔悴。\n楼上谁家吹长笛，向曲中、说尽相思意。\n三弄处，寸心碎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9426, '红林擒近', '袁去华', '森木蝉初噪，淡烟梅半黄。\n睡起傍檐隙，墙梢挂斜阳。\n鱼跃浮萍破处，碎影颠倒垂杨。\n晚庭谁与追凉。\n清风散荷香。\n望极霞散绮，坐待月侵廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9427, '垂丝钓', '袁去华', '江枫秋老。\n晓来红叶如扫。\n暮雨生寒，正北风低草。\n宾鸿早。\n乱半川残照。\n伤怀抱。\n记西园饮处，微云弄月，梅花人面争好。\n路长信杳。\n度日房栊悄。\n还是黄昏到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9428, '安公子', '袁去华', '弱柳丝千缕。\n嫩黄匀遍鸦啼处。\n寒入罗衣春尚浅，过一番风雨。\n问燕子来时，绿水桥边路。\n曾画楼、见个人人否。\n料静掩云窗，尘满哀弦危柱。\n庾信愁如许。\n为谁都著眉端聚。\n独立东风弹泪眼，寄烟波东去。\n念永昼春闲，人倦如何度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9429, '蓦山溪', '袁去华', '蕊珠宫阙，西帝陈嫔御。\n语笑梦中香，叹罗浮、几番春暮。\n江南岁晚，垂地冻云黄，修竹外，一枝斜，流水桥边路。\n小桃半吐。\n羞得无藏处。\n不怕雪霜欺，最难禁、豪风横雨。\n当年诗兴，犹自记扬州，今老矣，客天涯，还认何郎否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9430, '一丛花', '袁去华', '东风吹恨著眉心。\n金约瘦难任。\n西窗翦烛浑如梦，最愁处、南陌分襟。\n香歇绣囊，尘生罗幌，憔悴到如今。\n小花幽院夜沈沈。\n凉月转槐阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9431, '雨中花・夜行船', '袁去华', '江上西风晚。\n野水兼天远。\n云衣拖翠缕，易零乱。\n见柳叶满梢，秀色惊秋变。\n百岁今强半。\n两鬓青青，尽著吴霜偷换。\n向老来、功名心事懒。\n客里愁难遣。\n乍飘泊、有谁管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9432, '谒金门', '袁去华', '春索寞。\n楼上晚来风恶。\n午醉初醒罗袖薄。\n护寒添翠幕。\n愁里花时过却。\n闲处泪珠偷落。\n憔悴只羞人问著。\n镜中还自觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9433, '谒金门', '袁去华', '深院闭。\n漫漫东风桃李。\n芳草萋迷烟雨细。\n秦楼何处是。\n还是伤春意味。\n闲却踏青天气。\n折得海棠双蒂子。\n无言心自喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9434, '谒金门', '袁去华', '春寂寂。\n尽日蜂寻窗隙。\n隔叶黄鹂声历历。\n满庭芳草碧。\n相对熏炉象尺。\n新睡觉来无力。\n几日郎边无信息。\n闲拈双六掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9435, '谒金门', '袁去华', '归鸟急。\n照水斜阳红湿。\n篷底夜凉风露入。\n藕花香习习。\n点滴城头漏涩。\n凄断草间虫泣。\n新恨旧愁眉上集。\n月斜还伫立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9436, '谒金门', '袁去华', '烟水阔。\n夜久风生苹末。\n东舫西船人语绝。\n四更山吐月。\n客里光阴电抹。\n不记离家时节。\n楼上单于听未彻。\n又催征棹发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9437, '谒金门', '袁去华', '云障日。\n檐外雪销残滴。\n画阁红炉窗户窄。\n博山烟穗直。\n酒入横波滟溢。\n羞得梅无颜色。\n乡有温柔元未识。\n更从何处觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9438, '谒金门', '袁去华', '清汉曲。\n天际落霞孤鹜。\n幽草墙阴秋更绿。\n倚檐三两竹。\n绣被焚香独宿。\n梦绕绿窗华屋。\n何日明眸光射目。\n夜阑更秉烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9439, '金蕉叶', '袁去华', '涛翻浪溢。\n调停得、似饧似蜜。\n试一饮、风生两腋。\n更烦襟顿失。\n雾衫儿袖窄。\n出纤纤、自传坐客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9440, '金蕉叶', '袁去华', '行思坐忆。\n知他是、怎生过日。\n烦恼无、千万亿。\n诮将做饭吃。\n旧日轻怜痛惜。\n却如今、怨深恨极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9441, '金蕉叶', '袁去华', '江枫半赤。\n雨初晴、雁空绀碧。\n爱篱落、黄花秀色。\n带零露旋摘。\n向晚西风淡日。\n发萧萧、任从帽侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9442, '金蕉叶', '袁去华', '沈烟篆曲。\n可庭轩、翠梧荫绿。\n挂晚景、寒林数幅。\n对冰盘莹玉。\n印枕娇红透肉。\n眼偷垂、睡犹未足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9443, '清平乐', '袁去华', '嫩凉新霁。\n明月光如洗。\n长笛一声烟际起。\n人在危楼独倚。\n夜深风露娟娟。\n抱琴谁和流泉。\n只有乘鸾仙子，见人愁绝无眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9444, '清平乐', '袁去华', '春愁错莫。\n风定花犹落。\n斗草踏青闲过却。\n乳燕鸣鸠自乐。\n行人江北江南。\n满庭萱草毵毵。\n且恁亡忧可矣，只他怎解宜男。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9445, '清平乐', '袁去华', '移商换羽。\n花底流莺语。\n唱彻秦娥君且住。\n肠断能消几许。\n劝觥斜注微波。\n真情著在谁那。\n只怕如今归去，酒醒无奈愁何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9446, '清平乐', '袁去华', '长条依旧。\n不似章台柳。\n见客入来和笑走。\n腻脸羞红欲透。\n桃花流水茫茫。\n归来愁杀刘郎。\n尽做风情减尽，也应未怕颠狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9447, '清平乐', '袁去华', '春衫袖窄。\n烛底横波溢。\n困倚屏风无气力。\n故故停歌驻拍。\n夜深满劝金杯。\n曲中偷送情来。\n归去十分准拟，今宵梦里阳台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9448, '清平乐', '袁去华', '争妍占早。\n只有梅同调。\n紫晕丁香青盖小。\n比似横枝更好。\n日烘锦被熏香。\n老夫恼得颠狂。\n把酒花前一笑，醉乡别有风光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9449, '柳梢青', '袁去华', '草底虫吟。\n烟横水际，月澹松阴。\n荷近香浓，竹深凉早，销尽烦襟。\n发稀浑不胜簪，更客里、吴霜暗侵。\n富贵功名，本来无意，何况如今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9450, '柳梢青', '袁去华', '白鹭洲前，乌衣巷口，江上城郭。\n万古豪华，六朝兴废，潮生潮落。\n信流一叶飘泊。\n叹问米、东游计错。\n老眼昏花，吴山何处，孤云天角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9451, '柳梢青', '袁去华', '天接沧浪。\n晴虹垂饮，千步修梁。\n万顷玻璃，洞庭之外，纯浸斜阳。\n西风劝我持觞。\n况高栋、层轩自凉。\n饮罢不知，此身归处，独咏苍茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9452, '柳梢青', '袁去华', '一水萦回。\n参天古木，夹岸苍崖。\n三十三年，客星堂上，几度曾来。\n眼看变化云雷。\n分白首、烟波放怀。\n细细平章，钓台毕竟，高似云台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9453, '菩萨蛮', '袁去华', '流苏宝帐沈烟馥。\n寒林小景银屏曲。\n睡起鬓云松。\n日高花影重。\n沈吟思昨梦。\n闲抱琵琶弄。\n破拨错成声。\n春愁著莫人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9454, '菩萨蛮', '袁去华', '重湖草木威名熟。\n儿童犹唱平郴曲。\n宴寝静。\n恩波湘水深。\n举头天尺五。\n稳步烟霄去。\n三柱黑头公。\n朔庭谈笑空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9455, '菩萨蛮', '袁去华', '木犀开遍芙蓉老。\n东篱独占秋光好。\n还记笑春风。\n新妆相映红。\n莫嫌彭泽令。\n不似刘郎韵。\n把酒赋新诗。\n花前知是谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9456, '菩萨蛮', '袁去华', '西风送雨鸣庭树。\n嫩寒先到孤眠处。\n愁极梦频惊。\n马嘶天渐明。\n千林枫叶赤。\n寒事催刀尺。\n树杪又斜阳。\n迢迢归路长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9457, '思佳客', '袁去华', '把酒听歌始此回。\n流莺花底语徘徊。\n神仙也许人间见，腔调新翻辇下来。\n银烛，玉山颓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9458, '思佳客', '袁去华', '飞燕双双掌上身。\n花光纷艳晚妆新。\n纤腰妙舞萦回雪，皓齿清歌遏住云。\n欢卜夜，座添春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9459, '思佳客', '袁去华', '宝阁珠宫夜未央。\n嫌迟怕晚不成妆。\n乞求乌鹊填河汉，已早玉绳低建章。\n笼月烛，闭云房。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9460, '浣溪沙', '袁去华', '庭下丛萱翠欲流。\n梁间双燕语相酬。\n日长帘底篆烟留。\n金勒去遥芳草歇，玉箫吹罢紫兰秋。\n一年春事只供愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9461, '浣溪沙', '袁去华', '玉骨冰肌比似谁。\n淡妆浅笑总相宜。\n一枝清绝照涟漪。\n客意无聊花亦老，风烟错莫雨垂垂。\n溪边立马断肠时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9462, '浣溪沙', '袁去华', '一夕高唐梦里狂。\n云情雨意两茫茫。\n袖间依约去年香。\n乳燕鸣鸠闲院落，垂杨芳草小池塘。\n墙梢冉冉又斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9463, '山花子', '袁去华', '雾阁云窗别有天。\n丰肌秀骨净娟娟。\n独立含情羞不语，总妖妍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9464, '蝶恋花', '袁去华', '细雨斜风催日暮。\n一梦华胥，记得惊人句。\n雾阁云窗歌舞处。\n翠峰青嶂无重数。\n解佩江头元有路。\n流水茫茫，尽日无人渡。\n一点相思愁万缕。\n几时却跨青鸾去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9465, '蝶恋花', '袁去华', '十二峰前朝复暮。\n空忆兰台，公子高唐句。\n断雨残云无觅处。\n古来离合归冥数。\n咫尺明河无限路。\n牛女佳期，犹解年年渡。\n细写罗笺情缕缕。\n雁飞不到谁将去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9466, '惜分飞', '袁去华', '平日悲秋今已老。\n细看秋光自好。\n风紧寒生早。\n漫将短发还吹帽。\n寂寞东篱人不到。\n只有渊明醉倒。\n一笑留残照。\n世间万事蝇头小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9467, '惜分飞', '袁去华', '雨过残阳明远树。\n树底鸣蝉无数。\n临水人家住。\n靠西便入江南路。\n曲径通幽深几许。\n翠竹短窗无暑。\n小立凭肩语。\n个中曾是孤眠处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9468, '鹊桥仙', '袁去华', '明眸皓齿，丰肌秀骨，浑是揉花碎玉。\n十分心事有谁知，暗恼得、愁红怨绿。\n残云断雨，不期而会，也要天来大福。\n若还虚度可怜宵，便做下、来生不足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9469, '鹊桥仙', '袁去华', '牛郎织女，因缘不断，结下生生世世。\n人言恩爱久长难，又不道、如今几岁。\n眼穿肠断，一年今夜，且做不期而会。\n三杯酒罢闭云房，管上得、床儿同睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9470, '诉衷情', '袁去华', '荷花风细竹娟娟。\n新浴晚凉天。\n钩帘坐期素月，相对理朱弦。\n歌扇底，舞裙边。\n旧因缘。\n憎模样，别没包弹，只欠心坚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9471, '诉衷情', '袁去华', '晓来犹自雨冥冥。\n投晚却能晴。\n娥为谁著意，洗得十分明。\n人自老，兔长生。\n酒徐倾。\n杯行到手，休更推辞，转眼参横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9472, '相思引', '袁去华', '皓齿清歌绝代音。\n眼波斜处寄情深。\n东风吹散，云雨杳难寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9473, '相思引', '袁去华', '晓监燕脂拂紫绵。\n未梳掠髻云偏。\n日高人静，沈水袅残烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9474, '点绛唇', '袁去华', '楼槛凌风，四边浑是青山绕。\n水空相照。\n天末归帆小。\n家在江南，三径都荒了。\n何时到。\n暗尘扑帽。\n应被渊明笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9475, '点绛唇', '袁去华', '徙倚虚檐，柳阴疏处看飞鸟。\n水平池沼。\n云影闲相照。\n点翰舒笺，字密蝇头小。\n还揉了。\n路长山杳。\n寄得愁多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9476, '减字木兰花', '袁去华', '微红嫩白。\n照水横枝初摘索。\n一梦扬州。\n客里相逢无限愁。\n黄昏院落。\n细细清香无处著。\n觅句持觞。\n鬓点吴霜不碍狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9477, '减字木兰花', '袁去华', '灯前初见。\n冰玉玲珑惊眼眩。\n艳溢香繁。\n绝胜溪边月下看。\n铅华尽洗。\n只有檀唇红不退。\n倾坐精神。\n全似当时一个人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9478, '归字谣', '袁去华', '归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9479, '归字谣', '袁去华', '归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9480, '玉团儿', '袁去华', '吴江渺渺疑天接。\n独著我、扁舟一叶。\n步袜凌波，芙蓉仙子，绿盖红颊。\n登临正要诗弹压。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9481, '青山远', '袁去华', '花竹亭轩。\n曲径通幽小洞天。\n翠帏苒苒隔轻烟。\n锁婵娟。\n画图初试春风面，消得东君著意怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9482, '玉楼春', '袁去华', '垂鬟初学窥门户。\n妙舞妍歌俱独步。\n引成密约笑言间，认得真情离别处。\n潘郎两鬓今如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9483, '踏莎行', '袁去华', '醉拈黄花，笑持白羽。\n秋江绿涨迷平楚。\n燕鸿曾寄去年书，汉皋不记来时路。\n天际归舟，云中烟树。\n兰成憔悴愁难赋。\n香囊钿合忍重看，风裳水佩寻无处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9484, '南柯子・南歌子', '袁去华', '秋晚霜初肃，江寒雾未收。\n西风吹老白苹洲。\n长笛一声、谁在水边楼。\n带绿枨新破，真醇酒旋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9485, '虞美人', '袁去华', '娟娟缺月梧桐影。\n云度银潢静。\n夜深檐隙下微凉。\n醒尽酒魂何处、藕花香。\n鹊桥初会明星上。\n执手还惆怅。\n莫嗟相见动经年。\n犹胜人间一别、便终天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9486, '忆秦娥', '袁去华', '月照席。\n不知天上今何夕。\n今何夕。\n鹊桥初就，玉绳低侧。\n暂时不见犹寻觅。\n那堪更作经年隔。\n经年隔。\n许多良夜，怎生闲得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9487, '长相思', '袁去华', '荷花香。\n竹风凉。\n万动声沈更点长。\n荧荧月半床。\n好思量。\n恶凄惶。\n独立西厢花拂墙。\n如今空断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9488, '东坡引', '袁去华', '陇头梅半吐。\n江南岁将暮。\n闲窗尽日将愁度。\n黄昏愁更苦。\n归期望断，双鱼尺素。\n念嘶骑、今到何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9489, '如梦令', '朱雍', '池上数枝开遍。\n临水幽香清浅。\n楼上欲黄昏，吹彻一声晴管。\n零乱。\n零乱。\n衣上残英都满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9490, '生查子', '朱雍', '帘栊月上时，寂寞东风里。\n又是立黄昏，梅影临窗绮。\n玉梅清夜寒，梦断还无寐。\n晓角一声残，吹彻人千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9491, '点绛唇', '朱雍', '轻艳盈盈，相逢曾向寒溪路。\n惜飘零处。\n无计禁春雨。\n素影参差，人在琼城步。\n危阑暮。\n年光催度。\n特地香风住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9492, '浣溪沙', '朱雍', '残日凭阑目断霞。\n寒林人静每归鸦。\n小梅春早压群花。\n一槛风声清玉管，数枝月影到窗纱。\n隔帘时度暗香些。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9493, '谒金门', '朱雍', '春太早。\n十二玉楼初晓。\n半额试妆深院悄。\n相逢何草草。\n临水幽香缥缈。\n彷佛淡妆窥照。\n恰值日边人未到。\n纷纷萦古道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9494, '好事近', '朱雍', '春事为谁来，枝上半留残雪。\n恰近小园香径，对霜林寒月。\n危阑凄断笛声长，吹到偏呜咽。\n最好短亭归路，有行人先折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9495, '清平乐', '朱雍', '雪开瑶径。\n素蕊迎春影。\n楼上玉声三弄定。\n无奈幽香翻阵。\n凌晨不事铅华。\n化工却付春花。\n流水残阳江上，清随月色低斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9496, '忆秦娥', '朱雍', '风萧萧。\n驿亭春信期春潮。\n期春潮。\n黄昏浮动，谁在江皋。\n碧云冉冉横溪桥。\n琼车未至馀香飘。\n馀香飘。\n一帘疏影，月在花梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9497, '亭前柳', '朱雍', '拜月南楼上，面婵娟、恰对新妆。\n谁凭阑干处，笛声长。\n追往事，遍凄凉。\n看素质、临风消瘦尽，粉痕轻、依旧真香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9498, '亭前柳', '朱雍', '伫立东风里，放纤手、净试梅妆。\n眉晕轻轻画，远山长。\n添新恨，更凄凉。\n尝忆得、驿亭人别後，寻春去、尽是幽香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9499, '亭前柳', '朱雍', '养就玄霜圃，问东君、曾放瑶英。\n回首蓝桥路，遍琼城。\n横斜影，照人明。\n飘香信、玉溪仙佩晚，同新月、步入西清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9500, '十二时慢', '朱雍', '粉痕轻、谢池泛玉，波暖琉璃初暖。\n睹靓芳、尘冥春浦，水曲漪生遥岸。\n麝气柔、云容影淡，正日边寒浅。\n闲院寂，幽管声中，万感并生，心事曾陪琼宴。\n春暗南枝依旧，但得当时缱绻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9501, '塞孤', '朱雍', '雪江明，练静波声歇。\n玉浦梅英初发。\n隐隐瑶林堪乍别。\n琼路冷，云阶滑。\n寒枝晚、已黄昏，铺碎影、留新月。\n向亭皋、一任风冽。\n歌起郢曲时，目断秦城阙。\n远道冰车清彻。\n追念酥妆凝望切。\n淡伫迎佳节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9502, '八声甘州', '朱雍', '听漏永，洗银林、梅英半寒收。\n正蟾辉舒粉，云容缕色，切近妆楼。\n人在东风伫立，悄悄独凝眸。\n多少横斜影，萦绕江流。\n只有清香暗度，堕髻簪珥玉，曾赋清游。\n认瑶车冰辙，佳致肯延留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9503, '迷神引', '朱雍', '白玉楼高云光绕。\n望极新蟾同照。\n前村暮雪，霁梅林道。\n涧风平，波声渺。\n喜登眺。\n疏影寒枝颤，太春早。\n临水凝清浅，靓妆巧。\n瘦体伤离，向此萦怀抱。\n觉璧华轻，冰痕小。\n倦听塞管，转呜咽，令人老。\n素光回，长亭静，无尘到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9504, '瑶台第一层', '朱雍', '西母池边宴罢，赠南真、步玉霄。\n绪风和扇，冰华发秀，雪质孤高。\n汉陂澄练影，问是谁、独立江皋。\n便凝望，认壶中圭璧，天上琼瑶。\n清标。\n曾陪胜赏，坐忘愁解使尘销。\n况双成、与乳丹点染，都付香梢。\n寿妆酥冷，郢韵佩举，麝卷云绡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9505, '西平乐', '朱雍', '夜色娟娟皎月，梅玉供春绪。\n不使铅华点缀，超出精神淡伫。\n休妒残英如雨。\n清香眷恋，只恐随风满路。\n散无数。\n江亭暮。\n鸣佩语。\n正值忽忽乍别，天远瑶池缟毂，好趁飞琼去。\n忍孤负、瑶台伴侣。\n琼肌瘦尽，庾岭零落，空怅望、动情处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9506, '梅花引', '朱雍', '梅亭别。\n梅亭别。\n梅亭回首都如雪。\n粉融融。\n月。\n月上小车，归去小楼空。\n当时曾傅新妆薄。\n而今一任花零落。\n朝随风。\n朝随风。\n竹外孤根，犹与幽径通。\n长相忆。\n无消息。\n庾岭沈沈云暗碧。\n玉痕惊。\n对离情。\n无奈水遥天阔、隔琼城。\n年来素袂香不灭。\n此心无限凭谁说。\n夜绵绵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9507, '笛家弄・笛家', '朱雍', '质仙姿，缟袂清格，天然疏秀。\n静轩烟锁黄昏後。\n影瘦零乱，艳冷珑璁，雪肌莹暖，冰枝萦绣。\n更赋风流，几番攀赠，细拈香盈手。\n与东君、叙暌远，脉脉两情有旧。\n立久。\n阆苑凝夕，瑶窗淡月，百寻芳，醉玉谈群，千锺酹酒。\n向此，是处难忘瘦花，送远何劳垂柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9508, '玉女摇仙佩', '朱雍', '灰飞谷，佩解江干，庾岭寒轻梅瘦。\n水面吞蟾，山光暗斗。\n物色盈枝依旧。\n凭暖危阑久。\n有清香旖旎，却沾襟袖。\n赋情□、窥人艳冷，更是殷勤，忍重回首。\n谁知道，春归院落，缤纷雪飞鸳。\n须谢化机爱惜，碎璧铺酥，肯把飞英。\n念念瑶珂，乘飙烟浦，送别犹携纤手。\n馥郁盈芳酒。\n临妆罢、一点眉峰伤皱。\n又只恐、□收梦断，管凄风怨，晓催银漏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9509, '鹧鸪天', '晁公武', '笑擘黄柑酒半醒。\n玉壶金斗夜生冰。\n开窗尽见千山雪，雪未消时月正明。\n兰烬短，麝煤轻。\n画楼钟鼓已三更。\n倚栏谁唱清真曲，人与梅花一样清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9510, '少年游', '林仰', '霁霞散晓月犹明。\n疏木挂残星。\n山径人稀，翠萝深处，啼鸟两三声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9511, '虞美人', '邵伯雍', '玉壶满插梅梢瘦。\n帘幕轻寒透。\n从今春恨满天涯。\n月下几枝疏影、透窗纱。\n锦城咫尺如千里。\n乍别难成寐。\n孤眠半晌断人肠。\n夜静分明全似、那人香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9512, '念奴娇', '黄中辅', '炎精中否，叹人材委靡，都无英物。\n胡马长驱三犯阙，谁作长城坚壁。\n万国奔腾，两宫幽陷，此恨何时雪。\n草庐三顾，岂无高卧贤杰。\n天意眷我中兴，吾皇神武，踵曾孙周发。\n河海封疆俱效顺，狂虏何劳灰灭。\n翠羽南巡，叩阍无路，徒有冲冠发。\n孤忠耿耿，剑冷浸秋月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9513, '满庭芳', '黄中辅', '快磨三尺剑，欲斩佞臣头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9514, '瑞鹤仙', '郑闻', '醉归来，不悟人间天上，云雨难寻旧迹。\n但馀香、暗著罗衾，怎生忘得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9515, '鹊桥仙', '刘望之', '只应将巧畀人间，定却向、人间乞取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9516, '如梦令', '刘望之', '休絮。\n休絮。\n我自明朝归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9517, '好事近', '程大昌', '岁岁做生朝，只是儿孙捧酒。\n今岁丝纶茶药，有使人双授。\n圣君作事与天通，道有便真有。\n老去不能宣力，只民编分寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9518, '好事近', '程大昌', '我里比侨居，不欠山青水绿。\n只恨风冲雁序，使分飞隈澳。\n只今一苇视苕溪，见天伦雍睦。\n此去春浓絮起，应翻成新曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9519, '好事近', '程大昌', '自涉希寿来，疑道无多岁月。\n昨夜风吹好梦，报前途康吉。\n石桥坚壮跨黄河，不用资舟楫。\n管取身心安泰，阅椿龄千百。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9520, '减字木兰花', '程大昌', '桑弧标吉。\n做了生朝逾七十。\n子又生孙。\n阶砌芝兰欲满门。\n今年定好。\n春腊之交诞婴少。\n玉烛气中。\n寿富康宁四序同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9521, '念奴娇', '程大昌', '海角怀人，长误喜、籁籁敲帘风竹。\n命驾翩然，谁信道、不怕溪山回曲。\n榻拂凝尘，香笼清宴，尘柄从挥玉。\n好音闻耳，慰心何啻跫足。\n犹记一桂专秋，创开殊选，倒峡馀词力。\n往事茫茫十换岁，却共天涯。\n已分成翁，翘观赐带，上拥通仙录。\n休贪泉石，贤台闻用金筑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9522, '南歌子', '程大昌', '每月冰轮转，常疑桂影摇。\n封姨特地借今宵。\n万水一规光景、湛寒瑶。\n圆处应无恨，君胡不自聊。\n谁家隐隐度晴箫。\n莫是素娥仙玉、会丛霄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9523, '南歌子', '程大昌', '才出沧溟底，旋明紫岫腰。\n玉光漫漫涌层潮。\n上有乘流海贾、卧吹箫。\n更上云台望，翻牵旅思遥。\n我生何许著箪瓢。\n却向天涯起舞、影萧萧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9524, '南歌子', '程大昌', '韵致撩诗客，风流出酒家。\n长绳为驻日车斜。\n且向春香玉色、占生涯。\n细按歌珠串，从宝髻鸦。\n花应笑我鬓双华。\n偏向西阶吹馥、侑流霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9525, '点绛唇', '程大昌', '春草池塘，茸茸短碧通芳信。\n更饶华润。\n不解膏霜鬓。\n池上诗翁，别带超遥韵。\n阳和进。\n香苞翠晕。\n物物皆沾分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9526, '万年欢', '程大昌', '老钝迂疏，尽世间乐事，不不觑。\n痴向韦编，根究卦爻来处。\n浑沌包中天地。\n谢东家、从头指示。\n便和那、八八机关，并将匙钥分付。\n行年数、六十四。\n把一年一卦，恰好相拟。\n妙道生生，既济还存未济。\n身原河图比似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9527, '水调歌头', '程大昌', '坐上羽觞，水际洧衣褰。\n适兹胜赏，风轻云薄有情天。\n不用船舷悲唱，真俯阑干小海，乐事可忘年。\n莫向歌珠里，却叹鬓霜鲜。\n送朝潮，迎夕汐，思茫然。\n知他禊饮，此地过了几千千。\n既有相催春夏，自解转成今古，谁後更谁前。\n堪笑兴怀客，不似咏归川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9528, '水调歌头', '程大昌', '红树迎风舞，彷佛采衣褰。\n云容应为，虞侍分付（下缺）。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9529, '汉宫春', '曹冠', '一品天香。\n似蕊真仙质，宫额新妆。\n先春为传信息，压尽群芳。\n化工著意，赋阳和、欺雪凌霜。\n应自负，孤标介洁，岁寒独友松篁。\n因念广平曾赋，爱浮香胧月，疏影横窗。\n真堪玉堂对赏，琼苑依光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9530, '凤栖梧・蝶恋花', '曹冠', '魏紫姚黄凝晓露。\n国艳天然，造物偏锺赋。\n独占风光三月暮。\n声名都压花无数。\n蜂蝶寻香随杖屦。\n莺声，似劝游人住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9531, '凤栖梧・蝶恋花', '曹冠', '桂棹悠悠分浪稳。\n烟幕层峦，绿水连天远。\n赢得锦襄诗句满。\n兴来豪饮挥金碗。\n飞絮撩人花照眼。\n天阔风微，燕外晴丝卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9532, '凤栖梧・蝶恋花', '曹冠', '昨夜西畴新足雨。\n玉露金飙，著意鏖残暑。\n画阁登临凝望处。\n馀霞晚照明烟浦。\n闲是闲非知几许。\n物换星移，风景都如故。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9533, '凤栖梧・蝶恋花', '曹冠', '桃杏争妍韶景媚。\n雨霁烟轻，山色蓝翠。\n绿竹青松依涧水。\n了无一点尘埃气。\n忙里偷闲真得计。\n乘兴携壶，文饮欣同志。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9534, '夏初临', '曹冠', '琴拂虞薰，月裁班扇，麦秋槐夏清和。\n笋变琅，绛榴细蹙香罗。\n绿云初展圆荷。\n见金鳞、戏跃清波。\n山丹舒艳，葵花映日，萱草成窠。\n浮云富贵，出处无心，好天风月，如意偏多。\n功名事业，壮怀岜肯蹉跎。\n待拥雕戈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9535, '夏初临', '曹冠', '水榭风台，竹轩梅径，双溪新创名园。\n极目遐观，碧岭敛散瑶烟。\n柳塘风皱清涟。\n烂红云、花岛争妍。\n艳妆佳丽，相携笑歌，学弄秋千。\n遨头多暇，命友寻芳，赏心行乐，物态熙然。\n偎香拾翠，雅宜飞盖联翩。\n满劝金船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9536, '夏初临', '曹冠', '翠入烟岚，绿铺槐幄，薰风初扇微和。\n茂樾扶疏，绛榴花映庭柯。\n瀑泉飞下层坡。\n间新篁、夹迳青莎。\n良辰佳景，登临隽游，清兴何多。\n流觞高会，不减兰亭，感怀书事，聊寄吟哦。\n升沈变化，任它造物如何。\n蹑磴攀萝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9537, '风入松', '曹冠', '瑶烟敛散媚晴空。\n云淡奇峰。\n澄江金斗平波面，扁舟载、蓑笠渔翁。\n仿佛辋川图上，依稀苕溪中。\n舂锄掠水浪花重。\n飞傍芦丛。\n绮霞斜映征鸿影，供吟毫、佳景无穷。\n顿起骑鲸游兴，泠然欲御清风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9538, '霜天晓角', '曹冠', '小雨。\n轻烟舞曳风。\n林椒高低疏密，依浅濑、媚遥峰。\n浴鹭水溶溶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9539, '霜天晓角', '曹冠', '浦溆凝烟。\n谁家女采莲。\n手拈荷花微笑，传雅令、侑清欢。\n擘叶劝金船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9540, '霜天晓角', '曹冠', '水亭清绝。\n拥翠环林樾。\n湘簟宾筵乘兴，玉壶酒、漾冰雪。\n宝兽沈烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9541, '喜朝天・踏莎行', '曹冠', '绣水雕栏，绮霞邃宇。\n薰风飒至清无暑。\n花间休唱遏云歌，枝头且听娇莺语。\n景物撩人，悠然得句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9542, '喜朝天・踏莎行', '曹冠', '翠老红稀，歌慵笑懒。\n溟烟雨秋千院。\n芹泥带湿燕双飞，杜鹃啼诉芳心怨。\n座客分题，传觞迭劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9543, '浣溪沙', '曹冠', '翠带千条蘸碧流。\n多情不解系行舟。\n章台惜别恨悠悠。\n湿雨伤春眉黛敛，倚风无力舞腰柔。\n丝丝烟缕织离愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9544, '浣溪沙', '曹冠', '槐柳风微轩槛凉。\n芙蕖绿叶映池光。\n几多飞盖拥红妆。\n泉试云龙花乳泛，袖笼宝鼎水沈香。\n绞楸戏战赌霞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9545, '浣溪沙', '曹冠', '雁字鳞差印碧空。\n淡云萦缕媚遥峰。\n悠扬舒卷逐西风。\n烟锁绿杨深院静，花前寓意劝金锺。\n凤箫一曲月明中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9546, '朝中措', '曹冠', '春芽北苑小方圭。\n碾畔玉尘飞。\n金箸春葱击拂，花瓷雪乳珍奇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9547, '朝中措', '曹冠', '更阑月影转瑶台。\n歌舞下香阶。\n洞府归云缥缈，主宾清兴徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9548, '念奴娇', '曹冠', '蜀川三峡，有高唐奇观，神仙幽处。\n巨石岩临积水，波浪轰天声怒。\n十二灵峰，云阶月地，中有巫山女。\n须臾变化，阳台朝暮云雨。\n堪笑楚国怀襄，分当严父子，胡然无度。\n幻梦俱迷，应感逢魑魅，虚言冥遇。\n仙女耻求媒，况神清直，岂可轻诬污。\n逢君之恶，鄙哉宋玉词赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9549, '念奴娇', '曹冠', '金飚替暑，觉庭梧湘簟，凉生秋意。\n玉露宵零仙掌洁，云卷碧天如水。\n银汉波澄，蟾光练静，依约山横翠。\n清商佳景，笑它宋玉憔悴。\n堪笑利锁名缰，向蜗牛角上，所争何事。\n四者难并人易老，惟有修真得计。\n荣悴循环，功名由命，达观明深旨。\n桂花同赏，莫辞通夕欢醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9550, '念奴娇', '曹冠', '天津仙客，话平蔡、曾把龙锺调戏。\n茅舍云林方隐迹，日日琴樽适意。\n鹏激天池，扶摇未便，尚敛摩云翅。\n经纶万卷，个中真负豪气。\n喜遇良友知心，登临酬唱，堪作词林瑞。\n况是韶华将近也，待约连宵春醉。\n对客挥毫，如虹浩饮，争涌如泉思。\n同寅他日，誓坚忠义相济。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9551, '念奴娇', '曹冠', '碧天如水，湛银潢清浅，金波澄澈。\n疑是娥将宝鉴，高挂广寒宫阙。\n林叶吟秋，帘栊如画，丹桂香风发。\n年年今夕，庾楼此兴清绝。\n因念重折高枝，壮心犹郁，已觉生华发。\n好向林泉招隐处，时讲清游真率。\n乘兴歌欢，熙然朝野，何日非佳节。\n百杯千首，醉吟长对风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9552, '西江月', '曹冠', '仙掌初零玉露，清商乍肃金飚。\n回环高阁桂香飘。\n元自广寒移到。\n绛蜡银蟾辉映，纶巾鹤氅逍遥。\n赏心乐事醉良宵。\n赢取开怀吟啸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9553, '西江月', '曹冠', '秋霁娥二八，寒光逼散浮云。\n小山丛桂吐清芬。\n犹带蟾宫风韵。\n因念两登仙籍，恩沾雨露方新。\n汝今妙岁已能文。\n早折高枝荣奋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9554, '西江月', '曹冠', '一派弯溪曲港，两山松干柽萝。\n寻幽乘兴泛烟波。\n时见白鸥飞过。\n炫日浪纹金影，连云岸草青莎。\n陶然一醉养天和。\n解意歌莺劝我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9555, '水调歌头', '曹冠', '我本方壶客，飘逸离凡尘。\n胸中万卷，谈笑挥翰墨通神。\n不慕巢由隐迹，不羡皋夔功业，出处两无心。\n坦荡灵台净，廛隐胜云林。\n念生平，喜旷达，事幽寻。\n登临舒啸，惟有风月是知音。\n雅爱金华仙洞，一派苍崖飞瀑，四序景常新。\n遐想赤松子，来为醒冲襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9556, '水调歌头', '曹冠', '造物巧锺赋，新腊报花期。\n江梅清瘦，只是洁白逞芳姿。\n我欲超群绝类，故学仙家繁杏，艳映横枝。\n朱粉腻香脸，酒晕著冰肌。\n玉堂里，山驿畔，最希奇。\n谁将绛蜡笼玉，香雪染胭脂。\n好向歌台舞榭，斗取红妆娇面，偎倚韵偏宜。\n羌管莫吹动，风月正相知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9557, '水调歌头', '曹冠', '游燕赏潭洞，舒啸对云峰。\n瀑泉飞下银汉，一水净涵空。\n前度刘郎诗句，祗咏丹青摹写，佳境未亲逢。\n争似我吟赏，携酒屡从容。\n濯尘缨，挥羽扇，快薰风。\n因思往古游者，清兴与今同。\n泉石因人轻重，岘首名传千古，登览赖羊公。\n陵谷有迁变，勋烈耀无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9558, '鹧鸪天', '曹冠', '我昔蓬莱侍列仙。\n梦游方悟绊尘缘。\n青春放浪迷诗酒，黄卷优游对圣贤。\n嘲水石，咏云烟。\n乘风欲往思泠然。\n要知昨夜方壶景，只在芸斋杖屦前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9559, '好事近', '曹冠', '蟾苑桂飘香，雅称娥珍惜。\n吹下一丛仙种，伴秋光岑寂。\n金风玉露嫩凉天，造化有消息。\n醉赏绿云金粟，媚枝头月色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9560, '好事近', '曹冠', '商素肃金飚，吹帽又逢佳节。\n乘兴登临舒啸，玩云林清绝。\n高歌横剑志平戎，酒量与天阔。\n更待醉归开宴，赏东篱明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9561, '好事近', '曹冠', '良月戒微寒，清夜祥烟馥郁。\n来报天庭喜事，现灯花金粟。\n芝书奎画下层霄，宣召想来促。\n它日玉堂挥翰，赐金莲花烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9562, '兰陵王', '曹冠', '晚云碧。\n松飞泉翠滴。\n双鱼畔、疑是永和，曲水流觞旧风物。\n波光映山色。\n时见轻鸥出没。\n壶天邃，修竹翠阴，虚籁吟风更幽寂。\n登临兴何极。\n上烟际危亭，彩笔题石。\n山中猿鹤应相识。\n对远景舒啸，壮怀豪逸。\n刘郎何在玩石刻。\n感往事陈迹。\n还忆。\n少年日。\n帅旗鼓文场，轩冕京国。\n如今老大机心息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9563, '宴桃源・如梦令', '曹冠', '西湖避暑棹扁舟。\n忘机狎白鸥。\n荷香十里供瀛洲。\n山光翠欲流。\n歌浩浩，思悠悠。\n诗成兴未休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9564, '宴桃源・如梦令', '曹冠', '廉纤小雨养花天。\n池光映远山。\n蕙兰风暖正暄妍。\n归梁燕翼偏。\n芳草碧，绿波涟。\n良辰近禁烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9565, '惜芳菲・惜分飞', '曹冠', '寓意登临诗与酒。\n豪气直冲牛斗。\n挥翰风雷吼。\n我生嗟在东坡後。\n流水高山琴静奏。\n莫笑知音未偶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9566, '江神子・江城子', '曹冠', '雨馀乾鹊报新晴。\n晓风清。\n听莺声。\n飞盖南园，游赏赋闲情。\n麦垅黄云堆万顷，收刈处，有人耕。\n淙漱玉涧泉鸣。\n翠峰横。\n碧云凝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9567, '蓦山溪', '曹冠', '年年九日，萸菊登高宴。\n今岁旅新丰，听征雁、吟蛩幽怨。\n行行游赏，邂逅得诗人，呼斗酒，发清吟，豪气凌霄汉。\n穷通默定，志士那兴叹。\n寓意醉乡游，且赢得、开怀萧散。\n功名外物，何必累冲襟，炼丹井，叱羊山，寻个修真伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9568, '蓦山溪', '曹冠', '鉴湖千顷，四序风光好。\n拨棹皱涟漪，极目处、青山缭绕。\n微茫烟霭，鸥鹭点菰蒲，云帆过，钓舟横，俱被劳生扰。\n知章请赐，独占心何小。\n风月本无私，同众乐、宁论多少。\n浮家泛宅，它日效陶朱，烹鲈鳜，酌松醪，吟笔千篇扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9569, '蓦山溪', '曹冠', '深秋澄霁，烟淡霜天晓。\n翠岘峻摩穹，有碧涧、清溪缭绕。\n鸣弦多暇，乘兴约登临，听水乐，玩丰碑，遐想东坡老。\n当年叔子，何事伤怀抱。\n名与此山俱，叹无闻、真成可笑。\n吾侪勋业，要使列云台，擒颉利，斩楼兰，混一车书道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9570, '蓦山溪', '曹冠', '潮生潮落，千古长如许。\n吴越旧争衡，览遗迹、英雄何处。\n胥神忠愤，贾勇助鲸波，湍砥柱，驾鳌峰，万骑轰鼍鼓。\n连天雪浪，直上银河去。\n击楫誓中流，剑冲星、醉酣起舞。\n丈夫志业，当使列云台，擒颉利，斩楼兰，雪耻歼狂虏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9571, '蓦山溪', '曹冠', '佳辰九，吹帽霜风峭。\n画阁势崔嵬，遍危阑、翠峰缭绕。\n茂林修竹，别是小壶天，烟霭淡，夕阳明，隐映溪光渺。\n匣琴流水，休恨知音少。\n长啸对西风，觉志气、凌云缥缈。\n传杯兴逸，高会继龙山，簪嫩菊，插红萸，相对年年好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9572, '东坡引', '曹冠', '凉飚生玉宇。\n黄花晓凝露。\n汀苹岸蓼秋将暮。\n登高开宴俎。\n传杯兴逸，分咏得句。\n思戏马、长怀古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9573, '水龙吟', '曹冠', '自来百卉千葩，算多有、异芬清绝。\n此花独赋，天然标致，於中超越。\n月脸妆匀，碧琼枝瘦，真仙风骨。\n向严寒雪里，千林冻损，锺和气、先春发。\n信是芳姿高洁。\n肯趋陪、游蜂戏蝶。\n玉堂静处，竹梢斜亚，凝烟媚月。\n一任严城上，单于奏、角声凄切。\n待芳心结实，和羹鼎鼐，收功须别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9574, '满江红', '曹冠', '味道韬光，伴耕钓、城南涧曲。\n吾不羡、炼丹金井，访仙王屋。\n清洁无瑕通隐显，满堂岂肯贪金玉。\n向北窗、高卧水风凉，槐阴绿。\n闲自赏，东篱菊。\n偏喜种，幽居竹。\n信巍然良贵，有荣无辱。\n外物随缘姑泛应，无心仕止常知足。\n喜圣时、协气屡丰年，西畴熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9575, '满江红', '曹冠', '日暖烟轻，竹梢映、花阴凌乱。\n微风皱、池光青碧，绿杨垂岸。\n艳杏墙头红粉媚，幽兰砌下飘香暖。\n称邀宾、明日去寻芳，频欢宴。\n光景速，浑如箭。\n醉梦里，春强半。\n且花前莫厌，玉杯频劝。\n一枕游仙方警悟，浮名自笑犹萦绊。\n醉挥毫、付与雪儿歌，娇莺啭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9576, '桂飘香', '曹冠', '律应清商，嫩凉生、金风乍飘林叶。\n玉兔腾精，光浸楼台，宛似广寒宫阙。\n远山横翠烟霏敛，鹊枝绕、蛩声凄切。\n气萧爽，一年好处，桂花时节。\n香压群芳妙绝。\n记蟾窟高枝，两曾攀折。\n思报君亲，何事壮怀犹郁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9577, '喜迁莺', '曹冠', '艳阳时序。\n向祓禊芳辰，登临仙府。\n碧水澄虚，修篁耸翠，夹径蕙兰香吐。\n春晚巧莺声碎，风卷飞红无数。\n凝望处，见桑村麦陇，竹溪烟浦。\n欢聚。\n须信道，游宦东西，易得成离阻。\n北海开尊，东山乘兴，四乐偷闲赢取。\n棋战新来常胜，诗瘦只因吟苦。\n心湛静，笑白云多事，等闲为雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9578, '八六子', '曹冠', '晚秋时。\n碧天澄爽，云何宋玉兴悲。\n对美景良辰乐事，采萸簪菊登临，共上翠微。\n堪嗟乌兔如飞。\n秉烛欢游须屡，传杯到手休辞。\n念戏马台存，隽游安在，且开怀抱，听歌金缕，从教下客疏狂落帽，也胜龌龊东篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9579, '木兰花慢', '曹冠', '念行藏在道，仕宦岂为谋身。\n自谤起营蝇，东山高卧，北海开尊。\n荣枯置之度外，得饶人处，谩也饶人。\n须信吾躬道义，巍然良贵中存。\n浮名。\n蜗角是非蚊。\n过耳总休论。\n且啸傲幽居，清风皓月，光景常新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9580, '柳梢青', '曹冠', '湖岸千峰。\n嵌岩隐映，绿竹青松。\n古寺东西，楼台上下，烟雾溟。\n波光万顷溶溶。\n人面与、荷花共红。\n拨棹归欤，一天明月，十里香风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9581, '哨遍', '曹冠', '壬戍孟秋，苏子夜游，赤壁舟轻漾。\n观水光、弥渺接遥天，月出於东山之上。\n与客同，清欢扣舷歌咏，开怀饮酒情酣畅。\n如羽化登仙，乘风独立，飘然遗世高尚。\n客吹箫、音韵远悠扬。\n怨慕舞潜蛟、动凄凉。\n自古英雄，孟德周郎。\n旧踪可想。\n噫，水与月兮，逝者如斯曷尝往。\n变化如一瞬，盈虚兮、莫消长。\n自不变而观，物我无尽，何须感物兴悲怅。\n夫天地之间，物各有主，惟同风月清赏。\n念江山美景岂可量。\n吾与子、乐之兴徜徉。\n听江渚、樵歌渔唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9582, '小重山', '曹冠', '风池荷雨盖翻。\n明珠千万颗，碎仍圆。\n龟鱼浮戏皱清涟。\n翠光映，垂柳幂瑶烟。\n幽兴寓薰弦。\n俗尘飞不到，小壶天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9583, '满庭芳', '曹冠', '榴艳喷红，槐阴凝绿，薰风初扇微凉。\n新荷舒盖，翠色映波光。\n时见金鳞戏跃，听莺声、巧啭垂杨。\n谁知我，身闲无累，对景自襄羊。\n南堂。\n清昼永，瑶琴横膝，芸帙披香。\n负气冲牛斗，操凛冰霜。\n吟笔通神掣电，乘高兴、鲸吸飞觞。\n情何憾，君亲未报，功业志难忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9584, '卜算子', '曹冠', '午枕梦游仙，身到蓬莱境。\n何事莺声啭绿杨，刚把人惊醒。\n乘兴对琴尊，寄傲吟光景。\n绕舍清阴映远岑，香篆槐堂静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9585, '粉蝶儿', '曹冠', '绕舍清阴，还是暮春天气。\n遍苍苔、乱红堆砌。\n问留春不住，春怎知人意。\n最关情，云杪杜鹃声碎。\n休怨春归，四时有花堪醉。\n渐红莲、艳妆依水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9586, '临江仙', '曹冠', '三洞烟霞多胜致，壶中别有登临。\n白鸥飞处晚云深。\n群峰罗户牖，空翠入衣襟。\n分得双溪楼上景，四时佳趣供吟。\n浩歌鲸饮酒频斟。\n莺花休恨别，风月是知音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9587, '浪淘沙', '曹冠', '清介百无求。\n民瘼怀忧。\n席珍藏器效前修。\n自负平戎经国略，壮气横秋。\n二纪叹淹留。\n寻壑经丘。\n醉吟适意且遨游。\n致主丹心犹未老，天意知不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9588, '定风波', '曹冠', '万个琅筛日影，两堤杨柳蘸涟漪。\n鸣鸟一声林愈静。\n吟兴。\n未曾移步已成诗。\n旋汲清湘烹建茗，时寻野果劝金卮。\n况有良朋谈妙理。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9589, '青玉案', '曹冠', '烟村茂樾湾溪畔。\n似远景、摹轻练。\n细草平沙骑款段。\n渔翁乃，却惊鸥鹭，飞起澄波面。\n班荆对饮垂杨岸。\n枝上莺歌如解劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9590, '使牛子', '曹冠', '晚天雨霁横雌霓。\n帘卷一轩月色。\n纹簟坐苔茵，乘兴高歌饮琼液。\n翠瓜冷浸冰壶碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9591, '望海潮', '曹冠', '会稽藩镇，舟车都会，槐庭燕寝凝香。\n禹穴旧踪，兰亭胜致，千岩万壑生光。\n舆颂美龚黄。\n庆慈闱戏彩，眉寿而康。\n寓兴西园，月台风榭赏群芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9592, '玉蝴蝶', '葛郯', '忆昨苕溪，惯弄五亭月笛，四水烟蓑。\n何事毗檀门外，马驻长坡。\n野花中、乱红杳霭，小桥外、叠翠嵯峨。\n且颜酡。\n但存长袖，舞倒婆娑。\n云何。\n主盟惠政，春行五马，月皎千波。\n赢得宾僚，听隔墙、无事高歌。\n帐烟寒、瑞麟影坠，帘雾细、宝鸭香多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9593, '念奴娇', '葛郯', '冯夷微怒，被鲛人水府，织成绡。\n何处飞来双白鹭，点破一溪寒玉。\n岸柳烟迷，海棠酒困，赢得春眠足。\n凭栏搔首，为谁消遣愁目。\n遥想居士床头，竹渠新雨，溜瓮中春。\n不惜千锺为客寿，倒卧南山新绿。\n晚月催归，春风留住，费尽纱笼烛。\n恍疑仙洞，梦游天柱林屋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9594, '念奴娇', '葛郯', '阳关西路，看垂阳客舍，嫩浮波。\n宝马嘶风人渐远，隐隐歌声戛玉。\n踏遍春山，归来高卧，笑濯沧浪足。\n孤鸿天际，断霞摇曳心目。\n香露飞入壶中，仙家九酝，酿百家。\n一朵巫阳休怅望，且看家山眉绿。\n歌罢风生，舞馀花颤，凤髓飘红烛。\n瑶台月冷，夜归斗挂银屋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9595, '洞仙歌', '葛郯', '楼十二，无限神仙侣。\n紫绂丹麾彩鸾驭。\n步虚声杳霭，碧落天高，微云淡，点破瑶阶白露。\n暗香来水阁，冰簟纱厨，一枕风轻自无暑。\n更上水精帘，斗挂阑干，银河浅、天孙将渡。\n终不如、归去在苕川，看千顷菰蒲，乱鸣秋雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9596, '洞仙歌', '葛郯', '藐姑仙子，天外谁为侣。\n八极浮游气为驭。\n看朝餐沆瀣，暮饮醍醐，瑶台冷，吹落九天风露。\n翠空云幕净，宝鉴无尘，碧树秋来暗消暑。\n残夜水明楼，影落寒溪，行人起、沙头唤渡。\n任角声、吹落小梅花，梦不到渔翁，一蓑烟雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9597, '满庭霜・满庭芳', '葛郯', '红叶飞时，青山缺处，云横秋影斜阳。\n凤凰旌节，何事到吾乡。\n要见大江东去，寒光静、水与天长。\n人争看，恩袍焕锦，新惹御炉香。\n满城，夸盛事，两邦鼓吹，几部笙簧。\n看万红千翠，簇拥云裳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9598, '满庭霜・满庭芳', '葛郯', '归去来兮，苕溪深处，上有苍翠千峰。\n月桥烟墅，家在五湖东。\n试觅桃花流水，鸡犬静、人迹才通。\n沙汀晚，一天云锦，飞下水精宫。\n两年，官事少，江梅雾暗，多稼云丰。\n把毗坛清梦，尽入诗筒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9599, '满庭霜・满庭芳', '葛郯', '归去来兮，家林不远，梦魂飞绕烟峰。\n洞房花木，只在小池东。\n谁道云深无路，小桥外、一径相通。\n功名小，从教群蚁，鏖战大槐宫。\n故人，书夜到，秫田百亩，已兆年丰。\n把乌程烂醉，不数郫筒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9600, '满庭霜・满庭芳', '葛郯', '归去来兮，心空无物，乱山不斗眉峰。\n夜禅久坐，窗晓日升东。\n已绝乘槎忘想，沧溪迥、不与河通。\n维摩室，从教花雨，飞舞下天空。\n何人，开宴豆，楚羹莼嫩，吴脍盘丰。\n看一声乃，落日收筒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9601, '满江红', '葛郯', '家住苕西，小池映、青山一曲。\n翠深里、猿呼鹤应，短墙低屋。\n麦影离离翻翠浪，泉声НН敲寒玉。\n怪夜来、有蚁出糟床，新绿。\n和月种，南阳菊。\n饶云买，淇园竹。\n任蛮争触战，世间荣辱。\n两目未消凭远恨，一筇费尽登山足。\n便棹舟、炊火荻花中，鲈鱼熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9602, '满江红', '葛郯', '卷尽珠帘，楚天迥、阑干几曲。\n最好是、瑶台归路，月翻银屋。\n深院数枰风入座，高楼一喷云横玉。\n看橘林、霜浅未全黄，犹悬绿。\n悠然意，渊明菊。\n真如指，国师竹。\n者是非识破，都无荣辱。\n不管浮生如蝶梦，从教万事添蛇足。\n坐西、一笑八千秋，蟠桃熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9603, '满江红', '葛郯', '郢客高歌，犹未睹、阳春一曲。\n多应是、连城有价，藏华屋。\n但使章台无异意，何妨一见邯郸玉。\n料锦囊、随客泛东溪，凌波绿。\n难独唱，篱边菊。\n谁与咏，阶前竹。\n想秋光不久，又成虚辱。\n过雁不知蛩有恨，行夔应笑无足。\n愿为予、落笔走盘珠，争圆熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9604, '念奴娇', '葛郯', '年来衰懒，渐无心赏遍，目前佳趣。\n寂寂墙阴春荠老，不到先生鼎俎。\n诗卷寻医，禅林结局，酒入昏田务。\n山头云气，为谁来往朝暮。\n犹有筇杖多情，扪萝踏石，堕半岩花雨。\n更向葭业摇短艇，惊起飞鸿烟渚。\n横玉凄清，焦桐古淡，一笑忘千虑。\n更阑人静，此声今在何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9605, '念奴娇', '葛郯', '蓬莱一岛，卧长烟千柳，西溪幽趣。\n苜蓿盘中初日上，不把充俎，和月栽松，饶云买石，只此为家务。\n倚楹清啸，断霞斜倚天暮。\n闻道块磊浇胸，槎丫肝肺，动笔端风雨。\n壁上潇湘秋一帧，影落荻花洲渚。\n暗浦潮生，寒矶雪化，无复风尘虑。\n此时渔父，短蓑合在何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9606, '江神子・江城子', '葛郯', '亭亭鹤羽戏芝田。\n看群仙。\n起青涟。\n绿盖红幢，千乘去朝天。\n留得瑶姬清夜舞，人与月，斗婵娟。\n凭阑有恨不堪言。\n倩谁传。\n曲声圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9607, '江神子・江城子', '葛郯', '粼粼白水护青田。\n想真仙。\n弄清莲。\n十里香风，吹下碧云天。\n月在草堂人未寝，松竹暗，水涓涓。\n夜阑何事悄无言。\n怨空传。\n事难圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9608, '鹧鸪天', '葛郯', '千树家园锁旧津。\n谁移数点在孤村。\n海仙探蕊禽留影，楚客穿花蝶舞魂。\n桥断港，水横门。\n残霞零落晚烟昏。\n只因留住三更月，暗里香来别是春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9609, '鹧鸪天', '葛郯', '万木家园雾暗津。\n不须踏影下前村。\n须知苕水云窟，自有罗浮冰雪魂。\n横水馆，倚楼门。\n参旗有约共黄昏。\n此中有句无人见，谁在樽前领略春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9610, '洞仙歌', '葛郯', '风摇丹髻，叶翦西岩树。\n岁律峥嵘又如许。\n看千峰倒影，浮动觥船，纱窗外，万幅鲛绡斗舞。\n五弦弹不尽，碧落天高，隐隐孤鸿向云度。\n送斜红敛尽，催上蟾钩，金风细，点破瑶阶白露。\n任笛声、吹残一帘秋，看人□栏□，暮云高处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9611, '洞仙歌', '葛郯', '橹声伊轧，影转云间树。\n试问扁舟在何许。\n正溪堂波动，沙渚苹轻，渔翁醉，隔岸蓑衣对舞。\n归来无一事，尊酒相逢，莫把光阴更虚度。\n看歌云杳霭，香雾轻盈，银河转，笑芙蓉晓露。\n纵西风、黄叶满庭秋，也不碍凝眸，乱山多处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9612, '洞仙歌', '葛郯', '丹青明灭，霜著谁家树。\n满眼风光向谁许。\n送寒鸦万点，流水孤村，归来晚，月影三人夜舞。\n金英秋已老，蜡缀寒葩，空里时闻暗香度。\n任一枝瓶小，数点钗寒，佳人笑，饮尽床头玉露。\n看纱窗、红日上三竿，把蝶影捎空，在花深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9613, '水调歌头', '葛郯', '年来惯行役，楚尾又吴头。\n餐霞吸露，何事佳处辄迟留。\n云听渔舟夜唱，花落牧童横笛，占尽五湖秋。\n胡床兴不浅，人在庾公楼。\n绣帘卷，曲阑暝，翠鬟愁。\n森罗万象，与渠诗里一时收。\n天设四桥风月，地会三州山水，邀我伴沙鸥。\n明朝起归梦，一枕过苹洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9614, '水调歌头', '葛郯', '帆腹饱天际，树发渺云头。\n翠光千顷，为谁来去为谁留。\n疑是吴宫西子，淡扫修眉一抹，妆罢玉奁秋。\n中流送行客，却立望层楼。\n风色变，堤草乱，浪花愁。\n跳珠翻墨，轰雷掣电几时收。\n应是阳侯薄相，催我胸中锦绣，清唱和鸣鸥。\n残霞似相贷，一缕媚汀洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9615, '水调歌头', '葛郯', '青铜昏水面，乌帽裹山头。\n风涛如此，天公作意巧相留。\n常记垂虹晚渡，卧看菰蒲烟雨，屈指十三秋。\n恍若华胥梦，无语下西楼。\n翠翻空，寒入座，不禁愁。\n五弦弹尽，隐隐天末暮虹收。\n欲伴渔翁钓艇，乃一声江上，寒碧点轻鸥。\n无人阻归兴，直欲迈长洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9616, '兰陵王', '葛郯', '乱烟簇。\n帘外青山渐肃。\n莲房静。\n荷盖半残，欲放清涟媚溪绿。\n凭高送远目。\n飞起沧洲雁骛。\n寒窗静，茶碗未深，一枕胡床画眠足。\n闲行问松菊。\n今□雨谁家，空对银烛。\n箫声忽下瑶台曲。\n看鹤舞风动，乌啼云起，何须舟内怨女哭。\n抱琴写幽独。\n情触。\n会相续。\n况节近中元，月浪翻屋。\n长鲸愁晓寒蟾促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9617, '柳梢青', '葛郯', '谢家池阁。\n翠桁香浓，琐纱窗薄。\n夜雨灯前，秋风笔下，与谁同乐。\n主人许我清狂，奈酒量、从来最弱。\n颠倒冠巾，淋漓衣袂，醒时方觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9618, '柳梢青', '葛郯', '空中雨阁。\n一段轻阴，翠铺林薄。\n橘内仙翁，棋边公子，共成清乐。\n主人有井留车，看席上、云轻柳弱。\n斗转檐头，鸡鸣窗外，无人知觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9619, '朝中措', '葛郯', '双锦领出西山。\n戎幕护旌旗。\n横槊春风百咏，临淮夜月千卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9620, '感皇恩', '葛郯', '风雨半摧残，一园花老。\n绿遍池塘夜来草。\n看花何处，莫被此花相恼。\n世间多少事，邯郸道。\n凭远下临，暗尘飞绕。\n数点烟中树、水村小。\n斜阳且住，为我花间留照。\n从教红满地，何须扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9621, '感皇恩', '葛郯', '花似镜中人，不堪衰老。\n空羡青青岸边草。\n多情消瘦，更被无情相恼。\n近来无限事，凭谁道。\n胡蝶满园，丛边空绕。\n睡起流莺过、语声小。\n琐窗危坐，更被玉蟾相照。\n夜阑梅影瘦，凭谁扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9622, '太平欢・念奴娇', '姚述尧2', '蕤宾奏律，正太平无事，欢娱时节，翘首箫台南望处，两两寿星明彻。\n和满乾坤，春回草木，瑞霭凝金阙。\n钧天齐奏，嵩呼隐隐三发。\n遥想帝里繁华，庆父尧子舜，赓歌胥悦。\n黼座传觞仙仗里，拜舞两阶英杰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9623, '满庭芳', '姚述尧2', '酒泛恩波，香凝瑞彩，笙歌鼎沸华堂。\n簪缨济济，拜手祝君王。\n好是重华盛世，康衢里、争颂陶唐。\n古今少，圣明相继，交劝万年觞。\n升平，无外事，穷天极地，俱沐恩光。\n更宫花齐戴，锦绣成行。\n愿捧蟠桃为寿，对瑶宴、一曲山香。\n尧天近，葵倾心切，相约共梯航。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9624, '念奴娇', '姚述尧2', '山城秋早，听画角吟风，晓来声咽。\n梦断华胥人乍起，冷浸一天霜月。\n灏气参横，尘埃洗尽，玉管濡冰雪。\n兴来吟咏，灵均谁谓今绝。\n闻道潇洒王孙，对黄花清赏，喜延佳客。\n一坐簪缨谭笑处，全胜东篱山色。\n酒兴云浓，诗肠雷隐，饮罢须臾设。\n醉归凝伫，此怀还与谁说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9625, '念奴娇', '姚述尧2', '霜风初过，正仙吏微吟，诗喉清咽。\n静对南山真赏处，秋後一亭花月。\n翠簇香，光摇今胜，玉女肌凝雪。\n寒城无伴，灿然还自奇绝。\n况有凫朋来，拼金钱都罄，晚酣留客。\n应笑陶潜孤负了，多少傲霜馀色。\n鲸饮方豪，龙饮未已，更著雕胡设。\n清欢无限，醉归犹记前说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9626, '念奴娇', '姚述尧2', '山城秋好，正西风淅淅，登高时候。\n杖倚徘徊凝望处，翠叠万山如绣。\n云绕禾场，沈戎马，田野欢声凑。\n琴堂无事，何妨同泛香溜。\n况有庭下黄花，遍河阳、尽把金钱铺就。\n一座簪缨谭笑里，尘脱风生清昼。\n饮罢龙山，诗成彭泽，灏气森星斗。\n醉归凝伫，美人时炷金兽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9627, '念奴娇', '姚述尧2', '江山清绝，正箫台花县，霜秋时候。\n寻胜登高环望处，碧瓦参差铺绣。\n五岫藏云，两溪吞月，古市渔盐凑。\n青帘斜扬，家家香泛丹溜。\n况是东鲁风流，看儒冠济济，垂天赋就。\n陶令从容官事了，把菊高吟闲昼。\n草鞠圜扉，香凝燕寝，豪饮挥金斗。\n公庭无事，珍祥休问驯兽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9628, '念奴娇', '姚述尧2', '芸堂春早，正芳苞紫萼，笼烟调雨。\n隐隐朝阳歌宴罢，拥出三千宫女。\n醉面匀红，香囊暗惹，鹊尾烟频炷。\n庐山佳致，依然都在庭宇。\n因念一种天香，当年岩谷下，想难俦侣。\n一旦呈祥都占断，阆苑琼林歌舞。\n瑞彩扶疏，锦笼绰约，兰蕙应羞妒。\n明朝胜赏，有谁同唱金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9629, '念奴娇', '姚述尧2', '早春时候，占百花头上，天香芳馥。\n寥廓寒分和气到，知是花神全毓。\n独步前林，挽回春色，素节辉冰玉。\n悠然一笑，便应扫尽粗俗。\n最爱潇洒溪头，孤标凛凛，不与凡华逐。\n自是玉堂深处客，聊寄疏篱茅屋。\n已报君王，为调金鼎，直与人间足。\n更看难老，岁寒长友松竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9630, '水调歌头', '姚述尧2', '碧落暮云卷，玉宇静无尘。\n宝阶露滴仙掌，秋气正平分。\n冷浸银河清澈，光射珠躔明灭，素女拥冰轮。\n今夕桂华满，疑是别乾坤。\n对清影，凌灏气，沃芳尊。\n凭高凝望，万里城阙尽铺银。\n偏照长门离恨，更揽西园诗思，何处不关情。\n此景年年好，莫惜醉归频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9631, '水调歌头', '姚述尧2', '三五半圆夜，二七素秋天。\n银河耿耿，中渡绛节会星。\n宝鹊喜传佳信，丹凤欢迎仙仗，瑞彩映珠躔。\n此意天长久，不比在人间。\n多情客，捧香饵，洁宾筵。\n殷勤拜舞，乞寿乞富乞团圆。\n宜与人人愿足，更看家家欢洽，喜气满江山。\n今夕莫辞醉，後会是来年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9632, '水调歌头', '姚述尧2', '上苑暮春好，烟雨正溟。\n桃蹊冷落无语，嫩绿翳残红。\n好是翠乍展，喜见玉英初坼，裁翦费春工。\n绰约更娇软，轻扬万条风。\n散清馥，翻素艳，照晴空。\n佳人羞妒，兢把粉质斗芳容。\n无限恼人风味，别有留春情韵，都付酒杯中。\n极目凭阑久，月影在墙东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9633, '水调歌头', '姚述尧2', '泽国正秋杪，微雨洒江滨。\n凭高一望，万里多稼总如云。\n芳野壤歌鼎沸，古市欢声辐凑，尽是泰平人。\n铃阁尽无事，桃李满公门。\n恨瓜戍，趣征驭，惜芳辰。\n高情耿耿，重别中夜沃清尊。\n不为阑亭感慨，莫作楚狂醉倒，谭笑自生春。\n明日送行处，忍顾翠眉颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9634, '洞仙歌', '姚述尧2', '金风玉露，正清秋初霁。\n天上星郎夜游戏。\n喜鹊儿、向织女报佳期，停机杼，草草便谐欢会。\n情深悄无寤，云雨须臾，刚被鸡人早惊起。\n念岁岁年年，今夕之前，两下里、千山万水。\n到今夕、相逢又葱葱，愿地久天长，永无抛弃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9635, '南歌子', '姚述尧2', '素节秋强半，嘉名久最宜。\n霜风簌簌下天涯。\n幸有佳朋、何惜共登危。\n月窟诸仙子，天宫两白眉。\n相逢不醉定无归。\n笑问黄花重约、是何时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9636, '南歌子', '姚述尧2', '天宇霜风净，雷封露气寒。\n群贤高宴胜龙山。\n中有仙翁绿鬓、更朱颜。\n北阙心犹壮，东篱兴为阑。\n年年身健足清欢。\n後会不妨重约、醉长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9637, '南歌子', '姚述尧2', '人在烟云里，山横碧落旁。\n望中缥缈是仙乡。\n幸有佳朋、何惜醉斜阳。\n公子传杯速，骚人练句忙。\n悠然此兴未能忘。\n似觉庭花、全胜去年黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9638, '南歌子', '姚述尧2', '瑞彩迎朝日，柔枝绕庆云。\n谁将仙种下天阍。\n却笑葵杯榴火、俗纷纷。\n色映蔷薇水，光浮琥珀尊。\n美人浴罢近黄昏。\n总把淡妆浓抹、斗芳芬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9639, '南歌子', '姚述尧2', '咳唾琼珠璀，精神冰玉寒。\n不求名利不谈玄。\n明月清风相对、自怡然。\n潇洒真仙隐，繁华小洞天。\n薰风飒飒度虞弦。\n更拥姬姜何惜、醉华年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9640, '南歌子', '姚述尧2', '宾宴亲尧日，薰弦动舜风。\n公馀无事乐年丰。\n多谢歌姬流盼、更情浓。\n气逼云天外，毫濡雪碗中。\n百篇斗酒兴何穷。\n却笑东山无语、醉花丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9641, '南歌子', '姚述尧2', '罗盖轻翻翠，冰姿巧弄红。\n晚来习习度香风。\n疑是华山仙子、下珠宫。\n柳外神仙侣，花间锦绣丛。\n竞将玉质比芳容。\n笑指壶天何惜、醉千锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9642, '南歌子', '姚述尧2', '金谷貂蝉侣，东山锦绣丛。\n管弦丝竹醉东风。\n漫逐流莺飞舞、乱红中。\n清尝吾人事，诗情我辈锺。\n藤萝欲上更筇。\n笑指壶天烟绕、斗城东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9643, '南歌子', '姚述尧2', '误入红莲幕，来依玉树丛。\n也将尘迹寄东风。\n忙里偷闲同到、此山中。\n迥野韶华丽，晴岚秀色锺。\n凭高凝望倦扶筇。\n喜见今年和气、满南东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9644, '南歌子', '姚述尧2', '雨过云峰净，天高水镜平。\n望中寸碧远山横。\n潇洒何郎相对、挹金觥。\n朱李沈寒碧，新瓜破玉英。\n浩然谭笑有馀情。\n醉舞何妨颓玉、倚飞琼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9645, '临江仙', '姚述尧2', '山县登高真胜事，满筵当代英奇。\n黄花无语笑东篱。\n龙山真鼠辈，巴岭漫羁栖。\n醉後风流情更好，笑谈落落珠玑。\n莫将乌帽任风吹。\n动容皆是舞，出语总成诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9646, '临江仙', '姚述尧2', '佳节喜逢长久日，翩翩凫朋来。\n霜清天宇绝纤埃。\n遥怜巴岭月，拟上曲江台。\n怀县从容留客宴，追欢正好传杯。\n使君归骑莫相催。\n更拼明日醉，未放菊花开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9647, '临江仙', '姚述尧2', '云度岩扉风振谷，迅雷惊起蛟龙。\n天威汹汹变晴空。\n搅翻银汉水，倾入宝莲宫。\n雪浪奔冲凌翠麓。\n陇头低挂双虹。\n人间热恼尽消融。\n此流长不断，万折竟朝东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9648, '临江仙', '姚述尧2', '万石家声夸第一，清材更美姿容。\n笑谈落落与谁同。\n烟分丹篆碧，香泛小槽红。\n准拟中秋圆月好，暮云忽翳晴空。\n共将清致敌西风。\n举头连玉兔，乘兴沃金锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9649, '临江仙', '姚述尧2', '材刃纵横森武库，箫台旧日梅仙。\n累陪簪盖醉花前。\n吴门归去後，一别动经年。\n曾到赤城真隐处，飘飘凤举龙蟠。\n勒回俗驾向长安。\n好将医国手，从此活人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9650, '临江仙', '姚述尧2', '橘绿橙黄秋正好，霜飙洗尽炎威。\n园林木落望中奇。\n俊游方得意，楚客为谁悲。\n况有风流文字饮，何妨同醉东篱。\n狂歌犹记少陵诗。\n地偏初衣，山拥更登危。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9651, '临江仙', '姚述尧2', '一去吴山三改火，我来两见寒梅。\n君今先向斗城回。\n尊前方重别，征骑莫相催。\n堪笑人生如逆旅，明年我亦言归。\n羡君平步到天涯。\n吴侬如有问，为我说归期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9652, '临江仙', '姚述尧2', '忆昨曾将明使指，轺车踏遍东城。\n重来游戏拥双旌。\n江山皆故部，英俊尽门生。\n杖策翩然归去也，送行满坐簪缨。\n尊前雨泪不胜情。\n曲终人散後，江上数峰青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9653, '浣溪沙', '姚述尧2', '乳酒初颁菊正黄。\n去年高宴近清光。\n朝回犹带御炉香。\n暂向花封陪客醉，已闻芝检促归装。\n昌黎宁许到潮阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9654, '浣溪沙', '姚述尧2', '与客相从谒谢公。\n芝田绛节拥仙翁。\n数枝桃杏斗香红。\n醉眼斜拖春水绿，黛眉低拂远山浓。\n此情都在酒杯中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9655, '浣溪沙', '姚述尧2', '两到蟾宫折桂枝。\n经文纬武拟康时。\n箫台仙隐漫游嬉。\n气宇棱棱吞梦泽，笑谈落落催珠玑。\n何妨相对沃金卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9656, '浣溪沙', '姚述尧2', '短棹翩翩绿一莎。\n碧潭深处几风波。\n晚来风定却高歌。\n千尺丝纶随卷放，数声玉笛足清和。\n蝇头名利奈伊何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9657, '鹧鸪天', '姚述尧2', '玉宇无尘露气清。\n凭高极目万山横。\n霜前白雁初传信，篱下黄花独有情。\n乌帽侧，紫萸馨。\n尊前醉舞拥飞琼。\n明年此会知何处，不是鄱江是帝城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9658, '鹧鸪天', '姚述尧2', '昨夜东风到海涯。\n繁红簇簇吐胭脂。\n恍疑仙子朝天罢，醉面匀霞韵更宜。\n欢未足，困相依。\n羞将兰麝污天姿。\n少陵可是风情薄，却为无香不作诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9659, '鹧鸪天', '姚述尧2', '几阵萧萧弄雨风。\n片云微破月朦胧。\n田家侧耳听鸣鹳，寰海倾心想卧龙。\n尧日近，舜云浓。\n圣仁天覆忍民穷。\n会看膏泽随车下，祗恐诗人句未工。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9660, '鹧鸪天', '姚述尧2', '凤阙朝回晓色分。\n彩霞轻拂绛衣新。\n炎乌影里年年好，碧玉枝头日日春。\n携翠，对芳尊。\n东君著意属诗人。\n夜深莫放西风入，频遣司花护锦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9661, '瑞鹧鸪', '姚述尧2', '司花著意惜春光。\n桃杏飘零此独芳。\n一抹霞红匀醉脸，恼人情处不须香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9662, '西江月', '姚述尧2', '红叶漫随风舞，黄花不畏霜凋。\n诗人把酒竞招招。\n更欲移尊籍草。\n醉里谪仙兴逸，夜深归骑声呶。\n孟公投辖未相饶。\n不放秋光便老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9663, '西江月', '姚述尧2', '嫩绿烟笼碎玉，繁红日护香绡。\n故人去後恨迢迢。\n独倚危楼情悄。\n脉脉望穷云杪，看看月上花梢。\n嫩添金鸭任烟消。\n杜宇一声春晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9664, '减字木兰花', '姚述尧2', '井梧飞早。\n一雁横空天更好。\n才子寻幽。\n争把新诗断送秋。\n浮生鸥没。\n莫为尘劳轻度日。\n倒载何妨。\n唱彻凉州月在旁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9665, '减字木兰花', '姚述尧2', '烟收云敛。\n极目遥岑三四点。\n过了重阳。\n篱下残花未褪黄。\n郑庄好客。\n故遣红妆飞大白。\n月满回廊。\n饮散歌阑已断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9666, '减字木兰花', '姚述尧2', '暗香清绝。\n不比寻常枝上雪。\n细叠冰绡。\n多谢天公快翦刀。\n仙姿楚楚。\n轻曳霓裳来帝所。\n淡拂宫妆。\n瑞脑重铺片片香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9667, '减字木兰花', '姚述尧2', '霜天奇绝。\n江上寒英重缀雪。\n簌簌轻绡。\n应是司花巧奏刀。\n东君清楚。\n故把疏枝来酒所。\n点点新妆。\n冷浸冰壶别有香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9668, '减字木兰花', '姚述尧2', '飞龙利见。\n前夜君王方锡宴。\n今日相逢。\n却向南阳起卧龙。\n果为霖雨。\n洗尽苍生炎夏苦。\n喜气匆匆。\n好向尊前醉晚风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9669, '减字木兰花', '姚述尧2', '天寒人静。\n啸倚胡床闲画永。\n春信初回。\n报道南枝昨夜开。\n沈沈庭院。\n独坐黄昏谁是伴。\n风过南墙。\n似觉天宫暗递香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9670, '减字木兰花', '姚述尧2', '薰风解愠。\n手握乾符躬揖逊。\n廊庙无为。\n天子亲传万寿卮。\n恩覃湛露。\n和气欢声均海宇。\n嵩岳三呼。\n父子唐虞今古无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9671, '减字木兰花', '姚述尧2', '琴堂无事。\n满酌金承帝祉。\n乐奏箫韶。\n更与封人共祝尧。\n君王万岁。\n岁岁今朝歌既醉。\n主圣臣贤。\n从此鸿图万万年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9672, '如梦令', '姚述尧2', '绰约冰姿无语。\n高步广寒深处。\n香露檀心，拟到素娥云路。\n仙去。\n仙去。\n莫学朝云暮雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9673, '如梦令', '姚述尧2', '雅淡轻盈如语。\n碧玉枝头娇处。\n钩月衬凌波，仿佛湘江烟路。\n凝伫。\n凝伫。\n不似梨花带雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9674, '如梦令', '姚述尧2', '龙焙初分丹阙。\n玉果轻翻琼屑。\n彩仗挹香风，搅起一瓯春雪。\n清绝。\n清绝。\n更把兽烟频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9675, '点绛唇', '姚述尧2', '潇洒寒林，玉丛遥映松篁底。\n凤簪斜倚。\n笑傲东风里。\n一种幽芳，自有先春意。\n香风细。\n国人争媚。\n不数桃和李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9676, '点绛唇', '姚述尧2', '金碧交辉，江陵千树天然富。\n寒林争秀。\n独向霜风後。\n写入冰纨，两两情何厚。\n同携久。\n凉生清画。\n香满佳人手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9677, '点绛唇', '姚述尧2', '夜桂飘香，西风淅淅寒窗悄。\n素娥相照。\n倍觉秋光好。\n花本无情，刚被诗情恼。\n知音少。\n为花歌笑。\n醉向花前倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9678, '点绛唇', '姚述尧2', '玉叶金英，倩谁移下蟾宫树。\n香风飘度。\n满院飞黄雨。\n独倚寒林，搜尽高人句。\n关情处。\n素娥无语。\n的枝头露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9679, '行香子', '姚述尧2', '天赋仙姿。\n玉骨冰肌。\n向炎威、独逞芳菲。\n轻盈雅淡，初出香闺。\n是水宫仙，月宫子，汉宫妃。\n清夸檐卜，韵胜酴。\n笑江梅、雪里开迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9680, '朝中措', '姚述尧2', '满城风雨近重阳。\n小院更凄凉。\n遥想东篱山色，今年花为谁黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9681, '南乡子', '姚述尧2', '秋水莹精神。\n靖节先生太逼真。\n谭麈生风霏玉屑，津津。\n爽气冷然欲浸人。\n一坐尽生春。\n满引琼觞已半醺。\n更把黄花寿彭祖，盈盈。\n数阕新声又遏云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9682, '忆秦娥', '姚述尧2', '珠帘深。\n玉人天上传清音。\n传清音。\n云横新雁，梅落寒林。\n□□□□□□□。\n□□□□□□□。\n□□□。\n谢家庭院，寿酒频斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9683, '丑奴儿・采桑子', '姚述尧2', '山城寂寞浑无绪，兀坐黄昏。\n多谢东君。\n先遣司花来报春。\n清标自是蓬莱客，冰玉精神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9684, '丑奴儿・采桑子', '姚述尧2', '晓来佳气穿帘幕，郁郁葱葱。\n宝鸭烟浓。\n戏采庭前玉树丛。\n肌肤绰约真仙子，王母宫中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9685, '醉落魄・一斛珠', '姚述尧2', '春回海角。\n望中佳气连云幕。\n晓来隐隐闻天乐。\n玉女金童，来奉瑶池约。\n东风已破蟠桃萼。\n霞觞荐寿更酬酢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9686, '阮郎归', '姚述尧2', '江村昨夜一枝梅。\n先传春信回。\n非烟非雾下瑶台。\n香风拂面来。\n云幕卷，日华开。\n祥光映上台。\n安舆从此步天街。\n君王赐寿杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9687, '归国谣・归国遥', '姚述尧2', '初夏好。\n雨过池塘荷盖小。\n绿阴庭院莺声悄。\n朱帘隐隐笙歌早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9688, '归国谣・归国遥', '姚述尧2', '春已去。\n墙外榴花红半吐。\n薰风习习生庭户。\n美人浴罢黄昏暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9689, '好事近', '姚述尧2', '水阁弄清风，黯黯满园肥绿。\n茶罢竹间携手，有佳人如玉。\n渊明三径已催归，名利几时足。\n遥想五云多处，奏南风一曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9690, '好事近', '姚述尧2', '梅子欲黄时，霖雨晚来初歇。\n谁在绿窗深处，把彩丝双结。\n浅斟低唱笑相偎，映一团香雪。\n□指墙头榴火，倩玉郎轻折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9691, '临江仙', '石敦夫', '窥檐蟾影白，照坐烛花红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9692, '水调歌头', '甄龙友', '西风新叶堕，南国九秋初。\n周天三百六十五度，片云无。\n上有迢迢河汉，下有滔滔江水，横载洞庭湖。\n一叶放流去，人在浑仪图。\n满虚空，张宝盖，缀明珠。\n玻璃为地，游戏乾象驾坤舆。\n烂醉蓬莱方丈，遍入华严法界，试问夜何如。\n北斗转魁柄，东海欲飞乌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9693, '南乡子', '甄龙友', '十月小阳春。\n放榜梅花作状元。\n重庆礼成三日後，生贤。\n第一龙飞不偶然。\n劝酒自弹弦。\n更著班衣寿老仙。\n见说海坛沙涨也，明年。\n此夜休嗔我近前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9694, '贺新郎', '甄龙友', '思远楼前路。\n望平堤、十里湖光，画船无数。\n绿盖盈盈红粉面，叶底荷花解语。\n斗巧结、同心双缕。\n尚有经年离别恨，一丝丝、总是相思处。\n相见也，又重午。\n清江旧事传荆楚。\n叹人情、千载如新，尚沈菰黍。\n且尽尊前今日醉，谁肯独醒吊古。\n泛几盏、菖蒲绿醑。\n两两龙舟争竞渡，奈珠帘、暮卷西山雨。\n看未足，怎归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9695, '霜天晓角', '甄龙友', '峨眉仙客。\n四海文章伯。\n来向东坡游戏，人间世、著不得。\n去国谁爱惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9696, '念奴娇', '范端臣', '寻常三五，问今夕何夕，婵娟都胜。\n天豁云收崩浪净，深碧琉璃千顷。\n银汉无声，冰轮直上，桂湿扶疏影。\n纶巾玉麈，庾楼无限清兴。\n谁念江海飘零，不堪回首，惊鹊南枝冷。\n万点苍山何处是，修竹吾庐三径。\n香雾云鬟，清辉玉臂，醉了愁重醒。\n参横斗转，辘轳声断金井。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9697, '念奴娇', '范端臣', '玉楼绛气，卷霞绡云浪，飞空蟾魄。\n人世江山惊照耀，烟霭鳌峰千尺。\n陆海蓬壶，银葩星晕，点破琉璃碧。\n有人吟笑，紫河香满晴陌。\n况是东府君侯，西清别骑，樽俎开华席。\n迤逦飞轮催杖履，入对青黎仙客。\n襦裤歌谣，升平风露，拼取金莲侧。\n梅花吹动，满城依旧春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9698, '虞美人', '韦能谦', '风清日晚溪桥路。\n绿暗摇残雨。\n闲亭小立望溪山。\n画出明湖深秀、水云间。\n漫郎疏懒非真吏。\n欲去无深计。\n功名英隽满凌烟。\n省事应须速上、五湖船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9699, '浣溪沙', '耿时举', '露压蔷薇金井栏。\n辘轳声断碧丝乾。\n辽阳无信带围宽。\n花落池塘春梦静，月生帘幕夜香寒。\n闲愁无力凭阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9700, '浣溪沙', '耿时举', '独鹤山前步药苗。\n青山只隔过溪桥。\n洞宫深处白云飘。\n碧井卧花人寂寞，画廊鸣叶雨潇潇。\n漫题诗句满芭蕉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9701, '满江红', '耿时举', '问月杯空，谪仙去、无人重举。\n兰台旧、扁舟乘兴，处留奇语。\n洞府初疑仙骨瘦，樽前尚爱纶巾舞。\n信前身、太白尚何疑，词高古。\n盟後会，偕真侣。\n黄叶渡，丹枫渚。\n道五湖烟浪，胜游溢浦。\n念我神闲鸥样度，似海山共去君应许。\n但只愁、岳牧要人□，撑住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9702, '喜迁莺', '耿时举', '暮春清昼。\n政莺啭夏林，棠阴初秀。\n鼓角欢雄，旌旗明灭，宝马又还西骤。\n山水六朝堪画，宫阙千门如绣。\n印悬斗。\n盛元戎小队，花间迎候。\n芳酎。\n为公寿。\n带雨梨花，未用啼红袖。\n玉帐风前，胡床月下，谈笑要清群丑。\n桃叶渡船应在，太白酒楼依旧。\n暂回首。\n看槐班爰立，沙堤成就。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9703, '念奴娇', '管鉴', '登高作赋，叹老来笔力，都非年少。\n古观重游秋色里，冷怯西风吹帽。\n千里江山，一时人物，迥出尘埃表。\n危阑同凭，皎然玉树相照。\n惆怅紫菊红萸，年年簪发、应笑人空老。\n北阙西江君赐远，难得一枝来到。\n莫话升沈，且乘闲暇，赢得清尊倒。\n饮酣归暮，浩歌声振林杪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9704, '念奴娇', '管鉴', '楚山万叠，怅高情、不比当年嵩少。\n官况全如秋淡薄，枉却尘侵乌帽。\n菊蕊犹青，茱萸未紫，节意凭谁表。\n故园何处，暮云低尽残照。\n追念往昔佳辰，尊前绝唱，未觉徐娘老。\n聚散悲欢回首异，今岁古台谁到。\n藉甚声名，难忘风味，何日重倾倒。\n交情好在，雁书频寄云杪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9705, '念奴娇', '管鉴', '寒梢冰破，问何人远寄、江南春色。\n似是天怜为客久，报我春归消息。\n茅舍疏篱，故园开处，两岁关山隔。\n天涯重见，向人风味如昔。\n谁念月底风前，当时青鬓、渐与花颜白。\n不恨一番花阴早，恨把年华虚掷。\n嚼蕊含香，攀条觅句，拼醉禁愁得。\n酒醒还是，梦魂数遍归驿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9706, '念奴娇', '管鉴', '两鬟娇小，向尊前、未省修蛾攒碧。\n唱得主人英妙句，气压三江七泽。\n病怯遐征，老添离抱，我是愁堆积。\n故园归梦，等闲吹堕南国。\n况是耐久交情，经年方幸，接从容辞色。\n告别匆匆聊共醉，惜此分阴如璧。\n锦瑟华堂，明朝回望，暮霭迷空隙。\n相思何处，风林月挂纤魄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9707, '水龙吟', '管鉴', '小舟横截西江，晓来风静无尘起。\n霜馀日暖，东君见效，梅梢春醉。\n壮观亭高，通幽径远，吸江临水。\n任全抛簿领，携家访古，清泉畔、疏阴里。\n楚蜀江山分处，望神京、三千馀里。\n才高命偶，功名休羡，纷纷馀子。\n强健身心，团栾尊酒，此游须记。\n便他年富贵，园林钟鼓，只如今是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9708, '水龙吟', '管鉴', '晓来密雪如筛，望中莹彻还如洗。\n梅花过了，东风未放，满城桃李。\n碎翦琼英，高林低树，巧装匀缀。\n更江山秀发，田畴清润，满眼是、丰年意。\n谁念危楼独倚。\n共飘零、茫茫天外。\n毫端句涩，杯中酒减，欢情难寄。\n天为凄凉，暂时遮尽，黄茅白苇。\n但神州目断，珠宫玉阙，缈三千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9709, '水调歌头', '管鉴', '平生五湖兴，梦想白苹洲。\n只今何处，卷帘波影漾风钩。\n况值晚天新霁，菱叶荷花如拭，香翠拥行舟。\n却为湖山好，牵思绕皇州。\n柳边堤，竹里阁，旧曾游。\n恍然重到，不知身世此淹留。\n且对碧梧修竹，领略好风凉月，大白与重浮。\n欲和凌云赋，佳思苦难酬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9710, '水调歌头', '管鉴', '凉意在何许，高柳荫汀洲。\n移船藕花深处，待得月如钩。\n一抹晚山残照，十顷醉红香绿，百列琼舟。\n浩歌激苍莽，豪气溢神州。\n泛芙蓉，依绿水，并英游。\n明年此会，可怜独是贾胡留。\n赖有瀛洲仙子，少驻云霄高步，相与慰沈浮。\n富贵傥来尔，有酒且相酬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9711, '水调歌头', '管鉴', '秋色浩无际，风露洗晴空。\n登临江山胜处，楼倚最高峰。\n好是夕阳低後，四野暮云齐敛，遮尽远山重。\n城郭参差里，烟树有无中。\n坐间客，才论斗，气如虹。\n挥毫万字，举双白眼送飞鸿。\n莫问梅仙丹灶，休觅山灵蕙帐，追忆采芝翁。\n便草凌云赋，归奏大明宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9712, '水调歌头', '管鉴', '一雨洗烦溽，天气爽如秋。\n江山佳处，眼明重见旧交游。\n去国三千馀里，俯视朝宗一水，共笑此生浮。\n幸我扁舟具，归欲问菟裘。\n叹君才，方进用，岂容休。\n銮坡凤沼，情知不为蜀人留。\n便恐升沈各异，後日相逢无处，别语易成愁。\n记取平安使，时访荻花洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9713, '水调歌头', '管鉴', '南雪不到地，今雪瑞非常。\n堆檐平砌，晚来风定转飞扬。\n浩荡乾坤无际，洗尽蛮烟瘴雾，和气遍遐荒。\n满眼丰年意，民共乐时康。\n倚琼楼，临玉树，举瑶觞。\n高吟低唱，从他减尽少年狂。\n且趁明年春好，整顿雨犁风箬，归去老农桑。\n唤起江南梦，先到水云乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9714, '水调歌头', '管鉴', '举俗爱重九，秋至不须悲。\n登临昔贤胜地，空愧主人谁。\n滚滚长江不尽，叠叠青山无数，千载揖高姿。\n况有贤宾客，同醉此佳时。\n坐间菊，青作袂，玉为肌。\n香英泛酒，风流绝胜酌酴。\n莫话龙山高会，只作东篱幽想，应有故人思。\n北望江南路，回首暮云披。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9715, '水调歌头', '管鉴', '举俗爱重九，我辈更锺情。\n良辰好景，赏心乐事古难并。\n正是朝廷闲暇，四序均调玉烛，一路庆丰登。\n况值循良守，酒与政俱成。\n倚危亭，持玉，泛金英。\n风高日淡，一天秋色共澄清。\n指点云间岳镇，寿与两宫齐久，天地永成平。\n岁岁同民乐，持此报君恩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9716, '满江红', '管鉴', '百罚深杯，都不记、归来时节。\n仿佛听、重城更鼓，催成离缺。\n江上愁心山敛翠，津头夜色沙如雪。\n渐中年、怀抱更深交，难为别。\n歌声缓，行云歇。\n尊酒散，香尘灭。\n想来宵何处，乱山明月。\n得意春风群玉府，第名早晚黄金阙。\n但相思、莫遣雁来时，音书绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9717, '满江红', '管鉴', '去岁兹辰，记称寿、曾陪燕席。\n明朝更、屈公扶醉，相过为客。\n间世生贤元自异，偶然先後欢连日。\n怅如今、五岭望三湘，云霄隔。\n松鹤算，璋德。\n廊庙器，神仙格。\n想尊前仍唱，雪中晴色。\n公上清都调鼎鼐，我归旧隐寻泉石。\n愿年年、东阁燕嘉宾，常相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9718, '满江红', '管鉴', '十日狂风，都断送、杏花红去。\n却是有、海棠枝上，一分春住。\n桃叶桃根浑未觉，樱桃杨柳成轻负。\n强尊前、抖擞旧精神，谁能许。\n时不再，欢难屡。\n心未老，杯频举。\n尚不妨领略，登临佳处。\n山接武陵馀胜气，江吞大别仍东注。\n叹圣贤、功业与江山，无今古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9719, '洞仙歌', '管鉴', '悠然堂上，山色浑如画。\n堂下梅花未多谢。\n向小亭、留客处，晴雪初飞，香四面，不比茅檐低亚。\n绿窗帘尽卷，吹到眉心，点缀新妆称闲雅。\n缓歌喉、馀舞态，云遏风回，须信道、欲买青春无价。\n任匆匆、归去酒醒时，镇梦绕琼梢，月寒清夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9720, '洞仙歌', '管鉴', '化工妙手，惯与花为主。\n忍便摧残任风雨。\n翦姚黄、移魏紫，齐集梁园，春艳艳，何必尊前解语。\n绣屏深照影，帘密收香，夜久寒生费调护。\n宝杯翻、银烛烂，客醉忘归，共惜此、芳菲难遇。\n看明年、紫禁绕莺花，谩相望、春风五云深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9721, '蓦山溪', '管鉴', '潜藩报政，玉座勤深眷。\n假节上青霄，正霜风、轻寒翦翦。\n天香怀袖，凝燕得从容，占喜色，送新声，潋滟金荷满。\n趣装入相，盛事应重见。\n尽待苦留连，怕九重、兴思见晚。\n休文未老，金带称围腰，丹禁密，凤池深，不但长安远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9722, '蓦山溪', '管鉴', '老来生日，渐觉心情懒。\n卯酒带春酲，更昨来、东风已转。\n衰颜易改，不用看传神，欢意浅，酒肠悭，孤负深深劝。\n浮云富贵，本自无心羡。\n金带便围腰，也应似、休文瘦减。\n君恩未报，何日赋归欤，三径乐，五湖游，趁取身强健。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9723, '蝶恋花', '管鉴', '楼倚云屏江泻镜。\n尊俎风流，地与人俱胜。\n酒力易消风力劲。\n归时城郭烟生瞑。\n幕府俊游常许并。\n可惜佳辰，独阻登临兴。\n妙语流传空叹咏。\n一时珠玉交相映。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9724, '定风波', '管鉴', '秋入华堂一味清。\n四山环碧眼双明。\n欲送主人天上去。\n无绪。\n一尊已带别离情。\n洞府桃花常许见。\n□□。\n为谁特地惜娉婷。\n祗待明年春醉里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9725, '鹧鸪天', '管鉴', '杨柳梢头月未残。\n杏花开尽却春寒。\n宾鸿社燕寻常别，渭北江东别更难。\n尊欲尽，夜将阑。\n明朝马首便长安。\n悬知不作人间住，归去春风玉笋班。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9726, '鹧鸪天', '管鉴', '山色初晴翠拂云。\n画桥流水碧粼粼。\n一尊不尽登临兴，归及西湖二月春。\n班缀旧，诏除新。\n稳看腾踏上星辰。\n回头却望尘凡处，应记尘凡有故人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9727, '鹧鸪天', '管鉴', '前日新冬举寿觞。\n今朝喜色又非常。\n一阳生後逢生日，日渐舒长寿更长。\n移晚宴，庆新堂。\n堂前高竹早梅芳。\n年年一为梅花醉，醉到千回鬓未霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9728, '鹧鸪天', '管鉴', '富贵楼台玉琢成。\n更移玉节下西清。\n才高不数梅花赋，笑拈琼苞泛寿觥。\n莲幕静，宝香凝。\n春风和气自然生。\n要知他日调元手，看取今朝雪里情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9729, '鹧鸪天', '管鉴', '燕寝香中锦帐郎。\n二年和气蔼蒸湘。\n鬓间不减当年绿，眉上新添一点黄。\n徵诏近，寿筵长。\n乍晴人意喜非常。\n燕莺休苦留春住，归趁薰风殿阁凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9730, '朝中措', '管鉴', '十年班缀近彤庭。\n一笑下霓旌。\n好是平分风月，新秋特地凉生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9731, '朝中措', '管鉴', '暖风帘幕卷春阴。\n歌吹画堂深。\n云袖纤纤捧玉，霞觞滟滟浮金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9732, '朝中措', '管鉴', '清江绕舍竹成阴。\n秋日共登临。\n地与主人俱胜，情如酒盏方深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9733, '朝中措', '管鉴', '一年春事到酴。\n何处更花开。\n莫趁垂杨飞絮，且随红药翻阶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9734, '柳梢青', '管鉴', '神仙堕谪。\n天为赋与，经纶才识。\n盖代声名，宗英惟向，翰林颂白。\n黄堂一笑留客。\n算此处、淹留未得。\n且对清尊，高谈风月，厌厌今夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9735, '柳梢青', '管鉴', '澹云微月。\n又是一年，新秋佳节。\n天上欢期，人间何事，翻成离别。\n清尊欲醉还歇。\n怕饮散、匆匆话别。\n若是经年，得回相见，甘心愁绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9736, '好事近', '管鉴', '风扫暮云空，依旧四山环碧。\n珍重主人清意，放梅梢春色。\n靓妆清唱两无尘，莲步绣鞋窄。\n莫怪十分沈醉，为教人消得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9737, '好事近', '管鉴', '列炬照梅花，仰看满空春雪。\n翠幕沈沈天净，挂一钩新月。\n微风不动暖光融，金杯堕琼屑。\n仿佛暗香吹梦，醉广寒宫阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9738, '好事近', '管鉴', '鸳瓦晓霜浓，酒力渐消寒力。\n好是一堂和气，胜十分春色。\n髯翁笑领彩衣郎，同祝寿千百。\n看取明年欢宴，更强如今日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9739, '好事近', '管鉴', '楚观落成初，还是诏书催发。\n却似爱山堂上，拜新除时节。\n要知君自栋梁材，开藩暂南越。\n早建明堂一柱，去扶持天阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9740, '桃源忆故人', '管鉴', '寿芽初长香英嫩。\n拾翠芳洲春近。\n倩笑脸霞羞褪。\n真个都风韵。\n垂鬟小舞么歌趁。\n莺语绿杨娇困。\n多少旧愁新恨。\n一醉浑消尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9741, '桃源忆故人', '管鉴', '小园日日狂风雨。\n几阵桃花红去。\n惟有绿窗朱户。\n春色常如许。\n歌声屡唤飞云驻。\n销得行人且住。\n倒尽玉壶春露。\n醉到无愁处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9742, '菩萨蛮', '管鉴', '今日云山堂上客。\n明朝真个云山隔。\n人不似行云。\n相随长短亭。\n堂空歌韵响。\n清切缘云上。\n留住莫教飞。\n怕如人别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9743, '浣溪沙', '管鉴', '金殿晨趋玉佩苍。\n君才久合侍龙章。\n花砖学士紫薇郎。\n小试一麾行促诏，暂留千骑且飞觞。\n夜堂歌暖借春光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9744, '浣溪沙', '管鉴', '李花开雪满空。\n缟裙香袂俨春容。\n靓妆一笑喜相逢。\n拟倩清歌留白日，且扶残醉东风。\n好迟留处却匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9745, '浣溪沙', '管鉴', '十里狂风特地晴。\n天工著意送行人。\n负他桃李十分春。\n杜宇已催归思乱，啼莺休惹客愁新。\n晚风溪路净无尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9746, '浣溪沙', '管鉴', '小小梅花巧耐寒。\n曛曛晴日醉醒间。\n茶瓯金缕鹧鸪斑。\n三寿作朋须共醉，一杯留客未应悭。\n酒肠如海寿如山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9747, '醉落魄・一斛珠', '管鉴', '春阴漠漠。\n海棠花底东风恶。\n人情不似春情薄。\n守定花枝，不放花零落。\n绿尊细细供春酌。\n酒醒无奈愁如昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9748, '醉落魄・一斛珠', '管鉴', '春愁无力。\n酴娇软难禁摘。\n风流彻骨香无敌。\n积玉团珠，明月夜同色。\n花时易失欢难得。\n尊前半是将行客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9749, '醉落魄・一斛珠', '管鉴', '寒欺酒力。\n一番风雨花如摘。\n酴不与群花敌。\n笑吐清香，独自殿春色。\n春愁惟酒消除得。\n何妨常满坐中客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9750, '醉落魄・一斛珠', '管鉴', '碧云暮合。\n不教预赏中秋月。\n凉生楚观风初歇。\n山影沈沈，相对两奇绝。\n湘人怅望黄金节。\n只愁酒散仙舟发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9751, '生查子', '管鉴', '天教百媚生，赋得多情怨。\n背整玉搔头，宽了黄金钏。\n情随歌意深，故故回娇眄。\n不是不相知，只为难相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9752, '虞美人', '管鉴', '一枝繁杏千红蕊。\n笑东风里。\n恰如歌院晓妆迟。\n簇簇娇娆同步、出深闺。\n风流莲幕莺花主。\n持送花深处。\n花多莫便著情偏。\n一一淡匀深注、总堪怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9753, '虞美人', '管鉴', '海棠花下春风里。\n曾拼千场醉。\n如今老去谩情多。\n步绕芳丛无力、奈春何。\n蜀乡不远长安远。\n相向空肠断。\n不如携客过西楼。\n却是江山如画、可消忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9754, '临江仙', '管鉴', '昨日武陵溪上雪，今朝特地开晴。\n故留佳景付行人。\n琼田千顷熟，琪树万株春。\n好是长松飘坠屑，天花时下缤纷。\n桃源何处更寻真。\n腰悬明月佩，直访玉华君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9755, '临江仙', '管鉴', '三月更当三十日，留春不住春归。\n问春还有再来时。\n腊前梅蕊破，相见未为迟。\n不似人生无定据，匆匆聚散难期。\n水遥山远谩相思。\n情知难舍弃，何似莫分飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9756, '清平乐', '管鉴', '未春先暖。\n天与梅花便。\n点检枝头开已遍。\n一一檀心粉面。\n巡檐索笑题诗。\n老怀不似当时。\n犹有惜花心在，等闲羌管休吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9757, '点绛唇', '管鉴', '酒困诗慵，一春拚被花枝恼。\n艳妆浓笑。\n那更花中好。\n不著清尊，持底宽愁抱。\n须颠倒。\n晚风如扫。\n忍见枝头少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9758, '点绛唇', '管鉴', '去岁今朝，海棠桃杏开都遍。\n今年花晚。\n不恨春情浅。\n旋旋花开，图得春长远。\n且留恋。\n爱花心眼。\n常与花为伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9759, '酒泉子', '管鉴', '春色十分。\n付与海棠枝上满。\n清尊我亦十分倾。\n未忘情。\n阳春一曲唤愁醒。\n可惜无人歌此曲，须君别院恼春酲。\n绕梁声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9760, '酒泉子', '管鉴', '清夜将分。\n有酒为谁花下满，相逢轩盖暂时倾。\n故人情。\n海棠欲睡照教醒。\n烛影花光浑似锦，伴君佳句解人酲。\n恨无声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9761, '青玉案', '管鉴', '相逢何处梅花好。\n深院宇、笙歌绕。\n春入候门长不老。\n罗帏秀幕，护香藏粉，却许行人到。\n遏云清唱倾城笑。\n玉面花光互相照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9762, '阮郎归', '管鉴', '浅寒天气雨催冬。\n梅梢糁嫩红。\n天教来寿黑头公。\n和羹信已通。\n斟滟滟，劝重重。\n新琥珀浓。\n他年赐酒拆黄封。\n还思此会同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9763, '木兰花・玉楼春', '管鉴', '乱花飞絮。\n却是一年春好处。\n留住韶光。\n共醉蓬莱日月长。\n翻阶红药。\n天上东风传近约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9764, '西江月', '管鉴', '夜雨落花满地，晓风飞絮连天。\n苦无春恨可萦牵。\n只数年华暗换。\n生意惟添白发，化工不染朱颜。\n老来愈觉欠清闲。\n梦想故园春晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9765, '西江月', '管鉴', '好个今年生日，满堂儿女团栾。\n歌声不似笑声喧。\n满捧金杯争劝。\n富贵功名任运，佳辰乐事随缘。\n白头相守愿年年。\n只恁尊前长健。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9766, '鹊桥仙', '管鉴', '中秋重九，等闲虚过，多病全疏酒盏。\n初寒时候试新醅，正好为、霜螯持满。\n诗情未减，酒肠宽在，且趁尊前强健。\n百年三万六千场，试屈指、如今过半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9767, '鹊桥仙', '管鉴', '东皋圃隐，木犀开後，香遍江东十里。\n因香招我渡江来，悄不记、重阳青蕊。\n人生行乐，宦游佳处，闲健莫辞清醉。\n不寒不暖不阴晴，正是好登临天气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9768, '鹊桥仙', '管鉴', '中秋过了，重阳将近，正是一年佳处。\n枨黄橘绿总寻常，看丹桂、馀香再吐。\n胸中星斗，笔端风雨，定约蟾宫高步。\n赐袍归带御炉薰，共岁岁、斑衣戏舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9769, '南乡子', '管鉴', '檐外雪纷纷。\n雾阁云窗气自温。\n谩道使台霜样峻，情亲。\n引到壶中别有春。\n尊酒负殷勤。\n病减杯中量几分。\n十五年间无限事，休论。\n说与梅花解笑人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9770, '玉连环・解连环', '管鉴', '江上青山无数。\n绿阴深处。\n夕阳犹在系扁舟，为佳景、留人住。\n已办一蓑归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9771, '念奴娇', '吴儆', '凉生秋早，正梧桐院落，风清月白。\n帘卷香凝人笑喜，应是瀛洲仙谪。\n云绕画梁，花明彩服，中有人华发。\n恩袍蓝绿，高年况已逾百。\n最是有子宜家，兰阶方竞，珠履延佳客。\n好唤凌波来洛浦，醉促霓裳仙拍。\n玉井开莲，金茎承露，莫惜金尊侧。\n试占弧兆，祥光已映南极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9772, '蓦山溪', '吴儆', '清晨早起，小阁遥山翠。\n面整冠巾，问寝罢、安排菽水。\n随家丰俭，不羡五侯鲭，软煮肉，熟炊粳，适意为甘旨。\n中庭散步，一盏云涛细。\n迤逦竹洲中，坐息与、行歌随意。\n逡巡酒熟，呼唤社中人，花下石，水边亭，醉便颓然睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9773, '满庭芳', '吴儆', '宿雨滋兰，轻风柳，新来随处和融。\n幽兰曲径，花气巧相通。\n燕子才飞又语，带芹泥、时点芳丛。\n微中酒，日长睡起，心事在眉峰。\n年年，春好处，联镳荡桨，拾翠挪红。\n任金貂醉脱，不放杯空。\n谁信风流一别，当时事、已逐飞鸿。\n云山晚，阑干罢倚，烟寺起疏钟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9774, '满庭芳', '吴儆', '水满池塘，莺啼杨柳，燕忙知为泥融。\n桃花流水，竹外小桥通。\n又是一春憔悴，摘残英、绕遍芳丛。\n长安远，平芜尽处，叠叠但云峰。\n西湖，行乐处，牙樯漾，锦帐翻红。\n想年时桃李，应已成空。\n欲写相思寄与，云天阔、难觅征鸿。\n空凝想，时时残梦，依约上阳钟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9775, '虞美人', '吴儆', '银屏一夜金风细。\n便作中秋意。\n碧天如水月如眉。\n已有征鸿摩月、向南飞。\n金尊满酌蟾宫客。\n莫促阳关拍。\n须知丹桂擅秋天。\n千里婵娟指日、十分圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9776, '虞美人', '吴儆', '飞桥驾鹊天津阔。\n云驭看看发。\n相思惟恨不相逢。\n及至相逢还是、去匆匆。\n垂丝插竹真堪笑。\n欲乞天孙巧。\n天孙多巧漫多愁。\n巧得千般争解、劝郎留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9777, '虞美人', '吴儆', '双眸翦水团香雪。\n云际看新月。\n生绡笼粉倚窗纱。\n全似瑶池疏影、浸梅花。\n金翘翠靥双蛾浅。\n敛袂低歌扇。\n羞红腻脸语声低。\n想见流苏帐掩、烛明时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9778, '西江月', '吴儆', '竹里全无暑气，溪边长有清风。\n荷花落日照酣红。\n雨过遥山翠重。\n老作宫祠散汉，本来田舍村翁。\n腰缠三万禄千锺。\n也是一场春梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9779, '浣溪沙', '吴儆', '十里青山碧流。\n夕阳沙晚片帆收。\n重重烟树出层楼。\n人去人来芳草渡，鸥飞鸥没白苹洲。\n碧梧翠竹记曾游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9780, '浣溪沙', '吴儆', '歙浦钱塘一水通。\n闲云如幕碧重重。\n吴山应在碧云东。\n无力海棠风淡漾，困眠宫柳日葱茏。\n眼前春色为谁浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9781, '浣溪沙', '吴儆', '画朱栏绕碧山。\n平湖徙倚水云宽。\n人家杨柳带汀湾。\n目力已随飞鸟尽，机心还逐白鸥闲。\n萧萧微雨晚来寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9782, '浣溪沙', '吴儆', '寒日孤城特地红。\n瘦藤扶我上西风。\n一川平远画图中。\n江海一身真客燕，云天万里看归鸿。\n吴山应在白云东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9783, '浣溪沙', '吴儆', '秋到郊原日夜凉。\n黍禾高下已垂黄。\n荷花犹有晚来香。\n天上佳期称七夕，人间好景是秋光。\n竹洲有月可徜徉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9784, '浣溪沙', '吴儆', '风入枯藜衣袂凉。\n江枫园柳半青黄。\n洗车飞雨带天香。\n世事一场真大梦，宦情都薄似秋光。\n竹洲有酒可徜徉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9785, '浣溪沙', '吴儆', '斜阳波底湿微红。\n朱栏翠袖倚轻风。\n平平山色有无中。\n俯首微官真自缚，高飞远举羡冥鸿。\n何时一艇大江东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9786, '浣溪沙', '吴儆', '茅舍疏离出素英。\n临风照水眩精神。\n娟娟新月又黄昏。\n削约寒枝香未透，细看频嗅独消魂。\n为谁消瘦不禁春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9787, '减字木兰花', '吴儆', '碧梧秋老。\n满地琅纷不扫。\n门掩黄昏。\n惟有年时月照人。\n凄凉满眼。\n肯作六年灯火伴。\n莫说凄凉。\n来岁如今天一方。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9788, '减字木兰花', '吴儆', '思君欲老。\n一榻尘生谁与扫。\n禄仰晨昏。\n同是迟迟去鲁人。\n行当洗眼。\n看子青藜来夜伴。\n莫变炎凉。\n斩马还须请上方。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9789, '减字木兰花', '吴儆', '少陵未老。\n曾把千人军独扫。\n发白眵昏。\n却作天涯流落人。\n只堪合眼。\n夜直谁能潜入伴。\n斗酒西凉。\n何似卑栖且远方。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9790, '减字木兰花', '吴儆', '此身已老。\n三径都荒长却扫。\n面目尘昏。\n怕著朝章揖贵人。\n难瞒明眼。\n只有青山堪作伴。\n触事心凉。\n无病何劳更觅方。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9791, '念奴娇', '吴儆', '东风着意，正群芳未放，蟠桃初缀。\n王母当年亲手种，来作人间上瑞。\n婺女星躔，金华福地，聊驻千千岁。\n恰才八十，百分未及一二。\n况是间生英贤，名高日月，未说文昌贵。\n今日凝香称寿，来岁衮衣当发。\n黄贴天香，太白珍膳，押赐传中旨。\n戏拈金果，宫娥应是争取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9792, '念奴娇', '吴儆', '延州积庆，到如今千载，芳传遗绪。\n世袭簪缨来旧治，依约棠阴如故。\n百里休声，三年遗爱，若迹高今古。\n邑人尽道，郎君福过渠父。\n州县岂久徒劳，汉家密令，须作三公去。\n今入花城称寿处，他日荣归禁路。\n黄贴天有，上尊名酒，押赐传天语。\n朱颜绿鬓，腰黄绸蹙金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9793, '念奴娇', '吴儆', '相逢恨晚，人谁道、早有轻离轻折。\n不是无情，都只为、离合因缘难测。\n秋去云鸿，春深花絮，风雨随南北。\n絮飞鸿散，问谁解舀得得。\n君自举远高飞，知他此去、萍梗何时息。\n雅阁幽窗欢笑处，回首翻成陈迹。\n小楷缄题，细行针线，一一重收拾。\n风花雪月，此生长是思忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9794, '西江月', '吴儆', '山色不随春老，竹枝长向人新。\n桃蹊李径已成阴。\n深院莺啼人静。\n尘世白驹过隙，人情苍狗浮云。\n不须计较谩劳神。\n且恁随缘任运。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9795, '浣溪沙', '吴儆', '暖日和风并马蹄。\n畦秧陇麦绿新齐。\n人家桑柘午阴迷。\n山色解随春意远，残阳还傍远山低。\n晚风归路杜鹃啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9796, '浣溪沙', '吴儆', '帘额风微紫燕通。\n楼头柳暗碧云重。\n玉人争劝玉西东。\n醉拥雕鞍金蹀躞，夜归花院玉葱茏。\n归心何事与山浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9797, '浣溪沙', '吴儆', '已是青春欲暮天。\n酒愁离恨不禁添。\n尊前休说见郎难。\n别後要知还有意，生前莫道便无缘。\n雁来频寄小蛮笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9798, '浣溪沙', '吴儆', '汗褪香红雪莹肌。\n装馀静丽雾裁衣。\n晚凉新浴倚栏时。\n帘卷轻风斜虿发，杯深新月堕蛾眉。\n此时风味许谁知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9799, '朝中措', '吴儆', '文章声价擅南州。\n人物更风流。\n岂久徒劳州县，看看催上瀛洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9800, '赤壁词・念奴娇', '陆游', '禁门锺晓，忆君来朝路，初翔鸾鹄。\n西府中台推独步，行对金莲宫烛。\n蹙绣华鞯，仙葩宝带，看即飞腾速。\n人生难料，一尊此地相属。\n回首紫陌青门，西湖闲院，锁千梢修竹。\n素壁栖鸦应好在，残梦不堪重续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9801, '浣溪沙', '陆游', '懒向沙头醉玉瓶。\n唤君同赏小窗明。\n夕阳吹角最关情。\n忙日苦多闲日少，新愁常续旧愁生。\n客中无伴怕君行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9802, '浣溪沙', '陆游', '浴罢华清第二汤。\n红绵扑粉玉肌凉。\n娉婷初试藕丝裳。\n凤尺裁成猩血色，螭奁熏透麝脐香。\n水亭幽处捧霞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9803, '青玉案', '陆游', '西风挟雨声翻浪。\n恰洗尽、黄茅瘴。\n老惯人间齐得丧。\n千岩高卧，五湖归棹，替却凌烟像。\n故人小驻平戎帐。\n白羽腰间气何壮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9804, '水调歌头', '陆游', '江左占形胜，最数古徐州。\n连山如画，佳处缥渺著危楼。\n鼓角临风悲壮，烽火连空明灭，往事忆孙刘。\n千里曜戈甲，万灶宿貔貅。\n露沾草，风落木，岁方秋。\n使君宏放，谈笑洗尽古今愁。\n不见襄阳登览，磨灭游人无数，遗恨黯难收。\n叔子独千载，名与汉江流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9805, '浪淘沙', '陆游', '绿树暗长亭。\n几把离尊。\n阳关常恨不堪闻。\n何况今朝秋色里，身是行人。\n清泪罗巾。\n各自消魂。\n一江离恨恰平分。\n安得千寻横铁锁，截断烟津。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9806, '定风波', '陆游', '帽垂鞭送客回。\n小桥流水一枝梅。\n衰病逢春都不记。\n谁谓。\n幽香却解逐人来。\n安得身闲频置酒。\n携手。\n与君看到十分开。\n少壮相从今雪鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9807, '南乡子', '陆游', '归梦寄吴樯。\n水驿江程去路长。\n想见芳洲初系缆，斜阳。\n烟树参差认武昌。\n愁鬓点新霜。\n曾是朝衣染御香。\n重到故乡交旧少，凄凉。\n却恐它乡胜故乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9808, '南乡子', '陆游', '早岁入皇州。\n尊酒相逢尽胜流。\n三十年来真一梦，堪愁。\n客路萧萧两鬓秋。\n蓬峤偶重游。\n不待人嘲我自羞。\n看镜倚楼俱已矣，扁舟。\n月笛烟蓑万事休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9809, '满江红', '陆游', '危堞朱栏，登览处、一江秋色。\n人正似、征鸿社燕，几番轻别。\n缱绻难忘当日语，凄凉又作它乡客。\n问鬓边、都有几多丝，真堪织。\n杨柳院，秋千陌。\n无限事，成虚掷。\n如今何处也，梦魂难觅。\n金鸭微温香缥渺，锦茵初展情萧瑟。\n料也应、红泪伴秋霖，灯前滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9810, '满江红', '陆游', '疏蕊幽香，禁不过、晚寒愁绝。\n那更是、巴东江上，楚山千叠。\n帽闲寻西路，鞭笑向南枝说。\n恐使君、归去上銮坡，孤风月。\n清镜里，悲华发。\n山驿外，溪桥侧。\n凄然回首处，凤凰城阙。\n憔悴如今谁领略，飘零已是无颜色。\n问行厨、何日唤宾僚，犹堪折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9811, '感皇恩', '陆游', '春色到人间，彩初戴。\n正好春盘细生菜。\n一般日月，只有仙家偏耐。\n雪霜从点鬓，朱颜在。\n温诏鼎来，延英催对。\n凤阁鸾台看除拜。\n对衣裁稳，恰称球纹新带。\n个时方旋了、功名债。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9812, '感皇恩', '陆游', '小阁倚秋空，下临江渚。\n漠漠孤云未成雨。\n数声新雁，回首杜陵何处。\n壮心空万里，人谁许。\n黄阁紫枢，筑坛开府。\n莫怕功名欠人做。\n如今熟计，只有故乡归路。\n石帆山脚下，菱三亩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9813, '好事近', '陆游', '羁雁未成归，肠断宝筝零落。\n那更冻醪无力，似故人情薄。\n瘴云蛮雨暗孤城，身在楚山角。\n烦问剑南消息，怕还成疏索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9814, '好事近', '陆游', '风露九霄寒，侍宴玉华宫阙。\n亲向紫皇香案，见金芝千叶。\n碧壶仙露酝初成，香味两奇绝。\n醉後却骑丹凤，看蓬莱春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9815, '好事近', '陆游', '客路苦思归，愁似茧丝千绪。\n梦里镜湖烟雨，看山无重数。\n尊前消尽少年狂，慵著送春语。\n花落燕飞庭户，叹年光如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9816, '好事近', '陆游', '岁晚喜东归，扫尽市朝陈迹。\n拣得乱山环处，钓一潭澄碧。\n卖鱼沽酒醉还醒，心事付横笛。\n家在万重云外，有沙鸥相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9817, '好事近', '陆游', '华表又千年，谁记驾云孤鹤。\n回首旧曾游处，但山川城郭。\n纷纷车马满人间，尘土污芒。\n且访葛仙丹井，看岩花开落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9818, '好事近', '陆游', '挥袖别人间，飞蹑峭崖苍壁。\n寻见古仙丹灶，有白云成积。\n心如潭水静无风，一坐数千息。\n夜半忽惊奇事，看鲸波暾日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9819, '好事近', '陆游', '湓口放船归，薄暮散花洲宿。\n两岸白苹红蓼，映一蓑新绿。\n有沽酒处便为家，菱芡四时足。\n明日又乘风去，任江南江北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9820, '好事近', '陆游', '挥袖上西峰，孤绝去天无尺。\n拄杖下临鲸海，数烟帆历历。\n贪看云气舞青鸾，归路已将夕。\n多谢半山松吹，解殷勤留客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9821, '好事近', '陆游', '小倦带馀酲，澹澹数斜日。\n驱退睡魔十万，有双龙苍璧。\n少年莫笑老人衰，风味似平昔。\n扶杖冻云深处，探溪梅消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9822, '好事近', '陆游', '觅个有缘人，分付玉壶灵药。\n谁向市尘深处，识辽天孤鹤。\n月中吹笛下巴陵，条华赴前约。\n今古废兴何限，叹山川如昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9823, '好事近', '陆游', '平旦出秦关，雪色驾车双鹿。\n借问此行安往，赏清伊修竹。\n汉家宫殿劫灰中，春草几回绿。\n君看变迁如许，况纷纷荣辱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9824, '好事近', '陆游', '秋晓上莲峰，高蹑倚天青壁。\n谁与放翁为伴，有天坛轻策。\n铿然忽变赤龙飞，雷雨四山黑。\n谈笑做成丰岁，笑禅龛栗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9825, '鹧鸪天', '陆游', '家住东吴近帝乡。\n平生豪举少年场。\n十千沽酒青楼上，百万呼卢锦瑟傍。\n身易老，恨难忘。\n尊前赢得是凄凉。\n君归为报京华旧，一事无成两鬓霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9826, '鹧鸪天', '陆游', '看尽巴山看蜀山。\n子规江上过春残。\n惯眠古驿常安枕，熟听阳关不惨颜。\n慵服气，懒烧丹。\n不妨青鬓戏人间。\n秘传一字神仙诀，说与君知只是顽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9827, '鹧鸪天', '陆游', '梳发金盘剩一窝。\n画眉鸾镜晕双蛾。\n人间何处无春到，只有伊家独占多。\n微步处，奈娇何。\n春衫初换曲尘罗。\n东邻斗草归来晚，忘却新传子夜歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9828, '鹧鸪天', '陆游', '家住苍烟落照间。\n丝毫尘事不相关。\n斟残玉瀣行穿竹，卷罢黄庭卧看山。\n贪啸傲，任衰残。\n不妨随处一开颜。\n元知造物心肠别，老却英雄似等闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9829, '鹧鸪天', '陆游', '插脚红尘已是颠。\n更求平地上青天。\n新来有个生涯别，买断烟波不用钱。\n沽酒市，采菱船。\n醉听风雨拥蓑眠。\n三山老子真堪笑，见事迟来四十年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9830, '鹧鸪天', '陆游', '懒向青门学种瓜。\n只将渔钓送年华。\n双双新燕飞春岸，片片轻鸥落晚沙。\n歌缥渺，舻呕哑。\n酒如清露如花。\n逢人问道归何处，笑指船儿此是家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9831, '鹧鸪天', '陆游', '南浦舟中两玉人。\n谁知重见楚江滨。\n凭教後苑红牙版，引上西川绿锦茵。\n才浅笑，却轻。\n淡黄杨柳又催春。\n情知言语难传恨，不思琵琶道得真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9832, '蓦山溪', '陆游', '元戎十乘，出次高唐馆。\n归去旧行，更何人、齐飞霄汉。\n瞿唐水落，惟是泪波深，催叠鼓，起牙樯，难锁长江断。\n春深鳌禁，红日宫瓦暖。\n何处望音尘，黯消魂、层城飞观。\n人情见惯，不敢恨相忘，梅驿外，蓼滩边，只待除书看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9833, '蓦山溪', '陆游', '穷山孤垒，腊尽春初破。\n寂寞掩空斋，好一个、无聊底我。\n啸台龙岫，随分有云山，临浅濑，荫长松，闲据胡床坐。\n三杯径醉，不觉纱巾堕。\n画角唤人归，落梅村、篮舆夜过。\n城门渐近，几点妓衣红，官驿外，酒垆前，也有闲灯火。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9834, '木兰花・玉楼春', '陆游', '三年流落巴山道。\n破尽青衫尘满帽。\n身如西渡头云，愁抵瞿塘关上草。\n春盘春酒年年好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9835, '朝中措', '陆游', '幽姿不入少年场。\n无语只凄凉。\n一个飘零身世，十分冷淡心肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9836, '朝中措', '陆游', '怕歌愁舞懒逢迎。\n妆晚托春酲。\n总是向人深处，当时枉道无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9837, '朝中措', '陆游', '咚咚傩鼓饯流年。\n烛焰动金船。\n彩燕难寻前梦，酥花空点春妍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9838, '临江仙', '陆游', '鸠雨催成新绿，燕泥收尽残红。\n春光还与美人同。\n论心空眷眷，分袂却匆匆。\n只道真情易写，那知怨句难工。\n水流云散各西东。\n半廊花院月，一帽柳桥风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9839, '蝶恋花', '陆游', '陌上箫声寒食近。\n雨过园林，花气浮芳润。\n千里斜阳锺欲瞑。\n凭高望断南楼信。\n海角天涯行略尽。\n三十年间，无处无遗恨。\n天若有情终欲问。\n忍教霜点相思鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9840, '蝶恋花', '陆游', '桐叶晨飘蛩夜语。\n旅思秋光，黯黯长安路。\n忽记横戈盘马处。\n散关清渭应如故。\n江海轻舟今已具。\n一卷兵书，叹息无人付。\n早信此生终不遇。\n当年悔草长杨赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9841, '蝶恋花', '陆游', '水漾萍根风卷絮。\n倩笑娇颦，忍记逢迎处。\n只有梦魂能再遇。\n堪嗟梦不由人做。\n梦若由人何处去。\n短帽轻衫，夜夜眉州路。\n不怕银缸深绣户。\n只愁风断青衣渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9842, '钗头凤・撷芳词', '陆游', '红酥手。\n黄酒。\n满城春色宫墙柳。\n东风恶。\n欢情薄。\n一怀愁绪，几年离索。\n错错错。\n春如旧。\n人空瘦。\n泪痕红鲛绡透。\n桃花落。\n闲池阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9843, '清商怨', '陆游', '江头日暮痛饮。\n乍雪晴犹凛。\n山驿凄凉，灯昏人独寝。\n鸳机新寄断锦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9844, '水龙吟', '陆游', '樽前花底寻春处，堪叹心情全减。\n一身萍寄，酒徒云散，佳人天远。\n那更今年，瘴烟蛮雨，夜郎江畔。\n漫倚楼横笛，临窗看镜，时挥涕、惊流转。\n花落月明庭院。\n悄无言、魂消肠断。\n凭肩携手，当时曾效，画梁栖燕。\n见说新来，网萦尘暗，舞衫歌扇。\n料也羞憔悴，慵行芳径，怕啼莺见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9845, '秋波媚・眼儿媚', '陆游', '秋到边城角声哀。\n烽火照高台。\n悲歌击筑，凭高酹酒，此兴悠哉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9846, '秋波媚・眼儿媚', '陆游', '曾散天花蕊珠宫。\n一念堕尘中。\n铅华洗尽，珠玑不御，道骨仙风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9847, '采桑子', '陆游', '宝钗楼上妆梳晚，懒上秋千。\n闲拨沈烟。\n金缕衣宽睡髻偏。\n鳞鸿不寄辽东信，又是经年。\n弹泪花前。\n愁入春风十四弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9848, '卜算子', '陆游', '驿外断桥边，寂寞开无主。\n已是黄昏独自愁，更著风和雨。\n无意苦争春，一任群芳妒。\n零落成泥碾作尘，只有香如故。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9849, '沁园春', '陆游', '粉破梅梢，绿动萱丛，春意已深。\n渐珠帘低卷，筇枝微步，冰开跃鲤，林暖鸣禽。\n荔子扶疏，竹枝哀怨，浊酒一尊和泪斟。\n凭栏久，叹山川冉冉，岁月。\n当时岂料如今。\n漫一事无成霜鬓侵。\n看故人强半，沙堤黄阁，鱼悬带玉，貂映蝉金。\n许国虽坚，朝天无路，万里凄凉谁寄音。\n东风里，有灞桥烟柳，知我归心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9850, '沁园春', '陆游', '一别秦楼，转眼新春，又近放灯。\n忆盈盈倩笑，纤纤柔握，玉香花语，雪暖酥凝。\n念远愁肠，伤春病思，自怪平生殊未曾。\n君知否，渐香消蜀锦，泪渍吴绫。\n难求系日长绳。\n况倦客飘零少旧朋。\n但江郊雁起，渔村笛怨，寒委烬，孤砚生冰。\n水绕山围，烟昏云惨，纵有高台常怯登。\n消魂处，是鱼笺不到，兰梦无凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9851, '沁园春', '陆游', '孤鹤归飞，再过辽天，换尽旧人。\n念累累枯冢，茫茫梦境，王侯蝼蚁，毕竟成尘。\n载酒园林，寻花巷陌，当日何曾轻负春。\n流年改，叹围腰带剩，点鬓霜新。\n交亲。\n散落如云。\n又岂料如今馀此身。\n幸眼明身健，茶甘饭软，非惟我老，更有人贫。\n躲尽危机，消残壮志，短艇湖中闲采莼。\n吾何恨，有渔翁共醉，溪友为邻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9852, '忆秦娥', '陆游', '玉花骢。\n晚街金辔声璁珑。\n声璁珑。\n闲乌帽，又过城东。\n富春巷陌花重重。\n千金沽酒酬春风。\n酬春风。\n笙歌围里，锦绣丛中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9853, '汉宫春', '陆游', '浪迹人间。\n喜闻猿楚峡，学剑秦川。\n虚舟泛然不系，万里江天。\n朱颜绿鬓，作红尘、无事神仙。\n何妨在，莺花海里，行歌闲送流年。\n休笑放慵狂眼，看闲坊深院，多少婵娟。\n燕宫海棠夜宴，花覆金船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9854, '汉宫春', '陆游', '羽箭雕弓，忆呼鹰古垒，截虎平川。\n吹笳暮归，野帐雪压青毡。\n淋漓醉墨，看龙蛇、飞落蛮笺。\n人误许，诗情将略，一时才气超然。\n何事又作南来，看重阳药市，元夕灯山。\n花时万人乐处，帽垂鞭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9855, '月上海棠', '陆游', '斜阳废苑朱门闭。\n吊兴亡、遗恨泪痕里。\n淡淡宫梅，也依然、点酥剪水。\n凝愁处，似忆宣华旧事。\n行人别有凄凉意。\n折幽香、谁与寄千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9856, '月上海棠', '陆游', '兰房绣户厌厌病。\n叹春酲、和闷甚时醒。\n燕子空归，几曾传、玉关边信。\n伤心处，独展团窠瑞锦。\n熏笼消歇沈烟冷。\n泪痕深、展转看花影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9857, '乌夜啼', '陆游', '金鸭馀香尚暖，绿窗斜日偏明。\n兰膏香染云鬟腻，钗坠滑无声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9858, '乌夜啼', '陆游', '檐角楠阴转日，楼前荔子吹花。\n鹧鸪声里霜天晚，叠鼓已催衙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9859, '乌夜啼', '陆游', '我校丹台玉字，君书蕊殿云篇。\n锦官城里重相遇，心事两依然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9860, '乌夜啼', '陆游', '世事从来惯见，吾生更欲何之。\n镜湖西畔秋千顷，鸥鹭共忘机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9861, '乌夜啼', '陆游', '素意幽栖物外，尘缘浪走天涯。\n归来犹幸身强健，随分作山家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9862, '乌夜啼', '陆游', '园馆青林翠樾，衣巾细葛轻纨。\n好风吹散霏微雨，沙路喜新乾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9863, '乌夜啼', '陆游', '从宦元知漫浪，还家更觉清真。\n兰亭道上多修竹，随处岸纶巾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9864, '乌夜啼', '陆游', '纨扇婵娟素月，纱巾缥渺轻烟。\n高槐叶长阴初合，清润雨馀天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9865, '真珠帘', '陆游', '山村水馆参差路。\n感羁游、正似残春风絮。\n掠地穿帘，知是竟归何处。\n镜里新霜空自悯，问几时、鸾台鳌署。\n迟暮。\n谩凭高怀远，书空独语。\n自古。\n儒冠多误。\n悔当年、早不扁舟归去。\n醉下白苹洲，看夕阳鸥鹭。\n菰菜鲈鱼都弃了，只换得、青衫尘土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9866, '好事近', '陆游', '混迹寄人间，夜夜画楼银烛。\n谁见五云丹灶，养黄芽初熟。\n春风归从紫皇游，东海宴谷。\n进罢碧桃花赋，赐玉尘千斛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9867, '柳梢青', '陆游', '锦里繁华。\n环宫故邸，叠萼奇花。\n俊客妖姬，争飞金勒，齐驻香车。\n何须幕障帏遮。\n宝杯浸、红云瑞霞。\n银烛光中，清歌声里，休恨天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9868, '柳梢青', '陆游', '十载江湖，行歌沽酒，不到京华。\n底事翩然，长亭烟草，衰鬓风沙。\n凭高目断天涯。\n细雨外、楼台万家。\n只恐明朝，一时不见，人共梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9869, '夜游宫', '陆游', '雪晓清笳乱起。\n梦游处、不知何地。\n铁骑无声望似水。\n想关河，雁门西，青海际。\n睡觉寒灯里。\n漏声断、月斜窗纸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9870, '夜游宫', '陆游', '独夜寒侵翠被。\n奈幽梦、不成还起。\n欲写新愁泪溅纸。\n忆承恩，叹馀生，今至此。\n蔌蔌灯花坠。\n问此际、报人何事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9871, '安公子', '陆游', '风雨初经社。\n子规声里春光谢。\n最是无情，零落尽、蔷薇一架。\n况我今年，憔悴幽窗下。\n人尽怪、诗酒消声价。\n向药炉经卷，忘却莺窗柳榭。\n万事收心也。\n粉痕犹在香罗帕。\n恨月愁花，争信道、如今都罢。\n空忆前身，便面章台马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9872, '玉胡蝶・玉蝴蝶', '陆游', '倦客平生行处，坠鞭京洛，解佩潇湘。ピ\n此夕何年，来赋宋玉高唐。ピ\n绣帘开、香尘乍起，莲步稳、银烛分行。ピ\n暗端相。ピ\n燕羞莺妒，蝶绕蜂忙。ピ\n难忘。ピ\n芳樽频劝，峭寒新退，玉漏犹长。ピ\n几许幽情，只愁歌罢月侵廊。ピ\n欲归时、司空笑问，微近处，丞相嗔狂。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9873, '木兰花慢', '陆游', '阅邯郸梦境，叹绿鬓、早霜侵。\n奈华岳烧丹，青溪看鹤，尚负初心。\n年来向浊世里，悟真诠秘诀绝幽深。\n养就金芝九畹，种成琪树千林。\n星坛夜学步虚吟。\n露冷透瑶簪。\n对翠凤披云，青鸾溯月，宫阙萧森。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9874, '苏武慢', '陆游', '澹霭空，轻阴清润，绮陌细尘初静。\n平桥系马，画阁移舟，湖水倒空如镜。\n掠岸飞花，傍檐新燕，都似学人无定。\n叹连年戎帐，经春边垒，暗凋颜鬓。\n空记忆、杜曲池台，新丰歌管，怎得故人音信。\n羁怀易感，老伴无多，谈麈久闲犀柄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9875, '齐天乐', '陆游', '角残锺晚关山路，行人乍依孤店。\n塞月征尘，鞭丝帽影，常把流年虚占。\n藏鸦柳暗。\n叹轻负莺花，谩劳书剑。\n事往关情，悄然频动壮游念。\n孤怀谁与强遣。\n市垆沽酒，酒薄怎当愁酽。\n倚瑟妍词，调铅妙笔，那写柔情芳艳。\n征途自厌。\n况烟敛芜痕，雨稀萍点。\n最是眠时，枕寒门半掩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9876, '齐天乐', '陆游', '客中随处闲消闷，来寻啸台龙岫。\n路敛春泥，山开翠雾，行乐年年依旧。\n天工妙手。\n放轻绿萱牙，淡黄杨柳。\n笑问东君，为人能染鬓丝否。\n西州催去近也，帽檐风软，且看市楼沽酒。\n宛转巴歌，凄凉塞管，携客何妨频奏。\n征尘暗袖。\n漫禁得梅花，伴人疏瘦。\n几日东归，画船平放溜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9877, '望梅', '陆游', '寿非金石。\n恨天教老向，水程山驿。\n似梦里、来到南柯，这些子光阴，更勘轻掷。\n戍火边尘，又过了、一年春色。\n叹名姬骏马，尽付杜陵，苑路豪客。\n长绳漫劳系日。\n看人间俯仰，俱是陈迹。\n纵自倚、英气凌云，奈回尽鹏程，铩残鸾翮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9878, '洞庭春色・沁园春', '陆游', '壮岁文章，暮年勋业，自昔误人。\n算英雄成败，轩裳得失，难如人意，空丧天真。\n请看邯郸当日梦，待炊罢黄粱徐欠伸。\n方知道，许多时富贵，何处关身。\n人间定无可意，怎换得、玉丝莼。\n且钓竿渔艇，笔床茶灶，闲听荷雨，一洗衣尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9879, '渔家傲', '陆游', '东望山阴何处是。\n往来一万三千里。\n写得家书空满纸。\n流清泪。\n书回已是明年事。\n寄语红桥桥下水。\n扁舟何日寻兄弟。\n行遍天涯真老矣。\n愁无寐。\n鬓丝几缕茶烟里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9880, '绣停针', '陆游', '叹半纪，跨万里秦吴，顿觉衰谢。\n回首行，英俊并游，咫尺玉堂金马。\n气凌嵩华。\n负壮略、纵横王霸。\n梦经洛浦梁园，觉来泪流如泻。\n山林定去也。\n却自恐说著，少年时话。\n静院焚香，闲倚素屏，今古总成虚假。\n趁时婚嫁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9881, '桃源忆故人', '陆游', '斜阳寂历柴门闭。\n一点炊烟时起。\n鸡犬往来林外。\n俱有萧然意。\n衰翁老去疏荣利。\n绝爱山城无事。\n临去画楼频倚。\n何日重来此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9882, '桃源忆故人', '陆游', '栏干几曲高斋路。\n正在重云深处。\n丹碧未乾人去。\n高栋空留句。\n离离芳草长亭暮。\n无奈征车不住。\n惟有断鸿烟渚。\n知我频回顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9883, '桃源忆故人', '陆游', '一弹指顷浮生过。\n堕甑元知当破。\n去去醉吟高卧。\n独唱何须和。\n残年还我从来我。\n万里江湖烟舸。\n脱尽利名缰锁。\n世界元来大。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9884, '桃源忆故人', '陆游', '城南载酒行歌路。\n冶叶倡条无数。\n一朵红凝露。\n最是关心处。\n莺声无赖催春去。\n那更兼旬风雨。\n试问岁华何许。\n芳草连天暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9885, '桃源忆故人', '陆游', '中原当日三川震。\n关辅回头煨烬。\n泪尽两河征镇。\n日望中兴运。\n秋风霜满青青鬓。\n老却新丰英俊。\n云外华山千仞。\n依旧无人问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9886, '极相思', '陆游', '江头疏雨轻烟。\n寒食落花天。\n翻红坠素，残霞暗锦，一段凄然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9887, '一丛花', '陆游', '尊前凝伫漫魂迷。\n犹恨负幽期。\n从来不惯伤春泪，为伊後、滴满罗衣。\n那堪更是，吹箫池馆，青子绿阴时。\n回廊帘影昼参差。\n偏共睡相宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9888, '一丛花', '陆游', '仙姝天上自无双。\n玉面翠蛾长。\n黄庭读罢心如水，闭朱户、愁近丝簧。\n窗明几净，闲临唐帖，深炷宝奁香。\n人间无药驻流光。\n风雨又催凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9889, '隔浦莲近拍', '陆游', '飞花如趁燕子。\n直度帘栊里。\n帐掩香云暖，金笼鹦鹉惊起。\n凝恨慵梳洗。\n妆台畔，蘸粉纤纤指。\n宝钗坠。\n才醒又困，厌厌中酒滋味。\n墙头柳暗，过尽一年春事。\n罨画高楼怕独倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9890, '隔浦莲近拍', '陆游', '骑鲸云路倒景。\n醉面风吹醒。\n笑把浮丘袂，寥然非复尘境。\n震泽秋万顷。\n烟霏散，水面飞金镜。\n露华冷。\n湘妃睡起，鬟倾钗坠慵整。\n临江舞处，零乱塞鸿清影。\n河汉横斜夜漏永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9891, '昭君怨', '陆游', '昼永蝉声庭院。\n人倦懒摇团扇。\n小景写潇湘。\n自生凉。\n帘外蹴花双燕。\n帘下有人同见。\n宝篆拆官黄。\n炷熏香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9892, '双头莲', '陆游', '华鬓星星，惊壮志成虚，此身如寄。\n萧条病骥。\n向暗里。\n消尽当年豪气。\n梦断故国山川，隔重重烟水。\n身万里。\n旧社凋零，青门俊游谁记。\n尽道锦里繁华，叹官闲昼永，柴荆添睡。\n清愁自醉。\n念此际。\n付与何人心事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9893, '南歌子', '陆游', '异县相逢晚，中年作别难。\n暮秋风雨客衣寒。\n又向朝天门外、话悲欢。\n瘦马行霜栈，轻舟下雪滩。\n乌奴山下一林丹。\n为说三年常寄、梦魂间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9894, '豆叶黄・忆王孙', '陆游', '春风楼上柳腰肢。\n初试花前金缕衣。\n袅袅娉娉不自持。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9895, '豆叶黄・忆王孙', '陆游', '一春常是雨和风。\n风雨晴时春已空。\n谁惜泥沙万点红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9896, '醉落魄・一斛珠', '陆游', '江湖醉客。\n投杯起舞遗乌帻。\n三更冷翠沾衣湿。\n袅袅菱歌，催落半川月。\n空花昨梦休寻觅。\n云台麟阁俱陈迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9897, '鹊桥仙', '陆游', '华灯纵博，雕鞍驰射，谁记当年豪举。\n酒徒一一取封侯，独去作、江边渔父。\n轻舟八尺，低篷三扇，占断苹洲烟雨。\n镜湖元自属闲人，又何必、君恩赐与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9898, '鹊桥仙', '陆游', '一竿风月，一蓑烟雨，家在钓台西住。\n卖鱼生怕近城门，况肯到、红尘深处。\n潮生理棹，潮平系缆，潮落浩歌归去。\n时人错把比严光，我自是、无名渔父。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9899, '鹊桥仙', '陆游', '茅檐人静，蓬窗灯暗，春晚连江风雨。\n林莺巢燕总无声，但月夜、常啼杜宇。\n催成清泪，惊残孤梦，又拣深枝飞去。\n故山犹自不堪听，况半世、飘然羁旅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9900, '长相思', '陆游', '云千重。\n水千重。\n身在千重云水中。\n月明收钓筒。\n头未童。\n耳未聋。\n得酒犹能双脸红。\n一尊谁与同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9901, '长相思', '陆游', '桥如虹。\n水如空。\n一叶飘然烟雨中。\n天教称放翁。\n侧船篷。\n使江风。\n蟹舍参差渔市东。\n到时闻暮锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9902, '长相思', '陆游', '面苍然。\n鬓皤然。\n满腹诗书不直钱。\n官闲常昼眠。\n画凌烟。\n上甘泉。\n自古功名属少年。\n知心惟杜鹃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9903, '长相思', '陆游', '暮山青。\n暮霞明。\n梦笔桥头艇子横。\n苹风吹酒醒。\n看潮生。\n看潮平。\n小住西陵莫较程。\n莼丝初可烹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9904, '长相思', '陆游', '悟浮生。\n厌浮名。\n回视千锺一发轻。\n从今心太平。\n爱松声。\n爱泉声。\n写向孤桐谁解听。\n空江秋月明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9905, '菩萨蛮', '陆游', '江天淡碧云如扫。\n苹花零落莼丝老。\n细细晚波平。\n月从波面生。\n渔家真个好。\n悔不归来早。\n经岁洛阳城。\n鬓丝添几茎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9906, '菩萨蛮', '陆游', '小院蚕眠春欲老。\n新巢燕乳花如扫。\n幽梦锦城西。\n海棠如旧时。\n当年真草草。\n一棹还吴早。\n题罢惜春诗。\n镜中添鬓丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9907, '诉衷情', '陆游', '当年万里觅封侯。\n匹马戍梁州。\n关河梦断何处，尘暗旧貂裘。\n胡未灭，鬓先秋。\n泪空流。\n此生谁料，心在天山，身老沧洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9908, '诉衷情', '陆游', '青衫初入九重城。\n结友尽豪英。\n蜡封夜半传檄，驰骑谕幽并。\n时易失，志难成。\n鬓丝生。\n平章风月，弹压江山，别是功名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9909, '生查子', '陆游', '还山荷主恩，聊试扶犁手。\n新结小茅茨，恰占清江口。\n风尘不化衣，邻曲常持酒。\n那似宦游时，折尽长亭柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9910, '生查子', '陆游', '梁空燕委巢，院静鸠催雨。\n香润上朝衣，客少闲谈麈。\n鬓边千缕丝，不是吴蚕吐。\n孤梦泛潇湘，月落闻柔橹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9911, '破阵子', '陆游', '仕至千锺良易，年过七十常稀。\n眼底荣华元是梦，身後声名不自知。\n营营端为谁。\n幸有旗亭沽酒，何妨茧纸题诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9912, '破阵子', '陆游', '看破空花尘世，放轻昨梦浮名。\n蜡屐登山真率饮，筇杖穿林自在行。\n身闲心太平。\n料峭馀寒犹力，廉纤细雨初晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9913, '上西楼・相见欢', '陆游', '江头绿暗红稀。\n燕交飞。\n忽到当年行处、恨依依。\n洒清泪。\n叹人事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9914, '点绛唇', '陆游', '采药归来，独寻茅店沽新酿。\n暮烟千嶂。\n处处闻渔唱。\n醉弄扁舟，不怕粘天浪。\n江湖上。\n遮回疏放。\n作个闲人样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9915, '谢池春', '陆游', '壮岁从戎，曾是气吞残虏。\n阵云高、狼烽夜举。\n朱颜青鬓，拥雕戈西戍。\n笑儒冠、自来多误。\n功名梦断，却泛扁舟吴楚。\n漫悲歌、伤怀吊古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9916, '谢池春', '陆游', '贺监湖边，初系放翁归棹。\n小园林、时时醉倒。\n春眠惊起，听啼莺催晓。\n叹功名、误人勘笑。\n朱桥翠径，不许京尘飞到。\n挂朝衣、东归欠早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9917, '谢池春', '陆游', '七十衰翁，不减少年豪气。\n似天山、凄凉病骥。\n铜驼荆棘，洒临风清泪。\n甚情怀、伴人儿戏。\n如今何幸，作个故溪归计。\n鹤飞来、晴岚暖翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9918, '一落索', '陆游', '满路游丝飞絮。\n韶光将暮。\n此时谁与说新愁，有百啭、流莺语。\n俯仰人间今古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9919, '一落索', '陆游', '识破浮生虚妄。\n从人讥谤。\n此身恰似弄潮儿，曾过了、千重浪。\n且喜归来无恙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9920, '杏花天', '陆游', '老来驹隙度。\n只合、狂歌醉舞。\n金杯到手君休诉。\n看著春光又暮。\n谁为倩、柳条系住。\n且莫遣、城笳催去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9921, '太平时・添声杨柳枝', '陆游', '竹里房栊一径深。\n静。\n乱红飞尽绿成阴。\n有鸣禽。\n临罢兰亭无一事，自修琴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9922, '恋绣衾', '陆游', '不惜貂裘换钓篷。\n嗟时人、谁识放翁。\n归棹借、樵风稳，数声闻、林外暮锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9923, '恋绣衾', '陆游', '无方能驻脸上红。\n笑浮生、扰扰梦中。\n平地是、冲霄路，又何劳、千日用功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9924, '风入松', '陆游', '十年裘马锦江滨。\n酒隐红尘。\n万金选胜莺花海，倚疏狂、驱使青春。\n吹笛鱼龙尽出，题诗风月俱新。\n自怜华发满纱巾。\n犹是官身。\n凤楼常记当年语，问浮名、何似身亲。\n欲寄吴笺说与，这回真个闲人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9925, '真珠帘', '陆游', '灯前月下嬉游处。\n向笙歌、锦绣丛中相遇。\n彼此知名，才见便论心素。\n浅黛娇蝉风调别，最动人、时时偷顾。\n归去。\n想闲窗深院，调弦促柱。\n乐府初翻新谱。\n漫裁红点翠，闲题金缕。\n燕子入帘时，又一番春暮。\n侧帽燕脂坡下过，料也记、前年崔护。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9926, '风流子', '陆游', '佳人多命薄，初心慕、德耀嫁梁鸿。\n记绿窗睡起，静吟闲咏，句翻离合，格变玲珑。\n更乘兴，素纨留戏墨，纤玉抚孤桐。\n蟾滴夜寒，水浮微冻，凤笺春丽，花砑轻红。\n人生谁能料，堪悲处、身落柳陌花丛。\n空羡画堂鹦鹉，深闭金笼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9927, '双头莲', '陆游', '风卷征尘，堪叹处、青骢正摇金辔。\n客襟贮泪。\n漫万点如血，凭谁持寄。\n伫想艳态幽情，压江南佳丽。\n春正媚。\n怎忍长亭，匆匆顿分连理。\n目断淡日平芜，望烟浓树远，微茫如荠。\n悲欢梦里。\n奈倦客、又是关河千里。\n最苦唱彻骊歌，重迟留无计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9928, '鹧鸪天', '陆游', '杖屦寻春苦未迟。\n洛城樱笋正当时。\n三千界外归初到，五百年前事总知。\n吹玉笛，渡清伊。\n相逢休问姓名谁。\n小车处士深衣叟，曾是天津共赋诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9929, '蝶恋花', '陆游', '禹庙兰亭今古路。\n一夜清霜，染尽湖边树。\n鹦鹉杯深君莫诉。\n他时相遇知何处。\n冉冉年华留不住。\n镜里朱颜，毕竟消磨去。\n一句丁宁君记取。\n神仙须是闲人做。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9930, '渔父・渔歌子', '陆游', '石帆山下雨空。\n三扇香新翠箬篷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9931, '渔父・渔歌子', '陆游', '晴山滴翠水蓝。\n聚散渔舟两复三。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9932, '渔父・渔歌子', '陆游', '镜湖俯仰两青天。\n万顷玻璃一叶船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9933, '渔父・渔歌子', '陆游', '湘湖烟雨长莼丝。\n菰米新炊滑上匙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9934, '渔父・渔歌子', '陆游', '长安拜免几公卿。\n渔父横眠醉未醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9935, '恋绣衾', '陆游', '雨断西山晚照明。\n悄无人、幽梦自惊。\n说道去、多时也，到如今、真个是行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9936, '采桑子', '陆游', '三山山下闲居士，巾履萧然。\n小醉闲眠。\n风引飞花落钓船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9937, '水龙吟', '陆游', '摩诃池上追游路，红绿参差春晚。\n韶光妍媚，海棠如醉，桃花欲暖。\n挑菜初闲，禁烟将近，一城丝管。\n看金鞍争道，香车飞盖，争先占、新亭馆。\n惆怅年华暗换。\n黯销魂、雨收云散。\n镜奁掩月，钗梁拆凤，秦筝斜雁。\n身在天涯，乱山孤垒，危楼飞观。\n叹春来只有，杨花和恨、向东风满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9938, '月照梨花・河传', '陆游', '霁景风软，烟江春涨。\n小阁无人，绣帘半上。\n花外姊妹相呼。\n约樗蒲。\n修蛾忘了章台样。\n细思一饷。\n感事添惆怅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9939, '月照梨花・河传', '陆游', '闷已萦损。\n那堪多病。\n几曲屏山，伴人昼静。\n梁燕催起犹慵。\n换熏龙。\n新愁旧恨何时尽。\n渐凋绿鬓。\n小雨知花信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9940, '夜游宫', '陆游', '宴罢珠帘半卷。\n画檐外、蜡香人散。\n翠雾霏霏漏声断。\n倚香肩，看中庭，花影乱。\n宛是高唐馆。\n宝奁炷、麝烟初暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9941, '如梦令', '陆游', '独倚博山峰小。\n翠雾满身飞绕。\n只恐学行云，去作阳台春晓。\n春晓。\n春晓。\n满院绿阳芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9942, '失调名', '陆游', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9943, '解连环', '陆游', '泪淹妆薄。\n背东风伫立，柳绵池阁。\n漫细字、书满芳笺，恨钗燕筝鸿，总难凭托。\n风雨无情，又颠倒、绿苔红萼。\n仗香醪破闷，怎禁夜阑，酒酲萧索。\n刘郎已望故约。\n奈重门静院，光景如昨。\n尽做它、别有留心，便不念当时，雨意初著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9944, '大圣乐', '陆游', '电转雷惊，自叹浮生，四十二年。\n试思量往事，虚无似梦，悲欢万状，合散如烟。\n苦海无边，爱河无底，流浪看成百漏船。\n何人解，问无常火里，铁打身坚。\n须臾便是华颠。\n好收拾形体归自然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9945, '钗头凤・撷芳词', '唐婉', '世情薄。\n人情恶。\n雨送黄昏花易落。\n晓风乾。\n泪痕残。\n欲笺心事，独语斜阑。\n难难难。\n人成各。\n今非昨。\n病魂尝似秋千索。\n角声寒。\n夜阑珊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9946, '生查子', '陆游妾某氏', '只知愁上眉，不识愁来路。\n窗外有芭蕉，阵阵黄昏雨。\n逗晓理残妆，整顿教愁去。\n不合画春山，依旧留连住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9947, '祝英台近', '王', '柳烟浓，花露重，合是醉时候。\n楼倚花梢，长记小垂手。\n谁教钗燕轻分，镜鸾慵舞，是孤负、几番春昼。\n自别後。\n闻道花底花前，多是两眉皱。\n又说新来，比似旧时瘦。\n须知两意长存，相逢终有。\n莫谩被、春光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9948, '夜行船', '王', '曲水溅裙三月二。\n马如龙、钿车如水。\n风扬游丝，日烘晴昼，人共海棠俱醉。\n客里光阴难可意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9949, '朝中措', '贾逸祖', '青山隐隐水斜斜。\n修竹两三家。\n又是水寒山瘦，依然行客遍天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9950, '鹊桥仙', '蜀妓', '说盟说誓。\n说情说意。\n动便春愁满纸。\n多应念得脱空经，是那个、先生教底。\n不茶不饭，不言不语，一味供他憔悴。\n相思已是不曾闲，又那得、功夫咒你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9951, '画堂春', '姜特立', '故园二月正芳菲。\n红紫团枝。\n一番草绿谢郎池。\n人醉如泥。\n底事江乡风物，年年独殿芳时。\n无情燕子背人飞。\n似愧春迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9952, '浣溪沙', '姜特立', '节序回环已献裘。\n不堪风叶夜鸣秋。\n寒吟露月阶幽。\n蜗角虚名真误我，蝇头细字不禁愁。\n班超何日定封候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9953, '菩萨蛮', '姜特立', '日长庭院无人到。\n琅翠影摇寒瓮。\n困卧北窗凉。\n好风吹梦长。\n壁月升东岭。\n冷浸扶疏影。\n苗叶万珠明。\n露华圆更清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9954, '菩萨蛮', '姜特立', '蓬山学士文章伯。\n尊前风味谁能敌。\n新觅似花人。\n添成小院春。\n玉纤呵翠袖。\n满劝金杯酒。\n寿酒莫辞斟。\n酒深人意深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9955, '菩萨蛮', '姜特立', '镜天良月皆佳节。\n休恨今宵妨皎洁。\n玉锁闷蟾宫。\n娥意自通。\n终有开时节。\n莫放笙歌歇。\n来夕尚婵娟。\n何妨把酒看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9956, '霜天晓角', '姜特立', '欢娱电掣。\n何况轻离别。\n料得两情无奈，思量尽、总难说。\n酒热。\n凄兴发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9957, '阮郎归', '姜特立', '绿阴庭院记年时。\n家人捧寿卮。\n乐声催拍送腰支。\n香风匝地衣。\n清梦断，彩云飞。\n刘郎今鬓丝。\n强将杯酒破愁眉。\n如今触事非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9958, '浪淘沙', '姜特立', '春事有来期。\n且喜春归。\n问春何似去年时。\n报道今年春意好，随分开眉。\n往事莫伤悲。\n光景如飞。\n十分潘鬓已成丝。\n幸是风流犹未减，且醉芳菲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9959, '朝中措', '姜特立', '芳林曲径锦玲珑。\n腻白借微红。\n元是海棠标格，司花点化东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9960, '朝中措', '姜特立', '十分天赋好精神。\n宫样小腰身。\n迷却阳城下蔡，未饶宋玉东邻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9961, '朝中措', '姜特立', '如山堂上翠横空。\n山影浪花中。\n夜夜林间明月，时时柳外清风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9962, '蝶恋花', '姜特立', '飘粉吹香三月暮。\n病酒情怀，愁绪浑无数。\n有个人人来又去。\n归期有恨难留驻。\n明日尊前无觅处。\n咿轧篮舆，只向双溪路。\n我辈情锺君谩与。\n为云为雨应难据。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9963, '声声慢', '姜特立', '云迷越岫，枫冷吴江，天香忽到人寰。\n满额涂黄，别更一种施丹。\n天教素秋独步，笑同时、霜菊秋兰。\n最好处，向水阶月地，把酒相看。\n应有骚人雅韵，将胆瓶筠管，簇向屏山。\n野店云房，争待结屋中间。\n无奈猖狂老子，架巢卧、风露清闲。\n待早晚，约娥、同住广寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9964, '卜算子', '姜特立', '丹桂一枝芳，陡觉秋容静。\n月里人间总一般，共此扶疏影。\n枕畔忽闻香，夜半还思省。\n争奈娥不嫁人，寂寞孤衾冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9965, '西江月', '姜特立', '富贵从来自有，人生最羡长年。\n八秩未华颠。\n更喜此身强健。\n金印新来如斗，丝纶御墨犹鲜。\n枣如瓜大藕如船。\n莫惜尊前满劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9966, '满江红', '姜特立', '听说梅山，一邱内、深藏曲折。\n过醒心桥下，水光清彻。\n迤逦跻攀登翠岭，沈沈烟壑千峰列。\n更小亭、风露逼华堂，荷香发。\n歌声动，云横阕。\n舞腰转，风回雪。\n正良辰美景，众宾欢悦。\n老子中间聊笑傲，酒行莫放觥筹歇。\n愿此生、长似钓璜公，添华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9967, '念奴娇', '姜特立', '宦途险，问急流勇退，几人闻早。\n自别修门今正是，一纪生朝还到。\n绿野风光，平泉草木，争似梅山好。\n园林如画，芰荷香泛芳沼。\n早晚玉节来临，君恩踵至，金印应如斗。\n好是华堂开宴处，歌舞管弦声奏。\n海上蟠桃，山中仙杏，共劝长生酒。\n莫辞沈醉，年年此会依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9968, '满江红', '姜特立', '小小华堂，朱阑外、乱山如簇。\n更云中仙掌，一峰高矗。\n南极老人呈瑞处，丙丁躔次光相烛。\n又谁知、堂上有闲人，无拘束。\n宾朋至，须歌曲。\n风月好，纷丝竹，都不管、世间是非荣辱。\n屈指如今侪辈少，几人老後能知足。\n问此身、何地寄生涯，唯松菊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9969, '临江仙', '姜特立', '桃李飞花春渐老，海棠次第芬芳。\n庭前红叶已成行。\n酴开未到，犹更有花王。\n从此便须排日醉，莫将闲事相妨。\n老来不是太疏狂。\n尊前君看取，潘宾已成霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9970, '感皇恩', '姜特立', '儿女沸欢声，生朝来到。\n帘幕中间喷香兽。\n京祠新任，好事日边还又。\n清闲无个事，君恩厚。\n赢得乞食，歌姬一笑。\n旧衲云山伴红袖。\n蓬莱弱水，试问神仙何有。\n近来饶落托，贪杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9971, '朝中措', '周必大', '乘成台上晓书云。\n黄色映天庭。\n已谢浮名浮利，也知来应长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9972, '满庭芳', '周必大', '天壤茫茫，人心殊观，未免因欠思馀。\n太山邱垤，同载一方舆。\n那更长沙下湿，祝融峰、才比吾庐。\n秋风冷，攀缘汗浃，应叹苦区区。\n登高，聊尔耳，何须蜡屐，谁暇膏车。\n默存处，清都宛在须臾。\n笑约乘鸾羽客，窥倒景、拊掌崎岖。\n归来把，萸囊菊盏，一为洗泥涂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9973, '谒金门', '周必大', '梅乍吐。\n趁寿席、香风度。\n人与此花俱独步。\n风流天付与。\n好在青云歧路。\n愿共作、和羹侣。\n归访赤松辞万户。\n莺花犹是主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9974, '点绛唇', '周必大', '报答风光，满倾琼液休思睡。\n乱莺声碎。\n来往甘棠底。\n闻道中和，深简君王意。\n归舟起。\n到时应是。\n玉殿槐交翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9975, '点绛唇', '周必大', '醉上兰舟，羡他沙暖鸳鸯睡。\n月波金碎。\n愁海深无底。\n太守新词，解释无穷意。\n高歌起。\n浮云闲事。\n浑付烟中翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9976, '点绛唇', '周必大', '踏白江梅，大都玉斫酥凝就。\n雨肥霜逗。\n痴了闺房秀。\n莫待冬深，雪压风欺後。\n君知否。\n却嫌伊瘦。\n仍怕伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9977, '点绛唇', '周必大', '秋夜乘槎，客星容到天孙渚。\n眼波微注。\n将谓牵牛渡。\n见了还非，重理霓裳舞。\n都无误。\n几年一遇。\n莫讶周郎顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9978, '朝中措', '周必大', '月眉新画露珠圆。\n今夕正相鲜。\n欲导唐家诞节，先生汉相韦贤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9979, '朝中措', '周必大', '九重深念朔庭空。\n良弼梦时中。\n擢第难遵常制，筑岩直继高风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9980, '醉落魄・一斛珠', '周必大', '山川迥别。\n赤城自古雄东越。\n锺英储秀簪绅列。\n何事黄扉，殊未相黄发。\n如今衮职那容缺。\n人心恰与天时合。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9981, '醉落魄・一斛珠', '周必大', '才高句杰。\n飞黄却应鸾和节。\n新词聊卷波澜阔。\n泉玉淙铮，犹不比清切。\n相逢未稳愁相别。\n南园烟草南楼月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9982, '西江月', '周必大', '三月群贤毕集，二天五马生光。\n传觞击鼓底匆忙。\n画将飞江上。\n鲁国方虚两社，齐人要复侵疆。\n延英引对上东廊。\n应念幽人相望。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9983, '西江月', '周必大', '藉甚新除刺史，岿然鲁殿灵光。\n诏书催发棹讴忙。\n沙路从今稳上。\n有喜刊除戎索，无劳远抚闽疆。\n日高龙影转槐廊。\n想见清光注望。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9984, '导引', '周必大', '重华真主，晨夕奉庭闱。\n祀庆成时。\n乾元坤载同归美，宝册两光辉。\n斑衣何似赭黄衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9985, '导引', '周必大', '新阳初应，乐事起彤庭。\n和气满吴京。\n帝家来庆东皇寿，西母共长生。\n金书玉篆灿龙文。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9986, '导引', '周必大', '合宫亲飨，青女肃长空。\n精意与天通。\n后皇临顾谁为侑，文祖暨神功。\n亟蒙祉福岁长丰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9987, '合宫歌', '周必大', '圣明朝，旷典乘秋举。\n大飨本仁祖。\n九室八牖四户。\n敕躬齐戒格堪舆。\n盛牲实俎。\n并侑总稽古。\n玉露乍肃天宇。\n冰轮下照金铺。\n燎烟嘘呼。\n郁尊香，云门舞。\n仿佛翔坐，灵心咸嘉娱。\n众星俞美，光属照珠。\n清晓御丹凤，湛恩遍浃率溥。\n欢声雷动岳镇呼。\n徐命法驾，万骑花盈路。\n献胙慈极，寿同箕翼，事超唐虞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9988, '失调名', '周辉', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9989, '失调名', '周辉', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9990, '满江红', '范成大', '寒谷春生，熏叶气、玉筒吹谷。\n新阳後、便占新岁，吉云清穆。\n休把心情关乐裹，但逢节序添诗轴。\n笑强颜、风物岂非痴，终非俗。\n清昼永，佳眠熟。\n门外事，何时足。\n且团栾同社，笑歌相属。\n著意调停云露酿，从头检举梅花曲。\n纵不能、将醉作生涯，休拘束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9991, '满江红', '范成大', '竹里行厨，来问讯、诸侯宾老。\n春满座、弹丝未遍，挥豪先了。\n云避仁风收雨脚，日随和气薰林表。\n向尊前、来访白髯公，衰何早。\n志千里，功名兆。\n光万丈，文章耀。\n洗水壶胸次，月秋霜晓。\n应念一堂尘网暗，故将百和香云绕。\n算赏心、清话古来多，如今少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9992, '满江红', '范成大', '柳外轻雷，催几阵、雨丝飞急。\n雷雨过、半川荷气，粉融香。\n弄蕊攀条春一笑，从教水溅罗衣湿。\n打梁州、箫鼓浪花中，跳鱼立。\n山倒影，云千叠。\n横浩荡，舟如叶。\n有采菱清些，桃根双楫。\n忘却天涯泊地，尊前不放闲愁人。\n任碧筒、十丈卷金波，长鲸吸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9993, '满江红', '范成大', '罨画溪山，行欲遍、风蒲还举。\n天渐远、水云初静，柁楼人语。\n月色波光看不定，玉虹横卧金鳞舞。\n看五湖、今夜只边舟，追千古。\n怀往事，渔樵侣。\n曾共醉，松江渚。\n算今年依旧，一杯沧浦。\n宇宙此身元是客，不须怅望家何许。\n但中秋、时节好溪山，皆吾土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9994, '千秋岁', '范成大', '北城南埭。\n玉水方流汇。\n青樾里，红尘外。\n万桃春不老，双竹寒相对。\n回首处，满城明月曾同载。\n分散西园盖。\n消减东阳带。\n人事改，花源在。\n神仙虽可学，功行无过醉。\n新酒好，就船况有鱼堪买。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9995, '浣溪沙', '范成大', '倾坐东风百媚生。\n万红无语笑逢迎。\n照妆醒睡蜡烟轻。\n采横斜春不夜，绛霞浓淡月微明。\n梦中重到锦官城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9996, '浣溪沙', '范成大', '催下珠帘护绮丛。\n花枝红里烛枝红。\n烛光花影夜葱茏。\n锦地绣天香雾里，珠星璧月彩云中。\n人间别有几春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9997, '浣溪沙', '范成大', '送尽残春更出游。\n风前踪迹似沙鸥。\n浅斟低唱小淹留。\n月见西楼清夜醉，雨添南浦绿波愁。\n有人无计恋行舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9998, '浣溪沙', '范成大', '歙浦钱塘一水通。\n闲云如幕碧重重。\n吴山应在碧云东。\n无力海棠风淡荡，半眠官柳日葱茏。\n眼前春色为谁浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (9999, '浣溪沙', '范成大', '宝髻双双出绮丛。\n妆光梅影各春风。\n收灯时候却相逢。\n鱼子笺中此宛转，龙香拨上语玲珑。\n明朝车马莫西东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10000, '浣溪沙', '范成大', '红锦障泥杏叶鞯。\n解鞍呼渡忆当年。\n马骄不肯上航船。\n茅店竹篱开席市，绛裙青袂姜田。\n临平风物故依然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10001, '浣溪沙', '范成大', '白玉堂前绿绮疏。\n烛残歌罢困相扶。\n问人春思肯浓无。\n梦里粉香浮枕簟，觉来烟月满琴书。\n个浓情分更何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10002, '朝中措', '范成大', '东风半夜度关山。\n和雪到阑干。\n怪见梅梢未暖，情知柳眼犹寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10003, '朝中措', '范成大', '身闲身健是生涯。\n何况好年华。\n看了十分秋月，重阳更插黄花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10004, '朝中措', '范成大', '系船沽酒碧帘坊。\n酒满胜鹅黄。\n醉後西园入梦，东风柳色花香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10005, '朝中措', '范成大', '海棠如雪殿春馀。\n禽弄晚晴初。\n倦客长惭杜宇，佳辰且醉提壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10006, '朝中措', '范成大', '天容云意写秋光。\n木叶半青黄。\n珍重西风祛暑，轻衫早怯新凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10007, '蝶恋花', '范成大', '春涨一篙添水面。\n芳草鹅儿，绿满微风岸。\n画舫夷犹湾百转。\n横塘塔近依前远。\n江国多寒农事晚。\n村北村南，谷雨才耕遍。\n秀麦连冈桑叶贱。\n看看尝面收新茧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10008, '南柯子・南歌子', '范成大', '槁项诗馀瘦，愁肠酒後柔。\n晚凉团扇欲知秋。\n卧看明河银影、界天流。\n鹤警人初静，虫吟夜更幽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10009, '南柯子・南歌子', '范成大', '怅望梅花驿，凝情杜若洲。\n香云低处有高楼。\n可惜高楼、不近木兰舟。\n缄素双鱼远，题红片叶秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10010, '南柯子・南歌子', '范成大', '银渚盈盈渡，金风缓缓吹。\n晚香浮动五云飞。\n月姊妒人、颦尽一弯眉。\n短夜难留处，斜河欲淡时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10011, '水调歌头', '范成大', '细数十年事，十处过中秋。\n今年新梦，忽到黄鹤旧山头。\n老子个中不浅，此会天教重见，今古一南楼。\n星汉淡无色，玉镜独空浮。\n敛秦烟，收楚雾，熨江流。\n关河离合，南北依旧照清愁。\n想见娥冷眼，应笑归来双鬓，空敞黑貂裘。\n酾酒问蟾兔，肯去伴沧洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10012, '水调歌头', '范成大', '万里汉家使，双节照清秋。\n旧京行遍，中夜呼禹济黄流。\n寥落桑榆西北，无限太行紫翠，相伴过芦沟。\n岁晚客多病，风露冷貂裘。\n对重九，须烂醉，莫牢愁。\n黄花为我，一笑不管鬓霜羞。\n袖里天书咫尺，眼底关河百二，歌罢此生浮。\n惟有平安信，随雁到南州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10013, '西江月', '范成大', '十月谁云春小，一年两见风娇。\n云英此夕度蓝桥。\n人意花枝都好。\n百媚朝天淡粉，六铢步月生绡。\n人间霜叶满庭皋，别有东风不老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10014, '西江月', '范成大', '北客开眉乐岁，东君著意华年。\n遮风藏雨晚云天。\n应怕杏梢红浅。\n不惜灯前放夜，从教雪後留寒。\n水晶帘箔万花钿。\n听彻南楼晓箭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10015, '鹊桥仙', '范成大', '双星良夜，耕慵织懒，应被群仙相妒。\n娟娟月姊满眉颦，更无奈、风姨吹雨。\n相逢草草，争如休见，重搅别离心绪。\n新欢不抵旧愁多，倒添了、新愁归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10016, '宜男草', '范成大', '篱菊滩芦被霜後。\n袅长风、万重高柳。\n天为谁、展尽湖光渺渺，应为我、扁舟入手。\n橘中曾醉洞庭酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10017, '宜男草', '范成大', '舍北烟霏舍南浪。\n雪倾篱、雨荒薇涨。\n问小桥、别後谁过，惟有迷鸟羁雌来往。\n重寻山水问无恙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10018, '秦楼月・忆秦娥', '范成大', '窗纱薄。\n日穿红幔催梳掠。\n催梳掠。\n新晴天气，画檐闻鹊。\n海棠逗晓都开却。\n小云先在阑干角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10019, '秦楼月・忆秦娥', '范成大', '珠帘狭。\n卷帘春院花围合。\n花围合。\n昼长人静，双双胡蝶。\n花前苦金蕉叶。\n瞢腾午睡扶头怯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10020, '秦楼月・忆秦娥', '范成大', '香罗薄。\n带围宽尽无人觉。\n无人觉。\n东风日暮，一帘花落。\n西园空锁秋千索。\n帘垂帘卷闲池阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10021, '秦楼月・忆秦娥', '范成大', '楼阴缺。\n阑干影卧东厢月。\n东厢月。\n一天风露，杏花如雪。\n隔烟催漏金虬咽。\n罗帏暗淡灯花结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10022, '秦楼月・忆秦娥', '范成大', '浮云集。\n轻雷隐隐初惊蛰。\n初惊蛰。\n鹁鸠鸣怒，绿杨风急。\n玉炉烟重香罗。\n拂墙浓杏燕支湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10023, '念奴娇', '范成大', '双峰叠障，过天风海雨，无边空碧。\n月姊年年应好在，玉阕琼宫愁寂。\n谁唤痴云，一杯为尽，夜气寒无色。\n碧城凝望，高楼飘渺西北。\n肠断桂冷蟾孤，佳期如梦，又把阑干拍。\n雾鬓风鬟相借问，浮世几回今夕。\n圆缺晴阴，古今同恨，我更长为客。\n婵娟明夜，尊前谁念南陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10024, '念奴娇', '范成大', '十年旧事，醉京花蜀酒，万葩千萼。\n一棹归来吴下看，俯仰心情今昨。\n强倚雕阑，羞簪雪鬓，老恐花枝觉。\n揩摹愁眼，雾中相对依约。\n闻道家宴团栾，光风转夜，月傍西楼落。\n打彻梁州春自远，不饮何时欢乐。\n沾惹天香，留连国艳，莫散灯前酌。\n袜尘生处，为君重赋河洛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10025, '念奴娇', '范成大', '吴波浮动，看中流翻月，半江金碧。\n醉舞空明三万顷，不管娥愁寂。\n指点琼楼，凭虚有路，鲸背横东极。\n水云飘荡，阑干千丈无力。\n家世回首沧洲，烟波渔钓，有鸱夷仙迹。\n一笑闲身游物外，来访扁舟消息。\n天上今宵，人间此地，我是风前客。\n涛生残夜，鱼龙惊听横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10026, '念奴娇', '范成大', '水乡霜落，望西山一寸，修眉横碧。\n南浦潮生帆影去，日落天青江白。\n万里浮云，被风吹散，又被风吹积。\n尊前歌罢，满空凝淡寒色。\n人世会少离多，都来名利，似蝇头蝉翼。\n赢得长亭车马路，千古羁愁如织。\n我辈情锺，匆匆相见，一笑真难得。\n明年谁健，梦魂飘荡南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10027, '念奴娇', '范成大', '湖山如画，系孤篷柳岸，莫惊鱼鸟。\n料峭春寒花未遍，先共疏梅索笑。\n一梦三年，松风依旧，萝月何曾老。\n邻家相问，这回真个归到。\n绿鬓新点吴霜，尊前强健，不怕衰翁号。\n赖有风流车马客，来觅香云花岛。\n似我粗豪，不通姓字，只有银瓶倒。\n奔名逐利，乱帆谁在天表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10028, '惜分飞', '范成大', '易散浮云难再聚。\n遮莫相随百步。\n谁唤行人去。\n石湖烟浪渔樵侣。\n重别西楼肠断否。\n多少凄风苦雨。\n休梦江南路。\n路长梦短无寻处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10029, '梦玉人引', '范成大', '送行人去，犹追路、再相觅。\n天末交情，长是合堂同席。\n从此尊前，便顿然少个，江南羁客。\n不忍匆匆，少驻船梅驿。\n酒斟虽满，尚少如、别泪万千滴。\n欲语吞声，结心相对呜咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10030, '梦玉人引', '范成大', '共登临处，飘风袂、倚空碧。\n雨卷云飞，长有桂娥看客。\n箫鼓生春，遍锦城如画，雪山无色。\n一梦才成，恍天涯南北。\n舞馀歌罢，料宣华、回首尽陈迹。\n万里秦吴，有情应问消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10031, '如梦令', '范成大', '罨画屏中客住。\n水色山光无数。\n斜日满江声，何处撑来小渡。\n休去。\n休去。\n惊散一舟鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10032, '如梦令', '范成大', '两两莺啼何许。\n寻遍绿阴浓处。\n天气润罗衣，病起却微暑。\n休雨。\n休雨。\n明日榴花端午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10033, '菩萨蛮', '范成大', '小轩今日开窗了。\n揉蓝染碧绿阶草。\n檐佩可怜风。\n杏梢烟雨红。\n飘零欢事少。\n鬓点吴霜早。\n天色不愁人。\n眼前无限春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10034, '菩萨蛮', '范成大', '雪林一夜收寒了。\n东风恰向灯前到。\n今夕是何年。\n新春新月圆。\n绮丛香雾隔。\n犹记疏狂客。\n留取缕金。\n夜蛾相并看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10035, '菩萨蛮', '范成大', '黄梅时节春萧索。\n越罗香润吴纱薄。\n丝雨日明。\n柳梢红未晴。\n多愁多病後。\n不识会中酒。\n愁病送春归。\n恰如中酒时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10036, '临江仙', '范成大', '羽扇纶巾风袅袅，东厢月到蔷薇。\n新声谁唤出罗帏。\n龙须将笛绕，雁字入筝飞。\n陶写中年须个里，留连月扇云衣。\n周郎去後赏音稀。\n为君持酒听，那肯带春归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10037, '临江仙', '范成大', '万事灰心犹薄宦，尘埃未免劳形。\n故人相见似河清。\n恰逢梅柳动，高兴逐春生。\n卜昼匆匆还卜夜，仍须月坠河倾。\n明年我去白鸥盟。\n金闺三玉树，好问紫霄程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10038, '减字木兰花', '范成大', '玉烟浮动。\n银阕三山连海冻。\n翠袖阑干。\n不怕楼高酒力寒。\n双松冻折。\n忽忆衰翁容易别。\n想见鸥边。\n压损年时小钓船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10039, '减字木兰花', '范成大', '折残金菊。\n枨子香时新酒熟。\n谁伴芳尊。\n先问梅花借小春。\n道人破戒。\n染酒题诗金凤带。\n愁病相关。\n不似年时酒量宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10040, '减字木兰花', '范成大', '波娇鬓袅。\n中隐堂前人意好。\n不奈春何。\n拚却轻寒透薄罗。\n翦梅新曲。\n欲断还联三叠促。\n围坐风流。\n饶我尊前第一筹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10041, '减字木兰花', '范成大', '枕书睡熟。\n珍重月明相伴宿。\n宝鸭金寒。\n香满围屏宛转山。\n鸡人声杳。\n瑶井玉绳相对晓。\n黯淡窗纱。\n却下风帘护烛花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10042, '减字木兰花', '范成大', '腊前三白。\n春到西园还见雪。\n红紫花迟。\n借作东风万玉枝。\n归田计决。\n麦饭熟时应快活。\n身在高楼。\n心在山阴一叶舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10043, '鹧鸪天', '范成大', '休舞银貂小契丹。\n满堂宾客尽关山。\n从今袅袅盈盈处，谁复端端正正看。\n模泪易，写愁难。\n潇湘江上竹枝斑。\n碧云日暮无书寄，寥落烟中一雁寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10044, '鹧鸪天', '范成大', '荡漾西湖采绿苹。\n扬鞭南埭衮红尘。\n桃花暖日茸茸笑，杨柳光风浅浅颦。\n章贡水，郁孤云。\n多情争似桂江春。\n崔徽卷轴瑶姬梦，纵有相逢不是真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10045, '鹧鸪天', '范成大', '嫩绿重重看得成。\n曲栏幽槛小红英。\n酴架上蜂儿闹，杨柳行间燕子轻。\n春婉娩，客飘零。\n残花浅酒片时清。\n一杯且买明朝事，送了斜阳月又生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10046, '鹧鸪天', '范成大', '压蕊拈须粉作团。\n疏香辛苦颤朝寒。\n须知风月寻常见，不似层层带雪看。\n春髻重，晓眉弯。\n一枝斜并缕金。\n酒红不解东风冻，惊怪钗头玉燕乾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10047, '好事近', '范成大', '云暮暗千山，肠断玉楼金阕。\n应是高唐小妇，妒娥清绝。\n夜凉不放酒杯寒，醉眼渐生缬。\n何待桂花相照，有人人如月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10048, '好事近', '范成大', '昨夜报春来，的岭梅开雪。\n携手玉人同赏，比看谁奇绝。\n阑干倚遍忆多情，怕角声呜咽。\n与折一枝斜戴，衬鬓云梳月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10049, '卜算子', '范成大', '凉夜竹堂虚，小睡匆匆醒。\n银漏无声月上阶，满地阑干影。\n何处最知秋，风在梧桐井。\n不惜骖鸾弄玉箫，露湿衣裳冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10050, '卜算子', '范成大', '云压小桥深，月到重门静。\n冷蕊疏枝半不禁，更著横窗影。\n回首故园春，往事难重省。\n半夜清香入梦来，从此熏炉冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10051, '三登乐', '范成大', '一碧鳞鳞，横万里、天垂吴楚。\n四无人、橹声自语。\n向浮云、西下处，水村烟树。\n何处系船，暮涛涨浦。\n正江南、遥落後，好山无数。\n尽乘流、兴来便去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10052, '三登乐', '范成大', '路转横塘，风卷地、水肥帆饱。\n眼双明、旷怀浩渺。\n问菟裘、无恙否，天教重到。\n木落雾收，故山更好。\n过溪门、休荡桨，恐惊鱼鸟。\n算年来、识翁者少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10053, '三登乐', '范成大', '今夕何朝，披岫幌、云关重启。\n引冰壶、素空似洗。\n卷帘中、枕上，月星浮水。\n天镜夜明，半窗万里。\n盼庭柯、都老大，树犹如此。\n六年前、转头未几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10054, '三登乐', '范成大', '方帽卫寒，重检校、旧时农圃。\n荒三径、不知何许。\n但姑苏台下，有苍然平楚。\n人笑此翁，又来访古。\n况五湖、元自有，扁舟祖武。\n记沧洲、白鸥伴侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10055, '浪淘沙', '范成大', '黯淡养花天。\n小雨能悭。\n烟轻云薄有无间。\n官柳丝丝都绿遍，犹有春寒。\n空翠湿征鞍。\n马首千山。\n多情若是肯俱还。\n别有玉杯承露冷，留共君看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10056, '虞美人', '范成大', '霜馀好探梅消息。\n日日溪桥侧。\n不如君有似梅人。\n歌里工颦妍笑、两眉春。\n疏枝冷蕊风情少。\n却称衰翁老。\n从教来作静中邻。\n冷淡无言无笑、也无颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10057, '虞美人', '范成大', '落梅时节冰轮满。\n何似中秋看。\n琼楼玉宇一般明。\n只为娥、添了万枝灯。\n锦江城下杯残後。\n还照鄞江酒。\n天东相见说天西。\n除却衰翁和月、更谁知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10058, '虞美人', '范成大', '玉箫惊报同云重。\n仍怪金瓶冻。\n清明将近雪花翻。\n不道海堂消瘦、柳丝寒。\n王孙沈醉狨毡幕。\n谁怕罗衣薄。\n烛灯香雾两厌厌。\n仿佛有人愁损、上眉尖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10059, '虞美人', '范成大', '谁将击碎珊瑚玉。\n装上交枝粟。\n恰如娇小万琼妃。\n涂罢额黄、嫌怕污燕支。\n夜深未觉清香绝。\n风露溶溶月。\n满身花影弄凄凉。\n无限月和风露、一齐香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10060, '醉落魄・一斛珠', '范成大', '春城胜绝。\n暮林风舞催花发。\n垂云卷尽添空阔。\n吹上新年，美满十分月。\n红蕖影下勾丝抹。\n老来牵强随时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10061, '步虚词・西江月', '范成大', '珠霄境，却似化人宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10062, '步虚词・西江月', '范成大', '浮黎路，依约太微间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10063, '步虚词・西江月', '范成大', '罡风起，背负玉虚廷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10064, '步虚词・西江月', '范成大', '流铃响，龙驭云来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10065, '步虚词・西江月', '范成大', '钧天奏，流韵满空明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10066, '步虚词・西江月', '范成大', '楼阑外，辇道插非烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10067, '玉楼春', '范成大', '佳人无对甘幽独。\n竹雨松风相澡浴。\n山深翠袖自生寒，夜久玉肌元不粟。\n却寻千树烟江曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10068, '霜天晓角', '范成大', '晚晴风歇。\n一夜春折威。\n脉脉花疏天淡，云来去、数枝雪。\n胜绝。\n愁亦绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10069, '玉楼春', '范成大', '云横水绕芳尘陌。\n一万重花春拍拍。\n蓝桥仙路不崎岖，醉舞狂歌容倦客。\n真香解语人倾国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10070, '醉落魄・一斛珠', '范成大', '马蹄尘扑。\n春风得意笙歌逐。\n款门不问谁家竹。\n只拣红装，高处烧银烛。\n碧鸡坊里花如屋。\n燕王宫下花成谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10071, '菩萨蛮', '范成大', '冰明玉润天然色。\n凄凉拼作西风客。\n不肯嫁东风。\n殷勤霜露中。\n绿窗梳洗晚。\n笑把玻璃盏。\n斜日上妆台。\n酒红和困来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10072, '眼儿媚', '范成大', '酣酣日脚紫烟浮。\n妍暖破轻裘。\n困人天色，醉人花气，午梦扶头。\n春慵恰似春塘水，一片纹愁。\n溶溶泄泄，东风无力，欲皱还休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10073, '惜分飞', '范成大', '画戟锦车皆雅故。\n箫鼓留连客住。\n南浦春波暮。\n难望罗袜生尘处。\n明日船旗应不驻。\n且唱断肠新句。\n卷尽珠帘雨。\n雪花一夜随人去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10074, '菩萨蛮', '范成大', '客行忽到湘东驿。\n明朝真是潇湘客。\n晴碧万重云。\n几时逢故人。\n江南如塞北。\n别後书难得。\n先自雁来稀。\n那堪春半时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10075, '满江红', '范成大', '千古东流，声卷地、云涛如屋。\n横浩渺、樯竿十丈，不胜帆腹。\n夜雨翻江春浦涨，船头鼓急风初熟。\n似当年、呼禹乱黄川，飞梭速。\n击楫誓，空惊俗。\n休拊髀，都生肉。\n任炎天冰海，一杯相属。\n荻笋蒌芽新入馔，弦凤吹能翻曲。\n笑人间、何处似尊前，添银烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10076, '谒金门', '范成大', '塘水碧。\n仍带麴尘颜色。\n泥泥纹无气力。\n东风如爱惜。\n恰似越来溪侧。\n也有一双。\n只欠柳丝千百尺。\n系船春弄笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10077, '秦楼月・忆秦娥', '范成大', '湘江碧。\n故人同作湘中客。\n湘中客。\n东风回雁，杏花寒食。\n温温月到蓝桥侧。\n醒心弦里春无极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10078, '醉落魄・一斛珠', '范成大', '雪晴风作。\n松梢片片轻鸥落。\n玉楼天半褰珠箔。\n一笛梅花，吹裂冻云幕。\n去年小猎漓山脚。\n弓刀湿遍犹横槊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10079, '霜天晓角', '范成大', '少年豪纵。\n袍锦团花凤。\n曾是京城游子，驰宝马、飞金。\n旧游浑似梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10080, '菩萨蛮', '范成大', '彤楼鼓密催金轮。\n沈沈青琐重重幕。\n宣唤晚朝天。\n五云笼暝烟。\n风急东华路。\n暖扇遮微雨。\n香雾扑人衣。\n上林乌满枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10081, '水调歌头', '范成大', '万里汉都护。\n（下缺）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10082, '水调歌头', '范成大', '万里桥边客。\n（下缺）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10083, '水调歌头', '范成大', '万里吴船泊，归访菊篱秋。\n（下缺）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10084, '醉落魄・一斛珠', '范成大', '栖乌飞绝。\n绛河绿雾星明灭。\n烧香曳簟眠清樾。\n花久影吹笙，满地淡黄月。\n好风碎竹声如雪。\n昭华三弄临风咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10085, '朝中措', '范成大', '长年心事寄林扃。\n尘鬓已星星。\n芳意不如水远，归心欲与云平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10086, '水龙吟', '范成大', '仙翁家在丛霄，五云八景来尘表。\n黄扉紫闼，化钧高妙，风霆挥扫。\n漠北寒烟，峤南和气，笑谈都了。\n自玉麟归去，金牛再款，却回首、人间少。\n天与丹台旧籍，笑苍生、祝公难老。\n春葩秋叶，喧寒易变，壶天长好。\n物外新闻，凤歌鸾翥，龙蟠虎绕。\n想如心高会，寒霜夜永，尽横参晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10087, '满江红', '范成大', '山绕西湖，曾同泛、一篙春绿。\n重会面、未温往事，先翻新曲。\n劲柏乔松霜雪後，知心惟有孤生竹。\n对荒园、犹解两高歌，空惊俗。\n人更健，情逾熟。\n樱共柳，冰和玉。\n恐相逢如梦，夜阑添烛，别後书来空怅望，尊前酒到休拘束。\n笑簟瓢、未足已能狂，那堪足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10088, '青玉案', '王质', '中央自有仙风度。\n散入千林去。\n万点秋芳洒飞露。\n舜裳赭色，尧眉黄彩，化作花无数。\n层层翠葆鸾旗舞。\n吹下天香遍瑶宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10089, '青玉案', '王质', '浮萍不碍鱼行路。\n细数鱼来去。\n静倚溪阴深觅句。\n碧鲜清润，影摇香度。\n易觉阑干暮。\n凫雏深傍苹根住。\n浴罢红衣褪残缕。\n一寸江湖无可付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10090, '江城子', '王质', '细风微揭碧鳞鳞。\n绣帏深。\n不闻声。\n时见推帘，笼袖玉轻轻。\n不似绮楼高卷幔，相指点，总分明。\n斜湾丛柳暗阴阴。\n且消停。\n莫催行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10091, '江城子', '王质', '细风吹起翠田田。\n雨和烟。\n入梅天。\n鲜润繁阴，悄悄转清圆。\n十顷蒲萄深贮碧，鸥共鹭，各翩翩。\n影摇香度小婵娟。\n竹林贤。\n总神仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10092, '江城子', '王质', '柳梢无雪受风吹。\n绿垂垂。\n乳鸦啼。\n直下蒲萄，春水未平堤。\n却似今年春气早，白团扇，已相宜。\n红巾当日鸟衔飞。\n曲江湄。\n暮春时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10093, '蓦山溪', '王质', '枯林荒陌，矮树敷鲜叶。\n不见雅风标，十二分、山容野色。\n因何嫩茁，舞动小旗枪，梅花後，杏花前，色味香三绝。\n含光隐耀，尘土埋豪杰。\n试看大粗疏，争知变、寒云飞雪。\n休说休说，世只两名花，芍药相，牡丹王，未尽人间舌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10094, '满江红', '王质', '方丈维摩，蒙衲被、都齐不省。\n空怅望、锦裘绣帽，玉珂金镫。\n十月小春逢此日，一时胜事输公等。\n问短衣、匹马射南山，何人肯。\n山暮紫，峰如笋。\n江寒碧，沙如粉。\n望塞鸿杳杳，水遥天永。\n饮罢不妨瓶屡卧，归来自有风吹醒。\n试断桥、流水月明边，寻疏影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10095, '满江红', '王质', '整顿乾坤，恨无袖、回旋不足。\n须付与、腰金叠赤，面槐参绿。\n功业岂无人可了，英豪自有心相伏。\n自孤窗、寒烛听经纶，常三复。\n举大白，倾。\n为公起，歌此曲。\n曲中意惟有，斯贤堪属。\n萱草喜除烦恼障，莲花妙享清凉福。\n愿年年、团扇弄生绡，长如玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10096, '满江红', '王质', '惨淡轻阴，都养就、朱朱白白。\n最好是、梨花带雨，海棠映日。\n暖雾烘成芳草色，娇风分与垂杨力。\n听红边、翠杪啭清圆，曾相识。\n春绪乱，还如织。\n春梦断，还堪觅。\n看青梅下有，游人啧啧。\n爱酒正香须满泛，怜花太嫩休轻摘。\n把领巾、收聚众香浓，凭风立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10097, '满江红', '王质', '生平铺，吹不起、轻风无力。\n西江上、斗牛相射，水天一色。\n二妙风流今代少，一时光价何时息。\n更绛霄、白日下云，芙蓉客。\n整飞驭，成得得。\n寻前约、宽忆忆。\n正云飞雨卷，旧红新碧。\n茁茁抽长荷柄绿，毵毵吐净杨花白。\n渐衣篝、香润入梅天，红绡湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10098, '满江红', '王质', '莽莽云平，都不辨、近山远水。\n尽徘徊、尚留波面，未归湾尾。\n浪猛深深鸥抱稳，波寒缩缩鱼沈底。\n恐狂风、颠雨岸多摧，舟难舣。\n船篷重，拖不起。\n蓑衣湿，森如洗。\n想杖头未足，杯中无计。\n渔网吹翻无把捉，钓竿冻断成抛弃。\n到高歌、风静月明时，谁如你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10099, '满江红', '王质', '落尽斜阳，尚有些、断霞残影。\n甚弯环、东溪西巷，南岩北岭。\n行熟更教羊引著，睡浓却被鸦惊醒。\n渐孤村、树暗颤山，霜风冷。\n人世里，嫌他蠢。\n牛背上，输他稳。\n但芒鞋一，蓑衣一领。\n五脏荒陂蔬荐口，双幽崦花漫顶。\n虽云乌、月黑路蒙笼，何曾窘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10100, '满江红', '王质', '纸张梅花，有丛桂、又有修竹。\n是何声、雪飘远渚，泉鸣幽谷。\n红蓼白苹须拂袖，馀音尚带清香馥。\n挽素娥青女、问飞琼，谁家曲。\n韩退之，欧永叔。\n惚兮恍，恍兮惚。\n试侧耳，山常似黛，水常如玉。\n颜子操中何足怨，醉翁徽外无人续。\n正青天、明月上东南，芳时足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10101, '水调歌头', '王质', '江水去无极，无地有青天。\n怒涛汹涌，卷浪成雪蔽长川。\n一望扬州苍莽，隐见烟竿双矗，何处卷珠帘。\n落日瓜洲渡，鸿鹭满风前。\n古战场，皆白草，更苍烟。\n清平犹有遗恨，久矣在江边。\n北固山前三杰，遥想当年意气，づづ昵中原。\n上马促归去，风堕接翩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10102, '水调歌头', '王质', '细数十年梦，十处过中秋。\n今年清梦，还在黄鹤旧楼头。\n老子个中不浅，此会天教重见，今古一南楼。\n星汉淡无色，玉锦倚空浮。\n带秦烟，萦楚雾，熨江流。\n关河离合南北，依旧照清愁。\n想见娥冷笑，笑我归来霜鬓，空敝黑貂裘。\n把酒问清影，肯去伴沧洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10103, '水调歌头', '王质', '晚嶂倚斜日，秋树战悲风。\n一泓绀紫澄碧，中有睡蛟龙。\n散作清溪明玉，激上长松流水，雨电乱寒空。\n抛却红尘袂，飞入妙光宫。\n佛国大，天溥博，地含洪。\n空岩乱壑递响，珠影动金容。\n万古碧潭空界，一点青霄明月，涝漉总无功。\n云散殿突兀，风动铎丁东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10104, '水调歌头', '王质', '草蔓已多露，松竹总含风。\n群山左顾右盼，如虎更如龙。\n时见渔灯三两，知在谁家浦溆，星斗烂垂空。\n万有付一扫，人世等天宫。\n秋萧瑟，林脱叶，水归洪。\n江湖飘泊鸿雁，洲渚肯相容。\n要使群生安堵，不听三更吠犬，此则是奇功。\n一任画麟阁，吾自老墙东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10105, '水调歌头', '王质', '云在空碧，天宇共高明。\n重阳易得风雨，今日不胜晴。\n天为两朝元老，付与四时佳节，不动一丝尘。\n香霭洗金戟，飞雾洒霓旌。\n山鸣叶，江动石，总欢声。\n剑关玉垒千载，谁见此升平。\n细看尊前万蕊，相映眉间一点，黄气郁。\n江汉下淮海，都赖一长城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10106, '水调歌头', '王质', '花上插苍碧，花下走清湍。\n浓霜深覆残雪，更有月相参。\n似我竹溪茅屋，欲晓未明天气，扶杖绕篱看。\n秦楚五千里，何处是江南。\n饶风下，人不断，马相连。\n颇尝见有此客，相属意。\n欲为横吹出塞，无处可寻羌管，短策叩征鞍。\n策断征鞍裂，惊坠玉毵毵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10107, '水调歌头', '王质', '淮海一星出，分野到梁州。\n玉京群帝朝斗，公在列仙流。\n尽扫枪格泽，高拱紫微太乙，霞佩拂红。\n非雾非烟里，永侍绀云裘。\n日南至，月既望，寿君侯。\n梅花满眼，一朵聊当一千秋。\n半夜玉堂承诏，翼旦路朝宣册，归去作班头。\n风静瞿塘峡，安稳放行舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10108, '水调歌头', '王质', '河汉湛秋碧，玉露嗳瑶空。\n太清仙子，飘渺飞佩响玲珑。\n暂驭青鸾紫凤，来玩十洲三岛，旌旆卷芙蓉。\n身在大江表，名系绛霄宫。\n两仙客，歌驻月，舞迥风。\n宝薰轻度帘幕，香雾结重重。\n已觉长安近日，会看此星朝斗，千载庆云龙。\n翠霭彤烟里，长侍衮衣红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10109, '八声甘州', '王质', '海茫茫、天北与天南，吾友定安归。\n闻濡须江上，皖公山下，驾白云飞。\n莽苍空郊虚野，古路立斜晖。\n颜跖皆尘土，苦泪休挥。\n一代锦肠绣肺，想英魂皎皎，健口霏霏。\n望寒空明月，无路寄相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10110, '八声甘州', '王质', '事茫茫、赤壁半帆风，四海忽三分。\n想苍烟金虎，碧云铜爵，恨满乾坤。\n郁郁秣陵王气，传到第三孙。\n风虎云龙会，自有其人。\n朱颜二十有四，正锦帏秋梦，玉帐春声。\n望吴江楚汉，明月伴英魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10111, '八声甘州', '王质', '过隆中、桑柘倚斜阳，禾黍战悲风。\n世若无徐庶，更无庞统，沈了英雄。\n本计东荆西益，观变取奇功。\n转尽青天粟，无路能通。\n他日杂耕渭上，忽一星飞坠，万事成空。\n使一曹三马，云雨动蛟龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10112, '八声甘州', '王质', '气佳哉、烟紫石头城，云碧雨花台。\n想东山前後，望春树绿，看晚潮回。\n自古英雄豪杰，无不待时来。\n拥鼻微吟处，山静花开。\n商皓亦常如此，羡苍生皆有，瞻望之怀。\n但淝河洛涧，此事偶然谐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10113, '倦寻芳', '王质', '冰壶秋月，去了潘郎，传到梁老。\n骑马乘船，麾斥五湖三岛。\n任捎云，兼拂日，拽蛟龙、鳞鬣都推倒。\n厢尘中，分付高人胜士，把云烟扫。\n乾坤巧。\n自苍筠无汗，乌锥无刃，此为至宝。\n第一君门通表。\n书囊谏草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10114, '倦寻芳', '王质', '断崖树老，侧岸槎枯，倒倚斜插。\n脚面浅溪，掌样平洲重叠。\n著芒鞋，携竹杖，遇乱莎幽涧萦纡涉。\n那人家，有竹笋瓦缶。\n颇颇清冽。\n曾微呷。\n正斜阳淡淡，暮霭昏昏，晚风猎猎。\n转眼已成陈迹。\n不堪追蹑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10115, '万年欢', '王质', '一轮明月，古人心万年，更寸心存。\n沧海化为黄土，心不成尘。\n杳杳兴亡成败，满乾坤、未见知音。\n抚阑干、欲唤英魂，沈沈又没人应。\n无聊枕搔首，梦庐中坛上，一似平生。\n共挽长江为酒，相对同倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10116, '真珠帘', '王质', '翠虬夭矫拿苍玉。\n飞来到、吾庐溪湾山麓。\n一笑忽相逢，更解包投宿。\n北池之畔西墙曲，与主人、呼青吸绿。\n恨我，无天寒翠袖，共倚修竹。\n每遇飞雪萧萧，更惊风槭槭，清标可掬。\n更与月同来，无半点尘俗。\n冬有寒梅闲相伴，春亦有、幽兰相逐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10117, '沁园春', '王质', '二百年间，十二时中，悲欢往来。\n但盖头一把，容身方丈，无多缘饰，莫遣尘埃。\n屈曲成幽，萧条生净，野草闲花都妙哉。\n家无力，虽然咫尺，强作萦回。\n竹斋。\n向背松斋。\n须次第、春兰秋菊开。\n在竹篱虚处，密栽甘橘，荆桥斜畔，疏种香梅。\n山芋羹，地黄酿粥，冬後春前皆可栽。\n门通水，荷汀蓼渚，足可徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10118, '红窗怨', '王质', '欲寄意，都无有。\n且须折赠、市桥官柳。\n看君著上征衣，也寻思、榜舟楚江口。\n此会未知何时又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10119, '红窗怨', '王质', '帘不卷。\n人难见。\n缥缈歌声，暗随香转。\n记与三五少年，在杭州、曾听得几遍。\n唱到生绡白团扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10120, '凤时春', '王质', '标格风流前辈。\n才瞥见春风，萧然无对。\n只有月娥心不退。\n依旧断桥，横在流水。\n我亦共、月娥同意。\n肯将情移在，粗红俗翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10121, '泛兰舟', '王质', '萧萧乌帽黄衫。\n元水拍云岩。\n风清月白，一双碧眼莹秋潭。\n四海九州，茫茫东北，渺渺西南。\n松霜杉露毵毵。\n龙门隔如参井，青城佳气与天参。\n蔽山充野，牡丹红外茯苓甘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10122, '无月不登楼', '王质', '池塘生春草，梦中共、水仙相识。\n细拨冰绡，低沈玉骨，搅动一池寒碧。\n吹尽杨花，糁毡消白。\n却有青钱，点点如积。\n渐成翠、亭亭如立。\n汉女江妃入奁室。\n掰破靓妆拥出。\n夜月明前，夕阳後，清妙世间标格。\n中贮琼瑶汁。\n才嚼破、露飞霜泣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10123, '别素质・忆瑶姬', '王质', '一个茅奄，三间七架。\n两畔更添两厦。\n倒坐双亭平分，扶阑两下。\n门前数十丘。\n塍外更百十株桑柘。\n一溪活水长流，馀波及、蔬畦菜把。\n便是招提与兰若。\n时钞疏乡园，看经村社。\n随分斗米相酬，环钱相谢。\n便阕少亦堪借借。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10124, '笛家弄・笛家', '王质', '凌乱败荷，既似沙莞，又如淝水。\n颠倒旌旗都靡。\n馀花谢，又似乌江，骓兮不逝。\n虞兮奈尔。\n凋柳萧骚，又如轵道，故老何颜对。\n因缘断。\n时节转。\n自然如彼。\n自然如此。\n水边沙际。\n芦花摇曳。\n唤住行人，蓼花妩媚。\n引翻游子。\n又似江都酣夜延秋，建业望仙结绮。\n月下心飞，风前骨醉。\n共苹花得意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10125, '念奴娇', '沈瀛', '郊原浩荡，正夺目花光，动人春色。\n白下长干佳丽最，寒食嬉游人物。\n雾卷香轮，风嘶宝骑，云表歌声遏。\n归来灯火，不知斗柄西揭。\n六代当日繁华，幕天席地，醉拍江流窄。\n游女人人争唱道，缓缓踏青阡陌。\n乐事何穷，赏心无限，惟惜年光迫。\n须臾聚散，人生真信如客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10126, '念奴娇', '沈瀛', '梧桐响雨，忆空江寒浪，渔舟冲雪。\n横卧云峰千叠嶂，风旆槽香新压。\n网跃银刀，纶收钩线，倚棹清歌发。\n征鸿嘹亮，助予闲奏音节。\n天上桂子阴成，月中香旧，几度人间别。\n玉斧匣中常夜吼，可惜光阴虚设。\n唤下云梯，直攀金户，打透重门铁。\n娥念旧，料应重许人折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10127, '念奴娇', '沈瀛', '春来腊去，一番新风景，为君开设。\n试忆前时花雨坠，只少梅花清绝。\n两个难逢，一分才欠，巧杀终如拙。\n玉梅人唤，雪儿来对时节。\n应更付属楼头，丁宁笛伴，莫把声声彻。\n玉女行春娇渡马，休是鹊桥轻别。\n对我三人，与君一醉，醉了樽重设。\n清歌未放，更须天上呼月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10128, '念奴娇', '沈瀛', '赏心佳处，登临地、千古人人都说。\n何况江天来雪望，添得十分奇绝。\n倚遍栏干，下窥寒镜，照我容颜拙。\n举头惊笑，问今天是何节。\n天外矗矗琼山，溶溶银海，上下光相接。\n年去岁来频览为，何事今朝浑别。\n坐蹴云茵，横牵绡幕，玉女来铺设。\n公馀多暇，正堪同此风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10129, '念奴娇', '沈瀛', '阳春布暖，又还见、光景如梭催逼。\n帝里皇都人共道，好个前时春色。\n默默暗沈，含颦不语，此意谁人识。\n何如索笑，放开说尽端的。\n须信漏泄风光，百花头上，报一枝消息。\n多少园林应次第，迤逦排红骈白。\n金鼎芳滋，玉堂璀璨，趁取佳时节。\n东君归後，绿阴依旧南陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10130, '念奴娇', '沈瀛', '万般照破，无一点闲愁，萦系心目。\n种柳栽花园数亩，不觉吾庐幽独。\n闲上高台，溪光山色，一洗襟尘俗。\n小庵深处，萧然无限修竹。\n尽日闭却柴门，故人相问，扣户来车毂。\n相对围棋看胜负，更听弹琴一曲。\n尔汝忘形，高谈剧论，莫遣人来促。\n村歌社舞，为予倒尽千斛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10131, '念奴娇', '沈瀛', '光阴转毂，况生死事大，无常迅速。\n学道参禅、要识取，自家本来面目。\n闹里提撕，静中打坐，闲看传灯录。\n话头记取，要须生处教熟。\n一日十二时中，莫教间断，念念来相续。\n唤作竹蓖还则背，不唤竹蓖则触。\n斩却猫儿，问他狗子，更去参尊宿。\n忽然瞥地，碧潭冷浸寒玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10132, '满江红', '沈瀛', '姑孰名邦，黄山畔、古台巍立。\n秋渐老、重阳天气，郊原澄碧。\n隐隐西州增远望，长江一带平如席。\n怅英雄、千古到如今，空遗迹。\n吴太守，文章伯。\n寻胜事，酬佳节。\n拥笙歌千骑，遍游南陌。\n襟带江城当一面，折冲千里无强敌。\n更行看、击楫溯中流，妖氛息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10133, '满江红', '沈瀛', '半世飘蓬，今何幸、得归乡曲。\n却还似、重来燕子，认巢新屋。\n好是秋晴风日美，饭香云子炊如玉。\n念蟹螯、满把欲黄时，笋新绿。\n仍更有，初开菊。\n何妨更，重添竹。\n与此君相对，且无荣辱。\n待得吾庐三径就，此生素愿都齐足。\n任三竿、红日上檐梢，眠方熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10134, '水调歌头', '沈瀛', '潇洒云中鹤，容与水边鸥。\n缑山仙客，飘然曾约此中留。\n更有骑鲸公子，相与翱翔八极，凛凛气横秋。\n明月楼头宴，樽俎好诗流。\n思往事，增逸兴，唤仙舟。\n谁能拘束，尘埃堆里蹙昏眸。\n拟附星槎直上，十二玉京绛阕，高处且嬉游。\n回首视人世，天地一沙舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10135, '水调歌头', '沈瀛', '岁月如奔箭，屈指又中秋。\n去年江上行役，常动故乡愁。\n容与碧云亭畔，极目江山千里，隐隐是西州。\n日暮天容敛，鸥雁下汀洲。\n迥故棹，寻旧里，解客裘。\n功名前定，时到安得为淹留。\n幸有青编万轴，且又日长无事，莫恁做闲忧。\n花下常携酒，明月好登楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10136, '水调歌头', '沈瀛', '门外可罗雀，长者肯来寻。\n留君且住，听我一曲楚狂吟。\n枉了闲烦闲恼，莫管闲非闲是，说甚古和今。\n但看镜中影，双鬓已星星。\n人生世，多聚散，似浮萍。\n适然相会，须索有酒且同倾。\n说到人情真处，引入无何境界，惟酒是知音。\n况有好风月，相对且频斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10137, '满庭芳', '沈瀛', '画戟霜匀，谯门风动，满城和气氤氲。\n一年好事，今朝属东君。\n歌管欢迎五马，金章烂、华毂朱轮。\n班春了，归来燕寝，香重烛花轻。\n盈盈。\n春酒暖，金幡彩胜，霞袂云旌。\n算重重佳庆，都聚今辰。\n且听雪儿歌罢，称寿处、兰玉诜诜。\n新春暖，貂蝉象服，同日感皇恩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10138, '满庭芳', '沈瀛', '春琐琼台，花藏瑶圃，彩云片片来归。\n任城仙子，玉芨镇长移。\n时会三元金母，云奏、天上佳期。\n嬉游处，飘然侍女，玉佩紫霞衣。\n芙蓉帔欲去，鸾音鹤驭，洞府应迷。\n向人间挥手，留语人知。\n此去何须怅望，蓬莱水、弹指依稀。\n还知否，刘安未老，仙籍有津涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10139, '满庭芳', '沈瀛', '裘带功名，裤襦歌颂，世间谁似公贤。\n去年江上，谈笑息狼烟。\n多少宜民事了，芹宫内、华屋修椽。\n邦人爱，频频借寇，飞诏下甘泉。\n开筵。\n春昼永，朱颜相对，三凤齐肩。\n正鸾鸣丹桂，凤映红莲。\n人道名驹千里，他年事、能继青毡。\n休辞醉，三槐影里，岁岁捧金船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10140, '满庭芳', '沈瀛', '柳外山光，林间塔影，一溪横泻清流。\n四围洲渚，绿叶泼如油。\n荷盖亭亭照水，红蓼岸、芦荻萧飕。\n乘闲兴，溪云亭畔，终日看莲游。\n修篁栽欲遍，青松相映，两径成丘。\n种桃杏，随时亦弄春柔。\n此是先生活计，高卧处、无喜无忧。\n门前事，人来问我，回首但摇头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10141, '朝中措', '沈瀛', '论兵齿颊带霜寒。\n清似碧琅。\n好是天然风韵，琳宫瑶馆清闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10142, '朝中措', '沈瀛', '东风吹上小桃枝。\n春色拥旌麾。\n昨夜三台星见，分明直照姑溪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10143, '西江月', '沈瀛', '五马人生最贵，金陵自古繁华。\n光悬相印拥朱牙。\n况值边庭闲暇。\n满劝东西碧玉，高烧丽烛红葩。\n诏黄新湿字如鸦。\n明日天庭飞下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10144, '醉落魄・一斛珠', '沈瀛', '野庵吹鼓。\n翻腾似与寻常异。\n笙萧筝笛皆非是。\n今日头场，看取些儿戏。\n心中无事无萦系。\n村歌数首新来制。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10145, '醉落魄・一斛珠', '沈瀛', '时光盛逼。\n杯盘渐渐来收拾。\n主人便欲留连客。\n末後殷勤，一著怎生得。\n来时便有归时刻。\n归时便是来时迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10146, '醉落魄・一斛珠', '沈瀛', '致知格物。\n初学工夫参圣域。\n天高地远无穷极。\n欲造精微，莫若守惟一。\n纯全天理明如日。\n都缘人欲来相惑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10147, '醉落魄・一斛珠', '沈瀛', '致知格物。\n孔颜学问从兹出。\n圣言句句皆真实。\n涵养功深，将见自家得。\n毋意毋我毋固必。\n视听言动非礼勿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10148, '柳梢青', '沈瀛', '相逢今夕。\n故人相见，先谈踪迹。\n旧日书生，而今村叟，新来禅客。\n跳过世界三千，特特地、人间九百。\n自在狂歌，□□□□，一场杂剧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10149, '行香子', '沈瀛', '野叟愚痴。\n一向昏迷。\n笑呵呵、前事皆非。\n从前业债，今尽拼离。\n也不能文，不能酒，不能诗。\n屏除人事，闭却门儿。\n於奇中、别有儿戏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10150, '行香子', '沈瀛', '野叟归欤。\n朋友来无。\n数无多、几个相於。\n问谁姓字，在底中居。\n云陶靖节，白居士，邵尧夫。\n时时对语，一笑轩渠。\n他行藏、是我规模。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10151, '行香子', '沈瀛', '野叟长年。\n一室萧然。\n都齐收、万轴牙签。\n只留三件，三教都全。\n时看周易，读庄子，诵楞严。\n阕会得，万语千言。\n得鱼儿、了後忘筌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10152, '卜算子', '沈瀛', '睡觉五更钟，正好深提省。\n只看如今梦几般，觉後原无影。\n明暗若从来，且道来从甚。\n不是空生不是根，认取真如性。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10153, '卜算子', '沈瀛', '那里是闲时，这里何曾定。\n毕竟忙时恼杀人，到了还他静。\n静处又如何，莫被顽空引。\n一道神光总现前，受用无穷尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10154, '卜算子', '沈瀛', '只管要参禅，又被禅萦绕。\n好笑西来老秃奴，赚了人多少。\n你待更瞒咱，咱也今知晓。\n只这喃喃说底人，又被傍人笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10155, '如梦令', '沈瀛', '才听笛声三弄。\n关捩一时都动。\n收拾去来休，三脚驴儿相送。\n珍重。\n珍重。\n归去好生作梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10156, '捣练子', '沈瀛', '神欲出，便收来。\n神返心中气自回。\n换丹元，朝玉台。\n时运水，日搬柴。\n寸田一点是根。\n这交梨，常种栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10157, '捣练子', '沈瀛', '神欲出，便收来。\n神返心中气自回。\n返婴儿，成圣胎。\n灵液注，蕊珠开。\n大丹炉里响如雷。\n忽飞升，游九垓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10158, '捣练子', '沈瀛', '放下著，须弥山。\n分明北斗面南看。\n没丝毫，相阻拦。\n休侗，莫颟顸。\n含元殿上问长安。\n欲归家，行路难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10159, '捣练子', '沈瀛', '放下著，须弥山。\n百斛油麻水上摊。\n欲成团，真个难。\n除有累，去痴顽。\n无心犹是隔重关。\n到其中，方是安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10160, '捣练子', '沈瀛', '放下著，须弥山。\n情人今日出阳关。\n看人间，天地宽。\n徒缱绻，枉酒澜。\n别郎容易见郎难。\n且还家，重整冠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10161, '浣溪沙', '沈瀛', '雨点真珠水上鸣。\n更将青盖一时倾。\n总是江妃来坠珥，访娉婷。\n不为含愁啼粉泪，只因贪爱湿行云。\n惟有游鱼偏得意，许成群。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10162, '画堂春', '沈瀛', '荷花含笑调薰风。\n两情著意尤浓。\n水精栏槛四玲珑。\n照见妆容。\n醉里偷开盏面，晓来暗坼香风。\n不知何事苦匆匆。\n飘落残红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10163, '减字木兰花', '沈瀛', '乘流坎止。\n住个斋儿无愠喜。\n竹引清风。\n透入虚窗窍窍通。\n仰天酌酒。\n万八千年磐古寿。\n身在无何。\n只这斋儿已自多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10164, '减字木兰花', '沈瀛', '蓬门居止。\n竹见宾来先啸喜。\n窗外敲风。\n果有宾朋姓字通。\n莫嫌村酒。\n且祝佳宾万千寿。\n无用辞何。\n日出明朝事更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10165, '减字木兰花', '沈瀛', '停杯且止。\n斋里百无为客喜。\n冷淡文风。\n只有狂言数百通。\n不须载酒。\n粗有五车聊当寿。\n莫笑予何。\n空恁贪多嚼不多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10166, '减字木兰花', '沈瀛', '或行或止。\n难得人间相聚喜。\n一日分风。\n千里如何信息通。\n再倾寿酒。\n五福从来先说寿。\n其次云何。\n直至三公未足多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10167, '减字木兰花', '沈瀛', '渊明酒止。\n莫信渠言心妄喜。\n达士高风。\n只说三杯大道通。\n不如饮酒。\n人世岂能金石寿。\n无奈渠何。\n赢得尊前笑语多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10168, '减字木兰花', '沈瀛', '老而不止。\n三岁发蒙心已喜。\n朴略其风。\n裴楷王戎简要通。\n昏如醉酒。\n羞见总龟灵且寿。\n笑杀常何。\n空有闲言长语多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10169, '减字木兰花', '沈瀛', '不能者止。\n百念灰心无所喜。\n暖日和风。\n手把奇文诵数通。\n老来怯酒。\n欲保残生期养寿。\n少恕予何。\n近日衰翁病觉多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10170, '减字木兰花', '沈瀛', '且安汝止。\n快活心中惟法喜。\n一处通风。\n万别千差处处通。\n腐肠是酒。\n伐性蛾眉徒损寿。\n诗到阴何。\n地乱丝头绪多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10171, '减字木兰花', '沈瀛', '不如知止。\n看尽世间无可喜。\n心热生风。\n王老门前问仲通。\n六经如酒。\n一句中人仁者寿。\n仁道伊何。\n要处还他静处多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10172, '减字木兰花', '沈瀛', '动而思止。\n止即患生徒自喜。\n试举幡风。\n未举之前说已通。\n携瓶沽酒。\n却著衫来为我寿。\n者也之何。\n赚却阎浮世上多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10173, '减字木兰花', '沈瀛', '贪而忘止。\n贪即生逢饱喜。\n一逐贪风。\n恨不当初嫁邓通。\n残杯剩酒。\n食籍名中犹折寿。\n若使兼何。\n他日阴司罪过多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10174, '减字木兰花', '沈瀛', '人无常止。\n暮四朝三时怒喜。\n怪雨嫌风。\n高耳皇天下听通。\n刚而使酒。\n骂坐灌夫忘客寿。\n若予何。\n夫子雍容语不多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10175, '减字木兰花', '沈瀛', '心如皎止。\n何必佯痴藏暗喜。\n聋不听风。\n要得人情内外通。\n半半酒。\n痴黠恺之真短寿。\n莫折随何。\n宁可书痴胜彼多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10176, '减字木兰花', '沈瀛', '纠缠弗止。\n成是败非生戚喜。\n即灭灾风。\n否极还须有泰通。\n祸常因酒。\n酒亦令人能介寿。\n成也萧何。\n败也萧何更是多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10177, '减字木兰花', '沈瀛', '贪容肯止。\n结绶弹冠王贡喜。\n稍借天风。\n便说今年运大通。\n华亭别酒。\n安得思如亭鹤寿。\n贵若从何。\n只恐来生折本多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10178, '减字木兰花', '沈瀛', '瞻乌爰止。\n不是檐前闻鹊喜。\n上下鸣风。\n以类相从自感通。\n嫌茶爱酒。\n恶彼芝焚夸柏寿。\n说汝言何。\n一切人言口众多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10179, '减字木兰花', '沈瀛', '未行先止。\n鱼上竹竿人噪喜。\n九万鹏风。\n六月天池一息通。\n邯郸鲁酒。\n却笑行人陵柏寿。\n笑彼迟何。\n不道能行失亦多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10180, '减字木兰花', '沈瀛', '圣经五止。\n止向丘隅黄鸟喜。\n广大儒风。\n一贯三才万类通。\n太羹玄酒。\n圣域能跻民域寿。\n支派从何。\n关内濂溪洛涧多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10181, '减字木兰花', '沈瀛', '定而後止。\n善到止时心地喜。\n鱼跃鸢风。\n此理昭然上下通。\n好如好酒。\n欲似人常心欲寿。\n若到兹何。\n治国治家用处多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10182, '减字木兰花', '沈瀛', '朱幡归止。\n却返烟霞寻旧喜。\n羽帔香风。\n再拜天门直上通。\n青君赐酒。\n乞与长生无量寿。\n更挟仙何。\n跨鹤凌云洞府多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10183, '减字木兰花', '沈瀛', '气开气止。\n引得丹元童子喜。\n耳里闻风。\n知是泥丸一窍通。\n危楼宴酒。\n不觉黄芽生蕊寿。\n牙长如何。\n只觉金花罩体多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10184, '减字木兰花', '沈瀛', '琴心和止。\n姹女与君相对喜。\n窗牖藏风。\n每唤其名应即通。\n玉英金酒。\n更唤黄婆同饮寿。\n莫讳人何。\n见说婴儿屋里多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10185, '减字木兰花', '沈瀛', '工夫莫止。\n脱得壳儿方是喜。\n不识真风。\n只说双关夹脊通。\n氤氲似酒。\n元气本同天地寿。\n君可能何。\n一跃红楼好处多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10186, '减字木兰花', '沈瀛', '擎拳仰止。\n不是凡人名尹喜。\n道骨仙风。\n与帝神游结信通。\n献花跪酒。\n清彻云歌益寿。\n所愿维何。\n愿得升平乐事多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10187, '减字木兰花', '沈瀛', '雨难禁止。\n恼得衰翁浑没喜。\n一夜南风。\n北望苕溪震泽通。\n只鸡斗酒。\n且为晚禾生日寿。\n不奈之何。\n今岁田畴晚底多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10188, '减字木兰花', '沈瀛', '寿诗且止。\n设席肆筵谁助喜。\n抹月批风。\n先向天厨号令通。\n满卮天酒。\n上与天田同日寿。\n其应维何。\n寿及天民性命多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10189, '减字木兰花', '沈瀛', '玉人来止。\n见说冰翁心甚喜。\n好个家风。\n举案齐眉胜敬通。\n华堂举酒。\n簇簇亲姻相祝寿。\n善颂言何。\n桂树鸾鸣子姓多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10190, '减字木兰花', '沈瀛', '谁来贲止。\n千里得朋方切喜。\n汪氏门风。\n大学中庸正脉通。\n不妨诗酒。\n请以还丹为荐寿。\n已过羊何。\n绍述韩门得趣多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10191, '减字木兰花', '沈瀛', '凌波不止。\n少小拍浮荷女喜。\n出没由风。\n安得灵犀与暗通。\n龙池醉酒。\n应是太真羞见寿。\n不晓谁何。\n却是浑身一半多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10192, '减字木兰花', '沈瀛', '渴心先止。\n惟有杨家梅可喜。\n争笑梅风。\n空怨楼头角数通。\n甜浆酿酒。\n紫气结成千日寿。\n不奈人何。\n化作飞星处处多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10193, '减字木兰花', '沈瀛', '必恭敬止。\n老子甚为桑梓喜。\n骏马争风。\n诗卷人人数百通。\n斗杓挹酒。\n齐祝乡人箕翼寿。\n天若言何。\n更乞文星下照多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10194, '减字木兰花', '沈瀛', '锦囊送止。\n拆看篇篇珠玉喜。\n大胜鱼风。\n韶沪宫商角徵通。\n醉而强酒。\n有愧多闻张子寿。\n其哂由何。\n刻画无盐已甚多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10195, '减字木兰花', '沈瀛', '竹斋陋止。\n坐客无毡为客喜。\n壁不遮风。\n八达门窗更四通。\n邻家觅酒。\n赤脚扶翁翁老寿。\n子曰其何。\n除却渠侬没事多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10196, '减字木兰花', '沈瀛', '荷公临止。\n宾客惯看儿亦喜。\n歌雅歌风。\n通鉴通书又史通。\n欲相酹酒。\n瓦缶田家羞出寿。\n甚欲舟何。\n愧没瑶觞玉多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10197, '减字木兰花', '沈瀛', '棋枰响止。\n胜负岂能全两喜。\n不竞南风。\n忽尔三生六劫通。\n客方对酒。\n一片捷音来自寿。\n甚快人何。\n大胜呼庐百万多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10198, '减字木兰花', '沈瀛', '酒巡未止。\n先说一些儿事喜。\n别调吹风。\n佛曲由来自普通。\n长鲸吸酒。\n面对沈香山刻寿。\n吸尽如何。\n吸了西江说甚多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10199, '减字木兰花', '沈瀛', '酒巡未止。\n听说二疏归可喜。\n随意乘风。\n拄杖深村狭巷通。\n渊明漉酒。\n更与庞公庞媪寿。\n切莫讥何。\n唤取同来作队多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10200, '减字木兰花', '沈瀛', '酒巡未止。\n更号三般杨氏喜。\n上苑春风。\n宝带灵犀点点通。\n听歌侑酒。\n富贵两全添个寿。\n人少兼何。\n彭祖人言只寿多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10201, '减字木兰花', '沈瀛', '酒巡未止。\n说著四并须著喜。\n好月兼风。\n好个情怀命又通。\n明朝醒酒。\n起看佳人妆学寿。\n定问人何。\n昨夜何人饮最多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10202, '减字木兰花', '沈瀛', '酒巡未止。\n更说五行人听喜。\n康节淳风。\n说道诸公运数通。\n乞浆得酒。\n更检戊申前定寿。\n亥子推何。\n甲子生年四百多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10203, '减字木兰花', '沈瀛', '酒巡未止。\n鼓吹六经为公喜。\n也没回风。\n只有村中鼓数通。\n长须把酒。\n自当长头杯捧寿。\n问得穷何。\n一坐靴皮笑面多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10204, '减字木兰花', '沈瀛', '酒巡未止。\n且听七言馀韵喜。\n弹到悲风。\n醒酒风吹路必通。\n休休避酒。\n末後茶仙来献寿。\n七碗休何。\n不独茶多酒亦多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10205, '减字木兰花', '沈瀛', '八巡将止。\n八节四时人贺喜。\n汉俗成风。\n薛老之言贵尚通。\n妻儿设酒。\n更得比邻相庆寿。\n虚度时何。\n只恐妻儿怪汝多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10206, '减字木兰花', '沈瀛', '九巡将止。\n留读九歌章句喜。\n尽溘埃风。\n发轫苍梧万里通。\n楚歌发酒。\n读到人生何所寿。\n试问原何。\n尔独惺然枉了多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10207, '减字木兰花', '沈瀛', '十巡今止。\n乐事要须防极喜。\n烛影摇风。\n月落参横影子通。\n粗茶淡酒。\n五十狂歌供宴寿。\n敬谢来何。\n再得寻盟後日多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10208, '减字木兰花', '沈瀛', '陋人居止。\n旬一集真终日喜。\n先自薰风。\n客目轮流次第通。\n昔贤置酒。\n十老半千年纪寿。\n知彼由何。\n真处闲中日月多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10209, '减字木兰花', '沈瀛', '鸡鸣弗止。\n弗到天明心弗喜。\n投辖成风。\n壑谷吾公宜弗通。\n齐盟歃酒。\n扬觯先听方饮寿。\n盟载言何。\n卜昼三杯不用多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10210, '减字木兰花', '沈瀛', '适然萃止。\n不待灯花先报喜。\n不速真风。\n且免毛生不为通。\n诗歌棋酒。\n真正清欢真正寿。\n事事真何。\n更得真真真更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10211, '野庵曲', '沈瀛', '野叟最昏迷。\n叹世间、光阴奔走如驰。\n逢这闲时。\n忽寻忖、一生里事都非。\n从头到尾。\n都改了、重立根基。\n枕上披衣。\n浑无寐。\n时时摩挲行气。\n才睡起。\n避户扉。\n一炷清香，烟气霏霏。\n膜拜更归依。\n冥心坐、看经念佛行持。\n消除秽恶，光洒洒、禅律威仪。\n佛力慈悲。\n愿今世。\n永没冤债相随。\n食将惭愧。\n才饭了、一枕茶香美。\n迟迟日长，觅伴相对围棋。\n安排势子。\n相望相窥。\n闭心机。\n输赢成败，却似人居世。\n跳脱去、唤方帽杖黎。\n为伴侣、小桥那边一奄儿。\n登高望远输情思。\n叹物荣物枯，节换时移。\n春到园中，见寒梅同春雪乱飞。\n冷艳冰肌。\n须臾李杏开遍，一日芳菲。\n和风骀荡，两岸细柳拈金丝。\n清明时候，景物尤韶媚。\n春事退。\n叹万红狼籍飞满堤。\n水平池。\n风到卷涟漪。\n荷花一望如霞绮。\n对好些景物，敌去炎威。\n秋景凄凄。\n长空明月正扬辉。\n蒹葭岸、浮云侧畔坐钓矾。\n正桂花香喷鼻。\n黄花满眼，风劲霜坠。\n做寒来天气。\n秋光老、草木一齐似洗。\n独修篁径，青松路，残岁方知。\n日将斜，园里缓行归。\n听流水。\n明窗净几。\n调数徽。\n到妙处、古曲幽闲韵渐稀。\n徐徐弹了融心意。\n忽然惊起。\n外时闻车履。\n故人来相对。\n瓮浮蚁。\n草草杯盘灯正辉。\n漏声迟。\n浮飞觞，言渐嘻嘻。\n轩渠一笑，高歌野奄新唱、劝些儿。\n人听村歌，一霎时、好娱戏。\n休笑颠狂，也是大奇。\n能赶气闷忧悲。\n自然沈醉。\n客都去後，睡地。\n一枕华胥惊又起。\n晓鸡啼。\n重起着衣。\n心火烧脐。\n龙行虎驰。\n依前喱喱。\n从头到尾今如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10212, '醉乡曲', '沈瀛', '说与贤瞒，这躯壳、安能久仗凭。\n幸尊中有酒浇磊块，先交神气平。\n醉乡道路无他径。\n任陶陶、现出真如性。\n没闲恼、没闲争。\n也能使情怀长似春。\n也能使飘然逸气如云。\n饶君万劫修功行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10213, '驻马听', '沈瀛', '人都道四者难并。\n也由在人心。\n烦恼欢喜元无定。\n奸峭底自能称停。\n你待前面怎那，且随任咱分。\n自家有後自未奔。\n枉劳人方寸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10214, '风入松', '沈瀛', '金榜初登。\n绮楼朱楼对娉婷。\n软红尘、有人相等。\n归来寝立功名。\n油盖拥著一书生。\n开宴处、笙歌频奏声。\n眼前光景。\n人生如意享欢荣。\n得酒娱情。\n没事汉、清闲人。\n任自由、毁誉利害不上心。\n恣闲吟。\n登山玩水且闲行。\n来主他、风华雪月盟。\n相逢道友，握手闲语百事真。\n得酒忘情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10215, '归去来兮引・归去来兮', '杨万里', '侬家贫甚诉长饥。\n幼稚满庭闱。\n正坐瓶无储粟，漫求为吏东西。\n偶然彭泽近邻圻。\n公秫滑流匙。\n葛巾劝我求为酒，黄菊怨、冷落东篱。\n五斗折腰，谁能许事，归去来兮。\n老圃半榛茨。\n山田欲蒺藜。\n念心为形役又奚悲。\n独惆怅前迷。\n不谏後方追。\n觉今来是了，觉昨来非。\n扁舟轻扬破朝霏。\n风细漫吹衣。\n试问征夫前路，晨光小，恨熹微。\n乃瞻衡宇载奔弛。\n迎候满荆扉。\n已荒三径存松菊，喜诸幼、入室相携。\n有酒盈尊，引觞自酌，庭树遣颜怡。\n容膝易安栖。\n南窗寄傲睨。\n更小园日涉趣尤奇。\n尽虽设柴门，长是闭斜晖。\n纵遐观矫首，短策扶持。\n浮云出岫岂心思。\n鸟倦亦归飞。\n翳翳流光将入，孤松抚处凄其。\n息交绝友堑山溪。\n世与我相违。\n驾言复出何求者，旷千载、今欲从谁。\n亲戚笑谈，琴书觞咏，莫遣俗人知。\n邂逅又春熙。\n农人欲载。\n告西畴有事要耘耔。\n容老子舟车，取意任委蛇。\n历崎岖窈窕，丘壑随宜。\n欣欣花木向荣滋。\n泉水始流澌。\n万物得时如许，此生休笑吾衰。\n寓形宇内几何时。\n岂问去留为。\n委心任运无多虑，顾皇皇、将欲何之。\n大化中间，乘流归尽，喜惧莫随伊。\n富贵本危机。\n云乡不可期。\n趁良辰、孤往恣游嬉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10216, '念奴娇', '杨万里', '老夫归去，有三径、足可长拖衫袖。\n一道官衔清彻骨，别有监临主守。\n主守清风，监临明月，兼管栽花柳。\n登山临水，作诗三首两首。\n休说白日升天，莫夸金印，斗大悬双肘。\n且说庐陵传盛事，三个闲人眉寿。\n拣罢军员，归农押录，致政诚斋叟。\n只愁醉杀，螺江门外私酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10217, '好事近', '杨万里', '月未到诚斋，先到万花川谷。\n不是诚斋无月，隔一林修竹。\n如今才是十三夜，月色已如玉。\n未是秋光奇绝，看十五十六。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10218, '昭君怨', '杨万里', '偶听松梢扑鹿。\n知是沙鸥来宿。\n稚子莫喧哗。\n恐惊他。\n俄顷忽然飞去。\n飞去不知何处。\n我已乞归休。\n报沙鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10219, '昭君怨', '杨万里', '午梦扁舟花底。\n香满西湖烟水。\n急雨打篷声。\n梦初惊。\n却是池荷跳雨。\n散了真珠还聚。\n聚作水银窝。\n泻清波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10220, '武陵春', '杨万里', '长铗归乎逾十暑，不著冠。\n道是今年胜去年。\n特地减清欢。\n旧赐龙团新作祟，频啜得中寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10221, '水调歌头', '杨万里', '玉树映阶秀，玉节逐年新。\n年年九月，好为阿母作生辰。\n涧底蒲芽九节，海底银涛万顷，酿作一杯春。\n泛以东篱菊，寿以漆园椿。\n对西风，吹鬓雪，炷香云。\n郎君入奏，又迎珠入修门。\n看即金花紫诰，并举莆常两国，册命太夫人。\n三点台星上，一点老人星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10222, '忆秦娥', '杨万里', '新春早。\n春前十日春归了。\n春归了。\n落梅如雪，野桃红小。\n老夫不管春催老。\n只图烂醉花前倒。\n花前倒。\n儿扶归去，醒来窗晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10223, '眼儿媚', '某教授', '鬓边一点似飞鸦。\n莫把翠钿遮。\n三年两载，千百就，今日天涯。\n杨花又逐东风去，随分落谁家。\n若还忘得，除非睡起，不照菱花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10224, '水调歌头', '陈居仁', '重过钓台路，风物故依然。\n羊裘轩上，俯临清面孱颜。\n仰见先生风节，更有两公名德，冰雪照人寒。\n龙野方驰逐，鸿翼自孤骞。\n酹壶觞，追往昔，笑华颠。\n别来三纪，推排曾戴侍臣冠。\n惭愧君恩难答，聊复守符重绾，敢叹客途艰。\n少报期年政，行泛五湖船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10225, '满庭芳', '李洪', '香满千岩，芳传丛桂，小山曾咏幽菲。\n仙姿冷淡，不奈此香奇。\n翠葆层层障日，深爱惜、早被风吹。\n秋英嫩，夜来露，月底半离披。\n谁知。\n清品贵，带装金粟，韵透文犀。\n与降真为侣，罗袖相宜。\n宝鸭休薰百濯，清芬在、常惹人衣。\n娥约，广寒宫殿，留折最高枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10226, '满江红', '李洪', '梅雨成霖，倦永昼、暑行岩曲。\n爱云梢翠樾，枕溪蓬屋。\n轻木凌波冲卷雪，飞泉奔壑呜哀玉。\n羡渔翁、终岁老烟波，披蓑绿。\n嗟客宦，荒松菊。\n颓壮志，青编竹。\n更长年谙尽，是非荣辱。\n钟鼎无心时节异，山林有味簟瓢足。\n感故人、於此赋归欤，思之熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10227, '南乡子', '李洪', '挂席泛安流。\n细雨斜风到渡头。\n万叠云鬟真似画，云州。\n自古诗人几个游。\n旌旆去悠悠。\n别驾无功愧食浮。\n却忆五湖烟浪里，扁舟。\n第四桥南云水秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10228, '鹧鸪天', '李洪', '十月南闽未有霜。\n蕉林蔗圃郁相望。\n压枝橄榄浑如画，透甲香橙半弄黄。\n斟绿醑，泛沧浪。\n白沙翠竹近温汤。\n分明水墨山阴道，只欠冰溪雪月光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10229, '西江月', '李洪', '渺渺长汀远壑，萧萧雨叶风枝。\n几回临水送将归。\n客里暗添憔悴。\n门枕数峰滴翠，舟横几度涟漪。\n绿秧深处鹭于飞。\n愈觉田园有味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10230, '菩萨蛮', '李洪', '寒山横抹修眉绿。\n楼前溪瀑锵鸣玉。\n车马各西东。\n行人如转蓬。\n阑干成独倚。\n海阔天无际。\n云淡隔壶山。\n鸿飞杳霭间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10231, '浣溪沙', '李洪', '夭矫翔鸾溪上峰。\n飘萧雪霰打船篷。\n天花凌乱水晶宫。\n飞透纸窗斜取势，吹回溪面舞因风。\n身游水墨画图中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10232, '浣溪沙', '李洪', '碧涧苍崖玉四围。\n东君翦水散明玑。\n半开桃杏不胜威。\n疑是群仙游阆苑，歌云舞蝶斗高飞。\n珠幢玉节送人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10233, '浣溪沙', '李洪', '扫地烧香绝点尘。\n绿阶绿草又残春。\n略无闲事挠天真。\n时落燕泥沾几席，乱粘飞絮上衣巾。\n西湖回柁少年人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10234, '念奴娇', '李洪', '丽谯吹角，渐疏星明澹，帘筛残月。\n袅袅霜飙欺翠袖，飞下一庭香雪。\n半面妆新，回风舞困，此况真奇绝。\n桄榔林里，苏仙偏感华发。\n休怨时暂飘零，玉堂清梦，不惹闲蜂蝶。\n好似王家从竹畔，乘兴山阴时节。\n剪水无情，阆风归去，忍使芳心歇。\n和羹有待，恁时身到天阕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10235, '卜算子', '李洪', '南国小春时，常是寒威浅。\n玉缀香苞已有梅，疏影无人见。\n愁忆故园芳，梦断扬州远。\n不御铅华自出尘，赛过徐妃面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10236, '鹊桥仙', '李漳', '迢迢郎意，盈盈妾恨，今夕鹊桥欲度。\n世间儿女一何痴，斗乞巧、纷纷无数。\n遥知此际，有人孤坐，心切天街云路。\n好因缘是恶因缘，梦魂远、阳台雨暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10237, '桃源忆故人', '李漳', '小楼帘卷栏干外。\n花下朱门半启。\n中有倾城佳丽。\n一笑西风里。\n盈盈临水情难致。\n尽日相看如醉。\n乾鹊不知人意。\n只管声声喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10238, '满江红', '李漳', '雨歇前林，薰风度、琴声清淑。\n绮窗迥、张眉初扫，弄弦鸣玉。\n三叠瑶池仙侣宴，九江鹤唳清江曲。\n政伯鸾、此日梦维熊，祥烟馥。\n金徽外，音时续。\n雕筵上，听难足。\n且相将一醉，满倾。\n共祝遐龄何所似，水流不尽高山矗。\n算未应、归去抱琴书，云间宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10239, '鹧鸪天', '李漳', '淑德由来孟母名。\n方瞳鹤发莹精神。\n天教遐算灵椿比，亲见贤郎擢桂荣。\n逢诞日，庆孙曾。\n金花纶诰又重新。\n愿君学得司空母，管取年高寿太平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10240, '生查子', '李漳', '家承阀阅高，人擅闺房秀。\n嫁得伯鸾夫，直是齐眉偶。\n榴花著子时，萱草宜男候。\n一笑捧觥船，共祝人常寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10241, '南歌子', '李漳', '小子何时见，高秋此日生。\n阶兰岩桂正欣荣。\n家比杜陵犹有、彩衣轻。\n应诏须三载，传家有一经。\n齐禽刷羽早蜚鸣。\n莫效老夫头白、好归耕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10242, '水调歌头', '李泳', '危楼云雨上，其下水扶天。\n群山四合，飞动寒翠落檐前。\n尽是秋清栏槛，一笑波翻涛怒，雪阵卷苍烟。\n炎暑去无迹，清驶久翩翩。\n夜将阑，人欲静，月初圆。\n素娥弄影，光射空际绿婵娟。\n不用濯缨垂钓，唤取龙宫仙驾，耕此万琼田。\n横笛望中起，吾意已超然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10243, '贺新郎', '李泳', '门掩长安道。\n卷重帘、垂杨散暑，嫩凉生早。\n午梦惊回庭阴翠，蝶舞莺吟未了。\n政露冷、芙蓉池沼。\n金雁尘昏么弦断，理馀音、尚想腰支袅。\n欢渐远，思还绕。\n临皋望极苍江渺。\n晚潮平、湘烟万顷，断虹残照。\n彩舫凌波分飞後，别浦菱花自老。\n问锦鲤、何时重到。\n楼迥层城看不见，对潇潇、暮雨怜芳草。\n幽恨阔、楚天杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10244, '定风波', '李泳', '点点行人趁落晖。\n摇摇烟艇出渔扉。\n一路水香流不断。\n零乱。\n春潮绿浸野蔷薇。\n南去北来愁几许，登临怀古欲沾衣。\n试问越王歌舞地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10245, '满庭芳', '李', '麦秀连云，桑枝重绿，史君佳政流传。\n凤衔丹诏，来自九重天。\n千里欢腾祖帐，棠阴外、多少攀辕。\n津亭路，如五鼓，难驻邓侯船。\n光华，家世事，门中列戟，圯上遗编。\n况建炎勋业，图画凌烟。\n此去朝端济美，看平步、两两台躔。\n须知道，中兴盛治，主圣赖臣贤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10246, '西江月', '李', '可是江梅开晚，从教蜡雪来迟。\n此花清绝胜南枝。\n搀过春风第一。\n蘸蜡女工斗巧，涂黄汉额偏宜。\n□腮相倚并开时。\n认取东君深意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10247, '踏莎行', '李', '红药香残，绿筠粉嫩。\n春归何处寻春信。\n绣鞍初上马啼轻，举头便觉长安近。\n别酒无情，啼妆有恨。\n山城向晚斜阳褪。\n清江极目带寒烟，锦鳞去後凭谁问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10248, '满庭芳', '李', '油幕新开，旄前导，暂归梓里舂容。\n致身槐府，功在鼎中。\n慨想东山故侣，烟霞外，久阔仙踪。\n今何幸，相逢吐握，谈笑一尊同。\n德星，占瑞处，旌髦五马，衮绣三公。\n对渭川遗老，绛县仙翁。\n厚意杯传绀玉，那堪更，篚实囊红。\n拼沈醉，今宵盛事，复见古人风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10249, '千秋岁', '李', '峰凝瑞，鄞水浮佳气。\n晴景转，花光媚。\n碧幢森大纛，红旆纷千骑。\n相遇处，满城鹤发群仙萃。\n绮席张高会。\n鼍鼓笙箫沸。\n金兽袅，檀烟翠。\n玉山环回座，休惜今朝醉。\n觞再举，清歌共引千秋岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10250, '浣溪沙', '朱熹', '压架年来雪作堆。\n珍丛也是近移栽。\n肯令容易放春回。\n却恐阴晴无定度，从教红白一时开。\n多情蜂蝶早飞来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10251, '菩萨蛮', '朱熹', '晚红飞尽春寒浅。\n浅寒春尽飞红晚。\n尊酒绿阴繁。\n繁阴绿酒尊。\n老仙诗句好。\n好句诗仙老。\n长恨送年芳。\n芳年送恨长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10252, '菩萨蛮', '朱熹', '暮江寒碧萦长路。\n路长萦碧寒江暮。\n花坞夕阳斜。\n斜阳夕坞花。\n客愁无胜集。\n集胜无愁客。\n醒似醉多情。\n情多醉似醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10253, '好事近', '朱熹', '春色欲来时，先散满天风雪。\n坐使七闽松竹，变珠幢玉节。\n中原佳气郁葱葱，河山壮宫阕。\n丞相功成千载，映黄流清彻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10254, '西江月', '朱熹', '睡处林风瑟瑟，觉来山月团团。\n身心无累久轻安。\n况有清池凉馆。\n句稳翻嫌白俗，情高却笑郊寒。\n兰膏元自少陵残。\n好处金章不换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10255, '西江月', '朱熹', '堂下水浮新绿，门前树长交枝。\n晚凉快写一篇诗。\n不说人间忧喜。\n身老心闲益壮，形癯道胜还肥。\n软轮加璧未应迟。\n莫道前非今是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10256, '鹧鸪天', '朱熹', '暮雨朝云不自怜。\n放教春涨绿浮天。\n祗令画阁临无地，宿昔新诗满系船。\n青鸟外，白鸥前。\n几生香火旧因缘。\n酒阑山月移雕槛，歌罢江风拂玳筵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10257, '鹧鸪天', '朱熹', '已分江湖寄此生。\n长蓑短笠任阴晴。\n鸣桡细雨沧洲远，系舸斜阳画阁明。\n奇绝处，未忘情。\n几时还得去寻盟。\n江妃定许捐双佩，渔父何劳笑独醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10258, '鹧鸪天', '朱熹', '脱却儒冠著羽衣。\n青山绿水浩然归。\n看成鼎内真龙虎，管甚人间闲与非。\n生羽翼，上烟霏。\n回头祗见冢累累。\n未寻跨凤吹箫侣，且伴孤云独鹤飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10259, '南乡子', '朱熹', '落日照楼船。\n稳过澄江一片天。\n珍重使君留客意，依然。\n风月从今别一川。\n离绪悄危弦。\n永夜清霜透幕毡。\n明日回头江树远，怀贤。\n目断晴空雁字连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10260, '满江红', '朱熹', '秀野诗翁，念故山、十年乖隔。\n聊命驾、朱门旧隐，绿槐新陌。\n好雨初晴仍半暖，金玉开瑶席。\n更流传、丽藻借江天，留春色。\n过里社、将儿侄。\n谈往事，悲陈迹。\n喜尊前现在，镜中如昔。\n两鬓全期烟树绿，方瞳好映寒潭碧。\n但一年、一度一归来，欢何极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10261, '水调歌头', '朱熹', '富贵有馀乐，贫贱不堪忧。\n谁知天路幽险，倚伏互相酬。\n请看东门黄犬，更听华亭清唳，千古恨难收。\n何似鸱夷子，散发弄扁舟。\n鸱夷子，成霸业，有馀谋。\n致身千乘卿相，归把钓渔钩。\n春画五湖烟浪，秋夜一天云月，此外尽悠悠。\n永弃人间事，吾道付沧洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10262, '水调歌头', '朱熹', '长记与君别，丹凤九重城。\n归来故里，愁思怅望渺难平。\n今夕不知何夕，得共寒潭烟艇，一笑俯空明。\n有酒径须醉，无事莫关情。\n寻梅去，疏竹外，一枝横。\n与君吟弄风月，端不负平生。\n何处车尘不到，有个江天如许，争肯换浮名。\n只恐买山隐，却要炼丹成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10263, '水调歌头', '朱熹', '江水浸云影，鸿雁欲南飞。\n携壶结客，何处空翠渺烟霏。\n尘世难逢一笑，况有紫萸黄菊，堪插满头归。\n风景今朝是，身世昔人非。\n酬佳节，须酩酊，莫相违。\n人生如寄，何事辛苦怨斜晖。\n无尽今来古往，多少春花秋月，那更有危机。\n与问牛山客，何必独沾衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10264, '念奴娇', '朱熹', '临风一笑，问群芳谁是，真香纯白。\n独立无朋，算只有、姑射山头仙客。\n绝艳谁怜，真心自保，邈与尘缘隔。\n天然殊胜，不关风露冰雪。\n应笑俗李粗桃，无言翻引得，狂蜂轻蝶。\n争似黄昏闲弄影，清浅一溪霜月。\n画角吹残，瑶台梦断，直下成休歇。\n绿阴青子，莫教容易波折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10265, '水调歌头', '朱熹', '雪月两相映，水石互悲鸣。\n不知岩上枯木，今夜若为情。\n应见尘中胶扰。\n便道山间空旷，与麽了平生。\n与麽平生了，□水不流行。\n起披衣，瞻碧汉，露华清。\n寥寥千载，此事本分明。\n若向乾坤识易，便信行藏无间，处处总圆成。\n记取渊冰语，莫错定盘星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10266, '忆秦娥', '朱熹', '云垂幕。\n阴风惨淡天花落。\n天花落。\n千林琼玖，一空鸾鹤。\n征车渺渺穿华薄。\n路迷迷路增离索。\n增离索。\n剡溪山水，碧湘楼阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10267, '忆秦娥', '朱熹', '梅花发。\n寒梢挂著瑶台月。\n瑶台月。\n和羹心事，履霜时节。\n野桥流水声呜咽。\n行人立马空愁绝。\n空愁绝。\n为谁凝伫，为谁攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10268, '水调歌头', '朱熹', '不见严夫子，寂莫富春山。\n空馀千丈危石，高插暮云端。\n想象羊裘披了，一笑两忘身世，来把钓鱼竿。\n不似林间翮，飞倦始知还。\n中兴主，功业就，鬓毛斑。\n驰驱一世豪杰，相与济时艰。\n独委狂奴心事，不羡痴儿鼎足，放去任疏顽。\n爽气动心斗，千古照林峦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10269, '江神子・江城子', '黄铢', '秋风袅袅夕阳红。\n晚烟浓。\n暮云重。\n万叠青山，山外叫孤鸿。\n独上高楼三百尺，凭玉，睇层空。\n人间日月去匆匆。\n碧梧桐。\n又西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10270, '菩萨蛮', '黄铢', '海山翠叠青螺浅。\n暮云散尽天容远。\n匹马度江皋。\n北风生怒号。\n解鞍栖倦翮。\n皓月空庭白。\n何处小阑干。\n玉箫吹夜寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10271, '渔家傲', '黄铢', '永日离忧千万绪。\n雪舟远泛清漳浦。\n珍重故人寒夜语。\n挥玉麈。\n沈沈画阁凝香雾。\n风砌落花留不住。\n红蜂翠蝶闲飞舞。\n明日柳营江上路。\n云起处。\n苍山万叠人归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10272, '卜算子', '高宣教', '去又如何去。\n住又如何住。\n但得山花插满头。\n休问奴归处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10273, '卜算子', '严蕊', '不是爱风尘，似被前身误。\n花落花开自有时，总是东君主。\n去也终须去。\n住也如何住。\n若得山花插满头，莫问奴归处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10274, '如梦令', '严蕊', '道是梨花不是。\n道是杏花不是。\n白白与红红，别是东风情味。\n曾记。\n曾记。\n人在武陵微醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10275, '鹊桥仙', '严蕊', '碧梧初出，桂花才吐，池上水花微谢。\n穿针人在合欢楼，正月露、玉盘高泻。\n蛛忙鹊懒，耕慵织倦，空做古今佳话。\n人间刚道隔年期，指天上、方才隔夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10276, '满江红', '晦庵', '胶扰劳生，待足後、何时是足。\n据见定、随家丰俭，便堪龟缩。\n得意浓时休进步，须知世事多翻覆。\n漫教人、白了少年头，徒碌碌。\n谁不爱，黄金屋。\n谁不羡，千锺禄。\n奈五行不是，这般题目。\n枉费心神空计较，儿孙自有儿孙福。\n也不须、采药访神仙，惟寡欲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10277, '清平乐', '徐逸', '风韶雨秀。\n春已平分後。\n陡顿故人疏把酒。\n闲恁画阑搔首。\n争须携手踏青。\n人生几度清明。\n待得燕慵莺懒，杨花点点浮萍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10278, '五福降中天', '沈端节', '月胧烟澹霜蹊滑，孤宿暮林荒驿。\n绕树微吟，巡檐索笑，自分平生相得。\n冰池半释。\n正节物惊心，泪痕沾臆。\n流水溅溅，照影古寺满春色。\n沈叹今年未识。\n暗香微动处，人□初寂。\n酷爱芳姿，最怜幽韵，来款禅房深密。\n他时恨□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10279, '卜算子', '沈端节', '愁极强登临，毕竟愁难避。\n千里江山黯淡中，总是悲秋意。\n谁插菊花枝，谁带茱萸佩。\n独倚阑干醉不成，日暮西风起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10280, '卜算子', '沈端节', '冷蕊伴疏枝，一笑何时共。\n江北江南两处愁，忍看花影动。\n旅泊怕逢春，卜睡都无梦。\n岁暮何郎未得归，手拈频呵冻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10281, '卜算子', '沈端节', '踏雪探孤芳，只有诗人共。\n守定南枝待得开，不觉冰轮动。\n却月与凌风，谩说扬州梦。\n想见雕阑曲沼边，残雪和烟冻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10282, '卜算子', '沈端节', '客里见梅花，独赏无人共。\n风度精神总是伊，又是归心动。\n把酒破忧端，熏被寻佳梦。\n梦觉香残一味寒，有泪都成冻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10283, '卜算子', '沈端节', '烘手熨笙簧，呵冻匀酥面。\n闲向梅花树下行，拜月遥相见。\n何处托春心，乐府流深怨。\n却拈寒窗傍绮疏，恨极东风远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10284, '忆秦娥', '沈端节', '凭阑独。\n南山影蘸杯心绿。\n杯心绿。\n悠然忽见，卧披横轴。\n西风暗度钗梁玉。\n手香记得人簪菊。\n人簪菊。\n无穷幽韵，细看不足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10285, '惜分飞', '沈端节', '喜入眉心黄点莹。\n珠佩玲珑透影。\n风露萧萧冷。\n梦回月窟香成阵。\n秋後情怀君莫问。\n拼了因他瘦损。\n不似寻常韵。\n细看没处安排闷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10286, '南歌子', '沈端节', '远树昏鸦闹，衰芦睡鸭双。\n雪篷烟棹炯寒光。\n疑是风林纤月、到船窗。\n时序惊心破，江山引梦长。\n思量也待不思量。\n泪染罗巾犹带、旧时香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10287, '鹊桥仙', '沈端节', '怀人意思，悲秋情绪，长是文园病後。\n蛛丝轻袅玉钗风，想花貌、参差依旧。\n无穷往事，一襟新恨，老泪淋浪卮酒。\n天涯相对话平生，怅南北、还如箕斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10288, '醉落魄・一斛珠', '沈端节', '红娇翠弱。\n春寒睡起慵匀掠。\n些儿心事谁能学。\n深院无人，时有燕穿幕。\n漏声滴尽莲花萼。\n静看月转西阑角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10289, '太常引', '沈端节', '三三五五短长亭。\n都只解、送人行。\n天远树冥冥。\n怅好梦、才成又惊。\n夜堂歌罢，小楼钟断，归路已闻莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10290, '谒金门', '沈端节', '真个忆。\n花下雨声初息。\n猛记乌衣曾旧识。\n丁宁教去觅。\n春半峭寒犹力。\n泪滴两襟成迹。\n独倚危阑清昼寂。\n草长流翠碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10291, '谒金门', '沈端节', '春欲去。\n人瘦不胜金缕。\n门巷阴阴飞絮舞。\n断肠双燕语。\n孤坐晚窗闲处。\n月到花心亭午。\n寒色著人无意绪。\n竹鸣风似雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10292, '谒金门', '沈端节', '寻胜去。\n湖色净涵疏树。\n乃一声何处起。\n风铃相应语。\n目断遥林修渚。\n画出江南烟雨。\n山水照人人楚楚。\n锦肠生秀句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10293, '菩萨蛮', '沈端节', '春山千里供行色。\n客愁浓似春山碧。\n幸自不思归。\n子规心上啼。\n芳意随人老。\n绿尽江南草。\n窈窕可人花。\n路长何处家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10294, '菩萨蛮', '沈端节', '愁人道酒能消解。\n元来酒是愁人害。\n对酒越思量。\n醉来还断肠。\n酒醒初梦破。\n梦破愁无那。\n乾净不如休。\n休时只恁愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10295, '浣溪沙', '沈端节', '灯夜香甘动绮筵。\n明珠颗颗泛瓯圆。\n佳人巧意底难传。\n喜见翻溪流细滑，却思信手弄轻纤。\n不知辛苦为谁甜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10296, '行香子', '沈端节', '烟淡回塘。\n月浸疏篁。\n一枝□、压尽群芳。\n修然风度，玉质金章。\n有许多情，许多韵，许多香。\n中酒情怀，琢句心肠。\n倚屏山、子细端相。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10297, '喜迁莺', '沈端节', '暮云千里。\n正小雨乍晴，霜风初起。\n芦荻江边，月昏人静，独自小船儿里。\n消魂几声新雁，合造愁人天气。\n怎奈何，少年时光景，一成抛弃。\n回首空肠断，尺素未传，应是无双鲤。\n闷酒孤斟，半醺还醒，乾净不如不醉。\n有得恁多烦恼，直是没些如意。\n受尽也，待今回厮见，从头说似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10298, '菩萨蛮', '沈端节', '楚山千叠伤心碧。\n伤心只有遥相忆。\n解佩揖巫云。\n愁生洛浦春。\n香波凝宿雾。\n梦断消魂处。\n空听水泠泠。\n如闻宝瑟声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10299, '朝中措', '沈端节', '天遥野阔雁书空。\n山远暮云中。\n目断江南烟雨，□□枕春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10300, '念奴娇', '沈端节', '灯宵渐近，更兵尘初息，韶华偏早。\n太守风流张宴乐，不管江城寒峭。\n发底蜂儿，钗头梅蕊，一一夸新巧。\n笙歌鼎沸，万人争看标表。\n应记革履雍容，天香满袖，侍宴游三岛。\n圣主中兴思用旧，尊礼先朝元老。\n烛赐金莲，柑传罗帕，行即趋严道。\n深杯休诉，任教银漏催晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10301, '念奴娇', '沈端节', '重阳恁好，正秋清天色，水容如泻。\n野阔风高香雾满，采菊无人同把。\n堪笑渊明，蓬头曳杖，吟赏东篱下。\n孤风远韵，至今犹作佳话。\n争似太守才贤，慈祥恺悌，赋政多闲暇。\n千里江山供胜践，尊俎延登儒雅。\n只恐相将，吹花春宴，不许斯民借。\n花嘲便坐，尚怀方外司马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10302, '青玉案', '沈端节', '史君标韵如徐庾。\n更名节、高千古。\n卧治姑溪才小驻。\n闲云无定，阳春有脚，又作南昌去。\n兴来亭上清歌度。\n尽能唱、公诗句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10303, '洞仙歌', '沈端节', '雪肌花貌，见了千千万。\n眼去眉来几曾管。\n被今回打住，没□施程，□捺地，却悔看承较晚。\n琴心传密意，唯有相知，失笑他满恁撩乱。\n抖下俏和娇，掩翠凌红，真个是、从前可见。\n据入马牢笼怎乾休，但拈取真诚，试教人看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10304, '洞仙歌', '沈端节', '夜来惊怪，冷逼流苏帐。\n梦破初闻打窗响。\n向晓开帘，凌乱千里寒光，清兴发，鹤氅谁同纵赏。\n江南春意动，梅竹潜通，醉帽冲风自来往。\n慨念故人疏，便理扁舟，须信道、吾曹清旷。\n待石鼎煎茶洗馀醺，更依旧归来，浅斟低唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10305, '洞仙歌', '沈端节', '重阳近也，渐秋光凄劲。\n宿雨初收好风景。\n正干戈耆定，禾黍丰登，人意乐，歌舞贤侯美政。\n醉翁游历处，胜概依然，木落淮南见山影。\n有客共登临，醉里疏狂，乌帽、从嘲雪鬓。\n但目送孤鸿傍危栏，笑问道，黄花似谁风韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10306, '虞美人', '沈端节', '去年寒食初相见。\n花上双飞燕。\n今年寒食又花开。\n垂下重帘不许、燕归来。\n隔帘听燕呢喃语。\n似说相思苦。\n东君都不管闲愁。\n一任落花飞絮、两悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10307, '虞美人', '沈端节', '卧红堆碧纷无数。\n春事知何许。\n班班小雨犁花。\n又是清明时候、不归家。\n伤春减尽东阳带。\n人道多情杀。\n青春留下许多愁。\n分付与君今夜、一齐休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10308, '虞美人', '沈端节', '暮云衰草连天远。\n不记离人怨。\n可怜无处不关情。\n梦断孤鸿哀怨、两三声。\n恨眉醉眼何时见。\n夜夜相思遍。\n梧桐叶落候蛩秋。\n唯有一江烟雨、替人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10309, '探春令', '沈端节', '旧家元夜，追随风月，连宵欢宴。\n被那懑、引得滴流地，一似蛾儿转。\n而今百事心情懒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10310, '如梦令', '沈端节', '雨後轻寒天气。\n玉酒中人小醉。\n乍报一番秋，晚簟清凉如水。\n睡。\n睡。\n窗在芭蕉叶底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10311, '薄幸', '沈端节', '桂轮香满。\n送寒色、轻风剪剪。\n又还是、幽窗人静，梅影参差初转。\n念少年孤负芳音，多时不见文君面。\n漫快泻琼舟，浓熏宝鸭，终是心情差懒。\n谩就枕，浑无寐，□听彻、天边飞雁。\n闲愁消万缕，如何消遣。\n绣衾□忆鸳鸯暖。\n细思量、遍倚屏山，挑尽琴心，谁识相思怨。\n休文瘦损，陡觉频移带眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10312, '江城子', '沈端节', '秋声昨夜入梧桐。\n雨。\n洒窗风。\n短杵疏砧，将恨到帘栊。\n归梦未成心已远，云不断，水无穷。\n有人应念水之东。\n鬓如蓬。\n理妆慵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10313, '满庭芳', '沈端节', '雾薄阴轻，林深烟暖，海棠特地开迟。\n光风绝艳，独自殿芳时。\n须信东君注意，花神会、别有看持。\n群英外，嫣然一笑，富贵出添姿。\n日长，春睡足，粉香扑扑，酒晕微微。\n明皇当日，称许最相宜。\n妃子扶来半醉，宫妆淡、不扫蛾眉，偏怜处，流莺惊绕，金弹拂丛飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10314, '采桑子', '沈端节', '昔年曾记寻芳处，短帽冲寒。\n竹外江干。\n玉面皮儿月下观。\n而今老大风流减，百事心阑。\n谷底林间。\n坐对横枝祗鼻酸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10315, '西江月', '沈端节', '一枕香消睡恼，十年漂泊江湖。\n空馀清梦绕康庐。\n记得林间风度。\n锦绣谷中旧客，襟怀未肯全疏。\n从今不要别人扶。\n醉拥紫云归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10316, '喜迁莺', '沈端节', '冰池轻皱。\n喜寒律乍回，微阳初透。\n岁晚云黄，日晴烟暖，昼刻暗添宫漏。\n山色岸容都变，春意欲传官柳。\n最好处，正酥融粉薄，一枝梅瘦。\n行乐，春渐近，景胜欢长，幼眇丝簧奏。\n鸣玉行，退朝花院，犹有御香沾袖。\n试问西邻虽富，何似东皋依旧。\n趁未老，便优游林壑，围棋把酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10317, '西江月', '沈端节', '幸自心肠稳审，怎禁眼脑迷奚。\n招愁买恨带人疑。\n一味笑吟吟地。\n闲趁莺来日下，却随燕入乌衣。\n阿蛮风味有谁知。\n认得乐天词意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10318, '念奴娇', '沈端节', '嫩凉清晓，淡秋容、横写鲛绡十幅。\n山水光中参意味，不管人间荣辱。\n藜杖棕鞋，纶巾鹤氅，宾主俱遗俗。\n倚阑舒啸，一樽花下相属。\n云际有药千年，琼瑶争秀发，龙蛇新。\n富贵功名元自有，且乐无穷真福。\n莲社风流，醉乡跌宕，时奏长生曲。\n月娥同听，好风徐韵松竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10319, '念奴娇', '沈端节', '洛妃汉女，护春寒、不惜鲛绡重叠。\n拾翠江边烟澹澹，交影参差胧月。\n秦虢相将，英娥接武，同宴瑶池雪。\n层冰连璧，个中谁敢优劣。\n著意晕纷饶酥，韵多香剩，都与群花别。\n娟秀敷腴索笑处，玉脸微生娇靥。\n羞损南枝，映翻绿萼，不数黄千叶。\n形容不尽，细看一倍清绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10320, '念奴娇', '沈端节', '湖山照影，正日长娇困，不烦匀扫。\n絮满长洲春澹沲，开遍吴宫花草。\n嫩绿葱葱，轻红簌簌，渐觉枝头少。\n馀芳难并，破愁惟有馨。\n应是留得东君，海棠方待折，玉环娇小。\n雾薄阴轻初睡足，宝幄画屏香袅。\n醉态天真，半羞微敛，未肯都开了。\n嫣然一笑，此时风度尤好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10321, '念奴娇', '沈端节', '寻幽览胜，凭危栏、极目风烟平楚。\n自笑飘零惊岁晚，欲挂衣冠神武。\n芳甸时巡，醉乡日化，庭实名花旅。\n阆风蓬顶，自来不见烽戍。\n宴罢玉宇琼楼，醉中都忘却，瑶池归路。\n俯瞰尘寰千万落，渺渺峰端栖雾。\n群玉图书，广寒宫殿，一一经行处。\n相羊物外，旷怀高视千古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10322, '感皇恩', '沈端节', '和气霭微宵，黄云飘转。\n东阁观梅负诗眼。\n满斟绿酒，唱个曲儿亲劝。\n愿从今日去，长相见。\n宝幄欢浓，玉炉香软。\n彼此宜冬镇长键。\n绣床儿畔，渐渐日迟风暖。\n告他事事底，饶一线。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10323, '六州歌头', '张孝祥', '长怀望断，关塞莽然平。\n征尘暗，霜风劲，悄边声。\n黯销凝。\n追想当年事，殆天数，非人力，洙泗上，弦歌地，亦膻腥。\n隔水毡乡，落日牛羊下，区脱纵横。\n看名王宵猎，骑火一川明。\n笳鼓悲鸣。\n遣人惊。\n念腰间箭，匣中剑，空埃蠹，竟何成。\n时易失，心徒壮，岁将零。\n渺神京。\n干羽方怀远，静烽燧，且休兵。\n冠盖使，纷驰骛，若为情。\n闻道中原遗老，常南望，羽葆霓旌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10324, '水调歌头', '张孝祥', '隆中三顾客，圯上一编书。\n英雄当日感会，馀事了寰区。\n千载神交二子，一笑眇然兹世，却愿驾柴车。\n长忆淮南岸，耕钓混樵渔。\n忽扁舟，凌骇浪，到三吴。\n纶巾羽扇容与，争看列仙儒。\n不为莼鲈笠泽，便卦衣冠神武，此兴渺江湖。\n举酒对明月，高曳九霞裾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10325, '水调歌头', '张孝祥', '猩鬼啸篁竹，玉帐夜分弓。\n少年荆楚剑客，突骑锦红。\n千里风飞雷厉，四校星流慧扫，萧斧锉春葱。\n谈笑青油幕，日奏捷书同。\n诗书帅，黄阁老，黑头公。\n家传鸿宝秘略，小试不言功。\n闻道玺书频下，看即沙堤归去，帷幄且从容。\n君王自神武，一举朔庭空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10326, '水调歌头', '张孝祥', '濯足夜滩急，发北风凉。\n吴山楚泽行遍，只欠到潇湘。\n买得扁舟归去，此事天公付我，六月下沧浪。\n蝉脱尘埃外，蝶梦水云乡。\n制荷衣，纫兰佩，把琼芳。\n湘妃起舞一笑，抚瑟奏清商。\n唤起九歌忠愤，拂拭三闾文字，还与日争光。\n莫遣儿辈觉，此乐未渠央。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10327, '水调歌头', '张孝祥', '江山自雄丽，风露与高寒。\n寄声月姊，借我玉鉴此中看。\n幽壑鱼龙悲啸，倒影星辰摇动，海气夜漫漫。\n涌起白银阕，危驻紫金山。\n表独立，飞霞佩，切云冠。\n漱水濯雪，眇视万里一毫端。\n回首三山何处，闻道群仙笑我，要我欲俱还。\n挥手从此去，翳风更骖鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10328, '水调歌头', '张孝祥', '淮楚襟带地，云梦泽南州。\n沧江翠壁佳处，突兀起红楼。\n凭仗使君胸次，与问老仙何在，长啸俯清秋。\n试遣吹箫看，骑鹤恐来游。\n欲乘风，凌万顷，泛扁舟。\n山高月小，霜露既降，凛凛不能留。\n一吊周郎羽扇，尚想曹公横槊，兴废两悠悠。\n此意无尽藏，分付水东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10329, '水调歌头', '张孝祥', '青嶂度云气，幽壑舞回风。\n山神助我奇观，唤起碧宵龙。\n电掣金蛇千丈，雷震灵鼍万垒，汹汹欲崩空。\n尽泻银潢水，倾入宝莲宫。\n坐中客，凌积翠，看奔洪。\n人间应失匕箸，此地独从容。\n洗了从来尘垢，润及无边焦槁，造物不言功。\n天宇忽开霁，日在五云东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10330, '水调歌头', '张孝祥', '五岭皆炎热，宜人独桂林。\n江南驿使未到，梅蕊破春心。\n繁会九衢三市，缥缈层楼杰观，雪片一冬深。\n自是清凉国，莫遣瘴烟侵。\n江山好，青罗带，碧玉簪。\n平沙细浪欲尽，陡起忽千寻。\n家种黄柑丹荔，户拾明珠翠羽，箫鼓夜沈沈。\n莫问骖鸾事，有酒且频斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10331, '水调歌头', '张孝祥', '今夕复何夕，此地过中秋。\n赏心亭上唤客，追忆去年游。\n千里江山如画，万井笙歌不夜，扶路看遨头。\n玉界拥银阕，珠箔卷琼钩。\n驭风去，忽吹到，岭边州。\n去年明月依旧，还照我登楼。\n楼下水明沙静，楼外参横斗转，搔首思悠悠。\n老子兴不浅，聊复此淹留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10332, '水调歌头', '张孝祥', '雪洗虏尘静，风约楚云留。\n何人为写悲壮，吹角古城楼。\n湖海平生豪气，关塞如今风景，剪烛看吴钩。\n胜喜然犀处，骇浪与天浮。\n忆当年，周与谢，富春秋。\n小乔初嫁，香囊未解，勋业故优游。\n赤壁矶头落照，肥水桥边衰草，渺渺唤人愁。\n我欲乘风去，击楫誓中流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10333, '水调歌头', '张孝祥', '云海漾空阔，风露凛高寒。\n仙翁鹤驾，羽节缥缈下天端。\n指点虚无征路，时见双凫飞舞，挥斥隘尘寰。\n吹笛向何处，海上有三山。\n彩衣新，鱼服丽，更朱颜。\n蟠桃未熟，千岁容与且人间。\n早晚金泥封诏，归侍玉皇香案，踵武列仙班。\n玉骨自难老，未用九霞丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10334, '水调歌头', '张孝祥', '紫橐论思旧，碧落拜除新。\n内家敕使，传诏亲付玉麒麟。\n千里江山增丽，是处旌旗改色，佳气郁轮。\n看取连宵雪，借与万家春。\n建崇牙，开盛府，是生辰。\n十州老稚，都向今日祝松椿。\n多少活人阴德，合享无边长算，唯有我知君。\n来岁更今日，一气转洪钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10335, '水调歌头', '张孝祥', '舣棹太湖岸，天与水相连。\n垂虹亭上，五年不到故依然。\n洗我征尘三斗，快揖商飙千里，鸥鹭亦翩翩。\n身在水晶阕，真作驭风仙。\n望中秋，无五日，月还圆。\n倚栏清啸孤发，惊起壑龙眠。\n欲酹鸱夷西子，未办当年功业，空系五湖船。\n不用知馀事，莼正芳鲜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10336, '水调歌头', '张孝祥', '螯禁辍颇牧，熊拭赖龙黄。\n一时林莽千险，蜂午要驱攘。\n金版六韬初拭，烟敛山空野回，低草见牛羊。\n旒纩释南顾，戈甲濯银潢。\n玉书下，褒懿绩，促曹装。\n帝宸天近，红旆东去带朝阳。\n归辅五云丹陛，回首楚楼千里，遗爱满潇湘。\n应记依刘客，曾此奉离觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10337, '多丽', '张孝祥', '景萧疏，楚江那更高秋。\n远连天，茫茫都是，败芦枯蓼汀洲。\n认炊烟，几家蜗舍，映夕照，一簇渔舟。\n去国虽遥，宁亲渐近，数峰青处是吾州。\n便乘取，波平风静，荃棹且夷犹。\n关情有，冥冥去雁，拍拍轻鸥。\n忽追思，当年往事，惹起无限羁愁。\n拄笏朝来多爽气，秉烛夜永足清游。\n翠袖香寒，朱弦韵悄，无情江水只东流。\n楼晚，清商哀怨，还听隔船讴。\n无言久，馀霞散绮，烟际帆收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10338, '木兰花慢', '张孝祥', '送归云去雁，澹寒采、满溪楼。\n正佩解湘腰，钗孤楚鬓，鸾鉴分收。\n凝情望行处路，但疏烟远树织离忧。\n只有楼前溪水，伴人清泪长流。\n霜华夜永逼衾绸。\n唤谁护衣篝。\n念芬馆重来，芳尘未扫，争见嬉游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10339, '木兰花慢', '张孝祥', '紫箫吹散後，恨燕子，只空楼。\n念璧月长亏，玉簪中断，覆水难收。\n青鸾送碧云句，道霞扃雾锁不堪优。\n情与文梭共织，怨随宫叶同流。\n人间天上两悠悠。\n暗泪洒灯篝。\n记谷口园林，当时驿舍，梦里曾游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10340, '水龙吟', '张孝祥', '竹舆晓入青阳，细风凉月天如洗。\n峰回路转，云舒霞卷，了非人世。\n转就丹砂，铸成金鼎，碧光相倚。\n料天关虎守，箕畴龙负，开神秘、留兹地。\n缥缈珠幢羽卫。\n望蓬莱、初无弱水。\n仙人拍手，山头笑我，尘埃满袂。\n春锁瑶房，雾迷芝圃，昔游都记。\n怅世缘未了，匆匆又去，空凝伫、烟霄里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10341, '水龙吟', '张孝祥', '平生只说浯溪，斜阳唤我归船系。\n月华未吐，波光不动，新凉如水。\n长啸一声，山鸣谷应，栖禽惊起。\n问元颜去後，水流花谢，当年事，凭谁记。\n须信两翁不死。\n驾飞车，时游兹地。\n漫郎宅里，中兴碑下，应留屐齿。\n酌我清尊，洗公孤愤，来同一醉。\n待相将把袂，清都归路，骑鹤去，三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10342, '念奴娇', '张孝祥', '洞庭青草，近中秋、更无一点风色。\n玉鉴琼田三万顷，著我扁舟一叶。\n素月分辉，明河共影，表里俱澄澈。\n悠然心会，妙处难与君说。\n应念岭海经年，孤光自照，肝肺皆冰雪。\n短发萧骚襟袖冷，稳泛沧浪空阔。\n尽吸西江，细斟北斗，万象为宾客。\n扣舷独笑，不知今夕何夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10343, '念奴娇', '张孝祥', '弓刀陌上，净蛮烟瘴雨，朔云边雪。\n幕府横驱三万里，一把平安遥接。\n方丈三韩，西山八诏，慕义羞椎结。\n梯航入贡，路经头痛身热。\n今代文武通人，青宵不上，却把南州节。\n虏马秋肥雕力健，应看名王宵猎。\n壮士长歌，故人一笑，趁得梅花月。\n王春奏计，便须平布清切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10344, '念奴娇', '张孝祥', '朔风吹雨，送凄凉天气，垂垂欲雪。\n万里南荒云雾满，弱水蓬莱相接。\n冻合龙冈，寒侵铜柱，碧海冰澌结。\n凭高一笑，问君何处炎热。\n家在楚尾吴头，归期犹未，对此惊时节。\n忆得年时貂帽暖，铁马千群观猎。\n狐兔成车，笙歌震地，归踏层城月。\n持杯且醉，不须北望凄切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10345, '念奴娇', '张孝祥', '绣衣使者，度郢中绝唱，阳春白雪。\n人物应须天上去，一日君恩三接。\n粉省香浓，宫床锦重，更把丝结。\n臣心如水，不教炙手成热。\n还记岭海相从，长松千丈，映我秋竿节。\n忍冻推敲清兴满，风里乌巾猎猎。\n只要东归，归心入梦，梦泛寒江月。\n不因莼。\n白头亲望真切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10346, '念奴娇', '张孝祥', '星沙初下，望重湖远水，长云漠漠。\n一叶扁舟谁念我，今日天涯飘泊。\n平楚南来，大江东去，处处风波恶。\n吴中何地，满怀俱是离索。\n常记送我行时，绿波亭上，泣透青头薄。\n樯燕低飞人去後，依旧湘城帘幕。\n不尽山川，无穷烟浪，辜负秦楼约。\n渔歌声断，为君双泪倾落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10347, '醉蓬莱', '张孝祥', '问人间荣事。\n海内高名，似今谁比。\n脱屣归来，眇浮云富贵。\n致远钩深，乐天知命，且从容阅世。\n火候周天，金文满义，从来活计。\n有酒一尊，有棋一局，少日亲朋，旧家邻里。\n世故纷纭，但蚊虻过耳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10348, '雨中花慢', '张孝祥', '一叶凌波，十里驭风，烟鬟雾鬓萧萧。\n认得兰皋琼佩，水馆冰绡。\n秋霁明霞乍吐，曙凉宿霭初消。\n恨微颦不语，少进还收，伫立超遥。\n神交冉冉，愁思盈盈，断魂欲遣谁招。\n犹自待，青鸾传信，乌鹊成桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10349, '二郎神', '张孝祥', '坐中客。\n共千里、潇湘秋色。\n渐万宝西成农事了，看、黄云阡陌。\n乔□橘洲风浪稳，岳镇耸、倚天青壁。\n追前事、兴亡相续，空与山川陈迹。\n南国。\n都会繁盛，依然似昔。\n聚翠羽明珠三市满，楼观涌、参差金碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10350, '浣溪沙', '张孝祥', '同是瀛州册府仙。\n只今聊结社中莲。\n胡笳按拍酒如川。\n唤起封姨清晚景，更将荔子荐新圆。\n从今三夜看蝉娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10351, '浣溪沙', '张孝祥', '细仗春风簇翠筵。\n烂银袍拂禁炉烟。\n旃书名字压宫垣。\n太学诸生推独步，玉堂学士合登仙。\n乃翁种德满心田。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10352, '浣溪沙', '张孝祥', '只说闽山锦绣帷。\n忽从团扇得生枝。\n绉红衫子映丰肌。\n春线应怜壶漏永，夜针频见烛花摧。\n尘飞一骑忆来时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10353, '浣溪沙', '张孝祥', '滟滟湖光绿一围。\n修林断处白鸥飞。\n天机云锦蘸空飞。\n乞我百弓真可老，为公一饮醉忘归。\n扁舟日日弄晴晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10354, '浣溪沙', '张孝祥', '晚雨潇潇急做秋。\n西风凉鬓已飕飕。\n烛花明夜酒花浮。\n醉眼定知非妙赏，□词端为□□留。\n想君泾渭不同流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10355, '浣溪沙', '张孝祥', '稳泛仙舟上锦帆。\n桃花清浪舞清湾。\n寿星相伴到人间。\n黄石公传三百字，西王母授九霞丹。\n银潢有路接三山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10356, '浣溪沙', '张孝祥', '北苑春风小凤团。\n炎州沈水胜龙涎。\n殷勤送与绣衣仙。\n玉食乡来思苦口，芳名久合上凌烟。\n天教富贵出长年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10357, '浣溪沙', '张孝祥', '霜日明宵水蘸空。\n鸣鞘声里绣旗红。\n澹烟衰草有无中。\n万里中原烽火北，一尊浊酒戍楼东。\n酒阑挥泪向悲风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10358, '浣溪沙', '张孝祥', '宫柳垂垂碧照空。\n九门深处五云红。\n朱衣只在殿当中。\n细拈丝梢龙尾北，缓携纶旨凤池东。\n阿婆三五笑春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10359, '浣溪沙', '张孝祥', '日暖帘帏春画长。\n纤纤玉指动抨床。\n低头佯不顾檀郎。\n豆蔻枝头双蛱蝶，芙蓉花下两鸳鸯。\n壁间闻得唾茸香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10360, '浣溪沙', '张孝祥', '射策金门记昔年。\n又交藩翰入陶甄。\n不妨衣钵再三传。\n粉泪但能添楚竹，罗巾谁解系吴船。\n捧杯犹愿小留连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10361, '浪淘沙', '张孝祥', '琪树间瑶林。\n春意深深。\n梅花还被晓寒禁。\n竹里一枝斜向我，欲诉芳心。\n楼外卷重阴。\n玉界沈沈。\n何人低唱醉泥金。\n掠水飞来双翠碧，应寄归音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10362, '浪淘沙', '张孝祥', '溪练写寒林。\n云重烟深。\n楼高风恶酒难禁。\n徙倚阑干谁共语，江上愁心。\n清兴满山阴。\n鸿断鱼沈。\n一书何啻值千金。\n独扶瑶微弦欲断，凭寄知音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10363, '定风波', '张孝祥', '铃索声乾夜未央。\n曲栏花影步凄凉。\n莫道岭南冬更暖。\n君看。\n梅花如雪月如霜。\n见说墙西歌吹好，玉人扶坐劝飞觞。\n老子婆婆成独冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10364, '望江南・忆江南', '张孝祥', '谈子醉，独立睨东风。\n未试玉堂挥翰手，只今楚泽钓鱼翁。\n万事举杯空。\n谋一笑，一笑与君同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10365, '望江南・忆江南', '张孝祥', '朝元去，深殿扣瑶钟。\n天近月明黄道冷，参回斗转碧宵空。\n身在九光中。\n风露下，环佩响丁东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10366, '醉落魄・一斛珠', '张孝祥', '轻黄澹绿。\n可人风韵闲装束。\n多情早是眉峰蹙。\n一点秋波，闲里观人毒。\n桃花庭院光阴速。\n铜谁唱大堤曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10367, '桃源忆故人', '张孝祥', '朔风弄月吹银霰。\n帘幕低垂三面。\n酒入玉肌香软。\n压得寒威敛。\n檀槽乍拈么丝慢。\n弹得相思一半。\n不道有人肠断。\n犹作声声颤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10368, '临江仙', '张孝祥', '试问梅花何处好，与君藉草携壶。\n西园清夜片尘无。\n一天云破碎，两树玉扶疏。\n谁昭华吹古怨，散花便满衣裾。\n只疑幽梦在清都。\n星稀河影转，霜重月华孤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10369, '临江仙', '张孝祥', '试问宜楼楼下竹，年来应长新篁。\n使君五岭又三湘。\n旧游知好在，熟处更难忘。\n尚念论心舒否，只今湖海相望。\n遥怜阴过酒尊凉。\n举觞须酹我，门外是清江。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10370, '如梦令', '张孝祥', '花叶相遮相映。\n雨过翠明金润。\n折得一枝归，满路清香成阵。\n风韵。\n风韵。\n寄赠绮窗云鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10371, '菩萨蛮', '张孝祥', '丝金缕翠幡儿小。\n裁罗拈线花枝袅。\n明日是新春。\n春风生鬓云。\n吴霜看点点。\n愁里春来浅。\n只愿此花枝。\n年年长带伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10372, '菩萨蛮', '张孝祥', '庭叶翻翻秋向晚。\n凉砧敲月催金剪。\n楼上已清寒。\n不堪频倚栏。\n邻翁开社瓮。\n唤客情意重。\n不醉且无归。\n醉时归路迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10373, '菩萨蛮', '张孝祥', '恰则春来春又去。\n凭谁说与春教住。\n与问坐中人。\n几回迎送春。\n明年春更好。\n只怕人先老。\n春去有来时。\n愿春长见伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10374, '菩萨蛮', '张孝祥', '东风约略吹罗幕。\n一檐细雨春阴薄。\n试把杏花看。\n湿红娇暮寒。\n佳人双玉枕。\n烘醉鸳鸯锦。\n折得最繁枝。\n暖香生翠帏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10375, '菩萨蛮', '张孝祥', '琢成红玉纤纤指。\n十三弦上调新水。\n一弄入云声。\n月明天更青。\n匆匆莺语啭。\n待寓昭君怨。\n寄语莫重弹。\n有人愁倚栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10376, '菩萨蛮', '张孝祥', '玉龙细点三更月。\n庭花影下馀残雪。\n寒色到书帏。\n有人清梦迷。\n墙西歌吹好。\n烛暖香闺小。\n多病怯杯觞。\n不禁冬夜长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10377, '菩萨蛮', '张孝祥', '江山佳处留行客。\n醉馀老眼迷空碧。\n独倚最高楼。\n乾坤日夜浮。\n微风吹笑语。\n白日鱼龙舞。\n此意忽翩翩。\n凭虚吾欲仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10378, '菩萨蛮', '张孝祥', '雪消墙角收灯後。\n野梅官柳春全透。\n池阁又东风。\n烛花烧夜红。\n一尊留好客。\n尽阑干月。\n已醉不须归。\n试听乌夜啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10379, '菩萨蛮', '张孝祥', '溶溶花月天如水。\n阑干小倚东风里。\n夜久寂无人。\n露浓花气清。\n悠然心独喜。\n此意如何意。\n不似隐墙东。\n烛花围坐红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10380, '菩萨蛮', '张孝祥', '暗潮清涨蒲塘晚。\n断云不隔东归眼。\n堂上晚风凉。\n藕花开处香。\n夜航人不渡。\n白鹭双飞去。\n待得月华生。\n携筇独自行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10381, '菩萨蛮', '张孝祥', '缥缈飞来双彩凤。\n雨疏云淡撩清梦。\n兰薄未禁秋。\n月华如水流。\n采香溪上路。\n愁满参差树。\n独倚晚楼风。\n断霞萦素空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10382, '菩萨蛮', '张孝祥', '蘼芜白芷愁烟渚。\n曲琼细卷江南雨。\n心事怯衣单。\n楼高生晚寒。\n云鬓香雾湿。\n翠袖凄馀泣。\n春去有来时，春从沙际归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10383, '菩萨蛮', '张孝祥', '十年长作江头客。\n樯竿又挂西风席。\n白鸟去边明。\n楚山无数青。\n倒冠仍落佩。\n我醉君须醉。\n试问识君不。\n青山与白鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10384, '菩萨蛮', '张孝祥', '乳羝属国归来早。\n知君胆大身犹小。\n一节不须论。\n功名看致君。\n镇西楼上酒。\n父老为公寿。\n更祝太夫人。\n年年封诏新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10385, '菩萨蛮', '张孝祥', '胭脂浅染双珠树。\n东风到处娇无数。\n不语恨厌厌。\n何人思故园。\n故园花烂熳。\n笑我归来晚。\n我老只思归。\n故园花雨时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10386, '菩萨蛮', '张孝祥', '吴波细卷东风急。\n斜阳半落苍烟湿。\n一棹采菱歌。\n倚栏人奈何。\n天公怜好客。\n酒面风吹白。\n更引十玻璃。\n月明骑鹤归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10387, '菩萨蛮', '张孝祥', '冥秋夕溥清露。\n玉绳耿耿银潢注。\n永夜滴铜壶。\n月华楼影孤。\n佳人纡绝唱。\n翠幕丛宵上。\n休劝玉东西。\n乌鸦枝上啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10388, '西江月', '张孝祥', '问讯湖边春色，重来又是三年。\n东风吹我过湖船。\n杨柳丝丝拂面。\n世路如今已惯，此心到处悠然。\n寒光庭下水如天。\n飞起沙鸥一片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10389, '西江月', '张孝祥', '风定滩声未已，雨来篷底先知。\n岸边杨柳最怜伊。\n忆得船儿曾系。\n湖雾平吞白塔，茅檐自有青旗。\n三杯村酒醉如泥。\n天色寒呵且睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10390, '西江月', '张孝祥', '冉冉寒生碧树，盈盈露湿黄花。\n故人玉节有光华。\n高会仍逢戏马。\n万事只今如梦，此身到处为家。\n与君相逢更天涯。\n拼了茱萸醉把。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10391, '西江月', '张孝祥', '诸老何烦荐口，先生自简渊衷。\n千年圣学有深功。\n妙处无非日用。\n已授一编圯下，却须三顾隆中。\n鸿钧早晚转春风。\n我亦从君贾勇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10392, '西江月', '张孝祥', '慈母行封大国，老仙早上蓬山。\n天怜阴德遍人间。\n赐与还丹七返。\n莫问清都紫府，长教绿鬓朱颜。\n年年今日采衣斑。\n兄弟同扶酒盏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10393, '西江月', '张孝祥', '不识平源太守，向来水北山人。\n世间功业谩亏成。\n华发萧萧满镜。\n幸有田园故里，聊分风月江城。\n西湖西畔晚波平。\n袖手时来照影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10394, '西江月', '张孝祥', '楼外疏星印水，楼头画烛烘帘。\n凭高举酒恨厌厌。\n征路虚无指点。\n酒兴因君开阔，山容向我增添。\n一钩新月弄纤纤。\n浓雾花房办敛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10395, '西江月', '张孝祥', '满载一船秋色，平铺十里湖光。\n波神留我看斜阳。\n放起鳞鳞细浪。\n明日风回更好，今宵露宿何妨。\n水晶宫里奏霓裳。\n准拟岳阳楼上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10396, '西江月', '张孝祥', '窗户青红尚湿，主人已作归期。\n坐中宾客尽邹枚。\n盛事它年应记。\n别酒深深但劝，离歌缓缓休催。\n扁舟明日转清溪。\n好月相望千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10397, '西江月', '张孝祥', '汗铸九金神鼎，隋书小字莲经。\n刚风劫火转清冥。\n护守应烦仙圣。\n昨梦归来帝所，今朝寿我亲庭。\n只将此宝伴长生。\n谈笑中原底定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10398, '西江月', '张孝祥', '落日熔金万顷，晴岚洗剑双锋。\n紫枢元是黑头公。\n佳处因君愈重。\n分得湖光一曲，唤回庐岳千峰。\n清尊今夜偶然同。\n早晚商岩有梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10399, '西江月', '张孝祥', '畴昔通家事契，只今两镇交承。\n起居枢密太夫人。\n绿鬓斑衣相映。\n乞得神仙九酝，祝教福禄千春。\n台星直上寿星明。\n长见门阑鼎盛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10400, '减字木兰花', '张孝祥', '佳人绝妙。\n不惜千金频买笑。\n燕姹莺娇。\n始遣清歌透碧宵。\n主人好事。\n更倒一尊留客醉。\n我醉思家。\n月满南池欲漾花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10401, '减字木兰花', '张孝祥', '一尊留夜。\n宾蜡烘帘光激射。\n冻合铜壶。\n细听冰檐夜剪酥。\n清愁冉冉。\n酒唤红潮登玉脸。\n明日重看。\n玉界琼楼特地寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10402, '减字木兰花', '张孝祥', '爱而不见。\n立马章台空便面。\n想像娉婷。\n只恐丹青画不成。\n诗人老去。\n恰要莺莺相伴住。\n试与平章。\n岁晚教人枉断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10403, '减字木兰花', '张孝祥', '阿谁曾见。\n马上墙阴通半面。\n玉立娉婷。\n一点灵犀寄目成。\n明朝重去。\n人在横溪溪畔住。\n乔木千章。\n摇落霜风只断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10404, '减字木兰花', '张孝祥', '江头送客。\n枫叶荻花秋索索。\n弦索休弹。\n清泪无多怕湿衫。\n故人相遇。\n不醉如何归得去。\n我醉望归。\n烟满空江月满堤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10405, '减字木兰花', '张孝祥', '春如有意。\n未接年华春已至。\n春事还新。\n多得年时五日春。\n春郊便绿。\n只向腊前春已足。\n屈指元宵。\n正是新春二十朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10406, '减字木兰花', '张孝祥', '慈闱生日。\n见说今年年九十。\n戏彩盈门。\n大底孩儿七个孙。\n人间喜事。\n只这一般难得似。\n愿我双亲。\n都似君家太淑人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10407, '减字木兰花', '张孝祥', '吹箫泛月。\n往事悠悠休更说。\n拍碎琉璃。\n始觉从前万事非。\n清齐净戒。\n休作断肠垂泪债。\n识破嚣尘。\n作个逍遥物外人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10408, '减字木兰花', '张孝祥', '人间奇绝。\n只有梅花枝上雪。\n有个人人。\n梅样风标雪样新。\n芳心不展。\n嫩绿阴阴愁冉冉。\n一笑相看。\n试荐冰磐一点酸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10409, '减字木兰花', '张孝祥', '枷花搦柳。\n知道东君留意久。\n惨绿愁红。\n憔悴都因一夜风。\n轻狂蝴蝶。\n拟欲扶持心又怯。\n要免离披。\n不告东君更告谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10410, '清平乐', '张孝祥', '光尘扑扑。\n宫柳低迷绿。\n斗鸭阑干春诘曲。\n帘额微风绣蹙。\n碧云轻翼无凭。\n困来小倚银屏。\n楚梦未禁春晚，黄鹂犹自声声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10411, '清平乐', '张孝祥', '油幢画戟。\n玉铉调春色。\n勋阀诸郎俱第一。\n风流前辈敌。\n玉人双华х。\n翠云深处消摇。\n有客留君东阁，时闻风下笙箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10412, '清平乐', '张孝祥', '吹香嚼蕊。\n独立东风里。\n玉冻云娇天似水。\n羞杀夭桃李。\n如今见说阑干。\n不禁月冷霜寒。\n垅上驿程人远，楼头戍角声乾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10413, '清平乐', '张孝祥', '英姿慷慨。\n独立风尘外。\n湖海平生豪气在。\n行矣云龙际会。\n充庭兰玉森森。\n一觞共祝修铃。\n此地去天尺五，明年持西清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10414, '清平乐', '张孝祥', '向来省户。\n谋国参伊吕。\n暂借良筹非再举。\n谈笑肃清三楚。\n良辰上客徜佯。\n奏篇犹记传香。\n此日一尊相属，它时同在岩廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10415, '点绛唇', '张孝祥', '四到蕲州，今年更是逢重九。\n应时纳。\n随分开尊酒。\n屡舞婆娑，醉我平生友。\n休回首。\n世间何有。\n明月疏疏柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10416, '点绛唇', '张孝祥', '绮燕高张，玉潭月丽玻璃满。\n旆霞行卷。\n无复长安远。\n夏木阴阴，路袅薰风转。\n空留恋。\n细吹银管。\n别意随声缓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10417, '点绛唇', '张孝祥', '萱草榴花，画堂永昼风清暑。\n麝团菰黍。\n助泛菖蒲醑。\n兵辟神符，命续同心缕。\n宜欢聚。\n绮筵歌舞。\n岁岁酬端午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10418, '卜算子', '张孝祥', '雪月最相宜，梅雪都清绝。\n去岁江南见雪时，月底梅花发。\n今岁早梅开，依旧年时月。\n冷艳孤光照眼明，只欠些儿雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10419, '诉衷情', '张孝祥', '晚烟斜日思悠悠。\n西北有高楼。\n十分准拟明月，还似去年游。\n飞玉，卷琼钩。\n唤新愁。\n娥贪共，暮雨朝云，忘了中秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10420, '诉衷情', '张孝祥', '乱红深紫过群芳。\n初欲灭春光。\n花王自有标格，尘外锁韶阳。\n留国艳，问仙乡。\n自天香。\n翠帏遮日，红烛通宵，与醉千场。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10421, '好事近', '张孝祥', '一朵木犀花，珍重玉纤新摘。\n插向远山深处，占十分秋色。\n满园桃李闹春风，漫红红白白。\n争似淡妆娇面，伴蓬莱仙客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10422, '好事近', '张孝祥', '万瓦雪花浮，应是化工融结。\n仍看牡丹初绽，有层层千叶。\n镂冰剪水更鲜明，说道真奇绝。\n来报主人佳兆，庆我公还阕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10423, '南歌子', '张孝祥', '曾到蕲州不，人人说使君。\n使君才具合经纶。\n小试边城、早晚上星辰。\n佳节重阳近，清歌午夜新。\n举杯相属莫辞频。\n後日相思、我已是行人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10424, '水调歌头', '李处全', '明月浸瑶碧，河汉水交流。\n偏来照我，知我白发不胜愁。\n客里山中三载，枕上人间一梦，曾忆到瀛洲。\n矫首蓬壶路，两腋已飕飕。\n记扁舟，浮震泽，趁中秋。\n垂虹亭上，与客千里快凝眸。\n看剑引杯狂醉，饮水曲肱高卧，鹏已同游。\n起舞三人耳，横笛唤沙鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10425, '水调歌头', '李处全', '落日暝云合，客子意如何。\n定知今日，封六巽二弄干戈。\n四望际天空阔，一叶凌涛掀舞，壮志未消磨。\n为向吴儿道，听我扣舷歌。\n我常欲，利剑戟，斩蛟鼍。\n胡尘未扫，指挥壮士挽天河。\n谁料半生忧患，成就如今老态，白发逐年多。\n对此貌无恐，心亦畏风波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10426, '水调歌头', '李处全', '春事已如许，柳眼早依依。\n故园桃李何似，芳蕊想团枝。\n此地嵩高名里，信美元非吾土。\n清梦绕。\n扶杖欲行乐，还使我心悲。\n对琴书，歌一阕，引千卮。\n昔曾击楫，今日投老叹吾衰。\n睡起推窗凝睇，失喜柔桑微绿，便拟作春衣。\n搔首长吟处，此意有谁知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10427, '水调歌头', '李处全', '微雨眼明处，春信著南枝。\n百花头上消息，为我赴襟期。\n松下凌霜古干，竹外横窗疏影，同是翠寒姿。\n唤取我曹赏，莫使俗流知。\n对风前，看雪後，总相宜。\n碧天如洗，何许羌笛月边吹。\n一段出群标格，合得水仙兄事，千古豫章诗。\n鼎鼐付佳实，终待梦秋时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10428, '水调歌头', '李处全', '飞雪已传信，端叶未分枝。\n莫嫌开晚，前月曾付小春期。\n谁道梳风洗雨，不许调脂弄粉，容易天姿。\n眼界未多见，鼻观已先知。\n昔西湖，今北客，各从宜。\n要渠烂熳，趣得暖律为渠吹。\n犹记石亭攀折，浑似扬州观赏，清兴欲寻诗。\n三嗅不离手，如得和篇时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10429, '水调歌头', '李处全', '今夕定何夕，今夕岁还除。\n团栾儿女，尽情灯火照围炉。\n但惜年从节换，便觉身随日老，踪迹尚沈浮。\n万事古如此，聊作旧桃符。\n任东风，吹缟鬓，戏儒。\n韶颜壮齿，背人去似隙中驹。\n杯酌犹倾腊酒，漏箭已传春夜，何处不歌呼。\n惟愿长穷健，命酹且欢娱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10430, '水调歌头', '李处全', '楼观数南国，烟雨压东州。\n溪山雄胜，天开图画肖瀛洲。\n我破瀛洲客梦，来剖仙洲符竹，乐岁又云秋。\n聊作幻师戏，肯遗後人愁。\n趁佳时，招我辈，共凝眸。\n君侯胸次邱壑，意匠付冥搜。\n刻日落成华栋，对月难并清景，千丈素光流。\n老子兴何极，小子趣觥筹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10431, '满江红', '李处全', '清晓高堂，春晚处、旧红新绿。\n耸曩昔、蟠桃初种，更并潭菊。\n强健老人松下鹤，森荣孙子霜中竹。\n看共持、寿祝期颐，倾。\n烘晴昼，炉烟馥。\n连永夜，笙歌簇。\n喜一时欢意，何人兼足。\n早愿诸甥成宅相，便从明岁开汤沐。\n向年年、今日度新腔，调仙曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10432, '临江仙', '李处全', '畴昔方壶游戏地，群仙步履相从。\n明黄衫子御西风。\n佩环金错落，羽葆翠璁珑。\n骑鹄翩然归去路，吹箫横度青峰。\n夜深河汉冷秋容。\n前驱香十里，飘坠月轮东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10433, '念奴娇', '李处全', '一天春意，趁东皇幽赏，重飞端叶。\n造物有心成伟观，来伴红蕖开彻。\n桂魄初圆，梅腮全放，节物俱奇绝。\n冷官门巷，望中北固楼堞。\n遐想蓬底高人，拥衾无寐，九曲长增结。\n我亦低窗翻蠹纸，失喜瑶花盈尺。\n拥鼻孤吟，搔头危坐，所欠惟佳客。\n须君来此，脸纹相对生缬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10434, '满庭芳', '李处全', '乳燕将雏，啼莺求友，江南梅子黄时。\n欲晴还雨，烟外看成丝。\n迎袂风来梦陇，吹饼饵、香入书帷。\n行吟处，溪翁说我，不似去年衰。\n方池。\n荷出水，朱榴倚槛，粉箨穿篱。\n有吾曹我辈，把酒寻诗。\n醉去黑甜一枕，炉烟袅、花影斜晖。\n家山乐，南窗寄傲，唯有晦庵知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10435, '鹧鸪天', '李处全', '烟雨溟溟趁落成。\n只应天欲称佳名。\n万丝明灭青山映，匹素浓纤渌水萦。\n民亦乐，美能并。\n酒杯莫惜十分倾。\n要知社下平生志，觞政聊须为主盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10436, '鹧鸪天', '李处全', '缥缈危楼百尺雄。\n淡烟疏雨暗帘栊。\n偶妨清赏中秋夕，为忆名言玉局翁。\n贤达意，古今同。\n凉天佳月会相逢。\n老蟾一跃三千丈，却唤娥驾阆风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10437, '柳梢青', '李处全', '九天圆月。\n香尘碎玉，素涛翻雪。\n石乳香甘，松风汤嫩，一时三绝。\n清宵好尽欢娱，奈明日、扶头怎说。\n整顿颓山，殷勤春露，馀甘齿颊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10438, '柳梢青', '李处全', '馀甘齿颊。\n酒□半酣，漏声频促。\n月下传呼，风前掺别，无因留客。\n丁宁玉笋磨香，为料理、十分醒著。\n後会何时，前欢未尽，明朝重约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10439, '朝中措', '李处全', '晦庵四至似天宽。\n生计有心田。\n闲弄炉薰茗碗，困寻纸帐蒲团。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10440, '朝中措', '李处全', '薰风庭院燕双飞。\n园柳啭黄鹂。\n是处蜂狂蝶乱，元来绿暗红稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10441, '菩萨蛮', '李处全', '杜鹃只管催归去。\n知渠教我归何处。\n故国泪生痕。\n那堪枕上闻。\n严装吾已具。\n泛宅吴中路。\n弭棹唤东邻。\n江东日暮云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10442, '菩萨蛮', '李处全', '晦庵老子修行久。\n问禅金粟曾回首。\n截竹是禅机。\n吹破粟玉枝。\n西湖秋好处。\n承得昭阳露。\n香透月轮低。\n来薰打坐时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10443, '菩萨蛮', '李处全', '四时皆有司花女。\n杪秋犹见花如许。\n想得紫金丹。\n工夫造化间。\n春莺留弱羽。\n更渍蔷薇露。\n莫取落英餐。\n留供醉眼看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10444, '浣溪沙', '李处全', '宋玉应当久断肠。\n满城风雨尽重阳。\n年年戏马忆吾乡。\n催促东篱金蕊放，佳人更绣紫萸囊。\n白衣才到共飞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10445, '西江月', '李处全', '窗户风薰端午，楼台月满中秋。\n阴晴寒暑总无忧。\n几事不如重九。\n落帽何羞种种，看山都付悠悠。\n黄花已作醉乡游。\n梦觉黄花在手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10446, '西江月', '李处全', '妆楼红袖，亭亭将阃青油。\n东皇天巧世无俦。\n定有司花妙手。\n十里香风晓霁，千家绮陌春游。\n竹西路转古扬州。\n歌吹只应如旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10447, '西江月', '李处全', '南国一分春色，东窗八面光风。\n女兄欢笑酒尊同。\n满眼儿孙群从。\n但愿年逾百岁，何妨时醉千锺。\n朱颜绿发照青铜。\n要看如龙如凤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10448, '生查子', '李处全', '庭户小光中，帘幕秋光里。\n曲沼绮疏横，几处新妆洗。\n红脸露轻匀，翠袖风频倚。\n鸾鉴不须开，自有窗前水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10449, '生查子', '李处全', '温柔属东西，和冷经三五。\n几夜德星明，果应荀陈聚。\n分虎屈雄姿，展骥淹遐步。\n除诏已涂芝，便看朝天去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10450, '减字木兰花', '李处全', '今年菊早。\n想到重阳花正好。\n玉冷金寒。\n全似东篱挹露看。\n色庄香重。\n直与梅花堪伯仲。\n待唤渊明。\n三友相从盖为倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10451, '减字木兰花', '李处全', '谁将翡翠。\n闲屑黄金摅巧思。\n缀就花钿。\n飞上秋云入鬓蝉。\n一枝斜倚。\n披拂香风多少意。\n午镜重匀。\n娇额妆成宫样新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10452, '减字木兰花', '李处全', '更生观尽。\n双璧蒹葭那敢并。\n四海无人。\n笑语从容许我亲。\n平生此客。\n复与太丘登醉白。\n病里颦眉。\n贪看惺惺骑马归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10453, '相见欢', '李处全', '新凉襟袂冷然。\n乍晴天。\n风送谁家羌管、月便娟。\n云散尽，秋空碧，玉钩悬。\n洗耳时听三弄、等团圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10454, '江城子', '李处全', '一番风雨一番凉。\n炯秋光。\n又重阳。\n潇洒东篱，浑学汉宫妆。\n今日且须开口笑，花露袅，鬓云香。\n泼醅新取淡鹅黄。\n趁幽芳。\n趣飞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10455, '阮郎归', '李处全', '佳人偏爱菊花天。\n玉钗金附蝉。\n歌声缥缈紫云边。\n博山沈水烟。\n须斗酒，泛觥船。\n乃翁能百篇。\n高堂此会看年年。\n夜深人醉眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10456, '忆秦娥', '李处全', '春山寂。\n佳人凝笑山南陌。\n山南陌。\n东风寒浅，绛罗衫窄。\n阑干倚处云如幂。\n晚来雨过胭脂滴。\n胭脂滴。\n啼妆难劝，且须欢伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10457, '忆秦娥', '李处全', '莺花寂。\n为渠游冶长安陌。\n长安陌。\n今朝风景，酒肠宽窄。\n锦茵闲把薰笼幂。\n嫩红倚绿娇如滴。\n娇如滴。\n古今高咏，老泉仙伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10458, '好事近', '李处全', '香雪弄春妍，柳外黄昏池阁。\n要看月华相映，卷东风帘幕。\n更倾壶酒伴芳姿，名字胜桑落。\n直与岭梅兄弟，是醍醐酥酪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10459, '蓦山溪', '李处全', '梨花过雨，已是春强半。\n花恼欲颠狂，兴浑在、秋千架畔。\n搔头无语，斜日上帘栊，飞上下，语呢喃，又见双双燕。\n鱼吹细浪，镜面摇歌扇。\n籍草倒芳尊，亲香茵、落红千片。\n追奔蜗角，回首醉初醒，逢节物，且欢娱，莫待流年换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10460, '卜算子', '李处全', '春事忆松江，江上花无数。\n一枕匆匆醉梦中，芳草庵路。\n携手度虹梁，洗眼看渔具。\n盐豆莼羹是处无，早买扁舟去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10461, '卜算子', '李处全', '芍药斗新妆，杨柳飞轻雪。\n著意留连不放春，已向东皇说。\n况是谪仙家，自有长生诀。\n方士呼来借玉蟾，要吸杯中月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10462, '诉衷情', '李处全', '疏烟明淡雨膏如。\n青入烧痕初。\n开到无言桃李，春事喜敷腴。\n随杖履，有琴书。\n酒盈壶。\n风前花下，睡起醒时，著我篮舆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10463, '醉蓬莱', '李处全', '政馀春眷眷，首夏，清和时候。\n晓色，瑞霭凝轩牖。\n著子青梅，袅枝红药，物物俱情厚。\n绿倚朱弦，檀槽铁拨，华堂称寿。\n季父高怀，庆锺吾姊，富贵长年，自应兼有。\n更看诸郎，谢砌芝兰秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10464, '贺新郎', '李处全', '秋意生何许。\n对玉钩、微云避舍，素风吹暑。\n银汉桥成天路稳，乾鹊声声媚妩。\n送仙杖、年年须度。\n离合悲欢多少话，想今宵、缱绻难深诉。\n千古恨，无新故。\n聊须作意成欢绪。\n为佳时、金针戏把，翠觞频举。\n莫念匆匆轻掺袂，天上元无间阻。\n况好是、新凉庭户。\n倦客天涯磋老大，趁珠帘、绣额高楼处。\n乞些巧，调儿女。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10465, '贺新郎', '李处全', '心事知谁许。\n政吾曹、辞弄翰，邀凉蠲暑。\n节物於人俱可喜，今夕渠偏媚妩。\n笑曝腹、书生风度。\n河鼓天孙非世俗，纵惊云、急雨休轻诉。\n忆倾盖，便如故。\n良辰欢意宽离绪。\n称仙家、瑶台缥缈，霓裳掀举。\n应想尘寰空怅望，月路谁曾隔阻。\n是处有、绮窗朱户。\n我爱五湖烟水阔，待扁舟，寻到机处。\n访婺女，共女。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10466, '四和香・四犯令', '李处全', '香雪新苞偏胜韵。\n领袖催花信。\n华节良辰人有分。\n看士女、垂鬓。\n莫向春风寻旧恨。\n乐事随方寸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10467, '玉楼春', '李处全', '年光箭脱无留计。\n才过立春还守岁。\n要知一岁已寻侬，听打个惊人喷嚏。\n椒盘荐寿休辞醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10468, '南乡子', '李处全', '和气作春妍。\n以作寒归塞地天。\n岁月翩翩人老矣，华颠。\n胆冷更长自不眠。\n节物映椒盘。\n柏酒香浮白玉船。\n捧劝大家相祝愿，何言。\n但愿今年胜去年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10469, '苏幕遮', '韩仙姑', '不忧贫，不念富。\n大悟之人，开著波罗铺。\n内心真知无价宝，欲识真如，正照菩提路。\n贪爱心，须除去。\n清静法身，直是堪凭据。\n忍辱波罗为妙乐，服了一圆，万病都新愈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10470, '朝中措', '周颉', '郧城清胜压湖湘。\n人物镇相望。\n秀气谁符楚泽，建安诸子文章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10471, '朝中措', '王彭年', '人才七泽盛三湘。\n前辈敢追望。\n惭愧史君劝驾，杯前重赐篇章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10472, '朝中措', '李伯虎', '史君清德比清湘。\n妙政古相望。\n闲暇恩波万井，笑谈风月千章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10473, '水调歌头', '丘', '一雁破空碧，秋满荻花洲。\n淮山淡扫，欲颦眉黛唤人愁。\n落日归云天外，目断清江无际，浩荡没轻鸥。\n有恨寄流水，无泪学羁囚。\n望石城，思东府，话西州。\n平芜千里，古来佳处几回秋。\n歌舞当年何在，罗绮一时同尽，梦幻两悠悠。\n杯到莫停手，唯酒可忘忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10474, '水调歌头', '丘', '人物冠江左，正始有遗音。\n谪仙风味，洒然那受一尘侵。\n倚马文章天与，霏屑谈辞云委，宣室为虚襟。\n小驻外台节，聊屈济时心。\n记长庚，曾入梦，恰而今。\n橙黄橘绿，可人风物是秋深。\n九日明朝佳节，得得天教好景，供与醉时吟。\n从此寿千岁，一岁一登临。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10475, '水调歌头', '丘', '小队拥龙节，三度过鲈乡。\n烟波万顷，波绉湿斜阳。\n何处渔舟唱晚，最是芦花风断，乃一声长。\n矫首望空阔，逸兴坠微茫。\n笑尘缨，何日许，濯沧浪。\n天随甫里，相寻无处一凄凉。\n会把水光山色，收入烟蓑短艇，胜世作清狂。\n举酒属公子，富贵未渠央。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10476, '水调歌头', '丘', '一叶下林表，秋色满蘅皋。\n江风吹雨初过，天宇一何高。\n蜡屐径来堂上，倚杖け然长啸，万里看云涛。\n逸兴浩无际，安得驾灵鳌。\n叹吾生，天地里，一秋毫。\n江山如传，古来阅尽几英豪。\n回首只今何在，举目依然风景，此意属吾曹。\n欲去重惆怅，松径冷萧骚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10477, '水调歌头', '丘', '彩舰驾飞，帆影漾江乡。\n肥梅天气，一声横玉换新阳。\n惊起沙汀鸥鹭，点破暮天寒碧，极目楚天长。\n一抹残霞外，云断水茫茫。\n朔清风，歌白雪，和沧浪。\n枕流亭馆，昔年行处半荒凉。\n我欲骖风游戏，收拾烟波佳景，一一付词章。\n闻说洞天好，何处水中央。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10478, '满江红', '丘', '驻马江头，聊自放、尘劳踪迹。\n身渐老、尊前羞见，异乡风物。\n雪柳垂金胜小，钗头又报春消息。\n记去年、持酒觅新词，人疏隔。\n时序好，今犹昔。\n携赏处，空追忆。\n都如梦才觉，悄然难觅。\n且饮不须论许事，从今煞有佳天色。\n但官闲、有酒便嬉游，愁无益。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10479, '满江红', '丘', '玉宇无尘，斜阳外、江楼伫立。\n人正远、骑鲸南去，笑言难挹。\n冰雪生寒烟瘴冷，海山著处恩波湿。\n问碧门、金阕待君来，何时入。\n犹自有，新篇什。\n应念我，相思急。\n满乌丝挥遍，麝煤香。\n尊酒相逢佳□□，十年一梦长川吸。\n想上都、风月未盟寒，追良集。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10480, '满江红', '丘', '十载重游，愧好在、吴中父老。\n官事里、空然痴绝，竟何曾了。\n赖有平生知己地，全胜末路依刘表。\n竟此身、还复雁门，宁论早。\n篷仙语，开朕兆。\n郇翰洒，增荣耀。\n倚先声风动，了然家晓。\n翘馆每烦尘想□，宾筵更著红妆绕。\n算从前、得此慰初心，於人少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10481, '满江红', '丘', '冠盖吴中，羡来往、风流二老。\n谈笑处、清风满座，倡酬不了。\n琪树相鲜阆里，玉山高并云烟表。\n叹□时、顿有古来无，功名早。\n膺帝眷，符梦兆。\n为国镇，腾光耀。\n更宁容秀野，醉眠清晓。\n麟组已联方面重，衮衣行接天香绕。\n许畸人、巾履奉英游，荣多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10482, '满江红', '丘', '楚甸云收，歌舞地、依然江渚。\n嗟往事、豪华无限，梦回何许。\n翠被那知思玉度，绣谩说为行雨。\n悄不禁、俯仰一凄凉，成千古。\n吴蜀会，襟喉处。\n据胜势，开天府。\n著诗书元帅，谈笑尊俎。\n步障月明翻鼓吹，华榱雾湿披窗户。\n把胜游、都与旧风光，湔尘土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10483, '满江红', '丘', '平楚苍然，烟霭外、飞鸿冥灭。\n身老矣、登临感慨，几时当彻。\n痛饮从教吹帽落，悲歌莫击壶边缺。\n算人生、任运复何为，伤情切。\n功名事，休谩说。\n渠有命，谁工拙。\n且随宜斗健，强酬佳节。\n九节从今知几度，试看镜里头如雪。\n向醉中、赢取万缘空，真蝉脱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10484, '洞仙歌', '丘', '一番好景，近莺花时候。\n才过收灯便晴昼。\n正熊罴、占梦日，戏彩称觞，当此际，须信人间未有。\n光华分瑞节，粉署兰台，谁出如公望郎右。\n气如虹，才吐凤，指掌功名，馀事也，千载犹当不朽。\n待辟国、清边取封侯，看肘後、黄金印悬如斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10485, '洞仙歌', '丘', '江城梅柳，惯得春先处。\n催趁风光上歌舞。\n见九衢、车马流水如龙，喧笑语，罗绮香尘载路。\n欢娱多暇日，尊俎风流，重见承平旧官府。\n有多少、佳丽事，坠珥遗簪，芳径里，瑟瑟珠玑翠羽。\n好惜取、韶华醉连宵，更莫待、收灯酒阑人去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10486, '洞仙歌', '丘', '□□春□，□画□□处。\n十里红莲照歌舞。\n望鳌山天际，宝篆翻空，看未了，涌出珠宫贝宇。\n锦江桥那畔，罗绮重重，曲巷深坊暗香度。\n玉相辉，花并艳，明月随人，归去也，零落珠玑翠羽。\n先如许、风光更元宵，算却好、图将凤城夸去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10487, '洞仙歌', '丘', '花中尤物，欲赋无佳句。\n深染燕脂浅含露。\n被春寒无赖，不放全开，才半吐，翻与留连妙处。\n人间称绝色，倾国倾城，试问太真似花否。\n最娉婷，偏艳冶，百媚千娇，谁道许，须要能歌解舞。\n算费尽、春工到开时，甚却付、连宵等闲风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10488, '洞仙歌', '丘', '丰肌腻体，雅淡仍娇贵。\n不与群芳竞姝丽。\n向琼林珠殿，独占春风，仙仗里，曾奉三宫燕喜。\n低回如有恨，失意含羞，乐事繁华竟谁记。\n应怜我，空老去，无句酬伊，吟未就，不觉东风又起。\n镇独立黄昏怯轻寒，这情绪、年年共花憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10489, '沁园春', '丘', '雨趣轻寒，风作秋声，燕归雁来。\n动天涯羁思，登山临水，惊心节物，极目烟埃。\n客里逢君，才同一笑，何遽言归如此哉。\n别离久，算不应兴尽，却棹船回。\n主人下榻高斋。\n更点检笙歌频宴开。\n便留连不到，迎春见柳，也须小驻，度腊观梅。\n花上盈盈，闺中脉脉，应念胡麻正好栽。\n从教去，正危阑望断，小倚徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10490, '沁园春', '丘', '匏系弥年，江北江南，羡君去来。\n笑山横南浦，朝来爽致，文书堆案，胸次生埃。\n放旷如君，拘縻如我，试问人生谁乐哉。\n真难学，是得留且住，欲去须回。\n何时竹屋茅斋。\n去相傍为邻三径开。\n撰小窗临水，危亭当，随宜有竹，著处须梅。\n坐读黄庭，手援紫，一寸丹田时自栽。\n当馀暇，更与君来往，林下徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10491, '千秋岁', '丘', '梅妆竹外。\n未洗唇红退。\n酥脸腻，檀心碎。\n临溪闲自照，爱雪春犹带。\n沙路晓，亭亭浅立人无对。\n似恨谁能会。\n迟见江头盖。\n和鼎事，终应在。\n落残知未免，韵胜何曾改。\n牵醉梦，随香欲渡三山海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10492, '千秋岁', '丘', '征鸿天外。\n风急惊飞退。\n云彩重，窗声碎。\n初凝铺径絮，渐卷随车带。\n凝望处，巫山秀耸寒相对。\n高卧传都会。\n茅屋倾冠盖。\n空往事，今谁在。\n梅梢春意动，泽国年华改。\n楼上好，与君浩荡浮银海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10493, '千秋岁', '丘', '窥檐窗外。\n酒力冲寒退。\n风絮乱，琼瑶碎。\n凌波争缭绕，点舞相萦带。\n应惬当，凝香燕寝佳人对。\n恰与花时会。\n小阻寻芳盖。\n犹自得，春多在。\n日烘梅柳竞，翠入山林改。\n但只恐，别离恨远如云海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10494, '汉宫春', '丘', '横笛吹梅，记南楼夜月，疏蕊纤枝。\n香尘软红自暖，不怕寒欺。\n人归梦悄，怅凭阑、密约深期。\n身渐老，风流纵在，逢花那似当时。\n东阁占春宜早，甚开迟也似，雪屋疏篱。\n须公彩毫度曲，锦帐题诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10495, '汉宫春', '丘', '闻说瓢泉，占烟霏空翠，中著精庐。\n旁连吹台燕榭，人境清殊。\n犹疑未足，称主人、胸次恢疏。\n天自与，相攸佳处，除今禹会应无。\n选胜卧龙东畔，望篷莱对起，岩壑屏如。\n秋风夜凉弄笛，明月邀予。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10496, '水龙吟', '丘', '蕊珠仙籍标名，绛纱覆玉云霞里。\n銮坡凤掖，丝鸣佩，甘泉近侍。\n濯柳临春，梨照座，绝尘风味。\n记青蒲、夜半论兵，万人惊诵回天意。\n麟组遥临万里。\n谈笑处、江山增丽。\n遐冲坐折，风流馀事，唯应燕喜。\n新筑沙堤，暂占熊梦，恰经长至。\n过佳辰献寿，双旌便好，作朝天计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10497, '念奴娇', '丘', '烛花渐暗，似梦来非梦，今夕何夕。\n帘幕生香人醉里，家住深深密密。\n松客难为，独留无计，此意谁知得。\n相看无语，可怜心绪如织。\n缓辔踏月归来，空馀襟袖，有多情脂泽。\n浅笑轻颦追想处，眼底如今历历。\n著意新词，於人好语，过後应难必。\n今宵酒醒，断肠人正愁寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10498, '扑蝴蝶', '丘', '鸣鸠乳燕。\n春在梨花院。\n重门镇掩。\n沈沈帘不卷。\n纱窗红日三竿，睡鸭馀香一线。\n佳眠悄无人唤。\n谩消遣。\n行云无定，楚雨难凭梦魂断。\n清明渐近，天涯人正远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10499, '祝英台・祝英台近', '丘', '聚春工，开绝艳，天巧信无比。\n旧日京华，应也只如此。\n等闲一尺娇红，燕脂微点，宛然印、昭阳玉指。\n最好是。\n乐岁台府官闲，风流剩欢意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10500, '江城梅花引', '丘', '轻煤一曲染霜纨。\n小屏山。\n有无间。\n宛是西湖，雪後未晴天。\n水外几家篱落晚，半开关。\n有梅花、傲峭寒。\n渐看。\n渐远。\n水弥漫。\n小舟轻，去又还。\n野桥断岸，隐萧寺、□出晴峦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10501, '西河', '丘', '清似水。\n不了眼中供泪。\n今宵忍听唱阳关，暮云千里。\n可堪客里送行人，家山空老春荠。\n道别去、如许易。\n离合定非人意。\n几年回首望龙门，近才御李。\n也知追诏有来时，匆匆今见归骑。\n整弓刀，徒御喜。\n举离觞、饮无味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10502, '夜合花', '丘', '雨过凉生，风来香远，柳塘池馆清幽。\n圆荷万柄，芙蓉困倚轻柔。\n暮霞映，日初收。\n更满意、绿密红稠。\n是牵情处，低回照影，特地娇羞。\n惆怅好景难酬。\n慰家山梦绕，十顷新秋。\n庭空吏散，依然兴在沧州。\n未容短棹轻舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10503, '垂丝钓', '丘', '夕烽戍鼓。\n悲凉江岸淮浦。\n雾隐孤城，水荒沙聚。\n人共语。\n尽向来胜处。\n谩怀古。\n问柳津花渡。\n露桥夜月，吹箫人在何许。\n缭嫱望。\n粉黛成黄土。\n惟有江东注。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10504, '黄河清', '丘', '鼓角清雄占云。\n喜边尘、今度还静。\n一线乍添，长觉皇州日永。\n楼外崇牙影转，拥千骑、欢声万井。\n太平官府人初见，梦熊三占佳景。\n皇恩夜出天闱，云章粲、凤鸾飞动相映。\n宝带万钉，与作今朝佳庆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10505, '蓦山溪', '丘', '风传芳信，晓色便清霁。\n帘幕护春寒，篆香温、笙簧韵美。\n使华容与，星动帝王州，花上脸，柳边眉，竞报占熊喜。\n欢娱好是，玉塞无尘起。\n鞭计小迟留，要长折、遐冲万里。\n传闻有诏，宣室待归来，满，叵罗深，莫负春葱指。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10506, '鹧鸪天', '丘', '怀抱环奇懒叩阍。\n朝阳独赋远人村。\n即看飞下芝封诏，会见趣归金马门。\n今夕饮，拼濡裙。\n一时尊俎尽诗人。\n唯馀阿买真才劣，醉後犹能写八分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10507, '鹧鸪天', '丘', '陆海蓬壶自有山。\n光风霁月未应悭。\n但将歌舞酬佳节，却信阴晴是等闲。\n花照夜，烛烘盘。\n明年公更酒肠宽。\n奉陪黄伞传柑宴，莫望红妆拥座欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10508, '鹧鸪天', '丘', '准拟关门度一秋。\n强扶衰病起相酬。\n不辞酩酊还吹帽，自笑怯露头。\n江日晚，更迟留。\n争传五马足风流。\n论车载酒浑闲事，著笼藏花说未休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10509, '鹧鸪天', '丘', '两两维舟近柳堤。\n菱歌迤逦过前溪。\n曲中自诉衷肠事，岸上行人那得知。\n金齿屐，翠云篦。\n女萝为带蕙为衣。\n惜花贪折归时晚，急桨相呼入翠微。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10510, '鹧鸪天', '丘', '玳瑁宴中见绿珠。\n淡然高韵胜施朱。\n揉兰雾蔷薇浅，半露冰肌玉不如。\n餐秀色，味肤腴。\n轻红端合与为奴。\n只愁宴罢翻成恨，赢得偏怜不似初。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10511, '夜行船', '丘', '水满平湖香满路。\n绕重城、藕花无数。\n小艇红妆，疏帘轻盖，烟柳画桥斜渡。\n恣乐追凉忘日暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10512, '夜行船', '丘', '一舸鸱夷云水路。\n贪游戏、悄忘尘数。\n明月长随，清风满载，那向急流争渡。\n邂逅占星来已暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10513, '夜行船', '丘', '飞朝天云作路。\n长安近、更无程数。\n梧竹当年，丝纶弈世，咫尺凤池平渡。\n青眼相逢何太暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10514, '夜行船', '丘', '万柄荷花红绕路。\n锦连空、望无层数。\n照水旌旗，临风鼓吹，行遍月桥烟渡。\n堪笑年华今已暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10515, '临江仙', '丘', '天上玉卮称万寿，人间湛露初匀。\n种萱堂上阅青春。\n薰风频送喜，同日拜丝纶。\n班在蕊珠仙缀立，等闲历遍燕秦。\n紫皇先付与佳名。\n宜家更宜国，宜子又宜孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10516, '感皇恩', '丘', '时节近中秋，桂花天气。\n忆得熊罴梦呈瑞。\n向来三度，恨被一官萦系。\n今朝称寿，也休辞醉。\n斑衣戏彩，薄罗初试。\n华发双亲剩欢喜。\n功名荣贵，未要匆匆深计。\n一杯先要祝，千百岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10517, '蝶恋花', '丘', '梅子著花当献寿。\n得得天工，有意还知否。\n教在岁寒双雪後。\n长年不羡松筠茂。\n莫厌杯深歌舞奏。\n约略丝纶，正是来时候。\n富贵明年公自有。\n天香公烛黄封酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10518, '蝶恋花', '丘', '鼓吹东方天欲晓。\n打彻伊州，梅柳都开了。\n尽道鄞江春许早。\n使君未到春先到。\n号令只凭花信报。\n旗垒精明，家世临淮妙。\n遥想明年元夕好。\n玉人更著华灯照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10519, '蝶恋花', '丘', '逼砌筠窗围小院。\n日照花枝，疏影重重见。\n金鸭无风香自暖。\n腊寒才比春寒浅。\n画景温温烘笔砚。\n闲把安西，六纸都临遍。\n茗碗不禁幽梦远。\n鹊来唤起斜阳晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10520, '一翦梅', '丘', '潇洒佳人淡淡妆。\n特地凌寒，秀出孤芳。\n雪为肌体练为裳。\n韵处天姿，不御铅黄。\n古样铜壶湿篆章。\n浅浸横斜，净几明窗。\n何妨三弄点苔苍。\n但有疏枝，依旧清香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10521, '天仙子', '丘', '畏暑只嫌秋较晚。\n不道玉楼人渐远。\n此情那解却清凉，肠欲断。\n愁无限。\n安得冰壶还照眼。\n妙舞蹁跹歌宛转。\n走遍京华何处见。\n清眠无梦到西州，馀香浅。\n银钩软。\n唯仗锦书聊自遣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10522, '朝中措', '丘', '晚风斜日折梅花。\n楼外卷残霞。\n领略一城春气，华灯十万人家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10523, '朝中措', '丘', '几回相与叹高才。\n忽报驭风来。\n谁道亟朝天阕，更能同上春台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10524, '朝中措', '丘', '尊前宾主角多才。\n亦许我同来。\n诗思竞翻三峡，酒狂欲拗连台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10525, '菩萨蛮', '丘', '壶边击断歌无节。\n山川一带伤情切。\n依旧石头城。\n夕阳天外明。\n行人谁是侣。\n遗唱今何许。\n对酒转愁多。\n愁多奈酒何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10526, '菩萨蛮', '丘', '秋声夜到秋香园。\n重帘拭卷都开遍。\n只似旧时香。\n更添些子黄。\n绮窗人共赋。\n犹忆分香句。\n别後几回秋。\n见花空复愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10527, '菩萨蛮', '丘', '云林带水山横阁。\n故人去尽添萧索。\n反照射微茫。\n临分愁夕阳。\n传柑当令节。\n连璧朝天阕。\n还有雁西飞。\n慰人新别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10528, '西江月', '丘', '恰好轻篷短棹，绝胜锦缆牙樯。\n一声横笛起微茫。\n十里红莲步障。\n小待山头吐月，何妨说剑杯长。\n更看风露洗湖光。\n水底金盘漾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10529, '西江月', '丘', '明日又还重九，黄昏小雨疏风。\n菊英萸糁一尊同。\n付与今宵号梦。\n寒意梧桐叶上，客愁画角声中。\n小楼何日却从容。\n千里此情应共。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10530, '梅弄影', '丘', '雨晴风定。\n一任春寒逞。\n要勒群芳未醒。\n不废梅花，晚来妆面靓。\n曲阑斜凭。\n水栏临清镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10531, '诉衷情', '丘', '东风罨岸进船难。\n酒醒篆香残。\n不堪客里无绪，那更晚来寒。\n思往事，耿无眠。\n掩屏山。\n夜深人静，何处一声，月子弯弯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10532, '诉衷情', '丘', '素衣苍狗不成妍。\n何意妒蝉娟。\n不知高处难掩，终自十分圆。\n涵万象，独当天。\n照无边。\n乾坤呈露，何况人间，大地山川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10533, '诉衷情', '丘', '芙蓉深径小肩舆。\n相并语徐徐。\n红妆著处迎笑，遮路索踟蹰。\n锦步障，绣储胥。\n绕重湖。\n更添月照，人面花枝，疑在蓬壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10534, '诉衷情', '丘', '十分风味似诗人。\n有些子太清生。\n只应最嫌俗子，消瘦却盈盈。\n风乍静，雪初晴。\n月微明。\n泊然疏淡，莫是无情，作个关情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10535, '锦帐春', '丘', '翠竹如屏，浅山如画。\n小池面、危桥一跨。\n著棕亭临水，宛然郊野。\n竹篱茅舍。\n好是天寒，倍添幽雅。\n正雪意、垂垂欲下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10536, '谒金门', '丘', '风又雨。\n吹面落花红舞。\n把酒不禁春思苦。\n别离闻杜宇。\n叠嶂楼头佳处。\n犹想襞笺容与。\n思入云山便好语。\n莫辞频寄取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10537, '谒金门', '丘', '槐阴绿。\n帘卷翠屏山曲。\n照眼冰壶寒并玉。\n赐衣便雾。\n熊梦又惊初卜。\n好在掖垣梧竹。\n应讶人归犹未速。\n已颁新诏墨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10538, '谒金门', '丘', '罗袖薄。\n玉臂镂花金约。\n起晚欠伸莲步弱。\n倚床娇韵恶。\n独自青楼珠箔。\n怎向日长花落。\n门掩东风春寂寞。\n误人喜鹊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10539, '谒金门', '丘', '花雨润。\n烟锁玉炉香韵。\n笑度华年春不尽。\n寿觞寒食近。\n甲子才周一瞬。\n争羡珠颜青鬓。\n咫尺朝元仙路稳。\n碧云新有信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10540, '好事近', '丘', '空涧落鸣泉，千骑雨霖衣铁。\n金奏欲终人醉，有玉声清越。\n夜深纤手怯轻寒，馀韵寄愁绝。\n玉树梦回何处，但满庭霜月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10541, '好事近', '丘', '整整一冬晴，雨後不论朝夕。\n麦陇救得一半，莫妨他寒食。\n试看天气定乘除，宽更待三日。\n桃李且须宁耐，有无边春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10542, '浣溪沙', '丘', '铁锁星桥永夜通。\n万家帘幕度香风。\n俊游人在笑声中。\n罗绮十行眉黛绿，银花千炬簇莲红。\n座中争看黑头公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10543, '浣溪沙', '丘', '胜子幡儿袅鬓云。\n钗头绝唱旧曾闻。\n江城喜见又班春。\n拂柳和风初有信，欺梅残雪已无痕。\n只应笑语作春温。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10544, '浪淘沙', '丘', '潇洒无湖仙。\n踏遍尘寰。\n吟哦长忆两松闲。\n邂逅天涯还一笑，璧合珠连。\n风采照衰残。\n妙语冷然。\n妓围香暖簇金蝉。\n端为故人情未减，醉玉颓山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10545, '定风波', '丘', '月殿移根入帝乡。\n风流犹是旧时妆。\n猩血染成丹杏脸。\n浓点。\n郁金笼就赭衣黄。\n浪说锦城元自少。\n不道。\n只今何啻五枝芳。\n试问司花谁是主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10546, '卜算子', '丘', '翠被怯轻寒，花气撩幽梦。\n梦蹑飞云驾彩鸾，惊觉花枝动。\n宿酒未全醒，屋角闻晴。\n爱著荼シ彻骨香，嗅了还重□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10547, '柳梢青', '丘', '风佩珊珊。\n云屏曲曲，愁绝春悭。\n无奈馀寒。\n半醒宿酒，御夹成单。\n深沈院落人闲。\n凭阑处、眉颦黛残。\n彩笔慵拈。\n新声微度，兴入云山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10548, '点绛唇', '丘', '花落花开，等闲不管流年度。\n旧游何处。\n浅立空凝伫。\n惊拍栏干，忍见春将暮。\n凭风絮。\n为人飞去。\n散作愁无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10549, '醉花阴', '丘', '碧玉槎桠金粟小。\n山路惊秋老。\n倒倚湿寒烟，似怯秋风，阁泪啼清晓。\n铜壶冷浸宜深窈。\n人试新妆巧。\n云鬓一枝斜，小阁幽窗，是处都香了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10550, '愁倚阑・春光好', '丘', '风雨骤，妒花黄。\n忽斜阳。\n急手打开君会否，是伊凉。\n深深密密传觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10551, '如梦令', '丘', '门外绮罗入绣。\n堂上华灯入昼。\n领略一番春，共醉连宵歌酒。\n今後。\n今後。\n如此遨头少有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10552, '如梦令', '丘', '小小峰峦对起。\n芳树重重相倚。\n清溜绕阶除，聊备一池春水。\n游戏。\n游戏。\n适意随缘足矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10553, '太常引', '丘', '憎人虎豹守天关。\n嗟蜀道、十分难。\n说与沐猴冠。\n这富贵、於人怎谩。\n忘形尊俎，能言桃李，日日在东山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10554, '南歌子', '朱颜', '影落三秋月，寒生六月霜。\n是谁幻出玉。\n乞与一枝和雪、钓漓湘。\n劲节依琳馆，虚心漏草堂。\n笔端元自有雌黄。\n疑是化龙蜚到、葛仙旁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10555, '沁园春', '吕胜己', '月晃西窗，风掀斗帐，晓来梦回。\n见满川惊鹭，长空瑞鹤，联翩来下，翔舞徘徊。\n旋放金磐承积块，更轻撼琼壶撩冻澌。\n毡帏小，近宝炉兽炭，沈水兰煤。\n寒威。\n酒力相欺。\n荐绿蚁霜螯左右持。\n问岁岁祯祥，如何中断，年年梅月，因甚愆期。\n上绀碧楼，城高百尺，看白玉虬龙奔四围。\n纷争罢，正残鳞败甲，天上交飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10556, '醉桃源・阮郎归', '吕胜己', '山翁可是爱登台。\n看云日几回。\n恨无语似谪仙才。\n空教云去来。\n思往事，引深杯。\n长歌感壮怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10557, '醉桃源・阮郎归', '吕胜己', '马蹄西路赏春妍。\n重来十五年。\n好山如带水如环。\n红楼罨画闲。\n人易老，景如前。\n停杯俯逝川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10558, '醉桃源・阮郎归', '吕胜己', '去年手种十株梅。\n而今犹未开。\n山翁一日走千迥。\n今朝蝶也来。\n高树杪，暗香微。\n悭香越恼怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10559, '蝶恋花', '吕胜己', '墙角栽梅分两下。\n夹竹穿松，巧傍柴门亚。\n不似西湖明月夜。\n展开一片江南画。\n老子寻芳心已罢。\n为爱孤高，结约如莲社。\n清静界中观物化。\n憧憧门外驰车马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10560, '蝶恋花', '吕胜己', '天际行云红一缕。\n无尽青山，江水悠悠去。\n更上层楼凭远处。\n凄凉今古悲三楚。\n心事多端谁共语。\n酒醒愁来，望望家何所。\n薄宦漂零成久旅。\n天涯却羡鸿遵渚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10561, '蝶恋花', '吕胜己', '姑射真仙蓬海会。\n驭气乘龙，作意游方外。\n冬後翦花飞素彩。\n腊前陨璞抛团块。\n幂幂锦云相映带。\n川谷林峦，混一乾坤大。\n白玉装成全世界。\n江湖点染微瑕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10562, '蝶恋花', '吕胜己', '屈指瓜期犹渺渺。\n羡子征鞍，去上长安道。\n到得故园春正好。\n桃腮杏脸迎门笑。\n闻道难兄登显要。\n雁子云宵，花萼应同调。\n旧恨新愁须拼了。\n功名趁取方年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10563, '蝶恋花', '吕胜己', '眼约心期常未足。\n邂逅今朝，暂得论心曲。\n忽堕鲛珠红簌簌。\n双眸翦水明如烛。\n可恨匆匆归去速。\n去去行云，望断凄心目。\n何似当初情未熟。\n免教添得愁千斛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10564, '蝶恋花', '吕胜己', '天色沈沈云色赭。\n风扰阴寒，浩荡吹平野。\n万斛珠玑天弃舍。\n长空撒下鸣鸳瓦。\n玉女凝愁金阕下。\n褪粉残妆，和泪轻挥洒。\n欲降尘凡飙驭驾。\n翩翩白凤先来也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10565, '长相思', '吕胜己', '体夭夭。\n步飘飘。\n绶带金泥缕绛绡。\n珑璁趁步摇。\n浅霞消。\n两峰遥。\n斜插层楼金系腰。\n花羞人面娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10566, '长相思', '吕胜己', '展颦蛾。\n抹流波。\n并插玲珑碧玉梭。\n松分两髻螺。\n晓霜和。\n冻轻呵。\n拍罢阳春白雪歌。\n偎人春意多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10567, '长相思', '吕胜己', '冒寒吹。\n访琼姬。\n行到青山遇玉肌。\n凝情欲待谁。\n山疏篱。\n手同携。\n踏月随香清夜归。\n乘欢拨冻醅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10568, '浣溪沙', '吕胜己', '浅著铅华素净妆。\n翩跹翠袖拂云裳。\n傍人作意捧金觞。\n曲度清悲云冉冉，花飞零乱月茫茫。\n梦回人去似高唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10569, '浣溪沙', '吕胜己', '直系腰围鹤间霞。\n双垂项帕凤穿花。\n新妆全学内人家。\n惠性芳心谁得似，饶嗔□恶也还他。\n只消凡事与饶些。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10570, '清平乐', '吕胜己', '红尘久住。\n仙驭凌波去。\n本似行云无定处。\n那更腊残风雨。\n瑶芳片片轻飞。\n但留青子栾枝。\n孤负岁寒幽意，如今却与春宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10571, '清平乐', '吕胜己', '灵心暗属。\n髻垒黄金粟。\n寂静虚堂情不足。\n微步徘徊山麓。\n蕊珠宫里新妆。\n生香全似瑶芳。\n应为莺花留恋，人间暂歇鸾凤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10572, '促拍满路花', '吕胜己', '名花无影迹，寒气日凄凉。\n人间千万树，歇芬芳。\n紫微宫女，仙驭降霓裳。\n名在仙班簿，不属尘凡，洞天密锁云窗。\n遗连宝珥，人间识天香。\n凝寒承雨露，傲冰霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10573, '谒金门', '吕胜己', '花满树。\n两个黄鹂相语。\n恰似碧城双玉女。\n对歌还对舞。\n可惜娟娟楚楚。\n同伴彩云归去。\n居士心如泥上絮。\n那能无恨处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10574, '谒金门', '吕胜己', '嗟久客。\n又见他乡寒食。\n流水断桥春寂寂。\n孤村烟火息。\n白去红飞无迹。\n千树总成新碧。\n醉里伤春愁似织。\n东风欺酒力。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10575, '谒金门', '吕胜己', '芳思切，旧事不堪重说。\n浓露凝香花喷血。\n花心双蛱蝶。\n燕语莺啼都歇。\n又过清明时节。\n记得离歌三两阕。\n未歌先哽咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10576, '谒金门', '吕胜己', '花满树。\n两个黄鹂相语。\n恰似碧城双玉女。\n对歌还对舞。\n可惜娟娟楚楚。\n同伴彩云归去。\n居士心如泥上絮。\n那能无恨处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10577, '谒金门', '吕胜己', '嗟久客。\n又见他乡寒食。\n流水断桥春寂寂。\n孤村烟火息。\n白去红飞无迹。\n千树总成新碧。\n醉里伤春愁似织。\n东风欺酒力。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10578, '谒金门', '吕胜己', '芳思切，旧事不堪重说。\n浓露凝香花喷血。\n花心双蛱蝶。\n燕语莺啼都歇。\n又过清明时节。\n记得离歌三两阕。\n未歌先哽咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10579, '谒金门', '吕胜己', '春又过。\n那更雨摧风挫。\n留得浅红三两朵。\n竹梢烟雾锁。\n把酒对花危坐。\n多病多愁都可。\n舞蝶游蜂迷道左。\n惜春忙似我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10580, '谒金门', '吕胜己', '秋夜静。\n屋上狂风初定。\n两两啼蛄相答应。\n灯蛾摇烛影。\n枕上鸡声遥听。\n起舞良宵偏永。\n明日谩寻弓剑整。\n衰颜重揽镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10581, '谒金门', '吕胜己', '芳信拆。\n漏泄东君消息。\n帝殿宝炉烟未熄。\n龙香飘片白。\n点缀枯梢的。\n疏影摇荡寒碧。\n指与纤纤教自摘。\n枝横云鬓侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10582, '谒金门', '吕胜己', '天气暖。\n开了荼シ一半。\n红日迟迟风拂面。\n阶前花影乱。\n俊雅风流不见。\n定被莺花留恋。\n千尺游丝舒又。\n系人心上线。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10583, '谒金门', '吕胜己', '歌罢奏。\n敛步拂开罗袖。\n宝扇轻摇香汗透。\n软香沾素手。\n小立偎人良久。\n一寸娇波横溜。\n心事未言眉已皱。\n无端催劝酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10584, '南乡子', '吕胜己', '斗笠棹边舟。\n碧水湾头放自流。\n尽日垂丝鱼不上，优游。\n更觉心松奈得愁。\n行客语沧洲。\n笑道渔翁太拙休。\n万事要求须有道，何由。\n教与敲针换曲钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10585, '南乡子', '吕胜己', '纵棹越溪船。\n破浪冲涛到碧湾。\n种就长堤千亩竹，无边。\n插玉屯云满渭川。\n平日乐归田。\n不恋荣华不慕仙。\n得个容身栖隐处，宽闲。\n每日江边理钓竿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10586, '减字木兰花', '吕胜己', '烟云变化。\n面面青山如展画。\n俯对平川。\n野水烟村远接天。\n有时纵目。\n景物繁华观不足。\n月下风头。\n一曲清讴博见楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10587, '瑞鹤仙', '吕胜己', '南州春又到。\n向腊尽冬残，冰姑先报。\n芳心爱春早。\n露生香馥馥，靓妆皎皎。\n诗人最巧。\n道竹外、斜枝更好。\n旋移根引水，浇培松竹，凑成三妙。\n回首。\n当年客里，荆棘途中，幸陪欢笑。\n闲愁似扫。\n记风雪、关山道。\n待飘花结子，和羹煮酒，还我山居送老。\n那青红、浪蕊浮花，尽锄去了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10588, '瑞鹤仙', '吕胜己', '倚阑观四远。\n近有客登临，故相磨难。\n山形欠舒展。\n小峰峦云树，晦明更变。\n江淮楚甸。\n又何曾、分明在眼。\n但临深、自觉身高，未可便名博见。\n休辨。\n吾心乐处，不要他人，共同称善。\n痴儿浅浅。\n因他谩说一遍。\n问还知宴坐，回光收视，大地河山尽现。\n待於中、会得些时，举觞奉劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10589, '瑞鹤仙', '吕胜己', '人生如意少。\n谁得似仙翁，身名俱好。\n亨衢腾踏早。\n驾双旌五马，便居蓬岛。\n闽山蜀道。\n秉玉节、油幢屡到。\n号当今、有脚阳春，处处变愁成笑。\n尤妙。\n晚陪论道。\n密赞调元，虎符重剖。\n去劳自保。\n奉香火、归来了。\n见煌煌甲第，两两龙驹，绿鬓朱颜未到。\n是平生、种德阴功，自天有报。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10590, '瑞鹤仙', '吕胜己', '金枝联玉叶。\n世代有宗英，声华烨烨。\n君侯更超绝。\n抱不群才气，壮图英发。\n津途轨辙。\n□武上、青宵迥别。\n自玉阶、契合君王，拍拍满怀风月。\n奇绝。\n身居萧散，志在功名，眼高天阔。\n恩来魏阕。\n长江上、驻旌节。\n待胡尘有警，纶巾羽扇，谈笑周郎事业。\n恁时看、国倚强宗，诏褒伟烈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10591, '瑞鹤仙', '吕胜己', '残梅飘簌簌。\n看柳上春归，揉条新绿。\n娇莺离幽谷。\n弄弹簧清响，飞迁乔木。\n年华迅速。\n叹浮生、流晖转烛。\n自春来、每每遨游，多办九霞。\n溪北。\n踏青微步，斗草慵眠，锦花褥。\n铅华簇簇。\n歌声妙、间丝竹。\n爱一川好处，高山流水，不减城南杜曲。\n笑平生、卓地无锥，老来富足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10592, '满江红', '吕胜己', '往事千端，都销道、衰翁宦拙。\n今会得、人情物态，尽皆休说。\n广厦尽堪舒笑傲，层楼又见凌空阔。\n试闲思、画戟比衡门，谁优劣。\n尘里事，无休歇。\n楼上事、真奇绝。\n有一川虚旷，万山环列。\n识破古今如旦暮，肯将物我刚分别。\n愿时时、与客坐楼心，谈风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10593, '满江红', '吕胜己', '屈指重阳，有半月、犹零九日。\n且停待、今宵月上，宝轮飞出。\n有客最谙闲况味，无人会得真消息。\n算何须、抵死要荣华，劳心力。\n楼观迥、遥山碧。\n槽窄小，真珠滴。\n随分赏、闲亭别圃，好天良夕。\n篱畔行看金蕊耀，林梢便见瑶芳白。\n玩春来、夏去复秋冬，尘中客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10594, '满江红', '吕胜己', '小立危亭，风惨淡、斜阳满目。\n望渺渺、湘江一派，楚山千簇。\n芳草连云迷远树，断霞散绮飞孤骛。\n感骚人、赋客向来词，愁如束。\n磋远宦、甘微粟。\n惊世事，伤浮俗。\n且经营一醉，未怀荣辱。\n君不见、渊明归去後，一觞自泛东篱菊。\n仰高风、寂寞奠生刍，人如玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10595, '满江红', '吕胜己', '忆惜西来，春已暮、馀寒犹力。\n正迤逦、登山临水，未磋行役。\n云笈偶寻高士传，桃川又访秦人迹。\n向此时、游宦兴阑珊，归无策。\n归计定，归心追。\n惊换岁，犹为客。\n还怅望、家山千里，迥无消息。\n□□不堪泥路远，烟林赖有梅花白。\n为孤芳、领略岁寒情，谁人识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10596, '满江红', '吕胜己', '物理分明，人事巧、元来是拙。\n常自觉、满怀春意，向他谁说。\n剩喜登临频眺望，那知出处成迂阔。\n细闲思、萧散较贪痴，谁为劣。\n高楼上、蝉声歇。\n飞楝外，云行绝。\n见明河星斗，半空森列。\n领略光阴成赋咏，等闲酬唱休旌别。\n要良辰、把酒倩佳宾，嘲风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10597, '满江红', '吕胜己', '拍碎红牙，一声上、梁尘暗落。\n纨扇掩、雏莺叶下，巧呈绰约。\n字字只愁郎幸浅，声声似怨年华薄。\n坐中人、相顾感幽怀，添萧索。\n歌暂阕，杯交错。\n人又去，情怀沪。\n那堪听风雨，渭城吹角。\n去去已离闽岭路，行行渐近滕王阁。\n便无情、山海会相逢，坚心著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10598, '满江红', '吕胜己', '檀扳频催，双拈袖、飞来趁拍。\n锦上、娇抬粉面，浅蛾脉脉。\n鸾观莺窥秋水净，鸿惊凤翥祥云白。\n看妖娆、体态与山精神，天仙谪。\n带紧，弓靴窄。\n花压帽，云垂额。\n□回雪、定拼醉倒，厌厌良夕。\n明日恨随芳草远，回头目断遥山隔。\n料多情、应也念行人，思佳客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10599, '满江红', '吕胜己', '墙下松筠，并手种、花窠尽著。\n试屈指、一年前事，恍然如昨。\n繁杏新荷春夏景，疏梅细菊秋冬约。\n渭川翁、随分小生涯，些官爵。\n分物我，争强弱。\n都作梦，谁先觉。\n好一条平路，是人迷却。\n斑鬓已灰心里事，瘦滕谩卦瓢中药。\n愿当今、四海九州人，同欢乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10600, '满江红', '吕胜己', '雪压山颓，谁撒下、琼花玉蕊。\n寒气凛、沈沈天籁，望迷千里。\n群雀耐寒枯树顶，扁舟独钓平沙觜。\n把江南、图画展开看，都难比。\n台榭远、登临喜。\n楼阁上，歌声起。\n赏时光，居士独怜愁底。\n安得四方寒彦，归吾广厦千间里。\n但今生、此愿得从心，心休矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10601, '满江红', '吕胜己', '惨惨枯梢，初疑似、真酥点滴。\n见深红蒂萼，方认早梅消息。\n粉艳牵连春意动，冰姿照映霜华白。\n伴苍松、修竹似幽人，相寻觅。\n香远近，枝南北。\n幽涧畔，疏篱侧。\n便佣儿贩妇，也知怜惜。\n渭水渔翁方入社，西湖处士成陈迹。\n爱平生、炯炯岁寒心，无今昔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10602, '江城子', '吕胜己', '年年腊後见冰姑。\n玉肌肤。\n点琼酥。\n不老花荣，经岁转敷腴。\n向背稀稠如画里，明月下、影疏疏。\n江南有客问征途。\n寄音书。\n定来无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10603, '江城子', '吕胜己', '一钩新月下庭西。\n绣帘低。\n漏声迟。\n小宴幽欢，依约似当时。\n娇盼注人都不语，眉黛蹙，鬓云。\n街槐阴下玉骢嘶。\n苦相催。\n醉中归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10604, '满庭芳', '吕胜己', '丹浮空，琉璃耀日，上云楼阁眈眈。\n□□居士，燕坐息玄谈。\n十载劳心问道，今悟罢、截日停参。\n凝神处，九苞丹凤，翔舞在山南。\n喃喃。\n成障碍，千经万论，从此休贪。\n且陶陶兀兀，对酒醺酣。\n清兴有时狂放，扁舟上、绿水澄潭。\n渔歌起，从他两岸，齐笑老翁憨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10605, '卜算子', '吕胜己', '人事几时穷，我性偏宜静。\n世上谁无富贵心，到了须由命。\n闲里且偷安，醉後休教醒。\n醉里高歌妙入神，妙处君须听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10606, '卜算子', '吕胜己', '梅蕾破香时，雪後交光夜。\n何处飞来两玉蛾，体态双闲雅。\n纵目碧城楼，劝酒留云榭。\n唱底仙家古道情，分付知音者。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10607, '瑞鹧鸪', '吕胜己', '与君蹑足共凭阑。\n俯视周回四面山。\n目静鲁邦心渺渺，气吞梦泽意闲闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10608, '瑞鹧鸪', '吕胜己', '几时芟棘翦蒿蓬。\n付我天然地一弓。\n乔木茂林森耸耸，遥岑叠嶂碧重重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10609, '感皇恩', '吕胜己', '秋意满江湖，雨轻风熟。\n上水扁舟片帆速。\n远山低岸，贪看浅红深绿。\n不知回柁尾，沧湾宿。\n推枕起来，举杯相属。\n休叹风尘为微禄。\n几年行路，但觉登临不足。\n且翻楚调入，清江曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10610, '临江仙', '吕胜己', '忽忆裴公台上去，远空秋气棱棱。\n万山一水秀还明。\n此时三楚客，何意续骚经。\n爱竹子犹参杖履，能诗候喜同登。\n赓酬不尽古今情。\n清风生白尘，侧月照疏星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10611, '好事近', '吕胜己', '风景好樵川，郭外三洲烟渚。\n过尽古今清逸，奈天公不与。\n地灵人意会符同，留待烟霞侣。\n一棹轻舟开岸，弄滩声风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10612, '好事近', '吕胜己', '宿面浅匀妆，梅粉旋生春色。\n绣草冠儿宫样，系丁香新缬。\n凤檀槽上四条弦，轻□□□。\n恰似寻阳江畔，话长安时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10613, '鹊桥仙', '吕胜己', '银花千里，玉阶三尺，远近高低一色。\n天公今岁被诗催，特地放、冬前四白。\n梅梢竹外，频频轻撼，嫌乱瑶芳素质。\n耐寒相对不胜清，毡帐底、偎红未得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10614, '木兰花慢', '吕胜己', '残红吹尽了，换新绿、染疏林。\n正杜宇催归，行人贪路，天气轻阴。\n江亭旧游宴处，但瑶山、数叠晚云深。\n犹忆佳人敛黛，为予别泪盈襟。\n而今。\n旅况难禁。\n逢胜概、懒登临。\n念景熟难忘，情多易感，取次关心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10615, '木兰花慢', '吕胜己', '无言凭燕几，爱香袅、博山炉。\n正暖日辉辉，晴云淡淡，千里平芜。\n田家尽收刈了，见牛羊、下垅暝烟孤。\n闻说丰年景致，老农击壤呜呜。\n狂夫。\n素乏良图。\n从上策、赋归欤。\n有千亩松筠，三洲风月，尽随吾初。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10616, '木兰花慢', '吕胜己', '对轩辕古镜，照华发、短刁骚。\n念壮岁心情，平生志气，可笑徒劳。\n云中谩夸魏尚，请休论、定远说班超。\n总是黄粱一梦，怎如尘外逍遥。\n蛮徭。\n洞入云宵。\n算无分、到仙曹。\n愿归隐闽山，来临渭水，葺个云巢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10617, '木兰花慢', '吕胜己', '朝天门外路，路坦坦、走瑶京。\n悔年少狂图，争名远宦，为米孤征。\n星星。\n半凋鬓发，事千端、回首只堪惊。\n居士新来悟也，渭川小隐初成。\n临清。\n巧创幽亭。\n真富贵、享安荣。\n有猿鸟清讴，松篁森卫，桧柏双旌。\n蛙鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10618, '木兰花慢', '吕胜己', '平生花恨少，又那得、酒中愁。\n自禅板停参，蒲团悟罢，身世忘忧。\n南柯旧时太守，尽当年、富贵即时休。\n莫羡痴儿小子，心心念念封侯。\n优游。\n取次凝眸。\n春浩浩、思悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10619, '柳梢青', '吕胜己', '叶下云行，亭皋风静，凉雨丝丝。\n断雁孤鸣，寒蛩相应，寂寂书帏。\n蒲团纸帐兰台。\n梦不到、邯郸便回。\n蚁穴荣华，人间功业，都恼人怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10620, '鹧鸪天', '吕胜己', '竹树萧萧屋数椽。\n平湖漫漫纳通川。\n有时竹杖芒鞋至，醉著山光水色间。\n成小隐，未经年。\n功名夷路稳加鞭。\n逢时且数中书考，他日还寻独乐园。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10621, '鹧鸪天', '吕胜己', '记得追游故老家。\n红莲幕府在长沙。\n放船桥口秋随月，走马春园夜踏花。\n思往昔，谩咨磋。\n几番魂梦转天涯。\n葵轩老子今何在，岳麓风雩噪暮鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10622, '鹧鸪天', '吕胜己', '一夜春寒透锦帏。\n满庭花露起多时。\n垒金梳子双双耍，铺翠花儿袅袅垂。\n人去後，信来稀。\n等闲屈指数归期。\n门前恰限行人至，喜鹊如何圣得知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10623, '鹧鸪天', '吕胜己', '日日楼心与画眉。\n松分蝉翅黛云低。\n象牙白齿双梳子，驼骨红纹小棹篦。\n朝暮宴，浅深杯。\n更阑生怕下楼梯。\n徐娘怪我今疏懒，不及庐郎年少时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10624, '鹧鸪天', '吕胜己', '纸帐虚明好醉眠。\n博山轻袅水沉烟。\n了知世上都如梦，须信壶中别有天。\n知我者，为君言。\n道人有个好因缘。\n丹成有日归云路，且最梅花作地仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10625, '点绛唇', '吕胜己', '满路梅花，为谁开遍春风萼。\n短亭萧索。\n草草传杯酌。\n送子先归，我羡辽东鹤。\n他年约。\n瘦藤芒履。\n共子同丘壑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10626, '点绛唇', '吕胜己', '日月无根，循环常共天难老。\n世间扰扰。\n只见闲烦恼。\n满酌高吟，便是今生了。\n还知道。\n旧时官好。\n几个新华表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10627, '点绛唇', '吕胜己', '一叶扁舟，浮家来向江边住。\n这回归去。\n作个渔樵侣。\n不挂征帆，也莫遥双橹。\n天涯路。\n云山烟渚。\n总是留人处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10628, '点绛唇', '吕胜己', '桂子飘香，江南秋老霜风作。\n自怜漂泊。\n几度伤离索。\n孤馆迢迢，满引村醪酌。\n情无著。\n好音难托。\n又失黄花约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10629, '点绛唇', '吕胜己', '瑞气盈门，神仙谪下看看到。\n已知消耗。\n弧矢呈祥了。\n种德阴功，自有多男报。\n还知道。\n果生蓬岛。\n不比人间早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10630, '鱼游春水', '吕胜己', '林梢听布谷。\n郭外舒怀仍快目。\n平田浩荡，虢虢泉鸣暗谷。\n香稻吐芒针棘细，秀麦遥风波浪绿。\n山童野老，意亲情热。\n我待休官弃禄。\n屏迹幽闲安退缩。\n渭三千亩修篁，绀玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10631, '霜天晓角', '吕胜己', '晓来风作。\n病怯春衫薄。\n郭外溪山明秀，红尘里、自拘缚。\n村酒频斟酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10632, '虞美人', '吕胜己', '疏风摆撼芙蓉沼。\n垅上梅英小。\n谁家姊妹去寻芳。\n粉面云鬟参杂、汉宫妆。\n邯郸奏罢宫中乐。\n邂逅同杯酌。\n老来花酒制颓龄。\n为爱嫣然娇靥、斗盈盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10633, '虞美人', '吕胜己', '年年冬後心情快。\n常是留宾醉。\n尊前笑靥粲金钿。\n更有半黄枨橘、满堆磐。\n人人爱道休官去。\n总是闲言语。\n古今文士与贤才。\n为甚独高陶令、赋归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10634, '虞美人', '吕胜己', '横波清翦西湖水。\n黛拂吴山翠。\n藕丝衫子水沈香。\n坐久冰肌玉骨、起微凉。\n金徽泛柳听佳句。\n叠叠胎仙舞。\n曲终松下小磐桓。\n风露泠泠、直欲便骖鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10635, '菩萨蛮', '吕胜己', '遥山几叠天边碧。\n故教遮断天涯客。\n楼倚暮云端。\n春风罗袖寒。\n与君千里别。\n共此关山月。\n皓月一般明。\n君心怎敢凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10636, '菩萨蛮', '吕胜己', '岭猿啸罢千山碧。\n小庵虚室团团白。\n庵在小山头。\n从来少客游。\n道人方打坐。\n举袖来迎我。\n问我此来因。\n拈花与道人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10637, '南歌子', '吕胜己', '湛露凉亭馆，香风散芰荷。\n晚来月色似金波。\n间绿围红、同伴雪儿歌。\n年少风流足，情深欢会多。\n佳人月下拜嫦娥。\n不似隔年牛女、望星河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10638, '八声甘州', '吕胜己', '自秋来、多病意无聊，不作渭山游。\n想兰菊凋疏，松筠茂密，亭馆清幽。\n四望遥山万叠，叠叠翠光浮。\n人道蓬莱岛，仿佛瀛洲。\n居士心迷丘壑，念迂疏老懒，难觅封侯。\n看才能成事业，且自抽头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10639, '如梦令', '吕胜己', '花上娇莺哑咤。\n著色江南图画。\n可惜好春风，有酒无人同把。\n拚舍。\n拚舍。\n独醉好天良夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10640, '如梦令', '吕胜己', '王谢堂前旧燕。\n毕竟情高意远。\n只恐宠恩深，後会不教人见。\n深劝。\n深劝。\n不枉追欢一遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10641, '如梦令', '吕胜己', '梅雪渐当时候。\n访问全无消耗。\n凭杖小阳春，催取南枝先到。\n然後。\n然後。\n雪月交光同照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10642, '西江月', '吕胜己', '日日齐眉举案，年年劝酒持觥。\n今年著意寿卿卿。\n幼稚绵绵可庆。\n官冷未尝贫贱，家肥胜似功名。\n所为方便合人情。\n管取前途更永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10643, '渔家傲', '吕胜己', '长记浔阳江上宴。\n庚公楼上凭阑遍。\n北望淮山连楚甸。\n真伟观。\n中原气象依稀见。\n漂泊江湖波浪远。\n依然身在蛮溪畔。\n愁里不知时节换。\n春早晚。\n杜娟声里飞花满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10644, '渔家傲', '吕胜己', '闻道西洲梅已放。\n几时乘兴同寻访。\n稚子携壶翁策杖。\n徐徐往。\n青山绿水皆堪赏。\n满月当空川晃晃。\n却呼艇子遥双桨。\n几阵浓香新酝酿。\n波溶漾。\n宛然身在西湖上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10645, '渔家傲', '吕胜己', '特为梅花来渭水。\n有人折得横梢至。\n粉毖香悭春意未。\n多应是。\n江南信息争先寄。\n水绿山青风日美。\n此时正惬幽人意。\n驱使风光佳句里。\n□满纸。\n却将旧日诗词比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10646, '杏花天', '吕胜己', '当年悔我抛生计。\n趁升斗、蛮乡远地。\n谁知事向无心起。\n回首邯郸梦里。\n风雪满□□□□。\n最好处、吴头楚尾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10647, '感皇恩', '唐致政', '君欲问予年，八十有七。\n百岁十分尚留一。\n世间滋味，尝尽酸碱苦涩。\n时今倒食蔗、无甜汁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10648, '浣溪沙', '楼锷', '夏半阳乌景最长。\n小池不断藕花香。\n电影雷声催急雨，十分凉。\n芡剥明珠随意嚼，瓜分琼玉趁时尝。\n双枪堂深新酿好，且传觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10649, '洞仙歌', '林外', '飞梁压水，虹影澄清晓。\n橘里渔村半烟草。\n今来古往，物是人非，天地里，唯有江山不老。\n雨巾风帽。\n四海谁知我。\n一剑横空几番过。\n按玉龙、嘶未断，月冷波寒，归去也、林屋洞天无锁。\n认云屏烟障是吾庐，任满地苍苔，年年不扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10650, '西江月', '梁安世', '南国秋光过二，宾鸿未带初寒。\n洞中驼褐已嫌单。\n洞口犹须挥扇。\n夕照千峰互见，晴空万象都还。\n羡他渔艇系澄湾。\n枕玻璃一片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10651, '望海潮', '黄岩叟', '梅天雨歇，柳堤风定，江浮画纵横。\n瀛女弄萧，冯夷伐鼓，云间凤咽鼍鸣。\n波面走长鲸。\n卷怒涛来往，搅碎沧溟。\n两岸游人笑语，罗绮间簪缨。\n灵均逝魄无凭。\n但湘沅一水，到底澄清。\n菰黍万家，丝桐五彩，年年吊古深情。\n锦帜片霞明。\n使操舟妙手，翻动心旌。\n向晚鱼龙戏罢，千里浪花平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10652, '多丽', '富ノ', '淡云收、晓来春满湘中。\n柳如烟、花枝如糁，万红千翠织浓。\n照帘旌、微穿丽日，动罗幕、轻转香风。\n天上良辰，人间淑景，生贤和气显殊锺。\n映时表、南山北斗，相并两穹崇。\n须知道、英明罕此，文武谁同。\n奉慈亲、承颜戏彩，更闻吉梦占熊。\n扫蛮氛、遂清三楚，定徐方、行策元功。\n趣召遄归，康时佐主，指挥谈笑虏巢空。\n寿觞举、器舟斟海，不用水精锺。\n休辞醉，千龄会遇，美事重重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10653, '水调歌头', '邵怀英', '香亲紫荷陌，和气满长沙。\n黄堂庶寝春晓，风软碧幢遮。\n天遣武夷仙客，来掌元戎金印，千骑拥高牙。\n收了绿林啸，喜动紫薇花。\n青藜杖，鸿宾略，属公家。\n长城应与借一，天语屡褒嘉。\n且伴彩衣行乐，指日丝纶飞诏，归去凤池夸。\n千岁祝眉寿，福海浩无涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10654, '水龙吟', '赵长卿', '韶华迤逦三春暮。\n飞尽繁红无数。\n多情为与，牡丹长约，年年为主。\n晓露凝香，柔条千里，轻盈清素。\n最堪怜，玉质冰肌婀娜，江梅谩休争妒。\n翠蔓扶疏隐映，似碧纱笼罩，越溪游女。\n从前爱惜娇姿，终日愁风怕雨。\n夜月一帘，小楼魂断，有思量处。\n恐因循易嫁，东风烂熳，暗随春去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10655, '念奴娇', '赵长卿', '小春时候，见早梅吐玉，裁琼妆白。\n点点枝头光照眼，恼损柔肠情客。\n暗里芳心，出群标致，经岁成疏隔。\n如今风韵，何人依旧冰雪。\n冷艳潇洒天然，香姿肯易许，游蜂狂蝶。\n夜半黄昏担带了，多少清风明月。\n宋玉虽悲，元超虽恨，见了千愁歇。\n东君还许，有情取次攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10656, '满庭芳', '赵长卿', '爆竹声飞，屠苏香钿，华堂歌舞催春。\n百年消息，经半已凌人。\n念我功名冷落，又重是、一岁还新。\n惊心事，安仁华鬓，年少已逡巡。\n明知生似寄，何须苦苦，役慕蹄轮。\n最难忘、通经好学沈沦。\n况是读书万卷，辜负他、此志难伸。\n从今去，灯窗勉进，云路岂无因。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10657, '花心动', '赵长卿', '风软寒轻，暗香飘、扑面无限清楚。\n乍淡乍浓，应想前村，定是早梅初吐。\n马儿行过坡儿下，危桥外、竹梢疏处。\n半斜露。\n花花蕊蕊，灿然满树。\n一晌看花凝伫。\n因念我西园，玉英真素。\n最是系心，婉娩精神，伴得水云仙侣。\n断肠没奈人千里，无计向、钗头频窥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10658, '踏莎行', '赵长卿', '柳暗披风，桑柔宿雨。\n一番绿遍江头树。\n莺花已过苦无多，看看又是春归去。\n病酒情怀，光阴如许。\n闲愁俏没安排处。\n新来著意与兜笼，身心苦役伊知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10659, '南歌子', '赵长卿', '春色烘衣暖，宫梅破鼻香。\n尽驱和气入兰堂。\n又是轻云微雨、下巫阳。\n酒带欢情重，醺醺气味长。\n晚来拂拭略梳妆。\n笑指一钩新月、上迥廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10660, '蝶恋花', '赵长卿', '宿雨新晴天色好。\n李夭桃，一霎都开了。\n燕子归来深院悄。\n柳绵铺迳无人扫。\n咫尺莺花还又老。\n绿入闲阶，只有青青草。\n参揣前期谁可表。\n此情不语知多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10661, '鹧鸪天', '赵长卿', '镂玉裁琼莫比香。\n娉婷枝上春光。\n风流别有千般韵，割舍昏沈入醉乡。\n蜂共蝶，尽乾忙。\n檀心知未肯寻常。\n从来诗苦人消瘦，乞与幽窗富锦囊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10662, '鹧鸪天', '赵长卿', '蜂蜜酿成花已飞。\n海棠次第雨胭脂。\n园林检点春归也，只有萦风柳带垂。\n情默默，恨依依。\n可人天气日长时。\n东风恰好寻芳去，何事驱弛作别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10663, '江神子・江城子', '赵长卿', '年年长见傲寒林。\n压群英。\n有馀清。\n曾被芳心，红日恼诗情。\n玉质暗香无限意，偏婉娩，尽轻盈。\n今年潇洒照歧亭。\n更芳馨。\n也峥嵘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10664, '南歌子', '赵长卿', '春思浓如酒，离心乱似绵。\n一川芳草绿生烟。\n客里因循、重过艳阳天。\n屈指归期近，愁眉泪洒然。\n无端还被此情牵。\n为问桃源、还有再逢缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10665, '临江仙', '赵长卿', '忆昔去年花下饮，团蛮争看酴。\n酒浓花艳两相宜。\n醉中尝记得，裙带写新诗。\n还是春光惊已暮，此身犹在天涯。\n断肠无奈苦相思。\n忧心徒耿耿，分付与他谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10666, '一丛花', '赵长卿', '柳莺啼晓梦初惊。\n香雾入帘清。\n胭脂淡注宫妆雅，似文君、犹带春酲。\n芳心婉娩，媚容绰约，桃李总消声。\n相如春思正萦萦。\n无奈惜花情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10667, '青玉案', '赵长卿', '天涯目断江南路。\n见芳草，迷风絮。\n绿暗花梢春几许。\n小桃寂寞，海棠零乱，飞尽胭脂雨。\n子规声里山城暮。\n月挂西南梦回处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10668, '醉蓬莱', '赵长卿', '是三春已暮，浪蕊彤残，牡丹零落。\n独殿清和，有佳名芍药。\n浅浅芳业，绣幢鼎鼎，更艳香绰约。\n浑似扬州，画楼卷起，翠帘红幕。\n倚槛轻盈，万娇千媚，故整霞裙，笑花寂寞。\n太守风流，拥笙歌围著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10669, '雨中花慢', '赵长卿', '宿霭凝阴，天气未晴，峭寒勒住群葩。\n倚栏无语，羞辜负年华。\n柳媚梢头翠眼，桃蒸原上红霞。\n可堪那、尽日狂风荡荡，细雨斜斜。\n东君底事，无奈薄幸，著意残害莺花。\n惟是我，惜春情重，说奈咨磋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10670, '蓦山溪', '赵长卿', '晓来雨霁。\n弱柳摇新翠。\n丽日媚东风，正不暖不寒天气。\n幽禽弄舌，花上诉春光，高一饷，低一饷，清圆还碎。\n那知时势。\n春亦元无意。\n草木自敷荣，似人生、功名富贵。\n我咱谙分，随有亦随无，不妒富，不憎贫，歌酒闲游戏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10671, '蝶恋花', '赵长卿', '芍药开残春已尽。\n红浅香乾，蝶子迷花阵。\n阵是清和人正困。\n行云散後空留恨。\n小字金书频与问。\n意曲心诚，未必他能信。\n千结柔肠愁寸寸。\n钿钗几日重相近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10672, '虞美人', '赵长卿', '江梅虽是孤芳早。\n争似酴好。\n凡红飞尽草妻迷。\n婀娜枝头才见、细腰肢。\n玉容消得仙源惜。\n满架香堆白。\n檀心应共酒相宜。\n割舍花前猛饮、倒金卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10673, '虞美人', '赵长卿', '冰塘浅绿生芳草。\n枝上青梅小。\n柳眉愁黛为谁开。\n似向东君、喜见故人来。\n碧桃销恨犹堪爱。\n妃子今何在。\n风光小院酒尊同。\n向晚一钩新月、落花风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10674, '江神子・江城子', '赵长卿', '小溪清浅照孤芳。\n蕊珠娘。\n暗传香。\n春染粉容，清丽傅宫妆。\n金缕翠蝉曾记得，花密密、过雕墙。\n而今冷落水云乡。\n念平康。\n转情伤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10675, '醉蓬莱', '赵长卿', '是平分秋色，梦草池塘，暖风帘幕。\n昨夜三台，灿天边芝角。\n自是君家，庆流泽远，降生申崧岳。\n厚德温良，高才粹雅，渊源学博。\n何事丹墀，尚淹阔步，未许中原，少勤方略。\n且对笙歌，醉黄金错落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10676, '临江仙', '赵长卿', '春事犹馀十日，吴蚕早已三眠。\n多情忍对落花前。\n酴飘暖雪，荷叶媚晴天。\n香淡无心浸酒，绿浮可意邀船。\n时光堪恨也堪怜。\n单衣三月暮，歌扇一番圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10677, '青玉案', '赵长卿', '去年社日东风里。\n向三径、开桃李。\n脆管危弦随意起。\n绿阴红影，暖香繁蕊，伴我醺醺醉。\n今年社日空垂泪。\n客舍看花甚情意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10678, '南歌子', '赵长卿', '枝上红飞尽，梢头绿已匀。\n游丝柳絮媚青春。\n向晚暖风帘幕、练光新。\n春已匆匆去，那堪话别情。\n刘郎几日便登程。\n告你觅些欢笑、送行人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10679, '醉落魄・一斛珠', '赵长卿', '麦畦匀绿。\n枝头屑屑飞梅玉。\n伤心何事人南北。\n断尽回肠，忍听阳关曲。\n倚窗青荫亭亭竹。\n好风敲动声相续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10680, '点绛唇', '赵长卿', '密雨随风，咋来一夜檐声溜。\n奈何。\n官路梅花瘦。\n赋得多情，怕到春时候。\n如今一病非因酒。\n试问君知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10681, '点绛唇', '赵长卿', '春到垂杨，嫩黄染就金丝软。\n丽晴新暖。\n涌翠千山远。\n为甚年年，眉向东风展。\n闲消遣。\n欲归犹懒。\n渔笛天将晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10682, '点绛唇', '赵长卿', '轻暖轻寒，赏花天气春将半。\n柳摇金线。\n求友莺相唤。\n玉腕蛾眉，意眼频频眄。\n歌喉软。\n玉卮受劝。\n一醉应相拼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10683, '点绛唇', '赵长卿', '夜雨如倾，满溪添涨桃花水。\n落红铺地。\n枝上堆浓翠。\n去年如今，常伴酴醉。\n今年里。\n离家千里。\n独猛东风泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10684, '点绛唇', '赵长卿', '啼鸟喃喃，恨春归去春谁管。\n日和风暖。\n绿暗闲庭院。\n还忆当年，绮席新相见。\n人已远。\n水流云散。\n空结多情怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10685, '鹧鸪天', '赵长卿', '弱质纤姿俪素妆。\n水沈山麝郁幽香。\n直疑姑射来天上，要恼人间傅粉郎。\n简酿酒，枕为囊。\n更馀风味胜糖霜。\n肯如红紫空姚冶，谩惹游蜂戏蝶忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10686, '鹧鸪天', '赵长卿', '玉容应不羡梅妆。\n檀心特地赛炉香。\n半臧密叶墙头女，勾引酡颜马上郎。\n樽乏酒，且倾囊。\n蟹螯糟熟似黏霜。\n一年光景浑如梦，可惜人生忙处忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10687, '鹧鸪天', '赵长卿', '洗尽铅华不著妆。\n一般真色自生香。\n飘飘何处凌波女，故故相迎马上郎。\n寻谱谍，发诗囊。\n绝胜梅萼嫁冰霜。\n故山寒食依然在，句引东坡旅兴忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10688, '鹧鸪天', '赵长卿', '镂玉裁琼学靓妆。\n不须沈水自然香。\n好随梅蕊妆宫额，肯似桃花误阮郎。\n羞傅粉，贱香囊。\n何劳傲雪与凌霜。\n新来句引无情眼，拼为东风一晌忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10689, '鹧鸪天', '赵长卿', '绰约肌肤巧样妆。\n风流元自有清香。\n未应傅粉疑平叔，却笑荷花似六郎。\n浮蚁瓮，入诗囊。\n学人消瘦怯风霜。\n午窗一枕庄周梦，甘作花心粉蝶忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10690, '探春令', '赵长卿', '去年元夜，正钱塘，看天街灯烛。\n闹蛾儿转处，熙熙语笑，百万红妆女。\n今年肯把轻辜负。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10691, '小重山', '赵长卿', '清晚窗前杜宇啼。\n游仙惊梦醉，断魂迷。\n起来窗下看盆池。\n伤春去，消瘦不胜衣。\n柳陌记年时。\n行云音信杳、与心违。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10692, '小重山', '赵长卿', '绿示阴阴春已休。\n群花飘尽也，不胜愁。\n游丝飞絮两悠悠。\n迷芳草，日暖雨初收。\n深院小迟留。\n好香烧一炷，细烟浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10693, '菩萨蛮', '赵长卿', '梅花有意舒香粉。\n舒香已得先春信。\n香与露华清。\n露浓愁杀人。\n酒多愁愈重。\n此意谁能共。\n泪湿染衣斑。\n夜霜金缕寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10694, '菩萨蛮', '赵长卿', '梅花枝上东风软。\n朝来吹散真香远。\n雅淡有馀清。\n客心和泪倾。\n美人临别夜。\n月晃灯初。\n玉枕小屏山。\n眉尖曾细看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10695, '水龙吟', '赵长卿', '烟姿玉骨尘埃外，看自有神仙格。\n花中越样风流，曾是名标清客。\n月夜香魂，雪天孤艳，可堪怜惜。\n向枝间且作，东风第一，和羹事、期他日。\n闻道春归未识。\n问伊家、却知消息。\n当时恼杀林逋，空绕团栾千百。\n横管轻吹处，馀香散、阿谁偏得。\n寿阳宫、应有佳人，待与点、新妆额。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10696, '水龙吟', '赵长卿', '苇绡开得仙花，就中最有佳人似。\n香肌胜雪，千般揉缚，禁他风雨。\n缟夜精神，繁春标致，忍教孤负。\n怅潘郎去後，河阳满县，知他是、谁为主。\n多谢文章吏部。\n遇衔杯、不曾轻许。\n应知这底，无言情绪，难为分付。\n吹遍春风，耀残明月，总伤心处。\n待闲亭夜永，游人散後，作飞仙去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10697, '水龙吟', '赵长卿', '天教占得如簧，巧声乍啭千娇媚。\n金衣衬著，风流模样，於中可是。\n红杏香中，绿杨阴处，多应饶你。\n向黄昏、苦苦娇啼怨别，那堪更、东风起。\n别有诗肠鼓吹。\n未关他、等闲俗耳。\n双柑斗酒，当时曾是，高人留意。\n南国春归，上阳花落，止添憔悴。\n念啼声欲碎，何人解作留春计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10698, '水龙吟', '赵长卿', '淡烟轻霭，望中乍歇凝晴昼。\n才惊一霎催花，还又随风过了。\n清带梨梢，晕含桃脸，添春多少。\n向海棠点点，香红染遍，分明是、胭脂透。\n无奈芳心滴碎，阻游人、踏青携手。\n檐头线断，空中丝乱，才晴却又。\n帘幕闲垂处，轻风送、一番寒峭。\n正留君不住，潇潇更下黄昏後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10699, '胜胜慢・声声慢', '赵长卿', '浓芳满地，秀色连天，和烟带雨萋萋。\n几许芳心，还解报得春晖。\n当时谢郎梦里，似殷勤、传与新诗。\n却为甚、动长门怨感，南浦伤离。\n追想天涯行客，应解拥车轮，步步相随。\n惆怅如丝，正是欲断肠时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10700, '胜胜慢・声声慢', '赵长卿', '金垂烟重，雪扬风轻，东风惯得多娇。\n秀色依依，偏应绿水朱楼。\n腰肢先来太瘦，更眉尖、惹得闲愁。\n牵情处，是张郎年少，一种风流。\n别後长堤目断，空记得当时，马上墙头。\n细雨轻烟，何处夕系扁舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10701, '南歌子', '赵长卿', '黯霭阴云覆，滂沱急雨飞。\n洗残枝上乱红稀。\n恰是退花天气、困人时。\n向晓春酲重，偎人起较迟。\n薄罗初见拭轻衣。\n笑拭新妆、须要剪酴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10702, '浣溪沙', '赵长卿', '寒食风霜最可人。\n梨花榆火一时新。\n心头眼底总宜春。\n薄暮归吟芳草路，落红深处鹧鸪声。\n东风疏雨唤愁生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10703, '浣溪沙', '赵长卿', '柳老抛绵春已深。\n夹衣初试晓寒轻。\n别离无奈此时情。\n先自愁怀容易感，不堪闻底子规声。\n西楼料得数回程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10704, '浣溪沙', '赵长卿', '不愤江梅喷暗香。\n春前腊後正凄凉。\n霜风雪月忍思量。\n斜倚幽林如有恨，玉鳞飞後转堪伤。\n时人那解识孤芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10705, '朝中措', '赵长卿', '别来无事不思量。\n霜日最凄凉。\n凝想倚栏干处，攒眉应为萧郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10706, '昭君怨', '赵长卿', '隔叶乳鸦声软。\n啼断日斜影转。\n杨柳小腰肢。\n画楼西。\n役损风流心眼。\n眉上新愁无限。\n极目送云行。\n此时情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10707, '桃源忆故人', '赵长卿', '夜来一夜东风暖。\n春到桃腮柳眼。\n对景可堪肠断。\n强把愁眉展。\n花期惹起归期念。\n前事从头忖遍。\n凝想水遥山远。\n空结相思怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10708, '长相思', '赵长卿', '花飞飞。\n柳依依。\n帘卷东风日正迟。\n社前双燕归。\n药栏东，药栏西。\n记得当时素手携。\n弯弯月似眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10709, '感皇恩', '赵长卿', '景物一番新，熙熙时候。\n小院融和渐长昼。\n东君有意，为怜纤腰消瘦。\n软风吹破眉间皱。\n袅袅枝头，轻黄微透。\n舞到春深转清秀。\n锦囊多感，又更新来伤酒。\n断肠无语凭栏久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10710, '探春令', '赵长卿', '笙歌间错华筵启。\n喜新春新岁。\n菜传纤手青丝细。\n和气入、东风里。\n幡儿胜儿都姑。\n戴得更戏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10711, '菩萨蛮', '赵长卿', '赤栏干外桃花雨。\n飞花已觉春归去。\n柳色碧依依。\n浓阴春昼迟。\n海棠红未破。\n匀糁胭脂颗。\n风雨也相饶。\n应怜粉面娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10712, '丑奴儿・采桑子', '赵长卿', '牡丹已过酴谢，飞尽繁花。\n浓翠啼鸦。\n绿水桥边卖酒家。\n年时携手寻春去，满引流霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10713, '浣溪沙', '赵长卿', '帘卷轻风怜小春。\n荷枯菊悴正愁人。\n江梅喜见一枝新。\n料得主人偏爱惜，也应冰雪好精神。\n故园桃李莫生嗔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10714, '清平乐', '赵长卿', '楚梅娇小。\n好是霜天晓。\n宿酒恼人香暗绕。\n浸影碧波池沼。\n生成素淡芳容。\n不须抹黛匀红。\n准拟凝成阴结子，莫教枉费春工。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10715, '清平乐', '赵长卿', '绮疏新晓。\n学语雏莺巧。\n烟暖瑶阶梧叶老。\n满地东风芳草。\n少年不合风流。\n偿他酒债花愁。\n望断绿芜春去，销魂懒上层楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10716, '更漏子', '赵长卿', '日彤彤，风荡荡。\n帘外柳花飞扬。\n红有限，绿无穷。\n雨晴芳径中。\n肠寸结。\n萦离别。\n还是去年时节。\n春暮也，子归啼。\n伤春三月时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10717, '诉衷情', '赵长卿', '檀心刻玉几千重。\n开处对房栊。\n黄昏淡月笼艳，香与酒争浓。\n宜轻素，鄙轻红。\n思无穷。\n化工著意，南南北北，一种东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10718, '小重山', '赵长卿', '枝上杨花糁玉尘。\n晚风扶起处，雪轻盈。\n扑人点点细无声。\n谁能惜，撩乱满江城。\n忍泪未须倾。\n十年追往事，叹流莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10719, '蝶恋花', '赵长卿', '绿尽烧痕芳草遍。\n不暖不寒，切莫辜良宴。\n罨画屏风开羽扇。\n薄罗衫子仙衣练。\n晚雨小池添水面。\n戏跃鳞，又向波心见。\n持酒伊听声宛转。\n樽前唱彻昭阳怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10720, '鹧鸪天', '赵长卿', '梁上双双海燕归。\n故人应不寄新诗。\n柳梧阴里高还下，帘幕中间去复回。\n追盛事，忆乌衣。\n王家巷陌日沈西。\n兴亡无限惊心语，说与时人总不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10721, '鹧鸪天', '赵长卿', '谡谡东风作雨寒。\n无言独自凭栏干。\n绿肥红瘦春归去，恨逼愁侵酒怎宽。\n追往事，惜花残。\n残花往事总相关。\n风光台上伤心处，此意人休作等闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10722, '探春令', '赵长卿', '新元才过，渐融和气，先到帘帏。\n谩闲绕、柳径花蹊里。\n探看试、春来未。\n年时曾把春抛弃。\n与春光陪泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10723, '探春令', '赵长卿', '数声回雁。\n几番疏雨，东风回暖。\n甚今年、立得春来晚。\n过人日、方相见。\n缕金幡胜教先办。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10724, '探春令', '赵长卿', '冰檐垂箸，雪花飞絮，时方严肃。\n向寻常摇曳，凡花野草，怎生敢夸红绿。\n江梅孤洁无拘束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10725, '探春令', '赵长卿', '而今风韵，旧时标致，总皆奇绝。\n再相逢还是，春前腊後，粉面凝香雪。\n芳心自与群花别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10726, '探春令', '赵长卿', '雕墙风定，绮窗烛，沈吟独坐。\n料雪霜深处，司花神女，暗里焚百和。\n恼人一阵香初过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10727, '探春令', '赵长卿', '龟纱隔雾，绣帘钩月，那时曾见。\n照影儿、觑了千回百转。\n素艳明於练。\n柔肠堆满相思愿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10728, '探春令', '赵长卿', '疏篱横出，绿枝斜露，笑盈盈地。\n悄一似、初睹东邻女，有无限、风流意。\n半开折得琼瑰蕊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10729, '探春令', '赵长卿', '冰澌池面。\n柳摇金线，春光无限。\n问梅花底事，收香藏蕊，到此方舒展。\n百花头上俱休管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10730, '探春令', '赵长卿', '溪桥山路。\n竹篱茅舍，凄凉风雨。\n被摧残沮挫，精神依旧，无奈相思苦。\n东君故与收拾取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10731, '探春令', '赵长卿', '雨孱风瘦，雪欺霜妒，时光牢落。\n怎奈向、天与孤高出众，一任傍人恶。\n凡花且莫相嘲谑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10732, '探春令', '赵长卿', '楼头月满。\n栏干风度，有人肠断。\n为多情、役得神魂撩乱。\n又被梅萦绊。\n对花沈醉应须拼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10733, '探春令', '赵长卿', '清江平淡，暗香潇洒，满林风露。\n渐枝上、也学杨花柳絮。\n轻逐春归去。\n东君著意勤遮护。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10734, '宝鼎现', '赵长卿', '嚣尘尽扫，碧落辉腾，元宵三五。\n更漏永、迟迟停鼓。\n天上人间当此遇。\n正年少、尽香车宝马，次第追随士女。\n看往来、巷陌连甍，簇起星逑无数。\n政简物阜清闲处。\n听笙歌、鼎沸频举。\n灯焰暖、庭帏高下，红影相交知几户。\n恣欢笑、道今宵景色，胜前时几度。\n细算来、皇都此夕，消得喧传今古。\n排备绮席成行，炉喷袅、沈檀轻缕。\n睹遨游彩仗，疑是神仙伴侣。\n欲飞去、恨难留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10735, '青玉案', '赵长卿', '梅黄又见纤纤雨。\n客里情怀两眉聚。\n何处烟村啼杜宇。\n劝人归去，早思家转，听得声声苦。\n利名萦绊何时住。\n恼乱愁肠成万缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10736, '烛影摇红', '赵长卿', '梅雪飘香，杏花开艳燃春昼。\n铜驼烟淡晓风轻，摇曳青青柳。\n海燕归来未久。\n向雕梁、初成对偶。\n日长人困，绿水池塘，清明时候。\n帘幕低垂，麝煤烟喷黄金兽。\n天涯人去杳无凭，不念东阳瘦。\n眉上新愁压旧。\n要消遣、除非酒。\n酒醒人静，月满南楼，相思还又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10737, '念奴娇', '赵长卿', '银蟾光满，弄馀辉、冷浸江梅无力。\n缓引柔条浮素蕊，横在闲窗虚壁。\n染纸挥毫，粉涂墨晕，不似今端的。\n天然造化，别是一般，清瘦踪迹。\n今夜翠葆堂深，梦回风定，因月才相识。\n先自离愁，那更被、晓角残更催逼。\n曙色将分，轻阴移尽，过眼难寻觅。\n江南图上，画工应为描得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10738, '念奴娇', '赵长卿', '玉龙声杳，正瑶台曲舞，香山初彻。\n褪粉掐酥千万颗，满地平铺银雪。\n草褥香茵，苔钱买住，留待黄昏月。\n有人妆罢，对花凝伫愁绝。\n休更恨落羞开，东君情分，自古多离别。\n好把芳心收拾取，与个和羹人说。\n摆脱风尘，消停酸苦，终有成时节。\n浮花浪蕊，到头不是生活。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10739, '阮郎归', '赵长卿', '和风暖日小层楼。\n人闲春事幽。\n杏花深处一声鸠。\n花飞水自流。\n寻旧梦，续扬州。\n眉山相对愁。\n忆曾和泪送行舟。\n清江古渡头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10740, '虞美人', '赵长卿', '东风卷尽辛夷雪。\n逆旅清明节。\n黄昏烟雨失前山。\n陟遍朱栏、酒噤不禁寒。\n归来谁护衣篝火。\n倒拥文鸳卧。\n可堪连夜子规啼。\n唤得春归、人却未成归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10741, '念奴娇', '赵长卿', '兰枯菊槁。\n是返魂香入，江南春早。\n谷静林幽人不见，梦与梨花颠倒。\n雪刻檀心，玉匀丰颊，妆趁严锺晓。\n海山么凤，绿衣何处飞绕。\n竹外孤袅一枝，古今解道，只有东坡老。\n莫倚广平心似铁，闲把珠玑挥扫。\n桃李舆台，冰霜宾客，月地还凄悄。\n暗香消尽，和羹心事谁表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10742, '玉楼春', '赵长卿', '江村百六春强半。\n拍拍池塘春水满。\n风团柳絮舞如狂，雨压橘花香不散。\n阴阴巷陌闲庭院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10743, '谒金门', '赵长卿', '风又雨。\n满地残红无数。\n花不能言莺解语。\n晓来啼更苦。\n把酒东皋日暮。\n抵死留春春去。\n拟倩杨花寻去处。\n杨花无定据。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10744, '菩萨蛮', '赵长卿', '杨花飞尽莺声涩。\n杜娟唤得春归急。\n病酒起来迟。\n娇慵懒画眉。\n宝奁金鸭冷。\n重唤烧香饼。\n著意炼龙涎。\n纤纤手烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10745, '画堂春', '赵长卿', '小亭烟柳水溶溶。\n野花白白红红。\n恼人池上晚来风。\n吹损春容。\n又是清明天气，记当年、小院相逢。\n凭栏幽思几千重。\n残杏香中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10746, '画堂春', '赵长卿', '夜来暖趁海棠时。\n脸边匀透胭脂。\n乱红娇影困垂垂。\n睡损杨妃。\n多少肉温香润，朱唇绿鬓相偎。\n晚风何苦过台西。\n断送春归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10747, '卜算子', '赵长卿', '春水满江南，三月多芳草。\n幽鸟闲将远恨来，一一都啼了。\n不学鸳鸯老。\n回首临平道。\n人道长眉似远山，山不似长眉好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10748, '念奴娇', '赵长卿', '水边篱落独横枝，冉冉风烟岑寂。\n踏雪寻芳村路永，竹屋西头遥识。\n蕙草香销，小桃红未，醉眼惊春色。\n离愁何处，断肠无限陈迹。\n憔悴素脸朱唇，天寒日暮，倚栏干无力。\n岁晚天涯驿使远，难寄江南消息。\n自笑平生，怜清惜淡，故园曾亲植。\n百花虽好，问还有恁标格。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10749, '菩萨蛮', '赵长卿', '肩舆晓踏江头月。\n月华冷浸消残雪。\n雪月照疏篱。\n梅花三两枝。\n人怜花淡薄。\n花恨人牢落。\n不似那回时。\n醺醺醉玉肌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10750, '点绛唇', '赵长卿', '开尽梅花，雪残庭户春来早。\n岁华偏好。\n只恐催人老。\n惟有诗情，犹被花枝恼。\n金樽倒。\n共成欢笑。\n终是清狂少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10751, '鹧鸪天', '赵长卿', '手种梅花三四株。\n要看冰霜照清。\n朝来几朵茅檐下，竹外江头恐不如。\n凝玉面，吐香须。\n莫嫌孤瘦渐丰馀。\n化工不肯辜人意，做底欢娱报答渠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10752, '鹧鸪天', '赵长卿', '只惯娇痴不惯愁。\n离情浑不挂眉头。\n可怜恼尽尊前客，却趁东风上小舟。\n真个去，不留。\n落花流水一春休。\n自怜不及春江水，随到滕王阁下流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10753, '瑞鹤仙', '赵长卿', '海棠花半落。\n正蕙圃风生，兰亭香扑。\n青英暝池阁。\n任翻红飞絮，游丝穿幕。\n情怀易著。\n奈宿酲、情绪正恶。\n叹韶光渐改，年华荏苒，旧欢如许。\n追念凭肩盟誓，枕臂私言，尽成离索。\n记得忘却。\n当时事，那时约。\n怕灯前月下，得见则个，厌厌只待窥著。\n问新来、为谁萦牵，又还瘦削。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10754, '临江仙', '赵长卿', '过尽征鸿来尽燕，故园消息茫然。\n一春憔悴有谁怜。\n怀家寒食夜，中酒落花天。\n见说江头春浪渺，殷勤欲送归船。\n别来此处最萦牵。\n断篷南浦雨，疏柳断桥烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10755, '一丛花', '赵长卿', '阶前春草乱愁芽。\n尘暗绿窗纱。\n钗盟镜约知何限，最断肠、湓浦琵琶。\n南渚送船，西城折柳，遗恨在天涯。\n夜来魂梦到侬家。\n一笑脸如霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10756, '柳梢青', '赵长卿', '桃杏舒红。\n迟迟暖日，媚景芳浓。\n紫燕穿帘，香泥著地，未乳巢空。\n千山万水重重。\n烟雨里、王维画中。\n芳草斜阳，无人江渡，蓑笠渔翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10757, '花心动', '赵长卿', '绿水平湖，浸芙渠烂锦，艳胜倾国。\n半敛半开，斜立斜，好似困娇无力。\n水仙应赴瑶池宴，醉归去、美人扶策。\n驻香驾、拥波心媚容，倩妆颜色。\n曾见苕川澄碧。\n匀粉面、溪头旧时相识。\n翠被绣，彩扇香篝，度岁杳无消息。\n露痕滴尽风前泪，追往恨、悠悠踪迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10758, '鼓笛慢・水龙吟', '赵长卿', '暑风吹雨仙源过，深院静，凉於水。\n莲花郎面，翠幢红粉，烘人香细。\n别院新番，曲成初按，词清声脆。\n奈难堪羞涩，朦松病眼，无心听，笙簧美。\n还记当年此际。\n叹飘零、萍踪千里。\n楚云寂寞，吴歌凄切，成何情意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10759, '念奴娇', '赵长卿', '晚妆才罢，见栊丝匀玉，一团娇秀。\n趁得年光，长是向、金谷无花时候。\n不比莺莺，不关燕燕，不似章台柳。\n清凉无汗，雪肌潇洒难偶。\n好是斜月黄昏，瑶阶钿砌，百媚初含酒。\n恼杀多情香喷喷，双靥盈盈回首。\n倾国倾城，千金莫惜，兰蕙应难友。\n沈郎拚了，为花一味销瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10760, '满庭芳', '赵长卿', '竹斜梢，荷倾馀沥，晚风初到南池。\n雨收池上，高柳乱蝉嘶。\n冉冉莲香满院，夕阳映、红浸庭闱。\n凉生到，碧瓜破玉，白酒酌玻璃。\n思量，浮世事，枯荣辱宠，欢喜忧悲。\n算劳心劳力，得甚便宜。\n粗有田园笑傲，拣些个、朋友追随。\n好时景，莫教挫过，撞著醉如泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10761, '满庭芳', '赵长卿', '红藕洲塘，黄葵庭院，渚风时动清。\n素纨轻，凉色爽征衣。\n一一光阴日月，关情处、前事难期。\n空凝想，临鸾有恨，谁与画新眉。\n刀头，心寸折，江南厚约，惟是侬知。\n念默歌停舞，冷落屏帏。\n何日朱笼鹦鹉，迎门报、金勒东归。\n罗弦管，合欢声里，烂醉玉东西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10762, '好事近', '赵长卿', '山路乱蝉吟，声隐茂林修竹。\n恰值快风收雨，递荷香芬馥。\n破除愁虑酒宜多，把酒再三嘱。\n遥想溪亭潇洒，称晚凉新浴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10763, '虞美人', '赵长卿', '二乔姊妹新妆了。\n照水盈盈笑。\n多情相约五湖游。\n似向群花丛里、骋风流。\n丁香枝上千千结。\n怨惹相思切。\n争如特地嫁薰风。\n吐尽芳心点点、绛唇红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10764, '醉蓬莱', '赵长卿', '正火山槐夏，黛叶湘枝，荔子新摘。\n千里驰驱，荐仙源佳席。\n浪比龙晴，未输崖蜜，灿烂然红摘。\n满贮雕盘，纤纤素手，丹苞新擘。\n梨栗粗疏，带酸橘柚，凡品多般，总羞标格。\n何以浓香，洗烦襟仙液。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10765, '醉蓬莱', '赵长卿', '见浴兰才罢，拂掠新妆，巧梳云髻。\n初试生衣，恰三裁贴体。\n艾虎宜男，朱符辟恶，好储祥纳吉。\n金凤钗头，应时戴了，千般戏。\n那更殷勤，再三祝愿，斗巧合欢，彩丝缠臂。\n刻玉香蒲，泛金觥迎醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10766, '踏莎行', '赵长卿', '树影将圆，林梢不动。\n汗珠挹透纱衣重。\n荷风忽送雨飞来，晚凉习习生幽梦。\n珠箔高钩，瑶琴闲弄。\n移樽邀取蝉娟共。\n今宵拼著醉眠呵，夜香闻早添金凤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10767, '醉落魄・一斛珠', '赵长卿', '淡妆浓抹。\n西湖人面两奇绝。\n菖蒲角黍家家节。\n水戏鱼龙，十里画帘揭。\n凌波无限生尘袜。\n冰肌莹彻香罗雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10768, '阮郎归', '赵长卿', '东城沙软马蹄轻。\n清和雨乍晴。\n柳阴曲径泣流莺。\n凄凉不忍听。\n休苦怨，莫悲鸣。\n何须雨泪倾。\n但将巧语写心诚。\n东君肯薄情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10769, '蝶恋花', '赵长卿', '乱叠青钱荷叶小。\n浓绿阴阴，学语雏莺巧。\n小树飞花芳径草。\n堆红衬碧於中好。\n梅子弄黄枝上早。\n春已归时，戏蝶游蜂少。\n细把新词才和了。\n鸡声已唤纱窗晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10770, '鹧鸪天', '赵长卿', '新晴水暖藕花红。\n烘人暑意晚来浓。\n共携纤手桥东路，杨柳青青一径风。\n深翠里，艳香中。\n双莺初下蕊珠宫。\n月笼粉面三更露，凉透萧萧一梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10771, '江神子・江城子', '赵长卿', '彩云飞尽楚天空。\n碧溶溶。\n一帘风。\n吹起荷花，香雾喷人浓。\n明月凄凉多少恨，恨难许，我情锺。\n相思魂梦几时穷。\n洞房中。\n忆从容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10772, '新荷叶', '赵长卿', '冷彻蓬壶，翠幢鼎鼎生香。\n十顷玻璃，望中无限清凉。\n遮风掩日，高低衬、密护红妆。\n阴阴湖里，羡他双浴鸳鸯。\n猛忆西湖，当年一梦难忘。\n折得曾将盖雨，归思如狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10773, '临江仙', '赵长卿', '帘幕轻风洒洒，园林绿荫垂垂。\n楝花开遍麦秋时。\n雨深芳草渡，蝴蝶正慵飞。\n憔悴三春心事，风流一弄金衣。\n韶光老尽起深思。\n日长庭院里，徙倚听催归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10774, '朝中措', '赵长卿', '荷钱浮翠点前溪。\n梅雨日长时。\n恰是清和天气，雕鞍又作分携。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10775, '减字木兰花', '赵长卿', '柳丝摇翠。\n翠幄笼阴无限意。\n不绊行舟。\n只向江边绊客愁。\n月明风细。\n分付一江流去水。\n娇眼伤春。\n谁是章台欲折人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10776, '卜算子', '赵长卿', '执手送行人，水满荷花浦。\n旧恨新愁不忍论，泪压潇潇雨。\n行计已匆匆，无计留伊住。\n一点相思万里心，谁怕关山阻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10777, '临江仙', '赵长卿', '柳上斜阳红万缕，烘人满院荷香。\n晚凉初浴略梳妆。\n冠儿轻替枕，衫子染莺黄。\n蓄意新词轻缓唱，殷勤满捧瑶觞。\n醉乡日月得能长。\n仙源正闲散，伴我老高唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10778, '雨中花令', '赵长卿', '绿锁窗纱梧叶底。\n麦秋时、晓寒慵起。\n宿酒厌厌，残香冉冉，浑似那时天气。\n别日不堪频屈指。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10779, '画堂春', '赵长卿', '湖光乘雨碧连天。\n绕堤映、草色芊芊。\n舞风杨柳欲撕绵。\n依依起翠烟。\n还是春风客路，对花时、空负蝉娟。\n暮寒楼阁碧云间。\n罗袖成斑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10780, '浣溪沙', '赵长卿', '露挹新荷扑鼻香。\n恼人更漏乡浪浪。\n柳梳斜月上纱窗。\n小醉耳边私语好，五云楼阁羡刘郎。\n酒阑烛暗断回肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10781, '西江月', '赵长卿', '水满平塘过雨，洗妆红褪芙蕖。\n绿荷美影荫龟鱼。\n无限闲中景趣。\n潇洒高堂邃馆，那堪左右图书。\n凌云赋得似相如。\n多少风流态度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10782, '卜算子', '赵长卿', '闲路踏花来，闲逐清和云。\n来去虽然总是闲，有多少伤心处。\n红碧好池塘，朱绿深庭户。\n随分山歌社舞中，且乐陶陶趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10783, '清平乐', '赵长卿', '水乡清楚。\n襟袖销袢暑。\n绰约藕花初过雨。\n出浴杨妃无语。\n葡萄满酌玻璃。\n已拼一醉酬伊。\n浪卷夕阳红碎，池光飞上帘帏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10784, '清平乐', '赵长卿', '清和时候。\n底事休交瘦。\n满酌流霞看舞袖。\n步步锦红皱。\n六么舞到虚催。\n几多深意徘徊。\n拼了明朝中酒，为伊更饮琼杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10785, '浣溪沙', '赵长卿', '雾透龟纱月映栏。\n麦秋天气怯衣单。\n楝花风软晓来寒。\n懒起麝煤重换火，暖香浓处敛眉山。\n眼波横浸绿云鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10786, '浣溪沙', '赵长卿', '薄雾轻阴酿晓寒。\n起来宿酒尚酡颜。\n柳莺何事苦关关。\n新恨旧愁俱唤起，当年紫袖看弓弯。\n泪和梅雨两潸潸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10787, '鹧鸪天', '赵长卿', '牙领番腾一线红。\n花儿新样喜相逢。\n薄纱衫子轻笼玉，削玉身材瘦怯风。\n人易老，恨难穷。\n翠屏罗幌两心同。\n既无闲事萦怀抱，莫把双蛾皱碧峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10788, '菩萨蛮', '赵长卿', '方池新涨蒲萄绿。\n晓来雨过花如浴。\n测测杏园风。\n梢头一捻红。\n危楼愁独倚。\n一寸心千里。\n宿酒尚微醺。\n懒装堆髻云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10789, '西江月', '赵长卿', '稳唱巧翻新曲，灵犀密意潜通。\n荷花香染晚来风。\n相对恍然如梦。\n有恨眉尖皱碧，多情酒晕生红。\n此愁不是等闲浓。\n应为仙源倾动。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10790, '浣溪沙', '赵长卿', '睡起风帘一派垂。\n失巢燕子傍人飞。\n日长深院委香泥。\n绿笋出林翻锦箨，红葵著雨褪胭脂。\n微风度竹入轻衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10791, '蝶恋花', '赵长卿', '忆昔临平山下过。\n无数荷花，照水无纤。\n短艇直疑天上坐。\n醉眠花里香无那。\n雨红妆娇娜娜。\n脉脉含情，欲向风前破。\n莫道晚来风景可。\n青房著子千千颗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10792, '浣溪沙', '赵长卿', '密叶阴阴翠幄深。\n梅黄弄雨正频频。\n榴花照眼一枝新。\n缑岭有人今毓粹，飞凫不日严宸。\n一尊敬寿太夫人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10793, '浣溪沙', '赵长卿', '雨过西湖绿涨平。\n环湖密柳暗藏莺。\n麦秋天气似清明。\n对策有人新切直，逢春不日尽施行。\n扁舟未用速归程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10794, '青玉案', '赵长卿', '结堂雄占云烟表。\n万象争呈巧。\n老木参天溪四绕。\n乱山横秀，一湖澄照。\n天付阴晴好。\n夜空唤客清樽倒。\n明月飞来上林杪。\n凉满九宵风露浩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10795, '青玉案', '赵长卿', '恍如辽鹤归华表。\n阅尽人间巧。\n天乞一堂山对绕。\n微波不动，岸巾时照。\n照见星星好。\n舞风荷盖从倒。\n碧树生凉自天杪。\n谁识元龙胸次浩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10796, '谒金门', '赵长卿', '今夜雨。\n扫尽一番袢暑。\n宛似潇潇鸣远浦。\n短蓬何日去。\n自漉床头玉醑。\n清兴有谁知否。\n反笑功名能几许。\n槐宫非浪语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10797, '念奴娇', '赵长卿', '江城向晓，被西风揉碎，一天丝雨。\n乱织离愁千万缕，多少关心情绪。\n促织鸣时，木犀开後，秋色还如许。\n那堪飘泊，异乡千里孤旅。\n应想帘幕闲垂，西楼东院，齐把归期数。\n记得临歧收泪眼，执手叮咛言语。\n白酒红萸，黄花绿橘，莫等闲辜负。\n朱笼归骑，甚时先报鹦鹉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10798, '念奴娇', '赵长卿', '花王有意，念三秋寂寞，凄凉天气。\n木落烟深山雾冷，不比寻常风味。\n勒驾闲来，柳蒲憔悴，无限惊心事。\n仙容香艳，俨然春盛标致。\n雅态出格天姿，风流酝藉，羞杀岩前桂。\n寄语芙蓉临水际，莫骋芳颜妖丽。\n一朵凭栏，千花退避，恼得骚人醉。\n等闲风雨，更休愁容易。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10799, '声声慢', '赵长卿', '金风玉露，绿橘黄澄，商秋爽气飘逸。\n南斗腾光，应是间生贤出。\n照人紫芝眉宇，更仙风、谁能俦匹。\n细屈指，到小春时候，恰则三日。\n莫论早年富贵，也休问文章，有如椽笔。\n尧舜逢君，启沃定知多术。\n而今且张锦幄，麝煤泛、暖香郁郁。\n华堂里，听瑶琴轻弄，水仙新律。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10800, '瑞鹤仙', '赵长卿', '西风苹末起。\n动院落清秋，新凉如水。\n纤歌遏云际。\n正美人翻曲，阳春轻丽。\n兰衣玉佩。\n拥南斗、光中一醉。\n有邦人、万口同声，赞叹我公恺悌。\n百里。\n年丰谷稔，事简刑清，颂声盈耳。\n鹏程九万，摹空展、垂天翼。\n定丹书飞下，彤墀归去，秘略家传小试。\n看封留、亘古功名，未容退避。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10801, '满庭芳', '赵长卿', '雨洗长空，风清云路，又还毕备佳期。\n夜凉如水，一似去秋时。\n渺渺银河浪静，星桥外、香霭。\n霞轺举，鸾骖鹊驭，稳稳过飞梯。\n经年，成间阻，相逢无语，应喜应悲。\n怕玉绳低处，依旧睽离。\n和我愁肠万缕，嫦娥怨、底事来迟。\n广寒殿，春风桂魄，首与慰相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10802, '水调歌头', '赵长卿', '今夕知何夕，秋色正平分。\n嫦娥此际，底事越样好精神。\n已是天高气肃，那更清风洒洒，万里没纤云。\n把酒临风饮，酒面起红鳞。\n歌一曲，舞一曲，捧金樽。\n从他妄想，老兔憔悴正纷纷。\n我为桂花拚醉，明日扶头不起，颠倒白纶巾。\n天若知人意，夜雨莫倾盆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10803, '蓦山溪', '赵长卿', '满城风雨，又是重阳近。\n黄菊媚清秋，倚东篱、商量开尽。\n红萸白酒，景物一年年，人渐远，梦还稀，赢得无穷恨。\n钗分镜破，一一关方寸。\n强醉欲消除，醉魂醒、凄凉越闷。\n鸳鸯宿债，偿了恶因缘，当时事，只今愁，斑尽安仁鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10804, '洞仙歌', '赵长卿', '芰荷已老，菊与芙蓉未。\n一夜秋容上岩桂。\n间蘩芜、嫩黄染就琼瑰，开未足，已早香传十里。\n从前分付处，明月清风，不用斜晖照佳丽。\n叹浮花，徒解咤，浅白深红，争似我、潇洒堆金积翠。\n看天阔、秋高露华清，见标致风流，更无尘意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10805, '虞美人', '赵长卿', '西风明月临台榭。\n准拟中秋夜。\n一年等待到而今。\n为甚今宵陡顿、却无情。\n娥应怨孤眠苦。\n取次为云雨。\n素蟾特地暗中圆。\n未放清光容易、到仙源。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10806, '醉蓬莱', '赵长卿', '正金风无露。\n玉宇生凉，楚郊无暑。\n催起行人，恰槐黄时序。\n万里晴宵，几人争睹，快鹏抟一举。\n明月圆时，素秋中夜，凌云新赋。\n那更渊源，词锋轻锐，笔阵纵横，学通今古。\n誉望飞腾，是麟宗文虎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10807, '洞仙歌', '赵长卿', '黄花满地，庭院重阳後。\n天气凄清透襟袖。\n动离情、最苦旅馆萧条，那更堪、风剪凋零飞柳。\n临歧曾执手。\n祝付叮咛，知会别来念人否。\n为多情，生怕分离，只知道、准拟别来消瘦。\n甚苦苦、促装赴归期，要趁他、橘绿澄黄时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10808, '夏云峰', '赵长卿', '露华清。\n天气爽、新秋已觉凉生。\n朱户小窗，坐来低按秦筝。\n几多妖艳，都总是、白雪馀声。\n那更、玉肌肤韵胜，体段轻盈。\n照人双眼偏明，况周郎、自来多病多情。\n把酒为伊，再三著意须听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10809, '感皇恩', '赵长卿', '碧水浸芙容，秋风楚岸。\n三岁光阴转头换。\n且留都骑，未许匆匆分散。\n更持杯酒殷勤劝。\n休作等闲，别离人看。\n且对笙歌醉须拼。\n如君才调，掌得玉堂词翰。\n定应不久劳州县。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10810, '瑞鹤仙', '赵长卿', '败荷擎沼面，红叶舞林梢，光阴何速。\n碧天静如水，金风透帘幕，露清蝉伏。\n追思往事，念当年、悲伤宋玉。\n渐危楼向晚，魂销处、倚遍阑干曲。\n凝目。\n一霎微雨，塞鸿声断，酒病相续。\n无情赏处，金井梧，东篱菊。\n渐兰桡归去，银蟾满夜，水村烟渡怎宿。\n负伊家、万愁千恨，甚时是足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10811, '临江仙', '赵长卿', '万里西风吹去旆，满城无奈离情。\n甘棠也似戴公深。\n晓来风露里，叶叶做秋声。\n十载两番遗爱在，须知愁满宜春。\n楚天低处是归程。\n夕阳疏雨外，莫遣乱蝉鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10812, '临江仙', '赵长卿', '枫叶白苹秋未老，晚风吹泛轻。\n青山沥沥水茫茫。\n情随流水远，恨逐暮山长。\n一点相思千点泪，眼前无限情伤。\n佳人犹自捧离觞。\n阳关休唱彻，唱彻断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10813, '鹧鸪天', '赵长卿', '亭树萧萧生暮凉。\n安排清梦到胡床。\n楚山楚水秋江外，江北江南客恨长。\n苹渚冷，橘汀黄。\n断魂残梦更斜阳。\n欲将此日悲秋泪，洒向江天哭楚狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10814, '蓦山溪', '赵长卿', '木犀开了。\n还是生辰到。\n一笑对西风，喜人与、花容俱好。\n寿筵开处，香雾扑帘帏，笙簧奏，星河晓，拼取金倒。\n当年仙子，容易抛蓬岛。\n月窟与花期，要同向、人间不老。\n拈枝弄蕊，此乐几时穷，一岁里，一番新，莫与蟠桃道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10815, '醉落魄・一斛珠', '赵长卿', '伤离恨别。\n愁肠又似丁香结。\n不应斗顿音书绝。\n烟水连天，何处认红叶。\n残更数尽银缸灭。\n边城画角声呜咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10816, '好事近', '赵长卿', '初过菊花天，饯送月宫仙客。\n丹桂拒霜浓淡，映眉间黄色。\n红裙歌夜饮离觞，努力赴劲敌。\n惟愿捷书来到，道一声都得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10817, '菩萨蛮', '赵长卿', '倚楼小小穿针女。\n秋光点点蛛丝雨。\n今夕是何宵。\n龙车乌鹊桥。\n经年谋一笑。\n岂解令人巧。\n不用问如何。\n人间巧更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10818, '卜算子', '赵长卿', '凉夜竹堂空，小睡匆匆醒。\n庭院无人月上阶，满地栏干影。\n何处最知秋，风在梧桐井。\n夜半骖鸾弄玉笙，露湿衣裳冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10819, '点绛唇', '赵长卿', '蓼岸西风，小舟江上渔歌唱。\n倚栏凝想。\n幂幂云垂帐。\n好事因循，寂寞闲惆怅。\n如何向。\n又来心上。\n空向高亭望。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10820, '好事近', '赵长卿', '淅淅蓼花风，怪道晓来凄恻。\n翻见密云抛雨，动一山秋色。\n从前多感为伤时，无处顿然寂。\n个事已寒前约，只晚阴凝碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10821, '品令', '赵长卿', '情难托。\n离愁重、悄愁没处安著。\n那堪更、一叶知秋後，天色儿、渐冷落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10822, '小重山', '赵长卿', '一夜西风响翠条。\n碧纱窗外雨，长凉飙。\n朝来绿涨水平桥。\n添清景，疏韵入芭蕉。\n坐久篆烟销。\n多情人去後，信音遥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10823, '采桑子', '赵长卿', '去年岩桂花香里，著意非常。\n月在东厢。\n酒与繁华一色黄。\n今年杯酒流连处，银烛交光。\n往事难忘。\n待把真诚问阿郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10824, '朝中措', '赵长卿', '柳林幂幂暮烟斜。\n秋水浅平沙。\n楼外碧天无际，紫山断处横霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10825, '朝中措', '赵长卿', '征帆一缕转弯斜。\n惊鹭起沙汀。\n点点随风逆上，满江飞破残霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10826, '洞仙歌', '赵长卿', '广寒宫殿，不在人间世。\n分付天香与岩桂。\n向西风、遥曳处，数十里知闻，金翠里、别有出群标致。\n东园盛事。\n五亩浓阴芘。\n必以诗书取荣贵。\n况一门，三秀才，未足钦崇，那更是、异姓同居兄弟。\n更细把、繁英祝娥，看禹浪飞腾，定应来岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10827, '似娘儿', '赵长卿', '橘绿与澄黄。\n今小春、已过重阳。\n晚来一霎霏微雨，单衣渐觉，西风冷也，无限情伤。\n孤馆最凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10828, '蝶恋花', '赵长卿', '一梦十年劳忆记。\n社燕宾鸿，来去何容易。\n宿酒半醒便午睡。\n芭蕉叶映纱窗翠。\n衬粉泥书双合字。\n鸾凤鸳鸯，总是双双意。\n已作吹箫长久计。\n鸳衾空有中宵泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10829, '夜行船', '赵长卿', '泪眼江头看锦树。\n别离又还秋暮。\n细水浮浮，轻风冉冉，稳送扁舟去。\n归去江山应得助。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10830, '清平乐', '赵长卿', '鸿来燕去。\n又是秋光暮。\n冉冉流年嗟暗度。\n这心事还无据。\n寒窗露冷风清。\n旅魂幽梦频惊。\n何日利名俱赛，为予笑下愁城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10831, '清平乐', '赵长卿', '秋容眼界。\n随寓浑堪爱。\n远岫连天横淡霭。\n望断孤鸿飞外。\n夕阳红树林。\n重重锦障横陈。\n一段江南景色，倩谁为下丹青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10832, '一翦梅', '赵长卿', '霁霭迷空晓未收。\n羁馆残灯，永夜悲秋。\n梧桐叶上三更雨，别是人间一段愁。\n睡又不成梦又休。\n多愁多病，当甚风流。\n真情一点苦萦人，才下眉尖，恰上心头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10833, '南歌子', '赵长卿', '此日知何日，他乡忆故乡。\n乱山深处过重阳。\n走马吹花、无复少年狂。\n黄菊擎枝重，红茱湿露香。\n扁舟随雁过潇湘。\n遥想莱庭、应恨不同觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10834, '醉花阴', '赵长卿', '老去悲秋人转瘦。\n更异乡重九。\n人意自凄凉，只有茱萸，岁岁香依旧。\n登高无奈空搔首。\n落照归鸦後。\n六代旧江山，满眼兴亡，一洗黄花酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10835, '菩萨蛮', '赵长卿', '西风转蒹葭浦。\n客愁生怕秋阑雨。\n衾冷梦魂惊。\n声声滴到明。\n不眠枕听。\n故故添新恨。\n新恨有谁知。\n天寒雁正稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10836, '菩萨蛮', '赵长卿', '炊烟一点孤村迥。\n娇容敛尽天容净。\n雁字忽横秋。\n秋江泻客愁。\n银钩空寄恨。\n恨满凭谁问。\n袖手立西风。\n舟行秋色中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10837, '浣溪沙', '赵长卿', '雨滴梧桐点点愁。\n冷催秋色上帘钩。\n蛩声何事早知秋。\n一夜凉风惊去燕，满川晴涨漾轻鸥。\n怀人千里思悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10838, '满庭芳', '赵长卿', '晚色沈沈，雨声寂莫，夜寒初冻云头。\n晓来阶砌，一捻冷光浮。\n目断江天霭霭，低迷映、绿竹修修。\n多才客，高吟柳絮，还更上层楼。\n烹茶，新试水，人间清楚，物外遨游。\n胜似他、销金暖帐情柔。\n细看流风迥舞，终日价、浅酌轻讴。\n醺醺地，美人翻曲，消尽古今愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10839, '御街行', '赵长卿', '晚来无奈伤心处。\n见红叶、随风舞。\n解鞍还向乱山深，黄昏後、不成情绪。\n先来离恨，打叠不下，天气还凄楚。\n风儿住後云来去。\n装撰些儿雨。\n无眠托首对孤灯，好语向谁分付。\n从来烦恼，吓得胆碎，此度难担负。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10840, '有有令', '赵长卿', '前山减翠。\n疏竹度轻风，日移金影碎。\n还又年华暮，看看是、新春至。\n那更堪、有个人人，似花似玉，温柔伶俐。\n准拟。\n恩情戏。\n拈弄上、则人难比。\n我也埋根竖柱，你也争些气。\n大家一捺头地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10841, '摊破丑奴儿・采桑子', '赵长卿', '树头红叶飞都尽，景物凄凉。\n秀出群芳。\n又见江梅浅淡妆。\n也，真个是、可人香。\n兰魂蕙魄应羞死，独占风光。\n梦断高堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10842, '临江仙', '赵长卿', '日欲低时江景好，暮山紫翠重重。\n钓筒收尽碧潭空。\n一船霜夜月，两岸荻花风。\n遥忆暖春新向火，黄昏下了帘栊。\n水村渔浦舣孤篷。\n单衾愁梦断，无梦转愁浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10843, '南歌子', '赵长卿', '霜结凝寒夜，星辉识晓晴。\n兰膏重剔且教明。\n为照梢头香缕、一丝轻。\n坐久看看困，新词缀未成。\n梅花熏得酒初醒。\n更向耳边低道、月三更。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10844, '永遇乐', '赵长卿', '宵露珠零，溅冰花薄，凝瑞偏早。\n月练轻翻，风刀碎剪，青女呈纤巧。\n微丹枫缬，低摧蕉尾，不觉半池莲倒。\n最好是、千林橘柚，轻黄一村封了。\n佳人指冷，暗惊罗幕，一夜斜飞多少。\n怕倚银屏，愁看玉砌，金菊鲜鲜晓。\n伤嗟傅粉，佳期还未，何处冷沾衣透。\n争知人、临鸾试罢，与梅共瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10845, '玉蝴蝶', '赵长卿', '片片空中剪水，巧妆春色，照耀江湖。\n渐觉花球转柳，荚阵飞榆。\n散银杯、时时逐马。\n翻缟带、一一随车。\n遍帘隅。\n寒生冰箸，光剖明珠。\n应须。\n浅斟低唱，毡垂红帐，兽金炉。\n更向高楼，纵观吟醉谢娘扶。\n静时闻、竹声岩谷，漫不见、禽影江湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10846, '潇湘夜雨・满庭芳', '赵长卿', '斜点银缸，高擎莲炬，夜寒不奈微风。\n重重帘幕掩堂中。\n香渐远、长烟袅，光不定、寒影摇红。\n偏奇处，当庭月暗，吐焰如虹。\n红裳呈艳丽，□娥一见，无奈狂纵。\n试烦他纤手，卷上纱龙。\n开正好、银花照夜，堆不尽、金粟凝空。\n叮咛语，频将好事，来报主人公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10847, '念奴娇', '赵长卿', '据炉肃坐，听瓶笙、别有天然宫徵。\n纸帐屏山浑不俗，写出江南烟水。\n檠短灯青，灰闲香软，所欠惟梅矣。\n风飞无定，数声时颤窗纸。\n试问夜已何其，呼童起看，月上东墙未。\n天外忽闻征雁过，还把音书来寄。\n短笠埋烟，轻蓑鸣雨，已办征船计。\n放教归去，故乡江上鱼美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10848, '摊破丑奴儿・采桑子', '赵长卿', '又是两分携。\n憔悴损、看怎医治。\n烟村一带寒红绕，悲风红叶，残阳暮草，还似年时。\n愁绪暗犹夷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10849, '柳梢青', '赵长卿', '云暗天低。\n枫林凋翠，寒雁声悲。\n茅店儿前，竹篱巴後，初见横枝。\n盈盈粉面香肌。\n记月榭、当年见伊。\n有恨难传，无肠可断，立马多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10850, '祝英台近', '赵长卿', '记临歧，销黯处。\n离恨惨歌舞。\n恰是江梅，开遍小春暮。\n断肠一曲金衣，两行玉箸，酒阑後、欲行难去。\n恶情绪。\n因念锦幄香奁，别来负情素。\n冷落深闺，知解怨人否。\n料应宝瑟慵弹，露华懒傅，对鸾镜、终朝凝伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10851, '点绛唇', '赵长卿', '瓦湿鸳鸯，夜深霜重江风冷。\n月华明映。\n清浸梅梢粉。\n漏断寒浓，惹起当年恨。\n君休问。\n雁飞欲尽。\n没个南来信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10852, '点绛唇', '赵长卿', '当日相逢，枕衾清夜纱窗冷。\n翠梅低映。\n汗湿香腮粉。\n美满风情，结下无穷恨。\n凭谁问。\n此心难尽。\n说与他争信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10853, '点绛唇', '赵长卿', '云霁山横，翠涛拥起千重恨。\n砌成愁闷。\n那更梅花褪。\n凤管云笙，无不萦方寸。\n叮咛问。\n泪痕羞愠。\n界破香腮粉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10854, '柳梢青', '赵长卿', '千林落叶声声悲。\n听凄惨、江皋雁飞。\n难似玉肌，总惊花貌，压倒芳菲。\n香心吐尽因谁。\n料调鼎、工夫易期。\n休唱阳关，莫歌白雪，雨泪沾衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10855, '西江月', '赵长卿', '背日犹馀残雪，向阳初绽红梅。\n腊寒那事更相宜。\n醉了还醒又醉。\n堪笑多愁早老，管他闲是闲非。\n对花酌酒两忘机。\n唱个哩哩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10856, '眼儿媚', '赵长卿', '一钩新月照西楼。\n清夜思悠悠。\n那堪更被，征鸿嘹唳，绊惹离愁。\n倚栏不语情如醉，都总寄眉头。\n从前只为，惜他伶俐，举措风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10857, '别怨', '赵长卿', '娇马频嘶。\n晓霜浓、寒色侵衣。\n凤帷私语处，翻成离怨不胜悲。\n更与叮咛祝後期。\n素约谐心事，重来了、比看相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10858, '减字木兰花', '赵长卿', '小春天气。\n未唱阳关心已醉。\n红蓼秋容。\n後会何时得再逢。\n归期好事。\n仰看皇州扬雨露。\n百里恩波。\n拟欲留公无奈何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10859, '好事近', '赵长卿', '去路马蹄轻，正是小春时节。\n爱日暖烘江树，缀梅梢新雪。\n范滂揽辔正澄清，知我公明洁。\n分此仁风恺悌，济邻邦欢悦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10860, '霜天晓角', '赵长卿', '合儿幽静处，围炉面小窗。\n好是斗头儿坐，梅烟炷、返魂香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10861, '鹧鸪天', '赵长卿', '宝篆龙煤烧欲残。\n细听铜漏已更阑。\n纱窗斜月移梅影，特地笼灯仔细看。\n幽梦断，旧盟寒。\n那时屈曲小屏山。\n风光得似而今不，肯把花枝作等闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10862, '蓦山溪', '赵长卿', '玉妃整佩，绛节参差御。\n一笑唤春回，正江南、天寒岁暮。\n孤标独立，占断世间香，云屋冷，雪篱深，长记西湖路。\n人间尘土，不是留花处。\n羌管一声催，碎琼瑶、纷纷似雨。\n枝头著子，聊与世调羹，功就後，盍归休，还记来时不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10863, '浣溪沙', '赵长卿', '雪压前村曲径迷。\n万山寒立玉参差。\n孤舟独钓一蓑归。\n别坞时听风折竹，断桥闲看水流澌。\n一枝冻蕊出疏篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10864, '浣溪沙', '赵长卿', '风卷霜林叶叶飞。\n雁横寒影一行低。\n淡烟衰草不胜诗。\n白酒已浮蚁熟，黄鸡未老藁头肥。\n问侬不醉待何时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10865, '浣溪沙', '赵长卿', '忆为梅花醉不醒。\n断桥流水去无声。\n鹭翘沙嘴亦多情。\n疏影卧波波不动，暗香浮月月微明。\n高楼羌管未须横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10866, '点绛唇', '赵长卿', '离绪千重，角声偏著羁人枕。\n那堪酒醒。\n句引愁难整。\n门锁黄昏，月浸梅花冷。\n人初静。\n斗垂天迥。\n雁落清江影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10867, '鹧鸪天', '赵长卿', '门外寒江泊小船。\n月明留客小窗前。\n夜香烧尽更声远，斗帐低垂暖意生。\n醺著酒，炙些灯。\n伴他针线懒成眠。\n情知今夜鸳鸯梦，不似孤篷宿雁边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10868, '望江南・忆江南', '赵长卿', '山又水，云岫插峰峦。\n断雁飞时霜月冷，乱鸦啼处日衔山。\n疑在画图间。\n金乌转，游子损朱颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10869, '菩萨蛮', '赵长卿', '枫林飒飒凋寒叶。\n汀苹败蓼遥相接。\n景物已非秋。\n凄凉动客愁。\n还家贫亦好。\n肯厌杯中草。\n香饭滑流匙。\n三登快乐时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10870, '菩萨蛮', '赵长卿', '霜风飒飒溪山碧。\n寒波一望伤行色。\n落日淡荒村。\n人家半掩门。\n孤舟移野渡。\n古木栖鸦聚。\n著雨晚风酸。\n貂裘不奈寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10871, '菩萨蛮', '赵长卿', '败荷倒尽芙蓉老。\n寒光黯淡迷衰草。\n行客易销魂。\n笛飞何处村。\n云寒天借碧。\n树瘦烟笼直。\n若个是乡关。\n夕阳西去山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10872, '阮郎归', '赵长卿', '年年为客遍天涯。\n梦迟归路赊。\n无端星月浸窗纱。\n一枝寒影斜。\n肠未断，鬓先华。\n新来瘦转加。\n角声吹彻小梅花。\n夜长人忆家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10873, '霜天晓角', '赵长卿', '香来不歇。\n谁把南枝折。\n的砾疏花初破，都因是、夜来雪。\n清绝。\n十分绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10874, '霜天晓角', '赵长卿', '雪花飞歇。\n好向前村折。\n行至断桥斜处，寒蕊瘦、不禁雪。\n韵绝。\n香更绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10875, '菩萨蛮', '赵长卿', '客帆卸尽风初定。\n夜空霜落无江冷。\n幸自不思归。\n无端乌夜啼。\n鸡鸣残月落。\n到枕秋声恶。\n有酒不须斟。\n酒深愁转深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10876, '忆秦娥', '赵长卿', '寒萧索。\n征鸿过尽离怀恶。\n离怀恶。\n江空天迥，夜寒枫落。\n有人应误刀头约。\n情深翻恨郎情薄。\n郎情薄。\n梦回长是，半床闲却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10877, '如梦令', '赵长卿', '何处一声鸣橹。\n惊起满川寒鹭。\n一著画难成，雪霁乱山无数。\n且住。\n且住。\n数遍溪南烟树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10878, '水龙吟', '赵长卿', '危楼横枕清江上，两岸碧山如画。\n夕烟幂幂，晚灯点点，楼台新夜。\n明月当天，白沙流水，冷光连野。\n浸栏干万顷，琉璃软皱，打鱼艇、相高下。\n何处一声羌管，是谁家、倚楼人也。\n多情对景，无言有恨，欲歌还罢。\n把酒临筵，阿谁知我，此怀难写。\n忍思量後夜，芳容不似，暗尘随马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10879, '水调歌头', '赵长卿', '离愁晚如织，托酒与消磨。\n奈何酒薄愁重，越醉越愁多。\n忍对碧天好夜，皓月流光无际，光影转庭柯。\n有恨空垂泪，无语但悲歌。\n因凝想，从别後，蹙双蛾。\n春来底事，孤负紫袖与红靴。\n速整雕鞍归去，著意浅斟低唱，细看小婆娑。\n万蕊千花里，一任玉颜酡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10880, '水龙吟', '赵长卿', '酒潮匀颊双眸溜。\n美映远山横秀。\n风流俊雅，娇痴体态，眼前稀有。\n莲步弯弯，移归拍里，凌波难偶。\n对仙源醉眼，玉纤笼巧，拨轻声、鱼纹皱。\n我自多情多病，对人前、只推伤酒。\n瞒他不得，诗情懒倦，沈腰销瘦。\n多谢东君，殷勤知我，曲翻红袖。\n拼来朝又是，扶头不起，江楼知不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10881, '念奴娇', '赵长卿', '夕阳底尽，望楚天空阔，稀星帘幕。\n暮霭横江烟万缕，照水参差楼阁。\n两两三三，楼前归鹭，飞过栏干角。\n霜风何事，绕檐吹动寂寞。\n消散我已忘机，而今百念，灰了心头火。\n对酒当歌浑冷淡，一任他懑嗔恶。\n松竹园林，柳梧庭院，自有人间乐。\n闲云休问，去来本是无著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10882, '水调歌头', '赵长卿', '贪痴无了日，人事没休期。\n白驹过隙，百岁能得几多时。\n自古腰金结绶，著意经营辛苦，回首不胜悲。\n名未能安稳，身已至倾危。\n空剜刻，休巧诈，莫心欺。\n须知天定，只见高与新碑。\n我已从头识破，赢得当歌临酒，欢笑且随宜。\n较甚荣和辱，争甚是和非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10883, '水龙吟', '赵长卿', '曾著意斟量过，天下事、无穷尽。\n贪荣贪富，朝思夕计，空劳方寸。\n蹑足封王，功名盖世，谁如韩信。\n更堆金积玉，石崇豪侈，当时望、倾西晋。\n长乐宫中一叹，又何须累累悬印。\n坠楼效死，轻车东市，头膏血刃。\n尤物虚名，於身何补，一齐休问。\n遇当歌临酒，舒眉展眼，且随缘分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10884, '蓦山溪', '赵长卿', '壶天冰雪，消尽虚堂暑。\n多谢故人风，送花香传小树。\n香风初过，一曲断肠声，如怨诉。\n诉闲愁，落落琵琶语。\n江边马上，弹指成千古。\n泪眼与啼妆，叹风流、只今何处。\n芳心役损，触事起悲酸，招玉素。\n拨檀槽，整理金衣缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10885, '念奴娇', '赵长卿', '精神俊雅，更那堪、天与风流标格。\n罗绮丛中偏艳冶，偷处教人怜惜。\n目剪秋波，指纤春笋，新样冠儿直。\n高堂云雨，甚人有分消得。\n戏笑里含羞，回眸低盼，此意谁能识。\n密约幽欢空怅望，何日能谐端的。\n玳席歌馀，兰堂香散，此际愁如织。\n人归空对，晚阴庭树横碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10886, '瑞鹤仙', '赵长卿', '无言屈指也。\n算年年底事，长为旅也。\n凄惶受尽也。\n把良辰美景，总成虚也。\n自嗟叹也。\n这情怀、如何诉也。\n谩愁明怕暗，单栖独宿，怎生禁也。\n闲也。\n有时临镜，渐觉形容，日消减也。\n光阴换也。\n空辜负、少年也。\n念仙源深处，暖香小院，赢得群花怨也。\n是亏他见了，多教骂几句也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10887, '蓦山溪', '赵长卿', '无非无是。\n好个闲居士。\n衣食不求人，又识得、三文两字。\n不贪不伪，一味乐天真，三径里。\n四时花，随分堪游戏。\n学些沓拖，也似没意志。\n诗酒度流年，熟谙得、无争三昧。\n风波歧路，成败霎时间，你富贵。\n你荣华，我自关门睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10888, '青玉案', '赵长卿', '东门杨柳空盈路。\n系得征鞍能驻不。\n暗绿枝头新过雨。\n柔丝千尺，乳莺百啭，似怨行人去。\n行人去後如何处。\n去向天边鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10889, '虞美人', '赵长卿', '雨声破晓催行桨。\n拍拍溪流长。\n绿杨绕岸水痕斜。\n恰似画桥西畔、那人家。\n人家楼阁临江渚。\n应是停歌舞。\n珠帘整日不闲钩。\n目断征帆、犹未识归舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10890, '虞美人', '赵长卿', '灯前忍见啼红面。\n别酒频斟劝。\n愁蛾敛翠不胜情。\n报道看看天色、待平明。\n殷勤重把阳关唱。\n休要教人望。\n出门犹自尚叮咛。\n厮养频催恰好、趁凉行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10891, '临江仙', '赵长卿', '十里春风杨柳路，年年带雨披云。\n柔条万缕不胜情。\n还将无意眼，识遍有心人。\n饿损宫腰终不似，效颦总是难成。\n只愁秋色入高林。\n残蝉和落叶，此际不堪论。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10892, '渔家傲', '赵长卿', '客里情怀谁可表。\n凄凉举目知多少。\n强饮强歌还强笑。\n心悄悄。\n从头彻底思量了。\n当日相逢非草草。\n果然恩爱成烦恼。\n稳整征鞍归去好。\n重厮守。\n相期待与同偕老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10893, '江神子・江城子', '赵长卿', '当时得意两心齐。\n绮窗西。\n共于飞。\n拂掠宫妆，长与画新眉。\n一自别来烟水阔，愁易积，梦还稀。\n相逢恰似旧家时。\n恨依依。\n语低低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10894, '御街行', '赵长卿', '香熏斗帐相逢乍。\n正宫漏、沈沈夜。\n月飞梅影上帘栊，标致风流娇雅。\n眼波横浸，照人百媚，无限叮咛话。\n玉鞍门上嘶归马。\n趱行色、难留也。\n别来花艳不禁春，浪向东风轻嫁。\n空馀小院，博山修竹，依旧窗儿下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10895, '一丛花', '赵长卿', '当歌临酒恨难穷。\n酒不似愁浓。\n风帆正起归与兴，岸东西、芳草茸茸。\n楚梦乍回，吴音初听，谁念我孤踪。\n藏春小院暖融融。\n眼色与心通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10896, '天仙子', '赵长卿', '眼色媚人娇欲度。\n行尽巫阳云又雨。\n花时还复见芳姿，情几许。\n愁何许。\n莫向耳边传好语。\n往事悠悠曾记否。\n忍听黄鹂啼锦树。\n啼声惊碎百花心。\n分付与。\n谁为主。\n落蕊飞红知甚处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10897, '瑞鹧鸪', '赵长卿', '宝奁常见晓妆时。\n面药香融傅口脂。\n扰扰亲曾撩绿鬓，纤纤巧与画新眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10898, '瑞鹧鸪', '赵长卿', '结丝千绪不胜愁。\n莫怪安仁鬓早秋。\n檀口未歌先愠泪，柳眉将敛半凝羞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10899, '行香子', '赵长卿', '骄马花骢。\n柳陌经从。\n小春天、十里和风。\n个人家住，曲巷墙东。\n好轩窗，好体面，好仪容。\n烛歌慵。\n斜月朦胧。\n夜新寒、斗帐香浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10900, '夜行船', '赵长卿', '龟甲炉烟轻袅。\n帘栊静、乳莺啼晓。\n拂掠新妆，时宜头面，绣草冠儿小。\n衫子揉蓝初著了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10901, '采桑子', '赵长卿', '疏帘乍卷孜孜看，冰玉精神。\n体白停匀。\n端的于人不薄情。\n更无背约和焦燥，各表真诚。\n才得相亲。\n切莫分张向别人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10902, '蝶恋花', '赵长卿', '闲上西楼供远望。\n一曲新声，巧媚谁家唱。\n独倚危栏听半晌。\n长江快泻澄无浪。\n清泪恰同清水涨。\n拭尽重流，触事如何向。\n不觉黄昏灯已上。\n旧愁还是新愁样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10903, '蝶恋花', '赵长卿', '天净娥初整驾。\n桂魄蟾辉，来趁清和夜。\n费尽丹青无计画。\n纤纤侧向疏桐挂。\n人在扶疏桐影下。\n耳畔轻轻，细说家常话。\n年少难留应不借。\n未歌先咽歌还罢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10904, '蝶恋花', '赵长卿', '叶底蜂衙催日晚。\n向晚匀妆，巧画宫眉浅。\n翠幕无风香自远。\n金船酌酒须教满。\n未说别离魂已断。\n雨幌云屏，只恐良宵短。\n心事不随飞絮乱。\n宦情肯把恩情换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10905, '鹧鸪天', '赵长卿', '睡觉扶头听晓钟。\n隔帘花雾湿香红。\n翠摇钿砌梧桐影，暖透罗襦芍药风。\n闲对影，记曾逢。\n画眉临镜霎时同。\n相思已有无穷恨，忍见孤鸾宿镜中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10906, '鹧鸪天', '赵长卿', '宝篆烟消香已残。\n蝉娟月色浸栏干。\n歌喉不作寻常唱，酒令从他各自还。\n传杯手，莫教闲。\n醉红潮脸媚酡颜。\n相携共学骖鸾侣，却笑卢郎旧约寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10907, '鹧鸪天', '赵长卿', '绿水澄江得胜游。\n浪平风软称轻舟。\n樽前我易伤前事，柳外人谁独倚楼。\n空感慨，惜风流。\n风流赢得谩多愁。\n愁多著甚销磨得，莫怪安仁鬓早秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10908, '鹧鸪天', '赵长卿', '一曲清歌金缕衣。\n巧佼心事有谁知。\n自从别後难相见，空解题红寄好诗。\n忆携手，过阶墀。\n月笼花影半明时。\n玉钗头上轻轻颤，摇落钗头豆蔻枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10909, '眼儿媚', '赵长卿', '人随社节去匆匆。\n此恨几时穷。\n阳台寂寞，巫山凄惨，云雨成空。\n芭蕉密处窗儿下，冷落旧香中。\n黄昏静也，蛩声满院，明月清风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10910, '眼儿媚', '赵长卿', '槐阴密处啭黄鹂。\n午日正长时。\n一番过雨，绿荷池面，冷浸琉璃。\n红尘不到华堂里，纤楚对蛾眉。\n笑偎人道，新词觅个，美底腔儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10911, '眼儿媚', '赵长卿', '当年策马过钱塘。\n曲径小平康。\n繁红酽白，娇莺姹燕，争唤何郎。\n而今又客东风里，浑不似寻常。\n只愁别後，月房云洞，啼损红妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10912, '临江仙', '赵长卿', '蕊嫩花房无限好，东风一样春工。\n百年欢笑酒樽同。\n笙吹雏凤语，裙染石榴红。\n且向五云深处住，锦衾绣幌从容。\n如何即是出樊笼。\n蓬莱人少到，云雨事难穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10913, '临江仙', '赵长卿', '破靥盈盈巧笑，举杯滟滟迎逢。\n慧心端有谢娘风。\n烛花香雾，娇困面微红。\n别恨彩笺虽寄，清歌浅酌难同。\n梦回楚馆雨云空。\n相思春暮，愁满绿芜中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10914, '临江仙', '赵长卿', '夜久笙箫吹彻，更深星斗还稀。\n醉拈裙带写新诗。\n锁窗风露，烛月明时。\n水调悠扬声美，幽情彼此心知。\n古香烟断彩云归。\n满倾蕉叶，齐唱传花枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10915, '惜奴娇', '赵长卿', '洛浦娇魂，恐得到、人间少。\n把风流、分付花貌。\n六出精神，腊寒射、香试到。\n清秀。\n与江梅、争相先後。\n檐卜粗疏，怎似妖娆体调。\n比山樊、也应错道。\n最是殷勤，捧出金盏银台笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10916, '水龙吟', '赵长卿', '无情风掠芭蕉响，还是重门已闭。\n银缸独对，相思方切，教人怎睡。\n解叹从前事，解叹了、依前鳖气。\n想他家那里，知人憔悴，相应是、睡也未。\n且恁和衣强寝，奈无寐、依前重起。\n起来思想，当初与你，忒煞容易。\n及至而今也，半头天眼，不存不济。\n最消魂苦是，黄昏前後，冷清清地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10917, '水调歌头', '赵长卿', '把酒相劳苦，月色耀天章。\n冰轮碾破寒碧，飞入酒樽凉。\n击节词人妙句，吸此清辉万丈，肺腑亦生光。\n揽袂欲仙举，逸兴共天长。\n日边客，幕中俊，坐间狂。\n浩歌清啸，恍然云海渺茫茫。\n唤醒谪仙苏二，何事常愁客少，更恐被云妨。\n月与人长好，广大醉为乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10918, '水龙吟', '赵长卿', '先来天与精神，更因丽景添殊态。\n拖轻苒苒，才凝一段，还分五彩。\n毕竟非烟，有时为雨，惹情无奈。\n道无心，怎被歌声遏断，迟迟向、青天外。\n宜伴先生醉卧，得饶道、和山须买。\n也曾恼杀襄王，谁道依前不会。\n我欲乘风归去，翻怅恨、帝乡何在。\n念佳期未展，天长莫合，尽空相对。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10919, '诉衷情', '赵长卿', '花前月下会鸳鸯。\n分散两情伤。\n临行祝付真意，臂间皓齿留香。\n还更毒，又何妨。\n尽成疮。\n疮儿可後，痕儿见在，见後思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10920, '满江红', '赵长卿', '懊恼平生，奈天赋、恩情太薄。\n二三岁、看伊受尽，眼尖眉角。\n记得当初低耳畔，是谁先有于飞约。\n惟到今、划地误盟言，还先恶。\n天眼见，人难度。\n天易感，人难托。\n人心险，天又怎生捉摸。\n莫问傍人非与是，手儿但把心儿托。\n便不成、厮守许多时，乾休却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10921, '贺新郎', '赵长卿', '负你千行泪。\n大都来、一寸心儿，万般萦系。\n似恁愁烦那里洎。\n故自三年二岁。\n为你後、甘心憔悴。\n终待说、山盟海誓。\n这恩情、到此非容易。\n拼做个，久长计。\n紧要事须评议。\n怕人人、蓦地知时，怎生处置。\n毒害心肠祆知是。\n怕你生烦到底。\n便莫待、将人轻弃。\n不是我多疑你。\n被傍人、赚後失圈。\n经一事，长一智。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10922, '眼儿媚', '赵长卿', '连沧危观暮江前。\n几醉使君筵。\n少年俊气，曾将吟笔，买断江天。\n重来细把朋游数，回首一辛酸。\n兰成已老，文园多病，负此江山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10923, '簇水', '赵长卿', '长忆当初，是他见我心先有。\n一钩才下，便引得鱼儿开口。\n好是重门深院，寂寞黄昏後。\n厮觑著、一面儿酒。\n试就。\n便把我、得人意处，闵子里、施纤手。\n云情雨意，似十二巫山旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10924, '摊破丑奴儿・采桑子', '赵长卿', '最苦是离愁。\n行坐里、只在心头。\n待要作个巫山梦，孤衾展转，无眠到晓，和梦都休。\n梦里也无由。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10925, '更漏子', '赵长卿', '烛消红，窗送白。\n冷落一衾寒色。\n鸦唤起，马行。\n月来衣上明。\n酒香唇，妆印臂。\n亿共人人睡。\n魂蝶乱，梦鸾孤。\n知他睡也无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10926, '浣溪沙', '赵长卿', '一味风流一味香。\n十分浓艳十分妆。\n自然娇态自然芳。\n楼上好风楼下水，雪前栏槛竹前窗。\n也宜单著也宜双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10927, '浣溪沙', '赵长卿', '恻恻笙竽万籁风。\n阳关叠遍酒尊空。\n相逢草草别匆匆。\n满眼泪珠和雨洒，一襟愁绪抵秋浓。\n相思今夜五云东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10928, '汉宫春', '赵长卿', '讲柳谈花，我从来口快，说他家。\n眼前见了，无限楚女吴娃。\n千停万稳，较量来、终不如他。\n便做得，宫仪院体，歌谈不带烟花。\n从前万事堪夸。\n爱拈笺弄管，锦字斜。\n新来与人著，不许胡巴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10929, '雨中花慢', '赵长卿', '子分香，罗巾拭泪，别来时、未觅凄惶。\n上得船儿来了，地凄凉。\n可惜花前月里，却成水远山长。\n做成恩爱，如今赢得，万里千乡。\n情知这场寂寞，不干你事，伤我穷忙。\n不道是、久长活路，终要称量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10930, '柳梢青', '赵长卿', '小窗闲适。\n云髻肩，香肌偎膝。\n玉局无尘，明琼欲碎，春纤同掷。\n不争百万呼卢，赌今夜、鸳帷痛惜。\n好忍马儿，若还输了，当甚则剧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10931, '南歌子', '赵长卿', '梅萼和霜晓，梨花带雪春。\n玉肌琼艳本无尘。\n肯把铅华容易、污天真。\n汤饼尝初罢，罗巾拭转新。\n几回贪耍失黄昏。\n月里归来无处、觅精神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10932, '临江仙', '赵长卿', '人在梦云楼上别，残灯影里迟留。\n依稀绿惨更红羞。\n露痕双脸湿，山样两眉愁。\n几幅片帆天际去，云涛烟浪悠悠。\n今宵独立古江头。\n水腥鱼菜市，风碎荻花舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10933, '浣溪沙', '赵长卿', '画角声沈卷暮霞。\n寒生促索锦屏遮。\n沈檀半髻堆鸦。\n蝴蝶梦回馀烛影，子规啼处隔窗纱。\n夜深明月浸梨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10934, '浪淘沙', '赵长卿', '帘卷露花容。\n几度相逢。\n他知我意欲相通。\n偏奈天教多阻间，积恨何穷。\n云雨杳无踪。\n愁怕东风。\n时闻语笑恣欢浓。\n惟有俺咱真分浅，往事成空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10935, '如梦令', '赵长卿', '竹外半窥娇面。\n真个出尘体段。\n没处可偷怜，空恁眼穿肠断。\n休恋。\n休恋。\n只是与伊分浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10936, '浣溪沙', '赵长卿', '闲理丝簧听好音。\n西楼剪烛夜深深。\n半嗔半喜此时心。\n暖语温存无恙语，韵开香靥笑吟吟。\n别来烦恼到如今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10937, '减字木兰花', '赵长卿', '阳关唱彻。\n断尽离肠声哽咽。\n酒已三巡。\n今夜王孙是路人。\n此情难说。\n莫负等闲风与月。\n欲问归期。\n来戴钗头艾虎儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10938, '减字木兰花', '赵长卿', '半窗斜月。\n茅店萧条灯已灭。\n床下蛩声。\n声动凄凉不忍听。\n终宵无寐。\n覆去翻来真个是。\n屈指归期。\n应是梅花烂熳时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10939, '夜行船', '赵长卿', '短棹轻舟排办了。\n歌声断、晚霞残照。\n红蓼坡头，绿杨堤外，离恨知多少。\n别後莫教音信杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10940, '眼儿媚', '赵长卿', '玉楼初见念奴娇。\n无处不妖娆。\n眼传密意，樽前烛外，怎不魂消。\n西风明月相逢夜，枕簟正凉宵。\n人记得，叮咛残漏，且慢明朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10941, '品令', '赵长卿', '黄昏时候，诮不语、心如醉。\n无眠凝想，别来绣阁，多应憔悴。\n上了灯儿，知是睡哩坐哩。\n蓦思归计。\n又还是重屈指。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10942, '柳梢青', '赵长卿', '甜言软语。\n长记那时，萧娘叮嘱。\n清管危弦，前欢难断，鳞鸿无据。\n纷纷眼底浮花，拈弄动、几多思虑。\n千结丁香，且须珍重，休胡分付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10943, '浣溪沙', '赵长卿', '金兽喷香瑞霭氛。\n夜凉如水酒醺醺。\n照人娇眼媚生春。\n我自愁多魂已断，不禁楚雨带巫云。\n人情又是一番新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10944, '浣溪沙', '赵长卿', '坐看销金暖帐中。\n羔儿酒美兽煤红。\n浅斟低唱好家风。\n爱客东君多解事，晚妆新与画眉峰。\n便须催唤出房栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10945, '浣溪沙', '赵长卿', '堆枕冠儿翡翠钗。\n蒙金领子满鞋。\n于中沈净好情怀。\n新欲晚凉梳洗罢，半娇微笑下堂来。\n莲花因甚未曾开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10946, '临江仙', '赵长卿', '天外浓云云外雨，雨声初上檐牙。\n红蕖应褪洗妆花。\n晚凉如有意，到山家。\n为唤山童多索酒，金锺细酌流霞。\n晕生玉颊酒潮斜。\n闲中无宠辱，醉里是生涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10947, '夜行船', '赵长卿', '绿盖红幢笼碧水。\n鱼跳处、浪痕匀碎。\n惜别殷勤，留连无计，歌声与、泪和柔脆。\n一叶扁舟烟浪里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10948, '浪淘沙', '赵长卿', '窈窕绣帏深。\n窈窕娉婷。\n梅花初试晚妆新。\n那更娇痴年纪小，冰雪精神。\n举措忒轻盈。\n歌彻新声。\n柔肠魂断不堪听。\n但恐巫山留不住，飞作行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10949, '如梦令', '赵长卿', '居士年来懒散。\n凡事只从宽简。\n身外更无求，祗要夏凉冬暖。\n美满。\n美满。\n得过何须积趱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10950, '卜算子', '赵长卿', '十载仰高明，一见心相许。\n来日孤舟西水门。\n风饱征帆腹。\n後夜起相思，明月清江曲。\n若见秋风寒雁来，能寄音书否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10951, '眼儿媚', '赵长卿', '先来客路足伤悲。\n那更话别离。\n玉骢也解，知人欲去，骧首频嘶。\n马蹄动是三千里，後会莫相违。\n切须更把，丁香珍重，待我重期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10952, '南乡子', '赵长卿', '楚楚窄衣裳。\n腰身占却，多少风光。\n共说春来春去事，凄凉。\n懒对菱花晕晓妆。\n闲立近红芳。\n游峰戏蝶，误采真香。\n何事不归巫峡去，思量。\n故来尘世断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10953, '南乡子', '赵长卿', '月转水晶盘。\n楼上初闻一鼓残。\n又是去年天气好，栏干。\n风动梅梢玉斗寒。\n无奈壮情阑。\n对酒如何欲强欢。\n谁道破愁须仗酒，君看。\n酒到愁多破亦难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10954, '谒金门', '赵长卿', '灯乍灭。\n忽见一天明月。\n恰舞霓裳歌未歇。\n露寒回绛阙。\n羽服明晖玉雪。\n笑语轻参环。\n香泽恼人情不彻。\n夜长窗自白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10955, '点绛唇', '赵长卿', '云宫鬟，淡黄衫子轻香透。\n晚凉时候。\n睡起新妆就。\n冰枕生寒，玉浸纤纤手。\n沈吟久。\n眉山敛秀。\n爱道奴家瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10956, '菩萨蛮', '赵长卿', '春山已蹙眉峰绿。\n春心骀荡难拘束。\n惆怅为春伤。\n惜花心更狂。\n对花深有意。\n且向花前醉。\n花作有情香。\n与人相久长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10957, '画堂春', '赵长卿', '当时巧笑记相逢。\n玉梅枝上玲珑。\n酒杯流处已愁浓。\n寒雁横空。\n去程无记更从容。\n到归来好事匆匆。\n一时分付不言中。\n此恨难穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10958, '如梦令', '赵长卿', '居士年来病酒。\n肉食百不宜口。\n蒲合与波，更着同蒿葱韭。\n亲手。\n亲手。\n分送卧龙诗友。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10959, '如梦令', '赵长卿', '别恨眉尖无数。\n後夜王孙何处。\n歌馆与妆楼，目断行云凝伫。\n凝伫。\n凝伫。\n忆泪千行红雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10960, '菩萨蛮', '赵长卿', '隔江一带春山好。\n平林新绿春光老。\n休去倚阑干。\n飞红不忍看。\n东流何处去。\n便是归舟路。\n芳草外斜阳。\n行人更断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10961, '长相思', '赵长卿', '敛愁眉。\n恨依依。\n肠断关情怨别离。\n云中过雁悲。\n瘦因谁。\n病因谁。\n屈指无言忖後期。\n此时人怎知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10962, '柳梢青', '赵长卿', '潇洒仙源。\n夭桃李，曾对华筵。\n歌媚惊尘，舞弯低月，满劝金船。\n鉴湖烟水连天。\n政归棹、红妆斗妍。\n花雾香中，人询居士，切莫多传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10963, '好事近', '赵长卿', '不羡八千椿，不羡三偷桃客。\n也不羡他龟鹤，一总为凡物。\n羡君恰似老人星，长明无休息。\n好与中兴贤主，立维城勋绩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10964, '朝中措', '赵长卿', '南楼风物一番新。\n春暮畀斯民。\n岂但仁人恺弟，更兼政事如神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10965, '朝中措', '赵长卿', '文章学业继家声。\n名誉压群英。\n早岁掀腾仕，如公富贵难并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10966, '朝中措', '赵长卿', '先生德行冠南丰。\n锦绣作心胸。\n暂屈徒劳州县，文章後进宗工。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10967, '念奴娇', '赵长卿', '桂华蟾魄，到中秋、祗有人闻一六。\n浩渺清风因唤起，千里吹飞鸿鹄。\n碧落翻花，瑶空隐瑞，声节琅筑。\n板怀玉燕，此时嘉梦重育。\n始信名在丹台，方八百，子已三千熟。\n麟脯灵瓜那更有，琼神仙。\n秋水春山，柳腰花面，一醉霓裳曲。\n长生清净，自然何用辟谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10968, '好事近', '赵长卿', '江上一江楼，楼上远山横翠。\n还更腰金骑鹤，引竹西歌吹。\n寿君春酒遣双壶，满引见深意。\n肯向龟荷香里，唤侬来同醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10969, '好事近', '赵长卿', '剑水霭欢声，喜庆间生人杰。\n一段葱葱佳气，扇熏风时节。\n今朝银艾佐琴堂，争把寿香。\n去去凤皇池上，见龟巢连叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10970, '柳长春・踏莎行', '赵长卿', '梅喜先春，雁惊未腊。\n于门瑞气浮周匝。\n正当月应上弦时，长庚梦与良辰合。\n螺水恩浓，江德洽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10971, '武陵春', '赵长卿', '又是新逢三五夜，瑞气霭氤氲。\n万点灯和月色新。\n桃李倍添春。\n花县主人情思好，行乐逐良辰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10972, '临江仙', '赵长卿', '天炎图生国瑞，蓝田暂屈英僚。\n始知文宿降璇霄。\n中元前五日，七夕後三朝。\n江风流临此政，少年潇洒奇标。\n行看峻擢相熙朝。\n功名前稷契，寿算等松乔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10973, '喜迁莺', '赵长卿', '商轻透。\n动帘幕飞梧，乱飘庭。\n瑞气氤氲，沈檀初，烟喷宝台金兽。\n黄花美酒。\n天教占得，先他时候。\n诞元老，庆有声，此夕降生华胄。\n欢笑。\n宜称寿。\n弦管鼎沸，宫商方频奏。\n满捧瑶卮，华堂歌舞，拍转金钗斜溜。\n朱颜绿鬓，殷勤深愿，镇长如旧。\n叹滨海，道难留，指日荣迁飞骤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10974, '鹊桥仙', '赵长卿', '云峰初敛，秋荣如洗，庭院金风初扇。\n葱葱佳气霭侯门，信天上、麒麟乍见。\n祝君此去，飞黄腾踏，日侍凝旒邃冕。\n和羹调味早归来，坐看取、蓬莱清浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10975, '柳梢青', '赵长卿', '晴雪楼台，试灯帘幕，适是元宵。\n罗绮娇春，帝城风景，今夜应饶。\n争知我系如匏，便そ月良天任教。\n早闭柴门，从他箫鼓，细打轻敲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10976, '贺新郎', '赵长卿', '世谛人多错。\n阿谁将、虚名微利，放教轻著。\n万事莫非前定了，选甚微如饮酌。\n算徒诧、龙韬豹略。\n纵使龙头安尺木，更从教、豹变生三角。\n浑是梦，恍如昨。\n吾庐自笑常虚廓。\n对残编、磨穿枯砚，生涯微薄。\n负郭田园能有几，随分安贫守约。\n要不改、箪瓢颜乐。\n西掖百扉终须到，且嘲风咏月常相谑。\n更要甚，万金药。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10977, '东坡引', '赵长卿', '茅斋无客至。\n冰砚冻寒。\n南枝喜入新诗里。\n恼人频嚼蕊。\n恼人频嚼蕊。\n因思去腊江头醉。\n倚动客兴伤春意。\n经年自叹人如寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10978, '满庭芳', '赵长卿', '风力驱寒，云荣呈瑞，晓来到处花飞。\n遍装琼树，春意到南枝。\n便是渔蓑旧画，纶竿重、横玉低垂。\n今宵里，香闺邃馆，幽赏事偏宜。\n风流金马客，歌鬟醉拥，乌帽斜。\n问人间何处，鹏运天池。\n且共周郎按曲，音微误、首己先回。\n同心事，丹山路稳，长伴彩鸾归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10979, '杏花天', '赵长卿', '乍凉淅淅风生幕。\n人独在、朱栏翠阁。\n吹箫信杳炉香薄。\n眉上新愁又觉。\n从前事、拟将拼却。\n梦不断、花梢柳萼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10980, '临江仙', '赵长卿', '远岫螺头湿翠，流霞尾疏明。\n断虹斜界雨新晴。\n烟村灯火晚，江浦画难成。\n我向其间泛叶，终朝露渚风汀。\n老来心事最关情。\n不堪三弄笛，吹作断肠声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10981, '辊绣球', '赵长卿', '流水奏鸣琴，风月净、天无星斗。\n翠岚堆里，苍岩深处，满林霜腻，暗香冻了，那禁频嗅。\n马上再三回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10982, '眼儿媚', '赵长卿', '南枝消息杳然间。\n寂寞倚雕栏。\n紫腰艳艳，青腰袅袅，风月俱闲。\n佳人环佩玉阑珊。\n作恶探花还。\n玉纤拈粟，樱唇呵粉，愁点眉弯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10983, '菩萨蛮', '赵长卿', '日高犹恋珊瑚枕。\n羞红不忿花如锦。\n双燕运芹泥。\n燕归人未归。\n纵饶梳洗罢。\n朱户何曾跨。\n寂寞小房栊。\n回文和泪封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10984, '鹧鸪天', '赵长卿', '落魄东吴二十春。\n风流诗句得清新。\n今年却恨花星照，再见温卿与远真。\n分楚佩，染巫云。\n赤绳结得短花茵。\n若非京口初相识，安得毗陵作故人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10985, '浪淘沙', '赵长卿', '绿树转鸣禽。\n已是春深。\n杨花庭院日阴阴。\n帘外飞来双语燕，不寄归音。\n旧事懒追寻。\n空惹芳心。\n天涯消息远沈沈。\n记得年时中酒後，直至而今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10986, '谒金门', '赵长卿', '春睡足。\n帘卷翠屏山曲。\n芳草沿阶横地轴。\n垂杨相映绿。\n暗忆旧欢难续。\n又是禁烟传烛。\n陌上踏青新结束。\n秋千谁共促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10987, '侍香金童', '赵长卿', '一种春光，占断东君惜。\n算李、昭华争并得。\n粉腻酥融娇欲滴。\n端的尊前，旧曾相识。\n向夜阑、酒醒霜浓寒又力。\n但只与、冰姿添夜色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10988, '菩萨蛮', '赵长卿', '新晴庭户春阴薄。\n东风不度重帘幕。\n第几小兰房。\n雏莺初弄黄。\n悄寒春未透。\n不解寻花柳。\n只恐渐春深。\n愁生求友心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10989, '清平乐', '赵长卿', '紫箫声断。\n窗底春愁乱。\n试著春衫羞自看。\n窄似年时一半。\n一春长病厌厌。\n新来愁病重添。\n香冷倦熏金鸭，日高不卷珠帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10990, '好事近', '赵长卿', '齿颊带馀香，謦咳总成珠玉。\n剪碎袖罗花片，点金觥春绿。\n玉鱼花露自清凉，涓涓在郎腹。\n犹胜望梅消渴，对文君眉蹙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10991, '品令', '赵长卿', '好事客。\n宫商内、吟得风清月白。\n主人幸有豪家意，後堂煞有春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10992, '武陵春', '赵长卿', '落了丹枫残了菊，秋色苦无多。\n谁唤西风泣泪罗，吹恨入星河。\n碧枝头金粟闹，曾扌乖翠云窝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10993, '水调歌头', '罗愿', '秋宇净如水，月镜不安台。\n郁孤高处张乐，语笑脱氛埃。\n檐外白毫千丈，坐上银河万斛，心境两佳哉。\n俯仰共清绝，底处著风雷。\n问天公，邀月姊，愧凡才。\n婆娑人世，羞见蓬鬓漾金。\n来岁公归何处，照耀彩衣簪橐，禁直且休催。\n一曲庾江上，千古继韶陔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10994, '失调名', '罗愿', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10995, '醉翁操', '楼钥', '茫茫。\n苍苍。\n青山绕、千顷波光。\n新秋露风荷吹香。\n悠心地け然，生清凉。\n古岸摇垂杨。\n时有白鹭飞来双。\n隐君如在，鹤与翱翔。\n老仙何处，尚有流风未忘。\n琴与君兮宫商。\n酒与君兮杯觞。\n清欢殊未央。\n西山忽斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10996, '醉翁操', '楼钥', '冷然。\n清圆。\n谁弹。\n向屋山。\n何言。\n清风至阴德之天。\n悠馀响婵娟。\n方昼眠。\n迥立八风前。\n八音相宣知孰贤。\n有时悲壮，铿若龙泉。\n有时幽杳，彷佛猿吟鹤怨。\n忽若巍巍山巅。\n荡荡几如流川。\n聊将娱暮年。\n听之身欲仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10997, '导引', '楼钥', '孝宗纯孝，前圣更何加。\n高蹈处重华。\n丹成仙去龙远，越岸暮山遐。\n波臣先为卷寒沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10998, '导引', '楼钥', '吾皇尽孝，宗庙务崇尊。\n巨典备弥文。\n巍巍东向开基主，七世神孙。\n追思九闰整乾坤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (10999, '失调名', '张良臣', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11000, '西江月', '张良臣', '四壁空围恨玉，十香浅捻啼绡。\n殷云度雨井桐凋。\n雁雁无书又到。\n别後钗分燕股，病馀镜减鸾腰。\n蛮江豆蔻影连梢。\n不道参横易晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11001, '采桑子', '张良臣', '佳人满劝金蕉叶，夜玉春温。\n别後黄昏。\n燕子楼高月一痕。\n年年依旧梨花雨，粉泪空存。\n流水孤村。\n不著寒鸦也断魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11002, '水调歌头', '舒邦佐', '问讯金华伯，自是地行仙。\n只为朱轮画戟，句引到湘川。\n用个狎鸥心地，做就烹鲜时政，民化我何言。\n但贵衡阳纸，纸落尽云烟。\n对湖天，梅索笑，月还圆。\n旧时岳生申甫，重到是前缘。\n快洗瑶觥一醉，唤个鹤仙起舞，骑取上花砖。\n春秋更多少，庄木八千年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11003, '杏花天', '张孝忠', '爱寻水竹添情况。\n任云卧、溪边石上。\n衔杯乐圣成游荡。\n不为弓弯舞样。\n北湖迥、风飘彩舫。\n□笑击、冯夷薄相。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11004, '杏花天', '张孝忠', '看花随柳湖边去。\n似邂逅、水晶宫住。\n刘郎笔落惊风雨。\n酒社诗盟心许。\n玉关外、不辞马武。\n便好展、云霄稳步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11005, '破阵子', '张孝忠', '占气中涵清淑，徵诗古富篇章。\n杖屦闲随鱼□乐，怀抱清如湖水凉。\n何殊吴越乡。\n风柳春容袅袅，水花月影汪汪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11006, '玉楼春', '张孝忠', '绿波春早青烟暮。\n翠幕船如天上去。\n深杯浊酒醉贤人，隔岸幽花怜静女。\n浮云散乱流萍聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11007, '鹧鸪天', '张孝忠', '豆蔻梢头春意浓。\n薄罗衫子柳腰风。\n人间乍识瑶池似，天上浑疑月殿空。\n眉黛小，髻云松。\n背人欲整又还慵。\n多应没个藏娇处，满镜桃花带雨红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11008, '菩萨蛮', '张孝忠', '娇红隐映花稍雾。\n金莲容与歌声度。\n得句写香笺。\n江山此意传。\n醉当春好处。\n不道因风絮。\n去并锦闱眠。\n青绫被底仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11009, '西江月', '张孝忠', '堂上簪缨交错，花间帘幕高张。\n与君一咏一飞觞。\n莫笑诗狂饮畅。\n满路光风转蕙，吟边宫柳斜行。\n新词妙绝动宫墙。\n紫诰黄麻天上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11010, '霜天晓角', '张孝忠', '楚山浮碧。\n江汉无终极。\n鄂渚几行云树，天何意、限南北。\n使君觞醉客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11011, '点绛唇', '方有开', '七里滩边，江光漠漠山如戟。\n渔舟一叶。\n径入寒烟碧。\n笑我尘劳，羞对双台石。\n身如织。\n年年行役。\n鱼鸟浑相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11012, '满江红', '方有开', '跳出红尘，都不顾、是非荣辱。\n垂钓处、月明风细，水清山绿。\n七里滩头帆落尽，长山泷口潮回速。\n问有谁、特为上钩来，刘文叔。\n貂蝉贵，无人续。\n金带重，难拘束。\n这白麻黄纸，岂曾经目。\n昨夜客星侵帝座，且容伸脚加君腹。\n问高风、今古有谁同，先生独。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11013, '贺新郎', '许及之', '旧俗传荆楚。\n正江城、梅炎藻夏，做成重午。\n门艾钗符关何事，付与痴儿呆女。\n耳不听、湖边鼍鼓。\n独炷炉香熏衣润，对潇潇、翠竹都忘暑。\n时展卷，诵骚语。\n新愁不障西山雨。\n问楼头、登临倦客，有谁怀古。\n回首独醒人何在，空把清尊酹与。\n漾不到、潇湘江渚。\n我又相将湖南去，已安排、吊屈嘲渔父。\n君有语，但分付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11014, '水调歌头', '傅大询', '草草三间屋，爱竹旋添栽。\n碧沙窗户，眼前都是翠云堆。\n一月山翁高卧，踏雪水村清冷，木落远山开。\n唯有平安竹，留得伴寒梅。\n唤家童，开门看，有谁来。\n客来一笑，清话煮茗更传杯。\n有酒只愁无客，有客又愁无酒，酒熟且徘徊。\n明日人间事，天自有安排。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11015, '锦堂春・锦堂春慢', '傅大询', '梅要疏开，雪教迟下，怕他寒入江天。\n有月桥仙客，相伴婵娟。\n巷陌升平气象，一时都在鸣弦。\n望东家锦里，雁到云边。\n书到云边。\n尊前翠眉环唱，道新腔字稳，花折声圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11016, '柳梢青', '傅大询', '春到江南，今年寒少，早有疏梅。\n相伴双松，吟哦风月，着意花开。\n天香甚处安排。\n便何似、调羹去来。\n劲节仙姿，玉堂难老，身在蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11017, '念奴娇', '傅大询', '江梅破腊，把一枝来报，□春消息。\n锦帐银瓶龙麝暖，画烛光摇金碧。\n雨径桃花，一溪流水，路入神仙宅。\n云裳羽佩，洞天相会今夕。\n堂下乐问灵鼍，玉人清唱，舞袖低回雪。\n富贵风流须道是，天上人间难得。\n玉镜台边，琼浆盏畔，共说春心切。\n百年偕老，凤凰楼上风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11018, '行香子', '傅大询', '玉佩簪缨。\n罗袜生尘。\n问何时、来到湘滨。\n尧五叶，二月阳春。\n一霎时风，一霎时雨，一霎时晴。\n有子鸣琴。\n有路登瀛。\n戏斑衣、温酒重斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11019, '贺新郎', '刘德秀', '雨沐秋荣薄。\n莹湖光、琉璃千顷，浪平如削。\n步绕湖边佳绝处，时涌琼楼珠阁。\n记一一、经行皆昨。\n十万人家空翠里，借娥、玉鉴相依约。\n卷雾箔，飞烟幕。\n天机云锦才收却。\n放芙蓉、岸花十里，翠红成幄。\n向晚买舟撑月去，笑引银汉共酌。\n醉欲起、骑鲸碧落。\n试唤坡仙哦妙句，问淡妆、此夕如何著。\n只云月，是梳掠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11020, '水调歌头', '吴镒', '澄彻北湖水，圆镜莹青铜。\n客槎星汉天上，隐隐暗朝通。\n六月浮云落日，十顷增冰积雪，胜绝与谁同。\n罗袜步新月，翠袖倚凉风。\n子韩子，叫虞帝，傲祝融。\n御风凌雾来去，邂逅此从容。\n欲问骑何处，试举叉鱼故事，惊起碧潭龙。\n乞我飞霞佩，从子广寒宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11021, '水调歌头', '吴镒', '三楚上游地，五岭翠眉横。\n杜诗韩笔难尽，身到眼增明。\n最好流泉百道，НН绕城萦市，唯见洛阳城。\n化鹤三千岁，橘井尚凄清。\n阆风客，紫贝阙，白玉京。\n不堪天上官府，时此驻霓旌。\n岁晚朔云边雪，压尽蛮烟瘴雨，过雁落寒汀。\n况有如泉酒，细与故人倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11022, '水调歌头', '林淳', '潇洒东湖上，夜雨洗清秋。\n朝来尘霁，凝望千里兴悠悠。\n山色揉蓝深染，波影青铜新铸，□冷翠光浮。\n蓑笠真吾事，聊整钓鱼钩。\n坐中客，凌王谢，更风流。\n一觞一咏，豪俊谈笑气吞牛。\n花月连环长好，到处名园池□，遇景且遨游。\n试问陶元亮，底事赋归休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11023, '鹧鸪天', '林淳', '天近袄知雨露浓。\n湖山无日不春风。\n闲花野草皆掀舞，曾在君王顾盼中。\n时易得，会难逢。\n朝为逆旅暮三公。\n蛟龙得雨飞无便，鸡犬腾云夙有功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11024, '柳梢青', '林淳', '富贵园林。\n清虚清馆，随意登临。\n物外风光，云明花媚，鸟语烟深。\n徐徐缓辔微吟。\n迤逦度、松间柳阴。\n览遍幽奇，小舟归晚，月映波心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11025, '浣溪沙', '林淳', '却忆西湖烂漫游。\n水涵山影翠光浮。\n轻舟短棹不惊鸥。\n带露精神花妩媚，依风情态柳温柔。\n莺歌燕语巧相留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11026, '阮郎归', '王炎2', '落花时节近清明。\n南园芳草青。\n东风料峭雨难晴。\n那堪中宿酲。\n回首处，自销凝。\n谁知人瘦生。\n倚阑无语不禁情。\n杜鹃啼数声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11027, '青玉案', '王炎2', '深红数点吹花絮。\n又燕子、飞来语。\n远水平芜春欲暮。\n年年长是，清明时候，故遣人憔悴。\n竹鸡啼罢山村雨。\n正寥落、无情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11028, '浪淘沙令', '王炎2', '流水绕孤村。\n杨柳当门。\n昔年此地往来频。\n认得绿杨携手处，笑语如存。\n往事不堪论。\n强对清尊。\n梅花香里月黄昏。\n白首重来谁是伴，独自销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11029, '木兰花慢', '王炎2', '缃桃花树下，记罗袜、昔经行。\n至今日重来，人惟独自，花亦凋零。\n青鸟杳无信息，遍人间、何处觅云。\n红锦织残旧字，玉箫吹断馀声。\n销凝。\n衣故几时更。\n又谁复卿卿。\n念镜里琴中，离鸾有恨，别鹄无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11030, '清平乐', '王炎2', '呢喃燕语。\n共诉春归去。\n春去从他留不住。\n落尽枝头红雨。\n老翁袖手优游。\n闲愁不到眉头。\n过了麦黄椹紫，归期只在新秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11031, '清平乐', '王炎2', '儿曹耳语。\n借问何处去。\n家在翠微深处住。\n生计一犁春雨。\n客中且恁浮游。\n莫将事挂心头。\n纵使人生满百，算来更几春秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11032, '浪淘沙', '王炎2', '月色十分圆。\n风露娟娟。\n木犀香里凭阑干。\n河汉横斜天似水，玉鉴光寒。\n草草具杯盘。\n相对苍颜。\n素娥莫惜少留连。\n秋气平分蟾兔满，动是经年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11033, '卜算子', '王炎2', '渡口唤扁舟，雨後青绡皱。\n轻暖相重护病躯，料峭还寒透。\n老大自伤春，非为花枝瘦。\n那得心情似少年，双燕归时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11034, '卜算子', '王炎2', '散策问芳菲，春半花犹未。\n蓓蕾枝头怯苦寒，恰似人憔悴。\n人莫恨花迟，天自催寒去。\n雨意才收日气浓，玉靥红如醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11035, '江城子', '王炎2', '清波渺渺日晖晖。\n柳依依。\n草离离。\n老大逢春，情绪有谁知。\n帘箔四垂庭院静，人独处，燕双飞。\n怯寒未敢试春衣。\n踏青时。\n懒追随。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11036, '虞美人', '王炎2', '镜中失画双青鬓。\n懒更占花信。\n小梅半谢雨垂垂。\n未许轻红破蕾、缀桃枝。\n社前归燕穿帘语。\n似说人憔悴。\n自缘老去少欢。\n不是春寒料峭、怯东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11037, '南乡子', '王炎2', '云淡日明。\n久雨潺潺乍得晴。\n社近东皋农务急，催耕。\n又见菖蒲出水清。\n池面纹平。\n掠水迎风燕羽轻。\n试出访寻春色看，相迎。\n巧笑花枝似有情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11038, '忆秦娥', '王炎2', '胭脂点。\n海棠落尽青春晚。\n青春晚。\n少年游乐，而今慵懒。\n春光不可无人管。\n花边酌酒随深浅。\n随深浅。\n牡丹红透，荼シ香远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11039, '临江仙', '王炎2', '欲近上元人意好，月如人意团圆。\n暖风催趣养花天。\n三山来鹤驾，万户识凫仙。\n手种河阳桃李树，暂时来看春妍。\n彩衣一笑棹觥船。\n明年当此日，人到凤池边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11040, '好事近', '王炎2', '时节近元宵，天意人情都好。\n烟柳露桃枝上，觉今年春早。\n遏云一曲凤将雏，疑是在蓬岛。\n玉笋扶杯潋滟，愿黑头难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11041, '水调歌头', '王炎2', '爱日护轻暖，酝造小春时。\n桃溪云敛，一点郎星吐青辉。\n炼玉颜容难老，点漆精神如旧，不用摘霜髭。\n厌薄蓬莱景，戏踏两凫飞。\n潘花底，陶柳外，细民肥。\n万家喜色，融瑞气拥牙绯。\n凭仗春葱洗玉，领略朱樱度曲，引满又何辞。\n只待琴歌毕，安步上丹墀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11042, '念奴娇', '王炎2', '晓来雨过，正海棠枝上，胭脂如滴。\n桃杏不敢来比似，信是倾城倾国。\n藏韵收香，谁能描貌，阁尽诗人笔。\n从教睡去，为留银烛终夕。\n不待过了清明，绿阴结子，无处寻春色。\n簌簌轻红飞一片，便觉临风凄恻。\n莫道无情，嫣然一笑，也似曾相识。\n惜花无主，自怜身是行客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11043, '浪淘沙令', '王炎2', '秋色满东篱。\n露滴风吹。\n凭谁折取泛芳卮。\n长是年年重九日，苦恨开迟。\n因记得当时。\n共拈纤枝。\n而今寂寞凤孤飞。\n不似旧来心绪好，惟有花知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11044, '采桑子', '王炎2', '一番飞次春风巧，细看工夫。\n点缀红酥。\n此际多应别处无。\n玉人不与花为主，辜负芳菲。\n香透帘帏。\n谁向钗头插一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11045, '好事近', '王炎2', '玉颊映红绡，才报东风消息。\n虽则清如许，有生香真色。\n相看动是隔年期，忍不饮涓滴。\n莫待轻飞一片，却说花堪惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11046, '临江仙', '王炎2', '雪片幻成肌骨，月华借与精神。\n一声羌笛怨黄昏。\n吹香飘缟袂，脱迹委红裙。\n枝上青青结子，子中白白藏仁。\n那时别是一家春。\n劈泥尝煮酒，拂席卧清阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11047, '卜算子', '王炎2', '腻玉染深红，艳丽难常好。\n已是人间祓禊时，花亦随春老。\n唤起曲生来，醉赏惟宜早。\n此去阴晴十日间，点点粘芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11048, '木兰花慢', '王炎2', '博山香雾冷，新雨过、怯单衣。\n正飞絮，平芜杳杳，家在天涯。\n春难住、人易老，又等闲过了踏青时。\n枝上红稀绿暗，杜鹃刚向人啼。\n依依。\n谩叹歌生弹铗，尘满弦徽。\n想北山猿鹤，南溪鸥鹭，怪我归迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11049, '小重山', '王炎2', '日脚才添一线长。\n葭灰吹玉管，转新阳。\n老来添得鬓边霜。\n年华换，归思满沧浪。\n唤客对凝香。\n公庭凫骛散，缓行觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11050, '阮郎归', '王炎2', '几回幽梦绕家山。\n怯闻梅弄残。\n潇潇黄落客毡寒。\n不禁衣带宽。\n身外事，意阑珊。\n人间行路难。\n寻思百计不如闲。\n休贪朱两。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11051, '临江仙', '王炎2', '试问休官林下去，何人得似高年。\n壶中不记岁时迁。\n吹箫新有伴，餐玉共求仙。\n有客尊前曾得见，月眉云鬓娟娟。\n断肠刺史独无眠。\n谁能闻一曲，偷向笛中传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11052, '临江仙', '王炎2', '思忆故园花又发，等闲过了流年。\n休论升擢与平迁。\n拂衣归去好，无事即神仙。\n况是老人头雪白，羞看红粉婵娟。\n鸾孤凤只且随缘。\n莫将桃叶曲，留与世人传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11053, '水调歌头', '王炎2', '新涨鸭头绿，春满白苹洲。\n小停画，莫便折柳话离愁。\n飘渺觚棱在望，不用东风借便，一瞬到皇州。\n别酒十分酌，何惜覆瑶舟。\n从此去，上华顶，入清流。\n人门如许，自合唾手复公侯。\n老我而今衰谢，梦绕故园松菊，底事更迟留。\n早晚挂冠去，江上狎浮鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11054, '南柯子・南歌子', '王炎2', '天末家何许，津头客未归。\n柳梢绿暗早莺啼。\n蝴蝶不知春去、绕园飞。\n选胜多游冶，当垆有丽姝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11055, '好事近', '王炎2', '闲日似年长，又在他乡春暮。\n柳外一声，怨落花飞絮。\n苎罗只似旧时村，佳人在何处。\n试问鸱夷因甚，载轻颦同去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11056, '朝中措', '王炎2', '杜鹃声断日。\n过雨湿残红。\n老色菱花影里，客愁蕉叶香中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11057, '南柯子・南歌子', '王炎2', '对镜鸾休舞，求凰凤自飞。\n珠钿翠珥密封题。\n中有鸾笺细字、没人知。\n环佩灯前结，辎月下归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11058, '朝中措', '王炎2', '蔷薇露染玉肌肤。\n欲试缕金衣。\n一种出尘态度，偏宜月伴风随。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11059, '西江月', '王炎2', '蔌蔌落红都尽，依然见此清姝。\n水沈为骨玉为肤。\n留得春光少住。\n鸳帐巧藏翠幔，燕钗斜纤枝。\n休将往事更寻思。\n且为浓香一醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11060, '柳梢青', '王炎2', '葭管风微。\n莱衣香软，歌凤将雏。\n笑酌流霞，问人何处，别有瑶池。\n相将月佩霞裾。\n领凫舄、归朝玉墀。\n管取长年，进封大国，稳住清都。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11061, '踏莎行', '王炎2', '木落天寒，年华又暮。\n老来多病须调护。\n诗编酒总无缘，闲中赢得瞢腾睡。\n尘暗犀梳，香消翠被。\n悄无音信来青羽。\n新愁正上自眉峰，黄昏庭院潇潇雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11062, '清平乐', '王炎2', '一杯椒醑。\n惜饮难成醉。\n爆竹声中人未睡。\n共道今宵守岁。\n不如且就衾。\n谁能细数更筹。\n三百六旬过了，明朝却是年头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11063, '南柯子・南歌子', '王炎2', '山冥云阴重，天寒雨意浓。\n数枝幽艳湿啼红。\n莫为惜花惆怅、对东风。\n蓑笠朝朝出，沟塍处处通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11064, '夜行船', '王炎2', '淡饭粗衣随分过。\n新成就、庵寮一个。\n静处藏身，十分自在，只恁麽、有何不可。\n过眼空花都看破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11065, '临江仙', '王炎2', '一声春事了，不知苦劝谁归。\n花梢香露染蔷薇。\n小梅酸著齿，酒正堪携。\n鸭绿一篙新雨过，远山半出修眉。\n仙翁理棹欲来时。\n绕檐乌鹊喜，报与主人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11066, '蓦山溪', '王炎2', '莺啼花谢，断送春归去。\n雨後听鹃声，恰似诉、留春不住。\n韶光易迈，暗被老相催，无个事，没些愁，方是安身处。\n载松种菊，相对为宾主。\n终日掩柴扉，但只有、清风时度。\n不把酒，又不喜观书，饥时饭，饱时茶，困即睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11067, '忆秦娥', '王炎2', '头如雪。\n尘缘滚滚无休歇。\n无休歇。\n买田筑屋，是何时节。\n从今事事都休说。\n巢安寮里藏疏拙。\n藏疏拙。\n许谁为伴，溪山风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11068, '满江红', '王炎2', '宦海浮沉，名与字、不能彰彻。\n青云上、诸公衮衮，难登狭劣。\n结绶弹冠成底事，解颐折角皆虚说。\n待黄粱、梦觉始归来，非明哲。\n易消释，空中雪。\n多亏缺，天边月。\n算人生必有，衰羸时节。\n恁是一阳来复後，梅花柳眼先春发。\n料明年、又老似今年，当休歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11069, '玉楼春', '王炎2', '往年糊口谋升斗。\n朱墨尘埃粘两袖。\n黄粱梦断始归来，依旧琴书当左右。\n而今藏取持螯手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11070, '玉楼春', '王炎2', '大都四绪阴晴半。\n天上油云舒又卷。\n若还心也似云闲，老色何由来上面。\n生平辛苦今潇散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11071, '如梦令', '杨冠卿', '满院落花春寂。\n风絮一帘斜日。\n翠钿晓寒轻，独倚千秋无力。\n无力。\n无力。\n蹙破远山愁碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11072, '生查子', '杨冠卿', '娇莺恰恰啼，过水翻回去。\n欲共诉芳心，故绕池边树。\n人去绮窗闲，弦断秦筝柱。\n百啭听新声，总是伤心处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11073, '生查子', '杨冠卿', '消瘦不胜寒，独立江南路。\n罗袜暗生尘，不见凌波步。\n兰佩解鸣，往事凭谁诉。\n一纸彩云笺，好寄青鸾去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11074, '生查子', '杨冠卿', '潇湘日暮时，倚棹蒹葭浦。\n不见独醒人，愁对湘妃语。\n璧月送归云，一叶莲舟举。\n宝瑟奏清商，波底鱼龙舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11075, '浣溪沙', '杨冠卿', '洞口春深长薜萝。\n幽栖地僻少经过。\n一溪新绿涨晴波。\n惊梦觉来啼鸟近，惜春归去落花多。\n东风独倚奈愁何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11076, '浣溪沙', '杨冠卿', '银叶香销暑簟清。\n枕鸳醉倚玉钗横。\n起来红日半窗明。\n多病情怀无可奈，惜花天气恼馀酲。\n瑶琴谁弄晓莺声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11077, '霜天晓角', '杨冠卿', '渔舟簇簇。\n西塞山前宿。\n流水落红香远，春江涨、葡萄绿。\n蕲竹。\n奏新曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11078, '卜算子', '杨冠卿', '苍生喘未苏，贾笔论孤愤。\n文采风流今尚存，毫发无遗恨。\n凄恻近长沙，地僻秋将尽。\n长使英雄泪满襟，天意高难问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11079, '垂丝钓', '杨冠卿', '翠帘昼卷。\n庭花日影初转。\n酒力未醒，眉黛还敛。\n停歌扇。\n背画阑倚遍。\n情无限。\n怅韶华又晚。\n锦鞯去後，愁宽珠袖金钏。\n碧云信远。\n难托西楼雁。\n空写银筝怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11080, '菩萨蛮', '杨冠卿', '飞云障碧江天暮。\n杏花帘幕黄昏雨。\n翠袖怯春寒。\n有人愁倚阑。\n天涯芳草路。\n目送征鸿去。\n人远玉关长。\n尺书难寄将。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11081, '菩萨蛮', '杨冠卿', '春山愁对修眉绿。\n春衫谁为裁冰。\n日暮倚阑干。\n不禁烟雾寒。\n湖边归去路。\n犹记传觞处。\n往事等空花。\n客心惊岁华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11082, '菩萨蛮', '杨冠卿', '冰肌玉衬香绡薄。\n无言独倚阑干角。\n相见又还休。\n可堪归去愁。\n碧波溪上路。\n几阵黄昏雨。\n归去断人肠。\n纱厨枕簟凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11083, '菩萨蛮', '杨冠卿', '玉妃夜宴瑶池冷。\n翩然飞下霓旌影。\n天阔水云长。\n风飘舞袖香。\n姑山人似旧。\n清压红梅瘦。\n同凭玉阑干。\n光摇银海寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11084, '好事近', '杨冠卿', '晚起倦梳妆，斜压翠鬟云鬓。\n手拈花枝辄笑，问青鸾音信。\n绣帘慵卷玉钩垂，风篁奏馀韵。\n灯火黄昏院落，报雕鞍人近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11085, '好事近', '杨冠卿', '细雨落檐花，帘卷金泥红湿。\n楼外远山横翠，染修眉愁碧。\n旧游春梦了无痕，香尘暗瑶瑟。\n凭仗青鸾飞去，问新来消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11086, '谒金门', '杨冠卿', '伤漂泊。\n负了花前期约。\n寒食清明都过却。\n愁怀无处著。\n晴日柳阴池阁。\n风絮斜穿帘幕。\n帘外秋千闲彩索。\n断肠人寂寞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11087, '忆秦娥', '杨冠卿', '东风恶。\n雪花乱舞穿帘幕。\n穿帘幕。\n寒侵绿绮，音断弦索。\n宫梅已破香红萼。\n梅妆想称伊梳掠。\n伊梳掠。\n十分全似，旧时京洛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11088, '忆秦娥', '杨冠卿', '云垂幕。\n江天雪似杨花落。\n杨花落。\n翠衾不暖，晓寒偏觉。\n起来独倚西楼角。\n客怀无耐伤离索。\n伤离索。\n蛮笺欲寄，塞鸿难托。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11089, '清平乐', '杨冠卿', '翠团嘉树。\n杜宇呼春去。\n帘卷金泥凝望处。\n几点红薇香雨。\n等闲过了花时。\n殷勤来问酴。\n恰有一枝春在，画楼红日林西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11090, '柳梢青', '杨冠卿', '红药翻阶。\n天香国艳，辉映楼台。\n解语浑如，三千粉黛，十二金钗。\n青鞋踏破苍苔。\n趁舞蝶、游蜂去来。\n宿粉偷香，也应难似，年少情怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11091, '柳梢青', '杨冠卿', '金蕊飘残。\n江城秋晚，月冷霜寒。\n一种幽芳，雕冰镂玉，舞凤翔鸾。\n悠然静对南山。\n笑琼沼、鸳飞翠澜。\n小玉惊呼，太真娇困，俯槛慵看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11092, '柳梢青', '杨冠卿', '归梦迢迢。\n分明曾见，舞遍云韶。\n解道相思，愁宽金钏，瘦损宫腰。\n觉来情绪无聊。\n正戍角、声翻丽谯。\n楚塞山长，巫阳人远，斗帐香消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11093, '西江月', '杨冠卿', '妙墨龙蛇飞动，新词雪月交光。\n论文齿颊带冰霜。\n凤阁从来宫样。\n寿菊丛开三径，清姿高压群芳。\n折花聊尔问行藏。\n会见横飞直上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11094, '西江月', '杨冠卿', '罗袜浪传仙子，宫梅休写华光。\n人言寿客饱经霜。\n不趁凡花入样。\n万玉森罗素节，一枝剩有馀芳。\n孤高肯使蝶蜂藏。\n特立甘泉顶上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11095, '西江月', '杨冠卿', '昨梦钧天帝所，曾陪奏赋明光。\n玉除金蕊映秋霜。\n尽道宫花别样。\n娇额涂黄牢就，金莲衬步齐芳。\n舞鸾仪凤巧难藏。\n羞杀繁红陌上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11096, '东坡引', '杨冠卿', '绿波芳草路。\n别离记南浦。\n香云翦赠青丝缕。\n钗分金半股。\n钗分金半股。\n阳关一曲声凄楚。\n惹起离筵愁绪。\n梦魂拟逐征鸿去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11097, '鹧鸪天', '杨冠卿', '岁月如驰乌兔飞。\n情怀著酒强支持。\n经年不见宫妆面，碧谁斟翡翠卮。\n江路晚，夕阳低。\n奚奴空负锦囊归。\n欲凭驿使传芳信，未放东风第一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11098, '小重山', '杨冠卿', '一笑回眸百媚生。\n娇羞佯不语，艳波横。\n缓移莲步绕阶行。\n凝情久，幽怨托银筝。\n些事那回曾。\n水晶双枕冷，簟纹平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11099, '蝶恋花', '杨冠卿', '舞处曾看花满面。\n独倚东风，往事思量遍。\n绿怨红愁春不管。\n天涯芳草人肠断。\n一纸云笺鱼雁远。\n归凤求凰，谁识琴心怨。\n臂枕香消眉黛敛。\n也应为我宽金钏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11100, '蝶恋花', '杨冠卿', '月冷花寒宫漏促。\n人在虚檐，玉体温无粟。\n弦断鸾胶还再续。\n娇云时霎情难足。\n解道双鸳愁独宿。\n宿翠偎红，蛱蝶元相逐。\n蓬海路遥天六六。\n终须伴我骑黄鹄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11101, '水调歌头', '杨冠卿', '春涨一篙绿，江阔暮涛寒。\n龙骧万斛飞举，鲸饮酒杯宽。\n醉倚舵楼清啸，目送孤鸿杳霭，景意与俱闲。\n恍若驭风去，蓬岛旧家山。\n记吾庐，环翠竹，拱苍官。\n碧云信杳，谁为日日报平安。\n桂棹桃溪归後，流水落红香寂，春事想阑珊。\n赖有锦囊句，写向此中看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11102, '水调歌头', '杨冠卿', '形胜访淮楚，骑鹤到扬州。\n春风十里帘幕，香霭小红楼。\n楼外长江今古，谁是济川舟楫，烟浪拍天浮。\n喜见紫芝宇，儒雅更风流。\n气吞虹，才倚马，烂银钩。\n功名年少馀事，雕鹗几横秋。\n行演丝纶天上，环倚玉皇香案，仙袂揖浮丘。\n落笔惊风雨，润色焕皇猷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11103, '水调歌头', '杨冠卿', '年少青云客，怀抱百忧宽。\n北窗醉卧春晓，归梦趁吴帆。\n来访鸱夷仙迹，极目平湖烟浪，万象一毫端。\n云海渺空阔，咫尺是蓬山。\n佩飞霞，囊古锦，几凭阑。\n赤城应有居士，凤举更龙蟠。\n待向玉霄东望，相与神游八极，身未似云闲。\n长剑倚天外，功业镜频看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11104, '水调歌头', '杨冠卿', '曳杖罗浮去，辽鹤正南翔。\n青鸾为报消息，岩壑久相望。\n无奈渔溪乃，唤起苹洲昨梦，风雨趁归航。\n万里家何许，天阔水云长。\n历五湖，转湘楚，下三江。\n兴亡千古馀恨，收拾付诗囊。\n重到然犀矶渚，不见骑鲸仙子，客意转凄凉。\n举酒酹江月，襟袖泪淋浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11105, '水龙吟', '杨冠卿', '渡江天马龙飞，翠华小住兴王地。\n石城锺阜，雄依天堑，鼎安神器。\n鹊楼高，建章宫阔，玉绳低坠。\n望郁葱佳气，非烟非雾，方呈瑞、璇霄际。\n貔虎云屯羽卫。\n壮金汤、更隆国势。\n天骄胆落，狼烽昼熄，玉门晏闭。\n祗谒陵园，长安□远，中兴可冀。\n笑六朝旧事，空随流水，千古恨、无人记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11106, '贺新郎', '杨冠卿', '薄暮垂虹去。ピ\n正江天、残霞冠日，乱鸿遵渚。ピ\n万顷云涛风浩荡，笑整羽轮飞渡。ピ\n问弱水、神仙何处。ピ\n翳凤骑麟思往事，记朝元、金殿闻钟鼓。ピ\n环佩响，翠鸾舞。ピ\n梦中失却江南路。ピ\n待西风、长城饮马，朔庭张弩。ピ\n目尽青天何时到，赢得儿童好语。ピ\n怅未复、长陵土。ピ\n西子五湖归去後，泛仙舟、尚许寻盟否。ピ\n风袂逐，片帆举。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11107, '六州', '崔敦诗', '商秋吉，嘉会协中辛。\n涓路寝，修祀，圣德昭清。\n端志虑，罄竭斋精。\n锦绣排天仗，羽卫滨纷。\n朝太室、返中宸。\n被衮接神明。\n时平天时俱清晏，兼丰年和气，品物达芳馨。\n瞻座，舂容燕三灵。\n奠瑶爵，荐量币，清思呦冥冥。\n望昆仑。\n嘉祥塞。\n诚殚礼洽庆休成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11108, '十二时・忆少年', '崔敦诗', '勋华并、天胙昌期。\n圣德茂重离。\n英明经远，浚哲昭微。\n宝俭更深慈。\n观万国、累洽重熙。\n对明时。\n报礼秩神祗。\n玉帛奏华夷。\n雍肃显相，百辟各钦祗。\n奄嘉虞英璧奠华滋。\n神安坐、景气澄虚。\n极光焰、烛长丽。\n展诗应律，万舞逶迟。\n三献洽皇仪。\n垂露浸庆祜来宜。\n礼无违。\n鸣鸾临帝阙，飞凤下天倪。\n清和寰宇，霈泽一朝驰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11109, '柳梢青', '赵汝愚', '水月光中，烟霞影里，涌出楼台。\n空外笙箫，云间笑语，人在蓬莱。\n天香暗逐风回。\n正十里、荷花盛开。\n买个扁舟，山南游遍，山北归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11110, '摸鱼儿', '辛弃疾', '更能消、几番风雨。\n匆匆春又归去。\n惜春长恨花开早，何况落红无数。\n春且住。\n见说道、天涯芳草迷归路。\n怨春不语。\n算只有殷勤，画檐珠网，尽日惹飞絮。\n长门事，准拟佳期又误。\n蛾眉曾有人妒。\n千金纵买相如赋，脉脉此情谁诉。\n君莫舞。\n君不见、玉环飞燕皆尘土。\n闲愁最苦。\n休去倚危楼，斜阳正在，烟柳断肠处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11111, '摸鱼儿', '辛弃疾', '望飞来、半空鸥鹭。\n须臾动地鼙鼓。\n截江组练驱山去，鏖战未收貔虎。\n朝又暮。\n诮惯得、吴儿不怕蛟龙怒。\n风波平步。\n看红旆惊飞，跳鱼直上，蹙踏浪花舞。\n凭谁问，万里长鲸吞吐。\n人间儿戏千弩。\n滔天力倦知何事，白马素车东去。\n堪恨处。\n人道是、子胥冤愤终千古。\n功名自误。\n谩教得陶朱，五湖西子，一舸弄烟雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11112, '沁园春', '辛弃疾', '三径初成，鹤怨猿惊，稼轩未来。\n甚云山自许，平生意气，衣冠人笑，抵死尘埃。\n意倦须还，身闲贵早，岂为莼羹鲈哉。\n秋江上，看惊弦雁避，骇浪船回。\n东冈更葺茅斋。\n好都把轩窗临水开。\n要小舟行钓，先应种柳，疏篱护竹，莫碍观梅。\n秋菊堪餐，春兰可佩，留待先生手自栽。\n沈吟久，怕君恩未许，此意徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11113, '沁园春', '辛弃疾', '伫立潇湘，黄鹄高飞，望君不来。\n被东风吹堕，西江对语，急呼斗酒，旋拂征埃。\n却怪英姿，有如君者，犹欠封侯万里哉。\n空赢得，道江南佳句，只有方回。\n锦帆画舫行斋。\n怅雪浪粘天江影开。\n记我行南浦，送君折柳，君逢驿使，为我攀梅。\n落帽山前，呼鹰台下，人道花须满县栽。\n都休问，看云霄高处，鹏翼徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11114, '水龙吟', '辛弃疾', '渡江天马南来，几人真是经纶手。\n长安父老，新亭风景，可怜依旧。\n夷甫诸人，神州沈陆，几曾回首。\n算平戎万里，功名本是，真儒事、君知否。\n况有文章山斗。\n对桐阴、满庭清昼。\n当年堕地，而今试看，风云奔走。\n绿野风烟，平泉草木，东山歌酒。\n待他年，整顿乾坤事了，为先生寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11115, '水龙吟', '辛弃疾', '玉皇殿阁微凉，看公重试薰风手。\n高门画戟，桐阴阁道，青青如旧。\n兰佩芳空，蛾眉谁妒，无言搔首。\n甚年年却有，呼韩塞上，人争问、公安否。\n金印明年如斗。\n向中州、锦衣行昼。\n依然盛事，貂蝉前後，凤麟飞走。\n富贵浮云，我评轩冕，不如杯酒。\n待从公，痛饮八千馀岁，伴庄椿寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11116, '水龙吟', '辛弃疾', '楚天千里清秋，水随天去秋无际。\n遥岑远目，献愁供恨，玉簪螺髻。\n落日楼头，断鸿声里，江南游子。\n把吴钩看了，栏干拍遍，无人会、登临意。\n休说鲈鱼堪。\n尽西风、季鹰归未。\n求田问舍，怕应羞见，刘郎才气。\n可惜流年，忧愁风雨，树犹如此。\n倩何人，唤取盈盈翠袖，英雄泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11117, '满江红', '辛弃疾', '笳鼓归来，举鞭问、何如诸葛。\n人道是、匆匆五月，渡泸深入。\n白羽风生貔虎噪，青溪路断猩鼯泣。\n早红尘、一骑落平冈，捷书急。\n三万卷，龙韬客。\n浑未得，文章力。\n把诗书马上，笑驱锋镝。\n金印明年如斗大，貂蝉却自兜鍪出。\n待刻公、勋业到□云，浯溪石。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11118, '满江红', '辛弃疾', '瘴雨蛮烟，十年梦、尊前休说。\n春正好、故园桃李，待君花发。\n儿女灯前和泪拜，鸡豚社里归时节。\n看依然、舌在齿牙牢，心如铁。\n治国手，封侯骨。\n腾汉漫，排阊阖。\n待十分做了，诗书勋业。\n常日念君归去好，而今却恨中年别。\n笑江头、明月更多情，今宵缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11119, '满江红', '辛弃疾', '蜀道登天，一杯送、绣衣行客。\n还自叹、中年多病，不堪离别。\n东北看惊诸葛表，西南更草相如檄。\n把功名、收拾付君侯，如椽笔。\n儿女泪，君休滴。\n荆楚路，吾能说。\n要新诗准备，庐江山色。\n赤壁矶头千古浪，铜陌上三更月。\n正梅花、万里雪深时，须相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11120, '满江红', '辛弃疾', '快上西楼，怕天放、浮云遮月。\n但唤取、玉纤横笛，一声吹裂。\n谁做冰壶浮世界，最怜玉斧修时节。\n问常娥、孤冷有愁无，应华发。\n云液满，琼杯滑。\n长袖起，清歌咽。\n叹十常八九，欲磨还缺。\n若得长圆如此夜，人情未必看承别。\n把从前、离恨总成欢，归时说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11121, '满江红', '辛弃疾', '鹏翼垂空，笑人世、苍然无物。\n还又向、九重深处，玉阶山立。\n袖里珍奇光五色，他年要补天西北。\n且归来、谈笑护长江，波澄碧。\n佳丽地，文章伯。\n金缕唱，红牙拍。\n看尊前飞下，日边消息。\n料想宝香黄阁梦，依然画舫青溪笛。\n待如今、端的约锺山，长相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11122, '满江红', '辛弃疾', '落日苍茫，风才定、片帆无力。\n还记得、眉来眼去，水光山色。\n倦客不知身近远，佳人已卜归消息。\n便归来、只是赋行云，襄王客。\n些个事，如何得。\n知有恨，休重忆。\n但楚天特地，暮云凝碧。\n过眼不如人意事，十常八九今头白。\n笑江州、司马太多情，青衫湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11123, '满江红', '辛弃疾', '过眼溪山，怪都似、旧时曾识。\n是梦里、寻常行遍，江南江北。\n佳处径须携杖去，能消几两平生屐。\n笑尘埃、三十九年非，长为客。\n吴楚地，东南拆。\n英雄事，曹刘敌。\n被西风吹尽，了无陈迹。\n楼观才成人已去，旌旗未卷头先白。\n叹人间、哀乐转相寻，今犹昔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11124, '满江红', '辛弃疾', '湖海平生，算不负、苍髯如戟。\n闻道是、君王著意，太平长策。\n此老自当兵十万，长安正在天西北。\n便凤凰、飞诏下天来，催归急。\n车马路，儿童泣。\n风雨暗，旌旗湿。\n看野梅官柳，东风消息。\n莫向蔗庵追语笑，只今松竹无颜色。\n问人间、谁管别离愁，杯中物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11125, '满江红', '辛弃疾', '笑拍洪崖，问千丈、翠岩谁削。\n依旧是、西风白马，北村南郭。\n似整复斜僧屋乱，欲吞还吐林烟薄。\n觉人间、万事到秋来，都摇落。\n呼斗酒，同君酌。\n□小隐，寻幽约。\n且丁宁休负，北山猿鹤。\n有鹿从渠求鹿梦，非鱼定未知鱼乐。\n正仰看、飞鸟却应人，回头错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11126, '满江红', '辛弃疾', '曲几蒲团，方丈里、君来问疾。\n更夜雨、匆匆别去，一杯南北。\n万事莫侵闲鬓发，百年正要佳眠食。\n最难忘、此语重殷勤，千金直。\n西崦路，东岩石。\n携手处，今陈迹。\n望重来犹有，旧盟如日。\n莫信蓬莱风浪隔，垂天自有扶摇力。\n对梅花、一夜苦相思，无消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11127, '水调歌头', '辛弃疾', '带湖吾甚爱，千丈翠奁开。\n先生杖屦无事，一日走千回。\n凡我同盟鸥鸟，今日既盟之後，来往莫相猜。\n白鹤在何处，尝试与偕来。\n破青萍，排翠藻，立苍苔。\n窥鱼笑汝痴计，不解举吾杯。\n废沼荒丘畴昔，明月清风此夜，人世几欢哀。\n东岸绿阴少，杨柳更须栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11128, '水调歌头', '辛弃疾', '白日射金阙，虎豹九关开。\n见君谏疏频上，高论挽天回。\n千古忠肝义胆，万里蛮烟瘴雨，往事莫惊猜。\n政恐不免耳，消息日边来。\n笑吾庐，门掩草，径封苔。\n未应两手无用，要把蟹螯杯。\n说剑论诗馀事，醉舞狂歌欲倒，老子颇堪哀。\n白发宁有种，一一醒时栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11129, '水调歌头', '辛弃疾', '折尽武昌柳，挂席上潇湘。\n二年鱼鸟江上，笑我往来忙。\n富贵何时休问，离别中年堪恨，憔悴鬓成霜。\n丝竹陶写耳，急羽且飞觞。\n序兰亭，歌赤壁，绣衣香。\n使君千骑鼓吹，风采汉侯王。\n莫把骊驹频唱，可惜南楼佳处，风月已凄凉。\n在家贫亦好，此语试平章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11130, '水调歌头', '辛弃疾', '今日复何日，黄菊为谁开。\n渊明漫爱重九，胸次正崔嵬。\n酒亦关人何事，正自不能不尔，谁遣白衣来。\n醉把西风扇，随处障尘埃。\n为公饮，须一日，三百杯。\n此山高处东望，云气见蓬莱。\n翳凤骖鸾公去，落佩倒冠吾事，抱病且登台。\n归路有明月，人影共徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11131, '水调歌头', '辛弃疾', '君莫赋幽愤，一语试相开。\n长安车马道上，平地起崔嵬。\n我愧渊明久矣，独借此翁湔洗，素壁写归来。\n斜日透虚隙，一线万飞埃。\n断吾生，左持蟹，右持杯。\n买山自种云树，山下烟莱。\n百炼都成绕指，万事直须称好，人世几舆台。\n刘郎更堪笑，刚赋看花回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11132, '水调歌头', '辛弃疾', '造物故豪纵，千里玉鸾飞。\n等闲更把，万斛琼粉盖颇黎。\n好卷垂虹千丈，只放冰壶一色，云海路应迷。\n老子旧游处，回首梦耶非。\n谪仙人，鸥鸟伴，两忘机。\n掀髯把酒一笑，诗在片帆西。\n寄语烟波旧侣，闻道莼鲈正美，休制芰荷衣。\n上界足官府，汗漫与君期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11133, '水调歌头', '辛弃疾', '落日塞尘起，胡骑猎清秋。\n汉家组练十万，列舰耸高楼。\n谁道投鞭飞渡，忆昔鸣血污，风雨佛狸愁。\n季子正年少，匹马黑貂裘。\n今老矣，搔白首，过扬州。\n倦游欲去江上，手种橘千头。\n二客东南名胜，万卷诗书事业，尝试与君谋。\n莫射南山虎，直觅富民侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11134, '水调歌头', '辛弃疾', '万事到白发，日月几西东。\n羊肠九折歧路，老我惯经从。\n竹树前溪风月，鸡酒东家父老，一笑偶相逢。\n此乐竟谁觉，天外有冥鸿。\n味平生，公与我，定无同。\n玉堂金马，自有佳处著诗翁。\n好锁云烟窗户，怕入丹青图画，飞去了无踪。\n此语更痴绝，真有虎头风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11135, '水调歌头', '辛弃疾', '上古八千岁，才是一春秋。\n不应此日，刚把七十寿君侯。\n看取垂天云翼，九万里风在下，与造物同游。\n君欲计岁月，当试问庄周。\n醉淋浪，歌窈窕，舞温柔。\n从今杖屦南涧，白日为君留。\n闻道钧天帝所，频上玉卮春酒，冠拥龙楼。\n快上星辰去，名姓动金瓯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11136, '贺新郎', '辛弃疾', '云卧衣裳冷。\n看萧然、风前月下，水边幽影。\n罗袜尘生凌波去，汤沐烟江万顷。\n爱一点、娇黄成晕。\n不记相逢曾解佩，甚多情、为我香成阵。\n待和泪，收残粉。\n灵均千古怀沙恨。\n□当时、匆匆忘把，此仙题品。\n烟雨凄迷损，翠袂摇摇谁整。\n谩写入、瑶琴幽愤。\n弦断招魂无人赋，但金杯的银台润。\n愁酒，又独醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11137, '念奴娇', '辛弃疾', '兔园旧赏，怅遗踪、飞鸟千山都绝。\n缟带银杯江上路，惟有南枝香别。\n万事新奇，青山一夜，对我头先白。\n倚岩千树，玉龙飞上琼阙。\n莫惜雾鬓风鬟，试教骑鹤，去约尊前月。\n自与诗翁磨冻砚，看扫幽兰新阙。\n便拟□□，人间挥汗，留取层冰洁。\n此君何事，晚来还易腰折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11138, '念奴娇', '辛弃疾', '对花何似，似吴宫初教，翠围红阵。\n欲笑还愁羞不语，惟有倾城娇韵。\n翠盖风流，牙签名字，旧赏那堪省。\n天香染露，晓来衣润谁整。\n最爱弄玉团酥，就中一朵，曾入扬州咏。\n华屋金盘人未醒，燕子飞来春尽。\n最忆当年，沈香亭北，无限春风恨。\n醉中休问，夜深花睡香冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11139, '念奴娇', '辛弃疾', '我来吊古，上危楼、赢得闲愁千斛。\n虎踞龙蟠何处是，只是兴亡满目。\n柳外斜阳，水边归鸟，陇上吹乔木。\n片帆西去，一声谁喷霜竹。\n却忆安石风流，东山岁晚，泪落哀筝曲。\n儿辈功名都付与，长日惟消棋局。\n宝镜难寻，碧云将暮，谁劝杯中绿。\n江头风怒，朝来波浪翻屋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11140, '念奴娇', '辛弃疾', '野棠花落，又匆匆、过了青明时节。\n地东风欺客梦，一夜云屏寒怯。\n曲岸持觞，垂杨系马，此地曾轻别。\n楼空人去，旧游飞燕能说。\n闻道绮陌东头，行人长见，帘底纤纤月。\n旧恨春江流未断，新恨云山千叠。\n料得明朝，尊前重见，镜里花难折。\n也应惊问，近来多少华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11141, '念奴娇', '辛弃疾', '晚风吹雨，战新荷、声乱明珠苍璧。\n谁把香奁收宝镜，云锦红涵湖碧。\n飞鸟翻空，游鱼吹浪，惯趁笙歌席。\n坐中豪气，看公一饮千石。\n遥想处士风流，鹤随人去，老作飞仙伯。\n茅舍疏篱今在否，松竹已非畴昔。\n欲说当年，望湖楼下，水与云宽窄。\n醉中休问，断肠桃叶消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11142, '念奴娇', '辛弃疾', '近来何处有吾愁，何处还知吾乐。\n一点凄凉千古意，独倚西风寥廓。\n并竹寻泉，和云种树，唤做真闲客。\n此心闲处，不应长藉邱壑。\n休说往事皆非，而今云是，且把清尊酌。\n醉里不知谁是我，非月非云非鹤。\n冷露风高，松梢桂子，醉了还醒却。\n北窗高卧，莫教啼鸟惊著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11143, '新荷叶', '辛弃疾', '人已归来，杜鹃欲劝谁归。\n绿树如云，等闲借与莺飞。\n兔葵燕梦，问刘郎、几度沾衣。\n翠屏幽梦，觉来水绕山围。\n有酒重携。\n小园随意芳菲。\n往日繁华，而今物是人非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11144, '新荷叶', '辛弃疾', '春色如愁，行云带雨才归。\n春意长闲，游丝尽日低飞。\n闲愁几许，更晚风、特地吹衣。\n小窗人静，棋声似解重围。\n光景难携。\n任他芳菲。\n细数从前，不应诗酒皆非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11145, '最高楼', '辛弃疾', '长安道，投老倦游归。\n七十古来稀。\n藕花雨湿前湖夜，桂枝风澹小山时。\n怎消除，须酒，更吟诗。\n也莫向、竹边孤负雪。\n也莫向、柳边孤负月。\n闲过了，总成痴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11146, '最高楼', '辛弃疾', '西园买，谁载万金归。\n多病胜游稀。\n风斜画烛天香夜，凉生翠盖酒酣时。\n待重寻，居士谱，谪仙诗。\n看黄底、御袍元自贵。\n看红底、状元新得意。\n如斗大，只花痴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11147, '洞仙歌', '辛弃疾', '江头父老，说新来朝野。\n都道今年太平也。\n见朱颜绿鬓，玉带金鱼，相公是，旧日中朝司马。\n遥知宣劝处，东阁华灯，别赐仙韶接元夜。\n问天上、几多春，只是人间，但长见、精神如画。\n好都取、山河献君王，看父子貂蝉，玉京迎驾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11148, '洞仙歌', '辛弃疾', '飞流万壑，共千岩争秀。\n孤负平生弄泉手。\n叹轻衫短帽，几许红尘，还自喜，濯发沧浪依旧。\n人生行乐耳，身後虚名，何似生前一杯酒。\n便此地、结吾庐，待学渊明，更手种、门前五柳。\n且归去、父老约重来，问如此青山，定重来否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11149, '八声甘州', '辛弃疾', '把江山好处付公来，金陵帝王州。\n想今年燕子，依然认得，王谢风流。\n只用平时尊俎，弹压万貔貅。\n依旧钧天梦，玉殿东头。\n看取黄金横带，是明年准拟，丞相封侯。\n有红梅新唱，香阵卷温柔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11150, '声声慢', '辛弃疾', '开元盛日，天上栽花，月殿桂影重重。\n十里芬芳，一枝金粟玲珑。\n管弦凝碧池上，记当时、风月愁侬。\n翠华远，但江南草木，烟锁深宫。\n只为天姿冷澹，被西风酝酿，彻骨香浓。\n枉学丹蕉，叶展偷染娇红。\n道人取次装束，是自家、香底家风。\n又怕是，为凄凉、长在醉中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11151, '江神子・江城子', '辛弃疾', '梅梅柳柳斗纤。\n乱山中。\n为谁容。\n试著春衫，依旧怯东风。\n何处踏青人未去，呼女伴，认骄骢。\n儿家门户几重重。\n记相逢。\n画桥东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11152, '江神子・江城子', '辛弃疾', '玉箫声远忆骖鸾。\n几悲欢。\n带罗宽。\n且对花前，痛饮莫留残。\n归去小窗明月在，云一缕，玉千竿。\n吴霜应点鬓云斑。\n绮窗闲。\n梦连环。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11153, '江神子・江城子', '辛弃疾', '一川松竹任横斜。\n有人家。\n被云遮。\n雪後疏梅，时见两三花。\n比□桃源溪上路，风景好，不争多。\n旗亭有酒径须赊。\n晚寒些。\n怎禁他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11154, '江神子・江城子', '辛弃疾', '剩云残日弄阴晴。\n晚山明。\n小溪横。\n枝上绵蛮，休作断肠声。\n但是青山山下路，春到处，总堪行。\n当年彩笔赋芜城。\n忆平生。\n若为情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11155, '六么令', '辛弃疾', '酒群花队，攀得短辕折。\n谁怜故山归梦，千里莼羹滑。\n便整松江一棹，点检能言鸭。\n故人欢接。\n醉怀双橘，堕地金圆醒时觉。\n长喜刘郎马上，肯听诗书说。\n谁对叔子风流，直把曹刘压。\n更看君侯事业，不负平生学。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11156, '六么令', '辛弃疾', '倒冠一笑，华发玉簪折。\n阳关自来凄断，却怪歌声滑。\n放浪儿童归舍，莫恼比邻鸭。\n水连山接。\n看君归兴，如醉中醒、梦中觉。\n江上吴侬问我，一一烦君说。\n坐客尊酒频空，剩欠真珠压。\n手把鱼竿未稳，长向沧浪学。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11157, '满庭芳', '辛弃疾', '急管哀弦，长歌慢舞，连娟十样宫眉。\n不堪红紫，风雨晓来稀。\n惟有杨花飞絮，依旧是、萍满芳池。\n酴在，青虬快剪，插遍古铜彝。\n谁将春色去，鸾胶难觅，弦断朱丝。\n恨牡丹多病，也费医治。\n梦里寻春不见，空肠断、怎得春知。\n休惆怅，一觞一咏，须刻右军碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11158, '满庭芳', '辛弃疾', '柳外寻春，花边得句，怪公喜气轩眉。\n阳春白雪，清唱古今稀。\n曾是金銮旧客，记凤凰、独绕天池。\n挥毫罢，天颜有喜，催赐上方彝。\n只今江海上，钧天梦觉，清泪如丝。\n算除非，痛把酒疗花治。\n明日五湖佳兴，扁舟去、一笑谁知。\n溪堂好，且拼一醉，倚杖读韩碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11159, '鹧鸪天', '辛弃疾', '一榻清风殿影凉。\n涓涓流水响回廊。\n千章云木钩叫，十里溪风香。\n冲急雨，趁斜阳。\n山园细路转微茫。\n倦途却被行人笑，只为林泉有底忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11160, '鹧鸪天', '辛弃疾', '晚日寒鸦一片愁。\n柳塘新绿却温柔。\n若教眼底无离恨，不信人间有白头。\n肠已断，泪难收。\n相思重上小红楼。\n情知已被山遮断，频倚阑干不自由。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11161, '鹧鸪天', '辛弃疾', '翠竹千寻上薜萝。\n东湖经雨又增波。\n只因买得青山好，却恨归来白发多。\n明画烛，洗金荷。\n主人起舞客齐歌。\n醉中只恨欢娱少，明日醒时奈病何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11162, '鹧鸪天', '辛弃疾', '唱彻阳关泪未乾。\n功名馀事且加餐。\n浮天水送无穷树，带雨云埋一半山。\n今古恨，几千般。\n只应离合是悲欢。\n江头未是风波恶，别有人间行路难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11163, '鹧鸪天', '辛弃疾', '扑面征尘去路遥。\n香篝渐觉水沈销。\n山无重数周遭碧，花不知名分外娇。\n人历历，马萧萧。\n笙旗又过小红桥。\n愁边剩有相思句，摇断吟鞭碧玉梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11164, '鹧鸪天', '辛弃疾', '枕簟溪堂冷欲秋。\n断云依水晚来收。\n红莲相倚浑如醉，白鸟无言定自愁。\n书咄咄，且休休。\n一丘一壑也风流。\n不知筋力衰多少，但觉新来懒上楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11165, '丑奴儿・采桑子', '辛弃疾', '千峰云起，骤雨一霎时价。\n更远树斜阳，风景怎生图画。\n青旗卖酒，山那畔、别有人间，只消山水光中，无事过这一夏。\n午醉醒时，松窗竹户，万千潇洒。\n野鸟飞来，又是一般闲暇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11166, '蝶恋花', '辛弃疾', '衰草残阳三万顷。\n不算飘零，天外孤鸿影。\n几许凄凉须痛饮。\n行人自向江头醒。\n会少离多看两鬓。\n万缕千丝，何况新来病。\n不是离愁难整顿。\n被他引惹其他恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11167, '蝶恋花', '辛弃疾', '点检笙歌多酿酒。\n蝴蝶西园，暖日明花柳。\n醉倒东风眠永昼。\n觉来小院重携手。\n可惜春残风雨又。\n收拾情怀，长把诗。\n杨柳见人离别後。\n腰肢近日和他瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11168, '蝶恋花', '辛弃疾', '九畹芳菲兰佩好。\n空谷无人，自怨蛾眉巧。\n宝瑟泠泠千古调。\n朱丝弦断知音少。\n冉冉年华吾自老。\n水满汀洲，何处寻芳草。\n唤起湘累歌未了。\n石龙舞罢松风晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11169, '蝶恋花', '辛弃疾', '小小华年才月半。\n罗幕春风，幸自无人见。\n刚道羞郎低粉面。\n傍人瞥见回娇盼。\n昨夜西池陪女伴。\n柳困花慵，见说归来晚。\n劝客持觞浑未惯。\n未歌先觉花枝颤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11170, '定风波', '辛弃疾', '少日春怀似酒浓。\n插花走马醉千锺。\n老去逢春如病酒。\n唯有。\n茶瓯香篆小帘栊。\n卷尽残花风未定。\n休恨。\n花开元自要春风。\n试问春归谁得见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11171, '临江仙', '辛弃疾', '老去惜花心已懒，爱梅犹绕江村。\n一枝先破玉溪春。\n更无花态度，全有雪精神。\n剩向空山餐秀色，为渠著句清新。\n竹根流水带溪云。\n醉中浑不记，归路月黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11172, '临江仙', '辛弃疾', '莫向空山吹玉笛，壮怀酒醒心惊。\n四更霜月太寒生。\n被翻红锦浪，酒满玉壶冰。\n小陆未须临水笑，山林我辈锺情。\n今宵依旧醉中行。\n试寻残菊处，中路侯渊明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11173, '临江仙', '辛弃疾', '锺鼎山林都是梦，人间荣辱休惊。\n只消闲处过平生。\n酒杯秋吸露，诗句夜裁冰。\n记取小窗风雨夜，对床灯火多情。\n问谁千里伴君行。\n晚山眉样翠，秋水镜般明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11174, '菩萨蛮', '辛弃疾', '稼轩日向儿童说。\n带湖买得新风月。\n头白早归来。\n种花花已开。\n功名浑是错。\n更莫思量着。\n见说小楼东。\n好山千万重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11175, '菩萨蛮', '辛弃疾', '郁孤台下清江水。\n中间多少行人泪。\n西北是长安。\n可怜无数山。\n青山遮不住。\n毕竟江流去。\n江晚正愁予。\n山深闻鹧鸪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11176, '菩萨蛮', '辛弃疾', '无情最是江头柳。\n长条折尽还依旧。\n木叶下平湖。\n雁来书有无。\n雁无书尚可。\n妙语凭谁和。\n风雨断肠时。\n小山生桂枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11177, '菩萨蛮', '辛弃疾', '青山欲共高人语。\n联翩万马来无数。\n烟雨却低回。\n望来终不来。\n人言头上发。\n总向愁中白。\n拍手笑沙鸥。\n一身都是愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11178, '菩萨蛮', '辛弃疾', '香浮乳酪玻璃碗。\n年年醉里尝新惯。\n何物比春风。\n歌唇一点红。\n江湖清梦断。\n翠笼明光殿。\n万颗写轻匀。\n低头愧野人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11179, '西河', '辛弃疾', '西江水。\n道是西风人泪。\n无情却解送行人，月明千里。\n从今日日倚高楼，伤心烟树如荠。\n会君难，别君易。\n草草不如人意。\n十年著破绣衣茸，种成桃李。\n问君可是厌承明，东方鼓吹千骑。\n对梅花、更消一醉。\n有明年、调鼎风味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11180, '木兰花慢', '辛弃疾', '汉中开汉业，问此地、是耶非。\n想剑指三秦，君王得意，一战东归。\n追亡事、今不见，但山川满目泪沾衣。\n落日胡尘未断，西风塞马空肥。\n一编书是帝王师。\n小试去征西。\n更草草离筵，匆匆去路，愁满旌旗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11181, '木兰花慢', '辛弃疾', '老来情味减，对别酒、怯流年。\n况屈指中秋，十分好月，不照人圆。\n无情水、都不管，共西风、只等送归船。\n秋晚莼鲈江上，夜深儿女灯前。\n征衫。\n便好去朝天。\n玉殿正思贤。\n想夜半承明，留教视草，却遣筹边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11182, '朝中措', '辛弃疾', '绿萍池沼絮飞忙。\n花入蜜脾香。\n长怪春归何处，谁知个里迷藏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11183, '朝中措', '辛弃疾', '篮舆袅袅破重冈。\n玉笛两红妆。\n这里都愁酒尽，那边正和诗忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11184, '祝英台令', '辛弃疾', '宝钗分，桃叶渡。\n烟柳暗南浦。\n怕上层楼，十日九风雨。\n断肠片片飞红，都无人管，倩谁唤、流莺声住。\n鬓边觑。\n试把花卜心期，才簪又重数。\n罗帐灯昏，呜咽梦中语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11185, '乌夜啼', '辛弃疾', '江头醉倒山公。\n月明中。\n记得昨宵归路、笑儿童。\n溪欲转。\n山已断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11186, '乌夜啼', '辛弃疾', '人言我不如公。\n酒频中。\n更把平生湖海、问儿童。\n千尺蔓。\n云叶乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11187, '鹊桥仙', '辛弃疾', '朱颜晕酒，方瞳点漆，闲傍松边倚杖。\n不须更展画图看，自是个、寿星模样。\n今朝盛事，一杯深劝，更把新诗齐唱。\n人间八十最风流，长帖在、儿儿额上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11188, '太常引', '辛弃疾', '君王著意履声间。\n便令押、紫宸班。\n今代又尊韩。\n道吏部、文章泰山。\n一杯千岁，问公何事，早伴赤松闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11189, '昭君怨', '辛弃疾', '长记潇湘秋晚。\n歌舞橘洲人散。\n走马月明中。\n折芙蓉。\n今日西山南浦。\n画栋珠帘云雨。\n风景不争多。\n奈愁何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11190, '采桑子', '辛弃疾', '烟迷露麦荒池柳，洗雨烘晴。\n洗雨烘晴。\n一样春风几样青。\n提壶脱裤催归去，万恨千情。\n万恨千情。\n各自无聊各自鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11191, '杏花天', '辛弃疾', '病来自是於春懒。\n但别院、笙歌一片。\n蛛丝网遍玻璃盏。\n更问舞裙歌扇。\n有多少、莺愁蝶怨。\n甚梦里、春归不管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11192, '踏歌', '辛弃疾', '厥。\n看精神、压一庞儿劣。\n更言语、一似春莺滑。\n一团儿、美满香和雪。\n去也。\n把春衫、换却同心结。\n向人道、不怕轻离别。\n问昨宵、因甚歌声咽。\n秋被梦，春闺月。\n旧家事、却对何人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11193, '一络索・一落萦', '辛弃疾', '羞见鉴鸾孤却。\n倩人梳掠。\n一春长是为花愁，甚夜夜、东风恶。\n行绕翠帘珠箔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11194, '千秋岁', '辛弃疾', '塞垣秋草。\n又报平安好。\n尊俎上，英雄表。\n金汤生气象，珠玉霏谭笑。\n春近也，梅花得似人难老。\n莫惜金尊倒。\n凤诏看看到。\n留不住，江东小。\n从容帷幄去，整顿乾坤了。\n千百岁，从今尽是中书考。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11195, '感皇恩', '辛弃疾', '春事到清明，十分花柳。\n唤得笙歌劝君酒。\n酒如春好，春色年年如旧。\n青春元不老，君知否。\n席上看君，竹清松瘦。\n待与青春斗长久。\n三山路归，明日天香襟袖。\n更持银盏起，为君寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11196, '青玉案', '辛弃疾', '东风夜放花千树。\n更吹落、星如雨。\n宝马雕车香满路。\n凤箫声动，玉壶光转，一夜鱼龙舞。\n蛾儿雪柳黄金缕。\n笑语盈盈暗香去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11197, '霜天晓角', '辛弃疾', '吴头楚尾。\n一棹人千里。\n休说旧愁新恨，长亭树、今如此。\n宦游吾倦矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11198, '南乡子', '辛弃疾', '枕橹声边。\n贪听咿哑聒醉眠。\n变作笙歌花底去，依然。\n翠袖盈盈在眼前。\n别後两眉尖。\n欲说还休梦已阑。\n只记埋冤前夜月，相看。\n不管人愁独自圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11199, '阮郎归', '辛弃疾', '山前风雨欲黄昏。\n山头来去雪。\n鹧鸪声里数家村。\n潇湘逢故人。\n挥羽扇，整纶巾。\n少年鞍马尘。\n如今憔悴赋招魂。\n儒冠多误身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11200, '南歌子', '辛弃疾', '万万千千恨，前前後後山。\n傍人道我轿儿宽。\n不道被他遮得、望伊难。\n今夜江头树，船儿系那边。\n知他热後甚时眠。\n万万不成眠後、有谁扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11201, '小重山', '辛弃疾', '倩得薰风染绿衣。\n国香收不起，透冰肌。\n略开些子未多时。\n窗儿外，却早被人知。\n越惜越娇痴。\n一枝云鬓上，那人宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11202, '小重山', '辛弃疾', '旋制离歌唱未成。\n阳关先画出，柳边亭。\n中年怀抱管弦声。\n难忘处，风月此时情。\n夜雨共谁听。\n尽教清梦去，两三程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11203, '西江月', '辛弃疾', '千丈悬崖削翠，一川落日熔金。\n白鸥来往本无心。\n选甚风波一任。\n别浦鱼肥堪脍，前村酒美重斟。\n千年往事已沈沈。\n闲管兴亡则甚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11204, '减字木兰花', '辛弃疾', '盈盈泪眼。\n往日青楼天样远。\n秋月春花。\n输与寻常姊妹家。\n水村山驿。\n日暮行云无气力。\n锦字偷裁。\n立尽西风雁不来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11205, '清平乐', '辛弃疾', '柳边飞。\n露湿征衣重。\n宿鹭惊窥沙影动。\n应有鱼虾入梦。\n一川淡月疏星。\n浣沙人影娉婷。\n笑背行人归去，门前稚子啼声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11206, '清平乐', '辛弃疾', '茅檐低小。\n溪上青青草。\n醉里蛮音相媚好。\n白发谁家翁媪。\n大儿锄豆溪东。\n中儿正织鸡笼。\n最喜小儿亡赖，溪头卧剥莲蓬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11207, '清平乐', '辛弃疾', '断崖修竹。\n竹里藏冰玉。\n路绕清溪三百曲。\n香满黄昏雪屋。\n行人系马疏篱。\n折残犹有高枝。\n留得东风数点，只缘娇懒春迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11208, '清平乐', '辛弃疾', '绕床饥鼠。\n蝙蝠翻灯舞。\n屋上松风吹急雨。\n破纸窗间自语。\n平生塞北江南。\n归来华发苍颜。\n布被秋宵梦觉，眼前万里江山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11209, '清平乐', '辛弃疾', '连云松竹。\n万事从今足。\n拄杖东家分社肉。\n白酒床头初熟。\n西风梨枣山园。\n儿童偷把长竿。\n莫遣旁人惊去，老夫静处闲看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11210, '生查子', '辛弃疾', '昨宵醉里行，山吐三更月。\n不见可怜人，一夜头如雪。\n今宵醉里归，明月关山笛。\n收拾锦囊诗，要寄扬雄宅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11211, '生查子', '辛弃疾', '谁倾沧海珠，簸弄千明月。\n唤取酒边来，软语裁春雪。\n人间无凤凰，空费穿云笛。\n醉倒却归来，松菊陶潜宅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11212, '山鬼谣・摸鱼儿', '辛弃疾', '问何年，此山来此，西风落日无语。\n看君似是羲皇上，直作太初名汝。\n溪上路。\n算只有、红尘不到今犹古。\n一杯谁举。\n笑我醉呼君，崔嵬未起，山鸟覆杯去。\n须记取。\n昨夜龙湫风雨。\n门前石浪掀舞。\n四更山鬼吹灯啸，惊倒世间儿女。\n依约处。\n还问我、清游杖屦公良苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11213, '声声慢', '辛弃疾', '征埃成阵，行客相逢，都道幻出层楼。\n指点檐牙高处，浪拥云浮。\n今年太平万里，罢长淮、千骑临秋。\n凭栏望，有东南佳气，西北神州。\n千里怀嵩人去，应笑我、身在楚尾吴头。\n看取弓刀，陌上车马如流。\n从今赏心乐事，剩安排、酒令诗筹。\n华胥梦，愿年年、人似旧游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11214, '满江红', '辛弃疾', '直节堂堂，看夹道、冠缨拱立。\n渐翠谷、群仙东下，环声急。\n闻道天峰飞堕地，傍湖千丈开青壁。\n是当年、玉斧削方壶，无人识。\n山木润，琅湿。\n秋露下，琼珠滴。\n向危亭横跨，玉渊澄碧。\n醉舞且摇鸾凤影，浩歌莫遣鱼龙泣。\n恨此中、风月本吾家，今为客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11215, '满江红', '辛弃疾', '照影溪梅，怅绝代、幽人独立。\n更小驻、雍容千骑，羽觞飞急。\n琴里新声风响，笔端醉墨鸦栖壁。\n是使君、文度旧知名，方相识。\n清可漱，泉长滴。\n高欲卧，云还湿。\n快晚风吹赠，满怀空碧。\n宝马嘶归红旆动，团龙试碾铜瓶泣。\n怕他年、重到路应迷，桃源客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11216, '满江红', '辛弃疾', '可恨东君，把春去春来无迹。\n便过眼、等闲输了，三分之一。\n昼永暖翻红杏雨，风晴扶起垂杨力。\n更天涯、芳草最关情，烘残日。\n湘浦岸，南塘驿。\n恨不尽，愁如积。\n算年年孤负，对他寒食。\n便恁归来能几许，风流已自非畴昔。\n凭画栏、一线数飞鸿，沈空碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11217, '满江红', '辛弃疾', '尘土西风，便无限、凄凉行色。\n还记取、明朝应恨，今宵轻别。\n珠泪争垂华烛暗，雁行中断哀筝切。\n看扁舟、幸自涩清溪，休催发。\n白首路，长亭仄。\n千树柳，千丝结。\n怕行人西去，棹歌声阕。\n黄卷莫教诗酒污，玉阶不信仙凡隔。\n但从今、伴我又随君，佳哉月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11218, '满江红', '辛弃疾', '天上飞琼，毕竟向、人间情薄。\n还又跨、玉龙归去，万花摇落。\n云破林梢添远岫，月临屋角分层阁。\n记少年、骏马走韩庐，掀东郭。\n吟冻雁，嘲饥鹊。\n人已老，欢犹昨。\n对琼瑶满地，与君酬酢。\n最爱霏霏迷远近，却收扰扰还寥廓。\n待羔儿、酒罢又烹茶，扬州鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11219, '满江红', '辛弃疾', '折尽荼シ，尚留得、一分春色。\n还记取、青梅如弹，共伊同摘。\n少日对花昏醉梦，而今醒眼看风月。\n恨牡丹、笑我倚东风，形如雪。\n人渐远，君休说。\n榆荚阵，菖蒲药。\n算不因风雨，只因。\n老冉冉兮花共柳，是栖栖者蜂和蝶。\n也不因、春去有闲愁，因离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11220, '满江红', '辛弃疾', '天与文章，看万斛、龙文笔力。\n闻道是、一诗曾赐，千金颜色。\n欲说又休新意思，强啼偷笑真消息。\n算人人、合与共乘鸾，銮坡客。\n倾国艳，难再得。\n还可恨，还勘忆。\n看书寻旧锦，衫裁新碧。\n莺蝶一春花里活，可堪风雨飘红白。\n问谁家、却有燕归梁，香泥湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11221, '满江红', '辛弃疾', '绝代佳人，曾一笑、倾城倾国。\n休更叹、旧时清镜，而今华发。\n明日伏波堂上客，老当益壮翁应说。\n恨苦遭、邓禹笑人来，长寂寂。\n诗酒社，江山笔。\n松菊径，云烟屐。\n怕一觞一咏，风流弦绝。\n我梦横江孤鹤去，觉来却与君相别。\n记功名、万里要吾身，佳眠食。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11222, '满江红', '辛弃疾', '敲碎离愁，纱窗外、风摇翠竹。\n人去後、吹箫声断，倚楼人独。\n满眼不堪三月暮，举头已觉千山绿。\n但试将、一纸寄来书，从头读。\n相思字，空盈幅。\n相思意，何时足。\n滴罗襟点点，泪珠盈掬。\n芳草不迷行客路，垂杨只碍离人目。\n最苦是、立尽月黄昏，栏干曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11223, '满江红', '辛弃疾', '倦客新丰，貂裘敝、征尘满目。\n弹短铗、青蛇三尺，浩歌谁续。\n不念英雄江左老，用之可以尊中国。\n叹诗书、万卷致君人，番沈陆。\n休感叹，年华促。\n人易老，欢难足。\n有玉人怜我，为簪黄菊。\n且置请缨封万户，竟须卖剑酬黄犊。\n叹当年、寂寞贾长沙，伤时哭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11224, '满江红', '辛弃疾', '家住江南，又过了、清明寒食。\n花径里、一番风雨，一番狼藉。\n流水暗随红粉去，园林渐觉清阴密。\n算年年、落尽刺桐花，寒无力。\n庭院静，空相忆。\n无说处，闲愁极。\n怕流莺乳燕，得知消息。\n尺素如今何处也，彩云依旧无踪迹。\n谩教人、羞去上层楼，平芜碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11225, '贺新郎', '辛弃疾', '把酒长亭说。\n看渊明、风流酷似，卧龙诸葛。\n何处飞来林间鹊，蹙踏松梢微雪。\n要破帽、多添华发。\n剩水残山无态度，被疏梅、料理成风月。\n两三雁，也萧瑟。\n佳人重约还轻别。\n怅清江、天寒不渡，水深冰合。\n路断车轮生四角，此地行人销骨。\n问谁使、君来愁绝。\n铸就而今相思错，料当初、费尽人间铁。\n长夜笛，莫吹裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11226, '贺新郎', '辛弃疾', '老大犹堪说。\n似而今、元龙臭味，孟公瓜葛。\n我病君来高歌饮，惊散楼头飞雪。\n笑富贵、千钧如发。\n硬语盘空谁来听，记当时、只有西窗月。\n重进酒，唤呜瑟。\n事无两样人心别。\n问渠侬、神州毕竟，几番离合。\n汗血盐车无人顾，千里空收骏骨。\n正目断、关河路绝。\n我最怜君中宵舞，道男儿、到死心如铁。\n看试手，补天裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11227, '贺新郎', '辛弃疾', '细把君诗说。\n怅馀音、钧天浩荡，洞庭胶葛。\n千尺阴崖尘不到，惟有层冰积雪。\n乍一见、寒生毛发。\n自昔佳人多薄命，对古来、一片伤心月。\n金屋冷，夜调瑟。\n去天尺五君家别。\n看乘空、鱼龙惨淡，风云开合。\n起望衣冠神州路，白日消残战骨。\n叹夷甫、诸人清绝。\n夜半狂歌悲风起，听铮铮、阵马檐间铁。\n南共北，正分裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11228, '贺新郎', '辛弃疾', '凤尾龙香拨。\n自开元、霓裳曲罢，几番风月。\n最苦浔阳江头客，画舸亭亭待发。\n记出塞、黄云堆雪。\n马上离愁三万里，望昭阳、宫殿孤鸿没。\n弦解语，恨难说。\n辽阳驿使音尘绝。\n琐窗寒、轻拢慢拈，泪珠盈睫。\n推手含情还却手，一抹梁州哀彻。\n千古事、云飞烟灭。\n贺老定场无消息，想沈香亭北繁华歇。\n弹到此，为呜咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11229, '贺新郎', '辛弃疾', '柳暗清波路。\n送春归、猛风暴雨，一番新绿。\n千里潇湘葡萄涨，人解扁舟欲去。\n又樯燕、留人相语。\n艇子飞来生尘步，唾花寒、唱我新番句。\n波似箭，催鸣橹。\n黄陵祠下山无数。\n听湘娥、泠泠曲罢，为谁情苦。\n行到东吴春已暮，正江阔、潮平稳渡。\n望金雀、觚棱翔舞。\n前度刘郎今重到，问玄都、千树花存否。\n愁为倩，么弦诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11230, '水调歌头', '辛弃疾', '寄我五云字，恰向酒边来。\n东风过尽归雁，不见客星回。\n闻道琐窗风月，更著诗翁杖屦，合作雪堂猜。\n岁旱莫留客，霖雨要渠来。\n短檠灯，长剑铗，欲生苔。\n雕弓挂壁无用，照影落清杯。\n多病关心药裹，小摘亲锄菜甲，老子正须哀。\n夜雨北窗竹，更倩野人栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11231, '水调歌头', '辛弃疾', '酒罢且勿起，重挽史君须。\n一身都是和气，别去意何如。\n我辈情锺休问，父老田头说尹，泪落独怜渠。\n秋水见毛发，千尺定无鱼。\n望清阙，左黄阁，右紫枢。\n东风桃李陌上，下马拜除书。\n屈指吾生馀几，多病故人痛饮，此事正愁馀。\n江湖有归雁，能寄草堂无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11232, '水调歌头', '辛弃疾', '我饮不须劝，正怕酒尊空。\n别离亦复何恨，此别恨匆匆。\n头上貂蝉贵客，花外麒麟高冢，人世竟谁雄。\n一笑出门去，千里落花风。\n孙刘辈，能使我，不为公。\n余发种种如是，此事付渠侬。\n但觉平生湖海，除了醉吟风月，此外百无功。\n毫发皆帝力，更乞鉴湖东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11233, '水调歌头', '辛弃疾', '寒食不小住，千骑拥春衫。\n衡阳石鼓城下，记我旧停骖。\n襟似潇湘桂岭，带似洞庭春草，紫盖屹东南。\n文字起骚雅，刀剑化耕蚕。\n看使君，於此事，定不凡。\n奋髯抵几堂上，尊俎自高谈。\n莫信君门万里，但使民歌五裤，归诏凤凰衔。\n君去我谁饮，明月影成三。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11234, '水调歌头', '辛弃疾', '头白齿牙缺，君勿笑衰翁。\n无穷天地今古，人在四之中。\n臭腐神奇俱尽，贵贱贤愚等耳，造物也儿童。\n老佛更堪笑，谈妙说虚空。\n坐堆，行飒，立龙锺。\n有时三盏两盏，淡酒醉蒙鸿。\n四十九年前事，一百八盘狭路，拄杖倚墙东。\n老境何所似，只与少年同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11235, '水调歌头', '辛弃疾', '上界足官府，公是地行仙。\n青毡剑履旧物，玉立侍天颜。\n莫怪新来白发，恐是当年柱下，道德五千言。\n南涧旧活计，猿鹤且相安。\n歌秦缶，宝康瓠，世皆然。\n不知清庙钟磬，零落有谁编。\n堪笑行藏用舍，试问山林钟鼎，底事有亏全。\n再拜荷公赐，双鹤一千年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11236, '念奴娇', '辛弃疾', '少年握槊，气凭陵、酒圣诗豪馀事。\n缩手旁观初未识，两两三三而已。\n变化须臾，鸥飞石镜，鹊抵星桥□。\n捣残秋练，玉砧犹想纤指。\n堪笑千古争心，等闲一胜，拼了光阴费。\n老子忘机浑谩与，鸿鹄飞来天际。\n武媚宫中，韦娘局上，休把兴亡记。\n布衣百万，看君一笑沈醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11237, '念奴娇', '辛弃疾', '倘来轩冕，问还是、今古人间何物。\n旧日重城愁万里，风月而今坚壁。\n药笼功名，酒垆身世，可惜蒙头雪。\n浩歌一曲，坐中人物之杰。\n堪叹黄菊凋零，孤标应也有，梅花争发。\n醉里重揩西望眼，惟有孤鸿明减。\n世事从教，浮云来去，枉了冲冠发。\n故人何在，长歌应伴残月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11238, '念奴娇', '辛弃疾', '道人元是，道家风、来作烟霞中物。\n翠裁犀遮不定，红透玲珑油壁。\n借得春工，惹将秋露，薰做江梅雪。\n我评花谱，便应推此为杰。\n憔悴何处芳枝，十郎手种，看明年花发。\n坐对虚空香色界，不怕西风起灭。\n别驾风流，多情更要，簪满娥发。\n等闲折尽，玉斧重倩修月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11239, '念奴娇', '辛弃疾', '江南尽处，堕玉京仙子，绝尘英秀。\n彩笔风流，偏解写、姑射冰姿清瘦。\n笑杀春工，细窥天巧，妙绝应难有。\n丹青图画，一时都愧凡陋。\n还似篱落孤山，嫩寒清晓，祗欠香沾袖。\n淡伫轻盈，谁付与、弄粉调朱纤手。\n疑是花神，来人世，占得佳名久。\n松篁佳韵，倩君添做三友。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11240, '念奴娇', '辛弃疾', '疏疏淡淡，问阿谁、堪比天真颜色。\n笑杀东君虚占断，多少朱朱白白。\n雪里温柔，水边明秀，不惜春工力。\n骨清香嫩，迥然天与奇绝。\n尝记宝寒轻，琐窗人睡起，玉纤轻摘。\n漂泊天涯空瘦损，犹有当年标格。\n万里风烟，一溪霜月，未怕欺他得。\n不如归去，阆苑有个人忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11241, '水龙吟', '辛弃疾', '断崖千丈孤松，挂冠更在松高处。\n平生袖手，故应休矣，功名良苦。\n笑指儿曹，人间醉梦，莫嗔惊汝。\n问黄金馀几，旁人欲说，田园计、君推去。\n叹息芗林旧隐，对先生、竹窗松户。\n一花一草，一觞一咏，风流杖屦。\n野马尘埃，扶摇下视，苍然如许。\n恨当年、九老图中，忘却画、盘园路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11242, '水龙吟', '辛弃疾', '倚栏看碧成朱，等闲褪了香袍粉。\n上林高选，匆匆又换，紫云衣润。\n几许春风，朝薰暮染，为花忙损。\n笑旧家桃李，东涂西抹，有多少、凄凉恨。\n拟倩流莺说与，记容华、易消难整。\n人间得意，千红百紫，转头春尽。\n白发怜君，儒冠曾误，平生官冷。\n算风流未减，年年醉里，把花枝问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11243, '水龙吟', '辛弃疾', '补陀大士虚空，翠岩谁记飞来处。\n蜂房万点，似穿如碍，玲珑窗户。\n石髓千年，已垂未落，嶙峋冰柱。\n有怒涛声远，落花香在，人疑是、桃源路。\n又说春雷鼻息，是卧龙、弯环如许。\n不然应是，洞庭张乐，湘灵来去。\n我意长松，倒生阴壑，细吟风雨。\n竟茫茫未晓。\n只应白发，是开山祖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11244, '水龙吟', '辛弃疾', '稼轩何必长贫，放泉檐外琼珠泻。\n乐天知命，古来谁会，行藏用舍。\n人不堪忧，一瓢自乐，贤哉回也。\n料当年曾问，饭蔬饮水，何为是、栖栖者。\n且对浮云山上，莫匆匆、去流山下。\n苍颜照影，故应流落，轻裘肥马。\n绕齿冰霜，满怀芳乳，先生饮罢。\n笑挂瓢风树，一鸣渠碎，问何如哑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11245, '水龙吟', '辛弃疾', '听兮清琼瑶些。\n明兮镜秋毫些。\n君无去此，流昏涨腻，生蓬蒿些。\n虎豹甘人，渴而饮汝，宁猿猱些。\n大而流江海，覆舟如芥，君无助、狂涛些。\n路险兮、山高些。\n愧余独处无聊些。\n冬槽春盎，归来为我，制松醪些。\n其外芳芬，团龙片凤，煮云膏些。\n古人兮既往，嗟余之乐，乐箪瓢些。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11246, '最高楼', '辛弃疾', '相思苦，君与我同心。\n鱼没雁沈沈。\n是梦他松後追轩冕，是化为鹤後去山林。\n对西风，直怅望，到如今。\n待不饮、奈何君有恨。\n待痛饮、奈何吾有病。\n君起舞，试重斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11247, '最高楼', '辛弃疾', '吾衰矣，须富贵何时。\n富贵是危机。\n暂忘设醴抽身去，未曾得米弃官归。\n穆先生，陶县令，是吾师。\n待葺个、园儿名佚老。\n更作个、亭儿名亦好。\n闲饮酒，醉吟诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11248, '最高楼', '辛弃疾', '花好处，不趁绿衣郎。\n缟袂立斜阳。\n面皮儿上因谁白，骨头儿里几多香。\n尽饶他，心似铁，也须忙。\n甚唤得、雪来白倒雪。\n更唤得，月来香杀月。\n谁立马，更窥墙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11249, '最高楼', '辛弃疾', '金闺老，眉寿正如川。\n七十且华筵。\n乐天诗句香山里，杜陵酒债曲江边。\n问何如，歌窈窕，舞婵娟。\n更十岁、太公方出将。\n又十岁、武公才入相。\n留盛事，看明年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11250, '瑞鹤仙', '辛弃疾', '黄金堆到斗。\n怎得似、长年画堂劝酒。\n蛾眉最明秀。\n向水沈烟里，两行红袖。\n笙歌就。\n争说道、明年时候。\n被娥、做了殷勤，仙桂一枝入手。\n知否。\n风流别驾，近日人呼，文章太守。\n天长地久。\n岁岁上、乃翁寿。\n记从来人道，相门出相，金印累累尽有。\n但直须，周公拜前，鲁公拜後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11251, '汉宫春', '辛弃疾', '行李溪头，有钓车茶具，曲几团蒲。\n儿童认得，前度过者篮舆。\n时时照影，甚此身、遍满江湖。\n怅野老，行歌不住，定堪与语难呼。\n一自东篱摇落，问渊明岁晚，心赏何如。\n梅花正自不恶，曾有诗无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11252, '沁园春', '辛弃疾', '有酒忘杯，有笔忘诗，弄溪奈何。\n看纵横斗转，龙蛇起陆，崩腾决去，雪练倾河。\n袅袅东风，悠悠倒景，摇动云山水又波。\n还知否，欠菖蒲攒港，绿竹缘坡。\n长松谁剪嵯峨。\n笑野老来耘山上禾。\n算只因鱼鸟，天然自乐，非关风月，闲处偏多。\n芳草春深，佳人日暮，濯发沧浪独浩歌。\n徘徊久，问人间谁似，老子婆娑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11253, '沁园春', '辛弃疾', '一水西来，千丈晴虹，十里翠屏。\n喜草堂经岁，重来社老，斜川好景，不负渊明。\n老鹤高飞，一枝投宿，长笑蜗牛戴屋行。\n平章了，待十分佳处，著个茅亭。\n青山意气峥嵘。\n似为我归来妩媚生。\n解频教花鸟，前歌後舞，更催云水，暮送朝迎。\n酒圣诗豪，可能无势，我乃而今驾驭卿。\n清溪上，被山灵却笑，白发归耕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11254, '归朝欢', '辛弃疾', '我笑共工缘底怒。\n触断峨峨天一柱。\n补天又笑女娲忙，却将此石投闲处。\n野烟荒草路。\n先生柱杖来看汝。\n倚苍苔，摩挲试问，千古几风雨。\n长被儿童敲火苦。\n时有牛羊磨角去。\n霍然千丈翠岩屏，锵然一滴甘泉乳。\n结亭三四五。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11255, '水龙吟', '辛弃疾', '举头西北浮云，倚天万里须长剑。\n人言此地，夜深长见，斗牛光焰。\n我觉山高，潭空水冷，月明星淡。\n待燃犀下看，凭栏却怕，风雷怒，鱼龙惨。\n峡束□江对起，过危楼、欲飞还敛。\n元龙老矣，不妨高卧，冰壶凉簟。\n千古兴亡，百年悲笑，一时登览。\n问何人又卸，片帆沙岸，系斜阳缆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11256, '水龙吟', '辛弃疾', '只愁风雨重阳，思君不见令人老。\n行期定否，征车几两，去程多少。\n有客书来，长安却早，传闻追诏。\n问归来何日，君家旧事，直须待、为霖了。\n从此兰生蕙长，吾谁与、玩兹芳草。\n自怜拙者，功名相避，去如飞鸟。\n只有良朋，东阡西陌，安排似巧。\n到如今巧处，依前又拙，把平生笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11257, '卜算子', '辛弃疾', '百郡怯登车，千里输流马。\n乞得胶胶扰扰身，却笑区区者。\n野水玉鸣渠，急雨珠跳瓦。\n一榻清风方是闲，真得归来也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11258, '江神子・江城子', '辛弃疾', '梨花著雨晚来晴。\n月胧明。\n泪纵横。\n绣阁香浓，深锁凤箫声。\n未必人知春意思，还独自，绕花行。\n酒兵昨夜压愁城。\n太狂生。\n转关情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11259, '江神子・江城子', '辛弃疾', '宝钗飞凤鬓惊鸾。\n望重欢。\n水云宽。\n肠断新来，翠被□香残。\n待得来时春尽也，梅著子，笋成竿。\n湘筠帘卷泪痕斑。\n声闲。\n玉垂环。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11260, '鹧鸪天', '辛弃疾', '著意寻春懒便回。\n何如信步两三杯。\n山才好处行还倦，诗未成时雨早催。\n携竹杖，更芒鞋。\n朱朱粉粉野蒿开。\n谁家寒食归宁女，笑语柔桑陌上来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11261, '鹧鸪天', '辛弃疾', '水底明霞十顷光。\n天教铺锦衬鸳鸯。\n最怜杨柳如张绪，却笑莲花似六郎。\n方竹簟，小胡床。\n晚风消得许多凉。\n背人白鸟都飞去，落日残□更断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11262, '鹧鸪天', '辛弃疾', '漠漠轻□拨不开。\n江南细雨熟黄梅。\n有情无意东边日，已怒重惊忽地雷。\n云柱础，水楼台。\n罗衣费尽博山灰。\n当时一识和羹味，便道为霖消息来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11263, '鹧鸪天', '辛弃疾', '有甚闲愁可皱眉。\n老怀无绪自伤悲。\n百年旋逐花阴转，万事长看鬓发知。\n溪上枕，竹间棋。\n怕寻酒伴懒吟诗。\n十分筋力夸强健，只比年时病起时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11264, '鹧鸪天', '辛弃疾', '山上飞泉万斛珠。\n悬崖千丈落鼯。\n已通樵迳行还碍，似有人声听却无。\n闲略，远浮屠。\n溪南修竹有茅庐。\n莫嫌杖屦频来往，此地偏宜著老夫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11265, '鹧鸪天', '辛弃疾', '莫避春阴上马迟。\n春来未有不阴时。\n人情展转闲中看，客路崎岖倦後知。\n梅似雪，柳如丝。\n试听别语慰相思。\n短篷炊饭鲈鱼熟，除却松江枉费诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11266, '鹧鸪天', '辛弃疾', '白苎新袍入嫩凉。\n春蚕食叶响回廊。\n禹门已准桃花浪，月殿先收桂子香。\n鹏北海，凤朝阳。\n又携书剑路茫茫。\n明年此日青云去，却笑人间举子忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11267, '鹧鸪天', '辛弃疾', '莫上扁舟向剡溪。\n浅斟低唱正相宜。\n从□犬吠千家白，且与梅成一段奇。\n香暖处，酒醒时。\n画檐玉箸已偷垂。\n笑君解释春风恨，倩拂蛮笺只费诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11268, '鹧鸪天', '辛弃疾', '千丈阴崖百丈溪。\n孤桐枝上凤偏宜。\n玉音落落虽难合，横理庚庚定自奇。\n人散後，月明诗。\n试弹幽愤泪空垂。\n不如却付骚人手，留和南风解愠诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11269, '鹧鸪天', '辛弃疾', '陌上柔条初破芽。\n东邻蚕种已生些。\n平冈细草鸣黄犊，斜日寒林点暮鸦。\n山远近，路横斜。\n青旗沽酒有人家。\n城中桃李愁风雨，春在溪头野荠花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11270, '鹧鸪天', '辛弃疾', '春日平原荠菜花。\n新耕雨後落群鸦。\n多情白发春无奈，晚日青□酒易赊。\n闲意态，细生涯。\n牛□西畔有桑麻。\n青裙缟袂谁家女，去趁蚕生看外家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11271, '鹧鸪天', '辛弃疾', '千丈清溪百步雷。\n柴门都向水边开。\n乱云剩带炊烟去，野水闲将日影来。\n穿窈窕，历崔嵬。\n东林试问几时栽。\n动摇意态虽多竹，点缀风流却少梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11272, '鹧鸪天', '辛弃疾', '枕婆娑两鬓霜。\n起听檐溜碎喧江。\n那边玉箸销啼粉，这里车轮转别肠。\n诗酒社，水边乡。\n可堪醉墨几淋浪。\n画图恰似归家梦，千里河山寸许长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11273, '西江月', '辛弃疾', '明月别枝惊鹊，清风半夜鸣蝉。\n稻花香里说丰年。\n听取蛙声一片。\n七八个星天外，两三点雨山前。\n旧时茅店社林边。\n路转溪桥忽见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11274, '菩萨蛮', '辛弃疾', '淡黄弓样鞋儿小。\n腰肢只怕风吹倒。\n蓦地管弦催。\n一团红雪飞。\n曲终娇欲诉。\n定忆梨园谱。\n指日按新声。\n主人朝玉京。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11275, '菩萨蛮', '辛弃疾', '锦书谁寄相思语。\n天边数遍飞鸿数。\n一夜梦千回。\n梅花入梦来。\n涨痕纷树发。\n霜落沙洲白。\n心事莫惊鸥。\n人间千万愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11276, '菩萨蛮', '辛弃疾', '阮琴斜挂香罗绶。\n玉纤初试琵琶手。\n桐叶雨声乾。\n真珠落玉盘。\n朱弦调未惯。\n笑倩春风伴。\n莫作别离声。\n且听双凤鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11277, '朝中措', '辛弃疾', '年年金蕊艳西风。\n人与菊花同。\n霜鬓经春重绿，仙姿不饮长红。\n焚香度日尽从容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11278, '鹊桥仙', '辛弃疾', '小窗风雨，从今便忆，中夜笑谈清软。\n啼鸦衰柳自无聊，更管得、离人肠断。\n诗书事业，青毡犹在，头上貂蝉会见。\n莫贪风月卧江湖，道日近、长安路远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11279, '鹊桥仙', '辛弃疾', '松冈避暑。\n茅檐避雨。\n闲去闲来几度。\n醉扶孤石看飞泉，又却是、前回醒处。\n东家取妇。\n西家归女。\n灯火门前笑语。\n酿成千顷稻花香，夜夜费、一天风露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11280, '临江仙', '辛弃疾', '风雨催春寒食近，平原一片丹青。\n溪边唤渡柳边行。\n花飞蝴蝶乱，桑嫩野蚕生。\n绿野先生闲袖手，却寻诗酒功名。\n未知明日定阴晴。\n今宵成独醉，却笑众人醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11281, '临江仙', '辛弃疾', '住世都无菩萨行，仙家风骨精神。\n寿如山岳福如云。\n金花汤沐诰，竹马绮罗群。\n更愿升平添喜事，大家祷祝殷勤。\n明年此地庆佳辰。\n一杯千岁酒，重拜太夫人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11282, '定风波', '辛弃疾', '山路风来草木香。\n雨馀凉意到胡床。\n泉石膏肓吾已甚。\n多病。\n堤防风月费篇章。\n孤负寻常山简醉。\n独自。\n故应知子草玄忙。\n湖海早知身汗漫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11283, '定风波', '辛弃疾', '听我尊前醉後歌。\n人生亡奈别离何。\n但使情亲千里近。\n须信。\n无情对面是山河。\n寄语石头城下水。\n居士。\n而今浑不怕风波。\n借使未如鸥鸟惯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11284, '定风波', '辛弃疾', '仄月高寒水石乡。\n倚空青碧对禅床。\n白发自怜心似铁。\n风月。\n使君子细与平章。\n已判生涯筇竹杖。\n来往。\n却惭沙鸟笑人忙。\n便好剩留黄绢句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11285, '定风波', '辛弃疾', '昨夜山公倒载归。\n儿童应笑醉如泥。\n试与扶头浑未醒。\n休问。\n梦魂犹在葛家溪。\n千古醉乡来往路。\n知处。\n温柔东畔白云西。\n起向绿窗高处看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11286, '定风波', '辛弃疾', '春到蓬壶特地晴。\n神仙队里相公行。\n翠玉相挨呼小字。\n须记。\n笑簪花底是飞琼。\n总是倾城来一处。\n谁妒。\n谁携歌舞到园亭。\n柳妒腰肢花妒艳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11287, '定风波', '辛弃疾', '百紫千红过了春。\n杜鹃声苦不堪闻。\n却解啼教春小住。\n风雨。\n空山招得海棠魂。\n一似蜀宫当日女。\n无数。\n猩猩血染赭罗巾。\n毕竟花开谁作主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11288, '浣溪沙', '辛弃疾', '侬是崎可笑人。\n不妨开口笑时频。\n有人一笑坐生春。\n歌欲颦时还浅笑，醉逢笑处却轻颦。\n宜颦宜笑越精神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11289, '浣溪沙', '辛弃疾', '梅子熟时到几回。\n桃花开後不须猜。\n重来松竹意徘徊。\n惯听禽声浑可谱，饱观鱼阵已能排。\n晚云挟雨唤归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11290, '浣溪沙', '辛弃疾', '百世孤芳肯自媒。\n直须诗句与推排。\n不然唤近酒边来。\n自有渊明方有菊，若无和靖即无梅。\n只今何处向人开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11291, '浣溪沙', '辛弃疾', '未到山前骑马回。\n风吹雨打已无梅。\n共谁消遣两三杯。\n一似旧时春意思，百无是处老形骸。\n也曾头上带花来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11292, '杏花天', '辛弃疾', '牡丹比得谁颜色。\n似宫中、太真第一。\n渔阳鼙鼓边风急。\n人在沈香亭北。\n买栽池馆多何益。\n莫虚把、千金抛掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11293, '鹊桥仙', '辛弃疾', '风流标格，惺松言语，真个十分奇绝。\n三分兰菊十分梅，斗合就、一枝风月。\n笙簧未语，星河易转，凉夜厌厌留客。\n只愁酒尽各西东，更把酒、推辞一霎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11294, '鹊桥仙', '辛弃疾', '八旬庆会，人间盛事，齐劝一杯春酿。\n胭脂小字点眉间，犹记得、旧时宫样。\n彩衣更著，功名富贵，直过太公以上。\n大家著意记新词，遇著个、十字便唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11295, '鹊桥仙', '辛弃疾', '豸冠风采，绣衣声价，曾把经纶少试。\n看看有诏日边来，便入侍、明光殿里。\n东君未老，花明柳媚，且引玉尘沈醉。\n好将三万六千场，自今日、从头数起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11296, '鹊桥仙', '辛弃疾', '轿儿排了，担儿装了，杜宇一声催起。\n从今一步一回头，怎睚得、一千馀里。\n旧时行处，旧时歌处，空有燕泥香坠。\n莫嫌白发不思量，也须有、思量去里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11297, '虞美人', '辛弃疾', '一杯莫落吾人後。\n富贵功名寿。\n胸中书传有馀香。\n看写兰亭小字、记流觞。\n问谁分我渔樵席。\n江海消闲日。\n看君天上拜恩浓。\n却恐画楼无处、著东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11298, '虞美人', '辛弃疾', '翠屏罗幕遮前後。\n舞袖翻长寿。\n紫髯冠佩御炉香。\n看取明年归奉、万年觞。\n今宵池上蟠桃席。\n咫尺长安日。\n宝烟飞焰万花浓。\n试看中间白鹤、驾仙风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11299, '虞美人', '辛弃疾', '夜深困倚屏风後。\n试请毛延寿。\n宝钗小立白翻香。\n旋唱新词犹误、笑持觞。\n四更山月寒侵席。\n歌舞催时日。\n问他何处最情浓。\n却道小梅摇落、不禁风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11300, '虞美人', '辛弃疾', '群花泣尽朝来露。\n争奈春归去。\n不知庭下有荼シ。\n偷得十分春色、怕春知。\n淡中有味清中贵。\n飞絮残英避。\n露华微渗玉肌香。\n恰似杨妃初试、出兰汤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11301, '蝶恋花', '辛弃疾', '意态憨生元自好。\n学画鸦儿，旧日偏他巧。\n蜂蝶不禁花引调。\n西园人去春风少。\n春已无情秋又老。\n谁管闲愁，千里青青草。\n今夜倩簪黄菊了。\n断肠明月霜天晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11302, '蝶恋花', '辛弃疾', '谁向椒盘簪彩胜。\n整整韶华，争上春风鬓。\n往日不堪重记省。\n为花长把新春恨。\n春未来时先借问。\n晚恨开迟，早又飘零近。\n今岁花期消息定。\n只愁风雨无凭准。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11303, '蝶恋花', '辛弃疾', '老去怕寻年少伴。\n画栋珠帘，风月无人管。\n公子看花朱碧乱。\n新词搅断香思怨。\n凉夜愁肠千百转。\n一雁西风，锦字何时遣。\n毕竟啼乌才思短。\n唤回晓梦天涯远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11304, '蝶恋花', '辛弃疾', '莫向城头听漏点。\n说与行人，默默情千万。\n总是离愁无近远。\n人间儿女空恩怨。\n锦绣心胸冰雪面。\n旧日诗名，曾道空梁燕。\n倾盖未偿平日愿。\n一杯早唱阳关劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11305, '感皇恩', '辛弃疾', '七十古来稀，人人都道。\n不是阴功怎生到。\n松姿虽瘦，偏耐云寒霜晓。\n看君双鬓底，青青好。\n楼雪初晴，庭闱嬉笑。\n一醉何妨玉壶倒。\n从今康健，不用灵丹仙草。\n更看一百岁，人难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11306, '一枝花・促拍满路花', '辛弃疾', '千丈擎天手。\n万卷悬河口。\n黄金腰下印，大如斗。\n更千骑弓刀，挥霍遮前後。\n百计千方久。\n似斗草儿童，赢个他家偏有。\n算枉了、双眉长恁皱。\n白发空回首。\n那时闲说向，山中友。\n看丘陇牛羊，更辨贤愚否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11307, '永遇乐', '辛弃疾', '紫陌长安，看花年少，无限歌舞。\n白发怜君，寻芳较晚，卷地惊风雨。\n问君知否，鸱夷载酒，不似井瓶身误。\n细思量，悲欢梦里，觉来总无寻处。\n芒鞋竹杖，天教还了，千古玉溪佳句。\n落魄东归，风流赢得，掌上明珠去。\n起看清镜，南冠好在，拂了旧时尘土。\n向君道，云霄万里，这回稳步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11308, '御街行', '辛弃疾', '山城甲子冥冥雨。\n门外青泥路。\n杜鹃只是等闲啼，莫被他催归去。\n垂杨不语，行人去後，也会风前絮。\n情知梦里寻鹭。\n玉殿追班处。\n怕君不饮太愁生，不是苦留君住。\n白头自笑，年年送客，自唤春江渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11309, '御街行', '辛弃疾', '阑干四面山无数。\n供望眼、朝与暮。\n好风催雨过山来，吹尽一帘烦暑。\n纱厨如雾，簟纹如水，别有生凉处。\n冰肌不受铅华污。\n更旎旎、真香聚。\n临风一曲最妖娇，唱得行人且住。\n藕花都放，木犀开後，待与乘鸾去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11310, '生查子', '辛弃疾', '溪边照影行，天在清溪底。\n天上有行云，人在行云里。\n高歌谁和余，空谷清音起。\n非鬼亦非仙，一曲桃花水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11311, '渔家傲', '辛弃疾', '道德文章传几世。\n到君合上三台位。\n自是君家门户事。\n当此际。\n鬼山正抱西江水。\n三万六千排日醉。\n鬓毛只恁青青地。\n江里石头争献瑞。\n分明是。\n中间有个长生字。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11312, '好事近', '辛弃疾', '彩胜斗华灯，平地东风吹却。\n唤取雪中明月，伴使君行乐。\n红旗铁马响春冰，老去此情薄。\n惟有前村梅在，倩一枝随著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11313, '好事近', '辛弃疾', '和泪唱阳关，依旧字娇声稳。\n回首长安何处，怕行人归晚。\n垂杨折尽只啼鸦，把离愁勾引。\n却笑远山无数，被行云低损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11314, '行香子', '辛弃疾', '归去来兮。\n行乐休迟。\n命由天、富贵何时。\n百年光景，七十者稀。\n奈一番愁，一番病，一番衰。\n名利奔驰。\n宠辱惊疑。\n旧家时、都有些儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11315, '南歌子', '辛弃疾', '玄入参同契，禅依不二门。\n静看斜日隙中尘。\n始觉人间、何处不纷纷。\n病笑春先老，闲怜懒是真。\n百般啼鸟苦撩人。\n除却提壶、此外不堪闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11316, '南歌子', '辛弃疾', '世事从头减，秋怀彻底清。\n夜深犹道枕边声。\n试问清溪底事、不能平。\n月到愁边白，鸡先远处鸣。\n是中无有利和名。\n因甚山前未晓、有人行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11317, '清平乐', '辛弃疾', '此身长健。\n还却功名愿。\n枉读平生三万卷。\n满酌金杯听劝。\n男儿玉带金鱼。\n能消几许诗书。\n料得今宵醉也，两行红袖争扶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11318, '清平乐', '辛弃疾', '诗书万卷。\n合上明光殿。\n案上文书看未遍。\n眉里阴功早见。\n十分竹瘦松坚。\n看君自是长年。\n若解尊前痛饮，精神便是神仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11319, '清平乐', '辛弃疾', '清溪奔快。\n不管青山碍。\n千里盘盘平世界。\n更著溪山襟带。\n古今陵谷茫茫。\n市朝往往耕桑。\n此地居然形胜，似曾小小兴亡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11320, '浪淘沙', '辛弃疾', '金玉旧情怀。\n风月追陪。\n扁舟千里兴佳哉。\n不似子猷行半路，却棹船回。\n来岁菊花开。\n记我清杯。\n西风雁过山台。\n把似倩他书不到，好与同来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11321, '浪淘沙', '辛弃疾', '不肯过江东。\n玉帐匆匆。\n至今草木忆英雄。\n唱著虞兮当日曲，便舞春风。\n儿女此情同。\n往事朦胧。\n湘娥竹上泪痕浓。\n舜盖重瞳堪痛恨，羽又重瞳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11322, '虞美人', '辛弃疾', '当年得意如芳草。\n日日春风好。\n拔山力尽忽悲歌。\n饮罢虞兮从此、奈君何。\n人间不识精诚苦。\n贪看青青舞。\n蓦然敛袂却亭亭。\n怕是曲中犹带、楚歌声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11323, '新荷叶', '辛弃疾', '物盛还衰，眼看春药秋萁。\n贵贱交情，翟公门外人稀。\n酒酣耳热，又何须、幽愤裁诗。\n茂林修竹，小园曲迳疏篱。\n秋以为期。\n西风黄菊开时。\n拄杖敲门，从他颠倒裳衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11324, '生查子', '辛弃疾', '青山非不佳，未解留侬住。\n赤脚踏沧浪，为爱清溪故。\n朝来山鸟啼，劝上山高处。\n我意不关渠，自要寻兰去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11325, '西江月', '辛弃疾', '宫粉厌涂娇额，浓妆要压秋花。\n西真人醉忆仙家。\n飞丹霞羽化。\n十里芬芳未足，一亭风露先加。\n杏腮桃脸费铅华。\n终惯秋蟾影下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11326, '糖多令・唐多令', '辛弃疾', '淑景斗清明。\n和风拂面轻。\n小杯盘、同集郊。\n著个儿不肯上，须索要、大家行。\n行步渐轻盈。\n行行笑语频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11327, '王孙信・寻芳草', '辛弃疾', '有得许多泪。\n又闲却、许多鸳被。\n枕头儿、放处都不是。\n旧家时、怎生睡。\n更也没书来，那堪被、雁儿调戏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11328, '一翦梅', '辛弃疾', '记得同烧此夜香。\n人在回廊。\n月在回廊。\n而今独自睚昏黄。\n行也思量。\n坐也思量。\n锦字都来三两行。\n千断人肠。\n万断人肠。\n雁儿何处是仙乡。\n来也惶。\n去也惶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11329, '一翦梅', '辛弃疾', '独立苍茫醉不归。\n日暮天寒，归去来兮。\n探梅踏雪几何时。\n今我来思。\n杨柳依依。\n白石江头曲岸□。\n一片闲愁，芳草萋萋。\n多情山鸟不须啼。\n桃李无言，下自成蹊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11330, '玉楼春', '辛弃疾', '往年堂前路。\n路上人夸通判雨。\n去年拄杖过瓢泉，县吏垂头民笑语。\n学窥圣处文章古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11331, '玉楼春', '辛弃疾', '山行日日妨风雨。\n风雨晴时君不见。\n墙头尘满短辕车，门外人行芳草路。\n南城东野应联句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11332, '玉楼春', '辛弃疾', '人间反覆成云雨。\n凫雁江湖来又去。\n十千一斗饮中仙，一百八盘天上路。\n旧时枫叶吴江句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11333, '南乡子', '辛弃疾', '好个主人家。\n不问因由便去。\n病得那人妆晃了，巴巴。\n系上裙儿稳也哪。\n别泪没些些。\n海誓山盟总是赊。\n今日新欢须记取，孩儿，更过十年也似他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11334, '南乡子', '辛弃疾', '隔户语春莺。\n才挂帘儿敛袂行。\n渐见凌波罗袜步，盈盈。\n随笑随颦百媚生。\n著意听新声。\n尽是司空自教成。\n今夜酒肠还道窄，多情。\n莫放笼纱蜡炬明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11335, '忆王孙', '辛弃疾', '登山临水送将归。\n悲莫悲兮生别离。\n不用登临怨落晖。\n昔人非。\n惟有年年秋雁飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11336, '柳梢青', '辛弃疾', '姚魏名流。\n年年揽断，雨恨风愁。\n解释春光，剩须破费，酒令诗筹。\n玉肌红粉温柔。\n更染尽、天香未休。\n今夜簪花，他年第一，玉殿东头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11337, '惜分飞', '辛弃疾', '翡翠楼前芳草路。\n宝马坠鞭曾驻。\n最是周郎顾。\n尊前几度歌声误。\n望断碧云空日暮。\n流水桃源何处。\n闻道春归去。\n更无人管飘红雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11338, '六州歌头', '辛弃疾', '西湖万顷，楼观矗千门。\n春风路，红堆锦，翠连云。\n俯层轩。\n风月都无际，荡空蔼，开绝境，云梦泽，饶八九，不须吞。\n翡翠明，争上金堤去，勃姗。\n看贤王高会，飞盖入云烟。\n白鹭振振，鼓咽咽。\n记风流远，更休作，嬉游地，等闲看。\n君不见，韩献子，晋将军，赵孤存。\n千载传忠献，两定策，纪元勋。\n孙又子，方谈笑，整乾坤。\n直使长江如带，依前是、□赵须韩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11339, '六州歌头', '辛弃疾', '晨来问疾，有鹤止庭隅。\n吾语汝。\n只三事，太愁予。\n病难扶。\n手种青松树。\n碍梅坞。\n妨花迳，才数尺。\n如人立。\n却须锄。\n秋水堂前，曲沼明於镜，可烛眉须。\n被山头急雨，耕垄灌泥涂。\n谁使吾庐。\n映污渠。\n叹青山好，檐外竹，遮欲尽，有还无。\n删竹去，吾乍可，食无鱼。\n爱扶疏。\n又欲为山计，千百虑，累吾躯。\n凡病此。\n吾过矣。\n子奚如。\n口不能言臆对，虽扁鹊、药石难除。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11340, '满江红', '辛弃疾', '宿酒醒时，算只有、清愁而已。\n人正在、青涂堂上，月华如洗。\n纸帐梅花归梦觉，莼羹鲈秋风起。\n问人生、得意几何时，吾归矣。\n君若问，相思事。\n料长在，歌声里。\n这情怀只是，中年如此。\n明月何妨千里隔，顾君与我何如耳。\n向尊前、重约几时来，江山美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11341, '满江红', '辛弃疾', '几个轻鸥，来点破、一泓澄绿。\n更何处、一双，故来争浴。\n细读离骚还痛饮，饱看修竹何妨肉。\n有飞泉、日日供明珠，三千斛。\n春雨满，秧新谷。\n闲日永，眠黄犊。\n看云连麦垄，雪堆蚕簇。\n若要足时今足矣，以为未足何时足。\n被野老、相扶入东园，枇杷熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11342, '永遇乐', '辛弃疾', '投老空山，万松手种，政尔堪叹。\n何日成阴，吾年有几，似见儿孙晚。\n古来池馆，云烟草棘，长使後人凄断。\n想当年、良辰已恨，夜阑酒空人散。\n停云高处，谁知老子，万事不关心眼。\n梦觉东窗，聊复尔耳，起欲题书简。\n霎时风怒，倒翻笔砚，天也只教吾懒。\n又何事，催诗雨急，片云斗暗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11343, '兰陵王', '辛弃疾', '一丘壑。\n老子风流占却。\n茅檐上、松月桂云，脉脉石泉逗山脚。\n寻思前事错。\n恼杀晨猿夜鹤。\n终须是、邓禹辈人，锦绣麻霞坐黄阁。\n长歌自深酌。\n看天阔鸢飞，渊静鱼跃。\n西风黄菊芗喷薄。\n怅日暮云合，佳人何处，纫兰结佩带杜若。\n入江海曾约。\n遇合。\n事难托。\n莫击磬门前，荷蒉人过，仰天大笑冠簪落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11344, '蓦山溪', '辛弃疾', '饭蔬饮水，客莫嘲吾拙。\n高处看浮云，一丘壑、中间甚乐。\n功名妙手，壮也不如人，今老矣，尚何堪，堪钓前溪月。\n病来止酒，辜负鸬鹚杓。\n岁晚念平生，待都与、邻翁细说。\n人间万事，先觉者贤乎，深雪里，一枝开，春事梅先觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11345, '蓦山溪', '辛弃疾', '小桥流水，欲下前溪去。\n唤取故人来，伴先生、风烟杖屦。\n行穿窈窕，时历小崎岖，斜带水，半遮山，翠竹栽成路。\n一尊遐想，剩有渊明趣。\n山上有停云，看山下、细雨。\n野花啼鸟，不肯入诗来，还一似，笑翁诗，句没安排处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11346, '满庭芳', '辛弃疾', '倾国无媒，入宫见妒，古来颦损蛾眉。\n看公如月，光彩众星稀。\n袖手高山流水，听群蛙、鼓吹荒池。\n文章手，直须补衮，藻火粲宗彝。\n痴儿。\n公事了，吴蚕缠绕，自吐馀丝。\n幸一枝粗稳，三径新治。\n且约湖边风月，功名事、欲使谁知。\n都休问，英雄千古，荒草没残碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11347, '满庭芳', '辛弃疾', '西崦斜阳，东江流水，物华不为人留。\n铮然一叶，天下已知秋。\n屈指人间得意，问谁是、骑鹤扬州。\n君知我，从来雅意，未老已沧州。\n无穷身外事，百年能几，一醉都休。\n恨儿曹抵死，谓我心忧。\n况有溪山杖屦，阮籍辈、须我来游。\n还堪笑，机心早觉，海上有惊鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11348, '最高楼', '辛弃疾', '花知否，花一似何郎。\n又似沈东阳。\n瘦棱棱地天然白，冷清清地许多香。\n笑东君，还又向，北枝忙。\n著一阵、霎时间底雪。\n更一个、缺些儿底月。\n山下路，水边墙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11349, '最高楼', '辛弃疾', '君听取，尺布尚堪缝。\n斗粟也堪舂。\n人间朋友犹能合，古来兄弟不相容。\n棣华诗，悲二叔，吊周公。\n长叹息、脊令原上急。\n重叹息、豆萁煎正泣。\n形则异，气应同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11350, '江神子・江城子', '辛弃疾', '乱云扰扰水潺潺。\n笑溪山。\n几时闲。\n更觉桃源，人去隔仙凡。\n万壑千岩楼外雪，琼作树，玉为栏。\n倦游回首且加餐。\n短篷寒。\n画图间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11351, '木兰花慢', '辛弃疾', '路傍人怪问，此隐者、姓陶不。\n堪黄菊如云，朝吟暮醉，唤不回头。\n纵无酒成怅望，只东篱、搔首亦风流。\n与客朝餐一笑，落英饱便归休。\n古来尧舜有巢由。\n江海去悠悠。\n待说与佳人，种成香草，莫怨灵修。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11352, '木兰花慢', '辛弃疾', '旧时楼上客，爱把酒、向南山。\n笑白发如今，天教放浪，来往其间。\n登楼更谁念我，却回头、西北望层栏。\n云雨珠帘画栋，笙歌雾鬓云鬟。\n近来堪入画图看。\n父老愿公欢。\n甚拄笏悠然，朝来爽气，正尔相关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11353, '木兰花慢', '辛弃疾', '可怜今夕月，向何处、去悠悠。\n是别有人间，那边才见，光影东头。\n是天外空汗漫，但长风、浩浩送中秋。\n飞镜无根谁系，嫦娥不嫁谁留。\n谓洋海底问无由。\n恍忽使人愁。\n怕万里长鲸，纵横触破，玉殿琼楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11354, '声声慢', '辛弃疾', '停云霭霭，八表同昏，尽日时雨。\n搔首良朋，门前平陆成江。\n春醪湛湛独抚，限弥襟、闲饮东窗。\n空延伫，恨舟车南北，欲往何从。\n叹息东园佳树，列初荣枝叶，再兢春风。\n日月于征，安得促席从容。\n翩翩何处飞鸟，息庭树、好语和同。\n当年事，问几人、亲友似翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11355, '八声甘州', '辛弃疾', '故将军、饮罢夜归来，长亭解雕鞍。\n恨灞陵醉尉，匆匆未识，桃李无言。\n射虎山横一骑，裂石响惊弦。\n落托封侯事，岁晚田间。\n谁向桑麻杜曲，要短衣匹马，移住南山。\n看风流慷慨，谈笑过残年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11356, '水调歌头', '辛弃疾', '相公倦台鼎，要伴赤松游。\n高牙千里东下，笳鼓万貔貅。\n试问东山风月，更著中年丝竹，留得谢公不。\n孺子宅边水，云影自悠悠。\n占古语，方人也，正黑头。\n穹龟突兀千丈，石打玉溪流。\n金印沙堤时节，画栋珠帘云雨，一醉早归休。\n贱子亲再拜，西北有神州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11357, '水调歌头', '辛弃疾', '长恨复长恨，裁作短歌行。\n何人为我楚舞，听我楚狂声。\n余既滋兰九畹，又树蕙之百亩，秋菊更餐英。\n门外沧浪水，可以濯吾缨。\n一杯酒，问何似，身後名。\n人间万事，□□常重泰山轻。\n悲莫悲生离别，乐莫乐新相识，儿女古今情。\n富贵非吾事，归与白鸥盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11358, '水调歌头', '辛弃疾', '我亦卜居者，岁晚望三闾。\n昂昂千里，泛泛不作水中凫。\n好在书携一束，莫问家徒四壁，往日置锥无。\n借车载家具，家具少於车。\n舞乌有，歌亡是，饮子虚。\n二三子者爱我，此外故人疏。\n幽事欲论谁共，白鸥飞来似可，忽去复何如。\n群鸟欣有托，吾亦爱吾庐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11359, '水调歌头', '辛弃疾', '四坐且勿语，听我醉中吟。\n池塘春草未歇，高树变鸣禽。\n鸿雁初飞江上，蟋蟋还来床下，时序百年心。\n谁要卿料理，山水有清音。\n欢多少，歌长短，酒浅深。\n而今已不如昔，後定不如今。\n闲处直须行乐，良夜更教秉烛，高会惜分阴。\n白发短如许，黄菊倩谁簪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11360, '水龙吟', '辛弃疾', '昔时曾有佳人，翩然绝世而独立。\n未论一顾倾城，再顾又倾人国。\n宁不知其，倾城倾国，佳人难得。\n看行云行雨，朝朝暮暮，阳台下、襄王侧。\n堂上更阑烛灭。\n记主人、留髡送客。\n合尊促坐，罗襦襟解，微闻芗泽。\n当此之时，止乎礼义，不淫其色。\n但□□□□，啜其泣矣，又何嗟及。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11361, '贺新郎', '辛弃疾', '翠浪吞平野。\n挽天河、谁来照影，卧龙山下。\n烟雨偏宜晴更好，约略西施未嫁。\n待细把、江山图画。\n千顷光中堆滟，似扁舟、欲下瞿塘马。\n中有句，浩难写。\n诗人例入西湖社。\n记风流、重来手种，绿阴成也。\n陌上游人夸故国，十里水晶台榭。\n更夏道、横空清夜。\n粉黛中□歌妙曲，问当年、鱼鸟无存者。\n堂上燕，又长夏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11362, '贺新郎', '辛弃疾', '觅句如东野。\n想钱塘、风流处士，水仙祠下。\n更隐小孤烟浪里，望断彭郎欲嫁。\n是一色、空难画。\n谁解胸中吞云梦，试呼来、草赋看司马。\n须更把，上林写。\n鸡豚旧日渔樵社。\n问先生、带湖春涨，几时归也。\n为爱琉璃三万顷，正卧水亭烟榭。\n对玉塔、微澜深夜。\n雁鹜如云休报事，被诗逢敌手皆者。\n春草梦，也宜夏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11363, '贺新郎', '辛弃疾', '绿树听鹈。\n更那堪、鹧鸪声住，杜鹃声切。\n啼到春归无寻处，苦恨芳菲都歇。\n算未抵、人间离别。\n马上琵琶关塞黑，更长门、翠辇辞金阙。\n看燕燕，送归妾。\n将军百战身名裂。\n向河梁、回头万里，故人长绝。\n易水萧萧西风冷，满座衣冠似雪。\n正壮士、悲歌未彻。\n啼鸟还知如许恨，料不啼清泪长啼血。\n谁共我，醉明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11364, '贺新郎', '辛弃疾', '甚矣吾衰矣。\n怅平生、交游零落，只今馀几。\n白发空垂三千丈，一笑人间万事。\n问何物、能令公喜。\n我见青山多妩媚，料青山、见我应如是。\n情与貌，略相似。\n一尊搔首东窗里。\n想渊明、停云诗就，此时风味。\n江左沈酣求名者，岂识浊醪妙理。\n回首叫、云飞风起。\n不恨古人吾不见，恨古人、不见吾狂耳。\n知我者，二三子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11365, '沁园春', '辛弃疾', '我见君来，顿觉吾庐，溪山美哉。\n怅平生肝胆，都成楚越，只今胶膝，谁是陈雷。\n搔首踟蹰，爱而不见，要得诗来渴望梅。\n还知否，快清风入手，日看千回。\n直须抖擞尘埃。\n人怪我柴门今始开。\n向松间乍可，从他喝道，庭中且莫，踏破苍苔。\n岂有文章，谩劳车马，待唤青刍白饭来。\n君非我，任功名意气，莫恁徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11366, '沁园春', '辛弃疾', '杯汝来前，老子今朝，点检形骸。\n甚长年抱渴，咽如焦釜，于今喜睡，气似奔雷。\n汝说刘伶，古今达者，醉後何妨死便埋。\n浑如此，叹汝於知已，真少恩哉。\n更凭歌舞为媒。\n算合作平居鸠毒猜。\n况怨无大小，生於所爱，物无美恶，过则为灾。\n与汝成言，勿留亟退，吾力犹能肆汝杯。\n杯再拜，道麾之即去，招则须来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11367, '沁园春', '辛弃疾', '杯汝知乎，酒泉罢侯，鸱夷乞骸。\n更高阳入谒，都称齑臼，杜康初筮，正得云雷。\n细数从前，不堪余恨，岁月都将曲埋。\n君诗好，似提壶却劝，沽酒何哉。\n君言病岂无媒。\n似壁上雕弓蛇暗猜。\n记醉眠陶令，终全至乐，独醒屈子，未免沈灾。\n欲听公言，惭非勇者，司马家儿解覆杯。\n还堪笑，借今宵一醉，为故人来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11368, '哨遍', '辛弃疾', '蜗角斗争，左触右蛮，一战连千里。\n君试思、方寸此心微。\n总虚空、并包无际。\n喻此理。\n何言泰山毫末，从来天地一米。\n嗟大小相形，鸠鹏自乐，之二虫又何知。\n记跖行仁义孔丘非。\n更殇乐长年老彭悲。\n火鼠论寒，冰蚕语热，定谁同异。\n噫。\n贵贱随时。\n连城才换一羊皮。\n谁与齐万物，庄周吾梦见之。\n正商略遗篇，翩然顾笑，空堂梦觉题秋水。\n有客问洪河，百川灌雨，泾流不辨涯。\n於是焉河伯欣然喜。\n以天下之美尽在己。\n渺沧溟望洋东视。\n逡巡向若惊叹，谓我非逢子。\n大方达观之家，未免长见，犹然笑耳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11369, '哨遍', '辛弃疾', '一壑自专，五柳笑人，晚乃归田里。\n问谁知、几者动之微。\n望飞鸿、冥冥天际。\n论妙理。\n浊醪正堪长醉。\n从今自酿躬耕米。\n嗟美恶难齐，盈虚如代，天耶何必人知。\n试回头五十九年非。\n似梦里欢娱觉来悲。\n夔乃怜，谷亦亡羊，算来何异。\n嘻。\n物讳穷时。\n丰狐文豹罪因皮。\n富贵非吾愿，皇皇乎欲何之。\n正万籁都沈，月明中夜，心弥万里清如水。\n却自觉神游，归来坐对，依稀淮岸江。\n看一时鱼鸟忘情喜。\n会我已忘机更忘己。\n又何曾物我相视。\n非会濠梁遗意，要是吾非子。\n但教河伯、休惭海若，大小均为水耳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11370, '念奴娇', '辛弃疾', '未须草草，赋梅花，多少骚人词客。\n总被西湖林处士，不肯分留风月。\n疏影横斜，暗香浮动，□□春消息。\n尚馀花品，未忝今古人物。\n看取香月堂前，岁寒相对，楚两龚之洁。\n自与诗家成一种，不系南昌仙籍。\n怕是当年，香山老子，姓白来江国。\n谪仙人，字太白，还又名白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11371, '念奴娇', '辛弃疾', '为沽美酒，过溪来、谁道幽人难致。\n更觉元龙楼百尺，湖海平生豪气。\n自叹年来，看花索句，老不如人意。\n东风归路，一川松竹如醉。\n怎得身似庄周，梦中蝴蝶，花底人间世。\n记取江头三月暮，风雨不为春计。\n万斛愁来，金貂头上，不抵银瓶贵。\n无多笑我，此篇聊当宾戏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11372, '感皇恩', '辛弃疾', '富贵不须论，公应自有。\n且把新词祝公寿。\n当年仙桂，父子同攀希有。\n人言金殿上，他年又。\n冠冕在前，周公拜手。\n同日催班鲁公後。\n此时人羡，绿鬓朱颜依旧。\n亲朋来贺喜，休辞酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11373, '感皇恩', '辛弃疾', '案上数编书，非庄即老。\n会说忘言始知道。\n万言千句，自不能忘堪笑。\n朝来梅雨霁，青青好。\n一壑一丘，轻衫短帽。\n白发多时故人少。\n子云何在，应有玄经□草。\n江河流日夜，何时了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11374, '感皇恩', '辛弃疾', '七十古来稀，未为稀有。\n须是荣华更长久。\n满床靴笏，罗列儿孙新妇。\n精神浑是个，西王母。\n遥想画堂，两行红袖。\n妙舞清歌拥前後。\n大男小女，逐个出来为寿。\n一个一百岁，一杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11375, '南乡子', '辛弃疾', '无处著春光。\n天上飞来诏十行。\n父老欢呼童稚舞，前江。\n千载周家孝义乡。\n草木尽芬芳。\n更觉溪头水也香。\n我道乌头门侧畔，诸郎。\n准备他年昼锦堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11376, '小重山', '辛弃疾', '绿涨连云翠拂空。\n十分风月处，著衰翁。\n垂杨影断岸西东。\n君恩重，教且种芙蓉。\n十里水晶宫。\n有时骑马去，笑儿童。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11377, '婆罗门引', '辛弃疾', '落花时节，杜鹃声里送君归。\n未消文字湘累。\n只怕蛟龙云雨，後会渺难期。\n更何人念我，老大伤悲。\n已而已而。\n算此意、只君知。\n记取岐亭买酒，云洞题诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11378, '婆罗门引', '辛弃疾', '绿阴啼鸟，阳关未彻早催归。\n歌珠凄断累累。\n回首海山何处，千里共襟期。\n叹高山流水，弦断堪悲。\n中心怅而。\n似风雨、落花知。\n更拟停云君去，细□陶诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11379, '婆罗门引', '辛弃疾', '落星万点，一天宝焰下层霄。\n人间叠作仙鳌。\n最爱金连侧畔，红粉袅花梢。\n更鸣鼍击鼓，喷玉吹箫。\n曲江画桥。\n记花月、可怜宵。\n想见闲愁未了，宿酒才消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11380, '行香子', '辛弃疾', '好雨当春。\n要趁归耕。\n况而今、已是清明。\n小窗坐地，侧听檐声。\n恨夜来风，夜来月，夜来云。\n花絮飘零。\n莺燕丁宁。\n怕妨侬、湖上闲行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11381, '行香子', '辛弃疾', '白露园蔬。\n碧水溪鱼。\n笑先生、网钓还锄。\n小窗高卧，风展残书。\n看北移山，盘谷序，辋川图。\n白饭青刍。\n赤脚长须。\n客来时、酒尽重沽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11382, '行香子', '辛弃疾', '云岫如簪。\n野涨蓝。\n向春阑、绿醒红酣。\n青裙缟袂，两两三三。\n把曲生禅，玉版句，一时参。\n拄杖弯环。\n过眼嵌岩。\n岸轻乌、白发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11383, '粉蝶儿', '辛弃疾', '昨日春如，十三女儿学绣。\n一枝枝、不教花瘦。\n甚无情，便下得，雨风。\n向园林、铺作地衣红绉。\n而今春似，轻薄荡子难久。\n记前时、送春归後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11384, '锦帐春', '辛弃疾', '春色难留，酒杯常浅。\n把旧恨、新愁相间。\n五更风，千里梦，看飞红几片。\n这般庭院。\n几许风流，几般娇懒。\n问相见、何如不见。\n燕飞忙，莺语乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11385, '夜游宫', '辛弃疾', '几个相知可喜。\n才厮见、说山说水。\n颠倒烂熟只这是。\n怎奈向，一回说，一回美。\n有个尖新底。\n说底话、非名即利。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11386, '浪淘沙', '辛弃疾', '身世酒杯中。\n万事皆空。\n古来三五个英雄。\n雨打风吹何处是，汉殿秦宫。\n梦入少年丛。\n歌舞匆匆。\n老僧夜半误鸣钟。\n惊起西窗眠不得，卷地西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11387, '河传', '辛弃疾', '春水。\n千里。\n孤舟浪起。\n梦携西子。\n觉来村巷夕阳斜。\n几家。\n短墙红杏花。\n晚云做造些儿雨。\n折花去。\n岸上谁家女。\n太狂颠。\n那岸边。\n柳绵。\n被风吹上天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11388, '西江月', '辛弃疾', '人道偏宜歌舞，天教只入丹青。\n喧天画鼓要他听。\n把著花枝不应。\n何处娇魂瘦影，向来软语柔情。\n有时醉里唤卿卿。\n却被傍人笑问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11389, '西江月', '辛弃疾', '万事云烟忽过，一身蒲柳先衰。\n而今何事最相宜。\n宜醉宜游宜睡。\n早趁催科了纳，更量出入收支。\n乃翁依旧管些儿。\n管竹管山管水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11390, '丑奴儿・采桑子', '辛弃疾', '少年不识愁滋味，爱上层楼。\n爱上层楼。\n为赋新词强说愁。\n而今识尽愁滋味，欲说还休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11391, '破阵子', '辛弃疾', '少日春风满眼，而今秋叶辞柯。\n便好消磨心下事，莫忆寻常醉後歌。\n可怜白发多。\n明日扶头颠倒，倩谁伴舞婆娑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11392, '破阵子', '辛弃疾', '宿麦畦中雉，柔桑陌上蚕生。\n骑火须防花月暗，玉唾长携彩笔行。\n隔墙人笑声。\n莫说弓刀事业，依然诗酒功名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11393, '定风波', '辛弃疾', '少日犹堪话别离。\n老来怕作送行诗。\n极目南云无过雁。\n君看。\n梅花也解寄相思。\n无限江山行未了。\n父老。\n不须和泪看旌旗。\n後会丁宁何日□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11394, '定风波', '辛弃疾', '莫望中州叹黍离。\n元和圣德要君诗。\n老去不堪谁似我。\n归卧。\n青山活计费寻思。\n谁筑诗墙高十丈。\n直上。\n看君斩将更搴旗。\n歌舞正浓还有语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11395, '踏莎行', '辛弃疾', '进退存亡，行藏用舍。\n小人请学樊须稼。\n衡门之下可栖迟，日之夕矣□□下。\n去卫灵公，遭桓司马。\n东西南北之人也。\n长沮粲溺耦而耕，丘何为是栖栖者。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11396, '汉宫春', '辛弃疾', '春已归来，看美人头上，袅袅春幡。\n无端风雨，未肯收尽馀寒。\n年时燕子，料今宵、梦到西园。\n浑未办、黄柑荐酒，更传青韭堆盘。\n却笑东风从此，便薰梅染柳，更没些闲。\n闲时又来镜里，转变朱颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11397, '归朝欢', '辛弃疾', '山下千林花太俗。\n山上一枝看不足。\n春风正在此花边，菖蒲自蘸清溪绿。\n与花同草木。\n问谁风雨飘零速。\n莫怨歌，夜深岩下，惊动白云宿。\n病怯残年频自卜。\n老爱遗编难细读。\n苦无妙手画於菟，人间雕刻真成鹄。\n梦中人似玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11398, '玉蝴蝶', '辛弃疾', '古道行人来去，香红满树，风雨残花。\n望断青山，高处都被云遮。\n客重来、风流觞咏，春已去、光景桑麻。\n苦无多。\n一条垂柳，两个啼鸦。\n人家。\n疏疏翠竹，阴阴绿树，浅浅寒沙。\n醉兀篮舆，夜来豪饮太狂些。\n到如今、都齐醒却，只依旧、无奈愁何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11399, '雨中花慢', '辛弃疾', '旧雨常来，今□不来，佳人偃蹇谁留。\n幸山中芋栗，今岁全收。\n贫贱交情落落，古今吾道悠悠。\n怪新来却见，文反离骚，诗□秦州。\n功名只道，无之不乐，那知有更堪忧。\n怎奈向、儿曹抵死，唤不回头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11400, '临江仙', '辛弃疾', '一自酒情诗兴懒，舞裙歌扇阑珊。\n好天良夜月团团。\n杜陵真好事，留得一钱看。\n岁晚人欺程不识，怎教阿堵留连。\n杨花榆荚雪漫天。\n从今花影下，只看绿苔圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11401, '临江仙', '辛弃疾', '鼓子花开春烂漫，荒园无限思量。\n今朝拄杖过西乡。\n急呼桃叶渡，为看牡丹忙。\n不管昨宵风雨横，依然红紫成行。\n白头陪奉少年场。\n一枝簪不住，推道帽檐长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11402, '玉楼春', '辛弃疾', '三三两两谁家女。\n听取鸣禽枝上语。\n提壶沽酒已多时，婆饼焦时须早去。\n醉中忘却来时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11403, '南歌子', '辛弃疾', '散发披襟处，浮瓜沈李杯。\n涓涓流水细侵阶。\n凿个池儿，唤个月儿来。\n画栋频摇动，红葵尽倒开。\n斗匀红粉照香腮。\n有个人人，把做镜儿猜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11404, '品令', '辛弃疾', '更休说。\n便是个、住世观音菩萨。\n甚今年、容貌八十岁，见底道、才十八。\n莫献寿星香烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11405, '武陵春', '辛弃疾', '桃李风前多妩媚，杨柳更温柔。\n唤取笙歌烂熳游。\n且莫管闲愁。\n好趁春晴连夜赏，雨便一春休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11406, '鹧鸪天', '辛弃疾', '聚散匆匆不偶然。\n二年遍历楚山川。\n但将痛饮酬风月，莫放离歌入管弦。\n萦绿带，点青钱。\n东湖春水碧连天。\n明朝放我东归去，後夜相思月满船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11407, '鹧鸪天', '辛弃疾', '翰墨诸君久擅场。\n胸中书传许多香。\n苦无丝竹衔杯乐，却看龙蛇落笔忙。\n闲意思，老风光。\n酒徒今有几高阳。\n黄花不怯秋风冷，只怕诗人两鬓霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11408, '鹧鸪天', '辛弃疾', '万事纷纷一笑中。\n渊明把菊对秋风。\n细看爽气今犹在，惟有南山一似翁。\n情味好，语言工。\n三贤高会古来同。\n谁知止酒停云老，独立斜阳数过鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11409, '鹧鸪天', '辛弃疾', '点尽苍苔色欲空。\n竹篱茅舍要诗翁。\n花馀歌舞欢娱外，诗在经营惨澹中。\n听软语，笑衰容。\n一枝斜坠翠鬟松。\n浅颦轻笑谁堪醉，看取萧然林下风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11410, '鹧鸪天', '辛弃疾', '病绕梅花酒不空。\n齿牙牢在莫欺翁。\n恨无飞雪青松畔，却放疏花翠叶中。\n冰作骨，玉为容。\n当年宫额鬓云松。\n直须烂醉烧银烛，横笛难堪一再风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11411, '鹧鸪天', '辛弃疾', '句里春风正剪裁。\n溪山一片画图开。\n轻鸥自趁虚船去，荒犬还迎野妇回。\n松菊竹，翠成堆。\n要擎残雪斗疏梅。\n乱鸦毕竟无才思，时把琼瑶蹴下来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11412, '鹧鸪天', '辛弃疾', '石壁虚云积渐高。\n溪声绕屋几周遭。\n自从一雨花零乱，却爱微风草动摇。\n呼玉友，荐溪毛。\n殷勤野老苦相邀。\n杖藜忽避行人去，认是翁来却过桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11413, '鹧鸪天', '辛弃疾', '自古高人最可嗟。\n只因疏懒取名多。\n居山一似庚桑楚，种树真成郭橐驼。\n云子饭，水晶瓜。\n林间携客更烹茶。\n君归休矣吾忙甚，要看蜂儿趁晚衙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11414, '鹧鸪天', '辛弃疾', '掩鼻人间臭腐场。\n古来惟有酒偏香。\n自从归住云烟畔，直到而今歌舞忙。\n呼老伴，共秋光。\n黄花何事避重阳。\n要知烂熳开时节，直待西风一夜霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11415, '鹧鸪天', '辛弃疾', '谁共春光管日华。\n朱朱纷纷野蒿花。\n闲愁投老无多子，酒病而今较减些。\n山远近，路横斜。\n正无聊处管弦哗。\n去年醉处犹能记，细数溪边第几家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11416, '鹧鸪天', '辛弃疾', '占断雕栏只一株。\n春风费尽几工夫。\n天香夜染衣犹湿，国色朝酣酒未苏。\n娇欲语，巧相扶。\n不妨老干自扶疏。\n恰如翠幕高堂上，来看红衫百子图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11417, '鹧鸪天', '辛弃疾', '翠盖牙签几百株。\n杨家姊妹夜游初。\n五花结队香如雾，一朵倾城醉未苏。\n闲小立，困相扶。\n夜来风雨有情无。\n愁红惨绿今宵看，却似吴宫教阵图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11418, '鹧鸪天', '辛弃疾', '浓紫深红一画图。\n中间更著玉盘盂。\n先裁翡翠装成盖，更点胭脂染透酥。\n香潋滟，锦模糊。\n主人长得醉功夫。\n莫携弄玉栏边去，羞得花枝一朵无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11419, '鹧鸪天', '辛弃疾', '老病那堪岁月侵。\n霎时光景值千金。\n一生不负溪山债，百药难治书史淫。\n随巧拙，任浮沈。\n人无同处面如心。\n不妨旧事从头记，要写行藏入笑林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11420, '鹧鸪天', '辛弃疾', '鸡鸭成群晚不收。\n桑麻长过屋山头。\n有何不可吾方羡，要底都无饱便休。\n新柳树，旧沙洲。\n去年溪打那边流。\n自言此地生儿女，不嫁金家即聘周。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11421, '鹧鸪天', '辛弃疾', '不向长安路上行。\n却教山寺厌逢迎。\n味无味处求吾乐，材不材间过此生。\n宁作我，岂其卿。\n人间走遍却归耕。\n一松一竹真朋友，山鸟山花好弟兄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11422, '鹧鸪天', '辛弃疾', '是处移花是处开。\n古今兴废几池台。\n背人翠羽偷鱼去，抱蕊黄须趁蝶来。\n掀老瓮，拨新醅。\n客来且尽两三杯。\n日高盘馔供何晚，市远鱼鲑买未回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11423, '浣溪沙', '辛弃疾', '寸步人间百尺楼。\n孤城春水一沙鸥。\n天风吹树几时休。\n突兀趁人山石狠，朦胧避路野花羞。\n人家平水庙东头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11424, '浣溪沙', '辛弃疾', '细听春山杜宇啼。\n一声声是送行诗。\n朝来白鸟背人飞。\n对郑子真岩石卧，趁陶元亮菊花期。\n而今堪诵北山移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11425, '浣溪沙', '辛弃疾', '草木於人也作疏。\n秋来咫尺共荣枯。\n空山晚翠孰华余。\n孤竹君穷犹抱节，赤松子嫩已生须。\n主人相爱肯留无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11426, '浣溪沙', '辛弃疾', '艳杏夭桃两行排。\n莫携歌舞去相催。\n次第未堪供醉眼，去年栽。\n春意才从梅里过，人情都向柳边来。\n咫尺东家还又有，海棠开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11427, '浣溪沙', '辛弃疾', '酒面低迷翠被重。\n黄昏院落月朦胧。\n堕髻啼妆孙寿醉，泥秦宫。\n试问花留春几日，略无人管雨和风。\n瞥向绿珠楼下见，坠残红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11428, '浣溪沙', '辛弃疾', '强欲加餐竟未佳。\n只宜长伴病僧斋。\n心似风吹香篆过，也无灰。\n山上朝来云出岫，随风一去未曾回。\n次第前村行雨了，合归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11429, '浣溪沙', '辛弃疾', '新葺茅檐次第成。\n青山恰对小窗横。\n去年曾共燕经营。\n病怯杯盘甘止酒，老依香火苦翻经。\n夜来依旧管弦声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11430, '浣溪沙', '辛弃疾', '花向今朝粉面匀。\n柳因何事翠眉颦。\n东风吹雨细於尘。\n自笑好山如好色，只今怀树更怀人。\n闲愁闲恨一番新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11431, '浣溪沙', '辛弃疾', '台倚崩崖玉灭瘢。\n青山却作捧心颦。\n远林烟火几家村。\n引入沧浪鱼得计，展成寥阔鹤能言。\n几时高处见层轩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11432, '浣溪沙', '辛弃疾', '总把平生入醉乡。\n大都三万六千场。\n今古悠悠多少事，莫思量。\n微有寒些春雨好，更无寻处野花香。\n年去年来还又笑，燕飞忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11433, '浣溪沙', '辛弃疾', '北陇田高踏水频。\n西溪禾早已尝新。\n隔墙沽酒□纤鳞。\n忽有微凉何处雨，更无留影霎时云。\n卖瓜声过竹边村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11434, '新荷叶', '辛弃疾', '曲水流觞，赏心乐事良辰。\n兰蕙光风，转头天气还新。\n明眸皓齿，看江头、有女如云。\n折花归去，绮罗陌上芳尘。\n能几多春。\n试听啼鸟殷勤。\n览物兴怀，向来哀乐纷纷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11435, '生查子', '辛弃疾', '漫天春雪来，才抵梅花半。\n最爱雪边人，楚些裁成乱。\n雪儿偏解歌，只要金杯满。\n谁道雪天寒，翠袖阑干暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11436, '生查子', '辛弃疾', '去年燕子来，帘幕深深处。\n香径得泥归，都把琴书污。\n今年燕子来，谁听呢喃语。\n不见卷帘人，一阵黄昏雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11437, '昭君怨', '辛弃疾', '人面不如花面。\n花到开时重见。\n独倚小阑干。\n许多山。\n落叶西风时候。\n人共青山都瘦。\n说道梦阳台。\n几曾来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11438, '乌夜啼', '辛弃疾', '晚花露叶风条。\n燕飞高。\n行过长廊西畔、小红桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11439, '朝中措', '辛弃疾', '年年团扇怨秋风。\n愁绝宝杯空。\n山下卧龙丰度，台前戏马英雄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11440, '朝中措', '辛弃疾', '夜深残月过山房。\n睡觉北窗凉。\n起绕中庭独步，一天星斗文章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11441, '河渎神', '辛弃疾', '芳草绿萋萋。\n断肠绝浦相思。\n山头人望翠云旗。\n蕙香佳酒君归。\n惆怅画檐双燕舞。\n东风吹散灵雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11442, '太常引', '辛弃疾', '一轮秋影转金波。\n飞镜又重磨。\n把酒问娥。\n被白发、欺人奈何。\n乘风好去，长空万里，直下看山河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11443, '清平乐', '辛弃疾', '少年痛饮。\n忆向吴江醒。\n明月团圆高树影。\n十里蔷薇水冷。\n大都一点宫黄。\n人间直恁芳芬。\n怕是九天风露，染教世界都香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11444, '清平乐', '辛弃疾', '东园向晓。\n阵阵西风好。\n唤起仙人金小小。\n翠羽玲珑装了。\n一枝沈畔开时。\n罗帏翠幕低垂。\n恁地十分遮护，打窗早有蜂儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11445, '清平乐', '辛弃疾', '春宵睡重。\n梦里还相送。\n枕畔起寻双玉凤。\n半日才知是梦。\n一从卖翠人还。\n又无音信经年。\n却把泪来做水，流也流到伊边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11446, '菩萨蛮', '辛弃疾', '旌旗依旧长亭路。\n尊前试点莺花数。\n何处捧心颦。\n人间别样春。\n功名君自许。\n少日闻鸡舞。\n诗句到梅花。\n春风十万家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11447, '菩萨蛮', '辛弃疾', '画楼影蘸清溪水。\n歌声响彻行云里。\n帘幕燕双双。\n绿杨低映窗。\n曲中特地误。\n要试周郎顾。\n醉里客魂消。\n春风大小乔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11448, '菩萨蛮', '辛弃疾', '万金不换囊中术。\n上医元自能医国。\n软语到更阑。\n绨袍范叔寒。\n江头杨柳路。\n马踏春风去。\n快趁两三杯。\n河豚欲上来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11449, '菩萨蛮', '辛弃疾', '看灯元是菩提叶。\n依然会说菩提法。\n法似一灯明。\n须叟千万灯。\n灯边花更满。\n谁把空花散。\n说与病维摩。\n而今天女歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11450, '菩萨蛮', '辛弃疾', '游人占却岩中屋。\n白云只向檐头宿。\n谁解探玲珑。\n青山十里空。\n松篁通一径。\n噤山花冷。\n今古几千年。\n西乡小有天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11451, '菩萨蛮', '辛弃疾', '葛巾自向沧浪濯。\n朝来漉酒那堪著。\n高树莫鸣蝉。\n晚凉秋水眠。\n竹床能几尺。\n上有华胥国。\n山上咽飞泉。\n梦中琴断弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11452, '柳梢青', '辛弃疾', '莫炼丹难。\n黄河可塞，金可成难。\n休辟谷难。\n吸风饮露，长忍饥难。\n劝君莫远游难。\n何处有、西王母难。\n休采药难。\n人沈下土，我上天难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11453, '贺新郎', '辛弃疾', '濮上看垂钓。\n更风流、羊裘泽畔，精神孤矫。\n楚汉黄金公卿印，比著渔竿谁小。\n但过眼、才堪一笑。\n惠子焉知濠梁乐，望桐江、千丈高台好。\n烟雨外，几鱼鸟。\n古来如许高人少。\n细平章、两翁似与，巢由同调。\n已被尧知方洗耳，毕竟尘污人了。\n要名字、人间如扫。\n我爱蜀庄沈冥者，解门前、不使徵书到。\n君为我，画三老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11454, '贺新郎', '辛弃疾', '下马东山路。\n恍临风、周情孔思，悠然千古。\n寂寞东家丘何在，缥缈危亭小鲁。\n试重上、岩岩高处。\n更忆公归西悲日，正、陌上多零雨。\n嗟费却，几章句。\n谢安雅志还成趣。\n记风流、中年怀抱，长携歌舞。\n政尔良难君臣事，晚听秦筝声苦。\n快满眼、松篁千亩。\n把似渠垂功名泪，算何如、且作溪山主。\n双白鸟，又飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11455, '贺新郎', '辛弃疾', '逸气轩眉宇。\n似王良、轻车熟路，骅骝欲舞。\n我觉君非池中物，咫尺蛟龙云雨。\n时与命、犹须天付。\n兰佩芳菲无人问，叹灵均、欲向重华诉。\n空壹郁，共谁语。\n儿曹不料扬雄赋。\n怪当年、甘泉误说，青葱玉树。\n风引船回沧溟阔，目断三山伊阻。\n但笑指、吾庐何许。\n门外苍官千百辈，尽堂堂、八尺须髯古。\n谁载酒，带湖去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11456, '贺新郎', '辛弃疾', '路入门前柳。\n到君家、悠然细说，渊明重九。\n岁晚凄其无诸葛，惟有黄花入手。\n更西风、东篱依旧。\n斗顿南山高如许，是先生、拄杖归来後。\n山不记，何年有。\n是中不减康庐秀。\n倩西风、为君唤起，翁能来否。\n鸟倦飞还平林去，云肯无心出岫。\n剩准备、新诗几首。\n欲辨忘言当年意，慨遥遥、我去羲农久。\n天下事，可无酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11457, '贺新郎', '辛弃疾', '曾与东山约。\n为鱼、从容分得，清泉一勺。\n堪笑高人读书处，多少松窗竹阁。\n甚长被、游人占却。\n万卷何言达时用，士方穷、早与人同乐。\n新种得，几花药。\n山头怪石蹲秋鹗。\n俯人间、尘埃野马，孤撑高攫。\n拄杖危亭扶未到，已觉云生两脚。\n更换却、朝来毛发。\n此地千年曾物化，莫呼猿、且自多招鹤。\n吾亦有，一丘壑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11458, '贺新郎', '辛弃疾', '拄杖重来约。\n对东风、洞庭张乐，满空箫勺。\n巨海拔犀头角出，来向此山高阁。\n尚两两、三三前却。\n老我伤怀登临际，问何方、可以平哀乐。\n唯酒是，万金药。\n劝君且作横空鹗。\n便休论、人间腥腐，纷纷乌攫。\n九万里风斯在下，翻覆云头雨脚。\n更直上、濯发。\n好卧长虹陂十里，是谁言、听取双黄鹤。\n推翠影，浸云壑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11459, '贺新郎', '辛弃疾', '听我三章约。\n有谈功、谈名者舞，谈经深酌。\n作赋相如亲涤器，识字子云投阁。\n算枉把、精神费却。\n此会不如公荣者，莫呼来、政尔妨人乐。\n医俗士，苦无药。\n当年众鸟看孤鹗。\n意飘然、横空直把，曹吞刘攫。\n老我山中谁来伴，须信穷愁有脚。\n似剪尽、还生僧发。\n自断此生天休问，倩何人、说与乘轩鹤。\n吾有志，在沟壑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11460, '贺新郎', '辛弃疾', '高阁临江渚。\n访层城、空馀旧迹，黯然怀古。\n画栋珠帘当日事，不见朝云暮雨。\n但遗意、西山南浦。\n天宇修眉浮新绿，映悠悠、潭影长如故。\n空有恨，奈何许。\n王郎健笔夸翘楚。\n到如今、落霞孤鹜，竞传佳句。\n物换星移知几度，梦想珠歌翠舞。\n为徙倚、阑干凝伫。\n目断平芜苍波晚，快江风、一瞬澄襟暑。\n谁共饮，有诗侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11461, '水龙吟', '辛弃疾', '老来曾识渊明，梦中一见参差是。\n觉来幽恨，停觞不御，欲歌还止。\n白发西风，折腰五斗，不应堪此。\n问北窗高卧，东篱自醉，应别有、归来意。\n须信此翁未死。\n到如今、凛然生气。\n吾侪心事，古今长在，高山流水。\n富贵他年，直饶未免，也应无味。\n甚东山何事，当时也道，为苍生起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11462, '水龙吟', '辛弃疾', '被公惊倒瓢泉，倒流三峡词源泻。\n长安纸贵，流传一字，千金争舍。\n割肉怀归，先生自笑，又何廉也。\n但衔杯莫问，人间岂有，如孺子、长贫者。\n谁识稼轩心事，似风乎、舞雩之下。\n回头落日，苍茫万里，尘埃野马。\n更想隆中，卧龙千尺，高吟才罢。\n倩何人与问，雷鸣瓦釜，甚黄锺哑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11463, '水调歌头', '辛弃疾', '木末翠楼出，诗眼巧安排。\n天公一夜，削出四面玉崔嵬。\n畴昔此山安在，应为先生见挽，万马一时来。\n白鸟飞不尽，却带夕阳回。\n劝公饮，左手蟹，右手杯。\n人间万事变灭，今古几池台。\n君看庄生达者，犹对山林皋壤，哀乐未忘怀。\n我老尚能赋，风月试追陪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11464, '水调歌头', '辛弃疾', '万事几时足，日月自西东。\n无穷宇宙，人是一粟太仓中。\n一葛一裘经岁，一钵一瓶终日，老子旧家风。\n更著一杯酒，梦觉大槐宫。\n记当年，吓腐鼠，叹冥鸿。\n衣冠神武门外，惊倒几儿童。\n休说须弥芥子，看取鹏斥，小大若为同。\n君欲论齐物，须访一枝翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11465, '水调歌头', '辛弃疾', '唤起子陆子，经德问何如。\n万锺於我何有，不负古人书。\n闻道千章松桂，剩有四时柯叶，霜雪岁寒馀。\n此是山境，还似象山无。\n耕也馁，学也禄，孔子徒。\n青衫毕竟升斗，此意正关渠。\n天地清宁高下，日月东西寒暑，何用著工夫。\n两字君勿惜，借我榜吾庐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11466, '水调歌头', '辛弃疾', '十里深窈窕，万瓦碧参差。\n青山屋上，流水屋下绿横溪。\n真得归来笑语，方是闲中风月，剩费酒边诗。\n点检歌舞了，琴罢更围棋。\n王家竹，陶家柳，谢家池。\n知君勋业未了，不是枕流时。\n莫向痴儿说梦，且作山人索价，颇怪鹤书迟。\n一事定嗔我，已办北山移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11467, '水调歌头', '辛弃疾', '高马勿捶面，千里事难量。\n长鱼变化云雨，无使寸鳞伤。\n一壑一丘吾事，一斗一石皆醉，风月几千场。\n须作猬毛磔，笔作剑锋长。\n我怜君，痴绝似，顾长康。\n纶巾羽扇颠倒，又似竹林狂。\n解道澄江如练，准备停云堂上，千首买秋光。\n怨调为谁赋，一斛贮槟榔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11468, '水调歌头', '辛弃疾', '我志在寥阔，畴昔梦登天。\n摩挲素月，人世俯仰已千年。\n有客骖麟并凤，云遇青山赤壁，相约上高寒。\n酌酒援北斗，我亦虱其间。\n少歌曰，神甚放，形则眠。\n鸿鹄一再高举，天地睹方圆。\n欲重歌兮梦觉，推枕惘然独念，人事底亏全。\n有美人可语，秋水隔娟娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11469, '念奴娇', '辛弃疾', '看公风骨，似长松磊落，多生奇节。\n世上儿曹都蓄缩，冻芋旁堆秋瓞。\n结屋溪头，境随人胜，不是江山别。\n紫云如阵，妙歌争唱新阕。\n尊酒一笑相逢，与公臭味，菊茂兰须悦。\n天上四时调玉烛，万事宜询黄发。\n看取东归，周家叔父，手把元龟说。\n祝公长似，十分今夜明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11470, '念奴娇', '辛弃疾', '龙山何处，记当年高会，重阳佳节。\n谁与老兵供一笑，落帽参军华发。\n莫倚忘怀，西风也会，点检尊前客。\n凄凉今古，眼中三两飞蝶。\n须信采菊东篱，高情千载，只有陶彭泽。\n爱说琴中如得趣，弦上何劳声切。\n试把空杯，翁还肯道，何必杯中物。\n临风一笑，请翁同醉今夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11471, '念奴娇', '辛弃疾', '君诗好处，似邹鲁儒家，还有奇节。\n下笔如神强压韵，遗恨都无毫发。\n灸手炎来，掉头冷去，无限长安客。\n丁宁黄菊，未消勾引蜂蝶。\n天上绛阙清都，听君归去，我自癯山泽。\n人道君才刚百炼，美玉都成泥切。\n我爱风流，醉中颠倒，丘壑胸中物。\n一杯相属，莫孤风月今夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11472, '新荷叶', '辛弃疾', '曲水流觞，赏心乐事良辰。\n今几千年，风流禊事如新。\n明眸皓齿，看江头、有女如云。\n折花归去，绮罗陌上芳尘。\n丝竹纷纷。\n杨花飞鸟衔巾。\n争似群贤，茂林修竹兰亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11473, '新荷叶', '辛弃疾', '种豆南山，零落一顷为萁。\n岁晚渊明，也吟草盛苗稀。\n风流地，向尊前、采菊题诗。\n悠然忽见，此山正绕东篱。\n千载襟期。\n高情想像当时。\n小阁横空，朝来翠扑人衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11474, '婆罗门引', '辛弃疾', '龙泉佳处，种花满县却东归。\n腰间玉若金累。\n须信功名富贵，长与少年期。\n怅高山流水，古调今悲。\n卧龙暂而。\n算天上、有人知。\n最好五十学易，三百篇诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11475, '行香子', '辛弃疾', '少日尝闻。\n富不如贫。\n贵不如、贱者长存。\n由来至乐，总属闲人。\n且饮瓢泉，弄秋水，看停云。\n岁晚情亲。\n老语弥真。\n记前时、劝我殷勤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11476, '江神子・江城子', '辛弃疾', '簟铺湘竹帐垂纱。\n醉眠些。\n梦天涯。\n一枕惊回，水底沸鸣蛙。\n借问喧天成鼓吹，良自苦，为官哪。\n心空喧静不争多。\n病维摩。\n意云何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11477, '江神子・江城子', '辛弃疾', '两轮屋角走如梭。\n太忙些。\n怎禁他。\n拟倩何人，天上劝羲娥。\n何似从容来小住，倾美酒，听高歌。\n人生今古不须磨。\n积教多。\n似尘沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11478, '沁园春', '辛弃疾', '叠嶂西驰，万马回旋，众山欲东。\n正惊湍直下，跳珠倒溅，小桥横截，缺月初弓。\n老合投闲，天教多事，检校长身十万松。\n吾庐小，在龙蛇影外，风雨声中。\n争先见面重重。\n看爽气朝来三数峰。\n似谢家子弟，衣冠磊落，相如庭户，车骑雍容。\n我觉其间，雄深雅健，如对文章太史公。\n新堤路，问偃湖何日，烟水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11479, '沁园春', '辛弃疾', '甲子相高，亥首曾疑，绛县老人。\n看长身玉立，鹤般风度，方颐须磔，虎样精神。\n文烂卿云，诗凌鲍谢，笔势更右军。\n浑馀事，羡仙都梦觉，金阙名存。\n门前父老忻忻。\n焕奎阁新褒沼语温。\n记他年帷幄，须依日月，只今剑履，快上星辰。\n人道阴功，天教多寿，看到貂蝉七叶孙。\n君家里，是几枝丹桂，几树灵椿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11480, '喜迁莺', '辛弃疾', '暑风凉月。\n爱亭亭无数，绿衣持节。\n掩冉如羞，参差似妒，拥出芙渠花发。\n步衬潘娘堪恨，貌比六郎谁洁。\n添白鹭，晚晴时，公子佳人并列。\n休说。\n搴木末。\n当日灵均，恨与君王别。\n心阻媒劳，交疏怨极，恩不甚兮轻绝。\n千古离骚文字，芳至今犹未歇。\n都休问，但千杯快饮，露荷翻叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11481, '永遇乐', '辛弃疾', '怪底寒梅，一枝雪里，直恁愁绝。\n问讯无言，依稀似妒，天上飞英白。\n江山一夜，琼瑶万顷，此段如何妒得。\n细看来，风流添得，自家越样标格。\n晓来楼上，对花临镜，学作半妆宫额。\n著意争妍，那知却有，人妒花颜色。\n无情休问，许多般事，且自访梅踏雪。\n待行过溪桥，夜半更邀素月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11482, '永遇乐', '辛弃疾', '烈日秋霜，忠肝义胆，千载家谱。\n得姓何年，细参辛字，一笑君听取。\n艰辛做就，悲辛滋味，总是辛酸辛苦。\n更十分，向人辛辣，椒桂捣残堪吐。\n世间应有，芳甘浓美，不到吾家门户。\n比著儿曹，累累却有，金印光垂组。\n付君此事，从今直上，休忆对床风雨。\n但赢得，靴纹绉面，记余戏语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11483, '归朝欢', '辛弃疾', '万里康成西走蜀。\n药市船归书满屋。\n有时光彩射星躔，何人汉简雠天禄。\n好之宁有足。\n请看良贾藏金玉。\n记斯文，千年未丧，四壁闻丝竹。\n试问辛勤携一束。\n何似牙签三万轴。\n古来不作借人痴，有朋只就云窗读。\n忆君清梦熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11484, '瑞鹤仙', '辛弃疾', '片帆何太急。\n望一点须臾，去天咫尺。\n舟人好看客。\n似三峡风涛，嵯峨剑戟。\n溪南溪北。\n正遐想、幽人泉石。\n看渔憔、指点危楼，却羡舞筵歌席。\n叹息。\n山林锺鼎，意倦情迁，本无欣戚。\n转头陈迹。\n飞鸟外，晚烟碧。\n问谁怜旧日，南楼老子，最爱月明吹笛。\n到而今、扑面黄尘，欲归未得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11485, '玉蝴蝶', '辛弃疾', '贵贱偶然，浑似随风帘幌，篱落飞花。\n空使儿曹，马上羞面频遮。\n向空江、谁捐玉，寄离恨、应折疏麻。\n暮云多。\n佳人何处，数尽归鸦。\n侬家。\n生涯蜡屐，功名破甑，交友抟沙。\n往日曾论，渊明似胜卧龙些。\n记从来、人生行乐，休更问、日饮亡何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11486, '满江红', '辛弃疾', '我对君侯，长怪见、两眉阴德。\n更长梦、玉皇金阙，姓名仙籍。\n旧岁炊烟浑欲断，被公扶起千人活。\n算胸中、除却五车书，都无物。\n溪左右，山南北。\n花远近，云朝夕。\n看风流杖屦，苍髯如戟。\n种柳已成陶令宅，散花更满维摩室。\n劝人间、且住五千年，如金石。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11487, '雨中花慢', '辛弃疾', '马上三年，醉帽吟鞭，锦囊诗卷长留。\n怅溪山旧管，风月新收。\n明便关河杳杳，去应日月悠悠。\n笑千篇索价，未抵蒲萄，五斗凉州。\n停云老子，有酒盈尊，琴书端可消忧。\n浑未办、倾身一饱，淅米矛头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11488, '洞仙歌', '辛弃疾', '婆娑欲舞，怪青山欢喜。\n分得清溪半篙水。\n记平沙鸥鹭，落日渔樵，湘江上，风景依然如此。\n东篱多种菊，待学渊明，酒兴诗情不相似。\n十里涨春波，一棹归来，只做个、五湖范蠡。\n是则是、一般弄扁舟，争知道，他家有个西子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11489, '洞仙歌', '辛弃疾', '旧交贫贱，太半成新贵。\n冠盖门前几行李。\n看匆匆西笑，争出山来，凭谁问，小草何如远志。\n悠悠今古事。\n得丧乘除，暮四朝三又何异。\n任掀天勋业，冠古文章，有几个、笙歌晚岁。\n况满屋貂蝉未为荣，记裂土分茅，是公家世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11490, '洞仙歌', '辛弃疾', '松关桂岭，望青葱无路。\n费尽银钩榜佳处。\n怅空山岁晚，窈窕谁来，须著我，醉卧石楼风雨。\n仙人琼海上，握手当年，笑许君携半山去。\n叠嶂，卷飞泉，洞府凄凉，又却怪、先生多取。\n怕夜半、罗浮有时还，好长把云烟，再三遮住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11491, '鹧鸪天', '辛弃疾', '欲上高楼去避愁。\n愁还随我上高楼。\n经行几处江山改，多少亲朋尽白头。\n归休去，去归休。\n不成人总要封侯。\n浮云出处元无定，得似浮云也自由。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11492, '鹧鸪天', '辛弃疾', '一片归心拟乱云。\n春来谙尽恶黄昏。\n不堪向晚檐前雨，又待今宵滴梦魂。\n炉烬冷，鼎香氛。\n酒寒谁遣为重温。\n何人柳外横双笛，客耳那堪不忍闻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11493, '卜算子', '辛弃疾', '修竹翠罗寒，迟日江山暮。\n幽迳无人独自芳，此恨知无数。\n只共梅花语。\n懒逐游丝去。\n著意寻春不肯香，香在无寻处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11494, '卜算子', '辛弃疾', '欲行且起行，欲坐重来坐。\n坐坐行行有倦时，更枕闲书卧。\n病是近来身，懒是从前我。\n静扫瓢泉竹树阴，且凭随缘过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11495, '卜算子', '辛弃疾', '红粉靓梳妆，翠盖低风雨。\n占断人间六月凉，期月鸳鸯浦。\n根底藕丝长，花里莲心苦。\n只为风流有许愁，更衬佳人步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11496, '点绛唇', '辛弃疾', '身後功名，古来不换生前醉。\n青鞋自喜。\n不踏长安市。\n竹外僧归，路指霜锺寺。\n孤鸿起。\n丹青手里。\n剪破松江水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11497, '谒金门', '辛弃疾', '遮素月。\n云外金蛇明灭。\n翻树啼鸦声未彻。\n雨声惊落叶。\n宝蜡成行嫌热。\n玉腕藕花谁雪。\n流水高山弦断绝。\n怒蛙声自咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11498, '谒金门', '辛弃疾', '山吐月。\n画烛从教风灭。\n一曲瑶琴才听彻。\n金蕉三两叶。\n骤雨微凉还热。\n似欠舞琼歌雪。\n近日醉乡音问绝。\n有时清泪咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11499, '东坡引', '辛弃疾', '玉纤弹旧怨。\n还敲绣屏面。\n清歌目送西风雁。\n雁行吹字断。\n雁行吹字断。\n夜深拜月，琐窗西畔。\n但桂影、空阶满。\n翠帏自掩无人见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11500, '醉花阴', '辛弃疾', '黄花谩说年年好。\n也趁秋光老。\n绿鬓不惊秋，若斗尊前，人好花堪笑。\n蟠桃结子知多少。\n家住三山岛。\n何日跨归鸾，沧海飞尘，人世因缘了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11501, '清平乐', '辛弃疾', '清词索笑。\n莫厌银杯小。\n应是天孙新与巧。\n剪恨裁愁句好。\n有人梦断关河。\n小窗日饮亡何。\n想见重帘不卷，泪痕滴尽湘娥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11502, '清平乐', '辛弃疾', '灵皇醮罢。\n福禄都来也。\n试引雏花树下。\n断了惊惊怕怕。\n从今日日聪明。\n更宜潭妹嵩兄。\n看取辛家铁柱，无灾无难公卿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11503, '清平乐', '辛弃疾', '月明秋晓。\n翠盖团团好。\n碎剪黄金教恁小。\n都著叶儿遮了。\n折来休似年时。\n小窗能有高低。\n无顿许多香处，只消三两枝儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11504, '醉翁操', '辛弃疾', '长松。\n之风。\n如公。\n肯余从。\n山中。\n人心与吾兮谁问。\n湛湛千里之江。\n上有枫。\n噫，送子东。\n望君之门兮九重。\n女无悦己，谁适为容。\n不龟手药，或一朝兮取封。\n昔与游兮皆童。\n我独穷兮今翁。\n一鱼兮一龙。\n劳心兮忡忡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11505, '西江月', '辛弃疾', '秀骨青松不老，新词玉佩相磨。\n灵槎准拟泛银河。\n剩摘天星几个。\n奠枕楼东风月，驻春亭上笙歌。\n留君一醉意如何。\n金印明年斗大。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11506, '丑奴儿・采桑子', '辛弃疾', '鹅湖山下长亭路，明月临关。\n明月临关。\n几阵西风落叶乾。\n新词谁解裁冰雪，笔墨生寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11507, '破阵子', '辛弃疾', '掷地刘郎玉斗，挂帆西子扁舟。\n千古风流今在此，万里功名莫放休。\n君王三百州。\n燕雀岂知鸿鹄，貂蝉元出兜鍪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11508, '破阵子', '辛弃疾', '醉里挑灯看剑，梦回吹角连营。\n八百里分麾下炙，五十弦翻塞外声。\n沙场秋点兵。\n马作的卢飞快，弓如霹雳弦惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11509, '千年调', '辛弃疾', '左手把青霓，右手挟明月。\n吾使丰隆前导，叫开阊阖。\n周游上下，径入寥天一。\n览县圃，万斛泉，千丈石。\n钧天广乐，燕我瑶之席。\n帝饮予觞甚乐，赐汝苍璧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11510, '祝英台近', '辛弃疾', '水纵横，山远近。\n拄杖占千顷。\n老眼羞将，水底看山影。\n试教水动山摇，吾生堪笑，似此个、青山无定。\n一瓢饮。\n人问翁爱飞泉，来寻个中静。\n绕屋生喧，怎做静中境。\n我眠君且归休，维摩方丈，待天女、散花时问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11511, '祝英台近', '辛弃疾', '绿杨堤，青草渡。\n花片水流去。\n百舌声中，唤起海棠睡。\n断肠几点愁红，蹄痕犹在，多应怨、夜来风雨。\n别情苦。\n马蹄踏遍长亭，归期又成误。\n帘卷青楼，回首在何处。\n画梁燕子双双，能言能语，不解说、相思一句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11512, '江神子・江城子', '辛弃疾', '看君人物汉西都。\n过吾庐。\n笑谈初。\n便说公卿，元自要通儒。\n一自梅花开了後，长怕说，赋归欤。\n而今别恨满江湖。\n怎消除。\n算何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11513, '清平乐', '辛弃疾', '云烟草树。\n山北山南雨。\n溪上行人相背去。\n惟有啼鸦一处。\n门前万斛春寒。\n梅花可摧残。\n使我长忘酒易，要君不作诗难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11514, '临江仙', '辛弃疾', '莫笑吾家苍壁小，棱层势欲摩空。\n相知惟有主人翁。\n有心雄泰华，无意巧玲珑。\n天作高山谁得料，解嘲试倩扬雄。\n君看当日仲尼穷。\n从人贤子贡，自欲学周公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11515, '临江仙', '辛弃疾', '记取年年为寿客，只今明月相随。\n莫教弦管便生衣。\n引壶觞自酌，须富贵何时。\n入手清风词更好，细书白茧乌丝。\n海山问我几时归。\n枣瓜如可啖，直欲觅安期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11516, '临江仙', '辛弃疾', '忆醉三山芳树下，几层风韵忘怀。\n黄金颜色五花开。\n味如庐橘熟。\n贵似荔枝来。\n闻道商山馀四老，橘中自酿秋醅。\n试呼名品细推排。\n重重香腑脏，偏圣贤杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11517, '临江仙', '辛弃疾', '夜语南堂新瓦响，三更急雨珊珊。\n交情莫作细沙团。\n死生贫富际，试向此中看。\n记取他年耆旧传，与君名字牵连。\n清风一枕晚凉天。\n觉来还自笑，此梦倩谁园。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11518, '南乡子', '辛弃疾', '日日老莱衣。\n更解风流蜡凤嬉。\n膝上放教文度去，须知。\n要使人看玉树枝。\n剩记乃翁诗。\n绿水红莲觅旧题。\n归骑春衫花满路，相期。\n来岁流觞曲水时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11519, '玉楼春', '辛弃疾', '有无一理谁差别。\n乐令区区浑未达。\n事言无处未尝无，试把所无凭理说。\n伯夷饥采西山蕨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11520, '玉楼春', '辛弃疾', '客来底事逢迎晚。\n竹里鸣禽寻未见。\n日高犹苦圣贤中，门外谁酣蛮触战。\n多方为渴寻泉遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11521, '玉楼春', '辛弃疾', '何人半夜推山去。\n四面浮云猜是汝。\n常时相对两三峰，走遍溪头无觅处。\n西风瞥起云横渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11522, '玉楼春', '辛弃疾', '青山不会乘云去。\n怕有愚公惊著汝。\n人间踏地出租钱，借使移将无著处。\n三星昨夜光移度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11523, '玉楼春', '辛弃疾', '少年才把笙歌。\n夏日非长秋夜短。\n因他老病不相饶，把好心情都做懒。\n故人别後书来劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11524, '玉楼春', '辛弃疾', '君如九酝台黏。\n我似茅柴风味短。\n几时秋水美人来，长恐扁舟乘兴懒。\n高怀自饮无人劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11525, '玉楼春', '辛弃疾', '狂歌击碎村醪。\n欲舞还怜衫袖短。\n身如溪上钓矶闲，心似道旁官堠懒。\n山中有酒提壶劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11526, '鹧鸪天', '辛弃疾', '趁得东风汗漫游。\n见他歌後怎生愁。\n事如芳草春长在，人似浮云影不留。\n眉黛敛，眼波流。\n十年薄幸谩扬州。\n明朝短棹轻衫梦，只在溪南罨画楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11527, '鹧鸪天', '辛弃疾', '叹息频年廪未高。\n新词空贺此丘遭。\n遥知醉帽时时落，见说吟鞭步步摇。\n乾玉唾，秃锥毛。\n只今明月费招邀。\n最怜乌鹊南飞句，不解风流见二乔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11528, '鹧鸪天', '辛弃疾', '戏马台前秋雁飞。\n管弦歌舞更旌旗。\n要知黄菊清高处，不入当年二谢诗。\n倾白酒，绕东篱。\n只於陶令有心期。\n明朝重九浑潇洒，莫使尊前欠一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11529, '鹧鸪天', '辛弃疾', '水荇参差动绿波。\n一池蛇影噤群蛙。\n因风野鹤饥犹舞，积雨山栀病不花。\n名利处，战争多。\n门前蛮触日干戈。\n不知更有槐安国，梦觉南柯日未斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11530, '鹧鸪天', '辛弃疾', '出处从来自不齐。\n後车方载太公归。\n谁知孤竹夷齐子，正向空山赋采薇。\n黄菊嫩，晚香枝。\n一般同是采花时。\n蜂儿辛苦多官府，蝴蝶花间自在飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11531, '鹧鸪天', '辛弃疾', '秋水长廊水石间。\n有谁来共听潺。\n羡君人物东西晋，分我诗名大小山。\n穷自乐，懒方闲。\n人间路窄酒杯宽。\n看君不了痴儿事，又似风流靖长官。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11532, '鹧鸪天', '辛弃疾', '壮岁旌旗拥万夫。\n锦突骑渡江初。\n燕兵夜银胡，汉箭朝飞金仆姑。\n追往事，叹今吾。\n春风不染白髭须。\n都将万字平戎策，换得东家种树书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11533, '鹧鸪天', '辛弃疾', '上巳风光好放怀。\n忆君犹未看花回。\n茂林映带谁家竹，曲水流传第几杯。\n锦绣，写玫瑰。\n长年富贵属多才。\n要知此日生男好，曾有周公祓禊来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11534, '鹧鸪天', '辛弃疾', '去岁君家把酒杯。\n雪中曾见牡丹开。\n而今纨扇薰风里，又见疏枝月下梅。\n欢几许，醉方回。\n明朝归路有人摧。\n低声待向他家道，带得歌声满耳来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11535, '鹊桥仙', '辛弃疾', '溪边白鹭。\n来吾告汝。\n溪里鱼儿堪数。\n主人怜汝汝怜鱼，要物我、欣然一处。\n白沙远浦。\n青泥别渚。\n剩有虾跳鳅舞。\n任君飞去饱时来，看头上、风吹一缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11536, '西江月', '辛弃疾', '画栋新垂帘幕，华灯未放笙歌。\n一杯潋滟泛金波。\n先向太夫人贺。\n富贵吾应自有，功名不用渠多。\n只将绿鬓抵羲娥。\n金印须教斗大。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11537, '西江月', '辛弃疾', '风月亭危致爽，管弦声脆休催。\n主人只是旧时怀。\n锦瑟旁边须醉。\n玉殿何须侬去，沙堤只要公来。\n看看红药又翻阶。\n趁取西湖春会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11538, '西江月', '辛弃疾', '贪数明朝重九。\n不知过了中秋。\n人生有得许多愁。\n惟有黄花如旧。\n万象亭中酒。\n九江阁上扶头。\n城鸦唤我醉归休。\n细雨斜风时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11539, '西江月', '辛弃疾', '醉里且贪欢笑，要愁那得工夫。\n近来始觉古人书。\n信著全无是处。\n昨夜松边醉倒，问松我醉何如。\n只疑松动要来扶。\n以手推松曰去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11540, '瑞鹧鸪', '辛弃疾', '江头日日打头风。\n憔悴归来邴曼容。\n郑贾正应求死鼠，叶公岂是好真龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11541, '瑞鹧鸪', '辛弃疾', '期思溪上日千回。\n樟木桥边酒数杯。\n人影不随流水去，醉颜重带少年来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11542, '玉楼春', '辛弃疾', '无心云自来还去。\n元共青山相尔汝。\n霎时迎雨障崔嵬，雨过却寻归路处。\n侵天翠竹何曾度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11543, '玉楼春', '辛弃疾', '瘦筇倦作登高去。\n却怕黄花相尔汝。\n岭头拭目望龙安，更在云烟遮断处。\n思量落帽人风度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11544, '玉楼春', '辛弃疾', '风前欲劝春光住。\n春在城南芳草路。\n未随流落水边花，且作飘零泥上絮。\n镜中已觉星星误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11545, '玉楼春', '辛弃疾', '悠悠莫向文山去。\n要把襟裾牛马汝。\n遥知书带草边行，正在雀罗门里住。\n平生插架昌黎句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11546, '玉楼春', '辛弃疾', '琵琶亭畔多芳草。\n时对香炉峰一笑。\n偶然重傍玉溪东，不是白头谁觉老。\n普陀大士神通妙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11547, '玉楼春', '辛弃疾', '江头一带斜阳树。\n总是六朝人住处。\n悠悠兴废不关心，惟有沙洲双白鹭。\n仙人矶下多风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11548, '鹊桥仙', '辛弃疾', '少年风月，少年歌舞，老去方知堪羡。\n叹折腰、五斗赋归来，问走了、羊肠几遍。\n高车驷马，金章紫绶，传语渠侬稳便。\n问东湖、带得几多春，且看凌云笔健。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11549, '西江月', '辛弃疾', '且对东君痛饮，莫教华发空催。\n琼瑰千字已盈怀。\n消得津头一醉。\n休唱阳关别去，只今凰诏归来。\n五云两两望三台。\n已觉精神聚会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11550, '西江月', '辛弃疾', '剩欲读书已懒，只因多病长闲。\n听风听雨小窗眠。\n过了春光太半。\n往事如寻去鸟，清愁难解连环。\n流莺不肯入西园。\n唤起画梁飞燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11551, '西江月', '辛弃疾', '金粟如来出世，蕊宫仙子乘风。\n清香一袖意无穷。\n洗尽尘缘千种。\n长为西风作主，更居明月光中。\n十分秋意与玲珑。\n拼却今宵无梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11552, '西江月', '辛弃疾', '八万四千偈後，更谁妙语披襟。\n纫兰结佩有同心。\n唤取诗翁来饮。\n镂玉栽冰著句，高山流水知音。\n胸中不受一尘侵。\n却怕灵均独醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11553, '西江月', '辛弃疾', '粉面都成醉梦，霜髯能几春秋。\n来时诵我伴牢愁。\n一见尊前似旧。\n诗在阴何侧畔，字居罗赵前头。\n锦囊来往几时休。\n已遣蛾眉等候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11554, '朝中措', '辛弃疾', '年年黄菊滟秋风。\n更有拒霜红。\n黄似旧时宫额，红如此日芳容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11555, '清平乐', '辛弃疾', '溪回沙浅。\n红杏都开遍。\n不知春水暖。\n犹傍垂杨春岸。\n片帆千里轻船。\n行人想见眠。\n谁似先生高举，一行白鹭青天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11556, '好事近', '辛弃疾', '明月到今宵，长是不如人约。\n想见广寒宫殿，正云梳风掠。\n夜深休更唤笙歌，檐头雨声恶。\n不是小山词就，这一场寥索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11557, '好事近', '辛弃疾', '云气上林梢，毕竟非空非色。\n风景不随人去，到而今留得。\n老无情味到篇章，诗债怕人索。\n却笑近来林下，有许多词客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11558, '菩萨蛮', '辛弃疾', '江摇病眼昏如雾。\n送愁直到津头路。\n归念乐天诗。\n人生足别离。\n云屏深夜语。\n梦到君知否。\n玉箸莫偷垂。\n断肠天不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11559, '菩萨蛮', '辛弃疾', '西风都是行人恨。\n马头渐喜归期近。\n试上小红楼。\n飞鸿字字愁。\n阑干闲倚处。\n一带山无数。\n不似远山横。\n秋波相共明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11560, '菩萨蛮', '辛弃疾', '功名饱听儿童说。\n看公两眼明如月。\n万里勒燕然。\n老人书一编。\n玉阶方寸地。\n好趁风云会。\n他日赤松游。\n依然万户侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11561, '菩萨蛮', '辛弃疾', '送君直上金銮殿。\n情知不久须相见。\n一日甚三秋。\n愁来不自由。\n九重天一笑。\n定是留中了。\n白发少经过。\n此时愁奈何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11562, '菩萨蛮', '辛弃疾', '人间岁月堂堂去。\n劝君快上青云路。\n圣处一灯传。\n工夫萤雪边。\n曲生风味恶。\n辜负西窗约。\n沙岸片帆开。\n寄书无雁来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11563, '菩萨蛮', '辛弃疾', '红牙签上群仙格。\n翠罗盖底倾城色。\n和雨泪阑干。\n沈香亭北看。\n东风休放去。\n怕有流莺诉。\n试问赏花人。\n晓妆匀未匀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11564, '菩萨蛮', '辛弃疾', '君家玉雪花如屋。\n未应山下成三宿。\n啼鸟几曾催。\n西风犹未来。\n山房连石径。\n云卧衣裳冷。\n倩得李延年。\n清歌送上天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11565, '卜算子', '辛弃疾', '万里浮云，一喷空凡马。\n叹息曹瞒老骥诗，伏枥如公者。\n山鸟窥檐，野鼠饥翻瓦。\n老我痴顽合住山，此地菟裘也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11566, '丑奴儿・采桑子', '辛弃疾', '晚来云淡秋光薄，落日晴天。\n落日晴天。\n堂上风斜画烛烟。\n从渠去买人间恨，字字都圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11567, '丑奴儿・采桑子', '辛弃疾', '寻常中酒扶头後，歌舞支持。\n歌舞支持。\n谁把新词唤住伊。\n临歧也有旁人笑，笑己争知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11568, '丑奴儿・采桑子', '辛弃疾', '此生自断天休问，独倚危楼。\n独倚危楼。\n不信人间别有愁。\n君来正是眠时节，君且归休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11569, '丑奴儿・采桑子', '辛弃疾', '近来愁似天来大，谁解相怜。\n谁解相怜。\n又把愁来做个天。\n都将今古无穷事，放在愁边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11570, '丑奴儿・采桑子', '辛弃疾', '年年索尽梅花笑，疏影黄昏。\n疏影黄昏。\n香满东风月一痕。\n清诗冷落无人寄，雪艳冰魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11571, '浣溪沙', '辛弃疾', '寿酒同斟喜有馀。\n朱颜却对白髭须。\n两人百岁恰乘除。\n婚嫁剩添儿女拜，平安频拆外家书。\n年年堂上寿星图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11572, '浣溪沙', '辛弃疾', '歌串如珠个个匀。\n被花勾引笑和颦。\n向来惊动画梁尘。\n莫倚笙歌多乐事，相看红紫又抛人。\n旧巢还有燕泥新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11573, '浣溪沙', '辛弃疾', '父老争言雨水匀。\n眉头不似去年颦。\n殷勤谢却甑中尘。\n啼鸟有时能劝客，小桃无赖已撩人。\n梨花也作白头新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11574, '浣溪沙', '辛弃疾', '这里裁诗话别离。\n那边应是望归期。\n人言心急马行迟。\n去雁无凭传锦字，春泥抵死污人衣。\n海棠过了有荼シ。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11575, '浣溪沙', '辛弃疾', '妙手都无斧凿瘢。\n饱参佳处却成颦。\n恰如春入浣花村。\n笔墨今宵光有艳，管弦从此悄无言。\n主人席次两眉轩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11576, '添字浣溪沙・山花子', '辛弃疾', '句里明珠字字排。\n多情应也被春催。\n怪得名花和泪送，雨中栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11577, '添字浣溪沙・山花子', '辛弃疾', '记得瓢泉快活时。\n长年耽酒更吟诗。\n蓦地捉将来断送，老头皮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11578, '添字浣溪沙・山花子', '辛弃疾', '日日闲看燕子飞。\n旧巢新垒画帘低。\n玉历今朝推戊己，住衔泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11579, '添字浣溪沙・山花子', '辛弃疾', '杨柳温柔是故乡。\n纷纷蜂蝶去年场。\n大率一春风雨事，最难量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11580, '减字木兰花', '辛弃疾', '僧窗夜雨。\n茶鼎熏炉宜小住。\n却恨春风。\n勾引诗来恼杀翁。\n狂歌未可。\n且把一尊料理我。\n我到亡何。\n却听侬家陌上歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11581, '减字木兰花', '辛弃疾', '昨朝官告。\n一百五年村父老。\n更莫惊疑。\n刚道人生七十稀。\n使君喜见。\n恰限华堂开寿宴。\n问寿如何。\n百代儿孙拥太婆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11582, '醉太平', '辛弃疾', '态浓意远。\n眉颦笑浅。\n薄罗衣窄絮风软。\n鬓云欺翠卷。\n南园花树春光暖。\n红香径里榆钱满。\n欲上秋千又惊懒。\n且归休怕晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11583, '太常引', '辛弃疾', '仙机似欲织纤罗。\n仿佛度金梭。\n无奈玉纤何。\n却弹作、清商恨多。\n珠帘影里，如花半面，绝胜隔帘歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11584, '太常引', '辛弃疾', '论公耆德旧宗英。\n吴季子、百馀龄。\n奉使老於行。\n更看舞、听歌最精。\n须同卫武，九十入相，绿竹自青青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11585, '东坡引', '辛弃疾', '君如梁上燕。\n妾如手中扇。\n团团青影双双伴。\n秋来肠欲断。\n黄昏泪眼。\n秋来肠欲断。\n青山隔岸。\n但咫尺、如天远。\n病来只谢傍人劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11586, '东坡引', '辛弃疾', '花梢红未足。\n条破惊新绿。\n重帘下遍阑干曲。\n有人春睡熟。\n有人春睡熟。\n鸣禽破梦，云偏目蹙。\n起来香腮褪红玉。\n花时爱与愁相续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11587, '恋绣衾', '辛弃疾', '长夜偏冷添被儿。\n枕头儿、移了又移。\n我自是笑别人底，却元来、当局者迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11588, '杏花天', '辛弃疾', '牡丹昨夜方开遍。\n毕竟是、今年春晚。\n荼シ付与薰风管。\n燕子忙时莺懒。\n多病起、日长人倦。\n不待得、酒阑歌散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11589, '柳梢青', '辛弃疾', '白鸟相迎，相怜相笑，满面尘埃。\n华发苍颜，去时曾劝，闻早归来。\n而今岂是高怀。\n为千里、莼羹计哉。\n好把移文，从今日日，读取千回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11590, '武陵春', '辛弃疾', '走去走来三百里，五日以为期。\n六日归时已是疑。\n应是望多时。\n鞭个马儿归去也，心急马行迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11591, '谒金门', '辛弃疾', '归去未。\n风雨送春行李。\n一枕离愁头澈尾。\n如何消遣是。\n遥想归舟天际。\n绿鬓珑璁慵理。\n好梦未成莺唤起。\n粉香犹有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11592, '酒泉子', '辛弃疾', '流水无情，潮到空城头尽白，离歌一曲怨残阳。\n断人肠。\n东风官柳舞雕墙。\n三十六宫花溅泪，春声何处说兴亡。\n燕双双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11593, '霜天晓角', '辛弃疾', '暮山层碧。\n掠岸西风急。\n一叶软红深处，应不是、利名客。\n玉人还伫立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11594, '点绛唇', '辛弃疾', '隐隐轻雷，雨声不受春回护。\n落梅如许。\n吹尽墙边去。\n春水无情，碍断溪南路。\n凭谁诉。\n寄声传语。\n没个人知处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11595, '生查子', '辛弃疾', '梅子褪花时，直与黄梅接。\n烟雨几曾开，一春江里活。\n富贵使人忙，也有闲时节。\n莫作路旁花，长教人看杀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11596, '生查子', '辛弃疾', '悠悠万世功，当年苦。\n鱼自入深渊，人自居平土。\n红日又西沉，白浪长东去。\n不是望金山，我自思量禹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11597, '昭君怨', '辛弃疾', '夜雨剪残春韭。\n明日重斟别酒。\n君去问曹瞒。\n好公安。\n试看如今白发。\n却为中年离别。\n风雨正崔嵬。\n早归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11598, '一落索', '辛弃疾', '锦帐如云处。\n高不知重数。\n夜深银烛泪成行，算都把、心期付。\n莫待燕飞泥污。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11599, '如梦令', '辛弃疾', '燕子几曾归去。\n只在翠岩深处。\n重到画梁间，谁与旧巢为主。\n深许。\n深许。\n闻道凤凰来住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11600, '生查子', '辛弃疾', '一天霜月明，几处砧声起。\n客梦已难成，秋色无边际。\n旦夕是重阳，菊有黄花蕊。\n只怕又登高，未饮心先醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11601, '满江红', '辛弃疾', '老子当年，饱经惯、花期酒约。\n行乐处，轻裘缓带，绣鞍金络。\n明月楼台箫鼓夜，梨花院落秋千索。\n共何人、对饮五三锺，颜如玉。\n嗟往事，空萧索。\n怀新恨，又飘泊。\n但年来何待，许多幽独。\n海水连天凝望远，山风吹雨征衫薄。\n向此际、羸马独，情怀恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11602, '菩萨蛮', '辛弃疾', '与君欲赴西楼约。\n西楼风急征衫薄。\n且莫上兰舟。\n怕人青泪流。\n临风横玉管。\n声散江天满。\n一夜旅中愁。\n蛩吟不忍休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11603, '一翦梅', '辛弃疾', '尘洒衣裾客路长。\n霜林已晚，秋蕊犹香。\n别离触处是悲凉。\n梦里青楼，不忍思量。\n天字沈沈落日黄。\n云遮望眼，山割愁肠。\n满怀珠玉泪浪浪。\n欲倩西风，吹到兰房。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11604, '一翦梅', '辛弃疾', '歌罢尊空月坠西。\n百花门外，烟翠霏微。\n降纱笼烛照于飞。\n归去来兮。\n归去来兮。\n酒入香腮分外宜。\n行行问道，还肯相随。\n娇羞无力应人迟。\n何幸如之。\n何幸如之。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11605, '念奴娇', '辛弃疾', '西真姊妹，料凡心忽起，共辞瑶阙。\n燕燕莺莺相并比，的当两团儿雪。\n合韵歌喉，同茵舞袖，举措□□别。\n江梅影里，迥然双蕊奇绝。\n还听别院笙歌，仓皇走报，笑语浑重叠。\n拾翠洲边携手处，疑是桃根桃叶。\n并蒂芳莲，双头红药，不意俱攀折。\n今宵鸳帐，有同对影明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11606, '念奴娇', '辛弃疾', '论心论相，便择术满眼，纷纷何物。\n踏碎铁鞋三百，不在危峰绝壁。\n龙友相逢，洼樽缓举，议论敲冰雪。\n何妨人道，圣时同见三杰。\n自是不日同舟，平戎破虏，岂由言轻发。\n任使穷通相鼓弄，恐是真□难灭。\n寄食王孙，丧家公子，谁握周公发。\n冰□皎皎，照人不下霜月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11607, '念奴娇', '辛弃疾', '妙龄秀发，湛灵台一点，天然奇绝。\n万壑千岩归健笔，扫尽平山风月。\n雪里疏梅，霜头寒菊，迥与馀花别。\n识人青眼，慨然怜我疏拙。\n遐想後日娥眉，两山横黛，谈笑风生颊。\n握手论文情极处，冰玉一时清洁。\n扫断尘劳，招呼萧散，满酌金蕉叶。\n醉乡深处，不知天地空阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11608, '江城子', '辛弃疾', '留仙初试砑罗裙。\n小腰身。\n可怜人。\n江国幽香，曾向雪中闻。\n过尽东园桃与李，还见此，一枝春。\n庾郎襟度最清真。\n挹芳尘。\n便情亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11609, '惜奴娇', '辛弃疾', '风骨萧然，称独立、群仙首。\n春江雪、一枝梅秀。\n小样香檀，映朗玉、纤纤手。\n未久。\n转新声、泠泠山溜。\n曲里传情，更浓似、尊中酒。\n信倾盖、相逢如旧。\n别後相思，记敏政堂前柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11610, '眼儿媚', '辛弃疾', '烟花丛里不宜他。\n绝似好人家。\n淡妆娇面，轻注朱唇，一朵梅花。\n相逢比著年时节，顾意又争些。\n来朝去也，莫因别个，忘了人咱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11611, '如梦令', '辛弃疾', '韵胜仙风缥缈。\n的娇波宜笑。\n串玉一声歌，占断多情风调。\n清妙。\n清妙。\n留住飞云多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11612, '鹧鸪天', '辛弃疾', '翦烛西窗夜未阑。\n酒豪诗兴两联绵。\n香喷瑞兽金三尺，人插云梳玉一弯。\n倾笑语，捷飞泉。\n觥筹到手莫留连。\n明朝再作东阳约，肯把鸾胶续断弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11613, '踏莎行', '辛弃疾', '萱草齐阶，芭蕉弄叶。\n乱红点点团香蝶。\n过墙一阵海棠风，隔帘几处梨花雪。\n愁满芳心，酒潮红颊。\n年年此际伤离别。\n不妨横管小楼中，夜阑吹断千山月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11614, '□□□', '辛弃疾', '莺未老。\n花谢东风扫。\n秋千人倦彩绳闲，又被清明过了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11615, '谒金门', '辛弃疾', '山共水。\n美满一千馀里。\n不避晓行并早起。\n此情都为你。\n不怕与人尤。\n只怕被人调戏。\n因甚无个阿鹊地。\n没工夫说里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11616, '好事近', '辛弃疾', '春动酒旗风，野店芳醪留客。\n系马水边幽寺，有梨花如雪。\n山僧欲看醉魂醒，茗碗泛香白。\n微记碧苔归路，袅一鞭春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11617, '好事近', '辛弃疾', '花月赏心天，抬举多情诗客。\n取次锦袍须贳，爱春醅浮雪。\n黄鹂何处故飞来，点破野雪白。\n一点暗红犹在，正不禁风色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11618, '好事近', '辛弃疾', '春意满西湖，湖上柳黄时节。\n濒水雾窗云户，贮楚宫人物。\n一年管领好花枝，东风共披拂。\n已约醉骑双凰，玩三山风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11619, '水调歌头', '辛弃疾', '客子久不到，好景为君留。\n西楼著意吟赏，何必问更筹。\n唤起一天明月，照我满怀冰雪，浩荡百川流。\n鲸饮未吞海，剑气已横秋。\n野光浮。\n天宇迥，物华幽。\n中州遗恨，不知今夜几人愁。\n谁念英雄老矣，不道功名蕞尔，决策尚悠悠。\n此事费分说，来日且扶头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11620, '水调歌头', '辛弃疾', '泰岳倚空碧，汶□卷云寒。\n萃兹山水奇秀，列宿下人寰。\n八世家传素业，一举手攀丹桂，依约笑谈间。\n宾幕佐储副，和气满长安。\n分虎符，来近甸，自金銮。\n政平讼简无事，酒社与诗坛。\n会看沙堤归去，应使神京再复，款曲问家山。\n玉佩揖空阔，碧雾翳苍鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11621, '贺新郎', '辛弃疾', '世路风波恶。\n喜清时、边夫袖手，□将帷幄。\n正值春光二三月，两两燕穿帘幕。\n又怕个、江南花落。\n与客携壶连夜饮，任蟾光、飞上阑干角。\n何时唱，从军乐。\n归欤已赋居岩壑。\n悟人世、正类春蚕，自相缠缚。\n眼畔昏鸦千万点，□欠归来野鹤。\n都不恋、黑头黄阁。\n一咏一觞成底事，庆康宁、天赋何须药。\n金盏大，为君酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11622, '渔家傲', '辛弃疾', '风月小斋模画舫。\n绿窗朱户江湖样。\n酒是短桡歌是桨。\n和情放。\n醉乡稳到无风浪。\n自有拍浮千斛酿。\n从教日日蒲桃涨。\n门外独醒人也访。\n同俯仰。\n赏心却在鸱夷上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11623, '霜天晓角', '辛弃疾', '雪堂迁客。\n不得文章力。\n赋写曹刘兴废，千古事、泯陈迹。\n望中矶岸赤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11624, '苏武慢', '辛弃疾', '帐暖金丝，杯乾云液，战退夜□。\n障泥系马，扫路迎宾，先借落花春色。\n歌竹传觞，探梅得句，人在玉楼琼室。\n唤吴姬学舞，风流轻转，弄娇无力。\n尘世换、老尽青山，铺成明月，瑞物已深三尺。\n丰登意绪，婉娩光阴，都作暮寒堆积。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11625, '绿头鸭・多丽', '辛弃疾', '叹飘零。\n离多会少堪惊。\n又争如、天人有信，不同浮世难凭。\n占秋初、桂花散采，向夜久、银汉无声。\n凤驾催云，红帷卷月，泠泠一水会双星。\n素杼冷，临风休织，深诉隔年诚。\n飞光浅，青童语款，丹鹊桥平。\n看人间、争求新巧，纷纷女伴欢迎。\n避灯时、彩丝未整，拜月处、蛛网先成。\n谁念监州，萧条官舍，烛摇秋扇坐中庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11626, '乌夜啼', '辛弃疾', '江头三月清明。\n柳风轻。\n巴峡谁知还是、洛阳城。\n春寂寂。\n娇滴滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11627, '品令', '辛弃疾', '迢迢征路。\n又小舸、金陵去。\n西风黄叶，淡烟衰草，平沙将暮。\n回首高城，一步远如一步。\n江边朱户。\n忍追忆、分携处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11628, '好事近', '辛弃疾', '医者索酬劳，那得许多钱物。\n只有一个整整，也盒盘盛得。\n下官歌舞转凄惶，剩得几枝笛。\n觑著这般火色，告妈妈将息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11629, '金菊对芙蓉', '辛弃疾', '远水生光，遥山耸翠，霁烟深锁梧桐。\n正零玉露，淡荡金风。\n东篱菊有黄花吐，对映水、几簇芙蓉。\n重阳佳致，可堪此景，酒酽花浓。\n追念景物无穷。\n叹少年胸襟，忒煞英雄。\n把黄英红萼，甚物堪同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11630, '贺新郎', '辛弃疾', '瑞气笼清晓。\n卷珠帘、次第笙歌，一时齐奏。\n无限神仙离蓬岛。\n凤驾鸾车初到。\n见拥个、仙娥窈窕。\n玉佩玎裆风缥缈。\n望娇姿、一似垂杨袅。\n天上有，世间少。\n刘郎正是当年少。\n更那堪、天教付与，最多才貌。\n玉树琼枝相映耀。\n谁与安排忒好。\n有多少、风流欢笑。\n直待来春成名了。\n马如龙、绿绶欺芳草。\n同富贵，又偕老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11631, '好事近', '辛弃疾', '日日过西湖，冷浸一天寒玉。\n山色虽言如画，想画时难邈。\n前弦後管夹歌锺，才断又重续。\n相次藕花开也，几兰舟飞逐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11632, '生查子', '辛弃疾', '百花头上开，冰雪寒中见。\n霜月定相知，先识春风面。\n主人情意深，不管江妃怨。\n折我最繁枝，还许冰壶荐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11633, '传言玉女', '赵善扛', '璧月珠星，辉映小桃李。\n化工容易，与人间富贵。\n东风巷陌，春在暖红温翠。\n人来人去，笑歌声里。\n油壁青骢，第一番共燕喜。\n举头天上，有如人意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11634, '好事近', '赵善扛', '风动一川花，摇漾影迷红碧。\n人立杏花阴下，泛光风袭袭。\n琼枝碧月互相辉，春容泫将夕。\n罗盖暗承花雾，渍鲛绡香湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11635, '重叠金・菩萨蛮', '赵善扛', '楚宫杨柳依依碧。\n遥山翠隐横波溢。\n绝艳照春。\n春光欲醉人。\n纤纤芳草嫩。\n微步轻罗衬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11636, '重叠金・菩萨蛮', '赵善扛', '玉关芳草黏天碧。\n春风万里思行客。\n骑马向风嘶。\n道归犹未归。\n南云新有雁。\n望眼愁边断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11637, '重叠金・菩萨蛮', '赵善扛', '一川花月青春夜。\n玉容依约花阴下。\n月照曲阑干。\n红绡挹露寒。\n袖香温素手。\n意铄金卮酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11638, '十拍子・破阵子', '赵善扛', '柳絮飞时绿暗，荼シ开後春酣。\n花外青帘迷酒思，陌上晴光收翠岚。\n佳辰三月三。\n解人逢游女，踏青草斗宜男。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11639, '青玉案', '赵善扛', '一年陌上寻芳意。\n想人在、东风里。\n褪粉销红春有几。\n青翰飞去，紫云凝伫，往事如流水。\n烟横极浦山无际。\n暗解明问谁寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11640, '烛影摇红', '赵善扛', '桃李墙头，向人都似他年意。\n舞丝千丈晴光，骀青春无际。\n花气薰人自醉。\n傍垂杨、行行缓辔。\n倦游无奈，回首云山，归期犹未。\n玉锁楼空，鸟啼花外东风起。\n少年恩怨付波流，吟望朱阑倚。\n冉冉尘生客袂。\n对尊前、高情暂寄。\n洞天一笑，仙驭乘空，姑峰凝翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11641, '谒金门', '赵善扛', '新雨霁。\n开遍满园桃李。\n波暖池塘风细细。\n一双花鸭戏。\n唤起春融睡美。\n扶醉宿妆慵理。\n移步避入花影里。\n绣裙低地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11642, '宴清都', '赵善扛', '疏柳无情绪。\n都不管、渡头行客欲去。\n犹依赖得，玉光万顷，为人留住。\n相从岁月如骛，叹回首、离歌又赋。\n更举目、斜照沈沈，西风剪剪秋墅。\n君行定忆南池，歌筵舞地，花晨月午。\n八砖步日，三雍奏乐，送君云路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11643, '小重山', '赵善扛', '汲水添瓶恰换花。\n蜂儿争要采，打窗纱。\n青春谁与度年花。\n弦索暗，无绪几曾拿。\n春思正交加。\n马蹄声错认，客还家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11644, '感皇恩', '赵善扛', '七十古来稀，吾生已半。\n莫把身心自萦绊。\n据他缘分，且恁随时消遣。\n但知逢酒饮，逢花看。\n林泉有约，风光无限。\n日上花梢起来晚。\n芒鞋竹杖，信步水村山馆。\n更寻三两个，清闲伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11645, '贺新郎', '赵善扛', '昼永重帘卷。\n乍池塘、一番过雨，芰荷初展。\n竹引新梢半含粉，绿荫扶疏满院。\n过花絮、蝶稀蜂懒。\n窗户沈沈人不到，伴清幽、时有流莺啭。\n凝思久，意何限。\n玉钗坠枕风鬟颤。\n湛虚堂、壶冰莹彻，簟波零乱。\n自是仙姿清无暑，月影空垂素扇。\n破午睡、香销馀篆。\n一枕湖山千里梦，正白苹烟棹归来晚。\n云弄碧，楚天远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11646, '喜迁莺', '赵善扛', '韶华骀荡。\n看化工尽力，安排春仗。\n薄雾霏烟，软风轻日，物态与人交畅。\n鸟生弄巧千调，楼影垂空十丈。\n乱花柳，粲宝钿缨络、采丝帷帐。\n佳赏。\n辉艳冶，笑语盈盈，花面交相向。\n歌运长缫，酒凝深碧，和气盎然席上。\n好春易苦风雨，人意难逢舒放。\n但拍掌。\n醉陶然一笑，忘形天壤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11647, '菩萨蛮', '赵善括', '烟波江上西亭小。\n晓来雨过惊秋早。\n飞栋倚晴空。\n凉生面面风。\n痴儿官事了。\n独自凭栏笑。\n何处有尘埃。\n扁舟归去来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11648, '柳梢青', '赵善括', '愁别欣逢。\n人间离合，自古难同。\n写就茶经，注成花谱，何事西东。\n一尊良夜匆匆。\n怎忍见、轻帆短篷。\n汉水无情，楚云有意，目断飞鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11649, '鹧鸪天', '赵善括', '忆昔南楼旧使君。\n与君携手蹑浮云。\n如今更到经行处，妙墨新诗得屡闻。\n淮南路，楚江分。\n离尊相属更论文。\n明朝一棹人千里，多少红愁与翠颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11650, '鹧鸪天', '赵善括', '我是行人更送行。\n潇潇风雨倍伤情。\n征帆西去何须急，飞诏东来分外荣。\n红袖湿，玉尊倾。\n不堪回首暮云平。\n小舟准拟随君去，要听霜天晓角声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11651, '鹧鸪天', '赵善括', '雨沐芙蓉秋意清。\n可人风月满江城。\n怜风爱月方留恋，对月临风又送行。\n人渐远，酒须倾。\n只凭一醉遣多情。\n重来休厌刘郎老，明月清风有素盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11652, '沁园春', '赵善括', '虎啸风生，龙跃云飞，时不再来。\n试凭高望远，长淮清浅，伤今怀古，故国氛埃。\n壮志求伸，匈奴未灭，早以家为何谓哉。\n多应是，待著鞭事了，税驾方回。\n稼轩聊尔名斋。\n笑学请樊迟心未开。\n似南阳高卧，莘郊自乐，溪韬略，傅野盐梅。\n植杖亭前，集山楼下，五桂三槐次第栽。\n功名遂，向急流勇退，肯恁徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11653, '沁园春', '赵善括', '问舍东湖，招隐西山，惠然肯来。\n有香兰桂，无穷幽趣，隔溪车马，何处轻埃。\n微利虚名，朝荣暮辱，笑尔焉能浼我哉。\n闲欹枕，被幽禽唤觉，午梦惊回。\n无言独坐南斋。\n好唤取芳尊相对开。\n待醒时重醉，疏帘透月，醉时还醒，画角吹梅。\n无用千金，休悬六印，荆棘谁能满地栽。\n人间世，任游独运，斥低徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11654, '沁园春', '赵善括', '千里风湍，万叠云峰，自相送迎。\n叹扁舟如叶，漂流如梗，片帆如箭，聚散如萍。\n家在东湖，身来西浙，非为区区利与名。\n堪怜处，为雏饥犊暮，狗苟蝇营。\n平生。\n何辱何荣。\n且一任三才和五行。\n有飞鹏奋，鹤长凫短，朱颜富贵，白发公卿。\n印漫累累，绶何若若，休羡行歌朱买臣。\n归来好，向严滩垂钓，谷口躬耕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11655, '满江红', '赵善括', '一雨连春，东湖涨、蒲萄新绿。\n湖上路，柳浓花艳，绿园红簇。\n尘世难逢开口笑，人生待足何时足。\n况南州高士是西邻，人如玉。\n行路唱，谁家曲。\n愁易感，欢难续。\n问轩裳於我，有何荣辱。\n众醉岂容君独醒，出林休恨风催木。\n叹惊弦、飞鸟尚知还，安巢宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11656, '满江红', '赵善括', '三十年前，曾向此、舞风歌月。\n今依旧、江山如画，鬓须如雪。\n故友冥鸿随净社，旧时秋蚓横尘壁。\n赖庐峰、对我眼偏青，曾相识。\n开岫幌，携山屐。\n泉泻布，星飞石。\n为收帆舣棹，小留终日。\n休问重湖吹碧浪，且同五老浮琼液。\n待明朝、首向东飞，清风力。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11657, '满江红', '赵善括', '腾茂飞英，分忧愿、自然风力。\n千里静，江山改观，羽旄增色。\n林下风清公事少，笔端雷动奸豪息。\n听宴香、深处笑声长，文章客。\n丹诏自，天边得。\n宣室对，君心忆。\n趁良辰高会，履珠簪碧。\n和气回春徵酝酿，政声报最惟清白。\n看挥毫、万字扫云烟，吴笺湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11658, '鹧鸪天', '赵善括', '画翩翩去似飞。\n季鹰何事忽思归。\n风湍自送征帆隐，云须将彩笔挥。\n江作酒，海为卮。\n为君满酌不须辞。\n酒酣渴思回春梦，自笑何时是足时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11659, '念奴娇', '赵善括', '扬辉璧月，照层台缥缈，篷莱云气。\n玉宇清明仙语近，多少怨红愁翠。\n问我殷勤，几年尘土，依旧高标致。\n广寒别後，与谁曾共幽会。\n一日失脚人间，十常八九，底事如人意。\n狗苟蝇营真可笑，何乃比余於是。\n风月佳时，江山好处，无复怀愁悴。\n倚栏舒啸，六经时自心醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11660, '醉落魄・一斛珠', '赵善括', '重阳时节。\n可怜又是天崖客。\n扁舟小泊花溪侧。\n细雨斜风，不见秦楼月。\n白衣望断无消息。\n举觞一笑真难得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11661, '摸鱼儿', '赵善括', '喜连宵、四郊春雨。\n纷纷一阵红去。\n东君不爱闲桃李，春色尚馀分数。\n云影住。\n任绣勒香轮，且阻寻芳路。\n农家相语。\n渐南亩浮青，西江涨绿，芳沼点萍絮。\n西成事，端的今年不误。\n从他蝶恨蜂妒。\n莺啼也怨春多雨，不解与春分诉。\n新燕舞。\n犹记得、雕梁旧日空巢土。\n天涯劳苦。\n望故国江山，东风吹泪，渺渺在何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11662, '摸鱼儿', '赵善括', '被杨花、带将春去，飘扬一路无定。\n满庭绿荫丝千尺，枝上旧香吹尽。\n幽梦醒。\n对晚色、秋千院落人初静。\n柔条弄影。\n奈翦翦轻风，冥冥细雨，惹起万千恨。\n云山路，休蹑高楼独凭。\n楚天一抹烟暝。\n娇莺百啭飞鸠去，何处可寻芳信。\n心自省。\n念咫尺、青楼应怪人薄幸。\n归期将近。\n料喜鹊先知，飞来报了，日日倚门等。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11663, '虞美人', '赵善括', '长空一夜霜风吼。\n寒色消残酒。\n问伊今夜在谁行。\n遗恨落花流水、误刘郎。\n尤云雨多情话。\n分付阿谁也。\n侬家有分受凄惶。\n只怕娇痴不睡、也思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11664, '好事近', '赵善括', '月色透窗寒，一夜素衾霜湿。\n无寐起来搔首，正参横人寂。\n此心重省已回肠，何况是行役。\n欲弃利名归去，奈楚天云隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11665, '鹧鸪天', '赵善括', '枉道黉堂是冷官。\n深深青琐锁青鸾。\n新诗自得清歌举，和气都消永夜寒。\n花态净，酒杯宽。\n燕娇莺巧有馀欢。\n不因客里东阳瘦，好把西江一吸乾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11666, '满江红', '赵善括', '传语风光，须少驻、共君流转。\n谁忍见、绿肥红瘦，鲜欢多感。\n泽国千丝烟雨暗，江成一带云山远。\n看新荷、泛水学人愁，心常卷。\n羞鬓雪，凭花染。\n携酒阵，嫌杯浅。\n叹人生岂为，青衫槐板。\n记舞可怜宫柳细，写情但觉香笺短。\n上层楼、独倚有谁知，栏干暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11667, '水调歌头', '赵善括', '山险号北固，景胜冠南州。\n洪涛江上乱云，山里簇红楼。\n堪笑萍踪无定，拟泊叶舟何许，无计可依刘。\n金阙自帷幄，玉垒老貔貅。\n问兴亡，成底事，几春秋。\n六朝人物，五胡妖雾不胜愁。\n休学楚囚垂泪，须把祖鞭先著，一鼓版图收。\n惟有金焦石，不逐水漂流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11668, '好事近', '赵善括', '风雨做春愁，桃杏一时零落。\n是处绿肥红瘦，怨东君情薄。\n行藏独倚望江楼，双燕度帘幕。\n回首故园应在，误秋千人约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11669, '鹧鸪天', '赵善括', '玉殿分荣两桂华。\n灵根移植在长沙。\n风姨先绽无双蕊，月姊重开第一花。\n金榜烂，玉音加。\n从今稳步上天霞。\n休夸水击三千里，且歌笙歌十万家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11670, '醉落魄・一斛珠', '赵善括', '梯横画阁。\n碧栏干外江风恶。\n笑声欢意浮杯酌。\n秋水春山，相对称行乐。\n谁家青鸟穿帘幕。\n暗传空有阳台约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11671, '醉落魄・一斛珠', '赵善括', '梯横画阁。\n月明江静烟光薄。\n碧山回绕栏干角。\n一缕行云，忽向杯中落。\n樱歌柳舞俱柔弱。\n罗衣不耐江风恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11672, '朝中措', '赵善括', '东君著意在枝头。\n红紫自风流。\n贪引游蜂舞蝶，几多春事都休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11673, '菩萨蛮', '赵善括', '鹊桥巧雾随风远。\n蟾宫皓影凝空满。\n一点寿星明。\n祥光彻太清。\n周公天子传。\n礼乐新封鲁。\n功业焕旗常。\n钧天侍玉皇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11674, '水调歌头', '赵善括', '形胜视京兆，警跸驻钱塘。\n光前诏後弹压，谁数汉张王。\n几百万家和气，五十馀年创见，天下一循良。\n有口皆歌颂，无地不耕桑。\n春过半，花锦烂，柳丝长。\n潭潭门卫森戟，宴寝正凝香。\n笑把湖山佳色，醉挹西湖晴滟，童艾祝霞觞。\n四海瞻华衮，千载侍吾皇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11675, '满江红', '赵善括', '海岳储祥，符昌运、挺生前哲。\n天赋与、飘然才气，凛然忠节。\n颖脱难藏冲斗剑，誓清行击中流楫。\n二十年、麾节遍江湖，恩威浃。\n香穗直，云峰列。\n觞羽急，鲸川竭。\n共介公眉寿，赞公贤业。\n出处已能齐二老，功名岂止超三杰。\n侍吾皇、千载带金重，头方黑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11676, '醉蓬莱', '赵善括', '正采铃坠盖，玉燕投怀，梦符佳月。\n五百年间，诞中兴人杰。\n杖策归来，入关徒步，万里朝金阙。\n贯日精忠，凌云壮气，妙龄英发。\n名镇重湖，屡凭熊轼，恩满西江，载分龙节。\n有志澄清，誓击中流楫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11677, '醉蓬莱', '赵善括', '正百花堂下，山雨楼前，粲然梅柳。\n和气回春，滟一尊芳酒。\n桂子兰孙，凤歌鸾舞，介我公眉寿。\n天上遐龄，人间独乐，古来稀有。\n壮日题桥，儿时击瓮，名遂功成，自然长久。\n琳馆偷闲，约赤城为友。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11678, '醉蓬莱', '赵善括', '正槐堂日永，梅雨消尘，麦风摇翠。\n天昌辰，诞中兴嘉瑞。\n秀伟标姿，从容谋断，笑吐平戎计。\n汉节归来，边尘扫净，鼎司荣贵。\n间世良臣，威严辅政，妩媚承君，道襟冲粹。\n玉券金丹，称功名成遂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11679, '瑞鹤仙', '赵善括', '月华凝露掌。\n正极目鸾霄，望风鲸壤。\n深宫注遐想。\n听点点花漏，盈盈仙仗。\n笙箫迎响。\n降琼轮、玄云步障。\n洞□扉、笑别蓬瀛，下应太平无象。\n俱仰。\n姆仪春煦，妇节冰清，道风夷旷。\n三迁教养。\n金阙里，玉音赏。\n况传家清白，满堂朱紫，相对兰荪竞长。\n待齐秦、汤沐疏封，赐灵寿杖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11680, '鹊桥仙', '赵善括', '星桥未就，月钩初挂，翠叶暗惊秋早。\n蕊珠宫里厌清闲，试回首、尘寰一笑。\n仙风道骨，姆仪家范，须信人间最少。\n一枝丹桂四兰荪，况千岁、灵椿未老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11681, '贺新郎', '赵善括', '绛雪堆云绿。\n倚朱栏、鸾飞凤舞，乱红如簇。\n宫锦海沈肌理秀，极目明霞孤骛。\n对翠袖、天寒修竹。\n轻露有情添泪眼，粲精神、娇醉薰华屋。\n然宝篆，散清馥。\n江南到处多兰菊。\n更海棠、贪睡未醒，漫山粗俗。\n欲品此花为第一，真色生香俱足。\n又只怕、惊人凡目。\n把酒对花频管领，怕狂风骤雨难拘束。\n拾碎玉，泛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11682, '霜天晓角', '赵善括', '楚天风色。\n一夜波翻雪。\n舣岸锦帆不度，天有意、且留客。\n鼓声吹取急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11683, '水调歌头', '赵善括', '碧云初返岫，潦水正鸣滩。\n兰舟容与，歌舞偏称笑中看。\n烛影烘寒成暖，花色照人如画，一坐有馀欢。\n酒滟浮金盏，香缕霭雕盘。\n碧簪横，银漏永，玉樽乾。\n喧春鼓吹，翠袖起舞佩珊珊。\n记得山明水秀，何处朝云暮雨，常在梦魂间。\n多少难言事，都付两眉弯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11684, '念奴娇', '赵善括', '晓来膏雨，报一犁丰信，几枝娇色。\n岸草河沙明似镜，不到尘埃花陌。\n急管繁弦，香车宝勒，正阻寻春客。\n东风特起，半空微露晴碧。\n何况主意深勤，冰清才藻，玉润真圭璧。\n翠丽华堂横枕水，波底斜阳红湿。\n莲社风流，桃溪标致，便觉凡心息。\n玉尊倾尽，笑中归步钩月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11685, '念奴娇', '赵善括', '江南到处，被波光云影，留人行色。\n昔我来时春正好，舞絮□飞南陌。\n今日登临，读书斋上，重作凭栏客。\n清溪毂细，夜来微涨新碧。\n两岸蘸水浓阴，断虹横障，一带连环璧。\n林外青山千万叠，雨歇半空犹湿。\n已倩双鳞，更须灵鹊，先报归消息。\n归来征袖，尽携千里风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11686, '鹊桥仙', '赵善括', '花腮百媚，柳丝千尺，密影金铺碎日。\n过云微雨报清明，半天外、烟娇雾湿。\n当歌有恨，问春无语，笑我如何久客。\n小园归去又残红，便□地、飞觞尚得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11687, '鹊桥仙', '赵善括', '东风唤我，西园闲坐，大醉高歌竟日。\n行藏独依画栏干，便忘了、征衫泪湿。\n亭高烟远，天低云近，相对逃名隐客。\n掀髯无语看青山，断不信、尘埃到得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11688, '清平乐', '赵善括', '断云漏雨。\n依约西山暮。\n风定樯高须小住。\n不忍带将春去。\n此行抑有求欤。\n青衣拟问平都。\n万里一钩新月，相忘常在江湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11689, '水调歌头', '赵善括', '危台枕城堞，今昔几人游。\n绕城碧水一带，茂苑与长洲。\n寂寂弹琴风外，苒苒采香径畔，横截古溪头。\n极目暮云合，宋玉正悲秋。\n岘山碑，帝子阁，庾公楼。\n当时风物，如今烟水只供愁。\n处处山明水秀，岁岁春花秋月，何必美南州。\n故国未归去，萍梗叹漂流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11690, '水调歌头', '赵善括', '雨霁彩虹卧，半夜水明楼。\n太湖极目，四面水尽是天流。\n几点鲈乡荻浦，万里鲸波雪浪，掀舞小渔舟。\n金饼挂蟾魄，时景正中秋。\n钓纶轻，兰棹稳，笑王侯。\n一蓑一笠，得意何必美封留。\n纵使金章鼎贵，何似玉樽倾到，一醉可消愁。\n玉女在何许，唤起与同游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11691, '水调歌头', '赵善括', '佳客志淮海，贱子设樽。\n楚江昨夜清涨，短棹已安排。\n休问南楼风月，且念阳台云雨，几日却重来。\n银烛正凝泪，画鼓且休催。\n彩云飞，黄鹤举，两徘徊。\n林泉归去高卧，回首笑尘埃。\n我唱更凭君和，君起谁同我舞，莫惜玉山颓。\n他日扬州路，散策愿相陪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11692, '水调歌头', '赵善括', '浩叹对青史，循吏久无闻。\n二年江右，赖公华节布阳春。\n才自搴帷问俗，无复埋轮当道，一路尽澄清。\n多少攀辕意，不待及瓜人。\n驻膏车，迟祖帐，倒离尊。\n满庭桃李绿阴，何处不深恩。\n此去玉音应问，底事金围微减，忧国更忧民。\n造膝一言语，四海入洪钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11693, '满江红', '赵善括', '雨沐风梳，正梅柳、弄香逞色。\n谁忍听、送君南浦，阳关三叠。\n玉节前驱光照路，金杯争劝愁生席。\n泛锦樯、西去若登仙，乘槎客。\n春有意，寒无力。\n和风满，洪波息。\n笑庐峰湓浦，旧游陈迹。\n昔日蜚声台柏劲，他年坐对堂槐密。\n想轺车、不待政成时，追锋急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11694, '满庭芳', '赵善括', '蝶粉蜂黄，桃红李白，春风屡展愁眉。\n晓来雨过，应渐觉红稀。\n满径柔茵似染，新晴後、皱绿盈池。\n休孤负，幕天席地，逸饮酹金彝。\n东君，真好事，降唇歌雪，玉指鸣丝。\n念长卿多病，非药能治。\n试假瑶琴一弄，清音转、便许心知。\n从今去，园林好在，休学岘山碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11695, '好事近', '赵善括', '新月巧穿山，桂树影高群木。\n任使云遮烟锁，自春辉秋绿。\n我来折得最高枝，踏破一轮玉。\n宝斧修教园样，放十分光足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11696, '满江红', '程垓', '门掩垂杨，宝香度、翠帘重叠。\n春寒在，罗衣初试，素肌犹却。\n薄霭笼花天欲暮，小风送角声初咽。\n但独褰、幽幌悄无言，伤初别。\n衣上雨，眉间月。\n滴不尽，颦空切。\n羡栖梁归燕，入帘双蝶。\n愁绪多於花絮乱，柔肠过似丁香结。\n问甚时、重理锦囊书，从头说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11697, '满江红', '程垓', '水远山明，秋容淡、不禁摇落。\n况正是、楼台高处，晚凉犹薄。\n月在衣裳风在袖，冰生枕簟香生幕。\n算四时、佳处是清秋，须行乐。\n东篱下，西窗角。\n寻旧菊，催新酌。\n笑广平何事，对秋萧索。\n摇叶声声深院宇，折荷寸寸闲池阁。\n待归来、闲把木犀花，重薰却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11698, '最高楼', '程垓', '旧时心事，说著两眉羞。\n长记得、凭肩游。\n缃裙罗袜桃花岸，薄衫轻扇杏花楼。\n几番行，几番醉，几番留。\n也谁料、春风吹已断。\n又谁料、朝云飞亦散。\n天易老，恨难酬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11699, '南浦', '程垓', '金鸭懒薰香，向晚来春酲，一枕无绪。\n浓绿涨瑶窗，东风外、吹尽乱红飞絮。\n无言伫立，断肠惟有流莺语。\n碧云欲暮。\n空惆怅，韶华一时虚度。\n追思旧日心情，记题叶西楼，吹花南浦。\n老去觉欢疏，伤春恨，都付断云残雨。\n黄昏院落，问谁犹在凭栏处。\n可堪杜宇。\n空只解声声，催他春去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11700, '摊破江城子・江城梅花引', '程垓', '娟娟霜月又侵门。\n对黄昏。\n怯黄昏。\n愁把梅花，独自泛清尊。\n酒又难禁花又恼，漏声远，一更更，总断魂。\n断魂。\n断魂。\n不堪闻。\n被半温。\n香半温。\n睡也睡也，睡不稳、谁与温存。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11701, '木兰花慢', '程垓', '倩娇莺姹燕，说不尽、此时情。\n正小院春阑，芳园画锁，人去花零。\n凭高试回望眼，奈遥山远水隔重云。\n谁遣风狂雨横，便教无计留春。\n谁知雁杳与鸿冥。\n自难寄丁宁。\n纵柳院颦深，桃门笑在，知属何人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11702, '八声甘州', '程垓', '问东君、既解遣花开，不合放花飞。\n念春风枝上，一分花减，一半春归。\n忍见千红万翠，容易涨桃溪。\n花自随流水，无计追随。\n不忍凭高南望，记旧时行处，芳意菲菲。\n叹年来春减，花与故人非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11703, '洞庭春色・沁园春', '程垓', '锦字亲裁，泪巾偷，细说旧时。\n记笑桃门巷，妆窥宝靥，弄花庭前，香湿罗衣。\n几度相随游冶去，任月细风尖犹未归。\n多少事，有垂杨眼见，红烛心知。\n如今事都过也，但赢得、双鬓成丝。\n叹半妆红豆，相思有分，两分青镜，重合难期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11704, '四代好・宴清都', '程垓', '翠幕东风早。\n兰窗梦，又被莺声惊觉。\n起来空对，平阶弱絮，满庭芳草。\n厌厌未怀抱。\n记柳外、人家曾到。\n凭画阑、那更春好花好，酒好人好。\n春好尚恐阑珊，花好又怕，飘零难保。\n直饶酒好□渑，未抵意中人好。\n相逢尽拼醉倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11705, '水龙吟', '程垓', '夜来风雨匆匆，故园定是花无几。\n愁多愁极，等闲孤负，一年芳意。\n柳困花慵，杏青梅小，对人容易。\n算好春长在，好花长见，元只是、人憔悴。\n回首池南旧事。\n恨星星、不堪重记。\n如今但有，看花老眼，伤时清泪。\n不怕逢花瘦，只愁怕、老来风味。\n待繁红乱处，留云借月，也须拼醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11706, '玉漏迟', '程垓', '一春浑不见，那堪又是，花飞时节。\n忍对危栏数曲，暮云千叠。\n门外星星柳眼，看还似、当时风月。\n愁万结。\n凭谁为我，殷勤低说。\n不是惯却春心，奈新燕传情，旧莺饶舌。\n冷篆馀香，莫放等闲消歇。\n纵使繁红褪尽，犹有、荼シ堪折。\n魂梦切。\n如今不奈，飞来蝴蝶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11707, '折红英・撷芳词', '程垓', '桃花暖。\n杨花乱。\n可怜朱户春强半。\n长记忆。\n探芳日。\n笑凭郎肩，红偎碧。\n惜惜惜。\n春宵短。\n离肠断。\n泪痕长向东风满。\n凭青翼。\n问消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11708, '上平西・金人捧露盘', '程垓', '爱春归，忧春去，为春忙。\n旋点检、雨障云妨。\n遮红护绿，翠帷罗幕任高张。\n海棠明月杏花天，更惜浓芳。\n唤莺吟，招蝶拍，迎柳舞，倩桃妆。\n尽唤起、万籁笙簧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11709, '瑶阶草', '程垓', '空山子规叫，月破黄昏冷。\n帘幕风轻，绿暗红又尽。\n自从别後，粉消香腻，一春成病。\n那堪昼闲日永。\n恨难整。\n起来无语，绿萍破处池光净。\n闷理残妆，照花独自怜瘦影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11710, '碧牡丹', '程垓', '睡起情无著。\n晓雨尽，春寒弱。\n酒盏飘零，几日顿疏行乐。\n试数花枝，问此情何若。\n为谁开，为谁落。\n正愁却。\n不是花情薄。\n花元笑人萧索。\n旧观千红，至今冷梦难托。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11711, '满庭芳', '程垓', '南月惊乌，西风破雁，又是秋满平湖。\n采莲人尽，寒色战菇蒲。\n旧信江南好景，一万里、轻觅莼鲈。\n谁知道，吴侬未识，蜀客已情孤。\n凭高，增怅望，湘云尽处，都是平芜。\n问故乡何日，重见吾庐。\n纵有荷纫芰制，终不似、菊短篱疏。\n归情远，三更雨梦，依旧绕庭梧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11712, '念奴娇', '程垓', '秋风秋雨，正黄昏、供断一窗愁绝。\n带减衣宽谁念我，难忍重城离别。\n转枕褰帷，挑灯整被，总是相思切。\n知他别後，负人多少风月。\n不是怨极愁浓，只愁重见了，相思难说。\n料得新来魂梦里，不管飞来蝴蝶。\n排闷人间，寄愁天上，终有归时节。\n如今无奈，乱云依旧千叠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11713, '雪狮儿', '程垓', '断云低晚，轻烟带暝，风惊罗幕。\n数点梅花，香倚雪窗摇落。\n红炉对谑。\n正酒面、琼稣初削。\n云屏暖，不知门外，月寒风恶。\n迤逦慵云半掠。\n笑盈盈、闲弄宝筝弦索。\n暖极生春，已向横波先觉。\n花娇柳弱。\n渐倚醉、要人搂著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11714, '摸鱼儿', '程垓', '掩凄凉、黄昏庭院，角声何处呜咽。\n矮窗曲屋风灯冷，还是苦寒时节。\n凝伫切。\n念翠被熏笼，夜夜成虚设。\n倚阑愁绝。\n听凤竹声中，犀影帐外，簌簌酿寒轻雪。\n伤心处，却忆当年轻别。\n梅花满园初发。\n吹香弄蕊无人见，帷有暮云千叠。\n情未彻。\n又谁料而今，好梦分胡越。\n不堪重说。\n但记得当初，重门锁处，犹有夜深月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11715, '无闷', '程垓', '天与多才，不合更与，柳怜花情分。\n甚总为才情，恼人方寸。\n早是春残花褪。\n也不料、一春都成病。\n自失笑，因甚腰围半减，珠泪频。\n难省。\n也怨天、也自恨。\n怎免千般思忖。\n倩人说与，又却不忍。\n拼了一生愁闷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11716, '孤雁儿・御街行', '程垓', '在家不觉穷冬好。\n向客里、方知道。\n故园梅花正开时，记得清尊频倒。\n高烧红蜡，暖熏罗幌，一任花枝恼。\n如今客里伤怀抱。\n忍双鬓、随花老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11717, '孤雁儿・御街行', '程垓', '双鬓乍绾横波溜。\n记当日、香心透。\n谁教容易逐鸡飞，输却春风先手。\n天公元也，管人憔悴，放出花枝瘦。\n几宵和月来相就。\n问何事、春山斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11718, '意难忘', '程垓', '花拥鸳房。\n记驼肩髻小，约鬓眉长。\n轻身翻燕舞，低语转莺簧。\n相见处，便难忘。\n肯亲度瑶觞。\n向夜阑，歌翻郢曲，带换韩香。\n别来音信难将。\n似云收楚峡，雨散巫阳。\n相逢情有在，不语意难量。\n些个事，断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11719, '一丛花', '程垓', '伤春时候一凭阑。\n何况别离难。\n东风只解催人去，也不道、莺老花残。\n青笺未约，红绡忍泪，无计锁征鞍。\n宝钗瑶钿一时闲。\n此恨苦天悭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11720, '蓦山溪', '程垓', '老来风味，是事都无可。\n只爱小书舟，剩围着、琅几个。\n呼风约月，随分乐生涯，不羡富，不忧贫，不怕乌蟾堕。\n三杯径醉，转觉乾坤大。\n醉後百篇诗，尽从他、龙吟鹤和。\n升沈万事，还与本来天，青云上，白云间，一任安排我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11721, '满江红', '程垓', '葺屋为舟，身便是、烟波钓客。\n况人间元似，泛家浮宅。\n秋晚雨声篷背稳，夜深月影窗棂白。\n□满船诗酒满船书，随意索。\n也不怕，云涛隔。\n也不怕，风帆侧。\n但独醒还睡，自歌还拍。\n卧後从教秋鳝舞，醉来一任乾坤窄。\n恐有时、撑向大江头，占风色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11722, '小桃红・连理枝', '程垓', '不恨残花妥。\n不恨残春破。\n只恨流光，一年一度，又催新火。\n纵青天白日系长绳，也留春得麽。\n花院重教锁。\n春事从教过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11723, '芭蕉雨', '程垓', '雨过凉生藕叶。\n晚庭消尽暑，浑无热。\n枕簟不胜香滑。\n争奈宝帐情生，金尊意惬。\n玉人何处梦蝶。\n思一见冰雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11724, '红娘子・连理枝', '程垓', '小小闲窗底。\n曲曲深屏里。\n一枕新凉，半床明月，留人欢意。\n奈梅花引里唤人行，苦随他无计。\n几点清觞泪。\n数曲乌丝纸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11725, '醉落魄・一斛珠', '程垓', '夏围初结。\n绿深深处红千叠。\n杜鹃过尽芳菲歇。\n只道无春，满意春犹惬。\n折来一点如猩血。\n透明冠子轻盈贴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11726, '一翦梅', '程垓', '旧日心期不易招。\n重来孤负，几个良宵。\n寻常不见尽相邀。\n见了知他，许大无聊。\n昨夜梅花插翠翘。\n影落清溪，应也魂消。\n假饶真个住山腰。\n那个金章，换得渔樵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11727, '一翦梅', '程垓', '小会幽欢整及时。\n花也相宜。\n人也相宜。\n宝香未断烛光低。\n莫厌杯迟。\n莫恨欢迟。\n夜渐深深漏渐稀。\n风已侵衣。\n露已沾衣。\n一杯重劝莫相违。\n何似休归。\n何自同归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11728, '眼儿媚', '程垓', '一枝烟雨瘦东墙。\n真个断人肠。\n不为天寒日暮，谁怜水远山长。\n相思月底，相思竹外，犹自禁当。\n只恐玉楼贪梦，输他一夜清香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11729, '浪淘沙', '程垓', '山尽两溪头。\n水合天浮。\n行人莫赋大江愁。\n且是芙蓉城下水，还送归舟。\n渔雁两悠悠。\n烟断云收。\n谁教此水却西流。\n载我相思千点泪，还与青楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11730, '雨中花令', '程垓', '闻说海棠开尽了。\n怎生得、夜来一笑。\n颦绿枝头，落红点里，问有愁多少。\n小园闭门春悄悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11731, '雨中花令', '程垓', '旧日爱花心未了。\n紧消得、花时一笑。\n几日春寒，连宵雨闷，不道幽欢少。\n记得去年深院悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11732, '雨中花令', '程垓', '卷地芳草都过了。\n花不语、对人含笑。\n花与人期，人怜花病，瘦似人多少。\n闻道重门深悄悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11733, '凤栖梧・蝶恋花', '程垓', '九月江南烟雨里。\n客枕凄凉，到晓浑无寐。\n起上小楼观海气。\n昏昏半约渔樵市。\n断雁西边家万里。\n料得秋来，笑我归无计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11734, '凤栖梧・蝶恋花', '程垓', '有客钱塘江上住。\n十日斋居，九日愁风雨。\n断送一春弹指去。\n荷花又绕南山渡。\n湖上幽寻君已许。\n消息不来，望得行云暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11735, '凤栖梧・蝶恋花', '程垓', '门外飞花风约住。\n消息江南，已酿黄梅雨。\n蜀客望乡归不去。\n当时不合催南渡。\n忧国丹心曾独许。\n纵吐长虹，不奈斜阳暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11736, '凤栖梧・蝶恋花', '程垓', '薄薄窗油清似镜。\n两面疏帘，四壁文书静。\n小篆焚香消日永。\n新来识得闲中性。\n人爱人嫌都莫问。\n絮自沾泥，不怕东风紧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11737, '凤栖梧・蝶恋花', '程垓', '九月重湖寒意早。\n目断黄云，冉冉连衰草。\n惨别临江愁满抱。\n酒尊时事都相恼。\n闻道吴天消息好。\n鸳鸯西池，咫尺君应到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11738, '愁倚阑・春光好', '程垓', '山无数，雨萧萧。\n路迢迢。\n不似芙蓉城下去，柳如腰。\n梦随春絮飘飘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11739, '渔家傲', '程垓', '野店无人霜似水。\n清灯照影寒侵被。\n门外行人催客起。\n因个事。\n老来方有思家泪。\n寄问梅花开也未。\n爱花只有归来是。\n想见小桥歌舞地。\n浑含喜。\n天涯不念人憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11740, '渔家傲', '程垓', '独木小舟烟雨湿。\n燕儿乱点春江碧。\n江上青山随意觅。\n人寂寂。\n落花芳草催寒食。\n昨夜青楼今日客。\n吹愁不得东风力。\n细拾残红书怨泣。\n流水急。\n不知那个传消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11741, '临江仙', '程垓', '送我南来舟一叶，谁教催动鸣榔。\n高城不见水茫茫。\n云湾才几曲，折尽九回肠。\n买酒浇愁愁不尽，江烟也共凄凉。\n和天瘦了也何妨。\n只愁今夜雨，更做泪千行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11742, '临江仙', '程垓', '浓绿锁窗闲院静，照人明月团团。\n夜长幽梦见伊难。\n瘦从香脸薄，愁到翠眉残。\n只道花时容易见，如今花尽春阑。\n画楼依旧五更寒。\n可怜红绣被，空记合时欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11743, '朝中措', '程垓', '矮窗西畔翠荷香。\n人在小池塘。\n何事未拈期局，却来闲倚胡床。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11744, '朝中措', '程垓', '华筵饮散撤芳尊。\n人影乱纷纷。\n且约玉骢留住，细将团凤平分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11745, '朝中措', '程垓', '龙团分罢觉芳滋。\n歌彻碧云词。\n翠袖且留纤玉，沈香载捧冰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11746, '朝中措', '程垓', '真游六六洞中仙。\n骑鹤下三天。\n休道日斜岁暮，行年方是韶华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11747, '朝中措', '程垓', '片花飞後水东流。\n无计挽春留。\n香小谁栽杜若，梦回依旧扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11748, '醉落魄・一斛珠', '程垓', '风催雨促。\n今番不似前欢足。\n早来最苦离情毒。\n唱我新词，掩著面儿哭。\n临行只怕人行远。\n殷勤更写多情曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11749, '酷相思', '程垓', '月挂霜林寒欲坠。\n正门外、催人起。\n奈离别、如今真个是。\n欲住也、留无计。\n欲去也、来无计。\n马上离魂衣上泪。\n各自个、供憔悴。\n问江路梅花开也未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11750, '生查子', '程垓', '溪光曲曲村，花影重重树。\n风物小桃源，春事还如许。\n情知送客来，又作寻芳去。\n可惜一春诗，总为闲愁赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11751, '生查子', '程垓', '长记别郎时，月淡梅花影。\n梅影又横窗，不见江南信。\n无心换夕香，有分怜朝镜。\n不怕瘦棱棱，只怕梅开尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11752, '忆王孙', '程垓', '萧萧梅雨断人行。\n门掩残春绿荫生。\n翠被寒灯枕自横。\n梦初惊。\n窗外啼鹃催五更。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11753, '卜算子', '程垓', '枕簟暑风消，帘幕秋风动。\n月到夜来愁处明，只照团衾凤。\n去意杳无凭，别语愁难送。\n一纸鱼笺枕底香，且做新来梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11754, '卜算子', '程垓', '独自上层楼，楼外青山远。\n望到斜阳欲尽时，不见西飞雁。\n独自下层楼，楼下蛩声怨。\n待到黄昏月上时，依旧柔肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11755, '卜算子', '程垓', '几日赏花天，月淡荼シ小。\n写尽相思唤不来，又是花飞了。\n春在怕愁多，春去怜欢少。\n一夜安排梦不成，月堕西窗晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11756, '霜天晓角', '程垓', '几夜锁窗揭。\n素蟾光似雪。\n恰恨照人欹枕，纱橱爽、簟纹滑。\n迤逦篆香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11757, '霜天晓角', '程垓', '玉清冰样洁。\n几夜相思切。\n谁料浓云遮拥，同心带、甚时结。\n匆匆休惜别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11758, '乌夜啼', '程垓', '杨柳拖烟漠漠，梨花浸月溶溶。\n吹香院落春还尽，憔悴立东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11759, '乌夜啼', '程垓', '白酒欺人易醉，黄花笑我多愁。\n一年只有秋光好，独自却悲秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11760, '乌夜啼', '程垓', '绿外深深柳巷，红间曲曲花楼。\n一春想见贪游冶，不道有人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11761, '瑞鹧鸪', '程垓', '东风冷落旧梅台。\n犹喜山花拂面开。\n绀色染衣春意静，水沈熏骨晚风来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11762, '瑞鹧鸪', '程垓', '门前杨柳绿成阴。\n翠坞笼香径自深。\n迟日暖熏芳草眼，好风轻撼落花心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11763, '青玉案', '程垓', '宝林岩畔凌云路。\n记藉草、寻梅去。\n咏绿书红知几度。\n行云归後，碧云遮断，寂寞人何处。\n一声长笛江天暮。\n别後谁吟倚楼句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11764, '好事近', '程垓', '别梦记春前，春尽苦无归日。\n想见鹊声庭院，误几回消息。\n万重离恨万重山，无处说思忆。\n只有路傍双堠，也随人孤只。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11765, '好事近', '程垓', '天淡一帘秋，明月几时来得。\n何事桂底香近，把清光邀勒。\n人间明晦总由天，何必问通塞。\n且为人如月好，醉莫分南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11766, '好事近', '程垓', '烟尽戍楼空，又是一帘佳月。\n何事山城留滞，负好花时节。\n烧灯翦彩没心情，应有翠娥说。\n欲借好风吹恨，奈乱云愁叠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11767, '好事近', '程垓', '急雨闹冰荷，销尽一襟烦暑。\n趁取晚凉幽会，近翠阴浓处。\n风梢危滴撼珠矶，洒面得新句。\n莫怪玉壶倾尽，待月明归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11768, '点绛唇', '程垓', '梅雨收黄，暑风依旧闲庭院。\n露荷轻颤。\n只有香浮面。\n挂起西窗，月澹无人见。\n幽情远。\n随钗低扇。\n好个凉方便。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11769, '如梦令', '程垓', '风入藕花翻动。\n夜气与香俱纵。\n月又带风来，凉意一襟谁共。\n情重。\n情重。\n可惜短宵无梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11770, '清平乐', '程垓', '山城桃李。\n催促春无几。\n日日为花须早起。\n犹□惜花无计。\n阿谁留得春风。\n长教绕绿围红。\n莫遣十分芳意，输他万点愁容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11771, '清平乐', '程垓', '秋香谁买。\n散入琉璃界。\n点缀小红全不碍。\n还却铅华馀债。\n夜来月底相期。\n一枝未觉香迟。\n恰似青绫帐底，绛罗初试裙儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11772, '清平乐', '程垓', '疏疏整整。\n风急花无定。\n红烛照筵寒欲凝。\n时见筛帘玉影。\n夜深明月笼纱。\n醉归凉面香料。\n犹有惜梅心在，满庭误作吹花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11773, '清平乐', '程垓', '绿深红少。\n柳外横桥小。\n双燕不知幽梦好。\n惊起碧窗春晓。\n起来瞢多时。\n玉台金镜慵移。\n多少春愁未说，却来闲数花枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11774, '望秦川・南歌子', '程垓', '柳弱眠初醒，梅残舞尚痴。\n春阴将冷傍帘帷。\n又是东风和恨、向人归。\n乐事灯前记，愁肠酒後知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11775, '望秦川・南歌子', '程垓', '竹粉翻新箨，荷花拭靓妆。\n断云侵晚度横塘。\n小扇斜钗依约、傍牙床。\n蘸蜜分红荔，倾筒泻碧香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11776, '望秦川・南歌子', '程垓', '翠黛随妆浅，铢衣称体香。\n好风偏与十分凉。\n却扇含情独自、绕池塘。\n碧藕丝丝嫩，红榴叶叶双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11777, '天仙子', '程垓', '惨惨霜林冬欲尽。\n又是溪梅寒弄影。\n矮窗曲屋夜烧香，人已静。\n灯垂烬。\n点滴芭蕉和雨听。\n约个归期犹未定。\n一夜梦魂终不稳。\n知他勾得许多情，真个闷。\n无人问。\n说与画楼应不信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11778, '望江南・忆江南', '程垓', '篷上雨，篷底有人愁。\n身在汉江东畔去，不知家在锦江头。\n烟水两悠悠。\n吾老矣，心事几时休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11779, '南歌子', '程垓', '雨燕翻新幕，风鹃绕旧枝。\n画堂春尽日迟迟。\n又是一番平绿、涨西池。\n病起尊难尽，腰宽带易垂。\n不堪村落子规啼。\n问道行人一去、几时归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11780, '南歌子', '程垓', '淡霭笼青琐，轻寒薄翠绡。\n有人憔悴带宽腰。\n又见东风、不忍见柔条。\n闷酒尊难寻，闲香篆易销。\n夜来溪雪已平桥。\n溪上梅魂凭仗、一相招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11781, '南歌子', '程垓', '梅坞飞香定，兰窗翠色齐。\n水边沙际又春归。\n领略东风、能有几人知。\n爱月眠须晚，寻花去未迟。\n谁家庭院更芳菲。\n费尽才情、休负一春诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11782, '南歌子', '程垓', '荷盖倾新绿，榴巾蹙旧红。\n水亭烟榭晚凉中。\n又是一钩新月、静房栊。\n丝藕清如雪，纱薄似空。\n好维今夜与谁同。\n唤取玉人来共、一帘风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11783, '南歌子', '程垓', '野水寻溪路，青山踏晚春。\n偶来相值却锺情。\n一树琼瑶洗尽、客衣襟。\n曲沼通诗梦，幽窗净俗尘。\n何时散发伴裙。\n後夜相思生怕、月愁人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11784, '南乡子', '程垓', '几日诉离尊。\n歌尽阳关不忍分。\n此度天涯真个去，销魂。\n相送黄花落叶村。\n斜日又黄昏。\n萧寺无人半掩门。\n今夜粉香明月泪，休论。\n只要罗巾记旧痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11785, '浪淘沙', '程垓', '才合又轻离。\n心事多违。\n小窗灯影记亲移。\n可奈酒酣花困处，不省人归。\n山翠又如眉。\n肠断幽期。\n相思有梦阿谁知。\n莫遣重来风絮乱，不似当时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11786, '浪淘沙', '程垓', '老去懒寻花。\n独自生涯。\n几枝疏影浸窗纱。\n昨夜月来人不睡，看尽横斜。\n门外欲啼鸦。\n香意凌霞。\n从渠千树绕人家。\n世上一枝元也足，不要随他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11787, '摊破南乡子', '程垓', '休赋惜春诗。\n留春住、说与人知。\n一年已负东风瘦，说愁说恨，数期数刻，只望归时。\n莫怪杜鹃啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11788, '祝英台・祝英台近', '程垓', '坠红轻，浓绿润，深院又春晚。\n睡起厌厌，无语小妆懒。\n可堪三月风光，五更魂梦，又都被、杜鹃催攒。\n怎消遣。\n人道愁与春归，春归愁未断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11789, '虞美人', '程垓', '轻红短白东城路。\n忆得分襟处。\n柳丝无赖舞春柔。\n不系离人、只解系离愁。\n如今花谢春将老。\n柳下无人到。\n月明门外子规啼。\n唤得人愁、争似唤人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11790, '长相思', '程垓', '对重阳。\n感重阳。\n身在西风天一方。\n年年人断肠。\n景凄凉。\n客凄凉。\n纵有黄花祗异乡。\n晚云连梦长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11791, '长相思', '程垓', '酒孤斟。\n客孤吟。\n戏马台荒露草深。\n英雄何处寻。\n爱登临。\n莫登临。\n定是愁来关客心。\n暮天烟水沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11792, '长相思', '程垓', '风敲窗。\n雨敲窗。\n窗外芭蕉云作幢。\n声声愁对床。\n剔银缸。\n点银缸。\n梦采芙蓉隔一江。\n几时蝴蝶双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11793, '鹊桥仙', '程垓', '角声吹月，风声落枕，梦与柔肠俱断。\n谁教当日太情浓，不下、新愁一段。\n黄花开了，梅花开未，曾约那时相见。\n莫教容易负幽期，怕真个、孤他泪眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11794, '醉落魄・一斛珠', '程垓', '晚凉时节。\n翠梧风定蝉声歇。\n有人睡起香浮颊。\n倚著阑干，笑拣青荷叶。\n如今往事愁难说。\n曲池依旧闲风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11795, '减字木兰花', '程垓', '双双相并。\n一点红边偏照映。\n玉翦云裁。\n不比浮花共蒂开。\n几回心曲。\n选胜摘来情自足。\n插向云鬟。\n要与仙郎比并看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11796, '谒金门', '程垓', '春悄悄。\n红到一枝先巧。\n酒入半腮微带卯。\n粉寒香未饱。\n芳意枝头偏闹。\n困尽蜂须莺爪。\n拟倩玉纤和露拗。\n情多愁易搅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11797, '谒金门', '程垓', '花簇簇。\n触眼万条垂玉。\n小院春深窗锁绿。\n水沈风断续。\n明月又侵楼曲。\n羞向枕囊拘束。\n只待夜深清影足。\n醉来花底宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11798, '谒金门', '程垓', '乌帽侧。\n行遍杏花春色。\n野意青青分陇麦。\n人家烟水隔。\n春事莫催行客。\n弹指青梅堪摘。\n醉倚暮天江拍拍。\n雨晴沙路白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11799, '谒金门', '程垓', '花半湿。\n一霎晚云笼密。\n天气未佳风又急。\n小庭愁独立。\n酒病起来无力。\n懊恼篆烟锁碧。\n一饷春情无处觅。\n小屏山数尺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11800, '谒金门', '程垓', '春夜雨。\n催润柳塘花坞。\n小院深深门几许。\n画帘香一缕。\n独立晚庭凝伫。\n细把花枝闲数。\n燕子不来天欲暮。\n说愁无处所。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11801, '谒金门', '程垓', '风阵阵。\n吹落杨花无定。\n酒病厌厌三月尽。\n花檀红自隐。\n新绿轩窗清润。\n月影又移墙影。\n手拈青梅无处问。\n一春长闷损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11802, '谒金门', '程垓', '浓睡醒。\n惊对一帘秋影。\n桐叶乍零风不定。\n半窗疏雨影。\n愁与年光不尽。\n老入星星双鬓。\n只拟上楼寻远信。\n雁遥烟水暝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11803, '蝶恋花', '程垓', '日下船篷人未起。\n一个燕儿，说尽伤春意。\n江上残花能有几。\n风催雨促成容易。\n湖海客心千万里。\n著力东风，推得人行未。\n相次桃花三月水。\n菱歌谁伴西湖醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11804, '蝶恋花', '程垓', '满路梅英飞雪粉。\n临水人家，先得春光嫩。\n楼底杏花楼外影。\n墙东柳线墙西恨。\n撷翠揉红何处问。\n暖入眉峰，已作伤春困。\n归路月痕弯一寸。\n芳心只为东风损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11805, '蝶恋花', '程垓', '寒意勒花春未足。\n只有东风，不管春拘束。\n杨柳满城吹又绿。\n可人青眼还相属。\n小叶星星眠未熟。\n看尽行人，唱彻阳关曲。\n心事一春何计续。\n芳条未展眉先蹙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11806, '蝶恋花', '程垓', '晴带溪光春自媚。\n绕翠萦青，来约东风醉。\n云补断山疏复缀。\n雨回绿野清还丽。\n拄杖不妨舒客意。\n临水人家，问有花开未。\n江左风流今有几。\n逢春不要人憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11807, '蝶恋花', '程垓', '翠幕成阴帘拂地。\n池馆无人，四面生凉意。\n荷气竹香俱细细。\n分明著莫清风袂。\n玉枕如冰笙似水。\n才横钗，早被莺呼起。\n今夜月明人未睡。\n只消三四分来醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11808, '蝶恋花', '程垓', '画阁红炉屏四向。\n梅拥寒香，次第侵帷帐。\n烛影半低花影幌。\n修眉正在花枝傍。\n粉偎香羞一饷。\n未识春风，已觉春情荡。\n醉里不知霜月上。\n归来已踏梅花浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11809, '蝶恋花', '程垓', '楼角吹花烟月堕。\n的韶研，又向梅心破。\n钗上采看一个。\n赏心已觉春生坐。\n莫恨年华风雨过。\n人日嬉游，次第连灯火。\n翠幄高张金盏大。\n已拼醉袖随香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11810, '蝶恋花', '程垓', '小院菊残烟雨细。\n天气凄凉，恼得人憔悴。\n被暖橙香羞早起。\n玉钗一任慵云坠。\n楼上珠帘钩也未。\n数尺遥山，供尽伤高意。\n伫立不禁残酒味。\n绣罗依旧和香睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11811, '蝶恋花', '程垓', '小院秋光浓欲滴。\n独自钩帘，细数归鸿翼。\n鸿断天高无处觅。\n矮窗催暝蛩催织。\n凉月去人才数尺。\n断发萧骚，醉傍西风立。\n愁眼望天收不得。\n露华衣上三更湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11812, '蝶恋花', '程垓', '晴日溪山春可数。\n水绕池塘，知有人家住。\n寻日寻花花不语。\n旧时春恨还如许。\n苦恨东风无意绪。\n只解催花，不解催人去。\n日晚荒烟迷古戍。\n断魂正在梅花浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11813, '菩萨蛮', '程垓', '和风暖日西郊路。\n游人又踏青山去。\n何处碧云衫。\n映溪才两三。\n疏松分翠黛。\n故作羞春态。\n回首杏烟消。\n月明归渡桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11814, '菩萨蛮', '程垓', '春回绿野烟光薄。\n低花矮柳田家乐。\n陇麦又青青。\n喧蜂闲趁人。\n野翁忘近远。\n怪识刘郎面。\n断却小桥溪。\n怕人溪外知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11815, '菩萨蛮', '程垓', '画桥拍拍春江绿。\n行人正在春江曲。\n花润接平川。\n有人花底眠。\n东风元自好。\n只怕催花老。\n安得万垂杨。\n系教春日长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11816, '菩萨蛮', '程垓', '平芜冉冉连云绿。\n斜阳衬雨明溪足。\n小鸭睡晴沙。\n翠烘三两花。\n春光闲婉娩。\n尽日无人见。\n试著小屏山。\n图归云际看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11817, '菩萨蛮', '程垓', '山头翠树调莺舌。\n山腰野菜飞黄蝶。\n来为等闲休。\n去成多少愁。\n小庭花木改。\n犹有啼痕在。\n别後不曾看。\n怕花和泪残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11818, '菩萨蛮', '程垓', '罗衫乍试寒犹怯。\n妒花风雨连三月。\n灯冷闭门时。\n有愁谁得知。\n此情真个苦。\n只为当时语。\n莫道絮沾泥。\n絮飞魂亦飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11819, '菩萨蛮', '程垓', '夜来花底莺饶舌。\n把人心事分明说。\n许大好因缘。\n只成容易传。\n春阑无好计。\n唯有归来是。\n从此玉台前。\n晓妆休太妍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11820, '菩萨蛮', '程垓', '小窗荫绿清无暑。\n篆香终日萦兰炷。\n冰簟涨寒涛。\n清风一枕高。\n有日团扇却。\n门掩庭花落。\n少待月侵床。\n教他魂梦凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11821, '菩萨蛮', '程垓', '暑庭消尽风鸣树。\n树鸣风尽消庭暑。\n横枕一声莺。\n莺声一枕横。\n扇纨低粉面。\n面粉低纨扇。\n凉月淡侵床。\n床侵淡月凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11822, '菩萨蛮', '程垓', '东风有意留人住。\n熏风无意催人去。\n去住两茫然。\n相逢成短缘。\n平生花柳笑。\n过後关心少。\n今日奈情何。\n为伊饶恨多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11823, '菩萨蛮', '程垓', '去年恰好双星节。\n鹊桥未渡人离别。\n不恨障云生。\n恨他真个行。\n天涯消息近。\n不见乘鸾影。\n楼外鹧鸪声。\n几回和梦惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11824, '菩萨蛮', '程垓', '浅寒带暝和烟下。\n轻阴挟雨随风洒。\n翠幕护重帘。\n篆香销半奁。\n平生风雨夜。\n怕近芭蕉下。\n今夕定愁多。\n萧萧声奈何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11825, '菩萨蛮', '程垓', '客窗曾剪灯花弄。\n谁教来去如春梦。\n冷落旧梅台。\n小桃相次开。\n人间春易老。\n只有山中好。\n闲却槿花篱。\n莫教溪外知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11826, '菩萨蛮', '程垓', '晓烟笼日浮山翠。\n春风著水回川媚。\n远近碧重重。\n人家山色中。\n野花香自度。\n似识幽人处。\n安得著三间。\n与山终日闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11827, '菩萨蛮', '程垓', '扶犁野老田东睡。\n插花山女田西醉。\n醉眼眩东西。\n看看桃满溪。\n耕桑山下足。\n纨绮人间俗。\n莫管旧东风。\n从教吹软红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11828, '木兰花・玉楼春', '程垓', '疏枝半作窥窗老。\n又是一年春意早。\n风低小院得香迟，月傍女墙和影好。\n去年苦被离情恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11829, '鹧鸪天', '程垓', '昨夜思量直到明。\n拂明心绪更愁人。\n风披露叶高低怨，冷雨寒烟各自轻。\n休赖酒，莫求神。\n为谁教尔许多情。\n如今早被思量损，好更当时做弄成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11830, '入塞', '程垓', '好思量。\n正秋风、半夜长。\n奈银缸一点，耿耿背西窗。\n衾又凉。\n枕又凉。\n露华凄凄月半床。\n照得人、真个断肠。\n窗前谁浸木犀黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11831, '桃源忆故人', '程垓', '粉霜拂拂凝香砌。\n酝酿梅花天气。\n月上小窗如水。\n冷浸人无寐。\n平生可惯闲憔悴。\n担负新愁不起。\n消遣夜长无计。\n只倚熏香睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11832, '愁倚阑・春光好', '程垓', '春犹浅，柳初芽。\n杏初花。\n杨柳杏花交影处，有人家。\n玉窗明暖烘霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11833, '乌夜啼', '程垓', '静院槐风绿涨，小窗梅雨黄垂。\n欲看春事留连处，惟有夜寒知。\n魂梦长闲消午醉，扫花共坐风凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11834, '忆秦娥', '程垓', '青门深。\n海棠开尽春阴阴。\n春阴阴。\n万重云水，一寸归心。\n玉楼深锁烟消沈。\n知他何日同登临。\n同登临。\n待收红泪，细说如今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11835, '忆秦娥', '程垓', '情脉脉。\n半黄橙子和香擘。\n和香擘。\n分明记得，袖香熏窄。\n别来人远关山隔。\n见梅不忍和花摘。\n和花摘。\n有书无雁，寄谁归得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11836, '忆秦娥', '程垓', '愁无语。\n黄昏庭院黄梅雨。\n黄梅雨。\n新愁一寸，旧愁千缕。\n杜鹃叫断空山苦。\n相思欲计人何许。\n一重云断，一重山阻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11837, '西江月', '程垓', '众绿初围夏荫，老红犹驻春妆。\n画帘燕子日偏长。\n静看新雏来往。\n□□□□□□，□□□□□□。\n□□□□□□□。\n□□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11838, '西江月', '程垓', '□□□□□□，□□□□□□。\n□□□□□□□。\n□□□□□□。\n汲井漫随兰炷，心情半怯罗衣。\n粉香消尽无人觑，只门外、子规啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11839, '乌夜啼', '程垓', '墙外雨肥梅子，阶前水绕荷花。\n阴阴庭户熏风满，水纹簟、怯菱芽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11840, '浣溪沙', '程垓', '天女殷勤著意多。\n散花犹记病维摩。\n肯来丈室问云何。\n腰佩摘来烦玉笋，鬓香分处想秋波。\n不知真个有情麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11841, '浣溪沙', '程垓', '遥想当年出凤雏。\n王□风有未全疏。\n祗今朱绂为谁纡。\n芳草池塘春梦後，粉香帘幕晓晴初。\n一簪华发要人梳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11842, '浣溪沙', '程垓', '翠葆扶疏傍药阑。\n乱红飘洒满书单。\n清明时节又看看。\n小雨勒成春尾恨，东风偏作夜来寒。\n琴心老尽不须弹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11843, '浣溪沙', '程垓', '薄日移影午暑空。\n一杯何事便潮红。\n扇纨挥尽却疏慵。\n早睡青怀冰枕外，夜来消息雨荷中。\n不须留烛眩房栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11844, '浣溪沙', '程垓', '闲倚前荣小扇车。\n晚妆无力云鸦。\n凝情香落一庭花。\n笑挽清风归玉枕，懒随缺月傍窗纱。\n羞红两脸上娇霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11845, '鹧鸪天', '程垓', '木落江空又一秋。\n天寒几日不登楼。\n红绡帐里橙犹在，青琐窗深菊未收。\n新画阁，小书舟。\n篆烟熏得晚香留。\n只因贪伴开炉酒，恼得红儿一夜讴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11846, '鹧鸪天', '程垓', '泪湿芙蓉城上花。\n片飞何事苦参差。\n锁深不奈莺无语，巢稳争如燕有家。\n情未老，鬓先华。\n可怜各自淡生涯。\n桃花不解知人意，犹自沾泥也学他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11847, '一落索', '程垓', '门外莺寒杨柳。\n正减欢疏酒。\n春阴早是做人愁，更何况、花飞後。\n莫倚东风消瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11848, '一落索', '程垓', '小小腰身相称。\n更著人心性。\n一声歌起绣帘阴，都遏住、行云影。\n闻道玉郎家近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11849, '破阵子', '程垓', '小小红泥院宇，深深翠色屏帷。\n簇定熏炉酥酒软，门外东风寒不知。\n恰疑三月时。\n钗影半欹绿子，歌声轻度红儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11850, '一翦梅', '程垓', '斗转参横一夜霜。\n玉律声中，又报新阳。\n起来无绪赋行藏。\n只喜人间，一线添长。\n帘幕垂垂月半廊。\n节物心情，都付椒觞。\n年华渐晚鬓毛苍。\n身外功名，休苦思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11851, '木兰花・玉楼春', '程垓', '别时已有重来愿。\n谁料情多天不管。\n分明咫尺是青楼，抵死浓云遮得遍。\n寄声只倚西飞雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11852, '生查子', '程垓', '兰帷夜色高，绣被春寒拥。\n何事玉楼人，屡踏杨花梦。\n分明相见陈，不道幽情重。\n乞个好因缘，莫待来生种。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11853, '满庭芳', '虞俦', '色染莺黄，枝横鹤瘦，玉奴蝉蜕花间。\n铅华不御，慵态尽欹鬟。\n冷淡琐窗烟雾，来清供、莞尔怡颜。\n狂蜂蝶，还须敛衽，何得傍高闲。\n西山。\n招隐处，寒云缭绕，流水回环。\n念风前绰约，雪後清孱。\n别是仙韵道标，应羞对、舞袖弓弯。\n怀真赏，今宵归梦，一饷许跻攀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11854, '临江仙', '虞俦', '万壑千岩秋色里，歌眉醉眼争妍。\n一枝娇柳趁么弦。\n疑非香案吏，诏到小蓬天。\n乐事便成陈迹也，依人小月娟娟。\n尊前空唱短因缘。\n引船风又起，吹过浙江边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11855, '阮郎归', '徐似道', '茶寮山上一头陀。\n新来学者麽。\n蝤蛑螃蟹与乌螺。\n知他放几多。\n有一物，是蜂窝。\n姓牙名老婆。\n虽然无奈得它何。\n如何放得它。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11856, '浪淘沙', '徐似道', '风紧浪淘生。\n蛟吼鼍鸣。\n家人睡著怕人惊。\n只有一翁扪虱坐，依约三更。\n雪又打残灯。\n欲暗还明。\n有谁知我此时情。\n独对梅花倾一盏，还又诗成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11857, '瑞鹤仙令・临江仙', '徐似道', '西子湖边春正好，输他公子王孙。\n落花香趁马蹄温。\n暖烟桃叶渡，晴日柳枝门。\n中有能诗狂处士，闲将一鹤随轩。\n百钱买只下湖船。\n就他弦管里，醉过杏花天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11858, '一剪梅・一翦梅', '徐似道', '道学从来不则声。\n行也东铭。\n坐也西铭。\n爷娘死後更伶丁。\n也不看经。\n也不斋僧。\n却言渊子太狂生。\n行也轻轻。\n坐也轻轻。\n他年青史总无名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11859, '失调名', '徐似道', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11860, '蓦山溪', '徐安国', '青梅骨瘦，已有生春意。\n椒萼露微花，便觉香魂旖旎。\n惜花公子，可是赋情深，携瘦竹，绕疏篱，终日成孤倚。\n赏心乐事，又也何曾废。\n烟露湿铅华，误啼妆、三年客里。\n江南芳信，政自不愆期，吴山远，越山长，梦寐添憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11861, '鹧鸪天', '徐安国', '翠幕围香夜正迟。\n红麟生焰烛交辉。\n纤腰趁拍轻於柳，娇面添妆韵似梅。\n凝远恨，惜芳期。\n十年幽梦彩云飞。\n多情不管霜髯满，犹欲杯翻似旧时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11862, '满江红', '徐安国', '挥手华堂，重整顿、选花场屋。\n撩鼻观、飞浮杂沓，异香芬馥。\n金缕尚馀闲态度，冰姿早作新妆束。\n恨尊前、缺典费思量，无松竹。\n蜂蝶恨，何时足。\n桃李怨，成粗俗。\n为情深、拼了一生愁独。\n菊信谩劳频探问，兰心未许相随逐。\n想从今、无暇蔷薇，锄罂粟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11863, '满江红', '徐安国', '争献交酬，消受取、真山真水。\n供不尽、杯螺浮碧，髻鬟拥翠。\n莫便等闲嗟去国，固因特地经仙里。\n奉周旋、惟有老先生，门堪倚。\n追往驾，烟宵里。\n终旧学，今无计。\n叹白头犹记，壮年标致。\n一乐堂深文益著，风雩亭在词难继。\n问有谁、熟识晦庵心，南轩意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11864, '祝英台・祝英台近', '黄人杰', '异乡中，行色里，随分庆初度。\n老子今年，五十又还五。\n任他坎止流行，吴头楚尾，本来是、乾坤逆旅。\n贵和富。\n此事都付浮云，无必也无固。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11865, '酹江月・念奴娇', '黄人杰', '年时今日，御双凫曾到、蓬壶方丈。\n元是王孙生此夕，红紫娇春成行。\n数曲栏干，一双荚，正傍瑶阶长。\n风帘斜处，有时新燕来往。\n犹记不住称觞，挥毫著语，更与书扁榜。\n转首还逢汤饼客，景物依然和畅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11866, '感皇恩', '黄人杰', '秋色满西湖，雨添新绿。\n一派烟光望中足。\n清香十里，画舸去来相逐。\n酒酣时听得，渔家曲。\n人道似郎，郎还第六。\n云水相逢未谙熟。\n晚来风静，闲浸几枝红玉。\n水神应不禁，江妃浴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11867, '念奴娇', '黄人杰', '西湖胜绝，有栖云楼观，蟠空丘壑。\n玉鉴光中天不老，人在蓬壶行乐。\n画舫藏春，垂杨系马，幽处笙箫作。\n京华狂客，也忘身世飘泊。\n行时载酒寻芳，湖湾堤曲，放浪红尘脚。\n借景留欢排日醉，不负莺花盟约。\n忍缓东风，耐烦迟日，休恁匆匆著。\n温存桃李，莫教一顿开却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11868, '浣溪沙', '黄人杰', '的江梅共蜡梅。\n剪金裁玉一时开。\n黄姑相伴雪儿来。\n别驾公馀无个事，得将诗酒与栽培。\n为春留客小徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11869, '生查子', '黄人杰', '烟雨不多时，肥得梅如许。\n早有点儿酸，诮没星儿苦。\n飞燕恶禁持，又待衔春去。\n容著水精盐，觅个调羹处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11870, '柳梢青', '黄人杰', '恰则年时。\n风前雪底，初见南枝。\n可匆匆，花才清瘦，子已红肥。\n安排酒盏相随。\n看金弹、累累四垂。\n渴後情怀，鼎中风味，惟有心知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11871, '蓦山溪', '黄人杰', '翠环惊报，叶底梅如弹。\n小摘试尝看，齿微酸、生香不断。\n烟丸露颗，肥得颊儿红，还欲近，浅黄时，风雨催残半。\n何如珍重，剩著冰盘荐。\n持酒劝飞仙，似江梅、累累子满。\n饶将风味，成就与东君，随鼎鼐，著形盐，早趁调羹便。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11872, '满江红', '黄人杰', '小队旌旗，又催送、元戎领客。\n政十顷、荷香微度，草烟横碧。\n杨柳参差新合翠，水天上下俱齐色。\n傍野桥、容与绕重湖，严城侧。\n花作阵，舟为宅。\n敲羯鼓，鸣羌笛。\n渐夜凉风进，酒杯无力。\n遥想汉中鸡肋地，未应万里回金勒。\n看便随、飞诏下南州，朝京国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11873, '点绛唇', '蔡戡', '纤手工夫，采丝五色交相映。\n同心端正。\n上有双鸳并。\n皓腕轻缠，结就相思病。\n凭谁信。\n玉肌宽尽。\n却系心儿紧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11874, '水调歌头', '蔡戡', '肃霜靡衰草，骤雨洗寒空。\n刀弓斗力增劲，万马骤西风。\n细看外围合阵，忽变横斜曲直，妙在指麾中。\n号令肃诸将，谈笑听元戎。\n坐中客，休笑我，已衰翁。\n十年重到，今日此会与谁同。\n差把龙锺鹤发，来对虎头燕颔，年少总英雄。\n飞镞落金碗，酣醉吸长虹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11875, '水调歌头', '蔡戡', '拥节出闽峤，易镇上岷山。\n东西，分陕初不在荣观。\n痛念两河未复，独作中流砥柱，屹若障狂澜。\n极目神京远，百万虎貔闲。\n趁良时，摅豹略，勇声欢。\n风飞雷厉，威行逆虏胆生寒。\n汉寝周原如旧，一扫腥膻丑类，谈笑定三关。\n识取投机会，莫作等闲看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11876, '鹧鸪天', '何澹', '庾岭移来傍桂丛。\n绕花安敢望凌风。\n癯儒合作孤芳伴，四面相看一笑同。\n冰照座，玉横空。\n雪花零落暗香中。\n有人醉倚阑干畔，付与江南老画工。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11877, '桃源忆故人', '何澹', '拍堤芳草随人去。\n洞口山无重数。\n翦朝露成树。\n争晚渔翁住。\n今人忍听秦人语。\n只有花无今古。\n欲饮仙家寿醑。\n记取桥边路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11878, '满江红', '何澹', '灯夕筵开，人物共、英词三绝。\n环坐处、袖中珠玉，郢中春雪。\n红烛星繁销夜漏，紫霞香满催歌拍。\n算新年、何处不风光，三山别。\n云表殿，千层结。\n花籍锦，添明月。\n更浮屠七塔，万枝争发。\n多谢一天驱宿霭，故教三日成佳节。\n更何须、海上觅蓬莱，真仙阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11879, '满江红', '何澹', '乐禁初开，平地耸、海山清绝。\n千里内、欢声和气，可融霜雪。\n盛事终将椽笔记，新歌翻入梨园拍。\n道古来、南国做元宵，今宵别。\n灯万碗，花千结。\n星斗上，天浮月。\n向玉绳低处，笙箫高发。\n人物尽夸长乐郡，儿童争庆烧灯节。\n疑此身、清梦到华胥，朝金阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11880, '鹧鸪天', '何澹', '好景良辰造物悭。\n一年灯火遽摧残。\n雨淋夹道星千点，雪阻游人路九盘。\n停社舞，撤宾筵。\n谩烧银烛照金莲。\n不如我入香山社，一盏青灯说夜禅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11881, '满江红', '陈三聘', '薄日轻云，天气好、相将祈谷。\n民情喜、颂声洋溢，清风斯穆。\n饮酒不多元有量，吟诗无数添新轴。\n对古人、一笑我真愚，君无俗。\n斜川路，经行熟。\n黄花在，归心足。\n问渊明去後，有谁能属。\n神武衣冠惊梦里，江湖渔钓论心曲。\n但从今、散发更披襟，谁能束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11882, '满江红', '陈三聘', '天岂无情，天若道、有情也老。\n功名事、问天因甚，蒙人不了。\n好伴云烟耕谷口，休将翰墨传江表。\n算鬓边、能得几春风，惊秋早。\n陶令尹，张京兆。\n怀舒啸，贪荣耀。\n尽南柯一梦，漏残钟晓。\n滕阁暮霞孤鹜举，庾楼明月乌飞绕。\n念老来、於此兴无穷，知音少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11883, '满江红', '陈三聘', '绀浮空，山拥髻、晚来风急。\n吹骤雨、藕花千柄，艳妆新。\n窥鉴粉光犹有泪，凌波罗袜何曾湿。\n讶汉宫、朝罢玉皇归，凝情立。\n尊前恨，歌三叠。\n身外事，轻飞叶。\n怅当年空击，誓江孤楫。\n云色远连平野尽，夕阳偏傍疏林入。\n看月明、冷浸碧琉璃，君须吸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11884, '满江红', '陈三聘', '斜日熔金，三万顷、棹歌齐举。\n风不动、采苹双桨，翠鬟相语。\n月殿欲浮蟾兔魄，海神不放鱼龙舞。\n到今宵、秋气十分清，无今古。\n君试唤，扁舟侣。\n来伴我，潇湘渚。\n共夷犹春浪，笑歌秋浦。\n霸越独高身退後，尘缨未濯人谁许。\n叹酒杯、不到子陵台，刘伶土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11885, '千秋岁', '陈三聘', '当年渔隐，路转桃溪汇。\n流水下，青山外。\n客行花径曲，月上松门对。\n撑艇子，雪中蓑笠亲曾载。\n老去谁倾盖。\n腰瘦频移带。\n人健否，花仍在。\n明年春更好，来向花前醉。\n青鬓改，恁时难拼千金买。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11886, '浣溪沙', '陈三聘', '酒力先从脸晕生。\n粉妆新丽笑相迎。\n晓寒高护彩云轻。\n不语似愁春力浅，有情应恨烛花明。\n更於何处觅倾城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11887, '浣溪沙', '陈三聘', '翠幕遮笼锦一丛。\n尊前初见浅深红。\n淡云和月影葱茏。\n醉态只疑春睡里，啼妆愁听雨声中。\n更烧银烛醉东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11888, '浣溪沙', '陈三聘', '不怕春寒更出游。\n兰桡飞动却惊鸥。\n烟光佳处辄迟留。\n屏曲未曾歌醉梦，眉尖空只锁闲愁。\n从教丝柳绊行舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11889, '浣溪沙', '陈三聘', '越浦潮来信息通。\n吴山不见暮云重。\n人生何事各西东。\n烟外好花红浅淡，雨馀芳草绿葱茏。\n苦无欢意敌春浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11890, '浣溪沙', '陈三聘', '点检尊前花柳丛。\n於中偏占牡丹风。\n等闲言语惯迎逢。\n扇影不摇珠的，钗梁斜玉玲珑。\n梦魂长向楚江东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11891, '浣溪沙', '陈三聘', '不跃银鞍与绣鞯。\n曲筇芒跷见衰年。\n寻幽来立渡头船。\n碧涧芹羹珍下箸，红莲香饭乐归田。\n不妨尊酒兴悠然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11892, '浣溪沙', '陈三聘', '帘押低垂月影疏。\n梅枝和雪玉相扶。\n儿家春信入来无。\n半坠宝钗慵览镜，任偏罗髻却拈书。\n琴心谁与问相如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11893, '朝中措', '陈三聘', '朝来和气满西山。\n拄颊小阑干。\n柳色野塘幽兴，梅花纸帐轻寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11894, '朝中措', '陈三聘', '求田何处是生涯。\n双鬓已先华。\n随分夏凉冬暖，赏心秋月春花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11895, '朝中措', '陈三聘', '去年曾醉杏花坊。\n柳色间轻黄。\n重觅旧时行迹，春风满路梅香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11896, '朝中措', '陈三聘', '草堂春过一分馀。\n幽事酒醒初。\n琴调细鸣焦木，矢声不断铜壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11897, '朝中措', '陈三聘', '秋山横截半湖光。\n湖渚橘枝黄。\n纨扇罢摇蟾影，练衣已怯风凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11898, '蝶恋花', '陈三聘', '阊阖城西山四面。\n鸭绿鳞鳞，轻拍横塘岸。\n一阵东风羊角转。\n望中已觉孤帆远。\n独恨寻芳来较晚。\n柘老桑稠，农务村村遍。\n山鸟劝酤官酒贱。\n炊烟深巷听缫茧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11899, '南柯子・南歌子', '陈三聘', '别後惊人远，归心怯橹柔。\n晚天凉思冷於秋。\n冷浸一溪明月、水弥流。\n醉里狂仍在，吟馀趣极幽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11900, '南柯子・南歌子', '陈三聘', '烟树观前浦，风苹听远洲。\n等闲来上水边楼。\n怅望天涯、何处有归舟。\n香断灯花夜，歌停扇影秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11901, '南柯子・南歌子', '陈三聘', '月傍云头吐，风将雨脚吹。\n夜深乌鹊向南飞。\n应是星娥颦恨、入双眉。\n旧怨垂千古，新欢只片时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11902, '水调歌头', '陈三聘', '玉鉴十分满，清露一年秋。\n漂流踪迹，谁念楚尾与吴头。\n此夜刮明尘眼。\n望极好张诗胆。\n何处有高楼。\n浩荡银潢冷，缥缈白云浮。\n笑劳生，难坎止，亦乘流。\n阑干拍碎，清夜起舞不胜愁。\n万里关河依旧。\n一寸功名乌有。\n清泪滴衣裘。\n老去心空在，归梦绕苹洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11903, '水调歌头', '陈三聘', '有客念行役，劲气凛於秋。\n男儿未老，衔命如虏亦风流。\n决定平戎方略，恢复旧燕封壤，安用割鸿沟。\n莫献肃霜马，好衣白狐裘。\n我何人，怀壮节，但凝愁。\n平生未逢知己，哙伍实堪羞。\n金马文章何在，玉鼎勋庸何有，一笑等云浮。\n拼断好风月，羯鼓打梁州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11904, '西江月', '陈三聘', '诗眼曾逢花面，画图还识春娇。\n当年风格太妖饶。\n粉腻酥柔更好。\n酒晕不温香脸，玉慵犹怯轻绡。\n春风别後又秋高。\n再见只应人老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11905, '西江月', '陈三聘', '春事已浓多日，游人偏盛今年。\n梨花寒食雨馀天。\n鸭绿含风浪浅。\n翠袖半黏飞粉，罗衣尚怯轻寒。\n不辞归路委香钿。\n门外东风如箭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11906, '鹊桥仙', '陈三聘', '银潢仙仗，离多会少，朝暮世情休妒。\n夜深风露洒然秋，又莫是、轻分泪雨。\n云收雾散，漏残更尽，遥想双星情绪。\n凭谁批敕诉天公，待留住、今宵休去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11907, '宜男草', '陈三聘', '摇落丹枫素秋後。\n舞长亭、尚馀衰柳。\n别梦回、忆得霜柑分我，应自有、浓香手。\n宿酲谁解三杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11908, '宜男草', '陈三聘', '绿水黏天净无浪。\n转东风、纹微涨。\n个中趣、莫遣人知，容我日日、扁舟独往。\n平生书癖已无恙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11909, '秦楼月・忆秦娥', '陈三聘', '云衣薄。\n春晴自有东风掠。\n东风掠。\n试听枝上，几声乾鹊。\n曲屏心事新题却。\n离愁何用堆眉角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11910, '秦楼月・忆秦娥', '陈三聘', '花前狭。\n翠茵围坐花阴合。\n花阴合。\n闲情不似，一双狂蝶。\n春沟何处寻红叶。\n春寒料想罗衣怯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11911, '秦楼月・忆秦娥', '陈三聘', '光风薄。\n杨花欲谢春应觉。\n春应觉。\n一庭红叶，粉花吹落。\n冶游无复飞红索。\n凭高独上湖边阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11912, '秦楼月・忆秦娥', '陈三聘', '青楼缺。\n楼心人待黄昏月。\n黄昏月。\n入帘无奈，柳绵吹雪。\n谁人弄笛声呜咽。\n伤春未解丁香结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11913, '秦楼月・忆秦娥', '陈三聘', '青膏集。\n新雷忽起龙蛇蛰。\n龙蛇蛰。\n柳塘风快，水流声急。\n伤心有泪凭谁。\n尊前容易青衫湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11914, '念奴娇', '陈三聘', '浮云吹尽，卷长空、千顷都凝寒碧。\n兔杵无声风露冷，天也应怜人寂。\n故遣娥，驾蟾飞上，玉宇元同色。\n天津何事，此时偏界南北。\n不但对影三人，我歌君和，我舞君须拍。\n涤洗胸中愁万斛，莫问今宵何夕。\n老矣休论，著鞭安用，一笑真狂客。\n夜深归去，烂然溪上阡陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11915, '念奴娇', '陈三聘', '晴风丽日，算东君、坼遍梅心桃萼。\n独有名花开殿後，一笑嫣然如昨。\n黄袂层肤，霞冠高拥，多态春才觉。\n雨巾风帽，故人来趁花约。\n好是罗绮添春，香风环坐，半醉金钗落。\n老去心情难似旧，手拈花枝为乐。\n麝馥萦愁，妆花凝恨，莫惜金荷酌。\n酒阑花睡，梦魂重到京洛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11916, '念奴娇', '陈三聘', '水空高下，望沈沈一色，浑然苍碧。\n天籁不鸣凉有露，金气横秋寂寂。\n玉宇琼楼，望中何处，月到天中极。\n御风归去，不愁衣袂无力。\n此夜飘泊孤篷，短歌谁和，自笑狂踪迹。\n咫尺蓝桥仙路远，云英消息。\n疏影婆娑，恍然身世，我是尊前客。\n一声凄怨，倚楼谁弄长笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11917, '念奴娇', '陈三聘', '馀霞飞绮，望长天、顷刻云容凝碧。\n今夕江皋风力软，明日波心头白。\n客舸东流，语离深夜，遣我新愁积。\n春融花丽，定知天相行色。\n别後一纸乡书，故人相问，好趁秋鸿翼。\n空有佳人千点泪，锦字机中曾织。\n利锁名缰，古今同是，谁失知谁得。\n来朝愁望，旧楼何处西北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11918, '念奴娇', '陈三聘', '扁舟此计，问当年、谁与寻盟鸥鸟。\n许国勋名彝鼎在，风月不妨吟笑。\n碧草台边，红云溪上，寿杖扶诗老。\n水浮天处，未应俗驾曾到。\n盛事埒美知章，鉴湖君赐，宸翰今题号。\n指点飞烟轻霭外，有路直通仙岛。\n蓑笠渔船，琴书客坐，清夜尊倒。\n未须归去，片蟾初上林表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11919, '惜分飞', '陈三聘', '莫唱骊驹容首聚。\n花径重来微步。\n从此朝天去。\n故山怨鹤栖猿侣。\n试卜西园春在否。\n无奈细雨。\n明日长亭路。\n断魂芳草人何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11920, '梦玉人引', '陈三聘', '别来何处，酒醒後，梦难觅。\n晚日溪亭，清晓便挂帆席。\n满载离愁，指去程、还作江南行客。\n目断层城，数迢迢山驿。\n素巾空染，泪痕斑、应是暗中滴。\n记得轻分，玉箫犹自凄咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11921, '梦玉人引', '陈三聘', '倚阑干久，人不见，暮云碧。\n芳草池塘，春梦暗惊诗客。\n昨夜溪梅，向空山、雪里轻匀颜色。\n好赠行人，折枝南枝北。\n雨巾风帽，昔追游、谁念旧踪迹。\n料得疏篱，暗香时度风息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11922, '如梦令', '陈三聘', '红紫不将春住。\n风定更飘无数。\n溪涨绿含风，短艇晚横沙渡。\n归去。\n归去。\n肯念西池鸳鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11923, '如梦令', '陈三聘', '珍重故人相许。\n来向水亭幽处。\n文字间金钗，消尽晚天微暑。\n无雨。\n无雨。\n不比寻常端午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11924, '菩萨蛮', '陈三聘', '筇枝探得梅开了。\n青鞋渐踏江头草。\n日日作东风。\n海棠相次红。\n离多良会少。\n此计应须早。\n莫待作行人。\n却将愁送春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11925, '菩萨蛮', '陈三聘', '春城办得红蕖了。\n红蕖未点春先到。\n新月入新年。\n方才今夜圆。\n云屏谁为隔。\n肠断金钗客。\n好语写春幡。\n都教席上看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11926, '菩萨蛮', '陈三聘', '杨花满院飞红索。\n春光不似人情薄。\n楼阁断霞明。\n梨花开晚晴。\n玉虬香散後。\n扶困三杯酒。\n不是听思归。\n归心思此时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11927, '临江仙', '陈三聘', '夜饮只愁更漏促，留连笑蔷薇。\n歌声缭绕彻帘帏。\n坐中清泪落，梁上暗尘飞。\n重睹舞腰惊束素，不应更褪罗衣。\n别来容易见来稀。\n次公狂已甚，不醉亦忘归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11928, '临江仙', '陈三聘', '白首故人重会面，论交尔汝忘形。\n从今心迹喜双清。\n飞鸿追往事，为蝶笑馀生。\n琥珀杯浓春正好，此怀端为君倾。\n旧时猿鹤敢寒盟。\n鸠居从拙计，鹏翼任高程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11929, '减字木兰花', '陈三聘', '凝云不动。\n玉海无声千丈冻。\n来倚阑干。\n襟袖凭虚彻骨寒。\n归心易折。\n後夜月明应恨别。\n罨画图边。\n著我披蓑上钓船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11930, '减字木兰花', '陈三聘', '东篱黄菊。\n细拈香枝人事熟。\n少缓芳尊。\n且醉侬家麴米春。\n老人斋戒。\n底事新来移角带。\n归梦相关。\n明月松江万顷宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11931, '减字木兰花', '陈三聘', '盈盈袅袅。\n欲问卿卿还好好。\n无奈娇何。\n折折湘裙薄薄罗。\n尊前顾曲。\n舞作回风花拍促。\n压尽时流。\n棋里输伊一百筹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11932, '减字木兰花', '陈三聘', '先生困熟。\n万卷书中聊托宿。\n似怯清寒。\n更都梁向博山。\n游仙梦杳。\n啼鸟声中春又晓。\n未著乌纱。\n独坐溪亭数落花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11933, '减字木兰花', '陈三聘', '殷勤举白。\n昨夜东风犹有雪。\n莫恨春迟。\n曾见梅花第一枝。\n阴晴未决。\n早晚清明新火活。\n梦绕秦楼。\n欲趁归潮上客舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11934, '鹧鸪天', '陈三聘', '酒晕从教上脸丹。\n春愁何事点眉山。\n都将别後深深意，且向尊前细细看。\n多少恨，说应难。\n粉巾空染泪斓斑。\n炉猊筝雁长闲却，明月楼心夜正寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11935, '鹧鸪天', '陈三聘', '指剥春葱去采苹。\n衣丝秋藕不沾尘。\n眼波明处偏宜笑，眉黛愁来也解颦。\n巫峡路，忆行云。\n几番曾梦曲江春。\n相逢细把银照，犹恐今宵梦似真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11936, '鹧鸪天', '陈三聘', '昨夜东风怒不成。\n晓来犹自扫残英。\n半酸梅子连枝重，无力杨花到地轻。\n情易感，涕先零。\n玉虬香冷更凄清。\n事如芳草绵绵远，恨比浮云冉冉生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11937, '鹧鸪天', '陈三聘', '翦碎霜绡巧作团。\n玉纤特地破朝寒。\n疏花好向钗横见，瘦影难敲月堕看。\n将旧恨，入眉弯。\n不须多样缕金。\n当时千点东风泪，怪见妆成粉未乾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11938, '好事近', '陈三聘', '我欲御天风，飞上广寒宫阙。\n撼动一轮秋桂，照人间愁绝。\n归来须著酒消磨，玉面点红缬。\n起舞为君狂醉，更何须邀月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11939, '好事近', '陈三聘', '枝上几多春，数点不融香雪。\n纵有笔头千字，也难夸清绝。\n艳桃李敢争妍，清怨笛中咽。\n试策短筇溪上，看影浮波月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11940, '卜算子', '陈三聘', '雪後竹枝风，醉梦风吹醒。\n瘦立寒阶满地春，淡月梅花影。\n门外辘轳寒，晓汲喧金井。\n长笛何人更倚楼，玉指风前冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11941, '卜算子', '陈三聘', '涧下水声寒，壑底松风静。\n时有清香度竹来，步月寻疏影。\n往事属东风，试问花应省。\n曾是花前把酒人，别梦溪堂冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11942, '三登乐', '陈三聘', '南北相逢，重借问、古今齐楚。\n烛花红、夜阑共语。\n怅六朝兴废，但倚空高树。\n目断帝乡，梦迷雁浦。\n故人疏、梅驿断，音书有数。\n塞鸿归、过来又去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11943, '三登乐', '陈三聘', '注望晓山，晴色丽、晨餐应饱。\n纹平、涨天渺渺。\n倚藤枝、撑艇子，昔游曾到。\n江山自古，水云转好。\n怅年来、心纵在，盟寒鸥鸟。\n故人中、黑头渐少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11944, '三登乐', '陈三聘', '久蛰群虬，犹未肆、新雷初启。\n鼓东风、雨膏为洗。\n望横塘、越溪路，石湖烟水。\n西接洞庭，下连甫里。\n忆当年、归计早，扁舟从此。\n祖清风、相门有几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11945, '三登乐', '陈三聘', '一品归来，强健日、小园幽圃。\n扁舟兴、恐天未许。\n想当年、持汉节，众齐咻楚。\n丹忠此日，盛名千古。\n词章、师海内，纬文经武。\n莫寒盟、故山旧侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11946, '浪淘沙', '陈三聘', '风雨晚春天。\n芳兴慵悭。\n浅红稠绿满园间。\n独有梨花三四朵，留住春寒。\n年少跃金鞍。\n咫尺关山。\n倦飞如我已知还。\n洒向东风千点泪，衣上重看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11947, '虞美人', '陈三聘', '融融睡觉东风息。\n行到溪亭侧。\n一枝梅玉似人人。\n索笑依然消瘦、不禁春。\n相逢试问情多少。\n应怪山翁老。\n翠罗高护结花邻。\n一任馀芳争学、捧心颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11948, '虞美人', '陈三聘', '天公意向人情满。\n灯月教同看。\n中秋虽是十分明。\n不比今宵处处、有华灯。\n艳桃李歌阑後。\n更醉青楼酒。\n不妨饮尽玉东西。\n横笛声中春色、要君知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11949, '虞美人', '陈三聘', '飞琼晓压梅枝重。\n酒面羊羔冻。\n谁将缟带逐车翻。\n明月秦楼昨夜、不胜寒。\n何须卷起重帘幕。\n愁怕春罗薄。\n玉杯持劝醉厌厌。\n无奈有人笼袖、出香尖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11950, '虞美人', '陈三聘', '乾红翦碎烦纤玉。\n相并黄金粟。\n汉宫素面说明妃。\n马上秋风应解、著燕支。\n黄昏小树堪愁绝。\n不比梅花月。\n满天风露透肌凉。\n插取双枝归去、是谁香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11951, '醉落魄・一斛珠', '陈三聘', '东风寒绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11952, '眼儿媚', '陈三聘', '酸。\n何人为我，丁宁驿使，来到江干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11953, '水调歌头', '石孝友', '君恩九鼎重，臣命一毫轻。\n出身事主，刚甚须作不平鸣。\n老却西山薇蕨，闲损南窗松菊，羞死汉公卿。\n豺狼敢横道，草木要知名。\n秋已素，人又去，若为情。\n长沙何在，风送呜咽暮潮声。\n举棹却寻归路，挥麈莫谈时事，得酒且频倾。\n一片古时月，千里伴君行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11954, '宝鼎现', '石孝友', '雪梅清瘦，月桂圆冷，天街新霁。\n想帝辇、三朝薄暮，催促烛龙开扇雉。\n正拜舞、捧玉卮为寿，花满香铺凤髓。\n罄禹穴、胥涛万顷，春入南山声里。\n鼎轴元老诗书帅。\n体宸衷、双奉亲意。\n勤色养、行春惜花，夜欢宴、瑶池衣彩戏。\n鼓淑气、遍湖山千里。\n惊破悭红涩翠。\n笑那个痴儿无赖。\n打得金鱼坠地。\n休念太守当年，曾手把青藜照字。\n对珠帘云栋，收拾太平歌舞辍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11955, '眼儿媚', '石孝友', '何须著粉更施朱。\n元不在妆梳。\n寻常结束，珊珊环佩，短短裙襦。\n花羞柳妒空撩乱，冰雪做肌肤。\n而今便好，小名弄玉，小字琼奴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11956, '眼儿媚', '石孝友', '愁云淡淡雨潇潇。\n暮暮复朝朝。\n别来应是，眉峰翠减，腕玉香销。\n小轩独坐相思处，情绪好无聊。\n一丛萱草，几竿修竹，数叶芭蕉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11957, '临江仙', '石孝友', '一霎狂云惊雨过，月华恰到帘帷。\n槛前叠石翠参差。\n洞房相见处，灯火乍凉时。\n睡玉眠花愁夜短，匆匆共惜佳期。\n风梧不动酒醒迟。\n好同蝴蝶梦，飞上凤皇枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11958, '临江仙', '石孝友', '醉袖吟鞭行色里，帽檐低处风斜。\n晚山一半被云遮。\n残阳明远水，古木集栖鸦。\n暮去朝来缘底事，不如早早还家。\n曲屏深幌小窗纱。\n翠沾眉上柳，红脸边花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11959, '临江仙', '石孝友', '买笑当歌何处好，小楼四面江山。\n玉梅枝上卸馀寒。\n雨随春到急，风向晚来颠。\n任自腰围都瘦损，肯教欢意阑珊。\n引杯相属莫留残。\n花如人竞好，人与月争圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11960, '临江仙', '石孝友', '枕上莺声初破睡，峭寒轻透帘帏。\n起来惆怅有谁知。\n雨狂风转急，揉损好花枝。\n薄幸别来春又老，等闲误却佳期。\n斜阳影里立多时。\n远山何事□，相对蹙修眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11961, '临江仙', '石孝友', '常记梦云楼上住，残灯影里迟留。\n依稀绿惨更红羞。\n露痕双脸泪，山样两眉愁。\n数片轻帆天际去，云涛烟浪悠悠。\n今宵独宿古江头。\n水腥鱼菜市，风碎荻花洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11962, '鹧鸪天', '石孝友', '收拾眉尖眼尾情。\n当筵相见便相亲。\n偷传翡翠歌中意，暗合鸳鸯梦里身。\n云态度，月精神。\n月流云散两无情。\n觉来一枕凄凉恨，不敢分明说向人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11963, '鹧鸪天', '石孝友', '收拾眉尖眼尾情。\n夜来真个梦倾城。\n鸳鸯有底情难尽，蝴蝶无端梦易惊。\n愁一掬，月三更。\n绣帏应好睡轻盈。\n知他莫有相怜分，展转寻思直到明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11964, '鹧鸪天', '石孝友', '别後应怜信息疏。\n西风几度到庭梧。\n夜来纵有鸳鸯梦，春去空馀蛱蝶图。\n烟树远，塞鸿孤。\n垂垂天影带平芜。\n凭谁写此相思曲，寄与冯川郑小奴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11965, '鹧鸪天', '石孝友', '家在东湖湖上头。\n别来风月为谁留。\n落霞孤鹜齐飞处，南浦西山相对愁。\n真了了，好休休。\n莫教辜负菊花秋。\n浮云富贵何须羡，画饼声名肯浪求。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11966, '鹧鸪天', '石孝友', '花漏声乾月隐墙。\n灰迎晓透新阳。\n物情渐逐云容好，欢意偏随日脚长。\n山作鼎，玉为浆。\n寿杯丛处艳梅妆。\n醉乡路接华胥国，应梦朝天侍赭黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11967, '鹧鸪天', '石孝友', '玉烛调元黍律匀。\n迎长嘉节属芳辰。\n云如惜雨钩牵雪，梅不禁风漏泄春。\n天意好，物华新。\n偷闲赢取酒边身。\n太平朝野都无事，且与莺花作主人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11968, '鹧鸪天', '石孝友', '一夜冰澌满玉壶。\n五更喜气动洪炉。\n门前桃李知麟集，庭下芝兰看鲤趋。\n泉脉动，草心苏。\n日长添得绣工夫。\n试询补衮弥缝手，真个曾添一线无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11969, '鹧鸪天', '石孝友', '一别音尘两杳然。\n不堪虚度菊花天。\n惊秋远雁横斜字，噪晚哀蝉断续弦。\n好将息，恶姻缘。\n凉宵如水复如年。\n梦魂不怕风波险，飞过江西阿那边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11970, '鹧鸪天', '石孝友', '屏障重重翠幕遮。\n兰膏烟暖篆香斜。\n相思树上双栖翼，连理枝头并蒂花。\n凤髻，乌纱。\n云慵雨困兴无涯。\n个中赢取平生事，兔走乌飞一任他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11971, '卜算子', '石孝友', '人自蕊宫来，微步香云拥。\n小试樽前白雪歌，叶叶秋声动。\n一剪艳波横，两点愁山重。\n收拾眉尖眼尾情，作个鸳鸯梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11972, '卜算子', '石孝友', '见也如何暮。\n别也如何遽。\n别也应难见也难，後会难凭据。\n去也如何去。\n住也如何住。\n住也应难去也难，此际难分付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11973, '卜算子', '石孝友', '折得月中枝，坐惜青春老。\n及至归来能几时，又踏关山道。\n满眼秋光好。\n相见应须早。\n若趁重阳不到家，只怕黄花笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11974, '卜算子', '石孝友', '冷蕊红香，瘦节攒苍玉。\n更著堂堂十八翁，取友三人足。\n惜此岁寒姿，移向屏山曲。\n纸帐熏炉结胜缘，故伴仙郎宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11975, '鹧鸪天', '石孝友', '露叶披残露颗传。\n明星著地月流天。\n不辞独赏穷今夜，应为相逢忆去年。\n辜窈窕，负蝉娟。\n谁知两处照孤眠。\n娥不怕离人怨，有甚心情独自圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11976, '鹧鸪天', '石孝友', '万里羁孤困一箪。\n平头四十误儒冠。\n舜弦广播薰风暖，邹律潜消黍谷寒。\n楼谩倚，剑休弹。\n看君行复上金銮。\n凤池波里求馀润，肆泥中岂久蟠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11977, '渔家傲', '石孝友', '射虎将军搴绣帽。\n西园公子南山豹。\n共跨龙媒衔凤沼。\n风色好。\n宫花御柳迎人笑。\n剑履醒醒天日表。\n集英殿下春来早。\n双鹗盘空擎百鸟。\n归来了。\n蓝袍锦水光相照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11978, '渔家傲', '石孝友', '夜半潮声来枕上。\n击残梦破惊魂荡。\n见说钱塘雄气象。\n披衣望。\n碧波堆里排银浪。\n月影徘徊天漾。\n金戈铁马森相向。\n洗尽尘根磨业障。\n增豪放。\n从公笔力诗词壮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11979, '洞仙歌', '石孝友', '芙蓉院宇，露下秋容瘦。\n龟鹤仙人献长寿。\n问蓬山别後，几度春归，归去晚，开得蟠桃厮勾。\n人间游戏好，鲸背风高，那更相将凤雏九。\n事苹蘩，工翰墨，才德兼全，人总道、古今稀有。\n尽从他、乌兔促年华，看绿鬓朱颜，镇长依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11980, '念奴娇', '石孝友', '半千宝运，瑞清朝、诞育人间英物。\n暖律吹灰春到也，迟日光腾东壁。\n婺女双溪，沈郎八咏，辉映皆冰雪。\n储精毓秀，几年一个人杰。\n须信和气随人，粉梅欺黛柳，娇春争发。\n翠幕重重称寿处，莲炬蕙烟明灭。\n鼎席犹虚，九重频念此，衮衣华发。\n明年今夜，凤池应醉花月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11981, '念奴娇', '石孝友', '闷红颦翠，惜流年、忍对艳阳时节。\n白玉楼成人去後，两地音尘都绝。\n鸾鉴分飞，梦云零乱，欢意今衰飒。\n墨痕红淡，忆曾题遍红叶。\n须信後约难凭，臂啮鬟剪，也只成虚说。\n满眼凄凉无限事，付与丁香愁结。\n欲语情酸，临岐步懒，怅望兰舟发。\n出门谁伴，泪昏一片孤月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11982, '念奴娇', '石孝友', '平湖阁上，正残虹挂雨，微云擎月。\n万顷琉璃秋向冷，忍便翠销红歇。\n北海樽，西园游宴，兴逸湖山发。\n飞尘不到，坐移蓬岛珠阙。\n莫厌笑口频开，少年行乐事，转头胡越。\n公子多情真爱客，敢惮深杯百罚。\n太一舟轻，芙蓉城锁，醉指神仙窟。\n乘风归去，尽教吹乱华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11983, '念奴娇', '石孝友', '平湖阁上，正雌霓将卷，雄风初发。\n醉倚危栏吟眺处，月在篷莱溟渤。\n蓬叶香浮，桂华光放，翻动蛟鼍窟。\n踏轮谁信，宓妃曾借尘袜。\n人世景物堪悲，等闲都换了，朱颜云发。\n遥想广寒秋到早，闲著几多空阔。\n太白诗魂，玉川风腋，自有飞仙骨。\n嫦娥为伴，夜深同驾霜月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11984, '念奴娇', '石孝友', '麦秋天气，正玉杓斡暑，熏弦鸣律。\n浴佛生朝初过也，还数佳辰三日。\n筮水呈祥，梦熊叶庆，宝运符千一。\n太平朝野，异人端为时出。\n须信家世蝉联，乃翁遗范在，子孙逢吉。\n雾隐巢云聊寄傲，行矣飞英腾实。\n瀑布泉清，炉峰气秀，光映霞觞溢。\n萱堂争看，彩衣红堕双橘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11985, '醉落魄・一斛珠', '石孝友', '友莺梦蝶。\n寻花问柳深相结。\n教春去後群芳歇。\n零落朋游，辜负好时节。\n眼边愁绪多于发。\n迢迢一水通吴越。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11986, '醉落魄・一斛珠', '石孝友', '鸾孤凤只。\n而今怎忍轻抛掷。\n知他别後谁怜惜。\n一味惶，辜负我思忆。\n云山万叠烟波急。\n短书频寄征鸿翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11987, '醉落魄・一斛珠', '石孝友', '空庭草积。\n吹花风去春无迹。\n锁鸾深处应相忆。\n红染罗巾，颦损眉山碧。\n曲屏尘暗双。\n醉衾不暖炉烟湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11988, '醉落魄・一斛珠', '石孝友', '红娇翠弱。\n怨人珠泪频偷落。\n归期莫负青笺约。\n雨断云销，总是初情薄。\n夜深秋气生帘幕。\n半衾依旧空闲却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11989, '丑奴儿・采桑子', '石孝友', '凌花镜里桃花笑，清影团团。\n月淡风寒。\n深夜移灯许细观。\n武陵溪上当时事，何处飞鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11990, '西江月', '石孝友', '歌彻秋娘金缕，醉扳织女云车。\n而今谁复荐相如。\n拔剑茫然四顾。\n好景凭诗断送，闲愁著酒消除。\n镜中丝发莫惊呼。\n春满珠帘绣户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11991, '西江月', '石孝友', '脉脉无端心事，厌厌不奈春酲。\n越罗衫薄峭寒轻。\n试问几番花信。\n万点风头柳絮，数声柳外啼莺。\n斜阳还傍小窗明。\n门掩黄昏人静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11992, '鹧鸪天', '石孝友', '六十仙翁抱桂栽。\n果符吉梦诞英才。\n上天与降麒麟种。\n明月还生蚌蛤胎。\n华阁启，玳筵开。\n快呼玉手捧金。\n要知远地无功客，曾到高门作贺来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11993, '踏莎行', '石孝友', '沈水销红，屏山掩素。\n锁窗醉枕惊眠处。\n芰荷香里散秋风，芭蕉叶上鸣秋雨。\n飞阁愁登，倚阑凝伫。\n孤鸿影没江天暮。\n行云懒寄好音来，断云暗逐斜阳去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11994, '望海潮', '石孝友', '离情冰泮，归心云扰，黯然凝伫江皋。\n柳色摇金，梅香弄粉，依稀满眼春娇。\n常记极游遨。\n更与持玉，因解金貂。\n郎去翟塘，妾家巫峡水迢迢。\n别来暗减风标。\n奈碧云暗断，翠被香消。\n春草生池，芳尘凝榭，凄凉月夕花朝。\n千里梦魂劳。\n但鸟啼渡口，猿响山椒。\n拟把无穷幽恨，万叠写霜绡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11995, '虞美人', '石孝友', '醉寻芳草城头路。\n底事频凝伫。\n丽谯直下小层楼。\n鸳瓦重重匀砌、几重愁。\n睡红颦翠春风面。\n咫尺无由见。\n从教笑语落檐楹。\n图得香闺依约、认郎声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11996, '虞美人', '石孝友', '月娥弄影当窗照。\n疑是巫山晓。\n芙蓉帐里睡魂惊。\n浅拂轻匀犹恐、已天明。\n高楼未放梅花弄。\n却就鸳衾拥。\n舞腰纤瘦不禁春。\n姿意任郎撩乱、一梳云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11997, '水龙吟', '石孝友', '旧游曾记当年，凤城雨露开晴昼。\n端门发钥，御炉烟暗，宫花影覆。\n帝念民劳，俾乘轺传，暂临牛斗。\n散阳和四照，春光万井，来小试、调元手。\n职业才华竞秀。\n汉廷臣、无出其右。\n九重眷倚，频虚槐鼎，争迎衮绣。\n爽气西山，绿波南浦，酿成芳酒。\n趁锋车未到，霞觞共祝，百千长寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11998, '长相思', '石孝友', '你又痴。\n我又迷。\n到此痴迷两为谁。\n问天天怎知。\n长相思。\n极相思。\n愿得姻缘未尽时。\n今生重共伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (11999, '长相思', '石孝友', '红依稀。\n绿依稀。\n寒勒花梢开较迟。\n蝶魂空自迷。\n怕人疑。\n使人疑。\n人道闲愁想未知。\n歌眉因甚低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12000, '长相思', '石孝友', '蝶团飞。\n莺乱啼。\n陌上花开人未归。\n碧台歌舞稀。\n月入扉。\n风满帷。\n坐到黄昏人静时。\n清愁君不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12001, '长相思', '石孝友', '树槎牙。\n冰交加。\n冷艳疏疏瘦影斜。\n几枝梅花放。\n天一涯。\n语三叉。\n已是情多怨物华。\n那堪更忆家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12002, '品令', '石孝友', '困无力。\n几度偎人，翠颦红湿。\n低低问、几时麽，道不远、三五日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12003, '点绛唇', '石孝友', '霁景澄秋，晚风吹尽朝来雨。\n夕阳烟树。\n万里山光暮。\n一带长川，自在流今古。\n人何处。\n月波横素。\n冷浸蒹葭浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12004, '点绛唇', '石孝友', '缓解罗裳，十分鸳履低腰素。\n冰香微度。\n一罅殷红露。\n风折芳莲，影落盆池去。\n多羞处。\n怕人偷觑。\n粉面频回顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12005, '点绛唇', '石孝友', '著意栽银，砌成叶叶莲花舫。\n醉霞摇荡。\n恰似凌波样。\n自笑平生，鲸吸洪波量。\n孤心赏。\n不如深幌。\n一搦酬千想。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12006, '点绛唇', '石孝友', '杨柳腰枝，春来尚怯铢衣重。\n眼波偷送。\n笑把花枝弄。\n雨帐云屏，一枕高唐梦。\n春情动。\n人娇纵。\n困钗横凤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12007, '点绛唇', '石孝友', '醉倚危墙，望中归思生天际。\n山腰渚尾。\n几簇渔樵市。\n帆落西风，一段芦花水。\n八千里。\n锦书欲寄。\n新雁曾来未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12008, '点绛唇', '石孝友', '日薄风迟，柳眠无力花枝妥。\n燕楼空锁。\n好梦谁惊破。\n寒食清明，又等闲都过。\n愁无那。\n泪珠频堕。\n洒尽相思颗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12009, '玉楼春', '石孝友', '小桃破尽风前萼。\n草草年华闲过却。\n十分清瘦有谁知，一点相思无处著。\n书凭雁字应难托。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12010, '玉楼春', '石孝友', '春生泽国芳菲早。\n楼外墙阴闻语笑。\n东君著意到西园，点破施朱浑未了。\n楚云暮合吴天杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12011, '玉楼春', '石孝友', '风光澹沲云容粹。\n点染园林添况味。\n花间照夜簇红纱，柳外踏青摇彩旆。\n芳时不分空憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12012, '玉楼春', '石孝友', '扁舟破浪鸣双橹。\n岁晚客心分万绪。\n香红漠漠落梅村，愁碧萋萋芳草渡。\n汉皋失诚相误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12013, '玉楼春', '石孝友', '井花暖处新阳动。\n节物撩人添倥偬。\n寒齑冰齿晕轻澌，败絮粟肌悭短梦。\n文章彻了成何用。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12014, '玉楼春', '石孝友', '汉皇受禅新尧统。\n沼跃潜鱼仪舞凤。\n五云色备观台书，万世功成贤相用。\n江湖襟带蛮荆控。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12015, '玉楼春', '石孝友', '一阳不受群阴壅。\n残历行间冬破仲。\n云低吹白腊寒浓，梅小绽红春意重。\n湖山千里勤飞控。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12016, '玉楼春', '石孝友', '黄锺应律扶炎统。\n舜日迎长佳节用。\n娟娟芳意著花梢，盎盎暖香浮酒瓮。\n寿觞唤取纤纤捧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12017, '玉楼春', '石孝友', '台门瑞霭光阳动。\n人语鼓声沈汹汹。\n观风堂迥暗香飘，卷雨楼前寒翠拥。\n锋车促入承天宠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12018, '西地锦', '石孝友', '回望玉楼金阙。\n正水遮山隔。\n风儿又起，雨儿又煞，好愁人天色。\n两岸荻花枫叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12019, '朝中措', '石孝友', '乱山叠叠水泠泠。\n南北短长亭。\n客路如天杳杳，归心能地宁宁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12020, '阮郎归', '石孝友', '烛花吹尽篆烟青。\n长波拍枕鸣。\n西风吹断雁鸿声。\n离人梦暗惊。\n乡思动，旅愁生。\n谁知此夜情。\n乱山重叠拥孤城。\n空江月自明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12021, '满江红', '石孝友', '雁阵惊寒，故唤起、离愁万斛。\n因追念、镜鸾易破，凤弦难续。\n诗句已凭红叶去，梦魂未断黄粱熟。\n叹浪萍、风梗又天涯，成幽独。\n归来引，相思曲。\n尘满把，泪盈掬。\n对长天远水，落霞孤骛。\n立尽西风无好意，遥山也学双眉蹙。\n恨草根、不逐鬓根摧，秋更绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12022, '浪淘沙', '石孝友', '好恨这风儿。\n催俺分离。\n船儿吹得去如飞。\n因甚眉儿吹不展，叵耐风儿。\n不是这船儿。\n载起相思。\n船儿若念我孤。\n载取人人篷底睡，感谢风儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12023, '胜胜慢・声声慢', '石孝友', '花前月下，好景良辰，厮守日许多时。\n正美之间，何事便有轻离。\n无端珠泪暗簌，染征衫、点点红滋。\n最苦是、□殷勤密约，做造相思。\n咿哑橹声离岸，魂断处，高城隐隐天涯。\n万水千山，一去定失花期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12024, '忆秦娥', '石孝友', '秦楼月。\n秦娥本是秦宫客。\n秦宫客。\n梦云风韵，借仙标格。\n相从无计不如休，如今去也空相忆。\n空相忆。\n尊前欢笑，梦中寻觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12025, '菩萨蛮', '石孝友', '酒浓花艳秋波滑。\n舞馀腰素花枝活。\n相见又还休。\n不禁归去愁。\n醉衾成独拥。\n月冷知霜重。\n早是梦难成。\n梅花肠断声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12026, '菩萨蛮', '石孝友', '雪香白尽江南陇。\n暖风绿到池塘梦。\n叠影上檐明。\n夜潮春水生。\n踏青何处去。\n杨柳桥边路。\n不见浣花人。\n汀洲空白苹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12027, '菩萨蛮', '石孝友', '花销玉瘦斜平薄。\n舞衣宽尽腰如削。\n困甚不胜娇。\n乌云横鬓翘。\n双蛾颦浅黛。\n鸾镜愁空对。\n罗袖晚香寒。\n泪珠和粉弹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12028, '惜奴娇', '石孝友', '我已多情，更撞著、多情底你。\n把一心、十分向你。\n尽他们，劣心肠、偏有你。\n共你。\n风了人、只为个你。\n宿世冤家，百忙里、方知你。\n没前程、阿谁似你。\n坏却才名，到如今、都因你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12029, '惜奴娇', '石孝友', '合下相逢，算鬼病、须沾惹。\n闲深里、做场话霸。\n负我看承，枉驼我、许多时价。\n冤家。\n你教我、如何割舍。\n苦苦孜孜，独自个、空嗟呀。\n使心肠、捉他不下。\n你试思量，亮从前、说风话。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12030, '江城子', '石孝友', '青青杨柳水边桥。\n水迢迢。\n柳摇摇。\n缓引离觞，频驻木兰桡。\n我是行人君是客，俱有恨，总无聊。\n冰澌波暖数琼瑶。\n舞情飙。\n拂春潮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12031, '江城子', '石孝友', '相逢执手也踟蹰。\n立斯须。\n话区区。\n借问来时，曾见那人无。\n忍泪啼痕香不减，虽少别，忍轻辜。\n霜风摇落岁将徂。\n景凋疏。\n恨萦纡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12032, '如梦令', '石孝友', '照水粉梅开尽。\n春残峭寒犹甚。\n秋气著人衣，斗帐玉儿生晕。\n那更。\n那更。\n帘外月斜风横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12033, '如梦令', '石孝友', '风猎乱香如扫。\n又是粉梅开了。\n庭户锁残寒，梦断池塘春草。\n情悄。\n情悄。\n帘外数声啼鸟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12034, '如梦令', '石孝友', '折寄陇头春信。\n香浅绿柔红嫩。\n插向鬓云边，添得几多风韵。\n但问。\n但问。\n管与玉容相称。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12035, '亭前柳', '石孝友', '有件遮，算好事、大家都知。\n被新冤家矍索後，没别底，似别底也难为。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12036, '好事近', '石孝友', '幸自得人情，只是有些脾鳖。\n引杀俺时直甚，损我儿阴德。\n情知守定没乾休，乾休冤俺急。\n今夜这回除是，有翅儿飞得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12037, '夜行船', '石孝友', '昨日特承传诲。\n欲相见、奈何无计。\n这场烦恼捻著嚎，晓夜价、求天祝地。\n教俺两下不存济。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12038, '夜行船', '石孝友', '漏水迢迢清夜。\n露华浓、洞房寒乍。\n愁人早是不成眠，奈无端、月窥窗罅。\n心心念念都绿那。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12039, '茶瓶儿', '石孝友', '相对盈盈一水。\n多声价、开名得字。\n刚能见也还抛弃。\n负了万红千翠。\n留无计。\n来无计。\n□□□、成何况味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12040, '西江月', '石孝友', '拽尽风流露布，筑成烦恼根基。\n早知恁地浅情时。\n枉了教人恁地。\n惜你十分就，把人一味禁持。\n这回断了更相思。\n比似人间没你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12041, '望海潮', '石孝友', '云龙双辅，匣龙双起，当年楚尾吴头。\n借月命卿，占星分使，来宽俗瘵君忧。\n绣指屈儒流。\n□暂辍北阙，小试南州。\n协奏熏风，霈为霖雨岁登秋。\n春工点缀芳柔。\n正梅凝笑脸，柳弄青眸。\n柏叶荐觞，椒花载颂，休辞秉烛嬉游。\n乃眷在宸旒。\n更德标银管，名覆金瓯。\n共看朝天露稳，归拜富民侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12042, '清平乐', '石孝友', '恼花风雨。\n断送春将暮。\n底死留春春不住。\n那更送春归去。\n今朝且赋归与。\n明年春满皇都。\n共泛桃花锦浪，与君同醉西湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12043, '清平乐', '石孝友', '天涯重九。\n独对黄花酒。\n醉拈黄花和泪嗅。\n忆得去年携手。\n去年同醉流霞。\n醉中折尽黄花。\n还是黄花时候，去年人在天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12044, '清平乐', '石孝友', '见时怜惜。\n不见时思忆。\n花柳光阴都瞬息。\n□把光阴虚掷。\n才郎妾貌相当。\n有些似欠商量。\n看你憎模样，更须著我心肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12045, '清平乐', '石孝友', '醉红宿翠。\n髻乌云坠。\n管是夜来不得睡。\n那更今朝早起。\n春风满搦腰枝。\n阶前小立多时。\n恰恨一番雨过，想应湿透鞋儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12046, '清平乐', '石孝友', '山明水嫩。\n潇洒桐庐郡。\n极目风烟无限景。\n说也如何得尽。\n自怜俗状尘容。\n几年断梗飘蓬。\n借使严陵知道，祗应笑问东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12047, '清平乐', '石孝友', '霁光摇目。\n春入郊原绿。\n残雪压枝堆烂玉。\n时闻枝间蔌蔌。\n瘦藤细履平沙。\n醉中一任欹斜。\n落日数声啼鸟，香风满路梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12048, '一翦梅', '石孝友', '萍水相逢无定居。\n同在他乡，又问征途。\n离歌声里客心孤。\n花尽园林，水满江湖。\n烟树微茫带岸蒲。\n何处长沙，何处洪都。\n要知安稳到家无。\n千里征鸿，一纸来书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12049, '浣溪沙', '石孝友', '宿醉离愁慢髻鬟。\n绿残红豆忆前欢。\n锦江春水寄书难。\n红袖时笼金鸭暖，小楼吹彻玉笙寒。\n为谁和泪倚阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12050, '浣溪沙', '石孝友', '柳岸梅溪春又生。\n风枝斜里雪枝横。\n空牵归兴惹离情。\n灰尽寸心犹自热，泪承双睫不能晴。\n梦云楼隔豫章城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12051, '浣溪沙', '石孝友', '迎客西来送客行。\n堆堆历历短长亭。\n人残酒不能醒。\n烟染暮山浮紫翠，霜凋秋叶复丹青。\n凭谁图写入银屏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12052, '浣溪沙', '石孝友', '几曲屏山数幅波。\n雁声斜带夕阳过。\n卸帆聊醉菊花坡。\n旅枕梦魂归路远，秋江风紧夜寒多。\n薄情还解忆人麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12053, '谒金门', '石孝友', '归不去。\n归去又还春暮。\n洞里小桃音信阻。\n几番风更雨。\n相伴竹筇芒履。\n穿尽松溪花坞。\n早是行人贪道路。\n声声闻杜宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12054, '谒金门', '石孝友', '云树直。\n雨歇半空犹湿。\n山影插尖高几尺。\n依依衔落日。\n远岸双飞。\n一水无情自碧。\n飒飒白苹风正急。\n断肠人独立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12055, '谒金门', '石孝友', '春睡重。\n睡起烟销鸾凤。\n著雨柳绵吹易动。\n风帘花影弄。\n过雁空劳目送。\n纵有音书何用。\n有意相思无意共。\n不如休做梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12056, '谒金门', '石孝友', '风又雨。\n断送残春归去。\n人面桃花在何处。\n绿阴空满路。\n立马垂杨官渡。\n一寸柔肠万缕。\n回首碧云迷洞府。\n杜鹃啼日暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12057, '谒金门', '石孝友', '山雨绝。\n山重冷如冰雪。\n窗外芭蕉三两叶。\n影排窗上月。\n醉枕惊回蝴蝶。\n好梦无人共说。\n心事悠悠芳草歇。\n不眠听鼠啮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12058, '水调歌头', '石孝友', '清霜洗空阔，黍管吹秋灰。\n七馀翠，半月流素影徘徊。\n天遣蟠根仙李，世折一枝丹桂，积庆到云来。\n风骨峭冰玉，谈辩屑琼瑰。\n黄阁老，金闺彦，谪仙才。\n小分铜竹，遍洒雨露楚江隈。\n好把萧滩玉笥，变作嘉肴芳酒，为寿莫停杯。\n飞诏下霄汉，调鼎待盐梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12059, '水调歌头', '石孝友', '萧滩韵环佩，玉笥灿玲珑。\n仙原积庆，当日占梦兆维熊。\n学业肯先歆向，文焰已高白贺，飞步更蟾宫。\n秀色溢眉宇，雄辩倒心胸。\n作儿戏，为亲寿，捧霞锺。\n彩衣摇曳，光映怀橘堕双红。\n正好平分风月，且伴能言桃李，鲸吸海涛洪。\n行赴紫泥诏，归拜黑头公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12060, '水调歌头', '石孝友', '男儿四方志，岂久困泥沙。\n束书匣剑，依旧旅食在京华。\n蹭蹬青云未遂，奔走红尘何计，敛袂且还家。\n草木渐黄落，风月正清嘉。\n友猿鹤，宅丘壑，乐生涯。\n几时雷雨，轰磕平地起龙蛇。\n尺可鞭夷狄，寸舌可盂社稷，无路踏云车。\n今古万千事，洒泪向黄花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12061, '水调歌头', '石孝友', '美人在何许，相望正悠悠。\n云窗雾阖，遥想宛在海中洲。\n空对残云冷雨，何限重山叠水，一梦到无由。\n遗怨写红叶，薄幸记青楼。\n金乌掷，玉蟾缺，物华休。\n凤梧眢井，一夜风露各惊秋。\n唯有远山无赖，淡扫一眉晴绿，特地向人愁。\n敛袂且归去，回首谩迟留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12062, '水调歌头', '石孝友', '高情邈云汉，长揖谢君侯。\n脱遗轩冕，簸弄泉石下清幽。\n心契匡庐猿鹤，泪染固陵松柏，一衲且蒙头。\n风月感平发，魂梦绕神州。\n漾一叶，横孤管，去来休。\n琵琶亭畔，正是风叶荻花秋。\n点检诗囊酒碗，抬贴舞歌扇，收尽两眉愁。\n回望碧云合，相伴赤松游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12063, '杏花天', '石孝友', '把杯莫唱阳关曲。\n行客去、居人恨局。\n屏山似展江如簇。\n不见尊前醉玉。\n鹃啼处、怨声裂竹。\n问後夜、兰舟那宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12064, '南歌子', '石孝友', '蚁酒浮明月，鲸波泛落星。\n春花秋叶几飘零。\n只有庐山君眼、向人青。\n明日非今日，长亭更短亭。\n不辞一饮尽双瓶。\n争奈秋风江口、酒初醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12065, '南歌子', '石孝友', '草色裙腰展，冰容水镜开。\n又还春事破寒来。\n一夜东风吹绽、後园梅。\n糯瓮香酿，熏炉续麝煤。\n休惊节物暗相催。\n赢取大家沈醉、探春杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12066, '南歌子', '石孝友', '凤髻斜分翠，鸳鞋小砑红。\n东君著意绮罗丛。\n最好一枝特地、怨春风。\n懊恨无情语，娇羞忍笑容。\n相看疑是梦魂中。\n怕逐飞云归去、断行踪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12067, '南歌子', '石孝友', '畴昔飞鸾侣，而今断雁行。\n西风岭外下斜阳。\n无赖一钩新月、挂人肠。\n双泪沾襟袖，孤灯对客床。\n枕馀衾剩只残香。\n别得娇痴不睡、也思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12068, '南歌子', '石孝友', '春浅梅红小，山寒岚翠薄。\n斜风吹雨入帘幕。\n梦觉南楼呜咽、数声角。\n歌酒工夫懒，别离情绪恶。\n舞衫宽尽不堪著。\n若比那回相见、更消削。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12069, '南歌子', '石孝友', '乱絮飘晴雪，残花绣地衣。\n西园歌舞骤然稀。\n只有多情蝴蝶、作团飞。\n旧事深琴怨，新愁减带围。\n倚楼凝望更依依。\n怕见一天风雨、卷春归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12070, '武陵春', '石孝友', '走去走来三百里，五日以为期。\n六日归时已是疑。\n应是望归时。\n鞭个马儿归去也，心急马行迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12071, '好事近', '石孝友', '微雨洒芳尘，酝造可人春色。\n闻道梦云楼外，正小桃花发。\n殷勤留取最繁枝，樽前待闲折。\n准拟乱红深处，化一双蝴蝶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12072, '减字木兰花', '石孝友', '新荷小小。\n比目鱼儿翻翠藻。\n小小新荷。\n点破清光景趣多。\n青青半卷。\n一寸芳心浑未展。\n待得园时。\n罩定鸳鸯一对儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12073, '减字木兰花', '石孝友', '空阶雨过。\n细草摇摇光入座。\n斜日多情。\n恋恋幽窗故故明。\n沈吟无语。\n立遍梧桐庭下树。\n病叶先秋。\n零乱风前片段愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12074, '减字木兰花', '石孝友', '角声催晓。\n斗帐美人初梦觉。\n黛浅妆残。\n清瘦花枝不奈寒。\n匆匆睡起。\n冷落馀香栖翠被。\n何处阳台。\n雨散云收犹未来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12075, '柳梢青', '石孝友', '云髻盘鸦。\n眉山远翠，脸晕微霞。\n燕子泥香，鹅儿酒暖，曾见来那。\n秋光已著黄花。\n又恰恨、尊前见他。\n越样风流，恼人情意，真个冤家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12076, '乌夜啼', '石孝友', '潇湘雨打船篷。\n别离中。\n愁见拍天沧水、搅天风。\n留不住。\n终须去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12077, '愁倚阑・春光好', '石孝友', '人好远，路能长。\n奈思量。\n更放晚来些小雨，做新凉。\n衰草低衬斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12078, '愁倚阑・春光好', '石孝友', '淮水阔，楚山长。\n恨难量。\n不道愁离人独夜，更天凉。\n佳节虚过重阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12079, '满庭芳', '石孝友', '笔走龙蛇，词倾河汉，妙年德艺双成。\n帝庭敷奏，亲擢冠群英。\n龙首其谁不取，便直饶、勋业峥嵘。\n偏他甚，泼天来大，一个好声名。\n忆曾。\n瞻拜处，当年汝水，今日溢城。\n叹白首青衫，又造宾闳。\n谨贽诗文一卷，仗仙风、吹到蓬瀛。\n依归地，熏香摘艳，作个老门生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12080, '满庭芳', '石孝友', '兰畹霜浓，柳溪冰咽，春光先到江梅。\n瘦枝疏萼，特地破寒开。\n钩引天涯旧恨，双眉锁、九曲回肠。\n空销黯，故园何在，风月浸长淮。\n当年，吟赏处，醉山颓倒，飞屑成堆。\n怎奈向而今，雨误云乖。\n万里难凭驿使，那堪对、别馆离杯。\n谁知道，洛阳诗老，还有梦魂来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12081, '满庭芳', '石孝友', '瘦颊凝酥，残妆弄酒，相逢一笑东风。\n并肩携手，羞落可怜红。\n疑是回心院里，埋醉首、吐作芳丛。\n无端处，雄蜂雌蝶，相美两情通。\n一从。\n攀折後，汉皋失，铜雀春空。\n想桃叶桃根，此恨能同。\n多谢金銮旧客，收拾在、芸阁签中。\n还知否，窃香传粉，输与蠹书虫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12082, '满庭芳', '石孝友', '修竹蓝，梅山耸翠，小小佳处西安。\n从来闻说，今日还来看。\n便好求田问舍，耳溪涧、目饱林峦。\n争知道，尘缘未了，无计与盘桓。\n小蛮。\n应念处，弦孤么凤，镜掩孤鸾。\n愁在见多情，素日闲闲。\n早晚扁舟两桨，惊翠枕、云风湍。\n从前去，殷勤细数，细数万重滩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12083, '更漏子', '石孝友', '吟鞭，欹醉帽。\n行尽关山古道。\n霜满地，水平田。\n雁儿声在天。\n北沙门，南浦岸。\n望得眼穿肠断。\n桐树巷，梦云楼。\n玉儿应也愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12084, '更漏子', '石孝友', '烛销红，窗送白。\n冷落一衾寒色。\n鸡唤起，马驰行。\n月昏衣上明。\n酒香唇，妆印臂。\n竟夜人人共睡。\n魂蝶乱，梦鸾孤。\n知他睡稳无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12085, '木兰花・玉楼春', '石孝友', '阳关声里催行色。\n马惜离群人惜别。\n入怀风月记衔杯，迎步溪山供散策。\n阴飙断渡江吹白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12086, '木兰花・玉楼春', '石孝友', '寻春误入桃源洞。\n草草幽欢聊与共。\n牢笼风月此时情，做造溪山今夜梦。\n柳蹊未放金丝弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12087, '踏莎行', '石孝友', '钗凤摇金，髻螺分翠。\n铢衣稳束宫腰细。\n绿柔红小不禁风，海棠无力贪春睡。\n剪水精神，怯春情意。\n霓裳一曲当时事。\n五陵年少本多情，为何特地添憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12088, '行香子', '石孝友', '你也娇痴。\n我也狂迷。\n望今生、永不分离。\n如何别後，三换梅枝。\n是好相知，不相见，只相思。\n良辰美景，赏心乐事，□□□负我辜伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12089, '画堂春', '石孝友', '寒蛩切切响空帷。\n断肠风叶霜枝。\n凤楼何处雁书迟。\n空数归期。\n□□沈腰春瘦，却成宋玉秋悲。\n又还辜负菊花时。\n没个人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12090, '摊破浣溪沙・山花子', '石孝友', '落日秋风岭上村。\n全稀过雁少行人。\n正是悲伤愁绝处，更黄昏。\n漠漠野烟生碧树，漫漫衰草际黄云。\n借使昔人行到此，也销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12091, '燕归梁', '石孝友', '楼外春风桃李阴。\n记一笑千金。\n翠眉山敛眼波侵。\n情滴滴、怨深深。\n当初见了，而今别後，算此恨难禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12092, '望江南・忆江南', '石孝友', '山又水，云带风湾。\n断雁飞时天拍水，乱鸦啼处日衔山。\n疑在画图间。\n人渐远，游子损朱颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12093, '青玉案', '石孝友', '征鸿过尽秋容谢。\n卷离恨、还东下。\n剪剪霜风落平野。\n溪山掩映，水烟摇曳，几簇渔樵舍。\n芙蓉城里人如画。\n春伴春游夜转夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12094, '蝶恋花', '石孝友', '别後相思无限忆。\n欲说相思，要见终无计。\n拟写相思持送似。\n如何尽得相思意。\n眼底相思心里事。\n纵把相思，写尽凭谁寄。\n多少相思都做泪。\n一齐泪损相思字。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12095, '蝶恋花', '石孝友', '寒卸园林春已透。\n红著溪梅，绿染前堤柳。\n见个人人今感旧。\n引杯相属蒲塘酒。\n金缕歌中眉黛皱。\n多少闲愁，借与伤春瘦。\n明日马蹄浮野秀。\n柳颦梅惨空回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12096, '蝶恋花', '石孝友', '薄幸人人留不住。\n杨柳花时，还是成虚度。\n一枕梦回春又去。\n海棠吹落胭脂雨。\n金鸭未销香篆吐。\n断尽柔肠，看取沈烟缕。\n独上危楼凝望处。\n西山暝色连南浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12097, '蓦山溪', '石孝友', '莺莺燕燕。\n摇荡春光懒。\n时节近清明，雨初晴、娇云弄暖。\n醉红湿翠，春意酿成愁，花似染。\n草如剪。\n已是春强半。\n小鬟微盼。\n分付多情管。\n痴呆不知愁，想怕晚、贪春未惯。\n主人好事，应许玳筵开，歌眉敛。\n舞腰软。\n怎向轻分散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12098, '蓦山溪', '石孝友', '小花静院。\n有个人人现。\n缥缈更娉婷，算不数、歌朋舞伴。\n鸣珂曲里，常记偶相逢，无语恨，有情愁，绿嫩红妆浅。\n别来谁念。\n人面关山远。\n凝睇倚危楼，眼波长、眉峰不展。\n一年心事，到此向谁论，书雁杳，梦云深，寂寞江天晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12099, '蓦山溪', '石孝友', '醉魂初醒。\n强起寻芳径。\n一似楚云归，诮没个、鳞书羽信。\n疏狂踪迹，虚度可怜春，阴还闷。\n晴还困。\n赢得无端病。\n菱花宝镜。\n拆破双鸾影。\n别袖忍频看，生怕见、啼红醉粉。\n而今憔悴，瘦立对东风，红成阵，绿成阴，况是春将尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12100, '千秋岁', '石孝友', '春工领略。\n点破群花萼。\n对流景，伤沦落。\n踏青心缕懒，病酒情怀恶。\n无奈处，东风故故吹帘幕。\n腕玉宽金约。\n一去音容邈。\n鱼与雁，应难托。\n从前多少事，不忍思量著。\n心撩乱，斜阳影在栏干角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12101, '传言玉女', '石孝友', '雪压梅梢，金袅柳丝轻敛。\n锦宫春早，乍风和日暖。\n华国翠路，九陌绮罗香满。\n连空灯火，满城弦管。\n月射西楼，更交光照夜宴。\n万人拥路，指鳌山共看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12102, '水调歌头', '韩玉', '间世真贤出，吉梦兆维熊。\n玉麟天上谪见，帏薄贯长虹。\n追念当年筹算，封魏封留勋业，千古事攸同。\n语云仁者寿，何必喻乔松。\n嗣天子，乘九五，驭飞龙。\n分麾契符阃外，凭倚定寰中。\n由是天才英纵，散入枢庭闲暇，谈笑抚兵戎。\n伫看骄虏静，金鼎篆元功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12103, '水调歌头', '韩玉', '有美如花客，容饰尚中州。\n玉京杳渺天际，与别几经秋。\n家在金河堤畔，身寄白苹洲末，南北两悠悠。\n休苦话萍梗，清泪已难收。\n玉壶酒，倾潋滟，听君讴。\n伫云却月，新弄一曲洗人忧。\n同是天涯沦落，何必平生相识，相见且迟留。\n明日征帆发，风月为君愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12104, '水调歌头', '韩玉', '月里一枝桂，不付等闲人。\n昔年霄汉，闻道争者尽输君。\n衣袖天香犹在，风度仙清难老，冰雪莹无尘。\n赋才三十倍，论寿八千春。\n夏庭芝，周室凤，舜郊麟。\n岂如今日称瑞，皇国再生申。\n聊借济时霖雨，来种重湖桃李，和气一番新。\n尚闻虚黄阁，行看秉洪钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12105, '念奴娇', '韩玉', '吴东清胜，是吴山苍翠，吴江澄绿。\n灵秀锺人文物盛，历历皆非凡俗。\n而况君家，风流遗世，犹寄山阴曲。\n继承才业，算来真是名族。\n聊恁驻节重湖，惠歌仁咏，蔼丰年图绿。\n行看登庸归去後，谁展高才相续。\n寿日称觞，一杯千岁，应见蟠桃熟。\n祝君难老，为君还更再祝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12106, '感皇恩', '韩玉', '远柳绿含烟，土膏才透。\n云海微茫露晴岫。\n故乡何在，梦寐草堂溪友。\n旧时游赏处，谁携手。\n尘世利名，於身何有。\n老去生涯樽酒。\n小桥流水，一树雪香瘦。\n故人今夜月，相思否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12107, '满江红', '韩玉', '正欲登临，何处好、登临眺望。\n君约我、今朝携酒，古台同上。\n风静秋郊浑似洗，碧空淡覆玻璃盎。\n夕照外、渺渺万遥山，开青嶂。\n龙山事，空追想。\n风流会，今安往。\n我劝君一杯，为君高唱。\n今日谋欢真雅胜，休辞痛饮葡萄浪。\n纵黄花、明日未凋零，非佳赏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12108, '曲江秋', '韩玉', '明轩快目。\n正雨过湘溪，秋来泽国。\n波面鉴开，山光淀拂，竹声摇寒玉。\n鸥鹭戏晚日，芰荷动，香红蔌。\n千古兴亡意，凄凉扬□舟，望迷南北。\n仿佛烟笼雾簇。\n认何处、当年绣毂。\n沈香花萼事，潇然伤□，宫殿三十六。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12109, '一剪梅・一翦梅', '韩玉', '镜里新妆镜外情。\n小眉幽恨，浅绿低横。\n只怨闲纵绣鞍尘。\n不道天涯，萦绊归程。\n梦里兰闺相见惊。\n玉香花瘦，春艳盈盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12110, '上平西・金人捧露盘', '韩玉', '折腰劳，弹冠望，纵飞蓬。\n笑造化、相戏穷通。\n风帆浪桨，暮成寒角晓楼锺。\n暗借霜雪鬓边来，惊对青铜。\n萧闲好，何时遂，门横水，迳穿松。\n有无限、杯月襟风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12111, '西江月', '韩玉', '捍拨声传酒绿，蔷薇面衬宫黄。\n娇波斜入鬓云长。\n眉与春山一样。\n潇洒不禁疏瘦，低回犹似思量。\n换花梨叶晚阴凉。\n说与三年梦想。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12112, '临江仙', '韩玉', '月是银溪是镜，云霓与作衣裳。\n夜寒独立竹篱傍。\n妆成那待粉，笑罢自生香。\n自古佳人多薄命，枉教傲雪凌霜。\n从来林下异闺房。\n何须三弄笛，方断九回肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12113, '番枪子', '韩玉', '莫把团扇双鸾隔。\n要看玉溪头、春风客。\n妙处风骨潇闲，翠罗金缕瘦宜窄。\n转面两眉攒、青山色。\n到此月想精神，花似秀质。\n待与不清狂、如何得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12114, '清平乐', '韩玉', '梅花照雪。\n浑似人清绝。\n香叠绀螺双背结。\n曾侍霓旌降节。\n如今却向尘寰。\n棋中寄个清闲。\n纵使阿郎多病，也须偷画春山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12115, '减字木兰花', '韩玉', '香檀素手。\n缓理新词来伴酒。\n音调凄凉。\n便是无情也断肠。\n莫歌杨柳。\n记得渭城朝雨後。\n客路茫茫。\n几度东风春草长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12116, '行香子', '韩玉', '一剪梅花，一见销魂。\n况溪桥、雪里前村。\n香传细蕊，春透灵根。\n更水清冷，云黯淡，月黄昏。\n幽过溪兰，清胜山矾。\n对东风、独立无言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12117, '太常引', '韩玉', '荒山连水水连天。\n忆曾上、桂江船。\n风雨过吴川。\n又却在、潇湘岸边。\n不堪追念，浪萍踪迹，虚度夜如年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12118, '太常引', '韩玉', '东城归路水云间。\n几曾放、梦魂闲。\n何日整归鞍。\n又人对、西风凭栏。\n温柔情性，系怀伤感，欲诉诉应难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12119, '贺新郎', '韩玉', '柳外莺声碎。\n晚晴天、东风力软，嫩寒初退。\n花底觅春春已去，时见乱红飞坠。\n又闲傍、阑干十二。\n阑外青山烟缥缈，远连空、愁与眉峰对。\n凝望处，两叠翠。\n鸳鸯结带灵犀佩。\n绮屏深、香罗帐小，宝檠灯背。\n谁谓彩云和梦断，青翼阻寻後会。\n待都把、相思情缀。\n便做锦书难写恨，奈菱花、都见人憔悴。\n那更有，枕痕泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12120, '贺新郎', '韩玉', '绰约人如玉。\n试新妆、娇黄半绿，汉宫匀注。\n倚傍小阑闲伫立，翠带风前似舞。\n记洛浦、当年俦侣。\n罗袜尘生香冉冉，料征鸿、微步凌波女。\n惊梦断，楚江曲。\n春工若见应为主。\n忍教都、闲亭邃馆，冷风凄雨。\n待把此花都折取。\n和泪连香寄与。\n须信道、离情如许。\n烟水茫茫斜照里，是骚人、九辨招魂处。\n千古恨，与谁语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12121, '贺新郎', '韩玉', '睡起帘栊静。\n□金铺、春帏半卷，宝香烟冷。\n门外落花风不定。\n糁糁乱红堆径。\n谁唤做、春愁如病。\n零乱云鬟慵梳掠，傍菱花、羞对孤鸾影。\n情易感，恨难醒。\n沙边柳外当时景。\n记分携、离筵乍阕，去帆初整。\n尽举棹歌和泪听。\n云淡水寒烟暝。\n空怆望、楼高天迥。\n犹未归来何处也，日长时、不念人孤另。\n书谩写，雁谁倩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12122, '水调歌头', '韩玉', '重午日过六，灵岳再生申。\n丰神英毅，端是天上谪仙人。\n夙蕴机权才略，早岁来归明圣，惊耸汉庭臣。\n言语妙天下，名德冠朝绅。\n绣衣节，移方面，政如神。\n九重隆眷倚注，伟业富经纶。\n闻道山东出相，行拜紫泥飞诏，归去秉洪钧。\n寿虾自天锡，安用拟庄椿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12123, '且坐令', '韩玉', '闲院落。\n误了清明约。\n杏花雨过胭脂绰。\n紧了秋千索。\n斗草人归，朱门悄掩，梨花寂寞。\n书万纸、恨凭谁托。\n才封了、又揉却。\n冤家何处贪欢乐。\n引得我心儿恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12124, '风入松', '韩玉', '柳阴亭院杏梢长。\n依约巫阳。\n凤箫已远秦楼在，水沈烟暖馀香。\n临镜舞鸾窥沼，倚筝飞雁辞行。\n醉边人去自凄凉。\n泪眼愁肠。\n断云残雨当年事，到而今、好处难忘。\n两袖晓风花陌，一帘夜雨兰堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12125, '鹧鸪天', '韩玉', '披拂芝兰便断金。\n顿成南北岂胜任。\n三年尊酒半生话，千里云山一寸心。\n休怅望，莫登临。\n梦魂何处不相寻。\n柔肠欲问愁多少，未比湘江烟水深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12126, '鹧鸪天', '韩玉', '爱日烘晴旬日间。\n谩邀朋辈为跻攀。\n无穷望眼无穷恨，不尽长江不尽山。\n星点点，月团团。\n倒流河汉入杯盘。\n饱吟风月三千首，寄与吴姬忍泪看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12127, '生查子', '韩玉', '裙拖簇石榴，髻绾偏荷叶。\n头上短金钗，轻重还相压。\n轻颦月入眉，浅笑花生颊。\n夫婿不风流，取次看承别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12128, '卜算子', '韩玉', '杨柳绿成阴，初过寒食节。\n门掩金铺独自眠，那更逢寒夜。\n强起立东风，惨惨梨花谢。\n何事王孙不早归，寂寞秋千月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12129, '霜天晓月', '韩玉', '竹篱茅屋。\n一树扶疏玉。\n客里十分清绝，有人在、江南北。\n伫目。\n诗思促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12130, '蓦山溪', '熊良翰', '四时美景，最好惟春昼。\n仙诞弥辰，况还当、中春时候。\n日迟风软，是处霭晴烟，桃散锦，柳摇金，交映门庭秀。\n此时称寿。\n兰玉相先後。\n喜色上眉峰，且休辞、频倾芳酒。\n虚空看透，摆脱利名缰，云鬓绿，醉颜酡，笑挹浮丘袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12131, '鹧鸪天', '熊可量', '清晓南窗笑语喧。\n今朝生日胜从前。\n鹤吞沆瀣神逾爽，松饱风霜节更坚。\n调气马，殖心田。\n几曾佞佛与夸仙。\n戏衫脱了浑无累，快活人间百十年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12132, '万年欢', '熊上达', '春管方中，正良辰馀五，韶光明媚。\n晓见非烟佳气，满堂融溢。\n学语儿童喜色。\n庆间世、悬弧此日。\n休言未、结组弹冠，不劳戏傲泉石。\n生平服膺道德。\n看名高谷口，年齐箕翼。\n况有宁馨，已报月宫消息。\n只这谁人似得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12133, '南柯子・南歌子', '苏十能', '江水粼粼碧，云山叠叠奇。\n平生心事一钩丝。\n便是壶中日月、更何疑。\n文叔今方贵，君房素自痴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12134, '玉楼春', '朱景文', '玉阶琼室冰壶帐。\n恁地水晶帘不上。\n儿家住处隔红尘，云气悠扬风淡荡。\n有时闲把兰舟放。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12135, '满江红', '欧阳光祖', '恰则元宵，灿万灯、星球如昼。\n春乍暖、化工未放，十分花柳。\n和气并随灯夕至，一时锺作人间秀。\n问烟霄、直上舌含香，文绣。\n命世杰，调元手。\n荆楚地，淹留久。\n看日边追诏，印垂金斗。\n翠竹苍松身逾健，蛾儿雪竹人如旧。\n愿湘江、卷入玉壶中，为公寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12136, '瑞鹤仙', '欧阳光祖', '得毛韩经学。\n振祖风，挺挺凌烟勋业。\n文章世为甲。\n果妙龄秀发，荐膺衡鹗。\n名登雁塔。\n访梅仙，种河阳桃李，从兹两绾铜符，多少吏民欢洽。\n庆惬。\n归来整顿，松竹笑傲，武夷溪壑。\n韶光恰匝。\n清明过了旬浃。\n喜当初度日。\n称觞春酒，一饮红生双颊。\n愿儿孙，世袭簪缨，代常不乏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12137, '酹江月・念奴娇', '罗椿', '郎星锦帐，忽翩然归访，南溪孤鹜。\n前日登高谁信道，寿酒重浮茱萸。\n风露杯寒，芙蓉帐冷，笑受长生。\n广寒宫殿，桂华应已新续。\n不用翠倚红围，舞裙歌袖，共理称觞曲。\n只把文章千古事，留伴平生幽独。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12138, '沁园春', '游九言', '五十五年，满簪华发，俨然遂良。\n又何曾戚戚，荜门圭窦，何曾汲汲，玉带金章。\n困後高眠，饥来饱□，老矣狂夫老更狂。\n空回首，叹世间名利，傀儡开场。\n幸临晚节安康。\n又两日、三秋催萧霜。\n叹生朝亦是，贺宾踵至，龙锺矍铄，何足称觞。\n喜对诸贤，笑谈世事，相会亲朋醉玉觞。\n谁如我，素乐天知命，不事侯王。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12139, '赤枣子', '游九言', '河汉澈，碧霄晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12140, '赤枣子', '游九言', '香露湿，草晶荧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12141, '赤枣子', '游九言', '仙子去，眇云程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12142, '洞仙歌', '刘光祖', '晚风收暑，小池塘荷净。\n独倚胡床酒初醒。\n起徘徊、时有香气吹来，云藻乱，叶底游鱼动影。\n空擎承露盖，不见冰容，惆怅明妆晓鸾镜。\n後夜月凉时，月淡花低，幽梦觉、欲凭谁省。\n且应记、临流凭阑干，便遥想，江南红酣千顷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12143, '鹊桥仙', '刘光祖', '相逢一笑，又成相避，南雁归时霜透。\n明朝人在短亭西，看舞袖、双双行酒。\n歌声此处，秋声何处，几度乱愁搔首。\n如何不寄一行书，有万绪、千端别後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12144, '昭君怨', '刘光祖', '人在醉乡居住。\n记得旧曾来去。\n疏雨听芭蕉。\n梦魂遥。\n惆怅柳烟何处。\n目送落霞江浦。\n明夜月当楼。\n照人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12145, '江城子', '刘光祖', '十分雪意却成霜。\n暮云黄。\n月微茫。\n只有梅花，依旧吐幽芳。\n还喜无边春信漏，疏影下，觅浮香。\n才清端是紫薇郎。\n别行。\n忆宫墙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12146, '长相思', '刘光祖', '玉尊凉。\n玉人凉。\n若听离歌须断肠。\n休教成鬓霜。\n画桥西，画桥东。\n有泪分明清涨同。\n如何留醉翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12147, '水调歌头', '刘光祖', '客梦一回醒，三度碧梧秋。\n仰看今夕天上，河汉又西流。\n早晚凉风过雁，惊落空阶一叶，急雨闹清沟。\n归计休令暮，宵露征裘。\n古来今，生老病，许多愁。\n那堪更说，无限功业镜中羞。\n只有青山高致，对此还论世事，举白与君浮。\n送我一杯酒，谁起舞凉州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12148, '临江仙', '刘光祖', '小院回廊春寂寂，晚来独自闲行。\n画帘东畔碧云生。\n也知无雨，空滴枕边声。\n一簇小桃开又落，低头拾取红英。\n东风相送忘相迎。\n梨花寒食，到得锦宫城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12149, '临江仙', '刘光祖', '我似万山千里外，悠然一片归云。\n宫衔犹自带云云。\n谁知前进士，已是故将军。\n闲坐闲行闲饮酒，闲拈闲字闲文。\n诸公留我笑纷纷。\n一枝簪宝髻，六幅舞罗裙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12150, '踏莎行', '刘光祖', '扫径花零，闭门春晚。\n恨长无奈东风短。\n起来消息探荼縻，雪条玉蕊都开遍。\n晚月魂清，夕阳香远。\n故山别後谁拘管。\n多情於此更情多，一枝嗅罢还重拈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12151, '醉落魄・一斛珠', '刘光祖', '春风开者。\n一时还共春风谢。\n柳条送我今槐夏。\n不饮香醪，孤负人生也。\n曲塘泉细幽琴写。\n胡床滑簟应无价。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12152, '沁园春', '刘光祖', '画戟如霜，绮疏如水，篆香渐微。\n向莺花多处，青山衮衮，鹭凫散後，落屑霏霏。\n曾是鸾台金马客，一场梦觉来人事非。\n多少话，付无心云叶，自在闲飞。\n想看燕鸿易感，□几度春往秋又归。\n见黄馀露点，东坡菊赋，清传雪片，处士梅诗。\n向此年年开寿，算今古人生七十稀。\n歌啸外，作皇朝遗老，名字辉辉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12153, '满江红', '何师心', '一水飞空，揭起珠帘全幅。\n不须人卷，不须人轴。\n一点不容飞燕入，些而未许游鱼宿。\n向山头、款步听疏音，清如玉。\n三峡水，堪人掬。\n三汲浪，堪龙浴。\n更两边潇洒，数竿修竹。\n晓倩碧烟为绳束，夜凭新月为钩曲。\n问当年、题品是何人，黄山谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12154, '小重山', '赵蕃', '何地无溪祗欠人。\n有翁年八十，住其滨。\n直钩元不事丝缗。\n优游尔，聊以遂吾身。\n陶令赋归辰。\n未尝轻出入，犯风尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12155, '菩萨蛮', '赵蕃', '鸡声茅店饮残月。\n板桥人迹霜如雪。\n此是古人诗。\n身经老忘之。\n君行当此境。\n令我昏成醒。\n乘月犯霜来。\n诗真误尔哉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12156, '失调名', '赵蕃', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12157, '望江南・忆江南', '何令修', '登龙脊，抚剑一长歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12158, '水龙吟', '马子严', '买庄为贮梅花，玉妃一万森庭户。\n古来词客，比方不类，可怜毫楮。\n谁扫尘凡，独超物表，神仙中取。\n是丘标致，射山风骨，除此外、吾谁与。\n九酝醍醐雪乳。\n和金盘、月边清露。\n寿阳骄呆，单于疏贱，不堪充数。\n弄玉排箫，许琼挥拍，胎禽飞舞。\n待先生，披著羊裘鹤氅，作园林主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12159, '玉楼春', '马子严', '南枝又觉芳心动。\n慰我相思情味重。\n陇头何处寄将书，香发有时疑是梦。\n谁家横笛成三弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12160, '桃源忆故人', '马子严', '几年闲作园林主。\n未向梅花著语。\n雪後又开半树。\n风递幽香去。\n断魂不为花间女。\n枝上青禽□诉。\n我是西湖处士。\n长恨芳时误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12161, '十拍子・破阵子', '马子严', '点缀莫窥天巧，名称却道人为。\n香酝蜜脾分几点，色映乌云倚一枝。\n遥看步赏迟。\n映水不嫌疏影，娇春也自同时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12162, '花心动', '马子严', '雨洗胭脂，被年时、桃花杏花占了。\n独惜野梅，风骨非凡，品格胜如多少。\n探春常恨无颜色，试浓抹、当场微笑。\n趁时节，千般冶艳，是谁偏好。\n直与岁寒共保。\n问单于、如今几分娇小。\n莫怪山人，不识南枝，横玉自来同调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12163, '贺新郎', '马子严', '客里伤春浅。\n问今年梅蕊，因甚化工不管。\n陌上芳尘行处满。\n可计天涯近远。\n见说道、迷楼左畔。\n一似江南先得暖。\n向何郎、庭下都寻遍。\n辜负了，看花眼。\n古来好物难为伴。\n只琼花一种，传来仙苑。\n独许扬州作珍产。\n便胜了、千千万万。\n又却待、东风吹绽。\n自昔闻名今见面。\n数归期、屈指家山晚。\n归去说，也稀罕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12164, '满庭芳', '马子严', '共庆春时，满庭芳思，一枝心蕊非常。\n少年游冶，何但折垂杨。\n曾向瑶台月下，逢解佩、玉女翻香。\n风光好，真珠帘卷，都胜早梅芳。\n人间，无比并，玉蝴蝶树，争敢相方，既□春归後，此意难忘。\n夜梦扬州万玉，飞魂共、紫燕归梁。\n须行乐，马家花圃，不肯醉红妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12165, '水龙吟', '马子严', '东君直是多情，好花一夜都开尽。\n杏梢零落，药栏迟暮，不教宁静。\n风度秋千，日移帘幕，翠红交映。\n正太真浴罢，西施浓抹，都沉醉、娇相称。\n磨遍绿窗铜镜。\n挽春衫、不堪比并。\n暮云空谷，佳人何处，碧苔侵迳。\n睡里相看，酒边凝想，许多风韵。\n问因何，却欠一些香味，惹旁人恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12166, '二郎神', '马子严', '日高睡起，又恰见、柳梢飞絮。\n倩说与、年年相挽，却又因他相误。\n南北东西何时定，看碧沼、青萍无数。\n念蜀郡风流，金陵年少，哪寻张绪。\n应许。\n雪花比并，扑帘堆户。\n更羽缀游丝，毡铺小径，肠断鹁鸠唤雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12167, '天仙子', '马子严', '白玉为台金作盏。\n香是江梅名阆苑。\n年时把酒对君歌，歌不断。\n杯无算。\n花月当楼人意满。\n翘戴一枝蝉影乱。\n乐事且随人意换。\n西楼回首月明中，花已绽。\n人何远。\n可惜国香天不管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12168, '最高楼', '马子严', '花解笑，冷淡不求知。\n长是殿、众芳时。\n鲜鲜秀颈磋圆玉，洛阳翠佩剪琉璃。\n向人前，迎茉莉，送荼シ。\n几欲把、清香换春色。\n费多少、黄金酬不得。\n梅雨妒，麦风欺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12169, '青门引・青门饮', '马子严', '手种团团玉。\n香趁日晴初熟。\n金刀错落晓霜寒，十分风味，独向暑天足。\n唐君去後云空谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12170, '朝中措', '马子严', '龙荪晚颖破苔纹。\n英气欲凌云。\n深处未须留客，春风自掩柴门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12171, '临江仙', '马子严', '人意舒闲春事到，徐徐弄日微云。\n翠鬟飞绕蛾群。\n烟横沽酒市，风转落梅村。\n岁事一新人半旧，相逢际晚醺醺。\n花间亭馆柳间门。\n除风雨外，排日醉红裙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12172, '月华清', '马子严', '瑟瑟秋声，萧萧天籁，满庭摇落空翠。\n数遍丹枫，不见叶间题字。\n人何处、千里婵娟，愁不断、一江流水。\n遥睇。\n见征鸿几点，碧天无际。\n怅望月中仙桂。\n问窃药佳人，谁与同岁。\n把镜当空，照尽别离情意。\n心里恨、莫结丁香，琴上曲、休弹秋思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12173, '贺圣朝', '马子严', '游人拾翠不知远。\n被子规呼转。\n红楼倒影背斜阳，坠几声弦管。\n荼シ香透，海棠红浅。\n恰平分春半。\n花前一笑不须悭，待花飞休怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12174, '鱼游春水', '马子严', '池塘生春草。\n数尽归鸿人未到。\n天涯目断，青鸟尚赊音耗。\n晓月频窥白玉堂，暮雨还湿青门道。\n巢燕引雏，乳莺空老。\n庭际香红倦扫。\n乾鹊休来枝上嗓。\n前回准拟同他，翻成病了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12175, '海棠春', '马子严', '柳腰暗怯花风弱。\n红映秋千院落。\n归逐燕儿飞，斜撼真珠箔。\n满林翠叶胭脂萼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12176, '鹧鸪天', '马子严', '睡鸭俳徊烟缕长。\n日高春困不成妆。\n步草色金莲润，拈断花玉笋香。\n轻洛浦，笑巫阳。\n锦纹亲织寄檀郎。\n儿家闭户藏春色，戏蝶游蜂不敢狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12177, '归朝欢', '马子严', '听得提壶沽美酒。\n人道杏花深处有。\n杏花狼藉鸟啼风，十分春色今无九。\n麝煤销永昼。\n青烟飞上庭前柳。\n画堂深，不寒不暖，正是好时候。\n团团宝月凭纤手。\n暂借歌喉招舞袖。\n真珠滴破小槽红，香肌缩尽纤罗瘦。\n投分须白首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12178, '孤鸾', '马子严', '沙堤香软。\n正宿雨初收，落梅飘满。\n可奈东风，暗逐马蹄轻卷。\n湖波又远涨绿，粉墙阴、日融烟暖。\n蓦地刺桐枝上，有一声春唤。\n任酒帘、飞动画楼晚。\n便指数烧灯，时节非远。\n陌上叫声，好是卖花行院。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12179, '阮郎归', '马子严', '清明寒食不多时。\n香红渐渐稀。\n番腾妆束闹苏堤。\n留春春怎知。\n花褪雨，絮沾泥。\n凌波寸不移。\n三三两两叫船儿。\n人归春也归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12180, '浣溪沙慢', '马子严', '璧月上极浦。\n帆落人挝鼓。\n石城倒影，深夜鱼龙舞。\n佳气郁郁，紫阕腾云雨。\n回首分今古。\n千载是和非，夕阳中、双燕语。\n向人诉。\n记玉井辘轳，胭脂涨腻，几许蛾眉妒。\n感叹息、花好随风去。\n流景如羽。\n且共乐升平，不须後庭玉树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12181, '锦缠道', '马子严', '雨过园林，触处落红凝绿。\n正桑叶、齐如沃。\n娇羞只恐人偷目。\n背立墙阴，慢展纤纤玉。\n听鸠啼几声，耳边相促。\n念蚕饥、四眠初熟。\n劝路旁、立马莫踟躇，是那里唱道秋胡曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12182, '满江红', '马子严', '瑞霭秋空，银河里、非烟非雾。\n应想是、岳锺神秀，再生尹傅。\n昨夜五云随梦入，今朝万象朝元去。\n正六星、炳炳耀文昌，循初度。\n五马贵，多文富。\n人品异，心朝古。\n似冰清瑶水，玉森元圃。\n天子方将循异政，灵孙又合为霖雨。\n问汾阳、几考在中书，从今数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12183, '水调歌头', '马子严', '万仞鹅湖顶，千岁矫苍龙。\n楼台一簇，仙家遥寄五云中。\n天上朝元佳节，人世生贤华旦，瑞气郁葱葱。\n六辔耀闽海，列郡喜趋风。\n记昔年，当此际，早梅红。\n插花饮酒，狂歌醉舞寿昌宫。\n零落青袍如旧，敛板绣衣庭下，欣见黑头公。\n王室要师保，叔父忽居东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12184, '感皇恩', '马子严', '深约海棠开，一庭儿女。\n共插满头笑相语。\n入春准备了，到今朝团聚。\n近来都不怕，风和雨。\n一个一杯，君山绿醑。\n何必贪多似彭祖。\n但须看遍，子生孙孙生子。\n便年年拼一醉，花前舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12185, '浪淘沙', '马子严', '娇额尚涂黄。\n不久时妆。\n十分轻脆奈风霜。\n几度细腰寻得蜜，错认蜂房。\n东阁久凄凉。\n江路悠长。\n休将颜色较芬芳。\n无奈花间真若伪，赖有幽香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12186, '苏幕遮', '马子严', '地偏灵，天应瑞。\n簇簇银花，团绕真珠蕊。\n金阕玉楼分十二。\n要伴娥，与月循环睡。\n月如花，花表岁。\n人到闰年，添个真奇异。\n不许扬州夸间气。\n昨夜春风，吹送柴门里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12187, '万年欢', '赵师侠', '电绕神枢，华渚流虹，诞弥良用佳辰。\n万宇讴歌归舞，宝历增新。\n四七年间盛事，皇威畅、边鄙无尘。\n仁恩被，华夏咸安，太平极治欢声。\n重华道隆德茂，亘古今希有，揖逊重闻。\n圣子三宫欢聚，两世慈亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12188, '水调歌头', '赵师侠', '金鼎调元手，玉殿涣恩华。\n宣威蜀道，曾见千骑拥高牙。\n凭仗元枢筹略，宽我宸旒西顾，惠泽被幽遐。\n为忆江城好，南浦仙槎。\n格天心，膺帝眷，极褒嘉。\n琳宫香火缘在，远近玉皇家。\n霖雨久思贤佐，看即声传丹禁，唤仗听宣麻。\n衮绣公归去，宰路筑堤沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12189, '水调歌头', '赵师侠', '江亭送行客，肠断木兰舟。\n水高风快，满木烟树织成愁。\n咿轧数声柔橹，拍塞一怀离恨，指顾隔汀洲。\n独立苍茫外，欲去强迟留。\n海山长，云水阔，思难收。\n小亭深院歌笑，不忍记同游。\n唯有当时明月，千里有情还共，後会尚悠悠。\n此恨无重数，和泪付东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12190, '水调歌头', '赵师侠', '韶华能几许，节物叹推移。\n群花兢芳争艳，无奈隙驹驰。\n红紫随风何处，唯有抟枝新绿，暗逐雨摧肥。\n乔木莺初啭，深院燕交飞。\n渐清和，微扇暑，日迟迟。\n新荷泛水摇漾，萍藻弄晴漪。\n百岁光阴难挽，一笑欢娱易失，莫惜酒盈卮。\n无计留连住，还是送春归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12191, '水调歌头', '赵师侠', '江流清浅外，山色有无中。\n平田坡岸回曲，一目望难穷。\n波面轻鸥容与，沙际野航横渡，不信画图工。\n路入神仙宅，翠锁梵王宫。\n俯晴郊，增胜概，气横空。\n云林城市层列，知有几重重。\n更上危亭高几，徙倚栏干虚敞，象纬逼璇穹。\n要尽无边景，烟雨看空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12192, '水调歌头', '赵师侠', '人生如寄耳，世态逐时移。\n浮名薄利能几，方寸漫交驰。\n粗足生涯随分，到眼风光可乐，终不羡轻肥。\n有志但长叹，无路且卑飞。\n恨年华，何去速，又来迟。\n绿荫浓映池沼，浪皱风漪。\n啭午莺声，滚地杨花飘荡，爱景惜芳卮。\n此意谁能解，一笑任春归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12193, '水调歌头', '赵师侠', '心景雨无著，情物岂能移。\n超然远览失笑，名利苦纷驰。\n一品官资荣显，百万金珠豪富，空自喜家肥。\n会得个中理，川泳与云飞。\n静中乐，闲中趣，自舒迟。\n心如止水，无风无自更生漪。\n已是都忘人我，一任吾身醒醉，有酒引连卮。\n万法无差别，融解即同归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12194, '水调歌头', '赵师侠', '世态万纷变，人事一何忙。\n胸中素韬奇蕴，匣剑岂能藏。\n不向燕然纪绩，便与渔樵争席，摆脱是非乡。\n要地时难得，间处日偏长。\n志横秋，谋夺众，谩轩昂。\n蝇头蜗角微利，争较一毫芒。\n幸有乔木修竹，随分粗衣粝食，何必计冠裳。\n我已乐箫散，谁与共平章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12195, '水调歌头', '赵师侠', '台星明翼轸，和气满潇湘。\n长淮胜处地灵，应产股肱良。\n共仰三朝元老，要识一时英杰，人物自堂堂。\n直气薄霄汉，德望耸岩廊。\n拥貔貅，森戟，镇藩方。\n折冲樽俎，春融花柳侑壶觞。\n两世麟符玉节，九郡恩风惠雨，仁者寿宜长。\n凤诏来丹阙，绣衮觐明光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12196, '满江红', '赵师侠', '渺渺春江，迷望眼、蒲萄涨绿。\n春过也、萧疏庭户，寂寥心目。\n念远不禁啼闹，愁多易遣修蛾蹙。\n向小窗、时把彩笺看，翻新曲。\n晴昼永，便新浴。\n相思泪，不成哭。\n空无言憔悴，暗销肌玉。\n目断碧云无信息，试凭青翼飞南北。\n听掀帘、疑是故人来，风敲竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12197, '满江红', '赵师侠', '烟浪连天，寒尚峭、空细雨。\n春去也、红销芳径，绿肥江树。\n山色云笼迷远近，滩声水满望艰阻。\n挂片帆、掠岸晚风轻，停烟渚。\n浮世事，皆如许。\n名利役，惊时序。\n叹清明寒食，小舟为旅。\n露宿风餐安所赋，石泉榴火知何处。\n动归心、犹赖翠烟中，无杜宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12198, '满江红', '赵师侠', '露冷天高，秋气爽、千林叶落。\n惊初见、小桃枝上，盛开红萼。\n浅淡胭脂经雨洗，剪裁玛瑙如云薄。\n问素商、何事斗春工，施丹。\n芙蓉苑，颜如灼。\n曾暗与，花王约。\n要乘秋名字，并传京洛。\n回首瑶池高宴处，桂花香里骖高鹤。\n但莫教、容易逐西风，轻飘却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12199, '满江红', '赵师侠', '凉入三湘，秋气爽、江澄沙白。\n人欲去、离愁暗暗，莫留行色。\n盍在中朝陪鹭，暂来南楚分风月。\n与元枢、鹗荐共扶摇，朝天阙。\n皇华使，和戎策。\n西府赞，中兴业。\n有缁衣同美，武公勋烈。\n樯燕已知添别意，骊驹谁为歌新阕。\n恨此情、如月过中秋，圆还缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12200, '满江红', '赵师侠', '去去春光，留不住、情怀索莫。\n那堪是、日长人困，雨馀寒薄。\n叶底青青梅胜豆，枝头颗颗花留萼。\n叹流年、空有惜春心，凭春酌。\n歌共酒，谁酬酢。\n非与是，忘今昨。\n且随时随分，强欢寻乐。\n世事燕鸿南北去，人生乌兔东西落。\n问故园、不负送春期，明年约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12201, '沁园春', '赵师侠', '雨接梅霖，风怯槐暑，麦天已秋。\n正榴燃红炬，枝头色艳，荷翻绿盖，池面香浮。\n心景俱清，身名何有，且向忙中早转头。\n尘劳事，枉朝思夕计，细虑深谋。\n悠悠。\n不复徼求。\n但安分、随缘休便休。\n纵官居极品，徒为美玩，家称钜富，未免闲愁。\n遇酒开颜，逢欢乐意，有似木人骑土牛。\n从他笑，看一朝解悟，八极遨游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12202, '沁园春', '赵师侠', '羊角飘尘，金乌烁石，雨凉念秋。\n有虚堂临水，披襟散发，纱雾卷，湘潭波浮。\n远列云峰，近参荷气，卧看文书琴枕头。\n蝉声寂，向庄周梦里，栩栩无谋。\n茶瓯。\n醒困堪求。\n粗饱饭安居可以休。\n算け闲静胜，吾能自乐，荣华纷扰，人谩多愁。\n习懒非痴，觉迷是病，一力那能胜九牛。\n俱休问，且追寻觞咏，知友从游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12203, '酹江月・念奴娇', '赵师侠', '枕山平远。\n记当年小阁，牙床曾展。\n围幅高深春昼永，寂寂重帘不卷。\n棹西湖，人归南陌，酒晕红生脸。\n困来无那，玉肌小倚娇软。\n堪恨身在天涯，曲屏环枕，此意何由见。\n想像高唐无梦到，独拥闲衾展转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12204, '酹江月・念奴娇', '赵师侠', '飘流踪迹，趁春来、还趁春光归去。\n九十韶华能几许，著意留他不住。\n趱柳催花，催红长翠，多少风和雨。\n蜂闲蝶怨，尽凭枝上莺语。\n归棹去去难留，桃花浪暖，绿涨迷津浦。\n回首重城天样远，人在重城深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12205, '酹江月・念奴娇', '赵师侠', '斜风疏雨，正无聊情绪，天涯寒食。\n烟重云娇春烂漫，却得轻寒邀勒。\n柳褪鹅黄，池添鸭绿，桃杏浑狼藉。\n乱山深处，尚留些子春色。\n海燕未便归来，踏青斗草，谁与同寻觅。\n杜宇多情芳树里，只管声声历历。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12206, '酹江月・念奴娇', '赵师侠', '晓风清暑，映湖光如练，山光如染。\n十里荷花香满路，飞盖斜妆面。\n一叶扁舟，数声柔橹，陡觉红尘远。\n六桥三塔，恍然图画中见。\n因念当日三贤，两山佳处，应也经行遍。\n琢月吟风无限句，景物随人俱显。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12207, '酹江月・念奴娇', '赵师侠', '化工何意，向天涯海峤，有花清绝。\n缟袂绿裳无俗韵，不畏炎荒烦热。\n玉骨无尘，冰姿有艳，雅淡天然别。\n真香冶态，未饶红紫春色。\n底事□落江南，水仙兄弟，端自难优劣。\n瘴雨蛮烟魂梦远，宁识溪桥霜雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12208, '酹江月・念奴娇', '赵师侠', '平生奇观，爱登高临远，寻幽选胜。\n欲上层巅穷望眼，一半崎岖危径。\n万瓦鳞鳞，四山簇簇，咫尺疏林映。\n山川城郭，恍然多少清兴。\n残照斜敛馀红，横陈平远，一抹轻烟暝。\n何处飞来双白鹭，点破遥空澄莹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12209, '酹江月・念奴娇', '赵师侠', '韶华婉娩，正和风迟日，喧妍清昼。\n紫燕黄鹂争巧语，催老芬芳花柳。\n灼灼花王，盈盈娇艳，独殿春光後。\n鹤翎初拆，露沾香沁珠溜。\n遥想京洛风流，姚黄魏紫，间绿如铺纤。\n小盖低回雕栏曲，车马纷驰圆囿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12210, '促拍满路花', '赵师侠', '栽花春烂漫，叠石翠。\n小亭相对倚，数峰寒。\n主人寻胜，接竹引清泉。\n凿破苍苔地，一掬泓澄，六花疑是深渊。\n向闲中、百虑け然。\n情事寄鸣弦。\n炉香陪茗碗，可望言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12211, '促拍满路花', '赵师侠', '连枝蟠古木，瑞阴映晴空。\n桃江江上景，古今同。\n忙中取静，心地尽从容。\n扫尽荆榛蔽，结屋诛茅，道人一段家风。\n任乌飞兔走匆匆。\n世事亦何穷。\n官闲民不扰，更年丰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12212, '永遇乐', '赵师侠', '金昊行秋，季商回律，天气佳处。\n瑞应皇家，祥开圣旦，宝历绵基祚。\n瑶池人祝，钧天乐奏，湛露宴均寰宇。\n万花覆、千官尽醉，盛事顿超今古。\n中兴天统，四三传序，揖逊自归明主。\n黄屋非心，萝图有永，远付当今主。\n希夷高蹈，寿康长保，五世祖孙欢聚。\n尊之至，千秋令节，万年圣父。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12213, '永遇乐', '赵师侠', '秋满衡皋，淡云笼月，晚来风劲。\n一抹残霞，数声过雁，远是黄昏近。\n凭高临远，倚楼凝睇，多少断愁幽兴。\n听渔村、鸣榔隐隐，别浦暮烟收暝。\n湘妃起舞，芳栏纫佩，约略乱峰云鬓。\n景物悲凉，楚天澄淡，过尽归帆影。\n斜阳低处，远山重叠，萧树乱鸦成阵。\n空无言，栏干凭暖，闷怀似困。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12214, '永遇乐', '赵师侠', '日丽风暄，暗催春去，春尚留恋。\n香褪花梢，苔侵柳径，密幄清阴展。\n海棠零乱，梨花淡伫，初听闹空莺燕。\n有轻盈、妍姿靓态，缓步阆风仙苑。\n绿丛红萼，芳鲜柔媚，约略试妆深浅。\n细叶来禽，长梢戏蝶，簇簇枝头见。\n酡颜发，春愁无力，困倚画屏娇软。\n只应怕、风欺雨横，落红万点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12215, '风入松', '赵师侠', '溪山佳处是湘中。\n今古言同。\n平林远岫浑如画，更渔村、返照斜红。\n两岸荻风策策，一江秋水溶溶。\n苍涯石壁景尤雄。\n人自西东。\n利名汩没黄尘里，又那知、清胜无穷。\n何日轻蓑笠，持竿独钓西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12216, '凤凰阁', '赵师侠', '正薰风初扇，雨细梅黄暑溽。\n并摇双桨去程速。\n那更黄流浩淼，白浪如屋。\n动归思、离愁万斛。\n平生奇观，颇快江山寓目。\n日斜云定晚风熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12217, '蝶恋花', '赵师侠', '柳眼窥春春渐吐。\n又是东风，摇曳黄金树。\n宜入新春闻好语。\n一犁处处催耕雨。\n未有花须金缕缕。\n醉梦悠扬，似蝶翩跹舞。\n一枕仙游何处去。\n觉来依旧江南住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12218, '蝶恋花', '赵师侠', '春到园林能几许。\n昨夜疏疏，过却催花雨。\n暖日晴岚原上路。\n雕鞍暂系芳菲树。\n仙洞同游皆胜侣。\n翻忆年时，醉里曾寻句。\n要与龙江春作主。\n翩然又趁东风去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12219, '蝶恋花', '赵师侠', '剪剪西风催碧树。\n乱菊残荷，节物惊秋暮。\n绿叶红苞迎晓露。\n锦屏绣幄围芳圃。\n尘世鸾骖那肯驻。\n尚忆层城，仙苑飞琼侣。\n能共牡丹争几许。\n惜花对景聊为主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12220, '蝶恋花', '赵师侠', '百叠霜罗香蕊细。\n袅袅垂铃，缀簇黄金碎。\n独占九秋风露里。\n芳心不与群英比。\n采采东篱今古意。\n秀色堪餐，更惹兰膏腻。\n不用南山横紫翠。\n悠然消得因花醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12221, '蝶恋花', '赵师侠', '剪水凌虚飞雪片。\n认得清香，雪树深深见。\n傅粉凝酥明玉艳。\n含章檐下春风面。\n照影溪桥情不浅。\n羌管声中，叠恨传幽怨。\n陇首人归芳信断。\n万重云水江南远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12222, '蝶恋花', '赵师侠', '夜雨鸣檐声录蔌。\n薄酒浇愁，不那更筹促。\n感旧伤今难举目。\n无聊独剪西窗烛。\n弹指光阴如电速。\n富贵功名，本自无心逐。\n粝食粗衣随分足。\n此身安健他何欲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12223, '蝶恋花', '赵师侠', '春入园林新雨过。\n次第芳菲，惹起情无那。\n蜀锦青红初剪破。\n枝头点点胭脂颗。\n柳带随风金袅娜。\n隐映馀霞，灿灿红云堕。\n高烛夜寒光照坐。\n只□沈醉谁扶我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12224, '蝶恋花', '赵师侠', '解语花枝娇朵朵。\n不为伤春，爱把眉峰锁。\n宜笑精神偏一个。\n微涡媚靥樱桃破。\n先自腰肢常袅娜。\n更被新来，酒饮频过火。\n茶饭不犹自可。\n脸儿瘦得些娘大。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12225, '鹧鸪天', '赵师侠', '烟霭空江上春。\n夕阳芳草渡头情。\n飞红已逐东风远，嫩绿还因夜雨深。\n情脉脉，思沈沈。\n卷帘愁与暮云平。\n栏干倚遍东西曲，杜宇一声肠断人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12226, '鹧鸪天', '赵师侠', '玉带红花供奉班。\n裹头新样总宜男。\n闹装鞍辔青骢马，帖体衣裳紫窄衫。\n云鬓重，黛眉弯。\n内家妆束冠江南。\n轻裘缓带风流帅，锦绣丛花拥骑远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12227, '鹧鸪天', '赵师侠', '榕叶阴阴未著霜。\n浅寒犹试夹衣裳。\n雾浓烟重遥山暗。\n云淡天低去水长。\n风渐沥，景凄凉。\n乱鸦声里又斜阳。\n孤帆落处惊鸥鹭，飞映书空雁字行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12228, '鹧鸪天', '赵师侠', '一叶惊秋风露清。\n砌蛩初听傍窗声。\n人逢役鹊飞乌夜，桥渡牵牛织女星。\n银汉淡，暮云轻。\n新蟾斜挂一钩明。\n人间天上佳期处，凉意还从过雨生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12229, '鹧鸪天', '赵师侠', '风定江流似镜平。\n斜阳天外挂微明。\n云归远岫千山暝，雾映疏林一抹横。\n渔火细，钓丝轻。\n黄尘扑扑谩争荣。\n何时了却人间事，泛宅浮家过此生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12230, '鹧鸪天', '赵师侠', '妙曲清声压楚城。\n蕙心兰态见柔情。\n凌波隐称金莲步，蘸甲从教玉笋斟。\n歌缓缓，笑吟吟。\n向人真处可怜生。\n仙源幸有藏春处，何事乘风逐世尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12231, '鹧鸪天', '赵师侠', '爆竹声中岁又除。\n顿回和气满寰区。\n春风解绿江南树，不与人间染白须。\n残蜡烛，旧桃符。\n宁辞末後饮屠苏。\n归与幸有园林胜，次第花开可自娱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12232, '柳梢青', '赵师侠', '节物推移。\n青阳景变，玉灰飞。\n彩仗泥牛，星球雪柳，争报春回。\n丝金缕玉幡儿。\n更斜袅、东风应时。\n宜入新春，人随春好，春与人宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12233, '柳梢青', '赵师侠', '红紫凋零。\n化工特地，剪玉裁琼。\n碧叶丛芳，檀心点素，香雪团英。\n柔风唤起娉婷。\n似无力、斜翠屏。\n细细吹香，盈盈露，花里倾城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12234, '柳梢青', '赵师侠', '漠漠轻阴。\n养花天气，乍暗还明。\n曲径风微，蜂迷红片，蝶趁游人。\n平芜极目青青。\n谩怅望、谁招断魂。\n柳外愁闻，莺雏唤友，鸠妇呼晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12235, '柳梢青', '赵师侠', '料峭馀寒。\n元宵欲过，灯火阑珊。\n宿酒难醒，新愁未解，摇兀吟鞍。\n深林百舌关关。\n更雨洗、桃红未乾。\n野烧痕青，荒陂水满，春事何堪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12236, '柳梢青', '赵师侠', '烟敛云收。\n夕阳斜照，暮色迟留。\n天接波光，水涵山影，都在扁舟。\n虚名白尽人头。\n问来往、何时是休。\n潮落潮生，吴山越岭，依旧临流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12237, '柳梢青', '赵师侠', '人间春足。\n一番红紫，水流风逐。\n戏蝶初闲，轻摇粉翅，高低飞扑。\n雨昏烟暝增明，似积雪、枝间映绿。\n后土琼芳，蓬莱仙伴，蕊粉香粟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12238, '柳梢青', '赵师侠', '矫首遐观。\n崇台徙倚，心目俱宽。\n一水萦蓝，群峰耸翠，天接高寒。\n平生江北江南。\n总未识、闽中好山。\n雨暗前汀，云生衣袂，身倦跻攀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12239, '柳梢青', '赵师侠', '暑怀烦郁。\n危栏徙倚，凝情独立。\n榕叶连阴，横罔接秀，壶峰凝碧。\n海山云树微茫，更无数、归帆暮集。\n却忆潇湘，孤村烟渚，晚风斜日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12240, '柳梢青', '赵师侠', '水满方塘。\n菰蒲深处，戏浴鸳鸯。\n灿锦舒霞，红幢绿盖，时递幽香。\n天弓摇挂孤光。\n映烟树、云间渺茫。\n散发披襟，都忘身世，真在仙乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12241, '柳梢青', '赵师侠', '浓碧抟枝，柔黄衬紫，独殿春风。\n菡萏轻盈，甘瓜馥郁，叶萼相重。\n人生一笑难同。\n更馀韵、都藏笑中。\n日助清芬，酒添风味，须与从容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12242, '浣溪沙', '赵师侠', '日丽风和春昼长。\n杏花枝上正芬芳。\n无情社雨亦何狂。\n一洗娇红啼嫩脸，半开新绿映残妆。\n画梁空有燕泥香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12243, '浣溪沙', '赵师侠', '落日沈沈堕翠微。\n断云轻逐晚风归。\n西山南浦画屏围。\n一目波光明欲溜，雨眉山色翠长低。\n须知人与景相宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12244, '浣溪沙', '赵师侠', '松雪纷纷落冻泥。\n栖禽犹困傍枝低。\n茅檐冰柱玉鞭垂。\n流水溅溅春意动，群山灿灿晓光迷。\n朔风寒日度云迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12245, '浣溪沙', '赵师侠', '不比阳关去路赊。\n使君行即返京华。\n清江江上是吾家。\n聚散有时思夜雨，留连无计劝流霞。\n红愁绿惨一川花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12246, '浣溪沙', '赵师侠', '雪絮飘池点绿漪。\n舞风游漾燕交飞。\n阴阴庭院日迟迟。\n一缕水沈香散後，半瓯新茗味回时。\nけ闲万事总忘机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12247, '浣溪沙', '赵师侠', '本是孤根傲雪霜。\n肌肤不肯铅黄。\n要随尘世浅匀妆。\n似杏著花尤灿灿，比梅成实自双双。\n青枝巧缀碧鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12248, '菩萨蛮', '赵师侠', '扁舟又向萧滩去。\n危墙却系江头树。\n风送雨声来。\n凉生真快哉。\n电光云际掣。\n白浪天相接。\n不用怯风波。\n风波平地多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12249, '菩萨蛮', '赵师侠', '娇花媚柳新妆靓。\n裙边微露双鸳并。\n笑靥最多情。\n春从两脸生。\n香罗萦皓腕。\n翠袖笼歌扇。\n馀韵遏云低。\n梁尘簌簌飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12250, '菩萨蛮', '赵师侠', '晚风断送归帆急。\n重城回首天连碧。\n犹有小楼情。\n西山如旧青。\n故园今渐近。\n应卜灯花信。\n一喜一牵萦。\n平分两处心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12251, '菩萨蛮', '赵师侠', '故人心尚如天远。\n故心人更何由见。\n肠断楚江头。\n泪和江水流。\n江流空滚滚。\n泪尽情无尽。\n不怨薄情人。\n人情逐处新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12252, '菩萨蛮', '赵师侠', '小春爱日融融暖。\n危亭望处晴岚满。\n江静绿回环。\n横陈无际山。\n清霜欺远树。\n黄叶风扶去。\n试探岭头梅。\n点红开未开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12253, '菩萨蛮', '赵师侠', '琼英为惜轻飞去。\n可人妙笔移缣素。\n潇洒向南枝。\n永无开谢时。\n闺房难并秀。\n自是春风手。\n何必问逃禅。\n人间水墨仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12254, '菩萨蛮', '赵师侠', '多情可是怜高节。\n濡毫幻出真清绝。\n雨叶共风枝。\n天寒人倚时。\n萧萧襟韵胜。\n堪与梅兄并。\n不用翠成林。\n坡仙曾赏音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12255, '菩萨蛮', '赵师侠', '霜风落木千山远。\n护霜云散晴曦暖。\n潇洒小旗亭。\n山花照眼明。\n粉妆匀未了。\n一捻春风小。\n把酒恨匆匆。\n深情妩媚中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12256, '菩萨蛮', '赵师侠', '行舟荡漾鸣双桨。\n江流为我添新涨。\n指顾隔汀洲。\n人归心尚留。\n阳关三叠举。\n怨柳离情苦。\n何似莫来休。\n不来无许愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12257, '菩萨蛮', '赵师侠', '故人话别情难已。\n故人此别何时会。\n江上驻危亭。\n离怀牵故情。\n悠悠东去水。\n簇簇渔村市。\n应记合江滨。\n潇湘别故人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12258, '菩萨蛮', '赵师侠', '西风又老潇湘树。\n翩翩黄叶辞枝去。\n斜日淡云笼。\n溪山烟霭中。\n危阑闲独倚。\n浪连天际。\n残角起江城。\n书空征雁横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12259, '菩萨蛮', '赵师侠', '东皇不受人间俗。\n为嫌花柳纷红绿。\n特地春和。\n连延雨雪多。\n梅梢封玉蕊。\n春半开犹未。\n还恐怨韶华。\n吹绵作柳花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12260, '菩萨蛮', '赵师侠', '水风叶底波光浅。\n亭亭翠叶红妆面。\n六月下塘春。\n平铺云锦屏。\n露凉轻点缀。\n绿映珍珠袂。\n浑似太真妃。\n倚阑娇困时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12261, '好事近', '赵师侠', '红杏已香残，唯有海棠堪惜。\n天气著花如酒，醉娇红无力。\n娉娉袅袅倚东风，柔媚忍轻摘。\n凭仗暮寒要住，赛锦川春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12262, '好事近', '赵师侠', '云度鹊成桥，青翼已传消息。\n彩仗蕊宫初下，应人问佳夕。\n龙烟缥渺散妆楼，香雾拥瑶席。\n准拟洞房披扇，看仙家春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12263, '醉蓬莱', '赵师侠', '正金风零露，玉宇生凉，晚秋天气。\n华渚流虹，应生商佳瑞。\n电绕神枢，庆绵宗社，御宝图宸极。\n脱屣尘凡，游心澹泊，逍遥物外。\n圣子神孙，祖皇文母，上接三宫，下通五世。\n至盛难名，亘古今无比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12264, '汉宫春', '赵师侠', '丹诏天飞，见皇家愿治，侧席英才。\n鸿儒抱负素蕴，壮志兴怀。\n文场战胜，便从此、脱迹蒿莱。\n人共羡，鹿鸣劝驾，还因计吏偕来。\n先春占早争开。\n是人间第一，唯有江梅。\n莆中旧传盛事，六亚三魁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12265, '厅前柳', '赵师侠', '晚秋天。\n过暮雨，云容敛，月澄鲜。\n正风露凄清处，砌蛩喧。\n更黄蝶。\n舞翩翩。\n念故里、千山云水隔，被名缰利锁萦牵。\n莫作悲秋意，对尊前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12266, '厅前柳', '赵师侠', '景清佳。\n正倦客，凝秋思。\n浩无涯。\n递十里香芬馥，桂初华。\n向碧叶。\n露芳葩。\n为粟粒、鹅儿情淡薄，倩西风染就丹砂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12267, '诉衷情', '赵师侠', '清和时候雨初晴。\n密树翠阴成。\n新篁嫩摇碧玉，芳径绿苔深。\n雏燕语，乳莺声。\n暑风轻。\n帘旌微动，沈篆烟消，午枕馀清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12268, '诉衷情', '赵师侠', '神功圣德妙难量。\n灵应著莆阳。\n湄洲自昔仙境，宛在水中央。\n孚惠爱，备祈禳。\n降嘉祥。\n云车风马，来歆，桂酒椒浆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12269, '诉衷情', '赵师侠', '茫茫云海浩无边。\n天与谁相连。\n舳舻万里来往，有祷必安全。\n专掌握，雨权。\n属丰年。\n琼卮玉醴，飨此精诚，福庆绵绵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12270, '诉衷情', '赵师侠', '威灵千里护封圻。\n十万户归依。\n白湖宫殿云耸，香火尽虔祈。\n倾寿酒，诵声诗。\n谅遥知。\n民康俗阜，雨润风滋，功与天齐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12271, '一翦梅', '赵师侠', '雪里盈盈玉破花。\n遐想风流，压尽京华。\n点酥团粉任斜。\n独露春妍谁似他。\n有酒何须稚子赊。\n访戴归来，倚棹溪涯。\n人生得意定谈夸。\n除却西湖，不计谁家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12272, '一翦梅', '赵师侠', '暖日烘梅冷未苏。\n脱叶随风，独见枯株。\n先春占早又何如。\n玉点枝头，犹自萧疏。\n江北江南景不殊。\n雪里花清，月下香浮。\n他年调鼎费工夫。\n且与藏春，处士西湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12273, '朝中措', '赵师侠', '斜阳留照有馀红。\n烟霭淡冥。\n麦陇青摇一望，前山翠失双峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12274, '朝中措', '赵师侠', '疏疏帘幕映娉婷。\n初试晓妆新。\n玉腕云边缓转，修蛾波上微颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12275, '朝中措', '赵师侠', '西风著意送归船。\n家近总欣然。\n去日梅开烂漫，归时秋满山川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12276, '朝中措', '赵师侠', '乱山春过雪成堆。\n七里递香回。\n蕊簇玲珑金粟，花装碎屑玫瑰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12277, '朝中措', '赵师侠', '开随律度芳辰。\n鲜艳见天真。\n不比浮花浪蕊，天教月月常新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12278, '朝中措', '赵师侠', '眉间黄色喜何如。\n花县拜恩初。\n五品荣颁命服，十行祗奉天书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12279, '点绛唇', '赵师侠', '日暖风喧，殿春琼蕊依台榭。\n雪堆花架。\n不用丹青写。\n莹彻精神，映月唯宜夜。\n香帕。\n倩风扶下。\n碎玉残妆卸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12280, '点绛唇', '赵师侠', '漠漠春阴，褪花时候馀寒峭。\n数声啼鸟。\n唤起帘栊晓。\n云鬓慵梳，淡拂春山小。\n情多少。\n乱萦愁抱。\n风里垂杨袅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12281, '点绛唇', '赵师侠', '袅袅娉娉，可人尤赛娘风韵。\n花娇玉润。\n一捻春期近。\n占路藏机，已向棋中进。\n俱休问。\n酒旗花阵。\n早晚争先胜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12282, '扑蝴蝶', '赵师侠', '清和时候，薰风来小院。\n琅脱箨，方塘荷翠。\n柳丝轻度流莺，画栋低飞乳燕。\n园林绿阴初遍。\n景何限。\n轻纱细葛，纶巾和羽扇。\n披襟散发，心清尘不染。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12283, '醉桃源・阮郎归', '赵师侠', '微云扫尽碧虚宽。\n月华光影寒。\n山河表里鉴中看。\n沈沈清夜阑。\n风细细，露。\n神游八极间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12284, '醉桃源・阮郎归', '赵师侠', '纤枝延蔓走青虬。\n风清体更柔。\n故绕檀蕊著花稠。\n疏疏如缀旒。\n琼作靥，玉成裘。\n玫瑰应辈流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12285, '醉桃源・阮郎归', '赵师侠', '杜鹃花发映山红。\n韶光觉正浓。\n水流红紫各西东。\n绿肥春已空。\n闲戏蝶，懒游蜂。\n破除花影重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12286, '贺圣朝', '赵师侠', '千林脱落群芳息。\n有一枝先白。\n孤标疏影压花丛，更清香堪惜。\n吟情无尽，赏音未已，早纷纷藉藉。\n想贪结子去调羹，任叫云横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12287, '踏莎行', '赵师侠', '白云开残，红云吹尽。\n园林新绿迷芳径。\n榆钱不解青春，随风乱点苍苔晕。\n紫燕飞忙，黄鹂声嫩。\n日长烟暖游蜂困。\n凭高念远思无穷，那堪宿酒厌厌病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12288, '踏莎行', '赵师侠', '万事随缘，一身须正。\n功名富贵皆前定。\n多图广计要争强，如何人力将天胜。\n枉费机谋，徒劳奔竞。\n到头毕竟由他命。\n安时处顺得心闲，饥餐困寝亏贤甚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12289, '忆秦娥', '赵师侠', '伤离索。\n不堪凉月穿珠箔。\n穿珠箔。\n料应别後，粉销琼削。\n无聊倚遍西楼角。\n枝头几误惊飞鹊。\n惊飞鹊。\n先来憔悴，更逢摇落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12290, '武陵春', '赵师侠', '一阵晓风花信早，先到小桃枝。\n冉冉红云映翠微。\n开宴忆瑶池。\n零乱分飞贪结子，芳径自成蹊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12291, '武陵春', '赵师侠', '乍雨笼晴云不定，芳草绿纤柔。\n燕语莺啼小院幽。\n春色二分休。\n试凭危栏凝远目，山与水光浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12292, '清平乐', '赵师侠', '无风轻燕。\n缭绕深深院。\n昼永人闲帘不卷。\n时听莺簧巧啭。\n清和天气阴阴。\n南风初奏薰琴。\n唤起午窗新梦，愁添一掬归心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12293, '清平乐', '赵师侠', '一宵风雨。\n春与人俱去。\n春解再来花作主。\n只有行人无据。\n殷勤满酌离觞。\n阳关唱起愁肠。\n苦恨无情杜宇，声声叫断斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12294, '清平乐', '赵师侠', '纤娇小。\n也解争春早。\n占得中央颜色好。\n装点枝枝新巧。\n东皇初到江城。\n殷勤先去迎春。\n乞与黄金腰带，压持红紫纷纷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12295, '鹊桥仙', '赵师侠', '风波平地，尘埃扑面，总是争名竞利。\n悟时不必苦贪图，但言任、流行坎止。\n忽来忽去，何荣何辱，天也知人深意。\n一帆风送过桐江，喜跳出、琉璃井里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12296, '鹊桥仙', '赵师侠', '同云幕幕，狂风浩浩，激就六花飞下。\n山川满目白模糊，更茅舍、溪桥潇洒。\n玉田银界，瑶林琼树，光映乾坤不夜。\n行人不为旅人忙，怎解识、天然图画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12297, '鹊桥仙', '赵师侠', '春光已暮，花残叶密，更值无情风雨。\n斜阳芳树翠烟中，又听得、声声杜宇。\n血流无用，离魂空断，只挠凄凉为旅。\n在家谁道不如归，你何似、随风归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12298, '鹊桥仙', '赵师侠', '明河风细，鹊桥云淡，秋入庭梧先坠。\n摩孩罗荷叶伞儿轻，总排列、双双对对。\n花瓜应节、蛛丝卜巧，望月穿针楼外。\n不知谁见女牛忙，谩多少、人间欢会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12299, '谒金门', '赵师侠', '风和雨。\n又送一番春去。\n春去不知何处住。\n惜春无觅处。\n柳老空抟香絮。\n莺娇乍迁芳树。\n回念故园如旧否。\n不堪闻杜宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12300, '谒金门', '赵师侠', '江水绿。\n江山数峰如簇。\n唤渡小舟来岸北。\n笋舆行太速。\n素艳窗纱笼玉。\n埠负看花心目。\n今夜知他何处宿。\n断魂沙路曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12301, '谒金门', '赵师侠', '沙畔路。\n记得旧时行处。\n蔼蔼疏烟迷远树。\n野航横不渡。\n竹里疏花梅吐。\n照眼一川鸥鹭。\n家在清江江上住。\n水流愁不去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12302, '谒金门', '赵师侠', '风雨急。\n红紫又还狼藉。\n嫩绿团枝苔径湿。\n帘开双燕入。\n院静昼闲人寂。\n一缕水沈烟直。\n心事有谁能会得。\n阶前芳草碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12303, '谒金门', '赵师侠', '风策策。\n山迥暮烟横白。\n淅沥穿林翻败叶。\n羁怀愁倦客。\n问宿荒村山驿。\n谁识离情脉脉。\n雁足无书孤夜色。\n音尘千里隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12304, '谒金门', '赵师侠', '花夜雨。\n渺渺绿波南浦。\n擘絮晴云山外吐。\n凝情谁共语。\n十二玉梯空伫。\n闲却琐窗朱户。\n久客念归归未许。\n寸心愁万缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12305, '谒金门', '赵师侠', '风雨半。\n春锁绿杨深院。\n幕浪不翻香穗卷。\n轻寒闲便面。\n归兴新来不浅。\n勾引闲愁撩乱。\n一枕春酲谁与管。\n晓莺惊梦断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12306, '东坡引', '赵师侠', '相看情未足。\n离觞已催促。\n停歌欲语眉先蹙。\n何期归太速。\n如今去也，无计追逐。\n怎忍听、阳关曲。\n扁舟後夜滩头宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12307, '东坡引', '赵师侠', '飞花红不聚。\n都因夜来雨。\n枝头冷落情如许。\n东风谁是主。\n看看满地，堆却香絮。\n但目断、章台路。\n残英剩蕊留春住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12308, '东坡引', '赵师侠', '杯行情意密。\n今宵是何夕。\n行人此别真堪惜。\n愁肠空闷郁。\n明朝去也，回首相忆。\n要留恋、如何得。\n无端骤雨飘何急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12309, '生查子', '赵师侠', '梅从陇首传，柳向邮亭折。\n鸳瓦晓霜浓，掠面凝寒色。\n相逢意便亲，欲去如何说。\n我亦是行人，更与行人别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12310, '生查子', '赵师侠', '千山拥翠屏，一水萦罗带。\n雨过水痕添，云散山容在。\n亭高景最幽，天回风尤快。\n啼鸟一声闲，唤起情无奈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12311, '生查子', '赵师侠', '迟迟春昼长，冉冉东风软。\n寒食乍晴天，红紫芳菲遍。\n前峰积翠横，新涨蓝远。\n向晚淡烟迷，一段屏山展。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12312, '生查子', '赵师侠', '春光不肯留，风雨催将去。\n红逐故园尘，绿满江南树。\n阴晴寒食天，寂寞西郊路。\n芳草织新愁，怅望人何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12313, '生查子', '赵师侠', '庭虚任雀喧，院静无人到。\n回首十年非，赖得知几早。\n心随香篆销，意与梅花好。\n万事转头空，一笑吾身老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12314, '少年游', '赵师侠', '玉壶冰结暮天寒。\n朔吹绕阑干。\n雪破梢头，香传花外，春信入江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12315, '少年游', '赵师侠', '冰霜凝冻腊残时。\n暖律渐推移。\n彩胜罗幡，土牛春杖，和气与春回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12316, '小重山', '赵师侠', '乐岁农家喜夜春。\n朝来收宿雾，快新晴。\n云移日转午风轻。\n香罗薄，喧暖困游人。\n积水满春塍。\n绿波翻郁郁，露秧针。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12317, '霜天晓角', '赵师侠', '雨馀风劲。\n雾重千山暝。\n茅舍寒林相映。\n分明是、图画景。\n去程何日定。\n天远长安近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12318, '霜天晓角', '赵师侠', '舣舟砂碛。\n秋净波澄碧。\n极目青山横远，悬崖断、拥苍壁。\n傍岩渔艇集。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12319, '江南好・忆江南', '赵师侠', '天共水，水远与天连。\n天净水平寒月漾，水光月色两相兼。\n月映水中天。\n人与景，人景古难全。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12320, '关河令・清商怨', '赵师侠', '亭皋霜重飞叶满。\n听西风断雁。\n闲凭危阑，斜阳红欲敛。\n行人归期太晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12321, '关河令・清商怨', '赵师侠', '江头伊轧动柔橹。\n渐楚天欲暮。\n浩荡轻鸥，波间自容与。\n岸蓼汀苹无绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12322, '采桑子', '赵师侠', '连朝雨骤驱春去，瓦注盆倾。\n不记初春。\n润柳催花忒有情。\n春光解有重来日，宁耐休争。\n待得秋深。\n听你无聊点滴声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12323, '采桑子', '赵师侠', '梅花谢後樱花绽，浅浅匀红。\n试手天工。\n百卉千葩一信通。\n馀寒未许开舒妥，怨雨愁风。\n结子筠笼。\n万颗匀圆讶许同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12324, '浪淘沙', '赵师侠', '绛萼衬轻红。\n缀簇玲珑。\n夭桃繁李一时同。\n独向枝头春意闹，娇倚东风。\n飞片入帘栊。\n粉淡香浓。\n凤箫声断月明中。\n只恐明朝风雨恶，燕嘴泥融。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12325, '浪淘沙', '赵师侠', '桃萼正芳菲。\n初占春时。\n蒸霞灿锦望中迷。\n斜出繁枝临曲沼，鸾鉴妆迟。\n蜂蝶镇相依。\n天气融怡。\n空教追忆武陵溪。\n片片漫随流水去，风暖烟霏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12326, '浪淘沙', '赵师侠', '摇曳万丝风。\n轻染烟浓。\n鹅黄初褪绿茸茸。\n雨洗云娇春向晚，雪絮空。\n车马灞桥中。\n别绪匆匆。\n只知攀折怨西东。\n不道晓风残月岸，离恨无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12327, '双头莲令', '赵师侠', '太平和气兆嘉祥。\n草木总成双。\n红苞翠盖出横塘。\n两两斗芬芳。\n干摇碧玉并青房。\n仙髻拥新妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12328, '画堂春', '赵师侠', '西真仙子宴瑶池。\n素裳琼艳冰肌。\n瑞笼香雾扑铢衣。\n凤翥鸾飞。\n玉骨解凌风露，铅华不凝脂。\n戍楼羌管正孤吹。\n月淡烟低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12329, '南柯子・南歌子', '赵师侠', '木落千山瘦，风微一水澄。\n清霜暖日快归程。\n唤渡沙头、款款话离情。\n傍岸渔舟集，横空雁字轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12330, '西江月', '赵师侠', '笳鼓旌旗改色，弓刀铠甲增明。\n攒花簇队马蹄轻。\n禀听元戎号令。\n羊轻裘临阵，亚夫细柳屯营。\n观瞻已耸定王城。\n飞虎威名日振。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12331, '西江月', '赵师侠', '淼淼澄清波面，依依紫翠山光。\n危栏徙倚对斜阳。\n山影波流荡漾。\n世事一番醒醉，人生几度炎凉。\n高情收拾付觥觞。\n何止羲皇人上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12332, '洞仙歌', '赵师侠', '元宵三五。\n正好嬉游去。\n梅柳蛾蝉斗济楚。\n换鞋儿、添头面，只等黄昏，恰恨有、些子无情风雨。\n心忙腹热，没顿浑身处。\n急把灯台炙艾炷。\n做匙婆、许葱油，麦灰画葫芦，更漏转，越不停不住。\n待归去、尤自意迟疑，但无语空将，眼儿厮觑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12333, '南乡子', '赵师侠', '元夜景尤殊。\n万斛金莲照九衢。\n锤拍豉汤都卖得，争如。\n甘露杯中万颗珠。\n应是著功夫。\n脑麝浓薰费小厨。\n不比七夕黄蜡做，知无。\n要底圆儿糖上浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12334, '行香子', '赵师侠', '春日迟迟。\n春景熙熙。\n渐郊原、芳草萋萋。\n夭桃灼灼，杨柳依依。\n见燕喃喃，蜂簇簇，蝶飞飞。\n闲庭寂寂，曲沼漪漪。\n更秋千、红索垂垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12335, '卜算子', '赵师侠', '晴日敛春泥，陌上东风软。\n料峭寒禁花柳闲，枉恨春工浅。\n绿涨一江深，黛泼千山远。\n目断平芜无际愁，数尽征鸿点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12336, '卜算子', '赵师侠', '杨柳褪金丝，艳杏摇红影。\n欲雨还晴二月天，春色浑无定。\n晓梦不堪惊，午昼新来永。\n一掬归心万叠愁，空惹长亭恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12337, '卜算子', '赵师侠', '娇艳醉杨妃，轻袅怜飞燕。\n人在昭阳睡足时，初试妆深浅。\n一段锦新裁，万里来何远。\n高烛休教照夜寒，媚脸融春艳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12338, '卜算子', '赵师侠', '绿暗柳藏烟，红淡花经雨。\n更著如花似玉人，艳态娇波注。\n纤手捧瑶卮，缓遏歌云缕。\n只恐莺花不解留，还逐东风去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12339, '卜算子', '赵师侠', '云敛料寒轻，雨涨春波渺。\n旅枕无堪梦易惊，啼声催晓。\n尚忆故园花，红紫为容好。\n世路崎岖长短亭，来往何时了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12340, '伊州三台', '赵师侠', '桂华移自云岩。ピ\n更被灵砂染丹。ピ\n清露湿酡颜。ピ\n醉乘风、下临世间。ピ\n素娥襟韵萧闲。ピ\n不与群芳并看。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12341, '水调歌头', '陈亮', '不见南师久，谩说北群空。\n当场只手，毕竟还我万夫雄。\n自笑堂堂汉使，得似洋洋河水，依旧只流东。\n且复穹庐拜，会向藁街逢。\n尧之都，舜之壤，禹之封。\n於中应有，一个半个耻臣戎。\n万里腥膻如许，千古英灵安在，磅礴几时通。\n胡运何须问，赫日自当中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12342, '念奴娇', '陈亮', '江南春色，算来是、多少胜游清赏。\n妖冶廉纤，只做得，飞鸟向人偎傍。\n地辟天开，精神朗慧，到底还京样。\n人家小语，一声声近清唱。\n因念旧日山城，个人如画，已作州中想。\n邓禹笑人无限也，冷落不堪惆怅。\n秋水双明，高山一弄，著我些悲壮。\n南徐好住，片帆有分来往。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12343, '贺新郎', '陈亮', '修竹更深处。\n映帘栊、清阴障日，坐来无暑。\n水激泠泠如何许。\n跳碎危栏玉树。\n都不系、人间朝暮。\n东阁少年今老矣，况樽中有酒嫌推去。\n犹著我，明流语。\n大家绿野陪容与。\n算等闲、过了薰风，又还商素。\n手弄柔条人健否，尤忆当时雅趣。\n恩未报、恐成辜负。\n举目江河休感涕，念有君如此何愁虏。\n歌未罢，谁来舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12344, '满江红', '陈亮', '曾洗乾坤，问何事、雄图顿屈。\n试著眼、阶除当下，又添英物。\n北向争衡幽愤在，南来遗恨狂酋失。\n算凄凉部曲几人存，三之一。\n诸老尽，郎君出。\n恩未报，家何恤。\n念横飞直上，有时还戢。\n笑我只知存饱暖，感君元不论阶级。\n休更上百尺旧家楼，尘侵帙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12345, '桂枝香', '陈亮', '天高气肃。\n正月色分明，秋容新沐。\n桂子初收，三十六宫都足。\n不辞散落人间去，怕群花、自嫌凡俗。\n向他秋晚，唤回春意，几曾幽独。\n是天上、馀香剩馥。\n怪一树香风，十里相续。\n坐对花旁，但见色浮金粟。\n芙蓉只解添秋思，况东篱、凄凉黄菊。\n入时太浅，背时太远，爱寻高躅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12346, '三部乐', '陈亮', '小屈穹庐，但二满三平，共劳均佚。\n人中龙虎，本为明时而出。\n只合是、端坐王朝，看指挥整办，扫荡飘忽。\n也持汉节，聊过旧家宫室。\n西风又还带暑，把征衫著上，有时披拂。\n休将看花泪眼，闻弦□骨。\n对遗民、有如皎日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12347, '水调歌头', '陈亮', '人物从来少，篱菊为谁黄。\n去年今日，倚楼还是听行藏。\n未觉霜风无赖，好在月华如水，心事楚天长。\n讲论参洙泗，杯酒到虞唐。\n人未醉，歌宛转，兴悠扬。\n太平胸次，笑他磊欲成狂。\n且向武夷深处，坐对云烟开敛，逸思如微茫。\n我欲为君寿，何许得新腔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12348, '念奴娇', '陈亮', '危楼远望，叹此意、今古几人曾会。\n鬼设神施，浑认作、天限南疆北界。\n一水横陈，莲岗三面，做出争雄势。\n六朝何事，只成门户私计。\n因笑王谢诸人，登高怀远，也学英雄涕。\n凭却长江管不到，河洛腥膻无际。\n正好长驱，不须反顾，寻取中流誓。\n小儿破贼，势成宁问疆场。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12349, '贺新郎', '陈亮', '老去凭谁说。\n看几番、神奇臭腐，夏裘冬葛。\n父老长安今馀几，後死无仇可雪。\n犹未燥、当时生发。\n二十五弦多少恨，算世间、那有平分月。\n胡妇弄，汉宫瑟。\n树犹如此堪重别。\n只使君、从来与我，话头多合。\n行矣置之无足问，谁唤妍皮痴骨。\n但莫使、伯牙弦绝。\n九转丹砂牢拾取，管精金、只是寻常铁。\n龙共虎，应声裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12350, '瑞云浓慢', '陈亮', '蔗浆酪粉，玉壶冰醑，朝罢更闻宣赐。\n去天咫尺，下拜再三，幸今有母可遗。\n年年此日，共道月入怀中最贵。\n向暑天，正风云会遇，有恁嘉瑞。\n鹤冲霄，鱼得水。\n一超便、直入神仙地。\n植根江表。\n开拓两河，做得黑头公未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12351, '阮郎归', '陈亮', '波光渺渺浸晴陂。\n有亭湖岸西。\n芰荷香拂柳丝垂。\n升堂献寿卮。\n红约腕，绿侵衣。\n愿祝届期颐。\n花间妙语欲无诗。\n一年歌一词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12352, '祝英台近', '陈亮', '驾扁舟，冲剧暑。\n千里江上去。\n夜宿晨兴，一一旧时路。\n百年望了旬头，被人馋破，故纸里、是争雄处。\n怎生诉。\n欲待细与分疏，其如有凭据。\n包裹生鱼，活底怎遭遇。\n相逢樽酒何时，征衫容易，君去也、自家须住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12353, '蝶恋花', '陈亮', '手拈黄花还自笑。\n笑比渊明，莫也归来早。\n随世功名浑草草。\n五湖却共繁华老。\n冷淡家生冤得道。\n旖旎妖娆，春梦如今觉。\n管个岁华须到了。\n此花之後花应少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12354, '水调歌头', '陈亮', '人爱新来景，龙认旧时湫。\n不论三伏，小住便觉凛生秋。\n我自醉眠其上，任是水流其下，湍激若为收。\n世事如斯去，不去为谁留。\n本无心，随所寓，触虚舟。\n东山始末，且向灵洞与沈浮。\n料得神仙窟穴，争似提封万里，大小几琉球。\n但有君才具，何用问时流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12355, '念奴娇', '陈亮', '西风带暑，又还是、长途利牵名役。\n我已无心，君因甚，更把青衫为客。\n邂逅卑飞，几时高举，不露真消息。\n大家行处，到头须管行得。\n何处寻取狂徒，可能著意，更问渠侬骨。\n天上人间，最好是、闹里一般岑寂。\n瀛海无波，玉堂有路，稳著青霄翼。\n归来何事，眼光依旧生碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12356, '卜算子', '陈亮', '悄静菊花天，洗尽梧桐雨。\n倍九周遭烂熳开，祝寿当头取。\n顶戴玉袍黄，叠秀金棱吐。\n仙种花容晚节香，人愿争先睹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12357, '贺新郎', '陈亮', '离乱从头说。\n爱吾民，金缯不爱，蔓藤累葛。\n壮气尽消人脆好，冠盖阴山观雪。\n亏杀我，一星星发。\n涕出女吴成倒转，问鲁为齐弱何年月。\n丘也幸，由之瑟。\n斩新换出旗麾别。\n把当时、一椿大义，拆开收合。\n据地一呼吾往矣，万里摇肢动骨。\n这话霸、又成痴绝。\n天地洪炉谁扇，算於中、安得长坚铁。\n淝水破，关东裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12358, '垂丝钓', '陈亮', '菊花细雨。\n萧萧红蓼汀渚。\n景物渐幽，风致如许。\n秋未暮。\n又值吾初度。\n看天宇。\n正澄清欲往，登高未也，红尘当面飞舞。\n几人吊古。\n乌帽牢收取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12359, '彩凤飞', '陈亮', '人立玉，天如水，特地如何撰。\n海南沈烧著，欲寒犹暖。\n算从头，有多少、厚德阴功，人家上，一一旧时香案。\n经惯。\n小驻吾舟才尔，依然欢声满。\n莫也教、公子王孙眼见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12360, '鹧鸪天', '陈亮', '落魄行歌记昔游。\n头颅如许尚何求。\n心肝吐尽无馀事，口腹安然岂远谋。\n才怕暑，又伤秋。\n天涯梦断有书不。\n大都眼孔新来浅，羡尔微官作计周。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12361, '谒金门', '陈亮', '新雨足。\n洗尽山城袢褥。\n见说好峰三十六。\n峰峰如立玉。\n四海英游追逐。\n事业相时伸缩。\n入境德星须做福。\n只愁金诏趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12362, '天仙子', '陈亮', '一夜秋光先著柳。\n暑力平明羞失守。\n西风不放入帘帏，饶永昼。\n沈烟透。\n半月十朝秋定否。\n指点芙蕖凝伫久。\n高处成莲深处藕。\n百年长共月团圆，女进男，酒称寿。\n一点浮云人似旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12363, '水调歌头', '陈亮', '事业随人品，今古几麾旌。\n向来谋国，万事尽出汝书生。\n安识鲲鹏变化，九万里风在下，如许上南溟。\n斥旁边笑，河汉一头倾。\n叹世间，多少恨，几时平。\n霸图消歇，大家创见又成惊。\n邂逅汉家龙种，正尔乌纱白，驰骛觉身轻。\n樽酒从渠说，双眼为谁明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12364, '洞仙歌', '陈亮', '秋容一洗，不受凡尘。\n许大乾坤这回大。\n向上头，些子是雕鹗抟空，篱底下，只有黄花几朵。\n骑鲸汗慢，那得人同坐。\n赤手丹心扑不破。\n问唐虞、禹汤文武，多少功名，犹自是、一点浮云铲过。\n且烧却、一瓣海南沈，任拈取、千年陆沈奇货。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12365, '祝英台近', '陈亮', '嫩寒天，金气雨，揽断一秋事。\n仝样霏微，远作小晴意。\n世间万宝都成，些儿无欠，只待与、黄花为地。\n好招致。\n对此郁郁葱葱，新未成醉。\n翻手为云，造物等儿戏。\n也知富贵来时，一班呈露，便做出人中祥瑞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12366, '踏莎行', '陈亮', '书册如仇，旧游浑讳。\n有怀不断人应异。\n千山上去梦魂轻，片帆似下蛮溪水。\n已共酒杯，长坚海誓。\n见君忽忘花前醉。\n从来解事苦无多，不知解到毫芒未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12367, '南乡子', '陈亮', '人物满东瓯。\n别我江心识俊游。\n北尽平芜南似画，中流。\n谁系龙骧万斛舟。\n去去几时休。\n犹自潮上更来头。\n醉墨淋漓人感旧，离愁。\n一夜西风似夏不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12368, '三部乐', '陈亮', '入脚西风，渐去去来来，早三之一。\n春花无数，毕竟何如秋实。\n不须待、名品如麻，试为君屈指，是谁层出。\n十朝半月，争看抟空霜鹘。\n从来别真共假，任盘根错节，更饶仓卒。\n还他济时好手，封侯奇骨。\n没些儿、姗勃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12369, '贺新郎', '陈亮', '话杀浑闲说。\n不成教、齐民也解，为伊为葛。\n樽酒相逢成二老，却忆去年风雪。\n新著了、几茎华发。\n百世寻人犹接踵，叹只今两地三人月。\n写旧恨，向谁瑟。\n男儿何用伤离别。\n况古来、几番际会，风从云合。\n千里情亲长晤对，妙体本心次骨。\n卧百尺、高楼斗绝。\n天下适安耕且老，看买犁卖剑平家铁。\n壮士泪，肺肝裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12370, '点绛唇', '陈亮', '一夜相思，水边清浅横枝瘦。\n小窗如昼。\n情共香俱透。\n清入梦魂，千里人长久。\n君知否。\n雨人。\n格调还依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12371, '点绛唇', '陈亮', '电绕璇枢，此时昌运生真主。\n庆聊簪组。\n喜气生绵宇。\n宴启需云，湛露恩均布。\n锵韶。\n凤歌鸾舞。\n玉飞香醑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12372, '点绛唇', '陈亮', '碧落蟠桃，春风种在琼瑶苑。\n几回花绽。\n一子千年见。\n香染丹霞，摘向流虹旦。\n深深愿。\n万年天算。\n玉颗常来献。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12373, '点绛唇', '陈亮', '烟雨楼台，晓来独上无滋味。\n落花流水。\n掩映渔樵市。\n酒圣诗狂，只遣愁无计。\n频凝睇。\n问人天际。\n曾见归舟未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12374, '南歌子', '陈亮', '池草抽新碧，山桃褪小红。\n寻春闲过小园东。\n春在乱花深处、鸟声中。\n游镫归敲月，春衫醉舞风。\n谁家三弄学元戎。\n吹起闲愁，容易上眉峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12375, '好事近', '陈亮', '篱菊吐寒花，香弄小园秋色。\n携手画阑西畔，忆去年同摘。\n小亭依旧锁西风，往事已无迹。\n懒向碧云深处，问征鸿消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12376, '好事近', '陈亮', '横玉叫清宵，帘外月侵残烛。\n人在画楼高处，倚阑干几曲。\n穿云裂石韵悠扬，风细断远续。\n惊落小梅香粉，点一庭苔绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12377, '好事近', '陈亮', '的两三枝，点破暮烟苍碧。\n好在屋檐斜入，傍玉奴横笛。\n月华如水过林塘，花阴弄苔石。\n欲向梦中飞蝶，恐幽香难觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12378, '浣溪沙', '陈亮', '小雨翻花落画檐。\n栏堂香注酒重添。\n花枝能语出朱帘。\n缓步金莲移小小，持杯玉笋露纤纤。\n此时谁不醉厌厌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12379, '采桑子', '陈亮', '桃花已作东风笑，小蕊嫣然。\n春色暄妍。\n缓步烟霞到洞天。\n一杯满泻蒲桃绿，且共留连。\n醉倒花前。\n也占红香影里眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12380, '朝中措', '陈亮', '蓼花风淡水云纤。\n倚阁卷重帘。\n索寞败荷翠减，萧疏晚□红添。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12381, '柳梢青', '陈亮', '柳丝烟织。\n掩映小池，鳞鳞波碧。\n几片飞花，半檐残雨，长亭愁寂。\n凭高望断江南，怅千里、疏烟淡日。\n斗草风流，弄梅情分，教人思忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12382, '浪淘沙', '陈亮', '霞尾卷轻绡。\n柳外风摇。\n断虹低系碧山腰。\n古往今来离别地，烟水迢迢。\n归雁下平桥。\n目断魂销。\n夕阳无限满江皋。\n杨柳杏花相对晚，各自无聊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12383, '浪淘沙', '陈亮', '院落晓风酸。\n春如西园。\n芳英吹破玉阑干。\n墙外红尘飞不到，彻骨清寒。\n清浅小堤湾。\n瘦竹团栾。\n水光疏影有无间。\n仿佛浣沙溪上见，波面云鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12384, '小重山', '陈亮', '碧幕霞绡一缕红。\n槐枝啼宿鸟，冷烟浓。\n小楼愁倚画阑东。\n黄昏月，一笛碧云风。\n往事已成空。\n梦魂飞不到，楚王宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12385, '转调踏莎行・踏莎行', '陈亮', '洛浦尘生，巫山梦断。\n旗亭烟草里，春深浅。\n梨花落尽，荼シ又绽。\n天气也似，寻常庭院。\n向晚情怀，十分恼乱。\n水边佳丽地，近前细看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12386, '品令', '陈亮', '潇洒林塘暮。\n正迤逦、香风度。\n一番天气，又添作琼枝玉树。\n粉蝶无踪，疑在落花深处。\n深沈庭院，也卷起、重帘否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12387, '最高楼', '陈亮', '春乍透，香早暗偷传。\n深院落，斗清妍。\n紫檀枝似流苏带，黄金须胜辟寒钿。\n更朝朝，琼树好，笑当年。\n花不向沈香亭上看。\n树不著唐昌宫里玩。\n衣带水，隔风烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12388, '青玉案', '陈亮', '武陵溪上桃花路。\n见征骑、匆匆去。\n嘶入斜阳芳草渡。\n读书窗下，弹琴石上，留得销魂处。\n落花冉冉春将暮。\n空写池塘梦中句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12389, '诉衷情', '陈亮', '独凭江槛思悠悠。\n斜日堕林邱。\n鸳鸯属玉飞处，急桨荡轻舟。\n红蓼岸，白苹洲。\n夜来秋。\n数声渔父，一曲水仙，歌断还愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12390, '南乡子', '陈亮', '风雨满苹洲。\n绣阁银屏一夜秋。\n当日袜尘何处去，溪楼。\n怎对烟波不泪流。\n天际自归舟。\n浪卷涛翻一叶浮。\n也似我侬魂不定，悠悠。\n宋玉方悲庾信愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12391, '一丛花', '陈亮', '冰轮斜辗镜天长。\n江练隐寒光。\n危阑醉倚人如画，隔烟村、何处鸣。\n乌鹊倦栖，鱼龙惊起，星斗挂垂杨。\n芦花千顷水微茫。\n秋色满江乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12392, '清平乐', '陈亮', '银屏绣阁。\n不道鲛绡薄。\n嘶骑匆匆尘漠漠。\n远过夕阳村落。\n乱山千叠无情。\n今宵遮断愁人。\n两处香消梦觉，一般晓月秋声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12393, '渔家傲', '陈亮', '漠漠平沙初落雁。\n黄花浊酒情何限。\n红日渐低秋渐晚。\n听客劝。\n金荷莫诉真珠满。\n坐上少年差气岸。\n题诗落帽从来惯。\n戏马龙山当日燕。\n真奇观。\n尊前未觉风流远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12394, '丑奴儿・采桑子', '陈亮', '黄昏山驿销魂处，枝亚疏篱。\n枝亚疏离。\n酝藉香风蜜打围。\n隔篱鸡犬谁家舍，门掩斜晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12395, '滴滴金', '陈亮', '断桥雪霁闻啼鸟。\n对林花、弄晴晓。\n画角吹香客愁醒，见梢头红小。\n团酥剪蜡知多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12396, '七娘子', '陈亮', '风流家世传张绪。\n似灵和新种垂杨缕。\n绮席词，银台奏赋。\n当年梦绕蓬山路。\n卖花声断蓝桥暮。\n记吟鞭醉帽曾经处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12397, '醉花阴', '陈亮', '峻极云端潇洒寺。\n赋我登高意。\n好景属清游，玉友黄花，谩续龙山事。\n秋风满座芝兰媚。\n杯酒随宜醉。\n行乐任天真，一笑和同，休问无携妓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12398, '醉花阴', '陈亮', '姓名未勒慈恩寺。\n谁作山林意。\n杯酒且同欢，不许时人，轻料吾曹事。\n可怜风月於人媚。\n那对花前醉。\n珍重主人情，闻说当年，宴出红妆妓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12399, '汉宫春', '陈亮', '雪月相投。\n看一枝才爆，惊动香浮。\n微阳未放线路，说甚来由。\n先天一着，待辟开、多少旬头。\n却引取，春工入脚，争教消息停留。\n官不容针时节，做一般孤瘦，无限清幽。\n随缘柳绿柳白，费尽雕锼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12400, '暮花天・花发沁园春', '陈亮', '天意微悭，春工多裕，长须末後殷勤。\n骨瘦挽先，肌韵恰好，花头径尺徐陈。\n红黄粉紫，更牛家、姚魏为真。\n留几种，蒂中州，异时齐顿浑身。\n承平当日开多少，笙歌何限，是甚人人。\n气入江南，心知芍药，仿佛前事犹存。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12401, '新荷叶', '陈亮', '艳态远幽，谁能洁净争妍。\n淡抹疑浓，肯将自在求怜。\n终嫌独好，任毛嫱、西子差肩。\n六郎涂，似和不似依然。\n赫日如焚，诸馀只凭光鲜。\n雨过风生，也应百事随缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12402, '秋兰香', '陈亮', '未老金茎，些子正气，东篱淡伫齐芳。\n分头添样白，同菊几般黄。\n向闲处、须一一排行。\n浅深饶间新妆。\n那陶令，漉他谁酒，趁醒消详。\n况是此花开後，便蝶乱无花，管甚蜂忙。\n你从今、采却蜜成房。\n秋英诚商量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12403, '汉宫春', '陈亮', '雪满江头，怪一枝不耐，还漏微阳。\n诗人越样眼浅，早自成章。\n群葩如绣，到那时、争爱春长。\n须知道，未通春信，是谁饱试风霜。\n堪笑红炉画阁，问从来寒气，损甚容光。\n枝头有花恁好，映带新妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12404, '桂枝香', '陈亮', '仙风透骨。\n向夏叶丛中，春花重出。\n骏发天香，不是世间尤物。\n占些空阔闲田地，共霜轮、伴他秋实。\n浅非冷蕊，深非幽艳，中无倚握。\n任拈取、龙涎笃耨。\n儿女子看承，万屈千屈。\n做数珠见，刻画毋盐唐突。\n不知几树栾团着，但口吻、非鸣云室。\n是耶非也，书生见识，圣贤心术。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12405, '水龙吟', '陈亮', '钱王霸图成时，多应是百年遗树。\n羞将高古，为渠遮映，鱼盐调度。\n且向空山，趁时多事，四垂盘踞。\n算兴衰坐阅，权奇磊块，世间□，□斤斧。\n又见当天明圣，便弹丸、也难分土。\n一番整顿，旧家草木，新来雨露。\n铁石心肠，叫龙根干，亭亭天柱。\n纵茯苓下结，茑萝高际，怎堪攀附。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12406, '临江仙', '陈亮', '五百年间非一日，可堪只到今年。\n云龙欲化艳阳天。\n从来耆旧传，不博地行仙。\n昨夜风声何处度，典型犹在南山。\n自怜不结傍时缘。\n著鞭非我事，避路只渠贤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12407, '水龙吟', '陈亮', '闹花深处层楼，画帘半卷东风软。\n春归翠陌，平莎茸嫩，垂杨金浅。\n迟日催花，淡云阁雨，轻寒轻暖。\n恨芳菲世界，游人未赏，都付与、莺和燕。\n寂寞凭高念远。\n向南楼、一声归雁。\n金钗斗草，青丝勒马，风流云散。\n罗绶分香，翠绡封泪，几多幽怨。\n正销魂，又是疏烟淡月，子规声断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12408, '洞仙歌', '陈亮', '琐窗秋暮，梦高唐人困。\n独立西风万千恨。\n又檐花落处，滴碎空阶，芙蓉院，无限秋容老尽。\n枯荷催欲折，多少离声，锁断天涯诉幽闷。\n似蓬山去後，方士来时，挥粉泪、点点梨花香润。\n断送得，人间夜霖铃，更叶落梧桐，孤灯成晕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12409, '虞美人', '陈亮', '东风荡扬轻云缕。\n时送萧萧雨。\n水边台榭燕新归。\n一口香泥湿带、落花飞。\n海棠糁径铺香绣。\n依旧成春瘦。\n黄昏庭院柳啼鸦。\n记得那人和月、折梨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12410, '眼儿媚', '陈亮', '试灯天气又春来。\n难说是情怀。\n寂寥聊似，扬州何逊，不为江梅。\n扶头酒醒炉香，心绪未全灰。\n愁人最是，黄昏前後，烟雨楼台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12411, '思佳客', '陈亮', '花拂阑干柳拂空。\n花枝绰约柳鬟松。\n蝶翻淡碧低边影，莺啭浓香杪处风。\n深院落，小帘栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12412, '浣溪沙', '陈亮', '爽气朝来卒未阑。\n可能着我屋千间。\n不须拄笏望西山。\n柳外霎时征马骏，沙头尽日白鸥闲。\n称心容易足君欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12413, '贺新郎', '陈亮', '镂刻黄金屋。\n向炎天、蔷薇水洒，净瓶儿浴。\n湿透生绡裙微褪，谁把琉璃藉玉。\n更管甚、微凉生熟。\n磊浪星儿无著处，唤青奴、记度新翻曲。\n娇不尽，ソ州竹。\n一泓曲水鳞鳞蹙。\n粉生红、香脐皓腕，藕双莲独。\n拂掠乌云新妆晚，无奈纤腰似束。\n白笃耨、霞觞浮绿。\n三岛十州心在否，是天花、只怕凡心触。\n才乱坠，便簌簌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12414, '贺新郎', '陈亮', '昵昵骈头语。\n笑黄花、重阳去也，不成分数。\n倾国容华随时唤，依旧清歌妙舞。\n苦未冷、都无星暑。\n恰好良辰花共酒，斗尊前、见在阳台女。\n朝共暮，定何许。\n蓼红徙倚明汀渚。\n正萧萧、迎风夹岸，淡烟微雨。\n笃耨龙涎烧未也，好向儿家祝取。\n是有分、分工须与。\n以色事人能几好，愿衾稠、无缝休离阻。\n心一片，丝千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12415, '水调歌头', '李', '足迹半天下，家说在琼州。\n往来无定，蓬头垢面任憎嫌。\n挥扫笔头万字，贯穿胸中千古，不记受生年。\n海角一相遇，缘契似从前。\n锺离歌，吕公篆，醉张颠。\n恍如赤城龙凤，来过我鲸仙。\n笑我未离世网，不染个中尘土，饥食困来眠。\n拟问君家祖，兜率乐天天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12416, '六州歌头', '李', '高皇神武，善驾驭豪英。\n攘北狄，驱群盗，命天膺。\n救苍生。\n奈梦绕沙漠，隔温情，屈和好，召大将，归兵柄，列枢庭。\n公指汴京。\n威已振河洛，不顾身烹。\n失一时机会，嗟左衽吾民。\n痛岳家军。\n孰扶倾。\n久沈冤愤，七十载，还复遇，帝王真。\n表遗列，锡王号，日照临。\n激士心。\n始识安刘计，宁祸己，是忠臣。\n我乘传，访壁垒，想精明。\n英气懔然若在，仍题扁、昭揭天恩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12417, '水调歌头', '杨炎正', '寒眼乱空阔，客意不胜秋。\n强呼斗酒，发兴特上最高楼。\n舒卷江山图画，应答龙鱼悲啸，不暇顾诗愁。\n风露巧欺客，分冷入衣裘。\n忽醒然，成感慨，望神州。\n可怜报国无路，空白一分头。\n都把平生意气，只作如今憔悴，岁晚若为谋。\n此意仗江月，分付与沙鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12418, '水调歌头', '杨炎正', '杖屦觅春色，行遍大江西。\n访花问柳，都自无语欲成蹊。\n不道七州三垒，今岁五风十雨，全是太平时。\n征辔晚乘月，渔钓夜垂丝。\n诗书帅，坐围玉，尘挥犀。\n兴方不浅，领袖风月过花期。\n只恐梅梢青子，已露调羹消息，金鼎待公归。\n回首腾王阁，空对落霞飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12419, '水调歌头', '杨炎正', '父老一杯酒，争劝史君留。\n可怜桃李千树，无语送归舟。\n听得拈笙玉指，都把万家遗爱，吹作许离愁。\n倚醉袖红湿，生怕夕阳流。\n问君侯，今几日，到东州。\n还家时候，次第梅已暗香浮。\n只恐道间驿使，先寄调羹消息，归去总无由。\n鼎铉功名了，徐赴赤松游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12420, '水调歌头', '杨炎正', '买得一航月，醉卧出长安。\n平堤千里过尽，杨柳绿阴间。\n依约晓莺啼处，认得南徐风物，客梦恍惊残。\n重到旧游所，如把画图看。\n英雄事，千古意，一凭阑。\n惜今老矣，无复健笔写江山。\n天上人间知己，赖有使星郎宿，照映此尘寰。\n准拟五湖去，为乞钓鱼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12421, '水调歌头', '杨炎正', '把酒对斜阳，无语问西风。\n胭脂何事，都做颜色染芙蓉。\n放眼暮江千顷，中有离情万斛，无处落征鸿。\n天在阑干角，人倚醉醒中。\n千万里，江南北，浙西东。\n吾生如寄，尚想三径菊花丛。\n谁是中州豪杰，借我五湖舟楫，去作钓渔翁。\n故园且回首，此意莫匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12422, '水调歌头', '杨炎正', '一笛起城角，吹破小梅愁。\n东风犹未，谁遣春信到吾州。\n闻得东来千骑，鼓舞儿童竹马，和气与空浮。\n桃李未阴处，准拟种千头。\n今太守，宋人物，晋风流。\n政成谈笑，不妨高兴在南楼。\n只恐蓬莱仙伯，合侍玉皇香案，难作寇恂留。\n约住紫泥诏，凭轼且优游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12423, '水调歌头', '杨炎正', '踏碎九街月，乘醉出京华。\n半生湖海，谁念今日老还家。\n独把瓦盆盛酒，自与渔樵分席，说伊政声佳。\n竹马望尘去，倦客亦随车。\n听熏风，清晓月，韵梅花。\n人家十万，说尽炎热与咨嗟。\n只恐棠阴未满，已有枫宸趣召，归路不容遮。\n回首江边柳，空著旧栖鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12424, '满江红', '杨炎正', '春入台门，又见染、柳丝新绿。\n对此景，一年为寿，一番添福。\n莫怪凤池颁诏晚，要教淮水恩波足。\n听边民、千岁颂声中，重重祝。\n堂萱茂，庭枝馥。\n歌倚扇，杯持玉。\n共劝君一醉，满斟。\n今夜东风吹酒醒，明朝万里骑黄鹄。\n向九霞、光里望宸辉，看除目。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12425, '满江红', '杨炎正', '笔染相思，暗题尽、朱门白壁。\n动离思、春生远岸，烟销残日。\n杨柳结成罗带恨，海棠染就胭脂色。\n想深情、幽怨绣屏间，双。\n春水绿，春山碧。\n花有恨，酒无力。\n对一奁愁思，九分孤寂。\n寸寸锦肠浑欲断，盈盈玉泪应偷滴。\n倩东风、吹雁过江南，传消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12426, '满江红', '杨炎正', '寿酒如渑，拼一醉、劝君休惜。\n君不记、济河津畔，当年今夕。\n万丈文章光焰里，一星飞堕从南极。\n便御飞、乘兴入京华，班乡棘。\n君不是，长庚白。\n又不是，严陵客。\n只应是，明主梦中良弼。\n好把袖间经济手，如今去补天西北。\n等瑶池、侍宴夜归时，骑箕翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12427, '满江红', '杨炎正', '典尽春衣，也应是、京华倦客。\n都不记，麴尘香雾，西湖南陌。\n儿女别时和泪拜，牵衣曾问归时节。\n到归来、稚子已成阴，空头白。\n功名事，云霄隔。\n英雄伴，东南拆。\n对鸡豚社酒，依然乡国。\n三径不成陶令隐，一区未有扬雄宅。\n问渔樵、学作生生涯，从今日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12428, '瑞鹤仙', '杨炎正', '风光开旧眼。\n正梅雪初消，柳丝新染。\n楼台竞装点。\n照金荷十里，珠帘齐卷。\n湘弦楚管。\n动香风、旌旗影转。\n望云间，一点台星飞下，洞天清晚。\n争看。\n袖红围坐，舞翠回春，笑歌生暖。\n欢声正远。\n嬉游意，未容懒。\n恐丝纶趣召，清都仙伯，归去朝天夜半。\n倩邦人、挽取遨头，醉扶玉腕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12429, '贺新郎', '杨炎正', '十日狂风雨。\n扫园林、红香万点，送春归去。\n独有荼シ开未到，留得一分春住。\n早杨柳、趁晴飞絮。\n可奈暖埃欺昼永，试薄罗衫子轻如雾。\n惊旧恨，到眉宇。\n东风台榭知何处。\n问燕莺如今，尚有春光几许。\n可欢一年游赏倦，放得无情露醑。\n为唤取、扇歌裙舞。\n乞得风光远两眼，待为君、满把金杯举。\n扶醉玉，伴挥麈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12430, '贺新郎', '杨炎正', '梦里骖鸾驭。\n望蓬莱不远，翩然被风吹去。\n吹到楚楼烟月上，不记人间何处。\n但疑是、蓬壶别所。\n缥缈霓裳天女队，奉一仙、满把流霞举。\n如唤我，醉中舞。\n醉醒梦觉知何许。\n问潇湘今日，谁与主盟尊俎。\n无限青春难老意，拟倩管弦寄与。\n待新筑沙堤稳步。\n万里云霄都历遍，却依前、流水桃源路。\n留此笔，为君赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12431, '念奴娇', '杨炎正', '汉天云静，望一星飞过，湘南湘北。\n当是郴山猿鹤梦，唤起日边消息。\n羽扇纶巾，浩然乘兴，此意无人识。\n扁舟千里，但闻清夜横笛。\n记得天上人间，去年今日，曾作称觞客。\n明月风烟依旧似，只觉蓬莱悬隔。\n更恐明朝，诏黄飞下，趣驾冲霄翼。\n衮衣剑履，望公长在南极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12432, '念奴娇', '杨炎正', '杏花杨柳，对东风染尽、一年春色。\n弹压烟光三万顷，谁识清都仙伯。\n夜泛银潢，手移星纬，飞堕从天阙。\n御风乘兴，偶然身到乡国。\n二年人乐升平，舞台歌榭，处处红牙拍。\n寿酒千觞斟不尽，一醉何妨今夕。\n更约明年，凤凰迟上，去作称觞客。\n梅花折得，赠君调鼎消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12433, '洞仙歌', '杨炎正', '芙蓉开了，春未江梅透。\n小小东风弄晴昼。\n把万家和气，吹入笙歌，炉熏里，都与慈闱做寿。\n黄堂今日贵，自著莱衣，捧劝金船十分酒。\n愿从今，江海上，日日韶华桃李迳，总为人间种就。\n但看取、天边老人星，有一点台星，共光南斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12434, '洞仙歌', '杨炎正', '带湖佳处，仿佛真蓬岛。\n曾对金樽伴芳草。\n见桃花流水，别是春风，笙歌里，谁信东君曾老。\n功名都莫问，总是神仙，买断风光镇长好。\n但如今，经国手，袖里偷闲，天不管、怎得关河事了。\n待貌取、精神上凌烟，却旋买扁舟，归来闻早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12435, '鹊桥仙', '杨炎正', '思归时节，乍寒天气，总是离人愁绪。\n夜来无奈被西风，更吹作、一帘秋雨。\n征衫拂泪，阑干倚醉，羞对黄花无语。\n寄书除是雁来时，又只恐、书成雁去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12436, '鹊桥仙', '杨炎正', '筑成台榭，种成花柳，更又教成歌舞。\n不知谁为带湖仙，收拾尽、壶天风露。\n闲中得味，酒中得趣，只恐天还也妒。\n青山纵买万千重，遮不断、诏书来路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12437, '蝶恋花', '杨炎正', '离恨做成春夜雨。\n添得春江，划地东流去。\n弱柳系船都不住。\n为君愁绝听鸣橹。\n君到南徐芳草渡。\n想得寻春，依旧当年路。\n後夜独怜回首处。\n乱山遮隔无重数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12438, '蝶恋花', '杨炎正', '点检笙歌多酿酒。\n不放东风，独自迷杨柳。\n院院翠阴停永昼。\n曲栏随处堪垂手。\n昨日解酲今夕又。\n消得情怀，长被春。\n门外马嘶人去後。\n乱红不管花消瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12439, '蝶恋花', '杨炎正', '万点飞花愁似雨。\n峭杀轻寒，不会留春住。\n满地乱红风扫聚。\n只教燕子衔将去。\n独倚阑干闲自觑。\n深院无人，行到无情处。\n帘外丝丝杨柳舞。\n又还装点人情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12440, '千秋岁', '杨炎正', '五云缥缈。\n朝退金门晓。\n归未稳，传宣到。\n龙楼陪夕宴，凤沼吟春草。\n人间世，谁知自有蓬莱岛。\n一杯宜劝了。\n换得天颜笑。\n人不老，春长好。\n从今千百岁，总是中书考。\n瑶池会，金盘剩荐安期枣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12441, '玉人歌', '杨炎正', '风西起。\n又老尽篱花，寒轻香细。\n漫题红叶，句里意谁会。\n长天不恨江南远，苦恨无书寄。\n最相思，盘桔千枚，脍鲈十尾。\n鸿雁阻归计。\n算愁满离肠，十分岂止。\n倦倚阑干，顾影在天际。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12442, '点绛唇', '杨炎正', '邂逅开尊，眼中有个人纤软。\n袖罗轻转。\n玉腕回春暖。\n韵处无多，只恼人肠断。\n词将半。\n近前相劝。\n扑扑清香满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12443, '点绛唇', '杨炎正', '水载离怀，暮帆吹月寒欺酒。\n楚梅春透。\n忍放持杯手。\n莫唱阳关，免湿盈盈袖。\n君行後。\n那人消瘦。\n不恼诗肠否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12444, '秦楼月・忆秦娥', '杨炎正', '东风寂。\n垂杨舞困春无力。\n春无力。\n落红不管，杏花狼籍。\n断肠芳草萋萋碧。\n新来怪底相思极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12445, '浣溪沙', '杨炎正', '杨柳笼烟袅嫩黄。\n桃花蘸水染红香。\n薄罗衫子日初长。\n饮尽东风三百盏，醉来愁断几回肠。\n教人独自遣风光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12446, '浣溪沙', '杨炎正', '三迳闲情傲落霞。\n五湖高兴不浮家。\n自斟北斗浸丹砂。\n闲把胸中千涧壑，撰成醉处一生涯。\n雪楼风月篆岗花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12447, '桃源忆故人', '杨炎正', '尊前未语眉先皱。\n只把横波斜溜。\n此意问春知否。\n蝶困蜂儿瘦。\n呷丁些来酒。\n越会把人。\n有个约伊时候。\n梦里来相就。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12448, '踏莎行', '杨炎正', '宿鹭栖身，飞鸿点泪，不堪更是重阳到。\n一襟无处著凄凉。\n倚阑堪尽斜阳倒。\n瘦减难丰，悲伤易老，淡觞消得黄花笑。\n画眉人去玉篦存，浓愁如黛凭谁扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12449, '减字木兰花', '杨炎正', '月明如昼。\n占断小楼供把酒。\n入眼人人。\n如月精神更有情。\n大家休睡。\n留到天明和月醉。\n生怕醒来。\n月到波心忆酒媒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12450, '生查子', '杨炎正', '金莲照夜红，玉腕扶春碧。\n曲妙遏云行，人好欺花色。\n欢生酒面浓，笑染炉香湿。\n饮尽十玻璃，月堕东方白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12451, '柳梢青', '杨炎正', '生紫衫儿。\n影金领子，著得偏宜。\n步稳金莲，香熏纨扇，舞转花枝。\n捧杯更著。\n唱一个、新行耍词。\n玉骨冰肌，好天良夜，怎不怜伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12452, '相见欢', '杨炎正', '江湖万里征鸿。\n再相逢。\n多少风烟摸在、笑谈中。\n歌裙醉。\n罗巾泪。\n别愁浓。\n瘦减腰围不碍、带金重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12453, '诉衷情', '杨炎正', '露珠点点欲团霜。\n分冷与纱窗。\n锦书不到肠断，烟水隔茫茫。\n征燕尽，塞鸿翔。\n睇风樯。\n阑干曲处，又是一番，倚尽斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12454, '满江红', '杨炎正', '豹尾班中，谁一似、神仙冠玉。\n认得是、当年唱第，斗间星宿。\n万卷平生都看了，如今地无书读。\n向云霄、去路有行堤，沙新筑。\n黄封酒，生朝禄。\n金缕唱，生朝曲。\n且通宵一醉，剩裁红烛。\n待做太平真宰相，黑头坐对三槐绿。\n问恁时、犹有甚除书，长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12455, '点绛唇', '俞灏', '欲问东君，为谁重到江头路。\n断桥薄暮。\n香透溪云渡。\n细草平沙，愁入凌波步。\n今何许。\n怨春无语。\n片片随流水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12456, '清平乐', '连久道', '阵鸿惊处。\n一网沈江渚。\n落叶乱风和细雨。\n拨棹不如归去。\n芦花轻泛微澜。\n蓬窗独自清闲。\n一觉游仙好梦，任它竹冷松寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12457, '减字木兰花', '赵师', '江南春早。\n春到南枝花更好。\n不比寻常。\n深著胭脂学弄妆。\n寿阳开宴。\n拂拂红霞生酒面。\n从此溪桥。\n步障翻腾著绛绡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12458, '苏幕遮', '宋先生', '气随神，神随气。\n神气相随，透入泥丸里。\n长把金关牢锁闭。\n捉得金晶，暗地添欢喜。\n下辛勤，须发志。\n十二时中，莫把工夫弃。\n阴尽阳全神出体。\n功行成时，名列神仙位。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12459, '丑奴儿・采桑子', '宋先生', '真人本是凡人做，悟者何难。\n名利如山。\n隔断神仙路往还。\n谢师指教生死限，长在心间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12460, '沁园春', '宋先生', '速速修行，惜取身中，无价□珍。\n把金乌玉兔，炉中炼用，阴阳造化，养就阳神。\n虎啸龙吟丹田里，顶内时时仙乐声。\n泥丸里，烹煎水火，铅汞成真。\n夜来端坐澄心神。\n见真人颜貌新。\n用河车搬载，充开牛斗，星辰洁皎，光射分明。\n服了刀圭功成後，自知道、仙班有姓名。\n诸仙请，待玉皇宣至，朝拜三清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12461, '武陵春', '宋先生', '七返还丹人怎晓，晓後有何难。\n夜静存神向内观。\n神水满泥丸。\n搬运金精无夜昼，呼吸不曾闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12462, '武陵春', '宋先生', '虎绕龙蟠功最妙，交会在丹田。\n炉鼎烹煎火自然。\n日月炼为先。\n认取坎离为造化，真气要还源。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12463, '丑奴儿・采桑子', '宋先生', '河车怎敢停留住，搬入泥丸。\n水火烹煎。\n一粒丹砂炼汞铅。\n金丹大药人人有，只要心坚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12464, '丑奴儿・采桑子', '宋先生', '因师传说朝元理，昼夜功勤。\n炼煅成真。\n偷得阴阳共半斤。\n壶中天地何曾夜，四季长春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12465, '丑奴儿・采桑子', '宋先生', '夜来子後披衣坐，心定神清。\n见个真人。\n脸似胭脂体似银。\n炉中火焰炎炎起，紫气腾腾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12466, '太常引', '宋先生', '金丹只在自身中。\n真水火、炼成功。\n因遇吕仙公。\n识返本、还元祖宗。\n阳全阴尽，神光现处，认得自真容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12467, '点绛唇', '宋先生', '二气工夫，河车搬入脑。\n世人谁晓。\n此是玄元道。\n存得阳精，年老身不老。\n三田饱。\n行动都了。\n拂袖游蓬岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12468, '点绛唇', '宋先生', '这个工夫，因师传授知元祖。\n论甚子午。\n说甚龙和虎。\n只在目前，明有神仙路。\n速修取。\n有朝归去。\n消了阴司簿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12469, '捣练子', '宋先生', '真水火，谢师传。\n黑铅红汞鼎中煎。\n现神光，满目前。\n丹砂就，是神仙。\n金鼎捉住寿同天。\n待功成，玉帝宣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12470, '临江仙', '宋先生', '说甚坎离龙共虎，休言火候周天。\n阳精不走自神全。\n双关明有路，直上至泥丸。\n牢锁金关并玉户，日魂月魄烹煎。\n三宫都满体牢坚。\n阳神朝上帝，永劫作天仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12471, '丑奴儿・采桑子', '宋先生', '金公本是乾家子，住在坤宫。\n真虎真龙。\n吃尽三尸及九虫。\n丹砂锻炼泥丸里，赫赫长红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12472, '浪淘沙', '宋先生', '我有一张琴。\n随坐随行。\n无弦胜似有弦声。\n欲对人前弹一曲，不遇知音。\n夜静响轰。\n神鬼俱惊。\n惊天动地若雷鸣。\n只候功成归去後，携向蓬瀛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12473, '念奴娇', '张', '绿云影里，把明霞织就，千重文绣。\n紫腻红娇扶不起，好是未开时候。\n半怯春寒，半便晴色，养得胭脂透。\n小亭人静，嫩莺啼破清昼。\n犹记携手芳阴，一枝斜戴，娇艳波双秀。\n小语轻怜花总见，争得似花长久。\n醉浅休归，夜深同睡，明日还相守。\n免教春去，断肠空欢诗瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12474, '水调歌头', '张', '孤棹溯霜月，远过阖闾城。\n系船杨柳桥畔，吹袖晚寒轻。\n百尺层台重上，万事红尘一梦，回首几周星。\n风调信衰减，亲旧总雕零。\n认群峰，寻四塔，半烟横。\n平生感慨，况逢佳处辄销凝。\n休说当时雕辇，不见後来游鹿，斜照水空明。\n猛把画阑拍，飞雁两三声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12475, '水调歌头', '张', '忠肝贯日月，浩气抉云霓。\n诗书名帅，谈笑果胜棘门儿。\n牛弩旁穿七札，虎将分行十道，先解近城围。\n一骑夜飞火，捷奏上天墀。\n畅皇威，宣使指，领全师。\n襄阳耆旧，请公直过洛之西。\n箪食欢呼迎处，已脱毡裘左衽，远著旧藏衣。\n笳鼓返京阙，风采震华夷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12476, '木兰花慢', '张', '喜秋回霁宇，倩凉露、洗炎飙。\n被鹊误仙盟，经年恨阻，银汉迢迢。\n牛闲更停弄杼，趁佳期、华幄傍星桥。\n授玉鸾骞雾霭，赠绡龙戏花娇。\n欢娱回首是明朝。\n未别已魂销。\n想翠轭珠轮，归途望断，斗转斜勺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12477, '木兰花慢', '张', '年年三月二，是居士、始生朝。\n念绿鬓功名，初心已负，难报劬劳。\n天留帝城胜处，汇平湖、远岫碧。\n竹色诗书燕几，柳阴桃杏横桥。\n西邻东舍不难招。\n大半是渔樵。\n任翁媪欢呼，儿孙歌笑，野具村醪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12478, '木兰花慢', '张', '驾飙车直上，绛衣惹、彩云轻。\n过宝树千峰，东逾绿海，宫殿峥嵘。\n檐楹万花灿倚，映阶层、十二总雕琼。\n剑佩簪裳卫肃，序班真辅仙卿。\n瑶京。\n谁解有神升。\n为密授玄经。\n拜九光霞里，轮金日耀，丹篆符明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12479, '水龙吟', '张', '这番真个休休，梦中深谢仙翁教。\n浮生幻境，向来识破，那堪又老。\n苦我身心，顺他眼耳，思量颠倒。\n许多时打哄，鲇鱼上竹，被人弄、知多少。\n解放微官系缚，似笼槛、猿归林草。\n云山有约，儿孙无债，为谁烦恼。\n自古高贤，急流勇退，直须闻早。\n把忧煎换取，长伸脚睡，大开口笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12480, '祝英台近', '张', '暖风回，芳意动，吹破冻云凝。\n春到南湖，检校旧花径。\n手栽一色红梅，香笼十亩，忍轻负、酒肠诗兴。\n小亭凭。\n几多月魄□□，重重乱林影。\n却忆年时，同醉正同咏。\n问公白玉堂前，何如来听，玉龙喷、碧溪烟冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12481, '满江红', '张', '玉照梅开，三百树、香云同色。\n光摇动、一川银浪，九霄珂月。\n幸遇勋华时世好，欢娱况是张灯夕。\n更不邀、名胜赏东风，真堪惜。\n盘诰手，春秋笔。\n今内相，斯文伯。\n肯闲纡轩盖，远过泉石。\n奇事人生能几见，清尊花畔须教侧。\n到凤池、却欲醉鸥边，应难得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12482, '满江红', '张', '公为时生，才真是、禁中颇牧。\n擎天手、十年犹在，未应藏缩。\n说项无人堪欢息，瞻韩有意应恢复。\n用真儒、同建太平功，心相属。\n忠与孝，荣和辱。\n武昌柳，南湖竹。\n一箪瓢非欠，万锺非足。\n知命何曾怀喜愠，轻身岂为干名禄。\n看可汗生缚洗烟尘，机神速。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12483, '汉宫春', '张', '城畔芙蓉，爱吹晴映水，光照园庐。\n清霜乍雕岸柳，风景偏殊。\n登楼念远，望越山、青补林疏。\n人正在，秋风亭上，高情远解知无。\n江南久无豪气，看规恢意概，当代谁如。\n乾坤尽归妙用，何处非予。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12484, '烛影摇红', '张', '宿雨初乾，舞梢烟瘦金丝袅。\n嫩云扶日破新晴，旧碧寻芳草。\n幽径兰芽尚小。\n怪今年、春归太早。\n柳塘花院，万朵红莲，一宵开了。\n梅雪翻空，忍教轻趁东风老。\n粉围香阵拥诗仙，战退春寒峭。\n现乐歌弹闹晓。\n宴亲宝、团同笑。\n醉归时候，月过珠楼，参横蓬岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12485, '贺新郎', '张', '看了梅花去。\n要东风、攀翻飞雪，与君同赋。\n海内从来天际眼，一笑平窥千古。\n待翦尽、烛花红吐。\n久矣南湖无此客，似乔松、万丈凌霄举。\n飞唾，扫尘土。\n承平气象森眉宇。\n想天家、骖鸾洞里，细烟冰雾。\n我亦秦关归未得，谁念干将醉扶。\n拼良夜、横冠屦。\n莫欢潇湘居尚远，拥戎轺万骑鸣笳鼓。\n云正锁，汴京路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12486, '贺新郎', '张', '邂逅非专约。\n记当年、林堂对竹，艳歌春酌。\n一笑乘鸾明月影，馀事丹青麟阁。\n待宇宙、长绳穿却。\n念我中原空有梦，渺风尘、万里迷长乐。\n愁易老，欠灵药。\n别来几度霜天鹗。\n压纷纷、吞腥啄腐，狗偷乌攫。\n东晋风流兼慷慨，公自阳春有脚。\n妙悟处、不存毫发。\n何日相从云水去，看精神峭紧芝田鹤。\n书壮语，遍岩壑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12487, '瑞鹤仙', '张', '喜浓寒乍退。\n风共日、已作深春天气。\n轻车载歌吹。\n选名坊闲玩，落梅李。\n无端雨细。\n动清愁、聊成浅醉。\n怅年时、携手同来，笑里绣帘斜倚。\n佳节匆匆又至。\n抚事惊心，忍堪重记。\n阑情倦意。\n行不是，坐不是。\n闷归来，已早游人回尽，灯暗重门欲闭。\n念欢娱、最是今宵，怎知恁地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12488, '八声甘州', '张', '领千岩万壑岂无人，惟欠稼轩来。\n正松梧秋到，旌旗风动，楼观雄开。\n俯槛何劳一笑，瀚海荡纤埃。\n馀事了凫骛，闲命尊。\n江左风流旧话，想登临浩叹，白骨苍苔。\n把龙韬藏去，游戏且蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12489, '八声甘州', '张', '对黄花犹自满庭开，那恨过重阳。\n凭阑干醉袖，依依晚日，飘动寒香。\n自叹平生豪纵，歌笑几千场。\n白发欺人早，多似清霜。\n谁信心情都懒，但禅龛道室，黄卷僧床。\n把偎红调粉，抛掷向他芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12490, '江城子', '张', '飞来冰雪冷无声。\n可中庭。\n骨毛清。\n卧看东南，和露两三星。\n蓦地神游天上去，呼彩凤，驾云骈。\n望舒宫殿玉峥嵘。\n桂千层。\n宝香凝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12491, '渔家傲', '张', '拂拂春风生草际。\n新晴万景供游戏。\n鸥鹭飞来斜照里。\n金和翠。\n分明画出真山水。\n遮个渔翁无愠喜。\n乾坤都在乌蓬底。\n一曲高歌千古意。\n闲来睡。\n从教月到花汀外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12492, '八声甘州', '张', '叹流光迅景，百年间、能醉几中秋。\n正凄蛩响砌，惊乌翻树，烟淡苹洲。\n谁唤金轮出海，不带一云浮。\n才上青林顶，俄转珠楼。\n人老欢情已减，料素娥信我，不为闲愁。\n念几番清梦，常是故乡留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12493, '木兰花慢', '张', '清明初过後，正空翠、霭晴鲜。\n念水际楼台，城隅花柳，春意无边。\n清时自多暇日，看连镳、飞盖拥群贤。\n朱邸横经满坐，紫微渊思如泉。\n高情那更属云天。\n语笑杂歌弦。\n向啼声中，落红影里，忍负芳年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12494, '念奴娇', '张', '东吴名胜，有高楼直在，浮云齐处。\n十二阑干邀远望，历历斜阳烟树。\n香径人稀，廊山绕，往事今何许。\n一天和气，为谁吹散疏雨。\n知是兰省星郎，朱轮森戟，与风光为主。\n暇日登携多雅致，容我追随临赋。\n小宴重开，晚寒初劲，还下危梯去。\n烛花红坠，瑞堂犹按歌舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12495, '兰陵王', '张', '蓼汀侧。\n朝霭依依弄色。\n知何许、湘女淡妆，羽节飞来带秋碧。\n轻裙素绡织。\n谁与明竞饰。\n无言处、相与溯回，应有柔情正堆积。\n当年驻香。\n记草媚罗裙，波映文席。\n□□□□□□摘。\n□□□□□，□□□□，斜阳返照暮雨湿。\n爱天际凉入。\n愁寂。\n念畴昔。\n谩太华峰顶，幽梦寻觅。\n尔今两鬓如花白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12496, '乌夜啼', '张', '晓来闲立回塘。\n一襟香。\n玉云松风外、数枝凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12497, '如梦令', '张', '野菊亭亭争秀。\n闲伴露荷风柳。\n浅碧小开花，谁摘谁看谁嗅。\n知否。\n知否。\n不入东篱杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12498, '失调名', '张', '翠鬓佩明珂。\n度纹波。\n亲到曾入梦，听云和。\n洞庭香、随月影来过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12499, '风入松', '张', '芳丛簇簇水滨生。\n勾引午风清。\n六花大似天边雪，又几时、雪有三层。\n明艳射回蜂翅，净香熏透蝉声。\n晚檐人共月同行。\n疏影动银屏。\n指尖轻拈都如玉，听画栏、高啭流莺。\n道是花枝比得，不成花也多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12500, '蓦山溪', '张', '抚连吟就，檐葡还曾赋。\n相伴更无花，倦炉熏、日长难度。\n柔桑叶里，玉碾小芙蕖，生竺国，长闽山，移向玉城住。\n池亭竹院，宴坐冰围处。\n绿绕百千丛，夜将阑、争开迎露。\n煞曾评论，娇媚胜江梅，香称月，韵宜风，消尽人间暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12501, '菩萨蛮', '张', '层层细剪冰花小。\n新随荔子云帆到。\n一露一番开。\n玉人催卖栽。\n爱花心未已。\n摘放冠儿里。\n轻浸水晶凉。\n一窝云影香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12502, '贺新郎', '张', '桂隐传杯处。\n有风流、千岩韵胜，太丘遗绪。\n玉季金昆霄汉侣，平步鸾坡挥麈。\n莫便驾、飞帆烟渚。\n云动精神衡岳去，向君山、帝乐锵韶。\n兰艺畹，吊湘楚。\n南湖老矣无襟度。\n但尊前、踉跄醉影，帽花颠仆。\n只恐清时专文教，犹贷阴山狂虏。\n卧锦帐、貔貅钲鼓。\n忠烈前勋赍万恨，望神都、魏阙奔狐兔。\n呼翠袖，为君舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12503, '柳梢青', '张', '天远山围，龙蟠淡霭，虎踞斜晖。\n几度功名，几番成败，浑似鸥飞。\n楼台一望凄迷。\n算到底、空争是非。\n今夜潮生，明朝风顺，且送船归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12504, '鹧鸪天', '张', '御路东风拂翠衣。\n卖灯人散烛笼稀。\n不知月底梅花冷，只忆桥边步袜归。\n闲梦淡，旧游非。\n夜深谁在小帘帏。\n罘儿下围炉坐，明处行人立地时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12505, '宴山亭・燕山亭', '张', '幽梦初回，重阴未开，晓色吹成疏雨。\n竹槛气寒，蕙畹声摇，新绿暗通南浦。\n未有人行，才半启、回廊朱户。\n无绪。\n空望极霓旌，锦书难据。\n苔径追忆曾游，念谁伴、秋千采绳芳柱。\n犀奁黛卷，凤枕云孤，应也几番凝伫。\n怎得伊来，花雾绕、小堂深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12506, '柳梢青', '张', '千丈风漪。\n霁光明处，花柳高低。\n箫鼓声中，宝钗遥认，兰棹交驰。\n贪呆觑著帘儿。\n不好价、伊家怎知。\n便是重来，真情厮向，难似当时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12507, '朝中措', '张', '先生心地等空虚。\n行处幻仙都。\n点缀玲珑花柳，翻腾窈窕规模。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12508, '沁园春', '刘过', '玉带猩袍，遥望翠华，马去似龙。\n拥貂蝉争出，千宫鳞集，貔貅不断，万骑云从。\n细柳营开，团花袍窄，人指汾阳郭令公。\n山西将，算韬钤有种，五世元戎。\n旌旗蔽满寒空。\n鱼阵整、从容虎帐中。\n想刀明似雪，纵横脱鞘，箭飞如雨，霹雳鸣弓。\n威憾边城，气吞胡虏，惨淡尘沙吹北风。\n中兴事，看君王神武，驾驭英雄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12509, '沁园春', '刘过', '缓辔徐驱，儿童聚欢，神仙画图。\n正芹塘雨过，泥融路软，金莲自策，小小蓝舆。\n傍柳题诗，穿花劝酒，嗅蕊攀条得自如。\n经行处，有苍松夹道，不用传呼。\n清泉怪石盘纡。\n信风景江淮各异殊。\n记东坡赋就，沙笼素壁，西山句好，帘卷晴珠。\n白玉堂深，黄金印大，无此文君载後车。\n挥毫罢，看淋漓雪壁，真草行书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12510, '沁园春', '刘过', '古岂无人，可以似吾，稼轩者谁。\n拥七州都督，虽然陶侃，机明神鉴，未必能诗。\n常衮何如，羊公聊尔，千骑东方侯会稽。\n中原事，纵匈奴未灭，毕竟男儿。\n平生出处天知。\n算整顿乾坤终有时。\n问湖南宾客，侵寻老矣，江西户口，流落何之。\n尽日楼台，四边屏幛，目断江山魂欲飞。\n长安道，奈世无刘表，王粲畴依。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12511, '沁园春', '刘过', '问讯竹湖，竹如之何，如何未归。\n道吴山越水，无非佳处，来无定止，去亦何之。\n莫是秋来，未能忘耳，心与孤云相伴飞。\n愁无奈，但北窗寄傲，南涧题诗。\n人生万事成痴。\n算世上久无公是非。\n恨云台突兀，无君子者，雪堂寥落，有美人兮。\n疏雨梧桐，微云河汉，钟鼎山林无限悲。\n阳山县，是昌黎误汝，汝误昌黎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12512, '沁园春', '刘过', '一剑横空，飞过洞庭，又为此来。\n有汝阳者，唱名殿陛，玉川公子，开宴尊。\n四举无成，十年不调，大宋神仙刘秀才。\n如何好，将百千万事，付两三杯。\n未尝戚戚于怀。\n问自古英雄安在哉。\n任钱塘江上，潮生潮落，姑苏台畔，花谢花开。\n盗号书生，强名举子，未老雪从头上催。\n谁羡汝，拥三千珠履，十二金钗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12513, '沁园春', '刘过', '玉带金鱼，绿鬓朱颜，神仙画图。\n把擎天柱石，空留绿野，济川舟楫，闲舣西湖。\n天欲安刘，公归重赵，许大元勋谁得如。\n平章处，看人如伊吕，世似唐虞。\n不须别样规模。\n但收揽人才多用儒。\n况自昔军中，胆能寒虏，而今胸次，气欲吞胡。\n紫府真人，黑头元宰，收敛神功寂似无。\n归来好，正芝香枣熟，鹤瘦松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12514, '沁园春', '刘过', '斗酒彘肩，风雨渡江，岂不快哉。\n被香山居士，约林和靖，与东坡老，驾勒吾回。\n坡谓西湖，正如西子，浓抹淡妆临镜台。\n二公者，皆掉头不顾，只管衔杯。\n白云天竺飞来。\n图画里、峥嵘楼观开。\n爱东西双涧，纵横水绕，两峰南北，高下云堆。\n逋曰不然，暗香浮动，争似孤山先探梅。\n须晴去，访稼轩未晚，且此俳徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12515, '沁园春', '刘过', '柳思花情，湖山应怪，先生又来。\n想旧时谈舌，依然解使，六丁奔走，驱斥风雷。\n翠袖传觞，金貂换酒，痛饮何妨三百杯。\n人间世，算谪仙去後，谁是天才。\n碧窗画鼓船斋。\n胸次与乾坤一样开。\n试云间招手，下呼馀子，逡巡去矣，但觉尘埃。\n若是花时，无风无雨，一日须来一百回。\n教人道，看玉山自倒，不用相推。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12516, '沁园春', '刘过', '万马不嘶，一声寒角，令行柳营。\n见秋原如掌，枪刀突出，星驰铁骑，阵势纵横。\n人在油幢，戎韬总制，羽扇从容裘带轻。\n君知否，是山西将种，曾系诗盟。\n龙蛇纸上飞腾。\n看落笔四筵风雨惊。\n便尘沙出塞，封侯万里，印金如斗，未惬平生。\n拂拭腰间，吹毛剑在，不斩楼兰心不平。\n归来晚，听随军鼓吹，已带边声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12517, '沁园春', '刘过', '画凌空，红旗翻雪，灵鼍震雷。\n叹沈湘去国，怀沙吊古，江山凝恨，父老兴哀。\n正直难留，灵修已化，三户真能存楚哉。\n空江上，但烟波渺渺，岁月洄洄。\n持杯。\n西眺徘徊。\n些千载忠魂来不来。\n谩争标夺胜，鱼龙喷薄，呼声贾勇，地裂山摧。\n香黍缠丝，宝符插艾，犹有樽前儿女怀。\n兴亡事，付浮云一笑，身在天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12518, '沁园春', '刘过', '自注铜瓶，作梅花供，尊前数枝。\n说边头旧话，人生消得，几番行役，问我何之。\n小队红旗，黄金大印，直待封侯知几时。\n杯行处，且淋漓一醉，明日东西。\n如椽健笔鸾飞。\n还为写春风陌上词。\n便平生豪气，销磨酒里，依然此乐，儿辈争知。\n霜重貂裘，夜寒如水，饮到月斜犹未归。\n仙山路，有笙簧度曲，声到琴丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12519, '沁园春', '刘过', '万里湖南，江山历历，皆吾旧游。\n看飞凫仙子，张帆直上，周郎赤壁，鹦鹉汀洲。\n吸尽西江，醉中横笛，人在岳阳楼上头。\n波涛静，泛洞庭青草，重整兰舟。\n长沙会府风流。\n有万户娉婷帘玉钩。\n恨楚城春晚，岸花墙燕，还将客送，不与人留。\n且唤阳城，更招元结，摩抚之馀歌咏休。\n心期处，算世间真有，骑鹤扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12520, '沁园春', '刘过', '一别三年，一日三秋，庶几见之。\n念丹霞秋冷，风巾雾屦，五湖春暖，雨笠烟蓑。\n山水光中，要人携手，独欠金华俞紫芝。\n谁知道，向酴香里，杯酒同持。\n油然川泳云飞。\n但口不能言心自知。\n便狂敲铜斗，我歌君和，醉拈如意，我舞君随。\n风韵如君，岂堪言别，别後如之何勿思。\n须金玉，再相逢莫负，芷约兰期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12521, '沁园春', '刘过', '一笛横风，稳转船头，系楫大江。\n还有人争说，鸣琴手段，教侬重吐，锦绣肝肠。\n不复少年，插花槌鼓，雅意在乎云水乡。\n阳关泪，笑琼姬犹恋，奇俊王郎。\n谈兵齿颊冰霜。\n有万户侯封何用忙。\n借烟霞且作，诗中队仗，鹭已是，归日班行。\n收敛平生，筹边胸次，以酒浇之书传香。\n消凝处，怕三更枕上，疏雨潇湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12522, '沁园春', '刘过', '销薄春冰，碾轻寒玉，渐长渐弯。\n见凤鞋泥污，偎人强剔，龙涎香断，拨火轻翻。\n学抚瑶琴，时时欲翦，更掬水鱼鳞波底寒。\n纤柔处，试摘花香满，镂枣成班。\n时将粉泪偷弹。\n记绾玉曾教柳傅看。\n算恩情相著，搔便玉体，归期暗数，画遍阑干。\n每到相思，沈吟静处，斜倚朱唇皓齿间。\n风流甚，把仙郎暗掐，莫放春闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12523, '沁园春', '刘过', '洛浦凌波，为谁微步，轻尘暗生。\n记踏花芳径，乱红不损，步苔幽砌，嫩绿无痕。\n衬玉罗悭，销金样窄，载不起、盈盈一段春。\n嬉游倦，笑教人款捻，微褪些跟。\n有时自度歌声。\n悄不觉、微尖点拍频。\n忆金莲移换，文鸳得侣，绣茵催衮，舞凤轻分。\n懊恨深遮，牵情半露，出没风前烟缕裙。\n知何似，似一钩新月，浅碧笼云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12524, '水调歌头', '刘过', '春事能几许，密叶著青梅。\n日高花困，海棠春暖想都开。\n不惜春衣典尽，只怕春光归去，片片点苍苔。\n能得几时好，追赏莫俳徊。\n雨飘红，风换翠，苦相催。\n人生行乐，且须痛饮莫辞杯。\n坐则高谈风月，醉则恣眠芳草，醒後亦佳哉。\n湖上新亭好，何事不曾来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12525, '水调歌头', '刘过', '弓剑出榆塞，铅椠上蓬山。\n得之浑不费力，失亦匹如闲。\n未必古人皆是，未必今人俱错，世事沐猴冠。\n老子不分别，内外与中间。\n酒须饮，诗可作，铗休弹。\n人生行乐，何自催得鬓毛斑。\n达则牙旗金甲，穷则蹇驴破帽，莫作两般看。\n世事只如此，自有识鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12526, '水调歌头', '刘过', '文采汉机轴，人物晋风流。\n丈夫有此，便可谈笑觅封侯。\n试问湘南水石，今古阅人多矣，曾见此公不。\n名姓出天上，声誉塞南州。\n斩楼兰，擒颉利，志须酬。\n青衫何事，犹在楚尾与吴头。\n闻道长安灞水，尽是三槐风月，好奉板舆游。\n此曲为君寿，为我唤歌喉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12527, '念奴娇', '刘过', '知音者少，算乾坤许大，著身何处。\n直待功成方肯退，何日可寻归路。\n多景楼前，垂虹亭下，一枕眠秋雨。\n虚名相误，十年枉费辛苦。\n不是奏赋明光，上书北阙，无惊人之语。\n我自匆忙天未许，赢得衣裾尘土。\n白壁追欢，黄金买笑，付与君为主。\n莼鲈江上，浩然明日归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12528, '念奴娇', '刘过', '并肩楼上，小阑干、犹记年时凭处。\n百岁光阴弹指过，消得几番寒暑。\n鹊去桥空，燕飞钗在，不见穿针女。\n老怀凄断，夜凉知共谁诉。\n不管天上人间，秋期月影，两处相思苦。\n闲揭纱窗人未寝，泪眼不曾晴雨。\n花落莲汀，叶喧梧井，孤雁应为侣。\n浩歌而已，一杯长记时序。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12529, '糖多令・唐多令', '刘过', '芦叶满汀洲。\n塞沙带浅流。\n二十年、重过南楼。\n柳下系舟犹未稳，能几日、又中秋。\n黄鹤断矶头。\n故人今不在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12530, '满江红', '刘过', '猎猎风蒲，画船转、碧湾沙浦。\n都不是、蓼汀桃岸，橘州梅渚。\n指点山公骑马地，经由羊祜登山处。\n悄一如、人在水晶宫，销烦暑。\n薰风动，帘旌举。\n秦筝奏，凌波舞。\n拼冰壶沈醉，晚凉归去。\n侵岸一篙杨柳浪，过云几点荷花雨。\n倚楼人、十里凭阑干，神仙侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12531, '满江红', '刘过', '敌面风轻，一两点、海棠微雨。\n春总在、英雄元帅，晓来游处。\n楼阁万家帘幕卷，江郊十里旌旗驻。\n有黄鹂、百舌啭新声，垂杨舞。\n寒食近，喧箫鼓。\n车马闹，铜路。\n尽不妨沈醉，与花为主。\n风韵可将图画比，笑谈尽是惊人语。\n问何如、邹湛岘山头，陪羊祜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12532, '满江红', '刘过', '霜树啼鸦，梅欲放、小春清晓。\n庆初度、佩环风外，笑声云表。\n一柱独擎梁栋重，十年整顿乾坤了。\n种春风、桃李满人间，知多少。\n功甚大，心常小。\n居廊庙，思耕钓。\n奈华夷休戚，系王颦笑。\n盟府山河书带砺，成周师保须周召。\n看貂蝉、绿鬓本天人，真难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12533, '谒金门', '刘过', '归不去。\n船泊早春梅渚。\n试听玉人歌白苎。\n行云无觅处。\n翦烛写诗无语。\n漠漠寒生窗户。\n明日短篷眠夜雨。\n宝钗留半股。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12534, '谒金门', '刘过', '秋兴恶。\n愁怯罗衾风弱。\n雨线垂垂晴又落。\n轻烟笼翠箔。\n休道旅怀萧索。\n生怕香浓灰薄。\n桂子莫教孤酒约。\n诗情浑落魄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12535, '贺新郎', '刘过', '倦舞轮袍後。\n正鸾慵凤困，依然怨新怀旧。\n别有艳妆来执乐，春笋微揎罗袖。\n试一曲、琅初奏。\n莫放珠帘容易卷，怕人知、世有梨园手。\n钗玉冷，钏金瘦。\n烛花对翦明於昼。\n画堂深、屏山掩翠，炭红围兽。\n错认佩环犹未是，依约雏莺啭柳。\n任箭滴、铜壶银漏。\n一片雄心天外去，为声清、响彻云霄透。\n人醉也，尚呼酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12536, '贺新郎', '刘过', '院宇重重掩。\n醉沈沈、亭阴转午，绣帘高卷。\n金鸭香浓喷宝篆，惊起雕梁语燕。\n正一架、酴开遍。\n嫩萼梢头舒素脸。\n似月娥、初试宫妆浅。\n风力嫩，异香软。\n佳人无意拈针线。\n绕朱阑、六曲俳徊，为他留恋。\n试把花心轻轻数，暗卜归期近远。\n奈数了、依然重怨。\n把酒问春春不管。\n枉教人、只恁空肠断。\n肠断处，怎消遣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12537, '贺新郎', '刘过', '老去相如倦。\n向文君说似，而今怎生消遣。\n衣袂京尘曾染处，空有香红尚软。\n料彼此、魂销肠断。\n一枕新凉眠客舍，听梧桐、疏雨秋声颤。\n灯晕冷，记初见。\n楼低不放珠帘卷。\n晚妆残、翠钿狼藉，泪痕凝面。\n人道愁来须酒，无奈愁深酒浅。\n但寄兴、焦琴纨扇。\n莫鼓琵琶江上曲，怕荻花、枫叶俱凄怨。\n云万叠，寸心远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12538, '贺新郎', '刘过', '睡觉莺啼晓。\n醉西湖、两峰日日，买花簪帽。\n去尽酒徒无人问，唯有玉山自倒。\n任拍手、儿童争笑。\n一舸乘风翩然去，避鱼龙、不见波声悄。\n歌韵歇，唤苏小。\n神仙路远蓬莱岛。\n紫云深、参差禁树，有烟花绕。\n人世红尘西障日，百计不如归好。\n付乐事、与他年少。\n费尽柳金梨雪句，问沈香亭北何时召。\n心未惬，鬓先老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12539, '贺新郎', '刘过', '晓印霜花步。\n梦半醒、扶上雕鞍，马嘶人去。\n岚湿青丝双辔冷，缓野梅江路。\n听画角，吹残更鼓。\n悲壮寒声撩客恨，甚貂裘、重拥愁无数。\n霜月白，照离绪。\n青楼回首家何处。\n早山遥、水阔天低，断肠烟树。\n谁念天涯牢落况，轻负暖烟浓雨。\n记酒醒、香销时语。\n客里归鞯须早发，怕天寒、风急相思苦。\n应为我，翠眉聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12540, '贺新郎', '刘过', '多病刘郎瘦。\n最伤心、天寒岁晚，客他乡久。\n大舸翩翩何许至，元是高阳旧友。\n便一笑、相欢携手。\n为问武昌城下月，定何如、扬子江头柳。\n追往事，两眉皱。\n烛花细翦明於昼。\n唤青娥、小红楼上，殷勤劝酒。\n昵昵琵琶恩怨语，春笋轻笼翠袖。\n看舞彻、金钗微溜。\n若见故乡吾父老，道长安、市上狂如旧。\n重会面，几时又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12541, '贺新郎', '刘过', '弹铗西来路。\n记匆匆、经行十日，几番风雨。\n梦里寻秋秋不见，秋在平芜远树。\n雁信落、家山何处。\n万里西风吹客鬓，把菱花、自笑人如许。\n留不住，少年去。\n男儿事业无凭据。\n记当年、悲歌击楫，酒酣箕踞。\n腰下光芒三尺剑，时解挑灯夜语。\n谁更识、此时情绪。\n唤起杜陵风月手，写江东渭北相思句。\n歌此恨，慰羁旅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12542, '水龙吟', '刘过', '谪仙狂客何如，看来毕竟归田好。\n玉堂无比，三山海上，虚无飘缈。\n读罢离骚，酒香犹在，觉人间小。\n任菜花葵麦，刘郎去後，桃开处、春多少。\n一夜雪迷兰棹。\n傍寒溪、欲寻安道。\n而今纵有，新诗冰柱，有知音否。\n想见鸾飞，如椽健笔，檄书亲草。\n算平生、白傅风流，未可向、香山老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12543, '水龙吟', '刘过', '庆流阅古无穷，相门又见生名世。\n致君事业，全如忠献，经天纬地。\n十二年间，挺身为国，勋庸知几。\n便书之竹帛，铭之彝鼎，勤劳意、竟谁记。\n一自平章庶政，觉人心、顿然兴起。\n朝庭既正，乾坤交泰，华夷欢喜。\n行定中原，锦衣归相，分茅□□。\n看貂蝉绿鬓，中书上考，过三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12544, '祝英台近', '刘过', '笑天涯，还倦客。\n欲起病无力。\n风雨春归，一日近一日。\n看人结束征衫，前呵骑马，腰剑上、陇西平贼。\n鬓分白。\n只可归去家山，无田种瓜得。\n空抱遗书，憔悴小楼侧。\n杜鹃不管人愁，月明枝上，直啼到、枕边相觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12545, '柳梢青', '刘过', '泛菊杯深，吹梅角远，同在京城。\n聚散匆匆，云边孤雁，水上浮萍。\n教人怎不伤情。\n觉几度、魂飞梦惊。\n後夜相思，尘随马去，月逐舟行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12546, '霜天晓角', '刘过', '霜天晓角。\n梦回滋味恶。\n酒醒不襟寒力，纱窗外、月华薄。\n拥衾思旧约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12547, '辘轳金井・四犯翦梅花', '刘过', '翠眉重扫。\n後房深、自唤小蛮娇小。\n绣带罗垂，报浓妆才了。\n堂虚夜悄。\n但依约、鼓箫声闹。\n一曲梅花，尊前舞彻，梨园新调。\n高阳醉、玉山未倒。\n看鞋飞凤翼，钗梁微袅。\n秋满东湖，更西风凉早。\n桃源路杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12548, '好事近', '刘过', '谁斫碧琅轩，影撼半庭风月。\n尚有岁寒心在，留得数茎华发。\n龙孙戏弄碧波涛，随手清风发。\n滚到浪花深处，起一窝香雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12549, '四字令・醉太平', '刘过', '情深意真。\n眉长鬓青。\n小楼明月调筝。\n写春风数声。\n思君忆君。\n魂牵梦萦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12550, '蝶恋花', '刘过', '帘幕闻声歌已妙。\n一曲尊前，真个梅花早。\n眉黛两山谁为扫。\n风流京兆江南调。\n醉得白人易老。\n老去侯鲭，旧也曾年少。\n後夜短篷霜月晓。\n梦魂依约云山绕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12551, '蝶恋花', '刘过', '宝鉴年来微有晕。\n懒照容华，人远天涯近。\n昨夜灯花还失信。\n无心更唱江城引。\n行过短墙回首认。\n醉撼花梢，红雨飞成阵。\n拌了为郎憔悴损。\n庞儿恰似江梅韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12552, '临江仙', '刘过', '满院花香晴昼永，亭户无人。\n谁将心绪管青春。\n游丝知我懒，江柳也眉颦。\n近水远山都积恨，可堪芳草如茵。\n何曾一日不思君。\n无书凭朔雁，有泪在罗巾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12553, '临江仙', '刘过', '数叠小山亭馆静，落花红雨园林。\n画楼风月想重临。\n琵琶金凤语，长笛水龙吟。\n青眼已伤前遇少，白头孤负知音。\n苔墙藓井夜沈沈。\n无聊成独坐，有恨即沾襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12554, '临江仙', '刘过', '长短驿亭南北路，蒙茸醉拥驼裘。\n雪天行计欠人留。\n严风催酒醒，微雨替梅愁。\n自作小词呵冻写，冷金淡衬银钩。\n此情知得几时休。\n寒云迷洛浦，残梦绕秦楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12555, '临江仙', '刘过', '红袖扶来聊促膝，龙团共破春温。\n高标终是绝尘氛。\n两箱留烛影，一水试云痕。\n饮罢清风生两腋，馀香齿颊犹存。\n离情凄咽更休论。\n银鞍和月载，金碾为谁分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12556, '江城子', '刘过', '海棠风韵玉梅春。\n小腰身。\n晓妆新。\n长是花时，犹系茜罗裙。\n一撮精神娇欲滴，说不似，画难真。\n楼前江柳又江云。\n隔音尘。\n泪沾襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12557, '江城子', '刘过', '淡香幽艳露华浓。\n晚妆慵。\n略匀红。\n春困恹恹，□□鬓云松。\n早是自来莲步小，新样子，为谁弓。\n画堂西畔曲栏东。\n醉醒中。\n苦匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12558, '浣溪沙', '刘过', '黄鹤楼前识楚卿。\n彩云重叠拥娉婷。\n席间谈笑觉风生。\n标格胜如张好好，情怀浓似薛琼琼。\n半帘花月听弹筝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12559, '浣溪沙', '刘过', '墙外雨湿烟。\n参差小树绿阴圆。\n残春中酒落花前。\n海燕成巢终是客，鳏鱼入夜几曾眠。\n人间一段恶因缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12560, '浣溪沙', '刘过', '著意寻芳已自迟。\n可堪容易送春归。\n酒阑无奈思依依。\n杨柳小桥人远别，梨花深巷月斜辉，此情惟我与君知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12561, '浣溪沙', '刘过', '谁把幽香透骨薰。\n韵高全似玉楼人。\n几时劝酒不深颦。\n竹里绝怜闲体态，月边无限好精神。\n一枝斜插坐生春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12562, '浣溪沙', '刘过', '雾鬓云鬟已懒梳。\n君休乔木妾归欤。\n且来卖酒伴相如，骨细肌丰周画，肉多韵胜子瞻书。\n琵琶弦索尚能无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12563, '满庭芳', '刘过', '浅约鸦黄，轻匀螺黛，故教取次梳妆。\n减轻琶面，新样小鸾凰。\n每为花娇玉软，慵对客、斜倚银床。\n春来病，兰薰半歇，满舞衣裳。\n悲凉。\n人事改，三春艳，一夜繁霜。\n似人归洛浦，云散高唐。\n痛念平生情分，孤负我、临老风光。\n罗裙在，凭谁留意，去觅反魂香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12564, '西江月', '刘过', '细雨黄梅初熟，微风燕子交飞。\n手拈团扇写新题。\n心事恹恹难寄。\n片月只堪供恨，双星却有重期。\n石榴裙子正芬菲。\n知为何人慵系。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12565, '西江月', '刘过', '素面偏宜酒晕，晓妆净洗啼痕。\n只疑身是玉梅魂。\n长为春风瘦损。\n冉冉烟生兰渚，娟娟月挂愁村。\n落花飞絮耿黄昏。\n又是一番新恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12566, '西江月', '刘过', '楼上佳人楚楚，天边皓月徐徐。\n呼童忙为卷虾须。\n试问中情几句。\n圆少却因底事，缺多毕竟何如。\n嫦娥无语谩踌躇。\n飞过画栏西去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12567, '天仙子', '刘过', '别酒醺醺容易醉。\n回过头来三十里。\n马儿只管去如飞，牵一会。\n坐一会。\n断送杀人山共水。\n是则青衫终可喜。\n不道恩情拼得未。\n雪迷村店酒旗斜，去也是。\n住也是。\n烦恼自家烦恼你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12568, '天仙子', '刘过', '彩笔恹恹慵赋咏。\n斗草闲来寻小迳。\n西园春事只供愁，当好景。\n成孤另。\n春又那知人欲病。\n洗尽残妆临晚镜。\n淡玉一团浆水莹。\n强持檀板近芳樽，云遏定。\n君须听。\n低唱月来花弄影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12569, '六州歌头', '刘过', '中兴诸将，谁是万人英。\n身草莽，人虽死，气填膺。\n尚如生。\n年少起河朔，弓两石，剑三尺，定襄汉，开虢洛，洗洞庭。\n北望帝京。\n狡兔依然在，良犬先烹。\n过旧时营垒，荆鄂有遗民。\n忆故将军。\n泪如倾。\n说当年事，知恨苦，不奉诏，伪耶真。\n臣有罪，陛下圣，可鉴临。\n一片心。\n万古分茅土，终不到，旧奸臣。\n人世夜，白日照，忽开明。\n衮佩冕圭百拜，九泉下、荣感君恩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12570, '六州歌头', '刘过', '镇长淮，一都会，古扬州。\n升平日，珠帘十里春风、小红楼。\n谁知艰难去，边尘暗，胡马扰，笙歌散，衣冠渡，使人愁。\n屈指细思，血战成何事，万户封侯。\n但琼花无恙，开落几经秋。\n故垒荒丘。\n似含羞。\n怅望金陵宅，丹阳郡，山不断绸缪。\n兴亡梦，荣枯泪，水东流。\n甚时休。\n野灶炊烟里，依然是，宿貔貅。\n叹灯火，今萧索，尚淹留。\n莫上醉翁亭，看雨、杨柳丝柔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12571, '沁园春', '刘过', '天下稼轩，文章有弟，看来未迟。\n正三齐盗起，两河民散，势倾似土，国泛如杯。\n猛士云飞，狂胡灰灭，机会之来人共知。\n何为者，望桂林西去，一骑星驰。\n离筵不用多悲。\n唤红袖佳人分藕丝。\n种黄柑千户，梅花万里，等闲游戏，毕竟男儿。\n入幕来南，筹边如北，翻覆手高来去棋。\n公馀且，画玉簪珠履，倩米元晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12572, '八声甘州', '刘过', '问紫岩去後汉公卿，不知几貂蝉。\n谁能借留侯箸，著祖生鞭。\n依旧尘沙万里，河洛染腥膻。\n谁识道山客，衣钵曾传。\n共记玉堂对策，欲先明大义，次第筹边。\n况重湖八桂，袖手已多年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12573, '四犯翦梅花', '刘过', '水殿风凉，赐环归、正是梦熊华旦。\n叠雪罗轻，称云章题扇。\n西清侍宴。\n望黄伞、日华笼辇。\n金券三王，玉堂四世，帝恩偏眷。\n临安记、龙飞凤舞，信神明有後，竹梧阴满。\n笑折花看，橐荷香红润。\n功名岁晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12574, '小桃红・连理枝', '刘过', '晚入纱窗静。\n戏弄菱花镜。\n翠袖轻匀，玉纤弹去，小妆红粉。\n画行人、愁外两青山，兴尊前离恨。\n宿酒醺难醒。\n笑记香肩并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12575, '竹香子', '刘过', '一琐窗儿明快。\n料想那人不在。\n熏笼脱下旧衣裳，件件香难赛。\n匆匆去得忒煞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12576, '祝英台近', '刘过', '窄轻衫，联宝辔，花里控金勒。\n有底风光，都在画阑侧。\n日迟春暖融融，杏红深处，为花醉，一鞭春色。\n对娇质。\n为我歌捧瑶觞，欢歌动阡陌。\n□似多情，飞上鬓云碧。\n晚来约住青骢，蹋花归去，乱红碎、一庭风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12577, '临江仙', '刘过', '半雨半晴模样，乍寒乍热天时。\n榴花香逐湿风飞。\n绿云翻翠浪，水急转前溪。\n谁识清凉意思，珊瑚枕冷先知。\n秋光预若借些儿。\n剩催金粟闹，素魄好扬辉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12578, '鹧鸪天', '刘过', '楼外云山千万重。\n画眉人隔小帘栊。\n风垂舞柳春犹浅，雪点酥胸暖未融。\n携手处，又相逢。\n夜阑心事与郎同。\n一杯自劝羔儿酒，十幅销金暖帐笼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12579, '清平乐', '刘过', '憎憎地。\n一捻儿年纪。\n待道瘦来肥不是。\n宜著淡黄衫子。\n唇边一点樱多。\n见人频敛双蛾。\n我自金陵怀古，唱时休唱西河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12580, '西江月', '刘过', '堂上谋臣尊俎，边头将士干戈。\n天时地利与人和。\n燕可伐欤曰可。\n今日楼台鼎鼐，明年带砺山河。\n大家齐唱大风歌。\n不日四方来贺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12581, '临江仙', '刘过', '行道桥南无酒卖，老天犹困英雄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12582, '糖多令・唐多令', '刘过', '解缆蓼花湾。\n好风吹去帆。\n二十年、重过新滩。\n洛浦凌波人去後，空梦绕、翠屏间。\n飞雾湿征衫。\n苍苍烟树寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12583, '贺新郎', '刘过', '水浴芙蓉净。\n护浓香、迟开半敛，靓妆临镜。\n长忆耶溪薰风里，年少红颜照映。\n夜露冷、酒随香醒。\n回首当时同舟侣，为相思、怕折琼瑶柄。\n千万缕，意难罄。\n玻璃三万六千顷。\n洗精神、尘埃尽绝，然端整。\n浪蕊年来都慵问，爱此浓情淡性。\n待移种、灵根玉井。\n太一真人今何在，取高花、十丈供烟艇。\n来伴我，泛清影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12584, '清平乐', '刘过', '新来塞北。\n传到真消息。\n赤地居民无一粒。\n更五单于争立。\n维师尚父鹰扬。\n熊罴百万堂堂。\n看取黄金假钺，归来异姓真王。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12585, '西吴曲', '刘过', '说襄阳、旧事重省。\n记铜驼巷陌、醉还醒。\n笑莺花别後，刘郎憔悴萍梗。\n倦客天涯，还买个、西风轻艇。\n便欲访、骑马山翁，问岘首、那时风景。\n楚王城里，知几度经过，摩挲故宫柳瘿。\n漫吊景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12586, '好事近', '蔡幼学', '日日惜春残，春去更无明日。\n拟把醉同春住，又醒来岑寂。\n明年不怕不逢春，娇春怕无力。\n待向灯前休睡，与留连今夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12587, '西江月', '卢炳', '残雪犹馀远岭。\n晚烟半隐寒林。\n溶溶春涨绿波深。\n时有渔人钓艇。\n倚岸野梅坠粉。\n蘸溪宫柳摇金。\n凭栏凝伫酒初醒。\n料得谁知此景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12588, '念奴娇', '卢炳', '晚天清楚，扫太虚纤翳，凉生江曲。\n四顾青冥天地阔，惟有残霞孤骛。\n山气凝蓝，汀烟引素，竦竦浮群木。\n白苹风定，波澄万顷寒玉。\n时有一叶渔舟，收纶垂钓，来往何幽独。\n短发萧萧襟袖冷，便觉都无袢褥。\n曳杖归来，夜深人悄，月照鳞鳞屋。\n藤床一枕，迥然清梦无俗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12589, '鹊桥仙', '卢炳', '馀霞散绮，明河翻雪。\n隐隐鹊桥初结。\n牛郎织女两逢迎，□胜却、人间欢悦。\n一宵相会，经年离别。\n此语真成浪说。\n细思怎得似嫦娥，解独宿、广寒宫阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12590, '柳梢青', '卢炳', '兰蕙心情，海棠韵度，杨柳腰肢。\n步稳金莲，手纤春笋，肤似凝脂。\n歌生舞态都宜。\n拚著个、坚心共伊。\n无奈相思，带围宽尽，说与教知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12591, '柳梢青', '卢炳', '雅淡精神，铅黄未洗，犹带残妆。\n春艳一枝，鹅儿颜色，染就纤裳。\n月移影转南窗。\n特地送、些儿暗香。\n宿酒初醒，这般滋味，梦断池塘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12592, '谒金门', '卢炳', '春寂寂。\n节物又催寒食。\n楼上卷帘双燕入。\n断魂愁似织。\n门外雨馀风急。\n满地落英红湿。\n好梦惊回无处觅。\n天涯芳草碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12593, '谒金门', '卢炳', '春事寂。\n苦笋鲥鱼初食。\n风卷绣帘飞絮入。\n柳丝萦似织。\n迅速韶光去急。\n过雨绿阴尤湿。\n回首旧游何处觅。\n远山空伫碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12594, '谒金门', '卢炳', '门巷寂。\n梅豆微酸怯食。\n别恨萦心愁易入。\n寸肠如网织。\n去橹咿哑声急。\n泪滴春衫轻湿。\n尺素待凭鱼雁觅。\n远烟凝处碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12595, '浣溪沙', '卢炳', '水阁无尘午昼长。\n薰风十里藕花香。\n一番疏雨酿微凉。\n旋点新茶消睡思，不将恼诗肠。\n阑干倚遍挹湖光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12596, '贺新郎', '卢炳', '绿遍芳郊木。\n早红褪香乾，堪叹韶华瞬目。\n薄东皇缘底事，得恁匆匆去速。\n正永日、初长晴淑。\n尤忆夜来成梦处，记分明、浑似瑶台宿。\n人语静，燕双逐。\n纱窗一炷沈烟馥。\n拚淋浪剧饮，高枕春酲草屋。\n无计留春添怅望，空写新词叠幅。\n算负却、照妆画烛。\n欲说萦心些个事，恐教人、蹙损眉峰绿。\n慵倚遍，画阑曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12597, '菩萨蛮', '卢炳', '梦回小枕寒玉。\n博山香暖沈烟续。\n帷薄怯轻纱。\n风牵幌带斜。\n夜窗云影细。\n月送花阴至。\n身世在陶唐。\n闲愁不挂肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12598, '好事近', '卢炳', '庭院欲昏黄，秋思恼人情乱。\n宝瑟试弹新曲，更与谁同伴。\n阳台魂梦杳无踪，奴住巫山畔。\n不似楚襄云雨，俏输他一半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12599, '减字木兰花', '卢炳', '传消寄息。\n咫尺远如千里隔。\n欲见无由。\n惹起新愁与旧愁。\n情怀如醉。\n枕连宵终不寐。\n无奈相思。\n此恨凭谁说与伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12600, '画堂春', '卢炳', '轻红桃杏斗娇妍。\n晓来葱祥烟。\n霓旌绛节下云天。\n行地神仙。\n盛事频封锦诰，歌声齐劝金莲。\n教从沧海变桑田。\n富贵长年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12601, '临江仙', '卢炳', '弱水蓬莱真胜地，祥烟闪烁霓旌。\n瑶池欢会下云。\n康宁新喜事，淑善旧家声。\n戏采捧觞真乐事，蟠桃献寿千春。\n从今更愿子孙荣。\n加恩封锦诰，学道诵黄庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12602, '踏莎行', '卢炳', '秋色人家，夕阳洲渚。\n西风催过黄华渡。\n江烟引素忽飞来，水禽破暝双双去。\n奔走红尘，栖迟羁旅。\n断肠犹忆江南句。\n白云低处雁回峰，明朝便踏潇湘路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12603, '杏花天', '卢炳', '镂冰翦玉工夫费。\n做六出、飞花乱坠，舞风情态谁相似。\n算只有、江梅可比。\n极目处、瑶万里。\n海天阔、清寒似水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12604, '水调歌头', '卢炳', '华亭新伟观，胜地得高雄。\n凭栏徙倚要眇，万里景无穷。\n好是江流萦绕，那更云天舒阔，叠嶂倚晴空。\n眼界无尽藏，怀抱有清风。\n主人贤，开绮席，泛金锺。\n放怀一笑，许我满酌醉颜红。\n祗恐玺书即下，促起飞凫东去，行作黑头公。\n还记今朝客，曾待一杯同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12605, '鹧鸪天', '卢炳', '初过清明春昼长。\n紫红香雾蔼华堂。\n朱颜阿母逢生旦，采戏儿孙捧寿觞。\n齐祝颂，喜平康。\n天教两鬓正苍苍。\n壶中日月应长久，笑看蟠桃几度芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12606, '菩萨蛮', '卢炳', '石榴裙束纤腰袅。\n金莲稳衬弓靴小。\n娇呆□羞人。\n伞低遮半身。\n恩情如纸薄。\n方信当初错。\n邂逅苦匆匆。\n还疑是梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12607, '踏莎行', '卢炳', '雅淡容仪，温柔情性。\n偏伊赋得多风韵。\n明眸剪水玉为肌，凤鞋弓小金莲衬。\n相见虽频，欢娱无定。\n蛮笺写了凭谁问。\n坚心好事有成时，须教人道都相称。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12608, '贺新郎', '卢炳', '池管闲凝目。\n有玉人、向晚妖娆，洗妆梳束。\n雅淡容仪妃子样，羞使胭脂点触。\n莹冰雪、精神难掬。\n好是月明微露下，似晚凉、初向清泉浴。\n好对我，笑羞缩。\n好风拂面浑无俗。\n更撩人清兴，异香芬馥。\n惹起新愁无著处，细与端相未足。\n俏不忍、游蝶飞扑。\n可惜伊家娇媚态，问天公、底事教幽独。\n待拉向，锦屏曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12609, '水调歌头', '卢炳', '风驭过姑射，云挹浮丘。\n丁宁月姊，为我澄霁一天秋。\n尽展冰奁玉鉴，要看瑶台银阙，万里冷浮光。\n分与世间景，好在水边楼。\n想霓裳，呈妙舞，起清讴。\n蓝桥何处，试寻玉杵恣追游。\n拟待铅霜捣就，缓引琼浆沈醉，谁信是良筹。\n长啸跨鲸背，不必愿封留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12610, '武陵春', '卢炳', '红荻黄芦秋已老，妆点楚江头。\n更有吴姬拨小桡。\n来往自妖娆。\n款款舣舟临别岸，短缆系花梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12611, '朝中措', '卢炳', '晓来天气十分凉。\n时候近重阳。\n村落人家潇洒，篱菊有芬芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12612, '小重山', '卢炳', '一见情怀便雅投。\n尊前成密约，意绸缪。\n已成行计理归舟。\n空相忆，无计为伊留。\n执别话离愁。\n萦萦滋味恶，在心头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12613, '玉团儿', '卢炳', '绿云慢绾新梳束。\n这标致、诸馀不俗。\n邂逅相逢，情怀雅合，全似深熟。\n耳边笑语论心曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12614, '醉蓬莱', '卢炳', '正春回紫陌，瑞霭飞浮，暖风轻扇。\n皓月初圆，觉严城寒浅。\n采结鳌山，纱笼银烛，与□花争艳。\n午夜融和，红莲万顷，一齐开遍。\n讼简民熙，史君行乐，簇拥朱轮，旌旗辉暖。\n鼎沸笙歌，遏行云不散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12615, '一剪梅・一翦梅', '卢炳', '灯火楼台万斛莲。\n千门喜笑，素月婵娟。\n几多急莞与繁弦。\n巷陌骈阗。\n毕献芳筵。\n乐与民偕五马贤。\n绮罗丛里，一簇神仙。\n传柑雅宴约明年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12616, '满江红', '卢炳', '碧眼真仙，算元住、蓬莱宫里。\n记当日、等闲跨鹤，人间游戏。\n要把忠勋扶帝业，更将姓字联宗系。\n拥朱轮、特地为民来，诗书帅。\n千里地，都和气。\n十万户，生欢喜。\n祝黄堂眉寿，歌谣鼎沸。\n莫惜春醅供燕豆，便承芝检朝天陛。\n看云屏、隔坐并貂蝉，双清贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12617, '水调歌头', '卢炳', '再拜识英度，喜气觉飞浮。\n神清骨秀，元是蓬莱谪仙流。\n盍去冲摩霄汉，刚向平分风月，半刺岭南州。\n素蕴未施展，阔步尚淹留。\n从此去，朝帝阙，侍宸旒。\n论思献替，要须直与古人侔。\n好是羽仪朝著，勒就鼎彝勋业，却伴赤松游。\n曳杖太湖曲，笑傲八千秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12618, '清平乐', '卢炳', '玻璃翦叶。\n点缀黄金屑。\n雅淡幽姿风味别。\n翠影婆娑弄月。\n秋光占断江南。\n清香鼻观先参。\n一朵折来和露，乌云髻畔斜簪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12619, '念奴娇', '卢炳', '凿开方沼，问何人种玉、工夫奇绝。\n幻出瀛州有□□，十万水仙罗列。\n风曳琚，露零珠，天上人装结。\n君看炎夏，堕来何处冰雪。\n我来对此凉生，红尘飞尽，却笑凌波袜。\n最爱幽姿能雅淡，自蓄芳馨孤洁。\n挹取天浆，唤将空籁，齐作清歌发。\n不知尘世，晃然身在瑶阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12620, '念奴娇', '卢炳', '碧池如染，把玻璃就，纤埃都绝。\n西国夫人空里坠，圆盖亭亭排列。\n莹质无暇，尘心不染，远社堪重结。\n当时盛事，虎溪茗碗翻雪。\n千载此意谁论，人争买笑，醉眼看罗袜。\n坐上如今皆我辈，素蕴从来蠲洁。\n击节临风，停杯对月。\n浩气俱英发。\n两翁仙举，玉堂正在金阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12621, '念奴娇', '卢炳', '好风明月，共芙蕖、占作人间三绝。\n试问千花还□□，敢与英姿同列。\n一曲千锺，凌云长啸，舒放愁肠结。\n人生易老，莫教双鬓添雪。\n回首蝇利蜗名，微官多误，自笑尘生袜。\n争似玉人真妩媚，表里冰壶明洁。\n露下寒生，参横斗转，又听胡笳发。\n夜阑人静，一声清透云阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12622, '瑞鹧鸪', '卢炳', '客里惊嗟又岁除。\n萧萧寒雨滴茅庐。\n山深溪转泉声碎，夜永风摇烛影孤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12623, '武陵春', '卢炳', '常忆江南春欲到，消息付南枝。\n疏影横斜照水时。\n月淡暗香迟。\n可惜江头千树玉，雨暗更风欺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12624, '鹧鸪天', '卢炳', '秋月明眸两鬓浓。\n衫儿贴体绉轻红。\n清声宛转歌金缕，纤手殷勤捧玉锺。\n娇娅姹，语惺松。\n酒香沸沸透羞容。\n刘郎莫恨相逢晚，且喜桃源路已通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12625, '蓦山溪', '卢炳', '淡妆西子，怎比西湖好。\n南北两长堤，有罨画、楼台多少。\n翠光千顷，一片净琉璃，泛兰舟，摇画桨，尽日金尊倒。\n名园精舍，总被游人到。\n年少与佳人，共携手、嬉游歌笑。\n夕阳西下，沈醉尽归来，鞭宝马，闹竿随，簇著花藤轿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12626, '蓦山溪', '卢炳', '韶华七换，阻庆生申旦。\n今日向高堂，载卮酒、为君满劝。\n绣帘低挂，瑞霭□香浓，倩双娥，敲象板，缓缓歌珠贯。\n芝兰挺秀，俱是皇家彦。\n只这一般奇，见方寸、平生积善。\n几多厚德，天锡与遐龄，鬓长青，颜不老，日日开华宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12627, '减字木兰花', '卢炳', '莎衫筠笠。\n正是村村农务急。\n绿水千畦。\n惭愧秧针出得齐。\n风斜雨细。\n麦欲黄时寒又至。\n妇耕夫。\n画作今年稔岁图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12628, '满江红', '卢炳', '积雨连朝，添新涨、一篙春碧。\n寒犹在、东风料峭，柳丝无力。\n系惹画船都不住，从教兰棹双飞急。\n泛大江、东去欲何之，瓜期迫。\n龙锺裔，神仙伯。\n金闺彦，文章客。\n算河阳花县，恁生留得。\n制锦才高书善最，鸣琴化洽人欢怿。\n想未容、坐暖诏归来，君王侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12629, '踏莎行', '卢炳', '猎猎霜风，晓雾。\n归来喜踏江南路。\n千林翠幄半红黄，试看青女工夫做。\n茅舍疏篱，竹边低户。\n谁家酒滴真珠露。\n旋酤一盏破清寒，趁晴同过黄花渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12630, '蝶恋花', '卢炳', '满架冰蕤开遍了。\n试问花神，留得春多少。\n清胜荀香娇韵好。\n谢庭风月应难到。\n酒酿新醅名不老。\n醉倒花前，真个无烦恼。\n满座清欢供一笑。\n春酲拼却明窗晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12631, '点绛唇', '卢炳', '过眼溪山，向来都是经行处。\n骖鸾人去。\n冷落吹箫侣。\n小立江亭，愁对蒹葭浦。\n无情绪。\n酒杯慵举。\n闲看江枫舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12632, '诉衷情', '卢炳', '无端风雨送清秋。\n天气冷飕飕。\n行人先自离索，直是不禁愁。\n思往事，忆前游。\n泪难收。\n重阳近也，黄花依旧，谁伴清瓯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12633, '念奴娇', '卢炳', '快风收雨，正江城初霁，物华如许。\n丽日融和春思好，是处莺啼燕语。\n嫩绿成阴，落红堆绣，只恐春将暮。\n园林清昼，看看又见飞絮。\n太守无限风流，铃斋多暇，载酒郊原路。\n几队旌旗光闪烁，鼓吹更翻新谱。\n曲水流觞，兰亭修禊，俯仰成今古。\n为君一醉，归时楼上初鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12634, '冉冉云', '卢炳', '雨洗千红又春晚。\n留牡丹、倚阑初绽。\n娇娅姹、偏赋精神君看。\n算费尽、工夫点染。\n带露天香最清远。\n太真妃、院妆体段。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12635, '减字木兰花', '卢炳', '冰姿雪艳。\n天赋精神偏冷淡。\n惟有清香。\n何逊扬州暗断肠。\n孤芳好处。\n消得骚人题妙句。\n皴寒枝。\n未必生绡画得宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12636, '鹧鸪天', '卢炳', '阁雨浮云寒尚轻。\n商量雪意未全成。\n莫嫌竹外萧然处，忽有幽香透鼻清。\n诗兴逸，酒魂醒。\n主人留客更多情。\n不辞满引成痴客，且把梅花醉一觥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12637, '水龙吟', '卢炳', '晚晴一碧天如水，风约尘埃都扫。\n素娥睡起，玉轮稳驾，初离海表。\n碾破秋云，涌成银阙，光欺南斗。\n想广寒宫里，风流女伴，应都把、仙歌奏。\n夜永风生悄悄。\n耀冰雪、寒侵重峤。\n今宵休道，从来此夕，阴多晴少。\n坐久更深，露冷襟袖，不禁清晓。\n更天风吹下，桂香拂袂，想蟠根老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12638, '柳梢青', '卢炳', '笑菊欺梅。\n嫌蜂却蝶，压尽寒。\n月下精神，醉时风韵，红透香腮。\n天工造化难猜。\n甚怪我、愁眉未开。\n故遣名花，凌霜带露，先送春来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12639, '少年游', '卢炳', '绣罗子间金丝。\n打扮好容仪。\n晓雪明肌，秋波入鬓，鞋小步行迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12640, '汉宫春', '卢炳', '向暖南枝，最是他潇洒，先带春回。\n因何事、向岁晚，搀占花魁。\n天公著意，安排巧、特地教开。\n知道是，仙翁诞节，琼英要泛金杯。\n人学寿阳妆面，正梁州初按，羯鼓声催。\n年年此花开後，宴启蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12641, '多丽', '卢炳', '庆佳辰。\n熊罴协梦生申。\n记当年、曾游月殿，笑谈高跃龙津。\n德弥高、源流孔孟，才迥出、黼黻卿云。\n亟步华涂，蜚英腾茂，姓名端的简枫宸。\n最好是、雍容兰省，直道事吾君。\n还知否，承明倦直，来抚斯民。\n算人生、五马最贵，朱画戟行春。\n讼庭清、祥风和畅，铃斋静、佳气氤氲。\n寿宴香浓，梅繁柳嫩，年年今日劝芳尊。\n须信道、朱颜不老，眉寿等松椿。\n从兹去，衮衣特立，廊庙经纶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12642, '满江红', '卢炳', '媚景良时，无非是、三春富贵。\n花共柳、著工夫染，嫩红轻翠。\n日丽风和薰协气。\n莺吟燕舞皆欢意。\n况生辰、恰恰值清明，笙歌沸。\n分天派，真龙裔。\n到月殿，攀仙桂。\n看眉间黄色，诏书将至。\n莫向蓝田分佐理。\n便趋紫禁参朝对。\n问玉皇、仙籍注长生，三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12643, '蝶恋花', '卢炳', '罗幕护寒遮晓雾。\n爱日烘晴，又是年华暮。\n潇洒江梅争欲吐。\n暗香漏泄春来处。\n何日寻芳溪畔路。\n挈携筇，写景论心素。\n千里相逢真会遇。\n羡君解道江南句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12644, '水调歌头', '卢炳', '富贵本何物，底用苦趋奔。\n都为造物娱弄，人事覆来翻。\n须索高抬目力，觑破祗同儿戏，不必更重论。\n但愿吾长健，赢得日加飨。\n衣轻裘，乘驷马，驾高轩。\n算来荣耀，终输渔叟钓江村。\n休叹谋身太拙，未必折腰便是，炙手几曾温。\n清议不可辱，千古要长存。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12645, '满江红', '卢炳', '罨画池亭，对十万、盈盈粉面。\n依翠盖、临风一曲，霓裳舞遍。\n亭上人如蓬岛客，坐中别有飞琼伴。\n占世间、风月最清凉，宜开宴。\n当盛旦，歌喉啭。\n齐祝寿，金尊劝。\n算才华合侍，玉皇香案。\n处事从来坚特操，立朝更要持公论。\n使他时、台阁振风声，朝天眷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12646, '诉衷情', '卢炳', '柴扉人寂草生畦。\n藤蔓乱萦篱。\n秋净楚天如水，云叶度墙低。\n同把盏，且伸眉。\n对残晖。\n红茱笑拈，黄菊斜簪，恋饮忘归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12647, '浣溪沙', '卢炳', '常记京华昔浪游。\n青罗买笑万金酬。\n醉中曾此当貂裘。\n自恨山翁今老矣，惜花心性谩风流。\n清樽独酌更何愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12648, '清平乐', '卢炳', '方池小小。\n风摺玻璃皱。\n数朵荷花开更好。\n把住薰风一笑。\n芳容淡注胭脂。\n亭亭翠叶相依。\n只欠一双，便如画底屏帷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12649, '菩萨蛮', '卢炳', '而今怕听相思曲。\n多情蹙损眉峰绿。\n惜别上扁舟。\n望穷江际楼。\n蛮笺封了发。\n为忆人如雪。\n离恨写教看。\n休令盟约寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12650, '小重山令・小重山', '姜夔', '人绕湘皋月坠时。\n斜横花树小，浸愁漪。\n一春幽事有谁知。\n东风冷、香远茜裙归。\n鸥去昔游非。\n遥怜花可可，梦依依。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12651, '江梅引・江城梅花引', '姜夔', '人间离别易多时。\n见梅枝。\n忽相思。\n几度小窗，幽梦手同携。\n今夜梦中无觅处，漫徘徊。\n寒侵被、尚未知。\n湿红恨墨浅封题。\n宝筝空、无雁飞。\n俊游巷陌，算空有、古木斜晖。\n旧约扁舟，心事已成非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12652, '蓦山溪', '姜夔', '与鸥为客。\n绿野留吟屐。\n雨行柳垂阴，是当日、仙翁手植。\n一亭寂寞。\n烟外带愁横，荷苒苒，展凉云，横卧虹千尺。\n才因老尽，秀句君休觅。\n万绿正迷人，更愁入、山阳夜笛。\n百年心事，惟有玉阑知，吟未了，放船回，月下空相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12653, '莺声绕红楼', '姜夔', '十亩梅花作雪飞。\n冷香下、携手多时。\n两年不到断桥西。\n长笛为予吹。\n人妒垂杨绿，春风为、染作仙衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12654, '鬲溪梅令', '姜夔', '好花不与香人。\n浪粼粼。\n又恐春风归去绿成阴。\n玉钿何处寻。\n木兰双桨梦中云。\n小横陈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12655, '阮郎归', '姜夔', '红云低压碧玻璃。\n惺惚花上啼。\n静看楼角拂长枝。\n朝寒吹翠眉。\n休涉笔，且裁诗。\n年年风絮时。\n绣衣夜半草符移。\n月中双桨归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12656, '阮郎归', '姜夔', '旌阳宫殿昔徘徊。\n一坛云叶垂。\n与君闲看壁间题。\n夜凉笙鹤期。\n茅店酒，寿君时。\n老枫临路歧。\n年年强健得追随。\n名山游遍归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12657, '好事近', '姜夔', '凉夜摘花钿，苒苒动摇云绿。\n金络一团香露，正纱厨人独。\n朝来碧缕放长穿，钗头挂层玉。\n记得如今时候，正荔枝初熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12658, '点绛唇', '姜夔', '燕雁无心，太湖西畔随云去。\n数峰清苦。\n商略黄昏雨。\n第四桥边，拟共天随住。\n今何许。\n凭栏怀古。\n残柳参差舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12659, '点绛唇', '姜夔', '金谷人归，绿扬低扫吹笙道。\n数声啼鸟。\n也学相思调。\n月落潮生，掇送刘郎老。\n淮南好。\n甚时重到。\n陌上生春草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12660, '虞美人', '姜夔', '西园曾为梅花醉。\n叶翦春云细。\n玉笙凉夜隔帘吹。\n卧看花梢摇动、一枝枝。\n娉娉袅袅教谁惜。\n空压纱巾侧。\n沈香亭北又青苔。\n唯有当时蝴蝶、自飞来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12661, '虞美人', '姜夔', '摩挲紫盖峰头石。\n上瞰苍崖立。\n玉盘摇动半崖花。\n花树扶蔬、一半白云遮。\n盈盈相望无由摘。\n惆怅归来屐。\n而今仙迹杳难寻。\n那日青楼、曾见似花人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12662, '忆王孙', '姜夔', '冷红叶叶下塘秋。\n长与行云共一舟。\n零落江南不自由。\n两绸缪。\n料得吟鸾夜夜愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12663, '少年游', '姜夔', '双螺未合，双蛾先敛，家在碧云西。\n别母情怀，随郎滋味，桃叶渡江时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12664, '鹧鸪天', '姜夔', '京洛风流绝代人。\n因何风絮落溪津。\n笼鞋浅出鸦头袜，知是凌波漂渺身。\n红乍笑，绿长。\n与谁同度可怜春。\n鸳鸯独宿何曾惯，化作西楼一缕云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12665, '鹧鸪天', '姜夔', '曾共君侯历聘来。\n去年今日踏莓苔。\n旌扬宅里疏疏磬。\n挂枫前草草杯。\n呼煮酒，摘青梅。\n今年官事莫徘徊。\n移家径入蓝田县，急急船头打鼓催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12666, '鹧鸪天', '姜夔', '柏绿椒红事事新。\n隔篱灯影贺年人。\n三茅钟动西窗晓，诗鬓无端又一春。\n慵对客，缓开门。\n梅花闲伴老来身。\n娇儿学作人间字，郁垒神荼写未真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12667, '鹧鸪天', '姜夔', '巷陌风光纵赏时。\n笼纱未出马先嘶。\n白头居士无呵殿，只有乘肩小女随。\n花满市，月侵衣。\n少年情事老来悲。\n沙河塘上春寒浅，看了游人缓缓归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12668, '鹧鸪天', '姜夔', '忆昨天街预赏时。\n柳悭梅小未教知。\n而今正是欢游夕，却怕春寒自掩扉。\n帘寂寂，月低低。\n旧情惟有绛都词。\n芙蓉影暗三更後，卧听邻娃笑语归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12669, '鹧鸪天', '姜夔', '肥水东流无尽期。\n当初不合种相思。\n梦中未比丹青见，暗里忽惊山鸟啼。\n春未绿，鬓先丝。\n人间别久不成悲。\n谁教岁岁红莲夜，两处沈吟各自知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12670, '鹧鸪天', '姜夔', '辇路珠帘两行垂。\n千枝银烛舞。\n东风历历红楼下，谁识三生杜牧之。\n欢正好，夜何其。\n明朝春过小桃枝。\n鼓声渐远游人散，惆怅归来有月知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12671, '夜行船', '姜夔', '略横溪人不度。\n听流澌、佩环无数。\n屋角垂枝，船头生影，算唯有、春知处。\n回首江南天欲暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12672, '杏花天', '姜夔', '绿丝低拂鸳鸯浦。\n想桃叶、当时唤渡。\n又将愁眼与春风，待去。\n倚兰桡、更少驻。\n金陵路。\n莺吟燕舞。\n算潮水、知人最苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12673, '醉吟商小品・小品', '姜夔', '又正是春归，细柳暗黄千缕。\n暮鸦啼处。\n梦逐金鞍去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12674, '玉梅令', '姜夔', '疏疏雪片。\n散入溪南苑。\n春寒锁、旧家亭馆。\n有玉梅几树，背立怨东风，高花未吐，暗香已远。\n公来领略，梅花能劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12675, '踏莎行', '姜夔', '燕燕轻盈，莺莺娇软。\n分明又向华胥见。\n夜长争得薄情知，春初早被相思染。\n别後书辞，别时针线。\n离魂暗逐郎行远。\n淮南皓月冷千山，冥冥归去无人管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12676, '诉衷情', '姜夔', '石榴一树浸溪红。\n零落小桥东。\n五日凄凉心事，山雨打船篷。\n谙世味，楚人弓。\n莫忡忡。\n白头行客，不采苹花，孤负薰风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12677, '浣溪沙', '姜夔', '著酒行行满袂风。\n草枯霜鹘落晴空。\n销魂都在夕阳中。\n恨入四弦人欲老，梦寻千驿意难通。\n当时何似莫匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12678, '浣溪沙', '姜夔', '春点疏梅雨後枝。\n翦灯心事峭寒时。\n市桥携手步迟迟。\n蜜炬来时人更好，玉笙吹彻夜何其。\n东风落靥不成归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12679, '浣溪沙', '姜夔', '钗燕笼云晚不。\n拟将裙带系郎船。\n别离滋味又今年。\n杨柳夜寒犹自舞，鸳鸯风急不成眠。\n些儿闲事莫萦牵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12680, '浣溪沙', '姜夔', '雁怯重云不肯啼。\n画船愁过石塘西。\n打头风浪恶禁持。\n春浦渐生迎棹绿，小梅应长亚门枝。\n一年灯火要人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12681, '浣溪沙', '姜夔', '花里春风未觉时。\n美人呵蕊缀横枝。\n隔帘飞过蜜蜂儿。\n书寄岭头封不到，影浮杯面误人吹。\n寂寥惟有夜寒知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12682, '浣溪沙', '姜夔', '翦翦寒花小更垂。\n阿琼愁里弄妆迟。\n东风烧烛夜深归。\n落蕊半黏钗上燕，露黄斜映鬓边犀。\n老夫无味已多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12683, '霓裳中序第一', '姜夔', '亭皋正望极。\n乱落江莲归未得。\n多病却无气力。\n况纨扇渐疏，罗衣初萦。\n流光过隙。\n叹杏梁、双燕如客。\n人何在，一帘淡月，仿佛照颜色。\n幽寂。\n乱蛩吟壁。\n动庾信、清愁似织。\n沈思年少浪迹。\n笛里关山，柳下坊陌。\n坠红无信息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12684, '庆宫春・高阳台', '姜夔', '双桨莼波，一蓑松雨，暮愁渐满空阔。\n呼我盟鸥，翩翩欲下，背人还过木末。\n那回归去，荡云雪、孤舟夜发。\n伤心重见，依约眉山，黛痕低压。\n采香径里春寒，老子婆娑，自歌谁答。\n垂虹西望，飘然引去，此兴平生难遏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12685, '齐天乐', '姜夔', '庾郎先自吟愁赋。\n凄凄更闻私语。\n露湿铜铺，苔侵石井，都是曾听伊处。\n哀音似诉。\n正思妇无眠，起寻机杼。\n曲曲屏山，夜凉独自甚情绪。\n西窗又吹暗雨。\n为谁频断续，相和砧杵。\n候馆迎秋，离宫吊月，别有伤心无数。\n豳诗漫与。\n笑篱落呼灯，世间儿女。\n写入琴丝，一声声更苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12686, '满江红', '姜夔', '仙姥来时，正一望、千倾翠澜。\n旌旗共、乱云俱下，一依前山。\n命驾群龙金作轭，相从诸娣玉为冠。\n向夜深、风定悄无人，闻佩环。\n神奇处，君试看。\n奠淮右，诅江南。\n遣六丁雷电，别守东关。\n却笑英雄无好手，一篙春水走曹瞒。\n又怎知、人在小红楼，帘影间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12687, '一萼红', '姜夔', '古城阴。\n有官梅几许，红萼未宜簪。\n池面冰胶，墙腰雪老，云意还又沈沈。\n翠藤共、闲穿径竹，渐笑语、惊起卧沙禽。\n野老林泉，故王台榭，呼唤登临。\n南去北来何事，荡湘云楚水，目极伤心。\n朱户黏鸡，金盘簇燕，空叹时序侵寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12688, '念奴娇', '姜夔', '闹红一舸，记来时、尝与鸳鸯为侣。\n三十六陂人未到，水佩风裳无数。\n翠叶吹凉，玉容销酒，更洒菰蒲雨。\n嫣然摇动，冷香飞上诗句。\n日暮。\n青盖亭亭，情人不见，争忍凌波去。\n只恐舞衣寒易落，愁入西风南浦。\n高柳垂阴，老鱼吹浪，留我花间住。\n田田多少，几回沙际归路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12689, '念奴娇', '姜夔', '楚山修竹，自娟娟、不受人间袢暑。\n我醉欲眠伊伴我，一枕凉生如许。\n象齿为材，花藤为面，终是无真趣。\n梅风吹溽，此君直恁清苦。\n须信下榻殷勤，け然成梦，梦与秋相遇。\n翠袖佳人来共看，漠漠风烟千亩。\n蕉叶窗纱，荷花池馆，别有留人处。\n此时归去，为君听尽秋雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12690, '眉妩', '姜夔', '看垂杨连苑，杜若侵沙，愁损未归眼。\n信马青楼去，重帘下，娉婷人妙飞燕。\n翠尊共款。\n听艳歌、郎意先感。\n便携手、月地云阶里，爱良夜微暖。\n无限。\n风流疏散。\n有暗藏弓履，偷寄香翰。\n明日闻津鼓，湘江上，催人还解春缆。\n乱红万点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12691, '月下笛', '姜夔', '与客携壶，梅花过了，夜来风雨。\n幽禽自语。\n啄香心、度墙去。\n春衣都是柔荑翦，尚沾惹、残茸半缕。\n怅玉钿似扫，朱门深闭，再见无路。\n凝伫。\n曾游处。\n但系马垂杨，认郎鹦鹉。\n扬州梦觉，彩云飞过何许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12692, '清波引', '姜夔', '冷云迷浦。\n倩谁唤、玉妃起舞。\n岁华如许。\n野梅弄眉妩。\n屐齿印苍藓，渐为寻花来去。\n自随秋雁南来，望江国、渺何处。\n新诗漫与。\n好风景、长是暗度。\n故人知否。\n抱幽恨难语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12693, '法曲献仙音', '姜夔', '虚阁笼寒，小帘通月，暮色偏怜高处。\n树隔离宫，水平驰道，湖山尽入尊俎。\n奈楚客淹留久，砧声带愁去。\n屡回顾。\n过秋风、未成归计。\n谁念我、重见冷枫红舞。\n唤起淡妆人，问逋仙、今在何许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12694, '琵琶仙・自度曲', '姜夔', '双桨来时，有人似、旧曲桃根桃叶。\n歌扇轻约飞花，蛾眉正奇绝。\n春渐远、汀洲自绿，更添了、几声啼。\n十里扬州，三生杜牧，前事休说。\n又还是、宫烛分烟，奈愁里、匆匆换时节。\n都把一襟芳思，与空阶榆荚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12695, '玲珑四犯', '姜夔', '叠鼓夜寒，垂灯春浅，匆匆时事如许。\n倦游欢意少，俯仰悲今古。\n江淹又吟恨赋。\n记当时、送君南浦。\n万里乾坤，百年身世，唯有此情苦。\n扬州柳，垂官路。\n有轻盈换马，端正窥户。\n酒醒明月下，梦逐潮声去。\n文章信美知何用，漫赢得、天涯羁旅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12696, '侧犯', '姜夔', '恨春易去。\n甚春却向扬州住。\n微雨。\n正茧栗梢头弄诗句。\n红桥二十四，总是行云处。\n无语。\n渐半脱宫衣笑相顾。\n金壶细叶，千朵围歌舞。\n谁念我、鬓成丝，来此共尊俎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12697, '水龙吟', '姜夔', '夜深客子移舟处，两两沙禽惊起。\n红衣入浆，青灯摇浪，微凉意思。\n把酒临风，不思归去，有如此水。\n况茂林游倦，长干望久，芳心事、箫声里。\n屈指归期尚未。\n鹊南飞、有人应喜。\n画栏桂子，留香小待，提携影底。\n我已情多，十年幽梦，略曾如此。\n甚谢郎、也恨飘零，解道月明千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12698, '探春慢', '姜夔', '衰草愁烟，乱鸦送日，风沙回旋平野。\n拂雪金鞭，欺寒茸帽，还记章台走马。\n谁念飘零久，漫赢得、幽怀难写。\n故人清沔相逢，小窗闲共情话。\n长恨离多会少，重访问竹西，珠泪盈把。\n雁碛波平，渔汀人散，老去不堪游冶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12699, '八归', '姜夔', '芳莲坠粉，蔬桐吹绿，庭院暗雨乍歇。\n无端抱影销魂处，还见筱墙萤暗，藓阶蛩切。\n送客重寻西去路，问水面、琵琶谁拨。\n最可惜、一片江山，总付与啼。\n长恨相从未款，而今何事，又对西风离别。\n渚寒烟淡，棹移人远，缥缈行舟如叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12700, '解连环', '姜夔', '玉鞭重倚。\n却沈吟未上，又萦离思。\n为大乔、能拨春风，小乔妙移筝，雁啼秋水。\n柳怯云松，更何必、十分梳洗。\n道郎携羽扇，那日隔帘，半面曾记。\n西窗夜凉雨霁。\n叹幽欢未足，何事轻弃。\n问後约、空指蔷薇，算如此溪山，甚时重至。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12701, '喜迁莺慢・喜迁莺', '姜夔', '玉珂朱组。\n又占了、道人林下真趣。\n窗户新成，青红犹润，双燕为君胥宇。\n秦淮贵人宅第，问谁记、六朝歌舞。\n总付与、在柳桥花馆，玲珑深处。\n居士。\n闲记取。\n高卧未成，且种松千树。\n觅句堂深，写经窗静，他日任听风雨。\n列仙更教谁做，一院双成俦侣。\n世间住。\n且休将鸡犬，云中飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12702, '摸鱼儿', '姜夔', '向秋来、渐疏班扇，雨声时过金井。\n堂虚已放新凉入，湘竹最宜枕。\n闲记省。\n又还是、斜河旧约今再整。\n天风夜冷。\n自织锦人归，乘槎客去，此意有谁领。\n空赢得，今古三星炯炯。\n银波相望千顷。\n柳州老矣犹儿戏，瓜果为伊三请。\n云路回。\n漫说道、年年野鹊曾并影。\n无人与问。\n但浊酒相呼，疏帘自卷，微月照清饮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12703, '扬州慢', '姜夔', '淮左名都，竹西佳处，解鞍少驻初程。\n过春风十里，尽荠麦青青。\n自胡马窥江去後，废池乔木，犹厌言兵。\n渐黄昏，清角吹寒，都在空城。\n杜郎俊赏，算而今，重到须惊。\n纵豆蔻词工，青楼梦好，难赋深情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12704, '长亭怨慢', '姜夔', '渐吹尽、枝头香絮。\n是处人家，绿深门户。\n远浦萦回，暮帆零乱向何许。\n阅人多矣，谁得似、长亭树。\n树若有情时，不会得、青青如此。\n日暮。\n望高城不见，只见乱山无数。\n韦郎去也，怎忘得、玉环分付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12705, '淡黄柳', '姜夔', '空城晓月。\n吹入垂杨陌。\n马上单衣寒恻恻。\n看尽鹅黄嫩绿，都是江南旧相识。\n正岑寂。\n明朝又寒食。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12706, '石湖仙', '姜夔', '松江烟浦。\n是千古三高，游衍佳处。\n须信石湖仙，似鸱夷、翩然引去。\n浮云安在，我自爱、绿香红舞。\n容与。\n看世间、几度今古。\n卢沟旧曾驻马，为黄花、闲吟秀句。\n见说胡儿，也学纶巾雨。\n玉友金蕉，玉人金缕。\n缓移筝柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12707, '暗香', '姜夔', '旧时月色。\n算几番照我，梅边吹笛。\n唤起玉人，不管清寒与攀摘。\n何逊而今渐老，都忘却、春风词笔。\n但怪得、竹外疏花，香冷入瑶席。\n江国。\n正寂寂。\n叹寄与路遥，夜雪初积。\n翠尊易泣。\n红萼无言耿相忆。\n长记曾携手处，千树压、西湖寒碧。\n又片片、吹尽也，几时见得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12708, '疏影', '姜夔', '苔枝缀玉。\n有翠禽小小，枝上同宿。\n客里相逢，篱角黄昏，无言自倚修竹。\n昭君不惯胡沙远，但暗忆、江南江北。\n想佩环、月夜归来，化作此花幽独。\n犹记深宫旧事，那人正睡里，飞近蛾绿。\n莫似春风，不管盈盈，早与安排金屋。\n还教一片随波去，又却怨、玉龙哀曲。\n等恁时、重觅幽香，已入小窗横幅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12709, '惜红衣', '姜夔', '簟枕邀凉，琴书换日，睡馀无力。\n细洒冰泉，并刀破甘碧。\n墙头唤酒，谁问讯、城南诗客。\n岑寂。\n高柳晚蝉，说西风消息。\n虹粱水陌。\n鱼浪吹香，红衣半狼藉。\n维舟试望故国。\n眇天北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12710, '角招', '姜夔', '为春瘦。\n何堪更绕西湖，尽是垂柳。\n自看烟外岫。\n记得与君，湖上携手。\n君归未久。\n早乱落、香红千亩。\n一叶凌波缥缈，过三十六离宫，遣游人回首。\n犹有。\n画船障袖。\n青楼倚扇，相映人争秀。\n翠翘光欲溜。\n爱著宫黄，而今时候。\n伤春似旧。\n荡一点、春心如酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12711, '徵招', '姜夔', '潮回却过西陵浦，扁舟仅容居士。\n去得几何时，黍离离如此。\n客途今倦矣。\n漫赢得、一襟诗思。\n记忆江南，落帆沙际，此行还是。\n迤逦。\n剡中山，重相见、依依故人情味。\n似怨不来游，拥愁鬟十二。\n一丘聊复尔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12712, '秋宵吟', '姜夔', '古帘空，坠月皎。\n坐久西窗人悄。\n蛩吟苦，渐漏水丁丁，箭壶催晓。\n引凉、动翠葆。\n露脚斜飞云表。\n因嗟念，似去国情怀，暮帆烟草。\n带眼销磨，为近日、愁多顿老。\n卫娘何在，宋玉归来，两地暗萦绕。\n摇落江枫早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12713, '凄凉犯', '姜夔', '绿杨巷陌。\n秋风起、边城一片离索。\n马嘶渐远，人归甚处，戍楼吹角。\n情怀正恶。\n更衰草寒烟淡薄。\n似当时、将军部曲，迤逦度沙漠。\n追念西湖上，小舫携歌，晚花行乐。\n旧游在否，想如今、翠凋红落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12714, '翠楼吟', '姜夔', '月冷龙沙，尘轻虎落，今年汉初赐。\n新翻胡部曲，听毡幕、元戎歌吹。\n层楼高峙。\n看栏曲萦红，檐牙飞翠。\n人姝丽。\n粉香吹下，夜寒风细。\n此地。\n宜有词仙，拥素云黄鹤，与君游戏。\n玉梯凝望久，叹芳草、萋萋千里。\n天涯情味。\n仗酒清愁，花销英气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12715, '湘月・念奴娇', '姜夔', '五湖旧约，问经年底事，长负清景。\n暝入西山，渐唤我、一叶夷犹乘兴。\n倦网都收，归禽时度，月上汀州冷。\n中流容与，画桡不点清镜。\n谁解唤起湘灵，烟鬟雾鬓，理哀弦鸿阵。\n玉麈谈玄，叹坐客、多少风流名胜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12716, '小重山令・小重山', '姜夔', '寒食飞红满帝城。\n慈乌相对立，柳青青。\n玉阶端笏细陈情。\n天恩许，春尽可还京。\n鹊报倚门人。\n安舆扶上了，更亲擎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12717, '念奴娇', '姜夔', '昔游未远，记湘皋闻瑟，沣浦捐。\n因觅孤山林处士，来踏梅根残雪。\n獠女供花，伧儿行酒，卧看青门辙。\n一丘吾老，可怜情事空切。\n曾见海作桑田，仙人云表，笑汝真痴绝。\n说与依依王谢燕，应有凉风时节。\n越只青山，吴惟芳草，万古皆沈灭。\n绕枝三匝，白头歌尽明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12718, '卜算子', '姜夔', '江左咏梅人，梦绕青青路。\n因向凌风台下看，心事还将与。\n忆别庾郎时，又过林逋处。\n万古西湖寂寞春，惆怅谁能赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12719, '卜算子', '姜夔', '月上海云沈，鸥去吴波回。\n行过西泠有一枝，竹暗人家静。\n又见水沈亭，举目悲风景。\n花下铺毡把一杯，缓饮春风影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12720, '卜算子', '姜夔', '藓干石斜妨，玉蕊松低覆。\n日暮冥冥一见来，略比年时瘦。\n凉观酒初醒，竹阁吟才就。\n犹恨幽香作许悭，小迟春心透。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12721, '卜算子', '姜夔', '家在马城西，今赋梅屏雪。\n梅雪相兼不见花，月影玲珑彻。\n前度带愁看，一饷和愁折。\n若使逋仙及见之，定自成愁绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12722, '卜算子', '姜夔', '摘蕊暝禽飞，倚树悬冰落。\n下竺桥边浅立时，香已漂流却。\n空径晚烟平，古寺春寒恶。\n老子寻花第一番，常恐吴儿觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12723, '卜算子', '姜夔', '绿萼更横枝，多少梅花样。\n惆怅西村一坞春，开遍无人赏。\n细草藉金舆，岁岁长吟想。\n枝上么禽一两声，犹似宫娥唱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12724, '卜算子', '姜夔', '象笔带香题，龙笛吟春咽。\n杨柳娇痴未觉愁，花管人离别。\n路出古昌源，石瘦冰霜洁。\n折得青须碧藓花，持向人间说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12725, '卜算子', '姜夔', '御苑接湖波，松下春风细。\n云绿峨峨玉万枝，别有仙风味。\n长信昨来看，忆共东皇醉。\n此树婆娑一惘然，苔藓生春意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12726, '洞仙歌', '姜夔', '花中惯识，压架玲珑雪。\n乍见缃蕤间琅叶。\n恨春风将了，染额人归，留得个、袅袅垂香带月。\n鹅儿真似酒，我爱幽芳，远比酴又娇绝。\n自种古松根，待看黄龙，乱飞上、苍髯五鬣。\n更老仙、添与笔端春，敢唤起桃花，问谁优劣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12727, '蓦山溪', '姜夔', '青青官柳，飞过双双燕。\n楼上对春寒，卷珠帘、瞥然一见。\n如今春去，香絮乱因风，沾径草，惹墙花，一一教谁管。\n阳关去也，方表人肠断。\n几度拂行轩，念衣冠、尊前易散。\n翠眉织锦，红叶浪题诗。\n烟渡口，水亭边，长是心先乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12728, '永遇乐', '姜夔', '我与先生，夙期已久，人间无此。\n不学杨郎，南山种豆，十一徵微利。\n云霄直上，诸公衮衮，乃作道边苦李。\n五千言，老来受用，肯教造物儿戏。\n东冈记得，同来胥宇，岁月几时难计。\n柳老悲桓，松高对阮。\n未办为邻地。\n长干白下，青楼朱阁，往往梦中槐蚁。\n却不如、洼尊放满，老夫未醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12729, '虞美人', '姜夔', '阑干表立苍龙背。\n三面天翠。\n东游才上小蓬莱。\n不见此楼烟雨、未应回。\n而今指点来时路。\n却是冥处。\n老仙鹤驭几时归。\n未必山川城郭、是耶非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12730, '永遇乐', '姜夔', '云隔迷楼，苔封很石，人向何处。\n数骑秋烟，一篙寒汐，千古空来去。\n使君心在，苍绿嶂，苦被北门留住。\n有尊中酒差可饮，大旗尽绣熊虎。\n前身诸葛，来游此地，数语便酬三顾。\n楼外冥冥，江皋隐隐，认得征西路。\n中原生聚，神京耆老，南望长淮金鼓。\n问当时、依依种柳，至今在否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12731, '水调歌头', '姜夔', '日落爱山紫，沙涨省潮回。\n平生梦犹不到，一叶眇西来。\n欲讯桑田成海，人世了无知者，鱼鸟两相推。\n天外玉笙杳，子晋只空台。\n倚阑干，二三子，总仙才。\n尔歌远游章句，云气入吾杯。\n不问王郎五马，颇忆谢生双屐，处处长青苔。\n东望赤城近，吾兴亦悠哉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12732, '汉宫春', '姜夔', '云曰归欤。\n纵垂天曳曳，终反衡庐。\n扬州十年一梦，俯仰差殊。\n秦碑越殿，悔旧游、作计全疏。\n分付与、高怀老尹，管弦丝竹宁无。\n知公爱山入剡，若南寻李白，问讯何如。\n年年雁飞波上，愁亦关予。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12733, '汉宫春', '姜夔', '一顾倾吴。\n苎萝人不见，烟杳重湖。\n当时事如对弈，此亦天乎。\n大夫仙去，笑人间、千古须臾。\n有倦客、扁舟夜泛，犹疑水鸟相呼。\n秦山对楼自绿，怕越王故垒，时下樵苏。\n只今倚阑一笑，然则非欤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12734, '点绛唇', '姜夔', '祝寿筵开，画堂深映花如绣。\n瑞烟喷兽。\n帘幕香风透。\n一点台星，化作人间秀。\n韶音奏。\n两行红袖。\n齐劝长生酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12735, '越女镜心・法曲献仙音', '姜夔', '风竹吹香，水枫鸣绿，睡觉凉生金缕。\n镜底同心，枕前双玉，相看转伤幽素。\n傍绮阁、轻阴度。\n飞来鉴湖雨。\n近重午。\n燎银篝、暗薰溽暑。\n罗扇小、空写数行怨苦。\n纤手结芳兰，且休歌、九辩怀楚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12736, '月上海棠', '姜夔', '红妆艳色，照浣花溪影，绝代姝丽。\n弄轻风、摇荡满林罗绮。\n自然富贵天姿，都不比、等闲桃李。\n帘栊静悄，月上正贪春睡。\n长记初开日，逞妖丽、如与人面争媚。\n过韶光一瞬，便成流水。\n对此日叹浮华，惜芳菲、易成憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12737, '水调歌头', '汪莘', '听说古时月，皎洁胜今时。\n今人但见今月，也道似琉璃。\n君看少年眸子，那比婴儿神彩，投老又堪悲。\n明月不在盛，玉斧亦何为。\n约东坡，招太白，试寻思。\n凭谁斫却，里面桂影数千枝。\n忆在无怀天上，仍向有虞宫殿，看月到陈隋。\n别有一轮月，万古没成亏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12738, '乳燕飞・贺新郎', '汪莘', '去郢频回首。\n正横江、荪桡容与，兰旌悠久。\n怅望龙门都不见，似把长楸孤负。\n念往日、佳人为偶。\n独向芳洲相思处，采苹花、杜若空盈手。\n乘赤豹，谁来後。\n云中眼界穷高厚。\n览山川、冀州还在，陶唐何有。\n木叶纷纷秋风晚，缥缈潇湘左右。\n见帝子、冰魂厮守。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12739, '乳燕飞・贺新郎', '汪莘', '晓趁西湖约。\n到湖头，烟消日出，波生雨脚。\n日挈白鱼携碧酒，要与诗人共酌。\n把楼上、珠帘卷却。\n坐对荷花三万朵，念西邻、未嫁肌如削。\n待折与，不堪著。\n别来又见秋萧索。\n恨无由、将余风月，伴君云鹤。\n想见登山临水处，醉把茱萸礴。\n唱白雪、阳春新作。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12740, '浪淘沙', '汪莘', '天末起凉风。\n云气匆匆。\n如今何处有英雄。\n独佩一壶溪上去，秋水澄空。\n绝壁耸云中，倒挂青松。\n醉歌汉殿与秦宫。\n日现山西留不住，目送飞鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12741, '沁园春', '汪莘', '春至伤春，秋至悲秋，谁在华胥。\n叹谪仙才气，飞扬拔扈，渊明何事，慷慨欷。\n自我少年，如今晚境，行半人间真有馀。\n都休问，且一觞一咏，吾爱吾庐。\n南皋境界何如。\n舍明月清风谁与居。\n望蓬山路杳，万株翠桧，方壶门掩，四面红蕖。\n中有佳人，绰如姑射，一炷清香满太虚。\n尘寰外，被鸣鸾报客，飞鹤传书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12742, '满江红', '汪莘', '荆楚岁时，念自古、登临风俗。\n休更道、桓家车骑，谢家丝竹。\n不觉吹将头上帽，可来共采篱边菊。\n叹如今，重九有何人，相追逐。\n穷处士，枯如木。\n贤太守，温如玉。\n遣厨人馈酒，廪人馈粟。\n欲寄唐虞无限意，离骚都是相思曲。\n奈两三、寒蝶尚于飞，秋光促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12743, '满江红', '汪莘', '万古灰飞，算何用、黄金满屋。\n吾老矣，几番重九，几杯。\n此日登临多恨别，明年强健何由卜。\n且唤教、儿女逐人来，寻黄菊。\n苹已白，枫犹绿。\n鲈已晚，橙初熟。\n叹人间何事，稍如吾欲。\n五柳爱寻王母使，三闾好作湘妃曲。\n向飘风、冻雨返柴扉，骑黄犊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12744, '浣溪沙', '汪莘', '一曲清溪绕舍流。\n数间茅屋正宜秋。\n芙蓉灼灼出墙头。\n元亮气高还作令，少陵形瘦不封侯。\n村醪闲饮两三瓯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12745, '念奴娇', '汪莘', '龙山高会，忆当时宾主，风流云散。\n今日紫阳峰顶上，人望旌旗天半。\n万叠红蕖，千层黄菊，照耀成飞观。\n西风浩荡，碧天斜去双雁。\n遥想健笔淋漓，龙蛇落纸，妙句高张翰。\n笼日轻霞横数抹，绿水金波相间。\n目寄宣平，神追师道，归棹摇星汉。\n城中万户，烛光香雾交贯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12746, '蓦山溪', '汪莘', '金风玉露，洗出乾坤体。\n乘兴到前村，见一片、清溪无底。\n竹篱茅舍，鸡犬两三家，寻渔父，问湘灵，拄杖斜阳里。\n青春误我，白发今如此。\n幸自识方壶，有个人，神通游戏。\n涧边野鹤，岩上忽孤云，倾浊酒，对黄花，又似东篱子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12747, '生查子', '汪莘', '春来春色佳，秋至秋光好。\n无计奈春归，又看秋光老。\n去年飞雪时，病与梅花道。\n来岁雪飞时，为把金樽倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12748, '感皇恩', '汪莘', '年少好寻芳，早春时节。\n飞去飞来似蝴蝶。\n如今老大，懒趁五陵豪侠。\n梦中时听得，秦箫咽。\n割断人间，柳枝桃叶。\n海上书来恨离别。\n旧游还在，空锁烟霞万叠。\n举杯相忆处，青天月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12749, '忆秦娥', '汪莘', '村南北。\n夜来陡觉霜风急。\n霜风急。\n征途情绪，塞垣消息。\n佳人独倚琵琶泣。\n一江明月空相忆。\n空相忆。\n寒衣未絮，荻花狼籍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12750, '点绛唇', '汪莘', '数朵芙蕖，嫣然一笑凌清晓。\n谢家池沼。\n秋景偏宜少。\n气挟清霜，似把群花小。\n秋风袅。\n湘君来了。\n一曲烟波渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12751, '菩萨蛮', '汪莘', '问言何处秋光好。\n当年曾过长洲道。\n一望没遮拦。\n天宽水亦宽。\n也因轻霭扫。\n也傍斜晖讨。\n指点与君看。\n画他难不难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12752, '桃源忆故人', '汪莘', '人间只解春留住。\n不管秋归去。\n一阵西窗风雨。\n秋也归何处。\n柴扉半掩闲庭户。\n黄叶青苔无数。\n犹把小春分付。\n梅蕊前村路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12753, '浣溪沙', '汪莘', '青女催人两鬓霜。\n自白酒作重阳。\n方壶老子莫凄凉。\n天地两三胡蝶梦，古今多少菊花香。\n只将破帽送秋光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12754, '点绛唇', '汪莘', '晓角霜天，昼帘却是春天气。\n小园行处。\n双蝶相随至。\n恰向梅边，又向桃边觑。\n孜孜地。\n访兰寻蕙。\n谁会幽人意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12755, '汉宫春', '汪莘', '春色平分，甚偏他杨柳，分外风流。\n夭桃自适其适，一笑还休。\n可怜仙李，对东风、却少温柔。\n争奈得、海棠妆点，向人浑不知羞。\n谁觉韶华如梦，到酴开後，莺语供愁。\n天教姚黄晚出，贵与王侔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12756, '菩萨蛮', '汪莘', '渔翁家住寒潭上。\n晓霜晚日时相向。\n三尺白鱼长。\n一双摇玉光。\n前朝来献状。\n果慰携壶望。\n水月正商量。\n小桥梅欲香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12757, '小重山', '汪莘', '居士情怀爱小春。\n恰如重会面，旧时人。\n东君轻笑又轻颦。\n如道我，春去却伤心。\n青鸟下红巾。\n瑶池春信早，莫因循。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12758, '聒龙谣', '汪莘', '梦下瑶台，神飞阆苑，自叹尘寰久客。\n三入成周，望皇居帝宅。\n荡兰桨、伊阙波涛，曳玉杖、洛阳阡陌。\n独踌躇、武烈文谟，天垂晚，月生魄。\n故人少，别怀多，引壶觞自酌，谁怜衰白。\n群仙问我，尚低头方册。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12759, '水龙吟', '汪莘', '当年翦彩垂髫，超然便欲为仙去。\n世间俗状，人心狡计，不堪同住。\n每坐空山，独临古涧，神闲意寓。\n想瀛洲鸡犬，蓬莱猿鹤，应怅望，门前路。\n自昔侯王将相，几番成、落花飞絮。\n仰天醉眼，兴云妙手，年华迟暮。\n长揖烟尘，静朝日月，谁知幽素。\n正风清麟背，星垂海角，晓钟初寤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12760, '水调歌头', '汪莘', '寄语山阿子，何日出幽篁。\n兰衣蕙带，为我独立万寻冈。\n头上青天荡荡，足下白云霭霭，和气自悠扬。\n一阵东风至，灵雨过南塘。\n招山鬼，吊河伯，俟东皇。\n朱宫紫阙，何事宛在水中央。\n长望龙雷驾，凭仗箫钟交鼓，宾日出扶桑。\n我乃援北斗，子亦射天狼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12761, '水调歌头', '汪莘', '谁与玩芳草，公子未西归。\n天然脱去雕饰，秋水落芙蕖。\n发轫朝兮东壁，弭节夕兮西极，故国入踌躇。\n梦里不知路，南斗正扶疏。\n鸩不好，凤不利，忆三闾。\n算来何事，苦道岁晏孰华余。\n首拜东皇太乙，复次云君司命，高曳九霞裾。\n山鬼正含睇，慕我欲何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12762, '水调歌头', '汪莘', '尧舜去已远，稷契不重来。\n周流天上地下，我马亦悠哉。\n君向云中独立，知与何人相俟，孔盖逐风回。\n长忆目成处，却苦别离催。\n被明月，佩宝璐，冠崔嵬。\n可怜幼好奇服，年老在尘埃。\n天地与我同性，日月与我同命，何事有馀哀。\n故国空乔木，野鹿上高台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12763, '水调歌头', '汪莘', '孔孟化尘土，秦汉共丘墟。\n人间美恶如梦，试看几张书。\n还是天一地二，做出朝三暮四，堪笑又堪悲。\n谁忆陶元亮，春酒解饥劬。\n老将至，岁既晏，念春归。\n停云亲友南北，何以慰离居。\n半郭半村佳处，一竹一花生意，吾亦爱吾庐。\n时访前村酒，旋买小溪鱼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12764, '水调歌头', '汪莘', '志可洞金石，气可塞堪舆。\n问君所志安在，富贵胜人乎。\n看取首阳二子，叩住孟津匹马，天讨不枝梧。\n特立浮云外，大块可齐驱。\n铁可折，玉可碎，海可枯。\n不论穷达生死，直节贯殊途。\n立处孤峰万仞，袖里青蛇三尺，用舍付河图。\n汝阳阿上，濯汝洞庭河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12765, '水调歌头', '汪莘', '欲觅存心法，当自尽心求。\n此心尽处，豁地知性与天侔。\n行尽武陵溪路，忽见桃源洞口，渔子舍渔舟。\n输与逃秦侣，绝境几春秋。\n举全体，既尽得，要敛收。\n勿忘勿助之际，玄牝一丝头。\n君看天高地下，中有鸢飞鱼跃，妙用正周流。\n可与知者道，莫语俗人休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12766, '满江红', '汪莘', '唐宋诸公，谁道得、梅花亲切。\n到和靖、先生诗出，古人俱拙。\n写照乍分清浅水，传神初付黄昏月。\n尽後来、作者斗尖新，仍重叠。\n离不得，春和腊。\n少不得，烟和雪。\n更茅檐低亚，竹篱轻折。\n何事西邻春得入，还如东阁人伤别。\n总输他、树下作僧来，离言说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12767, '满江红', '汪莘', '洞府瑶池，多是见、桃红满地。\n君试问、江海清绝，因何抛弃。\n仙景常如二三月，此花不受春风醉。\n被贩儿、俚妇折来看，添憔悴。\n泛雪艇，摇冰。\n溪馆静，村扉闭。\n须祁寒彻骨，清香透鼻。\n孤竹赤松真我友，姚黄魏紫非吾契。\n笑方壶、日日绕南枝，犹多事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12768, '水调歌头', '汪莘', '草木自成岁，禽鸟已春声。\n仰观俯察，多少宇宙古今情。\n遐想炎黄以上，逮至汉唐而下，几个费经营。\n巢许有真意，无责自身轻。\n富与贵，贫与贱，死还生。\n方壶岁晚，深感梅蕊向人倾。\n造物元来无物，有物还应自造，人意几曾平。\n天际识归路，野鹤忽长鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12769, '沁园春', '汪莘', '三十六峰，三十六溪，长锁清秋。\n对孤峰绝顶，云烟竞秀，悬崖峭壁，瀑布争流。\n洞里桃花，仙家芝草，雪後春正取次游。\n亲曾见，是龙潭白画，海涌潮头。\n当年黄帝浮丘。\n有玉枕玉床还在不。\n向天都月夜，遥闻凤管，翠微霜晓，仰盼龙楼。\n砂穴长红，丹炉已冷，安得灵方闻早修。\n谁知此，问原头白鹿，水畔青牛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12770, '沁园春', '汪莘', '家在柳塘，榜挂方壶，图挂黄山。\n觉仙峰六六，满堂峭峻，仙溪六六，绕屋潺。\n行到水穷，坐看云起，只在吾庐寻丈间。\n非人世，但鹤飞深谷，猿啸高岩。\n如今老疾蹒跚。\n向画里嬉游卧里看。\n甚花开花落，悄无人见，山南山北，谁似余闲。\n住个庵儿，了些活计，月白风清人倚阑。\n山中友，类先秦气貌，後晋衣冠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12771, '行香子', '汪莘', '野店残冬。\n绿酒春浓。\n念如今、此意谁同。\n溪光不尽，山翠无穷。\n有几枝梅，几竿竹，几株松。\n篮舆乘兴，薄暮疏钟。\n望孤村、斜日匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12772, '行香子', '汪莘', '策杖溪边。\n倚杖峰前。\n望琼林、玉树森然。\n谁家残雪，何处孤烟。\n向一溪桥，一茅店，一渔船。\n别般天地，新样山川。\n唤家童、访鹤寻猿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12773, '水调歌头', '汪莘', '酿秫小春月，取酒雪花晨。\n漏壶插破浮蚁，涌起碧鳞鳞。\n谁觉东风密至，更带梅香潜入，瓮里净无尘。\n一见酒之面，便得酒之心。\n这番酒，□□□，未及宾。\n黄山图就，旧日境界喜重新。\n三十六峰云嶂，三十六溪烟水，三十六壶春。\n寄语黄山道，我是境中人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12774, '鹊桥仙', '汪莘', '柳塘居处，方壶道号，汪姓莘名耕字。\n欲将丹药点凡花，教都做、水仙无计。\n家中安石，村中居易，总是一场游戏。\n曲终金石满吾庐，争奈少、柳家风味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12775, '鹊桥仙', '汪莘', '傥来无定，浮生如寄，休说真非真是。\n道人半睡半醒时，全身在、碧霄宫里。\n风师四起，云君六合，茅舍有何准拟。\n待他雪阵打窗来，旋披起、半床纸被。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12776, '沁园春', '汪莘', '流水小桥，茅屋竹窗，纸帐蒲团。\n把坎宫闭了，虎龙吟啸，离宫锁定，日月回环。\n万点星飞，两轮电转，五色圆光天样宽。\n□奇处，渐冥冥杳杳，有个鸦翻。\n当时筑著机关。\n後常把空华戏弄看。\n更有些可笑，寐中清境，有些可怪，镜里清颜。\n太上留魂，老君炼魄，又被瞿昙都扫残。\n如何好，只单修见性，双练还丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12777, '杏花天', '汪莘', '残雪林塘春意浅。\n倚碧玉、阑干日晚。\n天涯五色明如翦。\n上有新蟾占断。\n从别後、水遥山远。\n倩说与、天台刘阮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12778, '杏花天', '汪莘', '美人家在江南住。\n每惆恨、江南日暮。\n白苹洲畔花无数。\n还忆潇湘风度。\n幸自是、断肠无处。\n怎强作、莺声燕语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12779, '减字木兰花', '汪莘', '诗家清绝。\n檐外森然苍玉节。\n学易无思。\n一笑窗前白玉妃。\n何人共说。\n山上青松松上雪。\n更有谁知。\n溪在门前月在溪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12780, '西江月', '汪莘', '红白虽分两色，清香总是梅花。\n早春风日野人家。\n相对伯夷柳下。\n爱影拈将灯取，惜香放下帘遮。\n长安如梦只堪嗟。\n乐此应须贤者。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12781, '西江月', '汪莘', '曾把江梅入室，门人不敬红梅。\n清香一点入灵台。\n傲雪家风犹在。\n状貌妇人孺子，性情烈士奇才。\n自开自落有谁来。\n与汝上林相待。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12782, '西江月', '汪莘', '天下老松有数，人间不记何年。\n海心岳顶寺门前。\n我欲收成一片。\n为向此公传语，却教老子随缘。\n龙盘虎踞负青天。\n岂若吾身亲见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12783, '卜算子', '汪莘', '夏则饮红泉，冬则餐红术。\n一片新春入手来，不费些儿力。\n春在水无痕，春在山无迹。\n李白桃红未吐时，好个春消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12784, '南乡子', '汪莘', '茅舍起疏烟。\n家在寒溪阿那边。\n修竹当篱梅当户，萧然。\n问是尧天是葛天。\n风雨入新年。\n惟恐春阴咽管弦。\n绿酒一樽歌一曲，人传。\n不属天仙属散仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12785, '好事近', '汪莘', '堂上挂黄山，辉映庭前春雪。\n记得山中雪境，恰一般清绝。\n须知天锡与方壶，比似镜湖别。\n好得镜湖狂客，伴方壶欢伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12786, '好事近', '汪莘', '挽我过溪桥，请与春风权摄。\n推出雪峰千丈，照碧溪春色。\n别来三度见梅花，今日共君说。\n只这溪山十里，剩几多风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12787, '生查子', '汪莘', '天上不知天，洞里休寻洞。\n洞府天宫在眼前，春日都浮动。\n我自觉来看，他在迷时梦。\n觉则人人总是仙，步步乘鸾凤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12788, '好事近', '汪莘', '风日未全春，又是春来风日。\n不出方壶门户，见东皇消息。\n此时春事苦无多，春意最端的。\n却被草牙引去，向柳梢收得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12789, '好事近', '汪莘', '春早不知春，春晚又还无味。\n一点日中星鸟，想尧民如醉。\n不寒不暖杏花天，花到半开处。\n正是太平风景，为人间留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12790, '好事近', '汪莘', '风雨打黄昏，啼杀满山杜宇。\n到得人间春去，问英雄何处。\n桃红李白竞春光，谁共残妆语。\n最是梨花一树，照谁家庭户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12791, '好事近', '汪莘', '阆苑梦回时，窗外数声啼鸟。\n觉我床前天气，便清明多少。\n诗人门户约花开，宿蝶误飞了。\n一段山青水绿，作洞庭春晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12792, '好事近', '汪莘', '夹岸隘桃花，花下苍苔如积。\n蓦地轻寒一阵，上桃花颜色。\n东邻西舍绝经过，新月是相识。\n白玉阑干斜倚，作蓬山春夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12793, '好事近', '汪莘', '天宇绿无云，迟日江山如绣。\n是日轻衫团扇，笑折花相授。\n南山之北北山南，星鸟尚依旧。\n谁在松风高卧，作嵩阳春画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12794, '好事近', '汪莘', '月落画桥西，花影柳阴相亚。\n把住常娥问道，是谁家亭榭。\n天边处士少微星，正在杏花下。\n斜卓参旗一片，作草堂春夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12795, '洞仙歌', '汪莘', '春王正月，雪阵联翩下。\n我有春风怎生卖。\n忽扫残夜雨，推出朝阳，天地里，玉烛一枝无价。\n早春虚过了，尚有二分，是处春光好收买。\n也不违天性，不远人情，杨柳陌、临水夭桃亭榭。\n身子外、只要自家人，共酒後羲皇，花前偏霸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12796, '乳燕飞・贺新郎', '汪莘', '策杖南山去。\n到南溪、谁家宅院，欺人先渡。\n羽扇徐麾童仆退，翠柳白沙西路。\n帝赐我、阆风玄圃。\n一片飞来红叶阔，细看来、上有双鸾句。\n应念我，尘中住。\n眼前儿女闲相语。\n怪人间、禁烟时节，安排樽俎。\n为道从来寒食好，且莫思量今古。\n共绿水、春风鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12797, '八声甘州', '汪莘', '惜馀春、蛱蝶引春来，杜鹃趣春归。\n算何如桃李，浑无言说，开落忘机。\n多谢黄鹂旧友，相逐落花飞。\n芳草连天远，愁杀斜晖。\n谁向西湖南畔，问亭台在否，花木应非。\n看孤山山下，惟说隐君庐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12798, '浣溪沙', '汪莘', '白日青天蘸水开。\n落花江上玉鞭回。\n东君擎出牡丹来。\n独占洛阳春气足，遂中天下作花魁。\n相知深处举离杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12799, '满庭芳', '汪莘', '云绕花屏，天横练带，画堂三月初三。\n斜风细雨，罗幕护轻寒。\n无数天香国色，枝枝带、洛浦嵩山。\n烧红烛，吞星□日，光射九霞冠。\n仙宫，深几许，黄莺问道，紫莺窥帘。\n似太真姊妹，半醒微酣。\n须信生来富贵，何曾在、草舍茅庵。\n皇州近，扁舟载去，春色冠东南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12800, '谒金门', '汪莘', '檐溜滴。\n都是春归消息。\n带雨牡丹无气力。\n黄鹂愁雨湿。\n争看洛阳春色。\n忘却连天草碧。\n南浦绿波双桨急。\n沙头人伫立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12801, '玉楼春', '汪莘', '一片江南春色晚。\n牡丹花谢莺声懒。\n问君离恨几多长，芳草连天犹觉短。\n昨夜溪头新溜满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12802, '江神子・江城子', '汪莘', '鹧鸪声里别江东。\n绿阴中。\n夕阳红。\n一点离愁，相对景重重。\n目断大罗天上客，朝玉帝，把芙蓉。\n紫阳山下偶相逢。\n醉金锺。\n跨苍龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12803, '满庭芳', '汪莘', '云梦南来，岷东会，楼前天水苍茫。\n黄州太守，万里作金汤。\n淮上烟尘初敛，仍安集、耕陇渔乡。\n须知道，纶巾羽扇，不独数周郎。\n生朝，遥想处，雪消赤壁，春动黄冈。\n有新翻杨柳，细抹丝簧。\n竹外一枝更好，应回首、清浅池塘。\n看看也，天边凤诏，归侍赭袍光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12804, '哨遍', '汪莘', '近腊景和，故山可过，足下听余述。\n便自往山中，憩精蓝，与僧饭讫。\n北涉灞川，明月华映郭，夜登华子冈头立。\n嗟辋水沦涟，与月上下，寒山远火蒙笼。\n听林外犬类豹声雄。\n更村落谁家鸣夜舂。\n疏钟相闻，独坐此时，多思往日。\n噫，记与君同。\n清流仄径玉琮。\n携手赋佳什。\n往来萝月松风。\n只待仲春天，春山可望，山中卉木垂萝密。\n见出水轻，点溪白鹭，青皋零露方湿。\n雉朝飞，麦陇鸣俦匹。\n念此去非遥莫相失。\n傥能从我敢相必。\n天机非子清者，此事非所急。\n是中有趣殊深，愿子无忽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12805, '满庭芳', '曹彦约', '老子今年，年登七十，阿婆年亦相当。\n几年辛苦，今日小风光。\n遇好景，何妨笑饮，依前是、未放心肠。\n人都道，明明了了，强似个儿郎。\n幸偿。\n婚嫁了，双雏蓝袖，拜舞称觞。\n女随夫上任，孙渐成行。\n惭愧十分圆满，无以报、办取炉香。\n频频祝，百年相守，老子更清强。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12806, '祝英台近', '张潞', '宝熏浓，云幄重，琼叶丽金蕊。\n黛绿蜂黄，秋态未憔悴。\n绣帘深院黄昏，著香无处，人欲睡、为花重起。\n月如水。\n别有天外楼台，玲珑异尘世。\n翠袖生寒，只欠素娥倚。\n何如倩取西风，吹将归去，为添在、广寒宫里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12807, '水调歌头', '崔与之', '万里云间戍，立马剑门关。\n乱山极目无际，直北是长安。\n人苦百年涂炭，鬼哭三边锋镝，天道久应还。\n手写留屯奏，炯炯寸心丹。\n对青灯，搔白发，漏声残。\n老来勋业未就，妨却一身闲。\n梅岭绿阴青子，蒲间清泉白石，怪我旧盟寒。\n烽火平安夜，归梦到家山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12808, '贺新郎', '崔与之', '雨过云容扫。\n使星明、德心高揭，福心旁照。\n槐屋犹喧梅正熟，最是清和景好。\n望金节、云间缥缈。\n和气如春清似水，漾恩波、沾渥天南道。\n晨鹊噪，有佳报。\n天家黄纸除书到。\n便归来、升华天下，安边养浩。\n好是六逢初度日，碧落笙歌会早。\n遍西郡、欢声多少。\n人道菊坡新酝美，把一觞、满酌歌难老。\n瓜样大，安期枣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12809, '念奴娇', '吴琚', '我来浮玉，似凭陵沧海，蹑金鳌背。\n又若骑鲸游汗漫，飞入八荒之外。\n钟鼓传声，楼台倒影，不类人间世。\n徘徊吟眺，恨无陶谢酬对。\n今古潮落潮生，问英雄多少，与江俱逝。\n直欲乘风归阆苑，疑是三生习气。\n未辨鱼蓑，先盟鸥鹭，奈卜邻无地。\n从今清夜，梦魂应绕空翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12810, '柳梢青', '吴琚', '彩仗鞭春。\n鹅毛飞管，斗柄回寅。\n拂面东风，虽然料峭，毕竟寒轻。\n戴花折柳心情。\n怎捱得、元宵放灯。\n不是今朝，有些残雪，先去踏青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12811, '浪淘沙', '吴琚', '云叶弄轻阴。\n屋角鸠鸣。\n青梅著子欲生仁。\n冷落江天寒食雨，花事关情。\n池馆昼盈盈。\n人醉寒轻。\n一川芳草只销凝。\n时有入帘新燕子，明日清明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12812, '浪淘沙', '吴琚', '岸柳可藏鸦。\n路转溪斜。\n忘机鸥鹭立汀沙。\n咫尺锺山迷望眼，一半云遮。\n临水整乌纱。\n两鬓苍华。\n故乡心事在天涯。\n几日不来春便老，开尽桃花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12813, '水龙吟', '吴琚', '紫皇高宴萧台，双成戏击琼包碎。\n何人为把，银河水翦，甲兵都洗。\n玉样乾坤，八荒同色，了无尘翳。\n喜冰销太液，暖融鹊，端门晓、班初退。\n圣主忧民深意。\n转鸿钧、满天和气。\n太平有象，三宫二圣，万年千岁。\n双玉杯深，五云楼迥，不妨频醉。\n细看来、不是飞花，片片是、丰年瑞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12814, '酹江月・念奴娇', '吴琚', '玉虹遥挂，望青山隐隐，一眉如抹。\n忽觉天风吹海立，好似春霆初发。\n白马凌空，琼鳌驾水，日夜朝天阙。\n飞龙舞凤，郁葱环拱吴越。\n此景天下应无，东南形胜，伟观真奇绝。\n好是吴儿飞彩帜，蹴起一江秋雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12815, '桂殿秋', '刘翰', '青帝子，碧莲宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12816, '桂殿秋', '刘翰', '双玉节，到神京。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12817, '蝶恋花', '刘翰', '团扇题诗春又晚。\n小梦惊残，碧草池塘满。\n一曲银钩帘半卷。\n绿窗睡足莺声软。\n瘦损衣围罗带减。\n前度风流，陡觉心情懒。\n谁品新腔拈翠管。\n画楼吹彻江南怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12818, '清平乐', '刘翰', '萋萋芳草。\n怨得王孙老。\n瘦损腰围罗带小。\n长是锦书来少。\n玉箫吹落梅花。\n晓寒犹透轻纱。\n惊起半屏幽梦，小窗淡月啼鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12819, '清平乐', '刘翰', '鸳鸯翡翠。\n小小池塘水。\n落絮游丝花满地。\n度日阑干独倚。\n金刀裁就春衫。\n起来初试轻寒。\n满把相思清恨，题诗欲寄江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12820, '好事近', '刘翰', '花底一声莺，花上半钩斜月。\n月落乌啼何处，点飞英如雪。\n东风吹尽去年愁，解放丁香结。\n惊动小亭红雨，舞双双金蝶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12821, '菩萨蛮', '刘翰', '去时满地花阴月。\n归来落尽梧桐叶。\n帘外小梅残。\n绿窗幽梦寒。\n明朝提玉勒。\n又作江南客。\n芳草遍长亭。\n东风吹恨生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12822, '谒金门', '赵', '天色晚。\n云外一筝斜雁。\n独凭阑干秋满眼。\n菊花寒尚浅。\n叶落香沟红泛。\n懒把新诗题怨。\n何处笛声三弄断。\n月迟帘未卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12823, '酹江月・念奴娇', '杜', '江山如此，是天开万古，东南王气。\n一自髯孙横短策，坐使英雄鹊起。\n玉树声消，金莲影散，多少伤心事。\n千年辽鹤，并疑城郭非是。\n当日万驷云屯，潮生潮落处，石头孤峙。\n人笑褚渊今齿冷，只有袁公不死。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12824, '摸鱼儿', '杜', '放扁舟、万山环处，平铺碧浪千顷。\n仙人怜我征尘久，借与梦游清枕。\n风乍静。\n望两岸群峰，倒浸玻璃影。\n楼台相映。\n更日薄烟轻，荷花似醉，飞鸟堕寒镜。\n中都内，罗绮千街万井。\n天教此地幽胜。\n仇池仙伯今何在，堤柳几眠还醒。\n君试问。\n□此意、只今更有何人领。\n功名未竟。\n待学取鸱夷，仍携西子，来动五湖兴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12825, '蓦山溪', '杜', '春风如客，可是繁华主。\n红紫未全开，早绿遍、江南千树。\n一番新火，多少倦游人，纤腰柳，不知愁，犹作风前舞。\n小阑干外，两两幽禽语。\n问我不归家，有佳人、天寒日暮。\n老来心事，唯只有春知，江头路，带春来，更带春归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12826, '贺新郎', '刘仙伦', '翠盖笼娇面。\n记当年、沈香亭北，醉中曾见。\n见了风流倾国艳，红紫纷纷过眼。\n算好处、何嫌春晚。\n谁把天香和晓露，倩东君、特地匀娇脸。\n千万朵，开时遍。\n隔花听取提壶劝。\n道此花过了，春归蝶愁莺怨。\n挽住东君须醉倒，花底不妨留恋。\n待唤取、笙歌一片。\n最爱就中红一朵，似状元、得意春风殿。\n还惹起，少年恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12827, '木兰花慢', '刘仙伦', '渐秋空向晚，被风雨、趱重阳。\n正木落疏林，海棠枝上，忽见红妆。\n料应妒他兰菊，任年年、独甚占秋光。\n故把春风娇面，向人逞艳呈芳。\n看来毕竟此花强。\n只是欠些香。\n诮一似当年，五陵公子，却厌膏梁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12828, '菩萨蛮', '刘仙伦', '东风去了秦楼畔。\n一川烟草无人管。\n芳树雨初晴。\n黄鹂三两声。\n海棠花已谢。\n春事无多也。\n只有牡丹时。\n知他归不归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12829, '贺新郎', '刘仙伦', '小队停钲鼓。\n向沙边、柳下维舟，庆公初度。\n平尽群蛮方易镇，此事多应有数。\n奈自古、功成人妒。\n君看乐羊中山役，任谤书、盈箧终无据。\n千载下，竞谁与。\n诗中带得西山雨。\n指天台、雁荡归欤，寿乡深处。\n缓急朝廷须公出，更作中流砥柱。\n笑痴呆、纷纷儿女。\n多少人间不平事，有皇天、老眼能区处。\n挥玉，听金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12830, '贺新郎', '刘仙伦', '重唤松江渡。\n叹垂虹亭下，销磨几番今古。\n依旧四桥风景在，为问坡仙甚处。\n但遗爱、沙边鸥鹭。\n天水相连苍茫外，更碧云、去尽山无数。\n潮正落，日还暮。\n十年到此长凝伫。\n恨无人、与共秋风，脍丝莼缕。\n小转朱弦弹九奏，拟致湘妃伴侣。\n俄皓月、飞来烟渚。\n恍若乘槎河汉上，怕客星、犯斗蛟龙怒。\n歌乃，过江去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12831, '贺新郎', '刘仙伦', '郑玉非娼女。\n叹尘缘未了，飘零被春留住。\n肠断胭脂坡下路。\n成甚心情意绪。\n生怕入、梨园歌舞。\n寂寞阳台云雨散，算人间、谁是吹箫侣。\n空买断，两眉聚。\n新来镜里惊如许。\n暗伤怀、莺老花残，几番春暮。\n事逐孤鸿都已往，月落千山杜宇。\n念修竹、天寒何处。\n不念琐窗并绣户，妾从前、命薄甘荆布。\n谁为作，解绦主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12832, '念奴娇', '刘仙伦', '东下，望西江千里，苍茫烟水。\n试问襄州何处是，雉堞连云天际。\n叔子残碑，卧龙陈迹，遗恨斜阳里。\n後来人物，如君瑰伟能几。\n其肯为我来耶，河阳下士，正自强人意。\n勿谓时平无事也，便以言兵为讳。\n眼底山河，楼头鼓角，都是英雄泪。\n功名机会，要须闲暇先备。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12833, '念奴娇', '刘仙伦', '吴山青处，恨长安路断，黄尘如雾。\n荆楚西来行堑远，北过淮严扈。\n九塞貔貅，三关虎豹，空作陪京固。\n天高难叫，若为得诉忠语。\n追念江左英雄，中兴事业，枉被奸臣误。\n不见翠华移跸处，枉负吾皇神武。\n击楫凭谁，问筹无计，何日宽忧顾。\n倚筇长叹，满怀清泪如雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12834, '念奴娇', '刘仙伦', '西风何事，为行人扫荡，烦襟如洗。\n垂涨蒸澜都卷尽，一片潇湘清。\n酒病惊秋，诗愁入鬓，对景人千里。\n楚宫故事，一时分付流水。\n江上买取扁舟，排云涌浪，直过金沙尾。\n归去江南丘壑处，不用来寻月姊。\n风露杯深，芙蓉裳冷，笑傲烟霞里。\n草庐如旧，卧龙知为谁起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12835, '满江红', '刘仙伦', '快阁东西，鸥边问、晚晴可喜。\n鸥解语、既盟之後，两翁曾倚。\n笛弄惯听黄鲁直，履声深识徐渊子。\n添我来、相对两忘机，真相似。\n也不种，闲桃李。\n也不玩，佳山水。\n有新诗字字，爱民而已。\n一片心闲秋水外，三年人在春风里。\n涨一篙、江水送归鸿，明朝是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12836, '满江红', '刘仙伦', '著意留春，留不住、春归难恋。\n最苦是、梅天烟雨，麦秋庭院。\n嫩竹阴浓莺出谷，柔桑采尽蚕成茧。\n奈沈腰、宽尽有谁知，难消遣。\n幽阁恨，双眉敛。\n香笺寄，飞鸿远。\n向风帘羞见，一双归燕。\n翠被闲将情做梦，青楼赚得恩成怨。\n对尊前、莫惜唤琼姬，持杯劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12837, '霜天晓角', '刘仙伦', '倚空绝壁。\n直下江千尺。\n天际两蛾凝黛，愁与恨、几时极。\n暮潮风正急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12838, '诉衷情', '刘仙伦', '征衣薄薄不禁风。\n长日雨丝中。\n又是一年春事，花信到梧桐。\n云漠漠，水溶溶。\n去匆匆。\n客怀今夜，家在江西，身在江东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12839, '江神子・江城子', '刘仙伦', '华堂深处出娉婷。\n语声轻。\n笑声清。\n燕语莺啼，一一付春情。\n恰似洛阳花正发，见花好，不知名。\n金瓯盛酒玉纤擎。\n满盈盈。\n劝深深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12840, '系裙腰', '刘仙伦', '山儿矗矗水儿清。\n船儿似叶儿轻。\n风儿更没人情。\n月儿明。\n厮合造、送行人。\n眼儿蔌蔌泪儿倾。\n灯儿更冷清清。\n遭逢著雁儿，又没前程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12841, '永遇乐', '刘仙伦', '青幄蔽林，白毡铺径，红雨迷楚。\n昼阁关愁，风帘卷恨，尽日萦情绪。\n阳台云去，文园人病，寂寞翠尊雕俎。\n惜韶容、匆匆易失，芳丛对眼如雾。\n巾欹润，衣宽凉渗，又觉渐回骄暑。\n解箨吹香，遗丸荐脆，小芰浮鸳浦。\n画栏如旧，依稀犹记，伫立一钩莲步。\n暗销魂，那堪又听，杜鹃更苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12842, '菩萨蛮', '刘仙伦', '吹箫人去行云杳。\n香篝翠被都闲了。\n叠损缕金衣。\n是他浑不知。\n冷烟寒食夜。\n淡月梨花下。\n犹自软心肠。\n为他烧夜香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12843, '江神子・江城子', '刘仙伦', '东风吹梦落巫山。\n整云鬟。\n却霜纨。\n雪貌冰肤，曾共控双鸾。\n吹罢玉箫香雾湿，残月坠，乱峰寒。\n解回首忆前欢。\n见无缘。\n恨无端。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12844, '蝶恋花', '刘仙伦', '小立东风谁共语。\n碧尽行云，依约兰皋暮。\n谁问离怀知几许。\n一溪流水和烟雨。\n媚荡杨花无著处。\n才伴春来，忙底随春去。\n只恐游蜂粘得住。\n斜阳芳草江头路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12845, '一翦梅', '刘仙伦', '唱到阳关第四声。\n香带轻分。\n罗带轻分。\n杏花时节雨纷纷。\n山绕孤村。\n水绕孤村。\n更没心情共酒尊。\n春衫香满，空有啼痕。\n一般离思两销魂。\n马上黄昏。\n楼上黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12846, '沁园春', '刘仙伦', '闻道参军，今日垂弧，胜如去年。\n正新颁蓝绶，天香芬馥，初开黄牒，御墨新鲜。\n鼻祖登科，已逾百载，衣钵于今喜再传。\n图南事，看抟风九万，击水三千。\n官曹小试民编。\n有奕世甘棠在道边。\n向樽前有兴，细斟清，琴中得趣，缓拂朱弦。\n东观酬书，西垣草制，此去掀胜好看鞭。\n应难老，信君家眉寿，自有山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12847, '好事近', '刘仙伦', '春事恰平分，南极夜来星瑞。\n闻道都曹初度，拥万红千翠。\n长才杰出应时须，一郡赖纲纪。\n看即诏还入觐，上鸳行班里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12848, '沁园春', '刘仙伦', '周易一书，更三圣人，深切著明。\n凡变通动静，有形有象，盈虚消息，时止时行。\n天相名卿，日探妙趣，往古来今无两心。\n褰帷暇，手韦编不置，聊以娱情。\n如今祝寿殷勤。\n请得以推评理致新。\n看九重有命，晋侯锡马，三公论道，鼎足承君。\n同厥震男，拔乎泰茹，玉笋班中联步什。\n贤奋建，定丰亨豫大，扬王庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12849, '喜迁莺', '刘仙伦', '祥云笼昼。\n正梅花弄粉，岁寒时候。\n长记今朝，瑶台仙子，降作人间明秀。\n四德生来全备，绿鬓年年依旧。\n更满目，儿妇儿孙，森罗前後。\n知否。\n笙歌奏。\n去岁芳筵，好事今年又。\n寿烛高烧，寿词齐唱，满劝长生酒。\n元自荣华富贵，况复康宁福寿。\n愿此去，等鹤算龟龄，天长地久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12850, '鹧鸪天', '刘仙伦', '帘幕祥风动玉钩。\n凤箫声彻瑞烟浮。\n萧郎玉女来相会，今日齐眉醉玉楼。\n同富贵、共风流。\n一封花诰一封侯。\n更须有子腰金斗，镜里双鸾到白头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12851, '满江红', '刘仙伦', '过了烧灯，杨柳外、无边春色。\n庆初度、香浮东阁，瑞呈南极。\n翰墨场中推老手，曾魁多士催敌。\n到而今、官薄在天台，神仙籍。\n和月倚，南坡石。\n滴露点，床头易。\n看白头红颊，目光摇碧。\n富贵康强仍有子，人生似此应难得。\n更摩挲、铜狄说当年，真消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12852, '好事近', '刘仙伦', '桃李绿阴浓，屈指中和三六。\n恰是仙翁初度，霭瑞烟芬馥。\n歌喉宛转绕华堂，总是长生曲。\n他日临清亭上，看儿孙朝服。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12853, '满江红', '刘仙伦', '凤历更端，才信宿、年华方好。\n深院宇、祥风飘荡，瑞烟缭绕。\n闻道君侯当诞日，欢声解压春寒峭。\n更九衢、烟火近元宵，闻嬉笑。\n人正在，蓬莱岛。\n烧绛蜡，斟清。\n听清歌艳曲，一声云杪。\n奠枕江淮无一事，留都宫殿千门晓。\n看赐环、千岁侍君王，人难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12854, '念奴娇', '刘仙伦', '一番春事，到芗林、更两日重三节。\n百品名花饶笑处，喜遇诞弥佳月。\n巢叶灵龟，舞琴野鹤，总是千年物。\n来为公寿，纶巾长映华发。\n平生圣处功夫，道□深味，胸次真冰雪。\n高蹈丘园还谢了，枚叟蒲轮朝谒。\n时上篮舆，相随孙子，庆满床簪笏。\n南丰道价，敬持一瓣香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12855, '满江红', '刘仙伦', '夜半天风，吹佩玉、列仙初度。\n又恰是、人间六月，叶方吐。\n黄纸除书惊乍到，青毡旧物欣重睹。\n拥皇华、玉节待清秋，江南去。\n招壮士，增王旅。\n漕廪粟，资淮浦。\n济江南嘉绩，久闻当宁。\n明弼堂前山满眼，来鸿庭後花无数。\n看召环、即到寿星边，朝明主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12856, '醉蓬莱', '刘仙伦', '昨长庚入梦，昴宿呈祥，岳神锺秀。\n降产英贤，信道由天佑。\n荚飞三，九秋将暮，遇称觞时候。\n香沈檀，曲调金缕，满斟春酒。\n试纪绛年，六身二首，甲子方延，才经八九。\n款醉蓬莱，寿与天长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12857, '满江红', '杜旃', '半落半开花有恨，一晴一雨春无力。\n……别缆解时风度紧，离觞尽处花飞急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12858, '浣溪沙', '韩彦古', '一缕金香永夜清。\n残编未掩古琴横。\n绣衾寒拥宝缺明。\n坐听竹风敲石磴，旋倾花水漱春酲。\n落梅和雨打帘声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12859, '水调歌头', '张祥', '为爱龙山胜，小队一登临。\n冯仙洞府安在，抉石试幽寻。\n商略生平事业，摆脱人间尘土，欲与斫丝苓。\n泉响似相答，未可启归心。\n中原地，禾黍茂，犬羊腥。\n君王梦想豪杰，有待扫妖氛。\n缚虎正须人手，跨鹤缓酬夙志，行矣勿因循。\n夜半遣雷雨，助我作秋成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12860, '柳梢青', '张履信', '雨歇桃繁，风微柳静，日淡湖湾。\n寒食清明，虽然过了，未觉春闲。\n行云掩映春山。\n真水墨、山阴道间。\n燕语侵愁，花飞撩恨，人在江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12861, '谒金门', '张履信', '春睡起。\n小阁明窗儿底。\n帘外雨声花积水。\n薄寒犹在里。\n欲起还慵未起。\n好是孤眠滋味。\n一曲广陵应忘记。\n起来调绿绮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12862, '婆罗门引', '赵昂', '暮霞照水，水边无数木芙蓉。\n晓来露湿轻红。\n十里锦丝步障，日转影重重。\n向楚天空迥，人立西风。\n夕阳道中。\n叹秋色、与愁浓。\n寂寞三千粉黛，临鉴妆慵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12863, '谒金门', '徐', '秋欲暮。\n路入乱山深处。\n扑面西风吹雾雨。\n驿亭欣暂驻。\n可惜国香风度。\n空谷寂寥谁顾。\n已作竹枝传楚女。\n客愁推不去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12864, '谒金门', '徐', '春欲半。\n重到寂寥山馆。\n修竹连山青不断。\n谁家门可款。\n红晕花梢未半。\n绿蘸柳芽犹短。\n金缕香消春不管。\n素蟾光又满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12865, '万年欢', '郭应祥', '佳气葱葱，望长安日下，鸾鹤翔舞。\n天佑皇家，当年挺生真主。\n令节标名瑞庆，曾未数、电枢虹渚。\n人都道，福若高宗，太平赛过仁祖。\n需云燕锡广宇。\n有霓旌绛节，西极金母。\n笑捧蟠桃，更酌九霞清醑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12866, '菩萨蛮', '郭应祥', '当年瑞雪多盈尺。\n今年仅有些儿白。\n天欲兆丰年。\n须教趁腊前。\n南枝初破萼。\n风味浑如昨。\n快与泻银瓶。\n寒醅醉易醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12867, '菩萨蛮', '郭应祥', '开禧三月初逢九。\n持杯来庆梅仙寿。\n警捕恰三年。\n四封人宴然。\n政成应不日。\n去作朝京客。\n阴德合长生。\n休看三住铭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12868, '菩萨蛮', '郭应祥', '雪销未久寒犹力。\n霜华特地催晴色。\n残腊尚馀旬。\n隔年先见春。\n独怜霜点鬓。\n羞戴银幡胜。\n百里却熙然。\n今年强去年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12869, '菩萨蛮', '郭应祥', '泉江三遇昌阳节。\n棹歌还向中流发。\n急桨更轻桡。\n看谁夺得标。\n明年归紫淦。\n尚忆舟同泛。\n应有旧双鬟。\n能讴菩萨蛮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12870, '菩萨蛮', '郭应祥', '转头又是清秋近。\n晚风淅淅凉犹嫩。\n多谢客携觞。\n空惭画饼章。\n中亭明月可。\n未要亲灯火。\n十阅望舒圆。\n归期在眼前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12871, '菩萨蛮', '郭应祥', '去年持酒为君寿。\n劝君更上悬车奏。\n通籍已金闺。\n腰银袍亦绯。\n壶中闲日月。\n自有长生诀。\n父子弟兄贤。\n一门行地仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12872, '菩萨蛮', '郭应祥', '诞辰迟似秋三日。\n草堂已有新凉入。\n鬓绿未全霜。\n欣然把一觞。\n吟松新纳禄。\n共享清闲福。\n两个老人星。\n君家难弟兄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12873, '菩萨蛮', '郭应祥', '牡丹已过酴谢。\n那堪风雨连朝夜。\n底事最堪悲。\n春归人未归。\n春宜留取住。\n人却推将去。\n早晚遂江滨。\n欢然夸尹新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12874, '菩萨蛮', '郭应祥', '秋堂积雨新凉入。\n今宵雅乘鹏飞集。\n劲翮会高风。\n功名唾中。\n笔头元有准。\n快写平生蕴。\n何日捷书来。\n重阳把一杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12875, '菩萨蛮', '郭应祥', '去年今日游稽古。\n斓斑曾著莱衣舞。\n四世共团栾。\n津然一笑欢。\n归期今不远。\n孥累俱先遣。\n犹有社中人。\n相从寂寞滨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12876, '菩萨蛮', '郭应祥', '修途六月清无暑。\n潘舆稳向盱南去。\n喜气已津津。\n平反一笑春。\n人言阴德报。\n罗纸重重诰。\n明岁早归来。\n泉江去催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12877, '菩萨蛮', '郭应祥', '涂黄仙子娇无力。\n秋花不敢争颜色。\n风物一番新。\n从今到小春。\n新词仍险韵。\n赓续惭非称。\n桃李寂无言。\n此花名独传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12878, '菩萨蛮', '郭应祥', '未观岩桂先观菊。\n世间底事真迟速。\n节物苦相催。\n重阳便到来。\n白衣何处觅。\n沽酒邀佳客。\n一笑有馀欢。\n官居终日闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12879, '菩萨蛮', '郭应祥', '佳辰昨日传筒黍。\n今朝重把离觞举。\n别驾奉安舆。\n前呵方塞途。\n庞眉真寿相。\n两处交迎养。\n庾岭到星沙。\n风光属一家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12880, '菩萨蛮', '郭应祥', '分宜七里逢重九。\n篱根无菊尊无酒。\n萧飒鬓如蓬。\n不禁吹帽风。\n插花开口笑。\n未分输年少。\n明岁定王台。\n传杯不放杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12881, '渔家傲', '郭应祥', '去岁簿书丛里过。\n生朝也有人来贺。\n随分侑尊呼几个。\n胡厮和。\n愁颜镇日何曾破。\n素发如今添老大。\n归来方是闲当坐。\n旋擘黄柑白堕。\n哩　罗。\n从他扰扰如旋磨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12882, '渔家傲', '郭应祥', '白古馀杭多俊俏。\n风流不独夸苏小。\n又见尊前人窈窕。\n花枝袅。\n贪看忘却朱颜老。\n曲巷横街深更杳。\n追欢买笑须年少。\n悔不从前相识早。\n心灰了。\n逢场落得掀髯笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12883, '传言玉女', '郭应祥', '稽古堂前，恰见四番端午。\n又来江上，听鸣鼍急鼓。\n棹歌才发，漠漠一川烟雨。\n轻舟摇扬，浪心掀舞。\n倦客今年续命，欠□彩缕。\n归期渐近，地萦心绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12884, '鹧鸪天', '郭应祥', '依约滩声杂橹声。\n波光隐映月华明。\n眼前好景真无尽，身外浮名尽可轻。\n穷胜赏，续欢盟。\n直饶风雨也须晴。\n满头插菊掀髯笑，笑道齐山浪得名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12885, '鹧鸪天', '郭应祥', '爱日迎长月向圆。\n当年飞堕蕊珠仙。\n相门赫奕人争羡，阃则柔嘉世所贤。\n罗纸贵，彩衣鲜。\n鼎来盛事乐无边。\n妇姑夫妇孙和子，同住人间五百年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12886, '鹧鸪天', '郭应祥', '谁道他乡异故乡。\n泉江风物似湄湘。\n钗头缀糁萸偏紫，杯面浮金菊倍黄。\n今共古，几重阳。\n休将往事更平章。\n舞衫歌扇姑随分，又得掀髯笑一场。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12887, '鹧鸪天', '郭应祥', '风雨潇潇旧满城。\n今年九日十分晴。\n且同北海邀佳客，共向东篱看落英。\n罗绮队，管弦声。\n银山高处好同登。\n催租岂解妨诗兴，自是潘郎名未成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12888, '鹧鸪天', '郭应祥', '鸾诰双双妇与姑。\n家尊荣宦到中都。\n暂时花县飞凫，新看芝庭捧鹤书。\n梅欲放，柳将舒。\n诞辰先占一阳初。\n清心堂下围红处，剩有长生酒满壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12889, '鹧鸪天', '郭应祥', '垂领纷纷已二毛。\n可堪州县尚徒劳。\n催科自笑阳城拙，勇退应惭靖节高。\n来祝寿，笑儿曹。\n说椿说柏说蟠桃。\n世间底事非前定，妙理还须问浊醪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12890, '鹧鸪天', '郭应祥', '休道泉江寂寞滨。\n喧喧歌吹遍城。\n莫辞邀赏连三日，且庆开禧第一春。\n呼小队，领嘉宾。\n王园佳处踏芳尘。\n星球不用随归骑，自有山头月逐人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12891, '鹧鸪天', '郭应祥', '人道今年秋较迟。\n木樨全未放些儿。\n不因诞节开千岁，争得今辰把一枝。\n呼宝鼎，伴渠伊。\n堂萱喜色正融怡。\n儿前妇後孙曾从，岁岁称觞无尽期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12892, '鹧鸪天', '郭应祥', '万里澄空没点云。\n素娥依旧驾冰轮。\n自缘人意看承别，未必清辉减一分。\n倾白堕，拥红裙。\n不知谁主复谁宾。\n更筹易促愁分袂，又作东西南北人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12893, '鹧鸪天', '郭应祥', '怪得欢声满十龙。\n诞辰和气敌严冬。\n安书莲幕欣频到，庆事花城喜屡逢。\n琼液泛，宝熏浓。\n华堂交口祝椿松。\n阿姑同健夫偕老，会有重重锦诰封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12894, '鹧鸪天', '郭应祥', '动地欢声遍十龙。\n元宵真赏与民同。\n春归莲焰参差里，人在蓬壶快乐中。\n乘皓月，逐和风。\n凉舆归去莫匆匆。\n班春休道无千炬，也有星球数点红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12895, '鹧鸪天', '郭应祥', '前数重阳後小春。\n中间十日是生辰。\n二年稳作栖鸾客，百里谁非贺燕人。\n无一事，扰天真。\n年登八八愈精神。\n句稽宜解淹贤辙，黄发犹须上要津。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12896, '鹧鸪天', '郭应祥', '点检尊前主与宾。\n今宵依旧昨宵人。\n自缘笑语生和气，不为风光属小春。\n香，酒清醇。\n山肴野蔌总前陈。\n掀髯抵掌君休怪，镜里星星白发新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12897, '鹧鸪天', '郭应祥', '贺了生辰却贺冬。\n今年乐事又重重。\n寿香喷处芝兰馥，寿洒斟时琥珀浓。\n偕桂隐，到花封。\n迎长介寿恰三逢。\n明年此日称觞罢，稳上肩舆九里松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12898, '鹧鸪天', '郭应祥', '诞节初开七帙祥。\n今秋仍喜十分凉。\n称觞堂下孙和息，备福人间寿且康。\n从庾岭，到章江。\n两州元自接封疆。\n儿曹此去分风月，莱彩潘舆乐未央。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12899, '鹧鸪天', '郭应祥', '瓶里梅花香正浓。\n阶前更著锦熏笼。\n且留幡胜明朝戴，共庆桑蓬此日逢。\n眉正绿，脸常红。\n後堂无日不春风。\n明年定又强今岁，会有明珠入掌中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12900, '鹧鸪天', '郭应祥', '令节标名自古闻。\n今宵银汉耿无云。\n难寻海上乘槎客，空诵河东乞巧文。\n罗异果，炷名熏。\n纫针拈线漫纷纷。\n蓬莱底事回车处，暗想当年钿合分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12901, '鹧鸪天', '郭应祥', '我离浏川七载强。\n去思那有召公棠。\n方怀旧友归鸿阁，忽枉高轩戏彩堂。\n频举白，剩添香。\n剧谈不觉引杯长。\n官居也有城门禁，未到三更尽不妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12902, '鹧鸪天', '郭应祥', '古遂长沙千里遥。\n三年三处做生朝。\n试拈疏蕊铜瓶插，更把轻沈宝鼎烧。\n杯绿泛，脸红潮。\n抱孙娱膝语声娇。\n官居只似私居样，管取寒松最後雕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12903, '鹧鸪天', '郭应祥', '方是闲堂寿宴开。\n今回生日胜前回。\n慈闱斑貌看看到，别驾除书鼎鼎来。\n纷彩服，滟金杯。\n缓歌慢舞不须催。\n明年此际称觞罢，醉向裴亭与定台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12904, '西江月', '郭应祥', '巧节已成昨梦，今宵重倒芳尊。\n主宾和气敌春温。\n雄辩高谈衮衮。\n剩把烛花高照，频教舞袖轻翻。\n笛声幽咽鼓声喧。\n却恨更筹苦短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12905, '西江月', '郭应祥', '锁棘方当拔士，挥毫正好文。\n词源三峡笔千军。\n尽出平生素蕴。\n天府伫登名姓，夜窗不负辛勤。\n直须平步上青云。\n始信文章有准。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12906, '西江月', '郭应祥', '十桂胜如五柳，九秋赛过三春。\n蓬蓬金粟吐奇芬。\n自有天然风韵。\n休羡一枝高折，尽教十里遥闻。\n尊前若有似花人。\n乞与些儿插鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12907, '西江月', '郭应祥', '赏月几成喜雨，开尊仍间围棋。\n令人却忆敬斋词。\n小饮不妨文字。\n底事冰轮未放，犹教银幕低垂。\n休言动是隔年期。\n闰八看看又至。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12908, '西江月', '郭应祥', '此老谁描拙状，今朝持献生辰。\n一人能变作三人。\n说与儿曹未信。\n坐者行者立者，化身报身法身。\n且须辨取假和真。\n肥瘦短长休问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12909, '西江月', '郭应祥', '明日恰当人日，今年远胜常年。\n瓣香卮酒寿蓝田。\n喜色津然满面。\n及戍人方竞进，悬车公独高骞。\n身闲便是地行仙。\n赢得千秋强健。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12910, '西江月', '郭应祥', '令节无过七夕，今年已隔三宵。\n奔驰五百里而遥。\n行止非人所料。\n月入尊楚楚，风生襟袖飘飘。\n不须抵死河桥。\n对月临风一笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12911, '西江月', '郭应祥', '妙句春云多态，丰姿秋水为神。\n慕潘应有捧心颦。\n谁是相看楚润。\n试问甜言软语，何如大醉高吟。\n杯行若怕十分深。\n人道对花不饮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12912, '西江月', '郭应祥', '洗眼重看十桂，转头已过三秋。\n人生遇坎与乘流。\n何况有花有酒。\n花若与人有意，酒能为我浇愁。\n拭金蕊泛金瓯。\n比似菊英胜否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12913, '西江月', '郭应祥', '碎影乱筛月地，浓香时度风檐。\n渊明有菊径开三。\n不似此花雅淡。\n兰蕙芬敷可并，芙蓉浅俗堪嫌。\n美人妆罢笑窥帘。\n插鬓些儿正欠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12914, '西江月', '郭应祥', '歌扇潜回暖吹，酒兵顿解寒围。\n红莲绛蜡两交辉。\n小醉何妨大醉。\n落笔君如王勃，属辞我愧周墀。\n明年应记盍簪时。\n耿耿怀人不寐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12915, '西江月', '郭应祥', '为爱脸边著晕，更怜肌里生香。\n此花端合占年芳。\n两朵那堪一样。\n自叹思归陶令，忽逢好事彭郎。\n朋来异卉与名章。\n击节何妨叹赏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12916, '西江月', '郭应祥', '不但酴芍药，此花亦殿馀春。\n麝囊初破酒初醺。\n恰有这般风韵。\n斓坼真成绝倒，半开犹带轻颦。\n不知抵死笑何人。\n待与折来细问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12917, '西江月', '郭应祥', '乐事无过新岁，生辰恰占元宵。\n湄湘台下有欢谣。\n令尹风流年少。\n暂借牛刀凫，宜参豹尾鸡翘。\n政成三异合归朝。\n试目天边紫诏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12918, '西江月', '郭应祥', '头上银幡初卸，堂前玉重飞。\n人言七十古来稀。\n七十如今已至。\n斑白元无一点，微黄已透双眉。\n一番庆寿十年期。\n更庆十番不啻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12919, '西江月', '郭应祥', '朔旦生朝同贺，寿觞社瓮齐倾。\n湄湘原是小东京。\n著个风流贰令。\n地胜岂如人胜，秋清争似官清。\n双瞳炯炯鬓青青。\n稳上华途捷径。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12920, '西江月', '郭应祥', '送我匆匆行色，赖君衮衮名章。\n德星今夜聚清湘。\n岂羡瀛洲方丈。\n宾醉须教主醉，更长不怕杯长。\n凤鸣端合在朝阳。\n飞诏来从天上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12921, '昭君怨', '郭应祥', '歌舞籍中第一。\n情致人间第一。\n年纪不多儿。\n尽娇痴。\n昨夜华严阁下。\n今夜海棠洞下。\n多少别离情。\n泪盈盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12922, '昭君怨', '郭应祥', '去岁银山塔上。\n今岁金山塔上。\n屈指到泉江。\n再重阳。\n有菊不妨同戴。\n有酒不妨同醉。\n嘉客与佳宾。\n两俱新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12923, '玉楼春', '郭应祥', '匆匆相遇匆匆去。\n恰似当年元未遇。\n生憎黄土岭头尘，强学章台街里絮。\n雨荒三径云迷路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12924, '玉楼春', '郭应祥', '贤僚益友俱亲密。\n真个三年如一日。\n清尊倒处笑喧哗，彩笔吟馀才俊逸。\n杯盘狼籍情真率。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12925, '鹊桥仙', '郭应祥', '金风淅淅，银河耿耿，七夕如今又至。\n人间唤作隔年期，但只似、屈伸指臂。\n罗花列果，拈针弄线，等是纷纷儿戏。\n巧人自少拙人多，那牛女、何曾管你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12926, '鹊桥仙', '郭应祥', '金飙乍歇，冰轮欲上，万里秋空如扫。\n一年十二度团圆，甚恰限、今宵最好。\n烹麟脍凤，幕天席地，争似杯盘草草。\n明年应更胜今年，但只恐、朱颜暗老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12927, '鹊桥仙', '郭应祥', '泥牛击罢，银幡卸了，又是一番春至。\n有人耳畔语低低，道宜入、新年吉利。\n堆盘红缕，浮杯绿蚁，自有及时风味。\n从今日日是东风，待拚了、偎红倚翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12928, '鹊桥仙', '郭应祥', '薄云笼月，轻飙却暑，天上人间佳节。\n银河自有鹊为桥，又那要、兰舟桂楫。\n後期可准，新欢如昨，选甚轻离易别。\n娥休要妒人呵，待更与、留连一霎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12929, '鹊桥仙', '郭应祥', '六人欢笑，六姬讴唱，六博时分胜负。\n六家盘馔斗芳鲜，恰两月、六番相聚。\n特排整整，华筵楚楚，终是不如草具。\n赏心乐事四时同，又管甚、落花飞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12930, '鹊桥仙', '郭应祥', '六丁文焰，六韬武略，那更六经心醉。\n六人相对座生风，继六逸、当年旧事。\n六州清唱，六么妙舞，执乐仍呼六妓。\n大家且饮六分觥，看宾主、迭居六位。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12931, '鹊桥仙', '郭应祥', '杯盘草草，园亭小小，不用罗帷锦幄。\n酴本是殿馀春，更风雨、无端趱却。\n有词可和，有棋可赌，杂以诙谐戏谑。\n闲时日日可遨嬉，又选甚，花开花落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12932, '鹊桥仙', '郭应祥', '去年七夕，今年五日，两见浴儿高会。\n乃翁种德已多年，看衮衮、公侯未艾。\n封胡羯末，综维缜绛，堪羡金鱼垂袋。\n丹砂白蜜不须涂，把续命、彩丝与带。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12933, '鹊桥仙', '郭应祥', '两情相向，一年厮睚，等得佳期又到。\n休言夜半悄无人，那喜鹊、也须知道。\n来今往古，吟诗度曲，总漫萦牵怀抱。\n不如乞取巧些些，待见了、分明祷告。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12934, '鹊桥仙', '郭应祥', '立春除夕，并为一日，此事今年创见。\n席间三世共团栾，随分有、笙歌满院。\n一名喜雪，二名饯岁，三则是名春宴。\n从教一岁大家添，但只要、明年强健。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12935, '鹊桥仙', '郭应祥', '今年七夕，新秋三日，已觉凉生院宇。\n吾乡风物胜他乡，那更著、莱衣起舞。\n泛槎经岁，分钗半夜，往事流传千古。\n独怜词客与诗人，费多少、闲言泼语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12936, '浣溪沙', '郭应祥', '仙子凌波袜有尘。\n翰林藻笔如神。\n此花此曲两无伦。\n不与妆台簪宝髻，却来书阁伴幽人。\n恨无佳客只空尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12937, '浣溪沙', '郭应祥', '屈指中秋一日期。\n雨馀云薄月来迟。\n冰轮犹自欠些儿。\n世事孰非颠倒相，客居东位主人西。\n觞行莫惜醉如泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12938, '浣溪沙', '郭应祥', '树底全无一点红。\n今年春事又成空。\n不须追恨雨和风。\n欲去未来多恶况，独眠无寐少欢。\n一声啼五更钟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12939, '浣溪沙', '郭应祥', '尊俎之间著二陈。\n津津眉宇笑生春。\n清歌妙舞两无伦。\n叔隗轻盈饶态度，小乔妩媚足精神。\n风流总属一家人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12940, '好事近', '郭应祥', '今日十分晴，好个重阳天气。\n又向银山高处，为黄花一醉。\n泉江风物饱相谙，瞥眼过三岁。\n但得明年强健，任举杯何地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12941, '好事近', '郭应祥', '今岁度元宵，随分点些灯火。\n不比旧家繁盛，有红莲千朵。\n客来草草办杯盘，杂蔬果。\n休羡暗尘随马，与银花铁锁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12942, '好事近', '郭应祥', '今岁庆生朝，迟似迎长十日。\n试向彩衣堂下，听欢声洋溢。\n小孙能笑长能歌，已自堪娱膝。\n管取婆犹未老，见满床堆笏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12943, '满江红', '郭应祥', '节物匆匆，又还见、浓春入眼。\n那更是、晓风初扇，宿云都卷。\n蝶舞已便花蕊乱，燕归仍惬香泥暖。\n又何须、女手学春工，并刀翦。\n欢乐事，郊遍。\n游赏处，轮蹄远。\n听谁家弦管，日开华宴。\n有客毫多丽句，惭予拆袜无长线。\n问新来、诗酒顿然疏，怎消遣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12944, '满江红', '郭应祥', '五十头颅，早已觉、飞腾景暮。\n愁眼看、蜂黄蝶粉，草烟花露。\n莫做阳台云雨梦，休怀渭北春天树。\n怅城、多少踏青人，红尘路。\n怀古恨，凭书诉。\n倾国貌，障羞妒。\n记山阴陈迹，群贤星聚。\n对景裁诗真漫与，看花不饮成虚负。\n问落红、千点总随流，归何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12945, '满江红', '郭应祥', '七帙华年，这强健、人谁得似。\n还又见、设弧令旦，秋风生桂。\n教子已成森砌玉，弄孙仍得追风骥。\n更後堂、深处著婵娟，笙歌沸。\n香篆，杯浮蚁。\n欢意洽，酡颜醉。\n有静中日月，闲中天地。\n不必亲扶灵寿杖，何须远挹浮丘袂。\n看蟠桃、著子又开花，三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12946, '念奴娇', '郭应祥', '琼苞玉屑，问天公、底事乱抛轻坠。\n城郭山川都一样，那得个般清气。\n谢女才情，如何只道，柳絮因风起。\n比梅差可，但无绿萼红蕊。\n坐上十客雄豪，颓然一老，草具相邀至。\n驱尽寒威凭酒力，买笑千金须费。\n谁办佳词，洛阳年少，笔下生新意。\n待添几盏，共君今夕同醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12947, '虞美人', '郭应祥', '二年浏水司征榷。\n小却平戎略。\n征衫指日去朝京。\n恰恰一江新渌、可扬。\n诗工画妙俱臻极。\n到处留真迹。\n一尊莫惜暂停桡。\n不待离歌唱彻、已魂销。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12948, '虞美人', '郭应祥', '梅桃末利东篱菊。\n著个瓶儿簇。\n寻常四物不同时。\n恰似西施二赵、太真妃。\n从来李郭多投分。\n伯仲俱清俊。\n苍颜独我已成翁。\n尚许掀髯一笑、对西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12949, '虞美人', '郭应祥', '周郎素蕴平戎略。\n聊此司征榷。\n他人两载已辞难。\n君独三年、只作一朝看。\n紫萸黄菊重阳後。\n木落秋容瘦。\n休斟别酒惨离裾。\n戚畹如今、个个有新除。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12950, '虞美人', '郭应祥', '天公有意留君住。\n故作纤纤雨。\n闭门觅句自持觞。\n并舍官梅、时有过来香。\n沈郎诗骨元来瘦。\n更挹湘江秀。\n不须骂雨与嘲风。\n收拾个般、都入锦囊中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12951, '醉落魄・一斛珠', '郭应祥', '琼楼玉宇。\n分明不受人间暑。\n寻常岂是无三五。\n惟有今宵，皓彩皆同普。\n素娥阅尽今和古。\n何妨小驻听吾语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12952, '采桑子', '郭应祥', '中秋过了还逢社，寿我亲闱。\n百里熙熙。\n尽道平反赖母慈。\n浏川水阔吾山峻，福禄如斯。\n禄鬓青眉。\n子又生孙孙又儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12953, '采桑子', '郭应祥', '饯筵绿绕红围处，只这孩儿。\n两泪垂垂。\n不忍叫人遽别离。\n别离不作多时计，千日为期。\n却恐归时。\n人道寻春已较迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12954, '朝中措', '郭应祥', '海棠零落花繁。\n春意已将阑。\n予告恰当寒食，邀宾同赏芳园。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12955, '卜算子', '郭应祥', '春事到清明，过了三之二。\n李夭桃委路尘，太半成泥滓。\n只有海棠花，恰似杨妃醉。\n折向铜壶把烛看，且莫教渠睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12956, '卜算子', '郭应祥', '谁把洛阳花，翦送河阳县。\n魏紫姚黄此地无，随分红深浅。\n小插向铜瓶，一段真堪羡。\n十二人簪十二枝，面面交相看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12957, '减字木兰花', '郭应祥', '仲春是七。\n门左垂弧当此日。\n点检春光。\n百草千葩已斗芳。\n折花持酒。\n彩袖殷勤来祝寿。\n明岁而今。\n稳向南宫待捷音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12958, '减字木兰花', '郭应祥', '偶然相聚。\n最是人间堪乐处。\n散步寻春。\n来作琴堂不速宾。\n缓歌一曲。\n野鹜纷纷都退缩。\n不用多杯。\n准拟花时日日来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12959, '减字木兰花', '郭应祥', '栖鸾高士。\n文采风流谁得似。\n年德虽高。\n对酒当歌气尚豪。\n明眸皓齿。\n一朵红莲初出水。\n膝上安排。\n爱惜须教不离怀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12960, '减字木兰花', '郭应祥', '遇如不遇。\n最是暂来还复去。\n归到乡关。\n欲再来时却恐难。\n丁宁去後。\n倩雁传书须访旧。\n万斛羁愁。\n逐水那容许大舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12961, '柳梢青', '郭应祥', '春事匆匆。\n花慵柳困，雨横风狂。\n寄语诗人，须烧银烛，与照红妆。\n休言桃李河阳。\n但过眼、难寻色香。\n只有今宵，更无明日，且缓飞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12962, '柳梢青', '郭应祥', '遁斋居士。\n今年今日，又添一岁。\n鬓雪心灰，十分老懒，十分憔悴。\n休言富贵长年，那个是、生涯活计。\n茗饮一瓯，纹楸一局，沈烟一穗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12963, '柳梢青', '郭应祥', '薄晚才晴。\n相邀移席，待月中庭。\n环坐斯须，屋山高处，忽吐微明。\n云收雨止风停。\n人世有、琼楼玉京。\n一任星移，从教斗转，且缓飞觥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12964, '柳梢青', '郭应祥', '合浦名邦。\n风流太守，紫绶金章。\n暂驻旌麾，来临祖席，一片潇湘。\n且须缓举离觞。\n细看取、眉间点黄。\n未到还珠，已闻赐玺，归近清光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12965, '柳梢青', '郭应祥', '两令邀宾。\n城南佳处，饯腊迎春。\n步入梅林，纷然缟袂，间似红英。\n遥岑寸碧增明。\n更酬唱、无惭昔人。\n一笑相欢，且斟佳醑，休羡莼羹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12966, '生查子', '郭应祥', '尊前主与宾，欠一还成九。\n休唱木犀词，预饮黄花酒。\n开怀今夕同，分手明朝又。\n不管岁年催，且把馨香嗅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12967, '生查子', '郭应祥', '银烛印红衫，薄暮新梳洗。\n一笑奉宾欢，未解东君意。\n回廊月转初，忆趁良宵会。\n喜事在明年，剧饮拼先醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12968, '点绛唇', '郭应祥', '九十韶光，闲忙晴雨常相半。\n赏春有愿。\n乘兴宁论晚。\n纵饮筠溪，日午花阴转。\n杯行缓。\n量悭嫌浅。\n须索斟教满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12969, '点绛唇', '郭应祥', '小队郊，耄倪争看铜章史。\n来宣德意。\n劝相遵彝制。\n夜雨连明，百谷应滋遂。\n真奇事。\n开禧元二。\n总是丰登岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12970, '点绛唇', '郭应祥', '五马归来，後车载得如花女。\n缓歌金缕。\n新样京华舞。\n主悦宾欢，一醉祛袢暑。\n停箫鼓。\n且须听取。\n三朵花能语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12971, '点绛唇', '郭应祥', '甲第初成，持杯酌酒来相庆。\n棣华辉映。\n相对开三径。\n小巧规模，百事都相称。\n年方盛。\n从容啸咏。\n不碍青云兴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12972, '江城子', '郭应祥', '开尊拟对菊花黄。\n舞伊凉。\n掺渔阳。\n更有风流，妓女胜徐娘。\n只道难逢开口笑，争驰逐，利名场。\n玉山蓝水两茫茫。\n采幽香。\n泛清觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12973, '临江仙', '郭应祥', '忆我归舟初系岸，君家盛事先知。\n後房深处第三姬。\n熊罴符吉兆，鹫产佳儿。\n衮衮庆源真未艾，谢兰还茁新枝。\n娇婴想见白和眉。\n他年贤子弟，今日小机宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12974, '临江仙', '郭应祥', '老子开年年五十，依前恁地痴顽。\n昨非今是有无间。\n惟惭新赤绂，不称旧苍颜。\n休羡长年并极富，休贪宝带腰环。\n人生难得是清闲。\n急须抛县印，归去隐家山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12975, '霜天晓角', '郭应祥', '琉璃十碗。\n兽炭红炉暖。\n花下两枝银烛，和气洽、欢声满。\n从他吹急管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12976, '踏莎行', '郭应祥', '鹗离风尘，燕辞门户。\n翩然举翮轻飞去。\n当初自恨探春迟，而今岂解留春住。\n花不重开，萍难再聚。\n垂杨只管牵离绪。\n直饶云雨梦阳台。\n梦回依旧无寻处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12977, '踏莎行', '郭应祥', '骤暖忽寒，送春迎夏。\n金沙过了酴谢。\n漏声款款日偏长，奇峰历历云如画。\n幸有杯觞，堪同保社。\n棋如飞雹睛空下。\n六人酬唱已成编，他年遂水留佳话。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12978, '踏莎行', '郭应祥', '露湿冠巾，风生襟袖。\n月华耿耿明好昼。\n主人情意十分浓，阮咸横膝清音奏。\n渐永更筹，新凉气候。\n穿针乞巧看看又。\n却怜相聚日无多，偷闲且可陪觞豆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12979, '踏莎行', '郭应祥', '明月清风，绿尊红袖。\n厌厌夜饮胜如昼。\n虽然文字有馀欢，也须闲把笙歌奏。\n十雨如期，三秋届候。\n去年丰稔今年又。\n东阡西陌稼如云，笑他齐量区兼豆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12980, '踏莎行', '郭应祥', '一撮精神，百般体态。\n兰心蕙性谁能赛。\n霎时不见早思量，许多日子如何捱。\n我已安排，你须宁耐。\n看看重了鸳鸯债。\n此生永愿不分飞，傍人一任胡怪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12981, '踏莎行', '郭应祥', '自昔中元，多生上相。\n麒麟今又来天上。\n云衢虽未掇勋名，月评先已腾声望。\n宝鼎浓熏，金翘绝唱。\n真珠百斛倾家酿。\n斯辰聊用祝龟龄，他年端合扶鸠杖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12982, '踏莎行', '郭应祥', '春已经旬，历方换岁。\n六花依旧来呈瑞。\n细思残腊与新年，一般清绝元非二。\n宿麦连云，遗蝗入地。\n坡仙有句谁能继。\n元宵此去日无多，会看霁色生和气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12983, '南歌子', '郭应祥', '生世逢端午，齐头五十番。\n一番须作一般看。\n又听竞船萧鼓、沸江干。\n不用丝缠臂，休将艾插门。\n及时蒲黍漫登盘。\n只恐岁华催促、鬓毛斑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12984, '南歌子', '郭应祥', '心下悬悬地，侬家好好儿。\n相怜相惜许多时。\n岂料一朝轻拆、便轻离。\n要见无由见，教归不肯归。\n数珠懒把镜慵窥。\n只有新添鬓雪、减腰围。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12985, '好事近', '郭应祥', '春事日相催，红尽浅桃深杏。\n可惜窥园无暇，任绿苔封径。\n凭谁说与雨和风，休要太狂横。\n等待禁烟予告，要选幽寻胜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12986, '卜算子', '郭应祥', '午夜一声雷，急雨如飞雹。\n枝上残红半点无，密叶都成幄。\n苦恨薄书尘，刚把闲身缚。\n却意湄湘春暮时，处处堪行乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12987, '卜算子', '郭应祥', '城上著裴亭，亭下临湘水。\n泼黛揉蓝画不成，暝色仍含紫。\n忙里不知春，却问今馀几。\n相与偷将半日闲，共把尘襟洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12988, '更漏子', '郭应祥', '月蟠根，天雨粟。\n宜贮阿娇金屋。\n心欲醉，眼偏明。\n无穷佳思生。\n焰银红，纷宝。\n倒著接花下。\n人已散，梦初回。\n渴心犹望梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12989, '谒金门', '郭应祥', '香篆袅。\n瓶里梅英犹小。\n鸳瓦霜华睛欲晓。\n今年生日好。\n鬓绿颜朱不老。\n女嫁儿婚将了。\n四世团栾同一笑。\n人间如此少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12990, '鹧鸪天', '郭应祥', '屈指新年五十三。\n未嫌垂领雪毵毵。\n设弧届旦人交贺，题座无功我自惭。\n荣莫羡，富休贪。\n寿龄也不慕彭聃。\n只思了却痴儿事，一榻香凝晓梦酣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12991, '秦楼月・忆秦娥', '郭应祥', '三月一。\n题舆恰届垂弧日。\n垂弧日。\n武安门外，欢声扬溢。\n双瞳炯炯头如漆。\n天公付与长生质。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12992, '卜算子', '郭应祥', '绿烛间红花，绝艳交相照。\n不分花时雨又风，折取供吟笑。\n拟把插乌巾，却恨非年少。\n点笔舒笺领略渠，座客词俱妙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12993, '临江仙', '郭应祥', '姑射仙人肌雪莹，笑他红紫纷纷。\n从教藏白後庭深。\n虬枝才破蕾，鼻观已遥闻。\n花正繁时春又暮，年华荏苒催人。\n惜花心事与谁论。\n长哦清绝句，目断古南云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12994, '浣溪沙', '李壁', '只记梅花破腊前。\n恼人春色又薰然。\n山头井似陆公泉。\n上客长谣追楚些，娇娃短舞看胡旋。\n崇桃积李自年年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12995, '朝中措', '李壁', '东风歌吹发重。\n飞旆入山新。\n小雨不妨酥润，江头一并霜晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12996, '小重山', '李壁', '燕雀风轻二月天。\n一枝何处是家园。\n有花不惜是谁怜。\n生嫌怕，不为老人妍。\n眉黛拥连娟。\n高情时载酒、雁湖边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12997, '满江红', '李壁', '帘卷东风，□林外、鸟啼姑恶。\n政迤逦、花梢红绽，柳梢黄著。\n散策丘园容懒□，折冲樽俎须雄略。\n但有书盈屋酒盈缸，还堪乐。\n嗟每被，浮云缚。\n黄梁梦，新来觉。\n悄祗愁湖海，故交辽邈。\n一纸素书来问我，数峰苍玉何如昨。\n更几时、夜雨落檐花，同春酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12998, '南歌子', '李壁', '紫绶新符竹，叶老兄弟。\n西风吹棹过湖亭。\n杨柳夫渠相伴、也多情。\n况是瀛洲侣，来同酒盏倾。\n白沤浑不避双旌。\n一种风流人似、玉壶清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (12999, '好事近', '李壁', '莫惜一樽留，共醉锦屏山色。\n多少飞花悠扬，送征轮南陌。\n曲湖归去未多时，还捧诏黄湿。\n生怕别来凄断，看满园行迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13000, '江神子・江城子', '李壁', '露荷香泛小池台。\n水云堆。\n好风催。\n宝扇胡床，无事且徘徊。\n帘外海榴裙一色，判共酹、两三杯。\n此怀能得几番开。\n玉山颓。\n不须推。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13001, '阮郎归', '李壁', '苏台一别费三年。\n锦书凭雁传。\n风姿重见阆江边。\n玉壶秋井泉。\n翻短舞，趁么弦。\n篆香同夕烟。\n多情莫惜为留连。\n落花中酒天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13002, '鹧鸪天', '李壁', '岸柳阴阴跃锦鳞。\n并湖莲子恰尝新。\n谁教故岁应官去，会老堂中少个人。\n归未久，意弥新。\n吹香不断酒倾银。\n行藏判已天公付，且斗而今见在身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13003, '西江月', '李壁', '又送鹏程轩翥，几看驹隙推移。\n多端时事只天知。\n不饮沈忧如醉。\n白首已甘蓬艾，苍生正倚丞疑。\n楚台风转一帆吹。\n朝列问君来未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13004, '临江仙', '韩', '难老一杯春酒美，主人玉监清秋。\n九华山下共追游。\n朝来多爽气，都向笔端收。\n台阁功名归去好，便应衮衮公侯。\n未妨含笑看吴钩。\n当年佳梦日，和气瑞光浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13005, '满江红', '韩', '五老峰前，九江上、曾生仙客。\n相邂逅、贵池亭下，定交金石。\n我辈风流宜啸咏，官曹尘冗从煎逼。\n且簿书、丛里举清觞，偷闲日。\n同一笑，当今夕。\n梅正好，香浮白。\n便相忘尔汝，醉巾沾湿。\n已向琼楼夸意态，似闻金殿传消息。\n想君今、归去际风云，应相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13006, '柳梢青', '韩', '云淡秋空。\n一江流水，烟雨。\n岸转溪回，野平山远，几点征鸿。\n行人独倚孤篷。\n算此景、如图画中。\n莫问功名，且寻诗酒，一棹西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13007, '醉蓬莱', '韩', '问西湖好处，楼上薰风，有谁称寿。\n十里荷香，对槐阴清昼。\n细浪揉蓝，远山凝黛，更管弦初奏。\n醉舞嗟嗟，欢声沸沸，生申时候。\n膝下婆娑，老莱儿戏，帝所辉光，使衣呈绣。\n眷倚方隆，赐金章华绶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13008, '水调歌头', '韩', '明月到花影，把酒对香红。\n此情飘洒，但觉清景满帘栊。\n人被好花相恼，花亦知人幽韵，佳处本同风。\n挥手谢尘网，举袂步蟾宫。\n秋已半，幽涧侧，乱山中。\n故人过我，终夕乘兴可千锺。\n赖有曲江才子，坐上平章花月，不管老英雄。\n心事将何寄，醉语又匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13009, '贺新郎', '韩', '万事佯休去。\n漫栖迟、灵山起雾，玉溪流渚。\n击楫凄凉千古意，怅怏衣冠南渡。\n泪暗洒、神州沈处。\n多少胸中经济略，气□□、郁郁愁金鼓。\n空自笑，听鸡舞。\n天关九虎寻无路。\n叹都把、生民膏血，尚交胡虏。\n吴蜀江山无自好，形势何能尽语。\n但目尽、东南风土。\n赤壁楼船应似旧，问子瑜、公瑾今安否。\n割舍了，对君举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13010, '贺新郎', '韩', '病起情怀恶。\n小帘栊、杨花坠絮，木阴成幄。\n试问春光今几许，都把年华忘却。\n更多少、从前盟约。\n拟待莺边寻好语，恍残红、零乱风回薄。\n思住事，信如昨。\n清明寒食须行乐。\n算人生、何时富贵，自徒萧索。\n试著春衫从酒伴，乱插繁英嫩萼。\n信莫被、功名担阁。\n随分溪山供笑傲，这一身、闲处谁能缚。\n琴剑外，尽杯酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13011, '清平乐', '韩', '鸣琴单父。\n凫宜飞去。\n不比河阳花满树。\n此意直高千古。\n清秋诞日相逢。\n乃同涧上村侬。\n笑指壶山为寿，仁心静处加功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13012, '水龙吟', '韩', '从来江左夷吾，大名迥诸出公右。\n金堂玉室，瑶林琼树，龙麟蟠走。\n志在神皋，气雄云梦，十吞八九。\n问三槐盛事，当年初度，人应羡、青毡旧。\n说与文章太守。\n庆千秋、好为亲寿。\n冰桃雪藕，霞裾月佩，莺鸾歌奏。\n雨熟西畴，星躔南极，宝香凝昼。\n趁新凉，便约乘云绕日，饮天浆酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13013, '清平乐', '韩', '萧然在涧。\n景色秋来冠。\n几缕明霞红未断。\n矫首时时遐观。\n回思五马清游。\n分明前辈风流。\n留作山间佳话，更谁愁上眉头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13014, '踏莎行', '韩', '雨意生凉，云容催暮。\n画楼人倚阑干处。\n柳边新月已微明，银潢隐隐疏星渡。\n今古佳期，漫传牛女。\n一杯试与寻新句。\n幽怀冷眼是青山，旧欢往恨浑无据。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13015, '清平乐', '韩', '常思高致。\n又见凉风起。\n欢喜年时为寿意。\n快写山歌重寄。\n愿公好德康宁。\n青云收取功名。\n莫道而今官小，吾儒正要仁民。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13016, '柳梢青', '韩', '雨洗元宵。\n楼台烟锁，隐隐笙箫。\n且插梅花，自烧银烛，沈水香飘。\n软红尘里星桥。\n想霁色、皇都绛霄。\n屏掩潇湘，醉和衣倒，春梦迢迢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13017, '菩萨蛮', '韩', '雪云收尽晴风软。\n小山春浪晴波远。\n梅片已飞香。\n海棠红试妆。\n人言诗易与。\n酒盏谁分付。\n不是没心情。\n夕阳啼鸟声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13018, '一翦梅', '韩', '说著相思梦亦愁。\n芳草斜阳，春满秦楼。\n楼前新绿水西流。\n一曲阳关，分付眉头。\n多少风流事已休。\n纷薄香浓，怕见绸缪。\n淡云笼月小庭幽。\n明日山长，清恨悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13019, '海月谣', '韩', '晚秋烟渚。\n更舟倚、萧萧雨。\n水痕清汜，迤逦渐整，云帆西去。\n三叠阳关，留下别离情绪。\n溪南一坞。\n对风月、谁为主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13020, '好事近', '韩', '春色入芳梢，点缀万枝红玉。\n莫道怕愁贪睡，倚新妆如束。\n纷纷桃李太妖娆，相对夜阑烛。\n记取疏花横处，有暗香飘馥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13021, '菩萨蛮', '韩', '平生常为梅花醉。\n数枝滴滴香沾袂。\n雪後月华明*胆瓶无限清。\n夜深灯影瘦。\n饮尽杯中酒。\n明日景尤新。\n人间都是春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13022, '西江月', '韩', '春色著人多少，溪头桃杏舒红。\n杖藜相与过桥东。\n往事旧欢如梦。\n花底醉眠芳草，柳边嘶入骄骢。\n如今憔悴坐诗穷。\n莫问醯鸡舞瓮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13023, '浣溪沙', '韩', '一曲青山映小池。\n林疏人静月明时。\n相逢杯酒也相宜。\n醉眼不知春事少，欢情犹得漏声迟。\n神仙何处梦魂飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13024, '浣溪沙', '韩', '宝鸭香消酒未醒。\n锦衾春暖梦初惊。\n鬓云撩乱玉钗横。\n半怯夜寒褰绣幌，尚馀娇困剔银灯。\n粉痕微褪脸霞生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13025, '西江月', '韩', '风暖晨光寂寂，月明夜气沈沈。\n山间林下步轻阴。\n花柳飞绵布锦。\n酒病向谁能遣，春愁惟我难禁。\n尊前一曲断肠声。\n梦破晓窗枕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13026, '朝中措', '韩', '池塘春草燕飞飞。\n人醉牡丹时。\n多少姚黄魏紫，搦成腻粉燕支。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13027, '水调歌头', '韩', '今古钓台下，行客系扁舟。\n扁舟何似，云山千叠亦东游。\n我欲停桡一醉，与写平生幽愤，横管更清讴。\n小上客星阁，短鬓独搔头。\n风乍起，烟未敛，雨初收。\n一年花事，数声欲春休。\n吊古怀贤情味，只有浮名如故，谁复识羊裘。\n赖得玄英隐，相望此溪流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13028, '西江月', '韩', '梅蕊小春天气，橘林良月风光。\n五云边近九霞觞。\n美景初无尽藏。\n老矣相逢湖海，年来游遍潇湘。\n诗情满眼兴何长。\n赢得烟霄直上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13029, '卜算子', '韩', '花底醉东风，好景宜同寿。\n海角天涯今几春，邂逅新丰酒。\n内集记高阳，南渡闲回首。\n但愿长年饱饭休，一笑风尘表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13030, '浣溪沙', '韩', '小雨收晴作社寒。\n月桥花院篆香残。\n杏腮桃脸黛眉弯。\n歌拂燕梁牵客恨，醉临鸾镜怕人看。\n良宵春梦绕屏山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13031, '菩萨蛮', '韩', '海棠欲谢绵飞柳。\n柳丝自拂行人首。\n上巳是清明。\n新烟带粥饧。\n轻阴帘幕冷。\n闲却秋千影。\n曲水兴无涯。\n丽人花半遮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13032, '浣溪沙', '韩', '湖海相逢更日边。\n槐风莲雨寿杯前。\n琴书图画水沈烟。\n共指金銮当直，不应彭泽尚回旋。\n今年初度想超然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13033, '恋绣衾', '韩', '欢浓两点笑靥儿。\n雪初消、梅欲放时。\n不信道、伤春瘦，怕人猜、犹待皱眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13034, '浣溪沙', '韩', '一曲霓裳舞未终。\n玉钗垂额鬓云松。\n梦回金殿月华东。\n燕子莺儿情脉脉，柳枝桃叶恨匆匆。\n罗襟空惹御香浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13035, '步蟾宫', '韩', '三年重到严滩路。\n叹须鬓、衣冠尘土。\n倚孤篷、闲自濯清风，见一片、飞鸿归去。\n人间何用论今古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13036, '水调歌头', '韩', '一枕暑风外，事事且随缘。\n随缘何处琴剑，闲泊此层巅。\n日绕九天楼殿，烟抹四山林薄，尘土市声前。\n老眼醉还醒，犹得到诗边。\n桥南院，双桂隐，有名言。\n江湖人物，好在收拾付书帘。\n回首吾庐无恙，寄卧僧窗何事，鸿鹄本高骞。\n水调赋明月，谁道更超然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13037, '鹧鸪天', '韩', '雨湿西风水面烟。\n一巾华发上溪船。\n帆迎山色来还去，橹破滩痕散复圆。\n寻浊酒，试吟篇。\n避人鸥鹭更翩翩。\n五更犹作钱塘梦，睡觉方知过眼前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13038, '水调歌头', '韩', '嘉节已吹帽，谁复见南山。\n南山佳处，台上云绕一溪环。\n犹记使君同醉，化鹤千年何在，今古自应悭。\n胜事漫陈迹，风物只高寒。\n都莫问，归酒畔，集毫端。\n等闲吟笑而已，赖有孔融尊。\n伟矣广平心致，赢得相遭淡泊，感旧唱酬闲。\n且看小斋菊，抵掌共凭阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13039, '减字木兰花', '韩', '年光虚度。\n能得几多消散处。\n莫恨归迟。\n得见新词不自持。\n山中酒里。\n笑语喧哗知有弟。\n此意谁如。\n世事纷纷一任渠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13040, '生查子', '韩', '霜叶柳塘风，烟蕊梅溪渡。\n茅店问村醪，未许空归去。\n倚杖小徘徊，写我吟边句。\n醉眼复何之，落日孤鸿处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13041, '西江月', '韩', '闻道晚春时候，暖风是处花飘。\n游人争渡水南桥。\n多少池塘春草。\n跃马谁联玉勒，钓鱼应泛兰桡。\n韶光何限不逍遥。\n输与溪鸥野鸟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13042, '朝中措', '韩', '春浓人静倦游嬉。\n烟雨战棠梨。\n翠径乱红无数，频啼枝上黄鹂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13043, '小重山', '韩', '云影收晴雨外明。\n碧溪春滟滟，落花平。\n莺声催我过桥行。\n人何在，诗酒淡心情。\n闲里兴还生。\n锦鳞题尺素，有谁能。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13044, '临江仙', '韩', '脆管繁弦无觅处，小楼空掩遥山。\n柳丝直下曲阑干。\n海棠红欲褪，玉钏怯春衫。\n酒不成芳信断，社寒新燕呢喃。\n雕盘慵整宝香残。\n绮疏明薄暮，帘外雨潺潺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13045, '朝中措', '韩', '五湖烟水百花洲。\n别乘最风流。\n人道紫枢家世，清时衮衮公侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13046, '月宫春', '韩', '柳娇花妒燕莺喧。\n断肠空眼穿。\n一春风雨夜厌厌。\n不闻钟鼓传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13047, '浣溪沙', '韩', '芍药酴满院春。\n门前杨柳媚晴曛。\n重帘双燕语沈沈。\n花映绿娇初日嫩，叶栖红小晚烟昏。\n轻雷不觉送微阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13048, '鹧鸪天', '韩', '烟禁荒荒雨湿云。\n近郊争出满城人。\n儿童藉草几成市，杯酒沾花不觉村。\n身又老，眼增明。\n回头一任是红尘。\n山中谁信无寒食，涧上何如且采苹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13049, '一丛花', '韩', '翻空雪浪送飞花。\n春晓媚霜华。\n风回点点迷人处，峭寒轻、诗思殊佳。\n双燕未来，断鸿何在，微雨又天涯。\n绮窗明暗是谁家。\n雕槛馥兰芽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13050, '眼儿媚', '韩', '东风拂槛露犹寒。\n花重湿阑干。\n淡云日，晨光微透，帘幕香残。\n阴晴不定瑶阶润，新恨觉心阑。\n凭高望断，绿杨南陌，无限关山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13051, '青玉案', '韩', '苏公堤上西湖路。\n柳外跃、青骢去。\n多少韶华惊暗度。\n南山游遍，北山归後，总是题诗处。\n如今老矣伤春暮。\n泽畔行吟漫寻句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13052, '浣溪沙', '韩', '只恐山灵俗驾回。\n海鸥飞下莫惊猜。\n机心消尽重徘徊。\n宿雨乍晴千涧落，晓云微露两山排。\n新苗时翼好风来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13053, '朝中措', '韩', '扁舟撑月转江湖。\n烟水湛金铺。\n篷底晓凉歌罢，肌肤冰雪初扶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13054, '明月棹孤舟・夜行船', '韩', '忽得相逢惊似旧。\n问山中、酒徒诗友。\n闲倚睛楼，长安市上，华发为君搔首。\n绿竹疏梅今在否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13055, '江城子', '韩', '天孙应为织云裳。\n试宫妆。\n问刘郎。\n湖上波寒，依旧远山苍。\n自是老来心事懒，空落拓，少年场。\n挥豪闲与细端相。\n记严扬。\n陋苏张。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13056, '冉冉云', '韩', '倚遍阑干弄花雨。\n卷珠帘、草迷芳树。\n山崦里、几许云烟来去。\n画不就、人家院宇。\n社寒梁燕呢喃舞。\n小桃红、海棠初吐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13057, '谒金门', '韩', '花影半。\n晴色乍开云卷。\n择胜寻春愁日短。\n雨馀山路晚。\n涧底桃深红满。\n人意不禁闲远。\n胡蝶绕枝啼鸟怨。\n东风吹酒面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13058, '满庭芳', '韩', '点点淮山，迢迢江水，分明别是风光。\n地灵人杰，星斗烂文章。\n初度充闾佳气，当年瑞、应弄璋。\n薰弦奏，凉宵宝月，玉井藕花香。\n清真，如逸少，兰亭修竹，曲水流觞。\n想醉乡日永，地久天长。\n小驻屏星怀玉，飞凫、元在行。\n功名事，云龙风虎，行矣佩金章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13059, '浣溪沙', '韩', '一曲西风醉木犀。\n天香吹梦入瑶池。\n钗横犹记未开枝。\n花重嫩舒红笑脸，叶稀轻拂翠颦眉。\n酒醒残月雁声迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13060, '浣溪沙', '韩', '山气吹云宝月凉。\n园英承露菊花黄。\n吾生只合醉为乡。\n怅望佳人因共赋，分明佳节是重阳。\n酒边犹发少年狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13061, '浣溪沙', '韩', '莫问星星鬓染霜。\n一杯同看月昏黄。\n放歌渔父濯沧浪。\n却忆手栽双柳句，真成云汉抉天章。\n苏仙何在立苍茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13062, '浣溪沙', '韩', '霜後黄花尚自开。\n老年情绪为何哉。\n株株浑是手亲栽。\n秋际有言挥玉尘，冬来无梦绕金钗。\n相思一夜发窗梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13063, '江城子', '韩', '雪消霜入小溪舟。\n试浮游。\n上山头。\n薄薄寒烟，依旧未全收。\n问道梅花开也未，吟不尽，一春愁。\n襟怀如此老还休。\n懒凝眸。\n转深幽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13064, '浣溪沙', '韩', '月角珠庭映伏犀。\n扶摇当上凤凰池。\n广寒曾折最高枝。\n壮志还同诸葛膝，清名还似紫芝眉。\n梅花春寿酒行迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13065, '鹧鸪天', '韩', '老去情怀酒味中。\n水边林下古人风。\n岁云暮矣江空晚，谁识儋州秃鬓翁。\n人易远，语难工。\n春时犹记一尊同。\n苦心未免皆如此，只合挥弦目送鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13066, '风入松', '韩', '小楼春映远山横。\n绿遍高城。\n望中一片斜阳静，更萋萋、芳草还生。\n疏雨冷烟寒食，落花飞絮清明。\n数声弦管忍重听。\n犹带微酲。\n问春何事春将老，春不语、春恨难平。\n莫把风流时节，都归闲淡心情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13067, '菩萨蛮', '韩', '小园红入春无际。\n新声休写花间意。\n一笑唤真真。\n香腮酒未醒。\n惜芳追胜事。\n畅饮馀诗思。\n无处说衷情。\n暗尘罗帐生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13068, '谒金门', '韩', '花肃肃。\n杨柳三眠未足。\n一棹溪山新涨绿。\n旧欢无梦续。\n莫问杜鹃啼蜀。\n只有江南水竹。\n北客凄凉无伴独。\n春山生草木。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13069, '谒金门', '韩', '幽意熟。\n吟啸春风自足。\n爽气初生晴未燠。\n相逢休问卜。\n画出高山盘谷。\n岩上飞云相逐。\n他日江东思渭北。\n断舷谁为续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13070, '卜算子', '韩', '一雨已秋深，月色寒而静。\n夜半披衣草树间，玉露团清影。\n长笛倚楼声，听彻还重省。\n手启柴门倦复关，云卧衣裳冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13071, '醉蓬莱', '韩', '庆文章太守，燕寝凝香，诞弥佳节。\n庾岭归来，又经年梅发。\n棋酒心情，笙歌滋味，便合朝天阙。\n玉作山前，冰为水际，几多风月。\n绿鬓朱颜，浩然相对，自是中原，旧家人物。\n鹭班回，尚记陪清切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13072, '朝中措', '韩', '为兹春酒寿诗翁。\n我辈一尊同。\n香动梅梢圆月，年年先得东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13073, '太常引', '韩', '小春时候腊前梅。\n还知道、为谁开。\n应绕百千回。\n夜色转、参横斗魁。\n十分孤静，替伊愁绝，片月共徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13074, '朝中措', '韩', '谁翻新曲玉溪滨。\n何日得为邻。\n醉里行歌相答，步随泉石松云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13075, '恋绣衾', '韩', '溪风吹雨晚打窗。\n把心情、阑入醉乡。\n记取在、山深处，我如今、双鬓已苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13076, '一翦梅', '韩', '一朵梅花百和香。\n浅色春风，别样宫妆。\n西湖衣钵更难忘。\n雪意江天，浑断人肠。\n清夜横斜竹影窗。\n赢得相思，魂梦悠扬。\n玉溪山外水云乡。\n茅舍疏篱，不换金章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13077, '蝶恋花', '韩', '道上疏梅花一树。\n人去人来，不管流年度。\n闲过南同散步。\n东风为我吹香去。\n试问青春今几许。\n明日新正，溪影横山暮。\n遮莫攀翻君且住。\n心儿却在题诗处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13078, '蝶恋花', '韩', '尽道今年春较早。\n梅与人情，觉得梅偏好。\n一树南香未老。\n春风已自生芳草。\n来自城中犹带晓。\n行到君家，细雨吹池沼。\n怅望沙坑须会到。\n玉溪此意年时少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13079, '生查子', '韩', '山意入春晴，都是梅和柳。\n白白与青青，日映风前酒。\n归去也如何，路上休回首。\n各自做新年，柳袅梅枝瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13080, '探春令', '韩', '暗尘明月小桃枝，旧家时情味。\n问而今、风转蛾儿底。\n有谁把、春衫试。\n景龙灯火升平世。\n动长安歌吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13081, '临江仙', '韩', '罗帐画屏新梦悄，绿窗慵起香残。\n重帘生怕倚阑干。\n春风吹玉水，春雪满灵山。\n梁燕未来归雁动，海棠才带红酣。\n酒愁花恨霎时间。\n烟云催薄暮，丝雨湿轻寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13082, '眼儿媚', '韩', '风回香雪到梨花。\n山影是谁家。\n小窗未晚，重檐初霁，玉倚蒹葭。\n社寒不管人如此，依旧在天涯。\n碧云暮合，芳心撩乱，醉眼横斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13083, '临江仙', '韩', '竹树阴阴流涧水，黄鹂飞去飞还。\n蓬门篱落小桥湾。\n更无尘迹到，我自爱其闲。\n雨又随风催薄暮，轻雷时动云斑。\n归来凉意一窗间。\n病馀真倦矣，睡熟簟纹宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13084, '蝶恋花', '韩', '斜日清霜山薄暮。\n行到桥东，林竹疑无路。\n小院横窗香雾。\n胆屏曲几花如雨。\n细酌心情因少驻。\n九万刚风，寒影吹琼素。\n不是月宫那有许。\n霓裳舞彻凌波步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13085, '柳梢青', '韩', '玉水明沙。\n峰回路转，城倚桥斜。\n老我登临，同谁酩酊，一望还赊。\n飞鸿杳霭天涯。\n但拚取、心情酒家。\n紫菊枝枝，红茱颗颗，休问年华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13086, '满庭芳', '韩', '玉水灵山，霜天清晓，非烟非雾琴堂。\n载临初度，圭璧记煌煌。\n百里民安抚字，欢呼处、禾黍登场。\n今年好，为兹春酒，莫惜醉淋浪。\n神仙，□领袖，山河勋业，星斗文章。\n便黄扉青琐，会遇明良。\n愿赐尚方之剑，攀槛折、於古辉光。\n飞凫去，甘棠遗爱，留与话桐乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13087, '菩萨蛮', '韩', '风前觅得梅花句。\n香来自是相分付。\n片月动黄昏。\n一枝横酒尊。\n人间何处有。\n又到春时候。\n莫负此诗家。\n将心吟好花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13088, '贺新郎', '韩', '梅蕊依稀矣。\n岁华深、け然但把，杖藜闲倚。\n山绕荒林红叶下，落日孤城烟水。\n意兴寄、云何则是。\n底事疏枝横绝峭，未吹香、便与花相似。\n不忍折，为之喜。\n寒鸦万点霜风起。\n正人家、园收芋栗，小槽初美。\n欲醉阿谁同一饮，拟赋才成又止。\n老态度、浑侵发齿。\n摸索孤根春在否。\n任红红、白白皆桃李。\n空烂漫，岂能尔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13089, '百字令・念奴娇', '韩', '诏飞天上，看金狨系马，西湖风月。\n朝罢香烟携满袖，身在琼楼玉阙。\n锦绣肝肠，珠玑唾，绿鬓非华发。\n与谁经济，河山应笑吴越。\n且把春酒寻梅，年年眉寿，坐对南枝发。\n兵卫朱门生画戟，醉舞尘生罗袜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13090, '菩萨蛮', '韩', '陇头无驿奚为朵。\n岩前有折宜来堕。\n风急雪云溪。\n诗清满意携。\n竹炉良夜饮。\n饮竟煎僧茗。\n梅以句深长。\n得花情未忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13091, '小重山', '韩', '点染烟浓柳色新。\n小桃红映水，日初匀。\n露收芳径草铺茵。\n凝情久，风淡起轻尘。\n梁燕已争春。\n折花闲伴酒，试濡唇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13092, '感皇恩', '韩', '急管度青枝，醉眠芳草。\n云断巫阳梦能到。\n乍醒馀困，晴影暗移纱帽。\n旧时闲意思，都忘了。\n今岁春迟，去年春早。\n点点繁红又多少。\n惜春归去，酒病翻成花恼。\n数声鸣鸟唤，人惊老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13093, '感皇恩', '韩', '诗社酒徒闲，村村花柳。\n月榭风亭更霞牖。\n临春结绮，又是那回时候。\n不禁中夜雨，相孱愁。\n弄蕊攀条，为寻芳酒。\n一斗谁能问千首。\n江南云梦，空说气吞八九。\n持杯人共我，能吟否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13094, '瑞鹧鸪', '韩', '南兰陵郡鹧鸪词。\n底用登临更赋诗。\n贵不能淫非一日，老当益壮未多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13095, '浣溪沙', '韩', '屋上青山列晚云。\n水边红袂映斜曛。\n柳阴荷气簟湘纹。\n酒以歌长谁乐事，诗成杯滟我离群。\n香消凉意有南薰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13096, '浣溪沙', '韩', '作意如何和好歌。\n细翻重看得长哦。\n晓梧吹雨露明荷。\n老我从他琴下爨，故人元自笛亭柯。\n北山烟岫郁嵯峨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13097, '浣溪沙', '韩', '鸦矫荒寒燕复低。\n门前长草与人齐。\n长桥南畔小桥西。\n安得有诗同尔句，可教无酒泛其杯。\n相思常苦易离携。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13098, '鹧鸪天', '韩', '只唱离歌一叠休。\n玉溪浮动木兰舟。\n如何又对云烟晚，不道难禁草树秋。\n空脉脉，忍悠悠。\n绸缪终是转绸缪。\n相思相见知何处，记取新欢说旧游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13099, '满江红', '韩', '归锦堂成，云汉上、天垂新画。\n有朱颜绿鬓，禁林仙客。\n玉局暂从香火社，金龟未报文章力。\n看彤庭、赐第别承恩，居君侧。\n斑衣戏，蟠桃摘。\n翠袖倚，歌檀拍。\n正祥开初度，颂声千百。\n又是腊前梅态度，几多春近花消息。\n想明年、今日醉西湖，光辉赫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13100, '好事近', '韩', '一涧水南山，腊尽春生梅雪。\n行过小桥深处，带疏钟横月。\n征衫闲著指东吴，休怕与人别。\n吟到翠圆枝上，是归来时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13101, '菩萨蛮', '韩', '南枝已见春消息。\n今年为寿方知得。\n俾尔炽而昌。\n流霞浮暗香。\n蓬壶清浅水。\n笑指云阶喜。\n高论不规模。\n平戎赋两都。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13102, '浣溪沙', '韩', '风软湖光远荡磨。\n春衫初试薄香罗。\n踏青无计奈君何。\n莫笑老来多岁月，肯教闲去少诗歌。\n长安陌上有铜驼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13103, '谒金门', '韩', '春尚早。\n春入湖山渐好。\n人去人来虽未老。\n酒徒犹恨少。\n梅落桃开烟岛。\n日日更吹香草。\n一片芳心拚醉倒。\n冷云藏落照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13104, '祝英台近', '韩', '馆娃宫，采香径，范蠡五湖侧。\n子夜吴歌，声缓不须拍。\n崇桃积李花闲，芳洲绿遍，更冉冉、柳丝无力。\n试思忆。\n老去一片身心，孤负好春色。\n古往今来，时序恼行客。\n去年今日山中，如何知得。\n却又在、他乡寒食。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13105, '浣溪沙', '韩', '梅叶阴阴占晚春。\n博山香尽玉嶙峋。\n茶瓯酒碗试濡唇。\n闲里常愁无伴侣，老来不是有情人。\n牡丹天气惜芳辰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13106, '洞仙歌', '韩', '溪山好处，赢得题新曲。\n待足人生甚时足。\n问临流情味，倚遍斜晖，应似画、小景生绡一幅。\n渔舟声乃，岩上云飞，杳杳归鸦去鸿逐。\n任当年伊吕，谈笑兴王，争敌恁、闲眠野宿。\n待雪天、月夜我还来，醉潇洒清幽，那些儿屋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13107, '点绛唇', '韩', '山凹春生，探梅只道今年早。\n暗香迎晓。\n人与花能好。\n岁岁持杯，天地同难老。\n须吟啸。\n放开怀抱。\n更约寻瑶草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13108, '减字木兰花', '韩', '菊花开了。\n待得梅梢来索笑。\n雪色江波。\n看尽千林未觉多。\n一丘缓步。\n只恐朝来有新句。\n岁岁年年。\n白发催人到酒边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13109, '采桑子', '韩', '萧萧两鬓吹华发，老眼全昏。\n徒倚衡门。\n岁晚寒消涧水痕。\n含情更觉沧洲远，欲语谁论。\n窈窕孤村。\n细雨梅花只断魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13110, '采桑子', '韩', '华灯自是年年好，月淡烟空。\n依旧东风。\n箫鼓吹香醉脸融。\n谢他诗侣还相觅，雨迹云踪。\n不分情浓。\n柳浅梅深鬓影松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13111, '好事近', '韩', '北客过江来，赢得家家都老。\n屈指中兴人物，到如今谁好。\n散庵常是爱山林，健笔胜挥扫。\n我则临风三叹。\n信儿曹惊倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13112, '减字木兰花', '韩', '一杯易足。\n自断此生犹杜曲。\n词客哀时，不敢愁来赋别离。\n孤城麦秀。\n常愧葛洪丹未就。\n诗罢长吟。\n衰晚迟回违寸心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13113, '鹧鸪天', '韩', '便把山林寄此身。\n也须诗酒属吾人。\n仙家旧是金堂士，吏隐新收玉局名。\n惟自乐，不忧贫。\n渊明谈笑更清真。\n年年眉寿登高後，醉帽常留菊满簪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13114, '好事近', '韩', '腊雪映江梅，冰玉更分风月。\n衮衮紫枢家世，庆诞弥时节。\n烘堂赢得戏莱衣，春酒宝杯凸。\n籍籍郑庄人物，要汉廷勋业。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13115, '太常引', '韩', '随风和雨带烟开。\n更清冷、照崔巍。\n片片亦佳哉。\n细看得、花如翦裁。\n茅檐出没，水浮桥外，人自两峰来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13116, '西江月', '韩', '脉脉蜂黄蝶粉，盈盈水秀山明。\n卖花声里听吹饧。\n佳丽芳华韵胜。\n下上休看舞燕，惺忪一任啼莺。\n枕痕屏曲梦关情。\n酒醒春宵漏尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13117, '谒金门', '韩', '行又住。\n水远山遥村路。\n把酒问春春几许。\n老年花似雾。\n坐上风流张绪。\n留我我还难去。\n却忆章台飞柳絮。\n只愁萦暮雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13118, '绕池游慢', '韩', '菏花好处，是红酣落照，翠蔼馀凉。\n绕郭从前无此乐，空浮动、山影林篁。\n几度薰风晚，留望眼、立尽濠梁。\n谁知好事，初移画舫，特地相将。\n惊起双飞属玉，萦小楫冲岸，犹带生香。\n莫问西湖西畔□，□九里、松下侯王。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13119, '水调歌头', '李廷忠', '抚景几今古，遗恨此江山。\n百年形胜，但见幽草杂枯菅。\n多少名流登览，赖有神扶坏栋，诗墨尚斑斑。\n风月要磨洗，顾我已衰颜。\n擎天手，携玉斧，到江干。\n一新奇观，领客觞咏有馀闲。\n烟草半川开霁，城郭两州相望，都在画屏间。\n便拟骑黄鹄，直上扣云关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13120, '满江红', '李廷忠', '玉帐西来，道前是、绣衣使者。\n游览处、秋风鼓吹，自天而下。\n湘水得霜清可鉴，巫峰过雨森如画。\n有神仙、佳致在胸襟，真潇洒。\n荆州宝，元无价。\n夔门政，长多暇。\n听谈兵樽俎，百川倾泻。\n此日寿觞容我劝，他年枢柄还公把。\n趁桂花、时节去朝天，香随马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13121, '鹧鸪天', '李廷忠', '槛外长江浪拍空。\n萧萧红蓼白苹风。\n三秋告稔三农庆，九日追欢九客同。\n烟渚北，月岩东。\n莫嫌光景太匆匆。\n登龙戏马英雄事，都在南楼一啸中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13122, '踏莎行', '李廷忠', '星野涵辉，云峰环翠。\n南园迎腊开梅蕊。\n瑶台仙子笑相逢，金钗行里拼沈醉。\n照乘骊珠，出闲天骥。\n相随寿母多年纪。\n春风侍宴宝花楼，五枝七叶都荣贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13123, '贺新凉・贺新郎', '李廷忠', '濯锦江头路。\n望祥云、密拥旌幢，初开天府。\n冰露壶中秋玉莹，不著人间烦暑。\n现物表、神仙风度。\n回首太清宫阙杳，是鸣珂簪笔遨游处。\n舟万斛，却西诉。\n筹边堂上兵无数。\n笑当年、蜀山谅将，夜分旗鼓。\n听取今朝宣阃令，洗尽蛮烟塞雾。\n便催唤、衮衣归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13124, '霜天晓角', '李廷忠', '洞天仙伯。\n总是梅标格。\n来索东风一笑，香浮动、潜溪月。\n寿尊谁共酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13125, '感皇恩', '李廷忠', '昨夜一星明，太微西畔。\n应得良朝诞名将。\n豹韬龙节，谈笑坐清江汉。\n年年梅雪里、开华宴。\n铁券高勋，金锺洪算。\n要同宗社流芳远。\n玺书褒异，自得君王深眷。\n看看登剑履、明光殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13126, '临江仙', '李廷忠', '人物风流真罕见，何须尘外求仙。\n绿龟千岁稳巢莲。\n醉倾金凿落，笑拥玉и娟。\n须信日边消息好，寒花也作春妍。\n笙歌乐地酒中天。\n功名无限事，都在寿觞前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13127, '临江仙', '李廷忠', '秋到三山呈瑞气，斑斑绣虎文章。\n早分桂殿一枝香。\n婉谋参幕府，华署等朝行。\n驾月娥来献寿，胜如昨夜辉光。\n十分满劝紫霞觞。\n年年花萼宴，相约侍君王。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13128, '庆清朝', '李廷忠', '天启重光，地锺上瑞，有人起自东山。\n当年谢傅，几曾鹤发貂冠。\n不似文章隽老，重来鸣步斗枢间。\n洪钧转，五原草绿，太白兵闲。\n运庆今朝初度，正日添纹线，月挂冰盘。\n恩重御壶宣劝，喜溢天颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13129, '卜算子', '李廷忠', '草际雪痕消，梅上春心动。\n碧幕红裙簇画筵，横玉声三弄。\n雅兴杂鱼龙，妙舞回鸾凤。\n莫道司空眼惯□，还入清宵梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13130, '百字令・念奴娇', '胡惠斋', '小斋幽僻，久无人到此，满地狼藉。\n几案尘生多少憾，把玉指亲传踪迹。\n画出南枝，正开侧面，花蕊俱端的。\n可怜风韵，故人难寄消息。\n非共雪月交光，这般造化，岂费东君力。\n只欠清香来扑鼻，亦有天然标格。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13131, '满江红', '胡惠斋', '暝霭黄昏，灯檠上、荧荧初炙。\n银焰袅、孤光分夜，寸心凝碧。\n留照娇颜欢笑偶，上元庆赏嬉游夕。\n笑聚萤、积雪与偷光，寒儒忆。\n蝶眷恋，成何得。\n花传喜，知何日。\n听邻家昨夜，扣阍谁觅。\n焰短始知新月上，摇红孤馆因风急。\n恨那人、别後不成眠，时时剔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13132, '卜算子', '谢直', '双桨浪花平，夹岸青山锁。\n你自归家我自归，说着如何过。\n我断不思量，你莫思量我。\n将你从前与我心，付与他人可。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13133, '金人捧露盘', '高似孙', '下明光，违宣曲，上扬州。\n玉帐暖、十万貔貅。\n梅花照雪，月随歌吹到江头。\n牙樯锦缆，听雁声、夜宿瓜州。\n南山客，东山妓，蒲萄酒，裘。\n占何逊、杜牧风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13134, '眼儿媚', '高似孙', '翠帘低护郁金堂。\n犹自未妆。\n梨花新月，杏花新雨，怎奈昏黄。\n春今不管人相忆，欲去又相将。\n只销相约，与春同去，须到君行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13135, '莺啼序', '高似孙', '青旗报春来了，玉鳞鳞风旎。\n陈瑶席、新奏琳琅，窈窕来荐嘉社。\n桂酒洗琼芳，丽景晖晖，日夜催红紫。\n湛青阳新沐，人声澹荡花里。\n光泛崇兰，坼遍桃李，把深心料理。\n共携手、蘅室兰房，奈何新恨如此。\n对佳时、芳情脉脉，眉黛蹙、羞搴琼珥。\n折微馨、聊寄相思，莫愁如水。\n青苹再转，淑思菲菲，春又过半矣。\n细雨湿香尘，未晓又止。\n莫教一无聊，群芳。\n伤情漠漠，泪痕轻洗。\n曲琼桂帐流苏暖，望美人、又是论千里。\n佳期杳渺，香风不肯为媒，可堪玩此芳芷。\n春今渐歇，不忍零花，犹恋馀绮。\n度美曲、造新声，乐莫乐此新知。\n思美人兮，有花同倚。\n年华做了，功成如委。\n天时相代何日已。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13136, '失调名', '高似孙', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13137, '蓦山溪', '易祓', '海棠枝上，留得娇莺语。\n双燕几时来，并飞入、东风院宇。\n梦回芳草，绿遍旧池塘，梨花雪，桃花雨。\n毕竟春谁主。\n东郊拾翠，襟袖沾飞絮。\n宝马趁雕轮，乱红中、香尘满路。\n十千斗酒，相与买春闲，吴姬唱，秦娥舞。\n拼醉青楼暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13138, '喜迁莺', '易祓', '帝城春昼。\n见杏脸桃腮，胭脂微透。\n一霎儿晴，一霎儿雨，正是催花时候。\n淡烟细柳如画，雅称踏青携手。\n怎知道、那人人，独倚阑干消瘦。\n别後。\n音信断，应是泪珠，滴遍香罗袖。\n记得年时，胆瓶儿畔，曾把牡丹同嗅。\n故乡水遥山远，怎得新欢如旧。\n强消遣，把闲愁推入，花前杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13139, '水调歌头', '易祓', '自古清胜地，江带与山。\n夸娥擘此石，不独岭之南。\n初见仙岩第一，再见砻岩第二，今见淡岩三。\n邱壑皆有分，品第不须谈。\n望前驱，陪後乘，破晴岚。\n出城一舍而近，峭壁与天参。\n不使尘埃脚，忽觉烟云对面，鹤驭可同骖。\n杖屦从归去，此乐湘潭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13140, '一翦梅', '易祓妻', '染泪修书寄彦章。\n贪做前廊。\n忘却回廊。\n功名成就不还乡。\n铁做心肠。\n石做心肠。\n红日三竿懒画妆。\n虚度韶光。\n瘦损容光。\n不知何日得成双。\n羞对鸳鸯。\n懒对鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13141, '水调歌头', '章斯才', '帝念重湖远，使者选清强。\n关西夫子人杰，搅辔出鸳行。\n熊楚一天坐镇，虎节三台更历，号令肃秋霜。\n褰帷间风俗，原隰总生光。\n瞻南极，朝北斗，酌霞觞。\n潢池息浪奏凯，筹饷属萧张。\n一点眉间多，一札日边有诏，香案侍东皇。\n岁岁蓬壶宴，好景对枨黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13142, '水调歌头', '章斯才', '秋老楚天阔，光粲极南星。\n郁葱瑞霭浮动，湘水舞湘灵。\n方启流虹华旦，恰值绂麟弥月，嘉会庆千龄。\n维岳绛神处，玉印注长生。\n衣衮绣，袍练鹊，纽双萦。\n民气和乐，雁到回地作欢声。\n楚观连天境界，四景撩人风物，身世自蓬瀛。\n剩酌金貂，飞诏到临蒸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13143, '水龙吟', '危稹', '洛阳九老图中，当时司马年犹小。\n争如今夕，举杯相劝，十人齐寿。\n已幸同庚，何分雌甲，本无多少。\n但有头可白，无愁可解，只如此、都赢了。\n庆礼十年还又，更十年、依前难老。\n尽教百岁，做人高祖，见孙白首。\n却要从今，探梅脚健，看山眼好。\n赖天公，顿得东园长在，陪歌陪酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13144, '渔家傲', '危稹', '老去诸馀情味浅。\n诗词不上闲钗钏。\n宝幌有人红两靥。\n帘间见。\n紫云元在梨花院。\n十四条弦音调远。\n柳丝不隔芙蓉面。\n秋入西窗风露晚。\n归去懒。\n酒酣一任乌巾岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13145, '沁园春', '危稹', '籍甚声名，门阑相种，文章世科。\n算当年瑞世，正当夏五，仙家毓德，全是春和。\n底事屏星，著之海峤，奈此腾骧骥足何。\n君知否，看飞来丹诏，径上鸾坡。\n殷勤携酒相过。\n要滟滟浮君金叵罗。\n叹同心相契，古来难觅，二年同处，意总无它。\n如此平分，更教添个，也自清风明月多。\n拼沈醉，任光浮绿鬓，笑满红涡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13146, '满江红', '王居安', '八十归来，方岩下、几竿修竹。\n柴门外，沙铺软路，水流清玉。\n栽接新来桃与李，安排旧日松和菊。\n过小桥、作个看山楼，千峰绿。\n收笔砚，藏棋局。\n酒莫饮，经须读。\n但平平放下，顿超凡俗。\n独睡已无年少梦，闲吟不唱他家曲。\n算人生、万事苦无多，相将足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13147, '沁园春', '王居安', '湖海襟期，烟霞气宇，天下星郎。\n有灵方时後，年年却老，神锋耳底，夜夜腾光。\n万卷蟠胸，千锺蘸甲，衮衮词源三峡滂。\n功成处，见须弥日月，河岳星霜。\n兴来引笔千行。\n看举世何人是智囊。\n任纵横万变，难瞒道眼，优游自乐，不识愁肠。\n闹市丛中，密林静处，鼻观常闻三界香。\n天书到，听笙箫竞奏，幢盖班行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13148, '朝中措', '王克勤', '银河无际渺澄空。\n一点寿光中。\n此夕谪仙初度，清歌吉甫清风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13149, '浣溪沙', '锺将之', '鬓云梳月带痕。\n软红香里步莲轻。\n妖娆六幅过腰裙。\n不怕满堂佳客醉，只愁灭烛翠眉颦。\n更期疏影月黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13150, '浣溪沙', '锺将之', '苹老秋深水落痕。\n桂花微弄雨花轻。\n癯仙也解醉红裙。\n太白麴君愁满饮，小鸿眉黛爱低颦。\n尊前一洗眼花昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13151, '水调歌头', '锺将之', '更似南津港，再遇吕公船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13152, '浣溪沙', '吴礼之', '南国风流是故乡。\n红盐落子不因霜。\n于中小底最珍藏。\n荐酒荐茶些子涩，透心透顶十分香。\n可人回味越思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13153, '喜迁莺', '吴礼之', '银蟾光彩。\n喜稔岁闰正，元宵还再。\n乐事难并，佳时罕遇，依旧试灯何碍。\n花市又移星汉，莲炬重芳人海。\n尽勾引，遍嬉游宝马，香车喧隘。\n晴快。\n天意教、人月更圆，偿足风流债。\n媚柳烟浓，夭桃红小，景物迥然堪爱。\n巷陌笑声不断，襟袖馀香仍在。\n待归也，便相期明日，踏青挑菜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13154, '丑奴儿・采桑子', '吴礼之', '金风颤叶，那更饯别江楼。\n听凄切、阳关声断，楚馆云收。\n去也难留。\n万重烟水一扁舟。\n锦屏罗幌，多应换得，蓼岸苹洲。\n凝想恁时欢笑，伤今萍梗悠悠。\n谩回首、妖娆何处，眷恋无由。\n先自悲秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13155, '杏花天', '吴礼之', '闷来凭得阑干暖。\n自手引、朱帘高卷。\n桃花半露胭脂面。\n芳草如茵乍展。\n烟光散、湖光潋滟。\n映绿柳、黄鹂巧啭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13156, '雨中花・夜行船', '吴礼之', '眷浓恩重，长离永别，凭谁为返香魂。\n忆湘裙霞袖，杏脸樱唇。\n眉扫春山淡淡，眼裁秋水盈盈。\n便如何忘得，温柔情态，恬静天真。\n凭栏念及，夕阳西下，暮烟四起江村。\n渐入夜、疏星映柳，新月笼云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13157, '瑞鹤仙', '吴礼之', '风传秋信至。\n颤叶叶庭梧，飘零阶砌。\n年华迅流水。\n况荣枯翻手，存亡弹指。\n谁编故纸。\n论古往、英雄斗智。\n在当时、唤做功名，到此尽成闲气。\n何谓。\n生为行客，死乃归人，世同驿邸。\n十步九计。\n空捞攘，谩儿戏。\n忍都将、有限光阴萦绊，趁逐无穷天地。\n我直须、跳出樊笼，做个俏底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13158, '蓦山溪', '吴礼之', '刘郎老矣，倦入繁华地。\n触目愈伤情，念陈迹、人非物是。\n共谁携手，落日步江村，临远水，对遥山，闲看烟云起。\n买牛卖剑，便作儿孙计。\n朋旧自荣华，也怜我、无名无利。\n箪瓢锺鼎，等是百年身，空妄作，枉迂回，贪爱从今止。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13159, '风入松', '吴礼之', '苹汀蓼岸荻花洲。\n占断清秋。\n五湖景物供心眼，几曾有、一点闲愁。\n梦里翩翩胡蝶，觉来叶叶渔舟。\n谢郎随分总优游。\n信任沈浮。\n恬然云水无贪吝，笑腰缠、骑鹤扬州。\n只恐丹青妙笔，写传难尽风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13160, '渔家傲', '吴礼之', '红日三竿莺百啭。\n梦回鸳枕离魂乱。\n料得玉人肠已断。\n眉峰敛。\n晓妆镜里春愁满。\n绿琐窗深难见面。\n云笺谩写教谁传。\n闻道笙歌归小院。\n梁尘颤。\n多因唱我新词劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13161, '蝶恋花', '吴礼之', '睡思厌厌莺唤起。\n帘卷东风，犹未梳洗。\n眼细眉长云拥髻。\n笑垂罗袖熏沈水。\n媚态盈盈闲举止。\n只有江梅，清韵能相比。\n诗酒琴棋歌舞地。\n又还同醉春风里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13162, '蝶恋花', '吴礼之', '急水浮萍风里絮。\n恰似人情，恩爱无凭据。\n去便不来来便去。\n到头毕竟成轻负。\n帘卷春山朝又暮。\n莺燕空忙，不念花无主。\n心事万千谁与诉。\n断云零雨知何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13163, '蝶恋花', '吴礼之', '满地落红初过雨。\n绿树成阴，紫燕风前舞。\n烟草低迷萦小路。\n昼长人静扃朱户。\n沈水香销新剪苎。\n枕朦胧，花底闻莺语。\n春梦又还随柳絮。\n等闲飞过东墙去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13164, '桃源忆故人', '吴礼之', '画桥流水飞花舞。\n柳外斜风细雨。\n红瘦绿肥春暮。\n肠断桃源路。\n欢随仙子乘鸾去。\n镂月裁云何处。\n唯有病和愁绪。\n肯伴刘郎住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13165, '谒金门', '吴礼之', '风乍扇。\n帘外落红千片。\n飞尽落花春不管。\n斗忙莺与燕。\n往事上心撩乱。\n睡起日高犹倦。\n料得伊家情眷眷。\n近来长梦见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13166, '霜天晓角', '吴礼之', '连环易缺。\n难解同心结。\n痴呆佳人才子，情缘重、怕离别。\n意切。\n人路绝。\n共沈烟水阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13167, '霜天晓角', '吴礼之', '西风又急。\n细雨黄花湿。\n楼枕一篙烟水，兰舟漾、画桥侧。\n念昔。\n空泪滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13168, '生查子', '吴礼之', '吴山与越山，相对摩今古。\n袅缆浙江亭，回首西兴渡。\n区区名利人，无分香闺住。\n匆遽促征鞍，又入临平路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13169, '失调名', '吴礼之', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13170, '好事近', '吴礼之', '金菊间芙蓉，秋意未为萧索。\n临水见山庭院。\n伴玉人杯酌。\n携炉终日袅沈烟，氤氲篆文□。\n可惜被风吹散，把袖儿笼著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13171, '柳梢青', '吴礼之', '板约红牙。\n歌翻白雪，杯泛流霞。\n苏小情多，潘郎年少，欢计生涯。\n轩窗临水人家。\n更门掩、青春杏花。\n百万呼卢，十千沽酒，不负韶华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13172, '满江红', '陈善', '三月风前花薄命，五更枕上春无力。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13173, '满江红', '丁黼', '梅腊宾春，瑞烟满、华堂馥郁。\n还又祝、屏垂彩，觞称。\n南浦西山开寿域，朱帘画栋调新曲。\n庆彩衣、龙节侍慈萱，春长绿。\n双鹤发，齐眉福。\n一麟瑞，如冰玉。\n看国封重见，五霞凝轴。\n王母瑶池鸾凤驭，麻姑金鼎神仙。\n数从今、椿算到何时，蟠桃熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13174, '贺新凉・贺新郎', '俞国宝', '梦里骖鸾鹤。\n觉三山不远，依前海风吹落。\n浮到五湖烟月上，刚被梅香醉着。\n粲玉树、轻明疏薄。\n十万琼琚天女队，捧冰壶、玉液琉璃杓。\n来伴我，荐清酌。\n恍然梦断浑非昨。\n问溪边竹外，新来为谁开却。\n无限冰魂招不得，拟把离骚唤觉。\n待抖擞、红尘双脚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13175, '风入松', '俞国宝', '一春长费买花钱。\n日日醉花边。\n玉骢惯识西湖路，骄嘶过、沽酒垆前。\n红杏香中箫鼓，绿杨影里秋千。\n暖风十里丽人天。\n花压髻云偏。\n画船载取春归去，馀情寄、湖水湖烟。\n明日重扶残醉，来寻陌上花钿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13176, '瑞鹤仙', '俞国宝', '春衫和泪著。\n又燕入江南，雁归衡岳。\n东风晓来恶。\n绕西园无绪，泪随花落。\n愁钟恨角。\n梦无凭、难成易觉。\n到春来易感，韩香顿减，沈腰如削。\n离索。\n挑灯占信，听鹊求音，不禁春弱。\n云轻雨薄。\n阳台远，信难托。\n念盟钗一股，鸾光两破，已负秦楼素约。\n但莫教、嫩绿成阴，把人误却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13177, '清平乐', '俞国宝', '数声乌鹊。\n院宇寒萧索。\n杨柳梢头秋过却。\n无叶可供风落。\n可人犹有芙蕖。\n向人泠澹妆梳。\n云外征鸿过尽，夕阳依旧平芜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13178, '卜算子', '俞国宝', '翦烛写香笺，拨火温寒醑。\n门外东风将我愁，欲作三更雨。\n夜夜玉楼心，日日长亭路。\n豆蔻花开信不来，尘满金钗股。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13179, '风入松', '俞国宝', '东风巷陌暮寒骄。\n灯火闹河桥。\n胜游忆遍钱塘夜，青鸾远、信断难招。\n蕙草情随雪尽，梨花梦与云销。\n客怀先自病无聊。\n绿酒负金蕉。\n下帏独拥香篝睡，春城外、玉漏声遥。\n可惜满街明月，更无人为吹箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13180, '水调歌头', '徐冲渊', '穷达付天命，生死见交情。\n人今老矣，□□狗苟与蝇营。\n赢得一头霜雪。\n闲却五湖风月。\n鸥鸟负前盟。\n颜厚已如甲，太息误平生。\n想箕山，怀颍水，挹馀清。\n只今归去，沧浪深处濯吾缨。\n笑抚山中泉石。\n细说人间荆棘。\n有道苦难行。\n好补青萝屋，且占白云耕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13181, '谒金门', '李好义', '花过雨。\n又是一番红素。\n燕子归来衔绣幕。\n旧巢无觅处。\n谁在玉楼歌舞。\n谁在玉关辛苦。\n若使胡尘吹得去。\n东风侯万户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13182, '望江南・忆江南', '李好义', '思往事，白尽少年头。\n曾帅三军平蜀难，沿边四郡一齐收。\n逆党反封侯。\n元宵夜，灯火闹啾啾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13183, '水调歌头', '程准', '船系钓台下，身寄碧云端。\n胸中千古风月，笔下助波澜。\n唤起羊裘仙魄，来伴蝉冠清影，星阁倚阑干。\n上想中兴事，名节重於山。\n濯沧浪，开玉鉴，照朱颜。\n平生多少英气，直欲斩楼兰。\n尽道诗书元帅，好作经纶上衮，勋业秉华丹。\n霄汉展鸾翼，雷雨震龙蟠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13184, '秋日田父辞', '高翥', '啄黍黄鸡没骨肥。\n绕篱绿橘缀枝垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13185, '秋日田父辞', '高翥', '少妇蓝旋染裙。\n大儿敲葛自浆巾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13186, '念奴娇', '高惟月', '岩扃不锁，算空洞深窈，是谁初凿。\n帝遣六丁持月斧，乱把云根斫。\n骇目奇观，恍如崩浪，汹涌从天落。\n谪仙何处，翠珉佳句如昨。\n惆怅白首重游，多情还似，与青山有约。\n且对清尊酬胜赏，休想舞衣歌乐。\n景物依然，头颅如许，何事嗟漂泊。\n翩翩归兴，故山无限林壑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13187, '水调歌头', '彭叔夏', '铜章纡墨绶，茜服佩银鱼。\n慈闱一笑，全胜莱子彩衣裾。\n好事柿红萱草，长伴朱颜绿发，荣贵更谁如。\n轴锦装鸾诰，帘绣藤舆。\n龙为炙，麟作脯，倒琼壶。\n寿筵今年，邀请金母伴麻姑。\n缥渺飞琼舞罢，宛转双成歌彻，何物奉亲娱。\n探支长命缕，预借角蟾蜍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13188, '失调名', '应', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13189, '失调名', '吴康', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13190, '失调名', '吴康', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13191, '贺新郎', '汪', '田舍炉头语。\n便如何学得，三变美成家数。\n村酒三杯狂兴发，拔剑偶然起舞。\n只麽也、迎寒送暑。\n待草万言书上阙，似忧端、倚柱东邻女。\n卿相事，未易许。\n渔歌且和芙蓉渚。\n又何须、淫辞语，诃风诋雨。\n劝人生、且随缘分，分外一毫莫取。\n那富贵、由天付与。\n身蹈危机犹不觉，如布衣、自在都无阻。\n空博得，雪千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13192, '蝶恋花', '汪', '午夜凉生风不住。\n河汉无声，时见疏星度。\n佳客伴君知未去。\n对床只欠潇潇雨。\n素月四更山外吐。\n金鸭慵添，消尽沈烟缕。\n料想玉楼人念处。\n归舟日望荷花浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13193, '念奴娇', '汪', '谁家野菜饭炊香，正是江南寒食。\n试问春光今几许，犹有三分之一。\n枝上花稀，柳间莺老，是处春狼藉。\n新来燕子，尚传晋苑消息。\n应记往日西湖，万家罗绮，见满城争出。\n急管繁弦嘈杂处，宝马香车如织。\n猛省狂游，恍如昨梦，何日重寻觅。\n杜鹃声里，桂轮挂上空碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13194, '水调歌头', '汪', '落日水亭静，藕叶胜花香。\n时贤飞盖，松间喝道挟胡床。\n暑气林深不受，山色晚来逾好，顿觉酒尊凉。\n妙语发天籁，幽眇亦张皇。\n射者中，弈者胜，兴悠长。\n佳人雪藕，更调冰水赛寒浆。\n惊饵游鱼深逝，带箭山禽高举，此话要商量。\n溪上采菱女，三五傍垂杨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13195, '如梦令', '汪', '几点弄晴微雨。\n翳日薄云来去。\n断送一番春，满径杨花飞絮。\n无语。\n无语。\n还是旧时院宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13196, '贺新郎', '汪', '帖子传新语。\n问自来、翰林学士，几多人数。\n或道江心空铸镜，或道艾人如舞。\n或更道、冰盘消暑。\n或道芸香能去蠹，有宫中、斗草盈盈女。\n都不管，道何许。\n离骚古意盈洲渚。\n也莫道、龙舟吊屈，浪花吹雨。\n只有辟兵符子好，少有词人拈取。\n谁肯向、帖中道与。\n绝口用兵两个字，是老臣、忠爱知艰阻。\n写此句，绛纱缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13197, '贺新郎', '汪', '夜对灯花语。\n且随宜、果盘草草，两三杯数。\n翠玉环中园五亩，自唱山歌自舞。\n况今夜、尊前无暑。\n何用食前须方丈，更後车、何用婵娟女。\n这闲福，自心许。\n蓼花芦叶纷江渚。\n有沙边、寒蛩吟透，梧桐秋雨。\n羡甚满堂金玉富，未可学人渔取。\n怕天也、未曾相与。\n豹遁蛟藏泉可濯，有鬼神、呵护盘之阻。\n鲜可食，脍银缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13198, '鹧鸪词・瑞鹧鸪', '汪', '伤时怀抱不胜愁。\n野水粼粼绿遍洲。\n满地落花春病酒，一帘明月夜登楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13199, '念奴娇', '汪', '相逢草草，共吟诗、同醉杯中之物。\n评论三王讥五霸，谈辩喧哗邻壁。\n敲缺唾壶，击残如意，妙语飞华雪。\n无能为也，如何对此三杰。\n看取东野诗成，南昌书就，奈征车催发。\n後夜山深何处宿，红豆寒灯明灭。\n一老堪怜，两生未起，应念星星发。\n风传佳话，花村无犬惊月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13200, '西江月', '汪', '千缕柳丝犹嫩，一星榆火初明。\n载将新意寿幽人。\n红袖持杯劝尽。\n老鹤自偏野性，沙鸥难比轻身。\n殷勤多谢祝长春。\n一笑东风夜静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13201, '沁园春', '汪', '民吾同胞，剖破藩篱，元是大家。\n故见之诰诏，视如子弟，谆勤恳切，悃无华。\n孝悌力田，职当劝相，起早非干为看花。\n亲酌酒，老农唯诺，句句仁芽。\n晓来犹觉寒些。\n看雨湿风吹旗□斜。\n笑吾生八十，尽谙农事，公筵既彻，更共烹茶。\n高唱豳风，敬酬令尹，王道桑麻乐有涯。\n春务急，见溪头杨柳，已可藏鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13202, '如梦令', '汪', '一只船儿没赛。\n七十六年装载。\n把柁更须牢，风饱蒲帆轻快。\n无碍。\n无碍。\n匹似子猷访戴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13203, '江城子', '汪', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13204, '南乡子', '虞刚简', '儿有掌中杯。\n但把归期苦苦催。\n奕世衣冠仍上第，公台。\n元自诗书里面来。\n秋色为渠开。\n先我梁山马首回。\n猿鹤莫轻窥蕙帐，惊猜。\n抬步归休亦乐哉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13205, '向湖边', '张拭', '万里烟堤，百花风榭，游女翩翩羽盖。\n彩挂秋千，向花梢娇对。\n矧门外、森立乔松，日花争丽，犹若当年文会。\n廊庙夔龙，暂卜邻交外。\n共讲真率，玉糁金齑脍。\n同萧散寄傲，樽倾北海。\n佳处难忘，约追欢须再。\n况风月不用一钱买。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13206, '霜天晓角', '赵希明', '空山木落。\n月淡阑干角。\n相与羊裘披上，方知道、宦情薄。\n老来须自觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13207, '醉蓬莱', '程', '望皇都清晓，瑞日祥烟，洞开阊阖。\n一朵红云，映重瞳日月。\n万岁山高，九霞杯暖，正想宸游洽。\n绝塞庭琛，重闱天笑，年年仙阙。\n韶凤徘徊，蒲鱼演漾，镐酒恩浓，龙蟠建业。\n玉琢麟符，分付人中杰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13208, '西江月', '程', '岁贡来从玉垒，天恩拜赐金奁。\n春风一朵紫云鲜。\n明月轻浮盏面。\n想见清都绛阙，雍容多少神仙。\n归来满袖玉炉烟。\n愿侍年年天宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13209, '鹧鸪天', '程', '饮罢天厨碧玉觞。\n仙韶九奏少停章。\n何人采得扶桑椹，捣就蓝桥碧绀霜。\n凡骨变，骤清凉。\n何须仙露与琼浆。\n君恩珍重浑如许，祝取天皇似玉皇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13210, '水调歌头', '程', '玉女扫天净，雍观掠江宽。\n问君何事底急，夜半挟舟还。\n三岛眠龙惊觉，万顷明琼碾破，凉月照东南。\n碧气正吞吐，满挹漱膺肝。\n烟蓬上，乘云象，嗷天关。\n人间已梦，我独危坐玩漫汗。\n螭殿黄昏未锁，鹤氅翩跹蜚下，共吸酒壶乾。\n兴罢吹笙去，风露五更寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13211, '水调歌头', '程', '电阙驱神骏，铁棰起痴蛟。\n木鸣山裂盛夏，白昼野号。\n急上瑶庭深处，为问龙君何怒，抉破古天河。\n日华开绚采，雨意属诗豪。\n与君来，蜚玉佩，斩觚瓢。\n纤流沈羽，借我万斛沸银涛。\n醉拍满缸香雪，写竭一池浓墨，逸气正飘。\n何事谪仙子，归去续松醪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13212, '水调歌头', '程', '日毂金钲赤，雪窦水晶寒。\n支机石下翻浪，喷薄出层关。\n半夜雌龙惊走，明日灵蛇张甲，蜚上石盘桓。\n多谢山君护，未放醉翁闲。\n安得醉，风，露珊珊。\n翠云老子，邀我瑶佩驾红鸾。\n一勺流觞何有，万石横缸如注，虹气饮溪乾。\n忽梦坐银井，长啸俯清湍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13213, '水调歌头', '程', '天地本无际，南北竟谁分。\n楼前多景，中原一恨杳难论。\n却似长江万里，忽有孤山两点，点破水晶盆。\n为借鞭霆力，驱去附。\n望淮阴，兵冶处，俨然存。\n看来天意，止欠士雅与刘琨。\n三拊当时顽石，唤醒隆中一老，细与酌芳尊。\n孟夏正须雨，一洗北尘昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13214, '水调歌头', '程', '渤东南界，西北倚。\n当时推步，但知宇内有乾坤。\n午夜风轮微转，驾我浮空泛景，一息过天垠。\n俯视人间世，渺渺聚沤尘。\n挽天吴，摩海若，吐还吞。\n宁用计年，八十阳九又三阴。\n要自白榆星外，直至黑流沙底，山与泽俱平。\n不论初末度，一色界如银。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13215, '六州歌头', '程', '向来抵掌，未必总谈空。\n难遍举，质三事，试从公。\n记当年，赋得一丘一壑，天鸢阔，渊鱼静，莫击磬，但酌酒，尽从容。\n一水西来他日，会从公、曳杖其中。\n问前回归去，已笑白发成蓬。\n不识如今，几西风。\n蒙庄多事，论虱豕，推羊蚁，未辞终。\n又骤说，鱼得计，孰能通。\n□□□。\n叹如云罔罟，龙伯啖，眇难穷。\n凡三惑，谁使我，释然融。\n岂是匏瓜者，把行藏、悉俯鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13216, '满江红', '程', '黄鹤楼前，江百尺、波横光溢。\n问老子、当年高兴，何人知得。\n最爱洞庭天际水，分明表里玻璃色。\n恐今宵、未必似前番，天应惜。\n都莫问，鸿锺勒。\n也休羡，壶天谪。\n忆故人霜下，乱滩横笛。\n便好骑鲸游汗漫，古来蟾影何曾没。\n更明年、重约再来时，乘槎客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13217, '满江红', '程', '颇恨登临，浪自作、骚人愁语。\n石城上、何须苦说，死袁生褚。\n当日卧龙商略处，秦淮王气真何许。\n与君来、萧瑟北风寒，黄云暮。\n枕锺阜，湖玄武。\n生此虎，真蹲踞。\n看四山环合，休临江渚。\n可笑唐人无意度，却言此虎凌波去。\n君且住、明月为人来，潮生浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13218, '沁园春', '程', '玉局仙人，轻帆万里，送入三吴。\n怪一舟如叶，元无浊物，依然姑射，满载冰壶。\n昔日文君，千言成诵，不识如今记得无。\n新来也，喜都将分付，一颗骊珠。\n向来田赋蠲输。\n散多少、春风巴与渝。\n算公家粗了，莼鲈而已，何妨西子，白发江湖。\n印铸黄金，时来须佩，毕竟人生万卷书。\n离情处，正秦淮岁晚，雪意模糊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13219, '步虚词・西江月', '程', '休怪频年司钥，仙官长守仙宫。\n东风未肯到凡红。\n先舞云韶彩凤。\n都是一团和气，故教上苑春浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13220, '沁园春', '程', '公有仙姿，苍松野鹤，落落昂昂。\n论法主长生，仍须极贵，云台绛阙，都许尚羊。\n更忆当年，而今时候，一念功名下帝旁。\n天分付，使人间草木，尽有春香。\n人知相法奇庞。\n又那识、阴功事更长。\n算毗陵荒政，江东风采，忠文典则，生光。\n再岁秦淮，觚棱入梦，帷幄从来在庙堂。\n公归去，好平心献替，人望时康。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13221, '沁园春', '程', '那用招秋，休言推暑，风自薰兮。\n问谁解当初，识公来处，月明碧落，旆卷青霓。\n千丈长松，起人生意，冻芋寒瓜空满畦。\n还堪怪，怪诸公衮衮，我尚凭泥。\n须教一举崔嵬。\n算人世、功名各有梯。\n更何须炼鼎，玄霜绛雪，只烦煮茗，水饼冰齑。\n紫府多仙，招来满座，公自长生角亢齐。\n何曾也，有玉麟行地，老凤梧栖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13222, '沁园春', '程', '君有新词，何妨为我，时遣奚奴。\n看此山大小，风流晋宋，眼中馀子，苦自侏儒。\n九曲清溪，千枝杨柳，还记新条更有无。\n春将好，欲从君商略，君意何如。\n佳人玉佩琼琚。\n更胸中、浇灌有诗书。\n把古人行处，从头检点，今人说底，却不须渠。\n更上石头，重登锺阜，画作金陵考古图。\n频相见，怕薰风早晚，便隔天隅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13223, '沁园春', '程', '消得雕栏，也不枉教，车马如狂。\n怪元和一事，韩公子者，归来斫去，玉毁冈。\n为解花嘲，朝来试看，采佩殷霞露香。\n君休怪，算只缘太艳，俗障难降。\n诗人未易平章。\n向百卉、雕零独後装。\n看洪炉大器，从来成晚，只须这著，也做花王。\n况是月坡，花围一尺，压尽纷纷琐细芳。\n还堪笑，笑龙锺老凤，方入都堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13224, '沁园春', '程', '试课阳坡，春後添栽，多少杉松。\n正桃坞昼浓，云溪风软，从容延叩，太史丞公。\n底事越人，见垣一壁，比过秦关遽失瞳。\n江神吏，灵能脱罟，不发卫平蒙。\n休言唐举无功。\n更休笑、丘轲自厄穷。\n算汨罗醒处，元来醉里，真敖假孟，毕竟谁封。\n太史亡言，床头酿熟，人在晴岚杳霭中。\n新堤路，喜枝鳞角，夭矫苍龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13225, '锦堂春・锦堂春慢', '程', '最是元来，苦无风雨。\n只恁匆匆归去。\n看游丝、都不恨，恨秦淮新涨，向人东注。\n醉里仙人，惜春曾赋。\n却不解、留春且住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13226, '壶中天・念奴娇', '程', '日躔东井，正轮桂影，十分光洁。\n火令方中符国运，天与非常英杰。\n荦荦平生，眼空宇宙，绿发千寻雪。\n笑谈一镇，单于底事心慑。\n晚岁佛地功深，人间富贵，五湖烟水阔。\n谁遣心期事左，须酬满、麒麟勋业。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13227, '烛影摇红', '程', '青旆摇风，朱帘漏月黄昏早。\n蓬山万叠忽蜚来，上有千灯照。\n和气祥烟缭绕。\n映琼楼、五云缥缈。\n青裙缟袂，乱吹繁弦，九衢欢笑。\n元是琴堂，十分管领春光到。\n手移星宿下人寰，招客来仙岛。\n信道邦人见少。\n彷佛似、皇都春好。\n明年只恐，鳌山扈从，随班清晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13228, '谒金门', '程', '烟漠漠。\n醉里看春都错。\n过了清明迟一著。\n牡丹重约摸。\n晓日渐明檐角。\n天与芳辰难却。\n驻得韶华元有药。\n桃源谁共约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13229, '水龙吟', '程', '道家弱水蓬莱，鲸波万里谁知得。\n人间自有，南昌居士，仙风道骨。\n诗似白星，貌如聃老，风尘挺出。\n向谪仙家里，滕王阁畔，飘玉佩、下丹阙。\n黄发四朝元老，又谁知、重生绿发。\n手提一笔，活人多少，三千功积。\n已冠文昌，人人瞻望，玉枢躔逼。\n对新凉、酒颊微红，宛是一星南极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13230, '喜迁莺', '程', '少年意气，脑燕兵胡，虏王区脱。\n眼底朦胧，腹中空洞，不著曹刘元白。\n闻道殊科八中，也要彩卢连掷。\n收拾尽，到如今但有，寸心如铁。\n天付，真奇特。\n口静神充，双眼胡僧碧。\n楚国离骚，唐朝词学，未信芳尘□歇。\n结取佳人香佩，截断儿曹绮舌。\n归去也，且斓斑戏彩，好春长日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13231, '喜迁莺', '程', '评君谁似，似长松千丈，离奇多节。\n骨瘦棱棱，文高荦荦，今日□来仙阙。\n走卒识公容貌，酋虏问公官阀。\n更史馆，一编书多少，频添勋业。\n伟绝。\n今岁别。\n新绿名孙，又见枝生叶。\n底事七旬，双瞳如水，毕竟桂花方发。\n赐第彤墀秋早，又一瑶枢光洁。\n故人也，念相逢谁似，凤池同列。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13232, '喜迁莺', '程', '一天风露，喜初行弹压，人间残暑。\n金母此时，云先绛，又见枢星光吐。\n人道鸿逢日，可是东方明处。\n更天上、走王人络绎，仪鸾琼醑。\n听语。\n更希举。\n试把皇朝、盛事都来数。\n当日鳌头，皇扉侍母，绿发方瞳□□。\n更有飞凫王季，往往文星再聚。\n浑休问，但回班千岁，貂蝉成谱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13233, '喜迁莺', '程', '去年玉燕，记曾期今岁，瑶光入度。\n今日都人，从头屈指，尽是黑头公辅。\n争道一朝语合，谁信千龄际遇。\n更积雨。\n晓来晴，洗出琉璃秋宇。\n笑语。\n知何许。\n旆卷青霓，来自钧天所。\n道骨仙风，安排顿著，须是人间紫府。\n要识云台高绝，更有凤池深处。\n从今数。\n看千秋万岁，永承明主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13234, '柳梢青', '程', '官已尚书，人犹寒素，仙有名言。\n谓是若人，法当至贵，仍主修年。\n唐人四字鲜妍。\n堪照映、画堂彩烟。\n更对新凉，一声芝曲，万斛金船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13235, '柳梢青', '程', '嫩绿成堆。\n朝来红紫，都在莓苔。\n方见春来，又闻春去，暗里谁催。\n人生易老何哉。\n春去矣、秋风又来。\n何似云溪，长春日月，无去无归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13236, '酹江月・念奴娇', '程', '平生有意，把六经膏泽，人人沾受。\n白被子明康节辈，浪说乘除先後。\n遇合一时，英雄千古，谁是高强手。\n蹉跎岁晚，临风浩然搔首。\n今但入梦青山，云溪深处，烟月生怀袖。\n宿有十年萧散愿，此段功缘须就。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13237, '贺新郎', '程', '袖手云溪畔。\n看人间、纷纷饥乌腐鼠，触蛮交战。\n便得金鱼垂玉带，多少雌黄点勘。\n算此语、必非河汉。\n直自弹冠班八座，更青春、数到期颐算。\n一段玉，无纤玷。\n公难学处尤堪羡。\n全似□、泠泠秋水，体清形健。\n衮处从来高一著，那肯随人脚转。\n要须是、常见乾坤清晏。\n天意未教公猛去，要都俞、了却从公便。\n歌寿，朱帘卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13238, '宝鼎现', '程', '绿杨欲舞，红杏微笑，春工渐侈。\n试偻指、自从嘉定，数到宝庆□□里。\n无一岁、不书年大有，问元功谁燮理。\n□□□、於变雍熙，如此自当千岁。\n况是端笏蓬莱陛。\n但看雍容、玉立山峙。\n炼五色、补天无迹，扶日天衢光四被。\n安清、填群心声色，恬然如谈笑耳。\n更八荒、民生奠枕，此著又当千岁。\n又况善述先猷，严武备、不开边鄙。\n阴功遍南北，千岁未多畴祉。\n且说总是三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13239, '念奴娇', '程', '归来一笑，尚看看趁得，人间寒食。\n阿寿牵衣仍问我，双鬓新来添白。\n忍见庭前，去年芳草，依旧青青色。\n西湖雨後，绿波两岸平拍。\n天教断送流年，三之一矣，又是成疏隔。\n燕子春寒浑未到，谁说江南消息。\n玉树熏香，冰桃翻浪，好个山间景物。\n这回归去，松风深处横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13240, '念奴娇', '程', '嫣然一笑，向烛花光下，经年才见。\n欲语还羞如有恨，方得东君一盼。\n天意无情，更教微雨，香泪流丹脸。\n今朝霁色，笙歌初沸庭院。\n因是思入东屏，当年手植，遍桃源低岸。\n失脚东来春七度，辜负芳丛无限。\n问讯园丁，宁如归去，细与从头看。\n东风独立，白云遮断双眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13241, '倾杯・倾杯乐', '程', '銮殿秋深，玉堂宵永，千门人静。\n问天上、西风几度，金盘光满，露浓银井。\n碧云飞下双鸾影。\n迤逦笙歌近笑语，群仙隐隐。\n更前问讯。\n堕在红尘今省。\n渐曙色、晓风清迥。\n更积霭沈阴、都卷尽。\n向窗前、引镜看来，尚喜精神炯炯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13242, '醉蓬莱', '程', '算千葩百卉，谁伴东风，早春时候。\n唯有江梅，在人间长久。\n雪後霜前，冲涉多少，尚精神如旧。\n岁岁年年，酴酥饮了，便为公寿。\n更向尊前席上，细看人与梅花，棱棱争瘦。\n桃李漫山，都落芳尘後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13243, '醉蓬莱', '程', '记蟾宫桂子，撒向人间，如今时候。\n□□□□，□□□□□。\n白下长干，乱滩横笛，想昔游依旧。\n大海一沤，千年一息，谁称彭寿。\n开遍门前丹蕊，渐西风入东篱，酿成仙酒。\n□□□□，□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13244, '西江月', '程', '天上初秋桂子，庭前八月丹花。\n一年一度见仙槎。\n秋色分明如画。\n愿把阴功一脉，灯灯相续无涯。\n降祥作善岂其差。\n永作渔樵嘉话。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13245, '西江月', '程', '底事中秋无月，元来留待今宵。\n群仙拍手度仙桥。\n惊起眠龙夭矫。\n天上灵槎一度，人间八月江潮。\n西兴渡口几魂消。\n又见潮生月上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13246, '满庭芳', '程', '未岁嘉平，初旬日四，雪中归自崇唐。\n山林湖海，一气接苍茫。\n踏尽玉龙千丈，更一望、龙尾天长。\n须臾上，高峰四顾，迤逦过前冈。\n群山，如玉削，松林百万，尽傅琼霜。\n浑疑是天际，一鹤翱翔。\n人道玉皇三六，欲一叩、风力方刚。\n明朝好，金乌衔烛，八表散祥光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13247, '满庭芳', '程', '去腊飞花，今春未已，迤逦将度元宵。\n俄然甲子，青帝下新条。\n净扫一天沈霭，红轮满、大地山河。\n从今好，便当听取，万国起歌谣。\n有人，当此际，锄云深坞，剪月中阿。\n已占断春风，自种仙桃。\n更扶疏桂影直，从岩底、上拂云梢。\n仍为我，长摩苍石，无负此清波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13248, '满庭芳', '程', '人道苍姬，燠多寒少，故教千岁绵绵。\n算来春夏，一气本无偏。\n底事今年玉历，秋未朔、风露泠然。\n君知否，山深地僻，自是早霜天。\n如今，当此去，十分亲切，面问婵娟。\n何须看仙槎，海上重还。\n好在金英玉屑，□为我、满泛金船。\n仍传语，横江秀石，□永锁三川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13249, '减字木兰花', '程', '不应双睫。\n看尽人间花与雪。\n曾是当时。\n一朵红云拥日飞。\n如今正好。\n万绿千红深处坐。\n也使春工。\n唤作天池五月风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13250, '意难忘', '朱用之', '宫额涂黄。\n怕笺凝怨墨，酒渍离觞。\n红楼春寄梦，青琐夕生香。\n花气暖，柳阴凉。\n棹曲水沧浪。\n爱弄娇、临流梳洗，顾影低相。\n桃花结子成双。\n纵题红去後，枉误刘郎。\n琴心挑别恨，莺羽学新妆。\n千万恨，恼愁肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13251, '失调名', '厉元范', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13252, '昭君怨', '郑域', '道是花来春未。\n道是雪来香异。\n竹外一枝斜。\n野人家。\n冷落竹篱茅舍。\n富贵玉堂琼榭。\n两地不同栽。\n一般开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13253, '念奴娇', '郑域', '水晶宫殿，放三千龙女，凌波浮浴。\n花里雕房分洞户，隐隐钉头齐簇。\n处子娇羞，碧裙无袖，密护圆玉。\n堤头微露，半身犹掩金绿。\n知是紫府筵开，□随纤指，出玲珑窗屋。\n倩剥霓裳轻手搔，掐损些些香玉。\n端的中心，密藏芳意，苦苦何时足。\n巴城憔悴，采歌犹闻新曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13254, '蓦山溪', '郑域', '嫣然一笑，风味人间没。\n来自广寒宫，直偷得、天香入骨。\n软金缕屑，点缀碧琼枝，花藏叶，叶笼花，刚被风吹拂。\n道人衾帐，不用沈烟熨。\n插满枕屏山，觉身在、蓝桥仙窟。\n一觞一咏，消得九秋愁，篱边菊，畹中兰，甘避芳尘不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13255, '霜天晓角', '郑域', '绿云剪叶。\n低护黄金屑。\n占断花中声誉，香与韵、两清洁。\n胜绝。\n君听说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13256, '念奴娇', '郑域', '素肌莹净，隔鲛绡贴衬，猩红妆束。\n火伞飞空熔不透，一块玲珑冰玉。\n破暑当筵，褪衣剥带，微露真珠肉。\n中心些子，向人何大焦缩。\n应恨旧日杨妃，尘埃走遍，向南闽西蜀。\n困入筠笼消黯搅，香色精神愁蹙。\n赖有君谟，为传家谱，不弃青黄绿。\n到头甜口，是人都要圜熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13257, '念奴娇', '郑域', '蕊宫仙子，爱痴儿、不禁三偷家果。\n弃核成根传汉苑，依旧风烟难□。\n老养丹砂，长留红脸，点透胭脂颗。\n金盘盛处，恍然天上新堕。\n莫厌对此飞觞，千年一熟，异人间梨枣。\n刘阮尘缘犹未断，却向花间飞过。\n争似莲枝，摘来满把，莺嘴平分破。\n餐霞嚼露，镇长歌醉蓬岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13258, '念奴娇', '郑域', '东陵美景，有轻烟和月，斜风吹雨。\n一体龙须随地转，不学松萝儿女。\n结就员青，收来掌握，犹带金盘露。\n拍浮金井，水花零乱飞舞。\n谁信六月飘霜，破开落刃，散银丝金缕。\n冷碧凄香萦齿颊，洗我尘襟烦暑。\n杜老吟诗，已公留客，此兴无今古。\n安期非诞，世间有枣如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13259, '画堂春', '郑域', '东风吹雨破花悭。\n客毡晓梦生寒。\n有人斜倚小屏山。\n蹙损眉弯。\n合是一钗双燕，却成两镜孤鸾。\n暮云修竹泪留残。\n翠袖凝斑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13260, '桃源忆故人', '郑域', '东风料峭寒吹面。\n低下绣帘休卷。\n憔悴怕他春见。\n一任莺花怨。\n新愁不受诗排遣。\n尘满玉毫金砚。\n若问此愁深浅。\n天阔浮云远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13261, '念奴娇', '郑域', '嗟来咄去，被天公、把做小儿调戏。\n蹀雪龙庭归未久，还促炎州行李。\n不半年间，北胡南越，一万三千里。\n征衫著破，著衫人、可知矣。\n休问海角天涯，黄蕉丹荔，自足供甘旨。\n泛绿依红无个事，时舞斑衣而已。\n救蚁藤桥，养鱼盆沼，是亦经纶耳。\n伊周安在，且须学老莱子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13262, '浣溪沙', '郑域', '酒薄愁浓醉不成。\n夜长枕数残更。\n嫩寒时节过烧灯。\n已自孤鸾羞对镜，未能双凤怕闻笙。\n莫教吹作别离声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13263, '霜天晓角', '王澡', '疏明瘦直。\n不受东皇识。\n留与伴春终肯，千红底、怎著得。\n夜色。\n何处笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13264, '祝英台近', '王澡', '玉东西，歌宛转。\n未做苦离调。\n著上征衫，字字是愁抱。\n月寒鬓影刁萧，舵楼开缆，记柳暗、乳鸦啼晓。\n短亭草。\n还是绿与春归，罗屏梦空好。\n燕语难凭，憔悴未渠了。\n可能妒柳羞花，起来浑懒，便瘦也、教春知道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13265, '点绛唇', '赵希', '又是年时，冷烟寒食梨花院。\n柳金拖线。\n一曲珠歌转。\n翠碧雕梁，风软帘通燕。\n何须劝。\n酒豪诗健。\n逸韵今重见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13266, '满江红', '戴复古', '赤壁矶头，一番过、一番怀古。\n想当时、周郎年少，气吞区宇。\n万骑临江貔虎噪，千艘列炬鱼龙怒。\n卷长波、一鼓困曹瞒，今如许。\n江上渡，江边路。\n形胜地，兴亡处。\n览遗踪，胜读史书言语。\n几度东风吹世换，千年往事随潮去。\n问道傍、杨柳为谁春，摇金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13267, '水调歌头', '戴复古', '雕鹗上云汉，虎豹守天关。\n一官游戏，笑向古郢试朱。\n天下封疆几郡，尽得公为太守，奉诏仰天宽。\n万物一吐气，千里贺平安。\n雪楼高，三百尺，玉栏干。\n政成无事，时复把酒对江山。\n问讯莫愁安在，见说风流宋玉，犹有屋三间。\n请和阳春曲，留与世人看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13268, '沁园春', '戴复古', '一曲狂歌，有百馀言，说尽一生。\n费十年灯火，读书读史，四方奔走，求利求名。\n蹭蹬归来，闭门独坐，赢得穷吟诗句清。\n夫诗者，皆吾侬平日，愁叹之声。\n空馀豪气峥嵘。\n安得良田二顷耕。\n向临邛涤器，可怜司马，成都卖卜，谁识君平。\n分则宜然，吾何敢怨，蝼蚁逍遥戴粒行。\n开怀抱，有青梅荐酒，绿树啼莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13269, '贺新郎', '戴复古', '说与黄花道。\n九秋深、三光五岳，气锺英表。\n金马玉堂真学士，蕴藉诗书奥妙。\n一一是、经纶才调。\n斟酌古今来活国，算忠言、谠论知多少。\n又入奏，金门晓。\n朝回问寝披萱草。\n对高堂长说，一片君恩难报。\n更待痴儿千载遇，膝下十分荣耀。\n趁绿鬓、朱颜不老。\n整顿乾坤济时了，奉板舆、拜国夫人号。\n可谓忠，可谓孝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13270, '贺新郎', '戴复古', '忆把金酒。\n叹别来、光阴荏苒，江湖宿留。\n世事不堪频着眼，赢得两眉长皱。\n但东望、故人翘首。\n木落山空天远大，送飞鸿、北去伤怀久。\n天下事，公知否。\n钱塘风月西湖柳。\n渡江来、百年机会，从前未有。\n唤起东山丘壑梦，莫惜风霜老手。\n要整顿、封疆如旧。\n早晚枢庭开幕府，是英雄、尽为公奔走。\n看金印，大如斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13271, '贺新郎', '戴复古', '百尺连云起。\n试登临、江山人物，一时俱伟。\n旁挹金陵龙虎势，京岘诸峰对峙。\n隐隐接、扬州歌吹。\n雪浪舞从三峡下，乍逢迎、海若谈秋水。\n形胜地，有如此。\n使君一世经纶志。\n把风斤月斧，来此等闲游戏。\n见说楼成无多日，大手一何容易。\n笑天下、纷纷血指。\n酝酿春风与和气，举长江、变作香醪美。\n人共乐，醉桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13272, '水调歌头', '戴复古', '轮奂半天上，胜概压南楼。\n筹边独坐，岂欲登览快双眸。\n浪说胸吞云梦，直把气吞残虏，西北望神州。\n百载一机会，人事恨悠悠。\n骑黄鹤，赋鹦鹉，谩风流。\n岳王祠畔，杨柳烟锁古今愁。\n整顿乾坤手段，指授英雄方略，雅志若为酬。\n杯酒不在手，双鬓恐惊秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13273, '满庭芳', '戴复古', '三日春光，群贤胜践，山阴何似山阳。\n鹅池墨妙，曲水记流觞。\n自许风流丘壑，何人共、击楫长江。\n新亭上，山河有异，举目恨堂堂。\n使君，经世志，十年边上，两鬓风霜。\n问池边杨柳，因甚凄凉。\n万树重新种了，株株在、桃李花傍。\n仍须待，剩栽兰芷，为国洗河湟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13274, '满庭芳', '戴复古', '赤壁矶头，临皋亭下，扁舟两度经过。\n江山如画，风月奈愁何。\n三国英雄安在，而今但、一目烟波。\n风流处，竹楼无恙，相对有东坡。\n登临，还自笑，狂游四海，一向忘家。\n算天寒路远，早早归呵。\n明日片帆东下，沧洲上、千里芦花。\n真堪爱，买鱼沽酒，到处听吴歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13275, '醉落魄・一斛珠', '戴复古', '龙山行乐。\n何如今日登黄鹤。\n风光政要人酬酢。\n欲赋归来，莫是渊明错。\n江山登览长如昨。\n飞鸿影里秋光薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13276, '柳梢青', '戴复古', '袖剑飞吟。\n洞庭青草，秋水深深。\n万顷波光，岳阳楼上，一快披襟。\n不须携酒登临。\n问有酒、何人共斟。\n变尽人间，君山一点，自古如今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13277, '锦帐春', '戴复古', '处处逢花，家家插柳。\n政寒食、清明时候。\n奉板舆行乐，使星随後。\n人间稀有。\n出郭寻仙，绣衣春昼。\n马上列、两行红袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13278, '行香子', '戴复古', '万石崔嵬，二水涟漪。\n此江山、天下之奇。\n太平气象，百姓熙熙。\n有文章公，经纶手，把州麾。\n满斟寿酒，笑拈梅枝。\n管年年、长见花时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13279, '鹊桥仙', '戴复古', '新荷池沼，绿槐庭院。\n檐外雨声初断。\n喧喧两部乱蛙鸣，怎得似、啼莺。\n风光流转。\n客游汗漫。\n莫问鬓丝长短。\n即时杯酒醉时歌，算省得、闲愁一半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13280, '木兰花慢', '戴复古', '莺啼啼不尽，任燕语、语难通。\n这一点闲愁，十年不断，恼乱春风。\n重来故人不见，但依然、杨柳小楼东。\n记得同题粉壁，而今壁破无踪。\n兰皋新涨绿溶溶。\n流恨落花红。\n念著破春衫，当时送别，灯下裁缝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13281, '洞仙歌', '戴复古', '卖花担上，菊蕊金初破。\n说着重阳怎虚过。\n看画城簇簇，酒肆歌楼，奈没个巧处，安排着我。\n家乡煞远哩，抵死思量，枉把眉头万千锁。\n一笑且开怀，小阁团栾，旋簇着、几般蔬果。\n把三杯两盏记时光，问有甚曲儿，好唱一个。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13282, '西江月', '戴复古', '宿酒才醒又醉，春霄欲雨还晴。\n柳边花底听莺声。\n白发莫教临镜。\n过隙光阴易去，浮云富贵难凭。\n但将一笑对公卿。\n我是无名百姓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13283, '西江月', '戴复古', '三过武昌台下，却逢三度重阳。\n菊花祗作旧时黄。\n白雪堆人头上。\n昨日将军亭馆，今朝陶令壶觞。\n醉来东望海茫茫。\n家近蓬莱方丈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13284, '贺新郎', '戴复古', '蜗角争多少。\n是英雄、割据乾坤，到头休了。\n一片泥涂荒草地，尽是鱼龙故道。\n新堤上、风涛难保。\n沧海桑田何时变，怕桑田、未变人先老。\n休为此，生烦恼。\n讼庭不许频频到。\n这官坊、翻来覆去，有何分晓。\n无诤人中为第一，长讼元非吉兆。\n但有恨、平章不早。\n尊酒唤回和气在，看从来、兄弟依然好。\n把前事，付一笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13285, '沁园春', '戴复古', '请赋林堂，林堂未成，吾何赋哉。\n想胸中丘壑，山中风月，亭台几所，花木千栽。\n应接光阴，品题胜概，须待堂成我再来。\n听分付，是经行去处，莫放苍苔。\n吾曹不堕尘埃。\n要胸次长随笑口开。\n任江湖浪迹，鸥盟雁序，功名到手，凤阁鸾台。\n它日相寻，有逾此约，酌水浮君三百杯。\n闻斯语，有冠山突兀，袍岭崔嵬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13286, '鹧鸪天', '戴复古', '圉圉洋洋各自由。\n或行或舞或沈浮。\n观鱼未必知鱼乐，政恐清波照白头。\n休结纲，莫垂钩。\n机心一露使鱼愁。\n终知不是池中物，掉尾江湖汗漫游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13287, '减字木兰花', '戴复古', '羊城旧路。\n檀板一声惊客去。\n不拟重来。\n白发飘飘上越台。\n故人居处。\n曲巷深深通竹所。\n问讯桃花。\n欲访刘郎不在家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13288, '减字木兰花', '戴复古', '天台狂客。\n醉里不知秋鬓白。\n应接风光。\n忆在江亭醉几场。\n吴姬劝酒。\n唱得廉颇能饭否。\n西雨东晴。\n人道无情又有情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13289, '减字木兰花', '戴复古', '阻风中酒。\n流落江湖成白首。\n历尽艰关。\n赢得虚名在世间。\n浩然归去。\n忆着石屏茅屋趣。\n想见山村。\n树有交柯犊有孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13290, '浣溪沙', '戴复古', '病起无聊倚绣床。\n玉容清瘦懒梳妆。\n水沈烟冷橘花香。\n说个话儿方有味，吃些酒子又何妨。\n一声啼断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13291, '清平乐', '戴复古', '醉狂痴作。\n误信青楼约。\n酒醒梅花吹画角。\n翻得一场寂寞。\n相如谩赋凌云。\n琴台不遇文君。\n江上琵琶旧曲，只堪分付商人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13292, '临江仙', '戴复古', '误入风尘门户，驱来花月楼台。\n樽前几度得徘徊。\n可怜容易别，不见牡丹开。\n莫恨银瓶酒尽，但将妾泪添杯。\n江头恰限北风回。\n再三相祝去，千万寄书来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13293, '鹊桥仙', '戴复古', '西山岩壑，东湖亭馆，尽是经行旧路。\n别时方见有荷花，还又见、梅花岁暮。\n宋家兄弟，黄家兄弟，一一烦君传语。\n相忘不寄一行书，元自有、不相忘处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13294, '祝英台近', '戴复古', '泛杭川，临尘水。\n几日共游戏。\n歌笑开怀，酒醒又还醉。\n奈何一但分携，连宵风雨，剪不断、客愁千里。\n水云际。\n遥望一片飞鸿，苦是失群地。\n满眼春风，管甚闲桃李。\n此行归老家山，相逢难又，但一味、相思而已。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13295, '大江西上曲・念奴娇', '戴复古', '大江西去，郁孤台八境，人间图画。\n地涌千峰摇翠浪，两派玉虹如泻。\n弹压江山，品题风月，四海今王谢。\n风流人物，如公一世雄也。\n一片忧国丹心，弹丝吹笛，未必能陶写。\n西北风尘方洞，宰相闲归绿野。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13296, '满江红', '戴复古', '太守风流，何人似、金华仙伯。\n试看取、珠篇玉句，银钩铁画。\n叶叶柳眉齐抹翠，梢梢花脸争匀白。\n比池塘、春草梦来诗，尤奇绝。\n胸中有，蛾眉月。\n笔头带，蓬□雪。\n笑归来万里，不登今阙。\n鹿瑞堂前冬日暖，螺山江上春波阔。\n但伤时、一念不能休，添华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13297, '望江南・忆江南', '戴复古', '壶山好，博古又通今。\n结屋三间藏万卷，挥毫一字直千金。\n四海有知音。\n门外路，咫尺是湖阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13298, '望江南・忆江南', '戴复古', '壶山好，胆气不妨粗。\n手奋空拳成活计，眼穿故纸下功夫。\n处世未全疏。\n生涯事，近日果何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13299, '望江南・忆江南', '戴复古', '壶山好，文字满胸中。\n诗律变成长庆体，歌词渐有稼轩风。\n最会说穷通。\n中年後，虽老未成翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13300, '望江南・忆江南', '戴复古', '壶山好，也解忆狂夫。\n转首便成千里别，经年不寄一行书。\n浑似不相疏。\n催归曲，一唱一愁予。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13301, '望江南・忆江南', '戴复古', '石屏老，家住海东云。\n本是寻常田舍子，如何呼唤作诗人。\n无益费精神。\n千首富，不救一生贫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13302, '望江南・忆江南', '戴复古', '石屏老，长忆少年游。\n自谓虎头须食肉，谁知猿臂不封侯。\n身世一虚舟。\n平生事，说着也堪羞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13303, '望江南・忆江南', '戴复古', '石屏老，悔不住山林。\n注定一生知有命，老来万事付无心。\n巧语不如喑。\n贫亦乐，莫负好光阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13304, '清平乐', '戴复古', '今朝欲去。\n忽有留人处。\n说与江头杨柳树。\n系我扁舟且住。\n十分酒兴诗肠。\n难禁冷落秋光。\n借取春风一笑，狂夫到老犹狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13305, '醉太平', '戴复古', '长亭短亭。\n春风酒醒。\n无端惹起离情。\n有黄鹂数声。\n芙蓉绣茵。\n江山画屏。\n梦中昨夜分明。\n悔先行一程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13306, '满庭芳', '戴复古', '草木生春，楼台不夜，团团月上云霄。\n太平官府，民物共逍遥。\n指点江梅一笑，几番负、雨秀风娇。\n今年好，花边把酒，歌舞醉元宵。\n风流，贤太守，青云志气，玉树丰标。\n是神仙班里，旧日王乔。\n出奉板舆行乐，金莲照、十里笙箫。\n收灯後，看看丹诏，催入圣明朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13307, '渔父・渔歌子', '戴复古', '渔父饮，不须钱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13308, '渔父・渔歌子', '戴复古', '渔父醉，钓竿闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13309, '渔父・渔歌子', '戴复古', '渔父醒，荻花洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13310, '渔父・渔歌子', '戴复古', '渔父笑，笑何人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13311, '沁园春', '戴复古', '访衡山之顶，雪鸿渺渺，湘江之上，梅竹娟娟。\n寄语波臣，传言鸥鹭，稳护渠侬书画船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13312, '祝英台近', '戴复古妻', '惜多才，怜薄命，无计可留汝。\n揉碎花笺，忍写断肠句。\n道傍杨柳依依，千丝万缕，抵不住、一分愁绪。\n如何诉。\n便教缘尽今生，此身已轻许。\n捉月盟言，不是梦中语。\n後回君若重来，不相忘处，把杯酒、浇奴坟土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13313, '玉楼春', '李子酉', '纱窗春睡朦胧著。\n相见尚怀相别恶。\n梦随城上角声残，泪逐楼前花片落。\n东风不解吹愁却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13314, '醉太平', '徐梦龙', '冰肌玉容。\n情真意浓。\n小楼几度春风。\n醉琉璃酒钟。\n关山万重。\n何时又逢。\n思量雨迹云踪。\n似襄王梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13315, '浣溪沙', '赵扩', '花似醺容上玉肌。\n方论时事却嫔妃。\n芳阴人醉漏声迟。\n珠箔半钩风乍暖，雕梁新语燕初飞。\n斜阳犹送水精卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13316, '西江月', '方信孺', '碧洞青崖著雨，红泉白石生寒。\n来十月九湖山。\n人笑元郎太漫。\n绝壑偏宜叠鼓，夕阳休唤归鞍。\n兹游未必胜骖鸾。\n聊作湖南公案。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13317, '失调名', '龚大明', '山居好。\n山居好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13318, '失调名', '龚大明', '山居好。\n山居好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13319, '失调名', '龚大明', '山居好。\n山居好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13320, '失调名', '龚大明', '山居好。\n山居好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13321, '失调名', '龚大明', '清高绝，雪崖翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13322, '西江月', '龚大明', '我本无为野客，飘飘浪迹人间。\n一时被命住名山。\n未免随机应变。\n识破尘劳扰扰，何如乐取清闲。\n流霞细酌咏诗篇。\n且与白云为伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13323, '水调歌头', '陈楠', '夺取天机妙，夜半看辰杓。\n一些珠露，阿谁运倒稻花头。\n便向此时采取，宛如碧莲合蕊，滴破玉池秋。\n万籁风初起，明月一沙鸥。\n紫河车，乘赤凤，入琼楼。\n谓之玉汞，与铅与土正相投。\n五气三花聚顶，吹著自然真火，炼得似红榴。\n十月胎仙出，雷电送金虬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13324, '鹊桥仙', '陈楠', '红莲含蕊，露珠凝碧，飞落华池滴滴。\n运归金鼎唤丁公，炼得似、一枚朱橘。\n三花喷火，五云拥月，上有金胎神室。\n洞房云雨正春风，十个月、胎仙了毕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13325, '真珠帘', '陈楠', '金丹大药人人有。\n要须是、心传口授。\n一片白龙肝，一盏醍醐酒。\n只为离无寻坎有。\n移却南宸回北斗。\n好笑。\n见金翁姹女，两个厮斗。\n些儿铅汞调匀，观汉月海潮，抽添火候。\n一箭透三关，方表神仙手。\n兔子方来乌处住，龟儿便把蛇吞了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13326, '望江南・忆江南', '陈楠', '黄中宝，须向胆中求。\n春气令人生万物，乾坤膝下与吾俦。\n百脉自通流。\n施造化，左右火双抽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13327, '望江南・忆江南', '陈楠', '玄珠降，丹窟在中宫。\n九候息调重九数，赤波或进太阳东。\n心肾遂交通。\n逢六变，重六息阴功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13328, '望江南・忆江南', '陈楠', '毛发薄，三转运行阳。\n胎色渐红阴渐缩，推移岁运助阳刚。\n育火养中央。\n成物象，五转辨微茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13329, '望江南・忆江南', '陈楠', '丹已返，四转运行阴。\n逢六闭藏阳户气，三关全透合丁壬。\n龟游任浮沉。\n时出入，无碍贯他心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13330, '望江南・忆江南', '陈楠', '珠自右，紫电入丹城。\n内养婴儿成赤象，时逢五转采阳精。\n火自水中生。\n烧鬼岳，紫电起峥嵘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13331, '望江南・忆江南', '陈楠', '日精满，阴魄化无形。\n每遇月圆开地户，神龟时饮碧瑶精。\n清洁复如冰。\n阳砂赤，阴粉色微青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13332, '望江南・忆江南', '陈楠', '形透日，七转任飞腾。\n幽静深岩图宴坐，息无来往气坚凝。\n却粒著其能。\n生成火，返本气澄清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13333, '望江南・忆江南', '陈楠', '内外变，八转始还元。\n地带长垂主坎户，周行胎息贯天门。\n太始道方存。\n纯一体，赤黑气常喷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13334, '失调名', '史弥巩', '羊左合人我。\n左既绝粮甘自饿。\n羊仕楚王官职大。\n依旧杀身蓬颗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13335, '水调歌头', '徐鹿卿', '廊庙补天手，夷夏想威名。\n上前张胆明目，倾倒汉公卿。\n二百年来章贡，前赵後萧相□，今古两豪英。\n四海望霖雨，可但总祥刑。\n自儿时，文字里，已心倾。\n魁躔邈在霄汉，薄宦偶趋承。\n山见崆峒秀丽，水见玉虹清绝，犹愿见先生。\n寄语二三子，洙泗在江城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13336, '酹江月・念奴娇', '徐鹿卿', '雪销平野，正云开天宇，灯辉花市。\n明灭吐吞无尽藏，巧斗飞桥激水。\n铁马响冰，牙旗穿夜，箫鼓声歌沸。\n丰年欢笑，酿成千里和气。\n相欢交□游嬉，卖薪买酒，歌舞升平里。\n记得前年随玉辇，吹下天香扑鼻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13337, '水调歌头', '徐鹿卿', '岭峤转和气，英挟新凉。\n登车搅辔慷慨，风采肃台纲。\n第一澄清官府，次第咨询民瘼，馀事到仓。\n谨勿养稂莠，莠盛稻苗伤。\n金芝秀，蒲涧碧，荔枝香。\n此中风味不恶，暂借使星光。\n毋薄炎荒瘴海，曾著广平李勉，归去□平章。\n唤起昔贤梦，千载续遗芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13338, '贺新郎', '徐鹿卿', '解组轻千里。\n趁朝来、风高气爽，波平如砥。\n试问馀恩深几许，江阔秋清无底。\n看两径、棠阴舞翠。\n明月归轻似叶，只梅花、香里诗千纸。\n端不愧，西江水。\n谪仙才气兰亭字。\n更清姿雅度，修竹长松标致。\n官职几人曾此过，萱草春风谁似。\n任彩服、蹁跹娱戏。\n去此云霄真一握，算令公、勋业浑馀事。\n中书考，从今始。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13339, '减字木兰花', '徐鹿卿', '狂吟江浦。\n不食人间烟火语。\n韦曲名家。\n也试河阳一县花。\n群仙推去。\n暂寄岭梅清绝处。\n笑俯清溪。\n只有清风明月知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13340, '减字木兰花', '徐鹿卿', '云横远浦。\n一段秋光烦著语。\n月下谁家。\n丹桂迎风一两花。\n双凫来去。\n不踏人间风日处。\n才入云溪。\n问我来时总不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13341, '酹江月・念奴娇', '徐鹿卿', '薰风有意，还年年吹下，九天纶绋。\n庾岭高哉知几仞，不隔清名突兀。\n明月扁舟，图书之外，所载无南物。\n襄公往矣，辽辽直到今日。\n南来北地开藩，甘棠好在，一夜春光入。\n父老欢迎相告语，依旧朱颜绿发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13342, '水调歌头', '徐鹿卿', '五剡乃脱选，通籍入金闺。\n祖宗立法初意，正欲猎英奇。\n近世流风薄矣，强者立跻霄汉，弱者困尘泥。\n流水伯牙操，底处有锺期。\n公为政，民不扰，吏无欺。\n春风桃李满县，当路几人知。\n五马宏开公道，一鹗首旌治最，迟乃速之基。\n不枉受人荐，更看荐人时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13343, '水调歌头', '徐鹿卿', '别驾映旋轸，父老绕称觥。\n西风底事于役，造物岂无情。\n知道神生崧岳，大庾岭边和气，未足助欢声。\n小试活人手，详谳命公行。\n赣滩石，青原雨，快阁晴。\n西江一带风物，尽把祝长生。\n福与此江无尽，寿与此江俱远，名与此江清。\n江水直到海，公亦上蓬瀛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13344, '汉宫春', '徐鹿卿', '庾岭梅花，到江空岁晚，始放南枝。\n岂徒冰雪蹊径，不受侵欺。\n孤高自负，尽炎凉、变态无期。\n便瘴雨、蛮烟如许，淡妆也不随时。\n未肯移根上苑，且竹边院落，月下园篱。\n除却西湖句子，此後无诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13345, '汉宫春', '徐鹿卿', '吏隐南昌，问盘根几世，长子孙枝。\n仙风道骨如此，信不吾欺。\n素姿倾国，□难昏、坐觉愆期。\n算好与、水仙作配，又还恨不同时。\n岁晚寻盟有几，早兰辞湘浦，竹谢东篱。\n自向月中弄影，雪里评诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13346, '满江红', '徐鹿卿', '斗大横江，旧曾著、周程夫子。\n谭道处，疏梅迎笑，双松延翠。\n百载高风勤景仰，数椽老屋重经始。\n更大书、留与後人看，公归矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13347, '木兰花・玉楼春', '邹应龙', '吾家二老。\n前有高平生癸卯。\n若到今辰。\n讵止荣华九十龄。\n共惟伯母。\n九十新年还又五。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13348, '鹧鸪天', '邹应龙', '九十吾家两寿星。\n今夫人赛昔夫人。\n百年转眼新开帙，十月循环小有春。\n生日到，转精神。\n目光如镜步如云。\n年年长侍华堂宴，子子孙孙孙又孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13349, '鹧鸪天', '邹应龙', '寿母开年九十三。\n佳辰就养大江南。\n缇屏晃耀新宁国，绣斧斓斑老朴庵。\n倾玉，擘黄柑。\n两孙垂绶碧於蓝。\n便当刊颂崆峒顶，留与千年作美谈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13350, '鹧鸪天', '邹应龙', '帝里风光别是天。\n花如锦绣柳如烟。\n还逢令节春三二，又庆慈闱岁八千。\n斟寿，列长筵。\n子孙何以咏高年。\n各裒千首西湖什，一度生朝献一篇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13351, '鹧鸪天', '邹应龙', '彩结轻车五马随。\n倾城争出看花枝。\n笙歌十里岩前去，灯火千门月下归。\n莲炬引，老莱衣。\n蛾眉无数卷帘窥。\n谁知万里逢灯夕，却胜寻常三五时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13352, '卜算子', '邹应龙', '满二望三时，春景方明媚。\n又见蟠桃结子来，王母初筵启。\n无数桂林山，不尽漓江水。\n总入今朝祝寿杯，永保千千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13353, '感皇恩', '邹应博', '觅得个州儿，稍供彩戏。\n多谢天公为排备。\n一轮明月，酝作清廉滋味。\n倾入寿杯里，何妨醉。\n我有禄书，呈母年万计。\n八十三那里暨。\n便和儿算，恰一百四十地。\n这九千馀岁，长随侍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13354, '鹧鸪天', '邹应博', '天遣丰年祝母龄。\n人人安业即安亲。\n探支十日新阳福，来献千秋古佛身。\n儿捧盏，妇倾瓶。\n更欣筵上有嘉宾。\n紫驼出釜双台馈，玉节升堂两使星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13355, '鹧鸪天', '邹应博', '诸佛林中女寿星。\n千祥百福产心田。\n喜归王母初生地，满劝麻姑不老泉。\n吾梦佛，半千员。\n一年一佛护庭萱。\n数过九十从头数，四百馀零一十年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13356, '浪淘沙', '黄某', '八十加三迎九十，还似婴童。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13357, '醉落魄・一斛珠', '叶秀发', '胸襟洒落。\n光风霁月澄寥廓。\n生平素志惟丘壑。\n随分田园，花木四时乐。\n儿孙不用千金橐。\n吾家自有诗书粕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13358, '贺新郎', '李刘', '鹄立通明殿。\n又重逢、揆余初度，梦庚华旦。\n不学花奴簪红槿，且看秋香宜晚。\n任甲子、从新重换。\n天欲东都修车马，故降神生甫维周翰。\n歌崧岳，咏江汉。\n明堂朝罢夷琛献。\n引星辰、万人共听，风尘长算。\n清昼山东诸将捷，席卷黄河两岸。\n问谁在、玉皇香案。\n师保万民功业别，向西京、原庙行圭瓒。\n定郏，卜涧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13359, '鱼游春水', '李刘', '湖南三千里。\n百万人家争送喜。\n元戎初度，和气水流山峙。\n荆楚中间寿域开，翼轸傍边台躔起。\n崧岳降神，维箕骑尾。\n见说君王注倚。\n问舟楫、盐梅谁是。\n国人争望周公，东归几几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13360, '水调歌头', '李刘', '万里碧鸡使，叱驭问邛崃。\n枪旗有烨，川秦奔走送龙媒。\n好在灵均初度，唤起长庚佳梦，霜月照金。\n寿似武侯柏，香在草堂梅。\n舞娉婷，斟凿落，沃崔嵬。\n神尧孙子，向来八九上三台。\n挂了桑弧蓬矢，便恐彤弓瓒，分宝下天阶。\n归赋梁园雪，试唤长卿来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13361, '酹江月・念奴娇', '李刘', '汉庭用老，想君王也忆、潜郎白首。\n底事煌煌金玉节，奔走天涯许久。\n江右风流，湖南清绝，更借诗翁手。\n明年七十，人间此事希有。\n固是守得堂间，鲂斋亭下，要称归来柳。\n上恐夜深□贾傅，便有锋车迎候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13362, '满庭芳', '李刘', '郑履声传，倪经业绍，半千贤运重开。\n妙年阔步，高折桂枝回。\n卿月郎星历遍，都贪把、符竹南来。\n棠阴永，仍持玉节，臬事副钦哉。\n吾生，真幸会，旧家桃李，曾费栽培。\n更春风次第，吹到寒。\n遥望绂麟祥旦，霄躔邈、阻奉琅杯。\n谁知道，清源路远，直上即蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13363, '生查子', '李刘', '湘江贯地维，衡岳生人杰。\n谁遣益州星，暂伴峨眉月。\n初度庆今朝，绣斧双龙节。\n为国罩嘉鱼，趣觐黄金阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13364, '浣溪沙', '李刘', '濯锦江边玉树明。\n碧油幢里彩衣荣。\n当年此日下长庚。\n细酌成都千岁酒，闲看谷一阳春。\n归听云母隔屏声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13365, '朝中措', '李刘', '我生辰在斗牛中。\n井路有何功。\n运转峨眉山月，按行雪界天风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13366, '水调歌头', '李刘', '端正九秋月，今夜始生明。\n扬辉毓秀，飘然海上跨长鲸。\n认得灵均初度，直用望舒为御，重耀紫枢庭。\n何事乘槎使，尚藉执卿。\n合东西，瞻使节，镜中行。\n腾腾渐渐，绕枝乌鹊不须惊。\n太白擒胡了未，即墨降城安否，玉斧仗修成。\n圆却山河影，捣药兔长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13367, '鹧鸪天', '李刘', '恰则重阳信宿前。\n菊潭先寿濮阳仙。\n暂陪明月清风夜，共醉孤云落照边。\n群玉府，紫微天。\n看看东壁二星连。\n月中斫桂吴夫子，定是长生不记年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13368, '生查子', '李刘', '万里彩衣远，旬日黄花後。\n蓬矢纪佳辰，莲幕翻新奏。\n更看桂枝香，归献灵椿寿。\n同对小蟠桃，共醉长生酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13369, '念奴娇', '郑清之', '楚天霜晓，看老来秋圃，寒花犹在。\n金阙栽培端正色，全胜东篱风采。\n雅韵清虚，幽香淡泊，惟有陶家爱。\n由他尘世，落红愁处如海。\n多少风雨飘摇，夫君何素，晚节应难改。\n休道三闾曾旧识，轻把木兰相对。\n延桂同盟，索梅为友，不复娇春态。\n年年秋後，笑观芳草萧艾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13370, '失调名', '陈鹄', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13371, '如梦令', '李仲虺', '门外数峰围绕。\n帖石路儿弯小。\n花老不禁风，委地乱红多少。\n人俏。\n人俏。\n隔叶数声啼鸟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13372, '眼儿媚', '黄简', '画楼濒水翠梧阴。\n清夜理瑶琴。\n打窗风雨，逼帘烟月，种种关心。\n当时不道春无价，幽梦费重寻。\n难忘最是，鲛绡晕满，锦香沉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13373, '柳梢青', '黄简', '病酒心情。\n唤愁无限，可奈流莺。\n又是一年，花惊寒食，柳认清明。\n天涯翠层层。\n是多少、长亭短亭。\n倦倚东风，只凭好梦，飞到银屏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13374, '玉楼春', '黄简', '龟纹晓扇堆云母。\n日上彩阑新过雨。\n眉心犹带宝觥酲，耳性已通银字谱。\n密奁彩索看看午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13375, '鹧鸪天', '陈耆卿', '莫惜花前泥酒壶。\n沙场千步锦平铺。\n将军闲试临边手，按出吴宫小阵图。\n清露里，晓霜馀。\n娇红淡白更怜渠。\n人间落木萧萧下，独倚秋江画不如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13376, '鹧鸪天', '陈耆卿', '艳朵珍丛间舞衣。\n蹴球场外打红围。\n小舆穿入花深处，且住簪花醉一卮。\n秋欲尽，最怜伊。\n江梅未破菊离披。\n情知不与韶华竞，回首西风怨阿谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13377, '玉漏迟', '林表民', '并湖游冶路。\n垂堤万柳，麴尘笼雾。\n草色将春，离思暗伤南浦。\n旧日坊陌，尚想得、画楼窗户。\n成远阻。\n凤笺空寄，燕梁何许。\n凄凉瘦损文园，记翠管联吟，玉壶通语。\n事逐征鸿，几度悲欢休数。\n莺醉乱花深里，悄难替、愁人分诉。\n空院宇。\n东风晚来吹雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13378, '渔父词・渔父', '薛师石', '十载江湖不上船。\n卷蓬高卧月明天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13379, '渔父词・渔父', '薛师石', '邻家船上小姑儿。\n相问如何是别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13380, '渔父词・渔父', '薛师石', '平明雾霭雨初晴。\n儿子敲针作钓成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13381, '渔父词・渔父', '薛师石', '船系兰芷长鲈。\n曲袷方袍忽访吾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13382, '渔父词・渔父', '薛师石', '春融水暖百花开。\n独棹扁舟过钓台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13383, '渔父词・渔父', '薛师石', '夜来采石渡头眠。\n月下相逢李谪仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13384, '渔父词・渔父', '薛师石', '莫论轻重钓竿头。\n住得船归即便休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13385, '绮罗香', '史达祖', '做冷欺花，将烟困柳，千里偷催春暮。\n尽日冥迷，愁里欲飞还住。\n惊粉重、蝶宿西园，喜泥润、燕归南浦。\n最妨它、佳约风流，钿车不到杜陵路。\n沈沈江上望极，还被春潮晚急，难寻官渡。\n隐约遥峰，和泪谢娘眉妩。\n临断岸、新绿生时，是落红、带愁流处。\n记当日、门掩梨花，翦灯深夜语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13386, '双双燕', '史达祖', '过春社了，度帘幕中间，去年尘冷。\n差池欲住，试入旧巢相并。\n还相雕梁藻井。\n又软语、商量不定。\n飘然快拂花梢，翠尾分开红影。\n芳径。\n芹泥雨润。\n爱贴地争飞，竞夸轻俊。\n红楼归晚，看足柳昏花暝。\n应自栖香正稳。\n便忘了、天涯芳信。\n愁损翠黛双蛾，日日画阑独凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13387, '阳春曲・阳春', '史达祖', '杏花烟，梨花月，谁与晕开春色。\n坊巷晓，东风断、旧火销处近寒食。\n少年踪迹。\n愁暗隔、水南山北。\n还是宝络雕鞍，被莺声、唤来香陌。\n记飞盖西园，寒犹凝结。\n惊醉耳、谁家夜笛。\n灯前重帘不挂，华裾、粉泪曾拭。\n如今故里信息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13388, '海棠春令・海棠春', '史达祖', '似红如白含芳意。\n锦宫外、烟轻雨细。\n燕子不知愁，惊堕黄昏泪。\n烛花偏在红帘底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13389, '夜行船', '史达祖', '不翦春衫愁意态。\n过收灯、有些寒在。\n小雨空帘，无人深巷，已早杏花先卖。\n白发潘郎宽沈带。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13390, '东风第一枝', '史达祖', '巧沁兰心，偷黏草甲，东风欲障新暖。\n谩凝碧瓦难留，信知暮寒轻浅。\n行天入镜，做弄出、轻松纤软。\n料故园、不卷重帘，误了乍来双燕。\n青未了、柳回白眼。\n红欲断、杏开素面。\n旧游忆著山阴，厚盟遂妨上苑。\n寒炉重暖，便放慢春衫针线。\n恐凤靴、挑菜归来，万一灞桥相见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13391, '东风第一枝', '史达祖', '草脚愁苏，花心梦醒，鞭香拂散牛土。\n旧歌空忆珠帘，彩笔倦题绣户。\n黏鸡贴燕，想立断、东风来处。\n暗惹起、一掬相思，乱若翠盘红缕。\n今夜觅、梦池秀句。\n明日动、探花芳绪。\n寄声沽酒人家，预约俊，游伴侣。\n怜它梅柳，乍忍俊、天街酥雨。\n待过了一月灯期，日日醉扶归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13392, '东风第一枝', '史达祖', '酒馆歌云，灯街舞绣，笑声喧似箫鼓。\n太平京国多欢，大绮罗几处。\n东风不动，照花影、一天春聚。\n耀翠光、金缕相交，苒苒细吹香雾。\n羞醉玉、少年丰度。\n怀艳雪、旧家伴侣。\n闭门明月关心，倚窗小梅索句。\n吟情欲断，念娇俊、知人无据。\n想袖寒、珠络藏香，夜久带愁归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13393, '玉楼春', '史达祖', '游人等得春晴也。\n处处旗亭堪系马。\n雨前杏尚娉婷，风後残梅无顾藉。\n忌拈针线还逢社。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13394, '玉楼春', '史达祖', '玉容寂寞谁为主。\n寒食心情愁几许。\n前身清澹似梅妆，遥夜依微留月住。\n香迷胡蝶飞时路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13395, '喜迁莺', '史达祖', '月波疑滴。\n望玉壶天近，了无尘隔。\n翠眼圈花，冰丝织练，黄道宝光相直。\n自怜诗酒瘦，难应接、许多春色。\n最无赖，是随香趁烛，曾伴狂客。\n踪迹。\n谩记忆。\n老了杜郎，忍听东风笛。\n柳院灯疏，梅厅雪在，谁与细倾春碧。\n旧情拘未定，犹自学、当年游历。\n怕万一，误玉人、夜寒帘隙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13396, '万年欢', '史达祖', '两袖梅风，谢桥边、岸痕犹带阴雪。\n过了匆匆灯市，草根青发。\n燕子春愁未醒，误几处、芳音辽绝。\n烟溪上、采绿人归，定应愁沁花骨。\n非干厚情易歇。\n奈燕台句老，难道离别。\n小径吹衣，曾记故里风物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13397, '阮郎归', '史达祖', '龙香吹袖白藤鞭。\n帽檐冲柳烟。\n一春几度画桥边。\n东风听管弦。\n花活计，酒因缘。\n从人嘲少年。\n真须吟就绿杨篇。\n湾头寄小怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13398, '阮郎归', '史达祖', '旧时明月旧时身。\n旧时梅萼新。\n旧时月底似梅人。\n梅春人不春。\n香入梦，粉成尘。\n情多多断魂。\n芙蓉孔雀夜温温。\n愁痕即泪痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13399, '眼儿媚', '史达祖', '潘郎心老不成春。\n风味隔花尘。\n帘波浸笋，窗纱分柳，还过天津。\n近时无觅湘云处，不记是行人。\n楼高望远，应将秦镜，多照施颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13400, '眼儿媚', '史达祖', '儿家七十二鸳鸯。\n珠佩锁瑶箱。\n期花等月，秦台吹玉，贾袖传香。\n十年白玉堂前见，直是翦柔肠。\n将愁去也，不成今世，终误王昌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13401, '忆瑶姬', '史达祖', '娇月笼烟，下楚领、香分两朵湘云。\n花房渐密时，弄杏笺初会，歌里殷勤。\n沈沈夜久西窗，屡隔兰灯幔影昏。\n自彩鸾、飞入芳巢，绣屏罗荐粉光新。\n十年未始轻分。\n念此飞花，可怜柔脆销春。\n空馀双泪眼，到旧家时郎谩染愁巾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13402, '南歌子', '史达祖', '采绿随双桨，看山藉一筇。\n关南桃树几番红。\n昨夜诗情频在、雨声中。\n花径无云隔，苔垣只梦通。\n旧欢一饷可过从。\n试觅鸳鸯新杏、简春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13403, '风流子', '史达祖', '红楼横落日，萧郎去、几度碧云飞。\n记窗眼递香，玉台妆罢，马蹄敲月，沙路人归。\n如今但，一莺通信息，双燕说相思。\n入耳旧歌，怕听琴缕，断肠新句，羞染乌丝。\n相逢南溪上，桃花嫩、娇样浅澹罗衣。\n恰是怨深腮赤，愁重声迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13404, '风流子', '史达祖', '飞琼神仙客，因游戏、误落古桃源。\n藉吟笺赋笔，试融春恨，舞裙歌扇，聊应尘缘。\n遣人怨，乱云天一角，弱水路三千。\n还因秀句，意流江外，便随轻梦，身堕愁边。\n风流休相误，寻芳纵来晚，尚有它年。\n只为赋情不浅，弹泪风前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13405, '金盏子', '史达祖', '奖绿催红，仰一番膏雨，始张春色。\n未踏画桥烟，江南岸、应是草花密。\n尚忆溅裙苹溪，觉诗愁相觅。\n光风外，除是倩莺烦燕，谩通消息。\n梨花夜来白。\n相思梦、空阑一林月。\n深深柳枝巷陌，难重遇、弓弯两袖云碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13406, '杏花天', '史达祖', '软波拖碧蒲芽短。\n画桥外、花晴柳暖。\n今年自是清明晚。\n便觉芳情较懒。\n春衫瘦、东风翦翦。\n过花坞、香吹醉面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13407, '杏花天', '史达祖', '古城官道花如霰。\n便恰限、花间再见。\n双眉最现愁深浅。\n隔雨春山两点。\n回头但、垂杨带苑。\n想今夜、铜驼梦远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13408, '杏花天', '史达祖', '细风微月垂杨院。\n记年少、春愁一点。\n栖莺未觉花梢颤。\n踏损残红几片。\n长安共、日边近远。\n况老去，芳情渐减。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13409, '杏花天', '史达祖', '扇香曾靠腮边粉。\n旧尘埋、月轮有晕。\n南风未似愁来近。\n前事临窗隐隐。\n凉花畔、云歌露饮。\n梦断了、终难再问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13410, '三姝媚', '史达祖', '烟光摇缥瓦。\n望晴檐多风，柳花如洒。\n锦瑟横床，想泪痕尘影，凤弦常下。\n倦出犀帷，频梦见、王孙骄马。\n讳道相思，偷理绡裙，自惊腰衩。\n惆怅南楼遥夜。\n记翠箔张灯，枕肩歌罢。\n又入铜驼，遍旧家门巷，首询声价。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13411, '寿楼春', '史达祖', '裁春衫寻芳。\n记金刀素手，同在晴窗。\n几度因风残絮，照花斜阳。\n谁念我今无肠。\n自少年、消磨疏狂。\n但听雨挑灯，床病酒，多梦睡时妆。\n飞花去，良宵长。\n有丝阑旧曲，金谱新腔。\n最恨湘云人散，楚兰魂伤。\n身是客，愁为乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13412, '于飞乐', '史达祖', '绮翼，问谁常借春陂。\n生愁近渚风微。\n紫山深，金殿暖，日暮同归。\n白头相守，情虽定、事却难期。\n带恨飞来，烟埋秦草，年年枉梦红衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13413, '南浦', '史达祖', '玉树晓飞香，待倩它、和愁点破妆镜。\n轻嫩一天春，平白地、都护雨昏烟暝。\n幽花露湿，定应独把阑干凭。\n谢屐未蜡，安排共文，重游芳径。\n年来梦里扬州，怕事随歌残，情趁云冷。\n娇眄隔东风，无人会、莺燕暗中心性。\n深盟纵约，尽同晴雨全无定。\n海棠梦在，相思过西园，秋千红影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13414, '探芳信', '史达祖', '谢池晓。\n被酒滞春眠，诗萦芳草。\n正一阶梅粉，都未有人扫。\n细禽啼处东风软，嫩约关心早。\n未烧灯，怕有残寒，故园稀到。\n说道试妆了。\n也为我相思，占它怀抱。\n静数窗棂，最欢听鹊声好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13415, '祝英台近', '史达祖', '柳枝愁，桃叶恨，前事怕重记。\n红药开时，新梦又溱洧。\n此情老去须休，春风多事。\n便老去、越难回避。\n阻幽会。\n应念偷翦酴，柔条暗萦系。\n节物移人，春暮更憔悴。\n可堪竹院题诗，藓阶听雨，寸心外、安愁无地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13416, '祝英台近', '史达祖', '绾流苏，垂锦绶。\n烟外红尘逗。\n莫倚莓墙，花气酽如酒。\n便愁醺醉青虬，蜿蜿无力，戏穿碎、一屏新绣。\n谩怀旧。\n如今姚魏俱无，风标较消瘦。\n露点摇香，前度翦花手。\n见郎和笑拖裙，匆匆欲去，蓦忽地、留芳袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13417, '祝英台近', '史达祖', '落花深，芳草暗，春到断肠处。\n金勒骄风，欲过大堤去。\n翠楼葛领西边，恰如曾约，画阑映、一枝琼树。\n正凝伫。\n芳意欺月矜春，浑欲便偷许。\n多少莺声，不敢寄愁与。\n谢郎日日西湖，如今归後，几时见、倚帘吹絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13418, '钗头凤・撷芳词', '史达祖', '春愁远。\n春梦乱。\n凤钗一股轻尘满。\n江烟白。\n江波碧。\n柳户清明，燕帘寒食。\n忆忆忆。\n莺声晓，箫声短。\n落花不许春拘管。\n新相识。\n休相失。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13419, '西江月', '史达祖', '西月澹窥楼角，东风暗落檐牙。\n一灯初见影窗纱。\n又是重帘不下。\n幽思屡随芳草，闲愁多似杨花。\n杨花芳草遍天涯。\n绣被春寒夜夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13420, '西江月', '史达祖', '三十六宫月冷，百单八颗香悬。\n只宜结赠散花天。\n金粟分身显现。\n指嫩香随甲影，颈寒秋入云边。\n未忘灵鹫旧因缘。\n赢得今生圆转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13421, '西江月', '史达祖', '一片秋香世界，几层凉雨阑干。\n青天不惜烂银盘。\n借与先生为劝。\n酒唤诗来酒外，人言身在人间。\n如何得似碧云闲。\n且共嫦娥相伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13422, '西江月', '史达祖', '裙摺绿罗芳草，冠梁白玉芙蓉。\n次公筵上见山公。\n红绶欲衔双凤。\n已向冰奁约月，更来玉界乘风。\n凌波袜冷一尊同。\n莫负彩舟凉梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13423, '庆清朝', '史达祖', '坠絮孳萍，狂鞭孕竹，偷移红紫池亭。\n馀花未落，似供残蝶经营。\n赋得送春诗了，夏帷撺断绿阴成。\n桑麻外，乳鸠稚燕，别样芳情。\n荀令旧香易冷，叹俊游疏懒，枉自销凝。\n尘侵谢屐，幽径斑驳苔生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13424, '桃源忆故人', '史达祖', '双鸳蹙月天津近。\n归後嫩情常剩。\n灯市一年愁凝。\n心共梅花冷。\n网尘洞户春沈静。\n衰尽冶游情性。\n羞见素娥娇影。\n明似愁鸾镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13425, '桃源忆故人', '史达祖', '明霞烘透春机杼。\n春在明霞多处。\n我是有诗渔父。\n一梦秦天古。\n柳枝巷陌深朱户。\n墙外风流一树。\n十五年来凝伫。\n弹尽胭脂雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13426, '花心动', '史达祖', '风约帘波，锦机寒、难遮海棠烟雨。\n夜酒未苏，春枕犹，曾是误成歌舞。\n半褰薇帐云头散，奈愁味、不随香去。\n尽沈静、文园更渴，有人知否。\n懒记温柔旧处。\n偏只怕、临风见他桃树。\n绣户锁尘，锦瑟空弦，无复画眉心绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13427, '解佩令', '史达祖', '人行花坞。\n衣沾香雾。\n有新词、逢春分付。\n屡欲传情，奈燕子、不曾飞去。\n倚珠帘、咏郎秀句。\n相思一度。\n愁一度。\n最难忘、遮灯私语。\n澹月梨花，借梦来、花边廊庑。\n指春衫、泪曾溅处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13428, '菩萨蛮', '史达祖', '梨花不碍东城月。\n月明照见空阑雪。\n雪底夜香微。\n褰帘拜月归。\n锦衾幽梦短。\n明月南堂宴。\n宴罢小楼台。\n春风来不来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13429, '菩萨蛮', '史达祖', '唐昌观里东风软。\n齐王宫外芳名远。\n桂子典刑边。\n梅花伯仲间。\n笼茸锼暖雪。\n琐细雕晴月。\n谁驾七香车。\n绿云飞玉沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13430, '菩萨蛮', '史达祖', '广寒夜捣玄霜细。\n玉龙睡重痴涎坠。\n斗合一团娇。\n偎人暖欲消。\n心情虽软弱。\n也要人抟搦。\n宝扇莫惊秋。\n班姬应更愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13431, '贺新郎', '史达祖', '花落台池静。\n自春衫闲来，老了旧香荀令。\n酒既相违诗亦可，此外云沈梦冷。\n又催唤、官河兰艇。\n匝岸烟霏吹不断，望楼阴、欲带朱桥影。\n和草色，入轻暝。\n裙边竹叶多应剩。\n怪南溪见後，无个再来芳信。\n胡蝶一生花里活，难制窃香心性。\n便有段、新愁随定。\n落日年年宫树绿，堕新声、玉笛西风劲。\n谁伴我，月中听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13432, '贺新郎', '史达祖', '绿障南城树。\n有高楼衔城，楼下芰荷无数。\n客自倚阑鱼亦避，恐是持竿伴侣。\n对别浦、扁舟容与。\n杨柳影间风不到，倩诗情、飞过鸳鸯浦。\n人正在，断肠处。\n两山带著冥冥雨。\n想低帘短额，谁见恨时眉妩。\n别为清尊眠锦瑟，怕被歌留愁住。\n便欲趁、采莲归去。\n前度刘郎虽老矣，奈年来、犹道多情句。\n应笑煞，旧鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13433, '贺新郎', '史达祖', '鹊翅西风浅。\n乍疏云垂幔，近月银钩将卷。\n天上应闲支机石，前度芳盟谁践。\n便好织、回文锦献。\n乞得欢今夜里，算盈盈、一水曾何远。\n宁不会，暗相见。\n彩楼吹断闲针线。\n想幽情嫩约，别有藓庭花院。\n青鸟沈沈音尘绝，烟锁蓬莱宫殿。\n渐木杪、参旗西转。\n不怕天孙成间阻，怕人间、薄幸心肠变。\n又学得，易分散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13434, '贺新郎', '史达祖', '同住西山下。\n是天地中间，爱酒能诗之社。\n船向少陵佳处放，尘世必无知者。\n暑不到、云宫风榭。\n楚竹忽然呼月上，被东西，几叶云萦惹。\n云散去，笑声罢。\n清尊莫为婵娟泻。\n为狂吟醉舞，毋失晋人风雅。\n踏碎桥边杨柳影，不听渔樵闲话。\n更欲举、空杯相谢。\n北斗以南如此几，想吾曹、便是神仙也，问今夜，是何夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13435, '贺新郎', '史达祖', '西子相思切。\n委萧萧、风裳水佩，照人清越。\n山染蛾眉波曼，聊可与之娱悦。\n便莫赋、湘妃罗袜。\n怕见绿荷相倚恨，恨白鸥、占了凉波阔。\n拣凉处，放船歇。\n道人不是尘埃物。\n纵狂吟魂魄，吹乱一巾凉发。\n不觉引杯浇肺渴，正要清歌骇发。\n更坐上、其人冰雪。\n截取断虹堪作钓，待玉奁、今夜来时节。\n也胜钓，石城月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13436, '夜合花', '史达祖', '冷截龙腰，偷拿鸾爪，楚山长锁秋云。\n梅华未落，年年怨入江城。\n千嶂碧，一声清。\n杜人间、儿女箫笙。\n共凄凉处，琵琶湓浦，长啸苏门。\n当时低度西邻。\n天澹阑干欲暮，曾赋高情。\n子期老矣，不堪带酒重听。\n纤手静，七星明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13437, '夜合花', '史达祖', '柳锁莺魂，花翻蝶梦，自知愁染潘郎。\n轻衫未揽，犹将泪点偷藏。\n念前事，怯流光。\n早春窥、酥雨池塘。\n向销凝里，梅开半面，情满徐妆。\n风丝一寸柔肠。\n曾在歌边惹恨，烛底萦香。\n芳机瑞锦，如何未织鸳鸯。\n人扶醉，月依墙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13438, '留春令', '史达祖', '秀肌丰靥，韵多香足，绿匀红注。\n翦取东风入金盘，断不买、临邛赋。\n宫锦机中春富裕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13439, '留春令', '史达祖', '故人溪上，挂愁无奈，烟梢月树。\n一涓春水点黄昏，便没顿、相思处。\n曾把芳心深相许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13440, '瑞鹤仙', '史达祖', '杏烟娇湿鬓。\n过杜若汀洲，楚衣香润。\n回头翠楼近。\n指鸳鸯沙上，暗藏春恨。\n归鞭隐隐。\n便不念、芳盟未稳。\n自箫声、吹落云东，再数故园花信。\n谁问。\n听歌窗罅，倚月钩阑，旧家轻俊。\n芳心一寸。\n相思後，总灰尽。\n奈春风多事，吹花摇柳，也把幽情唤醒。\n对南溪、桃萼翻红，又成瘦损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13441, '瑞鹤仙', '史达祖', '馆娃春睡起。\n为发妆酒暖，脸霞轻腻。\n冰霜一生里。\n厌从来冷澹，粉腮重洗。\n胭脂暗试。\n便无限、芳气味。\n向黄昏、竹外寒深，醉里为谁偷倚。\n娇媚。\n春风模样，霜月心肠，瘦来肌体。\n孤香细细。\n吹梦到，杏花底。\n被高楼横管，一声惊断，却对南枝洒泪。\n谩相思、桃叶桃根，旧家姊妹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13442, '点绛唇', '史达祖', '花落苔香，断无人肯行。\n晚风翻绣。\n吹醒东窗酒。\n犹卧氍毹，明月知人瘦。\n香消後。\n乱愁依旧。\n开□胡酥手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13443, '点绛唇', '史达祖', '山月随人，翠苹分破秋山影。\n钓船归尽。\n桥外诗心迥。\n多少荷花，不盖鸳鸯冷。\n西风定。\n可怜潘鬓。\n偏浸秦台镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13444, '青玉案', '史达祖', '蕙花老尽离骚句。\n绿染遍、江头树。\n日午酒消听骤雨。\n青榆钱小，碧苔钱古。\n难买东君住。\n官河不碍遗鞭路。\n被芳草、将愁去。\n多定红楼帘影暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13445, '浣溪沙', '史达祖', '不见东山月露香。\n姚家借得小芬芳。\n乱莺随趁过宫墙。\n香珀碾花娇有意，绿茸绣叶涩无光。\n御封春酒几时尝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13446, '蝶恋花', '史达祖', '二月东风吹客袂。\n苏小门前，杨柳如腰细。\n胡蝶识人游冶地。\n旧曾来处花开未。\n几夜湖山生梦寐。\n评泊寻芳，只怕春寒里。\n令岁清明逢上已。\n相思先到溅裙水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13447, '临江仙', '史达祖', '草脚青回细腻，柳梢绿转条苗。\n旧游重到合魂销。\n棹横春水渡，人凭赤阑桥。\n归梦有时曾见，新愁未肯相饶。\n酒香红被夜迢迢。\n莫交无用月，来照可怜宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13448, '临江仙', '史达祖', '倦客如今老矣，旧时不奈春何。\n几曾湖上不经过。\n看花南陌醉，驻马翠楼歌。\n远眼愁随芳草，湘裙忆著春罗。\n枉教装得旧时多。\n向来箫鼓地，犹见柳婆姿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13449, '临江仙', '史达祖', '愁与西风应有约，年年同赴清秋。\n旧游帘幕记扬州。\n一灯人著梦，双燕月当楼。\n罗带鸳鸯尘暗澹，更须整顿风流。\n天涯万一见温柔。\n瘦应因此瘦，羞亦为郎羞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13450, '汉宫春', '史达祖', '花隔东垣，咏燕台秀句，结带谋欢。\n匆匆旧盟，有限飞梦重关。\n南塘夜月，照湘琴、别鹤孤鸾。\n天便遣、清愁易长，春衣常恁香寒。\n唐昌故宫何许，顿翦霞裁雾，摆落尘缘。\n一声步虚，婉婉云驻天坛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13451, '兰陵王', '史达祖', '汉江侧。\n月弄仙人佩色。\n含情久，摇曳楚衣，天水空染娇碧。\n文漪簟影织。\n凉骨时将粉饰。\n谁曾见，罗袜去时，点点波间冷云积。\n相思旧飞。\n谩想像风裳，追恨瑶席。\n涉江几度和愁摘。\n记雪映双腕，刺萦丝缕，分开绿盖素袂湿。\n放新句吹入。\n寂寂。\n意犹昔。\n念净社因缘，天许相觅。\n飘萧羽扇摇团白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13452, '风入松', '史达祖', '素馨萼太寒生。\n多翦春冰。\n夜深绿雾侵凉月，照晶晶、花叶分明。\n人卧碧纱净，香吹雪练衣轻。\n频伽衔得堕南薰。\n不受纤尘。\n若随荔子华清去，定空埋、身外芳名。\n借重玉炉沈炷，起予石鼎汤声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13453, '隔浦莲・隔浦莲近拍', '史达祖', '红尘飞不到处。\n此地知无暑。\n乱竹分幽径，虚堂中、自回互。\n阴壑生暗雾。\n飞泉注。\n气入闲尊俎。\n快风度。\n齐宫楚榭，如今空锁烟树。\n何人伴我，梦赋雪车冰柱。\n惟有蝉声助冷语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13454, '隔浦莲・隔浦莲近拍', '史达祖', '洛神一醉未醒。\n俯鉴窥红影。\n万绿森相卫，西风静、不放冷。\n侵晓鸥梦稳。\n非尘境。\n棹月香千顷。\n锦机靓。\n亭亭不语，多应嗔赋玉井。\n西湖游子，惯识雨愁烟恨。\n只恐吴娃暗折赠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13455, '凤来朝', '史达祖', '晕粉就妆镜。\n掩金闺、彩丝未整。\n趁无人、学指鸳鸯颈。\n恨谁踏、藓花径。\n一梦蒲香葵冷。\n堕银瓶、脆绳挂井。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13456, '玉簟凉', '史达祖', '秋是愁乡。\n自锦瑟断弦，有泪如江。\n平生花里活，奈旧梦难忘。\n蓝桥云树正绿，料抱月、几夜眠香。\n河汉阻，但凤音传恨，阑影敲凉。\n新妆。\n莲娇试晓，梅瘦破春，因甚却扇临窗。\n红巾衔翠翼，早弱水茫茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13457, '鹊桥仙', '史达祖', '河深鹊冷，云高鸾远，水佩风裳缥缈。\n却推离恨下人间，第一个、黄昏过了。\n舟行有恨，愁来无限，去去长安渐杳。\n应将巧思入相思，觉泪比、银湾较少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13458, '湘江静', '史达祖', '暮草堆青云浸浦。\n记匆匆、倦篙曾驻。\n渔榔四起，沙鸥未落，怕愁沾诗句。\n碧袖一声歌，石城怨、西风随去。\n沧波荡晚，菰蒲弄秋，还重到、断魂处。\n酒易醒，思正苦。\n想空山、桂香悬树。\n三年梦冷，孤吟意短，屡烟钟津鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13459, '玲珑四犯', '史达祖', '雨入愁边，翠树晚，无人风叶如翦。\n竹尾通凉，却怕小帘低卷。\n孤坐便怯诗悭，念後赏、旧曾题遍。\n更暗尘、偷锁鸾影，心事屡羞团扇。\n卖花门馆生秋草，怅弓弯、几时重见。\n前欢尽属风流梦，天共朱楼远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13460, '玲珑四犯', '史达祖', '阔甚吴天，顿放得、江南离绪多少。\n一雨为秋，凉气小窗先到。\n轻梦听彻风蒲，又散入、楚空清晓。\n问世间、愁在何处，不离澹烟衰草。\n簟纹独浸芙蓉影，想凄凄、欠郎偎抱。\n即今卧得云衣冷，山月仍相照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13461, '八归', '史达祖', '秋江带雨，寒沙萦水，人瞰画阁愁独。\n烟蓑散响惊诗思，还被乱鸥飞去，秀句难续。\n冷眼尽归图画上，认隔岸、微茫云屋。\n想半属、渔市樵村，欲暮竞然竹。\n须信风流未老，凭持酒、慰此凄凉心目。\n一鞭南陌，几篙官渡，赖有歌眉舒绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13462, '过龙门・浪淘沙令', '史达祖', '一带古苔墙。\n多听寒。\n箧中针线早销香。\n燕尾宝刀窗下梦，谁翦秋裳。\n宫漏莫添长。\n空费思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13463, '过龙门・浪淘沙令', '史达祖', '醉月小红楼。\n锦瑟箜篌。\n夜来风雨晓来收。\n几点落花饶柳絮，同为春愁。\n寄信问晴鸥。\n谁在芳洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13464, '玉胡蝶・玉蝴蝶', '史达祖', '晚雨未摧宫树，可怜闲叶，犹抱凉蝉。\n短景归秋，吟思又接愁边。\n漏初长、梦魂难禁，人渐老、风月俱寒。\n想幽欢。\n土花庭，虫网阑干。\n无端。\n啼蛄搅夜，恨随团扇，苦近秋莲。\n一笛当楼，谢娘悬泪立风前。\n故园晚、强留诗酒，新雁远、不致寒暄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13465, '齐天乐', '史达祖', '秋风早入潘郎鬓，斑斑遽惊如许。\n暖雪侵梳，晴丝拂领，栽满愁城深处。\n瑶簪谩妒。\n便羞插宫花，自怜衰暮。\n尚想春情，旧吟凄断茂陵女。\n人间公道惟此，叹朱颜也恁，容易堕去。\n涅了重缁，搔来更短，方悔风流相误。\n郎潜几缕。\n渐疏了铜驼，俊游俦侣。\n纵有黟黟，奈何诗思苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13466, '齐天乐', '史达祖', '阑干只在鸥飞处，年年怕吟秋兴。\n断浦沈云，空山挂雨，中有诗愁千顷。\n波声未定。\n望舟尾拖凉，渡头笼暝。\n正好登临，有人歌罢翠帘冷。\n悠然魂坠故里，奈闲情未了，还被吹醒。\n拜月虚檐，听蛩坏砌，谁复能怜娇俊。\n忧心耿耿。\n寄桐叶芳题，冷枫新咏。\n莫遣秋声，树头喧夜永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13467, '齐天乐', '史达祖', '犀纹隐隐莺黄嫩，篱落翠深偷见。\n细雨重移，新霜试摘，佳处一年秋晚。\n荆江未远。\n想橘友荒凉，木奴嗟怨。\n就说风流，草泥来趁蟹螯健。\n并刀寒映素手，醉魂沈夜饮，曾倩排遣。\n沆瀣含酸，金罂裹玉，蔌蔌吴盐轻点。\n瑶姬齿软。\n待惜取团圆，莫教分散。\n入手温存，帕罗香自满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13468, '齐天乐', '史达祖', '鸳鸯拂破苹花影，低低趁凉飞去。\n画里移舟，诗边就梦，叶叶碧云分雨。\n芳游自许。\n过柳影闲波，水花平渚。\n见说西风，为人吹恨上瑶树。\n阑干斜照未满，杏墙应望断，春翠偷聚。\n浅约香，深盟捣月，谁是窗间青羽。\n孤筝几柱。\n问因甚参差，暂成离阻。\n夜色空庭，待归听俊语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13469, '齐天乐', '史达祖', '西风来劝凉云去，天东放开金镜。\n照野霜凝，如河桂湿，一一冰壶相映。\n殊方路永。\n更分破秋光，尽成悲境。\n有客踌躇，古庭空自吊孤影。\n江南朋旧在许，也能怜天际，诗思谁领。\n梦断刀头，书开虿尾，别有相思随定。\n忧心耿耿。\n对风鹊残枝，露蛩荒井。\n斟酌妲娥，九秋宫殿冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13470, '燕归梁', '史达祖', '楚梦吹成树外云。\n乍雁影斜分。\n黄花心事一帘尘。\n但频忆、小腰身。\n今宵素壁冰弦冷，怕弹断、沈郎魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13471, '燕归梁', '史达祖', '独卧秋窗桂未香。\n怕雨点飘凉。\n玉人只在楚云傍。\n也著泪、过昏黄。\n西风今夜梧桐冷，断无梦、到鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13472, '月当厅', '史达祖', '白壁旧带秦城梦，因谁拜下，杨柳楼心。\n正是夜分，鱼钥不动香深。\n时有露萤自照，占风裳、可喜影麸金。\n坐来久，都将凉意，尽付沈吟。\n残云事绪无人舍，恨匆匆、药娥归去难寻。\n缀取雾窗，会唱几拍清音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13473, '秋霁', '史达祖', '江水苍苍，望倦柳愁荷，共感秋色。\n废阁先凉，古帘空暮，雁程最嫌风力。\n故园信息。\n爱渠入眼南山碧。\n念上国。\n谁是、脍鲈江汉未归客。\n还又岁晚，瘦骨临风，夜闻秋声，吹动岑寂。\n露蛩悲、清灯冷屋，翻书愁上鬓毛白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13474, '满江红', '史达祖', '万水归阴，故潮信、盈虚因月。\n偏只到、凉秋半破，斗成双绝。\n有物揩磨金镜净，何人拿攫银河决。\n想子胥、今夜见嫦娥，沈冤雪。\n光直下，蛟龙穴。\n声直上，蟾蜍窟。\n对望中天地，洞然如刷。\n激气已能驱粉黛，举杯便可吞吴越。\n待明朝、说似与儿曹，心应折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13475, '满江红', '史达祖', '好领青衫，全不向、诗书中得。\n还也费、区区造物，许多心力。\n未暇买田清颍尾，尚须索米长安陌。\n有当时、黄卷满前头，多惭德。\n思往事，嗟儿剧。\n怜牛後，怀鸡肋。\n奈棱棱虎豹，九重九隔。\n三径就荒秋自好，一钱不直贫相逼。\n对黄花、常待不吟诗，诗成癖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13476, '满江红', '史达祖', '缓辔西风，叹三宿、迟迟行客。\n桑梓外、锄渐入，柳坊花陌。\n双阙远腾龙凤影，九门空锁鸳鸯翼。\n更无人、笛傍宫墙，苔花碧。\n天相汉，民怀国。\n天厌虏，臣离德。\n趁建瓴一举，并收鳌极。\n老子岂无经世术，诗人不预平戎策。\n办一襟、风月看升平，吟春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13477, '恋绣衾', '史达祖', '吴梅初试涧谷春。\n夜幽幽、江雁叫云。\n人正在、孤窗底，被浓愁、醺破醉魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13478, '恋绣衾', '史达祖', '黄花惊破九日愁。\n正寒城、风雨怨秋。\n愁便是、秋心也，又随人、来到画楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13479, '恋绣衾', '史达祖', '天风入扇吹苎衣。\n小红楼、夜气正微。\n有人在、冰弦外，水精帘、花影自移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13480, '换巢鸾凤', '史达祖', '人若梅娇。\n正愁横断坞，梦绕溪桥。\n倚风融汉粉，坐月怨秦箫。\n相思因甚到纤腰。\n定知我今，无魂可销。\n佳期晚，谩几度、泪痕相照。\n人悄。\n天眇眇。\n花外语香，时透郎怀抱。\n暗握荑苗，乍尝樱颗，犹恨侵阶芳草。\n天念王昌忒多情，换巢鸾凤教偕老。\n温柔乡，醉芙蓉、一帐春晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13481, '惜奴娇', '史达祖', '香剥酥痕，自昨夜、春愁醒。\n高情寄、冰桥雪岭。\n试约黄昏，便不误、黄昏信。\n人静。\n倩娇娥、留连秀影。\n吟鬓簪香，已断了、多情病。\n年年待、将春管领。\n镂月描云，不枉了、闲心性。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13482, '龙吟曲・水龙吟', '史达祖', '夜寒幽梦飞来，小梅影下东风晓。\n蝶魂未冷，吾身良是，悠然一笑。\n竹杖敲苔，布鞋踏冻，岁常先到。\n傍苍林却恨，储风养月，须我辈、新诗吊。\n永以南枝为好。\n怕从今、逢花渐老。\n愁消秀句，寒回斗酒，春心多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13483, '龙吟曲・水龙吟', '史达祖', '梦回虚白初生，便凝冷月通窗户。\n不知夜久，都无人见，玉妃起舞。\n银界回天，琼田易地，晃然非故。\n想儿童健意，生愁齐色，情频在、窥帘处。\n一片樵林钓浦。\n是天教、王维画取。\n未如授简，先将高兴，收归妙句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13484, '龙吟曲・水龙吟', '史达祖', '道人越布单衣，兴高爱学苏门啸。\n有时也伴，四佳公子，五陵年少。\n歌里眠香，酒酣喝月，壮怀无挠。\n楚江南，每为神州未复，阑干静、慵登眺。\n今日征夫在道。\n敢辞劳、风沙短帽。\n休吟稷穗，休寻乔木，独怜遗老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13485, '鹧鸪天', '史达祖', '睡袖无端几摺香。\n有人丹脸可占霜。\n半窗月印梅犹瘦，一律瓶笙夜正长。\n情艳艳，酒狂狂。\n小屏谁与画鸳鸯。\n解衣恰恨敲金钏，惊起春风傍枕囊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13486, '鹧鸪天', '史达祖', '御路东风拂醉衣。\n卖灯人散烛笼稀。\n不知月底梅花冷，只忆桥边步袜归。\n闲梦淡，旧游非。\n夜深谁在小帘帏。\n罘儿下围炉坐，明处将人立地时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13487, '鹧鸪天', '史达祖', '搭柳阑干倚伫频。\n杏帘胡蝶绣床春。\n十年花骨东风泪，几点螺香素壁尘。\n箫外月，梦中云。\n秦楼楚殿可怜身。\n新愁换尽风流性，偏恨鸳鸯不念人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13488, '鹧鸪天', '史达祖', '雁足无书古塞幽。\n一程烟草一程愁。\n帽檐尘重风吹野，帐角香销月满楼。\n情思乱，梦魂浮。\n缃裙多忆敝貂裘。\n官河水静阑干暖，从倚斜阳怨晚秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13489, '惜黄花', '史达祖', '涵秋寒渚。\n染霜丹树。\n尚依稀，是来时、梦中行路。\n时节正思家，远道仍怀古。\n更对著、满城风雨。\n黄花无数。\n碧云欲暮。\n美人兮，美人兮、未知何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13490, '玉烛新', '史达祖', '疏云萦碧岫。\n带晚日摇光，半江寒皱。\n越溪近远，空频向、过雁风边回首。\n酸心一缕。\n念水北、寻芳归後。\n轻醉醒、堤月笼沙，鞍松宝轮飞骤。\n秦楼屡约芳春，记扇背题诗，帕罗沾酒。\n瘦愁易就。\n因惊断、梦里桃源难又。\n临风话旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13491, '一翦梅', '史达祖', '谁写梅溪字字香。\n沙边幽梦，常恁芬芳。\n不知花解伴昏黄。\n只怕东风，吹断人肠。\n小阁无灯月浸窗。\n香吹罗袖，酒映宫妆。\n如今竹外怕思量。\n谷里佳人，一片冰霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13492, '一翦梅', '史达祖', '秦客当楼泣凤箫。\n宫衣香断，不见纤腰。\n隔年心事又今宵。\n折尽冰弦，何用鸾胶。\n些子轻魂几度销。\n兰骚蕙些，无计重招。\n东窗一段月华娇。\n也带春愁，飞上梅梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13493, '醉落魄・一斛珠', '史达祖', '鸳鸯意惬。\n空分付、有情眉睫。\n齐家莲子黄金叶。\n争比秋苔，靴凤几番蹑。\n墙阴月白花重叠。\n匆匆软语屡惊怯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13494, '醉落魄・一斛珠', '史达祖', '江痕妥帖。\n日光熨动黄金叶。\n阑干直下愁相接。\n一朵红莲，飞上越人楫。\n鲤鱼波上丁宁切。\n诗筒如线不曾别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13495, '醉公子', '史达祖', '神仙无皋泽。\n琼裾珠佩，卷下尘陌。\n秀骨依依，误向山中，得与相识。\n溪岸侧。\n倚高情、自锁烟翠，时点空碧。\n念香襟沾恨，酥手翦愁，今後梦魂隔。\n相思暗惊清吟客。\n想玉照堂前、树三百。\n雁翅霜轻，凤羽寒深，谁护春色。\n诗鬓白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13496, '步月', '史达祖', '翦柳章台，问梅东阁，醉中携手初归。\n逗香帘下，璀璨镂金衣。\n正依约、冰丝射眼，更荏苒、蟾玉西飞。\n轻尘外，双鸳细蹙，谁赋洛滨妃。\n霏霏。\n红雾绕，步摇共鬓影，吹入花围。\n管弦将散，人静烛笼稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13497, '齐天乐', '高观国', '碧云阙处无多雨，愁与去帆俱远。\n倒苇沙闲，枯兰溆冷，寥落寒江秋晚。\n楼阴纵览。\n正魂怯清吟，病多依黯。\n怕挹西风，袖罗香自去年减。\n风流江左久客，旧游得意处，朱帘曾卷。\n载酒春情，吹箫夜约，犹忆玉娇香软。\n尘栖故苑，叹璧月空檐，梦云飞观。\n送绝征鸿，楚峰烟数点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13498, '齐天乐', '高观国', '丛幽一笑东篱晓，霜华又随香冷。\n晕色黄娇，低枝翠婉，来趁登高佳景。\n谁偏管领。\n是彭泽归来，未荒三径。\n最惬清觞，道家标致自风韵。\n南山依旧翠倚，采花无限思，西风吹醒。\n万蕊金寒，三秋梦好，曾记餐英清咏。\n斓斑泪沁。\n怕节去蜂愁，雨荒烟暝。\n明日重阳，为谁簪短鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13499, '齐天乐', '高观国', '晚云知有关山念，澄霄卷开清霁。\n素景分中，冰盘正溢，何啻婵娟千里。\n危阑静倚。\n正玉管吹凉，翠觞留醉。\n记约清吟，锦袍初唤醉魂起。\n孤光天地共影，浩歌谁与舞，凄凉风味。\n古驿烟寒，幽垣梦冷，应念秦楼十二。\n归心对此。\n想斗插天南，雁横辽水。\n试问妲娥，有谁能为寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13500, '玉楼春', '高观国', '几双海燕来金屋。\n春满离宫三十六。\n春风翦草碧纤纤，春雨花红扑扑。\n卫姬郑女腰如束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13501, '玉楼春', '高观国', '燕脂染出春风锦。\n生怕黄昏人有恨。\n雨难揩泪玉环娇，烟不遮愁红袖冷。\n醉魂吹断香魂静。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13502, '玉楼春', '高观国', '多时不踏章台路。\n依旧东风芳草渡。\n莺声唤起水边情，日影炙开花上雾。\n谢娘不信佳期误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13503, '玉楼春', '高观国', '春烟澹澹生春水。\n曾记芳洲兰棹舣。\n岸花香到舞衣边，汀草色分歌扇底。\n棹沈云去情千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13504, '玉蝴蝶', '高观国', '唤起一襟凉思，未成晚雨，先做秋阴。\n楚客悲残，谁解此意登临。\n古台荒、断霞斜照，新梦黯、微月疏砧。\n总难禁。\n尽将幽恨，分付孤斟。\n从今。\n倦看青镜，既迟勋业，可负烟林。\n断梗无凭，岁华摇落又惊心。\n想莼汀、水云愁凝，闲蕙帐、猿鹤悲吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13505, '临江仙', '高观国', '俱是洛阳年少客，才华迥出天真。\n青衫惯拂软红尘。\n酒狂因月舞，诗俊为梅新。\n寄语长安风月道，莺花缓作青春。\n披风沐露问前津。\n客中春不当，归去倍还人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13506, '临江仙', '高观国', '风月生来人世，梦魂飞堕仙津。\n青春日日醉芳尘。\n一鞭花陌晓，双桨柳桥春。\n前度诗留醉袖，昨宵香罗巾。\n小姬飞燕是前身。\n歌随流水咽，眉学远山颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13507, '金人捧露盘', '高观国', '梦湘云，吟湘月，吊湘灵。\n有谁见、罗袜尘生。\n凌波步弱，背人羞整六铢轻。\n娉娉袅袅，晕娇黄、玉色轻明。\n香心静，波心冷，琴心怨，客心惊。\n怕佩解、却返瑶京。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13508, '金人捧露盘', '高观国', '念瑶姬，翻瑶佩，下瑶池。\n冷香梦、吹上南枝。\n罗浮梦杳，忆曾清晓见仙姿。\n天寒翠袖，可怜是、倚竹依依。\n溪痕浅，云痕冻，月痕澹，粉痕微。\n江楼怨、一笛休吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13509, '金人捧露盘', '高观国', '楚宫闲，金成屋，玉为阑。\n断云梦、容易惊残。\n骊歌几叠，至今愁思怯阳关。\n清音恨阻，抱哀筝、知为谁弹。\n年华晚，月华冷，霜华重，鬓华斑。\n也须念、闲损雕鞍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13510, '凤栖梧・蝶恋花', '高观国', '云唤阴来鸠唤雨。\n谢了江梅，可踏江头路。\n拼却一番花信阻。\n不成日日春寒去。\n见说东风桃叶渡。\n岸隔青山，依旧修眉妩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13511, '凤栖梧・蝶恋花', '高观国', '岩室归来非待聘。\n渺渺千崖，漠漠江千顷。\n明月清风休弄影。\n只愁踏破苍苔径。\n摘取香芝医鹤病。\n正要仙，相伴清闲性。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13512, '凤栖梧・蝶恋花', '高观国', '西子湖边眉翠妩。\n魂冷孤山，谁是风烟主。\n相唤吟诗天欲雨。\n嫩凉不隔鸥飞处。\n移下天孙云锦渚。\n翠盖牵风，绰约凌波女。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13513, '贺新郎', '高观国', '月冷霜袍拥。\n见一枝、年华又晚，粉愁香冻。\n云隔溪桥人不度，的春心未纵。\n清影怕、寒波摇动。\n更没纤毫尘俗态，倚高情、预得春风宠。\n沈冻蝶，挂么凤。\n一杯正要吴姬捧。\n想见那、柔酥弄白，暗香偷送。\n回首罗浮今在否，寂寞烟迷翠拢。\n又争奈、桓伊三弄。\n开遍西湖春意烂，算群花、正作江山梦。\n吟思怯，暮云重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13514, '喜迁莺', '高观国', '歌声凄怨。\n是几度诉春，春都不管。\n感绿惊红，颦烟啼月，长是为春消黯。\n玉骨瘦无一把，粉泪愁多千点。\n可怜损，任尘侵粉蠹，舞裙歌扇。\n转盼。\n尘梦断。\n峡里云归，空想春风面。\n燕子楼空，玉台妆冷，湖外翠峰眉浅。\n绮陌断魂名在，宝箧返魂香远。\n此情苦，问落花流水，何时重见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13515, '喜迁莺', '高观国', '凉云归去。\n再约著，晚来西楼风雨。\n水静帘阴，鸥闲菰影，秋到露汀烟浦。\n试省唤回幽恨，尽是愁边新句。\n倦登眺，动悲凉还在，残蝉吟处。\n凄楚。\n空见说，香锁雾扃，心似秋莲苦。\n宝瑟弹冰，玉台窥月，浅澹可怜偷聚。\n几时翠沟题叶，无复绣帘吹絮。\n鬓华晚，念庾郎情在，风流谁与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13516, '菩萨蛮', '高观国', '春风吹绿湖边草。\n春光依旧湖边道。\n玉勒锦障泥。\n少年游冶时。\n烟明花似绣。\n且醉旗亭酒。\n斜日照花西。\n归鸦花外啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13517, '菩萨蛮', '高观国', '红云半压秋波碧。\n艳妆泣露娇啼色。\n佳梦入仙城。\n风流石曼卿。\n宫袍呼醉醒。\n休卷西风锦。\n明日粉香残。\n六朝烟水寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13518, '菩萨蛮', '高观国', '玉鳞熬出香凝软。\n并刀断处冰丝颤。\n红缕间堆盘。\n轻明相映寒。\n纤柔分劝处。\n腻滑难停筋。\n一洗醉魂清。\n真成醒酒冰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13519, '菩萨蛮', '高观国', '玉阑秋色知谁主。\n隔阑一架葡萄雨。\n绿藓怕啼。\n可堪宫漏长。\n乌丝吟古怨。\n清泪消尘砚。\n梦冷不成云。\n□峰峰外情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13520, '菩萨蛮', '高观国', '何须急管吹云暝。\n高寒滟滟开金饼。\n今夕不登楼。\n一年空过秋。\n桂花香雾冷。\n梧叶西风影。\n客醉倚河桥。\n清光愁玉箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13521, '菩萨蛮', '高观国', '云娇雪嫩羞相倚。\n凌波共酌春风醉。\n的玉台寒。\n肯教金盏单。\n只疑双蝶梦。\n翠袖和香拥。\n香外有鸳鸯。\n风流烟水乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13522, '青玉案', '高观国', '平生似欠西湖债。\n每拼了、金貂解。\n妩媚烟云多变态。\n雕鞍来处，画船归去，花柳春风隘。\n玉京相接蓬壶界。\n入画遥山翠分黛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13523, '醉落魄・一斛珠', '高观国', '钩帘翠湿。\n寒江上、雨晴风急。\n乱峰低处明残日。\n雁字成行，写破暮天碧。\n故人天外长为客。\n倚阑一望情何极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13524, '夜合花', '高观国', '斑驳云开，松雨过，海棠花外寒轻。\n湖山翠暖，东风正要新晴。\n又唤醒，旧游情。\n记年时、今日清明。\n隔花阴浅，香随笑语，特地逢迎。\n人生好景难并。\n依旧秋千巷陌，花月蓬瀛。\n春衫抖擞，馀香半染芳尘。\n念嫩约，杳难凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13525, '花心动', '高观国', '碧藓封枝，点寒英、疏疏玉清冰洁。\n梦忆旧家，春与新恩，曾映寿阳妆额。\n绿裙青袂南邻伴，应怪我、精神都别。\n恨衰晚、春风意思，顿成羞怯。\n犹念横斜性格。\n恼和靖吟魂，自来清绝。\n斜傍劲松，偷倚修篁，总是岁寒相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13526, '昭君怨', '高观国', '一棹莫愁烟艇。\n飞破玉壶清影。\n水溅粉绡寒。\n渺云鬟。\n不肯凌波微步。\n却载春愁归去。\n风澹楚魂惊。\n隔瑶京。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13527, '杏花天', '高观国', '霁烟消处寒犹嫩。\n乍门巷、昼永。\n池塘芳草魂初醒。\n秀句吟春未稳。\n仙源阻、春风瘦损。\n又燕子、来无芳信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13528, '杏花天', '高观国', '远山学得修眉翠。\n看眉展、春愁无际。\n雨痕半湿东风外。\n不管梨花有泪。\n西园路、青鞋暗记。\n怕行入、秋千径里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13529, '杏花天', '高观国', '花凝露湿燕脂透。\n是彩笔、丹青染就。\n粉绡帕入班姬手。\n舒卷清寒时候。\n春禽静、来窥晴昼。\n问冷落、芳心知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13530, '杏花天', '高观国', '玉坛消息春寒浅。\n露红玉、娇生靓艳。\n小怜鬓湿燕脂染。\n只隔粉墙相见。\n花阴外、故宫梦远。\n想未识、莺莺燕燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13531, '祝英台近', '高观国', '拥红妆，翻翠盖，花影暗南浦。\n波面澄霞，兰艇采香去。\n有人水溅红裙，相招晚醉，正月上、凉生风露。\n两凝伫。\n别後歌断云闲，娇姿黯无语。\n魂梦西风，端的此心苦。\n遥想芳脸轻颦，凌波微步，镇输与、沙边鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13532, '祝英台近', '高观国', '一窗闲，孤烬冷，独自个春睡。\n绣被熏香，不似旧风味。\n静听滴滴檐声，惊愁搅梦，更不管、庾郎心碎。\n念芳意。\n一并十日春寒，梅花煞憔悴。\n懒做新词，春在可怜里。\n几时挑菜踏青，云沈雨断，尽分付、楚天之外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13533, '江城子', '高观国', '绿丛篱菊点娇黄。\n过重阳。\n转愁伤。\n风急天高，归雁不成行。\n此去郎边知近远，秋水阔，碧天长。\n郎心如妾妾如郎。\n两离肠。\n一思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13534, '生查子', '高观国', '野泉春吐芽，泥湿随飞燕。\n碧涧一杯羹，夜韭无人翦。\n玉钗和露香，鹅管随春软。\n野意重殷勤，持以君王献。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13535, '生查子', '高观国', '芙蓉羞粉香，倚竹窥烟霁。\n眼带楚波寒，骨艳春风醉。\n谁传侧帽情，想解遗鞭意。\n红叶可怜秋，不寄相思字。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13536, '生查子', '高观国', '蓬莱一捻云，彻骨龙涎染。\n风味韵而芳，笑语柔而婉。\n花娇绿鬓寒，酒凝清歌怨。\n翠幄已烟浓，银烛重休翦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13537, '生查子', '高观国', '春笼云润香，露湿青蛟瘦。\n偷学汉宫妆，舞彻霓裳後。\n酥胸紫领巾，冰翦柔荑手。\n有意入罗囊，不肯成春酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13538, '生查子', '高观国', '飞花澹澹风，破暖疏疏雨。\n香润玉阶尘，翠湿纱窗雾。\n钿筝离雁行，宝箧留钗股。\n惟有凤楼魂，夜夜江南路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13539, '生查子', '高观国', '香惊楚驿寒，瘦倚湘筠暮。\n一笛已黄昏，片月尤清楚。\n沈沈冰玉魂，漠漠烟云浦。\n酸泪不成弹，又向春心聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13540, '解连环', '高观国', '露条烟叶。\n惹长亭旧恨，几番风月。\n爱细缕、先轻黄，渐拂水藏鸦，翠阴相接。\n纤软风流，眉黛浅、三眠初歇。\n奈年华又晚，萦绊游蜂，絮飞晴雪。\n依依灞桥怨别。\n正千丝万绪，难禁愁绝。\n怅岁久、应长新条，念曾系花骢，屡停兰楫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13541, '解连环', '高观国', '浪摇新绿。\n漫芳洲翠渚，雨痕初足。\n荡霁色、流入横塘，看风外漪漪，皱纹如。\n藻荇萦回，似留恋、鸳飞鸥浴。\n爱娇云蘸色，媚日蓝，远迷心目。\n仙源漾舟岸曲。\n照芳容几树，香浮红玉。\n记那回、西洛桥边，裙翠传情，玉纤轻掬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13542, '烛影摇红', '高观国', '别浦潮平，远村帆落烟江冷。\n征鸿相唤著行飞，不耐霜风紧。\n雪意垂垂未定。\n正惨惨、云横冻影。\n酒醒情绪，日晚登临，凄凉谁问。\n行乐京华，软红不断香尘喷。\n试将心事卜归期，终是无凭准。\n寥落年华将尽。\n误玉人、高楼凝恨。\n第一休负，西子湖边，江梅春信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13543, '忆秦娥', '高观国', '栖乌惊。\n隔窗月色寒於冰。\n寒於冰。\n澹移梅影，冷印疏棂。\n幽香未觉魂先清。\n无端勾起相思情。\n相思情。\n恼人无睡，直到天明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13544, '忆秦娥', '高观国', '歌声闲。\n兰舟只隔芙蓉湾。\n芙蓉湾。\n扇摇波影，风卷云鬟。\n馀音袅袅留馀欢。\n双鸳飞处传情难。\n传情难。\n曲终人去，愁寄湖山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13545, '清平乐', '高观国', '盘枝翦翠。\n叶叶西风意。\n吹上玉人云□底。\n无限新凉气味。\n飘萧露卷烟柔。\n绝怜不逐宫流。\n寄语多情宋玉，悲秋得似宜秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13546, '清平乐', '高观国', '春蒲雨湿。\n燕子低飞急。\n云压前山群翠失。\n烟水满湖轻碧。\n小莲相见湾头。\n清寒不到青楼。\n请上琵琶弦索，今朝破得春愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13547, '更漏子', '高观国', '玉箫闲，清韵咽。\n人倚画兰愁绝。\n云恼月，月羞云。\n半溪梅影昏。\n恨春风，萧散後。\n夜夜数残更漏。\n情悄悄，思依依。\n天寒一雁飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13548, '东风第一枝', '高观国', '玉洁生英，冰清孕秀，一枝天地春早。\n素盟江国芳寒，旧约汉宫梦晓。\n溪桥独步，看洒落、仙人风表。\n似妙句、何逊扬州，最惜细吟清峭。\n香暗度、照影波渺。\n春暗寄、付情云杳。\n爱随青女横陈，更怜素娥窈窕。\n调羹雅意，好赞助、清时廊庙。\n羡韵高、只有松筠，共结岁寒难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13549, '东风第一枝', '高观国', '烧色回青，冰痕绽白，娇云先酿酥雨。\n纵寒不压葭尘，应时已鞭黛土。\n东君入夜，怕预恼、诗边心绪。\n意转新，无奈吟魂，醉里已题春句。\n香梦醒、几花暗吐。\n绿睡起、几丝偷舞。\n酒醅清惜重斟，菜甲嫩怜细缕。\n玉纤彩胜，愿岁岁、春风相遇。\n要等得、明日新晴，第一待寻芳去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13550, '摊破浣溪沙・山花子', '高观国', '袅袅天风响佩环。\n鹊桥有女夜乘鸾。\n也恨别多相见少，似人间。\n银浦无声云路渺，金风有信玉机闲。\n生怕河梁分袂处，晓光寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13551, '浣溪沙', '高观国', '遮坐银屏度水沈。\n障风罗幕皱泥金。\n日迟宫院静。\n繁杏半窥红日薄，小怜低唱绿窗深。\n试拈犀管写春心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13552, '水调歌头', '魏了翁', '落日下平楚，秋色到方塘。\n人间袢暑难耐，独有此清凉。\n龙卷八荒霖雨，鹤十州风露。\n回薄水云乡。\n欲识千里润，记取玉流芳。\n石兰衣，江蓠佩，芰荷裳。\n个中自有服媚，何必锦名堂。\n吸取玻璃清涨，唤起逍遥旧梦，人物俨相望。\n矫首望归路，三十六虚皇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13553, '贺新郎', '魏了翁', '独立西风里。\n渺无尘、明河挂斗，碧天如洗。\n鹊楼前迎风处，吹堕乘槎星使。\n弄札札、机中巧思。\n织就天孙云锦段，尚轻阴、朱阁留纤翳。\n亲为挽，天潢水。\n等闲富贵浮云似。\n须存留、几分清论，护持元气。\n曾把古今兴亡事，奏向前旒十二。\n虽去国、言犹在耳。\n念我独兮谁与共，谩凝思、一日如三岁。\n夜耿耿，不皇寐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13554, '水调歌头', '魏了翁', '溥露浸秋色，零雨濯湖弦。\n做成特地风月，管领老仙。\n雁落村间影，鱼识桥边柱杖，虑澹境长偏。\n祗恐未免耳，惊搅日高眠。\n龙握节，貂插案，鹿衔。\n於公元只馀事，所乐不存焉。\n手植蓝田种子，无数阶庭成树，郁郁紫生烟。\n富贵姑勿道，借问此何缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13555, '水调歌头', '魏了翁', '轻露沦残暑，哉魄拟初弦。\n天台万八千丈，中有紫霞仙。\n正理中枢旧武，却忆邻环昨梦，重上蜀青天。\n只守伯禽法，с野万云烟。\n锦川星，郎位宿，又移躔。\n为无结辈十数，踏遍蜀山川。\n人识绍兴奉使，家有显谟科约，慧命得公传。\n从此造朝去，两地亦青毡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13556, '水调歌头', '魏了翁', '岁岁为公寿，著语不能新。\n自公持节北去，我亦有遐征。\n坐我碧瑶洞府，被我石楠嘉荫，冰柱向人清。\n待屈西风指，王事有期程。\n我尝闻，由汉水，达河津。\n痴牛呆女会处，应有泛槎人。\n便向汉川东畔，直透银河左界，去上白云京。\n袖有传婿研，我欲丐馀芬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13557, '摸鱼儿', '魏了翁', '知年来、几番拜疏。\n但言归去归去。\n问归有底匆忙事，得恁陈情良苦。\n天未许。\n将花绶藻衣，为插仪庭羽。\n掉头不顾。\n念白发翁儿，本来天分，不是折腰具。\n从头数。\n多少汉庭簪组。\n滔滔车马成雾。\n争如祖帐东门外，父子缥缥高举。\n峨眉下、有几许湖山，无著春风处。\n留君不住。\n但远景楼前，追陪杖屦，莫忘却、别时语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13558, '朝中措', '魏了翁', '沙堤除道火成城。\n换得午桥清。\n寒色般添酒令，野芳抵当羹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13559, '水调歌头', '魏了翁', '曾记武林日，岁上德星堂。\n相君襟度夷雅，容我少年狂。\n辇路升平风月，禁陌清时锺鼓，送紫霞觞。\n回首十年事，解后衮衣乡。\n古今梦，元一辙，谩千场。\n纷纷间较目睫，谁解识方将。\n霜落南山秋实，风卷北邻夜燎，世事正匆忙。\n天意那可问，只愿善人昌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13560, '临江仙', '魏了翁', '晓色云日澹，绰开坦坦长途。\n西宁太守问程初。\n梅梢迎候骑，柳树困平芜。\n九折邛峡浑可事，不妨叱驭先驱。\n平平岂是策真无。\n抚摩迂事业，细密钝功夫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13561, '水调歌头', '魏了翁', '人物正寥阔，有美万夫望。\n七年填拊方面，帏幄自金汤。\n千尺玉龙衔诏，六尺宝照路，载绩满旗常。\n富贵姑勿道，难得此芬芳。\n尝试看，今古梦，几千场。\n人情但较目睫，谁解识方将。\n霜落南山秋实，风卷北邻夜燎，世事正匆忙。\n海内知公者，只愿寿而臧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13562, '临江仙', '魏了翁', '怪见江乡文物地，轻豪争逐春妍。\n银花斜紫金鞭。\n千灯浑是泪，一笑不论钱。\n今岁遨头穷相眼，繁华不学常年。\n只余底事索人怜。\n诗书真气味，农扈老风烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13563, '鹧鸪天', '魏了翁', '日日春风满范围。\n海棠又发去年枝。\n月笼火树更深後，露滴燕支晓起时。\n看不足，醉为期。\n宵征宁问角巾。\n一春好处无多子，不分西园掇取归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13564, '临江仙', '魏了翁', '脚踏西郊红世界，才知春意分明。\n不须更说锦官城。\n春来游冶骑，得得为渠停。\n停到花眠人且去，酒杯苦欲留行。\n直须醉饮到参横。\n不因歌白雪，三日作狂酲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13565, '柳梢青', '魏了翁', '撺掇花枝，趱那天气，一半春休。\n未分真休，平湖新涨，稚绿初抽。\n等闲作个扁舟。\n便都把、湖光卷收。\n世事元来，都缘本有，不在他求。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13566, '摸鱼儿', '魏了翁', '向江头、几回凝望，垂杨那畔舟才舣。\n江神似识东归意。\n故放一篙春水。\n却总被。\n三百里人家、祖帐连天起。\n且行且止。\n便为汝迟留，三朝两日，如此只如此。\n还须看，世上忧端如猬。\n一枰白黑棋子。\n肥边瘦腹都闲事。\n毕竟到头何似。\n当此际。\n要默识沈思，一著惺惺地。\n目前谁是。\n料当局诸公，敛容缩手，日夜待公至。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13567, '水调歌头', '魏了翁', '有匪碧岩使，长佩奏琅球。\n门前初暑才涨，一室淡於秋。\n帘卷峨眉烟雨，袖挟西川风露，满眼绿阴稠。\n人物眇然甚，得似此风流。\n此何时，公犹滞，剑南州。\n分明忧在目睫，只恁付悠悠。\n未问人谋当否，须信天生贤哲，不只等闲休。\n努力崇明德，巨浸要平舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13568, '贺新郎', '魏了翁', '汉使来何许。\n到如今、天边又是，薰弦三度。\n见说山深人睡稳，细雨自催茶户。\n向滴博、云间看取。\n料得权奇空却後，指浮云、万里追风去。\n跨燕越，抹秦楚。\n不妨且为斯人驻。\n正年来、忧端未歇，壮怀谁吐。\n顷刻阴晴千万态，怎解绸缪未雨。\n算此事、谁宽西顾。\n待洗岷峨凄怆气，为八荒、更著深长虑。\n间两社，辅明主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13569, '念奴娇', '魏了翁', '固陵江上，暮云急、一夜打头风雨。\n催送江船上水，笑指□山归去。\n靴帽丛中，渔樵席上，总是安行处。\n惟馀旧话，为公今日拈取。\n见说家近岷山，翠云平楚，万古青如故。\n要把平生三万轴，唤取山灵分付。\n庐阜嵩高，睢阳岳麓，会与岷为伍。\n及时须做，鬓边应未迟暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13570, '木兰花慢', '魏了翁', '怕年来年去，渐雅志、易华颠。\n叹梦里青藜，间边银信，望外朱。\n十年竟成何事，虽万锺、於我曷加焉。\n海上潮生潮落，山头云去云还。\n人生天地两仪间。\n只住百来年。\n今三纪虚过，七旬强半，四帙看看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13571, '满江红', '魏了翁', '有美人兮，招不至、几回凝伫。\n应只为、家山自好，不堪他顾。\n忙里抽头真得计，闲中袖手看成趣。\n念从前、出处总无心，天分付。\n云冉冉，更吞吐。\n泉活活，无朝暮。\n与自家意思，一般容与。\n月壑晓寒垂叶露，风窗午睡连山雨。\n看苍颜、白发两闲人，摩今古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13572, '满江红', '魏了翁', '宇宙中间，还独笑、谁疏谁密。\n正从容行处，山停川溢。\n锺鼎勒铭模物象，山林赐路开行荜。\n要不如、胸次祗熙熙，无今昔。\n便百中，穿牙戟。\n怕六凿，生虚室。\n为幽香小伫，旋供吟笔。\n人事未须劳预虑，天公浑不消余力。\n看雨馀、云卷约帘旌，明红日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13573, '鹧鸪天', '魏了翁', '尚忆都门祖帐时。\n重来动是十年期。\n云拖暮雨留行色，露挟秋凉入酒卮。\n湖上雁，水边犀。\n未须矫首叹来迟。\n北风满地尘沙暗，宣室方劳丙夜思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13574, '满江红', '魏了翁', '秋意冷然，对宇宙、一尊相属。ピ\n君看取、都无凝滞，天机纯熟。ピ\n水拍池塘鸿雁聚，露浓庭畹芝兰馥。ピ\n笑何曾、一事上眉头，萦心曲。ピ\n兴不浅，船明玉。ピ\n人更健，巾横幅。ピ\n问人间底处，升沉迟速。ピ\n气压暗岩虹半吐，眼明平楚云相逐。ピ\n但年年、屈指问西风，新。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13575, '鹧鸪天', '魏了翁', '月落星稀露气香。\n烟销日出晓光凉。\n天东扶木三千丈，一片丹心似许长。\n淇以北，洛之阳。\n买花移竹且迷藏。\n九重阊阖开黄道，未信低回两鬓霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13576, '满江红', '魏了翁', '湖水平漪，与我意、一般容与。\n任多少、双凫乘雁，落花飞絮。\n露冷云寒烟外竹，霜明日洁梅边路。\n怪天随、人意作阴晴，无非数。\n方寸地，图书府。\n老太史，亲分付。\n况身名四海，未为不遇。\n用舍行藏皆有命，时来将相还须做。\n且闲中、袖手阅时人，摩今古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13577, '虞美人', '魏了翁', '许时闭户间疏散。\n风月无人管。\n自从阳律一番新。\n又把前回风月、送西邻。\n浮云富贵非公愿。\n只愿公身健。\n更教剩活百来年。\n此老终须不枉、在人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13578, '醉落魄・一斛珠', '魏了翁', '无边春色。\n试从汉谕堂边觅。\n儿前上寿孙扶掖。\n九十娘娘，身是五朝客。\n眼前富贵浑闲历。\n个中真乐天然的。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13579, '水调歌头', '魏了翁', '古说士夫郡，犹欠殿头魁。\n记曾分付公等，行矣勉之哉。\n世事弈棋无定，甲子循还复尔，不免且低回。\n人物价自定，万事付衔杯。\n试与公，同握手，上春台。\n繁红丽紫何限，转首便尘埃。\n欲识化工定处，须向报秋时节，未用较先开。\n休道屋犹矮，卿相个中来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13580, '临江仙', '魏了翁', '天为西南分八使，更分四道蕃臣。\n争如齿宿彩衣新。\n亲年开百岁，又见子生孙。\n一度平反供一笑，无边桃李皆春。\n便归天上极恩荣。\n为君图寿母，去年曾以寿母图为献。\n更看太夫人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13581, '鹧鸪天', '魏了翁', '遥想庭闱上寿时。\n芝兰玉树俨成围。\n问娘鼎鼎修何行，一样都生及第儿。\n春淡沲，日熹微。\n两头娘子玉东西。\n一杯更为诸孙寿，子舍新来恰上楣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13582, '柳梢青', '魏了翁', '记得年年。\n阿奴碌碌，常在眼前。\n彩舫吴天，锦轮蜀地，阅尽山川。\n今年苦恋家园。\n便咫尺、千山万山。\n但想称觞，三荆树下，丛桂堂边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13583, '谒金门', '魏了翁', '那复有。\n气味於春酒。\n犹向故乡怀印绶。\n相过何日又。\n吐出心肠锦绣。\n问我阿娘依旧。\n娘亦祝君如柏寿。\n相看霜雪後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13584, '清平乐', '魏了翁', '蓝田玉种。\n为我酬清供。\n香压冰肌犹怕重。\n更倩留仙群捧。\n看花美倩偏工。\n举花消息方浓。\n此笑知谁领解，无言独倚东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13585, '清平乐', '魏了翁', '谁分天种。\n来上花供。\n绿叶素云姿雅重。\n那得愁心频捧。\n他花自是无工。\n不关香淡香浓。\n才问为谁含笑，盈盈靴面风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13586, '临江仙', '魏了翁', '双荔堂前呼大撇，蚪枝看取垂垂。\n帝怜尘土著冰姿。\n故教冻雨过，浴出万红衣。\n绿幄圆高下处，中含玉色清夷。\n人应笑太真肥。\n破除千古恨，须待谪仙诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13587, '浣溪沙', '魏了翁', '晓镜摇空髻耸丫。\n夜盘承露掌分叉。\n翠芳绰约总无华。\n欲往从之空怅望，潜虽伏矣莫藏遮。\n淤泥深处瑞莲花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13588, '浣溪沙', '魏了翁', '一日嘉名万口传。\n都凭新乐播芳鲜。\n非关呈瑞作人妍。\n地褊不妨金步稳，境幽生怕鼓声填。\n馀尊相与重留连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13589, '浣溪沙', '魏了翁', '密叶留香护境天。\n好风时雨媚清涟。\n亭亭双秀倚湖弦。\n造化曾居公掌握，呈祥宁许百花先。\n聊占棣萼蒂芳连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13590, '浣溪沙', '魏了翁', '试问伊谁若是班。\n二乔铜雀锁孱颜。\n千年痕露尚馀潸。\n羞向眼前供妩媚，独於静处惬幽娴。\n人情多少逐河间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13591, '贺新郎', '魏了翁', '只记来时节。\n又三年、朱炜过了，恰如时霎。\n独立薰风苍凉外，笑傍环湖花月。\n多少事、欲拈还辍。\n扶木之阴三千丈，远茫茫、无计推华发。\n容易过，三十八。\n此身待向清尊说。\n似江头、泛乎不系，扁舟一叶。\n将我东西南北去，都任长年旋折。\n风不定、川云如撇。\n惟有君恩浑未报，又故山、猿鹤催归切。\n将进酒，缓歌阕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13592, '满江红', '魏了翁', '物象芸芸，知几许、功夫来格。\n更时把、荷衣芰制，从容平熨。\n云淡天空诗献状，竹深花静机藏密。\n对窗前、屏岫老仪刑，真颜色。\n商古道，谁俦匹。\n评今士，谁钧敌。\n向平舟问雁，久间霜翮。\n枰上举棋元不定，磨边旋蚁何曾息。\n傥天公、有意要平治，饶华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13593, '念奴娇', '魏了翁', '修人物，元如许、谁把屏星留却。\n弄破峨眉山月影，似作平分消息。\n卷雾名谭，翳云长袖，未称三池客。\n且然袖手，人间烦暑方剧。\n分手未见前期，风前耿耿，目断斜阳角。\n亦欲乘风归去也，问讯故山猿鹤。\n鼓催鸡，挥弦送雁，转首成乖各。\n愿加饭，书来频寄新作。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13594, '贺新郎', '魏了翁', '久向闲边著。\n对沧江、烟轻日淡，雨疏云薄。\n一片闲心无人会，独倚团团羊角。\n便舍瑟、铿然而作。\n容室中间分明见，暮鸢飞、不尽天空阔。\n青山外，断霞末。\n看来此意无今昨。\n都不论、穷通得失，镇长和乐。\n此道舒之弥八极，卷却不盈一握。\n但长把、根基恢拓。\n将相时来皆可做，似君家、祖烈弥关洛。\n康国步，整戎略。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13595, '鹊桥仙', '魏了翁', '银潢濯月，金茎团露，一日清於一日。\n昨宵云雨暗河桥，似划地、不如今夕。\n乘查信断，机人去，误了桥边消息。\n天孙问我巧何如，正为怕、不曾陈乞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13596, '水调歌头', '魏了翁', '促织谁遣汝，唧唧不能休。\n揽衣起观，四顾河汉淡如油。\n露下南山荟蔚，风抹西湖菱芰，客感浩悠悠。\n尚此推不去，岁寿两公侯。\n自侯归，闲日月，几春秋。\n东方千骑，何事白首去为州。\n会有葛公清侣，携上神仙官府，玉案侍前旒。\n却袖经纶手，归伴赤松游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13597, '八声甘州', '魏了翁', '自王家无怨住襄城，世总生贤。\n似谢阶兰玉，马庭梧竹，一一堪怜。\n富贵关人何事，且问此何缘。\n又踏前朝脚，领蜀山川。\n点检重关复阁，尚甘棠匝地，乔木参天。\n中兴规画，父老至今传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13598, '贺新郎', '魏了翁', '此别情何限。\n最关情、一林醒石，重湖宾雁。\n几度南楼携手上，十二阑干凭暖。\n肯容我、樽前疏散。\n底事匆匆催人去，黯西风、别恨千千万。\n截不断，整仍乱。\n三年瞥忽如飞电。\n记从前、心情双亮，意词交划。\n千古黎苏登临意，人道於今重见。\n又分付、水流冰。\n满腹馀疑今谁问，上牛头、净拭乾坤眼。\n聊尔耳，恐不免。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13599, '贺新郎', '魏了翁', '多少龙头客。\n数从前、何官不做，清名难得。\n万里将归报汉，青锁还应催当夕。\n又一叶、扁舟去国。\n许史庐前车成雾，未如公、正怕云霄逼。\n留不尽，二三策。\n一声千里楼前笛。\n遏天涯、浮云不断，镇长秋色。\n试上层楼分明看，无数水遥山碧。\n问此意、有谁曾识。\n独抱孤衷苍茫外，满阑干，都是长安日。\n终有待，佐皇极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13600, '虞美人', '魏了翁', '一年一度屠苏酒。\n老我惊多又。\n明年岂是更无年。\n已是虚过、三十八年前。\n世间何物堪称好。\n家有斑衣老。\n相期他日早还归。\n怕似瞻由、出处不曾齐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13601, '念奴娇', '魏了翁', '岸容山意，随春好，人在春风独立。\n立尽闲云来又去，目断一天红日。\n岂不怀归，於焉信宿，此意无人识。\n只看鬓发，丝丝都为人白。\n风露正满人间，睡息，浑不知南北。\n要上南山披荟蔚，谁是同心相觅。\n天运无穷，事机难料，只有储才急。\n愿公寿考，养成元人物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13602, '朝中措', '魏了翁', '天公只解作丰年。\n不相冶游天。\n小队春旗不动，行庖晚突无烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13603, '洞庭春色・沁园春', '魏了翁', '花帽檐行，宝钗梁畔，还是上元。\n看去年芳草，如今又绿，当时皓月，此夕仍圆。\n节序驱人人不解，道岁岁年年都一般。\n看承处，有烛龙照夜，铁凤连天。\n东风不知倦客，又吹向楼阁山巅。\n任管弦闹处，诗豪得志，绮罗香里，侠少当权。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13604, '鹧鸪天', '魏了翁', '春漏逢欢恐不深。\n银花火树粲成林。\n酒中和乐无穷味，烛里光明一寸心。\n金马朔，玉堂寻。\n风流文献未如今。\n连宵坐我东风里，春满肝脾月满襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13605, '念奴娇', '魏了翁', '刘郎初度随春到，尚记彩衣春立。\n又上夫人千岁寿，相望不争旬日。\n琴瑟仪刑，山河态度，长是春风识。\n都将和气，蒸成满院红白。\n我被五斗红陈，三升官酒，驱到城北。\n解后相逢同一笑，此会几年难觅。\n宝蜡烧春，花光缟夜，未放觥筹急。\n天然真乐，傥来知是疣物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13606, '玉楼春', '魏了翁', '射洪官酒元曾醉。\n又六十八年重至。\n长江驿畔水如蓝，也应似、向人重翠。\n人生岂必高官贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13607, '贺新郎', '魏了翁', '谁主谁为客。\n叹人生、别离容易，会逢难得。\n省户高门十年梦，瞥忽浑如昨夕。\n风不定、乱云飞急。\n本自无心图富贵，也元知、富贵无缘逼。\n且还我，兔园策。\n谁知一曲柯亭笛。\n向天涯、依然解后，长安本色。\n怪我阿奶今老眼，已是看朱成碧。\n但犹记、黄裳曾识。\n多谢殷勤无以报，愿阿奶、长健如今日。\n送公子，上霄极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13608, '洞仙歌', '魏了翁', '人生一世。\n如此元如此。\n造化都从起时起。\n看庭前桃李，弄蕊开花，还又看，一度成阴结子。\n母寿亲认取，叶叶枝枝，一气分来结成底。\n更得故人书，遗我新词，把寸心、分明指似。\n信过眼、浮华几何时，剩培植根心，等闲千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13609, '西江月', '魏了翁', '曾记刘安鸡犬，误随鼎灶登仙。\n十年尘土行缠。\n怪见霞觞频劝。\n会合元非择地，乖逢宁得非天。\n妇闻风月正б娟。\n亲泼床头醅面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13610, '念奴娇', '魏了翁', '梦中犹记，来时路、五马踟蹰攒立。\n江北城南春澹沲，山锁一天晴日。\n伊轧征车，徊徨去意，只有东风识。\n如今还在，谁人伴我浮白。\n天外一曲阳春，依然有脚，来到萱堂北。\n不是奇情双照亮，肯寄鳞鸿相觅。\n酒引曹醇，歌翻楚调，触拨归心急。\n醉魂时绕，莺花世界风物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13611, '水调歌头', '魏了翁', '人道三十九，岁暮日斜时。\n儿今如许，才觉三十九年非。\n昨被玉山楼取，今仗牛山挽住，役役不知疲。\n自己未能信，漫仕亦何为。\n亦何为，应自叹，不如归。\n问归亦有何好，堂上彩成围。\n上下东冈南陌，来往北邻西舍，逖地看儿啼。\n富贵适然耳，此乐几人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13612, '蝶恋花', '魏了翁', '早岁腾身辇路。\n秋月春风，只作浑闲度。\n手挟雷公驱电母。\n袖中双剑蛟龙舞。\n如此壮心空浪许。\n四十明朝，忍把流年数。\n又过一番生日去。\n寿觞羞对亲朋举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13613, '醉蓬莱', '魏了翁', '又一番雨过，倚阁炎威，探支秋色。\n前度刘郎，为故园一出。\n黄发丝丝，赤心片片，俨中朝人物。\n诗里香山，酒中六一，花前康节。\n倦客才归，新亭恰就，萱径荫浓，卜林香发。\n尊酒相逢，看露花风叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13614, '江城子', '魏了翁', '水花湖荡翠连天。\n记年年。\n甚因缘。\n斗鸭阑干，云雾踏青妍。\n人似风流唐太白，披紫绮，卧青莲。\n如今别思浩如川。\n欲腾骞。\n隔风烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13615, '贺新郎', '魏了翁', '千里楼前客。\n数从前、几般契分，更谁同得。\n尚记流莺催人去，又见莎鸡当夕。\n叹天运、相煎何急。\n幸自江山皆吾土，被南薰、吹信还相逼。\n临大路，控长策。\n向来风月苏家笛。\n问天边、玉堂何似，黄冈秋色。\n万事无心随处好，风定一川澄碧。\n些个事、非公谁识。\n我亦年来知此意，但聪明、不及於前日。\n谁为我，指无极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13616, '满江红', '魏了翁', '许大才名，知几许、功夫做得。\n独自殿、三朝耆旧，岿然山立。\n出处只从心打当，去留不管人忻戚。\n抱孤衷、脉脉倚秋风，无人识。\n龙可养，凡鳞匹。\n鸾可挚，凡禽敌。\n便翩然归作，玉龙仙客。\n枰上举棋元不定，磨边旋蚁何曾息。\n傥天公、有意要平治，须华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13617, '江城子', '魏了翁', '一襟满贮梓城春。\n笑声频。\n笔挥银。\n自有江山，长是管将迎。\n不似如今归去客，云外步，水边身。\n萧然今代杰魁人。\n混光尘。\n越精神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13618, '江城子', '魏了翁', '如公何地不阳春。\n往来频。\n醉倾银。\n闻道河阳，童稚正欢迎。\n移向德威堂上著，疑潞国，是前身。\n行人还又送行人。\n夜无尘。\n对丰神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13619, '江城子', '魏了翁', '西来紫马倦行春。\n上书频。\n阙排银。\n愿听臣归，子舍便将迎。\n又为老臣全晚节，关教化，系臣身。\n帝心终眷老成人。\n想音尘。\n倍留神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13620, '江城子', '魏了翁', '与君同醉梓州春。\n不辞频。\n漏更银。\n尚记梅时，出郭喜相迎。\n又对西风斟别酒，云过眼，月分身。\n傥来官职不关人。\n等微尘。\n苦劳神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13621, '鹧鸪天', '魏了翁', '公在春官我已归。\n公来东蜀我居西。\n及公自遂移潼日，正我由潼使遂时。\n如有碍，巧相违。\n人生禁得几分飞。\n只祈彼此身长健，同处何曾有别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13622, '木兰花慢', '魏了翁', '记北人骑屋，看龙首、许仲元。\n自拥节来归，持荷直上，谁与争先。\n好官到头做彻，些儿欠缺便徒然。\n我爱庆元龙首，当春不逐时妍。\n人生天地两仪间。\n且住百来年。\n数初度庚寅，未来甲子，尽自宽闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13623, '木兰花慢', '魏了翁', '记薰风殿上，曾当暑、侍君王。\n看绛服临轩，白袍当殿，流汗翻浆。\n今年诏书催发，趁槐庭、初夏午阴凉。\n瘦马行时腊雪，叠猿啼处年光。\n大科异等士之常。\n难得姓名香。\n叹陋习相承，驹辕垂耳，麟楦成行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13624, '木兰花慢', '魏了翁', '问梅花月里，谁解唱、小秦王。\n向三叠声中，兰桡荃棹，桂醑椒浆。\n明朝濮渝江上，对暮云、平野北风凉。\n准拟八千里路，破除九十春光。\n砚涵槐影漾旗常。\n披拂御炉香。\n念人世难逢，玉阶方寸，陛颜行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13625, '西江月', '魏了翁', '一段同云似练，更无剩幅间边。\n玉娥不怕五更寒。\n剪就飞花片片。\n酒里吟边竞爽，枝头枝底争妍。\n入春无物不芳鲜。\n只我依然颜面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13626, '减字木兰花', '魏了翁', '新符旧历。\n交割新年馀七日。\n谁识春华。\n元住东川太守家。\n一年一曲。\n拟尽形容无可祝。\n愿似庭梅。\n长向春风伴斗魁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13627, '满江红', '魏了翁', '见说新来，把闲事、都齐阁束。\n日用处、浑无凝滞，天机纯熟。\n帘卷春风琴静好，庭移晓日兰芬馥。\n笑可曾，些子上眉头，萦心曲。\n吞宇宙，船明玉。\n批风月，诗成轴。\n问人间底处，升沈荣辱。\n与我言兮虽我愿，不吾以也吾常足。\n但年年、先後放灯时，新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13628, '海棠春令・海棠春', '魏了翁', '东君惯得花无赖。\n看不尽、冶容娇态。\n拟傍小车来，又被轻阴绐。\n阴晴长与随人改。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13629, '临江仙', '魏了翁', '自有天然真富贵，本来不为人妍。\n谨将醉眼著繁边。\n更擎高烛照，惊搅夜深眠。\n花不能言还自笑，何须有许多般。\n满空明月四垂天。\n柳边红沁露，竹外翠微烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13630, '朝中措', '魏了翁', '玳筵绮席绣芙蓉。\n客意乐融融。\n吟罢风头摆翠，醉馀日脚沈红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13631, '临江仙', '魏了翁', '去岁玉堂山下住，母旁後弟前哥。\n今年作县古松坡。\n静参朱祭酒，间印马头陀。\n去路更无山隔断，春风跋马经过。\n不妨缓辔尽婆娑。\n愿申临别语，长使得天多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13632, '柳梢青', '魏了翁', '昨夕相逢。\n烟苞沁绿，月艳羞红。\n旭日生时，初春景里，太极光中。\n别来三日东风。\n已非复、吴中阿蒙。\n须信中间、阴阳大造，雨露新功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13633, '小重山', '魏了翁', '养得儿男百不中。\n年年随举子，踏春风。\n寿觞庭院燕泥融。\n将雏处、长是半西东。\n移孝便为忠。\n儿行虽在远，母心同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13634, '南柯子・南歌子', '魏了翁', '暮雨收尘马，薰风起箨龙。\n夜凉人锁武成宫。\n却忆亲旁、寿饼荐油葱。\n谁锡诗人类，应颖谷封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13635, '眼儿媚', '魏了翁', '梦魂不踏正牙班。\n直作五云闲。\n简编真乐，埙篪雅韵，菽水清欢。\n都将瞥忽荣华事，春梦晓云看。\n只期他日，实愿受用，大耐高官。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13636, '眼儿媚', '魏了翁', '不居上界列仙班。\n梅隐寄幽闲。\n玉堂云晓，玉珍雨夜，总是真欢。\n如兄才誉居人上，鹏路正看看。\n只祈兄弟，长随母健，不爱高官。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13637, '洞仙歌', '魏了翁', '寿觞庭户，正柳明桃炫。\n拟斫江鱼脍银线。\n被春风吹入，花锦城中、惟有梦，时到轻轩翠。\n归来春已过，桃柳成阴，但喜庭闱镇强健。\n更得故人书，遗我瑰词，应重记、去年相见。\n望白鹤朱霞杳难攀，谩芳草如烟，青青河畔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13638, '鹧鸪天', '魏了翁', '夫子同年第太常。\n偶然二内亦同乡。\n其间更有真同处，道义场中无别香。\n花入思，绣为肠。\n不妨冬月作重阳。\n家人但歉今年会，犹欠腰金与鞠黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13639, '满江红', '魏了翁', '彼美人兮，不肯为、时人妆束。\n空自爱、北窗睡美，东邻醅熟。\n不道有人成离索，直教无计分膏馥。\n望鹤飞、不到暮云高，阑干曲。\n驹在谷，人金玉。\n盘在陆，人宽轴。\n笑吾今何苦，耐司空辱。\n应为嗷嗷乌反哺，真成落落蛇安足。\n到梓州、旧事上心来，呼杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13640, '眼儿媚', '魏了翁', '北风不竞帝师班。\n雨足桔槔闲。\n且容湖使，静中藏拙，忙里偷欢。\n一枰黑白终何若，未可目前看。\n自量愚分，不堪世用，只称田官。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13641, '洞庭春色・沁园春', '魏了翁', '四十之年，头颅如此，岂不自知。\n正东家尼父，叹无闻日，鄹人孟子，不动心时。\n顾我未能真自信，算三十九年浑是非。\n随禄仕，便加齐卿相，於我何为。\n人间郁蒸难耐，谁借我五万蒲葵。\n上玉台百尺，天连野□，□楼千里，江射晴晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13642, '水调歌头', '魏了翁', '冻雨洗烦浊，烈日霁威光。\n逸人去作太守，旗志倍精芒。\n莎外马蹄香湿，柳下阴晨润，景气踏苍苍。\n夹道气成雾，我独犯颜行。\n对颜行，斟尾酒，点头网。\n请君此，更伴顷刻笑谭香。\n为问锦屏富贵，孰与熙宁谏议，千古蔚仪章。\n世道正颓靡，此意傥毋忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13643, '洞庭春色・沁园春', '魏了翁', '安石声名，买臣富贵，我不敢知。\n谩扬州泛泛，浮湛随水，阊门轨轨，开阖从时。\n满目浮荣何与我，只赢得一场闲是非。\n诚知此，问不归何待，不饮胡为。\n岩松涧篁易老，应只能、采菽烹葵。\n看风沙漠漠，未清紫逻，烟云冉冉，时露晴晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13644, '鹧鸪天', '魏了翁', '内贵何妨知我希。\n芳荪纽佩石兰衣。\n不教尘外专云壑，准向人间驾使。\n忧国梦，绕端闱。\n静言思奋不能飞。\n时因风雨思畴昔，叹两苏公盍不归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13645, '水调歌头', '魏了翁', '桃李眩春昼，松柏傲霜时。\n春妍不必皆是，晚秀未为非。\n画斧河边瘴雾，叱驭关前险阻，马竭复人疲。\n胡不效侪等，趣取好官为。\n居之安，于胥乐，咏而归。\n毡裘舌成市，书史俨相围。\n月淡秋亭烽影，日静春斋铃索，未听杜鹃啼。\n美酒无深巷，莫道不吾知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13646, '小重山', '魏了翁', '开汉江山落手中。\n满门花粲阑，锦蒙戎。\n与人和气乐融融。\n应怜我，留滞剑南东。\n风味两文忠。\n恍如畴昔夜，一尊同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13647, '临江仙', '魏了翁', '闲放楼前千里目，天边云大如囤。\n秋风入帽露华新。\n无端忧国梦，应到守封臣。\n旧弼如今都有几，长教燕坐申申。\n折杨笑面背阳春。\n忧酲头欲雪，浊梦肺生尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13648, '水调歌头', '魏了翁', '三十作龙首，四十珥貂蝉。\n幡然携取名节，锦绣蜀山川。\n揽辔扶桑初晓，饮马咸池未旰，来日尽宽闲。\n兹事亦云足，所乐不存焉。\n女垂髫，儿分鼎，妇供鲜。\n尊章青鬓未改，和气玉生烟。\n造物犹嫌缺陷，要启公侯衮衮，又畀贾嘉贤。\n公更厚封植，自古有丰年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13649, '临江仙', '魏了翁', '七夕长留河汉女，重阳又属骚人。\n只馀八八号佳辰。\n中和无与拟，作一家春。\n俗事萦人何日了，随缘女嫁男婚。\n却将不系自由身。\n闲中书日月，随处弄儿孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13650, '贺新郎', '魏了翁', '旧日重阳日。\n叹满城，阑风去雨，寂寥萧瑟。\n造物翻腾新机杼，不踏诗人陈迹。\n都扫荡、一天云物。\n挟客凭高西风外，暮鸢飞、不尽秋空碧。\n真意思，浩无极。\n糕诗酒帽茱萸席。\n算今朝、无谁不饮，有谁真得。\n子美不生渊明老，千载寥寥佳客。\n无限事、欲忘还忆。\n金气高明弓力劲，正不堪、回首南山北。\n谁弋燕，问消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13651, '阮郎归', '魏了翁', '西风吹信趣征鞍。\n日高鸿雁寒。\n稻粱啄尽不留残。\n侬归阿那边。\n无倚著，只苍天。\n将心何处安。\n长教子骏满人间。\n犹令侬意宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13652, '浣溪沙', '魏了翁', '骊驹未撤客乘鞍。\n征鞭摇晚寒。\n雁边酲梦角惊残。\n关山斜日边。\n求道地，托恩天。\n人情久亦安。\n转移都在笑颦间。\n鄙夫应也宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13653, '浣溪沙', '魏了翁', '云外群鸿逐稻粱。\n独乘下泽少游乡。\n赤心片片为人忙。\n俗事萦缠何日了，自身活计孰为长。\n闭门书卷圣贤香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13654, '沁园春', '魏了翁', '惠我田畴，拯民水火，春满蜀东。\n更山连睥睨，长蛇隐雾，红移略约，睢霓横空。\n人卧流苏行席上，公心事夕阑晨枕中。\n长自苦，算无人识得，只有天公。\n天教百般如愿，也应是、天眼惺。\n看田间泥饮，门无夜打，水滨庐处，户有朝舂。\n拟上公堂，称兕爵酒，未抵人间春意浓。\n无可愿，愿城池永与，公寿无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13655, '水调歌头', '魏了翁', '宇宙一大物，掌握付诸人。\n人心不满方寸，北浩无垠。\n或者寒蝉自比，不尔秃犀贻笑，龊龊竟何成。\n胡不引贤者，相与共弥纶。\n未如何，尝试使，问苍。\n四时迭起代谢，有屈岂无伸。\n昨夜伶伦声里，一气排阴直上，阳德与时新。\n道长自今日，持此庆生申。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13656, '眼儿媚', '魏了翁', '乃翁表里玉无瑕。\n浑是得天多。\n一生受用，不完全处，都补填他。\n郎君心念和平处，似得十分家。\n天何以报，重重印字，滴滴檐窠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13657, '乌夜啼', '魏了翁', '不肯呈身觅举，那能随俗为官。\n梅花寒书窗月，一味漂阳酸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13658, '虞美人', '魏了翁', '无端嫁得龙头客。\n富贵长相迫。\n云深碧落记骖鸾。\n又逐东方千骑、到人间。\n妇前百拜儿称寿。\n季也参行酒。\n最怜小女太憨生。\n约住两头娘子、索新声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13659, '浪淘沙', '魏了翁', '老眼静中看。\n知我其天。\n纷纷得失了无关。\n花柳乾坤春世界，著我中间。\n世念久阑珊。\n随寓随安。\n人情犹望衮衣还。\n我愿时清无一事，尽使公闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13660, '浪淘沙', '魏了翁', '鹤外倚楼看。\n云晴天。\n天高鸡犬碍云关。\n掉臂双仙留不彻，还任人间。\n客佩振珊珊。\n来贺平安。\n年年直待卷灯还。\n似是天公偏著意，占破春闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13661, '木兰花令', '魏了翁', '儿前捧劝孙扶掖。\n共庆贺、娘娘七帙。\n此杯不比寻常，百年间、才是省陌。\n眼前彩绣成行立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13662, '醉落魄・一斛珠', '魏了翁', '才难如此。\n一门生许奇男子。\n长公更是惺惺底。\n千百年间，一寸心为纸。\n人知公在诗书里。\n天知公在诗书外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13663, '小重山', '魏了翁', '风雨移春醉梦中。\n忽然吹信息，堕泸戎。\n青炜风物换朱融。\n吾归矣，家在月明东。\n公等为人忠。\n年年称母寿，一尊同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13664, '临江仙', '魏了翁', '春院绣帘垂，一天风月横陈。\n慈亲初度纪嘉名。\n每从歌舞地，犹记杰魁人。\n大句忽随乌鹊至，恍如前岁逢春。\n只祈岁岁及兹辰。\n天风吹宝唾，华彩动文星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13665, '水调歌头', '魏了翁', '涪右金华宅，上有蔚蓝天。\n当年玉女何事，未摆世间缘。\n要把平夷心事，散作吉祥种子，春暖玉生烟。\n回首生处所，更欲与周旋。\n自归来，生处所，已三年。\n山头白鹤候我，应讶久留连。\n已作秋风归梦，忽递春风消息，吹我著泸川。\n安得且归去，绵上饱耕眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13666, '八声甘州', '魏了翁', '记幡然、持节下青云，巴月几成弦。\n待竹枝歌彻，讼棠匝地，扉草连天。\n却寻当年旧梦，来使蜀东川。\n人物寥寥甚，禁许回旋。\n愧我推挤不去，尚新官对旧，後任如前。\n与故人饮酒，月露写明蠲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13667, '贺新郎', '魏了翁', '霞下天垂宇。\n倚阑干、月华都在，大明生处。\n扶木元高三千丈，不分闲云无数。\n谩转却、人间朝暮。\n万古兴亡心一寸，只涓涓、日夜随流注。\n奈与世，不同趣。\n齐封冀甸今何许。\n百年间、欲招不住，欲推不去。\n闸断河流障海水，未放游鱼甫甫。\n叹多少、英雄尘土。\n挟客凭高西风外，问举头、还见南山否。\n花烂熳，草蕃庶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13668, '江城子', '魏了翁', '梦随瘦马渡晨烟。\n月犹弦。\n稻初眠。\n宇宙平宽，著我一人闲。\n梦破枇杷香满袂，应唤我，驻行鞯。\n王氏之门枇杷花正开。\n雁声砧杵落晴川。\n抚流年。\n叹区缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13669, '喜迁莺', '魏了翁', '鬓霜盈握。\n叹刍牧荒墟，稻粱衰索。\n落日牛羊，晚云鸿雁，傍地飞空无托。\n牧人困和雨睡，田父醉连云酌。\n醉梦未醒，虎嗥川谷，惊林薄。\n离别。\n谁不恶。\n心事同时，都不论离合。\n眼底时几，鼻端人物，谁辨北征东略。\n最怜世途局趣，只道书生疏阔。\n无可赠君，松阴庭院，菊华篱落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13670, '满江红', '魏了翁', '世道何常，都一似、水流云出。\n叹自古、燕巾滥宝，楚山迷璧。\n老我如今观变熟，行藏语嘿惟时适。\n似沧溟、容得乘禽飞，双凫集。\n花露晓，松风夕。\n经味永，山光吸。\n历岩中考第，案头月日。\n物欲强时心节制，才资弱处书扶掖。\n拟棕鞋、桐帽了平生，投簪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13671, '水调歌头', '魏了翁', '清燕卧霜角，月魄几回哉。\n一声云雁清叫，推枕赋归来。\n流水落花去路，画象棠阴陈迹，霄观傍楼台。\n别忆入梅艳，愁色上田莱。\n记来时，惊列缺，走吴回。\n人间都失匕箸，老婢亦惊猜。\n匹马晓风鞭袖，孤堞暮烟烽柝，辉却挂蛇杯。\n不负此邦去，笑口也应开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13672, '水调歌头', '魏了翁', '昨夜严家集，霜斗晴天。\n乾坤如许空阔，著我两人闲。\n醉帽三更月影，别袂一帘花气，语隽不知还。\n二十年间事，肝肺写明蠲。\n记相逢，一似昨，两经年。\n风波闹处，推出心胆至今寒。\n也为故人饮酒，也念邦人怀旧，姑为驻征鞍。\n未忍作离语，留待月华圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13673, '水调歌头', '魏了翁', '更尽一杯酒，春近武陵源。\n源头父老迎笑，人似老癯仙。\n检校露桃风叶，问讯渚莎江草，点检旧风烟。\n世界要人拄，公独卧闲边。\n叹从来，分宇宙，有山川。\n主宾均是寄耳，赢得鬓毛班。\n最苦中年相别，更是人才难得，相劝且加餐。\n归为玉昆说，时寄我平安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13674, '水调歌头', '魏了翁', '山岳会元气，初度首王春。\n扶持许大穹壤，全德付耆英。\n二万九千日力，四百八旬甲子，酿此杰魁人。\n玉剑卧霜斗，金锁挚天扃。\n学宗师，人气脉，国精神。\n不应闲处袖手，试与入经纶。\n磊落蟠溪感遇，迢递彭岁月，远到漆园椿。\n用舍关时运，一片老臣心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13675, '鹧鸪天', '魏了翁', '解后皇华并辔游。\n追随世好学风流。\n儿童拍手拦街笑，只是酸寒魏梓州。\n千炬烛，数声讴。\n不知白了几人头。\n惺两眼看来惯，且得人心乐便休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13676, '鹧鸪天', '魏了翁', '两便星前秉烛游。\n滔滔车马九河流。\n耳听宣政升平曲，目断炎兴未复州。\n闻鼓吹，强欢讴。\n被人送作遨头。\n凭谁为扫妖氛静，却与人间快活休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13677, '临江仙', '魏了翁', '一点阳和浑在里，时来尔许芳妍。\n春风吹上醉痕边。\n隽欢欺浅酌，清晤失佳眠。\n聊把繁华开笑口，须臾雨送风般。\n因花识得自家天。\n炯然长不夜，活处欲生烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13678, '柳梢青', '魏了翁', '庄敏传家，文安嫡胄，文惠诸孙。\n两大相辉，晋秦匹国，韩盈门。\n天风吹下双轩。\n恰趁得、酴牡丹。\n锦绣光中，殿春不老，阅岁长存。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13679, '蝶恋花', '魏了翁', '可煞潼人真慕顾。\n接得官时，只道来何暮。\n岁岁何曾得住。\n遂人又见迎将去。\n谩自儿曹相尔汝。\n心事同时，千里元相梧。\n况是棠阴随处处。\n秋江夜月春空雾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13680, '菩萨蛮', '魏了翁', '鸣蝉泊雨晴云湿。\n游龙翦岸涪江碧。\n气候尔和平。\n满家浑是春。\n公堂虽有酒。\n不敌公真有。\n寿宿对魁星。\n颊红衫鬓青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13681, '青玉案', '魏了翁', '中年怕踏长亭路。\n便自有、离愁苦。\n一自送君趋幕府。\n惺莺舌，呢喃燕觜，那解春无语。\n三年山月移朝暮。\n独倚松风等闲度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13682, '西江月', '魏了翁', '早厌人间腐鼠，要希云外飞皇。\n羲和不肯系朝阳。\n任向鬓边来往。\n出谷声中气味，编蒲册里晶光。\n至今心胆为渠狂。\n梦倚银潢天上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13683, '水调歌头', '魏了翁', '牛酒享宾客，焦烂列前荣。\n有人先事早计，残突伴孤星。\n香火家家绘象，鼓村村祠宇，翦不断人情。\n清泪九皋鹤，唤起梦魂惺。\n白苹洲，芳草渡，玉湖亭。\n画帘挂起簌，一卷易同盟。\n携手锦江箍隐，觌面墨池玄叟，扶杖蜀君平。\n三老冁然笑，云散太空清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13684, '临江仙', '魏了翁', '红杏花边曾共赏，天涯还是相逢。\n人言契分两重重。\n谁知声利外，别有一般同。\n炯炯奇情双亮处，天光水色相通。\n磨中旋蚁渺何穷。\n共扶天事业，此意政须公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13685, '临江仙', '魏了翁', '千里楼高人与并，个中彻地通天。\n秋风吹发半成宣。\n都将强岁月，空对旧山川。\n养就人才端有意，公今三祖差肩。\n偏轻偏重几番船。\n要公常把，容我老闲边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13686, '临江仙', '魏了翁', '占断人间闲富贵，长秋应是长春。\n前山推月上帘旌。\n缓觞旧友，勾拍按新声。\n时倚晴空看过雁，几州明月关情。\n知君早已倦青冥。\n时来那得免，事业一窗萤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13687, '满江红', '魏了翁', '逢著公卿，谁不道、人才难得。\n须认取、天根一点，几曾休息。\n未问人间多少士，一门男子头头立。\n只其间、如许广文君，谁人识。\n冠盖会，渔樵席。\n豪气度，清标格。\n要安排稳当，讲帷词掖。\n蜀泮堂堂元不恶，犹嫌偏惠天西壁。\n嘱公卿、著眼看乾坤，搜人物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13688, '千秋岁引', '魏了翁', '天生耆德，占断四时先。\n春院落，锦山川。\n万家灯市明朱紫，一庭花艳傍貂蝉。\n妇承姑，翁抱息，子差肩。\n匝是、文公开九帙。\n陆续看、武公逾九十。\n从九九，到千千。\n海风谩送天鸡舞，蛰雷未唤壑龙眠。\n且从他，歌缓缓，鼓咽咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13689, '醉落魄・一斛珠', '魏了翁', '无边春色。\n人情苦向南山觅。\n村村箫鼓家家笛。\n祈麦祈蚕，来趁元正七。\n翁前子後孙扶掖。\n商行贾坐农耕织。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13690, '南乡子', '魏了翁', '连夕雨盈畴。\n先为农家做麦秋。\n更放年头晴甲子，知不。\n应是天公及尔游。\n随事与民求。\n又与随时验乐忧。\n民气乐时天亦好，休休。\n为尔簪花插满头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13691, '水调歌头', '魏了翁', '千古峨眉月，照我别离杯。\n故人中岁聚散，脉脉若为怀。\n醉帽三更风雨，别袂一帘山色，为放笑眉开。\n握手道旧故，抵掌论人才。\n山中人，灶间婢，亦惊猜。\n江头新涨催发，欲去重裴回。\n世事丝丝满鬓，岁月匆匆上面，渴梦肺生埃。\n酒罢听客去，公亦赋归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13692, '水调歌头', '魏了翁', '舣棹汉嘉口，更尽渭城杯。\n凌云山色，似为行客苦伤怀。\n横出半天烟雨，锁定一川风景，未放客船开。\n想见此楼上，阅尽蜀人才。\n山猿鹤，江鸥鹭，亦相猜。\n滔滔日夜东注，全璧几人回。\n客亦莞然成笑，多少醉生梦死，转首总成埃。\n信屈四时耳，寒暑往还来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13693, '满江红', '魏了翁', '风引舟来，恰趁得、东楼嘉集。\n正满眼、轻红重碧，照筵浮席。\n更是姓黄人作守，重新墨妙亭遗迹。\n对暮天、疏雨话乡情，更筹急。\n嗟世眼，迷朱碧。\n矜气势，才呼吸。\n彼蔡章安在，千年黄笔。\n腐鼠那能凤吓，怒蜩未信冥鹏翼。\n与史君、酌酒酹兴亡，浇今昔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13694, '水调歌头', '魏了翁', '烟雨敛江色，江水大於杯。\n蓬窗一枕霄梦，忽忽到无怀。\n苦被江头新涨，推起天涯倦客，万里片帆开。\n收用到我辈，天下岂无才。\n路漫漫，行又止，信还猜。\n渊鱼得失有分，须载月明回。\n寄语鹤山亲友，若访吾庐花柳，为我扫烟埃。\n去去党无辱，振袂早归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13695, '卜算子', '魏了翁', '江横山簇。\n柏箭森如束。\n满眼飞蓬撩乱，知几几、未膏沐。\n快意忽破竹。\n一奁明翠玉。\n千古江山只麽，人都道、为君绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13696, '贺新郎', '魏了翁', '风定波纹细。\n夜无尘、云迷地轴，月流天位。\n摇裔飞来江山鹤，犹作故乡嘹唳。\n清境里、伴人无睡。\n应叹余生舟似泛，浪涛中、几度身尝试。\n书有恨，剑无气。\n从渠俗耳追繁吹。\n抚空明、一窗寒簟，对人如砥。\n梦倚银河天外立，云露惺惺满袂。\n看多少、人间嬉戏。\n要话斯心无分付，路茫茫、还有亲朋至。\n应为我，倒洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13697, '卜算子', '魏了翁', '携月上南楼，月已穿云去。\n莫照峨眉最上峰，同在峰前住。\n东望极青齐，西顾穷商许。\n酒到忧边总未知，犹认胡床处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13698, '卜算子', '魏了翁', '能得几时留，王事催人去。\n翠荡涵空酒满船，苦要留人住。\n身世两悠悠，飘泊知何许。\n但得心亲志合时，都是相逢处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13699, '卜算子', '魏了翁', '风雨满空霏，总得江山妙。\n洗出湖光镜似明，不受纤尘。\n心事竟堪凭，天意真难料。\n呼吸丰年倾刻间，也合轩渠笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13700, '水调歌头', '魏了翁', '昨梦鹤山去，风景逐时新。\n藕花拍满栏槛，松竹被池频。\n尽日兄酥弟酪，触处言鲭义，相对只翁卿。\n梦觉帝乡远，有酒为谁倾。\n忽飞来，天外句，梦中人。\n自怜何事，强把麋鹿裹朝绅。\n坐看九衢车马，鞭策长安日月，檐阁太玄经。\n只说来时节，金气已高明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13701, '木兰花慢', '魏了翁', '恰秋光四十，箕斗外、月初弦。\n笑浅濑平芜，寒城小市，掌许山川。\n半生梦魂不到，与君侯、岁岁此周旋。\n鞍马空销髀肉，兜牟未换貂蝉。\n人生天地两仪间。\n须住百馀年。\n数重卦三三，後天八八，来日千千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13702, '水调歌头', '魏了翁', '九十九峰下，百二十年州。\n西风吹起客梦，月满驿南楼。\n影入天河左界，辰在寿星向上，还是去年秋。\n要和木兰曲，载酒寿君侯。\n天边信，云外步，去难留。\n寿觞庭院依旧，已带别离愁。\n离合锺情未免，行止关人何事，浪白世间头。\n将相时来作，身健百无忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13703, '水调歌头', '魏了翁', '犹记端门外，鞭袖五更寒。\n一声天上钟柝，金锁挚重关。\n君向紫宸上阁，我侍玉皇香案，都号舍人般。\n梦觉帝乡远，相对两苍颜。\n玉围腰，金系肘，绣笼鞯。\n乡人衮衮严近，五马度荆山。\n收拾五湖气度，卷束蟠胸兵甲，春意满人间。\n天锡公纯嘏，气象自平宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13704, '鹧鸪天', '魏了翁', '日上午头度岁辰。\n黄钟吹龠煦乾坤。\n弦歌堂上三称寿，风月亭前又见君。\n人似旧，景长新。\n明朝六桂侍双椿。\n蛮邦父老惊曾见，得似君家别有春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13705, '满江红', '魏了翁', '月上南箕，还认得、去年星历。\n知谁把、一天星象，荡摩朝昔。\n若使平生浑自弃，如今老大何嗟及。\n更年来、偏得钝工夫，蹉跎力。\n溪瘴碍，蛮烟隔。\n穹壤断，江山窄。\n纵燕巾滥宝，楚山囚玉。\n小小穷通都未问，忍闻同气相煎急。\n诵虞郎、百字短长诗，忧何极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13706, '鹧鸪天', '魏了翁', '谁把璇玑运化工。\n参旗又挂玉梅东。\n三三律声馀亥，九九玄经卦起中。\n新岁月，旧游从。\n一觞还似去年冬。\n人间事会无终极，分付翘关老令公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13707, '菩萨蛮', '魏了翁', '东窗五老峰前月。\n南窗九叠坡前雪。\n推出侍郎山。\n著君窗户间。\n离骚乡里住。\n恰记庚寅度。\n挹取芷兰芳。\n酌君千岁觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13708, '念奴娇', '魏了翁', '被东风吹送，都看尽、蜀三川。\n向涪水西来，东山右去，剑阁南旋。\n家家露餐风宿，数旬间、浑不见炊烟。\n踏遍王孙草畔，眼明帝子城边。\n万家赤子日高眠。\n丝管夜喧阗。\n自梓遂而东，岷峨向里，汉益从前。\n人人里歌涂咏，愿君侯、长与作蕃宣。\n我愿时清无事，早归相伴华颠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13709, '贺新郎', '魏了翁', '幸有天遮蔽。\n为西南、空虚一面，挺生男子。\n塞下将军支颐卧，夜半揽衣推起。\n扫十万、胡人如洗。\n见说巴山马退，也都因、粮运如流水。\n剑以北，一人耳。\n十年梦断斜阳外。\n恰归来、昌蒲蘸酒，祝兄千岁。\n入从出藩谁不是。\n谁是难兄难弟。\n正乐意、融融未已。\n莫趣东方千骑去，愿时平、华皓长相对。\n闲富贵，只如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13710, '水调歌头', '魏了翁', '高氏八千古，驺哄溢街坊。\n庸夫俗子，夸道锦绣裹家乡。\n谁识书生心事，各要济时行己，肯顾利名场。\n用我吾所欲，不用亦何伤。\n汉嘉守，凡阅历，几麾幢。\n便教入从出节，都是分之常。\n但愿国安人寿，更只专城也好，不用较强梁。\n准拟耆英会，倚杖看人忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13711, '水调歌头', '魏了翁', '风雪锢迁客，闭户紧蒙头。\n一声门外剥啄，客有从予游。\n直自离骚国里，行到林闾屋畔，万里入双眸。\n世态随炎去，此意澹於秋。\n感毕逋，怀秸鞠，咏夫不，寻师学道虽乐，吾母有离忧。\n岁晚巫云峡雨，春日楚烟湘月，诗思满归舟。\n来日重过我，应记火西流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13712, '摸鱼儿', '魏了翁', '记年时、三星明处。\n尊前携手相语。\n家山幸有瓜和芋。\n何苦投身官府。\n谁知道，尚随逐风华，为蜀分南土。\n依前廉取。\n便卷却旌麾，提将绣斧。\n天口笑应许。\n逢初度。\n从头要为君数。\n怕君惊落前箸。\n天东扶木三千丈，不照关河烟雨。\n谁砥柱。\n想造物生才，肯恁无分付。\n九州风露。\n待公等归来，为清天步。\n容我赋归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13713, '水调歌头', '魏了翁', '尚记春归日，锦绣裹江城。\n谁推日驭西去，水认故乡痕。\n鱼鸟自飞自跃。\n红紫谁开谁落。\n天运渺无声。\n四序镇如此，当富复亭亭。\n是何年，修禊事，畅幽情。\n竞传元已天气，别是一般清。\n便引郑郊溱洧。\n不道孔门沂泗。\n大道掌如平。\n待挽迷津者，都向此中行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13714, '唐多令', '魏了翁', '轻露濯秋风，新楼插太空。\n更遭逢、解事天公。\n为唤羲和驱六马，将杲日、挂帘栊。\n日影正沈红。\n须臾月在东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13715, '唐多令', '魏了翁', '朔雪上征衣。\n春风送客归。\n万杨华、数点榴枝。\n春事无多天不管，教烂熳、住离披。\n开谢本同机。\n荣枯自一时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13716, '水调歌头', '魏了翁', '堪怪两外府，使传载朝缨。\n虽云身在江表，都号汉公卿。\n莫是才堪世用，莫是有人吹送，中外尔联荣。\n天运自消息，龙蠖不关情。\n更寻思，谁得失，孰亏成。\n潜鱼要向深渺，犹恐太分明。\n且愿时清无事，长把书生阁束，归践对床盟。\n强似抗尘俗，岁岁上陪京。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13717, '水调歌头', '魏了翁', '天地一大物，扶植要人才。\n人才谁是，不肯随俗强追陪。\n与我言兮我愿。\n莫我知兮谁怨。\n全仗帝为媒。\n此意久寥阔，今见者留台。\n笏围腰，书创屋，骑笼街。\n时贤白尽须发，老子抑名斋。\n更取堂名淇绿。\n要把北山万竹。\n一日倚云栽。\n自处只如此，将相任时来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13718, '唐多令', '魏了翁', '人物盛乾淳。\n东嘉最得人。\n费江山、几许精神。\n我已後时犹遍识，君子子、又相亲。\n秋入塞垣新。\n风寒上醉痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13719, '木兰花慢', '魏了翁', '正秋阴盛处，忽荡起、一冰轮。\n甚汉魏从前，才人胜士，断简残文。\n都无一词赏玩，更拟将、美色似非伦。\n此意谁能领会，自夸光景长新。\n得阴多处倍精神。\n俗眼转增明。\n向大第高楼，痴儿呆女，脆竹繁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13720, '八声甘州', '魏了翁', '被西风吹不断新愁。\n吾归欲安归。\n望秦云苍，蜀山渺，楚泽平漪。\n鸿雁依人正急，不奈稻粱稀。\n独立苍茫外，数遍群飞。\n多少曹苻气势，只数舟燥苇，一局枯棋。\n更元颜何事，花玉困重围。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13721, '玲珑四犯', '李从周', '初拨琵琶，未肯信，知音真个稀少。\n尽日芳情，萦系玉人怀抱。\n须待化作杨花，特地过、旧家池沼。\n想绮窗、刺绣迟了，半缕茜茸微绕。\n旧时眉妩贪相恼。\n到春来、为谁浓扫。\n新归燕子都曾识，不敢教知道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13722, '抛球乐', '李从周', '风荐红雨易晴。\n病花中酒过清明，绮窗幽梦乱於柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13723, '谒金门', '李从周', '花似匝。\n两点翠蛾愁压。\n人又不来春且恰。\n谁留春一霎。\n消尽水沈金鸭。\n写尽杏笺红蜡。\n可奈薄情如此黠。\n寄书浑不答。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13724, '一丛花令・一丛花', '李从周', '梨花随月过中庭。\n月色冷如银。\n金闺平帖阳台路，恨酥雨、不扫行云。\n妆褪臂闲，髻慵簪卸，盟海浪花沈。\n洞箫清吹最关情。\n腔拍懒温寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13725, '风流子', '李从周', '双燕立虹梁。\n东风外、烟雨湿流光。\n望芳草云连，怕经南浦，葡萄波涨，怎博西凉。\n空记省，浅妆眉晕敛，袖唾痕香。\n春满绮罗，小莺捎蝶，夜留弦索，么凤求凰。\n江湖飘零久，频回首、无奈触绪难忘。\n谁信温柔牢落，翻坠愁乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13726, '清平乐', '李从周', '美人娇小。\n镜里容颜好。\n秀色侵人春帐晓。\n郎去几时重到。\n叮咛记取儿家。\n碧云隐映红霞。\n直下小桥流水，门前一树桃花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13727, '风入松', '李从周', '霜风连夜做冬晴。\n晓日千门。\n香葭暖透黄钟管，正玉台、彩笔书云。\n竹外南枝意早，数花开对清樽。\n香闺女伴笑轻盈。\n倦绣停针。\n花砖一线添红景，看从今、迤逦新春。\n寒食相逢何处，百单五个黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13728, '乌夜啼', '李从周', '径藓痕沿碧，檐花影压红阑。\n今年春事浑无几，游冶懒情悭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13729, '清平乐', '李从周', '东风无用。\n吹得愁眉重。\n有意迎春无意送。\n门外湿云如梦。\n韶光九十悭悭。\n俊游回首关山。\n燕子可怜人去，海棠不分春寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13730, '鹧鸪天', '李从周', '绿色吴笺覆古苔。\n濡毫重拟赋幽怀。\n杏花帘外莺将老，杨柳楼前燕不来。\n倚玉枕，坠瑶钗。\n午窗轻梦绕秦淮。\n玉鞭何处贪游冶，寻遍春风十二街。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13731, '宴清都', '卢祖皋', '春讯飞琼管。\n风日薄、度墙啼鸟声乱。\n江城次第，笙歌翠合，绮罗香暖。\n溶溶涧渌冰泮。\n醉梦里、年华暗换。\n料黛眉重锁隋堤，芳心还动梁苑。\n新来雁阔云音，鸾分槛影，无计重见。\n啼春细雨，笼愁澹月，恁时庭院。\n离肠未语先断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13732, '鱼游春水', '卢祖皋', '离愁禁不去。\n好梦别来无觅处。\n风翻征袂，触目年芳如许。\n软红尘里鸣鞭镫，拾翠丛中句伴侣。\n都负岁时，暗关情绪。\n昨夜山阴杜宇。\n似把归期惊倦旅。\n遥知楼倚东风，凝颦暗数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13733, '倦寻芳', '卢祖皋', '香泥垒燕，密叶巢莺，春晦寒浅。\n花径风柔，著地舞红软。\n斗草烟欺罗袂薄，秋千影落春游倦。\n醉归来，记宝帐歌慵，锦屏香暖。\n别来怅、光阴容易，还又酴，牡丹开遍。\n妒恨疏狂，那更柳花迎面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13734, '江城子', '卢祖皋', '画楼帘幕卷新晴。\n掩银屏。\n晓寒轻。\n坠粉飘香，日日唤愁生。\n暗数十年湖上路，能几度，著娉婷。\n年华空自感飘零。\n拥春酲。\n对谁醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13735, '江城子', '卢祖皋', '护霜云日霭晴空。\n锦围中。\n卷香风。\n弄玉乘鸾，人自蕊珠宫。\n天遣岁寒为伴侣，还待得，谪仙翁。\n等闲随处是春功。\n笑相从。\n寸心同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13736, '江城子', '卢祖皋', '小山初筑自天成。\n架危亭。\n与云平。\n面面梅花，阑槛十分清。\n唤得长淮春意满，香暗度，月微明。\n数枝长忆傍岩扃。\n杖履轻。\n醉中行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13737, '西江月', '卢祖皋', '燕掠晴丝袅袅，鱼吹水叶粼粼。\n禁街微雨洒香尘。\n寒食清明相近。\n漫著宫罗试暖，闲呼社酒酬春。\n晚风帘幕悄无人。\n二十四番花讯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13738, '画堂春', '卢祖皋', '玉屏回梦月平谰。\n元来香冷衣单。\n柳风特地更将寒。\n吹上眉端。\n云羽未回征雁，镜花空舞双鸾。\n去年芳径又斓斑。\n门掩春闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13739, '画堂春', '卢祖皋', '柳黄移上袂罗单。\n酒醒娇风鬟。\n茗瓯才试鹧鸪斑。\n沈炷熏残。\n夜雨可无归梦，晓风何处征鞍。\n海棠开了尚凭阑。\n划地春寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13740, '画堂春', '卢祖皋', '柳塘风紧絮交飞。\n漾花一水平池。\n暖香飘径日迟迟。\n何处酴。\n胡蝶梦中寒浅，杜鹃声里春归。\n镜容不似旧家时。\n羞对清溪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13741, '清平乐', '卢祖皋', '镜屏开晓。\n寒入宫罗峭。\n脉脉不知春又老。\n帘外舞红多少。\n旧时驻马香阶。\n如今细雨苍苔。\n残梦不堪重理，一双胡蝶飞来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13742, '清平乐', '卢祖皋', '柳边深院。\n燕语明如翦。\n消息无凭听又懒。\n隔断画屏双扇。\n宝杯金缕红牙。\n醉魂几度儿家。\n何处一春游荡，梦中犹恨杨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13743, '清平乐', '卢祖皋', '玉肌春瘦。\n别凤离鸾後。\n柳外画船看翠袖。\n眼艳风流依旧。\n杏梁语燕绸缪。\n可堪前梦悠悠。\n几度欲成花雨，断云还过南楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13744, '清平乐', '卢祖皋', '朔风凝冱。\n不放云来去。\n稚柳回春能几许。\n一夜满城飞絮。\n羊羔酒面频倾。\n护寒香缓娇屏。\n唤取雪儿对舞，看他若个轻盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13745, '乌夜啼', '卢祖皋', '几曲微风按柳，生香暖日蒸花。\n鸳鸯睡足芳塘晚，新绿小窗纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13746, '乌夜啼', '卢祖皋', '照水飞禽斗影，舞风小径低花。\n征鸿排尽相思字，音信落谁家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13747, '乌夜啼', '卢祖皋', '柳色津头泫绿，桃花渡口啼红。\n一春又负西湖醉，离恨雨声中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13748, '乌夜啼', '卢祖皋', '漾暖纹波，吹晴丝雨。\n轻衫短帽西湖路，花气扑春骢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13749, '乌夜啼', '卢祖皋', '段段寒沙浅水，萧萧暮雨孤篷。\n香罗不共征衫远，砧杵客愁中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13750, '谒金门', '卢祖皋', '风不定。\n移去移来帘影。\n一雨林塘新绿净。\n杏梁归燕并。\n翠袖玉屏金镜。\n日薄绮疏人静。\n心事一春疑酒病。\n鸟啼花满径。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13751, '谒金门', '卢祖皋', '兰棹举。\n相趁落红飞去。\n一隙轻帘凝睇处。\n柳丝牵不住。\n昨日翠蛾金缕。\n今夜碧波烟渚。\n好梦无凭窗又雨。\n天涯知几许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13752, '谒金门', '卢祖皋', '间院宇。\n独自行来行去。\n花片无声帘外雨。\n峭寒生碧树。\n做弄清明时序。\n料理春酲情绪。\n忆得归时停棹处。\n画桥看落絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13753, '谒金门', '卢祖皋', '深院静。\n隔叶鸣禽相应。\n金鸭云寒闲梦醒。\n转帘花月影。\n闲步碧阶香径。\n翠残红慵整。\n明日阴晴犹未定。\n试教移小艇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13754, '谒金门', '卢祖皋', '寒半退。\n斜掩小屏珠翠。\n柳眼才醒桃欲醉。\n日高帘影碎。\n暗解鸳鸯罗带。\n独立晚风谁会。\n心事悠悠人好在。\n画桥流水外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13755, '谒金门', '卢祖皋', '人寂寞。\n帘外翠阴如幄。\n团扇藤床花间错。\n雨边残梦觉。\n翠浅粉销香薄。\n临镜不梳掠。\n新恨悠悠无处托。\n棋声闲院落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13756, '谒金门', '卢祖皋', '闲睡足。\n冰柱乱敲寒玉。\n簇簇庭阴嘉树绿。\n晚蝉声断续。\n一雨藕花新浴。\n香破小窗幽独。\n重理焦桐寻旧曲。\n隔墙风动竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13757, '谒金门', '卢祖皋', '香漠漠。\n低卷水风池阁。\n玉腕笼纱金半约。\n睡浓团扇落。\n雨後凉生云薄。\n女伴棹歌声乐。\n采得双莲迎笑剥。\n柳阴多处泊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13758, '谒金门', '卢祖皋', '秋几许。\n荒蓼败荷烟渚。\n贴水飞鸥江欲暮。\n风帆追急羽。\n蝶梦转头无据。\n愁到曲屏深处。\n寒入双城扃绣户。\n也应闻细雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13759, '谒金门', '卢祖皋', '罗袖褪。\n短鬓独搔谁恨。\n叶叶秋声风衮衮。\n万端心一寸。\n钗凤镜鸾谁问。\n想见粉香啼损。\n倩尽飞鸿终未稳。\n夜来寒陡顿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13760, '鹧鸪天', '卢祖皋', '纤指轻拈小砑红。\n自调宫羽按歌童。\n寒馀芍药阑边雨，香落酴架底风。\n闲意态，小房栊。\n丁宁须满玉西东。\n一春醉得莺花老，不似年时怨玉容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13761, '鹧鸪天', '卢祖皋', '庭绿初圆结荫浓。\n香沟收拾旧梢红。\n池塘少歇鸣蛙雨，帘幕轻回舞燕风。\n春又老，笑谁同。\n澹烟斜日小楼东。\n相思一曲临风笛，吹过云山第几重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13762, '鹧鸪天', '卢祖皋', '岸柳黄深绿已垂。\n庭院红遍白还飞。\n几回画蜡银台梦，双字香罗金缕衣。\n山浅澹，水茫弥。\n顿无消息许多时。\n杏梁知有新来燕，下却重帘不放归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13763, '踏莎行', '卢祖皋', '夜雨灯深，春风寒浅。\n梅姿雪态怜娇软。\n锦笺闲轴旧缄情，酒边一顾清歌遍。\n玉局弹愁，冰弦写怨。\n几时纤手教重见。\n小楼低隔一街尘，为谁长恁巫山远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13764, '相思引', '卢祖皋', '陆续鸣鸠呼晓晴。\n霏微残雾湿春城。\n未成梅雨，先做麦寒轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13765, '相思引', '卢祖皋', '夹岸垂杨步障深。\n露桥横截影沈沈。\n数家篱落，一晌晚凉侵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13766, '眼儿媚', '卢祖皋', '玉钩清晓上帘衣。\n香雾湿春枝。\n馀寒逗雨，罗裙无赖，重暖金猊。\n柳边谁寄东风缆，流水只年时。\n无人为记，天涯归思，梁燕空飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13767, '更漏子', '卢祖皋', '玉钩裁，罗袜浅。\n心事漫拈针线。\n钗半，鬓慵梳。\n新来消瘦无。\n江南路。\n花无数。\n春梦不知何处。\n帘影转，瞑禽西。\n看看眉黛低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13768, '更漏子', '卢祖皋', '蓼花繁，桐叶下。\n寂寂梦回凉夜。\n城角断，砌蛩悲。\n月高风起时。\n衣上泪。\n谁堪寄。\n一寸妾心千里。\n人北去，雁南征。\n满庭秋草生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13769, '锦园春三犯・锦园春', '卢祖皋', '昼长人倦。\n正凋红涨绿，懒莺忙燕。\n丝雨晴，放珠帘高卷。\n神仙笑宴。\n半醒醉、彩鸾飞遍。\n碧玉阑干，青油幢幕，沈香庭院。\n洛阳图画旧见。\n向天香深处，犹认娇面。\n雾霞绡，闻绮罗裁翦。\n情高意远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13770, '锦园春三犯・锦园春', '卢祖皋', '醉痕潮玉。\n爱柔英未吐，露丛如簇。\n绝艳矜春，分流芳金谷。\n风梳雨沐。\n耿空抱、夜阑清淑。\n杜老情疏，黄州赋冷，谁怜幽独。\n玉环睡醒未足。\n记传榆试火，高照宫烛。\n锦幄风翻，渺春容难续。\n迷红怨绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13771, '水龙吟', '卢祖皋', '杜鹃啼老春红，翠阴满眼愁无奈。\n飞来何处，凤鸾驭，霞裾云佩。\n风槛娇凭，露梢慵，酒浓微退。\n念洛阳人去，香魂又返，依然是，风流在。\n银烛光摇彩翠。\n画堂深、莫辞沈醉。\n十年一觉，扬州春梦，离愁似海。\n浩态难留，粉香吹散，几时重会。\n向尊前笑折，一枝红玉，帽檐斜戴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13772, '水龙吟', '卢祖皋', '荡红流水无声，暮烟细草黏天远。\n低回倦蝶，往来忙燕，芳期顿懒。\n绿雾迷墙，翠虬腾架，雪明香暖。\n笑依依欲挽，春风教住，还疑是，相逢晚。\n不似梅妆瘦减。\n占人间、丰神萧散。\n攀条弄蕊，天涯犹记，曲阑小院。\n老去情怀，酒边风味，有时重见。\n对枕帏空想，东床旧梦，带将离恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13773, '水龙吟', '卢祖皋', '会昌湖上扁舟，几年不醉西山路。\n流光又是，宫衣初试，安榴半吐。\n千里江山，满川烟草，薰风淮楚。\n念离骚恨远，独醒人去，阑干外，谁怀古。\n亦有鱼龙戏舞。\n艳晴川、绮罗歌鼓。\n乡情节意，尊前同是，天涯羁旅。\n涨渌池塘，翠阴庭院，归期无据。\n问明年此夜，一眉新月，照人何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13774, '水龙吟', '卢祖皋', '世间谁似蓬仙，坐间八帙齐眉寿。\n兰阶更喜，孙枝相映，红芳绿秀。\n鹤舞修庭，鹭飞青嶂，帘垂晴昼。\n向闲中时有，奚囊背锦，开松户，看云岫。\n不羡印金垂斗。\n笑纷纷、白云苍狗。\n银髯似戟，红颜如炼，风流依旧。\n野□晴初，陇梅花下，玉笙吹酒。\n怅今年又是，题笺寄远，倩传杯手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13775, '渡江云', '卢祖皋', '锦云香满镜，岸巾横笛，浮醉一舟轻。\n别愁萦短鬓，晚凉池阁，此地忽逢迎。\n柄圆绿，倚风流、还恁娉婷。\n凭画阑，嫣然输笑，无语寄心情。\n盈盈。\n露华匀玉，日影酣红，记晚妆慵整。\n还暗惊、人间离合，羞对池萍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13776, '洞仙歌', '卢祖皋', '玉肌翠袖，较似酴瘦。\n几度熏醒夜窗酒。\n问炎洲何事，得许清凉，尘不到，一段冰壶翦就。\n晚来庭户悄，暗数流光，细拾芳英黯回首。\n念日暮江东，偏为魂销，人易老、幽韵清标似旧。\n正簟纹如水帐如烟，更奈向，月明露浓时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13777, '洞仙歌', '卢祖皋', '月痕霜晕，雪染冰裁翦。\n车马尘中甚曾见。\n自扬州吟罢，踏遍西湖，堪爱处，偏是情高韵远。\n冷香惊梦破，姑射人归，图画空遗旧妆面。\n问何事东君，先与春心，还又是、容易飞花片片。\n对暮寒修竹哽无言，更画角层城，夜闻吹怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13778, '洞仙歌', '卢祖皋', '东楼佳丽，缥缈风烟表。\n幻得楼山更深窈。\n有苍崖乔木，石磴鸣泉，尘不到，掩映十洲三岛。\n平生丘壑趣，圭衮何心，自是清时重元老。\n想月下云根，鹤唳猿吟，人犹道、作计归游太早。\n待他年功退学商颜，却旋种木奴，缓寻瑶草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13779, '洞仙歌', '卢祖皋', '梅窗雪屋，还赋蓬仙寿。\n闻说今年胜於旧。\n有芝书催下，竹史颁春，山好处，留待文章太守。\n商霖消息近，缥缈闲云，一笑无心又出岫。\n纵高卧十年，八帙初开，天未许、闲向人间袖手。\n问西州千骑几时来，对月鹤霜猿，也教知否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13780, '洞仙歌', '卢祖皋', '扁舟入浙，便有家山意。\n全胜轺车驾边地。\n爱官尘不到，书眼争明，称寿处，春傍梅花影里。\n平生丘壑志，未老求闲，天亦徘徊就归计。\n想叠嶂双溪，千骑弓刀，浑不似、白石山中胜趣。\n怕竹屋梅窗欲成时，又飞诏东山，谢公催起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13781, '望江南・忆江南', '卢祖皋', '疏雨过，芳节到戎葵。\n缠臂细交纹线缕，称身初试碧绡衣。\n闲步小亭池。\n花下意，脉脉有谁知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13782, '临江仙', '卢祖皋', '南馆西池迎笑处，轻行不耐冰绡。\n粉香飞过碧阑桥。\n芙蕖争态度，杨柳学飘摇。\n醉里鸾飙乘月去，碧云依旧迢迢。\n深情谁为寄娇娆。\n簟纹风外展，香篆过边销。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13783, '临江仙', '卢祖皋', '洞府堂深花气满，娉婷绿展红围。\n个中年少出琼姬。\n双笼金约腕，独把玉参差。\n子晋台前无鹤驭，人间空有清诗。\n何如娇小贮帘帷。\n仙风知有待，凉月渐当时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13784, '临江仙', '卢祖皋', '跨鹤云间犹未久，风流全胜年时。\n唤回和气上梅枝。\n酒边春市动，琴外画帘垂。\n长是细吟攻愧寿，还歌连桂新词。\n早催凫向南飞。\n一官传鼎鼐，四海看埙篪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13785, '丑奴儿慢・采桑子慢', '卢祖皋', '湘筠展梦，还是带恨枕。\n对千顷、风荷凉艳，水竹清阴。\n半掩龟纱，几回小语月华侵。\n娉婷何处，回首画桥，朱户沈沈。\n闻道近时，题红传素，长是沾襟。\n想当日、冰弦弹断，总废清音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13786, '木兰花慢', '卢祖皋', '汀莲凋晚艳，又苹末、起秋风。\n漫搔首徐吟，微云河汉，疏雨梧桐。\n飘零倦寻酒盏，记那回、歌管小楼中。\n玉果蛛丝暗卜，细钗蝉鬓轻笼。\n吴云别後重重。\n凉宴几时同。\n纵人间信有，犀灵鹊喜，密意难通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13787, '木兰花慢', '卢祖皋', '洒窗声未定，怪襟袖、峭寒欺。\n渐邑界空明，山河表里，玉幻琼移。\n天边占春最早，万花中、不遣一尘飞。\n清想吟鞭瘦倚，醉怜歌锦红围。\n谁知。\n未去心期。\n慵酒更慵诗。\n算可人惟有，光浮茗碗，香浸梅枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13788, '木兰花慢', '卢祖皋', '嫩寒催客棹，载酒去、载诗归。\n正红叶漫山，清泉漱石，多少心期。\n三生溪桥话别，怅薜萝、犹惹翠云衣。\n不似今番醉梦，帝城几度斜晖。\n鸿飞。\n烟水弥弥。\n回首处，只君知。\n念吴江鹭忆，孤山鹤怨，依旧东西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13789, '木兰花慢', '卢祖皋', '翠阴春昼永，乍帘幕、暖飘香。\n正玉节来归，斑衣戏舞，□□荧煌。\n椿期始开九秩，看芝兰、奕叶早传芳。\n都把一门瑞气，酿成九酝霞觞。\n相将。\n诏墨趣星郎。\n乐事未渠央。\n渐锦封鸾诰，鱼轩象服，争贲萱堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13790, '木兰花慢', '卢祖皋', '向蒲江佳处，报新葺、小亭轩。\n有碧嶂青池，幽花瘦竹，白鹭苍烟。\n年华再周甲子，对黄庭、心事只け然。\n都占壶天岁月，便成行地神仙。\n十年。\n微禄萦牵。\n梦绕浙东船。\n更吾庐才喜，篱尽剖，门巷初全。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13791, '浣溪沙', '卢祖皋', '午睡醒来策瘦筇。\n几痕茸绿径苔封。\n石榴初□舞裙红。\n中酒情怀滋味薄，肥梅天气带衣慵。\n日长门巷雨馀风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13792, '卜算子', '卢祖皋', '续续露蛩鸣，索索风梧语。\n瘦骨从来不奈秋，一夜秋如许。\n簟冷卷风漪，髻滑抛云缕。\n展转无人共此情，画角吹残雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13793, '卜算子', '卢祖皋', '双鬓晚风前，一笛秋云外。\n木叶飞时看好山，山亦於人耐。\n意到偶题诗，饮少先成醉。\n笑折花枝步短檐，此意无人会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13794, '卜算子', '卢祖皋', '佩解洛波遥，弦冷湘江渺。\n月底盈盈误不归，独立风尘表。\n窗绮护幽妍，瓶玉扶轻袅。\n别後知谁语素心，寂寞山寒峭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13795, '卜算子', '卢祖皋', '寒谷耿春姿，遥夜乘幽兴。\n忆得和香载月归，醉里清魂醒。\n霜月解随人，不解将疏影。\n想见江南万斛愁，云卧衣裳冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13796, '满庭芳', '卢祖皋', '盘谷居成，辋川图就，便从鸥鹭寻盟。\n泛溪窈窕，游钓寄高情。\n尚忆儿童旧地，疏帘外、烟雨新晴。\n微吟罢，渔歌响答，乃醉中听。\n蓬瀛。\n归计早，下帆坐阅，涛浪堪惊。\n爱闲身长占，风澹波平。\n夜雪何时访戴，梅花下、同款柴扃。\n还知否，清时未许，野渡有舟横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13797, '夜行船', '卢祖皋', '暖入新梢风又起。\n秋千外、雾萦丝细。\n鸠侣寒轻，燕泥香重，人在杏花窗里。\n十二银屏山四倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13798, '瑞鹤仙', '卢祖皋', '江南秋欲遍。\n正莼际鲈分，酒边螯荐。\n青林雁霜浅。\n问风流何事，试华偏晚。\n凌波步远。\n误池馆、薰风笑宴。\n梦回时，细翦荷衣，尚倚半酣妆面。\n深院。\n绮霞低映，步障横陈，暮天慵倦。\n无言笑倩。\n尊前恨，仗谁遣。\n似重来鹤驭，锦城依旧，无复仙风宛转。\n念疏星澹月，长眉甚时再见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13799, '菩萨蛮', '卢祖皋', '芙蓉香卸桐阴薄。\n水窗未雨凉先觉。\n何处理秋裳。\n月高砧杵长。\n袂罗新恨悄。\n展转屏山晓。\n长是卷帘时。\n翠禽相对飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13800, '菩萨蛮', '卢祖皋', '烛房花幌参差见。\n疏帘镇日萦愁眼。\n巫峡小山屏。\n梦云犹未成。\n带霜边雁落。\n双字宫罗薄。\n二十四阑干。\n夜来相对寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13801, '菩萨蛮', '卢祖皋', '翠楼十二阑干曲。\n雨痕新染蒲桃绿。\n时节又黄昏。\n东风深闭门。\n玉箫吹未彻。\n窗影梅花月。\n无语只低眉。\n闲拈双荔枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13802, '鹊桥仙', '卢祖皋', '寒丛弄日，宝钿承露，篱落亭亭相倚。\n当年彭泽未归来，料独抱、幽香一世。\n疏风冷雨，澹烟残照，日日重阳天气。\n帽檐已是半斜，问瓮里、新熟未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13803, '鹊桥仙', '卢祖皋', '槐阴暑，荷风清梦，满院双成俦侣。\n阶庭一笑玉兰新，把酒更、重逢初度。\n丹书漫启，青云垂上，莫忘八篇奇语。\n功成休驾玉霄云，且长占、赤城佳处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13804, '鹊桥仙', '卢祖皋', '澄江晓碧，君山秋静，人与江山俱秀。\n最声吹下紫泥封，看宣献、风流依旧。\n□袍对引，鱼轩徐驾，小队旌旗陪後。\n万家指点寿星明，更把菊、登高时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13805, '摸鱼儿', '卢祖皋', '怪西风、晓来帽，年华还是重九。\n天机衮衮山新瘦，客子情怀谁剖。\n微雨後。\n更雁带边寒，袅袅欺罗袖。\n慵荷倦柳。\n悄不似黄花，田田照眼，风味尽如旧。\n登临地，寂寞崇台最久。\n阑干几度搔首。\n翻云覆雨无穷事，流水斜阳知否。\n吟未就。\n但衰草荒烟，商略愁时候。\n闲愁浪有。\n总输与渊明，东篱醉舞，身世付杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13806, '夜飞鹊慢', '卢祖皋', '骄嘶破清晓，分恨临期。\n花下恁月明知。\n馀光是处散离思，最怜香霭霏霏。\n牵衣弹泪，问凄风愁露，划地东西。\n留鞭换佩，怕匆匆、已是迟迟。\n凉怯几番罗袂，还燕别文梁，萤点书帏。\n一自秋娘迢递，黄金对酒，争忍轻挥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13807, '秋霁', '卢祖皋', '虹雨才收，正抱叶残蝉，渐老云木。\n银汉飞星，玉壶零露，万里素秋如沐。\n倚颦抱独。\n盼娇曾记郎心目。\n向艳歌偏爱，赋情多处寄衷曲。\n凄凉漫有，旧月阑干，夜凉无因，重照颓玉。\n扇纨收、鸾孤蠹损，一番愁绪黯相触。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13808, '虞美人', '卢祖皋', '清尊黄菊红萸佩。\n两度云岩醉。\n帽檐今日更清狂。\n冷雨疏风、著意过重阳。\n故宫历历遗烟树。\n往事知何处。\n漫山秋色好题诗。\n吟罢阑干、独自立多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13809, '渔家傲', '卢祖皋', '小阁腾腾人似醉。\n鸣阶簌簌霜林坠。\n起向楼头看雪意。\n云犹未。\n雁声一片江风起。\n官里从容何日是。\n偷闲著便寻幽事。\n见说小桥清浅水。\n梅欲蕊。\n吟边陡觉添风味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13810, '渔家傲', '卢祖皋', '檐玉敲寒声不定。\n水仙瓶里梅相映。\n半缕篝香云欲暝。\n窗几静。\n月华时送琅影。\n不用五湖寻小艇。\n吾庐剩有闲风景。\n薄醉起来行藓径。\n多幽兴。\n悠然一霎风吹醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13811, '渔家傲', '卢祖皋', '白石山中风景异。\n先生日日怀归计。\n何事黄冈飞雪地。\n偏著意。\n画堂却为东坡起。\n人说前身坡老是。\n文章气节浑相似。\n只待鼎彝勋业遂。\n梅花外。\n归来长向山中醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13812, '醉梅花・鹧鸪天', '卢祖皋', '传得西林一派清。\n年华垂过欠官称。\n居无多地花常好，客有来时鹤自鸣。\n分蕊馆，驻星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13813, '贺新郎', '卢祖皋', '挽住风前柳。\n问鸱夷、当日扁舟，近曾来否。\n月落潮生无限事，零乱茶烟未久。\n漫留得、莼鲈依旧。\n可是从来功名误，抚荒祠、谁继风流後。\n今古恨，一搔首。\n江涵雁影梅花瘦。\n四无尘、雪飞风起，夜窗如昼。\n万里乾坤清绝处，付与渔翁钓叟。\n又恰是、题诗时候。\n猛拍阑干呼鸥鹭，道他年、我亦垂纶手。\n飞过我，共尊酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13814, '沁园春', '卢祖皋', '几叶凋枫，半篙寒日，傍桥系船。\n爱洞门深锁，人间福地，双溪分占，天上星躔。\n破帽寒，短鞭敲月，此地经行知几年。\n空赢得，似沈郎消瘦，还欠诗篇。\n沙鸥伴我愁眠。\n向水驿风亭红蓼边。\n有村醪可饮，且须同醉，溪鱼堪，切莫论钱。\n笠泽波头，垂虹桥上，橙蟹肥时霜满天。\n相随否，算江南江北，惟有君闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13815, '沁园春', '卢祖皋', '台色齐辉，一点长庚，夜来更明。\n渐日添宫线，功催补衮，春回梅萼，香趁调羹。\n鹤禁班高，槐庭恩重，八帙人共荣。\n谁知道，纵身居公辅，心似书生。\n东楼见说初成。\n有帘卷江山万里横。\n想高情长羡，碧云出处，清时未计，绿野经营。\n东阁郎君，南宫进士，管领孙枝扶寿觥。\n齐眉醉，笑尊前乐事，真个全并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13816, '贺新郎', '卢祖皋', '十顷涵空碧。\n画图中、峥嵘幻玉，乱零吹璧。\n倚遍危阑吟不尽，把酒风前岸帻。\n记当日、西湖为客。\n谁翦吴淞江上水，笑乾坤、奇事成儿剧。\n还照我，夜窗白。\n崇台目断清无极。\n引枝筇、琼瑶步软，印登临屐。\n娃馆娉婷知何在，泪粉愁浓恨积。\n故化作、飞花狼籍。\n旧事悠悠浑莫问，有玉蟾、醉里曾相识。\n聊伴我，夜吹笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13817, '贺新郎', '卢祖皋', '万里岷峨路。\n笑归来、野逸萧闲，旧时风度。\n玉陛金闺春引处，迟却京华步武。\n漫赢得、西湖佳趣。\n香篆琴丝帘影外，有朝云、夜月和鸥鹭。\n都辨我，醉中句。\n飞凫又报匡庐去。\n怕赤霄、班里依然，有人留取。\n头黑功名浑好在，漫浪从渠赋予。\n但爱我、襟期相遇。\n满把一觞为君寿，有风荷、万顷摇清暑。\n聊为此，金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13818, '太常引', '卢祖皋', '梦回金井卸梧桐。\n嘶马带疏钟。\n草面露痕浓。\n渐薄袖、清寒暗通。\n天低绛阙，云浮碧海，残月尚朦胧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13819, '小阑干・少年游', '卢祖皋', '露华深酿古香浓。\n一树□云丛。\n窗间试与，闲培秋事，聊寄幽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13820, '倚阑令・春光好', '卢祖皋', '惜春心。\n步花阴。\n怕春深。\n风扬游丝吹落絮，满园林。\n日长帘幕沈沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13821, '满江红', '卢祖皋', '楼倚晴空，炎云净、晚来风力。\n沧海外、等闲吹上，满轮寒璧。\n河汉低垂天欲近，乾坤浩荡秋无极。\n凭阑干、衣袂拂青冥，知何夕。\n登眺地，追畴昔。\n吴越事，皆陈迹。\n对清光祗有，醉吟消得。\n万古悠悠惟月在，浮生衮衮空头白。\n自骑鲸、仙去有谁知，遥相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13822, '满江红', '卢祖皋', '拟问扁舟，归来趁、蓬莱寿席。\n还又向、月城迢递，岁寒为客。\n多竹襟期居已就，一川图画□堪觅。\n想玉笙、霜鹤拥蹁跹，真仙伯。\n身早退，头翻黑。\n心最懒，闲偏适。\n更新来膝下，始看袍色。\n安石正多人望在，子公何用缄书立。\n但年年、把酒为梅花，寻消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13823, '烛影摇红', '卢祖皋', '千载风云，庆符良月先呈瑞。\n旧家阴郭帝恩浓，圭衮公侯地。\n不道蝉联鼎贵。\n对秋灯、依然风味。\n紫囊归去，绿野闲来，青毡都未。\n琴鹤相随，小山花竹便幽意。\n满襟和气是藏春，日觉诗名起。\n已动金瓯姓字。\n早梅□，□□□□。\n□□□□，□□□□，□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13824, '月城春・四犯翦梅花', '卢祖皋', '五云腾晓。\n望凝香画戟，恍然蓬岛。\n玉露冰壶，照神仙风表。\n诗书坐啸。\n唤淮楚、满城春好。\n雨谷催耕，风帘戏鼓，家家欢笑。\n南湖细吟未了。\n看金莲夜直，丹凤飞诏。\n鬓影青青，办功名多少。\n持杯满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13825, '临江仙', '卢祖皋', '六鹤飞来松帐晓，菊迟梅早年光。\n西池移宴到萱堂。\n笙箫清弄玉，环佩暖回香。\n未问诰花金五色，新来乐事难量。\n双添雏凤趁称觞。\n争书八十字，分抱彩衣旁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13826, '贺新郎', '卢祖皋', '春色元无主。\n荷东君、著意看承，等闲分付。\n多少无情风与浪，又那更、蝶欺蜂妒。\n算燕雀、眼前无数。\n从便帘栊能爱护，到如今、已是成迟暮。\n芳草碧，遮归路。\n看看做到难言处。\n怕宣郎、轻转旌旗，易歌襦裤。\n月满西楼弦索静，云蔽城阆府。\n便恁地、一帆轻举。\n独倚阑干愁拍碎，惨玉容、泪眼如红雨。\n去与住，两难诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13827, '喜迁莺', '孙居敬', '宿酲初愈。\n更花焰频催，叶蕉重举。\n浓露沾丛，薰风入樾，黄叶马头飞舞。\n梦结尚依征旆，笛怨谁教渔谱。\n村路转，见寒机灯在，晨炊人语。\n无据。\n堪恨处。\n残月满襟，不念人羁旅。\n天接山光，云拖雁影，多少别离情绪。\n绣被香温密叠，罗帕粉痕重护。\n这滋味，最不堪两鬓，菱花羞觑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13828, '临江仙', '孙居敬', '触事老来情绪懒，西湖债未曾还。\n试呼小艇访孤山。\n昔年鸥鹤侣，总笑鬓斓斑。\n仙去坡翁山耐久，烟霏空翠凭阑。\n日斜尚觉酒肠宽。\n水云天共色，乃一声间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13829, '临江仙', '孙居敬', '摘索枝头何处玉，吹来万里春风。\n须臾陆地遍芙蓉。\n珠帘和气扑，一笑夺炉红。\n文字红裙相间出，主人钟鼎仙翁。\n清谈隽语与香浓。\n太平欢意远，人在玉壶中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13830, '贺新郎', '孙居敬', '风月为佳节。\n更湖光、平铺十里，水晶宫阙。\n若向孤山邀俗驾，只恐梅花凄咽。\n有图画、天然如揭。\n好看骚人冰雪句，走龙蛇、醉墨成三绝。\n尘世事，谩如发。\n真须脚踏层冰滑。\n倚高寒、身疑羽化，水平天阔。\n目送云边双白鹭，杳杳冲烟出没。\n□□□、□□□□。\n唤醒儿曹梁甑梦，把逍遥、齐物从头说。\n洗夜光，弄明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13831, '风入松', '孙居敬', '王孙去後几时归。\n音信全稀。\n绿痕染遍天涯草，更小红、已破桃枝。\n此恨无人共说，梦回月满楼时。\n只应明月照心期。\n一向舒眉。\n若还早遂蓝桥约，更不举、玉盏东西。\n怎望黄金屋贮，只图夸道于飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13832, '风入松', '孙居敬', '画梁燕子报新归。\n好语全稀。\n庭芳侵亚红相对，却羞见、蕊蕊枝枝。\n说与吹箫旧侣，痴心指望多时。\n朝云暮雨失欢期。\n碧画谁眉。\n凝愁立处桐阴转，又还是、红日将西。\n谩道梅花纸帐，鸳鸯终待双飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13833, '好事近', '孙居敬', '买断一川云，团结樵歌渔笛。\n莫向此中轻说，污天然寒碧。\n短蓬穿菊更移枨，香满不须摘。\n搔首断霞夕影，散银原千尺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13834, '西江月', '孙居敬', '翠幄轻寒护夜，寒妆靓暖宜春。\n酒筹诗令逐时新。\n仙佩朋簪清兴。\n凤炬呈妍粟粟，水仙照座盈盈。\n约君策马贺升平。\n回首尊前风韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13835, '八声甘州', '郑梦协', '大江流日夜，客心愁、不禁晚来风。\n把英雄□气，兴衰馀事，吹散无踪。\n但有山围故国，依旧夕阳中。\n直北神州路，几点飞鸿。\n欲问周郎赤壁，叹沙沈断戟，烟锁艨艟。\n听波声如语，空乱荻花丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13836, '蝶恋花', '真德秀', '两岸月桥花半吐。\n红透肌香，暗把游人误。\n尽道武陵溪上路。\n不知迷入江南去。\n先自冰霜真态度。\n何事枝头，点点胭脂污。\n莫是东君嫌淡素。\n问花花又娇无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13837, '满江红', '留元刚', '风送清篙，沿流溯、武夷九曲。\n回首处，虹桥无复，幔亭遗屋。\n翠壁云屏临钓石，银河雪瀑飞寒玉。\n想当年、铁笛倚林吹，秋空绿。\n褰荇带，筇竹。\n披荷芰，餐椒菊。\n问丹崖碧岭，底堪重辱。\n青笈不妨娱老眼，乌靴未许污吾足。\n恰仙游、一枕梦醒来，胡麻熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13838, '朝中措', '熊节', '麒麟早贵挂朝冠。\n自合侍金銮。\n收拾经纶事业，从容游戏人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13839, '沁园春', '范炎', '襟韵何如，文雅风流，王谢辈人。\n问传家何物，多书插架，放怀无可，有酒盈樽。\n一咏一谈，悠然高致，似醉当年曲水春。\n还知否，壮胸中万卷，笔下千军。\n门前我有佳宾。\n但明月、清风更此君。\n喜西庐息驾，心间胜日，东皇倚杖，目送行云。\n闻道君王，玉堂佳处，欲诏长杨奏赋孙。\n功名看，一枝丹桂，两树灵椿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13840, '水调歌・水调', '汪相如', '指点江水，遥认作琼醅。\n介公眉寿，年年倾入紫霞杯。\n寿与江流无尽，人在壶天不老，谈笑领春回。\n昨夜瞻南极，列宿拱中台。\n补天工，取日手，济时材。\n不应勇退，归来绿野宴瑶台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13841, '贺新郎', '张敬斋', '卓茕欧阳子，是江山、毓秀锺灵，异才间世。\n恰则韶光三月暮，叶尧阶有四。\n正天启、悬弧盛事。\n金鸭亭亭书云篆，散非烟、南极真仙至。\n来为尔，荐嘉瑞。\n神清洞府丹书字。\n拥笙歌、绮席高张，更罗珠翠。\n个里长春人不老，仙籍玉环暗记。\n但判取、沈醉。\n拟作新诗八千首，待一年、一献称俾尔。\n耆而艾，昌而炽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13842, '瑞鹧鸪', '徐照', '雨多庭石上苔文。\n门外春光老几分。\n为把旧书藏宝带，误翻残酒湿绡裙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13843, '南歌子', '徐照', '帘影筛金线，炉烟篆翠丝。\n菰芽新出满盆池。\n唤起玉瓶添水、养鱼儿。\n意取钗虫碧，慵梳髻翅垂。\n相思无处说相思。\n笑把画罗小扇、觅春词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13844, '清平乐', '徐照', '绿围红绕。\n一枕屏山晓。\n怪得今朝偏起早。\n笑道牡丹开了。\n迎人卷上珠帘，小螺未拂眉尖。\n贪教玉笼鹦鹉，杨花飞满妆奁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13845, '阮郎归', '徐照', '绿杨庭户静沈沈。\n杨花吹满襟。\n晚来闲向水边寻。\n惊飞双浴禽。\n分别後，忍登临。\n暮寒天气阴。\n妾心移得在君心。\n方知人恨深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13846, '玉楼春', '徐照', '萤飞月里无光色。\n波水不摇楼影直。\n每怜宿粉啼痕，懒把旧书观字迹。\n枯荷露重时闻滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13847, '渔家傲', '可', '曾讲弥陀经十遍。\n孤山疏钞频舒卷。\n事理圆融文义显。\n多方便。\n到头只劝生莲苑。\n本性弥陀随体现。\n唯心净土何曾远。\n十万程途从事见。\n休分辨。\n临终但自亲行转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13848, '渔家傲', '可', '我佛莲华随步踏。\n黄金妙相青螺发。\n因地曾将洪誓发。\n四十八。\n众生尽度成菩萨。\n宫殿红香华影合。\n宝阶三道琉璃阔。\n水鸟树林皆念法。\n声嘈。\n空中零乱天华撒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13849, '渔家傲', '可', '彼土因何名极乐。\n莲华九品无三恶。\n虽有频伽并白鹤。\n非彰灼。\n如来变化宣流作。\n九品一生离五浊。\n自然身挂珠璎珞。\n宛转白毫生额角。\n长辉烁。\n百千业障都消却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13850, '渔家傲', '可', '佛赞西方经现在。\n广长舌相三千界。\n为要众生生信解。\n临终迈。\n不修净业犹何待。\n七宝池塘波一派。\n莲华朵朵车轮大。\n华内托生真自在。\n分三辈。\n阿跋致长无退。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13851, '渔家傲', '可', '鹦鹉频伽知几只。\n音声和雅鸣朝夕。\n演畅五根并五力。\n令人忆。\n心飞恨不身生翼。\n从是西方十万亿。\n山长水远谁人识。\n唯是观门归路直。\n真消息。\n坐澄劫水琉璃碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13852, '渔家傲', '可', '清净乐邦吾本郡。\n娑婆流浪因贪吝。\n冉冉思归霜入鬓。\n深嗟恨。\n塞鸿不解传音信。\n落日尽边沙隐隐。\n向西望处归应近。\n天乐是时相接引。\n宜精进。\n紫金台上谁无分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13853, '渔家傲', '可', '理性本来长自在。\n灵通昭彻光无碍。\n因被无明风恼害。\n真如海。\n等闲吹动波千派。\n五蕴山头云。\n遮藏心月无光彩。\n六贼会须知悔改。\n除贪爱。\n刹那跳出娑婆界。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13854, '渔家傲', '可', '为厌娑婆求净土。\n驰情送想存朝暮。\n谁信不劳移一步。\n西方去。\n楼台隐隐云深处。\n珠网为光华作雨。\n金沙布地无尘土。\n怎不教人思去路。\n心专注。\n坐观落日如悬鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13855, '渔家傲', '可', '四相相催生病老。\n死魔不定朝难保。\n争似寅昏持佛号。\n西方好。\n树林水鸟称三宝。\n磨灭等闲髭鬓皓。\n乐邦行计唯宜早。\n万亿国邦非远道。\n休烦恼。\n一弹指顷能行到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13856, '渔家傲', '可', '人世罪冤知底数。\n前程不是无冥府。\n争似静焚香一炷。\n无行住。\n声声称念弥陀父。\n罪业尽消生有处。\n弥陀愿力堪凭据。\n十念一心存旦暮。\n西方路。\n功成足步红莲去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13857, '渔家傲', '可', '万事到头无益已。\n寻思只有修行是。\n若送此心游宝地。\n还容易。\n坐观落日当西坠。\n万顷红光归眼际。\n眼开眼闭长明媚。\n此观成时知法味。\n心欢喜。\n临终决定生莲里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13858, '渔家傲', '可', '西望乐邦云杳隔。\n一钩新月弯弯白。\n意欲往生何计策。\n劳魂魄。\n弥陀一念声千百。\n金殿玉楼为屋宅。\n七重行树强松柏。\n华里托生非血脉。\n真高格。\n乐天不是蓬莱客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13859, '渔家傲', '可', '富贵经中谈净域。\n赤珠玛瑙为严饰。\n彼土众生当晓色。\n擎衣。\n妙华供养他方佛。\n稚小嬉游随没溺。\n娑婆是苦何曾识。\n忻厌迩来方有力。\n从朝夕。\n静焚一炷香凝碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13860, '渔家傲', '可', '文墨尖新无处用。\n已将名利浑如梦。\n一串数珠随手弄。\n休千种。\n唯闻念佛心欢勇。\n漾空中仙乐动。\n笙箫声细天风送。\n接引凡夫归圣众。\n香云捧。\n男儿此日方崇重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13861, '渔家傲', '可', '休纵心猿驰意马。\n牢将系念绳头把。\n说破十疑因智者。\n争传写。\n庐山又结莲华社。\n十八大贤居会下。\n功成五色云西驾。\n诸上善人都在那。\n相迎迓。\n聚头只说无生话。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13862, '渔家傲', '可', '三十六般包一袋。\n脓囊臭秽犹贪爱。\n恰似蜣螂推粪块。\n无停待。\n朝朝只在尘中め。\n若解坚心生重悔。\n宁拘恶逆并魁脍。\n一念能消千劫罪。\n生华内。\n满身璎珞鸣珂佩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13863, '渔家傲', '可', '一点神魂初托魄。\n青莲华里琉璃宅。\n毫相法音非间隔。\n虽明白。\n到头不似金台客。\n九品高低随报获。\n或经劫数华方拆。\n若是我生心性窄。\n应煎迫。\n未开须把莲华擘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13864, '渔家傲', '可', '净土故乡嗟乍别。\n天涯流浪经时节。\n老去染沾眉鬓雪。\n思归切。\n闻声愿寄辽天月。\n念念时时修净业。\n临终佛定来迎接。\n有誓表为诚实说。\n广长舌。\n三千遍覆红莲叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13865, '渔家傲', '可', '善导可嗟今已往。\n化来老少皆归向。\n佛念一声分一镪。\n声才响。\n一声一佛虚空上。\n八万四千奇妙相。\n光明寿命皆无量。\n金色臂垂千万丈。\n鹅王掌。\n誓来迎接归安养。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13866, '渔家傲', '可', '西土纹成东土壤。\n星飞一点千华界。\n勿讶神魂生去快。\n无遮碍。\n乐邦只在同居内。\n八德池深华又大。\n跏趺端坐莲华载。\n耳听法音心悟解。\n低头拜。\n从今跳出胞胎外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13867, '望江南・忆江南', '净圆', '娑婆苦，长劫受轮回。\n不断苦因离火宅，祗随业报入胞胎。\n辜负这灵台。\n朝又暮，寒暑急相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13868, '望江南・忆江南', '净圆', '娑婆苦，身世一浮萍。\n蚊蚋睫中争小利，蜗牛角上窃虚名。\n一点气难平。\n人我盛，日夜长无明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13869, '望江南・忆江南', '净圆', '娑婆苦，情念骤如风。\n六贼村中无暂息，四蛇箧内更相攻。\n谁是主人公。\n无慧力，爱网转关笼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13870, '望江南・忆江南', '净圆', '娑婆苦，生老病无常。\n九窍腥臊流秽污，一包脓血贮皮囊。\n争弱又争强。\n随妄想，耽欲更荒唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13871, '望江南・忆江南', '净圆', '娑婆苦，终日走尘寰。\n不觉年光随逝水，那堪白发换朱颜。\n六趣任循环。\n今与古，谁肯死前闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13872, '望江南・忆江南', '净圆', '娑婆苦，光影急如流。\n宠辱悲欢何日了，是非人我几时休。\n生死路悠悠。\n三界里，水面一浮沤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13873, '望江南・忆江南', '净圆', '西方好，随念即超群。\n一点灵光随落日，万端尘事付浮云。\n人世自纷纷。\n凝望处，决定去栖神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13874, '望江南・忆江南', '净圆', '西方好，琼树耸高空。\n弥覆七重珠宝网，庄严百亿妙华宫。\n宫里众天童。\n金地上，栏绕重重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13875, '望江南・忆江南', '净圆', '西方好，七宝成池。\n四色好华敷菡萏，八功德水泛清漪。\n除渴又除饥。\n池岸上，楼殿势飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13876, '望江南・忆江南', '净圆', '西方好，群鸟美音声。\n华下和鸣歌六度，光中哀雅赞三乘。\n闻者悟无生。\n三恶道，犹自不知名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13877, '望江南・忆江南', '净圆', '西方好，清旦供尤佳。\n缥缈仙云随宝仗，轻盈衣贮天华。\n十万去非赊。\n诸佛土，随念遍河沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13878, '望江南・忆江南', '净圆', '西方好，我佛大慈悲。\n但具三心圆十念，即登九品越三祗。\n神力不思议。\n临报尽，接引定无疑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13879, '哨遍', '刘学箕', '木叶尽凋，湖色接天，雪月明江水。\n凌万顷、一苇纵所之。\n若凭虚驭风仙子。\n听洞箫、绵延不绝如缕，馀音袅袅游丝曳。\n乃举酒赋诗，玉鳞霜蟹，是中风味偏美。\n任满头堆絮雪花飞。\n更月澹蓬窗冻云垂。\n山郁苍苍，桥卧沈沈，夜鹊惊起。\n噫。\n倚兰桨兮。\n我今恍惚遗身世。\n渔樵甘放浪，蜉蝣然、寄天地。\n叹富贵何时。\n功名浪语。\n人生寓乐虽情尔。\n知逝者如斯。\n盈虚如彼，则知变者如是。\n且物生宇宙各有司。\n非已有纤毫莫得之。\n委吾心、耳目所寄。\n用之而不竭，取则不吾禁，自色自声，本非有意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13880, '蝶恋花', '刘学箕', '灯火已收正月半。\n一夜东风，吹得寒威转。\n怪得美人贪睡暖。\n飞瑛积玉千林变。\n道是柳绵春尚浅。\n比著梅花，花已都零乱。\n漠漠一天迷望眼。\n多情更把征衣点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13881, '贺新郎', '刘学箕', '午睡莺惊起。\n鬓云偏、未整，凤钗斜坠。\n宿酒残妆无意绪，春恨春愁如水。\n谁共说、厌厌情味。\n手展流苏腰肢瘦，叹黄金、两细香消臂。\n心事远，仗谁寄。\n帘栊渐是槐风细。\n对梧桐、清阴满院，夏初天气。\n回首春空梨花梦，屈指从头暗记。\n叹薄、抛人容易。\n目断孤鸿沈双鲤，恨萧郎、不寄相思字。\n幽恨积，黛眉翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13882, '忆王孙', '刘学箕', '淑景韶光晴昼。\n帘外雨、欲无还有。\n流莺枝上转新声，梦初醒、厌厌病酒。\n天连碧草凝情久。\n思旧事、不堪搔首。\n怀人有恨水云深，又绿暗、桥西柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13883, '恋绣衾', '刘学箕', '柳絮风翻高下飞。\n雨笼晴、香径尚泥。\n女伴笑、踏青好，凤钗偏、花压鬓垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13884, '惜分飞', '刘学箕', '池上楼台堤上路。\n尽日悠扬飞舞。\n欲下还重举。\n又随胡蝶墙东去。\n糁径飘空无定处。\n来往绿窗朱户。\n却被春风妒。\n送将蛛网留连住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13885, '浣溪沙', '刘学箕', '天上仙人萼绿华。\n何年分种小山家。\n九秋风露溢窗纱。\n密密翠罗攒玉叶，团团黄粟刻金花。\n一枝归插鬓云斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13886, '贺新郎', '刘学箕', '往事何堪说。\n念人生、消磨寒暑，漫营裘葛。\n少日功名频看镜，绿鬓未雪。\n渐老矣、愁生华发。\n国耻家雠何年报，痛伤神、遥望关河月。\n悲愤积，付湘瑟。\n人生未可随时别。\n守忠诚、不替天意，自能符合。\n误国诸人今何在，回首怨深次骨。\n叹南北、久成离绝。\n中夜闻鸡狂起舞，袖青蛇、戛击光磨铁。\n三太息，皆空裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13887, '贺新郎', '刘学箕', '东阁凭诗说。\n对丰姿、飘然杖屦，澹然巾葛。\n竹外一枝斜更好，玉质冰肌粲雪。\n谁折向、满头宣发。\n水驿云窗烟庭院，更宜晴、宜雨还宜月。\n霜夜永，景萧瑟。\n孤芳与群芳别。\n陇程遥、攀条难寄，碧云惊合。\n桃李漫山空春艳，不比仙风道骨。\n有潇洒、清新奇绝。\n我被幽香相懊恼，宋广平、岂但心如铁。\n飞暗度，石吹裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13888, '贺新郎', '刘学箕', '晓听儿曹说。\n道前村、疏梅莫与，蔽萧缠葛。\n急与呼童诛翦尽，趁此江天暮雪。\n唤小艇、渔翁鹤发，凛冽寒风吹酒面，与何人、共泛山阴月。\n归浩叹，御琴瑟。\n世寰恍惚山川别。\n望琼楼、玉宇相映，烂银环合。\n冰柱雪车新句就，不疗饥肠病骨。\n奈野鸟、千山飞绝。\n我笑书生贫亦甚，诵布衾、岁久寒如铁。\n儿恶卧，踏里裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13889, '满江红', '刘学箕', '午转槐阴，正炎暑、侵肌似醉。\n问何处、披襟散发，解衣扬袂。\n傍沼茅亭杨柳绿，倚崖草阁梧桐翠。\n唤玉人、纤手掬清泉，生凉意。\n开枕簟，浮瓜芰。\n琼液浅，歌喉细。\n对文禽雪鹭，助成幽致。\n十顷碧莲潇洒国，万竿修竹清凉世。\n算此时、情绪有谁同，吾侬自。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13890, '满江红', '刘学箕', '一柄双花，低翠盖、呈祥现美。\n人正在、薰风亭上，满襟如水。\n二陆比方夸俊少，两乔相并修容止。\n雨初晴、午永斗红酣，真奇耳。\n双白鹭，双鲤。\n飞与泳，俱来此。\n绾双鬟天上，侍香童子。\n双剑丰城双孕秀，双凫叶县双趋起。\n谩空谈、国士本无双，今双矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13891, '沁园春', '刘学箕', '浮利虚名，算来何用，蜗角蝇头。\n笑劳生一梦，两轮催逼，脆如朝露，轻若春沤。\n有限精神，无穷世路，劫劫忙忙谁肯休。\n堪惊叹，叹痴人未悟，终日营求。\n百年光景云浮。\n把意马心猿须早收。\n有真仙秘诀，飧霞导引，丹砂铅汞，早与身谋。\n闲是闲非，他强我弱，一任从教风马牛。\n还知道，上蓬莱稳路，八表神游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13892, '念奴娇', '刘学箕', '水轩沙岸，午风轻、飘动一天晴雪。\n日色晶荧光眩眼，细逐游丝明灭。\n帘幕中间，楼台侧畔，浑是瑶瑛积。\n缀松黏竹，恍然如对三绝。\n遥认仿佛飞花，花非还似，恼乱多情客。\n点染春衫无定度，又转沈香亭北。\n密密疏疏，斜斜整整，似雪难分别。\n坡仙不见，後人有口何说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13893, '念奴娇', '刘学箕', '断虹开霁，净秋容、点点初收微雨。\n夕下生阴山影澹，缥渺烟云吞吐。\n乌帽风偏，青鞋沙软，误入桃溪坞。\n多情鸥鹭，偶来忽又飞去。\n日暮修竹佳人，雾绡琼佩，绰约疑仙侣。\n愧我禅心春尽絮，不逐东风飞舞。\n红叶题诗，紫云传恨，密意渠能诉。\n此情疏隔，不关楼外烟树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13894, '菩萨蛮', '刘学箕', '暮涛掀浪溪流急。\n单衣未试春寒力。\n是处绿阴浓。\n春深杨柳风。\n人依溪岸住。\n酒美忘归去。\n巢燕堕芹泥。\n幽禽花外啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13895, '菩萨蛮', '刘学箕', '鸦儿学画犹嫌丑。\n佯羞步步随娘後。\n春浅瘦花枝。\n凝愁为阿谁。\n那回筵畔见。\n有意相留恋。\n只恐後期愆。\n章台飞柳绵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13896, '鹧鸪天', '刘学箕', '楼外银屏入望赊。\n楼前鸥鹭舞交加。\n穿林淅沥飞琼屑，度嶂缤纷过柳花。\n歌白雪，醉流霞。\n晚寒寒似夜来些。\n明朝酒醒掀帘幕，帘幕依然卖酒家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13897, '西江月', '刘学箕', '世事从来无据，人生自古难凭。\n茫如天水有云萍。\n聚散任他形影。\n每怪东阳瘦损，常嗤骑省多情。\n如今我也瘦棱棱。\n却喜青青两鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13898, '水调歌头', '刘学箕', '三载役京口，十度过松江。\n垂虹亭下烟水，长是映蓬窗。\n钓得锦鳞成脍，快把双螯浩饮，豪气未能降。\n醉舞影零乱，心逐浪舂撞。\n景苍茫，歌乃，石空。\n蒹葭深处，适意鱼鸟自双双。\n便拟轻舟短棹，明月清风长共，与世绝纷龙。\n嘉遁有真隐，不羡鹿门庞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13899, '醉落魄・一斛珠', '刘学箕', '江头离席。\n晚潮双橹催行色。\n往来属玉双飞白。\n笑我多情，犹作未归客。\n红尘奔走何时息。\n归心还似投林翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13900, '长相思', '刘学箕', '湖山横。\n湖水平。\n买个湖船一叶轻。\n傍湖随柳行。\n秋风清。\n秋月明。\n谁捣秋砧烟外声。\n悲秋无尽情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13901, '鹧鸪天', '刘学箕', '芳草萋萋入眼浓。\n一年花事又匆匆。\n吐舒桃脸今朝雨，零落梅妆昨夜风。\n云接野，水连空。\n画栏十二倚谁同。\n两眉新恨无分付，独立苍苔数落红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13902, '鹧鸪天', '刘学箕', '梦绕天涯去意浓。\n客愁春恨两匆匆。\n绿波初涨桃花浪，画轻随柳絮风。\n无笔力，判虚空。\n关山千里两心同。\n鱼书雁字都休问，只看啼痕翠袖红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13903, '鹧鸪天', '刘学箕', '山色都如归兴浓。\n春融融处客匆匆。\n岸花影里莺吟雾，江阁阴中燕受风。\n凭画，睇层空。\n情衷待说几时同。\n不如且尽樽中绿，图得醉脸红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13904, '菩萨蛮', '刘学箕', '昨日杏花春满树。\n今晨雨过香填路。\n零落软胭脂。\n湿红无力飞。\n转头春易去。\n春色归何处。\n待密与春期。\n春归人也归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13905, '浣溪沙', '刘学箕', '来日江头柳带香。\n去时篱下菊花黄。\n人生离别几凄凉。\n拂面红尘飞冉冉，背人白日去堂堂。\n尺书休负雁南翔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13906, '眼儿媚', '刘学箕', '十年不见柳腰肢。\n契阔几何时。\n天遥地远，秋悲春恨，只在双眉。\n雁声今夜楼西畔，情愫渺难期。\n杏花风景，梧桐夜月，都是相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13907, '桃源忆故人', '刘学箕', '暮霞散绮西溪浦。\n天上晴云开絮。\n清绝梅花几树。\n恼乱春愁处。\n小桥流水人来去。\n沙岸浴鸥飞鹭。\n谁画江南好处。\n著我闲巾屦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13908, '糖多令・唐多令', '刘学箕', '何处浣离忧。\n消除许大愁。\n望长江、衮衮东流。\n一去乡关能几日，才屈指、又中秋。\n芦叶满汀洲。\n沙矶小艇收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13909, '小重山', '刘学箕', '春水东流一苇杭。\n春情翦不断，汉江长。\n江花江草为谁芳。\n浑不似，沙暖睡鸳鸯。\n且道不思量。\n怕他知得後，痛肝肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13910, '行香子', '刘学箕', '雪白肥。\n墨黑修鲇。\n柳穿腮、小大相兼。\n金刀批脔，鲜活甘甜。\n或时熬，或时煮，或时腌。\n揎腕佳人，玉手纤纤。\n缕银丝、取意无厌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13911, '临江仙', '刘学箕', '人在空江烟浪里，叶舟轻似浮沤。\n此心无怨也无忧。\n汉江迷望眼，衮衮知东流。\n两岸荻芦青不断，四山岗岭绸缪。\n晚风吹袂冷飕飕。\n谁知三伏暑，全似菊花秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13912, '渔家傲', '刘学箕', '汉水悠悠还漾漾。\n渔翁出没穿风浪。\n千尺丝纶垂两桨。\n收又放。\n月明长在烟波上。\n钓得活鳞鳊缩项。\n成玉液香浮盎。\n醉倒自歌歌自唱。\n轻袅缆。\n碧芦红蓼清滩傍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13913, '菩萨蛮', '刘学箕', '烟汀一抹蒹葭渚。\n风亭两下荷花浦。\n月色漾波浮。\n波流月自留。\n若耶溪上女。\n两两三三去。\n眉黛敛羞蛾。\n采菱随棹歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13914, '乌夜啼', '刘学箕', '长亭急管生愁。\n楚天秋。\n落日寒鸦飞尽、水悠悠。\n红蓼岸。\n白苹散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13915, '虞美人', '刘学箕', '寒来暑往何时了。\n世故催人老。\n一人口插几张匙。\n何用波波劫劫、没休时。\n饥来吃饭困来睡。\n莫把身为累。\n谁能较短与量长。\n落叶西风一梦、熟黄粱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13916, '贺新郎', '刘学箕', '莫向愁人说。\n叹人生、不如意事，十常七八。\n是则中年伤怀抱，客里何堪送客。\n又添取、一襟凄咽。\n岸柳凋零秋容澹，黯消凝、怎忍轻攀折。\n重会面，甚时节。\n杏花丽日梅花雪。\n记当时、一觞一咏，楚云湘月。\n别後君休劳春梦，转眼江南塞北。\n莫漫被、闲愁萦结。\n且判离筵今夕醉，霎时间、便见兰舟发。\n空怅望，水云阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13917, '酹江月・念奴娇', '林正大', '诸公台省，问先生何事，冷官如许。\n甲第纷纷粱肉厌，应怪先生无此。\n道出羲皇，才过屈宋，空有名垂古。\n得钱沽酒，忘形欲道尔汝。\n好是清夜沈沈，共开春酌，细听檐花雨。\n茅屋石田荒已久，总待先生归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13918, '水调歌・水调', '林正大', '人笑杜陵客，短褐鬓如丝。\n得钱沽酒，时赴郑老同襟期。\n清夜沈沈春酌，歌语灯前细雨，相觅不相疑。\n忘形到尔汝，痛饮真吾师。\n问先生，今去也，早归来。\n先生去後，石田茅屋恐苍苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13919, '满江红', '林正大', '衮衮诸公，嗟独冷、先生宦薄。\n夸甲第、纷纷粱肉，谩甘寥寞。\n道出羲皇知有用，才过屈宋人谁若。\n剩得钱、沽酒两忘形，更酬酢。\n清夜永，开春酌。\n听细雨，檐花落。\n但高歌不管，饿填沟壑。\n司马逸才亲涤器，子云识字终投阁。\n且生前、相遇共相欢，衔杯乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13920, '一丛花', '林正大', '知章骑马似乘船。\n落井眼花圆。\n汝阳三斗朝天去，左丞相、鲸吸长川。\n潇洒宗之，皎如玉树，举盏望青天。\n长斋苏晋爱逃禅，李白富诗篇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13921, '贺新凉・贺新郎', '林正大', '兰亭当日事。\n有崇山、茂林修竹，群贤毕至。\n湍急清流相映带，旁引流觞曲水。\n但畅叙、幽情而已。\n一咏一觞真足乐，厌管弦丝竹纷尘耳。\n春正暮，共修禊。\n惠风和畅新天气。\n骋高怀、仰观宇宙，俯察品类。\n俯仰之间因所寄，放浪形骸之外。\n曾不知、老之将至。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13922, '酹江月・念奴娇', '林正大', '问陶彭泽，有田园活计，归来何晚。\n昨梦皆非今觉是，实迷途其未远。\n松菊犹存，壶觞自酌，寄傲南窗畔。\n闲云出岫，更看飞鸟投倦。\n归去请息交游，驾言焉往，独把琴书玩。\n孤棹巾车邱壑趣，物与吾生何恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13923, '沁园春', '林正大', '大人先生，高怀逸兴，酒肉寓名。\n纵幕天席地，居无庐室，以八荒为域，日月为扃。\n贵介时豪，绅处士，未解先生酒适情。\n徒劳尔，谩是非锋起，有耳谁听。\n先生。\n挈提罂。\n更箕踞衔杯枕麴生。\n但无思无虑，陶陶自得，任兀然而醉，恍然而醒。\n静听无闻，熟视无睹，以醉为乡乐性真。\n谁知我，彼二豪犹是，蜾蠃螟蛉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13924, '水调歌', '林正大', '太行有盘谷，隐者所翱翔，丈夫行世，磊磊落落信行藏。\n遇则声名利泽，不遇采山钓水，何似两俱忘。\n谁解盘中趣，与酒为歌章。\n问何如，盘之乐，乐无央。\n远驱虎豹，蛟龙于此亦潜藏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13925, '摸鱼儿', '林正大', '醉之乡、其去中国，不知其几千里。\n其土平旷无涯际。\n其气和平一揆。\n无寒暑，无聚落居城，无怒而无喜。\n昔黄帝氏。\n仅获造其都，归而遂悟，结绳已非矣。\n及尧舜，盖亦至其边鄙。\n终身太平而治。\n武王得志於周世。\n命立酒人之氏。\n从此後，独阮籍渊明，往往逃而至。\n何其淳寂。\n岂古华胥，将游是境，余故为之记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13926, '声声慢', '林正大', '暮春天气，争看长安，水边多丽人人。\n意远态浓，肌理骨肉轻匀。\n绣罗衣裳照映，尽蹙金、孔雀麒麟。\n夸荣贵，是椒房云幕，恩宠无伦。\n簇簇紫驼翠釜，间水精盘里，缕脍纷纶。\n御送珍羞，夹道箫鼓横陈。\n後来宾从杂，认青鸾、飞舞红巾。\n扶下马，似杨花、翻入锦茵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13927, '贺新凉・贺新郎', '林正大', '环滁皆山也。\n望西南、蔚然深秀，者琅邪也。\n泉水潺潺峰路转，上有醉翁亭也。\n亭、太守自名之也。\n试问醉翁何所乐，乐在乎、山水之间也。\n得之心、寓酒也。\n四时之景无穷也。\n看林霏、日出云归，自朝暮也。\n交错觥筹酣宴处，肴蔌杂然陈也。\n知太守、游而乐也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13928, '水调歌', '林正大', '庐山几千仞，屹立并长江。\n杨澜左里，洪涛巨浪日舂撞。\n风止雪消冰净，相与泊舟登岸，攀磴望空。\n岩壑响松桧，巨石激流淙。\n事幽寻，遗世俗，绝纷。\n幽花野草香满，时有鹤飞双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13929, '酹江月・念奴娇', '林正大', '泛舟赤壁，正风徐波静，举尊属客。\n渺渺予怀天一望，万顷凭虚独立。\n桂桨空明，洞箫声彻，怨慕还凄恻。\n星稀月淡，江山依旧陈迹。\n因念酾酒临江，赋诗横槊，好在今安适。\n谩寄蜉蝣天地尔，瞬目盈虚消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13930, '酹江月・念奴娇', '林正大', '雪堂闲步，过临皋、霜净晚林木落。\n月白风清如此夜，与客行歌相答。\n网举松鲈，手携斗酒，赤壁重寻约。\n悲歌长啸，划然声动寥廓。\n试问日月几何，江流山色，今日应如昨。\n履遍岩风露冷，水面怒涛惊跃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13931, '水调歌', '林正大', '仕宦至卿相，富贵好归乡。\n高车驷马，都人夹道共瞻望。\n意气当年尤盛，荣比昔人衣锦，昼锦以名堂。\n海内知名士，久矣望馀光。\n大丈夫，荣与贵，视寻常。\n丰功令德，要将尧舜致君王。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13932, '贺新凉・贺新郎', '林正大', '酌以蒲城酒。\n撷湘累、秋英满泛，介君眉寿。\n赠君点漆黟川墨，与印文章大手。\n问此别、相逢难又。\n三叠阳关声堕泪，写平时、兄弟情长久。\n离别事，古来有。\n十年骨肉情何厚。\n对江山千里，共期白首。\n夜雨连床追旧事，惟恨音书渐少。\n便只恐、炊沙不饱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13933, '水调歌', '林正大', '耿耿银潢净，窗月莹如冰。\n朱丝一扣，万籁不起冷光凝。\n千古遗音犹在，一洗淫哇郑卫，北里与南陵。\n孰识兴亡事，哀乐不同情。\n咽流泉，戛鸣玉，击浮金。\n老龙啼晓，幼猿忽复暮山吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13934, '满江红', '林正大', '落魄高人，拼百万、青铜一醉。\n挥素手、朱绳一抹，四筵惊起。\n催织寒虫秋弄月，叫群独雁天浮水。\n更黄鹂、紫燕对春风，争繁脆。\n悲楚国，羁臣意。\n怜汉女，逾千里。\n似深闺恩怨，共相汝尔。\n我有江南丘壑趣，此弦能道心中事。\n要曲肱、时听写松风，云窗里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13935, '朝中措', '林正大', '凌波仙子袜生尘。\n水上步轻盈。\n种作寒花愁绝，断肠谁与招魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13936, '满江红', '林正大', '太一真人，莲叶向、中流荡漾。\n凌万顷、风为帆席，浪为轻桨。\n乱舞翠绡云雾薄，卧看玉宇琉璃晃。\n似飘然、万斛举龙骧，随波荡。\n太华顶，花十丈。\n飘一叶，借清赏。\n倩龙眠老手，为渠摹彷。\n鳌禁谁寓直，玉堂学士今刘向。\n要清宵、特地杖青藜，来相访。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13937, '贺新凉・贺新郎', '林正大', '生长湖山曲。\n羡君儿、呼吸湖光，饱餐山渌。\n世外不须论隐逸，谁似先生冰玉。\n自骨冷、神清无俗。\n我不识君曾梦见，炯双瞳、碧色光相烛。\n遗妙语，看不足。\n生平高节难为续。\n到如今、凛凛风生，言犹可录。\n不作相如封禅藁，身後谁荣谁辱。\n争肯效、白头吟曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13938, '水调歌', '林正大', '欲状巴陵胜，千古岳之阳。\n洞庭在目，远衔山色俯长江。\n浩浩横无涯际，爽气北通巫峡，南望极潇湘。\n骚人与迁客，览物兴尤长。\n锦鳞游，汀兰郁，水鸥翔。\n波澜万顷，碧色上下一天光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13939, '木兰花慢', '林正大', '黄河天上派，到东海、去难收。\n况镜里堪悲，星星白发，早上人头。\n人生尽欢得意，把金尊、对月莫空休。\n天赋君材有用，千金散聚何忧。\n请君听我一清讴。\n锺鼎复奚求。\n但烂醉春风，古来惟有，饮者名留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13940, '水调歌', '林正大', '听说竹楼好，佳地占黄冈。\n月波相接，俯临江濑挹山光。\n急雨檐喧瀑布，密雪瓴敲碎玉，幽阒兴尤长。\n琴调更虚畅，诗韵转清扬。\n公退暇，披鹤氅，戴华阳。\n手披周易，消磨世虑坐焚香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13941, '清平乐', '林正大', '若耶溪女。\n笑隔荷花语。\n日照新妆明楚楚，香袖风轻举。\n谁家白面游郎。\n两三遥映垂杨。\n醉踏落花归去，踌躇空断柔肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13942, '满江红', '林正大', '为忆当时，沈醉里、青楼弄月。\n闲想像、绣帏珠箔，魂飞心折。\n羞向妲娥谈旧事，几经三五盈还缺。\n望翠眉、蝉鬓一天涯，伤离别。\n寻作梦，巫云结。\n流别泪，湘江咽。\n对花深两岸，忽添悲切。\n试与含愁弹绿绮，知音不遇弦空绝。\n忽窗前、一夜寄相思，梅花发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13943, '满江红', '林正大', '寂寞江城，┾只共、梅花幽独。\n揩病眼、佳人何许，嫣然空谷。\n幻出天姿真富贵，朱唇滞酒红生肉。\n笑漫山、繁李与夭桃，俱粗俗。\n迟日丽，春睡足。\n明月照，尤清淑。\n算移更千里，远从西蜀。\n流落天涯应可念，为渠剧饮仍歌曲。\n怕明朝、酒醒落纷纷，那忍触。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13944, '水调歌', '林正大', '落日岘山下，倒著接回。\n傍人笑问山翁，日日醉归来。\n三万六千长日，一日杯倾三百，麴筑糟抬。\n汉水鸭头绿，变酒入金。\n白铜，鸬鹚杓，鹦鹉杯。\n轻车快马，凤笙龙管更相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13945, '江神子・江城子', '林正大', '狂胡鞍马自为家。\n遣宫娃。\n嫁胡沙。\n万里风烟，行不见京华。\n马上思归哀怨极，推却手，奏琵琶。\n胡儿共听亦咨嗟。\n貌如花。\n落天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13946, '意难忘', '林正大', '蜀道登天。\n望峨眉横绝，石栈相连。\n西来当鸟道，逆浪俯回川。\n猿与鹤，莫攀缘。\n九折耸岩峦。\n算咫尺、扪参历井，回首长叹。\n西游何日当还。\n听子规啼月，愁减朱颜。\n连峰天一握，飞瀑壑争喧。\n排剑阁，越天关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13947, '沁园春', '林正大', '庐阜诸峰，炉峰绝胜，草堂介焉。\n敞明窗净室，素屏虚榻，要仰观山色。\n俯听流泉。\n中有池台，旁多竹卉，夹涧杉松高刺天。\n堂之北，据层崖积石，绿荫浓鲜。\n堂东瀑布飞悬。\n似雨露霏微珠贯穿。\n有春花秋月，夏云冬雪，阴晴显晦，雾吐烟吞。\n右抱琴书，左携妻子，杖屦从容尽暮年。\n平生志，赖清泉白石，实听余言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13948, '摸鱼儿', '林正大', '泛松江、水遥山碧，清寒微动秋浦。\n霜云霁色横无际，别鹄惊鸿无数。\n朝又暮。\n听牧笛长吹，隐隐渔榔度。\n骚人才子。\n既览物兴怀，浮游尘外，啸傲剧清思。\n人间世。\n扰扰荣途要路。\n瀛洲琼馆安所。\n轩裳何似渔蓑兴，萧散龙游鹤渚。\n须归去。\n办双桨孤帆，云月和烟雨。\n江湖伴侣。\n趁社橘初黄，汀葭馀翠，成我莼鲈趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13949, '意难忘', '林正大', '汹汹松风。\n更浮云皓皓，轻度春空。\n精神新发越，宾主少从容。\n犀箸厌，涤昏懵。\n茗碗策奇功。\n待试与，平章甲乙，为问涪翁。\n建溪日铸争雄。\n笑罗山梅岭，不数严邛。\n胡桃添味永，甘菊助香浓。\n投美剂，与和同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13950, '酹江月・念奴娇', '林正大', '坐愁书室，谩临风、遐想蓬莱高致。\n抚鹤扪松长叹息，失足误来人世。\n紫禁九重，碧山万里，无路鸣珂佩。\n江山胜处，且寻花柳倾醉。\n不堪送客清川，系帆渌水，烟景供憔悴。\n更举芳尊浇别恨，逸趣浮游天外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13951, '酹江月・念奴娇', '林正大', '杏花春晚，散馀芳、著处萦帘穿箔。\n唤起幽人明月夜，步月褰衣行乐。\n置酒花前，清香争发，雪挽长条落。\n山城薄酒，共君一笑同酌。\n且须眼底柔英，尊中清影，放待杯行数。\n莫道洞箫声断处，月落杯空牢寞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13952, '水调歌', '林正大', '华裾织翡翠，金辔闹珑璁。\n宝蹄轻稳，香尘满地骤隆隆。\n云是东京才子，名擅文章钜伯，一世独推雄。\n高盖拥宾从，下马气如虹。\n运元精，锺神秀，贯当中。\n磊磊落落，二十八宿列心胸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13953, '虞美人', '林正大', '武昌七十庞眉叟。\n学笛从年少。\n萧萧笛竹楚山秋。\n当日买林、曾典黑貂裘。\n一声占尽秋江月。\n天外行云绝。\n如今老去兴犹迟。\n尚想时时、一曲梦中吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13954, '江神子・江城子', '林正大', '拾遗流落锦宫城。\n故人情。\n眼为青。\n时向百花，潭水濯冠缨。\n韦曲杜陵行乐地，尘土暗，叹漂零。\n园翁溪友总比邻。\n酒盈尊。\n肯相亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13955, '沁园春', '林正大', '子陵先生，故人光武，以道相忘。\n幸炎符在握，六龙在御，臣来亿兆，阳德方刚。\n自是先生，独全高节，归去江湖乐未央。\n动星象，被羊裘傲睨，一世轩裳。\n高哉不事侯王。\n爱此地山高水更长。\n盖先生心地，超乎日月，又谁如光武，器量包荒。\n立懦廉顽，有功名教，万世清风更激扬。\n无古今，想云山郁郁，江水泱泱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13956, '临江仙', '林正大', '须信乾坤如逆旅，都来一梦浮生。\n夜游秉烛尽欢情。\n阳春烟景媚，乐事史来并。\n座上群公皆俊秀，高谈幽赏俱清。\n飞觞醉月莫辞频。\n休论金谷罚，七步看诗成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13957, '酹江月・念奴娇', '林正大', '开元盛日，爱名花绝品，浅红深紫。\n云想衣裳□□映，曲槛软风微度。\n群玉山头，瑶台月下，一□香凝露。\n嫣然倾国，巫山肠断云雨。\n借问标格风流，汉宫谁似，飞燕红妆舞。\n解释春风无限恨，博得君王笑语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13958, '沁园春', '洪咨夔', '诗不云乎，蒹葭苍苍，白露为霜。\n看高山乔木，青云老干，英华滋液，亦敛而藏。\n匠石操斤游林下，便一举采之充栋梁。\n须知道，是天将大任，翕处还张。\n薇郎玉佩丁当。\n问何事午桥花竹庄。\n又星回岁换，腊残春浅，锦熏笼紫，栗玉杯黄。\n唤起东风，吹醒宿酒，把甲子从头重数将。\n明朝去，趁传柑宴近，满袖天香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13959, '沁园春', '洪咨夔', '归去来兮，杜宇声声，道不如归。\n正新烟百五，雨留酒病，落红一尺，风妒花期。\n睡起绿窗，销残香篆，手板颐还倒持。\n无人解，自追游仙梦，作送春诗。\n风流不似年时。\n把别墅江山供弈棋。\n空一川芳草，半池晴絮，歌翻长恨，赋续怀离。\n桃叶渡头，沈香亭北，往事悠悠难重思。\n徘徊处，看鸣鸠唤妇，乳燕将儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13960, '沁园春', '洪咨夔', '饮马咸池，总辔，横鹜九州。\n庆中兴机会，天生山甫，非常事业，天授留侯。\n左搏龙蛇，右驯虎兕，万里中原谈笑收。\n功名早，便貂蝉猎猎，飞出兜牟。\n新无限欢讴。\n尽卖剑卖刀归买牛。\n正麦摇熏吹，黄迷断垄，秧涵朝雨，绿遍平畴。\n眼底太平，不图再见，罗拜焚香青海头。\n从今去，愿君王万岁，元帅千秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13961, '沁园春', '洪咨夔', '秋气悲哉，薄寒中人，皇皇何之。\n更黄花吹雨，苍苔滑屐，栏空斗鸭，床老支龟。\n静里跫音，明边眉睫，蹴踏星河天脱。\n清谈久，顿两忘妍丑，嫫姆西施。\n濂溪家住江湄。\n爱出水芙蓉清绝姿。\n好光风霁月，一团和气，尸居龙见，神动天随。\n著察工夫，诚存体段，个里语言文字非。\n君家事，莫空将太极。\n散大图碑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13962, '风流子', '洪咨夔', '锦幄醉荼シ。\n狻猊暖、银蒜压烟霏。\n正韩范安边，欧苏领客，红芳庭院，绿荫窗扉。\n著句挽春春肯住，更判羽觞挥。\n金系花腰，玉匀人面，娇慵无力，娅姹相依。\n繁华都能几，青油幕、好与遮护晴晖。\n寄语东君，莫教一片轻飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13963, '贺新郎', '洪咨夔', '露洗秋光透。\n指岷峨、无边峭碧，与君为寿。\n万里同随琴鹤到，只愿人情长久。\n尽头白、眼青如旧。\n从臾功名三尺剑，倚函关、风雨蛟龙吼。\n谈笑取，印如斗。\n从今尽展眉峰皱。\n看诸郎、翩翩黄甲，班班蓝绶。\n一簇孙枝扶膝下，翠竹碧梧争秀。\n便嘉庆、图中都有。\n花影婆娑清昼永，护新凉、更著丝簧手。\n欢未尽，剩添酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13964, '贺新郎', '洪咨夔', '风软帘花约。\n玉壶天、芙蕖欲盖，初槊。\n宿霭收阴晴色定，一点星明碧落。\n光拍满、浮溪β。\n银栉铁冠风物古，更秧青、麦熟蚕登箔。\n欢取酒，为君酌。\n华堂衮绣今如昨。\n长官清、水晶灯照，珊瑚钩琢。\n富贵功名知有样，晨起一声檐鹊。\n便好趁、六更宫钥。\n龙尾朝回长燕喜，宝香深、醉引莱衣著。\n吹紫凤，舞黄鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13965, '贺新郎', '洪咨夔', '放了孤山鹤。\n向西湖、问讯水边，嫩寒篱落。\n试粉盈盈微见面，一点芳心先著。\n正日暮、烟轻云薄。\n欲搅清香和月咽，倩冯夷、为洗黄金杓。\n花向我，劝多酌。\n单于吹彻今成昨。\n未甘渠、琢玉为堂，把春留却。\n倚遍黄昏栏十二，知被儿曹先觉。\n更笑杀、卢仝赤脚。\n但得东风先手在，管绿阴、好践青青约。\n方寸事，两眉角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13966, '贺新郎', '洪咨夔', '谁识昂昂鹤。\n且随缘、剩水残山，东村西落。\n世事几番新局面，看底却高三著。\n况转首、西山日薄。\n雪意压檐梅索笑，任柄长、柄短邻家杓。\n小瓮，动孤酌。\n见花忆得年时昨。\n正微醺、独步黄昏，被花迷却。\n冷月吹香春弄影，么凤梢头先觉。\n恍梦断、罗浮山脚。\n欲寄心期无驿使，想凌寒、不奈腰肢约，空凭暖，画栏角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13967, '汉宫春', '洪咨夔', '南极仙翁，占太微元盖，洞府为家。\n身骑若木倒景，手弄青霞。\n芙蓉飞旆，映一川、新绿平沙。\n好与问，东风结子，几回开遍桃花。\n况是初元玉历，更循环数起，希有年华。\n长把清明夜气，养就丹砂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13968, '夏初临', '洪咨夔', '铁瓮栽荷，铜彝种菊，胆瓶萱草榴花。\n庭户深沈，画图低映窗纱。\n数枝奇石。\n染宣和、瑞露明霞。\n於菟长啸，风林未鸣，霜草先斜。\n雪丝香里，冰粉光中，兴来进酒，睡起分茶。\n轻雷急雨，银篁迸插檐牙。\n凉入琵琶。\n枕帏开、又送蟾华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13969, '满江红', '洪咨夔', '送雨迎晴，花事过、一庭芳草。\n帘影动、归来双燕，似悲还笑。\n笑我不知人意变，悲人空为韶华老。\n满天涯、都是别离愁，无人扫。\n海棠晚，荼シ早。\n飞絮急，青梅小。\n把风流酝藉，向谁倾倒。\n秋水盈盈魂梦远，春云漠漠音期悄。\n最关情、鹎一声催，窗纱晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13970, '满江红', '洪咨夔', '把酒西风，浑莫问、主宾谁恶。\n千古事、几□遇合，几人流落。\n肝胆轮溟渤小，精神浩荡蓬莱薄。\n望拒霜、红处是东山，长如昨。\n苍苔迹，何曾削。\n黄叶梦，何难觉。\n等春云出岫，秋波归壑。\n老子婆娑风度远，佳人缥缈腰肢约。\n况登高、节过又登高，须多酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13971, '天香', '洪咨夔', '云母屏开，博山炉熨，人间南极星现。\n酥篆千秋，灯图百子，酒浪花光照面。\n堂深戏彩，任父老、儿童争劝。\n耆艾相将潞国，精明恰如清献。\n春风飘香合殿。\n仗云齐、漏迟宫箭。\n正好簪荷入侍，帕柑传宴。\n日月华虫绚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13972, '水调歌头', '洪咨夔', '四海止斋老，百世水心翁。\n都将不尽事业，付与道俱东。\n气脉中庸大学，体统采薇天保，几疏柘袍红，千仞倚寥碧，一点驾归鸿。\n扈江蓠，贯薜荔，制芙蓉。\n午桥绿野深处，心与境俱融。\n搏控乾坤龙马，簸弄坎离日月，苍鬓映方瞳。\n只恐又催诏，飞度橘花风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13973, '水调歌头', '洪咨夔', '如此好明月，梅里自来无。\n炎云溽雾收尽，宇宙一冰壶。\n浅濑乍分随合，清影欲连还断，漾玉浮图。\n风物庾楼似，秋思欠菰蒲。\n醉魂醒，尘骨换，我非吾。\n琼箫紫凤何许，风露足清都。\n君看流光多处，缥缈人立，白与藕花俱。\n只恐娥妒，凉透粟生肤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13974, '念奴娇', '洪咨夔', '香山老矣，正商量不下，去留蛮素。\n独立踌躇肠欲断，一段若耶溪女。\n水底新妆，空中香袖，斜日疏风浦。\n向人欲语，垂杨清荫多处。\n便好花里唤船，碧筒白酒，微吸荷心苦。\n佳月一钩天四碧，隐约明波横注。\n雪藕逢丝，擘莲见薏，枕簟凉如雨。\n一双宿鹭，伴人永夜翘伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13975, '念奴娇', '洪咨夔', '光风霁月，信行窝到处，人间天上。\n一笑唤回新造化，满眼翠舒红放。\n脑後功名，脚跟富贵，梦断春旗仗。\n辐巾萧散，任他虮虱龙象。\n正是杨柳初眠，海棠半睡，锦绣天开障。\n鹤骨松筋年望八，得醉不妨澜浪，节过烧灯，时催修禊，迎面韶华荡。\n宗文扶著，问翁马首何向。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13976, '更漏子', '洪咨夔', '眼生花，灯缀粟。\n人在黄金列屋。\n金缕细，道冠明。\n胆瓶凉意生。\n缓歌弦，停酒。\n待得香风吹下。\n斜月转，断云回。\n风流不让梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13977, '好事近', '洪咨夔', '二十四番风，才见一番花鸟。\n已是有人春瘦，正远山横峭。\n踏青底用十分晴，半阴晴方好。\n深院日长睡起，又海棠开了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13978, '朝中措', '洪咨夔', '荷花香里藕丝风。\n人在水晶宫。\n天上桥成喜鹊，云边帆认归鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13979, '朝中措', '洪咨夔', '翠盆红药护觥筹。\n风物似扬州。\n春事一声杜宇，人生能几狐裘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13980, '朝中措', '洪咨夔', '滂葩七十二滩春。\n锺瑞石麒麟。\n流水行云才思，光风霁月精神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13981, '点绛唇', '洪咨夔', '花事无多，笙歌绾取东风住。\n玉彝雕俎，楼外更筹屡。\n醉唤骊驹，催上天梯去。\n君知否。\n半边铜虎。\n邓艾经行路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13982, '西江月', '洪咨夔', '庭下宜男萱草，墙头结子榴花。\n非烟非雾富平家。\n人物风流如画。\n宝月曾修玉斧，银河欲泛仙槎。\n美人睡起绿云斜。\n一笑扶将寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13983, '浣溪沙', '洪咨夔', '苍鹤飞来水竹幽。\n初弦凉月一帘秋。\n木犀花底试新。\n凤味砚供无尽藏，龙飞榜占最高头。\n慈闱洗眼看封侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13984, '浣溪沙', '洪咨夔', '细雨斜风寂寞秋。\n黄花压鬓替人羞。\n归舟云树负箜篌。\n燕子楼寒迷楚梦，凤皇池暖惬秦讴。\n暮云凝碧可禁愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13985, '浣溪沙', '洪咨夔', '小雨轻霜作嫩寒。\n蜡梅开尽菊花乾。\n清香收拾贮诗肝。\n文武两魁前样在，功名四谏後来看。\n麻姑进酒斗阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13986, '浣溪沙', '洪咨夔', '六曲屏山似去年。\n雪花欺得怕寒肩。\n小窗和月照无眠。\n笔点轻澌心欲折，烛摇斜吹泪空煎。\n伴人梅影更堪怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13987, '菩萨蛮', '洪咨夔', '翠翘花艾年时昨。\n斗新五采同心索。\n含笑祝千秋。\n长眉如莫愁。\n流光旋磨蚁。\n换调重拈起。\n深院竹和丝。\n皱红裁舞衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13988, '鹧鸪天', '洪咨夔', '天理从来屈有信。\n东风到处物皆春。\n门前骢马权奇种，台上慈乌反哺心。\n花岛屐，柳湖尊。\n好将长健傲长贫。\n诸孙认取翁翁意，插架诗书不负人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13989, '蝶恋花', '洪咨夔', '画斛黄花寒更好。\n人爱花繁，却被花催老。\n旧恨新愁谁酝造。\n带围暗减知多少。\n开眼万般浑是恼。\n只仗微醺，假寐宽怀抱。\n隔屋愁眉春思早。\n数声啼破池塘草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13990, '临江仙', '洪咨夔', '万紫千红鬓上粉，聚成一撮精神。\n宣和宫样太清真。\n韶风摇斗帐，芳露湿纶巾。\n消得流莺花底滑，一声惊起梁尘。\n扶将芍药牡丹春。\n光浮金盏面，香到玉池津。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13991, '南乡子', '洪咨夔', '风雨过芳晨。\n多少愁红恨紫尘。\n两点眉尖凝远碧，纷纷。\n又被杨花误一春。\n金凤压娇云。\n睡起纱窗背欠伸。\n心事欲言言不尽，沈沈。\n乳燕雏莺触拨人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13992, '眼儿媚', '洪咨夔', '平沙芳草渡头村。\n绿遍去年痕。\n游丝下上，流莺来往，无限销魂。\n绮窗深静人归晚，金鸭水沈温。\n海棠影下，子规声里，立尽黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13993, '眼儿媚', '洪咨夔', '花光灯影浸帘栊。\n蓬岛现仙翁。\n瑶裾织翠，诗瞳点碧，酒脸潮红。\n窦郎阴德知多少，万卷奏新功。\n前庭梧竹，後园桃李，无限春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13994, '南乡子', '洪咨夔', '霜月冷婷婷。\n夹岸芦花雪点成。\n短艇水晶宫里系，闲情。\n谁道芙蓉更有城。\n阿鹊数归程。\n人倚低窗小画屏。\n莫恨年华飞上鬓，堪凭。\n一度春风一度莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13995, '祝英台近', '洪咨夔', '脸长红，眉半白，老鹤饱风露。\n岁换星移，禄运又交午。\n须知命带将来，福推不去，稳做个、荣华彭祖。\n记初度。\n谢他紫燕黄鹂，争先送好语。\n春满湖山，历历旧游处。\n管教柳外行厨，花边步，长占断、好晴奇雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13996, '谒金门', '洪咨夔', '春正美。\n满眼万红千紫。\n收拾群香归瓮蚁。\n长年花信里。\n深院帘栊如水。\n双燕呢喃芳垒。\n唾碧轻衫人送喜。\n梅梢新结子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13997, '谒金门', '洪咨夔', '开笑口。\n又是茱萸重九。\n好水佳山长似旧。\n健如黄犊走。\n菊蕊峥峥如豆。\n风雨轻寒初透。\n檐外鹊声谁送酒。\n莫闲金碗手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13998, '卜算子', '洪咨夔', '簸弄柳梢春，呼吸花心露。\n倦粉娇黄扇底风，尽向眉心度。\n唤醒海棠红，约住樱桃素。\n上到瑶台最上层，共跨青鸾去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (13999, '卜算子', '洪咨夔', '芍药打团红，萱草成窝绿。\n帘卷疏风燕子归，依旧卢仝屋。\n贫放麴生疏，闻到青奴熟。\n扫地焚香伴老仙，人胜连环玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14000, '柳梢青', '洪咨夔', '野服纶巾。\n白发红颊，无限阳春。\n二满三平，粗衣淡饭，锺鼎山林。\n尊前喜气轮，道蚕麦、今朝甲申。\n天放新晴，人占一饱，老子宽心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14001, '天仙子', '洪咨夔', '风月分将秋一半。\n昨夜月明今夜满。\n有人笙鹤御风来，玉绳转。\n银河淡。\n凉入天孙云锦段。\n笑拈桂枝香婉娩。\n十字金书光照眼。\n看看细札促归来，漏声缓。\n珂声远。\n夜宿玉堂谁是伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14002, '摸鱼儿', '赵与洽', '甚幽人、被花勾引，庭皋遥夜来去。\n江空岁晚谁为伴，只有琼枝玉树。\n愁绝处。\n望万里瑶台，梦断迷归路。\n花还解语。\n更雪琢精神，冰相韵度。\n粉黛尽如土。\n飘仙袂，曾缀蕊珠鹭。\n云茵月障千步。\n莫教衣袖天香冷，恐怨美人迟暮。\n更起舞。\n任斗转参横，翠羽曾知否。\n尘缘自误。\n终待骖鸾，乘风共去。\n长作此花主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14003, '江城梅花引', '赵与洽', '单衾寒引画龙声。\n雨初晴。\n月微明。\n竹外溪边，低见一枝横。\n澹月疏花三四点，尚春浅，早相看、似有情。\n夜来袖冷暗香凝。\n恨半销，酒半醒。\n靓妆照影，未整、雪艳冰清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14004, '碧牡丹', '李致远', '破镜重圆，分钗合钿，重寻绣户珠箔。\n说与从前，不是我情薄。\n都缘利役名牵，飘蓬无定，翻成轻负。\n别後情怀，有万千牢落。\n经时最苦分携，都为伊、甘心寂寞。\n纵满眼、闲花媚柳，终是强欢不乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14005, '失调名', '张琳', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14006, '翻香令', '邬虑', '醉和春恨拍阑干。\n宝香半倩谁翻。\n丁宁告、东风道，小楼空，斜月杏花寒。\n梦魂无夜不关山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14007, '如梦令', '冯熔', '素养浩然之气，铁石心肠谁拟。\n蒿目县前江，不逐队鱼游戏。\n藏器。\n藏器。\n只等时乘奋起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14008, '念奴娇', '刘镇2', '调冰弄雪，想花神清梦，徘徊南土。\n一夏天香收不起，付与蕊仙无语。\n秀入精神，凉生肌骨，销尽人间暑。\n稼轩愁绝，惜花还胜儿女。\n长记歌酒阑珊，开时向晚，笑金茎露。\n月浸栏干天似水，谁伴秋娘窗户。\n困云鬟，醉风帽，总是牵情处。\n返魂何在，玉川风味如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14009, '行香子', '刘镇2', '露叶烟条。\n天与多娇。\n算风流、张绪难消。\n恼人春思，政自无聊。\n赖敛愁眉，酣醉眼，减围腰。\n风絮相邀。\n蝶弄莺嘲。\n最关情、是短长桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14010, '沁园春', '刘镇2', '谁似花翁，长年湖海，蹇驴弊裘。\n想江尘醉帽，青楼歌扇，挥金谈笑，惜玉风流。\n吴下阿蒙，江南老贺，肯为良田二顷谋。\n人间世，算到头一梦，蝼蚁王侯。\n悠悠。\n吾道何求。\n况白首相逢说旧游。\n记疏风淡月，寒灯古寺，平章诗境，分付糟丘。\n聚散抟沙，炎凉转烛，归去来兮万事休。\n无何有，问从前那个，骑鹤扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14011, '沁园春', '刘镇2', '爽气西来，玉削群峰，千杉万松。\n望疏林清旷，晴烟紫翠，雪边回棹，柳外闻钟。\n夜月琼田，夕阳金界，倒影楼台表里空。\n桥阴曲，是旧来忠定，手种芙蓉。\n仙翁。\n心事谁同。\n付鱼鸟相望一笑中。\n向月梅香底，招邀和靖，云山高处，问讯梁公。\n物象搜奇，风流怀古，消得文章万丈虹。\n沈吟久，想依依春树，人在江东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14012, '花心动', '刘镇2', '鸠雨催晴，遍园林、一番绿娇红媚。\n柳外金衣，花底香须，消得艳阳天气。\n障泥步锦寻芳路，称来往、纵横珠翠。\n笑携手，旗亭问酒，更酬春思。\n还记东山乐事。\n向歌雪香中，伴春沈醉。\n粉袖人，彩笔题诗，陶写老来风味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14013, '汉宫春', '刘镇2', '日软风柔，望暖红连岛，晴绿平川。\n寻芳拾蕊，胜伴陌上鲜妍。\n玉骢归路，记青门、曾堕吟鞭。\n人去後，庭花弄影，一帘香月娟娟。\n追念旧游何在，叹佳期虚度，锦瑟华年。\n博山夜来烬冷，谁换沈烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14014, '水龙吟', '刘镇2', '三山腊雪才消，夜来谁转回寅斗。\n试灯帘幕，送寒幡胜，暗香携手。\n少日欢娱，旧游零落，异乡歌酒。\n到而今，生怕春来大早，空赢得、两眉皱。\n春到兰湖少住，肯殷勤、访梅寻柳。\n相思人远，带围宽减，粉痕消瘦。\n双燕无凭，尺书难表，甚时回首。\n想画栏、倚遍东风，闲负却、桃花咒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14015, '水龙吟', '刘镇2', '老来惯与春相识，长记伤春如故。\n去年今日，旧愁新恨，送将风絮。\n粉泪羞红，黛眉颦翠，推愁不去。\n任琐窗深闭，屏山半掩，还别有、愁来路。\n回首画桥烟水，念故人、匆匆何处。\n客情怀远，云迷北树，草连南浦。\n离合悲欢，去留迟速，问春无语。\n笑刘郎，不道无桃可种，苦留春住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14016, '水龙吟', '刘镇2', '弄晴台馆收烟候，时有燕泥香坠。\n宿酲未解，单衣初试，腾腾春思。\n前度桃花，去年人面，重门深闭。\n记彩鸾别後，青骢归去，长亭路、芳尘起。\n十二屏山遍倚。\n任苍苔、点红如缀。\n黄昏人静，暖香吹月，一帘花碎。\n芳意婆娑，绿阴风雨，画桥烟水。\n笑多情司马，留春无计，湿青衫泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14017, '庆春泽', '刘镇2', '灯火烘春，楼台浸月，良宵一刻千金。\n锦步承莲，彩云簇仗难寻，蓬壶影动星球转，映两行、宝珥瑶簪。\n恣嬉游，玉漏声催，未歇芳心。\n笙歌十里夸张地，记年时行乐，憔悴而今。\n客里情怀，伴人闲笑闲吟。\n小桃未静刘郎老，把相思、细写瑶琴。\n怕归来，红紫欺风，三径成阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14018, '蝶恋花', '刘镇2', '谁送凉蟾消夜暑。\n河汉迢迢，牛女何曾渡。\n乞得巧来无用处。\n世间枉费闲针缕。\n人在江南烟水路。\n头白鸳鸯，不道分飞苦。\n信远翻嗔乌鹊误。\n眉山暗锁巫阳雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14019, '柳梢青', '刘镇2', '乾鹊收声，湿萤度影，庭院秋香。\n步月移阴，梳云约翠，人在回廊。\n醺醺宿酒残妆。\n待付与、温柔醉乡。\n却扇藏娇，牵衣索笑，今夜差凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14020, '柳梢青', '刘镇2', '瞥眼光阴。\n章台旧路，杨柳春深。\n尚忆风流，人倚玉，替客挥金。\n高阳醉後分襟。\n想妒雨、嗔云到今。\n消息真时，笑啼难处，方表人心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14021, '江神子・江城子', '刘镇2', '思君梦里说邯郸。\n未成欢。\n已炊残。\n断送春归，风雨霎时间。\n空有生前医国手，医不到，子孙寒。\n欲登诗境吊方干。\n倩谁看。\n北邙山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14022, '临江仙', '刘镇2', '荡紫飘红芳信断，都无人问纤。\n吟鞭倚醉问凉蟾。\n香消金缕篆，尘压宝妆奁。\n梦峡朝云飞不到，一春离绪厌厌。\n却疑归燕碍重帘。\n心期花底误，眉恨柳边添。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14023, '浣溪沙', '刘镇2', '帘幕收灯断续红。\n歌台人散彩云空。\n夜寒归路噤鱼龙。\n宿醉未消花市月，芳心已逐柳塘风。\n丁宁莺燕莫匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14024, '清平乐', '刘镇2', '柳阴庭院。\n帘约风前燕。\n著雨荷花红半敛。\n消得盈盈绿扇。\n竹光野色生寒。\n玉纤雪藕冰盘。\n长记酒醒人静，暗香吹月栏干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14025, '贺新郎', '刘镇2', '云淡天垂野。\n望晴郊、疏烟半卷，断虹低跨。\n老树连阴藏远景，十里湖光照夜。\n看不尽、真山图画。\n春满轩窗无著处，更银蟾、冷浸鸳鸯瓦。\n人共境，转幽雅。\n文章太守归来也。\n似当年、和靖风流，小孤山下。\n问讯佩兰餐菊友，曾约梅兄入社。\n待付与、竹陶写。\n尘外闲寻行乐地，任傍人、歌舞喧台榭。\n诗世界，有王谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14026, '江神子・江城子', '刘镇2', '送春曾到百花洲。\n夕阳收。\n暮云留。\n想伴花神，骑鹤上扬州。\n回首湖山情味淡，重把酒，更登楼。\n相思南浦古津头。\n未拿舟。\n已惊鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14027, '阮郎归', '刘镇2', '寒阴漠漠夜来霜。\n阶庭风叶黄。\n归鸦数点带斜阳。\n谁家砧杵忙。\n灯弄幌，月侵廊。\n熏笼添宝香。\n小屏低枕怯更长。\n和云入醉乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14028, '阮郎归', '刘镇2', '金茎露未成霜。\n西风只旧凉。\n蕊仙何事换霞妆。\n恼人秋思长。\n香世界，锦文章。\n花神不覆藏。\n小山骚客政清狂。\n同花入醉乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14029, '玉楼春', '刘镇2', '泠泠水向桥东去。\n漠漠云归溪上住。\n疏风淡月有来时，流水行云无觅处。\n佳人独立相思苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14030, '木兰花慢', '刘镇2', '看纤云护月，湛河汉，夜声收。\n正玉尘生风，银床坠露，凉叶飕飕。\n襟怀静吞八表，莫登山临水易惊秋。\n闲想多情宋玉，旧来空替人愁。\n温柔。\n乡解老秋不。\n丝竹间秦讴。\n向橙橘香边，持螯把酒，聊伴清游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14031, '感皇恩', '刘镇2', '八十最风流，那谁不喜。\n况是精神可人意。\n太公当日，未必荣华如此。\n儿孙列两行，莱衣戏。\n好景良辰，满堂和气。\n唱个新词管教美。\n愿同彭祖，尚有八百来岁。\n十分才一分，那里暨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14032, '踏莎行', '刘镇2', '兰斛藏香，梅瓶浸玉。\n炉烟半袅屏山曲。\n谁烧银烛照黄昏，有人正倚萧萧竹。\n白雪歌翻，红牙板促。\n周郎自是难回目。\n禁寒不饮告推人，春风吹聚眉尖绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14033, '绛都春', '刘镇2', '和风乍扇，又还是去年，清明重到。\n喜见燕子，巧说千般如人道。\n墙头陌上青梅小。\n是处有、闲花芳草。\n偶然思想，前欢醉赏，牡丹时候。\n当此三春媚景，好连宵恣乐，情怀歌酒。\n纵有珠珍，难买红颜长年少。\n从他乌兔茫茫走。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14034, '秦楼月・忆秦娥', '张侃', '冰肌削。\n水沈香透胭脂萼。\n胭脂萼。\n怕愁贪睡，等闲梳掠。\n花前莫惜添杯酌。\n五更嫌怕春风恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14035, '月上海棠', '张侃', '南枝消息凭谁送。\n北枝寒、清晓破馀冻。\n横溪浸疏影，月黄昏、暗香浮动。\n真仙种。\n不与梨华同梦。\n洛阳姚魏争先贡。\n妒纷纷、红紫眩新宠。\n尽雪压风欺，□和羹、此时须用。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14036, '感皇恩', '张侃', '佳处记曾游，十年重到。\n罨画湖山最春早。\n红梅几树，一夜东风开了。\n矮松修竹外、依然好。\n玉色醺酣，香团娇小。\n消得金尊共倾倒。\n满怀风味，前度何郎今老。\n徘徊疏影里、花应笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14037, '感皇恩', '张侃', '换骨有丹砂，阿谁传与。\n爱惜芳心不轻吐。\n客来烂熳，解得此情良苦。\n有时三两点、胭脂雨。\n旧说江南，红罗亭下，未必春光便如许。\n认桃辨杏，最是渠家低处。\n问花曾怨不、娇无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14038, '西江月', '曾揆', '檐雨轻敲夜夜，墙云低度朝朝。\n日长天气已无聊。\n何况洞房人悄。\n眉共新荷不展，心随垂柳频摇。\n午眠仿佛见金翘。\n惊觉数声啼鸟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14039, '谒金门', '曾揆', '山衔日。\n泪洒西风独立。\n一叶扁舟流水急。\n转头无处觅。\n去则而今已去，忆则如何不忆。\n明日到家应记得。\n寄书回雁翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14040, '谒金门', '曾揆', '深院寂。\n一点春灯衔壁。\n空说销愁须酒力。\n病多禁未得。\n遥望西楼咫尺。\n争信今宵思忆。\n伴我枕头双泪湿。\n梧桐秋雨滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14041, '眼儿媚', '曾揆', '芙蓉帐冷翠衾单。\n魂梦几曾闲。\n怎禁未许，茫茫烟水，叠叠云山。\n去时频把归期约，远不过春残。\n而今已是，荷花开了，犹倚栏干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14042, '南柯子・南歌子', '曾揆', '桐叶凉生夜，藕花香满时。\n几多离思有谁知。\n遥望盈盈一水、抵天涯。\n雨洒征衣泪，月颦分镜眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14043, '西河', '曹豳', '今日事。\n何人弄得如此。\n漫漫白骨蔽川原，恨何日已。\n关河万里寂无烟，月明空照芦苇。\n谩哀痛，无及矣。\n无情莫问江水。\n西风落日惨新亭，几人堕泪。\n战和何者是良筹，扶危但看天意。\n只今寂寞薮泽里。\n岂无人、高卧闾里。\n试问安危谁寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14044, '红窗迥', '曹豳', '春闱期近也，望帝乡迢迢，犹在天际。\n懊恨这一双脚底。\n一日厮赶上五六十里。\n争气。\n扶持我去，转得官归，恁时赏你。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14045, '一翦梅', '周文璞', '风韵萧疏玉一团。\n更著梅花，轻袅云鬟。\n这回不是恋江南。\n只是温柔，天上人间。\n赋罢闲情共倚阑。\n江月庭芜，总是销魂。\n流苏斜掩烛花寒。\n一样眉尖，两处关山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14046, '浪淘沙', '周文璞', '还了酒家钱。\n便好安眠。\n大槐宫里著貂蝉。\n行到江南知是梦，雪压渔船。\n盘礴古梅边。\n也信前缘。\n鹅黄雪白又醒然。\n一事最奇君听取。\n明日新年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14047, '朝中措', '王武子', '画眉人去掩兰房。\n金鸭懒薰香。\n有恨只弹珠泪，无人与说衷肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14048, '玉楼春', '王武子', '红楼十二春寒恻。\n楼角何人吹玉笛。\n天津桥上旧曾听，三十六宫秋草碧。\n昭华人去无消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14049, '生查子', '魏子敬', '愁盈镜里山，心叠琴中恨。\n露湿玉阑秋，香伴银屏冷。\n云归月正圆，雁到人无信。\n孤损凤皇钗，立尽梧桐影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14050, '高阳台', '韩', '频听银签，重燃绛蜡，年华衮衮惊心。\n饯旧迎新，能消几刻光阴。\n老来可惯通宵饮，待不眠、还怕寒侵。\n掩清尊。\n多谢梅花，伴我微吟。\n邻娃已试春妆了，更蜂腰簇翠，燕股横金。\n勾引东风，也知芳思难禁。\n朱颜那有年年好，逞艳游、赢取如今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14051, '浪淘沙', '韩', '莫上玉楼看。\n花雨斑斑。\n四垂罗幕护朝寒。\n燕子不知人去也，飞认阑干。\n回首几关山。\n後会应难。\n相逢祗有梦魂间。\n可奈梦随春漏短，不到江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14052, '浪淘沙', '韩', '裙色草初青。\n鸭绿波轻。\n试花霏雨湿春晴。\n三十六梯人不到，独唤瑶筝。\n艇子忆逢迎。\n依旧多情。\n朱门只合锁娉婷。\n却逐彩鸾归去路，香陌春城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14053, '长相思', '韩', '郎恩深。\n妾思深。\n祗为恩深便有今。\n回纹辜旧吟。\n云沈沈。\n水沈沈。\n一点坚如百炼金。\n郎应知妾心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14054, '长相思', '韩', '杜娘家。\n谢娘家。\n楼压官桥柳半遮。\n帘波漾彩霞。\n拾飞花。\n怨飞花。\n望断郎来日又斜。\n东风吹鬓鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14055, '长相思', '韩', '夜萧萧。\n梦萧萧。\n又趁杨花到谢桥。\n凤沈明月箫。\n来迢迢。\n枉把吟笺寄寂寥。\n飞鸿不受招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14056, '好事近', '卓田', '奏赋谒金门，行尽云山无数。\n尚有江天一半，买扁舟东去。\n波神眼底识英雄，阁住半空雨。\n唤起一帆风力，去青天尺五。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14057, '昭君怨', '卓田', '千里功名歧路。\n几英雄草屦，八座与三台。\n个中来。\n壮士寸心如铁。\n有泪不沾离别。\n剑未斩楼兰。\n莫空还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14058, '品令', '卓田', '立秋十日，早露出新凉面。\n斜风急雨，战退炎光一半。\n月上纱窗，疑是广寒宫殿。\n无端宋玉，撩乱生悲怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14059, '眼儿媚', '卓田', '丈夫只手把吴钩。\n能断万人头。\n如何铁石，打作心肺，却为花柔。\n尝观项籍并刘季，一怒世人愁。\n只因撞着，虞姬戚氏，豪杰都休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14060, '酹江月・念奴娇', '卓田', '武夷山字，是使君衔上，新来带得。\n便觉闲中多胜事，满眼烟霞泉石。\n云卷尘劳，风生芒竹，去作山中客。\n晓坛朝罢，自然五福天锡。\n当此弧矢悬门，步虚声远，直透云霄碧。\n替却燕姬皓齿，洗尽人间筝笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14061, '沁园春', '卓田', '才大文豪，朱衣暗里，今须点头。\n奈兰宫一跌，槐黄时候。\n银袍逐浪，韦带随流。\n过尽鹤书，阅周鹗表，必竟都无名字留。\n空长恨，终不第，齿且先侯。\n休愁。\n有路堪由。\n最喜徐卿百不忧。\n正椿松未老，芝兰竞秀，奇毛雏凤，角犁牛。\n汉殿少年，新丰逆旅，岂肯卑微名位休。\n行将见，长沙召贾，御史除周。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14062, '满庭芳', '卓田', '柳暗千株，翻三荚，当年神岳生申。\n画堂庆会，今日贺生辰。\n宝鸭檀烟薰馥，颂椒觞、频斟。\n殷勤劝，歌喉宛转，恣乐醉红裙。\n荣华兼富贵，如君素享，胜似簪缨。\n虽田彭倚顿，未足多称。\n好是钱流地上，仓箱积、赈济饥贫。\n多阴德，子孙昌盛，指日绿袍新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14063, '木兰花・玉楼春', '锦溪', '华堂庆。\n一岁应须千百岁，乐事如何。\n寿酒斟时妹拜哥。\n爹夸利市。\n笑道看看生舍弟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14064, '壶中天・念奴娇', '锦溪', '骑鲸直上，问妲娥何日，天生英杰。\n笑下琼楼，还报道，甫近迎长佳节。\n万里无云，一天如水，拥出新团月。\n正当此夜，文星飞下天阙。\n蟾苑元有高枝，至今犹待，自是无心折。\n只爱林泉供笑傲，吟出阳春白雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14065, '满江红', '锦溪', '蓬岛仙翁，元来是、神锺岳渎。\n喜遇生申时节，一阳来复。\n荚合朝曾舞翠，月华昨夜圆如玉。\n展红笺、笔染新章，从头录。\n渭川叟，非钩绿。\n鲁公子，非徼福。\n况家传、胡氏长生。\n点额婴儿腾好语，殷勤捧献杯中绿。\n更九番、屈指铿年，为君祝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14066, '鹊桥仙', '李仲光', '诗书元帅，风流人物，看取方瞳如漆。\n铜驼陌上若相逢，当一笑、摩挲金狄。\n相门事业，中书考第，未数汾阳功绩。\n若将六十寿行年，才数得、百分之一。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14067, '百字令・念奴娇', '李仲光', '小红开也，问韶华、今年何事春早。\n尽道福星临照久，勾引东风仙岛。\n一点恩光，列城生意，万物无枯槁。\n圜扉深处，也应满地芳草。\n却怪有脚阳春，如何移向崆峒了。\n父老牵衣留不住，只有攀援遮道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14068, '鹊桥仙', '李仲光', '焚香清坐，呼童瀹茗，聊当一杯春酒。\n不须歌舞倩红裙，为祝百千长寿。\n诗书万卷，绮琴三弄，更有新词千首。\n从今日日与遨游，便是天长地久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14069, '失调名', '孙惟信', '寿花戴了。\n山童问、华庚多少。\n待瞒来、又怕旁人笑。\n况戒腊、淳熙可考。\n大衍之用恰恰好。\n学易後、尚一年小。\n谢屐唐衣眉山帽。\n薰风送下蓬岛。\n生巧。\n吕翁昨夜锺离早。\n又曾参、两个先生道。\n又也曾偷桃啖枣。\n百屋堆钱都不要。\n更不要、衮衣茸纛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14070, '风流子', '孙惟信', '三叠古阳关。\n轻寒噤、清月满征鞍。\n记玉笋揽衣，翠囊亲赠，绣巾脸，金柳初攀。\n自回首，燕台云掩冉，凤阁雨阑珊。\n天有尽头，水无西注，鬓难留黑，带易成宽。\n啼妆，东风悄，菱花在，拟倩锦字封还。\n应想恨蛾凝黛，慵髻堆鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14071, '烛影摇红', '孙惟信', '一朵红，宝钗压髻东风溜。\n年时也是牡丹时，相见花边酒。\n初试夹纱半袖。\n与花枝、盈盈斗秀。\n对花临景，为景牵情，因花感旧。\n题叶无凭，曲沟流水空回首。\n梦云不入小山屏，真个欢难偶。\n别後知他安否。\n软红街、清明还又。\n絮飞春尽，天远书沈，日长人瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14072, '清平乐', '孙惟信', '秋娘窗户。\n梦入阳台雨。\n小别殷勤留不住。\n恨满飞花落絮。\n一天晓月檐西。\n马嘶风拂罗衣。\n分付许多风致，送人行下楼儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14073, '阮郎归', '孙惟信', '满阶红影月昏黄，玉炉催换香。\n碧窗娇困懒梳妆。\n粉沾金缕裳。\n鸾髻耸，黛眉长。\n烛光分两行。\n许谁骑鹤上维扬。\n温柔和醉乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14074, '南乡子', '孙惟信', '璧月小红楼。\n听得吹箫忆旧游。\n霜冷阑干天似水，扬州。\n薄声名总是愁。\n尘暗裘。\n针线曾劳玉指柔。\n一梦觉来三十载，休休。\n空为梅花白了头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14075, '夜合花', '孙惟信', '风叶敲窗，露蛩吟瓮，谢娘庭院秋宵。\n凤屏半掩，钗花映烛红摇。\n润玉暖，腻云娇。\n染芳情、香透鲛绡。\n断魂留梦，烟迷楚驿，月冷蓝桥。\n谁念卖药文箫。\n望仙城路杳，莺燕迢迢。\n罗衫暗摺，兰痕粉迹都销。\n流水远，乱花飘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14076, '昼锦堂', '孙惟信', '薄袖禁寒。\n轻妆媚晚，落梅庭院春妍。\n映户盈盈，回倩笑整花钿。\n柳裁云剪腰支小，凤蟠鸦耸髻鬟偏。\n东风里，香步翠摇，蓝桥那日因缘。\n婵娟。\n留慧盼，浑当了、匆匆密爱深怜。\n梦过阑干，犹认冷月秋千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14077, '醉思凡・醉太平', '孙惟信', '吹箫跨鸾。\n香销夜阑。\n杏花楼上春残。\n绣罗衾半闲。\n衣宽带宽。\n千山万山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14078, '水龙吟', '孙惟信', '小童教写桃符，道人还了常年例。\n神前灶下，祓除清净，献花酌水。\n祷告些儿，也都不是，求名求利。\n但吟诗写字，分数上面，略精进、尽足矣。\n饮量添教不醉。\n好时节、逢场作戏。\n驱傩爆竹，软饧酥豆，通宵不睡。\n四海皆兄弟，阿鹊也、同添一岁。\n愿家家户户，和和顺顺，乐升平世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14079, '望远行', '孙惟信', '又还到元宵台榭。\n记轻衫短帽，酒朋诗社。\n烂漫向、罗绮丛中，驰骋风流俊雅。\n转头是、三十年话。\n量减才悭，自觉是、欢情衰谢。\n但一点难忘，酒痕香帕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14080, '失调名', '张端义', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14081, '倦寻芳', '张端义', '晓听社雨，犹带馀寒，尚侵襟袖。\n插柳千门，相近禁烟时候。\n鬓坠搔头深旧恨，臂宽条脱添新瘦。\n卷重帘，看双飞燕羽，舞庭花昼。\n谁共语、春来怕酒。\n一段情怀，灯暗更後。\n罨画屏山，今夜梦魂还又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14082, '谒金门', '卫元卿', '花过雨。\n又是一番红素。\n燕子归来愁不语。\n故巢无觅处。\n谁在玉楼歌舞。\n谁在玉关辛苦。\n若使边尘吹得去。\n东风侯万户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14083, '齐天乐', '卫元卿', '藕花洲上芙蓉楫，羞郎故移深处。\n弄影萍开，搴香袖，双双飞去。\n垂鞭笑顾。\n问住否横塘，试窥帘户。\n妙舞妍歌，甚时相见定相许。\n归来憔悴锦帐，久尘金犊，连娟黛眉颦妩。\n扇底红铅，愁痕暗渍，消得腰支如杵。\n鸾弦解语。\n镇明月西南，拌人凄楚。\n闷拾杨花，等闲春又负。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14084, '满庭芳', '彭止', '月闰清秋，时逢诞节，画堂瑞气多多。\n遥瞻南极，瑞彩照盘坡。\n好是年才五十，身当贵、福比山河。\n无些事，方裙短揭，时复自高歌。\n欢娱，当此际，香燃宝鸭，酒酌金荷。\n恣柳腰樱口，左右森罗。\n纵有人人捧拥，争得似、正面嫦娥。\n思量取，朱颜未老，好事莫蹉跎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14085, '留春令', '彭止', '夜来小雨三更作。\n近水处、小桃开却。\n玉女向晓掀朱箔。\n似与花枝有约。\n绿池上、柳腰纤弱。\n燕子过、谁家院落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14086, '兰陵王', '陈', '角声切。\n何处梅梢弄雪。\n还乡梦，玉井楼前，千朵芙蕖插空碧。\n邻翁问消息。\n为说红尘倦客。\n应怜笑、弓剑旌旗，底事留人未归得。\n淮山旧相识。\n记急处笙歌，静里锋镝。\n隋堤杨柳犹春色。\n嗟十载人事，几番棋局，青油年少已鬓白。\n漫惆怅京国。\n朱墨。\n困无力。\n似病鹤樊笼，老骥羁勒。\n夕阳不系栖林翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14087, '临江仙', '陈', '三十四年台榭，八千馀里江津。\n去时杨柳正轻颦。\n重来桃李少，不似旧时春。\n风扫半空烟雨，玉虹翠浪如新。\n可怜笳鼓送行人。\n白头梳上见，归梦枕边频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14088, '哨遍', '陈', '多病倦游，在家又贫，毕竟如何是。\n十万钱，骑鹤更扬州，是人间几曾有底。\n算一生，大都能消几屐，劳神到老成何事。\n趁齿落已双，发丝在两，归寻闲里滋味。\n不见青云路有危机。\n金缕歌声，渐变成悲。\n待思大东门，忆鹤华亭，悔之晚矣。\n休，归去来兮，北山幸有闲田地。\n地瘠宜瓜菜，引泉凿成方。\n这仲子蔬园，三公不换，况东陵自来瓜美。\n间走马溪头，倚阑垂钓，解衣自濯清。\n酿山泉、时复一中之。\n琴横膝。\n古淡无弦有音徽。\n送归鸿、暮云千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14089, '瑞龙吟', '方千里', '楼前路。\n愁对万点风花，数行烟树。\n依依斜日红收，暮山翠接，平芜尽处。\n小留伫。\n还是画栏凭暖，半扃朱户。\n帘栊尽日无人，消凝怅望，时时自语。\n堪恨行云难系，赋情杨柳，徘徊犹舞。\n追想向来欢娱，怀抱非故。\n题红寄绿，魂断江南句。\n何时见、轻衫雾唾，芳茵莲步。\n燕子西飞去。\n为人试道，相思闷绪。\n空有肠千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14090, '琐窗寒', '方千里', '燕子池塘，黄鹂院落，海棠庭户。\n东君暗许，借与轻风柔雨。\n奈春光困人正浓，画栏小立慵无语。\n念冶游时节，融怡天气，异乡愁旅。\n朝暮。\n凝情处。\n叹聚散悲欢，岁常十五。\n连飞并羽，未抵鸳朋凤侣。\n算章台、杨柳尚存，楚娥鬓影依旧否。\n再相逢、拼解雕鞍，燕乐同杯俎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14091, '风流子', '方千里', '春色遍横塘。\n年华巧、过雨湿残阳。\n正一带翠摇，嫩莎平野，万枝红滴，繁杏低墙。\n恼人是，燕飞盘软舞，莺语咽轻簧。\n还忆旧游，禁烟寒食，共追清赏，曲水流觞。\n回思欢娱处，人空老，花影尚占西厢。\n堪惜翠眉环坐，云鬓分行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14092, '渡江云', '方千里', '长亭今古道，水流暗响，渺渺杂风沙。\n倦游惊岁晚，自叹相思，万里梦还家。\n愁凝望结，但掩泪、慵整铅华。\n更漏长，酒醒人语，睥睨有啼鸦。\n伤嗟。\n回肠千缕，泪眼双垂，遏离情不下。\n还暗思、香翻香烬，深闭窗纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14093, '应天长', '方千里', '嫩黄上柳，新绿涨池，东风艳冶天色。\n又见乍晴还雨，年华傍寒食。\n春依旧，身是客。\n对丽景、易伤岑寂。\n怅凝望、一带平芜，剪就茵藉。\n前度少年场，醉记旗亭，联句遍窗壁。\n调笑映墙红粉，参差水边宅。\n芦鞭懒过故陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14094, '荔枝香', '方千里', '胜日登临幽趣。\n乘兴去。\n翠壁古木千章，林影生寒雾。\n空冷湿人衣，山路元无雨。\n深涧、斗泻飞泉溜甘乳。\n渔唱晚，看小棹、归前浦。\n笑指官桥，风酒旗斜举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14095, '荔枝香', '方千里', '小园花梢雨歇，浪羞泫。\n碧瓦光霁，罗幕香浮，莺啼燕语交加，是处池馆春遍。\n风外、认得笙歌近远。\n醉魂半萦，夜酒吹未散。\n暗忆年时，正日赴、西池宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14096, '还京乐', '方千里', '岁华惯，每到和风丽日欢再理。\n为妙歌新调，粲然一曲，千金轻费。\n记夜阑沈醉。\n更衣换酒珠玑委。\n怅画烛摇影，易积银盘红泪。\n向笙歌底。\n问何人、能道平生，聚合欢娱，离别兴味。\n谁怜露烟笼，尽栽培、艳桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14097, '扫花游・扫地游', '方千里', '野亭话别，恨露草芊绵，晓风酸楚。\n怨丝恨缕。\n正杨花碎玉，满城雪舞。\n耿耿无言，暗洒阑干泪雨。\n片帆去。\n纵百种避愁，愁早知处。\n离思都几许。\n但渐惯征尘，斗迷归路。\n乱山似俎。\n更重江浪淼，易沈书素。\n瞪目销魂，自觉孤吟调苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14098, '解连环', '方千里', '素封谁托。\n空寒潮浪叠，乱山云邈。\n对倦景，无语消魂，但香断露，絮飞风薄。\n杜宇声中，动多少、客情离索。\n远阑干伫立，暗记那回，赏遍花药。\n依依岁华自若。\n更低烟暮草，残照孤角。\n□叹息、故里春光，有幽圃名园，算也闲却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14099, '玲珑四犯', '方千里', '倾国名妹，似晕雪匀酥，无限娇艳。\n素质闲姿，天赋淡蛾丰脸。\n还是睡起慵妆。\n顾鬓影、翠云零乱。\n怅平生、把鉴惊换。\n依约琐窗逢见。\n绣帏凝想鸳鸯荐。\n画屏烘、兽烟葱。\n依红傍粉怜香玉，聊慰风流眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14100, '丹凤吟', '方千里', '宛转回肠离绪，懒倚危栏，愁登高阁。\n相思何处，人在绣帏罗幕。\n芳年艳齿，枉消虚过，会合丝轻，因缘蝉薄。\n暗想飞云骤雨，雾隔烟遮，相去还是天角。\n怅望不将梦到，素书谩说波浪恶。\n纵有青青发，渐吴霜妆点，容易凋铄。\n欢期何晚，忽忽坐惊摇落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14101, '满江红', '方千里', '为忆仙姿，相思恨、缠绵未足。\n从别後、沈郎消瘦，带围如束。\n消息三年沈过处，关山千里无飞肉。\n算谁知、中有不平心，弹棋局。\n空想像，金钗卜。\n时畏玩，回纹曲。\n许何时重到，琐窗华屋。\n长得一生花里活，软红深处鸳鸯宿。\n也胜如、骑马著征衫，京尘扑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14102, '瑞鹤仙', '方千里', '看青山绕郭。\n更暮草萋萋，疏烟漠漠。\n无风自花落。\n欲黄昏，谁向官楼吹角。\n刚肠顿弱。\n恨别来、辜负厚约。\n想香闺念旧，还忆去年，共举杯酌。\n寂寞。\n光阴虚度，未说离愁，泪痕先阁。\n珠帘翠幕。\n除相见，是奇药。\n况中年已後，凭高临远，情怀终是易恶。\n早归休，月地云阶，剩追笑乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14103, '西平乐', '方千里', '倦踏征尘，厌驱匹马，凝望故国犹赊。\n孤馆今宵，乱山何许，平林漠漠烟遮。\n怅过眼光阴似瞬，回首欢娱异昔，流年迅景，霜风败苇惊沙。\n无奈轻离易别，千里意，制泪独长嗟。\n绮窗人远，青门信杳，叙影何时，重见云斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14104, '浪淘沙', '方千里', '素秋霁，云横旷野，浪拍孤堞。\n柔橹悲声顿发。\n骊歌恨曲未阕。\n念一寸回肠千缕结。\n柳条在、忍使攀折。\n但怅惘章台路多少，相思拼愁绝。\n凄切。\n去程浩渺空阔。\n奈断梗孤蓬，西风外、蔌蔌残吹咽。\n应暗为行人，伤念离别。\n泪波易竭。\n凝怨怀、羞睹当时明月。\n烟浪无穷青山叠。\n鱼封远、雁书渐歇。\n甚时合、金钗分处缺。\n谩飘荡、海角天涯，再见日，应怜两鬓玲珑雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14105, '忆旧游', '方千里', '念花边玉漏，帐里鸾笙，曾款良宵。\n缕鸭吹香雾，更轻风动竹，韵响潇潇。\n画檐皓月初挂，帘幕纹摇。\n记罢曲更衣，挑灯细语，酒晕全消。\n迢迢。\n旧时路，纵下马铜驼，谁听扬镰。\n奈可怜庭院，又徘徊虚过，清梦难招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14106, '蓦山溪', '方千里', '园林晴昼，花上黄峰尾。\n莺语怯游人，又还傍、绿杨深避。\n曲池斜迳，草色碧於蓝，栏倦倚。\n帘半起。\n魂断斜阳里。\n江南春尽，渺渺平桥水。\n身在一天涯，问此恨、何时是已。\n飞帆轻桨，催送莫愁来，歌舞地。\n尊酒底。\n不羡东邻美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14107, '少年游', '方千里', '丹青闲展小屏山。\n香炉一丝寒。\n织锦回纹，生绡红泪，不语自羞看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14108, '少年游', '方千里', '东风无力扬轻丝。\n芳草雨馀姿。\n浅绿还池，轻黄归柳，老去愿春迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14109, '秋蕊香', '方千里', '一枕盘莺锦暖。\n初起懒匀妆面。\n绿云袅娜映娇眼。\n酒入桃腮晕浅。\n翠帘半卷香萦线。\n碍飞燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14110, '渔家傲', '方千里', '烛彩花光明似昼。\n罗帏夜出倾城秀。\n红锦纹茵双凤斗。\n看舞後。\n腰肢宛胜章台柳。\n眼尾春娇波态溜。\n金樽笑捧纤纤袖。\n一阵粉香吹散酒。\n更漏久。\n消魂独自归时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14111, '渔家傲', '方千里', '冷叶啼声恻恻。\n银床晓起清霜积。\n魂断江南烟水国。\n书难得。\n相思此意无人识。\n绿鬓金钗年少客。\n愁来懒傍菱花仄。\n雾阁云窗闲枕席。\n情何适。\n杯盈珠泪还偷滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14112, '南乡子', '方千里', '西北有高楼。\n淡霭残烟渐渐收。\n几阵凉风生客袖，飕飕。\n心逐年华衮衮流。\n花卉满前头。\n老懒心情万事休。\n独倚栏干无一语，回眸。\n鼓角声中唤起愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14113, '望江南・忆江南', '方千里', '春色暮，短艇舣长堤。\n飞絮空随花上下，啼莺占断水东西。\n来往燕争泥。\n桑柘绿，归去觅前溪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14114, '浣沙溪・浣溪沙', '方千里', '杨柳依依地垂。\n鞠尘波影渐平池。\n霏微细雨出鱼儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14115, '浣沙溪・浣溪沙', '方千里', '无数流莺远近飞。\n垂杨袅袅弄晴晖。\n断肠声里送春归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14116, '浣沙溪・浣溪沙', '方千里', '清泪斑斑著意垂。\n消魂迢递一天涯。\n谁能万里布长梯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14117, '迎春乐', '方千里', '参差凤铎鸣高屋。\n渐惊觉、清眠熟。\n看夕阳倒影花阴速。\n双燕子、归来宿。\n几曲危肠愁易束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14118, '迎春乐', '方千里', '红深绿暗春无迹。\n芳心荡、冶游客。\n记摇鞭跋马铜驼陌。\n凝睇认、珠帘侧。\n絮满愁城风卷白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14119, '点绛唇', '方千里', '池馆春深，海棠枝上斑斑雨。\n酒旗斜举。\n风滚杨花絮。\n游子征衫，凭暖阑干处。\n空凝伫。\n杜鹃啼苦。\n还报南楼鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14120, '一落索', '方千里', '月影娟娟明秀。\n帘波吹皱。\n徘徊空度可怜宵，谩问道、因谁瘦。\n不见芳音长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14121, '洞仙歌', '吴泳', '翠柔香嫩，乍春风庭院。\n换却幽人读书眼。\n淡鹅黄袅袅，玉破梢头，莺未啭，绿皱池波尚浅。\n王孙才别後，长负芳时，碧草萋萋绣软。\n海棠桃花雨，红湿青衫，春心荡，不省花飞减半。\n待持酒高堂、劝东皇，且爱惜芳菲，留春借暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14122, '上西平・金人捧露盘', '吴泳', '跨征鞍，横战槊，上襄州。\n便匹马、蹴踏高秋。\n芙蓉未折，笛声吹起塞云愁。\n男儿若欲树功名，须向前头。\n凤雏寒，龙骨朽，蛟渚暗，鹿门幽。\n阅人物、渺渺如沤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14123, '贺新凉・贺新郎', '吴泳', '额扣龙墀苦。\n对南宫、春风侍女，掉头不顾。\n烽火连营家万里，漠漠黄沙吹雾。\n莽关塞、白狼玄兔。\n如此江山俱破碎，似输棋、局满枰无路。\n弹血泪，迸如雨。\n轻帆且问夔州戍。\n俯江流、桑田屡改，阵图犹故。\n抱此孤忠长耿耿，痛恨年华不与。\n但月落、荒洲绝屿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14124, '青玉案', '吴泳', '玉骢已响关头路。\n待携取、功名去。\n慷慨不歌桃叶渡。\n囊书犹在，剑花未落，富有经纶处。\n从军缅想当年赋。\n纵局局翻新只如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14125, '满江红', '吴泳', '白鹤山人，被推作、诸军都督。\n对朔雪边云，上马龙光郁。\n戊己营西连太白，甲丁旗尾扪箕宿。\n倚梅花、听得凯歌声，横吹曲。\n船易漏，难沃。\n柯易烂，棋难复。\n阅勋名好样，只推吾蜀。\n风撼藕塘猩鬼泣，月吞采石鲸鲵戮。\n管明年、缚取敌人回，持钧轴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14126, '满江红', '吴泳', '倦客无家，且随寓、瞻乌爰止。\n浪占得，清溪一曲，水鲜山美。\n菡萏香浮几案上，芙蓉月落吟窗里。\n纵结庐、虽不是吾庐，聊复尔。\n人似玉，神如水。\n歌古调，传新意。\n问老庞何日，携家来此。\n後著岂无棋对待，前锋自有诗当底。\n若新秋、京口酒船来，仍命寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14127, '八声甘州', '吴泳', '每逢人、都道早归休，何曾猛归来。\n有邵平瓜圃，渊明菊径，谁肯徘徊。\n底是无波去处，空弄一竿桅。\n富贵非吾事，野马浮埃。\n况值清和时候，正青梅未熟，煮酒新开。\n共倒冠落佩，宁使别人猜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14128, '贺新郎', '吴泳', '一片湖光净。\n被游人、撑船刺破，宝菱花镜。\n和靖不来东坡去，欠了骚人逸韵。\n但翠葆、玉钗横鬓。\n碧藕花中人家住，恨幽香、可爱不可近。\n沙鹭起，晚风进。\n功名得手真奇隽。\n黯离怀、长堤翠柳，系愁难尽。\n世上浮荣一时好，人品百年论定。\n且牢守、文章密印。\n秘馆词人能度曲，更不消、檀板标苏姓。\n凌浩渺，纳光景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14129, '满江红', '吴泳', '风约湖船，微摆撼、水光山色。\n纵夹岸、秋芳冷淡，亦随风拆。\n荷芰尚堪骚客制，兰苕犹许诗人摘。\n最关情、疏雨画桥西，宜探索。\n蓬岛上，神仙宅。\n苍玉佩，青城客。\n把从前文字，委诸河伯。\n涵浸胸中今古藏。\n编排掌上乾坤策。\n却仍携、新草阜陵书，归山泽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14130, '洞庭春色・沁园春', '吴泳', '金柝声中，铁衣影里，仍旧上元。\n况银花鬓，看承春色，蜡珠照坐，暖熟丰年。\n宝月分明无缺玷，须洗尽黄云别看天。\n无限意，且平开莲浦，小作桃源。\n灯花夜来有喜，捷书便驰至军前。\n响乐棚高处，何妨颂圣，体筵侧傍，仍与中贤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14131, '洞庭春色・沁园春', '吴泳', '兰切膏凝，柳沟燧落，光景乍新。\n正石坛人静，风清绮陌，朱筵灯闹，雨压香尘。\n不似潘郎花作县，且管勾江山当主人。\n看承处，有帘犀透月，蜡凤烧云。\n裴回五花泉上，问谁解攻打愁城。\n算人生行乐，不须富贵，官居游适，必就高明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14132, '菩萨蛮', '吴泳', '莺花旧恨凭谁雪。\n也须管句灯时节。\n黄已上眉峰。\n小槽初滴红。\n好天佳月夕。\n结佩飞霞客。\n醒恐不如酲。\n何妨独屡更。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14133, '点绛唇', '李铨', '一朵千金，帝城谷雨初晴後。\n粉拖香透。\n雅称群芳首。\n把酒题诗，遐想欢如旧。\n花知否。\n故人清瘦。\n长忆同携手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14134, '鹊桥仙', '王大烈', '银潢流派，嫦娥出世。\n正是麦秋天气。\n荧煌一点寿星明，又恰向、今宵呈瑞。\n佳儿龙跳，荣封迩止。\n试问遐龄知几。\n从今旋数一千年，待足了、依前数起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14135, '蓦山溪', '王大烈', '东风吹物，渐入韶华媚。\n和气散千门，更灵鹊、前村报喜。\n月宫仙子，昨夜下瑶台，人传道，诞兰房，喜把金盆洗。\n中郎传业，此事今如意。\n遥想画堂中，有葱葱、云烟瑞。\n休言前日，玉燕不来投，看释氏，到明年，又送麒麟至。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14136, '念奴娇', '程公许', '晓凉散策，恨西风不贷，一池残绿。\n谁与冰轮玉斧，恰好今宵圆足。\n树杪翻光，莎庭转影，零乱昆台玉。\n荡胸清露，闲须浇下。\n休问湖海飘零，老人心事，似倚岩枯木。\n万里亲知应健否，脉脉此情谁属。\n世虑难平，天高难问，倚遍阑干曲。\n不妨随寓，买园催种松竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14137, '沁园春', '程公许', '万里飘萍，送江入海，过古润州。\n正羁怀无奈，凭高纵览，烟雨，簇簇渔舟。\n南北区分，江山形胜，忧愤令人扶上楼。\n沈凝久，任斜飞雪片，急洒貂裘。\n英风追想孙刘。\n似黑白两奁棋未收。\n把烟霞饶与，坡仙米老，丹青难觅，摩诘营邱。\n斗野号风，海门残照，长与人间管领愁。\n凭谁问，借天河一挽，洗甲兵休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14138, '水调歌头', '程公许', '驼褐倚禅榻，丝鬓扬茶烟。\n谁知老子方寸，历历著千年。\n试问汗青馀几，一笑腰黄萦梦，我自乐天全。\n出处两无累，赢取日高眠。\n八千里，西望眼，断霞边。\n弁苍苕碧，随分风月不论钱。\n执手还成轻别，何日归来投社，玉海得同编。\n经世付时杰，觅个钓鱼船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14139, '水调歌头', '包恢', '羽觞随曲水，佳气溢双清。\n真贤瑞世，恰与真圣日同生。\n出侍红云一朵，出按皇华六辔，特地福吾闽。\n底是长生，八郡咏歌声。\n奏天子，倾义廪，济饥民。\n南州指使，青州公案一般仁。\n却恐紫泥有诏，社稷重臣事业，非晚觐岩宸。\n来岁这般节，宣劝玉堂人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14140, '水调歌头', '岳甫', '鲁口天下壮，襟楚带三吴。\n山川表里营垒，屯列拱神都。\n鹦鹉洲前处士，黄鹤楼中仙客，拍手试招呼。\n莫诵昔人句，不食武昌鱼。\n望樊冈，过赤壁，想雄图。\n寂寥霸气，应笑当日阿瞒疏。\n收拾周黄策略，成就孙刘基业，未信赏音无。\n我醉君起舞，明日隔江湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14141, '满江红', '岳甫', '碧海迢遥，曾窥见、赤城楼堞。\n因傲睨尘寰，犹带凭虚仙骨。\n武库胸中兵十万，文场笔阵诗千百。\n记向来、小是听胪传，居前列。\n世间事，都未说。\n亲为大，官毫末。\n况诸郎锺庆，凤龄英发。\n银菟颁符方易地，金銮寓直行趋阙。\n更相期、尽节早归来，传丹诀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14142, '木兰花慢', '岳珂', '试晨妆淡伫，正疏雨、过含章。\n早巧额回春，岭云护雪，十里清香。\n何人剪冰缀玉，仗化工、施巧付东皇。\n瘦尽绮窗寒魄，凄凉画角斜阳。\n孤山西畔水云乡。\n篱落亚疏篁。\n问多少幽姿，半归图画，半入诗囊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14143, '六州歌头', '岳珂', '海棠开後，红雨洒江。\n春风路，窥杏非，剪葵榛。\n绕梅魂。\n满院禽声悄，扶醉起，初睡足，诮不似，玉奴辈，负东昏。\n回首曲江，多少花边卧，高麒麟。\n谩名缰利锁，何日濯尘缨。\n几绊浮生。\n遣区惊。\n试从今数，春归日，留不住，掩重门。\n风雨遇，归阆女，战吴军。\n费温存。\n总被流莺笑，英烂熳，误间关。\n诗卷债，负便腹，遂吟肝。\n长记风光流转，问少陵、曾与春言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14144, '醉落魄・一斛珠', '岳珂', '铜彝绣箔。\n风流不到临春阁。\n婆娑清影来岩壑。\n梅魄兰魂，香染九秋萼。\n蕊仙拥下青瑶幕。\n粟肌透入黄金约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14145, '满江红', '岳珂', '小院深深，悄镇日、阴晴无据。\n春未足、闺愁难寄，琴心谁与。\n曲径穿花寻蛱蝶，虚栏傍日教鹦鹉。\n笑十三、杨柳女儿腰，东风舞。\n云外月，风前絮。\n情与恨，长如许。\n想绮窗今夜，为谁凝伫。\n洛浦梦回留佩客，秦楼声断吹箫侣。\n正黄昏时候杏花寒，廉纤雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14146, '生查子', '岳珂', '芙蓉清夜游，杨柳黄昏约。\n小院碧苔深，润透双鸳薄。\n暖玉惯春娇，簌簌花钿落。\n缺月故窥人，影转阑干角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14147, '祝英台近', '岳珂', '瓮城高，盘径近。\n十里笋舆稳。\n欲驾还休，风雨苦无准。\n古来多少英雄，平沙遗恨。\n又总被、长江流尽。\n倩谁问。\n因甚衣带中分，吾家自畦畛。\n落日潮头，慢写属镂愤。\n断肠烟树扬州，兴亡休论。\n正愁尽、河山双鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14148, '祝英台近', '岳珂', '澹烟横，层雾敛。\n胜概分雄占。\n月下鸣榔，风急怒涛。\n关河无限清愁，不堪临鉴。\n正霜鬓、秋风尘染。\n漫登览。\n极目万里沙场，事业频看剑。\n古往今来，南北限天堑。\n倚楼谁弄新声，重城正掩。\n历历数、西州更点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14149, '酹江月・念奴娇', '岳珂', '天然灵种，遍尘寰、不许一枝分植。\n瀛海沈沈群玉宴，迥出八仙标格。\n珠幄留云，翠绡笼雪，浅露宫黄额。\n无双亭下，未容凡卉连璧。\n犹是射虎归来，朱阑独倚，曾作东风客。\n素态自羞时态改，何必铅华倾国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14150, '采桑子', '朱藻', '障泥油壁人归後，满院花阴。\n楼影沈沈。\n中有伤春一片心。\n闲穿绿树寻梅子，斜日笼明。\n团扇风轻。\n一径杨花不避人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14151, '水龙吟', '陈以庄', '晚来江阔潮平，越船吴榜催人去。\n稽山滴翠，胥涛溅恨，一襟离绪。\n访柳章台，问桃仙浦，物华如故。\n向秋娘渡口，泰娘桥畔，依稀是、相逢处。\n窈窕青门紫曲，罗新、衣翻金缕，旧音恍记，轻拢慢拈，哀弦危柱。\n金屋难成，阿娇已远，不堪春暮。\n听一声杜宇，红殷绿老，雨花风絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14152, '贺新郎', '陈以庄', '晓梦莺呼起。\n便安排、诗家厨传，酒家行李。\n点检花边新雨露，春在万家生齿。\n道官似、锦溪清驶。\n但便有人耕绿野，正不妨、鼓吹频来此。\n方觅句，且夷俟。\n画桥西畔多春意。\n记年年、曾来几度，落花流水。\n信到水穷云起处，依约辋川竹里。\n兴未属、王孙公子。\n料想明年端门里，有传柑宴罢黄封醉。\n肯回首，万杉底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14153, '蓦山溪', '陈以庄', '亭兰风蕙，昨日山阴曲。\n又过五峰来，听华堂、管弦丝竹。\n今年风物，著意庆生朝，□鹤舞，黑猿吟，花下眠青鹿。\n九龄五福，盛事人皆祝。\n谁识种春翁，等浮云、飞过目。\n上方渴士，忠节起闻孙，金坡近，玉堂深，莫羡春田绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14154, '摸鱼儿', '苏', '望关河、试穷遥眼，新愁似丝千缕。\n刘郎豪气今何在，应是九疑三楚。\n堪恨处。\n便拚得、一生寂寞长羁旅。\n无人寄语。\n但吊麦伤桃，边松倚竹，空忆旧诗句。\n文章事，到底将身自误。\n功名难料迟暮。\n鹑衣箪食年年瘦，受侮世间儿女。\n君信否。\n尽县簿高门，岁晚谁青顾。\n何如引起。\n任槎上张骞，山中李广，商略尽风度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14155, '雨中花・夜行船', '苏', '十载尊前，放歌起舞，人间酒户诗流。\n尽期君凌厉，羽翮高秋。\n世事几如人意，儒冠还负身谋。\n叹天生李广，才气无双，不得封侯。\n榆关万里，一去飘然，片云甚处神州。\n应怅望、家人父子，重见无由。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14156, '菩萨蛮', '许', '西风又转芦花雪。\n故人犹隔关山月。\n金雁一声悲。\n玉腮双泪垂。\n绣衾寒不暖。\n愁远天无岸。\n夜夜卜灯花。\n几时郎到家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14157, '水调歌头', '王迈', '天上一灯满，引起万灯明。\n不知今夕何夕，平地有蓬瀛。\n西母瑶池称寿，南守锋车催觐，二美一时并。\n一点魁星现，长侍老人星。\n心事好，天与寿，鬓长青。\n不将锺鼎为乐，念念在朝廷。\n此母宜生此子，须有医时良策，寿国福苍生。\n子自坐黄阁，母自课黄庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14158, '沁园春', '王迈', '人物渺然，蕙兰椒艾，孰臭孰香。\n昔尹公和靖，与龟山老，虽同名节，却异行藏。\n尹在当年，深居养道，亲见兵戈兴洛阳。\n杨虽出，又何畀於蔡，何救於章。\n公今为尹为杨。\n这一著须平心较量。\n正南洲潢弄，西淮鼎沸，廷绅噤舌，举国如狂。\n招鹤亭前，居然高卧，许大乾坤谁主张。\n公须起，要擎天一柱，支架明堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14159, '贺新郎', '王迈', '出了罗浮洞。\n有多情、梅花雪片，殷勤相送。\n见说け然琴鹤外，诗压牛腰较重。\n去管甚、群儿嘲弄。\n岭海三年持翠节，料无时、不作家山梦。\n驰玉勒，归金凤。\n金凤池，乃所居也。\n一门朱紫环昆仲。\n看阶庭、森森兰玉，慈颜欢动。\n宰相时来须著做，且舞莱衣侍奉。\n却不信、大才难用。\n时事多艰人物少，便中兴、谁辨浯溪颂。\n为大厦，要梁栋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14160, '贺新郎', '王迈', '此是河清宴。\n觉朝来、薰风满入，生绡团扇。\n太守愁眉才一展，且喜街头米贱。\n且莫管、官租难办。\n绕砌苔钱无限数，更莲池、雨过珠零乱。\n尽买得，凌波面。\n家山乐事真堪羡。\n记年时、荔支新熟，荷筒齐劝。\n底事来寻蕉鹿梦，赢得乾忙似箭。\n笑富贵、都如邮传。\n做了丰年还百姓，便莼鲈、归兴催张翰。\n看卿等，上霄汉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14161, '贺新郎', '王迈', '忆昔同时召。\n正青山、亲提玉尺，量材廊庙。\n当日班行比元，北玉西珠照耀。\n一转首、宫商移调。\n君自乌台登骑省，觉精神、风采增清峭。\n数贤者，一不肖。\n酒酣耳热惟长啸。\n便翩翩、辍班荷橐，一麾闽峤。\n堪笑狂生无用处，垂老云耕月钓。\n这富贵、非由人要。\n畴昔评君如玉雪，好け然、琴鹤风尘表。\n清献後，又有赵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14162, '贺新郎', '王迈', '璎珞珠垂缕。\n看花冠、端容丽服，补陀岩主。\n只坐尘缘蹉一念，朱紫丛中得度。\n人世福、夫人兼五。\n银鹿诸孙来定省，对金屏、绣幕辉云母。\n人顶礼，柳行路。\n所居地名柳行。\n朝朝口诵琅函句。\n觉从来、寿人福善，老夭无误。\n消得天恩封福国，锦诰鸾翔凤舞。\n听来岁、日边佳语。\n上殿肩舆帘蹙绣，遣佳儿、扶掖天应许。\n笑陈媪，三题柱。\n有陈夫人者，');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14163, '摸鱼儿', '王迈', '昔元城、一生清峭，南都高卧坚壁。\n留耕便是元城样，何肯枉吾寻尺。\n曾直笔。\n说社稷安危，屡叩龙墀额。\n明时逐客。\n却惠顾丹山，来持翠节，对此一湾碧。\n澄清暇，无奈登临有癖。\n梅山时访仙迹。\n神仙偏喜公心事，一见莞然前席。\n闲不得。\n有先见蓍龟，消得君王忆。\n天阍不隔。\n要济险孤舟，支倾一柱，公外向谁觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14164, '沁园春', '王迈', '首尾四年，台省好官，都做一回。\n便前头更有，合当做底，何妨且恁，猛省归来。\n甲第新成，开尊行乐，脆管繁弦十二钗。\n回头笑，这狂生无用，削尽官阶。\n狂生真个狂哉。\n泼性气年来全未灰。\n有龙鳞凤翼，不能攀附，牛衣渔具，早已安排。\n烂煮园蔬，熟煨山芋，白发苍颜穷秀才。\n官休做，莫狂无处著，送去琼崖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14165, '念奴娇', '王迈', '层台云外，阅古今、多少兴衰成败。\n老木千章，若个是、南国甘棠遗爱。\n群籁号风，繁阴蔽日，有此清凉界。\n宾朋在坐，朗然心目明快。\n更向会景亭前，登高吊古，此景何人会。\n岁岁春来春又去，独有灵台春在。\n早稻炊香，晚禾摇穗，管取三登泰。\n酿成春酒，把杯行乐须再。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14166, '沁园春', '王迈', '一笑樽前，数雄甲辰，几位上台。\n有唐裴相，徜徉绿野，我朝富老，游戏昆台。\n淮蔡功成，惊天动地，似胜单车和虏回。\n谁知道，活流民数万，赛过平淮。\n君侯初度奇哉。\n五百岁、三贤前後来。\n任朱幡西向，不妨为富，义旗北指，也解为裴，将相功名，时来便做，且醉红蕖三百杯。\n相期处，要千年汗竹，名节崔嵬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14167, '贺新郎', '王迈', '曾侍螭头立。\n吐危言、婴鳞编虎，扶持鳌极。\n谁炼精金铸刚卯，气节毅然镇国。\n肯顾恋、眼前官职。\n碧水丹山持翠节，这福星、特为吾闽出。\n发义廪，无难色。\n如今世道难扶植。\n直还他、温公德量，魏公风力。\n此事又关宗社福，仍系苍生休戚。\n且称寿、公生人日。\n炼得内丹成熟後，看河车、常运方瞳碧。\n五百岁，作良弼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14168, '瑞鹤仙', '王迈', '芳菲春二月。\n正软红尘里，踏青时节。\n山川孕人杰。\n好赤城丹洞，丰姿奇绝。\n云霄阀阅。\n个精神、清如玉雪。\n看谈兵议论，风霆舞剑，刚肠如铁。\n闻说。\n年方英妙，已向城边，飞书驰捷。\n誓清击楫。\n宁久此，淹车辙。\n对花朝称寿，朱颜未老，尽有功名事业。\n便张韩刘岳传名，何如一叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14169, '满江红', '王迈', '明日元宵，蔼佳气、清凉金粟。\n人道是、史君寿母，宴瑶池曲。\n九十春来萱草茂，三千年後蟠桃熟。\n看鳌头、名字未多时，分符竹。\n熏宝篆，张银烛。\n佳庆事，人人祝。\n况平反阴德，在长生。\n最喜芸香怀玉燕，安排锦帐骑银鹿。\n待雕轩、文驷上堤沙，如天福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14170, '满江红', '王迈', '轻暖轻寒，正春满、河阳花县。\n谁报道，金铃声响，百花开遍。\n天上谪仙人瑞世，佛中有宰官身现。\n好看承、金母上瑶池，开华宴。\n争捧取，金樽劝。\n更把取，丹砂炼。\n要朱颜长对，舞裙歌扇。\n准拟来年称寿日，沈香亭里春生面。\n有安期、大枣伴蟠桃，年年献。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14171, '念奴娇', '王迈', '见山堂上，画帘卷、犹是清和天气。\n绿水红莲，雅称得、瑶碧冰壶标致，名在丹台，籍通紫府，游戏人间世。\n三洪华阀，自应生此人瑞。\n好是佳旦称觞，班衣拜舞，有雏相对。\n後院婵娟争劝酒，端午彩丝双系。\n管取来年，雪罗风葛，荣被君恩赐。\n黑头公相，直须眉寿千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14172, '水龙吟', '王迈', '橙黄橘绿佳期，诘朝又报阳来复。\n笼葱瑞气，天教蟠绕，名门乔木。\n上界仙人，来游西塾，骖鸾跨鹤。\n有如椽彩笔，笺天万字，□呈了、琅腹。\n不愿班行鸣玉。\n问君王、再分符竹。\n棣华辉映，庭萱春好，举杯相属。\n伯氏乘轺，诸公须又，安排除目。\n这堆床牙笏，人人道是，太夫人福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14173, '沁园春', '王迈', '老今朝，载酒渡江，送孟吉州。\n遇舟之人士，来前问政，此公官去，莫也宜留。\n老子曰嘻，我游宦海，几度遭他风打头。\n君休问，但正因遇坎，行则乘流。\n江皋一叶惊秋。\n雁过也、严明白鹭洲。\n笑如今休顾，从前堕甑，无心相逐，等是虚舟。\n啄黍鸡肥，新酒熟，且作山中万户侯。\n林泉好，却输公一著，先我归休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14174, '南歌子', '王迈', '家里逢重九，新熟浊醪。\n弟兄乘兴共登高。\n右手茱杯、左手笑持螯。\n官里逢重九，归心切大刀。\n美人痛饮读离骚。\n因感秋英、饷我菊花糕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14175, '沁园春', '王迈', '夜来斗庵，左顾绿云，右盼素娥。\n好态浓意远，随宜梳洗，轻轻莲步，艳艳秋波。\n妒宠争妍，娇痴无际，齐劝诗翁金叵罗。\n翁微笑、□一时饮尽，谁少谁多。\n月娥。\n唱後颜酡。\n莫也怕、浮云妒月麽。\n问苏州刺史，旧欢如梦，江州司马，衫湿如何。\n翠幕空垂，唾花无迹，忍听樽前飞燕歌。\n销凝处，正潇潇烟雨，偏恼东坡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14176, '贺新凉・贺新郎', '叶路钤', '伛指循良吏。\n祗吴公、传不书名，一人而已。\n彷佛三生来展骥。\n就种棠阴千里。\n又还是、治平为最。\n绣线渐添红日影，恰搀前、七日冬书至。\n吾道长，佛出世。\n公清但酌螺川水。\n屏星躔次吴头，极星先比。\n节谊家声香国史。\n中有千秋生意。\n宜衮衮、公侯昌炽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14177, '水调歌头', '叶路钤', '天启黄旗运，复见汉黄香。\n名高黄榜，飞黄腾踏入鸳行。\n文彩苏黄而上，政事龚黄而右，黄纸选循良。\n黄见眉间色，卿月照黄堂。\n调黄锺，舞黄鹤，醉鹅黄。\n黄云催熟，黄童老叟庆金穰。\n闲展黄庭一卷，自爱黄花晚节，黄阁日偏长。\n印佩黄金斗，黄发半苍苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14178, '摸鱼儿', '曾开国', '望层霄、五云开处。\n屏星光射螺浦。\n复来七日冬将至，恰则岳神生甫。\n梅半吐。\n试索笑巡檐，稍稍香风度。\n花娇欲语。\n问昔日治平，吴公无传，今请为公歌襦裤。\n□□□，玉粒家家丰贮。\n因人岂关天数。\n金城千里谁能护，前召又逢後杜。\n□□□。\n见说道、长安新筑沙堤路。\n班催鹭序。\n垂色醉蟠桃，胸中色线，待把衮衣补。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14179, '十二时・忆少年', '彭耜', '素馨花、在枝无几。\n秋入阑干十二。\n那茉莉、如今已矣。\n只有兰英菊蕊。\n霜蟹年时，香橙天气。\n总是悲秋意。\n问宋玉、当日如何，对此凄凉风月，怎生存济。\n还未知、幽人心事。\n望得眼穿心碎。\n青鸟不来，彩鸾何处，云锁三山翠。\n是碧霄有路，要归归又无计。\n奈何他、水长天远，身又何曾生翼。\n手拈芙蓉，耳听鸿雁，怕有丹书至。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14180, '喜迁莺', '彭耜', '吾家何处。\n对落日残鸦，乱花飞絮。\n五湖四海，千岩万壑，已把此生分付。\n怎得海棠心绪，更没鸳鸯债负。\n春正好，叹流光有限，老山无数。\n归去。\n君试觑。\n紫燕黄鹂，愁怕韶华暮。\n细雨斜风，断烟芳草，暑往寒来几度。\n锁却心猿意马，缚住金鸟玉兔。\n今古事，似一江流水，此怀难诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14181, '婆罗门引', '彭耜', '中秋皓月，隔霄光倍照尘寰。\n九龙喷香水，胜沈檀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14182, '南乡子', '赵葵', '束发领西藩。\n百万雄兵掌握间，召到庙堂无一事，遭弹。\n昨日公卿今日闲。\n拂晓出长安。\n莫待西风割面寒。\n羞见钱塘江上柳，何颜。\n瘦仆牵驴过远山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14183, '庄椿岁・水龙吟', '方味道', '纶巾少驻家山，北窗睡觉南薰起。\n黄庭细看，长生秘诀，神仙奇趣。\n奈此苍生，愿苏炎熟，仰为霖雨。\n趁丹心未老，将整顿乾坤，手为经理。\n好是今年庆事。\n抱奇孙、一门佳气。\n蓬山振佩，麟符重锡，褒纶新美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14184, '沁园春', '黄机', '问讯西园，一春几何，君今再游。\n记流觞亭北，偷拈酒戏，凌云台上，暗度诗阄。\n略略花痕，差差柳意，十日不来红绿稠。\n须重醉，便功名了後，白发争休。\n定谁骑鹤扬州。\n任书放床头盏瓮头。\n况殷勤莺燕，能歌更舞，轻狂蜂蝶，欲去还留。\n岁月易忘，姓名须载，笔势翩翩回万牛。\n归来晚，有烛明金剪，香暖珠篝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14185, '沁园春', '黄机', '六月云初，人争议公，公无阻伤。\n记传飞急羽，舟还海道，弥漫白水，路入沙场。\n万姓三军，倚公为命，法有逗遛公自当。\n君还信，似崔嵬砥柱，屹立瞿塘。\n此行阴德难量。\n到论定才知滋味长。\n看鱼肥蟹健，妻孥共乐，酒稻熟，翁媪相将。\n何以报公，祝公千岁，多少人家烧夜香。\n凌烟上，更声名凛凛，冠剑堂堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14186, '沁园春', '黄机', '问讯梅梢，小春近也，花应渐开。\n记华堂此日，红牙丝竹，欢声昨夜，翠玉樽。\n雾节童童，金曳曳，人自阆风玄圃来。\n嬉游处，任沧波变陆，劫火成灰。\n行天看取龙媒。\n笑卫霍当年如此哉。\n有笔头文字，何妨挥洒，胸中兵甲，解洗氛埃。\n见说君王，防秋才了，便著芝泥封诏催。\n功名事，付孱颜燕石，突兀云台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14187, '沁园春', '黄机', '日过西窗，客枕梦回，庭空放衙。\n记海棠洞里，泥金宝，酴架下，油壁钿车。\n醉墨题诗，蔷薇露重，满壁飞鸦行整斜。\n争知道，向如今漂泊，望断天涯。\n小桃一半蒸霞。\n更两岸垂杨浑未花。\n便解貂贳酒，消磨春恨，量珠买笑、酬答年华。\n对面青山，招之不至，说与浮云休苦遮。\n山深处，见炊烟又起，知有人家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14188, '沁园春', '黄机', '暑风清微，梅腮渐红，麦须未黄。\n恨牡丹多病，医治费巧，酴易老，点缀无方。\n客里光阴，愁中意绪，想美人兮山水长。\n销凝处，有龙丝坠简，来唤持觞。\n华堂。\n剩贮春光。\n粲一行珠玑时样妆。\n更燕留轻态，词翻古调，莺娇欲啭，曲度新腔。\n玉漏声沈，银潢影泻，酒犹烧心字香。\n归来也，判明虬永日，瑞锦鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14189, '沁园春', '黄机', '问讯仙翁，殷勤为底，来万山中。\n想橘边丹井，鹤寻旧约，松间碧洞，鹿养新茸。\n雾节亭亭，星曳曳，导以浮丘双玉童。\n嬉游处，尽祥烟瑞雨，霁月光风。\n欢声已与天通。\n更日夜郴江流向东。\n定催归有谓，泥香芝检，留行无计，路熟花骢。\n如侍严凝，密陪清燕，吴水欢然相会逢。\n年年里，对春如酒好，酒似春浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14190, '沁园春', '黄机', '人物眇然，落落晓星，如君几何。\n有飘摇长袖，工持月斧，寂寥遗韵，妙鼓云和。\n政事文章，特其馀事，英气横空时浩歌。\n还堪笑，似龙文古鼎，谁复摩挲。\n青丝系马庭柯。\n为小驻寿君金叵罗。\n说一时伟望，齐高岳麓，二年遗爱，拍满湘波。\n世事多端，细凭商略，痛处不须言语多。\n从今去，好经从乌府，躐上銮坡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14191, '沁园春', '黄机', '有美一人，昔在何居，今方见之。\n俨琼缨翠弁，气清芬只，珠幢绛节，光陆离兮。\n吾道非耶，世情复尔，天骥昂藏不受羁。\n还知否，定曲高寡和，才大难施。\n行吟湘水之湄。\n看云卷云舒无定姿。\n想粲然长笑，物皆有用，时哉易失，我亦奚为。\n袖手旁观，何如小试，欲脱囊中失利锥。\n君休叹，正梅花将发，尘满征衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14192, '八声甘州', '黄机', '问讯翁、底事到人间，人间足嬉游。\n向文边书意，诗边著语，□满南州。\n逸韵高情总似，野水荡孤舟。\n所未能忘者，药鼎茶瓯。\n政恐功名相，便扶摇直上，龙尾螭头。\n想尘缘终薄，归去老菟裘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14193, '乳燕飞・贺新郎', '黄机', '击碎珊瑚树。\n为留春、怕春欲去，驶如风雨。\n春不留兮君休问，付与流莺自语。\n但莫赋、绿波南浦。\n世上功名花梢露。\n政何如、一笑翻金缕。\n系白日，莫教暮。\n苍头引马城西路。\n趁池亭、荻芽尚短，梅心未苦。\n小雨欲晴晴不定，漠漠云飞轻絮。\n算行乐、春来几度。\n鞭影不摇鞍小据。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14194, '乳燕飞・贺新郎', '黄机', '兴泼元同宇。\n唤君来、浮君大白，为君起舞。\n满袖斑斑功名泪，百岁风吹急雨。\n愁与恨、凭谁分付。\n醉里狂歌空漫触，且休歌、只倩琵琶诉。\n人不语，弦自语。\n诗成更将君自赋。\n渺楼头、烟迷碧草，云连芳树。\n草树那能知人意，怅望关河梦阻。\n有心事、笺天天许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14195, '乳燕飞・贺新郎', '黄机', '秋意今如许。\n怪征鞍、底事匆匆，翩然难驻。\n斗帐屏围山六曲，怕见琐窗欲暮。\n倩谁伴、梧桐疏雨。\n路入衡阳天一角，更山环、水绕无重数。\n容易□，便难阻。\n相思才信相思苦。\n省疏狂、迷歌酒，把人轻误。\n问取归期何日是，指点庭前幽树。\n定冷蕊、疏花将吐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14196, '摸鱼儿', '黄机', '惜春归、送春惟有，乱红扑蔌如雨。\n乱红也怨春狼藉，得泪痕无数。\n肠断处。\n更唤起、琼鹊催发长亭路。\n征鞍难驻。\n但脉脉含颦，嗔人底事，刚爱逐春去。\n阑干凭，芳草斜阳凝伫。\n愁连满眼堰树。\n不理金钗溜。\n鸾镜一奁香雾。\n花谁主。\n怅□□、玉容寂寞春知否。\n单衣懒御。\n任门外东风，流莺声里，尽日搅飞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14197, '水龙吟', '黄机', '晴江衮衮东流，为谁流得新愁去。\n新愁都在，长亭望际，扁舟行处。\n歌罢翻香，梦回呵酒，别来无据。\n恨荼シ吹尽，樱桃过了，便只恁、成孤负。\n须信情锺易感，数良辰、佳期应误。\n才高自叹，彩云空咏，凌波谩赋。\n团扇尘生，吟笺泪渍，一觞慵举。\n但丁宁双燕，明年还解，寄平安否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14198, '喜迁莺', '黄机', '平湖百亩。\n种满湖莲叶，绕堤杨柳。\n冉冉波光，辉辉烟影，空翠湿沾襟袖。\n静惬邻鸡啼午，暖逼沙鸥眠昼。\n西园路，更红尘不断，蝶酣蜂瘦。\n知否。\n堪画处，野荠芜菁，地铺茵绣。\n桃李阴边，桑麻丛里，斜矗酒帘夸酒。\n竹寺小依山趾，茅店平窥津口。\n春又晚，正香风有客，倚阑搔首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14199, '木兰花慢', '黄机', '叹镜中白发，元不向、酒边栽。\n奈诗习未除，客愁易感，剩要安排。\n浮名任他有命，怕青山、颇怪不归来。\n出屋长松招鹤，绕渠流水行杯。\n浪驱羸马踏江淮。\n幽梦苦相催。\n甚狭路崎，雄心突兀，谁忍徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14200, '木兰花慢', '黄机', '政胡尘满野，问谁与、作坚城。\n有老子行年，平头六十，无限声名。\n向来试陈大略，便群儿、啁哳耳边鸣。\n争识规模先定，破羌终属营平。\n吾心惟有忠城。\n羞媚妩，做逢迎。\n谓干戈锋镝，动关民命，此不宜轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14201, '木兰花慢', '黄机', '问功名何处，算只合、付悠悠。\n怕僮仆揶揄，长年为客，楚尾吴头。\n春来故园渐好，似不应、不醉把春休。\n剩买蒌蒿荻笋，河豚已上渔舟。\n人间太半足闲愁。\n蓑笠梦汀洲。\n向桃杏花边，招邀同社，秉烛来游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14202, '满江红', '黄机', '芽鼓声中，又妆点、千红万绿。\n春试手，银花影粲，雪梅香馥。\n归梦不知家近远，飞帆正挂天西北。\n记年时、歌舞绮罗丛，凭谁续。\n烟水迥，云山簇。\n劳怅望，伤追逐。\n把蛛丝鹊喜，意□占卜。\n月正圆时羞独照，夜偏长处怜孤宿。\n悔从前、轻被利名牵，征尘扑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14203, '满江红', '黄机', '万灶貔貅，便直欲、扫清关洛。\n长淮路、夜亭警燧，晓营吹角。\n绿鬓将军思饮马，黄头奴子惊闻鹤。\n想中原、父老已心知，今非昨。\n狂鲵剪，於菟缚。\n单于命，春冰薄。\n政人人自勇，翘关还槊。\n旗帜倚风飞电影，戈铤射月明霜锷。\n且莫令、榆柳塞门秋，悲摇落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14204, '满江红', '黄机', '云暗山昏，西风撼、一天悲雨。\n隐君问、短墙修竹，故园何处。\n九月江南无雁到，素书封了谁传与。\n待从头、拚却把心宽，还如故。\n吴姬唱，燕姬舞。\n持玉，温琼醑。\n恨人生欢会，一年几许。\n莫上小楼高处望，楼前诘曲来时路。\n便直须、匹马两苍头，东归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14205, '酹江月・念奴娇', '黄机', '春愁几许，似春云蔼蔼，连空无数。\n□□眉尖偏易得，没个因由分付。\n杨柳烟浓，海棠花暗，绿涨墙头路。\n小楼应是，有人和泪凝伫。\n长记宝轴妆成，鸳鸯绣懒，轻笑歌金缕。\n香雪精神依旧否，风月谁怜虚度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14206, '酹江月・念奴娇', '黄机', '东篱成趣，有西风解事，催开丛菊。\n碎摺黄金谁试手，一一清香堪掬。\n露湿凉轻，霞凝寒重，秀发如新沐。\n宫妆匀就，岂知红紫粗俗。\n因念昔日渊明，微官不受，归伴花幽独。\n弹压秋光三径里，浊酒床头初熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14207, '水调歌头', '黄机', '此日足可惜，心事正崔嵬。\n江淮踏遍，经岁相识定谁来。\n每向酒边长叹，更向花边长笑，意虑叵能猜。\n邂逅忽相遇，有客在尘埃。\n脱儒冠，著武弁，太多才。\n笔墨争似，钩戟容易到云台。\n馀子何须转手，便把平生胸臆，勇去莫徘徊。\n事业上金石，人世自叹哀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14208, '水调歌头', '黄机', '金篆锁岩穴，玉斧凿山湫。\n飞泉溅沫无数，六月自生秋。\n夭矫长松千岁，上有泠然天籁，清响眇难收。\n亭屋创新观，客鞅棹还留。\n推名利，付飘瓦，寄虚舟。\n蒸羔酿秫，醅瓮戢戢蚁花浮。\n唤取能歌能舞，乘兴携将高处，杯酌荐球。\n径醉双股直，白眼视庸流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14209, '六州歌头', '黄机', '百年忠愤，无泪洒江。\n曹刘事，埋露草，锁烟榛。\n哭英魂。\n此恨谁知者，时把剑，频看镜，徒自苦，拳破裂，眼眵昏。\n从古时哉去速，鄹人子、反袂伤麟。\n望家山何在，衮衮已缨。\n欲划还生。\n猛堪惊。\n膏肓危病，宁有药，针匕具，献无门。\n荆州启，条旧画，汉将军。\n已不存。\n便合囊封去，苍庾地，尚间关。\n此不用，心漫有，恐无干。\n人世欢哀数耳，天或者、又假人言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14210, '六州歌头', '黄机', '将军何日，去筑受降城。\n三万骑，貔貅虎，戮鲵鲸。\n洗沧溟。\n试上金山望，中原路，平於掌，百年事，心未语，泪先倾。\n若若累累印绶，偏安久、大义谁明。\n倚危栏欲遍，江水亦吞声。\n目断苹汀。\n海门青。\n停杯与问，焉用此，手虽子，积如京。\n波神怒，风浩浩，勃然兴。\n卷龙腥。\n似把渠忠愤，伸恳请，翠华巡。\n呼壮士，挽河汉，荡材枪。\n长算直须先定，如细故、休苦营营。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14211, '永遇乐', '黄机', '别院春深，华堂昼永，嘉宴初启。\n翠玉樽，红牙丝管，睡鸭沈烟里。\n弄晴云态，行空絮影，漠漠似飞如坠。\n最多情，紫绵团就，错落乱星流地。\n史君自有，元龙豪气，唤客且休辞醉。\n蝶困蜂酣，燕娇莺姹，欢意浓如此。\n侃其笑语，止乎礼义，衣佩细纫兰芷。\n遥归去，残更欲尽，晓鸦又起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14212, '传言玉女', '黄机', '日薄风柔，池面欲平还皱。\n纹楸玉子，磔磔敲春昼。\n衾绣半卷，花气浓薰香兽。\n小团初试，辘轳银。\n梦断阳台，甚情怀、似病酒。\n风奁羞对，比年时更瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14213, '清平乐', '黄机', '西园啼鸟。\n留得春多少。\n客里情怀无日好。\n愁损连天芳草。\n博山灰冷香残。\n微风吹满银笺。\n卓午花阴不动，一双蝴蝶团。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14214, '清平乐', '黄机', '晓窗晴日。\n一点黄金橘。\n万事如毛随日出。\n多少人间头白。\n未春长恨春迟。\n春来生怕春归。\n办取揭天箫鼓，莫教孤负荼シ。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14215, '清平乐', '黄机', '烟融雨腻。\n春去三之二。\n了却兰亭修禊事。\n判与仙翁一醉。\n方壶日月偏长。\n清容花草吹香。\n办取此身强健，功名饱看诸郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14216, '眼儿媚', '黄机', '粉墙朱阁映垂杨。\n晴绿小池塘。\n东风暖，单衣初试，昼日偏长。\n两鬓飞云影，钿合未梳妆。\n阑干侧畔，闲抛荔子，惊散鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14217, '眼儿媚', '黄机', '东风挟雨苦无端。\n恻恻送轻寒。\n那堪更向，湘湾六六，浅处留船。\n诗阄酒戏成孤负，春事已阑珊。\n离愁都在，落花枝上，杜宇声边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14218, '眼儿媚', '黄机', '莫嗔日日话思归。\n归也却便宜。\n东邻招茗，西邻唤酒，一笑开眉。\n人生万事无缘足，待足是何时。\n妻能纺绩，儿能耕获，未必寒饥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14219, '谒金门', '黄机', '风又雨。\n墙外落红无数。\n人不归来春不住。\n佳期还已误。\n细细一团愁绪，薄疏狂何处。\n化作青鸾飞得去。\n问天天亦许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14220, '谒金门', '黄机', '风雨後。\n枝上绿肥红瘦。\n乐事参差团不就。\n一春如病酒。\n楼外暖烟杨柳。\n忆得年时携手。\n燕子双双来未久。\n颇知人意否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14221, '谒金门', '黄机', '愁万叠。\n春在雨条烟叶。\n翠袖倚风寒霎霎。\n傍阑看乳鸭。\n何处一声啼。\n架上荼シ欲雪。\n绣被薰香香未歇。\n可怜音信绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14222, '谒金门', '黄机', '冬十月。\n记取生申时节。\n梅傍小春融绛雪。\n浅寒犹未却。\n且醉笙歌蕉叶。\n富贵不须频说。\n国太夫人头半白。\n看君金印烨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14223, '霜天晓角', '黄机', '玉粲冰寒。\n月痕侵画栏。\n客里安愁无地，为徙倚、到更残。\n问花花不言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14224, '霜天晓角', '黄机', '寒江夜宿。\n长啸江之曲。\n水底鱼龙惊动，风卷地、浪翻屋。\n诗情吟未足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14225, '霜天晓角', '黄机', '长江千里。\n中有英雄泪。\n却笑英雄自苦，兴亡事、类如此。\n浪高风又起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14226, '霜天晓角', '黄机', '江涵落日。\n风转飞帆急。\n问讯蛾眉好在，无一语、送行客。\n闲情眠未得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14227, '夜行船', '黄机', '红溅罗裙三月二。\n露桃开、柳眠又起。\n百尺游丝，莺留燕，判与南园一醉。\n历历斜阳明野水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14228, '长相思', '黄机', '东梁山。\n西梁山。\n占断长江相对闲。\n古今双鬓斑。\n天漫漫。\n水漫漫。\n人事如潮多往还。\n浅颦深恨间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14229, '乌夜啼', '黄机', '云容晓色相涵。\n趣征骖。\n碎点遥山如豆、是淮南。\n路渐远。\n家渐远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14230, '祝英台近', '黄机', '试单衣，扶短策，沙路净如洗。\n乍雨还晴，花柳自多丽。\n争知话别南楼，片帆天际，便孤了、同心连理。\n镇萦系。\n谩有罗带香囊，殷红斗轻翠。\n一纸浓愁，无处倩双鲤。\n可堪飞梦悠悠，春风无赖，时吹过、乱莺声里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14231, '鹊桥仙', '黄机', '黄花似钿，芙蓉如面，秋事凄然向晚。\n风流从古记登高，又处处、悲丝急管。\n有愁万斛，有才八斗，慷慨时惊俗眼。\n明年一笑复谁同，料天远、争如人远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14232, '西江月', '黄机', '漠漠波浮云影，遥遥天接山痕。\n一声渔唱起苹汀。\n名利缘渠唤醒。\n短棹拟携西子，长吟时吊湘灵。\n白鸥容我作同盟。\n占取两湖清影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14233, '西江月', '黄机', '拈翠低垂嫩萼，匀红倒簇繁英。\n纤消得比佳人。\n酒入香肌成晕。\n帘幕阴阴窗牖，阑干曲曲池亭。\n枝头不起梦春酲。\n莫遣流莺唤醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14234, '忆秦娥', '黄机', '秋萧索。\n梧桐落尽西风恶。\n西风恶。\n数声新雁，数声残角。\n离愁不管人飘泊。\n年年孤负黄花约。\n黄花约。\n几重庭院，几重帘幕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14235, '定风波', '黄机', '短策飘飘胜著鞭。\n携壶与客洗愁颜。\n兴到为君拚剧饮。\n狂甚。\n论诗说剑口澜翻。\n画烛烧残花影褪。\n长鲸要使百川乾。\n醉处不知谁氏子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14236, '虞美人', '黄机', '三年万里黄尘路。\n只欠江湖去。\n扁舟二月下湘湾。\n过了洞庭青草、又春残。\n□□□□□□□。\n□□□□□。\n□□□□□□□。\n□□□□□□、□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14237, '踏莎行', '黄机', '云树参差，烟芜平远。\n沙头只欠飞来雁。\n西风方做一分秋，凄凉已觉难消遣。\n窗底灯寒，帐前香暖。\n回肠偏学车轮转。\n剩衾闲枕自无眠，谯门更著梅花怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14238, '蝶恋花', '黄机', '碧树凉惊画扇。\n窗户齐开，秋意参差满。\n先自离愁裁不断。\n蛩更作声声怨。\n山绕千重溪百转。\n隔了溪山，梦也无由见。\n归计凭谁占近远。\n银缸昨夜花如糁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14239, '好事近', '黄机', '鸿雁几时来，目断暮山凝碧。\n别後故园无恙，定芙蓉堪折。\n休文多病废吟诗，有酒怕浮白。\n不是孤他诗酒，更孤他风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14240, '小重山', '黄机', '梧竹因依山尽头。\n潇潇疏雨後，几分秋。\n轻凉无数入西楼。\n凭栏久，满眼动离愁。\n飞鹭下汀洲。\n怕知鸿雁到，带书否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14241, '丑奴儿・采桑子', '黄机', '绿阴窗几明如拭，粉黛初匀。\n无限芳心。\n翻动牙签却人。\n多娇爱学秋来曲，微颤朱唇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14242, '更漏子', '黄机', '秋点长，秋梦短。\n怕见黄昏庭院。\n风，雨萧骚。\n倚窗魂欲销。\n候蛛丝，占鹊喜。\n依旧浓愁一纸。\n红袖，翠钿蔫。\n泪痕犹未乾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14243, '减字木兰花', '黄机', '西风淅淅。\n满眼芙蓉红欲滴。\n无限相思。\n百叠青山百曲溪。\n凭谁说与。\n依带别来宽几许。\n好片心肠。\n不道秋来早晚凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14244, '临江仙', '黄机', '上已清明都过了，客愁惟有心知。\n子规昨夜忽催归。\n驿程那复记，魂梦已先飞。\n回首故园花与柳，枝枝叶叶相思。\n归来拚得典春衣。\n绿阴幽远处，不管尽情啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14245, '临江仙', '黄机', '凤翥鸾飞空燕子，宝香犹惹流苏。\n旧欢凄断数行书。\n终山方种玉，合浦忽还珠。\n午枕梦圆春寂寂，依然刻雪肌肤。\n觉来烟雨满平芜。\n客情殊索莫，肯唤一尊无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14246, '南乡子', '黄机', '帘幕深沈。\n灯暗香销夜正深。\n花落画檐鸣细雨，岑岑。\n滴破相思万里心。\n晓色未平分。\n翠被寒生不自禁。\n待得梦成翻恶况，堪颦。\n飞雁新来也误人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14247, '鹧鸪天', '黄机', '细听楼头漏箭移。\n客床寒枕不胜。\n凄凉夜角偏多恨，吹到梅花第几枝。\n人间阔，雁参差。\n相思惟有梦相知。\n谢他窗外芭蕉雨，叶叶声声伴别离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14248, '鹧鸪天', '黄机', '柳际梅边腊雪乾。\n钗头蝴蝶又成团。\n飘零萍梗江湖客，冷落笙箫灯火天。\n浇浊酒，惜流年。\n牙旗夜市几时穿。\n太平乐事终须在，老去心情恐不然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14249, '鹧鸪天', '黄机', '济楚偏宜淡薄妆。\n冰涵清润玉生香。\n祗因梦峡成云雨，便拟吹箫跨凤皇。\n新间阻，旧思量。\n多情翻不似垂杨。\n年年才到春三月，百计飞花入洞房。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14250, '菩萨蛮', '黄机', '池落开遍莲房老。\n秋声已入梧桐表。\n葵扇与桃笙。\n尚宜相带行。\n危亭三百尺。\n爽气真堪挹。\n瀹茗且盘旋。\n翩翩吾欲仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14251, '菩萨蛮', '黄机', '相思绕遍天涯路。\n相思不识行人处。\n多病怕逢春。\n那堪春正深。\n日高梳洗懒。\n鸾镜香尘掩。\n双鬓绿。\n一帘花信风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14252, '菩萨蛮', '黄机', '惜山不厌山行远。\n山中禽鸟频惊见。\n小雨似怜春。\n霏霏容易晴。\n青裙田舍妇。\n饷前村去。\n溪水想平腰。\n唤船依断桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14253, '浣溪沙', '黄机', '绿锁窗前双凤奁。\n调朱匀粉玉纤纤。\n妆成谁解尽情看。\n柳转光风丝袅娜，花明晴日锦斓斑。\n一春心事在眉尖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14254, '浣溪沙', '黄机', '绿绮空弹恨未平。\n可堪执手送行人。\n碧酒谩将珍重意，莫辞斟。\n我定忆君吟渭北，君须思我赋停云。\n未信高山流水曲，断知音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14255, '浣溪沙', '黄机', '流转春光又一年。\n春愁尽日两眉尖。\n草草幽欢能几许，已天边。\n会得音书生羽翼，免教魂梦役关山。\n帘卷落花千万点，雨如烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14256, '浣溪沙', '黄机', '日转雕栏午漏分。\n井梧落尽小窗明。\n宝床丝索懒关心。\n愁压春山应脉脉，困凝秋水想沈沈。\n低头时露一湾金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14257, '浣溪沙', '黄机', '墨绿衫儿窄窄裁。\n翠荷斜领云堆。\n几时踪迹下阳台。\n歌罢樱桃和露小，舞馀杨柳趁风回。\n唤人休诉十分杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14258, '浣溪沙', '黄机', '著破春衫走路尘。\n子规啼断不禁闻。\n功名似我却羞人。\n象板且须歌皓齿，袅蹄何苦惜黄金。\n尊前休负此生身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14259, '卜算子', '黄机', '忆自别郎时，数到郎归日。\n及至郎归郎又行，泪脸香红湿。\n残梦怕寻思，绣慵收拾。\n夏簟青青白昼长，背倚阑干立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14260, '醉蓬莱', '黄机', '政槐云浓翠，榴火殷红，暑风凉细。\n紫府神仙，向人间游戏。\n瑞节珠幢，琼缨宝佩，炯冰壶标致。\n经济规模，登庸衣钵，家传如此。\n礼乐醇儒，诗书元帅，尽洗凡踪，平吞馀子。\n敬简堂深，且从容一醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14261, '醉落魄・一斛珠', '黄机', '初藕花发。\n薰风庭院凉成霎。\n碧纱金缕笼香雪。\n记得年时，心事凭栏说。\n如今陡顿音书绝。\n夜窗羞见团团月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14262, '虞美人', '黄机', '十年不作湖湘客。\n亭堠催行色。\n浅山荒草记当时。\n竹篱边羸马、向人嘶。\n书生万字平戎策。\n苦泪风前滴。\n莫辞衫袖障征尘。\n自苦英雄之楚、又之秦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14263, '虞美人', '黄机', '云情雨意才端的。\n津鼓催行色。\n因缘虽浅是因缘。\n犹胜当初无分、小留连。\n刘郎双鬓青堪照。\n君也方年少。\n尊前不用苦沾衣。\n未信桃源别後、路成迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14264, '清平乐', '黄机', '钗头蝴蝶。\n趁舞梅边雪。\n酒泻黄光夺月。\n岁岁年年蕉叶。\n边城莺唤春归。\n沙场马到秋肥。\n□□熊韬虎略，换渠金甲牙旗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14265, '清平乐', '黄机', '风韶烟腻。\n春事三之二。\n说与人生行乐耳。\n富贵古来如此。\n西园已有心期。\n姚黄魏紫开时。\n纤指金荷潋滟，香唇银竹参差。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14266, '江城子', '黄机', '醉来玉树倚风前。\n举吟鞭。\n指青帘。\n乌帽低昂，摇兀似乘船。\n傍路谁家妆束巧，斜映日，半窥帘。\n寻欢端合趁芳年。\n对弦。\n且陶然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14267, '鹊桥仙', '黄机', '松梢擎雪，竹枝溥露，炯炯照人清韵。\n仙家谱系合长生，元不藉、药炉丹井。\n凌云壮志，垂天健翮，九万扶摇路稳。\n发闻政最有公车，定飞下、日边音信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14268, '鹊桥仙', '黄机', '一番雨过，江头绿涨，催唤扁舟解去。\n重来言语是相宽，怎得似、而今且住。\n阳关声断，同心未绾，簌簌泪珠无数。\n秋鸿春燕往还时，莫忘了、锦笺分付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14269, '鹊桥仙', '黄机', '薄情也见，多情也见，不似这番著相。\n如何容易买归舟，报南浦、桃花绿涨。\n随君无计，留君无计，赢得泪珠两行。\n夕阳明处一回头，有人在、高楼凝望。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14270, '诉衷情', '黄机', '子规声老又残春。\n犹作未归人。\n天意不能怜客，何事苦教贫。\n归去也，莫逡巡。\n好从今。\n秧田车水，麦陇腰镰，总是关心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14271, '临江仙', '黄机', '寒食清明都过了，客中无计留春。\n东风吹雨更愁人。\n系船芳草岸，始信是官身。\n怅望故园烟水阔，几时匹马。\n别肠何止似车轮。\n天天不管，转作两眉颦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14272, '朝中措', '黄机', '驳云行雨苦无多。\n晴也快如梭。\n春思正难拘束，客愁谁为销磨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14273, '朝中措', '黄机', '逢逢船鼓绿杨津。\n彼此是行人。\n先自离愁无数，那堪病酒伤春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14274, '柳梢青', '黄机', '征路迢迢，征旗猎猎，征袖徘徊。\n扑簌珠泪，怕闻别语，慵举离杯。\n春风花柳齐开。\n只唤做、愁端恨媒。\n一片衷肠，十分好事，等待回来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14275, '丑奴儿・采桑子', '黄机', '绮窗拨断琵琶索，一一相思。\n一一相思。\n无限柔情说似谁。\n银钩欲写回文曲，泪满乌丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14276, '满庭芳', '黄机', '二十年间，旧游踪迹，梦飞岳麓湘湾。\n征衫再理，秋老菊花天。\n为客问君何好，爱水光、山色争妍。\n经行处，旗亭酤酒，曾记屋东偏。\n噫其，吾甚矣，不渐蹇拙，欲斗婵娟。\n办轻舆短艇，强载衰颜。\n人道郴阳无雁，奈情锺、藕断丝联。\n须相忆，新诗赋就，时复寄吴笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14277, '清平乐', '黄机', '西风猎猎。\n又是登高节。\n一片情怀无处说。\n秋满江头红叶。\n谁怜鬓影凄凉。\n新来更点吴霜。\n孤负萸囊菊盏，年年客里重阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14278, '谒金门', '黄机', '秋向晚。\n秋晚蕙根犹暖。\n碧染罗裙湘水浅。\n羞红微到脸。\n绣帘围遍。\n月薄霜明庭院。\n妆罢宝奁慵不掩。\n无风香自满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14279, '木兰花慢', '黄机', 'づ文王前子，自不与、世人同。\n况地望既华，天资更伟，云骥行空。\n年少才名蜚动，泛星槎、曾到广寒宫。\n桂子香浓秋月，桃花浪暖春风。\n神仙之说朦胧。\n铅与汞、亦何功。\n政磐石规模，维城事业，倚重周宗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14280, '满江红', '严羽', '日近觚棱，秋渐满、蓬莱双阙。\n正钱塘江上，潮头如雪。\n把酒送君天上去，琼裾玉佩鸿列。\n丈夫儿、富贵等浮云，看名节。\n天下事，吾能说。\n今老矣，空凝绝。\n对西风慷慨，唾壶歌缺。\n不洒世间儿女泪，难堪亲友中年别。\n问相思、他日镜中看，萧萧发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14281, '沁园春', '严羽', '问讯溪庄，景如之何，吾为平章。\n自月湖不见，江山零落，骊塘去後，烟月凄凉。\n有老先生，如梅峰者，健笔纵横为发扬。\n还添得，石屏诗句，一段风光。\n主人雅兴徜徉。\n每携客临流泛羽觞。\n想归来松菊，小烦管领，同盟鸥鹭，未许相忘。\n我道其间，如斯人物，只合盛之白玉堂。\n还须把，扁舟借我，散发沧浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14282, '贺新郎', '严仁', '兰芷湘东国。\n正愁予、一江红叶，水程孤驿。\n欲写潇湘无限意，那得如椽彩笔。\n但满眼、西风萧瑟。\n我所思兮何处所，在镡津、津上沧湾侧。\n谁氏子，阆风客。\n阆风仙客才无敌。\n赋悲秋、抑扬顿挫，流篱沈郁。\n百赋千诗朝复暮，解道波涛春力。\n忆共尔、乘槎吹笛。\n八表神游吾梦见，渺洞庭、青草烟波隔。\n空怅望，楚天碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14283, '贺新郎', '严仁', '碧浪摇春渚。\n浸虚檐、蒲萄漾，翠绡掀舞。\n委曲经过台下路，载取落花东去。\n问花亦、漂流良苦。\n花不能言应有恨，恨十分、都被春风误。\n同此恨，有飞絮。\n人生聚散元无据。\n尽凭阑、一尊相对，苹州春暮。\n嫉色冲冲空怅望，泪尽世间儿女。\n君不见、千金求赋。\n飞燕婕妤今何在，看黏云、江影伤千古。\n流不去，断魂处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14284, '贺新郎', '严仁', '说到城南杜。\n尽风流、至今人号，去天尺五。\n家世联翩苍玉佩，自有文章机杼。\n看鸾凤、九霄轩翥。\n文阵堂堂新得隽，正少年、壮气虹霓吐。\n拈彩笔，月城去。\n出关相送梅千树。\n雪连空、马蹄特特，晓寒人度。\n帝里春浓花似海，催入明光奏赋。\n须快展、亨衢阔步。\n随世功名真漫浪，要平生、所学期无负。\n须记得，别时语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14285, '归朝欢', '严仁', '五月人间挥汗雨。\n离恨一襟何处去。\n双溪楼下碧千寻，双溪楼上匏尊举。\n晚凉生绿树。\n渔灯几点依洲渚。\n莫狂歌，潭空月净，惨惨瘦蛟舞。\n变化往来无定所。\n求剑刻舟应笑汝。\n只今谁是晋司空，斗牛奕奕红光吐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14286, '归朝欢', '严仁', '云表金茎珠璀璨。\n当日投怀惊玉燕。\n文章议论压西，风流姓字翔东观。\n紫皇嗟见晚。\n祥麟五色留金殿。\n大江西，铜章墨绶，暂尔烦君绾。\n十二金钗扶玉盏。\n锦瑟随急管。\n兽炉烟动彩云高，秋声拍碎红牙板。\n趣君归翰苑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14287, '归朝欢', '严仁', '朱户绿窗深窈窕。\n闪闪华旗红干小。\n相逢斜柳绊轻舟，渚香不断苹花老。\n西风吹梦草。\n题诗未了还惊觉。\n独伤心，凄凉故馆，月过西楼悄。\n楼外斜河低浸斗。\n夜已如何夜将晓。\n心期欲寄赤鳞鱼，秋云不动秋江渺。\n相思千里道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14288, '水龙吟', '严仁', '翼然新榜高亭，翰林铁画燕公手。\n滁阳盛事，何人重继，湟川太守。\n太守谓谁，文章的派，醉翁贤胃。\n对千峰削翠，双溪注玉，端不减、琅琊秀。\n坐啸清香画戟，听丁丁、滴花晴漏。\n棠阴昼寂，细赓宾客，竹枝杨柳。\n只恐明朝，绨封趣觐，未容借寇。\n尽江山识赏，盐梅事业，焕青毡旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14289, '水龙吟', '严仁', '飚车飞上蓬莱，不须更跨琴高鲤。\n砉然长啸，天风洞，云涛无际。\n我欲乘桴，从兹浮海，约任公子。\n办虹竿千丈，钩五十，亲点对、连鳌饵。\n谁榜佳名空翠。\n紫阳仙、去骑箕尾。\n银钩铁画，龙拿凤翥，留人间世。\n更忆东山，哀筝一曲，洒沾襟泪。\n到而今，幸有高亭遗爱，寓甘棠意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14290, '水龙吟', '严仁', '城头杰观峥嵘，重阑下瞰苍龙脊。\n镂珉盘础，雕檀竦，玲珑金碧。\n华子冈头，麻源谷口，神仙窟宅。\n道至今清夜，月明风冷，常隐隐、闻笙笛。\n翠壁烟霞缥缈，更寒泉、飞空千尺。\n数峰江上，孤舟天际，夕阳红湿。\n抖擞征尘，浩然长啸，跨青鸾翼。\n向凤岗西望，遥酾斗酒，酹文章伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14291, '水调歌头', '严仁', '惨淡望京阙，慷慨梦天山。\n引杯中夜看剑，壮气刷幽燕。\n鼍鼓满天催曙，画角连云啸月，吹断戍瓶烟。\n犀角赤兔马，虎帐绿熊毡。\n仗汉节，伸大义，伐可汗。\n青冥更下斧钺，赤子要君安。\n铁骑千群观猎，宫样十眉环座，听鸣弦。\n莫厌兜鍪冷，归去又貂蝉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14292, '木兰花慢', '严仁', '东风吹雾雨，更吹起、夹衣寒。\n正莽莽丛林，潭潭伐鼓，郁郁焚兰。\n阑干曲、多少意，看青烟如篆绕溪湾。\n桑柘绿阴犹薄，杏桃红雨初翻。\n飞花片片走潺。\n问何日西还。\n叹扰扰人生，纷纷离合，渺渺悲欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14293, '蝶恋花', '严仁', '杰阁青红天半倚。\n万里归舟，更近阑干舣。\n木落山寒凫雁起。\n一声渔笛沧洲尾。\n千古文章黄太史。\n扪虱高风，长照冰壶里。\n何以荐君秋菊蕊。\n癯瓢为酌西江水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14294, '蝶恋花', '严仁', '院静日长花气暖。\n一簇娇红，得见春深浅。\n风送生香来近远。\n笑声只在秋千畔。\n目力未穷肠已断。\n一寸芳心，更逐游丝乱。\n朱户对开帘卷半。\n日斜江上春风晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14295, '鹧鸪天', '严仁', '一径萧条落叶深。\n离肠凄断月明砧。\n征鸿送恨连云起，促织惊秋傍砌吟。\n风悄悄，夜沈沈。\n鸳机坐冷晓霜侵。\n挑成锦字心相向，未必君心似妾心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14296, '鹧鸪天', '严仁', '多病春来事事慵。\n偶因扑蝶到庭中。\n落红万叠花经雨，斜碧千条柳因风。\n深院宇，小帘栊。\n几年离别恰相逢。\n擎觞未饮心先醉，为有春愁似酒浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14297, '鹧鸪天', '严仁', '行尽春山春事空。\n别愁离恨满江东。\n三更鼓润官楼雨，五夜灯残客舍风。\n寒淡淡，晓胧胧。\n黄鸡催断丑时钟。\n紫骝嚼勒金衔响，冲破飞花一道红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14298, '鹧鸪天', '严仁', '一曲危弦断客肠。\n津桥捩转牙樯。\n江心云带蒲帆重，楼上风吹粉泪香。\n瑶草碧，柳芽黄。\n载将离恨过潇湘。\n请君看取东流水，方识人间别意长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14299, '鹧鸪天', '严仁', '病去那知春事深。\n流莺唤起惜春心。\n桐舒碧叶悭三寸，柳引金丝可一寻。\n怜绣阁，对云岑。\n苦无多力懒登临。\n翠罗衫底寒犹在，弱骨难支瘦不禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14300, '鹧鸪天', '严仁', '高杏酣酣出短墙。\n垂杨袅袅蘸池塘。\n文鸳藉草眠春昼，金鲫吹波弄夕阳。\n闲倚镜，理明妆。\n自翻银叶炷衙香。\n鸣鞭已过青楼曲，不是刘郎定阮郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14301, '鹧鸪天', '严仁', '公子诗成著锦袍。\n王家桃叶旧妖娆。\n檀槽急斜金雁，彩袖翩跹翠翘。\n沈水过，懒重烧。\n十分浓醉十分娇。\n复罗帐里春寒少，只恐香酥拍渐消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14302, '玉楼春', '严仁', '春风只在园西畔。\n荠菜花繁胡蝶乱。\n冰池晴绿照还空，香径落红吹已断。\n意长翻恨游丝短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14303, '阮郎归', '严仁', '鳃花轻拂紫绵香。\n琼杯初暖妆。\n贪凭雕槛看鸳鸯。\n无心上绣床。\n风絮乱。\n恣轻狂。\n恼人依旧忙。\n梦随残雨下高唐。\n悠悠春梦长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14304, '婆罗门引', '严仁', '花明柳暗，一天春色绕朱楼。\n断鸿声唤人愁。\n欲问归鸿何处，身世自悠悠。\n正东风留滞，楚尾吴头。\n追思旧游。\n叹双鬓、飒惊秋。\n可惜等闲孤了，酒令花筹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14305, '醉桃源・阮郎归', '严仁', '拍堤春水蘸垂杨。\n水流花片香。\n弄花喈柳小鸳鸯。\n一双随一双。\n帘半卷，露新妆。\n春衫是柳黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14306, '好事近', '严仁', '晓色未分明，敲动月边鼍鼓。\n卯酒一杯径醉，又别君南浦。\n春江如席照晴空，大舶夹双橹。\n肠断斜阳渡口，正落红如雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14307, '诉衷情', '严仁', '一声水调解兰舟。\n人间无此愁。\n无情江水东流去，与我泪争流。\n人已远，更回头。\n苦凝眸。\n断魂何处，梅花岸曲，小小红楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14308, '多丽', '严仁', '最无端，官楼画角轻吹。\n一声来、深闺深处，把人好梦惊回。\n许多愁、尽教奴受，些个事、未必君知。\n泪滴兰衾，寒生珠幌，翠云撩乱枕频。\n窗儿上、几条残月，斜玉界罗帷。\n更堪听，霜摧败叶，静扣朱扉。\n念别离、千里万里，问何日是归期。\n关情处、鱼来雁往，断肠是、兔走乌飞。\n美景良辰，赏心乐事，风流孤负缕金衣。\n谩赢得、花颜玉骨，瘦损为相思。\n归须早，刘郎双鬓，莫遣成丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14309, '一落索', '严仁', '清晓莺啼红树。\n又一双飞去。\n日高花气扑人来，独自价、伤春无绪。\n别後暗宽金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14310, '南柯子・南歌子', '严仁', '柳陌通云径，琼梳启翠楼。\n桃花纸薄渍冰油。\n记得年时诗句、为君留。\n晓绿千层出，春红一半休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14311, '菩萨蛮', '严仁', '征鸿点破空云碧。\n丹霞染出新秋色。\n返照落平洲。\n半江红锦流。\n风清渔笛晚。\n寸寸愁肠断。\n寄语笛休横。\n只消三两声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14312, '沁园春', '严参', '曰归去来，归去来兮，吾将安归。\n但有东篱菊，有西园桂，有南溪月，有北山薇。\n蜂则有房，鱼还有穴，蚁有楼台兽有依。\n吾应有、云中旧隐，竹里柴扉。\n人间征路熹微。\n看处处丹枫白露。\n况寒原衰草，牛羊来下，淡烟秋水，鲈鳜初肥。\n自笑平生，颓然骨相，只合持竿坐钓矶。\n都休也，对西风无语，落日斜晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14313, '沁园春', '严参', '竹焉美哉，爱竹者谁，曰君子欤。\n向佳山水处，筑宫一亩，好风烟里，种玉千馀。\n朝引轻霏，夕延凉月，此外尘埃一点无。\n须知道，有乐其乐者，吾爱吾庐。\n竹之清也何如。\n应料得诗人清矣乎。\n况满庭秀色，对拈彩笔，半窗凉影，伴读残书。\n休说龙吟，莫言凤啸，且道高标谁胜渠。\n君试看，正绕坡云气，似渭川图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14314, '疏帘淡月・桂枝香', '张辑', '梧桐雨细。\n渐滴作秋声，被风惊碎。\n润逼衣篝，线袅蕙炉沈水。\n悠悠岁月天涯醉。\n一分秋、一分憔悴。\n紫箫吟断，素笺恨切，夜寒鸿起。\n又何苦、凄凉客里。\n负草堂春绿，竹溪空翠。\n落叶西风，吹老几番尘世。\n从前谙尽江湖味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14315, '貂裘换酒・贺新郎', '张辑', '笛唤春风起。\n向湖边、腊前折柳，问君何意。\n孤负梅花立晴昼，一舸凄凉雪底。\n但小阁、琴棋而已。\n佳客清朝留不住，为康庐、只在家窗里。\n湓浦去，两程耳。\n草堂旧日谈经地。\n更从容、南山北水，庾楼重倚。\n万卷心胸几今古，牛斗多年紫气。\n正江上、风寒如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14316, '淮甸春・念奴娇', '张辑', '短髯怀古，更文游台上，秋生吟兴。\n闻说坡仙来把酒，月底频留清影。\n极目平芜，孤城四水，画角西风劲。\n曲阑犹在，十分心事谁领。\n词卷空落人间，黄楼何处，回首愁深省。\n斜照寒鸦知几度，梦想当年名胜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14317, '如此江山・齐天乐', '张辑', '西风扬子江头路。\n扁舟雨晴呼渡。\n岸隔瓜洲，津横蒜石，摇尽波声千古。\n诗仙一去。\n但对峙金焦，断矶青树。\n欲下斜阳，长淮渺渺正愁予。\n中流笑与客语。\n把貂裘为浣，半生尘土。\n品水烹茶，看碑忆鹤，恍似旧曾游处。\n聊凭陆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14318, '钓船笛・好事近', '张辑', '载酒岳阳楼，秋入洞庭深碧。\n极目水天无际，正白苹风急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14319, '广寒秋・鹊桥仙', '张辑', '杯行将半，月来犹未，潇洒水亭无暑。\n清宵数客一阑秋，对冰雪、荷花似语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14320, '月当窗・霜天晓角', '张辑', '看朱成碧。\n曾醉梅花侧。\n相遇匆匆相别，又争似、不相识。\n南北。\n千里隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14321, '山渐青・长相思', '张辑', '山无情。\n水无情。\n杨柳飞花春雨晴。\n征衫长短亭。\n拟行行。\n重行行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14322, '碧云深・忆秦娥', '张辑', '风凄凄。\n井阑络纬惊秋啼。\n惊秋啼。\n凉侵好梦，月正楼西。\n卷帘望月知心谁。\n关河空隔长相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14323, '南浦月・点绛唇', '张辑', '来翦莼丝，江头一阵鸣蓑雨。\n孤篷归路。\n吹得苹花暮。\n短发萧萧，笑与沙鸥语。\n休归去。\n玉龙嘶处。\n邀月过南浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14324, '沙头雨・点绛唇', '张辑', '带醉归时，月华犹在吹箫处。\n晚愁情绪。\n忘却匆匆语。\n客里风霜，诗鬓空如许。\n江南去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14325, '花自落・谒金门', '张辑', '春寂寞。\n帘底蕙炉烟薄。\n听尽归鸿书怎托。\n相思天一角。\n象笔鸾笺闲却。\n秀句与谁商略。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14326, '垂杨碧・谒金门', '张辑', '花半湿。\n睡起一窗晴色。\n千里江南真咫尺。\n醉中归梦直。\n前度兰舟送客。\n双鲤沈沈消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14327, '阑干万里心・忆王孙', '张辑', '小楼柳色未春深。\n湘月牵情入苦吟。\n翠袖风前冷不禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14328, '杏梁燕・解连环', '张辑', '小楼春浅。\n记钓帘看雪，袖沾芳片。\n似不似、柳絮因风，更细与品题，屡呵冰砚。\n宛转吟情，纵真草、凤笺都遍。\n到灯前笑谑，酒祓峭寒，移尽更箭。\n而今柳阴满院。\n知花空雪似，人隔春远。\n叹万事、流水斜阳，谩赢得前诗，醉污团扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14329, '比梅・如梦令', '张辑', '深夜沉沉尊酒。\n酒醒客衾寒透。\n城角挟霜飞，吹得月如清昼。\n。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14330, '月上瓜洲・相见欢', '张辑', '江头又见新秋。\n几多愁。\n塞草连天何处、是神州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14331, '月底修箫谱・祝英台近', '张辑', '客西湖，听夜雨。\n更向别离处。\n小小船窗，香雪照尊俎。\n断肠一曲秋风，行云不语。\n总写入、征鸿无数。\n认眉妩。\n唤醒岩壑风流，丹砂有奇趣。\n羞杀秦郎，淮海谩千古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14332, '一丝风・诉衷情令', '张辑', '卧虹千尺界湖光。\n冷浸月茫茫。\n当日三高何处，渔唱入凄凉。\n人世事，纵轩裳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14333, '忆萝月・清平乐', '张辑', '新凉窗户。\n闲对琴言语。\n弹到无人知得处。\n两袖五湖烟雨。\n坐中斗转参横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14334, '倚秋千・好事近', '张辑', '人在玉屏闲，逗晓柳丝风急。\n帘外杏花微雨，罩春红愁湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14335, '断肠声・南歌子', '张辑', '柳户朝云湿，花窗午篆清。\n东风未放十分晴。\n留恋海棠颜色、过清明。\n垒润栖新燕，笼深锁旧莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14336, '念奴娇', '张辑', '嫩凉生晓，怪今朝湖上，秋风无迹。\n古寺桂香山色外，肠断幽丛金碧。\n骤雨俄来，苍烟不见，苔径孤吟屐。\n系船高柳，晚蝉嘶破愁寂。\n且约携酒高歌，与鸥相好，分坐渔矶石。\n算只藕花知我意，犹把红芳留客。\n楼阁空，管弦清润，一水盈盈隔。\n不如休去，月悬良夜千尺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14337, '祝英台近', '张辑', '竹间棋，池上字。\n风日共清美。\n谁道春深，湘绿涨沙觜。\n更添杨柳无情，恨烟颦雨，却不把、扁舟偷系。\n去千里。\n明日知几重山，後朝几重水。\n对酒相思、争似且留醉。\n奈何琴剑匆匆，而今心事，在月夜、杜鹃声里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14338, '忆秦娥', '张辑', '春寂寂。\n画阑背倚春风立。\n春风立。\n楚山无数，暮天云碧。\n琴心写遍愁何极。\n断肠谁与传消息。\n传消息。\n当年情墨，泪痕犹湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14339, '浣溪沙', '张辑', '夏果初收唤绿华。\n冰盘巧簇映金瓜。\n荷香飞上玉流霞。\n明月长留千岁色，蟠桃多结几番花。\n谁知罗带有丹砂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14340, '霜天晓角', '张辑', '暮天云阔。\n懒泛琴三叠。\n恰有梅花相伴，窗儿上、一枝月。\n忆别。\n恁时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14341, '临江仙', '张辑', '迢递关山身历遍，烟霞胜处曾游。\n九江江畔系孤舟。\n匡庐如画里，南望插天浮。\n瀑布香炉齐五老，层层爽气陵秋。\n何须魂梦觅瀛洲。\n云松终可卜，我与谪仙俦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14342, '洞仙歌', '张辑', '莲舟玉字，得真人亲授。\n圯上家风又还有。\n问因何五马，踏月云台。\n秋色里，却赏烟霞袖手。\n酒边听说剑，歌舞升平，方许君为赤松友。\n任浊世纷纭，海水扬尘，再相见、雪髯依旧。\n且岁岁、中秋後逾旬，更半月东离，菊花重九。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14343, '满江红', '张辑', '醉发吹凉，但拂剑、狂歌而已。\n倩谁问、九霄黄鹤，更曾来未。\n玉女窗深松昼静，研朱重点参同契。\n记前回、赤水得玄珠，骊龙睡。\n空扰扰，人间世。\n除学道，无真是。\n把洪崖肩拍，挹浮丘袂。\n朝驾长风沧岛上，夜骑明月青天际。\n更几时、回首旧山川，三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14344, '东风第一枝', '张辑', '雨蕊方桃，晴梢渐杏，东风娇语弦管。\n爱香帘约馀寒，唤舞袖翻嫩暖。\n红颜清健，旧墨竹、扶疏手段。\n且碧窗、写就黄庭，画楫海山开卷。\n春自好、得花不淡。\n花又好、得春不浅。\n晓莺瑶佩秋生，月蘸翠尊波满。\n长逢花处，笑西母、霜娥偷换。\n要日边、争看貂蝉，彩侍更迎宣劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14345, '瑞鹤仙', '张辑', '柳风双燕语。\n问有谁留人，岸花去橹。\n星辰快平步。\n俯圜扉草色，青青如许。\n儿童拥路。\n玉溪边、当年杜母。\n料从今、指点山川，总是绣衣行处。\n回顾。\n东堂深窈，楚帖长春，竹尊清午。\n红云帝所。\n摇佩玉，更容与。\n把蓬莱一笑，几番清浅，绿野为花作谱。\n向花前、三叠琴心，看苍鹤舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14346, '绮罗香', '张辑', '欲雨凉生，初弦月在，画戟香中清啸。\n旋种芙蕖，深夏木兰芳沼。\n银汉入、天镜搀秋，福星度、雪阑争照。\n又谁写、万幅莼波，一江佳思到鱼鸟。\n吴儿眉语笑里，要见圜扉绿遍，平畴青绕。\n羽扇纶巾，萧洒玉貌长好。\n问千年、庆会风云，正此日、静春花草。\n更弦管、非雾非烟，鹤声帘幕晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14347, '沁园春', '张辑', '东泽先生，谁说能诗，兴到偶然。\n但平生心事，落花啼鸟，多年盟好，白石清泉。\n家近宫亭，眼中庐阜，九叠屏开云锦边。\n出门去，且掀髯大笑，有钓鱼船。\n一丝风里婵娟。\n爱月在沧波上下天。\n更丛书观遍，笔床静昼，篷窗睡起，茶灶疏烟。\n黄鹤来迟，丹砂成未，何日风流葛稚川。\n人间世，听江湖诗友，号我东仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14348, '贺新郎', '张辑', '绿阴凉尊俎。\n映双旌、飞翻新带，日边恩露。\n千里湖山添鲜碧，玉宇光浮眉妩。\n料范老、应难独步。\n君亦胸中兵十万，把甘霖、小小春东楚。\n江上早，一犁雨。\n赤城霞起连天姥。\n有丹经、亲曾密授，八篇奇语。\n道骨仙风骑鲸客，合侍红云帝所。\n且画戟、清香时度。\n散入邦人箫鼓里，恰春留、芍药丛歌舞。\n还更咏，大鹏赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14349, '贺新郎', '张辑', '鹊喜花间晓。\n惜凝香、低将帘卷，海棠开早。\n前度登楼清啸月，吹入春风不老。\n後五日、花朝方到。\n趁舞罗衣花讯暖，拈吟髭、玉勒迎东笑。\n留肯往，春邮小。\n庐峰青里壶天好。\n一千春、棋声昼永，剑光云表。\n绛雪骊珠看丹转，金鼎龙盘虎绕。\n且未可、飞仙蓬岛。\n河洛烟芜眠狐兔，握风雪、办此升平了。\n却共我，拾瑶草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14350, '徵招', '张辑', '飞鸿又作秋空字，凄凄旧游湘浦。\n凉思带愁深，渺苍茫何许。\n岁华知几度。\n奈双鬓、不禁吟苦。\n独倚危楼，叶声摇暮，玉阑无语。\n尺素。\n欲传将，故人远、天涯屡惊回顾。\n心事只琴知，漫闲相尔汝。\n甚时江海去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14351, '木兰花慢', '张辑', '望瀛洲尺五，听海客、诧登临。\n记岛月分秋，天星降夕，神璧精金。\n他年作霖雨手，且明光奏赋寓良箴。\n槐府黑头旧业，芹宫青岁雄襟。\n。\n宝勒向东吟。\n戏彩看而今。\n更袜步黄云，琴弹碧玉，汇泽杯斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14352, '醉蓬莱', '张辑', '记澄湖抱练，画舫参差，闹花时节。\n油壁鸣堤，有障萦屏列。\n燕草香融，鸦条香浅，似渭城烟雪。\n急管斜阳，卫娘葱，带围寒怯。\n苏小闲情，绿杨如织，阑槛东边，好山千叠。\n料得如今，也翠销红歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14353, '好溪山', '张辑', '孤鸿遥下夕阳寒。\n秋清怀抱宽。\n篱根香满菊金团。\n客中邀客看。\n呼浊酒，共清欢。\n五弦随意弹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14354, '山庄劝酒', '张辑', '清吟湘碧。\n马首春风驿。\n闻说西湖梅早，又邀我、能诗客。\n书尺知到日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14355, '临江仙', '张辑', '忆昔风流秋社里，几人冰雪襟期。\n凉风吹散梦参差。\n寒灯多少恨，长笛不堪吹。\n别去化龙潭上水，东来不寄相思。\n白鸥应笑太忘机。\n沙头重载酒，休负桂花枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14356, '琐窗寒', '张辑', '露漏沈沈，洞房灯悄，鹊翻庭树。\n夜凉如水，人倚玉箫何处。\n澹纵横、疏星断河，点衣黄叶飞四五。\n向此时感旧，非关宋玉，悲秋情绪。\n追念章台路。\n共缓辔芳尘，妒花惹絮。\n旧游梦寐，总付相思新句。\n想风流还在匆匆，暗惊鬓底霜几缕。\n凭危栏、立尽归鸿，脆角凝清曙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14357, '画娥眉・忆王孙', '张辑', '清明小院杏花开。\n半启朱扉燕子来。\n晓起梳头对玉台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14358, '琐窗寒', '苏茂一', '云浦苍寒，烟堤幕翠，旧痕新涨。\n春愁十里，冉冉碧丝摇荡。\n记登临、少年思豪，唾壶击玉歌清壮。\n到如今梦里，秋风鸿阵，晚波渔唱。\n惆怅。\n重来处，望画舫天边，辔丝原上。\n山阴秀句，付与一声云响。\n正东湖、谁家柳下，午阴漠漠人荡桨。\n最堪怜、白发周郎，为江山自赏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14359, '点绛唇', '苏茂一', '竹翠藏烟，杏红流水归何处。\n透帘穿户。\n更洒黄昏雨。\n织锦题书，谁寄愁情去。\n浑无绪。\n绿杨千缕。\n不似真眉妩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14360, '祝英台近', '苏茂一', '结垂杨，临广陌，分袂唱阳关。\n稳上征鞍。\n目极万重山。\n归鸿欲到伊行，丁宁须记，写一封、书报平安。\n渐春残。\n是他红褪香收，绡泪点斑斑。\n枕上盟言。\n都做梦中看。\n销魂啼声中，杨花飞处，斜阳下、愁倚阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14361, '谒金门', '史愚', '深院宇。\n寂寂不禁风雨。\n苔迳流钱青莫数。\n银泥蜗篆古。\n满院多应无主。\n却被痴儿拈取。\n穿向柳丝喧笑语。\n买将春色去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14362, '满江红', '赵灌园', '看尽公卿，都输与、云山居士。\n肯掉了、龙章金印，归来闾里。\n云染笔头成五色，山来胸次堆空翠。\n更结庐、近在白鸥边，弄烟水。\n祗恐怕，明天子。\n黄纸唤，先生起。\n教依前插脚，孔鸾丛里。\n岩壑烟沙真作戏，貂蝉衮绣从兹始。\n酌凤凰、池沼九天浆，三千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14363, '兰陵王', '葛长庚', '一溪碧。\n何处桃花流出。\n春光好，寻个□□，小小篮舆漫行适。\n苍苔满白石。\n涧底阴风凛栗。\n疑无路，幽壑琮，峡转山回入林僻。\n千峰呈翠色。\n时亦有声声，樵唱渔笛。\n忽然一树樱桃白。\n又回头一顾，掀髯一笑，诗情酒思正豪逸。\n虎蹄过新迹。\n幂幂。\n雾如织。\n见异草珍禽，问名不识。\n山灵勒驾雨来急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14364, '兰陵王', '葛长庚', '三峰碧。\n缥渺烟光树色。\n高寒处，上有猿啼，鹤唳天风夜萧瑟。\n山形似笔格。\n人道江南第一。\n游紫观，月殿星坛，积翠楼前吹铁笛。\n客来访灵迹。\n闻王郭当年，曾此驻锡。\n二仙为谒浮丘伯。\n从骖鸾去後，云深难觅。\n丹炉灰冷杵声寂。\n依然旧泉石。\n泉石。\n最幽阒。\n更禽静花闲，松茂竹密。\n清都绛阙无消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14365, '兰陵王', '葛长庚', '桃花瘦。\n寒食清明前後。\n新燕子，禁得馀寒，风雨把人苦。\n梅粒今如豆。\n减却春光多少。\n空自有，满树山茶，似语如愁卧晴昼。\n幽人展襟袖。\n惜莺花未老，江山如旧。\n杜鹃声里同携手。\n叹陌上芳草，堤边垂柳。\n一春十病九因酒。\n愁来独搔首。\n豆蔻。\n枝头小。\n应可惜年华，孤负时候。\n九十韶光那得久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14366, '沁园春', '葛长庚', '嫩雨如尘，娇云似织，未肯便晴。\n见海棠花下，飞来双燕，垂杨深处，啼断孤莺。\n绿砌苔香，红桥水暖，笑拈吟髭行复行。\n幽寻懒、就半窗残睡，一枕初醒。\n消凝。\n次第清明。\n渺南北东西草又青。\n念镜中勋业，韶光冉冉，尊前今古，银发星星。\n青鸟无凭，丹霄有约，独倚东风无限情。\n谁知有，这春山万点，杜宇千声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14367, '沁园春', '葛长庚', '暂聚如萍，忽散似云，无可奈何。\n向天涯海角，两行别泪，风前月下，一片离骚。\n啼罢栖乌，望穷芳草，此恨与之谁较多。\n昏黄後，对青灯感慨，白酒悲歌。\n梦中作梦知麽。\n忆往事落花流水呵。\n更凭高□远，沈腰不瘦，怅今怀昔，潘鬓须皤。\n去燕来鸿，寻梅问柳，寸念从他寒暑熬。\n消魂处，但烟光缥渺，山色周遭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14368, '沁园春', '葛长庚', '锦绣文章，圭璋闻望，碧落侍郎。\n昨履声渐近，星辰避次，竹符重剖，湖海生光。\n委羽天空，石桥水冷，每为众生时雨滂。\n君知否，是民心襦库，吏胆冰霜。\n少须召入行。\n也不念无人荷紫囊。\n有本朝曾旦，移春手段，旧家羲献，补月心肠。\n此去三山，却登八座，已准金瓯姓氏香。\n还朝处，双凫作对，五马成行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14369, '沁园春', '葛长庚', '大丈夫儿，冰肝玉胆，砺山带河。\n算此身此世，无过驹隙，一名一利，未值鸿毛。\n相府如潭，侯门似海，那得烟霄尔许高。\n当初我，是乘云御气，几百千遭。\n此生勋业无多。\n也手种梅花三百窠。\n又底曾嗅著，庙堂钟鼎，底曾拈得，帏幄弓刀。\n玉帝遥知，金书何晚，时有鹤鸣於九皋。\n如今且，向风前浪舞，月下高歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14370, '沁园春', '葛长庚', '三径就荒，松菊犹存，归去来兮。\n叹折腰为米，弃家因酒，往之不谏，来者堪追。\n形役奚悲，途迷未远，今是还知悟昨非。\n舟轻扬，问征夫前路，晨色熹微。\n欢迎童稚嘻嘻。\n羡出岫云闲鸟倦飞。\n有南窗寄傲，东皋舒啸，西畴春事，植杖耘耔。\n矫首遐观，壶觞自酌，寻壑临流聊赋诗。\n琴书外，且乐天知命，复用何疑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14371, '沁园春', '葛长庚', '乍雨还晴，似寒而暖，春事已深。\n是妇鸠乳燕，说教鱼跃，豪蜂醉蝶，撩得莺吟。\n斗茗分香，脱禅衣夹，回首清明上已临。\n芳菲处，在梨花金屋，杨柳琼林。\n如今。\n诗酒心襟。\n对好景良辰似有妊。\n念恨如芳草，知他多少，梦和飞絮，何处追寻。\n病酒时光，困人天气，早有秋秧吐嫩针。\n兰亭路，渐流觞曲水，修禊山阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14372, '沁园春', '葛长庚', '吹面无寒，沾衣不湿，岂不快哉。\n正杏花雨嫩，红飞香砌，柳枝风软，绿映芳台。\n燕似谈禅，莺如演史，犹有海棠连夜开。\n清明也，尚阴晴莫准，蜂蝶休猜。\n朝来。\n应问苍苔。\n甚几日都成锦绣堆。\n念四方宾友，不堪渭树，一年春事，已属庭槐。\n宿酒难醒，多情易老，争奈传杯不放杯。\n如何好，看秋千戏剧，蹴鞠恢谐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14373, '沁园春', '葛长庚', '渭水秋深，湓江春老，洞庭一湖。\n问城南古树，如今在否，洛中狂客，还更来无。\n独上君山，渺观岩石，八百里鲸波泛巨区。\n何曾错，有茶中上灶，酒里仙姑。\n终须。\n度了肩吾。\n稽首终南锺大夫。\n自太平寺里，题诗去後，东林沈宅，大醉归欤。\n天上筵多，人间到少，更不向庐山索鳜鱼。\n如何好，好借君黄鹤，上我清都。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14374, '沁园春', '葛长庚', '且说罗浮，自从石洞，水帘以还。\n是向时景泰，初来卓锡，旧家勾漏，曾此修丹。\n药院空存，铁桥如故，上更有朱仙朝斗坛。\n飞云顶，在石桥高处，杳霭之间。\n山前。\n拾得清闲。\n也分我烟霞数亩宽。\n自竹桥人去，青莲馥郁，柴门闭了，绿柳回环。\n白酒初，清风徐至，有桃李时新几盘。\n仙家好，这许多快活，做甚时官。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14375, '沁园春', '葛长庚', '要做神仙，炼丹工夫，亦有何难。\n向雷声震处，一阳来复，玉炉火炽，金鼎烟寒。\n女乘龙，金公跨虎，片晌之间结大还。\n丹田里，有白鸦一个，飞入泥丸。\n河车运入山。\n全不动纤毫过玉关。\n把龟蛇乌兔，生擒活捉，霎时云雨，一点成丹。\n白雪漫天，黄芽满地，服此刀圭永驻颜。\n常温养，使脱胎换骨，身在云端。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14376, '沁园春', '葛长庚', '岁去年来，思量人生，空自沈埋。\n既这回冬至，一阳来复，便须修炼，更莫疑猜。\n好个鼎炉，见成铅汞，片晌工夫结圣胎。\n人身里，三千世界，十二楼台。\n周年造化安排。\n只在这些些真妙哉。\n要先擒日月，後攒星斗，黄庭中畔，化作琼瑰。\n谁会天机，分明说破，恰似江头雪里梅。\n丹成後，做些功行，归去蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14377, '沁园春', '葛长庚', '黄鹤楼前，吹笛之时，先生朗吟。\n想剑光飞过，朝游南岳，墨篮放下，夜醉东邻。\n铛煮山川，粟藏世界，有明月清风知此音。\n呵呵笑，笑酿成白酒，散尽黄金。\n知音。\n自有相寻。\n休踏破葫芦折断琴。\n唱白苹红蓼，庐山日暮，西风黄叶，渭水秋深。\n三入岳阳，再游湓浦，自一去优游直至今。\n桃源路，尽不妨来往，时共登临。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14378, '沁园春', '葛长庚', '客里家山，记踏来时，水曲山崖。\n被滩声喧枕，鸡声破晓，匆匆惊觉，依旧天涯。\n抖擞征衣，寒欺晓袂，回首银河西未斜。\n尘埃债，叹有如此发，空为伊华。\n古来客况堪嗟。\n尽贫也输他□在家。\n料驿舍旁边，月痕白处，暗香微度，应是梅花。\n拣折一枝，路逢南雁，和两字平安寄与他。\n教知道，有长亭短堠，五饭三茶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14379, '水龙吟', '葛长庚', '层峦叠浮空，断崖直下分三井。\n苍苔路古，鹿鸣芝涧，猿号松岭。\n露凤箫，烟迷枸杞，绿深翠冷。\n笑携筇一到，登高眺远，是多少、仙家景。\n长念青春易老，尚区区、枯蓬断梗。\n人间天上，喟然俯仰，只身孤影。\n世事空花，春心泥絮，此回还省。\n向琼台双阙，结间茅屋，坐千峰顶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14380, '水龙吟', '葛长庚', '云屏漫锁空山，寒猿啼断松枝翠。\n芝英安在，术苗已老，徒劳屐齿。\n应记洞中，凤箫锦瑟，镇常歌吹。\n怅苍苔路杳，石门信断，无人问、溪头事。\n回首暝烟无际，但纷纷、落花如泪。\n多情易老，青鸾何处，书成难寄。\n欲问双娥，翠蝉金凤，向谁娇媚。\n想分香旧恨，刘郎去後，一溪流水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14381, '瑞鹤仙', '葛长庚', '残蟾明远照。\n正一番霜讯，四山秋老。\n孤村带清晓。\n有鸣鞭归骑，乱林啼鸟。\n青帘缥缈。\n懒行时，持杯自笑。\n甚年来、破帽凋裘，惯得淡烟荒草。\n多少。\n客愁羁思，雨泊风餐，水边云杪。\n西窗正好。\n疏竹外，粉墙小。\n念归期相近，梦魂无奈，不为罗轻寒悄。\n怕无人、料理黄花，等闲过了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14382, '瑞鹤仙', '葛长庚', '赋情多懒率。\n每醉後疏狂，醒来瓢忽。\n无心恋簪祓。\n漫才高子建，韵欺王勃。\n胸中绝物。\n所容者、诗兵酒卒。\n一两时，调发将来，扫尽闷妖愁孽。\n莫说。\n杀人一万，自损三千，到底。\n悬河口讷。\n非夙世，无灵骨。\n把湖山牌印，莺花权柄，牒过清风朗月。\n且束之、高阁休休，这回更不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14383, '祝英台近', '葛长庚', '月如酥，天似玉，长啸弄孤影。\n十二楼台，昨梦暗寻省。\n自怜露满衣襟，风吹毛发，浑无寐、寒宵漏永。\n捧香鼎。\n翻起一片龙涎，梅花对人冷。\n庭户冰清，何处鹤声警。\n少时烛暗梧窗，烟生苔砌，晓钟动。\n忽然心醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14384, '水调歌头', '葛长庚', '二月一番雨，昨夜一声雷。\n枪旗争展，建溪春色占先魁。\n采取枝头雀舌，带露和烟捣碎，炼作紫金堆。\n碾破香无限，飞起绿尘埃。\n汲新泉，烹活火，试将来。\n放下兔毫瓯子，滋味舌头回。\n唤醒青州从事，战退睡魔百万，梦不到阳台。\n两腋清风起，我欲上蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14385, '菊花新', '葛长庚', '渺渺烟霄风露冷，夜未艾、凉蟾似水。\n海山外、五云散彩，三峰凝翠。\n一鹤横空何缥缈，见殿阁、笙歌拥罗绮。\n笑劳生，空如尺，恋槿花篱。\n於中青鸾唱美。\n丹鹤舞奇。\n有粉娥琼女，齐捧芳卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14386, '菊花新', '葛长庚', '十二楼台，但前回旧迹。\n想琪花似雪，忘了还思。\n朝暮痴痴地。\n只有老天知。\n却自省、玉阶金砌。\n错抛离。\n梧桐声颤，窗外草蛩吟细。\n醉魂觉，又听秋鸿悲呖。\n极目寒空，叹未有紫云梯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14387, '菊花新', '葛长庚', '宝鸭温香，诉丝城寸意。\n记当年事，闷本愁基。\n人间天上，只争得那些儿。\n吃禁持。\n却念九霄风味。\n清晨雁字。\n一句句在天如在纸。\n只得向风前，默默自喈惜。\n业债俱消，还未了、甚时已。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14388, '菊花新', '葛长庚', '念我东皇大帝儿。\n是操觚弄翰之职。\n飞落尘寰，似此度，算应希。\n向这里。\n安能便、策景御气。\n灰头土面、千河水。\n把我如何洗。\n纵便有铢衣，已失眉峰翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14389, '菊花新', '葛长庚', '弱水去蓬莱，四万八千里。\n远漠漠，俯仰天水青无际。\n鸟飞不到船去难，渺无依。\n翦锦字。\n云信待凭鸾翼。\n青芝素瀑，草舍儿、隐隐烟霞里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14390, '菊花新', '葛长庚', '铜壶四水。\n寒生素被。\n夜迢迢，烟月熹微。\n池浸霜荷，槛竹响，井枫飞。\n宝枕潭无梦，念忡忡地。\n形留神往，镇日价、忘食应忘寐。\n省得起，都是天上仙家事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14391, '菊花新', '葛长庚', '有个闷甚处，一向如痴醉。\n独倚住危阑，坐咬无名指。\n金鱼玉雁一从去，绝消息。\n念念怀天帝。\n密与冥契。\n晴霞照水。\n叹细草新蒲寒萋萋。\n对夕照，树色烟光相紫翠。\n花落莺啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14392, '菊花新', '葛长庚', '雪牖风轩度岁。\n时听芭蕉，雨声凄恻。\n情多易感，渐不觉鬓成丝。\n忽又成千古，诮如梦里。\n西山南浦尽秋意。\n一望芦花飞。\n有一点沙鸥，点破松梢翠。\n凄然念起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14393, '菊花新', '葛长庚', '忽水远天长，笑把玉龙嘶。\n一声声，吹断寒云沧波里。\n幽愁暗恨，弄皓月，怨白日。\n问太虚不尚，则成休矣。\n云心鹤性，死也要冲霄，乘风去。\n分自有、终合仙飞。\n感古怀今聊把笔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14394, '菩萨蛮', '葛长庚', '阁山云冷风萧瑟。\n野猿啼罢蟾光白。\n听彻太清弦。\n断肠云水天。\n金陵君此去。\n秋入蒹葭浦。\n兴满即回辕。\n明年二月春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14395, '谒金门', '葛长庚', '春又去。\n愁杀一声杜宇。\n昨夜海棠无□□。\n晓来闻燕语。\n缥缈佳人何处。\n镇日愁肠万缕。\n千里无家归未得，春风知我苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14396, '水调歌头', '葛长庚', '金液还丹诀，无中养就儿。\n别无他术，只要神水入华池。\n采取天真铅汞，片晌自然交媾，一点紫金脂。\n十月周天火，玉鼎产琼芝。\n你休痴，今说破，莫生疑。\n乾坤运用，大都不过坎和离。\n石里缘何怀玉，因甚珠藏蚌腹，借此显天机。\n何况妙中妙，未易与君知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14397, '水调歌头', '葛长庚', '吃了几辛苦，学得这些儿。\n蓬头赤脚，街头巷尾打无为。\n都没蓑衣笠子，多少风烟雨雪，便是活阿鼻。\n一具骷髅骨，忍尽万千饥。\n头不梳，面不洗，且憨痴。\n自家屋里，黄金满地有谁知。\n这里一声惭愧，那里一声调数，满面笑嘻嘻。\n白鹤青云上，记取这般时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14398, '水调歌头', '葛长庚', '有一修行法，不用问师傅。\n教君只是，饥来吃饭困来眠。\n何必移精运气，也莫行功打坐，但去净心田。\n终日无思虑，便是活神仙。\n不憨痴，不狡诈，不风颠。\n随缘饮啄，算来命也付之天。\n万事不由计较，造物主张得好，凡百任天然。\n世味只如此，拚做几千年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14399, '水调歌头', '葛长庚', '一个清闲客，无事挂心头。\n包巾纸袄，单瓢只笠自逍遥。\n只把随身风月，便做自家受用，此外复何求。\n倒指两三载，行过百来州。\n百来州，云渺渺，水悠悠。\n水流云散，於今几度蓼花秋。\n一任乌飞兔走，我亦不知寒暑，万事总休休。\n问我金丹诀，石女跨泥牛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14400, '水调歌头', '葛长庚', '不用寻神水，也莫问华池。\n黄芽白雪，算来总是假名之。\n只这坤牛乾马，便是离龙坎虎，不必更猜疑。\n药物无斤两，火候不须时。\n偃月炉，朱砂鼎，总皆非。\n真铅真汞不炼，之炼要何为。\n自己金公女，渐渐打成一块。\n胎息象婴儿。\n不信张平叔，你更问他谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14401, '水调歌头', '葛长庚', '要做神仙去，工夫譬似闲。\n一阳初动，玉炉起火炼还丹。\n捉住天魂地魄，不与龙腾虎跃，满鼎汞花乾。\n一任河车运，径路入泥丸。\n飞金精，采木液，过三关。\n金木间隔，如何上得玉京山。\n寻得曹溪路脉，便把华池神水，结就紫金团。\n免得饥寒了，天上即人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14402, '水调歌头', '葛长庚', '草涨一湖绿，天ぇ四山青。\n这千年里，几多兴废不容声。\n无分貂金佩玉，不梦歌钟食鼎，何处有车旌。\n便念旌阳剑，枉自染蛟腥。\n生诸葛，少马援，尚云萍。\n醉乡日月，飘然身世付刘伶。\n知道东门黄犬，不似西山白鹭，风月了平生。\n起来忽清啸，惊落夜潭星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14403, '水调歌头', '葛长庚', '杜宇伤春去，蝴蝶喜风清。\n一犁梅雨，前村布谷正催耕。\n天际银蟾映水，谷口锦云横野，柳外乱蝉鸣。\n人在斜阳里，几点晚鸦声。\n采杨梅，摘卢橘，朱樱。\n奉陪诸友，今宵烂饮过三更。\n同入醉中天地，松竹森森翠幄，酣睡绿苔茵。\n起舞弄明月，天籁奏箫笙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14404, '水调歌头', '葛长庚', '一个江湖客，万里水云身。\n鸟啼春去，烟光树色正黄昏。\n洞口寒泉漱石，岭外孤猿啸月，四顾寂无人。\n梦魂归碧落，泪眼看红尘。\n烟，风惨惨，暗消魂。\n南中诸友，而今何处问浮萍。\n青鸟不来松老，黄鹤何之石烂，叹世一伤神。\n回首南柯梦，静对北山云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14405, '水调歌头', '葛长庚', '昔在虚皇府，被谪下人间。\n笑骑白鹤，醉吹铁笛落星湾。\n十二玉楼无梦，三十六天夜静，花雨洒琅。\n瑶台归未得，忍听洞中猿。\n也休休，无情绪，炼金丹。\n从来天上，神仙官府更严难。\n翻忆三千神女，齐唱霓裳一曲，月里舞青鸾。\n此恨凭谁诉，云满武夷山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14406, '水调歌头', '葛长庚', '昔在虚皇府，啸咏紫云中。\n不知何事，误蒙天谪与公同。\n偶到金华洞口，忽见懒翁老子，挺挺众中龙。\n握手归仙隐，谈笑起天风。\n忽相逢，一转瞬，酒杯空。\n几时再会，唱赓词翰倒金锺。\n只恐武夷山里，千古猿啼鹤唳，未便蹑飞虹。\n公欲归仙去，我欲继公踪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14407, '水调歌头', '葛长庚', '误触紫清帝，谪下汉山川。\n既来尘世，奇奇怪怪被人嫌。\n懒去蓬莱三岛，且看江南风月，一住数千年。\n天风自霄汉，吹到剑峰前。\n做些诗，吃些酒，放些颠。\n木精石怪，时时唤作地行仙。\n朝隐四山猿鹤，夜枕一天星斗，纸被裹云眠。\n梦为蝴蝶去，依约在三天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14408, '水调歌头', '葛长庚', '一叶飞何处，天地起西风。\n夜来酒醒，月华千顷浸帘栊。\n塞外宾鸿来也，十里碧莲香满，泽国蓼花红。\n万象正萧爽，秋雨滴梧桐。\n钓台边，人把钓，兴何浓。\n吴江波上，烟寒水冷翦丹枫。\n光景暗中催去，览镜朱颜犹在，回首鹫巢空。\n铁笛一声晓，唤起玉渊龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14409, '水调歌头', '葛长庚', '江上春山远，山下暮云长。\n相留相送，时见双燕语风樯。\n满目飞花万点，回首故人千里，把酒沃愁肠。\n回雁峰前路，烟树正苍苍。\n漏声残，灯焰短，马蹄香。\n浮云飞絮，一身将影向潇湘。\n多少风前月下，逦天涯海角，魂梦亦凄凉。\n又是春将暮，无语对斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14410, '水调歌头', '葛长庚', '两鬓青丝发，双眼黑方瞳。\n人皆道是，昭庆一个老仙翁。\n暂别蓬莱弱水，自把星冠月帔，玉佩舞薰风。\n醉入桃源路，归去不知踪。\n举云，鸣铁笛，抚丝桐。\n满前剑弁森列，稽首捧金锺。\n挺挺松形鹤貌，任待桑田变海，宝鼎粒丹红。\n玉帝下明诏，独骑上瑶空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14411, '满江红', '葛长庚', '忆昔秦时，中秋日、武夷九曲。\n烟寂寂、斜阳数尺，寒鸦枯木。\n三十六峰凝晓翠，一溪流水生秋绿。\n正满林、桂子散天香，飞金粟。\n神仙客，金丹熟。\n玉诏下，云生足。\n岩头新换骨，尚粘红肉。\n夜半月华明似昼，玉皇降辇铺淆。\n笑曾孙、回首幔亭前，空松竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14412, '满江红', '葛长庚', '昨夜娥，游洞府、醉归天阙。\n缘底事、玉簪坠地，水神不说。\n持向水晶宫里去，晓来捧出将饶舌。\n被薰风、吹作满天香，谁分别。\n芳而润，清且洁。\n白似玉，寒於雪。\n想玉皇後苑，应无此物。\n只得赋诗空赏叹，教人不敢轻攀折。\n笑李粗、梅瘦不如他，真奇绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14413, '满江红', '葛长庚', '树色冥，山烟暮、鸟归日落。\n凭阑处、眼空宇宙，心游碧落。\n古往今来天地里，人间那有扬州鹤。\n幸而今、天付与青山，甘寥寞。\n好花木，多岩壑。\n得萧散，耐淡泊。\n把他人比并，我还不错。\n一曲瑶琴知此意，从前心事都忘却。\n况新秋、不饮更何时，何时乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14414, '满江红', '葛长庚', '明日如今，我已是、天涯行客。\n相别後、麻姑山上，齐云亭侧。\n几个黄昏劳怅想，几宵皓月遥思忆。\n与二仙、不但此今生，皆畴昔。\n频到此，欢无极。\n今去也，来无的。\n念浪萍风絮，东西南北。\n七八年中相契密，三千里外来将息。\n怅金丹、未就玉天辽，还凄恻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14415, '满江红', '葛长庚', '钧天高处，元自有、琼楼玉阙。\n又那更、九霞隐映，五云斗绝。\n八面玲珑光不夜，四围晃耀寒如月。\n有广寒、宫殿隐娥，冰壶洁。\n飘飘去，天风冽。\n星河外，花飞雪。\n见三千神女，尊前一阕。\n来到人间浑似梦，未能归去空悲咽。\n问仙都、此去几由旬，归心热。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14416, '满江红', '葛长庚', '豆蔻丁香，待则甚、如今休也。\n争知道、本来面目，风光洒洒。\n底事到头鸾凤侣，不如躲脱鸳鸯社。\n好说与、几个正迷人，休嗟讶。\n纱窗外，梅花下。\n酒醒也，教人怕。\n把翠云翦却，缁衣披挂。\n柳翠已参弥勒了，赵州要勘台山话。\n想而今、心似白芙蕖，无人画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14417, '摸鱼儿', '葛长庚', '问苍江、旧盟鸥鹭。\n年来景物谁主。\n悠悠客鬓知何似，吹满西风尘土。\n浑未悟。\n漫自许。\n功名谈笑侯千户。\n春衫戏舞。\n怕三径都荒，一犁未把，猿鹤笑君误。\n君且住。\n未必心期尽负。\n江山秋事如许。\n月明风静苹花路。\n枕试听鸣橹。\n还又去。\n道唤取。\n陶泓要草归来赋。\n相思最苦。\n是野水连天，渔榔四处，蓑笠占烟雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14418, '摸鱼儿', '葛长庚', '雨肥梅、亭台初夏。\n昙花开向前夜。\n纯阳鹤会先三日，何处神仙降驾。\n知得也。\n□□是、西山彭抗来胎化。\n平生性野。\n自倒指今年，七旬有六，使节半天下。\n焚金兽，毋惜满斟玉。\n儿孙况又潇洒。\n公今骨相如松在，一掬精神堪画。\n於今且。\n□□炼、金丹成了为凭藉。\n归心莲社。\n便做得乃翁，年登八百，未是寿长者。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14419, '摸鱼儿', '葛长庚', '这身儿、从来业障。\n一生空自劳攘。\n生生死死皆如梦，更莫别生妄想。\n没伎俩。\n只管去、天台雁荡寻方广。\n几人不省。\n被妻子萦缠，生涯拘束，甘自归黄壤。\n世间事，一斤两个八两。\n问谁能去俯仰。\n道义重了轻富贵，却笑输回来往。\n休勉强。\n老先生、从来恬淡无妆幌。\n一声长啸，把拄杖横肩，草鞋贴脚，四海平如掌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14420, '摸鱼儿', '葛长庚', '跨飞鸾、醉吹瑶笛，蓬莱知在何处。\n薰风飘散荷花露。\n梦觉已非帝所，忘归路。\n谁知道、人间别有神仙侣。\n身游枢府。\n奈诏入玉楼，猛骑箕尾，四海忆霖雨。\n问王母。\n天上桃红几度。\n蕊宫今是谁主。\n明年甲子从头数，春入鬟云鬓雾。\n如今去。\n是处里、福田都著黄金布。\n庭前玉树。\n看子早生孙，孙还生子，岁岁彩衣舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14421, '洞仙歌', '葛长庚', '南枝漏泄，一点春光别。\n无蝶无蜂正霜雪。\n向竹梢疏处，瘦影横斜，真个是、潇洒冰肌玉骨。\n黄昏人静，踏碎阶前月。\n忍冻相看惜攀折。\n巡檐空索笑，似笑无言，夜悄悄、仙入寒风清冽。\n更那堪、画角恼幽人，又满地落英，愁肠万结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14422, '满庭芳', '葛长庚', '百雉城边，乱花深处，竹间一笑双清。\n天公解事，为我弄阴晴。\n雨过槐阴绿净，女墙外、杨柳丝轻。\n堪嗟惜，诗尤酒，镜里失青春。\n清和，如许在，莺莺燕燕，相与忘情。\n谪仙风度，命代万人英。\n游戏琴棋书画，人间世、别有方瀛。\n後，玄裳效舞，所欠董双成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14423, '瑶台月', '葛长庚', '烟霄凝碧。\n问紫府清都，今夕何夕。\n桐阴下、幽情远，与秋无极。\n念陈迹、虎殿虬宫，记往事、龙箫凤笛。\n露华冷，蟾光白。\n云影净，天籁息。\n知得。\n是蓬莱不远，身无羽翼。\n广寒宫、舞彻霓裳，白玉台、歌罢瑶席。\n争不思下界，有人岑寂。\n羡博望、两泛仙槎，与曼倩、三偷蟠实。\n把丹鼎，暗融液。\n乘云气，醉挥斥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14424, '永遇乐', '葛长庚', '懒散家风，清虚活计，与君说破。\n淡酒三杯，浓茶一碗，静处乾坤大。\n倚藤临水，步登山，白日只随缘过。\n自归来，曲肱隐几，但祗恁和衣卧。\n柴扉草户，包巾纸袄，未必有人似我。\n我醉还歌，我歌且舞，一恁憨痴好。\n绿水青山，清风明月，自有人间仙岛。\n且偎随、补破遮寒，烧火。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14425, '永遇乐', '葛长庚', '银月凄凉，绮霞明灭，秋色如此。\n露满清襟，风生衰鬓，夜已三更矣。\n寻思往事，千头万绪，回首诮如梦里。\n指烟霄，不如归去，不知今夕何夕。\n鹑衣百结，脂垢腻，犹是小蛮针指。\n对酒逢诗，高吟大笑，四海今谁似。\n荷亭竹阁，共风同月，此会今生能几。\n君须记，去来聚散，只□底是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14426, '好事近', '葛长庚', '行到竹林头，探得梅花消息。\n冷蕊疏英如许，更无人知得。\n冰枯雪老岁年徂，俯仰自嗟惜。\n醉卧梅花影里，有何人相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14427, '好事近', '葛长庚', '何事雁来迟，独步秋园默默。\n莫恨桂花开尽，有菊花堪惜。\n回头顾影背斜阳，听西风萧瑟。\n无限诗情酒思，那早梅知得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14428, '桂枝香', '葛长庚', '楼前凝望。\n见水满一溪，云满千嶂。\n将晚欲行无绪，欲眠无况。\n岩花涧草春无极，倚东风、忽然惆怅。\n淡烟飞过，幽禽叫断，远钟嘹亮。\n为底事、沈吟一晌。\n念只影飘浮，寸心虚旷。\n无限游丝落絮，此怀难状。\n江湖淮海行将遍，觉诗肠、酒胆超畅。\n一丘一壑归来，念我旧家天上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14429, '南乡子', '葛长庚', '夜月照千峰。\n影满荷池静袅风。\n明日今宵还感慨，梧桐。\n叶叶随云扬碧空。\n聚散与谁同。\n野鹤孤云有底踪。\n别处要知相忆处，无穷。\n总在青山夕照中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14430, '南乡子', '葛长庚', '前度几相逢。\n此日游从乐不同。\n竹阁荷亭欢聚处，雍容。\n如在蓬莱第一宫。\n夜半月朦胧。\n秉烛东园风露中。\n明日匆匆还入浙，忡忡。\n却把音书寄远鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14431, '霜天晓角', '葛长庚', '五羊安在。\n城市何曾改。\n十万人家圜，东亦海、西亦海。\n年年蒲涧会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14432, '贺新郎', '葛长庚', '且尽杯中酒。\n问平生、湖海心期，更如君否。\n渭树江云多少恨，离合古今非偶。\n更风雨、十常八九。\n长铗歌弹明月堕，对萧萧、客鬓闲携手。\n还怕折，渡头柳。\n小楼夜久微凉透。\n倚危阑、一池倒影，半空星斗。\n此会明年知何处，苹未秋风未久。\n漫输与、鹭朋鸥友。\n已办扁舟松江去，与鲈鱼、莼菜论交旧。\n因念此，重回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14433, '贺新郎', '葛长庚', '梦绕荷花国。\n遍□□、橘州柳市，芙蓉巷陌。\n桂社兰乡白苹里，月冷波寒之夕。\n有孤鹜、落霞知得。\n一鹤横空云漠漠，见梅梢、万粒真珠滴。\n犹未把，寒香惜。\n画楼何处吹瑶笛。\n便□□、酥颦玉笑，露松霜瘠。\n姑射真人游紫府，下戏三江七泽。\n此莫是、冰魂雪魄。\n半逐风飞半随水，半在枝、半落苍苔白。\n酒醒後，晓窗碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14434, '贺新郎', '葛长庚', '是雨还堪拾。\n道非花、又从帘外，受风吹入。\n扑落梅梢穿度竹，恐是鲛人诉泣。\n积至暮、萤光熠熠。\n色映万山迷远近，满空浮、似片应如粒。\n忘炼得，我双睫。\n吟肩耸处飞来急。\n故撩人、粘衣袖，嫩香堪。\n细听疑无伊复有，贪看一行一立。\n见僧舍、茶烟飘湿。\n天女不知维摩事，漫三千、世界缤纷集。\n是翦水、谁能及。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14435, '贺新郎', '葛长庚', '晓雾须收霁。\n牡丹花、如人半醉，抬头不起。\n雪炼作冰冰作水。\n十朵未开三四。\n又加以、风禁雨制。\n□是东吴春色盛，尽移根、换叶分黄紫。\n所贵者，称姚魏。\n其间一种尤姝丽。\n似佳人、素罗裙在，碧罗衫底。\n中有一花边两蕊。\n恰似妆成小字。\n看不足、如何可比。\n白玉杯将青玉绿，据晴香、暖艳还如此。\n微笑道，有些是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14436, '贺新郎', '葛长庚', '飞尽桃花片。\n倚东风、高吟大啸，开怀消遣。\n芍药牡丹开未遍。\n不道韶华如电。\n无心向、小庭幽院。\n秉烛夜游虽不倦，奈一番、风雨花容变。\n春去也，无人见。\n何处莺莺啼不断。\n探後园、红稀翠减，青稠绿满。\n蝶在花间犹死恋。\n早有行人摇扇。\n故自要、与春为饯。\n笑指白云归去好，对夕阳、泻酒凭谁荐。\n柳深处，有双燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14437, '贺新郎', '葛长庚', '谓是无情者。\n又如何、临歧欲别，泪珠如洒。\n此去兰舟双桨急，两岸秋山似画。\n况已是、芙蓉开也。\n小立西风杨柳岸，觉衣单、略说些些话。\n重把我，袖儿把。\n小词做了和愁写。\n送将归、要相思处，月明今夜。\n客里不堪仍送客，平昔交游亦寡。\n况惨惨、苍梧之野。\n未可凄凉休哽咽，更明朝、後日才方罢。\n却默默，斜阳下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14438, '贺新郎', '葛长庚', '风雨今如此。\n问行人、如何有得，许多儿泪。\n为探木犀开也未，只有芙蓉而已。\n九十日、秋光能几。\n千里送人须一别，却思量、我了思量你。\n去则是，住则是。\n归归我亦行行矣。\n便行行、不须回首，也休萦系。\n一似天边双鸣雁，一个飞从东际。\n那一个、又飞西际。\n毕竟人生都是梦，再相逢、除是青霄里。\n却共饮，却共醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14439, '贺新郎', '葛长庚', '露白天如洗。\n淡烟轻、疏林映带，远山横翠。\n对此情怀成甚也，云断小楼风细。\n独倚遍、画阑十二。\n花馆云窗成憔悴。\n听宾鸿、天外声嘹唳。\n但不过，闷而已。\n房栊深静难成寐。\n夜迢迢、银台绛蜡，伴人垂泪。\n巴得暂时朦胧地。\n还又匆匆惊起。\n漫自展、云间锦字。\n往後各收千张纸。\n念梦劳魂役空凝睇。\n终不负，骖鸾志。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14440, '贺新郎', '葛长庚', '醉见千山面。\n晚晴初、蝉声未了，鸟声尤远。\n知道仙人丹灶在，尚有陈灰犹暖。\n但只恐、松枯石烂。\n笑问年华应不换，又如何、洞里笙箫断。\n还念我，去归晚。\n千岩万壑猿啼遍。\n一思量、一回懊恨，一回泪眼。\n岂是自家无仙骨，尚被红尘牵绊。\n要分此、烟霞一半。\n当日朱仙和葛老，更老黄、亦合同萧散。\n上帝近，永容懒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14441, '贺新郎', '葛长庚', '仙鹊梁银汉。\n见青原白鹭一点，秋光犹嫩。\n青鸟密传云外信，王母夜临香案。\n与河鼓、天孙为伴。\n太素真人乘此景，到芗城、即嗣胡忠简。\n南极上，星璀璨。\n松溪居士多词翰。\n是神仙风骨，元自无心仕宦。\n人道月卿临总饷，便合机廷揆馆。\n还又爱、山林萧散。\n玉女金钟萦暖响，指灵椿、仙鹤祈遐算。\n公自有，青精饭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14442, '贺新郎', '葛长庚', '倏又西风起。\n这一年光景，早过三分之二。\n燕去鸿来何日了，多少世间心事。\n待则甚、功成名遂。\n枫叶荻花动凉思，又寻思、江上琵琶泪。\n还感慨，劳梦寐。\n愁来长是朝朝醉。\n划地成、宋玉伤感，三闾憔悴。\n况是凄凉寸心碎。\n目断水苍山翠。\n更送客、长亭分袂。\n阁皂山前梧桐雨，起风樯、露舶无穷意。\n君此去，趁秋霁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14443, '贺新郎', '葛长庚', '一别蓬莱馆。\n看桑田成海，又见松枯石烂。\n目断虚皇无极处，安得殿头宣唤。\n指归路、钧天早晚。\n此去罡风三万里，但九霞、渺渺青云远。\n望不极，空泪眼。\n瑶池昔会群仙宴。\n此秋来、荻花枫叶，令人凄惋。\n满面朱尘那忍见，酒病花愁何限。\n知几度、春莺秋雁。\n从此飞神腾碧落，向清都、来往应无间。\n丹渐熟，骨将换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14444, '贺新郎', '葛长庚', '遥想阳明洞。\n夜深时、猿啼鹤唳，露寒烟重。\n家在神霄归未得，十二玉楼无梦。\n梦里听、瑶琴三弄。\n醉卧长安人不识，晚秋天、此意西风共。\n黄金印，吾何用。\n云衢高策青鸾。\n把天书玉篆，留与世人崇奉。\n垂手入廛长是醉，醉则从教懵懂。\n那些子、凝然不动。\n一剑行空神鬼惧，金粟儿、日向丹田种。\n把得稳，任放纵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14445, '贺新郎', '葛长庚', '万顷湖光绿。\n是处里、芙蓉金盏，木犀金粟。\n御飘飘行水谷，正是蟹香橙熟。\n山色似、风梳雨沐。\n携取阿娇命豪杰，过北山、疃处南山曲。\n寒烟淡，晴鸦浴。\n巨觥数引苍髭矗。\n便论诗说剑，人各有怀西北。\n两见西风客京国，多在红楼金屋。\n凝情处、落霞孤鹜。\n蒲柳凄凉今如许，问功名、志在何时足。\n更簪取，一枝菊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14446, '贺新郎', '葛长庚', '极目神霄路。\n斗柄南、丹华翠景，红霞紫雾。\n手折琪花今似梦，十二楼台何处。\n犹记得、当时伴侣。\n东府西台知谁主，忆当时、自泻金瓶雨。\n人间事，等风絮。\n上皇赫赫雷霆主。\n我何缘、清都绛阙，遽成千古。\n白鹤青乌消息断，梦想鸾歌凤舞。\n应未得、翻身归去。\n业债须教还净尽，这一回、尝遍红尘苦。\n归举似，西王母。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14447, '贺新郎', '葛长庚', '昔在神霄府。\n是上皇娇惜，便自酣歌醉舞。\n来此人间不知岁，仍是酒龙诗虎。\n做弄得、襟情如许。\n俯仰红尘几今古。\n算风灯、泡沫无凭处。\n即有这，烟霄路。\n淮山浙岸潇湘浦。\n一寻思、柳亭枫驿，泪珠溅俎。\n此去何时又相会，离恨萦人如缕。\n更天也、愁人风雨。\n语燕啼莺莫相管，请各家、占取闲亭坞。\n人事尽，天上去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14448, '贺新郎', '葛长庚', '倚剑西湖道。\n望弥漫、苍葭绿苇，翠芜青草。\n华表凄凉市朝古，极目暗伤怀抱。\n秋色与、芰荷俱老。\n桂棹兰舟聊遣兴，仗金风、吹使芙蓉破。\n柳阴里，堪少坐。\n衷肠底事君知那。\n要繁弦急管，又且沈酣则个。\n烟水冥茫黄叶断，嘹唳数声雁过。\n醉归去、山寒云暮。\n整日消闲镇来往，问城南、老树知渠麽。\n黄鹤氅，青纱帽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14449, '贺新郎', '葛长庚', '风送寒蟾影。\n望银河、一轮皎洁，宛如金饼。\n料得故人千里共，使我寸心耿耿。\n浑无奈、天长夜永。\n万树萧森猿啸罢，觉水边、林下非人境。\n睡不著，酒方醒。\n芙蓉池馆梧桐井。\n悄不知、今夕何夕，寒光万顷。\n年少风流多感慨，况此良辰美景。\n须对此、大拼酩酊。\n满目新寒舞黄落，嗟此身、何事如萍梗。\n桂花下，露华冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14450, '贺新郎', '葛长庚', '俯仰天粘水。\n尽□□、山河大地，光涵表里。\n一夜春风搜万象，檐外雨声不已。\n到晓来、六花靡靡。\n瑶树琪林寒彻骨，知谁家、娇女慵梳洗。\n且捏个，小狮子。\n琼楼架就东皇喜。\n□□使、玉龙战罢，柳绵飞起。\n千古佳人诗句在，一任如盐似米。\n君试看、岩头溪底。\n刹刹尘尘银世界，记当年、曾赴瑶池会。\n玉清境，还如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14451, '贺新郎', '葛长庚', '银汉千丝雨。\n被东风作恶，吹落满空柳絮。\n恰自江南消息断，才此六花飞舞。\n最好是、鹅毛鹤羽。\n万顷平田三尺玉，月明中、不见沙头鹭。\n苍烟里，一渔父。\n鹊桥半夜寒云妒。\n到晓来、千岩万壑，了无认处。\n极目四方银世界，五凤楼前如许。\n应自感、伤心凝伫。\n人在神霄玉清府，小狮儿、捏就无佳句。\n骑汗漫，好归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14452, '贺新郎', '葛长庚', '月插青螺髻。\n柳梢头、夕阳荏苒，西风摇曳。\n数粒苍山粘远汉，树色烟光紫翠。\n飞骑气、半醒半醉。\n剑跨秋空磨星斗，指琼童、不得鸣金辔。\n恐惊动，紫清帝。\n浮云飞度蓬莱水。\n忆山中、松寒露冷，猿啼鹤唳。\n家在武夷岩谷里，一亩烟霞活计。\n叹拈指、人生百岁。\n兰畹芝田几今古，洞门前、小鹿衔花戏。\n不知有，人间世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14453, '贺新郎', '葛长庚', '静看春容瘦。\n未清明、荼シ避席，蔷薇出昼。\n花里流莺骂桃李，似与东风管句。\n怕虚度、兰亭时候。\n我也别来天上夕，向年时、感叹湖山旧。\n旧日事，君知否。\n玉皇驾出清都晓。\n就御前、三千神女，指麾八九。\n化作花神下人世，如把粉团搦就。\n又一似、玉盘在手。\n莫是蕊珠亲付属，教小心、劝我杯儿酒。\n也只得，为陪笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14454, '贺新郎', '葛长庚', '极目飙尘表。\n醉酣时、楼中起舞，楼前舒啸。\n坐见四山烟雾散，是处落花啼鸟。\n忽惊下、九天星斗。\n双鹤飞来风露爽，一声声、清唳苍松杪。\n奈对景，不酾酒。\n旧家三点蓬莱小。\n有琼台双阙，长是香花缭绕。\n铁笛夜吹金剑吼，恨此瀛洲路杳。\n知几度、琪林春老。\n闲倚朱阑思昨梦，对江山、感慨无人晓。\n但千里，月华皎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14455, '柳梢青', '葛长庚', '一夜清寒，千红晓粲，春不曾知。\n细看如何，醉时西子，睡底杨妃。\n尽皆蜀种垂丝。\n晴日暖、薰成锦围。\n说与东风，也须爱惜，且莫吹飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14456, '柳梢青', '葛长庚', '鹤使南翔。\n词珍翰绮，谊暖情香。\n如在琼台，梦回初饮，月液云浆。\n风吹芦叶冥茫。\n夕照外、山高水长。\n遥想东楼，琪花玉树，梅影昏黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14457, '柳梢青', '葛长庚', '五马风流，销金帐暖，药玉船宽。\n放下荷囊，携来铜虎，又举熊幡。\n棠阴已接三山。\n此列郡、彼食大藩。\n柳雪萦旗，东风拦马，父老争看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14458, '一剪梅・一翦梅', '葛长庚', '剑倚青天笛倚楼。\n云影悠悠。\n鹤影悠悠。\n好同携手上瀛洲。\n身在阎浮。\n业在阎浮。\n一段红云绿树愁。\n今也休休。\n古也休休。\n夕阳西去水东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14459, '虞美人', '葛长庚', '苹花零乱秋亭暮。\n篱落江村路。\n棹歌摇曳钓船归。\n搅碎清风千顷、碧琉璃。\n山衔初月明疏柳。\n平野垂星斗。\n莫辞沈醉伴孤吟。\n他日江南江北、两关心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14460, '阮郎归', '葛长庚', '淡烟凝翠锁寒芜。\n斜阳挂碧梧。\n沙头三两雁相呼。\n萧萧风卷芦。\n何处笛，一声孤。\n岸边人钓鱼。\n快帆一夜泊桐庐。\n问人沽酒无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14461, '酹江月・念奴娇', '葛长庚', '思量世事，几千般翻覆，是非多少。\n随分随缘天地里，心与江山不老。\n道在天先，神游物外，自有长生宝。\n洞门无锁，悄无一个人到。\n一条柱杖横肩，芒鞋紧峭，正风清月好。\n惊觉百年浑似梦，空被利名萦绕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14462, '酹江月・念奴娇', '葛长庚', '孤村篱落，玉亭亭、为问何其清瘦。\n欲语还愁谁索笑，临水嫣然自照。\n甘受凄凉，不求识赏，风致何高妙。\n松挨竹拶，更堪霜雪。\n争奈终是冰肌，也过了几个，晴昏雨晓。\n冷艳寒香空自惜，後夜山高月小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14463, '酹江月・念奴娇', '葛长庚', '当初误触，紫微君、谪下神霄玉府。\n醉後骑龙吹铁笛，酒醒不知何处。\n绛阙寥寥，红尘扰扰，老泪滂如雨。\n人间天上，桑田沧海如许。\n遥想十二楼前，琪花开已遍，鸾歌鹤舞。\n梦到三天还又落，愁听空中箫鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14464, '酹江月・念奴娇', '葛长庚', '寄言天上，石麒麟、化作人间英物。\n醉拥诗兵驱笔阵，百万词锋退壁。\n世事空花，赏心泥絮，一点红炉雪。\n识时务者，当今惟有俊杰。\n我本浩气天成，才逢知已，便又清狂发。\n富贵於我如浮云，且看云生云灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14465, '酹江月・念奴娇', '葛长庚', '罗浮山下，正秋高气爽，凄凉风物。\n瘦落丹枫飞紫翠，峭拔青山石壁。\n客鬓萧疏，诗肠清苦，病骨如冰雪。\n怒髯铁立，有怀不下三杰。\n袖里宝剑生寒，中宵起舞，引酒清歌发。\n襟曲屡兴猿鹤梦，坐看月痕生灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14466, '酹江月・念奴娇', '葛长庚', '旧家宋玉，是何人、偏到秋来凄惨。\n细雨疏风天气冷，离别令人销黯。\n樯燕飞归，岸花吹送，自是生怀感。\n挑灯酌酒，平生明目张胆。\n二十年在江湖，枫亭柳驿，往事都曾览。\n胸次可吞云梦九，也没尘埃一糁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14467, '酹江月・念奴娇', '葛长庚', '海天秋老，夜凄清、坐对香温金鸭。\n听得寒蝉声断续，一似离歌相答。\n鸿雁初来，骅骝欲去，永夜烧红蜡。\n不须别酒，有时亦呷一呷。\n丈夫南北东西，何天不可，鸣剑雄开匣。\n岂特东湖徐孺子，下得陈蕃之榻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14468, '酹江月・念奴娇', '葛长庚', '道人於世，已忘情、尚更区区饯别。\n栖碧先生辞蕙帐，夜夜猿声凄切。\n剑上星寒，琴中风惨，眉宇飞黄色。\n一杯判袂，出门烟水空阔。\n我今流落江南，朝朝还暮暮，千愁万结。\n那更荻花枫叶景，又见长亭短驿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14469, '酹江月・念奴娇', '葛长庚', '桃花开尽，正溪南溪北，春风春雨。\n寒食清明都过了，愁杀一声杜宇。\n醉跨蹇驴，踏翻芳草，满满斟鹦鹉。\n游仙梦觉，不知身在何处。\n因甚青鸟不来，一年春事，拈指都如许。\n人在白云流水外，多少莺啼燕语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14470, '酹江月・念奴娇', '葛长庚', '汉江北泻，下长淮、洗尽胸中今古。\n楼橹横波征雁远，谁见鱼龙夜舞。\n鹦鹉洲云，凤凰池月，付与沙头鹭。\n功名何处，年年惟见春絮。\n非不豪似周瑜，壮如黄祖，亦随秋风度。\n野草闲花无限数，渺在西山南浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14471, '酹江月・念奴娇', '葛长庚', '绿菏十里吐秋香，湖水掌平如镜。\n日落云收天似洗，况又月明风静。\n露逼葭蒲，烟迷菱芡，缩尽寒鸦颈。\n两枝画桨，柳阴浓处乘兴。\n遥想和靖东坡，当年曾胜赏，一觞一咏。\n是则湖山常不老，前辈风流去尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14472, '促拍满路花', '葛长庚', '多才夸李白，美貌说潘安。\n一朝成万古，又徒闲。\n如何猛省，心地种仙蟠。\n堪叹人间事，泡沫风灯，阿谁肯做飞仙。\n莫思量、骏马与高轩。\n快乐任天然。\n最坚似松柏、更凋残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14473, '行香子', '葛长庚', '满洞苔钱。\n买断风烟。\n笑桃花流落晴川。\n石楼高处，夜夜啼猿。\n看二更云，三更月，四更天。\n细草如毡。\n独枕空拳。\n与山糜、野鹿同眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14474, '八六子', '葛长庚', '倚危亭。\n恨如芳草，萋萋划尽还生。\n念柳外青鸾去後，洞中白鹤归来，恍然暗惊。\n吾家渺在瑶京。\n夜月一帘花影，春风十里松鸣。\n奈昨梦、前尘渐随流水，凤箫歌杳，水长天远，那堪片片飞霞弄晚，丝丝细雨笼晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14475, '汉宫春', '葛长庚', '潇洒江梅，似玉妆珠缀，密蕊疏枝。\n霜风应是，不许蝶近蜂欺。\n嫣然自笑，与山矾、共水仙期。\n还亦有，青松翠竹，同今凛冽年时。\n何事向人如恨，带苍苔，半倚临水荒篱。\n孤山嫩寒放晓，尚忆前诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14476, '卜算子', '葛长庚', '云散雨初晴，蝉噪林逾静。\n古寺敲钟暮掩门，灯映琉璃影。\n浩气镇长存，昨梦还重省。\n独倚阑干啸一声，毛发萧萧冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14477, '卜算子', '葛长庚', '古寺枕空山，楼上昏钟静。\n饥鼠偷灯尾蘸油，悄悄无人影。\n长剑匣中鸣，今古深思省。\n此夕行藏独倚楼，风雨凄凄冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14478, '卜算子', '葛长庚', '渔火海边明，烟锁千山静。\n独坐僧窗夜未央，寂寞孤灯影。\n感慨辄兴怀，往事无人省。\n江汉飘浮二十年，一枕西风冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14479, '鹧鸪天', '葛长庚', '雨过山花向晚香。\n烟丝空翠柳微茫。\n旧家丹灶何人葛，今日帘泉阿姥黄。\n犀角枕，象牙床。\n椰心织簟昼生凉。\n杯行无算何曾醉，不觉罗浮日月长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14480, '鹧鸪天', '葛长庚', '西畔双松百尺长。\n当时亲自见刘王。\n山前今日莲花水，往者将军洗马塘。\n南粤路，汉宫墙。\n晚风历历说兴亡。\n摩挲东晋苍苔灶，细说仙翁炼药方。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14481, '鹧鸪天', '葛长庚', '翠幄张天见未曾。\n驼峰鹅掌出庖烹。\n醉酣浑是迷天地，但见尊前万点星。\n人似玉，酒如饧。\n果盘簇不知名。\n东风吹我三山下，如在神霄上帝庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14482, '蝶恋花', '葛长庚', '冷雨疏风凉漠漠。\n云去云来，万里秋阴薄。\n笑倚玉阑呼白鹤。\n烟笼素月青天角。\n竹影松声浑似昨。\n醉胆如天，谁道词源涸。\n满地苍苔霜叶落。\n今宵不饮何时乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14483, '蝶恋花', '葛长庚', '绿暗红稀春已暮。\n燕子衔泥，飞入谁家去。\n柳絮欲停风不住。\n杜鹃声里山无数。\n白马青衫无定据。\n好底林泉，信脚随缘寓。\n拼却此生心已许。\n一川风月聊为主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14484, '蝶恋花', '葛长庚', '楼上风光都占断。\n楼下风光，还许诗人管。\n管领风光谁是伴。\n一堤杨柳开青眼。\n波面琉璃花影乱。\n玉笋持杯，画舸歌声颤。\n醉里寻春春不见。\n夕阳芳草连天远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14485, '杨柳枝', '葛长庚', '碎梅花一断肠。\n送斜阳。\n风烟缥缈月微茫。\n又昏黄。\n平野寒芜何处断，接天长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14486, '沁园春', '葛长庚', '要做神仙，炼丹工夫，譬之似闲。\n耽姹女乘龙，金公御虎，玉炉火炽，土釜灰寒。\n铅里藏银，砂中取汞，神水华池上下间。\n山田内，有一条径路，直透泥丸。\n一声雷震山。\n真橐龠、飞冲夹脊关。\n见白雪漫天，黄芽满地，龟蛇缭绕，乌兔掀翻。\n自古乾坤，这些离坎，九转烹煎结大还。\n灵丹就，未飞升上阙，且在人寰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14487, '水调歌头', '葛长庚', '土釜温温火，橐龠动春雷。\n三田升降，一条径路属灵台。\n自有真龙真虎，和合天然铅汞，赤子结真胎。\n水里捉明月，心地觉花开。\n一转功，三十日，九旬来。\n抽添气候，炼成白血换骷骸。\n四象五形聚会，只在一方凝结，方寸绝纤埃。\n人在泥丸上，归路入蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14488, '水调歌头', '葛长庚', '一个奇男子，万象落心胸。\n学书学剑，两般都没个成功。\n要去披缁学佛，首下一拳轻快，打破太虚空。\n末後生华发，再拜玉清翁。\n二十年，空挫过，只飘蓬。\n这回归去，武夷山下第三峰。\n住我旧时庵子，碗水把柴升米，活火煮教浓。\n笑指归时路，弱水海之东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14489, '水调歌头', '葛长庚', '苦苦谁知苦，难难也是难。\n寻思访道，不知行过几重山。\n吃尽风雨，那见霜凝雪冻，饥了又添寒。\n满眼无人问，何处扣玄关。\n好因缘，传口诀，炼金丹。\n街头巷尾，无言暗地自生欢。\n虽是蓬头垢面，今已九旬来地，尚且是童颜。\n未下飞升诏，且受这清闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14490, '水调歌头', '葛长庚', '天下云游客，气味偶相投。\n暂时相聚，忽然云散水空流。\n饱饫闽中风月，又爱浙间山水，杖屦且逍遥。\n太上包中下，只得个无忧。\n是和非，名与利，一时休。\n自家醒了，不成得恁地埋头。\n任是南州北郡，不问大张小李，过此便相留。\n且吃随缘饭，莫作俗人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14491, '水调歌头', '葛长庚', '未遇明师者，日夜苦忧惊。\n及乎遇了，得些口诀又忘情。\n可惜蹉跎过了，不念精衰气竭，碌碌度平生。\n何不回头看，下手采来烹。\n天下人，知得者，不能行。\n可怜埋没，如何恁地不惺惺。\n只见口头说著，方寸都无些子，只管看丹经。\n地狱门开了，急急办前程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14492, '水调歌头', '葛长庚', '堪笑廛中客，都总是迷流。\n冤家缠缚，算来不是你风流。\n不解去寻活路，只是担枷负锁，不肯放教休。\n三万六千日，受尽百年忧。\n得人身，休蹉过，急须修。\n乌飞兔走刹那，又是死临头。\n只这眼前快乐，难免无常两字，何似出尘囚。\n炼就金丹去，万劫自逍遥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14493, '念奴娇', '葛长庚', '广寒宫里，散天花、点点空中柳絮。\n是处楼台皆似玉，半夜风声不住。\n万里盐城，千家珠瓦，无认蓬莱处。\n但呼童、且去探梅花，攀那树。\n垂帘未敢掀开，狮儿初捏就，佳人偷觑。\n溪畔渔翁蓑又重，几点沙鸥无语。\n竹折庭前，松僵路畔，满目都如许。\n问要晴，更待积痕消，须无雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14494, '满庭芳', '葛长庚', '鼎用乾坤，药须乌兔，恁时方炼金丹。\n水中虎吼，火里赤龙蟠。\n况是兑铅震汞，自元谷、上至泥丸。\n些儿事，坎离复垢，返老作童颜。\n五行，全四象，不调停火候，间断如闲。\n六天罡所指，玉出山。\n不动纤毫云雨，顷刻处、直透三关。\n黄庭内，一阳来复，丹就片时间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14495, '满庭芳', '葛长庚', '两种汞铅，黄婆感合，如如真虎真龙。\n周年造化，蹙在片时中。\n炉里温温种子，玄珠象、气透三宫。\n金木处，炼成赤水，白血自流通。\n无中。\n胎已兆，见龟蛇乌兔，恍惚相逢。\n但坎离既济，复垢交融。\n了得真空命脉，天地里、万物春风。\n阴阳外，天然夫妇，一点便成功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14496, '酹江月・念奴娇', '葛长庚', '因看斗柄，运周天、顿悟神仙妙诀。\n一点真阳生坎位，点却离宫之缺。\n造物无声，水中起火，妙在虚危穴。\n今年冬至，梅花依旧凝雪。\n先圣此日闭关，不通来往，皆为群生设。\n物物□含生育意，正在子初亥末。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14497, '珍珠帘・真珠帘', '葛长庚', '阴阳内感相交结。\n有铅汞、分八卦罗列。\n金鼎炼黄芽，正一阳时节。\n子後午前方进火，向玉炉、烹成白雪。\n通彻。\n这玄关、深奥难轻泄。\n因师指诀幽微，把金丹大药，将来分说。\n捉住虎龙精，自然日月。\n造化天机人怎晓，换俗骨、永无魔折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14498, '哨遍', '刘克庄', '胜处可宫，平处可田，泉土尤甘美。\n深复深，路绝住人稀。\n有人兮、盘旋於此。\n送子归。\n是他隐居求志。\n是要明主媒当世。\n嗟此意谁论，其言甚壮，孔颜犹有遗旨。\n大丈夫之被遇於时。\n入则坐庙朝出旗麾。\n列屋名姬，夹道武夫，满前才子。\n噫。\n有命存焉，吾非恶此而逃之。\n富贵人所欲，如之何、幸而致。\n向茂树堪休，清泉可濯，谷中别有闲天地。\n况脍细於丝，蕨甜似蜜，采於山，钓於水。\n大丈夫不遇之所为。\n唐处士、依稀是吾师。\n觉山林、尊如朝市。\n五侯门下宾客，扰扰趋形势。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14499, '六州歌头', '刘克庄', '维摩病起，兀坐等枯株。\n清晨里，谁来问，是文殊。\n遣名姝。\n夺尽群花色，浴才出，酲初解，千万态，娇无力，困相扶。\n绝代佳人，不入金张室，却访吾庐。\n对茶铛禅榻，笑杀此翁。\n珠髻金壶。\n始消渠。\n忆承平日，繁华事，修成谱，写成图。\n奇绝甚，欧公记，蔡公书。\n古来无。\n一自京华隔，问姚魏、竟何如。\n多应是，彩云散，劫灰馀。\n野鹿衔将花去，休回首、河洛丘墟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14500, '水调歌头', '刘克庄', '敕使竟空反，公不出梅关。\n当年玉座记忆，仄席问平安。\n羽扇尉佗城上，野服仙游阁下，辽鹤几时还。\n赖有蜀耆旧，健笔与书丹。\n青油士，珠履客，各凋残。\n四方蹙蹙靡骋，独此尚宽闲。\n丞相祠堂何处，太傅石碑堕泪，木老瀑泉寒。\n往者不可作，置酒且登山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14501, '水调歌头', '刘克庄', '遣作岭头使，似戍玉门关。\n来时送者，举酒珍重祝身安。\n街畔小儿拍笑，马上是翁矍铄，头与璧俱还。\n何处得仙诀，发白颊犹丹。\n屋茅破，篱菊瘦，架签残。\n老夫自计甚审，忙定不如闲。\n客难扬雄拓落，友笑王良来往，面汗背芒寒。\n再拜谢不敏，早晚乞还山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14502, '水调歌头', '刘克庄', '老子颇更事，打透利名关。\n百年扰扰于役，何异入槐安。\n梦里偶然得意，醒後才堪发笑，蚁穴驾车还。\n恰佩南柯印，彷佛毂曾丹。\n客未散，日初，酒犹残。\n向来幻境安在，回首总成闲。\n莫问浮云起灭，且跨刚风游戏，露冷玉箫寒。\n寄语抱朴子，候我石楼山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14503, '水调歌头', '刘克庄', '半世惯歧路，不怕唱阳关。\n朝来印绶解去，今夕枕初安。\n莫是散场优孟，又似下棚傀儡，脱了戏衫还。\n老去事多忘，公莫笑师丹。\n笔端花，胸中锦，两消残。\n江湖水草空旷，何必养天闲。\n久苦诸君共事，更尽一杯别酒，风露夜深寒。\n回首行乐地，明日隔云山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14504, '水调歌头', '刘克庄', '落日几呼渡，佳夕每留关。\n有时来照清浅，鬓云似潘安。\n一曲亲蒙君赐，两岸更无人迹，惟见鹭飞还。\n隙地欠栽接，蕉荔杂黄丹。\n柳全疏，松尚幼，怕摧残。\n旁人笑我痴计，管钥费防闲。\n翁意在乎林壑，客亦知夫水月，满腹贮清寒。\n赋咏差有愧，赤壁与滁山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14505, '水调歌头', '刘克庄', '羯虏问周鼎，柱史出秦关。\n苦求句漏，何意身世远差安。\n不见鸢堕水，时有飞鸿遵渚，乐此久忘还。\n采药寓言耳，胸次有灵丹。\n钓游处，榕叶暗，荻花残。\n自翁仙後千载，输与水鸥闲。\n我读内篇未竟，忽被急符驱去，洞闭白云寒。\n回首愧幽子，隐约海中山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14506, '水调歌头', '刘克庄', '怪事广寒殿，此夕不开关。\n林间乌鹊相贺，暂得一枝安。\n只在浮云深处，谁驾长风挟取，明镜忽飞还。\n玉兔呼不应，难觅臼中丹。\n酒行深，歌听彻，笛吹残。\n嫦娥老去孤另，离别匹如闲。\n待得银盘擎出，只怕玉峰醉倒，衰病不禁寒。\n卿去我欲睡，孤负此湖山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14507, '水调歌头', '刘克庄', '老年有奇事，天放两中秋。\n使君飞榭千尺，缥缈见麟洲。\n景物东徐城上，岁月北征诗里，圆缺几时休。\n俯仰慨今昔，惟酒可浇愁。\n风露高，河汉澹，素光流。\n贾胡野老相庆，四海十分收。\n竞看娥金镜，争信仙人玉斧，费了一番修。\n衰晚笔无力，谁伴赋黄楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14508, '水调歌头', '刘克庄', '岁晚太玄草，深悔赋长杨。\n向来户外之屦，已饱各飞扬。\n阁上青藜安在，院里金莲去矣，且爱短檠光。\n衰懒倦宾客，谁访老任棠。\n叹时人，怜黠小，笑鲐黄。\n汝曹变灭臭腐，侬底愈芬香。\n苦羡阿龙则甚，学取幼安亦可，坐穴几藜床。\n零落雁行小，敢不举君觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14509, '沁园春', '刘克庄', '何处相逢，登宝钗楼，访铜雀台。\n唤厨人斫就，东溟鲸脍，圉人呈罢，西极龙媒。\n天下英雄，使君与操，馀子谁堪共酒杯。\n车千两，载燕南赵北，剑客奇才。\n饮酣画鼓如雷。\n谁信被晨鸡轻唤回。\n叹年光过尽，功名未立，书生老去，机会方来。\n使李将军，遇高皇帝，万户侯何足道哉。\n披衣起，但凄凉感旧，慷慨生哀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14510, '沁园春', '刘克庄', '岁暮天寒，一剑飘然，幅巾布裘。\n尽缘云鸟道，跻攀绝顶，拍天鲸浸，笑傲中流。\n畴昔奇君，紫髯铁面，生子当如孙仲谋。\n争知道，向中年犹未，建节封侯。\n南来万里何求。\n因感慨桥公成远游。\n叹名姬骏马，都成昨梦，只鸡斗酒，谁吊新丘。\n天地无情，功名有命，千古英雄只麽休。\n平生客，独羊昙一个，洒泪西州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14511, '沁园春', '刘克庄', '我羡君归，一路秋风，芙蓉木犀。\n想慈颜望久，灵乌乍噪，新眉画就，郎马频嘶。\n忙脱征衫，快呼斗酒，细为家人说建溪。\n争知道，这中年怀抱，最怕分携。\n丈夫南北东西。\n应笑杀离筵粉泪啼。\n怅佳人来未，碧云冉冉，王孙去後，芳草萋萋。\n明日相思，山重水复，古道人稀茅店鸡。\n元龙老，有高楼百尺，谁共登梯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14512, '沁园春', '刘克庄', '一卷阴符，二石硬弓，百斤宝刀。\n更玉花骢喷，鸣鞭电抹，乌丝阑展，醉墨龙跳。\n牛角书生，虬髯豪客，谈笑皆堪折简招。\n依稀记，曾请缨系粤，草檄征辽。\n当年目视云霄。\n谁信道凄凉今折腰。\n怅燕然未勒，南归草草，长安不见，北望迢迢。\n老去胸中，有些磊块，歌罢犹须著酒浇。\n休休也，但帽边鬓改，镜里颜凋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14513, '沁园春', '刘克庄', '我梦见君，戴飞霞冠，著宫锦袍。\n与牧之高会，齐山诗酒，谪仙同载，采石风涛。\n万卷星罗，千篇电扫，肯学穷儿事楚骚。\n掀髯啸，有鱼龙鼓舞，狐兔悲嗥。\n英雄埋没蓬蒿。\n谁摸索当年刘与曹。\n叹事机易失，功名难偶，诛茅西崦，种秫东皋。\n栅有鸡豚，庭无羔雁，道是先生索价高。\n人间窄，待相期海上，共摘蟠桃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14514, '沁园春', '刘克庄', '有个头陀，形等枯株，心犹死灰。\n幸春山笋贱，无人争吃，夜炉芋美，与客同煨。\n何处花，忽相导引，莫是天宫迎赴斋。\n又疑道，向毗耶城里，讲席初开。\n这边尚自徘徊。\n笑那里纷纷早见猜。\n有尊神奋杵，拳粗似钵，名缁竖拂，喝猛如雷。\n老子无能，山僧不会，谁误檀那举请哉。\n山中去，便百千亿劫，休下山来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14515, '沁园春', '刘克庄', '我所思兮，延陵季子，别来九春。\n笑是非浮论，白衣苍狗，文章定价，秋月华星。\n独步岷峨，後身坡颍，何必荀家有二仁。\n中朝里，看叔兮衮斧，伯也丝纶。\n洛中曾识机云。\n记玉立堂堂九尺身。\n叹苕溪渔艇，幽人孤往，雁山马鬣，吊客谁经。\n宣室厘残，玄都花谢，回首旧游存几人。\n新腔美，堪洗空恩怨，唤起交情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14516, '沁园春', '刘克庄', '莫羡渠侬，白玉成楼，黄金筑台。\n也不消颠怪，骑被发，谁能委曲，令鸠为媒。\n鬓有二毛，袖闲双手，只了持螯与把杯。\n公过矣，赏陈登豪气，杜牧粗才。\n便烦问讯张雷。\n甚斗宿无光剑不回。\n想阁中鸣佩，时携客去，壁间悬榻，近有谁来。\n撤我虎皮，让君牛耳，谁道两贤相厄哉。\n中年後，向歌阑易感，乐极生哀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14517, '沁园春', '刘克庄', '辽鹤重来，不见繁华，只见凋残。\n甚都无人咏，何郎诗句，也无人报，书记平安。\n闾里俱非，江山略是，纵有高楼莫倚栏。\n沈吟处，但萤飞草际，雁起芦间。\n不辞露宿风餐。\n怕万里归来双鬓斑。\n算这边赢得，黑貂裘敞，那边输了，翡翠衾寒。\n檄草流传，吟笺倚阁，开到琼花亦懒看。\n君记取，向中州差乐，塞地无欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14518, '沁园春', '刘克庄', '华发萧萧，归碧鸡坊，出金马门。\n把一枝色笔，掷还郭璞，些儿残锦，回乞天孙。\n永免朝参，更无宣锁，送老三家水竹村。\n休休也，任巫阳来下，未易招魂。\n茅檐安得庖阍。\n倩便了沽来酒满樽。\n叹角巾东路，吾寻初服，上书北阙，子漫危言。\n漏院霜靴，火城雪辔，得似先生败絮温。\n安危事，付布衣融泰，鼎足膺蕃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14519, '沁园春', '刘克庄', '载籍以来，於宇宙间，有功者谁。\n自唐尧咨禹，水行由地，宗周微管，夏变为夷。\n谢傅棋边，莱公骰畔，淝水澶渊送捷旗。\n天不偶，生堂堂国老，真太平基。\n雅怀厌倦台司。\n新天子殷勤留帝师。\n向朝堂衮绣，万羊非泰，湖山绦褐，两鹤相随。\n寿过溪，德如淇澳，进了丹书作抑诗。\n蒯缑客，愿年年岁岁，来献新词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14520, '沁园春', '刘克庄', '驯於蹇驴，清於赐驹，我行尔从。\n幸柴车堪驾，何惭韩众，药苗可采，长伴庞公。\n野涧泉甘，阳坡草暖，有柏叶松枝充短供。\n修梦想，去游灵囿沼，入望夷宫。\n与夸夺子争雄。\n生与死未知谁手中。\n况嗾獒者众，放人少，大将触网，小亦伤弓。\n风月和柔，山林深密，折角何如且养茸。\n二虫喜，各衔花拜跪，来寿樗翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14521, '沁园春', '刘克庄', '剥啄谁欤，户外一宾，布衣麻鞋。\n有舌端雄辨，机锋破的，袖中行卷，锦绣成堆。\n阍启上宾，侬观诸老，个主人公喜挽推。\n怎奈向，今十分衰飒，非昔形骸。\n阍言宾怒如雷。\n因底事朱门晏未开。\n假使汝主公，做他将相，懒迎揖客，紧闭翘材。\n病叟惭惶，尊官宁耐，待铁拐先生旋出来。\n宾性急，怀生毛名纸，兴尽而回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14522, '沁园春', '刘克庄', '老子衰颓，晚与亲朋，约法三章。\n有谈除目者，勒回车马，谈时事者，麾出门墙。\n已挂衣冠，怕言轩冕，犯令先当举罚觞。\n书尺里，但平安二字，多少深长。\n溪翁苦未相忘。\n我今有双鱼烦寄将。\n道荒芜羞对，宫中莲烛，昏花难映，阁上藜光。\n闻庙瑟音，识关雎乱，诗学专门尽不妨。\n百年後，尚庶几申白，不数韦康。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14523, '沁园春', '刘克庄', '天造梅花，有许孤高，有许芬芳。\n似湘娥凝望，敛君山黛，明妃远嫁，作汉宫妆。\n冷艳谁知，素标难亵，又似夷齐饿首阳。\n幽雅意，纵写之缣楮，未得毫芒。\n曾经诸老平章。\n只一个孤山说影香。\n便诏书存问，漫招处士，节旄落尽，早屈中郎。\n日暮天寒，山空月堕，茅舍清於白玉堂。\n宁淡杀，不敢凭羌笛，告诉凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14524, '沁园春', '刘克庄', '畴昔遭逢，薰殿之琴，清庙之璋。\n谢锦袍打扮，佯狂太白，黄冠结裹，老大知章。\n种杏仙人，看桃君子，得似篱边嗅晚香。\n从人笑，笑安车迎晚，只履归忙。\n後身定作班扬。\n彼撼树蚍蜉不自量。\n偶有时戏笔，官奴藏去，有时醉坠，宗武扶将。\n永别鸾，已盟猿鹤，肯学周出草堂。\n从人笑，我韩公齿豁，张镐眉苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14525, '沁园春', '刘克庄', '惭愧清朝，罢贡包茅，住发牙璋。\n便羊裘归去，难留严子，牛衣病卧，肯泣王章。\n畴昔忧天，如今怀土，田舍鸡肥社酒香。\n甘雨足，且免扶锄苦，免踏车忙。\n先生少拟荀扬。\n晚自觉才衰可斗量。\n甚都无白凤，飞来玄草，亦无紫气，下烛干将。\n待得新亭，倒持手版，何似抽还政事堂。\n荣与辱，算到头由我，不属苍苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14526, '沁园春', '刘克庄', '吉梦维何，男子之祥，载弄之璋。\n嗟我辰安在，斯文後死，力侔元气，手抉天章。\n学稼田荒，炼丹灶壤，稽首南华一瓣香。\n休休也，免王良友笑，屑往来忙。\n浮名斗挹箕扬。\n世岂有明珠百斛量。\n叹种来瑶草，年深未熟，挑成锦字，道远难将。\n迁转不行，形容尽变，盍改称呼号瞎堂。\n遗弓远，怆帝乡云白，禹会山苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14527, '沁园春', '刘克庄', '余少之时，赋如仲宣，檄如孔璋。\n也曾观万舞，铺陈商颂，曾闻九奏，制作尧章。\n抖擞空囊，存留谏笏，犹带虚皇案畔香。\n今归矣，省听鸡骑马，趁早朝忙。\n榻前密启明扬。\n宰物者方持玉尺量。\n元未尝弃汝，自云耄及，无宁寿我，或者天将。\n富有图书，贫无钗泽，不似安昌列後堂。\n新腔好，任伊川看见，非亵穹苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14528, '沁园春', '刘克庄', '昔卧龙公，北走曹瞒，西克刘璋。\n看沙头八阵，百神呵护，渭滨一表，三代文章。\n绝笑渠侬，平生奸伪，死未忘情履与香。\n筹笔处，遣子丹引去，仲达奔忙。\n纷纷跋扈飞扬。\n这老子高深未易量。\n但纶巾指授，关河震动，灵旗征讨，夷汉宾将。\n到得市朝，变为陵谷，千载尝丞相堂。\n锦城外，有啭鹂音好，古柏皮苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14529, '沁园春', '刘克庄', '少工艺文，朱丝练弦，黄流在璋。\n值虞廷戛击，箫韶之乐，周王寿考，追琢其章。\n汾水雁飞，鼎湖龙远，魂返今无异域香。\n浮生短，更两轮屋角，来去荒忙。\n人言八十鹰扬。\n笑千岁如何尺捶量。\n但负图龟马，藏之为宝，舐丹鸡犬，去不能将。\n友鲁申公，师浮丘伯，尚可教书村学堂。\n投老泪，瞻越山紫翠，陵树青苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14530, '沁园春', '刘克庄', '安得奇材，颈系单于，首提子璋。\n便做些功业，胜穷措大，聚萤武子，吞凤君章。\n笑杀竖儒，错翻故纸，屈马何曾有艳香。\n榆塞外，恰枣红时候，想羽书忙。\n腰钱骑鹤维扬。\n分表事谁能预测量。\n叹防身一剑，壮图落，建侯万里，老境相将。\n读枕函书，宝家藏笏，免使他人笑弗堂。\n吾衰矣，虽尚存右臂，不解擎苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14531, '沁园春', '刘克庄', '帝赐玄圭，臣妾潘衡，奴隶侯璋。\n因封还除目，见鬼质，窜涂贽卷，取怨奇章。\n肯比寒儒，自夸秘宝，十袭庭寸许香。\n下岩石，要朝朝磨试，不论闲忙。\n何须狗监揄扬。\n这衡尺曾经圣手量。\n纵埋之地下，居然光怪，栖之梁上，亦恐偷将。\n蓬户无人，花村有犬，添几重茅覆野堂。\n交游少，约文房四友，泛浩摩苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14532, '沁园春', '刘克庄', '历事三朝，觐而执圭，祭而裸璋。\n更宫莲引入，视淮南草，御屏录了，露会稽章。\n贪膜外荣，遗身後臭，晔也平生漫传香。\n颜发改，独丹基无恙，事在休忙。\n曹丘生莫游扬。\n这瞎汉还曾自配量。\n已化为胡蝶，穿花栩栩，懒陪鹭，佩玉锵锵。\n机蹉面前，钟闻饭後，我上堂时众下堂。\n从前错，欲区区手援，天下黔苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14533, '沁园春', '刘克庄', '莫信人言，虺不如熊，瓦不如璋。\n为孟坚补史，班昭才学，中郎传业，蔡琰词章。\n尽洗铅华，亦无璎珞，犹带檀国里香。\n笑贫女，尚寒机轧轧，催嫁衣忙。\n好逑不数潘杨。\n占梦者曾言大秤量。\n待银河浪静，金针穿了，蓝桥路近，玉杵携将。\n倩似凝之，媲如道韫，帘卷燕飞王谢堂。\n恁时节，看孙皆朱紫，翁未皤苍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14534, '汉宫春', '刘克庄', '青女初晴，向丑梢枯干，幻出妍姿。\n休烦苑史翦彩，别有神司。\n东皇太乙，敕瑶姬、淡傅胭脂。\n还似得、华清汤暖，薄绡半卸冰肌。\n应笑楚宫痴绝，略施朱则个，便妒蛾眉。\n唐人更无籍在，浪比红儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14535, '汉宫春', '刘克庄', '多谢句芒，露十分春信，一种仙姿。\n主人领客卜夜，也唤分司。\n天葩国艳，几曾烦、薄粉浓脂。\n微似有，酒潮玉颊，更无粟起香肌。\n犹记老婆年少，爱斜簪宝髻，浅印红眉。\n回头笑他桃杏，太赤些儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14536, '汉宫春', '刘克庄', '酷爱名花，本不贪妖艳，惟赏幽姿。\n乌台旧案累汝，牵惹随司。\n冰层雪积，独伊家、点绛凝脂。\n应冷笑，海棠醉睡，牡丹未免丰肌。\n舞殿歌台此际，各新涂妆额，别画宫眉。\n那知有人淡泊，不识虫儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14537, '汉宫春', '刘克庄', '墙角残红，恍徐娘虽老，尚有丰姿。\n纷纶绛节导从，不要街司。\n随波万点，似阿房、漂出残脂。\n休懊恼，丹铅褪尽，本来冰雪为肌。\n老子平生心铁，被色香牵动，愁上双眉。\n且祝东风小缓，沥酒芒儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14538, '汉宫春', '刘克庄', '京辇相逢，忆茂陵临御，俱诣天官。\n绛纱玉斧咫尺，先引头班。\n桃花满观，与贞元、朝士同看。\n归骑晚，春城笳吹，冶游侵晓方还。\n回首龙髯何在，漫共谈前事，泪洒桥山。\n谁怜白头柱史，独出函关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14539, '汉宫春', '刘克庄', '老子今年，忽七旬加七，饱阅炎凉。\n夜窗犹坐书案，点勘偏旁。\n浮荣膜外，这些儿、感谢苍苍。\n试看取，名园甲第，主人几个还乡。\n淇澳溪二叟，向王朝抑抑，牧野洋洋。\n申公被蒲轮算，来议明堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14540, '汉宫春', '刘克庄', '此老先生，尚不留东阁，肯博西凉。\n我侬争敢，来近思旷之旁。\n朱颜未改，绝胜如、蔡义张苍。\n元自有，安丹灶地，何须求白云乡。\n欲缀小词称寿，□譬如河伯，观海洋。\n遥知垂弧甲第，置酒华堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14541, '汉宫春', '刘克庄', '吉语西来，已衮归行阙，册拜头厅。\n唐家岂可，一日轻去玄龄。\n洛英蜀客，老成人、几半朝廷。\n但管取，三边无警，活他百万生灵。\n槐第安排敕设，有藕如船大，有枣如瓶。\n瑶环瑜珥绕席，个个宁馨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14542, '汉宫春', '刘克庄', '公似寒梅，向层冰积雪，越样清奇。\n仙溪前辈相望，可比方谁。\n百篇剀切，似君谟、又似当时。\n更正简，相君颛面，崇清老子庞眉。\n未可卷怀袖手，续平泉庄记，绿野堂诗。\n苦言譬如食榄，回味方思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14543, '汉宫春', '刘克庄', '谢病归来，便文殊相问，懒下禅床。\n雀罗晨有剥啄，颠倒衣裳。\n袖中贽卷，原夫辈、安敢争强。\n若不是，子期苗裔，也应通谱元常。\n村叟鸡鸣籁动，更休烦箫管，自协宫商。\n酒边唤回柳七，压倒秦郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14544, '念奴娇', '刘克庄', '绕篱寻菊，菊犹迟、舍北芙蓉浑未。\n却是小山丛桂里，一夜天香飘坠。\n约束奴兵，丁宁稚子，莫扫青苔砌。\n风高露冷，倚栏疑匪人世。\n客有载酒过余，朗吟招隐，洗尽悲秋意。\n白发长官穷似虱，刚被天公调戏。\n遍地堆金，满空雨粟，不济渊明事。\n残英剩馥，明朝犹可同醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14545, '念奴娇', '刘克庄', '老夫白首，尚儿嬉、废圃一番料理。\n餐饮落英并坠露，重把离骚拈起。\n野艳幽香，深黄浅白，占断西风里。\n飞来双蝶，绕丛欲去还止。\n尝试诠次群芳，梅花差可，伯仲之间耳。\n佛说诸天金色界，未必庄严如此。\n尚友灵均，定交元亮，结好天随子。\n篱边坡下，一杯聊泛霜蕊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14546, '念奴娇', '刘克庄', '比如去岁前年，今朝差觉门庭静。\n玉轴锦标无一首，知道先生远佞。\n假使文殊，携诸菩萨，来问维摩病。\n无花堪散，亦无香积斋衬。\n回首雪浪惊心，黄茅过顶，瘴毒如炊甑。\n山鬼海神俱长者，饶得书生穷命。\n不慕飞仙，不贪成佛，不要钻天令。\n年年今日，白头母子家庆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14547, '念奴娇', '刘克庄', '卯君来处，与眉州仙子，依稀同日。\n一自前朝龚蔡後，颇觉壶山岑寂。\n谁料端平，继居遗补，复有斯人出。\n幅巾林下，姓名玉座长忆。\n须信谄语尤甘，忠言最苦，橄榄何如蜜。\n诸老萧疏星欲晓，留取南都铁壁。\n洛社自佳，镜湖虽好，莫问君王乞。\n年年岁岁，大家同做真率。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14548, '念奴娇', '刘克庄', '禁中张宴，苦留公、未许归寻初服。\n千载君臣鱼有水，不比严光文叔。\n火德中天，客星一夕，草草聊同宿。\n重来凝碧，依然赓载相属。\n过眼夸夺纷纷，浮云野马，几度棋翻局。\n客话凤池三入事，洗耳湖光一曲。\n伯始泉荒，稚圃冷，占断西风菊。\n年年岁岁，金英常泛芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14549, '念奴娇', '刘克庄', '素馨茉莉，向炎天、别有一般标致。\n淡妆绰约堪□□，导引海山大士。\n从者谁欤，青藜阁下，汉卯金之子。\n云阶月地，夜深凉意如水。\n客又疑这仙翁，唐玄都观里，咏桃花底。\n且赌樽前身见在，休管汉唐时事。\n坡颍归迟，机云发早，得似侬兄弟。\n屦来户外，但言二叟犹醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14550, '念奴娇', '刘克庄', '天风浩动，扫残暑、推上一轮圆魄。\n爱举眉山公旧话，与客泛舟赤壁。\n一自奎星，去朝帝所，叹洞箫声息。\n空馀二赋，至今凄动金石。\n长记诗境平生，诗豪酒圣，亦自仙中谪。\n畴昔停桡追欢处，忍听邻人吹笛。\n董相林荒，贺公湖在，俯仰成陈迹。\n两翁已矣，年年孤负今夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14551, '念奴娇', '刘克庄', '少时独步词场，引弦百发无虚矢。\n岁晚却蒙体力，世业工修鞋底。\n曾裂白麻，曾涂墨敕，谪堕俄徵起。\n鼎湖龙去，老臣何以堪此。\n回首当日遭逢，譬如春梦，误入华胥里。\n推枕黄粱犹未熟，封拜几王侯矣。\n似瓮中蛇，似蕉中鹿，又似槐中蚁。\n先人书在，尚堪追补遗史。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14552, '念奴娇', '刘克庄', '此翁双手，顿闲处、且把香篝笼袖。\n西掖北门辞不要，肯要南柯太守。\n小小亭台，些些竹木，何必灵和柳。\n地行仙里，合推侬做班首。\n取次著绝交书，续归田录，谁掣先生肘。\n莫遣朝衣梅醭了，留祝南山之寿。\n苍妓上厅，老僧封院，得似樗庵叟。\n虚名身後，生前且一杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14553, '念奴娇', '刘克庄', '梦中忘却，已闲退、谏草犹藏怀袖。\n文不会、铺张粉饰，武又安能战守。\n秃似葫芦，辣於姜桂，衰飒同蒲柳。\n没安顿处，不如归去丘首。\n岁晚筋力都非，任空花眩眼，枯杨生肘。\n客举前修三数个，待与刘君为寿。\n或号憨郎，或称钝汉，或自呼聱叟。\n一篇齐物，读时咽以卮酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14554, '念奴娇', '刘克庄', '戏衫抛了，下棚去、谁笑郭郎长袖。\n小小草庵无宝贝，何必神呵鬼守。\n黄奶篝灯，青奴拂榻，莫要他桃柳。\n客来问字，此翁高卧摇首。\n彷佛曾子当年，商歌满屋，衣不完衿肘。\n混沌若教休凿窍，巧历安知其寿。\n文叔故人，仲华几个，输与羊裘叟。\n浮生如寄，切身之物惟酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14555, '念奴娇', '刘克庄', '老逢初度，小儿女、盘问翁翁年纪。\n屈指先贤，彷佛似，当日申公归邸。\n跛子形骸，瞎堂顶相，更折当门齿。\n麒麟阁上，定无人物如此。\n追忆太白知章，自骑鲸去後，酒徒无几。\n恶客相寻，道先生、清晓中酲慵起。\n不袖青蛇，不骑黄鹤，混迹红尘里。\n彭聃安在，吾师淇澳君子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14556, '念奴娇', '刘克庄', '并游英俊，从头数、富贵消磨谁纪。\n道眼看来，叹人生如寄，家如旅邸。\n教婢羹藜，课奴种韭，聊诳残牙齿。\n草堂绵，百年栖托於此。\n岁晚笔秃无花，探怀中残锦，翦裁馀几。\n腰脚顽麻，赐他灵寿杖，也难扶起。\n离绝交游，变更名姓，日暮空山里。\n老儋复出，不知谁氏之子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14557, '念奴娇', '刘克庄', '四朝遗老，须眉白、巧历不知其纪。\n真唤九重为座主，肯谒侯门王邸。\n晚会耆英，未论爵德，乡曲无如齿。\n酒酣度曲，妙音久不闻此。\n堪叹化鹤重来，但累累华表，旧人存几。\n散尽黄金，留箧中团扇，怕秋风起。\n结绮歌阑，披香宴悄，放出深宫里。\n颠毛虽秃，尚堪封管城子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14558, '念奴娇', '刘克庄', '太丘晚节，把家事、一切传他谌纪。\n业已休休，又谁解露绶，会稽郡邸。\n张丈殷兄，阮生朱老，相与为唇齿。\n酒楼犹记，谪仙尝醉於此。\n一二耆旧贻书，新来强健否，问年今几。\n谢傅当时，却因个甚，抛了东山起。\n对局含，闻筝堕泪，围在愁城里。\n吾评晋士，不如归去来子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14559, '念奴娇', '刘克庄', '隆乾间事，两翁有、手泽遗编曾纪。\n余掌兰台修纂到，景定初开忠邸。\n起复麻，奋涂归笔，嚼碎张巡齿。\n德音犹在，非卿何足语此。\n老来兹事都休，问门前宾客，今朝来几。\n达汝空函，投伊大瓮内，谁曾提起。\n丹汞灰飞，黄粱炊熟，跳出槐宫里。\n儿童不识，秃翁定是谁子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14560, '念奴娇', '刘克庄', '轮云世故，千万态、过眼谁能殚纪。\n只履携归消许急，日暮行人问邸。\n麝以脐灾，绒为尾累，焚象都因齿。\n後之览者，亦将有感於此。\n检点洛下同盟，萧疏甚，白发戴花人几。\n一觉，笑仆家越石，闻鸡而起。\n颜发俱非，头皮犹在，胜捉来官里。\n俗间俚耳，未曾闻这腔子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14561, '念奴娇', '刘克庄', '自填曲子，自歌之、岂是行家官样。\n眼瞎背驼方引去，羞杀陈搏种放。\n摺起残编，寄声太乙，不必烦藜杖。\n陈人束阁，让他来者居上。\n安乐值几多钱，且幅巾绦褐，准云台象。\n长扇矮壶山南北，忘却晓随天仗。\n六逸七贤，五更三老，元不论资望。\n香山误矣，渔翁何减为相。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14562, '念奴娇', '刘克庄', '小孙盘问翁翁，今朝怎不陈弧矢。\n翁道暮年惟只眼，不比六根全底。\n常日谈玄，馀龄守黑，赤眚从何起。\n鬓须雪白，可堪委顿如此。\n心知病有根苗，短檠吹了，世界朦胧里。\n纵有金篦能去翳，不敢复囊萤矣。\n但愿从今，疾行如鹿，更细书如蚁。\n都无用处，留他教传麟史。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14563, '解连环', '刘克庄', '旁人嘲我。\n甚鬓毛都秃，齿牙频堕。\n不记是、何代何年，尽元熙宁，侬常喑麽。\n退下驴儿，今老矣、岂堪推磨。\n要挂冠神武，几番说了，这回真个。\n亲朋纷纷来贺。\n况弟兄对榻，儿女团坐。\n愿世世、相守茅檐，便宰相时来，二郎休作。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14564, '解连环', '刘克庄', '揆余初度。\n笑汝曹绯绿，乃翁苍素。\n一甲子、带水拖泥，今岁谢君恩，放还山去。\n政事堂中，把手版、分明抽付。\n向门前客道，老子出游，人不知处。\n小车万花引路。\n又谁能记得，观里千树。\n老冉冉、欢意阑珊，纵桃叶多情，难唤同渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14565, '解连环', '刘克庄', '悬弧之旦。\n忆争骑竹马，各怀金弹。\n恨岁月、去我堂堂，向酒畔愁生，镜中颜换。\n灶壤丹飞，慢追悔、邺侯婚宦。\n已发心忏悔，免去猴冠，卸下麟楦。\n依稀仆家铁汉。\n虽未梢老寿，初节魔难。\n幸闻早、省了柳枝，更送了朝云，尘念俱断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14566, '解连环', '刘克庄', '左弧悬了。\n把柴门闩定，悄无人到。\n惭傀得、一二亲朋，□□□□□，温存枯槁。\n玉轴银钩，撺掇我、比溪老。\n乏琼琚可报，惟有声声，司马称好。\n卷收绒鞯锦袄。\n且行拾遗穗，醉藉芳草。\n做一个、物外闲人，省山重担擎，天大烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14567, '木兰花慢', '刘克庄', '瀛洲真学士，为底事、在红尘。\n为语触宫围，沈香亭里，谪仙人。\n为亲近君侧者，见万言策子刘。\n为是尚方请剑，汉廷多惮朱云。\n君言往事勿重陈。\n且斗酒边身。\n也不会区区，算他甲子，记甚庚寅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14568, '木兰花慢', '刘克庄', '病翁将耳顺，牙齿落、鬓毛疏。\n也惭愧君恩，放还田舍，免诣公车。\n儿时某丘某水，到如今、老矣可樵渔。\n宝马华轩无分，蹇驴破帽如初。\n俘名箕斗竟成虚。\n磨折总因渠。\n帝锡余别号，江湖聱叟，山泽仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14569, '木兰花慢', '刘克庄', '古人吾不见，君莫是、郑当时。\n更筑就山房，躬耕谷口，名动京师。\n诸公任他衮衮，与杜陵野老共襟期。\n有客至门先喜，得钱沽酒何疑。\n昔年连辔柳边归。\n陈迹恍难追。\n况种桃道士，看花君子，回首皆非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14570, '木兰花慢', '刘克庄', '水亭凝望久，期不至、拟还差。\n隔翠幌银屏，新眉初画，半面犹遮。\n须臾淡烟薄霭，被西风扫不留些。\n失了白衣苍狗，夺回雪兔金蟆。\n乘云径到玉皇家。\n人世鼓三挝。\n试自判此生，更看几度，小住为佳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14571, '木兰花慢', '刘克庄', '海滨蓑笠叟，驼背曲、鹤形。\n定不是凡人，古来贤哲，多隐於渔。\n任公子、龙伯氏，思量来岛大上钩鱼。\n又说巨鳌吞饵，牵翻员峤方壶。\n溪老子雪眉须。\n肘後有丹书。\n被西伯载归，营丘茅土，牧野檀车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14572, '木兰花慢', '刘克庄', '郡人元未识，新太守、定何如。\n待说向诸贤，西桥人物，个个清。\n相将下车许久，但凝香之乐一些无。\n残漏几筹视事，浓油一盏观书。\n旁人徒见两轮朱。\n玉色未尝腴。\n有无穷阴骘，三农衣食，万衲钟鱼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14573, '木兰花慢', '刘克庄', '新来衰态见，书懒读，镜休看。\n笑量窄才悭，卷无警策，杯有留残。\n思量减些年甲，怎奈何、须与鬓难瞒。\n假使诏催上道，不如敕放还山。\n数年前乞挂衣冠。\n耄矣尚盘桓。\n且行歌拾穗，未应天上，解胜人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14574, '木兰花慢', '刘克庄', '维摩居士室，晨有鹊、噪檐声。\n排闼者谁欤，冶容服，宝髻珠璎。\n疑是毗耶城里，那天魔、变作散花人。\n姑射神仙雪艳，开元妃子春酲。\n延第一次西京。\n姚魏是知名。\n向欧九记中，思公屏上，描画难成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14575, '摸鱼儿', '刘克庄', '怪新年、倚楼看镜，清狂浑不如旧。\n暮云千里伤心处，那更乱蝉疏柳。\n凝望久。\n怆故国，百年陵阙谁回首。\n功名大谬。\n叹采药名山，读书精舍，此计几时就。\n封侯事，久矣输人妙手。\n沧洲聊作渔叟。\n高冠长剑浑闲物，世上切身惟酒。\n千载後。\n君试看，拔山扛鼎俱乌有。\n英雄骨朽。\n问顾曲周郎，而今还解，来听小词否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14576, '摸鱼儿', '刘克庄', '甚春来、冷烟凄雨，朝朝迟了芳信。\n蓦然作暖晴三日，又觉万姝娇困。\n霜点鬓。\n潘令老，年年不带看花分。\n才情减尽。\n怅玉局飞仙，石湖绝笔，孤负这风韵。\n倾城色，懊恼佳人薄命。\n墙头岑寂谁问。\n东风日暮无聊赖，吹得胭脂成粉。\n君细认。\n花共酒，古来二事天尤吝。\n年光去迅。\n漫绿叶成阴，青苔满地，做得异时恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14577, '摸鱼儿', '刘克庄', '便披蓑、荷锄归去，何须身著宫锦。\n与谁共话桑麻事，朱老阮生尤稔。\n筛样饼。\n瓮样茧，长须赤脚供樵饪。\n清流浊品。\n尽扫去胸中，置诸膜外，对酒莫辞饮。\n华胥梦，怕杀人惊晓枕。\n疏窗惟月来闯。\n一生常被弓旌误，且告朝家追寝。\n愁个甚。\n君管取，有薇堪采松堪荫。\n茅山再任。\n幸不是谋臣，又非世将，免犯道家禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14578, '转调二郎神・二郎神', '刘克庄', '抽还手版，受用处、十分轻省。\n便衣翦家机，饭炊躬稼，且免支移系省。\n帝悯龙锺蠲朝谒，予长假、毋烦申省。\n笑木石虚斋，暮年做，端明提省。\n闲冷。\n橐金散尽，书筒来省。\n有小小楼儿，看山待月，绝胜崔公望省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14579, '转调二郎神・二郎神', '刘克庄', '黄粱梦觉，忽跳出、北扉西省。\n今似得何人，老僧退院，秀才下省。\n罢草河西淮南诏，没一字、谘尚书省。\n已交侣樵渔，免教人道，弥封官省。\n多幸。\n条冰解去，新衔全省。\n笑杀太师光，赐灵寿杖，有诏扶他入省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14580, '转调二郎神・二郎神', '刘克庄', '一筇两屦，导从比、在京差省。\n更不草白麻，不批黄敕，稍觉心清力省。\n幸有善和书堪读，何必然藜芸省。\n且阁起庄骚，专看老易，课程尤省。\n梦境。\n槐阴禁苑，药翻纶省。\n纸裹里，有青铜钱三百，送与酒家展省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14581, '转调二郎神・二郎神', '刘克庄', '近来塞上，喜蜡弹、羽书清省。\n更万灶分屯，百年和籴，惭傀而今半省。\n蒙鞑残兵骑猪遁，永绝生侵省。\n做个太平民，戴花身健，催租符省。\n何幸。\n行人来密，佥军抽省。\n但进有都俞，退无科琐，不用依时出省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14582, '转调二郎神・二郎神', '刘克庄', '人言官冗，老病底、法当先省。\n况行则蹒跚，立时跛倚，幸免做他两省。\n客怕逢迎书慵答，得省处、而今姑省。\n笑落尽桃花，仆家梦得，重来郎省。\n凉冷。\n衣差薄，蒲葵堪省。\n叹三纪单栖，二毛纯白，情味似潘骑省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14583, '长相思', '刘克庄', '寒相催。\n暖相催。\n催了开时催谢时。\n丁宁花放迟。\n角声吹。\n笛声吹。\n吹了南枝吹北枝。\n明朝成雪飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14584, '长相思', '刘克庄', '朝有时。\n暮有时。\n潮水犹知日两回。\n人生长别离。\n来有时。\n去有时。\n燕子犹知社後归。\n君行无定期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14585, '长相思', '刘克庄', '风萧萧。\n雨萧萧。\n相送津亭折柳条。\n春愁不自聊。\n烟迢迢。\n水迢迢。\n准拟江边驻画桡。\n舟人频报潮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14586, '长相思', '刘克庄', '烟凄凄。\n草凄凄。\n野火原头烧断碑。\n不知名姓谁。\n印累累。\n冢累累。\n千万人中几个归。\n荣华朝露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14587, '长相思', '刘克庄', '劝一杯。\n复一杯。\n短锸相随死便埋。\n英雄安在哉。\n眉不开。\n怀不开。\n幸有江边旧钓台。\n拂衣归去来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14588, '昭君怨', '刘克庄', '曾看洛阳旧谱。\n只许姚黄独步。\n若比广陵花。\n太亏他。\n旧日王侯园圃。\n今日荆榛孤兔。\n君莫说中州。\n怕花愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14589, '昭君怨', '刘克庄', '后土宫中标韵。\n天上人间一本。\n道号玉真妃。\n字琼姬。\n我与花曾半面。\n流落天涯重见。\n莫把玉箫吹。\n怕惊飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14590, '昭君怨', '刘克庄', '一个恰雷州住。\n一个又廉州去。\n名姓在金瓯。\n不如休。\n昨日沙堤行马。\n今日都门飘瓦。\n君莫上长竿。\n下来难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14591, '生查子', '刘克庄', '繁灯夺霁华。\n戏鼓侵明发。\n物色旧时同，情味中年别。\n浅画镜中眉，深拜楼西月。\n人散市声收，渐入愁时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14592, '满江红', '刘克庄', '金甲雕戈，记当日、辕门初立。\n磨盾鼻、一挥千纸，龙蛇犹湿。\n铁马晓嘶营壁冷，楼船夜渡风涛急。\n有谁怜、猿臂故将军，无功级。\n平戎策，从军什。\n零落尽，慵收拾。\n把茶经香传，时时温习。\n生怕客谈榆塞事，且教儿咏花间集。\n叹臣之壮也不如人，今何及。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14593, '满江红', '刘克庄', '老子年来，颇自许、心肠铁石。\n尚一点、消磨未尽，爱花成癖。\n懊恼每嫌寒勒住，丁宁莫被晴烘坼。\n柰暄风烈日太无情，如何得。\n张画烛，频频惜。\n凭素手，轻轻摘。\n更几番雨过，彩云无迹。\n今夕不来花下饮，明朝空向枝头觅。\n对残红满院杜鹃啼，添愁寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14594, '满江红', '刘克庄', '赤日黄埃，梦不到、清溪翠麓。\n空健羡、君家别墅，几株幽独。\n骨冷肌清偏要月，天寒日暮尤宜竹。\n想主人、杖履绕千回，山南北。\n宁委涧，嫌金屋。\n宁映水，羞银烛。\n叹出群风韵，背时装束，竞爱东邻姬傅粉，谁怜空谷人如玉。\n笑林逋、何逊漫为诗，无人读。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14595, '满江红', '刘克庄', '满腹诗书，馀事到、穰苴兵法。\n新受了、乌公书币，著鞭垂发。\n黄纸红旗喧道路，黑风青草空巢穴。\n向幼安、宣子顶头行，方奇特。\n溪峒事，听侬说。\n龚遂外，无长策。\n便献俘非勇，纳降非怯。\n帐下健儿休尽锐，草间赤子俱求活。\n到崆峒、快寄凯歌来，宽离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14596, '满江红', '刘克庄', '落日登楼，谁管领、倦游狂客。\n待唤起、沧浪渔父，隔江吹笛。\n看水看山身尚健，忧晴忧雨头先白。\n对暮云、不见美人来，遥天碧。\n山中鹤，应相忆。\n沙上鹭，浑相识。\n想石田茅屋，草深三尺。\n空有鬓如潘骑省，断无面见陶彭泽。\n便倒倾、海水浣衣尘，难湔涤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14597, '满江红', '刘克庄', '天壤王郎，数人物、方今第一。\n谈笑里、风霆惊座，云烟生笔。\n落落元龙湖海气，琅琅董相天人策。\n问如何、十载尚青衫，诸侯客。\n易爱底，些官职。\n难保底，些名节。\n拟闭门投辖，剧谈三日。\n畴昔评君天下宝，当为天下苍生惜。\n向临分、慷慨出商声，摧金石。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14598, '满江红', '刘克庄', '鹤驭来时，长占定、一年清绝。\n九万里、纤云收尽，帝青空阔。\n月露偏为丹桂地，风霜欲放黄花节。\n听玉笙、缥缈度缑山，吹初彻。\n曾直把，龙鳞批。\n曾戏取，鲸牙拔。\n向绛河濯足，咸池发。\n俗子底量吾辈事，天仙不在儒列。\n世岂无、瑶草与蟠桃，堪攀掇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14599, '满江红', '刘克庄', '怪雨盲风，留不住、江边行色。\n烦问讯、冥鸿高士，钓鳌词客。\n千百年传吾辈话，二三子系斯文脉。\n听王郎、一曲玉箫声，凄金石。\n发处，怡山碧。\n垂钓处，沧溟白。\n笑而今拙宦，他年遗直。\n只愿常留相见面，未宜轻屈平生膝。\n有狂谈、欲吐且休休，惊邻壁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14600, '满江红', '刘克庄', '往日封章，曾耸动、君王颜色。\n今似得、三闾公子，四明狂客。\n古不能箝言者口，天方欲寿中朝脉。\n算人间、岂有病无医，须针石。\n年冉冉，袍犹碧。\n心耿耿，头先白。\n笑臣舒迂缓，臣山愚直。\n拂袖归来羞炙手，望尘拜了难伸膝。\n把富春濑与首阳山，图斋壁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14601, '满江红', '刘克庄', '三黜归来，饭疏食、浑无愠色。\n中年後、家如旅舍，身如行客。\n轩冕岂非疣赘具，烟霞已是膏盲脉。\n有些儿、隙地更疏泉，堆卷石。\n邻媪饷，新碧。\n溪友卖，鲜鳞白。\n向陈编冷笑，孔明元直。\n俗事不教污两耳，宴居聊可盘双膝。\n取当年、行脚一枝筇，悬高壁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14602, '满江红', '刘克庄', '畴昔胪传，仗下奏、祥云五色。\n何况是、西山弟子，鹤山宾客。\n上帝照临忠义胆，老师付授文章脉。\n问此君、彷佛似何人，徂徕石。\n园官菜，登盘碧。\n田舍米，翻匙白。\n懒投诗见素，寄书杓直。\n德耀不嫌为隐髻，龟儿已解摇吟膝。\n有谁怜、给札老相如，家徒壁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14603, '满江红', '刘克庄', '下见西山，料他日、面无惭色。\n君记取、不为吕党，亦非秦客。\n有意挽回当世事，无方延得诸贤脉。\n笑海波、渺渺几时平，空衔石。\n园五亩，纷红碧。\n家四世，传清白。\n任天孙笑拙，女嫌直。\n老去何烦援以手，向来不要加诸膝。\n待深山、深处著茅斋，看青壁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14604, '满江红', '刘克庄', '八十加三，人尽讶、还童返少。\n争信道、夜舂晓织，总曾经了。\n凛凛共姜当日誓，谆谆孟母平生教。\n到如今、象服拥鱼轩，天之报。\n如船藕，如瓜枣。\n斑衣舞，金锺。\n望秋宵一点，老人星照。\n尘世少如娘福寿，上苍知得儿忠孝。\n待看他、孙子又生孙，添怀抱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14605, '满江红', '刘克庄', '著破青鞋，浑不忆、踏他龙尾。\n更冷笑、痴人擘划，二三百岁。\n殇子彭谁寿夭，灵均渔父争醒醉。\n向江天、极目羡禽鱼，悠然矣。\n杯中物，姑停止。\n床头易，聊抛废。\n慨事常八九，不如人意。\n白雪调高尤协律，落霞语好终伤绮。\n待烦公、老手一摩挲，文公记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14606, '满江红', '刘克庄', '昨日梢头，点点似、玉尘珠砾。\n一夜里、天公染就，金丹颜色。\n体质翻嫌西子白，浓妆却笑东邻赤。\n尽重重、帘幕不能遮，香消息。\n寒日短，霜飞急。\n未摇落，须怜惜。\n且乱簪破帽，旋呼鸣瑟。\n便好移来云月地，莫教归去檀国。\n怕彩鸾、隐见霎时间，寻无迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14607, '满江红', '刘克庄', '祷祝封姨，休把做、扬沙吹砾。\n费西帝、许多薰染，浓香深色。\n满插铜芳气烈，高张画烛祥光赤。\n向先生、鼻观细参来，三千息。\n人老大，年华急。\n花妖艳，天公惜。\n到一枝摇落，千林萧瑟。\n摘蕊莫教轻糁地，返魂依旧能倾国。\n待彩云、月下再来时，寻陈迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14608, '满江红', '刘克庄', '月露晶英，融结做、秦宫块砾。\n长殿後、一年芳事，十分秋色。\n织女机边云锦烂，天台赋里晴霞赤。\n恍女仙、空际驾翔鸾，来游息。\n装束晚，飘零急。\n今不乐，空追惜。\n欠红牙按舞，朱弦调瑟。\n岂是时无花鸟使，是他自择风霜国。\n任落英、狼藉委苍苔，稀行迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14609, '满江红', '刘克庄', '谁把灵丹，点化了、荒园瓦砾。\n奇特处、恰当秋杪，不争春色。\n因甚素娥脂粉艳，怪他白帝车旗赤。\n叹暮年、无句比红儿，芳心息。\n狂飙起，行云急。\n开与谢，俱堪惜。\n唤妓行按酒，客来操瑟。\n扑鼻微香薰世界，解颜一笑迷人国。\n怕匆匆、归去广寒宫，难踪迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14610, '满江红', '刘克庄', '楮叶工夫，辛苦似、镂冰炊砾。\n君看取、天公巧处，自然形色。\n发彩已非前度绿，眼花休问何时赤。\n又谁能、月下待红娘，传音息。\n投辖饮，追欢急。\n持帚扫，痴心惜。\n有埙篪谐律，不宵竽瑟。\n点点散来居士室，丛丛生占骚人国，便高烧、绛蜡写乌丝，留真迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14611, '满江红', '刘克庄', '糁径红，莫要放、儿童抛砾。\n知渠是、仙家变幻，佛家空色。\n青女无端工翦彩，紫姑有崇曾迷赤。\n但双双、戏蝶绕空枝，飞还息。\n鲸量减，驹阴急。\n芳事过，馀情惜。\n漫新腔窈渺，奏云和瑟。\n飘荡随他红叶水，萧条化作青芜国。\n忆桥边、池上共攀翻，空留迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14612, '满江红', '刘克庄', '梅雨初收，浑不辨、东坡南荡。\n清旦里、鼓铙动地，车轮空巷。\n画舫稍渐京辇俗，红旗会踏吴儿浪。\n共葬鱼娘子斩蛟翁，穷欢赏。\n麻与麦，俱成长。\n蕉与荔，应来享。\n有累臣泽畔，感时惆怅。\n纵使菖蒲生九节，争如白发长千丈。\n但浩然一笑独醒人，空悲壮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14613, '满江红', '刘克庄', '说与行云，且就、嫦娥今夕。\n俄变见、金蛇能紫，玉蟾能白。\n九万里风清黑眚，三千世界纯银色。\n想天寒、桂老已吹香，堪攀摘。\n湘妃远，谁鸣瑟。\n桓伊去，谁横笛。\n叹素光如旧，朱颜非昔。\n老去欢无奈减，向来酒量常嫌窄。\n倩何人、天外挽冰轮，应留得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14614, '满江红', '刘克庄', '天上人间，好时节、无过初夏。\n君记取、瞿昙生後，纯阳来也。\n风骨清如野鹤，门庭低小才旋马。\n更旁无红粉有青奴，堪娱夜。\n鲸口吸，银瓶泻。\n蝇头字，篝灯写。\n数而今铁笔，谁如公者。\n便合去开丞相阁，未应牵入耆英社。\n待调羹事了却归来，寻前话。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14615, '满江红', '刘克庄', '屈指耆英，谁似得、三朝元老。\n尚留个、管夷吾在，何忧江表。\n世道方占公出处，裔夷争问今年貌。\n怎不移、此手整乾坤，长闲了。\n灵寿却，斑衣绕。\n如瓶李，如瓜枣。\n把禅龛闭定，怕蒲轮到。\n师尚父年浑未艾，中书令考犹为少。\n看画盆、岁岁浴曾玄，添怀抱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14616, '满江红', '刘克庄', '笳鼓春城，处处有、丰年语笑。\n浑忘却、金莲前导，青藜下照。\n白雪唱来遍寡和，朱颜老去难重少。\n羡遨头、四十已专城，真英妙。\n奎文宠，崇儒教。\n田毛喜，宽租诏。\n有舂陵之什，无潮州表。\n怪雨盲风稀发作，华星秋月争光耀。\n看来年、此夜侍端门，开佳兆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14617, '满江红', '刘克庄', '奎墨西来，落笔处、亲蒙天笑。\n谁信道、郡人生怕，福星移照。\n宾客唱予还和汝，使君安老兼怀少。\n况醉能同乐醒能文，新腔妙。\n无诸国，渐声教。\n元结辈，宣明诏。\n恍梦中辽鹤，重来华表。\n一盏勘书殊简径，万灯侍辇曾荣耀。\n怪晴檐、乾鹊语查查，公归兆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14618, '满江红', '刘克庄', '江左惟公，争些子、吾其衽发。\n谈笑里、旄头泛扫，斗杓旋斡。\n投一粒丹元气转，下三数著输棋活。\n把晋朝王谢传同看，谁优劣。\n飞凯奏，清夔峡。\n蠲和籴，宽畿浙。\n有三千功行，待从头说。\n玉满斟长寿酒，冰轮探借中秋月。\n更慈帏、喜见凤将雏，添丹穴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14619, '满江红', '刘克庄', '见宰官身，出只手、擎他宇宙。\n筹边外、招徕名胜，登崇勋旧。\n不下莱公扶景德，又如涑水开元。\n尽从渠、干贽及吾门，归斯受。\n上林苑，多花柳。\n祁连塞，稀刁斗。\n更红旗破贼，黄云栖亩。\n阿母瑶池枝上实，仙人太华峰头藕。\n泻铜盘、沆瀣入金卮，为公寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14620, '满江红', '刘克庄', '礼乐衣冠，浑靠定、堂堂国老。\n出双手、把天裂处，等闲补了。\n谢傅东山心未遂，周郎赤壁功犹小。\n事难於张赵两元台，扶炎绍。\n恢鹤禁，迎商皓。\n开兔苑，延枚叟。\n喜奎星来聚，旄头都扫。\n重译争询裴令貌，御诗也祝汾阳考。\n更何须、远向海山求，安期枣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14621, '满江红', '刘克庄', '压倒群芳，天赋与、十分艳。\n娇嫩处、有情皆惜，无香何慊。\n恰则才如针粟大，忽然谁把胭脂染。\n放迟开、不肯婿梅花，羞寒俭。\n时易过，春难占。\n欢事薄，才情欠。\n觉芳心欲诉，冶容微敛。\n四畔人来攀折去，一番雨有离披渐。\n更那堪、几阵夜来风，吹千点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14622, '满江红', '刘克庄', '嫌杀双轮，驾行客、之燕适粤。\n也不喜、船儿无赖，载他江浙。\n荡子不归鸳被冷，昭君远嫁毡车发。\n叹子规、闲管昔人愁，啼成血。\n渭城柳，争攀折。\n关山月，空圆缺。\n有琵琶改语，锦书难说。\n若要人生长美满，除非世上无离别。\n算古今、此恨似连环，何时绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14623, '水龙吟', '刘克庄', '年年岁岁今朝，左弧悬罢浑无事。\n吾衰久矣，我辰安在，老之将至。\n懒写京书，怕看除目，败人佳思。\n把东篱掩定，北窗开了，悠然酌、颓然睡。\n客有过门投贽。\n道先生访华胥氏。\n谁能辛苦，陪他绮语，记他奇字。\n屈指先贤，戴花老监，岂其苗裔。\n待异时约取，宽夫彦国，入耆英会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14624, '水龙吟', '刘克庄', '先生放逐方归，不如前辈抽身早。\n台郎旧秩，看来俗似，散人新号。\n起舞非狂，行吟非怨，高眠非傲。\n叹终南捷径，太行盘谷，用卿法、从吾好。\n闭了草庐长啸。\n後将军来时休报。\n床头书在，古人出处，今人非笑。\n制个淡词，呷些薄酒，野花簪帽。\n愿云台任满，又还因任，赛汾阳考。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14625, '水龙吟', '刘克庄', '病翁一榻萧然，不知世有欢娱事。\n雀罗庭院，载醪客去，催租人至。\n报答秋光，要些酒量，要些诗思。\n奈长鲸罢吸，寒蛩息响，查瓯外、惟贪睡。\n穷巷幸无干贽。\n或相过、莫知谁氏。\n柴门草户，阙人守舍，任伊题字。\n自和山歌，国风之变，离骚之裔。\n待从今向去，年年强健，插花高会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14626, '水龙吟', '刘克庄', '平生酷爱渊明，偶然一出归来早。\n题诗信意，也书甲子，也书年号。\n陶侃孙儿，孟嘉甥子，疑狂疑傲。\n与柴桑樵牧，斜川鱼鸟，同盟後、归於好。\n除了登临吟啸。\n事如天、莫相谘报。\n田园闲静，市朝翻覆，回头堪笑。\n节序催人，东篱把菊，西风吹帽。\n做先生处士，一生一世，不论资考。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14627, '水龙吟', '刘克庄', '祁公一度貂蝉，先生三度貂蝉了。\n燔柴升辂，银蟾烛夜，金乌腾晓。\n喜动龙颜，瑞班虹玉，归功元老。\n纵擎天力倦，明农心切，先还取、中书考。\n末著留侯难办，算除非、烦他商皓。\n紫芝产遍，赤松待久，何时高蹈。\n人世无过，鱼羹饭美，布衾铭好。\n待角巾东路，蹇驴北阜，伴公游钓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14628, '水龙吟', '刘克庄', '依然这後村翁，阿谁改换新曹号。\n虚名砂砾，旁观冷笑，何曾明道。\n吟歇後诗，说无生话，热瞒村獠。\n被儿童盘问，先生因甚，身顽健、年多少。\n不茹园公芝草。\n不曾餐、安期瓜枣。\n要知甲子，陈抟差大，邵雍差小。\n肯学痴人，据鞍求用，染髭藏老。\n待眉毛覆面，看千桃谢，阅三松倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14629, '水龙吟', '刘克庄', '儿童不识樗翁。\n挽衣借问年今几。\n少如彦国，大如君实，披襟高比。\n德业天渊，有些似处，须眉而已。\n愿老身无事，小车乘兴，名园内、行窝里。\n做取出关周史。\n莫做他、下山园绮。\n从人谤道，是浮丘伯，是庚桑子。\n背伛肩高，幅巾藜杖，敞袍穿履。\n向画图上面，十分似个，见端门底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14630, '水龙吟', '刘克庄', '即令七十平头，岂能久作人间客。\n左车牙落，半分臂小，几茎须白。\n挟种树书，举障尘扇，著游山屐。\n任蛙蟆胜负，鱼龙变化，侬方在、华胥国。\n岛大功名官职。\n眼中花、须臾无迹。\n小儿破贼，二郎作相，有何奇特。\n同辈萧疏，且留铁汉，要摩铜狄。\n向宝钗楼里，天津桥上，月明横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14631, '玉漏迟', '蒋捷', '翠鸳双穗冷。\n莺声唤转，春风芳景。\n花涌□香，此度徐妆偏称。\n水月仙人院宇，到处有、西湖如镜。\n烟岫暝。\n纤葱误指，莲峰篁岭。\n料想小阁初逢，正浪拍红猊，袖飞金饼。\n楼倚斜晖，暗把佳期重省。\n万种惺忪笑语，□一点、温柔情性。\n钗倦整。\n盈盈背灯娇影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14632, '高阳台', '蒋捷', '宛转怜香，徘徊顾影，临芳更倚苔身。\n多谢残英，飞来远远随人。\n回头却望晴檐下，等几番、小摘微薰。\n到而今、独袅鞭梢，笑不成春。\n愁吟未了烟林晓，有垂杨夹路，也为轻。\n今夜山窗，还□□绕梨云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14633, '探春令', '蒋捷', '玉窗蝇字记春寒，满茸丝红处。\n画翠鸳、双展金蜩翅。\n未抵我、愁红腻。\n芳心一点天涯去。\n絮遮住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14634, '秋夜雨', '蒋捷', '黄云水驿秋笳噎。\n吹人双鬓如雪。\n愁多无奈处，谩碎把、寒花轻绝。\n红云转入香心里，夜渐深、人语初歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14635, '秋夜雨', '蒋捷', '金衣露湿莺喉噎。\n春情不解分雪。\n宝筝弦断尽，但万缕、闲愁难绝。\n长红小白谁亭馆，过禁烟、弹指芳歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14636, '秋夜雨', '蒋捷', '髹车转急风如噎。\n冰丝松藕新雪。\n有人凉满袖，怕汗湿、红梢犹绝。\n三更梦断敲荷雨，细听来、疏点还歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14637, '秋夜雨', '蒋捷', '红麟不暖瓶笙噎。\n炉灰一片晴雪。\n醉无香嗅醒，但手把、新橙闲绝。\n更深冻损梅花也，听画堂、箫鼓方歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14638, '少年游', '蒋捷', '梨边风紧雪难晴。\n千点照溪明。\n吹絮窗低，唾茸窗小，人隔翠阴行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14639, '少年游', '蒋捷', '枫林红透晚烟青。\n客思满鸥汀。\n二十年来，无家种竹，犹借竹为名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14640, '柳梢青', '蒋捷', '学唱新腔。\n秋千架上，钗股敲双。\n柳雨花风，翠松裙褶，红腻鞋帮。\n归来门掩银。\n淡月里、疏钟渐撞。\n娇欲人扶，醉嫌人问，斜倚楼窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14641, '霜天晓角', '蒋捷', '人影窗纱。\n是谁来折花。\n折则从他折去，知折去、向谁家。\n檐牙。\n枝最佳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14642, '水龙吟', '陈德武', '东南第一名州，西湖自古多佳丽。\n临堤台榭，画船楼阁，游人歌吹。\n十里荷花，三秋桂子，四山晴翠。\n使百年南渡，一时豪杰，都忘却、平生志。\n可惜天旋时异。\n藉何人、雪当年耻。\n登临形胜，感伤今古，发挥英气。\n力士推山，天吴移水，作农桑地。\n借钱塘潮汐，为君洗尽，岳将军泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14643, '西江月', '陈德武', '山拱罗城四面，柳营横接江东。\n十年前事影随风。\n今日宛如春梦。\n天下几多邮驿，人生到处飘蓬。\n丹霞楼上再相逢。\n横笛为君三弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14644, '望海潮', '陈德武', '珑山西峙，浙江东逝，谁馀一箭临冲。\n凤舞龙飞，地灵人杰，当年树此勋庸。\n强弩万夫雄。\n令冯夷退舍，海若潜锋。\n拥石成堤，百川约束障西东。\n至今人物蕃丰。\n仰功扬山立，德润川容。\n乐极西湖，愁多南渡，他都是梦魂空。\n感古恨无穷。\n叹表忠无观，古墓谁封。\n棹舣钱塘，浊醪和泪洒秋风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14645, '水龙吟', '陈德武', '驿楼岁暮萧条，小桃何事迎人笑。\n无言如诉，命暌王母，信沈青鸟。\n靥瘦繁霜，脂销零雨，梦寒清晓。\n自刘郎去後，天台路隔，知孤负、春多少。\n今日玉骢来到。\n喜相逢、菱花孤照。\n清幽谁伴，黄花告谢，芙蓉云老。\n早趁东风，移根换叶，脱身池沼。\n卜佳期，前度琴心一曲，作相思调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14646, '沁园春', '陈德武', '冬夜如年，客枕无眠，怎到天明。\n待数残二十五、寒更点，听馀一百八、晓钟声。\n雨却敲篷，滩头激缆，总与离人诉不平。\n遍闻得，我浚深恨海，砌起愁城。\n问君何事牵萦。\n想最苦人间是别情。\n念千山万水，沈鱼阻雁，一身两地，燕煎莺。\n绣枕痕多，锦衾香冷，意有巫山梦不成。\n怎撇下，这两字相思，万里虚名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14647, '西江月', '陈德武', '时序去如流矢，人生宛如飞蓬。\n石湾江上又逢冬。\n且喜一场初动。\n但见堪舆杳杳，更连山水重重。\n凄凉云物雨。\n惟足睡中归梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14648, '望海潮', '陈德武', '山涯海角，天高地厚，长安举首何妨。\n万水朝宗，众星环极，平生此志无忘。\n亭上一翱翔。\n见烟收雾敛，凤翥龙骧。\n海色沧凉，金乌拍翅上扶桑。\n遥瞻咫尺清光。\n物无遐不烛，有隐皆彰。\n发心劳，之官路远，篙师又促归航。\n不敢久徜徉。\n抱梧桐绮实，葵藿心肠。\n假我双翰，一朝飞上五云乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14649, '木兰花慢', '陈德武', '自淮阳别後，一回首、又穷年。\n叹蓬逐旋飚，叶随流水，星散维垣。\n南来忽闻归兴，岂苍天、故意要储贤。\n云慢凌司马赋，风偏动季鹰船。\n梅窗夜月见修妍。\n骏辔忆连钱。\n命画桨溪流，篮舆山郭，囊锦诗篇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14650, '木兰花慢', '陈德武', '对江云日暮，又那更、夜如年。\n见霜满晴空，山衔星斗，月挂城垣。\n知心故人间阻，几何时、尊酒会多贤。\n冷落巴山夜雨，凄凉剡水寒船。\n孱容羞睹镜中研。\n远水与天连。\n怪梦有馀甜，酒无好味，诗不成篇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14651, '木兰花慢', '陈德武', '一春看又尽，问何日、是归年。\n望五岭重关，九嶷叠翠，满目藩垣。\n苍梧几时舣棹，许论文、高议仰英贤。\n夜立残花影月，朝盼尽柳阴船。\n天台山水世间研。\n天老赤城连。\n好收拾兰庄，白云深处，咏卜居篇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14652, '望海潮', '陈德武', '三分春色，十分官事，令人孤负芳菲。\n歌燕簧莺，语花舞柳，园林好处谁知。\n还忆旧游时。\n对海棠驻马，红药题诗。\n一别东君，回顾又是隔年期。\n相思远在天涯。\n镇海填恨臆，山锁愁眉。\n杜宇能言，鹧鸪有泪，慢劳蝴蝶于飞。\n景与少年宜。\n把榆分新火，香透罗衣。\n风月常存，双鱼报道早来归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14653, '百字谣・念奴娇', '陈德武', '惜花心事，不由人、蝴蝶梦魂先觉。\n刚纳绣鞋行掠鬓，仰见斗横林杪。\n昨日深红，今朝轻白，颜色殊昏晓。\n此中滋味，料他尘世知少。\n问二十四番风，寒梅并绛楝，始终俱好。\n须看未开开又谢，多少落英颠倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14654, '百字谣・念奴娇', '陈德武', '古今明月，魄生明後，积渐圆还缺。\n秋解伤神春最好，衾枕几番铺设。\n十二瑶台，千金一刻，横竹休吹彻。\n绣帘高揭，戒他莫把灯。\n夜久谁共婵娟，掩孤帏睡去，此情尤切。\n梦驾彩鸾何处觅，飞上玉楼琼阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14655, '百字谣・念奴娇', '陈德武', '晚临湘浦，忆鲛人、曾许泪珠绡帕。\n盥掬空明和月待，宫锁水晶深夜。\n跃壁初圆，浮金不定，敌眼寒光射。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14656, '百字谣・念奴娇', '陈德武', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14657, '望海潮', '陈德武', '南冠一载，西流万里，离怀孰不伤情。\n富贵邯郸，雨云巫峡，回头一梦空惊。\n谁辱又谁荣。\n问当时道德，今日功名。\n楚水吴山，向来多少送和迎。\n长安古道长亭。\n叹马啼不驻，车辙难停。\n薇老首阳，芝深商谷，时遥雾拥云平。\n此意已羞评。\n但金缄白雪，锦佩青萍。\n采竹，有时吹作凤凰鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14658, '望海潮', '陈德武', '祖觞东馆，移舟南渡，江天云树离离。\n盘谷渔樵，舞雩风咏，渴心常望云霓。\n知与故人齐。\n念翼残犹铩，足蹶还羁。\n百折江流，峡猿水鸟助孤凄。\n几回梦绕山西。\n耐疏篷夜雨，惊枕晨鸡。\n对无声诗，哦有声画，仪形已见端倪。\n回首暮云迷。\n又桐飞金井，燕落乌衣。\n有意相思，双鳞乘羽莫教迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14659, '西江月', '陈德武', '凤舞汉阳月丽，龙吟汉水波飞。\n行云何事驻天涯。\n横玉危阑四倚。\n问岳阳三度後，看尘世几番棋。\n鹤群何处未归来。\n冷落吴头楚尾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14660, '西江月', '陈德武', '为问云间滕六，天工何事依违。\n冬时三白不时为。\n今日驾言春瑞。\n瘦损穷彭泽柳，禁持杀傅岩梅。\n仁风反掌霁天威。\n都做一江流水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14661, '西江月', '陈德武', '疏散履穿东郭，流离马没蓝关。\n瓜洲谁问卧袁安。\n孤负新年月半。\n铁瓮成银瓮出，金山做玉山看。\n无知儿女不知寒。\n冰箸掌中争看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14662, '西江月', '陈德武', '压雪江山亦老，迎春草木俱新。\n雪销春去逐飞轮。\n谁识静中机运。\n浊浊坝头泥土，攘攘市上风尘。\n为何不住往来人。\n都被利名淘尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14663, '西江月', '陈德武', '有信江头春色，无凭天上浮云。\n白衣苍狗又何频。\n岂是随风情性。\n法受三千谪路，翻成万里思亲。\n瓜洲中道不逢人。\n谁寄江南春信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14664, '归朝欢', '陈德武', '昨夜城头望牛斗。\n金气横空作龙吼。\n朝天尺一鹤飞书，尊前夺我龙头友。\n风流江左後。\n青毡旧物曾坚守。\n念侨居、淮阳九载，闲却丝纶手。\n花骢欲系无长柳。\n玉箸频挥翻短袖。\n凤凰台近月重圆，紫薇花暖香依旧。\n功名随分有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14665, '望海潮', '陈德武', '陵山载酒，泗河扬柁，尊前折尽将离。\n才试牛刀，俄惊凫舄，令人去後多思。\n休唱别离词。\n看玉函星铁，骑佩铜丝。\n丹凤鸣阳，碧梧栖尔最高枝。\n等闲展对声词。\n对一庭明月，千里邦畿。\n西涧家声，玉堂人物，夜窗梦果心期。\n才思浩无涯。\n若深航濂洛，峻驾峨眉。\n胸抱相思，银筝锦字莫教迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14666, '沁园春', '陈德武', '飞雨一番，杜宇数声，东君又回。\n对花垂粉泪，舟移洛甫，柳眉颦黛，马走章台。\n南架海棠，北窗红药，都是当年手自裁。\n伤离别，想今朝去也，明日重来。\n轩车且莫相催。\n待细把衷肠诉此怀。\n这画阑六曲，懒和月倚，朱帘十二，不与风开。\n青杏园林，朱樱酪酒，争似和羹雪後梅。\n那时节，好都将心事，分付多才。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14667, '庆春宫・高阳台', '陈德武', '风送深冬，雪消残腊，天时人事相催。\n堂北迎萱，水东问柳，阿谁报道春回。\n土牛装罢，候葭、先飞律灰。\n宜春宝字，是处人家，罗绮筵开。\n三年客里情怀。\n千里亲闱，一寸灵台。\n彩燕金钗，青丝生菜，还思纤手安排。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14668, '水调歌头', '陈德武', '日色隐花萼，清夜宴华晴。\n梁州新曲初就，锦瑟按银筝。\n中坐太真妃子，列坐亲封秦虢，歌笑尽倾城。\n百斛金尊倒，一醉玉山倾。\n扶上马，东小玉，右双成。\n绛纱笼烛高照，宫漏已三更。\n抱得禄儿归去，酒醒三郎何处，忽听鼓鼙惊。\n可惜马嵬恨，不得寄丹青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14669, '水龙吟', '陈德武', '花骢柳外频嘶，使君底事拼人去。\n圮桥风月，睢陵桃李，几回良遇。\n我待君来，他催君去，谁留君住。\n想尊空北海，诗成东阁，这都是、欢娱处。\n宝月才圆又缺，况人生、会难离易。\n驭风无计，缩地无术，问天无语。\n枯海为炉，赭山为炭，尽烧愁绪。\n把一心天地，一家南北，此身堪寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14670, '醉春风', '陈德武', '推枕床羞下。\n临鸾眉不画。\n妒深谁复白圭瑕。\n怕怕怕。\n飞燕班姬，昭君延寿，孰知淫雅。\n背倚荼縻架。\n泪满鲛绡帕。\n白头吟断怨琵琶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14671, '水调歌头', '陈德武', '好是三春景，都在百花轩。\n美人眠不成梦，早已绣帘掀。\n分付海棠睡足，检点牡丹开未，桃李寂无言。\n叶露联珠络，枝月坠金盆。\n树铃索，高障槛，补篱藩。\n丁宁莺燕蜂蝶，上下莫争翻。\n遥想韶光九十，只恐花飞一片，瘦减玉颜温。\n不惮银瓶冷，汲井沃芳根。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14672, '水调歌头', '陈德武', '三五嫦娥月，夜色正婵娟。\n自从窃药归去，天上几千年。\n试问广寒高处，为甚缺多圆少，此理孰为权。\n弦望知天定，离合可人怜。\n典宫锦，歌水调，载楼船。\n谪仙居士何在，月色尚依然。\n遥想人生百岁，三万六千良夜，能得几时圆。\n莫遣金盆落，达曙照无眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14673, '水调歌头', '陈德武', '莲衬凌波步，笋浴影娥东。\n晚妆脂粉犹腻，雪洁弄春溶。\n却似玉盘拈指，莫是金环脱腕，宝镜逐华容。\n好个明珠颗，落在掌窝中。\n可人意，拿不住，握还空。\n骑鲸便欲深取，恐触卧骊龙。\n奈玉春纤冻也，那壁团圆何处，有影却无踪。\n不上广寒殿，便入水晶宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14674, '水调歌头', '陈德武', '梦足芙蓉曙，步入牡丹丛。\n试将枝叶枚数，宠紫与娇红。\n如诉如歌体态，轻暖轻寒天气，春色把人烘。\n百斛沈檀味，两腋麝兰风。\n春衫透，罗袜沁，暗回中。\n芳心能有多少，一点束千里。\n只恐避丝行露，漫惹狂蜂轻蝶，珍重惜仪容。\n兰蕙修芳佩，苹藻荐公宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14675, '惜馀春慢・选冠子', '陈德武', '不语佳人，多才名友，天遣伴吾幽独。\n令姿潘岳，太素何郎，争似一丛红玉。\n谁为织云锦裳，天孙巧处，暗空机轴。\n别离间、陡觉春风一度，电光惊目。\n因念著、旧日欢娱，清平歌曲。\n板按玉人横竹。\n金盆月落，银烛纱笼，一刻千金难赎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14676, '浣溪沙', '陈德武', '庭院深沈绝俗埃。\n绿苔因雨上层阶。\n画帘低卷燕归来。\n月似有情中夜入，花何无语向人开。\n谩劳飞梦到天台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14677, '西江月', '陈德武', '时序去如流水，功名冷似寒灰。\n尽教江庾赋多才。\n一刻千金难买。\n客里月圆月缺，尊前花落花开。\n春来何处带愁来。\n春去此愁还在。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14678, '蝶恋花', '陈德武', '昨夜狂风今日雨。\n风雨相催，断送春归去。\n万计千方留不住。\n春归毕竟归何处。\n好鸟如歌花解舞。\n花鸟无情，也诉离愁苦。\n流水落花芳草渡。\n明年好记归时落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14679, '浣溪沙', '陈德武', '月落桐梢杜宇啼。\n云埋芳树鹧鸪飞。\n夜阑分作送春诗。\n山上安山经几载，口中添口又何时。\n相思一曲诉伊谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14680, '木兰花慢', '陈德武', '自东君别後，对花柳、愈无聊。\n但旅寓年年，梦添夜夜，饭减朝朝。\n应怜此情何似，却梅天、风雨正潇潇。\n奁玉有谁暖眼，带围漫自松腰。\n深沈庭院好香烧。\n水远玉人遥。\n念信阻鸾笺，调空绿绮，字满鲛绡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14681, '清平乐', '陈德武', '娥眉淡伫。\n未约心先许。\n坐待不来来又去。\n直到碧窗深处。\n雨云偏妒妖娇。\n几孤三五良宵。\n要见残妆新画，多应暮暮朝朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14682, '清平乐', '陈德武', '天孙自织。\n经纬天南北。\n明月楼台高百尺。\n玉手昔曾亲摘。\n种榆人去何年。\n乘槎偶认张骞。\n报道秋期近也，好将巧思相传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14683, '清平乐', '陈德武', '呼来吸去。\n毕竟为谁主。\n软力慢扶花柳舞。\n禁不住颠狂处。\n等闲天易凉炎。\n每教人爱人嫌。\n最是相思病起，呼儿紧下珠帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14684, '清平乐', '陈德武', '丝丝线线。\n惹起云根燕。\n万里江山春欲遍。\n多在梨花庭院。\n经旬一见通宵。\n恍如身在蓝桥。\n记与巫山神女，不禁暮暮朝朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14685, '清平乐', '陈德武', '随风情性。\n聚散元无定。\n雨过黄昏收拾尽。\n送出月明花影。\n谁言出岫无心。\n腾腾飞上巫岑。\n梦断不知何处，玉人鬓上斜簪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14686, '清平乐', '陈德武', '娇声娇语。\n却似深闺女。\n三叠琴心音一缕。\n躲在绿阴深处。\n此音宁与人知。\n此身不与人欺。\n薄暮背将斜月，噤声飞上高枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14687, '清平乐', '陈德武', '三三两两。\n夜夜教人想。\n偷入霜绡斜隙帐。\n直到珊瑚枕上。\n玉人梦绕江南。\n输他一饷肥甘。\n莫恨我心儿毒，只因你口儿馋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14688, '清平乐', '陈德武', '轻姿傅粉。\n学得偷香俊。\n百紫千红人未问。\n先与芳心折损。\n一生天赋风流。\n不知节去蜂愁。\n堪笑庄周老子，将身梦里追游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14689, '清平乐', '陈德武', '黄梅雨住。\n青草池塘暮。\n轻许天然乐两部。\n遥想周郎不顾。\n生憎利口喃喃。\n凭谁井塞泥缄。\n最是玉人枕上，几回梦断江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14690, '清平乐', '陈德武', '星星散散。\n绕地无人管。\n一点寒光虽有烂。\n飞不到河西畔。\n画堂花暗银。\n井阑添个双双。\n欲照相思两字，藉风扶过虚窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14691, '清平乐', '陈德武', '啾啾唧唧。\n夜夜鸣东壁。\n如诉如歌如涕泣。\n乱我离怀似织。\n画堂帘幕沈深。\n美人睡稳香衾。\n懒妇知眠到晓，尔虫枉自劳心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14692, '醉春风', '陈德武', '陌上轮蹄满。\n花间蜂蝶乱，画帘低卷对南山。\n□□□。\n轻暖轻寒，乍晴乍雨，风流云散。\n罗袖伤春晚。\n纨扇惊秋换。\n谁将白雪污青鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14693, '玉蝴蝶', '陈德武', '好是春光秋色，天工巧处，都上花枝。\n更值云情雨态，净沐芳姿。\n醉相扶、霓裳舞困，眠未得、宫锦淋漓。\n有谁知。\n眼空相对，心系相思。\n相思。\n鲛绡帕上，珠悬红泪，水洗胭脂。\n寂寞阑干，无言暗忆旧游时。\n五花骢、载将郎去，双喜鹊、报道郎归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14694, '千秋岁引', '陈德武', '濯锦丰姿，新凉台阁。\n懊悔巫云太轻薄。\n琵琶未诉衣衫湿，菱花不照胭脂落。\n凤凰池，鸳鸯殿，重金钥。\n春色画船何处泊。\n秋色丹青人难摸。\n可惜风流总闲却。\n此情不与人知道，知时只恐人挠著。\n碧窗前，银灯下，陪孤酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14695, '玉蝴蝶', '陈德武', '金井梧桐飞报，秋期近也，乌鹊成桥。\n为问双星何事，长待今宵。\n别今年、新歌暂展，更五鼓、旧恨重摇。\n黯魂销。\n两情脉脉，一水迢迢。\n寂寥。\n寄言儿女，纵能多巧笑，奚暇相调。\n暗想离愁，人间天上古来饶。\n但心坚、天长地久，何意在、雨暮云朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14696, '木兰花慢', '陈德武', '值升平海宇，又春色、与俱还。\n向杨柳楼台，海棠庭院，红药阑干。\n可人好风良月，都收拾入锦囊间。\n心事已超尘外，天公分付人间。\n世途陆海拥波澜。\n回首梦中看。\n想酒醒罗浮，云空巫峡，饭熟邯郸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14697, '水龙吟', '陈德武', '问津扬子江头，滔滔潮汐东流去。\n六朝文物，千年陈迹，几更乌兔。\n天限东南，水流今古，地分吴楚。\n喜壮游千里，桑弧蓬矢，功名事、儒生语。\n翘首石头城北，簇楼台、远连芳树。\n雪销天气，澄江如练，碧峰无数。\n银瓮春回，金山钟晓，梦闲鸥鹭。\n早归来，尽日风平人静，孤舟横渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14698, '望远行', '陈德武', '城头初鼓，天街上、渐渐行人声悄。\n半窗风月，一枕新凉，睡熟不知天晓。\n最是家山千里，远劳归梦，待说离情难觉。\n觉来时，帘外数声啼鸟。\n谁道。\n为甚新来消瘦，底事恹恹烦恼。\n不是悲花，非干病酒，有个离肠难扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14699, '满江红', '陈德武', '记当年时，离筵上、把梅花折。\n还经尽、江南烟雨，淮阳风雪。\n寒食清明都过了，看看又到端阳节。\n倚阑干、屈指数流光，经年别。\n心一寸、愁肠结。\n千里梦、三更月。\n□晓来寒透，不堪愁绝。\n羞见慈乌啼反哺，厌闲乳燕调新舌。\n睹禽物、愈觉倍伤情，归心切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14700, '惜馀春慢・选冠子', '陈德武', '阑葺疏芦，帘编小苇，好个清幽公馆。\n栽槐夹道，种菊盈轩，景物便堪咏玩。\n门外一番雨馀，嫩绿缘枝，浅清清眼。\n悄无人，一枕新凉睡觉，燕泥香暖。\n蓦地里、对景伤怀，思量无限。\n回首故园春远。\n松期竹待，壑诮林嘲，苦被浮名牵绊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14701, '忆秦娥', '陈德武', '疏帘揭。\n云端仰见娟娟月。\n娟娟月。\n不应何恨，照人离别。\n闭门独睡空愁绝。\n娥梦里低低说。\n低低说。\n悲欢离合，阴晴圆缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14702, '踏莎行', '陈德武', '雾失南楼，云低东阁。\n枝头不见南飞鹊。\n娥何事太多情，今宵故误年时约。\n天易阴晴，人多哀乐。\n从来此事难凭度。\n匆匆又是隔年期，且烧银烛酬高酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14703, '一翦梅', '陈德武', '新酒初香菊半含。\n月也三三。\n日也三三。\n登高已约上崭岩。\n世事相担。\n风雨相担。\n头上茱萸颠倒簪。\n身在河南。\n心在江南。\n渊明何日解征骖。\n俯也何惭。\n仰也何惭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14704, '鹧鸪天', '陈德武', '三径芳根自不群。\n每於霜後播清芳。\n枝头蛱蝶如羞见，篱外征鸿不可闻。\n情脉脉，思纷纷。\n绕窗吟咏理馀薰。\n卷帘人在西风里，知是新来瘦几分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14705, '踏莎行', '陈德武', '声迹随风，浪痕如霰。\n蓝桥路远无由见。\n黄昏肠断倚阑时，看看数尽南飞雁。\n日理丝机，宵拈针线。\n春秋不管莺和燕。\n欲将心事诉佳期，回文直上金銮殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14706, '踏莎行', '陈德武', '梅压宫妆，柳横眉黛。\n都将留得春光在。\n弄琴台上忽相逢，吹箫月下曾相待。\n海燕春归，江鸿秋迈。\n到头总是恩和爱。\n佳期约在白云间，一团和气春如海。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14707, '南浦', '张炎', '波暖绿粼粼，燕飞来、好是苏堤才晓。\n鱼没浪痕圆，流红去、翻笑东风难扫。\n荒桥断浦，柳阴撑出扁舟小。\n回首池塘青欲遍，绝似梦中芳草。\n和云流出空山，甚年年净洗，花香不了。\n新渌乍生时，孤村路、犹忆那回曾到。\n馀情渺渺。\n茂林觞咏如今悄。\n前度刘郎归去後，溪上碧桃多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14708, '高阳台', '张炎', '接叶巢莺，平波卷絮，断桥斜日归船。\n能几番游，看花又是明年。\n东风且伴蔷薇住，到蔷薇、春已堪怜。\n更凄然。\n万绿西泠，一抹荒烟。\n当年燕子知何处，但苔深韦曲，草暗斜川。\n见说新愁，如今也到鸥边。\n无心再续笙歌梦，掩重门、浅醉闲眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14709, '忆旧游', '张炎', '看方壶拥翠，太极垂光，积雪初晴。\n阊阖开黄道，正绿章封事，飞上层青。\n古台半压琪树，引袖拂寒星。\n见玉冷闲坡，金明邃宇，人住深清。\n幽寻。\n自来去，对华表千年，天籁无声。\n别有长生路，看花开花落，何处无春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14710, '凄凉犯', '张炎', '萧疏野柳嘶寒马，芦花深、还见游猎。\n山势北来，甚时曾到，醉魂飞越。\n酸风自咽。\n拥吟鼻、征衣暗裂。\n正凄迷，天涯羁旅，不似灞桥雪。\n谁念而今老，懒赋长杨，倦怀休说。\n空怜断梗梦依依，岁华轻别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14711, '壶中天・念奴娇', '张炎', '杨万里，笑当年底事，中分南北。\n须信平生无梦到，却向而今游历。\n老柳官河，斜阳古道，风定波犹直。\n野人惊问，泛槎何处狂客。\n迎面落叶萧萧，水流沙共远，都无行迹。\n衰草凄迷秋更绿，惟有闲鸥独立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14712, '声声慢', '张炎', '平沙催晓，野水惊寒，遥岑寸碧烟空。\n万里冰霜，一夜换却西风。\n晴梢渐无坠叶，撼秋声、都是梧桐。\n情正远，奈吟湘赋楚，近日偏慵。\n客里依然清事，爱窗深帐暖，戏拣香筒。\n片霎归程，无奈梦与心同。\n空教故林怨鹤，掩闲门、明月山中。\n春又小，甚梅花、犹自未逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14713, '绮罗香', '张炎', '候馆深灯，辽天断羽，近日音书疑绝。\n转眼伤心，慵看剩歌残阕。\n才忘了、还著思量，待去也、怎禁离别。\n恨只恨、桃叶空江，殷勤不似谢红叶。\n良宵谁念哽咽。\n对熏炉象尺、闲伴凄切。\n独立西风，犹忆旧家时节。\n随款步、花密藏春，听私语、柳疏嫌月。\n今休问，燕约莺期，梦游空趁蝶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14714, '庆春宫・高阳台', '张炎', '波荡兰觞，邻分杏酪，昼辉冉冉烘晴。\n索飞仙，戏船移景，薄游也自人。\n短桥虚市，听隔柳、谁家卖饧。\n月题争系，油壁相连，笑语逢迎。\n池亭小队秦筝。\n就地围香，临水湔裙。\n冶态飘云，醉妆扶玉，未应闲了芳情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14715, '国香', '张炎', '莺柳烟堤。\n记未吟青子，曾比红儿。\n娴娇弄春微透，鬟翠双垂。\n不道留仙不住，便无梦、吹到南枝。\n相看两流落，掩面凝羞，怕说当时。\n凄凉歌楚调，袅馀音不放，一朵云飞。\n丁香枝上，几度款语深期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14716, '水龙吟', '刘克庄', '不须更问旁人，劝君自拂青铜照。\n幅巾短褐，有些野逸，有些村拗。\n两度呼来，也曾批敕，也曾还诏。\n笑先生此手，今堪何用，苔矶上、堪垂钓。\n白雪新腔高妙。\n把侬家、调疏称道。\n六韬未试，抑诗未作，如何归老。\n玉带金貂，星儿快活，天来烦恼。\n待自笺年甲，缴还官职，换山翁号。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14717, '水龙吟', '刘克庄', '行藏自决於心，不消谋及门前客。\n平生慕用，著书玄晏，挂冠贞白。\n帝奖孤高，别加九锡，一筇双屐。\n更赐之车服，胙之茅土，依稀在、槐安国。\n频领竹宫清职。\n仰飞仙、犹龙无迹。\n与谁同去，挑包徐甲，负辕班特。\n蹉过明师，且寻狎友，杜康仪狄。\n笑谢公旷达，暮年垂泪，听桓郎笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14718, '水龙吟', '刘克庄', '先生避谤山栖，戒门不纳高轩客。\n谁欤来者，吟诗张碧，诙谐侯白。\n礼数由他，谢郎著帽，王郎穿屐。\n且问花随柳，举杯邀月，那须预、人家国。\n香案旁边供职。\n鸟飞空、何曾留迹。\n翁铁汉，两贤安在，百夫之特。\n但愿王师，早俘颉利，早禽长狄。\n便太平无事，卖薪沽酒，骑牛腰笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14719, '水龙吟', '刘克庄', '当年玉立清扬，屋梁落月偏相照。\n而今衰飒，形骸百丑，情怀十拗。\n久已饰巾、尚堪扶杖，听山东诏。\n尽後车载汝，营丘封汝，何必在、溪钓。\n晚悟儋书玄妙。\n懒从他、锺离传道。\n不论资望推排，也做五更三老。\n宋玉多悲，唐衢喜哭，好闲烦恼。\n问天公，扑断散人二字，赐龟蒙号。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14720, '水龙吟', '刘克庄', '此翁饱阅人间，三生似是刘宾客。\n若论辈行，早陪韩柳，晚交元白。\n老矣安能，为人取履，与人争屐。\n叹酒泉郡远，醉乡路绝，今何处、堪开国。\n解去冰衔华职。\n遍空山、难寻行迹。\n道旁喘月，田间卧草，也胜郊特。\n宰相□□，周公留召，娄公容狄。\n喜时平身健，三行社饮，一声樵笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14721, '水龙吟', '刘克庄', '病夫鬓秃颜苍，不堪持向清溪照。\n一生枘凿，壮夫懦，通人嫌拗。\n让当行家，勒浯西颂，草淮南诏。\n幸脱离沮洳，浮游江海，悠然逝、毋吞钓。\n宴坐蒲团观妙。\n怪痴儿、舂粮求道。\n古人尚齿，迎他商皓，拜他庞老。\n鸠杖蒲轮，把身束缚，替人愁恼。\n煞为僧不了，下梢犹要，紫衣师号。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14722, '水龙吟', '刘克庄', '斋不是凡人，海山仙圣知来处。\n清英融结，佩瑶台月，饮金茎露。\n翰墨流行，禁中有本，御前停箸。\n向弘文馆里，薰风殿上，亲属和、微凉句。\n已被昭阳人妒。\n更那堪、鼎成龙去。\n曾传宝苑，曾将玉杵，付长生兔。\n地覆天翻，河清海浅，朱颜常驻。\n算给扶朝者，临雍拜者，下梢须做。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14723, '水龙吟', '刘克庄', '此翁幸自偏盲，那堪右目生微翳。\n羽流禳谢，缁郎忏悔，天乎无罪。\n客曰不然，也因口腹，也因瞻视。\n汝夜披黄卷，日餐丹荔，贻伊戚、将谁怼。\n长智都缘更事。\n尽今生、十分珍卫。\n暮年怕杀，汗青蠹简，擘红高会。\n也莫贪他，君谟旧谱，子云奇字。\n特邀张司业，看花题竹，韩家园内。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14724, '风流子', '刘克庄', '松桂各参天。\n石桥下，新种一池莲。\n似仙子御风，来从姑射，地灵献宝，产向蓝田。\n曾入先生虚白屋，不喜傅朱铅。\n记茂叔溪头，深衣听讲，远公社里，素衲安禅。\n山间。\n多红鹤，端相久，蓦地飞去蹁跹。\n但蝶戏鹭翘，有时偷近旁边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14725, '满庭芳', '刘克庄', '凉月如冰，素涛翻雪，人世依约三更。\n扁舟乘兴，莫计水云程。\n忽到一洲奇绝，花无数、多不知名。\n浑疑是，芙蓉城里，又似牡丹坪。\n蓬莱，应不远，天风海浪，满目凄清。\n更一声铁笛，石裂龙惊。\n回顾尘寰局促，挥袂去、散发骑鲸。\n蘧蘧觉，元来是梦，钟动野鸡鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14726, '贺新郎', '刘克庄', '吾少多奇节。\n颇揶揄、玉关定远，壶头新息。\n一剑防身行万里，选甚南溟北极。\n看塞雁、衔来秋色。\n不但槊棋夸妙手，管城君、亦自无敌。\n终贾辈，恐难匹。\n酒肠诗胆新来窄。\n向西风、登高望远，乱山斜日。\n安得良弓并快马，聊与诸公角力。\n漫醉把、栏干频拍。\n莫恨寒蟾离海晚，待与君、秉烛游今夕。\n欢易买，健难得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14727, '贺新郎', '刘克庄', '北望神州路。\n试平章、这场公事，怎生分付。\n记得太行山百万，曾入宗爷驾驭。\n今把作、握蛇骑虎。\n君去京东豪杰喜，想投戈、下拜真吾父。\n谈笑里，定齐鲁。\n两河萧瑟惟狐兔。\n问当年、祖生去後，有人来否。\n多少新亭挥泪客，谁梦中原块土。\n算事业、须由人做。\n应笑书生心胆怯，向车中、闭置如新妇。\n空目送，塞鸿去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14728, '贺新郎', '刘克庄', '尽说番和汉。\n这琵琶、依稀似曲，蓦然弦断。\n作麽一年来一度，欺得南人技短。\n叹几处、城危如卵。\n元凯後身居玉帐，报胡儿、休作寻常看。\n布严令，运奇算。\n开门决斗雌雄判。\n笑中宵、奚车毡屋，兽惊禽散。\n个个巍冠横尘柄，谁了君王此段。\n也莫靠、长江能限。\n不论周郎并幼度，便仲尼、复起嗟微管。\n驰露布，筑京观。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14729, '贺新郎', '刘克庄', '宣引东华去。\n似当年、文皇亲擢，马周徒步。\n殿上风霜生白简，下殿扁舟已具。\n怎不与、官家留住。\n古有一言腰相印，谁教他、满箧婴鳞疏。\n还笏退，不回顾。\n新来边报犹飞羽。\n问诸公、可无长策，少宽明主。\n攀槛朱云头雪白，流落如今底处。\n但一片、丹心如故。\n赖有越台堪眺望，那中原、莫已平安否。\n风色恶，海天暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14730, '贺新郎', '刘克庄', '驿骑联翩至。\n道台家、筹边方急，酒行姑止。\n作麽携将琴鹤去，不管州人堕泪。\n富与贵、平生无味。\n可但红尘难著脚，便山林、未有安身地。\n搔白发，兀相对。\n前身小范疑公是。\n忆当年、天章阁上，建明尤伟。\n庆历诸贤方得路，便不容他老子。\n须著放、延州城里。\n一句殷勤牢记取，在朝廷、最好图西事。\n何必向，玉关外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14731, '贺新郎', '刘克庄', '飞诏从天下。\n道中朝、名流欲尽，君王思贾。\n时事祗今堪痛哭，未可徐徐俟驾。\n好著手、扶将宗社。\n多少法筵龙象众，听灵山、属付些儿话。\n千百世，要传写。\n子方行矣乘骢马。\n又送他、江南太史，去游毡厦。\n老我伴身惟有影，倚遍风轩月榭。\n怅玉手、何时重把。\n君向柳边花底问，看贞元、朝士谁存者。\n桃满观，几开谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14732, '贺新郎', '刘克庄', '南国秋容晚。\n晓寒轻、菊花台榭，拒霜池馆。\n试向壶山堂上望，万顷黄云刈遍。\n总吃著、君侯方寸。\n不要汉廷夸击断，要史家、编入循良传。\n春脚到，福星见。\n家家香火人人愿。\n要还他、庆元狨座，建炎蝉冕。\n稳奉安舆迎两国，谁谓山遥水远。\n福寿比、河沙难算。\n来岁而今黄花节，早骖鸾、入侍瑶池宴。\n风浩荡，海清浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14733, '贺新郎', '刘克庄', '深院榴花吐。\n画帘开、衣纨扇，午风清暑。\n儿女纷纷夸结束，新样钗符艾虎。\n早已有、游人观渡。\n老大逢场慵作戏，任陌头、年少争旗鼓。\n溪雨急，浪花舞。\n灵均标致高如许。\n忆生平、既纫兰佩，更怀椒糈。\n谁信骚魂千载後，波底垂涎角黍。\n又说是、蛟馋龙怒。\n把似而今醒到了，料当年、醉死差无苦。\n聊一笑，吊千古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14734, '贺新郎', '刘克庄', '湛湛长空黑。\n更那堪、斜风细雨，乱愁如织。\n老眼平生空四海，赖有高楼百尺。\n看浩荡、千崖秋色。\n白发书生神州泪，尽凄凉、不向牛山滴。\n追往事，去无迹。\n少年自负凌云笔。\n到而今、春华落尽，满怀萧瑟。\n常恨世人新意少，爱说南朝狂客。\n把破帽、年年拈出。\n若对黄花孤负酒，怕黄花、也笑人岑寂。\n鸿北去，日西匿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14735, '贺新郎', '刘克庄', '绝顶规危榭。\n跨高寒、鸟飞不过，云生其下。\n斤无声人按堵，翕青红变化。\n览城郭、山川如画。\n阁老凤楼修造手，笑谈间、突出凌云厦。\n台上景，买无价。\n唾壶麈尾登临暇。\n似当年、滁阳太守，欧阳公也。\n倾倒赣江供砚滴，判断雪天月夜。\n更唤取、邹枚司马。\n铜雀凌歌舞散，访残砖、断甓无存者。\n馀翰墨，被风雅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14736, '贺新郎', '刘克庄', '动地东风起。\n画桥西、绕溪桑柘，漫山桃李。\n寂寂墙阴苍苔径，犹印前回屐齿。\n惊岁月、飙驰云驶。\n太息攀翻长亭树，是先生、手种今如此。\n君不乐，欲何俟。\n傍人错会渊明意。\n笑斯翁、皇皇汲汲，登山临水。\n佳处径呼篮舆去，彷佛柴桑栗里。\n从我者、门生儿子。\n尝试平章先贤传，屈原醒、不似刘伶醉。\n拼酩酊，卧花底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14737, '贺新郎', '刘克庄', '鹊报千林喜。\n还猛省、谢家池馆，早寒天气。\n要与瑶姬叙离索，草草杯盘藉地。\n怅减尽、何郎才思。\n不愿玉堂并金屋，愿年年、岁岁花间醉。\n餐秀色，挹高致。\n西园飞盖东山妓。\n问何如、半山雪里，孤山烟外。\n管甚夜深风露冷，人与长瓶共睡。\n任翠羽、枝头多事。\n老子平生无他过，为梅花、受取风流罪。\n簪白发，莫教坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14738, '贺新郎', '刘克庄', '溪上收残雨。\n倚画栏、薄绵乍脱，日阴亭午。\n闹市不知春色处，散在荒园废墅。\n渐小白、长红无数。\n客子虽非河阳令，也随缘、暂作莺花主。\n那可负，瓮中醑。\n碧云四合千岩暮。\n恨匆匆、余方有事，子姑归去。\n趁取群芳未摇落，暇日提鱼就煮。\n叹激电、光阴如许。\n回首明年何处在，问桃花、尚记刘郎否。\n公莫笑，醉中语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14739, '贺新郎', '刘克庄', '曾与瑶姬约。\n恍相逢、翠裳摇曳，珠联络。\n风露青冥非人世，揽结玉龙骖鹤。\n爱万朵、千条纤弱。\n祷祝花神怜惜取，问开时、晴雨须斟酌。\n枝上雪，莫消却。\n恼人匹似中狂药。\n凭危栏、烛光交映，乐声遥作。\n身上春衫香薰透，看到参横月落。\n算茉莉、犹低一著。\n坐有缑山王郎子，倚玉箫、度曲难为酢。\n君不饮，铸成错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14740, '贺新郎', '刘克庄', '想赴瑶池约。\n向东风、名姬骏马，翠鞯金络。\n太液池边鹄群下，又似南楼呼鹤。\n画不就、纤娇弱。\n罗帕封香来天上，泻铜盘、沆瀣供清酌。\n春去也，被留却。\n芳魂再返应无药。\n似诗咏、绿衣黄里，感伤而作。\n爱惜尚嫌蜂采去，何况流莺蹴落。\n且放下、珠帘遮著。\n除却江南黄九外，有何人、敢与花酬酢。\n君认取，莫教错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14741, '贺新郎', '刘克庄', '浅把宫黄约。\n细端相、普陀烟里，金身珠络。\n萼绿华轻罗袜小，飞下祥云仙鹤。\n朵朵赛、蜂腰纤弱。\n已被色香撩病思，尽鹅儿、酒美无多酌。\n看不足，怕残却。\n人间难得伤春药。\n更枝头、流莺呼起，少年狂作。\n留取姚家花相伴，羞与万红同落。\n未肯让、蜡梅先著。\n乐府今无黄绢手，问斯人、清唱何人酢。\n休草草，认题错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14742, '贺新郎', '刘克庄', '一梦扬州事。\n画堂深、金瓶万朵，元戎高会。\n座上祥云层层起，不减洛中姚魏。\n叹别後、关山迢递。\n国色天香何处在，想东风、犹忆狂书记。\n惊岁月，一弹指。\n数枝清晓烦驰骑。\n向小窗、依稀重见，芜城妖丽。\n料得花怜侬消瘦，侬亦怜花憔悴。\n漫怅望、竹西歌吹。\n老矣应无骑鹤日，但春衫、点点当时泪。\n那更有，旧情味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14743, '贺新郎', '刘克庄', '草草池亭宴。\n又何须、珠络臂，琵琶遮面。\n宾主一时词翰手，倏忽龙蛇满案。\n传写处、尘飞莺啭。\n但得时平鱼稻熟，这腐儒、不用青精饭。\n阴雾扫，霁华见。\n使君偿了丰年愿。\n便从今、也无敲扑，也无厨传。\n试拂笼纱看壁记，几个标名渠观。\n想九牧、闻风争羡。\n此老饱知民疾苦，早归来、载笔薰风殿。\n诗有讽，赋无劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14744, '贺新郎', '刘克庄', '梦断钧天宴。\n怪人间、曲吹别调，局翻新面。\n不是先生喑哑了，怕杀乌台旧案。\n但掩耳、蝉嘶禽啭。\n老去把茅依地主，有瓦盆盛酒荷包饭。\n停造请、免朝见。\n少狂误发功名愿。\n苦贪他、生前死後，美官佳传。\n白发归来还自笑，管辖希夷古观。\n看一道、冰衔堪羡。\n妃子将军未已，问匡山、何似金銮殿。\n休更待，杜鹃劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14745, '贺新郎', '刘克庄', '风露驱炎毒。\n记仙翁、飘然谪堕，吹笙骑鹄。\n历历汉初秦季事，山下瓜犹未熟。\n过眼见、群雄分鹿。\n想得拂衣游汗漫，试回头、刘项俱蛮触。\n斫鲸脍，脯麟肉。\n越人好事因成俗。\n拥遨头、如云士女，山南山北。\n问讯先生无恙否，齐鲁干戈满目。\n且游戏、扶胥黄木。\n不是世无瓜样枣，便有来、肯饱痴儿腹。\n聊举酒，笑相属。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14746, '贺新郎', '刘克庄', '此腹元空洞。\n少年时、诸公过矣，上天吹送。\n老大被他禁害杀，身与浮名孰重。\n这鼓笛、休休拈弄。\n彩笔掷还残锦去，愿今生、来世无妖梦。\n且饭犊，莫吞凤。\n新来喑哑如翁仲。\n羡王郎、骖鸾缥缈，玉箫吹动。\n应笑夔州村里女，灸面生愁进奉。\n要绝代、倾城安用。\n今古何人知此理，有吾家、酒德先生颂。\n三万卷，漫充栋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14747, '贺新郎', '刘克庄', '主判茅君洞。\n有檐间、查查喜鹊，晓来传送。\n几度黄符披戴了，此度君恩越重。\n被贺监、天随调弄。\n做取散人千百岁，笑渠侬、一霎邯郸梦。\n歌而过，凤兮凤。\n灌园织屦希陈仲。\n问先生、加齐卿相，可无心动。\n除却醴泉中太乙，拣个名山自奉。\n那捷径、输他藏用。\n有耳不曾闻黜陟，免教人、贬驳徂徕颂。\n服兰佩，结茅栋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14748, '贺新郎', '刘克庄', '谪下神清洞。\n更遭他、揶揄黠鬼，路旁遮送。\n薄命书生鸡肋尔，却笑尊拳忒重。\n破故纸、谁教翻弄。\n一枕茅檐春睡美，便周公、大圣何须梦。\n门前客，任题凤。\n卜邻羊仲并求仲。\n愿春来、西畴雨足，土膏犁动。\n白发巡官占岁稔，不问京房翼奉。\n槔与瓮、从今无用。\n醉与老农同击壤，莫随人、投献嘉禾颂。\n在陋巷，胜华栋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14749, '贺新郎', '刘克庄', '妾出於微贱。\n小年时、朱弦弹绝，玉笙吹遍。\n粗识国风关雎乱，羞学流莺百啭。\n总不涉、闺情春怨。\n谁向西邻公子说，要珠鞍、迎入梨花院。\n身未动，意先懒。\n主家十二楼连苑。\n那人人、靓妆按曲，绣帘初卷。\n道是华堂箫管唱，笑杀鸡坊拍衮。\n回首望、侯门天远。\n我有平生离鸾操，颇哀而不愠微而婉。\n聊一奏，更三叹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14750, '贺新郎', '刘克庄', '鬓雪今千缕。\n更休休、痴心呆望，故人明主。\n晚学瞿聃无所得，不解飞升灭度。\n似晓鼓、冬冬挝五。\n散尽朝来汤饼客，且烹鸡、要饭茅容母。\n怕回首，太行路。\n麟台学士微云句。\n便樽前、周郎复出，审音无误。\n安得春莺雪儿辈，轻拍红牙按舞。\n也莫笑、侬家蛮语。\n老去山歌尤协律，又何须、手笔如燕许。\n援琴操，促筝柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14751, '贺新郎', '刘克庄', '放逐身蓝缕。\n被门前、群鸥戏狎，见推盟主。\n若把士师三黜比，老子多他两度。\n袖手看、名场呼五。\n不会车边望尘拜，免他年、青史羞潘母。\n句曲洞，是归路。\n平生怕道萧萧句。\n况新来、冠弁侧，醉人多误。\n管甚是非并礼法，顿足低昂起舞。\n任百鸟、喧啾春语。\n欲托朱弦写悲壮，这琴心、脉脉谁堪许。\n君按拍，我调柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14752, '贺新郎', '刘克庄', '国脉微如缕。\n问长缨、何时入手，缚将戎主。\n未必人间无好汉，谁与宽些尺度。\n试看取、当年韩五。\n岂有谷城公付授，也不干、曾遇骊山母。\n谈笑起，两河路。\n少时棋柝曾联句。\n叹而今、登楼揽镜，事机频误。\n闻说北风吹面急，边上冲梯屡舞。\n君莫道、投鞭虚语。\n自古一贤能制难，有金汤、便可无张许。\n快投笔，莫题柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14753, '贺新郎', '刘克庄', '万字如针缕。\n忆王郎、丹墀大对，气为文主。\n贵近旁观俱失色，仰止如天圣度。\n笑杜牧、成名居五。\n晚面清光犹苦谏，似封人、恳切言君母。\n谪尘世，错行路。\n当时宜和薰风句。\n又那知、青云一跌，被才名误。\n输与灵和殿前柳，柔软随风学舞。\n怪两鸟、新来停语。\n不是先生高索价，问何时、宰相先生许。\n举杯祝，莫倾柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14754, '贺新郎', '刘克庄', '身畔无丝缕。\n但从前、裳练，做他家主。\n甲子一周加二纪，兔走乌飞几度。\n赛孔子、如来三五。\n鹤发萧萧无可截，要一杯、留客惭陶母。\n门外草，欲迷路。\n朗吟白雪阳春句。\n待夫君、骊驹不至，鹊声还误。\n老去聊攀莱子例，倒著斑衣戏舞。\n记田舍、火炉头语。\n肘後黄金腰下印，有高堂、未敢将身许。\n且扇枕，莫倚柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14755, '贺新郎', '刘克庄', '辇路东风里。\n试回头、金闺昨梦，侵寻三纪。\n岁晚岿然灵光殿，仆与君侯而已。\n漫过眼、几番桃李。\n珠履金钗常满座，问谁人、得似张公子。\n驰骥，佩龟紫。\n宿云收尽檐声止。\n玳筵开、高台风月，後堂罗绮。\n恰近洛人修禊节，莫惜飞觞临水。\n怕则怕、追锋徵起。\n此老一生江海客，愿风云、际会从今始。\n宁郁郁，久居此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14756, '贺新郎', '刘克庄', '老去光阴驶。\n向西风、疏林变缬，残霞成绮。\n尚喜暮年腰脚健，不碍登山临水。\n算自古、英游能几。\n客与桓公俱臭腐，独流传、吹帽狂生尔。\n後来者，亦犹此。\n篮舆伊轧柴桑里。\n问黄花、没些消息，空篱而已。\n赖有一般芙蓉月，偏照先生怀里。\n且觅个、栏干同倚。\n检点樽前谁见在，忆平生、共插茱萸底。\n欢未足，饮姑止。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14757, '贺新郎', '刘克庄', '忆昔俱年少。\n向斯晨、登高怀古，赋诗舒啸。\n追数樽前插花客，人物并皆佳妙。\n禁几度、西风残照。\n元子寄奴曾富贵，到而今、一一消磨了。\n君不乐，後人笑。\n山南山北添华表。\n叹归来、谢池草合，黄台瓜少。\n老去爱持齐物论，谁管彭殇寿夭。\n待细说、教天知道。\n不羡两苏并二宋，愿弟兄、岁岁同吹帽。\n杯到手，莫辞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14758, '贺新郎', '刘克庄', '何必游嵩少。\n屋边山、松风浩荡，虎龙吟啸。\n旧效楚人悲秋作，晚爱陶诗高妙。\n发如此、临流羞照。\n屈指向来夸毗子，被西风、一笔都勾了。\n曾不满，达人笑。\n当年玉振於江表。\n怅而今、老身空在，欢娱全少。\n假使真如彭祖寿，蒙叟犹嗤渠夭。\n偶落笔、不经人道。\n岁晚连床谈至晓，胜冈头、出没看乌帽。\n君举白，我频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14759, '贺新郎', '刘克庄', '人老难重少。\n强追陪、李侯痛饮，刘郎清啸。\n报答秋光无一字，虚说君房语妙。\n且匣起、青铜休照。\n赖有多情篱下菊，待西风、不肯先开了。\n留晚节，发孤笑。\n孔璋客绍衡依表。\n有谁怜、戴花翁病，插萸人少。\n生不逢场闲则剧，年似龚生犹夭。\n吃紧处、无人曾道。\n到得扶他迂叟出，算貂蝉、未抵深衣帽。\n街酒贱，更沽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14760, '贺新郎', '刘克庄', '犹记臣之少。\n兴狂时、过陈遵饮，对孙登啸。\n岁晚登临多感慨，但觉齐山诗妙。\n任蓉月、柳风吹照。\n金印不来丹飞去，拟神仙、富贵都差了。\n空铸错，与人笑。\n九年前拜悬车表。\n试回看、柴桑菊老，玄都花少。\n周也曾言殇子寿，佛以白头为夭。\n末後句、岩头曾道。\n头似秃巾裹懒，最不宜蝉冕宜僧帽。\n杯中物，直须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14761, '贺新郎', '刘克庄', '行乐尤宜少。\n忆坡公、洞箫听罢，划然长啸。\n四海共知霜鬓满，莫问近来何妙。\n也不记、金莲曾照。\n老没太官糕酒分，把茱萸、便准登高了。\n齐得丧，等嘻笑。\n集无韩子潮州表。\n数当时、南迁者众，北归人少。\n赤壁玉堂均一梦，此岂蛮烟能夭。\n与同叔、俱尝知道。\n谁向进贤冠底说，画出来、不似眉山帽。\n秋菊盏，献公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14762, '贺新郎', '刘克庄', '鹏赋年犹少。\n晚飘蓬、夜郎秋浦，渔歌猿啸。\n骏马名姬俱散去，参透南华微妙。\n敛万丈、光芒回照。\n妃子将军个甚，老先生、拂袖金闺了。\n供玉齿，粲然笑。\n解骖赖有汾阳老。\n叹今人、布衣交薄，绨袍情少。\n黄祖斗筲何足算，鹦鹉才高命夭。\n与贺监、其归同道。\n脱下锦袍与呆底，谪仙人、白伫乌纱帽。\n邀素月，入杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14763, '贺新郎', '刘克庄', '低局从头错。\n解危机、除非唤取，国棋来著。\n不信胡儿能胆大，南岸安他阵脚。\n谈笑里、乌巢空幕。\n西起岷峨东海岱，有捷旗、露布无宵柝。\n莘渭後，到秋壑。\n淮田犁遍吴田荻。\n问台家、山河宇宙，是谁擎托。\n自觉怀中残锦尽，采色彰施技薄。\n视柳雅、韩碑瞠若。\n稽首鲁公黄发颂，世何人、堪继奚斯作。\n楚狂语，莫删却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14764, '贺新郎', '刘克庄', '宿雨轻飘洒。\n少年时、追欢记节，同人于野。\n老去登临无脚力，徙倚屋东篱榭。\n但极目、海山如画。\n千古惟传吹帽汉，大将军、野马尘埃也。\n须彩笔，为陶写。\n鹤归旧里空悲咤。\n叹原头、累累高冢，洛英凋谢。\n留得香山病居士，却入渔翁保社。\n怅谁伴、先生情话。\n樽有葡萄簪有菊，西凉州、不似东篱下。\n休唤醒，利名者。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14765, '贺新郎', '刘克庄', '拂袖归来也。\n懒追陪、竹林嵇阮，兰亭王谢。\n谁与此翁相暖热，赖有平生伯雅。\n且放意、高吟闲话。\n山鸟山花皆上客，又何须、胜似公荣者。\n胸磊块，总浇下。\n盘龙痴绝求鹅炙。\n这先生、黄齑瓮熟，味珍无价。\n酒颂一篇差要妙，庄列诸书土苴。\n任礼法、中人嘲骂。\n君特未知其趣耳，若还知、火急来投社。\n共秉烛，惜今夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14766, '贺新郎', '刘克庄', '过眼光阴驶。\n忆垂髫、留连节物，逢场游戏。\n初试衣弄纨扇，斗采菖蒲涧里。\n今发白、颜苍如此。\n艾子萧郎方用事，怪先生、苦死纫兰芷。\n君不乐，欲何俟。\n头标夺得群儿喜。\n向溪边、旁观助噪，叹吾衰矣。\n欲建鼓旗无气力，唤起龙泉改委。\n但酒户、加封而已。\n晚觉醉乡差快活，那独醒、公子真呆底。\n聊洗净，笛筝耳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14767, '贺新郎', '刘克庄', '家有仙禽二。\n早追随、先生杖屦，互乡童子。\n旦旦池边三薰沐，夜夜山中警睡。\n且伴我、人间游戏。\n此老生平哀大陆，到末梢、始忆华亭唳。\n评往事，败佳思。\n古云鹤算谁能纪。\n叹归来、山川如故，人民非是。\n但愿主君高飞去，莫爱乘轩禄位。\n更赛过、令威千岁。\n假使焦山真羽化，待华阳贞逸铭方瘗。\n我拍手，渠展翅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14768, '洞仙歌', '刘克庄', '上林全树，曾借君栖宿。\n朝过瑶台暮群玉。\n忽翩然、脱下宫锦袍来，□□□，却向齐州受。\n等闲挥醉笔，咳唾千篇，长与诗家窃膏馥。\n身是酒星文星，刚被诗人，□唤做、禁中颇牧。\n便散发、骑鲸去何妨，从我者谁欤，安期徐福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14769, '洞仙歌', '刘克庄', '眇难揽镜，跛尤难穿履。\n赖有胡公菊潭水。\n信医言、断了重碧轻红，禁害杀，不遣高吟大醉。\n古来稀七十，添许多年，赢得笺天致君事。\n莫问客去门前，金尽床头，留宝扇、御诗珍秘。\n畴昔慕、乖崖老尚书，到晚节依稀，有些儿似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14770, '八声甘州', '刘克庄', '物微生处远，往还来、非但稻粱求。\n似爱长安日，怕阴山雪，善自为谋。\n个里幸无鸣镝，随意占沙洲。\n归兴何妨待，风景和柔。\n昔到衡阳回去，今随阳避地，遍海南头。\n与西川流寓，彼此各淹留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14771, '烛影摇红', '刘克庄', '拙者平生，不曾乞得天孙巧。\n那回忝扈属车来，岂是齐卿小。\n此膝不曾屈了。\n更休文、腰难运掉。\n前贤样子，表圣宜休，申公告老。\n凉簟安眠，绝胜直铃声搅。\n集中大半是诗词，幸没潮州表。\n月夕花朝咏啸。\n叹人间、愁多乐少。\n蓬莱有路，办个船儿，逆风也到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14772, '祝英台近', '刘克庄', '雨凄迷，风料峭。\n情绪被花恼。\n白白红红，满地无人扫。\n可堪解佩盟寒，坠楼命薄，更杜宇、枝头闲。\n绿阴绕。\n青帝结束匆匆，转眼朱明了。\n怕与春辞，茗玉山倒。\n後期觉做明年，春年年好，却不道、明年人老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14773, '最高楼', '刘克庄', '南岳後，累任作祠官。\n试说与君看。\n仙都玉局才交卸，新衔又管华州山。\n怪先生，吟胆壮，饮肠宽。\n去岁拥、旌旗称太守。\n今岁带、称漫叟。\n慵入闹，惯投闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14774, '最高楼', '刘克庄', '周郎後，直数到清真。\n君莫是前身。\n八音相应谐韶乐，一声未了落梁尘。\n笑而今，轻郢客，重巴人。\n只少个、绿珠横玉笛。\n更少个、雪儿弹锦瑟。\n欺贺晏，压黄秦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14775, '最高楼', '刘克庄', '吾衰矣，百事且随缘。\n只字不笺天。\n几曾三宿为归计，更巴一岁是希年。\n记儿时，闻祖父，说隆乾。\n我不与、少年争遇合。\n你莫共、老僧争戒腊。\n靴皱面，垂肩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14776, '最高楼', '刘克庄', '吾衰矣，不慕勒燕然。\n不爱画凌烟。\n此生惭愧支离叟，何功消受水衡钱。\n错教人，占卦气，算流年。\n漫摘取、野花簪一朵。\n更拣取、小词填一个。\n素发、暖丹田。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14777, '最高楼', '刘克庄', '辛亥後，六请挂衣冠。\n甲子始休官。\n白驹恰则来空谷，青牛早已出函关。\n笑狂生，还笏易，上竿难。\n也莫爱、宫中请内相。\n也莫爱、堂中呼六丈。\n但祷祝，要痴顽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14778, '最高楼', '刘克庄', '臣少也，豪举泛星槎。\n飘逸吐天葩。\n穆陵误奖推儒宿，龙泉曾唤做行家。\n今耄矣，文跌宕，字麻茶。\n同队者、多为公与相。\n广坐里、都无兄与丈。\n生有限，望犹奢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14779, '最高楼', '刘克庄', '金闺彦，荷蒉过山前。\n把钓坐溪边。\n呼来每得天颜笑，放归犹作地行仙。\n尽教人，避俗，谤逃禅。\n且缄了、淳夫三味口。\n更袖了、坡公三制手。\n宁殿後，不争先。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14780, '风入松', '刘克庄', '橐泉梦断夜初长。\n别馆凄凉。\n细思二十年前事，叹人琴、已矣俱亡。\n改尽潘郎鬓发，消残荀令衣香。\n多年布被冷如霜。\n到处同床。\n箫声一去无消息，但回首、天海茫茫。\n旧日风烟草树，而今总断人肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14781, '风入松', '刘克庄', '归鞍尚欲小徘徊。\n逆境难排。\n人言酒是消忧物，奈病馀、孤负金。\n萧瑟捣衣时候，凄凉鼓缶情怀。\n远林摇落晚风哀。\n野店犹开。\n多情惟是灯前影，伴此翁、同去同来。\n逆旅主人相问，今回老似前回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14782, '风入松', '刘克庄', '残更难睚抵年长。\n晓月凄凉。\n芙蓉院落深深闭，叹芳卿、今在今亡。\n绝笔无求凰曲，痴心有返魂香。\n起来休镊鬓边霜。\n半被堆床。\n定归兜率蓬莱去，奈人间、无路茫茫。\n缘断漫三弹指，忧来欲九回肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14783, '风入松', '刘克庄', '攀翻宰树暂徘徊。\n草草安排。\n昔人徒步陈鸡絮，愧公家、仆马觥。\n华表旧愁满目，黄粱残梦伤怀。\n欲将庄列等欢哀。\n对卷慵开。\n凭高指点虚无路，问何年、辽鹤归来。\n宿酒得风渐解，小舆待月同回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14784, '临江仙', '刘克庄', '玉笛钿车当日事，东涂西抹都曾。\n等闲曲子压和凝。\n纵游非草草，已醉强惺惺。\n今向三家村送老，身如罢讲吴僧。\n高楼百尺不须登。\n半炉烧叶火，一盏勘书灯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14785, '临江仙', '刘克庄', '落魄长官江海客，少豪万里寻春。\n而今樵悴向溪滨。\n断无觞咏兴，惟有簿书尘。\n手插海棠三百本，等闲妆点芳辰。\n他年绛雪映红云。\n丁宁风与月，记取种花人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14786, '临江仙', '刘克庄', '去岁越王台上饮，席间二客如龙。\n凭高吊古壮怀同。\n马嘶千嶂暮，乐奏半天中。\n今岁三家村市里，故人各自西东。\n菊花时节酒樽空。\n可怜双雪鬓，禁得几秋风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14787, '临江仙', '刘克庄', '不见仙湖能几日，尘沙变尽形容。\n夜来月冷露华浓。\n都忘茅屋下，但记画船中。\n两岸绿阴犹未合，更须补竹添松。\n最怜几树木芙蓉。\n手栽才数尺，别後为谁红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14788, '浪淘沙', '刘克庄', '去岁诣公车。\n天语勤渠。\n绛纱玉斧照寒儒。\n恰似昔人曾梦到，帝所清都。\n骨相太清。\n谪堕须臾。\n今年黄敕换称呼。\n只为此翁霜鬓秃，老不中书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14789, '浪淘沙', '刘克庄', '早岁类寒蛩。\n晚节遭逢。\n曾开黄卷侍重瞳。\n归去青藜光照窗，阶药翻红。\n出昼颇匆匆。\n主眷犹浓。\n除官全似紫阳翁。\n换个新衔头面改，又似包公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14790, '浪淘沙', '刘克庄', '纸帐素屏遮。\n全似僧家。\n无端霜月闯窗纱。\n唤起玉关征戍梦，几叠寒笳。\n岁晚客天涯。\n短发苍华。\n今年衰似去年些。\n诗酒新来俱倚阁，孤负梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14791, '浪淘沙', '刘克庄', '叠嶂碧周遮。\n游子思家。\n掩藏白发赖乌纱。\n落日倚楼千万恨，社鼓城笳。\n老去淡生涯。\n虚掷年华。\n腊茶盂子太清些。\n待得痴儿公事毕，谢了梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14792, '浪淘沙', '刘克庄', '目力已茫茫。\n缝菊为囊。\n论衡何必帐中藏。\n却爱素馨清鼻观，采伴禅床。\n风露送新凉。\n山麝开房。\n旋吹银烛闭华堂。\n无奈纱厨遮不住，一地闻香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14793, '凤凰阁', '刘克庄', '元规端委，得似幼舆丘壑。\n人言此辈宜高阁。\n几载种天随菊，采庞公药。\n龙尾道、难安汗脚。\n浮荣菌，选甚庶官从橐。\n对床句、子真佳作。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14794, '法驾导引', '刘克庄', '樵柯烂，丹灶熟，一跳出红尘。\n斗紫一双龙奋贽，帝青九万里为程。\n赤脚踏层云。\n鞭鸾上，骑麟下，彷佛睹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14795, '一翦梅', '刘克庄', '陌上行人怪府公。\n还是诗穷。\n还是文穷。\n下车上马太匆匆。\n来是春风。\n去是秋风。\n阶衔免得带兵农。\n嬉到昏钟。\n睡到斋钟。\n不消提岳与知宫。\n唤作山翁。\n唤作溪翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14796, '一翦梅', '刘克庄', '束宵行十里强。\n挑得诗囊。\n抛了衣囊。\n天寒路滑马蹄僵。\n元是王郎。\n来送刘郎。\n酒酣耳热说文章。\n惊倒邻墙。\n推倒胡床。\n旁观拍手笑疏狂。\n疏又何妨。\n狂又何妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14797, '踏莎行', '刘克庄', '日月跳丸，光阴脱兔。\n登临不用深怀古。\n向来吹帽插花人，尽随残照西风去。\n老矣征衫，飘然客路。\n炊烟三两人家住。\n欲携斗酒答秋光，山深无觅黄花处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14798, '踏莎行', '刘克庄', '驱鹊营桥，呼蟾出海，朝朝暮暮遥相望。\n谁知风雨此时来，银河便有些波浪。\n玉兔迷离，金鸡嘲晰，二星无语空惆怅。\n元来上界也多魔，天孙长怨牵牛旷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14799, '玉楼春', '刘克庄', '年年跃马长安市。\n客舍似家家似寄。\n青钱换酒日无何，红烛呼庐宵不寐。\n易挑锦妇机中字。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14800, '鹊桥仙', '刘克庄', '金风淅淅，银河淡淡，长少群贤毕会。\n平生心事曲生知，怪此夕、惺惺相对。\n玄花生眼，新霜点鬓，不肯遮藏老态。\n人间何处有仙方，擘划得、二三百岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14801, '鹊桥仙', '刘克庄', '御屏录了，冰衔换了，酷似香山居士。\n草堂丹灶莫留他，且领取、忠州刺史。\n移来芳树，摘来珍果，压尽来禽青李。\n三千年一荐金盘，又不是、玄都栽底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14802, '鹊桥仙', '刘克庄', '阁中芸冷，观中桃谢，谁问贞元朝士。\n吾宗一句好书绅，但记取、毋污青史。\n不交平勃，不游田窦，也不朋他牛李。\n平章此去似何人，似洛社、戴花舞底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14803, '鹊桥仙', '刘克庄', '出通明殿，入耆英社，谁似侍郎洪福。\n掌中元自有三珠，更检校、诸孙夜读。\n管他莱相，管他鹤相，留我本来面目。\n希夷一枕未曾醒，笑人世，几回翻局。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14804, '鹊桥仙', '刘克庄', '俱登瀛馆，俱还洛社，各自健如黄犊。\n不消外监与留台，也不要、嵩山崇福。\n我如原父，君如贡父，且把汉书重读。\n韩公当局等闲过，又看到、温公当局。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14805, '鹊桥仙', '刘克庄', '去年无麦，今年多稼，尽是君侯心地。\n向来寺寺总拘桩，今有不拘桩底寺。\n省仓展日，米场镌价，万落千村蒙惠。\n更将补纳放宽些，便是个、西京循史。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14806, '鹊桥仙', '刘克庄', '香芸辟蠹，青藜烛阁，天上宝书万轴。\n前回读得未精详，更罚走、一遭重读。\n松风如故，丹炉如故，坐阅人间陵谷。\n回头调戏窃桃儿，且宁耐、等他桃熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14807, '鹊桥仙', '刘克庄', '有时块坐，有时扶起，门外草深三尺。\n山禽肯唤我为哥，句句道、哥行不得。\n此儿害跛，群儿拍手，次第加公九锡。\n不消长尘短辕车，但乞取、一枝鹤膝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14808, '鹊桥仙', '刘克庄', '女孙笄珥，男孙袍笏，少长今朝咸集。ピ\n且留晚节伴寒香，莫要似、春华性急。ピ\n大招吟了，巫咸下了，未爱修门重入。ピ\n我侬不做佛漳闽，免大雪、庭中呆立。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14809, '鹊桥仙', '刘克庄', '一封奏御，九重知己，不假吹嘘送上。\n从今稳稳到蓬莱，三万里、没些风浪。\n臣年虽老，臣卿尚少，一片丹心葵向。\n何须远比马宾王，且做取、本朝种放。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14810, '鹊桥仙', '刘克庄', '我如龚胜，君如龚舍，拂袖同归乡里。\n共骑竹马有谁存，总唤入、耆英社里。\n苍华尚黑，黄婆方旺，争问翁年今几。\n一门两个老人星，直看见、孙儿生子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14811, '鹊桥仙', '刘克庄', '蒲鞭渐弛，筒渐少，安用知他帘外。\n从今也莫察渊鱼，做到不忍欺田地。\n四民香火，五营笳吹，来献一杯寿水。\n大家赞祝太夫人，长伴取、鲁侯燕喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14812, '柳梢青', '刘克庄', '申白苛留。\n绮园浪出，老不知羞。\n输与先生，一枝鹤膝，一领羊裘。\n便教赐履营丘。\n争似把、渔竿到头。\n冷落溪，张皇牧野，著甚来由。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14813, '鹧鸪天', '刘克庄', '前度看花白发郎。\n平生痼疾是清狂。\n幸然无事污青史，省得教人奏赤章。\n游侠窟，少年场。\n输他群谢与诸王。\n居人不识庚桑楚，弟子谁从魏伯阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14814, '鹧鸪天', '刘克庄', '诗变齐梁体已浇。\n香奁新制出唐朝。\n纷纷竞奏桑间曲，寂寂谁知爨下焦。\n挥彩笔，展红绡。\n十分峭措称妖娆。\n可怜才子如公瑾，未有佳人敌小乔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14815, '卜算子', '刘克庄', '尽是手成持，合得天饶借。\n风雨於花有底雠，著意相陵藉。\n做暖逼教开，做冷催教谢。\n不负明年花下人，只负栽花者。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14816, '卜算子', '刘克庄', '片片蝶衣轻，点点猩红小。\n道是天公不惜花，百种千般巧。\n朝见树头繁，暮见枝头少。\n道是天公果惜花，雨洗风吹了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14817, '卜算子', '刘克庄', '乱似盎中丝，密似风中絮。\n行遍茫茫禹迹来，底是无愁处。\n好客挽难留，俗事推难去。\n惟有翻身入醉乡，愁欲来无路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14818, '卜算子', '刘克庄', '开阁广延贤，负勤求旧。\n应念南宫老舍人，闲袖丝纶手。\n两制必当仁，五福无过寿。\n且喜新年不要□，天要开元。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14819, '卜算子', '刘克庄', '东宁馨儿，南国循良守。\n先把炉熏祝帝尧，次祝君侯寿。\n广致米商船，多酿兵厨酒。\n客有须眉似盖延，许至华堂否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14820, '卜算子', '刘克庄', '已怪社愆期，尚喜巢如故。\n过了清明未肯来，莫被春寒误。\n常傍画檐飞，忽委空梁去。\n忘却王家与谢家，别有衔泥处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14821, '卜算子', '刘克庄', '老圃献花来，异域移根至。\n相对炎官火伞中，便有清凉意。\n淡薄古梳妆，娴雅仙标致。\n欲起涪翁再品花，压了山矾弟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14822, '朝天子', '刘克庄', '宿雨频飘洒。\n欢喜西畴耕者。\n终朝连夜。\n有珠玑鸣瓦。\n渐白水、青秧鸥鹭下。\n老学种花兼学稼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14823, '清平乐', '刘克庄', '纤云扫迹。\n万顷玻璃色。\n醉跨玉龙游八极。\n历历天青海碧。\n水晶宫殿飘香。\n群仙方按霓裳。\n消得几多风露，变教人世清凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14824, '清平乐', '刘克庄', '风高浪快。\n万里骑蟾背。\n曾识娥真体态。\n素面元无粉黛。\n身游银阙珠宫。\n俯看积气。\n醉里偶摇桂树，人间唤作凉风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14825, '清平乐', '刘克庄', '宫腰束素。\n只怕能轻举。\n好筑避风台护取。\n莫遣惊鸿飞去。\n一团香玉温柔。\n笑颦俱有风流。\n贪与萧郎眉语，不知舞错伊州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14826, '清平乐', '刘克庄', '休弹别鹤。\n泪与弦俱落。\n欢事中年如水薄。\n怀抱那堪作恶。\n昨宵月露高楼。\n今朝烟雨孤舟。\n除是无身方了，有身长有闲愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14827, '清平乐', '刘克庄', '冰轮万里。\n云卷天如洗。\n先向海山生大士。\n却诞卯金之子。\n冰盆荔子堪尝。\n胆瓶茉莉尤香。\n震旦人人炎热，补陀夜夜清凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14828, '清平乐', '刘克庄', '人间喘汗。\n无计翻银汉。\n有个至人来震旦。\n宴坐补陀岩畔。\n吾闻福寿难量。\n待看海底生桑。\n乞取净瓶一滴，普教大地清凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14829, '好事近', '刘克庄', '老不计生朝，惭愧阿连书尺。\n雪鬓霜髭不管，管眼腰黄赤。\n待将心事自笺天，莫费子公力。\n乞赐先生处士，换一张黄敕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14830, '菩萨蛮', '刘克庄', '小鬟解事高烧烛。\n群花围绕樗蒲局。\n道是五陵儿。\n风骚满肚皮。\n玉鞭鞭玉马。\n戏走章台下。\n笑杀灞桥翁。\n骑驴风雪中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14831, '忆秦娥', '刘克庄', '游人绝。\n绿阴满野芳菲歇。\n芳菲歇。\n养蚕天气，采茶时节。\n枝头杜宇啼成血。\n陌头杨柳吹成雪。\n吹成雪。\n淡烟微雨，江南三月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14832, '忆秦娥', '刘克庄', '修禊节。\n晋人风味终然别。\n终然别。\n当时宾主，至今清绝。\n等闲写就兰亭帖。\n岂知留与人闲说。\n人闲说。\n永和之岁，暮春之月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14833, '忆秦娥', '刘克庄', '泥滑滑。\n一声声唤征鞍发。\n征鞍发。\n客亭杨柳，不禁攀折。\n荀郎衣上香初歇。\n萧郎心下书难说。\n书难说。\n霎时吹散，一生愁绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14834, '忆秦娥', '刘克庄', '春酲薄。\n梦中球马豪如昨。\n豪如昨。\n月明横笛，晓寒吹角。\n古来成败难描摸。\n而今却悔当时错。\n当时错。\n铁衣犹在，不堪重著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14835, '忆秦娥', '刘克庄', '梅谢了。\n塞垣冻解鸿归早。\n鸿归早。\n凭伊问讯，大梁遗老。\n浙河西面边声悄。\n淮河北去炊烟少。\n炊烟少。\n宣和宫殿，冷烟衰草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14836, '西江月', '刘克庄', '思邈方书去失，休文老病来攻。\n新年筋力太龙锺。\n腰似铁锚儿重。\n雅拜怎生笏，徐行也要扶筇。\n田翁邀饮不能从。\n难伴诸公上雍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14837, '朝中措', '刘克庄', '恰为仙佛做生辰。\n公又绂麒麟。\n黑白几枰屡变，丹青百奏如新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14838, '朝中措', '刘克庄', '受持鼻祖五千言。\n留得谷神存。\n伴我赋诗茅屋，饶渠待诏金门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14839, '朝中措', '刘克庄', '仙风道骨北山翁。\n万卷著胸中。\n涣若宦情冰释，作□醉面桃红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14840, '朝中措', '刘克庄', '海天万顷碧玻璃。\n风露洗炎曦。\n鹦鹉绿毛导从，蟾□雪色追随。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14841, '水调歌头', '刘克庄', '君看郭西景，浑不减孤山。\n飞楼突兀百尺，轮奂侈前观。\n绝唱新词寡和，堕泪旧碑无恙，往事付惊澜。\n不见辽鹤返，惟对水鸥闲。\n又何必，珠翠盛，管弦欢。\n唾壶麈尾潇洒，领客上高寒。\n丞相功存宗庙，祭酒义兼家国，世事尚相关。\n风月寓意耳，莫作晋人看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14842, '贺新郎', '刘克庄', '辜负东风约。\n忆曾将、淮南草木，笔端笼络。\n后土祠中明月夜，忽有瑶姬跨鹤。\n迥不比、水仙低弱。\n天上人间惟一本，倒千锺、琼露花前酌。\n追往事，怎忘却。\n移根应费仙家药。\n漫回头、关山信断，堡城笳作。\n问讯而今平安否，莫遣玉箫惊落。\n但画卷、依稀描著。\n白发愧无渡江曲，与君家、子敬相酬酢。\n新旧恨，两交错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14843, '满江红', '刘克庄', '晓色朦胧，佳色在、黄堂深处。\n记当日、霓旌飞下，鸾翔凤翥。\n兰省旧游隆注简，竹符新剖宽忧顾。\n有江南、千里好溪山，留君住。\n牙板唱，花舞。\n云液滑，霞觞举。\n顾朱颜绿鬓，年年如许。\n见说相门须出相，何时再筑沙堤路。\n看便飞、丹诏日边来，朝天去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14844, '水调歌头', '刘克庄', '风露洗玉宇，星斗灿银潢。\n云间笙鹤来下，人世变凄凉。\n九转金丹成後，一朵红云深处，玉立侍虚皇。\n却笑跨夺子，草草梦黄粱。\n君记否，齐桓□，鲁灵光。\n中原公案未了，直下欠人当。\n试问玉门关外，何似金銮殿上，此段及平章。\n富贵倘来耳，万代姓名香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14845, '乳燕飞・贺新郎', '刘克庄', '风流八十，是人间妆点，孩儿眉额。\n再著三星添上面，又是一般奇特。\n且置零头，举将成数，算起君须识。\n从今十倍，恰当彭祖八百。\n更把百倍添来，庄椿身世，又十头添撇。\n况迈非熊年纪在，管取方来勋业。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14846, '水龙吟', '刘克庄', '昔人风调谁高，二疏盛日还乡里。\n公卿祖道，百城围尽，争传佳事。\n闻自垂车日，都门外、送车凡几。\n今世无工，尽置之勿道，煌处、独青史。\n佳甚东阳山水。\n是昔时、钓游某地。\n风流脱似，洛中耆老，一人而已。\n好为霞觞，正庭阶、彩衣荣侍。\n便明朝有诏，启门解说，值先生醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14847, '买陂塘・摸鱼儿', '赵癯斋', '闻掀髯、岭头长啸，梅花一夜香吐。\n正看鸣凤朝阳影，何事惊鸿翩举。\n来又去。\n但赢得、儿童拍手笑无据。\n人间何处。\n有九曲栽芹，一峰横砚，江上听春雨。\n功名事，不信朝鳞暮羽。\n九关虎豹如许。\n午桥见有闲风月，正自不妨嘉趣。\n君记取。\n人尽道、东山安石难留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14848, '贺新郎', '程正同', '久矣无循吏。\n自当年、弘宽去後，风流谁继。\n律令喜为鹰击勇，无复柔桑驯雉。\n何幸见、真儒小试。\n手种海棠三百本，有几多、遗爱人须记。\n潘岳县，未为贵。\n文章政事通枫陛。\n看傅岩、霖雨岁旱，要须均施。\n玉色温其山似立，气禀新秋清厉。\n便好据、经纶要地。\n却笑庞才非百里，骤天衢、自合还天骥。\n卮酒祝，八千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14849, '沁园春', '程正同', '富敌陶猗，才卑贾马，气吞曹刘。\n更妓娱安石，东山名胜，樽盈文举，北海风流。\n事冷千年，身兼八子，豪举伊谁与匹俦。\n应还笑，为天将降任，未欲东周。\n优游。\n宁久淹留。\n管蓬矢桑弧志早酬。\n有棠棣联芳，庭萱不老，砌兰擢秀，蟾桂传秋。\n要颂椿龄，若将柏叶，婢膝奴颜应合羞。\n直须是，功名期会，同跨鳌头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14850, '满庭芳', '程正同', '五柳先生，宦情无几，赋成归去来兮。\n吾归何所，任运且随时。\n曾向高人问道，清妙处、已悟希夷。\n谁能羡，胸中芥子，容易纳须弥。\n竹林，新职事，神交狂客，志慕天随。\n但能乐天知命，夫复何疑。\n多谢故人念我，平安报、不必纲维。\n饮君酒，愿君同寿，此外本无为。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14851, '思越人・朝天子', '程正同', '曾把隋珠抵鹊来。\n拓弓花下不虚开。\n醉馀戏把行人弹，堪笑齐王谩筑台。\n穿兔手，落雕材。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14852, '朝中措', '程正同', '少年不入利名场。\n花柳作家乡。\n一片由甲口觜，几多耍俏心肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14853, '临江仙', '阳枋', '乐意相关莺对语，春风遍满天涯。\n生香不断树交花。\n个中皆实理，何处是浮华。\n收敛回来还夜气，一轮明月千家。\n看梅休用隔窗纱。\n清光辉皎洁，疏影自横斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14854, '念奴娇', '阳枋', '白尽蒹葭，衰从蒲柳，我只松筠节。\n君民尧舜，老翁揩眼勋业。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14855, '清夜游', '周端臣', '西园昨夜，又一番、阑风伏雨。\n清晨按行处。\n有新绿照人，乱红迷路。\n归吟窗低，但瓶几留连春住。\n窥晴小蝶翩翩，等闲飞来似相妒。\n迟暮。\n家山信杳，奈锦字难凭，清梦无据。\n春尽江头，啼鹃最凄苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14856, '春归怨', '周端臣', '问春为谁来、为谁去，匆匆太速。\n流水落花，夕阳芳草，此恨年年相触。\n细履名园，闲看嘉树，蔼翠阴成簇。\n争知也被韶华，换却诗人鬓边绿。\n小花深院静，旋引清尊，自歌新曲。\n燕子不归来，风絮乱吹帘竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14857, '木兰花慢', '周端臣', '霭芳阴未解，乍天气、过元宵。\n讶客袖犹寒，吟窗易晓，春色无聊。\n梅梢。\n尚留顾藉，滞东风、未肯雪轻飘。\n知道诗翁欲去，递香要送兰桡。\n清标。\n会上丛霄。\n千里阻、九华遥。\n料今朝别後，他时有梦，应梦今朝。\n河桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14858, '玉楼春', '周端臣', '华堂帘幕飘香雾。\n一搦楚腰轻束素。\n翩跹舞态燕还惊，绰约妆容花尽妒。\n樽前谩咏高唐赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14859, '六桥行', '周端臣', '芙蓉苑。\n记试酒清狂，鞭游遍。\n翠红照眼。\n凝芳露、洗出青霞一片。\n垂杨两岸。\n窥镜底、新妆深浅。\n应料似、锦帐行春，三千粉春矜艳。\n邂逅系马堤边，念玉笋轻攀，笑簪同欢。\n岁华暗换。\n西风路、几许愁肠凄断。\n仙城梦黯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14860, '六桥行', '周端臣', '苏堤路。\n正密柳烘烟，嫩莎收雨。\n野芳竞吐。\n山如画、隐隐云藏山坞。\n六桥徙倚。\n喧处处、行春箫鼓。\n鸥影外、一片湖光，夷犹彩舟来去。\n凝想禊饮花前，爱裙幄围香，款留连步。\n旧踪未改，还曾记、揽结亭边芳树。\n愁情几许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14861, '少年游', '周端臣', '四山烟霭未分明。\n宿雨破新晴。\n万顷湖光，一堤柳色，人在画图行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14862, '喜迁莺令・喜迁莺', '周端臣', '青嶂绕，翠堤斜。\n晴绮散馀霞。\n一湖春水碧无瑕。\n可惜画船遮。\n燕交飞，莺对语。\n风软香尘凝路。\n一年春事又扬花。\n诗酒□韶华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14863, '贺新郎', '周端臣', '怕听黄昏雨。\n到黄昏、陡顿潇潇，雨声不住。\n香冷罗衾愁无寐，难奈凄凄楚楚。\n暗试把、佳期重数。\n楼外一行征雁过，更偏来、撩理芳心苦。\n心自苦，向谁诉。\n菱花憔悴羞人觑。\n欢红低翠黯，不似旧家眉妩。\n目断阳台幽梦阻，孤负朝朝暮暮。\n怕泪落、瑶筝慵拊。\n手拈梅花春又近，料人间、别有安排处。\n云碧袖，为君舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14864, '沁园春', '赵福元', '一剑凌风，跨六鳌头，登群玉峰。\n听金童宣敕，琼胎掇送，大唐进士，圣宋仙翁。\n琪树玲珑，宝花散漫，香霭天枝绕绛空。\n後五日，有竹湖公相，梦叶非熊。\n峥嵘得子如龙。\n傲南墅修篁皓鹤中。\n似银瓶碾月，一清彻底，玉虹贯斗，千丈蟠胸。\n洛殿催班，燃灯赐对，九万鹏程瞬息通。\n蟠桃宴，与蟾宫双桂，长伴乔松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14865, '沁园春', '赵福元', '斗柄御寅，序启苍涂，气转洪钧。\n正乾坤交泰，圣贤相遇，风声虎啸，雾龙兴。\n华渚流虹，璇枢绕电，期迈三朝嵩降申。\n真希有，庆吾皇万岁，重臣千春。\n枫震宠数来频。\n绾叠组累累辉楚城。\n看袍将赐锦，带仍佩玉，十行丹诏，单骑红尘。\n入赞中兴，泰阶上宰，寿域八荒歌太平。\n运化笔，管烘□桃李，又一番新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14866, '沁园春', '赵福元', '珠斗阑干，银河清浅，梦帝关。\n见六丁拥道，一声传跸，翠幢舞凤，彩扇交鸾。\n寿祝天齐，神夸岳降，报到明朝重整班。\n璇星烂，有赤松黄石，雾凑苍坛。\n仙风绿鬓朱颜。\n才奏罢呼麟游海山。\n命飞琼步月，瑶台凝净，云英捣雪，玉杵光寒。\n鹤立芝庭，龟迎荷□，鼎看翩翩彩袖翻。\n留春醉，醉何须归去，常在人寰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14867, '减字木兰花', '赵福元', '吮煤弄笔。\n草圣寰中君第一。\n电脚摇光。\n骤雨旋风声满堂。\n豪厘巧辨。\n唤起羲之当北面。\n醉眼摩娑。\n错认书颠作酒颠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14868, '鹧鸪天', '赵福元', '裙曳湘波六幅缣。\n风流体段总无嫌。\n歌翻檀口朱缨小，拍弄红牙玉笋纤。\n腔子里，字儿添。\n嘲撩风月性多般。\n憎声里金珠迸，惊起梁尘落无帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14869, '念奴娇', '李亿', '镜鸾分影，望天涯肠断，悄无红叶。\n几度秋风吹翠被，一缕幽香难灭。\n燕卜新梁，花移别槛，回首春如客。\n欢情何在，绿杨空销愁色。\n可是今古风流，小乔姝丽，只许周郎得。\n金谷珠帘空百尺，不碍梦魂飞入。\n钗股盟深，旧缘未断，月有重圆日。\n蓝桥路近，乘云先问消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14870, '菩萨蛮', '李亿', '画楼酒醒春心悄。\n残月悠悠芳梦晓。\n娇汗浸低鬟。\n屏山云雨阑。\n香车河汉路。\n又是匆匆去。\n鸾扇护明妆。\n含情看绿杨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14871, '徵招', '李亿', '翠壶浸雪明谣夜，初疑玉虬飞动。\n莫弄紫箫吹，堕寒琼惊梦。\n把红炉对拥。\n怕清魄，不禁霜重。\n爱护殷勤，待长留作，道人香供。\n尘暗古南州，风流远、谁寻故枝么凤。\n谩举目销凝，对愁云。\n向霞扉月洞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14872, '满庭芳', '刘颉', '莺老梅黄，水寒烟淡，断香谁与添温。\n宝缸初上，花影伴芳尊。\n细细轻帘半卷，凭阑对、山色黄昏。\n人千里，小楼幽草，何处梦王孙。\n十年，羁旅兴，舟前水峄，马上烟村。\n记小亭香墨，题恨犹存。\n几夜江湖旧梦，空凄怨、多少销魂。\n归鸦被，角声惊起，微雨暗重门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14873, '贺新郎', '冯取洽', '九日明朝是。\n问宜轩何事，今朝众宾交至。\n长记每年八月八，曾庆饮仙出世。\n直推到、於今何意。\n要待千崖秋气爽，向东篱、试探花开未。\n挝急鼓，舞长袂。\n主人臭味花相似。\n笑争春、红紫低昂，转头扫地。\n独占西风摇落候，旋屑黄金点缀。\n做得个、秋花元帅。\n旧说东阳流菊水，饮之者、寿过百馀岁。\n泛此酒，劝公醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14874, '贺新郎', '冯取洽', '自愿卑栖翼。\n似沧洲、白鸟悠悠，静依拳石。\n聊寄一梯云木表，俯视霁虹千尺。\n乐江上、山间声色。\n镜样清流环样绕，笑赐湖、一曲夸唐敕。\n尘外趣，有谁识。\n飞来妙墨痕犹湿。\n走盘珠流出，不火食人胸膈。\n三叹阳春知和寡，但觉光生虚室。\n何处觅，倚歌箫客。\n他日玉林来得否，待平分、风月供吟笔。\n添一友，共闲逸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14875, '贺新郎', '冯取洽', '句里思黄九。\n笑王郎、不奈寒芳，腰围如柳。\n得似江郎饶雅趣，时揽黄花诳口。\n吐妙语、与之争秀。\n闲绕珍从吟不尽，尽风前、露下栾栾瘦。\n香自足，岂劳嗅。\n一尊问我能同否。\n叹双溪、冷落篱边，傲霜犹有。\n浩唱云笺金缕调，兴发小槽珠酒。\n待唤醒、早春梅友。\n独恨爱花人易老，漫一年，好景还依旧。\n东望处，立良久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14876, '贺新郎', '冯取洽', '梦折营门柳。\n送君归、暂戏斑衣，又拢征袖。\n到得皇州风景异，只有湖山似旧。\n把感慨、寓之杯酒。\n雨抹晴妆西子样，且平章、剩赋诗千首。\n富与贵，本来有。\n青油幕底筹攻守。\n拥貔貅、朝气凌云，夜锋冲斗。\n蜀淮氛犹在眼，一扫正须健帚。\n又何惜、驱弛奔走。\n快展韬铃资世用，看归来、金印悬双肘。\n倾玉，为亲寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14877, '贺新郎', '冯取洽', '那得身无事。\n问双溪老子，而今万缘空否。\n正使尘牢偿未了，毕竟难昏灵府。\n已笑唾、功名如土。\n五十九年风雨过，算非非、是是何须数。\n垂老也，信缘度。\n绿阴朱夏回清暑。\n叹病来、觞怯流霞，扇闲白羽。\n方念生初增感慨，谁寄乐章新语。\n知是我、花庵庵主。\n一别三年惟梦见，定何时、相对倾琼醑。\n惊世路，有豺虎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14878, '贺新郎', '冯取洽', '知彼须知此。\n问筹边、攻守规模，云何则是。\n景色犹日暮，壮士无由吐气。\n又安得、将如廉李。\n燕坐江沱甘自蹙，笑腐儒、枉楦朝家紫。\n用与舍，徒为耳。\n黄芦白苇迷千里。\n叹长淮、篱落空疏，仅馀残垒。\n读父兵书宁足恃，击楫谁盟江水。\n有识者、知其庸矣。\n多少英雄沈草野，岂堂堂、吾国无君子。\n起诸葛，总戎事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14879, '贺新郎', '冯取洽', '问讯花庵主。\n这一宗、拍板门槌，是谁亲付。\n逢翰墨场聊作戏，那个是真实语。\n算惟有、青山堪住。\n玉立林幽真脱洒，又何妨、白石和泉煮。\n底用判，云游据。\n朝三暮四从渠赋。\n且随缘、家养园收，自然成趣。\n此外盘蜗馀一室，人我两俱无负。\n要参到、道心微处。\n尽作逃禅逃得密，也难遮、拨草来寻路。\n应为拨，懒残芋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14880, '贺新郎', '冯取洽', '二老交相访。\n正不妨、勃姗，舍车而杖。\n忆在蓉村新雨过，门外春流浩荡。\n中有个、列仙相。\n把酒论诗饶胜韵，更柳边、花底同心赏。\n临别句，几回唱。\n忽传风驭来溪上。\n遣儿曹、策马郊迎，老怀欣畅。\n争讶金华佳父子，飞下蓬莱阆。\n有四士、追随仙仗。\n我爱君如何次道，便令人、直欲倾家酿。\n歌妙曲，郑声放。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14881, '贺新郎', '冯取洽', '往事休寻访。\n幸老来、筋力差强，未须扶杖。\n收脚八风波外立，一片虚空荡荡。\n误寿者、本来无相。\n今日不知何日也，便戊申、重见何须赏。\n大梦曲，此时唱。\n团栾儿女溪堂上。\n且一觞、一咏陶然，此情堪畅。\n漫说神仙华屋好，缥缈峤壶蓬阆。\n这浮幻、也难凭仗。\n何似熏风来岁岁，蔼一家、和气如春酿。\n婚嫁了，尽闲放。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14882, '沁园春', '冯取洽', '我爱□君，结屋并山，友松竹梅。\n有倦游孤剑，暂悬素壁，醉吟行履，时印苍苔。\n得失不惊，知恬交养，浩浩胸中何壮哉。\n须知道，似骅骝万里，道路方开。\n相期湖上舒怀。\n莫放过花枝与酒杯。\n况上天已办，河东新赋，圜桥乐得，海内英才。\n矍铄溪翁，据鞍一笑，画饼功名赋倘来。\n长堤上，正柳花荷气，尽可追陪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14883, '沁园春', '冯取洽', '人事好乖，云散风流，暗思去年。\n记竹舆伊轧，报临村里，筇枝颠倒，忙返溪边。\n翦韭新炊，寻桃小酌，取次欢谣俱可编。\n难忘处，是阳春一曲，群唱尊前。\n新晴又放花天。\n况家酿堪携不用钱。\n想有人如玉，已过南市，无人伴我，重醉西阡。\n旧约难凭，新词堪赋，乐事赏心那得全。\n归来也，命儿将此意，写以朱弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14884, '沁园春', '冯取洽', '一雨霈然，六合全清，空无点埃。\n喜秋容新沐，为谁媚妩，凉蟾留照，正尔徘徊。\n蜡屐清游，渔蓑淡话，富贵於予何有哉。\n双溪上，总旧盟鸥鹭，来往无猜。\n烟霞竹石松梅。\n更无数幽花陆续开。\n渐黄鸡啄黍，肥堪一箸，浮蛆拍瓮，美可三杯。\n儿解应门，翁方索句，俗客来时莫放来。\n青山好，尽从今日日，闼不妨排。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14885, '沁园春', '冯取洽', '举世纷纷，风靡波流，名氛利埃。\n有幽人嘉遁，长年修洁，寒花作伴，竟日徘徊。\n餐荐夕英，杯迎朝露，世味何如此味哉。\n扬扬蝶，尽弄芳来往，我又奚猜。\n双溪约玉林梅。\n拟真到庄门一扣开。\n奈衢山风急，勒教回驾，横圹水弱，未许浮杯。\n恨结停云，神驰落月，白雪风前忽堕来。\n教儿唱，侑蓑翁一醉，无闷堪排。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14886, '沁园春', '冯取洽', '问讯柳溪，溪上柳容，胡为带埃。\n叹阳春陡变，孰为披拂，赏音难遇，谁与徘徊。\n好在湖山，吾容不辱，寄径垂条岂偶哉。\n休摇荡，且深根宁极，免俗人猜。\n何妨傍竹依梅。\n待青眼春回一笑开。\n尽攀丝弄叶，效颦施黛，笼鞯拂帽，藉阴传杯。\n未碍飞绵，一高千丈，风力微时稳下来。\n天难问，便陶门汉苑，一任安排。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14887, '沁园春', '冯取洽', '禀气之中，具圣之和，生逢令辰。\n算三春仲月，方才破二，百年大齐，恰则平分。\n立玉林深，散花庵小，中有け然自在身。\n诗何似，似苏州闲远，庾府清新。\n青鞋布袜乌巾。\n试勇往蓉溪一问津。\n有心香一瓣，心声一阕，更携阿艾，同寿灵椿。\n劫劫长存，生生不息，宁极深根秋又春。\n聊添我，作风流二老，岁岁寻盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14888, '沁园春', '冯取洽', '有孤竹君，音节拂云，谥曰洞箫。\n纵柳郎填就，周郎顾罢，欠伊品藻，律也难调。\n惭愧何郎。\n呜呜袅袅，翻入颚唇齿舌喉。\n谁知道，是郭郎亲授，共贯同条。\n後来一辈枵枵。\n甚声响都如鹦鹉娇。\n叹秦青已往，嘉荣何在，念奴骨朽，李八魂消。\n试向尊前，听君一曲。\n前辈风流未觉凋。\n冯郎老，但点头咽唾，拼解金貂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14889, '水调歌头', '冯取洽', '林叶润而密，莺语老犹娇。\n懒翁哪记生日，兀兀度昏朝。\n勘破富贫贵贱，参透死生寿夭，至竟本同条。\n胸次绝疑碍，物外自超遥。\n又何尝，贪七贵，慕三乔。\n溪山吾所自有，宜钓更堪樵。\n窃笑傍门小法，休觅驻颜大药，揠长只伤苗。\n造化大炉耳，愚智一齐销。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14890, '水调歌头', '冯取洽', '雪霁春已半，露重午方喧。\n一筇拄上高绝，便觉眼前宽。\n指点数家楼阁，检校一村花柳，绿水接青烟。\n峦岫竞围绕，风日更清妍。\n闹媒蜂，纷使蝶，菜花繁。\n少年正尔行乐，谁复顾华颠。\n自有此丘此坂，那得游人箫鼓，暖响出中天。\n归步不妨晚，恰则月初弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14891, '念奴娇', '冯取洽', '高堂素壁，漫生绡十幅，图张消暑。\n不奈火云烧六合，逃也略无逃处。\n小派秋声，巨凉点，吸来何许。\n故人词翰，此时飞落蓬户。\n何幸一笑掀髯，停杯浩唱，三叹遗音古。\n雪碗冰瓯无表里，更贮三危鲜露。\n咀咽生香，清寒入梦，展转忘宵曙。\n对床误喜，与君同听风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14892, '金菊对芙蓉', '冯取洽', '宝镜缘空，玉簪点水，荡摇千顷寒光。\n正江妃月姊，斗理明妆。\n扶阑一笑开诗眼，少容我、吟讽其旁。\n一川风露，满怀冰雪，云海弥茫。\n不妨倚醉乘狂。\n问天公觅取，几曲渔乡。\n听小楼哀管，偷弄初凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14893, '木兰花慢', '冯取洽', '叹年光婉晚，蒲柳质、易惊秋。\n况念远怀人，停云幂幂，时雨飕飕。\n西风堕来雁信，似知予、竟日倚溪楼。\n报道归调汤剂，不知谁护衣篝。\n悠然富贵不须求。\n安乐万缘休。\n但饱饭煎茶，婆娑永日，也胜闲愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14894, '摸鱼儿', '冯取洽', '叹刘郎、那回轻别，霏霏三落红雨。\n玄都观里应遗恨，一抹断烟残缕。\n愁望处。\n想雾暗云深，忘却来时路。\n新花旧主。\n记客羽流商，裁红翦翠，山径日将暮。\n空枝上，时有幽禽对语。\n声声如问来否。\n人生行乐须闻健，衰老念谁免此。\n吾所与。\n在溪上深深，锦绣千花坞。\n何时定去。\n但对酒思君，呼儿为我，频唱小桃句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14895, '蝶恋花', '冯取洽', '秋到双溪溪上树。\n叶叶凉声，未省来何许。\n尽拓溪楼窗与户。\n倚阑清夜窥河鼓。\n那得吟朋同此住。\n独对秋芳，欲寄花无处。\n杖履相从曾有语。\n未来先自愁君去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14896, '西江月', '冯取洽', '老子齐头六十，新年第一今朝。\n放开怀抱不须焦。\n万事付之一笑。\n烟柳效颦翠敛，露桃献笑红妖。\n已拼行乐到元宵。\n尚可追随年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14897, '万年歌', '赵以夫', '凤历开新，正微和乍转，丽景初晓。\n五荚舒，光映玉阶瑶草。\n在在东风语笑。\n庆此日、虹流电绕。\n鲸波静，翠涌鳌山，嵩呼声动云表。\n绛节霓旌缥缈。\n望珠星灿烂，紫微深窈。\n琬液香浮，露湿蟠桃犹小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14898, '大', '赵以夫', '正绿阴浓，莺声懒，庭院轻寒烟薄。\n天然花富贵，逞夭红殷紫，叠葩重萼。\n醉艳酣春，妍姿露，翠羽轻明如削。\n檀心鸦黄嫩，似离情愁绪，万丝交错。\n更银烛相辉，玉瓶微浸，宛然京洛。\n朝来风雨恶。\n拍、低张青油幕。\n便好倩、佳人插帽，贵客传笺，趁良辰、赏心行乐。\n四美难并也，须拼醉、莫辞杯勺。\n被花恼、情无著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14899, '孤鸾', '赵以夫', '江南春早。\n问江上寒梅，占春多少。\n自照疏星冷，祗许春风到。\n幽香不知甚处，但迢迢、满汀烟草。\n回首谁家竹外，有一枝斜好。\n记当年、曾共花前笑。\n念玉雪襟期，有谁知道。\n唤起罗浮梦，正参横月小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14900, '金盏子', '赵以夫', '得水能仙，似汉皋遗佩，碧波寒月。\n蓝玉暖生烟，称缟袂黄冠，素姿芳洁。\n亭亭独立风前，照冰壶澄彻。\n当时事，琴心妙处谁传，顿成愁绝。\n六出自天然，更一味清香浑胜雪。\n西湖秋菊寒泉，似坡老风流，至今人说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14901, '天香', '赵以夫', '蜀锦移芳，巫云散彩，天孙翦取相寄。\n金屋看承，玉台凝盼，尚忆旧家风味。\n生香绝艳，说不尽、天然富贵。\n脸嫩浑疑看损，肌柔只愁吹起。\n花神为谁著意。\n把韶华、总归姝丽。\n可是老来心事，不成春思。\n却羡宫袍仙子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14902, '探春慢', '赵以夫', '南国收寒，东郊放暖，条风初回台榭。\n小燕横钗，闹蛾低鬓，根底吴娃妖冶。\n纤手传生菜，向人道、新春来也。\n莫须沈醉樽前，这些风景无价。\n长记年年此日，迎著个牛儿，彩鞭羞打。\n金幡，星星华发，得似家山闲暇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14903, '探春慢', '赵以夫', '屑璐飘寒，镂金献巧，妆成水晶亭榭。\n飞絮悠扬，散花零乱，绝胜翠娇红冶。\n粉艳嘻嘻道，尽飞上、使君也。\n多情莫笑衰翁，旧时梁苑声价。\n窗外小梅羞涩，倩羯鼓尊前，慢敲轻打。\n鲸海停波，鹤谯宾月，赢得残年清暇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14904, '探春慢', '赵以夫', '宝胜宾春，华灯照夜，穷冬浑然如客。\n炉焰鳞红，杯深翡翠，早减三分寒力。\n一笑团栾处，恰喜得、雪消风息。\n苔枝数蕊明珠，恍疑香麝初拆。\n懊恨东君无准，甚朝做重阴，暮还晴色。\n唤燕呼莺，雕花镂叶，机巧可曾休得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14905, '龙山会', '赵以夫', '重整登高屐。\n群玉峰头，万里秋无极。\n远山青欲滴。\n新雁过、飘缈孤云天北。\n烟入小桥低，水痕退、寒流澄碧。\n对佳辰，惊心客里，鬓丝堪摘。\n风流晋宋诸贤，骑台龙山，俯仰皆陈迹。\n凭阑看落日。\n嗟往事、唯有黄花如昔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14906, '龙山会', '赵以夫', '九日无风雨。\n一笑凭高，浩气横秋宇。\n群峰青可数。\n寒城小、一水萦回如缕。\n西北最关情，漫遥指、东徐南楚。\n黯销魂，斜阳冉冉，雁声悲苦。\n今朝黄菊依然，重上南楼，草草成欢聚。\n诗朋休浪赋。\n旧题处、俯仰已随尘土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14907, '龙山会', '赵以夫', '佳节明朝九。\n彩舫凌虚，共醉西风酒。\n湖光蓝滴透。\n云浪碎、巧学波纹吹皱。\n碧落杳无边，但玉削，千峰寒瘦。\n留连久，秋容似洗，月华如昼。\n回头南楚东徐，暝霭苍烟，处处空刁斗。\n山公今健否。\n功名事、付与年时交旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14908, '芙蓉月', '赵以夫', '黄叶舞碧空，临水处、照眼红苞齐吐。\n柔情媚态，伫立西风如诉。\n遥想仙家城阙，十万绿衣童女。\n云飘缈，玉娉婷，隐隐彩鸾飞舞。\n樽前更风度。\n记天香国色，曾占春暮。\n依然好在，还伴清霜凉露。\n一曲阑干敲遍，悄无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14909, '夜飞鹊・夜飞鹊慢', '赵以夫', '微云拂斜月，万籁声沈。\n凉露暗坠桐阴。\n蛾眉乞得天孙巧，楼上穿针。\n佳期鹊相误，到年时此夕，欢浅愁深。\n人间儿女，说风流，直到如今。\n河汉几曾风浪，因景物牵情，自是人心。\n长记秋庭往事，钿花翦翠，钗股分金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14910, '秋蕊香', '赵以夫', '一夜金风，吹成万粟，枝头点点明黄。\n扶疏月殿影，雅澹道家装。\n阿谁倩、天女散浓香。\n十分熏透霓裳。\n徘徊处，玉绳低转，人静天凉。\n底事小山幽咏，浑未识清妍，空自情伤。\n忆佳人、执手诉离湘。\n招蟾魄、和酒吸秋光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14911, '角招', '赵以夫', '晓风薄。\n苔枝上、翦成万点冰萼。\n暗香无处著。\n立马断魂，晴雪篱落。\n横溪略。\n恨寄驿、音书辽邈。\n梦绕扬州东阁。\n风流旧日何郎，想依然林壑。\n离索。\n引杯自酌。\n相看冷淡，一笑人如削。\n水云寒漠漠。\n底处群仙，飞来霜鹤。\n芳姿绰约。\n正月满、瑶台珠箔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14912, '徵招', '赵以夫', '玉壶冻裂琅折，逼人衣袂。\n暖絮张空飞，失前山横翠。\n欲低还又起。\n似妆点、满园春意。\n记忆当时，剡中情味，一溪云水。\n天际。\n绝行人，高吟处，依稀灞桥邻里。\n更翦翦梅花，落云阶月地。\n化工真解事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14913, '扬州慢', '赵以夫', '十里春风，二分明月，蕊仙飞下琼楼。\n看冰花翦翦，拥碎玉成球。\n想长日、云阶伫立，太真肌骨，飞燕风流。\n敛群芳、清丽精神，都付扬州。\n雨窗数朵，梦惊回、天际香浮。\n似阆苑花神，怜人冷落，骑鹤来游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14914, '扬州慢', '赵以夫', '粱苑吟新，高阳饮散，玉容寂寞妆楼。\n故人应念我，折赠水晶球。\n不须倩、东风说与，吹箫云路，解佩江流。\n似天涯、邂逅相逢，低问东州。\n为花更醉，细香、酒面酥浮。\n记桥月同看，帘风共笑，仙枕曾游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14915, '惜黄花', '赵以夫', '众芳凋谢。\n堪爱处、老圃寒花幽野。\n照眼如画。\n烂然满地金钱，买断金钱无价。\n古香逸韵似高人，更野服、黄冠潇洒。\n向霜夜。\n冷笑暖春，桃李夭冶。\n襟期问与谁同，记往昔、独自徘怀篱下。\n采采盈把。\n此时一段风流，赖得白衣陶写。\n而今为米负初心，且细摘、轻浮三雅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14916, '忆旧游慢', '赵以夫', '爱东湖六月，十里香风，翡翠铺平。\n误入红云里，似当年太乙，约我寻盟。\n叶舟荡漾寒碧，分得一襟冰。\n渐际晚轻阴，修蒲舞绿，倦柳梳青。\n娉婷。\n黯无语。\n想怨女三千，长日宫庭。\n六六阑干曲，有玉儿才貌，谁与看承。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14917, '忆旧游慢', '赵以夫', '望红渠影里，冉冉斜阳，十里堤平。\n唤起江湖梦，向沙鸥住处，细说前盟。\n水乡六月无暑，寒玉散清冰。\n笑老去心情，也将醉眼，镇为花青。\n亭亭。\n步明镜，似月浸华清，人在秋庭。\n照夜银河落，想粉香湿露，恩泽初承。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14918, '解语花', '赵以夫', '红香湿月，翠影停云，罗袜尘生步。\n并肩私语。\n知何事、暗遣玉容泣露。\n闲情最苦。\n任笑道、争妍似妒。\n倒银河，秋夜双星，不到佳期误。\n拟把江妃共赋。\n当时携手，烟水深处。\n明珠溅雨。\n凝脂滑、洗出一番铅素。\n凭谁说与。\n莫便化、彩鸾飞去。\n待玉童，双节来迎，为作芙蓉主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14919, '烛影摇红', '赵以夫', '乍冷还暄，小春时候今朝转。\n三分历日二分休，镜里清霜满。\n云幕低垂不展。\n矮窗明、红麟初暖。\n老来活计，浊酒三杯，黄庭一卷。\n万里关河，朔风吹到边声远。\n倚楼脉脉数归鸿，谁会愁深浅。\n最苦山寒日短。\n但梅花、相看岁晚。\n何人金屋，巧啭歌莺，慢调筝雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14920, '薄媚', '赵以夫', '桂香消，梧影瘦，黄菊迷深院。\n倚西风，看落日，长江东去如练。\n先生底事，有赋飘然。\n刚到为田园。\n独醒何为，持杯自劝。\n未能免。\n休把茱萸吟玩。\n但管年年健。\n千古事、几凭阑。\n吾生早、九十强半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14921, '沁园春', '赵以夫', '秋入书帏，漏箭初长，熏炉未灰。\n向酒边陶写，韩情杜思，案头料理，汉蠹秦煨。\n天有高情，世无慧眼，刚道先生是不斋。\n人都笑，这当行铺席，又不成开。\n忘怀。\n物外徘徊。\n与鸥鹭同盟两莫猜。\n似琉璃匣里，光涵牛斗，凤凰台上，声挟风雷。\n宝汞一钱，冰衔三字，浮利浮名安在哉。\n太平也，要泥金镂玉，除是公来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14922, '沁园春', '赵以夫', '客问吾年，吾将老矣，今五十三。\n似北海先生，过之又过，善财童子，参到无参。\n官路太行，世情沧海，何止嵇康七不堪。\n归来也，是休官令尹，有发瞿昙。\n千岩。\n秀色如蓝。\n新著个楼儿恰对南。\n看浮云自在，百般态度，长江无际，一碧虚涵。\n荔子江珧，莼羹鲈，一曲春风酒半酣。\n凭阑处，正空流皓月，光满寒潭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14923, '沁园春', '赵以夫', '自笑声来，骨相无奇，壬三甲三。\n觉紫宸班里，都忘故步，维摩室内，添个新参。\n壮也不如，老之将至，今日将军战岂堪。\n江湖客，况诗肥贾岛，笔瘦王昙。\n纷纷纡紫脱蓝。\n送水北山人又水南。\n喜支离得佚，散材可寿，一丘自足，万象中涵。\n脍炙功名，膏盲富贵，举世黄梁梦正酣。\n知谁健，且茹芝商岭，饮菊胡潭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14924, '贺新郎', '赵以夫', '满酌蓬莱酒。\n最苦是、中年作恶，送人时候。\n一夜朔风吹石裂，惊得梅花也瘦，更衣袂、严霜寒透。\n卷起潮头无丈尺，甚扁舟、拍上三江口。\n明月冷，载归否。\n分携欲折无垂柳。\n但层楼徙倚，两眉空皱。\n海阔天高无处问，万事不堪回首。\n况目断、孤鸿去後。\n玉样松鲈今正美，想子真、微笑还招手。\n且为我，饮三斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14925, '贺新郎', '赵以夫', '葵扇秋来贱。\n阿谁知、初回轻暑，又教题遍。\n不是琵琶知音少，无限如簧巧啭。\n倩说似、长门休怨。\n莫把蛾眉与人妒，但疏梅、淡月深深院。\n临宝鉴，欲妆懒。\n少时声价倾粱苑。\n到中年，也曾落魄，雾收云卷。\n待入汉庭金马去，洒笔长江滚滚。\n好留取、才名久远。\n过眼荣华俱尘土，听关睢、盈耳离骚婉。\n歌不足，为嗟叹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14926, '贺新郎', '赵以夫', '载酒阳关去。\n正西湖、连天烟草，满堤晴絮。\n采翠撷芳游冶处，应和娇弦艳鼓。\n看柳外、画船无数。\n万倾琉璃浑镜净，陡风波、汹汹鱼龙舞。\n谈笑里，遽如许。\n流觞满引浇离绪。\n便东西、斜阳立马，绿波前浦。\n自是莼鲈高兴动，恰值春山杜宇。\n漫回首、软红香雾。\n咫尺佳人千里隔，望空江、明月横洲渚。\n清梦断，恨如缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14927, '贺新郎', '赵以夫', '草色庭前绿。\n掩重门、国香伴我，画帘幽独。\n无奈熏风吹绿绮，闲理离骚旧曲。\n觉鼻观、微闻清馥。\n可是花神嫌冷淡，碧丛中、炯炯骈双玉。\n相对久，各欢足。\n冰姿带露如新沐。\n想当年、夷齐二子，独清孤竹。\n千古英雄尘土尽，凛凛西山云木。\n总付与、一尊。\n学得汉宫娇姊妹，便承恩、贮向黄金屋。\n终不似，在空谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14928, '贺新郎', '赵以夫', '碾破长空绿。\n看银蟾、一轮似水，照人清独。\n缥缈风摇环佩碎，疑是英茎妙曲。\n忽散作、天花芬馥。\n帝子双双来洞户，炯肌肤、冰雪颜如玉。\n愁易老，意难足。\n楚江万顷疏汤沐。\n想佳人，依然携手，碧云修竹。\n葱玲珑方寸许，清过千重夏木。\n速就我、同倾湘。\n追忆兰亭当日事，尽凄凉、也胜卢仝屋。\n应不到，羡金谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14929, '贺新郎', '赵以夫', '春事浑如客。\n趁新晴、花骢骄骏，衫轻窄。\n腊瓮初倾光欲动，笑把黄甘旋擘。\n更喜得、酒朋诗敌。\n陶写襟怀觞咏里，似风流、王谢当年集。\n忘尔汝，任争席。\n疏帘画舫梅妆白。\n看斜阳、波心镜面，照伊颜色。\n飘缈笙歌天上谱，一刻千金莫惜。\n谁信道、高楼占得。\n柳外暝烟人去也，但月钩、冷浸阑干湿。\n知过了，几寒食。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14930, '汉宫春', '赵以夫', '投老归来，记踏青堤上，三度逢君。\n寒窗冷淡活计，明月空尊。\n红红白白，又一番、春色撩人。\n谁信道，闲中天地，园林几见成尘。\n今夕偶无风雨，便满城箫鼓，来往纷纷。\n鳌山宝灯照夜，罗绮千门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14931, '暗香', '赵以夫', '冰花炯炯。\n记那回占断，春风鳌顶。\n独抱寒香，得意西湖酒初醒。\n为问玉堂富贵，争得似、山中深靓。\n向岁晚，竹翠松苍，闲伴一枝冷。\n南浦，水万顷。\n想月湿断矶，云弄疏影。\n粉英落尽。\n孤鹤长鸣夜方永。\n将见青青似豆，又迤逦、传黄风景。\n听报道、催去也，再调玉鼎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14932, '疏影', '赵以夫', '晴空漠膜。\n怪雪来底处，飘满篱落。\n元是花神，管领春风，幽香忽遍林壑。\n玉仙缓辔江城路，全不羡、扬州东阁。\n似天教、瑶佩琼裾，荐与翠尊冰勺。\n闻道儿童好语，丰年瑞覆斗，占取红萼。\n驿使飞驰，羹鼎安排，速趁良辰行乐。\n联镳一一清都客，也肯把、山翁同约。\n醉归来、梦断西窗，怕听丽谯悲角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14933, '尾犯', '赵以夫', '长啸蹑高寒，回首万山，空翠零乱。\n渺渺清秋，与斜阳天远。\n引光禄、清吟兴动，忆龙山、旧游梦断。\n夹衣初试，破帽多情，自笑霜蓬短。\n黄花长好在，一俯仰、节物惊换。\n紫蟹青橙，觅东篱幽伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14934, '燕春台', '赵以夫', '绣地残英，画空飞絮，东风又送春归。\n雨足郊，相将翠密成帷。\n燕莺犹恋芳菲。\n向枝头、叶底依依。\n留春不住，绿波渺渺，碧草萋萋。\n锦帆开晓，彩仗迎熏，峰回路转，月淡天低。\n红云影里，群仙报道班齐。\n九奏箫韶，算人间、无此埙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14935, '燕春台', '赵以夫', '锦里春回，玉墀天近，东风稳送雕鞯。\n祖帐移来，光流万斛金莲。\n十分香月娟娟。\n照人间、一点魁躔。\n此时新事，飞来双凤，催上甘泉。\n寻思京洛，少日芳游，柳遥禁雪，花淡宫烟。\n鳌山涌翠，通宵脆管繁弦。\n再见升平，想红云、飘缈群仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14936, '玉烛新', '赵以夫', '寒宽一雁落。\n正万里相思，被渠惊觉。\n春风字字吹香雪，唤起西湖盟约。\n当时醉处，仿佛记、青楼珠箔。\n又不是，南国花迟，徘徊酒边慵酌。\n家山月色依然，想竹外横枝，玉明冰薄。\n而今话昨。\n空对景、怅望美人天角。\n清尊淡薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14937, '念奴娇', '赵以夫', '重门翠锁，笑侯鲭断绝，又逢寒食。\n社瓮初开春浩荡，荠蕨漫山谁摘。\n榆火传新，柳绵吹老，愁绪空千忆。\n百花过了，游蜂将次成蜜。\n追思共醉西湖，诗朋馀几，俯仰成悲恻。\n月射波心光万丈，犹想当时颜色。\n黄鹄翩翩，白驹皎皎，莫待山灵勒。\n金貂箬笠，问渠还肯相易。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14938, '念奴娇', '赵以夫', '尊前一笑，问梅花消息，几枝开遍。\n咳唾随风人似玉，寒夜春生酒面。\n故里天遥，殊乡岁晚，忍对骊驹宴。\n无情潮汐，可能为我留恋。\n目断雪棹烟帆，匆匆轻别，岂是如鸿燕。\n要趁盘椒供燕喜，舞袖斓斑双旋。\n屈指重来，扬鞭催去，想在金銮殿。\n云萍无据，莫辞蘸甲深劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14939, '念奴娇', '赵以夫', '梅花度曲，被多情勾引，枝枝看遍。\n暗忆孤山今夜月，疏影横斜镜面。\n萼绿凌风，云英怯冷，未放瑶池宴。\n人间蜂蝶，也知无计迷恋。\n闻道管领多才，清词好句，泥落空梁燕。\n好换蕊珠供彩笔，莫待随风面旋。\n千岁蟠虬，双栖么凤，咫尺蓬莱殿。\n湖边春暗，料应日日酬劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14940, '风流子', '赵以夫', '忆惜少年日，吴江上、长啸步垂虹。\n看飞出玉轮，十分端正，幻成冰壑，一碧澄空。\n当此际，醉魂游帝所，凉袂扬秋风。\n桂殿凤笙，妙音何处，莼羹鲈脍，清兴谁同。\n今宵欢娱地，千钧笔、模写拟付良工。\n无奈云沈顾兔，雨挂痴龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14941, '二郎神', '赵以夫', '一江渌净，算阅尽、燕鸿来去。\n便系日绳长，修蟾斧妙，教驻韶华未许。\n白白红红多多态，问底事、东皇无语。\n但碧草烟淡，落花流水，不堪回伫。\n晴雨。\n陡寒乍热，清阴庭户。\n任诗卷抛荒，棋秤休务，寂寞风帘舞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14942, '二郎神', '赵以夫', '野塘暗碧，渐点点、翠钿明镜。\n想昼永珠帘，人闲金屋，时倚妆台照影。\n睡起阑干凝思处，漫数尽、归鸦栖暝。\n知月下莺黄，云边蛾绿，为谁低整。\n曾倩。\n雁传鹊报，心期千定。\n奈柳絮浮云，桃花流水，长是参差不并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14943, '木兰花慢', '赵以夫', '玉梅吹霁雪，觉和气、满南州。\n更连夕晴光，一番小雨，朝霭全收。\n人情不知底事，但黄童白叟总追游。\n驾海千寻彩岫，涨空万点星球。\n风流。\n秀色明眸。\n金莲步、度轻柔。\n任往来燕席，香风引舞，清官随讴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14944, '满江红', '赵以夫', '倾国精神，娇无力、亭亭向谁。\n还知否，羞沈月姊，妒杀风姨。\n满地胭脂春欲老，平池翡翠水新肥。\n祗花王、富贵占韶光，真绝奇。\n香暗动，人未知。\n翻玉拍，度金衣。\n任轻红殷紫，对景偏宜。\n闻道洛阳夸此地，因思京国太平时。\n向沈香亭北按新词，乘醉归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14945, '摸鱼儿', '赵以夫', '古城阴、一川新浸，天然尘外幽绝。\n谁家幻出千机锦，疑是蕊仙云织。\n环燕席。\n便纵有万花，此际无颜色。\n清风两腋。\n炯玉树森前，碧筒满注，共作醉乡客。\n长堤路，还忆西湖景物。\n游船曾点空碧。\n当时总负凌云气，俯仰顿成今昔。\n愁易极。\n更对景销凝，怅望天西北。\n归来日夕。\n但展转无眠，风水馆，冷浸五更月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14946, '水龙吟', '赵以夫', '塞楼吹断梅花，晓风瑟瑟添凄咽。\n关河万里，烟尘四野，眼前都别。\n击楫功名，椎锋意气，是人都说。\n问周郎何日，小乔到手，为君赋，酹江月。\n休把愁肠暗结。\n又相将、鲁云书节。\n锦围放密，金樽任满，歌声莫歇。\n赢得朝朝，半醒半醉，佯痴佯劣。\n尽瞢腾，深入无何，管甚须鬓成雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14947, '水龙吟', '赵以夫', '谁家明镜飞空，海天绀碧浮秋霁。\n西风淡荡，纤云卷尽，小星疑坠。\n宇宙冰壶，襟怀玉界，飘然仙思。\n炯灵犀一点，蟾辉万丈，长相射、清清地。\n祗又桂花长好，照人间、几番荣悴。\n年年此夕，持杯嚼露，挥毫翻水。\n宝瑟凄清，玉箫飘缈，佩环声碎。\n唤谪仙起舞，古今同梦，不知何世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14948, '水调歌・水调', '赵以夫', '竞渡楚乡事，夸胜锦缠头。\n湖光渌净，转胜雪浪舞潜虬。\n刚道琉璃宝苑，移作水晶珠阙，鳌顶出中流。\n一钓惊天地，能动此心不。\n活千年，封万户，等虚舟。\n渺然身世，烟水浩荡一沙鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14949, '双瑞莲', '赵以夫', '千机云锦里。\n看并蒂新房，骈头芳蕊。\n清标艳态，两两翠裳霞袂。\n似是商量心事。\n倚绿叶、无言相对。\n天蘸水。\n彩舟过处，鸳鸯惊起。\n飘缈漾影摇香，对刘阮风流，双仙姝丽。\n闲情不断，犹恋人间欢会。\n莫待西风吹老，荐玉醴、碧筒拼醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14950, '桂枝香', '赵以夫', '水天一色。\n正四野秋高，千古愁极。\n多少黄花密意，付他欢伯。\n楼前马戏星球过，又依稀、东徐陈迹。\n一时豪俊，风流济济，酒朋诗敌。\n画不就、江东暮碧。\n想阅尽千帆，来往潮汐。\n烟草萋迷，此际为谁心恻。\n引杯抚剑凭高处，黯消魂、目断天北。\n至今人笑，新亭坐间，泪珠空滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14951, '桂枝香', '赵以夫', '青霄望极。\n际万里月明，无点云色。\n一片冰壶世界，水乡先得。\n年年客里惊秋半，倚西风、鬓华吹白。\n觅闲无路，相逢且醉，好天凉夕。\n听曲曲、仙韶促拍。\n趁画舸飞空，雪浪翻激。\n行乐风流，暗省旧时京国。\n插空翠连星麓，但波痕、浮动金碧。\n不如归去，扁舟五湖，钓竿渔笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14952, '永遇乐', '赵以夫', '云雁将秋，露萤照夜，凉透窗户。\n星网珠疏，月奁金小，清绝无点暑。\n天孙河鼓，东西相望，隐隐光流华渚。\n妆楼上，青瓜玉果，多少呆儿痴女。\n金针暗度，珠丝密结，便有系人心处。\n经岁离思，霎时欢爱，愁绪空万缕。\n人间天上，一般情味，枉了锦笺嘱付。\n又何似，吹笙仙子，跨黄鹤去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14953, '鹊桥仙', '赵以夫', '翠绡心事，红楼欢宴，深夜沈沈无暑。\n竹边荷外再相逢，又还是、浮云飞去。\n锦笺尚湿，珠香未歇，空惹闲愁千缕。\n寻思不似鹊桥人，犹自得、一年一度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14954, '虞美人', '赵以夫', '天凉来傍荷花饮。\n携手看云锦。\n城头玉漏已三更。\n耳畔微闻新雁、几声声。\n兰膏影里春山秀。\n久立还成皱。\n酒阑天外月华流。\n我醉欲眠、卿且去来休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14955, '虞美人', '赵以夫', '素娥冷淡愁无奈。\n小作施朱态。\n霓裾霞佩下瑶台。\n一朵绿云围绕、送春来。\n玄霜捣尽丹砂就。\n拼醉长生酒。\n羡君幽壑狎流年。\n把住西风长对、广寒仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14956, '荔枝香近・荔枝香', '赵以夫', '翡翠丛中，万点星球小。\n怪得鼻观香清，凉馆熏风透。\n冰盘快剥轻红，滑凝水晶皱。\n风姿，姑射仙人正年少。\n红尘一骑，曾博妃子笑。\n休比葡萄，也尽压江瑶倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14957, '西江月', '赵以夫', '几点垂垂北斗，一床悄悄西风。\n山河天地点尘空。\n月殿蟾蜍欲动。\n舌本琼浆甘彻，鼻端玉蕊香通。\n棋边切莫笑衰翁。\n个里本来空洞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14958, '一落索', '赵以夫', '露蕊香肌娇秀。\n燕脂微透。\n蕊宫仙子驾祥鸾，被风卷、霞衣皱。\n轻翦倩他红袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14959, '青玉案', '赵以夫', '水亭横枕荷花浦。\n觉水面、香来去。\n亭上佳人云态度。\n天然娇韵，十分就，唱尽黄金缕。\n耳边低道清无暑。\n我欲卿卿卿且住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14960, '小重山', '赵以夫', '一种分香自月宫。\n人间清绝处，小山丛。\n谁将仙米掷虚空。\n丹砂碎，糁遍碧云中。\n好是窦家风。\n年年秋色里，又香浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14961, '谒金门', '赵以夫', '梅共雪。\n著个玉人三绝。\n醉倒醉乡无宝屑。\n照人些子月。\n催得花王先发。\n一曲阳春圆滑。\n疑是嵬坡留锦袜。\n至今香未歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14962, '醉蓬莱', '赵以夫', '正三边月静，万国年丰，菊多梅小。\n吐玉擎香，蔼黄都清晓。\n龙驾徐驱，貂冠夹侍，天也和人笑。\n紫陌欢谣，如今事事，胜端平好。\n玉带垂虹，衮衣华日，秋水精神，仙容貌。\n长对凝旒，不羡商岩老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14963, '凤归云', '赵以夫', '正愁予，可堪去马便骈骈。\n拟折一枝。\n堤上万垂丝。\n离思无边，离席易散，落日照清漪。\n苦是禁城催鼓，虚床难寐，梦魂无路归飞。\n陡寒还热，急雨随晴，化工无准，将息偏难，更向分携处、立多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14964, '芰荷香', '赵以夫', '倚晴空。\n爱湖光潋滟，楼影青红。\n彩丝金黍，水边还又相逢。\n怀沙人问，二千年、犹带酸风。\n骚人洒墨香浓。\n幽情要眇，雅调惺松。\n天上菖蒲五色，倩掺掺素手，分入雕锺。\n新欢往恨，一时付与歌童。\n斜阳正好，且留连、休要匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14965, '扬州慢', '郑觉斋', '弄玉轻盈，飞琼淡泞，袜尘步下迷楼。\n试新妆才了，炷沈水香球。\n记晓剪、春冰驰送，金瓶露湿，缇骑新流。\n甚天中月色，被风吹梦南州。\n尊前相见，似羞人、踪迹萍浮。\n问弄雪飘枝，无双亭上，何日重游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14966, '念奴娇', '郑觉斋', '卷帘酒醒，怕无言、慵理残妆啼粉。\n记绾同心双绣带，珠箔青楼花满。\n琢玉传情，断金订约，总是愁根本。\n谁知薄悻，肯於长处寻短。\n旧日掌上芙蓉，新来成刺，变却风流眼。\n自信华年风度在，未怕香红春晚。\n恩不相酬，怨难重合，往事冰澌泮。\n分明诀绝，股钗还我一半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14967, '谒金门', '郑觉斋', '秋夜永。\n叶叶梧桐霜冷。\n皓月窥人深院静。\n孤鸿窗外影。\n情是相思深井。\n恩是相思修绠。\n别後信音浑不定。\n银瓶何处引。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14968, '孤鸾', '张榘', '塞鸿来早。\n正碧瓦霜轻，玉麟寒少。\n昨夜南枝，一点阳和先到。\n黄昏半窗淡月，照青青、谢池春草。\n此际虚斋心事，与此花俱好。\n算巡檐、索共梅花笑。\n是千古风流，少陵曾道。\n争似油幢下，对一枝春小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14969, '烛影摇红', '张榘', '春小寒轻，南枝一夜阳和转。\n东君先递玉麟香，冷蕊幽芳满。\n应把朱帘暮卷。\n更何须、金猊烟暖。\n千山月淡，万里尘清，酒樽经卷。\n楼上胡床，笑谈声里机谋远。\n甲兵百万出胸中，谁谓江流浅。\n憔悴狂胡计短。\n定相将、来朝悔晚。\n功名做了，金鼎和羹，卷藏袍雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14970, '摸鱼儿', '张榘', '正挑灯、共听檐雨，问谁催动行色。\n风前千点离亭恨，惟有落梅知得。\n王谢宅。\n记前度斜阳，燕子曾相识。\n花香露。\n无计强追随，阳关声断，回首暮云隔。\n文章贯，合上薇垣梧掖。\n征鞍底事江北。\n青衫莫对韩彭著，还是玉麟佳客。\n须记忆。\n有衿佩锵锵，正愿依重席。\n荼シ未折。\n次第牡丹开，一樽留待，相与醉寒食。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14971, '摸鱼儿', '张榘', '正桃花、渐蜚红雨，依稀一半春色。\n东风十里离亭恨，杨柳丝丝如织。\n远又忆。\n向雪月梅边，陶写吟情逸。\n清愁拍拍。\n算祗暮山知，栖鸦斜照，春树渺空碧。\n文章贯，合整垂云健翼。\n翔鸾底用栖棘。\n要寻玉洞烟霞胜，聊趁麟符蜚檄。\n归骑急。\n看尘袂方清，有恩纶催入。\n凫仙倦。\n相与问孤山，开樽抵掌，一舸画桥侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14972, '青玉案', '张榘', '西风乱叶溪桥树。\n秋在黄花羞涩处。\n满袖尘埃推不去。\n马蹄浓露，鸡声淡月，寂历荒村路。\n身名多被儒冠误。\n十载重来漫如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14973, '浪淘沙', '张榘', '风色转东南。\n翠拥层峦。\n杏花疏雨逗清寒。\n锺阜石城何处是，烟霭漫漫。\n行旆已西关。\n一霎时间。\n芳樽聊复挽馀欢。\n明日断魂分付与，万叠云山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14974, '浪淘沙', '张榘', '雨过暮天南。\n高下青峦。\n小楼燕子话春寒。\n多少夕阳芳草地，雾掩烟漫。\n别恨正相关。\n心上眉间。\n离歌一曲间悲欢。\n後夜月明何处梦，锺阜容山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14975, '水龙吟', '张榘', '暮云低锁荒台，凭阑四望天垂地。\n曼花半夜，蜚香缭绕，昔人曾记。\n往事悠悠，物华非旧，江山仍丽。\n怅斜阳芳草，长安不见，谁共洒、新亭泪。\n开放青峦旧址。\n动骚人、一番词意。\n青油幕里，相忘鱼鸟，水边云际。\n却恨清游，未能追逐，区区僚底。\n问何时，脱了尘埃墨绶，为虚斋醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14976, '西江月', '张榘', '春事三分之二，落花庭院轻寒。\n翠屏围梦宝熏残。\n窗外流莺声乱。\n睡起犹支雪腕，觉来慵整云鬟。\n闲拈乐府凭阑干。\n宿酒才醒一半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14977, '孤鸾', '张榘', '荆溪清晓。\n问昨夜南枝，几分春到。\n一点幽芳，不待陇头音耗。\n亭亭水边月下，胜人间、等闲花草。\n此际风流谁似，有窝诗老。\n向虚檐、淡然索笑。\n任雪压霜欺，精神越好。\n最喜庭除，下映紫兰娇小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14978, '水龙吟', '张榘', '暮天丝雨轻寒，二分春色看看过。\n梅花谢了，苍苔万点，香残粉污。\n犹喜墙头，一枝娇袅，杏腮微露。\n算几回逗晓，朱阑独倚，悄只怕、东风大。\n浮世名缰利锁。\n这区区、要须识破。\n沧波夜月，翠微云树，依然还我。\n重结鸥盟，细听莺语，自歌自和。\n问黄沙飞镞，红尘走马，又还知麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14979, '水龙吟', '张榘', '昼长帘幕低垂，时时风度杨花过。\n梁间燕子，芹随香觜，频沾泥污。\n苦被流莺，蹴翻花影，一阑红露。\n看残梅飞尽，枝头微认，青青子、些儿大。\n谁道洞门无锁。\n翠苔藓、何曾踏破。\n好天良夜，清风明月，正须著我。\n闲展蛮笺，寄情词调，唱成谁和。\n问晓山亭下，山茶经雨，早来开麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14980, '水龙吟', '张榘', '先来花较开迟，怎禁风雪摧残过。\n红英紫萼，从他点缀，翻成沾污。\n一点清香，几多艳，紧藏不露。\n伴杨花散漫，逡巡堆积，纤粟处、妆成大。\n多谢东君造化。\n把群阴、一朝除破。\n千机锦绣，露浓香软，中间坐我。\n嚼徵含商，振金敲玉，埙篪相和。\n问西湖，别有一番桃李，肯同游麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14981, '水龙吟', '张榘', '近家添得园亭，晓山时看飞云过。\n拥石栽梅，疏池傍竹，剪除芜污。\n更喜南墙，杏腮桃脸，含羞微露。\n算莺花世界，都来十亩，规模好、何须大。\n开放两眉上锁。\n把春前、新醅拨破。\n病酒无聊，且容觞客，无多酌我。\n底用歌喉，柳边自有，鸣禽相和。\n逗归来，折得花枝教看，似人人麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14982, '念奴娇', '张榘', '楚湘旧俗，记包黍沈流，缅怀忠节。\n谁挽汨罗千丈雪，一洗些魂离别。\n赢得儿童，红丝缠臂，佳话年年说。\n龙舟争渡，搴旗捶鼓骄劣。\n谁念词客风流，菖蒲桃柳，忆闺门铺设。\n嚼徵含商陶雅兴，争似年时娱悦。\n青杏园林，一樽煮酒，当为浇凄切。\n南薰应解，把君愁袂吹裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14983, '念奴娇', '张榘', '三闾何在，把离骚细读，几番击节。\n蓠蕙椒兰纷江渚，较以艾萧终别。\n清浊同流，醉醒一梦，此恨谁能说。\n忠魂耿耿，只凭天辨优劣。\n须信千古湘流，彩丝缠黍，端为英雄设。\n堪笑儿童浮昌，悲愤翻为嬉悦。\n三叹灵均，竟罹谗网，我独中情切。\n薰风窗户，榴花知为谁裂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14984, '虞美人', '张榘', '金炉就裙纹折。\n香烬低云月。\n玉钿黏唾上眉心。\n不似寿阳檐下、六花清。\n翠禽飞起南枝动。\n惊破西湖梦。\n仗谁为作水龙声。\n吹绽寒葩诗眼、为君青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14985, '虞美人', '张榘', '小蛮才把鸳衾折。\n妆就梳横月。\n探梅不似旧年心。\n却爱窗前纸帐、十分清。\n朔风吹起寒云动。\n午寝都无梦。\n黄昏更被竹枝声。\n唤起醒醒相对、一灯青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14986, '虞美人', '张榘', '龙香浅渍罗屏褶。\n睡思低眉月。\n闲愁闲闷不关心。\n心似窗前梅影、一般清。\n绣帏交掩流苏动。\n一觉华胥梦。\n枕山轻戛宝钗声。\n粉褪香腮零乱、鬓鸦青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14987, '沁园春', '张榘', '静寿先生，笑傲四并，醉眠窝。\n甚一枰棋壤，掉头不顾，同舟风紧，袖手高歌。\n太白词华，更生忠愤，为问山林老得麽。\n须知道，有淮碑未作，浯石当磨。\n年来君子无多。\n试屈指、如公能几何。\n况刍荛公论，新曾推许，冕旒异眷，行见搜罗。\n泽润生民，洗清兵甲，待挽钱塘江上波。\n功名就，访蟠桃把玩，铜狄摩挲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14988, '凯歌', '张榘', '双阁护仙境，万壑渺清秋。\n台躔光动银汉，神秀孕公侯。\n胸次千崖灏气，笔底三江流水，姓字桂香浮。\n十载洞庭月，今喜照扬州。\n捧丹诏，升紫殿，建碧油。\n胡儿深避沙漠，铃阁轻裘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14989, '飞雪满堆山・飞雪满群山', '张榘', '爱日烘晴，梅梢春动，晓窗客梦方还。\n江天万里，高低烟树，四望犹拥螺鬟。\n是谁邀滕六，酿薄暮、同云冱寒。\n却元来是，铃阁露熏，俄忽老青山。\n都尽道、年来须更好，无缘农事，雨涩风悭。\n鹅池夜半，衔枚飞渡，看樽俎折冲间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14990, '绛都春', '张榘', '平山老柳。\n寄多少胜游，春愁诗瘦。\n万叠翠屏，一抹江烟浑如旧。\n晴空栏槛今何有。\n寂寞文章身後。\n唤回奇事，青油上客，放怀樽酒。\n知不。\n全淮万里，羽书静，草绿长亭津堠。\n小队出郊，花底赓酬闲时候。\n和薰筹幕垂春昼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14991, '朝中措', '张榘', '谁云万事转头空。\n春寓不言中。\n底问垂杨在否，年年一度东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14992, '千秋岁', '张榘', '鹤城秋晓。\n又庆生朝到。\n人与月，年年好。\n黑头公相贵，膝下欢娱笑。\n君知否。\n个般福分人间少。\n塞上西风老。\n红入霜前枣。\n日日有，平安报。\n慈颜酡晕浅，一呷金杯小。\n香缭绕。\n寿星明处台星照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14993, '青玉案', '张榘', '严城寂寞山缭绕。\n觉寒透、貂裘峭。\n云压江天风破晓。\n飞琼万顷，看来浑似，泽国芦花老。\n玉山不怕频频倒。\n要笔阵、纵横快挥扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14994, '青玉案', '张榘', '少时贪看琼林绕。\n任马上、寒威峭。\n昨暮六花飞逗晓。\n拥衾慵起，鬓丝笼帽，顿觉年来老。\n朱阑翠竹枝枝倒。\n把玉、棱层趁风扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14995, '青玉案', '张榘', '龙香熏被罗屏绕。\n任窗外、风儿峭。\n鸳枕梦回鸡唱晓。\n丫鬟惊笑，琼枝低亚，错认梅花老。\n红炉兽炭装还倒。\n强梳洗、忙将黛眉扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14996, '沁园春', '张榘', '思昔买臣，怀绶会稽，年犹五旬。\n算初无功用，维持国事，但将富贵，夸耀时人。\n未若先生，方当强仕，掌握长淮百万军。\n难摹写，是擎天拄地，纬武经文。\n河滨。\n胡马嘶春。\n便密运机筹出万全。\n拥熊旗指授，鹰扬や啖，毡裘胆落，鼠逸狐奔。\n褒诏飞来，威名加盛，从此不须关玉门。\n归朝也，看云台画像，金鼎调元。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14997, '金缕曲・贺新郎', '张榘', '社新相识。\n恍瞻君、丰神气貌，飘然仙白。\n笔底三江鲸浪注，胸次一瓯冰雪。\n怎不做、龙门上客。\n坎止流行元无定，敢一朝、挨却尘泥迹。\n且剩把，锦云织。\n试看自古贤侯伯。\n一时间、失虽暂失，得还终得。\n儋石空无君家事，百万付之一掷。\n渐养就、抟风鹏翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14998, '贺新凉・贺新郎', '张榘', '襟度天为侣。\n价平生、放浪江湖，浮云行住。\n倒挽峡流归笔底，衮衮二并四具。\n何尚友、沧波鸥鹭。\n藻黻皇猷君能事，况贤书、两度登天府。\n急著手，佐明主。\n晴风一舸来瓜步。\n剪灯花、樽酒论诗，顿忘羁旅。\n逗晓蛮笺传金缕，一片瑰词绮语。\n甚独茧、抽成长绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (14999, '醉落魄・一斛珠', '张榘', '瑶姬妙格。\n冰姿微带霜痕拆。\n一般恼杀多情客。\n风弄横枝，残月半窗白。\n孤山仙种曾移得。\n结根久傍王猷宅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15000, '摸鱼儿', '张榘', '猛思量、窝初度，鲁云呈瑞时节。\n平山杨柳苍茫外，犹是乡关明月。\n春漏泄。\n定知有、梅花先向江南发。\n烟波梦阔。\n谩约住西风，呼将塞雁，把酒为君说。\n君看取，世道羊肠屈摺。\n依然熟路轻辙。\n林泉暂洗经纶手，桐柏夜香熏彻。\n趋魏阙。\n指天上星辰，平步仪清切。\n蟠桃未结。\n待做著功名，却寻曼倩，相与带花折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15001, '瑞鹤仙', '张榘', '碧油推上客。\n有神机沈密，参运帷幄。\n威声际沙漠。\n庆云飞川泳，和熏三白。\n霄渊鬲。\n甚探梅、也来相约。\n更谁怜久客，泥深穿履，栖栖东郭。\n农麦。\n年来管好，禾黍离离，讵忘关洛。\n风高水涸。\n多少事、待韬略。\n看鹅池夜渡，黎明飞捷，儿辈未觉。\n便冲寒，铁骑横驱，汛扫六合。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15002, '沁园春', '张榘', '绿野归来，筇杖角巾，岂不快哉。\n有清泉白石，东西岩岫，翠阴红影，高下楼台。\n况是蕤宾，槐庭暑薄，照眼葵榴次第开。\n轻熏里，翦香蒲为寿，一笑传杯。\n栽培。\n多少英材。\n更霖雨、看看遍九垓。\n算支撑厦屋，正资梁栋，调和钧鼎，须用盐梅。\n旒冕兴思，绅望，应有天边丹诏催。\n依还是，为苍生一起，重位元台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15003, '木兰花慢', '张榘', '豆花轻雨霁，更七日、是中秋。\n记分野三台，家山双阙，孕秀名流。\n平生佐时大略，有忠勤、一念等伊周。\n十载清风楚泽，三年明月扬州。\n须知万灶出貔貅。\n智勇迈前猷。\n自向来颖，□番平海，胆落毡裘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15004, '好事近', '张榘', '素壁走龙蛇，难觅醉翁真迹。\n惟有断岗衰草，是几番经历。\n紫萸黄菊又西风，同作携壶客。\n清兴未阑归去，负晴空明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15005, '摸鱼儿', '张榘', '望神京、目断烟草，青天长剑频倚。\n香街十里朱帘月，空想当年华丽。\n堪叹处。\n渺沙霭蒹葭，咿ン雁声起。\n平山谩记。\n怅杨柳春风，晴空栏槛，陈迹总非是。\n重阳好，红叶黄华满地。\n良辰美景如此。\n青油幕府传芳，苒苒露琼花气。\n还更喜。\n看玉阃规恢，笑骋伊吾志。\n尘清北冀。\n便向关洛联镳，巍巍冠佩，麟阁画图里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15006, '唐多令', '张榘', '斜日淡芜烟。\n重阳又一年。\n怅垂杨、几度飞绵。\n只把晴空山色看。\n多少恨、倩谁笺。\n沙霭暗中原。\n横戈谁夜眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15007, '贺新凉・贺新郎', '张榘', '萸菊香凝雾。\n记重阳、才经三日，悬朱户。\n紫殿玉垣称寿，潋滟琼花清露。\n正万里、尘清淮浦。\n地宝从来标瑞应，甚新曾、秀出金芝树。\n正此处，诞申甫。\n人间小住千秋岁。\n画堂深、彩侍怡声，慈颜笑语。\n况是加恩封大国，锦诰鸾翔凤舞。\n便娱侍、鱼轩沙路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15008, '贺新凉・贺新郎', '张榘', '匹马锺山路。\n怅年来只解，邮亭送人归去。\n季子貂裘尘渐满，犹是区区羁旅。\n谩空有、剑锋如故。\n髀肉未消仪舌在，向樽前、莫洒英雄泪。\n鞭未动，酒频举。\n西风乱叶长安树。\n叹离离、荒宫废苑，几番禾黍。\n云栈萦纡今平步，休说襄淮乐土。\n但衮衮江涛东注。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15009, '满江红', '张榘', '淮海波澄，湛桂影、半规凉月。\n又还是、中秋相近，垂弧时节。\n纶诰飞来宸眷重，彩衣著处慈颜悦。\n注紫清、花露入瑶卮，琼香滑。\n挥羽扇，持旄钺。\n鲸海浪，阴山雪。\n看威声到处，遐冲都折。\n沙溪远标铜柱界，关河尽补金瓯缺。\n庆君臣、千载会风云，看伊说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15010, '浪淘沙', '张榘', '春梦草茸茸。\n愁雨愁风。\n对花须拚酒频中。\n莫遣枝头银烛暗，辜负嫣红。\n推起簿书丛。\n何苦匆匆。\n悭吟却讶少陵公。\n天定为花开一笑，日上篱东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15011, '浪淘沙', '张榘', '烟缕暗蒙茸。\n杨柳轻风。\n雨声多在夜窗中。\n春水渐生春事去，流尽残红。\n新笋绿丛丛。\n莺语匆匆。\n一樽同酹定林公。\n十里长松青未了，山北山东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15012, '摸鱼儿', '张榘', '正莓墙、柳绵低度，枝头红紫飞尽。\n阴涨绿冰钿碎，麝兰成阵。\n仙骨嫩。\n悦姑射瑶姬，青游琼苑。\n风前有恨。\n也一似宫梅，飘香坠粉，轻点寿阳鬓。\n梨花雪，讲道全无清韵。\n何曾流到春晚。\n柔条不受真珠露，滴沥紫檀心晕。\n芳又润。\n待放金樽，拚作通宵饮。\n日高慵困。\n任翠幄低云，玉薰泛梦，路入醉乡稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15013, '木兰花慢', '张榘', '渐稠红飞尽，早绿、遍林梢。\n正池馆轻寒，杨花飘絮，草色萦袍。\n天香夜浮院宇，看亭亭、雨槛渍春膏。\n趁取芳时胜赏，莫将年少轻抛。\n鞭鞘。\n驱放马啼高。\n世事一秋毫。\n便飞书倥偬，运筹闲暇，何害推敲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15014, '祝英台近', '张榘', '柳绵稀，桃锦淡，春事在何许。\n一种华，天香渍冰露。\n嫩苞叠叠湘罗，红娇紫妒。\n翠葆护、西真仙侣。\n试听取。\n更饶十日看承，霞腴污尘土。\n池馆轻寒，次第少风雨。\n好趁油幕清闲，重开芳醑。\n莫孤负、莺歌蝶舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15015, '满江红', '张榘', '玉垒澄秋，又还近、桂华如璧。\n算六载、筹边整暇，几多功绩。\n铁壁连云东海重，惊波截断狂鲵翼。\n把向来、捣颍旧规模，平淮北。\n经济妙，谁知得。\n都总是，诗书力。\n有召公家法，范公胸臆。\n赫赫勋名俱向上，绵绵福寿宜无极。\n著莱衣、辉映衮衣荣，恢霖泽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15016, '鹧鸪天', '张榘', '饱挹台城白露秋。\n又骑黄鹄上江州。\n恩波浩荡三千里，多少人家愿借留。\n□寿，菊香浮。\n姓名还喜到宸旒。\n片□□□□□□，□振□□□下流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15017, '安庆摸・摸鱼儿', '张榘', '渺长江、浩无今古，悠悠经几流景。\n桥家松竹知何在，寂历丹枫如锦。\n行阵整。\n想斗舰连艘，谈笑烟灰冷。\n寒光万顷。\n算只有当年，暮天霜月，惨澹照山影。\n元戎队，画角梅花缓引。\n楼船飞渡波稳。\n中流击楫酬初志，此去君王高枕。\n应暗省。\n使万里尘清，谁逊周公瑾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15018, '水调歌头', '刘克逊', '解变西体，一赋冠群英。\n清风峡畔，至今堂已读书名。\n富贵轻於尘土，孝义高於山岳，惜不大其成。\n陵谷纵迁改，草木亦光荣。\n与仇香，穿阮屐，试同登。\n石龛虽窄，可容一几短檠灯。\n千仞苍崖如削，四面翠屏不断，云雾镇长生。\n最爱岩前水，犹作诵弦声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15019, '金缕歌・贺新郎', '王广文', '辜负东风约。\n忆曾将、淮南草木，笔端笼络。\n后土祠中明月夜，忽有瑶姬跨鹤。\n迥不比、水仙低弱。\n天上人间惟一本，倒千锺、琼露花前酌。\n追往事，怎忘却。\n移根应费仙家药。\n漫回头、关山信断，堡城笳作。\n问讯而今平安否，莫遣玉箫惊落。\n但画卷、依稀描著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15020, '点绛唇', '宋自道', '山雨初晴，馀寒犹在东风软。\n满庭苔藓。\n青子无人见。\n好客不来，门外芳菲遍。\n难消遣。\n流莺声啭。\n坐看芭蕉展。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15021, '蓦山溪', '宋自逊', '壶山居士，未老心先懒。\n爱学道人家，办竹几、蒲团茗碗。\n青山可买，小结屋三间，开一径，俯清溪，修竹栽教满。\n客来便请，随分家常饭。\n若肯小留连，更薄酒、三杯两盏。\n吟诗度曲，风月任招呼，身外事，不关心，自有天公管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15022, '沁园春', '宋自逊', '归去来兮，田园将芜，云胡不归。\n既有诗千首，如斯者少，行年七十，从古来稀。\n地阙东南，天倾西北，人事何缘有足时。\n江湖上，转不如前日，步步危机。\n石屏自有柴扉。\n占海岸、潮头岸一矶。\n唤彩衣孙子，携壶挈，白头翁媪，举桉齐眉。\n身外声名，世间梦幻，万事一酲无是非。\n书来往，都不须长语，直写心期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15023, '贺新郎', '宋自逊', '唤起东坡老。\n问雪堂、几番兴废，斜阳衰草。\n一月有钱三十块，何苦抽身不早。\n又底用、北门藻。\n儋雨蛮烟添老色，和陶诗、翻被渊明恼。\n到底是，忘言好。\n周郎英发人间少。\n谩依然、乌鹊南飞，山高月小。\n岁月堂堂留不住，此世何时是了。\n算不满、英雄一笑。\n我有丰淮千斗酒，把新愁、旧恨都倾倒。\n三弄笛，楚天晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15024, '贺新郎', '宋自逊', '灵鹊桥初就。\n记迢迢、重湖风浪，去年时候。\n岁月不留人易老，万事茫茫宇宙。\n但独对、西风搔首。\n巧拙岂关今夕事，奈痴儿、呆女流传谬。\n添话柄，柳州柳。\n道人识破灰心久。\n只好风、凉月佳时，疏狂如旧。\n休笑双星经岁别，人到中年已後。\n云雨梦、可曾常有。\n雪藕调冰花熏茗，正梧桐、雨过新凉透。\n且随分，一杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15025, '满江红', '宋自逊', '举扇西风，又十载、重游秋浦。\n对旧日、江山错愕，鬓丝如许。\n世事兴亡空感慨，男儿事业谁堪数。\n被老天、开眼看人忙，成今古。\n江上路，喧鼙鼓。\n山中地，纷豺虎。\n谩乾坤许大，著身何处。\n名利等成狂梦寐，文章亦是闲言语。\n赖双投、酒熟蟹螯肥，忘羁旅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15026, '西江月', '宋自逊', '何敢笑人干禄，自知无分弹冠。\n只将贫贱博清闲。\n留取书遮老眼。\n世上风波任险，门前路径须宽。\n心无妄想梦魂安。\n万事鹤长凫短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15027, '昼锦堂', '宋自逊', '荷叶龟游，庭皋鹤舞，应是秋满淮涯。\n昨夜将星明处，彷佛峨眉。\n干戈已净银河淡，尘沙不动翠烟微。\n邦人道，半月中秋，当歌不饮何为。\n谁知心事远，但感慨登临，白羽频挥。\n恨不明朝出塞，猎猎旌旗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15028, '昼锦堂', '黄载', '丽景融晴，浮光起昼，玉妃信意寻春。\n一笑酒杯翻手，满地祥云。\n宝台艳蹙文绡帕，郎官娇舞郁金裙。\n嫣然处，况是生香微湿，腻脸馀醺。\n暖烘肌欲透，愁日炙还销，风动成尘。\n细为品归雪调，度与朱唇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15029, '隔浦莲・隔浦莲近拍', '黄载', '瑶妃香透袜冷。\n伫立青铜镜。\n玉骨清无汗，亭亭碧波千顷。\n云水摇扇影。\n炎天永。\n一国清凉境。\n晚妆靓。\n微酣不语，风流幽恨谁省。\n沙鸥少事，看到睡鸳双醒。\n兰棹歌遥隔浦应。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15030, '洞仙歌', '黄载', '吴宫故墅，是天开图画。\n缥缈层云出飞榭。\n隐隐楼空翠，水绕芜城，平畴迥，点染霜林凋谢。\n越来溪上雁，声切阑干，似觅胥门怨吴霸。\n属镂沈，香溪断，梦散云空，千年外、等是渔樵闲话。\n但极目荒台郁苍烟，衰草里、又还夕阳西下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15031, '孤鸾', '黄载', '冰心孤寂。\n恋几插灵峰，半泓寒碧。\n骨瘦和衣薄，清绝成愁极。\n萧然满身是雪，怕人知、镜中消息。\n独向百花梦外，自一家春色。\n记罗浮幽梦浑如昔。\n是浸眼鲸波，倚云丹壁。\n夜醉空山酒，叫裂横霜笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15032, '东风第一枝', '黄载', '迅影凋年，嫩晴贳暖，意行问讯春色。\n不知春在谁家，闯香幔拢玉勒。\n一枝竹外，似欲诉、经年相忆。\n奈情多、难剪愁来，寂寞水寒烟碧。\n吟正好、悲笳唤恨，酒正、夕阳催客。\n殷勤片月飞来，更随暗香细索。\n横斜瘦影，看尽未开时消息。\n为春来，还怕春多，肠断夜阑霜笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15033, '谒金门', '王平子', '书一纸。\n小砑吴笺香细。\n读到别来心下事。\n蹙残眉上翠。\n怕落傍人眼底。\n握向抹胸儿里。\n针线不收拾起。\n和衣和闷睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15034, '喜迁莺', '俞文豹', '小梅幽绝。\n向冰谷深深，云阴幂幂。\n饱阅年华，惯谙冷淡，只恁清风骨。\n任他万红千紫，句引狂蜂游蝶。\n惟只共、竹和松，同傲岁寒霜雪。\n喜得。\n化工力。\n移根上苑，向阳和培植。\n题名还经，孤山处士，许共高人攀折。\n一枝垂欲放，只等春风披拂。\n待叶底、结青青，恰是和羹时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15035, '满江红', '赵希迈', '三十年前，爱买剑、买书买画。\n凡几度、诗坛争敌，酒兵取霸。\n春色秋光如可买，钱悭也不曾论价。\n任粗豪、争肯放头低，诸公下。\n今老大，空嗟讶。\n思往事，还惊诧。\n是和非未说，此心先怕。\n万事全将飞雪看，一闲且问苍天借。\n乐馀龄、泉石在膏肓，吾非诈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15036, '八声甘州', '赵希迈', '寒云飞万里，一番秋、一番搅离怀。\n向隋堤跃马，前时柳色，今度蒿莱。\n锦缆残香在否，枉被白鸥猜。\n千古扬州梦，一觉庭槐。\n歌吹竹西难问，拚菊边醉著，吟寄天涯。\n任红楼踪迹，茅屋染苍苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15037, '念奴娇', '吴渊', '我来牛渚，聊登眺、客里襟怀如豁。\n谁著危亭当此处，占断古今愁绝。\n江势鲸奔，山形虎踞，天险非人设。\n向来舟舰，曾扫百万胡羯。\n追念照水然犀，男儿当似此，英雄豪杰。\n岁月匆匆留不住，鬓已星星堪镊。\n云暗江天，烟昏淮地，是断魂时节。\n栏干捶碎，酒狂忠愤俱发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15038, '水调歌头', '吴渊', '太白已仙去，诗骨此山藏。\n胸中锦绣如屋，都乞与东皇。\n碎翦杏花千树，浓抹胭脂万点，妖艳断人肠。\n晓露沐春色，晴日涨风光。\n孤村路，逢休暇，共徜徉。\n酒旗斜处，□□一簇几红妆。\n暂息江头烽火，无奈鬓边霜雪，聊复放疏狂。\n倚俟玉壶竭，未肯宝鞭扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15039, '沁园春', '吴渊', '喜我新归，逢戎初度，关情更深。\n正昼掩柴扉，□寻隐遁，□舒槐府，戎正经纶。\n白石清泉，紫枢黄阁，□□□□□□□。\n□□□，□弟为宰相，兄作闲人。\n南园借我登临。\n都不怕近前丞相。\n但曳履扶筇，堪怜独步，携壶载酒，每叹孤斟。\n七Α开颜，六旬屈指，风雨对床频上心。\n殷勤祝，道何时回首，及早抽身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15040, '沁园春', '吴渊', '十月江南，一番春信，怕凭玉栏。\n正地连边塞，角声三弄，人思乡国，愁绪千般。\n草草村墟，疏疏篱落，犹记花间曾卓庵。\n茶瓯罢，问几回吟绕，冷淡相看。\n堪怜。\n影落溪南。\n又月午无人更漏三。\n虽虚林幽壑，数枝偏瘦，已存鼎鼐，一点微酸。\n松竹交盟，雪霜心事，断是平生不肯寒。\n林逋在，倩诗人此去，为语湖山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15041, '满江红', '吴渊', '秋後锺山，苍翠色、可供餐食。\n登临处、怨桃旧曲，催梅新笛。\n江近苹风随汛落，峰高松露和云滴。\n叹头童、齿豁已成翁，犹为客。\n老怀抱，非畴昔。\n欢意思，须寻觅。\n人间世、假饶百岁，苦无多日。\n已没风云豪志气，只思烟水闲踪迹。\n问何年、同老转溪滨，渔钩掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15042, '满江红', '吴渊', '投老未归，太仓粟、尚教蚕食。\n家山梦、秋江渔唱，晚风牛笛。\n别墅流风惭莫继，新亭老泪空成滴。\n笑当年、君作主人翁，同为客。\n紫燕泊，犹如昔。\n青鬓改，难重觅。\n记携手、同游此处，恍如前日。\n且更开怀穷乐事，可怜过眼成陈迹。\n把忧边、忧国许多愁，权抛掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15043, '满江红', '曾寓轩', '细数班行，阿谁是、调元手段。\n君不见、当涂往岁，饥民流散。\n天幸立庵来歇马，留心济粜无遗算。\n未须臾、千里复安居，无愁叹。\n公与相，天皆愿。\n天施报，如符券。\n看青州阴骘，富公公案。\n已筑新堤旌异数，便膺虚席非常眷。\n待明年、弧失再垂门，蒙宣劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15044, '沁园春', '曾寓轩', '运在东南，千古金陵，帝王旧州。\n看地雄江左，蟠龙踞虎，事专阃外，缓带轻裘。\n惟断乃成，非贤罔任，真是富韩文范俦。\n难兄弟，久齐名天壤，谁劣谁优。\n冕旒。\n似欲兼收。\n命四辈传宣难借留。\n记适遵昆季，迭行沙路，育充伯仲，并在金瓯。\n或後或先，相推相逊，等是延陵德泽流。\n称觞了，便促装西上，同奉宸游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15045, '南乡子', '吴淇', '十日借春留。\n芍药荼シ不解愁。\n检点笙歌催酿酒，西州。\n有谪仙人烂熳游。\n白鹭自芳洲。\n咫尺红云最上头。\n万古沧江波不尽，风流。\n谁似监州旧姓牟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15046, '喜迁莺', '杜东', '生申华席。\n便占却新春，前头五日。\n椒颂梅英，金幡彩缕，好个早春天色。\n使君以仁得寿，和气融春无极。\n人总道，是阳春有脚，恩浮南国。\n应看，丹诏下，昨夜天边，初报春消息。\n日转黄麾，风生绛伞，春殿龙颜咫尺。\n共庆一堂嘉会，万宇同沾春泽。\n祝眉寿，便从今细数，好春千亿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15047, '清平乐', '赵汝迕', '初莺细雨。\n杨柳低愁缕。\n烟浦花桥如梦里。\n犹记倚楼别语。\n小屏依旧围香。\n恨抛薄醉残妆。\n判却寸心双泪，为他花月凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15048, '瑞鹤仙', '楼采', '冻痕销梦草。\n又招得春归，旧家池沼。\n园扉掩寒峭。\n倩谁将花信，遍传深窈。\n追游趁早。\n便栽却、轻衫短帽。\n任残梅、飞满溪桥，和月醉眠清晓。\n年小。\n青丝纤手，彩胜娇鬟，赋情谁表。\n南楼信杳。\n江云重，雁归少。\n记冲香嘶马，流红回岸，几度绿杨残照。\n想暗黄，依旧东风，灞陵古道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15049, '玉漏迟', '楼采', '絮花寒食路。\n晴丝日，绿阴吹雾。\n客帽欺风，愁满画船烟浦。\n彩柱秋千散後，怅尘锁、燕帘莺户。\n从间阻。\n梦云无准，鬓霜如许。\n夜永绣阁藏娇，记掩扇传歌，翦灯留语。\n月约星期，细把花须频数。\n弹指一襟幽恨，谩空趁、啼鹃声诉。\n深院宇。\n黄昏杏花微雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15050, '法曲献仙音', '楼采', '花匣么弦，象奁双陆，旧日留欢情意。\n梦到银屏，恨裁兰烛，香篝夜阑鸳被。\n料燕子重来地。\n桐阴锁窗绮。\n倦梳洗。\n晕芳钿、自羞鸾镜，罗袖冷，烟柳画栏半倚。\n浅雨压荼シ，指东风、芳事馀几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15051, '好事近', '楼采', '人去玉屏间，逗晓柳丝风急。\n帘外杏花细雨，春红愁湿。\n单衣初试麴尘罗，中酒病无力。\n应是绣床慵困，倚秋千斜立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15052, '二郎神', '楼采', '露床转玉，唤睡醒、绿云梳晓。\n正倦立银屏，新宽衣带，生怯轻寒料峭。\n闷绝相思无人问，但怨入、墙阴啼鸟。\n嗟露屋锁春，晴风喧昼，柳轻梅小。\n人悄。\n日长谩忆，秋千嬉笑。\n怅烬冷炉薰，花深莺静，帘箔微红醉袅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15053, '玉楼春', '楼采', '东风破晓寒成阵。\n曲锁沈香簧语嫩。\n凤钗敲枕玉声圆，罗袖拂屏金缕褪。\n云头雁影占来信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15054, '失调名', '楼采', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15055, '失调名', '楼采', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15056, '好事近', '雷应春', '梅片作团飞，雨外柳丝金湿。\n客子短篷无据，倚长风挂席。\n回头流水小桥东，烟扫画楼出。\n楼上有人凝伫，似旧家曾识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15057, '沁园春', '雷应春', '问讯故园，今如之何，还胜昔无。\n想旧耘兰蕙，依然葱茜，新栽杨柳，亦已扶疏。\n韭本千畦，芋根一亩，雨老烟荒谁为锄。\n难忘者，是竹吾爱甚，梅汝知乎。\n茅亭低压平湖。\n有狎鹭驯鸥尚可呼。\n把绛纱准拟，新官到也，寒毡收拾，贱子归欤。\n略整柴门，更芟草径，惟有幽人解枉车。\n丁宁著，与做添棋局，砌换茶垆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15058, '西江月', '包荣父', '雅意浯亭宽碧，何心禁路宽华。\n芝兰玉树侍臣家。\n一段洛滨图画。\n庆事两年亲见，今年福寿堪夸。\n更从头上人添些。\n却是八千岁也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15059, '千秋岁', '游文仲', '今年为寿，都道是、不比寻常时节。\n预庆我公八帙，来献新词一阕。\n算得年时，恰当尚父，入相周西伯。\n亲逢盛事，宗孙也五十八。\n一门富贵荣华，盈床牙笏，何待拈来说。\n且上祝龟龄鹤算，从此千千百百。\n笑道儿时，风流丹篆，写向龙驹额。\n更将彩笔，十字头上添一丿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15060, '念奴娇', '刘清夫', '乱山深处，见寒梅一朵，皎然如雪。\n的妍姿羞半吐，斜映小窗幽绝。\n玉染香腮，酥凝冷艳、容态天然别。\n故人虽远，对花谁肯轻折。\n疑是姑射神仙，幔亭宴罢，迤逦停瑶节。\n爱此溪山供秀润，饱玩洞天风月。\n万石丛中，百花头上，谁与争高洁。\n粗桃俗李，不须连夜催发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15061, '沁园春', '刘清夫', '浅碧芙蓉，素艳亭亭，前身阿娇。\n记湘滨露冷，酥容倍洁，华清水滑，酒晕全消。\n瑶剪丰肥，云翻碎萼，白羽鲜明时自摇。\n风流处，是古香幽韵，时度仙飙。\n琼枝璧月清标。\n对千朵婵娟倾翠瓢。\n况水晶台榭，低迷净绿，冰霜词调，隐约轻桡。\n细认金房，锺奇孕秀，已觉青衿横素腰。\n西风晚，看花开十丈，玉井非遥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15062, '金菊对芙蓉', '刘清夫', '浅拂春山，慢横秋水，玉纤闲理丝桐。\n按清冷繁露，淡伫悲风。\n素弦瑶轸调新韵，颤翠翘、金簇芙蓉。\n叠蠲重锁，轻挑慢摘，特地情浓。\n泛商刻羽无穷。\n似和鸣鸾凤，律应雌雄。\n问高山流水，此意谁同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15063, '水调歌头', '刘清夫', '残腊卷愁去，春至莫闲愁。\n荣枯会有成说，无处著机谋。\n身世石中敲火，富贵草头垂露，何用苦贪求。\n三尺布衣剑，千载赤松游。\n忆亲朋，方角，总白头。\n羊肠世路，莫莫且休休。\n选甚范侯高爵，遮莫陶公钜产，争似五湖舟。\n万事付蜗角，止坎谩乘流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15064, '玉楼春', '刘清夫', '柳梢绿小眉如印。\n乍暖还寒犹未定。\n惜花长是为花愁，酒却嫌添酒病。\n蝇头蜗角都休竞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15065, '贺新郎', '祝穆', '此木生林野。\n自唐家、丝纶置阁，托根其下。\n长伴词臣挥帝制，因号紫微堪诧。\n常缥缈、紫微仙驾。\n料想紫微垣降种。\n紫微郎、况是名同者。\n兼二美，作佳话。\n一株乃肯临茅舍。\n肌肤薄、长身挺立，扶疏潇洒。\n定怯麻姑爬痒爪，只许素商陶冶。\n擎绛雪、柔枝低亚。\n我忆香山东坡老，只小诗、便为增声价。\n後当有，继风雅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15066, '沁园春', '祝穆', '自有东阳，锦水城山，几千百年。\n记往时仅说，拥麾刻郡，而今创见，持橐甘泉。\n地脉方兴，天荒欲破，还为盐梅生钜贤。\n清和候，正风薰日永，作地行仙。\n题舆小驻樵川。\n常只恐祖生先著鞭。\n算谁从井落，重新疆理，谁从襄岘，一洗腥膻。\n幕府归来，未应袖手，行有诏书来九天。\n勋名就，使吾乡夸诧，盛事流传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15067, '念奴娇', '周文谟', '棋声特地，把十年心事，恍然惊觉。\n杨柳楼头歌舞地，长记一枝纤弱。\n破镜重圆，玉环犹在，鹦鹉言如昨。\n秦筝别後，知他几换弦索。\n谁念顾曲周郎，樽前重见，千种愁难著。\n犹胜玄都人去後，空怨残红零落。\n绿叶成阴，桃花结子，枉恨东风恶。\n盈盈泪眼，见人欲下还阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15068, '八声甘州', '李好古1', '壮东南、飞观切云高，峻堞缭波长。\n望蔽空楼橹，重关警柝，跨水飞梁。\n百万貔貅夜筑，形胜隐金汤。\n坐落诸蕃胆，扁榜安江。\n游子凭阑凄断，百年故国，飞鸟斜阳。\n恨当时肉食，一掷赌封疆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15069, '八声甘州', '李好古1', '古扬州、壮丽压长淮，形胜绝东南。\n问竹西歌吹，蜀冈何许，杨柳。\n行乐谁家年少，两两更三三。\n知我江南客，走马来看。\n过却长亭烟树，云山点点，烟浪漫漫。\n料桐花飞尽，夜合绕阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15070, '江城子', '李好古1', '从来难翦是离愁。\n这些愁。\n几时休。\n才趁风樯，千里到扬州。\n见说苍茫云海外，天杳杳，水愁愁。\n男儿三十敞貂裘。\n强追游。\n梦魂羞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15071, '江城子', '李好古1', '平沙浅草接天长。\n路茫茫。\n几兴亡。\n昨夜波声，洗岸骨如霜。\n千古英雄成底事，徒感慨，谩悲凉。\n少年有意伏中行。\n馘名王。\n扫沙场。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15072, '水调歌头', '李好古1', '历历江南树，半在水云间。\n不须回首，且来著眼向淮山。\n过尽金山晕碧，望断焦山空翠，杨柳绕江边。\n此意无人会，独自久凭阑。\n夜吹箫，朝问法，记坡仙。\n只今何许，当时三峡倒词源。\n水调翻成新唱，高压风流前辈，使我百忧宽。\n有酒更如海，容我醉时眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15073, '酹江月・念奴娇', '李好古1', '西风横荡，渐霜馀黄落，空山乔木。\n照水依然冰雪在，耿耿梅花幽独。\n抖擞征尘，扶携短策，步绕沧浪曲。\n怅然心事，浮生翻覆陵谷。\n试向商乐亭前，冷风台上，把酒招黄鹄。\n四十男儿当富贵，谁念漂零南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15074, '酹江月・念奴娇', '李好古1', '平生英气，叹年来、都付山林泉石。\n不作云霄轩冕梦，只拟纶竿蓑笠。\n见说湖阴，飞飞鸥鹭，半是君曾识。\n梅花时节，试来相与寻觅。\n休谩汨没尘埃，浮生能几，镜里催华发。\n趁取尊前强健在，莫负花前倾碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15075, '贺新郎', '李好古1', '人物风流远。\n忆当年、江东跌宕，知音南阮。\n惯倚胡床闲寄傲，妥腹难凭琴桉。\n妙制拥、银蟾光满。\n千古不传谁好事，忽茂陵、金碗人间见。\n轻擘动，思无限。\n长安钗鬓春横乱。\n仿规模、红条带拨，媚深情浅。\n安识高山流水趣，儿女空传恩怨。\n使得似、支郎萧散。\n听到三闾沈绝处，惨悲风、摇落寒江岸。\n不肠断，也肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15076, '清平乐', '李好古1', '清淮北去。\n千里扬州路。\n过却瓜州杨柳树。\n烟水重重无数。\n柁楼才转前湾。\n云山万点江南。\n点点尽堪肠断，行人休望长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15077, '清平乐', '李好古1', '瓜州渡口。\n恰恰城如斗。\n乱絮飞钱迎马首。\n也学玉关榆柳。\n面前直控金山。\n极知形胜东南。\n更愿诸公著意，休教忘了中原。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15078, '浣溪沙', '李好古1', '为怯云挟暑飞。\n嫩凉故故著征衣。\n江风吹雨过楼西。\n未必男儿生不遇，时来咳唾是珠玑。\n功名终岂壮心违。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15079, '菩萨蛮', '李好古1', '东园映叶梅如豆。\n西园扑地花铺绣。\n春水晓来深。\n日华娇漾金。\n带烟穿径竹。\n步入飞虹曲。\n何处早莺啼。\n曲桥西复西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15080, '菩萨蛮', '李好古1', '东风一夜都吹损。\n昼长春佳人困。\n满地委香钿。\n人情谁肯怜。\n诗人犹爱惜。\n故故频收拾。\n云彩缕丝丝。\n娇娆忆旧时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15081, '菩萨蛮', '李好古1', '纳红销翠春风里。\n精神一撮金莲底。\n不是睡杨妃。\n绿珠娇小儿。\n一般娇绝处。\n半带疏疏雨。\n不解吐繁香。\n却教人断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15082, '酹江月・念奴娇', '阮秀实', '汉庭用老，想君王、也忆潜郎白首。\n底事煌煌金玉节，奔走天涯许久。\n江右风流，湖南清绝，要借诗翁手。\n明年七十，人间此事希有。\n固是守约堂间，鲂斋亭下，要种归来柳。\n只恐夜深思贾傅，便有锋车迎候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15083, '昼锦堂', '刘子寰', '思纵步，时自驻篮舆，策杖荒郊。\n为有柔荑可坐，野菜时挑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15084, '解语花', '刘子寰', '龙沙殿腊，兔苑留寒，花照冰壶夜。\n乱山平野。\n装珠树满眼，买春无价。\n墙头苑下。\n浑不见、桃夭杏冶。\n疑趁风、庾岭寒梅，触处都飘谢。\n吹面峭寒未怕。\n览瑶池万里，飞观高榭。\n霓旌鹤驾。\n歌黄竹、胜跃踏青骄马。\n峰峦似画。\n但点缀、片时相借。\n惊望中、玉宇琼楼，残溜空鸳瓦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15085, '玉漏迟', '刘子寰', '翠草侵园径。\n阴阴夏木，鸣鸠相应。\n纵目江天，窈窈雨昏烟暝。\n屋角黄梅乍熟，听落颗、时敲金井。\n深院静。\n闲阶自长，花砖苔晕。\n楼居簟枕清凉，尽永日阑干，与谁同凭。\n旧社鸥盟，零落断无音信。\n辽鹤追思旧事，向华表、空吟遗恨。\n萦念损。\n休怪暮年多病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15086, '玉漏迟', '刘子寰', '暮天初过。\n雨凄清，顿觉今年秋早。\n夜景虚明，仿佛露华清晓。\n蕙草繁花竞吐，向暗里、幽香缥缈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15087, '醉蓬莱', '刘子寰', '访莺花陈迹，姚魏遗风，绿阴成幄。\n尚有馀香，付宝阶红药。\n淮海维阳，物华天产，未觉输京洛。\n时世新妆，施朱傅粉，依然相若。\n束素腰纤，捻红唇小，鄣袖娇看，倚阑柔弱。\n玉佩琼琚，劝王孙行乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15088, '阮郎归', '刘子寰', '长条袅袅串红绡。\n无风时自摇。\n十分妖艳更苗条。\n春情态娇。\n风影舞，露痕潮。\n买来和蝶饶。\n故园愁绝楚宫腰。\n相逢恨怎销。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15089, '好事近', '刘子寰', '秋色到东篱，一种露红先占。\n应念金英冷淡，摘胭脂浓染。\n依稀十月小桃花，霜蕊破霞脸。\n何事渊明风致，却十分妖艳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15090, '齐天乐', '刘子寰', '雅歌堂下新堤路。\n柳外行人相语。\n碧藕开花，金桃结子，三见使君初度。\n楼台北渚。\n似画出西湖，水云深处。\n彩双飞，水亭开宴近重午。\n溪蒲堪荐绿醑。\n幔亭何惜，为曾孙留住。\n碧水吟哦，沧洲梦想，未放舟横野渡。\n维申及甫。\n正夹辅中兴，擎天作柱。\n愿祝嵩高，岁添长命缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15091, '花发沁园春', '刘子寰', '换谱伊凉，选歌燕赵，一番乐事重起。\n花新笑靥，柳软纤腰，济楚众芳围里。\n年年佳会。\n长是傍、清明天气。\n正魏紫衣染天香，蜀妆红破春睡。\n一簇猩罗凤翠。\n遍东园西城，点检芳事。\n铃斋吏散，昼馆人稀，几阕管弦清脆。\n人生适意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15092, '玉楼春', '刘子寰', '今来古往吴京道。\n岁岁荣枯原上草。\n行人几度到江滨，不觉身随风树老。\n蒲花易晚芦花早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15093, '沁园春', '刘子寰', '云壑泉泓，小者如杯，大者如罂。\n更石筵平莹，宽容数客，淙流回激，环绕飞觥。\n三涧交流，两崖悬瀑，捣雪飞霜落翠屏。\n经行处，有丹荑碧草，古木苍藤。\n徘徊却倚山楹。\n笑山水娱人若有情。\n见傍回侧转，峰峦叠叠，欲穷还有，岩谷层层。\n仰视云间，茅茨鸡犬，疑是仙家来避秦。\n青林表，望烟霞缥缈，隐隐鸾笙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15094, '贺新郎', '刘子寰', '柱杖凌高绝。\n望千山隐隐，波澜动摇天末。\n下有白云平远壑，涌起潮头喷雪。\n浸绝岛、孤峰出没。\n赤县神州何处是，但风烟、杳杳迷空阔。\n呼不见，古人物。\n碧松枝下青瑶石。\n举头看、长空湛湛，淡琉璃色。\n上界屋辰多官府，夸父忙鞭日月。\n任兔走、乌飞超忽。\n宇宙茫茫如许大，百年间、何用争优劣。\n身世事，一毛发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15095, '满江红', '刘子寰', '云壑飞泉，蒲根下、悬流陆续。\n堪爱处、石池湛湛，一方寒玉。\n暑际直当磐石坐，渴来自引悬瓢掬。\n听泠泠、清响泻琮，胜丝竹。\n寒照胆，消炎燠。\n清彻骨，无尘俗。\n笑幽人忻玩，滞留空谷。\n静坐时看松鼠饮，醉眠不碍山禽浴。\n唤仙人、伴我酌琼瑶，餐秋菊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15096, '霜天晓角', '刘子寰', '横阴漠漠。\n似觉罗衣薄。\n正是海棠时候，纱窗外、东风恶。\n惜春春寂寞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15097, '洞仙歌', '刘子寰', '风餍雨足，也解为花地。\n收拾浮云放新霁。\n爱调亭小翠，点滴猩红，新妆了，妃子朝来睡起。\n遥知春有主，整顿欢娱，兴在新亭锦围底。\n便选歌燕赵，授简邹枚，须记作他日，城山盛事。\n笑东君不用管杨花，任飞去天涯，在东风里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15098, '醉蓬莱', '刘子寰', '正霜浮菊浅，露染枫深，九秋佳景。\n梅报南枝，一点和羹信。\n峻岳生申，太山瞻鲁，瑞启千年运。\n飞帛奎文，仪皇韶祉，明良相庆。\n岁值丰登，道方开泰，塞骑尘收，海鲸波静。\n几斗璇枢，仰三阶平正。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15099, '醉蓬莱', '刘子寰', '正花深绣阁，带拂流酥，暖帘初试。\n窈窕笙歌，拥新鲜珠翠。\n艳菊留金，早梅催粉，趁得瑶池会。\n画馆凝香，仙家正住，芙蓉城里。\n裼寝开祥，玉枝祝寿，列院欢娱，满堂佳瑞。\n福寿双星，现碧霄云际。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15100, '霜天晓角', '刘子寰', '满前儿女。\n今日都欢聚。\n今也阿弥八十，儿也五十五。\n瓷瓯并瓦注。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15101, '沁园春', '刘子寰', '长寿真人，玉佩琼裾，霞衣月裳。\n趁桃迎初度，千年方熟，蒲经端午，三日留春。\n兰杜绥旌，芙蓉搴盖，飞下清源云水乡。\n烟雾，引天机组织，官样文章。\n丁年璧水横翔。\n馀剩馥残膏沾四方。\n仰平生声望，九霄星斗，方来事业，万里风樯。\n经世规模，出尘丰骨，须合盛之白玉堂。\n轩腾去，看雍容槐棘，福艾耆庞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15102, '谒金门', '姚镛', '吟院静。\n迟日自行花影。\n熏透水沈云满鼎。\n晚妆窥露井。\n飞絮游丝无定。\n误了莺莺相等。\n欲唤海棠教睡醒。\n奈何春不肯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15103, '霓裳中序第一', '尹焕', '青颦粲素靥。\n海国仙人偏耐热。\n餐尽香风露屑。\n便万里凌空，肯凭莲叶。\n盈盈步月。\n悄似怜、轻去瑶阙。\n人何在，忆渠痴小，点点爱轻撅。\n愁绝。\n旧游轻别。\n忍重看、锁香金箧。\n凄凉清夜簟席。\n杳杳诗魂，真化风蝶。\n冷香清到骨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15104, '眼儿媚', '尹焕', '垂杨袅袅蘸清漪。\n明绿染春丝。\n市桥系马，旗亭沽酒，无限相思。\n云梳雨洗风前舞，一好百般宜。\n不知为甚，落花时节，都是颦眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15105, '唐多令', '尹焕', '苹末转清商。\n溪声供夕凉。\n缓传杯、催唤红妆。\n慢绾乌云新浴罢，裙拂地、水沈香。\n歌短旧情长。\n重来惊鬓霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15106, '沁园春', '夏元鼎', '大道无名，金丹有验，工夫片时。\n似婴儿娇俊，不离门户，盈盈姹女，缓步深帏。\n二八当年，黄婆匹配，隔碍潜通势似危。\n须臾见，见灵明宝藏，一点星飞。\n其时。\n似执躬圭。\n深保护阴阳造化儿。\n转南辰北斗，回风混合，雷轰雨骤，只许天知。\n梦幻浮生，天长地久，云路著鞭休要迟。\n金不坏，合朋合德，三教同归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15107, '沁园春', '夏元鼎', '太极才分，鸿凿破，云收雾开。\n见曦魂蟾魄，升沈昼夜，光含万象，机应丹台。\n火里栽莲，水中捉月，两个人人暗去来。\n鹊桥畔，任传神送气，巽户轰雷。\n微哉。\n火候休猜。\n无师授徒劳颜闵材。\n问从头下手，收因结果，争魂夺命，何处胚胎。\n小法旁门，幸勤一世，谩道修真不惹埃。\n争如我，水晶宫里，独步琼阶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15108, '沁园春', '夏元鼎', '天下江山，无如甘露，多景楼前。\n有谪仙公子，依山傍水，结茅筑圃，花竹森然。\n四季风光，一生乐事，真个壶中别有天。\n亭台巧，一琴一鹤，泥絮心田。\n不须块坐参禅。\n也不要区区学挂冠。\n但对境无心，山林钟鼎，流行坎止，闹里偷闲。\n向上玄关，南辰北斗，昼夜璇玑炼火还。\n分明见，本来面目，不是游魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15109, '水调歌头', '夏元鼎', '采取铅须密，诚意辨妍媸。\n休教错认，夺来鼎内及其时。\n二物分明真伪，一得还君永得，此事契天机。\n记取元阳动，妙用在虚危。\n法寅申，行子午，总皆非。\n自然时节，梦里也教知。\n不属精津气血，不是肺肝心肾，真土亦非脾。\n言下泄多矣，凡辈奈无知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15110, '水调歌头', '夏元鼎', '要识刀圭诀，一味水银铅。\n驴名马字，九三四八万千般。\n愚底转生分别，划地唤爷作父，荆棘满心田。\n去道日以远，至老昧蹄筌。\n譬如人，归故国，上轻帆。\n顺风得路，夜里也行船。\n岂问经州过县，管取投明须到，舟子自能牵。\n悟道亦如此，半句不相干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15111, '水调歌头', '夏元鼎', '耳目身之宝，固塞勿飞扬。\n存无守有，中间无念以为常。\n把定玄关一窍，视听尽收归里，坎兑互堤防。\n寤寐神依抱，形气两相忘。\n圆陀陀，光烁烁，貌堂堂。\n分明真我，罔象里全彰。\n此即非空非色，自是本来面目，阴鼎炼元阳。\n出世真如佛，馀二莫思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15112, '水调歌头', '夏元鼎', '真一北方气，玄武产先天。\n自然感合，蛇儿却把黑龟缠。\n便是蟾乌遇朔，亲见虎龙吞啖，顷刻过。\n赤黑达表里，炼就水银铅。\n有中无，无中有，两玄玄。\n生身来处，逆顺圣凡分。\n下士闻之大笑，不笑不足为道，难为俗人论。\n士塞命门了，去住管由君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15113, '水调歌头', '夏元鼎', '律应黄锺候，天地尚胚浑。\n腾腾一气，家园平地一枝春。\n下手依时急采，莫放中宫芽溢，害里却生恩。\n火候精勤处，加减武和文。\n定浮沈，明主客，别疏亲。\n真铅留汞，造化合乾坤。\n此是身中灵宝，谁信龙从火出，二八共成斤。\n些子希夷法，只在弄精魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15114, '水调歌头', '夏元鼎', '擒得铅归舍，进火莫教迟。\n抽添沐浴，临炉一意且防危。\n只为婴儿未壮，全藉黄婆养育，丁老共扶持。\n火力频加减，外药亦如之。\n汞生芽，铅作祖，土刀圭。\n火生於木，炎盛汞还飞。\n要得水银真死，须待阴浮阳伏，杂类降灰池。\n用铅终不用，古语岂吾欺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15115, '水调歌头', '夏元鼎', '要蹑天仙步，金丹是法身。\n不知谓气，须还识後自然真。\n大道从花孕子，点出个中阴魄，乌兔合阳魂。\n北斗随罡转，天地正氤氲。\n采依时，炼依法，莫辞勤。\n立跻圣域，从此脱沈沦。\n夜气正当过半，龙虎自然蛰动，势欲撼乾坤。\n片饷工夫耳，庄算八千春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15116, '水调歌头', '夏元鼎', '神气精三药，举世没人知。\n气随精化，镇常神逐气无归。\n心地不明天巧，业识更缠地网，背却上天梯。\n今古多豪杰，生死醉如泥。\n树头珠，潭底日，显金机。\n两般识破，性命更何疑。\n活捉金精入木，炼就当初真一，方表丈夫儿。\n信取玄中趣，端的世间稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15117, '水调歌头', '夏元鼎', '闻道不嫌晚，悟了莫悠悠。\n遇时不炼，今生乌兔恐难留。\n些子乾坤简易，不问在朝居市，达者尽堪修。\n火候无斤两，大药本非遥。\n守旁门，囚冷屋，望升超。\n迷迷相授，生死不相饶。\n未识先天一气，孰辨五行生克，不向眼前求。\n试道工夫易，福薄又难消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15118, '水调歌头', '夏元鼎', '我有一竿竹，偏会取根源。\n从来汲水桔槔，直挈上西天。\n不许常人著手，管定竿头先折，提桶落寒泉。\n拨得机关转，北斗向南看。\n仗回风，乘偃月，勿波澜。\n麻姑此日，西北见张骞。\n选佛妙高峰顶，饮罢醍醐似醉，独坐玩婵娟。\n水湛月明处，太极更无前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15119, '西江月', '夏元鼎', '四十修真学道，金鱼要换金丹。\n龟龄鹤算不知年。\n行满身冲霄汉。\n此事希夷玄奥，功参造化难言。\n眼前有药耀山川。\n好把元阳修炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15120, '西江月', '夏元鼎', '面目本来是道，阴阳造化成丹。\n骑牛寻犊不知原。\n真是三家村汉。\n古圣立言设象，後人得象忘言。\n且如乾画必三川。\n舍此如何烹炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15121, '西江月', '夏元鼎', '太一画前是道，全凭龙虎成丹。\n九还七返保长年。\n好个逍遥闲汉。\n日诣金门玉殿，青衣引赞无言。\n回风混合万神安。\n功向虚无中炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15122, '西江月', '夏元鼎', '举世沈迷大道，傍门小法求丹。\n咽津纳气等成仙。\n真个无知痴汉。\n何异雄鸡抱卵，梦同哑子交言。\n阴阳非类隔天渊。\n总是盲修瞎炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15123, '西江月', '夏元鼎', '不死谷神妙道，杳冥中有还丹。\n坤牛乾马运无边。\n却是修行真汉。\n脱去名缰利锁，金童玉女传言。\n工夫片饷彻玄关。\n水火从教法炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15124, '西江月', '夏元鼎', '大隐居尘奉道，衰颜能返朱丹。\n要须有主种三田。\n方免驱驰淮汉。\n天下江山第一，景胜何言。\n希夷妙处集真仙。\n默默重帘修炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15125, '西江月', '夏元鼎', '万里担簦访道，要知一点灵丹。\n日乌月兔在朝元。\n岂在迢迢云汉。\n罔象求珠易得，离明契后难言。\n五金八石是虚传。\n争似阳修阴炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15126, '西江月', '夏元鼎', '达磨西来说道，十年面壁安丹。\n争知水火不交煎。\n因果谩成罗汉。\n仰箭射空力尽，依然坠地何言。\n虚空拶破强参禅。\n肯把金丹烧炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15127, '西江月', '夏元鼎', '几载鸡窗求道，费他兔楮铅丹。\n经书子史尽蹄筌。\n鹿走徒嗟秦汉。\n百代兴亡瞬息，徒留纸上陈言。\n谁知太始道常存。\n乌兔仙家修炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15128, '西江月', '夏元鼎', '行处青牛引道，飞来鹤顶呈丹。\n谈玄玉局在西川。\n此日方当龙汉。\n千载寂寥吾道，可怜平叔多言。\n画蛇添足悟真篇。\n付与谁人修炼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15129, '水调歌头', '夏元鼎', '三三乾妙画，佑圣诞弥尘。\n北方壬癸，水生於坎产元精。\n一数先天有象，元始化生相应，灵气属阳神。\n寿永齐天地，万物尽回春。\n说龟蛇，名黑杀，蕴深仁。\n阴中阳长，要知害里却生恩。\n此意宜参造化，正是金丹大道，不在咽精津。\n富贵公方逼，肯问出人伦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15130, '水调歌头', '夏元鼎', '人身藏宇宙，乌兔走西东。\n昼舒夜卷，不拘春夏与秋冬。\n存想非心非肾，吐纳非精非气，子午谩行功。\n一点真灵宝，混合自回风。\n感婴儿，交姹女，爱丁公。\n黄婆匹配，一时辰内上仙宫。\n恍惚无中有象，阳火阴符密契，大道属鸿。\n火候能调理，天地与无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15131, '西江月', '夏元鼎', '甘露醴泉天降，琼浆玉液仙方。\n一壶馥郁喷天香。\n麴人间怎酿。\n要使周天火候，不应错认风光。\n浮沈清浊自斟量。\n日醉蓬莱方丈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15132, '西江月', '夏元鼎', '万汇阳春吐秀，争如雀舌含英。\n先天一气社前升。\n啖出峰顶。\n要得丁公煅炼，飞成宝屑窗尘。\n蜜脾神用脱金形。\n送与仙翁体认。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15133, '贺新郎', '夏元鼎', '天上神仙路。\n问谁能、超凡入圣，平虚交付。\n三岛十洲无限景，稳驾鸾舆鹤驭。\n更驯伏、木龙金虎。\n造化小儿真剧戏，炼阳精、要戴乾为父。\n须定力，似愚鲁。\n三旬一遇交乌兔。\n便丹成、天长地久，桑田变否。\n四象五行攒簇处，全藉黄婆真土。\n无私授、人多胡做。\n堪叹红尘声利客，向花朝月夕寻妆妇。\n应不解，乘槎去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15134, '满江红', '夏元鼎', '人世何为，江湖上、渔蓑堪老。\n鸣榔处，汪汪万顷，清波无垢。\n乃一声虚谷应，夷犹短棹关心否。\n向晚来、垂钓傍寒汀，牵星斗。\n砂碛畔，蒹葭茂。\n烟波际，盟鸥友。\n喜清风明月，多情相守。\n紫绶金章朝路险，青蓑箬笠沧溟浩。\n舍浮云、富贵乐天真，酾江酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15135, '满庭芳', '夏元鼎', '久视长生，登仙大道，思量无甚神通。\n正心诚意，儒释道俱同。\n虽是无为清净，依然要、八面玲珑。\n朝朝见，日乌月兔，造化运西东。\n黄婆能匹配，天机玄妙，朔会相逢。\n正三旬一遇，消息无穷。\n不待存心想肾，非关是、打坐谈空。\n君知否，灵明宝藏，收在水晶宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15136, '西河', '王野', '天下事。\n问天怎忍如此。\n陵图谁把献君王，结愁未已。\n少豪气概总成尘，空馀白骨黄苇。\n千古恨，吾老矣。\n东游曾吊淮水。\n绣春台上一回登，一回泪。\n醉归抚剑倚西风，江涛犹壮人意。\n只今袖手野色里。\n望长淮、犹二千里。\n纵有英心谁寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15137, '六州歌头', '王野', '龙蟠虎踞，今古帝王州。\n水如淮，山似洛，凤来游。\n五云浮。\n宇宙无终极，千载恨，六朝事，同一梦休。\n更莫问闲愁。\n风景悠悠。\n得似青溪曲，著我扁舟。\n对残烟衰草，满目是清秋。\n白鹭汀洲。\n夕阳收。\n黄旗紫盖，中兴运，锺王气，护金瓯。\n驻游跸，开行殿，夹朱楼。\n送华。\n万里长江险，集鸿雁，列貔貅。\n扫关河，清海岱，志应酬。\n机会何常，鹤唳风声处，天意人谋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15138, '沁园春', '王野', '月地云阶，碧山丹水，春满北园。\n正慈闱初度，酡颜绿发，黄堂称寿，画戟朱幡。\n戏彩斓斑，安舆游衍，未数当时莱与潘。\n今朝好，把一家和气，散在千门。\n潜藩。\n误玷君恩。\n人尚说、淳熙前状元。\n幸物情如旧，亲年未老，且开玉帐，共祝金樽。\n罗绮飘香，管弦度曲，晚岁欢娱谁与论。\n亭峰宴，似仙家大姥，尽见曾孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15139, '水调歌头', '哀长吉', '紫陌风光好，绣阁绮罗香。\n相将人月圆夜，早庆贺新郎。\n先自少年心意，为惜人娇态，久俟愿成双。\n此夕于飞乐，共学燕归梁。\n索酒子，迎仙客，醉红妆。\n诉衷情处，些儿好语意难忘。\n但愿千秋岁里，结取万年欢会，恩爱应天长。\n行喜长春宅，兰玉满庭芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15140, '齐天乐', '哀长吉', '青鸾海上传芳信。\n蓝田路入仙境。\n万卷书传，六奇计运，冰玉炯然清润。\n帷褰凤锦。\n□镜启鸾台，烟横鸳枕。\n一笑相迎，一双两好恰厮称。\n风流人在仙隐。\n更一县、陶柳春近。\n梦想金桃，宴分玉果，指日送尝汤饼。\n榆接畛。\n管此去亲盟，镇长交聘。\n自古朱陈，一村惟两姓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15141, '朝中措', '哀长吉', '自从佳偶共黄姑。\n几见设门弧。\n方喜阶庭联玉，又闻老蚌生珠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15142, '西江月', '哀长吉', '百和香凝宝络，长生酒满金尊。\n葱葱佳气霭庭萱。\n同把椿龄祝愿。\n玉树已生谢砌，孙枝复长于门。\n伫看百子共千孙。\n此去公侯衮衮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15143, '瑞鹤仙', '哀长吉', '天基佳节後。\n又诗咏嵩生，贤歌天佑。\n千龄运非偶。\n庆一堂风虎，云龙感召，相门华胄。\n盛少屈、一钱太守。\n听吏歌、一迳棠阴，民颂两岐麦秀。\n知否。\n海峰天柱，道骨仙风，总天所授。\n席虚机右。\n金瓯下，署名久。\n伫泥封飞下，沙堤归去，指日家声复旧。\n年年献、金鉴千秋，玉卮万寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15144, '瑞鹤仙', '哀长吉', '小春天未雪。\n见两蕊三花，放梅时节。\n昴宿孕人杰。\n对梅花雪片，平分风月。\n冰清玉洁。\n天赋与、仙风道骨。\n更等闲、来访刘仙，觅取秘传真诀。\n闻说。\n辉联台宿，瑞应文昌，世承阀阅。\n相门事业。\n有祖父、旧风烈。\n管泥封飞下，沙堤归来，光复青毡旧物。\n庆家传、八叶联芳，又添一叶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15145, '沁园春', '黄师参', '谷口高人，偶溯明河，近尺五天。\n见紫霄宫阙，空中突兀，玉皇姬侍，云里蹁跹。\n滴露研朱，披肝作纸，细写灵均孤愤篇。\n排云叫，奈大钧不管，沙界三千。\n语高天上惊传。\n早斥去人间伴谪仙。\n念赤城丹籍，香名空在，蓬莱弱水，欲到无缘。\n还倚枯槎，飘然归去，回首清都若个边。\n家山好，有一湾风月，小小渔船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15146, '祝英台近', '李义山', '夏初临，春正满，花事在红药。\n一阵光风，香雾喷珠箔。\n画堂旧日张家，梦中玉燕，早拂晓、飞来帘幕。\n酒深酌。\n曾记走马长安，功名戏樊郭。\n螺浦如杯，豪气怎生著。\n直须用了圮编，封侯万户，却归共、赤松翁约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15147, '风瀑竹', '牟子才', '阁住杏花雨。\n便新晴、等闲勾引，香车成雾。\n璧月光中箫凤远，袅袅馀音如缕。\n诮一似、群仙府。\n天意乍随人意好，渐星桥、度汉珠还浦。\n又何啻、列千炬。\n晚来乍觉阴盘固。\n笑人间、玉瓶瑶瑟，锦茵雕俎。\n无限升平宣政曲，回首中原何处。\n慨鸣镝、已无宫武。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15148, '水调歌头', '戴翼', '嵩岳周王佐，昴宿汉宗臣。\n从来间世英杰，出则致升平。\n况我皇华直指，元是福星出现，来此活生灵。\n五百岁初度，十一郡欢忻。\n挽西江，苏涸辙，洗尘埃。\n笑谈顷刻间宜，宇宙变为春。\n泽满赣川无限，福与崆峒齐耸，颂咏几多人。\n潋滟一卮寿，愿早秉洪钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15149, '水调歌头', '戴翼', '渤海卖刀剑，河汉洗戎兵。\n千金六月一雨，万陇稼云横。\n时节可人如许，天意开祥有在，申月岳生申。\n五百岁初度，千万户欢声。\n栋梁材，霖雨手，庙堂身。\n日边褒玺已到，岂久试鱼城。\n快上承明步武，展尽玉堂事业，再使旧毡青。\n公寿更天远，鼻祖等长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15150, '水调歌头', '徐经孙', '客问矩山老，何事得优游。\n追数平生出处，为客赋歌头。\n三十五时侥幸，四十三年仕宦，七十□归休。\n顶踵皆君赐，天地德难酬。\n书数册，棋两局，酒三瓯。\n此是日中受用，谁劣又谁优。\n寒则拥炉曝背，暖则寻花问柳，乘兴狎沙鸥。\n知足又知止，客亦许之不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15151, '百字令・念奴娇', '徐经孙', '八旬加二，荷君天垂，扶持老拙。\n目送新来檐外燕，手拣好花轻折。\n比似去年，十分强健，日看朱诗说。\n篇三百五，岁前尽有披阅。\n天教两子供官，一男留养，左右相娱悦。\n五见孙枝三弄授，童冠参差袍笏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15152, '哨遍', '徐经孙', '江山风月，耳目声色。\n取之无禁，用之不竭。\n造物之无尽藏，月白风清，有客有酒。\n踞虎登龙，放舟中流。\n听其所止而休焉。\n归去来兮，昨非今是。\n旧菊都荒，新松老矣。\n吾年今已如此。\n归去来兮，忘我忘世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15153, '乳燕飞・贺新郎', '徐经孙', '一雨炎□洗。\n似天知、溪山佳处，玳筵珠履。\n六十年前今朝庆，门左桑弧蓬矢。\n也似恁、郁葱佳气。\n绿鬓童颜春未老，问寿星、模样君真是。\n新甲子，从头起。\n应门有子能承志。\n总人间、皱眉底事，不关君耳。\n看不日孙枝毓秀，衮衮教人满意。\n更又报、门阑多喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15154, '鹧鸪天', '徐经孙', '安分随缘事事宜。\n平生快活过年时。\n长歌赤壁动坡赋，又咏归来元亮词。\n开八帙，望期颐。\n人生如此古犹稀。\n香飘金粟如来供，岁岁今朝荐酒卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15155, '八声甘州', '冯去非', '买扁舟、载月过长桥，回首梦耶非。\n问往日三高，清风万古，继者伊谁。\n惟有茶烟轻扬，零露湿莼丝。\n西子知何处，鸿怨蛩悲。\n遥想家山好在，正倚天青壁，石瘦云肥。\n甚抛奇秀，猿鹤互猜疑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15156, '点绛唇', '冯去非', '秋满孤篷，翠蒲红蓼留人住。\n一帘香缕。\n边影惊鸿度。\n小据胡床，旧事新情绪。\n凭谁诉。\n蜡灯犀尘。\n拟共西风语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15157, '喜迁莺', '冯去非', '凉生遥渚。\n正绿芰擎霜，黄花招雨。\n雁外渔村，蛩边蟹舍，绛叶满秋来路。\n世事不离双鬓，远梦偏欺孤旅。\n送望眼，但凭舷微笑，书空无语。\n慵觑。\n清镜里，十载征尘，长把朱颜污。\n借箸青油，挥毫紫塞，旧事不堪重举。\n间阔故山猿鹤，冷落同盟鸥鹭。\n倦游也，便樯云柁月，浩歌归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15158, '酹江月・念奴娇', '熊大经', '人生八十，自儿时祝愿，这般年数。\n滴露研朱轻点笔，个个眉心丹字。\n萱草丛边，梅花香里，真有人如此。\n红颜青鬓，儿时依旧相似。\n堪笑生子愚痴，投身枳棘，欲了官中事。\n万叠关山遥望眼，遐瞬白云飞处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15159, '喜迁莺', '张□□', '英声初发。\n记舍选齐驱，祖鞭先著。\n风月平分，尊谈旧，各已苍颜白发。\n屈指待拚一醉，祝生申嵩岳。\n怎知道，为清湘□润，暂移贤杰。\n休说。\n予心渴，里巷争先，拟持杯阶闼。\n毕竟人间，赏心乐事，种种尽归缘法。\n拈取瑞香一瓣，向湘山名刹。\n无量寿，和一身见在，两尊菩萨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15160, '失调名', '赵某', '□□□□皆乃，□□流垂□，断崖依旧横碧。\n□□独有千古文章，铿炳耀，不与名□。\n□□□□□□，□□□□，□尽□□远□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15161, '壶中天・念奴娇', '翁定', '昔时彭祖，闻道有、八百穹崇遐寿。\n屈指我公今几许，历岁才方七九。\n七百修龄，更三十七，犹是公之有。\n此逢诞节，盍须来献尊酒。\n好是子舍孙枝，居官领荐，迭复青毡旧。\n陶令解龟何太早，去作幔亭仙友。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15162, '菩萨蛮', '留元崇', '江头日落孤帆起。\n归心拍拍东流水。\n山远不知名。\n为谁迢递青。\n危桥来处路。\n尚带潇湘雨。\n楚尾与吴头。\n一生离别愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15163, '酹江月・念奴娇', '沈刚孙', '我来访古。\n把尘襟、都付一声鸣橹。\n笑把瑶觞波浩荡，却忆长鲸吞吐。\n坐挹高风，骨清毛冷，不作嚣尘语。\n客星何在，谩留遗像江渚。\n试问泽畔羊裘，当时何事，笑禹宫武。\n金印貂禅谁不爱，只为汉颜巢许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15164, '念奴娇', '王澜', '凭高远望，见家乡、只在白云深处。\n镇日思归归未得，孤负殷勤杜宇。\n故国伤心，新亭泪眼，更洒潇潇雨。\n长江万里，难将此恨流去。\n遥想江口依然，鸟啼花谢，今日谁为主。\n燕子归来，雕梁何处，底事呢喃语。\n最苦金沙，十万户尽，作血流漂杵。\n横空剑气，要当一洗残虏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15165, '满江红', '吴潜', '红玉阶前，问何事、翩然引去。\n湖海上、一汀鸥鹭，半帆烟雨。\n报国无门空自怨，济时有策从谁吐。\n过垂虹亭下系扁舟，鲈堪煮。\n拚一醉，留君住。\n歌一曲，送君路。\n遍江南江北，欲归何处。\n世事悠悠浑未了，年光冉冉今如许。\n试举头、一笑问青天，天无语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15166, '满江红', '吴潜', '露驿星程，又还控、西风征辔。\n原自有、孔璋书檄，元龙豪气。\n蜀道尚惊鼙鼓後，神州正在干戈里。\n佐元戎，一柱稳擎天，襄之水。\n功名事，山林计。\n人易老，时难值。\n看新丝一发，甚吾衰矣。\n转首从游十五载，关心契阔三千里。\n便秋空、边雁落江南，书来未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15167, '满江红', '吴潜', '十二年前，曾上到、绣春台顶。\n双脚健、不烦筇杖，透岩穿岭。\n老去渐消狂气习，重来依旧佳风景。\n想牧之、千载尚神游，空山冷。\n山之下，江流水。\n江之外，淮山暝。\n望中原何处，虎狼犹梗。\n句蠡规模非浅近，石苻事业真俄顷。\n问古今、宇宙竟如何，无人省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15168, '满江红', '吴潜', '万里西风，吹我上、滕王高阁。\n正槛外、楚山云涨，楚江涛作。\n何处征帆木末去，有时野鸟沙边落。\n近帘钩、暮雨掩空来，今犹昨。\n秋渐紧，添离索。\n天正远，伤飘泊。\n叹十年心事，休休莫莫。\n岁月无多人易老，乾坤虽大愁难著。\n向黄昏、断送客魂消，城头角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15169, '满江红', '吴潜', '柳带榆钱，又还过、清明寒食。\n天一笑、满园罗绮，满城箫笛。\n花树得晴红欲染，远山过雨青如滴。\n问江南、池馆有谁来，江南客。\n乌衣巷，今犹昔。\n乌衣事，今难觅。\n但年年燕子，晚烟斜日。\n抖擞一春尘土债，悲凉万古英雄迹。\n且芳尊、随分趁芳时，休虚掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15170, '满江红', '吴潜', '拟卜三椽，问何处、水回山曲。\n朝暮景、清风当户，白云藏屋。\n更得四时瓶贮酒，未输一品腰围玉。\n待千章、手种未成阴，周遮绿。\n且休，陶令菊。\n也休羡，子猷竹。\n算百年一梦，谁荣谁辱。\n唤客烹茶闲话了，呼童取枕佳眠足。\n但晨香、一炷愿天公，时丰熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15171, '满江红', '吴潜', '岳后湘灵，曾孕个、擎天人物。\n临古岘、纶巾羽扇，笑驱胡羯。\n护塞十年高叔子，出师一表侪诸葛。\n有孤忠、分付与佳儿，真衣钵。\n刘家骥，驰空阔。\n薛家凤，飞横绝。\n比君家兄弟，可能豪杰。\n草木声名如电扫，毡裘心胆闻风折。\n待安排、江汉一篇诗，归来说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15172, '满江红', '吴潜', '细阅浮生，为甚底、区区碌碌。\n算只是、信缘随分，早寻归宿。\n造物小儿簸弄，翻云覆雨难擐触。\n谩一堆、岁月鬓边来，跳丸速。\n田二顷，非无粟。\n官四品，非无禄。\n更不知足後，待何时足。\n恰好园池原自有，近来新创三椽屋。\n且饥时、吃饭困时眠，平为福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15173, '满江红', '吴潜', '举世悠悠，何妨任、流行坎止。\n算是处、鲜鱼羹饭，吃来都美。\n暇日扁舟清上，倦时一枕薰风里。\n试回头、堆案省文书，徒劳尔。\n南浦路，东溪水。\n离索恨，飘零意。\n况星星鬓影，近来如此。\n万事尽由天倒断，三才自有人撑抵。\n但多吟、康节醉中诗，频相寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15174, '满江红', '吴潜', '岁岁登高，算难得、今年美景。\n尽敛却、雨霾风障，雾沈云暝。\n远岫四呈青欲滴，长空一抹明於镜。\n更天教、老子放眉头，边烽静。\n数本菊，香能劲。\n数朵桂，香尤胜。\n向尊前一笑，几多清兴。\n安得便如彭泽去，不妨且作山翁酩。\n尽古今、成败共兴亡，都休省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15175, '满江红', '吴潜', '日薄寒空，正泽国、一汀霜叶。\n过万里、西风塞雁，数声哀咽。\n耿耿有怀天可讯，悠悠此恨谁能说。\n倚阑干、老泪落关山，平芜隔。\n提短剑，腰长铗。\n昔壮志，今华发。\n有江湖征棹，水云深阔。\n要斩鼯埋九地，可怜乌兔驰双辙。\n羡渠侬、健笔扫磨崖，文章别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15176, '满江红', '吴潜', '乍雨还晴，正轻暖轻寒帘幕。\n时怅望、故人烟水，鹭翻鸥落。\n老去可堪离恨结，新来转觉吟情薄。\n况等闲、客里送年华，成挥霍。\n天一顾，西南角。\n人万里，风埃阔。\n笑长卿归蜀，锦衣徒著。\n不是等闲螳臂怒，也休刚道鸡声恶。\n但千年、往事误平凉，今番莫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15177, '满江红', '吴潜', '痴霭顽阴，风扫尽、安排今夕。\n便放出、一轮金镜，皎然虚碧。\n照彻肺肝明似水，是中空洞无他物。\n倚亭皋、搔首问天公，天应识。\n人共景，都非昔。\n君共我，俱成客。\n且相逢一笑，笙歌箫笛。\n老去可怜杯酒减，醉来谩把阑干拍。\n便明朝、烟水挂征帆，还相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15178, '满江红', '吴潜', '客子愁来，闲信马、到涵空阁。\n谁为我、敛云收雾，青天为幕。\n八万顷湖如镜静，波神护断东南角。\n望孤帆、杳杳度微茫，山邀却。\n三塞外，纷狐貉。\n三径里，悲猿鹤。\n笑鸱夷老子，占他头著。\n正使百年能几许，看来万事难描摸。\n问吴王、池馆复何如，霜枫落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15179, '满江红', '吴潜', '试马东风，且来问、南枝消息。\n正小墅、几株斜倚，数花轻拆。\n自有山中幽态度，谁知世上真颜色。\n叹君家、五岭我双溪，俱成客。\n长塞管，孤城笛。\n天未晓，人犹寂。\n有几多心事，露清月白。\n好把寒英都放了，莫教春讯能占得。\n问竹篱、茅舍景如何，惟渠识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15180, '满江红', '吴潜', '借问如何，春能好、客怀偏恶。\n消遣底、闲言闲语，近都慵作。\n岁月从今休点检，江湖自古多流落。\n倚危亭、目断野云边，孤舟泊。\n人事改，人情薄。\n退後步，争先著。\n且开尊洗盏，为君斟酌。\n拂拭凤凰池上景，凄凉猿鹤山中约。\n更东阳、憔悴到腰围，浑如削。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15181, '哨遍', '吴潜', '在晋永和，癸丑暮春，初作兰亭会。\n集众贤，临峻岭崇山，有茂林修竹流水。\n畅幽情，纵无管弦丝竹，一觞一咏佳天气。\n於宇宙之中，游心骋目，此娱信可乐只。\n念人生相与放形骸。\n或一室晤言襟抱开。\n静躁虽殊，当其可欣，不知老至。\n然倦复何之。\n情随事改悲相系。\n俯仰间遗迹，往往俱成陈矣。\n况约境变迁，终期於尽，修龄短景都能几。\n谩古换今移，时消物化，痛哉莫大生死。\n每临文吊往一兴嗟。\n亦自悼不能喻於怀。\n算彭殇、妄虚均尔。\n今之视昔如契，後视今犹昔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15182, '水调歌头', '吴潜', '铁瓮古形势，相对立金焦。\n长江万里东注，晓吹卷惊涛。\n天际孤云来去，水际孤帆上下，天共水相邀。\n远岫忽明晦，好景画难描。\n混隋陈，分宋魏，战孙曹。\n回头千载陈迹，痴绝倚亭皋。\n惟有汀边鸥鹭，不管人间兴废，一抹度青霄。\n安得身飞去，举手谢尘嚣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15183, '水调歌头', '吴潜', '皎月亦长有，今夜独娟娟。\n浮云万里收尽，人在水晶奁。\n矫首银河澄澈，搔首金风浩荡，毛发亦冷然。\n宇宙能空阔，磨蚁正回旋。\n倩渔翁，撑舴艋，柳阴边。\n垂纶下饵，须臾钓得两三鲜。\n唤客烹鱼酾酒，伴我高吟长啸，烂醉即佳眠。\n何用骖鸾去，已是地行仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15184, '水调歌头', '吴潜', '宛水才停棹，一舸又澄江。\n岩花篱蕊开遍，时节正重阳。\n唤起沙汀渔父，揽取一天秋色，无处不潇湘。\n有酒时鲸吸，醉里是吾乡。\n济时心，忧国志，问穹苍。\n是非得失，成败何用苦论量。\n年事飞乌奔兔，世事崩崖惊浪，此别意茫茫。\n但愿身强健，努力报君王。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15185, '水调歌头', '吴潜', '才惜季方去，又更别元方。\n惊心天上双凤，接翅下高冈。\n万里瞿塘烟浪，一片昭亭云月，渺渺正相望。\n夜雨连风壑，此意独凄凉。\n杜鹃声，犹不住，搅离肠。\n黄鸡白酒，吾意归兴动江乡。\n人事纷纷难料，世事悠悠难说，何处问穹苍。\n肯落儿曹泪，一笑付沧浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15186, '水调歌头', '吴潜', '勋业竟何许，日日倚危楼。\n天风吹动襟袖，身世一轻鸥。\n山际云收云合，沙际舟来舟去，野意已先秋。\n很石痴顽甚，不省古今愁。\n郗兵强，韩舰整，说徐州。\n但怜吾衰久矣，此事恐悠悠。\n欲破诸公磊块，且倩一杯浇酹，休要问更筹。\n星斗阑干角，手摘莫惊不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15187, '沁园春', '吴潜', '第一江山，无边境界，压四百州。\n正天低云冻，山寒木落，萧条楚塞，寂寞吴舟。\n白鸟孤飞，暮鸦群注，烟霭微茫锁戌楼。\n凭阑久。\n问匈奴未灭，底事菟裘。\n回头。\n祖敬何刘。\n曾解把功名谈笑收。\n算当时多少，英雄气概，到今惟有，废垅荒丘。\n梦里光阴，眼前风景，一片今愁共古愁。\n人间事，尽悠悠且且，莫莫休休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15188, '沁园春', '吴潜', '落雁横空，乱鸦投树，孤村暮烟。\n有渔翁拖网，牧儿戴笠，行从水畔，唱过山前。\n云阁还垂，雨低欲堕，何处行人唤渡船。\n萧萧处，更柴门草店，竹外松边。\n凄然。\n倚马停鞭。\n叹客袂征衫岁月迁。\n既不缘富贵，功名系绊，非因妻子，田宅萦牵。\n只有寸心，难忘斯世，磊块轮知者天。\n愁无奈，且三杯浊酒，一枕酣眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15189, '贺新郎', '吴潜', '说著成凄楚。\n正尘飞、岷峨滟，兔嗥孤舞。\n颇牧禁中留不住，弹压征西幕府。\n便一舸、月汀烟渚。\n四塞三关天样险，问何人、自辟鼯路。\n成败事，几今古。\n荼シ芍药春将暮。\n最无情、飘零柳絮，搅人离绪。\n屈指秋风吹雁信，应忆西湖夜雨。\n谩岁月、消磨如许。\n上下四方男子志，肯临歧、昵昵儿曹语。\n呼大白，为君举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15190, '贺新郎', '吴潜', '扑尽征衫气。\n小夷犹、尊杖履，踏开花事。\n邂逅山翁行乐处，何似乌衣旧里。\n叹芳草、舞台歌地。\n百岁光阴如梦断，算古今、兴废都如此。\n何用洒，儿曹泪。\n江南自有渔樵队。\n想家山、猿愁鹤怨，问人归未。\n寄语寒梅休放尽，留取三花两蕊。\n待老子、领些春意。\n皎皎风流心自许，尽何妨、瘦影横斜水。\n烦翠羽，伴醒醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15191, '贺新郎', '吴潜', '可意人如玉。\n小帘栊、轻匀淡泞，道家装束。\n长恨春归无寻处，全在波明黛绿。\n看冶叶、倡条浑俗。\n比似江梅清有韵，更临风、对月斜依竹。\n看不足，咏不足。\n曲屏半掩青山簇。\n正轻寒、夜来花睡，半残烛。\n缥缈九霞光里梦，香在衣裳剩馥。\n又只恐、铜壶声促。\n试问送人归去後，对一奁、花影垂金粟。\n肠易断，倩谁续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15192, '贺新郎', '吴潜', '又是春残去。\n倚东风、寒云淡日，堕红飘絮。\n燕社鸿秋人不问，尽管吴笙越鼓。\n但短发、星星无数。\n万事惟有彭泽醉，也何妨、袖卷长沙舞。\n身与世，只如许。\n阑干拍手闲情绪。\n便明朝、苍鸥白鹭，北山南浦。\n笑指午桥桥畔路，帘幕深深院宇。\n尚趁得、柳烟花雾。\n我亦故山猿鹤怨，问何时、归棹双溪渚。\n歌一曲，恨千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15193, '贺新郎', '吴潜', '烟树瓜洲岸。\n望旌旗、猎猎摇空，故人天远。\n不似沙鸥飞得渡，直到雕鞍侧畔。\n但徙倚、危阑目断。\n自古锺情须我辈，况人间、万事思量遍。\n涛似雪，风如箭。\n扬州十里朱帘卷。\n想桃根桃叶，依稀旧家庭院。\n谁把青红吹到眼，知有醉翁局段。\n便回首、舟移帆转。\n渺渺江波愁未了，正淮山、日暮云撩乱。\n阁酒盏，倚歌扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15194, '贺新郎', '吴潜', '笑口开能几。\n把年年、芳情冶思，总抛闲里。\n桃杏枝头春才半，寒食清明又是。\n但岁月、飙飞川逝。\n回首秦楼双燕语，到如今、目断斜阳外。\n将往事，试重记。\n香罗尚有相思泪。\n算人生、新愁易积，旧欢难继。\n水上流红无觅处，还隔关山万里。\n但赢得、新来憔悴。\n昨夜东风颠狂後，想馀芳、尽是飘零底。\n词写就，倩谁寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15195, '满庭芳', '吴潜', '漠漠春阴，疏疏春雨，鹁鸠唤起春眠。\n小园人静，独自倚秋千。\n又见飘红堕雪，芳径里、都是花钿。\n年年事，闲愁闲闷，挂在绿杨边。\n寻思，都遍了，功名竹帛，富贵貂蝉。\n但身为利锁，心被名牵。\n争似依山傍水，数椽外、二顷良田。\n无萦绊，炊粳酿秫，长是好花天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15196, '满庭芳', '吴潜', '春水溶溶，春山漠漠，淡烟浅罩轻笼。\n危楼阑槛，掠面小东风。\n又是飞花落絮，芳草暗、万绿成丛。\n闲徙倚，百年人事，都在画船中。\n故园，无恙否，一溪翠竹，两径苍松。\n更有鱼堪钓，有秫堪舂。\n底事尘驱物役，空回首、社燕秋鸿。\n功名已，萧骚短鬓，分付与青铜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15197, '酹江月・念奴娇', '吴潜', '红尘飞骑，报元戎小队，踏青南陌。\n雪浪堆边呼小渡，吴楚半江分坼。\n岁月惊心，风埃迷目，相对头俱白。\n杨花撩乱，可怜如此春色。\n谁道燕燕莺莺，多情犹自，认得年时客。\n重唱江南肠断句，为我满倾云液。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15198, '酹江月・念奴娇', '吴潜', '晓来窗外，正南枝初放，两花三蕊。\n千古春风头上立，羞退桃繁李。\n姑射神游，寿阳妆褪，色界尘都洗。\n竹扉松户，平生所寄聊耳。\n堪笑强说和羹，此君心事，指高山流水。\n陇驿凄凉，却怕被、哀角城头吹起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15199, '酹江月・念奴娇', '吴潜', '半空楼阁，把江山图画，一时收拾。\n白鸟孤飞飞尽处，最好暮天秋碧。\n万里西风，百年人事，谩倚阑干拍。\n凝眸何许，扬州烟树历历。\n应念老子年来，浮名浮利，已作虚空掷。\n三径才寻归活计，又是飘零为客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15200, '八声甘州', '吴潜', '任渠侬、造物自儿嬉。\n安能止吾归。\n有秋来竹径，春时花坞，夏里荷漪。\n何事东涂西抹，空遣鬓毛稀。\n矫首看鸿鹄，远举高飞。\n点检人间今古，问谁为赢局，底是输棋。\n谩区区成败，蚁阵与蜗围。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15201, '八声甘州', '吴潜', '记高冈、两凤揽朝晖，翩翻万里来。\n向槐厅深处，松厅紧里，却立徘徊。\n一舸风帆烟浪，拟竖锦江桅。\n聊为玄晖老，共拂尘埃。\n我亦归来岩壑，正不妨散诞，笑口频开。\n算人间成败，何用苦惊猜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15202, '二郎神', '吴潜', '小楼向晚，正柳锁、一城烟雨。\n记十里吴山，绣帘朱户，曾学宫词内舞。\n浪逐东风无人管，但脉脉、岁移年度。\n嗟往事未尘，新愁还织，怎堪重诉。\n凝伫。\n问春何事，飞红飘絮。\n纵杜曲秦川，旧家都在，谁寄音书说与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15203, '解连环', '吴潜', '彩桡芳苑。\n嗟东风梦断，燕残莺懒。\n谩记得、标格精神，正云涨暮天，雨荒闲馆。\n嫩绿殷红，但回首、一川波暖。\n想娇情慧态，倚褪淡妆，画楼帘卷。\n吴歌数声冉冉。\n料移商变羽，人共天远。\n须信道、飞絮游丝，尽春去春来，景色偷换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15204, '汉宫春', '吴潜', '楼观齐雪，正霜明天净，一雁高飞。\n江南倦客徙倚，目断双溪。\n凭阑自语，算从来、总是儿痴。\n青镜里，数丝点鬓，问渠何事忘归。\n幸有三椽茅屋，更小园随分，秋实春菲。\n几多清风皎月，美景良时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15205, '祝英台近', '吴潜', '碧云开，红日丽，宫柳碎繁影。\n犹记朝回，马兀梦频醒。\n天教一舸江湖，数椽涧壑，渐摆脱、世间尘境。\n已深省。\n添买竹坞千畦，荷漪两三顷。\n鹤引禽伸，日月峤壶永。\n不须瓮里思量，隙中驰骛，也莫管、玉关风景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15206, '祝英台近', '吴潜', '雾霏霏，云漠漠，新绿涨幽浦。\n梦里家山，春透一犁雨。\n伤心塞雁回来，问人归未，怎知道、蜗名留住。\n镜中觑。\n近年短发难簪，丝丝不禁数。\n蕙帐尘侵，凄切共谁语。\n被他轻暖轻寒，将人憔悴，正闷里、梅花残去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15207, '祝英台近', '吴潜', '旋安排，新捻合，莺谷共烟浦。\n好处偏悭，一向风和雨。\n今朝捱得晴明，拖条藜杖，一齐把、春光黏住。\n且闲觑。\n水边行过幽亭，修竹净堪数。\n百舌楼罗，渐次般言语。\n从今排日追游，留连光景，但管取、笼灯归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15208, '摸鱼儿', '吴潜', '满园林、瘦红肥绿，休休春事无几。\n杜鹃唤起三更梦，窗外露澄风细。\n浑不寐。\n但目看、一帘夜月移花未。\n推衾自起。\n念岁月如流，容颜不驻，镜里留无计。\n人间事。\n休说贱贫富贵。\n天公长把人戏。\n萧裴曹郭今何在，空有旧闻千纸。\n君谩试。\n数青史荣名，到底三无二。\n浮生似寄。\n争似得江湖，烟蓑雨笠，不被蜗蝇系。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15209, '喜迁莺', '吴潜', '良辰佳节。\n问底事，十番九番为客。\n景物春妍，莺花日闹，自是情怀今别。\n只有思归魂梦，却怕杜鹃啼歇。\n消凝处，正丝杨冉冉，寸肠千折。\n谩说。\n临曲水，修竹茂林，人境成双绝。\n俯仰俱陈，彭殇等幻，何许世殊时隔。\n倚楼碧云日暮，漠漠远山千叠，沈醉好，又城头画角，一声声咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15210, '千秋岁', '吴潜', '水晶宫里。\n有客闲游戏。\n溪漾绿，山横翠。\n柳纾阴不断，荷递香能细。\n撑小艇，受风多处披襟睡。\n回首看朝市。\n名利人方醉。\n蜗角上，争荣悴。\n大都由命分，枉了劳心计。\n归去也，白云一片愁空外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15211, '声声慢', '吴潜', '挨晴拶暖，载酒呼朋，夷犹东圃西园。\n绿萼枝头，两三初破轻寒。\n平生自甘寂寞，占冷妆、不为人妍。\n林逋去，问疏影香暗，谁赋其间。\n空想故山奇事，正烟横岭曲，月浸溪湾。\n杏错桃讹，那时青子都圆。\n惟饶梦窗知处，对翠禽、依约神仙。\n休引角，怕征人、泪落塞边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15212, '青玉案', '吴潜', '黄昏先自无情绪。\n更几阵、风和雨。\n闲把楼头更点数。\n挑残灯烬，装成香缕。\n此际凭谁诉。\n新词旧曲歌还住。\n欲说相思渺无处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15213, '青玉案', '吴潜', '人生南北如歧路。\n惆怅方回断肠句。\n四野碧云秋日暮。\n苇汀芦岸，落霞残照，时有鸥来去。\n一杯渺渺怀今古。\n万事悠悠付寒暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15214, '江城子', '吴潜', '家园十亩屋头边。\n正春妍。\n酿花天。\n杨柳多情，拂拂带轻烟。\n别馆闲亭随分有，时策杖，小盘旋。\n采山钓水美而鲜。\n饮中仙。\n醉中禅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15215, '鹧鸪天', '吴潜', '去日春山淡翠眉。\n到家恰好整寒衣。\n人归玉垒天应惜，舟过松江月半垂。\n千万绪，两三卮。\n送君不忍与君违。\n书来频寄西边讯，是我江南愁断时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15216, '南柯子・南歌子', '吴潜', '池水凝新碧，阑花驻老红。\n有人独立画桥东。\n手把一枝杨柳、系春风。\n鹊绊游丝坠，蜂拈落蕊空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15217, '踏莎行', '吴潜', '红药将残，绿荷初展。\n森森竹里闲庭院。\n一炉香烬一瓯茶，隔墙听得黄鹂啭。\n陌上春归，水边人远。\n尽将前事思量遍。\n流光冉冉为谁忙，小桥伫立斜阳晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15218, '糖多令・唐多令', '吴潜', '白鹭立孤汀。\n行人长短亭。\n正垂杨、芳草青青。\n岁月尽抛尘土里，又隔日、是清明。\n日暮碧云生。\n魂伤老泪横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15219, '谒金门', '吴潜', '溪边屋。\n不浅不深团簇。\n野树平芜秋满目。\n有人闲意足。\n旋唤一尊。\n菱芡煮来新熟。\n归去来辞歌数曲。\n醉时无检束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15220, '谒金门', '吴潜', '东风恶。\n一片梅花吹落。\n独上小楼闲索。\n云垂天四角。\n春自於人如昨。\n人自於春难托。\n惆怅光阴虚过却。\n情怀无处著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15221, '谒金门', '吴潜', '庭垂箔。\n数点杨花飞落。\n倚遍阑干人寂寞。\n闲铺棋一角。\n客里春寒偏觉。\n睡起春衫偏薄。\n想得故山猿共鹤。\n笑人身计错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15222, '鹊桥仙', '吴潜', '扁舟昨泊，危亭孤啸，目断闲云千里。\n前山急雨过溪来，尽洗却、人间暑气。\n暮鸦木末，落凫天际，都是一团秋意。\n痴儿呆女贺新凉，也不道、西风又起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15223, '更漏子', '吴潜', '柳初眠，花正好。\n又被雨催风恼。\n红满地，绿垂堤。\n杜鹃和恨啼。\n对残春，消永昼。\n乍暖乍寒时候。\n人独自，倚危楼。\n夕阳多少愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15224, '海棠春', '吴潜', '天涯芳草迷征路。\n还又是、匆匆春去。\n乌兔里光阴，莺燕边情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15225, '卜算子', '吴潜', '春事到西湖，处处梅花笑。\n抖擞长安车马尘，眼底青山好。\n身世两悠悠，岁月间中老。\n极目烟波万顷愁，此意谁知道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15226, '卜算子', '吴潜', '苕水能清，更有人如水。\n秋水横边簇远山，相对盈盈里。\n溪上有鸳鸯，艇子频惊起。\n何似收归碧玉池，长在阑干底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15227, '忆秦娥', '吴潜', '娇滴滴。\n婵娟影里赠横笛。\n曾横笛。\n一声肠断，一番愁织。\n隔墙频听无消息。\n龙吟海底难重觅。\n难重觅。\n梅花残了，杏花消得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15228, '长相思', '吴潜', '要相逢。\n恰相逢。\n画舫朱帘脉脉中。\n霎时烟霭重。\n怨东风。\n笑东风。\n落花飞絮两无踪。\n分付与眉峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15229, '长相思', '吴潜', '燕高飞。\n燕低飞。\n正是黄梅青杏时。\n榴花开数枝。\n梦归期。\n数归期。\n想见画楼天四垂。\n有人攒黛眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15230, '长相思', '吴潜', '上帘钩。\n下帘钩。\n夜半天街灯火收。\n有人曾倚楼。\n思悠悠。\n恨悠悠。\n只有西湖明月秋。\n知人如许悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15231, '柳梢青', '吴潜', '衬步花茵，穿帘柳絮，堆地榆钱。\n乍暖仍寒，欲晴还雨，春事都圆。\n午窗睡起厌厌。\n屋角外、初啼杜鹃。\n百种凄凉，几般烦恼，没个人怜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15232, '柳梢青', '吴潜', '断续残红，翩飞去鸟，别岸孤村。\n傍水楼台，满城钟鼓，又是黄昏。\n悠悠岁月如奔。\n正目断、边尘塞云。\n两鬓秋风，百年人事，无限消魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15233, '阮郎归', '吴潜', '软风轻霭弄晴晖。\n鹁鸠相应啼。\n画堂人静画帘垂。\n阑干独倚时。\n闲拾句，困寻棋。\n沈吟心是非。\n荼シ开遍柳花飞。\n惜春春不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15234, '诉衷情', '吴潜', '几回相见见还休。\n说著泪双流。\n又听画角呜咽，都和作、一团愁。\n云似絮，月如钩。\n忆凭楼。\n蕙兰情性，梅竹精神，长在心头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15235, '霜天晓角', '吴潜', '云收雾辟。\n万里天空碧。\n舟过蛾眉亭下，景似旧、人非昔。\n年事如梭掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15236, '点绛唇', '吴潜', '禁鼓三敲，参旗初挂阑干角。\n浅屏疏箔。\n夜气侵已薄。\n乃吴歌，艇子当溪泊。\n休休莫。\n五湖烟浪，不是鸱夷错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15237, '蝶恋花', '吴潜', '野树梅花香似扑。\n小径穿幽，乐意天然足。\n回首人间名利局。\n大都一觉黄粱熟。\n别墅谁家屏簇簇。\n绮户疏窗，尚有藏春屋。\n镜断钗分何处续。\n伤心芳草庭前绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15238, '蝶恋花', '吴潜', '客枕梦回闻二鼓。\n冷落青灯，点滴空阶雨。\n一寸愁肠千万缕。\n更听切切寒蛩语。\n世事翻来还复去。\n造物儿戏，自古无凭据。\n利锁名缰空自苦。\n星星鬓影今如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15239, '天仙子', '吴潜', '百舌搬春春已透。\n长驿短亭芳草昼。\n家山肠断欲归人，风宿留。\n船津候。\n一夜朱颜烦恼瘦。\n不用寻思闲宇宙。\n倦鸟入林云返岫。\n小园自有四时花，铺锦绣。\n锺醇酎。\n尽胜累累悬印绶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15240, '如梦令', '吴潜', '插遍门前杨柳。\n又是清明时候。\n岁月不饶人，鬓影星星知否。\n知否。\n知否。\n且尽一杯春酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15241, '如梦令', '吴潜', '昨日春衫初试。\n今日春寒犹。\n待得晚风收，独上危楼闲倚。\n闲倚。\n闲倚。\n目断半空烟水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15242, '如梦令', '吴潜', '江上绿杨芳草。\n想见故园春好。\n一树海棠花，昨夜梦魂飞绕。\n惊晓。\n惊晓。\n窗外一声啼鸟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15243, '如梦令', '吴潜', '楼外残阳将暮。\n江上孤帆何处。\n搔首立东风，又是少年情绪。\n凝伫。\n凝伫。\n一抹淡烟轻雾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15244, '如梦令', '吴潜', '枝上蝶纷蜂闹。\n几树杏花残了。\n幽鸟亦多情，片片闲归芳草。\n休扫。\n休扫。\n管甚落英还好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15245, '如梦令', '吴潜', '镇日春阴漠漠。\n新燕乍穿帘幕。\n睡起不胜情，闲拾瑞香花萼。\n寂寞。\n寂寞。\n没个人人如昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15246, '如梦令', '吴潜', '庭院深深春寂。\n还是他乡寒食。\n闲利与闲名，谩把光阴虚掷。\n虚掷。\n虚掷。\n知道几时归得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15247, '如梦令', '吴潜', '闲向园林点检。\n又见小桃开遍。\n切莫便飘零，且为春光留恋。\n留恋。\n留恋。\n待我持杯深劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15248, '如梦令', '吴潜', '一饷园林绿就。\n柳外莺声初透。\n轻暖与轻寒，又是牡丹花候。\n花候。\n花候。\n岁岁年年人瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15249, '如梦令', '吴潜', '雨过远山如洗。\n云散落霞如绮。\n嫩绿与残红，又是一般春意。\n春意。\n春意。\n只怕杜鹃催里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15250, '望江南・忆江南', '吴潜', '家乡好，好处是三春。\n白白红红花面貌，丝丝袅袅柳腰身。\n锦绣底园林。\n行乐事，都付与闲人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15251, '望江南・忆江南', '吴潜', '家山好，好是夏初时。\n习习薰风回竹院，疏疏细雨洒荷漪。\n万绿结成帷。\n呼社友，长日共追随。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15252, '望江南・忆江南', '吴潜', '家山好，好处是秋来。\n绿橘黄橙随市有，岩花篱菊逐时开。\n管与付尊。\n新筑就，别馆共闲台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15253, '望江南・忆江南', '吴潜', '家山好，好处是三冬。\n梨栗甘鲜输地客，鲂鳊肥美献溪翁。\n醉滴小漕红。\n识破了，不用计穷通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15254, '望江南・忆江南', '吴潜', '家山好，结屋在山椒。\n无事琴书为伴侣，有时风月可招邀。\n安乐更相饶。\n伸脚睡，一枕日头高。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15255, '望江南・忆江南', '吴潜', '家山好，底事尚忘归。\n但我醉荣还避辱，从渠把是却成非。\n跳出世关机。\n将五十，老相已相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15256, '望江南・忆江南', '吴潜', '家山好，一室白云中。\n时唤道人谈命蒂，也呼和尚说禅宗。\n孔佛老和同。\n淘汰尽，八面总玲珑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15257, '望江南・忆江南', '吴潜', '家山好，负郭有田园。\n蚕可充衣天赐予，耕能足食地周旋。\n骨肉尽团圆。\n旋五福，岁岁乐丰年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15258, '望江南・忆江南', '吴潜', '家山好，有底尚萦牵。\n马後乐听馀十载，眼前赤看也多年。\n滋味只如然。\n身外事，不用强探拈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15259, '望江南・忆江南', '吴潜', '家山好，好处是安居。\n无事不须干郡县，有馀但管济乡闾。\n及早了王租。\n随日力，也著几般书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15260, '望江南・忆江南', '吴潜', '家山好，无事挂心怀。\n早课畦丁劝种菜，晚科园户漫浇花。\n祗此是生涯。\n尘世里，扰扰正如麻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15261, '望江南・忆江南', '吴潜', '家山好，百事尽如如。\n渴饮饥餐都属我，倒横直立总由渠。\n更不要贪图。\n三径里，恰好小茅庐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15262, '望江南・忆江南', '吴潜', '家山好，不是撰虚名。\n世上盛衰常倚伏，天家日月也亏盈。\n退步是前程。\n且恁地，卷索了收绳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15263, '望江南・忆江南', '吴潜', '家山好，凡事看来轻。\n一壑尽由侬，三才不欠你称停。\n有耳莫闲听。\n静地里，点检这平生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15264, '浪淘沙', '吴潜', '家在敬亭东。\n老桧苍枫。\n浮生何必寄萍蓬。\n得似满庭芳一曲，美酒千锺。\n万事转头空。\n聚散匆匆。\n片帆稳挂晓来风。\n别後平安真信息，付与飞鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15265, '浪淘沙', '吴潜', '长记去年时。\n雪满征衣。\n佳人携手画楼西。\n今日关山千里外，此恨谁知。\n想见绿窗低。\n依旧空闺。\n惜春还是惜花飞。\n纵有游蜂偷得去，争似帘帷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15266, '小重山', '吴潜', '溪上秋来晚更宜。\n夕阳西下处，碧云堆。\n谁家舟子采莲归。\n双白鹭，惊起背人飞。\n烟水渐凄迷。\n渔灯三数点，乍明时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15267, '昭君怨', '吴潜', '小雨霏微如线。\n人在暮秋庭院。\n衣袂带轻寒。\n睡初残。\n脉脉此情何限。\n惆怅光阴偷换。\n身世两沈浮。\n泪空流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15268, '南乡子', '吴潜', '去岁牡丹时。\n几遍西湖把酒卮。\n一种姚黄偏韵雅，相宜。\n薄薄梳妆淡淡眉。\n回首绿杨堤。\n依旧黄鹂紫燕飞。\n人在天涯春在眼，凄迷。\n不比巫山尚有期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15269, '虞美人', '吴潜', '美人一舸横秋水。\n冉冉烟波里。\n绿杨也解织离愁。\n故向东风摇曳、不能休。\n是非得失都休计。\n只有抽身是。\n橙黄蟹熟正当时。\n想见双溪风月、待人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15270, '生查子', '吴潜', '谁家白面郎，画舫朱帘挂。\n十二列金钗，一局文楸罢。\n歌舞不知休，醉倒荷花下。\n归棹踏烟波，灯火芜城夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15271, '武陵春', '吴潜', '惨惨凄凄秋渐紧，风雨更潇潇。\n强把炉薰寄寂寥。\n无语立亭皋。\n客路十年成底事，水国更停桡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15272, '二郎神', '吴潜', '小亭徙倚，慢一步、立秋千影。\n渐夕照林梢，晚风池上，缉缉轻寒嫩冷。\n又是将他春，酿一种、花愁花病。\n空客鬓岁迁，征衫人老，倚楼看镜。\n还省。\n故园多少，紫殷红凝。\n窗外晓莺啼，抚墙金缕，烟柳慵眠乍醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15273, '满江红', '吴潜', '为问人生，□要足、何时是足。\n这个底、蜗名蝇利，但添拘束。\n便使积官居鼎鼎，假饶累富堆金玉。\n似浮埃、抹电转头空，休迷局。\n分已定，心能服。\n宛句畔，昭亭曲。\n有水多於竹，竹多於屋。\n闲看白云归岫去，静观倦鸟投林宿。\n那借来、拍板与门槌，休掀扑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15274, '瑞鹤仙', '吴潜', '小亭山半枕。\n又一番园林，春事整整。\n微阴护轻冷。\n早蜂狂蝶浪，褪黄消粉。\n阑干日永。\n数花飞、残崖断井。\n仗何人、说与东风，莫把老红吹尽。\n休省。\n烟江云嶂，楚尾吴头，自来多景。\n愁高怅远。\n身世事，但难准。\n况禁他，东兔西乌相逐，古古今今不问。\n算鸱夷、办却扁舟，个中杀稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15275, '贺新郎', '吴潜', '一笑春无语。\n但园林、阴阴绿树，老红三数。\n底事东风犹自妒，片片狂飞乱舞。\n便燕懒、莺残初起。\n芍药荼シ还又是，仗何人、说与司花女。\n将岁月，浪如许。\n悠悠倦客停江渚。\n寄扁舟、浮云荡月，棹烟帆雨。\n留得闲言闲语在，可是卿卿记取。\n待尽把、愁肠说与。\n泛梗浮萍无定准，怕吴鳞、楚雁成离阻。\n歌未了，恨如缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15276, '水调歌头', '吴潜', '每怀天下士，要与共艰危。\n谁知暗里摸索，得此世间奇。\n却笑当年坡老，过眼翻迷五色，遇合古难之。\n访我鸳湖上，真足慰心期。\n醉谈兵，愁论世，夜阑时。\n自怜磊块，近来鬓底两三丝。\n目送云帆西去，肠断风尘北起，老泪欲垂垂。\n骐骥思长坂，好鸟择高枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15277, '青玉案', '吴潜', '十年三过苏台路。\n还又是、匆匆去。\n迅景流光容易度。\n鹭洲鸥渚，苇汀芦岸，总是消魂处。\n苍烟欲合斜阳暮。\n付与愁人砌愁句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15278, '水调歌头', '吴潜', '榆塞脱忧责，兰径遂游嬉。\n吾年逾六望七，休退已称迟。\n日日登山临水，夜夜早眠晏起，岂得不便宜。\n有酒数杯酒，无事一枰棋。\n休更□，世途恶，宦久羁。\n□深林密，去路人物两忘机。\n昨日既盟鸥鹭，今日又盟猿鹤，终久以为期。\n蜀魄不知我，犹道不如归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15279, '水调歌头', '吴潜', '有客抱幽独，高立万人头。\n东湖千顷烟雨，占断几春秋。\n自有茂林修竹，不用买花沽酒，此乐若为酬。\n秋到天空阔，浩气与云浮。\n叹吾曹，缘五斗，尚迟留。\n练江亭下，长忆闲了钓鱼舟。\n矧更飘摇身世，又更奔腾岁月，辛苦复何求。\n咫尺桃源隔，他日拟重游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15280, '满江红', '吴潜', '唤出山来，把鸥鹭、盟言轻食。\n依旧是、江涛如许，雨帆烟笛。\n歌罢莫愁檀板缓，杯倾白堕琼酥滴。\n但惊心、十六载重来，征埃客。\n秋风鬓，应非昔。\n夜雨约，聊相觅。\n叹主恩未报，无多来日。\n故国千年龙虎势，神州万里鼯迹。\n笑谢儿、出手便呼卢，掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15281, '满江红', '吴潜', '玛瑙冈头，左酾酒、右持螯食。\n怀旧处，磨东冶剑，弄清溪笛。\n望里尚嫌山是障，醉中要卷江无滴。\n这一堆、心事总成灰，苍波客。\n叹俯仰，成今昔。\n愁易揽，欢难觅。\n正平芜远树，落霞残日。\n自笑频招猿鹤怨，相期早混渔樵迹。\n把是非、得失与荣枯，虚空掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15282, '沁园春', '吴潜', '夜雨三更，有人枕，晓檐报晴。\n算顽云痴雾，不难扫荡，青天白日，元自分明。\n权植油幢，聊张皂纛，坐听前驺鼓角鸣。\n君休诧，岂宣申南翰，成旦东征。\n鸿冥。\n哽噎秋声。\n正万里榆关未罢兵。\n幸扬州上督，为吾石友，荆州元帅，是我梅兄。\n约束鲸鲵，奠安鼠，更使夷海晏清。\n连宵看，怕天狼隐耀，太白沈枪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15283, '沁园春', '吴潜', '笑指颓龄，循环雌甲，卦数已圆。\n叹蜀公高洁，休官去岁，温公耆旧，入社今年。\n底事崎岖，苍颜白发，犹拥貔貅护海。\n君恩重，算何能报国，未许归田。\n遥怜。\n宛居山前。\n正水涨溪肥系钓船。\n纵葵榴花闹，菖蒲酒美，都成客里，争似家边。\n寄语儿曹，若为翁寿，只把鸥盟更要坚。\n翁还祝，愿枪日静，云连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15284, '沁园春', '吴潜', '二十年前，君王东顾，诏牧此州。\n念昔时豪杰，犹难辟阖，如金老大，却更迟留。\n四载相望，三春又半，邂逅劭农得纵游。\n田畴事，是桑条正长，麦含初抽。\n悠悠。\n身世何求。\n算七十迎头合罢休。\n谩绕堤旌纛，牵连棹，喧天鼓吹，断送龙舟。\n翠层边，碧云堆处，一担担来天外愁。\n如何好，且同斟绿醑，自课清讴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15285, '宝鼎现', '吴潜', '晚风微动，净扫天地，云裾霞绮。\n将海外、银蟾推上，相映华灯辉万砌。\n看舞队、向梅梢然昼，丹焰玲珑玉蕊。\n渐陆地、金莲吐遍，恰似楼台临水。\n老子欢意随人意。\n引红裙、钗宝钿翠。\n穿夜市、珠筵玳席。\n多少吴讴联越吹。\n绣幕卷、散缤纷香雾，笼定团圆锦里。\n认一点、星球挂也，士女桃源洞里。\n闻说旧日京华，般百戏、灯棚如履。\n待端门排宴，三五传宣禁侍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15286, '昼锦堂', '吴潜', '绮毂团成，珠玑搦就，极目灯火楼台。\n七子八仙三教，耍队相挨。\n管箫笙簧相间斗，远如声韵碧霄来。\n环千炬，宝栅绛纱，云球雾衮交加。\n千里人笑乐，游妓合、脂尘香霭笼街。\n尽道今宵节物，天与安排。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15287, '贺新郎', '吴潜', '未是全衰暮。\n但相思、昭亭数曲，水村烟墅。\n只比儿儿额上寿，尚有时光如许。\n况坎子、常交离午。\n须信火龙能陆战，更驱他、水虎蟠沧浦。\n顶，时飞度。\n东皇蓦向遇。\n道如今、金阶玉陛，待卿阔步。\n犹恐荆人攀恋切，未放征帆高举。\n怕公去、狐狸嗥舞。\n江汉一时谁作者，想声声、赞祝明良聚。\n天下久，望霖雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15288, '贺新郎', '吴潜', '拍手阑干外。\n想回头、人非物是，不知何世。\n万事情知都是梦，聊复推迁梦里。\n也幻出、云山烟水。\n白白红红虽褪尽，尽倡条、浪蕊皆春意。\n时可醉，醉扶起。\n瀛洲旧说神仙地。\n奈江南、猿啼鹤泪，怨怀如此。\n三五阿婆涂抹遍，多少残樱剩李。\n又过雨、亭皋初霁。\n惭愧故人相问讯，但一回、一见苍颜耳。\n谁念我，鹪鹩志。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15289, '贺新郎', '吴潜', '宇宙原无外。\n问当年、渠缘底事，强逃人世。\n争似刘郎栽种後，长恁玄都观里。\n何用羡、武陵溪水。\n一见桃花还一笑，领春工、千古无穷意。\n儿女恨，且收起。\n洞中空阔多闲地。\n但人间、羊肠九折，未能知此。\n我已衰翁君渐老，那复颠张醉李。\n看翻覆、雨阴风霁。\n捱得清和时候了，舣扁舟、只待归来耳。\n惟处静，解吾志。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15290, '贺新郎', '吴潜', '了却儿痴外。\n撰园林、亭台馆榭，谩当吾世。\n红朱桥相映带，人在百花丛里。\n更依约、垂杨衬水。\n桧柏芙蓉橙桂菊，也还须、收拾秋冬意。\n闲坐久，忽惊起。\n繁华寂寞千年地。\n便渊明、桃源记在，几人知此。\n双手上还银菟印，趁得东风行李。\n看岭、鄞江澄霁。\n从此归欤无一欠，但君恩、天大难酬耳。\n嗟倦鸟，投林志。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15291, '贺新郎', '吴潜', '雪鬓难重绿。\n但け然、黄庭境界，抱藏龟六。\n也向无何乡里去，白堕舟边漾渌。\n算种种、尘缘都足。\n争那名缰犹系绊，尽辜他、猿鹤双溪曲。\n时又夏，暑将溽。\n虚舟飘瓦何烦。\n奈羊肠、千歧万折，近来纯熟。\n怅望老仙烟水外，惟把江云送目。\n想裴墅、碧梧金竹。\n安得结庐相近傍，买闲田、数亩躬耕筑。\n已梦断，大槐国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15292, '贺新郎', '吴潜', '燕子呢喃语。\n小园林、残红剩紫，已无三数。\n绿叶青枝成步障，空有蜂旋蝶舞。\n又宝扇、轻摇初暑。\n芳沼拳荷舒展尽，便回头、乱拥宫妆女。\n惊岁月，能多许。\n家山占断凫鸥渚。\n最相宜、岚烟水月，雾云霏雨。\n三岛十洲虽铁铸，难把归舟系取。\n且放我、渔樵为与。\n从此细斟昌酒，况神仙洞府无邀阻。\n何待结，长生缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15293, '贺新郎', '吴潜', '碧沼横梅屋。\n水平堤、双双翠羽，引雏偷浴。\n倚户无人深院静，犹忆棋敲嫩玉。\n还又是、朱樱初熟。\n手绾提炉香一炷，黯消魂、伫立阑干曲。\n闲转步，数修竹。\n新来有个眉峰蹙。\n自王姚、后魏都褪，只成愁独。\n凤带鸾钗宫样巧，争奈腰圈倦束。\n谩困倚、云鬟堆绿。\n淡月帘栊黄昏後，把灯花、印约休轻触。\n花烬落，泪珠簌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15294, '贺新郎', '吴潜', '宝扇驱纤暑。\n又凄凉、蒲觞菰忝，异乡重午。\n巧索从来无人系，惟对榴花自语。\n也何用、讴秦舞楚。\n生愧孟尝搀一日，叹三千、客汗挥成雨。\n如伯始，谩台傅。\n循环浩劫无终古。\n但坤牛、乾马抽换，是长生谱。\n安得笺天天便许，归炼金翁木父。\n问海运、争如穴处。\n一笑流行还坎止，算陈陈、往事俱灰土。\n南墅鹤，想思主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15295, '暗香', '吴潜', '晓霜一色。\n正恁时陇上，征人横笛。\n驿史不来，借问孤芳为谁折。\n休说和羹未晚，都付与、逋仙吟笔。\n算只是，野店疏篱，樵子共争席。\n寒圃，众籁寂。\n想暗里度香，万斛堆积。\n恼他鼻观，巡索还无最堪忆。\n萼绿堂前一笑，封老干、苔青莓碧。\n春漏也，应念我、要归未得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15296, '疏影', '吴潜', '佳人步玉。\n待月来弄影，天挂参宿。\n冷透屏帏，清入肌肤，风敲又听檐竹。\n前村不管深雪闭，犹自绕、枝南枝北。\n算平生、此段幽奇，占压百花曾独。\n闲想罗浮旧恨，有人正醉里，姝翠蛾绿。\n梦断魂惊，几许清凉，却是千林梅屋。\n鸡声野渡溪桥滑，又角引、戌楼悲曲。\n怎得知、清足亭边，自在杖藜巾幅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15297, '暗香', '吴潜', '雪来比色。\n对澹然一笑，休喧笙笛。\n莫怪广平，铁石心肠为伊折。\n偏是三花两蕊，消万古、才人骚笔。\n尚记得，醉卧东园，天幕地为席。\n回首，往事寂。\n正雨暗雾昏，万种愁积。\n锦江路悄，媒聘音沈两空忆。\n终是茅檐竹户，难指望、凌烟金碧。\n憔悴了、羌管里，怨谁始得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15298, '疏影', '吴潜', '寒梢砌玉。\n把胆瓶顿了，相伴孤宿。\n寂寞幽窗，筛影横斜，宜松更自宜竹。\n残更蝶梦知何处，□只在、昭亭山北。\n问平生、雪压霜欺，得似老枝擎独。\n何事胭脂点染，认桃与辨杏，枝叶青绿。\n莫是冰姿，改换红妆，要近金门朱屋。\n繁华艳丽如飞电，但宛转、断歌零曲。\n且不如、藏白收香，旋学世间边幅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15299, '暗香', '吴潜', '澹然绝色。\n记故园月下，吹残龙笛。\n怅望楚云，日日归心大刀折。\n犹怕冰条冷蕊，轻点污、丹青凡笔。\n可怪底，屈子离骚，兰蕙独前席。\n院宇，深更寂。\n正目断古邗，暮霭凝积。\n何郎旧梦，四十馀年尚能忆。\n须索梅兄一笑，但矫首、层霄空碧。\n春在手、人在远，倩谁寄得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15300, '疏影', '吴潜', '嗤琼笑玉。\n向画堂可肯，风露边宿。\n耐冻禁寒，便瘦宜枯，前生莫是孤竹。\n从来不上春工谱，梦不到、沈香亭北。\n算只消、澹影疏香，伴个幽栖人独。\n莫待痴蜂呆蝶，倩青女捺住，多少红绿。\n落雁寒芦，翠鸟冰枝，近傍三间茅屋。\n□□□□□□□，□□□、□□□□。\n想这般，夷旷襟怀，渺视乾员坤幅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15301, '暗香', '吴潜', '九垓共色。\n想洛滨剑客，吹呼长笛。\n豸老松，别树平欺烂柯折。\n应是千官鹤舞，腾贺表、谁家椽笔。\n赐宴也，内劝宣来，真个是瑶席。\n休怪，巷陌寂。\n有一种可人，扫了还积。\n悲饥闭户，僵卧袁安我偏忆。\n凝望天童列嶂，谁大胆、偷藏遥碧。\n待问讯、清友看，怕难认得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15302, '疏影', '吴潜', '千门委玉。\n是个人富贵，才隔今宿。\n冒栋摧檐，都未商量，呼童且伴庭竹。\n千蹊万径行踪灭，渺不认、溪南溪北。\n问白鸥，此际谁来，短艇钓鱼翁独。\n偏爱山茶雪里，放红艳数朵，衣素裳绿。\n兽炭金炉，羔酒金锺，正好笙歌华屋。\n敲冰煮茗风流衬，念不到、有人洄曲。\n但老农、欢笑相呼，麦被喜添全幅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15303, '水龙吟', '吴潜', '十洲三岛蓬壶，是花锦、一团装就。\n轻车细辇，绮罗香里，夜光如昼。\n朱户笙箫，画楼帘幕，有人回首。\n想金莲灿烂，星球缥缈，那风景、年时旧。\n应念白头太守。\n怎红旗、六街穿透。\n铺排玳席，追陪珠履，且酾春酎。\n楚舞秦讴，半慵莺舌，叠翻鸳袖。\n把千门喜色，万家和气，祝君王寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15304, '永遇乐', '吴潜', '和气熏来，这般光景，管无风雨。\n画栋朱甍，锦坊绣巷，娘子将嫫母。\n星球高挂，灯楼趱出，良夜正消增五。\n遨头事，牙旗铁马，且还那时鄞府。\n甘泉见说，捷书频奏，渐次不烦颦鼓。\n双凤云间，六鳌海上，祝赞齐手舞。\n三呼声里，君王万寿，岁岁传柑笑语。\n便都把，升平旧曲，腔儿旋补。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15305, '永遇乐', '吴潜', '天上人间，这般光景，管无风雨。\n绣户珠帘，锦坊花巷，戏队将嫫母。\n月扇团圆，星球灿烂，路偏市三街五。\n升平事，牙旗铁马，且还旧家藩府。\n三垂见说，凯歌频奏，渐次不烦颦鼓。\n双凤云间，六鳌尘外，想间都人欢舞。\n火城春近，金莲地市，消夜果边曾语。\n如今但，梅花纸帐，睡魔欠补。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15306, '永遇乐', '吴潜', '祝告天公，放灯时节，且收今雨。\n万户今门，六街三市，绽水晶云母。\n香车宝马，珠帘翠幕，不怕禁更敲五。\n霓裳曲，惊回好梦，误游紫宫朱府。\n沈思旧日京华，风景逗晓，犹听戏鼓。\n分镜圆时，断钗合处，倩笑歌与舞。\n如今闲院，蜂残蛾褪，消夜果边自语。\n亏人，梅花纸帐，权将睡补。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15307, '隔浦莲・隔浦莲近拍', '吴潜', '兰桡环城数叠。\n雾雨侵帘箔。\n翠竹交苍树，幽鸟声声如答。\n苇岸游绿鸭。\n暮山合。\n天际浓云罨，水周币。\n提携一醉，浊贤清圣欢洽。\n瀛洲美景，尽道东南都压。\n今日愁颜回笑颊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15308, '隔浦莲・隔浦莲近拍', '吴潜', '扇荷偷换羽葆。\n院宇人声窈。\n独步亭皋下，阑干并、栖幽鸟。\n新雨抽嫩草。\n檐花闹。\n一片萍铺沼。\n燕雏小。\n书空底事，那堪手版持倒。\n今来古往，几见北邙人晓。\n乡号无何但日到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15309, '水调歌头', '吴潜', '小队旌旗出，画倚嵩竹。\n青秧白水无际，中有一犁耕。\n听得田翁相语，今岁时年恰好，眨眼是秋成。\n老守何能解，持此报皇明。\n望家山，千里外，楚云平。\n良田二顷，非村非郭枕柴局。\n况有檐林香透，更有杨堤阴合，魂梦每宵征。\n巴得西风起，吾亦文前程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15310, '水调歌头', '吴潜', '老圃无关锁，放客意中行。\n颇欣天地开阔，烟钓与云耕。\n荷长亭亭翠盖，竹长森森翠葆，景致闹装成。\n几树榴花发，映水色偏明。\n绮楼空，金屋静，恨难平。\n鼓笙潇笛，谁怜冷落暗尘局。\n回首百年人事，转眼几番今古，日迈月俱征。\n且尽一杯酒，退步是前程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15311, '水调歌头', '吴潜', '过了中秋後，今夜月方佳。\n看来前夜圆满，才自阙些些。\n扫尽乌云黑雾，放出青霄碧落，恰似我情怀。\n把酒自斟酌，脱落到形骸。\n问渠侬，分玉镜，断金钗。\n少年心事，不知容易鬓边华。\n千古天同此月，千古人同此兴，不是旋安排。\n安得高飞去，长以月为家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15312, '水调歌头', '吴潜', '重九先三日，领客上危楼。\n满城风雨都住，天亦相邀头。\n右手持杯满泛，左手持螯大嚼，萸菊互相酬。\n徒倚阑干角，一笑与云浮。\n望平畴，千万顷，稻粱收。\n江澄海晏无事，赢得小迟留。\n但恨流光抹电，假似年华七十，只有六番秋。\n戏马台休问，破帽已飕飕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15313, '水调歌头', '吴潜', '天宇正高爽，更蹑最高楼。\n长风为我驱驾，极目海山头。\n不用牛山孟浩，不用齐山杜牧，人景自堪酬。\n举酒酹空阔，汗漫与为游。\n拈黄花，怜白首，恨难收。\n颓龄使汝能制，何待更封留。\n眼底朱甍画栋，往往人非物是，蟋蟀自鸣秋。\n万里一搔首，无处著萧飕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15314, '水调歌头', '吴潜', '屯结海云阵，奋击藉雷公。\n忽然天宇轩豁，杲日正当空。\n照出榴花丹艳，映出栀花玉色，生意与人同。\n闭纵一翻手，造化不言功。\n想平畴，禾，黍芄芄。\n老农拍手相问，相劳笑声中。\n办取黄鸡白酒，演了山歌村舞，等得庆年丰。\n此际莼鲈客，倚楫待西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15315, '二郎神', '吴潜', '古稀近也，是六十五翁生日。\n恰就得端阳，艾人当户，朱笔书符大吉。\n卦气周来从新起，怕白发、苍颜难必。\n随见定性缘，餐饥眠困，喜无秋唧。\n盈溢。\n书生做到，能高官秩。\n况碌碌儿曹，望郎明郡，叨冒差除不一。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15316, '二郎神', '吴潜', '近时厌雨，喜午日、放开天日。\n不用辟兵符，从今去也，管定千祥万吉。\n已报甘泉新捷到，况更是、年丰堪必。\n任景物换来，蛙鸣蝉噪，耳边唧。\n洋溢。\n尽教愿乞，兵厨闲秩。\n看恰好圆池，随宜亭榭，人道瀛洲压一。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15317, '传言玉女', '吴潜', '众绿亭前，都是郁葱佳气。\n越姬吴媛，粲珠钿翠珥。\n红消粉褪，几许粗桃凡李。\n连珠宝炬，两行缇骑。\n自笑衰翁，又行春锦绣里。\n禁肴宫酝，记当年宣赐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15318, '满江红', '吴潜', '芳景无多，又还是、乱红飞坠。\n空怅望、昭亭深处，家山桃李。\n柳眼花心都脱换，蜂须蝶翅难沾缀。\n谩相携、一笑竞良辰，春醪美。\n金兽艺，香风细。\n金凤拍，歌云腻。\n尽秦箫燕管，但逢场尔。\n只恐思乡情味恶，怎禁寒食清明里。\n问此翁、不止四宜休，翁归未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15319, '满江红', '吴潜', '聊把芳尊，殷勤勤、斜阳休坠。\n吾老矣，难从仙客，采丹丘李。\n且趁风光一百五，园林尚有残红缀。\n更忉忉、百舌对般春，生能美。\n鸾钗绊，游丝细。\n鸳袖惹，香尘腻。\n想吴姬越女，踏青才尔。\n争似江南樗枥社，俚歌声拂行云里。\n又枝头、梅子正酸时，莺知未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15320, '满江红', '吴潜', '楼观峥嵘，浑疑是、天风吹坠。\n金屋窈，几时曾贮，粗桃凡李。\n镜断钗分人去後，画阑文砌苍苔缀。\n想当年、日日醉芳丛，侯鲭美。\n春水涨，鳞鳞细。\n春草暗，茸茸腻。\n算留连光景，古犹今尔。\n椿菌鸠鹏休较计，倚空一笑东风里。\n喜知时、好雨夜来稠，秧青未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15321, '满江红', '吴潜', '一笑相携，且休管、兔升乌坠。\n那更是，可人宾客，未饶崔李。\n金叵罗中莹，玉玲珑畔歌珠缀。\n望湖光、一片浸韶光，真双美。\n云絮襞，能纤细。\n云彩聚，能黏腻。\n料出山归岫，等闲间尔。\n碧风流人去後，石窗景物春深里。\n算邯郸、客梦几惊残，炊犹未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15322, '满江红', '吴潜', '问海棠花，谁留恋、未教飘坠。\n真个好，一般标格，聘梅奴李。\n怯冷拟将苏幕护，怕惊莫把金铃缀。\n望铜梁、玉垒正春深，花空美。\n非粉饰，肌肤细。\n非涂泽，胭脂腻。\n恐人间天上，少其伦尔。\n西子颦收初雨後，太真浴罢微暄里。\n又明朝、杨柳插清明，鹃归未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15323, '满江红', '吴潜', '把手西园，有山色、波光相对。\n金马客，明朝飞棹，水肥帆驶。\n问我年华旬并七，异乡时景春巴二。\n最堪怜、游子送行人，垂杨外。\n聊小小，旌旗队。\n聊且且，笙歌载。\n正冥烟雨，许多情态。\n南北枝头犹点缀，东西玉畔休辞避。\n待莼鲈、归思动西风，相携未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15324, '满江红', '吴潜', '斫却凡柯，放岩桂、出些头地。\n从此去，引风披露，畅条昌蕊。\n待得清香千万斛，且饶老子为知己。\n趁今宵、新月驾空来，浮觞里。\n刘安笑，淹留耳。\n吴猛约，何时是。\n想故山深处，翠垂金缀。\n须信人生归去好，他乡未必江山美。\n问钗头、十二意如何，非吾事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15325, '满江红', '吴潜', '试问平生，几番见、中秋明月。\n今老矣，一年紧似，一年时节。\n底事层阴生障碍，不教玉界冰壶彻。\n莫垣娥、嫌此白头翁，心肠别。\n风动处，浮云揭。\n云绽处，清光泄。\n倩何人扫荡，大家澄澈。\n且掉悲欢离合事，相逢只怕尊中竭。\n放儿童、今夜上清霄，探蟾穴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15326, '满江红', '吴潜', '丹桂重开，向此际、十分香足。\n最好处，云为幕护，雨为膏沐。\n树杪层层如宝盖，枝头点点犹金粟。\n算人间、天上更无花，风流独。\n玉坛畔，仙娥簇。\n玉梁上，仙翁掬。\n叹吾今老矣，两难追逐。\n休把淹留成感慨，时间赏玩时闲福。\n怕今宵、芳景便凋零，高烧烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15327, '满江红', '吴潜', '岁岁重阳，何曾是、两般时景。\n人自有、悲欢离合，晦明朝暝。\n日月湖边来往艇，楼台水底参差影。\n又何妨、时暂狎沧波，轻鸥并。\n闲顿放，朱门静。\n新结裹，朱帘整。\n尽百年人事，移场换境。\n欲插黄花身已老，强倾绿醑心先醒。\n羡游鱼、有钓不能收，钩空饼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15328, '满江红', '吴潜', '安晚堂前，梅开尽、都无留萼。\n依旧是、铁心老子，故情堪托。\n长恐寿阳脂粉污，肯教摩诘丹青摸。\n纵沈香、为榭彩为园，难安著。\n高节耸，清名邈。\n翻李俗，粗桃恶。\n但山矾行辈，可来参错。\n六出不妨添羽翼，百花岂愿当头角。\n尽暗香、疏影了平生，何其乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15329, '满江红', '吴潜', '犹记长安，共攀折、琼林仙萼。\n人已去，年年梅放，怨怀谁托。\n和靖吟魂应未醒，补之画手何能摸。\n更堪怜、老子此时来，愁难著。\n云昼晚，烟宵邈。\n春欲近，风偏恶。\n早阑干片片，飘零相错。\n邂逅聊拼花底醉，迟留莫管城头角。\n且起居、魏卫国夫人，闻安乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15330, '满江红', '吴潜', '问信江梅，渐推出、红苞绿萼。\n堪爱处，平生怀抱，岁寒为托。\n瘦骨皱皮犹老硬，孤标独韵难描摸。\n怕东君、压住等春来，鞭先著。\n止渴事，风烟邈。\n和羹事，风波恶。\n想翠禽啁哳，笑他都错。\n争似花开颓醉玉，月天更引霜天角。\n便一年、强作十年人，山中乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15331, '满江红', '吴潜', '寒食清明，叹人在、天涯海角。\n饶锦绣，十洲装就，只成离索。\n岁去已空莺燕侣，年来尽负鸥凫约。\n想南溪、溪水一篙深，孤舟泊。\n天向晚，东风恶。\n春向晚，花容薄。\n又荼縻架底，绿阴成幄。\n舴艋也闻钲鼓闹，秋千半当笙歌乐。\n问山公、倒载接无，都休却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15332, '满江红', '吴潜', '钉残花，也随分、红红白白。\n缘底事，春才好处，又成轻别。\n芳草凄迷归路远，子规更叫黄昏月。\n倚阑干、触处是浓愁，凭谁说。\n我不厌，尊挈。\n君莫放，笙歌彻。\n自河南丞相，有兹宾客。\n一笑何曾千古换，半醺便觉乾坤窄。\n怕转头、天际望归舟，江山隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15333, '满江红', '吴潜', '午枕神游，晓鸡唱、城关偷度。\n俄顷里、笋舆伊轧，征夫前路。\n路入江南天地阔，黄云翠浪千千亩。\n有皤翁、三五喜相迎，邻田父。\n旋策杖，寻幽圃。\n旋挈，陈高俎。\n疑此身归去，朱陵丹府。\n布谷数声惊梦断，纱窗小阵梅黄雨。\n把人间、万事一般看，投芳醑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15334, '满江红', '吴潜', '回首家园，竹多屋、水还多竹。\n那更是，千峰凝翠，一溪凝绿。\n多谢故人相问讯，奚奴步步收珠玉。\n叹暮林、飞鸟也知还，寻归宿。\n遍历了，岳与牧。\n享过了，官与禄。\n算平生万事，尽无不足。\n争奈乞身犹未可，只缘欠种清闲福。\n想瞿硎、仙子亦相思，山之。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15335, '念奴娇', '吴潜', '一般妙质，笑乐天、夸诧小蛮樊素。\n万炳参差罗翠扇，全队西方靓女。\n不假施朱，也非涂碧，所乐惟幽浦。\n神仙姑射，算来合共游处。\n一任冶妓姬，采莲歌里，尽是相思苦。\n花气荷馨清入骨，长傍银河东注。\n月澹风轻，雾烟细，忽洒霏微雨。\n此时心事，美人泽畔停伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15336, '念奴娇', '吴潜', '为嫌涂抹，向万红丛里，澹然疑素。\n非粉非酥能样别，只是凌波仙女。\n隋沼浓妆，汉池冶态，争似沧浪浦。\n净鸥洁鹭，有时飞到佳处。\n梦绕太华峰巅，与天一笑，不觉跻攀苦。\n十丈藕船游汗漫，何惜浮生孤注。\n午鼓惊回，依然尘世，扑簌疏窗雨。\n起来寂寞，倚阑一饷愁伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15337, '念奴娇', '吴潜', '白苹影里，向何人可话，平生心素。\n月魄冰魂凝结就，犹薄湘妃洛女。\n吴沼芙蓉，陈陂菡萏，散入玄珠浦。\n采花蜂蝶，雾深都忘归去。\n堪笑并蒂霞冠，双头酡脸，只为多情苦。\n空遣隔江游冶子，撩乱心飞目注。\n同出泥涂，独标玉质，不是曼陀雨。\n风清露冷，有人长自迟伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15338, '念奴娇', '吴潜', '天然皓质，想当年此种，来从太素。\n一点红尘都不染，罗列蟾宫玉女。\n色压林，香欺兰畹，肯向闻筝浦。\n灵龟千岁，有时游漾其处。\n应念社结庐山，翻嗤靖节，底事攒眉苦。\n纽叶为盘花当盏，有酒何妨频注。\n太液波边，昆明池上，岂必沾金雨。\n从教同辈，为他凝伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15339, '念奴娇', '吴潜', '午飙褪暑，向绿阴深处，引杯孤酌。\n啼鸟一声庭院悄，日影偷移朱箔。\n杏落金丸，荷抽碧筒，景物挨排却。\n虚檐长啸，世缘菌簟箨。\n休问雪藕丝蒲，佩兰钿艾，旧梦都高阁。\n惟有流莺当此际，舌弄笙簧如约。\n短棹双溪，么锄三径，归计犹谁托。\n料应猿鹤，近来都怨离索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15340, '八声甘州', '吴潜', '向鄞江、面熟是薰风，吹燕麦凫葵。\n赖君王洪福，河清可晏，物阜人熙。\n想见搴帷使者，随处采声诗。\n羡高禽弋，离贴天飞。\n飞到苍云深处，便敛收毛羽，望暮林归。\n可以人不若，地挂征衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15341, '感皇恩', '吴潜', '老去最难禁，流光如水。\n甲子徒头试□指。\n年年生日，怕被旁人拈起。\n若攀儿额，颓龄犹未。\n方丈瀛洲，蓝溪碧。\n转眼鲈莼便秋意。\n君主定许，整顿江头行李。\n角巾归去也，休里第。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15342, '谒金门', '吴潜', '纱窗晓。\n杜宇数声声悄。\n真个不如归去好。\n天涯人已老。\n欹枕欲眠还觉。\n犹有青灯残照。\n谩道惜花春起早。\n家山千里杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15343, '谒金门', '吴潜', '停画。\n天外水澄烟碧。\n莫看遨头人似织。\n今年都老色。\n最苦今朝离夕。\n未卜今年归日。\n生怕晚风消酒力。\n愁城难借一。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15344, '谒金门', '吴潜', '山客野。\n新把朝衔书写。\n应想江南樗枥下。\n踏歌鸡黍社。\n休问坤牛乾马。\n大率人生且且。\n聊唤玉人斟玉。\n莫辞沈醉也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15345, '谒金门', '吴潜', '风韵彻。\n满架平平铺雪。\n贾女何郎盟共结。\n睡浓香更冽。\n春去悄怀怎说。\n却喜不闻蹄。\n月夜时来闲蹀。\n故园三载别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15346, '浣溪沙', '吴潜', '庆赏元宵只愿情。\n天公每事秤能平。\n管教檐溜便收声。\n三市海巡那惜夜，九街社火亦争名。\n权将歌酒作工程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15347, '浣溪沙', '吴潜', '春岸春风荻已芽。\n推排春事到芦花。\n只应推上鬓边华。\n投老未归真左计，久阴得霁且舒怀。\n红红白白有残葩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15348, '浣溪沙', '吴潜', '海棠已绽牡丹芽。\n犹有东君向上花。\n不须惆怅怨春华。\n装缀园林新景物，推敲风月旧情怀。\n也饶浪蕊与浮葩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15349, '浣溪沙', '吴潜', '正好江乡笋蕨芽。\n他乡却看担头花。\n只将蝶梦付南华。\n万事纷纭都入幻，一杯邂逅且忘怀。\n年年秋卉与春葩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15350, '浣溪沙', '吴潜', '雨过池堂水长芽。\n放开晴日正宣花。\n十洲三岛撰繁华。\n水畔丽人唐客恨，山阴佳客晋人怀。\n可怜云蕊与风葩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15351, '浣溪沙', '吴潜', '最好荼縻白间黄。\n消他蜂蝶采花忙。\n春残红粉厌梳妆。\n毕卓正思身夜瓮，刘章底用令秋霜。\n今宵帏枕十分香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15352, '浣溪沙', '吴潜', '宫额新涂一半黄。\n蔷薇空自效颦忙。\n澹然风韵道家妆。\n可惜今宵无皓月，尚怜向晓有繁霜。\n何妨手拈一枝香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15353, '海棠春', '吴潜', '海棠亭午沾疏雨。\n便一饷、胭脂尽吐。\n老去惜花心，相对花无语。\n羽书万里飞来处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15354, '海棠春', '吴潜', '嫩晴还更宜轻雨。\n最好处、欲开未吐。\n一点聘梅心，千古凭谁语。\n脸霞晕锦娇人处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15355, '海棠春', '吴潜', '苍龙夭矫停今雨。\n正不待、云吞雾吐。\n绝笑大夫松，今古闲言语。\n清光冷艳侵入处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15356, '霜天晓角', '吴潜', '倚花傍月。\n花底歌声彻。\n最好月筛花影，花月浸、香奇绝。\n双溪秋月洁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15357, '霜天晓角', '吴潜', '此花此月。\n一般风流彻。\n更好参横斗转，更漏断、人声绝。\n有谁秋共洁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15358, '霜天晓角', '吴潜', '杯中吸月。\n桂树飞琼屑。\n莫道胡床老子，怕风露、向凄冽。\n回首云娥折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15359, '霜天晓角', '吴潜', '为花问月。\n谁把金魂屑。\n犹有残英剩蕊，秋向老、香逾冽。\n且莫都攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15360, '霜天晓角', '吴潜', '新词唱彻。\n字字珠玑屑。\n更有张颠草圣，何止是、成双绝。\n金粟如霏雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15361, '霜天晓角', '吴潜', '小山幽彻。\n遍地堆香雪。\n只恐今宵入梦，梦到处、魂孤绝。\n八公头已雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15362, '霜天晓角', '吴潜', '梅花一簇。\n花上千枝烛。\n照出靓妆姿态，看不足、咏不足。\n便欲和花宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15363, '霜天晓角', '吴潜', '秋凉佳月。\n扫尽轻衫热。\n便欲乘风归去，冰玉界、琼林阙。\n不须持寸铁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15364, '霜天晓角', '吴潜', '举杯吸月。\n一洗烦襟热。\n想见摩诃池上，星斗转、挂银阙。\n金吾传漏铁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15365, '蝶恋花', '吴潜', '澹白轻黄纯雅素。\n一段风流，欹枕疏窗户。\n夜半香魂飞欲去。\n伴他月里霓裳舞。\n消得留春春且住。\n不比杨花，轻作沾泥絮。\n况是成阴环幄处。\n不愁更被红窗妒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15366, '朝中措', '吴潜', '春空一鸟落云干。\n只遣客心酸。\n勺药牡丹时候，午窗轻暖轻寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15367, '朝中措', '吴潜', '可人想见倚庭干。\n嚼句有甘酸。\n休问沈腰潘鬓，何妨岛瘦郊寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15368, '朝中措', '吴潜', '杨花撩乱与云干。\n春事可悲酸。\n况是雨荒院落，江南但有春寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15369, '朝中措', '吴潜', '夜来梦绕宛溪干。\n啼梦中酸。\n过了他乡寒食，白鸥划地盟寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15370, '朝中措', '吴潜', '兰皋彻夜树旄干。\n战渴望梅酸。\n想有歌姬半臂，更深自可鏖寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15371, '朝中措', '吴潜', '衰翁老大脚犹轻。\n行到净凉亭。\n近日方忧多雨，连朝且喜长晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15372, '虞美人', '吴潜', '东风催客呼前渡。\n宿鸟投林暮。\n欲送人送得归人。\n万叠青山罗列、是愁城。\n谁家台榭当年筑。\n芳草垂杨绿。\n云深雾暗不须悲。\n只缘盈虚消息、少人知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15373, '秋霁', '吴潜', '阶砌吟蛩，正竹外萧萧，雨骤风驶。\n凉浸桃笙，暑消葵扇，借伊一些秋意。\n枕边茉莉。\n满尘奁、贮香能腻。\n也不用，玉骨冰肌，人伴佳眠尔。\n谁信此境，渐入华胥，旷然不知，庄蝶谁是。\n笑邯郸、羁魂客梦，贪他荣贵暂时里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15374, '洞仙歌', '吴潜', '□□□□，□□□□瘦。\n□□□□□□酒。\n□□深，碎蕊残萼都收，归簟枕，谁道栀橐敢就。\n月边偏爱惜，冰玉肌肤，应对垣娥共搔首。\n疑怪得中原，讹道天花，胡尘後、可堪怀旧。\n且海国、浮沈醉花心，喜近日烽烟，渐消亭候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15375, '洞仙歌', '吴潜', '冠儿遍簇，那时人消瘦。\n玉琼卮劝君酒。\n是清凉境界，露湿烟凝，香更重，非是沈檀合就。\n四窗花满砌，争似家山，橙蟹将肥重回首。\n花亦为君怜，草木禽鱼，相思处、莫如乡旧。\n更西风、溪莼与香鲈，想别墅樵渔，费他侦候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15376, '小重山', '吴潜', '碧霄如水月如钲。\n今宵知为我，特分明。\n冰壶玉界两三星。\n清露下，渐觉湿衣轻。\n高树点流萤。\n秋声还又动，客心惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15377, '醉桃源・阮郎归', '吴潜', '东风阑槛两三亭。\n游人步晚晴。\n蜂回蝶转得能轻。\n忽然春意生。\n花未老，酒须倾。\n劝君休独醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15378, '青玉案', '吴潜', '流芳只怕春无几。\n拼夜饮、更才二。\n不用追他欢乐事。\n绮窗朱户，燕帷莺馆，多少人憔悴。\n踏歌梦想江南市。\n管春尽、扁舟放行李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15379, '点绛唇', '吴潜', '岸舣扁舟，江南有个人归老。\n簇新亭沼。\n分付还他了。\n凝伫晴空，一抹天边鸟。\n嗟潦倒。\n去多来少。\n莫问钟昏晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15380, '清平乐', '吴潜', '轻轻却暑。\n只是些儿雨。\n喜看新抽麻与苎。\n他家烟水墅。\n晚山放出青青。\n是谁簸弄阴晴。\n老子何时去也，祗应露湿金茎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15381, '渔家傲', '吴潜', '每日困慵当午昼。\n出来便解双眉皱。\n一带朦胧烟雨岫。\n山翁瘦。\n林泉纵好他园囿。\n一见此君如话旧。\n玉版老师呼唤候。\n万立琅争劝酒。\n踌躇久。\n清风收拾归怀袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15382, '渔家傲', '吴潜', '遍阅芳园闲半昼。\n残花尚有榴裙皱。\n倦鸟投林云返岫。\n人影瘦。\n可怜身世为他囿。\n燕子飞来还忆旧。\n回头又是梅黄候。\n且尽一杯昌酒。\n凝睇久。\n晚风细雨沾衫袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15383, '柳梢青', '吴潜', '绿野平泉，古来人事，空里飞花。\n月榭风亭，荷漪藓石，说郑公家。\n老梅傍水茶牙。\n人那得、光阴似他。\n万种思量，百年倒断，付与残霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15384, '柳梢青', '吴潜', '好把元宵。\n良辰美景，暮暮朝朝。\n万盏华灯，一轮明月，燕管秦箫。\n何人帕坠鲛绡。\n有玉凰、金鸾绣雕。\n目下欢娱，眼前烦恼，只在今宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15385, '贺圣朝', '吴潜', '捷书夜半甘泉去。\n报天骄膏斧。\n摩空铜垒，闸流瞿滟，扫清云雾。\n楼兰飞馘，焉耆授首，谩夸称前古。\n须知开庆，太平千载，方从今数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15386, '浪淘沙', '吴潜', '望月眼穿东。\n云幕千重。\n有时推出赖他风。\n恰似玉环犹未窦，得恁玲珑。\n谁在华山峰。\n一半天中。\n君逾五十我成翁。\n未必明年如此夜，笑口难逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15387, '贺新郎', '吴潜', '汲水驱炎热。\n晚些儿、披衣露坐，待他凉月。\n俄顷银盘从海际，推上璇霄璧阙。\n尽散作、满怀冰雪。\n万里河潢收卷去，掩长庚、弧矢光都灭。\n一大片，琉璃揭。\n玉ょ药何时歇。\n几千年、阴晴隐现，团圆亏缺。\n月缺还圆人但老，重换朱颜无诀。\n想旧日、嫦娥心别。\n且吸琼浆斟北斗，尽今来、古往俱休说。\n香茉莉，正清绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15388, '贺新郎', '吴潜', '月绽浮云里。\n未须臾、长风扫荡，碧空如水。\n谁在冰壶玉界上，眇视征蛮战蚁。\n便弃掷、尘寰脱屣。\n葛清冷紧袖冷，露华浓、暗袭人肌理。\n和酷暑，争些气。\n谯楼漏转三更二。\n夜沈沈、经星纬宿，换垣移市。\n万籁渐生秋意思，时节那堪屈指。\n奈投老、未酬归计。\n矫首高天天不应，忽林梢、睡鹊惊飞起。\n同一梦，我与尔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15389, '鹊桥仙', '吴潜', '银河半隐，玉蟾高挂，已觉炎光向後。\n穿针楼上未眠人，应自把、荷花揉。\n双星缥缈，霎时聚散，肯向鹊桥回首。\n原来一岁一番期，却捱得、天长地久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15390, '鹊桥仙', '吴潜', '馨香饼饵，新鲜瓜果，乞巧千门万户。\n到头人事控抟难，与拙底、无多来去。\n痴儿忘想，夜看银汉，要待云车飞度。\n谁知牛女已尊年，又那得、欢娱意绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15391, '秋夜雨', '吴潜', '不嫌天上云遮月。\n雨来正是双绝。\n雷公驱电母，尽收卷、十分袢热。\n三更又报初秋了，少待他、西风凄冽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15392, '秋夜雨', '吴潜', '云头电掣如金索。\n须臾天尽帏幕。\n一凉恩到骨，正骤雨、盆倾檐角。\n桃笙今夜难禁也，赖醉乡、情分非薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15393, '秋夜雨', '吴潜', '单于系颈须长索。\n捷书新上油幕。\n尽沈边柝也，更底问、悲笳哀角。\n衰翁七十迎头了，先自来、声利都薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15394, '秋夜雨', '吴潜', '吴翁里第还巾角。\n不妨天地席幕。\n家僮归报道，快酿酒、休教薄。\n相逢聚散应搔首，且趁时、一笑为乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15395, '秋夜雨', '吴潜', '西风半入孤城角。\n人生归燕巢幕。\n倦翁衰甚也，又不是、官卑禄薄。\n收绳卷索今番稳，尽一丘一壑足乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15396, '秋夜雨', '吴潜', '晚来小雨鸣檐角。\n又还烟障云幕。\n四明窗透荡，渐夜永、衫轻薄。\n候虫但要吟教老，不管人、老欠欢乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15397, '生查子', '吴潜', '坐临芳沼边，荷气侵衣湿。\n唧唧暗蛩鸣，点点流萤入。\n人生歧路中，底用杨朱泣。\n一笑倚阑干，颓玉当风立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15398, '生查子', '吴潜', '夜夜云气浮，带得香烟湿。\n万籁本无情，一一秋声入。\n须臾离合间，应笑儿曹泣。\n新雨涨鄞江，明日桅樯立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15399, '西河', '吴潜', '都会地。\n东南盛府堪记。\n蓬莱缥缈十洲中，雉城拥起。\n凭高一盼大江横，遥连沧海无际。\n壁同众山翠倚。\n赤龙、白鹞争系。\n风帆指顾便青齐，势雄万垒。\n越栖吴沼古难凭，兴亡都付流水。\n画堂绮屋锦绣市。\n是洛阳、耆旧州里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15400, '桂枝香', '吴潜', '三年海国。\n又荏苒素秋，天净如沐。\n凄砌寒蛩暗语，杵声相续。\n梧桐一叶西风里，对斜阳、好个团簇。\n老香堂畔，苍然古桧，无限心曲。\n叹石室、棋方半局。\n便时换人非，光景能蹙。\n千古鸱夷，尚恐欠些归宿。\n倚空笑把轮云事，付坤牛、乾马征逐。\n且巴重九，昭亭句溪，杖藜巾幅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15401, '南乡子', '吴潜', '野思浩难收。\n坐看鱼舟度远洲。\n芦苇已雕荷已败，风飕。\n桂子飘香八月头。\n归计这回酬。\n犹及家山一半秋。\n虽则家山元是客，浮休。\n有底欢娱有底愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15402, '南乡子', '吴潜', '野景有谁收。\n只在苍鸥白鹭洲。\n风树飘摇云树暗，衣飕。\n目断青天天际头。\n壮志世难酬。\n丹桂红蕖又晚秋。\n多少心情多少事，都休。\n载取江湖一片愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15403, '行香子', '吴潜', '世事尘轻。\n宠辱何惊。\n□不须、更问君平。\n一帆客棹，几曲渔汀。\n正年华晚，露华澹，月华明。\n休论烟阁，莫说云屏。\n算惟堪、瓜种东陵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15404, '秋夜雨', '吴潜', '腰棚傀儡曾悬索。\n粗瞒凭一层幕。\n施呈精妙处，解幻出、蛟龙头角。\n谁知鲍老从旁笑，更郭郎、摇手消薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15405, '糖多令・唐多令', '吴潜', '鸥鹭水中洲。\n夕阳天际流。\n倚西风、底处危楼。\n若使中秋无好月，虚过了、一年秋。\n举眼望云头。\n蟾光一线不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15406, '南乡子', '吴潜', '黄耳讯初收。\n为说鸥汀与鹭洲。\n争问主人归近远，飕飕。\n定是登高九月头。\n有酒且相酬。\n莫管西风满鬓秋。\n今日是今明日古，休休。\n转首鄞江总别愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15407, '诉衷情', '吴潜', '今宵分破鹘沦秋。\n孤客兴何悠。\n要向云中邀月，真个是呆头。\n风阵紧，电光流。\n雨声飕。\n嫦娥应道，未卜明年，是乐还愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15408, '水调歌头', '吴潜', '今岁月和桂，不肯作中秋。\n一年惟此佳节，底事白教休。\n我已侵寻七秩，况复轮万感，合恨更分愁。\n先自无聊赖，雨意得能稠。\n天柱峰，知何处，老难游。\n痴云如妒，不知弦管可吹不。\n安得风姨扫荡，推出团圆月姊，便遣桂香浮。\n世事十常九，不使展眉头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15409, '水调歌头', '吴潜', '已是三堪乐，更是百无忧。\n山朋溪友呼酒，互劝复争酬。\n钓水肥鲜鳊鳜，采树甘鲜梨栗，一齐收。\n树底飞轻盖，溪上放轻舟。\n笑鸱夷，名已谢，利还谋。\n蜗蝇些小头角，何事被渠钩。\n春际鹭翻蝶舞，秋际猿啼鹤唳，物我共悠悠。\n倚棹明当发，归梦落三洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15410, '水调歌头', '吴潜', '老子百般足，无事可闲忧。\n几年思返林壑，今日愿方酬。\n潦倒戏衫舞袖，郎讲门槌拍板，端的这回收。\n日月两浮毂，身世一虚舟。\n想鹪鹩，与鸿鹄，不相谋。\n惊鳞万里深逝，谁肯更吞钩。\n醉则北窗高卧，醒则南园行乐，莫莫更悠悠。\n云在山中谷，月在水中洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15411, '水调歌头', '吴潜', '若说故园景，何止可消忧。\n买邻谁欲来住，须把万金酬。\n屋外泓澄是水，水外阴森是竹，风月尽兜收。\n柳径荷漪畔，灯火系渔舟。\n且东皋，田二顷，稻粱谋。\n竹篱茅舍，窗户不用玉为钩。\n新擘黄鸡肉嫩，新斫紫螯膏美，一醉自悠悠。\n巴得春来到，芦笋长沙洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15412, '水调歌头', '吴潜', '且尽一杯酒，莫问百年忧。\n胸中多少磊块，老去已难酬。\n见说旄头星落，半夜天矫陨坠，玉垒阵云收。\n世运回如此，稳泛辋川舟。\n鸥鹭侣，猿鹤伴，为吾谋。\n主人归也，正是重九月如钩。\n便把三程为两，更趱两程为一，尚恐是悠悠。\n旁有渔翁道，肯负白苹洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15413, '水调歌头', '吴潜', '处处羊肠路，归路是安便。\n从头点检身世，今日岂非天。\n未论分封邦国，未论分符乡国，晚节且圆全。\n但觉君恩重，老泪忽潸然。\n谢东山，裴绿野，李平泉。\n从今许我，攀附诸老与齐肩。\n更得十年安乐，便了百年光景，不是谩归田。\n谨勿伤离别，聊共醉觥船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15414, '浣溪沙', '吴潜', '半饷西风暖换凉。\n岩花月魄衬云裳。\n一杯旋擘翠橙香。\n旧酝不妨排日醉，新尚可去时尝。\n无何乡里是吾乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15415, '谒金门', '吴潜', '秋已老。\n又是败荷衰草。\n客子安排归棹了。\n回头烟树渺。\n檀板休教歌杳。\n金兽且教香绕。\n一醉秋堂秋夜悄。\n从他霜漏晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15416, '谒金门', '吴潜', '汤怕老。\n缓煮龙芽凤草。\n七碗徐徐撑腹了。\n庐家诗兴渺。\n君岂荆溪路杳。\n我已泾川梦绕。\n酒兴茶酣人语悄。\n莫教鸡聒晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15417, '谒金门', '吴潜', '休怨老。\n更替北邙荒草。\n勘破人生都已了。\n江湖归兴渺。\n盘谷深深杳杳。\n曲水弯弯绕绕。\n啼鸟空山山更悄。\n钟昏钟又晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15418, '水调歌头', '吴潜', '倚舵秋江浒，明日片帆轻。\n从头点检身世，百事已圆成。\n及第曾攀龙首，仕宦曾居鸱阁，衣锦更光荣。\n若又不知止，天道恐亏盈。\n借称呼，遮俗眼，便归耕。\n但馀心愿，朝暮香火告神明。\n一愿君王万寿，次愿干戈永息，三愿岁丰登。\n四愿老安乐，疾病免相荣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15419, '水调歌头', '吴潜', '便作阳关别，烟雨暗孤汀。\n浮屠三宿桑下，犹自不忘情。\n何况情锺我辈，聚散葱葱草草，真个是云萍。\n上下四方客，後会渺难凭。\n愿诸公，皆衮衮，喜通津。\n老夫从此归隐，耕钓了馀生。\n若见江南苍，更遇江东黄耳，莫惜寄音声。\n强阁儿女泪，有酒且频倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15420, '贺新郎', '吴潜', '晚打西江渡。\n便抬头、严城鼓角，乱烟深处。\n无限珠玑双手接，颇觉奚囊暴富。\n强载月、空舟回去。\n劝子不须忧百草，四周维、自著灵鳌柱。\n互今古，只如许。\n杭州直北还乡路。\n想山中、猿呼鹿啸，鹭翔鸥舞。\n尽道翁归真个也，只怕颜容非故。\n愿从此、耕云钓雨。\n盘谷幽深空谷杳，但书来、时寄相思句。\n千里外，镇延伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15421, '风流子', '方君遇', '春被雨禁持。\n伤心事、仿佛去年时。\n记芳径暮归，褪妆微醉，暗帏先寝，闻笑佯痴。\n回首别离容易过，杨柳又依依。\n红烛怨歌，鬓花零落，青绫牵梦，屏影参差。\n桃源今何在，刘郎去，应念瘦损香肌。\n误约夜阑，从前怪我都疑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15422, '贺新郎', '平江妓', '春色元无主。\n荷东君、著意看承，等闲分付。\n多少无情风与浪，又那更、蜂欺蝶妒。\n算燕雀、眼前无数。\n纵使帘栊能爱护，到如今、已是成迟暮。\n芳草碧，遮归路。\n看看做到难言处。\n怕宣郎、旌旗轻转，易歌襦裤。\n月满西楼弦索静，云蔽城阆府。\n便恁地、一帆轻举。\n独倚阑干愁拍碎，惨玉容、泪眼如红雨。\n去与住，两难诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15423, '满江红', '陈垲', '万里长江，天与限、东南吴楚。\n何人者，提英□□，指鞭欲渡。\n孟德舳舻烟赤壁，佛狸心胆寒瓜步。\n问波涛、说尽几英雄，今犹古。\n中原地，纷（下缺）。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15424, '减字木兰花', '淮上女', '淮山隐隐。\n千里云峰千里恨。\n淮水悠悠。\n万顷烟波万顷愁。\n山长水远。\n遮住行人东望眼。\n恨旧愁新。\n有泪无言对晚春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15425, '行香子', '黄孝迈', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15426, '水龙吟', '黄孝迈', '自侧金卮，临风一笑，酒容吹尽。\n恨东风、忙去熏桃染柳，不念淡妆人冷。\n惊鸿去後，轻抛素袜，杳无音信。\n细看来，只怕蕊仙不肯，让梅花俊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15427, '湘春夜月', '黄孝迈', '近清明。\n翠禽枝上消魂。\n可惜一片清歌，都付与黄昏。\n欲共柳花低诉，怕柳花轻薄，不解伤春。\n念楚乡旅宿，柔情别绪，谁与温存。\n空樽夜泣，青山不语，残月当门。\n翠玉楼前，惟是有、一波湘水，摇荡湘云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15428, '水龙吟', '黄孝迈', '闲情小院沈吟，草深柳密帘空翠。\n风檐夜响，残灯慵剔，寒轻怯睡。\n店舍无烟，关山有月，梨花满地。\n二十年好梦，不曾圆合，而今老、都休矣。\n谁共题诗秉烛，两厌厌、天涯别袂。\n柔肠一寸，七分是恨，三分是泪。\n芳信不来，玉箫尘染，粉衣香退。\n待问春，怎把千红换得，一池绿水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15429, '水调歌头', '吴千能', '澹氏人安在，缥缈九霄间。\n我来唯有石屋，周览百寻宽。\n一曲中分夷险，两牖空光平布，满洞贮清寒。\n高歌自堪仰，何必论金丹。\n周贤士，知此意，薄秦官。\n一床一枕，依然犹伴白云间。\n门外俗尘如海，门里道心如水，谈笑足回澜。\n此事无今古，不信叩嵛山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15430, '望海潮', '史隽之', '危岑孤秀，飞轩爽豁，空江泱漭黄流。\n吴札故邱，春申旧国，西风吹换清秋。\n沧海浪初收。\n共登高临眺，尊俎绸缪。\n凤集高罔，驹留空谷接英游。\n八窗尽控琼钩。\n送帆樯杳杳，潮汐悠悠。\n千古兴怀，关河极目，愁边灭没轻鸥。\n淮岸隔重洲。\n认澹霞天末，一缕青浮。\n未许英雄老去，西北是神州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15431, '水调歌・水调', '张友仁', '石屋势平旷，峭壁几岩。\n妙哉天造地设，谁复谓神剜。\n畴昔涪翁题品，曾说人寰稀有，岂特冠湘南。\n趁取脚轻健，相与上高寒。\n避秦者，君莫问，意其间。\n祖龙文密，至今草木尚愁颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15432, '酹江月・念奴娇', '王柏', '今岁腊前，苦无多寒色、梅花先白。\n可惜横斜清浅处，谁妨孤山仙客。\n玉勒寻芳，金尊护冷，定与心期隔。\n夜阑人悄，可无一段春月。\n怕它香已飘零，罗浮梦断，不与东君接。\n买得鹅湖千幅绢，留取天然标格。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15433, '贺新郎', '刘震孙', '怕绿野堂边，刘郎去後，谁伴老裴度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15434, '点绛唇', '周晋', '午梦初回，卷帘尽放春愁去。\n昼长无侣。\n自对黄鹂语。\n絮影苹香，春在无人处。\n移舟去。\n未成新句。\n一砚梨花雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15435, '清平乐', '周晋', '图书一室。\n香暖垂帘密。\n花满翠壶熏研席。\n睡觉满窗晴日。\n手寒不了残棋。\n篝香细勘唐碑。\n无酒无诗情绪，欲梅欲雪天时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15436, '柳梢青', '周晋', '似雾中花，似风前雪，似雨馀云。\n本自无情，点萍成绿，却又多情。\n西湖南陌东城。\n甚管定、年年送春。\n薄东风，薄情游子，薄命佳人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15437, '菩萨蛮', '曾原一', '淡黄斜日留汀草。\n檐低半露遥岑小。\n病眼不禁愁。\n阑干无数秋。\n雁声何处落。\n旧梦还惊觉。\n风重葛衣单。\n深山吹笛寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15438, '小重山', '曾原一', '薄雪初消银月单。\n疏疏浮竹影、矮红阑。\n梅花梦事落孤山。\n禁人处，霜重鼓声寒。\n留取晓来看。\n斑帘低小阁、烛花残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15439, '谒金门', '曾原一', '梅粉褪。\n点点雨声春恨。\n半吐桃花芳意嫩。\n草痕青寸寸。\n把酒花边低问。\n莫解寒深红损。\n等待春风晴得稳。\n琵琶重整顿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15440, '临江仙', '赵希囿', '天宇寥山气肃，云寒树立无声。\n读书岩下石纵横。\n红尘飞不到，溪水自澄清。\n疏影暗香沙路古，何妨曳杖闲行。\n巢林冻雀不曾惊。\n晚钟穿翠霭，来共话平生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15441, '水调歌头', '江万里', '生日重重见，馀闰有新春。\n为吾母寿，富贵外物总休论。\n且说家怀旧话，教学也曾菽水，亲意尽欣欣。\n只此是真乐，乐岂在邦君。\n吾二老，常说与，要廉勤。\n庐陵几千万户，休戚属儿身。\n三瑞堂中绿醑，酿就满城和气，端又属人伦。\n吾亦老吾老，谁不敬其亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15442, '西江月', '萧廷之', '两手劈开混沌，坦然直露丹宗。\n日魂月魄自西东。\n牢捉莫轻放纵。\n外道邪魔缩项，相将结宝中宫。\n九还七返片时功。\n皆赖黄婆相送。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15443, '西江月', '萧廷之', '默运乾坤否泰，抽添妙在屯蒙。\n起於复卦剥于终。\n温养两般作用。\n沐浴要防危险，吹嘘全藉离风。\n工夫还返入坤宫。\n火足不宜轻弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15444, '西江月', '萧廷之', '要识真铅真汞，都来只一根源。\n烹煎火候妙中玄。\n不是知音难辨。\n采取莫差时日，仍分弦後弦前。\n玉炉一霎火烧天。\n无位真人出现。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15445, '西江月', '萧廷之', '莫问九三二八，无过阴偶阳奇。\n大都离坎结夫妻。\n要识屯蒙既未。\n若遇一阳起复，便堪进火无迟。\n只应差失在毫厘。\n野战更宜仔细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15446, '西江月', '萧廷之', '鼎器法天象地，坎离运用无差。\n夫妻相会入黄家。\n共说无生妙话。\n雨意云情了当，领头驾动河车。\n搬归顶上结三花。\n牢闭玉关金锁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15447, '西江月', '萧廷之', '拨动顶门关捩，自然虎啸龙吟。\n九还七返义幽深。\n出入不离玄牝。\n运用玉炉火候，鼎中练就真金。\n强兵战胜便收心。\n妙在无伤无损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15448, '西江月', '萧廷之', '一二复临养火，兔鸡沐浴潜藏。\n分明变化在中央。\n结就玄珠片饷。\n还返归根托体，守城抱一提防。\n黄庭来往是寻常。\n恍惚之中纵放。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15449, '西江月', '萧廷之', '夹脊双关透顶，此为大道玄门。\n金丹只是此宗根。\n大要知时搬运。\n温养守城野战，华池玉液频吞。\n玉炉常使火温温。\n采药审他老嫩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15450, '西江月', '萧廷之', '调燮火工非小，差殊只在毫厘。\n鼎炉汞走黑铅飞。\n从此恐君丧志。\n须共真师细论，无令妄动轻为。\n幽微玄妙最深机。\n言语仍须避忌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15451, '西江月', '萧廷之', '九曲江头逆浪，霎时冲过天心。\n顶上水澄澄。\n酝就琼浆自饮。\n便向此时采取，河车搬运无停。\n阴阳一气自浮沈。\n锁闭玉关牢稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15452, '西江月', '萧廷之', '药产西南坤地，金丹只此根宗。\n学人著意细推穷。\n妙绝无过真种。\n了一万般皆毕，休分南北西东。\n执文泥象岂能通。\n恰似哑人谈梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15453, '西江月', '萧廷之', '金液还丹大道，古人万劫一传。\n倾心剖腹露诸篇。\n接引直超道岸。\n莫怪天机泄尽，此玄玄外无玄。\n留传後代与名贤。\n有目分明觑见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15454, '南乡子', '萧廷之', '真汞与真铅。\n产在先天与後天。\n大开知时勤采取，玄玄。\n得穴何愁不作仙。\n进火要精专。\n审究前弦与後弦。\n屯卦抽添蒙卦止，难传。\n毫发差殊不结丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15455, '南乡子', '萧廷之', '两手擘鸿。\n慧剑飞来第一峰。\n外道修罗惊缩项，神通。\n造化元来在掌中。\n锻炼玉炉红。\n橐龠吹嘘藉巽风。\n十月托胎吞入腹，坤宫。\n立见三清太上翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15456, '南乡子', '萧廷之', '温养象周天。\n须要微微火力全。\n爱护婴儿惟藉母，三年。\n运用抽添象缺圆。\n牛斗会河边。\n拾取玄珠种玉田。\n定意如如行火候，精专。\n剖腹分明说与贤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15457, '南乡子', '萧廷之', '生甲更生庚。\n此是丹头切要明。\n药嫩采来归土釜，煎烹。\n文武刚柔次第行。\n片饷结丹成。\n沐浴防危更守城。\n到此不须行火候，持盈。\n火若加临必定倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15458, '南乡子', '萧廷之', '木兔与金鸡。\n刑德临门有偶奇。\n炉内丹砂宜沐浴，防危。\n神水溶溶满玉池。\n年月日并时。\n刻里工夫一例推。\n著意研穷丹造次，毫厘。\n十月殷勤自保持。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15459, '南乡子', '萧廷之', '鼎器法乾坤。\n上是天元下地元。\n若也更能颠倒运，交番。\n阖劈循环在八门。\n搬运上。\n龟与蛇儿自吐吞。\n百尺竿头牢把线，掀援。\n从此元神命永存。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15460, '南乡子', '萧廷之', '关锁自周天。\n升降循环三寸田。\n不在嘘呵并数息，天然。\n九转无亏火力全。\n胎息漫流传。\n要在阴阳不可偏。\n呼吸吹嘘皆赖巽，绵绵。\n妙在前弦与後弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15461, '南乡子', '萧廷之', '复卦起潜龙。\n戊己微调未可攻。\n九二见龙临卦主，神通。\n从此炉中次第红。\n泰卦恰相逢。\n猛火烧乾藉巽风。\n炼就黄芽并白雪，奇功。\n还返归坤道始穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15462, '南乡子', '萧廷之', '识得水中金。\n煅炼烹煎理更深。\n进退抽添须九转，浮沈。\n温养潜龙复与临。\n妙运自天心。\n托仗黄婆配丙壬。\n酝就醍醐山顶降，频斟。\n慢拨无弦一曲琴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15463, '南乡子', '萧廷之', '长子到西方。\n少女归乾变六阳。\n便好下功修二八，提防。\n至九方知道自昌。\n牛斗共商量。\n巧夺天功妙莫量。\n离坎夫妻交媾後，难忘。\n始觉壶中日月长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15464, '南乡子', '萧廷之', '白雪与黄芽。\n两味精华共一家。\n采择辨时衰与旺，堪夸。\n火候毫厘不可差。\n顶上结三花。\n驾动羊车与鹿车。\n乌兔往来南北面，交加。\n从此天河稳泛槎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15465, '南乡子', '萧廷之', '尽净露天机。\n只恐时人自执迷。\n颔下藏珠当猛取，休迟。\n道在身中更问谁。\n尘纲忽抛离。\n百岁年华七十稀。\n莫待老来铅汞少，堪悲。\n业报前途难自欺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15466, '百岁令', '朱涣', '瑞芳楼下，有花中君子，群然相聚。\n笑把筒が露，来庆黄堂初度。\n净植无尘，清香近远，人与花名伍。\n六郎那得，这般潇洒襟宇。\n运了多少兵筹，依红泛绿，向俭池容与。\n歌裤方腾持节去，未许制衣湘楚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15467, '二郎神', '周弼', '浪花皱石，毡叶月、欲移还定。\n想白伫烘晴，黄蕉摊雨，人整斜巾照领。\n翦断鲛绡何人续，黯梦想、秋江风冷。\n空露渍藻铺，云根苔，指痕环影。\n重省。\n五湖万里，谁问烟艇。\n料宝像尘侵，玉瓢珠锁，羞对菱花故镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15468, '浣溪沙', '周弼', '朴朴精神的的香。\n荼縻一朵晓来妆。\n雏莺叶底学宫商。\n著意劝人须尽醉，扶头中酒又何妨。\n绿窗花影日偏长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15469, '浣溪沙', '黄时龙', '雨歇花梢月正明。\n映帘人静绣灯昏。\n鸳鸯成字便停针。\n笑启玉奁明酒晕，缓寻金叶熨香心。\n一春情绪此时深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15470, '夜行船', '黄时龙', '十四弦声犹未断。\n星月上、西墙一半。\n却手休弹，含情微妒，报道春宵短。\n银烛纱笼须早办。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15471, '虞美人', '黄时龙', '卷帘人出身如燕。\n烛底粉妆明艳。\n羯鼓初催按六么。\n无限春娇都上、舞裙腰。\n画堂深窈亲曾见。\n宛转楚波如怨。\n小立花心曲未终。\n一把柳丝无力、倚东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15472, '玉楼春', '陈云', '琼奴家与章台并。\n路远可怜归梦近。\n波头浪语脸红潮，镜面频思眉翠晕。\n年年花月年年病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15473, '谒金门', '陈云', '春昼永。\n接叶鸣禽相应。\n风定落红香一径。\n疏疏窗竹影。\n寂寞年时酒病。\n远笛悠悠吹醒。\n闲上层楼天又暝。\n云山青不尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15474, '谒金门', '陈东甫', '西风竹。\n风入翠烟□矗。\n红小阑干知几曲。\n声声敲碧玉。\n窗下凤台银烛。\n断梦已惊难续。\n曾伴去年庭下菊。\n夜阑听雨宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15475, '长相思', '陈东甫', '花深深。\n柳阴阴。\n度柳穿花觅信音。\n君心负妾心。\n怨鸣琴。\n恨孤衾。\n钿誓钗盟何处寻。\n当初谁料今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15476, '望江南・忆江南', '陈东甫', '芳思远，南苑惜春时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15477, '瑞鹤仙', '黄中', '睡馀抛倦枕。\n忆篆鼎香销，起来慵整。\n晴光破清冷。\n正柳黄梅淡，染金匀粉。\n茶瓯隽永。\n试经行、桐花旧井。\n记前回、未绿鸥波，近日燕芹青尽。\n因省。\n春风如旧，人面何归，对时伤景。\n楼高望回。\n潮有信，雁无准。\n任相如多病，沈郎全瘦，都没音尘寄问。\n便做无、阿鹊频频，可能睡稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15478, '水龙吟', '李曾伯', '西风吹上牛头，天涯慰此人情耳。\n斜阳任晚，青山全似，故人知己。\n迤逦归来，须臾懒去，桂华犹未。\n待冰轮推上，梧桐树了，更儿是、点儿几。\n满眼碧天如洗。\n便分明、水晶宫里。\n区区玩事，一觞一咏，一灯而已。\n欲待无眠，争如且恁，有无穷意。\n怕嫦娥，隔窗偷看，须下却、帐儿睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15479, '水龙吟', '李曾伯', '几年野渡孤舟，萧然袖此经纶手。\n归来廊庙，从容进退，祖风犹有。\n小队环花，轻艘漕玉，暂临金斗。\n把持书帷幄，期年坐啸，尘不动、依依柳。\n好是公堂称寿。\n正元戎、阃垣开後。\n旌旗才举，胡雏马上，闻风西走。\n一点阳春，无边德泽，淮山长久。\n待官军，定了长安，貂蝉侍、未央酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15480, '水龙吟', '李曾伯', '明堂一柱擎天，眼看黄阁空诸老。\n平生方寸、班班四字，诚心公道。\n玉帐云旗，金城露布，尚勤征讨。\n向淮头蜀口，一时做就，安石传、孔明表。\n谈笑妖氛如扫。\n看整齐、乾坤都了。\n衮衣赤，归来廊庙，雍容师保。\n三相一门，双亲千岁，人间蓬岛。\n举黄封，细唱调羹，官梅上、正春早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15481, '水龙吟', '李曾伯', '东南一气当春，便从黄钺登台斗。\n紫皇举此，亨屯济泰，属之公手。\n淮浦烽销，未央觞献，捷传清昼。\n庆太平朝野，重见，昔淳化、今嘉。\n史观年编新就。\n看勋庸、光前垂後。\n三槐鼎盛，双椿盘固，古今希有。\n宴侍龙颜，欢承鹤发，相期长久。\n问前朝，相业谁同，八九十、迈文富。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15482, '水龙吟', '李曾伯', '岷峨寿佛东来，手移斗柄春寰宇。\n经纶事业，诗书流出，时为膏雨。\n载采三阶，炳丹一念，雍容枢辅。\n望岩廊风范，扬休山立，真汉相、殆天与。\n国步时当如许。\n赖明堂、倚空一柱。\n苍生引领，整齐中夏，奠安西土。\n多士相期，直须无愧，范韩文富。\n且梅边一笑，春风祝公，寿介东鲁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15483, '水龙吟', '李曾伯', '举杯长揖常娥，高情怜我霜髯白。\n婆娑树底，老蟾何物，千秋一色。\n一镜高悬，肺肝洞烛，了无尘隔。\n任亿千万里，同然玉界，都不管、天南北。\n老子萍蓬纵迹。\n对西风、几番行役。\n平生玩事，从头细数，山川历历。\n明月明年，知他何处，能如今夕。\n惜无人共我，登楼酹古，一笑横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15484, '水龙吟', '李曾伯', '少年管领良宵，直须醉待东方白。\n而今老去，何忧何乐，不空不色。\n桐影横斜，桂香摇落，仙凡奚隔。\n怅银桥梦断，玉啸声杳，人如往、楚天北。\n冷眼乾坤阵迹。\n笑英雄、等为行役。\n庾楼袁舫，浩歌长啸，壮游曾历。\n万里瑶台，乘风归去，不知何夕。\n对冰轮孤负，欠千锺酒，与三弄笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15485, '水龙吟', '李曾伯', '归来袖手江湖，不妨左右持螯白。\n凉宵幸对，一轮端正，娟娟秋色。\n万宇冰清，千林霜缟，更无云隔。\n对金茎露冷，铜壶漏静，梧阴转、画桥北。\n堪叹平生辙迹。\n算纷纷、为谁驱役。\n兔蟾应笑，蝇蜗累我，中年虚历。\n抖擞吟情，徘徊舞影，可怜佳夕。\n怅力微心在，梦中一曲，似黄楼笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15486, '水龙吟', '李曾伯', '归来三见梅花，年年借此花为寿。\n八窗轩槛，月边竹畔，数枝开又。\n姑射肌肤，广平风度，对人依旧。\n把离骚读遍，椒兰荃蕙，奚敢及、众芳首。\n幸与岁寒为友。\n任天公、雪霜。\n香名一点，西湖东阁，逊浦曾有。\n金鼎家毡，玉堂椽笔，傥来斯受。\n且巡檐、管领先春，林外事、付卮酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15487, '水龙吟', '李曾伯', '几番南极星边，樽前常借南枝寿。\n今年好处，冰清汉节，与梅为友。\n老桧苍榕，婆娑环拱，影横香瘦。\n把草庭生意，蛮烟尽洗，都付与、风霜手。\n岭首小春时候。\n看明宵、桂轮圆又。\n此人此地，此花此月，宜诗宜酒。\n把绣归来，调羹金鼎，西湖春後。\n愿玉奴、岁与素娥不老，共人长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15488, '水龙吟', '李曾伯', '小窗香雾笼葱，砚寒金井频呵冻。\n老坡仙去，新声犹寄，绿毛么凤。\n瘦脸盈盈，不禁，雪浓霜重。\n赖墨池佳致，草成玄白，聊以此、当清供。\n长记月明曾共。\n拈虬髯、几番孤耸。\n春风一点，著公翠袖，撩人清梦。\n逋尔何如，西湖惯见，影斜芗动。\n要岁寒得友，岂容无竹，倩谁添种。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15489, '水龙吟', '李曾伯', '元英燕罢瑶台，玉妃满地花钿委。\n山川幻出，剡溪梁苑，齐宫郢里。\n半点瑕无，一团和就，珠圆琼碎。\n任谢家儿女，庭前争诧，临空撤、絮风起。\n夜入蔡州城里。\n问官军、果谁堪比。\n饮羔烹凤，众宾一笑，直聊尔耳。\n寒耸玉楼，冻呵金井，属公诗史。\n更须待大白，浩歌黄竹，为丰年喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15490, '水龙吟', '李曾伯', '玉龙飞下残鳞，千岩万壑皆填委。\n乾坤一色，不知身隔，蓬莱几里。\n疑是瑶英，盛开元圃，被风敲碎。\n倚危楼极目，长江渺处，浑错认、沙鸥起。\n依约青帘遥指。\n记山家、酒香无比。\n访梅江路，何时归唤，小苍长耳。\n孙案袁门，不妨高卧，足娱书史。\n且摩挲霜鬓，嘲吟冰著，共荆人喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15491, '水龙吟', '李曾伯', '琅琅环佩三千，一楼玉立中端委。\n瑶琚碾就，襄王故国，屈平遗里。\n多少铅华，飞琼涂抹，一时碎。\n记少年驰逐，银杯缟带，几番被、鸡呼起。\n冷入重貂如水。\n鬓丝丝、叹非前比。\n羔儿满泛，狮儿低唱，飘风过耳。\n冰释边忧，春生民乐，欢形佐史。\n倩何人蜚奏，五云天上，助吾君喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15492, '醉蓬莱', '李曾伯', '倚栏干一笑，旧日琵琶，何处寻觅。\n独立东风，吹未醒狂客。\n沙外青归，柳边黄浅，依旧自春色。\n极目长淮，晴烟一抹，不堪重忆。\n老子平生，萍流蓬转，昔去今来，鸥鹭都识。\n拍拍轻舟，烟浪暗天北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15493, '醉蓬莱', '李曾伯', '是人生好处，仕宦归来，享清闲福。\n屈指吾翁，恰八年荆蜀。\n星火丛中，风涛局上，转青天刍粟。\n轺传欣还，里闾相庆，双鬓犹绿。\n为报中朝，如今老子，肯把貂蝉，换取松菊。\n西舍东邻，正新初熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15494, '醉蓬莱', '李曾伯', '把东南温厚，天遣西来，试薰风手。\n一佛人间，与峨眉长久。\n玉帐旌旗，金城鼓吹，笑乌奴歌酒。\n狐兔烟清，貔貅月淡，凯音新奏。\n元明时，中朝司马，记得边人，岁问安否。\n勋业如今，□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15495, '醉蓬莱', '李曾伯', '有擎天一柱，殿角西头，手扶宗。\n万里鱼凫，倚金城山立。\n亭障惊沙，毡裘卷地，倏度黄龙碛。\n玉帐从容，招摇才指，顿清边色。\n见说中天，翠华南渡，一捷金平，胆寒西贼。\n帝锡公侯，更高逾前绩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15496, '醉蓬莱', '李曾伯', '记石湖佳句，为海棠花，合来西蜀。\n不道东州，更香霏情淑。\n汉竹光中，召棠阴里，想清欢未足。\n少驻旌麾，姑留樽俎，待春风曲。\n见说吾家，丹溪老子，万籍名堂，孙枝犹馥。\n南极星边，正魁星明烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15497, '醉蓬莱', '李曾伯', '问江东父老，十数年来，谁为安石。\n万里鲸波，一柱独山立。\n汉橐班高，郢斤名重，喜动旌旗色。\n虎踞龙盘，有人於此，千载犹昔。\n好是元戎，护寒旧手，到处人传，争道公别。\n办取风樯，指顾定南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15498, '醉蓬莱', '李曾伯', '自陇头垂谱，调鼎传家，典刑犹有。\n岁岁芳期，报小春时候。\n仙骨非凡，生香不断，标格蕙兰右。\n江路孤山，水边雪际，为渠诗瘦。\n白玉堂前，青毡席上，孰谓无人，有如此酒。\n得意春风，且占万花首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15499, '醉蓬莱', '李曾伯', '正阳生一脉，绣日添长，台云书瑞。\n劲节昂霄，仁意雪霜里。\n粟庾红陈，草扉绿茂，襦裤蔼千里。\n马熟车轻，铃斋曾到，从容游戏。\n好是邦人，能言世美，犹爱其棠，而况其子。\n洞里桃花，岁月任渠记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15500, '六州歌头', '李曾伯', '桂香深处，倾盖岭之西。\n云南外，曾指点，是挛。\n酌玻璃。\n带江山里，挥银笔，绮句，湖海气，羞篷弱，吐虹霓。\n回首烟尘碌碌，公家事、自笑痴儿。\n盍田园归去，耕钓侣黔黎。\n月夕花时。\n恣吟题。\n怅荆州路，同北望，剡溪兴，又东驰。\n雄边上，夸前躅，壮新基。\n灿宸奎。\n客问西陲事，公莫惜，语教知。\n秋城梦，笳却骑，舞闻鸡。\n休作中年离恨，聊拼取、一醉如泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15501, '摸鱼儿', '李曾伯', '对楼头、欠招欢伯，和风吹老芳讯。\n凭阑面面蒲萄绿，依约碧岑才寸。\n无尽兴。\n纵燃竹烹泉，亦自清肠吻。\n凭谁与问。\n旧城郭何如，英雄安在，何说解孤愤。\n铜路，极目长安甚近。\n当时宾主相信。\n翩翩公子登高赋，局面还思著紧。\n乘暇整。\n谩课柳评花，援镜搔蓬鬓。\n江平浪稳。\n怅我有兰舟，何人共楫，毋作孔明恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15502, '八声甘州', '李曾伯', '拟龙山、把酒酹西风，西风苦无情。\n似秋容不受，骚人登眺，特地悭晴。\n依稀两三过雁，何处是方城。\n目断危楼外，山远烟轻。\n且对黄花一笑，叹浮生易老，乐事难并。\n唤遏云低唱，檐溜任霏铃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15503, '八声甘州', '李曾伯', '有庞眉、扶杖岘山来，举觞寿南山。\n道天怜赤子，相逢钧播，久望毡还。\n幸际君王神武，上宰是甘盘。\n少运风霆手，整顿何难。\n好个霜天时候，听雁门新雁，眺远凭阑。\n想经纶心上，一点炳如丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15504, '沁园春', '李曾伯', '形胜风流，乐事良辰，一时四并。\n正榆更新火，觞浮曲水，那堪上巳，又是清明。\n赤壁功名，东坡文字，俯仰人间无古今。\n诗书帅，对烽烟静昼，俎豆添春。\n水边天气催人。\n便须认杨花雪样生。\n慨英风满席，思旌绵上，清谈束阁，肯记兰亭。\n安得长绳，高悬碧落，系住画檐红日阴。\n柔桑外，听鸣鸠唤雨，全胜流莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15505, '沁园春', '李曾伯', '鸿禧主人，一闲半年，未尝厌闲。\n谓有溪可钓，有田可秣，有兰堪佩，有菊堪餐。\n羽檄秋风，胡笳夜月，多少勋名留汉关。\n如今且，效樽北海，歌舞东山。\n门前。\n咫尺长安。\n但只恐纶音催禁班。\n把鹭鬓数茎，更因民白，鸥心一片，犹为君丹。\n蓝绶儿痴，彩衣家庆，倦羽伶俜江汉还。\n春光小，看庭苇岁岁，一笑梅间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15506, '沁园春', '李曾伯', '轩冕傥来，功名杯水，行藏依楼。\n把方略评梅，工夫课柳，精神伴鹤，谈笑盟鸥。\n草檄寻樵，移文问钓，任江上东南风未休。\n君知否，问如今绿野，胜似青油。\n从伊万户封留。\n算得似团栾歌笑不。\n怕魏阙兴思，高车驷马，江湖难著，缓带轻裘。\n雪意何如，新醪熟未，乐事良辰聊献酬。\n从今去，更八千椿算，才一春秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15507, '沁园春', '李曾伯', '今代清流，北斗以南，文昌一星。\n对露门进读，銮坡演翰，琐闱批敕，宝牒成文。\n笔下权衡，胸中律度，礼乐人才俱讨论。\n鸳行里，羡才高片玉，辉映条冰。\n几年简在吾君。\n便须把诗书开太平。\n笑诸公炙手，昔成何事，一贤冷眼，今独修名。\n花底退朝，槐边听制，一武商岩霖雨新。\n金举，对春风九十，岁岁平分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15508, '沁园春', '李曾伯', '天下中庸，千载一灯，传之自公。\n有涵洪雅量，陂澄千顷，坚凝定力，壁立孤峰。\n佐鼎调梅，参帷借箸，略试斯文经济功。\n听淮鹤，暂素丝揽辔，玉帐分弓。\n朝来鼓角声雄。\n庆元帅新除初度逢。\n任西风局面，人皆洞，福星堂上，我独从容。\n草檄传燕，开门释蔡，了却中原公衮东。\n归廊庙，把格天勋业，与宋无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15509, '沁园春', '李曾伯', '画舸呼风，长剑倚天，壮哉此行。\n指洞庭彭蠡，遍观吴楚，瞿塘滟，直上峨岷。\n帝语春温，军声秋肃，手济时屯开泰平。\n天应是，念蚕丛父老，公为更生。\n眼看四海无人。\n今天下英雄惟使君。\n想驰情忠武，将兴王业，抚膺司马，忍咎吾民。\n净洗甲兵，归来鼎辅，定使八荒同一云。\n经营事，比京河形势，更近函秦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15510, '沁园春', '李曾伯', '漫浪江头，三听秋砧，一登故台。\n望烟芜莽苍，令人目断，风樯掀舞，何日眉开。\n把酒新亭，围棋别墅，老气当时何壮哉。\n江东事，百年无恙，全是时才。\n纷然竞付轻埃。\n还水绕赏心东向淮。\n叹阿奴侪悲，因人碌碌，乃翁材略，馀地恢恢。\n凤阙天高，鹭洲潮落，约取白鸥归去来。\n阑干外，英雄陈迹，一琼杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15511, '沁园春', '李曾伯', '绮阁香销，玉砌梦残，凄凉旧台。\n对御沟红叶，一番木落，宫墙黄菊，几度花开。\n水溯岷源，山联吴会，目送征鸿安往哉。\n都休问，六朝人物，谁拙谁才。\n平生衮衮烟尘。\n记匹马当年荆蜀淮。\n叹雕零殆尽，词源已竭，消磨未去，酒量犹恢。\n八跪蟹肥，四腮鲈美，客有可人招不来。\n油幢暇，凭栏一笑，相与传杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15512, '沁园春', '李曾伯', '目断长空，手拍危栏，高兴酒浓。\n拟招呼短艇，追陪飞盖，一餐湘菊，共赋芙蓉。\n雁字沈秋，鸦林噪晚，几阵萧萧雨更风。\n空凝伫，不如一鹤，随意西东。\n堪嗟乐事难逢。\n愧元伯、巨卿千里从。\n望文星聚彩，交辉吴分，天飙吹翅，独隔蓬。\n野墅荒烟，败荷衰草，人在可怜憔悴中。\n还相念，愿持觥薄罚，别许从容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15513, '沁园春', '李曾伯', '雨抹晴妆，修眉镜清，寸碧翠浓。\n对蒹葭尽处，丛丛烟树，池塘侧畔，面面芙蓉。\n千百栖乌，两三过雁，时有婆娑一笛风。\n斜阳里，更青帘半卷，在小桥东。\n佳人何日重逢。\n问还肯扁舟载酒从。\n笑平生劲概，寸心如铁，中年老态，两鬓成蓬。\n荷锸栽蔬，腰镰刈稻，且寄西郊图画中。\n空回首，望五湖鸥鹭，心事容容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15514, '沁园春', '李曾伯', '秋岂悲人，人不悲秋，比春更浓。\n有蕙兰风度，尚存芳菊，牡丹之献，犹在芙蓉。\n举蟹持醪，得鲈作，晋宋间人有此风。\n休轻笑，彼柴桑傲吏，龌龊篱东。\n携壶与客还逢。\n愿时许先生杖履从。\n叹尘踪如寄，鸥凫江海，性真聊适，蜩蒿蓬。\n刮眼青天，惊心黄叶，立尽梧桐月正中。\n凄然久，看物情终竟，不似春容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15515, '沁园春', '李曾伯', '大江之西，康庐之阴，壮哉此州。\n有舳橹千里，旌旗百万，襟喉上国，屏翰中流。\n弹压鲸波，指麾虎渡，著此商川万斛舟。\n青毡旧，看崇诗说礼，缓带轻裘。\n十年泉石优游。\n久高卧元龙百尺楼。\n正九重侧席，相期岩弼，一贤砥柱，聊试边筹。\n了却分弓，归来调鼎，得见茂洪何复忧。\n谈兵暇，问琵琶歌曲，无恙还不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15516, '沁园春', '李曾伯', '北固台端，南渡後来，无此伟人。\n自从容佐鼎，光华揽辔，几年中外，属目经纶。\n万灶炊烟，千艘漕雪，手整江淮如掌平。\n诗书效，看马腾士饱，酒好兵精。\n平生。\n馀事功名。\n岂管葛诸人能拟伦。\n暂牙筹游戏，小淹惟月，金瓯注想，便合为霖。\n沆瀣一襟，风流八咏，秋入诗坛如许清。\n为公寿，有黄花不老，长伴香名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15517, '沁园春', '李曾伯', '揽秀岷峨，著鞭江淮，诸公所奇。\n对塞垣烟淡，相随弓剑，城楼月落，几共灯棋。\n驿柳摇黄，溪桃涨绿，稳趁春风度玉墀。\n亨衢去，看紫薇红药，太乙青藜。\n孤山若放梅时。\n莫忘却扬州曾有诗。\n怅英游难驻，堪怜只影，中年易感，祗付双眉。\n珍重交情，勉旃时用，回首岫云从此归。\n能相忆，有好音遗我，在水之湄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15518, '沁园春', '李曾伯', '水北洛南，未尝无人，不同者时。\n赖交情兰臭，绸缪相好，宦情云薄，得失何知。\n夜观论兵，春原吊古，慷慨事功千载期。\n萧如也，料行囊如水，只有新诗。\n归兮。\n归去来兮。\n我亦办征帆非晚归。\n正姑苏台畔，米廉酒好，吴松江上，莼嫩鱼肥。\n我住孤村，相连一水，载月不妨时过之。\n长亭路，又何须回首，折柳依依。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15519, '沁园春', '李曾伯', '天下奇观，江浮两山，地雄一州。\n对晴烟抹翠，怒涛翻雪，离离塞草，拍拍风舟。\n春去春来，潮生潮落，几度斜阳人倚楼。\n堪怜处，怅英雄白发，空敝貂裘。\n淮头。\n虏尚虔刘。\n谁为把中原一战收。\n问只今人物，岂无安石，且容老子，还访浮丘。\n鸥鹭眠沙，渔樵唱晚，不管人间半点愁。\n危栏外，渺沧波无极，去去归休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15520, '沁园春', '李曾伯', '紫金山前，铁骑围中，惟公尚知。\n怅当时卯角，鱼犹同队，如今缟鬓，鸥已忘机。\n故垒荒榛，群贤拱木，畴记官军夜战时。\n不图见，独岁寒不改，老气犹奇。\n嗟哉月驶舟移。\n四十载光阴昨梦非。\n叹荷薪弗克，祗惭弓冶，扃柴却扫，绝望簪圭。\n菌短椿长，微鹏巨，天分当然何足疑。\n闻公里，有溪堪钓，盍亦云归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15521, '沁园春', '李曾伯', '大疏归来，小阮适闲，喜同此时。\n问垂弧历载，几番遥祝，举觞华旦，相会良希。\n颂以松椿，酌之椒柏，预卜明年百事宜。\n春犹浅，趁雪晴梅放，且和新诗。\n公虽厌直兰闱。\n如正色朝端当宁知。\n看大廷诸老，争推前席，吾家五祖，自有传衣。\n暖律初回，要津立上，卿相时来皆可为。\n祈公寿，与东君不老，南极齐辉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15522, '沁园春', '李曾伯', '弧矢四方，江汉一萍，少年壮游。\n叹而今老矣，祗宜野服，欲何为者，还著轻裘。\n匹马萧萧，孤鸾杳杳，城郭重来空白头。\n西风里，对一番新月，又荻花秋。\n依然千古荆州。\n问刘表诸人还在不。\n向亭前举酒，不堪北顾，船头击楫，忍负中流。\n远水长天，淡烟衰草，还是当时王粲楼。\n何如且，倩吴歌楚舞，一洗新愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15523, '沁园春', '李曾伯', '嗟矍铄翁，对婵娟月，怀汗漫游。\n怅江湖幸有，季鹰鲈脍，田园忍负，晏子弧裘。\n丹桂开时，青苹渺处，家在三吴天尽头。\n庭皋静，又一番叶落，天下皆秋。\n少年弓剑边州。\n惊转首黄粱还梦不。\n叹悠悠千载，关山无恙，滔滔一水，岁月俱流。\n镜老菱花，笳悲庐叶，新雁数行人倚楼。\n君知否，把眉峰蹙破，岂为身愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15524, '沁园春', '李曾伯', '唤麴生来，与常娥约，从太守游。\n把玉箫声寄，萧关短笛，霓裳曲换，清塞重裘。\n桂影飘摇，桐阴立尽，多少征人霜满头。\n油幢暇，不掀髯一笑，辜负中秋。\n斗杓矗处中州。\n还有解闻鸡起舞不。\n看鸣弦中鹄，穿杨电激，飞球戏马，策垂星流。\n绣帽归军，玳簪环客，薄晚同登庾亮楼。\n浮生事，是几番玩月，何苦多愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15525, '沁园春', '李曾伯', '麴生来言，素娥寄声，偶阆苑游。\n问去年今夕，逢余桂岭，前年今夕，见子菟裘。\n何事尘劳，启人厌倦，痴兔老蟾因缩头。\n宜珍重，要相期後会，直待来秋。\n休休。\n莫舞凉州。\n岂巫女风姨相妒不。\n枉停歌准拟，冰轮东上，持杯顾恋，银汉西流。\n一笑天悭，四并时少，应负珠帘十二楼。\n呼蕉叶，且与生酹古，排遣牢愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15526, '沁园春', '李曾伯', '百尺楼头，奇哉此翁，元龙後身。\n当壮年襟度，百川鲸吸，平生出处，一片鸥轻。\n冷淡逋梅，淋漓旭草，但见风雷笔下生。\n荆州幕，觉坐间小异，乃有斯人。\n牙樯喜色津津。\n正江影涵秋无点尘。\n对白苹黄苇，且供诗卷，紫薇红药，却演丝纶。\n举酒延蟾，倚栏闻雁，应念征人归尚春。\n君王问，尽不妨细说，万里戎情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15527, '水调歌头', '李曾伯', '一段太清境，谁幻出阶坳。\n不知身住何处，爽气逼霜袍。\n但见人间一样，似夜又还非夜，栖鸟不安巢。\n认得在尘世，禁鼓二更敲。\n最看，来竹底，上梅梢。\n几家朱户，不如儿女醉蓬茅。\n谁把琴声三弄，不管骚人幽趣，似向曲中嘲。\n长啸赋赤壁，有酒更无肴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15528, '水调歌头', '李曾伯', '夜永厌银烛，移步下堂坳。\n秋风昨梦少年，高兴鹄成袍。\n世上痴儿睡去，历历江山细数，孤鹘啸危巢。\n地静未容去，门掩不妨敲。\n转巍阑，低画桶，落寒梢。\n南楼老子争似，短笛一椽茅。\n无色界间长啸，不夜城中高卧，随意弄诗嘲。\n洗要更酌，为我问佳肴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15529, '水调歌头', '李曾伯', '千一载英杰，百二国山河。\n提封几半宇宙，万里仗天戈。\n十乘晋军旗鼓，三岁秦关扃锁，地利属人和。\n位次功第一，未数侯何。\n建青油，持柴荷，听黄麻。\n乾坤整顿都了，玉殿侍羲娥。\n且醉东湖花柳，却泛西湖舟楫，留不住岷峨。\n谁为语儒馆，浓墨被诗歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15530, '水调歌头', '李曾伯', '三蜀最佳处，昌是海棠州。\n清香燕寝闲暇，人与地风流。\n十万人家寿域，六七十翁儿状，眉寿祝公侯。\n谁为语廊庙，且许寇恂留。\n过书云，才几日，纪千秋。\n祖孙卮酒相贺，庆事袭箕裘。\n自有诗书万卷，安用田园千顷，松菊足优游。\n持以寿公者，梅萼伴清修。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15531, '水调歌头', '李曾伯', '老子世北客，家本住吴头。\n登临聊复尔耳，佳节懒为酬。\n刚被西风断送，又为黄花牵帅，草创作斯游。\n目力眇无际，更上一层楼。\n对长江，流不尽，古今愁。\n凭兰正拟一笑，襟袍怯於秋。\n高处令人心悸，放旷舒怀何暇，好趁醒时休。\n留取江湖量，归去醉中州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15532, '水调歌头', '李曾伯', '行客送行客，况又值新秋。\n莼乡此去万里，先我上扁舟。\n三载乌奴聚首，异县乡情对语，乘月几登楼。\n去去远蜀口，日日望吴头。\n丹青手，描不就，此离愁。\n半生萍梗江汉，别恨最绸缪。\n远水长空一色，风顺波平如掌，雁序际天游。\n故旧有相问，犹滞剑南州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15533, '水调歌头', '李曾伯', '骤雨送行色，把剑渡长淮。\n西风咄咄怪事，吹不散烟霾。\n才是橙黄时候，早似梅边天气，寒意已相催。\n老子尚顽耐，仆马苦虺。\n叹平生，身客路，半天涯。\n飞鸢曾见，底事又重来。\n回首白云何处，目送孤鸿千里，去影为徘徊。\n篱菊渐秋色，杜瓮有新醅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15534, '水调歌头', '李曾伯', '万里长淮北，青是汉时山。\n几年壁垒相望，高枕度春闲。\n不道草庐豪杰，手袖伊吾长剑，驰志在楼兰。\n锺鼓令秋肃，毡胆冰寒。\n诗书帅，金横带，玉为鞍。\n天生如结数辈，虏岂易江南。\n京索成皋此际，东郭韩庐俱困，故老正争看。\n琳檄未能草，冯铗直空弹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15535, '水调歌头', '李曾伯', '岘山羊叔子，江左管夷吾。\n勋名掀揭宇宙，金匮侈丹书。\n两载风寒卧护，一柱狂澜屹立，形势壮陪都。\n功业笑儿辈，别有大规模。\n看东归，游凤沼，转鸿枢。\n不应廊庙人物，犹佩玉麟符。\n好是茅峰仙客，更与锺山佛子，同日庆垂弧。\n一饮共千岁，永永辅皇图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15536, '水调歌头', '李曾伯', '簪履盛元幕，领袖属英游。\n登车揽辔馀事，何止客诸候。\n看尽巫云岷雪，却妨庐峰湓浦，砥柱赞中流。\n百叠青山路，一片白苹洲。\n今日事，风涛上，一虚舟。\n长江万顷寒碧，犹谓马能浮。\n况是眼前局面，心腹忧如边角，胜著赖帷筹。\n谈笑济时了，勋业迈前修。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15537, '水调歌头', '李曾伯', '风卷江湖浪，举足是羊肠。\n峡山知在何处，榛莽更凄凉。\n不为渊明五斗，直为班超万里，雅志未能忘。\n耿耿富襟抱，行计有诗囊。\n溯吴头，逾楚尾，界瞿塘。\n从他昵昵燕语，留不住征樯。\n芳草天涯弥望，着我飞凫来去，在在可徜徉。\n持此见刘表，抵掌与谈王。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15538, '水调歌头', '李曾伯', '幻出广寒境，罗袜净无尘。\n素娥风格分明，玉骨水为神。\n手揽清光盈掬，眼看山河一色，阅尽古今人。\n对影且长啸，一酌瓮头春。\n千万顷，琉璃色，楚天清。\n庾楼袁舫何事，汩汩主和宾。\n但见老蟾无恙，不管镜圆钩阙，寒暑任相更。\n此夕幸无雨，何惜放颜醺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15539, '水调歌头', '李曾伯', '碾就一轮玉，扫尽四边尘。\n白乎不涅不磷，千古此丰神。\n领略常娥体态，寂寞谪仙材调，四海岂无人。\n安得金丹诀，长驻玉颜春。\n镜圆明，冰样洁，水来清。\n良宵难值如许，何惜且留宾。\n拟唤桓伊三弄，影转画檐西畔，钟鼓趣残更。\n肺腑尽霜雪，麴不能醺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15540, '水调歌头', '李曾伯', '久欲乘槎去，间阔几仙尘。\n乾坤炯炯不夜，造化抑何神。\n谁道二分无赖，到处一轮都满，天未始私人。\n今夕果何夕，非夏亦非春。\n风露下，明作哲，圣之清。\n纷纷浮世代谢，燕客与鸿宾。\n欢恨离愁尽扫，谢赋鲍诗高束，一枕听严更。\n尔自屋梁落，吾已醉醺醺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15541, '水调歌头', '李曾伯', '薄酒长亭别，饱饭故园归。\n两年婉婉席上，甘苦每同之。\n骥群中独步，糜鹿兴前不瞬，孰可与争驰。\n力挽不能寸，健翮遽斜飞。\n经营事，艰难状，老天知。\n区区塞马得失，一笑付观棋。\n用则风云万里，不用烟霞一壑，两鬓未应丝。\n回首乌樯外，鸥鸟自忘机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15542, '水调歌头', '李曾伯', '壁垒壮西塞，形势古州来。\n九重庙算经远，边隙肯轻开。\n整顿金城千仞，遮护风寒数处，蛇豕敢当哉。\n惆怅倚长剑，扫未尽烟埃。\n骑连营，桥列栅，木成排。\n老酋鱼釜视我，孰与障吾淮。\n横槊冲围四出，北府牢之何勇，新进喜多才。\n老子何归矣，击壤乐春台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15543, '水调歌头', '李曾伯', '枣颊上秋色，朔漠寇南来。\n斧螗蜂猬棼集，腥雾扫难开。\n细看眼前局面，惊落人间匕箸，砥柱者谁哉。\n熊虎贾馀勇，弧兔等轻埃。\n炮雷轰，戈日耀，阵云排。\n不图风定波息，谈笑静长淮。\n休诧穿杨妙手，乘早闹蓝抽脚，谁拙又谁才。\n束起楼兰剑，归钓子陵台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15544, '水调歌头', '李曾伯', '壮志小鹏背，万里欲乘风。\n马裘敝，老来无复旧游重。\n楚尾吴头蜀口，三十载间陈迹，衮衮水之东。\n休说射雕手，且学钓渔翁。\n奚为者，聊尔耳，此山中。\n壶觞自引，不妨换羽与移宫。\n蓬矢桑弧何事，朝菌大椿皆分，识破色俱空。\n掬润弄明月，长啸倚青松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15545, '水调歌头', '李曾伯', '鸿雁未应到，可怪此番风。\n木犀天气，何事爽逼夹衣重。\n长记呼韩塞下，每向飞廉声里，占见马蹄东。\n今日闭门睡，都不管山翁。\n李北平，班定远，魏云中。\n纷纷成败，任取勋业纪南宫。\n幸得明朝无雨，定是中宵有月，莫放酒尊空。\n起舞弄庭叶，清影伴岩松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15546, '水调歌头', '李曾伯', '一番蓼花雨，几阵桂枝风。\n杖藜多暇，准拟同醉小山重。\n底事阮郎清致，苦托休文瘦损，咫尺阻西东。\n秋色浩如许，岂可欠诗翁。\n门前事，都莫问，付杯中。\n纷纷蛮触等耳，富贵大槐宫。\n何惜振衣而起，相与凭栏一笑，抵掌共谈空。\n佳客傥不至，推枕卧云松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15547, '水调歌头', '李曾伯', '缔好恨不早，觌面雅相志。\n璇星楼上，一见天产此英奇。\n功在淮梁砥柱，政蔼汉扶襦裤，仅借寇恂期。\n懊恼剑花冷，手欲鲸鲵。\n濡须坞，咽喉地，腹心谁。\n公其揽辔凭轼，勋业笑谈为。\n贯索旄头息焰，斗极泰阶动色，归佐太平基。\n客有问仆者，只说在渔矶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15548, '水调歌头', '李曾伯', '之子问行役，火伞正当天。\n酷哉几可炙手，流汗满襟沾。\n仆仆长亭古道，人在竹舆何似，甑釜受蒸煎。\n帝悯苍生热，敕下九龙渊。\n命丰隆，驱屏翳，起蜚廉。\n神工一炊黍顷，爽气遍垓埏。\n洗涤山河尘土，转作清凉境界，物类举醒然。\n稽首谢天赐，伸脚快宵眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15549, '水调歌头', '李曾伯', '君莫厌行役，易尔此非难。\n人情无已，久阴忧潦霁忧乾。\n借得庭轩一榻，忘却征涂炎暑，小驻瀹龙团。\n世路任渠险，襟抱五湖宽。\n叹平生，环辙迹，已苍颜。\n梅花雪片万里，奚又絷南冠。\n应是江山好处，犹待推排老眼，天未许休官。\n莫忆故园竹，日日报平安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15550, '水调歌头', '李曾伯', '乔木老盘谷，仙李盛峨岷。\n参横井转，月边犹赖有长庚。\n传得丹溪正派，更是平庵宅相，夷路早蜚英。\n十载星沙幕，一片玉壶冰。\n题舆了，千万里，尽云津。\n渚宫小驻，不妨谈笑对秋城。\n西去凭熊驾驷，东下握兰持橐，衮衮看峥嵘。\n愿借鹫峰桂，岁以寿金觥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15551, '水调歌头', '李曾伯', '万里净无翳，一镜独当天。\n老蟾痴兔顽甚，阅世几何年。\n任尔炎凉千变，不改山河一色，爽气逼人寒。\n何必乘槎去，直到斗牛间。\n叹常娥，元不嫁，只孤眠。\n古今遗恨，不能长似此宵圆。\n我有竹溪茅舍，办取金风玉露，一笑四并全。\n细和坡仙句，低唱教婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15552, '满江红', '李曾伯', '镇日山行，人倦也、马还无力。\n游历处，总堪图画，足供吟笔。\n涧水绿中声漱玉，岭云白外光浮碧。\n信野花、啼鸟一般春，今方识。\n真可羡，林泉客。\n真可叹，尘埃役。\n想希夷冷笑，我曹踪迹。\n七十二峰神物境，几千万壑仙人室。\n待身名、办了却归来，相寻觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15553, '满江红', '李曾伯', '衮衮青春，都只恁、堂堂过了。\n才解得，一分春思，一分春恼。\n儿态尚眠庭院柳，梦魂已入池塘草。\n问不知、春意到花梢，深多少。\n花正似，人人小。\n人应似，年年好。\n奈吴帆望断，秦关声杳。\n不恨碧云遮雁绝，只愁红雨催莺老。\n最苦是、茅店月明时，鸡声晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15554, '满江红', '李曾伯', '天顾坤维，烦紫气、来从南斗。\n鞭才定，匆匆塞上，咏薇吟柳。\n少借日边霖雨望，教知天下风云手。\n听吾民、争说近年无，前朝有。\n平安夜，舒长昼。\n笳鼓静，笙歌奏。\n记西湖五月，藕花时候。\n待把雁门冠带了，归来麟阁丹青旧。\n放蜀山、万点入樽，为君寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15555, '满江红', '李曾伯', '姑射山人，仙去後、唯存标格。\n犹赖有、墨池老手，草玄能白。\n留得岁寒风骨在，岂烦造化栽培力。\n有世间、肉眼莫教看，非渠识。\n元不夜，枝何月。\n元未腊，花何雪。\n最孤高不受，多情轻折。\n只有暗香天靳予，黄金作指难为术。\n更若将、解语付真真，空成色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15556, '满江红', '李曾伯', '老去生涯，都付与、一丘一壑。\n功名事，惭非好手，几逢危著。\n走马斗鸡年少趣，椎牛酾酒军中乐。\n到而今、浑似梦中看，休休莫。\n江湖路，西风恶。\n霄汉志，秋云薄。\n更那堪州铁，铸成重错。\n当贵买臣毋足羡，知非伯玉真能觉。\n问心期、应有海翁鸥，山人鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15557, '满江红', '李曾伯', '竹马同游，平生志、相期霄壑。\n今老矣，儒冠宁误，戎妆徒著。\n卷起鲸鲵江海事，放教禽鸟山林乐。\n问尚堪、舞剑渡河无，公应莫。\n粟可饭，衣从恶。\n秫可酒，茶胜薄。\n但此身长健，老天不错。\n竹院昼闲参内景，蒲团夜坐披圆觉。\n愿此生、无愧北山猿，西湖鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15558, '满江红', '李曾伯', '小小池亭，仿佛似、洛川岩壑。\n天付与、老身游戏，馀生吃著。\n剩喜酒能消思虑，翻疑书解妨人乐。\n听雨翁、白雪寄新词，愁言莫。\n毋自叹，蒿莱恶。\n甘自味，齑盐薄。\n对乱花丛竹，翠红交错。\n元亮悦闻亲友话，羲之常恐儿曹觉。\n望碧云、休忆女乘鸾，人骑鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15559, '满江红', '李曾伯', '既作闲人，便应付、此身沟壑。\n不应更，将愁半点，寸心中著。\n责子渊明徒自苦，忧君范老何时乐。\n纵一嘲、一咏欲奚为，何如莫。\n不自鄙，葵蔬恶。\n还肯荐，茅柴薄。\n任侯门海陆，杂陈珍错。\n有暇盍联车骑过，相忘勿遣诗情觉。\n怕家僮、无处买莼鲈，烹琴鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15560, '贺新郎', '李曾伯', '万里归朝去。\n倚江亭、绿波碧色，一川晴絮。\n赢得威名留草木，玉垒雪山高处。\n未应减、平淮裴度。\n见说金瓯书字久，待公来、便作商岩雨。\n休望却，蜀都赋。\n旌旗回首春城暮。\n听樯头、飞燕似把，人情低诉。\n两两三三鸥鹭里，拍拍船儿一羽。\n算惟有、清芬载取。\n百万人家儿样恋，恨柳风、不为留连住。\n离梦绕，沙堤路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15561, '贺新郎', '李曾伯', '满酌荆州酒。\n望莱庭、斑衣拜祝，俾吾亲寿。\n玉水雪楼游宦地，近访甘棠依旧。\n逢父老、颂声盈口。\n争道蜀边劳数载，也真宜、略畔云横岫。\n小儿辈，任成否。\n东皋十月梅开後。\n想亲朋、团栾一笑，从容觞豆。\n塞上弓刀成底事，不过腰金如斗。\n算不直、渊明株柳。\n只恐鲸鲵无计取，更须烦、绿野持竿手。\n看勋业，国长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15562, '贺新郎', '李曾伯', '将谓霏微雨。\n恍朝来、虚檐生白，寒侵冒絮。\n拟和盐花凌谢韫，巧思翻成金注。\n谁寄我、雪车冰柱。\n酿熟羊羔炉拥兽，羡画楼、金帐调宫羽。\n人应共，回风舞。\n围场校猎淮云暮。\n记当时、银杯缟带，网禽兔。\n老去不禁鞍马力，独对愁吟似甫。\n问一棹、剡溪何处。\n愿与铁衣春解戍，把梁园、旧话供儿语。\n孤梅外，梦魂度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15563, '贺新郎', '李曾伯', '才过黄花雨。\n问长堤、依依万柳，未春何絮。\n一目河山银幻出，惊诧夜光流注。\n巍观矗、玉为云柱。\n风卷寒庐迷过雁，渺沧波、莫认沙鸥羽。\n千万蝶，空中舞。\n霸桥寂寞前溪暮。\n耸诗肩、霜裘拥貉，月毫挥兔。\n记得梅奴曾索笑，解如逢交甫。\n今孤垒、寒烟深处。\n休说鹅池平蔡事，庆新年、一稔欢相语。\n持大白，勿虚度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15564, '贺新郎', '李曾伯', '幸得闲中趣。\n问何为、倏逾桂岭，重来荆渚。\n唤醒门前弧矢梦，钩月相辉初度。\n谩羞听、军中鼙鼓。\n马上弓刀成底事，仅平明、旆入襄州去。\n能不愧，古羊杜。\n此身何以酬明主。\n怅新来、鬓毛添白，衰容如许。\n三万貔貅齐贾勇，好为一清狐兔。\n看柳色、大堤如故。\n世事付之杯酒外，那棋边、得失都休语。\n来共看，雁儿舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15565, '念奴娇', '李曾伯', '黄梅过雨，望隔林、一缕长烟浮碧。\n亟拥征鞍寻午梦，卧看青山排闼。\n扫户风清，拂檐云淡，爽气生萧发。\n黄粱惊觉，子规枝上啼彻。\n堪羡麦熟蚕成，酒香鸡嫩，风味农家别。\n幸有住山供活计，何苦江湖南北。\n菊老陶园，瓜荒邵圃，空负干时策。\n洛阳三顷，胜如金印六国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15566, '念奴娇', '李曾伯', '平生宦海，是几番风雨，几番霜雪。\n绿野来归身强健，镜里微添华发。\n剑束床头，书寻架上，富贵轻於叶。\n南坡石竹，年来尤更清绝。\n好是梅坞松关，对湘溪一曲，翠屏千叠。\n柱杖篮舆诗卷里，尚小东山勋业。\n只恐鸥盟，难望鹤怨，未是闲时节。\n片云收却，照人依旧明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15567, '念奴娇', '李曾伯', '云胡不喜。\n得抽脚篮中，安身局外。\n世路风涛都历遍，几度眉攒心碎。\n八尺藤床，二升粟饭，方寸恢馀地。\n翻云覆雨，从伊造物儿戏。\n不见刻木牵丝，鸡皮鹤发，弄罢寂无事。\n随分风光堪领略，聊放疏狂些子。\n刘项雌雄，跖颜修短，无彼亦无此。\n茅檐高卧，不知春到花底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15568, '念奴娇', '李曾伯', '浮生如寄，叹征尘驱我，担簦西去。\n烟障云屏相迎送，几幅鹅溪缣素。\n挥汗流金，饮冰漱玉，桃叶呼前渡。\n若将有意，道傍一鹭延伫。\n细读壁上龙蛇，太丘笔在，更著茶玻句。\n樽酒十年今白发，不改江流东注。\n胜概难逢，旅怀易动，信美非吾土。\n恨无六翮，长风万里高举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15569, '满庭芳', '李曾伯', '浪拍金鳌，春浮铁瓮，气清天朗如秋。\n江皋无事，飞盖强追游。\n万顷蒲萄光里，风樯共、塔影悠悠。\n人间事，年华似掷，一水与俱流。\n绸缪。\n千古恨，纷纷离合，晋宋曹刘。\n望长安何处，落照西头。\n往事苍苔陈迹，夷吾在、吾属何愁。\n清樽畔，谁能为我，一曲舞梁州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15570, '满庭芳', '李曾伯', '山接平芜，烟横远墅，修眉淡抹晴妆。\n菊梅交际，天未十分霜。\n几许无穷秋思，空凝伫、衰柳斜阳。\n溪头路，黄芦一片，凫雁两三行。\n平章。\n风景似，画图一幅，著我徜徉。\n山中无事，聊尔适吾狂。\n不用登临感慨，青帘外、新酒堪尝。\n何为者，东家宋玉，千古叹凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15571, '瑞鹤仙', '李曾伯', '百年过半也。\n怅壮心零落，鬓星星也。\n风儿渐凉也。\n近中秋月儿，又初生也。\n田园暇也。\n矍铄哉、是翁也。\n记当时，弧矢垂门，孤负四方志也。\n休也。\n牙签插架，玉帐持麾，总成非也。\n浮生梦也。\n皇皇欲、奚为也。\n趁身闲、随分粗衣淡饭，一笑又何妨也。\n问神仙，底处蓬莱，醉乡是也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15572, '喜迁莺', '李曾伯', '轻云暮卷，望澄空如水，千里一碧。\n菱镜冰悬，桂轮玉碾，喜见中原秋色。\n老蟾炯炯无翳，阅尽尘寰今夕。\n堪恨处，度霓裳曾到，长生宫阙。\n坐客。\n休叹息。\n看此清光，天岂限南北。\n便好乘风，为持玉斧，修取山河如一。\n西湖旧时花草，会遣孀娥重识。\n从今去，举太平玩事，长如今夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15573, '声声慢', '李曾伯', '红绡剪就，绛蜡熔成，天然一种仙姿。\n竹外家风，凄凉俭薄为宜。\n东君苦怜消瘦，强教伊、傅粉匀脂。\n较量尽，胜夭桃轻俗，繁杏粗肥。\n好是新妆雅态，对疏蟾淡淡，薄雾霏霏。\n迥出红尘，轻盈玉骨冰肌。\n犹嫌污人颜色，谁云似、虢国娥眉。\n香韵别，怕满园、蜂蝶未知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15574, '声声慢', '李曾伯', '修洁孤高，凌霜傲雪，潇然尘外丰姿。\n一白无瑕，玉堂茅舍俱宜。\n飘飘羽衣缟袂，都不染、富贵膏脂。\n调羹事，看水边清瘦，雨後红肥。\n偏爱春工尚浅，向南枝信透，东阁香霏。\n翠袖犹寒，不禁弱质柔肌。\n浑如故人邂逅，聊相与、一笑开眉。\n归去晚，任帘栊、深闭未知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15575, '青玉案', '李曾伯', '栖鸦啼破烟林暝。\n把旅梦、俄惊醒。\n猛拍征鞍登小岭。\n峰回路转，月明人静，幻出清凉境。\n马蹄踏碎琼瑶影。\n任露压巾纱未整。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15576, '青玉案', '李曾伯', '去年曾借梅为寿。\n转眼垂弧小春又。\n一笑巡檐清影瘦。\n雪边聊且，收香藏白，少俟融和透。\n新来东阁高吟就。\n金鼎家声自依旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15577, '好事近', '李曾伯', '春在粉墙西，墙里不知春色。\n惟有桃花一树，似故园曾识。\n晚来携客上南楼，山外又山隔。\n准拟清明何处，问东风知得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15578, '柳梢青', '李曾伯', '万里青天，西来後我，先我东归。\n夜月鞭筹，春风幕府，鹗荐争推。\n杯行到手休辞。\n道秋菊、春兰有时。\n若到松江，莫惊鸥鹭，记取坡词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15579, '虞美人', '李曾伯', '韶华只隔窗儿外。\n病起昏於醉。\n花开花落总相忘。\n惟有梦随胡蝶、趁春忙。\n故园芳草应如旧。\n只恨人消瘦。\n拟凭飞燕语归期。\n拼却牡丹开了、有酴縻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15580, '减字木兰花', '李曾伯', '无可不可。\n还你天公还我我。\n味触声香。\n尽付庄周蝶满床。\n谩天不过。\n留取心机休用破。\n净几明窗。\n乐取闲中日月长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15581, '减字木兰花', '李曾伯', '如何则可。\n我亦不知其谓我。\n隐几焚香。\n对酒一壶书一床。\n知仁观过。\n浑沌翻怜谁凿破。\n寄傲南窗。\n堪羡渊明滋味长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15582, '西江月', '李曾伯', '不暖不寒天气，无思无虑山人。\n竹窗时听野禽鸣。\n更有松风成韵。\n竟日蒲团打坐，有时藜杖闲行。\n呼童开酒荐杯羹。\n欲睡携书就枕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15583, '西江月', '李曾伯', '排遣新寒有酒，追寻旧隐无人。\n四山朔吹又冬鸣。\n吹送午锺馀韵。\n过眼霜高木落，寄心月驶云行。\n归欤闭户饱藜羹。\n世事华胥一枕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15584, '糖多令・唐多令', '李曾伯', '枫荻响飕飕。\n长江六月秋。\n二十年、重到沙头。\n城郭人民那似旧，曾识面、两三鸥。\n落日且登楼。\n英雄休涕流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15585, '点绛唇', '李曾伯', '懒上巍楼，楚江一望天无际。\n漫游萍寄。\n莫挽东流水。\n一片秋光，直到山阴里。\n人还记。\n戍边归未。\n更忆鲈鱼美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15586, '摸鱼儿', '李曾伯', '趁西风、且登黄鹤，挥豪先奏秋赋。\n燕山桂种清分在，人物翩翩如许。\n堪羡处。\n长安近、蟾宫相继金闺步。\n佳哉盛举。\n看精淬龙泉，厚培鹏背，自此要津去。\n荆州事，多幸乡情相予。\n几番灯柝棋墅。\n转头江阔轻帆速，梦入吴松鸥鹭。\n君记取。\n旧王粲、曾言信美非吾土。\n故人相语。\n为细数艰难，满头雪白，无奈戌边苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15587, '摸鱼儿', '李曾伯', '对垂弧、引觞一笑，凄凉薄分天气。\n丁年驰骛弓刀後，报国孤忠自许。\n堪叹处。\n今老矣，强颜犹踵邯郸步。\n安能远举。\n谩目送征鸿，梦劳胡蝶，无计便归去。\n清闲禄，旧说天公靳予。\n何时松菊村墅。\n生非燕颔鸢肩相，岂是觚棱鹭。\n收拾取。\n休直似、文渊定远空怀土。\n阿戎可语。\n待乞得身还，屏伊世累，甘受作诗苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15588, '朝中措', '李曾伯', '少年随分赋鹦洲。\n得意桂花秋。\n今日送君行色，梦和月到南楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15589, '齐天乐', '李曾伯', '少年塞上秋来早，昴街尚馀芒曜。\n举目关河，惊心弧矢，顾我岂堪戎纛。\n几番凤诰。\n愧保障何功，恩隆旒藻。\n笑指呼鹰，露花烟草忆刘表。\n头颅如许相与，岁寒犹赖有，白发公道。\n对月怀人，临风访古，往事凄凉难考。\n何时是了。\n莫驰志伊吾，贪名清庙。\n松菊归来，稽山招此老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15590, '八声甘州', '李曾伯', '正莼鲈佳梦绕吴乡，牙樯忍轻离。\n向仲宣楼上，凭高举酒，几共灯棋。\n曾记少陵留咏，出幕合持麾。\n飞盖长安去，华贯平跻。\n好是倚门迎笑，恰野堂云壑，菊後梅时。\n庆凤雏新长，携手奉莱衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15591, '八声甘州', '李曾伯', '领青油车骑出郊，来游晋龙山。\n喜水天澄霁，稻畦镰净，榆塞戈闲。\n登高谩酬佳节，一笑破苍颜。\n剩泛茱萸菊，杯莫留残。\n休说参军往事，意当时凝眺，不到长安。\n赖座间小异，豪气眇尘寰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15592, '八声甘州', '李曾伯', '怅浮生、俯仰迹成空，依然此江山。\n对秋容如画，天长雁度，水阔鸥闲。\n追游未甘老态，凭酒借红颜。\n归骑斜阳外，柳老荷残。\n幸对黄花时节，喜宾朋晤语，烽火平安。\n仅风巾一笑，名尚满人寰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15593, '满庭芳', '李曾伯', '八足横戈，一身衷甲，将军致尔来前。\n呼僮解缚，亟荐泽虞鲜。\n族类横行草地，今骈首、鼎镬连连。\n荆江上，不图霜後，风味似吴天。\n晴川。\n千里外，分甘遗远，多谢勤拳。\n对香枨新酒，一洗腥膻。\n慰我吟情归思，都忘却、张孟鲈鳊。\n持螯了，老饕作赋，佳话楚乡传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15594, '哨遍', '李曾伯', '大块赋形，皇览揆予，俾尔昌而寿。\n嗟壮游。\n岁月老征裘。\n向秋来、顿如蒲柳。\n桂开又。\n鲈莼蟹橙正美，故人应忆传杯手。\n想薜荔岩峦，梧桐庭院，当时风景依旧。\n对斜阳、极目倚危楼。\n问一舸、何时过吴头。\n乘下泽车，戴华阳巾，锦衣游昼。\n犹。\n客有名流。\n交情金石襟期厚。\n双湖烟艇里，剑锋紫气冲斗。\n剩妙墨淋漓，清歌发越，未应独步诗千首。\n待挂了衣冠，来寻杖履，陪君此乐须有。\n到如今、不愿酒泉侯。\n愿生入、玉门早归休。\n任远人、从问安否。\n梁园宾客虽富。\n谁出相如右。\n相逢身健，时平无事，是处溪山明秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15595, '水龙吟', '李曾伯', '黄旗吉语飞来，胡儿已落将军手。\n吾皇神武，一新城郭，断谟天授。\n铁骑才临，雕戈竞逐，击蛇先首。\n快风驱雨洗，江空谷静，淮淝上、似之否。\n此事老臣何有。\n想捷传、延英方昼。\n玉颜应笑，金瓯堪保，贺声交口。\n吾责免夫，吾归可矣，萧然一叟。\n把功名，分付诸公，聊自尝酒盈斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15596, '水龙吟', '李曾伯', '荆州咫尺神州，几番得失孙刘手。\n山河天险，东南牖户，钺何轻授。\n泪落碑存，鹤归城是，不堪回首。\n喜大堤草色，镇长春在，羊与陆、孰能否。\n风景依然吾有。\n柳营深、铁衣闲画。\n摩云胜气，追戎马足，走蜚狐口。\n往事纷纷，付之蛮触，相忘庄叟。\n有人焉，中夜闻鸡，剑光正烛牛斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15597, '水龙吟', '李曾伯', '吾皇神武中兴，直须整顿舆图旧。\n岂惟天顾，岷峨一角，但西其首。\n遮护咽喉，扶持气派，宁无医手。\n有庙谟先定，傍观何待，留侯蹑、魏侯肘。\n天眷我家仁厚。\n盛英才、载量车斗。\n中流孤艇，千钧一发，老夫何有。\n休对秋风，移宫换羽，吟无绝口。\n看福星，太乙临梁，此虏自不能久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15598, '水龙吟', '李曾伯', '梅边连辔偕来，柳边先我观光去。\n一门椿桂，尊君孙盛，小儿文举。\n黄鹤联登，横翔雕鹗，健凌鹦鹉。\n趁霜晴春小，南宫问讯，又同奏、明光赋。\n从此青云阔步。\n看龙门、锦标双取。\n荆州时事，不妨大对，细陈当宁。\n久要论交，中年语别，不堪离绪。\n约杏园，得意归时，吾已在浙江浒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15599, '满江红', '李曾伯', '千古襄阳，天岂肯、付之荆棘。\n宸算定、图回三载，一新坚壁。\n狼吻不甘春哨衄，马蹄又踏寒滩入。\n向下洲、一鼓扫群胡，三军力。\n连帅是，并州绩。\n宾佐有，雍丘逖。\n赖阴人成事，同心却敌。\n见说陈尸三十里，投鞍委甲如山积。\n待老臣、为作岘樊铭，诸石。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15600, '满江红', '李曾伯', '推枕闻鸡，正怪得、乾坤都白。\n元是有、福星临照，至和薰出。\n缘饰夜城疑不夜，弥漫色界成无色。\n更词、巧欲夺天葩，尤殊特。\n貂帽拥，寒何力。\n羔酿举，情何极。\n欠开樽细挹，梅花标格。\n十万铁衣冰到骨，祈天只愿王师息。\n想家童、日办剡中舟，溪头立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15601, '满江红', '李曾伯', '荡节将行，原显尽、花毡铺白。\n人羡道、青丝辔整，红蕖幕出。\n宇宙中间无点医，水天上下俱同色。\n向个中、著此玉为人，真英特。\n元自得，融和力。\n浑不管，凝寒极。\n看福星临照，政敷民格。\n且访桃源仙世界，伫传梅驿春消息。\n定明年、拜表贺端闱，螭坳立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15602, '八声甘州', '李曾伯', '自当年、种柳向西门，古今号名州。\n对风声策策，浪涛衮衮，又是新秋。\n暂为江山弹压，谁得似贤侯。\n夜观灯棋里，几共边筹。\n休效季鹰高兴，为莼羹鲈脍，遽念吴头。\n且安排维楫，相与济中流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15603, '八声甘州', '李曾伯', '续仲宣、一赋小呼鹰，声名满荆州。\n向宾筵游戏，豪端月露，皮里阳秋。\n遍历文书刁斗，何患不封侯。\n横槊风烟表，独占诗筹。\n见说眉攒心事，在岷峨乡国，落日西头。\n怅英豪遗恨，都付大江流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15604, '八声甘州', '李曾伯', '自六朝、用武诧荆州，襟喉重疆陲。\n更西风似箭，峡江如线，事势夔夔。\n须仗中流砥柱，天付治平谁。\n甚矣吾衰矣，将老东篱。\n休说纷纷往梦，任阴平邓艾，骆谷姜维。\n向棋边聊且，官事了痴儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15605, '八声甘州', '李曾伯', '对西风、先自念莼鲈，又还月生西。\n叹平生霜露，而今都在，两鬓丝丝。\n当年门垂蓬矢，壮岁竟奚为。\n磊落中心事，只有天知。\n多谢君恩深厚，费丁宁温诏，犹置驱驰。\n看弓刀何事，终是愧毛锥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15606, '八声甘州', '李曾伯', '问秋光、乞得一宵闲，满引玉东西。\n喜亲朋咸集，宴酣真乐，非竹非丝。\n坎止流行付分，岂尽是人为。\n试向君平卜，还可前知。\n自笑头颅如此，奈乌轮难系，驹隙如驰。\n慨壮图已矣，指地不须锥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15607, '八声甘州', '李曾伯', '仿离骚、览揆度新讴，空云霭乌丝。\n把长庚才调，小施筹笔，犹处囊锥。\n鸾枳滩发轫，指日问朝衣。\n雪片梅花外，已露南枝。\n休羡汉疏晋阮，记当年楚产，同是家儿。\n怅岁华如许，同官复同时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15608, '八声甘州', '李曾伯', '记当年、虏压顺昌城，直欲付靴尖。\n赖君家乃祖，笑麾白羽，净洗腥膻。\n荆州甘棠蔼蔼，浓墨宇犹鲜。\n少出拿云手，整顿青毡。\n好个嫩凉天气，想闻鸡听雁，意气犹。\n看相将喜事，眉色已黄占。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15609, '八声甘州', '李曾伯', '问孀娥、厌看人，唯复厌人看。\n正凉宵准拟，招延素魄，慰藉苍颜。\n廉纤梧桐细雨，吹彻玉箫寒。\n仿佛山河影，只在云端。\n又似去年今夕，枉教人愁怅，立尽阑干。\n想菱花尘匣，憔悴女乘鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15610, '朝中措', '李曾伯', '灯棋三载客边头。\n江汉等萍浮。\n一片白云关念，对床夜雨难留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15611, '朝中措', '李曾伯', '南风吹棹过吴头。\n聚散付云浮。\n且共一杯怀楚，须期万户封留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15612, '朝中措', '李曾伯', '夜来南极十分明。\n申月应生申。\n小范龙图老子，大苏玉局仙人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15613, '贺新凉・贺新郎', '李曾伯', '可恨经年别。\n正安排、剖瓜植竹，拟酬佳节。\n应为犁锄机杼懒，天遣阿香磨折。\n翻一饷、廉纤凄切。\n寂寞金针红线女，枉玉箫、吹断秦楼月。\n清漏静，楚天阔。\n东皋且愿三农悦。\n任从渠、鹊桥蛛网，一番虚设。\n挽取天河聊为我，尽洗西风残热。\n休懊恼、云生巫峡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15614, '贺新凉・贺新郎', '李曾伯', '晓听平安报。\n信荆州、古今形胜，金汤天造。\n落日岘山陈迹在，依旧大堤芳草。\n叹紫塞、黄尘未扫。\n水合水生来又去，赖胡雏、犹畏熊当道。\n薇柳戌，甚时了。\n乞身屡上盏天表。\n感恩深、丁宁帝语，许同芳召。\n自愧黔驴无伎俩，桑土绸缪盍早。\n空手袖、剑锋懊恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15615, '贺新凉・贺新郎', '李曾伯', '梦觉闻鸡报。\n问岘边、晋家城郭，旧邦新造。\n谁遣平明旌旆入，人说当年草草。\n犹幸把、腥埃俱扫。\n对越老苍方寸在，任酉渠、远度龙堆道。\n还又过，一春了。\n少年意气轻三表。\n到如今、名惭小范，功卑前召。\n赖有把茅归去是，乘此抽身须早。\n何苦受、天来烦恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15616, '醉蓬莱', '李曾伯', '问金城方略，数十年来，谁堪称许。\n万福威名，草木识淮浦。\n西顾天长，中流地重，著此巨鳌柱。\n见说棋边，风声鹤唳，胆落胡虏。\n老子家声，六韬亲授，渭水归来，非熊非虎。\n江汉滔滔，建大将旗鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15617, '醉蓬莱', '李曾伯', '自鹫峰曾见，金粟如来，犹有英烈。\n碧玉琅，点缀碎琼屑。\n不御纷华，独餐沆瀣，比众芳殊别。\n好向凉宵，无风无雨，宜露宜月。\n身在山中，名香天下，全似幽人，一种修洁。\n解使多愁，对此亦纾悦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15618, '醉蓬莱', '李曾伯', '问前身应在，香醉山中，今存风烈。\n佳夕招延，清论度飞屑。\n玉盈盈，金英点点，标格侬家别。\n好个凉天，更无滴雨，只欠些月。\n菊客兰兄，纷纷侪辈，纵尔芬芳，输我高洁。\n鼻观先知，羞取俗颜悦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15619, '醉蓬莱', '李曾伯', '大不逾粟许，飘散人间，直恁清烈。\n管领芳樽，底事不渠屑。\n中夜庭前，小山丛畔，韵度从来别。\n那更今年，留连秋色，将傍菊月。\n堪羡纱窗，胆瓶斜浸，浅酌低讴，人花双洁。\n恼杀多情，一见一回悦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15620, '醉蓬莱', '李曾伯', '指梅花雪片，问讯八窗，南枝开未。\n一点春风，消息岭头寄。\n太白精神，广平韵度，是岂众芳拟。\n东阁吟边，水清月淡，不妨游戏。\n犹记双湖，几番初度，持酒相期，已花为比。\n鼎味家传，须向玉堂里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15621, '沁园春', '李曾伯', '天顾坤维，持橐秉旄，屈公此行。\n正地雷观象，一阳将复，天星验数，五福初临。\n汉指才宣，蜀民相贺，百万耄倪犹更生。\n先声布，便胆寒西贼，关塞无尘。\n休嗟往事营营。\n要清献、乖崖相拟伦。\n看作新精采，叶符气运，转旋机括，元在人心。\n奖率三军，扫清万里，从此西南开太平。\n功成後，却归来廊庙，细展经纶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15622, '沁园春', '李曾伯', '老子家山，近古苏州，有监本呆。\n叹长途荷担，斯宜已矣，急湍鼓，岂不危哉。\n我爱陶潜，休官彭泽，为三径荒芜归去来。\n君恩重，奈边戈未偃，阃毂犹推。\n东南休运将回。\n幸天日清明公道开。\n把孤忠自许，我心匪石，一真难灭，人口如碑。\n青眼旧交，黑头新贵。\n快九万里风鹏背培。\n诗筒寄，正多情未已，聊解君颐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15623, '沁园春', '李曾伯', '我爱临川，簪绂丛林，有宅一区。\n记谢墩名字，百年犹在，平泉孙子，三世重居。\n皂盖新营，青毡旧识，此复古春秋宜大书。\n奇哉事，信当时种子，下到工夫。\n笑渠。\n驷马门闾。\n是几往过之凡几墟。\n喜尚存遗爱，甘棠在在，无穷生意，茂草如如。\n载酒寻盟，论诗结社，想田可秫兮园可蔬。\n应须念，古亭乔木，无恙还无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15624, '兰陵王', '李曾伯', '甚天色。\n苦问桃红李白。\n伊祈氏，沙际才归，依约春回晓烟湿。\n老寒犹煞忒。\n景物。\n中年惯识。\n天应遣，雨洗风梳，柳睡花眠尚无力。\n名园谩他适。\n任黄四栽培，殷七奇特。\n一年好处须寒食。\n待花畔携酒，酒边索句，春馀太半未须急。\n记旧隐幽寂。\n我亦。\n几时得。\n归检点苔封，评品梅格。\n教看林下休官一。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15625, '江神子・江城子', '李曾伯', '白妃卷絮逐风颠。\n透朱帘。\n向空漫。\n剪出冰花，偏爱腊前看。\n能费化工多少力，千万里，尽同天。\n歌楼清赏记当年。\n玉人占。\n绣衾寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15626, '浪淘沙', '李曾伯', '昨夜雨兼风。\n断送残红。\n老寒犹自著帘栊。\n为问香篝人语道，翠被还重。\n何处有疏锺。\n惊起匆匆。\n惜春休放酒杯空。\n芳草天涯寒食又，归兴尤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15627, '哨遍', '李曾伯', '天限长江，云扰中原，一局持棋势。\n汉将谁。\n盍为扫清之。\n彼伎犹、黔驴而止。\n客亦知。\n何材不生斯世。\n丁宁屡费君王旨。\n向马首论诗，灯前观剑，岂无差强人意。\n幸崆峒麦熟且休师。\n又焉用陈琳檄书飞。\n一笛楼头，万柳营间，从容麾帜。\n噫。\n代有戎夷。\n时贤患乏经纶志。\n紫岩公一出，敌当惊见花字。\n谩被发忧邻，汗颜笑斩，客邪终岂婴元气。\n待拜表盏天，移文问隐，老夫行且归矣。\n怕胡雏穴隙尚相窥。\n有淝水儿曹举兵麾。\n看中兴、隽烈堪继。\n随世样多能底。\n卿自为卿计。\n不妨老子，婆娑矍铄，从渠屦盈户外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15628, '兰陵王', '李曾伯', '问梁益。\n天设金城铁壁。\n西风外，依约雁来，还报关山旧秋色。\n三秦听汉檄。\n远恨绵绵脉脉。\n频年事，虚掷桑阴，允诸人竟何策。\n彤弓误殊锡。\n怅活国难医，救世须佛。\n平生本藉毛锥力。\n对弧矢初度，满头白发，何堪兵卫叠画戟。\n咄青史陈碛。\n酒石。\n羡王绩。\n任击缶呼天，此乐何极。\n奚须太息惊前席。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15629, '八声甘州', '李曾伯', '问西陵、治比汉河南，若为遽东归。\n正峡江衮衮，中流我共，一楫杭之。\n倏听攀辕告语，公去裤襦谁。\n赖有甘棠在，人口如碑。\n百尺楼头徒倚，记绸缪桑土，几对灯棋。\n指鹭洲何处，心事想鸥知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15630, '水调歌头', '李曾伯', '序正象古琥，吉叶梦维熊。\n身随金粟出世，香满小山丛。\n铁券丹书家世，朱阁青毡步武，名字在尧聪。\n雕鹗健云翮，聊尔待西风。\n功名事，书剑里，笑谈中。\n江涛衮衮如此，天岂老英雄。\n先我甲庚三日，伴子春秋千岁，何幸举樽同。\n歌以寿南涧，愿学稼轩翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15631, '临江仙', '李曾伯', '同此三秋端正月，地高先得光辉。\n分明身世玉琉璃。\n不妨人未老，长与月相期。\n我有芳尊共玩事，从渠魏鹊无枝。\n直须饮到五更时。\n大家眠玉界，莫羡宴瑶池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15632, '水龙吟', '李曾伯', '楚乡三载中秋，倚楼辄值萧萧雨。\n澄空向午，廉纤数点，又疑虚度。\n卷起云鬟，掣开妆鉴，喜瞻眉宇。\n问常娥丰貌，间何阔矣，元不老、只如故。\n见了悄然无语。\n但令人、不堪怀古。\n老蟾应记，旧时人物，孙刘陶庾。\n俯仰皆空，阴晴何恨，芳樽频举。\n问他年，忆取今宵，人如许、月如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15633, '水调歌头', '李曾伯', '可爱十分月，都无一点云。\n清光是处皆有，浑不许人分。\n独是大江深处，一片水晶世界，仿佛有微痕。\n坐到夜深际，万籁寂无闻。\n与诸君，同一笑，举芳樽。\n素娥自有佳约，何必命红裙。\n顷刻参横斗转，归去华胥一觉，玩事任纷纷。\n我袖有玉斧，当为整乾坤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15634, '眼儿媚', '李曾伯', '公归东里我西州。\n枫荻楚天秋。\n乌樯转首，暮云江树，落日沙头。\n瞿唐此去风涛恶，宁愿贾胡留。\n明年春晚，松江笠泽，归约追游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15635, '大', '李曾伯', '对剑花凝，笳叶卷，天宇尘清声肃。\n楼船催解处，正日戈夕照，风旗西矗。\n虎战龙争，人非地是，形势昔雄三国。\n景升今何在，怅婆娑老子，奚堪荆牧。\n岂自古常言，力宁斗智，智宁如福。\n西征非太速。\n奈臣职、难负君王嘱。\n嗟往事、祁山抗表，剑阁刊铭，祗成堕甑并空轴。\n喜听平安信，岂止为、区区一竹。\n蚊类、笑谈逐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15636, '浪淘沙', '李曾伯', '斜日挂汀洲。\n帆影悠悠。\n碧云合处是吴头。\n几片寒芦三两雁，人立清秋。\n柳外莫停舟。\n休问闲愁。\n人生江海一萍浮。\n世路相期如此水，万里安流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15637, '八声甘州', '李曾伯', '上巍楼、指顾剑东西，依然旧江山。\n怅谁为荆棘，委渠天险，薄我风寒。\n金瓯经营几载，鸿雁尚漂残。\n一片迷棋局，著手良难。\n犹幸红旗破贼，有竹边新报，喜听平安。\n问纷纷遗事，一笑付凭栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15638, '满江红', '李曾伯', '才过新正，能几日、海棠开了。\n将谓是、睡犹未足，嫣然何笑。\n一片殷红新锦样，天机知费春多少。\n更芳期、不待燕黄昏，莺清晓。\n花旧说，南昌好。\n花宜占，东风早。\n想香霏地近，融和偏巧。\n佳句流传千古在，石湖不见坡翁老。\n倩何人、寄驿报家山，教知道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15639, '满江红', '李曾伯', '自入春来，花信费、几番风了。\n先付与、红妆万点，苍颜一笑。\n旧说沈香亭北似，今虽濯锦江头少。\n最可人、枝上月笼春，烟含晓。\n亨会称，花王好。\n嘉聘惜，梅兄早。\n对芳容细玩，天然新巧。\n羯鼓不须催太甚，霓裳易散梨园老。\n任杜鹃、犹自殿韶华，呼殷道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15640, '谒金门', '李曾伯', '风又雨。\n芳事葱葱如旅。\n借问甚时才百五。\n东君浑弗顾。\n红紫园林几许。\n横笛数声何处。\n桃涨连天归未去。\n客和春且驻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15641, '谒金门', '李曾伯', '春且驻。\n休惜残红无主。\n柳色青青还未絮。\n牡丹犹待雨。\n金鸭沈烟一缕。\n人在纱窗觅句。\n仿佛家山三月暮。\n隔帘闻燕语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15642, '水调歌头', '李曾伯', '今岁渝州热，过似岭南州。\n火流石铄如傲，尤更炽於秋。\n竟日襟常沾汗，中夕无停手，几至欲蕉头。\n世岂乏凉境，老向此山囚。\n赖苍灵，怜赤子，起龙秋。\n刹那顷耳，天瓢倾下足西畴。\n荡涤两间炎酷，苏醒一番枯槁，民瘼庶其廖。\n清入诗脾里，一笑解吾忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15643, '水调歌头', '李曾伯', '两岁是六帙，万里客他州。\n一眉新月西挂，又报桂花秋。\n想见吴中稚子，已办秫田数顷，更种橘千头。\n堪笑新亭酒，空效楚人囚。\n饭甘粗，衣任恶，卧从湫。\n世缘道眼看破，闻早问先畴。\n这服清凉散子，多在病坊弗悟，美甚时瘳。\n膏秣归盘去，无乐亦无忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15644, '沁园春', '李曾伯', '雪山有缘，白首重来，信不偶然。\n怅怆凄未洗，平戎何策，英灵不绝，赖蜀多贤。\n耆旧二三，甲兵百万，力障狂澜回巨川。\n秋声静，共巍楼把酒，自足筹边。\n何人为我盏天。\n焉用此客星留井躔。\n正柴桑栗里，稻肥蟹健，松江笠泽，莼美鲈鲜。\n百计求闲，一归未得，便得归闲能几年。\n持公赋，待後堂新唱，夸语彭宣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15645, '一剪梅・一翦梅', '李曾伯', '人生能有几中秋。\n人自多愁。\n月又何愁。\n老娥今夜为谁羞。\n云意悠悠。\n雨意悠悠。\n自怜踪迹等萍浮。\n去岁荆州。\n今岁渝州。\n可人谁与共斯楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15646, '沁园春', '李曾伯', '晚出千林，中立三秋，清哉此花。\n自鹫峰移下，碎成玉屑，蟾宫分到，缀作金葩。\n粟许来微，薰天声价，较楚蕙庾梅还韵些。\n真奇处，但餐沆瀣，不染繁华。\n酒边一笑婆娑。\n疑香醉山中尊者家。\n怅尘埃俗状，强颜羞对，风骚墨客，乐事堪夸。\n月照才清，露浓尤馥，饮待夜深应更佳。\n姑容我，胆瓶斜插，卧看窗纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15647, '沁园春', '李曾伯', '一种孤，四出清芬，半秋始花。\n只些儿肌骨，才逾一芥，许多韵度，迥压群葩。\n得雨相催，随风所到，较七里山樊尤远些。\n纷纷辈，笑渠侬桃李，徒竞春华。\n试容老子婆娑。\n恍身在广寒仙子家。\n任殷勤唤酒，恣从君赏，徘徊待月，剩向人夸。\n我有家林，旧栽岩壑，得归去相延方是佳。\n姑先约，拼共横船玉，教堕巾纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15648, '水龙吟', '李曾伯', '江头雨过黄花，片帆催向春闱去。\n两年共我，风舟问峡，霜砧闻楚。\n定远从军，兹恩策第，岂堪同语。\n谩咨嗟人事，分明天意，广寒阙、待平步。\n健笔凌云如许。\n看新年、榜登龙虎。\n转头却笑，弓刀塞上，粗官何取。\n海阔鹏搏，途穷马老，不胜离绪。\n过旧游、人问征夫，烦为说、戌边苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15649, '水龙吟', '李曾伯', '天涯舍我先归，还知我以何时去。\n浮生萍梗，南辕北旆，之吴之楚。\n岂偶然哉，祗堪一笑，无庸多语。\n向临歧赋别，丁宁祝望，竿百尺、进一步。\n其奈头颅如许。\n更藩篱、穴犹据虎。\n良机一失，付之谁手，探囊堪取。\n君对天庭，上咨西事，历陈条绪。\n问相如、汉指来宣，果何益、亦何苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15650, '沁园春', '李曾伯', '二十年间，黄州竹楼，共酬好春。\n记淮江表，群贤毕集，清明上巳，二美相并。\n一枕黄粱，满头白发，屈指旧游能几人。\n堪嗟处，怅光阴易老，犹困西尘。\n今朝又值良辰。\n空想像、长安天气新。\n问兰亭癸丑，雪堂壬戌，倏成畴昔，将似来今。\n觞泛流泉，茗烹新火，领略韶华聊啸吟。\n鹦洲去，有故人相问，为语归音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15651, '沁园春', '李曾伯', '咄咄衰翁，向羽书中，又过一春。\n正老怀梦想，扁舟访剡，壮图惭负，万里城并。\n溟翼之上，冀群空矣，自此阳关无故人。\n岷江路，忆一番风浪，三月烟尘。\n美哉乐事良辰。\n正好趁东门官柳新。\n且舒晴慷慨，何须感旧，转头解后，未必犹今。\n问讯南楼，劳还西戌，君为楚歌侬越吟。\n眉黄近，怕洛涯催出，便有佳音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15652, '沁园春', '李曾伯', '万里戌边，八载去家，始遂一归。\n怅中年早历，虎头兵幕，平生屡建，豹尾神旗。\n岂得闲身，毋庸多议，感荷九重渊听知。\n当时事，似狂澜欲倒，孰障东之。\n天教狂虏灰飞。\n更莫问儿郎存血衣。\n把雪裘霜帽，绝交楚徼，雨蓑风笠，投老吴矶。\n径与松荒，人同鹤在，交友晓天星样稀。\n从今去，共麴生相约，愿乐清时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15653, '沁园春', '李曾伯', '极目江涛，不有人焉，其能国乎。\n伟故家风烈，激扬手段，平生践履，精密工夫。\n冰漕功成，月卿召入，小却犹当登从涂。\n斯行也，非纪网省闼，定引京都。\n猗欤。\n愿疾其驱。\n弹指顷暑收秋又初。\n向玉阶芳寸，亲承温问，金成十二，细述嘉谟。\n苕船边，藕花香里，念人在洞庭青草湖。\n它年事，约携东老酒，附洛英图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15654, '沁园春', '李曾伯', '天目山房，洪崖老仙，亲授一灯。\n自檄草参筹，宾筵领袖，鼎梅助味，省闼权衡。\n华国文章，立朝风力，犹有老成人典刑。\n如公样，盍夜趋宣室，昼对延英。\n乘轺惠我湘民。\n作翼轸中间一福星。\n正千飕漕玉，张颐西峤，单车把绣，将指南闽。\n过阙留中，历阶而上，方值汉朝更化新。\n南中事，若君王问及，老弗能胜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15655, '满江红', '李曾伯', '明日生初，还知否、明年六十。\n嗟老矣、满头都缟，寸心犹赤。\n三十载间尘土债，几千里外风涛役。\n赖君天、许放故山归，恩无极。\n出而作，入而息。\n美可茹，鲜可食。\n任浩书空咄，禹笑人寂。\n断国谋王非我事，抱孙弄子聊吾适。\n且从今、时复一中之，杯中物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15656, '满江红', '李曾伯', '今岁潇湘，真个见、嘉平三白。\n圜里、无非和气，不知寒色。\n宇宙幻成清净境，了无一点红尘入。\n问太空、此瑞自何来，君王德。\n歌笑是，兔园客。\n辛苦是，鹅池役。\n任谢家儿女，赋嘲纷出。\n洗尽腥膻空万里，屏除螟深千尺。\n向此时、何以对梅花，呼欢伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15657, '满江红', '李曾伯', '蝶梦惊残，仿佛似、东方才白。\n人报道、城疑不夜，界几无色。\n敲瓦微听冰线响，开窗倏放风花入。\n拥重貂、曾不觉寒侵，将何德。\n呼剡棹，行为客。\n平蔡垒，何能役。\n算争如、穷檐高卧，闭门毋出。\n安得松江江上去，一蓑独钓丝千尺。\n要不持、寸铁和前修，文章伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15658, '满江红', '李曾伯', '立雪寒窗，照肝胆、了然明白。\n浑似得、齐宫气象，郢楼颜色。\n天籁无声随物应，阳春有脚从中入。\n与邦人、稽首谢天工，元冥德。\n人正作，潇湘客。\n谁谓有，蓝关役。\n对江天暮景，鹅溪描出。\n银浪卷飞鸥一片，玉枝擎重龙千尺。\n羡联镳、曾作岳峰游，前方伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15659, '满江红', '李曾伯', '把绣成吟，真压倒、古之元白。\n佳句有、雪车冰柱，曾无衿色。\n一点不留烟火气，时脾时有清风入。\n更岭边、多少活人恩，于公德。\n公自是，朝天客。\n应笑我，为人役。\n看时犹多事，公须一出。\n琅腹细披忠抱寸，龙颜密侍天威尺。\n借笔端、从此润皇猷，翰林伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15660, '满江红', '李曾伯', '听彻惊乌，起览镜、顿添头白。\n曾不见、江南人寄，一枝春色。\n风卷龙鳞残甲下，山无虎迹新蹄入。\n罄冰天、桂海使同风，修文德。\n三十载，江湖客。\n千万里，关山役。\n且付之杯酒，何愁西出。\n天女花边浑似剪，志公杖上平如尺。\n把富贫、都作一般看，何什伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15661, '满江红', '李曾伯', '草草春盘，那敢赋、丝青玉白。\n湘波动、雁怀归思，柳催行色。\n冻逐寒梢残雪解，暖随野烧轻烟入。\n举人间、无物不光辉，东皇德。\n莺燕报，朱门客。\n乌兔老，红尘役。\n羡翠轺多暇，彩花新出。\n捧日东城行应制，去天只隔城南尺。\n趁五更、桦烛向端闱，班常伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15662, '满江红', '李曾伯', '春日何来，深雪里、南枝先白。\n伊祈氏、一番陶冶，千林色香。\n弱柳眼回青尚浅，小桃腮晕红将入。\n笑渠侬、剪彩与裁花，夸闺德。\n九十日，春还客。\n数千里，官为役。\n看时来、雁随云去，鱼从冰出。\n一脉流通天造化，三杯扶植身关尺。\n对东皇、太乙续离骚，需词伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15663, '满江红', '李曾伯', '万紫千红，都不似、玉奴一白。\n三数萼、有冰霜操，无脂粉色。\n长共竹君松友伴，岂容蝶使蜂媒人。\n似惠和、伊任与夷清，兼三德。\n能洁已，能娱客。\n成子後，调羹役。\n更岁寒风味，时然後出。\n春浅吹回羌管寸，夜阑吟费花笺尺。\n炯使皇、两两月黄昏，真诗伯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15664, '贺新郎', '李曾伯', '岭蜀天涯路。\n忆前年、担簦西上，旌麾南去。\n谁谓潇湘还解后，重对灯前笑语。\n挺乔木、森森犹故。\n梅外柳边官事了，记牢之、曾著元戎府。\n聊访问，旧游处。\n酒边不用伤南浦。\n为亭、百年门户，正烦宗主。\n见说君王方旰食，借箸哺应为吐。\n这官职、二郎须做。\n若见时贤询小阮，愿早携、耕春雨。\n嗟矍铄，恐迟暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15665, '贺新郎', '李曾伯', '日近长安路。\n喜骖鸾、带簪游戏，弓旌招去。\n闻道汉朝帷帏里，要问隅蛮语。\n嗟时事、尚兹多故。\n办取忠谋宜入告，见石洪、曾在乌公府。\n须细访，风寒处。\n左荆右岭中湘浦。\n愿扶持、东南温厚，老天张主。\n翘馆钦贤人共说，一饭每勤三吐。\n公此去、好官须做。\n从臾泾舟同共济，更绸缪、桑土先阴雨。\n灭此虏，直朝暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15666, '贺新郎', '李曾伯', '老作星沙守。\n问今年、平头六十，翁还知否。\n暑葛霜砧都历遍，还著回旋舞袖。\n奚所用、皤然一叟。\n欲觅金丹驻颜色，纵铁鞋、踏破终无有。\n空自诧，不龟手。\n西风又近中秋候。\n记相将、桂华开未，月儿圆又。\n弧矢四方男子事，争奈灰心也久。\n何以报、国恩深厚。\n了却宫痴归去好，有竹窗、蓬户生涯旧。\n姑一笑，付杯酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15667, '贺新郎', '李曾伯', '问讯南州守。\n怅吾生、今非昔比，後犹今否。\n涉尽风涛凭个甚，一瓣心香在袖。\n人竞说、顽哉此叟。\n识破荣途皆幻境，只形骸、已累它何有。\n姑勉尔，应之手。\n休烦太卜勤占候。\n怕漂零、江湖易老，光阴难又。\n兔魄初生人初度，期共婵娟长久。\n赖此月、於人犹厚。\n燕颔封侯非我事，早携书、归卧吾庐旧。\n渝此约，有如酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15668, '水调歌头', '李曾伯', '宵旰轸先虑，岭海屈真儒。\n金城素有奇略，不待至才图。\n春满洲鹦楼鹤，天付簪山带水，驷马驾轻车。\n六月正炎热，吾肯缓吾驱。\n越蓬婆，逾邛，彼穹庐。\n其能涉我烟瘴，载籍以来无。\n联络五溪百粤，托柱南方半壁，中外保无虞。\n了此经营事，归去位钧枢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15669, '水调歌头', '李曾伯', '洞庭千古月，湘水一天秋。\n凉宵将傍三五，玩事若为酬。\n人立梧桐影下，身在桂花香里，疑是玉为州。\n宇宙大圆镜，沆瀣际空浮。\n傍谯城，瞻岳麓，有巍楼。\n不妨举酒，相与一笑作遨头。\n人已星星华发，月只团团素魄，几对老蟾羞。\n回首海天阔，心与水东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15670, '水调歌头', '李曾伯', '佳月四时有，举世重中秋。\n金明水秀竞爽，互古景难酬。\n爝火繁星退敛，桂海冰天洞照，清影遍神州。\n万象自妍丑，一鉴碧虚浮。\n昔苏张，夸玉界，赋琼楼。\n素娥阅人多矣，不怕雪添头。\n只恐参横斗转，还又酒阑歌散，醉态醒堪羞。\n安得真仙术，兔魄驻西流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15671, '水调歌头', '李曾伯', '敢问辽天月，历几亿春秋。\n老娥盍相刮目，无一语相酬。\n似讶经年间阔，类笑衰翁潦倒，岁岁客他州。\n清照五湖阔，倦影一萍浮。\n任渠侬，琴当户，酒当楼。\n人生适意，封君何似橘千头。\n月正圆时固好，人欲闲时须早，毋作陇西羞。\n多谢锦囊句，椽笔富清流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15672, '水调歌头', '李曾伯', '问讯中秋月，瞥见一眉弯。\n婆娑桂影，今年又向桂林看。\n蓬天桑弧初度，罗带玉簪旧识，俯仰十年间。\n记得老坡语，颓景薄西山。\n碧虚人，应笑我，已苍颜。\n岁寒耿耿，不改惟有寸心丹。\n目断风涛万里，梦绕烟霞一壑，老矣甚时闲。\n不愿酒泉郡，愿入玉门关。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15673, '木兰花慢', '李曾伯', '渐吾乡秋近，正莼美、更鲈肥。\n顾安得相从，征帆衔尾，飞盖追随。\n南中眼前事势，正相持、边腹一枰棋。\n将谓灯明月暗，笑谈共和韩诗。\n谁知。\n催上王畿。\n无计可，挽留之。\n想翠微深处，倚楼日望，天际人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15674, '沁园春', '李曾伯', '六十衰翁，更加二龄，此何等时。\n不退寻岩壑，相安耕钓，重来岭峤，犹事驱驰。\n绝类文渊，当年矍铄，上马据鞍奚所为。\n偏怜处，是难堪潦雾，水际鸢飞。\n云台铜柱空题。\n奈床下伊人心素疑。\n自古来如此，只须付酒，风光纵好，勿复言诗。\n莼菜美时，桂花香里，所愿少须臾乐之。\n西风外，喜羽书夜静，即是归期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15675, '满江红', '李曾伯', '今岁垂弧，欲自寿、一辞莫措。\n何可拟、翁头如雪，香山白傅。\n首夏一番罹重病，去秋数月撄狂虏。\n赖天公、肯为保馀生，逢初度。\n今幸释，千钧负。\n尤可喜，归田去。\n但蹒跚勃，龙锺如许。\n薇柳诸关成底事，菊松三径犹堪主。\n办篮舆、尚可檄渔樵，盟鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15676, '水龙吟', '李曾伯', '西风涤尽炎，连朝更值天无雨。\n笋舆轧轧，经行三日，碧无数。\n胜绝江山，余行天下，无如此处。\n任今来昔往，迎新送旧，风景在、只如许。\n谁谓阴山骄虏。\n去年冬、敢侵吾土。\n哀哀鸿雁，一番荡析，幸逢多黍。\n拜表出师，安南定北，岂无忠武。\n嗟病夫、老矣无能，促归棹，舣江渚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15677, '水调歌头', '李曾伯', '昨夜虽三五，宝鉴未纯全。\n今宵既望，兔魄才是十分圆。\n又得平滩系缆，冷浸玻璃千顷，表里一壶天。\n扶惫蓬窗下，拼却夜深眠。\n想嫦娥，应笑我，鬓苍然。\n平生修玩，犹记历历旧山川。\n安得乘槎访斗，问讯广寒宫殿，怅未了尘缘。\n愿赐长生药，换我骨为仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15678, '八声甘州', '李曾伯', '数年来、揆度在南州，今年在家山。\n叹平生踪迹，荆淮岭蜀，多少间关。\n幸对园林花竹，一笑且团栾。\n莫忆西风梦，驰志楼兰。\n赢得维摩多病，奈鬓毛剥落，步武蹒跚。\n神仙何处，遗我以金丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15679, '水龙吟', '李曾伯', '此花迥绝他花，湘中不减吴中盛。\n疑从太华，分来岳麓，根玉井。\n炬列千红，盖擎万绿，织成云锦。\n向壶天清暑，风梳露洗，尘不染、香成阵。\n好似一番雨过，似轻鬟、晚临妆镜。\n阿环浴罢，珠横翠乱，芳肌犹润。\n载月同游，隔花共语，酒边清兴。\n问六郎、凝伫多时，公不饮、俗几甚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15680, '八六子', '郑熏初', '忆南洲。\n绀波萦绕，垂杨翠拂朱楼。\n念十载风流梦觉，满身花影人扶，旧曾暗游。\n无言空怆离忧。\n醉袖将红泪，吟笺写许清愁。\n试与问、杨琼解怜郎否，也应还是，旧家身价，而今艳质不来眼底，柔情终在心头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15681, '乌夜啼', '郑熏初', '春江一望微茫。\n辨桅樯。\n无限青青麦里、菜花黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15682, '氐州第一', '郑熏初', '开遍来禽，春事过也，江南倦客心苦。\n料理花愁，销磨酒病，还是年时意绪。\n寒浅香轻，早一霎、朝来微雨。\n柳曲闻莺，河桥信马，旋题新句。\n漫道而今无贺铸。\n尽肠断、满帘飞絮。\n说似风流，除非小杜，妙绝夸能赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15683, '一萼红', '郑熏初', '忆燕台。\n正倚帘吹絮，小立望郎来。\n管调丝，涂妆绾髻，密意曾托蜂媒。\n空恁误、湔裙暗约，最无奈、好梦易惊回。\n想见而今，浅颦双翠，沁破妆梅。\n沈带悄然宽尽，恨年时行处，红糁苍苔。\n前事重寻，幽欢难偶，钿合空委鸾钗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15684, '瑞鹤仙', '余', '怪新来瘦损。\n对镜台、霜华零乱鬓影。\n胸中恨谁省。\n正关山寂寞，暮天风景。\n貂裘渐冷。\n听梧桐、声敲露井。\n可无人、为向楼头，试问塞鸿音信。\n争忍。\n勾引愁绪，半掩金铺，雨欺灯晕。\n家僮困卧，呼不应，自高枕。\n待催他、天际银蟾飞上，唤取嫦娥细问。\n要乾坤，表里光辉，照予醉饮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15685, '如梦令', '赵崇', '日日酒围花阵。\n画阁红楼相近。\n残月醉归来，长是雨羞云困。\n低问。\n低问。\n独自绣帏睡稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15686, '如梦令', '赵崇', '窗外燕娇莺妒。\n窗下梦魂无据。\n梦好却频惊，不到彩云深处。\n无绪。\n无绪。\n红重一帘花雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15687, '更漏子', '赵崇', '玉搔头，金约臂。\n娇重不胜残醉。\n留粉黛，晕胭脂。\n浅寒生玉肌。\n待归来，浑未准。\n疑杀那回书信。\n春又好，思无穷。\n卷帘花露浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15688, '谒金门', '赵崇', '春尚浅。\n江上柳梢风软。\n销尽玉梅春不管。\n冷香和梦远。\n脉脉绿窗新怨。\n花胜无心重翦。\n帘押护香闲不卷。\n卷帘芳事遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15689, '谒金门', '赵崇', '春意泄。\n香重一枝梅雪。\n寒透玉壶冰暗结。\n玉奴情更劣。\n似语还羞奇绝。\n妒白怜红时节。\n酒力未醒双眼缬。\n一帘风弄月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15690, '谒金门', '赵崇', '晴意早。\n帘外数声啼鸟。\n有约不来春梦杳。\n琐窗微弄晓。\n江上残梅未扫。\n叶底芳桃红小。\n天远断云尘不到。\n过春还草草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15691, '谒金门', '赵崇', '春意薄。\n江上晚来风恶。\n帘外海棠花半落。\n睡深浑未觉。\n梦想当年行乐。\n新恨暗添金鹊。\n写就金笺无处托。\n去鸿天一角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15692, '清平乐', '赵崇', '莺歌蝶舞。\n池馆春多处。\n满架花云留不住。\n散作一川香雨。\n相思夜夜情。\n青衫泪满啼红。\n料想故园桃李，也应怨月愁风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15693, '清平乐', '赵崇', '妒红欺绿。\n轻浪潮温玉。\n鸾袖卷香金。\n娇怯未消寒粟。\n锦衾初罢承欢。\n宿妆微褪香弯。\n醉眼乍松还困，断云犹绕巫山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15694, '南柯子・南歌子', '赵崇', '丝发风轻掠，酥胸冷不侵。\n背人小立卸瑶簪。\n一缕柔情、系得几人心。\n曲槛花方蓓，荷桥柳未阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15695, '南柯子・南歌子', '赵崇', '掩笑轻抬袖，慵妆浅画眉。\n嫩晴帘箔玉梅飞。\n门外寒轻、疏柳趁黄时。\n绾带香罗结，交叉绿玉枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15696, '望海潮', '赵崇', '轻云过雨，炎晖初减，楼台片片馀霞。\n曲径通幽，小阑斜护，水天薄暮人家。\n暝色趣归鸦，竹风交立玉，清透窗纱。\n断岸涟漪，乱萍芳苇绕烟沙。\n依稀画艇莲娃。\n掩鲛绡微沁，急桨咿哑。\n香雾霏微，冷光摇曳，娅红深映低花。\n天际玉钩斜。\n矶边菱唱答，惊断鸣蛙。\n满棹白苹归去，幽兴绕天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15697, '沁园春', '赵崇', '紫陌芳尘，烟缕收寒，雨丝过云。\n羡交阴桃叶，窗前曲槛，认巢燕子，柳底朱门。\n回首年时，雾鬟风袖，袅袅娉娉娇上春。\n逢迎处，尽芳华缱绻，玉佩殷勤。\n谁知此际销魂。\n漫隐约人前笑语温。\n记掌中纤细，真成一梦，花时怨忆，应为双文。\n载酒心情，教眉诗句，空悔风流曾误人。\n凭谁去，待寄将恨事，两处平分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15698, '摸鱼儿', '赵崇', '卷珠帘、几番花信。\n轻寒犹自成阵。\n一年芳事如朝梦，容易绿深红褪。\n寒食近。\n惟自有、断肠垂柳禁春困。\n琐窗深静。\n悄叠损缕衣，凝尘暗掩，金斗熨清润。\n章台恨。\n准拟芳期未稳。\n旧游细把重忖。\n鉴鸾钗凤平分久，留取年时心印。\n谁与问。\n待试写花笺，密寄教郎认。\n妒香怜粉。\n欲写却还羞，轻颦浅叹，字字揽方寸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15699, '过秦楼', '赵崇', '隐枕轻潮，拂尘疏雨，幽梦似真还断。\n莺雏燕婉，依约年时，花下试翻歌扇。\n憔悴鬓怯春寒，慢掠轻丝，柳风如箭。\n甚阳台渺邈，行云无准，楚天空远。\n应唤觉、当日琴心，祗今诗思，惆怅客衣尘染。\n钗留股玉，袜袭钩罗，荏苒腻寒香变。\n问讯多情，别後笑巧颦娇，对谁长倩。\n但晚来江上，眼迷心想，越山两点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15700, '归朝欢', '赵崇', '翠羽低飞帘半揭。\n宝簟牙床凉似雪。\n窗虚云母澹无风，隔墙花动黄昏月。\n玉钗鸾坠发。\n盈盈白露侵罗袜。\n记逢迎，鸿惊燕婉，灯影弄明灭。\n蜀雨巫云愁断绝。\n罗带同心留绾结。\n交枝红豆雨中看，为君滴尽相思血。\n染衣香未歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15701, '恋绣衾', '赵崇', '江烟如雾水满汀。\n早梅花、偏占浅清。\n倚翠竹、寒无力，想潇湘、斜日暮云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15702, '蝶恋花', '赵崇', '一翦微寒禁翠袂。\n花下重开，旧燕添新垒。\n风旋落红香币地。\n海棠枝上莺飞起。\n薄雾笼春天欲醉。\n碧草澄波，的的情如水。\n料想红楼挑锦字。\n轻云淡月人憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15703, '菩萨蛮', '赵崇', '桃花相向东风笑。\n桃花忍放东风老。\n细草碧如烟。\n薄寒轻暖天。\n折钗鸾作股。\n镜里参差舞。\n破碎玉连环。\n卷帘春睡残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15704, '金明池', '赵崇', '桂海云蒸，瘴山雾暖，片雪何曾到地。\n羡长日、岛仙清暑，自学得、剪冰裁□。\n把岁寒、五出工夫，别妆点薰风，尽成清致。\n尽虹雨翻晴，暮霞焦土，一种凄凉如洗。\n酝藉丰标浑无比。\n应似惜、潇湘蕙疏兰弃。\n纵未入、众芳题品，终自倚、一涯风味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15705, '满江红', '方岳', '说与梅花，且莫道、今年无雪。\n君不见、秋崖鬓底，茎茎骚屑。\n笔砚只催人老大，湖山不了诗愁绝。\n问、何事下矶来，抛云月。\n重省起，西山芴。\n终负却，东山屐。\n把草堂借与，鹭眠鸥歇。\n乌帽久闲苍藓石，青衫今作枯荷叶。\n笑人间、万事竟何如，从吾拙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15706, '满江红', '方岳', '且问黄花，陶令後、几番重九。\n应解笑、秋崖人老，不堪诗酒。\n宇宙一舟吾倦矣，山河两戒天知否。\n倚西风、无奈剑花寒，虬龙吼。\n江欲，谈天口。\n秋何负，持螯手。\n尽石鳞芜没，断烟衰柳。\n故国山围青玉案，何人印佩黄金斗。\n倘只消、江左管夷吾，终须有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15707, '满江红', '方岳', '苍石横筇，松风外、自调龟息。\n浑不记、东皋秋事，西湖春色。\n底处未嫌吾辈在，此心说与何人得。\n向海棠、烂醉过清明，酬佳节。\n君莫道，江鲈忆。\n吾自爱，山泉激。\n尽月明夜半，杜鹃声急。\n人事略如春梦过，年光不啻惊弦发。\n怕醒来、失口问诸公，今何日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15708, '水调歌头', '方岳', '左手紫螯蟹，右手绿螺杯。\n古今多少遗恨，俯仰已尘埃。\n不共青山一笑，不与黄花一醉，怀抱向谁开。\n举酒属吾子，此兴正崔嵬。\n夜何其，秋老矣，盍归来。\n试问先生归否，茅屋欲生苔。\n穷则箪瓢陋巷，达则鼎彝清庙，吾意两悠哉。\n寄语雪溪外，鸥鹭莫惊猜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15709, '水调歌头', '方岳', '秋雨一何碧，山色倚晴空。\n江南江北愁思，分付酒螺红。\n芦叶蓬舟千重，菰菜莼羹一梦，无语寄归鸿。\n醉眼渺河洛，遗恨夕阳中。\n苹洲外，山欲暝，敛眉峰。\n人间俯仰陈迹，叹息两仙翁。\n不见当时杨柳，只是从前烟雨，磨灭几英雄。\n天地一孤啸，匹马又西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15710, '水调歌头', '方岳', '醉我一壶玉，了此十分秋。\n江涛还此，当日击楫渡中流。\n问讯重阳烟雨，俯仰人间今古，此意渺沧洲。\n天地几今夕，举白与君浮。\n旧黄花，新白发，笑重游。\n满船明月犹在，何日大刀头。\n谁跨扬州鹤去，已怨故山猿老，借箸欲前筹。\n莫倚阑干北，天际是神州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15711, '满江红', '方岳', '甓社有明月，夜半吐光寒。\n淮南草木飞动，秀出斗牛间。\n自有秦沙以後，试问少游而下，谁卷入毫端。\n补衮仲山甫，冰雪照云寰。\n霄汉近，绣衣去，锦衣还。\n江南且为梅醉，莫道岁将阑。\n三百六旬欲换，五百岁终才始，月月两循环。\n酌彼金错落，浇此碧琅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15712, '水调歌头', '方岳', '明日又重午，搀借玉蒲香。\n劝金且尽杯酒，听我试平章。\n时事艰难甚矣，人物眇然如此，骚意满潇湘。\n醉问屈原子，烟水正微茫。\n溯层峦，浮叠嶂，碧云乡。\n眼中犹有公在，吾意亦差强。\n胸次甲兵百万，笔底天人三策，堪补舜衣裳。\n要及黑头耳，霖雨趁梅黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15713, '水调歌头', '方岳', '剡曲一篷月，乘兴到人间。\n蓬莱山在何处，鹤骨不禁寒。\n胸有云门禹穴，笔有禊亭晋帖，风露洗脾肝。\n秋入紫宸殿，磨玉写琅。\n问何如，趋琐闼，系狨鞍。\n江涛今已如此，可奈寸心丹。\n我宋与天无极，公寿如春难老，王气自龙蟠。\n勋业付浯石，留与世人看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15714, '水调歌头', '方岳', '宇宙一杯酒，暝色倚重湖。\n青山杳杳何处，烟水泻愁予。\n别岸风涛喷薄，半夜鱼龙悲啸，能撼我诗无。\n李白醉不醒，唤起问何如。\n是耶非，天莽苍，雪模糊。\n苍颜白发如此，空复笑今吾。\n寄语鹭朋鸥侣，好在风餐水宿，底处不烟芜。\n吾亦从此逝，从我者谁欤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15715, '沁园春', '方岳', '尽为春愁，尽劝春归，直恁恨深。\n况雨急黄昏，寒欺客路，月明夜半，人梦家林。\n店舍无烟，楚乡寒食，一片花飞那可禁。\n小凝伫，黯红蔫翠老，江树阴阴。\n汀洲杜若谁寻。\n想朝鹤怨兮猿夜吟。\n甚连天芳草，凄迷离恨，拂帘香絮，撩乱深心。\n汝亦知乎，吾今倦矣，瓮有馀春可共斟。\n归来也，问渊明而後，谁是知音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15716, '沁园春', '方岳', '岁在永和，癸丑暮春，修禊兰亭。\n有崇山峻岭，茂林修竹，清流湍激，映带山阴。\n曲水流觞，群贤毕至，是日风和天气清。\n亦足以，供一觞一咏，畅叙幽情。\n悲夫一世之人。\n或放浪形骸遇所欣。\n虽快然自足，终期於尽，老之将至，後视犹今。\n随事情迁，所之既倦，俯仰之间迹已陈。\n兴怀也，将後之览者，有感斯文。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15717, '沁园春', '方岳', '莺带春来，鹃唤春归，春总不知。\n恨杨花多事，杏花无赖，半随残梦，半惹晴丝。\n立尽碧云，寒江欲暮，怕过清明燕子时。\n春且住，待新雏熟了，却问行期。\n问春春竟何之。\n看紫态红情难语离。\n想芳韶犹剩，牡丹知处，也须些个，付与荼縻。\n唤取娉婷，劝教春醉，不道五更花漏迟。\n愁一饷，笑车轮生角，早已天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15718, '沁园春', '方岳', '蠢彼鼯，嗟尔何为，敢瞰长淮。\n遣诗书元帅，又劳指画，神仙寿日，不放襟怀。\n略已三年，可曾一笑，天岂悭吾老子哉。\n诸人者，且携将雅颂，留待磨崖。\n我姑酌彼金。\n便小醉、宁辞鹦鹉杯。\n问今何时也，子其休矣，有如此酒，奚取吾侪。\n帝曰不然，政须卿辈，作我长城惟汝谐。\n凝望处，见红尘飞骑，捷羽东来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15719, '沁园春', '方岳', '有美人兮，铁石心肠，寄春一枝。\n喜藓生龙甲，那因雪瘦，月横鹤膝，不受寒欺。\n云卧空山，梦回孤驿，生怕渠嗔未敢诗。\n江头路，问销魂几许，索笑何时。\n赋成字字明珠。\n君莫倚、家风旧解题。\n叹水曹安在，飘然欲去，逋仙已矣，其与谁归。\n烟雨愁予，江山老我，毕竟岁寒然後知。\n微酸在，尽危谯斜倚，残角孤吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15720, '沁园春', '方岳', '把酒问花，茧栗梢头，春今几何。\n笑身居近侍，阶翻万玉，面丐菩萨，髻拥千螺。\n一一牙签，英英碧字，占定花间甲乙科。\n归来也，傍紫薇吟处，揉作阳和。\n祗今花事无多。\n看几许风烟付与他。\n待围将翡翠，怕蜂粘粉，织成云锦，遣凤衔梭。\n谁翦并刀，赠之燕玉，莫负双娥娇溜波。\n花应道，尽花强人面，底用能歌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15721, '沁园春', '方岳', '子盍规夫，商丘之木，有樗不才。\n纵斧斤睥睨，何妨雪立，风烟傲兀，怎问春回。\n老子似之，倦游久矣，归晒渔蓑羹芋魁。\n村锄外，闻韭今有子，芥已生台。\n天於我辈悠哉。\n纵作赋问天天亦猜。\n且醉无何有，酒徒陶陆，与二三子，诗友陈雷。\n正尔眠云，阿谁敲月，不是我曹不肯来。\n君且住，怕口生荆棘，胸有尘埃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15722, '望江南・忆江南', '方岳', '梅欲老，撑月过南徐。\n家口纵多难减鹤，路程不远易携书。\n只是废春锄。\n霜满袖，茶灶借僧庐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15723, '蝶恋花', '方岳', '雁落寒沙秋恻恻。\n明月芦花，共是江南客。\n骑鹤楼高边羽急。\n柔情不尽淮山碧。\n世路只催双鬓白。\n菰菜莼羹，正自怜人忆。\n归梦不知江水隔。\n烟帆飞过平如席。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15724, '蝶恋花', '方岳', '山抹修眉横绿净。\n浦溆生寒，立尽梧桐影。\n香未消帘幕静。\n醉红如洗风吹醒。\n一夜秋声连玉井。\n梦落孤篷，已尽山阴兴。\n戍角凄凉清漏永。\n江南烟雨何堪省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15725, '蝶恋花', '方岳', '秋水涵空如镜净。\n满镜清寒，倒碧摇山影。\n药户谁抨圆玉静。\n碧纱人怯黄昏醒。\n丛桂小山寒井井。\n唤起江南，一叶莼鲈兴。\n先自新愁愁夜永。\n不堪宋□重提省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15726, '木兰花慢', '方岳', '慨晴江渺渺，乘风下、倚沧浪。\n问许大乾坤，金焦两点，曾几兴亡。\n平章古人安在，但青山、烟水共微茫。\n不道鹭嘲鸥笑，归来鬓已苍苍。\n垂杨。\n舞尽斜阳。\n双燕语、尽渠忙。\n黯柔情不管，花深传漏，羽急飞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15727, '如梦令', '方岳', '知是谁家燕子。\n直恁惺松言语。\n深入绣帘来，无奈落花飞絮。\n春去。\n春去。\n且道干卿何事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15728, '如梦令', '方岳', '雨洗海棠如雪。\n又是清明时节。\n燕子几时来，只了为花愁绝。\n愁绝。\n愁绝。\n枉与春风分说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15729, '贺新凉・贺新郎', '方岳', '霜月寒如洗。\n问梅花、经年何事，尚迷烟水。\n梦著翠霞寻好句，新雪阑干独倚。\n见竹外、一枝横蕊。\n已占百花头上了，料诗情、不但江山耳。\n春已逗，有佳思。\n一香吹动人间世。\n奈何地、丛篁低碧，巧相亏蔽。\n尽让春风凡草木，便做云根石底。\n但留取、微酸滋味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15730, '贺新凉・贺新郎', '方岳', '问讯江南客。\n怕秋崖、苔荒诗屋，云侵山屐。\n留得钓竿西日手，梦落鸥傍鹭侧。\n倩传语、溪翁将息。\n四十飞腾斜暮景，笑双篷、一懒无他画。\n惟饱饭，散轻策。\n世间万事知何极。\n问乾坤、待谁整顿，岂无豪杰。\n水驿山村还要我，料理松风竹雪。\n也不学、草颠诗白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15731, '贺新凉・贺新郎', '方岳', '雁向愁边落。\n渺汀洲、孤云细雨，暮天寒角。\n有美人兮山翠外，谁共霜桥月壑。\n想朋友、春猿秋鹤。\n竹屋一灯棋未了，问人间、局面如何著。\n风雨夜，更商略。\n六州铁铸从头错。\n笑归来、冰鲈堪脍，雪螯堪嚼。\n莫遣孤舟横浦溆，也怕浪狂风恶。\n且容把、钓纶收却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15732, '贺新凉・贺新郎', '方岳', '一笑君知否。\n笑当年、山阴道士，行歌樵叟。\n五十到头公老矣，只可鹭朋鸥友。\n便富贵、何如杯酒。\n好在归来苍崖底，想月明、不负携锄手。\n谁共酌，翦霜韭。\n乾坤许大山河旧。\n几多人、剑倚西风，笔惊南斗。\n俯仰之间成陈迹，亡是子虚乌有。\n渺烟草、不堪回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15733, '贺新凉・贺新郎', '方岳', '天意然乎否。\n待相携、风烟五亩，招邀迂叟。\n屋上青山花木野，尽可两朋三友。\n笑老子、只堪棋酒。\n似恁疏顽何为者，向人前、不解高叉手。\n宁学圃，种菘韭。\n春猿秋鹤皆依旧。\n怪吾今，鬓已成丝，胆还如斗。\n谁与庐山麾之去，尔辈何留之有。\n黯离绪、暮江搔首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15734, '西江月', '方岳', '茅屋何堪翠袖，芝田自有霓裳。\n一双雪舞碧云乡。\n富贵人家以上。\n竹外山童敲臼，梅边溪友传觞。\n青霞道服石炉香。\n便是寿星模样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15735, '西江月', '方岳', '燕子催将初度，梨花指定清明。\n春风可是太多情。\n乐事良辰一并。\n绛老从头甲子，楚骚几度庚寅。\n晴光不隔凤凰城。\n花底举头天近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15736, '西江月', '方岳', '蔬甲初肥雨润，茶枪小摘春明。\n野篱是处可诗情。\n打过下湖船并。\n捷报秋来旁午，贤关早晚同寅。\n绿杨连骑带春城。\n不问南山远近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15737, '一落索', '方岳', '瘦得黄花能小。\n一帘香杳。\n东篱云冷正愁予，犹幸是、西风少。\n叶下亭皋渺渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15738, '汉宫春', '方岳', '云涧之癯，有诗盟未了，鸥泛江湖。\n一官直为仙耳，不受尘驱。\n高情逸韵，自兰亭、已後都无。\n准拟画、剡舟夜雪，与君相对成图。\n半竹苔寒如此，问谁欤来者，鹤伴薰炉。\n何如贮之天上，风露冰壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15739, '汉宫春', '方岳', '问讯何郎，怎春风未到，却月横枝。\n当年东阁诗兴，夫岂吾欺。\n云寒岁晚，便相逢、已负深期。\n烦说与、秋崖归也，留香更待何时。\n家住江南烟雨，想疏花开遍，野竹巴篱。\n遥怜水边石上，煞欠渠诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15740, '酹江月・念奴娇', '方岳', '问天何事，雪垂垂欲下，又还晴却。\n春到梅梢香逗也，尽有心情行乐。\n剡曲舟回，灞桥诗在，一笑人如昨。\n此情分付，暮天寒月残角。\n谁道飞梦江南，群山如画，一一琼瑶琢。\n中有玉田三万顷，云是幼舆丘壑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15741, '酹江月・念奴娇', '方岳', '绿尊翠勺，约秋风、一醉小楼先月。\n谁取宝奁奔帝所，深锁玉华宫阙。\n老桂香寒，疏桐云重，生怕金蛇掣。\n那知天柱，一峰别与天接。\n我欲飞佩重游，置之衣袖，照我襟怀雪。\n玉斧难藏修月手，待做明宵清绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15742, '酹江月・念奴娇', '方岳', '幅巾云麓。\n笑人生瓮等，何时是足。\n莫道年来无好处，第一秫田新熟。\n孙息乘鸾，大儿荐鹗，翁已恩袍碌。\n笑谭戎幕，尽教岳也碌碌。\n是则江南江北，月明飞梦，认得溪桥屋。\n多少睡乡闲日月，不老柯山棋局。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15743, '酹江月・念奴娇', '方岳', '且拌春醉。\n问人间、谁是十分如意。\n道不好来人又道，也有一分好处。\n管甚长贫，只消长健，切莫眉头聚。\n尽教江路，梅花依旧留住。\n儿辈虽不如人，有何不可，怎敢嫌迟暮。\n但喜吾翁躔度转，唤起烟霞深痼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15744, '酹江月・念奴娇', '方岳', '花风初逗，喜边亭依旧，春闲营柳。\n烟草隋宫歌舞地，谁遣万红围绣。\n结酒因缘，装春富贵，也要经纶手。\n笙箫声里，一江晴绿吹皱。\n是处羽箭如飞，那知鹤府，花压阑干昼。\n油幕文书谈笑了，馀事尽堪茶酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15745, '酹江月・念奴娇', '方岳', '槎牙诗骨，想生来无分，史闱经幄。\n呵护九关多虎豹，谁道去天一握。\n奏赋两都，闻韶三月，雁远书难托。\n一寒如许，蟾枝莫倚高擢。\n空使满壑风烟，半村雪月，孤负梅花约。\n渺渺愁予初度也，山互同云垂幕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15746, '酹江月・念奴娇', '方岳', '祈山底处，为二松千竹，肯题崖壁。\n雪洒谈犀麾雁骛，尔辈何烦涉笔。\n使者知乎，民其劳止，且莫闲耕织。\n片言金石，唤回春意无极。\n虽则王谢人家，一癯仙泽，面作苍烟色。\n茶炷笔床将雨屐，吟到梅花消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15747, '水龙吟', '方岳', '当年睡里闻香，阿谁唤做花间瑞。\n巾飘沈水，笼熏古锦，拥青绫被。\n初日酣晴，柔风逗暖，十分情致。\n掩窗绡，待得香融酒醒，尽消受、这春思。\n从把万红排比。\n想较伊、更争些子。\n诗仙老手，春风妙笔，要题教似。\n十里扬州，三生杜牧，可曾知此。\n趁紫唇微绽，芳心半透，与骚人醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15748, '水龙吟', '方岳', '昼长庭院深深，春柔一枕流霞醉。\n蒙松欲醒，娇羞还困，锦屏围翠。\n豆寇初肥，樱桃微绽，玉阑同倚。\n记华清浴起，渭流波暖，红涨腻、弃脂水。\n燕子来时天气。\n尽韶风、与诗为地。\n芳丛雨歇，露痕日酽，英英仙意。\n莫恨无香，最怜有韵，天然情致。\n待问春能几，五更犹是，拌今宵睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15749, '满庭芳', '方岳', '半壳含黄，双螯擘紫，风流浑是芦花。\n江头秋老，谁了酒生涯。\n玉质金相如许，怎消受、明月寒沙。\n橙香也，不闲左手，除是付诗家。\n草泥，行郭索，横戈曾怒，张翰浮夸。\n笑鲈鱼虽好，风味争些。\n醉嚼霜前松雪，江湖梦、不枉归槎。\n停杯问，余其负腹，是腹负余耶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15750, '喜迁莺', '方岳', '淮山秋晓。\n问西风几度，雁云蛩草。\n铁色骢骄，金花袍窄，未觉塞垣寒早。\n笳鼓声中晴色，一羽不飞边报。\n君莫道，怎乾坤许大，英雄能少。\n谈笑。\n鸣镝处，生缚胡雏，烽火传音耗。\n漠漠寒沙，荒荒残照，正空不劳深讨。\n但喜欢迎马首，犹是中原遗老。\n关何事，待归来细话，一尊倾倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15751, '浣溪沙', '方岳', '半壳含潮带靥香。\n双螯嚼雪迸脐黄。\n芦花洲渚夜来霜。\n短棹秋江清到底，长头春瓮醉为乡。\n风流不枉与诗尝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15752, '浣溪沙', '方岳', '夜醉渊明把菊图。\n宿酲扶晓又冰壶。\n秋香留得伴双凫。\n并日满浮金馨落，明年初赐玉茱萸。\n更书欲上有除书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15753, '齐天乐', '方岳', '孤篷夜傍低丛宿，萧萧雨声悲切。\n一岸霜痕，半江烟色，愁到沙头枯叶。\n澹云没灭。\n黯西风吹老，满汀新雪。\n天岂无情，离骚点点送归客。\n归去来兮怎得，尽鹭翅鸥倚，乍寒时节。\n秋晚山川，夕阳浦溆，赢得别肠千结。\n涛翻浪叠。\n那得似西来，一筇横绝。\n搔首江南，雁衔千里月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15754, '花心动', '方岳', '雪带边寒，渺愁予、雪中谁抱奇节。\n逊在扬州，逋老孤山，芳信顿成消歇。\n江南茅屋今安在，疏影瘦、祗堪叹息。\n归来未，沙头立尽，暮天云碧。\n自笑梁园赋客。\n倚旧日鞍鞯，春风巾帻。\n问讯横枝，暖热新花，无处访寻诗阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15755, '风流子', '方岳', '小楼帘不卷，花正闹、灯火竞春宵。\n想旧日何郎，飞金叵罗，三生杜牧，醉董娇饶。\n香尘路，云松鸾髻，月衬马蹄骄。\n仿佛神仙，刘安鸡犬，分明富贵，子晋笙箫。\n人生行乐耳，君不见、迷楼春绿迢迢。\n二十四、经行处，旧月今桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15756, '瑞鹤仙', '方岳', '一年寒尽也。\n问秦沙、梅放未也。\n幽寻者谁也。\n有何郎佳约，岁云除也。\n南枝暖也。\n正同云、商量雪也。\n喜东皇，一转洪钧，依旧春风中也。\n香也。\n骚情酿就，书味熏成，这些情也。\n玉堂深也。\n莫道年华归也。\n是循环、三百六旬六日，生意无穷已也。\n但丁宁，留取微酸，调商鼎也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15757, '瑞鹤仙', '方岳', '中元才过节。\n正宇宙澄清，一天寒碧。\n凉飙动秋色。\n算佳辰恰是，下弦当日。\n天生俊杰。\n富文才、瑰奇挺特。\n看葱葱，和气薰城，共庆武夷仙伯。\n难得。\n钓鳌连六，虎傍登名，新题淡墨。\n从容莲幕。\n游花县，无邀隔。\n纵风流别驾，难淹紫诏，行对天颜咫尺。\n更堪夸，萱草长春，红衣交列。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15758, '哨遍', '方岳', '月亦老乎，劝尔一杯，听说平生事。\n吾问汝，开辟自何时。\n有乾坤更应有尔。\n年几许。\n鸿荒邈哉遐已。\n吾今断自唐虞起。\n系帝曰放勋，甲辰践祚，数至今、宋嘉熙。\n凡三千五百二十年馀。\n嗟雨风几盈亏。\n老兔奔驰，痴蟆吞吐，定应衰矣。\n噫。\n月岂无悲。\n吾观人寿几期颐。\n炯炯双眸子，明清无过婴儿。\n但才到中年，昏然欲，那堪老矣知何似。\n试以此推之。\n吾言有理，不能不自疑耳。\n恐古时月与今时异。\n恨则恨今人不千岁。\n但见今、冰轮如洗。\n阿谁曾自前古，看到隋唐世。\n几时明洁，几时昏暗，毕竟少晴多雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15759, '哨遍', '方岳', '月曰不然，君亦怎知，天上从前事。\n吾语汝，月岂有弦时。\n奈人间井观乃尔。\n休浪许。\n历家缪悠而已。\n谁云魄死生明起。\n又明死魄生，循环晦朔，有老兔、自熙熙。\n妄相传、月溯日光馀。\n嗟万古谁知了无亏。\n玉斧修成，银蟾奔去，此言荒矣。\n噫。\n世已堪悲。\n听君歌复解人颐。\n桂魄何曾死，寒光不减些儿。\n但与日相望，对如两镜，山河大地无疑似。\n待既望观之。\n冰轮渐侧，转斜才一钩耳。\n论本来不与中秋异。\n恐天问灵均未知此。\n又底用、咸池重洗。\n乾坤一点英气。\n宁老人问世。\n飞上天来，摩挲月去，才信有晴无雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15760, '眼儿媚', '方岳', '雁带新霜几多愁。\n和月落沧洲。\n桂花如许，菊花如许，怎不悲秋。\n江山例合闲人管，也白几分头。\n去年曾此，今年曾此，烟雨孤舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15761, '鹊桥仙', '方岳', '银河无浪，琼楼不暑。\n一点柔情如水。\n肯捐兰了渠愁，尽闲却、纤纤机杼。\n波心沁雪，鸥边分雨。\n翦得荷花能楚。\n天公煞自解风流，看得我、如何销汝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15762, '鹊桥仙', '方岳', '今朝廿九，明朝初一。\n怎欠秋崖个生日。\n客中情绪老天知，道这月、不消三十。\n春盘缕翠，春缸摇碧。\n便泥做、梅花消息。\n雪边试问是耶非，笑今夕、不知何夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15763, '玉楼春', '方岳', '木犀过了诗憔悴。\n只有黄花开又未。\n秋风也不管人愁，到处相寻吹短袂。\n露滴碧觞谁共醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15764, '虞美人', '方岳', '鸥清眠醉晴溪月。\n几梦寒蓑雪。\n断桥篱落带人家。\n枝北枝南初著、两三花。\n曾於春底横孤艇。\n香似诗能冷。\n娟娟玉立载归壶。\n渺渺愁予肯入、楚骚无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15765, '一剪梅・一翦梅', '方岳', '谁翦轻琼做物华。\n春绕天涯。\n水绕天涯。\n园林晓树恁横斜。\n道是梅花。\n不是梅花。\n宿鹭联拳倚断槎。\n昨夜寒些。\n今夜寒些。\n孤舟蓑笠钓烟沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15766, '烛影摇红', '方岳', '辇路融晴，宫云逗晓青旗报。\n梅边香沁彩鞭寒，初信花风到。\n笑语谁家帘幕，镂冰丝、红粉绿闹。\n髻横玉燕，鬓颤琼幡，不能知掉。\n看见春来，麴尘微涨催兰棹。\n娇横拂略上柔条，等得莺眠觉。\n引出千花万草。\n喜搀先、椒盘竹爆。\n问谁天上，瑶帖初供，玉堂归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15767, '最高楼', '方岳', '溪南北，本自一渔舟。\n烟雨几盟鸥。\n白鱼不负鸬鹚杓，青蓑不减裘。\n怎无端，贪射策，觅封侯。\n既不似、古人能识字。\n又不似、今人能识事。\n空老去，自宜休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15768, '最高楼', '方岳', '朝元了，万鹤放班回。\n携月下天来。\n初平家看青羊石，滕王阁醉绿螺杯。\n试鸣琴，花荡漾，玉崔嵬。\n前十日、鹊桥飞宝镫。\n後一月、兔奁开玉镜。\n秋色净，夜徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15769, '最高楼', '方岳', '秋崖底，云卧欲生苔。\n无梦到公台。\n有月锄、晓带乌犍去，与烟蓑、夜钓白鱼来。\n问谁能，供酒料，办诗材。\n君莫笑、闲忙棋得势。\n也莫笑、浮湛渔得计。\n胸次老，雪崔嵬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15770, '行香子', '方岳', '说与樵青。\n紧闭柴门。\n道先生检校东屯。\n阿戎安在，未扫愁痕。\n且免歌词，休载妓，莫携尊。\n梅自生春。\n雪立前村。\n道此杯、酒也须温。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15771, '江神子・江城子', '方岳', '窗绡深隐护芳尘。\n翠眉颦。\n越精神。\n几雨几晴，做得这些春。\n切莫近前轻著语，题品错，怕渠嗔。\n碧壶谁贮玉粼粼。\n醉香茵。\n晚风频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15772, '江神子・江城子', '方岳', '梅花吹梦过溪桥。\n路迢迢。\n雪初消。\n似恁天寒，诗瘦想无柳。\n听得草堂人有语，能几日，是生朝。\n乱云深处洗山瓢。\n鬓萧萧。\n酒红朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15773, '水调歌头', '方岳', '世不乏季子，藉甚有休声。\n芝兰挺秀庭砌，广厦万间新。\n胸次金天爽豁，风骨玉堂清彻，才器更轮。\n劲节九秋斡，和气万家春。\n过中元，才两日，是生辰。\n瓣香西上，都向此夕颂殷勤。\n自有阴功天佑，合享人间长寿，不独我知君。\n从此见今日，丹桂伴灵椿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15774, '瑞鹧鸪', '方岳', '中元过後恰三朝。\n因甚庭闱喜气飘。\n李谪若非当此夕，甲生应是在今宵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15775, '酹江月・念奴娇', '方岳', '楚天秋早，过中元拈指，飞四荚。\n怪得千门佳气满，恰值生申时节。\n蓬矢当年，椒盘今夕，瑞木金炉艺。\n主人情重，酒红潮上双颊。\n且看戏彩□□，鼎分丹桂，兰玉同班列。\n更喜萱庭南极老，亲授长生秘诀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15776, '满庭芳', '方岳', '秋入西郊，律调夷则，韩堂风露清凉。\n洞天昨夜，响动玉玎。\n朱户银寰放钥，长庚梦、应诞星郎。\n垂弧旦，飞五荚，簪履共称觞。\n未施经济手，暂参雄府，公论声扬。\n便好趁昌辰，入辅吾皇。\n况是中兴启运，正当宁、梦想循良。\n从兹去，万年佐主，福寿总无疆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15777, '满庭芳', '方岳', '星昴呈祥，山川锺秀，果然生此真贤。\n精神莹澈，秋水共长天。\n况值西风初起，中元过、七日凉先。\n庭院爽，称觞贺客，车马看骈阗。\n开筵。\n称寿处，红袖歌舞，脆管繁弦。\n愿公与椿松，对阅天年。\n纵使平分风月，不容暂、吟醉苕川。\n龙光近，行看凤诏，促入秉钧权。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15778, '百字谣・念奴娇', '方岳', '河南灵地，信从生俊杰，皆由天佑。\n见说簪缨称世袭，复是青毡还旧。\n学海渊源，笔端锋镝，未逊谁居右。\n使台暂赞，直须黄阁环召。\n欣遇初度良辰，中原节过，九日方称寿。\n好看莱衣□舞处，尽羡一门三秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15779, '八六子', '方岳', '喜椿庭。\n近来强健，团栾雁序欢声。\n正柳絮帘栊清昼，牡丹栏槛新晴，缓飞翠觥。\n阿戎碌碌功名。\n但要无灾无难，何曾著公卿。\n且抖擞斑衣，笑供儿戏，共将乐事，细酬佳景，须知翠袖全盛绿黛，金章不换蓑青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15780, '霜天晓角', '楼', '月淡风轻。\n黄昏未是清。\n吟到十分清处，也不啻、二三更。\n晓钟天未明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15781, '霜天晓角', '楼', '翦雪裁冰。\n有人嫌太清。\n又有人嫌太瘦，都不是、我知音。\n谁是我知音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15782, '桂枝香', '徐宝之', '人间秋至。\n对暮雨满城，沈思如水。\n桐叶惊风，似语怨蛩齐起。\n南楼月冷曾多恨，怕而今、夜深横吹。\n那堪更听，萧萧，透窗摇睡。\n问楚梦、闲云何地。\n但手约轻绡，省人深意。\n红树池塘，谁见宿妆凝睇。\n旧时裘马行歌事，合都归、汀苹烟芷。\n思王渐老，休为明，沈吟洛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15783, '沁园春', '徐宝之', '水榭春寒，梅雪漫阶，竹云堕墙。\n数花时近也，采芳香径，旧情著处，看月西窗。\n十二楼中，玉妃卧冷，懒掬胭脂放海棠。\n层堤外，渺归鸿无数，江树苍苍。\n席夜礼东皇。\n剪蕙叶为笺当绿章。\n道杏晴三月，等莺啼晓，草烟万里，待鸣芳。\n九十日春，三千丈发，如此愁来白更长。\n江南岸，正柳边无路，沙雨微茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15784, '莺啼序', '徐宝之', '荼シ一番过雨，洒残花似雪。\n向清晓、步入东风，细拾苔砌馀靥。\n有数片、飞沾翠柳，萦回半著双归蝶。\n悄无人、共立幽禽，昵昵能说。\n因念年华，最苦易失，对春愁暗结。\n叹自古、曾有佳人，长门深闭修洁。\n寄么弦、千言万语，闷满眼、欲弹难彻。\n靠珠栊，风雨微收，落花时节。\n春工渐老，绿草连天，别浦共一色。\n但暮霭、朝烟无际，尽日目极，江南江北，杜鹃叫裂。\n此时此意，危魂黯黯，渭城客舍青青树，问何人、把酒来看别。\n思量怎向，迟回独掩青扉，夕阳犹照南陌。\n春应记得，旧日疏狂，等受今磨折。\n便永谢、五湖烟艇，只有吟诗，曲坞煎茶，小窗眠月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15785, '水调歌・水调', '徐宝之', '了却意中事，卜筑快幽情。\n雨帘云栋深窈，歌笑霭春生。\n青嶂碧溪门户，暖翠浮岚衿席，前日展湘屏。\n种竹看霜节，栽菊待秋英。\n九世图，闲居赋，丽人行。\n名碑古画，贴遍东阁与西亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15786, '水龙吟', '祖吴', '紫貂南北分荣，有人瑞凤池疏秀。\n月斧云斤，斫成三绝，辉华星斗。\n早岁从军，乌戎口伐，奇功立就。\n更题衡忠义，传家清白，人道外甥似舅。\n好看五经说後。\n步蟾宫、桂香盈袖。\n紫橐持荷，清班布武，履声依旧。\n回意刊山，当年垂棒，月明烟袖。\n隐岩清秀，露玉风金，岁岁祝千秋寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15787, '水调歌头', '祖吴', '佳丽东阳境，瑞气晓笼晴。\n中元逾了十日，上相喜重生。\n四海文章宗匠，百里弦歌德化，官与水双清。\n恳切劝分意，赈恤活饥。\n幸依刘，空颂鲁，阻称觥。\n遥瞻快倚楼上，一点寿星明。\n闻道玺书将下，看取蓬瀛直造，指日秉钧衡。\n大展平戎略，谈笑复神京。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15788, '沁园春', '周申', '瑞应柯山，昴宿储祥，嵩岳降神。\n羡堂堂玉莹，汪汪陂量，一襟风月，满腹经纶。\n试问丹砂，聊乘凫，来种锦江桃李春。\n弦歌地，看吏能绰著，荐墨争新。\n从兹大振家声。\n待京国来归专秉钧。\n想宸恩初拜，北门学士，都能尽道，东阁郎君。\n雨细丝轻，梅花金重，两荚宝阶呈瑞。\n称觞庆，愿莱衣衮衮，长照庄椿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15789, '壶中天・念奴娇', '周申', '秋来两日，因个甚、乌鹊侵晨传喜。\n却是常娥亲姊妹，降作人间佳丽。\n黛柳长青，官梅稳衬，镜里春明媚。\n花颜难老，寿杯频劝浮蚁。\n闻道潇洒才郎，天庭试罢，名挂登科记。\n昨夜凉风新过雁，还有音书来寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15790, '沁园春', '赵汝腾', '人道耻堂，直声劲气，胜如鹤山。\n记殿庭叱禹，风生九陛，都亭劾冀，影摄群奸。\n海内英豪，如公有几，此地相逢同左官。\n丹青阁，望烟云缥缈，曾共凭栏。\n忧时空见眉端。\n叹西事何由圣虑宽。\n使蜀居诸葛，兵屯自肃，朝留一范，贼胆须寒。\n天欲兴唐，昴应相汉，立取勋名久远看。\n秋香耐，笑菊潭胡广，污简何颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15791, '沁园春', '赵孟坚', '许大江山，镇临弹压，岂小任哉。\n从潘冢导漾，东倾注海，截然限止，南北天开。\n试向中流，回观铁瓮，万石层棱攒剑堆。\n金焦峙，号紫金浮玉，卷雪轰雷。\n君侯文武兼才。\n天有为生才南国来。\n□历二十年，筹边给饷，上流襟要，几为安排。\n今此雄藩，精明笳鼓，又唤金汤气象回。\n长淮北，望中原非远，更展恢规。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15792, '鹊桥仙', '赵孟坚', '明金点染，枝头初见，四出如将刀翦。\n芳心才露一些儿，早以被、西风传遍。\n归来醉也，香凝襟袖，疑向广寒宫殿。\n便须著个胆瓶儿，夜深在、枕屏根畔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15793, '沁园春', '赵孟坚', '晓上画楼，望里笑惊，春到那家。\n便从臾闲情，安排醉事，寻芳唤友，行过平沙。\n最是堪怜，花枝清瘦，欲笑还羞寒尚遮。\n浓欢赏，待繁英春透，後会犹赊。\n归时月挂檐牙。\n见花影重重浸宝阶。\n□铜壶摧箭，兽环横钉，浓斟玉醑，芳漱琼芽。\n步绕曲廊，倦回芳帐，梦遍江南山水涯。\n谁知我，有墙头桂影，窗上梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15794, '朝中措', '赵孟坚', '担头看尽百花春。\n春事只三分。\n不似莺莺燕燕，相将红杏芳园。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15795, '好事近', '赵孟坚', '春早峭寒天，客里倦怀尤恶。\n待起冷清清地，又孤眠不著。\n重温卯酒整瓶花，总待自霍索。\n忽听海棠初卖，买一枝添却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15796, '感皇恩', '赵孟坚', '官小宦游初，清贫如旧。\n小簇杯盘旋酒。\n虽然微禄，不比他们丰厚。\n也知惭愧是，皇恩受。\n富贵千般，享之惟寿。\n心地平时到头有。\n摩挲铜狄，祝望比他长久。\n鼎来荣贵待，通闺後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15797, '感皇恩', '赵孟坚', '一百二十年，两番甲子。\n前番风霜饱谙矣。\n今番甲子，一似腊尽春至。\n程程有好在，应惭愧。\n莫道官贫，胜如无底。\n随分杯筵称家计。\n从今数去，尚有五十八生朝里。\n待儿官大，做奢遮会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15798, '风流子', '赵孟坚', '望极思悠悠。\n江如练、籁息浪纹收。\n看帆卷帆舒，往来征艇，鹭飞鹭立，远近芳洲。\n逝波不舍山常好，祗白少年头。\n杜若满汀，离骚幽怨，鸱夷去国，烟浪遨游。\n江南知何许，青林晚，山断处、白云浮。\n怀古慨今，谁人似我闲愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15799, '花心动', '赵孟坚', '庭院深深，正花飞零乱，蝶懒蜂稀。\n柳絮狂踪，轻入房栊，悄悄可有人知。\n画堂镇日闲晴昼，金炉冷、绣幕低垂。\n梁间燕，双双并翅，对舞高低。\n兰幌玉人睡起，情脉脉、无言暗敛双眉。\n斗帐半褰，六曲屏山，憔悴似不胜衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15800, '蓦山溪', '赵孟坚', '几年修绩，总待荣亲老。\n每羡院南豪，向寿席、花花草草。\n如今惭愧，微胜十年前，聊尔办，杯盘了，一对慈颜笑。\n愿亲强健，绿鬓长长好。\n来岁在琴堂，想凡事、应微热闹。\n契天交道，只办好心肠，官尽大，尽荣亲，待受金花诰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15801, '蓦山溪', '赵孟坚', '桃花雨动，测测轻寒小。\n曲槛面危阑，对东风、伤春怀抱。\n酒边心事，花下旧闲情，流年度，芳尘杳，懊恼人空老。\n粉红题字，寄与分明道。\n消息燕归时，辗柔茵、连天芳草。\n琐窗孤影，夜卜烛花明，清漏断，月朦胧，挂在梅梢袅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15802, '东风第一枝', '赵崇霄', '妒雪梅苏，迷烟柳醒，游丝轻扬新霁。\n卷帘看燕初归，步为花早起。\n春来犹浅，便做出、十分春意。\n喜凤钗、才卸珠幡，早换巧梳描翠。\n著数点、催花雨腻。\n更一番、递香风细。\n小莺暖调声，嫩蝶试晴舞翅。\n清欢易失，怕轻负、年芳流水。\n好趁闲、共整吟鞯，日日访桃寻李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15803, '减字木兰花', '马光祖', '多情多爱。\n还了平生花柳债。\n好个檀郎。\n室女为妻也不妨。\n杰才高作。\n聊赠青蚨三百索。\n烛影摇红。\n记取媒人是马公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15804, '贺新郎', '李南金', '流落今如许。\n我亦三生杜牧，为秋娘著句。\n先自多愁多感慨，更值江南春暮。\n君看取、落花飞絮。\n也有吹来穿绣幌，有因风、飘坠随尘土。\n人世事，总无据。\n佳人命薄君休诉。\n若说与、英雄心事，一生更苦。\n且尽樽前今日意，休记绿窗眉妩。\n但春到、儿家庭户。\n幽恨一帘烟月晓，恐明年、雁亦无寻处。\n浑欲倩，莺留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15805, '朝中措', '萧', '半山社雨欲黄昏。\n燕子不过门。\n杨柳染深绿意，海棠啼损红痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15806, '恋绣衣', '萧', '倚阑闲看燕定巢。\n旧弹筝、因病久抛。\n画不尽、残眉黛，被东风、吹在柳梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15807, '满江红', '萧', '（和陈漕使仙湖韵）莫是西湖，分一派、残波剩碧。\n闲问著、莺仙丹事，老榕知得。\n荇水带长鸥踏损，柳风絮暖鱼吞入。\n只前山、依旧汉时青，晴还湿。\n亭疏好，何消密。\n花少好，无多植。\n听黄鹂三请，要诗翁出。\n消渴泉斟寒玉液，留题石剥苍苔色。\n叹而今、翻羡□南春，乾坤窄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15808, '霜天晓角', '萧泰来', '千霜万雪。\n受尽寒磨折。\n赖是生来瘦硬，浑不怕、角吹彻。\n清绝。\n影也别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15809, '满江红', '萧泰来', '七十人稀，尝记得、少陵旧语。\n谁知道、五园庵主，寿今如许。\n书底青瞳如月样，镜中黑鬓无双处。\n与人间、世味不相投，神仙侣。\n文汉史，诗唐句。\n字晋帖，碑周鼓。\n这千年勋业，一年一部。\n晔晔紫芝商隐皓，猗猗绿竹淇瞻武。\n问先生、何处更高歌，凭椿树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15810, '城头月', '马天骥', '城头月色明如昼。\n总是青霞有。\n酒醉茶醒，饥餐困睡，不把双眉皱。\n坎离龙虎勤交媾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15811, '城头月', '黎道静', '阳光子夜开清昼。\n照了无何有。\n弱水蓬莱，河车忽动，万顷金波皱。\n红铅墨汞相交媾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15812, '满庭芳', '黄判院', '桃浪翻花，柳风飘絮，翠八叶呈芳。\n奎星初度，箕宿耀祥光。\n元是降神崧岳，生英杰、奇伟非常。\n文章士，青春未老，一鹗快飞黄。\n登瀛，平步上，鳌头独占，头角轩昂。\n主琼林宴席，荣冠绿衣郎。\n归侍彩俱庆，逢生旦、品上椒觞。\n从今去，公侯谈笑，福寿等天长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15813, '青玉案', '薛泳', '一盘消夜江南果。\n吃果看书只清坐。\n罪过梅花料理我。\n一年心事，半生牢落，尽向今宵过。\n此身本是山中个。\n才出山来便希差。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15814, '满江红', '徐元杰', '似玉仙人，三载相见，西湖清客。\n不碎、一团和气，只伊消得。\n雪里水中霜态度，腊前冬後春消息。\n看帘垂、清昼一张琴，中闲著。\n寒谷里，轻回脚。\n魁手段，堪描摸。\n唤东风吹上，兰台芸阁。\n只怕傅岩香不断，摩挲商鼎羹频作。\n管一番滋味一番新，今如昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15815, '沁园春', '国学生', '三学上书，冤乎天哉，哲人已萎。\n自纲常一疏，为时太息，典刑诸老，尽力扶持。\n方哭南床，继伤右揆，死到先生事可知。\n伤心处，笑寒梅冷落，血泪淋漓。\n人心公论难欺。\n愿君父、明明悟此机。\n昔九龄疏谏，禄山必叛，更生累奏，王氏为危。\n变起范阳，祸成新室，说著当年人噬脐。\n君知否，但皇天祚宋，此事无之。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15816, '瑞鹤仙', '陆', '湿云黏雁影。\n望征路愁迷，离绪难整。\n千金买光景。\n但疏钟催晓，乱鸦啼暝。\n花暗省。\n许多情、相逢梦境。\n便行云、都不归来，也合寄将音信。\n孤迥。\n盟鸾心在，跨鹤程高，後期无准。\n情丝待翦。\n翻惹得，旧时恨。\n怕天教何处，参差双燕，还染残朱剩粉。\n对菱花、与说相思，看谁瘦损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15817, '八声甘州', '陆', '问缠腰跨鹤，事如何，人生最风流。\n怕江边潮汐，世间歧路，只是离愁。\n白马青衫往事，赢得鬓先秋。\n目送红桥晚，几番行舟。\n兰空馀依黯，便南风吹水，人也难留。\n但从今别後，我亦似浮沤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15818, '甘州・八声甘州', '陆', '满清平世界庆秋成，看看斗三钱。\n论从来活国，论功第一，无过丰年。\n办得闲民一饱，馀事笑谈间。\n若问平戎策，微妙难传。\n玉帝要留公住，把西湖一曲，分入林园。\n有茶炉丹灶，更有钓鱼船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15819, '声声慢', '史可堂', '羞朱妒粉，染雾裁云，淡然苍佩仙裳。\n半额蜂妆，莫道梳洗家常。\n碧罗乱萦小带，翠虬寒、一架清香。\n春思苦，倚晴娇无力，如待韩郎。\n密幄笼芳吟夜，任露沾轻袖，月转空梁。\n弱骨柔姿，偏解勾引诗狂。\n遗钿碎金满地，恨无情、风送韶光。\n闲昼永，看青青、垂蔓过墙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15820, '蓦山溪', '史可堂', '危阑看月，番做听秋雨。\n一滴一声愁，似相伴，离人悲苦。\n笼香袖冷，独立倚西风，红叶落，菊花残，都是关情处。\n如何排遣，赖有高阳侣。\n长啸酒垆边，且同赋、秋娘词句。\n山翁醉矣，一笛小楼空，思往事，看孤云，目断征鸿去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15821, '眼儿媚', '陈诜', '鬓边一点似飞鸦。\n休把翠钿遮。\n二年三载，千拦百就，今日天涯。\n杨花又逐东风去，随分入人家。\n要不思量，除非酒醒，休照菱花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15822, '小桃红・连理枝', '余桂英', '芳草连天暮。\n斜日明汀渚。\n懊恨东风，恍如春梦，匆匆又去。\n早知人、酒病更诗愁，镇轻随飞絮。\n宝镜空留恨，筝雁浑无据。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15823, '八声甘州', '曾原', '问岩云朵朵为谁飞，向来读何书。\n道江南名宦，掉头勿顾，彩服归与。\n无限山中风物，今古属潜夫。\n渺渺辽天鹤，应费招呼。\n谩说缁巾缟带，与豸冠犀剑，忧乐如何。\n渐桥横采石，国步已趄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15824, '木兰花・玉楼春', '曾原', '断崖抛雪瀑，又潜溜、入山跟。\n听暗壁潺，山中紫雾，山下红云。\n当年七僧甚处，但空馀、老刹靠嶙峋。\n底事神粮不幻，翠窝剩积香尘。\n纷纷。\n结社种莲人。\n名氏已无闻。\n看银书般若，金陵故国，斜敕空存。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15825, '三台春曲', '许', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15826, '三台春曲', '许', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15827, '谒金门', '许', '微雨後。\n染得杏腮红透。\n春色好时人却瘦。\n镜寒妆不就。\n柳外一莺啼昼。\n约略情怀中酒。\n困起半弯眉袖。\n髻松簪玉溜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15828, '鹧鸪天', '许', '翠凤金鸾绣欲成。\n沈香亭下款新晴。\n绿随杨柳阴边去，红踏桃花片上行。\n莺意绪，蝶心情。\n一时分付小银筝。\n归来玉醉花柔困，月滤窗纱约半更。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15829, '柳枝・杨柳枝', '许', '冷迫春宵一半床。\n懒熏香。\n不如屏里画鸳鸯。\n永成双。\n重叠衾罗犹未暖。\n红烛短。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15830, '小重山', '许', '正是拈芳采艳时。\n连朝风雨里，掩朱扉。\n强排春恨剪新词。\n词未就，莺唱缕金衣。\n云薄弄晴晖。\n试穿花迳去，拣双枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15831, '满宫春', '许', '懒抟香，慵弄粉。\n犹带浅酲微困。\n金鞍何处掠新欢，偷倩燕寻莺问。\n柳供愁，花献恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15832, '浣溪沙', '许', '欲把香缯暖缬裁。\n玉箱金锁又慵开。\n一杯茶罢上春台。\n方向柳边揉碧缕，又从花畔并红腮。\n不知凝待阿谁来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15833, '更漏子', '许', '泪淹红，腮褪粉。\n等得玉销花损。\n羞阮凤，怯筝鸾。\n指寒无好弹。\n一庭雪。\n半窗月。\n又是独眠时节。\n孤枕怨，小屏愁。\n天涯梦里游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15834, '荷叶杯', '许', '鹊踏画檐双噪。\n书到。\n和笑拆封看。\n归程能隔几重山。\n远约数宵间。\n准备绣轮雕辔。\n游戏。\n说与百花知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15835, '夜行船', '许', '一辔东风留不住。\n离歌断、日斜春暮。\n多事啼莺，妒情飞燕，一路送人归去。\n文君自被琴心误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15836, '应天长', '许', '溅紫飘红风又雨。\n一刻韶芳留不住。\n燕吞声，莺谇语。\n待得晴来人已去。\n怯新歌，怜旧舞。\n冷落艳腔芳谱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15837, '喜迁莺', '许', '鸠雨细，燕风斜。\n春悄谢娘家。\n一重帘外即天涯。\n何必暮云遮。\n钏金寒，钗玉冷。\n薄醉欲成还醒。\n一春梳洗不簪花。\n孤负几韶华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15838, '虞美人', '许', '杏花窗底人中酒。\n花与人相守。\n帘衣不肯护春寒。\n一声娇嚏两眉攒。\n拥衾眠。\n明朝又有秋千约。\n恐未梳掠。\n倩谁传语画楼风。\n略吹丝雨湿春红。\n绊游踪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15839, '清平乐', '许', '凤双鸾偶。\n天上人间有。\n檐玉无声花影瘦。\n夜浅春浓时候。\n别来几度寒宵。\n六桥风月迢迢。\n灯下有谁相伴，一方红湿鲛绡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15840, '山花子', '许', '柳揉花旋染衣。\n丝丝红翠扑春辉。\n罗绮丛中无此艳，小西施。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15841, '相思引', '许', '组绣盈箱锦满机。\n倩谁缝作护花衣。\n恐花飞去，无复上芳枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15842, '画堂春', '许', '一绡香暖看灯衣。\n领珠襟翠争辉。\n金球斜雪梅枝。\n著带都宜。\n桃艳妆成醉脸，柳娇移上歌眉。\n一轮蟾玉堕花西。\n携手同归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15843, '相见欢', '许', '绣围春水锦笼山。\n冶游天。\n可惜连朝中酒、怯秋千。\n妆楼暖。\n朱帘卷。\n燕斜穿。\n冲落两三花片、镜台边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15844, '后庭花', '许', '一春不识西湖面。\n翠羞红倦。\n雨窗和泪摇湘管。\n意长笺短。\n知心惟有雕梁燕。\n自来相伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15845, '摸鱼儿', '陈策', '倚危梯、酹春怀古，轻寒才转花信。\n江城望极多愁思，前事恼人方寸。\n湖海兴。\n算合付元龙，举白浇谈吻。\n凭高试问。\n问旧日王郎，依刘有地，何事赋幽愤。\n沙头路，休记家山远近。\n宾鸿一去无信。\n沧波渺渺空归梦，门外北风凄紧。\n乌帽整。\n便做得功名，难绿星星鬓。\n敲吟为稳。\n又白鹭飞来，垂杨自舞，谁与寄离恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15846, '满江红', '陈策', '倦绣人闲，恨春去、浅颦轻掠。\n章台路，雪黏飞燕，带芹穿幕。\n委地身如游子倦，随风命似佳人薄。\n叹此花、飞後更无花，情怀恶。\n心下事，谁堪托。\n怜老大，伤飘泊。\n把前回离恨，暗中描摸。\n又趁扁舟低欲去，可怜世事今非昨。\n看等闲、飞过女墙来，秋千索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15847, '兰陵王', '李昴英', '燕穿幕。\n春在深深院落。\n单衣试，龙沫旋薰，又怕东风晓寒薄。\n别来情绪恶。\n瘦得腰围柳弱。\n清明近，正似海棠，怯雨芳踪任飘泊。\n钗留去年约。\n恨易老娇莺，多误灵鹊。\n碧云杳渺天涯各。\n望不断芳草，更迷香絮，回文强写字屡错。\n泪欲注还阁。\n孤酌。\n住春脚。\n便彩局谁，宝轸慵学。\n阶除拾取飞花嚼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15848, '摸鱼儿', '李昴英', '晓风痴、绣帘低舞。\n霏霏香碎红雨。\n燕忙莺懒春无赖，懒为好花遮护。\n浑不顾。\n费多少工夫，做得芳菲聚。\n休颦百五。\n却自恨新年，游疏醉少，光景恁虚度。\n猊烟瘦，困起庭阴正午。\n游丝飞絮无据。\n千林湿翠须臾遍，难绿鬓根霜缕。\n愁绝处。\n怎忍听，声声杜宇深深树。\n东君寄语。\n道去也还来，後期长在，紫陌岁相遇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15849, '摸鱼儿', '李昴英', '敞茅堂、茂林环翠，苔矶低蘸烟浦。\n青蓑混入渔家社，斜日断桥船聚。\n真乐处。\n坐芳草，瓦樽满酒频频注。\n皋禽自舞。\n惯松迳穿云，梅村踏雪，朗笑自来去。\n车乘坠，争似修筇稳步。\n前尘回首俱误。\n安闲得在中年好，抱瓮尚堪蔬圃。\n高眼觑。\n算不识、人间宠辱除巢许。\n风篁解语。\n应共笑群狙，无端喜怒，三四计朝暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15850, '摸鱼儿', '李昴英', '绕西园、粉笼千雉，镜池屏石天造。\n主人意匠工收拾，华屋落成闻早。\n轮奂巧。\n望缥缈、五云深处移蓬岛。\n油幢羽葆。\n指貔虎长驱，鲸鲲网取，电走捷旗报。\n铙吹发，回庑连屯饮犒。\n海山波静烟扫。\n纶巾萧散环珠履，春满绿杨芳草。\n人境好。\n是握穗五翁，福地无尘到。\n芝书在道。\n便整顿乾坤，经营万宇，栋国要元老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15851, '摸鱼儿', '李昴英', '怪朝来、片红初瘦，半分春事风雨。\n丹山碧水含离恨，有脚阳春难驻。\n芳草渡。\n似叫住东君，满树黄鹂语。\n无端杜宇。\n报采石矶头，惊涛屋大，寒色要春护。\n阳关唱，画徘徊东渚。\n相逢知又何处。\n摩挲老剑雄心在，对酒细评今古。\n君此去。\n几万里东南，只手擎天柱。\n长生寿母。\n更稳步安舆，三槐堂上，好看彩衣舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15852, '贺新郎', '李昴英', '绣谷流明帜。\n稳飞舆、茵柔草碧，盖欹松翠。\n遨首意行穷绝顶，彩榭千年胜地。\n远峰断、莽苍烟水。\n护日晴云收午暑，飒长风、振叶生秋思。\n笼雾炷，飘霞袂。\n清明官府歌棠芾。\n且萧闲事外，下看玉城珠市。\n山色骄人逢此客，麈尾霏霏露碎。\n一笑又、羊衔新穗。\n田野欢声和气合，唤觥船、猛为鱼占喜。\n谁会得，醉翁意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15853, '贺新郎', '李昴英', '世羡官高大。\n又谁知、几多卿相，身荣名壤。\n我辈相逢无愧色，彼此苍颜健在。\n又荣易、分携越海。\n写出阳关离别恨，看一行、雁字斜飞界。\n天下宝，愿自爱。\n白衣苍狗须臾改。\n久冥心、鸡虫得失，鹏迟快。\n君带貂蝉头上立，老我荷衣草带。\n肯此膝、向人雅拜。\n远饯元非趋炎者，二十年、相与形骸外。\n义金石，更坚耐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15854, '贺新郎', '李昴英', '谁种蓝田玉。\n碧云深、亭亭月上，水明溪曲。\n羞作时妆儿女态，冷淡冰餐露沐。\n出尘外、风标幽独。\n除了留侯无此貌，便何郎、傅粉终粗俗。\n意凝远，韵清淑。\n凉台向晚微风馥。\n讶银杯羽化，折取戏浮。\n安得梅花如许大，天遣辟除暑溽。\n浑不觉、鹭翘鸥浴。\n可恨妖妃污太液，只东林、社友追游熟。\n宜夜看，灿瑶烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15855, '贺新郎', '李昴英', '细与黄花说。\n是天教、开遇重阳，玉裁金屑。\n老行要寻松竹伴，雅爱山翁鬓雪。\n任满插、追陪节物。\n惟有渊明吾臭味，傍东篱、盘薄芳丛撷。\n便无酒，也清绝。\n芒寒色正孤标洁。\n惯平生、餐霜饮露，倚风迎月。\n不比芙蓉偏妩媚，不比茱萸太烈。\n似隐者、萧闲岩穴。\n至老枝头犹健在，笑纷纷、红紫尘沙汨。\n香耐久，看晚节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15856, '贺新郎', '李昴英', '元日除书湿。\n到而今、西风老矣，驾轺初入。\n自是龙颜深注想，孤凤翔而後集。\n久父老、攀留原隰。\n庾岭经行梅亦喜，小奚奴、背底惟诗笈。\n冰雪操，又谁及。\n昨来容易风云翕。\n便三台两地，也只等闲如拾。\n天马不鸣凡马喑，百步何如五十。\n况汹汹、波涛方急。\n此去一言回天力，著高高、百尺竿头立。\n浇磊，快鲸吸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15857, '贺新郎', '李昴英', '过雨璇空湿。\n浩秋香、光浮桂菊，晓风吹入。\n柳系牙樯应小驻，草草还成胜集。\n又追趁、牡车原隰。\n照座玉人风骨耸，想胸蟠、蕊阙琳琅笈。\n真作者，世难及。\n远山云雾工开翕。\n共朱阑徙倚，总好锦囊收拾。\n老我祗今才思涩，知二争如知十。\n戛金缕、檀敲休急。\n访古夷犹行八境，忆朝阳、鸣凤台端立。\n笔也醉，砚池吸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15858, '贺新郎', '李昴英', '天地中间大。\n纵遨游、登山临水，散人一个。\n学易已来秋又六，肯趁名缰利锁。\n得日日、安闲笑过。\n金马玉堂也曾到，尽不妨、拍手溪头坐。\n风笠，月兰舸。\n今朝记是初生我。\n近小春、黄菊犹葩，早梅将朵。\n拔宅危巅穷胜践，指点尘寰蚁磨。\n看涧底、飞泉珠颗。\n松柏苍苍俱寿相，更千年、雪鹤鸣相和。\n安期老，举杯贺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15859, '水龙吟', '李昴英', '唱恭初意如何，来五十三年矣。\n犁锄颇熟，诗书粗解，簪绅聊耳。\n自信柴愚，真成汲戆，却无刘腻。\n向高秋初度，同时有菊，淡相对、风霜里。\n最癖登山临水。\n又何心、蜗名蝇利。\n俗缘未了，强教肉食，何曾知味。\n无事微吟，会心微笑，逢场微醉。\n把日生、只恁安排，领取百十二岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15860, '水龙吟', '李昴英', '驿飞稳驾高秋，迎人满目清新景。\n秋还有色，芙蓉照水，晨妆对镜。\n雪卷寒芦，字横过雁，渡浮孤艇。\n是骚人行处，腔风调月，香满袖、过梅岭。\n断岸烟收人静。\n雨声乾、桐疏枫冷。\n掀髯独笑，仙翁起舞，卧龙呼醒。\n近小阳春，为梅也合，迟迟鞭影。\n更郁孤、一笑追欢，料得坡翁首肯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15861, '水龙吟', '李昴英', '碧潭新涨浮花，柳阴稠绿波痕腻。\n一声雷鼓，半空雪浪，双龙惊起。\n气压鲸鲵，怒掀鳞鬣，擘开烟水。\n算战争蛮触，雌雄汉楚，总皆一场如此。\n点额许教借一，得头筹、欢呼震地。\n翻嗤浮世，要津搀进，奔波逐利。\n斗了还休，倩渠衔寄，三闾角黍。\n会风云、快出为霖，可但颔明珠睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15862, '水调歌头', '李昴英', '郭外足幽胜，潮入涨溪流。\n舫斋小小一叶，老子日遨游。\n管领白苹红蓼，披戴绿蓑青箬，直钓任沈浮。\n玉楼胞鲈脍，雪阵狎沙鸥。\n个中眠，个中坐，个中讴。\n个中收拾诗料，觞客个中留。\n休羡乘槎博望，且听洞箫赤壁，乐处是瀛洲。\n日月荡双桨，天地一虚舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15863, '水调歌头', '李昴英', '万顷黄湾口，千仞白云头。\n一亭收拾，便觉炎海豁清秋。\n潮候朝昏来去，山色雨晴浓淡，天末送双眸。\n绝域远烟外，高浪舞连艘。\n风景别，胜滕阁，压黄楼。\n胡床老子，醉挥珠玉落南州。\n稳驾大鹏八极，叱起仙羊五石，飞佩过丹丘。\n一笑人间世，机动早惊鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15864, '水调歌头', '李昴英', '地位到公辅，耆艾过稀年。\n几人兼此二美，而况是名贤。\n松柏苍然长健，姜桂老来越辣，劲气九秋天。\n鲠鲠撄鳞语，不改铁心坚。\n说武夷，同此月，瑞三仙。\n公虽居後，瑰奇伟特却光前。\n续得紫阳脉络，了却西山事业，舟楫济商川。\n饮对黄花榭，一酌岁三千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15865, '水调歌头', '李昴英', '野趣在城市，崛起此台高。\n谁移蓬岛，冯夷夜半策灵鳌。\n十万人家碧，四面峰峦涌翠，远岫拍银涛。\n插汉笔双塔，簸两叶轻。\n我乘风，时一到，共嬉遨。\n江山无复偃蹇，弹压有诗豪。\n宝剑孤横星动，铁笛一声云裂，寒月冰宫袍。\n沧海一杯酒，世界眇鸿毛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15866, '念奴娇', '李昴英', '瑶池高会，见云香凤背，风柔鹤膝。\n天遣月卿来拜舞，新拜玺书增秩。\n有母能贤，生儿如此，总是前生佛。\n孙曾戏彩，慈颜一笑闲逸。\n曾向浑尺轩中，共评今古，手写王言绋。\n个里乃翁棠荫在，映得梅仙山碧。\n人爱黄堂，祝萱堂寿，拍拍欢声溢。\n明年宣劝，蟠桃火枣庭实。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15867, '念奴娇', '李昴英', '麦秋时候，薄阴罩炎日，山行乘兴。\n筇屐追随多胜侣，青佩黄冠方领。\n坐石谈玄，听泉濯暑，直上千山顶。\n倚风长啸，籁鸣林谷相应。\n忽涌云气漫空。\n海吹急雨，觉冰微冷。\n洗尽人间名利障，便是蓬莱仙境。\n半日偷闲，一生清福，岂在荣钟鼎。\n青灯深夜，陶然独妙清圣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15868, '瑞鹤仙', '李昴英', '玉城春不夜。\n映月璧寒流，烛蕖光射。\n鳌山海云驾。\n拥遨头箫鼓，锦旗红亚。\n东风近也。\n趁乐岁、良辰多暇。\n想阳和、早遍南州，暖得柳娇桃冶。\n堪画。\n纱笼夹道，露重花珠，尘吹兰麝。\n歌朋舞社。\n玉梅转，闹蛾耍。\n且茧占先探，芋郎戏巧，又卜紫姑灯下。\n听欢声、犹自未归，钿车宝马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15869, '沁园春', '李昴英', '才到中年，节物浑闲，赏心顿轻。\n据随分东风，瓶簪柳雪，应时灯夜，棚缀莲星。\n自一家春，也三杯酒，巧茧堆香笑语声。\n又何须，听那西楼弦管，南陌箫笙。\n平生。\n黄卷青灯。\n肯珠翠奢华八尺檠。\n欲趁队闲嬉，雕鞍宝马，回头猛忆，破案囊萤。\n邻曲渔歌，庭除鹤舞，尘外冰轮彻骨清。\n人闲处，这炯然方寸，一点长明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15870, '满江红', '李昴英', '薄冷催霜，碧空豁、飞鸿斜度。\n□九日、御风绝顶，下看尘宇。\n滕阁芳筵笺笔妙，龙山胜践旌旗驻。\n料山灵、也要可人游，成佳趣。\n吹帽堕，羞千古。\n题饧字，非吾侣。\n却坐间著得，煮茶桑苎。\n万里寒云迷北斗，望远峰夕照频西顾。\n且满浮、大白送黄花，剑休舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15871, '满江红', '李昴英', '人似梅花，峭玉立、岁寒风节。\n新圃辟、种梅千树，幻成南雪。\n池碎瀑声荷捧雨，径涵秋影篁筛月。\n唤石君、错落坐庭前，红尘绝。\n嫌聒耳，筝戛。\n慵著眼，俳优狎。\n但一觞一咏，放怀开阔。\n涌地池亭工掩映，擎天柱石觇施设。\n待枝头、金颗可调羹，休轻折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15872, '菩萨蛮', '李昴英', '云山叠叠双眸短。\n梦魂夜趁行人远。\n千里共襟期。\n吟风饮月时。\n碧溪穿翠峡。\n雪意蓬萧飒。\n安得翅飞来。\n冲寒同访梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15873, '渔家傲', '李昴英', '重著夹罗犹怯冷。\n隔帘拜祝团圆镜。\n取片龙涎安古鼎。\n香阁静。\n横窗写出梅花影。\n寒鹊颤枝飞不定。\n回纹刺就更筹永。\n小玉欣眠呼不醒。\n霜气紧。\n丽谯吹动梅花引。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15874, '西江月', '李昴英', '小载池心月，长虹夸水中天。\n主人情重客留连。\n便欲乘风寒殿。\n霜竹且传秋信，镜蕖不作春妍。\n夜凉正好倒金船。\n朔饮而今再见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15875, '浣溪沙', '李昴英', '笋玉纤纤拍扇纨。\n戏拈荷叶起文鸳。\n水亭初试小龙团。\n拜月深深频祝愿，花枝低压髻云偏。\n倩人解梦语喧喧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15876, '城头月', '李昴英', '工夫作用中宵昼。\n点化无中有。\n真气长存，童颜不改，底用呵磨皱。\n一身二五之精媾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15877, '琐窗寒', '吴文英', '绀缕堆云，清腮润玉，汜人初见。\n蛮腥未洗，海客一怀凄惋。\n渺征槎、去乘阆风，占香上国幽心展。\n□遗芳掩色，真姿凝澹，返魂骚畹。\n一盼。\n千金换。\n又笑伴鸱夷，共归吴苑。\n离烟恨水，梦杳南天秋晚。\n比来时、瘦肌更销，冷薰沁骨悲乡远。\n最伤情、送客咸阳，佩结西风怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15878, '尉迟杯', '吴文英', '垂杨径。\n洞钥启，时见流莺迎。\n涓涓暗谷流红，应有缃桃千顷。\n临池笑靥，春色满、铜华弄妆影。\n记年时、试酒湖阴，褪花曾采新杏。\n蛛窗绣网玄经，才石砚开奁，雨润云凝。\n小小蓬莱香一掬，愁不到、朱娇翠靓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15879, '渡江云三犯・渡江云', '吴文英', '羞红颦浅恨，晚风为落，片绣点重茵。\n旧堤分燕尾，桂棹轻鸥，宝勒倚残云。\n千丝怨碧，渐路入、仙坞迷津。\n肠漫回，隔花时见，背面楚腰身。\n逡巡。\n题门惆怅，堕履牵萦，数幽期难准。\n还始觉、留情缘眼，宽带因春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15880, '三部乐', '吴文英', '江初飞，荡万里素云，际空如沐。\n咏情吟思，不在秦筝金屋。\n夜潮上，明月芦花，傍钓蓑梦远，句清敲玉。\n翠罂汲晓，乃一声秋曲。\n越装片篷障雨，瘦半竿渭水，鹭汀幽宿。\n那知暖袍挟锦，低帘笼烛。\n鼓春波、载花万斛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15881, '霜叶飞', '吴文英', '断烟离绪。\n关心事，斜阳红隐霜树。\n半壶秋水荐黄花，香西风雨。\n纵玉勒、轻飞迅羽。\n凄凉谁吊荒台古。\n记醉蹋南屏，彩扇咽、寒蝉倦梦，不知蛮素。\n聊对旧节传杯，尘笺蠹管，断阕经岁慵赋。\n小蟾斜影转东篱，夜冷残蛩语。\n早白发、缘愁万缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15882, '瑞鹤仙', '吴文英', '泪荷抛碎璧。\n正漏云筛雨，斜捎窗隙。\n林声怨秋色。\n对小山不迭，寸眉愁碧。\n凉欺岸帻。\n暮砧催、银屏翦尺。\n最无聊、燕去堂空，旧幕暗尘罗额。\n行客。\n西园有分，断柳凄花，似曾相识。\n西风破屐。\n林下路，水边石。\n念寒蛩残梦，归鸿心事，那听江村夜笛。\n看雪飞、苹底芦梢，未如鬓白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15883, '瑞鹤仙', '吴文英', '晴丝牵绪乱。\n对沧江斜日，花飞人远。\n垂杨暗吴苑。\n正旗亭烟冷，河桥风暖。\n兰情蕙盼。\n惹相思、春根酒畔。\n又争知、吟骨萦销，渐把旧衫重翦。\n凄断。\n流红千浪，缺月孤楼，总难留燕。\n歌尘凝扇。\n待凭信，拌分钿。\n试挑灯欲写，还依不忍，笺幅偷和泪卷。\n寄残云、剩雨蓬莱，也应梦见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15884, '瑞鹤仙', '吴文英', '藕心抽莹茧。\n引翠针行处，冰花成片。\n金门从回辇。\n两玉凫飞上，绣绒尘软。\n丝侍宴。\n曳天香、春风宛转。\n傍星辰、直上无声，缓蹑素云归晚。\n奇践。\n平康得意，醉踏香泥，润红沾线。\n良工诧见。\n吴蚕唾，海沈楦。\n任真珠装缀，春申客屦，今日风流雾散。\n待宣供、禹步宸游，退朝燕殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15885, '瑞鹤仙', '吴文英', '乱云生古峤。\n记旧游惟怕，秋光不早。\n人生断肠草。\n叹如今摇落，暗惊怀抱。\n谁临晚眺。\n吹台高、霜歌缥缈。\n想西风、此处留情，肯著故人衰帽。\n闻道。\n萸香西市，酒熟东邻，浣花人老。\n金鞭袅。\n追吟赋，倩年少。\n想重来新雁，伤心湖上，销减红深翠窈。\n小楼寒、睡起无聊，半帘晚照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15886, '瑞鹤仙', '吴文英', '记年时茂苑。\n正画堂凝香，璇奎初焕。\n天边岁华转。\n向九重春近，仙桃传宴。\n银罂翠管。\n宝香飞、蓬莱小殿。\n荷玉皇、恩重千秋，翠麓峻齐云汉。\n须看。\n鸿飞高处，地阔天宽，弋人空羡。\n梅清水暖。\n苕溪上，几吟卷。\n算金门听漏，玉墀班早，赢得风霜满面。\n总不如、绿野身安，镜重未晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15887, '瑞鹤仙', '吴文英', '辘轳春又转。\n记旋草新词，江头凭雁。\n乘槎上银汉。\n想车尘才踏，东华红软。\n何时赐见。\n漏声移、深宫夜半。\n问莼鲈、今岁西风，未觉岁华迟晚。\n一片。\n丹心白发，露滴研朱，雅陪清宴。\n班回柳院。\n蒲团底，小禅观。\n望罘明月，初圆此夕，应共婵娟茂苑。\n愿年年、玉兔长生，耸秋井乾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15888, '瑞鹤仙', '吴文英', '夜寒吴馆窄。\n渐酒阑烛暗，犹分香泽。\n轻帆展为翮。\n送高鸿飞过，长安南陌。\n渔矶旧迹。\n有陈蕃、虚床挂壁。\n掩庭扉，蛛网黏花，细草摇春碧。\n还忆。\n洛阳年少，风露秋檠，岁华如昔。\n长吟堕帻。\n暮潮送，富春客。\n算玉堂不染，梅花清梦，宫漏声中夜直。\n正逋仙、清瘦黄昏，几时觅得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15889, '瑞鹤仙', '吴文英', '彩云栖翡翠。\n听凤笙吹下，飞天际。\n晴霞翦轻袂。\n澹春姿雪态，寒梅清。\n东皇有意。\n旋安排、阑干十二。\n早不知、为雨为云，尽日建章门闭。\n堪比。\n红绡纤素，紫燕轻盈，内家标致。\n游仙旧事。\n星斗下，夜香里。\n□华峰□□，纸屏横幅，春色长供午睡。\n更醉乘、玉井秋风，采花弄水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15890, '满江红', '吴文英', '云气楼台，分一派、沧浪翠蓬。\n开小景、玉盆寒浸，巧石盘松。\n风送流花时过岸，浪摇晴练欲飞空。\n算鲛宫、祗隔一红尘，无路通。\n神女驾、凌晓风。\n明月佩，响丁东。\n对两蛾犹锁，怨绿烟中。\n秋色未教飞尽雁，夕阳长是坠疏钟。\n又一声、乃过前岩，移钓篷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15891, '满江红', '吴文英', '结束萧仙，啸梁鬼、依还未灭。\n荒城外、无聊闲看，野烟一抹。\n梅子未黄愁夜雨，榴花不见簪秋雪。\n又重罗、红字写香词，年时节。\n帘底事，凭燕说。\n合欢缕，双条脱。\n自香消红臂，旧情都别。\n湘水离魂菰叶怨，扬州无梦铜华阙。\n倩卧箫、吹裂晚天云，看新月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15892, '解连环', '吴文英', '暮檐凉薄。\n疑清风动竹，故人来邈。\n渐夜久、闲引流萤，弄微照素怀，暗呈纤白。\n梦远双成，凤笙杳、玉绳西落。\n掩帷倦入，又惹旧愁，汗香阑角。\n银瓶恨沈断索。\n叹梧桐未秋，露井先觉。\n抱素影、明月空闲，早尘损丹青，楚山依约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15893, '解连环', '吴文英', '思和云结。\n断江楼望睫，雁飞无极。\n正岸柳、衰不堪攀，忍持赠故人，送秋行色。\n岁晚来时，暗香乱、石桥南北。\n又长亭暮雪，点点泪痕，总成相忆。\n杯前寸阴似掷。\n几酬花唱月，连夜浮白。\n省听风、听雨笙箫，向别枕倦醒，絮扬空碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15894, '夜飞鹊・夜飞鹊慢', '吴文英', '金规印遥汉，庭浪无纹。\n清雪冷沁花薰。\n天衔曾醉美人畔，凉枝移插乌巾。\n西风骤惊散，念棱悬愁结，蒂翦离恨。\n中郎旧恨，寄横竹、吹裂哀云。\n空剩露华烟彩，人影断幽坊，深闭千门。\n浑似飞仙入梦，袜罗微步，流水青苹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15895, '一寸金', '吴文英', '秋入中山，臂隼牵卢纵长猎。\n见骇毛飞雪，章台献颖，腰束缟，汤沐疏邑。\n管刊琼牒。\n苍梧恨、帝娥暗泣。\n陶郎老、憔悴玄香，禁苑犹催夜俱入。\n自叹江湖，雕龙心尽，相携蠹鱼箧。\n念醉魂悠扬，折钗锦字，黠髯掀舞，流觞春帖。\n还倚荆溪楫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15896, '一寸金', '吴文英', '秋压更长，看见娥瘦如束。\n正古花摇落，寒蛩满地，参梅吹老，玉龙横竹。\n霜被芙蓉宿。\n红绵透、尚欺暗烛。\n年年记、一种凄凉，绣幌金圆挂香玉。\n顽老情怀，都无欢事，良宵爱幽独。\n叹画图难仿，橘村砧思，笠蓑有约，莼洲渔屋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15897, '绕佛阁', '吴文英', '夜空似水，横汉静立，银浪声杳。\n瑶镜奁小。\n素娥乍起、楼心弄孤照。\n絮云未巧。\n梧韵露井，偏借秋早。\n晴暗多少。\n怕教彻胆，蟾光见怀抱。\n浪迹尚为客，恨满长安千古道。\n还记暗萤、穿帘街语悄。\n叹步影归来，人鬓花老。\n紫箫天渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15898, '绕佛阁', '吴文英', '霞艳锦，星媛夜织，河汉鸣杼。\n红翠万缕。\n送幽梦与、人闲绣芳句。\n怨宫恨羽。\n孤风剑漫倚，无限凄楚。\n□□□□。\n赋情缥缈、东风扬花絮。\n镜里半髯雪，向老春深莺晓处。\n长闭翠阴、幽坊杨柳户。\n看故苑离离，城外禾黍。\n短藜青屦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15899, '拜星月慢', '吴文英', '绛雪生凉，碧霞笼夜，小立中庭芜地。\n昨梦西湖，老扁舟身世。\n叹游荡，暂赏、吟花酌露尊俎，冷玉红香洗。\n眼眩魂迷，古陶洲十里。\n翠参差、澹月平芳砌。\n砖花、小浪鱼鳞起。\n雾盎浅障青罗，洗湘娥春腻。\n荡兰烟、麝馥浓侵醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15900, '水龙吟', '吴文英', '艳阳不到青山，古阴冷翠成秋苑。\n吴娃点黛，江妃拥髻，空遮断。\n树密藏溪，草深迷市，峭云一片。\n二十年旧梦，轻鸥素约，霜丝乱、朱颜变。\n龙吻春霏玉溅。\n煮银瓶、羊肠车转。\n临泉照影，清寒沁骨，客尘都浣。\n鸿渐重来，夜深华表，露零鹤怨。\n把闲愁换与，楼前晚色，棹沧波远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15901, '水龙吟', '吴文英', '夜分溪馆渔灯，巷声乍寂西风定。\n河桥径远，玉箫吹断，霜丝舞影。\n薄絮秋云，澹蛾山色，宦情归兴。\n怕烟江渡後，桃花又泛，宫沟上、春流紧。\n新句欲题还省。\n透香煤、重牒误隐。\n西园已负，林亭移酒，松泉荐茗。\n携手同归处，玉奴唤、绿窗春近。\n想骄骢、又踏西湖，二十四番花信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15902, '水龙吟', '吴文英', '有人独立空山，翠髯未觉霜颜老。\n新香秀粒，浓光绿浸，千年春小。\n布影参旗，障空云盖，沈沈秋晓。\n驷苍虬万里，笙吹凤女，骖飞乘、天风袅。\n般巧。\n霜斤不到。\n汉游仙、相从最早。\n皴鳞细雨，层阴藏月，朱弦古调。\n问讯东桥，故人南岭，倚天长啸。\n待凌霄谢了，山深岁晚，素心才表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15903, '水龙吟', '吴文英', '望中璇海波新，泛槎又币银河转。\n金风细袅，龙枝声奏，钧箫秋远。\n南极飞仙，夜来催驾，祥光重见。\n紫霄承露掌，瑶池荫密，蟠桃秀、螽莲绽。\n新栋晴凌汉。\n半凉生、兰檠书卷。\n绣裳五色，昆台十二，香深帘卷。\n花萼楼高处，连清晓、千秋传宴。\n赐长生玉字，鸾回凤舞，下蓬莱殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15904, '水龙吟', '吴文英', '望春楼外沧波，旧年照眼青铜镜。\n炼成宝月，飞来天上，银河流影。\n绀玉钩帘处，横犀尘、天香分鼎。\n记殷云殿锁，裁花翦露，曲江畔、春风劲。\n槐省。\n红尘昼静，午朝回、吟生晚兴。\n春霖绣笔，莺边清晓，金狨旋整。\n阆苑芝仙貌，生绡对、绿窗深景。\n弄琼英数点，宫梅信早，占年光永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15905, '水龙吟', '吴文英', '几番时事重论，座中共惜斜阳下。\n今朝翦柳，东风送客，功名近也。\n约住飞花，暂听留燕，更攀情话。\n问千牙过阙，一封入奏，忠孝事、都应写。\n闻道兰台清暇。\n载鸱夷、烟江一舸。\n贞元旧曲，如今谁听，惟公和寡。\n儿骑空迎，舜瞳回盼，玉阶前借。\n便急回暖律，天边海上，正春寒夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15906, '水龙吟', '吴文英', '外湖北岭云多，小园暗碧莺啼处。\n朝回胜赏，墨池香润，吟船系雨。\n霓节千妃，锦帆一箭，携将春去。\n算归期未卜，青烟散後，春城咏、飞花句。\n黄鹤楼头月午。\n奏玉龙、江梅解舞。\n薰风紫禁，严更清梦，思怀几许。\n秋水生时，赋情还在，南屏别墅。\n看章台走马，长堤种取，柔丝千树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15907, '水龙吟', '吴文英', '澹云笼月微黄，柳丝浅色东风紧。\n夜寒旧事，春期新恨，眉山碧远。\n尘陌飘香，绣帘垂户，趁时妆面。\n钿车催去急，珠囊袖冷，愁如海、情一线。\n犹记初来吴苑。\n未清霜、飞惊双鬓。\n嬉游是处，风光无际，舞葱歌。\n陈迹征衫，老容华镜，欢都尽。\n向残灯梦短，梅花晓角，为谁吟怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15908, '水龙吟', '吴文英', '杜陵折柳狂吟，砚波尚湿红衣露。\n仙桃宴早，江梅春近，还催客句。\n宫漏传鸡，禁门嘶骑，宦情熟处。\n正黄编夜展，天香字暖，春葱翦、红蜜炬。\n宫帽鸾枝醉舞。\n思飘扬、仙风举。\n星罗万卷，云驱千阵，飞毫海雨。\n长寿杯深，探春腔稳，江湖同赋。\n又看看、便系金狨莺晓，傍西湖路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15909, '玉烛新', '吴文英', '花穿帘隙透。\n向梦里销春，酒中延昼。\n嫩篁细掐，相思字、堕粉轻黏袖。\n章台别後，展绣络、红荐香旧。\n□□□，应数归舟，愁凝画阑眉柳。\n移灯夜语西窗，逗晓帐迷香，问何时又。\n素纨乍试，还忆是、绣懒思酸时候。\n兰清蕙秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15910, '解语花', '吴文英', '门横皱碧，路入苍烟，春近江南岸。\n暮寒如翦。\n临溪影、一一半斜清浅。\n飞弄晚。\n荡千里、暗香平远。\n端正看，琼树三枝，总似兰昌见。\n酥莹云容夜暖。\n伴兰翘清瘦，箫凤柔婉。\n冷云荒翠，幽栖久、无语暗申春怨。\n东风半面。\n料准拟、何郎词卷。\n欢未阑，烟雨青黄，宜昼阴庭馆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15911, '解语花', '吴文英', '檐花旧滴，帐烛新啼，香润残冬被。\n澹烟疏绮。\n凌波步、暗阻傍墙挑荠。\n梅痕似洗。\n空点点、年华别泪。\n花鬓愁，钗股笼寒，彩燕沾云腻。\n还斗辛盘葱翠。\n念青丝牵恨，曾试纤指。\n雁回潮尾。\n征帆去、似与东风相避。\n泥云万里。\n应翦断、红情绿意。\n年少时，偏爱轻怜，和酒香宜睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15912, '庆春宫・高阳台', '吴文英', '春屋围花，秋池沿草，旧家锦藉川原。\n莲花分津，桃边迷路，片红不到人间。\n乱篁苍暗，料惜把、行题共删。\n小晴帘卷，独占西墙，一镜清寒。\n风光未老吟潘。\n嘶骑征尘，祗付凭阑。\n鸣瑟传杯，辟邪翻烬。\n系船香斗春宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15913, '庆春宫・高阳台', '吴文英', '残叶翻浓，馀香栖苦，障风怨动秋声。\n云影摇寒，波尘销腻，翠房人去深扃。\n昼成凄黯，雁飞过、垂杨转青。\n阑干横暮，酥印痕香，玉腕谁凭。\n菱花乍失娉婷。\n别岸围红，千艳倾城。\n重洗清杯，同追深夜，豆花寒落愁灯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15914, '塞垣春', '吴文英', '漏瑟侵琼管。\n润鼓借、烘炉暖。\n藏钩怯冷，画鸡临晓，怜语莺啭。\n绿窗、细咒浮梅盏。\n换蜜炬、花心短。\n梦惊回，林鸦起，曲屏春事天远。\n迎路柳丝裙，看争拜东风，盈灞桥岸。\n髻落宝钗寒，恨花胜迟燕。\n渐街帘影转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15915, '宴清都', '吴文英', '翠羽飞梁苑。\n连催发，暮樯留话江燕。\n尘街堕珥，瑶扉乍钥，彩绳双。\n新烟暗叶成阴，效翠妩、西陵送远。\n又趁得、蕊露天香，春留建章花晚。\n归来笑折仙桃，琼楼宴萼，金漏催箭。\n兰亭秀语，乌丝润墨，汉宫传玩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15916, '宴清都', '吴文英', '绣幄鸳鸯柱。\n红情密，腻云低护秦树。\n芳根兼倚，花梢钿合，锦屏人妒。\n东风睡足交枝，正梦花、瑶钗燕股。\n障滟蜡、满照欢丛，嫠蟾冷落羞度。\n人间万感幽单，华清惯浴，春盎风露。\n连鬟并暖，同心共结，向承恩处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15917, '宴清都', '吴文英', '万壑蓬莱路。\n非烟霁，五云城阙深处。\n璇源媲凤，瑶池种玉，练颜金姥。\n长虹梦入仙怀，便洗日、铜华翠渚。\n向瑞世、独占长春，蟠桃正饱风露。\n殷勤汉殿传卮，隔江云起，暗飞青羽。\n南山寿石，东周宝鼎，千秋巩固。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15918, '宴清都', '吴文英', '翠匝西门柳。\n荆州昔，未来时正春瘦。\n如今剩舞，西风旧色，胜东风秀。\n黄粱露湿秋江，转万里、云樯蔽昼。\n正虎落、马静晨嘶，连营夜沈刁斗。\n含章换几桐阴，千官邃幄，韶凤还奏。\n席前夜久，天低宴密，御香盈袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15919, '宴清都', '吴文英', '柳色春阴重。\n东风力，快将云雁高送。\n书檠细雨，吟窗乱雪，井寒笔冻。\n家林秀橘霜老，笑分得、蟾边桂种。\n应茂苑、斗转苍龙，唯潮献奇吴凤。\n玉眉暗隐华年，凌云气压，千载云梦。\n名笺澹墨，恩袍翠草，紫骝青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15920, '宴清都', '吴文英', '万里关河眼。\n愁凝处，渺渺残照红敛。\n天低远树，潮分断港，路回淮甸。\n吟鞭又指孤店。\n对玉露金风送晚。\n恨自古、才子佳人，此景此情多感。\n吴王故苑。\n别来良朋雅集，空叹蓬转。\n挥毫记烛，飞觞赶月，梦销香断。\n区区去程何限。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15921, '齐天乐', '吴文英', '三千年事残鸦外，无言倦凭秋树。\n逝水移川，高陵变谷，那识当时神禹。\n幽云怪雨。\n翠萍湿空梁，夜深飞去。\n雁起青天，数行书似旧藏处。\n寂寥西窗久坐，故人悭会遇，同翦灯语。\n积藓残碑，零圭断璧，重拂人间尘土。\n霜红罢舞。\n漫山色青青，雾朝烟暮。\n岸锁春船，画旗喧赛鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15922, '齐天乐', '吴文英', '芙蓉心上三更露，茸香漱泉玉井。\n自洗银舟，徐开素酌，月落空杯无影。\n庭阴未暝。\n度一曲新蝉，韵秋堪听。\n瘦骨侵冰，怕惊纹簟夜深冷。\n当时湖上载酒，翠云开处共，雪面波镜。\n万感琼浆，千茎鬓雪，烟锁蓝桥花径。\n留连暮景。\n但偷觅孤欢，强宽秋兴。\n醉倚修篁，晚风吹半醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15923, '齐天乐', '吴文英', '凌朝一片阳台影，飞来太空不去。\n栋与参横，帘钩斗曲，西北城高几许。\n天声似语。\n便阊阖轻排，虹河平溯。\n问几阴晴，霸吴平地漫今古。\n西山横黛瞰碧，眼明应不到，烟际沈鹭。\n卧笛长吟，层霾乍裂，寒月溟千里。\n凭虚醉舞。\n梦凝白阑干，化为飞雾。\n净洗青红，骤飞沧海雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15924, '齐天乐', '吴文英', '新烟初试花如梦，疑收楚峰残雨。\n茂苑人归，秦楼燕宿，同惜天涯为旅。\n游情最苦。\n早柔绿迷津，乱莎荒圃。\n数树梨花，晚风吹堕半汀鹭。\n流红江上去远，翠尊曾共醉，云外别墅。\n澹月秋千，幽香巷陌，愁结伤春深处。\n听歌看舞。\n驻不得当时，柳蛮樱素。\n睡起恹恹，洞箫谁院宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15925, '齐天乐', '吴文英', '竹深不放斜阳度，横披澹墨林沼。\n断莽平烟，残莎剩水，宜得秋深才好。\n荒亭旋扫。\n正著酒寒轻，弄花春小。\n障锦西风，半围歌袖半吟草。\n独游清兴易懒，景饶人未胜，乐事长少。\n柳下交车，尊前岸帻，同抚云根一笑。\n秋香未老。\n渐风雨西城，暗客帽。\n背月移舟，乱鸦溪树晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15926, '齐天乐', '吴文英', '曲尘犹沁伤心水，歌蝉暗惊春换。\n露藻清啼，烟萝澹碧，先结湖山秋怨。\n波帘翠卷。\n叹霞薄轻绡，泛人重见。\n傍柳追凉，暂疏怀袖负纨扇。\n南花清斗素靥，画船应不载，坡静诗卷。\n泛酒芳筒，题名蠹壁，重集湘鸿江燕。\n平芜未翦。\n怕一夕西风，镜心红变。\n望极愁生，暮天菱唱远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15927, '齐天乐', '吴文英', '烟波桃叶西陵路，十年断魂潮尾。\n古柳重攀，轻鸥聚别，陈迹危亭独倚。\n凉乍起。\n渺烟碛飞帆，暮山横翠。\n但有江花，共临秋镜照憔悴。\n华堂烛暗送客，眼波回盼处，芳艳流水。\n素骨凝冰，柔葱蘸雪，犹忆分瓜深意。\n清尊未洗。\n梦不湿行云，漫沾残泪。\n可惜秋宵，乱蛩疏雨里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15928, '齐天乐', '吴文英', '玉皇重赐瑶池宴，琼筵第二十四。\n万象澄秋，群裾曳玉，清澈冰壶人世。\n鳌峰对起。\n许分得钧天，凤丝龙吹。\n翠羽飞来，舞鸾曾赋曼桃字。\n鹤胎曾梦电绕，桂根看骤长，玉干金蕊。\n少海波新，芳茅露滴，凉入堂阶彩戏。\n香霖乍洗。\n拥莲媛三千，羽裳风佩。\n圣姥朝元，炼颜银汉水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15929, '齐天乐', '吴文英', '馀香才润鸾绡汗，秋风夜来先起。\n雾锁林深，蓝浮野阔，一笛渔蓑鸥外。\n红尘万里。\n就中决银河，冷涵空翠。\n岸觜沙平，水杨阴下晚初舣。\n桃溪人住最久，浪吟谁得到，兰蕙疏绮。\n砚色寒云，签声乱叶，蕲竹纱纹如水。\n笙歌醉里。\n步明月丁东，静传环佩。\n更展芳塘，种花招燕子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15930, '丹凤吟', '吴文英', '丽景长安人海，避影繁华，结庐深寂。\n灯窗雪户，光映夜寒东壁。\n心凋鬓改，镂冰刻水，缥简离离，风签索索。\n怕遣花虫蠹粉，自采秋芸熏架，香泛纤碧。\n更上新梯窈窕，暮山澹著城外色。\n旧雨江湖远，问桐阴门巷，燕曾相识。\n吟壶天小，不觉翠蓬云隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15931, '扫花游・扫地游', '吴文英', '冷空澹碧，带翳柳轻云，护花深雾。\n艳晨易午。\n正笙箫竞渡，绮罗争路。\n骤卷风埃，半掩长蛾翠妩。\n散红缕。\n渐红湿杏泥，愁燕无语。\n乘盖争避处。\n就解佩旗亭，故人相遇。\n恨春太妒。\n溅行裙更惜，凤钩尘污。\n酹入梅根，万点啼痕暗树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15932, '扫花游・扫地游', '吴文英', '水云共色，渐断岸飞花，雨声初峭。\n步帷素袅。\n想玉人误惜，章台春老。\n岫敛愁蛾，半洗铅华未晓。\n舣轻棹。\n似山阴夜晴，乘兴初到。\n心事春缥缈。\n记遍地梨花，弄月斜照。\n旧时斗草。\n恨凌波路钥，小庭深窈。\n冻涩琼箫，渐入东风郢调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15933, '扫花游・扫地游', '吴文英', '草生梦碧，正燕子帘帏，影迟春午。\n倦茶荐乳。\n看风签乱叶，老沙昏雨。\n古简篇，种得云根疗蠹。\n最清楚。\n带明月自锄，花外幽圃。\n醒眼看醉舞。\n到应事无心，与闲同趣。\n小山有语。\n恨逋仙占却，暗香吟赋。\n暖通书床，带草春摇翠露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15934, '扫花游・扫地游', '吴文英', '水园沁碧，骤夜雨飘红，竟空林岛。\n艳春过了。\n有尘香坠钿，尚遗芳草。\n步绕新阴，渐觉交枝径小。\n醉深窈。\n爱绿叶翠圆，胜看花好。\n芳架雪未扫。\n怪翠被佳人，困迷清晓。\n柳丝系棹。\n问阊门自古，送春多少。\n倦蝶慵飞，故扑簪花破帽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15935, '扫花游・扫地游', '吴文英', '暖波印日，倒秀影秦山，晓鬟梳洗。\n步帷艳绮。\n正梁园未雪，海棠犹睡。\n藉绿盛红，怕委天香到地。\n画船系。\n舞西湖暗黄，虹卧新霁。\n天梦春枕被。\n和凤筑东风，宴歌曲水。\n海宫对起。\n灿骊光乍湿，杏梁云气。\n夜色瑶台，禁蜡初传翡翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15936, '应天长', '吴文英', '丽花斗靥，清麝溅尘，春声遍满芳陌。\n竟路障空云幕，冰壶浸霞色。\n芙蓉镜，词赋客。\n竞绣笔、醉嫌天窄。\n素娥下，小驻轻镳，眼乱红碧。\n前事顿非昔，故苑年光，浑与世相隔。\n向暮巷空人绝，残灯耿尘壁。\n凌波恨，帘户寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15937, '风流子', '吴文英', '金谷已空尘。\n薰风转、国色返春魂。\n半雪醉霜，舞低鸾翅，绛笼蜜炬，绿映龙盆。\n窈窕绣窗人睡起，临砌脉无言。\n慵整堕鬟，怨时迟暮，可怜憔悴，啼雨黄昏。\n轻桡移花市，秋娘渡、飞浪溅湿行裙。\n二十四桥南北，罗荐香分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15938, '风流子', '吴文英', '温柔酣紫曲，扬州路、梦绕翠盘龙。\n似日长傍枕，堕妆偏髻，露浓如酒，微醉红。\n自别楚娇天正远，倾国见吴宫。\n银烛夜阑，暗闻香泽，翠阴秋寂，重返春风。\n芳期嗟轻误，花君去、肠断妾若为容。\n惆怅舞衣叠损，露绮千重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15939, '过秦楼', '吴文英', '藻国凄迷，曲澜澄映，怨入粉烟蓝雾。\n香笼麝水，腻涨红波，一镜万妆争妒。\n湘女归魂，佩环玉冷无声，凝情谁诉。\n又江空月堕，凌波尘起，彩鸳愁舞。\n还暗忆、钿合兰桡，丝牵琼腕，见的更怜心苦。\n玲珑翠屋，轻薄冰绡，稳称锦云留住。\n生怕哀蝉，暗惊秋被红衰，啼珠零露。\n能西风老尽，羞趁东风嫁与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15940, '法曲献仙音', '吴文英', '风拍波惊，露零秋觉，断绿衰红江上。\n艳拂潮妆，澹凝冰靥，别翻翠池花浪。\n过数点斜阳雨，啼绡粉痕冷。\n宛相向。\n指汀洲、素云飞过，清麝洗、玉井晓霞佩响。\n寸藕折长丝，笑何郎、心似春荡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15941, '法曲献仙音', '吴文英', '落叶霞翻，败窗风咽，暮色凄凉深院。\n瘦不关秋，泪缘轻别，情消鬓霜千点。\n怅翠冷搔头燕，那能语恩怨。\n紫箫远。\n记桃根、向随春渡，愁未洗、铅水又将恨染。\n粉缟涩离箱，忍重拈、灯夜裁翦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15942, '还京乐', '吴文英', '宴兰溆，促奏丝萦管裂飞繁响。\n似汉宫人去，夜深独语，胡沙凄哽。\n对雁斜玫柱，琼琼弄月临秋影。\n凤吹远，河汉去杳，天风飘冷。\n泛清商竟。\n转铜壶敲漏，瑶床二八青娥，环佩再整。\n菱歌四碧无声，变须臾、翠翳红暝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15943, '塞翁吟', '吴文英', '草色新宫绶，还跨紫陌骄骢。\n好花是，晚开红。\n冷菊最香浓。\n黄帘绿幕萧萧梦，灯外换几秋风。\n叙往约，桂花宫。\n为别翦珍丛。\n雕栊。\n行人去、秦腰褪玉，心事称、吴妆晕浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15944, '塞翁吟', '吴文英', '有约西湖去，移棹晓折芙蓉。\n算才是，称心红。\n染不尽薰风。\n千桃过眼春如梦，还认锦叠云重。\n弄晚色，旧香中。\n旋撑入深丛。\n从容。\n情犹赋、冰车健笔，人未老、南屏翠峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15945, '丁香结', '吴文英', '香袅红霏，影高银烛，曾纵夜游浓醉。\n正锦温琼腻。\n被燕踏、暖雪惊翻庭砌。\n马嘶人散後，秋风换、故园梦里。\n吴霜融晓，陡觉暗动偷春花意。\n还似。\n海雾冷仙山，唤觉环儿半睡。\n浅薄朱唇，娇羞艳色，自伤时背。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15946, '六么令', '吴文英', '露蛩初响，机杼还催织。\n婺星为情慵懒，伫立明河侧。\n不见津头艇子，望绝南飞翼。\n云梁千尺。\n尘缘一点，回首西风又陈迹。\n那知天上计拙，乞巧楼南北。\n瓜果几度凄凉，寂寞罗池客。\n人事回廊缥缈，谁见金钗擘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15947, '蕙兰芳引', '吴文英', '空翠染云，楚山迥、故人南北。\n秀骨冷盈盈，清洗九秋涧绿。\n奉车旧畹，料未许、千金轻价。\n浅笑还不语，蔓草罗裙一幅。\n素女情多，阿真娇重，唤起空谷。\n弄野色烟姿，宜扫怨蛾澹墨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15948, '隔浦莲近・隔浦莲近拍', '吴文英', '榴花依旧照眼。\n愁褪红丝腕。\n梦绕烟江路，汀菰绿薰风晚。\n年少惊送远。\n吴蚕老、恨绪萦抽茧。\n旅情懒。\n扁舟系处，青帘浊酒须换。\n一番重午，旋买香蒲浮盏。\n新月湖光荡素练。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15949, '垂丝钓近・垂丝钓', '吴文英', '听风听雨，春残花落门掩。\n乍倚玉阑，旋翦夭艳。\n携醉靥。\n放溯溪游缆。\n波光撼。\n映烛花黯澹。\n碎霞澄水，吴宫初试菱鉴。\n旧情顿减。\n孤负深杯滟。\n衣露天香染。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15950, '荔枝香近・荔枝香', '吴文英', '锦带吴钩，征思横雁水。\n夜吟敲落霜红，船傍枫桥系。\n相思不管年华，唤酒吴娃市。\n因话、驻马新堤步秋绮。\n淮楚尾。\n暮云送、人千里。\n细雨南楼，香密锦温曾醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15951, '荔枝香近・荔枝香', '吴文英', '睡轻时闻，晚鹊噪庭树。\n又说今夕天津，西畔重欢遇。\n蛛丝暗锁红楼，燕子穿帘处。\n天上、未比人间更情苦。\n秋鬓改，妒月姊、长眉妩。\n过雨西风，数叶井梧愁舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15952, '西河', '吴文英', '春乍霁。\n清涟画舫融泄。\n螺云万叠暗凝愁，黛蛾照水。\n漫将西子比西湖，溪边人更多丽。\n步危径、攀艳蕊。\n掬霞到手红碎。\n青蛇细折小回廊，去天半咫。\n画阑日暮起东风，棋声吹下人世。\n海棠藉雨半绣地。\n正残寒、初御罗绮。\n除酒销春何计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15953, '浪淘沙慢', '吴文英', '梦仙到、吹笙路杳，度云滑。\n溪谷冰绡未裂。\n金铺昼锁乍掣。\n见竹静、梅深春海阔。\n有新燕、帘底低说。\n念汉履无声跨鲸远，年年谢桥月。\n曲折。\n折画阑尽日凭热。\n半蜃起玲珑楼阁畔，缥缈鸿去绝。\n飞絮扬东风，天外歌阕。\n睡红醉缬。\n还是催、寒食看花时节。\n花下苍苔盛罗袜。\n银烛短、漏壶易竭。\n料池柳、不攀春送别。\n倩玉兔、别捣秋香，更醉蹋、千山冷翠飞晴雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15954, '西平乐慢・西平乐', '吴文英', '岸压邮亭，路华表，堤树旧色依依。\n红索新晴，翠阴寒食，天涯倦客重归。\n叹废绿平烟带苑，幽渚尘香荡晚，当时燕子，无言对立斜晖。\n追念吟风赏月，十载事，梦惹绿杨丝。\n画船为市，夭妆艳水，日落云沈，人换春移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15955, '瑞龙吟', '吴文英', '堕虹际。\n层观翠冷玲珑，五云飞起。\n玉虬萦结城根，澹烟半野，斜阳半市。\n瞰危睇。\n门巷去来车马，梦游宫蚁。\n秦鬟古色凝愁，镜中暗换，明眸皓齿。\n东海青桑生处，劲风吹浅，瀛洲清。\n山影泛出琼壶，碧树人世。\n枪芽焙绿，曾试云根味。\n岩流溅、涎香惯搅，娇龙春睡。\n露草啼清泪。\n酒香断到，文丘废隧。\n今古秋声里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15956, '瑞龙吟', '吴文英', '黯分袖。\n肠断去水流萍，住船系柳。\n吴宫娇月娆花，醉题恨倚，蛮江豆蔻。\n吐春绣。\n笔底丽情多少，眼波眉岫。\n新园锁却愁阴，露黄漫委，寒香半亩。\n还背垂虹秋去，四桥烟雨，一宵歌酒。\n犹忆翠微携壶，乌帽风骤。\n西湖到日，重见梅钿皱。\n谁家听、琵琶未了，朝骢嘶漏。\n印剖黄金籀。\n待来共凭，齐云话旧。\n莫唱朱樱口。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15957, '瑞龙吟', '吴文英', '大溪面。\n遥望绣羽冲烟，锦棱飞练。\n桃花三十六陂，鲛宫睡起，娇雷乍转。\n去如箭。\n催趁戏旗游鼓，素澜雪溅。\n东风冷湿蛟腥，澹阴送昼，轻霏弄晚。\n洲上青苹生处，斗春不管，怀沙人远。\n残日半开一川，花影零乱。\n山屏醉缬，连棹东西岸。\n阑干倒、千红妆靥，铅香不断。\n傍暝疏帘卷。\n翠涟皱净，笙歌未散。\n簪柳门归懒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15958, '大', '吴文英', '峭石帆收，归期差，林沼年销红碧。\n渔蓑樵笠畔，买佳邻翻盖，浣花新宅。\n地凿桃阴，天澄藻镜，聊与渔郎分席。\n沧波耕不碎，似蓝田初种，翠烟生璧。\n料情属新莲，梦惊春草，断桥相识。\n平生江海客。\n秀怀抱、云锦当秋织。\n任岁晚、陶篱菊暗，逋冢梅荒，总输玉井尝甘液。\n忍弃红香叶。\n集楚裳、西风催著。\n正明月、秋无极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15959, '解蹀躞', '吴文英', '醉云又兼醒雨，楚梦时来往。\n倦蜂刚著梨花、惹游荡。\n还作一段相思，冷波叶舞愁红，送人双桨。\n暗凝想。\n情共天涯秋黯，朱桥锁深巷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15960, '江神子・江城子', '吴文英', '天街如水翠尘空。\n建章宫。\n月明中。\n人未归来，玉树起秋风。\n宝栗万钉花露重，催赐带，过垂虹。\n夜凉沈水绣帘栊。\n酒香浓。\n雾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15961, '江神子・江城子', '吴文英', '西风来晚桂开迟。\n月宫移。\n到东篱。\n簌簌惊尘，吹下半冰规。\n拟唤阿娇来小隐，金屋低，乱香飞。\n重阳还是隔年期。\n蝶相思。\n客情知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15962, '江神子・江城子', '吴文英', '西风一叶送行舟。\n浅迟留。\n舣汀洲。\n新浴红衣，绿水带香流。\n应是离宫城外晚，人伫立，小帘钩。\n新归重省别来愁。\n黛眉头。\n半痕秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15963, '沁园春', '吴文英', '澄碧西湖，软红南陌，银河地穿。\n见华星影里，仙棋局静，清风行处，瑞玉圭寒。\n斜谷山深，望春楼远，无此峥嵘小渭川。\n一泓地，解新波不涸，独障狂澜。\n老苏而後坡仙。\n继菊井嘉名相与传。\n试摩挲劲石，无令角折，丁宁明月，莫规圆。\n漫结鸥盟，那知鱼乐，心止中流别有天。\n无尘夜，听吾伊正在，秋水阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15964, '江神子・江城子', '吴文英', '情如之何，暮涂为客，忍堪送君。\n便江湖天远，中宵同月，关河秋近，何日清尘。\n玉尘生风，貂裘明雪，幕府英雄今几人。\n行须早，料刚肠肯，泪眼离颦。\n平生秀句清尊。\n到帐东风开自有神。\n听夜鸣黄鹤，楼高百尺，朝驰白马，笔扫千军。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15965, '珍珠帘・真珠帘', '吴文英', '蜜沈烬暖萸烟袅。\n层帘卷、伫立行人官道。\n麟带压愁香，听舞箫云渺。\n恨缕情丝春絮远，怅梦隔、银屏难到。\n寒峭。\n有东风嫩柳，学得腰小。\n还近绿水清明，叹孤身如燕，将花平绕。\n细雨湿黄昏，半醉归怀抱。\n蠹损歌纨人去久，漫泪沾、香兰如笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15966, '风入松', '吴文英', '春风吴柳几番黄。\n欢事小蛮窗。\n梅花正结双头梦，被玉龙、吹散幽香。\n昨夜灯前歌黛，今朝陌上啼妆。\n最怜无侣伴雏莺。\n桃叶已春江。\n曲屏先暖鸳衾惯，夜寒深、都是思量。\n莫道蓝桥路远，行云只隔幽坊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15967, '风入松', '吴文英', '听风听雨过清明。\n愁草瘗花铭。\n楼前绿暗分携路，一丝柳、一寸柔情。\n料峭春寒中酒，交加晓梦啼莺。\n西园日日扫林亭。\n依旧赏新晴。\n黄蜂频扑秋千索，有当时、纤手香凝。\n惆怅双鸳不到，幽阶一夜苔生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15968, '风入松', '吴文英', '兰舟高荡涨波凉。\n愁被矮桥妨。\n暮烟疏雨西园路，误秋娘、浅约宫黄。\n还泊邮亭唤酒，旧曾送客斜阳。\n蝉声空曳别枝长。\n似曲不成商。\n御罗屏底翻歌扇，忆西湖、临水开窗。\n和醉重寻幽梦，残衾已断熏香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15969, '风入松', '吴文英', '一番疏雨洗芙蓉。\n玉冷佩丁东。\n辘轳听带秋声转，早凉生、傍井梧桐。\n欢宴良宵好月，佳人修竹清风。\n临池飞阁乍青红。\n移酒小垂虹。\n贞元供奉梨园曲，称十香、深蘸琼锺。\n醉梦孤云晓色，笙歌一派秋空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15970, '风入松', '吴文英', '画船帘密不藏香。\n飞作楚云狂。\n傍怀半卷金炉烬，怕暖销、春日朝阳。\n清馥晴熏残醉，断烟无限思量。\n凭阑心事隔垂杨。\n楼燕锁幽妆。\n梅花偏恼多情月，慰溪桥、流水昏黄。\n哀曲霜鸿凄断，梦魂寒蝶幽扬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15971, '莺啼序', '吴文英', '天吴驾云阆海，凝春空灿绮。\n倒银海、蘸影西城，四碧天镜无际。\n彩翼曳、扶摇宛转，雩龙降尾交新霁。\n近玉虚高处，天风笑语吹坠。\n清濯缁尘，快展旷眼，傍危阑醉倚。\n面屏障、一一莺花，薛萝浮动金翠。\n惯朝昏、晴光雨色，燕泥动、红香流水。\n步新梯，藐视年华，顿非尘世。\n麟翁衮，领客登临，座有诵鱼美。\n翁笑起、离席而语，敢诧京兆，以役为功，落成奇事。\n明良庆会，赓歌熙载，隆都观国多闲暇，遣丹青、雅饰繁华地。\n平瞻太极，天街润纳璇题，露床夜沈秋纬。\n清风观阙，丽日罘，正午长漏迟。\n为洗尽、脂痕茸唾，净卷曲尘，永昼低垂，绣帘十二。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15972, '莺啼序', '吴文英', '残寒正欺病酒，掩沈香绣户。\n燕来晚、飞入西城，似说春事迟暮。\n画船载、清明过却，晴烟冉冉吴宫树。\n念羁情游荡，随风化为轻絮。\n十载西湖，傍柳系马，趁娇尘软雾。\n溯红渐、招入仙溪，锦儿偷寄幽素。\n倚银屏、春宽梦窄，断红湿、歌纨金缕。\n暝堤空，轻把斜阳，总还鸥鹭。\n幽兰旋老，杜若还生，水乡尚寄旅。\n别後访、六桥无信，事往花委，瘗玉埋香，几番风雨。\n长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。\n青楼彷佛，临分败壁题诗，泪墨惨澹尘土。\n危亭望极，草色天涯，吹鬓侵半苎。\n暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15973, '莺啼序', '吴文英', '横塘棹穿艳锦，引鸳鸯弄水。\n断霞晚、笑折花归，绀纱低护灯蕊。\n润玉瘦、冰轻倦浴，斜拖凤股盘云坠。\n听银床声细。\n梧桐渐搅凉思。\n窗隙流光，冉冉迅羽，诉空粱燕子。\n误惊起、风竹敲门，故人还又不至。\n记琅、新诗细掐，早陈迹、香痕纤指。\n怕因循，罗扇恩疏，又生秋意。\n西湖旧日，画舸频移，叹几萦梦寐。\n霞佩冷，叠澜不定，麝霭飞雨，乍湿鲛绡，暗盛红泪。\n单夜共，波心宿处，琼箫吹月霓裳舞，向明朝、未觉花容悴。\n嫣香易落，回头澹碧销烟，镜空画罗屏裹。\n残蝉度曲，唱彻西园，也感红怨翠。\n念省惯、吴宫幽憩。\n暗柳追凉，晓岸参斜，露零沤起。\n丝索寸藕，留连欢事。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15974, '天香', '吴文英', '珠络玲珑，罗囊闲斗，酥怀暖麝相倚。\n百和花须，十分风韵，半袭凤箱重绮。\n茜垂四角，慵未揭、流苏春睡。\n熏度红薇院落，烟销画屏沈水。\n温泉降绡乍试。\n露华侵、透肌兰。\n漫省浅溪月夜，暗浮花气。\n荀令如今老矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15975, '天香', '吴文英', '叶黏霜，蝇苞缀冻，生香远带风峭。\n岭上寒多，溪头月冷，北枝瘦、南枝小。\n玉奴有姊，先占立、墙阴春早。\n初试宫黄澹薄，偷分寿阳纤巧。\n银烛泪深未晓。\n酒锺悭、贮愁多少。\n记得短亭归马，暮衙蜂闹。\n豆蔻钗梁恨袅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15976, '玉漏迟', '吴文英', '雁边风讯小，飞琼望杳，碧云先晚。\n露冷阑干，定怯藕丝冰腕。\n净洗浮空片玉，胜花影、春灯相乱。\n秦镜满。\n素娥未肯，分秋一半。\n每圆处既良宵，甚此夕偏饶，对歌临怨。\n万里蝉娟，几许雾屏云幔。\n孤免凄凉照水，晓风起、银河西转。\n摩泪眼。\n瑶台梦回人远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15977, '金盏子', '吴文英', '卜筑西湖，种翠萝犹傍，软红尘裹。\n来往载清吟，为偏爱吾庐，画船频繁。\n笑携雨色晴光，入春明朝市。\n石桥锁，烟霞五百名仙，第一人是。\n临酒论深意。\n流光转、莺花任乱委。\n冷然九秋肺腑，应多梦、岩扃冷云空翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15978, '金盏子', '吴文英', '赏月梧园，恨广寒宫树，晓风摇落。\n莓砌扫珠尘，空肠断、熏炉烬销残萼。\n殿秋尚有馀花，锁烟窗云幄。\n新雁又、无端送人江上，短亭初泊。\n篱角。\n梦依约。\n人一笑、惺忪翠袖薄。\n悠然醉魂唤醒，幽丛畔、凄香雾雨漠漠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15979, '永遇乐', '吴文英', '春酌沈沈，晚妆的的，仙梦游惯。\n锦溆维舟，青门倚盖，还被笼莺唤。\n裴郎归後，崔娘沈恨，漫客请传芳卷。\n联题在，频经翠袖，胜隔绀纱尘幔。\n桃根杏叶，胶黏缃缥，几回凭阑人换。\n峨髻愁云，兰香腻粉，都为多情褪。\n离巾拭泪，征袍染醉，强作酒朋花伴。\n留连怕，风姨浪妒，又吹雨断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15980, '永遇乐', '吴文英', '风拂尘徽，雨侵凉榻，才动秋思。\n缓酒销更，移灯傍影，净洗芭蕉耳。\n铜华沧海，愁霾重嶂，燕北雁南天外。\n算阴晴，浑似几番，渭城故人离会。\n青楼旧日，高歌取醉，唤出玉人梳洗。\n红叶流光，苹花两鬓，心事成秋水。\n白凝虚晓，香吹轻烬，倚窗小瓶疏桂。\n问深宫，娥正在，妒云第几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15981, '永遇乐', '吴文英', '阁雪云低，卷沙风急，惊雁失序。\n户掩寒宵，屏闲冷梦，灯唇似语。\n堪怜窗景，都闲刺绣，但续旧愁一缕。\n邻歌散，罗襟印粉，袖湿茜桃红露。\n西湖旧日，留连清夜，爱酒几将花误。\n遣袜尘销，题裙墨黯，天远吹笙路。\n吴台直下，缃梅无限，未放野桥香度。\n重谋醉，揉香弄影，水清浅处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15982, '玉胡蝶・玉蝴蝶', '吴文英', '角断竿鸣疏点，倦萤透隙，低弄书光。\n一寸悲秋，生动万种凄凉。\n旧衫染、唾凝花碧，别泪想、妆洗蜂黄。\n楚魂伤。\n雁汀沙冷，来信微茫。\n都忘。\n孤山旧赏，水沈熨露，岸锦宜霜。\n败叶题诗，御沟应不到流湘。\n数客路、又随淮月，羡故人、还买吴航。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15983, '绛都春', '吴文英', '香深雾暖。\n正人在、锦瑟华年深院。\n旧日汉宫，分得红兰滋吴苑。\n临池羞落梅花片。\n弄水月、初匀妆面。\n紫烟笼处，双鸾共跨，洞箫低按。\n歌管。\n红围翠袖，冻云外，似觉东风先转。\n绣畔昼迟，花底天宽春无限。\n仙郎骄马琼林宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15984, '绛都春', '吴文英', '羁云旅雁。\n敛倦羽、寄楼墙阴年晚。\n问字翠尊，刻烛红笺悭曾展。\n冰滩鸣佩舟如箭。\n笑乌帻、临风重岸。\n傍邻垂柳，清霜万缕，送将人远。\n吴苑。\n千金未惜，买新赋、共赏文园词翰。\n流水翠微，明月清风平分半。\n梅深驿路香不断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15985, '绛都春', '吴文英', '螺屏暖翠。\n正雾卷暮色，星河浮霁。\n路幕递香，街马冲尘东风细。\n梅槎凌海横鳌背。\n倩稳载、蓬莱云气。\n宝阶斜转，冰峨素影，夜清如水。\n应记。\n千秋化鹤，旧华表、认得山川犹是。\n暗解绣囊，争掷金钱游人醉。\n笙歌晓度晴霞外。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15986, '绛都春', '吴文英', '情黏舞线。\n怅驻马灞桥，天寒人远。\n旋翦露痕，移得春娇栽琼苑。\n流莺常语烟中怨。\n恨三月、飞花零乱。\n艳阳归後，红藏翠掩，小坊幽院。\n谁见。\n新腔按彻，背灯暗、共倚屏葱茜。\n绣被梦轻，金屋妆深沈香换。\n梅花重洗春风面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15987, '绛都春', '吴文英', '南楼坠燕。\n又灯晕夜凉，疏帘空卷。\n叶吹暮喧，花露晨秋光短。\n当时明月娉婷伴。\n怅客路、幽扃俱远。\n雾鬟依约，除非照影，镜空不见。\n别馆。\n秋娘乍识，似人处、最在双波凝盼。\n旧色旧香，闲雨闲云情终浅。\n丹青谁画真真面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15988, '绛都春', '吴文英', '春来雁渚。\n弄艳冶、又入垂杨如许。\n困舞瘦腰，啼湿宫黄池塘雨。\n碧沿苍藓云根路。\n尚追想、凌波微步。\n小楼重上，凭谁为唱，旧时金缕。\n凝伫。\n烟萝翠竹，欠罗袖、为倚天寒日暮。\n强醉梅边，招得花奴来尊俎。\n东风须惹春云住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15989, '惜秋华', '吴文英', '细响残蛩，傍灯前、似说深秋怀抱。\n怕上翠微，伤心乱烟残照。\n西湖镜掩尘沙，翳晓影、秦鬟云扰。\n新鸿，唤凄凉、渐入红萸乌帽。\n江上故人老。\n视东篱秀色，依然娟好。\n晚梦趁、邻杵断，乍将愁到。\n秋娘泪湿黄昏，又满城、雨轻风小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15990, '惜秋华', '吴文英', '思渺西风，怅行踪、浪逐南飞高雁。\n怯上翠微，危楼更堪凭晚。\n蓬莱对起幽云，澹野色山容愁卷。\n清浅。\n瞰沧波、静衔秋痕一线。\n十载寄吴苑。\n惯东篱深把，露黄偷翦。\n移暮影、照越镜，意销香断。\n秋娥赋得闲情，倚翠尊、小眉初展。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15991, '惜秋华', '吴文英', '露蛛丝，小楼阴堕月，秋惊华鬓。\n宫漏未央，当时钿钗遗恨。\n人间梦隔西风，算天上、年华一瞬。\n相逢，纵相疏、胜却巫阳无准。\n和处动凉讯。\n听露井梧桐，楚骚成韵。\n彩云断、翠羽散，此情难问。\n银河万古秋声，但望中、婺星清润。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15992, '惜秋华', '吴文英', '数日西风，打秋林枣熟，还催人去。\n瓜果夜深，斜河拟看星度。\n葱葱便倒离尊，怅遇合、云销萍聚。\n留连，有残蝉韵晚，时歌金缕。\n绿水暂如许。\n奈南墙冷落，竹烟槐雨。\n此去杜曲，已近紫霄尺五。\n扁舟夜宿吴江，正水佩霓裳无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15993, '惜秋华', '吴文英', '路远仙城，自王郎去後，芳卿憔悴。\n锦段镜空，重铺步障新绮。\n凡花瘦不禁秋，幻腻玉、腴红鲜丽。\n相携。\n试新妆乍毕，交扶轻醉。\n长记断桥外。\n骤玉骢过处，千娇凝睇。\n昨梦顿醒，依约旧时眉翠。\n愁边暮合碧云，倩唱入、六幺声里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15994, '惜黄花慢', '吴文英', '粉靥金裳。\n映绣屏认得，旧日萧娘。\n翠微高处，故人帽底，一年最好，偏是重阳。\n避春祗怕春不远，望幽径、偷理秋妆。\n醉乡。\n寸心似翦，飘荡愁觞。\n潮腮笑入清霜。\n斗万花样巧，深染蜂黄。\n露痕千点，自怜旧色，寒泉半掬，百感幽香。\n雁声不到东篱畔，满城但、风雨凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15995, '惜黄花慢', '吴文英', '送客吴皋。\n正试霜夜冷，枫落长桥。\n望天不尽，背城渐杳，离亭黯黯，恨水迢迢。\n翠香零落红衣老，暮愁锁、残柳眉梢。\n念瘦腰。\n沈郎旧日，曾系兰桡。\n仙人凤咽琼箫。\n怅断魂送远，九辨难招。\n醉鬟留盼，小窗翦烛，歌云载恨，飞上银霄。\n素秋不解随船去，败红趁、一叶寒涛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15996, '十二郎・二郎神', '吴文英', '素天际水，浪拍碎、冻云不凝。\n记晓叶题霜，秋灯吟雨，曾系长桥过艇。\n又是宾鸿重来後，猛赋得、归期才定。\n嗟绣鸭解言，香鲈堪钓，尚庐人境。\n幽兴。\n争如共载，越娥妆镜。\n念倦客依前，貂裘茸帽，重向淞江照影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15997, '醉蓬莱', '吴文英', '望碧天书断，宝枕香留，泪痕盈袖。\n谁识秋娘，比行云纤瘦。\n象尺熏炉，翠针金缕，记倚床同绣。\n月琼梳，冰销粉汗，南花熏透。\n尽是当时，少年清梦，臂约痕深，帕绡红皱。\n凭鹊传音，恨语多轻漏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15998, '烛影摇红', '吴文英', '西子西湖，赋情合载鸱夷棹。\n断桥直去是孤山，应为梅花到。\n几度吟昏醉晓。\n背东风、偷闲斗草。\n乱鸦啼後，解佩归来，春怀多少。\n千里蝉娟，茂园今夜同清照。\n樱脂茸唾听吟诗，争似还家好。\n昵昵西窗语笑。\n凤云深、琼箫缥缈。\n顾春如旧，柳带同心，花枝压帽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (15999, '烛影摇红', '吴文英', '新月侵阶，彩云林外笙箫透。\n银台双引绕花行，红坠香沾袖。\n不管签声转漏。\n更明朝、棋消永昼。\n静中闲看，倦羽飞还，游云出岫。\n随处春光，翠阴那只西湖柳。\n去年溪上牡丹时，还试长安酒。\n都把愁怀抖擞。\n笑流莺、啼春漫漫瘦。\n晓风恶尽，妒雪寒销，青梅如豆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16000, '烛影摇红', '吴文英', '飞尽西园，晚秋却胜春天气。\n霜花开尽锦屏空，红叶新装缀。\n时放清杯泛水。\n暗凄凉、东风旧事。\n夜吟不绝，松影阑干，月笼寒翠。\n莫唱阳关，但凭彩袖歌千岁。\n秋星入梦隔明朝，十载吴宫会。\n一棹回潮度苇。\n正西窗、灯花报喜。\n柳蛮樱素，试酒争怜，不教不醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16001, '烛影摇红', '吴文英', '碧澹山姿，暮寒愁沁歌眉浅。\n障泥南陌润轻酥，灯火深深院。\n入夜笙歌渐暖。\n彩旗翻、宜男舞遍。\n恣游不怕，素袜尘生，行裙红溅。\n银烛笼纱，翠屏不照残梅怨。\n洗妆清靥湿春风，宜带啼痕看。\n楚梦留情未散。\n素娥愁、天深信远。\n晓窗移枕，酒困香残，春阴帘卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16002, '烛影摇红', '吴文英', '天桂飞香，御花簇座千秋宴。\n笑从王母摘仙桃，琼醴双金盏。\n掌上龙珠照眼。\n映萝图、星晖海润。\n浮槎远到，水浅蓬莱，秋明河汉。\n宝月将弦，晚钩斜挂西帘卷。\n未须十日便中秋，争看清光满。\n净洗红尘障面。\n贺朝霖、催班正殿。\n喜回天上，紫府开筵，瑶池宣劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16003, '烛影摇红', '吴文英', '莓锁虹梁，稽山祠下当时见。\n横斜无分照溪光，珠网空凝遍。\n姑射青春对面。\n驾飞虬、罗浮路远。\n千年春在，新月苔池，黄昏山馆。\n花满河阳，为君羞褪晨妆茜。\n云根直下是银河，客老秋槎变。\n雨外红铅洗断。\n又晴匣、惊飞暮管。\n倚阑祗怕，弄水鳞生，乘东风便。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16004, '烛影摇红', '吴文英', '秋入灯花，夜深檐影琵琶语。\n越娥青镜洗红埃，山斗秦眉妩。\n相问金茸翠亩。\n认城阴、春耕旧处。\n晚春相应，新稻炊香，疏烟林莽。\n清磬风前，海沈宿袅芙蓉炷。\n阿香秋梦起娇啼，玉女传幽素。\n人驾梅槎未渡。\n试梧桐、聊分宴俎。\n采菱别调，留取蓬莱，霎时云住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16005, '丑奴儿慢・采桑子慢', '吴文英', '东风未起，花上纤尘无影。\n峭云湿，凝酥深，乍洗梅清。\n钓卷愁丝，冷浮虹气海空明。\n若耶门闭，扁舟去懒，客思鸥轻。\n几度问春，倡红冶翠，空媚阴晴。\n看真色、千岩一素，天澹无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16006, '丑奴儿慢・采桑子慢', '吴文英', '空乍敛，波影帘花晴乱。\n正西子、梳妆楼上，镜舞青鸾。\n润逼风襟，满湖山色入阑干。\n天虚鸣籁，云多易雨，长带秋寒。\n遥望翠凹，隔江时见，越女低鬟。\n算堪羡、烟沙白鹭，暮往朝远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16007, '木兰花慢', '吴文英', '紫骝嘶冻草，晓云锁、岫眉颦。\n正蕙雪初销，松腰玉瘦，憔悴真真。\n轻藜渐穿险磴，步荒苔、犹认瘗花痕。\n千古兴亡旧恨，半丘残日孤云。\n开尊。\n重吊吴魂。\n岚翠冷、洗微醺。\n问几曾夜宿，月明起看，剑水星纹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16008, '木兰花慢', '吴文英', '步层丘翠莽，□□处、更春寒。\n渐晚色催阴，风花弄雨，愁起阑干。\n惊翰。\n带云去杳，任红尘、一片落人间。\n青冢麒麟有恨，卧听箫鼓游山。\n年年。\n叶外花前。\n腰艳楚、鬓成潘。\n叹宝奁瘗久，青萍共化，裂石空磐。\n尘缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16009, '木兰花慢', '吴文英', '送秋云万里，算舒卷、总何心。\n叹路转羊肠，人营燕垒，霜满蓬簪。\n愁侵。\n庾尘满袖，便封侯、那羡汉淮阴。\n一醉莼丝脍玉，忍教菊老松深。\n离音。\n又听西风，金井树、动秋吟。\n向暮江目断，鸿飞渺渺，天色沈沈。\n沾襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16010, '木兰花慢', '吴文英', '酹清杯问水，惯曾见、几逢迎。\n自越棹轻飞，秋莼归後，杞菊荒荆。\n孤鸣。\n舞鸥惯下，又渔歌、忽断晚烟生。\n雪浪闲销钓石，冷枫频落江汀。\n长亭。\n春恨何穷，目易尽、酒微醒。\n怅断魂西子，凌波去杳，环佩无声。\n阴晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16011, '木兰花慢', '吴文英', '润寒梅细雨，卷灯火、暗尘香。\n正万里胥涛，流花涨腻，春共东江。\n云樯。\n未传燕语，过罘、垂柳舞鹅黄。\n留取行人系马，软红深处闻莺。\n悠扬。\n霁月清风，凝望久、山苍。\n又紫箫一曲，还吹别调，楚际吴旁。\n仙方。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16012, '木兰花慢', '吴文英', '指罘晓月，动凉信、又催归。\n正玉涨松波，花穿画舫，无限红衣。\n青丝。\n傍桥浅系，问笛中、谁奏鹤南飞。\n西子冰销冷处，素娥宝镜圆时。\n清奇。\n好借秋光，临水色、写瑶卮。\n向醉中织就，天孙云锦，一杼新诗。\n依稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16013, '木兰花慢', '吴文英', '几临流送远，渐荒落、旧邮亭。\n念西子初来，当时望眼，啼雨难晴。\n娉婷。\n素亭共载，到越吟、翻调倚吴声。\n得意东风去棹，怎怜会重离轻。\n云零。\n梦绕浮觞，流水畔、叙幽情。\n恨赋笔分携，江山委秀，桃李荒荆。\n经行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16014, '喜迁莺', '吴文英', '凡尘流水。\n正春在、绛阙瑶阶十二。\n暖日明霞，天香盘锦，低映晓光梳洗。\n故苑浣花沈恨，化作妖红斜紫。\n困无力，倚阑干，还倩东风扶起。\n公子。\n留意处，罗盖牙签，一一花名字。\n小扇翻歌，密围留客，云叶翠温罗绮。\n艳波紫金杯重，人倚妆台微醉。\n夜和露，翦残枝，点点花心清泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16015, '喜迁莺', '吴文英', '烟空白鹭。\n乍飞下、似呼行人相语。\n细春波，微痕秋月，曾认片帆来去。\n万顷素云遮断，十二红帘钩处。\n黯愁远，向虹腰，时送斜阳凝伫。\n轻许。\n孤梦到，海上玑宫，玉冷深窗户。\n遥指人间，隔江烟火，漠漠水摇暮。\n看葺断矶残钓，替却珠歌雪舞。\n吟未了，去匆匆，清晓一阑烟雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16016, '喜迁莺', '吴文英', '江亭年暮。\n趁飞雁、又听，数声柔橹。\n蓝尾杯单，胶牙饧澹，重省旧时羁旅。\n雪舞野梅篱落，寒拥渔家门户。\n晚风峭，作初番花讯，春还知否。\n何处。\n围艳冶、红烛画堂，博良宵午。\n谁念行人，愁先芳草，轻送年华如羽。\n自剔短檠不睡，空索彩桃新句。\n便归好，料鹅黄，已染西池千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16017, '喜迁莺', '吴文英', '冬分人别。\n渡倦客晚潮，伤头俱雪。\n雁影秋空，蝶情春荡，几处路穷车绝。\n把酒共温寒夜，倚绣添慵时节。\n又底事，对愁云江国，离心还折。\n吴越。\n重会面，点检旧吟，同看灯花结。\n儿女相思，年华轻送，邻户断声噎。\n待移杖藜雪後，犹怯蓬莱寒阔。\n最起晚，任鸦林催晓，梅窗沈月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16018, '探芳信', '吴文英', '夜寒重。\n见羽葆将迎，飞琼入梦。\n整素妆归处，中宵按瑶凤。\n舞春歌夜棠梨岸，月冷和云冻。\n画船中、太白仙人，锦袍初拥。\n应过语溪否，试笑挹中郎，还叩清弄。\n粉黛湖山，欠携酒、共飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16019, '探芳信', '吴文英', '暖风定。\n正卖花吟春，去年曾听。\n旋自洗幽兰，银瓶钓金井。\n斗窗香暖悭留客，街鼓还催暝。\n调雏莺、试遣深杯，唤将愁醒。\n灯市又重整。\n待醉勒游缰，缓穿斜径。\n暗忆芳盟，绡帕泪犹凝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16020, '探芳信', '吴文英', '为春瘦。\n更瘦如梅花，花应知否。\n任枕函云坠，离怀半中酒。\n雨声楼阁春寒里，寂寞收灯後。\n甚年年、斗草心期，探花时候。\n娇懒强拈绣。\n暗背里相思，闲供晴昼。\n玉合罗囊，兰膏渍红豆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16021, '探芳信', '吴文英', '转芳径。\n见雾卷晴漪，鱼弄游影。\n旋解缨濯翠，临流抚菱镜。\n半林竹色香处，意足多新咏。\n试衣单、雁欲来时，旧寒才定。\n门巷对深静。\n但酒敌春浓，棋消日永。\n旧曲猗兰，待留向、月中听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16022, '探芳信', '吴文英', '探春到。\n见彩花钗头，玉燕来早。\n正紫龙眠重，明月弄清晓。\n夜尘不浸银河水，金盎供新澡。\n镇帷犀、护紧东风，秀藏芝草。\n星斗粲怀抱。\n问雾暖蓝田，玉长多少。\n禁苑传香，柳边语、听莺报。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16023, '声声慢', '吴文英', '蓝云笼晓，玉树悬秋，交加金钏霞枝。\n人起昭阳，禁寒粉栗生肌。\n浓香最无著处，渐冷香、风露成霏。\n绣茵展，怕空阶惊坠，化作萤飞。\n三十六宫愁重，问谁持金锸，和月都移。\n掣锁西厢，清尊素手重携。\n秋来鬓华多少，任压花低。\n正摇落，叹淹留、客又未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16024, '声声慢', '吴文英', '云深山坞，烟冷江皋，人生未易相逢。\n一笑灯前，钗行两两春容。\n清芳夜争真态，引生香、撩乱东风。\n探花手，与安排金屋，懊恼司空。\n憔悴翘委佩，恨玉奴销瘦，飞趁轻鸿。\n试问知心，尊前谁最情浓。\n连呼紫云伴醉，小丁香、才吐微红。\n还解语，待携归、行雨梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16025, '声声慢', '吴文英', '檀栾金碧，婀娜蓬莱，游云不蘸芳洲。\n露柳霜莲，十分点缀成秋。\n新弯画眉未稳，似含羞、低护墙头。\n愁送远，驻西台车马，共惜临流。\n知道池亭多宴，掩庭花、长是惊落秦讴。\n腻粉阑干，犹闻凭袖香留。\n输他翠涟拍，瞰新妆、时浸明眸。\n帘半卷，带黄花、人在小楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16026, '声声慢', '吴文英', '春星当户，眉月分心，罗屏绣幕围香。\n歌缓□□，轻尘暗簌文梁。\n秋桐泛商丝雨，恨未回、飘雪垂杨。\n连宝镜，更一家姊妹，曾入昭阳。\n莺燕堂深谁到，为殷勤、须放醉客疏狂。\n量减离怀，孤负蘸甲清觞。\n曲中倚娇佯误，算只图、一顾周郎。\n花镇好，驻年华、长在琐窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16027, '声声慢', '吴文英', '寒筲惊坠，香豆初收，银妆一夜霜深。\n乱泻明珠，金盘来荐清斟。\n绿窗细剥檀皱，料水晶、微损春簪。\n风韵处，惹手香酥润，樱口脂侵。\n重省追凉前事，正风吟莎井，月碎苔阴。\n颗颗相思，无情漫搅秋心。\n银台翦花杯散，梦阿娇、金屋沈沈。\n甚时见，露十香、钗燕坠金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16028, '声声慢', '吴文英', '清漪衔苑，御水分流，阿阶西北青红。\n朱浮云，碧窗宿雾。\n璇题净横秋影，笑南飞、不过新鸿。\n延桂影，见素娥梳洗，微步琼空。\n城外湖山十里，想无时长敞，罨画帘栊。\n暗柳回堤，何须系马金狨。\n莺花翰林千首，彩毫飞、海雨天风。\n凤池上，又相思、春夜梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16029, '声声慢', '吴文英', '六铢衣细，一叶舟轻，黄芦堪笑浮槎。\n何处汀洲，云澜锦浪无涯。\n秋姿澹凝水色，艳真香、不染春华。\n笑归去，傍金波开户，翠屋为家。\n回施红妆青镜，与一川平绿，五月晴霞。\n玉杯中，西风不到窗纱。\n端的旧莲深薏，料采菱、新曲羞夸。\n秋潋滟，对年年、人胜似花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16030, '声声慢', '吴文英', '莺围橙径，鲈跃莼波，重来雨过中秋。\n酒市渔乡，西风胜似春柔。\n宿舂去年村墅，看黄云、还委西畴。\n凤池去，信吴人有分，借与迟留。\n应是香山续梦，又凝香追咏，重到苏州。\n青鬓江山，足成千岁风流。\n围腰御仙花底，衬月中、金粟香浮。\n夜宴久，揽秋云、平倚画楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16031, '声声慢', '吴文英', '旋移轻，浅傍垂虹，还因送客迟留。\n泪雨横波，遥山眉上新愁。\n行人倚阑心事，问谁知、只有沙鸥。\n念聚散，几枫丹霜渚，莼绿春洲。\n渐近香菰炊黍，想红丝织字，未远青楼。\n寂寞渔乡，争如连醉温柔。\n西窗夜深翦烛，梦频生、不放云收。\n共怅望，认孤烟、起处是州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16032, '高阳台', '吴文英', '修竹凝妆，垂杨驻马，凭阑浅画成图。\n山色谁题，楼前有雁斜书。\n东风紧送斜阳下，弄旧寒、晚酒醒馀。\n自销凝，能几花前，顿老相如。\n伤春不在高楼上，在灯前枕，雨外熏炉。\n怕舣游船，临流可奈清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16033, '高阳台', '吴文英', '宫粉雕痕，仙云堕影，无人野水荒湾。\n古石埋香，金沙锁骨连环。\n南楼不恨吹横笛，恨晓风、千里关山。\n半飘零，庭上黄昏，月冷阑干。\n寿阳空理愁鸾。\n问谁调玉髓，暗补香瘢。\n细雨归鸿，孤山无限春寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16034, '高阳台', '吴文英', '淝水秋寒，淮堤柳色，别来几换年光。\n紫马行迟，才生梦草池塘。\n便乘丹凤天边去，禁漏催、春殿称觞。\n过松江，雪弄飞花，冰解鸣。\n芳洲酒社词场。\n赋高台陈迹，曾醉吴王。\n重上逋山，诗清月瘦昏黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16035, '高阳台', '吴文英', '风袅垂杨，雪销蕙草，何如清润潘郎。\n风月襟怀，挥豪倚马成章。\n仙都观里桃千树，映曲尘、十里荷塘。\n未归来，应恋花洲，醉玉吟香。\n东风晴昼浓如酒，正十分皓月，一半春光。\n燕子重来，明朝传梦西窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16036, '高阳台', '吴文英', '帆落回潮，人归故国，山椒感慨重游。\n弓折霜寒，机心已堕沙鸥。\n灯前宝剑清风断，正五湖、雨笠扁舟。\n最无情，岩上闲花，腥染春愁。\n当时白石苍松路，解勒回玉辇，雾掩山羞。\n木客歌阑，青春一梦荒丘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16037, '倦寻芳', '吴文英', '坠瓶恨井，分镜迷楼，空闲孤燕。\n寄别崔徽，清瘦画图春面。\n不约舟移杨柳系，有缘人映桃花见。\n叙分携，悔香瘢漫，绿鬟轻翦。\n听细语、琵琶幽怨。\n客鬓苍华，衫袖湿遍。\n渐老芙蓉，犹自带霜宜看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16038, '倦寻芳', '吴文英', '海霞倒影，空雾飞香，天市催晚。\n暮靥宫梅，相对画楼帘卷。\n罗袜轻尘花笑语，宝钗争艳春心眼。\n乱箫声，正风柔柳弱，舞肩交燕。\n念窈窕、东邻深巷，灯外歌沈，月上花浅。\n梦雨离云，点点漏壶清怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16039, '倦寻芳', '吴文英', '暮帆挂雨，冰岸飞梅，春思零乱。\n送客将归，偏是故宫离苑。\n醉酒曾同凉月舞，寻芳还隔江尘面。\n去难留，怅芙蓉路窄，绿杨天远。\n便系马、莺边清晓，烟草晴花，沙润香软。\n烂锦年华，谁念故人游倦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16040, '三姝媚', '吴文英', '吹笙池上道。\n为王孙重来，旋生芳草。\n水石清寒，过半春犹自，燕沈莺悄。\n樨柳阑干，晴荡漾、禁烟残照。\n往事依然，争忍重听，怨红凄调。\n曲榭方亭初扫。\n印藓迹双鸳，记穿林窈。\n顿隔年华，似梦回花上，露平晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16041, '三姝媚', '吴文英', '湖山经醉惯。\n溃春衫、啼痕酒痕无限。\n又客长安，叹断襟零袂，尘谁浣。\n紫曲门荒，沿败井、风摇青蔓。\n对语东邻，犹是曾巢，谢堂双燕。\n春梦人间须断。\n但怪得、当年梦缘能短。\n绣屋秦筝，傍海棠偏爱，夜深开宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16042, '三姝媚', '吴文英', '酣春青镜里。ピ\n照晴波明眸，暮云愁髻。ピ\n半绿垂丝，正楚腰纤瘦，舞衣初试。ピ\n燕客飘零，烟树冷、青骢曾系。ピ\n画馆朱楼，还把清尊，慰春憔悴。ピ\n离苑幽芳深闭。ピ\n恨浅薄东风，褪花销腻。ピ\n彩翻歌，最赋情、偏在笑红颦翠。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16043, '昼锦堂', '吴文英', '舞影灯前，箫声酒外，独鹤华表重归。\n旧雨残云仍在，门巷都非。\n愁结春情迷醉眼，老怜秋鬓倚蛾眉。\n难忘处，犹恨绣笼，无端误放莺飞。\n当时。\n征路远，欢事差，十年轻负心期。\n楚梦秦楼相遇，共叹相违。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16044, '汉宫春', '吴文英', '花姥来时，带天香国艳，羞掩名姝。\n日长半娇半困，宿酒微苏。\n沈香槛北，比人间、风异烟殊。\n春恨重，盘云坠髻，碧花翻吐琼盂。\n洛苑旧移仙谱，向吴娃深馆，曾奉君娱。\n猩唇露红未洗，客鬓霜铺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16045, '汉宫春', '吴文英', '名压年芳，倚竹根新影，独照清漪。\n千年禹梁藓碧，重发南枝。\n冰凝素质，遣凡桃、羞濯尘姿。\n寒正峭，东风似海，香浮夜雪春霏。\n练鹊锦袍仙使，有青娥传梦，月转参移。\n逋山傍莺系马，玉翦新辞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16046, '汉宫春', '吴文英', '怀得银符，卷朝衣归袖，犹惹天香。\n星移太微几度，飞出西江。\n吴城驻马，趁鲈肥、腊蚁初尝。\n红雾底，金门候晓，争如小队春行。\n何用倚楼看镜，算橘中深趣，日月偏长。\n江山待吟秀句，梅靥催妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16047, '秋霁', '吴文英', '一水盈盈，汉影隔游尘，净洗寒绿。\n秋沐平烟，日回西照，乍惊饮虹天北。\n彩阑翠馥。\n锦云直下花成屋。\n试纵目。\n空际、醉乘风露跨黄鹄。\n追想缥缈，钓雪松江，恍然烟蓑，秋梦重续。\n问何如、临池脍玉，扁舟空舣洞庭宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16048, '花心动', '吴文英', '入眼青红，小玲珑、飞檐度云微湿。\n绣槛展春，金屋宽花，谁管采菱波狭。\n翠深知是深多少，不都放、夕阳红入。\n待装缀，新漪涨翠，小圜荷叶。\n此去春风满箧。\n应时锁蛛丝，浅虚尘榻。\n夜雨试灯，晴雪吹梅，趁取玳簪重盍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16049, '花心动', '吴文英', '十里东风，袅垂杨、长似舞时腰瘦。\n翠馆朱楼，紫陌青门，处处燕莺晴昼。\n乍看摇曳金丝细，春浅映、鹅黄如酒。\n嫩阴裹，烟滋露染，翠娇红溜。\n此际雕鞍去久。\n空追念邮亭，短枝盈首。\n海角天涯，寒食清明，泪点絮花沾袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16050, '龙山会', '吴文英', '石径幽云冷，步障深深，艳锦青红亚。\n小桥和梦过，仙佩杳、烟水茫茫城下。\n何处不秋阴，问谁借、东风艳冶。\n最娇娆，愁侵醉颊，泪销红洒。\n摇落翠莽平沙，竞挽斜阳，驻短亭车马。\n晓妆羞未堕。\n沈恨起、金谷魂飞深夜。\n惊雁落清歌，酹花倩、觥船快泻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16051, '八声甘州', '吴文英', '渺空烟四远，是何年、青天坠长星。\n幻苍崖云树，名娃金屋，残霸宫城。\n箭径酸风射眼，腻水染花腥。\n时双鸳响，廊叶秋声。\n宫里吴王沈醉，倩五湖倦客，独钓醒醒。\n问苍波无语，华发奈山青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16052, '八声甘州', '吴文英', '步晴霞倒影，洗闲愁、深杯滟风漪。\n望越来清浅，吴杳霭，江雁初飞。\n辇路凌空九险，粉冷濯妆池。\n歌舞烟霄顶，乐景沈晖。\n别是青红阑槛，对女墙山色，碧澹宫眉。\n问当时游鹿，应笑古台非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16053, '八声甘州', '吴文英', '记行云梦影，步凌波、仙衣翦芙蓉。\n念杯前烛下，十香袖，玉暖屏风。\n分种寒花旧盎，藓土蚀吴蛩。\n人远云槎渺，烟海沈蓬。\n重访樊姬邻里，怕等闲易别，那忍相逢。\n试潜行幽曲，心荡□匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16054, '新雁过妆楼', '吴文英', '梦醒芙蓉。\n风檐近、挥疑佩玉丁东。\n翠微流水，都是惜别行踪。\n宋玉秋花相比瘦，赋情更苦似秋浓。\n小黄昏，绀云暮合，不见征鸿。\n宜城当时放客，认燕泥旧迹，返照楼空。\n夜阑心事，灯外败壁哀蛩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16055, '新雁过妆楼', '吴文英', '阆苑高寒。\n金枢动、冰宫桂树年年。\n翦秋一半，难破万户连环。\n织锦相思楼影下，细钗暗约小帘间。\n共无眠。\n素娥惯得，西坠阑干。\n谁知壶中自乐，正醉围夜玉，浅斗婵娟。\n雁风自劲，云气不上凉天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16056, '凄凉犯', '吴文英', '空江浪阔。\n清尘凝、层层刻碎冰叶。\n水边照影，华裾曳翠，露搔泪湿。\n湘烟暮合。\n□尘袜、凌波半涉。\n怕临风、□欺瘦骨，护冷素衣叠。\n樊姊玉奴恨，小细疏唇，洗妆轻怯。\n汜人最苦，粉痕深、几重愁靥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16057, '尾犯', '吴文英', '翠被落红妆，流水腻香，犹共吴越。\n十载江枫，冷霜波成缬。\n灯院静、凉花乍翦，桂园深、幽香旋折。\n醉云吹散，晚树细蝉，时替离歌咽。\n长亭曾送客，为偷赋、锦雁留别。\n泪接孤城，渺平芜烟阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16058, '尾犯', '吴文英', '绀海掣微云，金井暮凉，梧韵风急。\n何处楼高，想清光先得。\n江汜冷、冰绡乍洗，素娥，菱花再拭。\n影留人去，忍向夜深，帘户照陈迹。\n竹房苔径小，对日暮、数尽烟碧。\n露蓼香泾，记年时相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16059, '东风第一枝', '吴文英', '倾国倾城，非花非雾，春风十里独步。\n胜如西子妖娆，更比太真澹泞。\n铅华不御。\n漫道有、巫山洛浦。\n似恁地、标格无双，镇锁画楼深处。\n曾被风、容易送去。\n曾被月、等闲留住。\n似花翻使花羞，似柳任从柳妒。\n不教歌舞。\n恐化作、彩云轻举。\n信下蔡、阳城俱迷，看取宋玉词赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16060, '夜合花', '吴文英', '柳暝河桥，莺晴台苑，短策频惹春香。\n当时夜泊，温柔便入深乡。\n词韵窄，酒杯长。\n翦蜡花、壶箭催忙。\n共追游处，凌波翠陌，连棹横塘。\n十年一梦凄凉。\n似西湖燕去，吴馆巢荒。\n重来万感，依前唤酒银罂。\n溪雨急，岸花狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16061, '探春慢', '吴文英', '径苔深，念断无故人，轻敲幽户。\n细草春回，目送流光一羽。\n重云冷，哀雁断，翠微空，愁蝶舞。\n荡鸣澌，游蓬小，梦枕残云惊寤。\n还识西湖醉路。\n向柳下并鞍，银袍吹絮。\n事影难追，那负灯床闻雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16062, '柳梢青', '吴文英', '断梦游轮。\n孤山路杳，越树阴新。\n流水凝酥，征衫沾泪，都是离痕。\n玉屏风冷愁人。\n醉烂漫、梅花翠云。\n傍夜船回，惜春门掩，一镜香尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16063, '生查子', '吴文英', '暮云千万重，寒梦家乡远。\n愁见越溪娘，镜里梅花面。\n醉情啼枕冰，往事分钗燕。\n三月灞陵桥，心翦东风乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16064, '一翦梅', '吴文英', '远目伤心楼上山。\n愁里长眉，别後峨鬟。\n暮云低压小阑干。\n教问孤鸿，因甚先还。\n瘦倚溪桥梅夜寒。\n雪欲消时，泪不禁弹。\n翦成钗胜待归看。\n春在西窗，灯火更阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16065, '点绛唇', '吴文英', '春未来时，酒携不到千岩路。\n瘦还如许。\n晚色天寒处。\n无限新愁，难对风前语。\n行人去。\n暗消春素。\n横笛空山暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16066, '西江月', '吴文英', '枝袅一痕雪在，叶藏几豆春浓。\n玉奴最晚嫁东风。\n来结梨花幽梦。\n香力添熏罗被，瘦肌犹怯冰绡。\n绿阴青子老溪桥。\n羞见东邻娇小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16067, '桃源忆故人', '吴文英', '越山青断西陵浦。\n一片密阴疏雨。\n潮带旧愁生暮。\n曾折垂杨处。\n桃根桃叶当时渡。\n呜咽风前柔橹。\n燕子不留春住。\n空寄离樯语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16068, '木兰花慢', '吴文英', '记琼林宴起，软红路、几西风。\n想汉影千年，荆江万顷，槎信长通。\n金狨。\n锦赐马，又霜横、汉节枣仍红。\n细柳春阴喜色，四郊秋事年丰。\n从容。\n岁晚玉关，长不闭、静边鸿。\n访五昌旧垒，山川相缪，日费诗筒。\n兰宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16069, '夜行船', '吴文英', '碧清漪方镜小。\n绮疏净、半尘不到。\n古鬲香深，宫壶花换，留取四时春好。\n楼上眉山云窈窕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16070, '朝中措', '吴文英', '吴山相对越山青。\n湘水一春平。\n粉字情深题叶，红波香染浮萍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16071, '风入松', '吴文英', '一帆江上暮潮平。\n骑鹤过瑶京。\n湘波山色青天外，红香荡、玉佩东丁。\n西圃仍圆夜月，南风微弄秋声。\n阿咸才俊玉壶冰。\n王母最怜生。\n万年枝上千年叶，垂杨鬓、春共青青。\n连唤碧筒传酒，云回一曲双成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16072, '西江月', '吴文英', '清梦重游天上，古香吹下云头。\n箫声三十六宫愁。\n高处花惊风骤。\n客路羁情不断，阑干晚色先收。\n千山浓绿未成秋。\n谁见月中人瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16073, '朝中措', '吴文英', '殷云凋叶晚晴初。\n篱落认奚奴。\n才近西窗灯火，旋收残夜琴书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16074, '声声慢', '吴文英', '凭高入梦，摇落关情，寒香吹尽空岩。\n坠叶消红，欲题秋讯难缄。\n重阳正隔残照，趁西风、不响云尖。\n乘半暝、看残山濯翠，剩水开奁。\n暗省长安年少，几传杯吊甫，把菊招潜。\n身老江湖，心随飞雁天南。\n乌纱倩谁重整，映风林、钓玉纤纤。\n漏声起，乱星河、入影画檐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16075, '点绛唇', '吴文英', '金井空阴，枕痕历尽秋声闹。\n梦长难晓。\n月树愁鸦悄。\n梅压檐梢，寒蝶寻香到。\n窗黏了。\n翠池春小。\n波冷鸳鸯觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16076, '点绛唇', '吴文英', '明月茫茫，夜来应照南桥路。\n梦游熟处。\n一枕啼秋雨。\n可惜人生，不向吴城住。\n心期误。\n雁将秋去。\n天远青山暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16077, '玉楼春', '吴文英', '阑干独倚天涯客。\n心影暗雕风叶寂。\n千山秋入雨中青，一雁暮随云去急。\n霜花强弄春颜色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16078, '柳梢青', '吴文英', '翠嶂围屏。\n留连讯景，花外油亭。\n澹色烟昏，浓光清晓，一幅闲情。\n辋川落日渔罾。\n写不尽、人间四并。\n亭上秋声，莺笼春语，难入丹青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16079, '浣溪沙', '吴文英', '秦黛横愁送暮云。\n越波秋浅暗啼昏。\n空庭春草绿如裙。\n彩扇不歌原上酒，青门频返月中魂。\n花开空忆倚阑人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16080, '浣溪沙', '吴文英', '一曲鸾箫别彩云。\n燕钗尘涩镜华昏。\n灞桥舞色褪蓝裙。\n湖上醉迷西子梦，江头春断倩离魂。\n旋缄红泪寄行人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16081, '一翦梅', '吴文英', '老色频生玉镜尘。\n雪澹春姿，越看精神。\n溪桥人去几黄昏。\n流水泠泠，都是啼痕。\n烟雨轻寒暮掩门。\n萼绿灯前，酒带香温。\n风情谁道不因春。\n春到一分，花瘦一分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16082, '燕归梁', '吴文英', '一片游尘拂镜湾。\n素影护梅残。\n行人无语看春山。\n背东风、两苍颜。\n梦飞不到梨花外，孤馆闭、五更寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16083, '乌夜啼', '吴文英', '醉痕深晕潮红。\n睡初浓。\n寒食来时池馆，旧东风。\n银烛换。\n月西转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16084, '浪淘沙', '吴文英', '绿树越溪湾。\n过雨云殷。\n西陵人去暮潮还。\n铅泪结成红粟颗，封寄长安。\n别味带生酸。\n愁忆眉山。\n小楼灯外栋花寒。\n衫袖醉痕花睡在，犹染微丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16085, '蹋莎行・踏莎行', '吴文英', '润玉笼绡，檀樱倚扇。\n绣圈犹带脂香浅。\n榴心空叠舞裙红，艾枝应压愁鬟乱。\n午梦千山，窗阴一箭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16086, '浪淘沙', '吴文英', '山远翠眉长。\n高处凄凉。\n菊花清瘦杜秋娘。\n净洗绿杯牵露井，聊荐幽香。\n乌帽压吴霜。\n风力偏狂。\n一年佳节过西厢。\n秋色雁声愁几许，都在斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16087, '思佳客', '吴文英', '钗燕拢云睡起时。\n隔墙折得杏花枝。\n青春半面妆如画，细雨三更花又飞。\n轻爱别，旧相知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16088, '满江红', '吴文英', '竹下门敲，又呼起、胡蝶梦清。\n闲里看、邻墙梅子，几度仁生。\n灯外江湖多夜雨，月边河汉独晨星。\n向草堂、清晓卷琴书，猿鹤惊。\n宫漏静，朝马鸣。\n西风起，已关情。\n料希音不在，女瑟娲笙。\n莲荡折花香未晚，野舟横渡水初晴。\n看高鸿、飞上碧云中，秋一声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16089, '极相思', '吴文英', '玉纤风透秋痕。\n凉与素怀分。\n乘鸾归後，生绡净翦，一片冰云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16090, '思佳客', '吴文英', '丹桂花开第二番。\n东篱展却宴期宽。\n人间宝镜离仍合，海上仙槎去复还。\n分不尽，半凉天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16091, '醉落魄・一斛珠', '吴文英', '春温红玉。\n纤衣学翦娇鸦绿。\n夜香烧短银屏烛。\n偷掷金钱，重把寸心卜。\n翠深不碍鸳鸯宿。\n采菱谁记当时曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16092, '朝中措', '吴文英', '楚皋相遇笑盈盈。\n江碧远山青。\n露重寒香有恨，月明秋佩无声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16093, '杏花天', '吴文英', '蛮姜豆蔻相思味。\n算却在、春风舌底。\n江清爱与消残醉。\n悴憔文园病起。\n停嘶骑、歌眉送意。\n记晓色、东城梦里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16094, '满江红', '吴文英', '露初英，早遗恨、参差九日。\n还却笑、萸随节过，桂凋无色。\n杯面寒香蜂共泛，篱根秋讯蛩催织。\n爱玲珑、筛月水屏风，千枝结。\n芳井韵，寒泉咽。\n霜著处，微红湿。\n共评花索句，看谁先得。\n好漉乌巾连夜醉，莫愁金细无人拾。\n算遗踪、犹有枕囊留，相思物。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16095, '朝中措', '吴文英', '海东明月锁云阴。\n花在月中心。\n天外幽香轻漏，人间仙影难寻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16096, '梦行云', '吴文英', '簟波皱纤。\n朝炊熟。\n眠未足。\n青奴细腻，未拌真珠斛。\n素莲幽怨风前影，搔头斜坠玉。\n画阑枕水，垂杨疏雨，青丝乱、如乍沐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16097, '天香', '吴文英', '碧藕藏丝，红莲并蒂，荷塘水暖香斗。\n窈窕文窗，深沈书幔，锦瑟岁华依旧。\n洞箫韵里，同跨鹤、青田碧岫。\n菱镜妆台挂玉，芙蓉艳褥铺绣。\n西邻障蓬澡手。\n共华朝、梦兰分秀。\n未冷绮帘犹卷，浅冬时候。\n秋到霜黄半亩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16098, '谒金门', '吴文英', '鸡唱晚。\n斜照西窗白暖。\n一沈午酲幽梦远。\n素衾春絮软。\n紫燕红楼歌断。\n锦瑟华年一箭。\n偷果风流输曼倩。\n昼际生绣线。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16099, '点绛唇', '吴文英', '香泛罗屏，夜寒著酒宜偎倚。\n翠偏红坠。\n唤起芙蓉睡。\n一曲伊州，秋色芭蕉里。\n娇和醉。\n眼情心事。\n愁隔湘江水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16100, '夜游宫', '吴文英', '人去西楼雁杳。\n叙别梦、扬州一觉。\n云澹星疏楚山晓。\n听啼乌，立河桥，话未了。\n雨外蛩声早。\n细织就、霜丝多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16101, '瑶华', '吴文英', '秋风采石，羽扇挥兵，认紫骝飞跃。\n江蓠塞草，应笑春、空锁凌烟高阁。\n胡歌奏陇，问铙鼓、新词谁作。\n有秀荪、来染吴香，瘦马青刍南陌。\n冰澌细响长桥，荡波底蛟腥，不霜锷。\n乌丝醉墨，红袖暖、十里湖山行乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16102, '思佳客', '吴文英', '自唱新词送岁华。\n鬓丝添得老生涯。\n十年旧梦无寻处，几度新春不在家。\n衣懒换，酒难赊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16103, '六丑', '吴文英', '渐新鹅映柳，茂苑锁、东风初掣。\n馆娃旧游，罗襦香未灭。\n玉夜花节。\n记向留连处，看街临晚，放小帘低揭。\n星河潋艳春云热。\n笑靥梅，仙衣舞缬。\n澄澄素娥宫阙。\n醉西楼十二，铜漏催彻。\n红消翠歇。\n叹霜簪练发。\n过眼年光，旧情尽别。\n泥深厌听啼。\n恨愁霏润沁，陌头尘袜。\n青鸾杳、细车音绝。\n却因甚、不把欢期，付与少年华月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16104, '青玉案', '吴文英', '东风客雁溪边道。\n带春去、随春到。\n认得踏青香径小。\n伤高怀远，乱云深处，目断湖山杳。\n梅花似惜行人老。\n不忍轻飞送残照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16105, '采桑子', '吴文英', '茜罗结就丁香颗，颗颗相思。\n犹记年时。\n一曲春风酒一卮。\n彩鸾依旧乘云到，不负心期。\n清睡浓时。\n香趁银屏胡蝶飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16106, '水龙吟', '吴文英', '好山都在西湖，斗城转北多流水。\n屋边五亩，桥通双沼，平烟蘸翠。\n旋叠云根，半开竹径，鸥来须避。\n四时长把酒，临花傍月，无一日、不春意。\n独乐当时高致。\n醉吟篇、如今还继。\n举头见日，葵心倾□，□□归计。\n浮碧亭□，泛红波迥，桃源人世。\n待天香□□，开时又胜，翠阴青子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16107, '望江南・忆江南', '吴文英', '三月暮，花落更情浓。\n人去秋千闲挂月，马停杨柳倦嘶风。\n堤畔画船空。\n恹恹醉，长日小帘栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16108, '采桑子', '吴文英', '水亭花上三更月，扇与人闲。\n弄影阑干。\n玉燕重抽拢坠簪。\n心期偷卜新莲子，秋入眉山。\n翠破红残。\n半簟湘波生晓寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16109, '清平乐', '吴文英', '柔柯翦翠。\n胡蝶双飞起。\n谁堕玉细花径里。\n香带熏风临水。\n露红滴□秋枝。\n金泥不染禅衣。\n结得同心成了，任教春去多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16110, '燕归梁', '吴文英', '白玉搔头坠髻松。\n怯冷翠裙重。\n当时离佩解丁东。\n澹云低、暮江空。\n青丝结带鸳鸯盏，岁华晚、又相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16111, '西江月', '吴文英', '江上桃花流水，天涯芳草青山。\n楼台春锁碧湾。\n都入行人望眼。\n一镜波平鸥去，千林日落鸦还。\n天风袅袅送轻帆。\n蓦过星槎银汉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16112, '满江红', '吴文英', '翠暮深庭，露红晚、闲花自发。\n春不断、亭台成趣，翠阴蒙密。\n紫燕雏飞帘额静，金鳞影转池心阔。\n有花香、竹色赋闲情，供吟笔。\n闲问字，评风月。\n时载酒，调冰雪。\n似初秋入夜，浅凉欺葛。\n人境不教车马近，醉乡莫放笙歌歇。\n倩双成、一曲紫云回，红莲折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16113, '夜行船', '吴文英', '鸦带斜阳归远树。\n无人听、数声钟暮。\n日与愁长，心灰香断，月冷竹房扃户。\n画扇青山吴苑路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16114, '好事近', '吴文英', '翠冷石床云，海上偷传新曲。\n弹作一檐风雨，碎芭蕉寒绿。\n冰泉轻泻翠筒香，林果荐红玉。\n早是一分秋意，到临窗修竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16115, '鹧鸪天', '吴文英', '池上红衣伴倚阑。\n栖鸦常带夕阳还。\n殷云度雨疏桐落，明月生凉宝扇闲。\n乡梦窄，水天宽。\n小窗愁黛澹秋山。\n吴鸿好为传归信，杨柳阊门屋数间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16116, '虞美人影・桃源忆故人', '吴文英', '黄包先著风霜劲。\n独占一年佳景。\n点点吴盐雪凝。\n玉脍和齑冷。\n洋园谁识黄金径。\n一棹洞庭秋兴。\n香荐兰皋汤鼎。\n残酒西窗醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16117, '花上月令', '吴文英', '文园消渴爱江清。\n酒肠怯，怕深觥。\n玉舟曾洗芙蓉水，泻清冰。\n秋梦浅，醉云轻。\n庭竹不收帘影去，人睡起，月空明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16118, '卜算子', '吴文英', '凉挂晓云轻，声度西风小。\n井上梧桐应未知，一叶云鬟袅。\n来雁带书迟，别燕归程早。\n频探秋香开未开，恰似春来了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16119, '凤栖梧・蝶恋花', '吴文英', '开过南枝花满院。\n新月西楼，相约同针线。\n高树数声蝉送晚。\n归家梦向斜阳断。\n夜色银河情一片。\n轻账偷欢，银烛罗屏怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16120, '霜天晓角', '吴文英', '烟林褪叶。\n红藉游人。\n十里秋声松路，岚云重、翠涛涉。\n伫立。\n闲素。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16121, '乌夜啼', '吴文英', '西风先到岩扃。\n月笼明。\n金露啼珠滴翠，小银屏。\n一颗颗，一星星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16122, '夜行船', '吴文英', '逗晓阑干沾露水。\n归期杳、画檐鹊喜。\n粉汗馀香，伤秋中酒，月落桂花影里。\n屏曲巫山和梦倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16123, '凤栖梧・蝶恋花', '吴文英', '湘水烟中相见早。\n罗盖低笼，红拂犹娇小。\n妆镜明星争晚照。\n西风日送凌波杳。\n惆怅来迟羞窈窕。\n一霎留连，相伴阑干悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16124, '生查子', '吴文英', '当楼月半奁，曾买菱花处。\n愁影背阑干，素发残风露。\n神前鸡酒盟，歌断秋香户。\n泥落画梁空，梦想青春语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16125, '霜天晓角', '吴文英', '香莓幽径滑。\n索绕秋曲折。\n帘额红摇波影，鱼惊坠、暗吹沫。\n浪阔。\n轻棹拨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16126, '西江月', '吴文英', '添线绣床人倦，翻香罗暮烟斜。\n五更箫鼓贵人家。\n门外晓寒嘶马。\n帽压半檐朝雪，镜开千靥春霞。\n小帘沽酒看梅花。\n梦到林逋山下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16127, '恋绣衾', '吴文英', '频摩书眼怯细文。\n小窗阴、天气似昏。\n兽炉暖、慵添困，带茶烟、微润宝薰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16128, '杏花天', '吴文英', '鬓棱初翦玉纤弱。\n早春入、屏山四角。\n少年买困成欢谑。\n人在浓香绣幄。\n霜丝换、梅残梦觉。\n夜寒重、长安紫陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16129, '醉桃源・阮郎归', '吴文英', '五更枥马静无声。\n邻鸡犹怕惊。\n日华平晓弄春明。\n暮寒愁翳生。\n新岁梦，去年情。\n残宵半酒醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16130, '唐多令', '吴文英', '何处合成愁。\n离人心上秋。\n纵芭蕉、不雨也飕飕。\n都道晚凉天气好，有明月、怕登楼。\n年事梦中休。\n花空烟水流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16131, '好事近', '吴文英', '雁外雨丝丝，将恨和愁都织。\n玉骨西风添瘦，减尊前歌力。\n袖香曾枕醉红腮，依约唾痕碧。\n花下凌波入梦，引春雏双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16132, '忆旧游', '吴文英', '送人犹未苦，苦送春、随人去天涯。\n片红都飞尽，正阴阴润绿，暗裹啼鸦。\n赋情顿雪双鬓，飞梦逐尘沙。\n叹病渴凄凉，分香瘦减，两地看花。\n西湖断桥路，想系马垂杨，依旧斜。\n葵麦迷烟处，问离巢孤燕，飞过谁家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16133, '宴清都', '吴文英', '病渴文园久。\n梨花月，梦残春故人旧。\n愁弹枕雨，衰翻帽雪，为情。\n千金醉跃骄骢，试问取、朱桥翠柳。\n痛恨不、买断斜阳，西湖酝入春酒。\n吴宫乱水斜烟，留连倦客，慵更回首。\n幽蛩韵苦，哀鸿叫绝，断音难偶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16134, '金缕歌・贺新郎', '吴文英', '乔木生云气。\n访中兴、英雄陈迹，暗追前事。\n战舰东风悭借便，梦断神州故里。\n旋小筑、吴宫闲地。\n华表月明归夜鹤，叹当时、花竹今如此。\n枝上露，溅清泪。\n遨头小簇行春队。\n步苍苔、寻幽别坞，问梅开未。\n重唱梅边吸度曲，催发寒梢冻蕊。\n此心与、东君同意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16135, '醉落魄・一斛珠', '吴文英', '柔怀难托。\n老天如水人情薄。\n烛痕犹刻西窗约。\n歌断梨云，留梦绕罗幕。\n寒更唱遍吹梅角。\n香消臂趁弓削。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16136, '朝中措', '吴文英', '晚妆慵理瑞云盘。\n针线傍灯前。\n燕子不归帘卷，海棠一夜孤眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16137, '青玉案', '吴文英', '短亭芳草长亭柳。\n记桃叶，烟江口。\n今日江村重载酒。\n残杯不到，乱红青冢，满地闲春绣。\n翠阴曾摘梅枝嗅。\n还忆秋千玉葱手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16138, '青玉案', '吴文英', '新腔一唱双金斗。\n正霜落、分甘手。\n已是红窗人倦绣。\n春词裁烛，夜香温被，怕减银壶漏。\n吴天雁晓云飞後。\n百感情怀顿疏酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16139, '好事近', '吴文英', '飞露洒银床，叶叶怨梧啼碧。\n蕲竹粉连香汗，是秋来陈迹。\n藕丝空缆宿湖船，梦阔水云窄。\n还系鸳鸯不在，老红香月白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16140, '杏花天', '吴文英', '幽欢一梦成炊黍。\n知绿暗、汀菰几度。\n竹西歌断芳尘去。\n宽尽经年臂缕。\n梅黄後、林梢更雨。\n小池面、啼红怨暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16141, '浪淘沙', '吴文英', '灯火雨中船。\n客思绵绵。\n离亭春草又秋烟。\n似与轻鸥盟未了，来去年年。\n往事一潸然。\n莫过西园。\n凌波香断绿苔钱。\n燕子不知春事改，时立秋千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16142, '思佳客', '吴文英', '迷蝶无踪晓梦沈。\n寒香深闭小庭心。\n欲知湖上春多少，但看楼前柳浅深。\n愁自遣，酒孤斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16143, '采桑子慢', '吴文英', '桐敲露井，残照西窗人起。\n怅玉手、曾携乌纱，笑整风。\n水叶沈红，翠微云冷雁慵飞。\n楼高莫上，魂消正在，摇落江蓠。\n走马断桥，玉台妆榭，罗帕香遗。\n叹人老、长安灯外，愁换秋衣。\n醉把茱萸，细看清泪湿芳枝。\n重阳重处，寒花怨蝶，新月东篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16144, '古香慢', '吴文英', '怨娥坠柳，离佩摇荭，霜讯南圃。\n漫忆桥扉，倚竹袖寒日暮。\n还问月中游，梦飞过、金风翠羽。\n把残云、剩水万顷，暗熏冷麝凄苦。\n渐浩渺、凌山高处。\n秋澹无光，残照谁主。\n露粟侵肌，夜约羽林轻误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16145, '蹋莎行・踏莎行', '吴文英', '杨柳风流，蕙花清润。\n苹□未数张三影。\n沈香倚醉调清平，新辞□□□□□。\n鲛室裁绡，□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16146, '失调名', '吴文英', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16147, '烛影摇红', '翁元龙', '蜀锦华堂，宝筝频送花前酒。\n妖娆全在半开时，人试单衣後。\n花面围春竞秀。\n如红潮、玉腮微透。\n欲苏还坠，浅醉扶头，朦胧晴昼。\n金屋名姝，眼情空伫闲眉岫。\n世间还有此娉婷，拼尽珠量斗。\n真艳可令消受。\n倩莺催、天香共袖。\n冷烟庭院，淡月梨花，空教春瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16148, '齐天乐', '翁元龙', '曲廊连苑吹笙道，重来暗尘都满。\n种石生云，移花带月，犹欠藏春庭院。\n年华过眼。\n便梅谢兰销，舞沈歌断。\n露井寒蛩，为谁清夜诉幽怨。\n人生乐事最少，有时得意处，光阴偏短。\n树色凝红，山眉弄碧，不与朱颜相恋。\n临风念远。\n叹蝶梦难追，鹭盟重换。\n一片斜阳，送人归骑晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16149, '菩萨蛮', '翁元龙', '春心莫共花争发。\n花开不管连环缺。\n梦断小楼空。\n杜鹃啼晓红。\n眼看连理树。\n纤手移筝柱。\n调遍错成声。\n无人知此情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16150, '菩萨蛮', '翁元龙', '玉纤闲捻花间集。\n赤阑干对芭蕉立。\n薤叶晚生凉。\n竹阴移小床。\n拗莲牵藕线。\n藕断丝难断。\n弹水没鸳鸯。\n教寻波底香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16151, '倦寻芳', '翁元龙', '燕帘挂晚。\n莺槛迷晴，花思零乱。\n试觅娉婷，日日傍湖亭苑。\n掷果墙阴窥驻马，采香深迳抛春扇。\n醉归来，任钗云半落，绣帘慵卷。\n念灿锦、年华如旧，飞絮游丝，萦恨难翦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16152, '瑞龙吟', '翁元龙', '清明近。\n还是递趱东风，做成花讯。\n芳时一刻千金，半晴半雨、酬春未准。\n雁归尽。\n离字向人欲写，暗云难认。\n西园猛忆逢迎，翠纨障面，花间笑隐。\n曲径池莲平砌，绛裙曾与，濯香湔粉。\n无奈燕幕莺帘，轻负娇俊。\n青榆巷陌，蹋马红成寸。\n十年梦、秋千吊影，袜罗尘褪。\n事往凭谁问。\n昼长病酒添新恨。\n烟冷斜阳紧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16153, '隔浦莲近・隔浦莲近拍', '翁元龙', '街檐插缀翠柳。\n憔悴清明後。\n泪蜡堆香径，一夜海棠中酒。\n枝上酸似豆。\n莺声骤。\n恨软弹筝手。\n眉袖。\n嘶骢过尽平芜，绿衬飞绣。\n沈红入水，渐做小莲离藕。\n亭冷沈香梦似旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16154, '玲珑四犯', '翁元龙', '窗外啼莺，报数日西园，花事都空。\n绣屋专房，姚魏渐邀新宠。\n葱翠试剪春畦，羞对酒、夜寒犹重。\n误暗期、绿架香洞。\n月黯小阶云冻。\n算春将揽邮亭。\n柳成圈、记人迎送。\n蜀魂怨染岩花色，泥径红成陇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16155, '风流子', '翁元龙', '天阔玉屏空。\n轻阴弄、淡墨画秋容。\n正凉挂半蟾，酒醒窗下，露催新雁，人在山中。\n又一片，好秋花占了，香换却西风。\n箫女夜归，帐栖青凤，镜娥妆冷，钗坠金虫。\n西湖花深窈，闲庭砌、曾占席地歌钟。\n载取断云归去，几处房栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16156, '西江月', '翁元龙', '山色低衔小苑，春云暗宿空庭。\n秋千无月冷双绳。\n闲却画栏人静。\n一夜海棠如梦，半窗银烛多情。\n好花留不到清明。\n日日阴晴无定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16157, '忆秦娥', '翁元龙', '三月时。\n杨花飞尽无花飞。\n无花飞。\n不教春去，争得春归。\n高楼望断黄金羁。\n绿窗眉黛伤新离。\n伤新离。\n好将别後，长做归时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16158, '恋绣衾', '翁元龙', '兽炉烟重火半焦。\n卷帘时、雪意又销。\n过数点、残鸦外，想梅花、寒在灞桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16159, '水龙吟', '翁元龙', '画楼红湿斜阳，素妆褪出山眉翠。\n街声暮起，尘侵灯户，月来舞地。\n宫柳招莺，水荭飘雁，隔年春意。\n黯梨云，散作人间好梦，琼箫在、锦屏底。\n乐事轻随流水。\n暗兰消、作花心计。\n情丝万轴，因春织就，愁罗恨绮。\n昵沈迷香，占帘看夜，旧游轻醉。\n任孤山、剩雪残梅，渐懒跨、东风骑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16160, '醉桃源・阮郎归', '翁元龙', '千丝风雨万丝晴。\n年年长短亭。\n暗黄看到绿成阴。\n春由他送迎。\n莺思重，燕愁轻。\n如人离别情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16161, '谒金门', '翁元龙', '莺树暖。\n弱絮欲成芳茧。\n流水惜花流不远。\n小桥红欲满。\n原上草迷离苑。\n金勒晚风嘶断。\n等得日长春又短。\n愁深山翠浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16162, '绛都春', '翁元龙', '花娇半面。\n记蜜烛夜阑，同醉深院。\n衣袖粉香，犹未经年如年远。\n玉颜不趁秋容换。\n但换却、春游同伴。\n梦回前度，邮亭倦客，又拈笺管。\n慵按。\n梁州旧曲，怕离柱断弦，惊破金雁。\n霜被睡浓，不比花前良宵短。\n秋娘羞占东篱畔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16163, '江城子', '翁元龙', '一年箫鼓又疏钟。\n爱东风。\n恨东风。\n吹落灯花，移在杏梢红。\n玉靥翠钿无半点，空湿透，绣罗弓。\n燕魂莺梦渐惺松。\n月帘栊。\n影迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16164, '西江月', '翁元龙', '画阁换黏春贴，宝筝抛学银钩。\n东风轻滑玉钗流。\n织就燕纹莺绣。\n隔帐灯花微笑，倚窗云叶低收。\n双鸳刺罢底尖头。\n剔雪闲寻豆蔻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16165, '朝中措', '翁元龙', '花情偏与夜相投。\n心事鬓边羞。\n薰醒半床凉梦，能消几个开头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16166, '鹊桥仙', '翁元龙', '天长地久，风流云散，惟有离情无算。\n从分金镜不成圆，到此夜、年年一半。\n轻罗暗网，蛛丝得意，多似妆楼针线。\n晓看玉砌淡无痕，但吹落、梧桐几片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16167, '烛影摇红', '翁孟寅', '楼倚春城，锁窗曾共巢春燕。\n人生好梦比春风，不似杨花健。\n旧事如天渐远。\n奈情缘、素丝未断。\n镜尘埋恨，带粉栖香，曲屏寒浅。\n环佩空归，故园羞见桃花面。\n轻烟残下阑干，独自疏帘卷。\n一信狂风又晚。\n海棠花、随风满院。\n乱鸦归後，杜宇啼时，一声声怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16168, '阮郎归', '翁孟寅', '月高楼外柳花明。\n单衣怯露零。\n小桥灯影落残星。\n寒烟蘸水萍。\n歌袖窄，舞鬟轻。\n梨花梦满城。\n落红啼鸟两无情。\n春愁添晓酲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16169, '齐天乐', '翁孟寅', '幽香不受春料理，青青尚馀秋鬓。\n曲岩隈，烟梳露浴，甘与菰蒲共隐。\n芳标瘦迥。\n看缨结丁香，带萦晴荇。\n恨水东流，楚江憔悴乱云暝。\n凄凉梦游故苑，纵妒花风暴，吹梦难醒。\n艳李妖桃，纡青佩紫，争似广文官冷。\n尘波万顷。\n算谁是同心，自怜孤影。\n收敛风流，素弦清夜永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16170, '齐天乐', '翁孟寅', '红香十里铜驼梦，如今旧游重省。\n节序飘零，欢娱老大，慵立灯光蟾影。\n伤心对景。\n怕回首东风，雨晴难准。\n曲巷幽坊，管弦一片笑声近。\n飞棚浮动翠葆，看金钗半溜，春妒红粉。\n凤辇鳌山，云收雾敛，迤逦铜壶漏迥。\n霜风渐紧。\n展一幅青绡，净悬孤镜。\n带醉扶归，晓酲春梦稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16171, '摸鱼儿', '翁孟寅', '卷西风、方肥塞草，带钩何事东去。\n月明万里关河梦，吴楚几番风雨。\n江上路。\n二十载头颅，凋落今如许。\n凉生弄尘。\n叹江左夷吾，隆中诸葛，谈笑已尘土。\n寒汀外，还见来时鸥鹭。\n重来应是春暮。\n轻裘岘首陪登眺，马上落花飞絮。\n拼醉舞。\n谁解道，断肠贺老江南句。\n沙津少驻。\n举目送飞鸿，幅巾老子，楼上正凝伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16172, '蝶恋花', '万俟绍之', '啼一声云榭晚。\n好梦惊回，蓬岛疑行遍。\n无绪东风帘自卷。\n香苞云压荼シ院。\n似有还无烟色展。\n絮暖鱼肥，时复吹池面。\n扇影著花蜂蝶见。\n药栏春静红尘远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16173, '风入松', '万俟绍之', '一春心事与谁同。\n绿聚眉峰。\n小楼彻夜听鸣雨，想西园、锦绣成空。\n栏漾金鱼池水，钩闲紫燕帘风。\n年时忻折海棠红。\n来比芳容。\n如今玉减香销似，怕轻寒、懒出房栊。\n尘满谢娘吟卷，从教飞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16174, '贺新郎', '万俟绍之', '决眦入飞鸟。\n正江南、梅雨初晴，乱山浮晓。\n凤去台空箫声断，惟有疏林鸦噪。\n但空锁、吴时花草。\n指点中原青山外，奈征尘、迷望愁云绕。\n佳丽地，谩凝眺。\n清风助我舒长啸。\n问其中、虚帘曲槛，阅人多少。\n风景不殊江山在，况是英雄未老。\n且拚与、尊前一笑。\n欲说前朝兴亡事，唤谪仙、来共传清。\n归路晚，月明照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16175, '江神子・江城子', '万俟绍之', '十年心事上眉端。\n梦惊残。\n琐窗寒。\n云絮随风，千里度关山。\n琴里知音无觅处，妆粉淡，钏金宽。\n瑶箱吟卷懒重看。\n忆前欢。\n泪偷弹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16176, '水龙吟', '丁宥', '雁风吹裂云痕，小楼一线斜阳影。\n残蝉抱柳，寒蛩入户，凄音忍听。\n愁不禁秋，梦还惊客，青灯孤枕。\n未更深，早是梧桐泫露，那更度、兰宵永。\n空叹银屏金井。\n醉乡醒、温柔乡冷。\n征尘倦扑，闲花谩舞，何心管领。\n葱指冰弦，蕙怀春锦，楚梅风韵。\n怅芙蓉城杳，蓝云依黯，锁巫峰暝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16177, '法曲献仙音', '丁宥', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16178, '失调名', '丁宥', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16179, '六么令', '丁宥', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16180, '瑞鹤仙', '周氏', '画楼帘卷翠。\n正柳约东风，摇荡春霁。\n缃桃雨才洗。\n似妆临宝镜。\n脂凝铅水。\n云偏髻子。\n坠钗梁、羞看燕垒。\n最堪怜，锦绣香中，早有片红飘砌。\n闲记。\n琴弹古调，曲按清商，旧年时事。\n屏山画里。\n江南信，梦中寄。\n感春浓怀抱，午酲初解，浅酌依然又醉。\n傍阑干、犹怯馀寒，倦和袖倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16181, '水龙吟', '潘', '（上缺）玉带悬鱼，黄金铸印，侯封万户。\n待从头，缴纳君王，觅取爱卿归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16182, '南乡子', '潘', '生怕倚阑干。\n阁下溪声阁外山。\n惟有旧时山共水，依然。\n暮雨朝云去不远。\n应是蹑飞鸾。\n月下时时整佩环。\n月又渐低霜又下，更阑。\n折得梅花独自看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16183, '乌夜啼', '潘', '无端小雪廉纤。\n入平檐。\n金鸭旋添龙饼，莫开帘。\n寻梅约。\n开还落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16184, '满江红', '潘', '筑室依崖，春风送、一帘山色。\n沙岛外，渔樵而已，别无闲客。\n醉後和友眠犊背，醒来瀹茗寻泉脉。\n把心情、分付陇头云，溪边石。\n身未老，头先白。\n人不见，山空碧。\n约钓竿共把，自惭钩直。\n相蜀吞吴成底事，何如只抱隆中膝。\n漫长歌、歌罢悄无言，看青壁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16185, '洞仙歌', '潘', '雕檐绮户，倚晴空如画。\n曾是吴王旧台榭。\n自浣纱去後，落日平芜，行云断，几见花开花谢。\n凄凉阑干外，一簇江山，多少图王共争霸。\n莫闲愁、金杯潋滟，对酒当歌，欢娱地、梦中兴亡休话。\n渐倚遍、西风晚潮生，明月里、鹭鹚背人飞下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16186, '霜天晓角', '赵希', '娥戏剧。\n手种长生粒。\n宝干婆娑千古，飘芳吹满虚碧。\n韵色。\n檀露滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16187, '秋蕊香', '赵希', '髻稳冠宜翡翠。\n压鬓彩丝金蕊。\n远山碧浅蘸秋水。\n香暖榴裙衬地。\n亭亭二八馀年纪。\n恼春意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16188, '摸鱼儿', '孙吴会', '八窗空、展宽秋影，长江流入尊俎。\n天围绀碧低群岫，斜日去鸿堪数。\n沈别浦。\n但目断、烟芜莽苍连平楚。\n晨钟暮鼓。\n算触景多愁，关人底事，倚槛听鸣橹。\n英雄恨，赢得名存北府。\n寄奴今寄何所。\n西风依旧潮来去，山海颉颃吞吐。\n霜月古。\n直耐冷、相随燕我瑶芝圃。\n掀髯起舞。\n看伏苍苔，龙吟翠葆，天籁奏韶舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16189, '临江仙', '赵', '堤曲朱墙近远，山明碧瓦高低。\n好风二十四花期。\n骄骢穿柳去，文挟春飞。\n箫鼓晴雷殷殷，笑歌香雾霏霏，闲情不受酒禁持。\n断肠无立处，斜日欲归时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16190, '吴山青・长相思', '赵', '金璞明。\n玉璞明。\n小小杯翠袖擎。\n满将春色盛。\n仙佩鸣。\n玉佩鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16191, '庆宫春・高阳台', '刘澜', '春翦绿波，日明金渚，镜光尽浸寒碧。\n喜溢双蛾，迎风一笑，两情依旧脉脉。\n那时同醉，锦袍湿、乌纱侧。\n英雄何在，满目青山，飞下孤白。\n片帆谁上天门，我亦明朝，是天门客。\n平生高兴，青莲一叶，从此飘然八极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16192, '瑞鹤仙', '刘澜', '向阳看未足。\n更露立阑干，日高人独。\n江空佩鸣玉。\n问烟鬟霞脸，为谁膏沐。\n情闲景淑。\n嫁东风、无媒自卜。\n凤台高，贪伴吹笙，惊下九天霜鸪。\n红蹙。\n花开不到，杜老溪庄，已公茅屋。\n山城水国。\n欢易断，梦难续。\n记年时马上，人酣花醉，乐奏开元旧曲。\n夜归来，驾锦漫天，绛纱万烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16193, '齐天乐', '刘澜', '玉钗分向金华後，回头路迷仙苑。\n落翠惊风，流红逐水，谁信人间重见。\n花深半面。\n尚歌得新词，柳家三变。\n绿叶阴阴，可怜不似那时看。\n刘郎今度更老，雅怀都不到，书带题扇。\n花信风高，苕溪月冷，明日云帆天远。\n尘缘较短。\n怪一梦轻回，酒阑歌散。\n别鹤惊心，感时花泪溅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16194, '买陂塘・摸鱼儿', '刘澜', '御风来、翠乡深处，连天云锦平远。\n卧游已动蓬舟兴，那在芙蓉城畔。\n巾懒岸。\n任压顶嵯峨，满鬓丝零乱。\n飞吟水殿。\n载十丈青青，随波弄粉，菰雨泪如霰。\n斜阳外，也有新妆半面。\n无言应对花怨。\n西湖千顷腥尘暗。\n更忆鉴湖一片。\n何日见。\n试折藕占丝，丝与肠俱断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16195, '水调歌头', '魏庭玉', '璧月挂银汉，冷浸一江秋。\n天公付我清赏，仙籍桂香浮。\n极目江山如画，际晚云烟凝紫，秋色豁羁愁。\n领看上雄观，波影动帘钩。\n雁排空，渔唱晚，楚天幽。\n湖阴一曲千载，成败倩谁筹。\n试问谪仙何处，唤起于湖同醉，小为作遨头。\n老子欲起舞，摆脱利名休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16196, '贺新凉・贺新郎', '魏庭玉', '暮雨初收霁。\n凭阑干、一江新绿，远山凝翠。\n漠漠春阴添客思，怅望天涯无际。\n又猛省、平生行止。\n楚尾吴头多少恨，付吟边、醉里消磨矣。\n浮世事，只如此。\n阳关三叠徒劳耳。\n也何须、琵琶江上，掩青衫泪。\n一斗百篇乘逸兴，要借青天为纸。\n儿辈诧、龙蛇飞起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16197, '晴偏好', '李霜涯', '平湖百顷生芳草。\n芙蓉不照红颠倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16198, '渔父词・渔父', '王谌', '兰芷流来水亦香。\n满汀鸥鹭动斜阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16199, '渔父词・渔父', '王谌', '翁妪齐眉妇亦贤。\n小姑颜貌正笄年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16200, '渔父词・渔父', '王谌', '湘妃泪染竹痕斑。\n风雨连朝下钓难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16201, '渔父词・渔父', '王谌', '满湖飞雪搅长空。\n急起呼儿上短蓬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16202, '渔父词・渔父', '王谌', '离骚读罢怨声声。\n曾向江边问屈平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16203, '渔父词・渔父', '王谌', '白发松不记年。\n扁舟泊在荻花边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16204, '渔父词・渔父', '王谌', '只在青山可卜邻。\n妻儿笑语意全真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16205, '万年欢', '厉寺正', '卫武期颐，与文公福艾，俱号贤相。\n今我元台，齿德又居其上。\n玉立擎天一柱，似泰华、气凌秋庄。\n明良会，千载风云，长为龙衮凭仗。\n清知孔山叠嶂。\n有猿吟鹤舞，日俟鸠杖。\n无忝苍生依依，未容高尚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16206, '摸鱼儿', '施枢', '柳蒙茸、暗凌波路。\n烟飞惨淡平楚。\n七香车驻猊环掩，遥认翠华云母。\n芳景暮。\n鸳悄、铢衣来按飞琼舞。\n凄凉洛浦。\n渐玉漏沈沈，清阴满地，乘月步虚去。\n销凝处。\n谁说三生小杜。\n翔螭声断箫鼓。\n情知禁苑酥尘，羞与倡红同谱。\n春几度。\n想依旧、苔痕长印唐昌土。\n风流千古。\n人在小红楼，朱帘半卷，香注玉壶露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16207, '疏影', '施枢', '低枝亚实。\n望翠阴护晓，幽梦难觅。\n凄楚霓裳，琼阙瑶台，经年暗锁清逸。\n春风似怪重门掩，未许入、玉堂吟笔。\n想寿阳，却厌新妆，倦抹粉花宫额。\n还记孤山旧路，未应便负了，波冷蟾白。\n莫寄相思，惟有寒烟，伴我骚人闲寂。\n东君须自怜疏影，又何待、山前雪积。\n好试敲、羯鼓声催，与约鼎羹消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16208, '柳梢青', '施枢', '飞露初霜。\n冷侵金井，响到银床。\n懊恨碧梧，不留一叶，月占纱窗。\n雁声做尽凄凉。\n又陡顿、衾寒夜长。\n曲曲屏山，重重客梦，无限思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16209, '齐天乐', '储泳', '东风一夜吹寒食，枝头片红犹恋。\n宿酒初醒，新吟未稳，凭久栏杆留暖。\n将春买断。\n恨苔径榆阶，翠钱难贯。\n陌上秋千，相逢谁认旧时伴。\n轻衫粉痕褪了，丝缘馀梦在，良宵偏短。\n柳线经烟，莺梭织雾，一片旧愁新怨。\n慵拈象管。\n待寄与深情，难凭双燕。\n不似杨花，解随人去远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16210, '西江月', '储泳', '壁断何人旧字，炉寒隔岁残香。\n洞天人去海茫茫。\n玩世仙翁已往。\n西日长安道远，春风赵国台荒。\n行人谁不悟黄粮。\n依旧红尘陌上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16211, '念奴娇', '刘子实', '一门相种，剩河英岳粹，共扶昌录。\n夹辅正宜资鲁卫，左右秉持钧轴。\n缓驾轻车，任回虎节，何事劳山国。\n东民欲靖，作新少借康叔。\n况是佳辰，雪霜深处，秀孕椿松绿。\n天意特教荣晚节，挺挺世臣乔木。\n绣斧功成，衮衣促觐，莫恨公归速。\n一陶和气，要令天下蒙福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16212, '沁园春', '刘子实', '腊後寒收，柳眼青归，梅花笑生。\n正阳和有脚，日边送暖，洪钧换轴，天上回星。\n试巧春盘，介眉春酒，生意从头乐意新。\n须知道，是东风近也，玉燕逢辰。\n举头阊阖开明。\n便稳驾轻车熟路行。\n向玉堂青琐，从容洒翰，长淮赤壁，谈笑麾兵。\n周洛犹尘，商未雨，天下苍生望太平。\n休盘涧，任清溪九曲，不放舟横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16213, '贺新郎', '翁合', '世事今如许。\n祗先生、寿身寿国，尚堪撑拄。\n一脉宽仁忠厚意，留到如今可数。\n问谁是、擎天一柱。\n名节难全官职易，这娥眉、肯效争妍妒。\n几而作，色斯举。\n沧州万顷舟横渡。\n对和风、桃花流水，一蓑烟雨。\n亲得紫阳传正印，且作斯文宗主。\n世望皋夔伊傅。\n天意须酬平治愿，抚参同、一卷长生谱。\n平治了，仙为侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16214, '卜算子', '翁合', '口诵百中经，手运周天数。\n试问薇垣一小星，谁知是、韩王普。\n知得客星来，知得贤人聚。\n我若乘槎犯斗牛，莫向常人语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16215, '贺新郎', '王庚', '满劝黄封酒。\n是年年、春色长绕，径花宫柳。\n碧水丹山添清气，岁月兰亭癸丑。\n看枢极、光腾台斗。\n细数中书堂壁记，自欧韩、富范题名後，还有似、我公否。\n好知天意生贤候，正造化安排，孕出五阳之秀。\n何物一阴犹踯躅，尽决还公只手。\n这一著、邦家之寿。\n宰相时来须教做，算人间、是处鱼羹有。\n名与节，久轩久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16216, '小重山', '黄铸', '凉入秋檐雨意长。\n竹深啼络纬，响虚堂。\n一枝灯影耿昏黄。\n疏帘外，风度木樨香。\n心事易成伤。\n燕支坡下路，语如簧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16217, '秋蕊香令', '黄铸', '花外数声风定。\n烟际一痕月净。\n水晶屏小醉枕。\n院静鸣蛩相应。\n香销斜掩青铜镜。\n背灯影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16218, '庆清朝', '李宏模', '碧玉云深，彤绡雾薄，芳丛乱迷秋渚。\n重城傍水，中有吹箫俦侣。\n应是琼楼夜冷，月明谁伴乘鸾女。\n仙游处。\n翠障尘，红绮随步。\n别岸玉容伫倚，爱浅抹蜂黄，淡笼纨素。\n娇羞未语，脉脉悲烟泣露。\n彩扇何人，妙笔丹青，招得花魂住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16219, '木兰花慢', '杨子咸', '紫凋红落後，忽十丈，玉虬横。\n望众绿帏中，蓝田璞碎，鲛室珠倾。\n柔条系风无力，更不禁、连日峭寒清。\n空与蝶圆香梦，枉教莺诉春情。\n深深。\n苔径悄无人。\n栏槛湿香尘。\n叹宝髻松，粉铅狼藉，谁管飘零。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16220, '临江仙', '太学士人', '莫怪钱神容易致，钱神尽是愚夫。\n为何此鬼却相於。\n只因频展义，长是泣穷途。\n韩氏有文曾饯汝，临行慎莫踌躇。\n青灯双点照平湖。\n蕉船从此逝，相共送陶朱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16221, '失调名', '李之问', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16222, '失调名', '吴敏德', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16223, '失调名', '郭子正', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16224, '舜韶新', '郭子正', '香满西风，催岁晚东篱，黄花争吐。\n嫩英细蕊，金艳繁、妆点高秋偏富。\n寒地花媒少，算自结、多情烟雨。\n每年年妆面，谢他拒霜相顾。\n宝马王孙，休笑孤芳，陶令因谁，便思归去。\n负春何事，此恨惟、才子登高能赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16225, '望海潮', '鄱阳护戎女', '云收飞脚，日祛怒暑，新蝉高柳鸣时。\n兰佩紫囊，蒲抽碧剑，吴丝两腕双垂。\n闻道五陵儿。\n蛟龙吼波面，冲碎琉璃。\n画鼓声中，锦标争处红旗。\n使君冠盖追。\n正霞翻酒浪，翠敛歌眉。\n扇动水风生玉宇，微凉透入单衣。\n日暮楚天低。\n金蛇掣电漾，千顷霜溪。\n宴罢休燃宝蜡，凭月照人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16226, '西江月', '尹词客', '韩愈文章盖世，谢安才貌风流。\n良辰开宴在西楼。\n敢劝一卮芳酒。\n记得南宫高第，弟兄都占鳌头。\n金炉玉殿瑞香浮。\n名在甲科第九。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16227, '玉楼春', '尹词客', '浣花溪上风光主。\n燕集瀛洲开幕府。\n商岩本是作霖人，也使闲花沾雨露。\n谁怜氏族传簪组。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16228, '菩萨蛮', '王氏', '横湖十顷琉璃碧。\n画桥百步通南北。\n沙暖睡鸳鸯。\n春风花草香。\n闲来撑小艇。\n划破楼台影。\n四面望青山。\n浑如蓬莱间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16229, '水调歌头', '虞', '憔悴朔家种，零落雪边枝。\n淡妆素艳，无桃笑面柳眉低。\n懒向深宫点额，甘与孤山结社，照影水之湄。\n不怨风霜虐，我本岁寒姿。\n谢东君。\n开冷蕊，弄斜晖。\n强颜红紫同□，皎洁性难移。\n祗好竹篱茅舍，若话玉堂金鼎，老恐负心期。\n歌罢饮先醉，残月坠深卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16230, '月华清', '洪', '花影摇春，虫声吟暮，九霄云幕初卷。\n谁驾冰蟾，拥出桂轮天半。\n素魄映、青琐窗前，皓彩散、画阑干畔。\n凝眄。\n见金波漾，分辉鹊殿。\n况是风柔夜暖。\n正燕子新来，海棠微绽。\n不似秋光，只照离人肠断。\n恨无奈、利锁名缰，谁为唤、舞裙歌扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16231, '水龙吟', '洪', '经年不见书来，後期杳杳从谁问。\n柳英蜡小，柳枝金嫩，艳阳春近。\n罗幕风柔，泛红浮绿，连朝花信。\n念平生多少，情条恨叶，镇长使、芳心困。\n可是风流薄命。\n镜台前、松松蝉鬓。\n茜桃凝粉，薰兰涨腻，翠愁红损。\n纵使归来，灯前月下，恐难相认。\n卷重帘憔悴，残妆泪洗，把罗襟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16232, '蓦山溪', '洪', '潮平风稳，行色催津鼓。\n回首望重城，但满眼、红云紫雾。\n分香解佩，空记小楼东，银烛暗，绣帘垂，昵昵凭肩语。\n关山千里，垂柳河桥路。\n燕子又归来，但惹得、满身花雨。\n彩笺不寄，兰梦更无凭，灯影下，月明中，魂断金钗股。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16233, '齐天乐', '洪', '辘轳声破银床冻，霜寒又侵鸳被。\n皓月疏钟，悲风断漏，惊起画楼人睡。\n银屏十二。\n叹尘满丝簧，暗消金翠。\n可恨风流，故人迢递隔千里。\n相思情绪最苦，旧欢无续处，魂梦空费。\n断雁无情，离鸾有恨，空想吴山越水。\n花憔玉悴。\n但翠黛愁横，红铅泪洗。\n待剪江梅，倩人传此意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16234, '菩萨蛮', '洪', '断虹远饮横江水。\n万山紫翠斜阳里。\n系马短亭西。\n丹枫明酒旗。\n浮生长客路。\n事逐孤鸿去。\n又是月黄昏。\n寒灯人闭门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16235, '菩萨蛮', '洪', '吴姬压酒浮红蚁。\n少年未饮心先醉。\n驻马绿阳阴。\n酒楼三月春。\n相看成一笑。\n遗恨知多少。\n回首欲魂销。\n长桥连断桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16236, '踏莎行', '洪', '满满金杯，垂垂玉筋。\n离歌不放行人去。\n醉中扶上木兰船，醒来忘却桃源路。\n带绾同心，钗分一股。\n断魂空草高唐赋。\n秋山万叠水云深，茫茫无著相思处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16237, '瑞鹤仙', '洪', '听梅花吹动，凉夜何其，明星有烂。\n相看泪如霰。\n问而今去也，何时会面。\n匆匆聚散。\n恐便作、秋鸿社燕。\n最伤情、夜来枕上，断云零雨何限。\n因念。\n人生万事，回首悲凉，都成梦幻。\n芳心缱绻。\n空惆怅，巫阳馆。\n况船头一转，三千馀里，隐隐高城不见。\n恨无情、春水连天，片帆似箭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16238, '浪淘沙', '洪', '花雾涨冥冥。\n欲雨还晴。\n薄罗衫子正宜春。\n无奈今宵鸳帐里，身是行人。\n别酒不须斟。\n难洗离情。\n丝鞘如电紫骝鸣。\n肠断画桥芳草路，月晓风清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16239, '南柯子・南歌子', '洪', '柳浪摇晴沼，荷风度晚檐。\n碧天如水印新蟾。\n一罅清光斜露、玉纤纤。\n宝镜微开匣，金钩半押帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16240, '永遇乐', '洪', '歌雪徘徊，梦云溶曳，欲劝春住。\n薄幸杨花，无端杜宇，抵死催教去。\n参差烟岫，千回百匝，不解禁春归路。\n病厌厌，那堪更听，小楼一夜风雨。\n金钗斗草，玉盘行菜，往事了无凭据。\n合数松儿，分香帕子，总是牵情处。\n小桃朱户，题诗在否，尚忆去年崔护。\n绿阴中，莺莺燕燕，也应解语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16241, '谒金门', '洪', '风共雨。\n催尽乱红飞絮。\n百计留春春不住。\n杜鹃声更苦。\n细柳官河狭路。\n几被婵娟相误。\n空忆坠鞭遗扇处。\n碧窗眉语度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16242, '菩萨蛮', '洪', '玉琴不疗文园病。\n对花长抱深深恨。\n恨入鬓霜边。\n才情输少年。\n蛾眉梳坠马。\n翠袖薰兰麝。\n醉梦未全醒。\n绿窗啼晓莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16243, '阮郎归', '洪', '东风吹破藻池冰。\n晴光开五云。\n绿情红意两逢迎。\n扶春来远林。\n花艳艳，玉英英。\n罗衣金缕明。\n闹蛾儿簇小蜻蜓。\n相呼看试灯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16244, '行香子', '洪', '楚楚精神。\n杨柳腰身。\n是风流、天上飞琼。\n凌波微步，罗袜生尘。\n有许多娇，许多韵，许多情。\n十年心事，两字眉婚。\n问何时、真个行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16245, '鹧鸪天', '洪', '意态婵娟画不如。\n莹然初日照芙蕖。\n笑捐琼佩遗交甫，肯把文梭掷幼舆。\n花上蝶，水中凫。\n芳心密意两相於。\n情知不作庭前柳，到得秋来日日疏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16246, '水龙吟', '楼', '素蛾洗尽繁妆，夜深步月秋千地。\n轻腮晕玉，柔肌笼粉，缁尘敛避。\n霁雪留香，晓云同梦，昭阳宫闭。\n怅仙园路杳，曲栏人寂，疏雨湿、盈盈泪。\n未放游峰叶底。\n怕春归、不禁狂吹。\n象床困倚，冰魂微醒，莺声唤起。\n愁对黄昏，恨催寒食，满襟离思。\n想千红过尽，一枝独冷，把梅花比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16247, '菩萨蛮', '楼', '丝丝杨柳莺声近。\n晚风吹过秋千影。\n寒色一帘轻。\n灯残梦不成。\n耳边消息在。\n笑指花梢待。\n又是不归来。\n满庭花自开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16248, '沁园春', '楼', '开辟以来，便有此山，独当怒涛。\n正秋空万里，寒催雁信，尘寰一簇，轻等鸿毛。\n小可诗情，寻常酒量，到此应须分外豪。\n难为水，算平生未有，此番登高。\n飘飘。\n身踏金鳌。\n笑终日风波无限劳。\n看樯乌缥缈，帆归远浦，廛鱼杂沓，网带馀潮。\n待约诗人，相将月夜，取次携杯持蟹螯。\n乘桴意，问谁人领解，空立亭皋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16249, '念奴娇', '章谦亨', '垂杨得地，在楼台侧畔，无人攀折。\n不似津亭舟系处，只伴客愁离别。\n丝过摇金，带铺新翠，雅称莺调舌。\n芳筵相映，最宜斜挂残月。\n却得连日春寒，未教轻滚，一片庭前雪。\n应恨张郎今老去，难比风流时节。\n醉眼浑醒，愁眉都展，舞困腰肢怯。\n有时微笑，把伊绾个双结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16250, '步蟾宫', '章谦亨', '团小酌醺醺醉。\n厮捱著、没人肯睡。\n呼卢直到五更头，便铺了妆台梳洗。\n庭前鼓吹喧人耳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16251, '摸鱼儿', '章谦亨', '想先生、跨鹤归去。\n依然上界官府。\n胸中邱壑经营巧，留下午桥别墅。\n堪爱处。\n山对起、飞来万马平坡驻。\n带湖鸥鹭。\n犹不忍寒盟，时寻门外，一片芰荷浦。\n秋水观，环绕滔滔瀑布。\n参天林木奇古。\n云烟只在阑干角，生出晚来微雨。\n东道主。\n爱宾客、梅花烂漫开樽俎。\n满怀尘土。\n扫荡已无馀，□□时上，玉峤翠瀛语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16252, '念奴娇', '章谦亨', '画楼侧畔，试与君、管领南枝风物。\n影浸西湖清浅水，旁倚云崖烟壁。\n艾纳全披，檀心俱露，一片前村雪。\n碧松修竹，岁寒真是三杰。\n长向酒欲冰时，魁英相放，不待阳和发。\n一任无情风又雨，毕竟清香难灭。\n幻玉精神，添酥标致，羞上萧萧发。\n脆圆可爱，更看春二三月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16253, '浪淘沙', '章谦亨', '台上凭阑干。\n犹怯春寒。\n被谁偷了最高山。\n将谓六丁移取去，不在人间。\n却是晓云闲。\n特地遮拦。\n与天一样白漫漫。\n喜得东风收卷尽，依旧追还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16254, '小重山', '章谦亨', '久雨初晴天气佳。\n远峰犹□被，乱峰遮。\n更无一朵路旁花。\n春归也，光景只桑麻。\n山径曲如蛇。\n□□□□□，□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16255, '石州引・石州慢', '章谦亨', '半角庭阴，弓月映眉，珠露侵。\n花棚倒挂风枝，低鬓唇ぢ叶。\n凭肩笑问，甚日罢织流黄，泥人无语吟虫答。\n灯近悄分携，溜钗钿犀合。\n一霎。\n莲丝易折。\n未稳栖鸳，陡惊弹鸭。\n几度空阶，宵永笛声孤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16256, '水调歌头', '章谦亨', '解变西体，一赋冠群英。\n清风峡畔，至今堂以读书名。\n富贵轻於尘土，孝义重於山岳，惜不大其成。\n陵谷纵迁改，草木亦光荣。\n与仇香，穿阮屐，试同登。\n石龛虽窄，可容一几短檠灯。\n千仞苍崖如削，四面翠屏不断，云雾镇长生。\n最爱岩前水，犹作诵弦声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16257, '画堂春', '章谦亨', '连朝檐溜几曾乾。\n韶华一似衰颜。\n牡丹开尽木香残。\n忆家山，愁倚危阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16258, '阮郎归', '王同祖', '一帘疏雨细於尘。\n春寒愁杀人。\n桐花庭院近清明。\n新烟浮旧城。\n寻蝶梦，怯莺声。\n柳丝如妾情。\n丙丁帖子画教成。\n妆台求晚晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16259, '摸鱼儿', '王同祖', '记年时、荔枝香里，深红一片成阵。\n迎风浴露精神爽，谁似阿娇丰韵。\n黄昏近。\n望翠幕玳席，粉面云鬟映。\n娇波微瞬。\n向烛影交相，歌声闲绕，私语画阑并。\n佳期事，好处天还悭吝。\n莺啼燕语无定。\n一轮明月人千里，空梦云温雨润。\n萧郎病。\n恨天阔鸿稀，杳杳沈芳讯。\n日长人静。\n但时把好山，学他媚妩，偷就眉峰印。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16260, '西江月', '王同祖', '往事星移物换，旧游雨冷云沈。\n真娘墓草几回青。\n问著寒潮不应。\n何处芙蓉别馆，依前杨柳离亭。\n东风吹泪入重扃。\n为唤香魂教醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16261, '踏莎行', '杨伯', '梅观初花，蕙庭残叶。\n当时惯听山阴雪。\n东风吹梦到清都，今年雪比年前别。\n重酿宫醪，双钩官帖。\n伴翁一笑成三绝。\n夜深何用对青藜，窗前一片蓬莱月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16262, '木兰花慢', '李彭老', '正千门系柳，赐宫烛、散青烟。\n看秀靥芳唇，涂妆晕色，试尽春妍。\n田田。\n满阶榆荚，弄轻阴、浅冷似秋天。\n随处饧香杏暖，燕飞斜秋千。\n朱弦。\n几换华年。\n扶浅醉、落花前。\n记旧时游冶，灯楼倚扇，水院移船。\n吟边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16263, '壶中天・念奴娇', '李彭老', '素飙荡碧，喜云飞寥廓，清透凉宇。\n倦鹊惊翻台榭迥，叶叶秋声归树。\n珠斗斜河，冰轮辗雾，万里青冥路。\n香深屏翠，桂边满袖风露。\n烟外冷逼玻璃，渔郎歌渺，击空明归去。\n怨鹤知更莲漏悄，竹里筛金帘户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16264, '高阳台', '李彭老', '飘粉杯宽，盛香袖小，青青半掩苔痕。\n竹里遮寒，谁念灭尽芳云。\n么凤叫晚吹晴雪，料水空、烟冷西泠。\n感雕零。\n残缕遗钿，迤逦成尘。\n东园曾趁花前约，记按筝筹酒，戏挽飞琼。\n环佩无声，草暗台榭春深。\n欲倩怨笛传清谱，怕断霞、难返吟魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16265, '法曲献仙音', '李彭老', '云木槎桠，水荭摇落，瘦影半临清浅。\n翠羽迷空，粉容羞晓，年华柱弦频换。\n甚何逊、风流在，相逢共寒晚。\n总依黯。\n念当时、看花游冶，曾锦缆移舟，宝筝随辇。\n池苑锁荒凉，嗟事逐、鸿飞天远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16266, '一萼红', '李彭老', '过蔷薇。\n正风暄云淡，春去未多时。\n古岸停桡，单衣试酒，满眼芳草斜晖。\n故人老、经年赋别，灯晕里、相对夜何其。\n泛剡清愁，买花芳事，一卷新诗。\n流水孤帆渐远，想家山猿鹤，喜见重归。\n北阜寻幽，青津问钓，多情杨柳依依。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16267, '高阳台', '李彭老', '石笋埋云，风篁啸晚，翠微高处幽居。\n缥简云签，人间一点尘无。\n绿深门户啼鹃外，看堆床、宝晋图书。\n尽萧闲，浴砚临池，滴露研朱。\n旧时曾写桃花扇，弄霏香秀笔，春满西湖。\n松菊依然，柴桑自爱吾庐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16268, '探芳讯', '李彭老', '对芳昼。\n甚怕冷添衣，伤春疏酒。\n正绯桃如火，相看自依旧。\n闲帘深掩梨花雨，谁问东阳瘦。\n几多时，涨绿莺枝，坠红鸳。\n堤上宝鞍骤。\n记草色薰晴，波光摇岫。\n苏小门前，题字尚存否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16269, '祝英台近', '李彭老', '杏花吹，梅花过，时节又春半。\n帘影飞梭，轻阴小庭院。\n旧时月底秋千，吟香醉玉，曾细听、歌珠一串。\n忍重见。\n描金小字题情，生绡合欢扇。\n老了刘郎，天远玉箫伴。\n几番莺外斜阳，阑干倚遍，恨杨柳、遮愁不断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16270, '踏莎行', '李彭老', '紫曲迷香，绿窗梦月。\n芳心如对春风说。\n蛮笺象管写新声，几番曾试琼壶觖。\n庾信书愁，江淹赋别。\n桃花红雨梨花雪。\n周郎先自足风流，何须更拟秦箫咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16271, '浪淘沙', '李彭老', '泼火雨初晴。\n草色青青。\n傍檐垂柳卖春饧。\n画舫载花花解语，绾燕吟莺。\n箫鼓入西泠。\n一片轻阴。\n钿车罗盖竞归城。\n别有水窗人唤酒，弦月初生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16272, '四字令・醉太平', '李彭老', '兰汤晚凉。\n鸾钗半妆。\n红巾腻雪初香。\n擘莲房赌双。\n罗纨素。\n冰壶露床。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16273, '生查子', '李彭老', '罗襦隐绣茸，玉合消红豆。\n深院落梅钿，寒峭收灯後。\n心事卜金钱，月上鹅黄柳。\n拜了夜香休，翠被听春漏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16274, '壶中天・念奴娇', '李彭老', '水西云北，记前回同载，高阳伴侣。\n一色荷花香十里，偷把秋期频数。\n脆管排云，轻桡喷雪，不信催诗雨。\n碧筒呼酒，秀笺题遍新句。\n谁念病损文园，岁华摇落，事与孤鸿去。\n露井邀凉吹短发，梦入苹洲菱浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16275, '木兰花慢', '李彭老', '折秦淮露柳，带明月、倚归船。\n看佩玉纫兰，囊诗贮锦，江满吴天。\n吟边。\n唤回梦蝶，想故山、薇长已多年。\n草得梅花赋了，棹歌远和离舷。\n风弦。\n尽入吟篇。\n伤倦客、对秋莲。\n过旧经行处，渔乡水驿，一路闻蝉。\n留连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16276, '祝英台近', '李彭老', '载轻寒、低鸣橹。\n十里杏花雨。\n露草迷烟，萦绿过前浦。\n青青陌上垂杨，绾丝摇佩，渐遮断、旧曾吟处。\n听莺语。\n吹笙人远天长，谁翻水西谱。\n浅黛凝愁，远岫带眉妩。\n画阑闲倚多时，不成春醉，趁几点、白鸥归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16277, '清平乐', '李彭老', '合欢扇子。\n扑蝶花阴里。\n半醉海棠扶不起。\n淡日秋千闲倚。\n宝筝弹向谁听。\n一春能几番晴。\n帐底柳绵吹满，不教好梦分明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16278, '章台月・一斛珠', '李彭老', '露轻风细。\n中庭夜色凉如水。\n荷香柳影成秋意。\n萤冷无光，凉入树声碎。\n玉箫金缕西楼醉。\n长吟短舞花阴地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16279, '青玉案', '李彭老', '楚峰十二阳台路。\n算只有、飞红去。\n玉合香囊曾暗度。\n榴裙翻酒，杏帘吹粉，不识愁来处。\n燕忙莺懒青春暮。\n蕙带空留断肠句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16280, '浣溪沙', '李彭老', '玉雪庭心夜色空。\n移花小槛斗春红。\n轻衫短帽醉歌重。\n彩扇旧题烟雨外，玉箫新谱燕莺中。\n阑干到处是春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16281, '天香', '李彭老', '捣麝成尘，薰薇注露，风酣百和花气。\n品重云头，叶翻蕉样，共说内家新制。\n波浮海沫，谁唤觉、鲛人春睡。\n清润俱饶片脑，芬半是沈水。\n相逢酒边花外。\n火初温、翠炉烟细。\n不似宝珠金缕，领巾红坠。\n荀令如今憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16282, '摸鱼子', '李彭老', '过垂虹、四桥飞雨，沙痕初涨春水。\n腥波十里吴远，绿蔓半萦船尾。\n连复碎。\n爱滑卷青绡，香袅冰丝细。\n山人隽味。\n笑杜老无情，香羹碧涧，空只赋芹美。\n归期早，谁似季鹰高致。\n鲈鱼相伴菰米。\n红尘如海丘园梦，一叶又秋风起。\n湘湖外。\n看采撷、芳条际晓随鱼市。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16283, '失调名', '李彭老', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16284, '惜红衣', '李莱老', '笛送西泠，帆过杜曲。\n昼阴芳绿。\n门巷清风，还寻故人屋。\n苍华发冷，笑瘦影、相看如竹。\n幽谷。\n烟树晚莺，诉经年愁独。\n残阳古木。\n书画归船，匆匆又南北。\n苹洲鸥鹭素熟。\n旧盟续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16285, '青玉案', '李莱老', '吟情老尽江南句。\n几千万、垂丝缕。\n花冷絮飞寒食路。\n渔烟鸥雨，燕昏莺晓，总入昭华谱。\n红衣妆靓凉生渚。\n环碧斜阳旧时树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16286, '扬州慢', '李莱老', '玉倚风轻，粉凝冰薄，土花祠冷无人。\n听吹箫月底，传暮草金城。\n笑红紫、纷纷成雨，溯空如蝶，恐堕珠尘。\n叹而今、杜郎还见，应赋悲春。\n佩环何许，纵无情、莺燕犹惊。\n怅朱槛香消，绿屏梦渺，肠断瑶琼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16287, '谒金门', '李莱老', '春意态。\n闲却远山横黛。\n香径莓苔嗟粉坏。\n凤靴双斗彩。\n折得花枝懒戴。\n犹恋鸳鸯飞盖。\n旧恨新愁都只在。\n东风吹柳带。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16288, '浪淘沙', '李莱老', '榆火换新烟。\n翠柳朱檐。\n东风吹得落花颠。\n帘影翠梭悬绣带，人倚秋千。\n犹忆十年前。\n西子湖边。\n斜阳吹入画楼船。\n归醉夜堂歌舞月，拼却春眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16289, '生查子', '李莱老', '妾情歌柳枝，郎意怜桃叶。\n罗带绾同心，谁信愁千结。\n楼上数残更，马上看新月。\n绣被怨春寒，怕学鸳鸯叠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16290, '高阳台', '李莱老', '门掩香残，屏摇梦冷，珠细糁缀芳尘。\n临水搴花，流来疑是行云。\n藓梢空挂凄凉月，想鹤归、犹怨黄昏。\n黯消凝。\n人老天涯，雁影沈沈。\n断肠不在听横笛，在江皋解佩，翳玉飞琼。\n烟湿荒村，背春无限愁深。\n迎风点点飘寒粉，怅秋娘、燕袖啼痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16291, '木兰花慢', '李莱老', '向烟霞堆里，著吟屋、最高层。\n望海日翻红，林霏散白，猿鸟幽深。\n双岑。\n倚天翠湿，看浮云、收尽雨还晴。\n晓色千松逗冷，照人眼底长青。\n闲情。\n玉尘风生。\n摹茧字，校鹅经。\n爱静翻缃帙，芸台几，荷制兰缨。\n分明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16292, '清平乐', '李莱老', '绿窗初晓。\n枕上闻啼鸟。\n不恨王孙归不早。\n只恨天涯芳草。\n锦书红泪千行。\n一春无限思量。\n折得垂杨寄与，丝丝都是愁肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16293, '台城路・齐天乐', '李莱老', '半空河影流云碎，亭皋嫩凉收雨。\n井叶还惊，江莲乱落，弦月初生商素。\n堂深几许。\n渐爽入云帱，翠绡千缕。\n纨扇恩疏，晚萤光冷照窗户。\n文园憔悴顿老，又西风暗换，丝鬓无数。\n灯外残砧，琴边瘦枕，一一情伤迟暮。\n故人倦旅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16294, '浪淘沙', '李莱老', '宝押绣帘斜。\n莺燕谁家。\n银筝初试合琵琶。\n柳色春罗裁袖小，双戴桃花。\n芳草满天涯。\n流水韶华。\n晚风杨柳绿交加。\n闲倚阑干无藉在，数尽归鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16295, '杏花天', '李莱老', '年时中酒风流病。\n正雨暗、蘼芜深径。\n人家寒食烟初禁。\n狼藉梨花雪影。\n西湖梦、红沈翠冷。\n记舞板、歌裙厮趁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16296, '小重山', '李莱老', '画檐簪柳碧如城。\n一帘风雨里，近清明。\n吹箫门巷冷无声。\n梨花月，今夜负中庭。\n远岫敛修颦。\n春愁吟入谱，付莺莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16297, '倦寻芳', '李莱老', '缭墙黏藓，糁径飞梅，春绪无赖。\n绣压垂帘，骨有许多寒在。\n宝幄香消龙麝饼，钿车尘冷鸳鸯带。\n想西园，被一程风雨，群芳都碍。\n逗晓色、莺啼人起，倦倚银屏，愁沁眉黛。\n待拼千金，却恨好榷难买。\n翠苑欢游孤解佩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16298, '点绛唇', '李莱老', '绿染春波，袖罗金缕双。\n小桃匀碧。\n香衬蝉云湿。\n舞带歌钿，闲傍秋千立。\n情何极。\n燕莺尘迹。\n芳草斜阳笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16299, '西江月', '李莱老', '绿染晓云冉冉，红酣晴雾冥冥。\n银簪悬烛锦官城。\n困倚墙头半影。\n雨後遍饶艳冶，燕来同作清明。\n更深犹唤玉靴笙。\n不管西池露冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16300, '清平乐', '李莱老', '日寒风细。\n庭馆浮花气。\n白发潘郎吟欲醉。\n绿暗シ芜千里。\n西园南浦东城。\n一春多少闲情。\n日暮采苹歌远，梦回唤得愁生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16301, '念奴娇', '黄应武', '乾坤开辟，桂林有、元气自来融结。\n石磴盘空行木杪，天柱屹然中立。\n窟宅幽深，泉源清远，不是灵神擘。\n潜通後洞，张刘万古遗迹。\n输我长剑凌虚，六尘尽扫，银海秋波碧。\n志气飘飘游物外，惟有清风知得。\n唤起白龙，护持飙驭，稽首朝金阙。\n山灵欣喜，紫云已在诗壁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16302, '满庭芳', '如愚居士', '吾乃当涂，弃儒奉道，遵行圣诲多年。\n已逾三纪，截灭六尘缘。\n因习业、自营度日，未尝谒见豪贤。\n般若力，掀翻烦恼，坦荡独け然。\n来斯，十四载，装銮佛像，塔宇尽光鲜。\n造遮石道，直至水边。\n都系束修己镪，舍为助道安禅。\n知惭愧，了无所得，本觉性明圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16303, '满江红', '林革', '十载扁舟，几来往、三吾溪上。\n天宝事，一回看著，一回惆怅。\n笔画模糊犹雅健，文章褒贬添悲壮。\n枉教人、字字费沈吟，评轻重。\n西北望，情无量。\n东南气，真长王。\n想忠臣应读，宋中兴颂。\n主圣自然皆乐土，时平正合储良将。\n笑此身、老大尚奔驰，知何用。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16304, '水调歌头', '曾宏正', '风月无尽藏，泉石有膏肓。\n古今桂岭奇胜，骚客费平章。\n不假鬼谋神运，自是地藏天作，圆魂镇相望。\n举首吸空翠，赤脚踏沧浪。\n惊龙卧，攀栖鹘，翳鸾凰。\n秋爽一天凉露，桂子更飘香。\n坐我水精宫阙，呼彼神仙伴侣，大杓挹琼浆。\n主醉客起舞，今夕是何乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16305, '沁园春', '吴景伯', '再上高台，访谪仙兮，仙何所之。\n但石城西踞，潮平白鹭，浮图南峙，云淡乌衣。\n凤鸟不来，长安何处，惟有碧梧三数枝。\n兴亡事，对江山休说，谁是谁非。\n庭花飘尽胭脂。\n算结绮、繁华能几时。\n问何人重向，新亭挥泪，何人更到，别墅围棋。\n笑拍阑干，功名未了，宁肯绿蓑寻钓矶。\n深深饮，任玉山醉倒，明月扶归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16306, '点绛唇', '邓有功', '卷上珠帘，晚来一阵东风恶。\n客怀萧索。\n看尽残花落。\n自把银瓶，买酒成孤酌。\n伤漂泊。\n知音难托。\n闷倚阑干角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16307, '过秦楼', '邓有功', '燕蹴飞红，莺迁新绿，几阵晚来风急。\n谢家池馆，金谷园林，还又把春虚掷。\n年时恨雨愁云，物换星移，有谁曾忆。\n把一尊试酹，落花芳草，总成尘迹。\n频自笑、流浪孤萍，沾泥弱絮，有底困春无力。\n银屏香暖，宝簟波寒，又负月明今夕。\n往事梦里，沈思惟有罗襟，泪痕犹湿。\n奈垂杨万缕，不系西风白日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16308, '浪淘沙', '李振祖', '春在画桥西。\n画舫轻移。\n粉香何处度涟漪。\n认得一船杨柳外，帘影垂垂。\n谁倚碧阑低。\n酒晕双眉。\n鸳鸯并浴燕交飞。\n一片闲情春水隔，斜日人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16309, '二郎神', '汤恢', '琐窗睡起，闲伫立、海棠花影。\n记翠楫银塘，红牙金缕，杯泛梨花冷。\n燕子衔来相思字，道玉瘦、不禁春病。\n应蝶粉半销，鸦云斜坠，暗尘侵镜。\n还省。\n香痕碧唾，春衫都凝。\n悄一似荼シ，玉肌翠帔，消得东风唤醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16310, '倦寻芳', '汤恢', '饧箫吹暖，蜡烛分烟，春思无限。\n风到楝花，二十四番吹遍。\n烟湿浓堆杨柳色，昼长闲坠梨花片。\n悄帘栊，听幽禽对语，分明如翦。\n记旧日、西湖行乐，载酒寻春，十里尘软。\n背後腰肢，彷佛画图曾见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16311, '满江红', '汤恢', '小院无人，正梅粉、一阶狼藉。\n疏雨过，溶溶天气，早如寒食。\n啼鸟惊回芳草梦，峭风吹浅桃花色。\n漫玉炉、沈水熨春衫，花痕碧。\n绿水，红香陌。\n紫桂棹，黄金勒。\n怅前欢如梦，後游何日。\n酒醒香消人自瘦，天空海阔春无极。\n又一林、新月照黄昏，梨花白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16312, '祝英台近', '汤恢', '宿酲苏，春梦醒，沈水冷金鸭。\n落尽桃花，无人扫红雪。\n渐催煮酒园林，单衣庭院，春又到、断肠时节。\n恨离别。\n长忆人立荼シ，珠帘卷香月。\n几度黄昏，琼枝为谁折。\n都将千里芳心，十年幽梦，分付与、一声啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16313, '祝英台近', '汤恢', '月如冰，天似水，冷浸画阑湿。\n桂树风前，香半狼藉。\n此翁对此良宵，别无可恨，恨只恨、古人头白。\n洞庭窄。\n谁道临水楼台，清光最先得。\n万里乾坤，原无片云隔。\n不妨彩笔云笺，翠尊冰酝，自管领、一庭秋色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16314, '八声甘州', '汤恢', '摘青梅荐酒，甚残寒、犹怯苎萝衣。\n正柳腴花瘦，绿云冉冉，红雪霏霏。\n隔屋秦筝依约，谁品春词。\n回首繁华梦，流水斜晖。\n寄隐孤山山下，但一瓢饮水，深掩苔扉。\n羡青山有思，白鹤忘机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16315, '失调名', '汤恢', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16316, '二郎神', '汤恢', '碧崖倒影，浸一片、寒江如练。\n正岸岸柳花，村村修竹，唤醒春风笔砚。\n溯水舟轻轻如叶，只消得、溪风一箭。\n看水部雄文，太师健笔，月寒波卷。\n游倦。\n片云孤鹤，江湖都遍。\n慨金屋藏妖，绣屏包祸，欲与三郎痛辩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16317, '八声甘州', '汤恢', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16318, '摸鱼儿', '李演', '又西风、四桥疏柳，惊蝉相对秋语。\n琼荷万笠花云重，袅袅红衣如舞。\n鸿北去。\n渺岸芷汀芳，几点斜阳字。\n吴亭旧树。\n又系我扁舟，渔乡钓里，秋色淡归鹭。\n长干路。\n草莽疏烟断墅。\n商歌如写羁旅。\n丹溪翠岫登临事，苔屐尚黏苍土。\n鸥且住。\n怕月冷吟魂，婉冉空江暮。\n明灯暗浦。\n更短笛衔风，长云弄晚，天际画秋句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16319, '声声慢', '李演', '轻鞯绣谷。\n柔屐烟堤，六年遗赏新续。\n小舫重来，惟有寒沙鸥熟。\n徘徊旧情易冷，但溶溶、翠波如。\n愁望远，甚云销月老，暮山自绿。\n笑人生悲乐，且听我尊前，渔歌樵曲。\n旧阁尘封，长得树阴如屋。\n凄凉五桥归路，载寒秀、一枝疏玉。\n翠袖薄，晚无言、空倚修竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16320, '醉桃源・阮郎归', '李演', '双鸳初放步云轻。\n香帘蒸未晴。\n杏熔暗泪结红冰。\n留春蝴蝶情。\n寒薄薄，日阴阴。\n锦鸠花底鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16321, '南乡子', '李演', '芳水戏桃英。\n小滴燕支浸绿云。\n待觅琼觚藏彩信，流春。\n不似题红易得沈。\n天上许飞琼。\n吹下蓉笙染玉尘。\n可惜素鸾留不得，更深。\n误剪灯花断了心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16322, '八六子', '李演', '乍鸥边、一番腴绿，流红又怨苹花。\n看晚吹、约晴归路，夕阳分落渔家。\n轻云半遮。\n萦情芳草无涯。\n还报舞香一曲，玉瓢几许春华。\n正细柳青烟，旧时芳陌，小桃朱户，去年人面，谁知此日重来系马，东风淡墨鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16323, '祝英台近', '李演', '采芳苹，萦去舻。\n归步翠微雨。\n柳色如波，萦恨满烟浦。\n东君若是多情，未应花老，心已在、绿成阴处。\n困无语。\n柔被褰损梨云，间修牡丹谱。\n妒粉争香，双燕为谁舞。\n年年红紫如尘，五桥流水，知送了、几番愁去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16324, '贺新凉・贺新郎', '李演', '笛叫东风起。\n弄尊前、杨花小扇，燕毛初紫。\n万点淮峰孤角外，惊下斜阳似绮。\n又婉娩、一番春意。\n歌舞相缪愁自猛，卷长波、一洗空人世。\n闲热我，醉时耳。\n绿芜冷叶瓜州市。\n最怜予、洞箫声尽，阑干独倚。\n落落东南墙一角，谁护山河万里。\n问人在、玉关归未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16325, '水调歌头', '卫宗武', '风雨卷春去，绿紫总无馀。\n窈窕一川芳渚，软草接新蒲。\n杨柳垂垂飘絮，桑柘阴阴成幄，殷绿正敷。\n迁木莺呼友，营垒燕将雏。\n金蕉举，珠樱累，豆梅腴。\n寿乡歌舞，樽前暂得皱眉舒。\n往事南柯印绶，晚岁北山杖屦，寂寞笑今吾。\n幸作耆年侣，写入洛英图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16326, '摸鱼儿', '卫宗武', '小林峦、一年芳事，乱红还又飞雨。\n生香冉冉花阴转，云擘满空晴絮。\n游宴处。\n看乐意相关，庭下胎仙舞。\n歌声缓度。\n任圆玉敲寒，飞觞传晓，未许放春去。\n闲中趣。\n明月清风当户。\n莘莘容屋陈俎。\n翦裁妙语频赓唱，巧胜郢斤般斧。\n心自许。\n拼凋景颓龄，为莺俦燕侣。\n同盟会取。\n共花下小车，竹间三径，长作老宾主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16327, '摸鱼儿', '卫宗武', '见春来、又将春尽，狂风那更痴雨。\n一番芳径催人老，回首绿杨飘絮。\n欢会处。\n有小小池亭，止欠妙歌舞。\n光阴梭度。\n对草木幽姿，候禽雅奏，客至未应去。\n十年里，冷落翟公庭户。\n朋来草草樽俎。\n投闲赢得浮生乐，肯羡油幢绣斧。\n春几许。\n任洛谱名葩，留宴耆英侣。\n浮荣竞取。\n纵带玉围腰，印金系肘，争似莺花主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16328, '木兰花慢', '卫宗武', '聚林园芳景，尽输韩圃陶篱。\n任雨虐风饕，露凝霜压，丛木离披。\n正色幽香不减，与冬兰、并秀结心知。\n天赋花中名节，不教桃李同时。\n清奇。\n秋後尤宜。\n浮卉尽、尚芬菲。\n称处士庭除，先生简册，声续吾伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16329, '酹江月・念奴娇', '卫宗武', '露华凝聚，夜更长、寒压一床衾重。\n局缩龟藏灯幌悄，明灭银欲冻。\n鼻观流珠，肌纹浮粟，枕难成梦。\n明蟾交映，一窗清影梅弄。\n晓见黄陨丹空，但琼华点缀，万梢森耸。\n橘柚香来分好景，书後尽堪题送。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16330, '酹江月・念奴娇', '卫宗武', '暮云凝冻，耸玉楼、拈断冰髯知几。\n今岁天公悭破白，未放六呈瑞。\n瘗马发祥，妖麋应祷，终解从人意。\n腊前三白，瑶光一瞬千里。\n便好翦刻漫空，落花飞絮，滚滚随风起。\n莫待东皇催整驾，点点消成春水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16331, '满江红', '卫宗武', '屑玉飞，正堪称、冯夷展布。\n空几度、痴云凝聚，狂风掀舞。\n点点抛扬珠作霰，纤纤断续丝垂雨。\n借银河、翦刻六花飘，天应许。\n水漠漠，斜桥渡。\n烟淡淡，长亭路。\n望寒莎衰草，总成愁绪。\n坡老新堤须好在，逋仙孤屿犹堪去。\n共寻梅、止欠雪双清，烦青女。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16332, '满江红', '卫宗武', '弧矢开祥，喜从此、旬兼九日。\n新岁改、椒盘献颂，齐头七十。\n渐入唐人诸老画，可追洛社耆英集。\n有陶潜、三径健吟哦，贫而适。\n摘仙桂，探蟾窟。\n敛洪藻，归麟笔。\n总古先传记，讥评得失。\n不朽芬芳垂简册，浮荣土苴轻簪笏。\n看年如、卫武粲成章，诗传抑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16333, '天仙子', '卫宗武', '搭宅亭园虽不大。\n花木成阴难论价。\n豪端点缀有珠玑，竹一带。\n梅一派。\n明月清风何用买。\n子子孙孙纡寿彩。\n家庆成图和蔼蔼。\n更添三岁古来稀，酒满。\n诗满架。\n直到耆颐年未艾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16334, '水龙吟', '卫宗武', '桑蓬扫尽闲愁，未应人比梅花瘦。\n眉峰顿展，恰如云卷，北山□九。\n萦锦绣肠，袖丝纶手，希有。\n□□□博取，巍科□□，儒冠於我何负。\n初度年来年去，喜称觞、腊前还又。\n安时委命，金鱼玉带，傥来斯受。\n傍屋园林，抚松对竹，共朋三寿。\n且逍遥、安乐窝中，岁岁进、长生酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16335, '金缕曲・贺新郎', '卫宗武', '强半秋澄穆。\n半月弦、南极躔高，寿星明煜。\n今岁户庭殊旧岁，洗尽闲愁千斛。\n沸春夏、欢声相续。\n兰已种成香满砌，更华、得偶颜如玉。\n双捧劝，寿齐祝。\n郗枝芳映庄椿绿。\n觉这番、初度称觞，桂增芬馥。\n生子生孙从此始，剩有人传祖笏。\n看八座、青毡须复。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16336, '沁园春', '李敬则', '南渡盛时，壬寅之秋，生此伟人。\n是皇家柱石，端平君子，吾儒宗主，意一先生。\n自起丹山，晋登紫府，天下欣然望太平。\n至夷狄，亦慕吾中国，司马声名。\n愿君为尧舜之君。\n举一世民皆尧舜民。\n羡当年三渐，直声已著，近来四蜀，先虑尤深。\n事验平凉，眷隆当宁，指日须还公秉钧。\n愿公寿，以寿吾国脉，以寿斯文。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16337, '玉楼春', '吴益', '玉楼春信梅传早。\n三八芳辰阳复後。\n称觞喜对一椿高，莱庭双桂森兰茂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16338, '绿头鸭・多丽', '利登', '晚春天。\n柳丝初透晴烟。\n黯离怀、绿房深处，艳游曾记当年。\n衬龙绡、亭亭玉树，步鸯褥、窄窄金莲。\n烧蜜调蜂，翦花挑蝶，香云微湿绿弯鬟。\n嬉游困，倚郎私语，还爱抚郎肩。\n共携手，海棠院左，翡翠帘边。\n恨无情、锦笼鹦鹉，等闲轻语花前。\n昔相怜、关山咫尺，今相望、咫尺关山。\n是妾心阑，是郎意懒，是郎无分妾无缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16339, '菩萨蛮', '利登', '玉阑干外重帘晚。\n流云欲度长天远。\n花草不知名。\n春来各自春。\n绿鞍游冶客。\n何处垂杨陌。\n不信不归来。\n海棠花又开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16340, '玉楼春', '利登', '夹帘不卷重堂暮。\n白骑少年何处去。\n云根稚藕已胜花，烟外子松今作树。\n金Ι月涩知无与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16341, '水调歌头', '利登', '日月换飞涧，风雨老孤松。\n千岩万壑秋重，白气接长空。\n一笑掀髯徐起，苍佩腰间相照，犹自涌晴虹。\n桑海几番覆，人尚醉春风。\n横白石，结绿绮，送飞鸿。\n十年梦事消歇，长剑吼青龙。\n却笑人间多事，一壳蜗涎光景，颠倒死英雄。\n云日空里，玉鹤任西东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16342, '洞仙歌', '利登', '弄香吹粉，记前回酒困。\n绿露沈沈转花影。\n翠帘深，隐隐红雾依人，荷月静，新样双鸾交映。\n如今谁念省。\n短雨长云，曾托琵琶再三问。\n最苦绿屏孤，夜久星寒，无处顿、风流心性。\n又莫是偷香寄韩郎，到漏泄春风，一枝花信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16343, '过秦楼', '利登', '眉黛山分，靥朱星合，郁郁夜堂初见。\n芙蓉寄隐，豆蔻传香，便许翠鬟偷剪。\n迎夜易羞，欲晨先怯，风流楚楚未惯。\n正流苏帐掩，绿玉屏深，红香自暖。\n谁信道、媚月难留，惊云易散，从此三桥路远。\n巢燕春归，剪花词在，难寄红题一片。\n料想伊家，如今羞傍琴窗，慵题花院。\n但碧桃影下，应对流红自叹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16344, '齐天乐', '利登', '淡云荒草秋汀暮，归心又寒烟水。\n论槛移花，量船载酒，寂寞当年情味。\n孤蓬夜闭。\n听四壁松声，欲高还细。\n似近如遥，露鸿声乱楚天外。\n蓝桥人断岁久，旧家曾共赏，九华花事。\n艳雪初融，生香自暖，消得金莲贴地。\n相思破睡。\n谩一点琴心，暗关千里。\n愁怯潮生，晓帆风又起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16345, '鹧鸪天', '利登', '凤尾鬟香再叠梳。\n藕丝衫嫩蹙双鱼。\n闲收末利熏藤枕，自插芙蓉绕翠。\n新浴後，浅妆初。\n卫夫人帖学行书。\n西窗一霎黄昏雨，笑问新凉饮酒无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16346, '风流子', '利登', '梨园花柳地，扶残醉、曾记问妖娆。\n叹惹住轻烟，柔丝未改，霏零疏雨，腻粉先飘。\n更低道，花无三日艳，柳有一年娇。\n卷翠未迟，醉红易失，共偎香影，同赏良宵。\n如今知何处，三山远，云水一望迢迢。\n傍砌青鸾好在，谁送归飚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16347, '风入松', '利登', '断芜幽树际烟平。\n山外又山青。\n天南海北知何极，年年是、匹马孤征。\n看尽好花成子，暗惊新笋抽林。\n岁华情事苦相寻。\n弱雪鬓毛侵。\n十千斗酒悠悠醉，斜河界、白日云心。\n孤鹤尽边天阔，清猿咽处山深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16348, '水调歌头', '利登', '相聚不知好，相别始知愁。\n笋舆伊轧，穿尽斜照古平州。\n今夜荒风脱木，明夜山长水远，後夜已他州。\n转觉家山远，何计去来休。\n酒堪沽，花可买，月能留。\n相思酒醒，花落五更头。\n长记疏梅影底，一笛紫云飞动，相对大江流。\n此别无一月，一月一千秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16349, '失调名', '利登', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16350, '虞美人', '利登', '当时养士知何许。\n总把降幡去。\n汉家王气塞乾坤。\n一树盈盈、不为汉家春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16351, '沁园春', '吴势卿', '碧瓦霜融，绣阁寒经，春浮寿杯。\n羡华年七帙，人生稀有，新阳七日，天意安排。\n丹凤门开，黄麾仗立，此际应须召促回。\n人道是，却暂时绣斧，索笑盐梅。\n江假守非才，犹记得当时传庾台。\n算良机再会，抠衣来久，归鞭何速，祝寿方才。\n应与邦人，传为佳话，只为先生诞日来。\n明年看，是侬方九曲，公已三台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16352, '满江红', '刘浩', '岳渎储精，冰壶里、精神可掬。\n三万卷、龙蛇落纸，琅撑腹。\n便合弹冠登要路。\n如何袖手缄空谷。\n又谁知、天独授先生，长生。\n鹤易怨，龟多缩。\n竹太瘦，梅偏独。\n算人间何物，可传心曲。\n但愿君如天上月，年年此夜团如玉。\n更有人、千里共蝉娟，偷香祝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16353, '沁园春', '赵希汰', '持节浙东，六十年前，紫阳老师。\n看粟移七郡，功深到处，棠阴一道，民尚思之。\n心印亲传，雨岩来括，寅岁幸无庚子饥。\n仁同视，更备存先具，仓积千斯。\n青州阴德天知。\n只此事堪为崧岳祈。\n与太夫人寿，相看华发，转中书令，长著斑衣。\n岁岁梅花，樽前索笑，霜月先圆两夜规。\n称觞了，报春风千里，班觐龙墀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16354, '西江月', '徐俨夫', '曲折迷春院宇，参差近水楼台。\n吹箫人去燕归来。\n空有落梅香在。\n花底三更过雨，酒阑一枕惊雷。\n明朝飞梦隔天涯。\n肠断流莺声碎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16355, '宝鼎现', '陈合', '神鳌谁断，几千年再，乾坤初造。\n算当日、枰棋如许，争一著、吾其衽左。\n谈笑顷、又十年生聚，处处豳风葵枣。\n江如镜，楚氛馀几，猛听甘泉捷报。\n天衣细意从头补。\n烂山龙、华虫黼藻。\n宫漏永、千门鱼钥，截断红尘飞不到。\n街九轨，看千貂避路，庭院五侯深锁。\n好一部、太平六典，一一周公手做。\n赤绣裳，消得道、斑斓衣好。\n尽庞眉鹤发，天上千秋难老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16356, '木兰花慢', '李芸子', '占西风早处，一番雨，一番秋。\n记故国斜阳，去年今日，落叶林幽。\n悲歌几回激烈，寄疏狂、酒令与诗筹。\n遗恨清商易改，多情紫燕难留。\n嗟休。\n触绪茧丝抽。\n旧事续何由。\n奈予怀渺渺，羁愁郁郁，归梦悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16357, '洞仙歌', '张韫', '花泥絮浪，春怀如酒。\n书卷炉熏梦清昼。\n唤玉京稳携手松乔，飞光里，笑傲白云林岫。\n仙人犹狡狯，洒雪吹冰，声落星河翠蛟走。\n问箬下留丹，别已千年，华表鹤、亦归来否。\n有洞口、桃花识刘郎，共一笑相迎，朱颜如旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16358, '念奴娇', '游子西', '暑尘收尽，快晚来急雨，一番初过。\n是处凉飙回爽气，直把残云吹破。\n星律飞流，银河摇荡，只恐冰轮堕。\n云梯稳上，琼楼今夜无锁。\n便觉浮世卑沈，回翔偃薄，似蚁空旋磨。\n想得九天高绝处，不比人间更火。\n独立乾坤，浩歌春雪，可惜无人和。\n广寒宫里，有谁潇洒如我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16359, '清平乐', '施乘之', '风消云缕。\n一碧无今古。\n欲坏上元天不许。\n晴了晚来些雨。\n莫言冷落山家。\n山翁本厌繁华。\n试问莲灯千炬，何如月上梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16360, '八声甘州', '周济川', '有乾坤、清气入诗脾，随龙散神仙。\n蘸西湖和墨，长空为纸，几度诗圆。\n消得宫妃捧砚，夜烛照金莲。\n试问隔屏坐，谁後谁先。\n长是花香柳色，更风清月白，天入吟笺。\n自霞觞误覆，谪下玉皇边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16361, '点绛唇', '应次蘧', '雪意娇春，腊前妆点春风面。\n粉痕冰片。\n一笑重相见。\n倚竹偎松，谁道罗浮远。\n寒更转。\n楚骚为伴。\n韵绕香篝暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16362, '水龙吟', '李', '腰刀首帕从军，戍楼独倚闲凝眺。\n中原气象，狐居兔穴，暮烟残照。\n投笔书怀，枕戈待旦，陇西年少。\n叹光阴掣电，易生髀肉，不如易腔改调。\n世变沧海成田，奈群生、几番惊扰。\n干戈烂漫，无时休息，凭谁驱扫。\n眼底山河，胸中事业，一声长啸。\n太平时、相将近也，稳稳百年燕赵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16363, '贺新郎', '黄升', '倦整摩天翼。\n笑归来、点画亭台，按行泉石。\n落落元龙湖海气，更著高楼百尺。\n收揽尽、水光山色。\n曾驾飚车蟾宫去，几回批、借月支风敕。\n斯二者，惯相识。\n玲珑窗户青红湿。\n夜深时、寒光爽气，洗清肝膈。\n似此交游真洒落，判与升堂入室。\n有万象、来为宾客。\n不用笙歌轻点，看仙翁手搦虹霓笔。\n吟思远，两峰碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16364, '贺新郎', '黄升', '风送行春步。\n渐行行、山回路转，入云深处。\n问讯花梢春几许，半在诗人杖屦。\n点点是、祥烟膏露。\n中有瑶池千岁种，整严妆、来作巢仙侣。\n相妩媚，试凝伫。\n风流坐上挥谈尘。\n更多情、多才多调，缓歌金缕。\n趁取芳时同宴赏，莫惜清樽缓举。\n有明月、随人归去。\n从此一春须一到，愿东君、长与花为主。\n泉共石，闻斯语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16365, '贺新郎', '黄升', '莫恨黄花瘦。\n正千林、风霜摇落，暮秋时候。\n晚节相看元不恶，采采东篱独秀。\n试揽结、幽香盈手。\n几劫修来方得到，与渊明、千载为知旧。\n同冷淡，比兰友。\n柴桑心事君知否。\n把人间、功名富贵，付之尘垢。\n不肯折腰营口腹，一笑归欤五柳。\n怅此意、而今安有。\n若得风流如此老，也何妨、相对无杯酒。\n诗自可，了重九。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16366, '贺新郎', '黄升', '自扫梅花下。\n问梢头、冷蕊疏疏，几时开也。\n间者阔焉今久矣，多少幽怀欲写。\n有谁是、孤山流亚。\n香月一联真绝唱，与诗人、千载为嘉话。\n馀兴味，付来者。\n清癯不恋华亭榭。\n待与君、白发相亲，竹篱茅舍。\n喜甚今年无酒禁，溜溜小槽压蔗。\n已准拟、雪天霜夜。\n自醉自吟仍自笑，任解冠、落从嘲骂。\n书此意，寄同社。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16367, '木兰花慢', '黄升', '自沈香梦断，风雨外、失馀春。\n怅袍锦淋漓，金銮论奏，四海无人。\n蛾眉古来见妒，奈昭阳、飞燕亦成尘。\n惟有空梁落月，至今能为传神。\n神游八表跨长鲸。\n谁是再来身。\n爱云月溪头，玉环一曲，笔力千钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16368, '木兰花慢', '黄升', '问潘郎两鬓，更禁得、几番秋。\n怅病骨，幽怀渺渺，短发飕飕。\n云边一声长笛，这风情、多属赵家楼。\n枕困寻药裹，薰衣慵讯香篝。\n悠悠。\n老矣复焉求。\n何止赋三休。\n念少日书癖，中年酒病，晚岁诗愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16369, '木兰花慢', '黄升', '问春春不语，谩新绿、满芳洲。\n记历历前游，看花南陌，命酒西楼。\n东风翠红围绕，把功名、一笑付糟丘。\n醉里了忘身世，吟边自负风流。\n风流。\n莫莫复休休。\n白发渐盈头。\n怅十载重来，略无欢意，惟有闲愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16370, '南柯子・南歌子', '黄升', '天上传新火，人间试夹衣。\n定巢新燕觅香泥。\n不为绣帘朱户、说相思。\n侧帽吹飞絮，凭栏送落晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16371, '南柯子・南歌子', '黄升', '兰佩秋风冷，茱囊晓露新。\n多情多感怯芳辰。\n强折黄花来照、碧粼粼。\n落帽参军醉，空樽靖节贫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16372, '行香子', '黄升', '寒意方浓。\n暖信才通。\n是晴阳、暗拆花封。\n冰霜作骨，玉雪为容。\n看体清癯，香淡伫，影朦胧。\n孤城小驿，断角残钟。\n又无边、散与春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16373, '卖花声', '黄升', '莺蝶太匆匆。\n恼杀衰翁。\n牡丹开尽状元红。\n俯仰之间增感慨，花事成空。\n垂柳绿阴中。\n粉絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16374, '卖花声', '黄升', '秋色满层霄。\n剪剪寒飚。\n一襟残照两无聊。\n数尽归鸦人不见，落木萧萧。\n往事欲魂消。\n梦想风标。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16375, '长相思', '黄升', '天悠悠。\n水悠悠。\n月印金枢晓未收。\n笛声人倚楼。\n芦花秋。\n蓼花秋。\n催得吴霜点鬓稠。\n香笺莫寄愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16376, '长相思', '黄升', '砧声齐。\n杵声齐。\n金井栏边败叶飞。\n夜寒乌不栖。\n风凄凄。\n露凄凄。\n影转梧桐月已西。\n花冠窗外啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16377, '长相思', '黄升', '惜春归。\n爱春归。\n脱了罗衣著苎衣。\n绿阴黄鸟啼。\n酒醒时。\n梦醒时。\n清簟疏帘一局棋。\n丁东风马儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16378, '感皇恩', '黄升', '骑鹤上扬州，腰缠十万。\n拈起诗人旧公案。\n看山看水，此去胜游须遍。\n烦君收拾取，归吟卷。\n少日风流，暮年萧散。\n佳处何妨小留款。\n沙河塘上，落日绣帘争卷。\n也须拂拭起，看花眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16379, '蝶恋花', '黄升', '百计留春春不住。\n褪粉吹香，日日催教去。\n心事欲凭莺语诉。\n流莺划地无凭据。\n绿玉阑干围绮户。\n一点柔红，应在深深处。\n想倚翠帘吹柳絮。\n浅颦惆怅芳期误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16380, '月照梨花・河传', '黄升', '昼景。\n方永。\n重帘花影。\n好梦犹酣，莺声唤醒。\n门外风絮交飞。\n送春归。\n修蛾画了无人问。\n几多别恨。\n泪洗残妆粉。\n不知郎马何处嘶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16381, '摸鱼儿', '黄升', '问山中、小桃开後，曾经多少晴雨。\n遥知载酒花边去，唱我旧歌金缕。\n行乐处。\n正蝶绕蜂围，锦绣迷无路。\n风光有主。\n想倚杖西阡，停杯北望，望断碧云暮。\n花知道，应倩蜚鸿寄语。\n年来老子安否。\n一春一到成虚约，不道树犹如此。\n烦说与。\n但岁岁、东风妆点红云坞。\n刘郎老去。\n待有日重来，同君一笑，拈起看花句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16382, '水龙吟', '黄升', '少年有志封侯，弯弓欲挂扶桑外。\n一朝敛缩，萧然清兴，了无拘碍。\n袖里阴符，枕中鸿宝，功名蝉蜕。\n看舌端霹雳，剧谈玄妙，人间世、疑无对。\n阆苑醉乡佳处，想当年、绿阴犹在。\n群仙寄语，不须点勘，鬼神功罪。\n碧海千寻，赤城万丈，风高浪快。\n待踞龟食蛤，相期汗漫，与烟霞会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16383, '西河', '黄升', '天似洗。\n残秋未有寒意。\n何人短笛弄西风，数声壮伟。\n倚栏感慨展双眸，离离烟树如荠。\n少年事，成梦里。\n客愁付与流水。\n笔床茶具老空山，未妨肆志。\n世间富贵要时贤，深居宜有馀味。\n大江东去日西坠。\n想悠悠千古兴废。\n此地阅人多矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16384, '清平乐', '黄升', '珠帘寂寂。\n愁背银缸泣。\n记得少年初选入。\n三十六宫第一。\n当年掌上承恩。\n而今冷落长门。\n又是羊车过也，月明花落黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16385, '清平乐', '黄升', '深深禁。\n霁日明莺羽。\n风动槐龙交翠舞。\n恰恰花阴亭午。\n一帘暖絮悠扬。\n金炉旋炷沈香。\n天子方看谏疏，内人休斗新妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16386, '酹江月・念奴娇', '黄升', '玉林何有，有一弯莲沼，数间茅宇。\n断堑疏篱聊补葺，那得粉墙朱户。\n禾黍秋风，鸡豚晓日，活脱田家趣。\n客来茶罢，自挑野菜同煮。\n多少甲第连云，十眉环座，人醉黄金坞。\n回首邯郸春梦破，零落珠歌翠舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16387, '酹江月・念奴娇', '黄升', '西风解事，为人间、洗尽三庚烦暑。\n一枕新凉宜客梦，飞入藕花深处。\n冰雪襟怀，琉璃世界，夜气清如许。\n划然长啸，起来秋满庭户。\n应笑楚客才高，兰成愁悴，遗恨传千古。\n作赋吟诗空自好，不直一杯秋露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16388, '浣沙溪・浣溪沙', '黄升', '锺磬泠泠夜未央。\n梨花庭院月如霜。\n步虚声里拜瑶章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16389, '鹧鸪天', '黄升', '沈水香销梦半醒。\n斜阳恰照竹间亭。\n戏临小草书团扇，自拣残花插净瓶。\n莺宛转，燕丁宁。\n晴波不动晚山青。\n玉人只怨春归去，不道槐云绿满庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16390, '鹧鸪天', '黄升', '雨过芙蕖叶叶凉。\n摩挲短发照横塘。\n一行归鹭拖秋色，几树鸣蝉饯夕阳。\n花侧畔，柳旁相。\n微云澹月又昏黄。\n风流不在谈锋胜，袖手无言味最长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16391, '秦楼月・忆秦娥', '黄升', '心如结。\n西风老尽黄花节。\n黄花节。\n塞鸿声断，冷烟凄月。\n汉朝陵庙唐宫阙。\n兴衰万变从谁说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16392, '重叠金・菩萨蛮', '黄升', '西风半夜惊罗扇。\n蛩声入梦传幽怨。\n碧藕试初凉。\n露痕啼粉香。\n清冰凝簟竹。\n不许双鸳宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16393, '重叠金・菩萨蛮', '黄升', '南山未解松梢雪。\n西山已挂梅梢月。\n说似玉林人。\n人间无此清。\n此身元是客。\n小住娱今夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16394, '重叠金・菩萨蛮', '黄升', '银幡彩胜参差剪。\n东风吹上钗头燕。\n一笑绕花身。\n小桃先报春。\n新春今日是。\n明日新年至。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16395, '谒金门', '黄升', '花事浅。\n方费化工匀染。\n墙角红梅开未遍。\n小桃才数点。\n人在暮寒庭院。\n闲续茶经香传。\n酒思如冰诗思懒。\n雨声帘不卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16396, '南乡子', '黄升', '多病带围宽。\n未到衰年已鲜欢。\n梦破小楼风马响，珊珊。\n缺月无情转画栏。\n凉入苎衾单。\n起探灯花夜欲阑。\n书册满床空伴睡，慵观。\n拈得渔樵笛谱看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16397, '南乡子', '黄升', '万籁寂无声。\n衾铁棱棱近五更。\n香断灯昏吟未稳，凄清。\n只有霜华伴月明。\n应是夜寒凝。\n恼得梅花睡不成。\n我念梅花花念我，关情。\n起看清冰满玉瓶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16398, '花发沁园春', '黄升', '晓燕传情，午莺喧梦，起来检校芳事。\n荼シ褪雪，杨柳吹绵，迤逦麦秋天气。\n翻阶傍砌。\n看芍药、新妆娇媚。\n正凤紫匀染绡裳，猩红轻透罗袂。\n昼暖朱阑困倚。\n是天姿妖娆，不减姚魏。\n随蜂惹粉，趁蝶栖香，引动少年情味。\n花浓酒美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16399, '阮郎归', '黄升', '粉香吹暖透单衣。\n金泥双凤飞。\n闲来花下立多时。\n春风酒醒迟。\n桃叶曲，柳枝词。\n芳心空自知。\n湘皋月冷佩声微。\n雁归人不归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16400, '鹊桥仙', '黄升', '青林雨歇，珠帘风细，人在绿阴庭院。\n夜来能有几多寒，已瘦了、梨花一半。\n宝钗无据，玉琴难托，合造一襟幽怨。\n云窗雾阁事茫茫，试与问、杏梁双燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16401, '鹧鸪天', '黄升', '天气清和仅两旬。\n一旬前是佛生辰。\n当年来应徐卿梦，此夕遥瞻寿宿明。\n拼一笑，对诸贤。\n山翁何以祝龟龄。\n蟠桃瓜枣皆虚诞，愿把阴功福後人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16402, '瑞龙吟', '杨泽民', '城南路。\n凝望映竹摇风，酒旗标树。\n郊原游子停车，问山崦里，人家甚处。\n去还伫。\n徐见画桥流水，小窗低户。\n深沈绿满垂杨，芳阴娅姹，娇莺解语。\n多谢佳人情厚，卷帘羞得，庭花飘舞。\n可谓望风知心，倾盖如故。\n犹香玉，休赋断肠句。\n堪怜处、生尘罗袜，凌波微步。\n底事匆匆去。\n为他系绊，离情万绪。\n空有愁如缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16403, '琐窗寒', '杨泽民', '倦拂鸳衾，羞临鹊鉴，懒开窗户。\n韶华暗度，又过妒花风雨。\n掩熏炉、怕闻旧香，柳阴只有黄莺语。\n似向人、欲说离愁，因念未归行旅。\n春暮。\n知何处。\n便不念芳年，正当三五。\n轻衫快马，去逐狂朋怪侣。\n便罗帷、香阁顿忘，枕边要语曾记否。\n趁芳时、即早归来，尚可清俎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16404, '风流子', '杨泽民', '佳胜古钱塘。\n帝居丽、金屋对昭阳。\n有风月九衢，凤皇双阙，万年芳树，千雉宫墙。\n户十万，家家堆锦绣，处处鼓笙簧。\n三竺胜游，两峰奇观，涌金仙舸，丰乐霞觞。\n芙蓉城何似，楼台簇中禁，帘卷东厢。\n盈望虎貔分列，鸳鹭成行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16405, '渡江云', '杨泽民', '渔乡回落照，晚风势急，骛鹭集汀沙。\n解鞍将憩息，细径疏篱，竹隐两三家。\n山肴野蔌，竞素朴、都没浮华。\n回望时，绕村流水，万点舞寒鸦。\n休嗟。\n明年秋暮，一叶扁舟，望平川北下。\n应免劳、尘巾乌帽，宵炬红纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16406, '应天长', '杨泽民', '夭桃弄粉，繁杏透香，依然旧日颜色。\n奈彼妒花风雨，连阴过寒食。\n金钗试寻妙客。\n正昼永、院深人寂。\n善歌更解舞，传闻触处声藉。\n当日俊游时，屡向平康，吟咏共题壁。\n自後纵经回曲，难寻阿姨宅。\n芳华苑，罗绮陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16407, '荔枝香', '杨泽民', '瞰水自多佳处。\n春未去。\n绣桷斗起凌空，隐隐笼轻雾。\n已飞画栋朝云，又卷西山雨。\n相与。\n共煮新茶取花乳。\n开宴处。\n俯北榭、临南浦。\n迤扁逦舟，双浆棹歌齐举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16408, '荔枝香', '杨泽民', '未论离亭话别，涕先泫。\n旋涤瑶觯，深挹芳醪，凝愁满眼。\n偎人大白须卷。\n歌遍。\n三劝。\n记得当时送□远。\n素蟾屡明晦，彩云易散。\n後约难知，又却似、阳关宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16409, '还京乐', '杨泽民', '春光至，欲访清歌妙舞重为理。\n念莺轻燕怯媚容，百斛明珠须费。\n算枕前盟誓。\n深诚密约堪凭委。\n意正美，娇眼又洒，梨花春泪。\n记罗帷底。\n向鸳鸯、灯畔相偎，共把前回，词语咏味。\n无端浪迹萍蓬，奈区区、又催行李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16410, '扫花游・扫地游', '杨泽民', '素秋渐老，正叶落吴江，雁横南楚。\n暮霞散缕。\n听寒蝉断续，乱鸦鼓舞。\n客舍凄清，那更西风送雨。\n又东去。\n过野杏小桥，都在元处。\n心事天未许。\n似误出桃源，再寻仙路。\n去年燕俎。\n记芳腮妒李，细腰束素。\n事没双全，自古瓜甜蒂苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16411, '解连环', '杨泽民', '塞鸿难托。\n奈云深雾阔，水遥山邈。\n感两情、浑若连环，念恩爱厚深，利名浮薄。\n便好归来，怎禁得、许多萧索。\n免恹恹瘦减，漫滞寝，枉费汤药。\n伊心料应未若。\n对香消兽吻，月转楼角。\n凭便是、铁石心肠，有当日盟言，怎忍辜却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16412, '玲珑四犯', '杨泽民', '韵胜江梅，笑杏俗桃粗，空眩妖艳。\n尽屏铅华，天赋翠眉丹脸。\n门闭昼永春长，看燕子、并飞撩乱。\n叹岁华若箭频换。\n深院有谁能见。\n夜来初得同相荐。\n便门阑、瑞烟葱茜。\n天然素质真颜色，直是惊人眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16413, '丹凤吟', '杨泽民', '荏苒秋光虚度，玩月池台，登高楼阁。\n风传霜信，遍送晓寒侵幕。\n凄凉细雨，洒窗飘户，漏永更长，枕单衾薄。\n梦里惊鸿唤起，坐对寒，犹听晨漏残角。\n先自宿酲似病，共愁造合滋味恶。\n虽有丁宁语，怕旁人多口，还类金铄。\n如斯情绪，戚戚怎禁牢落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16414, '满江红', '杨泽民', '袅娜身材，经行处、金莲涉足。\n晨妆罢，黛眉新晕，素腰如束。\n丹脸匀红香在臂，秀肌腻滑凉生肉。\n记那回、同赌选花图，赢全局。\n相思病，休卜。\n辜负却，杨枝曲。\n漫榴花堆火，翠阴笼屋。\n菡萏方池闲艳蕊，画堂未许归云宿。\n任利名、踪迹久尘埃，教谁扑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16415, '瑞鹤仙', '杨泽民', '依山仍负郭。\n有松桂扶疏，烟霞渺漠。\n一年自成落。\n奈孤踪还系，蝇头蜗角。\n休嗤句弱。\n赋郊居、何让沈约。\n记乡人过我，傩立阼阶，酒行先酌。\n远映江山奇胜，下瞰重湖，上飞高阁。\n风帘絮幕。\n筑新槛，种花药。\n幸瓜期已近，秋风归去，免得奔驰味恶。\n待开池、剩起林亭，共同宴乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16416, '西平乐', '杨泽民', '圃韭畦蔬，嫩鸡野腊，邻酝稚子能赊。\n罗幕新裁，画楼高耸，松梧柳竹交遮。\n应便作归休计去，高揖渊明，下视林逋，到此如何，又走风沙。\n都为啼号累我，思量事、未遂即咨嗟。\n连年奔逐，旁州外邑，舟楫轻扬，鞭□倾斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16417, '浪淘沙慢', '杨泽民', '禁城外，青青细柳，翠拂高堞。\n征鼓催人骤发。\n长亭渐觉宴阕。\n情绪似丁香千百结。\n忍重看、手简亲折。\n听怨举离歌寄深意，新声更清绝。\n心切。\n暮天塞草烟阔。\n正乍轻尘，新睛後，汨汨清渭咽。\n闻西度阳关，风致全别。\n玉杯屡竭。\n思故人千里，唯同明月。\n扶上雕鞍还三叠。\n那堪第四声未歇。\n念蟾魄、能圆还解缺。\n况人事、莫苦悲伤悴艳色。\n归来复见头应雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16418, '忆旧游', '杨泽民', '念区区远宦，带月侵晨，燃烛中宵。\n在昔曾游遍，过三湘下浙，二水通潇。\n小舟暂辍兰棹，羸马复鞭摇。\n但旧日雄图，平生壮气，往往潜消。\n迢迢。\n向年事，记艳质平堤，曾共听镖。\n醉□游沙市，被疏狂伴侣，朝暮相招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16419, '蓦山溪', '杨泽民', '当年苏小，家住苕溪尾。\n一棹采莲归，悄羞得、鸳鸯飞避。\n苹洲蓼岸，花脸两难分，崖半倚。\n风乍起。\n荡漾烟光里。\n平生强项，未肯轻鱼水。\n溪上偶相逢，这一段、风情怎已。\n纫兰解佩，不负有情人，金尊侧，罗帐底。\n占尽人间美。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16420, '少年游', '杨泽民', '金炉喷兽枕山。\n衾帐不知寒。\n数片飞花，初临窗外，犹作堕梅看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16421, '少年游', '杨泽民', '三分芳髻拢青丝。\n花下见仙姿。\n雨情怀，沾风踪迹，相见恨欢迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16422, '秋蕊香', '杨泽民', '向晓银瓶香暖。\n宿蕊犹残娇面。\n风尘一缕透窗眼。\n恨入春山黛浅。\n短书封了凭金线。\n系双燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16423, '渔家傲', '杨泽民', '李素华曾缟昼。\n当年独冠群芳秀。\n今日再来眉暗斗。\n谁人後。\n追思恰似章台柳。\n先自病来迟唧溜。\n肌肤瘦减宽襟袖。\n已是无聊仍断酒。\n徘徊久。\n者番枉走长亭候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16424, '渔家傲', '杨泽民', '未把金杯心已恻。\n少年病酒还成积。\n一昨宦游来水国。\n心知得。\n陶陶大醉何人识。\n日近偶然频燕客。\n尊前巾帽时仄。\n致得沈疴盟枕席。\n吾方适。\n从今更不尝涓滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16425, '南乡子', '杨泽民', '乘月上高楼。\n一片清光浩莫收。\n帘卷好风知客意，飕飕。\n山自纵横水自流。\n却绕古城头。\n尘事匆匆得少休。\n遥送征鸿千里外，明眸。\n消尽人间万种愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16426, '望江南・忆江南', '杨泽民', '寻胜去，驱马上南堤。\n信脚不知人远近，醉眠犹劝玉东西。\n归帽任冲泥。\n春雨过，农事在瓜蹊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16427, '浣溪沙', '杨泽民', '芳蕊松夹道垂。\n珠幢玉节下瑶池。\n异香团就小花儿。\n应念裴航佳句好，休论白傅送行悲。\n月娥亲自送仙衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16428, '浣溪沙', '杨泽民', '原上芳华已乱飞。\n林间佛日却晖晖。\n一花六叶殿春归。\n身外色香空荏苒，鼻端消息正霏微。\n禅林曲几坐忘时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16429, '浣溪沙', '杨泽民', '金粟蒙茸翠叶垂。\n月宫仙种下天涯。\n儿曹攀折有云梯。\n枕畔幽芳醒睡思，炉中换骨脱金泥。\n待持金翦怕儿啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16430, '迎春乐', '杨泽民', '池边刺竹初成屋。\n拨芳瓮、酒初熟。\n奈巾车秣马催人速。\n还又伴、孤云宿。\n蜗角蝇头相窘束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16431, '迎春乐', '杨泽民', '沈吟暗想狂踪迹。\n亲曾作、燕堂客。\n赏春风、共醉垂杨陌。\n云鬓、金钗侧。\n对酒何曾辞大白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16432, '点绛唇', '杨泽民', '流水泠泠，闭门时候廉纤雨。\n菱歌齐举。\n风暖飘香絮。\n一叶扁舟，过尽莺啼处。\n空凝伫。\n到头辛苦。\n暮色闻津鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16433, '一落索', '杨泽民', '水与东风俱秀。\n一池春皱。\n满庭花卉尽芳菲，只有朵、江梅瘦。\n谱里知名自久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16434, '一落索', '杨泽民', '识尽人间甘苦。\n不如归去。\n先来孤馆客愁多，更倾下、连宵雨。\n尽日登山绕树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16435, '满庭芳', '杨泽民', '春过园林，雨馀池沼，嫩荷点点青圆。\n昼长人静，芳树欲生烟。\n一径幽通邃竹，松风漱、石齿溅溅。\n平生志，功名未就，先觅五湖船。\n不如，归去好，良田二顷，茅舍三椽。\n任高歌月下，痛饮花前。\n果解忘情寄意，又何在、频抚无弦。\n烟波友，扁舟过我，相伴白鸥眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16436, '隔浦莲近拍', '杨泽民', '桑阴柔弄羽葆。\n莲渚芳容窈。\n翠叶浓障屋，绵蛮时啭黄鸟。\n闲步嫩草。\n鱼儿闹。\n作队游苹沼。\n画屏小。\n纱厨簟枕，接沈醉犹倒。\n华胥境界，燕子几声催晓。\n携手兰房未步到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16437, '法曲献仙音', '杨泽民', '汀蓼收红，井梧凋绿，呖呖征鸿南度。\n静听寒砧，闷孤枕，蟾光夜深窥户。\n露暗滴、芭蕉重，潇潇本非雨。\n砌蛩语。\n怎知人、漏长无寐，因念游子，路修道又阻。\n早起懒晨妆，自秋来、眉黛谁妩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16438, '选官子・选冠子', '杨泽民', '塞雁呼云，寒蝉噪晚，绕砌夜蛩凄断。\n迢迢玉宇，耿耿银河，明月又歌团扇。\n行客暮泊邮亭，孤枕难禁，一窗风箭。\n念松荒三迳，门低五柳，故山犹远。\n堪叹处。\n对敌风光，题评景物，恶句斐然挥染。\n风埃世路，冷暖人情，一瞬几分更变。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16439, '侧犯', '杨泽民', '九衢艳质，看来怎比他闲靓。\n清韵。\n似照水横斜暮临镜。\n林间顿画阁，花底藏芳径。\n幽静。\n将绛烛、高烧照双影。\n琼瑶皓素，未及肌肤莹。\n伊试省。\n我从今、还肯再孤另。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16440, '塞翁吟', '杨泽民', '院宇临池水，桥边绕水胧。\n桥左右，水西东。\n水木两芙蓉。\n低疑洛浦凌波步，高如弄玉凌空。\n叶百叠，蕊千重。\n更都染轻红。\n冲冲。\n能消尽，忧心似结，看艳色、浑如梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16441, '苏幕遮', '杨泽民', '日烘晴，风却暑。\n帘幕中间，紫燕呢喃语。\n嫩竹新荷初沐雨。\n曲栏幽轩，四面明窗举。\n夏初临，春又去。\n不愿封侯，祗怕为羁旅。\n溪上故人无恙否。\n欲唱菱歌，发棹归南浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16442, '浣溪沙', '杨泽民', '南国幽花比并香。\n直从初夏到秋凉。\n素馨茉莉占时光。\n梅□正寒方著蕊，芙蓉过暑即空塘。\n个中春色最难量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16443, '浣溪沙', '杨泽民', '一径栽培九畹成。\n丛生幽谷免倾。\n异芳止合在林亭。\n馥郁国香难可拟，纷纭俗眼不须惊。\n好风披拂雨初晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16444, '浣溪沙', '杨泽民', '仙子何年下太空。\n凌波微步笑芙蓉。\n水风残月助惺忪。\n矾弟梅兄都在眼，银台金盏正当胸。\n为伊一醉酒颜红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16445, '浣溪沙', '杨泽民', '风递馀花点素缯。\n日烘芳炷下萝藤。\n为谁雕琢碎春冰。\n玉蕊观中犹得誉，木樨岩下尚驰声。\n何如高架任伊凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16446, '点绛唇', '杨泽民', '雨歇方塘，清圆一一风荷举。\n舣舟南浦。\n忘却来时路。\n醉拍春衫，便欲随君去。\n犹回顾。\n阿蛮樊素。\n更有留人处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16447, '诉衷情', '杨泽民', '眼前时果漫堆盘。\n莫是又贪酸。\n因何近来销减，微褪脸霞丹。\n还只为，枕衾闲。\n泪痕斑。\n我能医疗，一服收功，只霎时间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16448, '风流子', '杨泽民', '行乐平生志，方从事、未出已思归。\n叹欢宴会同，类多暌阻，冶游踪迹、还又参差。\n年华换，利名虚岁月，交友半云泥。\n休忆旧游，免成春瘦，莫怀新恨，恐惹秋悲。\n惟思行乐处，几思为春困，醉枕罗衣。\n何事暗辜芳约，偷负佳期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16449, '华胥引', '杨泽民', '征车将动，愁不成歌，对颦翠叶。\n静掩兰房，香铺卧鸭烟罢唼。\n别後羞看霓裳，更把筝休轧。\n频数更筹，乍寒孤枕偏怯。\n尝为霜髭，弄纤纤、向人轻镊。\n旧词新句，幽窗时时并阅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16450, '宴清都', '杨泽民', '早作听晨鼓。\n征车动、画桥乘月先度。\n邻鸡唱晓，人家未起，尚扃柴户。\n沙边塞雁声遥，料不见、当时伴侣。\n似怎地、满眼愁悲，秋如宋玉难赋。\n休论爱合暌离，微官系缚，期会良苦。\n封侯万里，金堆北斗，不如归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16451, '四园竹', '杨泽民', '残霞殿雨，气入窗扉。\n井梧堕叶，寒砌叫蛩，秋满屏帏。\n罗袖匆匆叙别，凄凉客里，异乡谁更相知。\n念伊其。\n当时芍药同心，谁知又爽佳期。\n直待金风到後，红叶秋时。\n细写情辞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16452, '齐天乐', '杨泽民', '护霜云澹兰皋暮，行人怕临昏晚。\n皓月明楼，梧桐雨叶，一片离愁难翦。\n殊乡异景，奈频易寒暄，屡更茵簟。\n案牍纷纭，夜深犹看两三卷。\n平川回棹未久，简书还授命，又催程限。\n贡浦南游，桃江西下，还是水行陆转。\n天寒雁远。\n但独拥兰衾，枕檀谁荐。\n再促征车，月华犹未敛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16453, '木兰花・玉楼春', '杨泽民', '奇容压尽群芳秀。\n枕臂浓香犹在袖。\n自从草草为传杯，但觉厌厌长病酒。\n堤上路长官柳瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16454, '霜叶飞', '杨泽民', '朔风严紧，长空布、同云低黯天表。\n更堪中夕振寒威，枕风声悄。\n望皓洁、窗纱向晓。\n珠帘才上银钩小。\n听美人都惊□，老尽群山，远近相照。\n深意劝客金尊，皑皑千里，琼台瑶圃重到。\n绮罗香暖恣欢娱，暂尔宽怀抱。\n更几朵、梅花开了。\n巡檐聊与花相调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16455, '蕙兰芳・蕙兰芳引', '杨泽民', '池亭小，帘幕初下，散飞凫骛。\n乍风约云开，遥障几眉横绿。\n画桥架月，映四岸、垂杨遮屋。\n绕翠栏满槛，尽是新栽花竹。\n风送荷香，凉生冰簟，岂畏炎燠。\n便催唤双成，看舞相时丽曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16456, '塞垣春', '杨泽民', '绣阁临芳野。\n向晚把、花枝卸。\n世间寻觅，除是图画。\n这欢娱已系人心也。\n更翰墨、新挥洒。\n展蛮笺、明窗底，把□心事都写。\n谢女与檀郎，清才对、真态俱雅。\n凤枕乐春宵，绛帷度秋夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16457, '丁香结', '杨泽民', '梅雨犹清，冷风乘急，遥送万丝斜陨。\n听水翻雷迅。\n冒雾湿，但觉衣裘皆润。\n乱山烟嶂外，轻寒透、未免强忍。\n崎岖危石，耸峭峻岭，都齐行尽。\n指引。\n看负弩旌旗，谩卷空、排素阵。\n向晚收云，黎明见日，渐生红晕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16458, '氐州第一', '杨泽民', '潇潇寒庭，深院绣盖，佳人就中娇小。\n半额装成，纤腰浴罢，初著铢衣缥缈。\n徐整鸾钗，向凤鉴、低徊斜照。\n情态方浓，憨痴不管，绿稀红老。\n阆苑春回花枝少。\n漫微步、芳丛频绕。\n密意难窥，幽欢未讲，时把琵琶抱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16459, '解蹀躞', '杨泽民', '一掬金莲微步。\n堪向盘中舞。\n主人开阖，呼来慰行旅。\n暂时略得舒怀，事如橄榄，馀甘卒难回苦。\n惹愁绪。\n便□偎人低唱，如何当奇遇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16460, '少年游', '杨泽民', '鸾胎麟角，金盘玉箸，芳果荐香橙。\n洛浦佳人，缑山仙子，高会共吹笙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16461, '庆春宫・高阳台', '杨泽民', '曲渚澜生。\n遥峰云敛，据鞍又出江城。\n青子垂枝，翠阴遮道，乍闻一两蝉声。\n素蟾犹在，但惟有、长庚殿星。\n征夫前路，应怪劳生，尘事相萦。\n年来厌逐时迎。\n千里追寻，两鬓凋零。\n佳景良辰，无虚度，谁怜客里凄清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16462, '醉桃源・阮郎归', '杨泽民', '十年依旧破衫青。\n空书制敕绫。\n但知心似玉壶冰。\n牛衣休涕零。\n聊蹇傲，莫升腾。\n毋为附骥蝇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16463, '醉桃源・阮郎归', '杨泽民', '大都修炼似蒸沙。\n阴阳失两家。\n正如飞鳖舞长蛇。\n宁知饮月华。\n回老貌，假群娃。\n熏蒸成绛霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16464, '点绛唇', '杨泽民', '岸草离离，暮天雨过添清润。\n小舟移近。\n怕得江头信。\n无奈风高，雁字难成阵。\n思排闷。\n管弦难趁。\n怎解心头恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16465, '夜游宫', '杨泽民', '一叶飘然下水。\n船头转、已行十里。\n冷落杯盘荐梅子。\n又经过，岭边村，江上市。\n那更轻帆底。\n一路上、翠飘红坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16466, '夜游宫', '杨泽民', '泪眼偎人强敛。\n鲛绡上、尚馀斑点。\n别後何愁不相见。\n只愁伊，被旁人，施暗箭。\n致得心肠转。\n教令得、神魂撩乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16467, '诉衷情', '杨泽民', '侵晨呵手怯清霜。\n闲写两三行。\n都将旧游新恨，收拾入行装。\n人乍别，路尤长。\n漫嗟伤。\n不如归去，只者温柔，便是仙乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16468, '伤情怨・清商怨', '杨泽民', '娇痴年纪尚小。\n试晚妆初了。\n自戴黄花，开奁还自照。\n临岐离思浩渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16469, '红林擒近', '杨泽民', '轻有鹅毛体，白如龙脑香。\n琼笋缀飞桷，冰壶鉴方塘。\n浑如瑶台阆苑，更无茅舍蓬窗。\n画阁自有梅装。\n贪耍罢弹簧。\n鼓舞沽酒市，蓑笠钓鱼乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16470, '红林擒近', '杨泽民', '梅信初回暖，风棱犹壮寒。\n禾稼响圭璧，帘旌隐琅。\n门外群山尚满，窗前数片馀残。\n冻底潜有鱼翻。\n东风渐生澜。\n杖策扶半醉，燕寝有馀欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16471, '满路花・促拍满路花', '杨泽民', '双眼滟秋波，两脸凝春雪。\n尊前初见处，琴心绝。\n千磨百难，石上琼簪折。\n人非天样阔。\n车马难通，奈何没个关节。\n深盟密约，啮臂曾流血。\n须知弦断有，鸾胶接。\n别离日久，转觉归心切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16472, '解语花', '杨泽民', '星桥夜度，火树宵开，灯月光交射。\n翠檐铜瓦。\n相辉映、隐隐绛霞飘下。\n风流艳雅。\n向柳陌、纤纤共把。\n筵宴时、频酌香醪，宝鸭喷沈麝。\n已是欢娱尽夜。\n对芳时堪画，条倡叶冶。\n鸳灯诗帕。\n嬉游看、到处骤轮驰马。\n十千换也。\n惟好事、寸心难谢。\n听九衢、三市行歌，到晓钟才罢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16473, '倒犯', '杨泽民', '黛眉新扫。\n芳容衬缟。\n佳人在、翠帘深窈。\n逡巡遽赠诗语，因询屏帏悄。\n道自有、蓝桥美质诚堪表。\n倩纤纤、捧芳。\n琴剑度关，望玉京人，迢迢天样。\n下马叩靖宇，见仙女、云英小。\n算冠绝、人间好。\n饮刀圭、神丹同得道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16474, '大', '杨泽民', '渐雨回春，风清夏，垂柳凉生芳屋。\n馀花犹满地，引蜂游蝶戏，慢飞轻触。\n院宇深沈，帘栊寂静，苍玉时敲疏竹。\n雕梁新来燕，恣呢喃不住，似曾相熟。\n但双去并来，漫萦幽恨，枕单衾独。\n仙郎去又速。\n料今在、何许停双毂。\n任梦想、频登台榭，遍倚阑干，水云千里空流目。\n纵遇双鱼客，难尽写、别来心曲。\n媚容幸倾城国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16475, '玉烛新', '杨泽民', '梨花寒食後。\n被丽日和风，一时开就。\n雨歇，香犹嫩、渐觉芳心彰漏。\n墙头月下，似旧日莺莺相候。\n纤手为、攀折翘枝，轻盈露沾红袖。\n风流出浴杨妃，向海上何人，更询安否。\n百花任斗。\n应粉艳、未减杏粗梅瘦。\n肤丰肉秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16476, '花犯', '杨泽民', '百花中，夭桃秀色，堪餐作珍味。\n武陵溪上，□宋玉墙头，全胜姝丽。\n去年此日佳人倚。\n凝情心暗喜。\n恨未得、合欢鸳帐，归来犹半被。\n寻春记前约因□，题诗算怎耐、相思憔悴。\n攀玩对、东君道，莫教轻坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16477, '丑奴儿・采桑子', '杨泽民', '冰姿冠绝人间世，傲雪凌霜。\n蕊点檀黄。\n更看红唇间素妆。\n清芬不是先桃李，桃李无香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16478, '水龙吟', '杨泽民', '腻金匀点繁英，好风更与花为地。\n梅魂蕙魄，素馨□长，酴请避。\n拍塞清香，远闻十里，如何藏闭。\n笑东篱嫩菊，空攒细蕊，祗供得、重阳泪。\n争似青青叶底。\n傍西窗、时复轻吹。\n玉炉换骨，宝瓶熏梦，幽人睡起。\n管领秋光，留连佳景，几多新意。\n怕娥、不□蟾宫桂种，□高枝比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16479, '六丑', '杨泽民', '叹浓欢易散，便忍把、恩情抛掷。\n恁时寸心，惟思生翅翼。\n别後踪迹。\n不定如萍泛，暂抛江沔，又留连京国。\n芳容料见尤光泽。\n共赏青楼，同游绮陌。\n皆曾痛怜深惜。\n纵鳞鸿托意，云水犹隔。\n兰房深寂。\n映轻红淡碧。\n翠竹名花底、同燕息。\n杯盘屡肯留客。\n见真诚厚爱，意深情极。\n乌纱翦为新冠帜。\n谁知道、荏苒尘埃带抹，任他倾侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16480, '虞美人', '杨泽民', '层层楼阁薰风暖。\n花里香苞短。\n清芬不逐火云消。\n看了一重姿媚、一重娇。\n几回池上寻芳径。\n惊见波中影。\n似将千叶再苞封。\n肠断昭阳一笑、付飞鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16481, '虞美人', '杨泽民', '小池芳蕊初开遍。\n恰似新妆面。\n扁舟一叶过吴门。\n只向花间高卧、度朝昏。\n浮萍点缀因风絮。\n更共鸳鸯语。\n花间有女恰如云。\n不惜一生常作、采花人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16482, '兰陵王', '杨泽民', '翠竿直。\n一叶扁舟漾碧。\n澄江上、几度啸日迎风，怡怡钓秋色。\n渔乡共水国。\n都属沧浪傲客。\n烟波外，风笠雨蓑，才掷丝纶便千尺。\n飘然去无迹。\n恣脚扣双船，帆挂轻席。\n盈钩香饵鱼争食。\n更拨棹葭岸，放篙菱浦，才过新栅又旧驿。\n占江南江北。\n堪恻。\n利名积。\n算纵有豪华，难比清寂。\n须知此乐天无极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16483, '蝶恋花', '杨泽民', '蜡尽江南梅发後。\n万点黄金，娇眼初窥牖。\n曾见渭城人劝酒。\n嫩条轻拂传杯手。\n料峭东风寒欲透。\n暗点轻烟，便觉添疏秀。\n莫道故人今白首。\n人虽有故心无旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16484, '蝶恋花', '杨泽民', '初过元宵三五後。\n曲槛依依，终日摇金牖。\n瘦损舞腰非为酒。\n长条聊赠垂鞭手。\n几叶小梅春已透。\n信是风流，占尽人间秀。\n走马章台还举首。\n可人标韵强如旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16485, '蝶恋花', '杨泽民', '寂寞春残花谢後。\n落絮轻盈，点点穿风牖。\n浓绿阴中人买酒。\n凉生午扇都停手。\n叶密啼莺飞不透。\n要咏清姿，除是凭才秀。\n往日周郎为唱首。\n今将高韵重翻旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16486, '蝶恋花', '杨泽民', '百卉千花都绽後。\n露依风，翠影笼芳牖。\n杏脸桃腮匀著酒。\n青红相映如携手。\n一段帘丝风约透。\n妆点亭台，表里俱清秀。\n几度长提频矫首。\n青青颜色新如旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16487, '西河', '杨泽民', '形势地。\n岳阳事见图记。\n因山峭拔耸孤城，画楼涌起。\n楚吴巨泽坼东南，惊涛浮动空际。\n半天楼栏翠倚。\n记人凤舸难系。\n空馀细草没章华，但存故垒。\n二妃祠宇隔黄陵，精魂遥接云水。\n蟹鱼橘柚渐上市。\n是当年屈宋乡里。\n别有老仙高世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16488, '三部乐', '杨泽民', '浓绿丛中，露半坼芳苞，自然奇绝。\n水亭风槛，正是蕤宾之月。\n固知道、春色无多，但绛英数点，照眼先发。\n为君的，尽是重心千叶。\n红巾又成半蹙。\n试寻双寄意，向丽人低说。\n但将一枝，插著翠环丝发。\n映秋波、艳云近睫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16489, '菩萨蛮', '杨泽民', '吟风敲遍阑干曲。\n极目澄江千顷绿。\n长笛下扁舟。\n一声人倚楼。\n床头醅正发。\n帐底人如雪。\n月色夜来看。\n可堪霜信寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16490, '品令', '杨泽民', '日长风静。\n浓香在、珠帘花影。\n棋具对著明窗近。\n未排角势，鸦鹭先分阵。\n双叠远山非有恨。\n正藏机休问。\n便如喝采争堂印。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16491, '玉楼春', '杨泽民', '笔端点染相思泪。\n尽写别来无限意。\n祗知香阁有离愁，不信长途无好味。\n行轩一动须千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16492, '满路花・促拍满路花', '杨泽民', '愁得鬓丝斑，没得心肠破。\n上梢恩共爱，忒过火。\n一床锦被，将为都包裹。\n刚被旁人隔，不似鸳鸯，等闲常得双卧。\n非无意智，触事应偏左。\n那堪名与利，相羁锁。\n一番记著，一夜还难过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16493, '声声慢', '陈郁', '澄空初霁，暑退银塘，冰壶雁程寥寞。\n天阙清芬，何事早飘岩壑。\n花神更裁丽质，涨红波、一奁梳掠。\n凉影里，算素娥仙队，似曾相约。\n闲把两花商略。\n开时候、羞趁观桃阶药。\n绿幕黄帘，好顿胆瓶儿著。\n年年粟金万斛，拒严霜、绵丝围幄。\n秋富贵，又何妨、与民同乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16494, '宝鼎现', '陈郁', '虞弦清暑，佳气葱郁，非烟非雾。\n人正在、东闱堂上，分瑞祥辉腾翠渚。\n奉玉，总欢呼称颂，争羡神光葆聚。\n庆诞节、弥生二佛，接踵瑶池仙母。\n最好英慧由天赋。\n有仁慈宽厚襟宇。\n每留念、修身忱意，博问谦勤亲保傅。\n染宝翰、镇规随宸画，心授家传有素。\n更吟咏、形容雅颂，隐隐赓歌风度。\n恩重汉殿传觞，宣付祝、恭承天语。\n对南薰初试，宫院笙箫竞举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16495, '绛都春', '陈郁', '晴天媚晓。\n正禁苑乍暖，莺声娇小。\n柳拂玉阑，花映朱帘韶光早。\n熙朝多暇舒长昼。\n庆圣主、新颁飞诏。\n贻谋恩重，齐家有训，万邦仪表。\n偏称宫闱欢笑。\n酿和气共结，天香缭绕。\n侍宴回车，韶部将迎金莲照。\n鸡鸣警戒丁宁了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16496, '念奴娇', '陈郁', '没巴没鼻，霎时间、做出漫天漫地。\n不论高低并上下，平白都教一例。\n鼓动滕六，招邀巽二，一任张威势。\n识他不破，只今道是祥瑞。\n却恨鹅鸭池边，三更半夜，误了吴元济。\n东郭先生都不管，关上门儿稳睡。\n一夜东风，三竿暖日，万事随流水。\n东皇笑道，山河原是我底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16497, '玉连环・解连环', '冯伟寿', '谪仙往矣，问当年、饮中俦侣，於今谁在。\n叹沈香醉梦，胡尘日月，流浪锦袍宫带。\n高吟三峡动，舞剑九州隘。\n玉皇归觐，半空遗下，诗囊酒佩。\n云月仰挹清芬，揽虬须、尚友千载。\n晋宋颓波，羲皇春梦，尊前一慨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16498, '春风袅娜', '冯伟寿', '被梁间双燕，话尽春愁。\n朝粉谢，午花柔。\n倚红阑故与，蝶围蜂绕，柳绵无数，飞上搔头。\n凤管声圆，蚕房香暖，笑挽罗衫须少留。\n隔院兰馨趁风远，邻墙桃影伴烟收。\n些子风情未减，眉头眼尾，万千事、欲说还休。\n蔷薇露，牡丹球。\n殷勤记省，前度绸缪。\n梦里飞红，觉来无觅，望中新绿，别後空稠。\n相思难偶，叹无情明月，今年已是，三度如钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16499, '春云怨', '冯伟寿', '春风恶劣。\n把数枝香锦，和莺吹折。\n雨重柳腰娇困，燕子欲扶扶不得。\n软日烘烟，乾风吹雾，芍药荼シ弄颜色。\n帘幕轻阴，图书清润，日永篆香绝。\n盈盈笑靥宫黄额。\n试红鸾小扇，丁香双结。\n团凤眉心倩郎贴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16500, '云仙引', '冯伟寿', '紫凤台高，红鸾镜里，几度秋馨。\n黄金重，绿云轻。\n丹砂鬓边滴粟，翠叶玲珑烟剪成。\n含笑出帘，月香满袖，天雾萦身。\n年时花下逢迎。\n有游女、翩翩如五云。\n乱掷芳英，为簪斜朵，事事关心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16501, '眼儿媚', '冯伟寿', '自颦双黛听啼鸦。\n帘外翠烟斜。\n社前风雨，已归燕子，未入人家。\n鞋儿试著无人看，莫是忒宽些。\n想它楼上，闷拈箫管，憔悴莺花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16502, '木兰花慢', '冯伟寿', '酒醒人世换，碧桃靓、海山春。\n任青鸟沈沈，紫鳞杳杳，有玉林人。\n宫袍掉头未爱，爱荷衣、不染市朝尘。\n仙样蓬莱翰墨，云间鸾凤精神。\n笑呼银汉入金鲸。\n琼苑自由身。\n羡咳唾成章，香薰花雾，音和韵钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16503, '失调名', '陈无咎', '一年一度春来，何时是了。\n花落花开浑是梦，只解把人引调。\n可怜浮世，等闲过日，却不识，绿水青山，四时都好。\n遇笔题诗，逢人饮酒，世间万事，看尽多多少少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16504, '沁园春', '陈草阁', '霜剥枯崖，何处邮亭，玉龙夜呼。\n唤经年幽梦，悠然独觉，参横璇汉，漏彻铜壶。\n漠漠风烟，昏昏水月，醉耸诗肩骑瘦驴。\n孤吟处，更寻香吊影，搔首踟蹰。\n古心落落如予。\n悄独立高寒凌万夫。\n对荒烟野草，浅溪沙路，班荆三嗅，此意谁如。\n高卧南阳，归来彭泽，借问风光还似无。\n难穷处，待凭将妙手，作岁寒图。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16505, '木兰香・减字木兰花', '徐介轩', '一帘疏雨。\n道是无情还有思。\n坐久魂销。\n风动珠唇点点娇。\n生平浩气。\n静乐机关随处是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16506, '步蟾宫', '章耐轩', '未开大如木犀蕊。\n开後是、梅花小底。\nけ然只欲住山林，肯容易、结根城市。\n叶儿又与冬青比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16507, '浣溪沙', '昭顺老人', '的堪为席上珍。\n银铛百沸麝脐薰。\n萧娘欲饵意中人。\n拈处玉纤笼蚌颗，剥时琼齿嚼香津。\n仙郎入口即轻身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16508, '南柯子・南歌子', '陈舜翁', '德祖家珍熟，钱塘五月中。\n碧梧桐盖翠筠笼。\n倾向水晶盘内、斗尝空。\n绛粟成团小，清甜笑蜜浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16509, '浪淘沙', '洪子大', '上苑又春残。\n樱颗如丹。\n明光宫里水晶盘。\n想得退朝花底散，宣赐千官。\n往事记金銮。\n荔子难攀。\n多情更有酪浆寒。\n蜀客筠笼相赠处，愁忆长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16510, '八声甘州', '郑子玉', '渐莺声近也，探年芳、河畔扼轻轮。\n旋东风染绿，绵绵平野，无际烟春。\n最苦夕阳天外，愁损倚阑人。\n无奈潇湘杳，留滞王孙。\n冷落池塘残梦，是送君归後，南浦消魂。\n赖东君能客，醉卧展香茵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16511, '虞美人', '文珏', '歌唇乍启尘飞处。\n翠叶轻轻举。\n似通舞态逞妖容。\n嫩条纤丽玉玲珑。\n怯秋风。\n虞姬珠碎兵戈里。\n莫认埋魂地。\n只应遗恨寄芳丛。\n露和清泪湿轻红。\n古今同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16512, '虞美人', '顾卞', '帐前草草军情变。\n月下旗旌乱。\n褫衣推枕惜离情。\n远风吹下楚歌声。\n正三更。\n抚鞍欲上重相顾。\n艳态花无主。\n手中莲萼凛秋霜。\n九泉归路是仙乡。\n恨茫茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16513, '壶中天・念奴娇', '陈景沂', '江邮湘驿。\n问暮年何事，暮冬行役。\n马首摇摇经历处，多少山南溪北。\n冷著烟扉，孤芳云掩，瞥见如相识。\n相逢相劳，如痴如诉如忆。\n最是近晓霜浓，初弦月挂，傅粉金鸾侧。\n冷淡生涯忧忘乐，不管冰檐雪壁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16514, '点绛唇', '陈景沂', '今古凡花，词人尚作词称庆。\n紫薇名盛。\n似得花之圣。\n为底时人，一曲稀流咏。\n花端正。\n花无郎病。\n病亦归之命。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16515, '水龙吟', '陈景沂', '阶前砌下新凉，嫩姿弱质婆娑小。\n仙家甚处，凤雏飞下，化成窈窕。\n尖叶参差，柔枝袅娜，体将玉造。\n自川葵放後，堂萱谢了，是圆苑、无花草。\n自恨西风太早。\n逞芳容、紫围绯绕。\n管里低昂，篦头约略，空成懊恼。\n圆胎结就，小铃垂下，直开临□。\n□凡间谪堕，不如西帝，曾关宸抱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16516, '念奴娇', '松洲', '麦场桑陇，道都是、六代宫城遗迹。\n梦里江山经几觉，还似堠旁征驿。\n燕去燕来，花开花谢，那个成端的。\n人烟牢落，晚风何处羌笛。\n堪叹挥泪新亭，算兴亡莫补、万分之一。\n到我凭阑，休更向酒畔，是今非昔。\n击楫誓清，闻鸡起舞，毕竟英难得。\n伤心残照，塔尖遥露秋碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16517, '浣溪沙', '韩准', '潇洒梧桐几度秋。\n凤凰飞去旧山幽。\n风景不殊人物换，恨悠悠。\n衰草远从烟际合，夕阳空趁水西流。\n恰好凭楼便回首，怕生愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16518, '沁园春', '王云焕', '四十君王，三百载间，兴亡一家。\n叹幕府峰高，生涯社燕，胭脂井暗，富贵飞花。\n山骨呈羞，江声带恨，磨尽英雄岁月赊。\n君知否，是枋头霸上，著数全差。\n倚空长剑吁嗟。\n奈争战年来似乱麻。\n但苍陵古冢，白杨啼，荒园废沼，青草鸣蛙。\n旗盖东南，风涛天堑，难比兴亡隙地些。\n休凝伫，望长安路杳，夕照愁鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16519, '满江红', '王淮', '踏遍江南，予岂为、解衣推食。\n谩赢得、烟波短棹，月楼长笛。\n看剑功名心已死，积薪涕泪今谁滴。\n想中原、一望一伤情，英雄客。\n形势地，还如昔。\n谈笑里，封侯觅。\n岂有於前代，无於今日。\n龙豹莫藏韬略手，犬羊快扫腥膻迹。\n看诸公、事业卜枭卢，何劳掷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16520, '莺啼序', '叶润', '离骚困吟梦醒，访台城旧路。\n问流水、东入沧溟，还解流转西否。\n乌衣梦、浪传故国，晴烟冉冉宫墙树。\n念吟魂凄断，待随燕子来去。\n回首十年，阑锦花场，趁吟云赋雨。\n可曾对、宝瑟知音，高轩为谁轻驻。\n倚东风、愁长笑短，水云深、春江日暮。\n伴羁怀，唯有征衫，贮寒半缕。\n高情谩赋，蕙带兰襟，蛾眉古来相妒。\n英雄到、江南易老。\n後来谁更，风景伤心，泪沾樽俎。\n登山宴水，横江酹酒，倾将慷慨酬形势，付兴亡、一笑翻歌舞。\n独醒难继山公，上马旌旗动，又还惊起鸥鹭。\n危亭恨极，落尽寒香，怕道断肠句。\n有多少、行星翠点，春浅寒深，孕粉藏香，蝶清蜂瘦。\n因孤彩笔芳笺，拟待倩取游丝，系却离绪。\n旋□□、写入鸣弦柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16521, '柳梢青', '张杜', '燕里花深，鹭汀云澹，客梦江皋。\n日日言归，淮山笑我，尘锁征袍。\n几回把酒凭高。\n阑干外、魂飞暮涛。\n只有南园，一番风雨，过了樱桃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16522, '风流子', '王泳祖', '东风长是客，帘栊静、燕子一双飞。\n看花坞日高，翠阴护晓，柳塘风细，绿涨浮漪。\n肠断处，渭城春树远，江国暮云低。\n芳径听莺，暗惊心事，画檐闻鹊，试卜归期。\n小楼凝伫地，疏窗下，几度对说相思。\n记得菱花交照，素手曾携。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16523, '氐州第一', '刘天游', '冰缩寒流，川凝冻霭，前回鹭渚冬晚。\n燕阁红炉，驼峰翠釜，曾忆花柔酒软。\n云海沧洲，甚又寄、南来客雁。\n洒雪朱门，回桡剡曲，镜华霜满。\n万里银霄凝望眼。\n恁吟袖、画阑空暖。\n树带潮墟，笳鸣古戍，簇仲宣幽怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16524, '摸鱼儿', '柴望', '问长江、几分秋色，三分浑在烟雨。\n何人折尽丝丝柳，此日送君南浦。\n帆且驻。\n试说著、羊裘钓雪今何许。\n鱼虾自舞。\n但一舸芦花，数声霜笛，鸥鹭自来去。\n年年事，流水朝朝暮暮。\n天涯长叹飘聚。\n衾寒不转钧天梦，楼外谁歌白。\n君莫诉。\n君试按、秦筝未必如锺吕。\n乡心最苦。\n算只有娟娟，马头皓月，今夜照归路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16525, '齐天乐', '柴望', '青青杨柳丝丝雨，他乡又逢寒食。\n几度刘郎，当年曼倩，迢递水村烟驿。\n寻踪访迹。\n正马上相逢，杏花狼藉。\n惟有沙边，旧时鸥鹭似相识。\n天涯流浪最久，十年何所事，幽愫历历。\n换字鹅归，看梅鹤去，回首征衫泪渍。\n新欢旧忆。\n笑客处如归，归处如客。\n独倚危阑，乱山无数碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16526, '祝英台・祝英台近', '柴望', '小船儿，双去橹。\n红湿海棠雨。\n燕子归时，芳草暗南浦。\n自从翠袖香消，明声断，怕回首、旧寻芳处。\n向谁语。\n可怜金屋无人，冷落凤箫谱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16527, '阳关三叠', '柴望', '西风吹鬓，残发早星星。\n叹故国斜阳，断桥流水，荣悴本无凭。\n但朝朝、才雨又晴。\n人生飘聚等浮萍。\n谁知桃叶，千古是离情。\n正无奈、黯黯离情。\n渡头烟暝，愁杀渡江人。\n伤情处，送君且待江头月，人共月、千里难并。\n笳鼓发，戍云平。\n此夜思君，肠断不禁。\n尽思君送君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16528, '摸鱼儿', '柴望', '这情怀、怎生消遣。\n思量只是凄怨。\n一春长为花和柳，风雨又还零乱。\n君试看。\n便杜牧风流，也则肠先断。\n更深漏短。\n更听得杜宇，一声声切，流水画桥畔。\n人间世，本只阴晴易换。\n斜阳衰草何限。\n悲欢毕竟年年事，千古漫嗟修短。\n无处问。\n是闲倚帘栊，尽日厌厌闷。\n浮名尽懒。\n但笑拍阑干，连呼大白，心事付归燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16529, '念奴娇', '柴望', '匆匆别去，算别来、又是几番春暮。\n酒债不偿还似可，负了若干吟句。\n渭北春天，江南夜雨，总是伤情处。\n黯然消歇，绿杨一阵莺语。\n空记十载嬉游，如今蓦地，两处成离阻。\n纵是相逢天涯路，难觅年时欢侣。\n寄语东君，岁华不驻，谁为留春住。\n小楼昨夜，东风依旧飞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16530, '摸鱼儿', '柴望', '便无他、杜鹃催去，匆匆春事能几。\n看来不见春归路，飞絮又随流水。\n留也是。\n怎禁得、东风红紫还飘坠。\n天涯万里。\n怅燕子人家，沈沈夜雨，添得断肠泪。\n嬉游事。\n早觉相如倦矣。\n谢娘庭院犹记。\n闲情已付孤鸿去，依旧被莺呼起。\n谁料理。\n正乍暖还寒，未是晴天气。\n无言自倚。\n想旧日桃花，而今人面，都是梦儿里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16531, '满江红', '柴望', '载酒何人，登临处、沧洲空阔。\n凭阑外、晴杨两岸，晚烟泼□。\n水鸟不知梁燕去，溪山半属冬青阁。\n有小舟、隐约载歌姝，调新曲。\n留与去，如何得。\n风又雨，催行色。\n共白苹红蓼，好生飘泊。\n别後三年重会面，人生几度三年别。\n正乡心、客梦两绸缪，城头角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16532, '贺新郎', '柴望', '满酌西湖酒。\n觉湖山、依然未老，游人如旧。\n数过清明才六日，欲暖未晴时候。\n正画舫、春明波透。\n记得名园曾驻马，锦鞍鞯、浅映堤桥柳。\n寻胜赏，重回首。\n不妨旋摘枝头有。\n喜青青、垂丸带子，脆圆如豆。\n想是和羹消息近，报与醉翁太守。\n道玉铉、有人启奏。\n红药当阶明似锦，觉娇莺、舞燕皆称寿。\n唱此曲，付红袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16533, '念奴娇', '柴望', '登高回首，叹山河国破，於今何有。\n台上金仙空已去，零落逋梅苏柳。\n双塔飞云，六桥流水，风景还依旧。\n凤笙龙管，何人肠断重奏。\n闻道凝碧池边，宫槐叶落，舞马衔杯酒。\n旧恨春风吹不断，新恨重重还又。\n燕子楼高，乐昌镜远，人比花枝瘦。\n伤情万感，暗沾啼血襟袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16534, '念奴娇', '柴望', '春来多困，正日移帘影，银屏深闭。\n唤梦幽禽烟柳外，惊断巫山十二。\n宿酒初醒，新愁半解，恼得成憔悴。\n云鬓，不鸾镜梳洗。\n门外满地香风，残梅零乱，玉糁苍苔碎。\n乍暖乍寒浑莫拟，欲试罗衣犹未。\n斗草雕阑，买花深院，做踏青天气。\n晴鸠鸣处，一池昨夜春水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16535, '桂枝香', '柴望', '今宵月色。\n叹暗水流花，年事非昨。\n潇洒江南似画，舞枫飘柞。\n谁家又唱江南曲，一番听、一番离索。\n孤鸿飞去，残霞落尽，怨深难托。\n又肠断、丁香画雀。\n记牡丹时候，归燕帘幕。\n梦里襄王，想念王孙飘泊。\n如今雪上萧萧鬓，更相思、连夜花发。\n柘枝犹在，春风那似，旧时宋玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16536, '齐天乐', '柴望', '凄凄杨柳潇潇雨，悄窗怎禁滴沥。\n思里传，愁边落雁，多少东吴山色。\n知他恨极。\n料为我窗前，强鸣刀尺。\n竟日西风，那堪无寐更邻笛。\n黄花开遍未也，花开应笑我，年少难觅。\n灞上长安，河边渭水，都把韶华暗掷。\n何人碎璧。\n尚衰草连天，暮烟凝碧。\n怕说相思，撼枫喧夜寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16537, '朝中措', '王玉', '杨花绕昼暖风多。\n晴云点池波。\n戏数翠萍几靥，零星未碍圆荷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16538, '菩萨蛮', '张桂', '东风忽骤无人见。\n玉塘烟浪浮花片。\n步湿下香阶。\n苔黏金凤鞋。\n翠鬟愁不整。\n临水闲窥影。\n摘得野蔷薇。\n游蜂相趁归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16539, '浣溪沙', '张桂', '雨压杨花路半乾。\n蜂遗花粉在阑干。\n牡丹开尽正春寒。\n懒品么弦金雁并，瘦惊双钏玉鱼宽。\n新愁不放翠眉间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16540, '瑞鹤仙', '张枢', '卷帘人睡起。\n放燕子归来，商量春事。\n风光又能几。\n减芳菲、都在卖花声里。\n吟边眼底。\n被嫩绿、移红换紫。\n甚等闲、半委东风，半委小桥流水。\n还是。\n苔痕湔雨，竹影留云，待晴犹未。\n兰舟静舣。\n西湖上、多少歌吹。\n粉蝶儿、守定落花不去，湿重寻香两翅。\n怎知人、一点新愁，寸心万里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16541, '风入松', '张枢', '春寒懒下碧云楼。\n花事等闲休。\n红绵湿透秋千索，记伴仙、曾倚娇柔。\n重叠黄金约臂，玲珑翠玉搔头。\n薰炉谁熨暖衣篝。\n消遣酒醒愁。\n旧巢未著新来燕，任珠帘、不上琼钩。\n何处东风院宇，数声揭调甘州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16542, '南歌子', '张枢', '柳户朝云湿，花窗午篆清。\n东风未放十分晴。\n留恋海棠颜色、过清明。\n垒润栖新燕，笼深锁旧莺。\n琵琶可是不堪听。\n无奈愁人把做、断肠声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16543, '谒金门', '张枢', '春梦怯。\n人静玉闺平帖。\n睡起眉心端正贴。\n绰枝双杏叶。\n重整金泥蹀躞。\n红皱石榴裙褶。\n款步花阴寻蛱蝶。\n玉纤和粉捻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16544, '庆宫春・高阳台', '张枢', '斜日明霞，残虹分雨，软风浅掠苹波。\n声冷瑶笙，情疏宝扇，酒醒无奈秋何。\n彩云轻散，漫敲缺、铜壶浩歌。\n眉痕留怨，依约远峰，学敛双蛾。\n银床露洗凉柯。\n屏掩香销，忍扫罗。\n楚驿梅边，吴江枫畔，庾郎从此愁多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16545, '壶中天・念奴娇', '张枢', '雁横迥碧，渐烟收极浦，渔唱催晚。\n临水楼台乘醉倚，云引吟情闲远。\n露脚飞凉，山眉锁暝，玉宇冰奁满。\n平波不动，桂华底印清浅。\n应是琼斧修成，铅霜捣就，舞霓裳曲遍。\n窈窕西窗谁弄影，红冷芙蓉深苑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16546, '恋绣衾', '张枢', '屏绡润惹篆烟。\n小窗闲、人泥昼眠。\n正雪暖、荼シ架，奈愁春、尘锁雁弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16547, '清平乐', '张枢', '凤楼人独。\n飞尽罗心烛。\n梦绕屏山三十六。\n依约水西云北。\n晓奁懒试脂铅。\n一谨傥⑵Ａ舻盟拮泵荚冢讨拦旅摺');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16548, '木兰花慢', '张枢', '歌尘凝燕垒，又软语、在雕梁。\n记剪烛调弦，翻香校谱，学品伊凉。\n屏山梦云正暖，放东风、卷雨入巫阳。\n金冷红绦孔雀，翠间彩结鸳鸯。\n银缸。\n焰冷小兰房。\n夜悄怯更长。\n待采叶题诗，含情赠远，烟水茫茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16549, '惜花春起早', '张枢', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16550, '失调名', '张枢', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16551, '失调名', '张枢', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16552, '兰陵王', '叶隆礼', '大堤直。\n袅袅游云蘸碧。\n兰舟上，曾记那回，拂粉涂黄弄春色。\n施颦托倾国。\n金缕尊前劝客。\n阳台路，烟树万重，空有相思寄鱼尺。\n飘零叹萍迹。\n自懒展罗衾，羞对瑶席。\n折钗分镜盟难食。\n看桃叶迎笑，柳枝垂结。\n萋萋芳草暗水驿。\n肠断画阑北。\n寒恻。\n泪痕积。\n想柱雁尘侵，笼羽声寂。\n天涯流水情何极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16553, '水调歌头', '家铉翁', '瀛台居北界，觌面是重城。\n老龙蹲踞不动，潭影净无尘。\n此地高阳胜处，天付仙翁为主，那肯借闲人。\n暂挂西堂锡，仍同旦过宾。\n六年里，五迁舍，得比邻。\n儒馆豆笾於粲，弦诵有遗音。\n甚喜黄冠为侣，更得青衿来伴，应不叹飘零。\n夜宿东华榻，朝餐泮水芹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16554, '念奴娇', '家铉翁', '神仙何处，人尽道、我州三神之一。\n为问何年飞到此，拔地倚天无迹。\n缥缈琼宫，溟茫朱户，不与尘寰隔。\n翩然鹤下，时传云外消息。\n露冷风清夜阑，梦高人过我，欢如畴昔。\n道骨仙风谁得似，谈笑云生几席。\n共踏银虬，迫随绛节，恍遇群仙集。\n云韶九奏，不类人间金石。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16555, '念奴娇', '家铉翁', '南来数骑，问征尘、正是江头风恶。\n耿耿孤忠磨不尽，惟有老天知得。\n短棹浮淮。\n轻毡渡汉，回首觚棱泣。\n缄书欲上，惊传天外清跸。\n路人指示荒台，昔汉家使者，曾留行迹。\n我节君袍雪样明，俯仰都无愧色。\n送子先归，慈颜未老，三径有馀乐。\n逢人问我，为说肝肠如昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16556, '清平乐', '石正伦', '香摇穗碧。\n梅巧红酥滴。\n云宝钗蝉坠翼。\n娇小争禁酒力。\n绣窗芳思迟迟。\n无端又敛双眉。\n贪把兰亭学字，一冬忘了弹棋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16557, '绮寮怨', '石正伦', '绿野春浓停骑，暖风飘醉襟。\n渐触目、景物凄悲，花无语、曲径沈沈。\n重檐缭垣静锁，丹青暗、断轴尘半侵。\n叹绛纱、玉臂封时，何期掩、夜泉流恨深。\n已矣霜凋蕙心。\n兰昌旧事，云容好信难寻。\n伫立孤吟。\n怕凤履、有遗音。\n今宵佩环奏月，知倦客、若登临。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16558, '渔家傲', '石正伦', '春入桃腮生妩媚。\n妆成日日行云意。\n贪听新声翻歇指。\n工尺字。\n窗前自品琼箫试。\n玉碾鸾钗珠结桂。\n金泥络缝乾红袂。\n从把画图夸绝世。\n金莲地。\n六朝未识双鸳细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16559, '霓裳中序第一', '石正伦', '凭高快醉目。\n翠拂遥峰相对簇。\n千丈涟漪泻谷。\n爱溶漾坠红，染波芬馥。\n何人笑掬。\n想温泉、初卸绡。\n春风荡，六宫丽质，那日赐汤沐。\n双浴。\n绣凫飘逐。\n恍记展、江南数幅。\n而今鬓边渐鹄。\n阮洞音稀，懒访仙躅。\n系船桥畔宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16560, '宝鼎现', '陈著', '玉宸凝眷。\n要得培□，神皋根本。\n天赋与、经纶好手，门外红尘谈笑遣。\n任草色、遍空庭交翠，月往风来自便。\n但纸帐、时供小憩，长理灯窗公案。\n五行俱下流光电。\n笔如神、毫发都见。\n是则是、霜严雪劲，到底春风生意满。\n唤得应、雨和晴恰好，旗舞粳艘百万。\n更社鼠城狐扫影，雁鹜惊人避箭。\n最是满腹精神，担负处、浑身皆胆。\n又谁知、条理元在，规模里面。\n天下事、又何难办。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16561, '真珠帘', '陈著', '纶巾古貌尘寰表。\n风流处、别是英雄才调。\n胸次著乾坤，触景皆诗料。\n金碧楼台新筑就，傍翠麓、旋添花草。\n仙棹。\n更逍遥来访，十洲三岛。\n遮眼富贵人多，算如公有子，人间应少。\n看膝下功名，共月林清皎。\n象简绯袍亲侍策，且胜赏、先春独笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16562, '大', '陈著', '把雪冰心，钧韶手，飞上青云时早。\n红尘难染著，十年前曾坐，凤池鳌岛。\n晕锦锵环，重金压带，相去能争多少。\n从容何心问，到如今都领，绣春花草。\n算耐处光阴，淡中滋味，世人那晓。\n笺天新有稿。\n要归去、盘礴山阴道。\n便整顿、随琴霜鹤，带石秋兰，约松乔、倚风清啸。\n争奈俞音杳。\n明月棹、又还停了。\n但珍重、经纶料。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16563, '大', '陈著', '问大江东，长淮上，缘分如何修到。\n轻裘还熟局，第三番又是，五年春了。\n菜饭工夫，露香心事，惟靠天公分晓。\n林泉琴书梦，算飞笺觅去，不知多少。\n奈雅意难酬，又还留住，口衔新诏。\n都无他嗜好。\n玉麟静、公事供谈笑。\n满眼是、风花飘忽，惟有长松，雪霜里、插天苍老。\n休忆家山好。\n安乐处、便成蓬岛。\n正春雨、秧畴饱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16564, '大', '陈著', '自有乾坤，扶人极，宗主须还人物。\n今为何时节，满红尘富贵，絮花飘忽。\n抵障狂澜，提携正印，一柱天擎突兀。\n平生分明处，是从容处□，不差毫发。\n把朝市山林，一般看了，无边风月。\n深衣清到骨。\n紫枢府、谁信曾簪笏。\n炊脱粟、黄鸡白酒，补菊栽梅，碧溪绕、竹篱茅屋。\n无限轻描貌。\n都说道、诏书催发。\n想回首、招黄鹄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16565, '沁园春', '陈著', '潇洒书斋，香清缕直，灯冷晕圆。\n忽惊窗鸣瓦，霰如筛下，裁冰翦玉，片似花鲜。\n深怕妨梅，也愁折竹，才作还休亦偶然。\n更深也，漫题窗记瑞，诗思绵绵。\n闻君礼佛日千。\n浪说道繁华不值钱。\n想鸳衾底下，都将命乞，蒲龛里畔，未必心安。\n兜率天宫，清凉境界，总是由心不是缘。\n雪山上，自有人坐了，不到君边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16566, '沁园春', '陈著', '出禁城西，湖光自别，唤醒两瞳。\n有画桥几处，通人南北，绿堤十里，分水西东。\n问柳旗亭，簇山梵所，空翠烟飞半淡浓。\n偏奇处，看笙歌千舫，泛绮罗宫。\n从容。\n莫问城中。\n是则是繁华九市通。\n奈一番雨过，沾衣泥黑，三竿日上，扑面尘红。\n那壁喧器，这边清丽，咫尺中间不同。\n休归去，便舣舟荷外，梦月眠风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16567, '沁园春', '陈著', '潇洒纶巾，风流野服，红尘外身。\n向南窗听雨，澜翻墨客，北亭恋月，笔走诗神。\n倚竹听琴，逢花倒磕，更得放晴游冠春。\n清闲好，算东洲人物，难得如君。\n华堂瑞气如云。\n西风到帘帷才一分。\n喜星桥鹊语，佳传依旧，缑山鹤舞，仙样翻新。\n箫玉香中，烛花影里，听取捧觞低祝人。\n千千岁，看功名事业，都在儿孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16568, '沁园春', '陈著', '月旦评中，有如公者，更谁与俦。\n看纷纷仁意，春风和气，堂堂义事，砥柱中流。\n已重物轻，身穷道泰，却占人间第一筹。\n回头笑，彼纷纷名利，过影浮沤。\n夷犹。\n庭户清幽。\n算此境神仙别一洲。\n但烧香挂画，呼童扫地，对山揖水，共客登楼。\n付与儿孙，只将方寸，此外无求百不忧。\n宜多寿，自今开八帙，到八千秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16569, '沁园春', '陈著', '小枕屏儿，面儿素净，吾自爱之。\n向春晴欲晓，低斜半展，夜寒如水，屈曲深围。\n消得题诗，不须作画，潇洒风流未易涯。\n人间世，但此身安处，是十分奇。\n笑他富贵家儿。\n这长物何为著意□。\n便绮罗六扇，何如玉洁，丹青万状，都是钱痴。\n假托伊来，遮阑便了，免得惊风侵梦时。\n何须泥，要物常随我，不物之随。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16570, '沁园春', '陈著', '运在东南，温厚气锺，吾葺芷翁。\n羡檠窗学问，迂斋正印，玉堂词翰，攻愧流风。\n制胜枢庭，参谋政府，一片平心扶大中。\n黄扉近，却翻然东顾，归宴方蓬。\n潘舆日奉从容。\n全胜□貂蝉趋汉宫。\n如名山镇静，出云相望，大川蓄，有水皆宗。\n吾道胚，诸贤命脉，阴受春风和气浓。\n宜多寿，与瑶图同庆，绿竹歌公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16571, '沁园春', '陈著', '吾竹窗兄，吾能评者，只将竹看。\n是丹山佳气，胚茂直，嵩溪润脉，滋养清坚。\n雪虐霜凌，风饕雨恶，撼顿侵欺今几年。\n元无损，这虚心实节，却自依然。\n人间。\n输此君贤。\n可曾向红尘里著鞭。\n称翩翩侣凤，舞依翡翠，昂昂雏鹤，立倚琅。\n动处非情，静中自韵，全得生来潇洒天。\n须长在，在月窗窗北，石涧东边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16572, '沁园春', '陈著', '吾菊坡兄，细观花□，元来一般。\n是山佳气，胚长茂，鄞江润脉，滋养清妍。\n移傍云霄，浓沾雨露，曾亚百花头上班。\n谁知道，待芬香透了，收敛东边。\n笑他红紫纷然。\n算眼底何曾长久看。\n这秋芳自韵，不争春艳，霜根难老，偏耐风寒。\n占得清名，尊为寿客，晚节谁能如此全。\n千千岁，把黄金正色，照映人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16573, '水龙吟', '陈著', '玉麟堂上神仙，算来便合归廊庙。\n天教且住，堂堂裘带，舒舒旗纛。\n一笑谈中，遍江淮上，太平花草。\n待金瓯揭了，黄扉坐处，祗依此、规模好。\n恰似虹流节後，庆生申、佳期还到。\n乾坤开泰，君臣相遇，机缘恁巧。\n谁信苍生，举头凝望，锋车催召。\n向芜湖，更有无言桃李，顾春风早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16574, '水龙吟', '陈著', '玉鳌头上蓬莱，十分好处饶松壑。\n无边风月，阴阴乔木，重重华萼。\n秋水门庭，淡交簪履，随宜斟酌。\n向西风回首，双旌缥缈，从天下、招琴鹤。\n是则阳春有脚。\n被金华、洞天留著。\n相传好语，新来初见，分明鼓角。\n田里相安，裤襦歌了，却来持橐。\n称年年，橘绿橙黄时节，与松乔约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16575, '瑞鹤仙', '陈著', '云无心出岫。\n游戏间、声名掀揭宇宙。\n红尘事看透。\n任高官惟有，鹤随诗瘦。\n溪山如绣。\n小轩亭、新话旧。\n想时时，梦到家林，但未有归时候。\n知否。\n分明世界，多少经纶，莫轻回首。\n平生抱负。\n金銮殿，有新奏。\n便相扶君相，从头做去，他又谁能出手。\n看明年、此日传宣，赐酴酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16576, '摸鱼儿', '陈著', '碧油幢、一开藩後，便思量早归去。\n工夫著紧新城好，风月万家笙鼓。\n游宴处。\n要管领春光，补种花无数。\n何须更驻。\n只画了潇湘，扁舟径发，挥手谢南楚。\n江帆卸、撑入清溪绿树。\n家山三两程路。\n安排小马随猿鹤，勾引诗朋酒侣。\n潇洒处。\n是则是初心，只恐难留驻。\n忙须著句。\n把泉石烟霞，平章一遍，回首凤纶舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16577, '洞仙歌', '陈著', '冰肌玉骨，自清凉无汗。\n云影翠山远。\n颤金莲缓步，手托珠帘，风微透，扇底荷花香满。\n归檐双飞燕，流盼消凝，微带羞红上娇面。\n又还黄昏近，一片闲情，天涯去、云也遮阑不断。\n回首处、沈思梦时曾，对十二屏山，怕拈秦阮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16578, '洞仙歌', '陈著', '冰肌玉骨，自清凉无汗，午梦醒来盼娇满。\n扇轻拈又放，浅炷兰薰，微笑处、吹著烟丝散乱。\n凉亭还独步，曾是凭阑，携手心盟指云汉。\n碧云斜阳外，信有如今，音书杳、寸肠千转。\n漫伫立、无言对荷花，看转眼秋风，翠移红换。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16579, '念奴娇', '陈著', '洛阳地脉，是谁人、缩到海涯天角。\n绿树成阴芳雾底，得见当年台阁。\n园杏贵客，海棠姬侍，拥入青油幕。\n人间那有，风流天上标格。\n如困如懒如羞，夜来应梦入，西瑶仙宅。\n为你闲风轻过去，□□不教妨却。\n娇不能行，笑还无语，惟把香狼藉。\n花花听取，年年无负春约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16580, '念奴娇', '陈著', '轻衫短旆，几年来、游遍江南江北。\n扰扰浮生争富贵，金碧楼台满目。\n厦屋千间，夜床八尺，此理谁能烛。\n翩然归去，家山是事都足。\n笑指旧隐逍遥，分猿鹤地，云顶栽花竹。\n乘兴生涯随处好，卜市心□新筑。\n山色窥帘，杏阴依户，门外从尘俗。\n朱颜雪鬓，清闲十二分福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16581, '念奴娇', '陈著', '暑天向晚，最相宜、一簇凉生新竹。\n潇洒轩窗还此景，此景真非凡俗。\n猿鹤相随，烟霞自在，与我交情熟。\n人生如梦，个中堪把心卜。\n休叹乌兔如飞，功名富贵，有分终须足。\n不管他非非是是，不管他荣和辱。\n净几明窗，残编断简，且恁闲劳碌。\n流萤过去，文章如在吾目。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16582, '念奴娇', '陈著', '紧头上立，问如何、犹向清溪盘礴。\n应为春防须熟局，且借轻裘弹压。\n野聚晴炊，烟波暖唱，尽出江南北。\n从容归衮，三年功满棋柝。\n真个福比南山，谁无富贵，无此团乐。\n锦瑟瑶琴清对处，青紫诸郎参错。\n楚楚孙枝，温温婿玉，帘幕欢声拍。\n抠衣小子，寿公也趁龟鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16583, '满江红', '陈著', '落枕鸿声，龙山梦、蓦然惊觉。\n还堪喜、木樨香底，鹊声翻晓。\n弄雨未成霜意懒，望寒先怯山容老。\n最难逢、无一点西风，惊乌帽。\n竹叶酒，倾杯小。\n橙齑，银盆好。\n称良辰欢宴，及今年少。\n须信从来黄菊寿，未应便放青霜恼。\n但看花、日日是重阳，金尊倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16584, '满江红', '陈著', '越水稽山，清明气、锺为人极。\n缨早、□中学问，从头施设。\n不受尘来霜壁立，常生意处春流活。\n与世间、别是一规模，师夔契。\n仙岛上，分风月。\n苍梧下，怀冰雪。\n更双亲犹是，朱颜时节。\n熏业要从青鬓上，乾坤如许丹山折。\n看凤衔、芝诏下层霄，朝金阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16585, '满江红', '陈著', '修茂堂深，芳尘满、沈烟一朵。\n帘半卷，好风催晓，晴光才破。\n新润顿教萱草鬯，轻寒未放酴过。\n称鱼轩、容与寿如山，群仙贺。\n琴帏底，声调和。\n庭阶下，儿孙大。\n喜新来咿喔，又还添个。\n总是人生如意处，休将时事关眉锁。\n趁莺花、时节绮罗筵，年年作。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16586, '烛影摇红', '陈著', '风月堂中，画屏不动香猊吐。\n珠翘环拥蕊宫仙，双鬓青如许。\n相对童颜寿侣。\n看庭前、绯袍拜舞。\n十洲三岛，柳探春时，梅欺雪处。\n甲子花周，自从今日重新数。\n碧瑶杯重翠涛深，笑领飞琼语。\n此去华筵喜聚。\n听传宣、云间紫府。\n万分如意，凤诏便蕃，香轩容与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16587, '水调歌头', '陈著', '风骨最魁岸，宇宙更宽平。\n□人皆道，天上南极寿星精。\n随意後园花木，满眼家山松竹，尽可适平生。\n门外底须问，好占菊轩清。\n听乡评，义方训，莫如兄。\n元方既玉就□，更要季方成。\n不使尘劳顿挫，他日功名入手，当不负椿庭。\n不见窦谏议，教子有馀荣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16588, '水调歌头', '陈著', '身到紫枢府，一蹴凤池间。\n何妨到头富贵，却自恋家山。\n多少名缰利锁，尘满霜髯雪鬓，役役不知还。\n桃李竞春事，坡菊自清闲。\n绿杨边，门径小，似僧关。\n吟情饮兴相将，二十载优闲。\n无限功名事业，分付儿孙纵靶，青镜尽朱颜。\n一语劝公酒，天下达尊三。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16589, '千秋岁', '陈著', '燕前莺底。\n一日春犹在。\n香雾晓，祥云霁。\n烟交槐影重，风约花尘卸。\n当此际。\n桃源不是人间世。\n彩袖环庭砌。\n华裾纷珂佩。\n欢声洽，童颜醉。\n金丹功已到，绿发生须再。\n箫鼓沸。\n飞琼来祝千千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16590, '踏莎行', '陈著', '杏苑长春，椿姿耐老。\n画堂琴幌融融调。\n生涯分付宁馨儿，西园手种闲花草。\n露浴明河，风浮素颢。\n桂花著蕊今年早。\n佳占端的在孙枝，明年寿席呕笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16591, '鹊桥仙', '陈著', '云南锺秀，间生人望。\n底事未成美况。\n当知大器大成时，更莫叹、贤关难上。\n前程分定，算来无妄。\n命达时终不放。\n且须寄语甲科人，断不下、一筹中榜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16592, '一翦梅', '陈著', '记得儿时识景年。\n翕忽光阴，二十馀年。\n梅边聚首又三年。\n结得因缘。\n五百来年。\n把酒君前欲问年。\n笑指松椿，当是同年。\n愿从今後八千年。\n长似今年。\n长似今年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16593, '惜分飞', '陈著', '筑垒愁城书一纸。\n雁雁儿将不起。\n好去西风里。\n到家分付眉颦底。\n落日阑干羞独倚。\n十里江山万里。\n容易成憔悴。\n惟归来是归来是。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16594, '西江月', '陈著', '宝瑟屏金深深处，斑衣箫玉香中。\n人生二美古难逢。\n杏苑今朝喜共。\n一霎豆花新雨，半帘梧叶清风。\n年年此景绿尊同。\n笑指南山称颂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16595, '西江月', '陈著', '箫玉和鸣云里，彩衣娱舞风前。\n好从龟鹤问长年。\n看取蟠桃结遍。\n事业都随今定，儿孙也靠心传。\n隐耕窗下腹便便。\n相去神仙不远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16596, '西江月', '陈著', '当此朱炎火日，恨无玉骨冰肌。\n问来思欲动凉。\n宝荷君相遗。\n如铁又添颜甲，报琼难续声诗。\n愿言长在奉扬时。\n似恁团到底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16597, '小重山', '陈著', '松是交朋竹是邻。\n横枝临水瘦，月黄昏。\n冲寒香入岭头云。\n清到底，人共一般清。\n好句更无痕。\n门前无俗客，不须扃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16598, '柳梢青', '陈著', '淡淡新妆，盈盈娇态，谁道荷花。\n料想香肌，不禁畏日，翠盖儿遮。\n我来胜赏高歌。\n故敛著、芳心为何。\n莫是伊花，恨余来晚，欲媚晨霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16599, '柳梢青', '陈著', '缥缈瑶城。\n客情春小，本分寒轻。\n霞佩云裾，步联西母，笑倚飞琼。\n那堪四美都并。\n喜气与、祥云共生。\n自在风流，融融箫玉，楚楚兰馨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16600, '霜天晓角', '陈著', '江寒雁咽。\n短棹还催发。\n曾是玉堂仙伯，相别处、满篷雪。\n此别。\n那堪说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16601, '卜算子', '陈著', '一自梦卢头，应学乘裴蹇。\n元是都门向上人，大用何嫌晚。\n三岁事非遥，三捷功非远。\n管取微生共此荣，联步云程稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16602, '卜算子', '陈著', '雨逗一分寒，未放晴光透。\n绮席春风十分，畅饮长春酒。\n花气渐薰帘，佳致归诗手。\n的是诗中陆地仙，左挹浮丘袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16603, '卜算子', '陈著', '风急雁声高，露冷蛩吟切。\n枕剩衾寒不耐烦，长是伤离别。\n望得眼儿穿，巴得心头热。\n且喜重阳节又来，黄菊花先发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16604, '减字木兰花', '陈著', '浮萍踪迹。\n又作南东□□客。\n不奈秋阳。\n一似朱明赫赫光。\n惊雷叱雨。\n料是阿香怜逆旅。\n好个凉天。\n称我前程步步便。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16605, '减字木兰花', '陈著', '夜帆初上。\n准拟今朝过越上。\n及到今朝。\n却被西风挫一潮。\n丈亭一处。\n要得纵观赢得住。\n行止皆天。\n谁道人生客路难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16606, '如梦令', '陈著', '家在明山南住。\n身在明山西路。\n回首碧云端，自笑不如飞鹜。\n飞去。\n飞去。\n飞入明山深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16607, '如梦令', '陈著', '晚泊江湾平处。\n楚楚苹花自舞。\n风翦雨丝轻，江上潮生船去。\n看取。\n看取。\n湿橹不惊鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16608, '捣练子', '陈著', '花影乱，晓窗明。\n莺弄春笙柳外声。\n和梦卷帘飞絮入，牡丹无语正盈盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16609, '鹧鸪天', '陈著', '看了山中薜荔衣。\n手将安石种分移。\n花鲜绚日猩红妒，叶密乘风翠羽飞。\n新结子，绿垂枝。\n老来眼底转多宜。\n牙齿不入甜时样，醋醋何妨荐酒卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16610, '念奴娇', '陈著', '翠云弄晓，芰荷香、微透凉帘箔。\n彩袂蹁跹欢舞处，勾引衔桃双鹤。\n骤马风前，奔鲸浪里，独有壶天乐。\n如何不醉，放教杯量宽著。\n消得寿八千春，百分才一，更童颜如渥。\n听取飞琼含笑道，堪学孩儿书额。\n令骖凫，瑶仙跨凤，喜聚家人醵。\n心香遥上，也随风过蓬弱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16611, '摸鱼儿', '陈著', '竹洲西、有人如玉，南柯一觉归早。\n青山绿水亭轩旧，犹有未荒花草。\n谁信道。\n又自爱湖光，买屋三间小。\n都无长好。\n但凤跃雄文，蝇书小楷，转老转奇妙。\n人间世，如许年高是少。\n浮生惟有闲好。\n回头翻讶溪叟，轻把一丝抛了。\n凉新到。\n记当日天香，露浴如今老。\n瑶卮寿晓。\n称酒到眉间，醺醺醉也，儿女满前笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16612, '庆春泽', '陈著', '翔凤阑干，啼鹃院宇，相逢似梦才醒。\n谁道无情，飞红舞翠欢迎。\n青春绿发花前饮，醉自歌、记那时曾。\n到如今，心事凄凉，怕说芳盟。\n追思艮岳归来後，稳依山护得，雨翮风翎。\n燕燕莺莺，从他巧舌饶声。\n翩翩一种天然艳，笑向人、不与春争。\n羡花花，好岁寒交，有卧云亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16613, '庆春泽', '陈著', '春困时光，风流昨梦，逢花便自醒醒。\n回首宣和，宫莺掖燕相迎。\n归来只恋春山好，到上林、枉是亲曾。\n又谁知，自有蟠松，相与论盟。\n阑干可是妨飞去，怕惊尘却，翠羽红翎。\n舞态亭亭，浑疑暗折韶声。\n人眼处还看破，道凤来、难与真争。\n醉扶归，但见啼鹃，怨夕阳亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16614, '水龙吟', '陈著', '蓬莱风月神仙，却来平地为霖雨。\n乾坤清了，如今多是，退行一步。\n寸寸归心，轻轩娱侍，竹溪花圃。\n奈君王眷眷，苍生恋恋，那肯放、钱塘渡。\n天也知公此意，问升平、要抽身去。\n把些夏潦，和些秋哨，轻轻缀住。\n一转移来，元勋力量，他谁堪付。\n待汾阳、了却中书，别又商量出处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16615, '真珠帘', '陈著', '鱼轩富贵人间少。\n那堪更、有子雍容廊庙。\n衮绣当斑衣，转色难心小。\n手把乾坤重整顿，略□□、微生一笑。\n分晓。\n是慈闱心事，如今著到。\n帘幕早是寒生，又橙黄近也，菊花香了。\n已劝九霞觞，春意浓於酒。\n玉带金鱼欢舞处，更捷骑、红尘峡□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16616, '宝鼎现', '陈著', '著林仙叟，梦境炊得，才香还觉。\n回首渺，觚棱何处，云与商量浮计小。\n矮矮屋、半弓来闲地，也著三花两草。\n沸眼底、鞭风笠雨，不满茶边一笑。\n寿骨奇耸神清峭。\n散人装、游戏尘表。\n帘昼永、长留雅伴，吟唾宽飞潇洒料。\n最好是、瑟和琴同调，眉里相看耐老。\n更绿草、孙枝可意，谱得家传较早。\n争指画额儿儿，欢祝处、荷薰吹晓。\n记兰汤初试，当日风光又到。\n拚醵饮、任金尊倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16617, '宝鼎现', '陈著', '问今何日，旧也曾尾，东风鹭。\n回首念，家山桃李，归去来兮闻早赋。\n梦境里、尽何妨疏散，时趁莺晴信步。\n是则是、清闲自好，一点心犹怀古。\n记得平世痴儿女。\n自灯宵、游了三五。\n还次第、湖边去也，寒食清明炊未住。\n是处处、是丹青图画，随意狂歌醉舞。\n奈蓦被、烟花浪手，一掷残阳孤注。\n须信乐极悲来，谁道是、曾歌琼树。\n夕阳亭遗，翻得江涛似许。\n忍望著、□天津路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16618, '真珠帘', '陈著', '如梅在壑清标格。\n襟怀好、又是融融春拍。\n鸳梦早惊飞，惯一窗岑寂。\n谱曲裁诗心自在，任雪月、风花需索。\n奇特。\n问生涯却道，浮云如得。\n回首门外黄尘，算何如、稳占溪光山色。\n八百岁为期，却十分才一。\n弟自高歌儿自舞，簇小小、榴花筵席。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16619, '真珠帘', '陈著', '青云玉树南薰扇。\n京华地、别是潇湘图展。\n茉莉芰荷香，拍满笙箫院。\n雪藕盈盈歌袅处，早已带、秋声凄怨。\n堪叹。\n把时光轻靠，冰山一片。\n从古幻境如轮，问铜驼、应是多番曾见。\n谁把笛吹凉，总是腔新换。\n水枕风船空入梦，但极目、波流云远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16620, '真珠帘', '陈著', '闲居是念随云散。\n琴帘底、却自平生心满。\n百二十年期，笑道今才半。\n一味齑盐清得瘦，婉娩似、梅花香晚。\n相伴。\n老霜松宁耐，溪山寒惯。\n探借十日前春，小杯盘、也做寿筵模范。\n绕膝舞斑衣，有酒从他劝。\n但任真来浑是处，梦不到、笙歌瑶燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16621, '金盏子', '陈著', '眼底时光，奈老来、如何奈得秋何。\n黄叶最多情，天分付、凉意一声先做。\n是处著露莎蛩，也酸吟相和。\n新雁想，飞到故都徘徊，未忍轻过。\n往事是堪唾。\n红枣信、烽折尽任他。\n湖山桂香自好，笙歌舫、沈沈醉也谁拖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16622, '玉漏迟', '陈著', '故都冬亦好。\n风光可是，人间曾有。\n问雪楼台，肉阵不教寒透。\n妙手搀春弄巧，唤得应、千花如绣。\n灯市酒。\n笙歌镇似，元宵时候。\n见说是事都新，但破冻潮声，去来依旧。\n老梦无情，不到六桥风柳。\n回首孤山好景，倩人问、梅花安否。\n应自瘦。\n雪霜可能。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16623, '沁园春', '陈著', '天盖西倾，地轴东翻，两年以来。\n那关中形势，已归勃勃，江南人马，都是回回。\n咄咄书空，栖栖问路，岁晚山空风雪催。\n如何得，与浑家踏遍，雪顶岩隈。\n谁知有客敲推。\n把世变心烦都说开。\n道严霜不杀，不成葭苇，冱寒惯耐，方是松梅。\n万事过前，一场梦里，分付茅柴三两杯。\n犹痴望，有太平时节，游戏春台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16624, '沁园春', '陈著', '旗盖运迁，衣冠事乖，岂非命来。\n自黄粱枕觉，分明看破，翠蓬舟近，及早抽回。\n谁料山深，也同鼎沸，步步危机忙里催。\n愁无奈，过青山万叠，碧水千隈。\n此愁何计能推。\n算何日天教眉锁开。\n记六桥花舫，晴边访柳，孤山草酌，雪後评梅。\n回首西湖，伤心前事，覆水如何收上杯。\n东风好，问如今吹入，谁处楼台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16625, '沁园春', '陈著', '人生功名，在醉梦中，早须掉头。\n自南宫一券，尘泥偶脱，前程双毂，日月如流。\n蕙帐真盟，菜羹馀味，江上归舟谁得留。\n谁知道，有邵平瓜圃，何日封侯。\n天天又不人由。\n奈危世山林也有忧。\n况青岗不助，晋家风鹤，黑云直卷，吴分星牛。\n分寸残生，万千魔障，他事如今都罢休。\n关心处，是离离禾黍，故国宗周。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16626, '沁园春', '陈著', '无价韶华，一笑相酬，青钱似苔。\n奈东风轻劣，催红雨去，西园次第，放绿阴回。\n老後时光，眉间心事，恰似怕酸人著梅。\n须知道，有谁能百岁，日日开怀。\n从教世变轮推。\n也莫问人间春去来。\n看渊明归了，有形谁役，少陵醉里，无闷堪排。\n贫贼何妨，风流自别，不是沈沈浊世杯。\n层霄上，与大鹏盘礴，下视浮埃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16627, '沁园春', '陈著', '人生几何，如何不自，珍重此生。\n向蠹残字上，甘心抛掷，蜗尖争处，著意丁宁。\n箭过时光，剑炊世界，谁带经锄谁笔耕。\n分明似，满一锅汤沸，无处清□。\n输兄。\n练得闲成。\n□无辱无忧惧惊。\n但菜羹粝饭，不求他味，芒鞋竹杖，足畅幽情。\n八十年来，万千看破，胸次春风秋月明。\n梅花帐，称困眠醒起，无打门声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16628, '沁园春', '陈著', '信书成痴，捱到如今，无生可谋。\n奈浑家梦饭，谷难虚贷，长年断肉，菜亦悭搜。\n风雨潇潇，江山落落，死又还生春复秋。\n八十岁，是这般多活，堪吊堪羞。\n休休。\n盍自回头。\n要铁汉须从穷处求。\n那袁安闭户，恬然僵卧，少陵任妇，长是贫愁。\n一等清风，千年佳话，蚁蚋看他金谷楼。\n是是是，笑出门天阔，一片云浮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16629, '水龙吟', '陈著', '好花天也多悭，放迟留做残春主。\n丰肌弱骨，晴娇无奈，新妆相妒。\n翠幕高张，玉阑低护，怕惊风雨。\n记年时、多少诗朋酒伴，逢花醉、簪花舞。\n那料无情光景，到如今、水流云去。\n残枝剩叶，依依如梦，不堪相觑。\n心事谁知，杜鹃饶舌，自能分诉。\n日西斜，烟草凄凄，望断洛阳何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16630, '水龙吟', '陈著', '百花开遍园林，又春归也谁为主。\n深黄浅紫，娇红腻白，他谁能妒。\n似不胜情，醉归花月，梦回云雨。\n又丰肌、恰被东风摇动，盈盈底、霓裳舞。\n世事纷纷无据。\n与杨花、飞来飞去。\n当年斗大，知他多少，蜂窥蝶觑。\n金谷春移，玉华人散，此愁难诉。\n漫寻思，承诏沈香亭上，倚阑干处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16631, '水龙吟', '陈著', '杜鹃啼正忙时，半风半雨春悭霁。\n酴未过，樱甜初熟，梅酸微试。\n一种红芳，九苞真色，舞窗翻砌。\n自仙樊去後，无人题凤，阑干外、成孤媚。\n谁信阳春妙手，锦云机、新番裁制。\n东君冷看，如何描摸，天然艳美。\n浑欲乘风，又如羞日，做双飞体。\n伫骖鸾，称得花前弄玉，与吟箫婿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16632, '瑞鹤仙', '陈著', '对南山翠峭。\n几百年、银青门第转好。\n梅花弄春小。\n向重帘暖处，华筵开早。\n斑衣簇绕。\n舞香云、哄堂颂祷。\n稳生涯、都自心田，自有老天堪靠。\n应道。\n□□□□，乐事难逢，可轻过了。\n鲈肥蟹健，桑落酒、酿来妙。\n称瑶卮争劝，襟宽放，一点尘嚣不到。\n但从今、家庆年年，醉乡里笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16633, '洞仙歌', '陈著', '清溪带竹，竹外山光抱。\n新筑浑如图画了。\n称闲心、管领昨夜天风，吹送□，端的琅音恰到。\n谁知青云上，鸾凤翱翔，曾把功名试多少。\n到如今梦觉，佩著飞霞，浑家问、玉芝瑶草。\n试冷看、重门外如何，恁得似，壶中羽衣尘表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16634, '贺新郎', '陈著', '北马飞江过。\n画图中、花城柳郭，万摧千挫。\n羌管直惊猿鹤梦，愁得千山翠锁。\n有多少、风餐雨卧。\n回首西湖空溅泪，醉沈沈、轻掷金瓯破。\n平地浪，如何。\n君家志气从来大。\n舞蓝袍、牵丝幕外，肯饶他个。\n谁料腥埃妨阔步，孤瘦依然故我。\n待天有情时须可。\n且占雪溪清绝处，看精神、全是梅花做。\n嫌暖饱，耐寒饿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16635, '念奴娇', '陈著', '晓村深处，记当年、轻被东风吹别。\n重得相看春雨屋，心事从头细说。\n深院灯寒，流苏帐暖，曾梦梅花月。\n如今何在，消凝分付啼。\n亭馆飞入腥烟，残香惟有，数朵酴雪。\n旧燕寻巢来又去，也觉双飞声咽。\n泛梗生涯，空花世界，且做杯中活。\n可人兰玉，风光还有时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16636, '念奴娇', '陈著', '百年光景，算山中、多占人间分数。\n一片清风梅是主，弹压粗花俗树。\n小小鱼池，深深莺谷，曲曲香云路。\n堪诗堪画，是天分付闲处。\n闻要跨鹤西游，家林自好，且何妨留驻。\n趁取酴新煮酒，烧笋煎花为具。\n万事皆空，千金一刻，底用闲愁苦。\n无情杜宇，笑他催我归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16637, '念奴娇', '陈著', '雨帘高卷，见榴花、应怪风流人老。\n是则年年佳节在，无奈闲心悄悄。\n巧扇风轻，香罗雪湿，梦里曾看了。\n如今溪上，欢盟分付年少。\n偏是眉好相宜，呼儿扶著，把菖蒲迎笑。\n说道浮生饶百岁，能有时光多少。\n幸自清贫，何妨乐趣，谱入瑶琴调。\n杯杯酒满，这般滋味谁晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16638, '绮罗香', '陈著', '障暑稠阴，梳凉细缕，□□□□□□。\n露腋玲珑，多少闹中幽趣。\n断又续、可是无情，□相送、短长亭路。\n记春风、曾著莺啼，便娇那得袅如许。\n知音人自暗省，凝睇青云影里，黄昏犹伫。\n一部笙，消得翠腰供舞。\n堪对景、翻入新妆，鬓影低、衬教眉妩。\n试回头、旧日章台，怕听声咽处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16639, '绮罗香', '陈著', '袅入风腔，清含露脉，声在丝丝烟碧。\n破暑吹凉，天付弄娇双腋。\n似恋恋、舞翠纤腰，断还续、忍相离拆。\n最欢时、微雨初晴，夕阳犹湿淡云隔。\n新来多少怆感，心怕无情过马，攀条惊著。\n梦里妆台，休说听来曾昨。\n凝伫漫、番节笙音，暗自将、玉阑轻拍。\n问谁能、唤起陶潜，醉翁同赋却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16640, '绮罗香', '陈著', '霁晓楼台，斜阳渡口，凉腋新声初到。\n占断清阴，随意自成宫调。\n看取次、颤引薰风，想无奈、露餐清饱。\n有时如、柔袅丝，忽如笙咽转娇妙。\n谁知忧怨极处，轻把宫妆蜕了，飞吟枝杪。\n耳畔如今，凄感又添多少。\n愁绪正、萦绕妆台，怎更禁、被他相恼。\n送残音、立尽黄昏，月明深院悄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16641, '满江红', '陈著', '梦里京华，忽听得、庭花遗曲。\n到醒来、愁满东风山屋。\n春事已非空结绮，晓班无分随群玉。\n想天涯、沦落杜秋娘，攒眉绿。\n谁能顾，荒芜菊。\n谁能问，平安竹。\n任时光流转，都成虚辱。\n无可奈何天地隘，只饶走得溪山足。\n但逢人、相问麦青青，何时熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16642, '烛影摇红', '陈著', '吾菊山翁，鹤骖来自蓬云界。\n平铺心地有天知，楚楚生兰。\n膝下青衫舞拜。\n更参差、斑衣戏队。\n清闲无事，门外从他，惊尘飞隘。\n寿八千年，百分才一朱颜耐。\n何妨长主翠嵩春，酒约诗盟在。\n家庆堂前欢会。\n领霞卮、醺红浅带。\n是人说道，真吕先生，风流潇洒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16643, '烛影摇红', '陈著', '潇洒琴帘，月灯归後新谐好。\n青云香里共清风，消得金花诰。\n争奈天颠地倒。\n好光阴、都惊散了。\n更听人说，七七年时，多多烦恼。\n捱到如今，信知空挂闲怀抱。\n天於负处最饶人，颦也翻成笑。\n牢闭柴门自好。\n对梅花、杯盘草草。\n满前儿女，耐後夫妻，齑盐偕老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16644, '烛影摇红', '陈著', '双杏堂深，山明水秀潆洄著。\n稳铺心事做平生，不买颦眉错。\n是则苍髯白发。\n笑微微、朱颜自渥。\n一团春意，半隐风流，他谁能学。\n六十年华，又从今起新花甲。\n葵榴初艳芰荷香，争赴开筵约。\n家庆真堪恣乐。\n碧瑶杯、须拚满酌。\n瑟琴声里，弟劝兄酬，儿歌孙拍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16645, '声声慢', '陈著', '珍丛凤舞，曾是宣和，春风送归禁幄。\n翠浅红深，婉娩步空金落。\n腥尘未飞动处，是先知、早辞华萼。\n好在□，四并难多少，怨怀无托。\n猛拍阑干谁会，浮世事、悠悠白云黄鹤。\n有酒当花，休得是今非昨。\n花犹百年宁耐，算人生、能几欢乐。\n又忽忽，醉梦里、春去不觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16646, '祝英台近', '陈著', '小盆池，新压藕，翠盖已擎雨。\n巧弄红妆，明艳便能许。\n自怜华发萧萧，风流无分，醉时眼、何妨偷觑。\n黯然伫。\n回首今是何时，逢花笑还语。\n梦里西湖，双落泪如缕。\n斜阳十里烟芜，六桥风浪，有谁掉、采莲舟去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16647, '江城子', '陈著', '中秋佳月最端圆。\n老痴顽。\n见多番。\n杯酒相延，今夕不应悭。\n残雨如何妨乐事，声淅淅，点斑斑。\n天应有意故遮阑。\n拍人间。\n等闲看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16648, '江城子', '陈著', '人生难满百年心。\n得分阴。\n胜千金。\n吹帽风流，时节又相寻。\n回首赐萸休说梦，真率具，自山林。\n逢迎一笑且开襟。\n酒频斟。\n量犹禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16649, '江城子', '陈著', '纷纷都说会双星。\n鹊桥成。\n凤骖迎。\n风雨凄凉，何故锁苍冥。\n儿女空愁谁解意，须道我，试来听。\n人间天上不同情。\n最无凭。\n是柔盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16650, '江城子', '陈著', '笼街弹压上元灯。\n满瑶城。\n簇珠星。\n老矣如今，谁记旧来曾。\n眼底相逢惟有月，空对面，若为情。\n残生消不尽齑茎。\n瘦棱棱。\n困腾腾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16651, '江城子', '陈著', '年年端午又今朝。\n鬓萧萧。\n思摇摇。\n应是南风，湘浦正波涛。\n千古独醒魂在否，无处问，有谁招。\n何人帘幕倚兰皋。\n看飞桡。\n夺高标。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16652, '青玉案', '陈著', '钱塘江上潮来去。\n花落花开六桥路。\n三竺三茅钟晓暮。\n当年梦境，如今故国，不忍回头处。\n他谁做得愁如许。\n平地波涛挟风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16653, '青玉案', '陈著', '青山流水迢迢去。\n总是东风往回路。\n送得春来春又暮。\n莺如何诉。\n燕如何语。\n只有春知处。\n时光渐渐春如许。\n何用怜春怕红雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16654, '渔家傲', '陈著', '浪麦风微花雾扫。\n痕沙水浅溪桥小。\n属玉双双飞杳杳。\n山宽绕。\n新晴绣得春分晓。\n独立无言心事渺。\n曾将宇宙思量了。\n世变何涯人已老。\n休烦恼。\n林泉况味终须好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16655, '渔家傲', '陈著', '山弄夕辉眉淡扫。\n溪分新水支流小。\n醉梦风光凝望杳。\n云树绕。\n杜鹃怨处谁能晓。\n浮世悠悠波渺渺。\n蜗争何事何时了。\n天为无情方不老。\n休苦恼。\n随缘诗酒清闲好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16656, '踏莎行', '陈著', '豆雨空晴，桂花风静。\n碧虚飞上圆明镜。\n谁能唤起秃翁吟，祗应笑得嫦娥醒。\n可奈良宵，不堪残境。\n强拚一醉偷光景。\n夜凉渐搅雪霜心，昏眵犹认山河影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16657, '卖花声', '陈著', '残梦腾腾。\n好鸟一声呼醒。\n小窗明、萧萧鬓影。\n当年头上，惯曾簪幡胜。\n到如今、有谁怀省。\n东风著面，却自依然相认。\n哄痴儿、声弄景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16658, '鹊桥仙', '陈著', '兄年八十，弟今年几，亦是七旬有九。\n人生取数已为多，更休问、前程无有。\n家贫是苦，算来又好，见得平生操守。\n杯茶盏水也风流，莫负了、桂时菊候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16659, '蝶恋花', '陈著', '世变无情风挟雨。\n长夜漫漫，何日开晴午。\n白发萧疏惊岁序。\n儿嬉漫说重重午。\n粒啄偷生如搏黍。\n过计何须，负郭多南亩。\n曾著宫衣沾雨露。\n如今掩袂悲湘浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16660, '虞美人', '陈著', '故园处处都荒雨。\n寂寞蜗书户。\n人间春事杏桃花。\n独有诗人依旧、菊为家。\n老来犹解高叉手。\n遥上花前寿。\n华颠无分插花枝。\n乞取霜根风月、送将归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16661, '浪淘沙', '陈著', '有约泛溪篷。\n游画图中。\n沙鸥引入翠重重。\n认取抱琴人住处，水浅山浓。\n一笑两衰翁。\n莫惜从容。\n瓮醅灰芋雪泥菘。\n直到梅花飞过也，桃李春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16662, '浪淘沙', '陈著', '记得去年时。\n采菊东篱。\n眉间一笑捧花枝。\n说道愿如花不老，交劝双卮。\n又是菊花期。\n客况谁知。\n便无风雨也凄凄。\n白发夫妻时节酒，堪几参差。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16663, '浪淘沙', '陈著', '窗影弄晴红。\n欢笑成丛。\n一声春困到衰翁。\n回首太平儿戏事，雨过云空。\n人世暗尘中。\n如梦方浓。\n也须留取自惺。\n试问若教都困了，谁管春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16664, '浪淘沙', '陈著', '迟饭甑炊红。\n青翦蔬丛。\n鸡声邻里狎田翁。\n兵後故人能有几，岁晚江空。\n谁信淡交中。\n依旧情浓。\n白头青眼转惺。\n相见莫教轻别去，负月孤风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16665, '浪淘沙', '陈著', '春事紫和红。\n蜂蝶争丛。\n消磨多少看花翁。\n不用借他炊黍枕，何梦非空。\n茅屋菜畦中。\n村瓮醅浓。\n醉时啼鸟唤惺。\n不道白头添一岁，舞月歌风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16666, '浪淘沙', '陈著', '年事夕阳红。\n霜满髯丛。\n摩挲苍藓石婆翁。\n能见几人曾百岁，一笑书空。\n回首棣华中。\n消得春浓。\n平生心事两惺。\n杖履相从须放密，山月溪风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16667, '糖多令・唐多令', '陈著', '雁阵晓来霜。\n鸦村夕照黄。\n满人间、风景凄凉。\n幸有菊窗堪一醉，争又滞、水云乡。\n沽酒也三行。\n邀风与较量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16668, '糖多令・唐多令', '陈著', '蟹熟晕橙霜。\n蛆浮染菊黄。\n淡交情、都没炎凉。\n说道白头难会面，留一日、醉中乡。\n世事与轮行。\n时光逐寸量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16669, '糖多令・唐多令', '陈著', '倦枕寄渔乡。\n篷低被怯霜。\n月窥人、多少思量。\n自是欲眠眠不稳，禁听得、雁声双。\n和梦早催行。\n归来梅竹窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16670, '行香子', '陈著', '吾辈么麽。\n休叹蹉跎。\n得闲时、且逐时过。\n人间名利，都是浮华。\n但退如进，失如得，少如多。\n谁信生来，从发尖磨。\n到如今、方见霜涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16671, '恋绣衾', '陈著', '梅窗归坐几岁寒。\n老生涯、寂寞自便。\n最喜得、双双健，与粗茶、淡饭结缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16672, '西江月', '陈著', '老去坐来睡重，病多吟得诗悭。\n有时忽自拍阑干。\n一点心随天远。\n柳絮飞从何处，莺声啼破空山。\n春风依旧满人间。\n不奈双颦闲管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16673, '西江月', '陈著', '华胄银青气脉，仙风斑白须眉。\n儿孙玉雪满庭帏。\n家庆人间难比。\n浮世事等云过，平生心有天知。\n举杯相约小春时。\n岁岁梅花里醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16674, '卜算子', '陈著', '月下百年缘，天上双星样。\n九秩齐开自是稀，清健那堪两。\n红叶景翻新，黄菊香宜晚。\n笑拥眉开祝寿声，满劝鸳鸯盏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16675, '卜算子', '陈著', '喜气满清门，庆集还新样。\n卜醉筵开意转浓，昨日今朝两。\n愧我一年多，见汝双欢晚。\n自觉人生此会稀，有酒宁论盏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16676, '南乡子', '陈著', '流景去难縻。\n浮世危如拍浪。\n才遇中秋聊对月，佳期。\n最怕晴明未可涯。\n人月本相依。\n果是今朝恰背违。\n孤负楼台多少醉，堪悲。\n何忍滂沱与毕离。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16677, '宝鼎现', '陈著', '望京门外，怕见催发，东风行马。\n清到底、冰壶满了，欲借留来无计也。\n祖劝酒、看依依情恋，都在眉尖眼下。\n任万户、诗旗曲帐，有笔应难描写。\n是则龟组随瓜卸。\n好规模、分付来者。\n才泛绿、依红小暇，移讲芹宫时促驾。\n又指点、秀宁城来脉，疏瀹春流似画。\n更巧为、溪山著句，留作千年佳话。\n最念一邑酸寒，风雨暗、真几成假。\n向纛牙交处，还得儒珍旧价。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16678, '沁园春', '陈著', '莲叶山前，戎帐宏开，轰然最称。\n羡铺心如水，肯教尘，为民乞雨，唤得天应。\n紫逻□锋，绿林扫影，夜户都开无犬声。\n三乡里，笑嬉嬉度日，歌舞清平。\n溪头载月舟□，□□帐花旗忍送行。\n算浮云自在，初无著相，薰风正好，却问归程。\n折柳依依，憩棠□□，□□□春无尽情。\n趋朝去，看青冥玉钺，金辔红缨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16679, '喜迁莺', '陈著', '南庐佳号。\n是自许孔明，经纶才调。\n对柳鸣琴，凭花制锦，小试一同谈笑。\n怎知画帘难驻，忽又星舆催召。\n但谶得、耀碑潭水月，交光相照。\n驿道。\n春正好。\n簇帐擎杯，听取殷勤祷。\n略松鲈，便膺芝凤，陵溯紫清津要。\n当家得时行志，回首旧封文庙。\n疏化雨，障狂澜不尽，生生芹藻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16680, '西江月', '陈著', '钱影何曾过眼，笔头那肯亏心。\n系门瘦马影沈沈。\n夜柝不惊春枕。\n一去轻如蕉梦，三乡都是棠阴。\n等闲换取印黄金。\n催上云程新任。\n（缺词文）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16681, '水龙吟', '陈著', '（缺词文）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16682, '谒金门', '赵与', '归去去。\n风急兰舟不住。\n梦里海棠花下语。\n醒来无觅处。\n薄幸心情似絮。\n长是轻分轻聚。\n待得来时春几许。\n绿阴三月暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16683, '千年调', '王义山', '胜地独湖山，满堂贮风月。\n歌舞大平气象，雪回云遏。\n红鞋朱帽，隔岸唤船，芙蓉万叠。\n人稀到，这清绝。\n因思旧事，庄敞平泉宅。\n莫与他人树石，对儿孙说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16684, '水调歌头', '王义山', '沆瀣金茎露，清洁玉壶冰。\n分明昨夜，光见南极老人星。\n山甫秀锺崧岳，传说上符箕尾，造物为时生。\n一代词科伯，飞上到蓬瀛。\n紫薇天，丹禁地，掌丝纶。\n盘洲益国，个样人物只三人。\n辞却翰林风月，故就湖湘霖雨，天下共为春，试看玉堂□，太半秉洪钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16685, '临江仙', '王义山', '明日中元生上相，真上相上元生。\n满城灯火昼三更。\n台星呈瑞处，一点寿星明。\n和气薰蒸开泰运，湖山万里光荣。\n愿推天地发生仁。\n八荒开寿域，一气转洪钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16686, '满庭芳', '王义山', '线柳迎风，锦棠媚日，十分春色豪奢。\n青烟宫烛，飞入侍臣家。\n瑞霭深笼画戟，寿星照、曲纛高牙。\n因知是、崧高华旦，玳宴醉琼花。\n翻鸦。\n新诏墨，闻枢庭召入，已办宣麻。\n比汾阳福寿，公更穹华。\n伫看稠青叠紫，书香蔼、桂子兰芽。\n鸣珂处，西湖路上，接武筑堤沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16687, '水调歌头', '王义山', '宇宙邮亭耳，游子问舟归。\n滩上滩下，转柁欲速□□迟。\n安得泛河一叶，寻见江南归处，多只是旬馀。\n此身无地著，惊浪湿征衣。\n独张翰，见风起，早知机。\n谁把乘舟，偏重良策济明时。\n夷岛人烟相接，恰在永嘉上浦，猛忆浩然诗。\n乡闾万馀里，失路一相悲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16688, '贺新郎', '王义山', '雅有登山癖。\n觉老来、尚可跻攀，浪游蹑屐。\n险怪称雁荡，争秀群山第一。\n更耸出、穹崖千尺。\n景物深藏长谷里，最上龛，水凿时冲激。\n处，巨□石。\n地生天作谁能识。\n睹江山如故，恨无一时人物。\n灵运当年为太守，佳处都曾游历。\n独不见、此山脚迹。\n风月直须人管领，怎不移、石壁题岩壁。\n今且著，老夫笔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16689, '念奴娇', '王义山', '南昌奇观，最东湖、好景重重叠叠。\n谁瞰湖光新佳阁，横挹翠峰。\n十里芙蓉，海神捧出，一镜何明彻。\n鸢鱼飞跃，活机触处泼泼。\n容斋巨笔如椽，迎来一记，赢得芳名独。\n猛忆泛莲前日事，诗社杯盘频设。\n倚看斜阳，檐头燕子，如把兴亡说。\n谁迎谁送，一川无限风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16690, '瑞龙吟', '王义山', '晨光曙。\n遥见□灼文奎，照天心处。\n峨眉棱上西飞，北魁南极，腾辉灿丽。\n神皋地。\n争看碧幢旗戟，蔼然佳气。\n深深有美堂中，绣帏□幕，笙歌不住。\n知是元戎初度，玉觥频举，云堤烟市。\n时听笑声，都人相贺相语。\n人人说是，活佛生今世。\n襟怀内、严霜莹月，春风秋水。\n文肃貂蝉贵。\n南丰学问，文昭节义。\n若问庄椿岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16691, '贺新郎', '王义山', '自笑斟。\n作皤然一老，逍遥东湖湖曲。\n好事爆然来子舍，报道生孙新浴。\n算天也、从人所欲。\n万事足虽缘有子，见孙时、万事方为足。\n诗礼脉，今有续。\n吾家本是山阴族。\n见生来、风神稍秀，足娱吾目。\n吾子吾孙同此月，日月才争五六。\n喜听得、欢声满目。\n愚鲁聪明天所赋，只无灾无难为多福。\n且愿汝，书勤读。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16692, '乐语', '王义山', '金阙深深，正夏日初长禁柳青。\n祥烟纷簇，红云一朵，飞度彤庭。\n千妃随步处，觉薰风、微拂觚棱。\n天颜喜，向东朝长乐，献九霞觥。\n分明。\n西王母，来从光碧驾飞。\n为言今日，金仙新浴，共庆长生。\n捧桃上寿，天一笑、赐宴蓬瀛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16693, '乐语', '王义山', '西山元是神仙境，瑞气郁森森。\n彩鸾飞下五云深。\n急管递繁音。\n碧鬓□斜花欲颤，轻盈莲步移金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16694, '乐语', '王义山', '慈元宫殿五云开。\n寿献九霞杯。\n步随王母共徘徊。\n仙子下瑶台。\n红袖引翻鸾镜媚，婆娑雪□风回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16695, '乐语', '王义山', '风吹仙袂飘飘举，底事下蓬莱。\n东朝遥祝万年杯。\n玉液泻金垒。\n天上蟠桃又熟，晕酡颜、红染芳腮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16696, '乐语', '王义山', '千年紫极锁烟萝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16697, '乐语', '王义山', '秘传玉诀自灵修。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16698, '乐语', '王义山', '自在云间白鹤飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16699, '乐语', '王义山', '闲云潭影日悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16700, '乐语', '王义山', '新吴曾遇许旌阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16701, '乐语', '王义山', '龙楼日永，鹤禁风薰，拂晓寿星光现。\n无限霞裾，欣传帝母，与佛同生华旦。\n佳气慈闱，看龙颜欢动，玉卮亲劝。\n捧祝殷勤，对萱草青松，菖蒲翠软。\n奇香喷，阶前芍药，频繁红深紫浅。\n遥望千官鹭序，晓仗初齐，趋觐慈元宫殿。\n更喜明朝，虹流佳节，同听嵩山呼万。\n湛露重重，燕庆两宫，盛事如今亲见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16702, '乐语', '王义山', '先献此花名字好。\n密叶长青，翠羽摇仙葆。\n紫禁风薰惊夏到。\n花飞细□香堪扫。\n拂晓宫娃争报道。\n无限琼妃，缥缈来蓬岛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16703, '乐语', '王义山', '端的长春春不老。\n玉颊微红，酒晕精神好。\n多谢天工相懊恼。\n花间不问春迟早。\n风外新篁摇翠葆。\n长乐宫边，绿阴笼驰道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16704, '乐语', '王义山', '莫忘九疑山上侣。\n住在山中，白石清泉处。\n好与长年沾雨露。\n灵根下遣蟠虬护。\n青青九节长如许。\n早晚成花，教见薰风度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16705, '乐语', '王义山', '岁岁丹霞天近处。\n借问殷勤，何以逢兰杜。\n碧砌玉阑春不去。\n清香长逐薰风度。\n况是恩光新雨露。\n绿叶青青，葱翠长如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16706, '乐语', '王义山', '犹是太真亲手植。\n猩染鲜葩，岁岁如曾拭。\n绛节青旌光耀日。\n分明是个神仙匹。\n引领金扉红的的。\n下有仙妃，纤手轻轻摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16707, '乐语', '王义山', '移向慈元供寿佛。\n压倒群花，端的成清绝。\n青萼玉包全未拆。\n薰风微处留香雪。\n未拆香包香已冽。\n沈水龙涎，不用金炉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16708, '乐语', '王义山', '还比蒲桃天上植。\n稚柳阴中，蜀锦开如织。\n万岁藤边娇五色。\n宜春馆里香寻觅。\n七十二行鲜的的。\n岁岁如今，早趁薰风摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16709, '乐语', '王义山', '日日传宣金掌露。\n当殿芳菲，似约春长驻。\n微紫深红浑谩与。\n淡妆偏趁泥金缕。\n拂早薰风花里度。\n吹送香尘，东殿称觞处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16710, '乐语', '王义山', '戏衮玉球添一笑。\n笑道轻狂，似恁人间少。\n偏倚龙池依凤沼。\n随风得得低回绕。\n掠面点衣夸百巧。\n似雪飞花，点束梁圆好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16711, '乐语', '王义山', '消息一年传一度。\n万岁枝香，总是留春处。\n曾倚东风娇不语。\n玉阶霞袂飘飘举。\n蓬莱清浅红云路。\n结子新成，要荐金盘去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16712, '乐语', '王义山', '十样仙葩天也爱。\n留住春光，一一娇相赛。\n万里莺花开世界。\n园林点检随时采。\n□□□眉仙体态。\n天与司花，舞彻歌还再。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16713, '蝶恋花', '刘云甫', '一点郎星光彻晓。\n许大乾坤，难著经纶手。\n拂袖归来应自笑。\n山翁偏爱林泉好。\n庭下儿孙歌寿酒。\n不献蟠桃，不数安期枣。\n且喜今朝云出岫。\n定知霖雨苍生早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16714, '柳梢青', '龚日升', '二十年前。\n君家桃李，种满螺川。\n凛凛英风，真如小范，不数梅仙。\n薰风吹送朝天。\n指何物、装添去船。\n千首新诗，一轮明月，两字清廉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16715, '沁园春', '陈若水', '拂袖归来，懒踏前回，京华软尘。\n算宦游虽好，何如生处，急流勇退，赢得闲人。\n身羡仙翁，萧然野服，笑咏东溪溪上亭。\n头犹黑、甚丰姿鹤瘦，标致梅清。\n今年转觉精神。\n便次第平头八十人。\n肯又抛渭钓，似周尚父，且来洛社，作宋耆英。\n报答明恩，一时分付，贤子贤孙事业新。\n丹心在，尚瓣香岁岁，遥祝尧龄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16716, '宴清都', '胡翼龙', '梦雨随春远。\n征衫薄、短篷犹逗寒浅。\n裁芳付叶，书愁沁壁，水窗竹院。\n别来被篝梅润，暗尘积、旧题纨扇。\n许多时，闲了阑干，放得藓痕青满。\n谁念。\n杜若还生，苹花又绿，不堪重□。\n山程水记，茶经砚谱，共谁闲展。\n湖山旧曾游遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16717, '徵招', '胡翼龙', '苹花又绿江南岸，宾鸿带将寒去。\n几许落梅愁，渺暗香何处。\n一春长是雨。\n剩费却、翠篝沉炷。\n冷隔帘旌，润销窗纸，有人吟苦。\n燕垒渍芹香，画堂永、关心去年情绪。\n愁压曲屏深，更小山无数。\n溅裙前事误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16718, '八声甘州', '胡翼龙', '甚年年、心事占秋多，芳洲乱芜生。\n正小山已桂，东篱又菊，秋为人清。\n肠断洞庭叶下，倚西风、谁可寄芳蘅。\n袅袅愁予处，欲醉还醒。\n为问素娥饮否，自谪仙去後，知与谁明。\n耿盈盈如此，分影落瑶觥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16719, '洞仙歌', '胡翼龙', '半栏花雨。\n是夜来凭处。\n梦过溪桥逢柳住。\n乱莺声残酒醒，正是关情，山枕上、吟就回纹锦句。\n归鸿应别浦。\n绿涨弥茫，早近湖阴唤船路。\n览芳菲，歌窈窕，独立莎根，剩一掬、闲情凄楚。\n欲待折、微馨寄相思，又生怕相思，带将春去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16720, '满庭芳', '胡翼龙', '秋彻檐花，吟苦砚海，日长多费茶烟。\n怀芳心苦，持此过年年。\n雨外飞红何许，应流到、采绿洲边。\n销凝处，别离情绪，正是海棠天。\n吹花题叶事，如今梦里，记得依然。\n料归来、莺居春後，燕占人先。\n谁念文园倦客，琴空在、懒向人弹。\n愁何极，楚天老月，偏是到窗前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16721, '鹧鸪天', '胡翼龙', '六曲银屏梦隔云。\n半分鸾影匣生尘。\n别来可是春愁觉，试著经衫不贴身。\n风月夜，短长亭。\n也须闻得子规声。\n归时莫看花梢上，但看芳洲绿浅深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16722, '少年游', '胡翼龙', '晓莺声脆雨花乾。\n倦枕梦初残。\n衣渍香留，窗深纸暗，把镜近檐看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16723, '霓裳中序第一', '胡翼龙', '江郊雨正歇。\n燕子飞来人忆别。\n未了残梅怨结。\n渺野色波光，春与天接。\n相思辽阔。\n怕柳风、吹老吟发。\n关情处，满汀芳草，遮莫是。\n时节。\n一饷愁绝。\n谩料理、新翻几阕。\n山尊堪共谁设。\n梦到断桥，飞絮仍雪。\n岁华休省阅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16724, '夜飞鹊・夜飞鹊慢', '胡翼龙', '星桥度情处，地久天长。\n尘世无此匆忙。\n纤云淡荡凉蝉小，家家瓜果钱唐。\n愁人独无那，叹紫箫易断，青翼难将。\n返魂何在，漫空留、荀令馀香。\n忍记穿针儿女，篝尘想都暗，叠损衣裳。\n谁念才情减灭，老来何逊，少日卢郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16725, '西江月', '胡翼龙', '水霁芹香燕觜，林深风暖莺吭。\n一春心事锦机傍。\n忘却寻芳模样。\n柳絮池塘昼午，梨花院落昏黄。\n阑干曲曲是回肠。\n倚到西厢月上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16726, '踏莎行', '胡翼龙', '合数冰莲，注情金叶。\n臂痕犹记嗔时迹。\n小楼几个月黄昏，荷香柳影都知得。\n问字灯深，学书窗黑。\n衣襟诗卷留残墨。\n想思不抵藕丝长，梦云断处吴山碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16727, '南歌子', '胡翼龙', '山枕莺声晓，羽觞花片飞。\n昨朝犹道未成归。\n不记春衫襟上、旧题诗。\n愁眼垂杨见，苦心红烛知。\n翻成怕见别离时。\n只寄一声将息、当相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16728, '长相思', '胡翼龙', '南山钟。\n北山钟。\n一听钟声百念空。\n古今昏晓中。\n望秋风。\n数秋风。\n等得秋来等过鸿。\n灯前书一封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16729, '兰陵王', '刘之才', '此何夕。\n天水空明一碧。\n商量赋、如此江山，几个斜阳了今昔。\n荒台步晚色。\n沙鸟依稀曾识。\n啼外，人远未归，江阔晴虹卧千尺。\n残碑藓痕积。\n记当日清游，夫君题墨。\n碧瑶仙去苍云隔。\n飞一镜秋冷，列屏天远，鸡声人语半郊邑。\n寄情又江国。\n愁寂。\n怕闻笛。\n正怨苦溪猿，飞倦汀翼。\n阴阴翡翠迷津驿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16730, '玲珑四犯', '刘之才', '几叠云山，隔不断阑干，天外凝眺。\n秋与愁并，梧迳雨痕先表。\n娇梦半握芙蓉，奈曲曲、翠屏深窈。\n问愁根，当年谁种，漠漠淡烟衰草。\n鸳鸯懒拂苹花影，记眉妩、萦情多少。\n辘轳玉虎牵丝转，听尽秋晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16731, '声声慢', '刘之才', '湘云织玉，楚葛篝香，澡兰帘幕风静。\n怨抑难招，沉魄当年独醒。\n莫唱江南古调，念天涯、深情谁省。\n时暗换，最秦楼惆望，归期无定。\n曾是榴裙误写，怕照眼枝头，绛绡花并。\n巧篆盘丝，午镜绿窗闹影。\n香蒲也应细剪，但年年、断云愁冷。\n迎醉面，看银蟾、飞浴露井。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16732, '贺新郎', '刘之才', '苍藓粘溪路。\n帐山君、け然羽化，梦魂何许。\n曾约秋云萦客袖，舞傍吟皋砚坞。\n矫清唳、裂穿云宇。\n江碧空无处问，问孤山、梅底人知否。\n烟夜永，耿心语。\n瑶华一去成幽阻。\n倚修篁、抱琴愁绝，天寒日暮。\n城郭悲歌华表恨，此事销凝千古。\n有招隐、小山能赋。\n蕙帐空兮谁夜怨，算课骚、读易俱凄楚。\n步深窈，堕松露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16733, '菩萨蛮', '刘之才', '题花曾蘸花心露。\n当初误结丁香树。\n往事小蛮窗。\n新愁桃叶江。\n缓歌留薄醉。\n急镫人千里。\n梅瘦月阑干。\n断云春梦寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16734, '解连环', '刘之才', '晚云粘湿。\n正吴峰惨澹，雨迷烟接。\n早陡顿、秋事分携，甚连苑暮墙，菊荒苔匝。\n空阔愁乡，更天外、怨鸿声黠。\n怕吟肩易瘦，料理篝衣，细认香折。\n银缸半明半灭。\n念花营柳阵，何日消歇。\n可是□、凝黯兰成，为情润才松，丽赋多惬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16735, '卖花声', '萧汉杰', '湿逗晚香残。\n春浅春寒，洒窗填户著幽兰。\n惨惨凄凄仍滴滴，做出多般。\n和霰撒珠盘。\n枕上更阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16736, '菩萨蛮', '萧汉杰', '春愁一段来无影。\n著人似醉昏难醒。\n烟雨湿阑干。\n杏花惊蛰寒。\n唾壶敲欲破。\n绝叫凭谁和。\n今夜欠添衣。\n那人知不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16737, '蝶恋花', '萧汉杰', '一缕春情风里絮。\n海阔天高，那更云无数。\n娇颤画梁非为雨。\n怜伊只合和伊去。\n欲话因缘愁日暮。\n细认帘旌，几度来还去。\n万一这回航可渡。\n共渠活处寻条路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16738, '浪淘沙', '萧汉杰', '愁似晚天云。\n醉亦无凭。\n秋光此夕属何人。\n贫得今年无月看，留滞江城。\n夜起候檐声。\n似雨还晴。\n旧家谁信此时情。\n惟有桂香时入梦，勾引诗成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16739, '清平乐', '罗椅', '明虹收雨。\n两桨能吴语。\n人在江南荷叶浦。\n采得苹花无数。\n梦中舞燕栖鸾。\n起来烟渚风湾。\n一点愁眉天末，凭谁却春山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16740, '八声甘州', '罗椅', '甚匆匆岁月，又人家、插柳记清明。\n正南北高峰，山传笑响，水泛箫声。\n吹散楼台烟雨，莺语碎春晴。\n何地无芳草，惟此青青。\n谁管孤山山下，任种梅竹冷，荐菊泉清。\n看人情如此，沉醉不须醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16741, '柳梢青', '罗椅', '萼绿华身，小桃花扇，安石榴裙。\n子野闻歌，周郎顾曲，曾恼夫君。\n悠悠羁旅愁人。\n似飘零、青天断云。\n何处销魂，初三夜月，第四桥春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16742, '更漏子', '罗椅', '晚潮生，凉月细。\n一抹远山无蒂。\n收越棹，起吴樯。\n人间何限忙。\n石头城，西北角。\n杳杳天低鹘落。\n浑不似，此波光。\n清歌催夕阳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16743, '长相思', '徐霖', '听莺声。\n惜莺声。\n客里莺声最有情。\n家山何处青。\n问归程。\n数归程。\n行尽长亭又短亭。\n征衫脱未成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16744, '点绛唇', '朱埴', '绣被鸳鸯，宝香熏透蔷薇水。\n枕边一纸。\n明月人千里。\n宿酒初醒，全不梳洗。\n抬纤指。\n微签玉齿。\n百色思量起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16745, '画堂春', '朱埴', '绿窗睡起小妆残。\n玉钗低堕云鬟。\n回纹枉寄见伊难。\n心绪阑珊。\n翠袖两行珠泪，画楼十二阑干。\n销磨今古霎时间。\n恨杀青山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16746, '南乡子', '朱埴', '花柳隔重扃。\n送过秋千笑语声。\n檐鹊也嗔人起晚，天晴。\n孤负东风趁踏青。\n细细砑红绫。\n小字相思写不成。\n心上可人云样远，寒盟。\n只恐恩情薄似云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16747, '酹江月・念奴娇', '张绍文', '举杯呼月，问神京何在，淮山隐隐。\n抚剑频看勋业事，惟有孤忠挺挺。\n宫阙腥膻，衣冠沦没，天地凭谁整。\n一枰棋坏，救时著数宜紧。\n虽是幕府文书，玉关烽火，暂送平安信。\n满地干戈犹未戢，毕竟中原谁定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16748, '水龙吟', '张绍文', '日迟风软花香，困人天气情怀懒。\n牡丹谢了，酴开後，红稀绿暗。\n慵下妆楼，倦吟莺镜，粉轻脂淡。\n叹韶华迤逦，将春归去，沉思处、空肠断。\n长是愁蛾不展。\n话春心、只凭双燕。\n良辰美景，可堪虚负，登临心眼。\n雁杳鱼沉，信音难托，水遥山远。\n但无言，倚遍阑干十二，对芳天晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16749, '壶中天・念奴娇', '张绍文', '丹台仙伯，记踪迹当年、琼楼金阙。\n底事来游人世界，为爱风云水月。\n结屋南园，境随人胜，不是溪山别。\n今朝初度，碧莲千顷齐发。\n况是鸳侣新偕，凤雏才长，占人间欢悦，且尽壶天终夕醉，听取妙歌千阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16750, '沁园春', '张绍文', '数遍时贤，谁似云溪，未老得闲。\n自抽身州县，归休旧隐，灰心名利，跳出尘寰。\n卸却朝衣，笑拈拄杖，日在花阴竹径间。\n身轻健，任高眠晏起，渴饮饥餐。\n垂弧猛省当年。\n且约住春风开寿筵。\n况园亭池馆，新奇佳丽，弟兄子侄，歌笑团栾。\n绿鬓朱颜，纶巾羽扇，做个人间长寿仙。\n霞觞举，愿年年今日，长对南山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16751, '八六子', '杨缵', '怨残红。\n夜来无赖，雨催春去匆匆。\n但暗水、新流芳恨，蝶凄蜂惨，千林嫩绿迷空。\n那知国色还逢。\n柔弱华清扶倦，轻盈洛浦临风。\n细认得凝妆，点脂匀粉，露蝉耸翠，蕊金团玉成丛。\n几许悉随笑解，一声歌转春融。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16752, '一枝春', '杨缵', '竹爆惊春，竞喧填、夜起千门箫鼓。\n流苏帐暖，翠鼎缓腾香雾。\n停杯未举。\n奈刚要、送年新句。\n应自有、歌字清圆，未夸上林莺语。\n从他岁穷日暮。\n纵闲愁、怎减刘郎风度。\n屠苏办了，迤逦柳欺梅妒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16753, '被花恼', '杨缵', '疏疏宿雨酿寒轻，帘幕静垂清晓。\n宝鸭微温瑞烟少。\n檐声不动，春禽对语，梦怯频惊觉。\n珀枕，倚银床，半窗花影明东照。\n惆怅夜来风，生怕娇香混瑶草。\n披衣便起，小径回廊，处处多行到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16754, '瑞鹧鸪', '史铸', '底事秋英色压黄。\n喜行春令惜红妆。\n谢天分付千年品，特地搀先九日香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16755, '恋绣衾', '林洪', '冰肌生怕雪未禁。\n翠屏前、短瓶满簪。\n真个是、疏枝瘦，认花儿、不要浪吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16756, '点绛唇', '吴大有', '江上旗亭，送君还是逢君处。\n酒阑呼渡。\n云压沙鸥暮。\n漠漠萧萧，香冻梨花雨。\n添愁绪。\n断肠柔橹。\n相逐寒潮去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16757, '浪淘沙', '金淑柔', '雨溜和风铃。\n滴滴丁丁。\n酿成一枕别离情。\n可惜当年陶学士，孤负邮亭。\n边雁带秋声。\n音信难凭。\n花须偷数卜归程。\n料得到家秋正晚，菊满寒城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16758, '沁园春', '陈人杰', '不恨穷途，所恨吾生，不见古人。\n似道傍郭泰，品题季伟，舟中谢尚，赏认袁宏。\n又似元之，与苏和仲，汲引孙子晁李秦。\n今安在，但高风凛凛，坟草青青。\n江东无我无卿。\n政自要胸中分渭泾。\n叹今人荣贵，祗修边幅，斯文寂寞，终欠宗盟。\n面蹉长江，目迷东野，却笑韩公接後生。\n知音者，恨黄金难铸，清泪如倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16759, '沁园春', '陈人杰', '我梦登天，尽把不平，问之化工。\n似桂花开日，秋高露冷，梅花开日，岁老霜浓。\n如此清标，依然香性，长在凄凉索寞中。\n何为者，祗纷纷桃李，占断春风。\n一时列鼎分封。\n岂猿臂将军无寸功。\n想世间成败，不关工拙，男儿济否，只声遭逢。\n天曰果然，事皆偶尔，凿井得铜奴得翁。\n君归去，但力行好事，休问穷通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16760, '沁园春', '陈人杰', '春为谁来，谁遣之归，挽之不还。\n纵小桃李，大都寂寞，紫薇红药，未到阑珊。\n毕竟须归，何妨小驻，容我一尊烟雨间。\n春无语，只游丝舞蝶，懒上杯盘。\n故园。\n风物班班。\n奈声利羁留身未闲。\n望归鸿影尽，白云万里，啼鹃声切，落日千山。\n春却笑人，年来何事，要得一归如许难。\n君知否，百八盘世路，尽在长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16761, '沁园春', '陈人杰', '太岁茫茫，犹有归时，我胡不归。\n为桂枝关约，十年阙下，梅花梦想，半夜天涯。\n婪尾三杯，胶牙一标，节物依然心事非。\n长安市，只喧喧箫鼓，催老男儿。\n篝灯自理征衣。\n正历乱愁肠千万丝。\n想椒盘寂寞，空传旧颂，桃符冷落，谁撰新诗。\n世事乾忙，人生寡遂，何限春风抛路歧。\n身安处，且开眉一笑，何以家为。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16762, '沁园春', '陈人杰', '为问杜鹃，抵死催归，汝胡不归。\n似辽东白鹤，尚寻华表，海中玄鸟，犹记乌衣。\n吴蜀非遥，羽毛自好，合趁东风飞向西。\n何为者，却身羁荒树，血洒芳枝。\n兴亡常事休悲。\n算人世荣华都几时。\n看锦江好在，卧龙已矣，玉山无恙，跃马何之。\n不解自宽，徒然相劝，我辈行藏君岂知。\n闽山路，待封侯事了，归去非迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16763, '沁园春', '陈人杰', '春事方浓，寂寞此君，谁相品题。\n到桃李，鸠边雨急，埋薇瘗药，燕外泥肥。\n鸟影舒炎，黄埃涨暑，又过绿阴青子时。\n夫然後，向猷家载酒，诩室题诗。\n风标如此清奇。\n叹世俗炎凉真可悲。\n看眼空凡木，云霄直上，心交古干，霜雪相依。\n弹压溪山，留连风月，红紫纷纷谁似之。\n人间世，这澹中风味，儿辈争知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16764, '沁园春', '陈人杰', '诗不穷人，人道得诗，胜如得官。\n有山川草木，纵横纸上，虫鱼鸟兽，飞动毫端。\n水到渠成，风来帆速，廿四中书考不难。\n惟诗也，是乾坤清气，造物须悭。\n金张许史浑闲。\n未必有功名久後看。\n算南朝将相，到今几姓，西湖名胜，只说孤山。\n象笏堆床，蝉冠满座，无此新诗传世间。\n杜陵老，向年时也自，井冻衣寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16765, '沁园春', '陈人杰', '记上层楼，与岳阳楼，酾酒赋诗。\n望长山远水，荆州形胜，夕阳枯木，六代兴衰。\n扶起仲谋，唤回玄德，笑杀景升豚犬儿。\n归来也，对西湖叹息，是梦耶非。\n诸君傅粉涂脂。\n问南北战争都不知。\n恨孤山霜重，梅凋老叶，平堤雨急，柳泣残丝。\n玉垒胜烟，珠淮飞浪，万里腥风吹鼓鼙。\n原夫辈，算事今如此，安用毛锥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16766, '沁园春', '陈人杰', '谁使神州，百年陆沉，青毡未还。\n怅晨星残月，北州豪杰，西风斜日，东帝江山。\n刘表坐谈，深源轻进，机会失之弹指间。\n伤心事，是年年冰合，在在风寒。\n说和说战都难。\n算未必江沱堪宴安。\n叹封侯心在，鲸失水，平戎策就，虎豹当关。\n渠自无谋，事犹可做，更剔残灯抽剑看。\n麒麟阁，岂中兴人物，不画儒冠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16767, '沁园春', '陈人杰', '落日都门，买得扁舟，乘兴而东。\n正苕川半夜，月寒似水，苹洲一路，秋老多风。\n携妓溪山，寻春岁月，往事黄粱昨梦中。\n高楼上，问何人怀古，湖海元龙。\n诸君解后相逢。\n更休问奚奴金错空。\n向琐窗看镜，鬓无霜白，玉挥酒，脸有潮红。\n莼美鲈肥，橙香蟹壮，风味不如归兴浓。\n明朝去，有西门一水，直与天通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16768, '沁园春', '陈人杰', '此去长安，说似交游，我来自东。\n向蒹葭极浦，吟篷泊雨，梧桐孤店，醉帻风。\n青市生涯，白洲活计，都在水乡鱼稻中。\n邮亭上，俯清流长啸，惊起虬龙。\n山面面迎逢。\n便回首旧游云水空。\n有连天秋草，寒烟借碧，满城霜叶，落照争红。\n六代蜂窠，七贤蝶梦，勾引客愁如酒浓。\n人间世，只醉乡堪向，休问穷通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16769, '沁园春', '陈人杰', '草满姑苏，问讯夫差，今安在哉。\n望虎丘苍莽，愁随月上，蠡湖浩渺，兴逐潮来。\n自古男儿，可人心事，惆怅要离招不回。\n离之後，似舞阳几个，成甚人才。\n西风斜照徘徊。\n比旧日江南尤可哀。\n叹茫茫马腹，黄尘如许，纷纷牛背，青眼难开。\n应物香销，乐天句杳，无限风情成死灰。\n都休问，向客边解后，祗好拈杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16770, '沁园春', '陈人杰', '日薄风狞，万里空江，隐隐有声。\n旋千旗万棹，一时东指，青山断处，白浪成层。\n渐近渐高，可惊可喜，作雪峰楼外横。\n教人讶，是鲸掀鳌，蛟斗龙争。\n属镂忠恨腾腾。\n要句践城台都荡平。\n奈岸身不动，潮头自落，又如飞剑，斫倒鼍城。\n若到夜深，更和月看，组练分明十万兵。\n尤奇特，有稼轩一曲，真野狐精。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16771, '沁园春', '陈人杰', '把酒西湖，花月三年，不见家山。\n想荆州座上，消磨岁月，唐风集里，收卷波澜。\n鹤邑朝帆，鲈乡夕棹，来往菰蒲何处间。\n应思我，似骑驴杜甫，长在长安。\n相逢依旧开颜。\n听玉屑霏霏当暑寒。\n笑髯生如许，尚夸年少，心忙未了，浪说身闲。\n尘梦无凭，菟裘堪老，付子声名吾欲还。\n斜阳外，把平生心事，同倚阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16772, '沁园春', '陈人杰', '过了梅花，纵有春风，不如早还。\n正燕泥日暖，草绵别路，莺朝烟澹，柳拂征鞍。\n黎岭天高，建溪雷吼，归好不知行路难。\n龟山下，渐青梅初熟，卢橘犹酸。\n名场老我闲关。\n分岁晚诛茅湖上山。\n叹龙舒君去，尚留破砚，鱼轩人老，长把连环。\n镜影霜侵，衣痕尘暗，赢得狂名传世间。\n君归日，见家林旧竹，为报平安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16773, '沁园春', '陈人杰', '斗酒津亭，方送月芗，夫君又行。\n正夕阳枯木，低回征路，寒烟衰草，迤逦离情。\n京洛风尘，吴兴山水，等是东西南北人。\n思君处，只梅花解后，心目开明。\n江湖夜雨青灯。\n曾说尽百年闲废兴。\n叹屠龙事业，依然汗漫，歌鱼岁月，政尔峥嵘。\n但使豫州，堪容玄德，何必区区依景升。\n需时耳，算不应长是，竖子成名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16774, '沁园春', '陈人杰', '塞外江山，如此萧条，可堪别离。\n纵虹桥烟浪，要君怀古，凤城风雨，奈我相思。\n玉茧挥诗，金鲸泻酒，件件清狂分付谁。\n长安市，有几多心事，岁老相期。\n春风渐到梅枝。\n算我辈荣枯应似之。\n莫提携剑铗，悲歌一曲，摩挲髀肉，清泪双垂。\n话到辛酸，居然慷慨，跃马岁年心自知。\n君行矣，有广平东阁，堪著男儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16775, '沁园春', '陈人杰', '未省吾生，石室云林，金门玉堂。\n但吕公来说，风神清怪，甘公来说，寿禄高强。\n果若人言，自应年少，曳紫鸣珂游帝乡。\n何为者，更风尘牢落，歧路回皇。\n替人缝嫁衣裳。\n奈未遇良媒空自伤。\n岂平生犹欠，阴功活蚁，从前未卜，吉地眠羊。\n岁晏何如，时来便做，但恐鬓毛容易霜。\n今休问，且揆予初度，满引金觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16776, '沁园春', '陈人杰', '五彩云中，群玉峰头，是吾故乡。\n为瑶池侍宴，偶违酒令，玉皇降敕，谪作诗狂。\n桧柏风姿，山林气象，未到中年先老苍。\n西湖路，尽留连光景，傲睨冰霜。\n东窗。\n翦烛焚香。\n剩满引梅花进寿觞。\n梦群仙相庆，烹炮麟凤，十洲同往，骖翳鸾凰。\n约向人间，尽偿吟债，依旧乘风来帝旁。\n如今未，且百年管领，橘绿橙黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16777, '沁园春', '陈人杰', '如此男儿，可是疏狂，才大兴浓。\n看曹瞒事业，雀台夜月，建封气概，燕子春风。\n叱咤生雷，肝肠似石，才到尊前都不同。\n人间世，只婵娟一剑，磨尽英雄。\n半生书剑无功。\n漫赢得闲情如二公。\n向紫云歌畔，玉最满，红桃笑里，金错长空。\n驼陌三年，牛腰几束，半在兰香巾笥中。\n君知否，是扬州景物，消得司封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16778, '沁园春', '陈人杰', '世路如秋，万里萧条，君何所之。\n想鲈乡烟水，尚堪垂钓，虎丘泉石，尽可题诗。\n橙弄霜黄，芦飘雪白，何处西风无酒旗。\n经行地，有会心之事，好吐胸奇。\n一邱封了要离。\n问世上男儿今有谁。\n但一尊相属，居然感慨，扁舟独往，可是崎。\n齐邸歌鱼，扬州跨鹤，风味浅深君自知。\n匆匆去，算梅边春动，又是归期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16779, '沁园春', '陈人杰', '抚剑悲歌，纵有杜康，可能解忧。\n为修名不立，此身易老，古心自许，与世多尤。\n平子诗中，庾生赋里，满目江山无限愁。\n关情处，是闻鸡半夜，击楫中流。\n澹烟衰草连秋。\n听鸣声声相应酬。\n叹霸才重耳，泥涂在楚，雄心元德，岁月依刘。\n梦落莼边，神游菊外，已分他年专一丘。\n长安道，且身如王粲，时复登楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16780, '沁园春', '陈人杰', '我自无忧，何用攒眉，今忧古忧。\n叹风寒楚蜀，百年受病，江分南北，千载归尤。\n洛下铜驼，昭陵石马，物不自愁人替愁。\n兴亡事，向西风把剑，清泪双流。\n边头。\n依旧防秋。\n问诸将君恩酬未酬。\n怅书生浪说，皇王帝霸，功名已属，韩岳张刘。\n不许请缨，犹堪草檄，谁肯种瓜归故邱。\n江中蜃，识平生许事，吐气成楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16781, '沁园春', '陈人杰', '尽典春衣，换酒津亭，送君此行。\n叹清朝有道，何曾逐客，有司议法，忍及书生。\n归去来兮，噫其甚矣，见说江涛也不平。\n君之友，岂都无义士，剖胆相明。\n挑诗行李如冰。\n正趁得越山桃李春。\n把从前豪举，著些老气，不应造物，到底无情。\n雁荡烟霞，凤城风雨，两地相思魂梦清。\n重来否，算海波未窄，犹可骑鲸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16782, '沁园春', '陈人杰', '南北战争，惟有西湖，长如太平。\n看高楼倚郭，云边矗栋，小亭连苑，波上飞甍。\n太守风流，游人欢畅，气象迩来都斩新。\n秋千外，剩钗骈玉燕，酒列金鲸。\n人生。\n乐事良辰。\n况莺燕声中长是晴。\n正风嘶宝马，软红不动，烟分彩，澄碧无声。\n倚柳分题，藉花传令，满眼繁华无限情。\n谁知道，有种梅处士，贫里看春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16783, '沁园春', '陈人杰', '万法皆空，空即是空，佛安在哉。\n有云名妙净，可遮热恼，海名圆觉，堪洗尘埃。\n翠竹真如，黄花般若，心上种来心上开。\n教参熟，是菩提无树，明镜非台。\n偷闲来此徘徊。\n把人世黄粱都唤回。\n算五陵豪客，百年荣贵，何如衲子，一钵生涯。\n俯仰溪山，婆娑松桧，两腋清风茶一杯。\n拿舟去，更扫尘东壁，聊记曾来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16784, '沁园春', '陈人杰', '懒学冯君，弹铗歌鱼，如今五年。\n为西湖西子，费人料理，东林东老，特地留连。\n坐注虫鱼，行吟雌霓，竟负逍遥第一篇。\n过从少，但赤髭白足，时复谈禅。\n倚门白水平田。\n看数点青山无尽天。\n叹春风心事，已成待兔，夕阳时节，又听啼鹃。\n如此凄凉，若为排遣，不是诗边即酒边。\n中宵梦，有逋梅吹雪，坡柳摇烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16785, '沁园春', '陈人杰', '云锦亭西，记与诗人，拍浮酒船。\n看洛川妃子，锦衾照水，汉皋游女，玉佩摇烟。\n秋老芳心，波空艳质，惟见寒霜凋碧圆。\n争知道，有西湖五月，长在尊前。\n素纨红障相鲜。\n更澹静一枝真叶仙。\n向风轩摇动，但无香耳，蓼丛掩映，自是天然。\n猊背生烟，蜡心吐月，赢得吴娃歌采莲。\n陈公子，似日休锺爱，兴满吟边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16786, '沁园春', '陈人杰', '易得仲宣，难得世间，有刘景升。\n叹男儿未到，鸣珂谒帝，此身那免，弹铗依人。\n橘自盈洲，莸难共器，一榻相看如越秦。\n元龙者，独门前有客，胸次无尘。\n君今重莅诗盟。\n载弄玉飞琼车後行。\n过鸱夷西子，曾游处所，水云应喜，重见娉婷。\n张禹堂深，马融帐暖，吟罢不妨丝竹声。\n松江上，约扁舟棹雪，同看梅春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16787, '沁园春', '陈人杰', '道骨仙风，自天上来，月潭主人。\n把玉清宝印，按行川岳，神霄铁尺，鞭叱雷霆。\n雨部收晴，日君腾照，一寸灵章飞杳冥。\n幡旗外，觉阴风肃肃，奔走神兵。\n登坛沥酒刑牲。\n有法馔如山饱万灵。\n想乖龙惊起，碧潭无底，妖蟆戮尽，月长明。\n行比旌阳，功高李靖，玉府丹台登姓名。\n平生志，合为霖为雨，大慰苍生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16788, '沁园春', '陈人杰', '禁鼓蓬蓬，忙杀公侯，穴城影中。\n正花前豪士，宿酲未解，松间逋客，清梦才浓。\n龙尾危机，犀围长物，何必飞书交子公。\n人间世，只闲之一字，受用无穷。\n主人窗户玲珑。\n悟富贵荣华回首空。\n向竹梧侧畔，聚先秦录，兰荪里许，吟晚唐风。\n琴外鸿归，棋边鹭静，天把一丘荣此翁。\n孙刘辈，枉百年争战，一昧雌雄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16789, '浣溪纱・浣溪沙', '毛', '绿玉枝头一粟黄。\n碧纱帐里梦魂香。\n晓风和月步新凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16790, '踏莎行', '毛', '顾曲多情，寻芳未老。\n一庭风月知音少。\n梦随蝶去恨墙高，醉听莺语嫌笼小。\n红烛呼卢，黄金买笑。\n弹丝踮屣长安道。\n彩笺拈起锦囊花，绿窗留得罗裙草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16791, '摸鱼儿', '张矩', '又吴尘、暗斑吟袖，西湖深处能浣。\n晴云片片平波影，飞趁棹歌声远。\n回首唤。\n仿佛记、春风共载斜阳岸。\n轻携分短。\n怅柳密藏桥，烟浓断径，隔水语音换。\n思量遍。\n前度高阳酒伴。\n离踪悲事何限。\n双峰塔露书空颖，情共暮鸦盘转。\n归兴懒。\n悄不似、留眠水国莲香畔。\n灯帘晕满。\n正蠹帙逢迎，沈煤半冷，风雨闭宵馆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16792, '应天长', '张矩', '曙林带暝，晴霭弄霏，莺花未认游客。\n草色旧迎雕辇，蒙茸暗香陌。\n秋千架，闲晓索。\n正露洗、绣鸳痕窄。\n费人省，隔夜浓欢，酲处先觉。\n重过涌金楼，画舫红旌，催向段桥泊。\n又怕晚天无准，东风妒芳约。\n垂杨岸，今胜昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16793, '应天长', '张矩', '候蛩探暝，书雁寄寒，西风暗剪绡织。\n报道凤城催钥，笙歌散无迹。\n冰轮驾，天纬逼。\n渐款引、素娥游历。\n夜妆靓，独展菱花，淡绚秋色。\n人在涌金楼，漏迥绳低，光重袖香滴。\n笑语又惊栖鹊，南飞傍林阒。\n孤山影，波共碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16794, '应天长', '张矩', '澌冱晓，篙水涨漪，孤山渐卷云簇。\n又见岸容舒腊，菱花照新沐。\n横斜树，香未北。\n倩点缀、数梢疏玉。\n断肠处，日影轻消，休怨霜竹。\n帘上涌金楼，酒滟酥融，金缕试春曲，最好半残鹊，登临快心目。\n瑶台梦，春未足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16795, '应天长', '张矩', '磬圆树杪，舟乱柳津，斜阳又满东角。\n可是暮情堪剪，平分付烟郭。\n西风影，吹易薄。\n认满眼、脆红先落。\n算惟有，塔起金轮，千载如昨。\n谁信涌金楼，此际凭阑，人共楚天约。\n准拟换樽陪月，缯空卷尘幕。\n飞鸿倦，低未泊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16796, '应天长', '张矩', '换桥度舫，添柳护堤，坡仙题欠今续。\n四面水窗如染，香波酿春曲。\n田田处，成暗绿。\n正万羽、背风斜矗。\n乱鸥去，不信双鸳，午睡犹熟。\n还记涌金楼，共抚雕阑，低度浣沙曲。\n自与故人轻别，荣枯换凉燠。\n亭亭影，惊艳目。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16797, '应天长', '张矩', '岸容浣锦，波影堕红，纤鳞巧避凫唼。\n禹浪未成头角，吞舟胆犹怯。\n湖山外，江海匝。\n怕自有、暗泉流接。\n楚天远，尺素无期，枉误停楫。\n四望涌金楼，带草烟，缥缈际城堞。\n渐见暮榔敲月，轻舫乱如叶。\n濠梁兴，归未惬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16798, '应天长', '张矩', '翠屏对晚，鸟榜占堤，钟声又敛春色。\n几度半空敲月，山南应山北。\n欢娱地，空浪迹。\n谩记省、五更闻得。\n洞天晓，夹柳桥疏，稳纵香勒。\n前度涌金楼，笑傲东风，鸥鹭半相识。\n暗数院僧归尽，长虹卧深碧。\n花间恨，犹记忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16799, '应天长', '张矩', '翠迷倦舞，红驻老妆，流莺怕与春别。\n过了禁烟寒食，东风颤环铁。\n游人恨，柔带结。\n更唤醒、羽喉宫舌。\n画桥远，不认绵蛮，晚棹空歇。\n争似涌金楼，燕燕归来，钩转暮帘揭。\n对语画梁消息，香泥砌花屑。\n昆明事，休更说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16800, '应天长', '张矩', '桂轮逼采，菱沼漾金，潜虬暗动鲛室。\n水路乍疑霜雪，明眸洗春色。\n年时事，还记忆。\n对万顷，葑痕龟坼。\n旧游处，不认三潭，此际曾识。\n今度涌金楼，素练萦窗，频照庾侯席。\n自与影娥人约，移舟弄空碧。\n宵风悄，签漏滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16801, '应天长', '张矩', '暮屏翠冷，秋树赭疏，双峰对起南北。\n好与霁天相接，浮图现西极。\n苕处，云共碧。\n漫费尽、少年游屐。\n故乡近，一望空遥，水断烟隔。\n闲凭涌金楼，潋滟波心，如洗梦淹笔。\n唤醒睡龙苍角，盘空壮商翼。\n西湖路，成倦客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16802, '梅子黄时雨', '张矩', '云宿江楼，爱留人夜语，频断灯炷。\n奈倦情如醉，黑甜清午。\n谩道迎薰何曾是，簟纹成浪衣成雨。\n茶瓯注。\n新期竹院，残梦莲渚。\n应误。\n重帘凄伫。\n记并刀剪翠，秋扇留句。\n信那回轻道，而今归否。\n十二曲阑随意凭，楚天不放斜阳暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16803, '七娘子', '吴申', '君家诸子燕山盛。\n去年两见门弧庆。\n银蜡烧花，宝香熏烬。\n盘珠玉还相映。\n耳边好语凭君听。\n此儿不与群儿并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16804, '沁园春', '姚勉', '锦水双龙，鞭风驾霆，来游璧池。\n有一龙跃出，精神电烨，一龙战退，鳞甲天飞。\n一样轩拿，殊途升蛰，造化真同戏小儿。\n时人眼，总羡他腾踏，笑我卑栖。\n促装且恁西归。\n信自古功名各有时。\n但而今莫问，谁强谁弱，只争些时节，来速来迟。\n无地楼台，有官鼎鼐，命到亨通事事宜。\n三年里，看龙头独露，雁塔同题。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16805, '贺新郎', '姚勉', '剑吼蛟龙怒。\n问苍天、功名两字，几时分付。\n生个英雄为世用，须早青云得路。\n却底事、知音未遇。\n两度入天飞折翼，谩教人、欲叹儒冠误。\n竟不晓，是何故。\n休休天也无凭据。\n有如椽健笔，蟾宫须还高步。\n若使长材终困踬，社稷谁教扶助。\n信浅水、留龙不住。\n万顷洪流通大海，向波涛、阔处兴云雾。\n须信道，这回做。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16806, '贺新郎', '姚勉', '长啸山中卧。\n叹从前、二十年来，因循空过。\n自是惺惺并了了，奈这五行尚左。\n遇好事、许多磨挫。\n浩荡醉乡狂莫检，算傍人、笑得唇焦破。\n谁信道，只恁麽。\n从今牢把江湖柁。\n要做些勋业，归来则个。\n不见彭余朱李辈，总是白身人作。\n震耀得、声名许大。\n万一老天青眼顾，又何难、印佩黄金颗。\n时来到，也还我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16807, '霜天晓角', '姚勉', '秋怀轩豁。\n痛饮天机发。\n世界只如掌大，算只有、醉乡阔。\n烟抹。\n山态活。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16808, '沁园春', '姚勉', '一部周官，学问渊源，山斋得来。\n最雄姿直气，不涂脂粉，仙风道骨，不尘埃。\n万里青云，相期阔步，底事向天门折翼回。\n君知否，这白衣御史，卿相胚胎。\n时人休用惊猜。\n机会到功名节节催。\n看蒲质易凋，何如松茂，菊花已老，须是梅开。\n万事何难，时来得做，且信天工次第排。\n从今去，愿径游璧水，直上兰台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16809, '贺新郎', '姚勉', '月转宫墙曲。\n六更残、钥鱼声亮，纷纷袍鹄。\n黼坐临轩清跸奏，天仗缀行森肃。\n望五色、云浮黄屋。\n三策忠嘉亲赐擢，动龙颜、人立班头玉，胪首唱，众心服。\n殿头赐宴宫花簇。\n写新诗、金笺竞进，绣床争蹙。\n御渥新沾催进谢，一点恩袍先绿。\n归袖惹、天香芬馥。\n玉勒金鞯迎夹路，九街人、尽道苍生福。\n争拥入，状元局。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16810, '沁园春', '姚勉', '忆昔东坡，秀夺眉山，生丙子年。\n盖丙离子坎，四方中气，宜当此岁，间出英贤。\n河岳重灵，星辰再孕，来自赤城中洞天。\n新秋霁，萃一襟爽气，风露澄鲜。\n玉阶同听胪传。\n伴宝马如龙丝袅鞭。\n正椿庭未老，同跻荣路，萼楼争耀，相照魁躔。\n即似坡公，金莲夜对，身作玉堂云雾仙。\n怜同岁，但乞如梦得，分买山钱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16811, '贺新郎', '姚勉', '唱彻阳关调。\n伴行人、梅拂征鞍，晓霜寒峭。\n金甲雕戈开玉帐，尊俎风流谈笑。\n看策马、从容江表。\n自是药阶苔砌客，卷经纶、且泛芙蓉沼。\n襟量阔，江面小。\n允文事业从容了。\n要岷峨人物，後先相照。\n见说君王曾有问，似此人才多少。\n便咫尺、云霄清要。\n四世三公毡复旧，况蜀珍、先已登廊庙。\n但侧耳，听新诏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16812, '念奴娇', '姚勉', '雕裘夜冷，怪地炉煨酒，经时难热。\n晓起盘风天舞絮，拍手儿童欢悦。\n客里新吟，天葩翦巧，思与梅争发。\n使君属和，雪花同是三绝。\n未说赋就梁园，阳春拍调，压倒唐元白。\n早晚联镳花底去，共看朝霞银阙。\n朝退归来，清虚堂里，醉洒淋漓墨。\n而今且对，聚星堂上宾客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16813, '沁园春', '姚勉', '四海中间，第一清流，惟有可斋。\n看平生践履，真如冰玉，雄文光焰，不尘埃。\n元诸贤，纷纷台省，惟有景仁招不来。\n狂澜倒，独中流砥柱，屹立崔嵬。\n挂冠有请高哉。\n但清庙正需梁栋材。\n便撑舟野水，出航巨海，有官鼎鼐，无地楼台。\n制菊龄高，看萸人健，万顷秋江入寿杯。\n经纶了，却驭风骑气，阆苑蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16814, '满江红', '姚勉', '仙苑蟠桃，恰则是、而今初熟。\n王母遣、飞琼捧献，绛金红玉。\n笑把九霞鸾凤，满斟七宝蒲萄。\n为长庚、此日自天来，殷勤祝。\n仙子唱，长生曲。\n仙客献，长生。\n活千人邓禹，阴功俱足。\n五鹗即齐公府剡，万羊自有中书禄。\n更从头、安享八千年，人间福。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16815, '沁园春', '姚勉', '梅笑东风，只两日间，又新岁华。\n有玉龟阿母，献三蟠实，蕊宫仙子，飞七香车。\n春满虾帘，雪晴鸳瓦，窗户非烟笼翠纱。\n萱堂上，看衣翻戏彩，觞捧流霞。\n君家。\n元是仙家。\n几度看菖蒲九节花。\n来剑池丹井，平分风月，一溪流水，犹泛胡麻。\n寿庆千秋，荣封两国，绿鬓犹深杨柳鸦。\n长生药，在蓬莱顶上，不必丹砂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16816, '水调歌头', '姚勉', '桃李河阳县，春又到花枝。\n先庚三日，鳌山晴雪放灯时。\n金宿争华玉婺，来入仙闺清梦，光动绣湖西。\n人物东都令，句法晚唐诗。\n两年春，三种异，十般奇。\n朝天近也，紫泥催起凫飞。\n总羡童颜绿发，荣绾金鱼玉带，日侍赭黄衣。\n来岁传柑宴，人在赏花池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16817, '水调歌头', '姚勉', '微雪弄新霁，寒月上初弦。\n长庚入梦，间生采石锦袍仙。\n分得天孙云织，掣断麒麟金锁，来自玉皇前。\n丹井凭泥轼，风月兴无边。\n诏书来，催入觐，占春先。\n柳边花底，细驺辇路骤鸣鞭。\n荣侍金銮殿上，更向沉香亭北，半醉拂华笺。\n来岁今朝里，人在八花砖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16818, '满江红', '姚勉', '万里西风，吹送到、五云鸾纸。\n□催促、文章太守，入朝花底。\n清节高横秋一片，仁风散作春千里。\n漾恩波、溶泳锦江中，深如水。\n难卧辙，留行李。\n但侧听，星辰履。\n看麒麟案侧，即催荣侍。\n红药香中翻诏草，紫薇影畔裁诗绮。\n更宸旒、已自覆公名，金瓯里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16819, '沁园春', '姚勉', '万里清风，吹送锦帆，入南浦云。\n看拂天旌旆，攀留不住，迷津舸舰，歌舞相迎。\n二许家声，三洪地望，今代风流第一人。\n蜚英早，合词林视草，书阁翻芸。\n飞刍远饷三军。\n特借作红莲入幕宾。\n把西山暮雨，暂时收卷，荷山明月，小试平分。\n苏醒枯鱼，剔除深蠹，个是人间有脚春。\n难淹久，看诏催入侍，香案麒麟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16820, '水龙吟', '姚勉', '芰荷香雨初收，竹风槐日凉清晓。\n年年祝寿，今年不比，常年时候。\n教子收功，五云金殿，初承亲诏。\n早胪传三日，寿称千岁，多应是、如公少。\n遥想寿椿堂上，饮霞觞、捧孙微笑。\n已见儿荣，更看孙贵，茅分蒲召。\n上第归来，彩衣挂绿，兰阶生耀。\n九霄中、一点光明，寿星高照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16821, '沁园春', '姚勉', '一叶新凉，又是西风，吹转素商。\n揽玉壶英气，锺为人物，银河精采，融作文章。\n司巧天公，搀先七夕，分付天孙云锦裳。\n骑龙凤，自九霄飞至，万丈光芒。\n早年奏赋长杨。\n饱挹尽瀛洲风露香。\n问石渠天禄，借将班马，荷山锦水，暂作龚黄。\n药省春风，薇垣夜月，合佩仙花侍玉皇。\n明年里，饮寿椒何处，宣劝持觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16822, '沁园春', '姚勉', '鹤发鸦髫，欢捧霞觞，酌丹井泉。\n庆湘山峰顶，飞来古佛，剑池洞里，活底神仙。\n春雨悭时，千金斗粟，民仰使君为食天。\n公知否，只活人阴德，合寿千年。\n宝猊香喷沈烟。\n环艳翠明红拥寿筵。\n最一般奇特，凤雏新贵，斑衣绿绶，光彩相鲜。\n帝命师臣，钦哉有子，飞诏看看又月边。\n黄封酒，到明年今日，中使传宣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16823, '沁园春', '姚勉', '超逸天才，文如三松，诗如卢溪。\n自白莲赋就，已高声价，梅花句出，远见襟期。\n玉尘精神，瑶林风韵，雪里神仙小氅衣。\n缑山夕，已再经旬浃，戏鹤重归。\n花间凫轻飞。\n便一似元规报十奇。\n最风流膝上，双亲未老，三槐手种，分付佳儿。\n人想夷吾，帝思王某，钧轴舍人知未迟。\n长生药，在玉盘麟脯，琼苑蟾芝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16824, '沁园春', '姚勉', '摘玉蕊梅，泛金叶蕉，祝公寿龄。\n算今年比似，常年更别，翠烟红雾，香霭门屏。\n凤诏云霄，龙光牛斗，辉射南州孺子亭。\n看看是，伴元戎小队，花柳郊。\n传家有子明经。\n浑不要黄金遗满。\n向月中传与，一枝仙桂，斓斑衣上，更著袍青。\n明日瓜期，今朝椿寿，好醉芝兰玉树庭。\n公知否，老人星一点，映泰阶星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16825, '贺新郎', '姚勉', '冷眼三边处。\n喜舍人、水滨跃马，上京西路。\n三国英雄千载矣，形胜依然如故。\n这勋业、向谁分付。\n袖里翰林风月手，也何妨、戮力风寒护。\n谈笑暇，诗吟虏。\n岘山几载无人顾。\n幸如今、翦除荆棘，扫清飚雾。\n换得东南新局面，政欠十分著数。\n算人物、须还羊杜。\n玉帐筹边机会好，把规模、赶出中原去。\n天下事，书生做。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16826, '沁园春', '姚勉', '崧岳降神，昴宿宣精，挺生伟人。\n整淳乾坤，浸如嘉，太平事业，了却端平。\n扶日中天，拱辰北极，一洒甘霖埃雾清。\n春寰海，听农歌载路，边柝沈声。\n旗常万世勋铭。\n便与国无穷垂令名。\n似青山流水，涑川贤相，黄花晚节，魏国元臣。\n五纬芒寒，六符色正，辉映老人南极星。\n苍生福，开八荒寿域，一气洪钧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16827, '沁园春', '姚勉', '章武中兴，淮蔡欲平，晋公已生。\n信天生英杰，正为国计，擎天著柱，要自支撑。\n万里长江，古称天险，去岁里风涛忽震惊。\n公谈笑，把云腥霓翳，一日都清。\n归来奠枕于京。\n有辉焕明堂前一星。\n称衮衣廊庙，枫宸眷宠，彩衣公府，萱砌春荣。\n著片公心，辨双明眼，长与群贤扶太平。\n无它愿，植万年宗社，万古功名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16828, '沁园春', '姚勉', '湖海元龙，逸气飘然，可百尺楼。\n爱文光万丈，星辰绚彩，爽襟一掬，风露澄秋。\n衔字冰清，班心玉立，海内而今第一流。\n书子，紫薇花浸月，夜揽词头。\n著身已是瀛洲。\n问更有长生别药不。\n是生来已带，神仙道骨，毫端自有，富贵封侯。\n拜赐黄封，承恩青琐，见说香名又覆瓯。\n从今去，了福公事业，从赤松游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16829, '沁园春', '姚勉', '道骨仙风，海上骑鲸，端是後身。\n把银河天巧，锺为文采，剑津宝气，融作精神。\n壶玉储冰，掌金擎露，胸次全无一点尘。\n年年里，早花朝六日，长庆生申。\n篁濯锦江滨。\n人尽道如公清最真。\n合沉香亭北，金笺奏曲，恩披兽锦，醉拭龙巾。\n泥紫颁来，渠黄飞去，自是八花砖上人。\n从後看，大钧播物，万象皆春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16830, '沁园春', '姚勉', '明月扁舟，轻逐江鸥，翩然赋归。\n任颠风掀舞，涛山浪屋，少顷平定，一碧硫璃。\n柳絮浮云，有无根蒂，到底不磨真是非。\n呵呵笑，笑人情似纸，世事如棋。\n宜堂事事皆宜。\n把杯酒论文更有谁。\n记风云满席，吟情浩荡，龙蛇满壁，醉墨淋漓。\n别後相思，有书寄否，春在梅花第一枝。\n重相见，约柳堤撑舫，竹阁寻诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16831, '沁园春', '姚勉', '拂剑整装，光射紫霄，斗牛色寒。\n大丈夫不作，儿曹离别，何须更唱，三叠阳关。\n尽锦还乡，油幢佐幕，谁道青天行路难。\n从今去，听声名焰焰，飞动岷山。\n征途少饮加餐。\n要做取功名久远看。\n卷长风吹醒，剑关云气，更须砥柱，三峡惊湍。\n闻道槐庭，已登安石，此去须弹贡禹冠。\n明年里，踏梅花有分，相见长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16832, '声声慢', '姚勉', '江涵石瘦，雪压桥低，森森万木寒僵。\n不是争魁，百花谁敢先芳。\n冰姿皎然玉立，笑儿曹、粉面何郎。\n调羹鼎，只此花馀事，说甚宫妆。\n松竹岁寒三友，恨竹汗晋士，松秦皇。\n雪魄冰魂，回首世上无香。\n西湖有人觅句，但知渠、清浅黄昏。\n奇绝处，五更初、横月带霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16833, '柳梢青', '姚勉', '长记西湖，水光山色，浓淡相宜。\n丰乐楼前，涌金门外，买个船儿。\n而今又是春时。\n清梦只、孤山赋诗。\n绿盖芙蓉，青丝杨柳，好在苏堤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16834, '贺新郎', '姚勉', '薄晚收残暑。\n叹西风、暗换流年，又还如许。\n鸦背斜阳初敛影，云淡新凉天宇。\n人袖手、阑干凝伫。\n邻笛唤将乡思动，听秋声、又入梧桐雨。\n秋到也，尚羁旅。\n故人只在江南渚。\n想应嫌、久恋东华，软红尘土。\n寄远裁衣知念否，新月家家砧杵。\n魂梦想、鹅黄金缕。\n雁影不来天更远，写书成、欲寄恁谁与。\n知客恨，两蛩语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16835, '贺新凉・贺新郎', '姚勉', '窗月梅花白。\n夜堂深、烛摇红影，绣帘垂额。\n半醉金钗娇应坐，寒处也留春色。\n深意在、四弦轻摘。\n香坞花行听啄木，翠微边、细落仙人屐。\n星盼转，趁娇拍。\n人间此手真难得。\n向尊前、相逢有分，底须相识。\n愁浅恩深千万意，惆怅故人云隔。\n怕立损、弓鞋红窄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16836, '摸鱼儿', '陈允平', '倚东风、画阑十二，芳阴帘幕低护。\n玉屏翠冷梨花瘦，寂寞小楼烟雨。\n肠断处。\n怅折柳柔情，旧别长亭路。\n年华似羽。\n任锦瑟声寒，琼箫梦远，羞对彩莺舞。\n文园赋。\n重忆河桥眉妩。\n啼痕犹溅纨素。\n丁香共结相思恨，空托绣罗金缕。\n春已暮。\n踪燕约莺盟，无计留春住。\n伤春倦旅。\n趁暗绿稀红，扁舟短棹，载酒送春去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16837, '木兰花慢', '陈允平', '杜鹃声渐老，过花信、几番风。\n爱翠幄笼晴，文梭扬暖，阑槛青红。\n新妆步摇未稳，捧心娇、乍入馆娃宫。\n消得金壶万朵，护风帘幄重重。\n匆匆。\n少小忆相逢。\n诗鬓已成翁。\n且持杯秉烛，天香院落，同赏芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16838, '绛都春', '陈允平', '秋千倦倚，正海棠半坼，不耐春寒。\n雨弄晴，飞梭庭院绣帘闲。\n梅妆欲试芳情懒。\n翠颦愁入眉弯。\n雾蝉香冷，霞绡泪，恨袭湘兰。\n悄悄池台步晚。\n任红薰杏靥，碧沁苔痕。\n燕子未来，东风无语又黄昏。\n琴心不度春云远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16839, '酹江月・念奴娇', '陈允平', '汉江露冷，是谁将瑶瑟，弹向云中。\n一曲清泠声渐杳，月高人在珠宫。\n晕额黄轻，涂腮粉艳，罗带织青葱。\n天香吹散，佩环犹自丁东。\n回首杜若汀洲，金钿玉镜，何日得相逢。\n独立飘飘烟浪远，袜尘羞溅春红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16840, '倦寻芳', '陈允平', '杏檐转午。\n青漏沈沈，春梦无据。\n凤锦龟纱，空闭酒尘香雾。\n流水行云天四远，玉箫声断人何处。\n倦寻芳，镇情尖翠压，强拈飞絮。\n记旧约、荼縻开後，屈指心期，数了还数。\n误我凭阑，几度片帆南浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16841, '大', '陈允平', '渐入融和，金莲放、人在东风楼阁。\n天香吹辇路，净无云一点，桂柳霜魄。\n雪霁梅飘，春柔柳嫩，半卷真珠帘箔。\n迢迢鸣鞘过，隘车钿辔玉，暗尘轻掠。\n拥琼管吹龙，朱弦弹凤，柳衢花陌。\n鳌山侵碧落。\n绛绡远，春霭浮鹊。\n民共乐、金吾禁静，翠跸声闲，遍青门、尽停鱼钥。\n衩袜寒初觉。\n方怪失、绣鸳弓窄。\n误良夜、瑶台约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16842, '永遇乐', '陈允平', '玉腕笼寒，翠阑凭晓，莺调新簧。\n暗水穿苔，游丝度柳，人静芳昼长。\n云南归雁，楼西飞燕，去来惯认炎凉。\n王孙远，青青草色，几回望断柔肠。\n蔷薇旧约，尊前一笑，等闲孤负年光。\n斗草庭空，抛梭架冷，帘外风絮香。\n伤春情绪，惜花时候，日斜尚未成妆。\n闻嬉笑，谁家女伴，又还采桑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16843, '月上海棠', '陈允平', '游丝弄晚，卷帘看处，燕重来时候。\n正秋千亭榭，锦窠春透。\n梦回褪浴华清，凝温泉、绛绡微皱。\n芳阴底，人立东风，露华如昼。\n宜酒。\n啼香泪薄，醉玉痕深，与春同瘦。\n想当年金谷，步帷初绣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16844, '疏影', '陈允平', '千峰翠玉。\n送孤云伴我，罗窗清宿。\n拂晓凭虚，春碧生寒，衣单瘦倚筇竹。\n东风不解吹愁醒，但芳草、溪城南北。\n认雾鬟，遥锁修颦，眉妩为谁愁独。\n江上轻鸥似识，背昭亭两两，飞破晴渌。\n一片苍烟，隔断家山，梦绕石窗萝屋。\n相看不厌朝还暮，算几度、赤阑干曲。\n待倩诗、收拾归来，写作卧游屏幅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16845, '暗香', '陈允平', '霁天秋色。\n正倚楼待月，谁伴横笛。\n涨绿浮空，闲数河星手堪摘。\n弥望澄光练净，分付与、玄晖才笔。\n烟溆阔，云远波平，归鸟趁风席。\n南国。\n信音寂。\n怅雁渚渡闲，鹭汀沙积。\n藓碑露泣。\n时拊遗踪暗嗟忆。\n人事空随逝水。\n今古但、双流一碧。\n待办取、蓑共笠，小舟泛得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16846, '水龙吟', '陈允平', '杜鹃啼老春愁，泪痕吹作胭脂雨。\n飞花乱点，东风枝上，红翔翠翥。\n丹穴鸣初，碧梧栖未，凄凉山坞。\n怅琼姬梦远，玉箫声断，孤鸾影、对谁舞。\n林下风光自许。\n算何必、玉京瑶圃。\n阑干醉倚，游尘香散，芳菲无主。\n经院僧眠，月楼钟静，欲飞还驻。\n待青松、化尽苍龙头角，共乘云去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16847, '齐天乐', '陈允平', '湖光祗在阑干外，凭虚远迷三楚。\n旧柳犹青，平芜自碧，几度朝昏烟雨。\n天涯倦旅。\n爱小却游鞭，共挥谈尘。\n顿觉尘清，宦情高下等风絮。\n芝山苍翠缥缈，黯然仙梦杳，吟思飞去。\n故国楼台，斜阳巷陌，回首白云何处。\n无心访古。\n对双塔栖鸦，半汀归鹭。\n立尽荷香，月明人笑语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16848, '酹江月・念奴娇', '陈允平', '霁空虹雨，傍啼莎草，宿鹭汀洲。\n隔岸人家砧杵急，微寒先到帘钩。\n步幄尘高，征衫酒润，谁暖玉香篝。\n风灯微暗，夜长频换更筹。\n应是雁柱调筝，鸳梭织锦，付与两眉愁。\n不似尊前今夜月，几度同上南楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16849, '桂枝香', '陈允平', '残蝉乍歇。\n又乱叶打窗，蛩韵凄切。\n寂寞天香院宇，露凉时节。\n乘鸾扇底婆娑影，幻清虚、广寒宫阙。\n小山秋重，千岩夜悄，举尊邀月。\n甚赋得、仙标道骨。\n倩谁捣玄霜，犹未成屑。\n回首蓝桥路迥，梦魂飞越。\n雕阑翠金英满，洒西风、非雨非雪。\n惜花心性，输他少年，等闲攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16850, '汉宫春', '陈允平', '开尽荼シ，正桑云麦浪，天气如秋。\n南园露梢半坼，金粟丝头。\n温香傍酒，尽多娇、不识春愁。\n莺院悄，轻阴弄晚，何人堪伴清游。\n偏爱紫蕤黄袅，想金壶胜赏，依旧扬州。\n花前夜阑醉後，斜月当楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16851, '木兰花慢', '陈允平', '爱吟休问瘦，为诗句、几凭阑。\n有可画亭台，宜春帐箔，如寄身闲。\n胸中四时胜景，小蓬莱、幻出五云间。\n一掬苹香暗沼，半梢松影虚坛。\n相看。\n倦羽久知还。\n回首鹭盟寒。\n记步寻云，呼灯听雨，越岭吴峦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16852, '宝鼎见・宝鼎现', '陈允平', '六鳌初驾，缥缈蓬阆，移来洲岛。\n还又是、梅飘冰泮，一夜青阳回海表。\n渐媚景、傍元宵时候，花底馀寒料峭。\n更喜报、三边晏静，人乐清平宇宙。\n画鼓簇队行春早。\n拥烟花、粉黛缭绕。\n开洞府、桃源路窈。\n戟外东风吹岸柳。\n正翠霭、映星桥月榭，十里红莲绽了。\n庆万家、珠帘半卷，绰约歌裙舞袖。\n重锦绣幄围香，阖凤管鸾丝环奏。\n望非烟非雾，春在壶天易晓。\n早隐隐、半空星斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16853, '八宝妆', '陈允平', '望远秋平。\n初过雨、微茫水满烟汀。\n乱疏柳，犹带数点残萤。\n待月重帘谁共倚，信鸿断续两三声。\n夜如何，顿凉骤觉，纨扇无情。\n还思骖莺素约，念凤箫雁瑟，取次尘生。\n旧日潘郎，双鬓半已星星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16854, '昼锦堂', '陈允平', '上苑寒收，西塍雨歇，东风是处花柳。\n步锦笼纱，依旧五陵台沼。\n绣帘珠箔金翠袅，琐窗雕槛青红斗。\n频回首。\n茶灶酒垆，春时几番携手。\n知否。\n人渐老。\n嗟眼为花狂，肩为诗瘦。\n唤醒乡心，无奈数声啼鸟。\n秉烛清游嫌夜短，采香新意输年少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16855, '绮罗香', '陈允平', '雁宇苍寒，蛩疏翠冷，又是凄凉时候。\n小揭珠帘，夜润唾花罗皱。\n饶晓鹭、独立衰荷，溯归燕、尚栖残柳。\n想黄花，羞涩东篱，断无新句到重九。\n孤檠清梦易觉，肠断唐宫旧曲，声迷官漏。\n滴入愁心，秋似玉楼人瘦。\n烟槛外、催落梧桐，带西风、乱捎鸳。\n记画檐，灯影沈沈，共裁春夜韭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16856, '探春・探春慢', '陈允平', '上苑乌啼，中洲鹭起，疏钟才度云窈。\n篆冷香篝，灯微尘幌，残梦犹吟芳草。\n搔首卷帘看，认何处、六桥烟柳。\n翠绕才舣西泠，趁取过湖人少。\n掠水风花缭绕。\n还暗忆年时，旗亭歌酒。\n隐约春声，钿车宝勒，次第凤城开了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16857, '秋霁', '陈允平', '千顷玻璃，远送目斜阳，渐下林阒。\n题叶人归，采菱舟散，望中水天一色。\n碾空桂魄。\n玉绳低转云无迹。\n有素鸥，闲伴夜深，呼棹过环碧。\n相思万里，顿隔婵媛，几回琼台，同驻鸾翼。\n对西风、恁谁问取，人间那得有今夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16858, '百字令・念奴娇', '陈允平', '凝云冱晓，正シ花才积，荻絮初残。\n华表翩跹何处鹤，爱吟人在孤山。\n冻解苔铺，冰融沙，谁凭玉勾阑。\n茸衫毡帽，冷香吹上吟鞍。\n将次柳际琼销，梅边粉瘦，添做十分寒。\n闲踏轻澌来荐菊，半潭新涨微澜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16859, '扫花游・扫地游', '陈允平', '数峰蘸碧，记载酒甘园，柳塘花坞。\n最堪避暑。\n爱莲香送晚，翠娇红妩。\n乃菱歌乍起，兰桡竞举。\n日斜处。\n望孤鹜断霞，初下芳杜。\n遥想山寺古。\n看倒影金轮，溯光朱户。\n瞑烟带树。\n有投林鹭宿，凭楼僧语。\n可惜流年，付与朝钟暮鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16860, '八声甘州', '陈允平', '放船杨柳下，听鸣蝉、薰风小新堤。\n正烟露蓼，飞尘酿玉，第五桥西。\n遥认青罗盖底，宫女夜游池。\n谁在鸳鸯浦，独棹玻璃。\n一片天机云锦，见凌波碧翠，照日胭脂。\n是西湖西子，晴抹雨妆时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16861, '蓦山溪', '陈允平', '春波浮渌，小隐桃溪路。\n烟雨正林塘，翠不碍、锦鳞来去。\n芹香藻腻，偏爱鲤花肥，檐影下，柳阴中，逐浪吹萍絮。\n宫沟泉滑，怕有题红句。\n钩饵已忘机，都付与、人间儿女。\n濠梁兴在，鸥鹭笑人痴。\n三湘梦，五湖心，云水苍茫处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16862, '齐天乐', '陈允平', '赤阑桥畔斜阳外，临江暮山凝紫。\n戏鼓才停，渔榔乍歇，一片芙蓉秋水。\n馀霞散绮。\n正银钥停关，画船催舣。\n鱼板敲残，数声初入万松里。\n坡翁诗梦未老，翠微楼上月，曾共谁倚。\n御苑烟花，宫斜露草，几度西风弹指。\n黄昏尽也，有眠月闲僧，醉香游子。\n鹫岭啼猿，唤人吟思起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16863, '黄莺儿', '陈允平', '六波烟黛浮空远，南陌嘤嘤，乔木初迁，纱窗无眠，画阑凭晓。\n看并宿暗黄深，织雾金梭小。\n那人携酒听时，料把春来，诗梦惊觉。\n飞绕。\n翠接断桥云，绿漾新堤草。\n数声娇啭，婉娩如愁，调簧弄歌尖巧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16864, '渡江云', '陈允平', '三神山路杳，六鳌驾浪，幻境□西湖。\n水连天四远，翠台如鼎，簇簇小浮图。\n烟沈雾迥，怪蜃楼、飞入清虚。\n秋夜长，一轮蟾素，渐渐出云衢。\n遥看寒光金镜，皓彩明，正人间三五。\n总输与、鸥眠葑蓼，鹭立菰蒲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16865, '婆罗门引', '陈允平', '髻鬟对耸，万松扶玉上青冥。\n西风共倚，烟南水北，石荒苔老，三十六梯平。\n爱翠尖如削，天外亭亭。\n高寒梦惊。\n是何夕堕双星。\n无限苍崖紫岫，谁拊棱层。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16866, '明月引・江城梅花引', '陈允平', '雨馀芳草碧萧萧。\n暗春潮。\n荡双桡。\n紫凤青鸾，旧梦带文箫。\n绰约佩环风不定，云欲堕，六铢香，天外飘。\n相思为谁兰恨销。\n渺湘魂、无处招。\n素纨犹在，真真意、还倩谁描。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16867, '糖多令・唐多令', '陈允平', '何处是秋风。\n月明霜露中。\n算凄凉、未到梧桐。\n曾向垂虹桥上看，有几树、水边枫。\n客路怕相逢。\n酒浓愁更浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16868, '江城子', '陈允平', '东风吹恨上眉弯。\n燕初还。\n杏花残。\n帘里春深，帘外雨声寒。\n拾翠芳期孤负却，空脉脉，倚阑干。\n流苏香重玉连环。\n绕屏山。\n宝筝闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16869, '思佳客', '陈允平', '一曲清歌酒一锺。\n舞裙摇曳石榴红。\n宝筝弦矗冰蚕缕，珠箔香飘水麝风。\n娇娅姹，笑迎逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16870, '思佳客', '陈允平', '压鬓钗横翠凤头。\n玉柔春腻粉香流。\n红酣醉靥花含笑，碧翦颦眉柳弄愁。\n偏婀娜，太温柔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16871, '思佳客', '陈允平', '锦幄沉沉宝篆残。\n惜春无语凭阑干。\n庭前芳草空惆怅，帘外飞花自往还。\n金屋静，玉箫闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16872, '思佳客', '陈允平', '玉辔青骢去不归。\n锦中频织断肠诗。\n窗凭绣日莺声婉，帘卷香云雁影回。\n金缕扇，碧罗衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16873, '思佳客', '陈允平', '曾约双琼品凤箫。\n玉台光映玉娇娆。\n银花烛冷飞罗暗，宝悄香融曲篆销。\n帘影乱，漏声迢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16874, '惜分飞', '陈允平', '钏阁桃腮香玉溜。\n困倚银床倦绣。\n双燕归来後。\n相思叶底寻红豆。\n碧唾春衫还在否。\n重理弓弯舞袖。\n锦藉芙蓉皱。\n翠腰羞对垂杨瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16875, '长相思', '陈允平', '风萧萧。\n雨骚骚。\n风雨萧骚梧叶飘。\n潇湘江畔楼。\n云迢迢。\n水遥遥。\n云水迢遥天尽头。\n相思心上秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16876, '祝英台近', '陈允平', '待春来，春又到，花底自徘徊。\n春浅花迟，携酒为春催。\n可堪碧小红微，黄轻紫艳，东风外、妆点池台。\n且衔杯。\n无奈年少心情，看花能几回。\n春自年年，花自为春开。\n是他春为花愁，花因春瘦，花残後、人未归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16877, '恋绣衾', '陈允平', '缃桃红浅柳褪黄。\n燕初来、宫漏渐长。\n任日转、花梢也，倚兰屏、犹未试妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16878, '南歌子', '陈允平', '素质盈盈瘦，娇姿淡淡妆。\n曲勾兰畔倚秋娘。\n一撮风流都在、晚西凉。\n彩线串层玉，金篝络细香。\n半钩新月浸牙床。\n犹记东华年少、那门相。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16879, '恋绣衾', '陈允平', '银鸳金凤画暗销。\n晓帘栊、新翠渐交。\n算多少、相思恨，被东风，吹上柳梢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16880, '谒金门', '陈允平', '春欲去。\n无计得留春住。\n纵著天涯浑柳絮。\n春归还有路。\n恨煞多情杜宇。\n愁煞无情风雨。\n春自悠悠人自苦。\n莺花谁是主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16881, '菩萨蛮', '陈允平', '杏花枝上莺声嫩。\n凤屏倦倚人初困。\n金兽莫添香。\n香浓情转伤。\n云沉归雁杳。\n绿涨江南草。\n独倚夕阳楼。\n双帆何处舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16882, '青玉案', '陈允平', '凉亭背倚斜阳树。\n过几阵、菰蒲雨。\n自棹轻舟穿柳去。\n绿裙红袂，与花相似，撑入花深处。\n妾家住在鸳鸯浦。\n妾貌如花被花妒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16883, '恋绣衾', '陈允平', '多情无语敛黛眉。\n寄相思、偏仗柳枝。\n待折向、尊前唱，奈东风、吹做絮飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16884, '南歌子', '陈允平', '懒傍青鸾镜，慵簪翠凤翘。\n玉屏春重宝香销。\n因甚不梳洗、怕登楼。\n载酒垂杨浦，停桡杜若洲。\n伤春情绪寄箜篌。\n流水残阳芳草、伴人愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16885, '醉桃源・阮郎归', '陈允平', '东风开到坼桐花。\n游蜂初报衙。\n兽环微掩是谁家。\n琐窗金绣纱。\n环佩小，领巾斜。\n绿云双髻鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16886, '清平乐', '陈允平', '凤城春浅。\n寒压花梢颤。\n有约不来梁上燕。\n十二绣帘空卷。\n去年共倚秋千。\n今年独倚阑干。\n误了海棠时候，不成直待花残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16887, '谒金门', '陈允平', '春又晚。\n枝上绿深红浅。\n燕语呢喃明似翦。\n采香人渐远。\n草色池塘碧软。\n丝竹谁家坊院。\n拂拂和风初著扇。\n蜂情愁不展。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16888, '浣溪沙', '陈允平', '杨柳烟深五凤楼。\n绣帘风扬玉梭球。\n夜寒谁伴锦香篝。\n残月情圆晓梦，落花无语诉春愁。\n宝笙偷按小梁州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16889, '鹧鸪天', '陈允平', '谁向瑶台品凤箫。\n碧虚浮动桂花秋。\n风从帘幕吹香远，人在阑干待月高。\n金粟地，蕊珠楼。\n佩云襟雾玉逍遥。\n仙娥已有玄霜约，便好骑鲸上九霄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16890, '谒金门', '陈允平', '风不定。\n吹漾一帘波影。\n归燕无期春正永。\n海棠眠未醒。\n筝雁别来谁整。\n好梦不堪重省。\n闲看鸳鸯交素颈。\n凭阑襟袖冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16891, '朝中措', '陈允平', '欲晴又雨雨还晴。\n时节又清明。\n红杏墙头燕语，碧桃枝上莺声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16892, '小重山', '陈允平', '岸柳黄深绿渐饶。\n林塘初雨过，涨蒲萄。\n秋千亭榭彩旗交。\n莺声里，春在杏花梢。\n慵整翠云翘。\n眉尖愁两点，倩谁描。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16893, '霜天晓角', '陈允平', '玄霜绛雪。\n散作秋林缬。\n昨夜西风吹过，最好是、睡时节。\n香绝。\n高处折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16894, '糖多令・唐多令', '陈允平', '明月可中庭。\n萧萧络纬声。\n画阑秋、千树吹香。\n玉宇无尘凉似水，销不尽、许多清。\n欲醉醉还醒。\n欲吟吟未成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16895, '柳梢青', '陈允平', '藓迹苔痕。\n香浮砚席，影蘸吟尊。\n雪正商量，同云淡淡，微月昏昏。\n孤山往事谁论。\n但招得、逋仙断魂。\n客里相逢，数枝驿路，千树江村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16896, '柳梢青', '陈允平', '沁月凝霜。\n精神好处，曾悟花光。\n带雪煎茶，和冰酿酒，聊润枯肠。\n看花小立疏廊。\n道是雪、如何恁香。\n几度巡檐，一枝清瘦，疑在蓬窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16897, '柳梢青', '陈允平', '菊谢东篱。\n问梅开未，先问南枝。\n两蕊三花，松边傍石，竹外临溪。\n尊前暗忆年时。\n算笛里、关情是伊。\n何逊风流，林逋标致，一二联诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16898, '柳梢青', '陈允平', '片片花飞。\n风前疏树，雪後残枝。\n地多情，带将明月，来伴书帏。\n岁寒心事谁知。\n向篱落、微斜半。\n添得闲愁，酒将阑处，吟未成时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16899, '思佳客', '陈允平', '簇簇红云冷欲凝。\n东风特地唤花醒。\n数枝夜色当银烛，一段春娇入画屏。\n如有恨，似多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16900, '糖多令・唐多令', '陈允平', '休去采芙蓉。\n秋江烟水空。\n带斜阳、一片征鸿。\n欲顿闲愁无顿处，都著在两眉峰。\n心事寄题红。\n画桥流水东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16901, '瑞龙吟', '陈允平', '双溪墅。\n重见种玉锄云，采花研露。\n遥知绿野芳浓，锦堂燕子，迎门共舞。\n近前语。\n还问去年山馆，旧经行处。\n西风鸿水边上，惊千里苑，梅英乍吐。\n几度月昏霜晓，望驰天北，驿传湘渚。\n冷艳暗香春寒，地清苦。\n看看翠幄，青子江头路。\n才收尽、蛮烟瘴雨，初回轻暑。\n便忆南园趣。\n唤人况有，多情杜宇。\n此计非迟暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16902, '渡江云', '陈允平', '桐花寒食近，青门紫陌，不禁绿杨烟。\n正长眉仙客，来向人间，听鹤语溪泉。\n清和天气，为栽培、种玉心田。\n莺昼长，一尊芳酒，容与看芝山。\n庭闲。\n东风榆荚，夜雨苔痕，满地欲流钱。\n爱墙阴、成蹊桃李，春自无言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16903, '八声甘州', '陈允平', '两台帘对卷，燕芹香、风花近清明。\n望春弥柳际，流红水布，暖天晴。\n谁信闲襟似水，时忆语溪耕。\n襟抱番江阔，云远波平。\n静昼轻挥玉尘，见春扉草绿，暮冶烟青。\n问清华姓字，几度录虬屏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16904, '三犯渡江云・渡江云', '陈允平', '风流三径远，此君淡薄，谁与伴清足。\n岁寒人自得，傍石锄云，闲里种苍玉。\n琅翠立，爱细雨、疏烟初沐。\n春昼长，秋声不断，洗红尘凡俗。\n高独。\n虚心共许，淡节相期，几人闲棋局。\n堪爱处，月明琴院，雪晴书屋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16905, '过秦楼', '陈允平', '谷雨收寒，茶烟扬晓，又是牡丹时候。\n浮龟碧水，听鹤丹山，彩屋幔亭依旧。\n和气缥缈人间，满谷红云，德星呈秀。\n向东风种就，一亭兰茁，玉香初茂。\n遥想曲度娇莺，舞低轻燕，二十四帘芳昼。\n清溪九曲，上已风光，觞咏似山阴否。\n翠阁凝清，正宜瀹茗银罂，熨香金斗。\n看双鸾飞下，长生殿里，赐蔷薇酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16906, '醉蓬莱', '陈允平', '正槐龙欲老，影动朱门，薰风帘卷。\n竹外人清，听秋声将转。\n梦草池塘，种兰庭砌，爽气生葵扇。\n香染黄扉，律调翠简，赏音清宴。\n因念南阳，碧幢烟静，纶玉宣频，辔丝催遣。\n带锡犀虹，宠下甘泉殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16907, '法曲献仙音', '陈允平', '风箨晴暄，昼桐阴早，燕阁新香时度。\n沁月楼台，带山城郭，西湖翠娇红妩。\n甚爱此闲中趣，寻盟旧鸥鹭。\n共容与。\n倚阑干、静看飞絮。\n吟啸里，帘卷暖烟霁雨。\n向一碧波璃，几东风、呼棹来去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16908, '八声甘州', '陈允平', '帘垂鸱尾阁，桂花风、天香满黄扉。\n向郁罗霄汉，朝回金阙，心运璇玑。\n一点元台初度，八表共清辉。\n紫塞烟尘静，捷羽东飞。\n此际钱塘江上，爱月仍夜色，潮正秋期。\n想波仙冰妹，同日宴瑶池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16909, '兰陵王', '陈允平', '楚天碧。\n秋晚尘清禁陌。\n朝鸡静，班退晓墀，回马金门漏犹滴。\n千官佩如织。\n来作黄扉寿客。\n黑头相，玉虹紫貂，亲奉春慈拜南极。\n丛萱燕堂北。\n正霭护犀帷，香泛鲛额。\n瑶池女伴驻鸾翼。\n拥歌袖笼翠，舞鞯铺锦，屏开家庆怎画得。\n想人在仙宅。\n今夕。\n是何夕。\n正月满槐厅，凉透席。\n黄花满地弄寒色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16910, '木兰花慢', '陈允平', '江南春信早，问谁是、百花魁。\n过揽桂褰蓉，纫兰采菊，独许寒梅。\n阳和渐回涧底，向水西、先放一枝开。\n潇洒纤琼瘦玉，化工月翦云裁。\n诗催。\n付与雪襟怀。\n消得暗香来。\n算知心惟有，青松瘦竹，白石苍苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16911, '摸鱼儿', '陈允平', '过重阳、晚香犹耐，江城风露初峭。\n梅花已索巡檐笑，春入数枝红小。\n寒恁早。\n正帘卷苍云，和气生芝草。\n金虬篆袅。\n喜人乐丰年，波澄瀚海，星斗焕牙纛。\n家山近，游宴十洲三岛。\n石桥诗思频绕。\n朱颜白发神仙样，谁信玉关人老。\n春渐好。\n望阊阖天低，咫尺瞻黄道。\n祥云缥缈。\n看柳色沙堤，莺声禁辇，鸣佩凤池晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16912, '汉宫春', '陈允平', '帘卷苍云，爱初翔凤尾，忽驾虬枝。\n青青岁寒自保，越样清奇。\n参天溜雨，带疏苔、密藓芳蕤。\n天赋与，凌霜傲雪，然山泽风姿。\n他年楝梁共许，记雪山巫峡，曾赋新诗。\n庭前可人翠幄，葱烟霏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16913, '汉宫春', '陈允平', '春满芝田，正鹤飞空霭，龟引清涟。\n祥云满谷缥缈，非雾非烟。\n莺花燕柳，占年年、三月长安。\n天气好，新声暖响，东风十二雕阑。\n葱兽炉香袅，映金貂玉佩，绿鬓朱颜。\n何妨买花载酒，日日湖边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16914, '风入松', '陈允平', '西清人住水云乡。\n心静日偏长。\n闲中自乐壶天趣，笑红尘、谁是羲皇。\n叠嶂双溪争似，西湖雨色晴光。\n碧龟巢处藕花香。\n波影浸书床。\n庭前一种红兰树，薰风又、吹长瑶芳。\n竹外椿前舞彩，柳边槐底鸣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16915, '西湖明月引・江城梅花引', '陈允平', '朝回花底晓星明。\n瑞烟凝。\n暖风轻。\n修禊湔裙，时节又闻莺。\n绰约岸桃堤柳近，波万顷，碧琉璃，镜样平。\n仙翁佩襟秋水清。\n渺莲舟，浮翠瀛。\n御楼香近，东风里、吹下青冥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16916, '临江仙', '陈允平', '门外湖光清似玉，雨桐烟柳扶疏。\n爱闲吾亦爱吾庐。\n炉香心在在，杯酒乐如如。\n有子专城才四十，诸孙颗颗明珠。\n传家衣钵只诗书。\n一坡存菊意，千岁学松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16917, '少年游', '陈允平', '光风怀抱玉精神。\n不染世间尘。\n香暖衣篝，歌题彩扇，清似晋时人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16918, '鹧鸪天', '陈允平', '四壁图书静不哗。\n里湖深处隐人家。\n斑衣自斗百家彩，乌帽亲裁一幅纱。\n新酿酒，旋烹茶。\n半溪霜月正梅花。\n前庭手种红兰树，看到春风第二芽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16919, '霜天晓角', '陈允平', '月树风枝。\n孤山两字诗。\n来到十洲三岛，香得更、十分奇。\n阳和迟自迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16920, '瑞鹤仙', '陈允平', '燕归帘半卷。\n正漏约琼签，笙调玉。\n蛾眉画来浅。\n甚春衫懒试，夜灯慵翦。\n香温梦暖。\n诉芳心、芭蕉未展。\n渺双波、望极江空，二十四桥凭遍。\n葱茜。\n银屏彩凤，雾帐金蝉，旧家坊院。\n烟花弄晚。\n芳草恨，断魂远。\n对东风无语，绿阴深处，时见飞红数片。\n算多情、尚有黄鹂，向人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16921, '垂杨', '陈允平', '银屏梦觉。\n渐浅黄嫩绿，一声莺小。\n细雨轻尘，建章初闭东风悄。\n依然千树长安道。\n翠云锁、玉窗深窈。\n断桥人、空倚斜阳，带旧愁多少。\n还是清明过了。\n任烟缕露条，碧纤青袅。\n恨隔天涯，几回惆怅苏堤晓。\n飞花满地谁为扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16922, '瑞龙吟', '陈允平', '长安路。\n还是燕乳莺娇，度帘迁树。\n层楼十二阑干，绣帘半卷，相思处处。\n漫凭伫。\n因念彩云初到，琐窗琼户。\n梨花犹却春寒，翠羞粉怨，尊前解语。\n空有章台烟柳，瘦纤仍似，宫腰飞舞。\n憔悴暗觉文园，双鬓非故。\n闲拈断叶，重托殷勤句。\n频回首、河桥素约，津亭归步。\n恨逐芳尘去。\n眩醉眼尽，游丝乱绪。\n肠结愁千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16923, '风流子', '陈允平', '阑干休去倚，长亭外、烟草带愁归。\n正晓阴帘幕，绮罗清润，西风环佩，金玉参差。\n深院悄，乱蝉嘶夏木，双燕别春泥。\n满地残花，蝶圆凉梦，半亭落叶，蛩感秋悲。\n兰屏馀香在，销魂处、憔悴瘦不胜衣。\n谁念凤楼当日，星约云期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16924, '风流子', '陈允平', '残梦绕林塘。\n诗添瘦、瘦不似东阳。\n正流水荡红，暗通幽径，嫩篁翻翠，斜映回墙。\n对握宝筝低度曲，销蜡靓新簧。\n莺懒昼长，燕闲人倦，乍亲花簟，慵引壶觞。\n帘栊深深地，歌尘静、芳草自碧空厢。\n十二画桥，一堤烟树成行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16925, '华胥引', '陈允平', '涵空斜照，掠水轻岚，满天红叶。\n雁泊平芜，凫依乱荻声唼唼。\n寂寞金井梧桐，渐辘轳伊轧。\n明月纱窗，夜寒孤枕应怯。\n吟老西风，笑衰髯、顿疏如镊。\n锦笺勤重，频剔兰灯自阅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16926, '意难忘', '陈允平', '额粉宫黄。\n衬桃花扇底，歌送瑶觞。\n裙拖金缕细，衫唾碧花香。\n琼佩冷，玉肌凉。\n罗袜步沧浪。\n漫共伊，心盟意约，眼觑眉相。\n连环未结双双。\n似桃源误入，初嫁刘郎。\n珑璁仙子髻，绰约道家妆。\n千种恨、九回肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16927, '宴清都', '陈允平', '听彻南楼鼓。\n寒宵迥、玉壶冰漏迟度。\n重温锦幄，低护青毡，曲通朱户。\n巡檐细嚼寒梅，叹寂寞、孤山伴侣。\n更信有、铁石心肠，广平几度曾赋。\n寒深试拥羊裘，松醪自酌，谁伴吟苦。\n摩挲醉眼，阑干笑拍，白鸥惊去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16928, '兰陵王', '陈允平', '古堤直。\n隔水轻阴扬碧。\n东风路，还是舞烟眠露，年年自春色。\n红尘遍京国。\n留滞高阳醉客。\n斜阳外，千缕翠条，彷佛流莺度金尺。\n长亭半陈迹。\n记曾系征鞍，频护歌席。\n匆匆江上又寒食。\n回首处应念，旧曾攀折，依然离恨遍四驿。\n倦游尚南北。\n恻恻。\n怨怀积。\n渐楚榭寒收，隋苑春寂。\n眉颦不尽相思极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16929, '琐窗寒', '陈允平', '禁烛飞烟，东风插柳，万家千户。\n梨花院落，数点弄晴纤雨。\n傍秋千、红云半湿，画帘燕子商春语。\n数十年南北，西湖倦客，曲江行旅。\n日暮。\n花深处。\n对修竹弹棋，戏评格五。\n携尊共约，诗酒云朋月侣。\n念旧游、九陌香尘，倡条冶叶还在否。\n踏青归，醉宿兰舟，枕藉黄金俎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16930, '隔浦莲近拍', '陈允平', '铅霜初褪凤葆。\n碧旆侵云窈。\n万绿伤春远，林幽乐、多禽鸟。\n斜阳堤畔草。\n游鱼闹。\n暗水流萍沼。\n翠钿小。\n凉亭醉倚，接罗巾、任倒。\n月明庭树，夜半鹊飞惊晓。\n隔岸苹乡梦渐到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16931, '早梅芳・喜迁莺', '陈允平', '柳初妍，花渐好。\n可恨行期到。\n落梅香尽，澹月朦胧微照。\n风帘银烛暗，露幕金花小。\n纵离歌缓唱，残角又霜晓。\n琐窗前，秦吉了。\n促上长安道。\n扬鞭西去，几点稀星尚云表。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16932, '早梅芳・喜迁莺', '陈允平', '凤钗横，鸾带绕。\n独步鸳鸯沼。\n阑干斜倚，自打精神对花笑。\n贴衣琼佩冷，衬袜金莲小。\n卷香茵缥缈，舞袖称纤妙。\n梦初成，欢未了。\n明日青门道。\n离云别雨，脉脉无情画堂晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16933, '四园竹', '陈允平', '昏昏瞑色，乱叶拥云扉。\n渚兰风润，庭桂露凉，香动秋帏。\n独向闲亭步月，阑干瘦倚，此情惟有天知。\n纵如其。\n黄花时节归来，因循已误心期。\n欲写相思寄与，愁拂鸾笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16934, '侧犯', '陈允平', '晚凉倦浴，素妆薄试铅华靓。\n凝定。\n似一朵芙蓉泛清镜。\n轻纨笑自拈，扑蝶鸳鸯径。\n娇懒。\n金凤、斜翠蝉影。\n冰肌玉骨，衬体红绡莹。\n还暗省。\n记青青、双鬓旧潘令。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16935, '齐天乐', '陈允平', '客愁都在斜阳外，凭阑桂香吹晚。\n乱叶蝉哀，寒汀鹭泊，离绪并刀难翦。\n牙屏半掩。\n渐尘扑冰纨，浪收云簟。\n露入征衣，满襟秋思付诗卷。\n远思前度问酒，凤楼人共倚，归兴无限。\n雁影亭皋，蛩声院落，双阙明河光转。\n田园梦远。\n叹篱菊初黄，涧莼堪荐。\n拄笏西风，四山烟翠敛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16936, '荔枝香近・荔枝香', '陈允平', '杜宇声声频唤，春渐去。\n暗碧柳色依依，湖上迷青雾。\n残香净冼红兰，昨夜朱铅雨。\n金泥帐底，双虬自沈乳。\n天际，渐迤逦片帆南浦。\n一笑蔷薇，别後酒杯慵举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16937, '荔枝香近・荔枝香', '陈允平', '脸霞香销粉薄，泪偷泫。\n金兽，沈水微薰，人帘绿树春阴，糁径红英风卷。\n芳草怨碧，王孙渐远。\n锦屏梦回，恍觉云雨散。\n玉瑟无心理，懒醉琼花宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16938, '水龙吟', '陈允平', '晓莺啼醒春愁，粉香独步千红地。\n庭闲散缟，林空翦雪，鸥惊鹤避。\n妒月魂凄，行云梦冷，温柔乡闭。\n渐黄昏院落，清明时候，东风里、无情泪。\n织翠玲珑叶底。\n倚阑人、玉龙休吹。\n残妆微洗，芳心微露，昭阳睡起。\n恨结连环，舞停双佩，水晶如意。\n倩蜂媒、聘取琼花，细与向、尊前比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16939, '六丑', '陈允平', '自清明过了，渐柳底、莺梭慵掷。\n万红御风，飘飘如附翼。\n锦绣陈迹。\n障地香尘暗，乱蜂似雨，漫冶游南国。\n兰襟缥缈辞湘泽。\n马迹郊原，燕泥巷陌。\n伤春为花深惜。\n叹芳菲薄幸，容易疏隔。\n庭闲人寂。\n空除芳草碧。\n梦里惊春去，如瞬息。\n长安市上狂客。\n为桃源解佩，醉浓欢极。\n无心整、雾襟烟帻。\n惊回处，断雨残云倦倚，画阑干侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16940, '塞垣春', '陈允平', '草碧铺横野。\n带暝色、归鞍卸。\n烟葭露苇，满汀鸥鹭，人在图画。\n渐一声雁过南楼也。\n更细雨、时飘洒。\n念徽容、都销瘦，漫将纨素描写。\n临镜理残妆，依然是、京兆柔雅。\n落叶感秋声，啼浆叹凉夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16941, '扫花游・扫地游', '陈允平', '蕙风扬暖，渐草色分吴，柳阴迷楚。\n寸心似缕。\n看窥帘燕妥，妒花蝶舞。\n翦翦愁红，万点轻飘泪雨。\n怕春去。\n问杜宇唤春，归去何处。\n後期重细许。\n倩落絮飞烟，障春归路。\n长亭别俎。\n对歌尘舞地，暗伤蛮素。\n算得相思，比著伤春又苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16942, '夜飞鹊・夜飞鹊慢', '陈允平', '秋江际天阔，风雨凄其。\n云阴未放晴晖。\n归鸦乱叶更萧索，砧声几处寒衣。\n沙头酒初熟，尽篱边朱槿，竹外青旗。\n潮期尚晚，怕轻离、故故迟迟。\n何以醉中先别，容易为分襟，独抱琴归。\n回首征帆缥缈，津亭寂寞，衰草烟迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16943, '满庭芳', '陈允平', '槐影连阴，竹光抟露，小荷新绿浮园。\n簟纹如浪，绡帐碧笼烟。\n回合溪桥一曲，初雨过、流水溅溅。\n阑干外，沙鸥野鸟，飞过钓鱼船。\n浮生，同幻境，眼空四海，迹寄三椽。\n但随天、休问我後谁前。\n要识渊明琴趣，真真意、都在无弦。\n薰风里，纶巾羽扇，一枕北窗眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16944, '花犯', '陈允平', '报南枝、东风试暖，萧萧甚情味。\n乱琼雕缀。\n幻姑射精神，玉蕊佳丽。\n寿阳宴罢妆台倚。\n眉颦羞鹊喜。\n念误却、何郎归去，清香空翠被。\n溪松径竹素知心，青青岁寒友，甘同憔悴。\n渐画角，严城上、雁霜惊坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16945, '大', '陈允平', '雾幕西山，珠帘卷，浓霭凄迷华屋。\n蒲萄新绿涨，正桃花烟浪，乱红翻触。\n绣阁留寒，罗衣怯润，慵理凤楼丝竹。\n东风垂杨恨，锁朱门深静，粉香初熟。\n念缓酌灯前，醉吟孤枕，顿成清独。\n伤心春去速。\n叹美景虚掷如飞毂。\n漫孤负、秋千台榭，拾翠心期，误芳菲、怨眉愁目。\n冷透金篝湿，空展转、画屏山曲。\n梦不到、华胥国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16946, '霜叶飞', '陈允平', '碧天如水，新蟾挂、修眉初画云表。\n半江枫叶自黄昏，深院砧声悄。\n渐凉蝶、残花梦晓。\n西风篱落寒小。\n背画阑依依，有数点、流萤乱扑，扇底微照。\n凝望渺漠平芜，蒹葭烟远，过雁远带愁到。\n拼教日日醉斜阳，但素琴横抱。\n记旧谱、归耕未了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16947, '法曲献仙音', '陈允平', '油幕收尘。\n素纨招月，一枕苹香微度。\n枕玉牙床，浣冰金斛，薰风夜凉窗户。\n渐睡醒、明河暗，芭蕉几声雨。\n对谁语。\n念徽容已成憔悴，心期误。\n归计欲成又阻。\n寂寞燕楼空，想弓弯、眉黛慵妩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16948, '渡江云', '陈允平', '青青江上草，片帆浪暖，初泊渡头沙。\n翠筇便瘦倚，问酒垂杨，影里那人家。\n东风未许，漫媚妩、轻试铅华。\n飘佩环、玉波秋莹，双髻绿堆鸦。\n空嗟。\n赤阑桥畔，暗约琴心，傍秋千影下。\n夜渐分、西窗愁对，烟月笼纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16949, '应天长', '陈允平', '流莺唤梦，芳草带愁，东风料峭寒色。\n又见杏浆饧粥，家家禁烟食。\n江湖几年倦客。\n曾惯识、凄凉岑寂。\n苦吟瘦，萧索诗肠，空愧郊籍。\n春事正溪山，柳雾花尘，深映翠萝壁。\n更谢多情双燕，归来旧庭宅。\n情丝乱游巷陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16950, '玉楼春', '陈允平', '东风跃马长安道。\n一树樱桃花谢了。\n别来千里梦频归，醉里五更愁不到。\n江南两岸无名草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16951, '玉楼春', '陈允平', '粉销香减红兰泪。\n总是文君初别意。\n春风织就闷情怀，夜月砌成愁况未。\n迢迢归梦频东里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16952, '玉楼春', '陈允平', '万花丛底曾抬目。\n澹雅梳妆娇已足。\n夜来鹦鹉梦中人，春去琵琶江上曲。\n双鸾碧重钗头玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16953, '玉楼春', '陈允平', '西园斗结秋千了。\n日漾游丝烟外袅。\n小桥杨柳色初浓，别院海棠花正好。\n粉墙低度莺声巧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16954, '玉楼春', '陈允平', '柳丝挽得秋光住。\n肠断驿亭离别处。\n斜阳一片水边楼，红叶满天江上路。\n来鸿去雁知何数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16955, '伤情怨・清商怨', '陈允平', '南枝春意正小。\n篱菊都荒了。\n帐底孤灯，夜来还独照。\n沙洲烟翠渺渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16956, '品令', '陈允平', '玉壶尘静。\n蟾光透、一帘疏影。\n偏爱水月楼台近。\n画阑独倚，风度寒香阵。\n犹记曲江烟水恨。\n叹凄凉谁问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16957, '木兰花・玉楼春', '陈允平', '长江浩渺山明秀。\n宛转西风惊客袖。\n相逢才系柳边舟，相别又倾花下酒。\n怪得新来诗骨瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16958, '秋蕊香', '陈允平', '晚酌宜城酒暖。\n玉软嫩红潮面。\n醉中窈窕度娇眼。\n不识愁深恨浅。\n绣窗一缕香绒线。\n击双燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16959, '菩萨蛮', '陈允平', '银城远枕清江曲。\n汀洲尽画蒹葭绿。\n君上木兰舟。\n妾愁双凤楼。\n角声何处发。\n月浸溪桥雪。\n独自倚阑看。\n风飘襟袖寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16960, '丑奴儿・采桑子', '陈允平', '岁寒时节千林表，独耐风霜。\n妒粉欺黄。\n澹澹衣裳薄薄妆。\n西湖十二阑干曲，倚遍寒香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16961, '感皇恩', '陈允平', '体态玉精神，惺言语。\n一点灵犀动人处。\n绣香罗帕，为待别时亲付。\n要人长记得，相思苦。\n彩鸾独跨，蓝桥归路。\n憔悴东风自蛮素。\n桃叶杨花，又向空江欲度。\n任洛阳城里，春无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16962, '宴桃源・如梦令', '陈允平', '闲倚琐窗工绣。\n春困两眉频皱。\n独自下香街，攀折画桥烟柳。\n晴昼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16963, '宴桃源・如梦令', '陈允平', '何处春风归路。\n金屋空藏樊素。\n零乱海棠花，愁梦欲随春去。\n情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16964, '月中行・月宫春', '陈允平', '鬓云斜插映山红。\n春里澹香融。\n自携纨扇出帘栊。\n意欲扑飞虫。\n蔷薇架下偏宜酒，纤纤手、自引金锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16965, '渔家傲', '陈允平', '日转花梢春已昼。\n双蛾曲理遥山秀。\n百草偏输羞不斗。\n随人後。\n无情自折金丝柳。\n秋水盈盈娇欲溜。\n六么倦舞弓弯袖。\n偷摘青梅推病酒。\n俳徊久。\n一双燕子归时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16966, '渔家傲', '陈允平', '自别春风情意恻。\n秦筝不理香尘积。\n去跃青骢游上国。\n归未得。\n何如莫向尊前识。\n薄幸高阳花酒客。\n迷云恋雨青楼侧。\n金屋空闲双凤席。\n离怀适。\n银台烛泪成行滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16967, '定风波', '陈允平', '慵拂妆台懒画眉。\n此情惟有落花知。\n流水悠悠春脉脉，闲倚绣屏，犹自立多时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16968, '蝶恋花', '陈允平', '谢了梨花寒食後。\n翦翦轻寒，晓色侵书牖。\n寂寞幽斋惟酌酒。\n柔条恨结东风手。\n浅黛娇黄春色透。\n薄雾轻烟，远映苏堤秀。\n目断章台愁举首。\n故人应似青青旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16969, '蝶恋花', '陈允平', '墙外秋千花影後。\n环兽金悬，暗绿笼朱牖。\n为怯轻寒犹酒。\n同心共结怀纤手。\n粉袖盈盈香泪透。\n蹙损双眉，懒画遥山秀。\n柔弱风条低拂首。\n渭城歌舞春如旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16970, '蝶恋花', '陈允平', '寂寞长亭人别後。\n一把垂丝，乱拂闲轩牖。\n三月春光浓似酒。\n传怀莫放纤纤手。\n金缕依依红日透。\n舞彻东风，不减蛮腰秀。\n扑鬓杨花如白首。\n少年张绪心如旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16971, '蝶恋花', '陈允平', '落尽樱桃春去後。\n舞絮飞绵，扑簌穿帘牖。\n异别情怀愁对酒。\n翠条折赠劳亲手。\n绣幕深沉寒尚透。\n雨雨晴晴，妆点西湖秀。\n怅望章台愁转首。\n画阑十二东风旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16972, '蝶恋花', '陈允平', '楼上钟残人渐定。\n庭户沉沉，月落梧桐井。\n闷倚琐窗灯炯炯。\n兽香闲伴银屏冷。\n淅沥西风吹雁影。\n一曲胡笳，别後谁堪听。\n誓海盟山虚话柄。\n凭书问著无言应。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16973, '红罗袄', '陈允平', '别来书渐少，家远梦徒归。\n念去燕来鸿，愁随秋到，旧盟新约，心与天知。\n楚江上、木落林稀。\n西风尚隔心期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16974, '少年游', '陈允平', '兰屏香暖，松醪味滑，湖蟹荐香橙。\n雁宇秋高，凤台人远，明月自吹笙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16975, '少年游', '陈允平', '斜阳冉冉水边楼。\n珠箔水晶钩。\n拍点红牙，萧吹紫玉，低按小梁州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16976, '少年游', '陈允平', '画楼深映小屏山。\n帘幕护轻寒。\n比翼香囊，合欢罗帕，都做薄情看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16977, '少年游', '陈允平', '翠罗裙解缕金丝。\n罗扇掩芳姿。\n柳色凝寒，花情雨，生怕踏青迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16978, '还京乐', '陈允平', '彩鸾去，适怨清和，锦瑟谁共理。\n奈春光渐老，万金难买，榆钱空费。\n岸草烟无际。\n落花满地芳尘委。\n翠袖里，红粉溅溅，东风吹泪。\n任鸳帏底。\n宝香寒、金兽慵熏绣被，依依离别意味。\n琼钗暗画心期。\n倩啼鹃、为催行李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16979, '解连环', '陈允平', '寸心谁托。\n望潇湘暮碧，水遥云邈。\n自绣带、同翦合欢，奈鸳枕梦单，凤帏寒薄。\n澹月梨花，别後伴、情怀萧索。\n念伤春渐懒，病酒未，两愁无药。\n魂销翠兰紫若。\n任钗沉鬓影，香沁眉角。\n怅画阁、尘满妆台，但玉佩依然，宝筝闲却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16980, '绮寮怨', '陈允平', '满院荼シ开尽，杜鹃啼梦醒。\n记晓月、绿水桥边，东风又、折柳旗亭。\n蒙茸轻烟草色，疏帘净、乱织罗带青。\n对一尊、别酒初斟，征衫上、点滴香泪盈。\n几度恨沉断云，飞鸾何处，连环尚结双琼。\n一曲琵琶，湓江上、惯曾听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16981, '玲珑四犯', '陈允平', '金屋春深，似灼灼娉婷，真真娇艳。\n洗净铅华，依旧曲眉丰脸。\n犹记舞歇凉州，渐缥缈、碧云缭乱。\n白玉环、宝镜偷换。\n别後甚时重见。\n鸾帏凤席鸳鸯荐。\n但空馀、蕙芳兰茜。\n天涯柳色青青恨，不入东风眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16982, '丹凤吟', '陈允平', '暗柳烟深何处，翡翠帘栊，鸳鸯楼阁。\n芹泥融润，飞燕竞穿珠幕。\n秋千倦倚，还思少年，袜步尘轻，衫裁罗薄。\n陡顿芳心暗老，强理新妆，离思都占眉角。\n过了几番花信，晓来地寒意恶。\n可煞东风，甚把夭桃艳杏，故故凌铄。\n伤春憔悴，泪矗粉腮香落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16983, '忆旧游', '陈允平', '又眉峰碧聚，记得邮亭，人别中宵。\n翦烛西窗下，听林梢叶坠，雾漠烟潇。\n彩鸾梦逐云去，环佩人扶遥。\n但镜裂鸳奁，钗分燕股，粉腻香销。\n迢迢。\n旧游处，向柳下维舟，花底扬镖。\n更忆西风里，采芙蓉江上，双桨频招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16984, '拜星月慢', '陈允平', '漏阁闲签，琴窗倦谱，露湿宵萤欲暗。\n雁咽凉声，寂寞芙蓉院。\n画檐外，树色惊霜渐改，澹碧云疏星烂。\n旧约桐阴，问何时重见。\n倚银屏、更忆秋娘面。\n想凌波、共立河桥畔。\n重念酒污罗襦，渐金篝香散。\n翦孤灯、伴宿西风馆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16985, '倒犯', '陈允平', '百尺凤皇楼，碧天暮云初扫。\n冰华散缟。\n双鸾驾镜悬空窈。\n婆娑桂影，香满西风阑干悄。\n渐玉魄金辉，飞度千山表。\n饵玄霜、醉琼。\n身在九霄，独步丹梯，飘飘轻雾。\n缥缈广寒殿，觉世山河小。\n爱十二、琼楼好。\n算谁知、消息盈虚道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16986, '解语花', '陈允平', '鳌峰溯碧，贝阙缘云，桂魄寒光射。\n凤檐鸳瓦。\n星河际、缥缈绣帘高下。\n笙箫奏雅。\n爱雪柳、蛾儿笑把。\n琼佩摇、珠翠盈盈，迤逦飘兰麝。\n陆地金莲照夜。\n富绮罗妆艳，春态容冶。\n笼纱鞍帕。\n香尘过、禁陌宝车骄马。\n游人静也。\n东风里、万红初谢。\n沉醉归、残角霜天，渐落梅声罢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16987, '过秦楼', '陈允平', '倦听蛩砧，初抛纨扇，隔浦乱钟催晚。\n湘蒲簟冷，楚竹帘稀，窗下乍闻裁翦。\n倦柳梳烟，枯莲蘸水，芙蓉翠深红浅。\n对半床灯火，虚堂凄寂，近书思遍。\n夜漏永、玉宇尘收，银河光烂。\n梦断楚天空远。\n婆娑月树，缥缈仙香，身在广寒宫殿。\n无奈离愁乱织，籍酒销磨，倩花排遣。\n渐江空霜晓，黄芦漠漠，一声来雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16988, '过秦楼', '陈允平', '翠约苹香。\n绿抟槐阴，隔水晚蝉声断。\n壶冰避暖，钏玉凉，倦暑懒拈歌扇。\n云浪缥缈鱼鳞，新月开弦，落星沉箭。\n恨经年闲阔，柔笺空寄，梦随天远。\n憔悴损、臂薄烟绡，腰宽霞缕，锦瑟暗尘侵染。\n韩香犹在，秦镜空圆。\n薄幸旧盟俱变。\n虚蠹春华，为谁容改芳徽，魂飞娇倩。\n凭危楼望断，江外青山乱点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16989, '解蹀躞', '陈允平', '岸柳飘残黄叶，尚学纤腰舞。\n谢他终日，亭前伴羁旅。\n无奈历历寒蝉，为谁唤老西风，伴人吟苦。\n闷无绪。\n记得芙蓉江上，萧娘旧相遇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16990, '蕙兰芳引', '陈允平', '虹雨乍收，楚天霁、乱飞秋鹜。\n渐草色衰残，墙外土花暗绿。\n故山鹤怨，流水自、菊篱茅屋。\n日暮诗吟就，澹墨闲题修竹。\n更忆飘蓬，霜绨风葛，几度凉燠。\n叹归去来兮，何日甬东一曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16991, '六么令', '陈允平', '授衣时节，犹未定寒燠。\n长空雨收云霁，湛碧秋容沐。\n还是鲈肥蟹美，橡栗村村熟。\n不堪追逐。\n龙山梦远，惆怅田园自黄菊。\n醉中还念倦旅，触景伤心目。\n羞破帽、把茱萸，更忆尊前玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16992, '红林擒近', '陈允平', '飞絮迷芳意，落梅销暗香。\n皓鹤泪空碧，白鸥避寒塘。\n妨它踏青斗草，便放晓日东窗。\n先自懒弄晨妆。\n谁奈靓笙簧。\n望帘寻酒市，看钓认渔乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16993, '红林擒近', '陈允平', '三万六千顷，玉壶天地寒。\n庾岭封的，淇园折琅。\n漠漠梨花烂漫，纷纷柳絮飞残。\n直疑潢潦惊翻，斜风溯狂澜。\n对此频胜赏，一醉饱清欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16994, '满路花・促拍满路花', '陈允平', '离歌泣断云，别舞愁飞雪。\n凤皇台上望，琼箫绝。\n钗分玉燕，寸寸回肠折。\n碧空归雁阔。\n犹有疏梅，岁寒独伴高节。\n鲛绡罗帕，泪洒胭脂血。\n悠悠江上水，天连接。\n朱楼遍倚，万里空情切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16995, '满路花・促拍满路花', '陈允平', '寒轻菊未残，春小梅初破。\n兽炉闲拨尽，松明火。\n青毡锦幄，四壁新妆裹。\n重暖香篝，绣被拥银屏，彩鸾空伴云卧。\n相思何处，梦入蓝桥左。\n归期还细数，愁眉锁。\n薄情孤雁，不向楼西过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16996, '氐州第一', '陈允平', '闲倚江楼，凉生半臂，天高过雁来小。\n紫芡波寒，青芜烟澹，南浦云帆缥缈。\n潮带离愁，去冉冉、夕阳空照。\n寂寞东篱，白衣人远，渐黄花老。\n见说西湖鸥鹭少。\n孤山路、醉魂飞绕。\n荻蟹初肥，莼鲈更美，尽酒怀诗抱。\n待南枝、春信早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16997, '尉迟杯', '陈允平', '长亭路。\n望渭北、漠漠春天树。\n殷勤别酒重斟，明日相思何处。\n晴丝扬暖，芳草外、斜阳自南浦。\n望孤帆、影接天涯，一江潮带愁去。\n回首杜若汀州，叹泛梗飘萍，乍散还聚。\n满径残红春归後，犹自有、杨花乱舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16998, '塞翁吟', '陈允平', '睡起鸾钗，金约鬓影胧。\n桅佩冷，玉丁东。\n镜里对芙蓉。\n秦筝倦理梁尘暗，惆怅燕子楼空。\n山万叠，水千重。\n一叶漫题红。\n忽忽。\n从别後，残云断雨，馀香在、鲛绡帐中。\n更懊恨、灯花无准，写幽愫、锦织回文，小字斜封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (16999, '绕佛阁', '陈允平', '暮烟半敛。\n云护澹月，斜照楼馆。\n春夜偏短。\n一床耿耿，孤灯晃帏幔。\n玉壶漏满。\n天外渐觉，归雁声远。\n离思凄婉。\n重怀执手，东风翠苹岸。\n料想凤楼人，倦绣回文停彩线。\n憔悴泪积，香销娇粉面。\n叹暗老年光，隙驹流箭。\n梦中空见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17000, '庆春宫・高阳台', '陈允平', '孤鹜披霞，归鞍卸日，晚香菊自寒城。\n虚馆灯闲，征衫尘浣，夜深何处砧声。\n乱蛩催怨，月明里、依稀数星。\n云山迢递，犹误归期，方寸遍萦。\n秋风燕送鸿迎。\n最怜堤柳，白露先零。\n倦倚楼高，恨随天远，桂风和梦俱清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17001, '满江红', '陈允平', '目断江横，相思字、难凭雁足。\n从别後、倦歌慵绣，悄无拘束。\n烟柳翠迷星眼恨，露桃红沁霞腮肉。\n傍琐窗、终日对文枰，翻新局。\n频暗把，归期卜。\n芳草恨，阑干曲。\n谢多情海燕，伴愁华屋。\n明月自圆双蝶梦，彩云空伴孤鸾宿。\n任画帘、不卷玉钩闲，扬花扑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17002, '丁香结', '陈允平', '尘拥妆台，翠闲歌扇，金井碧梧风陨。\n听豆虫声小，伴寂寞、冷逼莓墙苍润。\n料凄凉宋玉，悲秋恨、此际怎忍。\n莲塘风露，渐入粉艳，红衣落尽。\n勾引。\n记舞歇弓弯，几度柳围花阵。\n酒薄愁浓，霞腮泪渍，月眉香晕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17003, '西河', '陈允平', '形胜地。\n西陵往事重记。\n溶溶王气满东南，英雄闲起。\n凤游何处古台空，长江缥缈无际。\n石头城上试倚。\n吴襟楚带如系。\n乌衣巷陌几斜阳，燕闲旧垒。\n後庭玉树委歌尘，凄凉遗恨流水。\n买花问酒锦绣市。\n醉新亭、芳草千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17004, '一寸金', '陈允平', '吾爱吾庐，甬水东南半村郭。\n试倚楼极目，千山拱翠，舟横沙觜，江迷城脚。\n水满苹风作。\n阑干外、夕阳半落。\n荒烟瞑、几点昏鸦，野色青芜自空廓。\n浩叹飘蓬，春光几度，依依柳边泊。\n念水行云宿，栖迟羁旅，鸥盟鹭伴，归来重约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17005, '瑞鹤仙', '陈允平', '故庐元负郭。\n爱树色参差，湖光渺漠。\n楼危万山落。\n俯阑干十二，檐飞角。\n花娇柳弱。\n映轻黄、浅黛依约。\n与沙鸥、共结新盟，伴我醉眠醒酌。\n萧散云根石上，瀹茗松泉，注书芸阁。\n莺窥燕幕。\n檐外竹、圃中药。\n念耕烟钓雪，已成活计，一任风波自恶。\n但无心、万事由天，梦中更乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17006, '浪淘沙慢', '陈允平', '暮烟愁，鸦归古树，雁过空堞。\n南浦牙樯渐发。\n阳关歌尽半阕。\n便恨入回肠千万结。\n长亭柳、寸寸攀折。\n望日下长安近，莫遣鳞鸿成闲绝。\n凄切。\n去帆浪远江阔。\n怅顿解连环，西窗下、对烛频哽咽。\n叹百岁光阴，几度离别。\n翠销粉竭。\n信乍圆易散，彩云明月。\n浙水吴山重重叠。\n流苏帐、阳台梦歇。\n暗尘锁、孤鸾秦镜缺。\n羞人问、怕说相思，正满院杨花，落尽东风雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17007, '西平乐慢・西平乐', '陈允平', '泛梗飘萍，入山登陆，迢递雾迥烟赊。\n漠漠蒹葭，依依杨柳，天涯总是愁遮。\n叹寂寞尘埃满眼，梦逐孤云缥缈，春潮带雨，鸥迎远溆，雁别平沙。\n寒食梨花素约，肠断处，对景暗伤嗟。\n晚钟烟寺，晨鸡月店，征褐萧疏，破帽斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17008, '南乡子', '陈允平', '归雁转西楼。\n薄幸音书日日收。\n旧恨却凭红叶去，飕飕。\n春水多情日夜流。\n杨柳曲江头。\n烟里青青恨不休。\n九十韶光风雨半，回眸。\n一片花飞一片愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17009, '望江南・忆江南', '陈允平', '娇滴滴，聪隽在秋波。\n六幅香裙拖细，一钩尘袜翦轻罗。\n春意动人多。\n临宝鉴，石黛拂修蛾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17010, '望江南・忆江南', '陈允平', '烟漠漠，湖外绿杨堤。\n满地落花春雨後，一帘飞絮夕阳西。\n梁燕落香泥。\n流水恨，和泪入桃溪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17011, '浣溪沙', '陈允平', '自别萧郎锦帐寒。\n凤楼日日望平安。\n杏花枝上露才乾。\n眉皱但嫌钿翠堕，臂销惟觉钏金宽。\n薄情杨柳征鞍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17012, '浣溪沙', '陈允平', '一枕华胥梦不成。\n碧筒香润玉醪倾。\n日长花影过池亭。\n雪藕臂寒鹦较怯，采菱歌发鹭频惊。\n白苹洲上雨初晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17013, '浣溪沙', '陈允平', '约臂金圆隐绛缯。\n枕痕斜印曲花藤。\n玉肌娇软莹如冰。\n护日帘栊迷晓梦，舞风琼佩弄秋声。\n倦妆鸾鉴不凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17014, '浣溪沙', '陈允平', '宝镜奁开素月空。\n晚妆慵结绣芙蓉。\n人娇语更。\n倦浴金莲轻衫步，捧笙玉笋半当胸。\n枕痕又露一丝红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17015, '浣溪沙', '陈允平', '双倚妆楼宝髻垂。\n佩环依约下瑶池。\n鬓边斜插碧蝉儿。\n不嫁东风苏小恨，未圆明月柳娘悲。\n舞休愁叠缕金衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17016, '浣溪沙', '陈允平', '斗鸭阑干燕子飞。\n一堤春水漾晴晖。\n女郎何处踏青归。\n生色鞋儿销凤稳，碧罗衫子唾花微。\n後期应待牡丹时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17017, '浣溪沙', '陈允平', '六幅蒲帆晓渡平。\n一江星斗渐西倾。\n离家才是两三程。\n浦外野花如唤客，树头春鸟自呼名。\n五云深处锦官城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17018, '浣溪沙', '陈允平', '柳底征鞍花底车。\n两行香泪湿红襦。\n别来莺燕已春馀。\n梳洗楼台愁独倚，笙歌庭院醉谁扶。\n卷帘闲看玉储胥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17019, '浣溪沙', '陈允平', '十二珠帘绣带垂。\n柳烟迷暗楚江涯。\n自携玉笛凭丹梯。\n写恨鸾笺凝粉泪，踏青鸳袜溅金泥。\n落红深处乱莺啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17020, '浣溪沙', '陈允平', '睡起朦腾小篆香。\n素纨轻度玉肌凉。\n竹深荷净少炎光。\n雨过乱蝉嘶古柳，日斜双鹭立闲塘。\n更将心事自商量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17021, '点绛唇', '陈允平', '眉叶颦愁，泪痕红透兰襟润。\n雁声将近。\n须带平安信。\n独倚江楼，落叶风成阵。\n情怀闷。\n蝶随蜂趁。\n满地黄花恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17022, '点绛唇', '陈允平', '别後长亭，翠芜寂寞分襟地。\n雁书空寄。\n归梦频东里。\n一曲秋风，写尽渊明意。\n凝情际。\n雨襟烟袂。\n都是黄花泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17023, '点绛唇', '陈允平', '分袂情怀，快风一箭轻帆举。\n暮烟云浦。\n芳草斜阳路。\n输与闲鸥，朝暮潮来去。\n空凝伫。\n小桥樊素。\n金屋春深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17024, '点绛唇', '陈允平', '莺语愁春，海棠风里胭脂雨。\n酒怀慵举。\n闲扑亭前絮。\n漠漠斜阳，截断愁来路。\n凭阑伫。\n满怀离苦。\n分付楼南鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17025, '夜游宫', '陈允平', '愁厌眉峰成敛。\n几回皱、落花钿点。\n镜里芳容自羞见。\n又黄昏，听南楼，度更箭。\n月引桐阴转。\n珠帘动、影摇花乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17026, '夜游宫', '陈允平', '窄索楼儿傍水。\n渐秋到、渔村橘里。\n薄幸江南倦游子。\n恣轻狂，恋高阳，歌酒市。\n独自帘儿底。\n香罗带、翠闲金坠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17027, '诉衷情', '陈允平', '绿云凤髻不盘。\n情味胜思酸。\n晓色露桃烟杏，空照脸霞丹。\n花渐老，径苔闲。\n锦斓斑。\n怨红一叶，流水东风，好去人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17028, '诉衷情', '陈允平', '嫩寒侵帐弄微霜。\n客泪不成行。\n料得黄花憔悴，何日赋归装。\n楼独倚，漏声长。\n暗情伤。\n凄凉况味，一半悲秋，一半思乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17029, '一落索', '陈允平', '澹澹双蛾疏秀。\n为谁频皱。\n落花何处不春愁，料不是、因花瘦。\n锦字香笺封久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17030, '一落索', '陈允平', '欲寄相思情苦。\n倩流红去。\n满怀写不尽离愁，都化作、无情雨。\n渺渺暮云春树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17031, '迎春乐', '陈允平', '垂杨影下黄金屋。\n东风渐、粉香熟。\n恨当年、有约骖鸾速。\n误一枕、红云宿。\n带眼宽移腰似束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17032, '迎春乐', '陈允平', '江湖十载疏狂迹。\n红尘里、倦游客。\n驻雕鞍、问柳东风陌。\n花底帽、任侧。\n斗酒百篇呼太白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17033, '迎春乐', '陈允平', '依依一树多情柳。\n都未识行人手。\n对青青、共结同心就。\n更共饮、旗亭酒。\n褥上芙蓉铺软绣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17034, '虞美人', '陈允平', '春衫薄薄寒犹恋。\n芳草连天远。\n嫩红和露入桃腮。\n柳外东边楼阁、燕飞来。\n霓裳一曲凭谁按。\n错□□重看。\n金虬闲暖麝檀煤。\n银烛替人垂泪、共心灰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17035, '虞美人', '陈允平', '夕阳楼上都凭遍。\n柳下风吹面。\n强搴罗袖倚重门。\n懒傍玉台鸾镜、暗尘昏。\n离情脉脉如飞絮。\n此恨凭谁语。\n一天明月一江云。\n云外月明、应照凤楼人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17036, '虞美人', '陈允平', '疏林远带寒山小。\n月落霜天晓。\n棹歌初发浦烟中。\n自叹疏狂踪迹、似萍蓬。\n江边衰柳迷津堠。\n归兴浓於酒。\n断烟流水自寒塘。\n十里蒹葭、鸥鹭两三双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17037, '虞美人', '陈允平', '彩云别後房栊悄。\n愁立西风晓。\n倚阑无语对黄花。\n惆怅玉郎应在、楚江涯。\n钿筝空贮芳尘满。\n寂寞朱弦断。\n夜来一点帐前灯。\n频吐银花双烬、照罗屏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17038, '虞美人', '陈允平', '玉奁香细流苏暖。\n寒日花梢短。\n翠罗尘暗缕金销。\n□□东□华屋、自藏娇。\n当时携手鸳鸯径。\n一笑蔷薇影。\n如今眉黛镇愁封。\n欲问归期消息、望宾鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17039, '醉桃源・阮郎归', '陈允平', '金闺平帖被青青。\n宝街球路绫。\n晓风吹枕泪成冰。\n梅梢霜露零。\n金鸭暖，宝熏腾。\n晴窗粘冻蝇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17040, '醉桃源・阮郎归', '陈允平', '青青杨柳拂堤沙。\n溪头沽酒家。\n吟成醉笔走龙蛇。\n春风双鬓华。\n歌楚女，舞吴娃。\n轻烟笼翠霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17041, '凤来朝', '陈允平', '百媚春风面。\n凤箫催、绿么舞遍。\n玉鸾钗、半溜乌云乱。\n悄疑是、梦中见。\n曲叹弓弯袖敛。\n绣芙蓉、香尘未断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17042, '垂丝钓', '陈允平', '鬓蝉似羽。\n轻纨低映娇妩。\n凭阑看花，仰蜂粘絮。\n春未许。\n宝筝闲玉柱。\n东风暮。\n武陵溪上路。\n娉婷婀娜。\n刘郎依约曾遇。\n鸳俦凤侣。\n重记相逢处。\n云隔阳台雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17043, '芳草渡・系裙腰', '陈允平', '芳草渡。\n渐迤逦分飞，鸳俦凤侣。\n洒一枝香泪，梨花寂寞春雨。\n惜别情思苦。\n匆匆深盟诉。\n翠浪远，六幅蒲帆，缥缈东去。\n远顾。\n夕阳冉冉，恨逐潮回南浦路。\n漫空念、归来燕子，双栖旧庭户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17044, '相思引', '陈允平', '金谷园林锦绣香。\n踏青挑菜又相将。\n凤台人远，离思入三湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17045, '谒金门', '胡仲弓', '蛾黛浅。\n只为晚寒妆懒。\n润逼镜鸾红雾满。\n额花留半面。\n渐次梅花开遍。\n花外行人已远。\n欲寄一枝嫌梦短。\n湿云和恨翦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17046, '水龙吟', '施岳', '翠鳌涌出沧溟，影横栈壁迷烟墅。\n楼台对起，阑干重凭，山川自古。\n梁苑平芜，汴堤疏柳，几番晴雨。\n看天低四远，江空万里，登临处、分吴楚。\n两岸花飞絮舞。\n度春风、满城箫鼓。\n英雄暗老，昏潮晓汐，归帆过舻。\n淮水东流，塞云北渡，夕阳西去。\n正凄凉望极，中原路杳，月来南浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17047, '清平乐', '施岳', '水遥花瞑。\n隔岸炊烟冷。\n十里垂杨摇嫩影。\n宿酒和愁都醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17048, '解语花', '施岳', '云容冱雪，暮色添寒，楼台共临眺。\n翠丛深。\n无人处、数蕊弄春犹小。\n幽姿谩好。\n遥相望、含情一笑。\n花解语，因甚无言，心事应难表。\n莫待墙阴暗老。\n称琴边月夜，笛里霜晓。\n护香须早。\n东风度、咫尺画阑琼沼。\n归来梦绕。\n歌云坠、依然惊觉。\n想恁时，小几银屏冷未了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17049, '曲游春', '施岳', '画舸西泠落，占柳阴花影，芳意如织。\n小楫冲波，度麴尘扇底，粉香帘隙。\n岸转斜阳隔。\n又过尽、别船箫笛。\n傍断桥、翠绕红围，相对半篙晴色。\n顷刻。\n千山暮碧。\n向沽酒楼前，犹系金勒。\n乘月归来，正梨花夜缟，海棠烟幕。\n院宇明寒食。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17050, '兰陵王', '施岳', '柳花白。\n飞入青烟巷陌。\n凭高处，愁锁断桥，十里东风正无力。\n西湖路咫尺。\n犹阻仙源信息。\n伤心事，还似去年，中酒恹恹度寒食。\n闲窗掩春寂。\n但粉指留红，茸唾凝碧。\n歌尘不散蒙香泽。\n念鸾孤金镜，雁空瑶瑟。\n芳时凉夜尽怨忆。\n梦魂省难觅。\n鳞鸿，渺踪迹。\n纵罗帕亲题，锦字谁织。\n缄情欲寄重城隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17051, '步月', '施岳', '玉宇薰风，宝阶明月，翠丛万点晴雪。\n炼霜不就，散广寒霏屑。\n采珠蓓、绿萼露滋，嗔银艳、小莲冰洁。\n花痕在，纤指嫩痕，素英重结。\n枝头香未绝。\n还是过中秋，丹桂时节。\n醉乡冷境，怕翻成消歇。\n玩芳味、春焙旋熏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17052, '醉落魄・一斛珠', '薛梦桂', '单衣乍著。\n滞寒更傍东风作。\n珠帘压定银钩索。\n雨弄新晴，轻旋玉尘落。\n花唇巧借妆红约。\n娇羞才放三分萼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17053, '眼儿媚', '薛梦桂', '碧筒新展绿蕉芽。\n黄露洒榴花。\n蘸烟染就，和云卷起，秋水人家。\n只因一朵芙蓉月，生怕黛帘遮。\n燕衔不去，雁飞不到，愁满天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17054, '三姝媚', '薛梦桂', '蔷薇花谢去。\n更无情、连夜送春风雨。\n燕子呢喃，似念人憔悴，往来朱户。\n涨绿烟深，早零落、点池萍絮。\n暗忆年华，罗帐分钗，又惊春暮。\n芳草凄迷征路。\n待去也，还将画轮留住。\n纵使重来，怕粉容销腻，却羞郎觑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17055, '浣溪纱・浣溪沙', '薛梦桂', '柳映疏帘花映林。\n春光一半几销魂。\n新诗未了枕先温。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17056, '大有', '潘希白', '戏马台前，采花篱下，问岁华、还是重九。\n恰归来、南山翠色依旧。\n帘栊昨夜听风雨，都不似、登归时候。\n一片宋玉情怀，十分卫郎清瘦。\n红萸佩、空对酒。\n砧杆动微寒，暗欺罗袖。\n秋已无多，早是败荷衰柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17057, '贺新郎', '文及翁', '一勺西湖水。\n渡江来、百年歌舞，百年酣醉。\n回首洛阳花世界，烟渺黍离之地。\n更不复、新亭坠泪。\n簇乐红妆摇画艇，问中流、击楫谁人是。\n千古恨，几时洗。\n余生自负澄清志。\n更有谁、溪未遇，传严未起。\n国事如今谁倚仗，衣带一江而已。\n便都道、江神堪恃。\n借问孤山林处士，但掉头、笑指梅花蕊。\n天下事，可知矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17058, '失调名', '文及翁', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17059, '击梧桐', '李珏', '枫叶浓於染。\n秋正老、江上征衫寒浅。\n又是秦鸿过，霁烟外，写出离愁几点。\n年来岁去，朝生暮落，人似吴潮展转。\n怕听阳关曲，奈短笛唤起，天涯情远。\n双屐行春，扁舟啸晚。\n忆昔鸥湖莺苑。\n鹤帐梅花屋，霜月後、记把山扉牢掩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17060, '木兰花慢', '李珏', '故人知健否，又过了、一番秋。\n记十载心期，暮苔茅屋，杜若芳洲。\n天遥梦飞不到，但滔滔、岁月水东流。\n南浦春波旧别，西山暮雨新愁。\n吴钩。\n光透黑貂裘。\n客思晚悠悠。\n更何处相逢，残更听雁，落日呼鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17061, '步蟾宫', '钟过', '东风又送酴信。\n早吹得、愁成潘鬓。\n花开犹似十年前，人不似、十年前俊。\n水边珠翠香成阵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17062, '水调歌头', '谭方平', '富贵在何许，五十已平头。\n人生得失且笑，休遣两眉愁。\n管甚轮云世变，管甚风波世态，沙渚且盟鸥。\n止即尽教止，流即尽教流。\n田坷秫，山可簌，又何求。\n问天只觅穷健，游戏八千秋。\n好对梅花如粉，细剪烛花如豆，不改旧时游。\n翠袖更能舞，骑鹤上扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17063, '水调歌头', '马廷鸾', '把酒对湘浦，独吊大夫醒。\n当年皇览初度，饮露更餐英。\n服以高冠长佩，扈以江蓠薜芷，御气独乘清。\n谁意椒兰辈，从臾武关盟。\n哭东门，哀郢路，悄无宁。\n人世纷纷起灭，遗臭与留馨。\n一笑还游轻举，三叹道长世短，晦朔自秋春。\n洗眼看物变，朝菌共灵椿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17064, '齐天乐', '马廷鸾', '老夫耄矣，怪新年顿尔，□衰俱现。\n排闷篇诗，浇愁盏酒，自读离骚自劝。\n长安日远。\n怅旧国禾宫，故侯瓜畹。\n风景不殊，江涛如此世缘浅。\n莫莫休休□□，□□乾坤毁，幽怀无限。\n弱羽填波，轻装浮海，其奈沧溟潋滟。\n年华婉娩。\n况六十平头，底须顽健。\n戏唱高词，作还丹九转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17065, '沁园春', '马廷鸾', '杨柳依依，我生之辰，与公共之。\n叹袅娜章台，歌翻轻吹，飘零灞岸，影弄斜晖。\n花萼楼深，灵和殿古，人自凄凉柳自垂。\n相逢处，记吾侬坠地，嘉定明时。\n何须梦得君知。\n便稳道人生七十稀。\n笑桓大将军，枝条如此，陶潜处士，门巷归兮。\n几阵花飞，一池萍碎，又向先生把寿卮。\n年年好，祝东风万楼，老翠云齐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17066, '水调歌头', '马廷鸾', '老子早知退，鸥鹭未盟寒。\n痴顽逾六望七，宁以寿为欢。\n风有黍离伤咽，雅有蓼莪憔悴，使我不能餐。\n更把南陔读，泪落广陵澜。\n踏峨峰，腾华顶，卧王宫。\n青山与汝卒岁，紫茹可登盘。\n乞得白翁归处，莫学缁郎更误，危梦倚栏干。\n多谢长生曲，颜面怕人看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17067, '失调名', '马廷鸾', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17068, '桂殿秋', '李仁本', '飞翠盖，走篮舆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17069, '桂殿秋', '李仁本', '兽石，错虬松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17070, '桂殿秋', '李仁本', '金带重，紫袍宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17071, '沁园春', '谢枋得', '十五年来，逢寒食节，皆在天涯。\n叹雨濡露润，还思宰柏，风柔日媚，羞看飞花。\n麦饭纸钱，只鸡斗酒，几误林间噪喜鸦。\n天笑道，此不由乎我，也不由他。\n鼎中炼熟丹砂。\n把紫府清都作一家。\n想前人鹤驭，常游绛阙，浮生蝉蜕，岂恋黄沙。\n帝命守坟，王令修墓，男子正当如是邪。\n又何必，待过家上冢，画锦荣华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17072, '满江红', '莫起炎', '法在先天，玄妙处、无言可说。\n其要在、守乎中正，灵台莹彻。\n太极神居黄谷内，先天气在玄关穴。\n寂然不动感而通，凭刚烈。\n运风雷，祈雨雪。\n役鬼神，驱妖孽。\n只此是、非咒非符非罡诀。\n寂定神归元谷府，功成行满仙班列。\n玩太虚、稳稳驾祥云，朝金阙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17073, '木兰花慢', '牟', '山城如斗大，君肯为、两年留。\n问读易堂前，け然松竹，留得君不。\n天边乍传消息，趁春风、归侍翠云裘。\n留取去思无限，江离香满汀洲。\n不妨无蟹有监州。\n臭味喜相投。\n怪底事朝来，骊歌催唱，唤起离愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17074, '千秋岁', '牟', '平分敏手。\n更觉山城小。\n聊岸帻，时舒啸。\n当年湓浦月，偏照香山老。\n头未白，而今半百才逾九。\n共说东园好。\n问春馀多少。\n红药晚，金沙早。\n花须风日耐，人看功名久。\n催洗盏，对花一笑为君寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17075, '鹧鸪天', '牟', '鸠杖庞眉鹤发仙。\n诗中有史笔如椽。\n爱莲自是平生趣，吟到梅花晚更坚。\n珍九鼎，食万钱。\n谁如有子采衣鲜。\n蜀陈旧事君须记，贵盛还当具庆年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17076, '渔家傲', '牟', '病枕逢逢惊晓鼓。\n那堪送客江头路。\n莫唱骊驹催客去。\n风又雨。\n花飞一片愁千缕。\n折柳凄然无胜语。\n加餐更把篝衣护。\n泥滑篮舆须稳度。\n云飞处。\n亲闱安问应旁午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17077, '水调歌头', '牟', '表海归来後，眠食喜清安。\n身轻於鹄，上下山北与山南。\n何必交梨火枣，自是霜筠雪柏，岁晚越坚完。\n摩诘本无病，微笑指蒲团。\n天有意，留一老，殿诸贤。\n平生出处何似，试把二苏看。\n惟有黄门最贵，况是庞眉寿□，九秩阅人间。\n持此公寿，即是寿元元。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17078, '念奴娇', '牟', '山之天目，蔚苕、第一最佳泉石。\n见说老龙高卧处，正拥深深寒碧。\n独云扉，人思霖雨，未许无心出。\n苍崖赤子，而今谁为苏息。\n昨夜凉透西风，玉绳晚澹，喜见归鸿入。\n十二虚皇凝伫久，飞下陆离宸画。\n绣卣使名，洪枢衔位，催缀新班立。\n旗常婀娜，要陪沙路清跸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17079, '贺新郎', '牟', '云拥油幢碧。\n眷蓬莱、宿缘一纪，竟须公出。\n上界清高仙地位。\n耿耿为民还切。\n此自是、平生愿力。\n雨後新飙凉如濯，喜湖山、千里皆生色。\n便乘此，问阊阖。\n殷勤好与摩铜狄。\n炯精神、依然未老，鹤标龟息。\n造物生贤非无意，偏近中元时节。\n试记取、平园莱国。\n况有盘洲当家样，酉年秋、拾级升枢极。\n继盛事，看今日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17080, '满江红', '牟', '七荚新春，问底事、以人为日。\n记贞观、郑公恰至，名因人得。\n况是今朝生上相，老天著意尤端的。\n便唤为、人日岂徒哉，公人杰。\n宇宙要，公扶植。\n善类要，公收拾。\n愿我公千岁，长陪丹极。\n山立扬休人正健，耐寒彩胜华发。\n看年年、天际不曾阴，真奇特。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17081, '水调歌头', '牟', '叔父茅封贵，先帝棣华亲。\n平生为善最乐，夙德宛天人。\n玉叶金枝方茂，瑶沼丹壶如画，光景镇长新。\n五福一日寿，万象总皆春。\n正秋分，记初度，绂缠麟。\n传宣来自绛阙，瑞采蔚轮。\n乐有钧天九奏，尊有仙家九酝，翠釜紫驼珍。\n笑把南山指，还以祝严宸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17082, '瑞鹤仙', '徐理', '暮霞红映沼。\n恨柳枝疏瘦，不禁风搅。\n投林数归鸟。\n更枯茎敲荻，糁红堆蓼。\n江寒浪小。\n雁来多、音书苦少。\n试看尽，水边红叶，不见有诗流到。\n烦恼。\n凭阑人去，枕水亭空，路遥天杳。\n情深恨渺。\n无计诉与伊道。\n漏声催，门外霜清风细，月色今霄最好。\n怎割舍，美景良时，等闲睡了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17083, '醉蓬莱', '吴季子', '正淡烟疏雨，梅子黄时，清和天气。\n阿母当年，暂辍瑶池会。\n霞帔星冠，霓旌羽纛，下碧霄云际。\n恰与瞿昙，同时共日，降人间世。\n裼寝开祥，斑衣祝寿，一种灵椿，两枝仙桂。\n满引玻璃，且向今霄醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17084, '念奴娇', '吴季子', '雪罗初试，过赐衣时节，才三四日。\n记得延陵公子宅，麟角当年新绂。\n半刺名家，一经奥学，是青云人物。\n如何华发，蒲轮未聘遗逸。\n问讯怨鹤惊猿，不妨俱隐，且逍遥丈室。\n有子传家经可教，况有东皋种秫。\n醉里乾坤，闲中日月，便是长生术。\n瑶池宴後，剩看几度桃实。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17085, '声声慢', '何梦桂', '人间六月。\n好是王母瑶池，吹下冰雪。\n一片清凉，仙界蕊宫珠阙。\n金猊水沉未冷，看瑶阶、九开荚。\n尚记得，那年时手种，蟠桃千叶。\n庭下阿儿痴绝。\n争戏舞、绿袍环。\n笑捧金卮，满砌兰芽初茁。\n七十古来稀有，且高歌、万事休说。\n天未老，尚看他、儿辈事业。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17086, '八声甘州', '何梦桂', '对芙蓉峰晓，雪初消、云□霭烟霏。\n是阿谁寿母，紫鸾笙里，玉液琼枝。\n元是云翘仙子，珥节度瑶池。\n手种碧莲子，长记年时。\n此地神仙宫阙，几花封玉诰，金帔霞衣。\n但寿星堂上，七十古来稀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17087, '八声甘州', '何梦桂', '对千峰未晓，听西风、吹角下谯楼。\n拥貔貅千骑，旌十里，送客芳洲。\n曾是灯棋月柝，赞画坐清油。\n折尽长亭柳，莫系行舟。\n忆昔相逢何处，看飞鸿雪迹，休更回头。\n百年心事，长逐水东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17088, '满庭芳', '何梦桂', '燕子芹乾，龙孙箨老，绿阴深锁林塘。\n午风庭院，人试薄罗裳。\n数尽落红飞絮，摘青梅、煮酒初尝。\n重门静，一帘疏雨，消尽水沉香。\n把当年团扇，恩情犹在，未是相忘。\n笑衰翁鬓发，早已苍苍。\n说与乘鸾彩女，看世间、多少炎凉。\n都休怨，百年一梦，且共醉霞觞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17089, '踏莎行', '何梦桂', '夜月楼台，夕阳庭院。\n都将前事思量遍。\n当初识面待寻常，争知识後情如线。\n只怕梅梢，参横斗转。\n催人归去天涯远。\n断肠当在别离时，未曾说著肠先断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17090, '摸鱼儿', '何梦桂', '记年时、人人何处，长亭曾共尊酒。\n酒阑归去行人远，折不尽长亭柳。\n渐白首。\n待把酒送君，恰又清明後。\n青条似旧。\n问江北江南，离愁如我，还更有人否。\n留不住，强把蔬盘瀹韭。\n行舟又报潮候。\n风急岸花飞尽也，一曲啼红满袖。\n春波皱。\n青草外，人间此恨年年有。\n留连握手。\n叹人世相逢，百年欢笑，能得几回又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17091, '摸鱼儿', '何梦桂', '把人间、古今勋业，一时都付杯酒。\n青山行遍人华发，老尽门前青柳。\n试回首。\n记晓雨征衫，又过年时候。\n相逢故旧。\n浪说南楼北，亭花纵好、能似少年否。\n还自笑，应是山林厌韭。\n忘却儿童迎候。\n兴来谩学长沙舞，要舞更无长袖。\n眉休皱。\n欢笑外，风涛世上时时有。\n共君握手。\n且尽日尊前，相拌一醉，醉後明朝又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17092, '意难忘', '何梦桂', '避暑林塘。\n数元戎小队，一簇红妆。\n旌云影动，帘幕水沉香。\n金缕彻，玉肌凉。\n慢拍舞轻扬。\n更一般，轻弦细管，孤竹空桑。\n风姨昨夜痴狂。\n向华峰吹落，云锦天裳。\n波神藏不得，散作满池芳。\n移彩，柳阴傍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17093, '喜迁莺', '何梦桂', '留春不住。\n又早是清明，杨花飞絮。\n杜宇声声，黄昏庭院，那更半帘风雨。\n劝春且休归去。\n芳草天涯无路。\n悄无语。\n倚阑干立尽，落红无数。\n谁诉。\n长门事，记得当年，曾趁梨园舞。\n霓羽香消，梁州声歇，昨梦转头今古。\n金屋玉楼何在，尚有花钿尘土。\n君不顾。\n怕伤心，休上危楼高处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17094, '临江仙', '何梦桂', '十月江南风信早，梅枝早先春。\n田园剩得老来身。\n浪言陶处士，犹是晋朝臣。\n人道革爻居四九，谁知数在。\n明年五十志当伸。\n低头羞老妇，且结会稽盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17095, '满江红', '何梦桂', '春色三分，怎禁得、几番风力。\n又早见、亭台绿水，柳摇金色。\n满眼春愁无著处，知心惟有幽禽识。\n望青山、目断夕阳边，孤云隔。\n琴酒我，成三一。\n湖外舫，山头屐。\n且莫教春去，乱红堆积。\n记得年时陪宴赏，重门深处桃花碧。\n待修书、欲寄楚天遥，无行客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17096, '忆秦娥', '何梦桂', '伤离别。\n江南雁断音书绝。\n音书绝。\n两行珠泪，寸肠千结。\n伤心长记中秋节。\n今年还似前年月。\n前年月。\n那知今夜，月圆人缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17097, '西江月', '何梦桂', '犹记春风庭院，柳阴深锁帘帷。\n东君去後雨丝丝。\n空认紫骝嘶处。\n梦断箫台无据，十年往事休追。\n忽然拈起旧来书。\n依旧长亭双泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17098, '小重山', '何梦桂', '吹断笙箫春梦寒。\n倚楼思往事，泪偷弹。\n别时容易见时难。\n相看处，惟有玉连环。\n人在万重山。\n近来应不似，旧时颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17099, '沁园春', '何梦桂', '光岳储精，宇宙呈祥，锺英俊材。\n想春秋夹谷，前生夫子，婆娑南赡，见在如来。\n龙角标辰，蟾胎楸檬巧缈ｓ细枥铮炊菸瑁郝刑āＶ刂睾檬孪啻摺１愣园鸦品庾檬倮８腹钌希珂蛐澹腹孟拢は芬吕场Ｗ蛞寡兀追臧⒛福捏刺姨沂荚浴Ｈ辏嶙樱晁晗伪');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17100, '满江红', '何梦桂', '睡起纱窗，问春信、几番风候。\n待去做、踏青鞋履，懒拈纤手。\n尘满翠微低ぢ叶，离愁推去来还又。\n把菱花、独对泪阑干，羞蓬首。\n回鸾子，空怀袖。\n金缕曲，无心奏。\n记碧桃花下，夜参横斗。\n六幅罗裙香凝处，痕痕都是尊前酒。\n到如今、肠断怕回头，长门柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17101, '沁园春', '何梦桂', '衮衣绣裳，彤弓卢矢，山西将门。\n自雪岭蓬婆，夷成坦道，炎州蜓獠，去连营。\n吴越儿童，江淮草木，七见元戎识姓名。\n争知道，这一隅斗大，尚借麾旌。\n西风吹下天声。\n看万骑貔貅入井陉。\n彼山棚魍魉，雷霆震击，海濒赤子，天日开明。\n事业方来，乾坤无尽，千古英雄不偶生。\n从兹去，看云台翼轸，麟阁丹青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17102, '水龙吟', '何梦桂', '倚窗闲嗅梅花，霜风入袖寒初透。\n吾年如此，年年十月，见梅如旧。\n白发青衫，苍头玄鹤，花前尊酒。\n问梅花与我，是谁瘦绝，正风雨、年时候。\n不怕参横月落，怕人生、芳盟难又。\n高楼何处，寒英吹落，玉龙休奏。\n前日花魁，後来羹鼎，总归严岫。\n但逋仙流落，诗香留与，孤山同寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17103, '酹江月・念奴娇', '何梦桂', '三分春色，更消得风雨，几番零落。\n年少不来春老去，空负省薇阶药。\n燕子飞忙，杜鹃啼杀，总为谁悲乐。\n临春结绮，旧家何处楼阁。\n一任年去年来，怅歌阑舞断，尘生帘幕。\n千古雷塘浑一梦，人世到头俱错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17104, '酹江月・念奴娇', '何梦桂', '问春何去，乱随风飞坠，杨花篱落。\n罗袜香囊无觅处，谁有返魂灵药。\n细柳重门，碧桃深巷，回首曾行乐。\n玉龙吟断，夜深人在江阁。\n因念壁月琼枝，对玉人何处，绣帘珠幕。\n一半青铜尘满匣，空抚鸾刀金错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17105, '沁园春', '何梦桂', '老去无心，看尽青山，山前暮云。\n问重来海燕，乌衣安在，乍归辽鹤，华表空存。\n世路悠悠，风尘渺渺，白发相催乌兔频。\n浮生事，算天涯海角，谁是闲人。\n几番甲子庚申。\n看青草年年秋又春。\n笑武陵源上，桃花未实，山下，瑶树长新。\n霓羽飘零，蛾眉萧飒，欲觅神仙隔两尘。\n草堂在，但休教山鬼，夜半移文。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17106, '摸鱼儿', '何梦桂', '把心期、半生孤负。\n玉堂元在何处。\n朱弦弹绝无人听，空操离鸾烈女。\n遇不遇。\n休更问、悠悠世事都如许。\n人生草露。\n看百岁勋名，青铜鬓影，抚剑泪如雨。\n知谁语。\n落落江空岁暮。\n人间一梦今古。\n雷塘十里斜阳外，野草寒鸦无数。\n身世寓。\n聊尔耳、江山有恨谁堪付。\n冰心更苦。\n都说与梅花，参横月落，一醉且归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17107, '洞仙歌', '何梦桂', '天涯何处，望苍江渺渺。\n纵算解飞人不到。\n笑双丸乌兔，两鬓霜蓬，聊尔耳，那是人间三岛。\n黄梁初梦觉，起看孤云，还自长歌自长啸。\n不记桃源何地，橘渚何年，生涯事、惟有炉烟茶灶。\n问先生谁友，有白石青松，共成三老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17108, '喜迁莺', '何梦桂', '东君别後。\n见说道花枝，也成消瘦。\n夜雨帘栊，柳边庭院，烦恼有谁就。\n犹记旧看承处，梅子枝头如豆。\n最苦是，向重门人静，月明时候。\n知否。\n人不见，纵有音书，争似重携手。\n旧日沉腰，如今潘鬓，怎奈许多。\n极目万山深处，肠断不堪回首。\n情寸寸，到如今，只在长亭烟柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17109, '沁园春', '何梦桂', '尚书当年，蓬矢桑弧，初度佳期。\n是词林老虎，文场威凤，人中祥瑞，天下英奇。\n太守买臣，中书坡老，五十二年回首非。\n人间事，且开眉一笑，醉倒金卮。\n阿婆还忆年时。\n也曾趁鸿胪拜玉墀。\n念青衫荷叶，嫁衣尚在，青铜菱影，破镜犹遗。\n半席寒毡，一官俯首，造物还应戏小儿。\n问天道，看是他谁戏我，我戏他谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17110, '八声甘州', '何梦桂', '倚阑干立尽，看东风、吹度柳绵飞。\n怕杜鹃啼杀，江南雁杳，游子何之。\n梦断扬州芍药，落尽簇红丝。\n歌吹今何在，一曲沾衣。\n往事不堪重省，记柳边深巷，花外幽墀。\n把菱花独照，脂粉总慵施。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17111, '八声甘州', '何梦桂', '自辽东鹤去，算何人、插得翅能飞。\n笑平生错铸，儒冠误识，者也焉之。\n谩道寒蚕冰底，瓮茧解成丝。\n何许丝千丈，补得龙衣。\n镜里不堪勋业，纵梦中八翼，不到天墀。\n看间富贵，妻妾笑施施。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17112, '贺新郎', '何梦桂', '世事浑无定。\n问人间、翻来覆去，阿谁能忍。\n海怒惊涛山相拍，选甚鱼龙不任。\n看今古、英雄销尽。\n坐对青山闲白日，付长江、流送千年恨。\n天有意，唯何甚。\n待将洗耳泉边枕。\n正梅花、霜寒月白，斗回西柄。\n自寿一觞花前醉，醉彩幡金胜。\n笑儿辈、汾阳中令。\n倚遍层楼干阑曲，慨乾坤、渺渺青云影。\n无限事，尊前兴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17113, '贺新郎', '何梦桂', '花落风初定。\n倚危阑、衷情欲诉，踌躇不忍。\n把酒问春春无语，吹落游尘怎任。\n待泪雨、红妆蔫尽。\n不道燕衔春将去，误啼鹃、唤起年年恨。\n芳草路，人愁甚。\n浮生一梦黄梁枕。\n且不妨、狂歌醉舞，麈谈挥柄。\n金谷平泉俱尘土，谁是当年豪胜。\n但五柳、依然陶令。\n千古兴亡东流水，望孤鸿、没处残阳影。\n无限意，伤春兴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17114, '贺新郎', '何梦桂', '更静钟初定。\n卷珠帘、人人独立，怨怀难忍。\n欲拨金猊添沉水，病力厌厌不任。\n任蝶粉、蜂黄消尽。\n亭北海棠还开否，纵金钗、犹在成长恨。\n花似我，瘦应甚。\n凄凉无寐闲衾枕。\n看夜深、紫垣华盖，低摇杠柄。\n重拂罗裳蹙金线，尘满双鸳花胜。\n孤负我、花期春令。\n不怕镜中羞华发，怕镜中、舞断孤鸾影。\n天尽处，悠悠兴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17115, '八声甘州', '何梦桂', '叹人生聊尔，便晨风、翼倦也回飞。\n况自骑款段，欲追骐骥，千里安之。\n种得玄芝瑶草，不染满头丝。\n一醉梅花下，笑舞青衣。\n说甚封侯万里，待朱门画战，大第崇墀。\n人世何时□足，造物任隆施。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17116, '洞仙歌', '何梦桂', '青衫白发，独倚江楼小。\n待欲题诗压崔颢。\n慨凤台今在否，白鹭沙洲，芳草外、剩得闲身江表。\n醉来疑梦里，梦入梅花，歌彻青衣听清窈。\n起着飞鸿没尽，白鸟玄驹，谁能数、曹瞒袁绍。\n待明年、七十问何如，笑只是今朝，浣花堂老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17117, '玉漏迟', '何梦桂', '问春先开未，江南野水，得春初小。\n独殿群芳，却道花前开早。\n长苦冰霜压尽，更说甚、风标清窈。\n些子好。\n孤香冷艳，有谁知道。\n年年吹落还开，听画角楼头，送他昏晓。\n何处玉堂，满地苍苔不扫。\n谁是肝肠铁石，与共说、岁寒怀抱。\n花未老。\n无奈酒阑情好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17118, '蓦山溪', '何梦桂', '飞仙欲下，水殿严妆早。\n娇湿怕春知，跨白虬、天门未晓。\n霓裳零乱，肌骨自清妍，梅檐月，柳桥风，世上红尘杳。\n重门深闭，忘却山阴道。\n呼酒嚼琼花，任醉来、玉山倾倒。\n无言相对，这岁暮心期，茅舍外，玉堂前，处处风流好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17119, '蓦山溪', '何梦桂', '春工未觉，何处琼英早。\n夜半翦银河，到人间、楼台初晓。\n霏霏脉脉，不是不多情，金帐暖，玉堂深，却怪音尘杳。\n天公谪下，暂落红尘道。\n颜色自还怜，怕轻狂、随风颠倒。\n冰心谁诉，但吹入梅花，明月地，白云阶，相照天寒好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17120, '蓦山溪', '何梦桂', '蓬蓬，睡梦惊回早。\n谁为散天花，遍人间，夜深分晓。\n虚空幻出，富贵照乾坤，琼万顷，玉千株，莫道壶天杳。\n平明三尺，不拣江南道。\n只怕不坚牢，被天工、小儿翻倒。\n凝冰泮水，世态总无凭，明日事，昨朝人，谁丑还谁好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17121, '沁园春', '何梦桂', '孔盖霓旌，月佩云裳，人间女仙。\n问韶光九十，何如今待，明朝最处，好是明年。\n戏舞称觞，一堂家庆，眼见儿孙曾又玄。\n奇绝处，看菱花白发，不改朱颜。\n当年。\n手种红莲。\n笑几度桑田沧海乾。\n想蟾胎炼就，紫皇灵药，龙髯飞坠，玉女云。\n青鸟重来，红霞俨在，一曲云和犹未闲。\n羞尘世，把蛾眉蝉鬓，空为谁妍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17122, '浣溪沙', '何梦桂', '细柳连营绿荫重。\n暖风旗影扬蛇龙。\n昼闲吟思入千峰。\n紫绶金牌人绿发，绣鞯丝辔马青骢。\n会将三箭取侯封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17123, '浣溪沙', '何梦桂', '金紫山前山万重。\n山高云密下苍龙。\n春来好雨遍三峰。\n芳草郊原眠茧犊，垂杨营垒系花骢。\n趣归行有紫泥封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17124, '蝶恋花', '何梦桂', '风信花残吹柳絮。\n柳外池塘，乳燕时飞度。\n漠漠轻云山约住。\n半村烟树鸠呼雨。\n竹院深深深几许。\n深处人闲，谁识闲中趣。\n弹彻瑶琴移玉柱。\n苍苔满地花阴午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17125, '大江东去・念奴娇', '何梦桂', '半生习气，被风霜、销尽头颅如许。\n七十年来都铸错，回首邯郸何处。\n杜曲桑麻，柴桑松菊，归计成迟暮。\n一樽自寿，不妨沉醉狂舞。\n休问沧海桑田，看朱颜白发，转次全故。\n乌兔相催天也老，千古英雄坏土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17126, '玉漏迟', '何梦桂', '青衫华发，对风霜、倚遍危楼孤啸。\n恶浪平波，看尽世间多少。\n忘却金闺故步，都付与、野花啼鸟。\n祗自笑。\n悠悠心事，无人知道。\n扰扰世路红尘，看销尽英雄，青山亦老。\n宇宙无穷，事业到头谁了。\n高楼一声画角，把千古、梦中吹觉。\n天欲晓。\n起看蕊梅春小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17127, '玉漏迟', '何梦桂', '自怜翠袖，向天寒、独倚孤篁吟啸。\n半世虚名，孤负白云多少。\n欲问梅翁旧约，怕误我、沙头鸥鸟。\n时一笑。\n行行且止，人间蜀道。\n休怪岁月无情，叹尘世浮生，闲忙闲老。\n待趁黑头，万里封侯都了。\n今古勋名一梦，听未彻、钧天还觉。\n羌管晓。\n楼角曙星稀小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17128, '水龙吟', '何梦桂', '分知白首天寒，千林摇落寻真隐。\n天工付与，冰肌雪骨，暗香寒凝。\n自许负心，肯教色界，软红尘近。\n怅绿衣舞断，参横梦觉，依稀旧家犹认。\n不为角声落，向花前、为伊悲恨。\n玉堂茅舍，风流随处，年年孤另。\n不是人间，肝肠铁石，相逢休问。\n算知心、只许东风，漏泄一分春信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17129, '八声甘州', '何梦桂', '恨公来较晚，早归朝、骢马去难留。\n是朱轮华毂，联叠组，家世公侯。\n今在玉堂深处，借重护偏州。\n好把青毡拂，奕世勋猷。\n明日东津归路，正梅花霜暧，春上枝头。\n看连旗列鼓，送客下江楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17130, '传言玉女', '何梦桂', '阿母今朝，飞下琼楼金阙。\n先教玉女，为传言细说。\n蟠桃手种，尚记此春时节。\n三千春後，开花初结。\n宴罢瑶池，洗娥眉、已半雪。\n九旬偷度，笑韶光一映。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17131, '最高楼', '何梦桂', '南山老，还记少陵诗。\n七十古来稀。\n清池拥出红蕖坠，西风吹上碧梧枝。\n趁今朝，斟寿酒，记生时。\n也不羡、鲲鹏飞击水。\n也不羡、蛟龙行得雨。\n人世事，总危机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17132, '摸鱼子', '赵必', '倚西风、招鸿送燕，年华今已如客。\n青奴一饷贪凉梦，昨夜酒红无力。\n愁似织。\n听鸣叶寒蝉，话到情无极。\n舞衣春入。\n欢带眼偷移，琴心不断，襟袖旧时窄。\n红尘陌。\n谁寄佳人消息。\n任他珠网瑶瑟。\n金钗两鬓霓裳曲，总是浪歌闲拍。\n长夜笛。\n且慢析轻匀，留醉酒垆侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17133, '西江月', '林自然', '二十馀年访道，经游万水千山。\n明师未遇肯安闲。\n几度拈香一瓣。\n幸遇至人说破，虚无妙用循环。\n工夫只在片时间。\n遍体神光灿烂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17134, '酹江月・念奴娇', '林自然', '凿开混沌，见钱塘南控、长江凝碧。\n今古词人图此景，谁解推原端的。\n岁去年来，日庚月甲，因甚无差忒。\n如今说破，要知天地来历。\n道散有一强名，五行颠倒，互列乾坤历。\n坎水逆流朝丙户，随月盈亏消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17135, '念奴娇', '奚?', '踏破秋痕，向虚堂、细问新凉踪迹。\n野客从来无管领，独鹤自还空碧。\n红日重开，翠华曾到，应恨湖光窄。\n游龙别後，两山依旧南北。\n无语野草闲花，似嗔人问，万事今非昔。\n古木苍烟无限意，只有吟魂知得。\n歌舞百年，是非一醉，未必西风识。\n浩歌归去，满船风雨凄恻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17136, '长相思慢', '奚?', '日折霜檐，寒欺雾幕，晴枝浅弄春华。\n惊回绮梦，独拥绫衾，腮痕微印朝霞。\n倦起心情，念风移霜换，依旧天涯。\n雁影水云斜。\n算相思、一点愁赊。\n问橘楚橙吴，旧香犹在，别後襟袖输他。\n琴心知未许，想钿钗、流落谁家。\n怕上高楼，归思还、斜阳暮鸦。\n几多年、江湖浪识，知心只许梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17137, '声声慢', '奚?', '秋声淅沥，楚棹吴鞭，相逢易老颜色。\n桐竹鸣骚音韵，水云空觅。\n炎凉自今自古，信浮生、有谁禁得。\n漫回首，问黄花还念，故人犹客。\n莫管红香狼籍。\n兰蕙冷，偏他露知霜识。\n木落山空心事，对秋明白。\n征衣暗尘易染，算江湖、随人宽窄。\n正无据，看寒蟾、飞上暮碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17138, '解连环', '奚?', '霁环新掠。\n正风回浪影，时摇城脚。\n叹天涯、春草无伦，似凝伫当时，柳颦花弱。\n步锦珠沉，谩一眸、千年如昨。\n信龙楼凤阁，无奈都由，笑歌休却。\n斜阳柳边自落。\n听幽禽两两，沙际停泊。\n道世问、多少闲愁，总输与扁舟，五湖游乐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17139, '醉蓬莱', '奚?', '又扁舟东下，水树青圆，雨榴红薄。\n燕子愁多，在重重帘幕。\n杖山阴，而今休更问，月尖眉约。\n双杏盟寒，七香珠坠，歌尘飘泊。\n莫倚危阑，怨深黄竹，一鹤归来，乱峰飞落。\n笑色凌波，任雾抽烟邈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17140, '永遇乐', '奚?', '一雁斜阳，乱蛩衰草，天净秋远。\n独立西风，星星鬓影，疑被蕖霜染。\n蹇修何处，秋深湘水，隐约数峰青浅。\n想而今，亭亭皓月，共谁倚阑凄惋。\n瑶箱翠袭，玉奁芸剪，暗里泪化偷溅。\n一日思量，十年瘦削，春色回眸减。\n雕鸾好在，文箫重许，酒试香庭苑。\n正销魂，馀霞散碧，暮鸦数点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17141, '宴瑶池・越江吟', '奚?', '紫鸾飞舞，又东华宴罢，归步凝碧。\n缥缈天风吹送处，泠泠声清逸。\n青童两两，争笑拈、琪花半折。\n羽衣寒露香披，翠幢珠辂去云疾。\n西真还又传帝敕。\n霞城检校，问学仙消息。\n玉府高寒，有不老丹容，自然琼液。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17142, '齐天乐', '奚?', '金飙吹净人间暑。\n连朝弄凉新雨。\n万宝功成，无人解得，秋入天机深处。\n闲中自数。\n几心酌乾坤，手斟霜露。\n护了山河，共看元影在银兔。\n而今神仙正好，向青空觅个，冲澹襟宇。\n帝念群生，如何便肯，从我乘风归去。\n夷游洞府。\n把月抒云机，教他儿女。\n水逸山明，此情天付与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17143, '芳草', '奚?', '笑湖山、纷纷歌舞，花边如梦如薰。\n响烟惊落日，长桥芳草外，客愁醒。\n天风送远，向两山、唤醒痴云。\n犹自有、迷林去鸟，不信黄昏。\n销凝。\n油车归後，一眉新月，独印湖心。\n蕊宫相答处，空岩虚谷应，猿语香林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17144, '华胥引', '奚?', '澄空无际，一幅轻绡，素秋弄色。\n翦翦天风，飞飞万里，吹净遥碧。\n想玉杵芒寒，听环无迹。\n圆缺何心，有心偏向歌席。\n多少情怀，甚年年、共怜今夕。\n蕊宫珠殿，还吟飘香秀笔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17145, '玉漏迟', '赵闻礼', '絮花寒食路。\n晴丝日，绿阴吹雾。\n客帽欺风，愁满画船烟浦。\n彩柱秋千散後，恨尘锁、燕帘莺户。\n从间阻。\n梦云无准，鬓霜如许。\n夜永绣阁藏娇，记掩扇传歌，剪灯留语。\n月约星期，细把花须频数。\n弹指一襟幽恨，谩空倩、啼鹃声诉。\n深院宇。\n黄昏杏花微雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17146, '法曲献仙音', '赵闻礼', '花匣么弦，象奁双陆，旧日留欢情意。\n梦别银屏，恨裁兰烛，香篝夜闲鸳被。\n料燕子重来地，桐阴琐窗绮。\n倦梳洗。\n量芳钿、自羞鸳镜，罗袖冷，烟柳画兰半倚。\n浅雨压荼シ，指东风、芳事馀几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17147, '瑞鹤仙', '赵闻礼', '客边情味恶。\n花漏远、春静风鸣凤铎。\n空梁燕泥落。\n映柔红微，海棠帘箔。\n愁钟恨角。\n怕催人、黄昏索寞。\n拥吟袍、凭暖阑干，醉怯冷香罗薄。\n阿鹊。\n幽芳月淡，紫曲云昏，有人说著。\n名缰易缚。\n归鞭杳，误期约。\n记金泥卜画，银屏娱夜，弹指忽忽恨错。\n为情多、搀尽芳春，带围瘦觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17148, '瑞鹤仙', '赵闻礼', '冻痕消梦草。\n又招得春归，旧家池沼。\n园扉掩寒悄。\n倩谁将花信，偏传深窈。\n追游趁早，便裁却、春衫短帽。\n任残梅、飞满溪桥，和月醉眠清晓。\n年少。\n青丝织手，彩胜娇环，赋情谁表。\n南楼信杳。\n江云重，雁归少。\n记冲香嘶马，流红回岸，几度绿杨残照。\n想暗黄、依旧东风，灞陵古道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17149, '好事近', '赵闻礼', '人去绿屏闲，逗晓柳丝风急。\n帘外杏花微雨，春红愁湿。\n单衣催赐曲尘罗，中酒病无力。\n应是绣床慵困，倚秋千斜立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17150, '好事近', '赵闻礼', '小枕梦催闲，飞雨时鸣高屋。\n挂起西窗人静，听春禽声续。\n鸭塘溪绿涨轻痕，烟柳媚新绿。\n谁伴瘦筇尊酒，弄岩泉飞瀑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17151, '鱼游春水', '赵闻礼', '青楼临远水。\n楼上东风飞燕子。\n玉钩珠箔，密密锁红藏翠。\n剪胜裁幡春日戏。\n簇柳簪梅元夜醉。\n闲忆旧欢，暗弹新泪。\n罗帕啼痕未洗。\n愁见同心双凤翅。\n长安十日轻寒，春衫未试。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17152, '千秋岁', '赵闻礼', '莺啼晴昼，南国春如绣。\n飞絮眼，凭阑袖。\n日长花片落，睡起眉山斗。\n无个事，沉烟一缕腾金兽。\n千里空回首。\n两地厌厌瘦。\n春去也，归来否。\n五更楼外月，双燕门前柳。\n人不见，秋千院落清明後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17153, '风入松', '赵闻礼', '曲尘风雨乱春晴。\n花重寒轻。\n珠帘卷上还重下，怕东风、吹散歌声。\n棋倦杯频昼永，粉香花艳清明。\n十分无处著闲情。\n来觅娉婷。\n蔷薇误寻春袖，倩柔荑、为补香痕。\n苦恨啼鹃惊梦，何时翦烛重盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17154, '水龙吟', '赵闻礼', '几年埋玉蓝田，绿云翠水烘春暖。\n衣薰麝馥，袜罗尘沁，凌波步浅。\n钿碧搔头，腻黄冰脑，参差难翦。\n乍声沉素瑟，天风佩冷，蹁跹舞、霓裳遍。\n湘浦盈盈月满。\n抱相思、夜寒肠断。\n含香有恨，招魂无路，瑶琴写怨。\n幽韵凄凉，暮江空渺，数峰清远。\n粲迎风一笑，持花酹酒，结南枝伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17155, '隔浦莲近・隔浦莲近拍', '赵闻礼', '愁红飞眩醉眼。\n日淡芭蕉卷。\n帐掩屏香润，杨花扑、春云暖。\n啼鸟惊梦远。\n芳心乱。\n照影收奁晚。\n画眉懒。\n微醒带困，离情中酒相半。\n裙腰粉瘦，怕按六么歌板。\n帘卷层楼探旧燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17156, '贺新郎', '赵闻礼', '池馆收新雨。\n耿幽丛、流光几点，半侵疏户。\n入夜凉风吹不减，冷焰微茫暗度。\n碎影落、仙盘秋露。\n漏断长门空照泪，袖纱寒、映竹无心顾。\n孤枕掩，残灯炷。\n练囊不照诗人苦。\n夜沉沉、拍手相亲，呆儿痴女。\n栏外扑来罗扇小，谁在风廊笑语。\n竞戏踏、金钗双股。\n故苑荒凉悲旧赏，怅寒芜、衰草隋宫路。\n同磷火，遍秋圃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17157, '谒金门', '赵闻礼', '人病酒。\n生怕日高催绣。\n昨夜新翻花样瘦。\n旋描双蝶凑。\n慵凭绣床呵手。\n却说新愁还又。\n门外东风吹绽柳。\n海棠花厮勾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17158, '踏莎行', '赵闻礼', '照眼菱花，剪情菰叶。\n梦云吹散无踪迹。\n听郎言语识郎心，当时一点谁消得。\n柳暗花明，萤飞月黑。\n临窗滴泪研残墨。\n合欢带上旧题诗，如今化作相思碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17159, '摸鱼儿', '叶阊', '倚薰风、画阑亭午。\n采莲柔橹如语。\n红裙溅水鸳鸯湿，几度云朝雨暮。\n游冶处。\n是好是、小桥芳树寻幽趣。\n绣帘低护。\n任凉入霜纨，月侵冰簟，长夏等闲度。\n都如梦，怅望游仙旧侣。\n遗踪今在何许。\n愁予渺渺潇湘浦。\n槛竹空敲朱户。\n黯无绪。\n念多情文园，曾草长门赋。\n酒酣自舞。\n笑满袖缁尘，数茎霜鬓，羞杀照溪鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17160, '三姝媚', '杜良臣', '花浮深岸树。\n迎新曦窗影，细触游尘。\n映叶青梅，记共折南枝，又及尝新。\n驻屐危亭，烟墅杳、风物撩人。\n虹外斜阳留晚，莺边落絮催春。\n心事应辜桃叶，但自把新诗，遍写修筠。\n恨满芳洲，倩晚风吹梦，暗逐江云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17161, '齐天乐', '曹', '翠箫声断青鸾翼，心期破钗谁表。\n夜烛银屏，春风粉袖，犹记琵琶斜抱。\n瑶池路杳。\n恨巫女回云，月娥沉照。\n谩说蓬莱，玉环花貌梦难到。\n严花亭院乍冷，更蛩吟风碎，鸿飞烟渺。\n绿玉弹棋，红牙按拍，乐事欢情终少。\n刘郎未老。\n要鬓翼堆玄，腕酥凝皓。\n莫忘香荐，绿罗裙带草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17162, '瑞鹤仙', '曹', '炉烟销篆碧。\n对院落秋千，昼永人寂。\n浓春透花骨。\n正长红小白，晕香涂色。\n铜驼巷陌。\n想游丝、飞絮无力。\n念绣窗、深锁红鸾，虚度禁烟寒食。\n空忆。\n象床沉水，凤枕屏山，欢尤惜。\n粉香狼藉。\n海棠下、东风急。\n自秦台箫咽，汉皋冷，断雨零云难觅。\n但杏梁、双燕归来，似曾旧识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17163, '兰陵王', '曹', '杏花坼。\n烟柳藏鸦翠陌。\n苏堤上、人正踏青，嫩草茸茸衬罗袜。\n游丝挂晴塔。\n十里酣红艳白。\n秋千外，娇靥笑春，一片笙箫绮霞碧。\n阿香妒倾国。\n把镜日深奁，丝雨愁织。\n崇桃积李无颜色。\n但蝶粉香渍，燕泥芹冷，紫钱芳晕翳宝瑟。\n怅还近寒食。\n岑寂。\n恨无极。\n更酒驿孤烟，棋院长日。\n梨花满地春狼藉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17164, '玲珑四犯', '曹', '一架幽芳，自过了梅花，独占清绝。\n露叶檀心，香满万条晴雪。\n肌素净冼铅华，似弄玉、乍离瑶阙。\n看翠蛟、白凤飞舞，不管暮烟啼。\n酒中风格天然别。\n记唐宫、赐樽芳冽。\n玉蕤唤得馀春住，犹醉迷飞蝶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17165, '惜馀妍・惜余妍', '曹', '同根异色，看镂玉雕檀，芳艳如簇。\n秀叶玲珑，嫩条下垂修绿。\n禁华深锁清妍，香满架、风梳露浴。\n轻盈，便似觉、酴格调粗俗。\n蜂黄间涂蝶粉，疑旧日二乔，各样妆束。\n费却春工，斗合靓芳浓馥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17166, '宴山亭・燕山亭', '曹', '香月玲珑，柔风镂刻，嫩绿枝头圆腻。\n绯桃院宇，絮柳池塘，独立万红尘外。\n戏舞千团，讶粉羽、留连春媚。\n非是。\n看滚雪抛琼，镜鸾相倚。\n唐昌仙观风流，有霞洞藏花，绀环玉蕊。\n雕阑占赏，禁苑承恩，难比太平瑶卉。\n遍插金瓶，更移近、宝猊烟翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17167, '水调歌头', '郑雪岩', '甫营亭子小，花柳斩新裁。\n衰翁馀暇，何妨领客少徘徊。\n堪叹人生离合，恰似燕莺来往，光景暗中催。\n芦荻晚风起，明月满沙堆。\n去年秋，如此夜，有谁陪。\n欲挽天河无路，满眼总尘埃。\n未了痴儿官事，行止从来难定，又趣到苏台。\n不作别离句，共醉十分杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17168, '清平乐', '赵汝', '锦屏香褪。\n寒隐轻衫嫩。\n燕子护泥飞不稳。\n庭掩百花难认。\n双双绣带微风。\n海棠此夜帘栊。\n愁损一番寒食，小窗淡月残红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17169, '恋绣衾', '赵汝', '柳丝空有千万条。\n系不住、溪头画桡。\n想今宵、也对新月，过轻寒、何处小桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17170, '浣溪沙', '赵汝', '笑摘青梅傍绮疏。\n数枝花影漾前除。\n太湖石畔看金鱼。\n笋指晓寒慵出袖，翠鬟春懒不成梳。\n为君缝狭绣罗襦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17171, '梅花引', '赵汝', '对花时节不曾。\n见花残。\n任花残。\n小约帘栊，一面受春寒。\n题破玉笺双喜鹊，香烬冷，绕银屏，浑是山。\n待眠。\n未眠。\n事万千。\n也问天。\n也恨天。\n髻儿半偏。\n绣裙儿、宽了还宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17172, '摘红英', '赵汝', '东风冽。\n红梅拆。\n画帘几片飞来雪。\n银屏悄。\n罗裙小。\n一点相思，满塘春草。\n空愁切。\n何年彻。\n不归也合分明说。\n长安道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17173, '梦江南・忆江南', '赵汝', '帘不卷，细雨熟樱桃。\n数点霁霞山又晚，一痕凉月酒初消。\n风紧絮花高。\n闲处少，磨尽少年豪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17174, '谒金门', '赵汝', '羞说起。\n嚼破白桃花蕊。\n人在夕阳深巷里。\n燕儿来也未。\n一样半红半紫。\n双凤同心结子。\n分在郎边郎不记。\n为郎今拆碎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17175, '如梦令', '赵汝', '小砑红绫笺纸。\n一字一行春泪。\n封了更亲题，题了又还坼起。\n归未。\n归未。\n好个瘦人天气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17176, '汉宫春', '赵汝', '著破荷衣，笑西风吹我，又落西湖。\n湖间旧时饮者，今与谁俱。\n山山映带，似携来、画卷重舒。\n三十里、芙蓉步障，依然红翠相扶。\n一目清无留处，任屋浮天上，身集空虚。\n残烧夕阳过雁，点点疏疏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17177, '摸鱼儿', '谭宣子', '掩朱弦、住听金缕。\n天涯同是羁旅。\n多情记把香罗袖，残粉半粘荆树。\n还信否。\n便忍道、石台暗寂春无主。\n分明间阻。\n那睡鸭嘘云，翔鸳溜月，此际更休语。\n人间世，谁识缄愁最苦。\n轻帆重解烟雨。\n而今翻笑周郎误。\n挑剔寒缸寻谱。\n游倦处。\n果因甚、亭亭瘦影如前度。\n无由寄与。\n待谢却梅花，东风为我，吹梦过淮浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17178, '西窗烛', '谭宣子', '春江骤涨，晓陌微乾，断云如梦相逐。\n料应怪我频来去，似千里迢遥，伤心极目。\n为楚腰、惯舞东风，芳草萋萋衬绿。\n燕飞独。\n知是谁家箫声多事，吹咽寻常怨曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17179, '侧犯', '谭宣子', '素秋渐爽，倚香曲枕情依旧。\n怀袖。\n浸数尺湘漪、簟纹皱。\n悲欢尽梦里，玉骨从消瘦。\n空又。\n思太液芙蓉未央柳。\n翔凤何在，乐府传孤奏。\n人病酒。\n有鸳鸯双字倩谁绣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17180, '春声碎', '谭宣子', '津馆贮轻寒，脉脉离情如水。\n东风不管，垂杨无力，总雨颦烟寐。\n栏干外。\n怕春燕掠天，疏鼓叠、春声碎。\n刘郎易憔悴。\n况是恹恹病起。\n蛮笺漫展，便写就新词，倩谁将寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17181, '长相思', '谭宣子', '去路遥。\n归路遥。\n灯月光中立小桥。\n魂萦紫玉箫。\n风萧萧。\n雨萧萧。\n此夜相思空寂寥。\n梅花落丽谯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17182, '长相思', '谭宣子', '净亭亭。\n步盈盈。\n蝉影明绡傅体轻。\n水边无限情。\n翠尊倾。\n翠环倾。\n归去如何睡得成。\n西风吹酒醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17183, '谒金门', '谭宣子', '银漏滴。\n午夜平康巷陌。\n双掩兽环人语寂。\n馀香无处觅。\n回首旧游踪迹。\n绀碧染衣犹湿。\n一饷沉吟谁会得。\n月明春店笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17184, '谒金门', '谭宣子', '人病酒。\n生怕日高催绣。\n昨夜新翻花样瘦。\n旋描双蝶凑。\n闲凭绣床呵手。\n却说春愁还又。\n门外东风吹绽柳。\n海棠花厮勾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17185, '浣溪沙', '谭宣子', '欲展吴笺咏杜娘。\n为停楚棹觅秦郎。\n藕花三十六湖香。\n珠颗翠檠饶宿泪，玉痕红退怯晨妆。\n小桥风月思凄凉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17186, '玲珑四犯', '谭宣子', '碧黯塞榆，黄销堤柳，危栏谁料重抚。\n才情犹未减，指点惊如许。\n当时共伊东顾。\n为辞家、怕吟鹦鹉。\n衮衮波光，悠悠云气，陶写几今古。\n生尘每怜微步。\n渺江空岁晚，知在何处。\n土花封玉树。\n恨极山阳赋。\n吹芗扇底馀欢断，怎忘得、阴移庭午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17187, '鸣梭', '谭宣子', '织绡机上度鸣梭。\n年光容易过。\n萦萦情绪，似水烟山雾两相和。\n谩道当时何事，流盼动层波。\n巫影嵯峨。\n翠屏牵薜萝。\n不须微醉自颜酡。\n如今难凭麽。\n烛花销艳，但替人、垂泪满铜荷。\n赋罢西城残梦，犹问夜如何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17188, '江城子', '谭宣子', '嫩黄初染绿初描。\n倚春娇。\n索春饶。\n燕外莺边，想见万丝摇。\n便作无情终软美，天赋与，眼眉腰。\n短长亭外短长桥。\n驻金镳。\n系兰桡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17189, '渔家傲', '谭宣子', '深意缠绵歌宛转。\n横波停眼灯前见。\n最忆来时门半掩。\n春不暖。\n犁花落尽成秋苑。\n叠鼓收声帆影乱。\n燕飞又趁东风软。\n目力漫长心力短。\n消息断。\n青山一点和烟远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17190, '南乡子', '薛燧', '柳色锁重楼。\n楼上轻寒不满钩。\n堆径落红深半指，悠悠。\n飞絮帘栊几许愁。\n逐日望归舟。\n暖藕全宽玉臂。\n待得君来春去也，休休。\n未老鸳鸯早白头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17191, '伊州三台令・伊州三台', '杨韶父', '水村月淡云低。\n为爱寒香晚吹。\n瘦马立多时。\n是谁家、茅舍竹篱。\n三三两两芳蕤。\n未放琼铺雪堆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17192, '如梦令', '杨韶父', '凉月薄阴犹。\n红豆一枝秋思。\n门外几重山，山外行人千里。\n归未。\n归未。\n又是菊花天气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17193, '长相思', '杨韶父', '溪水清。\n溪水浑。\n溪上人家数亩园。\n垂杨深闭门。\n青罗裙。\n白罗裙。\n采尽青蘩到白苹。\n江南三月春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17194, '玉漏迟', '史深', '绿树深庭院。\n侵帘暝草，沿砌幽藓。\n问讯馀芳，糁迳碎红千点。\n暗有芹香坠几，认杏栋、营巢新燕。\n晴思软。\n春光几许，费人裁翦。\n梅阴地湿无尘，但密袖薰虬，静看诗卷。\n半掬羁心，似翠蕉难展。\n花事因循过了，渐愁人、薰风团扇。\n屏昼掩。\n屏上数峰青远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17195, '木兰花慢', '史深', '画楼帘半卷，倩谁觅、凤箫音。\n记待月梅边，笼香酒後，私语屏阴。\n忽忽佩珠暗解，断归鸿、消息两沉沉。\n前度刘郎易老，旧时飞燕难寻。\n罗襟。\n薄有泪痕侵。\n钗股暗黄金。\n向宝奁密看，绫笺小字，长是惊心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17196, '花心动', '史深', '肌雪浮香，见梅花清姿，漫劳凝伫。\n淡粉最娇，羞把春□，长记寿阳眉妩。\n绿苔深迳寻幽地，谁相伴、凌波微步。\n翠鸳冷，芳尘路杳，旧游何处。\n不信重城间阻。\n终没个因由，寄声传语。\n宝炬凝珠，彩笔呵冰，密写断肠新句。\n月寒烟瞑孤山下，羞吟□、断桥边去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17197, '齐天乐', '丁默', '两株烟柳荒城外，依依暮帆曾驻。\n小扇障尘，轻舆贴岸，谁料重行吟处。\n流光暗度。\n怅兰溆春移，苇汀秋聚。\n可奈清愁，快呼艇子载将去。\n中年怀抱易感，甚风花水叶，犹似孤旅。\n伴鹤幽期，随莺乐事，还是情乖意负。\n衣尘帽土。\n但杜镜堪羞，贺囊偏□。\n待报山灵，莫教云壑妒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17198, '华胥引', '丁默', '论交眉语，惜别心啼，费情不少。\n蕙渺溱期，苹深汜约轻误了。\n几度金铸相思，又燕归鸿杳。\n谁料如今，被莺闲占春草。\n频把愁勾，惜鸦云、娇红犹绕。\n浑拚如梦，争奈枕酲屏晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17199, '齐天乐', '丁默', '倦云休雨风还作，交相醒花苏柳。\n字满吟灰，痕添坐席，赢得新愁痴守。\n归期未有。\n负小院移兰，故园尝韭。\n谩道春来，沉腰惟觉似秋瘦。\n烧灯时候是也，楚津留野艇，曾趁芳友。\n问月赊晴，凭春买夜，明月添香解酒。\n□知别久。\n怅帝陌论心，客尘侵首。\n戏鼓声中，旧情犹在否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17200, '浣溪沙', '曾栋', '落日蒸红山欲烧。\n短筇行药过山腰。\n松声隐隐晚来潮。\n矮树依严无败叶，梅花当路少全梢。\n水村时有短长桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17201, '过秦楼', '曾栋', '曙色开晴，轻敷暖，日影才经檐角。\n倦来芳径，且倚阑干，独地新愁粘著。\n长日如年，可堪恨雨丝丝，梦云漠漠。\n见鸣禽递响，乳莺梳翅，痴愁方觉。\n凝望处，初绿呈新，陈柯拆旧，忘了一春归却。\n不伤花老，只怕花开，解使朱颜销铄。\n宝扇轻摇，乱抛花片教飞，迎风低掠。\n忍重携素手，骤觉一分瘦落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17202, '玉楼春', '江开', '风前帘幕沾飞絮。\n家在垂杨深处住。\n倚楼无语忆郎时，恰是去年今日去。\n帝城箫鼓青春暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17203, '菩萨蛮', '江开', '春时江上廉纤雨。\n张帆打鼓开船去。\n秋晚恰归来。\n看看船又开。\n嫁郎如未嫁。\n长是凄凉夜。\n情少利心多。\n郎如年少何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17204, '浣溪沙', '江开', '手拈花枝忆小苹。\n绿窗空锁旧时春。\n满楼飞絮一筝尘。\n素约未传双燕语，离愁还入卖花声。\n十分春事倩行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17205, '杏花天', '江开', '谢娘庭院通芳径。\n四无人、花梢转影。\n几番心事无凭准。\n等得青春过尽。\n秋千下、佳期又近。\n算毕竟、沉吟未稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17206, '鹧鸪天', '戴平之', '笑擘黄柑酒半醒。\n玉壶金斗夜生冰。\n开窗尽见千山雪，雪未消时月正明。\n兰烬短，麝煤轻。\n画楼钟鼓已三更。\n倚兰谁唱清真曲，人与梅花一样清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17207, '汉宫春', '王□□', '手拈黄花，对西风无语，双鬓萧萧。\n韶华暗中过眼，零落心交。\n登临把酒，更谁伴、破橘持螯。\n惟只有，湖边鸥鹭，飞来如受人招。\n往事不禁重省，料绾罗分钿，翠减香销。\n空向画桥古树，犹系轻桡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17208, '念奴娇', '程武', '蜀江城远，想连云危栈，接天穷处。\n惆怅烟尘回首地，双阙觚棱犹故。\n龙扈星联，羽林风肃，未放鸾去。\n不堪掩面，泪沾宸袖如雨。\n底事当日昭阳，吹羌鸣羯，却霓裳舞。\n三十六宫春满眼，曾把色嗔香妒。\n芳草埋情，飞花陨怨，翻被蛾眉误。\n画图惊见，黯然魂断今古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17209, '清平乐', '程武', '曳云摇玉。\n裙蹙秋绡幅。\n学得琵琶依约熟。\n贪按雁沙新曲。\n曲终满院春闲。\n清颦移上眉山。\n心事怕人猜破，折花背插云环。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17210, '小重山', '程武', '香减鲛绡添泪痕。\n彩云长是恨，等闲心。\n玉笙犹记夜深闻。\n湘水杳，寂寞隔巫云。\n翠被冷重熏。\n做成归梦了，却销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17211, '齐天乐', '王月山', '夜来疏雨鸣金井，一叶舞空红浅。\n莲渚收香，兰皋浮爽，凉思顿欺班扇。\n秋光苒苒。\n任老却芦花，西风不管。\n清兴难磨，几回有句到诗卷。\n长安故人别後，料征鸿声里，画阑凭遍。\n横竹吹商，疏砧点月，好梦又随云远。\n闲愁似线。\n甚系损柔肠，不堪裁翦。\n听著鸣蛩，一声声是怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17212, '踏莎行', '王万之', '柳外寒轻，水边亭小。\n昨朝燕子归来了。\n天涯无数旧愁根，东风种得成芳草。\n亭畔秋千，当时欢笑。\n香肌不满和衣抱。\n那堪别後更思量，春来瘦得知多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17213, '踏莎行', '钱宀孙', '征雁云深，乱蛩寒浅。\n惊心怕见年华晚。\n萧疏堤柳不禁霜，江梅瘦影清相伴。\n舞暗香茵，歌阑团扇。\n月明梦绕天涯远。\n断肠人在画楼中，东风不放珠帘卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17214, '踏莎行', '陈璧', '江阔天低，楼高思迥。\n春烟蘸淡如秋景。\n今年芳草去年愁，分明又报明年信。\n燕子还来，归期未定。\n可堪醉梦红尘境。\n世间万事尽消磨，水流不尽青山影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17215, '多丽', '赵时奚', '敛吴云，翠奁推上红晴。\n渺澄流、鳞光寒碎，远峰螺绀低凝。\n杏香引、画船影湿，柳阴趁、骄马蹄轻。\n桥限宽平，堤横南北，去来人入绣围行。\n渐际晚，梅妆游困，十里曳歌声。\n苍烟润，飞鸦妒春，一梦催醒。\n认名园、当时宴幸，缆痕犹在危亭。\n露花浓、静迎直砌，雾藓冷、淡护飞甍。\n几对东风，留连丽景，年□□老越山青。\n夜深月、照人依旧，何处最关情。\n欢娱地，星移世换，客恨还盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17216, '汉宫春', '赵时奚', '霜皎千林，正石桥人静，春满横塘。\n寒花自开自落，晓色昏黄。\n明沙暗草，对东风、深锁闲堂。\n金漏短，江南路远，梦回云冷潇湘。\n重到旧时花下，按玉笙歌彻，月正西廊。\n亭亭爱伊素影，粉薄新妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17217, '恋绣衾', '赵时奚', '迢迢江路日又曛。\n为春迟、长是怨春。\n小立马、千林下，寄寒香、归赠故人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17218, '恋绣衾', '赵时奚', '江南烟水几万重。\n记玉人、花底旧容。\n待欲寄、飞鸿信，望前山、夕照冷红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17219, '祝英台近', '向希尹', '晓帘栊，晴院宇，空鸭冷沉水。\n翠被欺寒，娇困未起。\n厌厌两点眉峰，一痕酒晕，正人在、温柔乡里。\n甚情味。\n羞对钗燕筝鸿，胭脂暗弹泪。\n欲写吴笺，无处问双鲤。\n倩他轻薄杨花，与愁结伴，直吹到，那人根底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17220, '浪淘沙', '向希尹', '结客去登楼。\n谁系兰舟。\n半稿清涨雨初收。\n把酒留春春不住，柳暗江头。\n老去怕闲愁。\n莫莫休休。\n晚来风恶下帘钩。\n试问落花随水去，还解西流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17221, '渡江云', '萧元之', '流苏垂翠，高低一色，红紫等泥沙。\n香山居士老，柳枝桃叶，飞梗属谁家。\n好音过耳，任啼鸟、怨入芳华。\n心情懒，笔床吟卷，醉墨戏翻鸦。\n堪嗟。\n雕弓快马，敕勒追踪，向夕阳坡下。\n休更忆，青丝络辔，红袖裁纱。\n司空见惯浑如梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17222, '菩萨蛮', '萧元之', '断红流水香难觅。\n行云一去无踪迹。\n杨柳漫遮阑。\n闲愁付远山。\n玉筝弹未了。\n倚柱人空老。\n青子摘来酸。\n酸心有几般。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17223, '水龙吟', '萧元之', '人生何必求名，身闲便是名高处。\n卧云衣袂，何因自染，修涂尘土。\n世路羊肠，人情狙赋，翻云覆雨。\n把从前旧梦，倚阑重省，休更错、添笺注。\n况是吾庐江上，也抵得、封侯千户。\n高眠闲听，邻舟渔唱，倚阑农语。\n休望当年，溪边俱载，隆中三顾。\n怕群鸥微觉，见人欲起，背人飞去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17224, '小重山', '陈成之', '恨入眉尖熨不开。\n日高犹未肯，傍妆台。\n玉郎嘶骑不归来。\n梁间燕，犹自及时回。\n粉泪污香腮。\n纤腰成瘦损，有人猜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17225, '如梦令', '王师锡', '竹上一楼凤翠。\n竹下一渠春水。\n中有隐人居，破屋数间而已。\n无事。\n无事。\n静夜月明千里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17226, '望江南・忆江南', '赵时行', '霜月湿，人睡矮篷秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17227, '菩萨蛮', '郭□□', '卖饧天气箫声软。\n午院水沉烟未断。\n睡起补残眉。\n红绵入镜迟。\n霎时开笑靥。\n花上看双蝶。\n新月上帘钩。\n相思不断头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17228, '浣溪沙', '王大简', '拂面凉生酒半醒。\n廉纤小雨晚初晴。\n过云无定月亏盈。\n庭户不关春悄悄，阑干倚遍夜深深。\n几回风竹误人听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17229, '更漏子', '王大简', '梦期疏，书约误。\n肠断夜窗风雨。\n灯晕冷，漏声遥。\n酒消愁未消。\n想天涯，芳草碧。\n人与芳春俱客。\n凭杜宇，向江城。\n好啼三两声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17230, '蓦山溪', '刘菊房', '醉魂离梦，捻合难成片。\n恶味怕黄昏，更西风，梧桐深院。\n蝉松翠妩，记那日相逢，情缱绻。\n语玲珑，人静凌波见。\n香云曾约，念阻题红怨。\n应是绿窗寒，也思郎、云衣谁换。\n郎今销黯，步楚竹江空，云缥缈，水弥茫，不抵相思半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17231, '谒金门', '杜龙沙', '阶露重。\n透寻花双凤。\n天色晴明风不动。\n薄衫金络缝。\n午枕高云斜纵。\n一觉风流春梦。\n起看翻翻帘影弄。\n夕阳归燕共。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17232, '踏莎行', '杜龙沙', '波暖芹汀，风香兰圃。\n清尘几点茸茸雨。\n画船丝竹载梁州，彩旗绳板欢游女。\n修禊初三，禁烟百五。\n年华恰到风流处。\n一生只当百回春，一回春到休轻负。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17233, '斗鸡回', '杜龙沙', '莺啼人起，花露真珠洒。\n白苎衫，青骢马。\n绣陌相将，斗鸡寒食下。\n回廊瞑色，应是待、归来也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17234, '雨淋铃', '杜龙沙', '窗影珑璁，画楼平晓，翳柳啼鸦。\n门巷渐有新烟，东风定、人扫桐花。\n峭寒斗减，看旅雁、争起蒹葭。\n溯断云，多少悲鸣，数行又下远汀沙。\n应是故园桃李谢。\n送清江、一曲阑干下。\n染翰为赋春羁，嗟双鬓、客舍成华。\n绣鞭绮陌，强携酒、来觅吴娃。\n听扇底、凄惋新声，醉里翻念家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17235, '诉衷情', '王苍', '补成团扇绣残工。\n并蒂瑞芙蓉。\n花心欲就针折，玉唾残茸。\n寻断绪，怨西风。\n寂寥中。\n两般时候，旧月新霜，晓角昏钟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17236, '阮郎归', '宋德广', '好风吹月过楼西。\n楼前人影稀。\n杜鹃啼断绿杨枝。\n行人知不知。\n红叶字，断肠诗。\n从今懒再题。\n後园零落淡胭脂。\n似君初去时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17237, '谒金门', '李好古2', '花过雨。\n又是一番红素。\n燕子归来愁不语。\n旧巢无觅处。\n谁在玉关劳苦。\n谁在玉楼歌舞。\n若使胡尘吹得去。\n东风侯万户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17238, '解连环', '黄廷', '乍寒帘幕。\n愁灯花正结，又还轻落。\n弄瘦影、瓶里梅梢，为谁缀陇头，向来新萼。\n万古千今，算惟有、别情难托。\n把潘郎鬓绿，尽付雁声，几度寥寞。\n扁舟暮江旧泊。\n记携觞就折，烟翠犹弱。\n漫过却、歌夕吟朝，问天道何时，素纤重握。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17239, '忆旧游', '黄廷', '乍梅黄雨过，遍倚层楼，时舞垂阳。\n暗绿知谁换，似烟浓雾薄，望眼偏妨。\n昔人画无数，相引入横塘。\n纵细切香蒲，重开绛蕊，懒向清觞。\n凄凉。\n旧游地，谩赋减兰成，才退周郎。\n总把芳辰误，念纱窗深静，冰簟流光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17240, '宴清都', '黄廷', '坠叶窥檐语。\n风帘薄，递来幽恨无数。\n牙签倦展，银缸细剔，悄然归旅。\n声传漏阁偏长，更奈向、潇潇乱雨。\n想近日，舞袖翻云，吟笺度雪谁愿。\n当时翠缕吹花，东城绣陌，双燕何许。\n香罗唾碧，晴纱印粉，甚缘重睹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17241, '兰陵王', '黄廷', '絮花弱。\n吹满斜阳院落。\n秋千外，无数小舟，绿水溶溶带城郭。\n流光漫暗觉。\n辜却。\n莺呼燕诺。\n欢游地，都在梦中，双蝶翩翩度帘幕。\n凭谁问康乐。\n又粉过新梢，红退残萼。\n阑干休倚东风恶。\n怜瑟韵空在，鉴容偷改，青青洲渚遍杜若。\n故交半廖寞。\n漂泊。\n镇如昨。\n念玉指频弹，珠泪还阁。\n孤灯隐隐巫云薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17242, '琐窗寒', '黄廷', '驻马林塘，还寻旧迹，雨收秋晚。\n残蕉映牖，强把碧心偷展。\n记相逢、画堂宴开，乱花影入帘初卷。\n正小池涨绿，丝纶曾试，事随鸿远。\n凄断。\n情何限。\n料素扇尘深，怨娥碧浅。\n清宫丽羽，漫有苔笺题满。\n问低墙、双柳尚存，几时艳烛亲共剪。\n但凝眸，数点遥峰，春色青如染。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17243, '齐天乐', '黄廷', '十年汉上东风梦，依然淡烟莺晓。\n系马桥空，维舟岸易，谁识当时苏小。\n筹花斗草。\n任波浴斜阳，絮迷芳岛。\n笑底歌边，黛娥娇聚怕归早。\n京尘衣袂易染，旧游随雾散，新恨难表。\n燕子朱扉，梨英翠箔，留得春光多少。\n晴丝漫绕。\n料带角香销，扇阴诗杳。\n细倚秋千，片云天共渺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17244, '塞翁吟', '陈坦之', '远碧秋痕瘦，楚玉恨赋凄凉。\n荷雨碎，泣残妆。\n系愁在垂阳。\n秋衣拂叠仙栀露，裁云刀尺犹香。\n诗锦字，献明。\n肯容易相忘。\n思量。\n空掩抑，分宵缓枕，终不敌、凉谯漏长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17245, '沁园春', '陈坦之', '睡起闻莺，卷帘微雨，黄昏递愁。\n正青翰音断，离怀几摺，碧云暮合，千里双眸。\n思发花前，人归雁後，误记归帆天际舟。\n浑无据，但馀香绕梦，频到西楼。\n风流。\n翻是花。\n谩长遣眉山翠不流。\n想哀筝绕指，鸿移凤咽，残灯背泣，玉沁春柔。\n夜月精神，朝阳微艳，何处瑶台轻驻留。\n愁无际，被东风吹去，绿黯芳洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17246, '柳梢青', '陈坦之', '绿弱红。\n暖云沁雨，乍有还无。\n破晓幽禽，平渠流水，春响庭除。\n梅酸初著花跗。\n似滴滴、新愁未舒。\n几信花风，一痕青烧，万里秦吴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17247, '谒金门', '陈坦之', '归未卜。\n频倒金纤玉。\n明月绡窗停剪烛。\n搦愁题蠹绿。\n秋水娟娟鱼目。\n腰素几分销缩。\n接得云笺无意读。\n雕鞍何处宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17248, '夜飞鹊・夜飞鹊慢', '张艾', '霓裳按歌地，凉影参差。\n还是佩解江湄。\n沧波正洗袜尘恨，流霞空沁铢衣。\n盈盈半输笑，向朱阑凝伫，欲诉心期。\n碧筒唤酒，恐娇娥、来下瑶池。\n未许西风吹断，环步障千重，镇护金猊。\n落晚文禽点镜，分香窃翠，却念幽羁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17249, '解语花', '张艾', '轻雷殷殷，小枕惊回，帘影摇庭户。\n嫩凉遥度。\n江云堕、结作西窗暗雨。\n闲阶静伫。\n叹疏袂、愁宽一缕。\n凭画栏，润叶鸣条，总是安秋处。\n因唤扁舟晚渡。\n渐闻歌招得，采菱俦侣。\n临平归路。\n花无数、应识汀洲倦旅。\n飞红怨暮。\n长趁得、断鸿南浦。\n闲枕衾，谁更无聊，应最怜纨素。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17250, '绕佛阁', '张艾', '渚云弄湿，烟缕际晚，江国遥碧。\n鸿过无迹。\n怕闻野寺孤钟动凄恻。\n小桥路窄。\n疏袖暗拂衰草，愁听蛩语还寂。\n可堪过了，龟纱负瑶席。\n荏苒露华白。\n一夜秋窗惊晓色。\n柳影孤危，残蝉空抱叶。\n想摇落关情，归梦频折。\n物华消歇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17251, '真珠帘', '徐□', '落红几阵清明雨。\n忆花期、半被晴悭寒阻。\n新柳著春浓，早翠池波妒。\n粉雨香云消息远，漫旧日、秋千庭宇。\n凝伫。\n正春醒帘外，一声莺语。\n尘锁宝筝弦柱。\n自眉峰惹恨。\n六么慵舞。\n深院不成妆，有泪弹谁与。\n记得踏青归去後，细共说、花阴深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17252, '桂枝香', '施翠岩', '西风满目。\n渐院落悄清，愁近银烛。\n多少虫书堕翠，又随波。\n娥半露扶疏影，向虚檐、似知幽独。\n浦鸿声断，枝乌漏永，芳梦难续。\n记旧日、离亭细嘱。\n早归趁香边，频泛。\n谁遣而今，对景黛娥双蹙。\n玉鞭但共秋光远，漫空怜、如许金粟。\n露零襟冷，萧萧更兼，数竿修竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17253, '沁园春', '施翠岩', '披紫菟裘，上白鹭亭，看吹洞箫。\n望长江庚鲸过，江横素练，回仙鹤度，月在青霄。\n依约淮山，清冷风露，如到瀛洲听海涛。\n浮图近，更玉铃金铎，初奏琅。\n人间梦境廖廖。\n问故国繁华能几朝。\n有千年枯井，龙沉凤怨，数邱黄壤，兔走猿嗥。\n莫问荣华，不如归去。\n短棹孤篷乘夜潮。\n翠岩下，耕白云二顷，胜种仙苗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17254, '念奴娇', '续雪谷', '砌红慵扫，问东风、应念西园廖落。\n帘卷垂阳莺啭巧，才见还因飞却。\n拈指光阴，关心节序，总在秋千索。\n翻翻双蝶，傍人争趁行乐。\n曾记步月归来，秦筝弹遍，共倚阑干角。\n别後池亭谁斗草，多少芳游担阁。\n世事升沈，人生聚散，俯仰空如昨。\n馀香犹在，绣帏清晓寒薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17255, '南歌子', '续雪谷', '眼媚双波溜，腰柔一搦纤。\n问伊何事放珠帘。\n笑道篆香销尽、要重添。\n数日宽金钏，梳云拂翠奁。\n梅妆依旧落虚檐。\n题起一春心事、两眉尖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17256, '长相思', '续雪谷', '心悠悠。\n恨悠悠。\n谁剪青山两点愁。\n笙寒燕子楼。\n晓星稀。\n暮云飞。\n织就回文不下楼。\n花飞人未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17257, '水调歌头', '荣樵仲', '既难求富贵，何处没溪山。\n不成天也，不容我去乐清闲。\n短褐宽裁疏葛，柱杖横拖瘦玉，著个竹皮冠。\n弄影碧霞里，长啸翠微间。\n醉时歌，狂时舞，困时眠。\nけ然自得，了无一点俗相干。\n拟把清风明月，剪作长篇短阕，留与世人看。\n待倩月边女，归去借青鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17258, '贺新凉・贺新郎', '陆象泽', '笛唤春风起。\n向湖边、腊前折柳，问君何意。\n孤负梅花立晴昼，一舸凄凉雪底。\n但小阁、琴棋而已。\n佳客清明留不住，为匡庐、只在家窗里。\n湓浦去，两程耳。\n草堂旧日谈经地。\n更从容、南山北水，庾楼重倚。\n万卷心胸几千古，仰首紫气。\n正江上、风寒如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17259, '桂枝香', '鞠华翁', '丁丁起处。\n在纵牧九京，经烧残树。\n时见鸟鸢饥噪，鸺妖呼。\n数间老屋团荒堵。\n算何人、瓣香来注。\n淡烟斜照，闲花野棠，杳杳年度。\n世事几、番云覆雨，独此道嫌人，抛弃尘土。\n眼里长青，谁也解如山否。\n三三五五骑牛伴，望前村、吹笛归去。\n柳青梨白，春浓月淡，蹋歌椎鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17260, '绮寮怨', '鞠华翁', '又见花阴如水，两心犹未平。\n正坐久、主客成三，空无语、影落秋枰。\n千年人间事业，垂成处、一著容易倾。\n便解围、小住何妨，机锋在，瞬息天又明。\n甚似汉吴对营。\n纷纷不了，孤光照彻连城。\n又似残星，向零落，有馀情。\n娥笑人迟暮，念才力、底须争。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17261, '贺新郎', '曾颜', '富贵人间有。\n就如今，秤量阴德，还公最厚。\n一郡鹘全似旧，春满霜畴稻亩。\n近帐外、干将夜吼。\n直指禾川弄霆雷，从山阴、鹿健那能走。\n都算计，怎担负。\n单车曲曲穿岩窦。\n向迷途、分明一呼，散渠回首。\n夹路香花迎拜了，见说家家举酒。\n道公是、再生父母。\n活一口还添一岁，这一回、活几千千口。\n只此事，是公寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17262, '好事近', '曾颜', '昨夜探寒梅，先报一阳消息。\n天遣花神妆点，衬贤侯清白。\n试将玉蕊比修龄，算枝头千百。\n更有不凡风味，付调羹仙客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17263, '谒金门', '朱子厚', '风动竹。\n清遍一窗梅溽。\n闻道小乔乘凤玉。\n仙裳飘雾。\n来嫁吾门公瑾叔。\n天上人间愿足。\n浓缭水沉燃宝烛。\n鬓长相对绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17264, '望江南・忆江南', '刘辰翁', '朝朝暮，云雨定何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17265, '望江南・忆江南', '刘辰翁', '春悄悄，春雨不须晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17266, '望江南・忆江南', '刘辰翁', '梧桐子，看到月西楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17267, '望江南・忆江南', '刘辰翁', '梧桐子，人在御街游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17268, '望江南・忆江南', '刘辰翁', '长欲语，欲语又蹉跎。\n已是厌听夷甫颂，不堪重省越人歌。\n孤负水云多。\n羞拂拂，懊恼自摩挲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17269, '望江南・忆江南', '刘辰翁', '前之夕，织女渡河边。\n天上一朝元五日，人间小住亦千年。\n相合降神仙。\n当富贵，掩鼻正高眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17270, '望江南・忆江南', '刘辰翁', '添一岁，减一岁愁眉。\n若待一生昏嫁了，更须采药十年迟。\n昏嫁已随时。\n东家者，俎豆伴儿嬉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17271, '望江南・忆江南', '刘辰翁', '盘之所，春蝶舞晴暄。\n溪傍野梅根种玉，墙围修竹笋生鞭。\n深院待回仙。\n嘉熙好，四十二年前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17272, '望江南・忆江南', '刘辰翁', '齐眉举，彩侍紫霞卮。\n天上九朝凫冉冉，尊前一笑玉差差。\n人唱自家词。\n篱下菊，醉把一枝枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17273, '望江南・忆江南', '刘辰翁', '七日後，重会是星前。\n二月之间浑似此，馀年何止万三千。\n日拟醉华筵。\n歌白雪，除是雪儿传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17274, '南乡子', '刘辰翁', '宽处略从容。\n华水华山自不同。\n旧日诸贤携手恨，匆匆。\n只说明年甚处重。\n几岁避辽东。\n茅竹秋风一并空。\n欲望辽东何处是，。\n也似秦楼一梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17275, '南乡子', '刘辰翁', '香雪碎团团。\n便合枝头带露餐。\n笑倒那人和玉屑，金丹。\n不在仙人掌上盘。\n千树碧阑干。\n山崦朱门梦里残。\n花下主人都在此，谁看。\n天上人间一样寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17276, '南乡子', '刘辰翁', '去似赏花移。ピ\n处处开尊亦不辞。ピ\n梨栗又空醅又尽，方知。ピ\n旧日骊驹劝客归。ピ\n归路月相随。ピ\n儿子门生个个迟。ピ\n坐久不知无可待，堪疑。ピ\n向道儿痴直是痴。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17277, '浪淘沙', '刘辰翁', '无叶著秋声。\n凉鬓堪惊。\n满城明月半窗横。\n惟有老人心似醉，未晓偏醒。\n起舞故无成。\n此恨难平。\n正襟危坐二三更。\n除却故人曹孟德，更与谁争。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17278, '浪淘沙', '刘辰翁', '卷海海翻杯。\n倾动蓬莱。\n似嫌到处马头埃。\n雨洗御街流到我，吹向潮回。\n寒似雪天梅。\n安石榴开。\n绣衾重暖笑炉灰。\n料想东风还忆我，昨夜归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17279, '浪淘沙', '刘辰翁', '无谓两眉攒。\n风雨春寒。\n池塘小小水漫漫。\n只为柳花无一点，忘了临安。\n何许牡丹残。\n客倚屏看。\n小楼面面是春山。\n日暮不知春去路，一带阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17280, '如梦令', '刘辰翁', '比似寻芳娇困。\n不是弓弯拍衮。\n无物倚春慵，三寸袜痕新紧。\n羞褪。\n羞褪。\n忽忽心情未稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17281, '如梦令', '刘辰翁', '寂历柳风斜倚。\n错莫梦云难记。\n花影为谁重，一握鲛人丝泪。\n何事。\n何事。\n历历脸潮羞起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17282, '如梦令', '刘辰翁', '睡眼青阴欲午。\n当户小风轻暑。\n倦近碧阑干，斜影却扶人去。\n无绪。\n无绪。\n落落一襟轻举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17283, '如梦令', '刘辰翁', '落叶西风满地。\n独宿琼楼丹桂。\n孤影抱蟾寒，寄与月明千里。\n休寄。\n休寄。\n粟粟蕊珠心碎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17284, '江城子', '刘辰翁', '涌金门外上船场。\n湖山堂。\n众贤堂。\n到几凄凉，城角夜吹霜。\n谁识两峰相对语，天惨惨，水茫茫。\n月移疏影傍人墙。\n怕昏黄。\n又昏黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17285, '江城子', '刘辰翁', '一年春事几何空。\n杏花红。\n海棠红。\n看取枝头，无语怨天公。\n幸自一晴晴太暖，三日雨，五更风。\n山中长自忆城中。\n到城中。\n望水东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17286, '江城子', '刘辰翁', '书题拂拂洞庭香。\n孕云黄。\n粲珠光。\n唤谪仙人，除是贺知章。\n未老得闲闲到老，无一事，和诗忙。\n是中曾著老人双。\n送千觞。\n乐谁妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17287, '江城子', '刘辰翁', '红醉袖阑干。\n夜将阑。\n去难拚。\n烧蜜调蜂，重照锦团栾。\n春到洞房深处暖，方知道，月宫寒。\n枝枝红泪不曾乾。\n背人弹。\n语羞檀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17288, '点绛唇', '刘辰翁', '小阁横窗，倩谁画得梅梢远。\n那回半面。\n曾向屏间见。\n风雪空山，怀抱无荀倩。\n春堪恋。\n自羞片片。\n更逐东风转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17289, '点绛唇', '刘辰翁', '一雪蹉跎，蹇驴不载吟鞭去。\n夜听春雨。\n踏雪差无苦。\n待得花晴，总是游人处。\n梅应许。\n小桥延伫。\n蜂蝶先成路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17290, '点绛唇', '刘辰翁', '醉里瞢腾，昨宵不记归时候。\n自疑中酒。\n耿耿还依旧。\n恨不能言，只是天相负。\n天知否。\n卷中人瘦。\n一似章台柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17291, '点绛唇', '刘辰翁', '燕子池塘，乱红过尽秋千晚。\n絮飞欲倦。\n正是帘初卷。\n睡起无情，犹道天涯远。\n羞匀面。\n乍惊红浅。\n梦自无人见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17292, '点绛唇', '刘辰翁', '指春寒，陇禽一片飞来雪。\n无言可说。\n暗啄相思结。\n双影年深，也作关山别。\n翻成拙。\n落花时节。\n倩子规声绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17293, '点绛唇', '刘辰翁', '虹玉横箫，纤纤指按新声作。\n参差重约。\n昨夜梁伊错。\n几许闲愁，品字都忘却。\n沉吟觉。\n一声哀角。\n满院残花落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17294, '浣溪沙', '刘辰翁', '高卧何须说打乖。\n小篱过雨翠长街。\n缃桃定有踏青鞋。\n晴日又思花处所，东风绝似柳情怀。\n人间安得酒如淮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17295, '浣溪沙', '刘辰翁', '身是去年人尚健。\n心知十日事如常。\n眼前杯酒是重阳。\n破帽簪萸携素手，长歌藉草慰寒香。\n儿童怪我老来狂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17296, '浣溪沙', '刘辰翁', '春日春风掠鬓须。\n乱山相对拥寒炉。\n彩鞭金胜一时无。\n自缕青丝成细柳，更堆残雪当凝酥。\n儿童且莫唱皇都。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17297, '浣溪沙', '刘辰翁', '身是高人欲寝冰。\n引年可待进苓。\n无忧无患也身轻。\n雪里放囚天亦喜，平安骑鹤到家庭。\n今年春早为长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17298, '浣溪沙', '刘辰翁', '十日千机可复谐。\n郭郎感运岂仙才。\n人间自是少行媒。\n直上扶摇须九万，满前星斗共昭回。\n又传贾客向曾来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17299, '浣溪沙', '刘辰翁', '暮暮相望夕甫谐。\n针楼巧巧似身材。\n下头无数老人媒。\n昨夜竹林那得见，朝来乾鹊是空回。\n人间五日後能来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17300, '摊破浣溪沙・山花子', '刘辰翁', '醉里微寒著面醒。\n天风不展帽倾。\n行过溪深松雪下，夜三更。\n白白野田铺似月，沙路踏如冰。\n不见剡溪三百曲，一舟横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17301, '摊破浣溪沙・山花子', '刘辰翁', '澹澹胭脂浅著梅。\n温柔不上避风台。\n若比杏桃真未识，夺银胎。\n汗面试来慵传粉，酒香浓後暗潮腮。\n娇嫩不应醒似醉，倩谁猜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17302, '霜天晓角', '刘辰翁', '柳梢欲雪。\n十里烟明灭。\n曲曲阑干转影，教人忆、夜来月。\n家人相对说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17303, '霜天晓角', '刘辰翁', '乌云汗漫。\n浊浪翻河汉。\n过尽千重魔障，堂堂地、一轮满。\n秋光还又半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17304, '霜天晓角', '刘辰翁', '骑台千骑。\n有菊知何世。\n想见登高无处，淮以北、是平地。\n老来无复味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17305, '霜天晓角', '刘辰翁', '经年寂寞。\n已负花前约。\n忽向红梅侧畔，开点雪、有人觉。\n不开何似莫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17306, '霜天晓角', '刘辰翁', '然如竹。\n自是天仙福。\n小小画堂锦样，听人唱、鹤飞曲。\n橙橘黄又绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17307, '霜天晓角', '刘辰翁', '朝来微雪。\n又近长生节。\n造就一枝清绝，梅与雪、怎分别。\n两年心似月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17308, '霜天晓角', '刘辰翁', '明年七十。\n歌彩桥仙夕。\n见说严君平道，年年是、月初一。\n同时同里密。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17309, '霜天晓角', '刘辰翁', '良宵七七。\n又近中元日。\n桥上老人有约，後五日、重来觅。\n婵娟银海出。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17310, '霜天晓角', '刘辰翁', '归来把菊。\n春瓮今朝熟。\n苦苦留君不得，携孺子、到汾曲。\n庐山真面目。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17311, '霜天晓角', '刘辰翁', '问春来未。\n也似辛壬癸。\n如此男儿五十，又过却、孔融二。\n画堂孙子子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17312, '霜天晓角', '刘辰翁', '□□□□。\n□□□□□。\n□□□□□□，□□□、□□□。\n治中心似佛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17313, '卜算子', '刘辰翁', '不是重看灯，重见河边女。\n长是蛾儿作队行，路转风吹去。\n十载废元宵，满耳番腔鼓。\n欲识尊前太守谁，起向尊前舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17314, '卜算子', '刘辰翁', '早已是三年，父老依依借。\n顾与天公借几年，保我鸡豚社。\n□□□□□，□□□□□。\n□□□□□□□，□□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17315, '菩萨蛮', '刘辰翁', '芭蕉叶上三更雨。\n人生只合随他去。\n便不到天涯。\n天涯也是家。\n屏山三五叠。\n处处飞胡蝶。\n正是菊堪看。\n东篱独自寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17316, '菩萨蛮', '刘辰翁', '黄鸡喔喔催人起。\n困不成眠窗似水。\n清露不曾寒。\n朝来起自难。\n家人当睡美。\n又忆归程几。\n不管湿阑干。\n芙蓉花自看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17317, '菩萨蛮', '刘辰翁', '画梁语透帘栊晓。\n坼桐风送杨花老。\n细雨绿阴寒。\n罗襟只似单。\n青门三里道。\n个个游芳草。\n比似嫁来看。\n踏青难更难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17318, '菩萨蛮', '刘辰翁', '江波何似西湖曲。\n村烟相对峰南北。\n何处不青青。\n青青是汉茔。\n长亭芳草路。\n寒食谁家墓。\n旧日厌残红。\n人行九里松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17319, '菩萨蛮', '刘辰翁', '殷勤欲送春归去。\n白首题将断肠句。\n春去自依依。\n欲归无处归。\n天涯同是寓。\n握手留春住。\n小住碧桃枝。\n桃根不属谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17320, '菩萨蛮', '刘辰翁', '八仙名姓当时少。\n污尊牛饮同倾倒。\n惟有我公荣。\n旁人笑独醒。\n多年村落走。\n泥饮无升斗。\n入了玉门关。\n人生一醉难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17321, '好事近', '刘辰翁', '□後百年闲，元度自伤来暮。\n打破虚空无碍，共乘龙飞去。\n更参末後句如何，此事未能付。\n前遇小桥风雪，是君诗成处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17322, '谒金门', '刘辰翁', '娇点点。\n困倚春光欲软。\n滴尽守宫难可染。\n浓欺红烛艳。\n寂寂露珠啼脸。\n翠袖不禁风。\n芳径相逢惊笑靥。\n日长初睡转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17323, '谒金门', '刘辰翁', '花露湿。\n红泪成珠粒。\n比似昭阳恩未得。\n睡来添醉色。\n一笑娇波滴滴。\n再顾羞潮拂拂。\n恨血千年明的。\n千年人共忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17324, '谒金门', '刘辰翁', '游赏竞。\n看取落红阵阵。\n花睡不成娇似病。\n春寒空受尽。\n旧日不知繁盛。\n欲饮如今无兴。\n恨满东风无绿鬓。\n东风还自恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17325, '长相思', '刘辰翁', '上元晴。\n上元晴。\n待得晴时坐触屏。\n山禽三两声。\n欲归城。\n未归城。\n见说城中处处灯。\n明年处处行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17326, '忆秦娥', '刘辰翁', '烧灯节。\n朝京道上风和雪。\n风和雪。\n江山如旧，朝京人绝。\n百年短短兴亡别。\n与君犹对当时月。\n当时月。\n照人烛泪，照人梅发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17327, '忆秦娥', '刘辰翁', '惊雷节。\n梅花冉冉销成雪。\n销成雪。\n一年一度，为君肠绝。\n古人长恨中年别。\n馀年又过新正月。\n新正月。\n不堪临镜，不堪垂发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17328, '忆秦娥', '刘辰翁', '梅花节。\n白头卧起餐毡雪。\n餐毡雪。\n上林雁断，上林书绝。\n伤心最是河梁别。\n无人共拜天边月。\n天边月。\n一尊对影，一编残发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17329, '忆秦娥', '刘辰翁', '收灯节。\n霖铃又似龟山雪。\n龟山雪。\n今宵清绝，今宵愁绝。\n老人似少终然别。\n痴痴更望春三月。\n春三月。\n花如人面，自羞余发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17330, '忆秦娥', '刘辰翁', '春如昨。\n晓风吹透胭脂阁。\n胭脂阁。\n满园茅草，冷烟城郭。\n青衫泪尽楼头角。\n佳人梦断花间约。\n花间约。\n黄昏细雨，一枝零落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17331, '西江月', '刘辰翁', '天上低昂似旧，人间儿女成狂。\n夜来处处试新妆。\n却是人间天上。\n不觉新凉似水，相思两鬓如霜。\n梦从海底跨枯桑。\n阅尽银河风浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17332, '西江月', '刘辰翁', '曾与回翁把手，自宜老子如龙。\n怀胎不敢问春冬。\n等待鞭鸾笞凤。\n昨夜又迟黄石，今朝重叩鸿。\n碧桃花下醉相逢。\n说尽鹏游蝶梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17333, '西江月', '刘辰翁', '玉帐传心如镜，青龙绕指成轮。\n尘中多少白头人。\n乾里寻壬难认。\n世事说来都了，鬼神见也须。\n迷槎问我是何津。\n向道先生昼困。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17334, '清平乐', '刘辰翁', '深红半面。\n一似墙头见。\n草树池塘青一片。\n独倚阑干几遍。\n更谁绛袖朱唇。\n火云相对英英。\n笑杀牡丹正午，离披不任看承。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17335, '清平乐', '刘辰翁', '君词为寿。\n绝妙孙辛妇。\n但恨杯无露添酒。\n空等待梅花久。\n喜君白首还玄。\n人间合信天缘。\n如此相从至老，我亦何倦馀年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17336, '归国遥', '刘辰翁', '初雨歇。\n照水绿腰裙带熟。\n杨花不做人情雪。\n风流欲过前村蝶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17337, '昭君怨', '刘辰翁', '月出东山之上。\n长忆御街人唱。\n恨我不能琴。\n有琴心。\n徙倚秋波平莹。\n渐久玉肌清冷。\n待更下阑干。\n起来看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17338, '浣溪沙', '刘辰翁', '远远游蜂不记家。\n数行新柳自啼鸦。\n寻思旧事即天涯。\n睡起有情和画卷，燕归无语傍人斜。\n晚风吹落小瓶花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17339, '浣溪沙', '刘辰翁', '点点疏林欲雪天。\n竹篱斜闭自清妍。\n为伊憔悴得人怜。\n欲与那人携素手，粉香和泪落君前。\n相逢恨恨总无言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17340, '减字木兰花', '刘辰翁', '何须翦纸。\n依旧一团圆照水。\n莫倚空寒。\n柳下池边也只般。\n君何忽忽。\n宇宙人生都是客。\n月在云端。\n人自愁人不解看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17341, '减字木兰花', '刘辰翁', '旧游山路。\n落在秋阴最深处。\n风雨重阳。\n无蝶无花更断肠。\n天知老矣。\n莫累门生与儿子。\n不用登高。\n高处风吹帽不牢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17342, '减字木兰花', '刘辰翁', '东风似客。\n醉里落花南又北。\n客似东风。\n携手斜阳一笑中。\n佳人怨我。\n不寄江南春一朵。\n我怨佳人。\n憔悴江南不似春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17343, '减字木兰花', '刘辰翁', '腊销三五。\n月向雪山云外吐。\n烟水黄昏。\n梅柳依稀笛断魂。\n今宵豫赏。\n便作香尘随步想。\n莫待元宵。\n灯火零星雨寂寥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17344, '减字木兰花', '刘辰翁', '无灯可看。\n雨水从教正月半。\n探茧推盘。\n探得千秋字字看。\n铜驼故老。\n说著宣和似天宝。\n五百年前。\n曾向杭州看上元。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17345, '减字木兰花', '刘辰翁', '送春待晓。\n春是五更先去了。\n我醉方知。\n春正怜伊怕别伊。\n留君不可。\n归到海边方忆我。\n做尽花归。\n欲赠君时少一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17346, '减字木兰花', '刘辰翁', '相州锦好。\n待到相州人已老。\n颍水归田。\n白鹭惊猜已十年。\n太师尚父。\n晚遇明时方用武。\n大笑相逢。\n把酒家乡是客中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17347, '减字木兰花', '刘辰翁', '不能管得。\n欲雨能教天地黑。\n待得开晴。\n不用吾言也自行。\n一杯亦醉。\n万事无能吾欲睡。\n旧亦能诗。\n说旧时诗问是谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17348, '减字木兰花', '刘辰翁', '清欢昨日。\n十事不如人六七。\n试数从前。\n素素相从得几年。\n子兮子兮。\n再拣一枝何处起。\n翠斧峰驼。\n客好其如良夜何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17349, '减字木兰花', '刘辰翁', '脾神喜乐。\n寿酒一杯胜服药。\n过却明朝。\n顶上新霜也合销。\n小春三日。\n便觉春暄梅影出。\n醉把梅看。\n比似茱萸更耐寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17350, '山花子', '刘辰翁', '东风解手即天涯。\n曲曲青山不可遮。\n如此苍茫君莫怪，是归家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17351, '山花子', '刘辰翁', '此处情怀欲问天。\n相期相就复何年。\n行过章江三十里，泪依然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17352, '柳梢青', '刘辰翁', '铁马蒙毡，银花洒泪，春人愁城。\n笛里番腔，街头戏鼓，不是歌声。\n那堪独坐青灯。\n想故国、高台月明。\n辇下风光，山中岁月，海上心情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17353, '南歌子', '刘辰翁', '搔困麻仙爪，含暄忍客衣。\n夜长窗月露成帏。\n不说明朝风雨、自当归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17354, '南歌子', '刘辰翁', '熟双投美，香飘一缕丝。\n霜前雁到蟹螯持。\n自试小窗醉墨、作新诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17355, '朝中措', '刘辰翁', '炼花为露玉为瓶。\n佳客为频倾。\n耐得风霜满鬓，此身合是金茎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17356, '太常引', '刘辰翁', '便晴也是不曾晴。\n不怕金吾禁行。\n风雨动乡情。\n梦灯火、扬州化城。\n少年跌宕，谁家娇小，绕带到天明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17357, '太常引', '刘辰翁', '此公去暑似新秋。\n吏毒一句句。\n行县胜监州。\n觉甘雨、随车应求。\n鹭清为酒，螺清为寿，起舞祝君侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17358, '玉楼春', '刘辰翁', '霜风不动晴明好。\n探梅有约城东道。\n桥边失却老仙期，城门落日人归早。\n野田一望迷芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17359, '玉楼春', '刘辰翁', '龙山歌舞无人道。\n只说先生狂落帽。\n秋风亦是可怜人，要令天意知人老。\n菊花不为重阳早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17360, '乌夜啼', '刘辰翁', '犹疑薰透帘栊。\n是东风。\n不分榴花更胜、一春红。\n新雨过，绿连空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17361, '乌夜啼', '刘辰翁', '素娥醉语曾留。\n又中秋。\n待得重圆谁妒、两悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17362, '乌夜啼', '刘辰翁', '何年似永和年。\n记湖船。\n如此晴天无处、望新烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17363, '行香子', '刘辰翁', '雪履无痕。\n溪影传神。\n著坡诗、请自清温。\n朝朝不去，夕夕空勤。\n似梦中云，云外雪，雪中春。\n四野昏昏。\n匹马巡巡。\n拣一枝、寄与芳尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17364, '行香子', '刘辰翁', '玉立风尘。\n光动黄银。\n便谈文、也到夜分。\n无人烛下，壁上传神。\n记老婆心，寒士语，道人身。\n极意形容，下语难亲。\n更万分、无一分真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17365, '行香子', '刘辰翁', '海水成尘。\n河水无银。\n恨幽明、我与公分。\n青山独往，回首伤神。\n叹魏阙心，石魄，汨罗身。\n除却相思，四海无亲。\n识风流、还贺季真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17366, '行香子', '刘辰翁', '月露吾痕。\n雪得吾神。\n更荒寒、不傍人温。\n山人去後，车马来勤。\n但梦朝云，愁暮雨，怨阳春。\n说著东昏。\n记著南巡。\n泪盈盈、檀板金尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17367, '品令', '刘辰翁', '满庭芳草。\n更昨日、落红如扫。\n绿阴正似人怀抱。\n一声，春色何曾老。\n幸自不须人起早。\n寂寞如相恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17368, '鹊桥仙', '刘辰翁', '乘鸾著色，痴蝇误拂。\n不及羲之醉墨。\n偶然入手送东阳，便看取、薰时清适。\n清风去暑，闲题当日。\n宰相纱笼谁识。\n封丘门外定何人，这一点、瞒他不得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17369, '鹊桥仙', '刘辰翁', '看人掷果，看人罢织。\n难得团栾七夕。\n蟠桃只在屋东头，庆西母、年开八ど。\n去年今日。\n今年今日。\n添个曾孙抱膝。\n人间乐事有多般，算此乐、人间第一。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17370, '鹊桥仙', '刘辰翁', '轻风澹月，年年去路。\n谁识小年初度。\n桥边曾弄碧莲花，悄不记、人间今古。\n吹箫江上，沾衣微露。\n依约凌波曾步。\n寒机何意待人归，但寂历、小窗斜雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17371, '鹊桥仙', '刘辰翁', '天香吹下，烟霏成路。\n飒飒神光暗度。\n桥边犹记泛槎人，看赤岸、苔痕如古。\n长空皓月，小风斜露。\n寂寞江头独步。\n人间何处得飘然，归梦入、梨花春雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17372, '一翦梅', '刘辰翁', '万事如花不可期。\n花不堪持。\n酒不堪持。\n江天雪意使人迷。\n翦一枝枝。\n歌一枝枝。\n歌者不来今几时。\n姜影无词。\n张影无词。\n不歌不醉不成诗。\n歌也迟迟。\n雪也迟迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17373, '一翦梅', '刘辰翁', '人生总受业风吹。\n三岁儿儿。\n八十儿儿。\n深闺空谷把还持。\n啼看人知。\n啼怕人知。\n客中自种绿猗猗。\n月下横枝。\n雪下横枝。\n尊前百岁且开眉。\n今岁今时。\n前岁今时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17374, '夜飞鹊・夜飞鹊慢', '刘辰翁', '何曾见飞渡，年又年痴。\n今古相望犹疑。\n朱颜一去似流水，断桥魂梦参差。\n何堪更嗟迟暮，听旁人说与，此夕佳期。\n深深代籍，盼悠悠、北地胭脂。\n谁寄扬州破镜，遍海角天涯，空待人归。\n自小秦楼望巧，吴机回锦，歌舞为谁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17375, '疏影', '刘辰翁', '香篝素被。\n听花犯低低，瑶花开未。\n长记那时，炽炭围炉，瘦妻换酒行试。\n当家人在销金帐，约莫是、打围归际。\n又谁知、别忆烹茶，冷落故家愁思。\n闻道滕骄巽懒，今朝待檄与，翻云须易。\n白白不成，又不教晴，做尽黄昏情味。\n银河本是冰冰底。\n怎忍向、东风成水。\n待满城、玉宇琼楼，却报卧庐人起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17376, '摘红英', '刘辰翁', '花朝月。\n朦胧别。\n朦胧也胜檐声咽。\n亲曾说。\n令人悦。\n落花情绪，上坟时节。\n花阴雪。\n花阴灭。\n柳风一似秋千掣。\n晴未决。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17377, '千秋岁', '刘辰翁', '新熟也，借问谁家早。\n梅影里，蜂儿绕。\n三更残月上，一夜霜天晓。\n溪桥小，春风有意年年到。\n当年青鸟去，落叶无人扫。\n铜柱仄，瑶池老。\n残钟长乐树，坠马咸阳道。\n空回首，御街人卖南京枣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17378, '促拍丑奴儿', '刘辰翁', '送岁可无诗。\n得团栾、忍不开眉。\n不记去年今夕梦，江东怀抱，江西信息，舍北妻儿。\n五十炊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17379, '促拍丑奴儿', '刘辰翁', '世事莫寻思。\n待说来、天也应悲。\n百年已是中年後，西州垂泪，东山携手，几个斜晖。\n也莫苦吟诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17380, '最高楼', '刘辰翁', '银河水，洗得世间清。\n山色雨馀青。\n老子纶巾棋别墅，人家鼾睡柝秋城。\n定谁劳，定谁福，定谁能。\n常恨著、景升儿不似。\n又恨著、景升牛小耳。\n空相望，愧平生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17381, '最高楼', '刘辰翁', '朱顶字，八十正平头。\n添作八千秋。\n无能也自收坞，到今恨不贬潮州。\n看几人，炎又冷，老还羞。\n也不学、太公忙把火。\n也不学、申公轮转磨。\n休莫莫，莫休休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17382, '最高楼', '刘辰翁', '非是雪，只是玉楼成。\n屑不尽云英。\n东边老树颓然折，西头稚柳爆然声。\n试平安，松丈丈，竹兄兄。\n有谁向、金船呼小玉，又谁怜、纸帐梦飞琼。\n怪疏影，坠娉婷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17383, '最高楼', '刘辰翁', '花上雪。\n信手捻来成。\n屑不就琼英。\n昨朝已见诗成卷，今朝又试曲成声。\n更催催，莫不做，水仙兄。\n终须待、晴时携斗酒。\n更须待、老夫吟数首。\n休更叠，□娉婷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17384, '桂枝香', '刘辰翁', '吹箫人去。\n但桂影徘徊，荒杯承露。\n东望鞭芙缥缈，寒光如注。\n去年夜半横江梦，倚危樯，参差曾赋。\n茫茫角动，回舟尽兴，未惊鸥鹭。\n情知道、明年何处。\n漫待客黄楼，尘波前度。\n二十四桥，颇有杜书记否。\n二三字者今如此，看使君、角巾东路。\n人间俯仰，悲欢何限，团圆如故。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17385, '临江仙', '刘辰翁', '丞相衮衣朝戏彩，年年庆事如新。\n尊前一笑共儿孙。\n人间传寿酒，天上送麒麟。\n缥缈祥烟连北阙，天颜有喜生春。\n蓬莱清浅海光平。\n今年初甲子，重试碧桃根。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17386, '临江仙', '刘辰翁', '闻道城东鹤会，欣然一笑乘风。\n不知一鹤在墙东。\n神仙人不识，未始出吾宗。\n弟子有年於此，先生之道如龙。\n碧桃花子落壶中。\n化为三五粒，元是北边松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17387, '临江仙', '刘辰翁', '天际何分南与北，五更纵又成横。\n夜来拾得断河星。\n化为一片石，持去问君平。\n老大看天一笑，儿童问我须应。\n向来牛女本无名。\n要知天上事，亦似谤先生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17388, '临江仙', '刘辰翁', '二十年前此日，女兄庆我生儿。\n簪萱弄彩听孙啼。\n典衣沽美酒，数待冠昏时。\n乱後飘零独在，紫荆墓棘风吹。\n尊前万事莫寻思。\n儿童看有子，白发故应衰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17389, '临江仙', '刘辰翁', '旧日诗肠论斗酒，风流怀抱如倾。\n几年不听渭城声。\n尊前无贺老，卷里少弥明。\n闻说语言都好，便应步履全轻。\n长生第一是风僧。\n额前书八十，能说又能行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17390, '临江仙', '刘辰翁', '西曲衣迷去路，雪销断岸无痕。\n寻花不拟到前村。\n暖风初转袖，小径忽开门。\n却忆临塘桥下马，暗香不是黄昏。\n人生南北与谁论。\n岭梅花树下，闲听蜜蜂喧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17391, '临江仙', '刘辰翁', '老去尚呼张丈，醉中自惜熊儿。\n越王台上鹧鸪啼。\n三朝臣不遇，无复好文时。\n情绪幽幽似结，鬓丝索索禁吹。\n病来魂不到相思。\n散人腰已散，倚杖叹吾衰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17392, '临江仙', '刘辰翁', '海日轻红通似脸，小窗明丽新晴。\n满怀著甚是真情。\n不知春睡美，为爱晓寒轻。\n说似吴山楼万叠，雪销未尽宫城。\n湖边柳色渐啼莺。\n才听朝马动，一巷卖花声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17393, '临江仙', '刘辰翁', '过雁天边信息，两宫池上心情。\n沉思海角愤难平。\n山风欺客梦，耿耿到天明。\n幸自不争名利，闲愁夜夜如惊。\n明朝鬓白两三茎。\n世人都不念，似汝复何成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17394, '临江仙', '刘辰翁', '睡过花阴一丈，愁深酒力千锺。\n梦魂不得似游蜂。\n瓶花无密约，到处自神通。\n天上西湖似锦，人间骄马如龙。\n今年不与去年同。\n飘零终不恨，难与故人逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17395, '临江仙', '刘辰翁', '幸自不须端帖子，闲中一句如无。\n爱他午日午时书。\n惟应三五字，便是辟兵符。\n久雨石鲸未没，小风纨扇相疏。\n邀朋一笑共菖蒲。\n去年初禁酒，今日漫提壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17396, '临江仙', '刘辰翁', '我去就他甚易，他来认我良难。\n悟时到处是壶天。\n古诗寻一句，危坐看香烟。\n金玉满堂不守，菁华岁月空迁。\n从今饱饭更安眠。\n丹经都不看，闲坐一千年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17397, '临江仙', '刘辰翁', '旧日采莲羞半面，至今回首忽忽。\n梦穿斜日水云红。\n痴心犹独自，等待郑公风。\n海上颓云潮不返，侧身空坠辽东。\n人间天上几时同。\n宫衣元不遇，无语醉醒中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17398, '临江仙', '刘辰翁', '昔走都门终夜雨，明朝泥淖堪惊。\n疏疏点点忽难鸣。\n数峰青似染，快活早来晴。\n十五年间春梦断，乱山寒食清明。\n无人挑菜踏青行。\n青鸠啼雨外，闲听寺中声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17399, '鹧鸪天', '刘辰翁', '白白江南一信霜。\n过都字不到衡阳。\n老嘉破帽并吹却，未省西风似此狂。\n攀北斗，酌天浆。\n月香满似菊花黄。\n神仙暗度龙山劫，鸡犬人间百战场。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17400, '鹧鸪天', '刘辰翁', '白发平津起然。\n燕飞定远望生还。\n世间最有团栾乐，又是平平过一年。\n银信近，玉鞭先。\n东来西去爵衔鳝。\n人生有命迟迟好，且喜称觞寿母前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17401, '鹧鸪天', '刘辰翁', '占得春风五日先。\n至今住处是开元。\n写真若遇丹元子，只著当时宫锦船。\n松戴雪，自苍然。\n八公花下少如前。\n看来天上多辛苦，且住人间五百年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17402, '鹧鸪天', '刘辰翁', '自入孤山分外香。\n南枝不改旧时妆。\n为曾盘里承青眼，一见溪头道胜常。\n商山乐，又相羊。\n上方不复记传觞。\n橘中个个盘深窈，依倚东风局意长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17403, '鹧鸪天', '刘辰翁', '去年太岁田间土，明日香烟壁下尘。\n马上新人红又紫，眼前歌妓送还迎。\n钗头燕，胜金。\n燕歌赵舞动南人。\n遗民植杖唐巾起，闲伴儿童看立春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17404, '鹧鸪天', '刘辰翁', '旧日桃符管送迎。\n灯毯爆竹斗先嬴。\n鹿门乱走团栾久，才到城门有鼓声。\n梅弄雪，柳窥晴。\n残年犹自冷如冰。\n欲知春色招人醉，须是元宵与踏青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17405, '鹧鸪天', '刘辰翁', '暖逼酥枝渐渐融。\n双飞谁识蝶雌雄。\n歌声已逐行云去，花片偏来酒盏中。\n眉月冷，画楼空。\n酒阑犹未见情锺。\n直须把烛穿花帐，方见佳人玉面红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17406, '青玉案', '刘辰翁', '稠塘旧是花千树。\n曾泛入、溪深误。\n前度刘郎重唤渡。\n漫山寂寂，年时花下，往往无寻处。\n一年一度相思苦。\n恨不抛人过江去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17407, '青玉案', '刘辰翁', '雪销未尽残梅树。\n又风送、黄昏雨。\n长记小红楼畔路。\n杵歌串串，鼓声叠叠，预赏元宵舞。\n天涯客鬓愁成缕。\n海上传柑梦中去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17408, '青玉案', '刘辰翁', '里中上大人谁大。\n人上大、仁难作。\n八十六翁闲处坐。\n小生懒惰。\n近来高卧。\n忘却今朝贺。\n甲申还是连珠麽。\n胜有老人星一个。\n白发朱颜堪婆娑。\n灵光殿火。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17409, '青玉案', '刘辰翁', '无肠可断听花雨。\n沉沉已是三更许。\n如此残红那得住。\n一春情绪。\n半生羁旅。\n寂寞空山语。\n霖铃不是相思阻。\n四十平分犹过五。\n渐远不知何杜宇。\n不如归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17410, '踏莎行', '刘辰翁', '命薄佳人，情锺我辈。\n海棠开後心如碎。\n斜风细雨不曾晴，倚阑滴尽胭脂泪。\n恨不能开，开时又背。\n春寒只了房栊闭。\n待他晴後得君来，无言掩帐羞憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17411, '踏莎行', '刘辰翁', '壁彩笼尘，金吾掠路。\n海风吹断楼台雾，无人知是上元时，一夜月明无著处。\n早是禁烟，朝来冻雨。\n东风自放银花树。\n雪晴须有踏青时，不成也待明年去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17412, '踏莎行', '刘辰翁', '北望蝶山，西迷凤苑。\n忽忽醉里题诗满。\n黄花只似去年黄，去年人去黄花远。\n雨压城荒，丘园路断。\n却晴又恨公来晚。\n依稀自唱古人诗，明年此会知谁健。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17413, '踏莎行', '刘辰翁', '松偃成阴，荷香去暑。\n过溪似是东林路。\n不知宿昔有谁来，寺门同听催诗雨。\n北马依风，凉蝉咽暮。\n城门半带东陵圃。\n江南不是米元晖，无人更得沧洲趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17414, '踏莎行', '刘辰翁', '珠压相於，胭脂同傅。\n樊家更共谁家语。\n梢头结取一番愁，玉箫不会双双侣。\n风送流莺，前歌後舞。\n并桃欲吐含来往。\n双飞燕子自相衔，会教唇舌调鹦鹉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17415, '烛影摇红', '刘辰翁', '老子婆娑，那回也上南楼去。\n素娥有恨隐云屏，元是娇痴故。\n惊扇徘徊未许。\n耿多情、为谁堪诉。\n使君愁绝，独倚阑干，後期无据。\n有酒如船，片云扫尽霓裳露。\n他时与客更携鱼，犹记临皋路。\n因念南羁北旅。\n醉乌乌、凭君楚舞。\n问君不见，璧月词成，楼西沉处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17416, '烛影摇红', '刘辰翁', '明月如冰，乱云飞下斜河去。\n旋呼艇子载箫声，风景还如故。\n袅袅余怀何许。\n听尊前、呜呜似诉。\n近年潮信，万里阴晴，和天无据。\n有客秋风，去时留下金盘露。\n少年终夜奏胡笳，谁料归无路。\n同是江南倦旅。\n封婵娟、君歌我舞。\n醉中休问，明月明年，人在何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17417, '烛影摇红', '刘辰翁', '春日江郊，素娥吹下银幡舞。\n东风点点乱茶烟，留到明朝否。\n掩袖凝寒不语。\n漫粘酥、枝枝缕缕。\n断肠何似，飞絮多时，落梅深处。\n仙掌擎来，翠眉敛半看成露。\n惊沙马上面帘轻，谁贵毡庐主。\n多少高阳伴侣。\n到如今、沉冥几许。\n乘槎相问，万里银河，欲归无路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17418, '念奴娇', '刘辰翁', '先生自寿，拥衾寒，重赋凌云游意。\n我有大儿孔文举，弱冠暮齿。\n桃已三偷，树犹如此，前度花开几。\n蓬莱可塞，还童却老无计。\n为此授笔翩翩，大江东去，好似歌头起。\n寄与两家孙又子，长看以文为戏。\n某所某公，同年同月，谁翦招魂纸。\n前三例好，不须举後三例。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17419, '念奴娇', '刘辰翁', '枯寒生晚，复何似、张绪少年时意。\n薄命不逢何至此，满眼啼妆龋齿。\n城是城非，年来年去，万八千能几。\n半痴半了，更痴儿计孙计。\n回首仕已半生，仕何如已，已矣羞拈起。\n幸有橘丸丸日大，且复从公围戏。\n若论弹文，更书谤箧，吾历无馀纸。\n多年致仕，大都有甚恩例。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17420, '念奴娇', '刘辰翁', '吾年如此，更梦里、犹作狼居胥意。\n千首新诗千斛酒，管甚侯何侯齿。\n员峤波翻，瀛洲尘败，吾屐能销几。\n经丘寻壑，是他早计迟计。\n犹记辰巳嗟嗟，故人贺我，且勉呼君起。\n五十不来来过二，方悟人言都戏。\n以我情怀，借公篇韵，恨不天为纸。\n馀生一笑，不须邴曼容例。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17421, '念奴娇', '刘辰翁', '沧洲一叶，待借君、回我炉亭春意。\n突兀灵光无立壁，八面江风寒齿。\n乡屐廊深，笼门槛赤，数月才几。\n千年未论，岂无数十年计。\n我本高卧墙东，何知人事，推枕为君起。\n憔悴庚寅何足记，不觉联翩宾戏。\n白雪阳春，黄鸡唱日，绝少澄心纸。\n我歌草草，和章有例还例。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17422, '念奴娇', '刘辰翁', '两丸日月，细看来、也是樊笼中物。\n点点山河经过了，拔帜几番残壁。\n白是沙堤，苍然吴楚，一片成毡雪。\n此时把酒，旧词还是坡杰。\n歌罢公瑾当年，天长地久，柳与梅都发。\n几许闲愁斜照里，掌上沤生沤灭。\n沧海桑枯，东陵瓜远，总不关渠发。\n簪花起舞，可怜今夕无月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17423, '乳燕飞・贺新郎', '刘辰翁', '赤壁之游乐。\n但古今、风清月白，更无坡作。\n矫首中洲公何许，共我横江孤鹤。\n把手笑、孙刘寂寞。\n颇有使君如今否，看青山、似我多前却。\n几见我、伴清酌。\n江心旧岂非城郭。\n抚千年、桑田海水，神游非昨。\n对影三人成六客，更倚归舟夜泊。\n尚听得、江城愁角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17424, '乳燕飞・贺新郎', '刘辰翁', '曾授茅山记。\n共当年、二百七十，又三甲子。\n昨上云台占云物，占得景风南至。\n又恰是、封侯千岁。\n行遍神州河洛外，早归来、庭下槐阴翠。\n春万户，共生意。\n溪翁图是参同契。\n想金丹、圆成功行，活人相似。\n顾我尊前歌赤壁，生子当如此耳。\n笑华发、东坡年几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17425, '乳燕飞・贺新郎', '刘辰翁', '过雨城西路。\n看轻云、弄日花间，微寒如雾。\n谁是宣华门守者，报我十分开五。\n便痛饮、能销几度。\n寄语後来看花客，待看花、莫待开成树。\n成树也，半为土。\n巢蜀锦今何许。\n记西湖、聚景村庄，王亭谢墅。\n冷落柯丘二三子，更问何园韩圃。\n悄一笑、回车竹所。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17426, '瑞鹤仙', '刘辰翁', '正丹翁初度。\n对花满江城，晓莺欲语。\n崆峒在何处。\n渐雨过农郊，劝耕问路。\n州人争观。\n问坡老、重来是否。\n把看灯、传说风流，八境尽图新句。\n如许。\n老子文章，挥毫立马，脱靴嫌污。\n太平易作。\n听父老，歌襦裤。\n愿使君小住，五风十雨。\n重见一麸三黍。\n又天边、飞诏殷勤，说相将去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17427, '高阳台', '刘辰翁', '雨枕莺啼，露班烛散，御街人卖花窠。\n过眼无情，而今魂梦年多。\n百钱曳杖桥边去，问几时、重到明河。\n便人问，无了东风，此恨难磨。\n落红点点入颓波。\n任归春到海，海又成涡。\n江上儿童，抱茅笑我重过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17428, '声声慢', '刘辰翁', '西风坠绿。\n唤起春娇，嫣然困倚修竹。\n落帽人来，花艳乍惊郎目。\n相思尚带旧子，甚凄凉、未妆束。\n吟鬓底，伴寒香一朵，并簪黄菊。\n却待金盘华屋。\n园林静、多情怎禁幽独。\n蛱蝶应愁，明日落红难触。\n那堪雁霜渐重，怕黄昏、欲睡未足。\n翠袖冷，且莫辞、花下秉烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17429, '汉宫春', '刘辰翁', '雨入轻寒，但新未试，荒了东篱。\n朝来暗惊翠袖，重倚屏帏。\n明窗丽阁，为何人、冷落多时。\n催重顿，妆台侧畔，画堂未怕春迟。\n漫省茸香粉晕，记去年醉里，题字倾。\n红炉未深乍暖，儿女成围。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17430, '汉宫春', '刘辰翁', '疏影横斜，似故人安道，只在前溪。\n年年望雪待月，漫倚吟矶。\n千红万紫，到春来、也是寻思。\n君不见，永阳江上，残梅冷雨丝丝。\n有几情人似我，漫骑牛卧笛，乱插繁枝。\n市门索笑憔悴，便作新知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17431, '洞仙歌', '刘辰翁', '也曾海上，啖如瓜大枣。\n海上归来相公老。\n画堂深、满引明月清风，家山好、一笑尘生蓬岛。\n六年春易过，赢得清阴，到处持杯藉芳草。\n看明年此日，人在黄金台上，早整顿、乾坤事了。\n但细数斋年几人存，更宰相高年，几人能到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17432, '洞仙歌', '刘辰翁', '有客从余，不计余无酒。\n袖有蟠桃为君寿。\n叹此桃再熟，也须年後。\n甚辨得，转盼个偷桃手。\n菊潭三十斛，月又月添，天赋先生日更久。\n但黄杨长寸，闰年倒寸，似凭得到梧宫甚时候。\n客又道奇特是阳生，後七日相看，醉春风柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17433, '齐天乐', '刘辰翁', '枝头雨是青梅泪。\n翻作一江春水。\n鱼腹魂销，龙舟叫彻，不了湖亭张戏。\n满庭芳芷。\n正艾日高高，葛风细细。\n试比陈人，人间除我更谁似。\n浮沉君共我里。\n记薰廊待对，闻鸡蹴起。\n昨日蟾蜍，明朝蝇虎，身与渠衰更悴。\n老夫病已。\n任采绿采苓，为师为帝。\n但有昌阳，倩酤扶路醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17434, '齐天乐', '刘辰翁', '海枯泣尽天吴泪。\n又涨经天河水。\n万古鱼龙，雷收电卷，宇宙刹那间戏。\n沉兰坠芷。\n想重整荷衣，顿惊腰细。\n尚有干将，冲牛射斗定何似。\n成都桥动万里。\n叹何时重见，鹃啼人起。\n孤竹双清，紫荆半落，到此吟枯神瘁。\n对床永已。\n但梦绕青神，尘昏白帝。\n重反离骚，众醒吾独醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17435, '齐天乐', '刘辰翁', '蒋陵故是簪花路。\n风烟奈何秋暑。\n候馆凋梧，宫墙断柳，谁识当年倦旅。\n余怀何许。\n想上马人扶，翠眉愁聚。\n旧日方回，而今能赋断肠语。\n登高能赋最苦。\n叹高高难问，欲望迷处。\n蝶绕东篱，鸿翻上苑，那更画梁辞主。\n来今往古。\n漫湛辈同来，远公回去。\n我醉安归，黄花扶路舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17436, '江城梅花引', '刘辰翁', '几年城中无看灯。\n夜三更。\n月空明。\n野庙残梅，村鼓自春声。\n长笑儿童忙踏舞，何曾见，宣德棚，不夜城。\n去年今年又伤心。\n去年晴。\n去年曾。\n不似今年，闲坐处、却不曾行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17437, '江城梅花引', '刘辰翁', '相思无处著春寒。\n傍阑干。\n湿阑干。\n似我情怀，处处忆临安。\n想见夜深村鼓静，灯晕碧，为傍人，说上元。\n是花是雪无意看。\n雨摧残。\n雨摧残。\n探春未还。\n到春还、似不如闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17438, '兰陵王', '刘辰翁', '雁归北。\n渺渺茫茫似客。\n春湖里，曾见去帆，谁遣江头絮风息。\n千年记当日。\n难得。\n宽闲抱膝。\n兴亡事，马上飞花，看取残阳照亭驿。\n哀拍。\n愿归骨。\n怅毡帐何匹，酪何食。\n相思青冢头应白。\n想荒坟酹酒，过车回首，香魂携手抱相泣。\n但青草无色。\n语绝。\n更愁极。\n漫一番青青，一番陈迹。\n瑶池黄竹哀离席。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17439, '兰陵王', '刘辰翁', '送春去。\n春去人间无路。\n秋千外、芳草连天，谁遣风沙暗南浦。\n依依甚意绪。\n漫忆海门飞絮。\n乱鸦过，斗转城荒，不见来时试灯处。\n春去。\n最谁苦。\n但箭雁沉边，梁燕无主。\n杜鹃声里长门暮。\n想玉树凋土，泪盘如露。\n咸阳送客屡回顾。\n斜日未能度。\n春去。\n尚来否。\n正江令恨别，庾信愁赋。\n苏堤尽日风和雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17440, '琐窗寒', '刘辰翁', '嫩绿如新，娇莺似旧，今吾非故。\n空山过雨，留春春去。\n似尊前曲曲阳关，行人回首江南处。\n漫停云低黯，征衫憔悴，酒痕犹污。\n欲语。\n浑未住。\n记匹马经行，风林烟树。\n家山何在，想见绿窗啼雾。\n又何堪满目凄凉，故园梦里能归否。\n但数声、惊觉行云，重省佳期误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17441, '归朝歌', '刘辰翁', '最是一人称好处。\n昨日小春留得住。\n梅花信信望东风，须待公归香满路。\n年时今已度。\n长是巴山深夜雨。\n宣又召，凯还簇簇，要见寿觞举。\n扫尽窝蜂闲绣斧。\n叠鼓春声欢岁暮。\n燕台剑履趣锋车，银信低低传好语。\n紫貂裘脱与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17442, '大圣乐', '刘辰翁', '芳草如云，飞红似雨，卖花声过。\n况回首、洗马塍荒，更寒食、宫人斜闭，烟雨铜驼。\n提壶卢何所得酒，泥滑滑、行不得也哥哥。\n伤心处，斜阳巷陌，人唱西河。\n天下事，不如意十常八九，无奈何。\n论兵忍事，对客称好，面皱如靴。\n广武噫嘻，东陵反覆，欢乐少兮哀怨多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17443, '宝鼎现', '刘辰翁', '红妆春骑。\n踏月影、竿旗穿市。\n望不尽、楼台歌舞，习习香尘莲步底。\n箫声断、约彩鸾归去，未怕金吾呵醉。\n甚辇路、喧阗且止。\n听得念奴歌起。\n父老犹记宣和事。\n抱铜仙、清泪如水。\n还转盼、沙河多丽。\n漾明光连邸第。\n帘影冻、散红光成绮。\n月浸葡萄十里。\n看往来、神仙才子。\n肯把菱花扑碎。\n肠断竹马儿童，空见说、三千乐指。\n等多时春不归来，到春时欲睡。\n又说向、灯前拥髻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17444, '祝英台近', '刘辰翁', '昨朝晴，今朝雨。\n渺莽遽如许。\n厌听儿童，总是涨江语。\n是谁力挽天河，误他仙客，并失却、乘槎来路。\n断肠苦。\n翦烛深夜巴山，酒醒听如故。\n勃荷衣，堕泪少乾土。\n从初错铸鸱夷，不如归去，到今此、欲归何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17445, '祝英台近', '刘辰翁', '看师师、成蝶蝶。\n蹙尽不成叠。\n欲试搔头，花重怎堪捻。\n是谁抛过东墙，今无赤凤，梦得似、那人身捷。\n年时腊。\n曾笑梅梢和豆，去月忽如荚。\n便向龙门，无复钏金接。\n待教开到琼林，阆仙重见，又谁念、昆明前劫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17446, '忆旧游', '刘辰翁', '渺山城故苑，烟横绿野，林胜青油。\n甚相思只在，华清泉侧，凝碧池头。\n故人念我何处，坠泪水西流。\n念寒食如君，江南似我，花絮悠悠。\n不知身南北，对断烟禁火，蹇六年留。\n恨听莺不见，到而今又恨，成愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17447, '唐多令', '刘辰翁', '明月满沧洲。\n长江一意流。\n更何人、横笛危楼。\n天地不知兴废事，三十万、八千秋。\n落叶女墙头。\n铜驼无恙不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17448, '唐多令', '刘辰翁', '风露小瀛洲。\n斜河倒海流。\n人间尘、不到琼楼。\n错向五陵陵上望，几回月、几回秋。\n落日太湖头。\n垂虹今是不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17449, '唐多令', '刘辰翁', '寒雁下荒洲。\n寒声带影流。\n便寄书、不到红楼。\n如此月明如此酒，无一事、但悲秋。\n万弩落潮头。\n灵胥还怒不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17450, '唐多令', '刘辰翁', '日落紫霞洲。\n兰舟稳放流。\n玉虹仙、如在黄楼。\n何必锦袍吹玉笛，听乃、数声秋。\n赤壁舞涛头。\n周郎还到不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17451, '唐多令', '刘辰翁', '零露下长洲。\n云翻海倒流。\n素娥深、不到西楼。\n忽觉断潮归去也，饮不尽、一轮秋。\n城外土馒头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17452, '唐多令', '刘辰翁', '明月满河洲。\n星河带月流。\n料素娥、独倚琼楼。\n竟是何年何药误，魂梦冷、不禁秋。\n少日梦龙头。\n知君犹梦不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17453, '唐多令', '刘辰翁', '残日下瓜洲。\n平安火又流。\n月高高、挂古城楼。\n回首少年真可笑，无一事、又悲秋。\n天在海边头。\n天风有意不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17454, '唐多令', '刘辰翁', '春雨满江城。\n汀洲春水生。\n更悲久雨似春酲。\n犹有一般天富贵，夜来雨、早来晴。\n年少总看灯。\n老来犹故情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17455, '虞美人', '刘辰翁', '空明一朵扬州白。\n红紫无□色。\n是谁唤作水晶球。\n惹起高烧银烛、上元愁。\n去年一捧飞来雪。\n不似渠千叶。\n狂风一蹴过秋千。\n憔悴玉人和泪、望婵娟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17456, '虞美人', '刘辰翁', '天香国色辞脂粉。\n肯爱红衫嫩。\nけ然自取玉为衣。\n似是银河水皱、织成机。\n寒欺薄薄春无力。\n月浸霓裳湿。\n一窠香雪世间稀。\n可惜不教留到、布衣时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17457, '虞美人', '刘辰翁', '寿安楼子重重蕊。\n少见如鱼尾。\n向来染得渭脂红。\n又自细摇花浪、动春风。\n鳞似是人谁信。\n但向残红认。\n若教随水去悠然。\n为报沙头玉鹭、莫贪鲜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17458, '虞美人', '刘辰翁', '花心定有何人捻。\n晕晕如娇靥。\n一痕明月老春宵。\n正似酥胸潮脸、不曾销。\n当年掌上开元宝。\n半是杨妃爪。\n若教此掏到痴人。\n任是高墙无路、蝶翻身。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17459, '虞美人', '刘辰翁', '无花敢与姚黄比。\n对对鸳鸯起。\n识他金带万钉垂。\n谁向麒麟楦里、卸猴绯。\n潜溪以上难为说。\n自是君恩别。\n後来西子避无盐。\n又道君王捉鼻、又何嫌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17460, '虞美人', '刘辰翁', '魏家品是君王后。\n岂比昭容袖。\n风吹满院绣囊香。\n谁赐大师师号、退昭阳。\n飞霞一落无根蒂。\n空坠重华泪。\n离披正午盛时休。\n闲为思王重赋、洛神愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17461, '虞美人', '刘辰翁', '犹疑绿萼花微甚。\n难与青莲并。\n青莲朵朵是天人。\n又向天人想见、洛阳春。\n多情素质尘生步。\n况被潘妃污。\n此花仍是□微。\n却似娇波波外、两眉青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17462, '虞美人', '刘辰翁', '楼台烟雨朱门悄。\n乔木芳云杪。\n半窗天晓又闻莺。\n比似当年春尽、最关情。\n客中自被啼鹃恼。\n况落春归道。\n满怀憔悴有谁知。\n犹记涌金门外、送人时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17463, '虞美人', '刘辰翁', '黄柑擘破传春雾。\n新酒如清露。\n城中也是几分灯。\n自爱城山堂上、两三星。\n枝头未便风和雨。\n寂寞无歌舞。\n天公肯放上元晴。\n自是六街三市、少人行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17464, '虞美人', '刘辰翁', '徐家破镜昏如雾。\n半面人间露。\n等闲相约是看灯。\n谁料人间天上、似流星。\n朱门帘影深深雨。\n憔悴新人舞。\n天涯海角赏新晴。\n惟有桥边卖镜、是闲行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17465, '虞美人', '刘辰翁', '黄帘绿幕窗垂雾。\n表立如承露。\n夕郎偷看御街灯。\n归奔河边残点、乱如星。\n开园蒋李游春雨。\n蛱蝶穿人舞。\n如今烟草锁春晴。\n并与苏堤葛岭、不堪行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17466, '虞美人', '刘辰翁', '红乾色无光霁。\n须是鲜鲜翠。\nけ然一点系裙腰。\n不著人间金屋、恐难销。\n英英肯似焉支贵。\n漫脱红霞帔。\n落时且勿尘泥。\n留向天台洞口、泛吾诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17467, '虞美人', '刘辰翁', '湿云待向三更吐。\n更是沉沉雨。\n眼前儿女意堪怜。\n不说明朝後日、说明年。\n当年知道晴三鼓。\n便似佳期误。\n笑他拜月不曾圆。\n只是今朝北望、也凄然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17468, '虞美人', '刘辰翁', '梅梢腊尽春归了。\n毕竟春寒少。\n乱山残烛雪和风。\n犹胜阴山海上、窖群中。\n年光老去才情在。\n惟有华风改。\n醉中幸自不曾愁。\n谁唱春花秋叶、泪偷流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17469, '虞美人', '刘辰翁', '情知是梦无凭了。\n好梦依然少。\n单于吹尽五更风。\n谁见梅花如泪、不言中。\n儿童问我今何在。\n烟雨楼台改。\n江山画出古今愁。\n人与落花何处、水空流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17470, '虞美人', '刘辰翁', '轻衫倚望春晴稳。\n雨压青梅损。\n皱绡池影泛红蔫。\n看取断云来去、似炉烟。\n愁春来暮仍愁暮。\n受却寒无数。\n年来无地卖花栽。\n向道明年花信、莫须来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17471, '虞美人', '刘辰翁', '娟娟二八清明了。\n犹说淮阳早。\n钱欧陆谱遍花光。\n红到寿阳、也不说淮阳。\n此花地望元非薄。\n回首伤流落。\n洛阳闲岁断春风。\n怎不当时道是、洛阳红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17472, '虞美人', '刘辰翁', '秋阴团扇如人老。\n渐近中秋好。\n新凉远忆小楼边。\n自在一窗明月、傍人眠。\n多情谁到星河晓。\n只道圆时少。\n他年几处与君看。\n长是成愁成恨、不成欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17473, '恋绣衾', '刘辰翁', '胭脂不紫玉箫。\n认宫中、银字未销。\n但凤去、台空古，比落花、无第二朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17474, '恋绣衾', '刘辰翁', '困如宿酒犹未销。\n满华堂、羞见目招。\n忽折向、西邻去，教旁人、看上马娇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17475, '恋绣衾', '刘辰翁', '当年三五舞太平。\n醉归来、花影满庭。\n办永夜、重开宴，笑姑苏、万眼未明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17476, '花犯', '刘辰翁', '海山昏，寒云欲下，低低压吹帽。\n平沙浩浩。\n想关塞无烟，时动衰草。\n苏郎卧处愁难扫。\n江南春不到。\n但怅望、雪花夜白，人间憔悴好。\n谁知广寒梦无，丁宁白玉炼，不关怀抱。\n看清浅、桑田外，尘生热恼。\n待说与、天公知道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17477, '花犯', '刘辰翁', '甚天花、纷纷坠也，偏偏著余帽。\n乾坤清皓。\n任海角荒荒，都变瑶草。\n落梅天上无人扫。\n角吹吹不到。\n想特为、东皇开宴，琼林依旧好。\n看儿贪耍不知寒，须塑就玉狮，置儿怀抱。\n奈转眼、今何在，泪痕成恼。\n白发翁翁向儿道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17478, '酹江月・念奴娇', '刘辰翁', '冰肌玉骨，笑嫣然、总是风尘中物。\n谁扫一枝，流落到、绝域高台素壁。\n匹马南来，千山万水，为访林间雪。\n渊明爱菊，不知谁是花杰。\n憔悴梦断吴山，有何人报我，前村夜发。\n蜡屐霜泥烟步外，转入波光明灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17479, '酹江月・念奴娇', '刘辰翁', '四无谁语，待推窗、初见江南风物。\n索笑巡檐无奈处，悄隔东邻一壁。\n有酒如船，招呼满载，只欠枝头雪。\n疏花冷眼，坐中都是词杰。\n堪恨几日西郊，寻消问息，肯向吟边发。\n著意相看，又恐是、六出幻成还灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17480, '酹江月・念奴娇', '刘辰翁', '五朝寿俊，算生平占得、淳熙四四。\n三万六千三万了，剩有一千饶底。\n三百年间，和风丽日，几个能销此。\n约山山笑，先生不负山矣。\n今岁甲子重阳，待重数，五百十三甲子。\n吟万首诗更自和，岁岁寿诗自喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17481, '酹江月・念奴娇', '刘辰翁', '西风处士，例一枝团月，咸平印印。\n千古诗宗传不绝，至竟被渠道尽。\n雪返香魂，霜吹晓怨，肯受东君聘。\n罗浮梦转，兔环知是谁孕。\n未说烟雨江南，垂垂青子，须要调金鼎。\n愁绝西山明秀处，依旧鹤南飞影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17482, '酹江月・念奴娇', '刘辰翁', '棹歌齐发，江云暮、吹得湘愁成雨。\n小酌千年，知他是、阿那年时沈午。\n日落长沙，风回极浦，黯不堪延伫。\n吴头楚尾，非关四面为楚。\n几度唤起醒累，淋漓痛饮，不学愁余句。\n踏鲤从鼋胥涛上，怎不化成龙去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17483, '酹江月・念奴娇', '刘辰翁', '岁寒相命，算人间、除了梅花无物。\n窥宋三年又不是，草草东邻凿壁。\n偃蹇风前，沉吟竹外，直待天骄雪。\n白家人至，一枝横出终杰。\n寂寞小小疏篱，探花使断，知复何时发。\n北驿不来春又远，只向窗前埋灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17484, '酹江月・念奴娇', '刘辰翁', '遥怜儿女，未解忆长安、十年前月。\n徙倚桂枝空延伫，无物同心堪结。\n冷落江湖，萧条门巷，犹著西楼客。\n恨无铁笛，一声吹裂山石。\n休说起舞登楼，那人已先我，渡江横楫。\n圆缺不销青冢恨，漠漠风沙如雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17485, '酹江月・念奴娇', '刘辰翁', '团团桂影，怕人道、大地山河里许。\n旧日影娥池未缺，惊断霓裳歌舞。\n雪白长城，金明古驿，尽是乘槎路。\n少年白发，自无八骏能去。\n犹记流落荒滨，故人相过，共吹箫前度。\n无酒无鱼空此客，昨夜留之不住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17486, '酹江月・念奴娇', '刘辰翁', '城中十万，有何人、和我乌乌鸣瑟。\n对影娥成三处，谁料尊中无月。\n翦纸吹成，长梯摘取，儿戏那堪惜。\n洞庭夜白，一声聊破空阔。\n休说二十四桥，便一分无赖，有谁谁识。\n一枕秋衾南北梦，好好娟娟成雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17487, '满江红', '刘辰翁', '淡淡胭脂，似褪向、景阳鸳石。\n依然是、春睡未足，捧心犹癖。\n藉甚不禁君再顾，嫣然却记渠初拆。\n黯销魂、欲尽更堪怜，终难得。\n犹记是，卿卿惜。\n空复见，谁谁摘。\n但当时一笑，也成陈迹。\n我懒花残都已往，诗朋酒伴犹相觅。\n听连宵、又雨又还晴，鸠鸣寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17488, '满江红', '刘辰翁', '何许相求，且不是、南温北石。\n也欲学、绝交高论，自陈余癖。\n万里鱼书长记忆，十年波浪伤离拆。\n算此舟、不是剡溪舟，空回得。\n非出处，何须惜。\n非瑕，何须摘。\n看雪销鸿去，有何留迹。\n安石岂无同乐意，玄真不是朝廷觅。\n但眼前、真率暂相违，歌声寂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17489, '满江红', '刘辰翁', '莺语依然，但春去、人间无约。\n谁念我、吟情憔悴，醉魂落魄。\n尽日只将行卷续，有时自整残棋著。\n向黄昏、细雨闷无，青梅落。\n南又北，相思错。\n朝异暮，人情薄。\n漫踌躇在目，奢华如昨。\n海底月沉天上兔，辽东人化扬州鹤。\n记龙云、波浪岂能平，天难托。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17490, '满江红', '刘辰翁', '十岁儿童，看骑竹、花阴满城。\n与新第、桐乡孙子，高下齐生。\n倚枕不寻柯下梦，举头自爱橘中名。\n但有时、米价问如何，公助平。\n东西塾，听书声。\n长短卷，和诗成。\n总神仙清福，前辈家庭。\n试问凌烟图相国，何如洛寺写耆英。\n甚天公、属意富民侯，银信青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17491, '八声甘州', '刘辰翁', '问海棠花下，又何如、玄都观中游。\n叹巢蜀锦，常时不数，前度何稠。\n谁见宣华故事，歌舞簇遨头。\n共是西江水，不解西流。\n在处繁华如梦，梦占人年少，生死堪羞。\n任倾城倾国，风雨一春休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17492, '八声甘州', '刘辰翁', '看团团、一物大如杯，时复几何秋。\n俯天涯海角，今来古往，人物如流。\n想见霓裳歌罢，无物与浇愁。\n惟有当时树，香满琼楼。\n谁念南楼老子，倚西风尘满，心事悠悠。\n便班姬袖里，明月一时休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17493, '八声甘州', '刘辰翁', '记前朝、鹤会又重来，攀翻第三桃。\n看云华授策，麻姑擘脯，嬴女吹箫。\n寻思曲江旧事，宫锦胜龙标。\n奏罢清华梦，独立春宵。\n不数相州锦样，是调羹御手，重解金貂。\n但今年此日，疏了醉葡萄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17494, '八声甘州', '刘辰翁', '但秋风、年又一年深，不禁长年悲。\n自景阳钟断，馆娃宫闭，冷落心知。\n千树西湖杨柳，更管别人离。\n看取茂陵客，一去无归。\n都是旧时行乐，漫烟销日出，水绕山围。\n看人情荏苒，不似鹧鸪飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17495, '八声甘州', '刘辰翁', '看飘飘、万里去东流，道伊去如风。\n便锦缆危潮，青山御宿，烟雨啼红。\n愁是明朝酒醒，听著返魂钟。\n留得春如故，了不关侬。\n春亦去人远矣，是别情何薄，归兴何浓。\n但江南好□，未便到芙蓉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17496, '八声甘州', '刘辰翁', '甚花间、儿女笑盈盈。\n人添雪狮成。\n任踏青无路，凌波有地，步步光尘。\n招得梅妃魂也，好似去年春。\n柳亦何曾絮，都是云英。\n休道东皇诞漫，到茶烟歇後，谁浊谁清。\n赖谢娘好语，端胜解围兵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17497, '水龙吟', '刘辰翁', '何须银烛红妆，菜花总是曾留处。\n流觞事远，绕梁歌断，题红人去。\n绕蝶东墙，啼莺修竹，疏蝉高树。\n叹一春风雨，归来抱膝，怀往昔、自凄楚。\n遥望东门柳下，梦参差、欲归幽路。\n断红芳草，连空积水，凭高坠雾。\n水洗铜驼，天清华表，升平重遇。\n但相如老去，江淹才尽，有何人赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17498, '水龙吟', '刘辰翁', '多年袖瓣心香，重新拈出为公寿。\n唤起老龙，如今正是，欠伸时候。\n弱语闻莺，轻阴转柳，弦薰未透。\n信江南，自有真孺未用，须待见、衮和绣。\n闻说锋车在道，更四辈、传宣来骤。\n蟠胸何限，天门夜对，春宫晨奏。\n梅子阴浓，菖蒲花老，枯槔闲後。\n但北关下泽，遗民社在，贺公归昼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17499, '水龙吟', '刘辰翁', '看人削树成槎，布帆海上秋风浪。\n白头坡老，知津水手，倚桄榔杖。\n九点齐州，半生髀肉，烟尘苍莽。\n但北窗梦转，青阴满眼，抚陈迹、玩新涨。\n世事艰难已遍，笑而今、不堪重想。\n龙筋虎骨，根深伏兔，擎空千丈。\n礼乐文章，终须梦卜，南人为相。\n问凌烟生面，他时彷佛，似何人像。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17500, '水龙吟', '刘辰翁', '闲思十八年前，依稀正是公年纪。\n铜驼陌上，乌衣巷口，臣清如水。\n是处风筝，满城昼锦，儿郎俊伟。\n但幅巾藜杖，低垂白鬓，用与绮、问何里。\n最忆他年甘旨。\n也曾经、三仕三已。\n至今结习，馀年未了，业多生绮。\n安得滕廛，移将近市，长薰晋鄙。\n望福星炯炯，西江千里，待公来社。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17501, '水龙吟', '刘辰翁', '多年绿幕黄帘，瓶花黯黯无谁主。\n荀陈迹远，燕吴路断，何人星聚。\n四圣楼台，水仙华表，冷烟和雨。\n但徘徊梦想，美人不见，空犹记、铁炉步。\n过尽凉风天末，坠华笺、行行飞翥。\n一端翠织，锦鲸茅屋，天吴惊舞。\n念我何辰，涸阴冰子，生怜金虎。\n恨儿痴不了，山川悠缅，共君黉宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17502, '水龙吟', '刘辰翁', '征衫春雨纵横，可曾湿得飞花透。\n知君念我，溪南徙倚，谁家红袖。\n藉草成眠，簪花倚醉，狂歌扶手。\n叹故人何处，闻鹃堕泪，春去也、到家否。\n说与东风情事，怕东风、似人眉皱。\n乱山华屋，残邻废里，不堪回首。\n寒食江村，牛羊丘陇，茅檐酤酒。\n笑周秦来往，与谁同梦，说开元旧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17503, '水龙吟', '刘辰翁', '孤烟澹澹无情，角声正送层城暮。\n伤怀绝似，龙山罢後，骑台沉处。\n珠履三千，金人十二，五陵无树。\n叹岐王宅里，黄公垆下，空鼎鼎、记前度。\n几许英雄文武。\n酒不到、故人坟土。\n平生破帽，几番摇落，受西风侮。\n昨日如今，明年此会，俯然怀古。\n便东篱甲子，花开花谢，不堪重数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17504, '宴春台', '刘辰翁', '五十三年，韶华刚度，今年夏五十三。\n瑞鹤朝来，待公弥月重探。\n人生贵寿多男。\n看斓斑室，添个荷衫。\n□□□，亭亭八面，醉倚红酣。\n承平故事，暇日清谈。\n云龙风虎，塞北江南。\n午桥午枕，羲皇白日如。\n手种蟠桃，明年看取，实大如柑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17505, '扫花游・扫地游', '刘辰翁', '春台路古，想店月潭云，鸡鸣关候。\n巾车尔久。\n记湘累降日，留词劝酒。\n不是行边，待与持杯论斗。\n算吾寿。\n已待得河清，万古晴昼。\n京国事转手。\n漫宫粉堆黄，髻妆啼旧。\n瑶池在否。\n自刘郎去後，宴期重负。\n解事天公，道是全无又有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17506, '忆江南', '刘辰翁', '花几许，已报八分催。\n却问主人何处去，且容老子个中来。\n花外主人回。\n年时客，如今安在哉。\n正喜锦宫城烂漫，忽惊花鸟使摧颓。\n世事只添杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17507, '梅花引', '刘辰翁', '酒熟未。\n梅开未。\n去年迟待重来醉。\n笑当筵。\n舞当筵。\n惟有今年。\n八十是开年。\n参差野袂成归鹤。\n石鼎未开容剥啄。\n岁开尊。\n岁添孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17508, '蝶恋花', '刘辰翁', '过雨新荷生水气。\n高影参差，无谓思量睡。\n梦里不知轻别意。\n醒来竟是谁先起。\n去路夕阳芳草际。\n不论阑干，处处情怀似。\n记得分明羞掷蕊。\n自知不是天仙子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17509, '蝶恋花', '刘辰翁', '八九十翁嬉入市。\n把菊簪萸，共说新美。\n何以祝公千百岁。\n寿潭自酌花间水。\n白鹭沉沉飞复起。\n杜老江头，不恨秋风里。\n欲种蟠根天上李。\n三千年看青青子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17510, '霓裳中序第一', '刘辰翁', '银河下若木。\n暖涨一川春雾绿。\n白凤徘徊清淑。\n似沉水无烟，汤千斛。\n柔肌暗粟。\n想临流、娇喷轻触。\n空恨恨，何人热恼，却忆冷泉掬。\n酥玉。\n未谙汤沐。\n深又浅、荡摇心目。\n云蒸雨渍翻覆。\n泛影浮红，飘飘相逐。\n裳衣还未欲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17511, '瑞龙吟', '刘辰翁', '老人语。\n曾见昨日开炉，坠天花否。\n生年不合荒荒，枯根薄命，婵娟误汝。\n那知许。\n女乐如烟点点，江南处处。\n何时重到湖，淋漓载酒，依稀吊古。\n终待胭脂露掌，弄鸥招鹤，凭君画取。\n万柳漫堤，一丝一泪垂雨。\n絮里，又送金铜去。\n漫肠断、王孙望帝，呕心囊句。\n市隐今成趣。\n袖回地狭，天吴凤舞。\n莫是青州谱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17512, '满庭芳', '刘辰翁', '千骑家山，一觞父老，前有韩魏公来。\n青原上巳，才见寿筵开。\n欧公云间还见，忆相州、更自迟回。\n公知否，福星分野，飞骑不须排。\n留春亭下草，雪霜过了，依旧春。\n待留春千岁，日醉千杯。\n却怕催归丹诏，栋明堂、须要雄材。\n趋朝去，西风便面，只手障浮埃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17513, '满庭芳', '刘辰翁', '空谷无花，新有酒，去年穷胜今年。\n蛩吟蛩和，且省费蛮笺。\n闻说先生去也，江南岸、缚草为船。\n依然在，山栖寒食，路断却归廛。\n老人，三又两，清风作供，晴日生烟。\n但高高杜宇，不办行缠。\n几度披衣教我，二升内、煮石烧铅。\n休重道，玉龙无孔，夜夜叫穿天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17514, '木兰花慢', '刘辰翁', '午桥清夜饮，花露重、烛光寒。\n约处处行歌，朝朝买酒，典却朝衫。\n尊前自堪一醉，但落红、枝上不堪安。\n归去柳阴行月，酒醒画角声残。\n王宫。\n难得似君闲。\n闲我见君难。\n记李陌看花，光阴冉冉，风雨番番。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17515, '木兰花慢', '刘辰翁', '自崆峒麦熟，耕犊满、桔槔闲。\n笑吾党清谈，长衣具，更进贤冠。\n仓皇庇公宇下，便秋风、江上不惊寒。\n雪夜入三城易，槐阴护一家难。\n东山。\n零雨几时还。\n领客竹林间。\n看满座空尊，轻裘缓带，绿鬓朱颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17516, '永遇乐', '刘辰翁', '璧月初晴，黛云远澹，春事谁主。\n禁苑娇寒，湖堤倦暖，前度遽如许。\n香尘暗陌，华灯明昼，长是懒携手去。\n谁知道，断烟禁夜，满城似愁风雨。\n宣和旧日，临安南渡，芳景犹自如故。\n缃帙流离，风鬟三五，能赋词最苦。\n江南无路，州今夜，此苦又谁知否。\n空相对，残无寐，满村社鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17517, '永遇乐', '刘辰翁', '灯舫华星，崖山碇口，官军围处。\n璧月辉圆，银花焰短，春事遽如许。\n麟洲清浅，鳌山流播，愁似汨罗夜雨。\n还知道，良辰美景，当时邺下仙侣。\n而今无奈，元正元夕，把似月朝十五。\n小庙看灯，团街转鼓，总是添恻楚。\n传柑袖冷，吹藜漏尽，又见岁来岁去。\n空犹记，弓弯一句，似虞兮语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17518, '内家娇', '刘辰翁', '结客少年场。\n携高李、闻笛赋游梁。\n看汉水淮山，高楼共卧，融尊郑驿，飞盖相望。\n春风里，种他红与白，笑我懒中忙。\n供奉後来，玄都桃改，佳人好在，庾岭梅香。\n何处最难忘。\n会稽归鬓晚，空带吴霜。\n赢得黄冠野服，笑傲羲皇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17519, '六州歌头', '刘辰翁', '向来人道，真个胜周公。\n燕然眇。\n浯溪小。\n万世功。\n再建隆。\n十五年宇宙，宫中膺。\n堂中伴。\n翻虎鼠，搏雀，覆蛇龙。\n鹤发庞眉，憔悴空山久，来上东封。\n便一朝符瑞，四十万人同。\n说甚东风。\n怕西风。\n甚边尘起，渔阳惨。\n霓裳断。\n广寒宫。\n青楼杳。\n朱门悄。\n镜湖空。\n里湖通。\n大纛高牙去，人不见，港重重。\n斜阳外，芳草碧，落花红。\n抛尽黄金无计，方知道、前此和戎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17520, '六丑', '刘辰翁', '看东风海底，送落日、飞空如掷。\n醉游暮归，怕西州堕策。\n归路偏失。\n记上元时节，千门立马，望金坡残雪。\n素娥推下团栾辙。\n塞草惊尘，河水渡楫。\n悠悠雨丝风拂。\n但相随断雁，时度荒泽。\n回头紫陌。\n梦归归未得。\n憔悴江南，秋风旧客。\n去年说著今日。\n漫故人相命，玳筵鸣瑟。\n愁汗漫、全林杯窄。\n况飘泊相遇，当时老叟，梨园歌籍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17521, '百字令・念奴娇', '刘辰翁', '少微星小。\n抚剑气横空，隐见林杪。\n夜来宋都如雨，更长得奇哉皎。\n与汝三龄，览余初度，一语占先兆。\n暮年喜见，甲申聚五星照。\n堪叹亡国馀民，老人孺子，尔汝霜桥晓。\n骑马听鸡朝寂寞，梦入南枝三绕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17522, '百字令・念奴娇', '刘辰翁', '洞房停烛，似新岁，数到上元时节。\n一盏屠苏千岁酒，添得新人罗列。\n昨日迎长，今朝献寿，尝团团佳月。\n永和春好，用之不竭嘉客。\n见说海上归来，有如瓜大枣，无人分得。\n六十二三刘梦得，输与香山乐色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17523, '莺啼序', '刘辰翁', '匆匆何须惊觉，唤草庐人起。\n算成败利钝，非臣逆睹，至死後已。\n又何似、采桑八百，看蚕夜织小窗里。\n漫二升自苦，教人吊卧龙里。\n别有佳人，追桃恨李。\n拥凝香绣被。\n争知道、壮士悲歌，萧萧正度寒水。\n问荆卿、田横古墓，更谁载酒为君酹。\n过霜桥落月，老人不见遗履。\n置之勿道，逝者如斯，甚矣衰久矣。\n君其为吾归计，为耕计。\n但问某所泉甘，何乡鱼美。\n此生不愿多才艺。\n功名马上兜鍪出，莫书生、误尽了人间事。\n昔年种柳江潭，攀枝折条，噫嘻树犹如此。\n登高一笑，把菊东篱，且复聊尔耳。\n试回首、龙山路断，走马台荒，渭水秋风，沙河夜市。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17524, '莺啼序', '刘辰翁', '闷如愁红著雨，卷地吹不起。\n便故人渺渺，相逢前事，欲语还已。\n凝望久、荒城落日，五湖四海烟浪里。\n问而今何处，寄声旧时邻里。\n闲说那回，海上苏李。\n雪深夜如被。\n想携手、汉天不语，叫□不应疑水。\n待河梁、一尊落月，生非死别君如酹。\n望故人阁上，依稀长剑方履。\n古人已矣，垂名青史，谓当如此矣。\n又谁料浮沈，自得鱼计。\n赏心乐事，良辰美景，撞钟舞女，朱门大第。\n雕鞍骏马番装笠，笑虚名何与身前事。\n区区相望，饿死西山，悬目东门，人生何乐为此。\n古人已矣，天下英雄，使君与操耳。\n听喔喔、鸡鸣早起，屡舞徘徊，痛饮高楼，狂歌过市。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17525, '莺啼序', '刘辰翁', '愁人更堪秋日，长似岁难度。\n相携去、晚登高，高极正犯愁处。\n常是恨、古人无计，看今人痴绝如许。\n但东篱半醉，残灯自修菊谱。\n归去来兮，怨调又苦。\n有寒余赋。\n湖山外、风笛阑干，胡床夜月谁据。\n恨当时、青云跌宕，天路断、险艰如许。\n便桥边，卖镜重圆，断肠无数。\n是谁玉斧，惊堕团团，失上界楼宇。\n甚天误、婵娟余误。\n悔却初念，不合梦他，霓裳楚楚。\n而今安在，枫林关塞，回头忆著神仙处，漫断魂飞过湖江去。\n时时说与，地上群儿，青琐瑶台，阆风悬圃。\n琵琶往往，凭鞍劝酒，千载能胡语。\n叹自古、宫花薄命，汉月无情，战地难青，故人成土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17526, '沁园春', '刘辰翁', '六十一翁，垂银带鱼，插四角轮。\n把百个今朝，重排花甲，十年前事，似臼齑辛。\n骰选功名，酒中富贵，管取当筵满劝旬。\n槐知道，待二郎做甚，父子封申。\n便应际会昌辰。\n怕林下相逢未是真。\n看焚芰裂荷，起锺山笑，卖田僦马，堕贡生贫。\n後六十年，有无穷事，是宰官身是报身。\n年来好，莫做他宰相，便是全人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17527, '沁园春', '刘辰翁', '刘子生时，当月下弦，输大半轮。\n记孤馆望云，朝饥讽午，寒炉拥雪，岁晚盘辛。\n比似先生，两壬相望，岂止参差一二旬。\n明年好，算乞浆得酒，酉胜如申。\n吾辰。\n定是雌辰。\n听穷鬼揶揄数得真。\n但鹤唳华亭，贵何似贱，珠沈金谷，富不如贫。\n明月清风，晴春暖日，出入千重云水身。\n吾老矣，叹臣之少也，已不如人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17528, '沁园春', '刘辰翁', '成佛生天，自是两途，任祖生先。\n看二三大老，依稀吾榜，几多新进，小少齐年。\n紫陌相逢，青山独往，倚杖鹤鸣听布泉。\n百年里，但儿时难得，老後依然。\n吾牛已不耕田。\n更雨滑泥深自在鞭。\n叹十年波浪，悠悠何补，三生石上，种种无缘。\n白发来呵，朱颜去也，一曲狂歌落酒边。\n谁似我，似官奴出籍，散圣安禅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17529, '沁园春', '刘辰翁', '十八年间，黄公垆下，崔九堂前。\n叹人生何似，飘花陌上，妾身难托，卖镜桥边。\n隔幔云深，绕梁声彻，不负杨枝旧日传。\n主人好，但留髡一石，空恼彭宣。\n不因浩叹明年。\n也不为青衫怆四筵。\n念故人何在，旧游如梦，清风明月，野草荒田。\n俯仰无情，高歌有恨，四壁萧条久绝弦。\n秋江晚，但一声河满，我自潸然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17530, '沁园春', '刘辰翁', '九日黄花，渊明之後，谁当汝俦。\n记龙山昨夜，寒泉九井，帽轻似叶，须戟如虬。\n庾扇西风，孔林落照，银海横波十二楼。\n闲笑道，那华亭上蔡，再见何由。\n人生似我何求。\n算惟有高人高处游。\n笑如今别驾，前时方外，尘埃半百，岁月如流。\n如此连墙，今年不见，一首犹胜万户侯。\n偷闲好，便明朝有约，莫莫休休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17531, '沁园春', '刘辰翁', '春汝归欤，风雨蔽江，烟尘暗天。\n况雁门厄塞，龙沙渺莽，东连吴会，西至秦川。\n芳草迷津，飞花拥道，小为蓬壶借百年。\n江南好，问夫君何事，不少留连。\n江南正是堪怜。\n但满眼杨花化白毡。\n看兔葵燕麦，华清宫里，蜂黄蝶粉，凝碧池边。\n我已无家，君归何里，中路徘徊七宝鞭。\n风回处，寄一声珍重，两地潸然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17532, '沁园春', '刘辰翁', '笑贡生狂，日日弹冠，西望王阳。\n待泥封屡下，蒲轮不至，卖琅琊产，办舍人装。\n厚绿故人，黄金有术，何不分伊肘後方。\n他年老，三千里外，八十思乡。\n何如吾寿华堂。\n在丞相东山旧第旁。\n任王人亲至，不妨高枕，吾州盛事，更短邻墙。\n我学希夷，邀公共坐，游戏壶中日月长。\n山僧道，成仙未晚，救火须忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17533, '法驾导引', '刘辰翁', '棠阴日，棠阴日，清美近花朝。\n共喜治中持福笔，春当霄汉布宽条。\n兰蕙雪初销。\n和气满，和气满，生意到渔樵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17534, '法驾导引', '刘辰翁', '蟠桃熟，蟠桃熟，一熟一千年。\n比似相公正年少，朱颜绿鬓锦蝉连。\n肉色更光鲜。\n西江好，西江好，春雨碧黏天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17535, '法驾导引', '刘辰翁', '儿童喜，儿童喜，献寿摘仙桃。\n篁峒鸣狐成鬼火，花村买犊卖蛮刀。\n惟有使君劳。\n燕山桂，燕山桂，犹带窦家香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17536, '法驾导引', '刘辰翁', '金茎露，金茎露，绝胜九霞觞。\n碎菊花如玉屑，满盘和月咽风香。\n不老是丹方。\n六十七，六十七，七岁见端平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17537, '法驾导引', '刘辰翁', '春小小，春小小，梅见著些些。\n未必神仙无白发，依然林下有黄花。\n潭影浸流霞。\n冬十十，冬十十，亥字雁斜斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17538, '法驾导引', '刘辰翁', '臣尚少，臣尚少，少似此翁些。\n点半点斑今似雪，飞来飞去自如花。\n醉眼看红霞。\n人间事，人间事，倒杖柱颐斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17539, '法驾导引', '刘辰翁', '天正子，天正子，亥正较差些。\n床下玉灵头戴九，手中铜叶锦添花。\n乞汝作飞霞。\n辽东鹤，辽东鹤，无语鹤头斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17540, '法驾导引', '刘辰翁', '盘之水，盘之水，清可濯吾缨。\n我与盘山疏一月，黄花满意绕荒城。\n怀抱向谁倾。\n十之十，十之十，十十到千龄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17541, '法驾导引', '刘辰翁', '东风雨，东风雨，河汉洗蓬莱。\n只见丹山高万丈，不知古驿路傍埃。\n到海几时回。\n二月八，二月八，长见醉桃腮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17542, '法驾导引', '刘辰翁', '五月五，五月五，细雨绿菖蒲。\n早是高花开九节，花堪结子节堪扶。\n持此揆□初。\n长命缕，长命缕，儿女漫区区。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17543, '水调歌头', '刘辰翁', '鹤会正阳後，又为此公来。\n向时圯上，不似魁梧出尘埃。\n少日河东赋手，醉里新丰对草，谈笑上金台。\n太子少灵气，马客岂仙才。\n紫貂裘，骇犀剑，鹦鹉杯。\n龙涎沈水是浅，薄命有人猜。\n闻说老仙清健，想见风姿皓伟，天语快行催。\n凫舄看双去，槐第似亲栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17544, '水调歌头', '刘辰翁', '五五复五五，二八且重重。\n後天先甲如此，满月喜相逢。\n一日须倾三百，月小又输一日，不满九千锺。\n但愿客常满，莫问海尊空。\n赋长篇，赓短韵，剩谈丛。\n乱来风日自美，一橘两衰翁。\n几见东陵瓜好，又看西邻葵烂，半醉半醒中。\n偶得洞宾象，混混起相从。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17545, '水调歌头', '刘辰翁', '夫子惠收我，谓我古心徒。\n闲居有客无酒，有酒又无鱼。\n报道犀兵远坠，问讯陈人何似，陈似隔年萸。\n天壤亦大矣，知有孔融乎。\n白雪歌，丹元赞，赫蹄书。\n洪崖何自过我，便作授经图。\n教我天根骑月，规我扶摇去意，餐我白芝符。\n从此须溪里，更著赤松湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17546, '水调歌头', '刘辰翁', '先生岂我辈，造物乃其徒。\n荷衣自放林壑，亦未弃银鱼。\n留得东篱晚节，笑倒龙山秃帽，一醉插茱萸。\n天下有大老，携手盍归乎。\n别头经，三昼梦，一编书。\n向之麟者止矣，且看老溪图。\n历遍後天既未，依约明朝三五，乾体适当符。\n还以奉公寿，不是讲鹅湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17547, '水调歌头', '刘辰翁', '似似不常似，似我一生徒。\n画工自画龙种，忽近海飞鱼。\n大笑北宫称弟，遂使西河疑女，同气自椒萸。\n且谓杜公者，即是老君乎。\n日给华，芎本，薛羊书。\n马师真只这是，可是浮图。\n大小卢同马异，天下使君与操，但欠虎铜符。\n说甚左眼痣，已过洞庭湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17548, '水调歌头', '刘辰翁', '不成三五夜，不放霎时晴。\n长街灯火三两，到此眼方明。\n把似每时庭院，传说个般障子，无路与君行。\n推手复却手，都付断肠声。\n漏通晓，灯收市，人下棚。\n中山铁马何似，遗恨杳难平。\n一落掺挝声愤，再见大晟舞罢，乐事总伤情。\n便有尘随马，也任雨霖铃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17549, '水调歌头', '刘辰翁', '明月几万里，与子共中秋。\n古今良夜如此，寂寂几时留。\n何处胡笳三弄，尚有南楼馀兴，风起木飕飕。\n白石四山立，玉露下平洲。\n醉青州，歌赤壁，赋黄楼。\n人间安得十客，谭笑发中流。\n看取横江皓彩，犹似沈河白璧，光气彻天浮。\n举首快哉去，灯火见神州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17550, '水调歌头', '刘辰翁', '群动各已息，在汝梦中游。\n尘埃大地如水，儿女不堪愁。\n寂寂古人安在，冉冉吾年如此，何处有高楼。\n客有洞箫者，泪下不能收。\n庾楼坠，秦楼渺，楚楼休。\n知公所恨何事，不是为封侯。\n自有此山此月，说甚何年何处，重泛木兰舟。\n起舞酹英魄，馀愤海西流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17551, '水调歌头', '刘辰翁', '寂寂复寂寂，此月古时明。\n银河也变成陆，灰劫断槎横。\n历落英雄孺子，灭没龙光牛斗，胜败黯然平。\n玉笛叫空阔，终有故人情。\n雁南飞，乌绕树，鹤归城。\n问君有酒，何不鼓瑟更吹笙。\n我饮呜呜起舞，我舞白发，顾影可怜生。\n旧日中秋客，几处几回晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17552, '水调歌头', '刘辰翁', '此夕酹江月，犹记濯缨秋。\n濯缨又去如水，安得主人留。\n旧日登楼长笑，此日新亭对泣，秃鬓冷飕飕。\n木落下极浦，渔唱发中洲。\n芙蓉阙，鸳鸯阁，凤凰楼。\n夜深白露纷下，谁见湿萤流。\n自有此生有客，但恨有鱼无酒，不了一生浮。\n重省看潮去，今夕是杭州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17553, '水调歌头', '刘辰翁', '不饮强须饮，不饮奈何明。\n也曾劬秃当了，依旧滑如冰。\n一吸金波荡漾，再吸琼楼倾倒，吾杓亦长盈。\n试入壶中看，只似世间晴。\n饮连江，江连月，月连城。\n十年离合老矣，悲喜得无情。\n想见凄然北望，欲说明年何处，衣露为君零。\n同此大圆镜，握手认环瀛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17554, '水调歌头', '刘辰翁', '仙掌下驰道，清露滴芙蓉。\n无似酒初醒，身世笑颦中。\n万朵花灯夜宴，一叶扁舟海岛，寂寂五更风。\n误赏明妆靓，愁思满青铜。\n陂六六，三十六，渺何穷。\n江南曲曲烟雨，谁是醉施翁。\n但恨才情都老，无复风流曾梦，缥缈赋惊鸿。\n寄语清净社，小饮合相容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17555, '水调歌头', '刘辰翁', '不饮强须饮，今日是重阳。\n向来健者安在，世事两茫茫。\n叔子去人远矣，正复何关人事，堕泪忽成行。\n叔子泪自堕，烟没使人伤。\n燕何归，鸿欲断，蝶休忙。\n渊明自无可奈，冷眼菊花黄。\n看取龙山落日，又见骑台荒草，谁弱复谁强。\n酒亦何有好，暂醉得相忘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17556, '水调歌头', '刘辰翁', '山水无宿约，村暗自当还。\n不知有客乘兴，载我弄沧湾。\n酒吸明河欲尽，月落三星在下，未放水风闲。\n影转松起舞，扶步入林间。\n恨无人，横野笛，叫关山。\n知君慷慨何事，惜得米阳关。\n看取大江东去，把酒凄然北望，说著泪潺。\n我饮自须尽，君唱有何难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17557, '水调歌头', '刘辰翁', '两声深院里，歌扇小楼中。\n当时飞燕马上，妖艳为谁容。\n娇颤须扶未稳，腰袅轻笼小驻，玉女最愁峰。\n掠鬓过车骤，回首意冲冲。\n宝钗斜，云鬓乱，几曾逢。\n谁知去三步远，此痛与君同。\n玉箸残妆谁见，獭髓轻痕妙补，粉黛不须浓。\n重见为低诉，馀恨更匆匆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17558, '水调歌头', '刘辰翁', '未信仙都子，曾识老仙翁。\n卿卿少年去後，心与道人同。\n挥麈不须九锡，开阁苦无长物，闲日醉千锺。\n一笑欠伸起，儿戏大槐中。\n友彭聃，招园绮，傲乔松。\n年来多惯世事，莫莫恼司空。\n等得三朝好老，恰则而今虚左，梅信已先通。\n富贵正不免，从此学痴聋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17559, '水调歌头', '刘辰翁', '百千孙子子，八十老翁翁。\n人间天下清福，阅世苦难同。\n谁叹东门猎倦，谁笑南阳舞罢，万事五更钟。\n但愿人长久，聊复进杯中。\n故侯瓜，丞相柏，大夫松。\n诸公健者安在，春梦转头空。\n可笑先生无病，病在枕流漱石，福至自然通。\n聋者固多笑，一笑更治聋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17560, '水调歌头', '刘辰翁', '我有此客否，难作主人翁。\n小年自不相似，偶与大年同。\n见说东厢诸少，正拥家君胜会，二八舞歌钟。\n亦欲得公重，公在画堂中。\n笑青蒿，真小草，倚长松。\n典衣欲作汤饼，家酿愧瓶空。\n公有潭州百斛，公有秫田二顷，贺客万钱通。\n小大不相似，但可似公聋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17561, '水调歌头', '刘辰翁', '明月隔千里，风动帐纹开。\n故人锦字如梦，梦转雁初来。\n倚遍西山朝爽，行过石头旧渡，久别忽经怀。\n不得与之语，日夕独持杯。\n调绿水，歌白雪，有心哉。\n也知尻高啄俯，无计脱尘埃。\n狗尾貂蝉满座，贝带弄粉，一舆一臣台。\n岁晚不如愿，谁更忿灰堆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17562, '水调歌头', '刘辰翁', '落日半亭榭，山影没壶中。\n苍然欲不可极，迢递未归鸿。\n锦织家人何在，春寄故人不到，寂寞听疏钟。\n木末见江去，无雪著渔翁。\n词舂容，歌慷慨，语玲珑。\n岁云暮矣相见，明日是东风。\n远想使君台上，携手与人同乐，中夜说元龙。\n世事无足语，且看烛花红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17563, '水调歌头', '刘辰翁', '不见古时月，何似汉时秋。\n朱陈村里新样，新妇又骑牛。\n欲脱参前氐後，又说河边河鼓，此会没来由。\n何处设瓜果，香动帻沟窭。\n郭郎老，谁为理，岂情流。\n人间□睡五日，五日复何悠。\n吾腹空虚久矣，子有满堂锦绣，犊鼻若为酬。\n玉友此时好，空负葛巾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17564, '水调歌头', '刘辰翁', '天地有中气，第一是中元。\n新秋七七，月出河汉斗牛间。\n正是使君初度，如见中州河岳，绿鬓又朱颜。\n茎露一杯酒，清彻瑞人寰。\n大暑退，潢潦净，彩云斑。\n三壬三甲厚重，屹不动如山。\n从此五风十雨，自可三年一日，香寝镇狮蛮。\n起舞愿公寿，未可愿公还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17565, '水调歌头', '刘辰翁', '夜看二星度，高会列群英。\n苍颜白发乌帽，风入古槐清。\n客有羽衣来者，仍是寻常百姓，坐觉孟公惊。\n且勿多酌我，未压我狂醒。\n金瓯启，银信喜，衮衣新。\n向来淮浙草木，隐隐有馀声。\n闻说井阑沙语，感念石壕村事，倾耳发惊霆。\n举酒奉公寿，天意厚苍生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17566, '水调歌头', '刘辰翁', '造物反乎覆，白首困耆英。\n吟风赏月石上，一笑再河清。\n一百八盘道路，二十四桥歌舞，身世梦堪惊。\n独酌未能醉，已醉蓦然醒。\n别与老，惊相见，几回新。\n来时燕栖未稳，满耳又蝉声。\n闲忆钱塘江上，两点青山欲白，血石起鞭霆。\n此事复安在，相对说平生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17567, '金缕曲・贺新郎', '刘辰翁', '晓殿龙光起。\n御香浓、新诗写就，云飞相第。\n一自骑箕承帝赉，千载君臣鱼水。\n端不负、当年弧矢。\n赤壁周郎神游处，料羞看、故垒斜阳里。\n今共看，更无比。\n尊前若说平生事。\n叹长江、几番风浪，几人胆碎。\n数载太平丰年瑞。\n三百年间又几。\n想皇揆、初心应喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17568, '金缕曲・贺新郎', '刘辰翁', '秋老寒香圃。\n自春来、桔槔闲了，去天尺五。\n陌上踏歌来何暮，收得黄云如土。\n但稽首、福星初度。\n不是使君人间佛，甚今朝、欲雨今朝雨。\n持寿酒，为公舞。\n虎头画手谁甚许。\n写天人、方瞳红颊，共宾笑语。\n卫戟连营三千士，簇簇满城箫鼓。\n早恐是、留公不住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17569, '金缕曲・贺新郎', '刘辰翁', '春入番江雨。\n满湖山、莺啼燕雨，前歌後舞。\n闻道行骢行且止，却听谯楼更鼓。\n正未卜，阴晴同否。\n老子胸中高小范，这精神、堪更开封府。\n新治足，旧民苦。\n扁舟浩荡乘风去。\n看莱衣、思贤堂上，寿觞朝举。\n六十二三前度者，敢望香山老傅。\n又过了、午年端午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17570, '金缕曲・贺新郎', '刘辰翁', '我误留公住。\n看人间、犹是重阳，满城风雨。\n父老堂阴携孺子，记得元宵歌舞。\n但稽首、乌乌无语。\n我有桓筝千年恨，为谢公、目送还云抚。\n公不乐，尚何苦。\n吾侬心事凭谁诉。\n有谁知、闭户穷愁，欲从之去。\n闻道明朝生申也，满酌一杯螺浦。\n又知复、明年何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17571, '金缕曲・贺新郎', '刘辰翁', '忘却来时路。\n恨苍苍、寒冰弃我，江南闲处。\n世事早知今如此，何不老农老圃。\n更种个、梅花深住。\n冻雨前朝浯溪石，对苍苔、堕泪怜臣甫。\n山似我，两眉聚。\n岁云暮矣如何度。\n但多情、寂寥相念，二三君子。\n越石暮年扶风赋，犹解闻鸡起舞。\n恨不减、二三十岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17572, '金缕曲・贺新郎', '刘辰翁', '昨醉君家酒。\n从今十万八千场，未疏老友。\n人道水仙标格俊，不许梅花殿後。\n但赢得、一年年瘦。\n迤逦聚星楼上雪，待天风、浩荡重携手。\n酌君酒，献君寿。\n年前春入燕台柳。\n看联翩、四辈金鞭，长楸承受。\n岂有中朝瓯覆久，更落闽山海口。\n端自有、玉堂金斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17573, '金缕曲・贺新郎', '刘辰翁', '七十三年矣。\n记小人、四百四十，五番甲子。\n看到蓬莱水清浅，休说树犹日如此。\n但梦梦、昨非今是。\n一曲尊前离鸾操，抚铜仙、清泪如铅水。\n歌未断，我先醉。\n新来画得耆英似。\n似灞桥、风雪吟肩，水仙梅弟。\n里巷依稀灵光在，飞过劫灰如洗。\n笑少伴、乌衣馀几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17574, '金缕曲・贺新郎', '刘辰翁', '拍瓮春醅动。\n洞庭霜、压绿堆黄，林苞堪贡。\n况有老人潭边菊，摇落赏心入梦。\n数百岁、半来许中。\n儿女牵衣团栾处，绕公公、愿献生申颂。\n公性，待重风。\n人生一笑何时重。\n奈今朝、有客无鱼，有鱼留冻。\n何似尊前斑斓起，低唱浅斟齐奉。\n也不待、烹龙凤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17575, '金缕曲・贺新郎', '刘辰翁', '绝北寒声动。\n渺黄昏、叶满长安，云迷章贡。\n最苦周公千年後，正与莽新同梦。\n五十国、纷纷入中。\n摇都人歌坞，问何如、昨日菘高颂。\n胪九锡，竟谁风。\n当初共道擎天重。\n奈天教、垓下风寒，滹沱兵冻。\n寂寞放翁南园记，带得园柑进奉。\n怅回首、何人修凤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17576, '金缕曲・贺新郎', '刘辰翁', '吾鬓如霜蕊。\n自江南、西风尘起，倒骑秃尾。\n旧日汾阳中书令，何限门生儿子。\n到今也、陆沈草昧。\n醉里不行西州路，但斗间、看望成龙气。\n聊寂寞，自相慰。\n夫君自是人间瑞。\n叹生儿、当如异日，孙仲谋耳。\n健笔风云蛟龙起，人物山川形势。\n犹有封、狼居胥意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17577, '金缕曲・贺新郎', '刘辰翁', '何处从头说。\n但倾尊、淋漓醉墨，疏疏密密。\n看取两轮东西者，也是樊笼中物。\n这光景、年来都别。\n白发道人隆中像，笑相逢、对拥炉边雪。\n又过了，上元节。\n纸窗旋补寒穿穴。\n柳黏窗、青青过雨，劝君休折。\n睡不成酣酒先醒，花底东风又别。\n夜复夜、吟魂飞越。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17578, '金缕曲・贺新郎', '刘辰翁', '岁事峥嵘甚。\n是当年、爆竹驱傩，插金幡胜。\n忽晓阑街儿童语，不为上元灯近。\n但笑拣、梅簪公鬓。\n莫恨青青如今白，愿年年、语取东君信。\n巾未堕，笑重整。\n他年不信东风冷。\n鼓连天、银烛花光，柳芽催迸。\n漫说沈香亭羯鼓，自著锦袍吟凭。\n待吹彻、玉箫人醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17579, '金缕曲・贺新郎', '刘辰翁', '叶叶跳珠雨。\n里湖通、十里红香，画桡齐举。\n昨梦天风高黄鹄，下俯人间何许。\n但动地、潮声如鼓。\n竹阁楼台青青草，问木棉、羁客魂归否。\n盘泣露，寺钟语。\n梦回酷似灵均苦。\n叹神游、前度都非，明朝重五。\n满眼离骚无人赋，忘却君愁吊古。\n任醉里、乌乌缕缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17580, '金缕曲・贺新郎', '刘辰翁', '襟泪涔涔雨。\n料骚魂、水解千年，依然轻举。\n还看吴儿胥涛上，高出浪花几许。\n绝倒是、东南旗鼓。\n风雨蛟龙争何事，问彩丝、香粽犹存否。\n溪女伴，采莲语。\n古人不似今人苦。\n漫追谈、少日风流，三三五五。\n谁似鄱阳鸱夷者，相望怀沙终古。\n待唤醒、重听金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17581, '金缕曲・贺新郎', '刘辰翁', '锦岸吴船鼓。\n问沙鸥、当日沈湘，是何端午。\n长恨青青朱门艾，结束腰身似虎。\n空泪落、婵媛女。\n我醉招累清醒否，算平生、清又醒还误。\n累笑我，醉中语。\n黄头舞棹临江处。\n向人间、独竞南风，叫云激楚。\n笑倒两崖人如蚁，不管颓波千屡。\n忽惊抱、汨罗无柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17582, '金缕曲・贺新郎', '刘辰翁', '破帽吹愁去。\n绕郊墟、残灰败壁，冷烟斜雨。\n舞马梦惊城乌起，散作童妖灶语。\n漫说与、谢仙一句。\n犹记醉归西州路，问行人、望望骊烽误。\n几未失，丧公屦。\n高高况是兴亡处。\n望平沙、落日湖光，暗淮沈楚。\n寂寞西陵歌又舞，疑冢嵯峨新土。\n黯牛笛、参差归路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17583, '金缕曲・贺新郎', '刘辰翁', '风雨东篱晚。\n渺人间、南北东西，平芜烟远。\n旧日携壶吹帽处，一色沈冥何限。\n天不遣、魂销肠断。\n不是苦无看山分，料青山、也自羞人面。\n秋後瘦，老来倦。\n惊回昨梦青山转。\n恨一林、金粟都空，静无人见。\n默默黄花明朝有，只待插花寻伴。\n又谁笑、今朝蝶怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17584, '金缕曲・贺新郎', '刘辰翁', '与客携壶去。\n望高高、半山失却，满城风雨。\n何许白衣人邂逅，小立东篱共语。\n未怪是、催租断句。\n寂寞午鸡啼三四，悄老人、桥上前期误。\n卿且去，整吾屦。\n寒空旧是题诗处。\n莽云烟、缠蛟舞凤，东吴西楚。\n千古新亭英雄梦，泪湿神州块土。\n叹落日、鸿沟无路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17585, '金缕曲・贺新郎', '刘辰翁', '携手登高赋。\n望前山、山色如烟，烟光如雨。\n少日凭阑峰南北，谁料美人迟暮。\n漫回首、残基冷绪。\n长恨中原无人问，到而今、总是经行处。\n书易就，雁难付。\n斜阳日日长亭路。\n倚秋风、洞庭一剑，故人何许。\n寂寞柴桑塞花外，还有白衣来否。\n但哨遍、长歌归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17586, '金缕曲・贺新郎', '刘辰翁', '问何年种植。\n独成蹊、花烂漫，锦开千步。\n花下老人犹记我，不似那回赏处。\n并吹却、道边谢墅。\n黄四娘家今何在，也飘零、偎向前村住。\n千万恨，寄红雨。\n携壶藉草行歌暮。\n记前宵、深盟止酒，况堪扶路。\n破手一杯花浮面，不觉二三四五。\n更竹里、颠狂崔护。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17587, '金缕曲・贺新郎', '刘辰翁', '少日都门路。\n听长亭、青山落日，不如归去。\n十八年间来往断，白首人间今古。\n又惊绝、五更一句。\n道是流离蜀天子，甚当初、一似吴儿语。\n臣再拜，泪如雨。\n画堂客馆真无数。\n记画桥、黄竹歌声，桃花前度。\n风雨断魂苏季子，春梦家山何处。\n谁不愿、封侯万户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17588, '金缕曲・贺新郎', '刘辰翁', '一笑披衣起。\n笑昨宵、东风似梦，韩张卢李。\n白发红云溪上叟，不记儿孙年齿。\n但回首、秦亡汉驶。\n苦苦渔郎留不住，约扁舟、後日重来此。\n吾已老，尚能俟。\n少年未解留人意。\n恍出山、红尘吹断，落花流水。\n天上玉堂人间改，漫乃声千里。\n更说似、玄都君子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17589, '金缕曲・贺新郎', '刘辰翁', '灯共墙檠语。\n记昨朝、芒鞋蓑笠，冷风斜雨。\n月入宫槐槐影澹，化作槐花无数。\n恍不记、鳌头压处。\n不恨扬州吾不梦，恨梦中、不醉琼花露。\n空耿耿，吊终古。\n千蜂万蝶春为主。\n怅何人、老忆江南，北朝开府。\n看取当年风景在，不待花奴催鼓。\n且未说、春丁分俎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17590, '摸鱼儿', '刘辰翁', '渐无多、诗朋酒伴，东林复几人许。\n旧时船子西湖柳，词与东风尘土。\n重记否。\n那月月下旬，且避何人疏。\n当朝自负。\n甚堕髻愁眉，滕短後，一往似伧父。\n当年事，伤心说庾开府。\n人生无百年虑。\n虎头燕颔人间肉，不是蜜翁翁做。\n今又古。\n是楚对凡亡，为是凡亡楚。\n朝朝暮暮。\n听画角楼头，呜咽未断，重数五更鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17591, '摸鱼儿', '刘辰翁', '记玄都、看花君子，一生恨奈何许。\n青云紫陌悠悠者，几个玉人成土。\n今在否。\n但四海九州，屈指从头疏。\n吾年空负。\n看射虎南山，遭逢醉尉，何须饮田父。\n神清梦，也是堂堂欧府。\n此中无破头虑。\n种槐不隔鞭蛆恶，更祝二郎儿做。\n苍苍古。\n漫年又一年，老却南公楚。\n池塘春暮。\n笑步步鸣蛙，看成两部，正似未忘鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17592, '摸鱼儿', '刘辰翁', '三百年、人间天上，遽如许、遽如许。\n落花寒食东风雨，漠漠长陵土。\n魂归否。\n怕些不分明，又堕人笺疏。\n且无相负。\n记昔与诸贤，共谈洛下，曾识老人父。\n牛衣泪，冷落闻鸡东府。\n风尘曾独深虑。\n子规声断长门晓，春梦不堪重做。\n千万古。\n但目极心伤，宛转虞兮楚。\n江东日暮。\n想野草荒田，而今何处，不待雍门鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17593, '摸鱼儿', '刘辰翁', '道醉乡、无边无岸，一尊到彼殊径。\n是间转海人知处，尺地不教渠剩。\n尊亦瘿。\n问一斗消酲，一石犹难信。\n临风小等。\n记我友醒狂，相从有意，中路恨羌永。\n梅花晚，早已雪堆余鬓。\n此花宁复风韵。\n空寒独倚天为主，天又几时曾定。\n今为晋。\n看秦女山中，绿发垂垂顶。\n百年一瞬。\n叹高卧北窗，闲过五十，无说答形影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17594, '摸鱼儿', '刘辰翁', '记歌头、辛壬癸甲，乌乌能知谁晓。\n梅花不待元宵好，雪月交光独照。\n愁未老。\n更老似渠□，冷面迎相笑。\n君词定峭。\n但减十年前，偎桃傍李，肯独为梅好。\n山中好。\n可但一枝春早。\n道边无限花草。\n米嘉荣共何戡在，还忆永新娇小。\n明年了。\n又唤起流莺，又自愁鹃叫。\n东皇太昊。\n更不是琼花，香无半点，一笑使人倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17595, '摸鱼儿', '刘辰翁', '懒能看、海桑世界，风花过眼如传。\n月明昨夜庭流水，天色朝来都变。\n尘石烂。\n铢衣坏，和衣减尽谁能怨。\n秦亡楚倦。\n但翦烛西窗，秋声入竹，点点已如霰。\n当年事，本是泗亭沛县。\n却教绵成殿。\n暮年八阵那曾用，付与江流石转。\n前楚辩。\n今哨遍，是乌乌者灯前劝。\n乾坤较健。\n叹君已归休，吾方俯仰，种种未曾见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17596, '摸鱼儿', '刘辰翁', '渺斜阳、村烟酒市，独教王谢如此。\n渔翁梦入江头絮，寂寂平安西子。\n东风起。\n东风起。\n种桃千树皆流水。\n桥边万里。\n甚老子情锺，明朝後日，又洒送春泪。\n春过雨，历历远山如洗。\n暮云堪共谁倚。\n诸贤洛下风流散，轻薄纷纷馀几。\n聊尔尔。\n问世事。\n何如自嗅残花蕊。\n金铜剑履。\n但陌上相逢，摩挲一笑，铸此几时矣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17597, '摸鱼儿', '刘辰翁', '又非他、今年晴少，海棠也恁空过。\n清羸欲与花同梦，不似蝶深深卧。\n春怜我。\n我又自、怜伊不见侬赓和。\n已无可奈。\n但愁满清漳，君归何处，无泪与君堕。\n春去也，尚欲留春可可。\n问公一醉能颇。\n锺情剩有词千首，待写大招招些。\n休阿那。\n阿那看、荒荒得似江南麽。\n老夫婆娑。\n问篱下闲花，残红有在，容我更簪朵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17598, '摸鱼儿', '刘辰翁', '是他家、绛唇翠袖，可容卿有功否。\n相思不到胭脂井，只隔东林烟柳。\n春去又。\n漫一夜东风，吹得花成旧。\n无人举酒。\n但照影堤流，图他红泪，飘洒到襟袖。\n人间事，大半归谋诸妇。\n不如意十八九。\n敲门夜半窥园李，赤脚玉川惊走。\n何处有。\n更炙烛风流，看到人归後。\n休休回首。\n笑旧日园林，巢蜀锦，处处可携手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17599, '摸鱼儿', '刘辰翁', '怎知他、春归何处，相逢且尽尊酒。\n少年袅袅天涯恨，长结西湖烟柳。\n休回首。\n但细雨断桥，憔悴人归後。\n东风似旧。\n问前度桃花，刘郎能记，花复认郎否。\n君且住，草草留君翦韭。\n前宵更恁时候。\n深杯欲共歌声滑，翻湿春衫半袖。\n空眉皱。\n看白发尊前，已似人人有。\n临分把手。\n叹一笑论文，清狂顾曲，此会几时又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17600, '摸鱼儿', '刘辰翁', '正何须、阳关肠断，吴姬苦劝人酒。\n中年怀抱萦萦处，看取伴烟和柳。\n柳摇首。\n笑飞到家山，已是酴後。\n留连话旧。\n问溪上儿童，颇曾见我，有此故人否。\n相逢地，还忆今宵三韭。\n青山知了迎候。\n东风自送归帆去，吹得乱红沾袖。\n暮云皱。\n听杜宇高高，啼向无何有。\n江花垂手。\n任春色重来，江花更好，难可少年又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17601, '摸鱼儿', '刘辰翁', '待欲□、家山未得，方知名不如酒。\n丹砂便做金句漏，难遣鬓青似柳。\n试搔首。\n记移竹南塘，又是三年後。\n情怀非旧。\n叹少日相如，垆边老去，能赋上林否。\n种兰处，赢得青青种韭。\n渊明中路相候。\n何须更待三三径，也自长拖衫袖。\n青袍皱。\n便持当金貂，赊取邻家有。\n小儿拍手。\n笑昨醉如泥，盟言止酒，何事醒来又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17602, '摸鱼儿', '刘辰翁', '更比他、东风前度，依然一榻如许。\n深深旧是谁家府，落日画梁燕语。\n帘半雨。\n记湖海平生，相遇忘宾主。\n阑珊春暮。\n看城郭参差，长空澹澹，沙鸟自来去。\n江山好，立马白云飞处。\n秦川终是吾土。\n登临笑傲西山笏，烟树高高杜宇。\n君且住。\n况双井泉甘，汲遍茶堪煮。\n歌残金缕。\n恰黄鹤飞来，月明三弄，仍是岳阳吕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17603, '摸鱼儿', '刘辰翁', '是疑他、春来倏忽，是疑岁别人去。\n古今守岁言无说，长是酒阑情绪。\n堪恨处。\n曾亲见都人，户户银花树。\n星河未曙。\n听朝马笼街，火城簇仗，御笔已题露。\n人间事，空忆桃符旧句。\n三茅钟自朝暮。\n严城夜禁故如鬼，况敢凭陵大呼。\n冬冬鼓。\n但画角声残，已是新人故。\n休思前度。\n叹五十加三，明朝领取，闲看五星聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17604, '摸鱼儿', '刘辰翁', '醒复醒、行吟泽畔，焉能忍此终古。\n招魂过海枫林暝，招得魂归无处。\n朝又暮。\n但依旧，禁街人静冬冬鼓。\n画船沈雨。\n听乃渔歌，兴亡事远，咽咽未能句。\n君且住。\n能歌吾不如汝。\n悠悠鼓而去。\n沧洲揽结芳成艾，唤作张三李五。\n羌自苦。\n更闲却，玉堂端帖多多许。\n无人自语。\n把画扇鸾边，香罗雪底，题作午年午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17605, '摸鱼儿', '刘辰翁', '想幼安、辽东归後，自羞年少龙首。\n长安市上垆边卧，枉却快行家走。\n空两袖。\n染醉墨淋漓，把似天香透。\n功名邂逅。\n便六一词高，君谟字伟，但见说行昼。\n人间事，苦似成丹无候。\n神清苔字如镂。\n明年六十闻歌後，颇记薄醺醺否。\n儿拍手。\n笑马上葛疆，也作家山友。\n烦伊起寿。\n更待复一中，毋多酌我，疏影共三嗅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17606, '摸鱼儿', '刘辰翁', '也何须、晴如那日，欣然且过江去。\n玄都纵有看花便，耿耿自羞前度。\n堪恨处。\n人道是，漫山先落坡翁句。\n东风绮语。\n但适意当前，来寻须赋，此土亦吾圃。\n海山石，犹记芙蓉城主。\n弹过飞种成土。\n是间便作仙客杏，谁与一栽千树。\n朝又暮。\n怅二十五年，临路花如故。\n人生自苦。\n只唤渡观桃，侵寻至此，世事奈何许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17607, '摸鱼儿', '刘辰翁', '醉与君、狂歌又笑，不知当日何调。\n孤山梅下吟魂冷，说甚那时苏小。\n沧波眇。\n奈此岛，累累竟是谁家表。\n归欤白鸟。\n看四圣飘香，朱门金榜，化作竺飞峤。\n衰也久，旧游梦翠禽绕。\n兮轧、皎兮窈。\n相思一夜窗前白，谁识余怀渺渺。\n残年了。\n听画角，悲凉又是霜天晓。\n馀音杳缈。\n叹五十之年，我加八九，君隔几科诏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17608, '摸鱼儿', '刘辰翁', '是耶非、吾年如此，更痴更悔今昨。\n狂吟近日疏于酒，转似秋山瘦削。\n浑未觉。\n恁儿子门生，前度登高弱。\n情怀又恶。\n叹亲友中年，不堪离别，况复久零落。\n长生乐。\n有分神仙难学。\n人生聊复行乐。\n百年半梦随流水，半在南枝北萼。\n妾命薄。\n但寂寞黄昏，时听城楼角。\n愁无可著。\n且取醉尊前，明朝休问，昨日已忘却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17609, '摸鱼儿', '刘辰翁', '对尊前、簪花骑竹，老胡起起能舞。\n春风浩荡天涯去，惟有薰吟自语。\n槐正午。\n看万户蜂脾，帘幕双双乳。\n娇儿呆女。\n漫学得琵琶，依稀马上，总是主恩处。\n凌烟像，空倚临风玉树。\n升沈事遽如许。\n刘郎贯是瑶池客，又醉碧桃三度。\n花下数。\n记三度三千，结子多红雨。\n年年五五。\n共准拟阶庭，钗符献酒，袅袅缀双虎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17610, '摸鱼儿', '刘辰翁', '待借留、几曾留得，来鸿空怨秋老。\n至今父老依依恨，犹说李将军好。\n东门草。\n早不为东风，遮却长安道。\n馀民如槁。\n愿金印重来，洪都开府，定复几时到。\n秋江鹭，尤记当年潦倒。\n沧洲无复华皓。\n朝饥堕泪荒田雨，洗忆窝蜂败扫。\n天能报。\n看凤烛亭亭，玉树宽人抱。\n风霜善保。\n但逢驿寄书，无书寄语，要说趋朝早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17611, '金缕曲・贺新郎', '刘辰翁', '世事如何说。\n似举鞍、回头笑问，并州儿葛。\n手障尘埃黄花路，千里龙沙如雪。\n著破帽、萧萧馀发。\n行过故人柴桑里，抚长松、老倒山间月。\n聊共舞，命相瑟。\n春风五老多年别。\n看使君、神交意气，依然晚合。\n袖有玉龙提携去，满眼黄金台骨。\n说不尽、古人痴绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17612, '意难忘', '刘辰翁', '角动寒谯。\n看雨中灯市，雪意潇潇。\n星球明戏马，歌管杂鸣刁。\n泥没膝，舞停腰。\n焰蜡任风销。\n更可怜、红啼桃槛，绿暗杨桥。\n当年乐事朝朝。\n曾锦鞍呼妓，金屋藏娇。\n围香春斗酒，坐月夜吹箫。\n今老矣，倦歌谣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17613, '大', '刘辰翁', '任琐窗深、重帘闭，春寒知有人处。\n常年笑花信，问东风情性，是娇是妒。\n冰柳成须，吹桃欲削，知更海堂堪否。\n相将燕归又，看香泥半雪，欲归还误。\n漫低回芳草，依稀寒食，朱门封絮。\n少年惯羁旅。\n乱山断，树唤船渡。\n正暗想、鸡声落月，梅影孤屏，更梦衾、千重似雾。\n相如倦游去。\n掩四壁、凄其春暮。\n休回首、都门路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17614, '谒金门', '刘辰翁', '风又雨。\n春事自无多许。\n欲待柳花团作絮。\n柳花冰未吐。\n翠袖不禁春误。\n沈却绿烟红雾。\n将谓花寒留得住，一晴春又暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17615, '临江仙', '刘辰翁', '过眼纷纷遥集，来归往往羝儿。\n草间塞口裤间啼。\n提携都不是，何似未生时。\n城上胡笳自怨，楼头画角休吹。\n谁人不动故乡思。\n江南秋尚可，塞外草先衰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17616, '水调歌头', '刘辰翁', '坐久语寂寞，泉响忽翻空。\n不知龙者为雨，雨者为成龙。\n看取交流万壑，不数飞来千丈，高屋总淙淙。\n是事等恶剧，裂石敢争雄。\n敲铿訇，扪滑仄，藉蒙茸。\n苍浪向来半掩，厚意复谁容。\n欲说正元旧事，未必玄都千树，得似洞中红。\n檐语亦颠倒，洗尔不平胸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17617, '绮寮怨', '刘辰翁', '漫道十年前事，闷怀天又阴。\n何须恨、典了西湖，更笑君、宴罢琼林。\n闲时数声啼鸟，凄然似、上阳宫女心。\n记断桥、急管危弦，歌声远，玉树金缕沈。\n看万年枝上禽。\n徊徨落月，断肠理绝弦琴。\n魂梦追寻。\n挥泪赋白头吟。\n当年未知行乐，无日夜、望乡音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17618, '失调名', '吴蒙庵', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17619, '醉太平', '颜奎', '茶边水经。\n琴边鹤经。\n小窗甲子初晴。\n报梅花小春。\n小冠晋人。\n小车洛人。\n醉扶儿子门生。\n指黄河解清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17620, '清平乐', '颜奎', '留君少住。\n且待晴时去。\n夜深水鹤云间语。\n明日棠梨花雨。\n尊前不尽馀情。\n都上鸣弦细声。\n二十四番风後，绿阴芳草长亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17621, '归平遥・归国遥', '颜奎', '春□□拂拂。\n檐花双燕入。\n少年湖上风日。\n问天何处觅。\n湖山画屏晴碧。\n梦华知夙昔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17622, '浣溪沙', '颜奎', '梦泊游丝画影移。\n水沈香宛紫烟微。\n玉笙才过画楼西。\n天上人间花事苦，镜中翠压四山低。\n又成春过据莺啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17623, '菩萨蛮', '颜奎', '燕姬越女初相见。\n鬓云翻覆随风转。\n日日转如云。\n朝朝白发新。\n江南古佳丽。\n只绾年时髻，信手绾将成。\n从来懒学人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17624, '忆秦娥', '颜奎', '水云幽。\n怕黄霜竹生新愁。\n生新愁。\n如今何处，倚月明楼。\n龙吟杳杳天悠悠。\n腾蛟起舞鸣箜篌。\n鸣箜篌。\n听吹短气，江上无秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17625, '大', '颜奎', '唱古荼シ，新荷叶，谁向重帘深处。\n东风三十六，向园林都过，馀寒犹妒。\n公子狐裘，佳人翠袖，怎见此时情否。\n天上知音杳，怪参差律吕，世间多误。\n记画扇题诗，单衣试酒，梦归泥絮。\n嗟春如逆旅。\n送无路、远涉前无渡。\n回首住、凌波亭馆，待月楼台，满身花气凝香雾。\n度入南薰去。\n留燕伴、不教迟暮。\n但一点、芳心苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17626, '摸鱼儿', '颜奎', '对琴台、不堪尘，春风微露纤指。\n峥嵘鹤膝翘空势，取次著花安蕊。\n偏有意。\n把竹外一枝，飞洒轻烟里。\n月痕如洗。\n又底事丹青，何须水墨，虚白阚清。\n华堂暮，珍重休弹麈尾。\n静中留此佳致。\n桥西几度香浮处，回首都随流水。\n闲徙倚。\n叹汨没黄埃，变幻皆如此。\n蜚廉莫起。\n待别有神人，风斤一运，和影上窗纸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17627, '木兰花慢', '尹济翁', '渺渺怀芳意，苦对景、可怜生。\n记燕外莺边，柳深竹嫩，度密穿青。\n如今淡烟细雨，正午窗半梦酒初醒。\n乐事怎堪重省，起来一饷愁萦。\n悠然又把酒壶倾。\n摆不动离情。\n想闲却春游，绿阴深院，芳草长亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17628, '玉蝴蝶', '尹济翁', '几许暮春清思，未知芍药，先拟荼蘼。\n老却东风，春去不与人期。\n似情多、何曾荀倩，便梦断、不为崔徽。\n且衔杯。\n暖风袭袭，淡日晖晖。\n怎知。\n怀芳心在，树花露泣，叶竹烟啼。\n满目青红，新愁成阵恨成围。\n画帘空、龙媒独倚，午阴静、燕子双飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17629, '声声慢', '尹济翁', '雕鞍芳径，翠管长亭，春酲不负妍华。\n几丈闲愁，寄风吹落天涯。\n深深小帘朱户，是何人、重整香车。\n愁未醒，记竹西歌吹，柳下人家。\n眉锁何曾舒展，看行人都是，醉眼横斜。\n寄语高阳，从今休唤流霞。\n残春又能几许，但相从、评水观茶。\n清梦远，怕东风、犹在杏花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17630, '风入松', '尹济翁', '曾闻几度说京华。\n愁压帽檐斜。\n朝衣熨贴天香在，如今但、弹指兰。\n不是柴桑心远，等闲过了元嘉。\n长生休说枣如瓜。\n壶日自无涯。\n河倾南纪明奎璧，长教见、寿气成霞。\n但得重携溪上，年年人共梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17631, '一萼红', '尹济翁', '玉搔头。\n是何人敲折，应为节秦讴。\n几朱弦，剪灯雪藕，几回数尽更筹。\n草草又、一番春梦，梦觉了、风雨楚江秋。\n却恨闲身，不如鸿雁，飞过妆楼。\n又是山枯水瘦，叹回肠难贮，万斛新愁。\n懒复能歌，那堪对酒，物华冉冉都休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17632, '诉衷情', '郑楷', '酒旗摇曳柳花天。\n莺语软於绵。\n碎绿未盈芳沼，倒影蘸秋千。\n奁玉燕，套金蝉。\n负华年。\n试问归期，是酴後，是牡丹前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17633, '谒金门', '赵淇', '吟望直。\n春在阑干咫尺。\n山插玉壶花倒立。\n雪明天混碧。\n晓露丝丝琼滴。\n虚揭一帘云湿。\n犹有残梅黄半壁。\n香随流水急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17634, '绮罗香', '张磐', '浦月窥檐，松泉漱枕，屏里吴山何处。\n暗粉疏红，依旧为谁匀注。\n都负了、燕约莺期，更闲却、柳烟花雨。\n纵十分、春到邮亭，赋怀应是断肠句。\n青青原上荠麦，还被东风无赖，翻成离绪。\n望极天西，惟有陇云江树。\n斜照带、一缕新愁，尽分付、暮潮归去。\n步闲阶、待卜心期，落花空细数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17635, '浣溪纱・浣溪沙', '张磐', '习习轻风破海棠。\n秋千移影上回廊。\n昼长蝴蝶为谁忙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17636, '唐多令', '张林', '金勒花骢。\n故山云雾中。\n翠苹洲、先有西风。\n可惜嫩凉时枕簟，都付与、旧山翁。\n双翠合眉峰。\n泪华分脸红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17637, '柳梢青', '张林', '白玉枝头，忽看蓓蕾，金粟珠垂。\n半颗安榴，一枝杏，五色蔷薇。\n何须羯鼓声催。\n银里、春工四时。\n却笑灯蛾，学他蝴蝶，照影频飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17638, '江城子', '曹良史', '夜香烧了夜寒生。\n掩银屏。\n理银筝。\n一曲春风，都是断肠声。\n杜宇欲啼杨柳外，愁似海，思如云。\n背灯暗卸乳鹅裙。\n酒初酲。\n梦初醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17639, '柳梢青', '赵与仁', '露冷仙梯。\n霓裳散舞，记取人归。\n月度层霄，雨连深夜，谁管花飞。\n金铺满地苔衣。\n似一片、斜阳未移。\n生怕清香，又随凉信，吹过东篱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17640, '相思引', '赵与仁', '冰箔纱帘小院清。\n晴尘不动地花平。\n昨宵风雨，凉到木樨屏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17641, '西江月', '赵与仁', '夜半河痕依约，雨馀天气冥。\n起行微月遍池东。\n水影浮花、花影动帘栊。\n量减难追醉白，恨长莫尽题红。\n雁声能到画楼中。\n也要玉人、知道有秋风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17642, '清平乐', '赵与仁', '柳丝摇露。\n不绾兰舟住。\n人宿溪桥知那处。\n一夜风声千树。\n晓楼望断天涯。\n过鸿影落寒沙。\n可惜些儿秋意，等闲过了黄花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17643, '好事近', '赵与仁', '春色醉酴，昼永篆烟初绝。\n临水杨花千树，尽一时飞雪。\n穿帘度竹弄轻盈，东风老犹劣。\n睡起凭栏无绪，听几声啼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17644, '乌夜啼', '陈逢辰', '月痕未到朱扉。\n送郎时。\n暗里一汪儿泪、没人知。\n不住。\n收不聚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17645, '西江月', '陈逢辰', '杨柳雪融滞雨，酴玉软欺风。\n飞英簌簌扣调栊。\n残蝶归来粉重。\n罨画扇题尘掩，绣花纱带寒笼。\n送春先自费啼红。\n更结疏云秋梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17646, '菩萨蛮', '史介翁', '柳丝轻黄金缕。\n织成一片沙窗雨。\n斗合做春愁。\n困慵熏玉篝。\n暮寒罗袖薄。\n社雨催花落。\n先自为诗忙。\n蔷薇一阵香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17647, '谒金门', '何光大', '天似水。\n池上藕花风起。\n隔岸垂杨青到地。\n乱萤飞又止。\n露湿玉阑闲倚。\n人静自生凉意。\n泛碧沈朱供晚醉。\n月斜才去睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17648, '霓裳中序第一', '应法孙', '愁云翠万叠。\n露柳残蝉空抱叶。\n帘卷流苏宝结。\n乍庭户嫩凉，阑干微月。\n玉纤胜雪。\n委素纨、尘锁香箧。\n思前事、莺期燕约，寂寞向谁说。\n悲切。\n漏签声咽。\n渐寒、兰缸未灭。\n良宵长是闲别。\n恨酒凝红绡，纷瑶。\n镜盟鸾影缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17649, '贺新郎', '应法孙', '宿雾楼台湿。\n晓清初、花明柳润，燕飞莺集。\n旧约重来歌舞地，留得艳香娇色。\n又梦草、东风吹碧。\n午困腾腾春欲醉，对文楸、玉子无心拾。\n看蝶舞，傍花立。\n酒痕未醒愁先入。\n记年时、翠楼寒浅，宝笙慵吸。\n想驻马河桥分别，恨轻竹风帆烟笠。\n早尘暗、华堂帘隙。\n倚尽黄昏人独自，望江南回雁归云急。\n凭付与，锦笺墨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17650, '高阳台', '王亿之', '双桨敲冰，低篷护冷，扁舟晓渡西泠。\n回首吴山，微茫遥带重城。\n堤边几树垂杨柳，早嫩黄、摇动春情。\n问孤鸿，何处飞来，共唤飘零。\n轻帆初落沙洲暝，渐潮痕雨渍，面色风皴。\n旅思羁愁，偏能老大行人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17651, '高阳台', '王茂孙', '迟日烘晴，轻烟缕昼，琐窗雕户慵开。\n人独春闲，金猊暖透兰煤。\n山屏缓倚珊瑚畔，任翠阴、移过瑶阶。\n悄无声，彩翅翩翩，何处飞来。\n片时千里江南路，被东风误引，还近阳台。\n腻雨娇云，多情恰喜徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17652, '点绛唇', '王茂孙', '折断烟痕，翠蓬初离鸳鸯浦。\n玉纤相妒。\n翻被专房误。\n乍脱青衣，犹著轻罗护。\n多情处。\n芳心一缕。\n都为相思苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17653, '真珠帘', '朱孙', '春云做冷春知未。\n春愁在、碎雨敲花声里。\n海燕已寻踪，到画溪沙际。\n院落秋千杨柳外。\n待天气、十分晴霁。\n春市。\n又青帘巷陌，红芳歌吹。\n须这处处东风，又何妨对此，笼香觅醉。\n曲尽索馀情，奈夜航催离。\n梦满冰衾身似寄。\n算几度、吴乡烟水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17654, '新荷叶', '郑斗焕', '乳鸭池塘，晴波漾绿鳞鳞。\n宿藕根香，夏来生意还新。\n蚨钱小、钿花贴翠，相间萍星。\n一番雨过，一番暗展圆青。\n鱼戏龟游，看来犹未胜情。\n因忆年时，垂钓曾约轻盈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17655, '市桥柳', '蜀中妓', '欲寄意、浑无所有。\n折尽市桥官柳。\n看君著上征衫，又相将，放船楚江口。\n後会不知何日又。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17656, '小重山', '周容', '谢了梅花恨不禁。\n小楼羞独倚，暮云平。\n夕阳微放柳梢明。\n东风冷，眉岫翠寒生。\n无限远山青。\n重重遮不断，旧离情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17657, '祝英台近', '张涅', '一番风，连夜雨。\n收拾做春暮。\n艳冷香销，莺燕惨无语。\n晓来绿水桥边，青门陌上，不忍见、落红无数。\n怎分付。\n独倚红药栏边，伤春甚情绪。\n若取留春，欲去去何处。\n也知春亦多情，依依欲住。\n子规道、不如归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17658, '木兰花慢', '周密', '恰芳菲梦醒，漾残月、转湘帘。\n正翠崦收钟，彤墀放仗，台榭轻烟。\n东园。\n夜游乍散，听金壶、逗晓歇花签。\n宫柳微开露眼，小莺寂妒春眠。\n冰奁。\n黛浅红鲜。\n临晓鉴、竞晨妍。\n怕误却佳期，宿妆旋整，忙上雕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17659, '木兰花慢', '周密', '碧霄澄暮霭，引琼驾、碾秋光。\n看翠阕风高，珠楼夜午，谁捣玄霜。\n沧茫。\n玉田万顷，趁仙查、咫尺接天潢。\n彷佛凌波步影，露浓佩冷衣凉。\n明。\n净洗新妆。\n随皓彩、过西厢。\n正雾衣香润，云鬟绀湿，私语相将。\n鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17660, '木兰花慢', '周密', '觅梅花信息，拥吟袖、暮鞭寒。\n自放鹤人归，月香水影，诗冷孤山。\n等闲。\n寒暖，看融城、御水到人间。\n瓦陇竹根更好，柳边小驻游鞍。\n琅。\n半倚云湾。\n孤棹晚、载诗还。\n是醉魂醒处，画桥第二，奁月初三。\n东阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17661, '木兰花慢', '周密', '塔轮分断雨，倒霞影、漾新晴。\n看满鉴春红，轻桡占岸，叠鼓收声。\n帘旌。\n半钩待燕，料香浓、径远趱蜂程。\n芳陌人扶醉玉，路旁懒拾遗簪。\n郊。\n未厌游情。\n云暮合、谩消凝。\n想罢歌停舞，烟花露柳，都付栖莺。\n重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17662, '木兰花慢', '周密', '软尘飞不到，过微雨、锦机张。\n正荫绿池幽，交枝径窄，临水追凉。\n宫妆。\n盖罗障暑，泛青苹、乱舞五云裳。\n迷眼红绡绛彩，翠深偷见鸳鸯。\n湖光。\n两岸潇湘。\n风荐爽、扇摇香。\n算恼人偏是，萦丝露藕，连理秋房。\n涉江。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17663, '木兰花慢', '周密', '六桥春浪暖，涨桃雨、鳜初肥。\n正短棹轻蓑，牵筒荇带，萦网莼丝。\n依稀。\n岸红溯远，漾仙舟、误入武陵溪。\n何处金刀脍玉，画船傍柳频催。\n芳堤。\n渐满斜晖。\n舟叶乱、浪花飞。\n听暮榔声合，鸥沈暗渚，鹭起烟矶。\n忘机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17664, '木兰花慢', '周密', '疏钟敲暝色，正远树、绿。\n看渡水僧归，投林鸟聚，烟冷秋屏。\n孤云。\n渐沈雁影，尚残箫、倦鼓别游人。\n宫柳栖鸦未稳，露梢已挂疏星。\n重城。\n禁鼓催更。\n罗袖怯、暮寒轻。\n想绮疏空掩，鸾绡翳锦，鱼钥收银。\n兰灯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17665, '木兰花慢', '周密', '晴空摇翠浪，昼禽静、霁烟收。\n听暗柳啼莺，新簧弄巧，如度秦讴。\n谁。\n翠丝万缕，金梭、宛转织芳愁。\n风袅馀音甚处，絮花三月宫沟。\n扁舟。\n缆系轻柔。\n沙路远、倦追游。\n望断桥斜日，蛮腰竞舞，苏小墙头。\n偏忧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17666, '木兰花慢', '周密', '游船人散後，正蟾影、印寒湫。\n看冷沁鲛眠，清宜兔浴，皓彩轻浮。\n扁舟。\n泛天镜里，溯流光、澄碧浸明眸。\n栖鹭空惊碧草，素鳞远避金钩。\n临流。\n万象涵秋。\n怀渺渺、水悠悠。\n念汉皋遗佩，湘波步袜，空想仙游。\n风收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17667, '木兰花慢', '周密', '碧尖相对处，向烟外、挹遥岑。\n记舞鹫啼猿，天香桂子，曾去幽寻。\n轻阴。\n易晴易雨，看南峰、淡日北峰云。\n双塔秋擎露冷，乱钟晓送霜清。\n登临。\n望眼增明。\n沙路白、海门青。\n正地幽天迥，水鸣山籁，风奏松琴。\n虚楹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17668, '失调名', '周密', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17669, '浪淘沙', '周密', '新雨洗晴空。\n碧浅眉峰。\n翠楼西畔画桥东。\n柳线嫩黄才半染，眼眼东风。\n绣户掩芙蓉。\n帐减香筒。\n远烟轻霭弄春容。\n雁雁又归莺未到，谁寄愁红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17670, '浣溪沙', '周密', '几点红香入玉壶。\n几枝红影上金铺。\n昼长人困斗樗。\n花径日迟蜂课蜜，杏梁风软燕调雏。\n荼シ开了有春无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17671, '浣溪沙', '周密', '波影摇花碎锦铺。\n竹风清泛玉扶疏。\n画屏纹枕小纱。\n合色麝囊分翠绣，夹罗萤扇缕金书。\n十分凉意淡妆梳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17672, '浣溪沙', '周密', '浅色初栽试暖衣。\n画帘斜日看花飞。\n柳摇蛾绿妒春眉。\n象局懒拈双陆子，宝弦愁按十三徽。\n试凭新燕问归期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17673, '东风第一枝', '周密', '草梦初回，柳眠未起，新阴才试花讯。\n雏鸳迎晓偎香，小蝶舞晴弄影。\n飞梭庭院，早已觉、日迟人静。\n画帘轻、不隔春寒，旋减酒红香晕。\n吟欲就、远烟催暝。\n人欲醉、晚风吹醒。\n瘦肌羞怯金宽，笑靥暖融粉沁。\n珠歌缓引。\n更巧试、杏妆梅鬓。\n怕等闲、虚度芳期，老却翠娇红嫩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17674, '楚宫春・楚宫春慢', '周密', '香迎晓白。\n看烟佩霞绡，弄妆金谷。\n倦倚画阑，无语情深娇足。\n云拥瑶房翠暖，绣帐卷、东风倾国。\n半捻愁红，念旧游、凝伫兰翘，瑞鸾低舞庭绿。\n犹想沈香亭北。\n人醉里，芳笔曾题新曲。\n自翦露痕，移取春归华屋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17675, '大圣乐', '周密', '娇绿迷云，倦红颦晓，嫩晴芳树。\n渐午阴、帘影移香，燕语梦回，千点碧桃吹雨。\n冷落锦宫人归後，记前度兰桡停翠浦。\n凭栏久，谩凝想凤翘，慵听金缕。\n留春问谁最苦。\n奈花自无言莺自语。\n对画楼残照，东风吹远，天涯何许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17676, '三犯渡江云・渡江云', '周密', '冰溪空岁晚，苍茫雁影，浅水落寒沙。\n那回乘夜兴，云雪孤舟，曾访故人家。\n千林未绿，芳信暖、玉照霜华。\n共凭高，联诗唤酒，暝色夺昏鸦。\n堪嗟。\n澌鸣玉佩，山护云衣，又扁舟东下。\n想故园、天寒倚竹，袖薄笼纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17677, '露华', '周密', '暖消蕙雪，渐水纹漾锦，云淡波溶。\n岸香弄蕊，新枝轻袅条风。\n次第燕归将近，爱柳眉、桃靥烟浓。\n鸳径小，芳屏聚蝶，翠渚飘鸿。\n六桥旧情如梦，记扇底宫眉，花下游骢。\n选歌试舞，连宵恋醉珍丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17678, '桃源忆故人', '周密', '流苏静掩罗屏小。\n春梦苦无分晓。\n一缕旧情谁表。\n暗逐馀响袅。\n相思谩寄流红杳。\n人瘦花枝多少。\n郎马未归春老。\n空怨王孙草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17679, '糖多令・唐多令', '周密', '丝雨织莺梭。\n浮钱点细荷。\n燕风轻、庭宇正清和。\n苔面唾茸堆绣径，春去也、奈春何。\n宫柳老青娥。\n题红隔翠波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17680, '西江月', '周密', '波影暖浮玉，柳阴深锁金铺。\n湘桃花褪燕调雏。\n又是一番春暮。\n碧柱情深凤怨，云屏梦浅莺呼。\n绣窗人倦冷熏垆。\n帘影摇花亭午。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17681, '菩萨蛮', '周密', '霜风渐入龙香被。\n夜寒微涩宫壶水。\n滴滴是愁声。\n声声滴到明。\n梦魂随雁去。\n飞到颦眉处。\n雁已过西楼。\n又还和梦愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17682, '绣鸾凤花犯・花犯', '周密', '楚江湄，湘娥乍见，无言洒清泪。\n淡然春意。\n空独倚东风，芳思谁寄。\n凌波路冷秋无际。\n香云随步起。\n谩记得，汉宫仙掌，亭亭明月底。\n冰弦写怨更多情，骚人恨，枉赋芳兰幽芷。\n春思远，谁叹赏、国香风味。\n相将共、岁寒伴侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17683, '探春慢', '周密', '彩胜宜春，翠盘消夜，客里暗惊时候。\n翦燕心情，呼卢笑语，景物总成怀旧。\n愁鬓妒垂杨，怪稚眼、渐浓如豆。\n尽教宽尽春衫，毕竟为谁消瘦。\n梅浪半空如绣。\n便管领芳菲，忍孤诗酒。\n映烛占花，临窗卜镜，还念嫩寒宫袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17684, '瑶花慢', '周密', '朱钿宝。\n天上飞琼，比人间春别。\n江南江北，曾未见，谩拟梨云梅雪。\n淮山春晚，问谁识、芳心高洁。\n消几番、花落花开，老了玉关豪杰。\n金壶翦送琼枝，看一骑红尘，香度瑶阙。\n韶华正好，应自喜、初识长安蜂蝶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17685, '玉京秋', '周密', '烟水阔。\n高林弄残照，晚蜩凄切。\n碧砧度韵，银床飘叶。\n衣湿桐阴露冷，采凉花、时赋秋雪。\n叹轻别。\n一襟幽事，砌蛩能说。\n客思吟商还怯。\n怨歌长、琼壶暗缺。\n翠扇恩疏，红衣香褪，翻成消歇。\n玉骨西风，恨最恨、闲却新凉时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17686, '鹧鸪天', '周密', '燕子时时度翠帘。\n柳寒犹未褪香绵。\n落花门巷家家雨，新火楼台处处烟。\n情默默，恨恹恹。\n东风吹动画秋千。\n拆桐开尽莺声老，无奈春何只醉眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17687, '夜行船', '周密', '蛩老无声深夜静。\n新霜桀、一帘灯影。\n妒梦鸿高，烘愁月浅，萦乱恨丝难整。\n笙字娇娥谁为靓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17688, '采绿吟', '周密', '采绿鸳鸯浦，画舸水北云西。\n槐薰入扇，柳阴浮桨，花露侵诗。\n点尘飞不到，冰壶里、绀霞浅压玻璃。\n想明、凌波远，依依心事寄谁。\n移棹舣空明，苹风度、琼丝霜管清脆。\n咫尺挹幽香，怅岸隔红衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17689, '解语花', '周密', '晴丝蝶，暖蜜酣蜂，重檐卷春寂寂。\n雨萼烟梢，压阑干、花雨染衣红湿。\n金鞍误约，空极目、天涯草色。\n阆苑玉箫人去後，惟有莺知得。\n馀寒犹掩翠户，梁燕乍归，芳信未端的。\n浅薄东风，莫因循、轻把杏钿狼藉。\n尘侵锦瑟。\n残日绿窗春梦窄。\n睡起折花无意绪，斜倚秋千立。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17690, '曲游春', '周密', '楚苑东风外，暖丝情絮，春思如织。\n燕约莺期，恼芳情偏在，翠深红隙。\n漠漠香尘隔。\n沸十里、乱弦丛笛。\n看画船，尽入西泠，闲却半湖春色。\n柳陌。\n新烟凝碧。\n映帘底宫眉，堤上游勒。\n轻暝笼寒，怕梨云梦冷，杏香愁幂。\n歌管酬寒食。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17691, '大圣乐', '周密', '虹雨霉风，翠萦苹渚，锦翻葵径。\n正小亭、曲沼幽深，簟枕梦回，苔色槐阴清润。\n暗忆兰汤初洗玉，衬碧雾笼绡垂蕙领。\n轻妆了，袅凉花绛缕，香满鸾镜。\n人闲午迟漏永。\n看双燕将雏穿藻井。\n喜玉壶无暑，凉涵荷气，波摇帘影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17692, '桂枝香', '周密', '岩霏逗绿。\n又凉入小山，千树幽馥。\n仙影悬霜粲夜，楚宫六六。\n明霞洞珊瑚冷，对清商、吟思堪掬。\n麝痕微沁，蜂黄浅约，数枝秋足。\n别有雕阑翠屋。\n任满帽珠尘，拼醉香玉。\n瘦倚西风，谁见露侵肌粟。\n好秋能几花前笑，绕凉云、重唤银烛。\n宝瓶空晓，珍丛怨月，梦回金谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17693, '杏花天', '周密', '瑞云盘翠侵妆额。\n眉柳嫩、不禁愁积。\n返魂谁染东风笔。\n写出郢中春色。\n人去後、垂杨自碧。\n歌舞梦、欲寻无迹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17694, '杏花天', '周密', '汉宫乍出慵梳掠。\n关月冷、玉沙飞幕。\n龙香拨重春葱弱。\n一曲哀弦谩托。\n君恩厚、空怜命薄。\n青冢远、几番花落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17695, '南楼令・唐多令', '周密', '桂影满空庭。\n愁更廿五声。\n一声声、都是消凝。\n新雁旧蛩相应和。\n禁不过、冷清清。\n酒与梦俱醒。\n病因愁做成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17696, '南楼令・唐多令', '周密', '沈听西风。\n蛩阶月正中。\n弄秋声、金井孤桐。\n闲省十年吴下路，船几度、系江枫。\n辇路又迎逢。\n秋如归兴浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17697, '秋霁', '周密', '重到西冷，记芳园载酒，画船横笛。\n水曲芙蓉，渚边鸥鹭，依依似曾相识。\n年芳易失。\n段桥几换垂杨色。\n谩自惜。\n愁损庾郎，霜点鬓华白。\n残蛩露草，怨蝶寒花，转眼西风，又成陈迹。\n叹如今、才消量减，尊前孤负醉吟笔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17698, '齐天乐', '周密', '宫檐融暖晨妆懒。\n轻霞未匀酥脸。\n倚竹娇颦，临流瘦影，依约尊前重见。\n盈盈笑靥。\n映珠络玲珑，翠绡葱茜。\n梦入罗浮，满衣清露暗香染。\n东风千树易老，怕红颜旋减，芳意偷变。\n赠远天寒，吟香夜永，多少江南新怨。\n琼疏静掩。\n任翦雪栽云，竞夸轻艳。\n画角黄昏，梦随春共远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17699, '忆旧游', '周密', '念芳钿委路，粉浪翻空，谁补春痕。\n伫立伤心事，记宫檐点鬓，候馆沾襟。\n东君护香情薄，不管径云深。\n叹金谷楼危，避风台浅，消瘦飞琼。\n梨云已成梦，谩蝶恨凄凉，人怨黄昏。\n拈残枝重嗅，似徐娘虽老，犹有风情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17700, '一枝春', '周密', '碧淡春姿，柳眠醒、似怯朝来酥雨。\n芳程乍数。\n唤起探花情绪。\n东风尚浅，甚先有、翠娇红妩。\n应自把、罗绮围春，占得画屏春聚。\n留连绣丛深处。\n爱歌云袅袅，低随香缕。\n琼窗夜暖，试与细评新谱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17701, '一枝春', '周密', '帘影移阴，杏香寒、乍湿西园丝雨。\n芳期暗数。\n又是去年心绪。\n金花谩翦，倩谁画、旧时眉妩。\n空自想、杨柳风流，泪滴软绡红聚。\n罗窗那回歌处。\n叹庭花倦舞，香消衣缕。\n楼空燕冷，碎锦懒寻尘谱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17702, '点绛唇', '周密', '雪霁寒轻，兴来载酒移吟艇。\n玉田千顷。\n桥外诗情迥。\n重到孤山，往事何愁醒。\n东风紧。\n水边疏影。\n谁念梅花冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17703, '恋绣衾', '周密', '粉黄衣薄沾麝尘。\n作南华、春梦乍醒。\n活计一生花里，恨晓房、香露正深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17704, '江城子', '周密', '玉肌多病怯残春。\n瘦棱棱。\n睡腾腾。\n清楚衣裳，不受一尘侵。\n香冷翠屏春意靓，明月淡、晓风轻。\n楼中燕子梦中云。\n似多情。\n似无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17705, '绿盖舞风轻・绿尽舞风轻', '周密', '玉立照新妆，翠盖亭亭，凌波步秋绮。\n真色生香，明摇淡月，舞袖斜倚。\n耿耿芳心，奈千缕、情思萦系。\n恨开迟、不嫁东风，颦怨娇蕊。\n花底谩卜幽期，素手采珠房，粉艳初退。\n雨湿铅腮，碧云深、暗聚软绡清泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17706, '玲珑四犯', '周密', '波暖尘香，正嫩日轻阴，摇荡清昼。\n几日新晴，初展绮枰纹绣。\n年少忍负韶华，尽占断、艳歌芳酒。\n看翠帘、蝶舞蜂喧，催趁禁烟时候。\n杏腮红透梅钿皱。\n燕将归、海棠厮句。\n寻芳较晚，东风约、还在刘郎後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17707, '谒金门', '周密', '花不定。\n燕尾翦开红影。\n几点露香蜂赶趁。\n日迟帘幕静。\n试把翠蛾轻晕。\n愁满宝台鸾镜。\n屈指一春将次尽。\n归期犹未稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17708, '眼儿媚', '周密', '飞丝半湿惹归云。\n愁里又闻莺。\n淡月秋千，落花庭院，几度黄昏。\n十年一梦扬州路，空有少年心。\n不分不晓，恹恹默默，一段伤春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17709, '拜星月慢', '周密', '腻叶阴清，孤花香冷，迤逦芳洲春换。\n薄酒孤吟，怅相如游倦。\n想人在、絮幕香帘凝望，误忍几许，烟樯风幔。\n芳草天涯，负华堂双燕。\n记箫声、淡月梨花院。\n砑笺红、谩写东风怨。\n一夜落月啼鹃，唤四桥吟缆。\n荡归心、已过江南岸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17710, '好事近', '周密', '秋水浸芙蓉，清晓绮窗临镜。\n柳弱不胜愁重，染兰膏微沁。\n下阶笑折紫玫瑰，蜂蝶扑云鬓。\n回首见郎羞走，绣裙微褪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17711, '长亭怨慢', '周密', '记千竹、万荷深处。\n绿净池台，翠凉亭宇。\n醉墨题香，闲箫横玉尽吟趣。\n胜流星聚。\n知几诵、燕台句。\n零落碧云空，叹转眼、岁华如许。\n凝伫。\n望涓涓一水，梦到隔花窗户。\n十年旧事，尽消得、庾郎愁赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17712, '齐天乐', '周密', '东风又入江南岸，年年汉宫春早。\n宝屑无痕，生香有韵，消得何郎花恼。\n孤山梦绕。\n记路隔金沙，那回曾到。\n夜月相思，翠尊谁共饮清。\n天寒空念赠远，水边凭为问，春得多少。\n竹外凝情，墙阴照影，谁见嫣然一笑。\n吟香未了。\n怕玉管西楼，一声霜晓。\n花自多情，看花人自老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17713, '月边娇', '周密', '酥雨烘晴，早柳盼颦娇，兰芽愁醒。\n九街月淡，千门夜暖，十里宝光花影。\n尘凝步袜，送艳笑、争夸轻俊。\n笙箫迎晓，翠幕卷、天香宫粉。\n少年紫曲疏狂，絮花踪迹，夜蛾心性。\n戏丛围锦，灯帘转玉，拚却舞勾歌引。\n前欢谩省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17714, '宴清都', '周密', '老去闲情懒。\n东风外、菲菲花絮零乱。\n轻鸥涨绿，啼鹃暗碧，一春过半。\n寻芳已是来迟，怕迤逦、华年暗换。\n应怅恨、白雪歌空，秋霜鬓冷谁管。\n凭阑自笑清狂，事随花谢，愁与春远。\n持杯顾曲，登楼赋笔，杜郎才减。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17715, '梅花引', '周密', '瑶妃鸾影逗仙云。\n玉成痕。\n麝成尘。\n露冷鲛房，清泪霰珠零。\n步绕罗浮归路远，楚江晚，赋宫斜，招断魂。\n酒醒。\n梦醒。\n惹新恨。\n褪素妆，愁粉。\n翠禽夜冷。\n舞香恼、何逊多情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17716, '瑞鹤仙', '周密', '翠屏围昼锦。\n正柳织烟绡，花易春镜。\n层阑几回凭。\n看六桥莺晓，两堤鸥暝。\n晴岚隐隐。\n映金碧、楼台远近。\n谩曾夸、万幅丹青，画笔画应难尽。\n那更。\n波涵月彩，露莲妆，水描梅影。\n调朱弄粉，凭谁写，四时景。\n问玉奁西子，山眉波盼，多少浓施浅晕。\n算何如、付与吟翁，缓评细品。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17717, '倚风娇近', '周密', '云叶千重，麝尘轻染金缕。\n弄娇风软、霞绡舞。\n花国选倾城，暖玉倚银屏，绰约娉婷，浅素宫黄争妩。\n生怕春知，金屋藏娇深处。\n蜂蝶寻芳无据。\n醉眼迷花映红雾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17718, '祝英台近', '周密', '烛摇花，香袅穗，独自奈春冷。\n过了收灯，才始作花信。\n无端雨外馀酲，莺边残梦，又还动、惜芳心性。\n忍重省。\n几多绿意红情，吟笺倩谁整。\n香减春衫，老却旧荀令。\n小楼深闭东风，曲屏斜倚，知他是、为谁成病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17719, '浪淘沙', '周密', '芳草碧茸茸。\n染恨无穷。\n一春心事雨声中。\n窄索宫罗寒尚峭，闲倚熏笼。\n犹记粉阑东。\n同醉香丛。\n金鞍何处骤骅骢。\n袅袅绿窗残梦断，红杏东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17720, '浣溪沙', '周密', '不下竹帘怕燕。\n旋移芳槛引流莺。\n春光却早又中分。\n杏火无烟然绿暗，梨云如雪冷清明。\n冶游天气冶游心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17721, '浣溪沙', '周密', '丝雨笼烟织晚晴。\n睡馀春酒未全醒。\n翠钿轻脱隐香痕。\n生怕柳绵萦舞蝶，戏抛梅弹打啼莺。\n最难消遣是残春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17722, '齐天乐', '周密', '清溪数点芙蓉雨，苹飙泛凉吟。\n洗玉空明，浮珠沆瀣，人静籁沈波息。\n仙潢咫尺。\n想翠宇琼楼，有人相忆。\n天上人间，未知今夕是何夕。\n此生此夜此景，自仙翁去後，清致谁识。\n散发吟商，簪花弄水，谁伴凉宵横笛。\n流年暗惜。\n怕一夕西风，井梧吹碧。\n底事闲愁，醉歌浮大白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17723, '大', '周密', '又子规啼，荼シ谢，寂寂春阴池阁。\n罗窗人病酒，奈牡丹初放，晚风还恶。\n燕燕归迟，莺莺声懒，闲秋千红索。\n三分春过二，尚剩寒犹凝，翠衣香薄。\n傍鸳径鹦笼，一池萍碎，半檐花落。\n最怜春梦弱。\n楚台远、空负朝云约。\n谩念想、清歌锦瑟，翠管瑶尊，几回沈醉东园酌。\n燕麦兔葵恨，倩谁访、画阑红药。\n况多病、腰如削。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17724, '霓裳中序第一', '周密', '湘屏展翠叠。\n恨入宫沟流怨叶。\n冷金花暗结。\n又雁影带霜，蛩音凄月。\n珠宽腕雪。\n叹锦笺、芳宇盈箧。\n人何在，玉箫旧约，忍对素娥说。\n愁切。\n夜砧幽咽。\n任帐底、沈烟渐灭。\n红兰谁采赠别。\n洛汜分绡，汉浦遗。\n舞鸾光半缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17725, '过秦楼', '周密', '绀玉波宽，碧云亭小，苒苒水枫香细。\n鱼牵翠带，燕掠红衣，雨急万荷喧睡。\n临槛自采瑶房，铅粉沾襟，雪丝萦指。\n喜嘶蝉树远，盟鸥乡近，镜奁光里。\n帘户悄、竹色侵棋，槐影移漏，昼永簟花铺水。\n清眠乍足，晚浴初慵，瘦约楚裙尺二。\n曲砌虚庭夜深，月透龟纱，凉生蝉翅。\n看银潢泻露，金井啼鸦渐起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17726, '声声慢', '周密', '瑶台月冷，佩渚烟深，相逢共话凄凉。\n曳雪牵云，一般淡雅梳妆。\n樊姬岁寒旧约，喜玉儿、不负萧郎。\n临水镜，看清铅素靥，真态生香。\n长记湘皋春晓，仙路迥，冰钿翠带交相。\n满引台杯，休待怨笛吟商。\n凌波又归甚处，问兰昌、何似唐昌。\n春梦好，倩东风、留驻琐窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17727, '声声慢', '周密', '妆额黄轻，舞衣红浅，西风又到人间。\n小雨新霜，萍池藓径生寒。\n输它汉宫姊妹，粲星钿、霞佩珊珊。\n凉意早，正金盘露洁，翠盖香残。\n三十六宫秋好，看扶疏仙影，伴月长闲。\n宝络风流，何如细蕊堪餐。\n幽香未应便减，傲清霜、正自宜看。\n吟思远，负东篱、还赋小山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17728, '风入松', '周密', '柳梢烟软已璁珑。\n娇眼试东风。\n情思又逐青丝乱，剩寒轻、犹恋芳栊。\n笋玉新栽早燕，杏钿时引晴蜂。\n当时兰柱系花骢。\n人在小楼东。\n莺娇戏索迎春句，爱露笺、新染香红。\n未信闲情便懒，探花拚醉琼锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17729, '浪淘沙', '周密', '柳色淡如秋。\n蝶懒莺羞。\n十分春事九分休。\n开尽楝花寒尚在，怕上帘钩。\n京洛少年游。\n谁念淹留。\n东风吹雨过西楼。\n残梦宿酲相合就，一段新愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17730, '鹧鸪天', '周密', '相傍清明晴便悭。\n闭门空自惜花残。\n海棠半坼难禁雨，燕子初归不耐寒。\n金鸭冷，锦闲。\n银缸空照小屏山。\n翠罗袖薄东风峭，独倚西楼第几阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17731, '夜行船', '周密', '寒菊风栖小蝶。\n帘栊静、半规凉月。\n梦不分明，恨无凭据，肠断锦笺盈箧。\n哀角吹霜寒正怯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17732, '齐天乐', '周密', '曲屏遮断行云梦，西楼怕听疏雨。\n研冻凝华，香寒散雾，呵笔慵题新句。\n长安倦旅。\n叹衣染尘痕，镜添秋缕。\n过尽飞鸿，锦笺谁为寄愁去。\n箫台应是怨别，晓寒梳洗懒，依旧眉妩。\n酒滴垆香，花围坐暖，闲却珠鞲钿柱。\n芳心谩语。\n恨柳外游缰，系情何许。\n暗卜归期，细将梅蕊数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17733, '满庭芳', '周密', '玉沁唇脂，香迷眼缬，肉红初映仙裳。\n湘皋春冷，谁翦茜云香。\n疑是潘妃乍起，霞侵脸、微印宫妆。\n还疑是，寿阳凝醉，无语倚含章。\n绛绡，清泪冷，东风寄远，愁损红娘。\n笑李凡桃俗，蝶喜蜂忙。\n莫把杏花轻比，怕杏花、不敢承当。\n飘零处，还随流水，应去误刘郎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17734, '清平乐', '周密', '吹梅声噎。\n帘卷初弦月。\n一寸春霏消蕙雪。\n愁染垂杨带结。\n画桥平接金沙。\n软红浅隔儿家。\n燕子未归门掩，晚妆空对菱花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17735, '清平乐', '周密', '晚莺桥噎。\n庭户溶溶月。\n一树湘桃飞茜雪。\n红豆相思渐结。\n看看芳草平沙。\n游鞯犹未归家。\n自是萧郎飘荡，错教人恨杨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17736, '乳燕飞・贺新郎', '周密', '波影摇涟。\n趁熏风、一舸来时，翠阴清昼。\n去郭轩楹才数里，藓磴松关云岫。\n快屐齿、筇枝先後。\n空半危亭堪聚远，看洞庭、缥缈争奇秀。\n人自老，景如旧。\n来帆去棹还知否。\n问古今、几度斜阳，几番回首。\n晚色一川谁管领，都付雨荷烟柳。\n知我者、燕朋鸥友。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17737, '扫花游・扫地游', '周密', '柳花白，又火冷饧香，岁时荆楚。\n海棠似语。\n惜芳情燕掠，锦屏红舞。\n怕里流芳，暗水啼烟细雨。\n带愁去。\n叹寂寞东园，空想游处。\n幽梦曾暗许。\n奈草色迷云，送春无路。\n翠丸荐俎。\n掩清尊谩忆，舞蛮歌素。\n怨碧飘香，料得啼鹃更苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17738, '龙吟曲・水龙吟', '周密', '仙山非雾非烟，翠微缥缈楼台亚。\n江芜海树，晴光雨色，天开图画。\n两岸潮平，六桥烟霁，晚钩帘挂。\n自玄晖去後，云情雪意，丹青手、应难写。\n花底朝回多暇。\n倚高寒、有人潇洒。\n东山杖屦，西州宾客，笑谈风雅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17739, '风入松', '周密', '枇杷花老洞云深。\n流水泠泠。\n蓝田谁种玲珑玉，土华寒、晕碧云根。\n佳兴秋英春草，好音夜鹤朝禽。\n闲听天籁静看云。\n心境俱清。\n好风不负幽人意，送良宵、一枕松声。\n四友江湖泉石，二并钟鼎山林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17740, '凤栖梧・蝶恋花', '周密', '竹窈花深连别墅。\n曲曲回廊，小小闲庭宇。\n忽地香来无觅处。\n杖藜闲趁游蜂去。\n老桂悬秋森玉树。\n涧底孤芳，苒苒吹诗句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17741, '少年游', '周密', '松风兰露滴崖阴。\n瑶草入帘青。\n玉凤惊飞，翠蛟时舞，喷薄溅春云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17742, '西江月', '周密', '花气半侵云阁，柳阴近隔春城。\n画阑明月按瑶筝。\n醉倚满身芳影。\n翠格素虬晴雪，锦笼紫凤香云。\n东风吹玉满闲庭。\n二十四帘春靓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17743, '清平乐', '周密', '诗情画意。\n只在阑干外。\n雨露天低生爽气。\n一片吴山越水。\n宫烟醉柳春晴。\n海风洗月秋明。\n唤取九霞飞佩，夜凉跨鹤吹笙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17744, '朝中措', '周密', '桐阴薇影小阑干。\n昼永琐窗闲。\n当日清谭赌墅，风流犹记东山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17745, '闻鹊喜', '周密', '天水碧。\n染就一江秋色。\n鳌戴雪山龙起蛰。\n快风吹海立。\n数点烟鬟青滴。\n一杼霞绡红湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17746, '浣溪沙', '周密', '竹色苔香小院深。\n蒲团茶鼎掩山扃。\n松风吹尽世间尘。\n静养金芽文武火，时调玉轸短长清。\n石床闲卧看秋云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17747, '吴山青・长相思', '周密', '山青青。\n水泠泠。\n养得风烟数亩成。\n乾坤一草亭。\n云无心。\n竹无心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17748, '祝英台近', '周密', '步玲珑，寻窈窕，瑶草四时碧。\n小小蓬莱，花气透帘隙。\n几回翠水荷初，苍崖梅小，绮寮掩、玉壶春色。\n柳屏窄。\n芳槛日日东风，几醉几吟笔。\n曲折花房，莺燕似相识。\n最怜灯影才收，歌尘初静，画楼外、一声秋笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17749, '长相思', '周密', '灯辉辉。\n月微微。\n帐暖香深春漏迟。\n梦回闻子规。\n欲成诗。\n未成诗。\n生怕春归春又归。\n花飞花未飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17750, '清平乐', '周密', '小桥萦绿。\n密翠藏吟屋。\n千顷风烟森万玉。\n依约辋川韦曲。\n临流照影何人。\n悠然倚仗看云。\n柳色翠迷山色，泉声清和蝉声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17751, '清平乐', '周密', '锦城春晓。\n苑陌芳菲早。\n可是杜陵人未老。\n日日酒迷花恼。\n归鞯困倚芳酲。\n醒来还有新吟。\n人与杏花俱醉，春风一路闻莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17752, '清平乐', '周密', '静香真色。\n花与人争白。\n属玉双飞烟月夕。\n点波一奁秋碧。\n翠罗袖薄天寒。\n笛声何处关山。\n手拈一枝春色，东风怨入江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17753, '柳梢青', '周密', '约略春痕。\n吹香新句，照影清尊。\n洗尽时妆，效颦西子，不负东昏。\n金沙旧事休论。\n尽消得、东风返魂。\n一段真情，风前孤驿，雪後前村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17754, '柳梢青', '周密', '万雪千霜。\n禁持不过，玉雪生光。\n水部清多，杜郎老去，空恼愁肠。\n天寒野屿空廊。\n静倚竹、无人自香。\n一笑相逢，江南江北，竹屋山窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17755, '柳梢青', '周密', '映水穿篱。\n新霜微月，小蕊疏枝。\n几许风流，一声龙竹，半幅鹅溪。\n江头怅望多时。\n欲待折、相思寄伊。\n真色真香，丹青难写，今古无诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17756, '柳梢青', '周密', '夜鹤惊飞。\n香浮翠藓，玉点冰枝。\n古意高风，幽人空谷，静女深帏。\n芳心自有天知。\n任醉舞、花边帽。\n最爱孤山，雪初晴後，月未残时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17757, '南楼令・唐多令', '周密', '开了木芙蓉。\n一年秋已空。\n送新愁、千里孤鸿。\n摇落江蓠多少恨，吟不尽、楚云峰。\n往事夕阳红。\n故人江水东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17758, '南楼令・唐多令', '周密', '好梦不分明。\n楚云千万层。\n带围宽、愁损兰成。\n玉杵玄霜才咫尺，青羽信、便沈沈。\n水调夜楼清。\n清宵谁共听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17759, '声声慢', '周密', '橙香小院，桂冷闲庭，西风雁影涵秋。\n凤拨龙槽，新声小按梁州。\n莺吭夜深啭巧，凝凉云、应为歌留。\n慵顾曲，叹周郎老去，鬓改花羞。\n何事登临感慨，倩金蕉一洗，千古清愁。\n屡舞高歌，作成陶谢风流。\n人生最难一笑，拚尊前、醉倒方休。\n待醉也，带黄花、须带满头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17760, '明月引・江城梅花引', '周密', '舞红愁碧晚萧萧。\n溯回潮。\n伫仙桡。\n风露高寒，飞下紫霞箫。\n一雁远将千万恨，怀渺渺，翦愁云，风外飘。\n酒醒未醒香旋消。\n采江蓠，吟楚招。\n清徽芳笔，梅魂冷、月影空描。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17761, '明月引・江城梅花引', '周密', '雁霜苔雪冷飘萧。\n断魂潮。\n送清桡。\n翠袖珠楼，清夜梦琼箫。\n江南江北云自碧，人不见，泪花寒，随雨飘。\n愁多病多腰素消。\n倚清琴。\n调大招。\n江空年晚，凄凉句、远意难描。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17762, '六么令', '周密', '痴云翦叶，檐滴夜深悄。\n银城飞捷翠垅，占祥丰年报。\n白战清吟未了。\n寒鹊惊枝晓。\n鹤迷翠表。\n山阴今日，醉卧何人问安道。\n交映虚窗净沼。\n不许游尘到。\n谁念絮帽茸裘，叹幼安今老。\n玉鉴修眉未扫。\n白雪词新草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17763, '六么令', '周密', '回风带雨，冻涩漏声悄。\n小窗照影虚白，几误邻鸡报。\n千树天花绽了。\n鹄立通明晓。\n眼空八表。\n宫袍带月，醉里应迷灞陵道。\n风静琼林翠沼。\n片片随春到。\n吟鞯十里新堤，怪四山青老。\n玉唾珠尘怕扫。\n句冷池塘草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17764, '谒金门', '周密', '芳事晚。\n数点杏钿香浅。\n恻恻轻寒风翦翦。\n锦屏春梦远。\n稚柳拖烟娇软。\n花影暗藏深院。\n初试轻衫并画扇。\n牡丹红未展。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17765, '好事近', '周密', '轻翦楚台云，玉影半分秋月。\n一饷凄凉无语，对残花么蝶。\n碧天愁雁不成书，郎意似秋叶。\n闲展鸳绡残谱，卷泪花双叠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17766, '声声慢', '周密', '燕泥沾粉，鱼浪吹香，芳堤十里新晴。\n静惹游丝，花边袅袅扶春。\n多情最怜飘泊，记章台、曾绾青青。\n堪爱处，是扑帘娇软，随马轻盈。\n长是河桥三月，做一番晴雪，恼乱诗魂。\n带雨沾衣，罗襟点点离痕。\n休缀潘郎鬓影，怕绿窗、年少人惊。\n卷春去，翦东风、千缕碎云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17767, '忆旧游', '周密', '记花阴映烛，柳影飞梭，庭户东风。\n彩笔争春艳，任香迷舞袖，醉拥歌丛。\n画帘静掩芳昼，云翦玉璁珑。\n奈恨绝冰弦，尘消翠谱，别凤离鸿。\n莺笼。\n怨春远，但翠冷闲阶，坠粉飘红。\n事逐华年换，叹水流花谢，燕去楼空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17768, '水龙吟', '周密', '燕翎谁寄愁笺，天涯望极王孙草。\n新烟换柳，光风浮蕙，馀寒尚峭。\n倚仗看云，翦灯听雨，几番诗酒。\n叹长安倦客，江南旧恨，飞花乱、清明後。\n堤上垂杨风骤。\n散香绵、轻沾吟袖。\n麴尘两岸，纹波十里，暖蒸香透。\n海阔云深，水流春远，梦魂难句。\n问莺边按谱，花前觅句，解相思否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17769, '水龙吟', '周密', '舞红轻带愁飞，宝鞯暗忆章台路。\n吟香醉雨，吹箫门巷，飘梭院宇。\n立尽残阳，眼迷睛树，梦随风絮。\n叹江潭冷落，依依旧恨，人空老、柳如许。\n锦瑟华年暗度。\n赋行云、空题短句。\n情思系燕，么弦弹凤，文君更苦。\n烟水流红，暮山凝紫，是春归处。\n怅江南望远，苹花自采，寄将愁与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17770, '徵招', '周密', '江蓠摇落江枫冷，霜空雁程初到。\n万景正悲凉，奈曲终人杳。\n登临嗟老矣，问今古、清愁多少。\n一梦东园，十年心事，恍然惊觉。\n肠断，紫霞深，知音远、寂寂怨琴凄调。\n短发已无多，怕西风吹帽。\n黄花空自好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17771, '酹江月・念奴娇', '周密', '奁霏净洗，唤素娥睡起，平分秋色。\n雁背风高霜兔冷，露脚侵衣香湿。\n银浦流云，珠房迎晓，鬓影霜争白。\n玉尊良夜，与谁同醉瑶席。\n忍记倚桂分题，簪花筹酒，处处成陈迹。\n十二楼空环佩杳，惟有孤云知得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17772, '夜合花', '周密', '月地无尘，珠宫不夜，翠笼谁炼铅霜。\n南州路杳，仙子误入唐昌。\n零露滴，湿微妆。\n逗清芬、蝶梦空忙。\n梨花云暖，梅花雪冷，应妒秋芳。\n虚庭夜气偏凉。\n曾记幽丛采玉，素手相将。\n青蕤嫩萼，指痕犹映瑶房。\n风透幕，月侵床。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17773, '水龙吟', '周密', '素鸾飞下青冥，舞衣半惹凉云碎。\n蓝田种玉，绿房迎晓，一奁秋意。\n擎露盘深，忆君凉夜，暗倾铅水。\n想鸳鸯、正结梨云好梦，西风冷、还惊起。\n应是飞琼仙会。\n倚凉飙、碧簪斜坠。\n轻妆斗白，明照影，红衣羞避。\n霁月三更，粉云千点，静香十里。\n听湘弦奏彻，冰绡偷翦，聚相思泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17774, '天香', '周密', '碧脑浮冰，红薇染露，骊宫玉唾谁捣。\n麝月双心，凤云百和，宝钏佩环争巧。\n浓熏浅注，疑醉度、千花春晓。\n金饼著衣馀润，银叶透帘微袅。\n素被琼篝夜悄。\n酒初醒、翠屏深窈。\n一缕旧情，空趁断烟飞绕。\n罗袖馀香馨渐少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17775, '珍珠帘・真珠帘', '周密', '宝阶斜转春宵永，云屏敞、雾卷东风新霁。\n光动万星寒，曳冷云垂地。\n暗省连昌游冶事，照炫转、荧煌珠翠。\n难比。\n是鲛人织就，冰绡渍泪。\n独记梦入瑶台，正玲珑透月，琼钩十二。\n金缕逗浓香，接翠蓬云气。\n缟夜梨花生暖白，浸潋滟、一池春水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17776, '疏影', '周密', '冰条木叶。\n又横斜照水，一花初发。\n素壁秋屏，招得芳魂，彷佛玉容明灭。\n疏疏满地珊湖冷，全误却、扑花幽蝶。\n甚美人、忽到窗前，镜里好春难折。\n闲想孤山旧事，浸清漪、倒映千树残雪。\n暗里东风，可惯无情，搅碎一帘香月。\n轻妆谁写崔徽面，认隐约、烟绡重叠。\n记梦回，纸帐残灯，瘦倚数枝清绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17777, '齐天乐', '周密', '槐薰忽送清商怨，依稀正闻还歇。\n故苑愁深，危弦调苦，前梦蜕痕枯叶。\n伤情念别。\n是几度斜阳，几回残月。\n转眼西风，一襟幽恨向谁说。\n轻鬟犹记动影，翠娥应妒我，双鬓如雪。\n枝冷频移，叶疏犹抱，孤负好秋时节。\n凄凄切切。\n渐迤逦黄昏，砌蛩相接。\n露洗馀悲，暮烟声更咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17778, '满江红', '周密', '秋水涓涓，情渺渺、美人何许。\n还记得、东堂松桂，对床风雨。\n流水桃花西塞隐，茂林修竹山阴路。\n二十年、历历旧经行，空怀古。\n评砚品，临书谱。\n笺画史，修茶具。\n喜一愚天禀，一闲天赋。\n百战徵求千里马，十年三都赋。\n问何如、石鼎约弥明，同联句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17779, '玉漏迟', '周密', '老来欢意少。\n锦鲸仙去，紫霞声杳。\n怕展金奁，依旧故人怀抱。\n犹想乌丝醉墨，惊俊语、香红围绕。\n闲自笑。\n与君共是，承平年少。\n雨窗短梦难凭，是几番宫商，几番吟啸。\n泪眼东风，回首四桥烟草。\n载酒倦游甚处，已换却、花间啼鸟。\n春恨悄。\n天涯暮云残照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17780, '西江月', '周密', '万壑千岩剡曲，朝南暮北樵中。\n江潭杨柳几东风。\n犹忆当年手种。\n鬓雪愁侵秋绿，容华酒借春红。\n非非是是总成空。\n金谷兰亭同梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17781, '杏花天', '周密', '金池琼苑曾经醉。\n是多少、红情绿意。\n东风一枕游仙睡。\n换却莺花人世。\n渐暮色、鹃声四起。\n正愁满、香沟御水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17782, '四字令・醉太平', '周密', '残月半篱。\n残雪半枝。\n孤吟自款柴扉。\n听猿啼鸟啼。\n人归未归。\n无诗有诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17783, '醉落魄・一斛珠', '周密', '寒侵径叶。\n雁风击碎珊瑚屑。\n砚凉闲试霜晴帖。\n颂菊骚兰，秋事正奇绝。\n故人又作江西别。\n书楼虚度中秋节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17784, '祝英台近', '周密', '馀酲，寻旧雨，愁与病相半。\n绿意阴阴，丝竹静深院。\n绝怜事逐春移，泪随花落，似翦断、鲛房珠串。\n喜重见。\n为谁倦酒慵诗，筠屏掩双扇。\n白发潘郎，羞见看花伴。\n可堪好梦残时，新愁生处，烟月冷、子规声断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17785, '甘州・八声甘州', '周密', '渐萋萋、芳草绿江南，轻晖弄春容。\n记少年游处，箫声巷陌，灯影帘栊。\n月暖烘炉戏鼓，十里步香红。\n枕听新雨，往事朦胧。\n还是江春梦晓，怕等闲愁见，雁影西东。\n喜故人好在，水驿寄诗筒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17786, '甘州・八声甘州', '周密', '信山阴、道上景多奇，仙翁幻吟壶。\n爱一邱一壑，一花一草，窈窕扶疏。\n染就春云五色，更种玉千株。\n咳唾骚香在，四壁骊珠。\n曲折冷红幽翠，涉流花涧净，步月堂虚。\n羡风流鱼鸟，来往贺家湖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17787, '齐天乐', '周密', '护春帘幕东风里，当年问花曾到。\n玉影孤搴，冰痕半拆，漠漠冻云迷道。\n临流更好。\n正雪意逢迎，阴光相照。\n梦入罗浮，古苔啁哳翠禽小。\n一枝空念赠远，溯波流不到，心事谁表。\n倚竹天寒，吟香夜冷，几度月昏霜晓。\n寻芳欠早。\n怕鹤怨山空，雁归书少。\n不恨春迟，恨春容易老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17788, '忆旧游', '周密', '记移灯翦雨，换火篝香，去岁今朝。\n乍见翻疑梦，向梅边携手，笑挽吟桡。\n依依故人情味，歌舞试春娇。\n对婉娩年芳，漂零身世，酒趁愁消。\n天涯未归客，望锦羽沈沈，翠水迢迢。\n叹菊荒薇老，负故人猿鹤，旧隐谁招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17789, '声声慢', '周密', '琼壶歌月，白发簪花，十年一梦扬州。\n恨入琵琶，小怜重见湾头。\n尊前漫题金缕，奈芳情、已逐东流。\n还送远，甚长安乱叶，都是闲愁。\n次第重阳近也，看黄花绿酒，也合迟留。\n脆柳无情，不堪重系行舟。\n百年正消几别，对西风、休赋登楼。\n怎去得，怕凄凉时节，团扇悲秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17790, '踏莎行', '周密', '结客千金，醉春双玉。\n旧游宫柳藏仙屋。\n白头吟老茂陵西，清平梦远沈香北。\n玉笛天津，锦囊昌谷。\n春红转眼成秋绿。\n重翻花外侍儿歌，休听酒边供奉曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17791, '国香慢・国香', '周密', '玉润金明。\n记曲屏小几，翦叶移根。\n经年汜人重见，瘦影娉婷。\n雨带风襟零乱，步云冷、鹅管吹春。\n相逢旧京洛，素靥尘缁，仙掌霜凝。\n国香流落恨，正冰铺翠薄，谁念遗簪。\n水天空远，应念矾弟梅兄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17792, '一萼红', '周密', '步深幽。\n正云黄天淡，雪意未全休。\n鉴曲寒沙，茂林烟草，俯仰千古悠悠。\n岁华晚、漂零渐远，谁念我、同载五湖舟。\n磴古松斜，崖阴苔老，一片清愁。\n回首天涯归梦，几魂飞西浦，泪洒东州。\n故国山川，故园心眼，还似王粲登楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17793, '扫花游・扫地游', '周密', '江蓠怨碧，早过了霜花，锦空洲渚。\n孤蛩自语。\n正长安乱叶，万家砧杵。\n尘染秋衣，谁念西风倦旅。\n恨无据。\n怅望极归舟，天际烟树。\n心事曾细数。\n怕水叶沈红，梦云离去。\n情丝恨缕。\n倩回纹为织，那时愁句。\n雁字无多，写得相思几许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17794, '三姝媚', '周密', '浅寒梅未绽。\n正潮过西陵，短亭逢雁。\n秉烛相看，叹俊游零落，满襟依黯。\n露草霜花，愁正在、废宫芜苑。\n明月河桥，笛外尊前，旧情消减。\n莫诉离肠深浅。\n恨聚散匆匆，梦随帆远。\n玉镜尘昏，怕赋情人老，後逢凄惋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17795, '献仙音・法曲献仙音', '周密', '松雪飘寒，岭云吹冻，红破数椒春浅。\n衬舞台荒，浣妆池冷，凄凉市朝轻换。\n叹花与人凋谢，依依岁华晚。\n共凄黯。\n问东风、几番吹梦，应惯识当年，翠屏金辇。\n一片古今愁，但废绿、平烟空远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17796, '高阳台', '周密', '照野旌旗，朝天车马，平沙万里天低。\n宝带金章，尊前茸帽风。\n秦关汴水经行地，想登临、都付新诗。\n纵英游，叠鼓清笳，骏马名姬。\n酒酣应对燕山雪，正冰河月冻，晓陇云飞。\n投老残年，江南谁念方回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17797, '庆宫春・高阳台', '周密', '重叠云衣，微茫雁影，短篷稳载吴雪。\n霜叶敲寒，风灯摇晕，棹歌人语呜咽。\n拥衾呼酒，正百里、冰河乍合。\n千山换色，一镜无尘，玉龙吹裂。\n夜深醉踏长虹，表里空明，古今清绝。\n高台在否，登临休赋，忍见旧时明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17798, '高阳台', '周密', '小雨分江，残寒迷浦，春容浅入蒹葭。\n雪霁空城，燕归何处人家。\n梦魂欲渡苍茫去，怕梦轻、还被愁遮。\n感流年，夜汐东还，冷照西斜。\n萋萋望极王孙草，认云中烟树，鸥外春沙。\n白发青山，可怜相对苍华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17799, '探芳讯', '周密', '步晴昼。\n向水院维舟，津亭唤酒。\n叹刘郎重到，依依谩怀旧。\n东风空结丁香怨，花与人俱瘦。\n甚凄凉，暗草沿池，冷苔侵。\n桥外晚风骤。\n正香雪随波，浅烟迷岫。\n废苑尘梁，如今燕来否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17800, '四字令・醉太平', '周密', '眉消睡黄。\n春凝泪妆。\n玉屏水暖微香。\n听蜂儿打窗。\n筝尘半妆。\n绡痕半方。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17801, '西江月', '周密', '绿绮紫丝步障，红鸾彩凤仙城。\n谁将三十六陂春。\n换得两堤秋锦。\n眼缬醉迷朱碧，笔花俊赏丹青。\n斜阳展尽赵昌屏。\n羞死舞鸾妆镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17802, '江城子', '周密', '罗窗晓色透花明。\n瑶笙。\n按瑶筝。\n试讯东风，能有几分春。\n二十四阑凭玉暖，杨柳月，海棠阴。\n依依愁翠沁双颦。\n爱莺声。\n怕鹃声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17803, '少年游', '周密', '帘消宝篆卷宫罗。\n蜂蝶扑飞梭。\n一样东风，燕梁莺院，那处春多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17804, '好事近', '周密', '新雨洗花尘，扑扑小庭香湿。\n早是垂杨烟老，渐嫩黄城碧。\n晚帘都卷看青山，山外更山色。\n一色梨花新月，伴夜窗吹笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17805, '西江月', '周密', '情缕红丝冉冉，啼花碧袖荧荧。\n迷香双蝶下庭心。\n一行帘影。\n北里红红短梦，东风雁雁前尘。\n称消不过牡丹情。\n中半伤春酒病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17806, '醉落魄・一斛珠', '周密', '忆忆忆忆。\n宫罗褶褶消金色。\n吹花有尽情无极。\n泪滴空帘，香润柳枝湿。\n春愁浩荡湘波窄。\n红兰梦绕江南北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17807, '朝中措', '周密', '彩绳朱乘驾涛云。\n亲见许飞琼。\n多定梅魂才返，香瘢半掐秋痕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17808, '醉落魄・一斛珠', '周密', '馀寒正怯。\n金钗影卸东风揭。\n舞衣丝损愁千褶。\n一缕杨丝，犹是去年折。\n临窗拥髻愁难说。\n花庭一寸燕支雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17809, '浣溪沙', '周密', '蚕已三眠柳二眠。\n双竿初起画秋千。\n莺栊风响十三弦。\n鱼素不传新信息，鸾胶难续旧因缘。\n薄情明月几番圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17810, '踏莎行', '周密', '远草情锺，孤花韵胜。\n一楼耸翠生秋暝。\n十年二十四桥春，转头明月箫声冷。\n赋药才高，题琼语俊。\n蒸香压酒芙蓉顶。\n景留人去怕思量，桂窗风露秋眠醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17811, '酹江月・念奴娇', '林式之', '桐皋东去，又依然、烟际云边柔橹。\n赖有双台知己耳，牢落孤怀欲吐。\n小倚云根，细商心事，提起千年语。\n九天飞梦，别来长记幽渚。\n试说北海归文，西山何事，犹不甘臣武。\n广大尧天箕颍小，绵上可能如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17812, '摸鱼儿', '王奕', '问梅花、几人邀咏，平生见外骚楚。\n相思一夜罗浮远，姑射仙姿何处。\n情未吐。\n□□□、雄蜂雌蝶空相遇。\n岁年孰与。\n叹皓首相看，冰心独抱，谩作广平赋。\n黄昏暮。\n半点酸辛谁诉。\n寿阳眉恨妖妩。\n南来北使无明眼，细认杏花真谱。\n私自语。\n道消息、孤根还有春风主。\n启明未举。\n听画角吹残，马头摇梦，人已山阳路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17813, '水调歌头', '王奕', '吾玄终不白，拗出老扬雄。\n近日青衿绿发，转盼忽成翁。\n缩首天坠地，极力虞渊取日，直欲入冯宫。\n迂阔有如此，谁不笑王公。\n十年後，数椽屋，隐琊峰。\n人叹乾坤许大，醯瓮老山中。\n於是泛淮航泗，於是沿邹过鲁，千古慕雩风。\n造物既生我，斯道岂终穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17814, '沁园春', '王奕', '耳目肺肠，不由我乎，更由乎谁。\n也不必君平，不消詹尹，不疑何卜，不卜何疑。\n三径归来，一时有见，岂为黄初与义熙。\n天下事，但行其可，自合乎宜。\n大哉用易乘时。\n纵乌喙那能食子皮。\n叹失若塞翁，失为得本，赢如刘毅，赢乃输基。\n大黠小痴，有馀不足，谁必彭殇早与迟。\n眼前物，纵铜山金屋，一瞑全非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17815, '南乡子', '王奕', '搔首倚薰风。\n一幅画图尘土中。\n鹤怨猿惊人去也，潜龙。\n谁绞香车起蛰松。\n岁月去熙丰。\n世味人情自淡浓。\n春去春来墩不竞，匆匆。\n蜀水吴山血又红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17816, '霜天晓角', '王奕', '天无四壁。\n底用量江尺。\n徒把乾坤分裂，谁与帝、扶民厄。\n几年樊圃缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17817, '贺新郎', '王奕', '有客过东鲁。\n自葛水、泛舟西下，帆开三楚。\n万里湖光磨水镜，际五老、落星烟渚。\n又飞过、二姑门户。\n彭泽柳青新旧色，望九华、依约池阳路。\n风雨庙，乌江羽。\n蛾眉牛渚皆如故。\n问缘何、鲁港汀洲，江声无语。\n采石书生勋业在，吊锦袍、公子魂何处。\n流恨下、秦淮商女。\n多景楼头吟北固，笑平山堂里谁为主。\n且烂饮，琼花露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17818, '贺新郎', '王奕', '醉醒琼花露。\n买扁舟、邵伯津头，向秦邮去。\n流水孤村鸦万点，忆少游、回首斜阳树。\n又访著、山阳酒侣。\n细剔留城碑藓看，上歌舞、一啸江东主。\n望凫峄，过邹鲁。\n孔林百拜瞻茔墓。\n历四阜、少之墟，大庭之库。\n竟涉汶河登泰岱，候清光，夜半开玄圃。\n迤逦问、东平归路。\n蚩冢黄花吟笑罢，下新州，醉白楼头赋。\n复淮楚，寻故步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17819, '贺新郎', '王奕', '帆卸西湾侧。\n望康庐、老峰面目，旧曾相识。\n岁岁滔滔江浪远，回首暮云空碧。\n今想见、发痕全白。\n眠鹿矶头茅屋烂，问草堂、谁管真泉石。\n还更有，青牛迹。\n老峰点首如招客。\n道十年、玉斗窗间，两成疏觌。\n赢得老夫谙阅世，不作少年太息。\n看雨馀、依旧青山色。\n汶上归来重过我，最峰头、新长芝堪摘。\n分半席、共横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17820, '沁园春', '王奕', '八十日官，浩然归去，知心者希。\n谓诗有招魂，姑言其概，注其述酒，亦特其微。\n不事小儿，惟书甲子，皆是先生杜得机。\n看时运，与天荣木，始识真归。\n黄唐邈不可追。\n慨四十无闻昨已非。\n故怀彼仙师，策夫名骥，志夫童冠，寤寐交挥。\n人表何时，谁生过鲁，愿企高风慕浴沂。\n兹行也，尚庶几短葛，不负公衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17821, '八声甘州', '王奕', '诵公诗、大雅久不闻，吾衰竟谁陈。\n自晋宋以来，隋唐而下，旁若无人。\n光焰文章万丈，肯媚永王。\n卓有汾阳老，抱丈人贞。\n不是沈香亭上，谩题飞燕，蹴起靴尘。\n安得锦袍西下，明月堕江滨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17822, '水调歌头', '王奕', '长江衣带水，历代鼎彝功。\n服定衣冠礼乐，聊尔就江东。\n追忆金戈铁马，保以油幢玉垒，燧几秋风。\n更有当头著，全局倚元戎。\n攒万舸，开一棹，散无踪。\n到了书生死节，蜂蚁愧诸公。\n上有皇天白日，下有人心青史，未必竟朦胧。\n停棹抚遗迹，往恨逐冥鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17823, '贺新郎', '王奕', '决眦斜阳里。\n品江山、洛阳第一，金陵第二。\n休论六朝兴废梦，且说南浮之始。\n合就此、衣冠故址。\n底事轻抛形胜地，把笙歌、恋定西湖水。\n百年内，苟而已。\n纵然成败由天理。\n叹石城、潮落潮生，朝昏知几。\n可笑诸公俱铸错，回首金瓯瞥徙。\n漫了、紫云青史。\n老媚幽花栖断础，睇故宫、空拊英雄髀。\n身世蝶，侯王蚁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17824, '酹江月・念奴娇', '王奕', '英雄老矣，对江山、莫遣泪珠成斛。\n一西风休掩面，白浪黄尘迷目。\n凤去台空，鹭飞洲冷，几度斜阳木。\n欲书往事，南山应恨无竹。\n宁是商女当年，後来腔调，拍手铜曲。\n偃蹇老松虽拗□，犹□一枰残局。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17825, '法曲献仙音', '王奕', '九曲青溪，千年陈迹，往事不堪依据。\n老我重来，海乾石烂，那复断碑残础。\n应讶野王当日，三弄罢、乍无语。\n□□□。\n高牙大纛船如屋，又少甚笙歌，翠云箫鼓。\n流恨入寒筝，离合君臣良苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17826, '贺新郎', '王奕', '惆怅秦淮路。\n慨当年、商女谁家，几多年数。\n死去方知亡国恨，尚激起、浪花如语，应不为、黍峰蒲缕。\n花隔青溪胭井湿，又谁省、此时情绪。\n云盖拥，翠阴午。\n汨罗无复灵均楚。\n到如今、荃蕙椒兰，尽成禾黍。\n疑是龙穿王气，遗恨六朝作古。\n□留与、浮歌载醑。\n天外长江浑不管，也无春无夏无晴雨。\n流岁月、滔滔去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17827, '木兰花慢', '王奕', '翠微亭上醉，搔短发、舞缤纷。\n问六朝五姓，王姬帝胄，今有谁存。\n何似乌衣故垒，尚年年、生长儿孙。\n今古兴亡无据，好将往史俱焚。\n招魂。\n何处觅东山，筝泪落清樽。\n怅石城暗浪，秦淮旧月，东去西奔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17828, '南乡子', '王奕', '豪杰说中州。\n及此见题多景楼。\n曹石当年徒浪耳，悠悠。\n岁月滔滔江自流。\n风雪老兜鍪。\n不混关河事不休。\n浪舞桃花颠又蹶，嬴刘。\n莫与武陵仙客谋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17829, '水调歌头', '王奕', '迢迢冢水，直泻到东州。\n不拣秦淮吴楚，明月一家楼，何代非卿非相，底事柴桑老子，偏恁不推刘。\n半体鹿皮服，千古晋貔貅。\n过东鲁，登北固，感春秋。\n抵掌嫣然一笑，莫枉少陵愁。\n说甚萧锅曹石，古矣苏吟米画，黑白满盘收。\n对水注杯酒，为我向东流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17830, '八声甘州', '王奕', '问苍天、苍天阒无言，浩歌摘星楼。\n这茫茫禹迹，南来第一，是古扬州。\n当日双龙未渡，风月一家秋。\n中分胡越後，横断江流。\n□百年间春梦，笑槐柯蚁穴，多少王侯。\n谩平山堂里，棋局几边筹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17831, '临江仙', '王奕', '二十四桥明月好，暮年方到扬州。\n鹤飞仙去总成休。\n襄阳风笛急，何事付悠悠。\n几阕平山堂上酒，夕阳还照边楼。\n不堪风景事回头。\n淮南新枣熟，应不说防秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17832, '沁园春', '王奕', '唐李太白，访贺知章，浩歌此楼。\n想斗酒百篇，眼花落井，一时豪杰，千古风流。\n白骨青山，美人黄土，醉魄吟魂安在否。\n江南客，因来游胜践，稽首前修。\n悠悠。\n往事俱休，更莫遣兴亡狂白头。\n也莫论高皇、莫论项羽，谁为黄帝，谁为蚩尤。\n拶破愁城，吸乾酒海，袖拂安梁舞暮秋。\n题未了，又笑骑白鹤，飞下扬州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17833, '婆罗门引', '王奕', '佳人鬓发，几回涂抹共蝉娟。\n又何止三千。\n拟待盈盈宝鉴，多少绮罗筵。\n恨妖蟆怪事，长夜中天。\n中河影圆。\n清泪落尊前。\n舞罢霓裳初服，肯为人妍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17834, '贺新郎', '王奕', '试问司花女。\n是何年、培植琼葩，分来何谱。\n禁苑岂无新雨露，底事刚移不去，偏恋定、鹤城土。\n却怕杏花生眼觑。\n先廿年、和影无寻处。\n遗草木，悴风雨。\n看花老我成迟暮。\n绕阑干、追忆沈吟，欲言难赋。\n根本已非枝叶异，谁把赝苗裨补。\n但认得、唐人旧句。\n明月楼前无水部。\n扣之梅、梅又全无语。\n询古柏，过东鲁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17835, '沁园春', '王奕', '醉面挟风，携杜康酒，酹刘伶台。\n问漂母矶头，韩侯安在，钵山池下，乔鹊曾回。\n孝说仲车，忠传祖逖，忠孝如今亦可哀。\n清河口，但潮生潮落，帆去帆来。\n休呆。\n且饮三杯。\n莫枉教、东乌西兔催。\n更谁可百年，脱身不化，谁能五日，笑口长开。\n痛饮高歌，胡涂乱抹，快活斗山王秀才。\n今天下，曰利而已，何以平哉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17836, '唐多令', '王奕', '直上倚天楼。\n怀哉古楚州。\n黄河水、依旧东流。\n千古兴亡多少事，分付与、白头鸥。\n祖逖与留侯。\n二公今在不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17837, '沁园春', '王奕', '吾祖文中，曾於夫子，受罔极恩。\n有宇宙以来，春秋而後，三纲所系，万古常存。\n列国何时，东吴何地，十哲之中尚有言。\n况今也、与圣闲邦域，同一乾坤。\n卑飞难傍天阍。\n但勃衔香拜圣门。\n要水看黄河，山登岱岳，鲁求君子，学究中原。\n虽有他人，不如同姓，仰止文星出禁垣。\n又安得，借蒙庄大瓢，酌泗水之源。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17838, '西河', '王奕', '江左地。\n兴亡旧恨谁记。\n腥风不搅洛山云，怒涛怎起。\n泪眶历落泫新亭，碑趺犹卧江际。\n古今事，天莫倚。\n废兴元有时系。\n女墙月色自荒荒，尽平寸垒。\n舞台歌谢草痕深，青溪弥望烟水。\n马蹄杂锦绣市。\n认乌衣六朝，东巷西里。\n景物已非人世。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17839, '满江红', '蒲寿', '楼倚虚空。\n觉人世、不知何处。\n人缥缈、半檐星斗，一窗风露。\n潮退沙平凫雁静，夜深月黑鱼龙怒。\n把清樽、独自笑馀生，成何事。\n尘埃外，谈高趣。\n烟波上，题诗句。\n这美景良宵，且休虚度。\n梦觉宦情甜似蜡，老来况味酸如醋。\n念儿曹、南北几时归，情朝暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17840, '贺新郎', '蒲寿', '铁笛穿花去。\n问长安、市上生涯，而今何似。\n破帽青衫尘满面。\n不识何人共语。\n且面壁、听风雨。\n惟我虚中元识破，笑人间、日月无停杼。\n名与利，莫轻许。\n人生穷达皆天铸。\n试灯前、为问灵龟，劝君休怒。\n心肯命通元有数，何幸知音记取。\n季主也、应留得住。\n百岁光阴弹指过，算伯夷、盗跖俱尘土。\n心一寸，人千古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17841, '渔父词・渔父', '蒲寿', '万里长江一钓丝。\n萧萧蓬鬓任风吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17842, '渔父词・渔父', '蒲寿', '江渚春风澹荡时。\n斜阳芳草鹧鸪飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17843, '渔父词・渔父', '蒲寿', '烟浦回环几百湾。\n无人知此橛头船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17844, '渔父词・渔父', '蒲寿', '野缆闲移石笋江。\n旁人争看老眉庞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17845, '渔父词・渔父', '蒲寿', '葭荻横披众木东。\n浪花如雪晚来风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17846, '渔父词・渔父', '蒲寿', '飘忽狂风一霎间。\n长鱼吹浪势如山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17847, '渔父词・渔父', '蒲寿', '清晓朦胧古渡头。\n烟中人语橹声柔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17848, '渔父词・渔父', '蒲寿', '搔首推篷晓色新。\n雪花飘瞥大江滨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17849, '渔父词・渔父', '蒲寿', '明月愁人夜未央。\n篷窗如画水浪浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17850, '渔父词・渔父', '蒲寿', '白首渔郎不解愁。\n长歌箕踞亦风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17851, '渔父词・渔父', '蒲寿', '琉璃为地水精天。\n一叶渔舟浪满颠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17852, '渔父词・渔父', '蒲寿', '江上浪花飞洒天。\n拍阶屋如船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17853, '渔父词・渔父', '蒲寿', '远入茫茫无尽边。\n渔舟来往似行天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17854, '渔父词・渔父', '蒲寿', '白水塘边白鹭飞。\n龙湫山下鲫鱼肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17855, '渔父词・渔父', '蒲寿', '岩下无心云自飞。\n塘边足雨水初肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17856, '乃词', '蒲寿', '白头翁。\n白头翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17857, '喜迁莺', '吴龙翰', '微雨後，落花天。\n娇态病恹恹。\n怕人猜著是相思，成日不开帘。\n宝钗横，蝉鬓乱。\n院宇待人归尽。\n缓移莲步玉阑前。\n纤手掐花钿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17858, '摸鱼儿', '朱嗣发', '对西风、鬓摇烟碧，参差前事流水。\n紫丝罗带鸳鸯结，的的镜盟钗誓。\n浑不记、漫手织回文，几度欲心碎。\n安花著蒂。\n奈雨覆云翻，情宽分窄，石上玉簪脆。\n朱楼外。\n愁压空云欲坠。\n月痕犹照无寐。\n阴晴也只随天意。\n枉了玉消香碎。\n君且醉。\n君不见、长门青草春风泪。\n一时左计。\n悔不早荆钗，暮天修竹，头白倚寒翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17859, '更漏子', '陈达叟', '妾倚门，君上马。\n残月晓星犹挂。\n眉黛敛，泪珠凝。\n别离多少情。\n翠翘横，云鬓乱。\n复入绮衾犹暖。\n人独自，枕成双。\n争教不断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17860, '菩萨蛮', '陈达叟', '举头忽见衡阳雁。\n千声万字情何限。\n叵耐薄情夫。\n一行书也无。\n泣归香阁恨。\n和泪掩红粉。\n待雁却回时。\n也无书寄伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17861, '齐天乐', '文天祥', '南楼月转银河曙，玉箫又吹梅早。\n鹦鹉沙晴，葡萄水暖，一缕燕香清袅。\n瑶池春透。\n想桃露霏霞，菊波沁晓。\n袍锦风流，御仙花带瑞虹绕。\n玉关人正未老。\n唤矶头黄鹤，岸巾谈笑。\n剑拂淮清，槊横楚黛，雨洗一川烟草。\n印黄似斗。\n看半砚蔷薇，满鞍杨柳。\n沙路归来，金貂蝉翼小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17862, '齐天乐', '文天祥', '夜来早得东风信，潇湘一川新绿，柳色含晴，梅心沁暖，春浅千花如束。\n银蝉乍浴。\n正沙雁将还，海鳌初矗。\n云拥旌旗，笑声人在画阑曲。\n星虹瑶树缥缈，佩环鸣碧落，瑞笼华屋。\n露耿铜虬，冰翻铁马，帘幕光摇金粟。\n迟迟倚竹。\n更为把瑶尊，满斟。\n回首宫莲，夜深归院烛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17863, '酹江月・念奴娇', '文天祥', '庐山依旧，凄凉处、无限江南风物。\n空翠晴岚浮汗漫，还障天东半壁。\n雁过孤峰，猿归危嶂，风急波翻雪。\n乾坤未老，地灵尚有人杰。\n堪嗟漂泊孤舟，河倾斗落，客梦催明发。\n南浦闲云连草树，回首旌旗明灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17864, '酹江月・念奴娇', '文天祥', '水天空阔，恨东风不借、世间英物。\n蜀鸟吴花残照里，忍见荒城颓壁。\n铜雀春情，金人秋泪，此恨凭谁雪。\n堂堂剑气，斗牛空认奇杰。\n那信江海馀生，南行万里，属扁舟齐发。\n正为鸥盟留醉眼，细看涛声云灭。\n睨柱吞嬴，回旗走懿，千古冲冠发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17865, '酹江月・念奴娇', '文天祥', '乾坤能大，算蛟龙、元不是池中物。\n风雨牢愁无著处，那更寒虫四壁。\n横槊题诗，登楼作赋，万事空中雪。\n江流如此，方来还有英杰。\n堪笑一叶漂零，重来淮水，正凉风新发。\n镜里朱颜都变尽，只有丹心难灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17866, '满江红', '文天祥', '燕子楼中，又捱过、几番秋色。\n相思处、青年如梦，乘鸾仙阙。\n肌玉暗消衣带缓，泪珠斜透花钿侧。\n最无端、蕉影上窗纱，青灯歇。\n曲池合，高台灭。\n人间事，何堪说。\n向南阳阡上，满襟清血。\n世态便如翻覆雨，妾身元是分明月。\n笑乐昌、一段好风流，菱花缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17867, '满江红', '文天祥', '试问琵琶，胡沙外、怎生风色。\n最苦是、姚黄一朵，移根仙阙。\n王母欢阑琼宴罢，仙人泪满金盘侧。\n听行宫、半夜雨淋铃，声声歇。\n彩云散，香尘灭。\n铜驼恨，那堪说。\n想男儿慷慨，嚼穿龈血。\n回首昭阳离落日，伤心铜雀迎秋月。\n算妾身、不愿似天家，金瓯缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17868, '沁园春', '文天祥', '为子死孝，为臣死忠，死又何妨。\n自光岳气分，士无全节，君臣义缺，谁负刚肠。\n骂贼睢阳，爱君许远，留得声名万古香。\n後来者，无二公之操，百炼之钢。\n人生翕云亡。\n好烈烈轰轰做一场。\n使当时卖国，甘心降虏，受人唾骂，安得留芳。\n古庙幽沈，仪容俨雅，枯木寒鸦几夕阳。\n邮亭下，有奸雄过此，仔细思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17869, '念奴娇', '邓剡', '水天空阔，恨东风不惜、世间英物。\n蜀鸟吴花残照里，忍见荒城颓壁。\n铜雀春情，金人秋泪，此恨凭谁雪。\n堂堂剑气，斗牛空认奇杰。\n那信江海馀生，南行万里，不放扁舟发。\n正为鸥盟留醉眼，细看涛声云灭。\n睨柱吞嬴，回旗走懿，千古冲冠发。\n伴人无寐，秦淮应是孤月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17870, '满江红', '邓剡', '王母仙桃，亲曾醉、九重春色。\n谁信道、鹿衔花去，浪翻鳌阙。\n眉锁娇娥山宛转，髻梳堕马云侧。\n恨风沙、吹透汉宫衣，馀香歇。\n霓裳散，庭花灭。\n昭阳燕，应难说。\n想春深铜雀，梦残啼血。\n空有琵琶传出塞，更无环佩鸣归月。\n又争知、有客夜悲歌，壶敲缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17871, '浪淘沙', '邓剡', '疏雨洗天晴。\n枕簟凉生。\n井梧一叶做秋声。\n谁念客身轻似叶，千里飘零。\n梦断古台城。\n月淡潮平。\n便携酒访新亭。\n不见当时王谢宅，烟草青青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17872, '唐多令', '邓剡', '雨过水明霞。\n潮回岸带沙。\n叶声寒、飞透窗纱。\n堪恨西风吹世换，更吹我、落天涯。\n寂寞古豪华。\n乌衣日又斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17873, '烛影摇红', '邓剡', '郢雪歌高，天教鹤子参鸣和。\n薰风旌节瑞华□，光动垂弧左。\n早是烟楼撞破。\n更明珠、重添一颗。\n镜容中夜，摩顶欣然，石麟天堕。\n未羡眉山，两峰儿子中峰我。\n推贤世世珥金貂，何况阴功大。\n欲写弄獐书贺。\n愧无功、难消玉果。\n摩挲老眼，曾识英雄，试啼则个。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17874, '霜天晓角', '邓剡', '蛮烟塞雪。\n天老梅花骨。\n还著锦衣游戏，清江上、管风月。\n木兰归海北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17875, '木兰花慢', '邓剡', '步凉绿野，□锺鼓、□园林。\n有骑竹更生，扶藜未老，歌舞堂阴。\n金鞭半横玉带，烨神人、风度五云深。\n大耐自应鹤骨，活人总是天心。\n寿蒲香晚尚堪斟。\n梧竹对潇森。\n早问道燕城，衣裁绣衮，台筑黄金。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17876, '摸鱼儿', '邓剡', '问庐陵、米作何价。\n棠阴又绿今夏。\n活人手段依然在，独乐园中司马。\n初度也。\n算几处篝香，手额你多谢。\n风亭月榭。\n尽隐橘观棋，折荷筒酒，花竹秀而野。\n阶庭树，满目鱼鱼雅雅。\n千金难买清暇。\n纷纷征榷尘如梦，谁有似公闲者。\n天怎舍。\n趁绿鬓朱颜，须入凌烟画。\n海天不夜。\n管岁岁安期，采蒲为寿，高宴碧桃下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17877, '促拍丑奴儿', '邓剡', '睡起怯春寒。\n海棠花、开未开间。\n莫言春色三分二，朱颜绿鬓，栽花种竹，谁似君闲。\n侯印旧家毡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17878, '八声甘州', '邓剡', '笑钗符、恰正带宜男。\n还将寿花簪。\n早风薰竹醉，松凉鹤健，午坐存庵。\n三十六峰玉立，隔尘听玄谈。\n何似人难老，三十才三。\n闻得天边好语，第一流人物，偏重江南。\n满玻璃春绿，十载爱棠甘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17879, '好事近', '邓剡', '桃脸破初寒，笑问刘郎前度。\n为说正元朝上，缥缈午桥午。\n百年方半日来多，且醉且吟去。\n须信剑南万首，胜侯封千户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17880, '摸鱼儿', '邓剡', '笑平生、布帆无恙，堂堂稳送君去。\n江声悲壮崖殷血，曾是英雄行处。\n今亦古。\n甚一点东风，天不周郎与。\n城幡夜竖。\n几铜爵春残，战沙秋冷，华发遽如许。\n东坡老，千载风流两赋。\n馀音不绝如缕。\n临皋一笑三生梦，还认岷峨乡语。\n挥玉麈。\n尽不碍灯前，痛饮檐花雨。\n雪堂在否。\n管驾鹤归来，为君细赏，蝴蝶上阶句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17881, '疏影', '邓剡', '瑶尊蘸翠。\n短长亭送别，风恋晴袂。\n腊树迎春，一路清寒，能消几日羁思。\n霜华不惜阳关柳，悄莫系、行人嘶骑。\n对梅花、一笑分携，胜约别来相寄。\n人物仙蓬妙韵，瑞鸾敛迅翼，聊憩香枳。\n见说使君，好语先传，付与芙蓉清致。\n客来欲问荆州事，但细语、岳阳楼记。\n梦故人、剪烛西窗，已隔洞庭烟水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17882, '贺新郎', '刘鉴', '曾作莺迁贺。\n道玉皇、久敕薇垣，分君星颗。\n只待好年好时日，约束东风吹堕。\n到今日、看来真个。\n恰好丁年翁七十，五云间、太乙吹藜火。\n青一点，杉溪左。\n太翁阴天来大。\n後隆山、层一层高，层层突过。\n簪绂蝉联孙又子，眼里人家谁那。\n算只有、翁恁麽。\n孙陆机云翁卫武，便履声、毡复尚书坐。\n拚几许，犀钱果。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17883, '满江红', '刘鉴', '袅袅春幡，恰十日、又逢元夕。\n人正在、景清堂上，金樽娱客。\n蜡炬红摇花外竹，宝香情透梅边石。\n听儿童、父老说青原，东风国。\n平易政，人皆悦。\n真实念，天知得。\n想旌旗一路，又添春色。\n满眼变成金色界，举头身近琼楼月。\n问明年、何处著鳌山，蓬莱北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17884, '满江红', '翁', '祷雨文昌，只全靠、心香一瓣。\n才信宿，沛然膏泽，来从方寸。\n早稻含风香旖旎，晚秧饱水青葱茜。\n问螺江、恰见线来流，今平岸。\n君作事，看天面。\n天有眼，从君愿。\n信瑞莲芝草，几曾虚献。\n此雨千金无买处，丰年饱吃君侯饭。\n管酿成、春酒上公堂，人人献。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17885, '糖多令・唐多令', '王洧', '雁荡接台山。\n秋来最好看。\n寿星明、高现云端。\n八月初弦三日里，□二老、福人间。\n玉节近天颜。\n东西两路安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17886, '南乡子', '汪梦斗', '西北有神州。\n曾倚斜阳江上楼。\n目断淮南山一抹，何由。\n载泪东风洒汴流。\n何事却狂游。\n直驾驴车度白沟。\n自古幽燕为绝塞，休愁。\n未是穷荒天尽头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17887, '朝中措', '汪梦斗', '人言楼观似寥阳。\n巍倚太清傍。\n便有二京赋手，也须费力铺张。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17888, '人月圆', '汪梦斗', '寻常一样窗前月，人只看中秋。\n年年今夜，争寻诗酒，共上高楼。\n一奁明镜，能圆几度，白了人头。\n良辰美景，赏心乐事，输少年游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17889, '金缕曲・贺新郎', '汪梦斗', '满目飞明镜。\n忆年时、呼朋楼上，畅怀觞咏。\n圆到今宵依前好，诗酒不成佳兴。\n身恰在、燕台天近。\n一段凄凉心中事，被秋光、照破无馀蕴。\n却不是，诉贫病。\n宫庭花草埋幽径。\n想夜深，女墙还有，过来蟾影。\n千古词人伤情处，旧说石城形胜。\n又今说、断桥风韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17890, '摸鱼儿', '汪梦斗', '忆旧时、东方□郡，东原尽是佳处。\n梁都破了寻南渡，几遍狐号鳝舞。\n君试觑。\n环一抹荒城，草色今如许。\n芳华旧地。\n曾一上飞云，歌台酒馆，落日乱鸦度。\n吟情苦。\n滴尽应雄老泪。\n凄酸非是儿女。\n西湖似我西湖否。\n只怕不如西子。\n秋欲暮。\n要一看秋波，又自催归计。\n休□浪语。\n待过江说与，高车驷马，今是朝天路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17891, '踏莎行', '汪梦斗', '选得官归，黄埃满面。\n难於奏赋明光殿。\n秋帆落日渡淮来，三杯酒浊凭谁劝。\n旧日佳词，自吟一遍。\n绿袍不是嫦娥翦。\n红楼十里古扬州，无人为把珠帘卷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17892, '汉宫春', '彭元逊', '十日春风，又一番调弄，怕暖愁阴。\n夜来风雨，摇得杨柳黄深。\n熏篝未断，梦旧寒、浅醉同衾。\n便是闻灯见月，看花对酒惊心。\n携手满身花影，香物霏霏，露湿罗襟。\n笙歌行人归去，回首沈沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17893, '满江红', '彭元逊', '翠袖馀寒，早添得、铢衣几重。\n何须怪、妍华都谢，更为谁容。\n衔尽吴花成鹿苑，人间不恨雨和风。\n便一枝、流落到人家，清泪红。\n山雾湿，倚熏笼。\n垂ぢ叶，鬓酥融。\n恨宫云一朵，飞过空同。\n白日长闲青鸟在，杨家花落白苹中。\n问故人、忍更负东风，尊酒空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17894, '解佩环・疏影', '彭元逊', '江空不渡，恨蘼芜杜若，零落无数。\n远道荒寒，婉娩流年，望望美人迟暮。\n风烟雨雪阴晴晚，更何须，春风千树。\n尽孤城、落木萧萧，日夜江声流去。\n日晏山深闻笛，恐他年流落，与子同赋。\n事阔心违，交淡媒劳，蔓草沾衣多露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17895, '徵招', '彭元逊', '人间无欠秋风处，偏到霜痕月杪。\n风雨船篷，日夜风波未了。\n忽潮生海立，又天阔、江清欲晓。\n孤迥幽深，激扬悲壮，浮沈浩渺。\n行路古来难，貂裘敞、匹马关山人老。\n锦字未成，寒到君边书到否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17896, '子夜歌', '彭元逊', '视春衫、箧中半在，酒痕花露。\n恨桃李、如风过尽，梦里故人成雾。\n临颍美人，秦川公子，晚共何人语。\n对人家、花草池台，回首故园咫尺，未成归去。\n昨宵听、危弦急管，酒醒不知何处。\n飘泊情多，衰迟感易，无限堪怜许。\n似尊前眼底，红颜消几寒暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17897, '临江仙', '彭元逊', '红袖乌丝失酒，金钗银烛销春。\n柳边桃下复清晨。\n帽风回马旋，扇雨拂花情。\n白帝空惊旧曲，阳关只梦行人。\n碧云何处认芳尘。\n紫荆花作荚，青杏核生仁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17898, '临江仙', '彭元逊', '自结床头麈尾，角巾坐枕孤松。\n片云承日过山东。\n起听荷叶雨，行受芷花风。\n无客同羹莼菜，有人为剥莲蓬。\n东墙年少未从容。\n何因知我意，吹笛月明中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17899, '瑞鹧鸪', '彭元逊', '背人西去一莺啼。\n拍手还惊百舌飞。\n浅雨微寒春有思，宿妆残酒欲时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17900, '瑞鹧鸪', '彭元逊', '东洲游伴寄兰苕。\n人日晴时不用招。\n微雨来看杨柳色，故人相遇浴龙桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17901, '蝶恋花', '彭元逊', '微雨烧香馀润气，新绿，乳燕相依睡。\n无复卷帘知客意，杨柳更欲因风起。\n旧梦苍茫云海际。\n强作欢娱，不觉当年似。\n曾笑浮花并浪蕊。\n如今更惜棠梨子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17902, '蝶恋花', '彭元逊', '日晚游人酥粉。\n四雨亭前，面面看花坐。\n扇拂游蜂青杏堕。\n新红一路秋千过。\n帘外清歌帘底和。\n自理琵琶，不用笙簧佐。\n八摺香罗馀碧唾。\n路花点笔轻题破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17903, '如梦令', '彭元逊', '今夜故人独宿。\n小雨梨花当屋。\n犹有未残枝，轻脆不堪人触。\n休触。\n休触。\n憔悴怕惊郎目。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17904, '菩萨蛮', '彭元逊', '玉蛇踯躅流光卷。\n连珠合沓帘波远。\n花动见鱼行。\n红裳眩欲倾。\n人来惊翡翠。\n小鸭惊还睡。\n两岸绿阴生。\n修廊时听莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17905, '谒金门', '彭元逊', '春一点。\n透得酥温玉软。\n唇晕睡花连袖染。\n嫣红惊绝艳。\n日暮飞红扑脸。\n翠被夜寒波。\n梦断锦茵成堕靥。\n宫廊微月转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17906, '月下笛', '彭元逊', '江上行人，竹间茅屋，下临深窈。\n春风袅袅，翠鬟窥树犹小。\n遥迎近倚，归还愿、分付横枝未了。\n扁舟却去，中流回首，惊散飞鸟。\n重踏新亭屐齿，耿山抱孤城，月来华表。\n鸡听人语，隔江相伴歌笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17907, '六丑', '彭元逊', '似东风老大，那复有、当时风气。\n有情不收，江山身是寄。\n浩荡何世。\n但忆临官道，暂来不住，便出门千里。\n痴心指望回风坠。\n扇底相逢，钗头微缀。\n他家万条千缕，解遮亭障驿，不隔江水。\n瓜洲曾舣，等行人岁岁。\n日下长秋，城乌夜起。\n帐庐好在春睡。\n共飞归湖上，草青无地。\n雨、春心如腻。\n欲待化、丰乐楼前，青门都废。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17908, '隔浦莲近・隔浦莲近拍', '彭元逊', '夜寒晴早人起。\n见柳知新翠。\n撼树试花意。\n两蜂狂救堕蕊。\n见著羞懒避。\n春都在，时节到愁地。\n屏间字。\n香痕半掏，误期一一曾记。\n朱弦谩锁，不会近番慵脆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17909, '忆旧游', '彭元逊', '记新楼试酒，上客回车，初识能歌。\n几许怜才意，觉援琴意动，授简情多。\n青鸾昼下缥缈，烟雾隔轻罗。\n还自有人猜，素巾承汗，微影双蛾。\n西陂千树雪，欲绝世乘风，下照沧波。\n怪倚春憔悴，扁舟月上，草草相过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17910, '生查子', '彭元逊', '痴多故恼人，妆晚翻嫌趣。\n只为眼波长，嗔笑娇难触。\n春心不肯深，春睡何曾足。\n莫待柳花飞，飞去无拘束。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17911, '玉女迎春慢・玉女迎春', '彭元逊', '浅入新年，逢人日、拂拂淡烟无雨。\n叶底妖禽自语。\n小啄幽香还吐。\n东风辛苦，便怕有、踏青人误。\n清明寒食，消得渡江，黄翠千缕。\n看临小帖宜春，填轻晕湿，碧花生雾。\n为说钗头袅袅，系著轻盈不住。\n问郎留否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17912, '齐天乐', '方衡', '皇天眷佑中兴烈。\n维岳共生鸿硕。\n镇抚精神，规恢调度，未数至言长策。\n中原望，总万里山河，尽归经画。\n更看旋乾转坤，烦一指麾力。\n胡尘顿消海岱，倚天长啸处，兼惠南北。\n宝镇还朝，圣恩如海，趁得崧高华席。\n星晨步峻，看丹凤飞来，趣登枢极。\n□寿齐天，愿齐开寿域。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17913, '声声慢', '郭居安', '捷书连昼，甘洒通宵，新来喜沁尧眉。\n许大担当，人间佛力须弥。\n年年八月八日，长记他、三月三时。\n平生事，想祗和天语，不遣人知。\n一片闲心鹤外，被乾坤系定，虹玉腰围。\n阊阖云边，西风万籁吹齐。\n归舟更归何处，是天教、家在苏堤。\n千千岁，比周公、多个彩衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17914, '木兰花慢', '郭居安', '听都人共语，又还是、岁逢庚。\n记今帖频催，衮衣将至，绣先迎。\n笙歌六宫齐奏，到而今、犹唱贺升平。\n千岁人间福本，天公著意看承。\n秋深。\n帘卷空明。\n问西子，最宜晴。\n喜新来多暇，玉醪龙炙，菊院花城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17915, '摸鱼儿', '赵从橐', '指庭前、翠云金雨。\n霏霏香满仙宇。\n一清透彻浑无底，秋水也无流处。\n君试数。\n此样襟怀，顿得乾坤住。\n闲情半许。\n听万物氤氲，从来形色，每向静中觑。\n琪花落，相接西池寿母。\n年年弦月时序。\n荷衣菊佩寻常事，分付两山容与。\n天证取。\n此老平生，可向青天语。\n瑶卮缓举。\n要见我何心，西湖万顷，来去自鸥鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17916, '木兰花慢', '廖莹中', '请诸君著眼，来看我、福华编。\n记江上秋风，鲸涨雪，雁徼迷烟。\n一时几多人物，只我公、只手护山川。\n争睹阶符瑞象，又扶红日中天。\n因怀下走奉。\n磨盾夜无眠。\n知重开宇宙，活人万万，合寿千千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17917, '个侬', '廖莹中', '恨个侬无赖，卖娇眼、春心偷掷。\n苍苔花落，先印下一双春迹。\n花不知名，香才闻气，似月下箜篌，蒋山倾国。\n半解罗襟，蕙薰微度，镇宿粉、栖香双蝶。\n语态眠情，感多情、轻怜细阅。\n休问望宋墙高，窥韩路隔。\n寻寻觅觅。\n又暮雨凝碧。\n花径横烟，红扉映月，尽一刻、千金堪值。\n卸袜熏笼，藏灯衣桁，任裹臂金斜，搔头玉滑。\n更恨檀郎，恶怜深惜。\n尽颤袅、周旋倾侧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17918, '万年欢', '丁察院', '葛井丹明，西来金母，霓旌云旆。\n移下瑶池，竹外一壶秋水。\n菊□香留宿醉。\n看後夜、冰轮满桂。\n貂蝉映、虹玉称觞，遂初堂上佳会。\n娇孙彩衣聚戏。\n指明年八十，儿额先记。\n要比庄椿，八数更加千倍。\n好是皇恩锡类。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17919, '卜算子', '黄右曹', '清晓听麻姑，来约西王母。\n共取蟠桃簇玉盘，来劝摩耶酒。\n王母问摩耶，此意还知否。\n只为曾生我佛来，更与千千寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17920, '水龙吟', '翁溪园', '镇淮楼下旌旗，晶明辉映云山阁。\n宸旒倚重，折冲千里，无逾秋壑。\n缓带清裘，纶巾羽扇，从容筹略。\n使毡裘胆破，丁宁边吏，无生事，空沙漠。\n二十四桥风月，称迷楼、卷尽帘箔。\n绂麟华旦，饱吟玉蕊，款簪金药。\n驿骑朝驰，宝鞍赍赐，御筵宣押。\n更赐环促召，中书入令，作汾阳郭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17921, '水调歌头', '翁溪园', '丹鹤结青士，玄鹿侍苍官。\n寿仙堂下，应伴凫戏莱斑。\n麟记当年绣绂，燕剪今朝彩胜，淑气逐椒盘。\n孕毓阳和粹，独占一春先。\n平淮了，勋业盛，傲东山。\n中原犹待经略，趣诏凤池还。\n更数尧阶五荚，又上华封三祝，千载圣须贤。\n即拜玉枝赐，长冠紫宸班。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17922, '沁园春', '翁溪园', '记得花筵，巧夕星河，初度女牛。\n更四双荚，十分桂魄，中元佳致，妆点初秋。\n蔼蔼非烟，如雾，锦水郁葱佳气浮。\n人人道，是王孙帝胄，今日生朝。\n银潢万叶源流。\n见一点长庚辉绛霄。\n似东平为善，河间献雅，风流酝藉，西汉诸刘。\n恰遇称觞，蓬壶歌缓，满酌蒲萄双玉舟。\n椿松等算，年年醉傲，花马金裘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17923, '洞仙歌', '翁溪园', '几番梅雨，蒲风过、端阳後。\n细数月轮，犹待双秀。\n戏彩华堂宴，设朱门右。\n酌金荷，争献寿。\n蟠桃新熟，阿母齐长久。\n一门奋建，攀桂客、无双手。\n好事来春在，杏苑联蓝绶。\n应继琼林董，却胜燕山窦。\n夸盛事、真罕有。\n金花封诰，管取重重受。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17924, '踏莎行', '翁溪园', '荚飞双，桂分缺二。\n金风已肃深秋意。\n萱庭戏彩恰称觞，蕊宫仙子天台裔。\n鹤发童颜，龟龄福备。\n孩儿书额添三字。\n常将机训付儿孙，取青行拥潘舆侍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17925, '夜行船', '倪君', '年少疏狂今已老。\n筵席散、杂剧打了。\n生向空来，死从空去，有何喜、有何烦恼。\n说与无常二鬼道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17926, '一翦梅', '杨佥判', '襄樊四载弄干戈。\n不见渔歌。\n不见樵歌。\n试问如今事若何。\n金也消磨。\n谷也消磨。\n拓枝不用舞婆娑。\n丑也能多。\n恶也能多。\n朱门日日买朱娥。\n军事如何。\n民事如何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17927, '沁园春', '萧某', '士籍令行，伯仲分明，逐一排连。\n问子孙何习，父兄何业，明经词赋，右具如前。\n最是中间，娶妻某氏，试问于妻何与焉。\n乡保举，那当著押，开口论钱。\n祖宗立法于前。\n又何必更张万万千。\n算行关改会，限田放籴，生民凋瘵，膏血既。\n只有士心，仅存一脉，今又艰难最可怜。\n谁作俑，陈坚伯大，附势专权。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17928, '乌夜啼', '赵文', '院静槐阴似水，雨馀蝉语先秋。\n熟残梅子无人打，金弹满红沟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17929, '阮郎归', '赵文', '冰肌玉骨淡裳衣。\n素云生翠枝。\n一生不晓谪仙诗。\n雪香应自知。\n微雨後，禁烟时。\n洗妆君莫迟。\n东风不解惜妍姿。\n吹成蝴蝶飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17930, '阮郎归', '赵文', '舞红一架欲生衣。\n残英辞旧枝。\n雨生自唱惜春词。\n行人应未知。\n新火後，薄罗时。\n君归何太迟。\n镜中失却少年姿。\n年随花共飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17931, '苏幕遮', '赵文', '绿秧平，烟树远，村落声喧，凫雁归来晚。\n自倚阑干舒困眼。\n一架葡萄，青得池塘满。\n饮先愁，吟又懒。\n几许闲情，百计难消遣。\n客落不如归梦短。\n何况啼鹃，怎不教肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17932, '侧犯', '赵文', '恨花开尽，夜深自敛胭脂颗。\n雨过。\n绕曲曲花篷锦围裹。\n浮空烧蜜矩，香雾霏霏堕。\n无那。\n倚滴滴娇红笑相。\n歌俦饮伴，花底围春坐。\n念满眼、少年人，谁更老於我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17933, '石州慢', '赵文', '京浙尘埃，闽峤风霜，不觉催老。\n封侯事付儿曹，懒把菱花频照。\n明光赋笔，那知白首山中，年年管领闲花草。\n叩角夜漫漫，问何时能晓。\n堪笑。\n空有传世千篇，正似病呻饥啸。\n欲傲王侯，早被王侯相傲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17934, '望海潮', '赵文', '云外梅阴，雨馀苔晕，嫩寒初沁罗裳。\n书几凝尘，琴丝带润，小窗幽梦生凉。\n新水涨银塘。\n恨王孙去後，烟草茫茫。\n记得湖山胜处，相对拆封黄。\n情笺思墨犹香。\n奈当时两鬓，都是吴霜。\n兔颖吟苦，裘解尽，何意此□游梁。\n旧话不堪长。\n便倩薰风吹去，本地看风光。\n惟有青山，伴我耕钓老村庄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17935, '大', '赵文', '正宝香残，重帘静，飞鸟时惊花铎。\n沈思前梦去，有当时老泪，欲弹还阁。\n太一宫墙，菩提寺路，谁管纷纷开落。\n心情浑何似，似琵琶马上，晓寒沙漠。\n想筝雁频移，钏金度瘦，素肌清削。\n相思无奈著。\n重访旧、谁遣车生角。\n暗记省、刘郎前度，杜枚三生，为何人、顿乖芳约。\n试把菱花拭，愁来处、鬓丝先觉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17936, '莺啼序', '赵文', '东风何许红紫，又匆匆吹去。\n最堪惜、九十春光，一半情绪听雨。\n到昨日、看花去处，如今尽是相思树。\n倚斜阳脉脉，多情燕子能语。\n自怪情怀，近日顿懒，忆刘郎前度。\n断桥外、小院重帘，那人正柳边住。\n问章台、青青在否。\n芳信隔、□魂无据。\n想行人，折尽柔条，滚愁成絮。\n闲将杯酒，苦劝羲和，揽辔更少驻。\n怎忍把、芳菲容易委路。\n春还倒转归来，为君起舞。\n寸肠万恨，何人共说，十年暗洒铜仙泪，是当时、滴滴金盘露。\n思量万事成空，只有初心，英英未化为土。\n浮生似客，春不怜人，人更怜春暮。\n君不见、青楼朱阁，舞女歌童，零落山丘，便房幽户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17937, '莺啼序', '赵文', '秋风又吹华发，怪流光暗度。\n最可恨、木落山空，故国芳草何处。\n看前古、兴亡堕泪，谁知历历今如古。\n听吴儿唱彻，庭花又翻新谱。\n肠断江南，庾信最苦，有何人共赋。\n天又远，云海茫茫，鳞鸿似梦无据。\n怨东风、不如人意，珠履散、宝钗何许。\n想故人、月下沈吟，此时难诉。\n吾生已矣，如此江山，又何怀故宇。\n不恨赋归迟，归计大误。\n当时只合云龙，飘飘平楚。\n男儿死耳，嘤嘤昵昵，丁宁卖履分香事，又何如、化作胥潮去。\n东君岂是无能，成败归来，手种瓜圃。\n膏残夜久，月落山寒，相对耿无语。\n恨前此、燕丹计早，荆庆才疏，易水衣冠，总成尘土。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17938, '绮寮怨', '赵文', '绛阙珠宫何处，碧梧双凤吟。\n为底事、一落人间，轻题破、隐韵天音。\n当时点云滴雨，匆匆处、误墨沾素襟。\n算人间、最苦多情，争知道、天上情更深。\n世事似晴又阴。\n罗褥甲帐，回头一梦难寻。\n虎啸ㄛ，护遗迹、尚如今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17939, '疏影', '赵文', '寒泉溅雪，有环佩隐隐，飞度霜月。\n易水风寒，壮士悲歌，关山万里离别。\n杨花浩荡晴空转，又化作、云鸿霜鹘。\n耿石壕，夜久无言寂历，如闻幽咽。\n云谷山人老矣，江空又岁晚，相对愁绝。\n玉立长身，自是胎仙，舞我黄庭三叠。\n人间只惯丁当字，妙处在、一声清拙。\n待明朝、试拂菱花，老我一簪华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17940, '瑞鹤仙', '赵文', '绿杨深似雨。\n西湖上、旧日情丝恨缕。\n风流似张绪。\n羡春风依旧，年年眉妩。\n宫腰楚楚。\n倚画阑、曾斗妙舞。\n想而今似我，零落天涯，却悔相妒。\n痛绝长秋去後，杨白花飞，旧腔难谱。\n年年暗度。\n凄凉事，不堪诉。\n记菩提寺路，段家桥水，何时重到梦处。\n况柔条老去，争奈系春不住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17941, '法驾导引', '赵文', '云漠漠，云漠漠，云拥紫皇家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17942, '法驾导引', '赵文', '山中好，山中好，长日养婴儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17943, '法驾导引', '赵文', '公度我，公度我，我是汉铜仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17944, '八声甘州', '赵文', '是去年、春草又凄凄，尘生缕金衣。\n怅朱颜为土，白杨堪柱，燕子谁依。\n谩说漫漫六合，无地著相思。\n辽鹤归来後，城亦全非。\n更有延平一剑，向风雷半夜，何处寻伊。\n怪天天何物，堪作玉弹棋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17945, '塞翁吟', '赵文', '又海棠开後，楼上倍觉春寒。\n绿叶润，雨初乾。\n爱远树团团。\n当时剩买名花种，那信付与谁看。\n十载事，土花漫。\n但青得阑干。\n悲欢。\n思人世、真如一梦，留不住、城头日残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17946, '凤凰台上忆吹箫', '赵文', '白玉磋成，香罗捻就，为谁特地团团。\n羡司花神女，有此清闲。\n疑是弓靴蹴鞠，刚一踢、误挂花间。\n方信道，酴失色，玉蕊无言。\n凭阑。\n几回淡月，怪天上冰轮，移下尘寰。\n奈堪同玉手，难插云鬟。\n人道转官球也，春去也，欲转何官。\n聊寄与、诗人案头，冰雪相看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17947, '玉烛新', '赵文', '梅花新霁後。\n正锦样华堂，一时装就。\n洞房花烛深深处，慢转铜壶银漏。\n新妆未了。\n奈浩荡、春心相侯。\n香篆里、簇簇笙歌，微寒半侵罗袖。\n侵晨浅捧兰汤，问堂上萱花，夜来安否。\n功名漫斗。\n漫赢得、万里相思清瘦。\n蓝袍俊秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17948, '花犯', '赵文', '绣帘深，刘郎一笑，风流胜前度。\n戟香门户。\n还别有祥云，檐外飞舞。\n洞底烛下应低语。\n晨妆须带曙。\n待献了、堂前罗袜，双双交祝付。\n从前茜桃与杨枝，如今便、合逊梅花为主。\n行乐处。\n西溪上、柳汀花屿。\n封侯事、看人漫苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17949, '氐州第一', '赵文', '风雨山城，天意欲雪，梅花照影清峭。\n彩燕飞春，祥麟祓旦，当日文星高照。\n天地无情，向十载、风埃吹老。\n盖世科名，经邦事业，白衣苍狗。\n不是贪名求分表。\n漫猎较、逢场一笑。\n野外朝仪，城中马队，且暂淹才调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17950, '莺啼序', '赵文', '初荷一番濯雨，锦云红尚卷。\n隘华屋、赋客吟仙，候望南极天远。\n还报道、飘然紫气，山奇水胜都行遍。\n却归来领客，水晶庭院开宴。\n窗户青红，正似京洛，按笙歌一片。\n似别有、金屋佳人，桃根桃叶清婉。\n倚薰风、虬须正绿，人似玉手纨扇。\n算风流，只有蓬瀛，画图曾见。\n谁知老子，正自萧然，於此兴颇浅。\n只拟问、金砂玉蕊，兔髓乌肝，偃月炉中，七还九转。\n今来古往，悠悠史传，神仙本是英雄做，笑英雄、到此多留恋。\n看看破晓耕龙，跨海骑鲸，千年依旧丹脸。\n便教乞与，万里封侯，奈朔风如箭。\n又何似、广山一任，种竹栽花，棋局思量，墨池挥染。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17951, '最高楼', '赵文', '春小小，和气满仙家。\n喜渐近春华。\n彩衣明媚人如玉，金杯潋滟酒成霞。\n寿诗翁，翁饮少，更添些。\n便万里传宣谁不羡。\n便万里封侯谁不愿。\n适意处，退为佳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17952, '临江仙', '赵文', '如此中山如此酒，何须更觅蓬瀛。\n江湖历□记平生。\n诗囊都束起，只好说丹经。\n家事付他儿辈，功名留待诸孙。\n维摩法喜鬓青青。\n日长深院里，时听读书声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17953, '临江仙', '赵文', '恰好菊花前二日，寿星高照秋天。\n堂前王母鬓方玄。\n怀中娇凤小，已解祝公年。\n如此生涯如此屋，看看海亦成田。\n闲中多把酒杯传。\n长生无别诀，放下有神仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17954, '洞仙歌', '赵文', '千年鹭渚，持作须翁酒。\n剩有儿孙上翁寿。\n向玉和堂前，樽俎从容，笑此处，惯著丝纶大手。\n金丹曾熟未，熟得金丹，头上安头甚时了。\n便踢翻炉鼎，抛却蒲团，直恁俊鹘梢空时候。\n但唤取、心斋老门生，向城北城南，傍花随柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17955, '塞翁吟', '赵文', '坐对梅花笑，还记初度年时。\n名利事，总成非。\n漫老矣何为。\n吴山夜月闽山雾，回首鬓影如丝。\n懒更问，斗牛箕。\n强凭醉成诗。\n闲思。\n嗟飘泊，浮云飞絮，曾跌荡、春风柘枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17956, '八声甘州', '赵文', '记年时、快马上青云，而今衮衣还。\n问公归何有，春风万斛，散满人间。\n闻道金銮召对，风采动朝班。\n宰相从来有，几个朱颜。\n梅雨槐风清润，正台星一点，光照龙湾。\n赴经纶馀暇，按行紫芝山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17957, '木兰花慢', '赵文', '鹭州江上水，望南浦、送将归。\n想陌上儿童，尊前父老，口口能碑。\n家声一琴一鹤，甚和他、琴鹤也无之。\n城市貔貅昼静，泮宫芹藻春迟。\n与公南北两天涯，渺再见何时。\n记楼月歌残，碧云句好，尽是相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17958, '扫花游・扫地游', '赵文', '结庐胜境，似旧日曾游，玉莲佳处。\n万花织组。\n爱回廊宛转，楚腰束素。\n度密穿青，上有燕支万树。\n探梅去。\n正竹外一枝，春意如许。\n奇绝盘谷序。\n更碧皱沿堤，绮霏承宇。\n柳桥花坞。\n问何人解有，玉兰能赋。\n老子婆娑，长与春风作主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17959, '八声甘州', '赵功可', '渺平沙、莽莽海风吹，一寒气崔嵬。\n耿长天欲压，河流不动，云湿如灰。\n帝敕冰花剪刻，飞瑞上燕台。\n马上行人笑，万玉堆。\n漾天衔晴昼，料酒楼歌馆，都是春回。\n喜丰年有象，贺表四方来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17960, '氐州第一', '赵功可', '杨柳楼深，推梦乍起，前山一片愁雨。\n嫩绿成云，飞红欲雪，天亦留春不住。\n借问东风，甚飘泊、天涯何许。\n可惜风流，三生杜枚，少年张绪。\n陌上差差携手去。\n怕行到、歌台旧处。\n落日啼鹃，断烟荒草，吟不成谁语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17961, '曲游春', '赵功可', '千树玲珑罩，正蒲风微过，梅雨新霁。\n客里幽窗，算无春可到，和愁都闭。\n万种人生计。\n应不似、午天闲睡。\n起来踏碎松阴，萧萧欲动疑水。\n借问归舟归未。\n望柳色烟光，何处明媚。\n抖擞人间，除离情别恨，乾坤馀几。\n一笑晴凫起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17962, '声声慢', '赵功可', '情痴倦极，天阔归迟，吟魂无力随风。\n月落墙阴，一屏睡睫。\n邯郸平生难记，记花前、犹醉金锺。\n留连处，忽一声山外，吹度晴钟。\n觉来重重追忆，似游尘飞去，那拾遗踪。\n寄谢芳卿，向来曾主芙蓉。\n人间兴亡万感，看千年、与梦皆空。\n披衣起，倚阑干、人在笑中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17963, '桂枝香', '赵功可', '晓天凉露。\n天上玉箫吹，飞声如雨。\n金阙高寒，闲却一庭梅雨。\n漫漫八表尘埃梦，把文章、洗空千古。\n精神一似，风裳水佩，兰皋蘅浦。\n看万里、跳龙跃虎。\n甚花娇英气，剑清尘妩。\n憔悴江南，应念小窗贫女。\n朱楼十二春无际，倚苍寒、青袖如故。\n茶香酒熟，月明风细，试教歌舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17964, '绮寮怨', '赵功可', '忽忽东风又老，冷云吹晚阴。\n疏帘下、茶鼎孤烟，断桥外、梅豆千林。\n江南庾郎憔悴，睡未醒、病酒愁怎禁。\n倚阑干、一扇凉风，看平地、落花如雪深。\n千曲囊中古琴。\n平泉金谷，不堪旧事重寻。\n当日登临。\n都化作、梦销沈。\n元龙丘坟无恙，谁唤起，共论心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17965, '柳梢青', '赵功可', '一健如仙，东湖烟柳，坐拥吟翁。\n几许功名，百年身世，相见匆匆。\n别来三度秋风。\n怕看见、云间过鸿。\n酒醒灯寒，更残月落，吾美楼中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17966, '柳梢青', '赵功可', '客里凄凉，桐花满地，杜宇深山。\n幸自君来，谁教春去，剪剪轻寒。\n愁怀无语相看。\n谩写入、徽弦自弹。\n小院黄昏，前村风雨，莫倚阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17967, '满江红', '汪宗臣', '检点春光，阴雨过、三分之一。\n从头数、元宵灯夕，都无晴日。\n不碍郊原肥草绿，但漫丘壑沈云黑。\n那东君、忒煞没纲维，春无力。\n燕忙甚，泥浑湿。\n蜂愁甚，脾无蜜。\n更两旬又是，梨花寒食。\n蔫红殷桃吾不较，岂堪浸烂东畴麦。\n望前村、白鹭衬霞红，探晴色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17968, '蝶恋花', '汪宗臣', '年去年来来去早。\n怪底不来，庭院春光老。\n知过谁家翻别调。\n家家望断飞踪。\n千里潇湘烟渺渺。\n不记雕梁，旧日恩多少。\n匝近清明檐外叫。\n故巢犹在朱檐晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17969, '酹江月・念奴娇', '汪宗臣', '白蛇宵断，逐鹿人、交趁罾鱼群起。\n赤帜雄张军缟素，龙种天生大器。\n堪鄙猴冠，自为狼藉，楚帐多尘垒。\n胆寒垓下，一鞭东窜休矣。\n亭长空舣扁舟，范增群辈，尽涂脂流髓。\n望断秦关无限恨，羞面江东山水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17970, '水调歌头', '汪宗臣', '候应黄锺动，吹出百葭灰。\n五云重压头上，潜蛰地中雷。\n莫道希声妙寂，竹雄鸣合凤，九寸律初裁。\n欲识天心处，请问学颜回。\n冷中温，穷时达，信然哉。\n彩云山外如画，送上笔尖来。\n一气先通关窍，万物旋生头角，谁合又谁开。\n官路春光早，箫落数枝梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17971, '湘灵瑟', '刘埙', '酸风泠泠。\n哀笳吹数声。\n碎雨冥冥。\n泣瑶英。\n花心路，芙蓉城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17972, '醉思仙', '刘埙', '琼楼几间。\n瑶徽几弹。\n觅花声绕回阑。\n悄微闻佩环。\n帘栊昼闲。\n炉薰昼残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17973, '点绛唇', '刘埙', '风卷游云，梨云梦冷人何处。\n一溪烟雨。\n遮断垂杨路。\n恨入琴心，能写当时语。\n愁无绪。\n泪痕红蠹。\n犹带香如故。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17974, '浣溪沙', '刘埙', '已断因缘莫更寻。\n寻时烦恼不如心。\n从今休听世间音。\n鸾梦渐随秋水远，鹤情甘伴野云深。\n隔楼花月自阴阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17975, '菩萨蛮', '刘埙', '长亭望断来时路。\n楼台杳霭迷花雾。\n山雨隔窗声。\n思君魂梦惊。\n泪痕侵褥锦。\n闲却鸳鸯枕。\n有泪不须垂。\n金鞍明月归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17976, '菩萨蛮', '刘埙', '故园青草依然绿。\n故宫废址空乔木。\n狐兔穴岩城。\n悠悠万感生。\n胡笳吹汉月。\n北语南人说。\n红紫闹东风。\n湖山一梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17977, '谒金门', '刘埙', '云薄薄。\n人静黄梅院落。\n细数花期并柳约。\n新愁沾一握。\n梦醒从前多错。\n寄恨画檐灵鹊。\n明月欲西天寂寞。\n魂销连晓角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17978, '谒金门', '刘埙', '花雾暖。\n红逗海棠开半。\n毡坐谈经春四换。\n今朝官正满。\n好上鳌坡虎观。\n好近御屏香案。\n休笑吾侬行色缓。\n待君来作伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17979, '谒金门', '刘埙', '眉月小。\n红烛画楼歌绕。\n唱到刘郎频笑道。\n古词今恰好。\n深夜银屏香袅。\n明日雕鞍尘杳。\n一饷春风容易晓。\n三生思不了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17980, '谒金门', '刘埙', '春正媚。\n闲步武陵源里。\n千树霞蒸红散绮。\n一枝高插髻。\n飞过洞庭烟水。\n酩酊莫教花坠。\n铅鼎温温神谒帝。\n何曾真是醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17981, '清平乐', '刘埙', '铿金戛玉。\n弹就神仙曲。\n铁拨弦清更熟。\n新腔浑胜俗。\n教坊尽道名师。\n声华都处俱知。\n指日内前宣唤，云韶独步丹墀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17982, '太常引', '刘埙', '甘棠春色满南丰。\n春好处、在黉宫。\n宫柳映墙红。\n对墙柳、常思耐翁。\n文章太守，词华哲匠，人与易居东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17983, '柳梢青', '刘埙', '青鸟西沈，彩鸾北去，月冷河桥。\n梦事荒凉，垂杨暗老，几度魂销。\n云边音信迢迢。\n把楚些、凭谁为招。\n万叠清愁，西风横笛，吹落寒潮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17984, '恋绣衾', '刘埙', '轻风吹雾月满廊。\n芙蕖香、飘入隔窗。\n记旧月、闲庭院，擘碎红、蒙幂晓妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17985, '临江仙', '刘埙', '朔雪驱将残腊去，东风放出新晴。\n绣衣瑞彩照岩城。\n江天收宿霭，湖水动春声。\n要净狐嗥并鳝舞，未烦鹤怨猿惊。\n元龙老气正峥嵘。\n毫端肤寸润，野烧绿痕生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17986, '洞仙歌', '刘埙', '津亭折柳，正秋光如画。\n绕路黄花拥朝马。\n叹市槐景淡，池藻波寒，分明是、三载春风难舍。\n军峰天际碧，云隔空同，无奈相思月明夜。\n薇药早催人，应占先春，休如我、醉卧水边林下。\n待来岁、今时庆除书，绣锦映宫花，玉京随驾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17987, '西湖明月引・江城梅花引', '刘埙', '江村烟雨暗萧萧。\n涨寒潮。\n送春桡。\n目断京尘，何日听鸾箫。\n金雀觚棱千里外，指天际，碧云深，魂欲飘。\n薰炉炷愁烟尽销。\n酒孤斟、谁与招。\n满怀情思，任吟笺、赋笔难描。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17988, '意难忘', '刘埙', '汀柳初黄。\n送流车出陌，别酒浮觞。\n乱山迷去路，空阁带馀香。\n人渐远，意凄凉。\n更暮雨淋浪。\n悔不办，窄衫细马，两两交相。\n春梁语燕犹双。\n叹晓窗新月，独照刘郎。\n寄笺频误约，临镜想慵妆。\n知几梦，恼愁肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17989, '六么令', '刘埙', '晓来寒角，吹起愁相触。\n乱云黯淡江渚，疏柳双鸦宿。\n锦瑟银屏何处，花雾翻香曲。\n柔红娇绿。\n魂消往梦，羞向孤梅说幽独。\n燕支曾印素袂，绛艳收残馥。\n频问讯，道新来闷损纤腰束。\n多谢芳心恋，罗结文鸳蹴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17990, '满庭芳', '刘埙', '帘卷疏，楼平危堞，几回笋玉凭阑。\n觅花呼酒，更共理哀弹。\n暖日柔风好景，行云绕、莺燕翩翻。\n谁知道，冶游重到，已付解连环。\n乘云，行处去，花深隔院，应恨春闲。\n但紫骝嘶度，时望重关。\n长恨江楼柳老，女郎腰、又负眠三。\n东城路，一回一感，愁见月儿弯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17991, '天香', '刘埙', '雨秀风明，烟柔雾滑，魏家初试娇紫。\n翠羽低云，檀心晕粉，独冠洛京新谱。\n沈香醉墨，曾赋与、昭阳仙侣。\n尘世几经朝暮，花神岂知今古。\n愁听流莺自语，叹唐宫、草青如许。\n空有天边浩月，见霓裳舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17992, '烛影摇红', '刘埙', '院落黄昏，残霞收尽廉纤雨。\n天香富贵洛阳城，巧费春工作。\n自笑平生吟苦。\n写不尽、此花风度。\n玉堂银烛，翠幄画阑，万红争妒。\n那更深宵，寒光幻出清都府。\n嫦娥跨影下人间，来按红鸾舞。\n连夜杯行休驻。\n生怕化、彩云飞去。\n酒阑人静，月淡尘清，晓风轻露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17993, '长相思', '刘埙', '雾隔平林，风欺败褐，十分秋满黄华。\n荒庭人静，声惨寒蛩，惊回羁思如麻。\n庾信多愁，有中宵清梦，迢递还家。\n楚水绕天涯。\n黯消魂、几度栖鸦。\n对绿橘黄橙，故园在念，怅望归路犹赊。\n此情吟不尽，被西风、吹入胡笳。\n目极黄云，飞渡处、临流自嗟。\n又斜阳，征鸿影断，夜来空信灯花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17994, '选冠子', '刘埙', '暝霭迷红，水天笼晓，帆去野潮声急。\n离鸾独倚，巧燕双飞，忍向东风飘拆。\n尘销紫曲阑干，筝雁成声，顿成孤臆。\n叹舟回人远，钿花芗泽，悄无痕迹。\n憔悴损，俊赏杜郎，多情荀令，欲写别愁无力。\n闽星南转，江月西沈，空拟梦来今夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17995, '惜馀春慢・选冠子', '刘埙', '玉勒丝鞭，彩旗红索，总向愁中休了。\n偏怜景媚，为甚愁浓，都为雨多晴少。\n桃杏开到梨花，红印香印，绿平幽沼。\n也无饶、红药殿春，更作薄寒清峭。\n尘梦里、暗换年华，东风能几，又把一番春老。\n莺花过眼，蚕麦当头，朝日浓阴笼晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17996, '买陂塘・摸鱼儿', '刘埙', '暮云沈、凄凄花陌，荒苔青润鸳。\n娇红一捻不胜春，苦雨酸雨。\n从别後。\n但暗忆娉婷，几把垂杨蹂。\n香销韩袖。\n念莺燕悲吟，凤鸾仙去，空负摘花手。\n铜铺掩，窥见文窗依旧。\n筝琶尘暗弦绉。\n欲圆春梦今犹未，怪得西飞太骤。\n凝伫久。\n拟待倩、鸿都羽客寻仙偶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17997, '买陂塘・摸鱼儿', '刘埙', '倚楼西、西风惊鬓，吹回尘思萧瑟。\n碧桃花下骖鸾梦，十载雨沈云隔。\n空自忆。\n漫红蜡香笺，难写旧凄恻。\n烟村水国。\n欲闲却琴心，蠹残箧面，老尽看花客。\n河桥侧。\n曾试雕鞍玉勒。\n如今已忘南北。\n人间纵有垂杨在，欲挽一丝无力。\n君莫拍。\n浑不似、年时爱听酒边笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17998, '贺新郎', '刘埙', '办著春游费。\n奈狂风吹寒，禁定满城花事。\n天暝云深时度雨。\n院落秦筝未试。\n倩谁趱、杏娇桃媚。\n韶色三停今过一，只淡黄杨柳装愁思。\n芳径滑，绣窗闭。\n玉炉闷炷香温被。\n忆去年、匆匆胜赏，梦沈烟水。\n遥望秋千新彩索，难把旧痕重系。\n待暖入、香红十里。\n别拥双鸾迎素月，教明年、不恨今憔悴。\n莺共燕，汝知未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (17999, '贺新郎', '刘埙', '莫笑刘郎老。\n老刘郎平生，不是山林怀抱。\n梦里风云翻海岳，觉後狂歌坠帽。\n叹几度、荒鸡误晓。\n天际晴云开五色，纵今年、意气犹年少。\n机事远，有时到。\n凯歌檄笔凭谁道。\n对村中、一溪流水，半林斜照。\n赖有可人堪话旧，时共掀髯绝倒。\n也来问、衮衣茸帽。\n聊且问天占百岁，看乾坤、此事如何了。\n肠断处，春城早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18000, '贺新郎', '刘埙', '醉里江南路。\n问梅花、经年冷落，几番烟雨。\n玉骨冰肌终是别，犹带孤山瑞露。\n想蕴藉、和羹风度。\n万紫千红羡妒早，羡仙标、岂比人间侣。\n聊玩弄，六花舞。\n云寒木落山城暮。\n忽飘来、暗香万斛，春浮江浦。\n茅舍竹篱词客老，拟傍东风千树。\n看好月、亭亭当午。\n流水村中清浅处，称横斜疏影相容与。\n时索笑，想应许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18001, '太常引', '王清观', '邯郸梦里武陵溪。\n春色醉冥迷。\n花压帽檐欹，谩赢得、红尘满衣。\n青蛇飞起，黄龙喝住，才是酒醒时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18002, '满庭芳', '熊则轩', '波有颓澜，渴无冷镬，谁言制邑为难。\n汾阳善政，只在笑谈间。\n三载刑清讼简，官事辨、俗阜民安。\n帘垂昼，焚香宴坐，犹得半清闲。\n西风，催入觐，声驰当道，名达朝端。\n任锦溪溪上，卧辙攀辕。\n从此燕辕北去，好官样、留与人看。\n扁舟稳，图书外，惟有月俱还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18003, '大江乘・念奴娇', '阮溪', '东阳四载，但好事、一一为民做了。\n谈笑半闲风月里，管甚讼庭生草。\n瓯茗炉香，菜羹淡饭，此外无烦恼。\n问侯何苦，自饥只要民饱。\n犹念甘旨相违，白云万里，不得随昏晓。\n暂舍苍生归定省，回首又看父老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18004, '风流子', '危西麓', '西风吹锦水，朝天路、冉冉两凫飞。\n看父老袅花，苦遮去辙，儿童骑竹，争问归期。\n帐簇马前纷蔽日，实绩纪行碑。\n冰饮三年，从容官事，棠阴百里，悠久民思。\n圣明衿遐远，关山道，应是来骤华丝。\n画绣过家，莱庭彩舞斑衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18005, '满江红', '汪元量', '一个兰舟，双桂桨、顺流东去。\n但满目、银光万顷，凄其风露。\n渔火已归鸿雁汊，棹歌更在鸳鸯浦。\n渐夜深、芦叶冷飕飕，临平路。\n吹铁笛，鸣金谷。\n丝玉脍，倾香醑。\n且浩歌痛饮，藕花深处。\n秋水长天迷远望，晓风残月空凝伫。\n问人间、今夕是何年，清如许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18006, '金人捧露盘', '汪元量', '越山云，越江水，越王台。\n个中景、尽可徘徊。\n凌高放目，使人胸次共崔嵬。\n黄鹂紫燕报春晚，劝我衔杯。\n古时事，今时泪，前人喜，後人哀。\n正醉里、歌管成灰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18007, '相思引', '汪元量', '晓拂菱花巧画眉。\n猩罗新翦作春衣。\n恐春归去，无处看花枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18008, '长相思', '汪元量', '吴山深。\n越山深。\n空谷佳人金玉音。\n有谁知此心。\n夜沈沈。\n漏沈沈。\n闲却梅花一曲琴。\n月高松竹林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18009, '传言玉女', '汪元量', '一片风流，今夕与谁同乐。\n月台花馆，慨尘埃漠漠。\n豪华荡尽，只有青山如洛。\n钱塘依旧，潮生潮落。\n万点灯光，羞照舞钿歌箔。\n玉梅消瘦，恨东皇命薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18010, '好事近', '汪元量', '独倚浙江楼，满耳怨笳哀笛。\n犹有梨园声在，念那人天北。\n海棠憔悴怯春寒，风雨怎禁得。\n回首华清池畔，渺露芜烟荻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18011, '洞仙歌', '汪元量', '西园春暮。\n乱山迷行路。\n风卷残花堕红雨。\n念旧巢燕子，飞傍谁家，斜阳外、长笛一声今古。\n繁华流水去。\n舞歇歌沈，忍见遗钿种香土。\n渐橘树方生，桑枝才长，都付与、沙门为主。\n便关防、不放贵游来，又突兀梯空，楚王宫宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18012, '莺啼序', '汪元量', '金陵故都最好，有朱楼迢递。\n嗟倦客、又此凭高，槛外已少佳致。\n更落尽梨花，飞尽杨花，春也成憔悴。\n问青山、三国英雄，六朝奇伟。\n麦甸葵丘，荒台败垒。\n鹿豕衔枯荠。\n正朝打孤城，寂寞斜阳影里。\n听楼头、哀笳怨角，未把酒、愁心先醉。\n渐夜深，月满秦淮，烟笼寒水。\n凄凄惨惨，冷冷清清，灯火渡头市。\n慨商女不知兴废。\n隔江犹唱庭花，馀音。\n伤心千古，泪痕如洗。\n乌衣巷口青芜路，认依稀、王谢旧邻里。\n临春结绮。\n可怜红粉成灰，萧索白杨风起。\n因思畴昔，铁索千寻，谩沈江底。\n挥羽扇、障西尘，便好角巾私第。\n清谈到底成何事。\n回首新亭，风景今如此。\n楚囚对泣何时已。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18013, '六州歌头', '汪元量', '绿芜城上，怀古恨依依。\n淮山碎。\n江波逝。\n昔人非。\n今人悲。\n惆怅隋天子。\n锦帆里。\n环朱履。\n丛香绮。\n展旌旗。\n荡涟猗。\n击鼓挝金，拥琼玉吹。\n姿意游嬉。\n斜日晖晖。\n乱莺啼。\n销魂此际。\n君臣醉。\n貔貅弊。\n事如飞。\n山河坠。\n烟尘起。\n风凄凄。\n雨霏霏。\n草木皆垂泪。\n家国弃。\n竟忘归。\n笙歌地。\n欢娱地。\n尽荒畦。\n唯有当时皓月，依然挂、杨柳青枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18014, '水龙吟', '汪元量', '鼓惊破霓裳，海棠亭北多风雨。\n歌阑酒罢，玉啼金泣，此行良苦。\n驼背模糊，马头匝，朝朝暮暮。\n自都门燕别，龙艘锦缆，空载得、春归去。\n目断东南半壁，怅长淮、已非吾土。\n受降城下，草如霜白，凄凉酸楚。\n粉阵红围，夜深人静，谁宾谁主。\n对渔灯一点，羁愁一搦，谱琴中语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18015, '望江南・忆江南', '汪元量', '官舍悄，坐到月西斜。\n永夜角声悲自语，客心愁破正思家。\n南北各天涯。\n肠断裂，搔首一长嗟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18016, '卜算子', '汪元量', '我向河南来，伊向河西去。\n客里相逢只片时，无计留伊住。\n去住总由伊，莫把眉头聚。\n安得并州快剪刀，割断相思路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18017, '满江红', '汪元量', '天上人家，醉王母、蟠桃春色。\n被午夜、漏声催箭，晓光侵阙。\n花覆千官鸾阁外，香浮九鼎龙楼侧。\n恨黑风、吹雨湿霓裳，歌声歇。\n人去後，书应绝。\n肠断处，心难说。\n更那堪杜宇，满山啼血。\n事去空流东汴水，愁来不见西湖月。\n有谁知、海上泣蝉娟，菱花缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18018, '满江红', '汪元量', '一霎浮云，都掩尽、日无光色。\n遥望处、浮图对峙，梵王新阙。\n燕子自飞关北外，杨花闲度楼西侧。\n慨金鞍、玉勒早朝人，经年歇。\n昭君去，空愁绝。\n文姬去，难言说。\n想琵琶哀怨，流泪成血。\n蝴蝶梦中千种恨，杜鹃声里三更月。\n最无情、鸿雁自南飞，音书缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18019, '一翦梅', '汪元量', '十年愁眼泪巴巴。\n今日思家。\n明日思家。\n一团燕月照窗纱。\n楼上胡笳。\n塞上胡笳。\n玉人劝我酌流霞。\n急拈琵琶。\n缓拈琵琶。\n一从别後各天涯。\n欲寄梅花。\n莫寄梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18020, '惜分飞', '汪元量', '燕子留君君欲去。\n征马频嘶不住。\n握手空相觑。\n泪珠成缕。\n眉峰聚。\n恨入金徽孤凤语。\n愁得文君更苦。\n今夜西窗雨。\n断肠能赋。\n江南句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18021, '唐多令', '汪元量', '莎草被长洲。\n吴江拍岸流。\n忆故家、西北高楼。\n十载客窗憔悴损，搔短鬓、独悲秋。\n人在塞边头。\n断鸿书寄不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18022, '鹧鸪天', '汪元量', '潋滟湖光绿正肥。\n苏堤十里柳丝垂。\n轻便燕子低低舞，小巧莺儿恰恰啼。\n花似锦，酒成池。\n对花对酒两相宜。\n水边莫话长安事，且请卿卿吃蛤蜊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18023, '眼儿媚', '汪元量', '记得年时想荼シ。\n蝴蝶满园飞。\n一双宝马，两行箫管，月下扶归。\n而今寂寞人何处，脉脉泪沾衣。\n空房独守，风穿帘子，雨隔窗儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18024, '忆王孙', '汪元量', '汉家宫阙动高秋。\n人自伤心水自流。\n今日晴明独上楼。\n恨悠悠。\n白尽梨园子弟头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18025, '忆王孙', '汪元量', '吴王此地有楼台。\n风雨谁知长绿苔。\n半醉闲吟独自来。\n小徘徊。\n惟见江流去不回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18026, '忆王孙', '汪元量', '长安不见使人愁。\n物换星移几度秋。\n一自佳人坠玉楼。\n莫淹留。\n远别秦城万里游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18027, '忆王孙', '汪元量', '阵前金甲受降时。\n园客争偷御果枝。\n白发宫娃不解悲。\n理征衣。\n一片春帆带雨飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18028, '忆王孙', '汪元量', '鹧鸪飞上越王台。\n烧接黄云惨不开。\n有客新从赵地回。\n转堪哀。\n岩畔古碑空绿苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18029, '忆王孙', '汪元量', '离宫别苑草萋萋。\n对此如何不泪垂。\n满槛山川漾落晖。\n昔人非。\n惟有年年秋雁飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18030, '忆王孙', '汪元量', '上阳宫里断肠时。\n春半如秋意转迷。\n独坐纱窗刺绣迟。\n泪沾衣。\n不见人归见燕归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18031, '忆王孙', '汪元量', '华清宫树不胜秋。\n云物凄凉拂曙流。\n七夕何人望斗牛。\n一登楼。\n水远山长步步愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18032, '忆王孙', '汪元量', '五陵无树起秋风。\n千里黄云与断蓬。\n人物萧条市井空。\n思无穷。\n惟有青山似洛中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18033, '凤鸾双舞', '汪元量', '慈元殿、薰风宝鼎，喷香云飘坠。\n环立翠羽，双歌丽调，舞腰新束，舞缨新缀。\n金莲步、轻摇彩凤儿，翩翻作戏。\n便似月里仙娥谪来，人间天上，一番游戏。\n圣人乐意。\n任乐部、韶声沸。\n众妃欢也，渐调笑微醉。\n竞奉霞觞，深深愿、圣母寿如松桂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18034, '柳梢青', '汪元量', '滟滟平湖，双双画桨，小小船儿。\n袅袅珠歌，翩翩翠舞，续续弹丝。\n山南山北游□，看十里、荷花未归。\n缓引壶觞，个人未醉，要我吟诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18035, '暗香', '汪元量', '馆娃艳骨。\n见数枝雪里，争开时节。\n底事化工，著衣阳和暗偷泄。\n偏把红膏染质，都点缀、枝头如血。\n最好是、院落黄昏，压栏照水清绝。\n风韵自迥别。\n谩记省故家，玉手曾折。\n翠条袅娜，犹学宫妆舞残月。\n肠断江南倦客，歌未了、琼壶敲缺。\n更忍见，吹万点、满庭绛雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18036, '疏影', '汪元量', '虬枝茜萼。\n使轻盈态度，香透帘幕。\n净洗铅华，浓抹胭脂，风前伴我孤酌。\n诗翁瘦硬□□□，断不被、春风熔铄。\n有陇头、折赠殷勤，又恐暮笳吹落。\n寂寞。\n孤山月夜，玉人万里外，空想前约。\n雁足书沈，马上弦哀，不尽寒阴砂漠。\n昭君滴滴红冰泪，但顾影、未梳掠。\n等恁时、环佩归来，却慰此况萧索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18037, '天香', '汪元量', '迟日侵阶，和风入户，朱弦欲奏还倦。\n一幅鸾笺，五云飞下，赐予内家琴苑。\n音随指动，犹彷佛、虞薰再见。\n妙处谁能解心，和平自无哀怨。\n猩罗帕封古洗，有龙涎、渗花千片。\n骤睹瑶台清品，眼明如电。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18038, '摸鱼儿', '王学文', '记当年、舞衫零乱，霖铃忍按新阕。\n杜鹃枝上东风晚，点点泪痕凝血。\n芳信歇。\n念初试琵琶，曾识关山月。\n悲弦易绝。\n奈笑罢颦生，曲终愁在，谁解寸肠结。\n浮云事，又作南柯梦彻。\n一簪聊寄华发。\n乾坤桑海无穷事，才历昆明初劫。\n谁共说。\n都付与焦桐，写入梅花叠。\n黄花送客。\n休更问湘魂，独醒何在，沈醉浩歌发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18039, '满江红', '王清惠', '太液芙蓉，浑不似、旧时颜色。\n曾记得、春风雨露，玉楼金阙。\n名播兰簪妃后里，晕潮莲脸君王侧。\n忽一声、颦鼓揭天来，繁华歇。\n龙虎散，风云灭。\n千古恨，凭谁说。\n对山河百二，泪盈襟血。\n客馆夜惊尘土梦，宫车晓碾关山月。\n问嫦娥、於我肯从容，同圆缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18040, '长相思', '章丽贞', '吴山秋。\n越山秋。\n吴越两山相对愁。\n长江不尽流。\n风飕飕。\n雨飕飕。\n万里归人空白头。\n南冠泣楚囚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18041, '长相思', '袁正真', '南高峰。\n北高峰。\n南北高峰云淡浓。\n湖山图画中。\n采芙蓉。\n赏芙蓉。\n小小红船西复东。\n相思无路通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18042, '望江南・忆江南', '金德淑', '春睡起，积雪满燕山。\n万里长城横玉带，六街灯火已阑珊，人立蓟楼间。\n空懊恼，独客此时还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18043, '望江南・忆江南', '连妙淑', '寒料峭，独立望长城。\n木落萧萧天远大，□声羌管遏云行。\n归客若为情。\n樽酒尽，勒马问归程。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18044, '望江南・忆江南', '黄静淑', '君去也，晓出蓟门西。\n鲁酒千杯人不醉，臂鹰健卒马如飞。\n回首隔天涯。\n云黯黯，万里雪霏霏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18045, '望江南・忆江南', '陶明淑', '秋夜永，月影上阑干。\n客枕梦回燕塞冷，角声吹彻五更寒。\n无语翠眉攒。\n天渐晚，把酒泪先弹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18046, '望江南・忆江南', '柳华淑', '何处笛，觉妾梦难谐。\n春色恼人眠不得，卷帘移步下香阶。\n呵冻卜金钗。\n人去也，毕竟信音乖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18047, '望江南・忆江南', '杨慧淑', '江北路，一望雪皑皑。\n万里打围鹰隼急，六军刁斗去还来。\n归客别金台。\n江北酒，一饮动千杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18048, '望江南・忆江南', '华清淑', '燕塞雪，片片大如拳。\n蓟上酒楼喧鼓吹，帝城车马走骈阗。\n羁馆独凄然。\n燕塞月，缺了又还圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18049, '望江南・忆江南', '梅顺淑', '风渐软，暖气满天涯。\n莫道穷阴春不透，今朝楼上见桃花。\n花外碾香车。\n围步帐，羯鼓杂琵琶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18050, '望江南・忆江南', '吴昭淑', '今夜永，说剑引杯长。\n坐拥地炉生石炭，灯前细雨好烧香。\n呵手理丝簧。\n君且住，烂醉又何妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18051, '望江南・忆江南', '周容淑', '春去也，白雪尚飘零。\n万里归人骑快马，到家时节藕花馨。\n那更忆长城。\n妾薄命，两鬓渐星星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18052, '霜天晓角', '吴淑真', '塞门桂月。\n蔡琰琴心切。\n弹到笳声悲处，千万恨、不能雪。\n愁绝。\n泪还北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18053, '满江红', '张琼英', '太液芙蓉，浑不似、丹青颜色。\n常记得、春风雨露，玉楼金阙。\n名播兰簪妃后里，晕生莲脸君王侧。\n忽一声、颦鼓拍天来，繁华歇。\n龙虎散，风云灭。\n千古恨，凭谁说。\n对山河百二，泪痕沾血。\n客馆夜惊尘土梦，宫车晓转关山月。\n问嫦娥、垂顾肯相容，同圆缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18054, '霓裳中序第一', '詹玉', '一规古蟾魄。\n瞥过宣和几春色。\n知那个、柳松花怯。\n曾磋玉团香，涂云抹月。\n龙章凤刻。\n是如何、儿女消得。\n便孤了、翠鸾何限，人更在天北。\n磨灭。\n古今难别。\n幸相从、蓟门仙客。\n萧然林下秋叶。\n对云淡星疏，眉青影白。\n佳人已倾国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18055, '汉宫春', '詹玉', '吟发萧萧。\n正古槎秋入，河汉银涛。\n红云甚家院落，一片笙箫。\n晋时言语，问何人、还肯逍遥。\n知几度、落花啼鸟，乡歌犹在儿曹。\n游帷旧时明月，照满庭空翠，剪剪春梢。\n西山笑人底事，流浪宫袍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18056, '多丽', '詹玉', '晚云归，小楼又作阴凉。\n霎儿间，恨桐招雨，西风叶叶商量。\n醒时心、又还南浦，愁边句、多在夕阳。\n菱碗笼青，莲瓶拖艳，旋倾花水咽茶香。\n怨蛩有、许多言语，说动软心肠。\n夜沈沈，几条凉月，界破晴窗。\n共绣帘吹絮未久，却孤剑水云乡。\n自家书、未能成字，邻家笛、且莫吹商。\n好梦偏悭，闲情未了，隔墙又唱秋娘。\n帕绡衣、旧时香折，戏封做书囊。\n鸳鸯字，见时千万，绣一双双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18057, '桂枝香', '詹玉', '紫薇花露，潇洒作凉云，点商勾羽。\n字字飞仙，下笔一帘风雨。\n江亭月观今如许。\n叹飘零、墨香千古。\n夕阳芳草，落花流水，依然南浦。\n甚两两、凌风驾虎。\n恁天孙标致，月娥眉妩。\n一笑生春，那学世间儿女。\n笔床砚滴曾窥处，有西山、青眼如故。\n素笺寄与，玉箫声彻，凤鸣鸾舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18058, '渡江云', '詹玉', '拖阴笼晚暝，商量清苦，阵阵打篷声。\n分明都是泪，不道今宵，篷底有离人。\n松涛摇睡，梦不稳、难湿巫云。\n几点儿、泪痕跳响，休要醒时听。\n销魂。\n灯下无语，□泣梨花，掩重门夜永。\n应是添、伤春滋味，中酒心情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18059, '三姝媚', '詹玉', '一篷儿别苦。\n是谁家、花天月地儿女。\n紫曲藏娇，惯锦窠金翠，玉锺吕。\n绮席传宣，笑声里、龙楼三鼓。\n歌扇题诗，舞袖笼香，几曾尘土。\n因甚留春不住。\n怎知道人间，匆匆今古。\n金屋银屏，被西风吹换，蓼汀苹渚。\n如此江山，应悔却、西湖歌舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18060, '一萼红', '詹玉', '泊沙河。\n月钩儿挂浪，惊起两鱼梭。\n浅碧依痕，嫩凉生润，山色轻染修蛾。\n钓船在、绿杨阴下，蓦听得、扇底有吴歌。\n一段风情，西湖和靖，赤壁东坡。\n往事水流云去，叹山川良是，富贵人多。\n老树高低，疏星明淡，只有今古销磨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18061, '齐天乐', '詹玉', '相逢唤醒金华梦，吴尘暗斑吟发。\n倚担评花，认旗沽酒，历历行歌奇迹。\n吹香弄碧。\n又坡柳风情，逋梅月色。\n画鼓红船，满湖春水断桥客。\n当时何限怪侣，甚花天月地，人被云隔。\n却载苍烟，更招白鹭，一醉修江又别。\n今回记得。\n再折柳穿鱼，赏花催雪。\n如此湖山，忍教人更说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18062, '阮郎归', '詹玉', '斜河一道界相思。\n好秋都上眉。\n鸾笺象管写心啼。\n搦愁题做诗。\n添别恨，卜欢期。\n灯花红几时。\n看看月上小窗儿。\n夜香今夜迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18063, '八声甘州', '詹玉', '从黄石容履，一编书，曾佐汉王关。\n甚殷勤佳约，茹芝人共，引鹤差鸾。\n借手便成羽翼，方略正如闲。\n说道赤松去，还在人间。\n紫绶青春如许，是南辰尊宿，北斗天官。\n问沙堤早晚，喜色满长安。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18064, '桂枝香', '詹玉', '沈云别浦。\n又何苦扁舟，青衫尘土。\n客里相逢，洒洒舌端飞雨。\n只今便把如伊吕。\n是当年、渔翁樵父。\n少知音者，苍烟吾社，白鸥吾侣。\n是如此英雄辛苦。\n知从前、几个适齐去鲁。\n一剑西风，大海鱼龙掀舞。\n自来多被清谈误。\n把刘琨、埋没千古。\n扣舷一笑，夕阳西下，大江东去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18065, '浣溪沙', '詹玉', '淡淡青山两点春。\n娇羞一点口儿樱。\n一梭儿玉一啤０着合阒屑髯樱衩坊ㄏ掠稣丫２辉娓鲆蚕辍');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18066, '庆清朝慢・庆清朝', '詹玉', '红雨争妍，芳尘生润，将春都揉成泥。\n分明蕙风薇露，持搦花枝。\n款款汗酥薰透，娇羞无奈湿云痴。\n偏厮称，霓裳霞佩，玉骨冰肌。\n梅不似，兰不似，风流处，那更著意闻时。\n蓦地生绡扇底，嫩凉浮动好风微。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18067, '天香', '王沂孙', '孤峤蟠烟，层涛蜕月，骊宫夜采铅水。\n讯远槎风，梦深薇露，化作断魂心字。\n红瓷候火，还乍识、冰环玉指。\n一缕萦帘翠影，依稀海天云气。\n几回娇半醉。\n翦春灯、夜寒花碎。\n更好故溪飞雪，小窗深闭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18068, '花犯', '王沂孙', '古婵娟，苍鬟素靥，盈盈瞰流水。\n断魂十里。\n叹绀缕飘零，难系离思。\n故山岁晚谁堪寄。\n琅聊自倚。\n谩记我、绿蓑冲雪，孤舟寒浪里。\n三花两蕊破蒙茸，依依似有恨，明珠轻委。\n云卧稳，蓝衣正、护春憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18069, '露华', '王沂孙', '绀葩乍坼。\n笑烂漫娇红，不是春色。\n换了素妆，重把青螺轻拂。\n旧歌共渡烟江，却占玉奴标格。\n风霜峭、瑶台种时，付与仙骨。\n闲门昼掩凄侧。\n似淡月梨花，重化清魄。\n尚带睡痕香凝，怎忍攀摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18070, '露华', '王沂孙', '晚寒伫立，记铅轻黛浅，初认冰魂。\n绀罗衬玉，犹凝茸唾香痕。\n净洗妒春颜色，胜小红、临水湔裙。\n烟渡远，应怜旧曲，换叶移根。\n山中去年人到，怪月悄风轻，闲掩重门。\n琼肌瘦损，那堪燕子黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18071, '南浦', '王沂孙', '柳下碧粼粼，认麴尘乍生，色嫩如染。\n清溜满银塘，东风细、参差纹初遍。\n别君南浦，翠眉曾照波痕浅。\n再来涨绿迷旧处，添却残红几片。\n葡萄过雨新痕，正拍拍轻鸥，翩翩小燕。\n帘影蘸楼阴，芳流去，应有泪珠千点。\n沧浪一舸，断魂重唱苹花怨。\n采香幽径鸳鸯睡，谁道湔裙人远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18072, '南浦', '王沂孙', '柳外碧连天，漾翠纹渐平，低蘸云影。\n应是雪初消，巴山路、蛾眉乍窥清镜。\n绿痕无际，几番漂荡江南恨。\n弄波素袜知甚处，空把落红流尽。\n何时橘里莼乡，泛一舸翩翩，东风归兴。\n孤梦绕沧浪，苹花岸、漠漠雨昏烟暝。\n连筒接缕，故溪深掩柴门静。\n只愁双燕衔芳去，拂破蓝光千顷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18073, '声声慢', '王沂孙', '风声从臾，云意商量，连朝滕六迟疑。\n茸帽貂裘，兔园准拟吟诗。\n红炉旋添兽炭，办金船、羔酒熔脂。\n问翦水，恁工夫犹未，还待何时。\n休被梅花争白，好夸奇斗巧，早遍琼枝。\n彩索金铃，佳人等塑狮儿。\n怕寒绣帏慵起，梦梨云、说与春知。\n莫误了，约王猷、船过剡溪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18074, '高阳台', '王沂孙', '霜楮刳皮，冰花擘茧，满腔絮湿湘帘。\n抱瓮工夫，何须待吐吴蚕。\n水香玉色难裁翦，更绣针、茸线休拈。\n伴梅花，暗卷春风，斗帐孤眠。\n篝熏鹊锦熊毡。\n任粉融脂，犹怯痴寒。\n我睡方浓，笑他欠此清缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18075, '疏影', '王沂孙', '琼妃卧月。\n任素裳瘦损，罗带重结。\n石径春寒，碧藓参差，相思曾步芳。\n离魂分破东风恨，又梦入、水孤云阔。\n算如今、也厌娉婷，带了一痕残雪。\n犹记冰奁半掩，冷枝画未就，归棹轻折。\n几度黄昏，忽到窗前，重想故人初别。\n苍虬欲卷涟漪去，慢蜕却、连环香骨。\n早又是，翠荫蒙茸，一似一枝清绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18076, '无闷', '王沂孙', '阴积龙荒，寒度雁门，西北高楼独倚。\n怅短景无多，乱山如此。\n欲唤飞琼起舞，怕搅碎、纷纷银河水。\n冻云一片，藏花护玉，未教轻坠。\n清致。\n悄无似。\n有照水一枝，已搀春意。\n误几度凭栏，莫愁凝睇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18077, '眉妩', '王沂孙', '渐新痕悬柳，澹彩穿花，依约破初暝。\n便有团圆意，深深拜，相逢谁在香径。\n画眉未稳，料素娥、犹带离恨。\n最堪爱、一曲银钩小，宝帘挂秋冷。\n千古盈亏休问。\n叹慢磨玉斧，难补金镜。\n太液池犹在，凄凉处、何人重赋清景。\n故山夜永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18078, '水龙吟', '王沂孙', '晓寒慵揭珠帘，牡丹院落花开未。\n玉栏干畔，柳丝一把，和风半倚。\n国色微酣，天香乍染，扶春不起。\n自真妃舞罢，谪仙赋後，繁华梦、如流水。\n池馆家家芳事。\n记当时、买栽无地。\n争如一朵，幽人独对，水边竹际。\n把酒花前，剩拚醉了，醒来还醉。\n怕洛中、春色匆匆，又入杜鹃声里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18079, '水龙吟', '王沂孙', '世间无此娉婷，玉环未破东风睡。\n将开半敛，似红还白，馀花怎比。\n偏占年华，禁烟才过，夹衣初试。\n叹黄州一梦，燕宫绝笔，无人解、看花意。\n犹记华阴同醉。\n小阑干、月高人起。\n千枝媚色，一庭芳景，清寒似水。\n银烛延娇，绿房留艳，夜深花底。\n怕明朝、小雨，便化作燕支泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18080, '水龙吟', '王沂孙', '晓霜初著青林，望中故国凄凉早。\n萧萧渐积，纷纷犹坠，门荒径悄。\n渭水风生，洞庭波起，几番秋杪。\n想重崖半没，千峰尽出，山中路、无人到。\n前度题红杳杳。\n溯宫沟、暗流空绕。\n啼未歇，飞鸿欲过，此时怀抱。\n乱影翻窗，碎声敲砌，愁人多少。\n望吾庐甚处，只应今夜，满庭谁扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18081, '水龙吟', '王沂孙', '淡妆不扫蛾眉，为谁伫立羞明镜。\n真妃解语，西施净洗，娉婷顾影。\n薄露初匀，纤尘不染，移根玉井。\n想飘然一叶，飕飕短发，中流卧、浮烟艇。\n可惜瑶台路迥。\n抱凄凉、月中难认。\n相逢还是，冰壶浴罢，牙床酒醒。\n步袜空留，舞裳微褪，粉残香冷。\n望海山依约，时时梦想，素波千顷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18082, '水龙吟', '王沂孙', '翠云遥拥环妃，夜深按彻霓裳舞。\n铅华净洗，涓涓出浴，盈盈解语。\n太液荒寒，海山依约，断魂何许。\n甚人间、别有冰肌雪艳，娇无奈、频相顾。\n三十六陂烟雨。\n旧凄凉、向谁堪诉。\n如今谩说，仙姿自洁，芳心更苦。\n罗袜初停，玉还解，早凌波去。\n试乘风一叶，重来月底，与修花谱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18083, '绮罗香', '王沂孙', '屋角疏星，庭阴暗水，犹记藏鸦新树。\n试折梨花，行人小阑深处。\n听粉片、簌簌飘阶，有人在、夜窗无语。\n料如今，门掩孤灯，画屏尘满断肠句。\n佳期浑似如水，还见梧桐几叶，轻敲朱户。\n一片秋声，应作两边愁绪。\n江路远、归雁无凭，写绣笺、倩谁将去。\n谩无聊，犹掩芳樽，醉听深夜雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18084, '绮罗香', '王沂孙', '玉杵馀丹，金刀剩彩，重染吴江孤树。\n几点朱铅，几度怨啼秋暮。\n惊旧梦、绿鬓轻凋，诉新恨、绛唇微注。\n最堪怜，同拂新霜，绣蓉一镜晚妆妒。\n千林摇落渐少，何事西风老色，争妍如许。\n二月残花，空误小车山路。\n重认取，流水荒沟，怕犹有、寄情芳语。\n但凄凉、秋苑斜阳，冷枝留醉舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18085, '绮罗香', '王沂孙', '夜滴研朱，晨妆试酒，寒树偷分春艳。\n赋冷吴江，一片试霜犹浅。\n惊汉殿、绛点初凝，认隋苑、彩枝重翦。\n问仙丹，炼熟何迟，少年色换已秋晚。\n疏枝频撼暮雨，消得西风几度，舞衣吹断。\n绿水荒沟，终是赋情人远。\n空一似、零落桃花，又等闲、误他刘阮。\n且留取，闲写幽情，石阑三四片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18086, '齐天乐', '王沂孙', '碧痕初化池塘草，荧荧野光相趁。\n扇薄星流，盘明露滴，零落秋原飞磷。\n练裳暗近。\n记穿柳生凉，度荷分暝。\n误我残编，翠囊空叹梦无准。\n楼阴时过数点，倚阑人未睡，曾赋幽恨。\n汉苑飘苔，秦陵坠叶，千古凄凉不尽。\n何人为省。\n但隔水馀晖，傍林残影。\n已觉萧疏，更堪秋夜永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18087, '齐天乐', '王沂孙', '绿槐千树西窗悄，厌厌昼眠惊起。\n饮露身轻，吟风翅薄，半翦冰笺谁寄。\n凄凉倦耳。\n漫重拂琴丝，怕寻冠珥。\n短梦深宫，向人犹自诉憔悴。\n残虹收尽过雨，晚来频断续，都是秋意。\n病叶难留，纤柯易老，空忆斜阳身世。\n窗明月碎。\n甚已绝馀音，尚遗枯蜕。\n鬓影参差，断魂青镜里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18088, '齐天乐', '王沂孙', '一襟馀恨宫魂断，年年翠阴庭树。\n乍咽凉柯，还移暗叶，重把离愁深诉。\n西窗过雨。\n怪瑶佩流空，玉筝调柱。\n镜暗妆残，为谁娇鬓尚如许。\n铜仙铅泪似洗，叹携盘去远，难贮零露。\n病翼惊秋，枯形阅世，消得斜阳几度。\n馀音更苦。\n甚独抱清高，顿成凄楚。\n谩想薰风，柳丝千万缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18089, '齐天乐', '王沂孙', '冷烟残水山阴道，家家拥门黄叶。\n故里鱼肥，初寒雁落，孤艇将归时节。\n江南恨切。\n问还与何人，共歌新阙。\n换尽秋芳，想渠西子更愁绝。\n当时无限旧事，叹繁华似梦，如今休说。\n短褐临流，幽怀倚石，山色重逢都别。\n江云冻结。\n算只有梅花，尚堪攀折。\n寄取相思，一枝和夜雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18090, '齐天乐', '王沂孙', '十洲三岛曾行处，离情几番凄惋。\n坠叶重题，枯条旧折，萧飒那逢秋半。\n登临顿懒。\n更葵难留，苎衣将换。\n试语孤怀，岂无人与共幽怨。\n迟迟终是也别，算何如趁取，凉生江满。\n挂月催程，收风借泊，休忆征帆已远。\n山阴路畔。\n纵鸣壁犹蛩，过楼初雁。\n政恐黄花，笑人归较晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18091, '一萼红', '王沂孙', '思飘飘。\n拥仙姝独步，明月照苍翘。\n花候犹迟，庭阴不扫，门掩山意萧条。\n抱芳恨、佳人分薄，似未许、芳魄化春娇。\n雨涩风悭，雾轻波细，湘梦迢迢。\n谁伴碧樽雕俎，笑琼肌皎皎，绿鬓萧萧。\n青凤啼空，玉龙舞夜，遥睇河汉光摇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18092, '一萼红', '王沂孙', '玉婵娟。\n甚春馀雪尽，犹未跨青鸾。\n疏萼无香，柔条独秀，应恨流落人间。\n记曾照、黄昏淡月，渐瘦影、移上小阑干。\n一点清魂，半枝空色，芳意班班。\n重省嫩寒清晓，过断桥流水，问信孤山。\n冰粟微销，尘衣不浣，相见还误轻攀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18093, '一萼红', '王沂孙', '占芳菲。\n趁东风妩媚，重拂淡燕支。\n青凤衔丹，琼奴试酒，惊换玉质冰姿。\n甚春色、江南太早，有人怪、和雪杏花飞。\n藓佩萧疏，茜裙零乱，山意霏霏。\n空惹别愁无数，照珊瑚海影，冷月枯枝。\n吴艳离魂，蜀妖泪，孤负多少心期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18094, '一萼红', '王沂孙', '翦丹云。\n怕江皋路冷，千叠护清芬。\n弹泪绡单，凝妆枕重，惊认消瘦冰魂。\n为谁趁、东风换色，任绛雪、飞满绿罗裙。\n吴苑双身，蜀城高髻，忽到柴门。\n欲寄故人千里，恨燕支太薄，寂寞春痕。\n玉管难留，金樽易泣，几度残醉纷纷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18095, '一萼红', '王沂孙', '小庭深。\n有苍苔老树，风物似山林。\n侵户清寒，捎池急雨，时听飞过啼禽。\n扫荒径、残梅似雪，甚过了、人日更多阴。\n压酒人家，试灯天气，相次登临。\n犹记旧游亭馆，正垂杨引缕，嫩草抽簪。\n罗带同心，泥金半臂，花畔低唱轻斟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18096, '解连环', '王沂孙', '万珠悬碧。\n想炎荒树密，□□□□。\n恨绛娣、先整吴帆，政鬟翠逞娇，故林难别。\n岁晚相逢，荐青子、独夸冰颊。\n点红盐乱落，最是夜寒，酒醒时节。\n霜槎猬芒冻裂。\n把孤花细嚼，时咽芳冽。\n断味惜、回涩馀甘，似重省家山，旧游风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18097, '三姝媚', '王沂孙', '蓝缸花半绽。\n正西窗凄凄，断萤新雁。\n别久逢稀，谩相看华发，共成销黯。\n总是飘零，更休赋、梨花秋苑。\n何况如今，离思难禁，俊才都减。\n今日山高江浅。\n又月落帆空，酒醒人远。\n彩袖乌纱，解愁人、惟有断歌幽婉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18098, '三姝媚', '王沂孙', '红缨悬翠葆。\n渐金铃枝深，瑶阶花少。\n万颗燕支，赠旧情、争奈弄珠人老。\n扇底清歌，还记得、樊姬娇小。\n几度相思，红豆都销，碧丝空袅。\n芳意荼シ开早。\n正夜色瑛盘，素蟾低照。\n荐笋同时，叹故园春事，已无多了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18099, '庆清朝', '王沂孙', '玉局歌残，金陵句绝，年年负却薰风。\n西邻窈窕，独怜入户飞红。\n前度绿阴载酒，枝头色比舞裙同。\n何须拟，蜡珠作蒂，缃彩成丛。\n谁在旧家殿阁，自太真仙去，扫地春空。\n朱幡护取，如今应误花工。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18100, '庆宫春・高阳台', '王沂孙', '明玉擎金，纤罗飘带，为君起舞回雪。\n柔影参差，幽芳零乱，翠围腰瘦一捻。\n岁华相误，记前度、湘皋怨别。\n哀弦重听，都是凄凉，未须弹彻。\n国香到此谁怜，烟冷沙昏，顿成愁绝。\n花恼难禁，酒销欲尽，门外冰澌初结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18101, '高阳台', '王沂孙', '残萼梅酸，新沟水绿，初晴节序暄妍。\n独立雕栏，谁怜枉度华年。\n朝朝准拟清明近，料燕翎、须寄银笺。\n又争知、一字相思，不到呤边。\n双蛾不拂青鸾冷，任花阴寂寂，掩户闲眠。\n屡卜佳期，无凭却恨金钱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18102, '高阳台', '王沂孙', '驼褐轻装，狨鞯小队，冰河夜渡流澌。\n朔雪平沙，飞花乱拂蛾眉。\n琵琶已是凄凉调，更赋情、不比当时。\n想如今，人在龙庭，初劝金卮。\n一枝芳信应难寄，向山边水际，独抱相思。\n江雁孤回，天涯人自归迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18103, '高阳台', '王沂孙', '残雪庭阴，轻寒帘影，霏霏玉管春葭。\n小帖金泥，不知春在谁家。\n相思一夜窗前梦，奈个人、水隔天遮。\n但凄然，满树幽香，满地横斜。\n江南自是离愁苦，况游骢古道，归雁平沙。\n怎得银笺，殷勤与说年华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18104, '扫花游・扫地游', '王沂孙', '商飚乍发，渐淅淅初闻，萧萧还住。\n顿惊倦旅。\n背青灯吊影，起吟愁赋。\n断续无凭，试立荒庭听取。\n在何许。\n但落叶满阶，惟有高树。\n迢递归梦阻。\n正老耳难禁，病怀凄楚。\n故山院宇。\n想边鸿孤唳，砌蛩私语。\n数点相和，更著芭蕉细雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18105, '扫花游・扫地游', '王沂孙', '小庭荫碧，遇骤雨疏风，剩红如扫。\n翠交径小。\n问攀条弄蕊，有谁重到。\n谩说青青，比似花时更好。\n怎知道。\n□一别汉南，遗恨多少。\n清昼人悄悄。\n任密护帘寒，暗迷窗晓。\n旧盟误了。\n又新枝嫩子，总随春老。\n渐隔相思，极目长亭路杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18106, '扫花游・扫地游', '王沂孙', '卷帘翠湿，过几阵残寒，几番风雨。\n问春住否。\n但匆匆暗里，换将花去。\n乱碧迷人，总是江南旧树。\n谩凝伫。\n念昔日采香，今更何许。\n芳径携酒处。\n又荫得青青，嫩苔无数。\n故林晚步。\n想参差渐满，野塘山路。\n倦枕闲床，正好微曛院宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18107, '扫花游・扫地游', '王沂孙', '满庭嫩碧，渐密叶迷窗，乱枝交路。\n断红甚处。\n但匆匆换得，翠痕无数。\n暗影沈沈，静锁清和院宇。\n试凝伫。\n怕一点旧香，犹在幽树。\n浓阴知几许。\n且拂簟清眠，引筇闲步。\n杜郎老去。\n算寻芳较晚，倦怀难赋。\n纵胜花时，到了愁风怨雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18108, '锁窗寒・琐寒窗', '王沂孙', '趁酒梨花，催诗柳絮，一窗春怨。\n疏疏过雨，洗尽满阶芳片。\n数东风、二十四番，几番误了西园宴。\n认小帘朱户，不如飞去，旧窠双燕。\n曾见。\n双蛾浅。\n自别後，多应黛痕不展。\n扑蝶花阴，怕看题诗团扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18109, '锁窗寒・琐寒窗', '王沂孙', '料峭东风，廉纤细雨，落梅飞尽。\n单衣恻恻，再整金猊香烬。\n误千红、试妆较迟，故园不似清明近。\n但满庭柳色，柔丝羞舞，淡黄犹凝。\n芳景。\n还重省。\n向薄晓窥帘，嫩阴枕。\n桐花渐老，已做一番风信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18110, '锁窗寒・琐寒窗', '王沂孙', '出谷莺迟，踏沙雁少，阴庭宇。\n东风似水，尚掩沈香双户。\n凭莓阶、雪痕乍铺，那回已趁飞梅去。\n奈柳边占得，一庭新暝，又还留住。\n前度。\n西园路。\n记半袖争持，斗娇眉妩。\n琼肌暗怯，醉立千红深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18111, '应天长', '王沂孙', '疏帘蝶粉，幽径燕泥，花间小雨初足。\n又是禁城寒食，轻舟泛晴渌。\n寻芳地，来去熟。\n尚彷佛、大堤南北。\n望杨柳、一片阴阴，摇曳新绿。\n重访艳歌人，听取春声，犹是杜郎曲。\n荡漾去年春色，深深杏花屋。\n东风曾共宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18112, '八六子', '王沂孙', '扫芳林。\n几番风雨，匆匆老尽春禽。\n渐薄润侵衣不断，嫩凉随扇初生。\n晚窗自吟。\n沈沈。\n幽径芳寻。\n暗霭苔香帘净，萧疏竹影庭深。\n谩淡却蛾眉，晨妆慵扫，宝钗虫散，绣屏鸾破，当时暗水和云泛酒，空山留月听琴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18113, '摸鱼儿', '王沂孙', '洗芳林、夜来风雨。\n匆匆还送春去。\n方才送得春归了，那又送君南浦。\n君听取。\n怕此际、春归也过吴中路。\n君行到处。\n便快折湖边，千条翠柳，为我系春住。\n春还住。\n休索吟春伴侣。\n残花今已尘土。\n姑苏台下烟波远，西子近来何许。\n能唤否。\n又恐怕、残春到了无凭据。\n烦君妙语。\n更为我将春，连花带柳，写入翠笺句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18114, '摸鱼儿', '王沂孙', '玉帘寒、翠痕微断，浮空清影零碎。\n碧芽也抱春洲怨，双卷小缄芳字。\n还又似。\n系罗带相思，几点青钿缀。\n吴中旧事。\n怅酪乳争奇，鲈鱼谩好，谁与共秋醉。\n江湖兴，昨夜西风又起。\n年年轻误归计。\n如今不怕归无准，却怕故人千里。\n何况是。\n正落日垂虹，怎赋登临意。\n沧浪梦里。\n纵一舸重游，孤怀暗老，馀恨渺烟水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18115, '声声慢', '王沂孙', '啼门静，落叶阶深，秋声又入吾庐。\n一枕新凉，西窗晚两疏疏。\n旧香旧色换却，但满川、残柳荒蒲。\n茂陵远，任岁华苒苒，老尽相如。\n昨夜西风初起，想莼边呼棹，桔後思书。\n短景凄然，残歌共叩铜壶。\n当时送行共约，雁归时、人赋归欤。\n雁归也，问人归、如雁也无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18116, '声声慢', '王沂孙', '高寒户牖，虚白尊，千山尽入孤光。\n玉影如空，天葩暗落清香。\n平生此兴不浅，记当年、独据胡床。\n怎知道，是岁华换却，处处堪伤。\n已是南楼曲断，纵疏花淡月，也只凄凉。\n冷雨斜风，何况独掩西窗。\n天涯故人总老，谩相思、永夜相望。\n断梦远，趁秋声、一片渡江。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18117, '声声慢', '王沂孙', '迎门高髻，倚扇清吭，娉婷未数西州。\n浅拂朱铅，春风二月梢头。\n相逢靓妆俊语，有旧家、京洛风流。\n断肠句，试重拈彩笔，与赋闲愁。\n犹记凌波欲去，问明罗袜，却为谁留。\n枉梦相思，几回南浦行舟。\n莫辞玉樽起舞，怕重来、燕子空楼。\n谩惆怅，抱琵琶、闲过此秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18118, '金盏子', '王沂孙', '雨叶吟蝉，露草流萤，岁华将晚。\n对静夜无眠，稀星散、时度绛河清浅。\n甚处画角凄凉，引轻寒催燕。\n西楼外，斜月未沈，风急雁行吹断。\n此际怎消遣。\n要相见、除非待梦见。\n盈盈洞房泪眼，看人似、冷落过秋纨扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18119, '更漏子', '王沂孙', '日衔山，山带雪。\n笛弄晚风残月。\n湘梦断，楚魂迷。\n金河秋雁飞。\n别离心，思忆泪。\n锦带已伤憔悴。\n蛩韵急，杵声寒。\n征衣不用宽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18120, '锦堂春・锦堂春慢', '王沂孙', '桂嫩传香，榆高送影，轻罗小扇凉生。\n正鸳机梭静，凤渚桥成。\n穿线人来月底，曝衣花入风庭。\n看星残靥碎，露滴珠融，笑掩云扃。\n彩盘凝望仙子，但三星隐隐，一水盈盈。\n暗想恁肩私语，鬓乱钗横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18121, '青房并蒂莲', '王沂孙', '醉凝眸。\n是楚天秋晓，湘岸云收。\n草绿兰红，浅浅小汀洲。\n芰荷香里鸳鸯浦，恨菱歌、惊起眠鸥。\n望去帆，一片孤光，棹声伊轧橹声柔。\n愁窥汴堤翠柳，曾舞送当时，锦缆龙舟。\n拥倾国、纤腰皓齿，笑倚迷楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18122, '锦堂春・锦堂春慢', '王沂孙', '露掌秋深，花签漏永，那堪此夕新晴。\n正纤尘飞尽，万籁无声。\n金镜开奁弄影，玉壶盛水侵棱。\n纵帘斜树隔，烛暗花残，不碍虚明。\n美人凝恨歌黛，念径年间阻，只恐云生。\n早是宫鞋鸳小，翠鬓蝉轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18123, '如梦令', '王沂孙', '妾似春蚕抽缕。\n君似筝弦移柱。\n无语结同心，满地落花飞絮。\n归去。\n归去。\n遥指乱云遮处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18124, '醉蓬莱', '王沂孙', '扫西风门径，黄叶凋零，白云萧散。\n柳换枯阴，赋归来何晚。\n爽气霏霏，翠蛾眉妩，聊慰登临眼。\n故国如尘，故人如梦，登高还懒。\n数点寒英，为谁零落，楚魄难招，暮寒堪揽。\n步荒篱，谁念幽芳远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18125, '法曲献仙音', '王沂孙', '层绿峨峨，纤琼皎皎，倒压波痕清浅。\n过眼年华，动人幽意，相逢几番春换。\n记唤酒寻芳处，盈盈褪妆晚。\n已销黯。\n况凄凉、近来离思，应忘却、明月夜深归辇。\n荏苒一枝春，恨东风、人似天远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18126, '淡黄柳', '王沂孙', '花边短笛。\n初结孤山约。\n雨悄风轻寒漠漠。\n翠镜秦鬟钗别，同折幽芳怨摇落。\n素裳薄。\n重拈旧红萼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18127, '长亭怨・长亭怨慢', '王沂孙', '泛孤艇、东皋过遍。\n尚记当日，绿阴门掩。\n屐齿莓阶，酒痕罗袖事何限。\n欲寻前迹，空惆怅、成秋苑。\n自约赏花人，别後总、风流云散。\n水远。\n怎知流水外，却是乱山尤远。\n天涯梦短。\n想忘了、绮疏雕槛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18128, '西江月', '王沂孙', '褪粉轻盈琼靥，护香重叠冰绡。\n数枝谁带玉痕描。\n夜夜东风不扫。\n溪上横斜影淡，梦中落莫魂销。\n峭寒未肯放春娇。\n素被独眠清晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18129, '踏莎行', '王沂孙', '白石飞仙，紫霞凄调。\n断歌人听知音少。\n几番幽梦欲回时，旧家池馆生青草。\n风月交游，山川怀抱。\n凭谁说与春知道。\n空留离恨满江南，相思一夜苹花老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18130, '醉落魄・一斛珠', '王沂孙', '小窗银烛。\n轻鬟半拥钗横玉。\n数声春调清真曲。\n拂拂朱帘，残影乱红扑。\n垂杨学画蛾眉绿。\n年年芳草迷金谷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18131, '醉落魄・一斛珠', '王沂孙', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18132, '霜天晓角', '王沂孙', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18133, '谒金门', '王沂孙', '恰似断魂江上柳，越春深越瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18134, '失调名', '王沂孙', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18135, '潇湘神', '黄公绍', '望湖天。\n望湖天。\n绿杨深处鼓。\n好是年年三二月，湖边日日看划船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18136, '潇湘神', '黄公绍', '斗轻桡。\n斗轻桡。\n雪中花卷棹声摇。\n天与玻璃三万顷，尽教看得几吴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18137, '潇湘神', '黄公绍', '看龙舟。\n看龙舟。\n两堤未斗水悠悠。\n一片笙歌催闹晚，忽然鼓棹起中流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18138, '潇湘神', '黄公绍', '贺灵鼍。\n贺灵鼍。\n几年翠舞与珠歌。\n看到日斜犹未足，涌金门外涌金波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18139, '潇湘神', '黄公绍', '马如龙。\n马如龙。\n飞过苏堤健斗风。\n柳下系船青作缆，湖边荐酒碧为筒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18140, '潇湘神', '黄公绍', '绣周张。\n绣周张。\n楼台帘幕絮高扬。\n谁赋珠宫并贝阙，怀王去後去沈湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18141, '潇湘神', '黄公绍', '棹如飞。\n棹如飞。\n水中万鼓起潜螭。\n最是玉莲堂上好，跃来夺锦看吴儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18142, '潇湘神', '黄公绍', '建云。\n建云。\n土风到处总相犹。\n朝了霍山朝岳帝，十分打扮是杭州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18143, '潇湘神', '黄公绍', '踏青青。\n踏青青。\n西泠桥畔草连汀。\n扑得龙船儿一对，画阑倚遍看游人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18144, '潇湘神', '黄公绍', '月明中。\n月明中。\n满湖春水望难穷。\n欲学楚歌歌不得，一场离恨两眉峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18145, '满江红', '黄公绍', '客子光阴，又还是、杏花阡陌。\n枕听、一窗夜雨，怎生禁得。\n银蜡痕消珠凤小，翠衾香冷文鸳拆。\n叹人生、时序百年心，萍踪迹。\n声不断，楼头滴。\n行不住，街头屐。\n倩新来双燕，探晴消息。\n可煞东君多著意，柳丝染出西湖色。\n待牡丹、开处十分春，催寒食。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18146, '念奴娇', '黄公绍', '山围宽碧，月十分圆满，十分春暮。\n匹似涌金门外看，添得绿阴佳树。\n野阔星垂，天高云敛，不受红尘污。\n徘徊水影，闲中自有佳处。\n乘兴著我扁舟，山阴夜色，渺渺流光溯。\n望美人兮天一角，我欲凌风飞去。\n世事浮沈，人生圆缺，得似烟波趣。\n兴怀赤壁，大江千古东注。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18147, '望江南・忆江南', '黄公绍', '思晴好，去上竹山窠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18148, '望江南・忆江南', '黄公绍', '思晴好，试卜那朝晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18149, '望江南・忆江南', '黄公绍', '思晴好，小驻岂无因。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18150, '望江南・忆江南', '黄公绍', '思晴好，春透海棠枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18151, '望江南・忆江南', '黄公绍', '思晴好，天运几乘除。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18152, '望江南・忆江南', '黄公绍', '思晴好，路滑少人行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18153, '望江南・忆江南', '黄公绍', '思晴好，我欲问花神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18154, '望江南・忆江南', '黄公绍', '思晴好，松路翠光寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18155, '望江南・忆江南', '黄公绍', '思晴好，日影漏些儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18156, '望江南・忆江南', '黄公绍', '思晴好，晨起望篱东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18157, '花犯', '黄公绍', '翠奁空、红鸾蘸影，嫣然弄妆晚。\n雾鬟低颤。\n飞嫩藕仙裳，清思无限。\n象床试锦新翻样，金屏连绣展。\n最好似、阿环娇困，云酣春帐暖。\n寻思水边赋娟娟，新霜□旧约，西风庭院。\n肠断处，秋江上、彩云轻散。\n凭谁向、一筝过雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18158, '喜迁莺', '黄公绍', '乱红飞雨。\n怅春心一似，腾腾闷暑。\n密绾柔情，暗传芳意，人在垂杨深宇。\n晓雪一帘幽梦，半点檀心知否。\n春不管，想粉香凝泪，翠颦含趣。\n谁念芳径小，新绿笺笺，问讯今何许。\n玉冷钗头，罗宽带眼，缥缈青鸾难遇。\n望断碧云深处，倚遍画阑将暮。\n空惆怅，更江头桃叶，溜横波渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18159, '汉宫春', '黄公绍', '身到瑶池。\n正□永芙蓉，素鸾飞。\n绿云淡笼波面，鸳影差差。\n青冥世界，向龙宫、涌出江妃。\n凝望久，夜凉如水，人间惆怅芳时。\n池上方壶仙伯，是珊珊月佩，绰棹冰肌。\n重来碧环胜处，笑引琼卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18160, '莺啼序', '黄公绍', '银云卷晴缥缈，卧长龙一带。\n柳丝蘸、几簇柔烟，两市帘栋如画。\n芳草岸、弯环半玉，鳞鳞曲港双流会。\n看碧天连水，翻成箭样风快。\n白露横江，一苇万顷，问灵槎何在。\n空翠湿衣不胜寒，日华金掌沆瀣。\n花平、绿文衬步，琼田涌出神仙界。\n黛眉修，依约雾鬟，在秋波外。\n阁嘘青蜃，楼啄彩虹，飞盖蹴鳌背。\n灯火暮，相轮倒影，偷睇别浦，片片归帆，远自天际。\n舞蛟幽壑，栖鸦古木，有人翦取松江水，忆细鳞巨口鱼堪。\n波涵笠泽，时见静影浮光，霏阴万貌千态。\n蒹葭深处，应有闲鸥，寄语休见怪。\n倩洗却、香红尘面，买个扁舟，身世飘萍，名利微芥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18161, '明月棹孤舟・夜行船', '黄公绍', '雁带愁来寒事早。\n西风把鬓华吹老。\n猛省中秋，都来几日，先自木樨开了。\n轻阴天弄晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18162, '踏莎行', '黄公绍', '蟾苑萧疏，云岩芳馥。\n仙娥寄种来溪曲。\n晓烟薰上古龙涎，西风展破黄金粟。\n庾岭未梅，陶园休菊。\n天教占取清香独。\n胆瓶枕畔两三枝，梦回疑在瑶台宿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18163, '洞仙歌', '黄公绍', '银菟分竹，是君王亲付。\n州在扶舆最清处。\n紫云楼、记取天语丁宁，襦绔手，好好为吾摩拊。\n望公如望月，见说郴江，父老多时问来暮。\n旌旆试初凉，紫马西来，青丝络、秋风满路。\n早桔井丹成入仙班，有乔木前芳，事须公做。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18164, '喜迁莺', '黄公绍', '世情冰尽。\n算耐久祗是，陇头芳信。\n惆怅人间，几千年□，留得陆郎馀韵。\n朔云解识花意，遮断疏狂蝶粉。\n岁寒了，狂风传香远，月移影近。\n清润。\n无点，不曰坚乎，如玉真难尽。\n除宋广平，与林和靖，肉眼有谁能认。\n仙丰道骨如许，相对霜髯雪鬓。\n长健也，好年年管领，春光随分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18165, '凤凰台上忆吹箫', '彭履道', '劝客新楼，鸣筝上酒，夜凉人爱秋深。\n何似过、赏心佳处，依约湖阴。\n东望寒光缥缈，烟水阔、短笛销沈。\n阑干近，胜时种柳，清到如今。\n凌波又成误约，自佩环飞去，暗想遗音。\n重省江城倦客，醉拥秋衾。\n谁家一掬红泪，孤雁远、湿逗罗襟。\n石城晓，数声又递寒砧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18166, '兰陵王', '彭履道', '章台路。\n西出重城几步。\n秦楼晓、花气未明，一霎空洗高树。\n行人半倚户。\n飞去黄鹂自语。\n秋千小，不系柳条，惟有轻阴约飞絮。\n钿车暗相遇。\n早拂拭红巾，初放鹦鹉。\n闻歌犹是淋铃处。\n掩面鸣筝，倚垆呼酒，东风重记旧眉妩。\n报伊共歌舞。\n西去。\n屡回顾。\n渐客舍荒凉，嘶马先驻。\n玉关万里知何许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18167, '疏影', '彭履道', '银云缥缈。\n正石梁倒挂，飞下晴昊。\n早挽悬河，高泻鲸宫，洪声百步低小。\n分明仙仗崆峒过，又化作，归帆杳杳。\n倚参差，翠影红霞，远落明湖残照。\n曾共呼龙夭矫。\n几回过月下，先种瑶草。\n九叠屏风，青鸟冥冥，更约谪仙重到。\n昨梦骑黄鹄，飞不去、和天也笑。\n等恁时、秋夜携琴，已落洞天霜晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18168, '摸鱼儿', '韦居安', '绕苕城、水平坡渺，双明遥睇无际。\n就中惟有鱼湾好，占得西关佳致。\n杨柳外、羡泛宅浮家，当日元真子。\n溪山信美。\n叹陈迹犹存，前贤已往，谁会景中意。\n萧闲甚，筑屋三间近水。\n汀洲香泛兰芷。\n清风明月知多少，肯滞软红尘里。\n垂钓饵。\n这春水生时，剩有桃花鳜。\n烦襟净洗。\n待办取轻蓑，来分半席，相对弄清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18169, '唱金缕・贺新郎', '柴元彪', '春到云中早。\n恰梅花、雪後□□，锁窗寒悄。\n鼓吹喧天灯市闹，在处鳌山蓬岛。\n正新岁、金鸡唱晓。\n一点魁星光焰里，这水晶、庭院知多少。\n鸣凤舞，洞箫袅。\n太平官府人嘻笑。\n道紫微、魁星聚会，参差联照。\n借地栽花河阳县，桃李芳菲正好。\n暖沁入、东风池沼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18170, '水龙吟', '柴元彪', '秋云元自无心，那曾系得归心住。\n阳关酒尽，灞桥人远，也须别去。\n□□□□，□□□□，□□□□。\n有哀雁声声，愁蛩切切，悄悄地、听人语。\n回首琵琶旧恨，叹西风、□兴如许。\n江左百年，风流云散，不堪重举。\n怎得归来，樵歌互答，自相容与。\n又何须□□，三五蟾光，重阳风雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18171, '踏莎行', '柴元彪', '浅柳平芜，乱烟疏雨。\n雁声叫彻芦花渚。\n亭前落叶又西风，断送离怀无著处。\n切切归期，盈盈尺素。\n断魂正在西兴渡。\n满船空载暮愁来，潮头一吼推将去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18172, '蝶恋花', '柴元彪', '去年走马章台路。\n送酒无人，寂寞黄花雨。\n又是重阳秋欲暮。\n西风此恨谁分付。\n无限归心归不去。\n却梦佳人，约我花间住。\n蓦地觉来无觅处。\n雁声叫断潇湘浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18173, '苏幕遮', '柴元彪', '晚晴初，斜照里。\n远水连天，天外帆千里。\n百尺高楼谁独倚。\n滴落梧桐，一片相思泪。\n马又嘶，风又起。\n断续寒砧，又送黄昏至。\n明月照人人不睡。\n愁雁声声，更切愁人耳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18174, '海棠春', '柴元彪', '阳关可是登高路。\n算到底、不如归去。\n时节近中秋，那更黄花雨。\n酒病恹恹，羁愁缕缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18175, '惜分飞', '柴元彪', '候馆天寒灯半灭。\n对着灯儿泪咽。\n此恨难分说。\n能禁几度黄花别。\n乍转寒更敲未歇。\n蛩语更添凄恻。\n今夜归心切。\n砧声敲碎谁家月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18176, '高阳台', '柴元彪', '丹碧归来，天荒地老，华发相催。\n见说钱塘，北高峰更崔嵬。\n琼林侍宴簪花处，二十年、满地苍苔。\n倩阿谁，为我起居，坡柳逋梅。\n凄凉往事休重省，且凭阑感慨，抚景衔杯。\n冷暖由天，任他花谢花开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18177, '百字令・念奴娇', '东冈', '排云拓月，向天上移下，神仙华屋。\n画栋飞檐千万落，黼黼城南乔木。\n出谷莺迁，趋庭燕尔，袍绾登科绿。\n嫦娥分付，广寒今夜花烛。\n遥想高越于门，烂盈百辆，夹道争车毂。\n春满剡溪溪上路，一任瑶华飞六。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18178, '意难忘', '范文', '清泪如铅。\n叹咸阳送远，露冷铜仙。\n岩花粉堕雪，津柳暗生烟。\n寒食後，暮江边。\n草色更芊芊。\n四十年，留春意绪，不似今年。\n山阴欲棹归船。\n暂停杯雨外，舞剑灯前。\n重逢应未卜，此别转堪怜。\n凭急管，倩繁弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18179, '失调名', '叶李', '君来路。\n吾归路。\n来来去去何时住。\n公田关子竟何如，国事当时谁汝误。\n雷州户。\n崖州户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18180, '念奴娇', '梁栋', '一场春梦，待从头，说与旁人听著。\n罨画溪山红锦障，舞燕歌莺台阁。\n碧海倾春，黄金买夜，犹道看承薄。\n雕香剪玉，今生今世盟约。\n须信欢乐过情，闲嗔冷妒，一阵东风恶。\n韵白娇红消瘦尽，江北江南零落。\n骨朽心存，恩深缘浅，忍把罗衣著。\n蓬莱何处，云涛天际冥漠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18181, '摸鱼儿', '梁栋', '枕寒流、碧萦衣带，高台平与云倚。\n燕来莺去谁为主，磨灭谪仙吟墨。\n愁思里。\n待说与山灵，还又羞拈起。\n萧韶已矣。\n甚竹实风摧，桐阴雨瘦，景物变新丽。\n江山在，认得刘郎阿寄。\n年来声誉休废。\n英雄不博胭脂井，谁念故人衰悴。\n时有几。\n便凤去台空，莫厌频游此。\n兴亡过耳。\n任北雪迷空，东风换绿，都付梦和醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18182, '一萼红', '梁栋', '怨东风。\n把韶华付去，李小桃红。\n黄落山空，香销水冷，此际才与君逢。\n敛秋思、愁肠九结，拥翠袖、应费剪裁工。\n晕脸迎霜，幽姿泣露，寂寞谁同。\n休笑梳妆淡薄，看浮花浪蕊，眼底俱空。\n夜帐云闲，寒城月浸，有人吟遍深丛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18183, '水龙吟', '莫', '镜寒香歇江城路，今度见春全懒。\n断云过雨，花前歌扇，梅边酒盏。\n离思相欺，万丝萦绕，一襟销黯。\n但年光暗换，人生易感，西归水、南飞雁。\n也拟与愁排遣。\n奈江山、遮拦不断。\n娇讹梦语，湿荧啼袖，迷心醉眼。\n绣毂华茵，锦屏罗荐，何时拘管。\n但良宵空有，亭亭霜月，作相思伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18184, '玉楼春', '莫', '绿杨芳径莺声小。\n帘幕烘香桃杏晓。\n馀寒犹峭雨疏疏，好梦自惊人悄悄。\n凭君莫问情多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18185, '生查子', '莫', '三两信凉风，七八分圆月。\n愁绪到今年，又与前年别。\n衾单容易寒，独暗相将灭。\n欲识此时情，听取鸣蛩说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18186, '卜算子', '莫', '红底过丝明，绿外飞绵小。\n不道东风上海棠，白地春归了。\n月笛曲栏留，露芳池绕。\n争得闲情似旧时，遍索檐花笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18187, '摸鱼儿', '莫', '听春教、燕颦莺诉。\n朝朝花困风雨。\n六桥忘却清明後，碧尽柳丝千缕。\n蜂蝶侣。\n正闲觅闲花，闲草闲歌舞。\n最怜西子。\n尚薄薄云情，盈盈波泪，点点旧眉妩。\n流红记，空泛秋宫怨句。\n才色何处娇妒。\n落红无风限随风絮。\n诗恨有谁曾遇。\n堪恨处。\n恨二十四番，花信催花去。\n东君暗苦。\n更多嘱多情，多愁杜宇，多诉断肠语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18188, '摸鱼儿', '姚云文', '渺人间、蓬瀛何许，一朝飞入梁苑。\n辋川梯洞层瑰出，带取鬼愁龙怨。\n穷游宴。\n谈笑里，金风吹折桃花扇。\n翠华天远。\n怅莎沼黏萤，锦屏烟合，草露泣苍藓。\n东华梦，好在牙樯雕辇。\n画图历历曾见。\n落红万点孤臣泪，斜日牛羊春晚，摩双眼。\n看尘世，鳌宫又报鲸波浅。\n吟鞘拍断。\n便乞与娲皇，化成精卫，真不尽遗恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18189, '玲珑玉', '姚云文', '开岁春迟，早赢得、一白潇潇。\n风窗淅簌，梦惊金帐春娇。\n是处貂裘透暖，任尊前回舞，红倦柔腰。\n今朝。\n亏陶家、茶鼎寂寥。\n料得东皇戏剧，怕蛾儿街柳，先斗元宵。\n宇宙低迷，倩谁分、浅凸深凹。\n休嗟空花无据，便真个、琼雕玉琢，总是虚飘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18190, '木兰花慢', '姚云文', '笑花神较懒，似忘却、趁清明。\n更油幄晴悭，箬庵寒浅，湿重红云。\n东君似怜花透，环碧ㄓ、遮住怕渠惊。\n惆怅犊车人远，绿杨深闭重城。\n香名。\n谁误娉婷。\n曾注谱、上金屏。\n问洛中亭馆、竹西鼓吹，人醉花醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18191, '紫萸香慢', '姚云文', '近重阳、偏多风雨，绝怜此日暄明。\n问秋香浓未，待携客、出西城。\n正自羁怀多感，怕荒台高处，更不胜情。\n向尊前、又忆洒酒插花人。\n只座上、已无老兵。\n凄情。\n浅醉还醒。\n愁不肯、与诗平。\n记长楸走马，雕弓ㄇ柳，前事休评。\n紫萸一枝传赐，梦谁到、汉家陵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18192, '洞仙歌', '姚云文', '燕窠香湿，误天涯芳信。\n社近阴晴未前定。\n听莺簧宛转，似羽疑宫，歌未断，落落旧愁都醒。\n疏狂追少日，杜曲樊楼，拼把黄金买春恨。\n回首武陵溪，花待郎归，洞云深、未知春尽。\n问杨柳梢头几分青，消不得，朝来雨寒一阵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18193, '齐天乐', '姚云文', '柳花引过横塘路，萦回曲蹊通圃。\n插槿编篱，挨梅砌石，次第海棠成坞。\n吟筇独拄。\n待寻访斜桥，水边窥户。\n已约青山，云深不碍客来处。\n繁华阅人无数。\n问旧日平原，君还知否。\n啼鸟窗幽，画阴人寂，慵困不如飞絮。\n匆匆燕语。\n似迎得春来，且留春住。\n惜取名花，一枝堪寄与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18194, '蝶恋花', '姚云文', '春到海棠花几信。\n堠馆馀寒，欲雨征衣润。\n燕认杏梁栖未稳。\n牡丹忽报清明近。\n恨入青山连晓镜。\n香雪柔酥，应被春消尽。\n绣阁深深人半醒。\n烛花贴在金钗影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18195, '如梦令', '姚云文', '昨夜佳人凭酒。\n隔著罗衾厮守。\n听彻五更钟，陡觉霜飞寒逗。\n却又。\n却又。\n陪笑倩人温手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18196, '八声甘州', '姚云文', '卷丝丝、雨织半晴天，棹歌发清舷。\n甚苍虬怒耀，灵鼍急吼，雪涌平川。\n楼外榴裙几点，描破绿杨烟。\n把画罗遥指，助啸争先。\n憔悴潘郎曾记，得青龙千舸，采石矶边。\n叹内家帖子，闲却缕金笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18197, '绮罗香', '赵必', '办一枝藤，蜡一双屐，纵步翠微深处。\n无限芳心，付与蜂媒蝶侣。\n红堆里、杏脸匀妆，翠围外、柳腰娇舞。\n有吟翁、热恼心肠，肯拈出、美成佳句。\n九十光阴箭过，趁取芳晴追逐，春风杖屦。\n消得几番，风和雨、春归去。\n怅莺老、对景多愁，倩燕语、苦难留住。\n秋千影里送斜阳，梨花深院宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18198, '念奴娇', '赵必', '一时四美，对重阳、那更无风无雨。\n尘世难逢开口笑，不饮黄花有语。\n云谷春生，星岩秋好，引领群仙去。\n满襟霁月，山中一洗尘雾。\n濂翁旧说犹存，渊明独爱菊，风流千古。\n拄杖笑谈卿与我，不减晋人风度。\n破帽风，空尊眠月，也有悠然趣。\n秋容未老，晚香尤有佳处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18199, '兰陵王', '赵必', '画阑直。\n千红万碧。\n无端被，怪雨狂风，柳花禁春色。\n寻芳遍楚国。\n谁识。\n五陵俊客。\n流水远，题叶无情，雁足不来杳笺尺。\n浮生等萍迹。\n才卸却归鞍，坐未温席。\n匆匆还又京华食。\n叹聚少离多，漂零因甚，江南逢梅望寄驿。\n美人兮天北。\n悲恻。\n恨成积。\n怅钗玉尘生，猊金烟寂。\n绿杨芳草情何极。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18200, '风流子', '赵必', '旧梦忆钱塘。\n笙歌里、几度醉斜阳。\n曾载月一篷，眠杨柳岸，买春深巷，过杏花墙。\n肠恼断，香鬟盘凤髻，樱口啭莺簧。\n钗玉分轻，梦孤宵枕，歌纨蠹久，愁对春觞。\n司空曾见惯，相逢处，还又联步西厢。\n底用十分迷，翠阵红行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18201, '风流子', '赵必', '春光才一半，春未老、谁肯放春归。\n问买春价数，酒边商略，寻春巷陌，鞭影参差。\n春无尽，春莺调巧舌，春燕垒香泥。\n好趁春光，爱花惜柳，莫教春去，柳怨花悲。\n春心犹未足，春帏暖，炉薰香透春衣。\n说与重欢後约，春以为期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18202, '齐天乐', '赵必', '东南半壁乾坤窄，渺人物、消磨尽。\n官爵网罗，功名钓饵，眼底纷纷蛙井。\n暮更朝令。\n捍格了多少，英雄豪俊。\n身事悠悠，儒冠误矣文章病。\n休休蕉鹿梦省。\n早牛衣无恙，鸥盟未冷。\n相越平吴，终成底用，不似五湖舟稳。\n浩歌狂饮。\n休说我命通，待他心肯。\n浮世南柯，梦邯郸一枕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18203, '华胥引', '赵必', '沧浪矶外，小舣兰舟，旋沽竹叶。\n雨过溪肥，波心荡漾鸥对唼。\n烟晚乃渔歌，和橹声咿轧。\n要泛五湖，祗恐西施羞怯。\n年少飘零，鬓未霜，底须轻镊。\n江南归雁，寄来鸳笺细阅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18204, '意难忘', '赵必', '魏紫姚黄。\n属吟翁管领，曾醉春觞。\n盟寒钗凤股，灰冷宝猊香。\n前事远，此心凉。\n去也棹沧浪。\n把年时、芳情付与，鸳颈交相。\n灯前吊影成双。\n叹星星丝鬓，老矣潘郎。\n愁偏欺客枕，样不入时妆。\n尘面目，铁心肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18205, '宴清都', '赵必', '远远渔村鼓。\n斜阳外、宾鸿三两飞度。\n茅檐春小，白云隐几，青山当户。\n骚翁底事飘蓬，浑忘却、耕徒钓侣。\n何时寻、斗酒江鲈，悠悠千古坡赋。\n风流种柳渊明，折腰五斗，身为名苦。\n有秫田贰顷，菊松三迳，不如归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18206, '锁窗寒・琐寒窗', '赵必', '乳燕双飞，黄莺百啭，深深庭户。\n海棠开遍，零乱一帘红雨。\n绣帘低、卷起春风，香肩倦倚娇无语。\n叹玉堂底事。\n匆匆聚散，又江南旅。\n春暮。\n人何处。\n想歌馆睡浓，日高丈五。\n旧迷未醒，莫负孤眠凤侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18207, '隔浦莲・隔浦莲近拍', '赵必', '东风吹长嫩葆。\n花坞穿青窈。\n玉管新声，金铃颤响惊青鸟。\n行乐莫草草。\n春光闹。\n鸳浴垂杨沼。\n红娇小。\n梳宫样、髻云钗凤斜倒。\n酒边轻别，一枕相思到晓。\n巫山难梦到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18208, '苏幕遮', '赵必', '远迎风，回避暑。\n人似荷花，笑隔荷花语。\n无限情云并意雨。\n惊散鸳鸯，兰棹波心举。\n约重游，轻别去。\n断桥风月，梦断飘蓬旅。\n旧日秋娘犹在否。\n雁足不来，声断衡阳浦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18209, '齐天乐', '赵必', '红纷绿闹东风透，暖得枳花香也。\n雪柳拈金，玉梅铺粉，妆点春光无价。\n鳌蓬如画。\n簇万顷芙蕖，桂华相射。\n艳冶逢迎，香尘满路飘兰麝。\n人生行乐聊尔，况良辰美景，好天晴夜。\n茧帖争先，芋郎卜巧，细说成都旧话。\n传觞立马。\n看翠阵珠围，歌朋舞社。\n酒尽更阑，月在蒲萄架。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18210, '烛影摇红', '赵必', '月浸芙蕖，冰壶天地波凝碧。\n太平歌舞醉东风，花市人如织。\n桃李一城春色。\n玉梅娇、闹娥无力。\n粉围红阵，灯火楼台，绮罗巷陌。\n乐事还同，遨头引领神仙客。\n高烧银烛照红妆，香雾穿瑶席。\n款款檀牙细拍。\n醉金尊、东方未白。\n传柑相遗，探茧争先，明年何夕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18211, '沁园春', '赵必', '看做官来，只似儿时，掷选官图。\n如琼崖儋岸，浑么便去，翰林给舍，喝采曾除。\n都一掷间，许多般样，输了还赢赢了输。\n回头看，这浮云富贵，到底花虚。\n吾生谁毁谁誉。\n任荆棘丛丛满仕途。\n叹塞翁失马，祸也福也，蕉间得鹿，真欤梦欤。\n何怨何尤，自歌自笑，天要吾侪更读书。\n归去也，向竹松深处，结个茅庐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18212, '贺新郎', '赵必', '绣口琅腹。\n美人兮、阳春一曲，华貂难续。\n唤醒荷花归棹梦，犹忆红尘迷目。\n只消得、乌飞兔逐。\n往事已随流水去，眇愁予、郁郁哀时俗。\n恨千缕，泪一掬。\n不使清史流芳馥。\n也不须、荣华富贵，尊前频祝。\n但得山中茅屋在，莫遣鹤悲猿哭。\n随意种、荼薇躅。\n莼菜可羹鲈可，听渔舟、晚唱清溪曲。\n醉又醒，唤芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18213, '夏日燕黉堂', '赵必', '赤城中。\n奏鹤笙一曲，玉佩丁东。\n蒲节後七日，宴翠阆琼宫。\n年年王母来称寿，醉蟠桃、几度东风。\n簇花间五马，轻裘短帽，雪鬓吟翁。\n魁宿耀三雍。\n曾归车共载，非虎非熊。\n急流勇退，渊底卧骊龙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18214, '水调歌头', '赵必', '百岁人能几，七十世间稀。\n何况先生八十，蔗境美如饴。\n好与七松处士，更与梅花君子，永结岁寒知。\n菊节先五日，满酌紫霞卮。\n美成词，山谷字，老坡诗。\n三径田园如昨，久矣赋归辞。\n不是商山四皓，便是香山九老，红颊白须眉。\n九十尚入相，绿竹颂猗猗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18215, '贺新郎', '赵必', '寿酒浮萸菊。\n记年年、重阳嘉节，开尊华屋。\n绿鬓朱颜春不改，彼美人兮如玉。\n有锦绣、珠玑满腹。\n户外红尘飞不到，受人间、倒大清闲福。\n数花甲，才八六。\n十分秋色呈新绿。\n一簇儿、池馆亭台，左梅右竹。\n柳下系船花下饮，不减西园金谷。\n更桔外、安排棋局。\n独立小桥明月夜，唤莺莺、低唱双飞曲。\n有子也，万事足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18216, '贺新郎', '赵必', '低唱芙蓉菊。\n有吟翁、坐拥红娇，宴黄金屋。\n恰则绂鳞三日後，灿灿盘珠玉。\n不待梦、燕怀枫腹。\n自是嫦娥分桂种，伴灵椿、千岁延清福。\n回笑我，龟藏六。\n归欤老圃锄春绿。\n吾菟裘、三径荒苔，一庭瘦竹。\n欲隐贫无山可买，聊尔徜徉盘谷。\n更管甚、云台玉局。\n紧闭柴门传语客，道主人、高枕南窗曲。\n有酒蟹，此生足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18217, '贺新郎', '赵必', '沙上盟鸥鹭。\n笑吟翁、梦今不到，草堂深处。\n金屋重重春睡暖，傍翠偎香步步。\n已自摘、蟠桃三度。\n旧日画眉情性在，更君房、妙绝文章语。\n消受得，乘鸾侣。\n楼中燕燕谁家住。\n又从新、移根换叶，栽花千树。\n第一信风春事觉，莫遣绿羞红污。\n早早做、阑干遮护。\n天上姻缘千里合，喜乘槎、先入银河路。\n人似玉，衣金缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18218, '满江红', '赵必', '如此风涛，又断送、一番蒲节。\n何处寄、黍简彩线，龙馋蛟啮。\n已矣骚魂招不返，兰枯蕙老馀香歇。\n俯仰间、万事总成陈，新愁结。\n梅子雨，荷花月。\n消几度，头如雪。\n叹英雄虚老，凄其一。\n回首百年歌舞地，胥涛点点孤臣血。\n问长江、此恨几时平，茫无说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18219, '念奴娇', '赵必', '烧灯过也，倩东风、又翦芙蕖千朵。\n翠阵珠围依然是，旧日笙歌社火。\n一曲乘莺，万钱骑鹤，仙子来蓬岛。\n金尊满酌，不妨斜戴花帽。\n人生能几欢娱，趁良辰美景，绿娇红小。\n洞里桃花应笑道，前度刘郎未老。\n眼雨眉云，情香粉态，恨不相逢早。\n明年今夕，犀钱玉果分我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18220, '念奴娇', '赵必', '中年怕别，唱阳关未了，情怀先恶。\n回首西湖十年梦，几夜檐花清酌。\n人世如萍，客愁似海，吟鬓俱非昨。\n风涛如许，只应高卧林壑。\n菊松尽可归欤，叹折腰为米，渊明已错。\n相越平吴，终成底事，一舸五湖差乐。\n细和陶诗，径寻坡隐，时访峰头鹤。\n罗浮咫尺，春风寄我梅萼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18221, '醉落魄・一斛珠', '赵必', '西园饮歇。\n倚阑干、玉箫声彻。\n荷枯菊老秋芳歇。\n两蕊三花、九月南州雪。\n何郎情思逋仙骨。\n观桃墙杏成疏阔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18222, '浣溪沙', '赵必', '只为相思怕上楼。\n离莺一操恨悠悠。\n十二翠屏烟篆冷，晓窗秋。\n绣线未拈心已懒，花笺欲寄写还羞。\n懊恨郎边无个信，暮云愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18223, '菩萨蛮', '赵必', '红娇翠溜歌喉急。\n旧弦拨断新腔入。\n往事水东流。\n菱花晓带秋。\n帏香双凤集。\n清泪层绡湿。\n残梦五更头。\n酒醒依旧愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18224, '朝中措', '赵必', '凤凰台上听吹箫。\n银烛万红摇。\n要觅琼浆玉饮，隔墙便是蓝桥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18225, '朝中措', '赵必', '冰肌玉骨为谁癯。\n只为故人疏。\n憔悴粉销香减，风流不似当初。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18226, '朝中措', '赵必', '桔肥梅小蜡橙黄。\n薄薄板桥霜。\n春透谢娘庭院，雅宜倚玉偎香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18227, '鹧鸪天', '赵必', '湖海相逢尽赏音。\n囊中粒剂值千金。\n单传扁鹊卢医术，不用杨高郭玉针。\n三斛火，一壶冰。\n蓝桥捣熟隔云深。\n无方可疗相思病，有药难医薄幸心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18228, '大江东去・念奴娇', '黎廷瑞', '鲍鱼腥断，楚将军、鞭虎驱龙而起。\n空费咸阳三月火，铸就金刀神器。\n垓下兵稀，阴陵道隘，月黑云如垒。\n楚歌哄发，山川都姓刘矣。\n悲泣呼醒虞姬，和伊死别，雪刃飞花髓。\n霸业休休骓不逝，英气乌江流水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18229, '蝶恋花', '黎廷瑞', '密炬瑶霞光颤酒。\n翠柏红椒，细翦青丝韭。\n且劝金樽千万寿。\n年时芳梦休回首。\n小雨轻寒风满袖，下却帘儿，莫道梅花瘦。\n万点鹅黄春色透。\n玉箫吹上江南柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18230, '八声甘州', '黎廷瑞', '恨巨灵、多事凿长江，消沈几英雄。\n恨乌江亭长，天机轻泄，说与重瞳。\n更恨南阳耕叟，撺掇紫髯翁。\n一弹金陵土，战虎争龙。\n杯酒凤凰台上，对石城流水，锺阜诸峰。\n问六朝陵阙，何处是遗踪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18231, '水龙吟', '黎廷瑞', '不知玄武湖中，一瓢春水何人借。\n裁冰翦雨，等闲占断，桃花春社。\n古阜花城，玉龙盐虎，夕阳图画。\n是东风吹就，明朝吹散，又还是、东风也。\n回首当时光景，渺秦淮、绿波东下。\n滔滔江水，依依山色，悠悠物化。\n璧玉琼花，世间消得，几多朝夜。\n笑乌衣、不管春寒，只管说、兴亡话。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18232, '南乡子', '黎廷瑞', '醉罢黑瑶池。\n渺渺春云海峤归。\n画楝珠帘成昨梦，谁知。\n百姓人家几度非。\n相对语斜晖。\n肠断江城柳絮飞。\n再见玉郎应不认，堪悲。\n也被缁尘染素衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18233, '清平乐', '黎廷瑞', '秋怀骚屑。\n卧听萧萧叶。\n四壁寒蛩吟不歇，旧恨新愁都说。\n疏疏雨打栖鸦。\n月痕犹在窗纱。\n一夜西风能紧，明朝瘦也黄花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18234, '浪淘沙', '黎廷瑞', '别易见时难。\n万水千山。\n参商烟树暮云间。\n料想凤凰城里梦，夜夜归鞍。\n杨柳小楼闲。\n倚遍阑干。\n东风翦翦雨珊珊。\n落尽桃花无可落，只管春寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18235, '浣溪沙', '黎廷瑞', '一曲离愁浅黛。\n云帆渺渺下烟津。\n山长水远客愁新。\n柳絮低迷千里梦，桃花荡洋一江春。\n小楼疏雨可怜人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18236, '祝英台近', '黎廷瑞', '彩云空，香雨霁。\n一梦千年事。\n碧幌如烟，却扇试新睡。\n恁时杨柳阑干，芙蓉池馆，还只似、如今天气。\n远山翠。\n空相思，淡扫修眉，盈盈照秋水。\n落日西风，借问雁来未。\n只愁雁到来时，又无消息，只落得，一番憔悴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18237, '水调歌・水调', '黎廷瑞', '腰缠十万贯，骑鹤上扬州。\n诗翁那得有此，天地一扁舟。\n二十四番风信，二十四桥风景，正好及春游。\n挂席欲东下，烟雨暗层楼。\n紫绮冠，绿玉杖，黑貂裘。\n沧波万里，浩荡踪迹寄浮鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18238, '满江红', '黎廷瑞', '千亩君封，新移就、美泉天禄。\n形制古，椰樽嫌窄，瓠壶嫌俗。\n爱酒步兵缘业重，平生所愿何时足。\n再来生、竟堕此林中，充其腹。\n秋入洞，鉴金筑。\n春出户，跳珠玉。\n想宜城九酝，叶光凝绿。\n驴背夕阳同倒载，醉乡只在谷。\n问东坡、何独饮松醪，还思肉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18239, '唐多令', '黎廷瑞', '回棹百花洲。\n迢迢碧玉流。\n听笛声、何处高楼。\n如此江山无此客，虽有酒、奈何秋。\n呼月出云头。\n问渠能饮不。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18240, '朝中措', '黎廷瑞', '游丝千万暖风柔，只系得春愁。\n恨杀啼莺句引，孤他语燕攀留。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18241, '眼儿媚', '黎廷瑞', '暖云挟雨洗尘埃。\n地峭寒翠。\n燕儿知否，莺儿知否，厮句春回。\n小楼日日重帘卷，应是把人猜。\n杏花如许，桃花如许，不见归来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18242, '诉衷情', '黎廷瑞', '曲屏深院赴幽期。\n心事梦云知。\n佩环零乱何处，江上草离离。\n日平西，天似幕，月如眉。\n依稀还记，两岸杨花，送上船时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18243, '贺新郎', '黎廷瑞', '帆影斜阳里。\n与芦花、分风飞过，落星遗此。\n瓦老苔荒钟鼓陋，斑剥，残碑无几。\n想此处、阅人多矣。\n天上白榆犹落去，况人间、一瞬浮花蕊。\n问五老，笑而已。\n仙翁当日曾挥麈。\n拍阑干、浩歌音响，振鱼龙耳。\n九十馀年无人问，遗韵半江烟水。\n慨宇宙、风涛如许。\n安得六丁移此石，去横身、作个中流砥。\n长唱罢，冥鸿起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18244, '青玉案', '黎廷瑞', '巨舟双橹鸣鹅鹳。\n千万顷、玻璃面。\n宇宙浮萍堪永叹。\n黄唐开辟，秦隋争战。\n不把江山换。\n芦花新雪秋撩乱。\n何处渔舟起孤管。\n一片古愁萦不断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18245, '酹江月・念奴娇', '黎廷瑞', '远山如簇，对楼前、浓抹淡妆新翠。\n应是西湖湖上景，移过江南千里。\n旧日春光，重归杨柳，苒苒黄金缕。\n市声分付，画桥之外流水。\n最好叠观泥金，危城带粉，文笔双峰倚。\n烟寺晚钟渔浦笛，都入王维画里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18246, '酹江月・念奴娇', '黎廷瑞', '锦袍何处，向旧江、衰草寒芦萧瑟。\n瀛馆神仙挥玉尘，唤醒诗酒魂魄。\n走电飞红，惊涛触石，举目乾坤窄。\n油然归去，短篷多载风月。\n好在雨外云根，水边石上，鸥鹭盟重结。\n见说西湖湖上路，香沁梅梢新雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18247, '一翦梅', '黎廷瑞', '小小黄花尔许愁。\n楚事悠悠。\n晋事悠悠。\n荒芜三径渺中洲。\n开几番秋。\n落几番秋。\n不是孤芳万古留。\n餐亦堪羞。\n采亦堪羞。\n离骚赋罢酒新。\n醒也风流。\n醉也风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18248, '水龙吟', '黎廷瑞', '荒城落日西风，满街芳草无行路。\n楼台羽化，萤飞故苑，蛩吟残础。\n不减承平，半湖秋月，隔溪烟树。\n慨江南风景，一朝如许，教人恨、王夷甫。\n对酒强推愁去。\n酒醒来、愁还如故。\n青萍三尺，阴符一卷，土花尘蠹。\n试问黄花，花知余否，沈吟无语。\n拍阑干，空羡平沙落雁，沧波归鹭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18249, '清平乐', '黎廷瑞', '清明寒食。\n过了空相忆。\n千里音书无处觅。\n渺渺乱芜摇碧。\n苍天雨细风斜。\n小楼燕子谁家。\n只道春寒都尽，一分犹在桐花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18250, '秦楼月・忆秦娥', '黎廷瑞', '云根屋。\n东风四壁花如玉。\n花如玉。\n水仙伤婉。\n山矾伤俗。\n高标懒趁时妆束。\n一丘一壑便幽独。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18251, '秦楼月・忆秦娥', '黎廷瑞', '罗浮暮。\n青松林下相逢处。\n相逢处。\n缟衣素袂，沈吟无语。\n行云飞入瑶台路。\n梦回飘渺香风度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18252, '秦楼月・忆秦娥', '黎廷瑞', '叶叶里。\n一枝冷浸铜瓶水。\n铜瓶水。\n飞英簇簇，砚屏香几。\n夜来雪片敲窗纸。\n半衾芳梦相料理。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18253, '秦楼月・忆秦娥', '黎廷瑞', '春脉脉。\n含章檐下妆宫额。\n妆宫额。\n也还点画，春烟茅结。\n人间天上俱清绝。\n风流大似东坡客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18254, '秦楼月・忆秦娥', '黎廷瑞', '红苞拆。\n巡檐一笑风情别。\n风情别。\n广平空道，心肠如铁。\n灞桥更有狂吟客。\n短鞭破帽貂裘窄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18255, '秦楼月・忆秦娥', '黎廷瑞', '春来了。\n孤根矫树花开早。\n花开早。\n水村山郭，嫩红晴晓。\n陇头何处鳞鸿香。\n一枝欲寄行人少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18256, '秦楼月・忆秦娥', '黎廷瑞', '齐山硕。\n扫开残雪簪花饮。\n簪花饮。\n樽前人唱，暗香疏影。\n枝南枝北迢迢恨。\n春风旧梦难重省。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18257, '秦楼月・忆秦娥', '黎廷瑞', '花孤冷。\n海棠聘与花应肯。\n花应肯。\n海棠只是，无香堪恨。\n香无却有仙风韵。\n能争几日芳期近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18258, '秦楼月・忆秦娥', '黎廷瑞', '醒人眼。\n一枝玉雪疏篱晚。\n疏篱晚。\n精神旷逸。\n风姿凝远。\n幽香零乱无人管。\n依依春恨天涯满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18259, '秦楼月・忆秦娥', '黎廷瑞', '幽香歇。\n玉龙吹彻花如雪。\n花如雪。\n小桥流水，不胜愁绝。\n横梢翦入生绡墨。\n翠阴青子盈盈结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18260, '贺新郎', '李震', '楼据湖山背。\n倚高寒、尘飞不到，越山相对。\n老月腾辉群动息，独坐清分沆瀣。\n更满听、潮声澎湃。\n醉里诗成神鬼泣，景苍凉、又在新诗外。\n浑忘却、功名债。\n凭谁妙笔能图绘。\n羡中郎、前身摩诘，宛然心会。\n拈出清宵无限意，半幅溪藤光怪。\n方信有、人间仙界。\n云淡天低奇绝处，笑僧殊、未识丹青在。\n留此轴，夸千载。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18261, '贺新郎', '陈纪', '趁拍哀弦促。\n听泠泠、弦间细语，手间推覆。\n莺语间关花底滑，急雨斜穿梧竹。\n又涧底、松风簌簌。\n铁拨弦春夜永，对金钗锺乳人如玉。\n敲象板，翦银烛。\n六么声断凉州续。\n怅梅花、岁晚天寒，佳人空谷。\n有限弦声无限意，沦落天涯幽独。\n顿唤起、闲愁千斛。\n贺老定场无处问，到如今，只鼓昭君曲。\n呼羯鼓，泻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18262, '念奴娇', '陈纪', '断桥流水，见横斜清浅，一枝孤袅。\n清气乾坤能有几，都被梅花占了。\n玉质生香，冰肌不栗，韵在霜天晓。\n林间姑射，高情迥出尘表。\n除是孤竹夷齐，商山四皓，与尔方向调。\n世上纷纷巡檐者，尔辈何堪一笑。\n风雨忧愁，年来何逊，孤负渠多少。\n参横月落，有怀付与青鸟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18263, '满江红', '陈纪', '凤去台空，庭叶下、嫩寒初透。\n人世上、几番风雨，几番重九。\n列岫迢迢供远目，晴空荡荡容长袖。\n把中年、怀抱更登台，秋知否。\n天亦老，山应瘦。\n时易失，欢难久。\n到于今惟有，黄花依旧。\n岁晚凄其诸葛恨，乾坤只可渊明酒。\n忆坡头、老菊晚香寒，空搔首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18264, '倦寻芳', '陈纪', '满簪霜雪，一帽尘埃，消几寒食。\n手拈梨花，还是年时岑寂。\n簌簌落红春似梦，萋萋柔绿愁如织。\n怪东君、太匆匆，亦是人间行客。\n问几度、五侯传烛，但回首东风，吹尽尘迹。\n笑杜陵泪洒，金波如积。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18265, '摸鱼儿', '仇远', '爱青山、去红尘远，清清谁似巢许。\n白云窗冷灯花小，夜静对床听雨。\n愁不语。\n念锦屋瑶筝，却伴闲云住。\n莲心尚苦。\n谩自折兰苕，答书蕉叶，都是断肠句。\n鸥沙外，还笑失群鸳鸯。\n凄凉烟水深处。\n碧笺空寄江南弄，鸦墨乱无行数。\n梅半树。\n怅未识、佳人日暮情谁与。\n何时辇路。\n共系柳游鞯，印苔金屐，湖曲步春去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18266, '摸鱼儿', '仇远', '恼晴空、日长无力，风吹不尽愁绪。\n马头零乱流光转，粟粟巧黏红树。\n闲意度。\n似特地、随他燕子穿帘去。\n徘徊不语。\n谩彷弗眉尖，留连眼底，芳草正如雾。\n冥处。\n独凭阑干凝伫。\n翠蛾今在何许。\n隔花箫鼓春城暮。\n肠断小窗微雨。\n休更舞。\n明日看、池萍始信低飞误。\n长桥短浦。\n怅不似危红，苍苔点遍，犹涩马蹄驻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18267, '诉衷情', '仇远', '渚莲香贮一房秋。\n秋叶上人头。\n年光鬓影偷换，堪叹不堪留。\n人渺渺，事休休。\n恨悠悠。\n莼鲈不梦，也□归舟。\n家住沧洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18268, '台城路・齐天乐', '仇远', '暮云春树江东远，十年软红尘井。\n雨屋酣歌，月楼醉倚，还倩天风吹醒。\n青镫耿耿。\n算除却渊明，谁怜孤影。\n自卷荷衣，石床高卧翠微冷。\n山空但觉昼永。\n旧游花柳梦，不忍重省。\n燕子梁空，鸡儿巷静，休说长安风景。\n丹台路迥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18269, '临江仙', '仇远', '湘水晓行无酒，楚乡客久思家。\n空城暗柳老愁芽。\n燕归才社後，人老尚天涯。\n记得津头轻别，离觞愁听琵琶。\n东风吹泪落鸥沙。\n一番新雨重，飞不起杨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18270, '糖多令・唐多令', '仇远', '凉露湿秋芜。\n空庭啼蟪蛄。\n紫苔衣、犹护金铺。\n疏箔翠眉人不见，流水急，泣鳏鱼。\n恨草倩谁锄。\n西风吹鬓疏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18271, '如梦令', '仇远', '特特问花消息。\n结果剩红残白。\n芍药可人怜，相约荼シ留客。\n消得。\n消得。\n犹有一分春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18272, '如梦令', '仇远', '听尽西窗风雨。\n又听东邻砧杵。\n犹自立危阑，阑外青山无语。\n何处。\n何处。\n一树乱鸦啼暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18273, '南歌子', '仇远', '结屋依苍树，开窗对碧山。\n西湖不厌久长看。\n玉勒钿车偏在、六桥间。\n露柳凝朝润，烟花敛暮寒。\n才经人赏便阑残。\n谢柳辞花、醉策瘦筇还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18274, '南歌子', '仇远', '细细金丝柳，重重青黛山。\n玉人楼上倚愁看。\n移得浅颦深恨，上眉间。\n泪湿红绡薄，香凝碧绮寒。\n多情别去未春残。\n归趁海棠开後、燕双还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18275, '点绛唇', '仇远', '黄帽棕鞋，出门一步为行客。\n几时寒食。\n岸岸梨花白。\n马首山多，雨外青无色。\n谁禁得。\n残鹃孤驿。\n扑地春云黑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18276, '点绛唇', '仇远', '千里平阑，水天低处山无数。\n断城孤树。\n城外人来去。\n欲问青鸾，杳杳随烟雾。\n空怀古。\n巴山何处。\n自翦镫听雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18277, '蝶恋花', '仇远', '碧树残鹃啼未歇。\n昨夜春归，不与行人别。\n留得绿杨枝上月。\n晓风吹作晴天雪。\n龟甲屏低红叠叠。\n火暖萸烟。\n罗荐鸳鸯热。\n一插宝簪云妥贴。\n下阶先拣花枝折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18278, '蝶恋花', '仇远', '深院萧萧梧叶雨。\n知道秋来，不见秋来处。\n云压小桥人不渡。\n黄芦苦竹愁如雾。\n四壁秋声谁更赋。\n人只留春，不解留春住。\n秋又欲归天又暮。\n斜阳红影随鸦去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18279, '虞美人', '仇远', '满城风雨消凝处。\n谁是潘郎句。\n萧萧杨柳□凋黄。\n醉渡官桥瘦马、踏轻霜。\n旧时都道游春好。\n不似秋光小。\n菊花过了海棠来。\n定是催归锦字、不须开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18280, '阮郎归', '仇远', '教他双燕意循循。\n隔湖杨柳深。\n芹香泥滑趁新晴。\n差池来往频。\n春浪暖，绿无痕。\n醒人也醉人。\n断桥日落水云昏。\n归舟个个轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18281, '阮郎归', '仇远', '桃花坊陌散香红。\n捎鞭骤玉骢。\n官河柳带结春风。\n高楼小燕空。\n山暗霭，草蒙茸。\n江南春正浓。\n王孙家在画桥东。\n相寻无路通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18282, '渡江云', '仇远', '流莺啼怨粉，嫩寒著柳，语尚困东风。\n问荒垣旧藓，烟雨何时，溅泪瘗危红。\n□愁不尽，对乱花、芳草茸茸。\n嗟绮尘、漂零无定，绡幕燕巢空。\n匆匆。\n玉銮声杳，绣屋香消，谩精神入梦。\n记旧家、定场声价，曾冠深宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18283, '卜算子', '仇远', '疏树小花风，别浦残鹃雨。\n不是王孙忘却归，草没归来路。\n空积琐窗尘，谁按琼箫谱。\n暗把金钱卜远人，争敢分明语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18284, '眼儿媚', '仇远', '谢家池馆占花中。\n微雨湿春风。\n艳红修碧，浓香疏影，浮动帘栊。\n娇蛾聚翠寻春梦，衣上泪痕重。\n闲窗愁对，金笼鹦鹉，彩带芙蓉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18285, '眼儿媚', '仇远', '伤春情味酒频中。\n困倚小屏风。\n宝钗斜插，懒来梳洗，懒出帘栊。\n云鬟娇无力，此醉不禁重。\n分明彷佛，未央杨柳，太液芙蓉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18286, '谒金门', '仇远', '但病酒。\n愁对清明时候。\n不为吟诗应也瘦。\n坐久衣痕皱。\n曾约花间携手。\n空忆洛阳耆旧。\n道不相逢还却又。\n海棠开厮句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18287, '南乡子', '仇远', '急雨涨潮头。\n越树吴城势拍浮。\n海鹤一声苍竹裂，扁舟。\n轻载行云压水流。\n独倚最高楼。\n回首屏山叠叠秋。\n江上数峰人不见，沙鸥。\n曾识西风独客愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18288, '酹江月・念奴娇', '仇远', '探春消息，觉南枝开遍，北枝犹阙。\n越女娉婷天下白，堪与冰霜争洁。\n孤影棱棱，暗香楚楚，水月成三绝。\n行云不动，素波轻浣尘袜。\n回首雪里关山，玉龙吹怨，似替人幽咽。\n溪上园林应满树，一径莓苔萦折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18289, '酹江月・念奴娇', '仇远', '片云凝墨，看荷花才湿，依然无雨。\n水槛空明人少到，却却幽禽相语。\n曲几横陈，长琴高挂，自奏南风谱。\n俄闻刀尺，隔窗人翦霜苎。\n因念西子湖边，闹红一舸，曾宿鸳鸯浦。\n翠羽不传沧岛信，日暮闲情□与。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18290, '玉蝴蝶', '仇远', '独立软红尘表，远吞翠雾，平挹纹澜。\n草长西垣，生怕隔断双鬟。\n树梢明、夕阳未冷，菱叶静、新雨初乾。\n倚阑干。\n一声鹅管，人影高寒。\n休寻王孙桂隐，白云鸡犬，曾识刘安。\n羽扇纶巾，不知门外有人闲。\n袖素手、懒招黄鹄，写碧笺、空寄青鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18291, '玉蝴蝶', '仇远', '野树昏鸦归尽，素烟如练，低罩平芜。\n断壁飞楼，红翠似有还无。\n女墙矮、月笼粉雉，娃馆静、尘暗金铺。\n问清都。\n广寒仙子，别後何如。\n愁予。\n十年梦境，浅歌短酒，总是欢娱。\n寂寞秦郎，不堪离镜照鸾孤。\n记曲径、共携素手，向闲窗、频拈吟须。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18292, '金缕曲・贺新郎', '仇远', '仙骨清无暑。\n爱兰桡、撑入鸳波，锦云深处。\n休唱采莲双浆曲，老却鸥朋鹭侣。\n算只有、青山如故。\n旧雨初晴新水涨，画桥低、杳霭迷苍渚。\n头戴笠，日亭午。\n独醒耿耿空怀楚。\n渺愁予、岸芷江蓠，尚青青否。\n锦瑟谩弹斑竹恨，难写湘妃怨语。\n怅谁与、孤芳为主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18293, '霜天晓角', '仇远', '绮帷高揭。\n风动流苏结。\n兴在夜凉多处，兰烬短、半明灭。\n醉彻。\n香未绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18294, '浪淘沙', '仇远', '芍药小纱窗。\n唾碧茸长。\n粉香犹旧时妆。\n玉佩丁东仙步远，好处难忘。\n草草赋高唐。\n终是荒凉。\n凉蟾飞入合欢床。\n争得花阴重邂逅，才不思量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18295, '烛影摇红', '仇远', '中酒情怀，怨春羞见桃花面。\n王孙别去草萋萋，十里青如染。\n不恨梨云梦远。\n恨只恨、盟深交浅。\n一般孤闷，两下相思，黄昏依黯。\n楼依斜阳，翠鸾不到音书远。\n绿窗空对绣鸳鸯，□缕凭谁翦。\n知在新亭旧院。\n杜鹃啼、东风意懒。\n便归来後，也过清明，花飞春减。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18296, '生查子', '仇远', '飞尘入建章，乐事难重见。\n白发故宫娃，闲说沈香宴。\n霓裳秋梦寒，□黏冰片。\n萤火起庭莎，犹忆轻罗扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18297, '醉落魄・一斛珠', '仇远', '水西云北。\n锦苞泫露无颜色。\n夜寒花外眠双。\n莫唱江南，谁是鹧鸪客。\n薄情青女司花籍。\n粉愁红怨啼急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18298, '江神子・江城子', '仇远', '云阶步影夜凄凉。\n采丹房。\n宿芽黄。\n万粟千萤，风露四阑香。\n歌断小山枝上月，环佩冷，怯流光。\n年时金屋罩琴床。\n忆情郎。\n淡梳妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18299, '八声甘州', '仇远', '敛双蛾、冷雨立毡车，离思上青枫。\n想天阶辞辇，长门分镜，征骑西东。\n应被婵娟早误，谁遣出深宫。\n鸾袖不堪绾，前事成空。\n独掩琵琶无语，恨主恩太薄，泪脸弹红。\n又争如汉月，深夜照帘栊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18300, '清平乐', '仇远', '寒泉如线。\n莎石绵云软。\n十里梅花香一片。\n不记入山深浅。\n谩留两袖春风。\n罗浮旧梦成空。\n独对阑干明月，教人犹忆山中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18301, '清平乐', '仇远', '苑秋凉早，石径幽花小。\n霜絮飞飞风草草。\n翠碧斓斑驰道。\n香沟诗叶难寻。\n依然绿浅红深。\n倚竹空歌黄鹄，谁招青冢游云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18302, '塞翁吟', '仇远', '短绿抽堤草，芳信未许花知。\n尚留冻梗冰枝。\n藓石雪消迟。\n方塘水浅鸳鸯冷，沙际水翼相依。\n拾翠约，踏青期。\n终是乐游稀。\n相思。\n江南远，渔汀渺渺，还又是、梅花谢时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18303, '塞翁吟', '仇远', '风柳吹残醉，惟枕梦便难寻。\n小院静，曲屏深。\n翦不断轻阴。\n新蚕乍扫鹅毛细，纤手镂叶如针。\n又负了，赏花心。\n听高树鸣禽。\n千金。\n嗟难买，飘红坠粉，怕容易、愁痕暗侵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18304, '忆旧游', '仇远', '忆寒烟古驿，淡月孤舟，无限江山。\n落叶牵离思，到秋来，夜夜梦入长安。\n故人翦烛清话，风雨半窗寒。\n甚宦海漂流，客毡寂寞，忍说闲关。\n征衫。\n赋归去，喜故里西湖，不厌重看。\n莫待青春晚，趁莺花未老，觅醉寻欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18305, '忆旧游', '仇远', '对庭芜黯淡，院柳萧疏，还又深秋。\n正一星镫暗，更一声雁过，一点萤流。\n合成一片离思，都在小红楼。\n想扑地阴云，人愁不尽，诗与天愁。\n酸风未应□，雨簌簌潇潇，欲下还收。\n忆绣帏贪睡，任花悄晨影，移上帘钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18306, '小秦王', '仇远', '眼溜秋潢脸晕霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18307, '小秦王', '仇远', '水拍江堤没软沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18308, '木兰花令', '仇远', '月堕觚棱寒鹊起。\n露拭秋空清似水。\n西风昨起过江南，红叶黄芜三四里。\n香莼先近幽人齿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18309, '八拍蛮', '仇远', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18310, '好女儿', '仇远', '恨结眉峰。\n两抹青浓。\n不人、昨夜曾中酒，甚小蛮绿困，太真红醉，肯嫁东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18311, '桃园忆故人・桃源忆故人', '仇远', '苎萝山下花藏路。\n只许流莺来去。\n吹落梨花无数。\n香雪迷官渡。\n浣纱溪浅人何许。\n空对碧云凝暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18312, '忆闷令', '仇远', '岸柳丝丝青尚浅。\n渐春归吴苑。\n缭垣不隔花屏，爱翠深红远。\n瞥地飞来何处燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18313, '极相思', '仇远', '云头灰冷，金彝熏透茜罗衫。\n可人犹带，紫陌青门，珠泪斑斑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18314, '少年游', '仇远', '钗云垂耳未胜冠，私语别青鸾。\n露帐银床，海棠睡足，偏称晚来看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18315, '燕归来・喜迁莺', '仇远', '三叠曲，四愁诗。\n心事少人知。\n西风未老燕迟归。\n巢冷半乾泥。\n流红句，回文字。\n除燕知，谁能记。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18316, '睡花阴令・醉花阴', '仇远', '愁云歇雨，净洗一奁秋霁。\n枝上鹊、欲栖还起。\n曲阑人独倚。\n持杯酌月，月未醉、笑人先醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18317, '望仙楼・胡捣练', '仇远', '九仙山晓。\n雾冥冥、一鹤飞来华表。\n衔得红云花岛。\n双蒂仙桃小。\n破罂旋汲香泉，短闲锄春草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18318, '眼儿媚', '仇远', '苔笺醉草调清平。\n鸦墨湿浮云。\n霓裳步冷，琼箫声断，旧梦关心。\n小乔不恋周郎老，翠被折秋痕。\n那堪门外，黄花红叶，细雨更深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18319, '爱月夜眠迟・爱月夜眠迟慢', '仇远', '小市收镫，渐柝声隐隐，人语沈沈。\n月华如水，香街尘冷，阑干琐碎花阴。\n罗帏不隔婵娟，多情伴人，孤枕最分明。\n见屏山翠叠，遮断行云。\n因记款曲西厢，趁凌波步影，笑拾遗簪。\n元宵相次近也，沙河箫鼓，却是如今。\n行行舞袖歌裙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18320, '花心动', '仇远', '醒眼明霞，问染成、晴堤几分秋色。\n腻困未醒，欲语还羞，掩映雾笼烟幂。\n艳姿相亚柔枝妥，恁娇倚、西风无力。\n只疑是、彩云散影，误留仙魄。\n不见芳卿消息。\n但晓沁嫣红，雨湿轻白。\n落日光中，窥影横塘，却似试妆脉脉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18321, '薄幸', '仇远', '眼波横秀。\n乍睡起、茸窗倦绣。\n甚脉脉、阑干凭晓，一握乱丝如柳。\n最恼人、微雨悭晴，飞红满地春风骤。\n记帕折香绡，簪敲凉玉，小约清明前後。\n昨梦云何处，应只在，春城迷酒。\n对溪桃羞语，海棠贪困，莺声唤醒愁仍旧。\n劝花休瘦。\n看钗盟再合，秋千小院同携手。\n回文锦字，寄与知他信否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18322, '风流子', '仇远', '红锦旧同心。\n西池上、曾与系青禽。\n记山水写情，秋桐促轸，鸳鸯萦恨，春绣停针。\n常叹好风妨画扇，明月堕瑶簪。\n短梦易残，一声长笛，新愁无限，何处孤砧。\n香奁依然在，但鸾镜、孤影渺渺难寻。\n雨後胭脂，应想粉蚀尘侵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18323, '清商怨', '仇远', '黄花丹叶绀草。\n染恨西园晓。\n梦度秦楼，孤鸿云影倒。\n连环旧约忘了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18324, '台城路・齐天乐', '仇远', '海棠才试春光小，西风便吹秋去。\n白石粼粼，丹林点点，装缀东皋南浦。\n清游顿阻。\n谩空有园林，可无钟鼓。\n一曲庭花，隔江谁与问商女。\n离怀浑似梦里，碧云犹冉冉，佳人何处。\n越岫难盟，秦楼燕约，争奈年华已暮。\n凭高吊古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18325, '醉公子', '仇远', '晓入蓬莱岛。\n松下锄瑶草。\n贪看碧桃花。\n误游金母家。\n一酌洼尊露。\n醉失归来路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18326, '台城路・齐天乐', '仇远', '画楼西送斜阳下，不随逝波东去。\n野旷莎长，山空木短，零落红衣南浦。\n游云路阻。\n便魂断苍梧，怨弦谁鼓。\n空采江蓠，□□□□吊湘女。\n迢迢千里万里。\n碧天空雁信，传意无处。\n翠袖闲笼，珠帏怨卧，几度黄昏□暮。\n相思自古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18327, '庆春宫・高阳台', '仇远', '江影涵空，山光浮水，画楼直倚东城。\n落叶声稀，归鸿声杳，晚风却递钟声。\n去天咫尺，祗疑是、齐云摘星。\n阑干疑伫，愁见垂杨，烟絮萦萦。\n官梅冷笑相迎。\n□怕繁枝，容易凋零。\n因念□□，吟仙鹤去，断桥谁赋疏清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18328, '阳台怨', '仇远', '月明如白日。\n遮径花阴密密。\n未见黄云衬袜来，空伴花阴立。\n疑是碧瑶台，不放彩鸾飞出。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18329, '梦江南・忆江南', '仇远', '花露湿，黯黯覆庭燕。\n十二阑干空见月，谁教凉影伴人孤。\n素被带香铺。\n情荏苒，金屋又笙竽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18330, '巫山一段云', '仇远', '酒力欺愁薄，轻红晕脸微。\n双鸳谁袖出青闺。\n袜步东西。\n倦蝶栖香懒，雏莺调语低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18331, '忆秦娥', '仇远', '秋乍觉。\n露凉顿觉罗衾薄。\n罗衾薄。\n黄昏庭院，水风帘幕。\n阑干待月花时约。\n愁长梦短浑忘却。\n浑忘却。\n南山猿鹤，北枝乌鹊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18332, '八犯玉交枝・八宝妆', '仇远', '沧岛云连，绿瀛秋入，暮景欲沈洲屿。\n无浪无风天地白，听得潮生人语。\n擎空孤柱。\n翠倚高阁恁虚，中流苍碧迷烟雾。\n惟见广寒门外，青无重数。\n遥想贝阙珠宫，琼林玉树。\n不知还是何处。\n倩谁问、凌波轻步。\n谩凝睇、乘鸾秦女。\n想庭曲、霓裳正舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18333, '夜行船', '仇远', '十二阑干和露倚。\n银潢淡、玉蟾如洗。\n万籁无声，纤云不染。\n目断楚天千里。\n自把黄花闲数蕊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18334, '荐金蕉', '仇远', '梅边当江南信。\n醉语无恁准。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18335, '思佳客', '仇远', '落尽红雨乍收。\n新篁静院叫钩。\n柳丝轻拂阑干角，怕引闲愁懒上楼。\n春淡淡，水悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18336, '思佳客', '仇远', '日影扶花一万重。\n秋香阁下又芙蓉。\n旧时楚楚霓裳，移入长杨短柳中。\n文碧，朱墙红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18337, '蝶恋花', '仇远', '燕燕楼空帘意静。\n露叶如啼，红沁胭脂井。\n浅约深盟期未定。\n木犀风里鸳鸯径。\n楚岫秦眉相入映。\n私倚云阑，淡月笼花顶。\n今夕兰空吊影。\n绣衾罗荐馀香冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18338, '秋蕊香', '仇远', '三径归来秋早。\n门外金铺谁扫。\n东篱不种闲花草。\n恼乱西风未了。\n霜华侵鬓渊明老。\n南山晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18339, '解连环', '仇远', '绮疏人独。\n记芙蓉院宇，玉箫同宿。\n尚隐约、屏窄山多，□衾暖浪浮，帐香云扑。\n步袜蹁然，又何处、秦筝金屋。\n□柔簪易折，破镜难留，断缕难续。\n斜阳谩穷倦目。\n甚天寒袖薄，犹倚修竹。\n待听雨、闲说前期，奈心在江南，人在江北。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18340, '雪狮儿', '仇远', '武林春早，乘兴试问，孤山枝南枝北。\n见说椒红，初破芳苞犹绿。\n罗浮梦熟。\n记曾有、幽禽同宿。\n依稀是、缟衣楚楚，佳人空谷。\n娇小春意未足。\n甚娇羞，怕入玉堂金屋。\n误学宫妆，粉额蜂黄轻扑。\n江空岁晚，最难是、旧交松竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18341, '探芳信', '仇远', '坐清昼。\n记步幄行春，短亭呼酒。\n怅湔裙香远，波痕尚依旧。\n亦阑桥下桃花观，寒勒花枝瘦。\n转回廊、古瓦生松，暗泉鸣。\n山雨夜来骤。\n便绿涨平堤，云横远岫。\n细认沙头，还见有落红否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18342, '琐窗寒', '仇远', '小袖啼红，残茸唾碧，深愁如织。\n闲愁不断，冉冉舞丝千尺。\n倚修筠、袖笼浅寒，望人在水西云北。\n想绿杨影里，兰舟轻舣，赤阑桥侧。\n游剧归来，恨汗湿酥融，步悭袜窄。\n兰情蕙盼，付与栖鸾消息。\n奈无情、风雨做愁，帐镫闪闪春寂寂。\n梦相思、一枕巫山，更画楼吹笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18343, '一寸金', '仇远', '楼倚寒城，隔岸江山见东越。\n望远红千尺，游丝起舞，空青一段，斜阳明灭。\n孤树秋声歇。\n霜枝袅、尚留病叶。\n阑干外、带郭人家，蜂房几盘折。\n我独逍遥，乘虚凭远，天风醒毛发。\n问西窗停烛，谁吟巴雨，连床鼓瑟，谁弹湘月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18344, '声声慢', '仇远', '藏莺院静，浮鸭池荒。\n绿阴不减红芳。\n高卧虚堂。\n南风时送微凉。\n游鞯践香未遍，怪青春、别我堂堂。\n闲里好，有故书盈箧，新酒盈缸。\n只怕吴霜侵鬓，叹春深铜雀，空老周郎。\n弱絮沾泥，如今梦冷平康。\n翻思旧游踪迹，认断云、低度横塘。\n离恨满，甚月明、偏照小窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18345, '越山青・长相思', '仇远', '四月时。\n五月时。\n柳絮无风不肯飞。\n卷帘看燕归。\n雨凄凄。\n草凄凄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18346, '尾犯', '仇远', '宝蜡夜笼花，不碍画楼，无限清景。\n病叶分秋，翦愁桐金井。\n银汉外、尘飞不到，暮云收、琉璃万顷。\n弁山横翠，好倩西风，送上江心镜。\n霓裳空楚楚，钧天旧梦难醒。\n最忆婵娟，□钗钿香冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18347, '两同心', '仇远', '踏青归後，小步西园。\n翠袖薄、新篁难倚，绿窗润、弱絮轻黏。\n春风急，暮雨凄然。\n早听啼鹃。\n忆昔几度湖边。\n款曲花前。\n约俊客、同倾凿落，看游女、同上秋千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18348, '瑶花慢', '仇远', '疏疏密密，漠漠纷纷，乍舞风无力。\n残砖断础，才转眼、化作方圭园壁。\n非花非絮，似骋巧、先投窗隙。\n立小楼、不见青山，万里鸟飞无迹。\n休邻冻梗冰苔，算飞入园林，都是春色。\n年华婉娩，谁信道、老却梁园词客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18349, '破阵子', '仇远', '柳浪六桥春碧，香尘十里香风。\n好是烂游浓醉後，画□阑干见小红。\n红明绿暗中。\n旧约涌金门道，纱笼毕竟相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18350, '凤凰阁', '仇远', '晴绵欺雪，扑扑红楼锦幄。\n小晴蜓载水花泊。\n犹记横波浅笑，香云深约。\n甚可怪、匆匆忘却。\n寻芳人老，那得心情问著。\n雁程不到怨无托。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18351, '归田乐', '仇远', '略横溪曲。\n映带短莎修竹。\n傍岸谁家屋。\n爱水护遥碧，林拥深绿。\n呼布谷。\n东里西邻才一簇。\n社鼓初鸣春酒熟。\n长衫方帽，翁醉扶黄犊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18352, '解佩令', '仇远', '浅莎深苑，流萤暗度。\n问霜纨、藏在何处。\n一自西风，乱翦翦、枝头红露。\n怕因循、彩鸾尘蠹。\n歌台香散，离宫烛暗，谩消凝、凌波微步。\n最怕黄昏，小楼外、零云残雨。\n把相思、共青镫诉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18353, '何满子・河满子', '仇远', '舞褥行云衬步，歌纨片月生怀。\n歌残舞罢花困软，凝情犹小徘徊。\n髻滑频扶堕珥，裙低略露弓鞋。\n当日凝香清燕，惯听八拍三台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18354, '更漏子', '仇远', '楝花风，都过了。\n冷落绿阴池沼。\n春草草，草离离。\n离人归未归。\n暗魂消，频梦见。\n依约旧时庭院。\n红笑浅，绿颦深。\n东风不自禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18355, '庆清朝', '仇远', '山束滩声，月移石影，寒江夜色空浮。\n丹青古壁，风幡横卧东流。\n小舣载云轻棹，湖痕渐落葑泥稠。\n津亭外，隔船吹笛，唤起眠鸥。\n非但予愁渺渺，料那人，应自有、一襟愁。\n霜栖露泊，容易吹白人头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18356, '一落索', '仇远', '尽日西阑凭醉。\n新寒难睡。\n袖炉烟冷帐云宽，倩倩倩、先温被。\n空对短屏山水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18357, '相思引', '仇远', '鸦墨斜行印粉香。\n倚楼凝望过鸿将。\n寸心天远，月冷梦浮湘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18358, '生查子', '仇远', '钗头缀玉虫，耿耿东窗晓。\n京洛少年游，犹恨归来早。\n寒食正梨花，古道多芳草。\n今夜试青镫，依旧春花小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18359, '合欢带', '仇远', '令巍巍、一段风流。\n看情性、忒温柔。\n记得河桥曾识面，雨凝晴、欲问还羞。\n沈吟半晌，蝉舞鬓、莺涩歌喉。\n到黄昏饮散，□虽未语，心已相留。\n纱窗低转，红袖同携，随花归去秦楼。\n酒力难禁花易软，聚眉峰、点点清愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18360, '思佳客', '仇远', '家住银塘东复东。\n赤阑桥下笑相逢。\n春风豆蔻抽新绿，夜雨茱萸湿老红。\n鸥鸟散，水天空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18361, '思佳客', '仇远', '东壁谁家夜捣砧。\n荆江流滞客偏闲。\n三三五五潇湘雁，飞尽南云入北云。\n人独自，月黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18362, '思佳客', '仇远', '霜醉秋花锦覆堤。\n西风一舸小桥西。\n闲将窗下红兰梦，写入江南白苎词。\n芳绪断，旧游非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18363, '满江红', '仇远', '脂雨东流，觉春去、绿阴如幄。\n尝记得、桃花碧径，自怜幽独。\n日暮碧云空冉冉，摘花小袖犹依竹。\n望江南、草色欲连天，人江北。\n谁共翦，西窗烛。\n谁共度，西园曲。\n甚采香情懒，楚骚谁续。\n海远休寻双燕信，夜长争忍孤鸾宿。\n夹缃签、曾有旧题诗，镫前读。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18364, '浣溪沙', '仇远', '鸦墨鸳茸暗小窗。\n栀花时递淡中香。\n何须华屋艳红妆。\n栊月凉筛金琐碎，床琴清写玉丁当。\n风车闲倚在回廊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18365, '浣溪沙', '仇远', '薄薄梳妆细扫眉。\n鬟鸦双叠岭云低。\n对人浓笑问归期。\n荀令老来香已减，谢娘别後梦应迷。\n一番心事只春知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18366, '浣溪沙', '仇远', '红紫妆林绿满池，游丝飞絮两依依。\n正当谷雨弄晴时。\n射鸭矮阑苍藓滑，画眉小槛晚花迟。\n一年弹指又春归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18367, '浣溪沙', '仇远', '豆蔻枝头冷蝶飞。\n荼縻花里老莺啼。\n懒留春住听春归。\n北海芳尊谁共醉，东山游屐近应稀。\n小窗寒草送春时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18368, '西江月', '仇远', '犹记春风庭院，桃花初识刘郎。\n绿腰传得旧官腔。\n自向花前学唱。\n锦瑟空寻小袖，翠衾尚带馀香。\n一番拈起一思量。\n又是桃花月上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18369, '西江月', '仇远', '楚塞残星几点，关山明月三年。\n长亭犹有竹如椽。\n可惜中郎不见。\n折柳新愁未歇，落梅旧梦谁圆。\n何人吹向内门前。\n一片鹧鸪清怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18370, '西江月', '仇远', '漠漠河桥柳外，门巷镫初。\n笙歌饮散醉相扶。\n明月伴人归去。\n娃馆深藏云木，女墙斜掠烟芜。\n水天空阔见西湖。\n鹤立夜寒多处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18371, '西江月', '仇远', '暗柳荒城叠鼓，小花静院深镫。\n年年寒食可曾晴。\n今夜晴犹未稳。\n豆蔻梢头二月，杜鹃枝上三更。\n春风知得此时情。\n吹动秋千红影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18372, '西江月', '仇远', '小立画桥西畔，仙车蓦送香风。\n多情问我太匆匆。\n疑是当年小宋。\n须识蓬山不远，梨云路杳无踪。\n觉来斜月隔帘栊。\n不是相逢是梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18373, '满庭芳', '仇远', '寒食无情，阳春如客。\n晚风吹尽繁枝。\n落红堆径，小槛立移时。\n乐事不堪再省，吴乡远、愁思依依。\n谁家燕，斜穿绣幕，轻惹画梁泥。\n还知。\n人寂寞，殷勤软语，来说差池。\n怕王孙归去，芳草离离。\n倚翠屏山梦断，无心听、啼鸟催归。\n何时向，溪流练带，一舸载鸱夷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18374, '减字木兰花', '仇远', '鸡儿画曲。\n处处筝鸣雨屋。\n十载重游。\n柳外啼乌也怨秋。\n粉楹醉墨。\n燕去楼空人不识。\n醉踏花阴。\n错认人家月下门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18375, '减字木兰花', '仇远', '三生杜牧。\n惯识小红楼上宿。\n压帽花斜。\n醉跨门前白鼻。\n归来寻睡。\n懒拨熏炉温素被。\n两袖香尘。\n肯信春风老得人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18376, '减字木兰花', '仇远', '一番春暮。\n恼人更下潇潇雨。\n花片纷纷。\n燕子人家都是春。\n莫留春住。\n问春归去家何处。\n春与人期。\n春未归时人未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18377, '木兰花慢', '仇远', '远钟消断梦，又霜信、到纹窗。\n有六曲屏山，四垂斗帐，重锦方床。\n轻寒画眉尚懒，想留连、一线枕痕香。\n无语因谁悒怏，何心重理丝簧。\n花房。\n空记旧周郎。\n指印□鸳鸯。\n悄不堪□□，暗尘绣陌，淡月幽坊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18378, '木兰花慢', '仇远', '泥凉闲倚竹，奈冉冉、碧云何。\n爱水槛空明，风疏画扇，雪透香罗。\n惺松未成楚梦，看玲珑、清影罩平坡。\n便有一庭秋意，碎蛩声乱寒莎。\n银河。\n不起纤波。\n天似水，月明多。\n算江南再有，贺方回在，空费吟哦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18379, '木兰花令', '仇远', '一声啼无芳草。\n南浦晴波云渺渺。\n蠹尘珠网满香车，三十六桥春悄悄。\n垂杨柳舞吹笙道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18380, '菩萨蛮', '仇远', '翠鸾不隔巫山路。\n无人肯指行云处。\n徙倚最高楼。\n秋波春望愁。\n先来愁似雾。\n更下丝丝雨。\n芳径溅香泥。\n苔花滑马蹄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18381, '菩萨蛮', '仇远', '瑶琴欲把相思谱。\n殷勤难写相思语。\n人在碧苕滨。\n相思烟水深。\n鳞波流碎月。\n荏苒年芳歇。\n何处寄相思。\n白苹秋一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18382, '水龙吟', '仇远', '晓星低射疏，寒却枕还慵起。\n炊烟逗屋，隔房人语，镫前行李。\n霜滑平桥，雾迷衰草，时间流水。\n怅雕鞍独拥，清寒满袖，入斜月、空山里。\n谩把鞭梢暗指。\n酒旗边、柴门又闭。\n分水点墨，因风欲寄，梅花万里。\n宝帐春慵，梦中肯信，有人憔悴。\n待归来、别倚新腔，换却泪毫愁纸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18383, '早梅芳近・早梅芳', '仇远', '碧溪湾，疏竹外，正小春天气。\n绿珠羞涩，半吐椒红可人意。\n月香传瘦影，露脸凝清泪。\n笑倡条冶叶，怕冷尚贪睡。\n马行迟，雪未霁。\n还忆前村里。\n青禽啁哳，疑是当时梦初起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18384, '齐天乐', '仇远', '夕阳门巷荒城曲，清音早鸣秋树。\n薄翦绡衣，凉生鬓影，独饮天边风露。\n朝朝暮暮。\n奈一度凄吟，一番凄楚。\n尚有残声，蓦然飞过别枝去。\n齐宫往事谩省，行人犹与说，当时齐女。\n雨歇空山，月笼古柳，彷佛旧曾听处。\n离情正苦。\n甚懒拂冰笺，倦拈琴谱。\n满地霜红，浅莎寻蜕羽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18385, '湘月・念奴娇', '董嗣杲', '莲幽竹邃，旧池亭几处，多爱君子。\n醉玉吹香还认取，忙里得闲标致。\n心逐云帆，情随烟笛，高会知谁继。\n宵筵会启，蓦然身外浮世。\n因见杜牧疏狂，前缘梦里，谩蹙双眉翠。\n香满屏山春满几，炉拥麝焦禽睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18386, '齐天乐', '董嗣杲', '玉山曾醉凉州梦，图芳无今古。\n露颗虬藤，风枝蠹叶，遗墨何人收取。\n当时赠与。\n记轻别西湖，笑离南浦。\n万里奚囊，岂知随处助吟苦。\n归来情寄谩远，旧寻犹在望，荒亭荒圃。\n绀蕾攒冰，苍阴弄月，休说堆盘马乳。\n云梯尚阻。\n袖一幅秋烟，扫空尘土。\n静想山窗，半乘寒架雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18387, '失调名', '高远', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18388, '霜天晓角', '杨均', '丹楹转月。\n金绣纷幢钺。\n勋在有唐宗社，人千载、仰英烈。\n维辰嗟尽节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18389, '霜天晓角', '杨均', '当年宋壁。\n血拥河流赤。\n全护东南形胜，百易万、五神力。\n人心同奋激。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18390, '霜天晓角', '杨均', '忠忱谊。\n对越如丹赤。\n缅想遗风馀烈，犹身见、古颜色。\n惟馨非黍稷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18391, '水调歌头', '胡幼黄', '有喜君初度，风雨作秋声。\n连旬烈日，稻畦麦垅欲扬尘。\n好似天瓢在手，笑把群龙呵叱，四野注如倾。\n勃勃生意满，翠浪涌纵横。\n君知否，仁者寿，寿斯仁。\n自从三代而下，民命寄苍。\n满目桑麻谷粟，满目簿书期会，试说与仁人。\n小试作霖手，苏醒永新民。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18392, '婆罗门引', '熊禾', '秋宵倦起，起来风露湿人衣。\n休休未是早行时。\n旋摘青蔬炊饭，暖酒就炉围。\n值青山有意，且把诗题。\n兴阑便归，忽邂逅、故人期。\n道是游山正叔，消息曾知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18393, '沁园春', '熊禾', '自笑生身，历事以来，垂六十年。\n今浮沈闾里，半非识面，交游朋友，各已华颠。\n富贵不来，少年已去，空见悠悠岁月迁。\n虽然是，壮心一点，犹自依然。\n新阳又长天边。\n人指似山间诗酒仙。\n算胸次崔嵬，不胜百，笔端枯槁，难足千篇。\n隐几杖藜，相耕听诵，聊看诸郎相後先。\n馀何事，但读书煮茗，日晏高眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18394, '满庭芳', '熊禾', '斗转旋霄，梧飘金井，洞天秋气方新。\n幔亭仙子，飞佩下瑶京。\n霞袂霓裳缥缈，冰肌莹、月作精神。\n云动，琼仙歌舞，共庆捧瑶觥。\n蟾宫，人未老，纵横礼乐，谈笑功句名。\n从今去，有多少、富贵光荣。\n且听宾云奏曲，千秋岁、更引清声。\n齐眉处，朱颜绿鬓，相与共长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18395, '瑞鹤仙', '熊禾', '翠旗迎风辇。\n正金母、西游瑶台宝殿。\n蓬莱都历遍。\n□飘然来到，笙歌庭院。\n朱颜绿鬓。\n须尽道、人间罕见。\n更恰恰占得，美景良辰，小春天暖。\n开宴。\n画堂深处，银烛高烧，珠帘任卷。\n香浮宝篆。\n翻舞袖，掩歌扇。\n看兰孙桂子，成团成簇，共捧金荷齐劝。\n□从今、鹤算龟龄，天长地远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18396, '鹊桥仙', '詹无咎', '龟儿吐火，鹤儿衔火。\n药线上、轮儿走火。\n十胜一斗七星毯，一架上、有许多包裹。\n梨花数朵。\n杏花数朵。\n又开放、牡丹数朵。\n便当场好手路歧人，也须教、点头咽唾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18397, '贺新郎', '詹无咎', '梅子黄时雨。\n对幽窗、依依抱独，几多愁绪。\n润逼琴丝无雅韵，难续文园旧诣。\n头白尽、相如谁顾。\n燕子楼空尘又锁，望天涯、不寄红丝缕。\n嗟往事，且休语。\n伤情当日班衣舞。\n更宫衣、香罗乍带，九天繁露。\n一寸草心迎永日，更把葵心自许。\n怎料有、风推雨如。\n惹起灵均千古恨，转凄凉、更不成端午。\n拼小醉，读骚句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18398, '水龙吟', '王槐建', '武夷一片闲云，被风吹落清原顶。\n溪梅馥馥，飞来相傍，不嫌凄冷。\n瓦釜争鸣，丝桐一曲，满城倾听。\n奈阳春未了，骊驹已驾，桐阴底、梦魂醒。\n何限吟笺赋笔，甚乡心、分却清兴。\n鳌峰胜处，遥知风月，属谁管领。\n邂逅何时，无穷事业，有穷光景。\n但相期、不负初心，此外分、皆前定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18399, '祝英台近', '刘应李', '濯沧浪，歌窈窕，云日弄微霁。\n屏倚曾空，鹤去几何岁。\n尚留洞草芊青，岩花重碧，游泳处、露中风袂。\n木兰舣。\n亭外冉冉斜阳，杯行尚联断。\n独凭危阑，解渴漱寒水。\n少须酒力还低，茶香不断，清与处、月明川底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18400, '摸鱼儿', '王梦应', '问谁歌、暗香疏影，此花堪照人世。\n起持霜月为花寿，天亦愿花千岁。\n谁有意。\n著如此人间，更著花如此。\n高寒洒洒。\n看浩荡刚风，跨虬飞佩，玉影乱如水。\n行春处，一笑人间紫翠。\n纷纷窥此天地。\n寿如川至。\n□好是、涧翁兹岁喜。\n荣沾南儒恩例。\n捧觞更喜郎君美。\n任夜来归侍。\n见说生辰，恰逢本命，寿筵且未。\n听老聃孙子。\n祝公耆艾，祝公富贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18401, '锦堂春・锦堂春慢', '王梦应', '浅帻分秋，凉尊试月，西风未雁犹蝉。\n看芙蓉影里，绿鬓年年。\n日上云帆压海，尘清玉马行天。\n更烟楼凤举，风幕麟游，锦後珠前。\n绿阴池馆如画，记晴春药径，雨晓芝田。\n已办十年笑语，小聚云边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18402, '念奴娇', '王梦应', '欲霜更雨，记青云篱落，东风前此。\n帘外客秋人共老，雁与愁飞千里。\n水郭烟明，竹陂波小，万叶寒声起。\n凭高那更，九嶷吹尽云气。\n婉娩空复多情，年年晋梦，花与柴桑是。\n谁解意消风日晚，短笛孤舟林水。\n江蟹笼新，露萸斟浅，浇得乡关思。\n平芜天远，一痕黄抹秋霁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18403, '疏影', '王梦应', '瞢腾晓被，听堕冰屋角，晴仍未。\n土湿烟生，庭掩寒青，障泥懒为春试。\n东风旧与花飞去，料记得、年年沙际。\n忍落梅、万点苔根，化作一窗离思。\n犹忆蔫红稚绿，断桥雪未扫，天近春易。\n老对荒寒，事旧人新，雁後不成情味。\n人间解有花如海，待一片、不教随水。\n但玉香、酥影玲珑，逐日暖红云里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18404, '醉太平', '王梦应', '寒窗月晴。\n寒梢露明。\n一痕归影灯青。\n又分携短亭。\n蘅皋佩云。\n蒸溪酒春。\n有谁勤说归程。\n是峰头雁声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18405, '渔父词・渔父', '孙锐', '平湖千顷浪花飞。\n春後银鱼霜更肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18406, '水调歌头', '孙锐', '渔钓有遗逸，天子宠元真。\n赐之奴仆，得随妫艳下神京。\n几度苹汀蓼岸，不问金钩无饵，谈笑取冰鳞。\n珍重主人意，名我曰樵青。\n肩兰桨，萦桂棹，出波津。\n凌虚上□□□，□□会群真。\n卸下绿蓑青笠，付与渔童收管，相与□红尘。\n归去又□□，同赏洞中春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18407, '满江红', '李琳', '碧醮江山，鹤唳晓、云献画屏。\n瑶宫敞，舞金翔翠，巍枕春城。\n龙背神瓢飞旱雨，虹光花石转阴晴。\n蔼昼香、飞雾福苍生，千古灵。\n箫莺响，笙鹤鸣。\n瑞烟起，彩云行。\n满阑干花影，绣扬帘旌。\n佛界三千笼日月，仙楼十二挂星辰。\n望赭袍、霞佩并云，游紫清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18408, '木兰花慢', '李琳', '蕊珠仙驭远，横羽葆、簇霓旌。\n甚鸾月流辉，凤云布彩，翠绕蓬瀛。\n舞衣怯环佩冷，问梨园、几度沸歌声。\n梦里芝田八骏，禁中花漏三更。\n繁华一瞬化飞尘，辇路劫灰平。\n恨碧灭烟销，红凋露粉，寂寞秋城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18409, '六么令', '李琳', '淡烟疏雨，香径渺啼。\n新晴昼帘闲卷，燕外寒犹力。\n依约天涯芳草，染得春风碧。\n人间陈迹。\n斜阳今古，几缕游丝趁飞蝶。\n柳向尊前起舞，又觉春如客。\n翠袖折取嫣红，笑与簪华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18410, '一翦梅', '醴陵士人', '宰相巍巍坐庙堂。\n说着经量。\n便要经量。\n那个臣僚上一章。\n头说经量。\n尾说经量。\n轻狂太守在吾邦。\n闻说经量。\n星夜经量。\n山东河北久抛荒。\n好去经量。\n胡不经量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18411, '百字令・念奴娇', '褚生', '半堤花雨。\n对芳辰消遣，无奈情绪。\n春色尚堪描画在，万紫千红尘土。\n鹃促归期，莺收佞舌，燕作留人语。\n绕栏红药，韶华留作孤主。\n真个恨杀东风，几番过了，不似今番苦。\n乐事赏心磨灭尽，忽见飞书传羽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18412, '祝英台近', '褚生', '倚危栏，斜日暮。\n蓦蓦甚情绪。\n稚柳娇黄，全未禁风雨。\n春江万里云涛，扁舟飞渡。\n那更听、塞鸿无数。\n叹离阻。\n有恨落天涯，谁念孤旅。\n满目风尘，冉冉如飞雾。\n是何人惹愁来，那人何处。\n怎知道、愁来不去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18413, '满庭芳', '徐君宝妻', '汉上繁华，江南人物，尚遗宣政风流。\n绿窗朱户，十里烂银钩。\n一旦刀兵齐举，旌旗拥、百万貔貅。\n长驱入，歌台舞榭，风卷落花愁。\n清平三百载，典章人物，扫地俱休。\n幸此身未北，犹客南州。\n破鉴徐郎何在，空惆怅、相见无由。\n从今後，梦魂千里，夜夜岳阳楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18414, '霜天晓角', '徐君宝妻', '双峦斗碧，寒玉雕秋壁。\n两道凝螺天半，横无限、青青色。\n拍案涛声急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18415, '沁园春', '刘氏', '我生不辰，逢此百罹，况乎乱离。\n奈恶因缘到，不夫不主，被擒捉去。\n为妾为妻。\n父母公姑，弟兄姐妹，流落不知东与西。\n心中事，把家书写下，分付伊谁。\n越人北向燕支。\n回首望、雁峰天一涯。\n奈翠鬟云软，笠儿怎带，柳腰春细，马性难骑。\n缺月疏桐，淡烟衰草，对此如何不泪垂。\n君知否，我生於何处，死亦魂归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18416, '沁园春', '无闻翁', '埋怨姐姐，衔恨婆婆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18417, '沁园春', '杨氏', '便归去，懒东涂西抹，学少年婆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18418, '满庭芳', '杨氏', '错应谁铸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18419, '更漏子', '张淑芳', '墨痕香，红蜡泪。\n点点愁人离思。\n桐叶落，蓼花残。\n雁声天外寒。\n五云岭，九溪坞。\n待到秋来更苦。\n风淅淅，水淙淙。\n不教蓬径通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18420, '满路花・促拍满路花', '张淑芳', '罗襟湿未乾，又是凄凉雪。\n欲睡难成寐、音书绝。\n窗前竹叶，凛凛狂风折。\n寒衣弱不胜，有甚遥肠，望到春来时节。\n孤灯独照，字字吟成血。\n仅梅花知苦、香来接。\n离愁万种，提起心头切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18421, '浣溪沙', '张淑芳', '散步山前春草香。\n朱阑绿水绕吟廊。\n花枝惊堕绣衣裳。\n或定或摇江上柳，为莺为凤月中篁。\n为谁掩抑锁芸窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18422, '齐天乐', '王易简', '宫烟晓散春如雾。\n参差护晴窗户。\n柳色初分，饧香未冷，正是清明百五。\n临流笑语。\n映十二阑干，翠红妒。\n短帽轻鞍，倦游曾遍断桥路。\n东风为谁媚妩。\n岁华顿感慨，双鬓何许。\n前度刘郎，三生杜牧，赢得征衫尘土。\n心期暗数。\n总寂寞当年，酒筹花谱。\n付与春愁，小楼今夜雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18423, '酹江月・念奴娇', '王易简', '暗帘吹雨，怪西风梧井，凄凉何早。\n一寸柔情千万缕，临镜霜痕惊老。\n雁影关山，蛩声院宇，做就新怀抱。\n湘皋遗佩，故人空寄瑶草。\n已是摇落堪悲，飘零多感，那更长安道。\n衰草寒芜吟未尽，无那平烟残照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18424, '庆宫春・高阳台', '王易简', '庭草春迟，汀苹香老，数声悄苍玉。\n年晚江空，天寒日暮，壮怀聊寄幽独。\n倦游多感，更西北、高楼送目。\n佳人不见，慷慨悲歌，夕阳乔木。\n紫霞洞云深，袅袅馀香，凤箫谁续。\n桃花赋在，竹枝词远，此恨年年相触。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18425, '天香', '王易简', '烟峤收痕，云沙拥沫，孤槎万里春聚。\n蜡杵冰尘，水研花片，带得海山风露。\n纤痕透晓，银镂小、初浮一缕。\n重剪纱窗暗烛，深垂绣帘微雨。\n馀馨恼人最苦。\n染罗衣、少年情绪。\n谩省佩珠曾解，蕙羞兰妒。\n好是芳钿翠妩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18426, '水龙吟', '王易简', '翠裳微护冰肌，夜深暗泣瑶台露。\n芳容淡泞，风神萧散，凌波晚步。\n西子残妆，环儿初起，未须匀注。\n看明素袜，相逢憔悴，当应被、西风误。\n十里云愁雪妒。\n抱凄凉、盼娇无语。\n当时姐妹，朱颜楼褪酒，红衣按舞。\n别浦重寻，旧盟唯有，一行鸥鹭。\n伴玉颜月晓，盈盈冷艳，洗人间暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18427, '摸鱼儿', '王易简', '怪鲛宫、水晶帘卷，冰痕初断香缕。\n澄波荡桨人初到，三十六陂烟雨。\n春又去。\n伴点点荷钱，隐约吴中路。\n相思日暮。\n恨洛浦娉婷，芳钿翠剪，奁影照凄楚。\n功名梦，消得西风一度。\n高人今在何许。\n鲈香菰冷斜阳里，多少天涯意绪。\n谁记取。\n但枯豉红盐，溜玉凝秋箸。\n尊前起舞。\n算唯有渊明，黄花岁晚，此兴共千古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18428, '齐天乐', '王易简', '翠云深锁齐姬恨，纤柯暗翻冰羽。\n锦瑟重调，绡衣乍著，聊饮人间风露。\n相逢甚处。\n记槐影初凉，柳阴新雨。\n听尽残声，为谁惊起又飞去。\n商量秋信最早。\n晚来吟未彻，却是凄楚。\n断韵还连，馀悲似咽，欲和愁边佳句。\n幽期谁语。\n怕寒叶凋零，蜕痕尘土。\n古木斜晖，向人怀抱苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18429, '天香', '冯应瑞', '枯石流痕，残沙拥沫，骊宫夜蛰惊起。\n海市收时，鲛人分处，误入众芳丛里。\n春霖未就，都化作、凄凉云气。\n惟有清寒一点，消磨小窗残醉。\n当年翠篝素被。\n拂馀薰、倦怀如水。\n谩惜舞红犹在，为谁重试。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18430, '天香', '唐艺孙', '螺甲磨星，犀株杵月，蕤英嫩压拖水。\n海蜃楼高，仙蛾钿小，缥缈结成心字。\n麝煤候暖，载一朵、轻云不起。\n银叶初生薄晕，金猊旋翻纤指。\n芳杯恼人渐醉。\n碾微馨、凤团闲试。\n满架舞红都换，懒收珠佩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18431, '齐天乐', '唐艺孙', '柳风微扇闲池阁，深林翠阴人静。\n渐理琴丝，谁调金奏，凄咽流空清韵。\n虹明雨润。\n正乍集庭柯，凭阑新听。\n午梦惊回，有人娇困酒初醒。\n西轩晚凉又嫩。\n向枝头占得，银露千顷。\n蜕翦花轻，羽翻纸薄，老去易惊秋信。\n残声送暝。\n恨秦树斜阳，暗催光景。\n淡月疏桐，半窗留鬓影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18432, '桂枝香', '唐艺孙', '收帆渡口。\n认远岸夜篝，松炬如昼。\n还见沙痕雪涨，水纹霜後。\n秦宫梦到无肠断，望明河、月斜疏柳。\n琐窗相对，茶边犹记，眼波频溜。\n渐嫩菊、初绿酒。\n叹风味尊前，潇洒如旧。\n几度金橙香雾，玉盘纤手。\n清愁小醉凄凉里，拼今生、容易消瘦。\n草心春浅，年年相忆，看灯时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18433, '天香', '吕同老', '冰片熔肌，水沈换骨，蜿蜒梦断瑶岛。\n翦碎腥云，杵匀枯沫，妙手制成翻巧。\n金篝候火，无似有、微薰初好。\n帘影垂风不动，屏深护春宜小。\n残梅舞红褪了。\n佩珠寒、满怀清峭。\n几度酒馀重省，旧愁多少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18434, '水龙吟', '吕同老', '素肌不污天真，晓来玉立瑶池里。\n亭亭翠盖，盈盈素靥，时妆净洗。\n太液波翻，霓裳舞罢，断魂流水。\n甚依然、旧日浓香淡粉，花不似，人憔悴。\n欲唤凌波仙子。\n泛扁舟、浩波千里。\n只愁回首，冰帘半掩，明乱坠。\n月影凄迷，露华零落，小阑谁倚。\n共芳盟，犹有双栖雪鹭，夜寒惊起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18435, '齐天乐', '吕同老', '绿荫初蔽林塘路，凄凄乍流清韵。\n倦咽高槐，惊嘶别柳，还忆当曾听。\n西窗梦醒。\n叹弦绝重调，珥空难整。\n绰约冰绡，夜深谁念露华冷。\n不知身世易老，一声声断续，频报秋信。\n坠叶山明，疏枝月小，惆怅齐姬薄幸。\n馀音未尽。\n早枯翼飞仙，暗嗟残景。\n见洗冰奁，怕翻双翠鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18436, '桂枝香', '吕同老', '松江岸侧。\n正乱叶坠红，残浪收碧。\n犹记灯寒暗聚，簖疏轻入。\n休嫌郭索尊前笑，且开颜、共倾芳液。\n翠橙丝雾，玉葱浣雪，嫩黄初擘。\n自那日、新诗换得。\n又几度相逢，落潮秋色。\n常是篱边早菊，慰渠岑寂。\n如今谩有江山兴，更谁怜、草泥踪迹。\n但将身世，浮沈醉乡，旧游休忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18437, '天香', '李居仁', '瀛峤浮烟，沧波挂月，潜虬睡起清晓。\n万里槎程，一番花信，付与露薇冰脑。\n纤云渐暖，凝翠席、氤氲不了。\n银叶重调火活。\n珠帘日垂风悄。\n螺屏酒醒梦好。\n绣罗帱、依旧痕少。\n几度试拈心字，暗惊芳抱。\n隐约仙舟路杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18438, '水龙吟', '李居仁', '蕊仙群拥宸游，素肌似怯波心冷。\n霜裳缟夜，冰壶凝露，红尘洗尽。\n弄玉轻盈，飞琼绰约，淡妆临镜。\n更多情、一片碧云不掩，笼娇面、回清影。\n菱唱数声乍听。\n载名娃、藕丝萦艇。\n雪鸥沙鹭，夜来同梦，晓风吹醒。\n酒量全消，粉痕微渍，色明香莹。\n问此花，盖贮瑶池，应未许、繁红并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18439, '水龙吟', '唐珏', '淡妆人更婵娟，晚奁净洗铅华腻。\n泠泠月色，萧萧风度，娇红敛避。\n太液池空，霓裳舞倦，不堪重记。\n叹冰魂犹在，翠舆难驻，玉簪为谁轻坠。\n别有凌空一叶，泛青寒、素波千里。\n珠房泪湿，明恨远，旧游梦里。\n羽扇生秋，琼楼不夜，尚遗仙意。\n奈香易散，绡衣半脱，露凉如水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18440, '摸鱼儿', '唐珏', '渐沧浪、冻痕消尽。\n琼丝初漾明镜。\n鲛人夜翦龙髯滑，织就水晶帘冷。\n凫叶净。\n最好似、嫩荷半卷浮倩影。\n玉流翠凝。\n早枯豉融香，红盐和雪，醉齿嚼清莹。\n功名梦，曾被秋风唤醒。\n故人应动高兴。\n悠然世味浑如水，千里旧怀谁省。\n空对景。\n奈回首、姑苏台畔愁波暝。\n烟寒夜静。\n但只有芳洲，苹花共老，何日泛归艇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18441, '齐天乐', '唐珏', '蜡痕初染仙茎露，新声又移凉影。\n佩玉流空，绡衣翦雾，几度槐昏柳暝。\n幽窗睡醒。\n奈欲断还连，不堪重听。\n怨结齐姬，故宫烟树翠阴冷。\n当时旧情在否，晚妆清镜里，犹记娇鬓。\n乱咽频惊，馀悲渐杳，摇曳风枝未定。\n秋期话尽。\n又抱叶凄凄，暮寒山静。\n付与孤蛩，苦吟清夜永。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18442, '桂枝香', '唐珏', '松江舍北。\n正水落晚汀，霜老枯荻。\n还见青匡似绣，绀螯如戟。\n西风有恨无肠断，恨东流、几番潮沙。\n夜灯争聚微光，挂影误投帘隙。\n更喜荐、新玉液。\n正半壳含黄，一醉秋色。\n纤手香橙风味，有人相忆。\n江湖岁晚听飞雪，但沙痕、空记行迹。\n至今茶鼎，时时犹认，眼波愁碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18443, '水龙吟', '赵汝钠', '露华洗尽凡妆，玉妃来侍瑶池宴。\n风裳水佩，冰肌雪艳，清凉不汗。\n解语情多，凌波步稳，酒容易散。\n想温泉浴罢，天然真态，浑疑是、宫妆浅。\n暗想凄愁别岸。\n粉痕消、香腮凝汗。\n雪空冰冷，此情唯许，鹭知鸥见。\n羽扇微摇，翠帷低拥，清凉庭院。\n待夜深，月上阑干，更邀取、娥伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18444, '贺新郎', '曹稆孙', '极目天如画。\n水花中、涌出莲宫，翠楹碧瓦。\n胜景中川金焦似，勒石□□□□。\n尚隔浦、风烟不跨。\n妖蜃自降真歇手，涨平沙、妙补乾坤罅。\n双寺合，万僧夏。\n东西塔影龙分挂。\n夜无云、点点一天，星斗相射。\n七十二滩声到海，括橹瓯帆上下。\n泣不为、琵琶声哑。\n故寝荒凉成一梦，问来鸥、去鹭无知者。\n烟树湿，怒涛打。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18445, '大江词・念奴娇', '林横舟', '一呈秀，近迎长佳节，拟书云物。\n隐隐虹桥天际下，光照梅仙丹壁。\n鹏路横飞，蟾宫直上，早脱麻衣雪。\n一时篇翰，并游俱是魁杰。\n长记怀燕良辰，华堂称庆，皓齿清歌发。\n自暖杯中须缓举，莫放金炉香灭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18446, '浣溪沙', '杨舜举', '残照西风一片愁。\n疏杨画出六桥秋。\n游人不上十三楼。\n有泪金仙还泣汉，无心玉马已朝周。\n平湖寂寂水空流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18447, '永遇乐', '危复之', '早叶初莺，晚风孤蝶，幽思何限。\n檐角萦云，阶痕积雨，一夜苔生遍。\n玉窗闲掩，瑶琴慵理，寂寞水沈烟断。\n悄无言，春归无觅处，卷帘见双飞燕。\n风亭泉石，烟林薇蕨，梦绕旧时曾见。\n江上闲鸥，心盟犹在，分得眠沙半。\n引觞浮月，飞谈卷雾，莫管愁深欢浅。\n起来倚阑干，拾得残红一片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18448, '金人捧露盘', '罗志仁', '湿苔青，妖血碧，坏垣红。\n怕精灵、来往相逢。\n荒烟瓦砾，宝钗零乱隐鸾龙。\n吴峰越，翠颦锁、苦为谁容。\n浮屠换、昭阳殿，僧磬改、景阳钟。\n兴亡事、泪老金铜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18449, '霓裳中序第一', '罗志仁', '来鸿又去燕。\n看罢江潮收画扇。\n湖曲雕阑倚倦。\n正船过西陵，快篙如箭。\n凌波不见。\n但陌花、遗曲凄怨。\n孤山路，晚蒲病柳，淡绿锁深院。\n谁恨。\n五云深处宫殿。\n记旧日、曾游翠辇。\n青红如写便面。\n下鹄池荒，放鹤人远。\n粉墙随岸转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18450, '风流子', '罗志仁', '歌咽翠眉低。\n湖船客、尊酒谩重携。\n正断续斋钟，高峰南北，飘零野褐，太乙东西。\n凄凉处，翠连松九里，僧马溅障泥。\n葛岭楼台，梦随烟散，吴山宫阙，恨与云霁。\n灵峰飞来久，飞不去，有落日断猿啼。\n无限风荷废港，露柳荒畦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18451, '扬州慢', '罗志仁', '危榭摧红，断砖埋玉，定王台下园林。\n听樯干燕子，诉别後惊心。\n尽江上、青峰好在，可怜曾是，野烧痕深。\n付潇湘渔笛，吹残今古销沈。\n妙奴不见，纵秦郎、谁更知音。\n正雁妾悲歌，雕奚醉舞，楚户停砧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18452, '虞美人', '罗志仁', '君王曾惜如花面。\n往事多恩怨。\n霓裳和泪换袈裟。\n又送鸾舆北去、听琵琶。\n当年未削青螺髻。\n知是归期未。\n天花丈室万缘空。\n结绮临春何处、泪痕中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18453, '木兰花慢', '罗志仁', '汉家糜粟诏，将不醉、饱生灵。\n便收拾银瓶，当垆人去，春歇旗亭。\n渊明权停种秫，遍人间，暂学屈原醒。\n天子宜呼李白，妇人却笑刘伶。\n提葫芦更有谁听。\n爱酒已无星。\n想难变春江，蒲桃酿绿，空想芳馨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18454, '菩萨蛮', '罗志仁', '晓莺催起。\n问当年秀色，为谁料理。\n怅别後、屏掩吴山，便楼燕月寒，鬓蝉云委。\n锦字无恁，付银烛、尽烧千纸。\n对寒泓静碧，又把去鸿，往恨都洗。\n桃花自贪结子。\n道东风有意，吹送流水。\n谩记得当日、心嫁卿卿，是日暮天寒，翠袖堪倚。\n扇月乘鸾，尽梦隔、婵娟千里。\n到嗔人、从今不信，画檐鹊喜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18455, '减字木兰花', '曾寅孙', '生绡蜀茧。\n笔底墨云飞一片。\n点点秋腴。\n收得骊龙颌下珠。\n兴来一扫。\n惜处有时悭似宝。\n露叶烟条。\n几度西风吹不凋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18456, '甘州・八声甘州', '沈钦', '有吴僧、醉倒墨池边，西风暗吹芳。\n对苍髯冷挂，龙珠万颗，晴映经窗。\n却似仙人黄鹤，笛里换时光。\n静处观生意，竹老梅荒。\n犹说当年分种，是枯槎远驾，万里途长。\n信留真何许，烨烨楮毫香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18457, '甘州・八声甘州', '刘沆', '爱累累、万颗贯骊珠，特地写幽芳。\n想黄昏云淡，夜深人静，清影横窗。\n冷澹一枝两叶，笔下老秋光。\n参透圆明相，日观开荒。\n最是柔髭修梗，映风姿雾质，雅趣悠长。\n更淋漓草圣，把玩墨犹香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18458, '卜算子', '止禅师', '书是玉关来，泪向松江堕。\n梅自飘香柳自青，嘹唳征鸿过。\n沙漠暗尘飞，嵩狱愁云锁。\n淮上千营夜枕戈，此恨凭谁破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18459, '贺新郎', '蒋捷', '渺渺啼鸦了。\n亘鱼天、寒生峭屿，五湖秋晓。\n竹几一灯人做梦，嘶马谁行古道。\n起搔首、窥星多少。\n月有微黄篱无影，挂牵牛、数朵青花小。\n秋太淡，添红枣。\n愁痕倚赖西风扫。\n被西风、翻催鬓，与秋俱老。\n旧院隔霜帘不卷，金粉屏边醉倒。\n计无此、中年怀抱。\n万里江南吹箫恨，恨参差、白雁横天杪。\n烟未敛，楚山杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18460, '贺新郎', '蒋捷', '雁屿晴岚薄。\n倚层屏、千树高低，粉纤红弱。\n云隘东风藏不尽，吹艳生香万壑。\n又散入、汀蘅洲药。\n扰扰匆匆尘土面，看歌莺、舞燕逢春乐。\n人共物，知谁错。\n宝钗楼上围帘幕。\n小婵娟、双调弹筝，半霄鸾鹤。\n我辈中人无此分，琴思诗情当却。\n也胜似、愁横眉角。\n芳景三分才过二，便绿阴、门巷杨花落。\n沽斗酒，且同酌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18461, '贺新郎', '蒋捷', '浪涌孤亭起。\n是当年、蓬莱顶上，海风飘坠。\n帝遣江神长守护，八柱蛟龙缠尾。\n斗吐出、寒烟寒雨。\n昨夜鲸翻坤轴动，卷雕、掷向虚空里。\n但留得，绛虹住。\n五湖有客扁舟舣。\n怕群仙、重游到此，翠旌难驻。\n手拍阑干呼白鹭，为我殷勤寄语。\n奈鹭也、惊飞沙渚。\n星月一天云万壑，览茫茫、宇宙知何处。\n鼓双楫，浩歌去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18462, '贺新郎', '蒋捷', '梦冷黄金屋。\n叹秦筝、斜鸿阵里，素弦尘扑。\n化作娇莺飞归去，犹认纱窗旧绿。\n正过雨、荆桃如菽。\n此恨难平君知否，似琼台、涌起弹棋局。\n消瘦影，嫌明烛。\n鸳楼碎泻东西玉。\n问芳、何时再展，翠钗难卜。\n待把宫眉横云样，描上生绡画幅。\n怕不是、新来妆束。\n彩扇红牙今都在，恨无人、解听开元曲。\n空掩袖，倚寒竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18463, '贺新郎', '蒋捷', '深阁帘垂绣。\n记家人、软语灯边，笑涡红透。\n万叠城头哀怨角，吹落霜花满袖。\n影厮伴、东奔西走。\n望断乡关知何处，羡寒鸦、到著黄昏後。\n一点点，归杨柳。\n相看只有山如旧。\n叹浮云、本是无心，也成苍狗。\n明日枯荷包冷饭，又过前头小阜。\n趁未发、且尝村酒。\n醉探枵囊毛锥在，问邻翁、要写牛经否。\n翁不应，但摇手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18464, '沁园春', '蒋捷', '老子平生，辛勤几年，始有此庐。\n也学那陶潜，篱栽些菊，依他杜甫，园种些蔬。\n除了雕梁，肯容紫燕，谁管门前长者车。\n怪近日，把一庭明月，却借伊渠。\n鬓边白发纷如。\n又何苦招宾约客欤。\n但夏榻宵眠，面风枕，冬檐昼短，背日观书。\n若有人寻，只教僮道，这屋主人今自居。\n休羡彼，有摇金宝辔，织翠华裾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18465, '沁园春', '蒋捷', '结算平生，风流债负，请一笔句。\n盖攻性之兵，花围锦阵，毒身之鸩，笑齿歌喉。\n岂识吾儒，道中乐地，绝胜珠帘十里楼。\n迷因底，叹晴乾不去，待雨淋头。\n休休。\n著甚来由。\n硬铁汉从来气食牛。\n但只有千篇，好诗好曲，都无半点，闲闷闲愁。\n自古娇波，溺人多矣，试问还能溺我不。\n高抬眼，看牵丝傀儡，谁弄谁收。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18466, '女冠子', '蒋捷', '蕙花香也。\n雪晴池馆如画。\n春风飞到，宝钗楼上，一片笙箫，琉璃光射。\n而今灯漫挂。\n不是暗尘明月，那时元夜。\n况年来、心懒意怯，羞与蛾儿争要。\n江城人悄初更打。\n问繁华谁解，再向天公借。\n剔残红。\n但梦里隐隐，钿车罗帕。\n吴笺银粉砑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18467, '女冠子', '蒋捷', '电旗飞舞。\n双双还又争渡。\n湘漓云外，独醒何在，翠药红蘅，芳菲如故。\n深衷全未语。\n不似素车白马，卷潮起怒。\n但悄然、千载旧迹，时有闲人吊古。\n生平惯受椒兰苦。\n甚魄沈寒浪，更被馋蛟妒。\n结琼纫璐。\n料贝阙隐隐，骑鲸烟雾。\n楚妃花倚暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18468, '大圣乐', '蒋捷', '笙月凉边，翠翘双舞，寿仙曲破。\n更听得艳拍流星，慢唱寿词初了，群唱莲歌。\n主翁楼上披鹤氅，展一笑、微微红透涡。\n襟怀好，纵炎官驻伞，长是春和。\n千年鼻祖事业，记曾趁雷声飞快梭。\n但也曾三径，抚松采菊，随分吟哦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18469, '解连环', '蒋捷', '妒花风恶。\n吹青阴涨却，乱红池阁。\n驻媚景、别有仙葩，遍琼小台，翠油疏箔。\n旧日天香，记曾绕、玉奴弦索。\n自长安路远，腻紫肥黄，但谱东洛。\n天津霁红如昨。\n听鹃声度月，春又寥寞。\n散艳魄、飞入江南，转湖渺山茫，梦境难托。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18470, '永遇乐', '蒋捷', '清逼池亭，润侵山阁，雪气凝聚。\n未有蝉前，已无蝶後，花事随逝水。\n西园支径，今朝重到，半碍醉筇吟袂。\n除非是、莺身瘦小，暗中引雏穿去。\n梅檐溜滴，风来吹断，放得斜阳一缕。\n玉子敲枰，香绡落翦，声度深几许。\n层层离恨，凄迷如此，点破谩烦轻絮。\n应难认、争春旧馆，倚红杏处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18471, '花心动', '蒋捷', '春入南塘，粉梅花、盈盈倚风微笑。\n虹晕贯帘，星球攒巷，遍地宝光交照。\n涌金门外楼台影，参差浸、西湖波渺。\n暮天远，芙蓉万朵，是谁移到。\n鬓双仙未老。\n陪玳席佳宾，暖香云绕。\n翠叩冰，银管嘘霜，瑞露满锺频。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18472, '金盏子', '蒋捷', '练月萦窗，梦乍醒、黄花翠竹庭馆。\n心字夜香消，人孤另、双鹣被池羞看。\n拟待告诉天公，减秋声一半。\n无情雁。\n正用恁时飞来，叫云寻伴。\n犹记杏栊暖。\n银烛下、纤影卸佩款。\n春涡晕，红豆小，莺衣嫩，珠痕淡印芳汗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18473, '喜迁莺', '蒋捷', '游丝纤弱。\n谩著意绊春，春难凭托。\n水暖成纹，云晴生影，双燕又窥帘幕。\n露添牡丹新艳，风摆秋千闲索。\n对此景，动高歌一曲，何妨行乐。\n行乐。\n春正好，无奈绿窗，孤负敲棋约。\n锦屋调笙，银瓶索酒，争奈也曾迷著。\n自从发凋心倦，常倚钩阑斜角。\n翠深处，看悠悠几点，杨花飞落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18474, '昼锦堂', '蒋捷', '染柳烟消，敲菰雨断，历历犹寄斜阳。\n掩冉玉妃芳袂，拥出灵场。\n倩他鸳鸯来寄语，驻君舴艋亦何妨。\n渔榔静，独奏棹歌，邀妃试酌清觞。\n湖上云渐暝，秋浩荡，鲜风支尽蝉粮。\n赠我非环非佩，万斛生香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18475, '水龙吟', '蒋捷', '醉兮琼瀣浮觞些。\n招兮遣巫阳些。\n君毋去此，飓风将起，天微黄些。\n野马尘埃，污君楚楚，白霓裳些。\n驾空兮云浪，茫洋东下，流君往、他方些。\n月满兮西厢些。\n叫云矣、笛凄凉些。\n归来为我，重倚蛟背，寒鳞苍些。\n俯视春红，浩然一笑，吐山香些。\n翠禽兮弄晓，招君未至，我心伤些。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18476, '瑞鹤仙', '蒋捷', '缟霜霏霁雪。\n渐翠没凉痕，猩浮寒血。\n山窗梦凄切。\n短吟筇犹倚，莺边新樾。\n花魂未歇。\n似追惜、芳消艳灭。\n挽西风、再入柔柯，误染绀云成缬。\n休说。\n深题锦翰，浅泛琼漪，暗春曾泄。\n情条万结。\n依然是，未愁绝。\n最怜他，南苑空阶堆遍，人隔仙蓬怨别。\n锁芙蓉、小殿秋深，碎虫诉月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18477, '瑞鹤仙', '蒋捷', '绀烟迷雁迹。\n渐断鼓零钟，街喧初息。\n风檠背寒壁。\n放冰蜍飞到，丝丝窗隙。\n琼瑰暗泣。\n念乡关、霜芜似织。\n漫将身、化鹤归来，忘却旧游端的。\n欢极。\n蓬壶蕖浸，花院梨溶，醉连春夕。\n柯云罢弈。\n樱桃在，梦难觅。\n劝清光，乍可幽窗相伴，休照红楼夜笛。\n怕人间、换谱伊凉，素娥未识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18478, '瑞鹤仙', '蒋捷', '玉霜生穗也。\n渺洲云翠痕，雁绳低也。\n层帘四垂也。\n锦堂寒早近，开炉时也。\n香风递也。\n是东篱、花深处也。\n料此花、伴我仙翁，未肯放秋归也。\n嬉也。\n缯波稳舫，镜月危楼，琼也。\n笼莺睡也。\n红妆旋、舞衣也。\n待纱灯客散，纱窗日上，便是严凝序也。\n换青毡、小帐围春，又还醉也。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18479, '瑞鹤仙', '蒋捷', '素肌元是雪。\n向雪里带香，更添奇绝。\n梅花太孤洁。\n问梨花何似，风标难识。\n长洲漾楫。\n料鸳边、娇容乍折。\n对珠栊、自翦凉衣，爱把淡罗轻叠。\n清彻。\n螺心翠靥，龙吻琼涎，总成虚设。\n微微醉缬。\n窗灯晕，弄明灭。\n算银台高处，芳菲仙佩，步遍纤云万叶。\n觉来时、人在红帱，半廊界月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18480, '木兰花慢', '蒋捷', '傍池阑倚遍，问山影、是谁偷。\n但鹭敛琼丝，鸳藏绣羽，碍浴妨浮。\n寒流。\n暗冲片响，似犀椎、带月静敲秋。\n因念凉荷院宇，纷丸曾泛金瓯。\n妆楼。\n晓涩翠罂油。\n倦鬓理还休。\n更有何意绪，怜他半夜，瓶破梅愁。\n红。\n泪乾万点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18481, '木兰花慢', '蒋捷', '渺琉璃万顷，冷光射、夕阳洲。\n见败柳漂枝，残芦泛叶，欲去仍留。\n罗帱。\n少年梦里，正窥帘、月浸素肌柔。\n谁念衰翁自老，断髭冻得成虬。\n凝眸。\n一望绝飞鸥。\n宇宙正清幽。\n漫细敲紫砚，轻呵翠管，吟思难抽。\n飕飕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18482, '珍珠帘・真珠帘', '蒋捷', '书楼四面筠帘卷。\n微薰起，翠弄悬签丝软。\n楼上读书仙，对宝狻霏转。\n绣馆钗行云度影，滟寿觥、盈盈争劝。\n争劝。\n奈芸边事切，花中情浅。\n金奏未响昏蜩，早传言放却，舞衫歌扇。\n柳雨一窝凉，再展开湘卷。\n万颗蕖心琼珠辊，细滴与、银朱小砚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18483, '高阳台', '蒋捷', '霞铄帘珠，云蒸篆玉，环楼婉婉飞铃。\n天上王郎，飚轮此地曾停。\n秋香不断台隍远，溢万丛、锦艳鲜明。\n事成尘，鸾凤箫中，空度歌声。\n翁一点清寒髓，惯餐英菊屿，饮露兰汀。\n透屋高红，新营小样花城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18484, '高阳台', '蒋捷', '燕卷情丝，蜂黏落絮，天教绾住闲愁。\n闲里清明，匆匆粉涩红羞。\n灯摇缥晕茸窗冷，语未阑、蛾影分收。\n好伤情，春也难留，人也难留。\n芳尘满目悠悠。\n问萦云佩响，还绕谁楼。\n别酒才斟，从前心事都休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18485, '高阳台', '蒋捷', '桥尾星沈，街心尘敛，天公还把春饶。\n桂月黄昏，金丝柳换星摇。\n相逢小曲方嫌冷，便暖薰、珠络香飘。\n却怜他、隔岁芳期，枉费囊绡。\n人情终似蛾儿舞，到翻宿粉，怎比初描。\n认得游踪，花骢不住嘶骄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18486, '春夏两相期', '蒋捷', '听深深、谢家庭馆。\n东风对语双燕。\n似说朝来，天上婺星光现。\n金裁花诰紫泥香，绣裹藤舆红茵软。\n散蜡宫辉，行鳞厨品，至今人羡。\n西湖万柳如线。\n料月仙当此，小停飚辇。\n付与长年，教见海心波浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18487, '念奴娇', '蒋捷', '稼翁居士，有几多抱负，几多声价。\n玉立绣衣霄汉表，曾览八州风化。\n进退行藏，此时正要，一著高天下。\n黄埃扑面，不成也控羸马。\n人道云出无心，才离山後，岂是无心者。\n自古达官酣富贵，住住遭人描画。\n只有青门，种瓜闲客，千载传佳话。\n稼翁一笑，吾今亦爱吾稼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18488, '绛都春', '蒋捷', '春愁怎画。\n正莺背带雪，酴花谢。\n细雨院深，淡月廊斜重帘挂。\n归时记约烧灯夜。\n早拆尽、秋千红架。\n纵然归近，风光又是，翠阴初夏。\n娅姹。\n青泫白，恨玉佩罢舞，芳尘凝榭。\n几拟情人，付与兰香秋罗帕。\n知他堕策斜拢马。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18489, '声声慢', '蒋捷', '黄花深巷，红叶低窗，凄凉一片秋声。\n豆雨声来，中间夹带风声。\n疏疏二十五点，丽谯门、不锁更声。\n故人远，问谁摇玉佩，檐底铃声。\n彩角声吹月堕，渐连营马动，四起笳声。\n闪烁邻灯，灯前尚有砧声。\n知他诉愁到晓，碎哝哝、多少蛩声。\n诉未了，把一半、分与雁声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18490, '尾犯', '蒋捷', '夜倚读书床，敲碎唾壶，灯晕明灭。\n多事西风，把斋铃频掣。\n人共语、温温芋火，雁孤飞、萧萧桧雪。\n遍阑干外，万顷鱼天，未了予愁绝。\n鸡边长剑舞，念不到、此样豪杰。\n瘦骨棱棱，但凄其衾铁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18491, '满江红', '蒋捷', '一掬乡心，付杳杳、露莎烟苇。\n来相伴、凄然客影，谢他穷鬼。\n新绿旧红春又老，少玄老白人生几。\n况无情、世故荡摩中，凋英伟。\n词场笔，行群蚁。\n战场胄，藏群虮。\n问何如清昼，倚藤凭。\n流水青山屋上下，束书壶酒船头尾。\n任垂涎、斗大印黄金，狂周。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18492, '满江红', '蒋捷', '秋本无愁，奈客里、秋偏岑寂。\n身老大、敲秦缶，懒移陶甓。\n万误曾因疏处起，一闲且向贫中觅。\n笑新来、多事是征鸿，声嘹呖。\n双户掩，孤灯剔。\n书束架，琴悬壁。\n笑人间无此，小窗幽阒。\n浪远微听葭叶响，雨残细数梧梢滴。\n正依稀、梦到故人家，谁横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18493, '探芳信', '蒋捷', '翠吟悄。\n似有人黄裳，孤伫埃表。\n渐老侵芳岁，识君恨不早。\n料应陶令吟魂在，凝此秋香妙。\n傲霜姿，尚想前身，倚窗馀傲。\n回首醉年少。\n控骏马蓉边，红茸帽。\n淡泊东篱，有谁肯、梦飞到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18494, '梅花引', '蒋捷', '白鸥问我泊孤舟。\n是身留。\n是心留。\n心若留时、何事锁眉头。\n风拍小帘灯晕舞，对闲影，冷清清，忆旧游。\n旧游旧游今在不。\n花外楼。\n柳下舟。\n梦也梦也，梦不到、寒水空流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18495, '洞仙歌', '蒋捷', '世间何处，最难忘杯酒。\n惟是停云想亲友。\n此时无一盏，千种离愁，西风外，长伴枯荷衰柳。\n去年深夜语，倾倒书□，窗烛心悬小红豆。\n记得到门时，雨正萧萧，嗟今雨、此情非旧。\n待与子、相期采黄花，又未卜重阳，果能晴否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18496, '洞仙歌', '蒋捷', '枝枝叶叶，受东风调弄。\n便是鸾穿也微动。\n自鹅黄千缕，数到飞绵，闲无事，谁管将春迎送。\n轻柔心性在，教得游人，酒舞花吟姿狂纵。\n更谁家鸾镜里，贪学纤蛾，移来傍、妆楼新种。\n总不道、江头锁清愁，正雨渺烟茫，翠阴如梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18497, '最高楼', '蒋捷', '新春景，明媚在何时。\n宜早不宜迟。\n软尘巷陌青油，重帘深院画罗衣。\n要些儿，晴日照，暖风吹。\n一片片、雪儿休要下。\n一点点、雨儿休要洒。\n才恁地，越愆期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18498, '祝英台・祝英台近', '蒋捷', '柳边楼，花下馆。\n低卷绣帘半。\n帘外天丝，扰扰似情乱。\n知他蛾绿纤眉，鹅黄小袖。\n在何处、闲游闲玩。\n最堪叹。\n筝面一寸尘深，玉柱网斜雁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18499, '风入松', '蒋捷', '东风方到旧桃枝。\n仙梦已云迷。\n画阑红子处，依然是、春昼帘垂。\n恨杀河东狮子，惊回海底鸥儿。\n寻芳小步莫嫌迟。\n此去却慵移。\n断肠不在分襟後，元来在、襟未分时。\n柳岸犹携素手，兰房早掩朱扉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18500, '解佩令', '蒋捷', '春晴也好。\n春阴也好。\n著些儿、春雨越好。\n春雨如丝，绣出花枝红袅。\n怎禁他、孟婆合皂。\n梅花风小。\n杏花风小。\n海棠风、蓦地寒峭。\n岁岁春光，被二十四风吹老。\n楝花风、尔且慢到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18501, '一翦梅', '蒋捷', '小巧楼台眼界宽。\n朝卷帘看。\n暮卷帘看。\n故乡一望一心酸。\n云又迷漫。\n水又迷漫。\n天不教人客梦安。\n昨夜春寒。\n今夜春寒。\n梨花月底两眉攒。\n敲遍阑干。\n拍遍阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18502, '一翦梅', '蒋捷', '一片春愁待酒浇。\n江上舟摇。\n楼上帘招。\n秋娘度与泰娘娇。\n风又飘飘。\n雨又萧萧。\n何日归家洗客袍。\n银字笙调。\n心字香烧。\n流光容易把人抛。\n红了樱桃。\n绿了芭蕉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18503, '糖多令・唐多令', '蒋捷', '秋碧泻晴湾。\n楼台云影闲。\n记仙家、元在蓬山。\n飞到雁峰尘更少，三万顷、玉无边。\n金盏倒垂莲。\n歌摇香雾鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18504, '柳梢青', '蒋捷', '小饮微吟，残灯断雨，静户幽窗。\n几度花开，几番花谢，又到黄昏。\n潘娘不是潘郎。\n料应也、霜黏鬓旁。\n鹦鹉阑空，鸳鸯壶破，烟渺云茫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18505, '阮郎归', '蒋捷', '雪飞灯背雁声低。\n寒生红被池。\n小屏风畔立多时。\n闲看番马儿。\n新泪，旧题诗。\n一般罗带垂。\n琼箫夜夜挟愁吹。\n梅花知不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18506, '金蕉叶', '蒋捷', '云褰翠幕。\n满天星碎珠迸索。\n孤蟾阑外，照我看看过转角。\n酒醒寒砧正作。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18507, '忆秦娥', '蒋捷', '山无限。\n登山试望吴宫殿。\n吴宫殿。\n是藏深坞，是临清浅。\n（缺词文）（缺词文）（缺词文）（缺词文）（缺词文）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18508, '谒金门', '蒋捷', '（缺词文）（缺词文）（缺词文）（缺词文）（缺词文）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18509, '菩萨蛮', '蒋捷', '（缺词文）（缺词文）（缺词文）（缺词文）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18510, '卜算子', '蒋捷', '（缺词文）（缺词文）（缺词文）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18511, '霜天晓角', '蒋捷', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18512, '点绛唇', '蒋捷', '（缺词文）');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18513, '昭君怨', '蒋捷', '担子挑春虽小。\n白白红红都好。\n卖过巷东家。\n巷西家。\n帘外一声声叫。\n帘里鸦鬟入报。\n问道买梅花。\n买梅花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18514, '如梦令', '蒋捷', '夜月溪篁鸾影。\n晓露岩花鹤顶。\n半世踏红尘，到底输他村景。\n村景。\n村景。\n樵斧耕蓑渔艇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18515, '小重山', '蒋捷', '晴浦溶溶明断霞。\n楼台摇影处，是谁家。\n银红裙裥皱宫纱。\n风前坐，闲斗郁金芽。\n人散树啼鸦。\n粉团黏不住，旧繁华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18516, '小重山', '蒋捷', '曾伴芳卿锵佩环。\n西风吹梦断，堕人寰。\n假饶无分入雕阑。\n窥妆镜，也合小溪湾。\n此地有谁怜。\n斜阳牛卧处，牧童攀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18517, '白苎', '蒋捷', '正春晴，又春冷，云低欲落。\n琼苞未剖，早是东风作恶。\n旋安排、一双银蒜镇罗幕。\n幽壑。\n水生漪，皱嫩绿、潜鳞初跃。\n门巷，桃树红才约略。\n知甚时，霁华烘破青青萼。\n忆昨。\n□□□□，引蝶花边，近来重见，身学垂杨瘦削。\n问小翠眉山，为谁攒却。\n斜阳院宇，任蛛丝遍，玉筝弦索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18518, '蝶恋花', '蒋捷', '我爱荷花花最软。\n锦拶云挨，朵朵娇如颤。\n一阵微风来自远。\n红低欲蘸凉波浅。\n莫是羊家张静婉。\n抱月飘烟，舞得腰肢倦。\n偷把翠罗香被展。\n无眠却又频翻转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18519, '虞美人', '蒋捷', '丝丝杨柳丝丝雨。\n春在溟处。\n楼儿忒小不藏愁。\n几度和云飞去、觅归舟。\n天怜客子乡关远。\n借与花消遣。\n海棠红近绿阑干。\n才卷朱帘却又、晚风寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18520, '虞美人', '蒋捷', '少年听雨歌楼上。\n红烛昏罗帐。\n壮年听雨客舟中。\n江阔云低、断雁叫西风。\n而今听雨僧庐下。\n鬓已星星也。\n悲欢离合总无情。\n一任阶前、点滴到天明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18521, '南乡子', '蒋捷', '泊雁小汀洲。\n冷淡湔裙水漫秋。\n裙上唾花无觅处，重游。\n隔柳惟存月半钩。\n准拟架层楼。\n望得伊家见始休。\n还怕粉云天末起，悠悠。\n化作相思一片愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18522, '南乡子', '蒋捷', '翠夜游车。\n不到山边与水涯。\n随分纸灯三四盏，邻家。\n便做元宵好景夸。\n谁解倚梅花。\n思想灯球坠绛纱。\n旧说梦华犹未了，堪嗟。\n才百馀年又梦华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18523, '步蟾宫', '蒋捷', '绿华翦碎娇云瘦。\n剩妆点、菊前蓉後。\n娟娟月也染成香，何况、纤罗襟袖。\n秋窗一夜西风骤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18524, '步蟾宫', '蒋捷', '玉窗掣锁香云涨。\n唤绿袖、低敲方响。\n流苏拂处字微讹，但斜倚、红梅一饷。\n月在帘衣上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18525, '玉楼春', '蒋捷', '秦人占得桃源地。\n说道花深堪避世。\n桃花湾内岂无花，吕政马来拦不住。\n明朝与子穿花去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18526, '恋绣衾', '蒋捷', '茜金小袖花下行。\n过桥亭、倚树听莺。\n被柳线、低萦鬓，绀云垂、钗凤半横。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18527, '浪淘沙', '蒋捷', '人爱晓妆鲜。\n我爱妆残。\n翠钗扶住欲鬟。\n印了夜香无事也，月上凉天。\n新谱学筝难。\n愁涌蛾弯。\n一床衾浪未红翻。\n听得人催佯不睬，去洗珠钿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18528, '浪淘沙', '蒋捷', '明露浴疏桐。\n秋满帘栊。\n掩琴无语意忡忡。\n掐破东窗窥皓月，早上芙蓉。\n前事渺茫中。\n烟水孤鸿。\n一尊重九又成空。\n不解吹愁吹帽落，恨杀西风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18529, '燕归梁', '蒋捷', '我梦唐宫春昼迟。\n正舞到、曳裾时。\n翠云队仗绛霞衣。\n慢腾腾、手双垂。\n忽然急鼓催将起，似彩凤、乱惊飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18530, '步蟾宫', '蒋捷', '去年云掩冰轮皎。\n喜今岁、微阴俱扫。\n乾坤一片玉琉璃，怎算得、清光多少。\n无歌无酒痴顽老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18531, '南乡子', '蒋捷', '冷淡是秋花。\n更比秋花冷淡些。\n到处芙蓉供醉赏，从他。\n自有幽人处士夸。\n寂寞两三葩。\n昼日无风也带斜。\n一片西窗残照里，谁家。\n卷却湘裙薄薄纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18532, '行香子', '蒋捷', '红了樱桃。\n绿了芭蕉。\n送春归、客尚蓬飘。\n昨宵谷水，今夜兰皋。\n奈云溶溶，风淡淡，雨潇潇。\n银字笙调。\n心字香烧。\n料芳、乍整还凋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18533, '粉蝶儿', '蒋捷', '啼声中，春光化成春梦。\n问东君、仗谁诗送。\n燕怜晴，莺爱暖，一窗芳哄。\n奈匆匆、催他柳绵狂纵。\n轻罗扇小，桐花又飞么凤。\n记寒吟、沁梅霜冻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18534, '翠羽吟', '蒋捷', '绀露浓。\n映素空。\n楼观峭玲珑。\n粉冻霁英，冷光摇荡古青松。\n半规黄昏淡月，梅气山影溟。\n有丽人、步依修竹，萧然态若游龙。\n绡袂微皱水溶溶。\n仙茎清瀣，净洗斜红。\n劝我浮香桂酒，环佩暗解，声飞芳霭中。\n弄春弱柳垂丝，慢按翠舞娇童。\n醉不知何处，惊翦翦、凄紧霜风。\n梦醒寻痕访踪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18535, '贺新郎', '蒋捷', '甚矣君狂矣。\n想胸中、些儿磊，酒浇不去。\n据我看来何所似，一似韩家五鬼。\n又一似、杨家风子。\n怪鸟啾啾鸣未了，被天公、捉住樊笼里。\n这一错，铁难铸。\n濯溪雨涨荆溪水。\n送君归、斩蛟桥外，水光清处。\n世上恨无楼百尺，装着许多俊气。\n做弄得、栖栖如此。\n临别赠言朋友事，有殷勤、六字君听取。\n节饮食，慎言语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18536, '贺新郎', '蒋捷', '妾有琵琶谱。\n抱金槽、慢拈轻抛，柳梢莺妒。\n羽调六么弹遍了，花底灵犀暗度。\n奈敲断、玉钗纤股。\n低画屏深朱户掩，卷西风、满地吹尘土。\n芳事往，蝶空诉。\n天天把妾芳心误。\n小楼东、隐约谁家，凤箫鼍鼓。\n泪点染衫双袖翠，修竹凄其又暮。\n背灯影、萧条情互。\n捐佩洲前裙步步，渺无边、一片相思苦。\n春去也，乱红舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18537, '贺新郎', '蒋捷', '绿堕云垂领。\n背琵琶、盈盈袖手，粉闲红靓。\n依约春游归来倦，又似春眠未醒。\n滟寒、低迷蓉影。\n莺带松声飞过也，柳窗深、尚记停针听。\n魂浩荡，孤芳景。\n金钗断股瓶沈井。\n问苏城、香销卷子，倩谁题咏。\n灯晕青红残醉在，小院屏昏帐暝。\n误怪、眉心慵整。\n人道真真招得下，任千呼万唤无言应。\n空对此，泪花冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18538, '摸鱼子', '蒋捷', '吟鞭、雁峰高处。\n曾游长寿仙府。\n年年长见瑶簪会，霞杪盖芝轻度。\n开绣户。\n笑万朵香红，剩染秋光素。\n清箫丽鼓。\n任滟玉杯深，鸾酣凤醉，犹未洞天暮。\n尘缘误。\n迷却桃园旧步。\n飞琼芳梦同赋。\n朝来闻道仙童宴，翘首翠房玄圃。\n云又雾。\n身恍到微茫，认得胎禽舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18539, '沁园春', '蒋捷', '昔裴晋公，生甲辰岁，秉唐相钧。\n向东都治第，才娱老眼，北门建节，又绊闲身。\n燠馆花浓，凉台月淡，不记弓刀千骑尘。\n谁堪羡，羡南塘居士，做散仙人。\n南塘水向晴云。\n三百树凤洲杨柳春。\n有绿衣奏曲，金斜小雁，彩衣劝酒，玉跪双麟。\n前後同年，逸劳异趣，中立翻成雌甲辰。\n斯言也，是梅花说与，竹里山民。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18540, '喜迁莺', '蒋捷', '风涛如此，被闲鸥诮我，君行良苦。\n槲叶深湾，芦窠窄港，小憩倦篙慵橹。\n壮年夜吹笛去，惊得鱼龙嗥舞。\n怅今老，但蓬窗紧掩，荒凉愁愫。\n别浦。\n云断处。\n低雁一绳，拦断家山路。\n佩玉无诗，飞霞乏序，满席快飚谁付。\n醉中几番重九，今度芳尊孤负。\n便晴否。\n怕明朝蝶冷，黄花秋圃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18541, '喜迁莺', '蒋捷', '晴天廖廓。\n被孤云画出，离愁消索。\n玉局弹棋，金钗翦烛，芳思可胜摇落。\n镜妆为慵迟晚，笙曲缘愁差错。\n倒纤指，□从头细数，年时同乐。\n寂寞。\n花院悄，昨夜醉眠，梦也难凭托。\n车角生时，马蹄方後，才始断伊漂泊。\n闷无半分消遣，春又一番担阁。\n倚阑久，奈东风忒冷，红绡单薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18542, '齐天乐', '蒋捷', '银蟾飞到觚棱外。\n娟娟下窥龙尾。\n电紫鞘轻，云红曲，雕玉舆穿灯底。\n峰缯岫绮。\n沸一簇人声，道随竿媚。\n侍女迎銮，燕娇莺姹炫珠翠。\n华胥仙梦未了，被天公洞，吹换尘世。\n淡柳湖山，浓花巷陌，惟说钱塘而已。\n回头汴水。\n望当日宸游，万□□□。\n但有寒芜，夜深青磷起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18543, '念奴娇', '蒋捷', '夜深清梦，到丛花深处，满襟冰雪。\n人在琼云方响乐，杳杳冲牙清绝。\n翠翔龙，金枞跃凤，不是蕤宾铁。\n凄锵仙调，风敲珠树新折。\n中有五色光开，参差帔影，对舞山香彻。\n雾阁云窗归去也，笑拥灵君旌节。\n六曲阑干，一声鹦鹉，霍地空花灭。\n梦回孤馆，秋笳霜外呜咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18544, '应天长', '蒋捷', '柳湖载酒，梅墅赊棋，东风袖里寒色。\n转眼翠笼池阁，含樱荐莺食。\n匆匆过、春是客。\n弄细雨、昼阴生寂。\n似琼花、谪下红裳，再返仙籍。\n无限倚阑愁，梦断云箫，鹊叫度青壁。\n漫有戏龙盘□，盈盈住花宅。\n骄骢马、嘶巷陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18545, '贺新郎', '蒋捷', '绝代幽人独。\n掩芳姿、深居何处，乱云深谷。\n自说关中良家子，零落聊依草木。\n世丧败、谁收骨肉。\n轻薄儿郎为夫婿，爱新人、窕窈颜如玉。\n千万事，风前烛。\n鸳鸯一旦成孤宿。\n最堪怜、新人欢笑，旧人哀哭。\n侍婢卖珠回来後，相与牵萝补屋。\n漫采得、柏枝盈掬。\n日暮山中天寒也，翠绡衣、薄甚肌生粟。\n空敛袖，倚修竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18546, '玉漏迟', '蒋捷', '客窗空翠杪。\n前生饮惯，长生琼。\n回首红尘，换了□花草。\n隔水神仙洞府，但只有、飞霞能到。\n谁信道。\n西风送我，还陪清啸。\n缥渺。\n柳侧双楼，正绣幕围春，露深烟悄。\n鱼尾停时，雪上云犹少。\n醉傍芙蓉自语，愿来此、年年簪帽。\n青屿小。\n鹤立淡烟秋晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18547, '台城路・齐天乐', '张炎', '十年前事翻疑梦，重逢可怜俱老。\n水国春空，山城岁晚，无语相看一笑。\n荷衣换了。\n任京洛尘沙，冷凝风帽。\n见说吟情，近来不到谢池草。\n欢游曾步翠窈。\n乱红迷紫曲，芳意今少。\n舞扇招香，歌桡唤玉，犹忆钱塘苏小。\n无端暗恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18548, '三姝媚', '张炎', '芙蓉城伴侣。\n乍卸却单衣，茜罗重护。\n傍水开时，细看来、浑似阮郎前度。\n记得小楼，听一夜，江南春雨。\n梦醒箫声，流水青苹，旧游何许。\n谁翦层芳深贮。\n便洗尽长安，半面尘土。\n绝似桃根，带笑痕来伴，柳枝娇舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18549, '甘州・八声甘州', '张炎', '记玉关、踏雪事清游。\n寒气脆貂裘。\n傍枯林古道，长河饮马，此意悠悠。\n短梦依然江表，老泪洒西州。\n一字无题处，落叶都愁。\n载取白云归去，问谁留楚佩，弄影中洲。\n折芦花赠远，零落一身秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18550, '声声慢', '张炎', '寒花清事，老圃闲人，相看秋色霏霏。\n带叶分根，空翠半湿荷衣。\n沅湘旧愁未减，有黄金、难铸相思。\n但醉里，把苔笺重谱，不许春知。\n聊慰幽怀古意，且频簪短帽，休怨斜晖。\n采摘无多，一笑竟日忘归。\n从教护香径小，似东山、还似东篱。\n待去隐，怕如今、不是晋时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18551, '扫花游・扫地游', '张炎', '烟霞万壑，记曲径幽寻，霁痕初晓。\n绿窗窈窕。\n看随花石，就泉通沼。\n几日不来，一片苍云未扫。\n自长啸。\n怅乔木荒凉，都是残照。\n碧天秋浩渺。\n听虚籁泠泠，飞下孤峭。\n山空翠老。\n步仙风，怕有采芝人到。\n野色闲门，芳草不除更好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18552, '琐窗寒', '张炎', '断碧分山，空帘剩月，故人天外。\n香留酒。\n蝴蝶一生花里。\n想如今、醉魂未醒，夜台梦语秋声碎。\n自中仙去後，词笺赋笔，便无清致。\n都是。\n凄凉意。\n怅玉笥埋云，锦袍归水。\n形容憔悴。\n料应也、孤吟山鬼。\n那知人、弹折素弦，黄金铸出相思泪。\n但柳枝、门掩枯阴，候蛩愁暗苇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18553, '木兰花慢', '张炎', '龟峰深处隐，岩壑静、万尘空。\n任一路白云，山童休扫，却似崆峒。\n只恐烂柯人到，怕光阴、不与世间同。\n旋采生枝带叶，微煎石鼎团龙。\n从容。\n吟啸百年翁。\n行乐少扶筇。\n向镜水传心，柴桑袖手，门掩清风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18554, '三姝媚', '张炎', '苍潭枯海树。\n正雪窦高寒，水声东去。\n古意萧闲，问结庐人远，白云谁侣。\n贺监犹狂，还散迹、千岩风露。\n抱瑟空游，都是凄凉，此愁难语。\n莫趁江湖鸥鹭。\n怕太乙炉荒，暗消铅虎。\n投老心情，未归来何事，共成羁旅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18555, '扫花游・扫地游', '张炎', '嫩寒禁暖，正草色侵衣，野光如洗。\n去城数里。\n绕长堤是柳，钓船深舣。\n小立斜阳，试数花风第几。\n问春意。\n待留取断红，心事难寄。\n芳讯成拈指。\n甚远客他乡，老怀如此。\n醉馀梦里。\n尚分明认得，旧时罗绮。\n可惜空帘，误却归来燕子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18556, '台城路・齐天乐', '张炎', '春风不暖垂杨树，吹却絮云多少。\n燕子人家，夕阳巷陌，行入野畦深窈。\n筹花斗草。\n记小舫寻芳，断桥初晓。\n那日心情，几人同向近来老。\n消忧何处最好。\n夜深频秉烛，犹是迟了。\n南浦歌阑，东林社冷，赢得如今怀抱。\n吟暗恼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18557, '疏影', '张炎', '柳黄未结。\n放嫩晴消尽，断桥残雪。\n隔水人家，浑是花阴，曾醉好春时节。\n轻车几度新堤晓，想如今、燕莺犹说。\n纵艳游、得似当年，早是旧情都别。\n重到翻疑梦醒，弄泉试照影，惊见华发。\n却笑归来，石老云荒，身世飘然一叶。\n闭门约住青山色，自容与、吟窗清绝。\n怕夜寒、吹到梅花，休卷半帘明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18558, '渡江云', '张炎', '山空天入海，倚楼望极，风急暮潮初。\n一帘鸠外雨，几处闲田，隔水动春锄。\n新烟禁柳，想如今、绿到西湖。\n犹记得、当年深隐，门掩两三株。\n愁余。\n荒洲古溆，断梗疏萍，更漂流何处。\n空自觉、围羞带减，影怯灯孤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18559, '琐窗寒', '张炎', '乱雨敲春，深烟带晚，水窗慵凭。\n空帘谩卷，数日更无花影。\n怕依然、旧时燕归，定应未识江南冷。\n最怜他、树底蔫红，不语背人吹尽。\n清润。\n通幽径。\n待移灯翦韭，试香温鼎。\n分明醉里，过了几番风信。\n想竹间、高阁半开，小车未来犹自等。\n傍新晴、隔柳呼船，待教潮信稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18560, '忆旧游', '张炎', '记开帘过酒，隔水悬灯，款语梅边。\n未了清游兴，又飘然独去，何处山川。\n淡风暗收榆荚，吹下沈郎钱。\n叹客里光阴，消磨艳冶，都在尊前。\n留连。\n人处，是镜曲窥莺，兰阜围泉。\n醉拂珊瑚树，写百年幽恨，分付吟笺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18561, '水龙吟', '张炎', '仙人掌上芙蓉，涓涓犹湿金盘露。\n轻妆照水，纤裳玉立，飘摇似舞。\n几度消凝，满湖烟月，一汀鸥鹭。\n记小舟夜悄，波明香远，浑不见、花开处。\n应是浣纱人妒。\n褪红衣、被谁轻误。\n闲情淡雅，冶容清润，凭娇待语。\n隔浦相逢，偶然倾盖，似传心素。\n怕湘皋佩解，绿云十里，卷风西去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18562, '忆旧游', '张炎', '叹江潭树老，杜曲门荒，同赋飘零。\n乍见翻疑梦，对萧萧乱发，都是愁根。\n秉烛故人归後，花月锁春深。\n纵草带堪题，争如片叶，能寄殷勤。\n重寻。\n已无处，尚记得依稀，柳下芳邻。\n伫立香风外，抱孤愁凄惋，羞燕惭莺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18563, '甘州・八声甘州', '张炎', '倚危楼、一笛翠屏空，万里见天心。\n度野光清峭，晴峰涌日，冷石生云。\n帘卷小亭虚院，无地不花阴。\n径曲知何处，春水泠泠。\n啸傲柴桑影里，且怡颜莫问，谁古谁今。\n任燕留鸥住，聊复慰幽情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18564, '摸鱼子', '张炎', '爱吾庐、傍湖千顷，苍茫一片清润。\n晴岚暖翠融融处，花影倒窥天镜。\n沙浦迥。\n看野水涵波，隔柳横孤艇。\n眠鸥未醒。\n甚占得莼乡，都无人见，斜照起春暝。\n还重省。\n岂料山中秦晋。\n桃源今度难认。\n林间即是长生路，一笑元非捷径。\n深更静。\n待散以吹箫，跨鹤天风冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18565, '风入松', '张炎', '老来学圃乐年华。\n茅屋短篱遮。\n儿孙戏逐田翁去，小桥横、路转三叉。\n细雨一犁春意，西风万宝生涯。\n携筇犹记度晴沙。\n流水带寒鸦。\n门前少得宽闲地，绕平畴、尽是桑麻。\n却笑牧童遥指，杏花深处人家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18566, '凤凰台上忆吹箫', '张炎', '水国浮家，渔村古隐，浪游惯占花深。\n犹记得、琵琶半面，曾湿衫青。\n不道江空岁晚，桃叶渡、还叹飘零。\n因乘兴，醉梦醒时，却是山阴。\n投闲倦呼俦侣，竟棹入芦花，俗客难寻。\n风渺渺、云拖暮雪，独钓寒清。\n远溯流光万里，浑错认、叶竹寰瀛。\n元来是、天上太乙真人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18567, '解连环', '张炎', '楚江空晚。\n怅离群万里，恍然惊散。\n自顾影、欲下寒塘，正沙净草枯，水平天远。\n写不成书，只寄得、相思一点。\n料因循误了，残毡拥雪，故人心眼。\n谁怜旅愁荏苒。\n谩长门夜悄，锦筝弹怨。\n想伴侣、犹宿芦花，也曾念春前，去程应转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18568, '满庭芳', '张炎', '晴皎霜花，晓熔冰羽，开帘觉道寒轻。\n误闻啼鸟，生意又园林。\n闲了凄凉赋笔，便而今、不听秋声。\n消凝处，一枝借暖，终是未多情。\n阳和能几许，寻红探粉，也恁人。\n笑邻娃痴小，料理护花铃。\n却怕惊回睡蝶，恐和他、草梦都醒。\n还知否，能消几日，风雪灞桥深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18569, '忆旧游', '张炎', '问蓬莱何处，风月依然，万里江清。\n休说神仙事，便神仙纵有，即是闲人。\n笑我几番醒醉，石磴扫松阴。\n任狂客难招，采芳难赠，且自微吟。\n俯仰成陈迹，叹百年谁在，阑槛孤凭。\n海日生残夜，看卧龙和梦，飞入秋冥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18570, '解连环', '张炎', '句章城郭。\n问千年往事，几回归鹤。\n叹贞元、朝士无多，又日冷湖阴，柳边门钥。\n向北来时，无处认、江南花落。\n纵荷衣未改，病损茂陵，总是离索。\n山中故人去却。\n但碑寒岘首，旧景如昨。\n怅二乔、空老春深，正歌断帘空，草暗铜雀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18571, '台城路・齐天乐', '张炎', '薛涛笺上相思字，重开又还重折。\n载酒船空，眠波柳老，一缕离痕难折。\n虚沙动月。\n叹千里悲歌，唾壶敲缺。\n却说巴山，此时怀抱那时节。\n寒香深处话别。\n病来浑瘦损，懒赋情切。\n太白闲云，新丰旧雨，多少英游消歇。\n回潮似咽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18572, '声声慢', '张炎', '荷衣消翠，蕙带馀香，灯前共语生平。\n苦竹黄芦，都是梦里游情。\n西湖几番夜雨，怕如今、冷却鸥盟。\n倩寄远，见故人说道，杜老飘零。\n难挽清风飞佩，有相思都在，断柳长汀。\n此别何如，一笑写入瑶琴。\n天空水云变色，任、山鬼愁听。\n兴未已，更何妨、弹到广陵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18573, '水龙吟', '张炎', '乱红飞已无多，艳游终是如今少。\n一番雨过，一番春减，催人渐老。\n倚槛调莺，卷帘收燕，故园空杳。\n奈关愁不住，悠悠万里，浑恰似、天涯草。\n不拟相逢古道。\n才疑梦、又还惊觉。\n清风在柳，江摇白浪，舟行趁晓。\n遮莫重来，不如休去，怎堪怀抱。\n那知又、五柳门荒，曾听得、鹃啼了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18574, '一萼红', '张炎', '倚阑干。\n问绿华何事，偷饵九还丹。\n浣锦溪边，餐霞竹里，翠袖不倚天寒。\n照芳树、晴光泛晓，护么凤、无处认冰颜。\n露洗春腴，风摇醉魄，听笛江南。\n树挂珊瑚冷月，叹玉奴妆褪，仙掾诗悭。\n谩觅花云，不同梨梦，推篷恍记孤山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18575, '祝英台近', '张炎', '水痕深，花信足，寂寞汉南树。\n转首青阴，芳事顿如许。\n不知多少消魂，夜来风雨。\n犹梦到、断红流处。\n最无据。\n长年息影空山，愁入庾郎句。\n玉老田荒，心事已迟暮。\n几回听得啼鹃，不如归去。\n终不似、旧时鹦鹉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18576, '月下笛', '张炎', '万里孤云，清游渐远，故人何处。\n寒窗梦里，犹记经行旧时路。\n连昌约略无多柳，第一是、难听夜雨。\n谩惊回凄悄，相看烛影，拥衾谁语。\n张绪。\n归何暮。\n半零落，依依断桥鸥鹭。\n天涯倦旅。\n此时心事良苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18577, '水龙吟', '张炎', '几番问竹平安，雁书不尽相思字。\n篱根半树，村深孤艇，阑干屡倚。\n远草兼云，冻河胶雪，此时行李。\n望去程无数，并州回首，还又渡、桑乾水。\n笑我曾游万里。\n甚匆匆、便成归计。\n江空岁晚，栖迟犹在，吴头楚尾。\n疏柳经寒，断槎浮月，依然憔悴。\n待相逢、说与相思，想亦在、相思里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18578, '绮罗香', '张炎', '万里飞霜，千林落木，寒艳不招春妒。\n枫冷吴江，独客又吟愁句。\n正船舣、流水孤村，似花绕、斜阳归路。\n甚荒沟、一片凄凉，载情不去载愁去。\n长安谁问倦旅。\n羞见衰颜借酒，飘零如许。\n谩倚新妆，不入洛阳花谱。\n为回风、起舞尊前，尽化作、断霞千缕。\n记阴阴、绿遍江南，夜窗听暗雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18579, '洞仙歌', '张炎', '野鹃啼月，便角巾还第。\n轻掷诗瓢付流水。\n最无端、小院寂历春空，门自掩，柳发离离如此。\n可惜欢娱地。\n雨冷云昏，不见当时谱银字。\n旧曲怯重翻，总是离愁，泪痕洒、一帘花碎。\n梦沈沈、知道不归来，尚错问桃根，醉魂醒未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18580, '新雁过妆楼', '张炎', '风雨不来，深院悄、清事正满东篱。\n杖藜重到，秋气冉冉吹衣。\n瘦碧飘萧摇露便，腻黄秀野拂霜枝。\n忆芳时。\n翠微唤酒，江雁初飞。\n湘潭无人吊楚，叹落英自采，谁寄相思。\n淡泊生涯，聊伴老圃斜晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18581, '江神子・江城子', '张炎', '奇峰相对接球庭。\n乍微晴，又微阴。\n舍北江东，如盖自亭亭。\n翻笑天台连雁荡，隔一片、不逢君。\n此中幽趣许谁邻。\n境双清。\n人独清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18582, '塞翁吟', '张炎', '交到无心处，出岫细话幽期。\n看流水、意俱迟。\n且淡薄相依。\n凌霄未肯从龙去，物外共鹤忘机。\n迷古洞，掩晴晖。\n翠影湿行衣。\n飞飞。\n垂天翼，飘然万里，愁日暮、佳人未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18583, '祝英台近', '张炎', '占宽闲，锄浩渺。\n船舣水村悄。\n非雾非烟，生气覆瑶草。\n蒙茸数亩春阴，梦魂落寞，知踏碎、梨花多少。\n听孤啸。\n山浅种玉人归，缥缈度晴峭。\n鹤下芝田，五色散微照。\n笑他隔浦谁家，半江疏雨，空吟断、一犁清晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18584, '风入松', '张炎', '卷舒无意入虚玄。\n丘壑伴云烟。\n石根清气千年润，覆孤松、深护啼猿。\n霭霭静随仙隐，悠悠闲对僧眠。\n傍花懒向小溪边。\n空谷覆流泉。\n浮踪自感今如此，已无心、万里行天。\n记得晋人归去，御风飞过斜川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18585, '瑶台聚八仙・新雁过妆楼', '张炎', '带雨春潮。\n人不渡、沙外晓色迨遥。\n自横深静，谁见隔柳停桡。\n知我知鱼未是乐，转篷闲趁白鸥招。\n任风飘。\n夜来酒醒，何处江皋。\n泛宅浮家更好，度菰蒲影里，濯足吹箫。\n坐阅千帆，空竞万里波涛。\n他年五湖访隐，第一是吴淞第四桥。\n玄真子、共游烟水，人月俱高。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18586, '疏影', '张炎', '黄昏片月。\n似碎阴满地，还更清绝。\n枝北枝南，疑有疑无，几度背灯难折。\n依稀倩女离魂处，缓步出、前村时节。\n看夜深、竹外横斜，应妒过云明灭。\n窥镜蛾眉淡抹。\n为容不在貌，独抱孤洁。\n莫是花光，描取春痕，不怕丽谯吹彻。\n还惊海上然犀去，照水底、珊瑚如活。\n做弄得、酒醒天寒，空对一庭香雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18587, '木兰花慢', '张炎', '采芳洲薜荔，流水外、白鸥前。\n度万壑千岩，晴岚暖翠，心目娟娟。\n山川。\n自今自古，怕依然。\n认得米家船。\n明月闲延夜语，落花静拥春眠。\n吟边。\n象笔蛮笺。\n清绝处、小留连。\n正寂寂江潭，树犹如此，那更啼鹃。\n居廛。\n闭门隐几，好林泉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18588, '风入松', '张炎', '小窗晴碧帘波。\n昼影舞飞梭。\n惜春休问花多少，柳成阴、春已无多。\n金字初寻小扇，铢衣早试轻罗。\n园林未肯受清和。\n人醉牡丹坡。\n啸歌且尽平生事，问东风、毕竟如何。\n燕子寻常巷陌，酒边莫唱西河。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18589, '台城路・齐天乐', '张炎', '云多不记山深浅，人行半天岩壑。\n旷野飞声，虚空倒影，松挂危峰疑落。\n流泉喷薄。\n自窈窕寻源，引瓢孤酌。\n倦倚高寒，少年游事老方觉。\n幽寻闲院邃阁。\n树凉僧坐夏，翻笑行乐。\n近竹惊秋，穿萝误晚，都把尘缘消却。\n东林似昨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18590, '还京乐', '张炎', '醉吟处。\n都是琴尊，竟日松下语。\n有笔床茶灶，瘦筇相引，逢花须住。\n正翠阴迷路。\n年光荏苒成孤旅。\n待趁燕樯，休忘了、玄都前度。\n渐烟波远，怕五湖凄冷，佳人袖薄，修竹依依日暮。\n知他甚处重逢，便匆匆、背潮归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18591, '台城路・齐天乐', '张炎', '一窗烟雨不除草。\n移家静藏深窈。\n东晋图书，南山杞菊，谁识幽居怀抱。\n疏阴未扫。\n叹乔木犹存，易分残照。\n慷慨悲歌，故人多向近来老。\n相逢何事欠早。\n爱吟心共苦，此意难表。\n野水无鸥，闲门断柳，不满清风一笑。\n荷衣制了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18592, '梅子黄时雨', '张炎', '流水孤村，爱尘事顿消，来访深隐。\n向醉里谁扶，满身花影。\n鸥鹭相看如瘦，近来不是伤春病。\n嗟流景。\n竹外野桥，犹系烟艇。\n谁引。\n斜川归兴。\n便啼鹃纵少，无奈时听。\n待棹击空明，鱼波千顷。\n弹到琵琶留不住，最愁人是黄昏近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18593, '西子妆慢・西子妆', '张炎', '白浪摇天，青阴涨地，一片野怀幽意。\n杨花点点是春心，替风前、万花吹泪。\n遥岑寸碧。\n有谁识、朝来清气。\n自沈吟、甚流光轻掷，繁华如此。\n斜阳外。\n隐约孤村，隔坞闲门闭。\n渔舟何似莫归来，想桃源、路通人世。\n危桥静倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18594, '声声慢', '张炎', '门当竹径，鹭管苔矶，烟波自有闲人。\n棹入孤村，落照正满寒汀。\n桃花远迷洞口，想如今、方信无秦。\n醉梦醒，向沧浪容与，净濯兰缨。\n乃一声归去，对笔床茶灶，寄傲幽情。\n雨笠风蓑，古意谩说玄真。\n知鱼淡然自乐，钓清名、空在丝纶。\n笑未已，笑严陵、还笑渭滨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18595, '湘月・念奴娇', '张炎', '行行且止。\n把乾坤收入，篷窗深里。\n星散白鸥三四点，数笔横塘秋意。\n岸觜冲波，篱根受叶，野径通村市。\n疏风迎面，湿衣原是空翠。\n堪叹敲雪门荒，争棋墅冷。\n苦竹鸣山鬼。\n纵使如今犹有晋，无复清游如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18596, '长亭怨・长亭怨慢', '张炎', '笑海上、白鸥盟冷。\n飞过前滩，又顾秋影。\n似我知鱼，乱蒲流水动清饮。\n岁华空老，犹一缕、柔丝恋顶。\n慵忆鸳行，想应是、朝回花径。\n人静。\n怅离群日暮，都把野情消尽。\n山中旧隐。\n料独树、尚悬苍暝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18597, '徵招', '张炎', '秋风吹碎江南树，石床自听流水。\n别鹤不归来，引悲风千里。\n馀音犹在耳。\n有谁识、醉翁深意。\n去国情怀，草枯沙远，尚鸣山鬼。\n客里。\n可消忧，人间世、寥寥几年无此。\n杏老古坛荒，把凄凉空指。\n心尘聊更洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18598, '法曲献仙音', '张炎', '云隐山晖，树分溪影，未放妆台帘卷。\n篝密笼香，镜圆窥粉，花深自然寒浅。\n正人在、银屏底，琵琶半遮面。\n语声软。\n且休弹、玉关愁怨。\n怕唤起西湖，那时春感。\n杨柳古湾头，记小怜、隔水曾见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18599, '渡江云', '张炎', '江山居未定，貂裘已敝，空自带愁归。\n乱花流水外，访里寻邻，都是可怜时。\n桥边燕子，似软语、斜日江篱。\n休问我、如今心事，错认镜中谁。\n还思。\n新烟惊换，旧雨难招，做不成春意。\n浑未省、谁家芳草，犹梦吟诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18600, '斗婵娟・霜叶飞', '张炎', '旧家池沼。\n寻芳处、从教飞燕频绕。\n一湾柳护水房春，看镜鸾窥晓。\n晕宿酒、双蛾淡扫。\n罗襦飘带腰围小。\n尽醉方归去，又暗约明朝斗草。\n谁解先到。\n心绪乱若晴丝，那回游处，坠红争恋残照。\n近来心事渐无多，尚被莺声恼。\n便白发、如今纵少。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18601, '暗香', '张炎', '羽音辽邈。\n怪四檐昼悄，近来无鹊。\n木叶吹寒，极目凝思倚江阁。\n不信相如便老，犹未减、当时游乐。\n但趁他、斗草筹花，终是带离索。\n忆昨。\n更情恶。\n谩认著梅花，是君还错。\n石床冷落。\n闲扫松阴与谁酌。\n一自飘零去远，几误了、灯前深约。\n纵到此、归未得，几曾忘却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18602, '玉漏迟', '张炎', '竹多尘自扫。\n幽通径曲，禅房深窈。\n空翠吹衣，坐对闲云舒啸。\n寒木犹悬故叶，又过了、一番残照。\n经院悄。\n诗梦正迷，独怜衰草。\n幽趣尽属闲僧，浑未识人间，落花啼鸟。\n呼酒凭高，莫问四愁三笑。\n可惜秦山晋水，甚却向、此时登眺。\n清趣少。\n那更好游人老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18603, '长亭怨・长亭怨慢', '张炎', '记横笛、玉关高处。\n万里沙寒，雪深无路。\n破却貂裘，远游归後与谁谱。\n故人何许。\n浑忘了、江南旧雨。\n不拟重逢，应笑我、飘零如羽。\n同去。\n钓珊瑚海树。\n底事又成行旅。\n烟篷断浦。\n更几点、恋人飞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18604, '西河', '张炎', '花最盛。\n西湖曾泛烟艇。\n闹红深处小秦筝，断桥夜饮。\n鸳鸯水宿不知寒，如今翻被惊醒。\n那时事、都倦省。\n阑干来此闲凭。\n是谁分得半边机云，恍疑昼锦。\n想当飞燕皱裙时，舞盘微堕珠粉。\n软波不翦素练净。\n碧盈盈、移下秋影。\n醉里玉书难认。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18605, '玲珑四犯', '张炎', '流水人家，乍过了斜阳，一片苍树。\n怕听秋声，却是旧愁来处。\n因甚尚客殊乡，自笑我、被谁留住。\n问种桃、莫是前度。\n不拟桃花轻误。\n少年未识相思苦。\n最难禁、此时情绪。\n行云暗与风流散，方信别泪如雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18606, '凄凉犯', '张炎', '西风暗翦荷衣碎，柔丝不解重缉。\n荒烟断浦，晴晖历乱，半山摇碧。\n悠悠望极。\n忍独听、秋声渐急。\n更怜他、萧条柳发，相与动秋色。\n老态今如此，犹自留连，醉筇游屐。\n不堪瘦影，渺天涯、尽成行客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18607, '声声慢', '张炎', '山风古道，海国轻车，相逢只在东瀛。\n淡薄秋光，恰似此日游情。\n休嗟鬓丝断雪，喜闲身、重渡西泠。\n又溯远，趁回潮拍岸，断浦扬。\n莫向长亭折柳，正纷纷落叶，同是飘零。\n旧隐新招。\n知住第几层云。\n疏篱尚存晋菊，想依然、认得渊明。\n待去也，最愁人，犹恋故人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18608, '烛影摇红', '张炎', '舟舣鸥波，访邻寻里愁都散。\n老来犹似柳风流，先露看花眼。\n闲把花枝试拣。\n笑盈盈，和香待翦。\n也应回首，紫曲门荒，当年游惯。\n箫鼓黄昏，动人心处情无限。\n锦街不甚月明多，早已骄尘满。\n才过风柔夜暖。\n渐迤逦、芳程递趱。\n向西湖去，那里人家，依然莺燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18609, '忆旧游', '张炎', '记凝妆倚扇，笑眼窥帘，曾款芳尊。\n步交枝径，引生香不断，流水中分。\n忘了牡丹名字，和露拨花根。\n甚杜牧重来，买栽无地，都是消魂。\n空存。\n断肠草，伴几摺眉痕，几点啼痕。\n镜里芙蓉老，问如今何处，绾绿梳云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18610, '春从天上来', '张炎', '海上回槎。\n认旧时鸥鹭，犹恋蒹葭。\n影散香消，水流云在，疏树十里寒沙。\n难问钱塘苏小，都不见、擘竹分茶。\n更堪嗟。\n似荻花江上，谁弄琵琶。\n烟霞。\n自延晚照，尽换了西林，窈窕纹纱。\n蝴蝶飞来，不知是梦，犹疑春在邻家。\n一掬幽怀难写，春何处、春已天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18611, '甘州・八声甘州', '张炎', '看涓涓、两水自东西，中有百花庄。\n步交枝径里，帘分昼影，窗聚春香。\n依约谁教鹦鹉，列屋带垂杨。\n方喜闲居好，翻为诗忙。\n多少周情柳思，向一丘一壑，留恋年光。\n又何心逐鹿，蕉梦正钱塘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18612, '庆清朝', '张炎', '浅草犹霜。\n融泥未燕，晴梢润叶初乾。\n闲扶短策，邻家小聚清欢。\n错认篱根是雪，梅花过了一番寒。\n风还峭，较迟芳信，恰是春残。\n此境此时此意，待移琴独去，石冷慵弹。\n飘飘爽气，飞鸟相与俱还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18613, '真珠帘', '张炎', '绿房几夜迎清晓，光摇动、素月溶溶如水。\n惆怅一枝寒，记东阑闲倚。\n近日花边无旧雨，便寂寞、何曾吹泪。\n烛外。\n谩羞得红妆，而今犹睡。\n琪树皎立风前，万尘空、独挹飘然清气。\n雅淡不成娇，拥玲珑春意。\n落寞云深诗梦浅，但一似、唐昌宫里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18614, '探春慢', '张炎', '银浦流云，绿房迎晓，一抹墙腰月淡。\n暖玉生烟，悬冰解冻，碎滴瑶阶如霰。\n才放些晴意，早瘦了、梅花一半。\n也知不做花看，东风何事吹散。\n摇落似成秋苑。\n甚酿得春来，怕教春见。\n野渡舟回，前村门掩，应是不胜清怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18615, '风入松', '张炎', '一春不是不寻春。\n终是不人。\n好怀渐向中年减，对歌钟、浑没心情。\n短帽怕黏飞絮，轻衫压扑游尘。\n暖香十里软莺声。\n小舫绿杨阴。\n梦随蝴蝶飘零後，尚依依、花月关心。\n惆怅一株梨雪，明年甚处清明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18616, '渡江云', '张炎', '锦香缭绕地，深灯挂壁，帘影浪花斜。\n酒船归去後，转首河桥，那处认纹纱。\n重盟镜约，还记得、前度秦嘉。\n惟只有、叶题堪寄，流不到天涯。\n惊嗟。\n十年心事，几曲阑干，想萧娘声价。\n闲过了、黄昏时候，疏柳啼鸦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18617, '探芳信', '张炎', '坐清昼。\n正冶思萦花，馀酲倦酒。\n甚采芳人老，芳心尚如旧。\n消魂忍说铜驼事，不是因春瘦。\n向西园，竹扫颓垣，蔓萝荒。\n风雨夜来骤。\n叹歌冷莺帘，恨凝蛾岫。\n愁到今年，多似去年否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18618, '声声慢', '张炎', '烟堤小舫，雨屋深灯，春衫惯染京尘。\n舞柳歌桃，心事暗恼东邻。\n浑疑夜窗梦蝶，到如今、犹宿花阴。\n待唤起，甚江蓠摇落，化作秋声。\n回首曲终人远，黯消魂、忍看朵朵芳云。\n润墨空题，惆怅醉魄难醒。\n独怜水楼赋笔，有斜阳、不怕登临。\n愁未了，听残莺、、啼过柳阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18619, '徵招', '张炎', '可怜张绪门前柳，相看顿非年少。\n三径已荒凉，更如今怀抱。\n薄游浑是感，满烟水、东风残照。\n古调谁弹，古音谁赏，岁华空老。\n京洛染缁尘，悠然意，独对南山一笑。\n只在此山中，甚相逢不早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18620, '甘州・八声甘州', '张炎', '记天风、飞佩紫霞边，顾曲万花深。\n甚相如情倦，少陵愁老，还叹飘零。\n短梦恍然今昔，故国十年心。\n回首三三径，松竹成阴。\n不恨片篷南浦，恨翦灯听雨，谁伴孤吟。\n料瘦筇归後，闲锁北山云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18621, '一萼红', '张炎', '制荷衣。\n傍山窗卜隐，雅志可闲时。\n款竹门深，移花槛小，动人芳意菲菲。\n怕冷落、苹洲夜月，想时将、渔笛静中吹。\n尘外柴桑，灯前儿女，笑语忘归。\n分得烟霞数亩，乍扫苔寻径，拨叶通池。\n放鹤幽情，吟莺欢事，老去却愿春迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18622, '高阳台', '张炎', '古木迷鸦，虚堂起燕，欢游转眼惊心。\n南圃东窗，酸风扫尽芳尘。\n鬓貂飞入平原草，最可怜、浑是秋阴。\n夜沈沈。\n不信归魂，不到花深。\n吹箫踏叶幽寻去，任船依断石，袖裹寒云。\n老桂悬香，珊瑚碎击无声。\n故园已是愁如许，抚残碑，却又伤今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18623, '台城路・齐天乐', '张炎', '郎吟未了西湖酒，惊心又歌南浦。\n折柳官桥，呼船野渡，还听垂虹风雨。\n漂流最苦。\n况如此江山，此时情绪。\n怕有鸱夷，笑人何事载诗去。\n荒台只今在否。\n登临休望远，都是愁处。\n暗草埋沙，明波洗月，谁念天涯羁旅。\n荷阴未暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18624, '桂枝香', '张炎', '晴江迥阔。\n又客里天涯，还叹轻别。\n万里潮生一棹，柳丝犹结。\n荷衣好向山中补，共飘零、几年霜雪。\n赋归何晚，依依径菊，弄香时节。\n料此去、清游未歇。\n引一片秋声，都付吟箧。\n落叶长安，古意对人休说。\n相思只在相留处，有孤芳、可怜空折。\n旧怀难写，山阳怨笛，夜凉吹月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18625, '庆春宫・高阳台', '张炎', '蟾窟研霜，蜂房点蜡，一枝曾伴凉宵。\n清气初生，丹心未折，浓艳到此都消。\n避风归去，贮金屋、妆成汉娇。\n栗肌微润，和露吹香，直与秋高。\n小山旧隐重招。\n记得相逢，古道迢遥。\n把酒长歌，插花短舞，谁在水国吹箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18626, '长亭怨・长亭怨慢', '张炎', '望花外、小桥流水，门巷，玉箫声绝。\n鹤去台空，佩环何处弄明月。\n十年前事，愁千折、心情顿别。\n露粉风香谁为主，都成消歇。\n凄咽。\n晓窗分袂处，同把带鸳亲结。\n江空岁晚，便忘了、尊前曾说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18627, '甘州・八声甘州', '张炎', '望涓涓、一水隐芙蓉，几被暮云遮。\n正凭高送目，西风断雁，残月平沙。\n未觉丹枫尽老，摇落已堪嗟。\n无避秋声处，愁满天涯。\n一自盟鸥别後，甚酒瓢诗锦，轻误年华。\n料荷衣初暖，不忍负烟霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18628, '甘州・八声甘州', '张炎', '隔花窥半面，带天香、吹动一天秋。\n叹行云流水，寒枝夜鹊，杨柳湾头。\n浪打石城风急，难系莫愁舟。\n未了笙歌梦，倚棹西州。\n重省寻春乐事，奈如今老去，鬓改花羞。\n指斜阳巷陌，都是旧曾游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18629, '疏影', '张炎', '雪空四野，照归心万里，千峰独立。\n身与天游，一洗襟怀，海镜倒涌秋白。\n相逢懒问盈亏事，但脉脉、此情无极。\n是几番、飞盖追随，桂底露衣香湿。\n闲款楼台夜色。\n料水光未许，人世先得。\n影里分明，认得山河，一笑乱山横碧。\n乾坤许大须容我，浑忘了、醉乡犹客。\n待倩谁、招下清风，共结岁寒三益。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18630, '湘月・念奴娇', '张炎', '随风万里。\n已无心出岫，浮游天地。\n为问山中何所有，此意不堪持寄。\n淡薄相依，行藏自适，一片松阴外。\n石根苍润，飘飘元是清气。\n长伴暗谷泉生，晴光潋滟，湿影摇花碎。\n浊浊波涛江汉里，忽见清流如此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18631, '真珠帘', '张炎', '云深别有深庭宇。\n小帘栊、占取芳菲多处。\n花暗水房春，润几番酥雨。\n见说苏堤晴未稳，便懒趁、踏青人去。\n休去。\n且料理琴书，夷犹今古。\n谁见静里闲心，纵荷衣未茸，雪巢堪赋。\n醉醒一乾坤，任此情何许。\n茂树石床同坐久，又却被、清风留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18632, '大圣乐', '张炎', '隐市山林，傍家池馆，顿成佳趣。\n是几番临水看云，就树揽香，诗满阑干横处。\n翠径小车行花影，听一片春声人笑语。\n深庭宇。\n对清昼渐长，闲教鹦鹉。\n芳情缓寻细数。\n爱碧草平烟红自雨。\n任燕来莺去，香凝翠暖，歌酒清时钟鼓。\n二十四帘冰壶里，有谁在箫台犹醉舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18633, '瑞鹤仙', '张炎', '楚云分断雨。\n问那回、因甚琴心先许。\n匆匆话离绪。\n正花房蜂闹，著春无处。\n残歌剩舞。\n尚隐约、当时院宇。\n黯消凝、铜雀深深，忍把小乔轻误。\n休赋。\n玉尊别後，老叶沈沟，暗珠还浦。\n欢游再数。\n能几日、采芳去。\n最无端做了，霎时娇梦，不道风流恁苦。\n把馀情、付与秋蛩，夜长自语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18634, '祝英台近', '张炎', '水西船，山北酒，多为买春去。\n事与云消，飞过旧时雨。\n谩留一掬相思，待题红叶，奈红叶、更无题处。\n正延伫。\n乱花浑不知名，娇小未成语。\n短棹轻装，逢迎段桥路。\n那知杨柳风流，柳犹如此，更休道、少年张绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18635, '恋绣衾', '张炎', '一枝凉玉路尘。\n下瑶台、疑是梦云。\n怕趁取、西风去，被何人、拈住皱裙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18636, '甘州・八声甘州', '张炎', '记当年、紫曲戏分花，帘影最深深。\n听惺忪语笑，香寻古字，谱掐新声。\n散尽黄金歌舞，那处著春情。\n梦醒方知梦，梦岂无凭。\n几点别馀清泪，尽化作妆楼，断雨残云。\n指梢头旧恨，豆蔻结愁心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18637, '浣溪纱・浣溪沙', '张炎', '犀押重帘水院深。\n柳绵扑帐昼。\n梦回孤蝶弄春阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18638, '菩萨蛮', '张炎', '蕊香不恋琵琶结。\n舞衣折损藏花蝶。\n春梦未堪凭。\n几时春梦真。\n愁把残更数。\n泪落灯前雨。\n歌酒可曾。\n情怀似去年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18639, '四字令・醉太平', '张炎', '莺吟翠屏。\n帘吹絮云。\n东风也怕花。\n带飞花赶春。\n邻娃笑迎。\n嬉游趁晴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18640, '声声慢', '张炎', '穿花省路，傍竹寻邻，如何故隐都荒。\n问取堤边，因甚减却垂杨。\n消磨纵然未尽，满烟波、添了斜阳。\n空叹息，又翻成无限，杜老凄凉。\n一舸清风何处，把秦山晋水，分贮诗囊。\n发已飘飘，休问岁晚空江。\n松陵试招旧隐，怕白鸥、犹识清狂。\n渐溯远，望并州、却是故乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18641, '杏花天', '张炎', '湘罗几翦黏新巧。\n似过雨、胭脂全少。\n不教枝上春痕闹。\n都被海棠分了。\n带柳色、愁眉暗恼。\n谩遥指、孤村自好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18642, '醉落魄・一斛珠', '张炎', '柳侵阑角。\n画帘风软红香泊。\n引人蝴蝶翻轻薄。\n已自关情，和梦近来恶。\n眉梢轻把闲愁著。\n如今愁重眉梢弱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18643, '甘州・八声甘州', '张炎', '过千岩万壑古蓬莱，招隐竟忘还。\n想乾坤清气，霏霏冉冉，却在阑干。\n洞户来时不锁，归水映花关。\n只可自怡悦，持寄应难。\n狂客如今何处，甚酒船去後，烟水空寒。\n正黄尘没马，林下一身闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18644, '小重山', '张炎', '清气飞来望似空。\n数椽何用草，膝堪容。\n卷将一片当帘栊。\n难持赠，只在此山中。\n鱼影倦随风。\n无心成雨意，又西东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18645, '声声慢', '张炎', '晴光转树，晓气分岚，何人野渡横舟。\n断柳枯蝉，凉意正满西州。\n匆匆载花载酒，便无情、也自风流。\n芳昼短，奈不堪深夜，秉烛来游。\n谁识山中朝暮，向白云一笑，今古无愁。\n散发吟商，此兴万里悠悠。\n清狂未应似我，倚高寒、隔水呼鸥。\n须待月，冼多清、都付与秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18646, '木兰花慢', '张炎', '幽栖身懒动，邃庭悄、日偏长。\n甚不隐山林，不喧车马，不断生香。\n澄心淡然止水，笑东风、引得落花忙。\n慵对鱼翻暗藻，闲留莺管垂杨。\n徜徉。\n净几明窗。\n穿窈窕、染芬芳。\n看白鹤无声，苍云息影，物外行藏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18647, '玉蝴蝶', '张炎', '留得一团和气，此花开尽，春已规圆。\n虚白窗深，恍讶碧落星悬。\n芳丛、低翻雪羽，凝素艳、争簇冰蝉。\n向西园。\n几回错认，明月秋千。\n欲觅生香何处，盈盈一水，空对娟娟。\n待折归来，倩谁偷解玉连环。\n试结取、鸳鸯锦带，好移傍、鹦鹉珠帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18648, '南楼令・唐多令', '张炎', '一片赤城霞。\n无心恋海涯。\n远飞来、乔木人家。\n且向琴书深处隐，终胜似、听琵琶。\n休近七香车。\n年华已破瓜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18649, '国香', '张炎', '空谷幽人。\n曳冰簪雾带，古色生春。\n结根未同萧艾，独抱孤贞。\n自分生涯淡薄，隐蓬蒿、甘老山林。\n风烟伴憔悴，冷落吴宫，草暗花深。\n霁痕消蕙雪，向崖阴饮露，应是知心。\n所思何处，愁满楚水湘云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18650, '探春慢', '张炎', '列屋烘炉，深门响竹，催残客里时序。\n投老情怀，薄游滋味，消得几多凄楚。\n听雁听风雨，更听过、数声柔舻。\n暗将一点归心，试托醉乡分付。\n借问西楼在否。\n休忘了盈盈，端正窥户。\n铁马春冰，柳蛾晴雪，次第满城箫鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18651, '烛影摇红', '张炎', '隔水呼舟，采香何处追游好。\n一年春事二分花，犹有花多少。\n容易繁华过了。\n趁园林、飞红未扫。\n旧酲新醉，几日不来，绿阴芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18652, '木兰花慢', '张炎', '万花深处隐，安一点、世尘无。\n步翠麓幽寻，白云自在，流水萦纡。\n携歌缓游细赏，倩何人、重写辋川图。\n迟日香生草木，淡风声和琴书。\n安居。\n歌引巾车。\n童放鹤、我知鱼。\n看静里闲中，醒来醉後，乐意偏殊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18653, '意难忘', '张炎', '风月吴娃。\n柳阴中认得，第二香车。\n春深妆减艳，波转影流花。\n莺语滑，透纹纱。\n有低唱人夸。\n怕误却，周郎醉眼，倚扇佯遮。\n底须拍碎红牙。\n听曲终奏雅，可是堪嗟。\n无人知此意，明月又谁家。\n尘滚滚，老年华。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18654, '壶中天・念奴娇', '张炎', '瘦筇访隐，正繁阴闲锁，一壶幽绿。\n乔木苍寒图画古，窈窕行人韦曲。\n鹤响天高，水流花净，笑语通华屋。\n虚堂松外，夜深凉气吹烛。\n乐事杨柳楼心，瑶台月下，有生香堪掬。\n谁理商声帘外悄，萧瑟悬鸣玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18655, '壶中天・念奴娇', '张炎', '穿幽透密，傍园林宴乐，清时钟鼓。\n帘隔波纹分昼影，融得一壶春聚。\n篆径通花，花多迷径，难省来时路。\n缓寻深静，野云松下无数。\n空翠暗湿荷衣，夷犹舒啸，日涉成佳趣。\n香雪因风晴更落，知是山中何树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18656, '清波引', '张炎', '江涛如许。\n更一夜听风听雨。\n短篷容与。\n盘礴那堪数。\n弭节澄江树。\n不为莼鲈归去。\n怕教冷落芦花，谁招得旧鸥鹭。\n寒汀古溆。\n尽日无人唤渡。\n此中清楚。\n寄情在谭麈。\n难觅真闲处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18657, '暗香', '张炎', '猗兰声歇。\n抱孤琴思远，几番弹彻。\n洗耳无人，寂寂行歌古时月。\n一笑东风又急。\n黯消凝、恨听啼。\n想少陵、还叹飘零，遣兴在吟箧。\n愁绝。\n更离别。\n待款语迟留，赋归心切。\n故园梦接。\n花影闲门掩春蝶。\n重访山中旧隐，有羁怀、未须轻说。\n莫相忘，堤上柳、此时共折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18658, '一萼红', '张炎', '舣孤篷。\n正丛篁护碧，流水曲池通。\n伛偻穿岩，纡盘寻径，忽见倒影凌空。\n拥一片、花阴无地，细看来、犹带古春风。\n胜事园林，旧家陶谢，诗酒相逢。\n眼底烟霞无数，料神仙即我，何处崆峒。\n清气分来，生香不断，洞户自有云封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18659, '霜叶飞', '张炎', '故园空杳。\n霜风劲、南塘吹断瑶草。\n已无清气碍云山，奈此时怀抱。\n尚记得、修门赋晓。\n杜陵花竹归来早。\n傍雅亭幽榭，惯款语英游，好怀无限欢笑。\n不见换羽移商，杏梁尘远，可怜都付残照。\n坐中泣下最谁多，叹赏音人少。\n怅一夜、梅花顿老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18660, '忆旧游', '张炎', '记琼筵卜夜，锦槛移春，同恼莺娇。\n暗水流花径，正无风院落，银烛迟销。\n闹枝浅压髫髻，香脸泛红潮。\n甚如此游情，还将乐事，轻趁冰消。\n飘零又成梦，但长歌袅袅，柳色迢迢。\n一叶江心冷，望美人不见，隔浦难招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18661, '木兰花慢', '张炎', '水痕吹杏雨，正人在、隔江船。\n看燕集春芜，渔栖暗竹，湿影浮烟。\n馀寒尚犹恋柳，怕东风、未肯擘晴绵。\n愁重迟教醉醒，梦长催得诗圆。\n楼前。\n笑语当年。\n情款密、思留连。\n记白月依弦，青天堕酒，衮衮山川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18662, '潇潇雨・踏莎行', '张炎', '空山弹古瑟，掬长流、洗耳复谁听。\n倚阑干不语，江潭树老，风挟波鸣。\n愁里不须啼，花落石床平。\n岁月鸥前梦，耿耿离情。\n记得相逢竹外，看词源倒泻，一雪尘缨。\n笑匆匆呼酒，飞雨夜行舟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18663, '台城路・齐天乐', '张炎', '分明柳上春风眼，曾看少年人老。\n雁拂沙黄，天垂海白，野艇谁家昏晓。\n惊心梦觉。\n谩慷慨悲歌，赋归不早。\n想得相如，此时终是倦游了。\n经行几度怨别，酒痕消未尽，空被花恼。\n茂苑重来，竹溪深隐，还胜飘零多少。\n羁怀顿扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18664, '木兰花慢', '张炎', '目光牛背上，更时把、汉书看。\n记落叶江城，孤云海树，漂泊忘还。\n悬知偶然是梦，梦醒来、未必是邯郸。\n笑指萤灯借暖，愁怜镜雪惊寒。\n投闲。\n寄傲怡颜。\n要一似、白鸥闲。\n且旋缉荷衣，琴尊客里，岁月人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18665, '瑶台聚八仙・新雁过妆楼', '张炎', '秋水涓涓。\n人正远、鱼雁待拂吟笺。\n也知游意，多在第二桥边。\n花底鸳鸯深处影，柳阴淡隔里湖船。\n路绵绵。\n梦吹旧笛，如此山川。\n平生几谢屐，任放歌自得，直上风烟。\n峭壁谁家，长啸竟落松前。\n十年孤剑万里，又何似、畦分抱瓮泉。\n山中酒，且醉餐石髓，白眼青天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18666, '摸鱼子', '张炎', '想西湖、段桥疏树。\n梅花多是风雨。\n如今见说闲云散，烟水少逢鸥鹭。\n归未许。\n又款竹谁家，远思愁□庾。\n重游倦旅。\n纵认得乡山，长江滚滚，隔浦正延伫。\n垂杨渡。\n握手荒城旧侣。\n不知来自何处。\n春窗翦韭青灯夜，疑与梦中相语。\n阑屡拊。\n甚转眼流光，短发真堪数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18667, '壶中天・念奴娇', '张炎', '海山缥缈。\n算人间自有，移来蓬岛。\n一粒粟中生倒景，日月光融丹灶。\n玉洞分春，雪巢不夜，心寂凝虚照。\n鹤溪游处，肯将琴剑同调。\n休问挂树瓢空，窗前清意，赢得不除草。\n只恐渔郎曾误入，翻被桃花一笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18668, '风入松', '张炎', '危楼古镜影犹寒。\n倒景忽相看。\n桃花不识东西晋，想如今、也梦邯郸。\n缥缈神仙海上，飘零图画人间。\n宝光丹气共回环。\n水弱小舟闲。\n秋风难老三珠树，尚依依、脆管清弹。\n说与霓裳莫舞，银桥不到深山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18669, '数花风・凤凰阁', '张炎', '好游人老，秋鬓芦花共色。\n征衣犹恋去年客。\n古道依然黄叶。\n谁家萧瑟。\n自笑我、如何是得。\n酒楼仍在，流落天涯醉白。\n孤城寒树美人隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18670, '南楼令・唐多令', '张炎', '风雨怯殊乡。\n梧桐又小窗。\n甚秋声、今夜偏长。\n忆著旧时歌舞地，谁得似、牧之狂。\n茉莉拥钗梁。\n云窝一枕香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18671, '南楼令・唐多令', '张炎', '重整旧渔蓑。\n江湖风雨多。\n好襟怀、近日消磨。\n流水桃花随处有，终不似、隐烟萝。\n南浦又渔歌。\n桃云泛远波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18672, '淡黄柳', '张炎', '楚腰一捻。\n羞翦青丝结。\n力未胜春娇怯怯。\n暗托莺声细说。\n愁蹙眉心斗双叶。\n正情切。\n柔枝未堪折。\n应不解、管离别。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18673, '清平乐', '张炎', '候蛩凄断。\n人语西风岸。\n月落沙平江似练。\n望尽芦花无雁。\n暗教愁损兰成，可怜夜夜关情。\n只有一枝梧叶，不知多少秋声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18674, '虞美人', '张炎', '修眉刷翠春痕聚。\n难翦愁来处。\n断丝无力绾韶华。\n也学落红流水、到天涯。\n那回错认章台下。\n却是阳关也。\n待将新恨趁杨花。\n不识相思一点、在谁家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18675, '减字木兰花', '张炎', '锁香亭榭。\n花艳烘春曾卜夜。\n空想芳游。\n不到秋凉不信愁。\n酒迟歌缓。\n月色平分窗一半。\n谁伴孤吟。\n手擘黄花碎却心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18676, '踏莎行', '张炎', '柳未三眠，风才一讯。\n催人步吹笙径。\n可曾中酒似当时，如今却是看花病。\n老愿春迟，愁嫌昼静。\n秋千院落寒犹剩。\n卷帘休问海棠开，相传燕子归来近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18677, '南乡子', '张炎', '歌扇锦连枝。\n问著东风已不知。\n怪底楼前多种柳，相思。\n那叶浑如旧样眉。\n醉里眼都迷。\n遮莫东墙带笑窥。\n行到寻常游冶处，慵归。\n只道看花似向时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18678, '蝶恋花', '张炎', '颇爱杨琼妆淡注。\n犹理螺鬟，扰扰松云聚。\n两翦秋痕流不去。\n佯羞却把周郎顾。\n欲诉闲愁无说处。\n几过莺帘，听得间关语。\n昨夜月明香暗度。\n相思忽到梅花树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18679, '蝶恋花', '张炎', '仙子锄云亲手种。\n春闹枝头，消得微霜冻。\n可是东风吹不动。\n金铃悬网珊瑚重。\n社燕盟鸥诗酒共。\n未足游情，刚把斜阳送。\n今夜定应归去梦。\n青苹流水箫声弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18680, '蝶恋花', '张炎', '巧结分枝黏翠艾。\n翦翦香痕，细把泥金界。\n小簇葵榴芳锦隘。\n红妆人见应须爱。\n午镜将拈开凤盖。\n倚醉凝娇，欲戴还慵戴。\n约臂犹馀朱索在。\n梢头添挂朱符袋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18681, '清平乐', '张炎', '暗香千树。\n结屋中间住。\n明月一方流水护。\n梦入梨云深处。\n清冰隔断尘埃。\n无人踏碎苍苔。\n一似逋仙归後，吟诗不下山来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18682, '烛影摇红', '张炎', '闲苑深迷，趁香随粉都行遍。\n隔窗花气暖扶春，只许莺莺占。\n烛焰晴烘醉脸。\n想东邻、偷窥笑眼。\n欲寻无处，暗掐新声，银屏斜掩。\n一片云闲，那知顾曲周郎怨。\n看花犹自未分明，毕竟何时见。\n已信仙缘较浅。\n谩凝思、风帘倒卷。\n出门一笑，月落江横，数峰天远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18683, '露华', '张炎', '乱红自雨，正翠蹊误晓，玉洞明春。\n蛾眉淡扫，背风不语盈盈。\n莫恨小溪流水，引刘郎、不是飞琼。\n罗扇底，从教净冶，远障歌尘。\n一掬莹然生意，伴压架酴，相恼芳吟。\n玄都观里，几回错认梨云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18684, '解语花', '张炎', '行歌趁月，唤酒延秋，多买莺莺笑。\n蕊枝娇小。\n浑无奈、一掬醉乡怀抱。\n筹花斗草。\n几曾放、好春闲了。\n芳意阑，可惜香心，一夜酸风扫。\n海上仙山缥缈。\n问玉环何事，苦无分晓。\n旧愁空杳。\n蓝桥路、深掩半庭斜照。\n馀情暗恼。\n都缘是、那时年少。\n惊梦回、懒说相思，毕竟如今老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18685, '祝英台近', '张炎', '及春游，卜夜饮，人醉万花醒。\n转眼年华，白发半垂领。\n与鸥同一清波，风苹月树，又何事、浮踪不定。\n静中省。\n便须门掩柴桑，黄卷伴孤隐。\n一粟生涯，乐事在瓢饮。\n爱闲休说山深，有梅花处，更添个、暗香疏影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18686, '瑶台聚八仙・新雁过妆楼', '张炎', '楚竹闲挑。\n千日酒、乐意稍稍渔樵。\n那回轻散，飞梦便觉迢遥。\n似隔芙蓉无路到，如何共此可怜宵。\n旧愁消。\n故人念我，来问寂寥。\n登临试开笑口，看垂垂短发，破帽休飘。\n款语微吟，清气顿扫花妖。\n明朝柳岸醉醒，又知在烟波第几桥。\n怀人处，任满身风露，踏月吹箫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18687, '满江红', '张炎', '傅粉何郎，比玉树、琼枝谩夸。\n看生子、东涂西抹，笑语浮华。\n蝴蝶一生花里活，似花还却似非花。\n最可人、娇艳正芳年，如破瓜。\n离别恨，生叹嗟。\n欢情事，起喧哗。\n听歌喉清润，片玉无瑕。\n洗尽人间笙笛耳，赏音多向五侯家。\n好思量、都在步莲中，裙翠遮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18688, '祝英台近', '张炎', '带飘飘，衣楚楚。\n空谷饮甘露。\n一转花风，萧艾遂如许。\n细看息影云根，淡然诗思，曾□被、生香轻误。\n此中趣。\n能消几笔幽奇，羞掩众芳谱。\n薜老苔荒，山鬼竟无语。\n梦游忘了江南，故人何处，听一片、潇湘夜雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18689, '台城路・齐天乐', '张炎', '老枝无著秋声处，萧萧倦听风雨。\n暗饮春腴，欣荣晚节，不载天河人去。\n心存太古。\n喜冰雪相看，此君欲语。\n共倚云根，岁寒羞并岁寒所。\n当年曾见汉馆，卷帘频坐对，飞梦湘楚。\n叹我重来，何堪如此，落叶空江无数。\n盘桓屡抚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18690, '长亭怨・长亭怨慢', '张炎', '跨匹马、东瀛烟树。\n转首十年，旅愁无数。\n此日重逢，故人犹记旧游否。\n雨今云古。\n更秉烛、浑疑梦语。\n衮衮登台，叹野老、白头如许。\n归去。\n问当初鸥鹭。\n几度西湖霜露。\n漂流最苦。\n便一似、断蓬飞絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18691, '忆旧游', '张炎', '笑铭崖笔倦，访雪舟寒，觅里寻邻。\n半掩闲门草，看长松落荫，旧榻悬尘。\n自怜此来何事，不为忆鲈莼。\n但回首当年，芙蓉城里，胜友如云。\n思君。\n度遥夜，谩疑是梅花，檐下空巡。\n蝶与周俱梦，折一枝聊寄，古意殊真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18692, '踏莎行', '张炎', '花引春来，手擎春住。\n芳心一点谁分付。\n微歌微笑蓦思量，瞥然抛与东流去。\n带润偷拈，和香密护。\n归时自有留连处。\n不随烟水不随风，不教轻把刘郎误。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18693, '浪淘沙', '张炎', '香雾湿云环。\n蕊佩珊珊。\n酒醒微步晚波寒。\n金鼎尚存丹已化，雪冷虚坛。\n游冶未知还。\n鹤怨空山。\n潇湘无梦绕丛兰。\n碧海茫茫归不去，却在人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18694, '西江月', '张炎', '落落奇花未吐，离离瑶草偏幽。\n蓬山元是不知秋。\n却笑人间春瘦。\n潇丽寒犀麈尾，玲珑润玉搔头。\n半窗晴日水痕收。\n不怕杜鹃啼後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18695, '珍珠令', '张炎', '桃花扇底歌声杳。\n愁多少。\n便觉道花阴闲了。\n因甚不归来，甚归来不早。\n满院飞花休要扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18696, '壶中天・念奴娇', '张炎', '波明昼锦，看芳莲迎晓，风弄晴碧。\n乔木千年长润屋，清荫图书琴瑟。\n龟甲屏开，虾须帘卷，瑶草秋无色。\n和熏兰麝，彩衣欢拥诗伯。\n溪上燕往鸥还，笔床茶灶，筇竹随游屐。\n闲似神仙闲最好，未必如今闲得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18697, '摸鱼子', '张炎', '溯空明、霁蟾飞下，湖湘难辨遥树。\n流来那得清如许，不与众流东注。\n浮净宇。\n任消息虚盈，壶内藏今古。\n停杯问取。\n甚玉笛移宫，银桥散影，依旧广寒府。\n休凝伫。\n鼓渔歌在否。\n沧浪浑是烟雨。\n黄河路接银河路。\n炯炯近天尺五。\n还自语。\n奈一寸闲心，不是安愁处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18698, '好事近', '张炎', '葱倩满身云，酒晕浅融香颊。\n水调数声娴雅，把芳心偷说。\n风吹裙带下阶迟，惊散双蝴蝶。\n佯拈花枝微笑，溜晴波一瞥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18699, '小重山', '张炎', '阴过云根冷不移。\n古林疏又密，色依依。\n何须喷饭笑当时。\n谷，盈尺小鹅溪。\n展玩似堪疑。\n楚山从此去，望中迷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18700, '蝶恋花', '张炎', '求友林泉深密处。\n弄舌调簧，如问春何许。\n燕子先将雏燕去。\n凄凉可是歌来暮。\n乔木萧萧梧叶雨。\n不似寻芳，翻落花心露。\n认取门前杨柳树。\n数声须入新年语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18701, '南楼令・唐多令', '张炎', '天净雨初晴。\n秋清人更清。\n满吟窗、柳思周情。\n一片香来松桂下，长听得，读书声。\n闲处卷黄庭。\n年年两鬓青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18702, '风入松', '张炎', '新篁依约佩初摇。\n老石润山腰。\n逸人未必犹酣酒，正溪头、风雨潇潇。\n砺齿犹随市隐，虚心肯受春招。\n从教三径入渔樵。\n对此觉尘消。\n娟枝冷叶无多子，伴明窗、书卷诗瓢。\n清过炎天梅蕊，淡欺雪里芭蕉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18703, '踏莎行', '张炎', '水落槎枯，田荒玉碎。\n夜阑秉烛惊相对。\n故家人物已无传，一灯却照清江外。\n色展天机，光摇海贝。\n锦囊日月奚童背。\n重逢何处抚孤松，共吟风月西湖醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18704, '声声慢', '张炎', '因风整帽，借柳维舟，休登故苑荒台。\n去岁何年，游处半入苍苔。\n白鸥旧盟未冷，但寒沙、空与愁堆。\n谩叹息，问西门洒泪，不忍徘徊。\n眼底江山犹在，把冰弦弹断，苦忆颜回。\n一点归心，分付布袜青鞋。\n相寻已期到老，那知人、如此情怀。\n怅望久，海棠开、依旧燕来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18705, '声声慢', '张炎', '□声短棹，柳色长条，无花但觉风香。\n万境天开，逸兴纵我清狂。\n白鸥更闲似我，趁平芜、飞过斜阳。\n重叹息，却如何不□，梦里黄梁。\n一自三高非旧，把诗囊酒具，千古凄凉。\n近日烟波，乐事尽逐渔忙。\n山横洞庭夜月，似潇湘、不似潇湘。\n归未得，数清游、多在水乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18706, '声声慢', '张炎', '百花洲畔，十里湖边，沙鸥未许盟寒。\n旧隐琴书，犹记渭水长安。\n苍云数千万叠，却依然、一笑人间。\n似梦里，对清尊白发，秉烛更阑。\n渺渺烟波无际，唤扁舟欲去，且与凭阑。\n此别何如，能消几度阳关。\n江南又听夜雨，怕梅花、零落孤山。\n归最好，甚闲人，犹自未闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18707, '木兰花慢', '张炎', '二分春是雨，采香径、绿阴铺。\n正私语晴蛙，于飞晚燕，闲掩纹疏。\n流光惯欺病酒，问杨花、过了有花无。\n啼初闻院宇，钓船犹系菰蒲。\n林逋。\n树老山孤。\n浑忘却、隐西湖。\n叹扇底歌残，蕉间梦醒，难寄中吴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18708, '清平乐', '张炎', '□花一叶。\n比似前时别。\n烟水茫茫无处说。\n冷却西湖□月。\n贞芳只合深山。\n红尘了不相关。\n留得许多清影，幽香不到人间。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18709, '清平乐', '张炎', '□□不了。\n都被红尘老。\n一粒粟中休道好。\n弱水竟通蓬岛。\n孤云漂泊难寻。\n如今却在□□。\n莫趁清风出岫，此中方是无心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18710, '清平乐', '张炎', '平沙流水。\n叶老芦花未。\n落雁无声还有字。\n一片潇湘古意。\n扁舟记得幽寻。\n相寻只在□□。\n莫趁春风飞去，玉关夜雪犹深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18711, '临江仙', '张炎', '翦翦春水出万壑，和春带出芳丛。\n谁分弱水洗尘红。\n低回金叵罗，约略玉玲珑。\n昨夜洞庭云一片，朗吟飞过天风。\n戏将瑶草散虚空。\n灵根何处觅，只在此山中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18712, '思佳客', '张炎', '梦里瞢腾说梦华。\n莺莺燕燕已天涯。\n蕉中覆处应无鹿，汉上从来不见花。\n今古事，古今嗟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18713, '清平乐', '张炎', '柳间花外。\n日日离人泪。\n忆得楼心和月醉。\n落叶与愁俱碎。\n如今一笑吴中。\n眼青犹认衰翁。\n先泛扁舟烟水，西湖多定相逢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18714, '清平乐', '张炎', '□□晴树。\n寒食无风雨。\n记得当时游冶处。\n桂底一身香露。\n神仙只在蓬莱。\n不知白鹤飞来。\n乘兴飘然归去，人踏破青苔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18715, '风入松', '张炎', '满头风雪昔同游。\n同载月明舟。\n回来又续西湖梦，绕江南、那处无愁。\n赢得如今老大，依然只是漂流。\n故人翦烛对花讴。\n不记此身浮。\n征衣冷落荷衣暖，径虽荒、也合归休。\n明□□□烟水，相思却在并州。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18716, '渔歌子', '张炎', '□卯湾头屋数间。\n放船收尽一溪山。\n聊适兴，且怡颜。\n问天难买是真闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18717, '渔歌子', '张炎', '□□□□□溪流。\n紧系篱边一叶舟。\n沽酒去，闭门休。\n从此清闲不属鸥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18718, '渔歌子', '张炎', '□□□□白云多。\n童子贪眠枕绿蓑。\n莞尔笑，浩然歌。\n奈此萧萧落叶何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18719, '渔歌子', '张炎', '□□□□半树梅。\n卷帘一色玉蓬莱。\n宜啸咏，莫徘徊。\n乘兴扁舟好去来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18720, '渔歌子', '张炎', '□□□□□子同。\n更无人识老渔翁。\n来往事，有无中。\n却恐桃源自此通。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18721, '渔歌子', '张炎', '□□□□□求鱼。\n钓不得鱼还自如。\n尘事远，世人疏。\n何须更写绝交书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18722, '渔歌子', '张炎', '□□□□濯尘缨。\n严濑溪有重轻。\n多少事，古今情。\n今人当似古人清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18723, '渔歌子', '张炎', '□□□□□浮家。\n篷底光阴鬓未华。\n停短棹，舣平沙。\n流水恐是杏坛花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18724, '渔歌子', '张炎', '□□□□□孤村。\n路隔尘寰水到门。\n斜照散，远云昏。\n白鹭飞来老树根。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18725, '渔歌子', '张炎', '□□□年酒半酣。\n知鱼知我静中参。\n峰六六，径三三。\n此怀难与俗人谈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18726, '一翦梅', '张炎', '闷蕊惊寒减艳痕。\n蜂也消魂。\n蝶也消魂。\n醉归无月傍黄昏。\n知是花村。\n知是前村。\n留得闲枝叶半存。\n好似桃根。\n不似桃根。\n小楼昨夜声浑。\n春到三分。\n秋到三分。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18727, '南乡子', '张炎', '野色一桥分。\n活水流云直到门。\n落叶堆篱从不扫，开尊。\n醉里教儿诵楚文。\n隔断马蹄痕。\n商鼎熏花独自闻。\n吟思更添清绝处，黄昏。\n月白枝寒雪满村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18728, '清平乐', '张炎', '五湖一叶。\n风浪何时歇。\n醉里不知花影别。\n依旧空山明月。\n夜深鹤怨归迟。\n此时那处堪归。\n门外一株杨柳，折来多少相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18729, '柳梢青', '张炎', '一夜凝寒，忽成琼树，换却繁华。\n因甚春深，片红不到，绿水人家。\n眼惊白昼天涯。\n空望断、尘香钿车。\n独立回风，东阑惆怅，莫是梨花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18730, '南歌子', '张炎', '窗密春声聚，花多水影重。\n只留一路过东风。\n围得生香不断、锦熏笼。\n月地连金屋，云楼瞰翠蓬。\n惺忪笑语隔帘栊。\n知是谁调鹦鹉、柳阴中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18731, '青玉案', '张炎', '万红梅里幽深处。\n甚杖履、来何暮。\n草带湘香穿水树。\n尘留不住。\n云留却住。\n壶内藏今古。\n独清懒入终南去。\n有忙事、修花谱。\n骑省不须重作赋。\n园中成趣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18732, '台城路・齐天乐', '张炎', '当年不信江湖老，如今岁华惊晚。\n路改家迷，花空阴落，谁识重来刘阮。\n殊乡顿远。\n甚犹带羁怀，雁凄蛩怨。\n梦里忘归，乱浦烟浪片帆转。\n闭门休叹故苑。\n杖藜游冶处，萧艾都遍。\n雨色云西，晴光水北，一洗悠然心眼。\n行行渐懒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18733, '菩萨蛮', '张炎', '霜花铺岸浓如雪。\n田间水浅冰初结。\n林密乱鸦啼。\n山深雁过稀。\n风恬湖似镜。\n冷浸楼台影。\n梅不怕隆寒。\n疏葩正耐看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18734, '尾犯', '张炎', '一白受春知。\n独爱老来，疏瘦偏宜。\n古月黄昏，许松竹相依。\n晕藓枯槎半折，影浮波、渴龙倒窥。\n岁华凋谢，水边篱落，雪後忽横枝。\n百花头上立，且休问、向北开迟。\n老了何郎，不成便无诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18735, '祝英台近', '张炎', '水空流，心不竞，门掩柳阴早。\n芸暖书芗，声压四檐悄。\n断尘飞远清风，人间醒醉，任蝶梦、何时分晓。\n古音少。\n素琴久已无弦，俗子未知道。\n听雨看云，依旧静中好。\n但教春风融融，一般意思，小窗外、不除芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18736, '华胥引', '张炎', '碧浮春盖，黄点秋旗，细芳泛月。\n露委残钗，烟梳高髻曾戏折。\n几度宿寄山房，□曲尘云屑。\n香入蜂须，蜜房风味应别。\n酒浮汤，爱霏霏、粉黄清绝。\n嫩苞新子，凭谁香歌五粒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18737, '甘州・八声甘州', '张炎', '想不劳、添竹引龙须，断梗忽传芳。\n记珠悬润碧，飘飘秋影，曾印禅窗。\n诗外片云落莫，错认是花光。\n无色空尘眼，雾老烟荒。\n一翦静中生意，任前看冷淡，真味深长。\n有清风如许，吹断万红香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18738, '沁园春', '韩信同', '望紫云翁，启明在东，长庚在西。\n但空有寸心，荆州江汉，未能百里，弱水沙黎。\n菊底秋深，樵边信至，一曲阳春草木知。\n长吟咏，觉声如韩操，骨似陶诗。\n不应鬓发能稀。\n七十寿强如六十耆。\n想高谈倾坐，风斯下矣，微辞漱物，清且涟漪。\n谩说翁，休夸淇叟，用舍行藏各有时。\n真修养，有近思家学，字字参芝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18739, '沁园春', '王炎午', '又是年时，杏红欲脸，柳绿初芽。\n奈寻春步远，马嘶湖曲，卖花声过，人唱窗纱。\n暖日晴烟，轻衣罗扇，看遍王孙七宝车。\n谁知道，十年魂梦，风雨天涯。\n休休何必伤嗟。\n谩赢得、青青两鬓华。\n且不知门外，桃花何代，不知江左，燕子谁家。\n世事无情，天公有意，岁岁东风岁岁花。\n拚一笑、且醒来杯酒，醉後杯茶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18740, '点绛唇', '徐瑞', '多事春风，年年绿遍江南草。\n罗裙色好。\n莫把相如恼。\n梦入瑶台，搔背麻姑爪。\n还惊觉。\n杜鹃啼早。\n一夜相思老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18741, '菩萨蛮', '王去疾', '吴波深处波声急。\n栏干下瞰鱼龙宅。\n江北与江南。\n斜阳山外山。\n十洲三岛地。\n梦里身曾至。\n今日醉危亭。\n神仙邀我盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18742, '踏莎行', '刘将孙', '水际轻烟，沙边微雨。\n荷花芳草垂杨渡。\n多情移徙忽成愁，依稀恰是西湖路。\n血染红笺，泪题锦句。\n西湖岂忆相思苦。\n只应幽梦解重来，梦中不识从何去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18743, '阮郎归', '刘将孙', '斜阳江路柳青青。\n传杯那放停。\n上船不记送人行。\n南风吹酒醒。\n江曲曲，路萦萦。\n月明潮水生。\n送将残梦作浮萍。\n角声何处城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18744, '南乡子', '刘将孙', '山色泛秋光。\n点点东篱菊又黄。\n岁月欺人如此去，堂堂。\n一事无成两鬓霜。\n佳节共持觞。\n无限杯供有限狂。\n明月明年诗句苦，茫茫。\n细把茱萸感慨长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18745, '八声甘州', '刘将孙', '不看萸、把酒对名山，无帽厌西风。\n渺四海故人，一尊今雨，万里长空。\n宇宙此山此日，今夕几人同。\n举世谁不醉，独属陶公。\n当日白衣几许，漫凄其寄兴，落日篱东。\n抚停云六合，借醉托孤踪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18746, '八声甘州', '刘将孙', '看东风、天上放梅开，经岁又新成。\n笑柳眼迷青，桃腮改白，蝶舞尘惊。\n任是万红千紫，无力与春争。\n想建章鹊，犹是残。\n不比腊前憔悴，拨寒炉，茶薄烟清。\n快玉龙战罢，四野迥收兵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18747, '八声甘州', '刘将孙', '又江南、三月更明朝，便已是南风。\n拟强驻韶光，狂追柳絮，卧占残红。\n早向尊前沈醉，莫听五更钟。\n赢得春工笑，恼杀渠侬。\n只道春风不改，□年来岁去，柳密花浓。\n但沈腰潘鬓，无复旧时容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18748, '满江红', '刘将孙', '正好花时，忽办得、匆匆来去。\n道一往无情，却又别颦愁妩。\n四海云鬟高样髻，长思红袖□分路。\n怪近来、不怨客毡寒，婵娟误。\n黄花约，终难据。\n曾未肯，清园住。\n只昼思夜梦，浅斟低诉。\n莲子擘开谁在意，徐娘一笑来何暮。\n又争知、寂寞白头吟，寒机素。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18749, '满江红', '刘将孙', '南浦绿波，只断送、行人行色。\n虽只是、鹏抟九万，天池春碧。\n鸾侣凤朋争快睹，鸥盟鹭宿空曾识。\n到玉堂、天上念西江，今非昔。\n公去也，宁怀别。\n人感旧，情空切。\n但岁寒松柏，相期茂悦。\n好在莫偿尘土债，风流宁可金门客。\n俯人间、大暑少清风，多炎热。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18750, '满江红', '刘将孙', '千里酸风，茂陵客、咸阳古道。\n宫门夜、马嘶无迹，东关云晓。\n牵上魏车将汉月，忆君清泪知多少。\n怅土花、三十六宫墙，秋风袅。\n露兰，啼痕绕。\n画阑桂，雕香早。\n便天还知道，和天也老。\n独出携盘谁送客，刘郎陵上烟迷草。\n悄渭城、已远月荒凉，波声小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18751, '摸鱼儿', '刘将孙', '又匆匆、一番元夕，无灯更愁风雨。\n人间天上无归梦，惟有春来春去。\n愁不语。\n漫泪湿香绡，□草人何许。\n百年胜处。\n还更有琉璃，春棚月架，万眼蝶罗否。\n风流事，孤负後来儿女。\n可怜薄命三五。\n千金无买吴呆处，更说龙飞凤舞。\n今又古。\n便剩有才情，无分登楼赋。\n春醪独抚。\n也难觅阿瞒，肯容狂客，醉里试歌舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18752, '摸鱼儿', '刘将孙', '雨萧萧、春寒欲暮。\n杜鹃声转□□。\n东风与汝何恩怨，强管人间去住。\n行且去。\n漫憔悴十年，愁得身成树。\n青青故宇。\n看浩荡灵修，徘徊落日，不乐复何故。\n曾听处。\n少日京华行路。\n青灯梦断无语。\n风林飒飒鸡声乱，摇落壮心如土。\n今又古。\n任啼到天明，清血流红雨。\n人生几许。\n且赢得刘郎，看花眼惯，懒复赋前度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18753, '摸鱼儿', '刘将孙', '甚平生、风流谢客，刀头梦送酸楚。\n不堪又得花间曲，猛忆云英霜杵。\n闲情赋。\n谁催就月明，云鬓犀梳吐。\n才情几许。\n待遗策重来，吹箫一弄，鸾凤共轻举。\n留春住。\n买得绿波南浦。\n黄金□散如土。\n蔷薇洞口三生路。\n无奈春光顿阻。\n新□绪。\n也待见东邻，花艳墙低处。\n东风看取。\n便娇送飞梭，半携编贝，笑咏尚高古。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18754, '金缕曲・贺新郎', '刘将孙', '我老无能矣。\n叹人生、得开笑口，一年闲几。\n去景悠悠如有待，白发已非春事。\n便一笑、何曾是喜。\n我本渔樵孟诸野，向举家、尽叹今如是，空自苦，有谁似。\n堆堆独坐文书里。\n是无能、爱闲爱静，清时有味。\n出处古今无真是，往往君言有理。\n看攘臂、後来锋起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18755, '江城子', '刘将孙', '云涛白凤贺瑶池。\n仗葳蕤。\n路芳菲。\n十月温汤，赐浴卸罗衣。\n半点檀心天一笑，琼奴弱，玉环肥。\n风流谁合婿金闺。\n露将。\n雪争晖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18756, '江城梅花引', '刘将孙', '明霞回雨霁秋空。\n笑难逢。\n步城东。\n直上翠微，客有可人同。\n回首向来轻节序，筋力异，心犹在，愧鬓蓬。\n悲年冉冉江滚滚。\n骑台平，蒋陵冷。\n天高年晚，山河险，烟雾冥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18757, '六州歌头', '刘将孙', '天涯倦客，如梦说今宵。\n承平事，车尘涨，马鸣萧。\n火城朝。\n狂歌闲嬉笑，平康客，五陵侠，闲相待，沙河路，灞陵桥。\n万眼琉璃，目眩去闲买，一翦梅烧。\n数金蛾彩蝶，簇带那人娇。\n说著魂销。\n掩鲛绡。\n波翻海，尘换世，铜仙泪，铁心娆。\n渺何地，朱履，解金貂。\n步宫腰。\n瑶池惊燕罢，瓶落井，箭离。\n灯楼倒，吴儿老，绛都迢。\n点点梅梢残雪，似东风、吹恨难消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18758, '水调歌头', '刘将孙', '摇风犹似旆，倾雨不成盘。\n西风未禁十日，早作背时看。\n寂寞六郎秋扇，牵补灵均破屋，风露半襟寒。\n坐感青年晚，不但翠云残。\n叹此君，深隐映，早阑珊。\n人间受尽炎热，暑夕几恁阑。\n待得良宵灏气，正是好天良月，红到绿垂乾。\n摇落从此始，感慨不能闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18759, '沁园春', '刘将孙', '壬戌之秋，七夕既望，苏子泛舟。\n正赤壁风清，举杯属客，东山月上，遗世乘流。\n桂棹叩舷，洞箫倚和，何事呜呜怨泣幽。\n悄危坐，抚苍苍东望，渺渺荆州。\n客云天地蜉蝣。\n记千里舳舻旗帜浮。\n叹孟德周郎，英雄安在，武昌夏口，山水相缪。\n客亦知夫，盈虚如彼，山月江风有尽不。\n喜更酌，任东方既白，与子遨游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18760, '沁园春', '刘将孙', '十月雪堂，将归临皋，二客从坡。\n适薄暮得鱼，细鳞巨口，新霜脱叶，月步行歌。\n有客无肴，有肴无酒，如此风清月白何。\n归谋妇，得旧藏斗酒，重载婆娑。\n登虬踞虎嵯峨。\n更凭醉攀翻栖鹘窠。\n曾岁月几何，江流断岸，山川非昔，夜啸扪萝。\n孤鹤横江，羽衣入梦，应悟飞鸣昔我过。\n开户视，但寂寥四顾，万顷烟波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18761, '沁园春', '刘将孙', '流水断桥，坏壁春风，一曲韦娘。\n记宰相开元，弄权疮，全家骆谷，追骑仓皇。\n彩凤随鸦，琼奴失意，可似人间白面郎。\n知他是，燕南牧马，塞北驱羊。\n啼痕自诉衷肠。\n尚把笔低徊愧下堂。\n叹国手无棋，危涂何策，书窗如梦，世路方长。\n青冢琵琶，穹庐笳拍，未比渠侬泪万行。\n二十载，竟何时委玉，何地埋香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18762, '忆旧游', '刘将孙', '正落花时节，憔悴东风，绿满愁痕。\n悄客梦惊呼伴侣，断鸿有约，回泊归云。\n江空共道惆怅，夜雨隔篷闻。\n尽世外纵横，人间恩怨，细酌重论。\n叹他乡异县，渺旧雨新知，历落情真。\n匆匆那忍别，料当君思我，我亦思君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18763, '水龙吟', '陈恕可', '素姬初宴瑶池，佩环误落云深处。\n分香华井，洗妆湘渚，天姿淡泞。\n碧盖吹凉，玉冠迎晓，盈盈笑语。\n记当时乍识，江明夜静，只愁被、婵娟误。\n几点沙边飞鹭。\n旧盟寒、远迷烟雨。\n相思未尽，纤罗曳水，清铅泣露。\n玉镜台空，银瓶绠绝，断魂何许。\n待今宵试探，中流一叶，共凌波去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18764, '齐天乐', '陈恕可', '碧柯摇曳声何许，阴阴晚凉庭院。\n露湿身轻，风生翅薄，昨夜绡衣初翦。\n琴丝宛转。\n弄几曲新声，几番凄惋。\n过雨高槐，为渠一洗故宫怨。\n清虚襟度漫与，向人低诉处，幽思无限。\n败叶枯形，残阳绝响，消得西风肠断。\n尘情已倦。\n任翻鬓云寒，缀貂金浅。\n蜕羽难留，顿觉仙梦远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18765, '齐天乐', '陈恕可', '蜕仙飞佩流空远，珊珊数声林杪。\n薄暑眠轻，浓阴听久，勾引凄凉多少。\n长吟未了。\n想犹怯高寒，又移深窈。\n与整绡衣，满身风露正清晓。\n微薰庭院昼永，那回曾记得，如诉幽抱。\n断响难寻，馀悲独省，叶底还惊秋早。\n齐宫路杳。\n叹往事魂消，夜阑人悄。\n谩省轻盈，粉奁双鬓好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18766, '桂枝香', '陈恕可', '西风故国。\n记乍免内黄，归梦溪曲。\n还是秦星夜映，楚霜秋足。\n无肠枉抱东流恨，任年年、褪匡微绿。\n草汀篝火，芦洲纬箔，早寒渔屋。\n叙旧别、芳荐玉。\n正香擘新橙，清泛佳菊。\n依约行沙乱雪，误惊窗竹。\n江湖岁晚相思远，对寒灯、谩怀幽独。\n嫩汤浮眼，枯形蜕壳，断魂重续。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18767, '水龙吟', '陈深', '此翁疑是香山，老来愈觉才情富。\n天孙借与，金刀玉尺，裁云缝雾。\n一曲阳春，樽前惟欠，柳蛮樱素。\n对苍松翠竹，江空岁晚，伴明月、倾芳醑。\n深谷修兰楚楚。\n续离骚、载歌初度。\n麻姑素约，天寒相访，遗余琼露。\n拟借青鸾，吹笙碧落，采芝玄圃。\n奈玉堂催召，文园醉叟，草凌云赋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18768, '贺新郎', '陈深', '丹凤翔云表。\n览德辉、翩然飞下，翠蓬仙岛。\n银汉无声天似水，昨夜新凉多少。\n听一曲、琼箫音渺。\n千尺秦台凌空峻，见一双、翠羽先飞到。\n披紫雾，揽瑶草。\n风流别乘当英妙。\n对江山、掀髯把酒，浩歌长啸。\n绿发公候何足浼，自是无双才调。\n况槐阴、青青天杪。\n月殿娥云深处，近清秋、丹桂催开早。\n斟绿醑，戴花帽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18769, '沁园春', '陈深', '浪迹烟霞，有酒千锺，有书五车。\n任从来萧散，闲心似水，何堪妩媚，笑面如花。\n濯发沧浪，放歌江海，肯被红尘半点遮。\n谁知道，抱无名钜璞，重价难赊。\n嘻嗟。\n大泽龙蛇。\n且蟠屈、深潜得计些。\n看淋漓醉墨，神情自足，摩挲雄剑，肝胆无邪。\n渭水烟蓑，营丘绣衮，出处何尝有异耶。\n今何在，但素蟾东出，红日西斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18770, '齐天乐', '陈深', '秋涛欲涨西陵渡，江亭晓来雄观。\n帝子吹笙，洛妃起舞，应喜蓬宫仙诞。\n斗墟东畔。\n望缥缈星槎，来从河汉。\n明月楼台，绣筵重启曼桃宴。\n庄椿一树翠色，五枝芳桂长，金蕊玉干。\n自笑狂疏，尊前起寿，不似卫郎温润。\n一卮泛满。\n羡彭泽风流，醉巾长岸。\n老圃黄花，清香宜岁晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18771, '西江月', '陈深', '龙沫流芳旎旎，犀沈锯削霏霏。\n薇心玉露练香泥。\n厌尽人间花气。\n银叶初温火缓，金猊静袅烟微。\n此时清赏只心知。\n难向人前举似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18772, '虞美人', '陈深', '玉搔斜压乌云堕。\n拄颊看书卧。\n开元天子惜娉婷。\n一笑嫣然何事、便倾城。\n马嵬风雨归时路。\n艳骨销黄土。\n多情谁写书画中。\n江水江花千古、恨无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18773, '洞仙歌', '陈深', '银波湛碧，遥泛仙槎早。\n婺宿荧煌瑞云晓。\n庆芳传丹桂，欢动连枝，称寿处，一簇蓬莱翠窈。\n步虚声宛转，清澈瑶坛，疑是钧霄凤音渺。\n正金姥、礼虚皇，天阶净，凉入绡衣风袅。\n想金书、秘字赐长生，进九酝霞卮，练颜长好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18774, '少年游', '刘铉', '石榴花下薄罗衣。\n睡起却寻棋。\n未省高低，被伊春笋，拈了白玻璃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18775, '蝶恋花', '刘铉', '人自怜春春未去。\n萱草石榴，也解留春住。\n只道送春无送处。\n山花落得红成路。\n高处莺啼低蝶舞。\n何况日长，燕子能言语。\n付与光阴相客主。\n晴云又卷西边雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18776, '乌夜啼', '刘铉', '垂杨影里残红。\n甚匆匆。\n只有榴花、全不怨东风。\n暮雨急。\n晓鸦湿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18777, '贺新郎', '梁明夫', '万里朝天去。\n见浔阳江上，风引仙舟淮浦。\n到得玉阶方寸地，历历苍生辛苦。\n要尽活、江南一路。\n昼绣归来沾御渥，听邦人、箫鼓迎初度。\n龟与鹤，亦掀舞。\n前身定是溪吕。\n笑当时、八十始卜，非熊非虎。\n试数行年逢革卦，革命正逢汤武。\n真千载、风云会遇。\n拟向庐山招五老，诣道山、同献蓬莱赋。\n仍剪菊，荐秋露。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18778, '鹊桥仙', '梅坡', '华桐日永，泛兰风细，节近朱明十日。\n玉麟何事吐书来，瑞世应、文章东壁。\n绿衣戏彩，金樽酌醴，兰玉阶庭森列。\n更看千岁树青青，管取并、三槐手植。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18779, '满江红', '梅坡', '天佑生贤，安排个、麦秋六日。\n人尽道、英雄慷慨，中兴人物。\n佛祖庆生宜後两，洞宾初度犹迟七。\n欲急流勇退作神仙，如何得。\n州县考，劳书绩。\n东西府，今虚席。\n看台星北拱，寿星南极。\n即见紫泥书下逮，须还玉笋班头立。\n愿得君、千载庆风云，齐箕翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18780, '水调歌头', '梅坡', '五月进农黍，三叶换阶。\n不知今夕何夕，嵩岳庆生申。\n莲幕泮宫小试，花悬二车遍历，所至蔼芳声。\n一札颁明诏，千里寄专城。\n席方温，边报警，塞飞尘。\n腹中数万兵甲，笑却狄人兵。\n金印明年如斗，黄阁有人引类，阔步到公卿。\n遥拜祝椿算，长愿侍枫宸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18781, '千秋岁引', '梅坡', '两叶开，千年桃熟，恰近秋期十三日。\n寿星辉映福星现，寿山高对城山立。\n蕊宫仙，王母宴，瑶池客。\n齐劝芳樽斟玉液。\n齐唱新词翻玉笛。\n岁岁今朝陪燕集。\n荣华富贵长年出，重重锦上花添色。\n谢庭兰，燕山桂，登科必。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18782, '蓦山溪', '徐观国', '儒官措大，是官曰都得做。\n宰相故崇下，呼召也须同，太原公子，能武又能文，闲暇里，抱琴书，车马时相过。\n樽开北海，减请还知麽。\n叵耐这点徒，刚入词、把人点污。\n儒冠屈辱，和我被干连，累告讦，孟尝君，带累三千个。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18783, '渔家傲', '某邑妓', '十月小春梅蕊破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18784, '失调名', '阮郎中', '东风捻就，腰儿纤细。\n系的粉裙儿不起。\n近来只惯掌中看，忍教在、烛花影里。\n更阑应是，酒红微褪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18785, '失调名', '吴某', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18786, '南乡子', '吴某', '楼台里、东风淡荡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18787, '南乡子', '吴某', '乍卷珠帘新燕入。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18788, '多丽', '吴某', '几声天外归鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18789, '渔家傲', '吴某', '一声初报晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18790, '蝶恋花', '俞克成', '梦断池塘惊乍晓。\n百舌无端，故作枝头闹。\n报道不禁寒料峭。\n未教舒展闲花草。\n尽日帘垂人不到。\n老去情疏，底事伤春瘦。\n相对一樽归计早。\n玉山不减巫山好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18791, '万年欢', '胡浩然', '灯月交光，渐轻风布暖，先到南国。\n罗绮娇容，十里绛纱笼烛。\n花艳惊郎醉目。\n有多少、佳人如玉。\n春衫袂，整整齐齐，内家新样妆束。\n欢情未足。\n更阑谩勾牵旧恨，萦乱心曲。\n怅望归期，应是紫姑频卜。\n暗想双眉对蹙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18792, '东风齐著力', '胡浩然', '残腊收寒，三阳初转，已换年华。\n东君律管，迤逦到山家。\n处处笙簧鼎沸，会佳宴、坐列仙娃。\n花丛里，金炉满，龙麝烟斜。\n此景转堪夸。\n深意祝、寿山福海增加。\n玉觥满泛，且莫厌流霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18793, '送入我门来', '胡浩然', '荼垒安扉，灵馗挂户，神傩烈竹轰雷。\n动念流光，四序式周回。\n须知今岁今宵尽，似顿觉明年明日催。\n向今夕，是处迎春送腊，罗绮筵开。\n今古遍同此夜，贤愚共添一岁，贵贱仍偕。\n互祝遐龄，山海固难摧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18794, '春霁・秋霁', '胡浩然', '迟日融和，乍雨歇东郊，嫩草凝碧。\n紫燕双飞，海棠相衬，妆点上林春色。\n黯然望极。\n因人天气浑无力。\n又听得。\n园苑，数声莺啭柳阴直。\n当此暗想，故国繁华，俨然游人，依旧南陌。\n院深沈、梨花乱落，那堪如练点衣白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18795, '满庭芳', '胡浩然', '潇洒佳人，风流才子，天然分付成双。\n兰堂绮席，烛影耀荧煌。\n数辐红罗绣帐，宝妆篆、金鸭焚香。\n分明是，芙蕖浪里，一对浴鸳鸯。\n欢娱，当此际，山盟海誓，地久天长。\n愿五男二女，七子成行。\n男作公卿将相，女须嫁、君宰侯王。\n从兹去，荣华富贵，福禄寿无疆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18796, '小冲山・小重山', '宋丰之', '花样妖娆柳样柔。\n眼波流不断、满眶秋。\n窥人佯整玉搔头。\n娇无力，舞罢却成羞。\n无计与迟留。\n满怀禁不得、许多愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18797, '风中柳・谢池春', '孙夫人', '销灭芳容，端的为郎烦恼。\n鬓慵梳、宫妆草草。\n别离情绪，待归来都告。\n怕伤郎、又还休道。\n利锁名缰，几阻当年欢笑。\n更那堪、鳞鸿信杳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18798, '满庭芳', '陈若晦', '五洞深沈，九峰回抱，望中云汉相侵。\n暮春天气，宫殿翠烟深。\n一片山光澹净，溪月上、碧水浮金。\n环楼杪，仙人度曲，空外响虚音。\n龙香，时暗引，青鸾白鹤，飞下秋阴。\n露华冷、环珠点缀瑶林。\n犹记华胥梦断，从别後、几许追寻。\n人间世，逝川东注，红日又西沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18799, '摸鱼儿', '徐一初', '对茱萸、一年一度。\n龙山今在何处。\n参军莫道无勋业，消得从容尊俎。\n君看取。\n便破帽飘零，也博名千古。\n当年幕府。\n知多少时流，等闲收拾，有个客如许。\n追往事，满目山河晋土。\n征鸿又过边羽。\n登临莫上高层望，怕见故宫禾黍。\n觞绿醑。\n浇万斛牢愁，泪阁新亭雨。\n黄花无语。\n毕竟是西风，朝来披拂，犹忆旧时主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18800, '声声慢', '吴叔', '烟横山腹，雁点秋容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18801, '沁园春', '陈彦章妻', '记得爷爷，说与奴奴，陈郎俊哉。\n笑世人无眼，老夫得法，官人易聘，国士难媒。\n印信乘龙，夤绿叶凤，选似扬鞭选得来。\n果然是，西雍人物，京样官坯。\n送郎上马三杯。\n莫把离愁恼别怀。\n那孤灯只砚，郎君珍重，离愁别恨，奴自推排。\n白发夫妻，青衫事业，两句微吟当折梅。\n彦章去，早归则个，免待相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18802, '忆秦娥', '郑文妻', '花深深。\n一钩罗袜行花阴。\n行花阴。\n闲将柳带，细结同心。\n日边消息空沈沈。\n画眉楼上愁登临。\n愁登临。\n海棠开後，望到如今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18803, '鹧鸪天', '刘鼎臣妻', '金屋无人夜剪缯。\n宝钗翻作齿痕轻。\n临行执手殷勤送，衬取萧郎两鬓青。\n听嘱付，好看承。\n千金不抵此时情。\n明年宴罢琼林晚，酒面微红相映明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18804, '柳梢青', '张任国', '挂起招牌。\n一声喝采，旧店新开。\n熟事孩儿，家怀老子，毕竟招财。\n当初合下安排。\n又不豪门买呆。\n自古道、正身替代，见任添差。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18805, '卜算子', '福建士子', '月上小楼西，鸡唱霜天晓。\n泪眼相看话别时，把定纤纤手。\n伊道不忘人，伊却都忘了。\n我若无情似你时，瞒不得、桥头柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18806, '水调歌头', '钟辰翁', '皓皓一何洁，更暴以秋阳。\n秋毫尘滓，如何浣得这肝肠。\n况对金风初度，酌彼银河静浴，六月凛冰霜。\n精白生来别，日月许争光。\n清明朝，清要路，遍流芳。\n澄清闽峤，姑命申伯式南邦。\n洗得甲兵静了，去作读书元帅，却入相吾皇。\n清问同天老，俾尔寿而昌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18807, '齐天乐', '钟辰翁', '南墙槐竹风摇翠。\n欢声为谁吹起。\n水秀龟神，松清鹤健，人在蓬壶深处。\n金猊喷雾。\n睹鬓雪青归，脸霞红驻。\n一点寿星，分明光照梅花树。\n三年冰蘖清苦。\n这长生富贵，天应分付。\n经阅黄庭，鼎烹丹井，心事澹然如水。\n东山霖雨。\n正出洗太虚，未容别墅。\n紫诏飞来，玉堂锵步武。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18808, '沁园春', '萧仲芮', '五马南来。\n一骑东驰，诏黄已催。\n正寻幽择胜，闲边点检，吟风弄月，忙处徘徊。\n玉井莲房，碧筒酒熟，趁得长年千岁杯。\n杯浮处，正芒寒南极，色映三台。\n明光殿北屏门，记御笔亲题名姓来。\n看河东召入，韩侯归觐，通班玉笋。\n稳上鸾台。\n作汉元功，继唐八叶，绿鬓依然昼绣回。\n安排了，待秋风先看，双桂联魁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18809, '沁园春', '陈士豪', '把酒西湖，问梅一笑，为谁试花。\n有淡庵人品，精忠许国，文昌地位，清白传家。\n鸾检封芝，麟符剖竹，立马嘶风催戍瓜。\n从今好，听夜郎江上，谯鼓喧。\n雌堂玉暖吴娃。\n向燕寝香中早放衙。\n但一麾十里，风清画戟，五溪六诏、云拥高牙。\n褒玺疏荣，锋车趣召，万寿杯中色翠霞。\n何须更，问武陵玉屑，勾漏丹砂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18810, '沁园春', '赵通判', '贺白文章，英卫规模，簪缨世家。\n更襟怀，芳润光风齐月，笔端奇伟，春藻天葩。\n课最严城，升班清禁，蔽芾棠阴人竞夸。\n争知道，富恩波衮衮，万顷无涯。\n清辉庭桂方花。\n映潋滟仙杯浮紫霞。\n庆云龙风虎，明良际会，鸿动骏业，重叠辉华。\n寿挹南峰，福迎庐水，未羡还丹九转砂。\n从此去，看腰黄眼赤，迤逦堤沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18811, '念奴娇', '赵汝恂', '金塘瑞溢，爱琉璃十顷，风漪摇碧。\n玉女三千擎翠盖，簇拥芙蓉仙伯。\n鸾鹤回翔，龙蛇飞动，醉墨挥仙笔。\n磨崖书寿，分明知是今日。\n应为今日生申，银钩照坐，光满图书壁。\n竹马儿童传好语，小住湖山开国。\n玉玺成文，金莲赐封，剑履登玄石。\n丹砂九转，功成依旧头黑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18812, '贺新凉・贺新郎', '石麟', '一骑飞来速。\n报平山、将颁凤检，宠分符竹。\n自是平淮勋名在，姓字屏风纪录。\n正欲革、潢池风俗。\n古括久思贤太守，待东山、一起苍生福。\n唐李段，追芳躅。\n横舟竹下凭青鹿。\n庆生朝、称觞蔼蔼，履珠簪玉。\n争奈回溪民望切，计日带牛佩犊。\n便合早、秣驺脂毂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18813, '金缕词・贺新郎', '石麟', '欲上南楼寿。\n记当年、祥占玉燕。\n一阳生候。\n今数书云犹七日，宫线未添刺绣。\n便草就、寿词盈袖。\n合捧金荷称鹤算，想华堂、剩醉眉春酒。\n惭斐句，为觞侑。\n功名八稚年方少。\n自归来、陶庐蒋径，菊松为友。\n轩筑易安栽花药，不坠家声五柳。\n况满砌、芝兰争秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18814, '水调歌头', '石麟', '九叶仙茅秀，旬浃一阳生。\n中山瑞气和暖，融作玉壶春。\n昨夜洪临跨鹤，翌早绿华骖凤，今日岳生申。\n须信神仙侣，引从降蓬瀛。\n文中虎，寿中鹤，酒中鲸。\n一门盛事相继，桥梓奋鹏程。\n应羡华堂燕处，许大规摹涵养，大器晚方成。\n醒後宫花句，伫看赋琼林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18815, '鹧鸪天', '石麟', '欲寿中山不老仙。\n寿词更拟办千篇。\n九日秀尧阶地，五色云祥鲁观天。\n吟逸老，醉逃禅。\n香传丹桂子孙贤。\n莫言大器韬藏久，犹是梁魁擢第年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18816, '水调歌头', '石麟', '日暖唐宫绣，云绚鲁台观。\n九叶仙茅方茂，瑞气霭中山。\n逸老堂前戏彩，新抱玄孙弥月，红字写眉间。\n八十庆公寿，添撇更成千。\n寿中星，人中杰，酒中仙。\n功名富贵，事业分付子孙贤。\n赢得濠梁真乐，剩有陶园佳趣，杖屦日安闲。\n第恐非熊兆，好事逼新年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18817, '满江红', '黄通判', '太守风流，管领尽、十分春色。\n开藩了、万花妆就，舒长化国。\n太白方观宫锦样，老人又现端门侧。\n听螺州、千里沸观声，春无极。\n龙种贵，蟾宫客。\n熊轼彦，鱼书直。\n更精神天赋，寒光停碧。\n宝篆定膺铜狄数，金樽好按梁州拍。\n待予环、赤映貂蝉，头方黑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18818, '念奴娇', '高子芳', '葱葱佳气，人都道、今日垂弧令旦。\n怪得欢声如鼎沸，准拟华堂开宴。\n三虎容仪，二乔态度，争捧金杯劝。\n瑶池王母，何妨引领仙眷。\n况有道骨仙风，灵丹秘决，钟鼎何心恋。\n却笑玉阶轩冕客，难脱功名羁绊。\n萧散陶篱，徜徉裴野，风月堪为伴。\n拳拳祝颂，寿龄期等龟算。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18819, '菩萨蛮', '高子芳', '去年曾祝夫人寿。\n今岁也又还依旧。\n鬓绿与颜朱。\n神仙想不如。\n骨相真难老。\n疑是居蓬岛。\n那更舞霓裳。\n笙歌溢画堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18820, '沁园春', '萧仲', '笑问鸥盟，所不同心，有如大江。\n念渊明漫仕，虽轻斗粟，弦歌有得，难慕柴桑。\n相业流芳，元枢新躅，拈作先生一瓣香。\n长生酒，仗西风桂子，吹到河阳。\n湘江。\n笑绾铜章。\n便好筑绵州六一堂。\n看千年辽鹤，重归故里，一般明月，又上潇湘。\n橐紫翻荷，官黄书诏，不待阴成蔽芾棠。\n中书考，更侯封国，汤沐宁乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18821, '洞仙歌', '熊德修', '洪崖仙裔，接武浮丘袂。\n佩玉长裾下尘世。\n东寻山水，独抱一琴来锦里。\n不犯人间宫祉。\n城山堂宇静，百丈楼高，湖海元龙浩然气。\n初度启初筵，昼永堂垂，笙鹤铿、轰出云际。\n问雅乐、何时献三雍，待汉殿明年，日长风细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18822, '满江红', '范飞', '律转黄钟，尧尚、零星一叶。\n人尽道、当年此日，诞生豪杰。\n我是君家门下士，三年屡献阳春雪。\n更此行、骑鹤上扬州，恩稠叠。\n君有子，文章伯。\n君有女，夸才色。\n更风流酝藉，东床佳客。\n胥祝长生儿祝寿，玉杯举罢金杯接。\n愿年年、长醉腊前梅，梅梢月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18823, '沁园春', '程和仲', '呼伯雅来，满进松精，致寿于公。\n况富矣锦囊，吟边得句，森然武库，书里称雄。\n亭长新封，亩宫雅趣，一笑侯王名位穹。\n闲官守，任平章批抹，明月清风。\n年年申庆桑蓬。\n幸至节今晨恰又逢。\n想霭霭其祥，瑞云兆，绵绵之算，线日增红。\n一段文章，三千功行，名在长生宝中。\n人间窄，待骖鸾驾鹤，上祝融峰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18824, '贺新郎', '咏槐', '绿长阶九。\n近黄锺、薰晴爱日，渐添宫绣。\n乾鹊檐头声声喜，催与东屏祝寿。\n怪一点、星明南斗。\n玉燕当年储瑞气，记垂弧、共醉蓬莱酒。\n无杰语，为觞侑。\n英风耿耿拿云手。\n向青春、蟾宫已步，桂香盈袖。\n却要诗书成曲，酝酿锦心绣口。\n待匣里、青萍雷吼。\n今日功名乘机会，笑谈间、首入英雄彀。\n看父子，继蓝绶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18825, '渡江云', '陈梦协', '瑞云浓，缥缈弦月当庭，天香满院。\n玉女传言，把真珠帘卷。\n拥鹊桥仙，引江城子，醉蓬莱宴。\n吹紫玉箫，唱黄金缕，按拍声声慢。\n昼锦堂前，倾杯为寿，祝快活年，应天长远。\n喜似娘儿，解称人心愿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18826, '鹧鸪天', '刘清之', '柳色青青罩翠烟。\n花光灼灼映临川。\n欲知窈窕呈祥日，恰近清明淑景天。\n浮瑞霭，庆真仙。\n不须男女祝椿年。\n异时早约西王母，剩折蟠桃荐寿筵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18827, '菩萨蛮', '王绍', '天正朔旦开新历。\n吾家伯父长生日。\n兰玉傍庭阶。\n称觞特地来。\n後年逢七十。\n今岁瞻南极。\n南极寿星宫。\n分明矍铄翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18828, '清平乐', '程节斋', '吾家三母。\n先後相为寿。\n管领诸郎尽明秀。\n都是婺女星宿。\n华筵今日居先。\n适逾甲子周天。\n敬以庄椿为祝，举觞我愿年年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18829, '木兰花・玉楼春', '程节斋', '瑶池开宴後，问甚处、赋蟠桃。\n有砌底芝兰，涧边苹藻，淑德方高。\n闺中秀、林下气，是寻常空委蓬蒿。\n相映鱼轩黄绶，行膺鸾锦金罗。\n自惭半子误恩多。\n所祝意如何。\n愿台星旁映，寿星齐照，乐自陶陶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18830, '沁园春', '程节斋', '彼两髦，未几见兮，突而弁兮。\n记昔年犀玉，奇资秀质，今朝簪佩，丰颊修眉。\n满面春风，一团和气，发露胸中书与诗。\n人都羡，是君家驹子，天上麟儿。\n画堂人物熙熙。\n会簪履雍容举庆宜。\n看筮日礼宾，陈锺列俎，三加致祝，一献成仪。\n绿鬓貂蝉，朱颜豸角，早有君臣庆会期。\n荣冠带，看绶悬若若，印佩累累。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18831, '水调歌头', '程节斋', '秋色正潇洒，佳气夜充闾。\n人传好语，君家门左正垂弧。\n毕万从来有後，释氏果然抱送，丹穴凤生雏。\n未作汤饼客，先写弄獐书。\n参军妇，贤相敌，古来无。\n锺奇毓秀，应是积善庆之馀。\n想见珠庭玉角，表表出群英物，我已预知渠。\n他日容相顾，啼看定何如。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18832, '沁园春', '程节斋', '自古人言，庆在子孙，端有由来。\n看长庚孕李，昴星佐汉，福从人召，瑞自天开。\n曾忆当年，乃翁熊梦，岂在区区春祀。\n祗凭个、仁心积累，厚德栽培。\n天工信巧安排。\n试说与君当一笑哉。\n记年时此际，嗷嗷万口，俾之粒食，活及婴孩。\n岁始星周，事还好在，故遣麒麟出此胎。\n何须问，是兴宗必矣，业广基恢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18833, '沁园春', '程节斋', '三百篇诗，三十六篇，以祈寿言。\n惟上天所佑，锡之君子，中心岂弟，盖有仁存。\n允矣我公，韦平世胄，学问于兹有本原。\n临民处，看精神秋彻，气宇春温。\n由来淑景中分。\n第一日桑弧挂左门。\n是赋受不凡，仁而宜寿，笑渠谄子，徒费辞繁。\n命匪在天，算非由数，我只把公心地论。\n从今去，管亟登槐棘，福遍乾坤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18834, '木兰花慢', '程节斋', '西风吹昨梦，直飞上、广寒宫。\n见绛节霓旌，常娥延伫，玉立双童。\n殷勤桂枝分付，却为言、当日有仙翁。\n谪堕人间几载，只今恰挂桑蓬。\n佳音未返碧楼空。\n青鸟耗难通。\n闻洞府已成，南州占断，皓月光风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18835, '水调歌・水调', '程节斋', '养气兼养勇，岂不丈夫哉。\n何人刚欲斗力，谩向此间来。\n莫论施身文绣，看取兼人胆谅，胸次尽嵬嵬。\n独步登坛後，诸子尽舆台。\n笑渠侬，身贲育，伎婴孩。\n虚娇自恃，未识金德木鸡才。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18836, '水调歌・水调', '程节斋', '都尉部千弩，旧事汉材官。\n连拳一臂三石，夜半破阴山。\n曾使中有扪足，造次摧坚挫锐，分白辱宠涓。\n省括一机耳，人未识黄间。\n锦为标，虽有戏，技为难。\n疾飞两箭，兄弟齐夺姓名还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18837, '步蟾宫', '张仲殊', '笙歌喜庆争催晓。\n篆烟舞、龙鸾缥缈。\n香罗上、不画寿仙人，献一段、长生寿草。\n一心一意同欢笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18838, '好事近', '吴氏2', '腊近渐知春，已有早梅堪折。\n况是诞辰佳宴，拥笙簧罗列。\n玉杯休惜十分斟，金炉更频。\n连理愿同千岁。\n看蟠桃重结。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18839, '贺新凉・贺新郎', '吴编修', '出处男儿事。\n甚从前、说著渊明，放高头地。\n点检柴桑无剩粟，未肯低头为米。\n算此事、非难非易。\n三十年间如昨日，秀才瞒、撰到专城贵。\n饱共暖，已不翅。\n旁人问我归耶未。\n数痴年、平头六十，更须三岁。\n把似如今高一著，更好闻鸡禁市。\n总不似、长伸脚睡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18840, '八声甘州', '吴编修', '系酒船、夜入古江楼，浑莫辨西东。\n叹从前眼底，一丁不识，四海曾空。\n老去休休莫莫，谁识旧元龙。\n尚解被襟去，赋大王雄。\n回首演仙高处，问赤松无恙，舍子何从。\n便不然学稼，犹有相牛翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18841, '摸鱼儿', '吴编修', '予何人、此何时节，驾言我欲行志。\n青原煮豆然萁後，谁豢龙蛇赤子。\n心为碎。\n宽底是、翻疑又怕严底是。\n吾方左计。\n冷眼别人看，畏首畏尾，身复尚馀几。\n陶元亮，自古真奇男子。\n督邮尚若人耳。\n秋风一曲柴桑路，新秫炊香正美。\n黄鹄起。\n见说道、山光潭影皆欢喜。\n晴窗静倚。\n还我向来高，仙人羽客，别有一天地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18842, '念奴娇', '赵龙图', '吾今老矣。\n好归来、了取青山活计。\n甲子一周馀半纪，谙尽人间物理。\n婚嫁随缘，田舍粗给，知足生惭愧。\n心田安逸，自然绰有馀地。\n还是初度来临，葛巾野服，不减貂蝉贵。\n门外风波烟浪恶，我已收心无累。\n弟劝兄酬，儿歌女舞，落得醺醺醉。\n满堂一笑，大家百二十岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18843, '沁园春', '竹林亭长', '自笑生身，历事以来，垂六十年。\n今浮湛闾里，半非识面，交游朋友，各色华颠。\n富贵不来，少年已去，空见悠悠岁月迁。\n虽然是，只壮心一点，犹自依然。\n新阳又长天边。\n人指似山间诗酒仙。\n算胸次崔嵬，不胜百，笔端枯槁，难足千篇。\n隐几杖藜，相耕听诵，聊看诸郎相後先。\n馀何□，但读书煮茗，日晏高眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18844, '满庭芳', '杨樵云', '只道空烟，又疑流水，依依却是行云。\n了然相对，又是梦纷纭。\n半面春风图画，黄金在、难铸昭君。\n溪桥断，梅花晴雪，端的白三分。\n真真。\n难唤醒，三年抽藕，织得榴裙。\n甚徘徊窥镜，交翼鸾文。\n一片飞花来去，并刀快、翦取晴纹。\n无情处，分明著眼，强半带春醺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18845, '水龙吟', '杨樵云', '多情不在分明，绣窗日日花阴午。\n依依云絮，溶溶香雪，觑他寻路。\n一滴东风，怎生消得，翠苞红栩。\n被疏钟敲断，流莺唤起，但长记、弓弯舞。\n定是相思入骨，到如今、月痕同醉。\n教人枉了，若还真个，匆匆如此。\n全未惺松，缬纹生眼，胡床犹据。\n算从前、总是无凭，待说与、如何寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18846, '小楼连苑・水龙吟', '杨樵云', '一枝斜堕墙腰，向人颤袅如相媚。\n是谁翦取，断云零玉，轻轻妆缀。\n不是幽人，如何能到，水边沙际。\n又匆匆过了，春风半面，尽长把、重门闭。\n只管相思成梦，道无情、又关乡意。\n苍苔半亩，如今已是，鹿胎田地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18847, '木兰花慢', '刘应雄', '梅妆堪点额，觉残雪、未全消。\n忽春递南枝，小窗明透，渐褪寒骄。\n天公似怜人意，便挽回、和气做元宵。\n太守公家事了，何妨银烛高烧。\n旋开铁锁粲星桥。\n快灯市、客相邀。\n且同乐时平，唱弹弦索，对舞纤腰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18848, '锁窗寒・琐寒窗', '曾隶', '绣额云横，银钩月小，绿杨庭院。\n疏明满幅，永昼未高卷。\n爱空纹、巧匀曲波，弄晴日色花阴转。\n任筛金影碎，轻敲檐玉，碍双飞燕。\n凝见。\n窗留篆影，六曲雕阑，翠深绛浅。\n香风暗度，不隔娇松莺啭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18849, '解连环', '黄水村', '凤楼倚倦。\n正海棠睡足，锦香衾软。\n似不似、雾阁云窗，拥绝妙灵君，霎时曾见。\n屏里吴山，又依约、兽环半掩。\n到教人觑了，非假非真，一种春怨。\n游丝落花满院。\n料当时、错怪杏梁归燕。\n记得栩栩多情，似蝴蝶飞来，扑翻轻扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18850, '霓裳中序第一', '姜个翁', '园林罢组织。\n树树东风翠云滴。\n草满旧家行迹。\n时听得声声，晓莺如觅。\n愁红半湿。\n煞憔悴、墙根堪惜。\n可念我、飘零如此，一地送岑寂。\n龟石。\n当年第一。\n也似老、人间风日。\n馀葩选甚颜色。\n羞拈江南，断肠词笔。\n留春浑未得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18851, '满江红', '彭芳远', '愁满关山，又吹得、芦花雪深。\n西楼外、天低水涌，龙挟秋吟。\n回首人间无此曲，数峰江上落馀音。\n似断云、飞絮两悠悠，何处寻。\n江南路，晴又阴，声韵改，泪盈襟。\n自中郎去後，羽泛商沈。\n牛背斜阳添别恨，鸾胶秋月续琴心。\n待醉骑、黄鹤度苍寒，霜满林。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18852, '满江红', '戴山隐', '醉倚江楼，长空外、行云遥驻。\n甚凄凉孤吹，含商引羽。\n薄夜冷侵沙浦雁，老龙吟彻寒潭雨。\n蓦凉飚、一阵卷潮来，惊飞去。\n重欲听，知何处。\n谁为我，胡床据。\n谩寻寻觅觅，凝情如许。\n旧日山阳空有恨，杏花明月今谁赋。\n恐凭阑、人有爱梅心，空愁伫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18853, '摸鱼儿', '李裕翁', '计江南、许多风景，繁华只在晴昼。\n些儿淡沲冲融意，到处粘花著柳。\n疏雨後。\n更艳艳绵绵，泼眼浓如酒。\n飞浮宇宙。\n但借日浮香，随烟著物，巧笔画难就。\n惆怅处，曾记苏堤携手。\n十年惊觉回首。\n苍埃霁景成阴晦，湖水湖烟依旧。\n凝望久。\n问燕燕莺莺，识此年华否。\n长门别有。\n脉脉断肠人，柔情荡漾，长是为伊瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18854, '忆旧游', '龙端是', '问南楼月色，十载相疏，何似今宵。\n旧雨菰蒲国，想波光雁影，远撼沅潇。\n拟苏堤上杨柳，烟碧为谁摇。\n叹庾扇尘深，胡床梦浅，翠减香销。\n迢迢。\n谩回首，记酹酒江山，曾共金镳。\n暮色沈西垒，几狂朋来往，舟叶招招。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18855, '齐天乐', '萧东父', '扇鸾收影惊秋晚，梧桐又供疏雨。\n翠箔凉多，绣囊香减，陡觉簟冰如许。\n温存谁与。\n更禁得荒苔，露蛩相诉。\n恨结愁萦，风刀难翦几千缕。\n闲思前事易远，怅旧欢无据，月堕湘浦。\n软玉分，腻云侵枕，犹忆喷兰低语。\n如今最苦。\n甚怕见灯昏，梦游间阻。\n怨杀娇痴，绿窗还嚏否。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18856, '昭君怨', '王从叔', '门外春风几度。\n马上行人何处。\n休更卷朱帘。\n草连天。\n立尽海棠花月。\n飞到荼シ香雪。\n莫怪梦难成。\n梦无凭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18857, '阮郎归', '王从叔', '风中柳絮水中萍。\n聚散两无情。\n斜阳路上短长亭。\n今朝第几程。\n何限事，可怜生。\n能消几度春。\n别时言语总伤心。\n何曾一字真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18858, '南柯子・南歌子', '王从叔', '碧树留云湿，青山似笠低。\n鹧鸪啼罢竹鸡啼。\n不晓天天何意、要梅肥。\n昨日穿新葛，今朝御夹衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18859, '浣溪沙', '王从叔', '水月精神玉雪胎。\n乾坤清气化生来。\n断桥流水领春回。\n昨夜醉眠苔上石，天香冉冉下瑶台。\n起来窗外见花开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18860, '秋蕊香', '王从叔', '薄薄罗衣乍暖，红入酒痕潮面。\n絮花舞倦带娇眼。\n昨夜平堤水浅。\n故人信断风筝线。\n误归燕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18861, '凤凰台上忆吹箫', '吴元可', '更不成愁，何曾是醉，豆花雨後轻阴。\n似此心情自可，多了闲吟。\n秋在西楼西畔，秋较浅、不似情深。\n夜来月，为谁瘦小，尘镜羞临。\n弹筝，旧家伴侣，记雁啼秋水，下指成音。\n听未稳、当时自误，又况如今。\n那是柔肠易断，人间事、独此难禁。\n雕笼近，数声别似春禽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18862, '杨州慢', '吴元可', '露叶犹青，岩花迟动，幽幽未似秋阴。\n似梅风带溽，吹度长林。\n记当日、西廊共月，小屏轻扇，人语凉深。\n对清觞，醉笑醒颦，何似如今。\n临高欲赋，甚年来、渐减狂心。\n为谁倚多才，难凭易感，早付销沈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18863, '采桑子', '吴元可', '江南二月春深浅，芳草青时，燕子来迟。\n翦翦轻寒不满衣。\n清宵欲寐还无寐，顾影颦眉。\n整带心思。\n一样东风两样吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18864, '浪淘沙', '吴元可', '浅约未曾来。\n一迳苍苔。\n缃桃无数棘花开。\n怪得闭门机杼静，挑菜初回。\n幽树鸟声催。\n欲去徘徊。\n□□别久易相猜。\n幽绪一晴无处著，戏打青梅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18865, '永遇乐', '李太古', '玉砌标鲜，雪园风致，似曾相识。\n蝉锦霞香，乌丝云湿，吹渴蟾蜍滴。\n青青白白，关关滑滑，寒损铢衣狂客。\n尽声声、不如归去，归也怎生归得。\n含桃红小，香芹翠软，惆怅宜城山色。\n百折浮岚，几湾流水，那一些儿直。\n落花情味，露花魂梦，蒲花消息。\n抚纤眉，织乌西下，为君凝碧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18866, '恋绣衾', '李太古', '桔花风信满院香。\n摘青梅、犹自怕尝。\n向绿密、红疏处，喜相逢、飞下一双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18867, '南歌子', '李太古', '月下秦淮海，花前晏小山。\n二仙仙去几时还。\n留得月魂花魄、在人间。\n河汉流旌节，天风袅环。\n满空香雾湿云鬟。\n何处一声横笛、杏花寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18868, '虞美人', '李太古', '西风海色秋无际。\n双泪如铅水。\n白羊成队梦初平。\n挂杖敲云、云外晓鸿惊。\n小琼闲抱银筝笑。\n问有芳卿否。\n玉书分付莫开封。\n明日人间临水、拾流红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18869, '卜算子', '李太古', '尽道是伤春，不似悲秋怨。\n门外分明见远山，人不见，空肠断。\n朝来一霎晴，薄暮西风远。\n却忆黄花小雨声，误落下、三四点。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18870, '西湖月', '黄子行', '湖光冷浸玻璃，荡一饷薰风，小舟如叶。\n藕花十丈，云梳雾洗，翠娇红怯。\n壶觞围坐处，正酒吹波红映颊。\n尚记得、玉臂生凉，不放汗香轻浃。\n人小摘墙榴，为碎掐猩红，细认裙褶。\n旧游如梦，新愁似织，泪珠盈睫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18871, '西湖月', '黄子行', '初弦月挂林梢，又一番西园，探梅消息。\n粉墙朱户，苔枝露蕊，淡匀轻饰。\n玉儿应有恨，为怅望东昏相记忆。\n便解、飞入云阶，长伴此花倾国。\n诗腰瘦损刘郎，记立马攀条，倚阑横笛。\n少年风味，拈花弄蕊，爱香怜色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18872, '贺新郎', '黄子行', '开遍寒梅萼。\n正东皇、排酥砌玉，幻成楼阁。\n十万琼琚仙女队，来趁春光游乐。\n向醉里、玉簪轻落。\n零乱不知何处去，甚人间、一夜东风恶。\n吹起在，画檐角。\n参差向晓森如削。\n似吴姬、妆残粉指，向人垂著。\n好似西园春笋瘦，红锦儿乍剥。\n且莫遣、儿童敲却。\n拟办羔儿香瓮酒，唤刘叉、来醉尊前约。\n吟好句，再描摸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18873, '满江红', '黄子行', '津鼓匆匆，犹记得、故人相送。\n春江上、鸟啼花影，马嘶香。\n情逐阳关金缕断，泪和杨柳春丝重。\n算别来、几度月明时，相思梦。\n山万垒，愁眉耸。\n春一点，归心动。\n问风俦月侣，有谁游从。\n百里家山明日到，一尊芳酒今宵共。\n任楼头、吹尽五更风，梅花弄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18874, '花心动', '黄子行', '谁倚青楼，把谪仙长笛，数声吹裂。\n一片乍零，千点还飞，正是雨晴时节。\n水晶帘外东风起，卷不尽、满庭香雪，画阑小，斜铺乱，翠苔成缬。\n袅袅馀香未歇。\n空怅望音尘，两眉愁切。\n翠袖泪乾，粉额妆寒，此恨有谁同说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18875, '小重山', '黄子行', '一点斜阳红欲滴。\n白鸥飞不尽，楚天碧。\n渔歌声断晚风急。\n搅芦花，飞雪满林湿。\n孤馆百忧集。\n家山千里远，梦难觅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18876, '齐天乐', '龙紫蓬', '雨帘云栋重寻处，青红半空飞去。\n槛影侵鸥，檐光送雁，摇荡秋容千里。\n歌珠舞翠。\n怎禁得无情，一江流水。\n可是西山，半眉新绿向人觑。\n千年留下剩赏，尽登临无限，须付才思。\n坏堞闲愁，危樯往恨，欲拍阑干无路。\n新碑旧记。\n更今古匆匆，一番兴废。\n立尽斜阳，共谁评半语。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18877, '渡江云', '萧允之', '蔷薇开欲谢，峭寒渐少，轩槛俯晴沙。\n先来愁未了，又听一声，新阕落渔家。\n徘徊伫立，似玉笛、三弄昭华。\n春昼长、暗怀谁写，戏墨乱翻鸦。\n吁嗟。\n诗情犹隽，酒兴偏豪，记南楼月下。\n曾共乐、沈烟绮席，烛影窗纱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18878, '满江红', '萧允之', '冷逼疏帘，浑不似、今春寂寞。\n风雨横，赏心欢事，总如云薄。\n柳眼花须空点缀，莺情蝶思应萧索。\n但绕庭、流水碧潺潺，车音邈。\n怀往事，孤素约。\n酒未饮，愁先觉。\n甚中年滋味，共谁商略。\n芳草易添闲客恨，垂杨难系行人脚。\n谩几回、吟遍夕阳红，阑干角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18879, '琐窗寒', '萧允之', '细雨收尘，轻寒弄日，柳丝掠道。\n桃边杏处，犹记玉骢曾到。\n对东风、回首旧游，香销艳歇无音耗。\n怅佳人、有约难来，绿遍满庭芳草。\n愁抱。\n沈吟久，翠珥金钿，为何人好。\n回文细字，尘暗当年纤缟。\n倚阑干、斜阳又西，欢期易失春易老。\n待何时、再觅珍丛，共把清尊倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18880, '蝶恋花', '萧允之', '十幅归帆风力满。\n记得来时，买酒朱桥畔。\n远树平芜空目断。\n乱山惟见斜阳半。\n谁把新声翻玉管。\n吹过沧洲，多少伤春怨。\n已是客怀如絮乱。\n画楼人更回头看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18881, '虞美人', '萧允之', '朱楼曾记回娇盼。\n满坐春风转。\n红潮生面酒微醺。\n一曲清歌留往、半窗云。\n大都咫尺无消息。\n望断青鸾翼。\n夜长香短烛花红。\n多少思量只在、雨声中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18882, '点绛唇', '萧允之', '花径相逢，眼期心诺情如昨。\n怕人疑著。\n佯弄秋千索。\n知有而今，何似留初莫。\n愁难托。\n雨铃风铎。\n梦断灯花落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18883, '洞仙歌', '段宏章', '一庭晴雪，了东风孤注。\n睡起浓香占窗户。\n对翠蛟盘雨，白凤迎风，知谁见、愁与飞红流处。\n想飞琼弄玉，共驾苍烟，欲向人间挽春住。\n清泪满檀心，如此江山，都付与、斜阳杜宇。\n是曾约梅花带春来，又自共梨花，送春归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18884, '满庭芳', '刘贵翁', '宫鸟西飞，杨花北去，春风飘向伊谁。\n盈盈小小，轻薄不堪肥。\n天付风流到骨，消不尽、流落青池。\n谁知道，踏歌朝暮，痴绝待渠归。\n，春似酒，日痕生绀，裙色明漪。\n笑东家西沼，到处依依。\n同是东风种得，独无据，飘泊年时。\n青梅落，水光帘影，小翠立横枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18885, '水龙吟', '黄霁宇', '丽华一握青丝，金珠粟粟香环里。\n春窥绮阁，新妆风舞，铢衣如碎。\n翠凤苍虬，骑来下界，蝶惊蜂避。\n甚三生富贵，垂垂晓露，犹凝满身珠翠。\n谁共那人结发，问何时、蹇修为理。\n对花一笑，香茸易翦，碎金难缀。\n半点芳心，乱愁如织，缕丝传意。\n倩东皇、拂拭新条，更与作、来生计。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18886, '齐天乐', '刘天迪', '瑞麟香软飞瑶席，吟仙笑陪欢宴。\n桐影吹香，梅阴弄碧，一味微凉堪荐。\n停杯缓劝。\n记罗帕求诗，琵琶遮面。\n十载扬州，梦回前事楚云远。\n人生总是逆旅，但相逢一笑，如此何限。\n采石宫袍，沈香醉笔，何似轻衫小扇。\n流年暗换。\n甚新雨情怀，故园心眼。\n明日西江，斜阳帆影转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18887, '一萼红', '刘天迪', '拥孤衾，正朔风凄紧，毡帐夜生寒。\n春梦无凭，秋期又误，迢递烟水云山。\n断肠处、黄茅瘴雨，恨骢马、憔悴只空还。\n揉翠盟孤，啼红怨切，暗老朱颜。\n堪叹扬州十里，甚倡条冶叶，不省春残。\n蔡琰悲笳，昭君怨曲，何预当日悲欢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18888, '虞美人', '刘天迪', '子规解劝春归去。\n春亦无心住。\n江南风景正堪怜。\n到得而今不去、待何年。\n无端往事萦心曲。\n两鬓先惊绿。\n蔷薇花发望春归。\n谢了蔷薇、又见楝花飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18889, '蝶恋花', '刘天迪', '日暮杨花飞乱雪。\n宝镜慵拈，强整双鸳结。\n烧罢夜香愁万叠。\n穿花暗避阶前月。\n凤尾罗衾寒尚怯，却悔当时，容易成分别。\n闷对枕鸾谁共说。\n柔情一点蔷薇血。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18890, '凤栖梧・蝶恋花', '刘天迪', '一翦晴波娇欲溜。\n绿怨红愁，长为春风瘦。\n舞罢金杯眉黛皱。\n背人倦倚晴窗绣。\n脸晕潮生微带酒。\n催唱新词，不应频摇手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18891, '点绛唇', '刘天迪', '一笑相逢，依稀似是桃根旧。\n娇波频溜。\n悄可灵犀透。\n扶过危桥，轻引纤纤手。\n频回首。\n何时还又。\n微月黄昏後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18892, '满江红', '张半湖', '新绿池塘，一两点、荷花微雨。\n人正静，桐阴竹影，半侵庭户。\n枕未圆蝴蝶梦，隔窗时听幽禽语。\n卷沙帏、随意理琴丝，黄金缕。\n鲛绡扇，轻轻举。\n龙涎饼，微微炷。\n向水晶宫里，坐消袢暑。\n剥啄谁敲棋子响，莺儿林里惊飞去。\n最好是、活水瀹新茶，醒春醑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18893, '扫花游・扫地游', '张半湖', '柳丝曳绿，正豆雨初晴，水天朱夏。\n石榴绽也。\n看猩红万点，倚亭榭。\n锁闼深中，料想酒阑歌罢。\n日将下。\n是那处藕花，香胜沈麝。\n窗外风竹打。\n似戛玉敲金，送声潇洒。\n共观古画。\n唤石鼎烹茶，细商幽话。\n宝鸭烟消，天外新蟾低挂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18894, '念奴娇', '刘景翔', '甚情幻化，似流酥围暖，酣春娇寐。\n不数锦篝烘古篆，沁入屏山沈水。\n笑吐丁香，紫绡衬粉，房列还同蒂。\n翠球移影，媚人清晓风细。\n依约玉骨盈盈，小春暖逗，开到灯宵际。\n疑是九华仙梦冷，误落人间游戏。\n比雪情多，评梅香浅。\n三白还堪瑞。\n尘缘洗尽，醒来还又葱翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18895, '小重山', '刘景翔', '山翠晴岚曲曲偎。\n红香浮玉醉窝颓。\n不烦人筑避风台。\n潇湘路，随意自徘徊。\n春倦怕频催。\n琵琶私语近、问谁来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18896, '玉楼春', '刘景翔', '可怜又误江南景。\n雨腻风喧愁入暝。\n依稀碧玉水边魂，憔悴绿珠楼外影。\n点点随人飞远近。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18897, '如梦令', '刘景翔', '独立荷汀烟渚。\n一霎锦云香雨。\n似为我无情，惊起鸳鸯飞去。\n飞去。\n飞去。\n却在绿杨深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18898, '摸鱼儿', '周伯阳', '又匆匆、月鞭露镫，梅花江上归路。\n海图破碎来时线，何似彩衣低舞。\n风雪暮。\n正望断青山，一发云横处。\n浩歌独举。\n便想见迎门，牵衣儿女，总是旧眉妩。\n阳关曲，挥洒紫薇花露。\n妙音清远高古。\n经寒杨柳休轻折，摇动一溪霜雾。\n邯郸步。\n笑布袜青鞋，去住知何许。\n汀鸥沙鹭。\n若问我重来，明年有约，今日是前度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18899, '春从天上来', '周伯阳', '浩荡青冥。\n正凉露如洗，万里虚明。\n鼓角悲健，秋入重城。\n彷佛石上三生。\n指蓬莱云路，渺何许、月冷风清。\n倚南楼、一声长笛，几点残星。\n西风旧年有约，听候蛩语夜，客里心惊。\n红树山深，翠苔门掩，想见露草疏萤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18900, '尉迟杯', '尹公远', '冰弦语。\n在竹树、院落深深处。\n当年野草闲花，何许浮云飞絮。\n征鸿止止，纵汗漫、游人远回顾。\n迟琼楼、五色帘开，唤醒玄鹤飞舞。\n何事梦断湖山，尚九里松声，八月潮怒。\n三十年馀池台泪，应不为、花奴羯鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18901, '齐天乐', '尹公远', '江湖千里秋风客，翩然白云黄鹄。\n石鼎烟霏，篆书红湿，随处菊香泉绿。\n幅巾野服。\n尽扫叶开门，抱琴听瀑。\n何事蓬壶，归来独待海涛陆。\n卢鸿旧时隐处，想斜阳草树，水榭云屋。\n麈尾玄玄，笔花语语，剪尽雨窗残烛。\n黄庭误读。\n且东老留诗，采和歌曲。\n後日重寻，洞天三十六。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18902, '摸鱼儿', '李天骥', '又何须、向明还灭，寒花点缀孤影。\n玉龙度海吹鱼浪，烟淡宝钗横鬓。\n斜又整。\n是虫滴骊珠、两两相交颈。\n夜长人静。\n恁玉果低抛，金钱暗卜，此意有谁领。\n欢娱事，料想凭伊先应。\n帕绡新泪独凝。\n银篦未忍轻挑下，只恐暗风吹烬。\n重记省。\n怕莫是、明朝有个青鸾信。\n怎知无定。\n算只解窥人，人孤影只，成瘦又成病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18903, '忆旧游', '刘应几', '记铜驼载酒，翠陌吹箫，曾听相呼。\n不尽离离意，觉柔肠如剪，立马踟蹰。\n人生似此苍鬓，禁得几声疏。\n想怨入秋深，愁随天远，满目平芜。\n音书未曾寄，正人在燕台，忘却回车。\n奈菰蒲旧地，山空木落，霜老泉枯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18904, '木兰花慢', '周孚先', '访梅江路远，喜春在、剑川湄。\n正雁碛云深，渔村笛晚，茸帽斜。\n旧游不堪回首，更文园、多病减腰围。\n惟有秋娘声价，风流仍似前时。\n依稀壁粉旧曾题。\n烟草半凄迷。\n叹单父台荒，黄公垆寂，难觅佳期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18905, '鹧鸪天', '周孚先', '曾唱阳关送客时。\n临岐借酒话分离。\n如今酒被多情苦，却唱阳关去别伊。\n欢会远，渺难期。\n黄垆门掩昼阴迟。\n青楼更有痴儿女，谩忆胡姬捧劝词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18906, '蝶恋花', '周孚先', '舟舣津亭何处树。\n晓起珑璁，回首迷烟雾。\n江上离人来又去。\n飘零只似风前絮。\n倦倚蓬窗谁共语。\n野草闲花，一一伤情绪。\n明日重来须记取。\n绿杨门巷深深处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18907, '念奴娇', '彭泰翁', '九华惊觉，又偷承雨露，羞匀春色。\n岸蓼汀苹成色界，未必天香人识。\n粉脂凝，霜销雾薄，娇颤浑无力。\n黄昏月掩，山城那更闲笛。\n应是未了尘缘，重来迟暮，草草西风客。\n莺燕无情庭院悄，愁满阑干苔积。\n宫锦尊前，霓裳月下，梦亦无消息。\n嫣然一笑，江南如此风日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18908, '忆旧游', '彭泰翁', '玉环扶浅醉，翠袖笼寒，香汗初融。\n昨夜残妆在，最难胜珠络，都沁铅红。\n朝云低护深约，蜂蝶不知踪。\n奈燕子情多，斜飞轻触，泪洒羞容。\n重逢。\n记前度，解翦烛调笙，踏月鸣骢。\n风入人间远，待尘缘洗尽，飞凌空。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18909, '拜星月慢', '彭泰翁', '雾觚棱，尘侵团扇，恨满哀弹倦理。\n控雨笼云，共闲情孤倚。\n敛娥黛、怕似流莺历历，惹得玉销琼碎。\n可惜阑干，但苔花沈穗。\n算天音、不入人间耳。\n何人谩、损青山泪。\n不是旧谱都忘，厌新腔娇脆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18910, '水龙吟', '曾允元', '日高深院无人，杨花扑帐春云暖。\n回文未就，停针不语，绣床倚遍。\n翠被笼香，绿鬟坠腻，伤春成怨。\n尽云山烟水，柔情一缕，又暗逐、金鞍远。\n鸾佩相逢甚处，似当年、刘郎仙苑。\n凭肩後约，画眉新巧，从来未惯。\n枕落钗声，帘开燕语，风流云散。\n甚依稀难记，人间天上，有缘重见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18911, '月下笛', '曾允元', '又老杨花，浮萍点点，一溪春色。\n闲寻旧迹。\n认溪头、浣纱碛。\n柔条折尽成轻别，向空外、瑶簪一掷。\n算无情更苦，莺巢暗叶，啼破幽寂。\n凝立。\n阑干侧。\n记露饮东园，联镳西陌。\n容销鬓减，相逢应自难识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18912, '齐天乐', '曾允元', '碧梧枝上占秋信，微闻雨声还惬。\n虹影分晴，云光透晚，残日依依团。\n阑干一霎。\n又长笛归舟，乱鸦荒堞。\n两鬓西风，有人心事到红叶。\n娇莲相对欲语，奈莲茎有刺，愁不成折。\n天上欢期，人间巧意，今夜明河如雪。\n新宽带结。\n想宝篆频温，翠奁低揭。\n雾湿云鬟，浅妆深拜月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18913, '点绛唇', '曾允元', '一夜东风，枕边吹散愁多少。\n数声啼鸟。\n梦转纱窗晓。\n来是春初，去是春将老。\n长亭道。\n一般芳草。\n只有归时好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18914, '沁园春', '朱元夫', '心上浮香，轩前度影，约久传梅。\n奈月意风情，枝南枝北，云婚雨嫁，年去年来。\n几望溪桥，屡肥芳信，历尽冰霜春自回。\n朝来报，报梢头儿女，并蒂花开。\n佩环飞下妆台。\n喜今度佳期不用催。\n羡行李三千，金屏翠幄，仙姿第一，玉骨琼腮。\n雌蝶纷纷，雄蜂逐逐，争道工为使与媒。\n翁知麽，有西楼过雁，暗为徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18915, '壶中天・念奴娇', '朱元夫', '人生有酒，得闲处、便合开怀随意。\n况对寿、龟仙鹤舞，犹直壶天一醉。\n蚕麦江村，梅霖院落，立夏明朝是。\n樽前回首，去年四月十二。\n依旧洛里吟窝，华台书隐，心事无怀氏。\n偃鼠醯鸡空扰扰，海月天风谁寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18916, '沁园春', '邵桂子', '知是今年，一冬较暖，开遍梅花。\n有一朵妖娆，塘之东畔，东君爱惜，云幕低遮。\n小萼微红，香腮傅粉，把寿阳妆取自夸。\n谁知道，忽移来秀水，深处人家。\n清香扑透窗纱。\n渐仙李华无等差。\n这冰姿一样，玉颜双好，月明静夜，疏影横斜。\n传语曹林，须将止渴，结子今番早早些。\n梅自笑，嗔贺新郎曲，待拍红牙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18917, '贺新郎', '邵桂子', '新雨黄花路。\n看清江、旌旗千骑，使君东去。\n万里归来城头角，吹彻家山旧处。\n惜洲鹭、留君不驻。\n白发遗民壶觞语，笑浣花邻里来襦裤。\n夸见早，恨来暮。\n故人只在山中住。\n记年时、肠断相望，天风海雨。\n满鬓星星华发少，君鬓尚今青否。\n休夸说、神仙官府。\n玉笥平生清入梦，会有时、乘兴携吾侣。\n就君醉，为君舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18918, '满江红', '邵桂子', '离却京华，到这里、二千八百。\n穷醋大、齐齐整整，岂无贷揭。\n随地平章花与柳，为天评品风和月。\n只留得、一管钝毛锥，一丸墨。\n初不是，丝绵帛。\n又不是，茶盐铁。\n更有苏州破砚，兔园旧册。\n一领征衣半尘土，两头箬笠几风雪。\n问栏头、直得几多钱，从头说。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18919, '百字令・念奴娇', '邵桂子', '三年幕画，是小试相业，桐阴相谱。\n协暂拥容心似佛，春在螺山螺浦。\n白玉无瑕，黄扉倚重，一府中流柱。\n箫然锦满，扁舟明日归去。\n此去南北才名，看青云隐驾，玉阶徐步。\n共说荆州老长史，宰相须还他做。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18920, '贺新郎', '彭子翔', '一点阳春小。\n傍妆台、梅梢粉嫩，桃花红透。\n合卺樽前人笑语，银烛两行红补。\n云正暖、流苏香兽。\n金屋阿娇元共贮，待玄霜、杵就方成偶。\n□□□，□□□。\n西园扑蝶春风早。\n看浮花、浪蕊飞尽，娟娟闺秀。\n柳带菖蒲堪绾结，只绾同心未就。\n算今夜、心都同了。\n待阙鸳鸯情似海，锦衾温、说到鸡声晓。\n头白也，镇相守。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18921, '木兰花慢', '彭子翔', '仙家春不老，谁说到、牡丹休。\n算蛮柳樊樱，怎生了得，白傅风流。\n枝头。\n梅实好，奈绿阴、庭户不禁愁。\n幸有琴中凤语，能通镜里鸾求。\n锵。\n杂佩下瀛洲。\n宝紫烟浮。\n望兰情红盼，三生曾识，一见如羞。\n绸缪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18922, '千秋岁', '彭子翔', '重阳来未。\n谁领黄花意。\n斟玉醑，歌金缕。\n云山笼瑞彩，风月溶清气。\n北山顶，寿星一点光无际。\n六十今朝是。\n甲子从头起。\n堂堂去，千千岁。\n是非华表鹤，深浅蓬莱水。\n翁不管，年年先共黄花醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18923, '声声慢', '彭子翔', '萸房初荐，橙子新槎。\n菊松图下捧金荷。\n看翁将息，後生似、去年些。\n更眼前、稚子又多。\n鬓绿颜酡。\n对花醉、把花歌。\n熙宁安乐好行窝。\n佳辰虽异，翁此兴、不输他。\n更如何、欢喜也呵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18924, '临江仙', '彭子翔', '佛说波斯王此岁，衰颜羞见河流。\n翁今丹脸发光浮。\n毗卢金色界，烂熳菊花秋。\n七个明朝方九日，年年税在今朝。\n八千秋老又从头。\n明朝无尽在，蝴蝶不须愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18925, '暗香', '彭子翔', '停云望极。\n问秀溪何似，英溪风月。\n劫火灰飞，又见雕檐照寒碧。\n何事归来归去，似熙载、江南江北。\n还又向、殊乡初度。\n故乡人，却为客。\n是则。\n家咫尺。\n不是有、莼羹鲈堪忆。\n从心时节。\n消得山阴几双屐。\n莫把放翁笑我，又似忆、平泉花石。\n篱菊老，梅枝亚，不归怎得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18926, '醉蓬莱', '百兰', '怪柳吟翻雪，梅笑冲寒，郁葱如彩。\n还是瑶池，宴神俦侣。\n罗幕轻掀，绣帘低揭，按霓裳宫羽。\n宝炷熏浓，佩环声颤，凤飞鸾舞。\n犹记年时，玉箫吹彻，并驾萧郎，共骖赢女。\n旋捧麒麟，种旧家前武。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18927, '满庭芳', '百兰', '有分非难，是缘终合，采来还换须臾。\n少年培植，春意已敷腴。\n毕竟花多驻果，坚牢是、蚌老生珠。\n君知否，今番定也，颠不破。\n遥知纷瑞霭，十分郎罢，黄溢眉须。\n便何妨燕喜，剩卖欢娱。\n况侍北堂难老，庭阶映、玉树森如。\n金荷劝，从教酩酊，扶醉看孙株。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18928, '雨中花・夜行船', '百兰', '斗云山，挨排烟水，六丁午夜文移。\n道滁翁孙子，欲寄游嬉。\n高趁鹜霞舒啸，低群鸥鹭忘机。\n牢笼两下，楼乘汗漫，桥枕清漪。\n灞陵吟畅，岳阳登览，百色都副襟期。\n还好是、行天马渡，探月人归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18929, '碧桃春・阮郎归', '丁持正', '几年辛苦捣元霜。\n一朝琼粉香。\n云英缥渺曳仙裳。\n相将骑凤凰。\n帝乐，酌天浆。\n千年颜色芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18930, '一箩金・蝶恋花', '李石才', '武陵春色浓如酒。\n游冶才郎，初试花间手。\n绛蜡烛残人静後。\n眉峰便作伤春皱。\n一霎风狂和雨骤。\n柳嫩花柔，浑不禁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18931, '水调歌头', '魏顺之', '人世斗南瑞，天上璧东星。\n谁分佳种，锺作间世玉麒麟。\n本是南阳相种，来应瑞龙间气，试听即英声。\n若问贤相敌，君去问参军。\n质金浑，标玉立，气冰清。\n梅花时候，结子便可鼎调金。\n人谓丹山苞凤，天产渥洼骏骨，德毓窦家椿。\n来作汤饼客，何幸厕嘉宾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18932, '贺新郎', '伍梅城', '甲子头春雨。\n知老天、净冼荆扬，十年烟雾。\n夜半堕中星一颗，飞下五云深处。\n帝亲敕、六丁呵护。\n须信斯人为世瑞，非人龙、定是文中虎。\n关世道，系天数。\n此儿殊怕人惊顾。\n况当家、廷评为祖，大中为父。\n料想廷评公一笑，笑对大中共语。\n应自把、小程夸取。\n会见九州熙白日，做状元、宰相荣门户。\n年正少，四亲具。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18933, '贺新郎', '伍梅城', '梦到天宫里。\n见长庚星颗，忽自月边飞至。\n直奏玉皇金阙道，臣已五年于此。\n今亦欲、过宫一次。\n福禄寿星齐赞叹，过宫时、须过廉泉位。\n帝首肯，从他意。\n朝来鹊送帘前喜。\n闻廉泉、似是紫岩，螟蛉兄子。\n是子南轩人物祥，功业行看相似。\n岂同祖、同闻而已。\n细把所闻详所梦，想天文、实应人间事。\n况真是，长庚李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18934, '最高楼', '伍梅城', '知君久，勘破利名关。\n未老得先闲。\n今年最喜吟身健，生朝更觉酒肠宽。\n且随宜，将秫种，买花看。\n门外吏、催科无一迹。\n窗下客、谈诗常经日。\n儿玉树，弟金兰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18935, '醉蓬莱', '伍梅城', '倚东风笑问。\n落红啼，清明来未。\n小雨弄晴，做轻寒天气。\n南极光中，五云深处，人庆千秋岁。\n翡翠屏间，琉璃帘下，彩衣明媚。\n九老风流，五候家数，如此乾坤，有人如此。\n天正烦君，作江南一瑞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18936, '摸鱼儿', '伍梅城', '极知君、腰骑鹤，此心与水相似。\n梧桐叶上黄昏雨，恨杀无情流水。\n滔滔地。\n今日大江头，明日人千里。\n君思往事。\n两袖淮云，一轮明月，要亦寻常耳。\n君去也，我亦扁舟东矣。\n尊前何惜同醉。\n五年未老君犹健，五十行当富贵。\n书频寄。\n报王粲、何时可决荆州计。\n俱胝一纸。\n更细算何时，五星同会，天下太平未。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18937, '贺新郎', '伍梅城', '上界神仙府。\n谁移来、登瀛堂畔，五云深处。\n江水一弓山万朵，竹外梅花千树。\n看都入、高人庭户。\n南北两厅相对起，要门前、便是浮岚路。\n依暖翠，开吟圃。\n莺迁喜奉高堂母。\n向销金帐下，坐看秦歌赵舞。\n唐宋几年名阀阅，到此步高一步。\n君听取，邦人庆语。\n多少朱门随世化，独眼前、突兀新如许。\n真个是，擎天柱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18938, '贺新郎', '丁几仲', '喜溢蟾宫梦。\n起推衣、平章宝桂，湿鸦飞动。\n果报佳音传络秀，丹穴雏生彩凤。\n想孔释、亲来抱送。\n不羡徐卿秋水澈，试闻声、识破真英种。\n培杞梓，待时用。\n当年绛帐承新宠。\n问何如归来，碧荷香重。\n都是刘郎看承处，多少温柔从臾。\n会起我嘉宾钦竦。\n左氏公羊，从初所学，看家传、声誉今腾涌。\n拚醉舞，与谁共。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18939, '百字谣・念奴娇', '禅峰', '中秋近也，正于门瑞气，葱葱时节。\n隔岁维熊占吉梦，今夕天生英杰。\n仙籍流芳，瑞龙毓秀，应是非凡骨。\n诗书勋业，妙龄行见英发。\n好是日满三朝，剩陈汤饼，投辖留宾客。\n玉果犀钱排绮宴，窈窕歌珠舞雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18940, '西江月', '刘涧谷', '淑质生当良月，辰喜遇今朝。\n掌心托个儒人苗。\n早晚夫人争叫。\n阿母神仙苗裔，阿爷宰相丰标。\n阿兄气宇更飘飘。\n阿弟看看速肖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18941, '浣溪沙', '游稚仙', '日先联瑞日红。\n寿星明照寿筵中。\n庆门乐事正重重。\n明日贾逵添戏彩，异时李汉看乘龙。\n鱼轩玉轴定荣封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18942, '沁园春', '李团湖', '六桂传家，三槐植庭，箕裘大儒。\n甚二郎意气，似同稷契，一时庆会，致主唐虞。\n百揆登庸，双亲未老，此乐人间还有无。\n那堪更、有棣华，听履亨衢。\n朝来天上传呼。\n便写作、衣冠盛事图。\n有声容备乐，传宣锡动，充庭牲饩，簇拥欢娱。\n整顿乾坤，巩安宗社，亦有臣功如此乎。\n中书考，愿年年此日，春满蓬壶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18943, '满江红', '黄诚之', '五岳三光，锺秀气、笃生人杰。\n天付与、心肠锦绣，精神冰雪。\n姓字早登龙虎榜，文书夜直丝纶阁。\n谢君王、特地掇鸾坡，来闽粤。\n几千顷，恩波阔。\n十万户，欢声浃。\n看致君尧舜，归班夔契。\n淡笑扫清沙漠净，弥缝补就苍天缺。\n愿年年、长醉腊前春，梅梢月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18944, '洞仙歌', '熊子默', '春逢花好，一笑长相见。\n令似当年徊仙苑。\n况歌翻桃叶，香绕莱衣，须信道，人与千秋共远。\n不妨留绛节，看即沙堤，玉笋班高侍金辇。\n问人间、缘底事，犹欠河清，须妙手、鸿钧一传。\n待整顿乾坤、却归来，唤舞鹤翔云，洞天游伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18945, '水调歌头', '陈惟哲', '近畿贤太守，陆地隐神仙。\n功高玉记，名通紫府自长年。\n拂拭壶中光景，游戏人间风月，富贵本青毡。\n十载五分牧，惠泽浸江天。\n把文章，做勋业，德才全。\n龟峰堂上，满城和气入歌筵。\n春在百花庭院，坐拥十眉珠翠，寿酒吸长川。\n来岁称觞处，稳向凤池边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18946, '摸鱼儿', '欧阳朝阳', '正当绂麟时候，秋香还弄清晓。\n双旌五马人间贵，千里共腾欢笑。\n人未老。\n看绿鬓朱颜，赢得花簪帽。\n兽炉篆袅。\n听檀板轻敲，歌珠一串，依约似蓬岛。\n青云步，九万论程未了。\n芹宫多世仪表。\n提封晋郡重拈出，留样他年称好。\n书上考。\n怕种满棠阴，丹诏催归早。\n安期献枣。\n对鹤健丹香，龟轻莲叶，起舞醉清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18947, '贺新郎', '碧虚', '兖兖登台阁。\n问诸公、谁讲谁明，诗书礼乐。\n前日毕星光焰里，有一濂渠伊洛。\n被翠玉、江山占却。\n天下国家多少事，好人才、半刺东南角。\n当路者，欠商确。\n寿杯端拜深深酌。\n把寻常、祝颂芜词，一时删削。\n引饮莱公同鼎轴，共定渊一著。\n二百载、无人能学。\n文简毕公真事业，非先生之托谁之托。\n龟鹤舞，蛟龙跃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18948, '琐寒窗', '彭正大', '千里儒流，称觞此际，梅花三度。\n书台最上，健羡一翁如许。\n问吴江、别来旧人，当时折柳凭谁语。\n但春在芹宫，芳滋兰畹，一帘今雨。\n凭阑、凝望处。\n有绿水青山，乾坤付与。\n百年家谱，曾是斯文宗主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18949, '感皇恩', '叶巽斋', '冬岭秀乔松，江南飞雪。\n数朵梅花弄春色。\n玉颜苍鬓，人似松梅标格。\n岁寒长不老，人奇绝。\n簿领馀间，长生有道，福寿从今更千百。\n孙枝浸盛，万卷家传方册。\n樽前频醉，此宵风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18950, '庆长春・念奴娇', '铁笔翁', '有洒如渑，便开怀痛饮，我歌君拍。\n世事轮云都莫问，只要颜红鬓黑。\n鹂燕风清，鸳鸯水暖，打当生申节。\n薰风来也，几人感戴翁德。\n好是驾海胸襟，屠龙手段，一笑乾坤窄。\n门外尘涛三百尺，不博剡溪一雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18951, '醉蓬莱', '刘性初', '喜首夏清和，槐绿成阴，榴红正朵。\n仙鹤翩跹，来致千秋贺。\n南极长明，後天不老，瑞霭浮青琐。\n满树蟠桃，瑶池捧献，一年一颗。\n好敞亭台，胜添花柳，时醉时歌，时行时坐。\n受用黄庭，宝熟丹田火。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18952, '齐天乐', '刘学颜', '红冈小塔枫林路，曾见承平歌舞。\n舞罢人归，月斜影转，重见郎官星度。\n乡关境土，又二十馀年，桑麻深露。\n说与闾巷，少年知得当时否。\n如今苍颜白发，问耕聊尔耳，依稀农圃。\n父老吾伊，深山鸡黍，谁念乱离父母。\n村南昼午。\n谩对客烹茶，笑谈今古。\n千岁迢迢，竹风时扫户。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18953, '好事近', '江史君', '耳顺恰当年，甲子方一数。\n绛县老人曾纪，四百四十五。\n孙弘博士适遭逢，马援击蛮未遇。\n五福祝君全备，更尊荣安富。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18954, '最高楼', '徐架阁', '年高德劭，休叹老而传。\n纵白发，尚红颜。\n楚丘且谓吾始壮，大致仕亦宜然。\n更尊荣，安富贵，寿绵延。\n闻道生辰当月吉，万福千祥降自天。\n献春酒，展华筵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18955, '沁园春', '立斋', '表表耆英，松柏贞刚，冰霜洁清。\n正持囊紫禁，急流勇退，步角巾绿野，闲处安身。\n里社鸡豚，家山猿鹤，物我相忘法从荣。\n东溪畔，似非熊尚父，在渭之滨。\n闲来袖手梅亭。\n似桃李纷纷谷自春。\n算高风难进，缙绅楷式，颓波立，乡曲仪刑。\n厚德清名，疏星碧落，屈指如公今几人。\n无他祝，但似山难老，镇压嚣尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18956, '酹江月・念奴娇', '黄革', '堂堂卿月，奉君恩来作，潜藩贤守。\n喜遇慈闱年八十，特向新正称寿。\n千里春风，满堂和气，是处歌声奏。\n荷衣紫绶，捧觞齐上春酒。\n人道彭祖高年，寿高八百，管从来稀有。\n似此遐龄，屈指算、犹有十分之九。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18957, '百字令・念奴娇', '陈潜心', '梅峰孕秀，庆仙翁、咫尺元宵三夕。\n盛德温温如玉粹，多少殊勋嘉绩。\n两拥朱幡，独清节，高谊真难屈。\n景疏堂下，台星长伴南极。\n雅羡椿桂联芳，金章紫绶，拜舞欢声溢。\n福备宜高仁者寿，喜占人间八十。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18958, '三登乐', '罗子', '过了元宵，见七叶又飞。\n恰今朝、昴宿降瑞。\n初度果生贤，尽道丰姿绝异。\n翰林人物，云霄富贵。\n自栖鸾展骥。\n迤逦黄堂，每登要路无留滞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18959, '虞美人', '刘公子', '搀先四日花朝节。\n红紫争罗列。\n传言玉女降生朝。\n箕宿光联婺宿、灿云霄。\n衣红袖齐歌舞。\n称颂椒觞举。\n群仙列侍宴瑶池。\n王母麻姑同寿、更无期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18960, '百字谣・念奴娇', '三槐', '武夷秀气，萃君家、春色融和时节。\n赏了花朝才六日，曾记挺生英杰。\n量吸鲸川，志吞牛渚，标格冰壶洁。\n台星明处，年年辉映南极。\n须信早晚横翔，云霄直上，宁久栖鸾棘。\n富贵荣华年正少，谢砌芝兰秀发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18961, '沁园春', '程东湾', '毓德婺虚，联辉魁宿，天启儒英。\n正仲春阶，三留叶秀，晓来蓬矢，六挂门荣。\n星昴诞萧，神嵩降甫，怎似今朝记始生。\n当此际，有满城和气，万井欢声。\n龚黄政事勋名。\n镜里文书吏胆惊。\n况百年经界，于今修复，四贤道学，至此彰明。\n月对艳阳，日逢初度，紫诏行催觐玉京。\n黄堂上、寿觞称处，介福邦民。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18962, '百字谣・念奴娇', '张', '榆烟新起，正清明节过，翠九叶。\n欣会谪仙初度日，凤穴产真。\n心肠琅琅，文章锦绣，看镜期勋业。\n暂居马帐，後知有赖先觉。\n可想大器晚成，功名有志，未逊苏秦学。\n奈不在身先在子，果向秋风抟鹗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18963, '水调歌・水调', '胡德芳', '湛湛玉清水，矗矗炼丹山。\n秀环侯泮，广文分得括苍仙。\n虞殿薰风初入。\n尧陛祥七叶，此际诞真贤。\n学术瑞王国，声誉蔼人寰。\n绿槐宫，丹桂殿，杏花坛。\n英华粲发，聊将文教布龙藩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18964, '声声慢', '赵宰', '洞宾仙客，诞节明朝，方斋今日称觞。\n为有金丹，希年近也康强。\n平生铁石肺腑，肯依阿、贪恋朝行。\n芹溪上，把等闲出处，付与沧浪。\n花竹午桥葱倩，身退静、功名大耐偏长。\n济世经纶，暂时收敛何妨。\n黄扉有分须到，况玉皇、久待平章。\n康时了，万千年、姓字弥香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18965, '满庭芳', '张宰', '气吐虹霓，笔飞鸾凤，从来锦绣文章。\n谪仙才调，复见庆流芳。\n向自题名雁塔，不十载、德播河阳。\n慰民望，一麾出守，风月任平章。\n清和，时欲半，吕仙诞日，正此相当。\n欣逢初度旦，敢献椒觞。\n只恐经纶大手，应休期、便趣曹装。\n愿箕宿，照临南极，拱北远流光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18966, '满江红', '梁大年', '九十炎光，又过了、三分之一。\n记当年光际，诞生良弼。\n崧岳降神锺秀气，孕成间世真英杰。\n妙文章、拾芥立功名，谁能敌。\n周孔业，邹轲质。\n伊尹志，渊明节。\n袖经纶妙手，屡投班笔。\n富贵一朝知己逼，封候谈笑真堪觅。\n信功名、管取出长年，看箕翼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18967, '水调歌头', '梁大年', '南极寿星现，佳气蔼庭除。\n谁为绛人甲子，为我一轩渠。\n恰喜亥成二首，还庆阳来七日，和气渐舒徐。\n敬为图南祝，一瓣问兴居。\n傲松筠，抚龟鹤，乐蓬壶。\n斑衣戏舞，春满兰玉正森如。\n却忆杜陵老子，因羡碧山学士，茅屋换银鱼。\n何似温柔地，丝竹伴琴书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18968, '烛影摇红', '鼓峰', '风入虞弦，麦秋向晚梅天润。\n彩丝长命斗新奇，还是端阳近。\n想见瑶池仙韵。\n对蟠桃、朱颜相映。\n篆飘宝鼎，酒满霞觞，黄堂深静。\n超悟真筌，凤归不作登台恨。\n庆馀有子在河图，详试龚黄政。\n好是棠阴清永。\n且游戏、壶中光景。\n会有飞诏，却奉轻轩，天朝归觐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18969, '水龙吟', '程霁岩', '夏秋晦朔之间，伊谁为作交承主。\n昂仙伯，挺生此日，宾凉饯暑。\n绛县老人，问将甲子，恰今岁数。\n举香山晏会，才先一载，愚深幸、获叨预。\n何以寿君初度。\n愿朱颜、年年如许。\n棘栖鸾凤，瑞浮，争如燕处。\n双桂渐香，灵椿好在，福全九五。\n向画堂深处，不妨重按，旧时歌舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18970, '满庭芳', '程霁岩', '一叶鸣秋，五纪瑞，申月还庆生申。\n巍巍郎宿，辉映寿星明。\n一段精神玉立，秋潭自、足副徽称。\n长生，只在公丹府，何待祝修龄。\n粉垣，才过了，便持荷橐，光近枫宸。\n况金瓯将启，庆满槐庭。\n朝旆行行入侍，彩衣映、衮冕辉新。\n从今去，相门出相，未数汉韦平。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18971, '水调歌头', '翠微翁', '荚绕开六，宝历已当千。\n人间收尽繁溽，凉意入琴弦。\n尽道荐衡交剡，更值生申时节，喜色动闾阎。\n终夜望银汉，文宿贯台躔。\n定燕秦，封晋魏，信当然。\n处处红莲开幕，曹掾岂能淹。\n见说玉堂飞诏，已许金闺通籍，蓬岛伴神仙。\n来岁寿卮酒，应醉御炉烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18972, '朝中措', '菊翁', '桂花庭院是蓬壶。\n行地列仙图。\n月姊搀先两日，捧觞来庆垂弧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18973, '水龙吟', '赵佥判', '老人星照螺川，丽谯瑞霭笼晴昼。\n使君初度，满城和气，欢声盈口。\n篱菊浮金，茱萸泛紫，重阳时候。\n算年年长是，节前八日，先满□、为公寿。\n一代文章山斗。\n拥朱幡、暂劳分守。\n崇墉万堞，浮梁千丈，此恩难朽。\n襦裤方谣，丝纶已下，即登班首。\n看明年今日，开筵凤池，赐黄封酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18974, '沁园春', '李慧之', '八九十翁，似婴儿戏，汉司马迁。\n记渭川垂钓，一年之长，龙山吹帽，七日之前。\n口角春风，襟期秋月，万事从来只任缘。\n随渠道，更登天富贵，陆地神仙。\n儿孙绿绶青编。\n看鼓舞云霄高刺天。\n但阶移花影，闲寻棋局，风斜竹径，缓起茶烟。\n心迹逾清，精神越健，不用金丹资节宣。\n洪崖老，笑将眉寿，祝我老人轩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18975, '最高楼', '留晚香', '西江水，分润到全闽。\n芹藻亦生春。\n秀锺东壁双躔瑞，祥开南极一星明。\n把紫阳、年月算，恰同庚。\n前十日、重阳秋正好。\n後十日、小阳春未透。\n梅与菊，此交承。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18976, '八声甘州', '杨守', '问梅边消息有还无，似微笑应人。\n道近来别有，相家一种，叶叶都新。\n趁得嫩寒轻暖，七日小阳春。\n一点和羹意，来做生辰。\n锦绣香中开国，向绮霞洞里，暂寄闲身。\n欠朝家多少，未了底经纶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18977, '满江红', '草夫人', '清晓新妆，鸾台畔、潜呼小玉。\n问阿谁庭院，调长生曲。\n报道隔邻人庆寿，新来荣领金花轴。\n细推来、阳月已将周，惟三宿。\n陈□颂，年多祝。\n环珠翠，人如簇。\n奉金杯相庆，满斟。\n愿享麻姑难老福，屡餐王母蟠桃熟。\n更儿孙、岁岁献莱庭，蓝袍绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18978, '多丽', '游慈', '约梅花，年年开向华筵。\n借清香，飞入寿杯中，永祝英贤。\n才履长、便登八帙，那须要、更待来年。\n和气先春，祥风破腊，开七荚正敷妍。\n君不见，太公此际，犹欲钓川。\n争知道、副车已办，西伯来畋。\n驻东阳、清淡终日，种成桃李森然。\n向庭闱、绯衣戏彩，更孙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18979, '摸鱼儿', '静山', '晓峰高、飞泉如瀑，潜虬鞭驾轩翥。\n为他一片韩山石，直到红云天尺五。\n想应道、公皆安在来何暮。\n金川小渚。\n那韶石参天，郡纲宜录，为我分南顾。\n锦衣昼，满袖尚疑香雾。\n催人富贵如许。\n岭云见说今如砥，凤挟九成迎舞。\n烦道甫。\n问金镜铁胎，还记开元否。\n封词寄与。\n但目送河桥，吟消醉拍，载酒满江浒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18980, '水龙吟', '静山', '片帆天际归舟，好风动、吹来消息。\n浪间双浆，回头春杪，去来几日。\n十八滩头，水飞如舞，石如壁。\n把连樯白粲，等闲卸却，更呼取、入。\n不羡公家事了，羡二难、一番游历。\n江花江水，无边风月，不知行役。\n和郁孤词，倚崆峒剑，唤醒龙蛰。\n试问君，过我青原，听得几声羌笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18981, '满江红', '刘守', '归去来兮，要待足、何时是足。\n荣对辱、饮河鼹鼠，无过满腹。\n浴月朝霞红赛锦，排云晚岫青如玉。\n更修筠、与合抱长松，依梅麓。\n森画戟，谩符竹。\n舞袖短，辕驹局。\n惟茧丝堡障，医疮剜肉。\n节对开炉应去也，钗头又有长生。\n算归程、恐到荔枝乡，已过熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18982, '江城子', '逸民', '秀才落得甚乾忙。\n冗中秋，闷重阳。\n百年三万，消得几科场。\n吟配十年灯火梦，新米粥，紫苏汤。\n如今且说世平康。\n收战场。\n息枪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18983, '江城子', '无何有翁', '小年底死路槐忙。\n叹蝉声，早斜阳。\n今夕何年，白骨照沙场。\n天上人间都是梦，石中火，镬中汤。\n人如今且免秀才康。\n驰大马，试长枪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18984, '沁园春', '任翔龙', '客有问余，号日汝水，逸民者谁。\n是胸罗星斗，熟知天命，口分造化，妙泄天机。\n百十日前，再三地说，端的秋来攀桂枝。\n那时节，果鳌头高跨，鹗首横飞。\n君休说是谈非。\n是则是干支带得来。\n也要他有个、读书种子，一丁不识，富贵何为。\n报道长安，梅边春色，早趁东风掠马蹄。\n重逢处，办一封好纸，觅状元诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18985, '西江月', '程梅斋', '刻木工夫最巧，舆梁底事尤精。\n玉虹饮水映波明。\n彼此往来利济。\n真个作家手段，从今名播寰瀛。\n人从鳌背获安行。\n镇作城南景致。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18986, '沁园春', '刘省斋', '男子才生，桑弧蓬矢，志期古同。\n况平生慷慨，胸襟磊落，弛张洞晓，经艺该通。\n笔扫云烟，腹储兵甲，志气天边万丈虹。\n行藏事，笑不侯李广，射石夸雄。\n仰天一问穷通。\n叹风虎云龙时未逢。\n羡傅岩版筑，终符求象，渭滨渔钓，果兆非熊。\n白额未除，长鲸未脍，臂健何嫌二石弓。\n天山定，任扶桑高挂，凌阁图功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18987, '踏莎行', '刘仁父', '不假牵丝，何劳刻木。\n天然容貌施妆束。\n把头全仗姓刘人，就中学写秦城筑。\n伎俩优长，恢谐软熟。\n当场喝采醒群目。\n赠行无以表殷勤，特将谢意标芳轴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18988, '如梦令', '刘南翁', '没计断春归路。\n借问春归何处。\n莺燕也含愁，总对落花无语。\n春去。\n春去。\n门掩一庭疏雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18989, '贺新郎', '勿翁', '庭外潇潇雨。\n对空山、再度端阳，悄无情绪。\n旧日文君今瘦损，寻旧曲、不成腔谱。\n更不周郎回顾。\n尚喜庭萱春未老，捧蒲觞、细细歌金缕。\n儿女醉，笑还语。\n醉馀更作婆娑舞。\n又谁知、灵均心事，菊英兰露。\n最苦当年哀郢意，因甚夫君未许。\n却枉使、蛾眉见妒。\n在再章台才十载，笑关河、失报应旁午。\n愁读到，楚辞句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18990, '沁园春', '李君行', '三岛十洲，移掇者谁，玉城稚仙。\n解运诗之巧，裁山剪水，用诗之力，斡地回天。\n大笑宋初，秀才屋子，著不得官家十万钱。\n又谁说，李膺豪放，门号龙门。\n我家呼喝山川。\n道今日山春莺已迁。\n汝南山顶上，虎毋久卧，秀溪底下，龙莫长眠。\n打起精神，护持诗府，推出诗城障山边。\n山川道，如稚仙肯出，当拜君言。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18991, '齐天乐', '赋梅', '雕阑曲曲芙蓉水，天然一时潇洒。\n露冰壶，风摇玉佩，缥缈蓬莱如画。\n银烛欲下。\n照藻桷飞，杏梁虹架。\n如此规模，杜陵何止万间厦。\n明年春燕归早，卷帘应认得，旧家王谢。\n袖里经纶，幕中佳话，高断云根谁写。\n青冥综靶。\n看人在金坡，炬莲盈把。\n句忆湘南，渌池明月夜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18992, '临江仙', '易少夫人', '何处甘泉来席上，嫩黄初汤银瓶。\n月团尝罢有馀清。\n惠山名品在，歌舞暂留停。\n欲赏壑源新气味，不应兼进苓。\n此中端有淡交情。\n相如方病酒，一饮骨毛轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18993, '临江仙', '易少夫人', '记得高堂同饮散，一标汤罢分携。\n绛纱笼影簇行旗。\n更残银漏急，天淡玉绳低。\n只恐曲终人不见，歌声且为迟迟。\n如今车马各东西。\n画堂携手处，疑梦又疑非。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18994, '减字木兰花', '胡平仲', '天然标格。\n不问青枝和绿叶。\n彷佛吴姬。\n酒晕无端上玉肌。\n怕愁贪睡。\n谁会伤春无限意。\n乞与徐熙。\n画出横斜竹外枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18995, '减字木兰花', '胡平仲', '兰凋蕙歇。\n野店酒初尝竹叶。\n绝艳幽姿。\n洗出铅华见雪肌。\n云阶月地。\n凭仗幽人须着意。\n一夜花飞。\n一点微酸已著枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18996, '宴桃源・如梦令', '曹遇', '西湖辟暑棹扁舟。\n忘机狎白鸥。\n荷香十里供瀛洲。\n山光翠欲流。\n歌浩浩，思悠悠。\n诗成兴未休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18997, '宴桃源・如梦令', '曹遇', '廉纤小雨养花天。\n池光映远山。\n蕙兰风暖正暄妍。\n归梁燕翼偏。\n芳草碧，绿波涟。\n良辰近禁烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18998, '蓦山溪', '曹遇', '鉴湖千顷，四序风光好。\n拔棹皱涟漪，极目处、青山缭绕。\n微茫烟霭，鸥鹭点菰蒲，云帆过，钓舟横，俱被劳生扰。\n知章请赐，独占心何小。\n风月本无私，同众乐、宁论多少。\n浮家泛宅，它日郊陶朱，烹鲈鳜，酌松醪，吟笔千篇扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (18999, '水调歌头', '曹遇', '造物巧能赋，新腊报花期。\n江梅清瘦，只是洁白逞芳姿。\n我欲超君绝类，故学仙家繁杏，艳映横枝。\n朱粉腻香脸，酒晕著冰肌。\n玉堂里，山驿畔，最希奇。\n谁将绛蜡笼玉，香雪染胭脂。\n好向歌台舞榭，斗取红妆娇面，偎依韵偏宜。\n羌管莫吹动，风月正相知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19000, '西江月', '曹遇', '秋霁嫦娥二八，寒光逼散浮云。\n小山丛桂吐清芬，犹带蟾宫风韵。\n因念两登仙籍，恩沾雨露方新。\n汝今妙岁已能文。\n早折高枝荣奋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19001, '满江红', '白君瑞', '木落林疏，秋渐冷、芙蓉新拆。\n傍碧水，晓妆初鉴，露匀妖色。\n故向霜前呈艳态，想应青女加怜惜。\n映朝阳、翠叶拥红苞，闲庭侧。\n岩桂香，随飘泊。\n篱菊嫩，陪幽寂。\n笑春红容易，被风吹落。\n满眼炯然宫锦烂，一身如寄神仙宅。\n把绿尊、莫惜醉相酬，春工力。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19002, '水调歌头', '白君瑞', '凉吹佛衣袂，助我上高台。\n云檐风栋，窗户绝纤埃。\n四绕江山雄麓，万古盘龙踞虎，壮气销崖嵬。\n二水中分远，艇子自归来。\n望白云，迎碧汉，俯长淮。\n铎声到耳，亭亭孤塔现林隈。\n烟惹宫城深树，日照酒楼帘幕，物象眼前排。\n长啸下梯径，欲去更徘徊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19003, '柳梢青', '白君瑞', '玉骨冰姿，天然清楚，雪里曾看。\n物外幽人，细窥天巧，收入毫端。\n一枝影落云笺。\n便似觉、清风夜寒。\n试向松窗，待闲一展，俗虑都捐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19004, '风入松', '白君瑞', '一冬不见雪花飞。\n爱日荡晴晖。\n腊残未解寒塘冻，东风细、已露春期。\n正是年时策马，相随村落寻梅。\n故人别久信音稀。\n排闷有新诗。\n雁声北去江城暖，暗舒展、花柳容仪。\n屈指烧灯不远，等闲休锁双眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19005, '念奴娇', '白君瑞', '江干蹭蹬，镇寻常、怀想京城春色。\n静倚山亭凝望处，惟见鸟飞云幕。\n拂面埃尘，跳□□□，老却风流格。\n年来却有，短蓑轻棹胸臆。\n闻与俊逸嬉游，笙歌丛里，眷恋中华国。\n况是韶阳将近也，应办青骢金勒。\n丰乐阑干，西湖烟水，遍赏苏堤侧。\n举觞须酹，天隅犀渚孤客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19006, '水调歌头', '贾应', '晚日浴鲸海，壁月挂鳌峰。\n不知今夕何夕，灯火万家同。\n楼外芙蕖开遍，人在琉璃里，语笑隔帘重。\n对景且行乐，一醉任东风。\n黄堂宴，春酒绿，艳妆红。\n文章太守，和气都在笑谈中。\n正此觥筹交错，只恐笙歌未散，温诏促追锋。\n来岁传柑处，侍宴自从容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19007, '沁园春', '杨元亨', '一棹横江，问讯盟鸥，太守谓谁。\n道皇华使者，光风洒落。\n元宵三五，乐与民俱。\n宝金鞯，玉梅钗燕，斗鸭阑干花影嬉。\n人迎笑，似玉京春浅，长是灯时。\n风流不减人知。\n算岳牧词人谁似之。\n把南楼风月，渚宫丘壑，竹西歌舞，行乐濡须。\n万斛金莲，满城开遍，朵朵留迎学士归。\n明年宴，看柑传天上，月在云西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19008, '八声甘州', '林实之', '客星堂下水，碧浮空、烟树几重重。\n想故人当日，论情蓬，际会云龙。\n底事泥涂轩冕，不肯作三公。\n千仞钓江浒，此意谁同。\n应笑赤松黄石，效痴儿成事，犹自言功。\n怎知他箕颍，袖手独舂容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19009, '水调歌头', '刘源', '几载沧江梦，此夕复经过。\n双台双峙如画，空翠滴晴波。\n不是先生高节，激起清风千古，汉鼎复如何。\n矫首望天际，烟树翠婆娑。\n危楼下，数不尽，去帆多。\n人人惊肉生髀，却日欲挥戈。\n谁识矶边泉石，别有壶中天地，烟雨一青蓑。\n自笑亦华发，三叹吊岩阿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19010, '水调歌头', '曾中思', '有客泛轻舸，迤逦到桐庐。\n山湾水曲，个中依约是仙区。\n试唤清江渔父，为问来今往古，兴废事如何。\n笑指寒烟里，此是子陵居。\n汉光武，兴皇运，握乾符。\n客星侵座，方见不与故人疏。\n自是先生高尚，无限经纶才略，飘泛寄江湖。\n凛凛亘千载，风月属樵渔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19011, '水调歌头', '黄子功', '绾纤钓台下，敛任谒严陵。\n石矶封藓，一笑挟策独先登。\n山献修蛾几抹，江绕青罗千顷，今古富春声。\n行有二三子，心迹喜双清。\n吊羊裘，追往躅，尚仪型。\n丹青洒落三反，谁动紫垣星。\n重袖调元大手，归傲纶巾一线，志不在寒鲸。\n千载仰风节，鸿鹄自冥冥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19012, '水调歌头', '张嗣初', '名节本来重，轩冕亦何轻。\n人间儿戏，刚自指点客星明。\n黄屋龙旗九仞，苍石渔丝千尺，谁辱又谁荣。\n会得傥来意，方识古交情。\n想当时，奇男子，汉真人。\n龙潜豹隐，胸中同是一经纶。\n公办中兴事业，我向沧浪学钓，各自寄吾真。\n谁信往来客，千古诵清名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19013, '水调歌头', '沈明叔', '汉事正犹豫，足迹正跫然。\n岩陵老子，当时底事动天顽。\n曾把丝纶一掷，藐视山河九鼎，高议凛人寒。\n竹帛非吾事，霄汉任腾骞。\n问云台，还得似，钓台巅。\n几年山下，使人犹识汉衣冠。\n寄语功名馀子，今日成尘何在，百战亦多艰。\n一笑桐江上，来往钓名船。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19014, '点绛唇', '寇寺丞', '春睡腾腾，觉来鸳被堆香暖。\n起来慵懒。\n触目情何限。\n深院日斜，人静花阴转。\n柔肠断。\n凭高不见。\n芳草连天远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19015, '减字木兰花', '苏小小', '别离情绪。\n万里关山如底数。\n遣妾伤悲。\n未必郎家知不知。\n自从君去。\n数尽残冬春又暮。\n音信全乖。\n等到花开不见来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19016, '减字木兰花', '李秀兰', '自从君去。\n晓夜萦牵肠断处。\n绿遍香阶。\n过夏经秋雁又来。\n想伊那里。\n应也情怀愁不止。\n渺渺书沈。\n直至如今没信音。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19017, '采桑子', '胡夫人', '与君别後愁无限，永远团，间阻多方。\n水远山遥寸断肠。\n终朝等候郎音耗，捱过春光。\n烟水茫茫。\n梅子青青又待黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19018, '失调名', '窦夫人', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19019, '失调名', '王娇姿', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19020, '御街行', '洛阳女', '一身萍梗随邮转。\n恨归路、如天远。\n近来魂梦也疏人，不似旧时常见。\n剩衾馀枕，冷清清地，空恁闲一半。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19021, '渔家傲', '丁羲叟', '十里寒塘初过雨。\n采莲舟上谁家女。\n秋水接云迷远树。\n天光暮。\n船头忘了回来路。\n却系兰舟深处住。\n歌声惊散鸳鸯侣。\n波上清风花上雾。\n无计去。\n月明肠断双栖去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19022, '苏幕遮', '陶氏', '与君别，情易许。\n执手相将，永远成鸳侣。\n一去音书千万里。\n望断阳关，泪滴如秋雨。\n到如今，成间阻。\n等候郎来，细把相思诉。\n看著梅花花不语。\n花已成梅，结就心中苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19023, '升平乐', '吴奕', '水阁层台，短亭深院，依稀万木笼阴。\n飞暑无涯，行云有势，晚来细雨回晴。\n庭槐转影，纱厨两两蝉鸣。\n幽梦断枕，金猊旋热，兰炷微薰。\n堪命俊才俦侣，对华筵坐列，朱履红裙。\n檀板轻敲，金樽满泛，纵交畏日西沉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19024, '选冠子', '杨太尉', '碧眼连车，黄头间座，望断故人何处。\n当时胜丽，旧日繁华，都变虏言胡语。\n万里衔冤，几年埋恨，仔细向谁分诉。\n对南风凝眸，眺神旌、触目泪流如雨。\n今幸会，电扫雷驱，云开雾敛，一旦青天重睹。\n桃林卧草，华岳嘶风，行迓太平周武。\n洗尽腥膻巷陌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19025, '多丽', '李子申', '好人人。\n去来欲见无因。\n记当时、藕香倚暖，岂期蝶散鹣分。\n到而今、漫劳梦想，嗟後会、惨啼痕。\n绣阁银屏，知他何处，一重山尽一重云。\n暮天杳、梗踪萍迹，还是寄孤村。\n寂寥月，今宵为谁，虚照黄昏。\n细追思深诚密意，黯然一饷消魂。\n仗游鱼、漫传尺素，望塞雁、空噎回纹。\n帐衾寒、香消尘满，博山沈水更谁薰。\n断肠也、无聊情味，惟有芳尊。\n沈吟久，移灯向壁，掩上重门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19026, '朝中措', '闾丘次杲', '横江一抹是平沙。\n沙上几千家。\n得到人家尽处，依然水接天涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19027, '眼儿媚', '危昂霄', '晴云十丈跨杉溪。\n偏称夜凉时。\n我来正值，一滩月朗，万木霜飞。\n谪仙不住人间世，此恨有谁知。\n何人画我，倚阑得句，听水忘归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19028, '水调歌头', '万某', '卷尽风和雨，晴日照清秋。\n南山高处回首，潇洒一扁州。\n且向飞霞瀹茗，还归云间书院，何幸有从游。\n随分了公事，同乐与同忧。\n少年事，湖海气，百尺楼。\n萧萧华发，归兴只念故山幽。\n今日聊修故事，□岁大江东去，应念我穷愁。\n不但莼鲈□，杜若访芳洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19029, '金缕曲・贺新郎', '蔡士裕', '怪得梅开早。\n被何人、香罗剪就，天工奇巧。\n茅舍竹篱容不得，移向华堂深悄。\n别一样、风流格调。\n玉质冰姿依然在，算暗中、只欠香频到。\n著些子，更奇妙。\n有时来伴金尊倒。\n几徘徊、认成真後，又还误了。\n费尽东君回护力，空把芳心萦绕。\n竟不解、索他一笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19030, '浦湘曲', '蔡士裕', '功名早。\n步武青云缭绕。\n斯文近有成效。\n绛纱拍拍春风满，香动一池芹藻。\n瓜期到。\n便勇撤皋比，此去应光耀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19031, '水调歌头', '覃怀高', '翠蕤插云表，初意隔仙凡。\n临风据案一见，邂逅似开颜。\n几欲拿舟九曲，便拟扪参绝顶，直下俯尘寰。\n聊此税吾驾，赢得片时闲。\n问仙人，缘底事，去不还。\n长风浩浩，何许清梦杳难攀。\n只有苍烟古木，好在清湍白石，依旧画图间。\n回首武夷路，杳霭没云鬟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19032, '水调歌头', '巴州守', '霁色满空碧，爽气正横秋。\n登高行乐，□来只说古巴州。\n扫□尘埃来坐，携取烟云杖履，容□□清游。\n坐上尽佳客，一醉破千忧。\n倚虚壁，绝临□，上层楼。\n黄花赤叶，鸟□啼断四山幽。\n醉里不知归去，空有乱云衰草，落日几多愁。\n舞鹤在霄汉，宿鹭点汀洲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19033, '满江红', '江无□', '使节行秋，算天也、知公风力。\n长啸罢、烟云尽卷，□□□□。\n重九汉峰黄泛酒，五更泰岳□观日。\n问扬公、去後有谁□，□朝集。\n大华□，□□□。\n今古□，□陈迹。\n甚牛山□□，□□□□。\n□□□嫌□薄，高怀□□□□□。\n□□□、黄鹤□□□，□相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19034, '头盏曲', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19035, '浣溪沙', '无名氏', '倦客东归得自由。\n西风江上泛扁舟。\n夜寒霜月素光流。\n想得故人千里外，醉吟应上谢家楼。\n不多天气近中秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19036, '浣溪沙', '无名氏', '北固江头浪拍空。\n归帆一夜趁秋风。\n月明初上荻花丛。\n渐入三吴烟景好，此身将过浙江东。\n梦魂先在鉴湖中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19037, '沁园春', '无名氏', '小阁深沈，寸心怀感，暗忆旧时。\n念母兄贫窘，姻亲劝诱，一身权作，七岁为期。\n及到门阑，小君猜忌，如履轻冰愁过违。\n多磨难，是房中诟骂，堂上鞭笞。\n堪悲。\n命运乖衰。\n甚长个孩儿朝夜啼。\n叹此生缘业，两餐淡薄，无时无泪，如醉如痴。\n暗里相逢，低声说与，此个恩情休谩为。\n须知道，联难为夏竦，不易张祁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19038, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19039, '王子高六么大曲・自度曲', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19040, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19041, '误桃源', '无名氏', '砥柱勒铭赋，本赞禹功勋。\n试官亲处分，赞唐文。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19042, '云鬓松令', '无名氏', '鬓云松，眉叶聚。\n一阕离歌，不为行人驻。\n檀板停时君看取。\n数尺鲛绡，果是梨花雨。\n鹭飞遥，天尺五。\n凤阁鸾坡，看即飞腾去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19043, '胜胜慢・声声慢', '无名氏', '严凝天气，近腊时节，寒梅暗绽疏枝。\n素艳琼苞，盈盈掩映亭池。\n雪中欺寒探暖，替东君、先报芳菲。\n暗香远，把荒林幽圃，景致妆迟。\n别是一般风韵，超群卉、不待淡荡风吹。\n雅态仪容，特地惹起相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19044, '胜胜慢・声声慢', '无名氏', '寒应消尽，丽日添长，百花未敢先拆。\n冷艳幽香，分过溪南春色。\n调酥旋成素蕊，向碧琼、枝头匀滴。\n愁肠断，怕韶华三弄，雪映溪侧。\n应是酒阑人静，香散处、惟见玉肌冰格。\n细细疏风，清态为谁脉脉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19045, '汉宫春', '无名氏', '梅萼知春，见南枝向暖，一朵初芳。\n冰清玉丽，自然赋得幽香。\n烟庭水榭，更无花、争染春光。\n休谩说、桃夭杏冶，年年蝶闹蜂忙。\n立马伫、凝情久，念美人自别，鳞羽茫茫。\n临岐记伊，尚带宿酒残妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19046, '汉宫春', '无名氏', '雪打风摧。\n正篱枯壁尽，却有寒梅。\n衰柳败蒲碍眼，喜见芳蕾。\n江村路曲，问青帘、与酌馀醅。\n须凭取，东君为我，一枝先寄春来。\n寂寞槿门牛巷，有清香自倚，不怕低回。\n终须会逢赏目，健步移栽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19047, '汉宫春', '无名氏', '点点江梅，对寒威强出，一弄新奇。\n零珠碎玉，为谁密上南枝。\n幽香冷艳，纵孤高、却遣谁知。\n惟只有、江头驿畔，征鞍独为迟迟。\n聊拈粉香重问，问春来甚日，春去何时。\n移将院落，算应未肯头低。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19048, '鼓笛慢・水龙吟', '无名氏', '雪霏冰结霜凝，是谁透得春工意。\n南枝向暖，江边岭上，独先众卉。\n闲态幽姿，绿窗红蒂，粉英金蕊。\n念冰肤秀骨，人间要见，除非是、真仙子。\n羌管且休横吹。\n待佳人、新妆初试。\n鸾台晓鉴，人花相对，何须更比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19049, '鼓笛慢・水龙吟', '无名氏', '去年今日关山路，疏雨断魂天气。\n据鞍惊见，梅花的，篱边水际。\n一枝折得，雪妍冰丽，风梳雨洗。\n正水村山馆，倚阑愁寄，有多少、春情意。\n好是孤芳莫比。\n自不分、歌梁舞地。\n砌香砌影，高禅文友，清谈相对。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19050, '鼓笛慢・水龙吟', '无名氏', '淡烟池馆，霜飚乍紧，又是年华暮。\n黄花老尽，丹枫舞困，江梅初吐。\n点缀南枝，暗传春信，玉苞微露。\n凭危阑空断，谁家素脸，遥山远、空凝伫。\n昨夜一枝开处。\n正前村、雪深幽曙。\n看来只恐，瑶台云散，玉京人去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19051, '念奴娇', '无名氏', '雨肥红绽，把芳心轻吐，香喷清绝。\n日暮天寒，独自倚修竹，冰清玉洁。\n待得春来，百花若见，掩面应羞杀。\n当风抵雨，犯寒则怕吹霎。\n潇潇爱出墙东，途中遥望，已慰人心渴。\n斗压阑干，人面共花面，难分优劣。\n嚼蕊寻香，凌波微步，雪沁吴绫袜。\n玉纤折了，人须要斜插。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19052, '念奴娇', '无名氏', '岁华渐杪，又还是春也，难禁愁寂。\n欲探疏梅，独自个、寻访山村水驿。\n路转溪斜，竹低墙短，应是瑶姬宅。\n玉蕤不动，月轮寒浸国色。\n回首故国风光，只因清好，重作江南客。\n堪笑广平，争解我、羁旅芳心脉脉。\n不借铅华，枝头雪霁，愈见香肌白。\n高楼且住，恁渠一弄羌笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19053, '念奴娇', '无名氏', '兰枯蕙死，向竹斋深处，谁传消息。\n霜雪丛中浑似个，缥缈吴人标格。\n绛萼微深，琼苞不露，自与尘凡隔。\n黄昏遥见，一枝烟淡笼白。\n曾记雾阁云窗，轻飞香篆，佳句应难得。\n道韫能文，终未胜、潇洒风流姿质。\n待到春来，满城桃李，相并无颜色。\n殷勤祝付，画楼休品长笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19054, '洞庭春色・沁园春', '无名氏', '绛萼欺寒，暗传春信，一枝乍芳。\n向篱边竹外，前村雪里，青梢犹瘦，疏影溪傍。\n惹露和烟凝酥艳，似潇洒玉人初试妆。\n江南路，有多情伫立，回尽柔肠。\n倚楼最难忘处，正皓月、千里流光。\n纵广平心劲，难思丽句，少陵诗兴，犹爱清香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19055, '沁园春', '无名氏', '山驿萧疏，水亭清楚，仙姿太幽。\n望一枝颖脱，寒流林外，为传春信，风定香浮。\n断送光阴，还同昨夜，叶落从知天下秋。\n凭阑处，对冰肌玉骨，姑射来游。\n无端品笛悠悠。\n似怨感长门人泪流。\n奈微酸已寄，青青杪，助当年太液，调鼎和馐。\n樵岭渔桥，依稀精彩，又何藉纷纷俗士求。\n孤标在，想繁红闹紫，应与包羞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19056, '真珠髻', '无名氏', '重重山外，苒苒流光，又是残冬时节。\n小圆幽径，池边楼畔，翠木嫩条春别。\n纤蕊轻苞，粉萼染、猩猩鲜血。\n乍几日，好景和风，次第一齐催发。\n天然香艳殊绝。\n比双成皎皎，倍增芳洁。\n去年因遇东归使，指远恨、意曾攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19057, '远朝归', '无名氏', '新律才交，早旧梢南枝，朱污粉腻。\n烟笼淡妆，恰值雨膏初细。\n而今看了，记他日、酸甜滋味。\n多应是，伴玉簪凤钗，低桠斜堕。\n迤逦。\n对酒当歌，眷恋得芳心，竟日何际。\n春光付与，尤是见欺桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19058, '击梧桐', '无名氏', '雪叶红凋，烟林翠减，独有寒梅难并。\n瑞雪香肌，碎玉奇姿，迥得佳人风韵。\n清标暗折芳心，又是轻泄，江南春信。\n最好山前水畔，幽闲自有，横斜疏影。\n尽日凭阑，寻思无语，可惜飘琼飞粉。\n但怅望、王孙未赏，空使清香成阵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19059, '泛兰舟', '无名氏', '霜月亭亭时节，野溪开冰灼。\n故人信付江南，归也仗谁托。\n寒影低横，轻香暗度，疏篱幽院何在，秦楼朱阁。\n称帘幕。\n携酒共看，依依承醉更堪作。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19060, '十月梅・十月桃', '无名氏', '千林凋尽，一阳未报，已绽南枝。\n独对霜天，冒寒先占花期。\n清香映月浮动，临浅水、疏影斜。\n孤标不似，绿李夭桃，取次成蹊。\n纵寿阳、妆脸偏宜。\n应未笑、天然雅态冰肌。\n寄语高楼，凭栏羌管休吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19061, '蓦山溪', '无名氏', '冰肌玉骨，不与凡花数。\n一点破清香，这心情、更谁为主。\n愁春归晚，时被雨廉纤，琼枝上，泪淋浪，似恨孤芳处。\n幽姿标格，独向江头路。\n拟待使君来，把芳心、丁宁分付。\n疏篱茅舍，回首试轻辞，争望远，嫁东风，对玉堂同处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19062, '蓦山溪', '无名氏', '梅传春信，又报年华晚。\n昨夜半开时，似雪到、梢头未遍。\n凝酥缀粉，绰约玉肌肤，香黯淡，月朦胧，谁是黄昏伴。\n故园深处，想见孤根暖。\n千里未归人，向此际、只回泪眼。\n凭谁为我，折寄一枝来，凝睇久，俯层楼，忍更闻羌管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19063, '蓦山溪', '无名氏', '素苞淡注。\n自是东君试。\n占断陇头光，正雪里、前村独步。\n一枝竹外，日暮怯轻寒，山色远，水声长，寂寞江头路。\n小桥斜渡。\n人静销魂处。\n淡月破黄昏，影浮疏、清香暗度。\n竹篱茅舍，斜倚为谁愁，应有恨，负幽情，惟恐风姨妒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19064, '蓦山溪', '无名氏', '沙塘水浅，又一番春信。\n玉骨不知寒，亲修篁、几苞隐映。\n幽香荏苒，不让洒蔷薇，弯月冷，漫涟漪，云断暗香影。\n朱扉深处。\n谢绝尘埃境。\n百草未开花，□茕然、教伊孤冷。\n东风世态，只恋碧桃枝，曲玉管，且休吹，免使成遗恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19065, '蓦山溪', '无名氏', '前村昨夜，先报春消息。\n庾岭一枝开，见行人、频频顾惜。\n东君布巧，妆蕊似裁□，疏竹外，小溪边，雪里藏春色。\n朔风吹绽，不假和风拆。\n根暖独亨嘉，向百花、头先占得。\n高楼羌笛，且劝莫凄然，协帝梦，起商岩，须尽调羹力。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19066, '蓦山溪', '无名氏', '冰肌玉骨，不假铅黄借。\n岂是占年芳，又只恐、嫌春不嫁。\n十分清瘦，可有闲愁，沙路晚，雪村晴，半幅江南画。\n林间系马，曾忆关山夜。\n醉袖惹香归，误几回、灯前娇雅。\n如今老矣，无计奈春何，人去後，独来时，风月闲亭榭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19067, '蓦山溪', '无名氏', '前村雪里，度一枝春信。\n况自占年芳，淡妆梳、常嫌脂粉。\n樱唇轻捧，何似鹤头红，香阵阵。\n回舆认。\n摘有金卮酝。\n佳人嗅处，微把香尘喷。\n懊恼故无言，使人□、重重再问。\n它年寄与，惟有陇头人，春未困。\n香尤嫩。\n好与添风韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19068, '蓦山溪', '无名氏', '郊居牢落，一水流清浅。\n忆得去年冬，数枝梅、低临水畔。\n今朝重见，把酒祝东风，和雪看。\n整凝眸，宛若江南岸。\n浮生瞥尔，劝汝休嗟叹。\n不觉失芳心，柳腰□、纤纤仍换。\n一朝光景，休恁作浑闲，春不远。\n且追游，又办寻芳宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19069, '蓦山溪', '无名氏', '重黎默运，可意萦人处。\n清楚玉蕤仙，独幽栖、村溪月坞。\n冰腮露鬓，佳致在西湖，月出早，雪消迟，立马红墙序。\n寒梢微萼，点点蝇头许。\n欲露小檀心，似生怕、施朱红紫。\n返魂香细，堪吊独醒人，临泽国，袭清风，且咏离骚句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19070, '蓦山溪', '无名氏', '前村雪里，漏泄春光早。\n似待故人来，束芳心、幽香未老。\n溪边昨夜，雨过却参横，云旖旎，玉玲珑，不遣纤尘到。\n无情有意，寂寞谁知道。\n幽梦觉来时，淡无言、风清月。\n何郎去後，憔悴少新诗，空怅望，倚楼人，玉笛霜天晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19071, '蓦山溪', '无名氏', '竹篱茆舍，底是藏春处。\n玉蓓锁檀心，带黄昏、轻烟细雨。\n神清骨莹，端似雪堂仙，临岁晚，傲寒威，寂寞江村住。\n琼林阆苑，有信终归去。\n冷暖笑凡情，辨南枝、北枝几许。\n灵芳绝艳，知肯为谁容，东阁里，西湖畔，总与花为主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19072, '蓦山溪', '无名氏', '岁寒辽邈，望断江南信。\n墙外一枝斜，对兰堂、绮罗隐映。\n水清月淡，疑是寿阳妆，烟浪急，小桥横，点点疏清影。\n天姿潇洒，不减瑶台韵。\n占断玉楼春，被松筠、笑他孤冷。\n幽人何在，无处觅馀寒，疏雨过，泪痕深，枉了衷肠恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19073, '蓦山溪', '无名氏', '危栏独倚，往事思量遍。\n回首掩朱扉，敛云鬓、闲拈针线。\n轻罗碎翦，缝个小梅花，灯闪闪，夜沈沈，玉指轻轻拈。\n寒苞素艳，浑似枝头见。\n半拆与初开，谁赢得、江南手段。\n玉冠斜插，惟恨欠清香，风动处，月明时，不怕吹羌管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19074, '蓦山溪', '无名氏', '孤村冬杪，有景真堪画。\n茅舍绕疏篱，见一枝、寒梅潇洒。\n欲将诗句，拟待说包容，辞未尽，意悠悠，难把精神写。\n临溪疏影，都是前人话。\n此外更何如，更须索、良工描下。\n明窗净几，长做小图看，高楼笛，尽教吹，不怕随声谢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19075, '蓦山溪', '无名氏', '梅梢破萼，已见春心了。\n别有淡容仪，又不与、嫣然同笑。\n东风翦蜡，簇作闹蛾儿，冰未泮，水犹寒，散在千林表。\n轻衫小帽，行尽荒山道。\n一点麝脐香，恼著人、多多少少。\n月斜门掩，消损怕黄昏，清影乱，翠帏深，且喜归来早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19076, '蓦山溪', '无名氏', '小山苍翠，竹影横窗畔。\n青缕断薰炉，觉身居、风台月观。\n清香招近，谁为植幽丛，金作蓓，蕾成花，尚带鹅黄浅。\n汉宫半额，未许人间见。\n不比岭前梅，问无因、天高水远。\n宜烟宜雨，淡淡一枝春，乘好兴，缀新诗，只恐冰生砚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19077, '蓦山溪', '无名氏', '江南春信，已过长安路。\n柳眼尚贪眠，又争知、先传春去。\n东风漏泄，休更垂杨，深雪里，一枝开，谁占先春处。\n当时马上，回首曾凝顾。\n水浅月黄昏，倚琼枝、谁家亭户。\n一声羌管，遗恨到如今，凭栏处，赏花时，莫使花轻负。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19078, '蓦山溪', '无名氏', '当时曾见，上苑东风暖。\n今岁却相逢，向烟村、亭边驿畔。\n垂鞭立马，一晌黯无言，江南信，寿阳人，怅望成断肠。\n琼妆雪缀，满野空零乱。\n谁是倚阑干，更那堪、胡笳羌管。\n疏枝残蕊，犹懒不娇春，水清浅，月黄昏，冷淡从来惯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19079, '梅花引', '无名氏', '园林静。\n萧索景。\n寒梅漏泄东君信。\n探春回。\n探春回。\n四时却被，伊家苦相催。\n江村畔。\n开烂熳。\n看看又近年光晚。\n绽芬芳。\n喷清香。\n寿阳宫里，爱学靓梳妆。\n夭桃红杏夸颜色。\n争似情怀雪中拆。\n冒严寒。\n冒严寒。\n游蜂戏蝶，莫作等闲看。\n故人别後知何处。\n春色岭头逢驿使。\n赠新诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19080, '绿头鸭・多丽', '无名氏', '敛同云。\n破腊雪霁前村。\n占阳和、孤根先暖，数枝已报新春。\n如青女、谩同素质，笑姑射、难并天真。\n疏影横斜，澄波清浅，暗香浮动月黄昏。\n山驿畔，行人立马，回首几销魂。\n江南远，陇使趁程，踏尽冰痕。\n有个人人，玉肌偏似，移我常对金尊。\n拈纤枝、鬓边斜戴，嗅芳蕊、眉晕潜分。\n素脸笼霞，香心喷日，寿阳妆罢酒初醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19081, '金盏倒垂莲', '无名氏', '依约疏林，见盈盈春意，几点霜蕤。\n应是东君，试手作芳菲。\n粉面倚、天风微笑，是日暖、雪已晴时。\n人静么凤翩翩，踏碎残枝。\n幽香浑无著处，甚一般雨露，独占清奇。\n淡月疏云，何处不相宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19082, '梅香慢', '无名氏', '高阁寒轻，映万朵芳梅，乱堆香雪。\n未待江南，早冠成花，先占一阳佳节。\n翦彩凝酥，无处学、天然奇绝。\n便寿阳妆，工夫费尽，艳姿终别。\n风里弄轻盈，掩珠英明莹，待腊飘烈。\n莫放芳菲歇。\n剩永宵欢赏，酒酣吟折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19083, '马索', '无名氏', '晓窗明，庭外寒梅向残月。\n吴溪庾岭，一枝偷把阳和泄。\n冰姿素艳，自然天赋，品格真殊常别。\n奈北人、不识南枝，唤作腊前杏先发。\n奇绝。\n照溪临水，素禽飞下，玉羽琼芳斗清洁。\n懊恨春来何晚，伤心邻妇争先折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19084, '定风波慢', '无名氏', '漏新春、消息前村，数枝楚梅轻绽。\n□雪艳精神，冰肤淡伫，姑射依稀见。\n冷香凝，金蕊浅。\n青女饶伊妒无限。\n堪羡。\n似寿阳妆阁，初匀粉面。\n纤条绿染。\n异群葩、不似和风扇。\n向深冬、免使游蜂舞蝶，撩拨春心乱。\n水亭边，山驿畔。\n立马行人暗肠断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19085, '庆春泽', '无名氏', '晓风严，正萧然兔园，薄雾微罩。\n梅渐弄白，耸危苞、匀胜胭脂，半点琼瑰小。\n望江南、信息何杳。\n纵寿阳妍姿，学就新妆，暗香须少。\n幽艳满寒梢，更游蜂舞蝶，浑无飞绕。\n天赋品格，借东皇施巧。\n孤根占得春前俊，笑雪霜、谩欺容貌。\n况此花高强，终待和羹，肯饶芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19086, '尉迟杯', '无名氏', '岁云暮。\n叹光阴苒苒能几许。\n江梅尚怯馀寒，长安信音犹阻。\n春风无据。\n凭阑久，欲去还凝伫。\n忆溪边月下徘徊，暗香疏影庭户。\n朝来冻解霜消，南枝上，香英数点微露。\n把酒看花，无言有泪，还是那时情绪。\n花依旧、晨妆何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19087, '木兰花慢', '无名氏', '望阳生渐布，见梅萼、暖初回。\n向雪里、一枝才苞，素艳已占春台。\n烟笼半含粉面，透清香、暗触满襟怀。\n可惜前村望断，魏林庾岭栽培。\n皑皑。\n嫩蕊清光，凝笑也恁风猥。\n但折取行人，途中对酒，不用尊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19088, '木兰花慢', '无名氏', '饱经霜古树，怕春寒、趁腊引青枝。\n逗一点阳和，隔年信息，远报佳期。\n凄葩未容易吐，但凝酥半面点胭脂。\n山路相逢驻马，暗香微染征衣。\n风前袅袅含情，虽不语、引长思。\n似怨感芳姿，山高水远，折赠何迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19089, '最高楼', '无名氏', '梅花好，千万君须爱。\n比杏兼桃犹百倍。\n分明学得嫦娥样，不施朱粉天然态。\n蟾宫里，银河畔，风霜耐。\n岭上故人千里外。\n寄去一枝君要会。\n表江南信相思。\n清香素艳应难对。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19090, '尾犯', '无名氏', '轻风淅淅，正园林萧索，未回暖律。\n岭头昨夜，寒梅初发，一枝消息。\n香苞渐拆。\n天不许、雪霜欺得。\n望东吴，驿使西来，为谁折赠春色。\n玉莹冰清容质。\n迥不同、群花品格。\n如晓妆匀罢，寿阳香脸，徐妃粉额。\n好把琼英摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19091, '望远行', '无名氏', '重阴未解，又早是、年时梅花争绽。\n暗香浮动，疏影横斜，月淡水清亭院。\n好是前村，雪里一枝开处，昨夜东风布暖。\n动行人、多少离愁肠断。\n凝恋。\n天赋自然雅态，似寿阳、初匀粉面。\n故人折赠，欣逢驿使，只恐陇头春晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19092, '宝鼎现', '无名氏', '东君著意，化工恩被，灼灼妖艳。\n袅嫩梢轻蓓，萦风惹露，偏早香英绽。\n似向人、故矜夸标致，倚阑全如顾盼。\n尚困怯馀寒，柔情弱态，天真无限。\n断桥压柳时非浅。\n先百花、风光独占。\n当送腊初归，迎春欲至，芳姿偏婉娈。\n料碎翦就，缯纨辉丽，更把胭脂重染。\n自赋得、一般容冶，宛胜神仙妆脸。\n折送小阁幽窗，酷爱处、令亲几砚。\n尽孜孜观赏，不枉人称妙选。\n待密付、如膏雨泽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19093, '望梅花', '无名氏', '寒梅堪羡。\n堪羡轻苞初展。\n被天人、制巧妆素艳。\n群芳皆贱。\n碎翦月华千万片。\n缀向琼枝欲遍。\n小庭幽院。\n雪月相交无辨。\n影玲珑、何处临溪见。\n谢家新宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19094, '喜迁莺', '无名氏', '南枝向暖。\n乍秀出庾岭，梅英初吐。\n玉颊轻匀，琼腮微抹，姑射冰容相许。\n几回立马凝伫，影映寒光霜妒。\n□尽占，在百花头上，严冬独步。\n芳华春意早，昨夜一番，雪里开无数。\n万蕊千梢，铅堆粉污，总是化工偏赋。\n月明暗香浮动，休使龙吟声苦。\n且留取。\n待时时，频倚阑干重顾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19095, '喜迁莺', '无名氏', '腊残春未。\n正候馆梅开，墙阴雪里。\n冷艳凝寒，孤根回暖，昨夜一枝春至。\n素苞暗香浮动，别有风流标致。\n谢池月，最相宜，疏影横斜临水。\n谁为。\n传驿骑。\n陇上故人，不见今千里。\n寄与东君，徒教知人，别後岁寒清意。\n乱山万叠何在，但有飞云天际。\n故园好，早归来，休恋繁桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19096, '喜迁莺', '无名氏', '霜凝雪，正斗标临丑，三阳将近。\n万木凋零，群芳消歇，禁苑有梅初盛。\n异香似薰沈水，素色瑞如玉莹。\n人尽道，第一番，天遣先占春信。\n标韵。\n尤耿耿。\n月观水亭，谁解怜疏影。\n何逊扬州，拾遗东阁，一见便生清兴。\n望林止渴功就，不数夭桃繁杏。\n岁寒意，看结成秀子，归调商鼎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19097, '喜迁莺', '无名氏', '一阳初起。\n渐庾岭梅雪，才苞香蕊。\n品格清高，姿容闲雅，别受化工深意。\n放开独占严景，不使混同凡卉。\n微雨霁。\n似玉容寂寞，无言有泪。\n难比。\n凝素态，不共艳阳，桃杏争妍丽。\n疑是佳人，巧拈香酥，枝上玉纤轻缀。\n前村可惜无赏，好近天庭阶砌。\n成实後，有调和鼎鼐，一般滋味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19098, '折红梅', '无名氏', '陇上残雪，曲水流断，淑气潜通。\n群花冷未吐，夜来梅萼，数枝繁红。\n光夺化工。\n发艳色、不染东风。\n信凭晓风，难压精神，占青春未上，别是标容。\n天香渐杳，似蓬阙玉妃，酒困娇慵。\n只愁恐、上阳爱惜，和种移向瑶宫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19099, '折红梅', '无名氏', '倚花阑清晓，裴回探得，南枝初绽。\n通春意、漏巧斗奇，东君首先回暖。\n盈盈素面。\n刚强点、胭脂深浅。\n是他自有，标格清香，恣千种妖饶，万般闲雅。\n移时细看。\n算浓雪严霜，怎生拘管。\n也拟是、小桃未蕊，依约杏添清伴。\n笛声休怨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19100, '折红梅', '无名氏', '忆笙歌筵上，匆匆见了，□□相别。\n红炉暖、画帘绣阁，曾共鬓边斜插。\n南枝向暖，北槛里、春风犹怯。\n也应别後，不减芳菲，念咫尺阑干，甚时重折。\n清风间发，如天与浓香，粉匀檀颊。\n纱窗影、故人凝处，冷落暮天残雪。\n一轩明月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19101, '折红梅', '无名氏', '睹南翔征雁，疏林败叶，凋霜零乱。\n独红梅、自守岁寒，天教最後开绽。\n盈盈水畔。\n疏影蘸、横斜清浅。\n化工似把，深色胭脂，怪姑射冰姿，剩与红间。\n谁人宠眷。\n待金锁不开，凭阑先看。\n曾飞落、寿阳粉额，妆成汉宫传遍。\n江南风暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19102, '满庭霜・满庭芳', '无名氏', '一种江梅，偷传春信，夜来先绽南枝。\n嫩苞寒萼，妆点缀胭脂。\n雪里浑迷素质，明月下、惟有香肌。\n山村路，人家舍窄，低亚水边篱。\n偏宜。\n寿阳女，新妆淡淡，粉面曾施。\n更胡笛羌管，塞曲争吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19103, '满庭霜・满庭芳', '无名氏', '园林萧索，亭台寂静，万木皆冻凋伤。\n晓来初见，一品蜡梅芳。\n疑是黄酥点缀，超群卉、独占中央。\n堪闲玩，檀心紫蕊，清雅喷幽香。\n华堂。\n欢会处，陶陶共醉，相劝瑶觞。\n逞风流开早，不畏严霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19104, '黄莺儿', '无名氏', '香梢匀蕊先回暖，点点胭脂轻衬。\n红苞隐映疏篁，红翠相间。\n方瑞雪乍晴时，爱日初添线。\n五云楼上遥看，似睹溪边，仙子妆面。\n堪羡。\n影转玉枝斜，艳拂朝霞浅。\n就中妖娆，独得芬芳，偏教容易琼苑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19105, '锦堂春・锦堂春慢', '无名氏', '腊雪初晴，冰销凝泮，寻幽闲赏名园。\n时向长亭登眺，倚遍朱阑。\n拂面严风冻薄，满阶前、霜叶声乾。\n见小台深处，数叶江梅，漏泄春权。\n百花休恨开晚，奈韶华瞬息，常放教先。\n非是东君私语，和煦恩偏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19106, '瑶台月', '无名氏', '严风凛冽，万木冻，园林肃静如洗。\n寒梅占早，争先暗吐香蕊。\n逞素容、探暖欺寒，遍妆点、亭台佳致。\n通一气，超群卉。\n值腊後，雪清丽。\n开筵共赏，南枝宴会。\n好折赠、东君驿使。\n把岭头信息远寄。\n遇诗朋酒侣，尊前吟缀。\n且优游，对景欢娱，更莫厌、陶陶沈醉。\n羌管怨，琼花缀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19107, '玉梅香慢', '无名氏', '寒色犹高，春力尚怯。\n微律先催梅拆。\n晓日轻烘，清风烦触，凝散数枝残雪。\n嫩英妒粉，嗟素艳、有蜂蝶。\n全似人人，向我依然，顿成离缺。\n裴回寸肠万结。\n又因花、暗成凝咽。\n拈蕊怜香，不禁恨深难绝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19108, '双头莲', '无名氏', '触目庭台，当岁晚凋残，恁时方见。\n琼英细蕊，似美玉碾就，轻冰裁翦。\n暗想蜂蝶不知，有清香为援。\n深疑是，傅粉酡颜，何殊寿阳妆面。\n惟恐易落难留，仗何人巧把，名词褒羡。\n狂风横雨，枉堕落、细蕊纷纷千片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19109, '夏云峰', '无名氏', '琼结苞，酥凝蕊，粉心轻点胭脂。\n疑是素娥妆罢，玉翠低垂。\n化工深意，巧付与、别个标仪。\n怎奈向，风寒景里，独是开时。\n缘何不与春期。\n此花又、岂肯争竟芳菲。\n疑雨恨烟，忍见岭畔江湄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19110, '庆清朝', '无名氏', '北陆严凝，东郊料峭，化工争付归期。\n前村夜来雪里，先见纤枝。\n想像靓妆淡伫，钗头翡翠茧蛾儿。\n冰壶莹，坐间静对，姑射仙姿。\n潇洒处，非艳冶最奇。\n是名赋、处士新诗。\n尊前坐曲，忍听羌管频吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19111, '烛影摇红', '无名氏', '点点飞香，见梅知道春心透。\n怕寒不卷玉楼帘，羞与花同瘦。\n手拈青枝频嗅。\n诮冷落、蔷薇金斗。\n翻惊绿鬓，不似芳姿，年年依旧。\n绕破凝酥，满园桃李看看又。\n江南幽梦了无痕，啼晕残襟袖。\n鸳被有谁温绣。\n怎敢更、十分酒。\n伴君独自，几个黄昏，月明时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19112, '凤凰台忆吹箫・凤凰台上忆吹箫', '无名氏', '红蓓珠圆，素蕤玉净，南荒已报春还。\n便迤逦，云开五岭，雪霁群蛮。\n喜见东君信息，应不管、潘鬓新班。\n凭谁寄，心萦秋水，目断春山。\n长记小桥斜渡，潇洒处，苇篱茅舍三间。\n肯伴我、风光赏遍，月影疑残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19113, '东风第一枝', '无名氏', '腊雪犹凝，东风递暖，江南梅早先拆。\n一枝经晓芬芳，几处漏春信息。\n孤根寒艳，料化工、别施恩力。\n迥不与、桃李争妍，自称寿阳妆饰。\n雪烂熳、怨蝶未知，嗟燕孤、画楼绮陌。\n暗香空写银笺，素艳谩传妙笔。\n王孙轻顾，便好与、移栽京国。\n更免逐、羌管凋零，冷落暮山寒驿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19114, '东风第一枝', '无名氏', '溪侧风回，前村雾散，寒梅一枝初绽。\n雪艳凝酥，冰肌莹玉，嫩条细软。\n歌台舞榭，似万斛、珠玑飘散。\n异众芳，独占东风，第一点装琼苑。\n青萼点、绛唇疏影，潇洒喷、紫檀龙麝。\n也知青女娇羞，寿阳懒匀粉面。\n江梅腊尽，武陵人、应知春晚。\n最苦是，皎月临风，画楼一声羌管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19115, '昼夜乐', '无名氏', '一阳生後风光好。\n百花瘁，群木槁。\n南枝探暖欺寒，嘉卉争先占早。\n晓来风送清香杳。\n映园林、报春来到。\n素艳自超群，似姑射容貌。\n画堂开宴邀朋友，赏琼英，同欢笑。\n陇头寄信丁宁，楼上新妆斗巧。\n对景乘兴倾芳酒，　沈醉、玉山频倒。\n结实用和羹，是真奇国宝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19116, '柳初新', '无名氏', '千林凋谢严凝日。\n青帝许、梅花拆。\n孤根回暖，前村雪里，昨夜一枝凝白。\n天匠与、雕琼镂玉，淡然非、人间标格。\n别有神仙第宅。\n绣帘垂、碧纱窗隔。\n月明风送，清香苒苒，著摸美人词客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19117, '蜡梅香', '无名氏', '爱日初长。\n正园林才见，万木凋黄。\n槛外朝来，已见数枝，复欲掩映回廊。\n赐与东皇。\n付芳信、妆点江乡。\n想玉楼中，谁家艳质，试学新妆。\n桃杏苦寻芳。\n纵成蹊，岂能似恁清香。\n素艳妖娆，应是尽夜，曾与明月添光。\n瑞雪冰霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19118, '满江红', '无名氏', '林外溪边，深深见、一林寒雪。\n惟觉有、袭人襟袖，暗香不绝。\n天与风流标格在，肯同桃杏开时节。\n也须烦、玉手折将来，和明月。\n调鼎事，君休说。\n龙笛韵，空悲咽。\n将何助清赏，待传佳阕。\n君不见广平词赋丽，挥毫弄翰心如铁。\n便直饶、何逊在扬州，成虚设。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19119, '选冠子', '无名氏', '憔悴江山，凄凉古道，寒日澹烟残雪。\n行人立马，手折江梅，红萼素英初发。\n月下瑶台，弄玉飞琼，不老年年春色。\n被东君、唤遣娆红，高韵且饶清白。\n因动感、野水溪桥，竹篱茅舍，何似玉堂金阙。\n天教占了，第一枝春，何处不宜风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19120, '选冠子', '无名氏', '庾岭烟光，江南风景，冷落岁寒庭院。\n疏林万木冻折，孤根独犯，晓霜回暖。\n萼点胭脂，粉凝芳叶，依稀几枝初绽。\n上层楼、月夜凭阑，风送暗香清远。\n嗟往昔、汉妃临鸾，新妆才饰，艳绝人间金钿。\n东君信息，造化工夫，却笑众葩开晚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19121, '落梅慢・落梅', '无名氏', '带烟和雪，繁枝澹伫，谁将粉融酥滴。\n疏枝冷蕊厌群芳，年年常占春色。\n江路溪桥谩倒，袅袅风中无力。\n暗香浮动冰姿，明月里，想无花比高格。\n争奈光阴瞬息。\n动幽怨、潜生羌笛。\n新花斗巧，有天然闲态，倚阑堪惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19122, '早梅香', '无名氏', '北帝收威，又探得早梅，漏春消息。\n粉蕊琼苞，拟将胭脂，轻染颜色。\n素质盈盈，终不许、雪霜欺得。\n奈化工、偏宜赋与，寿阳妆饰。\n独自逞冰姿，比夭桃繁杏，迥然殊别。\n为报山翁，逢此有花，樽前须攀折。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19123, '马家春慢', '无名氏', '珠箔风轻，绣帘浪卷，乍入人间蓬岛。\n斗玉阑干，渐庭馆帘栊春晓。\n天许奇葩贵品，异繁杏、夭桃轻巧。\n命化工、倾国风流，□与一枝纤妙。\n樽前五陵年少。\n纵丹青异格，难别颜貌。\n悲露凝烟，困红娇额，微鼙低笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19124, '望梅', '无名氏', '画阑人寂，喜轻盈照水，犯寒先拆。\n袅芳枝、云缕鲛绡，露浅浅涂黄，汉宫娇额。\n翦玉裁冰，已占断、江南春色。\n恨风前素艳，雪里暗香，偶成抛掷。\n如今眼穿故国。\n待拈花嗅蕊。\n时话思忆。\n想陇头、依约飘零，甚千里芳心，杳无消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19125, '望梅', '无名氏', '小寒时节，正同云暮惨，劲风朝烈。\n信早梅、偏占阳和，向日暖临溪，一枝先发。\n时有香来，望明艳、瑶枝非雪。\n想玲珑嫩蕊，绰约横斜，旖旎清绝。\n仙姿更谁并列。\n有幽香映水，疏影笼月。\n且大家、留倚阑干，对绿醑飞觥，锦笺吟阅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19126, '洞仙歌', '无名氏', '蓬莱宫殿。\n去人间三万。\n玉体仙娥有谁见。\n被月朋雪友，邀下琼楼，溪桥畔。\n相对寒光浅浅。\n一般天上格，独带真香，冰麝犹嫌未清远。\n似太真望幸，一饷销凝，愁未惯。\n消瘦难禁素练。\n又只恐、东风破寒来，伴神女同归，阆峰仙苑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19127, '洞仙歌', '无名氏', '摧残万物，不忍临轩槛。\n待得春来是早晚。\n向纷纷、雪里开，一枝见。\n清香满。\n漏泄东君先绽。\n暗香浮动、疏影横斜，只这些儿意不浅。\n怎禁他，澹澹地、匀粉弹红，争些儿、羞杀桃腮杏脸。\n为传语、东风共垂杨，奈辛苦，千丝万丝撩乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19128, '洞仙歌', '无名氏', '断云疏雨，冷落空山道。\n匹马又重到。\n望孤村，两三间、茅屋疏篱，溪水畔、一簇芦花晚照。\n寻思行乐地，事去无痕，回首湘波与天杳。\n叹人生几度，能醉金钗，青镜里、赢得朱颜未老。\n又枝头、一点破黄昏，问客路春风，为谁开早。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19129, '洞仙歌', '无名氏', '梳风洗雨，兰蕙摧残後。\n玉蕊檀芳做霜晓。\n板桥平，溪岸小。\n月下归来、乘露冷，赢得清香满抱。\n一枝春在手，细嗅重看，风味人间自然少。\n拟欲问东君，妙语难寻，搜索尽、池塘春草。\n想不是、诗人赏幽姿，纵竹外横斜，是谁知道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19130, '摸鱼儿', '无名氏', '岁华向晚，遥天布同云，霁雪轻飞。\n前村昨夜漏春光，楚梅先放南枝。\n叹东君运巧思。\n裁琼镂玉妆繁蕊。\n花中偏异。\n解向严冬逞芳菲。\n免使游蜂粉蝶戏。\n梁台上，汉宫里。\n殷勤仗、高楼羌管休吹。\n何妨留取凭阑干，大家吟玩欢醉。\n待明年，念芳草、王孙万里。\n归未得、仙源应是。\n又被花、开向天涯，泪洒东风对桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19131, '春雪间早梅', '无名氏', '梅将雪共春。\n彩艳灼灼不相因。\n逐吹霏霏能争密，排枝碎碎巧妆新。\n谁令香来满坐，独使净敛无尘。\n芳意饶呈瑞，寒光助照人。\n玲珑次第开已遍，点缀坐来频。\n那是俱怀疑似，须知造化，两各逼天真。\n荧煌清影初乱眼，浩荡逸气忽迷神。\n未许琼花并重，将从玉树相亲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19132, '万年欢', '无名氏', '北陆风回，顿园林凋尽，庭院岑寂。\n潇洒寒梅，偷报艳阳消息。\n素澹英姿粹质。\n天赋与、出伦标格。\n一枝向、雪里初开，纤说清香寻得。\n神仙乍离姑射。\n更琼妆翠佩，冰莹肌骨。\n仿佛华清浴罢，懒匀脂泽。\n陇上休轰怨笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19133, '万年欢', '无名氏', '天气严凝，乍寒梅数枝，岭上开拆。\n傅粉凝脂，疑是素娥妆饰。\n先报阳和信息。\n更雪月、交光一色。\n因追念，往日欢游，共君携手同摘。\n别来又经岁隔。\n奈高楼梦断，无计寻觅。\n冷艳寒容，啼雨恨烟愁湿。\n似向人前泪滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19134, '雨中花・夜行船', '无名氏', '梦破江南春信，渐入江梅，暗香初发。\n乞与横斜疏影，为怜清绝。\n梁苑相如，平生有赋，未甘华发。\n便广寒争遣，韶华惊怨，讵妨轻折。\n扬州二十四桥歌吹，不道画楼声歇。\n生怕有、江边一树，要堆轻雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19135, '早梅芳・喜迁莺', '无名氏', '冰唯清，玉唯润。\n清润无风韵。\n此花风韵，自然清润传香粉。\n故应春意别，不使凡英恨。\n到春前腊後，长是寄芳信。\n此情闲，此意远。\n一点萦方寸。\n风亭水馆，解与行人破离恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19136, '婆罗门・婆罗门引', '无名氏', '江南地暖，数枝先得岭头春。\n分付似、翦玉裁冰。\n素质偏怜匀澹，羞杀寿阳人。\n算多情留意，偏在东君。\n暗香旋生。\n对澹月与黄昏。\n寂寞谁家院宇，斜掩重门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19137, '踏青游', '无名氏', '岭上梅残，堤畔柳眠娇小。\n绽数枝、横烟临沼。\n既大雅，且丽，繁而不扰。\n冒寒来、游蜂红蝶尚阻，年年占得春早。\n澹白轻红，清香迎芳道。\n更情与、碧天如扫。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19138, '绛都春', '无名氏', '东君运巧。\n向枝头点缀，琼英虽小。\n全是一般，风味花中最轻妙。\n横斜疏影当池沼。\n似弄粉、初临鸾照。\n众芳皆有，深红浅白，岂能争早。\n莫厌金樽频倒。\n把芳酒赏花，追陪欢笑。\n有愿告天，愿天多情休教老。\n奇花也愿休残了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19139, '雪梅香', '无名氏', '岁将暮，云帆风卷正凄凉。\n见梅花呈瑞，素英澹薄含芳。\n千片逞姿向江国，一枝无力倚邻墙。\n凝眸望，昨夜前村，雅态难忘。\n争妍斗鲜洁，皓彩寒辉，冷艳清香。\n姑射真人，更兼粉傅容光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19140, '雪梅香', '无名氏', '冻云深，六出瑶花满长空。\n渐飘来呈瑞，皑皑万里皆同。\n荒野枯冰竦欲折，小亭寒梅吐轻红。\n香清□，疏影横斜，照水熔熔。\n临风。\n传芳信，驿使来自，庾岭南峰。\n占早争先，总无粉蝶游蜂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19141, '千秋岁', '无名氏', '腊残春近。\n江上梅开粉。\n一枝漏泄东君信。\n寿阳妆面靓，姑射冰姿莹。\n似浅杏。\n清香试与分明认。\n只恐霜侵破，又怕风吹损。\n待折取，还不忍。\n莫将花上貌，来点多情鬓。\n凝睇久，行人立马成遗恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19142, '月上海棠', '无名氏', '南枝昨夜先回暖。\n便临寒、开花暗香远。\n化工忒，把琼瑶、恣情裁翦。\n皑皑的、点缀梢头又遍。\n横斜影蘸清溪浅。\n似玉人、临鸾照粉面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19143, '眼儿媚', '无名氏', '前时同醉曲江滨。\n初样小梅春。\n花残人远，几经风雨，结子青青。\n谁知别後无肠断，行尽水云程。\n修峰万仞，邮亭息，独对黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19144, '相见欢', '无名氏', '月明疏影林间。\n水潺潺。\n一点浓香十里、渡关山。\n且莫负。\n好分付。\n冷无眠。\n只怕笛声呜咽、到愁边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19145, '捣练子', '无名氏', '捣练子，赋梅枝。\n暖借东风次第吹。\n自是百花留不住，让教先发放春归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19146, '捣练子', '无名氏', '捣练子，赋梅芳。\n柳绿桃红谩点妆。\n试问仙标横竹外，敢同高节伴冰霜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19147, '捣练子', '无名氏', '捣练子，赋梅红。\n玉体凝酥半醉中。\n诗酒兴来须要早，忍看红雨落西东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19148, '捣练子', '无名氏', '捣练子，赋梅香。\n蕙魄兰魂又再阳。\n只为人间无著处，借他龙笛返仙乡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19149, '捣练子', '无名氏', '捣练子，赋梅英。\n枝上商量细细生。\n不是根株贪结子，被吹羌笛两三声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19150, '捣练子', '无名氏', '捣练子，赋梅妆。\n镜里佳人傅粉忙。\n额子画成终未是，更须插向鬓云傍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19151, '捣练子', '无名氏', '捣练子，赋梅音。\n云底江南树树深。\n怅望故人千里远，故将春色寄芳心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19152, '捣练子', '无名氏', '捣练子，赋梅青。\n休共檀梨取次争。\n叶底青青如豆小，已知金鼎待和羹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19153, '鹧鸪天', '无名氏', '冷落人间昼掩门。\n泠泠残粉成纹。\n几枝疏影溪边见，一拂清香马上闻。\n冰作质，月为魂。\n萧萧细雨入黄昏。\n人间暂识东风信，梦绕江南云水村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19154, '鹧鸪天', '无名氏', '梦草池塘春意回。\n巧传消息是寒梅。\n北枝休羡南枝暖，凭仗东风次第开。\n酥点萼，粉匀腮。\n未攀已得好香来。\n西邻且莫吹羌笛，留待行春把酒杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19155, '鹧鸪天', '无名氏', '雪屋冰床深闭门。\n缟衣应笑织成纹。\n雨中清泪无人见，月下幽香只自闻。\n长在眼，远销魂。\n玉奴那忍负东昏。\n隅然谪堕行云去，不入春风花柳村。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19156, '鹧鸪天', '无名氏', '小槛冬深未破梅。\n孤枝清瘦耐风埃。\n月中寂寞无人管，雪里萧疏近水栽。\n微雨过，早春回。\n阳和消息自天来。\n才根多谢东君力，琼蕊苞红一夜开。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19157, '鹧鸪天', '无名氏', '春入江梅破晚寒。\n冻枝惊鹊语声乾。\n离愁满抱人谁问，病耳初闻心也宽。\n风细细，露珊珊。\n可堪驿使道漫漫。\n斜梢待得人来後，簪向乌云仔细看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19158, '鹧鸪天', '无名氏', '别得东皇造化恩。\n黛消铅褪自天真。\n耻随庾岭花争白，疑是东篱菊返魂。\n风淡淡，月盈盈。\n麝煤沈馥动孤根。\n寒蝉冷蝶知何处，惟有蜂房不待春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19159, '浣溪沙', '无名氏', '水净烟闲不染尘。\n小山斜卧几枝春。\n夜寒香惹一溪云。\n粉淡朱轻妆未了，十分孤迥好精神。\n为伊清瘦却愁人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19160, '浣溪沙', '无名氏', '苒苒飞云横画阑。\n黄昏烟雨满江干。\n小梅香浅不禁寒。\n楼上风轻帘不卷，酒红销尽昼妆残。\n玉人斜拈一枝看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19161, '浣溪沙', '无名氏', '十月开花是子真。\n小春分付与精神。\n折来含露晓妆新。\n暖意便从窗下见，粉容何待鉴中匀。\n宛然长似玉华清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19162, '浣溪沙', '无名氏', '梅粉初娇拟嫩腮。\n一枝春信腊前开。\n玉英珠颗傍妆台。\n明月泛将疏影去，暗香疑是那人来。\n消魂独自立空阶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19163, '浣溪沙', '无名氏', '翦碎红娘舞旧衣。\n汉宫妆粉满琼枝。\n东风来晚未曾知。\n颜色不同香小异，瑶台春近宴回时。\n宝灯相引素娥归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19164, '浣溪沙', '无名氏', '梅与为名蜡与容。\n寒枝偏缀小金钟。\n插时只恐鬓边熔。\n疑是佳人薰麝月，起来风味入怀浓。\n暗香依旧月朦胧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19165, '浣溪沙', '无名氏', '梅与称名蜡与黄。\n枝无袅娜色无光。\n掩檀欺麝冠群芳。\n结处定缘蜂力就，开时微带蜜脾香。\n风标不减寿阳妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19166, '太常引', '无名氏', '行云踪迹杳无期。\n梅梢上、又春归。\n不道久别离。\n这一度、清香为谁。\n多情嘱付，庾楼羌管，凭仗且休吹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19167, '太常引', '无名氏', '江梅开似蕊珠宫。\n报桃李、又春风。\n蓦岫看前峰。\n待摘取、横斜盏中。\n魏林楚岭，素妆清绝，不与众芳同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19168, '小重山', '无名氏', '竹里清香帘影明。\n一枝照水弄精神。\n楼头横管罢龙吟。\n休三弄，留为与调羹。\n紫陌与青门。\n溪边浮动处，绝纤尘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19169, '小重山', '无名氏', '不是蛾儿不是酥。\n化工应道也难摹。\n花儿清瘦影儿孤。\n多情处，时有暗香浮。\n试问玉肌肤。\n夜来霜雪重，怕寒无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19170, '小重山', '无名氏', '天际春来都为君。\n依稀丹萼动，泛红云。\n恼人天气近黄昏。\n霜月底，山麝斗微薰。\n标格自天真。\n寿阳仙骨瘦，玉无纹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19171, '西地锦', '无名氏', '不与群花相续。\n独占春光速。\n幽香远远散西东，惟竹篱茅屋。\n羌管谁调一曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19172, '西地锦', '无名氏', '岭上初消残雪。\n有梅花先坼。\n东君造化多成翠，巧风韵奇绝。\n小院黄昏时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19173, '踏歌', '无名氏', '带雪。\n向南枝，一朵江梅坼。\n许多时、甚处收香白。\n占千葩百卉、先春色。\n拟莹洁。\n正广寒宫殿人窥隔。\n销魂处、画角数声彻。\n暗香浮动黄昏月。\n最潇洒处最奇绝。\n孤标迥、不与群芳列。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19174, '感皇恩', '无名氏', '翦玉蹙花苞，腊寒时候。\n间竹横溪自清瘦。\n黄昏时候，拂拂暗香微透。\n寿阳妆面恨，眉频斗。\n堪赏占断，三春先手。\n不是东君意偏有。\n百花羞尽，故教孤芳独秀。\n只愁明月夜，笛声奏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19175, '枕屏儿', '无名氏', '江国春来，留得素英肯住。\n月笼香，风弄粉，诗人尽许。\n酥蕊嫩，檀心小，不禁风雨。\n须东君、与他做主。\n繁杏夭桃，颜色浅深难驻。\n奈芳容，全不称，冰姿伴侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19176, '忆秦娥', '无名氏', '瑶台月。\n寒光零乱蒙香雪。\n蒙香雪。\n横枝疏影，动人清彻。\n分明姑射神仙骨。\n冰姿雪里难埋没。\n难埋没。\n百花头上，为春先发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19177, '望江南・忆江南', '无名氏', '梅花好，满树锦江边。\n不似武陵曾见日，清香冷艳扶尊前。\n销得醉留连。\n凭造化，分付与花权。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19178, '望江南・忆江南', '无名氏', '梅花好，依约透春光。\n记得佳人初睡起，巧临鸾鉴试新妆。\n粉面斗琼芳。\n江亭上，绕树嗅清香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19179, '品令', '无名氏', '山重云起。\n断桥外、池塘水。\n晓来风定，竹枝相亚，残阳影里。\n多少风流，都在冷香疏蕊。\n江南千里。\n问折得、谁能寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19180, '品令', '无名氏', '一阳生暖。\n见庾岭、梅初绽。\n琼枝玉树，浑如傅粉，寿阳妆面。\n疏影横斜，隐隐月溪清浅。\n前村雪里，向雪里、真难辨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19181, '品令', '无名氏', '雪花飞堕。\n有人报、江南意。\n博山炉畔，砚屏风里，铜盘寒水。\n赋得幽香，疏淡数枝相倚。\n绛肤黄蕊。\n另一种、高标致。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19182, '相思引', '无名氏', '笑盈盈，香喷喷。\n姑射仙人风韵。\n天与肌肤常素嫩。\n玉面犹嫌粉。\n斜倚小楼凝远信。\n多少往来人恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19183, '相思引', '无名氏', '半苞红，微露粉。\n潇洒早梅犹嫩。\n香入梦魂残酒醒。\n芳意相牵引。\n不畏晓霜侵手冷。\n欲折一枝芳信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19184, '庆金枝', '无名氏', '新春入旧年，绽梅萼、一枝先。\n陇头人待信音传。\n算楚岸、未香残。\n小枕风雪凭栏干。\n下帘幕、护轻寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19185, '菩萨蛮', '无名氏', '天威乱糁琼蕤密。\n一光吞尽千山碧。\n梅与雪争妍。\n孤香风暗传。\n玉骨从来瘦。\n不奈春。\n羌管一声残。\n水乡生暮寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19186, '菩萨蛮', '无名氏', '黄昏月暗清溪色。\n帘垂小阁霜华白。\n一夜玉玲珑。\n横斜水月中。\n小行孤影动。\n生怕惊花梦。\n半夜得春归。\n屏山人未归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19187, '菩萨蛮', '无名氏', '霜天不管青山瘦。\n轻云浅拂修眉皱。\n烟树隔潇湘。\n隔帆吹异香。\n影残春恨小。\n淡墨斜倒。\n无处著消愁。\n笛寒人倚楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19188, '南乡子', '无名氏', '梅蕊露鲜妍。\n雪态冰恣巧耐寒。\n南北枝头香不断，堪观。\n露琼苞粉未乾。\n画手写应难。\n横管休吹恐易残。\n留得佳人临晓际，凭栏。\n试把新妆比并看。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19189, '南乡子', '无名氏', '把酒对江梅。\n个是花中第一枝。\n冰雪肌肤潇洒态，须知。\n姑射仙人正似伊。\n东阁赋新诗。\n惭愧当年杜拾遗。\n月里何人横玉笛，休吹。\n正是芳梢著子时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19190, '南乡子', '无名氏', '莫作俗花看。\n珠有清香雪太寒。\n拟把千锺酬国艳，林间。\n醉倒犹嫌酒量悭。\n欲去更重攀。\n送尽斜阳未忍还。\n争得重城休上销，留连。\n借取冰轮照玉颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19191, '南乡子', '无名氏', '醉拈一枝春。\n此意谁人会得君。\n嫩白轻红才入手，盈盈。\n一似前时酒半醺。\n心眼两相亲。\n绝代风流恼杀人。\n粉蝶霜禽休怅望，叮咛。\n只要扬州作主盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19192, '南乡子', '无名氏', '栏槛对幽堂，翠叶枝头万朵霜。\n檀口乍开龙麝喷，非常。\n体胜佳人异骨香。\n花与月争光。\n偏引蜂儿戏绕墙。\n不与群英争艳丽，芬芳。\n溪落东君只淡妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19193, '南乡子', '无名氏', '凛冽苦寒时。\n万木凋枯力渐衰。\n昨夜前村深雪里，春回。\n庾岭南枝绽早梅。\n映月与清辉。\n驿使加鞭喜探回。\n风送馨香来小院，芳时。\n料想群花尚未知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19194, '南乡子', '无名氏', '把酒祝江梅。\n春到南枝早早开。\n人在陇头凝望久，徘徊。\n驿使如今尚未来。\n寄语莫相催。\n直待东风细剪裁。\n只恐未能传信息，妆台。\n先要飞来衬粉腮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19195, '戛金钗', '无名氏', '梅蕊破初寒，春来何太早。\n轻傅粉、向人先笑。\n比并年时较些少。\n愁底事，十分清瘦了。\n影静野塘空，香寒霜月晓。\n风韵减、酒醒花老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19196, '人月圆', '无名氏', '园林已有春消息，寻待岭头梅。\n一枝清淡，疏疏带雪，昨夜初开。\n芳心几点，东风多少，先为传来。\n不随红紫，纷纷闹闹，蝶妒蜂猜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19197, '一斛珠', '无名氏', '寒冰初泮。\n岭头一朵香苞绽。\n菡萏如画真堪羡。\n休逞随风、柳絮垂金线。\n月宫每嫖开较晓。\n寿阳又喜匀妆面。\n更闻何处鸣羌管。\n一曲一声、惹起神撩乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19198, '解佩令', '无名氏', '蕙兰无韵，桃李堪扫。\n都不数、凡花闲草。\n对月临风，长是伊、故来相恼。\n和魂梦、被他香到。\n江头陇畔，争先占早。\n一枝枝、看来总好。\n似凭风标，待发愿、春前祈祷。\n祝东君、放教不老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19199, '醉花阴', '无名氏', '粉妆一捻和香聚。\n教露华休妒。\n今日在尊前，只为情多，脉脉都无语。\n西湖雪过留难住。\n指广寒归去。\n去後又明年，人在江南。\n梦到花开处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19200, '醉花阴', '无名氏', '霓裳浅艳来何处。\n不是闲云雨。\n雪苑旧精神，燕席吟窗，昨夜生轻素。\n阑珊岂是东风妒。\n惜暗香分付。\n香在玉清宫，不惹年华，只带春寒去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19201, '扫地舞', '无名氏', '酥点萼。\n玉碾萼。\n点时碾时香雪薄。\n才折得。\n春方弱。\n半掩朱扉，垂绣幕。\n怕吹落。\n拈一饷。\n嗅一饷。\n拈时嗅时宿酒忘。\n春争上。\n不忍放。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19202, '玉楼人', '无名氏', '去年寻处曾持酒。\n还是向、南枝见後。\n宜霜宜雪精神，没些儿、风味减旧。\n先春似与群芳斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19203, '燕归梁', '无名氏', '月里云装冷艳裁。\n独秀在岩隈。\n雪中昨夜一枝开。\n探春色、岁前来。\n清香折得，多情寄与，人向陇头回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19204, '忆人人・鹊桥仙', '无名氏', '密传春信。\n微妆晓景，淡伫香苞欲绽。\n临风虽未吐芳心，奈暗露、盈盈粉面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19205, '忆人人・鹊桥仙', '无名氏', '前村深雪，难寻幽艳，无奈清香漏绽。\n烟梢霜萼出墙时，似暗妒、寿阳妆面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19206, '采桑子', '无名氏', '阳和欲报春来也，先上南枝。\n桃李休疑。\n折遍香梢人未知。\n黄昏小院谁攀折，疏影斜。\n半掩朱扉。\n旋嗅清香月下归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19207, '采桑子', '无名氏', '江南春信梅先赋，休道春迟。\n映竹开时。\n姑射仙人雪作肌。\n青楼且莫吹羌管，留劝金卮。\n折取高枝。\n香满名园蝶未知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19208, '采桑子', '无名氏', '南枝淡伫无妖艳，蜡蕊羞黄。\n争似红妆。\n不假施朱弄晓光。\n雪融日暖琼肌腻，酒晕生香。\n桃脸相当。\n尤笑桃花混众芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19209, '采桑子', '无名氏', '幽芳莹白前村里，岂藉春工。\n胜尽群红。\n琼拈凝酥向不同。\n一声羌管愁人处，片片西东。\n睹此遗踪。\n不怨狂风怨马融。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19210, '采桑子', '无名氏', '东君有意观群卉，故放争先。\n带露含烟。\n对月偏宜映水边。\n琼苞素蕊胭脂淡，雪後风前。\n堪赏堪怜。\n曾与歌楼佐管弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19211, '采桑子', '无名氏', '群芳尽老园林烬，独有寒梅。\n探得春回。\n昨夜前村一朵开。\n轻盈雪里孤根秀，素脸香腮。\n羌管休催。\n留取琼葩佐酒杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19212, '采桑子', '无名氏', '霜风漏泄春消息，折破孤芳。\n野兴彷徨。\n姑射神仙触处藏。\n新妆不假施朱粉，雪月交光。\n欲赠东皇。\n冷淡龙涎点点香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19213, '采桑子', '无名氏', '烟笼淡月寒宵永，悄悄帘栊。\n微度香风。\n几点梅开小院中。\n拥衾枕难成寐，萧寺初钟。\n雁响遥空。\n家在青山千万重。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19214, '采桑子', '无名氏', '飞琼欲赴瑶台宴，先具威仪。\n云驾霓衣。\n从者皆骑白凤飞。\n人间尽变为银海，此景偏奇。\n姑射冰姿。\n昨夜前村见一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19215, '采桑子', '无名氏', '熔金脱得花钿小，点缀琼枝。\n月淡风微。\n露香肌自是奇。\n玉人呵手昂头翦，纤鬓边垂。\n似簇蜂儿。\n春入芳容不肯飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19216, '寻梅', '无名氏', '幽香浅浅湿未透。\n认雪底、思来始有。\n翦裁尚觉琼瑶皱。\n苦寒中、越恁骨清肌瘦。\n东风气象园林旧。\n又去年、而今时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19217, '红', '无名氏', '粉香尤嫩，衾寒可惯。\n怎奈向、春心已转。\n玉容别是，一般闲婉。\n悄不管、桃红香浅。\n月影帘栊，金琼波面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19218, '武林春・武陵春', '无名氏', '昨夜前村深雪里，春信为谁传。\n风送清香满座间。\n不用热沈檀。\n竹外一枝斜更好，偏称玉人攀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19219, '瑞鹧鸪', '无名氏', '临鸾常恁整妆梅。\n枝枝仙艳月中开。\n可杀天心、故与多端丽，那更罗衣峭窄裁。\n几回瞻觑魂消黯，芙蕖匀透双腮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19220, '瑞鹧鸪', '无名氏', '汉宫铅粉净无痕。\n蜡点寒梢水畔村。\n忍犯冰霜欺竹柏，肯同雪月吊兰荪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19221, '瑞鹧鸪', '无名氏', '柳未回青兰未芽。\n谁知此物在君家。\n绿窗借得先春手，黄蜡吹成耐冻花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19222, '一落索', '无名氏', '腊後东风微透。\n越梅时候。\n一枝芳信到江南，来报先春秀。\n宿醉频拈轻嗅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19223, '鬓边华', '无名氏', '小梅香细艳浅。\n过楚岸、尊前偶见。\n爱闲淡，天与精神，掠青鬓、开人醉眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19224, '御阶行・御街行', '无名氏', '平生有个风流愿。\n愿长与梅为伴。\n问伊因甚破寒来，只恐百花先绽。\n比兰比麝，比酥比玉，休恁闲撩乱。\n瑶台月下分明见。\n依旧残妆浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19225, '西江月', '无名氏', '北岭天饶瑞雪，南枝地段红苞。\n朦胧霁月映寒梢。\n谁把玉人纱罩。\n香胜炉薰龙麝，奇过庭拥琼瑶。\n一杯清酒愿相招。\n慰我茅堂清瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19226, '西江月', '无名氏', '翡翠枝头晚萼，婵娟月里飘香。\n春兰秋蕙作寻常。\n不与夭桃朋党。\n笑见深红浅白，从教蝶舞蜂忙。\n风流标致道家妆。\n潇洒得来别样。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19227, '西江月', '无名氏', '黄蜡谁将点缀，红膏不许施妆。\n孤根来自水云乡。\n风味天然酝酿。\n看取玉奴呵手，摘来珠露沾裳。\n翠环斜插一枝香。\n似簇蜂儿头上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19228, '西江月', '无名氏', '万木经霜冻折，孤根独报春来。\n前村雪里一枝开。\n将缓月华光彩。\n一点唇红不褪，妆如傅粉皑皑。\n和羹端的禀天才。\n终入庖人鼎鼐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19229, '蝶恋花', '无名氏', '暖发黄宫和气软。\n雪里精神，巧借东君翦。\n嫩蕊商量春色浅。\n青枝疑是香酥溅。\n谁道和羹芳信远。\n点点微酸，已向枝头见。\n休待玉英飞四散。\n且移疏影横金盏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19230, '桃源忆故人', '无名氏', '园林万木凋零尽。\n惟是寒梅香喷。\n不许雪霜欺损。\n迥有天然性。\n南枝渐吐红苞嫩。\n冠绝夭桃繁杏。\n不记故人音信。\n对景成离恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19231, '桃源忆故人', '无名氏', '江天雪意云飞重。\n却倚阑干初冻。\n回傍小楼独拥。\n尽日无人共。\n墙梅未落春先纵。\n欲寄一枝谁送。\n月夜暗香浮动。\n似作离人梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19232, '桃源忆故人', '无名氏', '南枝向暖清香喷。\n谁付骚人词咏。\n一种陇头春信。\n不借胭脂晕。\n梢头谁把轻黄。\n浑似不施粉。\n疑是寿阳孤冷。\n染得相思病。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19233, '桃源忆故人', '无名氏', '寒苞初吐黄金莹。\n色染蔷薇犹嫩。\n枝上紫檀香喷。\n洒落饶风韵。\n南枝一种同春信。\n何事不朱粉。\n自称霓裳孤冷。\n怨感宫腰恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19234, '添字浣溪沙・山花子', '无名氏', '雪态冰姿好似伊。\n料应尝笑水仙迟。\n驿使初传芳信早，赏佳期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19235, '添字浣溪沙・山花子', '无名氏', '谁染深红酥缀来。\n意浓含笑美颜开。\n误认浣溪人饮罢，上香腮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19236, '添字浣溪沙・山花子', '无名氏', '取次匀妆粉有痕。\n参差玉软淡精神。\n姑射重绡风卷乱，喜相迎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19237, '添字浣溪沙・山花子', '无名氏', '蜜室蜂房别有香。\n腊前偏会泄春光。\n凝伫清容何所似，笑姚黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19238, '玉交枝・忆秦娥', '无名氏', '胆样瓶儿几点春。\n翦来犹带水云痕。\n且移孤冷，相伴最深樽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19239, '玉交枝・忆秦娥', '无名氏', '蕙子兰孙小样儿。\n化工簇就寄南枝。\n笑他兰蕙，虽韵带轻肥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19240, '玉交枝・忆秦娥', '无名氏', '谁道花房采蜜脾。\n翦成黄蜡小花儿。\n恶嫌朱粉，不肯肖青枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19241, '玉楼春', '无名氏', '迢递前村深雪里。\n望断行云香细细。\n笛中宫里慕芳姿，怨曲啼妆长见泪。\n不会同心荣落易。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19242, '玉楼春', '无名氏', '萧萧海上风长起。\n也有梅花开玉蕊。\n爱君风措莹如冰，伴我情怀清似水。\n诗人纵复工难似。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19243, '玉楼春', '无名氏', '腊前先报东君信。\n清似龙涎香得润。\n黄轻不肯整齐开，比着红梅仍旧韵。\n纤枝瘦绿天生嫩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19244, '捣练子', '无名氏', '欺万木，怯寒时。\n倚阑初认月宫姬。\n拭新妆，披素衣。\n孤标韵，暗香奇。\n冰容玉艳缀琼枝。\n借阳和，天付伊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19245, '喜团圆', '无名氏', '轻攒碎玉，玲珑竹外，脱去繁华。\n尤东君，最先点破，压倒群花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19246, '愁倚栏・春光好', '无名氏', '冰肌玉骨精神。\n不风尘。\n昨夜窗前都折尽，忽疑君。\n清泪拂拂沾巾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19247, '减字木兰花', '无名氏', '庭梅初绽。\n风递幽香清更远。\n别有孤根。\n不待阳和一点恩。\n雪中风韵。\n皓质冰姿真莹静。\n月下精神。\n来到窗前疑是君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19248, '减字木兰花', '无名氏', '疏梅风韵。\n不许游蜂飞蝶近。\n要识芳容。\n除向瑶台月下逢。\n尊前一见。\n换尽平生桃李眼。\n却笑襄王。\n楚梦无踪空断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19249, '减字木兰花', '无名氏', '山城驿近。\n又报寒梅传驿信。\n远水孤村。\n月下何人与断魂。\n幽芳在手。\n花木无情那得瘦。\n似此天真。\n好赠东阳姓沈人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19250, '减字木兰花', '无名氏', '香肌清瘦。\n泪湿轻红疏雨後。\n笑靥微开。\n宿雨微醺越女腮。\n多情无奈。\n玉管休吹帘影外。\n薄晚池台。\n惆怅繁华梦里来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19251, '减字木兰花', '无名氏', '东君有待。\n留得一枝香雪在。\n晚日融融。\n只恐轻酥暖渐熔。\n歌催管送。\n芳酒一尊谁与共。\n寂寞墙东。\n潇洒黄昏满院风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19252, '减字木兰花', '无名氏', '鹅黄初吐。\n无数蜂儿飞不去。\n别有香风。\n不与南枝斗浅红。\n凭谁折取。\n拟把玉人分付与。\n碧玉搔头。\n淡淡霓裳人倚楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19253, '减字木兰花', '无名氏', '园林衰槁。\n一品梅花开太早。\n紫蕊檀心。\n独占中央色似金。\n幽香清远。\n对景开尊同赏玩。\n雅称仙姿。\n莫是多情染相思。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19254, '临江仙', '无名氏', '漏出春光三四朵，冰肌玉骨偏宜。\n乍开应笑百花迟。\n将军曾止渴，画角已先知。\n素艳不容蜂蝶采，清香自有人知。\n而今虽被霜雪欺。\n和羹终待手，金鼎自逢时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19255, '临江仙', '无名氏', '陇首云收天色暮，寒光射月初开。\n荆山玉莫疑猜。\n琳琅疑此地，仙子不红腮。\n丽质霜裾真性雅，馀香暗送人来。\n乱将碎玉缀枝排。\n雪中寻不见，青萼辨奇才。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19256, '临江仙', '无名氏', '昨夜新阳回候馆，芳菲正满霜林。\n此时珍赏重千金。\n谁知红粉艳，还有岁寒心。\n风动霞衣香散漫，酒醺丹脸深沈。\n妖娆偏称美人簪。\n一枝无处赠，折得自孤吟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19257, '临江仙', '无名氏', '爱日新添春一线，化工先到寒梅。\n不随桃李傍熙台。\n前村深雪里，昨夜一枝开。\n姑射仙人标格韵，凝墙粉谢香腮。\n数家清弄笛声衰。\n愁人不怨听，自向枕边来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19258, '临江仙', '无名氏', '玉貌香腮天赋与，清姿不假铅华。\n素芳寻在五陵家。\n欲知春信息，庾岭一枝斜。\n别有玲珑潇洒处，月梢淡影笼遮。\n休教羌笛一声嗟。\n宫妆犹未似，留取意无涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19259, '踏莎行', '无名氏', '枝绿初匀，萼红犹浅。\n化工妆点年华晚。\n暗香疏影水亭边，黄昏月下依稀见。\n十二危楼，谁人倚遍。\n只愁羌笛声幽怨。\n少留情意待春来，东君准拟长拘管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19260, '踏莎行', '无名氏', '萼破前村，枝横江路。\n铁心应也频凝伫。\n怕愁惟恐不禁愁，宁教雪月相分付。\n不测春来，难追香去。\n无人知我心先误。\n多情总道是东君，东君也有无情处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19261, '踏莎行', '无名氏', '点点琼酥，初寒乍结。\n看来未忍轻轻折。\n园林正告久萧条，春工著意饶先发。\n眼底不凡，枝头自别。\n也知彻苦宜霜雪。\n这般风味凭馨香，怎教桃李同时节。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19262, '踏莎行', '无名氏', '玉母池边，曾记旧识。\n玉京仙苑新移得。\n素娥青女好精神，比看终是无颜色。\n传入汉宫，偷拟妆饰。\n寿阳空恁劳心力。\n寒香都不为春来，莫将远寄春消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19263, '渔家傲', '无名氏', '蕙死兰枯篱菊槁。\n返魂香入江南早。\n竹外一枝斜更好。\n谁解道。\n只今惟有东坡老。\n去岁花前人醉倒。\n酒醒花落嫌人扫。\n人去不来春又到。\n愁满抱。\n青山一带连芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19264, '渔家傲', '无名氏', '雪点江梅才可可。\n梅心暗弄纤纤朵。\n疑是月娥庭下过。\n仙翘。\n云衫密缀真珠颗。\n玉金瓯连臂坐。\n芳辰莫把离魂挫。\n一曲绣筵娇婀娜。\n情无那。\n阳关声里樱桃破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19265, '定风波', '无名氏', '又是春归烟雨村。\n一枝香雪度黄昏。\n竹外云低疏影亚。\n潇洒。\n水清沙浅见天真。\n瘦玉欺寒香不暖。\n堪羡。\n冰姿照夜月无痕。\n楼上笛声休听取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19266, '定风波', '无名氏', '一树寒梅傍小溪。\n夜来陡觉绽南枝。\n冷艳冰姿金蕊浅。\n堪羡。\n凝明因与雪霜期。\n折赠美人临宝鉴。\n云脸。\n鬓边斜插最相宜。\n凭仗高楼频祝付。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19267, '鹊踏枝・蝶恋花', '无名氏', '南国寒轻山自碧。\n庭际梅花，先报春消息。\n绮萼玉英何忍摘。\n真堪树下陈瑶席。\n旋嗅清香消酒力。\n翦采无功，粉笔争描得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19268, '鹊踏枝・蝶恋花', '无名氏', '故里山遥春霭碧。\n为想繁枝，清梦何曾息。\n缧带霜英人不摘。\n纷纷日暮飘席。\n休抱离肠凭酒力。\n只有轻纨，依约应传得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19269, '清平乐', '无名氏', '寒溪过雪。\n梅蕊春前发。\n照影弄姿香苒苒，临水一枝风月。\n梦游仿佛仙乡。\n绿窗曾见幽芳。\n事往无人共说，愁闻玉笛声长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19270, '春光好', '无名氏', '看看腊尽春回。\n消息到、江南早梅。\n昨夜前村深雪里，一朵花开。\n盈盈玉蕊如裁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19271, '人娇', '无名氏', '玉瘦香浓，檀深雪散。\n今年恨、探梅较晚。\n江楼楚馆。\n云闲水远。\n清昼永，凭阑翠帘低卷。\n坐上客来，尊中酒满。\n歌声共、水流云断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19272, '二色宫桃', '无名氏', '镂玉香苞酥点萼。\n正万木、园林萧索。\n惟有一枝雪里开，江南有信凭谁托。\n前年记赏登高阁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19273, '河传', '无名氏', '香苞素质。\n天赋与、倾城标格。\n应是晓来，暗传东君消息。\n把孤芳、回暖律。\n寿阳粉面增妆饰。\n说与高楼，休更吹羌笛。\n花下醉赏，留取时倚阑干，斗清香、添酒力。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19274, '七娘子', '无名氏', '清香浮动到黄昏，向水边、疏影梅开尽。\n溪边畔，轻蕊，有如浅杏。\n一枝喜得东君信。\n风吹只怕霜侵损。\n更新来、插向多情鬓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19275, '忆少年', '无名氏', '疏疏整整，斜斜淡淡，盈盈脉脉。\n徒怜暗香句，笑梨花颜色。\n羁马萧萧行又急。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19276, '浪淘沙', '无名氏', '春色入横塘。\n变尽凄凉。\n青梢弄粉雪溪傍。\n疑是化工偏著意，欲试新妆。\n玉蓓锁春藏。\n占断寒芳。\n他时鼎鼐不须忙。\n泄漏清香方有思，别是春光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19277, '浪淘沙', '无名氏', '雪里暗香浓。\n乍吐琼英。\n横斜疏影月明中。\n学傅胭脂桃与杏，虚废春工。\n素艳有谁同。\n不并妖红。\n应如褒姒笑时容。\n绝胜梨花春带雨，旖旎春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19278, '浪淘沙', '无名氏', '村左小溪傍。\n粉黛宜芳。\n寒添潇洒冷添霜。\n清瘦几枝堪入画，竹映苔墙。\n疏影浸横塘。\n月暗浮香。\n当时曾伴寿阳妆。\n不似东君先倚栏，泄漏春光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19279, '点绛唇', '无名氏', '破萼江梅，迥然标格冰肌莹。\n暗香疏影。\n月张银塘静。\n折取一枝，与插多情鬓。\n临鸾镜。\n粉容相并。\n试问谁端正。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19280, '点绛唇', '无名氏', '烟淡黄昏，小移疏影横斜去。\n暗香微度。\n点缀梢头雨。\n玉管休吹，更要留春住。\n人何处。\n对花无语。\n望断江南路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19281, '点绛唇', '无名氏', '点点江梅，向疏篱处香风逗。\n未容春透。\n花亦知人瘦。\n姑射山头，谁伴黄昏後。\n君知否。\n自然孤秀。\n横玉休三奏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19282, '点绛唇', '无名氏', '雪里芳丛，岭头还报东君信。\n寿阳妆靓。\n姑射冰肌莹。\n曲岸横斜，清浅波相应。\n风不定。\n暗香疏影。\n占断花中韵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19283, '点绛唇', '无名氏', '万木凋残，早梅独占孤根暖。\n前村雪满。\n昨夜南枝绽。\n堪恨倚栏，容易吹羌管。\n飘琼片。\n翠蛾争选。\n贴向桃花面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19284, '点绛唇', '无名氏', '昨夜寒梅，一枝雪里多风措。\n幽香无数。\n不与群花语。\n最是凝情，月夜交光处。\n谁为主。\n待须折取。\n羌管休轻举。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19285, '点绛唇', '无名氏', '春日芳心，暗香偏向黄昏逗。\n玉肌寒透。\n抵死添清瘦。\n影落横塘，月淡人归後。\n君知否。\n一枝先秀。\n应向东君奏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19286, '点绛唇', '无名氏', '赋雪归来，绿窗一夜霜风紧。\n也知春信。\n消息南枝近。\n隐映斜阳，玉暖香成阵。\n西湖景。\n繁英有恨。\n只□□□□。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19287, '惜双双・惜分飞', '无名氏', '冒雪披风开数点。\n万花厌、欺寒探暖。\n掩映闲庭院。\n月下疏影横斜，幽香远。\n命友开尊同宴玩。\n听丽质、歌声宛转。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19288, '朝中措', '无名氏', '山城水隘小桥傍。\n竹里早梅芳。\n纵有丹青图画，难描幽韵清香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19289, '虞美人', '无名氏', '清江一曲君应见。\n昨夜潮头浅。\n不争落落斗奇奇。\n看取水边寒蕊、雪边枝。\n日斜疏影还倒。\n沙上娇老。\n只今何处有新诗。\n好在小春十月、醉翁辞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19290, '醉落魄・一斛珠', '无名氏', '琼搓粉滴。\n南枝只报江南坼。\n横斜疏影溪边窄。\n翦碎白云，分付陇头客。\n冰肌绰约疑姑射。\n铅华消尽见真色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19291, '醉落魄・一斛珠', '无名氏', '梅花似雪。\n赏花记得同欢悦。\n更阑犹自贪攀折。\n不怯春寒，须要待明月。\n如今月上花争发。\n疏枝冷蕊对离缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19292, '更漏子', '无名氏', '宝香瓶，桐叶卷。\n荡水痕微还远。\n思乡信，觉春迟。\n野梅初见时。\n上潮风，临晚渡。\n人欲过西江去。\n吹寒管，陇云低。\n江南花未知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19293, '更漏子', '无名氏', '绛纱笼，金叶盖。\n向晓灯花犹在。\n冰未结，小琉璃。\n陇梅香满枝。\n雪无香，花有意。\n不是江南新寄。\n霜月尽，碧天寒。\n玉楼人倚阑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19294, '落梅风・落梅', '无名氏', '宫烟如水湿芳晨。\n寒梅似雪相亲。\n玉楼侧畔数枝春。\n惹香尘。\n寿阳娇面偏怜惜，妆成一面花新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19295, '古记・如梦令', '无名氏', '一枕厌厌春困。\n记得小梅风韵。\n何处最关情，嫩蕊初传芳信。\n堪恨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19296, '古记・如梦令', '无名氏', '腊半雪梅初绽。\n玉屑琼英碎翦。\n素艳与清香，别有风流堪羡。\n苞嫩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19297, '古记・如梦令', '无名氏', '疑是水晶宫殿。\n云女天仙宝宴。\n吟赏欲黄昏，风送一声羌管。\n烟淡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19298, '生查子', '无名氏', '朔风吹冻云，云破天容碧。\n新月过溪来，隐见横云色。\n天与水争妍，花与月争白。\n一倩管城君，寄此春消息。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19299, '蓦山溪', '无名氏', '青春三月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19300, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19301, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19302, '调笑・调笑令', '无名氏', '千里。\n楚江水。\n明月楼高愁独倚。\n井梧宫殿生秋意。\n望断巫山十二。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19303, '调笑・调笑令', '无名氏', '相误。\n桃源路。\n万里苍苍烟水暮。\n留君不住君须去。\n秋月春风闲度。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19304, '调笑・调笑令', '无名氏', '非雾。\n花无语。\n远似朝云何处去。\n凌波不过横塘路。\n燕燕莺莺飞舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19305, '调笑・调笑令', '无名氏', '相忆。\n无消息。\n目断遥天云自白。\n寒山一带伤心碧。\n风土萧疏胡国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19306, '调笑・调笑令', '无名氏', '来见。\n蕊宫殿。\n记得随班迎凤辇。\n馀花落尽苍苔院。\n斜掩金铺一片。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19307, '调笑・调笑令', '无名氏', '君去。\n逐鸳侣。\n斜倚绿窗鸳鉴女。\n琴弹秋思明心素。\n一寸还成千缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19308, '调笑・调笑令', '无名氏', '无处。\n难轻诉。\n锦瑟华年谁与度。\n黄昏更下潇潇雨。\n况是青春将暮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19309, '调笑・调笑令', '无名氏', '衫湿。\n情何极。\n上下花间声转急。\n满船明月芦花白。\n秋水长天一色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19310, '九张机', '无名氏', '一张机。\n织梭光景去如飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19311, '九张机', '无名氏', '两张机。\n月明人静漏声稀。\n千丝万缕相萦系。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19312, '九张机', '无名氏', '三张机。\n中心有朵耍花儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19313, '九张机', '无名氏', '四张机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19314, '九张机', '无名氏', '五张机。\n芳心密与巧心期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19315, '九张机', '无名氏', '六张机。\n雕花铺锦半离披。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19316, '九张机', '无名氏', '七张机。\n春蚕吐尽一生丝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19317, '九张机', '无名氏', '八张机。\n纤纤玉手住无时。\n蜀江濯尽春波媚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19318, '九张机', '无名氏', '九张机。\n一心长在百花枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19319, '九张机', '无名氏', '轻丝。\n象床玉手出新奇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19320, '九张机', '无名氏', '春衣。\n素丝染就已堪悲。\n尘世昏污无颜色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19321, '九张机', '无名氏', '一张机。\n采桑陌上试春衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19322, '九张机', '无名氏', '两张机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19323, '九张机', '无名氏', '三张机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19324, '九张机', '无名氏', '四张机。\n咿哑声里暗颦眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19325, '九张机', '无名氏', '五张机。\n横纹织就沈郎诗。\n中心一句无人会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19326, '九张机', '无名氏', '六张机。\n行行都是耍花儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19327, '九张机', '无名氏', '七张机。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19328, '九张机', '无名氏', '八张机。\n回纹知是阿谁诗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19329, '九张机', '无名氏', '九张机。\n双花双叶又双枝。\n薄情自古多离别。\n从头到底。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19330, '南歌子', '无名氏', '席近浑如远，帘高故放低。\n偏它能画斗头眉。\n戴顶烧香铺翠、小冠儿。\n酒伴残妆在，花随秀鬓垂。\n薄罗小扇写新诗。\n解下双双罗带、要重题。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19331, '南歌子', '无名氏', '象戏红牙局，琵琶绿锦绦。\n小窗方簟困香醪。\n帘外拂檐宫柳、翠阴交。\n烟媚莺莺近，风微燕燕高。\n更将乳酪伴樱桃。\n要共那人一递、一匙抄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19332, '南歌子', '无名氏', '小小生金屋，盈盈向凤帏。\n斜枝石竹绣罗衣。\n为怕春来风日、卷帘稀。\n金殿承恩久，兰堂得梦回。\n薰炉空惹御香归。\n今夜花前还是、日平西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19333, '南歌子', '无名氏', '阁儿虽不大，都无半点俗。\n窗儿根底数竿竹。\n画展江南山景、两三幅。\n彝鼎烧异香，胆瓶插嫩菊。\nけ然无事净心目。\n共那人人相对、弈棋局。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19334, '南歌子', '无名氏', '风动槐龙舞，花深禁漏传。\n一竿红日照花砖。\n走马晨晖门里、快行宣。\n百五开新火，清明尚禁烟。\n鱼符不请便朝天。\n醉里归来疑是、梦游仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19335, '感皇恩', '无名氏', '暖律破寒威，春回宫柳。\n晴景初曦上元候。\n禁城烟火，移下一天星斗。\n素娥凝碧汉，明如昼。\n绣毂电转，锦鞯飞骤。\n九踏笙歌按新奏。\n胜游方凝，忽听晓钟银漏。\n两两归去也，应回首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19336, '鱼游春水', '无名氏', '秦楼东风里。\n燕子还来寻旧垒。\n馀寒微透，红日薄侵罗绮。\n嫩笋才抽碧玉簪，细柳轻黄金蕊。\n莺啭上林，鱼游春水。\n屈曲阑干遍倚。\n又是一番新桃李。\n佳人应念归期，梅妆淡洗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19337, '五彩结同心', '无名氏', '珠帘垂户。\n金索悬窗，家接浣沙溪路。\n相见桐阴下，一钩月、恰在凤凰栖处。\n素琼拈就宫腰小。\n花枝袅、盈盈娇步。\n新妆浅，满腮红雪，绰约片云欲度。\n尘寰岂能留住。\n唯只愁、化作彩云飞去。\n蝉翼衫儿，薄冰肌莹，轻罩一团香雾。\n彩笺巧缀相思苦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19338, '侍香金童', '无名氏', '宝台蒙绣，瑞兽高三尺。\n玉殿无风烟自直。\n迤逦传杯盈绮席。\n苒苒菲菲，断处凝碧。\n是龙涎凤髓，恼人情意极。\n想韩寿、风流应暗识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19339, '洞仙歌', '无名氏', '溶溶泄泄，似飘扬愁绪。\n不是因风等闲度。\n道无心用甚，却又情多，行未驻，还作高阳暮雨。\n襄王情尚浅，会少离多，空自朝朝又暮暮。\n肠断晓光中，一缕归时，销散後、不知何处。\n试密锁、琼楼洞房深，与遮断江皋，楚台归路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19340, '永遇乐', '无名氏', '功名闲事，利禄休问，莫系心上。\n幸有衣食，随缘过得，著甚乾劳攘。\n风前月下，三杯两盏，撞著即莫与放。\n且与个、山庄道友，退闲故人来往。\n新来做得，一个宽袖布衫，著来也畅。\n出户迎宾，入城干事，恰似王保长。\n我咱後，神歌鬼舞，任尔万般毁谤。\n死来後，一家一个，那底怎向。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19341, '西江月', '无名氏', '灯火楼台欲下，笙歌院落将归。\n冰瓷金缕胜琉璃。\n春笋捧来纤细。\n饮罢高阳人散，曲终巫峡云飞。\n千万修合斗新奇。\n须带别离滋味。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19342, '水调歌头', '无名氏', '帆落松陵浦，枯柳缆琼艘。\n杖策无人独步，浪厌百花桥。\n我挂风裳水佩，一笑波寒月白，馀韵触惊涛。\n绝景有谁赏，雾暮闭三高。\n不须臾，千古事，一萧条。\n鲈鱼纵有，泽荒甫里失溪桥。\n更吾名高业茂，终归荒田野草，且稳一枝巢。\n举酒酹空阔，烟远路迢迢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19343, '菩萨蛮', '无名氏', '江城烽火连三月。\n不堪对酒江亭别。\n休作断肠声。\n老来无泪倾。\n风高帆影疾。\n目送舟痕碧。\n锦字几时来。\n薰风无雁回。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19344, '减字木兰花', '无名氏', '啬薇叶暗。\n满架浓阴风不乱。\n午酒才醒。\n历历黄鹂枕上听。\n此情难遣。\n不比红蕉心易展。\n要识离愁。\n只似杨花不自由。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19345, '浣溪沙', '无名氏', '梦入瑶台千步芳。\n万妃相向玉为装。\n同心带翠罗长。\n浓艳只宜供枕席，醉魂长是傍壶觞。\n绀纱囊薄为谁香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19346, '浣溪沙', '无名氏', '白玉楼中白雪歌。\n更将白衬春罗。\n软红香里最么麽。\n桃叶桃根随处有，江南江北见来多。\n风前月底奈愁何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19347, '临江仙', '无名氏', '竹里行厨草草，花边系马匆匆。\n使君移传意何穷。\n儿童随骑火，猿鹤避歌钟。\n梅雪自欺舞态，烛花先放春红。\n酒醒人散夜堂空。\n殷勤松上月，独照老仙翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19348, '阮郎归', '无名氏', '山池芳草绿初匀。\n柳寒眉尚颦。\n东风吹雨细如尘。\n一庭花脸皴。\n莺共蝶，怨还嗔。\n眼前无好春。\n这番天气杀愁人。\n人愁旋旋新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19349, '浣溪沙', '无名氏', '春院无人花自香。\n飞来蜂蝶意何狂。\n玉钩帘卷日偏长。\n笑又不成愁未是，曲屏闲倚绣鸳鸯。\n归时应供□□妆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19350, '南乡子', '无名氏', '李郭共仙舟。\n准拟苏台烂熳游。\n风雪为谁留住也，沧洲。\n一尺银沙未肯收。\n无语只关愁。\n强金卮不计筹。\n想得人人梳洗懒，妆楼。\n只帘儿不上钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19351, '凤栖梧・蝶恋花', '无名氏', '姑射仙人游汗漫。\n白凤翩翩，银海光凌乱。\n龟手儿童贪戏玩。\n风檐更折梅梢看。\n漠漠银沙平晚岸。\n笑拥寒蓑，聊作渔翁伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19352, '归自谣', '无名氏', '愁冉冉。\n目送书空鸿数点。\n落霞风剪江分染。\n胜处屏云犹未掩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19353, '卜算子', '无名氏', '曾约再来时，花暗春风树。\n今日人来花未开，春未知人处。\n坐客有疏狂，彩笔题新语。\n浑为玉人颓玉山，忘了阳关路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19354, '卜算子', '无名氏', '烟髻绾层巅，云叶生寒树。\n斜日行人窈窕村，愁阵纵横处。\n细细写蛮笺，道寄相思语。\n会倩春风展柳眉，回马章台路。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19355, '好事近', '无名氏', '潇洒小楼东，斜亚一枝梅雪。\n若在玉溪仙馆，更风流奇绝。\n花神应为护芳心，付与何人折。\n行客几回搔首，认暗香浮月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19356, '谒金门', '无名氏', '江上路。\n依约数家烟树。\n一枕归心村店暮。\n更乱山深处。\n梦过江南芳草渡。\n晓色又催人去。\n愁似游丝千万缕。\n倩东风约住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19357, '杜韦娘', '无名氏', '华堂深院，霜笼月采生寒晕。\n度翠幄、风触梅香喷。\n渐岁晚、春光将近。\n惹离恨万种，多情易感，欢难聚少愁成阵。\n拥红炉，凤枕慵，银灯挑尽。\n当此际，争忍前期後约，度岁无凭准。\n对好景、空积相思恨。\n但自觉、恹恹方寸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19358, '摸鱼儿', '无名氏', '被谁家、数声弦管，惊回好梦难省。\n起来无语疏雨过，芳草嫩苔侵径。\n春昼永。\n迟日暮，碧沼浪浸红楼影。\n卷帘人静。\n被风触，一叶两叶，杏花零乱对残景。\n依前是，撩拨春心堪恨。\n檀郎言约无定。\n不知何处贪欢笑，恣纵酒迷歌逞。\n珠泪迸。\n自别後，每忆翠黛凭谁整。\n芳年相称。\n又到得今来，却成病了，羞懒对鸾镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19359, '满庭芳', '无名氏', '五斗相逢，千锺一饮，古今乐事无过。\n香生银瓮，浮蚁浴春波。\n潋滟光凝盏面，轻风皱、浅碧宫罗。\n乘欢处，倾痛饮，珠贯引清歌。\n云何。\n君不饮，良辰美景，聚少离多。\n忍怎放春风，容易蹉跎。\n但愿一樽常共，花阴下、急景如梭。\n须乘醉，雕鞍归去，争看醉颜酡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19360, '潇湘静・湘江静', '无名氏', '画帘微卷香风逗。\n正明月、乍圆时候。\n金盘露冷，玉炉篆消，渐红鳞生酒。\n娇唱倚繁弦，琼枝碎、轻回云袖。\n风台歌短、铜壶漏永，人欲醉、夜如昼。\n因念流年迅景，被浮名、暗辜欢偶。\n人生大抵，离多会少，更相将白首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19361, '十月桃', '无名氏', '东篱菊尽，遍园林败叶，满地寒。\n露井平明，破香笼粉初开。\n佳人共喜芳意，呵手剪、密插鸾钗。\n无言有艳，不避繁霜，变作春媒。\n问武陵溪上谁栽。\n分付与南园，舞榭歌台。\n恰似凝酥衬玉，点缀装裁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19362, '汉宫春', '无名氏', '江月初圆，正新春夜永，灯市行乐。\n芙蕖万朵，向晚为谁开却。\n层楼画阁。\n尽卷上、东风帘幕。\n罗绮拥，欢声和气，惊破柳梢梅萼。\n绰约。\n暗尘浮动，正鱼龙曼衍，戏车交作。\n高牙影里，缓控玉羁金络。\n铅华间错。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19363, '汉宫春', '无名氏', '玉减香销，被婵娟误我，临镜妆慵。\n无聊强开强解，蹙破眉峰。\n凭高望远，但断肠、残月初钟。\n须信道，承恩在貌，如何教妾为容。\n风暖鸟声和碎，更日高院静，花影重重。\n愁来待只酒，酒困愁浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19364, '风流子', '无名氏', '淑景皇州满，和风渐、催促柳花飞。\n过清明骤雨，五候台榭，青烟散入，新火开时。\n绣帘外、傍人飞燕子，映叶语黄鹂。\n秋千昼永，绮罗人散，花阴笑隔，红粉墙低。\n青门多行乐，寻芳处、何计强逐轻肥。\n空对旧游满目，谁共开眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19365, '夏日宴黉堂・夏日燕黉堂', '无名氏', '日初长。\n正园林换叶，瓜李飘香。\n帘外雨过，送一霎微凉。\n萍芜迳，曲凝珠颗，衬汀沙、细簇蜂房。\n被晚风轻，圆荷翻水，泼觉鸳鸯。\n此景最难忘。\n趁芳樽泛蚁，筠簟铺湘。\n兰舟棹稳，倚何处垂杨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19366, '渔家傲', '无名氏', '轻拍红牙留客住。\n韩家石鼎联新句。\n珍重龙团并凤髓。\n君王与。\n春风吹破黄金缕。\n往事不须凭陆羽。\n且看盏面浓如乳。\n若是蓬莱鳌稳负。\n知何处。\n玉川一枕清风去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19367, '醉春风', '无名氏', '陌上清明近。\n行人难借问。\n风流何处不来归，闷闷闷。\n回雁峰前，戏鱼波上，试寻芳信。\n夜久兰膏烬。\n春睡何曾稳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19368, '卓牌儿・卓牌子', '无名氏', '当年早梅芳，曾邂逅、飞琼侣。\n肌云莹玉，颜开嫩桃，腰支轻袅，未胜金缕。\n佯羞整云环，频向人、娇波寄语。\n湘佩笑解，韩香暗传，幽欢後期难诉。\n梦魂顿阻。\n似一枕、高唐云雨。\n蕙心兰态，知何计重遇。\n试问春蚕丝多少，未抵离愁半缕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19369, '南乡子', '无名氏', '晓日压重檐。\n斗帐犹寒起未。\n天气困人梳洗倦，眉尖。\n淡画春山不喜添。\n闲把绣丝。\n得金针又怕拈。\n陌上行人归也未，恹恹。\n满院杨花不卷帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19370, '南乡子', '无名氏', '深结花工知。\n赐与衣裳尽是绯。\n曾向玉盘深处见，隈随。\n两个心肠一片儿。\n从小便相依。\n酒伴歌筵不暂离。\n只恐被人分擘破，东西。\n怎得团圆似旧时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19371, '望远行', '无名氏', '当时云雨梦，不负楚王期。\n翠峰中、高楼十二掩瑶扉。\n尽人间欢会，只有两心自知。\n渐玉困花柔香汗挥。\n歌声翻别怨，云驭欲回时。\n这无情红日，何似且休西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19372, '归田乐', '无名氏', '水绕溪桥绿。\n泛苹汀、步迷花曲。\n衣巾散馀馥。\n种竹更洗竹。\n咏竹题竹。\n日暮无人伴幽独。\n光阴双转毂。\n可惜许、等闲愁万斛。\n世间种种，只是荣和辱。\n念足又愿足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19373, '临江仙', '无名氏', '促坐重燃绛蜡，香泉细泻银瓶。\n一瓯月露照人明。\n清真无俗韵，久淡似交清。\n正味能销酒力，馀甘解助茶清。\n琼浆一饮觉身轻。\n蓝桥知不远，归卧对云英。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19374, '行香子', '无名氏', '天与秋光。\n转转情伤，探金英、知近重阳。\n薄衣初减，绿蚁初尝。\n渐一番风，一番雨，一番凉。\n黄昏院落，惶惶。\n酒醒时、往事愁肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19375, '诉衷情', '无名氏', '碧天明月晃金波。\n清浅滞星河。\n深深院宇人静，独自问娥。\n圆夜少，缺时多。\n事因何。\n嫦娥莫是，也有别离，一似人麽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19376, '绕池游', '无名氏', '渐春工巧，玉漏花深寒浅。\n韶景变、融晴蕙风暖。\n都门十二，三五银蟾光满。\n瑞烟葱茜，禁城阆苑。\n棚山雉扇。\n绛蜡交辉星汉。\n神仙籍、梨园奏弦管。\n都人游玩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19377, '好事近', '无名氏', '小院看酴，正是盛开时节。\n莫惜大家沈醉，有春醅初泼。\n花前月下细看来，无物比清绝。\n若问此花何似，似一堆香雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19378, '阮郎归', '无名氏', '春风吹雨绕残枝。\n落花无可飞。\n小池寒渌欲生漪。\n雨晴还日西。\n帘半卷，燕双归。\n讳愁无奈眉。\n翻身整顿著残棋。\n沈吟应劫迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19379, '点绛唇', '无名氏', '公子归来，画堂深院丛罗绮。\n绿杯浮蚁。\n风皱红鳞起。\n信马斜阳，误入桃源里。\n珠帘底。\n淡妆斜倚。\n一寸秋江水。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19380, '海棠春', '无名氏', '晓莺窗外春啼晓。\n睡未足、把人惊觉。\n翠被晓寒轻，宝篆沈烟袅。\n宿酲未解，双娥报道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19381, '宴桃源・如梦令', '无名氏', '落日霞消一缕。\n素月棱棱微吐。\n何处夜归人，呕嗄几声柔橹。\n归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19382, '祝英台・祝英台近', '无名氏', '海棠开，花影下，忆得共游戏。\n恰似双鸾，同步彩云里。\n梦回雨收云散，匆匆归去，一枕乍、惊回浓睡。\n甚情味。\n人去花亦凋零，芳伴憔悴。\n点点飞红，知是去时泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19383, '夜游宫', '无名氏', '是处追寻侣。\n灯光散、九衢红雾。\n人在星河繁闹处。\n暗相逢，惹天香，飘满路。\n游困先归去。\n奈怨别、相思情绪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19384, '杨柳枝', '无名氏', '簌簌花飞一雨残。\n乍衣单。\n屏风数幅画江山。\n水云闲。\n别易会难无计那，泪潸潸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19385, '摊破浣溪沙・山花子', '无名氏', '相恨相思一个人。\n柳眉桃脸自然春。\n别离情思，寂寞向谁论。\n映地残霞红照水，断魂芳草碧连云。\n水边楼上，回首倚黄昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19386, '一翦梅', '无名氏', '恨入椒觞暖未拈。\n春葱微蘸，谁是纤纤。\n别来愁夜不胜长，明日从教一线添。\n夜久寒深睡未。\n旧愁新恨，占断眉尖。\n一钩斜月却知人。\n直到天明，不下疏帘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19387, '卜算子', '无名氏', '垂螺近额时，只怕莺声老。\n尽日贪花斗草忙，不信有闲烦恼。\n凤鬓已胜钗，恨别王孙早。\n若把芳心说与伊，道绿遍、池塘草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19388, '忆王孙', '无名氏', '杨柳风前旗鼓闹。\n正陌上、闲花芳草。\n忍将愁眼芳菲，人未老。\n春先老。\n长安比日知多少。\n日易见、长安难到。\n无情苕水不西流，渐迤逦、仙舟小。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19389, '南歌子', '无名氏', '夕露沾芳草，斜阳带远村。\n几声残角起谯门。\n撩乱栖鸦飞舞、闹黄昏。\n天共高城远，香馀绣被温。\n客程常是可销魂。\n乍向心头横著、个人人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19390, '南歌子', '无名氏', '楼迥迷云日，溪深涨晓沙。\n年来悴憔费铅华。\n楼上一天春思、浩无涯。\n罗带宽腰素，真珠溜脸霞。\n海棠开尽柳飞花。\n薄只知游荡、不思家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19391, '南歌子', '无名氏', '玉殿分时果，金盘弄赐冰。\n晚来阶下按歌声。\n恰好一方明月、可中庭。\n露下天如水，风来夜又清。\n偏他不肯大家行。\n漾下扇儿拍手、引流萤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19392, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19393, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19394, '玉珑璁', '无名氏', '城南路。\n桥南路。\n玉钩帘卷香横雾。\n新相识。\n旧相识。\n浅颦低拍，嫩红轻碧。\n惜惜惜。\n刘郎去。\n阮郎住。\n为云为雨朝还暮。\n心相忆。\n空相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19395, '浣溪沙', '无名氏', '碎剪香罗泪痕。\n鹧鸪声断不堪闻。\n马嘶人去近黄昏。\n整整斜斜扬柳陌，疏疏密密杏花村。\n一番风月更销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19396, '点绛唇', '无名氏', '燕子依依，晓来总为谁归去。\n淡云生处。\n已觉宾鸿度。\n浅笑深颦，便面机中素。\n乘鸾女。\n琐窗琼宇。\n会有明年暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19397, '踏青游', '无名氏', '识个人人，恰正二年欢会。\n似赌赛、六只浑四。\n向巫山、重重去，如鱼水。\n两情美。\n同倚画楼十二。\n倚了又还重倚。\n两日不来，时时在人心里。\n拟问卜、常占归计。\n拚三八清齐，望永同鸳被。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19398, '玉楼春', '无名氏', '东风杨柳门前路。\n毕竟雕鞍留不住。\n柔情胜似岭头云，别泪多如花上雨。\n青楼画幕无重数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19399, '浣溪沙', '无名氏', '云锁柴门半掩关。\n垂纶犹自在前湾。\n独乘孤棹夜方还。\n任使有荣居紫禁，争如无事隐青山。\n浮名浮利总输闲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19400, '浣溪沙', '无名氏', '一副纶竿一只船。\n蓑衣竹笠是生缘。\n五湖来往不知年。\n青嶂更无荣辱到，白头终没利名牵。\n芦花深处伴鸥眠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19401, '浣溪沙', '无名氏', '钓罢高歌酒一杯。\n醉醒曾笑楚臣来。\n夕阳维缆碧江隈。\n蓑笠每因山雨戴，船窗多为水花开。\n安居流景任相催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19402, '浣溪沙', '无名氏', '雨气兼香泛芰荷。\n回舟冒雨懒披蓑。\n夜阑风静水无波。\n白酒追欢常恨少，青山入望岂嫌多。\n人间荣辱尽从他。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19403, '定风波', '无名氏', '雨雾云收望远山。\n钓竿林下恣清闲。\n蝉噪日斜林影转。\n溪岸。\n绿深红浅画屏间。\n对酒狂歌时鼓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19404, '雨中花・夜行船', '无名氏', '我有五重深深愿。\n第一愿、且图久远。\n二愿恰如雕梁双燕。\n岁岁後、长相见。\n三愿薄情相顾恋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19405, '望海潮', '无名氏', '彩筒角黍，兰桡画舫，佳时竟吊沅湘。\n古意未收，新愁又起，断魂流水茫茫。\n堪笑又堪伤。\n有临皋仙子，连璧檀郎。\n暗约同归，远烟深处弄沧浪。\n倚楼魂已飞扬。\n共偷挥玉箸，痛饮霞觞。\n烟水无情，揉花碎玉，空馀怨抑凄凉。\n杨谢旧遗芳。\n算世间纵有，不恁非常。\n但看芙蓉并蒂，他日一双双。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19406, '失调名', '无名氏', '喜则喜、得入手。\n愁则愁、不长久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19407, '扑蝴蝶', '无名氏', '烟条雨叶，绿遍江南岸。\n思归倦客，寻芳来较晚。\n岫边红日初斜，陌上飞花正满。\n凄凉数声羌管。\n怨春短。\n玉人应在，明月楼中画眉懒。\n蛮笺锦字，多时鱼雁断。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19408, '侍香金童', '无名氏', '喜叶之地，手把怀儿摸。\n甚恰恨、出题斯撞著。\n内臣过得不住脚。\n忙里只是，看得斑驳。\n骇这一身冷汗，都如云雾薄。\n比似年时头势恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19409, '啄木儿', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19410, '柳梢青', '无名氏', '晓星明灭。\n白露点、秋风落叶。\n故址颓垣，荒烟衰草，溪前宫阙。\n长安道上行客，念依旧、名深利切。\n改变容颜，销磨古今，垅头残月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19411, '眉峰碧・卜算子', '无名氏', '蹙破眉峰碧。\n纤手还重执。\n镇日相看未足时，忍便使、鸳鸯只。\n薄暮投村驿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19412, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19413, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19414, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19415, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19416, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19417, '行香子', '无名氏', '清要无因，举选艰辛。\n系书钱、须要十分。\n浮名浮利，虚苦劳神。\n叹旅中愁，心中闷，部中身。\n虽抱文章，苦苦推寻。\n更休说、谁假谁真。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19418, '失调名', '无名氏', '君是园中杨柳，能得几时青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19419, '失调名', '无名氏', '华宫瑶馆游毕。\n却返绛节、回鸾翼。\n荷殷勤、三香醪，供养我、上真仙客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19420, '湘灵瑟', '无名氏', '霜风摧兰。\n银屏生晓寒。\n淡扫眉山。\n脸红殷。\n潇湘浦，芙蓉湾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19421, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19422, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19423, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19424, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19425, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19426, '减字木兰花', '无名氏', '家门希差。\n养得一枚依样画。\n百事无能。\n只去篱边缠倒藤。\n几回水上。\n轧捺不翻真个强。\n无处容他。\n只好炎天作巴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19427, '满庭芳', '无名氏', '光芒。\n长万丈，司空见惯，应谓寻常。\n……仍传□、儋崖父老，只候蔡元长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19428, '失调名', '无名氏', '妙手庖人，搓得细如麻线。\n面儿白、心下黑，身长行短。\n蓦地下来後，吓出一身冷汗。\n这一场欢会，早危如累卵。\n便做羊肉燥子，勃推碗。\n终不似、引盘美满。\n舞万遍。\n无心看。\n愁听弦管。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19429, '浪淘沙', '无名氏', '水饭恶冤家。\n些小姜瓜。\n尊前正欲饮流霞。\n却被伊来刚打住，好闷人那。\n不免着匙爬。\n一似吞沙。\n主人若也要人夸。\n莫惜更搀三五盏，锦上添花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19430, '夜游宫', '无名氏', '因被吾皇手诏。\n把天下、寺来改了。\n大觉金仙也不小。\n德士道。\n却我甚头脑。\n道袍须索要。\n冠儿戴、恁且休笑。\n最是一种祥瑞好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19431, '西江月', '无名氏', '早岁轻衫短帽。\n中间圆顶方袍。\n忽然天赐降宸毫。\n接引私心入道。\n可谓一身三教。\n如今且得逍遥。\n擎拳稽首拜云霄。\n有分长生不老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19432, '青玉案', '无名氏', '钉鞋踏破祥符路。\n似白鹭、纷纷去。\n试幞头谁与度。\n八厢儿事，两员直殿，怀挟无藏处。\n时辰报尽天将暮。\n把笔胡填备员句。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19433, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19434, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19435, '滴滴金', '无名氏', '当初亲下求言诏。\n引得都来胡道。\n人人招是骆宝王，并洛阳年少。\n自讼监宫并岳庙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19436, '水调歌头', '无名氏', '平生太湖上，短棹几经过。\n如今重到，何事愁与水云多。\n拟把匣中长剑，换取扁舟一叶，归去老渔蓑。\n银艾非吾事，丘壑已蹉跎。\n脍新鲈，斟美酒，起悲歌。\n太平生长，岂谓今日识兵戈。\n欲泻三江雪浪，净洗胡尘千里，不用挽天河。\n回首望霄汉，双泪堕清波。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19437, '失调名', '无名氏', '做园子，得数载。\n栽培得、那花木，就中堪爱。\n特将一个、保义酬劳，反做了、今日殃害。\n诏书下来索金带。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19438, '失调名', '无名氏', '叠假山、得保义。\n幞头上、带著百般村气。\n做模样、偏得人憎，又识甚条例。\n今日伏惟安置。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19439, '结带巾', '无名氏', '头巾带。\n谁理会。\n三千贯赏钱，新行条例。\n不得向後长垂，与胡服相类。\n法甚严，人尽畏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19440, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19441, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19442, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19443, '鹊桥仙', '无名氏', '柳家一句最著题，道暮雨、芳尘轻洒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19444, '失调名', '无名氏', '你自平生行短，不公正、欺物瞒心。\n交年夜、将烧毁，犹自昧神明。\n若还替得，你可知好里，争奈无凭。\n我虽然无口，肚里清醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19445, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19446, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19447, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19448, '鹧鸪天', '无名氏', '春晓千门放钥匙。\n万官班从出祥曦。\n九重彩浪浮龙盖，一点红云护赭衣。\n车马过，打球归。\n芳尘洒定不教飞。\n钧天品动回銮曲，十里珠帘待日西。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19449, '鹧鸪天', '无名氏', '日暮迎祥对御回。\n宫花载路锦成堆。\n天津桥畔鞭声过，宣德楼前扇影开。\n奏舜乐，进尧杯。\n传宣车马上天街。\n君王喜与民同乐，八面三呼震地来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19450, '鹧鸪天', '无名氏', '紫禁烟光一万重。\n五门金碧射晴空。\n梨园羯鼓三千面，陆海鳌山十二峰。\n香雾重，月华浓。\n露台仙仗彩云中。\n朱栏画栋金泥幕，卷尽红莲十里风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19451, '鹧鸪天', '无名氏', '香雾氤氲结彩山。\n蓬莱顶上驾头还。\n绣鞯狨坐三千骑，玉带金鱼四十班。\n风细细，佩珊珊。\n一天和气转春寒。\n千门万户笙萧里，十二楼台月上栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19452, '青玉案', '无名氏', '人生南北如歧路。\n世事悠悠等风絮。\n造化小儿无定据。\n翻来覆去，倒横直竖，眼见都如许。\n伊周功业何须慕。\n不学渊明便归去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19453, '绛都春', '无名氏', '寒阴渐晓。\n报驿使探春，南枝开早。\n粉蕊弄香，芳脸凝酥琼枝小。\n雪天分外精神好。\n向白玉堂前应到。\n化工不管，朱门闭也，暗传音耗。\n轻渺。\n盈盈笑靥，称娇面、爱学宫妆新巧。\n几度醉吟，独倚栏干黄昏後。\n月笼疏影横斜照。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19454, '孤鸾', '无名氏', '天然标格。\n是小萼堆红，芳姿凝白。\n淡伫新妆，浅点寿阳宫额。\n东君相留厚意，倩年年、与传消息。\n昨夜前村雪里，有一枝先折。\n念故人、何处水云隔。\n纵驿使相逢，难寄春色。\n试问丹青手，是怎生描得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19455, '金菊对芙蓉', '无名氏', '花则一名，种分三色，嫩红妖白娇黄。\n正清秋佳景，雨霁风凉。\n郊墟十里飘兰麝，潇洒处、旖旎非常。\n自然风韵，开时不惹，蝶乱蜂狂。\n携酒独揖蟾光。\n问花神何属，离兑中央。');
