INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19538, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19539, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19540, '金钱子', '无名氏', '昨夜金风，黄叶乱飘阶下。\n听窗前、芭蕉雨打。\n触处池塘，睹风荷凋谢。\n景色凄凉，总闲却、舞台歌榭。\n独倚阑干，惟有木犀幽雅。\n吐清香、胜如兰麝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19541, '念奴娇', '无名氏', '沁园秋早。\n对亭台冷落，荒凉池沼。\n西帝晨游无异胜，都把仙花开了。\n金粟玲珑，鹅黄娇嫩，不管霜风悄。\n清香入梦，梦魂惟怕天晓。\n乘兴折取一枝，满身兰麝，不减蟾宫好。\n赠与佳人，因笑道、休学娥空老。\n待约明朝，金英满地，莫遣儿童扫。\n相将花上，醉眠尤胜芳草。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19542, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19543, '鹧鸪天', '无名氏', '五百人中第一仙。\n等闲平步上青天。\n绿袍乍著君恩重，黄榜初开御墨鲜。\n龙作马，玉为鞭。\n花如罗绮柳如绵。\n时人莫讶登科早，自是嫦娥爱少年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19544, '鹊桥仙', '无名氏', '我今夜为情忙，又那得、工夫送巧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19545, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19546, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19547, '失调名', '无名氏', '晓日楼头残雪尽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19548, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19549, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19550, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19551, '木兰花・玉楼春', '无名氏', '东风昨夜吹春昼。\n陡觉去年梅蕊旧。\n谁人能解把长绳，系得乌飞并兔走。\n清香潋滟杯中酒。\n新眼苗条江上柳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19552, '木兰花・玉楼春', '无名氏', '东风昨夜归来後。\n景物便为春意候。\n金丝齐奏喜新春，愿介香醪千岁寿。\n寻花插破桃枝臭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19553, '失调名', '无名氏', '捏个牛儿体态。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19554, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19555, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19556, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19557, '失调名', '无名氏', '金铺翠、蛾毛巧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19558, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19559, '新水令', '无名氏', '冒风连骑出金城，闻孤猿韵切，怀念亲眷。\n为笑徐都尉，徒夸彩绘，写出盈盈娇面。\n振旅阗阗。\n讶睹阆苑神仙。\n越公深骤万马，侵凌转盼。\n感先锋，容放镜，收鸾鉴一半。\n归前阵，惨怛切，同陪元帅恣欢恋。\n二岁偶尔，将军沈醉连绵，私令婢捧菱花，都市寻遍。\n新官听说邀郎宴。\n因令赋悲欢。\n孰敢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19560, '驻马听', '无名氏', '雕鞍成谩驻。\n望断也不归，院深天暮。\n倚遍旧日，曾共凭肩门户。\n踏青何处所，想醉拍、春衫歌舞。\n征旆举。\n一步红尘，一步回顾。\n行行愁独语。\n想媚容、今宵怨郎不住。\n来为相思苦。\n又空将愁去。\n人生无定据。\n叹後会、不知何处。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19561, '南歌子', '无名氏', '禁苑沈沈静，春波漾漾行。\n仙姿才韵两相并。\n叶上题诗、千古得佳名。\n墙外分明见，花间隐约声。\n银钩掷处眼双明。\n应讶昔时、不得见情人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19562, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19563, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19564, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19565, '阮郎归', '无名氏', '及妆时结薄衫儿。\n蒙金艾虎儿。\n画罗领抹缬裙儿。\n盆莲小景儿。\n香袋子，搐钱儿。\n胸前一对儿。\n绣帘妆罢出来时。\n问人宜不宜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19566, '阮郎归', '无名氏', '门儿高挂艾人儿。\n鹅儿粉扑儿。\n结儿缀着小符儿。\n蛇儿百索儿。\n纱帕子，玉环儿。\n孩儿画扇儿。\n奴儿自是豆娘儿。\n今朝正及时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19567, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19568, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19569, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19570, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19571, '失调名', '无名氏', '从前浪荡休整理。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19572, '失调名', '无名氏', '天上佳期。\n九衢灯月交辉。\n摩孩儿，斗巧争奇。\n戴短檐珠子帽，披小缕金衣。\n嗔眉笑眼，百般地、敛手相宜。\n转晴底、工夫不少，引得人爱後如痴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19573, '伊州曲', '无名氏', '金鸡障下胡雏戏。\n乐极祸来，渔阳兵起。\n鸾舆幸蜀，玉环缢死。\n马嵬坡下尘滓。\n夜对行宫皓月，恨最恨、春风桃李。\n洪都方士。\n念君萦系。\n妃子。\n蓬莱殿里。\n觅寻太真，宫中睡起。\n遥谢君意。\n泪流琼脸，梨花带雨，仿佛霓裳初试。\n寄钿合、共金钗，私言徒尔。\n在天愿为、比翼同飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19574, '失调名', '无名氏', '月到中秋偏莹。\n乍团圆、早欺我孤影。\n穿帘共透幕，来寻趁。\n钩起窗儿，里面故把、灯儿扑烬。\n看尽古今歌咏。\n状玉盘、又拟金饼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19575, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19576, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19577, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19578, '倾杯序・倾杯乐', '无名氏', '昔有王生，冠世文章，尝随旧游江渚。\n偶尔停舟寓目，遥望江祠，依依陌上闲步。\n恭诣殿砌，稽首瞻仰，返回归路。\n遇老叟，坐于矶石，貌纯古。\n因语□，子非王勃是致，生惊询之，片饷方悟。\n子有清才，幸对滕王高阁，可作当年词赋。\n汝但上舟，休虑。\n迢迢仗清风去。\n到筵中、下笔华丽，如神助。\n会俊侣。\n面如玉。\n大夫久坐觉生怒。\n报云落霞并飞孤鹜。\n秋水长天，一色澄素。\n阎公竦然，复坐华筵，次诗引序。\n道鸣鸾佩玉，锵锵罢歌舞。\n栋云飞过南浦。\n暮帘卷向西山雨。\n闲云潭影，淡淡悠悠，物换星移，几度寒暑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19579, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19580, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19581, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19582, '蝶恋花', '无名氏', '花为年年春易改。\n待放柔条，系取春常在。\n宫样妆成还可爱。\n鬓边斜作拖枝戴。\n每到无情风雨大。\n点检群芳，却是深丛耐。\n摇曳绿罗金缕带。\n丹青传得妖娆态。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19583, '如梦令', '无名氏', '今夜荼シ风起。\n应是玉消琼碎。\n淡荡满城春，恼破愁人春睡。\n须醉。\n须醉。\n莫待梅黄雨细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19584, '最高楼', '无名氏', '司春有序，排次到荼シ。\n远预报，在庭知。\n蕊珠宫里晨妆罢，披香殿下晓班齐。\n探花正、驱使问，菊花期。\n元不逊、梅花浮月影，也知妒、梨花带雨枝。\n偏恨柳、绿条垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19585, '南柯子・南歌子', '无名氏', '翠袖熏龙脑，乌云映玉台。\n春葱一簇荐金杯。\n曾记西楼同醉、角声催。\n袅袅凌波浅，深深步月来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19586, '满庭芳', '无名氏', '青幄高张，琼枝巧缀，万颗香染红殷。\n绛罗衣润，疑是火然山。\n白玉钗头试，黄金带、奇巧工钻。\n题评处，仙家异种，分付在人间。\n年年。\n输帝里，欢呼内监，妆点金盘。\n况曾得真妃，笑脸频看。\n炎岭当时奏曲，风流命、乐府名传。\n凭谁道、移归禁苑，长使近天颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19587, '浣溪沙', '无名氏', '酒拍胭脂颗颗新。\n丹砂然火弃精神。\n暑天秋杪锦生春。\n香味已惊樱实淡，绛皮还笑荔枝皴。\n美人偏喜破朱唇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19588, '南柯子・南歌子', '无名氏', '积雪迷松迳，围炉掩竹扉。\n床头一味有蹲鸱。\n软火深开香熟、已多时。\n自得陶朱法，休教懒瓒知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19589, '贺新郎', '无名氏', '天意扶炎宋。\n为吾皇、维衡狱孕，长沙星梦。\n社稷勋庸天地窄，不数智名功勇。\n要自有、胸中妙用。\n擎着东南一柱，看边民、买犊归耕种。\n官职易，此身重。\n黄封已见传宣送。\n却春来、洪钧初转，紫枢归拱。\n岁岁玉楼春处，慧质明妆环拥。\n正弟劝、兄酬欢纵。\n一寸丹心坚似铁，待磨崖、勒就浯溪颂。\n龙尾道，接天踵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19590, '贺圣朝', '无名氏', '太平无事，四边宁静狼烟眇。\n国泰民安，谩说尧舜禹汤好。\n万民翘望彩都门，龙灯凤烛相照。\n只听得教坊杂剧欢笑。\n美人巧。\n宝宫前，咒水书符断妖。\n更梦近、竹林深处胜蓬岛。\n笙歌闹。\n奈吾皇，不待元宵景色来到。\n只恐後月，阴晴未保。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19591, '踏莎行', '无名氏', '宴罢琼林，醉游花市，此时方显男儿志。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19592, '祝英台近', '无名氏', '客毡寒，兰房悄，金炉红兽。\n好个霜天，消遣正宜酒。\n嫩橙初截鹅肪，肌肤香透。\n又还记、吴姬纤手。\n事难偶。\n墨冻空染梨笺，新词谩题就。\n酒薄愁浓，枕听寒漏。\n可堪霜月亭亭，照人无寐，映窗外、一枝梅瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19593, '花心动', '无名氏', '碧瓦朱甍，销千门沈沈，丽日初旭。\n画栋暗尘，锦瑟空弦，窈窕故窗红绿。\n御柳宫花依然好，春不管、为谁妆束。\n翠华远，风光尽属，野樵夷牧。\n指似行人恸哭。\n尚能道、先朝圣游不足。\n凤辇路荒，龙沼波乾，犹有弃珠遗玉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19594, '西江月', '无名氏', '梁上喃喃燕语，纸间戢戢蚕生。\n满城风雨近清明。\n不道有人新病。\n春事一溪流水，杨花千点浮萍。\n好风一霎为吹晴。\n独步小园清影。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19595, '梅花引', '无名氏', '清阴陌。\n狂踪迹。\n朱门团扇香迎客。\n牡丹风。\n数苞红。\n水香扑蕊，新妆谁为容。\n蜡灯春酒风光夕。\n锦浪龙须花六尺。\n月波寒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19596, '恋绣衾', '无名氏', '元宵三五酒半醺。\n马蹄前、步步是春。\n闹市里、看灯去，喜金吾、不禁夜深。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19597, '青玉案', '无名氏', '年年社日停针线。\n怎忍见、双飞燕。\n今日江城春已半。\n一身犹在，乱山深处，寂寞溪桥畔。\n春衫著破谁针线。\n点点行行泪痕满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19598, '捣练子', '无名氏', '偏□戏，最风流。\n斗帐金猊暖不收。\n一阵蜜蜂狂絮里，酒酣眠折玉搔头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19599, '捣练子', '无名氏', '初酒醒，乍衣单。\n褪著裙儿侧著冠。\n门外小桥寒食夜，月明人去杏花残。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19600, '楼心月', '无名氏', '柳下争拿画浆摇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19601, '楼心月', '无名氏', '手把新荷叶一枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19602, '楼心月', '无名氏', '新著生红小舞衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19603, '花心动', '无名氏', '粉堞云齐，度清笳、愁入暮烟林杪。\n素艳透春，玉骨凄凉，勾带月痕生早。\n江天苍莽黄昏後，依然是、粉寒香瘦。\n动追感、西园嫩约，夜深人悄。\n记得东风窈窕。\n曾夜踏横斜，醉携娇小。\n惆怅旧欢，回首俱非，忍看绿笺红豆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19604, '踏莎行', '无名氏', '酒情怀，恨春时节。\n柳丝巷陌黄昏月。\n把君团扇卜君来，近墙扑得双蝴蝶。\n笑不成言，喜还生怯。\n颠狂绝似前春雪。\n夜寒无处著相思，梨花一树人如削。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19605, '鹧鸪天', '无名氏', '题得相思字数行。\n起来桐叶满纱窗。\n秋光欲雨棋声泻，粉帐不容花露香。\n新寂寞，旧疏狂。\n玉炉消息记钱塘。\n小阑立遍红蕉树，一带残云趁月黄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19606, '阮郎归', '无名氏', '薄罗生色画酴。\n酴满架时。\n隔池贪看燕争泥。\n坠双红荔支。\n销金字，晚唐诗。\n夹纱团扇儿。\n自遮微雨傍花归。\n个情天得知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19607, '青门怨', '无名氏', '月烟景。\n远思孤影。\n旧梦云飞，离魂冰冷。\n脉脉恨满东风。\n对孤鸿。\n翠珠尘冷香如雾。\n人何许。\n心逐章台絮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19608, '水调歌头', '无名氏', '不能烦恼得，掉臂便归休。\n前度风樯，这回潦辙几悠悠。\n幸得有云一谷，更自有书万卷，著甚麽来由。\n月采混鱼目，霜口蝇头。\n相山中，侯醉境，将诗流。\n情知薄命，天样勋业也须收。\n辟逻世间万事，推放那边一壁，百尺卧高楼。\n日月草头露，天地水中沤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19609, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19610, '霜天晓角', '无名氏', '一声阿鹊。\n人在云西角。\n信有黄昏风雨，孤灯酒、不禁酌。\n错错。\n谁误著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19611, '满庭芳', '无名氏', '凤阁祥烟，龙城佳气，明恭谢时丰。\n绮罗争看，帘幕卷南风。\n十里仙仪宝仗，暖红翠、玉碾玲珑。\n銮回也，箫韶缓奏，声在五云中。\n千官，迎万乘，丝纶叠叠，锦绣重重。\n听鸣辇路，宴罢鳌宫。\n瞻仰天颜有喜，君恩霈、寰宇雍容。\n生平愿，洪基巩固，圣寿永无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19612, '庆清朝', '无名氏', '银漏花残，红消烛泪。\n九重鱼钥欢声沸。\n奏万乘、祥曦门外。\n盖圣君、恭谢灵休，谨访景明嘉礼。\n天意好，祥风瑞月，时正当、小春天气。\n禁街十里香中，御辇万红影里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19613, '御街行', '无名氏', '时康三载升平世。\n恭谢三朝礼。\n群臣禁卫带花回，龊巷儿郎精锐。\n战袍新样团雕拥，重隘围子队。\n绣衣花帽挨排砌。\n锦仗天街里。\n有如仙队玉京来，妙乐钧天盈耳。\n都民观望时，果是消灾灭罪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19614, '瑞鹤仙', '无名氏', '是欢声盈万户。\n庆景陵礼毕，銮舆游步。\n西郊暖风布。\n喜湖山深锁，非烟非雾。\n传收绣羽。\n骅骝驰骤绒缕。\n望彤芳、稳稳金銮，衮鸾翔舞。\n云驭。\n近回天厩，锡宴琼津，洪恩均顾。\n霞天向暮。\n翠华动，舞韶举。\n绛纱笼千点，星飞清禁，银烛交辉辇路。\n瑞光中、渺祝无疆，太平圣主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19615, '真珠帘', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19616, '沁园春', '无名氏', '国步多艰，民心靡定，诚吾隐忧。\n叹浙民转徙，怨寒嗟暑，荆襄死守，阅岁经秋。\n虏未易支，人将相食，识者深为社稷羞。\n当今亟，出陈大谏，箸借留候。\n□□迂阔为谋。\n天下士如何可籍收。\n况君能尧舜，臣皆稷契，世逢汤武，业比伊周。\n政不必新，贯仍宜旧，莫与秀才做尽休。\n吾元老，广四门贤路，一柱中流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19617, '小重山', '无名氏', '鼓报黄昏禽影歇。\n单衣犹未试，觉寒怯。\n尘生锦瑟可曾阅。\n人去也，闲过好时节。\n对景复愁绝。\n东风吹不散，鬓边雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19618, '谒金门', '无名氏', '休只坐。\n也去看花则个。\n明日满庭红欲堕。\n花还愁似我。\n索性痴眠一和。\n凭个梦儿好做。\n杜宇不知春已过。\n枝头声越大。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19619, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19620, '行香子', '无名氏', '浙右华亭。\n物价廉平。\n一道会、卖个三升。\n打开瓶後，滑辣光馨。\n教君霎时饮，霎时醉，霎时醒。\n听得渊明。\n说与刘伶。\n这一瓶、约迭三斤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19621, '长相思', '无名氏', '晴也行。\n雨也行。\n雨也行时不似晴。\n天晴终快人。\n名也成。\n利也成。\n利也成时不似名。\n名成天下惊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19622, '摸鱼儿', '无名氏', '过湘皋、碧龙惊起，冰涎犹护髯影。\n春洲未有菱歌伴，独占暮烟千顷。\n呼短艇。\n试翦取纤条，玉溜青丝莹。\n尊前细认。\n试水面新荷，波心半掩，点点翠钿净。\n凄凉味，酪乳那堪比并。\n吴盐一箸秋冷。\n当时不为鲈鱼去，聊尔动渠归兴。\n还记省。\n是几度西风，几度吹愁醒。\n鸥昏鹭瞑。\n谩换得霜痕，萧萧两鬓，羞与共秋镜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19623, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19624, '多丽', '无名氏', '日初长，宝炉一缕沈烟。\n绿阴新，垂杨亭榭，知谁巧擘香绵。\n有时共、落红零乱，有时共、芳草留连。\n只道无情，那知有意，几回飞过绮窗前。\n人争讶，艳阳三月，乾雪舞晴天。\n游丝外，不堪燕掠，无奈蜂黏。\n那小鬟、忒娇劣，镇日地、倚阑干。\n轻吹处、樱桃的的，闲拈处、笋指纤纤。\n爱点猩罗，装成粉缬，嗔人不许放朱帘。\n端相好、蓦然风起，特送上秋千。\n明朝看，池塘雨过，萍翠应添。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19625, '沁园春', '无名氏', '我善观梅，识梅妙处，舍我其谁。\n待裁冰翦雪，已无足道，凝酥弄粉，愈不为奇。\n枉费心神，巡檐索笑，点检南枝并北枝。\n梅应道，似这般题品，未是相知。\n分明有个端倪。\n遮莫把人间凡眼窥。\n那精神全在，半含蕊处，风流全在，未有香时。\n万木丛边，两三点白，此是生生化化机。\n花开也，又怎生消得，个样词儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19626, '壶中天・念奴娇', '无名氏', '日长晴昼。\n厌厌地、懒向窗前绣。\n因倚屏风无意绪，□把眉儿双皱。\n似醉还醒，才眠又起，频拈梨花嗅。\n看他儿女，闲寻百草来斗。\n相思能几何时，料归期不到，清和时候。\n生怕鸳鸯香被冷，旋沈檀薰透。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19627, '满江红', '无名氏', '一点阳和，天不许、凡花先得。\n这些儿深意，蜂蝶怎生窥测。\n北陆正当风凛冽，南枝却漏春消息。\n教琼仙、翦水缀成葩，天然白。\n影横处，寒窗月。\n香浮处，寒梢雪。\n被东皇做就，这般标格。\n虽是腊前年後景，终非竹外篱边物。\n不安排、顿放玉堂中，真堪惜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19628, '买坡塘・摸鱼儿', '无名氏', '喜西风、朝来如约，新凉一雨初霁。\n家山望断知何处，渺渺长天秋水。\n空眼底。\n叹雁杳鱼沈，尺纸无人寄。\n芸窗草砌。\n渐影颤疏桐，声敲落叶，孤枕怎成睡。\n逢场戏。\n遮莫悲秋憔悴。\n今朝有酒须醉。\n尊前待唤佳人道，为雪藕丝轻脆。\n闲省记。\n便笑口频开，一岁知能几。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19629, '瑞鹤仙', '无名氏', '赏残陶径菊。\n正袅袅愁予，风凄露肃。\n何人抱幽独。\n更檐马锵金，廊鱼响木。\n此情谁属。\n向底处、骋怀游目。\n小窗前，频览菱花，一笑鬓丝犹绿。\n萧索。\n故国云迷，佳人日暮，轻颦倚竹。\n短钗敲玉。\n算几夜，恁孤宿。\n问旅情如许，怎生排遣，应费酒尊诗轴。\n最无端、谁隔西楼，正调弦促。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19630, '更漏子', '无名氏', '画楼深，春昼永。\n帘幕东风微冷。\n莺啭罢，燕归来。\n佳人午梦回。\n鬓钗横，眉黛浅。\n一捻楚腰纤软。\n推绣户，倚雕阑。\n无言看牡丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19631, '更漏子', '无名氏', '鬓慵梳，眉懒画。\n独自行来花下。\n情脉脉，泪垂垂。\n此情知为谁。\n雨初晴，帘半卷。\n两两衔泥新燕。\n人比燕，不成双。\n枉教人断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19632, '更漏子', '无名氏', '粉墙低，蓬户小。\n一点尘运不到。\n眠纱帐，坐蒲团。\n道人随分安。\n笋芽新，蔬甲嫩。\n日日家常羹饭。\n羹饭罢，怎消闲。\n携筇出看山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19633, '愁倚阑令・春光好', '无名氏', '东风恶，宿云凝。\n忒无情。\n合造梨花深院雨，断肠声。\n枕上春梦初醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19634, '红窗迥', '无名氏', '河可挽。\n石可转。\n那一个愁字，却难驱遣。\n眉向酒边暂展。\n酒後依旧见。\n枫叶满阶红万片。\n待拾来、一一题写教遍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19635, '一翦梅', '无名氏', '漠漠春阴酒半酣。\n风透春衫。\n雨透春衫。\n人家蚕事欲眠三。\n桑满筐篮。\n柘满筐篮。\n先自离怀百不堪。\n樯燕呢喃。\n梁燕呢喃。\n篝灯强把锦书看。\n人在江南。\n心在江南。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19636, '长相思', '无名氏', '不思量。\n又思量。\n一点寒灯耿夜光。\n鸳衾闲半床。\n雨声长。\n漏声长。\n几阵斜风摇纸窗。\n如何不断肠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19637, '长相思', '无名氏', '云垂垂。\n雨霏霏。\n只恐今年花事迟。\n不然孤负伊。\n燕飞飞。\n柳依依。\n有个人人倚翠扉。\n深攒双黛眉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19638, '长相思', '无名氏', '雨如丝。\n柳如丝。\n织出春来一段奇。\n莺梭来往飞。\n酒如池。\n醉如泥。\n遮莫教人有醒时。\n雨晴都不知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19639, '长相思', '无名氏', '燕成双。\n蝶成双。\n飞去飞来杨柳旁。\n问伊因底忙。\n绿纱窗。\n篆炉香。\n午梦惊回书满床。\n棋声春昼长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19640, '采桑子', '无名氏', '年年才到花时候，风雨成旬。\n不肯开晴。\n误却寻花陌上人。\n今朝报道天晴也，花已成尘。\n寄语花神。\n何似当初莫做春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19641, '风光好', '无名氏', '柳阴阴。\n水深深。\n风约双凫不自禁。\n碧波心。\n孤村桥断人迷路。\n舟横渡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19642, '虞美人', '无名氏', '□□□□□□□。\n□□□□□。\n□□□□□□□。\n□□□□□□、□□□。\n□□□□□□处。\n归向桃源住。\n桃源有路透渔溪。\n自恨仙凡从此、隔云泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19643, '虞美人', '无名氏', '绮疏人把罗衣叠。\n岫幌铺残月。\n宝烟细袅博山中。\n梦惹暖红鸳锦、醉香风。\n觉来犹记乘鸾处。\n不是蓝桥住。\n落花流水认前溪。\n想见五云为路、静无泥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19644, '虞美人', '无名氏', '悲商吹尽枝间绿。\n绛萼含冰玉。\n为谁搀早冒寒开。\n应念天涯憔悴、挽春回。\n玉壶自酌清漪满。\n又识东风面。\n夜深斜月印窗纱。\n好在数枝疏瘦、两三花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19645, '虞美人', '无名氏', '萧萧风竹千蛟舞。\n云阁催诗雨。\n中秋时节变新凉。\n又是一番红叶、下三湘。\n君如膝上王文度。\n早晚乡关去。\n绣香佳处且留连。\n正好橙黄橘绿、未寒天。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19646, '虞美人', '无名氏', '当年合德并飞燕。\n涎涎无人见。\n清魂沦入海棠枝。\n料想天寒同著、翠罗衣。\n同心佩带连环玉。\n并髻云鬟绿。\n谁教红萼自成双。\n恰似新荷叶里、睡鸳鸯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19647, '木兰花・玉楼春', '无名氏', '小桃枝上东风转。\n□□草绿江南岸。\n绿杨学舞小蛮腰，红药惜开菩萨面。\n故乡何处天涯远。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19648, '朝中措', '无名氏', '严霜封草树凋红。\n叶落小园空。\n何事洛阳花面，却来冠冕秋风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19649, '朝中措', '无名氏', '红鸾飞下绿云中。\n天淡日和融。\n回首小园桃杏，怜伊独困霜风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19650, '朝中措', '无名氏', '洛阳常见画图中。\n春去只心融。\n国色辉开寒日，天香熏破霜风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19651, '朝中措', '无名氏', '从来黄菊占秋风。\n红只许芙蓉。\n正是百花浓睡，如何唤起春工。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19652, '朝中措', '无名氏', '宦游只欲赋归休。\n花为解离愁。\n看取星星潘鬓，花应羞上人头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19653, '西江月', '无名氏', '草市人归日落，荒城风急鸦翻。\n独携尊酒上高寒。\n缥缈云横楚观。\n柳外半篙绿水，烟中数笔青山。\n天涯流落岁将残。\n望断故园心眼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19654, '西江月', '无名氏', '扑扑云垂四野。\n冥冥雁下平芜。\n萧萧风叶乱黄芦。\n寒入一滩鸥鹭。\n准拟云窗水榭。\n装成玉树冰壶。\n卷帘独坐拈髭须。\n待看六花飞舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19655, '西江月', '无名氏', '风雨朝来恶甚，池塘春去无多。\n绿杨阴里溜莺棱。\n枝上老红犹堕。\n酒满蚁浮金，烛残泪滴铜荷。\n更阑孤枕奈情何。\n只恐巫山梦破。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19656, '西江月', '无名氏', '花下春光正好，柳边春色才多。\n雨声日夜长沧波。\n暗地芳心滴破。\n拍拍浪飞白雪，冥冥山点青螺。\n汀兰岸芷有情麽。\n还惜江城春过。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19657, '西江月', '无名氏', '膝下红金不暖，窗前绛蜡犹然。\n夜深城麓走风烟。\n的砾还飘雪霰。\n海上正迷蝶梦，山阴未棹溪船。\n愿骑白凤玉为鞭。\n西赴瑶池芳宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19658, '西江月', '无名氏', '琼沼融成沆瀣，冰檐滴尽真珠。\n一园草木气方苏。\n又学杨花飞舞。\n何必乱飘密洒，却疑细糁轻铺。\n谁将粉墨画成图。\n玉做小亭高树。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19659, '西江月', '无名氏', '翦翦轻寒雨後，瞳瞳晓日晴时。\n春风先到绿杨枝。\n金缕野桥山市。\n巧调琴筑，海棠惜吐胭脂。\n玉骢未解锦障泥。\n且挂征鞭一醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19660, '西江月', '无名氏', '翠岭游仙梦破，暖香残酒醒时。\n子规啼月下花枝。\n日涌山光照市。\n柳拂眉间黛色，桃匀脸上胭脂。\n凄凄芳草路无泥。\n脉脉归心似醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19661, '西江月', '无名氏', '风雨馀寒过了，池塘春水生时。\n迁莺飞上拂云枝。\n春遍柳村花市。\n酒面清空似水，玉杯温莹如脂。\n莫教花谢尘泥。\n把住东君索醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19662, '点绛唇', '无名氏', '晓翠初分，挂藤窈窕穿深静。\n乌啼风径。\n竹舞千蛟影。\n又过重阳，感叹伤流景。\n人多病。\n酒杯慵问。\n闲却金卮柄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19663, '好事近', '无名氏', '篱落晓来霜，花嫩不禁寒力。\n脉脉自摇疏影，印一奁空碧。\n天生潇洒谢夫人，绝世有谁识。\n何必嫣然一笑，已倾城倾国。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19664, '秦楼月・忆秦娥', '无名氏', '□□□。\n□□□□□□□。\n□□□。\n□□□□，□□□□。\n白鸥飞下屏山曲。\n行人点破秋郊绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19665, '秦楼月・忆秦娥', '无名氏', '秋漠漠。\n登临常羡东飞鹤。\n东飞鹤。\n一襟乡泪，为君双落。\n明年不负黄花约。\n故人须我归舟泊。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19666, '秦楼月・忆秦娥', '无名氏', '风淅淅。\n天容暗淡梅花白。\n梅花白。\n点酥凝粉，比君不得。\n清歌飞下龙沙雪。\n绮疏休印蟾宫月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19667, '西地锦', '无名氏', '重过黄梁古驿。\n著一鞭春色。\n长亭细柳，青青尚浅，不禁攀折。\n且醉章台风月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19668, '如梦令', '无名氏', '试问春归何处。\n红入小桃花树。\n同访古章台，把盏重听金缕。\n休去。\n休去。\n应被好山留住。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19669, '清平乐', '无名氏', '风不定。\n舞碎海棠红影。\n数点雨声池上听。\n湿尽一庭花冷。\n倚阑多少心情。\n轻寒未放春晴。\n谁管天涯憔悴，楚乡又过清明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19670, '浣溪沙', '无名氏', '遍地轻阴绿满枝。\n乍晴初试袷罗衣。\n东风院落日长时。\n池边飞燕子，海棠花里闹蜂儿。\n一春心事只春知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19671, '望江南・忆江南', '无名氏', '清夜老，流水淡疏星。\n云母窗前生晓色，梧桐叶上得秋声。\n村落一鸡鸣。\n催唤起，带梦著冠缨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19672, '醉蓬莱', '无名氏', '见笋成新竹，燕教雏飞，画堂清昼。\n萱草榴花，遍小庭如绣。\n角簟纱厨，葛巾葵扇，正麦秋时候。\n玉尘生风，け然隐几，香蟠金兽。\n又值生初，故乡何在，三楚云高，谩劳回首。\n睡起情怀，况渊明止酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19673, '满庭芳', '无名氏', '梅子成阴，海棠初谢，小园才过清明。\n百花扫地，红紫践为尘。\n别有烟红露绿，嫣然笑、管领东君。\n还知否，天香国色，独步殿馀春。\n轻盈。\n多态度，洛阳图画，韩令经营。\n想谪仙风韵，洒面词成。\n一捻深红尚透，谁信道、花亦通灵。\n君休待、花归阆苑，莫惜醉山倾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19674, '汉宫春', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (19675, '瑞鹤仙', '无名氏', '恨佳人命薄。\n似春云无定，杨花飘泊。');
