INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20437, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20438, '江城梅花引', '无名氏', '逋仙千载独知心。\n别无人。\n泪痕深。\n长是自开自落自成阴。\n白石後来疏影句，饶绮丽，总输他、清浅吟。\n伤情。\n伤情。\n角中声。\n夜沉沉。\n更捣砧。\n欲雪未雪、天欲老，云气昏昏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20439, '踏莎行', '无名氏', '瘦影横斜，断桥路小。\n如今梦断孤山了。\n冷魂趁鹤不归来，荒山没尽深深草。\n月下罗浮，一樽自笑。\n旧枝尚记幽禽抱。\n王令人梦里说相思，被谁惊破霜天晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20440, '满江红', '无名氏', '雪後郊原，烟林静、梅花初拆。\n春初半、犹自探春消息。\n一眼平芜看不尽，夜来小雨催新碧。\n笑去年、携酒折花时，君应识。\n兰舟漾，城南陌。\n云影淡，天容窄。\n绕风漪十顷，遥浮晴色。\n恰似槎头收钓处，坐中仍有江南客。\n试与问、何如两桨下苕溪，吞梦泽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20441, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20442, '献仙桃', '无名氏', '元宵嘉会赏春光。\n盛事当年忆上阳。\n尧颡喜瞻天北极，舜衣深拱殿中央。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20443, '献天寿慢・献天寿', '无名氏', '日暖风和春更迟。\n是太平时。\n我从蓬岛整容姿。\n来降贺丹墀。\n幸逢灯夕真佳会，喜近天威。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20444, '献天寿令', '无名氏', '阆苑人间虽隔，遥闻圣德弥高。\n西离仙镜下云霄。\n来献千岁灵桃。\n上祝皇龄齐天久，犹舞蹈、贺贺圣朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20445, '金盏子慢・金盏子', '无名氏', '丽日舒长，正葱葱瑞气，遍满神京。\n九重天上，五云开处，丹楼碧阁峥嵘。\n盛宴初开，锦帐绣幕交横。\n应上元佳节，君臣际会，共乐升平。\n广庭。\n罗绮纷盈。\n动一部、笙歌尽新声。\n蓬莱宫殿神仙景。\n浩荡春光，逦迤王城。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20446, '金盏子令', '无名氏', '东风报暖，到头嘉气渐融怡。\n巍峨凤阙，起鳌山万仞，争耸云涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20447, '瑞鹧鸪慢・瑞鹧鸪', '无名氏', '海东今日太平天。\n喜望龙云庆会筵。\n尾扇初开明黼座，画帘高卷罩祥烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20448, '瑞鹧鸪慢・瑞鹧鸪', '无名氏', '北暴东顽，纳款慕义争来。\n日新君德更明哉。\n歌咏载衢街。\n清宁海宇无馀事，乐与民同燕春台。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20449, '寿延长中腔令・寿延长', '无名氏', '彤云映彩色相映，御座中、天簇簪缨。\n万花铺锦满高庭。\n庆敞需宴欢声。\n千龄启统乐功成。\n同意贺、元丰擎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20450, '寿延长破字令', '无名氏', '青春玉殿和风细。\n奏箫韶络绎。\n瑞绕行云飘飘曳。\n泛金尊、流霞艳溢。\n瑞日晖晖临丹。\n广布慈德宸遐迩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20451, '步虚子令', '无名氏', '碧烟笼晓海波闲。\n江上数峰寒。\n佩环声里，异香飘落人间。\n弭绛节、五云端。\n宛然共指嘉禾瑞，开一笑、破朱颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20452, '破字令', '无名氏', '缥缈三山岛。\n十万岁、方分昏晓。\n春风开遍碧桃花，为东君一笑。\n祥飙暂引香尘到。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20453, '抛球乐折花令・抛球乐', '无名氏', '翠幕华筵，相将正是多欢宴。\n举舞袖、回旋遍。\n罗绮簇宫商，共歌清羡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20454, '抛球乐水龙吟令・抛球乐', '无名氏', '洞天景色常春，嫩红浅白开轻萼。\n琼筵镇起，金炉烟重，香凝锦幄。\n窈窕神仙，妙呈歌舞，攀花相约。\n彩云月转，朱丝网徐在，语笑抛球乐。\n绣袂风翻凤举，转星眸、柳腰柔弱。\n头筹得胜，欢声近地，光容约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20455, '抛球乐小抛球乐・抛球乐', '无名氏', '两行花窍占风流。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20456, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20457, '失调名', '无名氏', '');
