INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20461, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20462, '清平令破子・清平乐', '无名氏', '满庭罗绮流粲。\n清朝画楼开宴。\n似初发芙蓉正烂熳。\n金尊莫惜频劝。\n近看柳腰似折。\n更看舞回流雪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20463, '惜奴娇', '无名氏', '春早皇都冰泮。\n宫沼东风布轻暖。\n梅粉飘香，柳带弄色，瑞霭祥烟凝浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20464, '惜奴娇', '无名氏', '无算。\n仗委东君遍。\n有风光、占五陵闲散。\n从把千金，五夜继赏，并彻春宵游玩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20465, '惜奴娇', '无名氏', '夸帝里。\n万灵咸集，永卫紫陌青楼，富臻既庶矣。\n四海升平，文武功勋盖世。\n赖圣主，兴贤佐，恁致理。\n气绪凝和，会景新、访雅致。\n列群公锡宴在迩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20466, '惜奴娇', '无名氏', '景云披靡。\n露轻寒若水。\n尽是游人美。\n陌尘润、宝沉递。\n笑指扬鞭，多少高门胜会。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20467, '惜奴娇', '无名氏', '盛日凝理。\n羽巢可窥。\n阆苑金关启扉。\n烬连宵、宁防避。\n暗尘随马，明月逐人无际。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20468, '惜奴娇', '无名氏', '骋轮纵勒，翠羽花钿比织。\n并雅同陪，共越九衢遍，尽遨逸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20469, '惜奴娇', '无名氏', '莫如胜慨，景压天街际。\n彩鳌举、百仞耸倚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20470, '惜奴娇', '无名氏', '渐灼兰膏，覆满青烟罩地。\n簇宫花、荡纷委。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20471, '惜奴娇', '无名氏', '楼起霄宫里。\n五福中天纷绛瑞。\n弦管齐谐，清宛振逸天外。\n万舞低回纷绕，罗纨摇曳。\n顷刻转轮归去，念感激天意。\n幸列熙台，洞天遥遥望圣梓。\n五夕华胥，鱼钥并开十二。\n圣景难逢无比。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20472, '万年欢慢・万年欢', '无名氏', '禁初晴，见万年枝上，工啭莺声。\n藻殿连云，萍曦高照檐楹。\n好是帘开丽景，袅金炉、香暖烟轻。\n传呼道、天跸来临，两行拱引簪缨。\n看看筵敞三清。\n洞宝玉杯中，满酌犀觥。\n烂熳芳葩，斜簪庆快春情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20473, '万年欢慢・万年欢', '无名氏', '当今圣主，理化感四塞，永减狼烟。\n太平朝野无征战，国内晏然。\n风调雨顺歌声喧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20474, '万年欢慢・万年欢', '无名氏', '妁要肢轻婀娜。\n学内样、深深梳果。\n如五凤双鸾相对舞，随腰带、乍游琐。\n莺幕、满头花，见绿杨摸蔌。\n金阶献，一庭细管繁弦里，谁把ㄉ抛过。\n舞鸾双翥，香兽低。\n散瑞景烟微。\n投袂翩翩，趁拍迟迟。\n按曲度瑶池。\n曲遍新声，敛绣衣跪。\n彩袖高捧琼卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20475, '忆吹箫慢・凤凰台上忆吹箫', '无名氏', '血洒霜罗，泪薄艳锦，伊方教我成行。\n渐望断、斜桥暮柳，曲水归云。\n月暗风高露冷，独自才抵孤城。\n江南远，今夜就中，愁损行人。\n愁人。\n旧香遗粉，空淡淡馀暖，隐隐残痕。\n到这里、思量是我，忒无情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20476, '月华清慢・月华清', '无名氏', '雨洗天开，风将云去，极目都无纤翳。\n当遇中秋夜，静月华如水。\n素光晃、金屋楼台，清气彻、玉壶天地。\n此际。\n比无常三五，婵娟特异。\n因念玉人千里。\n待尽把愁肠，分付沉醉。\n只恐难当漏尽，又还经岁。\n最堪恨、独守书帏，空对景、不成欢意。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20477, '感皇恩令・感皇恩', '无名氏', '和袖把金鞭，腰如束素。\n骑介驴儿过门去。\n禁街人静，一阵香风满路。\n凤鞋宫样小，弯弯露。\n蓦地被他，回眸一顾。\n便是令人断肠处。\n愿随鞭镫，又被名缰勒住。\n恨身不做个，闲男女。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20478, '醉太平', '无名氏', '厌厌闷着。\n厌厌闷着。\n奴儿近日听人咬，把初心忘却。\n教人病深谩摧拙。\n凭谁与我分说破，仔细思量怎奈何，见了伏些弱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20479, '还宫乐', '无名氏', '喜贺我皇，有感蓬莱，尽降神仙。\n到乘鸾驾鹤御楼前。\n来献长寿仙丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20480, '清平乐', '无名氏', '真主玉历成康。\n德睿宁安国中良。\n时和岁丰稔，民阜乐、何情，瑞木呈日五色，月华重有光。\n更羽鹤来仪凤凰。\n万邦乡。\n齐供明皇。\n祝遐龄、圣寿无疆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20481, '荔子丹', '无名氏', '斗巧宫妆扫翠眉。\n相唤折花枝。\n晓来深入艳芳里，红香散，露在罗衣。\n盈盈巧笑咏新词。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20482, '水龙吟慢・水龙吟', '无名氏', '玉皇金阙长春，民仰高天欣载。\n年年一度定佳期，风情多感慨。\n绮罗竞交会。\n争折花枝两相对。\n舞袖翩翩歌声妙，掩粉面、斜窥翠黛。\n锦额门开彩架，球儿裳、先秀神仙队。\n融香拂席霓裳动，铿锵环。\n宝座巍巍五云密，欢呼争拜退。\n管弦众作欲归去，愿吾皇、万年恩爱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20483, '太平年慢・太平年', '无名氏', '皇州春满群芳丽。\n散异香旖旎。\n鳌宫开宴赏佳致。\n举笙歌鼎沸。\n永日迟迟和风媚。\n柳色烟凝翠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20484, '金殿乐慢', '无名氏', '驾紫鸾。\n乘风缥缈游仙。\n红霓蘸影，近瑶池、鹤戏芝田。\n临蕙圃、饮琼泉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20485, '安平乐・安平乐慢', '无名氏', '开琼筵，庆佳辰。\n彩当中月华明。\n笙歌乐、如梦幻，望丹山彩凤，飞舞邃庭。\n遐艳异、寿杯同斟。\n舞讴歌浃欢声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20486, '爱月夜眠迟慢', '无名氏', '禁鼓初敲，觉六街夜悄，车马人稀。\n暮天澄淡，云收雾卷，亭亭皎月如。\n冰轮碾出遥空，无私照临千里。\n最堪怜、有情风，送得丹桂香微。\n唯愿素魄长圆，把流霞对饮，满泛觥卮。\n醉凭栏处、赏玩不忍，辜却好景良时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20487, '惜花春起早慢', '无名氏', '向春来，睹林园，绣出满槛鲜萼。\n流莺海棠枝上弄舌，紫燕飞绕池阁。\n三眠细柳，垂万条、罗带柔弱。\n为思量，昨夜去看花，犹自斑驳。\n须拌尽日樽前，当媚景良辰，且恁欢谑。\n更阑夜深秉烛，对花酌、莫辜轻喏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20488, '千秋岁令・千秋岁引', '无名氏', '想风流态，种种般般媚。\n恨别离时大容易。\n香笺欲写相思意。\n相思泪滴香笺字。\n画堂深，银烛暗，重门闭。\n似当日、欢娱何日遂。\n愿早早相逢重设誓。\n美景良辰莫轻拌，鸳鸯帐里鸳鸯被。\n鸳鸯枕上鸳鸯睡。\n似恁地，长恁地，千秋岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20489, '风中柳令・谢池春', '无名氏', '爱鬓云长，惜眉山，寻乍相见，一时眠起。\n为伊尚验，未欲将言相戏。\n早樽前、会人深意。\n霎时间阻，眼儿早巴巴地。\n便也解、封题相寄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20490, '汉宫春慢・汉宫春', '无名氏', '春日迟迟。\n称游人、尽日赏燕芳菲。\n新荷泛水，渐入夏景云奇。\n炎光易息，又早是、零落风西。\n白露点，黄金菊蕊，朝云暮雪霏霏。\n光阴迅速如飞。\n邀酒朋共欢，且恁开眉。\n清歌妙舞，更兼玉管瑶篪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20491, '花心动慢・花心动', '无名氏', '暑逼芳襟，甚全无因依，便教人恶。\n赖有枕溪百尺，朱楼映日，数重香箔。\n驮冰围定犹嫌暖，红日绽、雨收残脚。\n漫试取，红绡弄雪，碎琼推削。\n妆罢低云未。\n叶叶地仙衣，剪轻裁薄。\n汗洒泪珠，急捧金盘，向前颗颗盛却。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20492, '行香子慢', '无名氏', '瑞景光融。\n换中天霁烟、佳气葱葱。\n皇居崇壮丽，金碧辉空。\n彤霄外、瑶殿深处，帘卷花影重重。\n迎步辇、几簇真仙，贺庆寿新宫。\n方逢。\n圣主飞龙。\n正休盛大宁，朝野欢同。\n何妨宴赏，奉宸意慈容。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20493, '雨中花慢', '无名氏', '宴阙倚栏郊外，乍别芳姿，醉登长陌。\n渐觉联绵离绪，淡薄秋色。\n宝马频嘶，寒蝉晚、正伤行客。\n念少年踪迹。\n风流声价，泪珠偷滴。\n从前与、酒朋花侣，镇赏画楼瑶席。\n今夜里、清风明月，水村山驿。\n往事悠悠似梦，新愁苒苒如织。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20494, '迎春乐令・迎春乐', '无名氏', '神州丽景春先到。\n看看是、韶光早。\n园林深处东风过，红杏里、莺声好。\n漠漠青烟远远道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20495, '西江月慢', '无名氏', '烟笼细柳，映粉墙、垂丝轻袅。\n正岁稍暖律风和，装点後苑台沼。\n见乍开、桃若燕脂染，便须信、江南春早。\n又数枝、零乱残花，飘满地、未曾扫。\n幸到此、芳菲时渐好。\n恨间阻、佳期尚杳。\n听几声、云里悲鸿，动感怨愁多少。\n谩送目、层阁天涯远，甚无人、音书来到。\n又只恐、别有深情，盟言忘了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20496, '游月宫令', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20497, '桂枝香慢・桂枝香', '无名氏', '暖风迟日，正韶阳时节，淑景明媚。\n一霎雨打红桃，花落满地。\n□闺独坐帘高卷，困春容、懒临香砌。\n自从檀郎，金门献赋，不绝朱翠。\n闻上国、才有书回，应贤良明庭，已擢高第。\n拆破香笺，离恨却成新喜。\n早教宴罢琼林苑，愿归来、永同连理。\n这回良夜，从他桂枝，香惹鸳被。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20498, '庆金枝令・庆金枝', '无名氏', '莫惜金缕衣。\n劝君惜、少年时。\n花开堪折直须折，莫待折空枝。\n一朝杜宇才鸣後，便从此、歇芳菲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20499, '百宝妆・新雁过妆楼', '无名氏', '一抹弦器，初宴画堂，琵琶人把当头。\n髻云腰素，仍占绝风流。\n轻拢慢拈，生情艳态，翠眉黛颦，无愁谩似愁。\n变新声曲，自成获索，共听一奏梁州。\n弹到遍急敲颖，分明似语，争知指面纤柔。\n坐中无语，惟断续金虬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20500, '满朝欢令', '无名氏', '未央宫阙丹霞住。\n十二玉楼挥锦绣。\n云开雉扇卷珠帘，烟粉龙香添瑞兽。\n瑶觞一举箫韶奏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20501, '天下乐令・减字木兰花', '无名氏', '寿星明久。\n寿曲高歌沉醉後。\n寿烛荧煌。\n手把金炉，燃一寿香。\n满斟寿酒。\n我意殷勤来祝寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20502, '感恩多令・山花子', '无名氏', '罗帐半垂门半开。\n残灯孤月照窗台。\n北斗渐移天欲曙、漏更催。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20503, '解佩令', '无名氏', '脸儿端正。\n心儿峭俊。\n眉儿长、眼儿入鬓。\n鼻儿隆隆，口儿小、舌儿香软。\n耳垛儿、就中红润。\n项如琼玉，发如云鬓。\n眉如削、手如春笋。\n奶儿甘甜，腰儿细、脚儿去紧。\n那些儿、更休要问。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20504, '沁园春', '无名氏', '道过江南，泥墙粉壁，石具在前。\n述某州某县，某乡某里，住何人地，佃何人田。\n气象萧条，生灵憔悴，经略从来未必然。\n惟何甚，为官为已，不把人怜。\n思量几许山川。\n况土地分张又百年。\n正西蜀岩，云迷鸟道，两淮清野，日警狼烟。\n宰相弄权，奸人罔上，谁念干戈未息肩。\n掌大地，何须经理，万取千焉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20505, '糖多令・唐多令', '无名氏', '天上谪星班。\n青牛初度关。\n幻出蓬莱新院宇，花外竹，竹边山。\n轩冕傥来闲。\n人生闲最难。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20506, '长相思', '无名氏', '去年秋。\n今年秋。\n湖上人家乐复忧。\n西湖依旧流。\n吴循州。\n贾循州。\n十五年前一转头。\n人生放下休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20507, '祝英台近', '无名氏', '掩琵琶，临别语，把酒泪如洗。\n似恁春时，仓卒去何意。\n牡丹恰则开园，荼シ厮句，便下得、一帆千里。\n好无谓。\n复道明日行呵，如何恋得你。\n一叶船儿，休要更沉醉。\n後梅子青时，杨花飞絮，侧耳听，喜鹊□哩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20508, '汉宫春', '无名氏', '横吹声沉，倚危楼红日，江转天斜。\n黄尘边火洞，何处吾家。\n胎禽怨夜，半乘风、玄露丹霞。\n先生笑，飞空一剑，东风犹自天涯。\n情知道山中好，早翠嚣含隐，瑶草新芽。\n青溪故人信断，梦逐飙车。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20509, '水调歌头', '无名氏', '握虎符，持玉节，佩金鱼。\n三十正当方面，此事世间无。\n寄语东淮父老，夺我诗书元帅，於汝抑安乎。\n早早归廊庙，天下尽欢娱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20510, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20511, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20512, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20513, '忆秦娥', '无名氏', '烟漠漠。\n水天摇荡蓬莱阁。\n蓬莱阁，朱甍碧瓦，半浸寥廓。\n三山谩有长生药。\n茫茫云海风涛恶。\n风涛恶。\n仙槎不见，暮沙潮落。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20514, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20515, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20516, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20517, '减字木兰花', '无名氏', '舞台歌院。\n雨後西风寒翦翦。\n翠掩屏风。\n花与残霞一样红。\n宫隐绣。\n香软巧随莲步绉。\n不怕露寒。\n日日拼教醉画栏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20518, '虞美人', '无名氏', '秋深犹带秋初热。\n未放秋香发。\n爱他楼下木芙蓉。\n妆罢三千美女、出唐宫。\n西湖虽小风光胜。\n分得钱塘景。\n这些林木这些山。\n恰似三贤堂後、凭阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20519, '念奴娇', '无名氏', '晓来雨过，见三点两点，催花开却。\n满目园林如锦绣，低亚阑干西角。\n魏紫风流，姚黄妖艳，桃李皆粗俗。\n金刀翦下，燕鸳窥妒惊愕。\n雅称似玉人人，淡妆才罢，粉衬胭脂薄。\n蝉翼轻笼云鬓巧，斜插一枝红萼。\n睡足杨妃，醉沉西子，娇困铅华落。\n多情风蝶，晚来犹更随著。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20520, '望江南・忆江南', '无名氏', '左右字，从古不曾闻。\n未必书生能点墨，安知荫子不能文。\n尔汝今朝。\n除去了，多谢圣明恩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20521, '朝中措', '无名氏', '与君同是饱齑盐。\n先达後何淹。\n任玉东西醉倒，明朝病酒厌厌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20522, '忆秦娥', '无名氏', '花蹊侧。\n秦楼夜访金钗客。\n金钗客。\n江梅风韵，野棠颜色。\n尊前醉倒君休惜。\n不成去後空相忆。\n空相忆。\n山长水远，几时来得。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20523, '失调名', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20524, '倚西楼', '无名氏', '禁鼓初传时下打。\n虚过清风明月夜。\n眼如鱼目几曾乾，心似酒旗终日挂。\n银汉低垂星斗斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20525, '捣练子', '无名氏', '云鬓乱，晚妆残。\n带恨眉儿远岫攒。\n斜托香腮春笋懒，为谁和泪倚阑干。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20526, '长相思', '无名氏', '花满枝。\n柳满枝。\n眼底春光似旧时。\n燕归人未归。\n泪沾衣。\n酒沾衣。\n烦恼长多欢事稀。\n此情风月知。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20527, '乌夜啼', '无名氏', '都无一点残红。\n夜来风。\n底事东君归去、太匆匆。\n桃花醉。\n梨花泪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20528, '乌夜啼', '无名氏', '一弯月挂危楼。\n似藏钩。\n醉里不知黄叶、报新秋。\n征鸿断。\n归云乱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20529, '捣练子', '无名氏', '林下路，水边亭。\n凉吹水面散馀酲。\n小藤床、随意横。\n暗记得、旧时经。\n翠荷闹雨做秋声。\n恁时节、不怕听。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20530, '生查子', '无名氏', '闲倚曲屏风，试写相思字。\n不道极多情，却是浑无思。\n笑近短墙阴，抛个青梅子。\n苔上印钩弯，邂逅难忘此。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20531, '贺圣朝影・添声杨柳枝', '无名氏', '雪满长安酒价高。\n度寒宵。\n身轻不要袍。\n醉红娇。\n花月暗成离别恨，梦无。\n起来春信惹梅梢。\n又魂消。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20532, '莫思归・抛球乐', '无名氏', '花满名园酒满觞。\n且开笑口对芳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20533, '点绛唇', '无名氏', '蹴罢秋千，起来慵整纤纤手。\n露浓花瘦。\n薄汗轻衣透。\n见客入来，袜金钗溜。\n和羞走。\n倚门回首。\n却把青梅嗅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20534, '减字木兰花', '无名氏', '春融酒困。\n一寸横波千里恨。\n著处芳菲。\n蝶与莺情醉自迷。\n云妥翠。\n冷落金屏山十二。\n低抱琵琶。\n月向黄昏日又斜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20535, '菩萨蛮', '无名氏', '昔年曾伴花前醉。\n今年空洒花前泪。\n花有再荣时。\n人无重见期。\n故人情义重。\n不忍营新宠。\n日月有盈亏。\n妾心无改移。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20536, '谒金门', '无名氏', '山无数。\n遮断故人何处。\n见说阑舟独系住。\n溪边红叶树。\n忆著前时欢遇。\n惹起今番愁绪。\n怎得西风吹泪去。\n阳台为暮雨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20537, '更漏子', '无名氏', '解语花，断肠草。\n谙尽风流烦恼。\n欢会少，别离多。\n此情无奈何。\n帐前灯，窗间月。\n记得那□时节。\n绣被剩，画屏空。\n如今在梦中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20538, '镜中人・相思引', '无名氏', '柳烟浓，梅雨润。\n芳草绵绵离恨。\n花坞风来几阵。\n罗袖沾春粉。\n独上小楼迷远近。\n不见浣溪人信。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20539, '眼儿媚', '无名氏', '惨云愁雾罩江天。\n呵手卷帘看。\n蒙茸柳絮，万千蝴蝶，飞过危栏。\n後庭一树瑶华缀，零乱暗香残。\n今番桂影，也应寒重，不放新弯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20540, '眼儿媚', '无名氏', '忆从溪上得相逢。\n樽酒两心同。\n梅缄香雪，竹摇寒月，柳探春风。\n而今总是消魂处，冷落半床空。\n梦迷狂蝶，喜占乾鹊，愁望飞鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20541, '眼儿媚', '无名氏', '平生几度怨长亭。\n不似这番深。\n霜收水瘦，风流帆饱，怎忍轻分。\n栏干倚遍慵归去，独自个黄昏。\n荷横钗股，柳垂裙带，总是销魂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20542, '乌夜啼', '无名氏', '水漫汀洲新绿，云开崦嶂微青。\n残红不见成阴後，寂无声。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20543, '与团圆・喜团圆', '无名氏', '绞绡雾，没多重数，紧拟偷怜。\n孜孜觑着，算前生、只结得眼因缘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20544, '花前饮', '无名氏', '雨馀天色渐寒渗。\n海棠绽、胭脂如锦。\n告你休看书，共我花前饮。\n皓月穿帘未成寝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20545, '转调贺圣朝・贺圣朝', '无名氏', '渐觉一日，浓如一日，不比寻常。\n若知人、未伊瘦损，成病又何妨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20546, '西江月', '无名氏', '昨夜轺车宿处，乱山深锁邮亭。\n烟溪霜叶颤秋声。\n不管愁人不听。\n枕冷安排难稳，衾寒重叠犹轻。\n凭谁说与那人人。\n报道衾寒枕冷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20547, '望江南・忆江南', '无名氏', '这痴呆，休恁泪涟涟。\n他是霸陵桥畔柳，千人攀了到君攀。\n刚甚别离难。\n荷上露，莫把作珠穿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20548, '鹧鸪天', '无名氏', '紫陌朱轮去似流。\n丁香初结小银钩。\n凭阑试问秦楼路，瞥见纤纤十指柔。\n金约腕，玉搔头。\n尽教人看却佯羞。\n欲题红叶无流水，别是桃源一段愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20549, '鹧鸪天', '无名氏', '镇日无心扫黛眉。\n临行愁见理征衣。\n樽前只恐伤郎意，阁泪汪汪不敢垂。\n停宝马，捧瑶卮。\n相斟相劝忍分离。\n不如饮待奴先醉，图得不知郎去时。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20550, '遍地花', '无名氏', '元是竹林旧伴侣。\n去人日、偶相遇。\n笑卢同、狂怪尝茶，问子建、诗成几步。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20551, '红窗迥', '无名氏', '富春坊，好景致。\n两岸尽是、歌姬舞妓。\n引调得、上界神仙，把凡心都起。\n内有丙丁并壬癸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20552, '小重山', '无名氏', '络纬声残织翠丝。\n金风剪不断、雁来时。\n梦回缄泪寄征衣。\n寒到早，应怪寄衣迟。\n心事有谁知。\n黄昏常立尽、暗萤飞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20553, '撷芳词', '无名氏', '风摇荡，雨茸。\n翠条柔弱花头重。\n春衫窄。\n香肌湿。\n记得年时，共伊曾摘。\n都如梦。\n何曾共。\n可怜孤似钗头凤。\n关山隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20554, '拨棹子', '无名氏', '烟姿媚，冰容薄。\n芳蕖嫩、隐映新萍池阁。\n撷英人去後，清香微绽，透真珠帘幕。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20555, '香山会', '无名氏', '向神前发愿，烧香做咒。\n断了去、娼家吃酒。\n果子钱早是遭他毒手。\n更一个、瓶儿渗漏。\n才斟两盏三盏，早斟不勾。\n又添和、薄漓半斗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20556, '品令', '无名氏', '急雨惊秋晓。\n今岁较、秋风早。\n一觞一咏，更须莫负、晚风残照。\n可惜莲花已谢，莲房尚小。\n汀苹岸草。\n怎称得、人情好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20557, '御街行', '无名氏', '霜风渐紧寒侵被。\n听孤雁、声嘹唳。\n一声声送一声悲，云淡碧天如水。\n披衣起。\n告雁儿略住，听我些儿事。\n塔儿南畔城儿里。\n第三个、桥儿外。\n濒河西岸小红楼，门外梧桐雕砌。\n请教且与，低声飞过，那里有、人人无寐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20558, '惜寒梅', '无名氏', '看尽千花，爱寒梅暗与、雪期霜约。\n雅态香肌，迥有天然淡泊。\n五侯园囿姿游乐。\n凭阑处、重开绣幕。\n秦娥妆罢，遥相纵，艳过京洛。\n天涯再见素萼。\n似凝然向人，玉容寂寞。\n江上飘零，怎把芳心付托。\n那堪风雨夜来恶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20559, '古阳关・阳关引', '无名氏', '渭城朝雨，一霎轻尘。\n更洒遍、客舍青青。\n弄柔凝、千缕柳色新。\n更洒遍，客舍青青，千缕柳色新。\n休烦恼。\n劝君更尽一杯酒，人生会少。\n自古富贵功名有定分。\n莫遣容仪瘦损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20560, '永遇乐', '无名氏', '孤衾不暖，静闻银漏，枕难稳。\n细想多情，多才多貌，总是多愁本。\n而今幽会难成，佳期顿阻，只恁萦方寸。\n知他莫是，今生共伊，此欢无分。\n寻思断肠肠断，珠泪了，依前重。\n终待临岐，分明说与，我这厌厌闷。\n得伊知後，教人成病。\n万种断也无限。\n只恐他、恁不分晓，谩劳瘦损。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20561, '一萼红', '无名氏', '断云漏日，青阳布，渐入融和天气。\n糁缀夭桃，金绽垂杨，妆点亭台佳致。\n晓露染、风裁雨晕，是牡丹、偏称化工美。\n向此际会，未教一萼，红开鲜蕊。\n迤逦。\n渐成春意。\n放秀色妖艳，天真难比。\n粉惹蝶翅，香上蜂须，忍把芳心萦碎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20562, '霜叶飞', '无名氏', '故宫秋晚馀芳尽，轻阴闲淡池阁。\n凤泥银暗玳纹花，卷断肠帘幕。\n渐砌菊、遗金谢却，芙蓉才共清霜约。\n半弄蕊、冰绡波浅，拂胭脂、翠琼连并雕萼。\n应是曾倚东君，纵艳姿轻盈，映损丹杏红药。\n旋成深妒，判与西风，任从开落。\n况衰晚、渊明意薄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20563, '檐前铁', '无名氏', '悄无人，宿雨厌厌，空庭乍歇。\n听檐前、铁马戛叮当，敲破梦魂残结。\n丁年事，天涯恨，又早在心头咽。\n谁怜我、绮帘前，镇日鞋儿双跌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20564, '娇木笪・木笪', '无名氏', '酒入愁肠，谁信道、都做泪珠儿滴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20565, '小品', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20566, '小品', '无名氏', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20567, '鹧鸪天', '无名氏', '全似丹青染成。\n更将何物斗轻盈。\n雪因舞态羞频下，云为歌声不忍行。\n螺髻小，凤鞋轻。\n天边斗柄又斜横。\n水晶庭柱琉璃帐，客去同谁看月明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20568, '甘露滴乔松', '无名氏', '沙堤露近，喜五年相遇，朱颜依旧。\n尽道名世半千，公望三九。\n是今日、富民侯。\n早生聚、考堂户口。\n谁欤兼致，文章燕许，歌辞苏柳。\n更饶万卷图书，把藤笈芸编，遍题青镂。\n一经传得，旧事韦平先後。\n试衮衮、数英游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20569, '满江红', '无名氏', '雪共梅花，念动是、经年离拆。\n重会面、玉肌真态，一般标格。\n谁道无情应也妒，暗香埋没教谁识。\n却随风、偷入傍妆台，萦帘额。\n惊醉眼，朱成碧。\n随冷暖，分青白。\n叹朱弦冻折，高山音息。\n怅望关河无驿使，剡溪兴尽成陈迹。\n见似枝而喜对杨花，须相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20570, '念奴娇', '无名氏', '天工谬巧，恁平地、推出岩壁。\n虎跃龙骧飞凤翥，疑道补天馀石。\n洞壑穿云，来今往古，知是谁开辟。\n千年兰若，林峦隐映金碧。\n我兴邱壑尤长，来此境，惯蹑登山屐。\n适意人生随处好，何必岘南阳峄。\n谢傅东山，裴公绿野，俯仰俱陈迹。\n何如轻举，廓寥云外横笛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20571, '秦楼月・忆秦娥', '梁意娘', '春宵短。\n香闺寂寞愁无限。\n愁无限。\n一声窗外，晓莺新啭。\n起来无语成娇懒。\n柔肠易断人难见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20572, '茶瓶儿', '梁意娘', '满地落花铺绣。\n春色著人如酒。\n晓莺窗外啼杨柳。\n愁不奈、两眉频皱。\n关山杳。\n音尘悄。\n那堪是、昔年时候。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20573, '西江月', '越娘', '一自东君去後，几多恩爱暌离。\n频凝泪眼望乡畿。\n客路迢迢千里。\n顾我风情不薄，与君驿邸相随。\n参军虽死不须悲。\n幸有连枝同气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20574, '西江月', '张师师', '一种何其轻薄，三眠情意偏多。\n飞花舞絮弄春和。\n全没些儿定个。\n踪迹岂容收拾，风流无处消磨。\n依依接取手亲。\n永结同心向我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20575, '西江月', '钱安安', '谁道词高和寡，须知会少离多。\n三家本作一家和。\n更莫容他别个。\n且恁眼前同乐，休将饮里相磨。\n酒肠不奈苦揉。\n我醉无多酌我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20576, '南乡子', '张商英', '向晚出京关。\n细雨微风拂面寒。\n杨柳堤边青草岸，堪观。\n只在人心咫尺间。\n酒饮盏须乾。\n莫道浮生似等闲。\n用则逆理天下事，何难。\n不用云中别有山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20577, '南乡子', '张商英', '瓦钵与磁瓯。\n闲伴白云醉後休。\n得失事常贫也乐，无忧。\n运去英雄不自由。\n彭越与韩侯。\n盖世功名一土丘。\n名利有饵鱼吞饵，轮收。\n得脱那能更上钩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20578, '人娇', '徐都尉', '小苑藏春，信道游人未见。\n花脸嫩、柳腰娇软。\n停觞缓引，正夕阳将晚。\n莺误入，蹴损海棠花片。\n只怅春心，当时露见，小楼外、曾劳目断。\n灯前料想。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20579, '最高楼', '崔木', '蹇驴缓跨，迢递至京城。\n当此际，正芳春。\n芹泥融暖飞雏燕，柳条摇曳韵鹂庚。\n更那堪，迟日暖，晓风轻。\n算费尽、主人歌与酒，更费尽、青楼与筝。\n多少事，绊牵情。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20580, '虞美人', '崔木', '春来秋往何时了。\n心事知多少。\n深深庭院悄无人。\n独自行来独坐、若为情。\n双旌声势虽云贵。\n终是谁存济。\n今宵已幸得人言。\n拟待劳烦神女、下巫山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20581, '虞美人', '黄舜英', '一从骨肉相抛了。\n受了多多少。\n溪山风月属何人。\n到此思量、因甚不关情。\n而今虽道王孙贵。\n有事凭谁济。\n自从今夜得媒言。\n相见佳期无谓、隔关山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20582, '南乡子', '贾奕', '闲步小楼前。\n见个佳人貌类仙。\n暗想圣情浑似梦，追欢。\n执手兰房恣意怜。\n一夜说盟言。\n满掬沉檀喷瑞烟。\n报道早朝归去晚，回銮。\n留下鲛绡当宿钱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20583, '鹧鸪天', '窃杯女子', '灯火楼台处处新。\n笑携郎手御街行。\n回头忽听传呼急，不觉鸳鸯两处分。\n天表近，帝恩荣。\n琼浆饮罢脸生春。\n归来恐被儿夫怪，愿赐金杯作证明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20584, '念奴娇', '窃杯女子', '桂魄澄辉，禁城内、万盏花灯罗列。\n无限佳人穿绣径，几多妖艳奇绝。\n凤烛交光，银灯相射，奏箫韶初歇。\n鸣鞘响处，万民瞻仰宫阙。\n妾自闺门给假，与夫携手，共赏元宵节。\n误到玉皇金殿砌，赐酒金杯满设。\n量窄从来，红凝粉面，尊见无凭说。\n假王金盏，免公婆责罚臣妾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20585, '鹧鸪天', '刘', '竹引牵牛花满街。\n疏篱茅舍月光筛。\n琉璃盏内茅柴酒，白玉盘中簇豆梅。\n休懊恼，且开怀。\n平生赢得笑颜开。\n三千里地无知己，十万军中挂印来。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20586, '菩萨蛮', '陈义', '平生只被今朝误。\n今朝却把平生补。\n重午一年期。\n斋僧只待时。\n主人恩义重。\n两载蒙恩宠。\n清净得为僧。\n幽闲度此生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20587, '菩萨蛮', '陈义', '包中香黍分边角。\n彩丝剪就交绒索。\n樽俎泛菖蒲。\n年年五月初。\n主人恩义重。\n对景承欢宠。\n何日玩山家。\n葵蒿三四花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20588, '苏幕遮', '净端', '遇荒年，每常见。\n就中今年，洪水皆淹遍。\n父母分离无可恋。\n幸望豪民，救取庄家汉。\n最堪伤，何忍见。\n古寺禅林，翻作悲田院。\n日夜烧香频□□，祷告皇天，救护开方便。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20589, '浪淘沙', '善珍', '相对两衰翁。\n身似枯蓬。\n分飞吹聚谢天风。\n零落交游无一个，五十年中。\n生客语藏锋。\n不答阳聋。\n心期难话与儿童。\n共结庵招猿鹤侣，烟锁云封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20590, '浪淘沙', '善珍', '七十二年翁。\n曾客吴中。\n清游占断水晶宫。\n几度藕花归棹晚，月渚烟钟。\n追记已陈踪。\n回首空。\n恁高荒草夕阳同。\n欲问谢公歌舞地，落叶鸣蛩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20591, '望梅词・望梅', '善珍', '寸阴堪惜。\n趁身强健去，结茅苍壁。\n错料事、临老方知，国师与高僧，二途俱失。\n识字吟诗，数不得、死生何益。\n看寒山着语，李杜也输，莫道元白。\n千年过如瞬息。\n共飞鸿缥缈，沉没空碧。\n问懒瓒、因甚遭逢，芋魁亦联翩，著名金石。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20592, '渔歌・渔父', '李彭', '南院嫡孙唯此个。\n西河狮子当门坐。\n绢扇清凉随手簸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20593, '渔歌・渔父', '李彭', '掌握千差都照破。\n石霜这汉难关锁。\n水出高源酬佛陀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20594, '渔歌・渔父', '李彭', '孤硬云峰无计较。\n大愚滩上曾垂钓。\n佛法何曾愁烂了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20595, '渔歌・渔父', '李彭', '万古黄龙真夭矫。\n斩新勘破台山媪。\n佛手驴蹄人不晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20596, '渔歌・渔父', '李彭', '宝觉禅河波浩浩。\n五湖衲子来求宝。\n忽坚拳头宜速道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20597, '渔歌・渔父', '李彭', '贬剥诸方真净老。\n顶门眼正形枯槁。\n一点深藏人莫造。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20598, '渔歌・渔父', '李彭', '积翠十年丹风穴。\n当时亲得黄龙钵。\n掣电之机难把撮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20599, '渔歌・渔父', '李彭', '骂佛骂人新孟八。\n是非窟里和身拶。\n不惜眉毛言便发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20600, '渔歌・渔父', '李彭', '绝唱灵源求和寡。\n先牛寻得西家马。\n顾陆笔端难拟画。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20601, '渔歌・渔父', '李彭', '选佛堂中川苴。\n衲僧卑孔头垂下。\n独秀握来无一把。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20602, '渔家傲', '无际道人', '七坐道场三奉诏。\n空花水月何时了。\n小玉声中曾悟道。\n真堪笑。\n从来漫得儿孙好。\n辩涌海潮声浩浩。\n明如皓月当空照。\n飞锡西归云杳渺。\n巴猿啸。\n大家唱起还乡调。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20603, '解佩令', '张伯端', '修行之士，功勤不小。\n识五行、逆顺颠倒。\n妙理玄玄，玉炉中、龙蟠虎踞，金鼎内、炼成至宝。\n阳神雕体，杳杳冥冥，刹那间、游遍三岛。\n出入纯熟，按捺住、别寻玄妙。\n合真空，太虚是了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20604, '齐天乐', '朱涣', '白云封断仙岩路，重重洞深窈。\n翠竹笼烟，苍崖溅瀑，古木阴森回抱。\n坛空不老。\n锁一片莓苔，几丝莎草。\n试把桃源，较量风景是谁好。\n乘鸾人去已久，只今惟有，鹤飞猿啸。\n树拥香幢，泉敲玉佩，疑是群仙重到。\n尘氛可笑。\n久志慕丹台，梦思蓬岛。\n愿挹英游，细参梨与枣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20605, '满江红', '陈纪', '揽辔埋轮，算不负、苍髯如戟。\n人争看、横秋一鹗，轩然健翼。\n只手为天行日月，寸怀与物同苏息。\n到于今、天定瘴云开，伊谁力。\n云霄路，金门客。\n念往事，情可极。\n把行藏细说，应无惭色。\n虹气上横牛斗剑，梅花不软心肠石。\n愿此行、珍重不赀躯，无瑕璧。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20606, '念奴娇', '陈纪', '凭高眺远，见凄凉海国，高秋云物。\n岛屿沉洋萍几点，漠漠天垂四壁。\n粟粒太虚，蜉蝣天地，怀抱皆冰雪。\n清风明月，坐中看我三杰。\n为爱暮色苍寒，天光上下，舣棹须明发。\n一片玻璃秋万顷，天外去帆明灭。\n招手仙人，拍肩居士，散我骑鲸发。\n钓鳌台上，叫云吹断残月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20607, '鹧鸪天', '无名氏', '抛却功名弃却诗。\n从教身染气球泥。\n侵晨打齐云会，际暮演筹落魄归。\n园苑里，粉墙西。\n佳人偷揭绣帘窥。\n高侵云汉垂肩久，低拂花梢下脚迟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20608, '西江月', '无名氏', '健体安身可美，喜笑化食堪夸。\n更言一事实为佳。\n肥风瘦痨都罢。\n兼且时光似箭，更加景色难赊。\n名园等处乐奢华。\n一任佳人玩耍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20609, '鹧鸪天', '无名氏', '不贪名利乐优游。\n收转心猿踢气球。\n日享三餐朋友饭，夜眠一宿玉人缕。\n真快活，度春秋。\n从他乌兔走无休。\n或时戏耍名园里，或把长竿湖上游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20610, '西江月', '无名氏', '蹴场中年少，秋千架上佳人。\n三三两两趁芳辰。\n玩赏风光美景。\n日暖风和明媚，更加花草香馨。\n红颜移步出闺门，偷揭绣帘相认。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20611, '鹧鸪天', '无名氏', '虎掌葵花一锭银。\n全凭巧匠弄精神。\n里外跨知高下，逼拐挑尖月一轮。\n欺强汉，灭村人。\n其间奥妙岂堪论。\n不问贵戚并公子，曾与区区并马行。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20612, '鹧鸪天', '无名氏', '巧匠园缝异样花。\n身轻体健实堪夸。\n能令公子精神爽，善诱王孙礼义加。\n宜富贵，逞奢华。\n一团和气遍天涯。\n宋祖昔日皆曾习，占断风流第一家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20613, '西江月', '无名氏', '请知诸郡子弟，尽是湖海高朋。\n今年神首赛齐云。\n别是一般风韵。\n来时向前参圣，然後疏上挥名。\n香金留下仿花人，必定气球取胜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20614, '鹧鸪天', '无名氏', '轩辕起置号齐云。\n社祖西川妙道君。\n□□亲自裁成就，万古流传作玩珍。\n江湖客，听原因。\n今朝出狱见其真。\n来到圣前必撞案，诚将实艺向前呈。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20615, '苏幕遮', '无名氏', '水中金，冲牛斗。\n玉锁金关，护法灵童守。\n赤水丹台龙虎走。\n万象森罗，勃勃投珠口。\n饮灵源，明火候。\n太乙炉开，丹熟神光透。\n浮名浮利终不久。\n下手速修。\n穷取无中有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20616, '满庭芳', '毕大节', '玉笋京华，紫荷香润，宴闲密侍西清。\n碧幢金节，仍尹凤皇城。\n须信千龄庆遇，丹霄上、重叠恩荣。\n时多暇，湖山丽景，许酒乐升平。\n新春。\n逢诞日，莺花渐好，初过烧灯。\n想笙歌丛里，醉赏瑶觥。\n占尽人间福寿，行看取、稳赞机衡。\n貂蝉映，朱颜绿鬓，沙路马蹄轻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20617, '满庭芳', '毕大节', '井络储精，岷江锺秀，挺生名世真贤。\n充闾佳气，非雾亦非烟。\n况值小春时候，背下、八荚争妍。\n馀波在，九华父老，歌颂喧嗔。\n三年。\n书治最，南唐重赋，一旦俱蠲。\n此恩垂不朽，刻石流传。\n愿借沧溟为寿，玳筵上、满吸长川。\n从兹去，鸾坡凤阁，平步稳登仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20618, '蝶恋花', '寇准', '四十年来身富贵。\n游处烟霞，步履如平地。\n紫府丹台仙籍里，皆知独擅无双美。\n将相兼荣谁敢比。\n彩凤徊翔，重浴荀池水。\n位极人臣功济世，芬芳天下歌桃李。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20619, '渔家傲', '庞籍', '儒将不须躬甲胄。\n指挥玉麈风云走。\n战罢挥毫飞捷奏。\n倾贺酒。\n三杯遥献南山寿。\n草软沙平春日透。\n萧萧下马长川逗。\n马上醉中山色秀。\n光一一。\n旌戈矛戟山前後。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20620, '蝶恋花', '晏殊', '紫府群仙名籍秘。\n五色班龙，暂降人间世。\n海变沧田都不记。\n蟠桃一熟三千岁。\n露滴彩旌云绕秋，谁信壶中，别有笙歌地。\n门外落花随水逝。\n相看莫惜尊前醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20621, '诉衷情', '晏殊', '幕天席地斗豪奢。\n歌妓捧红牙。\n从他醉醒醒醉，斜插满头花。\n车载酒，解貂贳。\n尽繁华。\n儿孙贤俊，家道荣昌，祝寿无涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20622, '诉衷情', '晏殊', '喧天丝竹韵融融。\n歌唱画堂中。\n玲女世间希有，烛影夜摇红。\n一同笑，饮千锺。\n兴何穷。\n功成名遂，富足年康，祝寿如松。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20623, '南乡子', '沈唐', '朝觐俯尧阶。\n宠拜新恩天上回。\n欢动边城十万户，民怀。\n荣见旌旗却再来。\n清晓敞铃齐。\n庭下鸣鼍绮宴开。\n红袖两行频捧劝，金□。\n利市应销十二钗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20624, '蝶恋花', '周起', '岳佐星储生佐圣。\n真道宏才，济世功名盛。\n久践机衡宣密命。\n逢时力赞无为政。\n明主得贤朝野庆。\n昼按从容，帝宠何人并。\n早晚紫垣持国柄。\n民瞻共荷三台正。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20625, '醉蓬莱', '杨绘', '对亭台幽雅，水竹清虚，嫩凉轻透。\n碧沼红蕖，送香风盈袖。\n白首冯唐，诞辰同庆，上百分仙酎。\n鳌禁词垣，乌台谏省，昔游俱旧。\n千里长沙，五年湓浦，近捧丝纶，更藩移守。\n桂苑馀芳，有孙枝新秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20626, '长寿乐', '苏氏', '微寒应候。\n望日远六远，阶初秀。\n爱景欲挂扶桑，漏残银箭，杓回瑶斗。\n庆高闳此际，掌上一颗明珠剖。\n有令容淑德，归逢佳偶。\n到如今，昼锦满堂贵胄。\n荣耀，久步禁，一一金章绿绶。\n更值棠棣连阴，虎符熊轼，夹河分守。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20627, '万年欢', '苏氏', '日暖霜红，画戟门开，锦筵歌振梁尘。\n正是慈闱熙熙，庆诞佳辰。\n象服鱼轩灿烂，喜高年、福禄长新。\n承颜处，朱紫相将，更兼华胄诜诜。\n家声未论王谢，有禁中颇牧，江左机云。\n雁字鸳行，雍容高步金门。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20628, '减字木兰花', '王观', '寿星明久。\n寿曲高歌沉醉後。\n寿烛荣煌。\n手把金炉寿香。\n满斟寿酒。\n我意殷勤来祝寿。\n问寿如何。\n寿比南山福更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20629, '减字木兰花', '王观', '花筵布巧。\n绿绕红□花枝闹。\n朵朵风流。\n好向尊前插满头。\n此花妖艳。\n愿得年年长相见。\n满劝金锺。\n祝寿如花岁岁红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20630, '减字木兰花', '王观', '天之美禄。\n会饮思量平生福。\n一硕刘伶，五斗将来且解酲。\n百年长解。\n三万六千能几日。\n劝饮瑶觞。\n祝寿不如岁月长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20631, '减字木兰花', '王观', '红牙初展。\n象板如云遮娇面。\n曲按宫商。\n声遏行云绕画梁。\n正当衮遍。\n休唱阳关人肠断。\n劝饮流霞。\n祝寿千年转更加。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20632, '减字木兰花', '王观', '多愁早老。\n着甚由来闲烦恼。\n休管浮名。\n安乐身康似宝珍。\n酒逢知己，好向尊前朝日醉。\n满劝瑶觥。\n祝寿如山岁岁青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20633, '减字木兰花', '王观', '今晨佳宴。\n昨夜南极星光现。\n鹤舞青霁，丹凤呈祥瑞气飘。\n仙书来诏。\n绿鬓朱颜长不老。\n满劝香醪。\n祝寿如云转转高。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20634, '减字木兰花', '王观', '角声三品。\n银漏更残将欲尽。\n盏盏华筵。\n玉粒琼瓯散又圆。\n知君洪量。\n不用推辞须一上。\n满劝殷勤。\n祝寿如同福禄星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20635, '减字木兰花', '王观', '新秋气肃。\n此时仙翁曾诞育。\n禀赋应遍。\n绿□朱颜似少年。\n阶庭兰玉。\n行见儿孙俱曳绿。\n更祝遐龄。\n愿比壮椿过八千。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20636, '减字木兰花', '王观', '百年能几。\n似数巡环无了日。\n有限时光。\n玉兔金鸟晓夜忙。\n幸逢清世。\n最好排筵斟绿蚁。\n满捧金蕉。\n祝寿如松永不凋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20637, '减字木兰花', '王观', '三皇五帝。\n古代英雄闲争气。\n勇猛韩彭。\n十大功劳空有名。\n休谈人我。\n大限催煎如何。\n前酌觥舡。\n祝寿如同海月圆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20638, '减字木兰花', '王观', '春光景媚。\n花褪残红炎天气。\n蝉噪高枝。\n雁叫长空雪乱飞。\n四时如箭。\n八节忙忙频改换。\n满捧金彝。\n祝寿如同海岳齐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20639, '减字木兰花', '王观', '才鸣□鼓。\n曲奏仙音如乐府。\n美似梨园。\n一派箫韶列玳筵。\n使人清耳。\n满尘宾朋皆欢喜。\n劝饮金荷。\n祝寿延长福更多。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20640, '沁园春', '苏轼', '情若连环，恨如流水，甚时是休。\n也不须惊怪，沈郎易瘦，也不须惊怪，潘鬓先愁。\n总是难禁，许多魔难，奈好事教人不自由。\n空追想，念前欢杳杳，後会悠悠。\n凝眸。\n悔上层楼。\n谩惹起、新愁与旧愁。\n向彩笺写遍，相思字了，重重封卷，密寄书邮。\n料到伊行，时时开看，一看一回和泪收。\n须知道，□这般病染，两处心头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20641, '人娇', '无名氏', '解了痴绦，泼煞闷火。\n眉尖上、放闲愁锁。\n高来不可，低来不可，莫是人间剩我一个。\n富贵谩人，功名赚我。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20642, '定风波', '无名氏', '痛饮形骸骑蹇驴。\n葛巾不整倩人扶。\n笑指桃源泥样醉。\n三睡。\n诗魔长是泣穷途。\n画手也知仙骨瘦。\n□□山玉水点银须。\n天地不能容此老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20643, '玉女摇仙佩', '黄庭坚', '宫梅弄粉，御柳摇金，又喜皇州春早。\n盛世生贤，真仙应运，当日来从三岛。\n车马喧清晓。\n看千锺赐饮，中人传诏。\n最好是、芝兰并砌，鸣腰金，彩衣相照。\n炉烟袅。\n高堂半卷珠帘，神仙缥缈。\n须信槐庭荫美，凤沼波澄，屈指十年三到。\n九叙重歌，元圭再锡，已把成功来告。\n四海瞻仪表。\n庆君臣会集，诗符天保。\n况自有、仙风道骨，玉函金篆，阴功须报。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20644, '瑶台第一层', '黄庭坚', '阆苑归来，因醉上、瑶台第一层。\n洞天深处，年年不夜，日日长春。\n万花妆烂锦，散异香，馥郁留人。\n便乘兴，命玉龙吟笛，彩凤吹笙。\n身轻。\n先逢瑞景，众中先识董双成。\n环声丽，舞腰袅袅，浓艳腾腾。\n翠屏金缕枕，绣被软，梦冷槐清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20645, '永遇乐', '晁端礼', '雪霁千岩，春回万壑，和气如许。\n今古稽山，风流人物，真是生申处。\n儿童竹马，欢迎夹道，争为使君歌舞。\n道当年、蓬莱朵秀，又来作蓬莱主。\n一编勋业，家传几世，自是赤松仙侣。\n青琐黄堂，等闲游戏，又问乘槎路。\n银河耿耿，使星今夜，应与老人星聚。\n要知他、秋羹消息，早梅初吐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20646, '满庭芳', '仲殊', '晓日迎凉，烟华生翠，玉麟香转风轻。\n细丝钧管，罗绮拥芝庭。\n竞折蟠桃献寿，雨露罩，春下仙瀛。\n碧池上，龟游鹤舞，一曲奏长生。\n当年。\n嘉庆会，兰江秀气，星昴光灵。\n奄奕世馀徽，同降元精。\n此日中吴太守，看看秉、廊庙钧衡。\n麒麟阁，功名第一，从此入丹青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20647, '踏莎行', '仲殊', '德感元精，岳方孕秀。\n才明渊智神兼授。\n飞鸣早应舜韶来，五符千骑难淹久。\n熊梦开祥，龟文献寿。\n龙香卷雾摇东斗。\n南天为现老人暑，一时顶礼抬双神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20648, '满庭芳', '仲殊', '三月迟迟，牡丹时节，算来淑景方融。\n板舆闲暇，香雾锁花宫。\n曾侍瑶池宴席，三千女，深浅匀红。\n轻含笑，尊前认得，阿母旧慈容。\n倾心。\n齐献寿，一时倾倒，春在杯中。\n戏彩衣间作，喜气重重。\n更有天仙寄语，教皓鹤、双舞云空。\n人长命，花枝长在，岁又东风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20649, '醉蓬莱', '仲殊', '报一阳初动，二五疏，履长时候。\n大昴星精，宛分灵储秀。\n早运钧衡，亟还貂衮，向载歌成後。\n书展仪形，承华羽翼，恩深惟旧。\n天眷难留，片帆归去，水柯山，故人携手。\n枕月眠云，老华胥闲昼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20650, '减字木兰花', '仲殊', '英花万蕊。\n醒□丹房玄石髓。\n烟驾来时。\n一勺仙翁手自随。\n旋煎松火。\n始觉醍醐直可可。\n扶起精神。\n洞里天闲日月新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20651, '鹊踏枝・蝶恋花', '仲殊', '一霎雕栏疏雨罢。\n三月十三，曾是寒食夜。\n尽日暖香熏柏麝。\n西施醉起留归驾。\n酒满玻璃花艳冶。\n莫负春心，快饮千锺罢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20652, '醉花阴', '仲殊', '一双鹤绕蟠桃戏。\n说人间千岁。\n昨夜降元精，蓬矢桑弧，又报千家喜。\n绮罗庭院笙歌沸。\n拥玳簪珠履。\n五福一……。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20653, '永同欢', '仲殊', '绣帘卷，沉烟细。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20654, '柳垂金', '仲殊', '中春天气禁烟暖。\n馀七叶，丹未卷。\n海岳灵辉储庆远。\n降非熊，运符亨旦。\n宝雾香凝，非锦筵红荐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20655, '西江月', '仲殊', '耐老花间的子，长生海里明珠。\n南天星象降真符。\n五福同行同住。\n秀骨养成犀顶，被人唤作龙驹。\n传家事业有诗书。\n富贵功名看取。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20656, '西江月', '仲殊', '乙未河清九曲，神霄瑞降群仙。\n唯公殊宠最华年。\n高侍玉皇香案。\n富贵鹏程九万，康宁鹤算三千。\n功成拔宅上青天，愿厕庭中鸡犬。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20657, '念奴娇', '仲殊', '延陵福绪，蔼遗芳馀庆，直至如今。\n帝锡朋龟曾献策。\n早揖丹桂华簪。\n一代荣名，三州遗爱，留入歌吟。\n归来湖山付得，依旧闲心。\n延赏报德推封。\n名迁书监，喜天恩垂临。\n拜舞龙香还注想，丹阙拖紫垂金。\n酒满霞觞，期君眉寿，千岁与披衿。\n年年风月，两行门外桐阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20658, '步蟾宫', '仲殊', '仙郎心似长江阔。\n妾意如、波间明月。\n相随定、一带向东流，共宴乐、无时暂歇。\n长生只在长欢悦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20659, '步蟾宫', '仲殊', '笙歌喜庆争催晓。\n篆烟舞、龙鸾缥缈。\n香罗上、不尽寿仙人，献一段、长生寿草。\n一心一意同欢笑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20660, '步蟾宫', '仲殊', '凤帘舞带花铺绣。\n水沉暖、祥烟迷昼。\n凤衔灯照蕊珠筵，韵双、钧声已奏。\n绮罗人劝千秋寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20661, '醉蓬莱', '仲殊', '过灵香一炷，燕馆清虚，晚窗风细。\n雨入园林，荡凝烟摇曳。\n天上春融，暖移残腊，早信音来至。\n宫粉龙香，一时拈入，江梅轻蕊。\n人在瑶山，九仙书府，静与羲皇，淡然相对。\n锦琴无声，鼓一轩和气。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20662, '步蟾宫', '仲殊', '长庚星驭重来日，结灵秀、东阳清骨。\n过中秋，两夜月犹圆，五福降、先宫第一。\n鹤书新自金门出。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20663, '醉蓬莱', '仲殊', '骤西风凄惨，秋昊平分，晚收清昼。\n素月潜生，倚危墙时候。\n渐照芳樽，前中孤影，喜暂时为友。\n醉学吴儿，狂歌乱拍，蹁跹双袖。\n堪叹从来，误了词赋，进取才能，桂枝难勾。\n纵得虚名，与平生相负。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20664, '瑞鹧鸪', '仲殊', '融融十月小春天。\n翼翼清都降圣贤。\n大抵龙飞云必动，请观二十七年前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20665, '醉蓬莱', '仲殊', '望金华真界，宝婺星垣，瑞符玄动。\n羽葆莱游，有八鸾环拥。\n日在龙房，下弦平月，见崧岳生申。\n天上三奇，人间五福，一齐景宠。\n骞树七台，紫微金简，授延年，大椿腾颂。\n玉液称觞，引长生歌送。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20666, '沁园春', '毛滂', '左元仙伯，旧从当日，太一下生。\n念道尊德贵，体隆貌重，盖天勋业，出世才名。\n父子一时，君臣千载，侍宴通宵留太清。\n衣冠盛事，满床象简，隔坐云屏。\n年年此夜寒轻。\n正在东风下，不夜城。\n看御杯重劝，宸章屡赐，盛传歌舞，高会簪缨。\n桃李玉姬，芝兰子舍，尽向三台瞻寿星。\n从今去，愿千春献祝，午夜观灯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20667, '沁园春', '毛滂', '秀禀元精，灵锺崧岳，命世大贤。\n自飞英任路，承流百里，郎官星彩，辉映经躔。\n劲柏凌霜，香梅娇雪，月弯弯新上弦。\n垂弧节庆，麒麟古梦，此夜初圆。\n罗川。\n父老欣然。\n算善政、古来谁与肩。\n念桃阴浓密，瓜期咫尺，双凫难驻，便欲朝天。\n争把丹青，绘成芝宇，立作生祠千载传。\n仍知道，看它时画像，别有凌烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20668, '念奴娇', '赵鼎臣', '嫦娥伴侣，降人世，天与长生仙。\n五色云开浮瑞霭，中有西真眉目。\n贤德家风，艳容天赋，占尽人间福。\n长庚明月，誓同千古相逐。\n开宴香蔼华堂，金杯休诉，好醉蟠桃熟。\n子子孙孙同上寿，有个人人同祝。\n雨鬓春风，一钗香雾，长与瑶池绿。\n更祈眉寿，愿如南山松竹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20669, '小重山', '吴则礼', '鹤舞青青雪里松。\n冰门龟在藻，绿蒙茸。\n一成不见蕊珠宫。\n蟠桃熟，犹待几东风。\n玉酒紫金锺。\n非烟罗幕暖，宝□浓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20670, '东风第一枝', '吴则礼', '经国谋猷，补天气力，岳祗来佐兴运。\n王当华阙春融，共仰相门地峻。\n清台占象，见壁月、珠星明润。\n对一百五日风光，二十四番花信。\n勋共德、继增篆鼎。\n今共古、问谁比并。\n广乐初出，层霄寿，旋颁紫叶，湘桃浓杏。\n映彩服、朱颜青鬓。\n看千岁，桀阁飞楼，燕赏太平光景。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20671, '绛都春', '吴则礼', '馀寒尚峭。\n早凤沼冻开，芝田春到。\n茂对诞期，天与公春向廊庙。\n元功开物争春妙。\n传与华多少。\n召还和气，拂开霁色，未妨谈笑。\n缥缈。\n五云乱处，种雕胡自熟，蟠桃犹小。\n雨露在门，光彩充闾乌亦好。\n宝熏郁雾城西道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20672, '绛都春', '吴则礼', '韶华渐好。\n报锦里又是，春风来早。\n昴宿降萧，崧岳生申符英表。\n三朝望人倾祷。\n寿与长城俱老。\n碧油红旆，高牙大纛一时荣耀。\n矫矫。\n甘泉旧德，少年日，翰苑玉堂曾到。\n润饰帝谟，粉泽皇猷文章妙。\n主盟经济尊吾道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20673, '多丽', '吴则礼', '听新蝉，舜琴初弄清弦。\n伴薰风、匆匆佳气，锺希世英贤。\n正芳、更馀九荚，况强仕，犹待三年。\n笔下烟云，胸中岩壑，玉峰凛凛映人寒。\n公不见、清潭宝剑，九彩动星躔。\n浑疑是，风雷变化，落在人间。\n驻东阳、清谭终日，种成桃李森然。\n向庭闱、彩衣有庆，更华萼、棠棣相鲜。\n骥足难留，牛刀暂屈，匪朝伊夕步花砖。\n自今往、掀天扶地，声迹寄凌烟。\n它时事，赤松共约，携手骖鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20674, '点绛唇', '吴则礼', '柏叶春醅，为君亲酌玻璃盏。\n玉箫牙管。\n人意如春暖。\n绿鬓长留，不使韶华晚。\n春无限。\n碧桃花畔。\n笑看蓬莱浅。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20675, '点绛唇', '吴则礼', '何处君家，蟠桃花下瑶池畔。\n日迟风暖。\n占得春长远。\n几见花开，一任年光换。\n今年见。\n明年再见。\n春色如人面。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20676, '玉楼春', '吴则礼', '今朝何以为公寿。\n极贵长年公素有。\n庭阶不乏长芝兰，少翁又是庭臣右。\n三能粲粲依魁秀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20677, '玉楼春', '吴则礼', '我公两器兼文武。\n谈笑岩廊无治古。\n经颜绿发已官高，赤儿绣裳今仲父。\n我欲形容无妙识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20678, '清平乐', '吴则礼', '娟娟月满。\n冉冉梅花暖。\n春意初长寒力浅。\n渐拟芳菲满眼。\n当时吉梦重重。\n间生天子三公。\n付与人间桃李，年年管领春风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20679, '清平乐', '吴则礼', '瀛洲春酒。\n满酌公眉寿。\n月照沙堤春榜柳，恩暖朝天衮绣。\n东君着意丁宁。\n芳酸先许梅英。\n要就升平滋味，待公来後和羹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20680, '清平乐', '吴则礼', '雪馀寒退。\n惟有青松在。\n春不加荣寒不悴。\n用舍如公都耐。\n流肪磊落龟蛇。\n会留红日西斜。\n欲助我公寿骨，蟠桃等见桃花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20681, '清平乐', '吴则礼', '晨辉初转。\n拜舞金銮殿。\n想见对符睿春，天语丁宁见晚。\n雍容玉笋班聊，功名早上凌烟。\n金鼎刀圭莫惜，愿随鸡犬升仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20682, '清平乐', '吴则礼', '庆锺华胄。\n人物朝端秀。\n朝罢章华骄马骤。\n十万人家举手。\n後房桃李娟娟。\n有谁云雨恩偏。\n看取晚春时候，兰芽玉茁争妍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20683, '西江月', '吴淑虎', '门被五王德泽，家承七帝恩光。\n古今富贵迥无双。\n多少公卿将相。\n久蕴腾空气宇，行看平步岩廊。\n更祈王母寿而康。\n真个人间天上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20684, '水调歌头', '吴叔虎', '清澈黄河底，乙未政和年。\n坤珍阐瑞，运符五百间生贤。\n日暖曲江花柳，鼎沸韶春弦管，尺五是青天。\n殊宠逢熙载，吉梦送真仙。\n承盛德，公故国，庆双全。\n行看旌钺紫泥，丹诏下苕川。\n多祝多男多寿，长愿长安长乐，剑履玉宸前。\n蕙炷紫琳馆，丹笔蕊珠篇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20685, '水调歌头', '张伯寿', '天地有英气，盘结在名山。\n储精孕秀，诞生豪杰向人间。\n早拾巍科甲第，归作日边仙客，眷注不容间。\n讲道桥门暇，戏作彩衣欢。\n振斯文，回巨浸，遏狂澜。\n玉阶三尺，好扶经济侍天颜。\n把取平事业，趁取河清桃熟，十载付金銮。\n草却登封检，双鬓未曾斑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20686, '临江仙', '张伯寿', '天上娥元不老，人间紫府长春。\n朱颜鹤发更清新。\n观音常自在，水月净无尘。\n有子飘飘麟阁像，有孙庭下诜诜。\n他年看取递成名。\n进封加上国，荣拜太夫人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20687, '临江仙', '张伯寿', '吴越家声传铁券，当年功指山河。\n公侯衮衮後来多。\n休符锺俊杰，气宇禀冲和。\n磊落胸襟清庙器，鹏程背可天摩。\n他时帝里笑鸣珂。\n双椿犹鹤算，二女已鸾坡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20688, '临江仙', '张伯寿', '家住清湘云外窟，肯随玉笋同班。\n竹林风味正相联。\n独高霜外节，微露管中斑。\n吏隐丛祠聊寄傲，胸襟半是湖山。\n此君端可助跻攀。\n支颐供鹤立，拱膝看鳌翻。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20689, '临江仙', '张伯寿', '龙首凤池家鼎贵，庆传仙李芬芳。\n凛然冰雪照闺房。\n诞弥当此日，佳气满华堂。\n锦袖新封开大国，诏书急欲徵黄。\n莫辞沉醉九霞觞。\n蟠桃看子实，地久与天长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20690, '临江仙', '张伯寿', '瑞气薰城春色早，光生帘幕飞浮。\n五陵应是产风流。\n冰清兼玉润，轩冕一时游。\n已得长生元妙术，庄椿不数春秋。\n徐卿一醉百无忧。\n但知从此去，衮衮出公侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20691, '临江仙', '张伯寿', '爆竹声残天未晓，金炉细沉烟。\n儿孙戏彩映芳鲜。\n共倾元日酒，同祝大椿年。\n我愿儿孙如我寿，高低富贵随缘。\n不须厚禄与多田。\n诗书为世业，清白是家传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20692, '喜迁莺', '曹宰', '岁华将近。\n得昨夜一枝，江南佳信。\n建水城中，武夷峰上，恰属老人星分。\n间世挺生贤哲，贾马文章清俊。\n推太守，想区区百里，难淹良骏。\n舆论怀报也，暂把玉山，寄与丹青晕。\n寿旦方临，祠堂其立，底事古今谁胜。\n自有养生妙诀，赢得朱颜芳鬓。\n犹更好，佩金鱼宝带，凌烟优选。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20693, '喜迁莺', '曹宰', '皇都春早，正媚景霁色，融和时候。\n宿霭初收，祥烟新布，桃李满林惟绣。\n挺生垩朝哲辅，风采独居人右。\n世希有，看陈思名族，平阳革裔。\n眷厚知已久，近辅名藩，符竹频分剖。\n一节趋朝，神京作镇，高掩昔年贤守。\n芝检异恩才下，玉笋清班须。\n寿龄远，与湖山同永，松椿同寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20694, '喜迁莺', '曹宰', '梅含春信，冒北律严寒，南枝先暖。\n月上初弦，萱开九叶，嵩岳诞生英俊。\n冰玉丰姿莹彻，锦绣文章焕烂。\n人歌赞，是今朝卓鲁，他年伊旦。\n犹羡瓜期近，课春九重，优陟公卿选。\n列鼎鸣钟，乘轩袭冕。\n直把功名占断。\n好是宾僚会宴，争捧觥觞频劝。\n重重愿，与青青松柏，岁寒难变。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20695, '满庭芳', '王子容', '台衮筹边，京师蒙福，两淮谈笑尘清。\n正筒无讼，桴鼓亦稀鸣。\n阅武分弓角射，催春事、亲劝农耕。\n何须付，寻花问柳，小队出郊。\n功名。\n今已就，九重近天，好去辞荣。\n算人间极贵，何似长生。\n刺占梅山日月，观二妙，玉纹抨。\n休辞醉，洛阳花信，香到露华亭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20696, '满庭芳', '王子容', '瑞霭腾空，长庚入梦，挺生名世真贤。\n荐膺宸眷，移镇日华边。\n千里民谣载路，薰和气、俱作春妍。\n须知道，西湖草木，亦自肃成权。\n黄堂。\n开雅宴，酒浮云液，歌倚湘弦。\n□赐金增秩，入侍甘泉。\n且向露桃花底，拚沉醉，频举觥舡。\n祈难老，鬓随柳绿，官共早莺迁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20697, '满庭芳', '王子容', '蓬海移春，卿云约月，庆传王母骖鸾。\n九仙福地，不减玉龟山。\n况是莱儿绣斧，都衬得、彩舞斓斑。\n瑶觞举，平反一笑，功行足三十。\n木天。\n来瑞节，行封两国，宫锦蝉联。\n更孙枝满座，兰畹芝田。\n中诏肩舆上殿，称万寿，椒掖欢颜。\n黄锺数，从新九九，巧历演长年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20698, '感皇恩', '叶景山', '十月小春时，舒六翠。\n天佑皇家诞贤裔。\n熊罴协梦，疑是麒麟分瑞。\n世间无限事，都如意。\n粉阵香围，香娇玉媚。\n春酒争持泛琼蚁，笙歌缭绕，同祝我公千岁。\n他年陪绿野，拚酣醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20699, '临江仙', '叶景山', '清晓于门开寿宴，绮罗香袅芳丛。\n红娇绿软媚光风。\n绣屏金翡翠，锦帐玉芙蓉。\n珠履争驰千岁酒，葡萄满泣金锺。\n人生福寿古难逢。\n好将家庆事，写入画图中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20700, '临江仙', '叶景山', '杨柳池塘桃李径，华堂寿宴初开。\n香团翠幕舞风回。\n东山携妓女，北海罄樽。\n玉笋轻敲红象板，金荷潋潋传杯。\n笙歌缭绕宴春台。\n华阳闲日日月，绿野醉蓬莱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20701, '感皇恩', '叶景山', '春水满池塘，春风吹柳。\n春草茸茸媚晴昼。\n春烟骀荡，春色着人如旧。\n春光无限好，花时候。\n春院宴开，春屏环绣。\n春酒争持介眉寿。\n春衫春暖，春回遏云声透。\n春年常不老，松筠茂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20702, '水调歌头', '无名氏', '昭代数人物，谁似我公贤。\n平生磊磊，常以义为先。\n广立湖中义学，盛集陕西义社，良法自家传。\n阴德有如此，眉寿不须言。\n圣天子，方右武，复宗文。\n诗书马上，看君父子共争先。\n伫听天山三箭，还共秋闱一举，相继凯歌旋。\n金印大如斗，富贵出长年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20703, '水调歌头', '无名氏', '云海漾空阔，风露凛高寒。\n仙翁鹤驾羽节，缥缈下天端。\n指点虚无征路，时见双凫飞舞，挥斥隘尘寰。\n吹笛向何处，海上有三山。\n彩衣新，鱼服丽，映朱颜。\n蟠桃未熟，千岁容与旦人间。\n早晚金泥封诏，归侍紫皇香案，踵武列仙班。\n玉骨自不老，未用九还丹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20704, '醉蓬莱', '李商英', '庆朋良相遇，夷夏均欢，福沾绵宇。\n扶日勋高，更补天力巨。\n学造渊微，文赓三圣，被褒语。\n来自丹台，生逢华旦，身登仙路。\n衮绣归来，水晶宫里，燕处超然，去天尺五。\n绿发朱颜，照青春如故。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20705, '醉蓬莱', '李商英', '庆长庚协梦，仙李蟠根，挺生名世。\n粉省收声，早云霄自致。\n凤掖鸾坡，荷囊簪笔，久要津历试。\n红旆班春，碧油开府，出分忧寄。\n均逸真祠，右弧开宴，宵月光澄，玉炉烟细。\n漆发冰眸，揽浮丘仙袂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20706, '洞仙歌', '李商英', '腊残寒峭，渐近新正际。\n喜溢门阑霭佳气。\n遇昌辰，符吉梦，岳渎呈祥瑞。\n知是天诞人间奇瑞。\n文章推晁董，学擅卿云，高揭声猷缙绅里。\n上瀛洲册府，师表宗藩，华要地，俱是宸衷注意。\n又何止看看便持荷，更寿为崆峒，广成同岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20707, '洞仙歌', '李商英', '霓旌降节，缥缈蓬瀛里。\n前是骖鸾在人世。\n云衢沾圣泽，两地疏封，须信道，不减瑶台富贵。\n兰帏称寿日，朱紫盈门，碧藕蟠桃奉甘旨。\n更何须，求大药饵服还丹，长不老，鹤骨仙标无比。\n况壶天日月自延长，看几度人间，百年千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20708, '胜胜慢・声声慢', '李商英', '笙簧缭绕，书鼓声喧，佳人对舞绣帘前。\n高卷铺衬，广列华筵。\n人人献香祝寿，捧流霞，永庆高年。\n名香，睹重重华盖，金兽喷烟。\n一愿皇恩频降，松柏对龟鹤，彭祖齐肩。\n二愿子子孙孙，尽贡三元。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20709, '木兰花慢', '李商英', '喜琼筵乍启，似王母、宴瑶池。\n正珠履骈肩，群仙间坐，冰玉交辉。\n新词更兼旧曲，听歌声、宛转绕屏帏。\n一缕龙香水麝，满堂如彩云飞。\n金卮主献宾酬。\n无算数醉如泥。\n诮不管山翁，霜髯皓鬓，为插花枝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20710, '胜胜慢・声声慢', '李商英', '香浮椒柏，暖入酴酥，非烟晓生帘幕。\n绛阙真仙，来自五云楼阁。\n青霁路岐游遍，排冠归、水晶城郭。\n萧散处，有壶中日月，故园猿鹤。\n好是朱颜难老，嬉游处，不减少年行乐。\n正好寻春，莫负燕期莺约。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20711, '水调歌头', '马伯升', '瑞应杉溪县，光动极星宫。\n人间盛事此日，岳降自高嵩。\n庆兆三阳开泰，散作一团和气，无地不春风。\n眉寿八千岁，今代黑头公。\n听剑履，上星辰，此行中。\n况金瓯姓字，当路那已达宸聪。\n管取凤池新命，来自虎关上阙，明日到花封。\n王室要师保，叔父勿居东。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20712, '满江红', '马伯升', '人品如君，人尽道，士林横绝。\n那更是、关西流庆，三山英杰。\n欣遇当年神降日，又逢初度阳生月。\n把八千馀岁祝君龄，为君说。\n君自有，封侯骨。\n君不是，栖鸾客。\n况如今东阁，正收人物。\n坦腹素知王逸少，求贤不必商岩说。\n便明朝、有诏自天来，君王礼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20713, '水调歌头', '马伯升', '和气应鼙鼓，喜色上辕门。\n貔貅万骑，争相庆主将佳晨。\n遥望九霄上阙，霭霭庆云澄处，一点将星明。\n天瑞不虚应，人杰岂虚生。\n况君家，名将旧，有元勋。\n上方拊髀，要资颇牧作长城。\n管取斋坛入拜，会见凯歌归奏，振起旧家声。\n与国同休语，王府又重盟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20714, '西江月', '陈克', '捣玉扬珠万户，眉高髻千峰。\n佳辰清寿黑头公，老稚扶携欢动。\n借问优游黄倚，何如强健夔龙。\n舡一棹百分空，浇泼胸中云梦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20715, '鹧鸪天', '陈克', '风露绢绢玉井莲，霓旌绛节会中元。\n鬓头未学功名晚，金紫由来称长年。\n青作穗，酒如泉。\n蓬莱方丈自飞仙。\n黄麻敕胜长生，早送夔龙到日边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20716, '南歌子', '陈克', '凤飞醇酎，龙筵喷异香。\n又还仁还祝延长。\n正对金风玉露、爽秋光。\n一种庄椿老，五仙桂芳。\n当年天产窦家郎。\n须信来春同此、赋高唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20717, '南歌子', '陈克', '爱日烘晴昼，轻寒护晓霜。\n小春庭院绕天香。\n仙风珊珊来自、五云乡。\n庭下芝兰秀，壶中日月长。\n要看发绿与瞳方。\n一笑人间千岁、饮淋浪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20718, '新荷叶', '李清照', '薄露初零，长宵共、永昼分停。\n绕水楼台，高耸万丈蓬瀛。\n芝兰为寿，相辉映、簪笏盈庭。\n花柔玉净，捧觞别有娉婷。\n鹤瘦松青，精神与、秋月争明。\n德行文章，素驰日下声名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20719, '寿星明・沁园春', '莫蒙', '翠樾阴浓，见嵩山洛水，紫薇光聚。\n雏华飞，黄驹骏天下，夜擎香露奋身许玉斧，来作明堂一柱。\n试看人间，谁能具此，神峰眉宇。\n烟缕摇曳暗雾。\n想高正簇清歌妍舞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20720, '瑞庭花引', '莫蒙', '对画帘卷，正钩挂虾须细锦幄。\n展凤屏。\n开朱户。\n初启宝兽，香飘龙麝，袅袅烟成穗。\n神仙宴满座，瑞色笼金翠。\n□□□窈窕，秦娥唱，行云散，梁□坠。\n花满帽，酒盈樽，长富长贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20721, '江城子', '莫蒙', '博山香暖衬江云。\n舞飞琼。\n拜双成。\n雾鬓风鬟，不改旧时青。\n滟滟金船罗袖劝，齐祝寿，比松椿。\n照人冰雪自天真。\n翠绡轻。\n下蓬瀛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20722, '江城子', '莫蒙', '秋堂风露月初弦。\n望灵源。\n隐珠躔。\n曾许东皇，游戏了尘缘。\n四海声名收不得，麾玉节，下清关。\n相逢只说好江山。\n紫宸班。\n待公还。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20723, '念奴娇', '宝月', '延陵福绪，蔼遗芳馀庆，直至如今。\n帝锡朋龟曾献策，早揖丹桂华簪。\n一代荣名，三州遗爱，留入歌吟。\n归来湖山付得，依旧闲心。\n延赏报德推封。\n名迁书监，喜天恩重临。\n拜舞龙香还注想，丹阙拖紫垂金。\n酒满霞觞，期君眉寿，千岁与披衿。\n年年风月，两行门外桐阴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20724, '菩萨蛮', '邓肃', '乳羝属国归来早。\n知君胆大身犹小。\n一节不须论。\n功名看致君。\n镇西楼上酒。\n父老为君寿。\n更寿太夫人。\n年年封诏新。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20725, '水龙吟', '曾', '去年看月诗成，援毫曾寄鄞江守。\n流传乐府，惭非宾客，竹枝杨柳。\n今岁江楼，载勤歌扇，青蛾应奏。\n况铃斋初驻，凉生燕寝，有香雾凝清昼。\n遥想十洲三岛，对冰轮、寒光依旧。\n主人来自，清都碧落，天香满袖。\n寄语嫦娥，剩留清照，时为公寿。\n恐明光诏下，翩然归去，试为霖手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20726, '洞仙歌', '严抑', '云车鹤盖，三岛朝元後。\n绿意红情在梅柳。\n想仙风从碧落次，吹得春来甘泉，喜见颜红宇秀。\n承明厌直，小憩苹洲，箫鼓行春此时候。\n华堂深苍耸，天女遥闻，凭细问，应得年长视久。\n喜苕邦人咏恩波，原有酒如渑，与公为寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20727, '鹧鸪天', '沈长卿', '瑞气氤氲入绛纱。\n水沉香荐碧流霞。\n疏梅欲破风前蕊，冷菊犹开霜後花。\n销粉黛，减铅华。\n药炉经卷好生涯。\n络滨侍从他年贵，便是蟠桃王母家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20728, '南乡子', '张浚', '迟日惠风柔。\n桃李成阴绿渐稠。\n把酒樽前逢盛旦，凝眸。\n十里松湖瑞气浮。\n功业古难侔。\n宜在凌烟更上头。\n已向眉间浮喜气，风流。\n千岁三分万户侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20729, '水龙吟', '胡寅', '玉梅冲腊传香，瑞秀荚开三四。\n莲花沉漏，熊罴占应，洛阳名裔。\n岁比甘罗，便疏同队，累棋观志。\n向修文寓直，仙楼侍宴，梁王宝、真难俪。\n多少襟怀未试，暂超然、壶中游戏。\n行看献策，归瞻旒藻，常勋记。\n歌畔巫云，舞回邹管，金钗扶醉。\n有阴功不乞，丹砂十纪，寿祺全畀。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20730, '满庭芳', '鲁', '坐啸蓬宫，移旌天府，往来三岛十洲。\n况瑞霭当年，初下琼楼。\n自是长生伴侣，那堪更河润神州。\n人争叹，威名福寿，衮衮压潮头。\n金瓯。\n须满泛，天厨禁脔，相酝□□。\n□□□□日，此会风流。\n正是湖山春媚，千秋岁、□□民猷。\n还知道，金瓯未拜，先拜富民侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20731, '雨中花・夜行船', '陆凝之', '三百年间，青史几多人物，俱委埃尘。\n独先生斯世，炼气成神。\n将我一支丹桂，换他千载青春。\n岳阳楼上，纱巾羽扇，谁识天人。\n千山短褐，掬水擎花，为君增祝灵椿。\n遥想望、吹笙坐殿，奏舞鸾。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20732, '满庭芳', '阳居士', '良月霜清，小春寒浅，瑞庭荚双飞。\n岭梅香度，初发向南枝。\n此际高门袭庆，真金降、金璧生辉。\n传瀛海向歆父子，相继大名垂。\n广寒，山藉在，笔驱造化，夕照虹霓。\n暂徘徊、莲幕名誉交驰。\n行继夔龙步武，蓬山静、玉宇春迟。\n当清夜，神交大一，相对熟青藜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20733, '醉蓬莱', '赵士', '正春风初扇，梅蕊飘香，雨馀晴昼。\n箫鼓声中，麝烟喷金兽。\n幕府宾僚，杜诗韩笔，竟吐奇争秀。\n共指乔松，同瞻峻岳，祝公眉寿。\n汉相功勋，陈思文藻，奕世风流，迥居人右。\n持节分符，屡试经邦手。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20734, '庆清朝', '李朴', '晓庭天离，擎香肖紫，严瑞气满春彰。\n勋门旧擎，从来功在江南。\n二百岁中阴德去，今天府享潭潭。\n遵画一，记得那时，□□□□。\n且趁东风解冻，向柳梢青处，□□□□。\n□□听满，此夕何惜醺酣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20735, '少年游', '温镗', '东风先报上林春。\n枝上晓莺新。\n凌虹御气，鞭鸾翳凤，来辅玉晨君。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20736, '少年游', '温镗', '谢家庭槛晓无尘。\n芳宴启良辰。\n风流妙舞，樱桃清唱，依约驻行云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20737, '少年游', '温镗', '芙蓉花发去年枝。\n双燕欲归飞。\n兰堂风软，金炉香暖，新曲动帘帷。\n家人拜上千春寿，深意满琼卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20738, '折丹桂', '温镗', '秋风秋露清秋节。\n秋雨过、秋香初发。\n二仙生值好秋天，气却与、秋霜争烈。\n秋霄开宴群仙列。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20739, '念奴娇', '芮烨', '化工着意，向柳稍梅萼，偷回春色。\n叶双飞政天上，一点文星初谪。\n发藻儒林，当年荣耀，四海声名白。\n谪仙飞貌，澹然物外踪迹。\n且与笑傲瀛洲，风流词翰，自是西垣客。\n异日功成辞富贵，却与赤松游剧。\n一曲清歌，三千珠履，不愧非潘璧。\n满斟芳醑，仰称遐寿千百。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20740, '蓦山溪', '傅自得', '洪钧转处，都在薰陶内。\n瑞世得奇才，赞化工，协调和气。\n雄词健笔，谈笑斡千钧，馀闲手，尹王畿，治行称尤异。\n雍容儒雅，早合登高位。\n天路踏骅骝，看峨冠，羽仪班缀。\n东风骀荡，王酒鳞红，春不老，寿难穷，莫惜今朝醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20741, '洞仙歌', '李鼐', '馀寒未展，帘幕新来燕。\n杨柳梢头嫩黄染。\n小溪山缭绕，别是风烟，春澹澹，谁道蓬莱路远。\n冰姿人不老，长伴春闲，环声中度芳宴。\n宝屏开，烟袅袅，金鸭吹香，欢笑处，烛影花光共暖。\n便莫惜瑶觞醉如泥，占岁岁东风，舞衣歌扇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20742, '渔家傲', '李鼐', '日借嫩黄初看柳。\n池塘冰泮游鱼透。\n庭馆匆匆佳气候。\n□山透。\n膺时贤佐生天佑。\n寿者康宁还德厚。\n功名富贵须长久。\n从此安排千岁酒。\n常祝寿。\n一年一献黄金酎。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20743, '鹧鸪天', '李鼐', '种得门阑五福全。\n常珍初喜庆华筵。\n王环醉拍春衫舞，今见康强九九年。\n神爽朗，骨清坚。\n壶天日月旧因缘。\n从今把定春风笑，且作人间长寿仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20744, '鹧鸪天', '李鼐', '珍重高人阎右丞。\n胸中丘壑富丹青。\n暂从天下分轺使，来向人间作寿星。\n凉日挂，暑风轻。\n一番秋思十分清。\n细倾鹦鹉休辞劝，烂醉葡菊不用醒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20745, '一井金', '李鼐', '绿阴清昼。\n两茸茸、梅子黄时侯。\n华堂金兽。\n香润炉烟透。\n舞燕回轻袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20746, '一井金', '李鼐', '一杯为寿。\n笑捧处、自传织手钗头。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20747, '风入松', '李鼐', '翠烟笼日上花梢。\n花外楼高。\n海犀不动帘栊静，昼长人懒莺娇。\n宝篆浓薰沉水，清商低按擅槽。\n画堂深处燕蟠桃。\n亲见仙曹。\n雾鬟不改朱颜好，年年长被春饶。\n一品疏封它日，十分沉醉今朝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20748, '玉蝴蝶', '李鼐', '望处水寒云绕，倚栏千里，澹荡晴晖。\n梦燕门阑，和气喜动帘帏。\n舞重、花明彩凤，歌扇小、香暖金猊。\n漏声迟。\n洞天秋晓，风露霏霏。\n嘉时。\n谪仙高宴，华分玉蜡，艳列文姬。\n玉树临风，自然老月中枝。\n酒肠宽、胸容云梦，词源壮、笔勇助溪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20749, '满庭芳', '李鼐', '腊雪溶酥，春冰浮玉，素蟾三五才过。\n晓来庭户，何事五云多。\n尽道九天麟坠，╆环、袅袅鸣珂。\n风标爽、胸中嵬磊，豪气挽天河。\n平生，横溯志，指挥夷虏，平定干戈。\n看它年功业，还让廉颇。\n且对江山难老，金樽满、鲸海翻波。\n歌声转，玉人扶处，拚取醉颜酡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20750, '鹧鸪天', '韩元吉', '雨歇云如隔座屏。\n薰风摇动一天青。\n今年五十平头过，又喜清歌洗耳听。\n浮世事，绝曾经。\n此生应直斗牛星。\n且倾田舍黄鸡酒，敢望君家白玉庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20751, '鹧鸪天', '韩元吉', '万古光寒太白精。\n直宜分作两郎星。\n不然安得难兄弟，先後尧三荚生。\n霜月冷，斗杓横。\n老人今夜已齐明。\n他年莫作郎星看，两两台躔拱太清。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20752, '满庭芳', '张抡', '威彻冰河，兵严玉帐，济时人在壶天。\n妙龄谈笑，图画上凌烟。\n但见勋书鼎鼐，谁知道、名列高仙。\n风云会，钩陈羽卫，绿鬓影貂蝉。\n绵绵。\n流庆远，芝兰秀发，折桂争先。\n占盛一门，文武更双全。\n已饵琼英绛雪，灵龟寿、何止千年。\n年年看，笙歌丛里，金盏倒垂莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20753, '鹧鸪天', '张抡', '鹤驭来从玉席前。\n笑谈勋业照凌烟。\n心游物外都无碍，春在壶中别有天。\n香似雾，酒如泉。\n华堂冰雪映神仙。\n灵椿不老青松健，花里年年醉管弦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20754, '鹧鸪天', '张抡', '彩舞萱堂喜气新。\n年年今日庆生辰。\n碧凝香雾笼清晓，红入桃花媚小春。\n须酩酊，莫逡巡。\n九霞杯冷又重温。\n壶天自是人难老，长拥笙歌醉洞云。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20755, '鹧鸪天', '张抡', '五福仙娥月殿来。\n依稀微步彩云随。\n一从别有瑶池宴，不见蟠桃几度开。\n歌宛转，舞徘徊。\n碧梧秋意满池台。\n年年玉露收残暑，长送新凉入寿杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20756, '鹧鸪天', '张抡', '消息枝头梅子黄。\n两宫恩意酿湖光。\n长庚自是文章瑞，好伴前星烛万方。\n金鸭暖，玉杯香。\n换鹅笔墨醉淋浪。\n只将名字为公祝，便合千秋佐玉皇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20757, '鹧鸪天', '张抡', '福善天应锡寿祺。\n人生七十古来稀。\n我翁更有椿龄在，馀庆堂前玉树辉。\n传世业，长孙枝。\n捧杯欢见老莱衣。\n一阳渐近门多喜，百禄争迎好事归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20758, '画堂春', '张抡', '月娥来自广寒宫。\n步摇环丁东。\n戏鸾双舞驾天风。\n雪满云空。\n一剪玉梅花小，九霞琼醴杯浓。\n凤箫千载莫匆匆。\n且醉壶中。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20759, '望仙门', '张抡', '玉池波浪碧如鳞。\n露莲新。\n新歌一曲翠眉。\n舞乖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20760, '望仙门', '张抡', '玉京清漏起微凉。\n好秋光。\n金杯潋滟酌琼浆。\n会仙乡。\n新曲调丝管，新声更霓裳。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20761, '望仙门', '张抡', '紫微枝上露华浓。\n起秋风。\n管弦声细出帘栊。\n象筵中。\n仙酒斟云液，山歌转绕梁虹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20762, '水调歌头', '侯置', '白鹤到时节，霜信满南州。\n金盘露重，银潢波浪载天流。\n岳渎千龄锺秀，赋出人间英气，清照洞庭秋。\n烈日严霜操，竹简万年留。\n苏属国，二千秩，若为酬。\n杜园阴密，未央前席动宸旒。\n入践紫薇郎省，擢赞绿槐公位，指日凤池游。\n千顷玉芝熟，准备饭青牛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20763, '水调歌头', '无名氏', '八月秋欲半，後夜月将圆。\n天潢当日流润，□派落人寰。\n尘扫长淮千里，威振南蛮八郡，梓里绣衣还。\n芳毓燕山桂，庆衍谢庭兰。\n小山阴，长松下，白云间。\n壶中自有天地，闻早挂逢冠。\n笑指横空丹壑，闲倚拿云竹杖，佳处日跻攀。\n山色既无尽，公寿亦如山。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20764, '水龙吟', '赵彦端', '两山空翠烟霏，几□又入东君□。\n□□但见，肉红染杏，眉黄着柳。\n彩燕风轻，宝灯月满，欢连清昼。\n是香山行处，苏仙座上，春不老，人依旧。\n闻道新骑白凤，过章台、天香满袖。\n英姿不向，通明宫殿，人间未有。\n况是从来，爱留南国，名高北斗。\n看君恩，却与西湖涨绿，作长生酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20765, '菩萨蛮', '芮辉', '晴云低蘸湖光湿。\n新凉远带江声入。\n风影逼中秋。\n移樽月在楼。\n蓝田栽竹手。\n借竹为君寿。\n苍翠一年年。\n长承雨露边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20766, '虞美人', '芮辉', '翠屏罗幕遮前後。\n舞袖翻长寿。\n紫髯冠御炉香。\n看取明年归奉、万年觞。\n今宵池上蟠桃席。\n咫尺长安日。\n宝烟飞焰万花浓。\n试看中间白鹤、驾仙风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20767, '念奴娇', '刘季裴', '三光五岳，震乾坤英彩，非金非玉。\n赫赫岩岩真相种，来跨横空仙鹄。\n十万儿童，和丰堂下，齐把梅山祝。\n黑头难老，岁寒苍桧修竹。\n须信自有家传，中庸一卷，是长生真。\n借问河阳公去後，几度桃开桃熟。\n十九年间，梦回天上，又见棠阴绿。\n看看促觐，喜传沙路新筑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20768, '满庭芳', '姜特立', '丹染吴枫，青环越岫，镜天霁色凝鲜。\n华堂珊，非务拥神仙。\n天遣澄清海岳，亲曾授黄石奇编。\n兴王略，智名俱泯，功业妙难言。\n翩翩。\n真迥立，香飘绣衮，色映貂蝉。\n有清诗千首，美酒如川。\n长与嫦娥共约，放冰轮，今夕先圆。\n中秋月，从今屈指，更借一千年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20769, '促拍满路花', '徐叔至', '人间秋正好，天上月才圆。\n玉霄人不老，对婵娟。\n五龙护日，一笑着貂蝉。\n禁殿开金钥，宝炬宫壶，诏催移下钓天。\n昴奎分秀采，箕翼与长年。\n华堂歌宛转，舞蹁跹。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20770, '鹧鸪天', '徐叔至', '两两台符映昴躔，南熏披拂寿炉烟。\n宝图继统千龄会，金铉调元一相贤。\n兰玉满，庆蝉联。\n天教世有鲁山川。\n霞觞更对瑶池，共看蟠桃着子年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20771, '鹧鸪天', '范成大', '仗下仪客笔下文。\n天风驾鹤住仙真。\n榴花三日迎端午，蕉叶千春纪诞辰。\n经志，立朝身。\n暂烦高手活吴民。\n明朝莫遣书丹篆，怕引新符刻玉麟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20772, '洞仙歌', '范成大', '碧城风物，有湖中天地。\n长笑羲娥不停轨。\n记蟠桃枝上，金母嗔尝，回首处，还又三千岁矣。\n料仙人拊顶，曾授长生，名在云琼赐书里。\n懒上郁萧台，应厌高寒，飘然下，赤城游戏。\n且山泽留连作仙，不要管蓬莱海中尘起。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20773, '西江月', '范成大', '樱笋园林绿暗，槐榆院落清和，年年高会引笙歌，戏彩人随燕贺。\n一笑难逢身健，十分休惜颜酡。\n还将瓜枣送金荷，遍照金章满座。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20774, '临江仙', '范成大', '功行三千宜五福，长生何假金丹。\n从教沧海又成田。\n琼枝春不老，壁月夜长妍。\n上界从来官府满，何妨游戏人间。\n年年强健到樽前。\n莫辞杯潋滟，君是酒中仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20775, '鹧鸪天', '范成大', '绣户当年瑞气充。\n紫阳驾鹤下天风。\n万山秀色浑锺尽，六月炎光一洗空。\n蕉叶满，彩衣重。\n刻符持节尽人雄。\n坐中金母欣馀庆，劝醉周公劝鲁公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20776, '满江红', '范成大', '天气新晴，寻昨梦，池塘春早。\n雨过湔裙，水上柳丝风袅。\n却忆去年今日，桃花人面依前好。\n怪今年、酒量却添多，银杯小。\n谁劝我，玉山倒。\n催细抹，翻新调。\n渐金狎压锦，喷首云绕。\n笼柏飞来双翠袖，弓弯内样人间少。\n为留连、春色伴山翁，都休老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20777, '清平乐', '范成大', '降嵩储昂，仙驭来尘表。\n身佩安危人不老。\n化国风光长好。\n功名南北天涯，欢声蛮峤胡沙。\n草木何□□露，小春桃李都花。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20778, '清平乐', '范成大', '何须轻举，上界多官府。\n身似灵光长镇鲁。\n俯仰人间今古。\n雨馀帘卷江流，朱颜流映琼舟。\n不假岗陵□寿，西山低似西楼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20779, '八声甘州', '□阳', '渐纷纷、木叶下亭皋，秋容际寒空。\n庆屏山南畔，龟游绿藻，鹤舞青松。\n缥缈非烟非雾，喜色有无中。\n帘幕金风细，香篆迷。\n好是庭闱称寿，簇舞裙歌板，欢意重重。\n况芝兰满砌，行见黑头公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20780, '点绛唇', '赵彦逾', '春到皇都，日边已觉风光丽。\n异人名世。\n独禀阳和粹。\n福寿川增，行庆鸳行缀。\n笙歌重。\n几多珠翠。\n拚取今宵醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20781, '南歌子', '张孝祥', '俭德仁诸族，阴功格上清。\n焚香扫地夜朝真。\n看取名花浮玉、鉴齐精。\n宝篆融融满，□流细细倾。\n双亲俱寿八千龄。\n却捧紫皇飞诏、上蓬瀛。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20782, '水调歌头', '卫时敏', '骑鲸紫霞客，来作世耆英。\n襟怀金玉循良，名字古无人。\n所至民歌遗爱，脱屣归来绿野，笑傲乐天真。\n不学渭滨老，公子自长生。\n一杯酒，再三祝，八十春。\n从今细数庆集，百度似今辰。\n绿鬓朱颜长好，何事紫芝仙草，兰玉自诜诜。\n盛事有如此，谁道四难并。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20783, '念奴娇', '卫时敏', '春风桃李，问耐寒何似，霜松雪柏。\n珍重拨烦京兆手，早岁声名霹雳。\n收卷经论，摆遗荣利，物外多间适。\n熊经龟咽，真传秘诀消息。\n奉秩初满华严，韶颜转映，绿鬓方瞳碧。\n况□□云供宴几，静对凫翁鹤客。\n只恐日边，蒲轮催动，密侍钧天席。\n上玉卮尧殿，长生倍注仙籍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20784, '汉宫春', '高伯达', '绛阙朝元。\n倦飞鸾控鹤，来寓人间。\n天教散舒和气，好与春还。\n蓬瀛罢宴，褪仙裳、欲冠貂蝉。\n应是念、潇湘胜概，来与蕃宣。\n宣室向来初见，叹不如、文帝夜半虚前。\n多情吊沉赋罢，莫负留连。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20785, '千秋岁', '高伯达', '影摇波动。\n晓日浮华栋。\n庆麟绂，徵兰梦。\n绿擎龟叶小，红拂莲腮重。\n帘幕外，半天仙驭来飞。\n两两骖鸾凤。\n□珠衣纵。\n香雾散，祥云拥。\n口传金母信，酒为麻姑送。\n休惜醉，与君更下蟠桃种。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20786, '鹧鸪天', '高伯达', '海上蟠桃月样圆。\n从头屈指几千年。\n双成已报春消息，输与萧郎半月前。\n风露晓，月华鲜。\n兽炉烟袅水沉烟。\n骑鸾鹤休归去，留取人间作女仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20787, '喜迁莺', '郝子直', '风云际会。\n自军兴勋业，唯公屈指。\n中镝红心，骄虏胆丧，中正已回天意。\n采石扶危鏖战，激励熊罴乘势。\n震天地，沮金狄百万，元颜诛毙。\n英卫。\n摅红气，寰海共欣，雪恨亡胡岁。\n宸眷褒功，华衮貂蝉，荣拜济时左揆。\n圣君用贤终始，肯使留侯谦退。\n後范蠡，愿永佐中兴，庄椿同纪。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20788, '画堂春', '郝子直', '华堂当日诞今辰。\n庆门人降西真。\n一杯千岁祝遐龄。\n莫厌频斟。\n不愿头白还黑，不愿齿落重生。\n但容艳只如今。\n寿等松椿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20789, '天香', '何得之', '南国蜚声，三鳌孕粹，中兴循吏称首。\n官在中都，斑参玉笋，妙简帝心应久。\n长材已试，名字向、金瓯先覆。\n貂冕冠蝉载服，鸾台凤池荣。\n年年桂觞介寿。\n正江梅、犯寒时候。\n料想舞僮歌女，翠鬟依旧。\n富贵人间罕有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20790, '水调歌头', '徐明仲', '迟日笼晴昼，新火敛馀寒。\n东君着意，留恋春色在人间。\n故遣蓬瀛仙侣，来布阳和德泽，造化寄毫端。\n麾节经行处，喜气满江山。\n听歌谣，五裤暖，二天宽。\n汉朝侧席，英隽玺诏促徵还。\n鞭算钱流粟腐，刃往剧烦解，启沃动龙颜。\n已有白麻笔，草制在金銮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20791, '水调歌头', '徐明仲', '宗社中兴佐，廊庙黑头公。\n故家乔木，十年风虎会云龙。\n三镇上流藩翰，千里北门符钥，何许在民功。\n刀剑还牛犊，饥馑化登丰。\n政成时，春明媚，日和融。\n寿觞如海，愿公一酌倒三松。\n移取活人心手，归作调元勋业，谈笑共平戎。\n还使十书老，直与古人同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20792, '满江红', '陈之贤', '人物英雄，更独抱、无双才气。\n年正壮，文章武略，尽曾留意。\n破胆欲凭胸内甲，清原宴启舟中誓。\n笑区区、燕雀不能知，青云志。\n封侯貌，神人比。\n社下手，须荣试。\n况相门出将，君家常事。\n斗印垂金他日贵，寿杯浮玉今朝醉。\n看年年、南极倍明时，春明媚。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20793, '念奴娇', '陈之贤', '炎精昌运，庆天为笃生，中兴人杰。\n横臆甲兵三百万，要扫群胡妖孽。\n抚弱怜贫，排奸击暴，所至人推服。\n飘飘志气，伟哉一代英特。\n预信衮衮公侯，名闻英胄，素有阴功积。\n腾踏从天上去，笑作龙头奇客。\n相印重封，将符再绾，尽履青毡物。\n寿杯满泛，年年长醉正月。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20794, '踏莎行', '丁求安', '风卷霜浓，寒销冰谢。\n一年皎月惟今夜。\n桑弧蓬矢庆门阑，云旌羽盖连车马。\n命服新翻，恩波如泻。\n海沂致锦傅声价。\n晓来和气着梅梢，春随温诏看看下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20795, '踏莎行', '丁求安', '紫府延龄，瑶池开宴。\n人间好事都如愿。\n凤雏喜带桂宫香，东床镇压鸾台彦。\n酒泛金杯，香飘龙篆。\n大家齐把瑶觞献。\n中兴天子急贤才，相期共入金銮殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20796, '念奴娇', '赵师律', '镜天露洗，荡仁风，满县正开桃李。\n无讼堂深睛画永，帘卷鹅山浓翠。\n吏散棠阴，鸟啼花散，箫鼓弦歌地。\n印封碧藓，笑谈无限清致。\n佳会正属悬弧，十分蕉叶，共祝千秋岁。\n道骨仙风元自有，功业人间游戏。\n名覆金瓯，班联玉笋，行庆风云会。\n莲舟容与，此时归继仙裔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20797, '念奴娇', '赵师律', '楚天春晚，尽替了，残红点成层碧。\n蝴蝶蜂儿娇未足，舞破游丝千尺。\n一夜风高，满天清露，冷浸琼楼彻。\n遮鸾绕凤，使君不是凡骨。\n游荡偶尔人间，铃斋谈笑，好作龚黄匹。\n火急功成天上去，却问蓬莱消息。\n酒泻鹅儿，十分金盏，染就眉间色。\n满城争看，一封鹗荐飞入。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20798, '齐天乐', '赵师律', '重阳还近秋光好，银屏翠箔凉透。\n凤髓炉温，鱼轩瑞应，天与冰壶清透。\n多文在手。\n更赖玉腰肢，唾花衫袖。\n旧约梅仙，为来人世作珍偶。\n虚堂帘半卷，化工何限意，妆点时昼。\n真香葵倾劝盏，都把芳心为寿。\n当歌对酒。\n愿绿发朱颜，镇长依旧。\n宝名高，已书千岁久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20799, '蓦山溪', '赵师严', '文章太守，今作湖山主。\n冰雪照人清，赋仙家、出尘风度。\n流芳积庆，故自有渊源，家将相，世侯王，勋德藏盟府。\n政修人治，千里歌来暮。\n有脚是阳春，鼓和风、遍充寰宇。\n芝泥封诏，肯为郡人留，苍玉佩，紫金貂，稳上星辰去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20800, '喜迁莺', '无名氏', '光风转蕙，正中和节过，艳阳春半。\n暖日，瑞烟蓬勃，正是生申华旦。\n保厘东土三载，分却九重霄旰。\n政成也，且凝香燕寝，雍容方面。\n堪羡。\n德望重，敌国隐然，不假长江险。\n堂上奇兵，胸中妙画，便是当年韩范。\n况逢左辖虚位，早晚洪钧须转。\n来岁里，看内家敕使，传呼宣劝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20801, '蓦山溪', '辛弃疾', '画堂帘卷，贺燕双双语。\n花柳一番春，倚东风、雕红镂翠。\n草堂风月，还似旧家时，歌扇底，舞边，寿年年醉。\n兵符传垒，已莅葵丘戍。\n两手挽天河，要一洗、蛮烟瘴雨。\n貂蝉冠冕，应是出兜鍪，五鼎，梦三刀，侯印黄金铸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20802, '感皇恩', '辛弃疾', '露染武夷秋，千蛮耸翠。\n练色泓澄玉清水。\n十分冰鉴，未吐玉壶天地。\n精神先付与，人中瑞。\n青锁步趋，紫微标致。\n凤翼看看九十里。\n任挥金碗，莫负凉飚佳致。\n瑶台人度曲，千秋岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20803, '水调歌头', '辛弃疾', '簪履竟晴昼，画戟插层霄。\n红莲幕底风定，香雾不成飘。\n螺髻梅妆环列，凤管檀糟交泰，回雪无纤腰。\n觞酒荡寒玉，冰颊醉江潮。\n颂丰功，祝难老，沸民谣。\n晓庭梅蕊初绽，定报鼎羹调。\n龙衮方思勋旧，已覆金瓯名姓，行看紫泥褒。\n重试补天手，高插侍中貂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20804, '望海潮', '沈伯文', '山连嵩岱，疆分齐鲁，济南自古多奇月。\n魄堕英星，芒剪瑞□，来参汉主龙飞。\n仙露繁枝。\n振家声赫奕，金印传龟。\n一种春风，後园桃李自成蹊。\n淮暂弭旌旗。\n庆歌浮绿野，人静圜扉。\n梅破粉痕，柳回星眼，相将紫诏催归。\n玉勒晓骢嘶。\n望天墀咫尺，香惹朝衣。\n最好朱颜绿发，劝宴凤凰池。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20805, '念奴娇', '钱处仁', '勋门积庆，为皇家此日，重生贤辅。\n崧岳储神须信道，非特当年申甫。\n清白传芳，高明驰誉，材更兼文武。\n黑头年少，风云还会龙虎。\n天为指日垂弧，张持节，不遣穹庐去。\n中使传宣，颁赐锡赍，清晓欢声旁午。\n两世光华，一门荣耀，盛事夸千古。\n祝公千岁，庙堂长佐贤主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20806, '醉蓬莱', '钱处仁', '正梧阴碧转，扇浪凉生，渐回秋意。\n祥绕朱门，有崧灵锺瑞。\n笔走龙蛇，句雕风月，好客敦高谊。\n苏小琵琶，绿珠箫管，日添罗绮。\n邃阁清班，贰车清政，奕叶蝉联，世间谁比。\n行侍甘泉，趁青春荣贵。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20807, '喜迁莺', '李焕', '云蒸雷动。\n庆瑞岳降真，祥生申甫。\n元后慈贤，勋臣英烈，百世显光家谱。\n久许致身忠孝，何止满怀今古。\n听舆论，是侯王苗裔，神仙俦侣。\n争睹藩尹盛，刑揩政成，和气横眉宇。\n北阙莺花，西湖风月，旌骑稳游天路。\n福海寿山无比，烂醉黄堂歌舞。\n正荣耀，有华姻宠授，清朝恩数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20808, '喜迁莺', '李焕', '风云嘉会，有英杰瑞时，来符平泰。\n子建才华，平阳勋业，流庆至今犹在。\n闾史卿来曾记，骨相堂堂庞艾。\n少年日，已心包云泽，名高嵩岱。\n超迈人尽道，今代吏师，小试犹淹大。\n两路登车，三州出牧，游刃了无凝碍。\n便合进推荷橐，迤逦参陪天。\n愿从此，奉明君真相，优游千载。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20809, '喜迁莺', '林伯镇', '百年卿族。\n更七叶桂籍，蝉联相续。\n早冠鳌峰，入持魁柄，却商野耕岩筑。\n绅望山瞻斗。\n勋业铭书金竹。\n倦陶冶，暂镜湖舒啸，琳宫休足。\n催促。\n归秉轴，须与君王，同享无疆福。\n缓访赤松，莫留绿野，宇县待公恢复。\n手把命堂印，腰束精寒玉。\n愿岁岁，看和羹梅绽，古阶槐绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20810, '凤栖梧・蝶恋花', '林伯镇', '破腊星回春可数。\n天佑中兴，岳降神生再。\n造膝一言曾寤主，翱翔历遍清华路。\n盖代功名知自许。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20811, '南乡子', '林伯镇', '弥诞秩初筵。\n催舞春雷杂管弦。\n惊破梅梢香喷雪，都缘。\n王母瑶池会列仙。\n残腊嫩寒天。\n恰在正朝两日前。\n搀借椒花先献寿，新元。\n重数壬辰第一年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20812, '念奴娇', '王涣', '水沉香霭，满钱塘千里，秋烟如织。\n万井欢声瞻宝钱，遥指明星南极。\n辇路看花，神旗垂彩，名冠金门籍。\n平阳家世，凌烟都减颜色。\n须信勋业风流，阳春有脚，到处开桃李。\n拥油幢宸眷重，吴越江南江北。\n认取疏梅，东君深意，遣调羹消息。\n凤书飞下，绿槐元自相识。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20813, '水调歌头', '陈敷', '明月双溪上，胜景号金华。\n当年此夕，多少鸾凤杂云霞。\n共拥飘倦伯，来作人间英杰，王谢旧名家。\n纶绋妙文采，帷幄富忠嘉。\n圣天子，形梦寐。\n眷尤加。\n麒麟烟上早晚，丹陛听宣麻。\n鼎袖无穷勋业，岁岁薰风日永，萱秀北堂花。\n潋滟绮筵酒，寿算等胡沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20814, '满庭芳', '甄良友', '杲杲重光，遥山耸翠，九天秋气高明。\n露团仙掌，初月挂前星。\n帝念吾君父子，亲传授、光启中兴。\n生储后，是为三圣，一道以相承。\n升平。\n当此际，黄花照座，丹桂充庭。\n对雨宫喜色，百辟欢声。\n好是橙黄桔绿，宣猷殿、酒碧香清。\n重重庆，尧仁舜孝，亲见禹功成。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20815, '南乡子', '甄良友', '十月小春天。\n放榜梅花作状元。\n会庆礼成三日後，生贤。\n第一龙飞不偶然。\n劝酒自弹弦。\n更着班衣寿老仙。\n见说海坛沙张也，明年。\n此夜休嗔我近前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20816, '感皇恩', '甄良友', '华表鹤重来，嘉禾合穗。\n天命真人救斯世。\n故仙子来佐，中兴之际。\n这回真是个，风云会。\n天水庆源，钱塘潮势。\n主圣臣贤千岁。\n半钩月小，一剪梅花香细。\n太平无事也，休辞醉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20817, '水调歌头', '甄良友', '直节傲山雪，偃盖咏松风。\n天香真色来报，春信月明中。\n六七日分景纬，五百年间英气，相值产维崧。\n君子中庸也，天下有胡公。\n把州麾，将漕计，简渊衷。\n淳熙新政，往风虎，趁云龙。\n底用玉卮卜寿，看取天然难老，高竹与长松。\n更有红梅实，调鼎告成功。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20818, '菩萨蛮', '甄良友', '希夷本是儒先祖。\n云仍来自神仙所。\n前日一阳生。\n德星今夜明。\n灵椿殊未老。\n仙桂双双好。\n好是百花魁。\n年年称寿杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20819, '蝶恋花', '甄良友', '照水绮霞明木杪。\n彩翼双栖，未觉桐阴少。\n正是一年秋光好。\n世间重睹香山老。\n祝寿人如群玉绕。\n满酌金莲，愿永谐歌笑。\n仙客莫疑来不早。\n洞中日月天昏晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20820, '水调歌头', '郑元秀', '富贵不难致，名节几人全。\n渡江龙化，于今五十有三年。\n历数中兴诸老，谁似武夷仙伯，操行老弥坚。\n吾道方中否，一柱独擎天。\n江南北，湘左右，惠宣敷。\n见说韩公城下，米斗只三钱。\n人愿公归台鼎，我愿公归草隐，九老要齐肩。\n岁岁祝公寿，风月满梅川。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20821, '水调歌头', '郑元秀', '园林夸富贵，红绿簇枝头。\n阳和毓秀，气屈贾压曹刘。\n翰墨场中独步，洒落胸中万卷，横截百川流。\n邈视青云侣，俯着看瀛洲。\n到如今，萦扃务，尚淹留。\n庙堂应得好语，早晚觐宸旒。\n从此立登要路，便可羽仪台阁，指日凤池游。\n岁岁蟠桃会，椿算八千秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20822, '瑞鹤仙', '黄人杰', '飞花闲院落。\n渐燕觜泥融，蜂须香薄。\n风光未全恶。\n有出林青杏，殿春红药。\n东皇旧约。\n把馀芳、一时留著。\n等君侯维岳佳辰，惜景为供春酌。\n新乐。\n谁番清韵，非石非金，金城弦索。\n如闻荐鹗，青云外，有飞削。\n双凫容与，摩天东上，稳步鸾台凤阁。\n管平泉，昼锦归时，发犹未鹤。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20823, '贺新郎', '黄人杰', '垛翠云蓬远。\n日鸟高、炎官直午，暑风微扇。\n二六尧开秀荚，跨海冰轮待满。\n怪院落，笙箫如剪。\n太乙然藜天际下，度卯金仙子，生华旦。\n依日月，近云汉。\n经时持橐明光殿。\n问江乡年来有几，只君方见。\n入座夫人难老甚，炯炯金霞照眼。\n笑指点，琼舟权劝。\n愿得调元勋业就，为红泉石磴轻轩冕。\n归共作，赤松伴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20824, '贺新郎', '黄人杰', '突金仙屋。\n素秋深、长空霁雨，万山如浴。\n惊破元戎呼小队，来看飞泉喷玉。\n正晚谷，清镜圆熟。\n还是紫微初度至，对禅关，自奏长生曲。\n留杖屦，倚松竹。\n汉中念远眉休蹙。\n问擎天拄地，个事只今谁独。\n看领召环回首，笑把江神要束。\n任碾破，澄波新绿。\n去了中兴台辅叶，挂貂蝉莫受风埃触。\n归绿野，种瑶簌。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20825, '满江红', '黄人杰', '季灰融，盛寒里、梅香乍放。\n元道是酿成和气，间生名将。\n马革裹尸男子志，虎头食肉通侯相。\n更胸中、十万拥奇兵，人皆仰。\n腰金印，垂玉帐。\n忠胆锐，雄心壮。\n倚辕门几望，北州驰想。\n且倒长江为寿酒，却翻银浦千寻浪。\n算时来、一笑洗胡尘，迎天仗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20826, '满江红', '黄人杰', '老子生朝，萧然坐离骚窟宅。\n更莫诧、才雄屈宋，诗高刘白。\n不向凤凰池上住，不逃鹦鹉洲边迹。\n谩一官、如水过称呼，诸侯客。\n平生志，水投石。\n首已皓，心犹赤。\n算陆沉雄奋，总非人力。\n广武成名惟孺子，高阳适意须欢伯。\n睨醉乡、一笑抚青萍，乾坤窄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20827, '满江红', '黄人杰', '老火西流，风露洗、银湾一色。\n还又近、半秋天气，月将成魄。\n玉燕来时清梦觉，书麟游处飞仙谪。\n问东南、一尉着斯人，如何得。\n君不学，吴门卒。\n君不问，长安狄。\n且持杯半揖，楚江。\n东府西台看历遍，归来绿野盟泉石。\n却从容、三万六千朝，追元白。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20828, '满江红', '黄人杰', '小驻碧油，公两载、重临初度。\n满全楚、袭人和气，拍天歌舞。\n波涌荆江流不断，地连巫峡山无数。\n指此山、此水诵公恩，难忘处。\n民有恨，来何暮。\n民有愿，归无遽。\n各相携卧断，衮衣归路。\n只恐九重劳梦寐，不容十国私霖雨。\n看便飞、丹诏日边来，朝天去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20829, '醉蓬莱', '黄人杰', '记征鸿归候，梦燕来时，雪清梅瘦。\n寒日迎长，觉微宽宫漏。\n翼轸分辉，斗牛呈瑞，间气维锺秀。\n江左风流，夷吾家世，尘源深厚。\n况是新闻，日边增秩，诰墨方妍，玉符将剖。\n五马西还，看鸳鸿为偶。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20830, '念奴娇', '黄人杰', '菊黄萸紫，近重阳、天气秋光如洗。\n怀燕占熊，还又应、崧岳生申时节。\n玉女擎香，金仙持送，锦里欢声彻。\n照人风度，满怀俱是冰雪。\n那更千里江城，政成人化，比春生秋杀。\n双凤云间御诏墨，将下十行新札。\n黄阁亨衢，碧油重幕，稳复清毡物。\n策勋归去，蟠桃犹许三窃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20831, '念奴娇', '黄人杰', '山光堂下，恰催花雨过，韶华将半。\n蝶舞回风莺度曲，暖响笙箫庭院。\n泥轼仙翁，当时此夕，正梦投怀燕。\n紫髯黄发，到今如此清健。\n岂但风月平分，海沂千里，流得欢声遍。\n屈宋江山，还助说，莫惜金荷频卷。\n问寿何如，凤池三到，却放壶天晚。\n赤松应待，挂冠归伴萧散。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20832, '玉楼春', '黄人杰', '生申时节书云月。\n惊怪玉梅开不彻。\n犯寒那得一枝春，要与邦君供胜绝。\n可轩有个词清切。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20833, '贺新郎', '黄人杰', '晓色收梅雨。\n玉衡高、寒杓插午，月生银浦。\n一片祥光横碧落，幻出新晴院宇。\n拥阆苑、擎香天女。\n簇引飞仙来瑞世，向乌衣巷陌，生文度。\n人物似，古怀祖。\n履声合上尧阶去。\n问如何低回计幕，蜀山深处。\n金字催还知有日，且听尊前妙语。\n更领略、双成歌舞。\n愿借流三峡水，与君侯尽作流霞注。\n觞百举，寿千数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20834, '渔家傲', '黄人杰', '桔绿橙黄霜落候。\n小春天气宜晴昼。\n一片祥光横宇宙。\n仙乐奏。\n千官共祝南山寿。\n湛露恩波浓似酒。\n□堂宴罢嵩呼後。\n压帽宫花红欲溜。\n还拜手。\n瞻天望圣徘徊久。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20835, '祝英台近', '黄人杰', '绛河清，丹阙晓。\n云路烛龙照。\n鹤发仙翁，笞凤下天眇。\n莹然璞玉襟怀，层冰风表。\n镇长住、人间三岛。\n怎知道。\n不用九转丹砂，灵椿自难老。\n骥子麟儿、勋业付渠了。\n已持红药开时，赤松游处，寿觞对、壶天倾倒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20836, '胜胜慢・声声慢', '黄人杰', '荣喉娇脆，燕体轻盈，争翻妙舞新声。\n元是君侯生日，爽气澄清。\n天应人为献寿。\n春着意、花也留情。\n恣豪饮，似流觞曲水，前度兰亭。\n况遇湖山官满，无一事、身心分外安宁。\n买个归舟，随鸥趁鹭长征。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20837, '临江仙', '黄人杰', '六月炎官收火伞，南薰尽洗烦蒸。\n十三荚又争青。\n问知陈仲举，元是此时生。\n别驾功成清暇日，题舆尚带屏星。\n黑头非晚至公卿。\n且倾浮蚁酒，来听祝龟龄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20838, '临江仙', '黄人杰', '江上小春来几许，湘桃已发微妍。\n开云今夕降飞仙。\n花神回暖律，天女炷祥烟。\n见说士元方展骥，低回共应尘缘。\n人间更住一千年。\n却骑丹凤去，归到五云边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20839, '临江仙', '黄人杰', '秋色三分绕过二，江城又近重阳。\n翠双荚为谁芳。\n梅仙生此日，神物自呈祥。\n陶菊半黄萸斗紫，一时来共飞觞。\n祝君腾踏比奇章。\n玉枝元不许，眉寿与天长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20840, '临江仙', '黄人杰', '解事西风真可意，秋声不到尧。\n尚馀□荚十分清。\n知君当此际，清梦应长庚。\n道骨仙风元不老，天开鹤算龟龄。\n更看宝带换红。\n拂衣辞管库，谈笑取功名。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20841, '蝶恋花', '黄人杰', '问讯梅花开也未。\n孕雪┭香，春在寒梢尾。\n试与折来供一醉。\n寿乡容与生春意。\n律转黄锺霜小霁。\n月姊乘鸾，伴我浮尘世。\n结取年年今日誓。\n梅花影里看仙桂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20842, '贺新郎', '黄人杰', '三月桃花浪。\n涌荆红、浮光散彩，倚空千丈。\n杨柳阴中长堤路，一片笙歌暖响。\n春待晚、气清天亮。\n闻道君侯生此日，具虎头、飞食封侯相。\n风度远，襟怀爽。\n宝杯为我倾家酿。\n醉乡深，何妨更尽，吸川鲸量。\n富贵时来应自有，岂在随人俯仰。\n且共把、眉头开放。\n但得仙风长不老，又安知、不做东南将。\n勋业付，云台上。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20843, '瑞鹧鸪', '黄人杰', '江梅还是嫁东风。\n夜半春心一点融。\n知道个人生此日，暗香浮雪荐金锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20844, '清平乐', '黄人杰', '西风猎猎，秋到双荚。\n天女擎香开寿□，寿酒浮花蘸甲。\n眉间一点轻黄。\n归帆已载斜阳。\n去矣留中好住，尧天日月偏长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20845, '沁园春', '黄人杰', '金虎鸣秋，玉龙ㄏ月，天气正凉。\n应梦熊时侯，叶丹苔碧，栖鸾亭馆，桔绿橙黄。\n人在兰台公子上，更身寄风流屈宋卿。\n登赏处，记含情纾思，曾赋高唐。\n春明旧家不远，算蝉嫣袭庆，都付仇香。\n况弦初续，和生角徵，鹗书频下，名厕循良。\n但得西风吹峡水，尽倒卷波澜添寿觞。\n功业事，有朱颜领略，未许称量。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20846, '满江红', '黄人杰', '腊近嘉平，谁教放、梅梢弄雪。\n更为问、霜前甘泽，应何时节。\n十荚尧开翠羽，一番潘貌蒸红颊。\n是武夷、六六洞王中，生贤哲。\n头未雪，心犹铁。\n柔不茹，刚难折。\n个功名怀抱，试看摅发。\n渌水中间辞地角，绛霄高处朝天阙。\n管痴儿、事了挂冠归，方华发。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20847, '满江红', '黄人杰', '居士生朝，元来是、湖山胜日。\n长共荐、霜前篱落，半黄橙桔。\n酒压浮蛆新旨酽，香浮瑞兽祥烟密。\n更小蛮、清唱入时宜，声飘逸。\n湖海量，冰霜质。\n年未老，身犹屈。\n记平生操履，几曾亏失。\n季野阳秋虽有自，伯仁崆峒原无物。\n待着君、添个老人星，人间出。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20848, '满江红', '黄人杰', '解语宫商，为谁奏、长生一曲。\n见说道、密堂深处，宝香芬馥。\n月里飞仙云际下，乘鸾来伴凫仙宿。\n约年年、生日醉冰，簪梅玉。\n花与貌，争清淑。\n云共发，斗新绿。\n尽壶觞为寿，苦无他说。\n有子有孙真老大，无嗔无妒家和睦。\n更鸾花、剩着几番封，平生足。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20849, '贺新郎', '黄人杰', '逗晓晴烟敛。\n过书云、祥开五日，漏添宫线。\n葭莞飞灰微度暖，着梅梢尚浅。\n怪深院、笙箫如剪。\n非雾非烟浮月观，应麟书，吐处豪英产。\n迟绣斧，启华宴。\n楚腰舞彻霓裳遍。\n拥金船，柔纤莹玉，十分争劝。\n醉入无何休莫问，日下长安非远。\n况一点、眉黄新见。\n掩鼻功名须办了，赋归来、却访乔松伴。\n应未许，雪枝汗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20850, '贺新郎', '黄人杰', '急雨收庚暑。\n倚三峰、祥光万丈，晓窥临汝。\n金石台边人语闹，惊怪麟书夜吐。\n又却是、重生申甫。\n笔底婆澜翻瀚海，更风流，不减王文度。\n冰共雪，是标榘。\n双凫有底人间住。\n为萍江，一齐洗尽，吏奸民蠹。\n见说王堂新有诏，趣近尧天尺五。\n看紫闼黄扉平步。\n我有新翻长寿曲，愿淮波、衮衮长东注。\n波未竭，寿无数。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20851, '鹧鸪天', '黄人杰', '挺挺君家有祖风。\nō任馀庆尚无穷。\n钓鳌莫问当年事，汗马须收第一功。\n何日是，梦维熊。\n麦光摇翠浪花红。\n一尊敬为祈难老，要作人间矍铄翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20852, '鹧鸪天', '黄人杰', '落落南班间世英。\n风流人物汉更生。\n当时良月垂孤处，天女惊香下广庭。\n鲸作量，兕为觥。\n尽倾家酿祝龄。\n校雠天禄须君辈，藜杖看陪太乙星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20853, '鹧鸪天', '黄人杰', '瑞霭朝迷紫极宫。\n梅香轻度琐窗风。\n关西都护生时节，来吐芳心献寿锺。\n头来白，频先红。\n臂强方解挽雕功。\n银符玉帐轻毡在，稳著功名继乃翁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20854, '菩萨蛮', '黄人杰', '小春就双桃靥。\n伴他二六尧荚。\n红绿若为新。\n个时生玉人。\n玉人持酒笑。\n笑与仙翁道。\n从此百年中，莺花几度封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20855, '虞美人', '黄人杰', '瑶台夜冷清霜泣。\n听得双成语。\n有人乘月下云端。\n吹彻凤箫来此、伴栖鸾。\n尊前有个新番曲。\n不唱蟠桃熟。\n一杯聊驻玉精神，长与雪梅争韵、更争春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20856, '虞美人', '黄人杰', '吕城春色知何处。\n试听流莺语。\n江头别有小壶天，唤起一番花柳、弄芳妍。\n主人元是虬髯种。\n胸次吞云梦。\n一尊何翅祝长年。\n看取金枝从此、更联。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20857, '虞美人', '黄人杰', '菊花不等重阳到。\n昨夜都开了。\n问知仙子是生辰。\n采翠浮金来供、玉壶春。\n周郎莫计文君寿。\n头白须相守。\n从今更数百年期。\n月底云间同跨、彩鸾归。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20858, '虞美人', '黄人杰', '飞八叶书云後。\n此日孙枝秀。\n爱他风味似吾人。\n都是笔头能篆、又能文。\n青青两鬓年方壮。\n儿女俱成长。\n要添福寿与荣华。\n教取一庭兰玉、共成家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20859, '虞美人', '黄人杰', '疏梅淡月年年好。\n景思今年早。\n迎长时节近佳辰。\n看取衮衣华发、尽麒麟。\n酒中倒卧南山绿。\n起舞人如玉。\n风流椿树可怜生。\n长与柳枝桃叶、共青青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20860, '念奴娇', '黄人杰', '挽红留翠，为东皇、那住二分春色。\n燕舞回风莺度曲，晴昼光生瑶席。\n天女擎香，长庚入梦，还有飞仙谪。\n方瞳方颊，玉壶清浸胸臆。\n休问辟谷延年，介君眉寿，自有阴功□。\n膝下雏俱擢秀，争奋摩天云翼。\n白雪声中，黄流影里，且放琼舟侧。\n醉乡深处，兴来时拊金伏。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20861, '满江红', '石孝友', '分景亭前，梅红糁、柳金谁粟。\n芳意闹，烧灯初过，坠萱才六。\n此日悔康歌别驾，当年神降生崧岳。\n看邦人，称寿雾凝香，杯丛玉。\n采石月，光天禄。\n姑溪水，增川福。\n炳灵祥曾产，瑞枝奇木。\n秋露短檠诗礼训，春风小院琵琶曲。\n愿长眉疏鬓等松椿，年年绿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20862, '鹧鸪天', '石孝友', '贤圣相逢信有因。\n同年同月下穹庭。\n紫薇花下丝纶手，采石江边衮绣身。\n梅破腊，酒浮春。\n锦绷行弄掌珠新。\n那人请效封人祝，愿寿尧君与舜臣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20863, '南乡子', '石孝友', '梅雪弄芳馨。\n饯日迎辰契月。\n争着琴堂称贺处，娉婷。\n满捧霞觞璨鲤庭。\n鹤等更龟龄。\n八十仙翁醉复醒。\n好倩洛阳驰誉手，丹青。\n乞与人间作寿星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20864, '满江红', '石孝友', '帘卷南薰，微雨过、天容似沐。\n开绮燕，红蕖别馆，绿槐高屋。\n灵寿杖横龙脊瘦，长年酒酿鹅儿熟。\n唤飞琼、亲捧紫霞杯，歌新曲。\n双凤好，温和玉。\n谈俭幕，嬉莱眼。\n且功成身退，注名仙。\n莲社焚香冰琢句，兰亭笔云翻墨。\n愿朱颜、长伴赤松游，骑黄鹄。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20865, '满江红', '石孝友', '且转桐阴，正玉燕、飞来夏屋。\n帘幕映，海留红艳，麝重兰馥。\n风采传闻瞻瑞节，婉谋曾是回钧轴。\n卷秦淮、吹入酒杯中，波翻绿。\n丹诏下，公归速。\n看日奏，三千牍。\n想春迷柳院，夜分莲烛。\n清暑声寒苍玉佩，月娥笑捧长生。\n问瑶池、阿母手栽花，何年熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20866, '满庭芳', '周云', '黄蕊封金，素英缕玉，此花端为君开。\n五云深处，昨夜见三台。\n天相勋门庆胄，嫖姚後，重产英材。\n蝉宫客，胸中万卷，荷橐久徘徊……。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20867, '洞仙歌', '周云', '千崖滴翠。\n正秋高时侯。\n橙黄桔绿又重九。\n有蓬壶仙子、赤鲤来游，风云会，施展经纶妙手。\n去年称寿处，北斗天浆，今夜天浆挹南斗。\n听笙箫云里奏，月满琼楼，瑶台上、拥出嫦娥观酒。\n待脚踏层云倒天河，尽倾向霞觞，与君为寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20868, '水调歌头', '俞国宝', '灵谷有荚气，盘结在巴山。\n云蒸雨朵欲遣，奇怪出人间。\n不作丰城宝剑，不作渥洼灵种，不作化龙竿。\n生此济时杰，理乱总相关。\n入为相，出为将，两馀闲。\n忠肝义胆，曾将鲠论破天颜。\n好把平勋业，趁取河清桃熟，千岁奉金銮。\n草却登封检，双鬓未曾斑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20869, '满庭芳', '俞国宝', '南省西清，黄扉青琐，五年历遍中都。\n一封朝奏，无乃爱君欤。\n便作筠阳胜赏，东溪上、鸥鸟相娱。\n谁知道，心存魏阙，身暂寄江湖。\n东溪，何所有，冬梅夏柳，春杞秋蕖。\n谩回首，多少笼鸟池鱼。\n细看山林朝市，经行处、等是蘧庐。\n今朝好，一杯寿酒，一卷养生书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20870, '临江仙', '俞国宝', '落落江湖三岛，才高懒住清都。\n手携黄石一编书。\n醉眠莘垅月，闲钓渭川鱼。\n见说玉阶三尺地，思君来讲唐虞。\n夜来南极一星孤。\n不知天子梦，曾到傅岩无。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20871, '蓦山溪', '俞国宝', '木犀开了。\n还是生辰到。\n一笑对东风，喜人与、花容俱好。\n寿筵启处，香雾扑帘帏，星河晓，晚丝簧奏，拚取金尊倒。\n当年仙子，容易抛蓬岛。\n月窟与花期，要同向、人间不老。\n拈枝弄蕊，此乐几时穷，一岁里，一番新，莫与蟠桃道。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20872, '临江仙', '俞国宝', '春到江南江北了，东皇未识花权。\n直将和气入巴川。\n逢迎天上客，来作地行仙。\n满捧一杯听细说，只今谁似公贤。\n愿推功业辅尧年。\n都将闲日月，来醉百花前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20873, '蓦山溪', '俞国宝', '群花烂熳，春色浓如酒。\n芳草绿铺茵，正荼シ、牡丹时侯。\n佳辰协瑞，来降蕊宫仙，珠帘卷，画堂深，香雾腾金兽。\n朱颜绿鬓，不改长安旧。\n金盏莫辞深，拚通宵、尽从银漏。\n笙歌丛里，欢笑度年华。\n看荣贵，有儿孙，永祝松椿寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20874, '蓦山溪', '俞国宝', '江天霜晓，梅粉参差吐。\n剪剪暗香风，自吹到、瑶台仙路。\n辎缥缈，昨夜出蓬莱，云鬓薄，月眉纤，元是飞琼侣。\n知书识字，书带先生女。\n来配计然家，货财等、封君千户。\n谷量牛马，更用斗量金，年不老，富无穷，常作蟠桃主。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20875, '念奴娇', '俞国宝', '云收雾敛，过一番疏雨，秋容新沐。\n月满巴山天似水，满眼祥云飞扑。\n一点长庚，瑞腾光彩，独照梅仙屋。\n十洲三岛，有人初降凡俗。\n长怪李白疏狂，骑鲸一去，千载无人逐。\n也解重来应尚欠，多少人间传曲。\n只怨君王，促归批诏，夜对金莲烛。\n蓬莱日醉，不知海岛桃熟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20876, '念奴娇', '王孝严', '昨宵灰动，有阶前春草，侵凌春雪。\n碧玉堂前为寿处，齐祝遐龄千百。\n夜冷笙箫，庭深灯火，应照梅妆额。\n容华依旧，向来姑射标格。\n独恨绾系日边，东风回首，还有溪山隔。\n怅望云飞，凝伫久，空使怀英心折。\n遥折一枝，饱斟花露，再拜瞻南极。\n愿言来岁，凤池同看春色。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20877, '南歌子', '陈晔', '腰下重金贵，眉间一点黄。\n定知从此庆非常。\n况有阴功宜寿、等天长。\n乞得仙家酒，来称诞日觞。\n乃翁阿母醉何妨。\n行见诸郎接武、上明光。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20878, '满庭芳', '陈晔', '翠竹阴团，绿荷芗嫩，朝来和气盈盈。\n薰风楼阁，玉燕梦初成。\n便有功名壮志，持符节，麟虎频。\n更归来後，挂冠神武，四海□高名。\n今年，方八十，莱衣舞处，拜霞觥。\n想笙歌递奏，鼎沸欢声。\n何用渠渠颂祝，自应合、福禄安荣。\n丹台上，玉清山籍，金字注长生。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20879, '醉蓬莱', '陈晔', '算当年紫府，乘兴霓车，世间游戏。\n符节功名，谩略儿小试。\n自挂衣冠，旋栽松菊，占水云佳致。\n九人年高，重重恩渥，丝纶光贲。\n十里西湖，九霞仙酿，举劝吾翁，诞辰一醉。\n窦氏阴功，筹彭久视。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20880, '耍鼓令', '陈晔', '化日长。\n政莺语，啭新篁。\n到处园林垂绿幄，槐风细，梅雨凉。\n见庭户，瑞霭回翔。\n拥真仙，鸾驭临华堂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20881, '水调歌头', '邵元实', '双阙步云尾，六阁上鳌头。\n侍臣冠底，英英人物是君侯。\n闻道东皇深意，回想西清往事，早晚启金瓯。\n丹伫宏略，黄阁待名流。\n九秋天，千岁日，一樽酬。\n策勋黄石，相期茅土更封侯。\n稳扈钩陈天仗，净扫搀抢氛，按辔入神州。\n收了卢龙塞，却访赤松游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20882, '喜迁莺', '卑叔文', '春回天际，见柳眼翠窥，梅腮粉腻。\n日庆三阳，时逢千载，帷幄挺生元帅。\n亘古抚今忠义，天下安危注意。\n负英伟，信功高耿贾，勋侔霍卫。\n和气。\n东风里，楼阁五云，玉帐环珠翠。\n庙食真扬，人怀邵父，当代虎臣难比。\n拟把倩桃为寿，莫惜金花沉醉。\n受阃寄，佐君王神武，复恢舆地。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20883, '满庭芳', '臧鲁子', '澹露零空，好风光袂，月华飞入觥筹。\n青莲碧藕，芡实与鸡头。\n笑傲纶巾羽扇，有如此、人物风流。\n西湖上，不妨游戏，民富自封侯。\n骈蕃。\n新宠渥，弃华延阁，领事园丘。\n看木牛流马，恢复神州。\n万里凉霄浩渺，使星共、南极光浮。\n从今好，一秋长醉，直醉过千秋。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20884, '鹧鸪天', '臧鲁子', '虎踞龙蟠万古雄。\n横飞一节大江东。\n今归定作鸾坡客，笔底山川写不穷。\n吟絮柳，赋东风。\n年年春在建章宫。\n天教随佛生人世，恰似河沙寿我公。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20885, '满庭芳', '臧鲁子', '露洗银潢，风来玉宇，正当□□□□。\n□□□阁，争看拥冰轮。\n共指银河影里，依稀见、执斧仙人。\n还知麽，天教此夕，嵩岳再生申。\n夤缘，当阃寄，高明洞物，爽气侵云。\n记广寒宫殿，曾对高真。\n玉兔捣馀灵药，霞觞化、万种花春。\n嫦娥嘱，愿公难老，长似月精神。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20886, '满庭芳', '陈秉文', '山涌银涛，屏间绣，太平今日皇州。\n共惟京牧，昭裔本宗周。\n好是王春正月，维岳降，膺此神休。\n尧阶下，存八荚，长应八千秋。\n优游。\n兼国计，丰财重谷，首善承流。\n更刑清讼简，政入歌讴。\n已副貂蝉眷宠，夸中外，耸动□讴。\n居恩重，苍生望切，好个富民侯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20887, '满庭芳', '谈羲仲', '星宿呈祥，溪山锺秀，凛然生此真贤。\n冰清玉润，还称岁寒天。\n正是梅梢酝雪，探江南，春信先傅。\n庭轩爽，涓涓皎月，今夜十分圆。\n开筵。\n称寿处，歌尘飞动，舞袖蹁跹。\n愿公与椿松，对阅天年。\n第恐宏才重望，不容暂吟醉苕川。\n龙光近，行看凤诏，来自日华边。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20888, '点绛唇', '谈羲仲', '冰玉神人，岁寒时节迎初诞。\n照溪梅绽。\n秀岭孤松远。\n香雾氤氲，不放重帘卷。\n歌声缓。\n酒杯深劝。\n此会年年见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20889, '水调歌头', '王高', '千枝蔓仙牒，眉宇肖苍龙。\n就中天赋英杰，玉磬照金锺。\n满袖春风和气，散在苕溪水，讴歌颂儿童。\n好个庙堂样，貂弁马头公。\n烛如椽，香似雾，宴蓬瀛。\n我家寿酒须信，不与世间同。\n昨夜欢传清禁，今日黄堂歌舞，千载一相逢。\n来岁五云里，宣劝折黄封。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20890, '水调歌头', '王高', '今夕是何夕，南极见祥光。\n自天飘下佳气，五色覆黄堂。\n为借盐梅妙手，暂对裤襦欢颂，森戟护凝香。\n馀事剩吟咏，金薤灿琳琅。\n眷田园，松径旧，菊畦荒。\n欲乘风驭归去，策杖纵相羊。\n物外乾坤自在，壶里无尘日月，千岁傲羲皇。\n天意未应许，军国要平章。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20891, '蝶恋花', '江袤', '身世谁人知觉梦。\n阳焰空花，尽被三彭弄。\n可但运机畦上瓮。\n由来不了轻根重。\n休要寻文披大洞。\n丹鼎屯蒙，养取元珠动。\n意马此时何用。\n长生自与天齐共。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20892, '瑞鹧鸪', '华岳', '挑尽银缸半夜花。\n拍帘风劲卷龙沙。\n香传梅福深深意，春在钱塘小小家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20893, '瑞鹧鸪', '华岳', '华月楼前见玉容。\n凤钗斜褪鬓云松。\n梅花体态香凝雪，杨柳腰肢瘦怯风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20894, '满江红', '华岳', '自古称稀，须信道、人生七十。\n当七月、庆生佳节，更逢七夕。\n丹鼎麻姑多两转，蟠桃王母无双实。\n更竹林、作者茂芝兰，俱无敌。\n持觞劝，辰拱北。\n阴功在，头俱黑。\n况轲亲教子，同声战国。\n九万鹏程当不二，八千椿寿看逾一。\n愿从今、屈指再从头，山中日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20895, '菩萨蛮', '华岳', '玉纤倒把罗纨扇。\n屏山半倚羞人见。\n回首忽相逢。\n桃花生嫩红。\n见了娇无语。\n还向屏山去。\n略略转秋波。\n客愁无奈何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20896, '念奴娇', '华岳', '倚藤临水，照丰姿自笑，天然丘壑。\n利鞅名缰成底事，空把此身缠缚。\n李杜文章，良平事业，且束之高阁。\n浩然归去，暮霞残照零落。\n闻道西北埃尘，东南形胜，次第清河岳。\n此等功名尘世事，与我初无关约。\n十里松萝，一蓑烟雨，说甚扬州鹤。\n倚栏长啸，玉轮飞上天角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20897, '满江红', '华岳', '懒取冠儿，只偏带、一枝翠柏。\n记刺指、封书罗带，尚馀残血。\n愁入柳眉云黛蹙，汗凝桃脸胭脂湿。\n把玉纤、掩定古词名，猜谁识。\n瓶已坠，宁无阙。\n盟已负，难成匹。\n念当年亭院，画楼东北。\n烛影烧残蝴蝶梦，纹皱起鸳鸯翼。\n叹如今、憔悴忆前欢，重门隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20898, '霜天晓角', '华岳', '裙儿六幅，谁染秋波绿。\n一搦柳腰两过，樽前粲粲玉。\n暑气消烦溽。\n日月飞车轴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20899, '蝶恋花', '华岳', '叶底无风池面静。\n掬水佳人，拍破青铜镜。\n残月朦胧花弄影，新梳斜插乌云鬓。\n拍索闷怀添酒兴。\n旋撷园蔬，随分成盘。\n说与翠微休急性，功名富贵皆前定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20900, '南歌子', '华岳', '粉絮飘琼树，摇花结玉池。\n蕊仙滕六逞瑰奇。\n都把银河细剪、做花飞。\n小院风声急，歌楼酒力微。\n闷中犹记去年时。\n呵手牵人相伴、塑狮儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20901, '望江南・忆江南', '华岳', '罗雾薄、绀绿拥重重。\n八幅宝香薰锦绣，一床烟浪卷芙蓉。\n屏翠叠东风。\n云点缀，香汗透玲珑。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20902, '霜天晓角', '华岳', '情刀无。\n割尽相思肉。\n说後说应难尽，除非是、写成轴。\n帖儿烦付祝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20903, '霜天晓角', '华岳', '蒲帆十幅。\n飞破秋江绿。\n天际彩虹千丈，阑干外、泻寒玉。\n一雨收残溽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20904, '满江红', '华岳', '……正秋容万里，十分明洁。\n后羿久忘逃去处，东方尚忆来年月。\n但无端、燕贺赋声诗，容凡客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20905, '满江红', '华岳', '庙社如今，谁复问、夏松殷柏。\n最苦是、二江涂脑，两淮流血。\n壮士气虹箕斗贯，征夫汗马兜鍪湿。\n问孙吴、黄石几编书，何曾识。\n青玉锁，黄金阙。\n车万乘，骓□匹。\n看长驱万里，直冲燕北。\n禹地悉归龙虎掌，尧天更展鹏翼。\n指凌烟、去路复何忧，关山隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20906, '渔家傲', '华岳', '昨夜寿星朝北极。\n牵牛织女排筵席。\n闻有谪仙先一夕。\n方知得。\n流倬底人生日。\n慷慨英雄当路识。\n鹗书已凝循京秩。\n试问遐龄谁与敌。\n回ò绎。\n撇头添个长长十。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20907, '水调歌头', '华岳', '英荚才开六，宝历已当千。\n人间收尽繁溽，凉意入虞弦。\n尽道荐衡交剡，更值生申佳节，喜色动闾阎。\n终夜望银汉，文宿贯台躔。\n定燕秦，封晋魏，信当然。\n处处红莲开幕，曹掾岂能淹。\n见说玉堂飞诏，已许金闺通籍，蓬岛伴神仙。\n来岁寿卮酒，应醉御炉烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20908, '水调歌头', '华岳', '万里楚天阔，一点寿星明。\n庭语以识歌舞，拍拍□秋声。\n会过牛郎六夕，圆欠嫦娥一夜，此际是佳辰。\n□□□□□，□□□□□赍予说，□神岳，庆生申。\n□领仓符，□兼漕节握藩旌。\n但□闽山建水，无地不阳春。\n今日范滂刘宴，来岁周公伊尹，元化斡洪钧。\n北阙中书今，南极老人星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20909, '满江红', '华岳', '帘拍风颠，云共雨、商量欲雪。\n愁不寐、兽炉灰冷，寸肠千结。\n罗带只贪珠泪擤，金钗不整乌云侧。\n对菱花、空自敛双蛾，伤离别。\n心下事，凭谁说。\n愁与恨，如山积。\n被傍人调闻，呢龟成鳖。\n塞雁来时空怅望，梅花开後无消息。\n恨薄情、拚却与分飞，还重忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20910, '瑞鹧鸪', '赵希蓬', '强将纸帐醉梅花。\n千劫应知作热沙。\n梦逐梨云迷去路，曲随杨柳到伊家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20911, '瑞鹧鸪', '赵希蓬', '把定离觞不肯斟。\n闻君未醉尽衷情。\n丁香空结千般恨，柳线难萦一片心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20912, '瑞鹧鸪', '赵希蓬', '长亭无路对孤斟。\n自古离家三日情。\n慷慨要酬平昔志，猖狂休起少年心。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20913, '瑞鹧鸪', '赵希蓬', '温柔乡里睹春容。\n无语闲将脚带松。\n魂梦阳台迷暮雨，丰姿洛浦挹仙风。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20914, '念奴娇', '赵希蓬', '功名富贵，算到头，怎免委沟填壑。\n曳钓抱琴秋水畔，肯与微官空缚。\n五亩苍阴，一丘寒碧，说甚凌烟阁。\n静观物理，从他荣悴开落。\n任待入谷鸣雏，不须歆艳，免使朝南岳。\n修竹长松常与伴，更有寒梅堪约。\n夜且三更，西风万籁，入耳悲猿鹤。\n从头洗去，更无一点圭角。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20915, '蝶恋花', '赵希蓬', '昼永无人深院静。\n一枕春醒，犹未临镜。\n帘卷新蟾光射影。\n连忙掠起蓬松鬓。\n对景沉吟嗟没兴。\n薄幸不来，空把杯盘。\n休道妇人多水性。\n今宵独自言无定。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20916, '南歌子', '赵希蓬', '玉立亭亭树，水澌小小池。\n园林遍地幻珍奇。\n战罢奇鳞无数、满天飞。\n云冻风威惨，天低月色微。\n红绡暖帐浅斟时。\n那更樽前清韵、听歌儿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20917, '霜天晓角', '赵希蓬', '枕痕如斫。\n一线红生肉。\n睡起娇羞无语，远山坐对横轴。\n烧香频祷祝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20918, '满江红', '赵希蓬', '干结青铜，根走石、参天古柏。\n最好是、苍阴不怕，火云如血。\n雪里直疑神物护，雨馀任待霜皮湿。\n但只愁、涧底老风烟，无人识。\n栋梁用，知难缺。\n轮辈，俱非匹。\n望长松万丈，徂徕山北，一种刚姿雕样劲，共扶大厦斯翼。\n便作舟、归去也何愁，蓬莱隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20919, '满江红', '赵希蓬', '休羡莺花，春富贵、韶光九十。\n最好是、清秋时候，人间何夕。\n天上紫云车趣驾，殿中青鸟音传实。\n正女牛、南极一齐明，光相敌。\n诗在手，堂趋北。\n染豪处，池翻黑。\n看回鸾飞诰，宠封新国。\n福比箕畴兼备五，寿除彭祖千中一。\n更好将、大衍数重推，来复日。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20920, '满江红', '赵希蓬', '七叶开，正祈巧、穿针时节。\n织女不骖王母驾，谪生名阅。\n鹤算七旬书宝，鹊桥千丈飞银阙。\n更玳筵、银烛照红妆，神仙列。\n歌宛转，莺调舌。\n番舞袖，风回雪。\n对寿觞频劝，寿星明洁。\n今日汉宫千岁药，明年唐殿长生月。\n问班衣、戏彩是何人，蓝袍客。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20921, '满江红', '赵希蓬', '缟兔黔乌，送不了、人间昏晓。\n问底事、红尘野马，浮生扰扰。\n万古末来千古往，人生得失知多少。\n叹荣华、过眼只须臾，如风扫。\n篱下菊，门前柳。\n身外事，杯中酒。\n肯教它萧瑟，负持螯手。\n漠漠江南天万里，白云入望何时到。\n倚西风、吼彻剑花寒，频搔首。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20922, '菩萨蛮', '赵希蓬', '何人四座环歌扇。\n平生有限何曾见。\n今日忽遭逢，流霞映脸红。\n此恨凭谁语，梦逐巫山去。\n对景苦奔波，其如愁思何。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20923, '菩萨蛮', '赵希蓬', '慧刀挥处人头落。\n虹霓万道冲云脚。\n灭尽我人心，何劳向外寻。\n白莲生火里，法忍无生死。\n忍辱两皆空，龟毛兔角同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20924, '渔家傲', '赵希蓬', '怪见台星离紫极。\n果然揆左还虚席。\n明日人间逢七夕。\n真难得。\n生贤特也涓良日。\n坐侯鲭人罕识。\n流璃都把宾筵秩。\n寿祝乔松谁与敌。\n珠落绎。\n樽前一列金钗十。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20925, '水调歌头', '赵希蓬', '熟见蟠桃几，岁阅大椿千。\n鞭鸾间出簇拥，仙仗蔼丝弦。\n落尽纨罗习气，都把诗书酝籍，忧念到闾阎。\n人物降崧岳，文采焕奎躔。\n抟扶摇，游汗漫，气飘然。\n珠曹莲区区，州县步难淹。\n鹗荐交腾当路，凤诏飞来伊夕，称寿萃群仙。\n事业登黄阁，图绘上凌烟。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20926, '满江红', '赵希蓬', '劲节刚姿，谁与比、岁寒松柏。\n几度欲、排云呈腹，叩头流血。\n杜老爱君□谩苦，贾生流涕衣空湿。\n为国家、子细计安危，渊然识。\n英雄士，非全阙。\n东南富，尤难匹。\n却甘心修好，无心逐北。\n螳怒空横林影臂，鹰扬不展秋空翼。\n但只将、南北限藩篱，长江隔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20927, '满江红', '赵希蓬', '海阔何人，工剪水、飞花作雪。\n刚不北、秋高风劲，露凝霜洁。\n遍地直疑琼玉砌，对人恍在珠玑侧。\n比寻常、万翠与千红，浑然别。\n梁园内，都休说。\n蓝关路，堆如积。\n把行人冻得，头颅如鳌。\n翡翠帘中杯潋滟，销金帐里姑情息。\n偶兴来、访戴起山阴，真相忆。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20928, '水调歌头', '程伯春', '功名果何物，天欲付英豪。\n请看襄汉，今日谁驾六灵鳌。\n阅礼崇诗元帅，大纛高牙临塞，砥柱一洪涛。\n百辟拱辰极，欢动赭黄袍。\n策无遗，勋益著，德弥高。\n定知阳报，谢庭兰玉付儿曹。\n秀发如君独擅，浑似当年幼度，文武素兼韬。\n岁岁长为寿，霞液荐蟠桃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20929, '满庭芳', '赵良玉', '红杏香中，绿杨影里，画桥春水泠泠。\n深沉院满，风送卖花声。\n又是清明近也，粉墙畔，时有迁莺。\n当此际，人传天上，特降玉麒麟。\n风云。\n今会遇，名邦坐抚，入侍严宸。\n更儿孙兰玉，都是宁馨。\n脆管繁弦竞奏，蕙炉袅，沉水烟轻。\n华筵罢，江城回首，一点寿星明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20930, '减字木兰花', '赵孟谦', '荣魁鹗荐。\n一举南宫膺妙选。\n人物规模。\n楚楚吾家千里驹。\n彩衣侍酒。\n更祝二亲无限寿。\n父子荣迁。\n俱侍玉皇香案前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20931, '贺新郎', '张明中', '卓茕欧阳子。\n是江山、毓秀锺灵，异才间世。\n恰则韶光三月暮，叶尧阶有四。\n正天启、悬弧盛事。\n金鸭亭亭书云篆，散非烟、南极真仙至。\n来为尔，荐嘉瑞。\n神清洞府丹书字。\n拥笙歌、绮席高张，更罗珠翠。\n千里长春人不老，仙籍玉环暗记。\n但判取、沉醉。\n拟作新诗八千首，待一年、一献称俾尔。\n耆而艾，昌而炽。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20932, '卜算子', '刘克庄', '四大因缘做，苦海凭船渡。\n一清风到岸头，得上无生路。\n人叹风贫苦，我步闲闲趣。\n脱体全空没一文，胜似石崇富。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20933, '卜算子', '刘克庄', '自入玄门户，寂寂清虚做。\n静里披搜四假身，勘破尘行路。\n悟上还重悟，得得真闲趣。\n收住身中无价真，岂逐人情去。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20934, '卜算子', '刘克庄', '风汉闲中做，彼岸神舟渡。\n万里晴空无片云，月照南溪路。\n割断冤情苦，默默明玄趣。\n一任傍人笑我贫，肚里非常富。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20935, '卜算子', '刘克庄', '纤软小腰身，明秀天真面。\n淡画修眉小作春，中有相思怨。\n昔立向人羞，颜破因谁倩。\n不比阳台梦里逢，亲向尊前见。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20936, '卜算子', '刘克庄', '梅岭数枝春，疏影斜临水。\n不借芳华只自香，娇面长如洗。\n还把最繁枝，过与偏怜底。\n试把鸾台子细看，何似丹青里。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20937, '满江红', '方岳', '晓傍苍崖，滴寒露、研朱点易。\n五十四卦为归姝，惟幽人吉。\n彼美人兮春上下，如吾徒者山南北。\n辨一生、坚壁卧烟霞，诗无敌。\n人间世，胶中漆。\n功名事，刀头蜜。\n放乾坤醉眼，看朱成碧。\n曾共梅花相尔汝，仅教雪後无消息。\n莫怕寒、容易嫁东风，春狼藉。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20938, '水调歌头', '方岳', '老子兴不浅，归矣复言归。\n不知归又何处，知我者何希。\n幸有青山一片，付与白云千载，便可乐渔矶。\n且尽一杯酒，春瓮晓生肥。\n倩梅花，邀涧叟，醉林扉。\n五年今已如此，莫倚健於飞。\n日月笼中双鸟，今古人间一马，五十五年非。\n归去不归去，未了比山薇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20939, '满庭芳', '方岳', '雨带苍烟，须粘残雪，几年今日秋崖。\n梅花篱落，不减旧情怀。\n更觉神仙有分，一条冰、羽客官阶。\n朝真外，研朱点易，风露滴松钗。\n蓬莱。\n清浅未，吾将游戏，月坞云齐。\n已相期汗漫，鹤蜕青鞋。\n一念人间尘土，为雏孙、留醉茅柴。\n今而後，村书杂字，仅有老生涯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20940, '江城子', '方岳', '几年诗骨雪槎牙。\n痼烟霞。\n老生涯。\n五十八翁，堪喜亦堪嗟。\n忽忆香山居士语，还失笑，较争些。\n荒寒梅坞月横斜。\n短篱遮。\n野人家。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20941, '永遇乐', '郭子正', '多种阴功，後蒙天报，荣贵长久。\n一片灵台，丹青要画，画请看人间秀。\n慈仁雅着，延永松年，内鼎有丹方就。\n想除非，真的高人，五福自然兼有。\n从来义方，今见公辅，量运夔龙居後。\n承北门风，相传世业，都是经邦手。\n狂歌将意，知公难老，永助庆堂尊酒。\n有重重，腰金孙子，继来献寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20942, '菩萨蛮', '朱子厚', '酴浴罢温香玉。\n牡丹睡起歌云绿。\n弹压属东阳。\n留春在庆堂。\n简端新组绶。\n辉映烟岚秀。\n妙曲倩清妍。\n祝君无尽年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20943, '失调名', '张埴', '玉宇风清，金茎露爽，五日新秋。\n正好小轩，相逢初度，七十边头。\n满前白发けけ。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20944, '瑞鹧鸪', '汪元量', '内家雨宿日辉辉。\n夹遥桃花张锦机。\n黄纛软舆抬圣母，红罗凉伞罩贤妃。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20945, '汉宫春', '汪元量', '玉砌雕栏。\n见吴宫西子，一笑嫣然。\n舞困人间半，艳粉争妍。\n珠帘尽卷，看人间、金屋神仙。\n歌队里，霞裾袅娜，百般娇态堪怜。\n别有一枝仙种，更同心并蒂，来奉君筵。\n猩蜃若教解语，曲谱应传。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20946, '瑶花', '汪元量', '天中树木，高耸玲珑，向濯缨亭曲。\n繁枝缀玉。\n开朵朵九出。\n飞琼环簇。\n唐昌曾见，有玉女、来送春目，更月夜、八仙相聚。\n素质粲然幽独。\n江淮倦客再游，访后土琼英，树已倾覆，攀条掐干，细嗅来、尚有微微清馥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20947, '莺啼序', '汪元量', '檀栾宫墙数仞，敞朱帘绣户。\n正春暖、飘拂和风，衮入红尘香雾。\n见丝柳青青，袅娜如学宫腰舞。\n有黄莺、恰恰飞来，一梭金羽。\n小巧身儿，锦心绣口，圆滑遽如许。\n避人，渐飞入琼林藏身，桃杏深处。\n对银屏、珠圆翠陈，隔叶底、恣歌金缕。\n忽群妃，拍手惊飞，奋然高举。\n晓来雨湿，花娜柳垂，误投罗网去。\n缓缓访、六宫寻问，玉纤争握。\n放入金笼，眼娇眉妩。\n身如旅琐，无心求友。\n烟窗分影光阴里，听蛮声，似怨还如诉。\n青山隔断，红妆满眼，谁怜一。\n幽恨难吐，沉香拂拂。\n亭北阑干，已得君王顾。\n但暗忆、西湖美景，雨色晴光，入翠穿红，巧转娇语。\n莺莺休怨天家，已赠金衣公子。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20948, '失调名', '汪元量', '绿荷初展。\n海榴花半吐，绣帘高卷。\n整顿朱弦，奏霓裳初遍，音清意远。\n恍然在广寒宫殿，窈窕柔情，绸缪细意，闲愁难剪。\n曲中似哀似怨。\n似梧桐叶落，秋雨声颤。\n岂待闻铃，自泪珠如霰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20949, '忆王孙', '汪元量', '神舟稳驾出沉流。\n明月辉辉命自周。\n两个先生暗点头。\n有来由。\n万劫轮回向此休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20950, '忆王孙', '汪元量', '修行谁会把心降。\n赤凤驱将饮碧江。\n调引婴娇笑舞双。\n剔银缸。\n物物头头现晓窗。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20951, '忆王孙', '汪元量', '从初得得便风流。\n降伏龟蛇住定州。\n千日丹成永永收。\n好因由。\n自在逍遥万事休。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20952, '忆王孙', '汪元量', '心中无事气神和。\n不觉忻忻言语多。\n剑用磨更磨。\n害风哥。\n割了舌头赶退魔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20953, '忆王孙', '汪元量', '尘寰财色苦相萦。\n著爱浮华役此身。\n好收灵源一点真。\n绝贪嗔。\n便是逍遥到岸人。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20954, '忆王孙', '汪元量', '无无无有有无无，悟得无无便不愚。\n日月年时损壮粗。\n见元初。\n万道霞光攒宝珠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20955, '忆王孙', '汪元量', '茫茫苦海两无边。\n无限迷鱼戏黑渊。\n我掷金钩钓有缘。\n线儿牵。\n引上神州采玉莲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20956, '忆秦娥', '汪元量', '笑盈盈。\n晓妆扫出长眉青。\n长眉青。\n双开雉扇，六曲鸳屏。\n少年心在尚多情。\n酒边银甲弹长筝。\n弹长筝。\n碧桃花下，醉到三更。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20957, '忆秦娥', '汪元量', '雪霏霏。\n蓟门冷落人行稀。\n人行稀。\n秦娥渐老，着破宫衣。\n强将纤指按金徽。\n未成曲调心先悲。\n心先悲。\n更无言语，玉箸双垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20958, '忆秦娥', '汪元量', '天沉沉。\n香罗拭泪行穷阴。\n行穷阴。\n左霜右雪，冷气难禁。\n几回相忆成孤斟。\n塞边鼓愁人心。\n愁人心。\n北鱼南雁，望到而今。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20959, '忆秦娥', '汪元量', '水悠悠。\n长江望断无归舟。\n无归舟。\n欲携斗酒，怕上高楼。\n当年出塞拥貂裘。\n更听马上弹箜篌。\n弹箜篌。\n万般哀怨，一种离愁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20960, '忆秦娥', '汪元量', '风声恶。\n个人蕉萃凭高阁。\n凭高阁。\n相思无尽，泪珠偷落。\n锦书欲寄鸿难托。\n那堪更听边城角。\n边城角。\n又添烦恼，又添萧索。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20961, '忆秦娥', '汪元量', '如何说。\n人生自古多离别。\n多离别。\n年年辜负，海棠时节。\n娇娇独坐成愁绝。\n胡笳吹落关山月。\n关山月。\n春来秋去，几番圆缺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20962, '忆秦娥', '汪元量', '马萧萧。\n燕支山中风飘飘。\n风飘飘。\n黄昏寒雨，直是无。\n玉人何处教吹箫。\n十年不见心如焦。\n心如焦。\n彩笺难寄，水远山遥。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20963, '人月圆', '汪元量', '钱塘江上春潮急，风卷锦帆飞。\n不堪回首，离宫别馆，杨柳依依。\n蓟门听雨，燕台听雪，寒入宫衣。\n娇鬟慵理，香肌瘦损，红泪双垂。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20964, '太常引', '汪元量', '广寒宫殿五云边。\n看天上、烛金莲。\n香袅御炉烟。\n拥彩仗、千官肃然。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20965, '婆罗门引', '汪元量', '一生富贵，岂知今日有离愁。\n锦帆风力难收。\n望断燕山蓟水，万里到幽州。\n恨病馀双眼，冷泪交流。\n行年已休岁，七十又平头。\n梦破银屏金屋，此意悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20966, '锦瑟清商引', '汪元量', '玉窗夜静月流光。\n拂鸳弦、先奏清商。\n天外塞鸿飞呼，群夜渡潇湘。\n风回处，戛玉铿金，翩翩作新势，声声字字，历历锵锵。\n忽低颦有恨，此意极凄凉。\n炉香帘栊正清洒，转调促柱成行。\n机籁杂然鸣素手，击碎琳琅。\n翠云深梦里昭阳。\n此心长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20967, '玉楼春', '汪元量', '咸淳十载聪明帝。\n不见宋家陵寝废。\n暂离绛阙九重天，飞过黄河千丈水。\n长春宫殿仙沸。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20968, '玉楼春', '汪元量', '帝乡春色浓於雾。\n谁遣双环堆绣户。\n金张公子总封侯，姚魏弟兄皆列士。\n碧纱窗下修花谱。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20969, '满庭芳', '丁无悔', '道格天渊，令行海岳，凛然名德尊崇。\n云烟千里，分付笑谈中。\n川后波神效职，潮声细、一鉴涵空。\n风樯便，蛮珠贾舶，累译更遥通。\n雍容。\n廊庙手，蓍龟先见，日月精忠。\n自丛机初解，眷渥尤隆。\n共道奇庞福艾，衮衣到，宁久居东。\n谁门晓，高牙大纛，辉映醉颜红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20970, '满庭芳', '丁无悔', '偃屋霜清，棱层烟碧，玲珑移在人间。\n山光林色，常伴主人闲。\n元有仙风道骨，无心趁、玉简朝班。\n归来赋，不因五斗，谈笑挂衣冠。\n尤难。\n谁不羡，商山桔乐，湄水渔竿。\n引相君王子，助发幽欢。\n满泛寿觞多祝，南溟共、比海波澜。\n君知否，庙堂有意，相与问寒岩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20971, '喜迁莺', '杨再可', '腊天初晓，庆五色瑞云，华轩呈绕。\n紫府真人，丹台仙伯，合降世间荣耀。\n彩笔素题，篇翰未减，家声词藻。\n秀眉宇，俊丰标阀阅，声名都好。\n富贵长欢笑。\n此际锦堂，移下蓬莱岛。\n妙舞蹁跹，清歌宛转，两行翠娥燕赵。\n劝饮百千锺酒，岁岁朱颜不老。\n春近也，看香红又怕，小桃开了。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20972, '水调歌头', '刘仲讷', '昨夜乘秋兴，长啸驭清风。\n飘然玉宇虚廓，忽到广寒宫。\n解后娥相见，为问中秋诞节，奇特世难同。\n底事长庚梦，独占此宵中。\n呼金兔，寻玉策，检前踪。\n自从盘古有月，便有此山仙翁。\n公向人间游戏，月在天衢来往，清气每相通。\n明月既无尽，公寿亦无穷。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20973, '水调歌头', '蒋思恭', '紫府掣金钥，银汉夜乘槎。\n老仙暂驻幢节，来佐玉皇家。\n翠发朱颜好在，肘後有方医国，宝鼎养丹砂。\n谈笑功名了，身退饭胡麻。\n游物外，聚紫脑，炼青芽。\n星坦寓直有子，曾步八砖花。\n来岁称觞寿宴，衮绣彩衣交映，重荐枣如瓜。\n俯首拾瑶草，长啸卧烟霞。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20974, '水调歌头', '蒋思恭', '风流九霞客，名在五云乡。\n十年出入华禁，簪奉君王。\n黄伞西清日转，宝月红鸾影里，长近赭袍光。\n彩笔赓歌处，殿阁有馀凉。\n跨秋风，凌宝鼎，笑芝房。\n人间争识奇贵，妙帖焕名章。\n莫羡碧幢金印，换取玉堂清琐，翰墨看淋浪。\n岁岁宫壶酒，雨露带天香。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20975, '洞仙歌', '张成可', '薰风池阁，八叶初展。\n紫府当年侍香案。\n见蟠桃频着子，偷荐瑶觞，贪醉寐，谪向人间未满。\n青禽传近信，催赴仙班，怪我尘缘未能断。\n爱吴中山色好，抹日批风，蓑共笠，纵有金章不换。\n待驾鹤遨访蓬壶，问海水从来，几番增减。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20976, '醉蓬莱', '丁仲远', '正霜融日暖，风淡寒轻，小春时候。\n後苑疏梅早放，数枝开就。\n知是花工，预回天气，与作仙翁寿。\n君看侯门，祥云锁戟，瑞烟笼昼。\n天赋麒麟风骨，尽道德耀宗盟，名高星斗。\n两郡甘棠，惠爱传民口。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20977, '水龙吟', '真知柔', '碧霄彩旆垂铃，应南极星躔光灿。\n巍巍名阀，芳传汉相，貂蝉炳焕。\n德莹冰壶，量包沧海，神锺岩电。\n向宝储内阁，英才华，声猷著膺宸眷。\n荐领名都屏翰，更循良、歌腾畿甸。\n峻专剧郡，荣登法从，光生尧殿。\n密勿论思，雍容启沃，才华独冠。\n愿年年长见，兰芽玉喷，柳梢金嫩。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20978, '玉楼春', '张时甫', '姑苏台上春光发。ピ\n菊老寒轻香未歇。ピ\n人言太守是龚黄，天为吾君生稷契。ピ\n月良庆会俱良月。ピ');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20979, '玉楼春', '张时甫', '蟠桃十月惊春早。\n春到玉梅枝上小。\n和羹人物应时生，天上骑鲸生凤沼。\n万家宝篆祥烟晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20980, '玉楼春', '李朝卿', '谪仙暂下金銮殿。\n开宴瑶池春未晚。\n飞琼献舞锦靴寒，弄玉吹箫银字暖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20981, '玉楼春', '李朝卿', '炉烟不断腾金兽。\n香雾入帘波影皱。\n秋堂锦席艳群仙，不惜绮罗萦舞袖。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20982, '玉楼春', '李朝卿', '厌玉为浆麟作□。\n玉树琼葩长不谢。\n翠帘绣暖燕归来，宝鸭花香蜂上下。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20983, '小重山', '李朝卿', '春正浓时月正圆。\n华堂初燕喜，雨真仙。\n霞衣相对旧貂蝉。\n人间少，福寿子孙贤。\n□□佳非烟。\n花光羞粉艳，敢争妍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20984, '鹧鸪天', '李朝卿', '万里霜空爽气高。\n翩翩天雁薄云霄。\n佳祥已协当年梦，岂但非熊可珥貂。\n金笏带，紫花袍。\n朱衣双引玉宸朝。\n百年富贵须平步，仍有功名信史褒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20985, '西江月', '李朝卿', '盛德须知异禀，天教占尽秋光。\n一轮明月照华堂。\n荐寿笙歌嘹亮。\n座上簪缨并列，庭前兰玉成行。\n只应难老胜松篁。\n五福人间供仰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20986, '踏莎行', '李朝卿', '月挂琼钩，日添绣线。\n骑花翻浪重帘卷。\n风传环晓珊珊，画堂羯鼓催开宴。\n翠缕香凝，玉膏酒滟。\n仙翁莫诉玻璃满。\n凤衔丹诏下云电。\n千秋长在黄金殿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20987, '鹧鸪天', '李朝卿', '九凤箫低彩雾高。\n鸾车鹤驭下层霄。\n天教来辅长生帝，宝殿千秋侍赭袍。\n飞急召，促归朝。\n沙路稳为马蹄娇。\n功成并画兰台上，奎画重看御赞褒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20988, '青玉案', '谈元范', '虾须帘上银钩小。\n筵内轻寒绕。\n红叶徵香侵语笑。\n金钗珠履，凤萧龟鼓，疑是蓬莱岛。\n萱堂日日春生貌。\n嫩绿休然鬓边好。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20989, '青玉案', '倪翼周', '烟浓水淡荷香浅。\n近翠幕、闻弦管。\n逸气棱层冲碧汉。\n绝无风骨，炼成铅鼎，未许童颜换。\n长门深锁文君院。\n前度蛮笺泪痕满。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20990, '青玉案', '倪翼周', '四时令节惟重九。\n况此日、逢佳偶。\n金菊已花杯有酒。\n瑶池宴罢，一枝斜插，好作渊朋友。\n翠眉淡淡匀宫柳。\n比似年时更清瘦。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20991, '青玉案', '倪翼周', '薰风解尽吾民愠。\n正蓬渚芳遍。\n昨夜商周生伊旦。\n从来仁者，仲尼称寿，更捧金杯劝。\n我有诗词三百卷。\n待留取、频频献。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20992, '青玉案', '倪翼周', '熙春堂下花无数。\n红紫映、桃溪路。\n蝶往蜂来知几许。\n翠筠亭外，绿阳堤畔，时听娇莺语。\n绮筵罗列开樽俎。\n况总是、神仙侣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20993, '醉蓬莱', '段倚', '正星杓首舍，月律开祥，嗣兴芳序。\n梦协长庚，诞清朝仪羽。\n运继姬周，庆流嵩岳，认再生申甫。\n职尹京华，功宣国计，声猷兼著。\n子建文章，懿侯宗范，叔度襟怀，紫芝眉宇。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20994, '新荷叶', '贺及', '莲萼飘香，金风乍扇轻凉。\n郁郁葱葱，瑞烟萦绕华堂。\n星辰孕秀，良霄梦、吉协熊祥。\n紫芝眉宇，莹然如峙圭璋。\n忠孝传芳，集庆门、奕世簪裳。\n他日岩廊，致君直上虞唐。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20995, '沁园春', '傅伯达', '白帝司权，炎宫回驭，一叶报秋。\n正银河高泻，金风作扇，冰轮将满，火伞初收。\n吴越传芳，斗牛锺秀，间世生贤谁与俦。\n那堪更负，过人才气，济世谋猷。\n风流花县优游，有善政廉名达郡侯。\n鹗书朝荐，泥封暮召，荣登闺籍，平步瀛洲。\n歌驻行云，舞翔回雪，寿酒深倾碧玉瓯。\n从今愿，愿龄齐鼻祖，名在丹丘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20996, '满庭芳', '郑达可', '肥绽梅红，嫩翻荷绿，微凉时起青萍。\n人间福艾，都属老人星。\n累建高牙大纛，循良治、是处彬彬。\n棠阴里，丰碑纪德，仁爱浃生民。\n纶巾。\n风物裹，一筇徒倚，傲睨寰瀛。\n况清朝黄发，尤急咨询。\n第恐商山芝客，岂容便、蝉蜕功名。\n他时看，腰横玉带，朱紫列云仍。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20997, '念奴娇', '郑达可', '嫩凉如水，正一天风露，秋容如沐。\n明日中秋今夜月，千里清辉光足。\n周室姬公，唐家元轨，来享人间福。\n老人星瑞，光芒南照檐曲。\n行看裂土分茅，朱颜青鬓，好称腰横玉。\n便挽银河斟北斗，倾作千锺。\n子舍荣华，孙枝赫奕，茂盛同松竹。\n尊前欢笑，竞将椿算为祝。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20998, '南歌子', '臧馀庆', '桔里风烟好，壶中日月长。\n松身鹤发自安强。\n应有老人呈瑞、动光芒。\n酒饮无边酒，香烧不断香。\n从今乞与醉为乡。\n更醉百年三万、六千场。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (20999, '鹧鸪天', '臧馀庆', '天与君王管晏才。\n尚书两曳履声来。\n今朝望着楼头看，已有台星照斗魁。\n金蹀躞，玉崔嵬。\n天香满袖早朝回。\n中书尚享无穷考，长揖南风醉寿杯。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21000, '鹧鸪天', '臧馀庆', '寿菊才开三四葩。\n秋光着意主人家。\n清香未许人间识，先占重阳醉紫霞。\n儿绿绶，母金花。\n斑衣庭下乐无涯。\n要知他日中书考，细数沙堤堤上沙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21001, '感皇恩', '臧馀庆', '消息近春来，东风还又。\n先借椒盘劝金斗。\n坐间和气，压尽一番梅柳。\n掖庭频寓直，君恩厚。\n天两宫，南山齐寿。\n况有仙丹在公手。\n论功医国，合在药王之右。\n不妨千岁饮，长生酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21002, '感皇恩', '臧馀庆', '南岳有真仙，人间祥瑞。\n酒量诗豪世无比。\n晚年林下，做个清闲活计。\n诮如千岁鹤，巢云际。\n此日大家，广排筵会。\n酒劝千锺莫辞醉。\n昔时彭祖，寿年八百馀岁。\n十分才一分，那里暨。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21003, '感皇恩', '臧馀庆', '交广出沉香，路遥难致。\n何况卑人更不易。\n寿星香帕，我又几曾识置。\n有般祝寿底，忒戏。\n剪下一张，池州表纸。\n拈得轻圆更滑腻。\n五双纸拈，管打十个喷嚏。\n□□□□儿，一百岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21004, '鹧鸪天', '胡于', '去日清霜菊满丛。\n归来高柳絮缠空。\n长驱万里山收瘴，径度层波海不风。\n阴德遍，岭西东。\n天教慈母寿无穷。\n遥知今夕称觞处，衣彩还将衣绣同。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21005, '鹧鸪天', '胡于', '阿母蟠桃下记春。\n长沙星里寿星明。\n金花罗纸新裁诏，具叶傍行别绶经。\n同龙子，祝龟龄。\n天教二老鬓长青。\n明年今日称觞处，更有孙枝满谢庭。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21006, '鹧鸪天', '胡于', '楚楚吾家千里驹。\n老人心事正开渠。\n风流不减庭前玉，爱惜真如掌上珠。\n纡绿绶，荐方壶。\n老人沉醉弟兄扶。\n问将何物为儿寿，付与家传万卷书。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21007, '鹧鸪天', '胡于', '袅袅薰风响环。\n广寒仙子跨清鸾。\n谁教瑞世仪周间，自赋多才继小山。\n铃阁静，画堂闲。\n衮衣象服镇团栾。\n年年此日称觞处，留待菖蒲驻玉颜。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21008, '鹧鸪天', '申国章', '十载分符衣绣衣。\n裳阴处处浙东西。\n政成已可书银笔，词鹿仍堪付雪儿。\n春未半，日方迟。\n御沟金袅柳如丝。\n凤池留得梅花住，欲与先生荐寿卮。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21009, '鹧鸪天', '陈日章', '内乐清虚息万缘。\n逍遥真是地行仙。\n徙他玉带金鱼贵，听我纶巾羽扇便。\n倾九酝，祝长年。\n休辞潋滟十分舡。\n来年此日称觞处，定有重孙戏膝前。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21010, '鹧鸪天', '李景良', '清晓祥云绕碧天。\n老人星忽下南躔。\n庭兰共酌长生酒，持上华堂彩侍前。\n开绮席，舞朱颜。\n轻红莲叶荐金盘。\n沉香小院浑先暑，更有杯传数百年。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21011, '鹧鸪天', '张思济', '衣润红绡梅欲黄。\n几年欢意属华堂。\n红颜阿母逢占虺，班鬓儿童尽举觞。\n麟作脯，玉为浆。\n从今三万六千场。\n桑麻休说桑田变，自是经门日月长。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21012, '减字木兰花', '李夫人', '幕天席地。\n瑞脑香浓笙歌沸。\n白衣轻。\n发霜髯照座明。\n轻簪小珥。\n却是人间真富贵。\n好着丹青。\n画与人间作寿星。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21013, '蝶恋花', '李夫人', '急鼓疏钟声报晓，楼上今朝，卷起重帘早。\n环珊珊香袅袅。\n尘埃不到如蓬岛。\n何用珠玑相映照。\n韵胜形清，自有天然好。\n莫向尊前辞醉倒。\n松枝鹤骨偏宜老。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21014, '瑞鹧鸪', '李夫人', '新晴庭院暑风轻。\n瑞气朝来特地清。\n霞帔羽衣筠竹杖，萱堂真有寿星明。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21015, '望海潮', '张藻', '露零金井，尘清玉宇，双呈瑞新秋。\n佳气郁葱，祥烟缭绕，玉门初诞风流。\n宾客竞回眸。\n庆虎头食肉，燕颔封侯。\n骨相非凡，便宜谈笑上瀛洲。\n青衫莫欢淹留。\n有儿孙兰玉，不负箕裘。\n莲幕向来，花城今日，不妨小试良筹。\n名姓在金瓯。\n看佩珂鸣玉，促侍宸旒。\n直待功成名遂，归作赤松游。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21016, '虞美人', '胡文卿', '枢庭喜庆生辰到。\n仙伯离蓬岛。\n鲁台云物正呈祥。\n线绣工夫从此、日添长。\n满斟绿醑深深劝。\n岁岁长相见。\n蟠桃结子几番红。\n笑赏清歌声调、叶黄锺。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21017, '虞美人', '胡文卿', '香烟绕遍兰堂宴。\n香鸭珠帘卷。\n香风转後送韶音。\n香酝佳筵今日、庆佳辰。\n香山烧尽禽飞放。\n香袖佳人唱。\n香醪满满十分斟。\n香信传时延寿、保千春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21018, '虞美人', '胡文卿', '寿香烟篆金炉细。\n寿酒邀宾至。\n寿筵两畔列红妆。\n寿曲仙音一品、舞霓裳。\n寿星高挂生祥瑞。\n寿祝长生意。\n寿杯满劝庆遐龄。\n寿比南山松柏、永长春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21019, '虞美人', '胡文卿', '香云佳气交盘结。\n又庆生申节，满堂簪绂奉霞觞。\n瑞应台躔南极、见光芒。\n心田积累阴功足。\n来受人天福。\n从今几度见河清。\n笑傲壶中日月、镇长春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21020, '虞美人', '胡文卿', '昨霄南极星光现。\n今日开华宴。\n朱颜翠鬓占春多。\n且向博山香袅、卷金荷。\n龟游鹤舞千年寿。\n更酌千锺酒。\n满庭佳客捧殷勤。\n此日蒲菊新绿、瓮头春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21021, '阮郎归', '胡文卿', '良辰佳景列华筵。\n笙歌奏管弦。\n位居荣显子孙贤。\n功名事双全。\n庆祝寿，拜尊前。\n重重福禄坚。\n愿如彭祖寿齐年。\n金杯劝寿仙。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21022, '阮郎归', '胡文卿', '谢娘诗礼有家风。\n吹窗清昼同。\n笑言偕老与梁鸿。\n闺门喜气融。\n来月殿，下珠宫。\n人间春意浓。\n一尊仙酝祝芳丛。\n蟠桃千岁红。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21023, '阮郎归', '胡文卿', '薰风吹尽不多云。\n晓天如水清。\n哦松庭院忽闻笙。\n帘疏香篆明。\n兰玉盛，凤和鸣。\n家声留汉庭。\n狨鞍长傍九重城。\n年年双鬓青。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21024, '蝶恋花', '杨道居', '气禀五行天与秀。\n瑞见枢延，况是黄锺奏。\n日影量来添午昼。\n柳梅消息年时侯。\n红粉吹香帘幕透。\n深院笙歌，劝饮金锺酒。\n乐事赏心千岁有。\n黑头人做三公有。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21025, '苏幕遮', '史佐尧', '柳垂金，梅褪玉。\n昴宿呈祥，符应生公族。\n盖世功名夸九牧。\n黼衮褒扬，庆阀辉南北。\n赐宫醪，分笃。\n天与长生，谩把仙椿祝。\n好继平阳腾茂躅。\n富贵千秋，饮听瑶池曲。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21026, '满庭芳', '徐去非', '凤历书元，龟图画泰，瑞两两初开。\n舞风仙子，飞雪拥春来。\n平荡人间险秽，端为你没点尘埃。\n清明世，冰辉太洁，鸥鹭莫惊猜。\n儿孙，同劝寿，桃添西阆，兰绕南陔。\n看琼玉妆成，万瓦楼台。\n飘洒风流酥满盏，浑疑醉，月影蓬莱。\n从今去，诗高未老，点化尽多才。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21027, '锦被堆', '徐去非', '一种两容仪，红共白、交映南枝。\n紫霞仙指冰翁语，花如醉玉，香同臭雪，别样风姿。\n相守岁寒期。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21028, '卷珠帘・蝶恋花', '徐去非', '祥景飞光衮绣。\n流庆台，自是神仙胄。\n谁遣阳和放春透。\n化工重入丹青手。\n云筝锦瑟争为寿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21029, '点绛唇', '舒大成', '祝寿筵开，华堂深映花如绣。\n瑞烟喷兽。\n帘幕香风透。\n一点台星，化作人间秀。\n韶音奏。\n两行红袖。\n争劝长生酒。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21030, '临江仙', '贾少卿', '月寺星轺尘梦断，如今平地仙人。\n烟霞卷起旧精神。\n焚香金鸾，书奏玉麒麟。\n闻道枫宸求侍从，看庆命重新。\n且将风月剩身。\n樽中长有酒，花下不辜春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21031, '江城子', '陆汉广', '绿莺庭院燕莺啼。\n绣帘垂。\n瑞烟霏。\n一片笙箫，声过彩云低。\n疑是蕊宫仙子降，翻玉袖，舞瑶姬。\n冰姿玉质自清奇。\n看孙枝。\n列班衣。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21032, '临江仙', '王阜民', '家法从来师静治，赵张高掩前踪。\n清才八斗继宗风。\n年年正月尾，桃李满城中。\n已把长江成九酝，请将太白浮公。\n更移春槛向房栊。\n有花虽解语，莫负锦薰笼。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21033, '感皇恩', '霍安人', '十月小春天，梅飘香细。\n九叶尧已呈瑞。\n寿阳仙子，暂降羽衣环。\n林间风味，别人难比。\n齐眉共庆，劝声鼎沸。\n有子知书继家世。\n兼金五福，行被君恩宠贲。\n愿祈龟鹤算，千千岁。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21034, '醉蓬莱', '霍安人', '正朱明时侯，院宇清和，庆逢佳节。\n梦应熊罴，尧翻三叶，罗绮如云，寿杯争劝，竞起歌新阕。\n瑞气氤氲，祥云缭绕，玉炉频。\n溪室封功，几多勋业，首冠今朝，一时英杰。\n得配侯门，岂不惭疏拙。\n彩凤和鸣，早膺荣擢。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21035, '满庭芳', '霍安人', '桐叶霜乾，芦花风软，晓来一色新秋。\n碧光无际，良夜月明楼。\n瑞应长庚入梦，锺奇秀、特产贤侯。\n堪夸处，雄姿英发，连箭射双雕。\n回头。\n思往事，皂囊三进，豪气冲牛。\n记前回凤诏，空下南洲。\n冷笑浮云坠甑，鲈鱼美、归老扁舟。\n祝君寿，青山不尽，绿水自悠悠。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21036, '瑞鹤仙', '希叟', '燕堂秋未老。\n正木犀香散，芙蓉红小。\n门阑瑞烟绕。\n望银河月暗，寿星偏照。\n碧霞道要。\n有真人、亲传最妙。\n况桃源旧约，重寻鬓发，胜如年少。\n缥缈。\n六铢衣降，九转丹成，五云齐到。\n十洲三岛。\n神仙路，终须到。\n对芝兰玉树，宝杯交劝，何惜玉山醉倒。\n看乘鸾跨鹤，归来洞天未晓。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21037, '水调歌头', '沈元实', '金关五云里，玉座太微间。\n凌虚新就燕间，宣唤侍臣班。\n丹坐移前席，禁漏声传高阁，喜气满龙颜。\n天语眷畴昔，政路稳跻攀。\n酒如渑，香袅穗，寿南山。\n橙黄桔绿，樽前辉映菊花团。\n清晓凉风凝露，晴昼秋光满院，岁岁奉君。\n待看云台画，荣观侈人寰。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21038, '满江红', '游子蒙', '春玉苍山，屏星暖、佳辰难得。\n看柳眼梅金，全似海沂春色。\n和气欢声俄尔许，祥烟瑞霭今何夕。\n是风流、儒雅黑头公，悬弧日。\n福不尽，贵无敌。\n愿岁岁，见华席。\n捧霞觞称寿，寿如南极。\n见说蟠桃花正发，柔风暖日瑶池碧。\n待他年、结子欲成时，留君摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21039, '满江红', '游子蒙', '雪坞霜林，一夜报、春归消息。\n看是处、春回柳眼，粉匀梅额。\n和气已欣回北陆，寿星更喜明南极。\n问四井、节物奉谁欢，辽东客。\n熊梦旦，非常日。\n珠履闹，金钗密。\n指双溪千顷，共斟琼液。\n不用殷勤千岁祝，姓名已上神仙籍。\n但时从、王母借蟠桃，躬亲摘。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21040, '清平乐', '贾逋', '薰梅染柳。\n借得东君手。\n柳色梅香到樽前，摅写才华八斗。\n当年占梦佳辰。\n今年乐事尤新。\n日侍玉皇香案，钧天日月常春。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21041, '蝶恋花', '吴文若', '玉宇生凉秋恰半。\n月到今霄，分外清光满。\n兔魄呈祥冰烂。\n广寒仙子生华旦。\n聪慧风流天与擅，淑质冰婆，本是飞琼伴。\n□领彩衣椿祝劝。\n蟠桃待熟瑶池宴。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21042, '满庭芳', '去非', '龙角辉春，蛾春惊晓，梦阑金翠屏开。\n异芬薰室，风送蕊仙来。\n玉女擎香沐浴，人间世、洗彻凡埃。\n梅开後，留花酝染，清味俗难猜。\n东君，尤雅爱，传香芳畹，香发庭陔。\n宁馨满尊前，喜奏瑶台。\n便好纽为佩王，瀛洲路、同赏蓬莱。\n蟠桃宴，从今曼倩，三骋奇材。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21043, '南乡子', '潘熊飞', '十日後重阳。\n甘菊阶前满意黄。\n生日无钱留贺客，何妨。\n尚有儿曹理寿觞。\n双鬓已沧浪。\n休问金门与玉堂。\n二仲相期三径在，徜徉。\n何用功成似子房。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21044, '水调歌头', '黄庭佐', '露着桂枝晓，霜护菊篱秋。\n无尘玉宇南极，一点瑞光浮。\n崧岳精英瑞世，河洛图书寓直，琳馆奉宸游。\n独袖功名手，谁与复神州。\n带垂金，头尚黑，紫绮裘。\n年年今日，灵寿扶出富民侯。\n应为娉婷一笑，烂醉葡萄新熟，明月满西楼。\n西北雨峰峙，端与寿山侔。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21045, '失调名', '赵□', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21046, '失调名', '吴氏3', '');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21047, '南乡子', '吴氏3', '楼台里，春风淡荡。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21048, '南乡子', '吴氏3', '乍卷珠帘新燕入。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21049, '多丽', '吴氏3', '几声天外归鸿。');
INSERT INTO `visualization_ci` (`value`, `rhythmic`, `author`, `content`) VALUES (21050, '渔家傲', '吴氏3', '一声初报晓。');
